const QUESTION_BANK = [{"id": 1,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Femur is the longest bone in the body. Its length is approximately what percentage of body height?","options": [{"key": "A","text": "15%"},{"key": "B","text": "27%"},{"key": "C","text": "20%"},{"key": "D","text": "35%"}],"correct": "B","explanation": "Femur length ≈ 27% of total body height — useful in forensic estimation of stature."},{"id": 2,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The angle of inclination (neck-shaft angle) of femur in adults is:","options": [{"key": "A","text": "115–120°"},{"key": "B","text": "100–110°"},{"key": "C","text": "140–150°"},{"key": "D","text": "125–135°"}],"correct": "D","explanation": "Normal neck-shaft angle = 125–135°. >135° = coxa valga; <125° = coxa vara."},{"id": 3,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "Coxa vara is defined as neck-shaft angle:","options": [{"key": "A","text": "Greater than 150°"},{"key": "B","text": "Greater than 135°"},{"key": "C","text": "Less than 120°"},{"key": "D","text": "Equal to 125°"}],"correct": "C","explanation": "Coxa vara = neck-shaft angle <120° (some say <125°); coxa valga = >135°."},{"id": 4,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The angle of anteversion of femoral neck in adults is:","options": [{"key": "A","text": "15–20°"},{"key": "B","text": "10–15°"},{"key": "C","text": "20–25°"},{"key": "D","text": "5–10°"}],"correct": "A","explanation": "Normal femoral anteversion = 15–20° in adults; at birth ~40°, decreases with age."},{"id": 5,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Greater trochanter of femur lies at which vertebral level when standing?","options": [{"key": "A","text": "L4"},{"key": "B","text": "L5"},{"key": "C","text": "S1"},{"key": "D","text": "L3"}],"correct": "A","explanation": "Greater trochanter is at the level of L4 vertebra — useful landmark in clinical practice."},{"id": 6,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which structure is attached to the lesser trochanter of femur?","options": [{"key": "A","text": "Iliopsoas"},{"key": "B","text": "Gluteus maximus"},{"key": "C","text": "Obturator internus"},{"key": "D","text": "Piriformis"}],"correct": "A","explanation": "Iliopsoas (iliacus + psoas major) inserts into the lesser trochanter of femur."},{"id": 7,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Gluteus maximus is inserted into which structure of femur?","options": [{"key": "A","text": "Gluteal tuberosity and iliotibial tract"},{"key": "B","text": "Greater trochanter"},{"key": "C","text": "Linea aspera"},{"key": "D","text": "Lesser trochanter"}],"correct": "A","explanation": "Gluteus maximus inserts into gluteal tuberosity of femur and iliotibial tract (75% to IT band)."},{"id": 8,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Linea aspera is a feature found on which surface of femur?","options": [{"key": "A","text": "Posterior surface"},{"key": "B","text": "Medial surface"},{"key": "C","text": "Anterior surface"},{"key": "D","text": "Lateral surface"}],"correct": "A","explanation": "Linea aspera is a prominent ridge on the posterior surface of femoral shaft."},{"id": 9,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The nutrient foramen of femur is directed towards:","options": [{"key": "A","text": "Knee (distally)"},{"key": "B","text": "Hip (proximally)"},{"key": "C","text": "Laterally"},{"key": "D","text": "Medially"}],"correct": "A","explanation": "Nutrient foramen of femur directed distally (away from the growing end = knee)."},{"id": 10,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Adductor tubercle is located on which part of femur?","options": [{"key": "A","text": "Medial condyle"},{"key": "B","text": "Lateral condyle"},{"key": "C","text": "Greater trochanter"},{"key": "D","text": "Lesser trochanter"}],"correct": "A","explanation": "Adductor tubercle is on the medial condyle — insertion of adductor magnus (hamstring part)."},{"id": 11,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Which structure separates the two condyles of femur anteriorly?","options": [{"key": "A","text": "Intercondylar fossa"},{"key": "B","text": "Patellar surface (trochlear groove)"},{"key": "C","text": "Articular surface"},{"key": "D","text": "Popliteal surface"}],"correct": "B","explanation": "Patellar (trochlear) surface separates condyles anteriorly; intercondylar notch separates them posteriorly."},{"id": 12,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The quadriceps femoris muscle is attached to femur at:","options": [{"key": "A","text": "Gluteal tuberosity"},{"key": "B","text": "Linea aspera"},{"key": "C","text": "Intertrochanteric line (anterior)"},{"key": "D","text": "Both A and B"}],"correct": "C","explanation": "Vastus intermedius arises from anterior/lateral femoral shaft; rectus femoris from AIIS — but common attachment = intertrochanteric line area."},{"id": 13,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "In subcapital fracture of femur, blood supply most at risk is from:","options": [{"key": "A","text": "First perforating artery"},{"key": "B","text": "Obturator artery"},{"key": "C","text": "Medial circumflex femoral artery"},{"key": "D","text": "Lateral circumflex femoral artery"}],"correct": "C","explanation": "Medial circumflex femoral artery (retinacular vessels) is the main supply to femoral head — at risk in neck fractures."},{"id": 14,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Intertrochanteric line is located on which surface of femur?","options": [{"key": "A","text": "Posterior"},{"key": "B","text": "Lateral"},{"key": "C","text": "Anterior"},{"key": "D","text": "Medial"}],"correct": "C","explanation": "Intertrochanteric line is on the anterior surface; intertrochanteric crest is on the posterior surface."},{"id": 15,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Quadratus femoris is inserted into:","options": [{"key": "A","text": "Greater trochanter"},{"key": "B","text": "Lesser trochanter"},{"key": "C","text": "Intertrochanteric crest (quadrate tubercle)"},{"key": "D","text": "Linea aspera"}],"correct": "C","explanation": "Quadratus femoris inserts into quadrate tubercle on intertrochanteric crest (posterior femur)."},{"id": 16,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Which bursae communicates with the knee joint cavity most commonly?","options": [{"key": "A","text": "Pes anserinus bursa"},{"key": "B","text": "Prepatellar bursa"},{"key": "C","text": "Infrapatellar bursa"},{"key": "D","text": "Suprapatellar bursa"}],"correct": "D","explanation": "Suprapatellar bursa routinely communicates with knee joint cavity — part of synovial cavity."},{"id": 17,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Medial condyle of femur is larger than lateral condyle. Why?","options": [{"key": "A","text": "To compensate for the valgus angle (Q-angle) of femur"},{"key": "B","text": "To support more body weight"},{"key": "C","text": "To compensate for the angle of neck"},{"key": "D","text": "For knee flexion"}],"correct": "A","explanation": "Medial condyle is longer to compensate for the femoral valgus — both condyles reach same horizontal level."},{"id": 18,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The popliteal surface of femur is formed between which structures?","options": [{"key": "A","text": "Condyles and popliteal fossa"},{"key": "B","text": "Medial and lateral supracondylar lines"},{"key": "C","text": "Two lips of linea aspera above, condyles below"},{"key": "D","text": "Linea aspera and condyles"}],"correct": "B","explanation": "Popliteal surface = triangular area between medial & lateral supracondylar lines above condyles."},{"id": 19,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Piriformis is inserted into which part of femur?","options": [{"key": "A","text": "Intertrochanteric crest"},{"key": "B","text": "Lesser trochanter"},{"key": "C","text": "Gluteal tuberosity"},{"key": "D","text": "Greater trochanter (medial surface of upper border)"}],"correct": "D","explanation": "Piriformis inserts into the medial surface of the upper border of greater trochanter."},{"id": 20,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which type of bone is the femur?","options": [{"key": "A","text": "Short bone"},{"key": "B","text": "Irregular bone"},{"key": "C","text": "Flat bone"},{"key": "D","text": "Long bone"}],"correct": "D","explanation": "Femur is a long bone — it has a diaphysis (shaft) and two epiphyses."},{"id": 21,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Distal femoral epiphysis appears at birth. Proximal femoral epiphysis (head) appears at:","options": [{"key": "A","text": "Birth"},{"key": "B","text": "1 year"},{"key": "C","text": "3 years"},{"key": "D","text": "6 months"}],"correct": "B","explanation": "Distal femoral epiphysis = present at birth; Femoral head epiphysis appears at ~1 year of age."},{"id": 22,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Neck of femur fracture in elderly is most common at which type?","options": [{"key": "A","text": "Subcapital"},{"key": "B","text": "Transcervical"},{"key": "C","text": "Basal"},{"key": "D","text": "Pertrochanteric"}],"correct": "A","explanation": "Subcapital fracture is most common neck of femur fracture in elderly — avascular necrosis risk highest."},{"id": 23,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Bryant's triangle is used to assess fractures/dislocation involving:","options": [{"key": "A","text": "Femoral neck"},{"key": "B","text": "Patella"},{"key": "C","text": "Tibia"},{"key": "D","text": "Ankle"}],"correct": "A","explanation": "Bryant's triangle detects shortening of femoral neck — used in hip fractures and dislocations."},{"id": 24,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which nerve is in close relation to the posterior aspect of hip joint, at risk in posterior dislocation?","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Sciatic nerve"},{"key": "C","text": "Lateral cutaneous nerve of thigh"},{"key": "D","text": "Obturator nerve"}],"correct": "B","explanation": "Sciatic nerve passes posterior to hip — at risk in posterior dislocation of hip."},{"id": 25,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The Q-angle (quadriceps angle) is formed between:","options": [{"key": "A","text": "IT band and patella"},{"key": "B","text": "Femoral neck and shaft"},{"key": "C","text": "Line from ASIS to patella and patella to tibial tuberosity"},{"key": "D","text": "Femur shaft and tibia"}],"correct": "C","explanation": "Q-angle = angle between line ASIS→patella and patella→tibial tuberosity. Normal ♂ ~10–15°, ♀ ~15–20°."},{"id": 26,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Tibia is the weight-bearing bone of the leg. It transmits weight to the foot through:","options": [{"key": "A","text": "Talus via ankle mortise"},{"key": "B","text": "Fibula"},{"key": "C","text": "Navicular bone"},{"key": "D","text": "Calcaneus directly"}],"correct": "A","explanation": "Tibia transmits body weight to the talus through the ankle (talocrural) joint."},{"id": 27,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The tibial tuberosity is the site of attachment of:","options": [{"key": "A","text": "Gastrocnemius"},{"key": "B","text": "Sartorius"},{"key": "C","text": "Patellar tendon (ligamentum patellae)"},{"key": "D","text": "Hamstrings"}],"correct": "C","explanation": "Patellar tendon (ligamentum patellae) inserts into tibial tuberosity — Osgood-Schlatter disease affects this site."},{"id": 28,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Pes anserinus is the combined insertion of which three muscles on tibia?","options": [{"key": "A","text": "Sartorius, gracilis, semitendinosus"},{"key": "B","text": "Gracilis, semitendinosus, semimembranosus"},{"key": "C","text": "Rectus femoris, sartorius, gracilis"},{"key": "D","text": "Sartorius, biceps femoris, gracilis"}],"correct": "A","explanation": "Pes anserinus (goose's foot) = Sartorius + Gracilis + Semitendinosus on medial tibia."},{"id": 29,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Intercondylar eminence of tibia lies between:","options": [{"key": "A","text": "Medial and lateral tibial condyles (intercondylar area)"},{"key": "B","text": "Tibial condyles and fibula head"},{"key": "C","text": "Tibial tuberosity and shaft"},{"key": "D","text": "Medial and lateral condyles posteriorly"}],"correct": "A","explanation": "Intercondylar eminence (tibial spine) projects between medial and lateral articular facets of tibia."},{"id": 30,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which ligament attaches to the anterior intercondylar area of tibia?","options": [{"key": "A","text": "Posterior cruciate ligament"},{"key": "B","text": "Medial collateral ligament"},{"key": "C","text": "Lateral collateral ligament"},{"key": "D","text": "Anterior cruciate ligament"}],"correct": "D","explanation": "ACL attaches to anterior intercondylar area of tibia; PCL to posterior intercondylar area."},{"id": 31,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The soleal line is a feature on which surface of tibia?","options": [{"key": "A","text": "Posterior surface"},{"key": "B","text": "Anterior surface"},{"key": "C","text": "Medial surface"},{"key": "D","text": "Lateral surface"}],"correct": "A","explanation": "Soleal line runs obliquely on the posterior surface of tibia — origin of soleus muscle."},{"id": 32,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The nutrient foramen of tibia is directed:","options": [{"key": "A","text": "Distally (towards ankle)"},{"key": "B","text": "Laterally"},{"key": "C","text": "Medially"},{"key": "D","text": "Proximally (towards knee)"}],"correct": "A","explanation": "Nutrient foramen of tibia is directed distally — away from the growing end (upper end)."},{"id": 33,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Osgood-Schlatter disease is osteochondrosis of:","options": [{"key": "A","text": "Navicular bone"},{"key": "B","text": "Medial tibial condyle"},{"key": "C","text": "Femoral head"},{"key": "D","text": "Tibial tuberosity"}],"correct": "D","explanation": "Osgood-Schlatter disease = traction apophysitis of tibial tuberosity in adolescents."},{"id": 34,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The medial malleolus is a part of:","options": [{"key": "A","text": "Fibula"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Talus"},{"key": "D","text": "Tibia"}],"correct": "D","explanation": "Medial malleolus is the downward projection of the medial aspect of distal tibia."},{"id": 35,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which structure is posterior to medial malleolus (from anterior to posterior order)?","options": [{"key": "A","text": "Tibialis posterior, FDL, FHL"},{"key": "B","text": "FHL, FDL, tibialis posterior"},{"key": "C","text": "Tibialis anterior, EHL, EHB"},{"key": "D","text": "FDL, tibialis posterior, FHL"}],"correct": "A","explanation": "Tom, Dick And Very Nervous Harry: Tibialis posterior, FDL, posterior tibial Artery, Vein, Nerve, FHL."},{"id": 36,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tibial plateau fracture most commonly involves which side?","options": [{"key": "A","text": "Both equally"},{"key": "B","text": "Posterior plateau"},{"key": "C","text": "Medial plateau"},{"key": "D","text": "Lateral plateau"}],"correct": "D","explanation": "Lateral tibial plateau fracture is more common (Schatzker classification) due to valgus force in trauma."},{"id": 37,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The interosseous membrane between tibia and fibula is attached to which border of tibia?","options": [{"key": "A","text": "Medial border"},{"key": "B","text": "Posterior border"},{"key": "C","text": "Anterior border"},{"key": "D","text": "Interosseous (lateral) border"}],"correct": "D","explanation": "Interosseous membrane attaches to the interosseous (lateral) border of tibia and medial border of fibula."},{"id": 38,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Which muscle arises from the lateral condyle of tibia?","options": [{"key": "A","text": "Tibialis anterior"},{"key": "B","text": "Popliteus"},{"key": "C","text": "Extensor digitorum longus"},{"key": "D","text": "Peroneus longus"}],"correct": "C","explanation": "Extensor digitorum longus arises partly from lateral tibial condyle and interosseous membrane."},{"id": 39,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Popliteus muscle is attached to tibia at:","options": [{"key": "A","text": "Posterior surface above soleal line"},{"key": "B","text": "Lateral condyle"},{"key": "C","text": "Tibial tuberosity"},{"key": "D","text": "Medial condyle"}],"correct": "A","explanation": "Popliteus inserts into triangular area on posterior tibia above soleal line."},{"id": 40,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The upper end of tibia ossifies:","options": [{"key": "A","text": "At birth only"},{"key": "B","text": "At 1 year"},{"key": "C","text": "At 3 years"},{"key": "D","text": "At birth and joins shaft at 20 years"}],"correct": "D","explanation": "Upper tibial epiphysis present at birth; fuses with shaft around 20 years."},{"id": 41,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The tibial shaft is most narrow at:","options": [{"key": "A","text": "Lower third"},{"key": "B","text": "Junction of middle and lower third"},{"key": "C","text": "Upper third"},{"key": "D","text": "Junction of upper and middle third"}],"correct": "B","explanation": "Tibia is narrowest at the junction of middle and lower third — most common site of stress fractures."},{"id": 42,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Shin bone refers to which surface of tibia?","options": [{"key": "A","text": "Lateral"},{"key": "B","text": "Medial"},{"key": "C","text": "Anterior (subcutaneous)"},{"key": "D","text": "Posterior"}],"correct": "C","explanation": "Anterior surface/border of tibia is subcutaneous (shin) — no muscle covers it, prone to direct injury."},{"id": 43,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Semimembranosus inserts into which part of tibia?","options": [{"key": "A","text": "Tibial tuberosity"},{"key": "B","text": "Pes anserinus"},{"key": "C","text": "Gerdy's tubercle"},{"key": "D","text": "Posterior aspect of medial tibial condyle"}],"correct": "D","explanation": "Semimembranosus inserts into the posterior aspect of medial tibial condyle."},{"id": 44,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Gerdy's tubercle on tibia is the insertion of:","options": [{"key": "A","text": "Iliotibial band"},{"key": "B","text": "Biceps femoris"},{"key": "C","text": "Patellar tendon"},{"key": "D","text": "Sartorius"}],"correct": "A","explanation": "Iliotibial band inserts into Gerdy's tubercle on the anterolateral aspect of lateral tibial condyle."},{"id": 45,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In tibial shaft fracture, the compartment most commonly affected by compartment syndrome is:","options": [{"key": "A","text": "Lateral"},{"key": "B","text": "Posterior deep"},{"key": "C","text": "Posterior superficial"},{"key": "D","text": "Anterior"}],"correct": "D","explanation": "Anterior compartment syndrome is most common after tibial fracture — tight fascial boundary."},{"id": 46,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The distal tibial growth plate (physis) fuses at approximately:","options": [{"key": "A","text": "16–18 years"},{"key": "B","text": "18–20 years"},{"key": "C","text": "14–16 years"},{"key": "D","text": "12–14 years"}],"correct": "A","explanation": "Distal tibial physis fuses at ~16–18 years; proximal physis fuses later (~20 years)."},{"id": 47,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Tillaux fracture is a Salter-Harris type III fracture of which bone?","options": [{"key": "A","text": "Calcaneus"},{"key": "B","text": "Fibula"},{"key": "C","text": "Femur"},{"key": "D","text": "Tibia (distal)"}],"correct": "D","explanation": "Tillaux fracture = Salter-Harris III of anterolateral distal tibia, seen in adolescents during physeal closure."},{"id": 48,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which surface of tibia faces the fibula?","options": [{"key": "A","text": "Posterior surface"},{"key": "B","text": "Anterior surface"},{"key": "C","text": "Medial surface"},{"key": "D","text": "Lateral surface"}],"correct": "D","explanation": "Lateral surface of tibia faces the fibula; interosseous membrane connects their interosseous borders."},{"id": 49,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The articular surface for fibula on tibia is located at:","options": [{"key": "A","text": "Medial condyle"},{"key": "B","text": "Intercondylar eminence"},{"key": "C","text": "Both proximal (lateral condyle) and distal fibular notch"},{"key": "D","text": "Lateral condyle only (proximal)"}],"correct": "C","explanation": "Tibia articulates with fibula at superior tibiofibular joint (lateral condyle) and inferior (fibular notch)."},{"id": 50,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Dreaded black line in tibial stress fracture indicates:","options": [{"key": "A","text": "Healing fracture"},{"key": "B","text": "Periosteal reaction"},{"key": "C","text": "High-risk fracture of anterior tibial cortex"},{"key": "D","text": "Completed fracture"}],"correct": "C","explanation": "Dreaded black line = transverse lucency on anterior tibial cortex — high nonunion risk, requires surgery."},{"id": 51,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Fibula is primarily a:","options": [{"key": "A","text": "Weight-bearing bone"},{"key": "B","text": "Sesamoid bone"},{"key": "C","text": "Non-weight-bearing bone providing muscle attachment and ankle stability"},{"key": "D","text": "Main bone of leg"}],"correct": "C","explanation": "Fibula bears only ~6% of body weight; mainly provides muscle attachment and lateral ankle stability."},{"id": 52,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Head of fibula articulates with:","options": [{"key": "A","text": "Lateral condyle of tibia"},{"key": "B","text": "Talus"},{"key": "C","text": "Femoral condyle"},{"key": "D","text": "Medial condyle of tibia"}],"correct": "A","explanation": "Fibular head articulates with the lateral condyle of tibia at the superior tibiofibular joint."},{"id": 53,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The lateral malleolus (fibula) extends how much lower than medial malleolus?","options": [{"key": "A","text": "3 cm lower"},{"key": "B","text": "1–2 cm lower"},{"key": "C","text": "Same level"},{"key": "D","text": "1 cm lower"}],"correct": "B","explanation": "Lateral malleolus extends ~1–2 cm more distally than medial malleolus, preventing lateral talar shift."},{"id": 54,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Common peroneal nerve winds around which part of fibula?","options": [{"key": "A","text": "Head of fibula"},{"key": "B","text": "Neck of fibula"},{"key": "C","text": "Lateral surface of shaft"},{"key": "D","text": "Lateral malleolus"}],"correct": "B","explanation": "Common peroneal nerve winds around the neck of fibula — vulnerable to injury here."},{"id": 55,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Fracture of neck of fibula most commonly injures which nerve?","options": [{"key": "A","text": "Common peroneal nerve"},{"key": "B","text": "Sural nerve"},{"key": "C","text": "Tibial nerve"},{"key": "D","text": "Superficial peroneal nerve"}],"correct": "A","explanation": "CPN winds around fibular neck → foot drop on fracture at this level."},{"id": 56,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Fibula is used as a bone graft donor site most commonly for:","options": [{"key": "A","text": "Wrist fusion"},{"key": "B","text": "Hip replacement"},{"key": "C","text": "Mandible reconstruction"},{"key": "D","text": "Spinal fusion"}],"correct": "C","explanation": "Free vascularized fibula graft is gold standard for mandibular reconstruction after oncologic resection."},{"id": 57,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The inferior tibiofibular joint is which type of joint?","options": [{"key": "A","text": "Fibrous (syndesmosis)"},{"key": "B","text": "Gomphosis"},{"key": "C","text": "Synovial"},{"key": "D","text": "Cartilaginous"}],"correct": "A","explanation": "Inferior tibiofibular joint = fibrous syndesmosis — held by anterior & posterior tibiofibular ligaments."},{"id": 58,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Peroneus longus and brevis arise from the lateral surface of:","options": [{"key": "A","text": "Tibia"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Fibula"},{"key": "D","text": "Both tibia and fibula"}],"correct": "C","explanation": "Peroneus (fibularis) longus and brevis arise from the lateral surface of the fibula."},{"id": 59,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Peroneus (fibularis) tertius arises from the:","options": [{"key": "A","text": "Anterior fibula (lower third)"},{"key": "B","text": "Medial fibula"},{"key": "C","text": "Lateral fibula (lower third)"},{"key": "D","text": "Tibia"}],"correct": "A","explanation": "Peroneus tertius arises from the anterior surface of lower fibula — dorsiflexes and everts foot."},{"id": 60,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "A Pott's fracture involves:","options": [{"key": "A","text": "Talus"},{"key": "B","text": "Fifth metatarsal"},{"key": "C","text": "Fibula alone or with medial malleolus/deltoid ligament"},{"key": "D","text": "Tibia only"}],"correct": "C","explanation": "Pott's fracture = bimalleolar fracture (fibula + medial malleolus or deltoid tear) from eversion injury."},{"id": 61,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Maisonneuve fracture is a proximal fibular fracture associated with:","options": [{"key": "A","text": "Distal tibia fracture + syndesmotic disruption"},{"key": "B","text": "Talar fracture"},{"key": "C","text": "Tibial shaft fracture"},{"key": "D","text": "Calcaneal fracture"}],"correct": "A","explanation": "Maisonneuve = proximal fibula fracture with disruption of syndesmosis and medial ankle structures."},{"id": 62,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Which muscle arises from the posterior surface of fibula?","options": [{"key": "A","text": "Extensor hallucis longus"},{"key": "B","text": "Peroneus longus"},{"key": "C","text": "Tibialis anterior"},{"key": "D","text": "Flexor hallucis longus"}],"correct": "D","explanation": "FHL arises from posterior surface of fibula (lower 2/3) — important in hallux stabilisation."},{"id": 63,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Extensor hallucis longus arises from which surface of fibula?","options": [{"key": "A","text": "Medial surface"},{"key": "B","text": "Medial (anterior interosseous) surface"},{"key": "C","text": "Posterior surface"},{"key": "D","text": "Lateral surface"}],"correct": "B","explanation": "EHL arises from the anterior (medial) surface of fibula and interosseous membrane."},{"id": 64,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The nutrient foramen of fibula is directed:","options": [{"key": "A","text": "Medially"},{"key": "B","text": "Proximally"},{"key": "C","text": "Laterally"},{"key": "D","text": "Distally"}],"correct": "D","explanation": "Nutrient foramen of fibula faces distally — same direction as tibia (both away from growing proximal end)."},{"id": 65,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Anterior talofibular ligament (ATFL) is the most commonly injured ligament in ankle sprain. It attaches to:","options": [{"key": "A","text": "Tibia and fibula"},{"key": "B","text": "Fibula and calcaneus"},{"key": "C","text": "Medial malleolus and talus"},{"key": "D","text": "Lateral malleolus and talar neck"}],"correct": "D","explanation": "ATFL runs from lateral malleolus to talar neck — ruptures in inversion sprain."},{"id": 66,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "How many tarsal bones are present in the foot?","options": [{"key": "A","text": "7"},{"key": "B","text": "5"},{"key": "C","text": "6"},{"key": "D","text": "8"}],"correct": "A","explanation": "7 tarsal bones: Calcaneus, Talus, Navicular, Cuboid, and 3 Cuneiforms (medial, intermediate, lateral)."},{"id": 67,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The largest tarsal bone is:","options": [{"key": "A","text": "Talus"},{"key": "B","text": "Navicular"},{"key": "C","text": "Cuboid"},{"key": "D","text": "Calcaneus"}],"correct": "D","explanation": "Calcaneus is the largest tarsal bone — forms the heel and transmits body weight to the ground."},{"id": 68,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Talus is unique among tarsal bones because:","options": [{"key": "A","text": "It is sesamoid"},{"key": "B","text": "It is not weight-bearing"},{"key": "C","text": "It has no muscle attachments"},{"key": "D","text": "It has no ligament attachments"}],"correct": "C","explanation": "Talus has NO muscular attachments — only ligaments and articular surfaces cover most of its surface."},{"id": 69,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The body of talus articulates with tibia above and fibula laterally. Which surface of talus articulates with calcaneus?","options": [{"key": "A","text": "Medial surface"},{"key": "B","text": "Anterior surface"},{"key": "C","text": "Inferior surface (3 facets)"},{"key": "D","text": "Posterior surface"}],"correct": "C","explanation": "Inferior talus has 3 articular facets (anterior, middle, posterior) for subtalar joint with calcaneus."},{"id": 70,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Subtalar (talocalcaneal) joint is responsible for which movement?","options": [{"key": "A","text": "Toe flexion"},{"key": "B","text": "Inversion and eversion of foot"},{"key": "C","text": "Dorsiflexion and plantarflexion"},{"key": "D","text": "Knee flexion"}],"correct": "B","explanation": "Subtalar joint produces inversion and eversion (pronation/supination) of the foot."},{"id": 71,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Calcaneus articulates with which bones?","options": [{"key": "A","text": "Cuboid only"},{"key": "B","text": "Navicular and talus"},{"key": "C","text": "Talus only"},{"key": "D","text": "Talus and cuboid"}],"correct": "D","explanation": "Calcaneus articulates superiorly with talus (subtalar joint) and anteriorly with cuboid."},{"id": 72,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Calcaneal tuberosity (posterior) is the insertion of:","options": [{"key": "A","text": "Tibialis posterior"},{"key": "B","text": "Flexor hallucis longus"},{"key": "C","text": "Peroneus longus"},{"key": "D","text": "Achilles tendon (tendo calcaneus)"}],"correct": "D","explanation": "Achilles tendon (gastrocnemius + soleus) inserts into the posterior calcaneal tuberosity."},{"id": 73,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Sustentaculum tali is a medial shelf of calcaneus that supports:","options": [{"key": "A","text": "Cuboid"},{"key": "B","text": "Cuneiform"},{"key": "C","text": "Navicular"},{"key": "D","text": "Head of talus"}],"correct": "D","explanation": "Sustentaculum tali supports the head and neck of talus medially."},{"id": 74,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which tendon passes in the groove beneath sustentaculum tali?","options": [{"key": "A","text": "Flexor hallucis longus"},{"key": "B","text": "Flexor digitorum longus"},{"key": "C","text": "Tibialis posterior"},{"key": "D","text": "Peroneus longus"}],"correct": "A","explanation": "FHL runs in a groove under sustentaculum tali — hence sustentaculum tali is NOT avulsed in calcaneal fractures."},{"id": 75,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Bohler's angle (tuber-joint angle) is used to assess fractures of:","options": [{"key": "A","text": "Fibula"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Navicular"},{"key": "D","text": "Talus"}],"correct": "B","explanation": "Bohler's angle (normal 20–40°) is reduced in calcaneal fractures — indicates depression."},{"id": 76,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Most common tarsal bone to fracture is:","options": [{"key": "A","text": "Talus"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Cuboid"},{"key": "D","text": "Navicular"}],"correct": "B","explanation": "Calcaneus is the most commonly fractured tarsal bone — usually from axial loading (fall from height)."},{"id": 77,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Avascular necrosis is most common after fracture of which tarsal bone?","options": [{"key": "A","text": "Talus"},{"key": "B","text": "Navicular"},{"key": "C","text": "Calcaneus"},{"key": "D","text": "Cuboid"}],"correct": "A","explanation": "Talus has precarious blood supply — AVN occurs in ~10–40% of talar neck fractures (Hawkins classification)."},{"id": 78,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Navicular bone is on the medial side of foot. It articulates with:","options": [{"key": "A","text": "Cuboid and 3 cuneiforms"},{"key": "B","text": "Calcaneus posteriorly, cuboid laterally"},{"key": "C","text": "Talus and cuboid"},{"key": "D","text": "Talus posteriorly, 3 cuneiforms anteriorly"}],"correct": "D","explanation": "Navicular articulates with talus (posteriorly) and 3 cuneiforms (anteriorly), and sometimes cuboid."},{"id": 79,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Kohler's disease is osteochondrosis of:","options": [{"key": "A","text": "Navicular"},{"key": "B","text": "Talus"},{"key": "C","text": "Calcaneus"},{"key": "D","text": "Cuboid"}],"correct": "A","explanation": "Kohler's disease = avascular necrosis of navicular bone in children aged 3–7 years."},{"id": 80,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tibialis posterior inserts into which bone primarily?","options": [{"key": "A","text": "Medial cuneiform"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Navicular tuberosity"},{"key": "D","text": "Cuboid"}],"correct": "C","explanation": "Tibialis posterior inserts primarily into navicular tuberosity + all tarsal bones except talus."},{"id": 81,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Peroneus longus tendon passes under the foot in a groove on:","options": [{"key": "A","text": "Calcaneus"},{"key": "B","text": "Navicular"},{"key": "C","text": "Medial cuneiform"},{"key": "D","text": "Cuboid"}],"correct": "D","explanation": "Peroneus longus tendon turns under the foot in a groove on the cuboid — inserts into medial cuneiform + 1st MT base."},{"id": 82,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Lisfranc joint is the articulation between:","options": [{"key": "A","text": "Tarsals and metatarsals (tarsometatarsal joint)"},{"key": "B","text": "Metatarsals and phalanges"},{"key": "C","text": "Tibia and talus"},{"key": "D","text": "Talus and calcaneus"}],"correct": "A","explanation": "Lisfranc joint = tarsometatarsal joint; Lisfranc ligament connects medial cuneiform to 2nd MT base."},{"id": 83,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Chopart's joint (midtarsal joint) is between:","options": [{"key": "A","text": "Tibia and talus"},{"key": "B","text": "Calcaneus and navicular"},{"key": "C","text": "Talus + calcaneus / navicular + cuboid"},{"key": "D","text": "Tarsals and metatarsals"}],"correct": "C","explanation": "Chopart's joint = calcaneocuboid + talonavicular joints — transverse tarsal joint."},{"id": 84,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Cuboid bone articulates with all EXCEPT:","options": [{"key": "A","text": "Navicular"},{"key": "B","text": "Lateral cuneiform"},{"key": "C","text": "Calcaneus"},{"key": "D","text": "4th and 5th metatarsals"}],"correct": "A","explanation": "Cuboid does NOT consistently articulate with navicular. It articulates with calcaneus, 4th/5th MT, and lateral cuneiform."},{"id": 85,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The medial longitudinal arch of foot passes through which bones?","options": [{"key": "A","text": "Calcaneus, cuboid, 4th/5th MT"},{"key": "B","text": "Calcaneus, talus, navicular, cuneiforms, 1st–3rd MT"},{"key": "C","text": "Calcaneus, talus, cuboid, MT"},{"key": "D","text": "Tibia, talus, navicular, MT"}],"correct": "B","explanation": "Medial longitudinal arch: Calcaneus → Talus → Navicular → 3 Cuneiforms → 1st–3rd Metatarsals."},{"id": 86,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Lateral longitudinal arch of foot is formed by:","options": [{"key": "A","text": "Talus, cuboid, 5th MT"},{"key": "B","text": "Calcaneus, cuneiforms, 1st–3rd MT"},{"key": "C","text": "Calcaneus, talus, navicular, 1st MT"},{"key": "D","text": "Calcaneus, cuboid, 4th & 5th metatarsals"}],"correct": "D","explanation": "Lateral longitudinal arch: Calcaneus → Cuboid → 4th & 5th metatarsals (lower, less mobile arch)."},{"id": 87,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Pes planus (flat foot) is loss of which arch?","options": [{"key": "A","text": "Transverse arch"},{"key": "B","text": "Lateral longitudinal arch"},{"key": "C","text": "All arches equally"},{"key": "D","text": "Medial longitudinal arch"}],"correct": "D","explanation": "Pes planus = collapse of medial longitudinal arch — tibialis posterior insufficiency is common cause."},{"id": 88,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Pes cavus (high arch) is associated with which neurological condition?","options": [{"key": "A","text": "Duchenne muscular dystrophy"},{"key": "B","text": "Polio"},{"key": "C","text": "Cerebral palsy (diplegia)"},{"key": "D","text": "Charcot-Marie-Tooth disease"}],"correct": "D","explanation": "Pes cavus = high arch; strongly associated with Charcot-Marie-Tooth (hereditary motor sensory neuropathy)."},{"id": 89,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In a 'March fracture' (stress fracture), which bone is most commonly involved?","options": [{"key": "A","text": "2nd metatarsal neck"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Tibia"},{"key": "D","text": "Fibula"}],"correct": "A","explanation": "March fracture = stress fracture of 2nd (most common) or 3rd metatarsal neck from repetitive loading."},{"id": 90,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Sever's disease is apophysitis of:","options": [{"key": "A","text": "Tibial tuberosity"},{"key": "B","text": "Femoral head"},{"key": "C","text": "Calcaneal apophysis"},{"key": "D","text": "Navicular"}],"correct": "C","explanation": "Sever's disease = calcaneal apophysitis in adolescents — traction by Achilles tendon on calcaneal growth plate."},{"id": 91,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which bone gives attachment to the deltoid ligament?","options": [{"key": "A","text": "Calcaneus"},{"key": "B","text": "Lateral malleolus (fibula)"},{"key": "C","text": "Medial malleolus (tibia)"},{"key": "D","text": "Navicular"}],"correct": "C","explanation": "Deltoid ligament (medial collateral) attaches to medial malleolus (tibia) — very strong, resists eversion."},{"id": 92,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The keystone of the medial longitudinal arch is:","options": [{"key": "A","text": "Talus"},{"key": "B","text": "Navicular"},{"key": "C","text": "Medial cuneiform"},{"key": "D","text": "Calcaneus"}],"correct": "A","explanation": "Talus is the keystone of the medial longitudinal arch — it receives body weight and distributes it."},{"id": 93,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Thomas test assesses:","options": [{"key": "A","text": "Hip abduction contracture"},{"key": "B","text": "Knee extension lag"},{"key": "C","text": "Hip flexion contracture (iliopsoas tightness)"},{"key": "D","text": "Ankle dorsiflexion"}],"correct": "C","explanation": "Thomas test detects fixed hip flexion deformity — normal hip extends to 0° when opposite hip fully flexed."},{"id": 94,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "In calcaneal fracture from fall from height, which spinal level is also at risk?","options": [{"key": "A","text": "Lumbar spine (L1)"},{"key": "B","text": "Cervical spine"},{"key": "C","text": "Thoracic spine"},{"key": "D","text": "Sacrum"}],"correct": "A","explanation": "Axial load fracture of calcaneus → 10% risk of L1 compression fracture (Don Juan fracture pattern)."},{"id": 95,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "The talar neck fracture classification is known as:","options": [{"key": "A","text": "Schatzker classification"},{"key": "B","text": "Neer classification"},{"key": "C","text": "Hawkins classification"},{"key": "D","text": "Garden classification"}],"correct": "C","explanation": "Hawkins classification (Type I–IV) describes talar neck fractures and risk of AVN."},{"id": 96,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which fracture is described as 'lover's fracture' or 'Don Juan fracture'?","options": [{"key": "A","text": "Distal femur fracture"},{"key": "B","text": "Tibial plateau fracture"},{"key": "C","text": "Bilateral calcaneal fracture"},{"key": "D","text": "Talar fracture"}],"correct": "C","explanation": "Bilateral calcaneal fractures from jumping/falling = lover's fracture or Don Juan fracture."},{"id": 97,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The normal tibiofibular angle (mechanical axis of lower limb) in adults is approximately:","options": [{"key": "A","text": "5–7° valgus"},{"key": "B","text": "5° varus"},{"key": "C","text": "10–15° valgus"},{"key": "D","text": "0° (straight)"}],"correct": "A","explanation": "Normal mechanical axis of lower limb has ~5–7° valgus at knee — slight physiological valgus."},{"id": 98,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which test assesses medial longitudinal arch clinically?","options": [{"key": "A","text": "Lachman test"},{"key": "B","text": "Trendelenburg test"},{"key": "C","text": "Jack's test (hallux dorsiflexion test)"},{"key": "D","text": "Thomas test"}],"correct": "C","explanation": "Jack's test: passive dorsiflexion of hallux → plantar fascia tightens → MLA rises (windlass mechanism)."},{"id": 99,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Genu varum (bow legs) in adults is associated with which condition?","options": [{"key": "A","text": "Tibial plateau fracture"},{"key": "B","text": "Cerebral palsy"},{"key": "C","text": "Rickets in childhood / OA medial compartment"},{"key": "D","text": "Femoral neck fracture"}],"correct": "C","explanation": "Genu varum = medial knee OA in adults or rickets in childhood — medial compartment overloaded."},{"id": 100,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The epiphysis of the distal femur is used in forensic medicine to estimate:","options": [{"key": "A","text": "Height of individual"},{"key": "B","text": "Sex of individual"},{"key": "C","text": "Age at puberty"},{"key": "D","text": "Age at birth (present at birth → maturity)"}],"correct": "D","explanation": "Distal femoral epiphysis is present at birth and used as a sign of fetal maturity (≥36 weeks gestation)."},{"id": 101,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Hip joint is which type of synovial joint?","options": [{"key": "A","text": "Hinge joint"},{"key": "B","text": "Condyloid joint"},{"key": "C","text": "Pivot joint"},{"key": "D","text": "Ball and socket joint"}],"correct": "D","explanation": "Hip joint = ball and socket (multiaxial) synovial joint — femoral head in acetabulum."},{"id": 102,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The acetabulum is formed by the fusion of which three bones?","options": [{"key": "A","text": "Ilium, sacrum, pubis"},{"key": "B","text": "Ilium, ischium, pubis"},{"key": "C","text": "Ilium, ischium, coccyx"},{"key": "D","text": "Femur, ilium, ischium"}],"correct": "B","explanation": "Acetabulum formed by ilium (2/5), ischium (2/5), pubis (1/5) — fuse at triradiate cartilage."},{"id": 103,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The acetabular labrum is deficient inferiorly at:","options": [{"key": "A","text": "Anterior rim"},{"key": "B","text": "Acetabular notch"},{"key": "C","text": "Posterior rim"},{"key": "D","text": "Superior rim"}],"correct": "B","explanation": "Acetabular labrum is C-shaped — deficient inferiorly at acetabular notch (bridged by transverse acetabular ligament)."},{"id": 104,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Transverse acetabular ligament converts the acetabular notch into a foramen through which passes:","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Sciatic nerve"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Acetabular branch of obturator artery"}],"correct": "D","explanation": "Acetabular branch of obturator artery passes through acetabular notch to supply femoral head via ligamentum teres."},{"id": 105,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Ligamentum teres (round ligament of femur head) attaches to:","options": [{"key": "A","text": "Lesser trochanter"},{"key": "B","text": "Greater trochanter"},{"key": "C","text": "Fovea capitis of femoral head"},{"key": "D","text": "Femoral neck"}],"correct": "C","explanation": "Ligamentum teres attaches to fovea capitis on femoral head and carries a small artery (in children)."},{"id": 106,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which ligament is the strongest ligament of the hip joint?","options": [{"key": "A","text": "Ligamentum teres"},{"key": "B","text": "Pubofemoral ligament"},{"key": "C","text": "Ischiofemoral ligament"},{"key": "D","text": "Iliofemoral ligament (Y-ligament of Bigelow)"}],"correct": "D","explanation": "Iliofemoral ligament (Y-ligament of Bigelow) is the strongest ligament in the body — prevents hyperextension."},{"id": 107,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The Y-ligament of Bigelow (iliofemoral ligament) is attached to which bony landmark?","options": [{"key": "A","text": "ASIS to intertrochanteric crest"},{"key": "B","text": "ASIS to lesser trochanter"},{"key": "C","text": "AIIS to intertrochanteric line"},{"key": "D","text": "Ischial spine to greater trochanter"}],"correct": "C","explanation": "Iliofemoral ligament: AIIS (apex) → two bands to intertrochanteric line (Y-shape)."},{"id": 108,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Ischiofemoral ligament prevents which movement at hip?","options": [{"key": "A","text": "Flexion"},{"key": "B","text": "Abduction"},{"key": "C","text": "Extension"},{"key": "D","text": "Medial rotation and adduction (especially in extension)"}],"correct": "D","explanation": "Ischiofemoral ligament (posterior capsule) prevents medial rotation and adduction — tightens in extension."},{"id": 109,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Hip joint capsule is attached anteriorly to:","options": [{"key": "A","text": "Greater trochanter"},{"key": "B","text": "Intertrochanteric line"},{"key": "C","text": "Lesser trochanter"},{"key": "D","text": "Intertrochanteric crest"}],"correct": "B","explanation": "Anteriorly, capsule attaches to intertrochanteric line; posteriorly, ~1 cm above intertrochanteric crest."},{"id": 110,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Zona orbicularis of hip joint is:","options": [{"key": "A","text": "A band of synovium"},{"key": "B","text": "Articular cartilage ring"},{"key": "C","text": "A circular band of capsular fibres around femoral neck"},{"key": "D","text": "A ligament"}],"correct": "C","explanation": "Zona orbicularis = circular fibres of capsule forming a collar around femoral neck."},{"id": 111,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The primary blood supply to femoral head in adults is via:","options": [{"key": "A","text": "Medial circumflex femoral artery (retinacular vessels)"},{"key": "B","text": "Obturator artery"},{"key": "C","text": "Lateral circumflex femoral artery"},{"key": "D","text": "Ligamentum teres artery"}],"correct": "A","explanation": "Medial circumflex femoral artery → retinacular vessels supply most of femoral head in adults."},{"id": 112,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Trendelenburg sign is positive when:","options": [{"key": "A","text": "Both legs show limp"},{"key": "B","text": "Pelvis drops on the side of affected hip"},{"key": "C","text": "Affected leg cannot bear weight"},{"key": "D","text": "Pelvis drops on unsupported side (contralateral)"}],"correct": "D","explanation": "Trendelenburg sign: weak abductors (affected side) → pelvis drops on opposite (unsupported) side."},{"id": 113,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Trendelenburg gait is caused by weakness of which muscle?","options": [{"key": "A","text": "Gluteus medius and minimus"},{"key": "B","text": "Gluteus maximus"},{"key": "C","text": "Iliopsoas"},{"key": "D","text": "Adductor magnus"}],"correct": "A","explanation": "Gluteus medius & minimus are the hip abductors — weakness = Trendelenburg gait (waddling gait)."},{"id": 114,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Posterior dislocation of hip is more common than anterior. The classic posture is:","options": [{"key": "A","text": "Hip flexed, abducted, externally rotated"},{"key": "B","text": "Hip flexed, adducted, internally rotated"},{"key": "C","text": "Hip extended, adducted, externally rotated"},{"key": "D","text": "Hip extended, abducted, externally rotated"}],"correct": "B","explanation": "Posterior dislocation: hip flexed, adducted, internally rotated — limb appears shortened."},{"id": 115,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "In anterior dislocation of hip, the limb posture is:","options": [{"key": "A","text": "Flexed, adducted, internally rotated"},{"key": "B","text": "Flexed, abducted, internally rotated"},{"key": "C","text": "Extended, adducted, internally rotated"},{"key": "D","text": "Extended, abducted, externally rotated"}],"correct": "D","explanation": "Anterior dislocation: hip extended, abducted, externally rotated — opposite of posterior."},{"id": 116,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Nerve most commonly injured in posterior hip dislocation:","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Superior gluteal nerve"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Sciatic nerve"}],"correct": "D","explanation": "Sciatic nerve (especially peroneal division) is at risk in posterior hip dislocation."},{"id": 117,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Thomas test specifically detects:","options": [{"key": "A","text": "Hip abduction contracture"},{"key": "B","text": "Hip flexion deformity (fixed flexion deformity)"},{"key": "C","text": "Trendelenburg weakness"},{"key": "D","text": "Knee flexion contracture"}],"correct": "B","explanation": "Thomas test: flex opposite hip fully → fixed flexion deformity of tested hip becomes apparent."},{"id": 118,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Ober's test assesses tightness of:","options": [{"key": "A","text": "Iliopsoas"},{"key": "B","text": "Piriformis"},{"key": "C","text": "Adductors"},{"key": "D","text": "Iliotibial band / tensor fasciae latae"}],"correct": "D","explanation": "Ober's test detects IT band / TFL tightness — positive = hip remains abducted when lowered in sidelying."},{"id": 119,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "FABER test (Patrick's test) is positive in:","options": [{"key": "A","text": "Hip joint pathology or SI joint dysfunction"},{"key": "B","text": "Tibial stress fracture"},{"key": "C","text": "ACL tear"},{"key": "D","text": "Knee meniscus tear"}],"correct": "A","explanation": "FABER = Flexion ABduction External Rotation — stresses hip joint and SI joint."},{"id": 120,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "FADIR test is used to detect:","options": [{"key": "A","text": "Knee ligament laxity"},{"key": "B","text": "Hip labral tear or femoroacetabular impingement (FAI)"},{"key": "C","text": "IT band syndrome"},{"key": "D","text": "Ankle instability"}],"correct": "B","explanation": "FADIR = Flexion ADduction Internal Rotation — positive in FAI and labral tears."},{"id": 121,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "In femoroacetabular impingement (FAI), CAM type involves:","options": [{"key": "A","text": "Coxa vara"},{"key": "B","text": "Acetabular retroversion"},{"key": "C","text": "Acetabular over-coverage"},{"key": "D","text": "Aspherical femoral head-neck junction"}],"correct": "D","explanation": "CAM impingement = abnormal femoral head-neck junction (pistol grip deformity) — aspherical head."},{"id": 122,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "PINCER type FAI is due to:","options": [{"key": "A","text": "Coxa valga"},{"key": "B","text": "Acetabular over-coverage (coxa profunda/protrusio/retroversion)"},{"key": "C","text": "Ligamentum teres rupture"},{"key": "D","text": "Abnormal femoral head"}],"correct": "B","explanation": "PINCER FAI = acetabular over-coverage — linear contact between acetabular rim and femoral neck."},{"id": 123,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Normal range of hip flexion is:","options": [{"key": "A","text": "110–120°"},{"key": "B","text": "150°"},{"key": "C","text": "90°"},{"key": "D","text": "130–140°"}],"correct": "D","explanation": "Hip flexion ROM = 0–120° (active), up to 135–140° passively with knee flexed."},{"id": 124,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Avascular necrosis of femoral head most commonly occurs after:","options": [{"key": "A","text": "Pelvic fracture"},{"key": "B","text": "Subcapital fracture of femur neck"},{"key": "C","text": "Femoral shaft fracture"},{"key": "D","text": "Intertrochanteric fracture"}],"correct": "B","explanation": "Subcapital fracture disrupts retinacular vessels → AVN in 15–35% cases."},{"id": 125,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Garden classification is used for:","options": [{"key": "A","text": "Acetabular fractures"},{"key": "B","text": "Talar fractures"},{"key": "C","text": "Tibial plateau fractures"},{"key": "D","text": "Femoral neck fractures"}],"correct": "D","explanation": "Garden classification (I–IV) grades femoral neck fractures by degree of displacement."},{"id": 126,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The obturator nerve (L2,L3,L4) supplies the hip joint and may refer pain to:","options": [{"key": "A","text": "Dorsum of foot"},{"key": "B","text": "Buttock and posterior thigh"},{"key": "C","text": "Groin and medial thigh/knee"},{"key": "D","text": "Lateral thigh"}],"correct": "C","explanation": "Obturator nerve → pain referred to groin and medial knee (Hilton's law — same nerve supplies joint and skin)."},{"id": 127,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Snapping hip (coxa saltans) most commonly involves which structure snapping?","options": [{"key": "A","text": "Ligamentum teres over acetabular rim"},{"key": "B","text": "Iliotibial band over greater trochanter"},{"key": "C","text": "Both B and C are common"},{"key": "D","text": "Psoas tendon over iliopectineal eminence"}],"correct": "C","explanation": "External type: IT band over greater trochanter; Internal type: iliopsoas tendon over iliopectineal eminence."},{"id": 128,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Shenton's line is disrupted in:","options": [{"key": "A","text": "Hip dislocation or femoral neck fracture"},{"key": "B","text": "Tibial plateau fracture"},{"key": "C","text": "Knee OA"},{"key": "D","text": "Ankle fracture"}],"correct": "A","explanation": "Shenton's line = arc from medial femoral neck to superior obturator foramen — disrupted in hip pathology."},{"id": 129,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Legg-Calvé-Perthes disease is AVN of femoral head in children aged:","options": [{"key": "A","text": "4–8 years"},{"key": "B","text": "10–14 years"},{"key": "C","text": "0–2 years"},{"key": "D","text": "2–5 years"}],"correct": "A","explanation": "Perthes disease affects children 4–8 years (peak), boys > girls, unilateral in 90%."},{"id": 130,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "SUFE (Slipped Upper Femoral Epiphysis) most commonly occurs in:","options": [{"key": "A","text": "Obese adolescents 10–16 years"},{"key": "B","text": "Toddlers"},{"key": "C","text": "Adults"},{"key": "D","text": "School-age children 4–8 years"}],"correct": "A","explanation": "SUFE occurs in obese adolescents during growth spurt — posterior and inferior slip of epiphysis."},{"id": 131,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The safe zone for intramuscular injection in gluteal region is:","options": [{"key": "A","text": "Upper outer quadrant"},{"key": "B","text": "Lower inner quadrant"},{"key": "C","text": "Lower outer quadrant"},{"key": "D","text": "Centre of buttock"}],"correct": "A","explanation": "Upper outer quadrant of buttock — avoids sciatic nerve and superior gluteal vessels."},{"id": 132,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Piriformis syndrome causes compression of:","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Sciatic nerve"},{"key": "C","text": "Superior gluteal nerve"},{"key": "D","text": "Obturator nerve"}],"correct": "B","explanation": "Piriformis syndrome = sciatic nerve compressed by piriformis muscle in greater sciatic foramen."},{"id": 133,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Coxa profunda/protrusio acetabuli is characterised by:","options": [{"key": "A","text": "Medial protrusion of femoral head into pelvis"},{"key": "B","text": "Coxa vara"},{"key": "C","text": "Lateral subluxation"},{"key": "D","text": "Shallow acetabulum"}],"correct": "A","explanation": "Protrusio acetabuli = medial wall of acetabulum pushed medially → femoral head protrudes into pelvis."},{"id": 134,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Which nerve is at risk in total hip replacement (posterior approach)?","options": [{"key": "A","text": "Lateral femoral cutaneous nerve"},{"key": "B","text": "Sciatic nerve (peroneal division)"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Femoral nerve"}],"correct": "B","explanation": "Sciatic nerve (especially common peroneal division) is at risk in posterior approach THR."},{"id": 135,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Hip joint is a multiaxial joint allowing movements in all EXCEPT:","options": [{"key": "A","text": "Circumduction only in one plane"},{"key": "B","text": "Abduction-adduction"},{"key": "C","text": "Medial-lateral rotation"},{"key": "D","text": "Flexion-extension"}],"correct": "A","explanation": "Hip allows flexion, extension, abduction, adduction, medial/lateral rotation, and circumduction (multiaxial)."},{"id": 136,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Knee joint is which type of joint?","options": [{"key": "A","text": "Modified hinge (condylar) joint"},{"key": "B","text": "Pivot joint"},{"key": "C","text": "Ball and socket"},{"key": "D","text": "Simple hinge"}],"correct": "A","explanation": "Knee = modified hinge (condylar) joint — primarily flexion/extension + slight rotation in flexion."},{"id": 137,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The knee joint is formed by how many articulations?","options": [{"key": "A","text": "4"},{"key": "B","text": "2"},{"key": "C","text": "3"},{"key": "D","text": "1"}],"correct": "C","explanation": "Knee = 3 articulations: medial tibiofemoral, lateral tibiofemoral, and patellofemoral joints."},{"id": 138,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which structure deepens the articular surface of tibial condyles?","options": [{"key": "A","text": "Medial and lateral menisci"},{"key": "B","text": "Collateral ligaments"},{"key": "C","text": "Cruciate ligaments"},{"key": "D","text": "Patellar tendon"}],"correct": "A","explanation": "Menisci deepen the tibial articular surface, distribute load, and improve stability."},{"id": 139,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Medial meniscus is more commonly injured than lateral meniscus because:","options": [{"key": "A","text": "It bears more weight"},{"key": "B","text": "It is firmly attached to medial collateral ligament and capsule (less mobile)"},{"key": "C","text": "It is larger"},{"key": "D","text": "It is thinner"}],"correct": "B","explanation": "Medial meniscus is less mobile (attached to MCL + capsule) → more susceptible to injury in rotation."},{"id": 140,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Anterior cruciate ligament (ACL) prevents:","options": [{"key": "A","text": "Valgus stress"},{"key": "B","text": "Anterior translation of tibia on femur + hyperextension"},{"key": "C","text": "Posterior translation of tibia on femur"},{"key": "D","text": "Varus stress"}],"correct": "B","explanation": "ACL prevents anterior tibial translation on femur and hyperextension."},{"id": 141,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "ACL is attached on tibia at:","options": [{"key": "A","text": "Tibial tuberosity"},{"key": "B","text": "Posterior intercondylar area"},{"key": "C","text": "Medial condyle"},{"key": "D","text": "Anterior intercondylar area"}],"correct": "D","explanation": "ACL: anterior intercondylar area of tibia → lateral femoral condyle (inner surface)."},{"id": 142,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Posterior cruciate ligament (PCL) prevents:","options": [{"key": "A","text": "Posterior translation of tibia on femur"},{"key": "B","text": "Knee hyperextension"},{"key": "C","text": "Valgus stress"},{"key": "D","text": "Anterior translation of tibia"}],"correct": "A","explanation": "PCL is the primary restraint to posterior tibial translation — strongest ligament of knee."},{"id": 143,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Lachman test is the most sensitive test for:","options": [{"key": "A","text": "MCL tear"},{"key": "B","text": "ACL tear"},{"key": "C","text": "PCL tear"},{"key": "D","text": "Meniscus tear"}],"correct": "B","explanation": "Lachman test (knee at 20–30° flexion) is the most sensitive test for ACL tear (~85% sensitivity)."},{"id": 144,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Anterior drawer test is performed at knee flexion of:","options": [{"key": "A","text": "90°"},{"key": "B","text": "Full flexion"},{"key": "C","text": "0°"},{"key": "D","text": "20–30°"}],"correct": "A","explanation": "Anterior drawer test = knee at 90° flexion; Lachman = 20–30° flexion."},{"id": 145,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Posterior drawer test at 90° flexion is positive in:","options": [{"key": "A","text": "PCL tear"},{"key": "B","text": "Meniscus tear"},{"key": "C","text": "ACL tear"},{"key": "D","text": "MCL tear"}],"correct": "A","explanation": "Posterior drawer test: tibia pushed posteriorly at 90° — positive if tibia drops back (PCL tear)."},{"id": 146,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "McMurray's test is used to detect:","options": [{"key": "A","text": "ACL tear"},{"key": "B","text": "Meniscus tear"},{"key": "C","text": "MCL tear"},{"key": "D","text": "PCL tear"}],"correct": "B","explanation": "McMurray's test: rotation + varus/valgus stress in flexion — click/pain = meniscus tear."},{"id": 147,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Apley's grind test differentiates meniscus injury from:","options": [{"key": "A","text": "PCL injury"},{"key": "B","text": "Ligament injury (distraction test)"},{"key": "C","text": "ACL injury"},{"key": "D","text": "Patellar injury"}],"correct": "B","explanation": "Apley's test: compression (grind) → meniscus; distraction → ligament. Differentiates both."},{"id": 148,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Valgus stress test at 0° and 30° tests integrity of:","options": [{"key": "A","text": "LCL"},{"key": "B","text": "ACL"},{"key": "C","text": "MCL"},{"key": "D","text": "PCL"}],"correct": "C","explanation": "Valgus stress test at 30° = MCL; at 0° (full extension) = MCL + posterior capsule."},{"id": 149,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Lateral collateral ligament (LCL) is attached to:","options": [{"key": "A","text": "Tibia and femur"},{"key": "B","text": "Tibia and fibula"},{"key": "C","text": "Fibular head and lateral femoral condyle"},{"key": "D","text": "Fibular head and medial femoral condyle"}],"correct": "C","explanation": "LCL (fibular collateral ligament) = lateral femoral condyle → fibular head (cord-like, not attached to capsule)."},{"id": 150,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The unhappy triad (O'Donoghue's triad) of knee injuries consists of:","options": [{"key": "A","text": "ACL + PCL + medial meniscus"},{"key": "B","text": "ACL + MCL + medial meniscus"},{"key": "C","text": "PCL + MCL + medial meniscus"},{"key": "D","text": "ACL + LCL + lateral meniscus"}],"correct": "B","explanation": "Unhappy triad = ACL + MCL + medial meniscus — from valgus + rotational force."},{"id": 151,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Patella is the largest sesamoid bone in the body. It is embedded in:","options": [{"key": "A","text": "ACL"},{"key": "B","text": "IT band"},{"key": "C","text": "MCL"},{"key": "D","text": "Quadriceps tendon / patellar tendon"}],"correct": "D","explanation": "Patella is embedded in the quadriceps tendon (above) and continues as patellar tendon (below)."},{"id": 152,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The Q-angle is the angle between the quadriceps pull and patellar tendon. Increased Q-angle causes:","options": [{"key": "A","text": "ACL tear"},{"key": "B","text": "Patellar medial subluxation"},{"key": "C","text": "PCL tear"},{"key": "D","text": "Patellar lateral subluxation"}],"correct": "D","explanation": "Increased Q-angle (>20° in females) increases lateral patellar subluxation risk."},{"id": 153,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Clarke's sign (patellar grind test) is positive in:","options": [{"key": "A","text": "LCL injury"},{"key": "B","text": "Chondromalacia patellae"},{"key": "C","text": "ACL tear"},{"key": "D","text": "Meniscus tear"}],"correct": "B","explanation": "Clarke's sign: pressing patella distally and asking patient to contract quad — pain = chondromalacia."},{"id": 154,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The popliteus muscle 'unlocks' the knee by producing:","options": [{"key": "A","text": "Lateral rotation of tibia"},{"key": "B","text": "Extension at terminal range"},{"key": "C","text": "Posterior translation of tibia"},{"key": "D","text": "Medial rotation of tibia on femur (or lateral rotation of femur)"}],"correct": "D","explanation": "Popliteus unlocks the fully extended (screwed-home) knee by medially rotating tibia (or laterally rotating femur)."},{"id": 155,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Screw-home mechanism of knee occurs during the last degrees of extension. It involves:","options": [{"key": "A","text": "Patellar tilt"},{"key": "B","text": "Medial rotation of femur"},{"key": "C","text": "Lateral rotation of tibia on femur"},{"key": "D","text": "Flexion of knee"}],"correct": "C","explanation": "Screw-home: last 10–15° of knee extension → tibia laterally rotates → locks joint (close-packed)."},{"id": 156,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The suprapatellar bursa communicates with the knee joint at what age?","options": [{"key": "A","text": "Adolescence"},{"key": "B","text": "It never communicates"},{"key": "C","text": "Birth"},{"key": "D","text": "By age 3–6 months"}],"correct": "D","explanation": "Suprapatellar bursa communicates with knee joint synovial cavity by ~6 months of age."},{"id": 157,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The oblique popliteal ligament is an expansion of which muscle?","options": [{"key": "A","text": "Biceps femoris"},{"key": "B","text": "Semimembranosus"},{"key": "C","text": "Popliteus"},{"key": "D","text": "Gastrocnemius"}],"correct": "B","explanation": "Oblique popliteal ligament = expansion of semimembranosus tendon — reinforces posterior capsule."},{"id": 158,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Arcuate ligament of knee reinforces which aspect of the capsule?","options": [{"key": "A","text": "Posteromedial"},{"key": "B","text": "Posterolateral"},{"key": "C","text": "Anterior"},{"key": "D","text": "Medial"}],"correct": "B","explanation": "Arcuate ligament = Y-shaped reinforcement of posterolateral capsule — part of posterolateral corner."},{"id": 159,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Pes anserinus bursitis causes pain at:","options": [{"key": "A","text": "Posterior knee (popliteal fossa)"},{"key": "B","text": "Lateral knee"},{"key": "C","text": "Anterior knee"},{"key": "D","text": "Medial knee below joint line"}],"correct": "D","explanation": "Pes anserinus bursa is between the conjoined tendon (sartorius, gracilis, semitendinosus) and MCL — medial pain."},{"id": 160,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Baker's cyst (popliteal cyst) is a distension of which bursa?","options": [{"key": "A","text": "Prepatellar bursa"},{"key": "B","text": "Suprapatellar bursa"},{"key": "C","text": "Pes anserinus bursa"},{"key": "D","text": "Gastrocnemio-semimembranosus bursa"}],"correct": "D","explanation": "Baker's cyst = gastrocnemio-semimembranosus bursa distension — communicates with knee in adults."},{"id": 161,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The lateral meniscus is more mobile than medial because:","options": [{"key": "A","text": "It is thicker"},{"key": "B","text": "It is attached to the capsule only anteriorly"},{"key": "C","text": "It is larger"},{"key": "D","text": "It has no attachment to LCL or popliteus"}],"correct": "D","explanation": "Lateral meniscus is not attached to LCL (separated by popliteus tendon) → more mobile → less torn."},{"id": 162,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Osgood-Schlatter disease is caused by traction on patellar tendon at:","options": [{"key": "A","text": "Femoral condyle"},{"key": "B","text": "Tibial tuberosity apophysis"},{"key": "C","text": "Patellar lower pole"},{"key": "D","text": "Tibial shaft"}],"correct": "B","explanation": "Osgood-Schlatter = repetitive traction apophysitis of tibial tuberosity — adolescents."},{"id": 163,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Which test is used to assess posterolateral corner (PLC) of knee?","options": [{"key": "A","text": "Valgus stress test"},{"key": "B","text": "Dial test (tibial external rotation at 30° and 90°)"},{"key": "C","text": "McMurray test"},{"key": "D","text": "Lachman test"}],"correct": "B","explanation": "Dial test: ER of tibia at 30° = PLC injury; at both 30° and 90° = PLC + PCL injury."},{"id": 164,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The medial compartment of knee is most commonly affected in OA. Varus deformity develops because:","options": [{"key": "A","text": "Ligament laxity only"},{"key": "B","text": "Muscular imbalance"},{"key": "C","text": "Lateral cartilage loss → varus"},{"key": "D","text": "Medial cartilage loss → varus"}],"correct": "D","explanation": "Medial compartment OA → medial cartilage loss → knee bows medially (genu varum)."},{"id": 165,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Pivot shift test (MacIntosh test) is specific for:","options": [{"key": "A","text": "MCL tear"},{"key": "B","text": "ACL tear with anterolateral instability"},{"key": "C","text": "Meniscus bucket handle tear"},{"key": "D","text": "PCL tear"}],"correct": "B","explanation": "Pivot shift = subluxation-reduction of lateral tibial plateau — specific for ACL tear."},{"id": 166,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The knee joint is most stable in which position?","options": [{"key": "A","text": "Full extension (close-packed)"},{"key": "B","text": "90° flexion"},{"key": "C","text": "20° flexion"},{"key": "D","text": "45° flexion"}],"correct": "A","explanation": "Close-packed position of knee = full extension (screw-home mechanism locks it)."},{"id": 167,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Prepatellar bursitis ('housemaid's knee') causes swelling:","options": [{"key": "A","text": "Below tibial tuberosity"},{"key": "B","text": "Over the patella (superficial to it)"},{"key": "C","text": "Behind the knee"},{"key": "D","text": "Above the patella"}],"correct": "B","explanation": "Prepatellar bursa is anterior to patella — inflamed by prolonged kneeling."},{"id": 168,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Infrapatellar fat pad (Hoffa's fat pad) is located:","options": [{"key": "A","text": "In popliteal fossa"},{"key": "B","text": "Behind the patellar tendon between it and tibia"},{"key": "C","text": "Medial to patella"},{"key": "D","text": "Above patella"}],"correct": "B","explanation": "Hoffa's fat pad is between the patellar tendon anteriorly and synovium posteriorly."},{"id": 169,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The nerve supply of knee joint is from all EXCEPT:","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Lateral femoral cutaneous nerve"},{"key": "C","text": "Sciatic nerve"},{"key": "D","text": "Obturator nerve"}],"correct": "B","explanation": "Knee joint supply: femoral, obturator, common peroneal, tibial (from sciatic). Lateral femoral cutaneous supplies skin, not joint."},{"id": 170,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Discoid meniscus is most common in which meniscus?","options": [{"key": "A","text": "Medial"},{"key": "B","text": "Both equally"},{"key": "C","text": "Posterior horn only"},{"key": "D","text": "Lateral"}],"correct": "D","explanation": "Lateral discoid meniscus is more common — disc-shaped instead of C-shaped, causes snapping knee."},{"id": 171,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Ankle (talocrural) joint is which type of joint?","options": [{"key": "A","text": "Condyloid"},{"key": "B","text": "Hinge (ginglymus) joint"},{"key": "C","text": "Ball and socket"},{"key": "D","text": "Pivot"}],"correct": "B","explanation": "Ankle = hinge (ginglymus) synovial joint — allows dorsiflexion and plantarflexion."},{"id": 172,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The ankle mortise is formed by:","options": [{"key": "A","text": "Fibula and calcaneus"},{"key": "B","text": "Tibia, fibula (malleoli) and talus"},{"key": "C","text": "Tibia and talus"},{"key": "D","text": "Tibia, fibula and calcaneus"}],"correct": "B","explanation": "Ankle mortise = distal tibia (plafond) + medial malleolus + lateral malleolus gripping the talar dome."},{"id": 173,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which surface of talus articulates in the ankle joint?","options": [{"key": "A","text": "Posterior process"},{"key": "B","text": "Talar dome (trochlea)"},{"key": "C","text": "Talar head"},{"key": "D","text": "Talar neck"}],"correct": "B","explanation": "Talar dome (trochlea) articulates with tibial plafond above and malleoli on each side."},{"id": 174,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The talar dome is wider anteriorly. This makes ankle more stable in:","options": [{"key": "A","text": "Plantarflexion"},{"key": "B","text": "Eversion"},{"key": "C","text": "Inversion"},{"key": "D","text": "Dorsiflexion"}],"correct": "D","explanation": "Wider anterior talus wedges into mortise during dorsiflexion → more stable. Plantarflexion is less stable."},{"id": 175,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Most ankle sprains are due to which mechanism?","options": [{"key": "A","text": "Eversion injury"},{"key": "B","text": "Plantarflexion injury"},{"key": "C","text": "Dorsiflexion injury"},{"key": "D","text": "Inversion injury"}],"correct": "D","explanation": "85% ankle sprains = inversion (lateral ligament injuries — ATFL most commonly)."},{"id": 176,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The lateral ligament of ankle consists of three bands. Arrange from most to least commonly injured:","options": [{"key": "A","text": "ATFL > CFL > PTFL"},{"key": "B","text": "CFL > ATFL > PTFL"},{"key": "C","text": "ATFL > PTFL > CFL"},{"key": "D","text": "PTFL > CFL > ATFL"}],"correct": "A","explanation": "ATFL (anterior talofibular) > CFL (calcaneofibular) > PTFL (posterior talofibular) — in order of injury frequency."},{"id": 177,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Deltoid ligament is the medial ligament of ankle. It is injured in:","options": [{"key": "A","text": "Dorsiflexion only"},{"key": "B","text": "Plantarflexion"},{"key": "C","text": "Inversion sprain"},{"key": "D","text": "Eversion injury / severe pronation trauma"}],"correct": "D","explanation": "Deltoid (medial collateral) ligament is very strong — injured in eversion injuries or Pott's fractures."},{"id": 178,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "The deltoid ligament has how many parts?","options": [{"key": "A","text": "5"},{"key": "B","text": "4"},{"key": "C","text": "2 (superficial and deep)"},{"key": "D","text": "3"}],"correct": "B","explanation": "Deltoid ligament = 4 parts: tibionavicular, tibiocalcaneal, anterior tibiotalar, posterior tibiotalar."},{"id": 179,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Ottawa ankle rules indicate X-ray if there is:","options": [{"key": "A","text": "Tenderness over lateral malleolus + inability to bear weight"},{"key": "B","text": "Any ankle pain"},{"key": "C","text": "Pain on dorsiflexion"},{"key": "D","text": "Swelling only"}],"correct": "A","explanation": "Ottawa rules: bony tenderness at posterior malleoli or base of 5th MT/navicular + inability to weight-bear → X-ray needed."},{"id": 180,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The subtalar (talocalcaneal) joint produces which movements?","options": [{"key": "A","text": "Toe flexion and extension"},{"key": "B","text": "Rotation only"},{"key": "C","text": "Dorsiflexion and plantarflexion"},{"key": "D","text": "Inversion and eversion of hindfoot"}],"correct": "D","explanation": "Subtalar joint = triplanar motion producing inversion/eversion (supination/pronation) of hindfoot."},{"id": 181,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Simmond's (Thompson) test is positive when:","options": [{"key": "A","text": "Ankle is painful on dorsiflexion"},{"key": "B","text": "Ankle swells on compression"},{"key": "C","text": "Ankle doesn't plantarflex on calf squeeze"},{"key": "D","text": "Deltoid ligament is lax"}],"correct": "C","explanation": "Simmonds/Thompson test: squeeze calf → no plantarflexion = Achilles tendon rupture."},{"id": 182,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Achilles tendon is the combined tendon of:","options": [{"key": "A","text": "Gastrocnemius + plantaris"},{"key": "B","text": "Gastrocnemius + soleus (triceps surae)"},{"key": "C","text": "Gastrocnemius only"},{"key": "D","text": "Soleus only"}],"correct": "B","explanation": "Achilles tendon = gastrocnemius + soleus (triceps surae) → inserts into calcaneal tuberosity."},{"id": 183,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The watershed zone of Achilles tendon (most prone to rupture) is located:","options": [{"key": "A","text": "At musculotendinous junction"},{"key": "B","text": "At calcaneal insertion"},{"key": "C","text": "2–6 cm proximal to calcaneal insertion"},{"key": "D","text": "At myotendinous junction"}],"correct": "C","explanation": "Achilles watershed zone (poorest blood supply) = 2–6 cm proximal to insertion → common rupture site."},{"id": 184,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Achilles tendon rupture is most commonly seen in:","options": [{"key": "A","text": "Children"},{"key": "B","text": "Young athletes"},{"key": "C","text": "Middle-aged recreational athletes (30–50 years)"},{"key": "D","text": "Elderly >70 years"}],"correct": "C","explanation": "Achilles rupture most common in 'weekend warriors' — middle-aged recreational athletes."},{"id": 185,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Anterior talofibular ligament (ATFL) resists which movement?","options": [{"key": "A","text": "Eversion of ankle"},{"key": "B","text": "External rotation"},{"key": "C","text": "Dorsiflexion"},{"key": "D","text": "Anterior translation of talus and internal rotation in plantarflexion"}],"correct": "D","explanation": "ATFL becomes the main stabilizer in plantarflexion — resists anterior talar translation + IR."},{"id": 186,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Anterior drawer test of ankle assesses integrity of:","options": [{"key": "A","text": "PTFL"},{"key": "B","text": "ATFL"},{"key": "C","text": "Deltoid ligament"},{"key": "D","text": "CFL"}],"correct": "B","explanation": "Anterior drawer test: foot in 20° plantarflexion, stabilize tibia, push talus anteriorly — tests ATFL."},{"id": 187,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Talar tilt test assesses:","options": [{"key": "A","text": "CFL (and ATFL if severe)"},{"key": "B","text": "ATFL"},{"key": "C","text": "Syndesmosis"},{"key": "D","text": "Deltoid ligament"}],"correct": "A","explanation": "Talar tilt test: inversion stress — primarily tests CFL (calcaneofibular ligament)."},{"id": 188,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "High ankle sprain (syndesmotic sprain) injury involves:","options": [{"key": "A","text": "Deltoid ligament"},{"key": "B","text": "Subtalar joint"},{"key": "C","text": "Anterior tibiofibular ligament and interosseous membrane"},{"key": "D","text": "ATFL and CFL"}],"correct": "C","explanation": "High ankle sprain = syndesmotic injury (anterior tibiofibular ligament + interosseous membrane) from ER force."},{"id": 189,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Squeeze test for ankle syndesmosis: squeeze fibula to tibia at mid-calf causes:","options": [{"key": "A","text": "Pain at ankle (syndesmosis) = positive"},{"key": "B","text": "Pain at subtalar joint"},{"key": "C","text": "Fibular fracture"},{"key": "D","text": "Negative always"}],"correct": "A","explanation": "Squeeze test: compression at mid-fibula-tibia → pain at distal syndesmosis = syndesmotic sprain."},{"id": 190,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The tarsal tunnel syndrome is compression of which nerve?","options": [{"key": "A","text": "Posterior tibial nerve"},{"key": "B","text": "Sural nerve"},{"key": "C","text": "Superficial peroneal nerve"},{"key": "D","text": "Common peroneal nerve"}],"correct": "A","explanation": "Tarsal tunnel syndrome = posterior tibial nerve compressed under flexor retinaculum behind medial malleolus."},{"id": 191,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Peroneal tendons pass posterior to which structure at ankle?","options": [{"key": "A","text": "Navicular"},{"key": "B","text": "Medial malleolus"},{"key": "C","text": "Lateral malleolus"},{"key": "D","text": "Calcaneus"}],"correct": "C","explanation": "Peroneus longus and brevis pass posterior to lateral malleolus in a groove, held by superior peroneal retinaculum."},{"id": 192,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Peroneal tendon subluxation occurs due to rupture of:","options": [{"key": "A","text": "Calcaneofibular ligament"},{"key": "B","text": "Superior peroneal retinaculum"},{"key": "C","text": "Inferior peroneal retinaculum"},{"key": "D","text": "ATFL"}],"correct": "B","explanation": "Superior peroneal retinaculum rupture → peroneal tendon subluxation/dislocation anteriorly."},{"id": 193,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Plantar fasciitis causes heel pain most severe:","options": [{"key": "A","text": "At night"},{"key": "B","text": "On dorsiflexion of toes"},{"key": "C","text": "After rest, first steps in morning"},{"key": "D","text": "During running only"}],"correct": "C","explanation": "Plantar fasciitis pain is worst with first steps in morning (after rest) — fascia tightens overnight."},{"id": 194,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The plantar fascia (plantar aponeurosis) originates from:","options": [{"key": "A","text": "Medial calcaneal tuberosity"},{"key": "B","text": "Navicular tuberosity"},{"key": "C","text": "Cuboid"},{"key": "D","text": "Talus"}],"correct": "A","explanation": "Plantar fascia arises from medial calcaneal tuberosity and inserts into bases of proximal phalanges."},{"id": 195,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Windlass mechanism refers to:","options": [{"key": "A","text": "Peroneal tendon stabilisation"},{"key": "B","text": "Subtalar joint locking"},{"key": "C","text": "Achilles tendon elastic recoil"},{"key": "D","text": "Tightening of plantar fascia on toe dorsiflexion → raises medial arch"}],"correct": "D","explanation": "Windlass mechanism: hallux dorsiflexion tightens plantar fascia → raises medial longitudinal arch."},{"id": 196,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Haglund's deformity is a bony prominence at:","options": [{"key": "A","text": "Base of 5th metatarsal"},{"key": "B","text": "Medial malleolus"},{"key": "C","text": "Posterior-superior calcaneus (pump bump)"},{"key": "D","text": "Navicular tuberosity"}],"correct": "C","explanation": "Haglund's deformity = posterosuperior calcaneal prominence → retrocalcaneal bursitis + Achilles impingement."},{"id": 197,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The close-packed position of ankle joint is:","options": [{"key": "A","text": "Plantarflexion"},{"key": "B","text": "Inversion"},{"key": "C","text": "Neutral"},{"key": "D","text": "Maximum dorsiflexion"}],"correct": "D","explanation": "Close-packed (most stable) position of ankle = maximum dorsiflexion — wider talus locked in mortise."},{"id": 198,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Lateral process of talus fracture is called:","options": [{"key": "A","text": "Jones fracture"},{"key": "B","text": "Snowboarder's fracture"},{"key": "C","text": "Aviator's astragalus"},{"key": "D","text": "Lisfranc fracture"}],"correct": "B","explanation": "Snowboarder's fracture = lateral talar process fracture — from dorsiflexion + inversion in snowboarding."},{"id": 199,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Jones fracture is a fracture at the base of:","options": [{"key": "A","text": "2nd metatarsal"},{"key": "B","text": "5th metatarsal (junction of proximal metaphysis and diaphysis)"},{"key": "C","text": "1st metatarsal"},{"key": "D","text": "4th metatarsal"}],"correct": "B","explanation": "Jones fracture = 5th MT at meta-diaphyseal junction (~1.5 cm distal to styloid) — poor healing, high nonunion."},{"id": 200,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Which ankle ligament injury accompanies a Pott's fracture (bimalleolar injury)?","options": [{"key": "A","text": "PTFL"},{"key": "B","text": "Deltoid ligament (medial)"},{"key": "C","text": "CFL"},{"key": "D","text": "ATFL"}],"correct": "B","explanation": "Pott's fracture = fibula fracture + either medial malleolus fracture or deltoid ligament tear."},{"id": 201,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which part of humerus articulates with glenoid cavity?","options": [{"key": "A","text": "Trochlea"},{"key": "B","text": "Head"},{"key": "C","text": "Greater tubercle"},{"key": "D","text": "Capitulum"}],"correct": "B","explanation": "Head of humerus is the rounded part that fits into glenoid cavity of scapula forming glenohumeral joint."},{"id": 202,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Greater tubercle of humerus gives attachment to which muscle?","options": [{"key": "A","text": "Biceps brachii"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Coracobrachialis"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Supraspinatus inserts on the highest facet of greater tubercle; infraspinatus and teres minor on middle and lower facets."},{"id": 203,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Lesser tubercle of humerus is the insertion for which muscle?","options": [{"key": "A","text": "Teres minor"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Infraspinatus"},{"key": "D","text": "Supraspinatus"}],"correct": "B","explanation": "Subscapularis inserts on lesser tubercle; it is the only rotator cuff muscle inserting on lesser tubercle."},{"id": 204,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Surgical neck of humerus is vulnerable to injury involving which nerve?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Axillary nerve"},{"key": "D","text": "Median nerve"}],"correct": "C","explanation": "Axillary nerve winds around surgical neck of humerus; fracture here commonly damages this nerve."},{"id": 205,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Radial groove (spiral groove) of humerus transmits which structure?","options": [{"key": "A","text": "Median nerve and brachial artery"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Radial nerve and profunda brachii artery"},{"key": "D","text": "Ulnar nerve"}],"correct": "C","explanation": "Radial nerve and profunda brachii artery lie in the radial groove on the posterior shaft of humerus."},{"id": 206,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which epicondyle of humerus gives origin to common flexor tendons?","options": [{"key": "A","text": "Lateral epicondyle"},{"key": "B","text": "Capitulum"},{"key": "C","text": "Trochlea"},{"key": "D","text": "Medial epicondyle"}],"correct": "D","explanation": "Medial epicondyle is the common origin of wrist and finger flexors (tennis elbow medial type)."},{"id": 207,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Lateral epicondyle of humerus gives origin to which muscles?","options": [{"key": "A","text": "Wrist flexors"},{"key": "B","text": "Pronator teres"},{"key": "C","text": "Common extensor muscles"},{"key": "D","text": "Flexor carpi ulnaris"}],"correct": "C","explanation": "Common extensor origin: extensor carpi radialis brevis, extensor digitorum, extensor digiti minimi, extensor carpi ulnaris."},{"id": 208,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Trochlea of humerus articulates with which bone?","options": [{"key": "A","text": "Coronoid process of ulna"},{"key": "B","text": "Head of radius"},{"key": "C","text": "Trochlear notch of ulna"},{"key": "D","text": "Olecranon of ulna"}],"correct": "C","explanation": "Trochlea articulates with the trochlear notch (semilunar notch) of ulna at the elbow joint."},{"id": 209,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Capitulum of humerus articulates with which structure?","options": [{"key": "A","text": "Coronoid process"},{"key": "B","text": "Radial notch of ulna"},{"key": "C","text": "Olecranon"},{"key": "D","text": "Head of radius"}],"correct": "D","explanation": "Capitulum is the rounded lateral part of the distal humerus that articulates with the head of radius."},{"id": 210,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Deltoid tuberosity is located on which part of humerus?","options": [{"key": "A","text": "Middle third"},{"key": "B","text": "Near surgical neck"},{"key": "C","text": "Lower third"},{"key": "D","text": "Upper third"}],"correct": "A","explanation": "Deltoid tuberosity is a roughened area on the lateral aspect of the middle third of the humeral shaft."},{"id": 211,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which fossa of humerus accommodates the olecranon in full extension?","options": [{"key": "A","text": "Olecranon fossa"},{"key": "B","text": "Radial fossa"},{"key": "C","text": "Coronoid fossa"},{"key": "D","text": "Cubital fossa"}],"correct": "A","explanation": "Olecranon fossa is a posterior depression that receives the olecranon process during elbow extension."},{"id": 212,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Coronoid fossa of humerus is on which surface?","options": [{"key": "A","text": "Medial"},{"key": "B","text": "Anterior"},{"key": "C","text": "Posterior"},{"key": "D","text": "Lateral"}],"correct": "B","explanation": "Coronoid fossa is on the anterior surface of distal humerus; it receives the coronoid process in full flexion."},{"id": 213,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Ulnar nerve passes behind which structure at the elbow?","options": [{"key": "A","text": "Head of radius"},{"key": "B","text": "Olecranon"},{"key": "C","text": "Lateral epicondyle"},{"key": "D","text": "Medial epicondyle"}],"correct": "D","explanation": "Ulnar nerve passes through the cubital tunnel behind the medial epicondyle, vulnerable to 'funny bone' injury."},{"id": 214,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Fracture of anatomical neck of humerus affects which structure primarily?","options": [{"key": "A","text": "Blood supply to head"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Brachial plexus"},{"key": "D","text": "Axillary nerve"}],"correct": "A","explanation": "Anatomical neck fracture disrupts blood supply to humeral head causing avascular necrosis risk."},{"id": 215,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Intertubercular (bicipital) groove lies between which structures?","options": [{"key": "A","text": "Medial and lateral epicondyles"},{"key": "B","text": "Capitulum and trochlea"},{"key": "C","text": "Head and greater tubercle"},{"key": "D","text": "Greater and lesser tubercles"}],"correct": "D","explanation": "The bicipital groove between greater and lesser tubercles transmits the long head of biceps tendon."},{"id": 216,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which tendon runs in the intertubercular groove of humerus?","options": [{"key": "A","text": "Short head of biceps"},{"key": "B","text": "Long head of biceps"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Coracobrachialis"}],"correct": "B","explanation": "Long head of biceps tendon runs in the intertubercular groove held by transverse humeral ligament."},{"id": 217,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Teres major inserts on which part of humerus?","options": [{"key": "A","text": "Lesser tubercle"},{"key": "B","text": "Medial lip of bicipital groove"},{"key": "C","text": "Greater tubercle"},{"key": "D","text": "Lateral lip of bicipital groove"}],"correct": "B","explanation": "Teres major inserts on the medial lip of intertubercular groove; latissimus dorsi on the floor."},{"id": 218,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Pectoralis major inserts on which part of humerus?","options": [{"key": "A","text": "Greater tubercle"},{"key": "B","text": "Lateral lip of intertubercular groove"},{"key": "C","text": "Medial lip of intertubercular groove"},{"key": "D","text": "Lesser tubercle"}],"correct": "B","explanation": "Pectoralis major inserts on the lateral lip of bicipital groove (intertubercular groove)."},{"id": 219,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Carrying angle at elbow is due to which feature of humerus?","options": [{"key": "A","text": "Medial epicondyle projection"},{"key": "B","text": "Oblique trochlea"},{"key": "C","text": "Capitulum prominence"},{"key": "D","text": "Lateral condyle tilt"}],"correct": "B","explanation": "The oblique orientation of trochlea causes the carrying angle (physiological valgus) of the elbow."},{"id": 220,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Normal carrying angle in males is approximately:","options": [{"key": "A","text": "20-25 degrees"},{"key": "B","text": "10-15 degrees"},{"key": "C","text": "15-20 degrees"},{"key": "D","text": "5-10 degrees"}],"correct": "D","explanation": "Carrying angle is 5-10° in males and 10-15° in females; greater angles indicate cubitus valgus."},{"id": 221,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Head of radius is located at which end?","options": [{"key": "A","text": "Middle"},{"key": "B","text": "Proximal"},{"key": "C","text": "Medial"},{"key": "D","text": "Distal"}],"correct": "B","explanation": "Head of radius is at the proximal end; it articulates with capitulum of humerus and radial notch of ulna."},{"id": 222,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Radial tuberosity is the insertion for which muscle?","options": [{"key": "A","text": "Supinator"},{"key": "B","text": "Biceps brachii"},{"key": "C","text": "Pronator teres"},{"key": "D","text": "Brachioradialis"}],"correct": "B","explanation": "Biceps brachii inserts on radial tuberosity; this is also called bicipital tuberosity."},{"id": 223,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Pronator teres inserts on which part of radius?","options": [{"key": "A","text": "Middle of lateral surface"},{"key": "B","text": "Distal end"},{"key": "C","text": "Styloid process"},{"key": "D","text": "Radial tuberosity"}],"correct": "A","explanation": "Pronator teres inserts on the middle of the lateral convex surface (pronator tuberosity) of radius."},{"id": 224,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Styloid process of radius is on which side?","options": [{"key": "A","text": "Posterior"},{"key": "B","text": "Lateral"},{"key": "C","text": "Medial"},{"key": "D","text": "Anterior"}],"correct": "B","explanation": "Radial styloid process is on the lateral side and extends further distally than ulnar styloid process."},{"id": 225,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which carpal bone articulates with the distal end of radius?","options": [{"key": "A","text": "Capitate"},{"key": "B","text": "Hamate"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Lunate and scaphoid"}],"correct": "D","explanation": "Distal radius articulates with scaphoid (lateral) and lunate (medial) in the radiocarpal joint."},{"id": 226,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Colles' fracture involves which structure?","options": [{"key": "A","text": "Radial neck"},{"key": "B","text": "Proximal radius"},{"key": "C","text": "Distal radius with dorsal displacement"},{"key": "D","text": "Head of radius"}],"correct": "C","explanation": "Colles' fracture is a distal radius fracture with dorsal (posterior) displacement giving 'dinner fork' deformity."},{"id": 227,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Smith's fracture is reverse Colles' — what is the displacement?","options": [{"key": "A","text": "Lateral"},{"key": "B","text": "Dorsal"},{"key": "C","text": "Medial"},{"key": "D","text": "Volar (anterior)"}],"correct": "D","explanation": "Smith's fracture has volar/anterior displacement of distal fragment, opposite to Colles' fracture."},{"id": 228,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Supinator muscle wraps around which part of radius?","options": [{"key": "A","text": "Middle third"},{"key": "B","text": "Head"},{"key": "C","text": "Neck"},{"key": "D","text": "Upper third of shaft"}],"correct": "D","explanation": "Supinator wraps around the upper third of radius, rotating it to produce supination."},{"id": 229,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Interosseous membrane connects radius to ulna. Its fibers run in which direction?","options": [{"key": "A","text": "Vertically"},{"key": "B","text": "Upward-medially"},{"key": "C","text": "Downward-medially from radius to ulna"},{"key": "D","text": "Horizontal"}],"correct": "C","explanation": "Interosseous membrane fibers run downward and medially from radius to ulna, transmitting force proximally."},{"id": 230,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "Which nerve is at risk in radial neck fracture?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Posterior interosseous nerve"}],"correct": "D","explanation": "Posterior interosseous nerve (deep branch of radial nerve) winds around radial neck and is at risk."},{"id": 231,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Olecranon process of ulna is the insertion for which muscle?","options": [{"key": "A","text": "Biceps brachii"},{"key": "B","text": "Anconeus"},{"key": "C","text": "Brachialis"},{"key": "D","text": "Triceps brachii"}],"correct": "D","explanation": "Triceps brachii inserts on the posterior surface of olecranon process of ulna."},{"id": 232,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Coronoid process of ulna gives insertion to which muscle?","options": [{"key": "A","text": "Biceps"},{"key": "B","text": "Supinator"},{"key": "C","text": "Brachialis"},{"key": "D","text": "Triceps"}],"correct": "C","explanation": "Brachialis inserts on coronoid process and anterior surface of ulna (tuberosity of ulna)."},{"id": 233,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Trochlear notch (semilunar notch) of ulna articulates with which structure?","options": [{"key": "A","text": "Head of radius"},{"key": "B","text": "Lateral epicondyle"},{"key": "C","text": "Trochlea of humerus"},{"key": "D","text": "Capitulum"}],"correct": "C","explanation": "Trochlear notch is the large concavity on the anterior ulna that articulates with trochlea of humerus."},{"id": 234,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Radial notch of ulna articulates with which structure?","options": [{"key": "A","text": "Capitulum"},{"key": "B","text": "Radial tuberosity"},{"key": "C","text": "Head of radius"},{"key": "D","text": "Distal radius"}],"correct": "C","explanation": "Radial notch is a small articular depression on the lateral aspect of coronoid process for head of radius."},{"id": 235,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Styloid process of ulna is on which aspect?","options": [{"key": "A","text": "Lateral distal end"},{"key": "B","text": "Anterior distal"},{"key": "C","text": "Medial distal end"},{"key": "D","text": "Posterior proximal"}],"correct": "C","explanation": "Ulnar styloid process projects from the posteromedial aspect of the distal ulna."},{"id": 236,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor digitorum profundus originates from which bone primarily?","options": [{"key": "A","text": "Carpals"},{"key": "B","text": "Humerus"},{"key": "C","text": "Ulna"},{"key": "D","text": "Radius"}],"correct": "C","explanation": "Flexor digitorum profundus originates from the anterior and medial surfaces of the upper 3/4 of ulna."},{"id": 237,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Extensor carpi ulnaris originates from which structure?","options": [{"key": "A","text": "Olecranon only"},{"key": "B","text": "Lateral epicondyle and posterior ulna"},{"key": "C","text": "Medial epicondyle only"},{"key": "D","text": "Styloid process"}],"correct": "B","explanation": "Extensor carpi ulnaris has a dual origin: lateral epicondyle (common extensor) and posterior border of ulna."},{"id": 238,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "The proximal radioulnar joint involves which surface of ulna?","options": [{"key": "A","text": "Olecranon fossa"},{"key": "B","text": "Coronoid fossa"},{"key": "C","text": "Radial notch"},{"key": "D","text": "Trochlear notch"}],"correct": "C","explanation": "Radial notch of ulna forms the proximal radioulnar joint with the circumference of radial head."},{"id": 239,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Ulna is the main stabilizer of elbow joint. Which process provides this stability?","options": [{"key": "A","text": "Coronoid process and olecranon together"},{"key": "B","text": "Styloid process"},{"key": "C","text": "Radial notch"},{"key": "D","text": "Interosseous border"}],"correct": "A","explanation": "Coronoid process prevents posterior dislocation and olecranon prevents hyperextension — together they stabilize."},{"id": 240,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Anconeus muscle inserts on which part of ulna?","options": [{"key": "A","text": "Styloid process"},{"key": "B","text": "Olecranon lateral surface"},{"key": "C","text": "Posterior shaft"},{"key": "D","text": "Coronoid process"}],"correct": "B","explanation": "Anconeus inserts on the lateral surface of olecranon and upper posterior ulna; assists in elbow extension."},{"id": 241,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "How many carpal bones are there?","options": [{"key": "A","text": "7"},{"key": "B","text": "10"},{"key": "C","text": "8"},{"key": "D","text": "6"}],"correct": "C","explanation": "There are 8 carpal bones arranged in 2 rows of 4: proximal (STLP) and distal (TCHT) row."},{"id": 242,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which carpal bone is most commonly fractured?","options": [{"key": "A","text": "Lunate"},{"key": "B","text": "Scaphoid"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Capitate"}],"correct": "B","explanation": "Scaphoid is the most commonly fractured carpal bone, often from fall on outstretched hand (FOOSH)."},{"id": 243,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scaphoid fracture at waist risks avascular necrosis due to:","options": [{"key": "A","text": "Proximal blood supply entering distally"},{"key": "B","text": "Distal blood supply"},{"key": "C","text": "Periosteal stripping"},{"key": "D","text": "No blood supply"}],"correct": "A","explanation": "Blood enters scaphoid distally; waist fracture cuts off supply to proximal pole causing AVN."},{"id": 244,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which carpal bone can dislocate anteriorly causing median nerve compression?","options": [{"key": "A","text": "Scaphoid"},{"key": "B","text": "Lunate"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Capitate"}],"correct": "B","explanation": "Lunate dislocation is the most common carpal dislocation and compresses median nerve in carpal tunnel."},{"id": 245,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Carpal tunnel contains all of the following EXCEPT:","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Flexor pollicis longus"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Flexor digitorum superficialis tendons"}],"correct": "C","explanation": "Ulnar nerve passes through Guyon's canal (ulnar canal), NOT the carpal tunnel."},{"id": 246,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which carpal bone articulates with the thumb metacarpal at a saddle joint?","options": [{"key": "A","text": "Scaphoid"},{"key": "B","text": "Capitate"},{"key": "C","text": "Trapezoid"},{"key": "D","text": "Trapezium"}],"correct": "D","explanation": "Trapezium articulates with the first metacarpal at the carpometacarpal joint — a saddle (sellar) joint."},{"id": 247,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Pisiform bone is a sesamoid bone in the tendon of which muscle?","options": [{"key": "A","text": "Flexor carpi radialis"},{"key": "B","text": "Flexor carpi ulnaris"},{"key": "C","text": "Extensor carpi ulnaris"},{"key": "D","text": "Palmaris longus"}],"correct": "B","explanation": "Pisiform is a sesamoid bone within the flexor carpi ulnaris tendon and sits on the anterior triquetrum."},{"id": 248,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Anatomical snuffbox is bounded by tendons of which muscles?","options": [{"key": "A","text": "FCR and FCU"},{"key": "B","text": "APL, EPB (radially), EPL (ulnarly)"},{"key": "C","text": "EDC and EIP"},{"key": "D","text": "EPL and FPL"}],"correct": "B","explanation": "Anatomical snuffbox: radial boundary — APL and EPB; ulnar boundary — EPL. Floor is scaphoid."},{"id": 249,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Tenderness in anatomical snuffbox after wrist injury suggests fracture of:","options": [{"key": "A","text": "Lunate"},{"key": "B","text": "Trapezium"},{"key": "C","text": "Scaphoid"},{"key": "D","text": "Capitate"}],"correct": "C","explanation": "Scaphoid forms the floor of anatomical snuffbox; snuffbox tenderness is classical for scaphoid fracture."},{"id": 250,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Hamate bone has a hook (hamulus) that forms the:","options": [{"key": "A","text": "Ulnar border of carpal tunnel"},{"key": "B","text": "Radial border of carpal tunnel"},{"key": "C","text": "Floor of Guyon's canal"},{"key": "D","text": "Roof of carpal tunnel"}],"correct": "A","explanation": "Hook of hamate forms the ulnar border of carpal tunnel and the radial wall of Guyon's canal."},{"id": 251,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which muscle originates from the supraglenoid tubercle of scapula and runs in the bicipital groove?","options": [{"key": "A","text": "Long head of biceps"},{"key": "B","text": "Coracobrachialis"},{"key": "C","text": "Short head of biceps"},{"key": "D","text": "Deltoid"}],"correct": "A","explanation": "Long head of biceps originates from supraglenoid tubercle and travels through the bicipital groove of humerus."},{"id": 252,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Deltoid muscle inserts on which surface of humerus?","options": [{"key": "A","text": "Medial surface"},{"key": "B","text": "Anterior surface"},{"key": "C","text": "Posterior surface"},{"key": "D","text": "Deltoid tuberosity on lateral surface"}],"correct": "D","explanation": "Deltoid inserts on the deltoid tuberosity, a roughened V-shaped area on the lateral mid-shaft of humerus."},{"id": 253,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "In a Holstein-Lewis fracture, which nerve is injured?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "C","explanation": "Holstein-Lewis fracture is a distal third humeral shaft fracture that traps the radial nerve."},{"id": 254,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Supracondylar fracture of humerus in children commonly injures which artery?","options": [{"key": "A","text": "Radial artery"},{"key": "B","text": "Brachial artery"},{"key": "C","text": "Anterior interosseous artery"},{"key": "D","text": "Ulnar artery"}],"correct": "B","explanation": "Brachial artery can be kinked/torn in supracondylar fractures causing Volkmann's ischemic contracture."},{"id": 255,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Medial nerve injury in supracondylar fracture produces which deformity?","options": [{"key": "A","text": "Claw hand"},{"key": "B","text": "Ape hand"},{"key": "C","text": "Benediction hand"},{"key": "D","text": "Wrist drop"}],"correct": "B","explanation": "Median nerve injury causes 'ape hand' — loss of thenar eminence and inability to oppose thumb."},{"id": 256,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which bursa lies between the olecranon and skin?","options": [{"key": "A","text": "Radial bursa"},{"key": "B","text": "Olecranon bursa"},{"key": "C","text": "Cubital bursa"},{"key": "D","text": "Subacromial bursa"}],"correct": "B","explanation": "Olecranon bursa is a superficial bursa overlying the olecranon; inflamed in 'student's elbow'."},{"id": 257,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Coracobrachialis muscle inserts on which part of humerus?","options": [{"key": "A","text": "Medial surface of mid-shaft"},{"key": "B","text": "Deltoid tuberosity"},{"key": "C","text": "Lesser tubercle"},{"key": "D","text": "Greater tubercle"}],"correct": "A","explanation": "Coracobrachialis inserts on the medial surface of humerus at the mid-shaft level."},{"id": 258,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which muscle is NOT a rotator cuff muscle?","options": [{"key": "A","text": "Supraspinatus"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Teres major"},{"key": "D","text": "Infraspinatus"}],"correct": "C","explanation": "Rotator cuff = SITS: Supraspinatus, Infraspinatus, Teres minor, Subscapularis. Teres major is NOT part of it."},{"id": 259,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The medial wall of intertubercular groove is formed by:","options": [{"key": "A","text": "Surgical neck"},{"key": "B","text": "Greater tubercle"},{"key": "C","text": "Deltoid tuberosity"},{"key": "D","text": "Lesser tubercle"}],"correct": "D","explanation": "Lesser tubercle forms the medial wall of the bicipital (intertubercular) groove."},{"id": 260,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Radial fossa of humerus receives which structure during elbow flexion?","options": [{"key": "A","text": "Radial head"},{"key": "B","text": "Coronoid process"},{"key": "C","text": "Olecranon"},{"key": "D","text": "Capitulum"}],"correct": "A","explanation": "Radial fossa is a shallow anterior depression above capitulum that accommodates radial head during flexion."},{"id": 261,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which muscle originates from the anterior surface of radius and inserts on distal phalanx of thumb?","options": [{"key": "A","text": "Flexor pollicis longus"},{"key": "B","text": "Flexor pollicis brevis"},{"key": "C","text": "Abductor pollicis longus"},{"key": "D","text": "Opponens pollicis"}],"correct": "A","explanation": "Flexor pollicis longus originates from anterior radius and interosseous membrane; flexes IP joint of thumb."},{"id": 262,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Lister's tubercle is present on which bone?","options": [{"key": "A","text": "Radius"},{"key": "B","text": "Ulna"},{"key": "C","text": "Scaphoid"},{"key": "D","text": "Lunate"}],"correct": "A","explanation": "Lister's tubercle (dorsal radial tubercle) is on the dorsal distal radius; EPL tendon wraps around it."},{"id": 263,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Abductor pollicis longus inserts on which structure?","options": [{"key": "A","text": "Distal phalanx of thumb"},{"key": "B","text": "Trapezium"},{"key": "C","text": "Base of first metacarpal"},{"key": "D","text": "Proximal phalanx of thumb"}],"correct": "C","explanation": "APL inserts on the base of first metacarpal (radial side) and contributes to anatomical snuffbox boundary."},{"id": 264,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Distal radioulnar joint allows which movement?","options": [{"key": "A","text": "Pronation-supination"},{"key": "B","text": "Flexion-extension"},{"key": "C","text": "Radial-ulnar deviation"},{"key": "D","text": "Circumduction"}],"correct": "A","explanation": "Distal radioulnar joint (DRUJ) along with proximal RUJ allows forearm pronation and supination."},{"id": 265,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Galeazzi fracture is:","options": [{"key": "A","text": "Radial head fracture with ulnar dislocation"},{"key": "B","text": "Distal radius with ulnar styloid fracture"},{"key": "C","text": "Both bones forearm fracture"},{"key": "D","text": "Radius shaft fracture with DRUJ dislocation"}],"correct": "D","explanation": "Galeazzi = fracture of radius shaft + dislocation of distal radioulnar joint. 'Radius friend, ulna end'."},{"id": 266,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Monteggia fracture involves:","options": [{"key": "A","text": "Scaphoid fracture"},{"key": "B","text": "Distal radius fracture"},{"key": "C","text": "Both bone forearm fracture"},{"key": "D","text": "Ulna shaft fracture with radial head dislocation"}],"correct": "D","explanation": "Monteggia = fracture of proximal ulna + dislocation of radial head. 'Ulna friend, radius head end'."},{"id": 267,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Brachioradialis muscle inserts on which part of radius?","options": [{"key": "A","text": "Middle of shaft"},{"key": "B","text": "Radial tuberosity"},{"key": "C","text": "Dorsal surface"},{"key": "D","text": "Styloid process"}],"correct": "D","explanation": "Brachioradialis inserts on the lateral surface of distal radius above the styloid process."},{"id": 268,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Which muscle is attached to the oblique line of radius?","options": [{"key": "A","text": "Flexor pollicis longus"},{"key": "B","text": "Pronator teres"},{"key": "C","text": "Flexor digitorum superficialis"},{"key": "D","text": "Supinator"}],"correct": "C","explanation": "Flexor digitorum superficialis has an oblique line origin on the anterior radius between radial tuberosity and pronator insertion."},{"id": 269,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The annular ligament stabilizes which joint?","options": [{"key": "A","text": "Proximal radioulnar joint"},{"key": "B","text": "Elbow joint"},{"key": "C","text": "Distal radioulnar joint"},{"key": "D","text": "Wrist joint"}],"correct": "A","explanation": "Annular ligament wraps around the head of radius, holding it against the radial notch of ulna."},{"id": 270,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Pulled elbow (nursemaid's elbow) is due to slipping of radial head through which structure?","options": [{"key": "A","text": "Quadrate ligament"},{"key": "B","text": "Annular ligament"},{"key": "C","text": "Lateral collateral ligament"},{"key": "D","text": "Interosseous membrane"}],"correct": "B","explanation": "Annular ligament slips over the radial head in young children causing subluxation (pulled elbow)."},{"id": 271,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Supinator originates from which part of ulna?","options": [{"key": "A","text": "Posterior shaft"},{"key": "B","text": "Radial notch"},{"key": "C","text": "Coronoid process and supinator crest"},{"key": "D","text": "Olecranon"}],"correct": "C","explanation": "Supinator originates from lateral epicondyle of humerus, radial collateral ligament, and supinator crest of ulna."},{"id": 272,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor carpi ulnaris has two heads — which structure passes between them?","options": [{"key": "A","text": "Radial artery"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Anterior interosseous nerve"}],"correct": "C","explanation": "Ulnar nerve passes between the humeral and ulnar heads of flexor carpi ulnaris — compression here causes cubital tunnel syndrome."},{"id": 273,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Extensor pollicis longus wraps around which bony landmark?","options": [{"key": "A","text": "Olecranon"},{"key": "B","text": "Lister's tubercle on radius"},{"key": "C","text": "Ulnar styloid"},{"key": "D","text": "Radial styloid"}],"correct": "B","explanation": "EPL tendon changes direction around Lister's tubercle (dorsal tubercle of radius) before reaching thumb."},{"id": 274,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The triangular fibrocartilage complex (TFCC) attaches to the base of:","options": [{"key": "A","text": "Radial styloid"},{"key": "B","text": "Pisiform"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Ulnar styloid"}],"correct": "D","explanation": "TFCC attaches to the base of ulnar styloid process and is the primary stabilizer of DRUJ."},{"id": 275,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "In cubital tunnel syndrome, which nerve is compressed?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Ulnar nerve is compressed in cubital tunnel (behind medial epicondyle); causes ring and little finger numbness."},{"id": 276,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which surface of ulna is subcutaneous throughout its length?","options": [{"key": "A","text": "Posterior surface"},{"key": "B","text": "Medial surface"},{"key": "C","text": "Anterior surface"},{"key": "D","text": "Lateral surface"}],"correct": "B","explanation": "The posterior/medial border of ulna is subcutaneous throughout; palpable along entire length."},{"id": 277,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Pronator quadratus muscle is located:","options": [{"key": "A","text": "In the forearm posteriorly"},{"key": "B","text": "In the hand"},{"key": "C","text": "In the arm"},{"key": "D","text": "In the forearm anteriorly near wrist"}],"correct": "D","explanation": "Pronator quadratus is a flat quadrilateral muscle on the anterior distal forearm connecting radius and ulna."},{"id": 278,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which is the primary pronator of the forearm?","options": [{"key": "A","text": "Pronator quadratus"},{"key": "B","text": "Pronator teres"},{"key": "C","text": "Flexor carpi radialis"},{"key": "D","text": "Brachioradialis"}],"correct": "B","explanation": "Pronator teres is the primary pronator; pronator quadratus assists and acts alone in slow pronation."},{"id": 279,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Olecranon bursitis is clinically called:","options": [{"key": "A","text": "Golfer's elbow"},{"key": "B","text": "Tennis elbow"},{"key": "C","text": "Miner's elbow"},{"key": "D","text": "Student's elbow"}],"correct": "D","explanation": "Olecranon bursitis due to pressure from leaning on elbows while studying is called student's elbow."},{"id": 280,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "The interosseous border of ulna gives attachment to:","options": [{"key": "A","text": "Extensor carpi ulnaris"},{"key": "B","text": "Pronator quadratus"},{"key": "C","text": "Interosseous membrane"},{"key": "D","text": "Flexor carpi ulnaris"}],"correct": "C","explanation": "The sharp interosseous border of ulna gives attachment to the interosseous membrane connecting radius-ulna."},{"id": 281,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Proximal row of carpals from radial to ulnar side:","options": [{"key": "A","text": "Scaphoid, Lunate, Triquetrum, Pisiform"},{"key": "B","text": "Capitate, Hamate, Trapezium, Trapezoid"},{"key": "C","text": "Lunate, Scaphoid, Pisiform, Triquetrum"},{"key": "D","text": "Trapezium, Trapezoid, Capitate, Hamate"}],"correct": "A","explanation": "Proximal row: Scaphoid, Lunate, Triquetrum, Pisiform (mnemonic: She Looks Too Pretty)."},{"id": 282,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Distal row of carpals from radial to ulnar side:","options": [{"key": "A","text": "Trapezium, Trapezoid, Capitate, Hamate"},{"key": "B","text": "Lunate, Capitate, Trapezoid, Hamate"},{"key": "C","text": "Scaphoid, Lunate, Triquetrum, Pisiform"},{"key": "D","text": "Capitate, Hamate, Trapezium, Trapezoid"}],"correct": "A","explanation": "Distal row: Trapezium, Trapezoid, Capitate, Hamate (mnemonic: Try To Catch Her)."},{"id": 283,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Which carpal bone has no muscular attachment?","options": [{"key": "A","text": "Scaphoid"},{"key": "B","text": "Capitate"},{"key": "C","text": "Trapezoid"},{"key": "D","text": "Lunate"}],"correct": "D","explanation": "Lunate has no muscle attachments; it is held by ligaments only, making it prone to dislocation."},{"id": 284,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Carpal tunnel syndrome most commonly compresses which nerve?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Anterior interosseous nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "C","explanation": "Carpal tunnel syndrome involves compression of median nerve under flexor retinaculum causing thenar wasting."},{"id": 285,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Flexor retinaculum (transverse carpal ligament) is attached to which four bones?","options": [{"key": "A","text": "Scaphoid, Lunate, Capitate, Hamate"},{"key": "B","text": "Trapezium, Trapezoid, Capitate, Pisiform"},{"key": "C","text": "Radius, Ulna, Capitate, Hamate"},{"key": "D","text": "Scaphoid, Trapezium, Hamate, Pisiform"}],"correct": "D","explanation": "Flexor retinaculum attaches to scaphoid tubercle, trapezium ridge (radially) and hamate hook, pisiform (ulnarly)."},{"id": 286,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Kienbock's disease is avascular necrosis of which carpal bone?","options": [{"key": "A","text": "Scaphoid"},{"key": "B","text": "Triquetrum"},{"key": "C","text": "Capitate"},{"key": "D","text": "Lunate"}],"correct": "D","explanation": "Kienbock's disease = AVN of lunate, often associated with negative ulnar variance."},{"id": 287,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Guyon's canal (ulnar tunnel) transmits:","options": [{"key": "A","text": "Ulnar nerve and ulnar artery"},{"key": "B","text": "Superficial radial nerve"},{"key": "C","text": "Anterior interosseous nerve"},{"key": "D","text": "Median nerve and radial artery"}],"correct": "A","explanation": "Guyon's canal transmits ulnar nerve and ulnar artery; bounded by pisiform, hamate, and palmar carpal ligament."},{"id": 288,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which carpal bone is at the apex of the carpal arch (keystone)?","options": [{"key": "A","text": "Capitate"},{"key": "B","text": "Scaphoid"},{"key": "C","text": "Hamate"},{"key": "D","text": "Lunate"}],"correct": "A","explanation": "Capitate is the largest carpal bone and acts as the keystone of the carpal arch."},{"id": 289,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Watson's test (scaphoid shift test) is used to diagnose:","options": [{"key": "A","text": "Scapholunate instability"},{"key": "B","text": "TFCC tear"},{"key": "C","text": "Lunate dislocation"},{"key": "D","text": "Hook of hamate fracture"}],"correct": "A","explanation": "Watson's test detects scapholunate dissociation by applying pressure on scaphoid tubercle during ulnar-to-radial deviation."},{"id": 290,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Perilunate dislocation — which bone dislocates?","options": [{"key": "A","text": "Lunate anteriorly"},{"key": "B","text": "Triquetrum medially"},{"key": "C","text": "Scaphoid posteriorly"},{"key": "D","text": "All carpals except lunate"}],"correct": "D","explanation": "In perilunate dislocation, the lunate stays in place while all other carpals dislocate posteriorly."},{"id": 291,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which ossification centre appears first in the elbow?","options": [{"key": "A","text": "Capitulum"},{"key": "B","text": "Medial epicondyle"},{"key": "C","text": "Lateral epicondyle"},{"key": "D","text": "Radial head"}],"correct": "A","explanation": "Capitulum appears first at 1-2 years. Mnemonic for order: CRITOE (C-R-I-T-O-E)."},{"id": 292,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "CRITOE mnemonic for elbow ossification — what does 'T' stand for?","options": [{"key": "A","text": "Triquetrum"},{"key": "B","text": "Tubercle"},{"key": "C","text": "Trochlea"},{"key": "D","text": "Teres"}],"correct": "C","explanation": "CRITOE: Capitulum, Radial head, Internal (medial) epicondyle, Trochlea, Olecranon, External (lateral) epicondyle."},{"id": 293,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Lateral epicondylitis (Tennis elbow) involves which tendon primarily?","options": [{"key": "A","text": "Extensor carpi radialis brevis"},{"key": "B","text": "Extensor digitorum"},{"key": "C","text": "Extensor carpi ulnaris"},{"key": "D","text": "Extensor carpi radialis longus"}],"correct": "A","explanation": "Extensor carpi radialis brevis (ECRB) tendon is most commonly involved in lateral epicondylitis."},{"id": 294,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Medial epicondylitis (Golfer's elbow) involves which muscles?","options": [{"key": "A","text": "Common flexor-pronator origin"},{"key": "B","text": "Triceps"},{"key": "C","text": "Common extensor origin"},{"key": "D","text": "Brachioradialis"}],"correct": "A","explanation": "Golfer's elbow affects the common flexor-pronator origin at the medial epicondyle, especially FCR and pronator teres."},{"id": 295,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Posterior interosseous nerve is a branch of which nerve?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Median nerve"}],"correct": "B","explanation": "Posterior interosseous nerve is the deep branch of radial nerve; it supplies extensor muscles of forearm."},{"id": 296,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Anterior interosseous nerve is a branch of which nerve?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Median nerve"}],"correct": "D","explanation": "Anterior interosseous nerve (AIN) is a branch of median nerve supplying FPL, lateral FDP, and pronator quadratus."},{"id": 297,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "In 'Saturday night palsy' which nerve is injured?","options": [{"key": "A","text": "Axillary nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "B","explanation": "Radial nerve is compressed in the spiral groove (e.g., sleeping with arm over chair) causing wrist drop."},{"id": 298,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Froment's sign is positive in injury to which nerve?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Axillary nerve"}],"correct": "B","explanation": "Froment's sign: thumb IP flexion during key pinch due to adductor pollicis weakness — ulnar nerve palsy."},{"id": 299,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "'Dinner fork' deformity is seen in which fracture?","options": [{"key": "A","text": "Smith's fracture"},{"key": "B","text": "Colles' fracture"},{"key": "C","text": "Monteggia fracture"},{"key": "D","text": "Galeazzi fracture"}],"correct": "B","explanation": "Colles' fracture produces 'dinner fork' deformity due to dorsal displacement and tilt of distal radius fragment."},{"id": 300,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Wartenberg's sign is associated with palsy of which nerve?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Anterior interosseous nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Wartenberg's sign = persistent abduction of little finger due to weakness of palmar interossei in ulnar nerve palsy."},{"id": 301,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Shoulder (glenohumeral) joint is classified as which type of synovial joint?","options": [{"key": "A","text": "Saddle joint"},{"key": "B","text": "Condyloid joint"},{"key": "C","text": "Hinge joint"},{"key": "D","text": "Ball and socket joint"}],"correct": "D","explanation": "Glenohumeral joint is a multiaxial ball and socket synovial joint allowing greatest ROM of any joint in body."},{"id": 302,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Glenoid cavity is deepened by which fibrocartilaginous structure?","options": [{"key": "A","text": "Glenoid labrum"},{"key": "B","text": "Transverse humeral ligament"},{"key": "C","text": "Glenohumeral ligament"},{"key": "D","text": "Coracoacromial ligament"}],"correct": "A","explanation": "Glenoid labrum is a fibrocartilaginous rim that deepens the glenoid by approximately 50%, improving stability."},{"id": 303,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "The shoulder joint capsule is attached proximally to the rim of:","options": [{"key": "A","text": "Coracoid process"},{"key": "B","text": "Glenoid labrum and glenoid margin"},{"key": "C","text": "Acromion"},{"key": "D","text": "Humeral head"}],"correct": "B","explanation": "The capsule is attached proximally to the glenoid labrum and margin of glenoid cavity."},{"id": 304,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which is the weakest part of the shoulder joint capsule?","options": [{"key": "A","text": "Superior"},{"key": "B","text": "Posterior"},{"key": "C","text": "Inferior (axillary pouch)"},{"key": "D","text": "Anterior"}],"correct": "C","explanation": "Inferior capsule (axillary pouch) is the weakest — most shoulder dislocations are inferior initially then anterior."},{"id": 305,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Coracohumeral ligament strengthens which part of the shoulder capsule?","options": [{"key": "A","text": "Posterior"},{"key": "B","text": "Superior"},{"key": "C","text": "Anterior"},{"key": "D","text": "Inferior"}],"correct": "B","explanation": "Coracohumeral ligament blends with the superior capsule and reinforces it; also limits external rotation."},{"id": 306,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which three glenohumeral ligaments reinforce the anterior capsule?","options": [{"key": "A","text": "Superior, Middle, Inferior GHL"},{"key": "B","text": "Coracohumeral, Coracoacromial, Coracoclavicular"},{"key": "C","text": "Acromioclavicular, Sternoclavicular, Coracoclavicular"},{"key": "D","text": "Transverse, Oblique, Vertical"}],"correct": "A","explanation": "Superior, Middle and Inferior glenohumeral ligaments (SGHL, MGHL, IGHL) reinforce the anterior joint capsule."},{"id": 307,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Inferior glenohumeral ligament (IGHL) is the primary stabilizer against:","options": [{"key": "A","text": "Superior dislocation"},{"key": "B","text": "Anterior-inferior dislocation"},{"key": "C","text": "Superior translation"},{"key": "D","text": "Posterior dislocation"}],"correct": "B","explanation": "IGHL complex is the primary static stabilizer against anterior-inferior translation and dislocation."},{"id": 308,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which muscle is the primary dynamic stabilizer of the shoulder joint?","options": [{"key": "A","text": "Pectoralis major"},{"key": "B","text": "Biceps brachii"},{"key": "C","text": "Deltoid"},{"key": "D","text": "Rotator cuff muscles"}],"correct": "D","explanation": "Rotator cuff (SITS) provides dynamic stability by compressing humeral head into glenoid during movements."},{"id": 309,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Rotator cuff interval is a gap between which two tendons?","options": [{"key": "A","text": "Supraspinatus and infraspinatus"},{"key": "B","text": "Subscapularis and supraspinatus"},{"key": "C","text": "Supraspinatus and deltoid"},{"key": "D","text": "Infraspinatus and teres minor"}],"correct": "B","explanation": "Rotator cuff interval is between subscapularis and supraspinatus tendons; contains SGHL and CHL."},{"id": 310,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which muscle prevents superior migration of humeral head during deltoid contraction?","options": [{"key": "A","text": "Infraspinatus"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Supraspinatus"},{"key": "D","text": "Teres minor"}],"correct": "C","explanation": "Supraspinatus acts as a humeral head depressor/stabilizer preventing superior migration during shoulder abduction."},{"id": 311,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Subacromial bursa lies between which structures?","options": [{"key": "A","text": "Coracoid and subscapularis"},{"key": "B","text": "Deltoid and supraspinatus tendon/greater tubercle"},{"key": "C","text": "Glenoid and humeral head"},{"key": "D","text": "Acromion and clavicle"}],"correct": "B","explanation": "Subacromial (subdeltoid) bursa lies between deltoid muscle and supraspinatus tendon/greater tubercle."},{"id": 312,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Neer's impingement sign tests which tendon primarily?","options": [{"key": "A","text": "Infraspinatus"},{"key": "B","text": "Biceps long head"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Neer's sign: pain on passive forward flexion — tests supraspinatus (and long head biceps) impingement under acromion."},{"id": 313,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Hawkins-Kennedy test is positive in impingement of:","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Infraspinatus"},{"key": "D","text": "Supraspinatus under coracoacromial arch"}],"correct": "D","explanation": "Hawkins-Kennedy: internal rotation in 90° flexion — impinges supraspinatus against coracoacromial ligament."},{"id": 314,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Painful arc syndrome occurs during shoulder abduction between:","options": [{"key": "A","text": "0-30°"},{"key": "B","text": "120-180°"},{"key": "C","text": "30-60°"},{"key": "D","text": "60-120°"}],"correct": "D","explanation": "Painful arc is between 60-120° of abduction due to supraspinatus tendon impingement under acromion."},{"id": 315,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Anterior shoulder dislocation — humeral head lies:","options": [{"key": "A","text": "Below acromion"},{"key": "B","text": "Posterior to glenoid"},{"key": "C","text": "Anterior to glenoid, under coracoid process"},{"key": "D","text": "Superior to glenoid"}],"correct": "C","explanation": "In anterior dislocation (most common — 95%), humeral head lies anteriorly under coracoid process."},{"id": 316,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Bankart lesion in recurrent shoulder dislocation involves:","options": [{"key": "A","text": "Acromion fracture"},{"key": "B","text": "Rotator cuff tear"},{"key": "C","text": "Hill-Sachs lesion on humerus"},{"key": "D","text": "Anterior-inferior labrum detachment"}],"correct": "D","explanation": "Bankart lesion = detachment of anterior-inferior glenoid labrum and capsule from glenoid rim."},{"id": 317,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Hill-Sachs lesion in anterior shoulder dislocation is:","options": [{"key": "A","text": "Labrum tear"},{"key": "B","text": "Compression fracture of posterior humeral head"},{"key": "C","text": "SLAP lesion"},{"key": "D","text": "Compression fracture of anterior glenoid"}],"correct": "B","explanation": "Hill-Sachs lesion = compression fracture/defect of posterolateral humeral head from impaction on glenoid rim."},{"id": 318,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Posterior dislocation of shoulder is associated with which injury mechanism?","options": [{"key": "A","text": "Overhead throwing"},{"key": "B","text": "Epileptic seizure or electric shock"},{"key": "C","text": "Fall on outstretched hand"},{"key": "D","text": "Collision sports"}],"correct": "B","explanation": "Posterior dislocation is classically associated with epileptic seizures and electrocution (strong internal rotation)."},{"id": 319,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Axillary nerve injury in shoulder dislocation causes loss of sensation over:","options": [{"key": "A","text": "Thumb and index finger"},{"key": "B","text": "Medial forearm"},{"key": "C","text": "Lateral shoulder (regimental badge area)"},{"key": "D","text": "Medial arm"}],"correct": "C","explanation": "Axillary nerve supplies sensation to regimental badge area (upper lateral arm) via superior lateral cutaneous nerve."},{"id": 320,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Empty can test (Jobe's test) specifically tests integrity of:","options": [{"key": "A","text": "Infraspinatus"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Empty can test: arm in 90° abduction, 30° horizontal flexion (scapular plane), internal rotation — tests supraspinatus."},{"id": 321,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "SLAP lesion stands for:","options": [{"key": "A","text": "Subluxation Labrum Anterior Posterior"},{"key": "B","text": "Superior Ligament Avulsion Posterior"},{"key": "C","text": "Superior Labrum Anterior-Posterior tear"},{"key": "D","text": "Supraspinatus Labrum Anterior-Posterior"}],"correct": "C","explanation": "SLAP lesion = Superior Labrum Anterior to Posterior tear — involves long head of biceps anchor at glenoid."},{"id": 322,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "O'Brien's active compression test is used to diagnose:","options": [{"key": "A","text": "Shoulder instability"},{"key": "B","text": "Frozen shoulder"},{"key": "C","text": "Rotator cuff tear"},{"key": "D","text": "SLAP lesion and AC joint pathology"}],"correct": "D","explanation": "O'Brien's test: 90° flexion, 10° adduction, internal rotation — positive for SLAP lesion or AC joint pathology."},{"id": 323,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Lift-off test (Gerber's test) assesses integrity of:","options": [{"key": "A","text": "Infraspinatus"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Supraspinatus"},{"key": "D","text": "Subscapularis"}],"correct": "D","explanation": "Lift-off test: hand behind back, patient lifts away — tests subscapularis muscle and tendon integrity."},{"id": 324,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "External rotation lag sign tests which muscle?","options": [{"key": "A","text": "Infraspinatus and teres minor"},{"key": "B","text": "Supraspinatus"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Deltoid"}],"correct": "A","explanation": "External rotation lag sign: inability to maintain external rotation in 90° abduction — tests infraspinatus/teres minor."},{"id": 325,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Frozen shoulder (adhesive capsulitis) affects which motion first and most?","options": [{"key": "A","text": "Flexion"},{"key": "B","text": "Abduction"},{"key": "C","text": "External rotation"},{"key": "D","text": "Internal rotation"}],"correct": "C","explanation": "External rotation is lost first and most in frozen shoulder due to contracture of coracohumeral ligament."},{"id": 326,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Acromioclavicular (AC) joint type is:","options": [{"key": "A","text": "Ball and socket"},{"key": "B","text": "Plane (gliding) synovial joint"},{"key": "C","text": "Saddle joint"},{"key": "D","text": "Hinge joint"}],"correct": "B","explanation": "AC joint is a plane synovial joint with a fibrocartilaginous disc between the acromial and clavicular articular surfaces."},{"id": 327,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Coracoclavicular ligament has two components — which are they?","options": [{"key": "A","text": "Anterior and posterior"},{"key": "B","text": "Medial and lateral"},{"key": "C","text": "Superior and inferior"},{"key": "D","text": "Conoid and trapezoid"}],"correct": "D","explanation": "Coracoclavicular ligament = conoid (posteromedial) + trapezoid (anterolateral); suspends scapula from clavicle."},{"id": 328,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "In Grade III AC joint dislocation, which ligament is torn?","options": [{"key": "A","text": "Coracoclavicular ligament only"},{"key": "B","text": "AC ligament only"},{"key": "C","text": "Coracoacromial ligament"},{"key": "D","text": "Both AC and coracoclavicular ligaments"}],"correct": "D","explanation": "Grade III: complete tear of both AC and coracoclavicular ligaments causing complete dislocation."},{"id": 329,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Piano key sign is seen in:","options": [{"key": "A","text": "AC joint dislocation"},{"key": "B","text": "Frozen shoulder"},{"key": "C","text": "Sternoclavicular dislocation"},{"key": "D","text": "Shoulder impingement"}],"correct": "A","explanation": "Piano key sign: distal clavicle springs up when pressed down — positive in complete AC joint dislocation."},{"id": 330,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Sternoclavicular (SC) joint is the only articulation between:","options": [{"key": "A","text": "Manubrium and coracoid"},{"key": "B","text": "Scapula and thorax"},{"key": "C","text": "Upper limb and axial skeleton"},{"key": "D","text": "Clavicle and first rib"}],"correct": "C","explanation": "SC joint is the only synovial joint connecting the upper limb to the axial skeleton."},{"id": 331,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Elbow joint is a compound joint consisting of how many articulations?","options": [{"key": "A","text": "2"},{"key": "B","text": "4"},{"key": "C","text": "5"},{"key": "D","text": "3"}],"correct": "D","explanation": "Elbow has 3 articulations: humeroulnar, humeroradial, and proximal radioulnar — all within one capsule."},{"id": 332,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Humeroulnar joint is classified as:","options": [{"key": "A","text": "Pivot"},{"key": "B","text": "Ball and socket"},{"key": "C","text": "Hinge (ginglymoid)"},{"key": "D","text": "Condyloid"}],"correct": "C","explanation": "Humeroulnar joint is a hinge joint allowing flexion and extension only."},{"id": 333,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Proximal radioulnar joint is classified as:","options": [{"key": "A","text": "Hinge"},{"key": "B","text": "Saddle"},{"key": "C","text": "Pivot (trochoid)"},{"key": "D","text": "Condyloid"}],"correct": "C","explanation": "Proximal RUJ is a pivot joint — radial head rotates within the annular ligament."},{"id": 334,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Normal elbow extension is limited by which structure impacting olecranon fossa?","options": [{"key": "A","text": "Coronoid process"},{"key": "B","text": "Radial head"},{"key": "C","text": "Olecranon"},{"key": "D","text": "Medial epicondyle"}],"correct": "C","explanation": "Olecranon impacting the olecranon fossa is the bony block to elbow extension (0°)."},{"id": 335,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Normal range of elbow flexion is approximately:","options": [{"key": "A","text": "90°"},{"key": "B","text": "120°"},{"key": "C","text": "140-150°"},{"key": "D","text": "160°"}],"correct": "C","explanation": "Normal elbow flexion is 140-150°; functional range for daily activities is 30-130°."},{"id": 336,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Medial collateral ligament (UCL) of elbow has which most important component?","options": [{"key": "A","text": "Oblique band"},{"key": "B","text": "Transverse band"},{"key": "C","text": "Anterior band"},{"key": "D","text": "Posterior band"}],"correct": "C","explanation": "Anterior band of UCL (from medial epicondyle to coronoid process) is the primary stabilizer against valgus stress."},{"id": 337,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tommy John surgery involves reconstruction of which structure?","options": [{"key": "A","text": "Annular ligament"},{"key": "B","text": "Ulnar collateral ligament (medial)"},{"key": "C","text": "Interosseous membrane"},{"key": "D","text": "Lateral collateral ligament"}],"correct": "B","explanation": "Tommy John surgery = UCL (medial collateral ligament) reconstruction using palmaris longus or gracilis graft."},{"id": 338,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Lateral collateral ligament complex of elbow includes:","options": [{"key": "A","text": "UCL and annular ligament"},{"key": "B","text": "Only radial collateral ligament"},{"key": "C","text": "LUCL, RCL, annular and accessory lateral ligaments"},{"key": "D","text": "Coracoclavicular and coracoacromial"}],"correct": "C","explanation": "Lateral complex: Lateral UCL (LUCL), radial collateral ligament (RCL), annular ligament, accessory lateral ligament."},{"id": 339,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Posterolateral rotatory instability (PLRI) of elbow is due to injury of:","options": [{"key": "A","text": "Interosseous membrane"},{"key": "B","text": "Medial UCL"},{"key": "C","text": "Annular ligament"},{"key": "D","text": "Lateral UCL (LUCL)"}],"correct": "D","explanation": "LUCL injury causes PLRI — most common pattern of elbow instability after dislocation."},{"id": 340,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cubital fossa is bounded medially by which muscle?","options": [{"key": "A","text": "Pronator teres"},{"key": "B","text": "Brachioradialis"},{"key": "C","text": "Brachialis"},{"key": "D","text": "Biceps brachii"}],"correct": "A","explanation": "Cubital fossa: medial border — pronator teres; lateral border — brachioradialis; roof — bicipital aponeurosis."},{"id": 341,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Contents of cubital fossa from medial to lateral (TAN):","options": [{"key": "A","text": "Radial nerve, Brachial artery, Biceps tendon"},{"key": "B","text": "Median nerve, Brachial artery, Tendon of biceps"},{"key": "C","text": "Ulnar nerve, Radial artery, Biceps tendon"},{"key": "D","text": "Tendon of biceps, Brachial artery, Median nerve"}],"correct": "B","explanation": "Cubital fossa contents medial to lateral: Median nerve, brachial Artery, biceps teNdon (MAN/TAN)."},{"id": 342,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Carrying angle of elbow is measured between:","options": [{"key": "A","text": "Humerus and radius"},{"key": "B","text": "Radius and ulna"},{"key": "C","text": "Forearm and hand"},{"key": "D","text": "Humerus and ulna"}],"correct": "D","explanation": "Carrying angle is the angle between long axis of humerus and ulna with elbow in full extension and supination."},{"id": 343,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cubitus valgus (increased carrying angle >15°) can stretch which nerve?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Axillary nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Increased carrying angle (cubitus valgus) stretches ulnar nerve causing tardy ulnar nerve palsy."},{"id": 344,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "In posterior elbow dislocation, the olecranon displaces:","options": [{"key": "A","text": "Medially"},{"key": "B","text": "Anteriorly"},{"key": "C","text": "Laterally"},{"key": "D","text": "Posteriorly"}],"correct": "D","explanation": "In posterior dislocation (most common elbow dislocation), both radius and ulna displace posteriorly."},{"id": 345,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Valgus stress test of elbow tests integrity of:","options": [{"key": "A","text": "Annular ligament"},{"key": "B","text": "Interosseous membrane"},{"key": "C","text": "Lateral collateral ligament"},{"key": "D","text": "Medial collateral ligament (UCL)"}],"correct": "D","explanation": "Valgus stress test (milking maneuver) stresses the medial UCL; pain/laxity indicates UCL injury."},{"id": 346,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cozen's test is used to diagnose:","options": [{"key": "A","text": "Medial epicondylitis"},{"key": "B","text": "Biceps tendon rupture"},{"key": "C","text": "Lateral epicondylitis"},{"key": "D","text": "Posterior interosseous nerve entrapment"}],"correct": "C","explanation": "Cozen's test: resisted wrist extension with elbow extended — pain at lateral epicondyle indicates tennis elbow."},{"id": 347,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Mill's test for lateral epicondylitis involves:","options": [{"key": "A","text": "Resisted pronation"},{"key": "B","text": "Passive wrist flexion with elbow extended and forearm pronated"},{"key": "C","text": "Resisted supination"},{"key": "D","text": "Resisted wrist flexion"}],"correct": "B","explanation": "Mill's test: passive wrist/finger flexion with elbow extended — stretches ECRB causing lateral epicondyle pain."},{"id": 348,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Normal pronation range of the forearm is approximately:","options": [{"key": "A","text": "90°"},{"key": "B","text": "45°"},{"key": "C","text": "60-80°"},{"key": "D","text": "100°"}],"correct": "A","explanation": "Normal pronation is approximately 80-90°; supination is also 80-90° (some sources 80°)."},{"id": 349,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Biceps brachii is the most powerful:","options": [{"key": "A","text": "Shoulder abductor and flexor"},{"key": "B","text": "Elbow flexor and supinator"},{"key": "C","text": "Elbow flexor and pronator"},{"key": "D","text": "Wrist flexor"}],"correct": "B","explanation": "Biceps brachii is a powerful elbow flexor (in supination) and the most powerful supinator of the forearm."},{"id": 350,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Popeye sign (distal biceps rupture) causes the muscle belly to:","options": [{"key": "A","text": "Migrate proximally (bunch up)"},{"key": "B","text": "Migrate distally"},{"key": "C","text": "Disappear"},{"key": "D","text": "Become elongated"}],"correct": "A","explanation": "Distal biceps tendon rupture causes the muscle belly to retract/bunch up proximally — Popeye deformity."},{"id": 351,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Wrist (radiocarpal) joint is classified as:","options": [{"key": "A","text": "Ellipsoid (condyloid) joint"},{"key": "B","text": "Hinge joint"},{"key": "C","text": "Ball and socket"},{"key": "D","text": "Saddle joint"}],"correct": "A","explanation": "Wrist joint is an ellipsoid (condyloid) synovial joint allowing flexion, extension, and radial/ulnar deviation."},{"id": 352,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Distal articular surface of radius is inclined in which direction?","options": [{"key": "A","text": "Dorsally and radially"},{"key": "B","text": "Horizontally"},{"key": "C","text": "Volarly and ulnarly"},{"key": "D","text": "Ulnarly only"}],"correct": "C","explanation": "Normal distal radius has 11-12° of volar tilt and 22-23° of ulnar inclination."},{"id": 353,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Ulna does NOT directly articulate with the carpals — which structure separates them?","options": [{"key": "A","text": "Ulnar collateral ligament"},{"key": "B","text": "Flexor retinaculum"},{"key": "C","text": "Triangular fibrocartilage (TFCC)"},{"key": "D","text": "Palmar carpal ligament"}],"correct": "C","explanation": "TFCC (triangular fibrocartilage complex) separates the distal ulna from the carpals at the wrist."},{"id": 354,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Radial deviation at the wrist is limited by:","options": [{"key": "A","text": "Radial styloid impacting scaphoid"},{"key": "B","text": "Ulnar styloid"},{"key": "C","text": "Scaphoid-trapezium contact"},{"key": "D","text": "TFCC"}],"correct": "A","explanation": "Radial deviation (~15-20°) is limited when scaphoid impinges against the radial styloid process."},{"id": 355,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Ulnar deviation at the wrist has greater range than radial deviation — approximately:","options": [{"key": "A","text": "10° vs 30°"},{"key": "B","text": "20° vs 20°"},{"key": "C","text": "30° vs 15°"},{"key": "D","text": "45° vs 30°"}],"correct": "C","explanation": "Ulnar deviation is ~30-40° while radial deviation is ~15-20°; ulnar deviation allows greater excursion."},{"id": 356,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Flexor carpi radialis inserts on base of which metacarpal?","options": [{"key": "A","text": "Second and third"},{"key": "B","text": "Fourth"},{"key": "C","text": "First"},{"key": "D","text": "Fifth"}],"correct": "A","explanation": "FCR inserts primarily on base of 2nd metacarpal with a slip to 3rd metacarpal."},{"id": 357,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Flexor carpi ulnaris inserts on which bone primarily?","options": [{"key": "A","text": "Pisiform (and via ligaments to hamate and 5th metacarpal)"},{"key": "B","text": "Triquetrum"},{"key": "C","text": "Ulnar styloid"},{"key": "D","text": "Hamate directly"}],"correct": "A","explanation": "FCU inserts on pisiform, and via pisohamate and pisometacarpal ligaments extends to hamate and 5th metacarpal."},{"id": 358,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "De Quervain's tenosynovitis affects tendons in which extensor compartment?","options": [{"key": "A","text": "First dorsal compartment (APL and EPB)"},{"key": "B","text": "Third dorsal compartment"},{"key": "C","text": "Sixth dorsal compartment"},{"key": "D","text": "Second dorsal compartment"}],"correct": "A","explanation": "De Quervain's = stenosing tenosynovitis of 1st dorsal compartment containing APL and EPB tendons."},{"id": 359,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Finkelstein's test is used to diagnose:","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "De Quervain's tenosynovitis"},{"key": "C","text": "Scapholunate instability"},{"key": "D","text": "TFCC tear"}],"correct": "B","explanation": "Finkelstein's: thumb in palm, ulnar deviation of wrist — pain over radial styloid = De Quervain's positive."},{"id": 360,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Phalen's test for carpal tunnel syndrome involves:","options": [{"key": "A","text": "Wrist flexion for 60 seconds causing median nerve symptoms"},{"key": "B","text": "Resisted finger flexion"},{"key": "C","text": "Wrist extension for 60 seconds"},{"key": "D","text": "Tapping over carpal tunnel"}],"correct": "A","explanation": "Phalen's test: sustained wrist flexion (60 sec) compresses median nerve, reproducing CTS symptoms."},{"id": 361,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Tinel's sign at the wrist indicates:","options": [{"key": "A","text": "Ulnar nerve injury"},{"key": "B","text": "Radial nerve injury"},{"key": "C","text": "TFCC tear"},{"key": "D","text": "Median nerve regeneration or compression"}],"correct": "D","explanation": "Tinel's sign: tapping over carpal tunnel produces tingling in median nerve distribution — indicates CTS."},{"id": 362,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "TFCC tear causes pain specifically with:","options": [{"key": "A","text": "Radial deviation"},{"key": "B","text": "Ulnar-sided wrist pain, worse with forearm rotation"},{"key": "C","text": "Wrist flexion"},{"key": "D","text": "Wrist extension only"}],"correct": "B","explanation": "TFCC tears cause ulnar-sided wrist pain exacerbated by gripping, forearm rotation and ulnar deviation."},{"id": 363,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "The piano key sign at the wrist (DRUJ) indicates:","options": [{"key": "A","text": "Distal ulna dorsal instability"},{"key": "B","text": "De Quervain's"},{"key": "C","text": "Scapholunate instability"},{"key": "D","text": "TFCC tear"}],"correct": "A","explanation": "Piano key sign at DRUJ: dorsal prominence of distal ulna that springs back on pressure — DRUJ instability."},{"id": 364,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Midcarpal joint is between:","options": [{"key": "A","text": "Distal carpals and metacarpals"},{"key": "B","text": "Radius and proximal carpals"},{"key": "C","text": "DRUJ and radiocarpal joint"},{"key": "D","text": "Proximal and distal carpal rows"}],"correct": "D","explanation": "Midcarpal joint lies between the proximal and distal rows of carpal bones."},{"id": 365,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Carpometacarpal (CMC) joint of thumb is a saddle joint allowing:","options": [{"key": "A","text": "Flexion-extension only"},{"key": "B","text": "Flexion, extension, abduction, adduction, and opposition"},{"key": "C","text": "Hinge movements only"},{"key": "D","text": "Rotation only"}],"correct": "B","explanation": "Thumb CMC joint (trapezio-metacarpal) is a saddle joint allowing multi-directional movement including opposition."},{"id": 366,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Scapholunate dissociation shows which finding on X-ray?","options": [{"key": "A","text": "Terry Thomas sign (gap > 3mm between scaphoid and lunate)"},{"key": "B","text": "Distal radius tilt"},{"key": "C","text": "Pisiform fracture"},{"key": "D","text": "Traction spur on lunate"}],"correct": "A","explanation": "Scapholunate dissociation = >3mm gap between scaphoid and lunate on PA X-ray (Terry Thomas/David Letterman sign)."},{"id": 367,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Normal wrist flexion-extension total arc is approximately:","options": [{"key": "A","text": "100°"},{"key": "B","text": "130°"},{"key": "C","text": "160-170°"},{"key": "D","text": "90°"}],"correct": "C","explanation": "Normal wrist: flexion ~80-85° + extension ~70-80° = total arc ~160-170°. Functional arc: 40° flex to 40° ext."},{"id": 368,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Extensor retinaculum at the wrist has how many compartments?","options": [{"key": "A","text": "8"},{"key": "B","text": "4"},{"key": "C","text": "5"},{"key": "D","text": "6"}],"correct": "D","explanation": "Extensor retinaculum divides into 6 compartments for the extensor tendons of the wrist and hand."},{"id": 369,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "EPL tendon runs in which dorsal compartment of the wrist?","options": [{"key": "A","text": "Second"},{"key": "B","text": "Fourth"},{"key": "C","text": "Third"},{"key": "D","text": "First"}],"correct": "C","explanation": "EPL runs in the 3rd dorsal compartment (with Lister's tubercle as a pulley) before reaching thumb."},{"id": 370,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Wrist drop is due to injury of which nerve?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Anterior interosseous nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Median nerve"}],"correct": "A","explanation": "Radial nerve injury causes wrist drop — loss of wrist and finger extension due to extensor muscle paralysis."},{"id": 371,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Guyon's canal syndrome causes sensory loss in:","options": [{"key": "A","text": "Ring and little finger"},{"key": "B","text": "Dorsum of hand"},{"key": "C","text": "Thumb, index and middle finger"},{"key": "D","text": "All fingers"}],"correct": "A","explanation": "Guyon's canal syndrome (ulnar nerve compression) causes numbness in ring and little fingers."},{"id": 372,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "The 'dangerous arc' of shoulder abduction where most rotator cuff tears occur is at:","options": [{"key": "A","text": "Above 90°"},{"key": "B","text": "0-30°"},{"key": "C","text": "60-90°"},{"key": "D","text": "30-60°"}],"correct": "C","explanation": "Supraspinatus tension is greatest between 60-90° of abduction — the zone of maximal impingement risk."},{"id": 373,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scapulohumeral rhythm ratio during arm elevation is:","options": [{"key": "A","text": "1:1"},{"key": "B","text": "3:1"},{"key": "C","text": "1:2"},{"key": "D","text": "2:1 (glenohumeral:scapulothoracic)"}],"correct": "D","explanation": "Normal scapulohumeral rhythm: 2° glenohumeral movement for every 1° scapulothoracic movement (2:1 ratio)."},{"id": 374,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Winging of scapula is caused by paralysis of which muscle?","options": [{"key": "A","text": "Trapezius"},{"key": "B","text": "Serratus anterior"},{"key": "C","text": "Both A and B"},{"key": "D","text": "Rhomboids"}],"correct": "C","explanation": "Medial (vertebral border) winging — serratus anterior palsy; lateral winging — trapezius palsy."},{"id": 375,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Long thoracic nerve injury causes winging of scapula by paralyzing:","options": [{"key": "A","text": "Serratus anterior"},{"key": "B","text": "Trapezius"},{"key": "C","text": "Levator scapulae"},{"key": "D","text": "Rhomboids"}],"correct": "A","explanation": "Long thoracic nerve (C5,6,7) supplies serratus anterior; its injury causes classic medial border winging."},{"id": 376,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Suprascapular nerve entrapment at the spinoglenoid notch causes weakness of:","options": [{"key": "A","text": "Supraspinatus only"},{"key": "B","text": "Both supraspinatus and infraspinatus"},{"key": "C","text": "Infraspinatus only"},{"key": "D","text": "Subscapularis"}],"correct": "C","explanation": "Entrapment at spinoglenoid notch affects only infraspinatus (supraspinatus branch already given off at suprascapular notch)."},{"id": 377,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Speed's test is positive in pathology of:","options": [{"key": "A","text": "Supraspinatus"},{"key": "B","text": "SLAP lesion"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Long head of biceps tendon"}],"correct": "D","explanation": "Speed's test: resisted shoulder flexion with elbow extended and forearm supinated — positive for bicipital tendinitis."},{"id": 378,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Yergason's test assesses:","options": [{"key": "A","text": "Rotator cuff integrity"},{"key": "B","text": "AC joint pathology"},{"key": "C","text": "Shoulder instability"},{"key": "D","text": "Long head of biceps stability in bicipital groove"}],"correct": "D","explanation": "Yergason's test: resisted supination with elbow at 90° — pain in bicipital groove indicates biceps tendinitis/instability."},{"id": 379,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Apprehension test for shoulder tests for:","options": [{"key": "A","text": "AC joint instability"},{"key": "B","text": "SLAP lesion"},{"key": "C","text": "Rotator cuff tear"},{"key": "D","text": "Anterior glenohumeral instability"}],"correct": "D","explanation": "Apprehension test: arm in 90° abduction and external rotation — patient feels apprehension of dislocation."},{"id": 380,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Relocation test (Jobe's relocation test) is a follow-up to which test?","options": [{"key": "A","text": "Speed's test"},{"key": "B","text": "Empty can test"},{"key": "C","text": "Apprehension test"},{"key": "D","text": "Neer's test"}],"correct": "C","explanation": "Relocation test: posterior pressure on proximal humerus during apprehension test — relief confirms anterior instability."},{"id": 381,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "The most common direction of recurrent shoulder instability is:","options": [{"key": "A","text": "Posterior"},{"key": "B","text": "Superior"},{"key": "C","text": "Anterior-inferior"},{"key": "D","text": "Inferior"}],"correct": "C","explanation": "Anterior-inferior instability is most common (>95%) — associated with Bankart and Hill-Sachs lesions."},{"id": 382,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Type II SLAP lesion (most common) involves:","options": [{"key": "A","text": "Detachment of biceps anchor and superior labrum"},{"key": "B","text": "Posterior labrum only"},{"key": "C","text": "Bucket handle tear of labrum"},{"key": "D","text": "Fraying of superior labrum only"}],"correct": "A","explanation": "Type II SLAP = detachment of biceps-labral complex from superior glenoid — most clinically significant type."},{"id": 383,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Sulcus sign indicates:","options": [{"key": "A","text": "Inferior glenohumeral instability"},{"key": "B","text": "Posterior instability"},{"key": "C","text": "AC joint instability"},{"key": "D","text": "Rotator cuff tear"}],"correct": "A","explanation": "Sulcus sign: downward traction on arm creates a dimple below acromion — indicates inferior shoulder laxity/MDI."},{"id": 384,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Multidirectional instability (MDI) of shoulder is best treated initially with:","options": [{"key": "A","text": "Surgery"},{"key": "B","text": "Physiotherapy and muscle strengthening"},{"key": "C","text": "Steroid injection"},{"key": "D","text": "Immobilization"}],"correct": "B","explanation": "MDI is primarily treated conservatively with rotator cuff and periscapular strengthening for 6 months."},{"id": 385,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Calcific tendinitis of the shoulder most commonly affects which tendon?","options": [{"key": "A","text": "Infraspinatus"},{"key": "B","text": "Supraspinatus (critical zone)"},{"key": "C","text": "Teres minor"},{"key": "D","text": "Subscapularis"}],"correct": "B","explanation": "Calcific tendinitis most commonly occurs in the critical zone of supraspinatus — 1 cm from its insertion."},{"id": 386,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The 'critical zone' of supraspinatus tendon is an area of:","options": [{"key": "A","text": "Maximum tension"},{"key": "B","text": "Maximum thickness"},{"key": "C","text": "Nerve supply"},{"key": "D","text": "Relative avascularity"}],"correct": "D","explanation": "Critical zone is ~1 cm from supraspinatus insertion — relatively avascular, predisposing to tears and calcification."},{"id": 387,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Varus stress test of elbow tests which ligament?","options": [{"key": "A","text": "Lateral collateral ligament complex"},{"key": "B","text": "Interosseous membrane"},{"key": "C","text": "Annular ligament"},{"key": "D","text": "Medial UCL"}],"correct": "A","explanation": "Varus stress test stresses the lateral collateral ligament complex of the elbow."},{"id": 388,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Moving valgus stress test is the most sensitive test for:","options": [{"key": "A","text": "Posterior impingement"},{"key": "B","text": "Radial head fracture"},{"key": "C","text": "Lateral epicondylitis"},{"key": "D","text": "UCL injury in throwing athletes"}],"correct": "D","explanation": "Moving valgus stress test: valgus stress while moving elbow 30-120° — pain at 70-120° (shear zone) = UCL tear."},{"id": 389,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Radial head fracture most commonly results from:","options": [{"key": "A","text": "Direct blow"},{"key": "B","text": "Hyperextension only"},{"key": "C","text": "Throwing"},{"key": "D","text": "Fall on outstretched hand (FOOSH)"}],"correct": "D","explanation": "Radial head fracture commonly results from FOOSH — axial load transmitted through radius to radial head."},{"id": 390,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Mason classification is used for:","options": [{"key": "A","text": "Lateral epicondylitis grades"},{"key": "B","text": "Radial head fractures"},{"key": "C","text": "Coronoid fractures"},{"key": "D","text": "Elbow dislocation"}],"correct": "B","explanation": "Mason classification (Types I-IV) grades radial head fractures by displacement and comminution."},{"id": 391,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Posterior interosseous nerve (PIN) entrapment occurs at:","options": [{"key": "A","text": "Radial tunnel (Arcade of Frohse)"},{"key": "B","text": "Guyon's canal"},{"key": "C","text": "Carpal tunnel"},{"key": "D","text": "Cubital tunnel"}],"correct": "A","explanation": "PIN is entrapped at the arcade of Frohse (fibrous arch at supinator muscle) — causes radial tunnel syndrome."},{"id": 392,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Radial tunnel syndrome pain is located:","options": [{"key": "A","text": "4-5 cm distal to lateral epicondyle over radial tunnel"},{"key": "B","text": "Directly over lateral epicondyle"},{"key": "C","text": "Posterior elbow"},{"key": "D","text": "Medial elbow"}],"correct": "A","explanation": "Radial tunnel syndrome pain is 4-5 cm distal to lateral epicondyle — distinct from epicondylitis location."},{"id": 393,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Distal biceps tendon rupture best position for repair is:","options": [{"key": "A","text": "Delayed repair at 6 weeks"},{"key": "B","text": "Never surgical"},{"key": "C","text": "Immediate repair within 2 weeks"},{"key": "D","text": "Conservative management only"}],"correct": "C","explanation": "Distal biceps rupture: surgical repair within 2 weeks gives best outcomes; delay causes retraction and scarring."},{"id": 394,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Triceps tendon rupture is the LEAST common tendon rupture in the body. Mechanism is:","options": [{"key": "A","text": "Overuse"},{"key": "B","text": "Forceful flexion against resisting extension"},{"key": "C","text": "Fall on outstretched hand"},{"key": "D","text": "Direct blow only"}],"correct": "B","explanation": "Triceps rupture: forceful elbow flexion against an actively contracting triceps (eccentric failure)."},{"id": 395,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Lateral pivot shift test of elbow tests for:","options": [{"key": "A","text": "Radial head dislocation"},{"key": "B","text": "Annular ligament injury"},{"key": "C","text": "UCL integrity"},{"key": "D","text": "Posterolateral rotatory instability (PLRI)"}],"correct": "D","explanation": "Lateral pivot shift test: supination + valgus + axial load in flexion — positive for PLRI (LUCL injury)."},{"id": 396,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cubital tunnel syndrome is the second most common peripheral nerve compression after:","options": [{"key": "A","text": "Radial tunnel syndrome"},{"key": "B","text": "Thoracic outlet syndrome"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "Guyon's canal syndrome"}],"correct": "C","explanation": "Cubital tunnel syndrome (ulnar nerve at elbow) is second most common after CTS (median nerve at wrist)."},{"id": 397,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Scapholunate angle on lateral wrist X-ray is normally:","options": [{"key": "A","text": "100-120°"},{"key": "B","text": "70-90°"},{"key": "C","text": "30-60°"},{"key": "D","text": "10-20°"}],"correct": "C","explanation": "Normal scapholunate angle is 30-60° (average 47°); >70° suggests scapholunate dissociation."},{"id": 398,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "DISI (Dorsal Intercalated Segment Instability) shows:","options": [{"key": "A","text": "Capitate dislocates"},{"key": "B","text": "Lunate tilts volar, scaphoid tilts dorsal"},{"key": "C","text": "Lunate tilts dorsal, scaphoid flexes"},{"key": "D","text": "Both bones rotate equally"}],"correct": "C","explanation": "DISI: lunate tilts dorsally (extended) due to scapholunate ligament rupture — SL angle >70°."},{"id": 399,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "VISI (Volar Intercalated Segment Instability) is associated with:","options": [{"key": "A","text": "Distal radius fracture"},{"key": "B","text": "Lunotriquetral ligament tear"},{"key": "C","text": "TFCC tear only"},{"key": "D","text": "Scapholunate ligament tear"}],"correct": "B","explanation": "VISI: lunate tilts volarly due to lunotriquetral ligament injury — SL angle < 30°."},{"id": 400,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Ulnar variance refers to:","options": [{"key": "A","text": "Relative length difference between distal radius and ulna"},{"key": "B","text": "Ulnar styloid length"},{"key": "C","text": "DRUJ gap"},{"key": "D","text": "Ulnar deviation angle"}],"correct": "A","explanation": "Ulnar variance = relative length of distal ulnar articular surface vs distal radius (positive, negative or neutral)."},{"id": 401,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Positive ulnar variance is associated with:","options": [{"key": "A","text": "Kienbock's disease"},{"key": "B","text": "Scapholunate dissociation"},{"key": "C","text": "TFCC tears and ulnocarpal impaction"},{"key": "D","text": "Galeazzi fracture only"}],"correct": "C","explanation": "Positive ulnar variance (ulna longer than radius) causes ulnocarpal impaction and increased TFCC stress."},{"id": 402,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Grind test (compression rotation test) of thumb CMC joint diagnoses:","options": [{"key": "A","text": "Basal thumb arthritis (CMC OA)"},{"key": "B","text": "De Quervain's tenosynovitis"},{"key": "C","text": "Trigger thumb"},{"key": "D","text": "Scaphoid fracture"}],"correct": "A","explanation": "Grind test: axial compression + rotation of thumb CMC joint — pain/crepitus = CMC osteoarthritis."},{"id": 403,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Intersection syndrome is inflammation of which tendons crossing?","options": [{"key": "A","text": "2nd and 3rd dorsal compartment tendons"},{"key": "B","text": "FCR and FCU"},{"key": "C","text": "1st and 2nd dorsal compartment tendons"},{"key": "D","text": "3rd and 4th dorsal compartment tendons"}],"correct": "C","explanation": "Intersection syndrome: 1st compartment (APL, EPB) crossing 2nd compartment (ECRL, ECRB) ~4 cm proximal to wrist."},{"id": 404,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Trigger finger is due to stenosis of:","options": [{"key": "A","text": "A1 pulley of the finger flexor tendon sheath"},{"key": "B","text": "Carpal tunnel"},{"key": "C","text": "Extensor retinaculum"},{"key": "D","text": "Lumbrical canal"}],"correct": "A","explanation": "Trigger finger = stenosing tenosynovitis at A1 pulley causing catching/locking of the flexor tendon."},{"id": 405,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Linburg-Comstock syndrome is anomalous connection between tendons of:","options": [{"key": "A","text": "FDS and FDP"},{"key": "B","text": "EPL and EIP"},{"key": "C","text": "FPL and FDP of index finger"},{"key": "D","text": "APL and EPB"}],"correct": "C","explanation": "Linburg-Comstock: anomalous tendinous slip between FPL and FDP of index finger causing linked movement."},{"id": 406,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Codman's paradox refers to:","options": [{"key": "A","text": "Rotation produced by circumduction without active rotation"},{"key": "B","text": "Painful arc phenomenon"},{"key": "C","text": "Scapular rhythm reversal"},{"key": "D","text": "Shoulder instability pattern"}],"correct": "A","explanation": "Codman's paradox: after circumduction the arm ends in opposite rotation to start — demonstrates coupled motions."},{"id": 407,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Zero position of shoulder (Saha's zero position) is at:","options": [{"key": "A","text": "90° abduction in scapular plane with full external rotation"},{"key": "B","text": "90° forward flexion"},{"key": "C","text": "0° — arm at side"},{"key": "D","text": "Full elevation"}],"correct": "A","explanation": "Zero position: arm in scapular plane at ~155° elevation — glenohumeral and scapular axes aligned; most stable."},{"id": 408,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "GIRD (Glenohumeral Internal Rotation Deficit) is common in:","options": [{"key": "A","text": "Gymnasts"},{"key": "B","text": "Overhead throwing athletes"},{"key": "C","text": "Weight lifters"},{"key": "D","text": "Swimmers"}],"correct": "B","explanation": "GIRD is common in throwers (baseball pitchers) — posterior capsule tightness restricts internal rotation."},{"id": 409,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Thrower's shoulder 'dead arm' syndrome is caused by:","options": [{"key": "A","text": "Rotator cuff tear"},{"key": "B","text": "Biceps rupture"},{"key": "C","text": "Transient anterior subluxation causing neurovascular symptoms"},{"key": "D","text": "AC joint injury"}],"correct": "C","explanation": "Dead arm = transient neurological symptoms from anterior subluxation during late cocking phase of throwing."},{"id": 410,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Lateral epicondylitis is due to degeneration of which tendon and at what location?","options": [{"key": "A","text": "ECU at lateral epicondyle"},{"key": "B","text": "EDC at musculotendinous junction"},{"key": "C","text": "ECRL at origin"},{"key": "D","text": "ECRB at its origin on lateral epicondyle"}],"correct": "D","explanation": "Tennis elbow = angiofibroblastic tendinosis of ECRB at its origin on lateral epicondyle."},{"id": 411,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Normal elbow carrying angle in females is:","options": [{"key": "A","text": "15-20°"},{"key": "B","text": "20-25°"},{"key": "C","text": "10-15°"},{"key": "D","text": "5-10°"}],"correct": "A","explanation": "Carrying angle in females is approximately 13-15° (some references up to 15-20°) — greater than males."},{"id": 412,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Nursemaid's elbow (pulled elbow) most commonly occurs in children aged:","options": [{"key": "A","text": "1-4 years"},{"key": "B","text": "Above 10 years"},{"key": "C","text": "Below 1 year"},{"key": "D","text": "5-10 years"}],"correct": "A","explanation": "Pulled elbow most common in 1-4 year olds — annular ligament is lax and radial head is smaller."},{"id": 413,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "After elbow dislocation reduction, which movement is tested first?","options": [{"key": "A","text": "Supination-pronation"},{"key": "B","text": "Shoulder rotation"},{"key": "C","text": "Wrist extension"},{"key": "D","text": "Flexion-extension arc and valgus-varus stability"}],"correct": "D","explanation": "After reduction, elbow is tested through flexion-extension arc and stressed for medial/lateral stability."},{"id": 414,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Wartenberg's syndrome is entrapment of:","options": [{"key": "A","text": "Anterior interosseous nerve"},{"key": "B","text": "Posterior interosseous nerve"},{"key": "C","text": "Ulnar nerve at wrist"},{"key": "D","text": "Superficial branch of radial nerve"}],"correct": "D","explanation": "Wartenberg's syndrome: entrapment of superficial radial nerve causing dorsoradial forearm/hand sensory symptoms."},{"id": 415,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Normal grip strength loss expected after wrist fusion (arthrodesis) is:","options": [{"key": "A","text": "No loss"},{"key": "B","text": "~50% loss"},{"key": "C","text": "~10-15% loss"},{"key": "D","text": "~80% loss"}],"correct": "C","explanation": "Wrist fusion sacrifices all wrist motion but grip strength is generally well preserved (~10-15% reduction)."},{"id": 416,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scapular plane (scaption) is approximately how many degrees anterior to the coronal plane?","options": [{"key": "A","text": "15°"},{"key": "B","text": "60°"},{"key": "C","text": "30-45°"},{"key": "D","text": "90°"}],"correct": "C","explanation": "Scapular plane (scaption) is 30-45° anterior to the coronal plane — optimal position for shoulder function."},{"id": 417,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "In FOOSH injury, which combination represents 'terrible triad' of the elbow?","options": [{"key": "A","text": "Olecranon fracture + UCL + lateral ligament tear"},{"key": "B","text": "Radial head fracture + UCL tear + elbow dislocation"},{"key": "C","text": "Elbow dislocation + radial head fracture + coronoid fracture"},{"key": "D","text": "Coronoid + olecranon + MCL tear"}],"correct": "C","explanation": "Terrible triad of elbow = elbow dislocation + radial head fracture + coronoid process fracture."},{"id": 418,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "SITS mnemonic for rotator cuff muscles stands for:","options": [{"key": "A","text": "Supraspinatus, Infraspinatus, Teres major, Serratus"},{"key": "B","text": "Supraspinatus, Infraspinatus, Teres minor, Subscapularis"},{"key": "C","text": "Subscapularis, Infraspinatus, Trapezius, Supraspinatus"},{"key": "D","text": "Subscapularis, Infraspinatus, Teres major, Supraspinatus"}],"correct": "B","explanation": "SITS = Supraspinatus, Infraspinatus, Teres minor, Subscapularis — all 4 rotator cuff muscles."},{"id": 419,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Supraspinatus originates from which fossa of scapula?","options": [{"key": "A","text": "Infraspinous fossa"},{"key": "B","text": "Supraspinous fossa"},{"key": "C","text": "Subscapular fossa"},{"key": "D","text": "Glenoid fossa"}],"correct": "B","explanation": "Supraspinatus originates from the supraspinous fossa of scapula above the spine of scapula."},{"id": 420,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Supraspinatus inserts on which facet of greater tubercle?","options": [{"key": "A","text": "Upper (highest) facet"},{"key": "B","text": "Lower facet"},{"key": "C","text": "Middle facet"},{"key": "D","text": "Lesser tubercle"}],"correct": "A","explanation": "Supraspinatus inserts on the uppermost (highest) facet of the greater tubercle of humerus."},{"id": 421,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Primary action of supraspinatus is:","options": [{"key": "A","text": "External rotation"},{"key": "B","text": "Internal rotation"},{"key": "C","text": "Initiation of abduction (0-15°)"},{"key": "D","text": "Adduction"}],"correct": "C","explanation": "Supraspinatus initiates abduction and compresses humeral head into glenoid; acts throughout entire abduction arc."},{"id": 422,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Nerve supply of supraspinatus is:","options": [{"key": "A","text": "Suprascapular nerve (C5,C6)"},{"key": "B","text": "Thoracodorsal nerve"},{"key": "C","text": "Upper subscapular nerve"},{"key": "D","text": "Axillary nerve"}],"correct": "A","explanation": "Supraspinatus is supplied by the suprascapular nerve (C5, C6) which passes through the suprascapular notch."},{"id": 423,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Infraspinatus originates from which fossa?","options": [{"key": "A","text": "Subscapular fossa"},{"key": "B","text": "Supraspinous fossa"},{"key": "C","text": "Teres fossa"},{"key": "D","text": "Infraspinous fossa"}],"correct": "D","explanation": "Infraspinatus originates from the infraspinous fossa of scapula, below the spine of scapula."},{"id": 424,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Infraspinatus inserts on which facet of greater tubercle?","options": [{"key": "A","text": "Lesser tubercle"},{"key": "B","text": "Highest facet"},{"key": "C","text": "Middle facet"},{"key": "D","text": "Lowest facet"}],"correct": "C","explanation": "Infraspinatus inserts on the middle facet of the greater tubercle of humerus."},{"id": 425,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Primary action of infraspinatus is:","options": [{"key": "A","text": "External rotation of shoulder"},{"key": "B","text": "Abduction of shoulder"},{"key": "C","text": "Adduction of shoulder"},{"key": "D","text": "Internal rotation of shoulder"}],"correct": "A","explanation": "Infraspinatus is the primary external rotator of the shoulder along with teres minor."},{"id": 426,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Teres minor inserts on which facet of greater tubercle?","options": [{"key": "A","text": "Lesser tubercle"},{"key": "B","text": "Middle facet"},{"key": "C","text": "Highest facet"},{"key": "D","text": "Lowest (inferior) facet"}],"correct": "D","explanation": "Teres minor inserts on the lowest (inferior) facet of the greater tubercle of humerus."},{"id": 427,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Teres minor is supplied by which nerve?","options": [{"key": "A","text": "Posterior branch of axillary nerve"},{"key": "B","text": "Upper subscapular nerve"},{"key": "C","text": "Lower subscapular nerve"},{"key": "D","text": "Suprascapular nerve"}],"correct": "A","explanation": "Teres minor is supplied by the posterior branch of the axillary nerve (C5, C6)."},{"id": 428,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Subscapularis originates from:","options": [{"key": "A","text": "Subscapular fossa (costal surface of scapula)"},{"key": "B","text": "Supraspinous fossa"},{"key": "C","text": "Infraspinous fossa"},{"key": "D","text": "Spine of scapula"}],"correct": "A","explanation": "Subscapularis originates from the subscapular fossa on the costal (anterior) surface of the scapula."},{"id": 429,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Subscapularis inserts on:","options": [{"key": "A","text": "Intertubercular groove floor"},{"key": "B","text": "Greater tubercle — middle facet"},{"key": "C","text": "Greater tubercle — highest facet"},{"key": "D","text": "Lesser tubercle of humerus"}],"correct": "D","explanation": "Subscapularis inserts on the lesser tubercle of humerus — the only rotator cuff muscle to do so."},{"id": 430,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Primary action of subscapularis is:","options": [{"key": "A","text": "Extension of shoulder"},{"key": "B","text": "External rotation and abduction"},{"key": "C","text": "Internal rotation and adduction of shoulder"},{"key": "D","text": "Flexion of shoulder"}],"correct": "C","explanation": "Subscapularis is the primary internal rotator of the shoulder and also assists in adduction."},{"id": 431,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Subscapularis is supplied by which nerves?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Suprascapular nerve"},{"key": "C","text": "Upper and lower subscapular nerves (C5,C6)"},{"key": "D","text": "Axillary nerve"}],"correct": "C","explanation": "Subscapularis is supplied by upper subscapular nerve (C5,6) and lower subscapular nerve (C5,6)."},{"id": 432,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Lift-off test specifically tests which rotator cuff muscle?","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Supraspinatus"},{"key": "C","text": "Teres minor"},{"key": "D","text": "Infraspinatus"}],"correct": "A","explanation": "Lift-off test (Gerber): hand behind back, lift away from lumbar spine — tests subscapularis integrity."},{"id": 433,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Bear hug test is another clinical test for:","options": [{"key": "A","text": "Teres minor tear"},{"key": "B","text": "Infraspinatus tear"},{"key": "C","text": "Subscapularis tear"},{"key": "D","text": "Supraspinatus tear"}],"correct": "C","explanation": "Bear hug test: patient places hand on opposite shoulder, examiner tries to pull it away — tests subscapularis."},{"id": 434,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Most commonly torn rotator cuff tendon is:","options": [{"key": "A","text": "Teres minor"},{"key": "B","text": "Infraspinatus"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Supraspinatus is the most commonly torn rotator cuff tendon, especially at the critical zone (1 cm from insertion)."},{"id": 435,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Full-thickness supraspinatus tear on MRI shows which sign?","options": [{"key": "A","text": "Dark signal in tendon"},{"key": "B","text": "Fluid signal (bright on T2) through full thickness of tendon"},{"key": "C","text": "Calcification only"},{"key": "D","text": "Thickened tendon"}],"correct": "B","explanation": "Full-thickness tear shows bright T2 fluid signal extending through entire thickness of supraspinatus tendon."},{"id": 436,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Rotator cuff muscles collectively perform which key biomechanical function?","options": [{"key": "A","text": "Force couple with deltoid for abduction"},{"key": "B","text": "Elevation of scapula"},{"key": "C","text": "Abduction only"},{"key": "D","text": "Compression of humeral head into glenoid (concavity compression)"}],"correct": "D","explanation": "Rotator cuff muscles compress the humeral head into the glenoid (concavity compression), providing dynamic stability."},{"id": 437,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "External rotation lag sign indicates tear of:","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Long head of biceps"},{"key": "C","text": "Infraspinatus and/or teres minor"},{"key": "D","text": "Supraspinatus"}],"correct": "C","explanation": "ER lag sign: patient cannot maintain full external rotation — indicates infraspinatus (± teres minor) tear."},{"id": 438,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Biceps brachii has two heads — where does the long head originate?","options": [{"key": "A","text": "Supraglenoid tubercle of scapula"},{"key": "B","text": "Acromion"},{"key": "C","text": "Coracoid process"},{"key": "D","text": "Glenoid labrum only"}],"correct": "A","explanation": "Long head of biceps originates from the supraglenoid tubercle of scapula and passes through the bicipital groove."},{"id": 439,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Short head of biceps originates from:","options": [{"key": "A","text": "Acromion"},{"key": "B","text": "Clavicle"},{"key": "C","text": "Coracoid process of scapula"},{"key": "D","text": "Supraglenoid tubercle"}],"correct": "C","explanation": "Short head of biceps originates from the tip of the coracoid process along with coracobrachialis."},{"id": 440,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Biceps brachii inserts on:","options": [{"key": "A","text": "Olecranon of ulna"},{"key": "B","text": "Radial tuberosity and bicipital aponeurosis"},{"key": "C","text": "Styloid process of radius"},{"key": "D","text": "Coronoid process of ulna"}],"correct": "B","explanation": "Biceps inserts on the radial tuberosity (main insertion) and the bicipital aponeurosis (lacertus fibrosus)."},{"id": 441,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Biceps brachii is supplied by which nerve?","options": [{"key": "A","text": "Musculocutaneous nerve (C5, C6)"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Axillary nerve"},{"key": "D","text": "Median nerve"}],"correct": "A","explanation": "Biceps brachii is supplied by the musculocutaneous nerve (C5, C6) — a branch of lateral cord of brachial plexus."},{"id": 442,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Biceps brachii is most powerful as a supinator when the elbow is at:","options": [{"key": "A","text": "Full flexion"},{"key": "B","text": "90° flexion"},{"key": "C","text": "Full extension"},{"key": "D","text": "45° flexion"}],"correct": "B","explanation": "Biceps is most efficient supinator when elbow is at 90° flexion — the tendon angle of pull is optimal."},{"id": 443,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Bicipital aponeurosis (lacertus fibrosus) protects which structure beneath it?","options": [{"key": "A","text": "Brachial artery and median nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Radial artery"}],"correct": "A","explanation": "Bicipital aponeurosis fans medially over the cubital fossa, protecting the brachial artery and median nerve."},{"id": 444,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Speed's test is positive for pathology of:","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Coracobrachialis"},{"key": "C","text": "Short head of biceps"},{"key": "D","text": "Long head of biceps tendon"}],"correct": "D","explanation": "Speed's test: resisted forward flexion with elbow extended and forearm supinated — tests long head of biceps."},{"id": 445,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Yergason's test involves:","options": [{"key": "A","text": "Resisted supination with elbow at 90° — pain in bicipital groove"},{"key": "B","text": "Passive internal rotation"},{"key": "C","text": "Resisted abduction"},{"key": "D","text": "Resisted elbow flexion"}],"correct": "A","explanation": "Yergason's test: resisted supination at 90° elbow flexion — pain in bicipital groove = biceps tendinitis/instability."},{"id": 446,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Proximal biceps tendon rupture causes which deformity?","options": [{"key": "A","text": "Popeye deformity distally"},{"key": "B","text": "Claw hand"},{"key": "C","text": "Wrist drop"},{"key": "D","text": "Popeye deformity proximally"}],"correct": "D","explanation": "Proximal (long head) biceps rupture: muscle belly falls distally creating a bulge in distal arm (Popeye sign)."},{"id": 447,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Distal biceps tendon rupture — which action is most affected?","options": [{"key": "A","text": "Wrist flexion"},{"key": "B","text": "Shoulder abduction"},{"key": "C","text": "Supination strength (50-60% loss)"},{"key": "D","text": "Elbow flexion strength"}],"correct": "C","explanation": "Distal biceps rupture causes ~50% loss of supination strength and ~30% loss of flexion strength."},{"id": 448,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Hook test is used to diagnose:","options": [{"key": "A","text": "Distal biceps tendon rupture"},{"key": "B","text": "Brachialis tear"},{"key": "C","text": "Coracobrachialis tear"},{"key": "D","text": "Proximal biceps rupture"}],"correct": "A","explanation": "Hook test: examiner hooks finger under biceps tendon from lateral side at elbow — absence of cord = distal rupture."},{"id": 449,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Biceps brachii reflex tests which nerve root level?","options": [{"key": "A","text": "C5–C6"},{"key": "B","text": "C4"},{"key": "C","text": "C8"},{"key": "D","text": "C7"}],"correct": "A","explanation": "Biceps reflex (C5–C6) tests musculocutaneous nerve; diminished in C5/C6 radiculopathy."},{"id": 450,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Long head of biceps tendon is an intra-articular but extra-synovial structure. It lies:","options": [{"key": "A","text": "Below the coracoacromial arch only"},{"key": "B","text": "Inside the glenohumeral joint capsule, covered by synovium"},{"key": "C","text": "Outside the capsule only"},{"key": "D","text": "Inside the subacromial bursa"}],"correct": "B","explanation": "Long head biceps is intra-articular (within capsule) but covered by synovial sheath — makes it extra-synovial."},{"id": 451,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Biceps is a weak flexor in which forearm position?","options": [{"key": "A","text": "Neutral"},{"key": "B","text": "Semi-supination"},{"key": "C","text": "Pronation"},{"key": "D","text": "Supination"}],"correct": "C","explanation": "In pronation, biceps tendon is wound around radial tuberosity, reducing its mechanical advantage for flexion."},{"id": 452,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Coracobrachialis muscle shares origin with biceps short head at:","options": [{"key": "A","text": "Glenoid rim"},{"key": "B","text": "Coracoid process"},{"key": "C","text": "Supraglenoid tubercle"},{"key": "D","text": "Acromion"}],"correct": "B","explanation": "Coracobrachialis and short head of biceps both originate from the tip of the coracoid process."},{"id": 453,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Triceps brachii has how many heads?","options": [{"key": "A","text": "2"},{"key": "B","text": "1"},{"key": "C","text": "3"},{"key": "D","text": "4"}],"correct": "C","explanation": "Triceps brachii has three heads: long, medial, and lateral — the only extensor of the elbow."},{"id": 454,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Long head of triceps originates from:","options": [{"key": "A","text": "Lateral epicondyle"},{"key": "B","text": "Posterior ulna"},{"key": "C","text": "Infraglenoid tubercle of scapula"},{"key": "D","text": "Posterior humerus"}],"correct": "C","explanation": "Long head of triceps originates from the infraglenoid tubercle of scapula — only head with scapular origin."},{"id": 455,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Lateral head of triceps originates from:","options": [{"key": "A","text": "Posterior shaft above the radial groove"},{"key": "B","text": "Lateral epicondyle"},{"key": "C","text": "Infraglenoid tubercle"},{"key": "D","text": "Posterior shaft below the radial groove"}],"correct": "A","explanation": "Lateral head originates from the posterior humeral shaft proximal and lateral to the radial (spiral) groove."},{"id": 456,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Medial head of triceps is also called the 'deep head'. It originates from:","options": [{"key": "A","text": "Posterior humerus above radial groove"},{"key": "B","text": "Olecranon"},{"key": "C","text": "Posterior humerus below the radial groove (entire posterior shaft)"},{"key": "D","text": "Infraglenoid tubercle"}],"correct": "C","explanation": "Medial (deep) head originates from the posterior humeral shaft distal and medial to the radial groove."},{"id": 457,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Triceps brachii inserts on:","options": [{"key": "A","text": "Posterior surface of olecranon"},{"key": "B","text": "Styloid process of ulna"},{"key": "C","text": "Radial tuberosity"},{"key": "D","text": "Coronoid process"}],"correct": "A","explanation": "All three heads of triceps converge and insert on the posterior surface (upper part) of the olecranon process."},{"id": 458,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Triceps brachii is supplied by which nerve?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Radial nerve (C6,C7,C8)"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "C","explanation": "Triceps is supplied by the radial nerve (C6, C7, C8) — branches arise in the axilla and spiral groove."},{"id": 459,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Which head of triceps is not affected in radial nerve injury at the spiral groove?","options": [{"key": "A","text": "Long head"},{"key": "B","text": "Medial head (deep head)"},{"key": "C","text": "Lateral head"},{"key": "D","text": "All are equally affected"}],"correct": "B","explanation": "Medial head's nerve branch arises proximal to spiral groove — it is often spared in Saturday night palsy."},{"id": 460,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Triceps reflex tests which nerve root?","options": [{"key": "A","text": "C8–T1"},{"key": "B","text": "C7–C8"},{"key": "C","text": "C6–C7"},{"key": "D","text": "C5–C6"}],"correct": "B","explanation": "Triceps reflex (C7–C8) tests the radial nerve; diminished in C7 radiculopathy."},{"id": 461,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Long head of triceps passes between which two muscles?","options": [{"key": "A","text": "Deltoid and teres minor"},{"key": "B","text": "Teres major and minor"},{"key": "C","text": "Teres minor above and teres major below"},{"key": "D","text": "Infraspinatus and teres major"}],"correct": "C","explanation": "Long head of triceps passes between teres minor (above) and teres major (below), creating quadrangular and triangular spaces."},{"id": 462,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Quadrangular space transmits which structures?","options": [{"key": "A","text": "Axillary nerve and posterior circumflex humeral artery"},{"key": "B","text": "Ulnar nerve and ulnar artery"},{"key": "C","text": "Long thoracic nerve"},{"key": "D","text": "Radial nerve and profunda brachii"}],"correct": "A","explanation": "Quadrangular space: bounded by teres minor, teres major, long head triceps, and humerus — transmits axillary nerve and PCHA."},{"id": 463,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Triangular space (medial triangular space) transmits:","options": [{"key": "A","text": "Circumflex scapular artery"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Profunda brachii artery"}],"correct": "A","explanation": "Medial triangular space (between teres minor, teres major, long head triceps) transmits the circumflex scapular artery."},{"id": 464,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Triangular interval (lower triangular space) transmits:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Radial nerve and profunda brachii artery"},{"key": "C","text": "Axillary nerve and PCHA"},{"key": "D","text": "Circumflex scapular artery"}],"correct": "B","explanation": "Triangular interval (between teres major, lateral head triceps, humerus shaft) transmits radial nerve and profunda brachii."},{"id": 465,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Anconeus muscle assists triceps in elbow extension. Its nerve supply is:","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Radial nerve"}],"correct": "D","explanation": "Anconeus is supplied by the radial nerve (C7, C8); it assists extension and abducts ulna in pronation."},{"id": 466,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Primary action of long head of triceps (in addition to elbow extension) is:","options": [{"key": "A","text": "Elbow flexion"},{"key": "B","text": "Shoulder abduction"},{"key": "C","text": "Shoulder extension and adduction"},{"key": "D","text": "Shoulder flexion"}],"correct": "C","explanation": "Long head crosses the shoulder joint — it assists in shoulder extension and adduction."},{"id": 467,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Triceps tendon rupture is avulsed from which structure?","options": [{"key": "A","text": "Medial epicondyle"},{"key": "B","text": "Posterior olecranon"},{"key": "C","text": "Lateral epicondyle"},{"key": "D","text": "Posterior ulnar shaft"}],"correct": "B","explanation": "Triceps tendon avulses from the posterior olecranon — tested by resisted elbow extension."},{"id": 468,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Anterior compartment of forearm is divided into how many layers?","options": [{"key": "A","text": "3"},{"key": "B","text": "5"},{"key": "C","text": "4"},{"key": "D","text": "2"}],"correct": "A","explanation": "Anterior forearm has 3 layers: superficial (5 muscles), intermediate (FDS), and deep (FDP, FPL, PQ)."},{"id": 469,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which muscles form the superficial layer of anterior forearm?","options": [{"key": "A","text": "FCR, FCU, PL, PT, FDS"},{"key": "B","text": "FDS, FDP, FPL, PQ, PT"},{"key": "C","text": "FCR, FCU, FDP, PL, PT"},{"key": "D","text": "PT, FCR, PL, FCU, BR"}],"correct": "D","explanation": "Superficial layer (5 muscles): Pronator teres, FCR, Palmaris longus, FCU, and Brachioradialis (BR)."},{"id": 470,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Flexor digitorum superficialis (FDS) inserts on:","options": [{"key": "A","text": "Proximal phalanges of fingers 2-5"},{"key": "B","text": "Base of first metacarpal"},{"key": "C","text": "Distal phalanges of fingers 2-5"},{"key": "D","text": "Middle phalanges of fingers 2-5"}],"correct": "D","explanation": "FDS splits and inserts on the sides of the middle phalanges of the medial four fingers."},{"id": 471,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Flexor digitorum profundus (FDP) inserts on:","options": [{"key": "A","text": "Distal phalanges of fingers 2-5"},{"key": "B","text": "Middle phalanges"},{"key": "C","text": "Metacarpals"},{"key": "D","text": "Proximal phalanges"}],"correct": "A","explanation": "FDP inserts on the anterior surface of the base of distal phalanges of fingers 2-5."},{"id": 472,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "FDP to index and middle fingers is supplied by:","options": [{"key": "A","text": "Median nerve proper"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Anterior interosseous nerve (branch of median)"}],"correct": "D","explanation": "Lateral part of FDP (index and middle fingers) is supplied by the anterior interosseous nerve (AIN), branch of median nerve."},{"id": 473,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "FDP to ring and little fingers is supplied by:","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Anterior interosseous nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Medial part of FDP (ring and little fingers) is supplied by the ulnar nerve (C8, T1)."},{"id": 474,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Flexor pollicis longus originates from:","options": [{"key": "A","text": "Anterior surface of ulna"},{"key": "B","text": "Coracoid process"},{"key": "C","text": "Anterior surface of radius and adjacent interosseous membrane"},{"key": "D","text": "Medial epicondyle"}],"correct": "C","explanation": "FPL originates from the anterior surface of the radius and adjacent interosseous membrane."},{"id": 475,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "FPL is supplied by which nerve?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve proper"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Anterior interosseous nerve (AIN)"}],"correct": "D","explanation": "FPL is supplied by the anterior interosseous nerve (AIN) — a branch of the median nerve."},{"id": 476,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Pronator quadratus (PQ) is the primary muscle for:","options": [{"key": "A","text": "Rapid pronation only"},{"key": "B","text": "Slow pronation and maintains DRUJ stability"},{"key": "C","text": "Supination of forearm"},{"key": "D","text": "Wrist flexion"}],"correct": "B","explanation": "PQ is the primary pronator for all forearm pronation and stabilizes DRUJ; pronator teres assists."},{"id": 477,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Palmaris longus is absent in approximately what percentage of population?","options": [{"key": "A","text": "50%"},{"key": "B","text": "14%"},{"key": "C","text": "5%"},{"key": "D","text": "30%"}],"correct": "B","explanation": "Palmaris longus is absent in about 14% of individuals (varies by population); used as graft donor tendon."},{"id": 478,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Palmaris longus is used clinically as a graft for:","options": [{"key": "A","text": "Tendon graft for UCL reconstruction (Tommy John)"},{"key": "B","text": "Knee ACL reconstruction"},{"key": "C","text": "Nerve graft"},{"key": "D","text": "Skin graft"}],"correct": "A","explanation": "Palmaris longus tendon is commonly harvested for UCL reconstruction (Tommy John surgery) at the elbow."},{"id": 479,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Anterior interosseous nerve (AIN) syndrome causes inability to:","options": [{"key": "A","text": "Extend wrist"},{"key": "B","text": "Flex distal phalanx of index finger and thumb (pinch sign)"},{"key": "C","text": "Abduct thumb"},{"key": "D","text": "Flex fingers 4 and 5"}],"correct": "B","explanation": "AIN syndrome: loss of FPL and lateral FDP (index) — patient cannot make 'OK sign'; pinch becomes tip-to-tip."},{"id": 480,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "'OK sign' (tip-to-tip pinch) failure suggests injury to:","options": [{"key": "A","text": "Posterior interosseous nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Anterior interosseous nerve"},{"key": "D","text": "Median nerve at wrist"}],"correct": "C","explanation": "AIN palsy: FPL and lateral FDP paralysis — patient makes pulp-to-pulp instead of tip-to-tip pinch."},{"id": 481,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor carpi radialis (FCR) inserts on:","options": [{"key": "A","text": "Bases of 2nd and 3rd metacarpals"},{"key": "B","text": "Trapezium"},{"key": "C","text": "Pisiform bone"},{"key": "D","text": "Base of 5th metacarpal"}],"correct": "A","explanation": "FCR inserts on the base of the 2nd metacarpal (primarily) and a slip to 3rd metacarpal."},{"id": 482,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor carpi ulnaris (FCU) is the only flexor muscle supplied entirely by the ulnar nerve. It inserts on:","options": [{"key": "A","text": "Pisiform (and via ligaments to hamate and 5th metacarpal)"},{"key": "B","text": "Lunate"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Hamate only"}],"correct": "A","explanation": "FCU inserts on pisiform, and its pull is transmitted via pisohamate and pisometacarpal ligaments."},{"id": 483,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which forearm muscle is the primary wrist flexor tested in isolation?","options": [{"key": "A","text": "PQ"},{"key": "B","text": "FDP"},{"key": "C","text": "FDS"},{"key": "D","text": "FCR"}],"correct": "D","explanation": "FCR and FCU are the primary wrist flexors; FCR tested by resisted wrist flexion with radial deviation."},{"id": 484,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Volkmann's ischemic contracture follows compartment syndrome of forearm. Which muscles are primarily affected?","options": [{"key": "A","text": "Intrinsic hand muscles"},{"key": "B","text": "Extensor muscles"},{"key": "C","text": "Flexor muscles (FDP and FPL most severely)"},{"key": "D","text": "Brachioradialis"}],"correct": "C","explanation": "Volkmann's: deep flexors (FDP and FPL) are most affected as they are furthest from collateral circulation."},{"id": 485,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Pronator syndrome is entrapment of median nerve between two heads of:","options": [{"key": "A","text": "Pronator teres"},{"key": "B","text": "FDS"},{"key": "C","text": "FCU"},{"key": "D","text": "PQ"}],"correct": "A","explanation": "Pronator syndrome: median nerve compressed between humeral and ulnar heads of pronator teres."},{"id": 486,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "FDS is tested in isolation by:","options": [{"key": "A","text": "Flexing all fingers simultaneously"},{"key": "B","text": "Flexing DIP joint against resistance"},{"key": "C","text": "Holding other fingers in extension, then flexing the tested finger at PIP joint"},{"key": "D","text": "Resisted wrist flexion"}],"correct": "C","explanation": "FDS test: hold other fingers extended (eliminating FDP), then flex the tested finger at PIP — tests FDS only."},{"id": 487,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Intermediate layer of anterior forearm consists of:","options": [{"key": "A","text": "Pronator teres only"},{"key": "B","text": "FDP and FPL"},{"key": "C","text": "Flexor digitorum superficialis only"},{"key": "D","text": "PQ only"}],"correct": "C","explanation": "FDS forms the entire intermediate layer; it is the largest muscle in the anterior forearm."},{"id": 488,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Posterior compartment of forearm has how many muscles?","options": [{"key": "A","text": "7"},{"key": "B","text": "12"},{"key": "C","text": "9"},{"key": "D","text": "6"}],"correct": "B","explanation": "Posterior forearm has 12 muscles: 7 superficial (including BR, ECRL, ECRB, ED, EDM, ECU, Anconeus) and 5 deep."},{"id": 489,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Brachioradialis muscle, though in posterior compartment, is a:","options": [{"key": "A","text": "Wrist flexor"},{"key": "B","text": "Elbow flexor"},{"key": "C","text": "Wrist extensor"},{"key": "D","text": "Forearm supinator"}],"correct": "B","explanation": "Brachioradialis (supplied by radial nerve) is primarily an elbow flexor — most effective when forearm is in neutral."},{"id": 490,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "ECRL and ECRB insert on which metacarpal bases?","options": [{"key": "A","text": "1st and 2nd"},{"key": "B","text": "3rd and 4th"},{"key": "C","text": "2nd and 3rd"},{"key": "D","text": "4th and 5th"}],"correct": "C","explanation": "ECRL inserts on base of 2nd metacarpal; ECRB on base of 3rd metacarpal — both extend and radially deviate wrist."},{"id": 491,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Extensor carpi ulnaris (ECU) inserts on:","options": [{"key": "A","text": "Base of 5th metacarpal"},{"key": "B","text": "Triquetrum"},{"key": "C","text": "Base of 4th metacarpal"},{"key": "D","text": "Hamate"}],"correct": "A","explanation": "ECU inserts on the base of the 5th metacarpal — it extends and ulnarly deviates the wrist."},{"id": 492,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Supinator muscle originates from:","options": [{"key": "A","text": "Lateral epicondyle, radial collateral ligament, and supinator crest of ulna"},{"key": "B","text": "Medial epicondyle only"},{"key": "C","text": "Annular ligament only"},{"key": "D","text": "Radial head only"}],"correct": "A","explanation": "Supinator has a broad origin: lateral epicondyle, radial collateral ligament, annular ligament, and supinator crest of ulna."},{"id": 493,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Posterior interosseous nerve (PIN) passes between the two heads of:","options": [{"key": "A","text": "Brachioradialis"},{"key": "B","text": "FCU"},{"key": "C","text": "Pronator teres"},{"key": "D","text": "Supinator"}],"correct": "D","explanation": "PIN (deep branch of radial nerve) passes between the superficial and deep heads of supinator at the arcade of Frohse."},{"id": 494,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Arcade of Frohse is the fibrous arch at the proximal edge of:","options": [{"key": "A","text": "ECU"},{"key": "B","text": "Pronator teres"},{"key": "C","text": "Supinator"},{"key": "D","text": "Brachioradialis"}],"correct": "C","explanation": "Arcade of Frohse is the fibrous proximal arch of the superficial head of supinator — most common site of PIN entrapment."},{"id": 495,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Abductor pollicis longus (APL) inserts on:","options": [{"key": "A","text": "Base of first metacarpal"},{"key": "B","text": "Proximal phalanx of thumb"},{"key": "C","text": "Trapezium"},{"key": "D","text": "Distal phalanx of thumb"}],"correct": "A","explanation": "APL inserts on the base of the first metacarpal (radial side) — forms the radial border of anatomical snuffbox."},{"id": 496,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Extensor pollicis brevis (EPB) inserts on:","options": [{"key": "A","text": "First metacarpal base"},{"key": "B","text": "Trapezium"},{"key": "C","text": "Base of distal phalanx of thumb"},{"key": "D","text": "Base of proximal phalanx of thumb"}],"correct": "D","explanation": "EPB inserts on the base of the proximal phalanx of the thumb — it extends the MCP joint of thumb."},{"id": 497,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Extensor pollicis longus (EPL) inserts on:","options": [{"key": "A","text": "First metacarpal"},{"key": "B","text": "Base of distal phalanx of thumb"},{"key": "C","text": "Base of proximal phalanx"},{"key": "D","text": "Trapezoid bone"}],"correct": "B","explanation": "EPL inserts on the base of the distal phalanx of thumb — it extends the IP joint of thumb."},{"id": 498,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Extensor indicis proprius (EIP) allows:","options": [{"key": "A","text": "Index finger extension only"},{"key": "B","text": "Wrist extension"},{"key": "C","text": "Abduction of index finger"},{"key": "D","text": "Independent extension of index finger with other fingers flexed"}],"correct": "D","explanation": "EIP allows independent extension of index finger; clinically tested by asking patient to point while fist is made."},{"id": 499,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "De Quervain's tenosynovitis involves tendons in which extensor compartment?","options": [{"key": "A","text": "1st (APL and EPB)"},{"key": "B","text": "4th"},{"key": "C","text": "2nd"},{"key": "D","text": "3rd"}],"correct": "A","explanation": "De Quervain's = stenosing tenosynovitis of 1st dorsal compartment containing APL and EPB."},{"id": 500,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "All muscles of posterior forearm are supplied by:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Radial nerve and its branches"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "C","explanation": "All posterior forearm muscles are supplied by the radial nerve — either directly or via its PIN branch."},{"id": 501,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Mallet finger is due to rupture/avulsion of:","options": [{"key": "A","text": "FDP tendon at middle phalanx"},{"key": "B","text": "Extensor tendon at DIP joint (terminal tendon)"},{"key": "C","text": "FDS tendon"},{"key": "D","text": "Intrinsic muscles"}],"correct": "B","explanation": "Mallet finger: forced flexion of extended DIP joint ruptures the terminal extensor tendon, causing droop."},{"id": 502,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Boutonniere deformity results from rupture of:","options": [{"key": "A","text": "Terminal extensor tendon"},{"key": "B","text": "FDS tendon"},{"key": "C","text": "Central slip of extensor tendon at PIP joint"},{"key": "D","text": "Lateral bands"}],"correct": "C","explanation": "Boutonniere: central slip rupture allows PIP to flex through the rent; lateral bands slide volarly causing DIP hyperextension."},{"id": 503,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Wrist drop is due to which nerve injury?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Radial nerve"}],"correct": "D","explanation": "Radial nerve injury causes wrist drop — loss of wrist and finger extensors (posterior compartment paralysis)."},{"id": 504,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "In radial nerve palsy, which wrist movement is preserved?","options": [{"key": "A","text": "Wrist extension"},{"key": "B","text": "Thumb extension"},{"key": "C","text": "Wrist flexion (FCR and FCU intact via median and ulnar nerves)"},{"key": "D","text": "Finger extension"}],"correct": "C","explanation": "In radial nerve palsy, wrist flexion is preserved because FCR (median) and FCU (ulnar) are intact."},{"id": 505,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Claw hand deformity is due to injury of:","options": [{"key": "A","text": "Median nerve only"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Ulnar nerve — ring and little finger clawing"},{"key": "D","text": "All three nerves"}],"correct": "C","explanation": "Ulnar nerve palsy causes intrinsic muscle paralysis of ring and little fingers — MCP hyperextension + IP flexion (claw)."},{"id": 506,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "'Pointing index' (Benediction hand) posture occurs in high median nerve injury because:","options": [{"key": "A","text": "FDP and FPL for index and middle are paralyzed"},{"key": "B","text": "Thenar muscles are weak"},{"key": "C","text": "FDS is weak"},{"key": "D","text": "Interossei are paralyzed"}],"correct": "A","explanation": "High median nerve injury paralyzes lateral FDP and FPL — patient cannot flex index and middle fingers fully."},{"id": 507,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Ape hand deformity (thenar wasting) is due to:","options": [{"key": "A","text": "Radial nerve palsy"},{"key": "B","text": "Median nerve palsy"},{"key": "C","text": "Ulnar nerve palsy"},{"key": "D","text": "Axillary nerve palsy"}],"correct": "B","explanation": "Median nerve palsy causes thenar wasting and loss of thumb opposition — classic ape hand appearance."},{"id": 508,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Intrinsic plus position of hand (lumbrical position) is:","options": [{"key": "A","text": "MCP flexion + IP extension"},{"key": "B","text": "All joints in extension"},{"key": "C","text": "All joints in flexion"},{"key": "D","text": "MCP hyperextension + IP flexion"}],"correct": "A","explanation": "Intrinsic plus (lumbrical) position: MCP flexion with IP extension — opposite to claw hand deformity."},{"id": 509,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Froment's sign tests which muscle?","options": [{"key": "A","text": "FPL (AIN)"},{"key": "B","text": "Opponens pollicis (median)"},{"key": "C","text": "Adductor pollicis (ulnar nerve)"},{"key": "D","text": "APL (radial nerve)"}],"correct": "C","explanation": "Froment's sign: patient flexes thumb IP (using FPL) during key pinch — indicates adductor pollicis weakness (ulnar nerve)."},{"id": 510,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Intrinsic muscles of the hand are supplied by:","options": [{"key": "A","text": "Median (LOAF) and ulnar nerves"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Median nerve only"},{"key": "D","text": "Ulnar nerve only"}],"correct": "A","explanation": "LOAF muscles by median nerve; remaining intrinsics (interossei, medial 2 lumbricals, hypothenar) by ulnar nerve."},{"id": 511,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "LOAF muscles (median nerve in hand) are:","options": [{"key": "A","text": "All lumbricals and thenar"},{"key": "B","text": "Lumbricals 1&2, Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis"},{"key": "C","text": "Interossei and lumbricals"},{"key": "D","text": "Lumbricals 3&4, Opponens, APL, FPB"}],"correct": "B","explanation": "LOAF: Lateral 2 Lumbricals, Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis (superficial head)."},{"id": 512,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Wartenberg's sign (persistent little finger abduction) is due to paralysis of:","options": [{"key": "A","text": "Palmar interosseous muscle of little finger"},{"key": "B","text": "Abductor digiti minimi"},{"key": "C","text": "Extensor digiti minimi"},{"key": "D","text": "FDS to little finger"}],"correct": "A","explanation": "Wartenberg's sign: ulnar nerve palsy paralyzes the palmar interosseous — no active adduction of little finger."},{"id": 513,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Compartment syndrome of forearm — which test is most sensitive?","options": [{"key": "A","text": "Passive stretch pain"},{"key": "B","text": "Paralysis"},{"key": "C","text": "Pallor"},{"key": "D","text": "Paresthesia"}],"correct": "A","explanation": "Passive stretch pain is the earliest and most sensitive sign of forearm compartment syndrome."},{"id": 514,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "After radial nerve repair at the spiral groove, which muscle recovers last?","options": [{"key": "A","text": "Brachioradialis"},{"key": "B","text": "ECRL"},{"key": "C","text": "Supinator"},{"key": "D","text": "Extensor indicis proprius (EIP)"}],"correct": "D","explanation": "EIP is most distal — nerve regenerates at ~1 mm/day, so distal muscles recover last after proximal injury."},{"id": 515,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Z-plasty lengthening of Achilles tendon is a technique borrowed for forearm flexor contracture release in Volkmann's. The original Volkmann's procedure involves:","options": [{"key": "A","text": "Fasciotomy only"},{"key": "B","text": "Tendon transfer"},{"key": "C","text": "Nerve decompression"},{"key": "D","text": "Muscle slide operation"}],"correct": "D","explanation": "Muscle slide (modified Scaglietti) procedure releases flexor pronator origin to correct Volkmann's contracture."},{"id": 516,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Which test differentiates between extrinsic and intrinsic tightness of hand?","options": [{"key": "A","text": "Watson's test"},{"key": "B","text": "Bunnel-Littler test"},{"key": "C","text": "Finkelstein's test"},{"key": "D","text": "Froment's sign"}],"correct": "B","explanation": "Bunnel-Littler test: PIP flexion tested with MCP extended vs flexed — differentiates intrinsic from capsular tightness."},{"id": 517,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Stenosing tenosynovitis (trigger finger) most commonly affects which finger?","options": [{"key": "A","text": "Middle finger"},{"key": "B","text": "Index finger"},{"key": "C","text": "Ring finger"},{"key": "D","text": "Little finger"}],"correct": "C","explanation": "Trigger finger most commonly affects the ring finger, followed by the thumb (trigger thumb)."},{"id": 518,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Brachial plexus is formed by the ventral rami of which spinal segments?","options": [{"key": "A","text": "C4-C8"},{"key": "B","text": "C5-T2"},{"key": "C","text": "C4-T1"},{"key": "D","text": "C5-T1"}],"correct": "D","explanation": "Brachial plexus = C5, C6, C7, C8, T1 ventral rami."},{"id": 519,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which part of brachial plexus lies in the posterior triangle of neck?","options": [{"key": "A","text": "Divisions"},{"key": "B","text": "Cords"},{"key": "C","text": "Branches"},{"key": "D","text": "Trunks"}],"correct": "D","explanation": "3 trunks (upper, middle, lower) lie in posterior triangle of neck."},{"id": 520,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Upper trunk of brachial plexus is formed by:","options": [{"key": "A","text": "C6 & C7"},{"key": "B","text": "C5 & C6"},{"key": "C","text": "C5, C6 & C7"},{"key": "D","text": "C5 only"}],"correct": "B","explanation": "Upper trunk = C5 + C6; Middle trunk = C7; Lower trunk = C8 + T1."},{"id": 521,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Erb's point is located at:","options": [{"key": "A","text": "C4-C5 junction"},{"key": "B","text": "C6-C7 junction"},{"key": "C","text": "C5-C6 junction"},{"key": "D","text": "C7-T1 junction"}],"correct": "C","explanation": "Erb's point = junction of C5 & C6 roots; site of upper trunk of brachial plexus."},{"id": 522,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Erb's palsy results from injury to which roots of brachial plexus?","options": [{"key": "A","text": "C7, C8"},{"key": "B","text": "C6, C7"},{"key": "C","text": "C8, T1"},{"key": "D","text": "C5, C6"}],"correct": "D","explanation": "C5-C6 injury = Erb's palsy (waiter's tip position) — shoulder adducted, elbow extended."},{"id": 523,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Klumpke's palsy results from injury to:","options": [{"key": "A","text": "C5, C6"},{"key": "B","text": "C6, C7"},{"key": "C","text": "C8, T1"},{"key": "D","text": "C7, C8"}],"correct": "C","explanation": "C8-T1 injury = Klumpke's palsy — intrinsic hand muscle weakness, claw hand."},{"id": 524,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which cord of brachial plexus lies medial to axillary artery?","options": [{"key": "A","text": "Posterior cord"},{"key": "B","text": "All cords"},{"key": "C","text": "Medial cord"},{"key": "D","text": "Lateral cord"}],"correct": "C","explanation": "Medial cord is medial, lateral cord is lateral, posterior cord is posterior to axillary artery."},{"id": 525,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Posterior cord of brachial plexus is formed by:","options": [{"key": "A","text": "C5, C6, C7 posterior divisions"},{"key": "B","text": "Anterior divisions of all 3 trunks"},{"key": "C","text": "Posterior divisions of all 3 trunks"},{"key": "D","text": "C7, C8, T1 posterior divisions"}],"correct": "C","explanation": "Posterior cord = posterior divisions of all 3 trunks (C5–T1)."},{"id": 526,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which nerve arises directly from the roots of brachial plexus?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Long thoracic nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "B","explanation": "Long thoracic nerve (C5,C6,C7) arises directly from the roots, not cords."},{"id": 527,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Lateral cord of brachial plexus gives rise to all EXCEPT:","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Lateral pectoral nerve"},{"key": "C","text": "Medial root of median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Ulnar nerve arises from medial cord, not lateral cord."},{"id": 528,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Median nerve is formed by the union of:","options": [{"key": "A","text": "Posterior cord only"},{"key": "B","text": "Medial cord only"},{"key": "C","text": "Lateral and medial cords"},{"key": "D","text": "Lateral and posterior cords"}],"correct": "C","explanation": "Median nerve = lateral root (lateral cord C6,C7) + medial root (medial cord C8,T1)."},{"id": 529,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Median nerve enters forearm between which two heads of pronator teres?","options": [{"key": "A","text": "Radial and humeral heads"},{"key": "B","text": "Humeral and ulnar heads"},{"key": "C","text": "Radial and ulnar heads"},{"key": "D","text": "Superficial and deep heads"}],"correct": "B","explanation": "Median nerve passes between humeral and ulnar heads of pronator teres."},{"id": 530,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The Ape thumb deformity is associated with which nerve injury?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Median nerve"}],"correct": "D","explanation": "Median nerve injury → loss of thenar muscles → ape thumb (thumb lies in plane of palm)."},{"id": 531,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Carpal tunnel syndrome is due to compression of which nerve?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Anterior interosseous nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "C","explanation": "Median nerve is compressed under flexor retinaculum at carpal tunnel."},{"id": 532,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Palmar cutaneous branch of median nerve arises:","options": [{"key": "A","text": "Inside carpal tunnel"},{"key": "B","text": "Distal to carpal tunnel"},{"key": "C","text": "Proximal to carpal tunnel"},{"key": "D","text": "From ulnar nerve"}],"correct": "C","explanation": "Palmar cutaneous branch arises proximal to flexor retinaculum, so spared in carpal tunnel syndrome."},{"id": 533,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Anterior interosseous nerve (AIN) is a branch of:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "B","explanation": "AIN is a pure motor branch of median nerve in the forearm."},{"id": 534,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "AIN syndrome causes weakness of all EXCEPT:","options": [{"key": "A","text": "Flexor digitorum profundus (index)"},{"key": "B","text": "Pronator quadratus"},{"key": "C","text": "Flexor pollicis longus"},{"key": "D","text": "Opponens pollicis"}],"correct": "D","explanation": "Opponens pollicis is supplied by recurrent branch of median nerve, not AIN."},{"id": 535,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "LOAF muscles are supplied by median nerve. What does 'L' stand for?","options": [{"key": "A","text": "Lumbrical 1 & 2"},{"key": "B","text": "Lumbrical 1 only"},{"key": "C","text": "Lumbrical 3 & 4"},{"key": "D","text": "Lumbrical 2 only"}],"correct": "A","explanation": "LOAF = Lumbricals (1&2), Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis."},{"id": 536,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which test is used to test the integrity of median nerve at wrist?","options": [{"key": "A","text": "Phalen's test"},{"key": "B","text": "Froment's sign"},{"key": "C","text": "Finkelstein's test"},{"key": "D","text": "Allen's test"}],"correct": "A","explanation": "Phalen's test (wrist flexion for 60 sec) reproduces symptoms of carpal tunnel syndrome."},{"id": 537,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Benediction sign is seen in injury to which nerve?","options": [{"key": "A","text": "Ulnar nerve at wrist"},{"key": "B","text": "Median nerve at wrist"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Median nerve at elbow"}],"correct": "D","explanation": "High median nerve injury → benediction hand (index & middle fingers extended while ring & little flex)."},{"id": 538,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Ulnar nerve arises from which cord of brachial plexus?","options": [{"key": "A","text": "Both lateral and medial cords"},{"key": "B","text": "Posterior cord"},{"key": "C","text": "Medial cord"},{"key": "D","text": "Lateral cord"}],"correct": "C","explanation": "Ulnar nerve (C8, T1) arises from medial cord of brachial plexus."},{"id": 539,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Ulnar nerve passes through which groove at the elbow?","options": [{"key": "A","text": "Bicipital groove"},{"key": "B","text": "Olecranon fossa"},{"key": "C","text": "Radial groove"},{"key": "D","text": "Cubital tunnel (medial epicondyle groove)"}],"correct": "D","explanation": "Ulnar nerve passes posterior to medial epicondyle in cubital tunnel."},{"id": 540,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Ulnar nerve enters palm through:","options": [{"key": "A","text": "Guyon's canal"},{"key": "B","text": "Cubital tunnel"},{"key": "C","text": "Carpal tunnel"},{"key": "D","text": "Spiral groove"}],"correct": "A","explanation": "Ulnar nerve passes through Guyon's canal (ulnar canal) at wrist."},{"id": 541,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Claw hand deformity is most pronounced in:","options": [{"key": "A","text": "High median nerve lesion"},{"key": "B","text": "Low ulnar nerve lesion"},{"key": "C","text": "High ulnar nerve lesion"},{"key": "D","text": "Radial nerve lesion"}],"correct": "B","explanation": "Low ulnar nerve lesion → more pronounced claw (ring & little fingers) due to intact FDP."},{"id": 542,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Froment's sign tests the function of:","options": [{"key": "A","text": "Abductor pollicis brevis"},{"key": "B","text": "Adductor pollicis"},{"key": "C","text": "Opponens pollicis"},{"key": "D","text": "Flexor pollicis longus"}],"correct": "B","explanation": "Froment's sign tests adductor pollicis (ulnar nerve); positive = thumb IP flexion during paper grip."},{"id": 543,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Hypothenar muscles are supplied by:","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Hypothenar muscles (abductor, flexor, opponens digiti minimi) all supplied by ulnar nerve."},{"id": 544,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which muscle is NOT supplied by ulnar nerve?","options": [{"key": "A","text": "Adductor pollicis"},{"key": "B","text": "Flexor carpi ulnaris"},{"key": "C","text": "Palmaris longus"},{"key": "D","text": "Flexor digitorum profundus (ring & little)"}],"correct": "C","explanation": "Palmaris longus is supplied by median nerve, not ulnar nerve."},{"id": 545,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Ulnar paradox refers to:","options": [{"key": "A","text": "Less claw in high lesion"},{"key": "B","text": "Froment's sign reversal"},{"key": "C","text": "More claw in high lesion"},{"key": "D","text": "More claw in radial lesion"}],"correct": "A","explanation": "In high ulnar lesion, FDP also paralysed → less claw deformity (ulnar paradox)."},{"id": 546,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Dorsal cutaneous branch of ulnar nerve arises:","options": [{"key": "A","text": "At medial epicondyle"},{"key": "B","text": "In palm"},{"key": "C","text": "5 cm proximal to wrist"},{"key": "D","text": "Inside Guyon's canal"}],"correct": "C","explanation": "Dorsal cutaneous branch arises ~5 cm proximal to wrist, so spared in Guyon's canal compression."},{"id": 547,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Wartenberg's sign is a feature of:","options": [{"key": "A","text": "Radial nerve injury"},{"key": "B","text": "Median nerve injury"},{"key": "C","text": "Musculocutaneous injury"},{"key": "D","text": "Ulnar nerve injury"}],"correct": "D","explanation": "Wartenberg's sign = abducted little finger due to unopposed extensor digiti minimi in ulnar palsy."},{"id": 548,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Radial nerve arises from which cord of brachial plexus?","options": [{"key": "A","text": "Posterior cord"},{"key": "B","text": "Medial cord"},{"key": "C","text": "Lateral cord"},{"key": "D","text": "Both lateral and medial"}],"correct": "A","explanation": "Radial nerve (C5-T1) is the largest branch of posterior cord."},{"id": 549,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Radial nerve winds around the humerus in which groove?","options": [{"key": "A","text": "Bicipital groove"},{"key": "B","text": "Cubital groove"},{"key": "C","text": "Spiral (radial) groove"},{"key": "D","text": "Olecranon groove"}],"correct": "C","explanation": "Radial nerve lies in the spiral groove (radial groove) of humerus — site of injury in midshaft humeral fractures."},{"id": 550,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Wrist drop is a feature of injury to:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Median nerve"}],"correct": "B","explanation": "Radial nerve injury → paralysis of wrist extensors → wrist drop."},{"id": 551,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Deep branch of radial nerve is also known as:","options": [{"key": "A","text": "Lateral cutaneous nerve"},{"key": "B","text": "Posterior interosseous nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Anterior interosseous nerve"}],"correct": "B","explanation": "Deep branch of radial nerve = Posterior Interosseous Nerve (PIN) — purely motor."},{"id": 552,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Superficial branch of radial nerve is:","options": [{"key": "A","text": "Purely sensory"},{"key": "B","text": "Purely motor"},{"key": "C","text": "Autonomic"},{"key": "D","text": "Mixed"}],"correct": "A","explanation": "Superficial radial nerve is purely sensory — supplies dorsum of hand (lateral 3½ digits)."},{"id": 553,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Saturday night palsy involves which nerve and level?","options": [{"key": "A","text": "Radial nerve in axilla"},{"key": "B","text": "Median nerve at elbow"},{"key": "C","text": "Radial nerve in spiral groove"},{"key": "D","text": "Ulnar nerve at wrist"}],"correct": "C","explanation": "Saturday night palsy = radial nerve compressed in spiral groove (arm draped over chair)."},{"id": 554,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In crutch palsy, radial nerve is damaged at:","options": [{"key": "A","text": "Axilla"},{"key": "B","text": "Posterior cord"},{"key": "C","text": "Lateral epicondyle"},{"key": "D","text": "Spiral groove"}],"correct": "A","explanation": "Crutch palsy → radial nerve compressed at axilla by crutch top."},{"id": 555,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Posterior interosseous nerve (PIN) syndrome spares which muscle?","options": [{"key": "A","text": "Extensor carpi radialis longus (ECRL)"},{"key": "B","text": "Extensor pollicis longus"},{"key": "C","text": "Extensor digitorum"},{"key": "D","text": "Extensor carpi ulnaris"}],"correct": "A","explanation": "ECRL is supplied by radial nerve before it bifurcates, so spared in PIN syndrome."},{"id": 556,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Triceps is spared in which radial nerve injury?","options": [{"key": "A","text": "Axillary injury"},{"key": "B","text": "Spiral groove injury"},{"key": "C","text": "Lateral epicondyle injury"},{"key": "D","text": "Posterior cord injury"}],"correct": "B","explanation": "Triceps branch arises proximal to spiral groove; mid-humeral fracture spares triceps."},{"id": 557,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Radial nerve supplies the skin of dorsum of hand over how many digits?","options": [{"key": "A","text": "3½ digits"},{"key": "B","text": "All 5 digits"},{"key": "C","text": "2½ digits"},{"key": "D","text": "4 digits"}],"correct": "A","explanation": "Radial nerve (superficial branch) supplies dorsum of lateral 3½ digits (thumb, index, middle, half ring)."},{"id": 558,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Musculocutaneous nerve is a branch of which cord?","options": [{"key": "A","text": "Lateral cord"},{"key": "B","text": "All cords"},{"key": "C","text": "Posterior cord"},{"key": "D","text": "Medial cord"}],"correct": "A","explanation": "Musculocutaneous nerve (C5,C6,C7) is a branch of the lateral cord."},{"id": 559,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which nerve is most commonly injured in anterior dislocation of shoulder?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Axillary nerve"}],"correct": "D","explanation": "Axillary nerve winds around surgical neck of humerus — injured in shoulder dislocation/surgical neck fracture."},{"id": 560,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "'Pen test' or 'OK sign' tests integrity of:","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Median nerve — AIN"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "B","explanation": "AIN (branch of median nerve) is tested by making OK sign — FPL and FDP index finger."},{"id": 561,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In high radial nerve palsy, which movement is preserved?","options": [{"key": "A","text": "Finger extension"},{"key": "B","text": "Wrist extension"},{"key": "C","text": "Elbow flexion"},{"key": "D","text": "Elbow extension"}],"correct": "C","explanation": "Elbow flexion is by musculocutaneous nerve (biceps/brachialis), unaffected in radial nerve injury."},{"id": 562,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which nerve injury causes loss of sensation over the anatomical snuffbox?","options": [{"key": "A","text": "Superficial radial nerve"},{"key": "B","text": "Anterior interosseous nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "A","explanation": "Anatomical snuffbox sensory supply = superficial branch of radial nerve."},{"id": 563,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Sensory loss on medial 1½ fingers (palmar) indicates injury to:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Radial nerve"}],"correct": "A","explanation": "Ulnar nerve supplies palmar aspect of medial 1½ fingers (little + medial ring)."},{"id": 564,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which nerve injury results in loss of elbow flexion?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "D","explanation": "Musculocutaneous nerve supplies biceps brachii and brachialis — main elbow flexors."},{"id": 565,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Lateral cutaneous nerve of forearm is the cutaneous continuation of:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Radial nerve"}],"correct": "C","explanation": "Musculocutaneous nerve pierces deep fascia and continues as lateral cutaneous nerve of forearm."},{"id": 566,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In lower trunk (C8,T1) injury, which feature is SEEN?","options": [{"key": "A","text": "Loss of elbow flexion"},{"key": "B","text": "Wrist drop"},{"key": "C","text": "Claw hand with intrinsic weakness"},{"key": "D","text": "Loss of shoulder abduction"}],"correct": "C","explanation": "Lower trunk = Klumpke's palsy — intrinsic hand muscle weakness, claw hand, Horner's syndrome."},{"id": 567,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The 'gun stock deformity' (cubitus varus) most likely injures which nerve?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Radial nerve"}],"correct": "C","explanation": "Cubitus varus (malunited supracondylar fracture) causes delayed ulnar nerve palsy due to stretching."},{"id": 568,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which of the following muscles is supplied by BOTH median and ulnar nerves?","options": [{"key": "A","text": "Flexor digitorum profundus"},{"key": "B","text": "Opponens pollicis"},{"key": "C","text": "Flexor carpi ulnaris"},{"key": "D","text": "Flexor digitorum superficialis"}],"correct": "A","explanation": "FDP medial half (ring & little) = ulnar nerve; FDP lateral half (index & middle) = median nerve."},{"id": 569,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which nerve arises from the upper trunk of brachial plexus?","options": [{"key": "A","text": "Long thoracic nerve"},{"key": "B","text": "Nerve to subclavius"},{"key": "C","text": "Suprascapular nerve"},{"key": "D","text": "Both A and B"}],"correct": "D","explanation": "Upper trunk gives: suprascapular nerve + nerve to subclavius."},{"id": 570,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Thoracodorsal nerve supplies which muscle?","options": [{"key": "A","text": "Serratus anterior"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Pectoralis major"},{"key": "D","text": "Latissimus dorsi"}],"correct": "D","explanation": "Thoracodorsal nerve (C6,C7,C8) from posterior cord supplies latissimus dorsi."},{"id": 571,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Injury to long thoracic nerve causes:","options": [{"key": "A","text": "Winging of scapula"},{"key": "B","text": "Claw hand"},{"key": "C","text": "Shoulder dislocation"},{"key": "D","text": "Wrist drop"}],"correct": "A","explanation": "Long thoracic nerve → serratus anterior → paralysis causes medial winging of scapula."},{"id": 572,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which nerve supplies teres minor?","options": [{"key": "A","text": "Suprascapular nerve"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Lower subscapular nerve"}],"correct": "B","explanation": "Axillary nerve (C5,C6) supplies teres minor and deltoid."},{"id": 573,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Medial pectoral nerve arises from:","options": [{"key": "A","text": "Posterior cord"},{"key": "B","text": "Lateral cord"},{"key": "C","text": "Medial cord"},{"key": "D","text": "Upper trunk"}],"correct": "C","explanation": "Medial pectoral nerve (C8,T1) arises from medial cord; lateral pectoral from lateral cord."},{"id": 574,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which cord gives rise to both ulnar nerve and medial cutaneous nerves of arm and forearm?","options": [{"key": "A","text": "Medial cord"},{"key": "B","text": "Lateral cord"},{"key": "C","text": "Upper trunk"},{"key": "D","text": "Posterior cord"}],"correct": "A","explanation": "Medial cord → ulnar nerve, medial cutaneous nerve of arm, medial cutaneous nerve of forearm."},{"id": 575,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Horner's syndrome in brachial plexus injury indicates involvement of:","options": [{"key": "A","text": "Posterior cord"},{"key": "B","text": "Upper trunk (C5,C6)"},{"key": "C","text": "Middle trunk (C7)"},{"key": "D","text": "Lower trunk (C8,T1)"}],"correct": "D","explanation": "T1 root carries sympathetic fibres; lower trunk injury can cause Horner's syndrome."},{"id": 576,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "'Policeman's tip' posture is seen in:","options": [{"key": "A","text": "Erb's palsy"},{"key": "B","text": "Klumpke's palsy"},{"key": "C","text": "PIN syndrome"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "A","explanation": "Erb's palsy → shoulder adducted & internally rotated, elbow extended, forearm pronated = waiter's/policeman's tip."},{"id": 577,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which muscle is supplied by dorsal scapular nerve?","options": [{"key": "A","text": "Rhomboids"},{"key": "B","text": "Supraspinatus"},{"key": "C","text": "Infraspinatus"},{"key": "D","text": "Serratus anterior"}],"correct": "A","explanation": "Dorsal scapular nerve (C5) supplies rhomboids major, minor and levator scapulae."},{"id": 578,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The medial root of median nerve carries fibres from:","options": [{"key": "A","text": "C5, C6"},{"key": "B","text": "C7, C8"},{"key": "C","text": "C8, T1"},{"key": "D","text": "C6, C7"}],"correct": "C","explanation": "Medial root of median nerve = C8,T1 from medial cord; lateral root = C6,C7 from lateral cord."},{"id": 579,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor digitorum superficialis is supplied by which nerve?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Anterior interosseous nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Median nerve"}],"correct": "D","explanation": "FDS is supplied by median nerve in the forearm (not AIN)."},{"id": 580,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "In carpal tunnel syndrome, which test has highest sensitivity?","options": [{"key": "A","text": "Phalen's test"},{"key": "B","text": "Durkan's compression test"},{"key": "C","text": "Tinel's sign"},{"key": "D","text": "Reverse Phalen's test"}],"correct": "B","explanation": "Durkan's carpal compression test has highest sensitivity (~87%) for CTS."},{"id": 581,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Median nerve innervates all of the following in the hand EXCEPT:","options": [{"key": "A","text": "Flexor pollicis brevis (superficial head)"},{"key": "B","text": "Abductor pollicis brevis"},{"key": "C","text": "Opponens pollicis"},{"key": "D","text": "Adductor pollicis"}],"correct": "D","explanation": "Adductor pollicis is supplied by deep branch of ulnar nerve, not median nerve."},{"id": 582,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Pronator syndrome is compression of median nerve between heads of:","options": [{"key": "A","text": "Supinator"},{"key": "B","text": "Pronator teres"},{"key": "C","text": "Flexor digitorum superficialis"},{"key": "D","text": "Flexor carpi radialis"}],"correct": "B","explanation": "Pronator syndrome = median nerve compressed between humeral and ulnar heads of pronator teres."},{"id": 583,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Which finger is NOT affected in median nerve sensory loss at wrist?","options": [{"key": "A","text": "Index finger"},{"key": "B","text": "Little finger"},{"key": "C","text": "Thumb"},{"key": "D","text": "Middle finger"}],"correct": "B","explanation": "Median nerve supplies palmar aspect of lateral 3½ digits; little finger (medial 1½) = ulnar nerve."},{"id": 584,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Recurrent (thenar) branch of median nerve arises:","options": [{"key": "A","text": "Distal to flexor retinaculum"},{"key": "B","text": "Proximal to carpal tunnel"},{"key": "C","text": "From AIN"},{"key": "D","text": "Inside carpal tunnel"}],"correct": "A","explanation": "Recurrent branch arises just distal to flexor retinaculum and hooks back to supply thenar muscles."},{"id": 585,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "The functional loss most disabling in median nerve injury at wrist is:","options": [{"key": "A","text": "Loss of elbow flexion"},{"key": "B","text": "Loss of finger extension"},{"key": "C","text": "Loss of thumb opposition"},{"key": "D","text": "Loss of wrist flexion"}],"correct": "C","explanation": "Thumb opposition (opponens pollicis) is the most functionally important movement lost in median nerve injury."},{"id": 586,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor pollicis longus is supplied by:","options": [{"key": "A","text": "Recurrent branch of median nerve"},{"key": "B","text": "Median nerve (main trunk)"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Anterior interosseous nerve"}],"correct": "D","explanation": "FPL is exclusively supplied by AIN (branch of median nerve) in the forearm."},{"id": 587,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Lumbrical muscles 3 and 4 are supplied by:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Both median and ulnar"}],"correct": "A","explanation": "Lumbricals 1&2 = median nerve; Lumbricals 3&4 = deep branch of ulnar nerve."},{"id": 588,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "In high median nerve lesion at elbow, which movement is PRESERVED?","options": [{"key": "A","text": "Thumb flexion (FPL)"},{"key": "B","text": "Ring finger flexion (FDP)"},{"key": "C","text": "Index finger flexion (FDP)"},{"key": "D","text": "Wrist flexion by FCR"}],"correct": "B","explanation": "Ring & little FDP = ulnar nerve; so ring finger flexion preserved in median nerve lesion."},{"id": 589,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor carpi ulnaris is tested by:","options": [{"key": "A","text": "Wrist extension against resistance"},{"key": "B","text": "Thumb opposition"},{"key": "C","text": "Finger abduction"},{"key": "D","text": "Wrist flexion with ulnar deviation"}],"correct": "D","explanation": "FCU (ulnar nerve) causes wrist flexion with ulnar deviation."},{"id": 590,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which intrinsic hand muscles are supplied by ulnar nerve? (Select best answer)","options": [{"key": "A","text": "All interossei + medial 2 lumbricals + hypothenar"},{"key": "B","text": "All interossei only"},{"key": "C","text": "All lumbricals + thenar"},{"key": "D","text": "Thenar + hypothenar"}],"correct": "A","explanation": "Ulnar nerve supplies: all 7 interossei, lumbricals 3&4, all hypothenar muscles, adductor pollicis, deep head FPB."},{"id": 591,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In Guyon's canal, the ulnar nerve divides into:","options": [{"key": "A","text": "Motor and sensory branches"},{"key": "B","text": "Medial and lateral branches"},{"key": "C","text": "Dorsal and palmar branches"},{"key": "D","text": "Superficial and deep branches"}],"correct": "D","explanation": "In Guyon's canal, ulnar nerve divides into superficial (sensory) and deep (motor) branches."},{"id": 592,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Card test (Egawa's test) assesses function of:","options": [{"key": "A","text": "Opponens digiti minimi"},{"key": "B","text": "Dorsal interossei"},{"key": "C","text": "Lumbrical 3 & 4"},{"key": "D","text": "Adductor pollicis"}],"correct": "B","explanation": "Card test (holding card between fingers) tests dorsal interossei — finger abduction — ulnar nerve."},{"id": 593,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In ulnar nerve injury, the interossei are paralyzed causing loss of:","options": [{"key": "A","text": "Finger abduction and adduction (DAB, PAD)"},{"key": "B","text": "Wrist extension"},{"key": "C","text": "Thumb flexion"},{"key": "D","text": "Finger flexion"}],"correct": "A","explanation": "Dorsal interossei = ABduct (DAB); Palmar interossei = ADduct (PAD) — both paralyzed in ulnar nerve injury."},{"id": 594,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Cubital tunnel syndrome is compression of ulnar nerve at:","options": [{"key": "A","text": "Wrist (Guyon's canal)"},{"key": "B","text": "Spiral groove"},{"key": "C","text": "Elbow (medial epicondyle)"},{"key": "D","text": "Axilla"}],"correct": "C","explanation": "Cubital tunnel syndrome = ulnar nerve compressed at elbow, most common site of ulnar nerve entrapment."},{"id": 595,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "In ulnar nerve lesion, sensory loss on dorsum of hand means lesion is:","options": [{"key": "A","text": "At wrist (Guyon's canal)"},{"key": "B","text": "Distal to dorsal cutaneous branch"},{"key": "C","text": "Inside carpal tunnel"},{"key": "D","text": "At or proximal to mid-forearm"}],"correct": "D","explanation": "Dorsal cutaneous branch arises 5 cm proximal to wrist; its involvement indicates lesion at/above mid-forearm."},{"id": 596,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which deformity is MORE pronounced in LOW ulnar nerve lesion?","options": [{"key": "A","text": "Winging of scapula"},{"key": "B","text": "Wrist drop"},{"key": "C","text": "Claw hand"},{"key": "D","text": "Ape thumb"}],"correct": "C","explanation": "Low lesion → FDP intact → stronger pull on ring & little fingers → more pronounced claw (ulnar paradox)."},{"id": 597,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Adductor pollicis is tested clinically by:","options": [{"key": "A","text": "Phalen's test"},{"key": "B","text": "Pen test"},{"key": "C","text": "Pinch grip strength"},{"key": "D","text": "Froment's sign"}],"correct": "D","explanation": "Froment's sign tests adductor pollicis — patient uses FPL (median) to compensate when holding paper."},{"id": 598,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Rider's palsy / handlebar neuropathy is compression of:","options": [{"key": "A","text": "Radial nerve at spiral groove"},{"key": "B","text": "PIN at arcade of Frohse"},{"key": "C","text": "Ulnar nerve at Guyon's canal"},{"key": "D","text": "Median nerve at wrist"}],"correct": "C","explanation": "Cyclist's palsy / handlebar palsy = ulnar nerve compression at Guyon's canal due to prolonged cycling."},{"id": 599,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Arcade of Frohse is the site of compression of:","options": [{"key": "A","text": "Anterior interosseous nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Superficial radial nerve"},{"key": "D","text": "Posterior interosseous nerve"}],"correct": "D","explanation": "Arcade of Frohse = fibrous arch of supinator — compresses PIN (deep branch of radial nerve)."},{"id": 600,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "In radial nerve injury at spiral groove, which movement is SPARED?","options": [{"key": "A","text": "Finger extension"},{"key": "B","text": "Elbow extension (triceps)"},{"key": "C","text": "Thumb extension"},{"key": "D","text": "Wrist extension"}],"correct": "B","explanation": "Triceps branch arises proximal to spiral groove → elbow extension preserved in midshaft humeral fracture."},{"id": 601,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The radial nerve is most commonly injured in fracture of:","options": [{"key": "A","text": "Lateral epicondyle"},{"key": "B","text": "Radial head"},{"key": "C","text": "Surgical neck of humerus"},{"key": "D","text": "Midshaft of humerus"}],"correct": "D","explanation": "Radial nerve lies in spiral groove at midshaft humerus — most common site of injury."},{"id": 602,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Cheiralgia paresthetica is compression of which nerve?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Superficial radial nerve"},{"key": "D","text": "Lateral cutaneous nerve of forearm"}],"correct": "C","explanation": "Cheiralgia paresthetica (Wartenberg's syndrome) = compression of superficial radial nerve at wrist."},{"id": 603,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Brachioradialis is supplied by radial nerve. It acts as:","options": [{"key": "A","text": "Elbow extensor"},{"key": "B","text": "Forearm supinator"},{"key": "C","text": "Wrist extensor"},{"key": "D","text": "Weak elbow flexor in mid-prone position"}],"correct": "D","explanation": "Brachioradialis flexes the elbow, especially in mid-prone position (between full pronation and supination)."},{"id": 604,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "In PIN (posterior interosseous nerve) palsy, wrist extension is:","options": [{"key": "A","text": "Normal"},{"key": "B","text": "Replaced by ulnar deviation"},{"key": "C","text": "Partially preserved (radial deviation)"},{"key": "D","text": "Completely lost"}],"correct": "C","explanation": "ECRL (radial nerve, proximal to PIN) preserved → wrist extends with radial deviation; ECU (PIN) paralyzed."},{"id": 605,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Radial nerve at axilla injury additionally loses which function compared to spiral groove injury?","options": [{"key": "A","text": "Finger extension"},{"key": "B","text": "Triceps function"},{"key": "C","text": "Wrist extension"},{"key": "D","text": "Brachioradialis"}],"correct": "B","explanation": "Triceps branch arises above spiral groove; axillary injury additionally paralyzes triceps."},{"id": 606,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Tennis elbow (lateral epicondylitis) must be differentiated from:","options": [{"key": "A","text": "CTS"},{"key": "B","text": "PIN entrapment at radial tunnel"},{"key": "C","text": "Guyon's canal syndrome"},{"key": "D","text": "Cubital tunnel syndrome"}],"correct": "B","explanation": "Radial tunnel syndrome (PIN entrapment) mimics tennis elbow — point tenderness 4 cm distal to lateral epicondyle."},{"id": 607,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Extensor pollicis longus is supplied by:","options": [{"key": "A","text": "Posterior interosseous nerve (PIN)"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Anterior interosseous nerve"},{"key": "D","text": "Superficial radial nerve"}],"correct": "A","explanation": "EPL, EPB, APL, EIP, EDC, ECU — all supplied by PIN (deep branch of radial nerve)."},{"id": 608,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Sensory supply of the first web space on dorsum of hand is by:","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Superficial radial nerve"},{"key": "C","text": "Ulnar nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "B","explanation": "First web space (dorsal) = superficial branch of radial nerve — useful to test in radial nerve lesions."},{"id": 609,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Intrinsic plus deformity refers to:","options": [{"key": "A","text": "MCP extension + IP flexion"},{"key": "B","text": "MCP flexion + IP extension"},{"key": "C","text": "MCP flexion + IP flexion"},{"key": "D","text": "MCP extension + IP extension"}],"correct": "B","explanation": "Intrinsic plus = lumbricals/interossei overactive → MCP flexion + IP extension (opposite of claw)."},{"id": 610,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which nerve is tested by resisted forearm supination with elbow at 90°?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "D","explanation": "Biceps brachii (musculocutaneous nerve) is the primary supinator with elbow at 90°."},{"id": 611,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Boutonniére deformity involves which structures primarily?","options": [{"key": "A","text": "FDS + FDP"},{"key": "B","text": "Lateral bands + collateral ligaments"},{"key": "C","text": "Central slip of extensor tendon + volar plate"},{"key": "D","text": "Interossei + lumbricals"}],"correct": "C","explanation": "Boutonnière = rupture of central slip → PIP flexion + DIP hyperextension."},{"id": 612,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Injury to medial cord of brachial plexus causes loss of BOTH:","options": [{"key": "A","text": "Median and radial nerve functions"},{"key": "B","text": "Median (partial) and ulnar nerve functions"},{"key": "C","text": "Musculocutaneous and radial functions"},{"key": "D","text": "Ulnar and radial nerve functions"}],"correct": "B","explanation": "Medial cord gives ulnar nerve + medial root of median nerve (C8,T1) — both affected in medial cord injury."},{"id": 613,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Posterior cord injury causes loss of all EXCEPT:","options": [{"key": "A","text": "Elbow flexion"},{"key": "B","text": "Elbow extension (triceps)"},{"key": "C","text": "Wrist and finger extension"},{"key": "D","text": "Shoulder abduction (deltoid)"}],"correct": "A","explanation": "Elbow flexion (biceps/brachialis) = musculocutaneous nerve (lateral cord) — not affected in posterior cord lesion."},{"id": 614,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which nerve supplies the first dorsal interosseous muscle?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Deep branch of ulnar nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Superficial ulnar nerve"}],"correct": "B","explanation": "All interossei (including 1st dorsal interosseous) are supplied by deep branch of ulnar nerve."},{"id": 615,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Pinch grip is mainly tested for:","options": [{"key": "A","text": "Both median and ulnar"},{"key": "B","text": "Radial nerve — EPL"},{"key": "C","text": "Ulnar nerve — adductor pollicis"},{"key": "D","text": "Median nerve — opponens pollicis"}],"correct": "A","explanation": "Normal pinch requires median nerve (APB, opponens) + ulnar nerve (adductor pollicis) working together."},{"id": 616,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The most common site of ulnar nerve entrapment is:","options": [{"key": "A","text": "Axilla"},{"key": "B","text": "Elbow (cubital tunnel)"},{"key": "C","text": "Thoracic outlet"},{"key": "D","text": "Wrist (Guyon's canal)"}],"correct": "B","explanation": "Cubital tunnel (elbow) is the most common site of ulnar nerve entrapment."},{"id": 617,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Which nerve injury produces a 'pointing index finger' on making a fist?","options": [{"key": "A","text": "Median nerve at elbow"},{"key": "B","text": "Ulnar nerve at wrist"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "AIN injury"}],"correct": "D","explanation": "AIN injury → FPL + FDP index paralysis → patient cannot flex index DIP or thumb IP when making fist."},{"id": 618,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In thoracic outlet syndrome, which trunk is most commonly compressed?","options": [{"key": "A","text": "All trunks equally"},{"key": "B","text": "Upper trunk (C5,C6)"},{"key": "C","text": "Middle trunk (C7)"},{"key": "D","text": "Lower trunk (C8,T1)"}],"correct": "D","explanation": "Lower trunk (C8,T1) is most vulnerable in thoracic outlet syndrome — causes hand intrinsic weakness."},{"id": 619,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The nerve to subclavius is clinically important because it may provide accessory supply to:","options": [{"key": "A","text": "Biceps brachii"},{"key": "B","text": "Phrenic nerve (C5 anastomosis)"},{"key": "C","text": "Serratus anterior"},{"key": "D","text": "Deltoid"}],"correct": "B","explanation": "Nerve to subclavius may anastomose with phrenic nerve — important in cervical root avulsion surgeries."},{"id": 620,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which muscle is the primary knee extensor?","options": [{"key": "A","text": "Rectus femoris"},{"key": "B","text": "Biceps femoris"},{"key": "C","text": "Sartorius"},{"key": "D","text": "Gracilis"}],"correct": "A","explanation": "Rectus femoris is the only quadriceps muscle that crosses both hip and knee joints, making it primary knee extensor."},{"id": 621,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "How many heads does the quadriceps femoris have?","options": [{"key": "A","text": "Two"},{"key": "B","text": "Four"},{"key": "C","text": "Three"},{"key": "D","text": "Five"}],"correct": "B","explanation": "Quadriceps femoris has four heads: rectus femoris, vastus lateralis, vastus medialis, and vastus intermedius."},{"id": 622,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The quadriceps muscle inserts into which structure?","options": [{"key": "A","text": "Lateral condyle of femur"},{"key": "B","text": "Medial condyle of tibia"},{"key": "C","text": "Fibular head"},{"key": "D","text": "Tibial tuberosity via patellar tendon"}],"correct": "D","explanation": "All four quadriceps heads converge into the quadriceps tendon, which continues as the patellar tendon inserting into tibial tuberosity."},{"id": 623,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Vastus medialis oblique (VMO) is primarily responsible for:","options": [{"key": "A","text": "Knee flexion"},{"key": "B","text": "Hip flexion"},{"key": "C","text": "Full knee extension"},{"key": "D","text": "Last 15-20 degrees of knee extension"}],"correct": "D","explanation": "VMO is critical for the final 15-20 degrees of knee extension and patellar stabilization."},{"id": 624,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which nerve innervates the quadriceps femoris?","options": [{"key": "A","text": "Common peroneal nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Femoral nerve"},{"key": "D","text": "Sciatic nerve"}],"correct": "C","explanation": "Femoral nerve (L2, L3, L4) innervates all four heads of quadriceps femoris."},{"id": 625,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Rectus femoris originates from:","options": [{"key": "A","text": "Lesser trochanter"},{"key": "B","text": "Anterior inferior iliac spine (AIIS)"},{"key": "C","text": "Ischial tuberosity"},{"key": "D","text": "Greater trochanter"}],"correct": "B","explanation": "Rectus femoris has two heads: straight head from AIIS and reflected head from acetabular ridge."},{"id": 626,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which quadriceps muscle does NOT cross the hip joint?","options": [{"key": "A","text": "Vastus lateralis"},{"key": "B","text": "Both B and C"},{"key": "C","text": "None of these"},{"key": "D","text": "Rectus femoris"}],"correct": "B","explanation": "Vastus lateralis, vastus medialis, and vastus intermedius originate from the femur and only cross the knee joint."},{"id": 627,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The Q-angle is measured between:","options": [{"key": "A","text": "Hip and knee axis"},{"key": "B","text": "Femur and tibia"},{"key": "C","text": "Quadriceps line and patellar tendon"},{"key": "D","text": "ASIS to patella center and patella center to tibial tuberosity"}],"correct": "D","explanation": "Q-angle is the angle formed by a line from ASIS to patella center and patella center to tibial tuberosity; normal is 10-15 degrees."},{"id": 628,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Vastus intermedius originates from:","options": [{"key": "A","text": "Anterior and lateral femoral surface"},{"key": "B","text": "Posterior femoral surface"},{"key": "C","text": "Medial femoral surface"},{"key": "D","text": "Lateral femoral surface"}],"correct": "A","explanation": "Vastus intermedius originates from the anterior and lateral surfaces of the femoral shaft."},{"id": 629,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "In knee extension, the screw-home mechanism involves:","options": [{"key": "A","text": "Lateral rotation of tibia"},{"key": "B","text": "Medial rotation of tibia"},{"key": "C","text": "Medial rotation of femur on fixed tibia"},{"key": "D","text": "Lateral rotation of femur"}],"correct": "A","explanation": "During terminal knee extension (open kinetic chain), tibia laterally rotates to lock the knee - called screw-home mechanism."},{"id": 630,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which quadriceps muscle has oblique fiber orientation most important for patellar tracking?","options": [{"key": "A","text": "Vastus medialis oblique"},{"key": "B","text": "Rectus femoris"},{"key": "C","text": "Vastus intermedius"},{"key": "D","text": "Vastus lateralis"}],"correct": "A","explanation": "VMO's oblique fibers (50-55 degrees) pull patella medially, counteracting lateral pull of vastus lateralis."},{"id": 631,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Peak torque of quadriceps is produced at approximately:","options": [{"key": "A","text": "90 degrees of knee flexion"},{"key": "B","text": "30-60 degrees of knee flexion"},{"key": "C","text": "120 degrees of knee flexion"},{"key": "D","text": "Full extension (0 degrees)"}],"correct": "B","explanation": "Quadriceps produce maximum torque between 30-60 degrees of knee flexion due to optimal length-tension relationship."},{"id": 632,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The blood supply to quadriceps is primarily from:","options": [{"key": "A","text": "Lateral circumflex femoral artery"},{"key": "B","text": "Popliteal artery"},{"key": "C","text": "Femoral artery and its branches"},{"key": "D","text": "Obturator artery"}],"correct": "C","explanation": "Quadriceps is primarily supplied by the femoral artery and its muscular branches, including lateral circumflex femoral artery."},{"id": 633,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Rectus femoris acts as a hip flexor due to its origin at:","options": [{"key": "A","text": "Iliac crest"},{"key": "B","text": "Pubic symphysis"},{"key": "C","text": "ASIS"},{"key": "D","text": "AIIS"}],"correct": "D","explanation": "Rectus femoris originates at AIIS, anterior to the hip joint axis, allowing it to flex the hip."},{"id": 634,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In open kinetic chain, quadriceps contraction produces:","options": [{"key": "A","text": "Hip extension"},{"key": "B","text": "Knee flexion"},{"key": "C","text": "Knee extension with tibial movement"},{"key": "D","text": "Tibial internal rotation"}],"correct": "C","explanation": "In open kinetic chain, distal segment (tibia) moves; quadriceps contraction extends the knee by moving tibia forward."},{"id": 635,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The quadriceps-to-hamstring strength ratio (Q:H ratio) normal value is approximately:","options": [{"key": "A","text": "2:1"},{"key": "B","text": "1:2"},{"key": "C","text": "1:1"},{"key": "D","text": "3:1"}],"correct": "A","explanation": "Normal Q:H ratio is approximately 2:1 (60:30 Nm), though values between 1.5:1 to 2.5:1 are considered acceptable."},{"id": 636,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Vastus lateralis originates from:","options": [{"key": "A","text": "Greater trochanter only"},{"key": "B","text": "Femoral neck"},{"key": "C","text": "Intertrochanteric line and lateral lip of linea aspera"},{"key": "D","text": "Medial lip of linea aspera"}],"correct": "C","explanation": "Vastus lateralis originates from the intertrochanteric line, greater trochanter, and lateral lip of linea aspera."},{"id": 637,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which condition is associated with VMO weakness and patellar maltracking?","options": [{"key": "A","text": "Iliotibial band syndrome"},{"key": "B","text": "Meniscal tear"},{"key": "C","text": "Hamstring strain"},{"key": "D","text": "Patellofemoral pain syndrome"}],"correct": "D","explanation": "Weak VMO causes lateral patellar tracking, leading to patellofemoral pain syndrome due to increased lateral compression."},{"id": 638,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "The patellar reflex tests which spinal cord level?","options": [{"key": "A","text": "L4-L5"},{"key": "B","text": "L1-L2"},{"key": "C","text": "L3-L4"},{"key": "D","text": "L2-L3"}],"correct": "C","explanation": "The patellar (knee jerk) reflex tests the L3-L4 spinal cord levels via the femoral nerve."},{"id": 639,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "During closed kinetic chain squat, quadriceps work is greatest at:","options": [{"key": "A","text": "0-30 degrees flexion"},{"key": "B","text": "60-90 degrees flexion"},{"key": "C","text": "Beyond 90 degrees"},{"key": "D","text": "Full extension"}],"correct": "B","explanation": "Quadriceps work is greatest at 60-90 degrees during squat as the moment arm and compressive forces are highest."},{"id": 640,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Eccentric quadriceps contraction is used in treatment of:","options": [{"key": "A","text": "Patellar tendinopathy"},{"key": "B","text": "Plantar fasciitis"},{"key": "C","text": "Hip bursitis"},{"key": "D","text": "Achilles tendinopathy"}],"correct": "A","explanation": "Eccentric quadriceps loading (e.g., decline squat) is the gold standard for patellar tendinopathy rehabilitation."},{"id": 641,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The femoral triangle contains the femoral nerve, artery, and vein in which order (lateral to medial)?","options": [{"key": "A","text": "Nerve, artery, vein"},{"key": "B","text": "Nerve, vein, artery"},{"key": "C","text": "Vein, artery, nerve"},{"key": "D","text": "Artery, vein, nerve"}],"correct": "A","explanation": "From lateral to medial: Nerve, Artery, Vein - remembered by acronym NAVY (Nerve, Artery, Vein)."},{"id": 642,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Rectus femoris tightness test is performed by:","options": [{"key": "A","text": "Thomas test"},{"key": "B","text": "FABER test"},{"key": "C","text": "Ely's test"},{"key": "D","text": "Ober's test"}],"correct": "C","explanation": "Ely's test (prone knee flexion test) assesses rectus femoris tightness; positive if hip rises from table."},{"id": 643,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which quadriceps exercise provides maximum VMO activation with minimal patellofemoral stress?","options": [{"key": "A","text": "Terminal knee extension"},{"key": "B","text": "Leg press at 90 degrees"},{"key": "C","text": "Deep squat"},{"key": "D","text": "Full arc extension"}],"correct": "A","explanation": "Terminal knee extension (0-30 degrees) maximally activates VMO with least patellofemoral joint compression."},{"id": 644,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Quadriceps cross-sectional area is largest in which muscle?","options": [{"key": "A","text": "Vastus intermedius"},{"key": "B","text": "Rectus femoris"},{"key": "C","text": "Vastus medialis"},{"key": "D","text": "Vastus lateralis"}],"correct": "D","explanation": "Vastus lateralis has the largest cross-sectional area among quadriceps muscles and contributes most to total quadriceps force."},{"id": 645,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which muscles form the hamstring group?","options": [{"key": "A","text": "Biceps femoris, semitendinosus, semimembranosus"},{"key": "B","text": "Rectus femoris, biceps femoris, semimembranosus"},{"key": "C","text": "Adductor magnus, biceps femoris, gracilis"},{"key": "D","text": "Biceps femoris, semitendinosus, popliteus"}],"correct": "A","explanation": "Hamstrings consist of biceps femoris (long and short head), semitendinosus, and semimembranosus."},{"id": 646,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Most hamstring injuries occur at:","options": [{"key": "A","text": "Proximal musculotendinous junction"},{"key": "B","text": "Distal insertion"},{"key": "C","text": "Mid-belly"},{"key": "D","text": "Ischial tuberosity"}],"correct": "A","explanation": "Approximately 70% of hamstring strains occur at the proximal myotendinous junction, especially in biceps femoris long head."},{"id": 647,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The common origin of hamstrings is:","options": [{"key": "A","text": "Greater trochanter"},{"key": "B","text": "AIIS"},{"key": "C","text": "Ischial tuberosity"},{"key": "D","text": "Femoral shaft"}],"correct": "C","explanation": "All three hamstring muscles (except biceps short head) originate from the ischial tuberosity."},{"id": 648,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Biceps femoris short head is innervated by:","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Common peroneal nerve"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Tibial nerve"}],"correct": "B","explanation": "Biceps femoris short head is uniquely innervated by common peroneal nerve (L5, S1, S2), unlike other hamstrings."},{"id": 649,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Semimembranosus inserts into:","options": [{"key": "A","text": "Medial condyle of tibia"},{"key": "B","text": "Tibial tuberosity"},{"key": "C","text": "Lateral condyle of tibia"},{"key": "D","text": "Head of fibula"}],"correct": "A","explanation": "Semimembranosus inserts primarily into the medial condyle of tibia via its direct arm."},{"id": 650,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The 'pes anserinus' is formed by:","options": [{"key": "A","text": "Sartorius, gracilis, semitendinosus"},{"key": "B","text": "Sartorius, semimembranosus, biceps femoris"},{"key": "C","text": "Gracilis, biceps femoris, semitendinosus"},{"key": "D","text": "Rectus femoris, sartorius, gracilis"}],"correct": "A","explanation": "Pes anserinus ('goose foot') is the conjoined insertion of sartorius, gracilis, and semitendinosus on the medial tibia."},{"id": 651,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "During running, hamstrings are most active in:","options": [{"key": "A","text": "Mid-swing only"},{"key": "B","text": "Loading response"},{"key": "C","text": "Push-off phase"},{"key": "D","text": "Swing phase deceleration and early stance"}],"correct": "D","explanation": "Hamstrings decelerate the swinging leg (eccentric) and then produce hip extension force in early stance."},{"id": 652,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The Nordic hamstring curl primarily trains:","options": [{"key": "A","text": "Eccentric hamstring contraction"},{"key": "B","text": "Isometric hamstring contraction"},{"key": "C","text": "Concentric hamstring contraction"},{"key": "D","text": "Hip extensor strength"}],"correct": "A","explanation": "Nordic hamstring curl is an eccentric exercise where hamstrings control knee extension under load, preventing injury."},{"id": 653,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Semitendinosus tendon is commonly harvested for:","options": [{"key": "A","text": "Patellar tendon repair"},{"key": "B","text": "Meniscal repair"},{"key": "C","text": "PCL reconstruction"},{"key": "D","text": "ACL reconstruction"}],"correct": "D","explanation": "Semitendinosus (and gracilis) tendons are commonly used as autograft for ACL reconstruction."},{"id": 654,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which test assesses hamstring flexibility?","options": [{"key": "A","text": "Straight leg raise test"},{"key": "B","text": "Thomas test"},{"key": "C","text": "Trendelenburg test"},{"key": "D","text": "Ober's test"}],"correct": "A","explanation": "Straight leg raise (SLR) with passive hip flexion (knee extended) assesses hamstring flexibility; normal >80 degrees."},{"id": 655,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Hamstrings function as knee flexors and:","options": [{"key": "A","text": "Hip extensors"},{"key": "B","text": "Hip adductors"},{"key": "C","text": "Hip abductors"},{"key": "D","text": "Hip flexors"}],"correct": "A","explanation": "Hamstrings (except biceps short head) cross both joints, acting as knee flexors and hip extensors."},{"id": 656,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Proximal hamstring tendinopathy pain is aggravated by:","options": [{"key": "A","text": "Walking flat"},{"key": "B","text": "Lying down"},{"key": "C","text": "Sitting on hard surfaces and hill running"},{"key": "D","text": "Standing"}],"correct": "C","explanation": "Proximal hamstring tendinopathy causes pain with sitting (compressive load) and uphill running (high stretch loads)."},{"id": 657,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The 'H' ratio (hamstring:quadriceps) for injury prevention should be:","options": [{"key": "A","text": "Less than 0.5"},{"key": "B","text": "0.6-0.8"},{"key": "C","text": "Greater than 1.0"},{"key": "D","text": "Exactly 1.0"}],"correct": "B","explanation": "Hamstring:Quadriceps ratio of 0.6-0.8 is considered safe; ratio below 0.6 increases hamstring injury risk."},{"id": 658,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Biceps femoris long head is innervated by:","options": [{"key": "A","text": "Saphenous nerve"},{"key": "B","text": "Tibial nerve"},{"key": "C","text": "Femoral nerve"},{"key": "D","text": "Common peroneal nerve"}],"correct": "B","explanation": "Biceps femoris long head is innervated by the tibial division of sciatic nerve (L5, S1, S2)."},{"id": 659,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Semimembranosus has how many insertional arms?","options": [{"key": "A","text": "Two"},{"key": "B","text": "Five"},{"key": "C","text": "Three"},{"key": "D","text": "One"}],"correct": "B","explanation": "Semimembranosus has five insertional arms: direct, anterior, oblique popliteal ligament, popliteal fascia, and medial meniscus."},{"id": 660,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which hamstring is most commonly injured in sprinting?","options": [{"key": "A","text": "Biceps femoris short head"},{"key": "B","text": "Semitendinosus"},{"key": "C","text": "Biceps femoris long head"},{"key": "D","text": "Semimembranosus"}],"correct": "C","explanation": "Biceps femoris long head is the most commonly injured hamstring in sprinting due to its biarticular nature."},{"id": 661,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "During seated knee flexion, which hamstrings are at mechanical advantage?","options": [{"key": "A","text": "All equally"},{"key": "B","text": "Biceps femoris"},{"key": "C","text": "Semimembranosus"},{"key": "D","text": "Semitendinosus"}],"correct": "B","explanation": "Biceps femoris has a greater moment arm for knee flexion when hip is flexed (seated position)."},{"id": 662,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Grade II hamstring strain involves:","options": [{"key": "A","text": "Partial muscle tear (5-90% fibers)"},{"key": "B","text": "Less than 5% fiber tear"},{"key": "C","text": "Complete muscle rupture"},{"key": "D","text": "Bone avulsion"}],"correct": "A","explanation": "Grade II strain involves partial tear (5-90% of fibers), causing significant pain and functional limitation."},{"id": 663,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Return to sport after hamstring grade II strain typically takes:","options": [{"key": "A","text": "3-5 days"},{"key": "B","text": "3-6 weeks"},{"key": "C","text": "3-6 months"},{"key": "D","text": "1-2 weeks"}],"correct": "B","explanation": "Grade II hamstring strain typically requires 3-6 weeks for rehabilitation before safe return to sport."},{"id": 664,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The posterior thigh cutaneous nerve provides sensation to:","options": [{"key": "A","text": "Lateral leg"},{"key": "B","text": "Posterior thigh and upper leg"},{"key": "C","text": "Medial knee"},{"key": "D","text": "Anterior thigh"}],"correct": "B","explanation": "Posterior femoral cutaneous nerve (S1-S3) provides sensory innervation to posterior thigh and proximal leg."},{"id": 665,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Hamstring tightness affects lumbar spine by:","options": [{"key": "A","text": "Increasing lumbar lordosis"},{"key": "B","text": "Flattening lumbar lordosis in standing"},{"key": "C","text": "No effect on lumbar spine"},{"key": "D","text": "Increasing thoracic kyphosis"}],"correct": "B","explanation": "Tight hamstrings posteriorly tilt the pelvis, which flattens the lumbar lordosis in standing posture."},{"id": 666,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The optimal length for hamstring strengthening on isokinetic machine is:","options": [{"key": "A","text": "At shortened position"},{"key": "B","text": "At neutral position"},{"key": "C","text": "At lengthened position"},{"key": "D","text": "Position doesn't matter"}],"correct": "C","explanation": "Hamstrings are stronger eccentrically and training at longer muscle lengths improves eccentric capacity and reduces injury risk."},{"id": 667,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Avulsion fracture of ischial tuberosity is common in:","options": [{"key": "A","text": "Young athletes during sudden sprinting"},{"key": "B","text": "Elderly patients"},{"key": "C","text": "Osteoporotic women"},{"key": "D","text": "Distance runners"}],"correct": "A","explanation": "Ischial tuberosity avulsion occurs in young athletes (open physis) during sudden hamstring contraction in sprinting."},{"id": 668,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Sciatic nerve relationship to hamstrings:","options": [{"key": "A","text": "Lies anterior to hamstrings"},{"key": "B","text": "Not related to hamstrings"},{"key": "C","text": "Lies posterior to hamstrings"},{"key": "D","text": "Lies between hamstrings"}],"correct": "D","explanation": "Sciatic nerve courses between the long and short heads of biceps femoris in the posterior thigh."},{"id": 669,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "In ACL deficient knee, hamstrings compensate by:","options": [{"key": "A","text": "Reducing their activity"},{"key": "B","text": "Relaxing during loading"},{"key": "C","text": "Shifting to concentric work only"},{"key": "D","text": "Increasing their co-contraction to provide dynamic stability"}],"correct": "D","explanation": "In ACL deficiency, hamstrings increase their co-contraction to provide dynamic posterior tibial restraint and joint stability."},{"id": 670,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The gluteus maximus is the primary:","options": [{"key": "A","text": "Hip extensor"},{"key": "B","text": "Hip internal rotator"},{"key": "C","text": "Hip abductor"},{"key": "D","text": "Hip flexor"}],"correct": "A","explanation": "Gluteus maximus is the largest and most powerful hip extensor, also performing external rotation."},{"id": 671,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Gluteus maximus innervation is from:","options": [{"key": "A","text": "Sciatic nerve"},{"key": "B","text": "Pudendal nerve"},{"key": "C","text": "Inferior gluteal nerve"},{"key": "D","text": "Superior gluteal nerve"}],"correct": "C","explanation": "Gluteus maximus is innervated by the inferior gluteal nerve (L5, S1, S2)."},{"id": 672,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Trendelenburg sign indicates weakness of:","options": [{"key": "A","text": "Obturator internus"},{"key": "B","text": "Gluteus medius and minimus"},{"key": "C","text": "Piriformis"},{"key": "D","text": "Gluteus maximus"}],"correct": "B","explanation": "Positive Trendelenburg sign indicates weakness of gluteus medius/minimus on the weight-bearing side, causing pelvic drop."},{"id": 673,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Gluteus medius is primarily a:","options": [{"key": "A","text": "Hip adductor"},{"key": "B","text": "Hip abductor and internal rotator"},{"key": "C","text": "Hip flexor"},{"key": "D","text": "Hip extensor"}],"correct": "B","explanation": "Gluteus medius is the primary hip abductor; its anterior fibers also internally rotate the hip."},{"id": 674,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The IT band (iliotibial band) is the distal extension of:","options": [{"key": "A","text": "Rectus femoris"},{"key": "B","text": "Gluteus medius"},{"key": "C","text": "Tensor fasciae latae and gluteus maximus"},{"key": "D","text": "Gluteus maximus only"}],"correct": "C","explanation": "The IT band receives contributions from both TFL and gluteus maximus as it courses down the lateral thigh."},{"id": 675,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Piriformis syndrome mimics:","options": [{"key": "A","text": "Femoral nerve compression"},{"key": "B","text": "Lateral cutaneous nerve compression"},{"key": "C","text": "Obturator nerve compression"},{"key": "D","text": "Sciatic nerve compression (sciatica)"}],"correct": "D","explanation": "Piriformis muscle can compress the sciatic nerve (which passes through or beneath it), mimicking true sciatica."},{"id": 676,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The superior gluteal nerve innervates:","options": [{"key": "A","text": "Piriformis"},{"key": "B","text": "Gluteus maximus"},{"key": "C","text": "Gluteus medius, minimus, and TFL"},{"key": "D","text": "Obturator internus"}],"correct": "C","explanation": "Superior gluteal nerve (L4, L5, S1) innervates gluteus medius, gluteus minimus, and tensor fasciae latae."},{"id": 677,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Gluteus maximus inserts primarily into:","options": [{"key": "A","text": "Greater trochanter"},{"key": "B","text": "Femoral neck"},{"key": "C","text": "Lesser trochanter"},{"key": "D","text": "Iliotibial band and gluteal tuberosity of femur"}],"correct": "D","explanation": "Approximately 75% of gluteus maximus inserts into the IT band and 25% into the gluteal tuberosity of the femur."},{"id": 678,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The 'deep six' external rotators of the hip include all EXCEPT:","options": [{"key": "A","text": "Obturator internus"},{"key": "B","text": "Piriformis"},{"key": "C","text": "Quadratus femoris"},{"key": "D","text": "Gluteus medius"}],"correct": "D","explanation": "The six deep external rotators are: piriformis, obturator internus/externus, superior/inferior gemellus, and quadratus femoris."},{"id": 679,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Gluteus minimus primary function:","options": [{"key": "A","text": "Hip external rotation"},{"key": "B","text": "Knee flexion"},{"key": "C","text": "Hip abduction and internal rotation"},{"key": "D","text": "Hip extension"}],"correct": "C","explanation": "Gluteus minimus assists gluteus medius in hip abduction; its anterior fibers also medially rotate the hip."},{"id": 680,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "During single-leg stance, gluteus medius must produce torque to prevent:","options": [{"key": "A","text": "Hip extension"},{"key": "B","text": "Ankle pronation"},{"key": "C","text": "Pelvic drop on the contralateral side"},{"key": "D","text": "Knee extension"}],"correct": "C","explanation": "Gluteus medius contracts isometrically/eccentrically to prevent contralateral pelvic drop during single-leg stance."},{"id": 681,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Greater trochanteric pain syndrome (bursitis) is associated with:","options": [{"key": "A","text": "Gluteus medius/minimus tendinopathy"},{"key": "B","text": "Hamstring tendinopathy"},{"key": "C","text": "Hip flexor tendinopathy"},{"key": "D","text": "Piriformis syndrome"}],"correct": "A","explanation": "Greater trochanteric pain is now understood to primarily involve gluteus medius/minimus tendinopathy rather than pure bursitis."},{"id": 682,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Clam shell exercise primarily strengthens:","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Adductors"},{"key": "C","text": "Gluteus maximus"},{"key": "D","text": "Gluteus medius in external rotation"}],"correct": "D","explanation": "Clamshell exercise targets gluteus medius in external rotation while maintaining hip and knee flexion position."},{"id": 683,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The sciatic nerve exits the pelvis through:","options": [{"key": "A","text": "Lesser sciatic foramen"},{"key": "B","text": "Ischial spine"},{"key": "C","text": "Greater sciatic foramen below piriformis"},{"key": "D","text": "Obturator foramen"}],"correct": "C","explanation": "Sciatic nerve typically exits below piriformis through the greater sciatic foramen (infrapiriform portion)."},{"id": 684,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Weak gluteus maximus affects gait by producing:","options": [{"key": "A","text": "Trendelenburg gait"},{"key": "B","text": "Antalgic gait"},{"key": "C","text": "Gluteus maximus lurch (backward trunk lean)"},{"key": "D","text": "Steppage gait"}],"correct": "C","explanation": "Weak gluteus maximus causes the patient to lean backward over the stance leg to reduce hip extension demand."},{"id": 685,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The FABER test (Patrick's test) assesses:","options": [{"key": "A","text": "Hip joint pathology and SI joint"},{"key": "B","text": "Hamstring tightness"},{"key": "C","text": "IT band tightness"},{"key": "D","text": "Quadriceps tightness"}],"correct": "A","explanation": "FABER (Flexion, ABduction, External Rotation) tests hip joint integrity and sacroiliac joint dysfunction."},{"id": 686,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Gluteus medius weakness leads to which lower extremity alignment problem?","options": [{"key": "A","text": "Genu varum"},{"key": "B","text": "Increased hip adduction and knee valgus (dynamic)"},{"key": "C","text": "Ankle pronation alone"},{"key": "D","text": "Genu recurvatum"}],"correct": "B","explanation": "Weak gluteus medius allows hip adduction and internal rotation, creating dynamic knee valgus (medial knee collapse)."},{"id": 687,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The piriformis muscle originates from:","options": [{"key": "A","text": "Posterior ilium"},{"key": "B","text": "Pubic bone"},{"key": "C","text": "Anterior sacrum"},{"key": "D","text": "Ischial tuberosity"}],"correct": "C","explanation": "Piriformis originates from the anterior surface of sacrum (S2-S4) and inserts into greater trochanter."},{"id": 688,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Hip abduction strength testing MMT grade 3 means:","options": [{"key": "A","text": "Full ROM against gravity with no resistance"},{"key": "B","text": "Full ROM against gravity with maximum resistance"},{"key": "C","text": "Partial ROM against gravity"},{"key": "D","text": "Full ROM only with gravity eliminated"}],"correct": "A","explanation": "MMT Grade 3 = full ROM against gravity with no additional resistance applied."},{"id": 689,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The tensor fasciae latae (TFL) is a:","options": [{"key": "A","text": "Hip extensor"},{"key": "B","text": "Knee extensor"},{"key": "C","text": "Pure hip abductor"},{"key": "D","text": "Hip flexor, internal rotator, and abductor"}],"correct": "D","explanation": "TFL performs hip flexion, abduction, and internal rotation; it also provides IT band tension for knee stabilization."},{"id": 690,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Iliotibial band syndrome (ITBS) is caused by:","options": [{"key": "A","text": "IT band friction over lateral femoral epicondyle"},{"key": "B","text": "Hamstring tightness"},{"key": "C","text": "Medial knee ligament injury"},{"key": "D","text": "Patellar maltracking"}],"correct": "A","explanation": "ITBS results from repetitive friction of the tight IT band over the lateral femoral epicondyle during knee flexion-extension."},{"id": 691,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Gluteal amnesia refers to:","options": [{"key": "A","text": "Hip pain affecting memory"},{"key": "B","text": "Memory loss due to gluteal injury"},{"key": "C","text": "Gluteal muscle atrophy from nerve damage"},{"key": "D","text": "Inhibition of gluteal muscles due to prolonged sitting"}],"correct": "D","explanation": "Prolonged sitting causes reciprocal inhibition of gluteal muscles by hip flexors, leading to reduced gluteal activation."},{"id": 692,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The obturator externus inserts into:","options": [{"key": "A","text": "Iliotibial band"},{"key": "B","text": "Greater trochanter"},{"key": "C","text": "Trochanteric fossa"},{"key": "D","text": "Lesser trochanter"}],"correct": "C","explanation": "Obturator externus inserts into the trochanteric fossa on the medial surface of the greater trochanter."},{"id": 693,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Which deep gluteal muscle passes through the lesser sciatic foramen?","options": [{"key": "A","text": "Quadratus femoris"},{"key": "B","text": "Piriformis"},{"key": "C","text": "Gemellus superior"},{"key": "D","text": "Obturator internus"}],"correct": "D","explanation": "Obturator internus leaves the pelvis through the lesser sciatic foramen, hooking around the ischium."},{"id": 694,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "For runners with gluteal weakness, which exercise best activates gluteus medius?","options": [{"key": "A","text": "Deadlift"},{"key": "B","text": "Prone hip extension"},{"key": "C","text": "Hip thrust"},{"key": "D","text": "Side-lying hip abduction"}],"correct": "D","explanation": "Side-lying hip abduction isolates gluteus medius effectively; single-leg bridges and step-ups also provide high activation."},{"id": 695,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The gastrocnemius has how many heads?","options": [{"key": "A","text": "Three"},{"key": "B","text": "Two"},{"key": "C","text": "Four"},{"key": "D","text": "One"}],"correct": "B","explanation": "Gastrocnemius has two heads: medial and lateral, originating from respective femoral condyles."},{"id": 696,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The Achilles tendon is the common tendon of:","options": [{"key": "A","text": "Gastrocnemius and soleus"},{"key": "B","text": "Gastrocnemius, soleus, and plantaris"},{"key": "C","text": "Soleus only"},{"key": "D","text": "Gastrocnemius only"}],"correct": "A","explanation": "Achilles tendon is formed by the combined tendons of gastrocnemius and soleus (triceps surae)."},{"id": 697,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Gastrocnemius is innervated by:","options": [{"key": "A","text": "Tibial nerve"},{"key": "B","text": "Superficial peroneal nerve"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Common peroneal nerve"}],"correct": "A","explanation": "Gastrocnemius is innervated by the tibial nerve (S1, S2)."},{"id": 698,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which calf muscle is more important for walking at slow speeds?","options": [{"key": "A","text": "Popliteus"},{"key": "B","text": "Gastrocnemius"},{"key": "C","text": "Plantaris"},{"key": "D","text": "Soleus"}],"correct": "D","explanation": "Soleus is more active during slow walking; gastrocnemius is more active during faster walking and running."},{"id": 699,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Soleus originates from:","options": [{"key": "A","text": "Posterior fibular head and soleal line of tibia"},{"key": "B","text": "Posterior femoral condyles"},{"key": "C","text": "Calcaneus"},{"key": "D","text": "Posterior tibia only"}],"correct": "A","explanation": "Soleus originates from the posterior fibular head/neck, soleal line and medial border of tibia."},{"id": 700,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Thompson's test assesses integrity of:","options": [{"key": "A","text": "Achilles tendon"},{"key": "B","text": "Tibialis anterior"},{"key": "C","text": "Plantar fascia"},{"key": "D","text": "Peroneal tendons"}],"correct": "A","explanation": "Thompson test (calf squeeze test) diagnoses Achilles tendon rupture; absence of plantar flexion = positive."},{"id": 701,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The soleus is primarily composed of:","options": [{"key": "A","text": "Type II (fast-twitch) fibers"},{"key": "B","text": "Type I (slow-twitch) fibers"},{"key": "C","text": "Equal mix"},{"key": "D","text": "Type IIx fibers predominantly"}],"correct": "B","explanation": "Soleus contains approximately 70-80% Type I slow-twitch fibers, making it ideal for sustained anti-gravity function."},{"id": 702,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Gastrocnemius acts on which joints?","options": [{"key": "A","text": "Knee and ankle"},{"key": "B","text": "Hip and ankle"},{"key": "C","text": "Hip, knee, and ankle"},{"key": "D","text": "Ankle only"}],"correct": "A","explanation": "Gastrocnemius crosses both knee and ankle joints, acting as knee flexor and ankle plantarflexor."},{"id": 703,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "The triceps surae group includes:","options": [{"key": "A","text": "Gastrocnemius and soleus"},{"key": "B","text": "All posterior compartment muscles"},{"key": "C","text": "Gastrocnemius and popliteus"},{"key": "D","text": "Gastrocnemius, soleus, and plantaris"}],"correct": "D","explanation": "Triceps surae consists of gastrocnemius (2 heads) and soleus, sometimes including plantaris as a fourth head."},{"id": 704,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Eccentric calf training (heel drop exercise) on a step is used for:","options": [{"key": "A","text": "Peroneal tendinopathy"},{"key": "B","text": "Posterior tibialis tendinopathy"},{"key": "C","text": "Plantar fasciitis"},{"key": "D","text": "Achilles tendinopathy"}],"correct": "D","explanation": "Alfredson protocol of eccentric heel drops (straight and bent knee) is first-line treatment for Achilles tendinopathy."},{"id": 705,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The sural nerve provides sensation to:","options": [{"key": "A","text": "Dorsum of foot"},{"key": "B","text": "Plantar surface"},{"key": "C","text": "Lateral foot and little toe"},{"key": "D","text": "Medial sole of foot"}],"correct": "C","explanation": "Sural nerve is a sensory nerve providing sensation to the lateral foot and fifth toe."},{"id": 706,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Calf raises with straight knee primarily targets:","options": [{"key": "A","text": "Soleus"},{"key": "B","text": "Flexor digitorum longus"},{"key": "C","text": "Tibialis posterior"},{"key": "D","text": "Gastrocnemius"}],"correct": "D","explanation": "Straight knee calf raises (plantarflexion with extended knee) primarily target gastrocnemius as it crosses the knee."},{"id": 707,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Calf raises with bent knee (90 degrees) primarily targets:","options": [{"key": "A","text": "Both equally"},{"key": "B","text": "Gastrocnemius"},{"key": "C","text": "Soleus"},{"key": "D","text": "Plantaris"}],"correct": "C","explanation": "Bent-knee calf raises reduce gastrocnemius contribution (it's slackened), isolating soleus."},{"id": 708,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The Achilles tendon insertion is on:","options": [{"key": "A","text": "Base of fifth metatarsal"},{"key": "B","text": "Calcaneal tuberosity (posterior surface)"},{"key": "C","text": "Navicular bone"},{"key": "D","text": "Cuboid"}],"correct": "B","explanation": "Achilles tendon inserts into the posterior surface of the calcaneus (calcaneal tuberosity)."},{"id": 709,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which condition presents with medial heel pain worse in the morning?","options": [{"key": "A","text": "Posterior tibialis tendinopathy"},{"key": "B","text": "Plantar fasciitis"},{"key": "C","text": "Achilles tendinopathy"},{"key": "D","text": "Tarsal tunnel syndrome"}],"correct": "B","explanation": "Plantar fasciitis classically presents with medial heel pain that is worst with first steps in the morning."},{"id": 710,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Ankle plantarflexion range of motion is normally:","options": [{"key": "A","text": "0-50 degrees"},{"key": "B","text": "0-20 degrees"},{"key": "C","text": "0-70 degrees"},{"key": "D","text": "0-30 degrees"}],"correct": "A","explanation": "Normal ankle plantarflexion is 0-50 degrees (average 45 degrees) measured from neutral position."},{"id": 711,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The zone of poor vascularity in Achilles tendon is located:","options": [{"key": "A","text": "Throughout the tendon"},{"key": "B","text": "2-6 cm proximal to insertion"},{"key": "C","text": "At the calcaneal insertion"},{"key": "D","text": "At the musculotendinous junction"}],"correct": "B","explanation": "The critical zone of relative avascularity (watershed zone) is 2-6 cm proximal to the Achilles insertion, where most ruptures occur."},{"id": 712,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Calf muscle pump failure leads to:","options": [{"key": "A","text": "Arterial insufficiency"},{"key": "B","text": "Lymphedema only"},{"key": "C","text": "Nerve compression"},{"key": "D","text": "Venous insufficiency and DVT risk"}],"correct": "D","explanation": "The calf muscle pump (soleus venous sinuses) propels blood upward; pump failure leads to venous stasis, edema, and DVT risk."},{"id": 713,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which spinal level is tested by Achilles tendon reflex?","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "L4-L5"},{"key": "C","text": "S3-S4"},{"key": "D","text": "S1-S2"}],"correct": "D","explanation": "Achilles reflex (ankle jerk) tests S1-S2 spinal levels via the tibial nerve."},{"id": 714,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Plantaris muscle rupture mimics:","options": [{"key": "A","text": "Medial gastrocnemius tear (tennis leg)"},{"key": "B","text": "DVT"},{"key": "C","text": "Achilles tendon rupture"},{"key": "D","text": "Soleus injury"}],"correct": "A","explanation": "Plantaris rupture presents similar to medial gastrocnemius tear (tennis leg) with sudden posterior calf pain."},{"id": 715,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "During push-off in gait, which muscle produces the most power?","options": [{"key": "A","text": "Hip extensors"},{"key": "B","text": "Tibialis anterior"},{"key": "C","text": "Quadriceps"},{"key": "D","text": "Soleus and gastrocnemius"}],"correct": "D","explanation": "Ankle plantarflexors (gastrocnemius and soleus) generate the most power during push-off phase of gait."},{"id": 716,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Compartment syndrome of the posterior deep compartment affects:","options": [{"key": "A","text": "Tibialis anterior"},{"key": "B","text": "Tibialis posterior, FDL, FHL"},{"key": "C","text": "Peroneals"},{"key": "D","text": "Gastrocnemius"}],"correct": "B","explanation": "Deep posterior compartment contains tibialis posterior, flexor digitorum longus, and flexor hallucis longus."},{"id": 717,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The speed of Achilles tendon vibration sensation is a test for:","options": [{"key": "A","text": "Tendon pathology"},{"key": "B","text": "Tibial nerve function"},{"key": "C","text": "Ankle instability"},{"key": "D","text": "Peripheral vascular disease"}],"correct": "B","explanation": "Tuning fork vibration testing over the Achilles tendon area assesses large fiber sensory function and S1 dermatome."},{"id": 718,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Single-leg heel raise test requires minimum repetitions for normal function:","options": [{"key": "A","text": "5"},{"key": "B","text": "5-10"},{"key": "C","text": "15-25"},{"key": "D","text": "30-40"}],"correct": "C","explanation": "Normal single-leg heel raise capacity is approximately 15-25 repetitions; less than 15 suggests calf weakness."},{"id": 719,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Medial gastrocnemius strain (tennis leg) most commonly occurs at:","options": [{"key": "A","text": "Distal musculotendinous junction"},{"key": "B","text": "Proximal musculotendinous junction of medial gastrocnemius"},{"key": "C","text": "Calcaneal insertion"},{"key": "D","text": "Mid-belly"}],"correct": "B","explanation": "Tennis leg (medial gastrocnemius strain) typically occurs at the proximal musculotendinous junction with sudden calf pain during activity."},{"id": 720,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Femoral nerve is formed from which nerve roots?","options": [{"key": "A","text": "L3, L4, L5"},{"key": "B","text": "L1, L2, L3"},{"key": "C","text": "L2, L3, L4"},{"key": "D","text": "L1, L2, L3, L4"}],"correct": "C","explanation": "Femoral nerve arises from the posterior divisions of L2, L3, L4 nerve roots of the lumbar plexus."},{"id": 721,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Femoral nerve exits the pelvis through:","options": [{"key": "A","text": "Lesser sciatic foramen"},{"key": "B","text": "Greater sciatic foramen"},{"key": "C","text": "Obturator foramen"},{"key": "D","text": "Femoral triangle deep to inguinal ligament"}],"correct": "D","explanation": "Femoral nerve passes deep to the inguinal ligament (lateral to femoral vessels) to enter the femoral triangle."},{"id": 722,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The longest branch of femoral nerve is:","options": [{"key": "A","text": "Saphenous nerve"},{"key": "B","text": "Nerve to vastus medialis"},{"key": "C","text": "Anterior cutaneous nerve of thigh"},{"key": "D","text": "Nerve to rectus femoris"}],"correct": "A","explanation": "Saphenous nerve is the longest branch of femoral nerve, accompanying the great saphenous vein to the medial foot."},{"id": 723,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Femoral nerve supplies all EXCEPT:","options": [{"key": "A","text": "Adductor longus"},{"key": "B","text": "Pectineus"},{"key": "C","text": "Quadriceps femoris"},{"key": "D","text": "Sartorius"}],"correct": "A","explanation": "Femoral nerve supplies quadriceps, sartorius, and pectineus. Adductor longus is supplied by obturator nerve."},{"id": 724,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The saphenous nerve is a branch of femoral nerve that provides sensation to:","options": [{"key": "A","text": "Posterior thigh"},{"key": "B","text": "Medial leg and foot"},{"key": "C","text": "Sole of foot"},{"key": "D","text": "Lateral leg"}],"correct": "B","explanation": "Saphenous nerve (purely sensory) supplies medial aspect of leg, ankle, and medial side of foot."},{"id": 725,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Femoral nerve injury proximal to inguinal ligament causes loss of:","options": [{"key": "A","text": "Knee extension only"},{"key": "B","text": "Knee extension and hip flexion, with sensory loss over anterior thigh"},{"key": "C","text": "Hip extension only"},{"key": "D","text": "Ankle dorsiflexion"}],"correct": "B","explanation": "Proximal femoral nerve injury causes weakness of quadriceps (knee extension) and iliacus (hip flexion), with anterior thigh sensory loss."},{"id": 726,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "In femoral triangle, the arrangement lateral to medial is:","options": [{"key": "A","text": "Vein, Artery, Nerve"},{"key": "B","text": "Artery, Nerve, Vein"},{"key": "C","text": "Nerve, Artery, Vein"},{"key": "D","text": "Nerve, Vein, Artery"}],"correct": "C","explanation": "Lateral to medial in femoral triangle: Nerve, Artery, Vein — remembered by NAVY (Nerve, Artery, Vein, Y-fronts/lymphatics)."},{"id": 727,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Femoral nerve innervates which hip flexor muscle?","options": [{"key": "A","text": "TFL"},{"key": "B","text": "Iliacus"},{"key": "C","text": "Psoas major"},{"key": "D","text": "Rectus femoris only"}],"correct": "B","explanation": "Femoral nerve innervates iliacus; psoas major is innervated by direct branches from L1-L3 ventral rami."},{"id": 728,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Saphenous nerve is at risk during:","options": [{"key": "A","text": "Ankle arthroscopy"},{"key": "B","text": "Great saphenous vein harvesting"},{"key": "C","text": "Total knee replacement"},{"key": "D","text": "Hip arthroplasty"}],"correct": "B","explanation": "Saphenous nerve runs alongside the great saphenous vein and is commonly injured during vein harvesting for CABG."},{"id": 729,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Loss of patellar reflex indicates femoral nerve injury at level:","options": [{"key": "A","text": "L5"},{"key": "B","text": "L3-L4"},{"key": "C","text": "S1"},{"key": "D","text": "L2"}],"correct": "B","explanation": "Patellar reflex (knee jerk) is mediated through L3-L4 via femoral nerve; its loss indicates injury at this level."},{"id": 730,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Femoral nerve passes through the femoral triangle in which compartment?","options": [{"key": "A","text": "Within femoral sheath"},{"key": "B","text": "Lateral to femoral sheath"},{"key": "C","text": "Posterior to femoral sheath"},{"key": "D","text": "Medial to femoral sheath"}],"correct": "B","explanation": "Femoral nerve lies lateral to the femoral sheath (which contains artery and vein); it is NOT within the sheath."},{"id": 731,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Meralgia paresthetica is caused by compression of:","options": [{"key": "A","text": "Obturator nerve"},{"key": "B","text": "Lateral femoral cutaneous nerve"},{"key": "C","text": "Femoral nerve"},{"key": "D","text": "Saphenous nerve"}],"correct": "B","explanation": "Meralgia paresthetica is entrapment of lateral femoral cutaneous nerve (L2, L3) at the inguinal ligament, causing anterolateral thigh numbness."},{"id": 732,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Nerve to sartorius branches from femoral nerve:","options": [{"key": "A","text": "In the adductor canal"},{"key": "B","text": "Within the femoral triangle"},{"key": "C","text": "Before entering femoral triangle"},{"key": "D","text": "After exiting femoral triangle"}],"correct": "B","explanation": "The nerve to sartorius arises from the femoral nerve within the femoral triangle."},{"id": 733,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The adductor (Hunter's) canal contains:","options": [{"key": "A","text": "Femoral nerve, artery, vein"},{"key": "B","text": "Sciatic nerve and femoral artery"},{"key": "C","text": "Obturator nerve and femoral vein"},{"key": "D","text": "Femoral artery, vein, and saphenous nerve"}],"correct": "D","explanation": "Hunter's canal contains: femoral artery and vein, saphenous nerve, and nerve to vastus medialis."},{"id": 734,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Femoral nerve block is performed at:","options": [{"key": "A","text": "Posterior to femoral artery"},{"key": "B","text": "Knee level"},{"key": "C","text": "Inguinal ligament level, lateral to femoral artery"},{"key": "D","text": "Mid-thigh level"}],"correct": "C","explanation": "Femoral nerve block is done just below the inguinal ligament, lateral to the femoral artery pulse."},{"id": 735,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Femoral neuropathy most commonly results from:","options": [{"key": "A","text": "Diabetes mellitus (diabetic amyotrophy)"},{"key": "B","text": "Piriformis syndrome"},{"key": "C","text": "Trauma to posterior thigh"},{"key": "D","text": "Disc herniation at L3-L4"}],"correct": "A","explanation": "Diabetic amyotrophy (diabetic lumbosacral radiculoplexus neuropathy) is the most common cause of femoral neuropathy."},{"id": 736,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Which test specifically assesses femoral nerve stretch?","options": [{"key": "A","text": "SLR test"},{"key": "B","text": "SLUMP test"},{"key": "C","text": "FABER test"},{"key": "D","text": "Prone knee bend (femoral nerve stretch test)"}],"correct": "D","explanation": "Prone knee bend test stretches the femoral nerve; pain in anterior thigh indicates femoral nerve irritation."},{"id": 737,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Femoral nerve injury during hip arthroplasty most commonly causes:","options": [{"key": "A","text": "Foot drop"},{"key": "B","text": "Loss of hip abduction"},{"key": "C","text": "Loss of knee extension (quadriceps weakness)"},{"key": "D","text": "Ankle weakness"}],"correct": "C","explanation": "Femoral nerve injury during hip surgery causes quadriceps weakness and loss of knee extension reflex."},{"id": 738,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The intermediate and medial cutaneous nerves of thigh are branches of:","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Ilioinguinal nerve"},{"key": "D","text": "Lateral femoral cutaneous nerve"}],"correct": "A","explanation": "Anterior cutaneous branches (medial and intermediate) of femoral nerve supply the anterior and medial thigh skin."},{"id": 739,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Femoral hernia passes:","options": [{"key": "A","text": "Through inguinal canal"},{"key": "B","text": "Through obturator foramen"},{"key": "C","text": "Lateral to femoral vein"},{"key": "D","text": "Medial to femoral vein through femoral canal"}],"correct": "D","explanation": "Femoral hernia descends through the femoral canal, which lies medial to the femoral vein."},{"id": 740,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Adductor canal block targets which nerve for knee surgery?","options": [{"key": "A","text": "Tibial nerve"},{"key": "B","text": "Saphenous nerve"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Femoral nerve completely"}],"correct": "B","explanation": "Adductor canal block targets saphenous nerve for sensory analgesia after knee surgery, preserving quadriceps strength."},{"id": 741,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Femoral nerve arises from which part of lumbar plexus?","options": [{"key": "A","text": "Posterior divisions of L2, L3, L4"},{"key": "B","text": "Anterior divisions of L1, L2, L3"},{"key": "C","text": "All divisions of L2, L3"},{"key": "D","text": "Anterior divisions of L2, L3, L4"}],"correct": "A","explanation": "Femoral nerve arises from posterior divisions of L2, L3, L4 of lumbar plexus (dorsal divisions)."},{"id": 742,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Reverse straight leg raise (SLR) tests which nerve root specifically?","options": [{"key": "A","text": "S1, S2"},{"key": "B","text": "L5, S1"},{"key": "C","text": "L4, L5"},{"key": "D","text": "L2, L3, L4 (femoral nerve)"}],"correct": "D","explanation": "Reverse (prone) SLR stretches the femoral nerve roots (L2-L4); pain in anterior thigh is a positive test."},{"id": 743,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Femoral nerve sensory distribution on the leg is via:","options": [{"key": "A","text": "Lateral sural nerve"},{"key": "B","text": "Sural nerve"},{"key": "C","text": "Saphenous nerve only"},{"key": "D","text": "Superficial peroneal nerve"}],"correct": "C","explanation": "Saphenous nerve (femoral nerve branch) provides the only sensory distribution of femoral nerve below the knee."},{"id": 744,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Paralysis of quadriceps from femoral nerve injury causes difficulty in:","options": [{"key": "A","text": "Ankle dorsiflexion"},{"key": "B","text": "Climbing stairs and rising from chair"},{"key": "C","text": "Foot inversion"},{"key": "D","text": "Hip abduction"}],"correct": "B","explanation": "Quadriceps weakness causes difficulty with weight-bearing knee extension activities like stair climbing and sit-to-stand."},{"id": 745,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Sciatic nerve is the largest nerve in the body arising from:","options": [{"key": "A","text": "L4-S2"},{"key": "B","text": "L2-L5"},{"key": "C","text": "L4, L5, S1, S2, S3"},{"key": "D","text": "L3-S2"}],"correct": "C","explanation": "Sciatic nerve is formed from anterior rami of L4, L5, S1, S2, S3 — the largest nerve in the human body."},{"id": 746,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Sciatic nerve exits the pelvis through:","options": [{"key": "A","text": "Above piriformis"},{"key": "B","text": "Lesser sciatic foramen"},{"key": "C","text": "Greater sciatic foramen below piriformis"},{"key": "D","text": "Obturator foramen"}],"correct": "C","explanation": "Sciatic nerve exits through the infrapiriform part of greater sciatic foramen in 85% of people."},{"id": 747,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Sciatic nerve divides into tibial and common peroneal nerves at:","options": [{"key": "A","text": "Knee joint"},{"key": "B","text": "Gluteal region"},{"key": "C","text": "Upper angle of popliteal fossa"},{"key": "D","text": "Mid-thigh"}],"correct": "C","explanation": "Sciatic nerve typically divides into tibial and common peroneal nerves at the upper angle of the popliteal fossa."},{"id": 748,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The two components of the sciatic nerve are:","options": [{"key": "A","text": "Sural and saphenous nerves"},{"key": "B","text": "Superficial and deep peroneal nerves"},{"key": "C","text": "Tibial and common peroneal nerves"},{"key": "D","text": "Femoral and obturator nerves"}],"correct": "C","explanation": "Sciatic nerve is actually two nerves (tibial and common peroneal) bound together by a common epineurial sheath."},{"id": 749,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Piriformis syndrome compresses the sciatic nerve causing:","options": [{"key": "A","text": "Anterior thigh pain"},{"key": "B","text": "Posterior thigh and leg pain mimicking sciatica"},{"key": "C","text": "Foot drop only"},{"key": "D","text": "Medial knee pain"}],"correct": "B","explanation": "Piriformis syndrome causes sciatic nerve compression resulting in buttock pain radiating down the posterior thigh and leg."},{"id": 750,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Safe site for gluteal injection to avoid sciatic nerve is:","options": [{"key": "A","text": "Lower inner quadrant"},{"key": "B","text": "Upper outer quadrant of buttock"},{"key": "C","text": "Lower outer quadrant"},{"key": "D","text": "Central buttock"}],"correct": "B","explanation": "Intramuscular injections should be given in the upper outer quadrant of the buttock to avoid the sciatic nerve."},{"id": 751,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Sciatic nerve supplies which muscles in the thigh?","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Adductors"},{"key": "C","text": "Hamstrings and adductor magnus (ischial part)"},{"key": "D","text": "Quadriceps"}],"correct": "C","explanation": "Sciatic nerve innervates all hamstrings, short head of biceps femoris, and the ischial part of adductor magnus."},{"id": 752,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Complete sciatic nerve palsy causes:","options": [{"key": "A","text": "Hip extension weakness"},{"key": "B","text": "Foot drop only"},{"key": "C","text": "Loss of all movements below knee + posterior thigh weakness"},{"key": "D","text": "Quadriceps weakness"}],"correct": "C","explanation": "Complete sciatic nerve palsy causes paralysis of hamstrings and all muscles below the knee, with sensory loss."},{"id": 753,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Straight leg raise (SLR) test is positive when pain radiates below knee at:","options": [{"key": "A","text": "Only at full flexion"},{"key": "B","text": "Less than 70 degrees of hip flexion"},{"key": "C","text": "Less than 30 degrees"},{"key": "D","text": "90 degrees"}],"correct": "B","explanation": "SLR is positive when sciatic pain radiates below the knee at less than 70 degrees; 30-40 degrees = severe compression."},{"id": 754,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Bragard's sign (SLR + ankle dorsiflexion) increases:","options": [{"key": "A","text": "Sciatic nerve tension"},{"key": "B","text": "Obturator nerve tension"},{"key": "C","text": "Sural nerve tension"},{"key": "D","text": "Femoral nerve tension"}],"correct": "A","explanation": "Ankle dorsiflexion added to SLR further stretches the sciatic nerve, increasing neural tension (Bragard's sign)."},{"id": 755,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Which disc herniation most commonly compresses the sciatic nerve?","options": [{"key": "A","text": "L3-L4 disc"},{"key": "B","text": "L1-L2 disc"},{"key": "C","text": "L4-L5 and L5-S1 disc"},{"key": "D","text": "L2-L3 disc"}],"correct": "C","explanation": "L4-L5 (compressing L5) and L5-S1 (compressing S1) disc herniations are the most common causes of sciatica."},{"id": 756,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "In sciatic nerve injury at the gluteal level, which movement is preserved?","options": [{"key": "A","text": "Knee flexion"},{"key": "B","text": "Hip extension by gluteus maximus"},{"key": "C","text": "Ankle dorsiflexion"},{"key": "D","text": "Toe extension"}],"correct": "B","explanation": "Gluteus maximus is supplied by inferior gluteal nerve (not sciatic), so hip extension is preserved in sciatic nerve injury."},{"id": 757,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The SLUMP test stretches:","options": [{"key": "A","text": "Lateral femoral cutaneous nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Sciatic nerve and its meningeal coverings"},{"key": "D","text": "Femoral nerve"}],"correct": "C","explanation": "SLUMP test creates dural and sciatic nerve tension through lumbar flexion, knee extension, and ankle dorsiflexion."},{"id": 758,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Sciatic nerve relation to quadratus femoris muscle:","options": [{"key": "A","text": "Posterior to it"},{"key": "B","text": "Medial to it"},{"key": "C","text": "Anterior to it"},{"key": "D","text": "Lateral to it"}],"correct": "A","explanation": "Sciatic nerve descends posterior to quadratus femoris (and gemelli, obturator internus) in the gluteal region."},{"id": 759,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Hip replacement surgery sciatic nerve injury most commonly involves:","options": [{"key": "A","text": "Entire sciatic nerve equally"},{"key": "B","text": "Tibial division more commonly"},{"key": "C","text": "Peroneal division more commonly"},{"key": "D","text": "Only sensory fibers"}],"correct": "C","explanation": "Peroneal division of sciatic nerve is more commonly injured during hip replacement due to its lateral position and less connective tissue."},{"id": 760,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Sciatic nerve variation where it passes through piriformis occurs in:","options": [{"key": "A","text": "15% of population"},{"key": "B","text": "All individuals"},{"key": "C","text": "5% of population"},{"key": "D","text": "50% of population"}],"correct": "A","explanation": "In approximately 15% of individuals, the peroneal division passes through the piriformis muscle, predisposing to piriformis syndrome."},{"id": 761,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "L4 nerve root compression causes:","options": [{"key": "A","text": "Foot drop"},{"key": "B","text": "Loss of ankle reflex"},{"key": "C","text": "Lateral thigh numbness"},{"key": "D","text": "Medial leg numbness and weak quadriceps"}],"correct": "D","explanation": "L4 compression causes medial leg sensory loss (saphenous distribution), weak quadriceps, and reduced patellar reflex."},{"id": 762,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "L5 nerve root compression causes:","options": [{"key": "A","text": "Weak ankle dorsiflexion and great toe extension, with dorsal foot sensory loss"},{"key": "B","text": "Medial thigh numbness"},{"key": "C","text": "Patellar reflex loss"},{"key": "D","text": "Ankle reflex loss"}],"correct": "A","explanation": "L5 compression causes weakness of tibialis anterior, EHL (foot drop), and sensory loss over dorsum of foot."},{"id": 763,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "S1 nerve root compression causes:","options": [{"key": "A","text": "Anterior leg numbness"},{"key": "B","text": "Quadriceps weakness"},{"key": "C","text": "Weak plantarflexion, reduced Achilles reflex, lateral foot numbness"},{"key": "D","text": "Foot drop"}],"correct": "C","explanation": "S1 compression causes weak plantarflexors, absent Achilles reflex, and sensory loss over lateral foot and sole."},{"id": 764,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Sciatic nerve is palpable at:","options": [{"key": "A","text": "Mid-thigh posteriorly"},{"key": "B","text": "Popliteal fossa"},{"key": "C","text": "Gluteal fold"},{"key": "D","text": "Midpoint between ischial tuberosity and greater trochanter"}],"correct": "D","explanation": "Sciatic nerve can be palpated at the midpoint between the ischial tuberosity and greater trochanter in the gluteal region."},{"id": 765,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Posterior cutaneous nerve of thigh (sciatic nerve's companion) arises from:","options": [{"key": "A","text": "L4, L5"},{"key": "B","text": "L5, S1"},{"key": "C","text": "S1, S2, S3"},{"key": "D","text": "S2, S3, S4"}],"correct": "C","explanation": "Posterior femoral cutaneous nerve arises from S1, S2, S3 and runs with sciatic nerve in posterior thigh."},{"id": 766,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Sciatic nerve injury at the level of ischial tuberosity spares:","options": [{"key": "A","text": "Biceps femoris short head"},{"key": "B","text": "Hamstrings"},{"key": "C","text": "Gastrocnemius"},{"key": "D","text": "All hamstrings equally"}],"correct": "A","explanation": "If injury is at the ischial tuberosity, hamstrings (which originate there) may be partially spared as their branches arise proximally."},{"id": 767,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "The femoral component of sciatic nerve (L4, L5) runs in:","options": [{"key": "A","text": "Equally in both"},{"key": "B","text": "Tibial division"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Peroneal division"}],"correct": "D","explanation": "L4 and L5 fibers predominantly run in the peroneal (common fibular) division of the sciatic nerve."},{"id": 768,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Wallet-sitting sciatica is caused by:","options": [{"key": "A","text": "SI joint dysfunction"},{"key": "B","text": "Piriformis compression from wallet in back pocket"},{"key": "C","text": "Disc herniation"},{"key": "D","text": "Hamstring tightness"}],"correct": "B","explanation": "Prolonged sitting on a thick wallet compresses the piriformis region, irritating the underlying sciatic nerve."},{"id": 769,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Sciatic nerve block in posterior approach targets nerve at:","options": [{"key": "A","text": "Popliteal fossa only"},{"key": "B","text": "Inguinal ligament level"},{"key": "C","text": "Thigh level only"},{"key": "D","text": "Subgluteal or gluteal level"}],"correct": "D","explanation": "Classical sciatic nerve block is performed at the gluteal or subgluteal level (Labat approach) for lower limb anesthesia."},{"id": 770,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Tibial nerve is the larger terminal branch of sciatic nerve arising from:","options": [{"key": "A","text": "L2, L3, L4"},{"key": "B","text": "S1, S2, S3"},{"key": "C","text": "L4, L5, S1, S2, S3"},{"key": "D","text": "L3, L4, L5"}],"correct": "C","explanation": "Tibial nerve (medial popliteal nerve) arises from the tibial (medial) division of sciatic nerve — L4, L5, S1, S2, S3."},{"id": 771,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Tibial nerve enters the leg by passing:","options": [{"key": "A","text": "Deep to popliteus and through soleal arch"},{"key": "B","text": "Through interosseous membrane"},{"key": "C","text": "Anterior to popliteus"},{"key": "D","text": "Lateral to popliteus"}],"correct": "A","explanation": "Tibial nerve passes deep to popliteus and then through the tendinous arch of soleus to enter the posterior compartment."},{"id": 772,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Tarsal tunnel syndrome involves compression of tibial nerve at:","options": [{"key": "A","text": "Behind medial malleolus under flexor retinaculum"},{"key": "B","text": "Plantar fascia"},{"key": "C","text": "Popliteal fossa"},{"key": "D","text": "Mid-leg"}],"correct": "A","explanation": "Tarsal tunnel syndrome is entrapment of the tibial nerve (or its branches) beneath the flexor retinaculum posterior to medial malleolus."},{"id": 773,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Tibial nerve supplies which compartment of the leg?","options": [{"key": "A","text": "All compartments equally"},{"key": "B","text": "Posterior compartment (superficial and deep)"},{"key": "C","text": "Lateral compartment"},{"key": "D","text": "Anterior compartment"}],"correct": "B","explanation": "Tibial nerve supplies all muscles of the posterior compartment: superficial (gastrocnemius, soleus, plantaris) and deep (tibialis posterior, FDL, FHL)."},{"id": 774,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Ankle jerk reflex is mediated by tibial nerve at spinal level:","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "S2-S3"},{"key": "C","text": "L4-L5"},{"key": "D","text": "S1-S2"}],"correct": "D","explanation": "Achilles tendon reflex is mediated through S1-S2 via the tibial nerve."},{"id": 775,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tibial nerve divides into medial and lateral plantar nerves at:","options": [{"key": "A","text": "Mid-foot"},{"key": "B","text": "In the tarsal tunnel / beneath flexor retinaculum"},{"key": "C","text": "Behind medial malleolus"},{"key": "D","text": "Heel"}],"correct": "B","explanation": "Tibial nerve divides into medial and lateral plantar nerves within the tarsal tunnel under the flexor retinaculum."},{"id": 776,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Medial plantar nerve (tibial nerve branch) innervates:","options": [{"key": "A","text": "All intrinsic foot muscles"},{"key": "B","text": "Lateral 1.5 toes"},{"key": "C","text": "Only skin of sole"},{"key": "D","text": "Medial 3.5 toes and intrinsic muscles (LAFF)"}],"correct": "D","explanation": "Medial plantar nerve innervates skin of medial 3.5 toes and muscles: Lumbrical 1, Abductor hallucis, Flexor hallucis brevis, Flexor digitorum brevis (LAFF)."},{"id": 777,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Lateral plantar nerve supplies:","options": [{"key": "A","text": "Dorsum of foot"},{"key": "B","text": "Medial 3.5 toes"},{"key": "C","text": "Lateral 1.5 toes and most intrinsic foot muscles"},{"key": "D","text": "Only plantar skin"}],"correct": "C","explanation": "Lateral plantar nerve supplies lateral 1.5 toes and most intrinsic muscles (interossei, 3 lumbricals, adductor hallucis, flexor digiti minimi)."},{"id": 778,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Sural nerve is formed by branches of:","options": [{"key": "A","text": "Common peroneal nerve only"},{"key": "B","text": "Saphenous and tibial nerve"},{"key": "C","text": "Tibial nerve and common peroneal nerve (sural communicating branch)"},{"key": "D","text": "Tibial nerve only"}],"correct": "C","explanation": "Sural nerve is formed by the medial sural cutaneous nerve (tibial) and sural communicating branch (peroneal)."},{"id": 779,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Tibial nerve injury at the popliteal fossa causes:","options": [{"key": "A","text": "Foot drop"},{"key": "B","text": "Loss of plantarflexion, toe flexion, and inversion with sensory loss over sole"},{"key": "C","text": "Hip flexion weakness"},{"key": "D","text": "Loss of dorsiflexion only"}],"correct": "B","explanation": "Popliteal tibial nerve injury causes weakness of all posterior leg and foot intrinsic muscles with sole sensory loss."},{"id": 780,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Medial sural cutaneous nerve supplies:","options": [{"key": "A","text": "Dorsum of foot"},{"key": "B","text": "Lateral and posterior leg skin"},{"key": "C","text": "Sole of foot"},{"key": "D","text": "Anterior leg"}],"correct": "B","explanation": "Medial sural cutaneous nerve (from tibial) supplies posterior and lateral leg; joins peroneal communicating branch to form sural nerve."},{"id": 781,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Tibial nerve in popliteal fossa lies in relation to popliteal artery:","options": [{"key": "A","text": "Superficial and lateral"},{"key": "B","text": "Deep to artery"},{"key": "C","text": "Medial and deep"},{"key": "D","text": "Anterior to artery"}],"correct": "A","explanation": "In the popliteal fossa from superficial to deep: tibial nerve → popliteal vein → popliteal artery."},{"id": 782,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Jogger's foot (medial plantar nerve entrapment) presents with:","options": [{"key": "A","text": "Lateral heel pain"},{"key": "B","text": "Medial arch pain and numbness in medial toes"},{"key": "C","text": "Lateral toe numbness"},{"key": "D","text": "Dorsal foot pain"}],"correct": "B","explanation": "Jogger's foot is entrapment of medial plantar nerve at the knot of Henry, causing medial arch pain radiating to medial toes."},{"id": 783,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tibialis posterior is innervated by:","options": [{"key": "A","text": "Superficial peroneal nerve"},{"key": "B","text": "Deep peroneal nerve"},{"key": "C","text": "Tibial nerve"},{"key": "D","text": "Sural nerve"}],"correct": "C","explanation": "Tibialis posterior is innervated by the tibial nerve (L4, L5), which is important in posterior tibialis tendinopathy assessment."},{"id": 784,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flexor hallucis longus is innervated by:","options": [{"key": "A","text": "Sural nerve"},{"key": "B","text": "Tibial nerve"},{"key": "C","text": "Superficial peroneal nerve"},{"key": "D","text": "Deep peroneal nerve"}],"correct": "B","explanation": "Flexor hallucis longus (deep posterior compartment) is innervated by the tibial nerve (S2, S3)."},{"id": 785,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Baxter's nerve (inferior calcaneal nerve) is a branch of:","options": [{"key": "A","text": "Tibial nerve directly"},{"key": "B","text": "Sural nerve"},{"key": "C","text": "Medial plantar nerve"},{"key": "D","text": "Lateral plantar nerve"}],"correct": "D","explanation": "Baxter's nerve (nerve to abductor digiti minimi) is the first branch of lateral plantar nerve; its entrapment causes heel pain."},{"id": 786,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tibial nerve calcaneal branches supply:","options": [{"key": "A","text": "Intrinsic toe muscles"},{"key": "B","text": "Lateral ankle"},{"key": "C","text": "Skin of heel (plantar and medial)"},{"key": "D","text": "Achilles tendon"}],"correct": "C","explanation": "Medial calcaneal branches arise from tibial nerve to supply the medial and plantar heel skin."},{"id": 787,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "In tarsal tunnel syndrome, Tinel's sign is positive at:","options": [{"key": "A","text": "Medial malleolus (tapping over tibial nerve)"},{"key": "B","text": "Plantar fascia"},{"key": "C","text": "Popliteal fossa"},{"key": "D","text": "Lateral malleolus"}],"correct": "A","explanation": "Tinel's sign in tarsal tunnel syndrome: tapping posterior to medial malleolus reproduces tingling in the plantar foot."},{"id": 788,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Tibial nerve provides articular branches to:","options": [{"key": "A","text": "Only ankle joint"},{"key": "B","text": "SI joint"},{"key": "C","text": "Knee and ankle joints"},{"key": "D","text": "Hip joint"}],"correct": "C","explanation": "Tibial nerve provides articular branches to both the knee joint (in popliteal fossa) and ankle joint."},{"id": 789,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Plantarflexion against resistance with intact sensation tests integrity of:","options": [{"key": "A","text": "S1-S2 and tibial nerve"},{"key": "B","text": "S3-S4 and pudendal nerve"},{"key": "C","text": "L4-L5 and peroneal nerve"},{"key": "D","text": "L3-L4 and femoral nerve"}],"correct": "A","explanation": "Plantarflexion is primarily a tibial nerve function (gastrocnemius/soleus) testing S1-S2."},{"id": 790,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Tibial nerve posterior tarsal tunnel contents include all EXCEPT:","options": [{"key": "A","text": "Tibialis posterior tendon"},{"key": "B","text": "Tibial nerve"},{"key": "C","text": "Peroneal tendons"},{"key": "D","text": "Flexor hallucis longus tendon"}],"correct": "C","explanation": "Tarsal tunnel (posterior) contains: tibialis posterior, FDL, tibial artery/vein, tibial nerve, FHL (Tom, Dick, ANd Harry). Peroneals pass behind lateral malleolus."},{"id": 791,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Sciatic nerve high division where tibial and peroneal separate in thigh occurs in:","options": [{"key": "A","text": "5% of individuals"},{"key": "B","text": "All individuals"},{"key": "C","text": "12% of individuals"},{"key": "D","text": "50% of individuals"}],"correct": "C","explanation": "High division of sciatic nerve (separation in thigh rather than popliteal fossa) occurs in approximately 10-12% of individuals."},{"id": 792,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Tibial nerve motor branch to popliteus functions to:","options": [{"key": "A","text": "Unlock knee by internally rotating tibia"},{"key": "B","text": "Extend knee"},{"key": "C","text": "Flex knee"},{"key": "D","text": "Externally rotate tibia"}],"correct": "A","explanation": "Popliteus (supplied by tibial nerve) unlocks the fully extended knee by internally rotating the tibia (or externally rotating femur)."},{"id": 793,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Loss of toe flexion and intrinsic foot muscle function results from tibial nerve injury at:","options": [{"key": "A","text": "Plantar level"},{"key": "B","text": "Below knee but above tarsal tunnel"},{"key": "C","text": "Tarsal tunnel level"},{"key": "D","text": "Above knee (high injury)"}],"correct": "C","explanation": "Tibial nerve injury at the tarsal tunnel affects toe flexion and intrinsic muscles while preserving posterior leg muscles."},{"id": 794,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Tibial nerve supplies all posterior compartment leg muscles EXCEPT:","options": [{"key": "A","text": "Peroneus longus"},{"key": "B","text": "Soleus"},{"key": "C","text": "Popliteus"},{"key": "D","text": "Gastrocnemius"}],"correct": "A","explanation": "Peroneus (fibularis) longus is in the lateral compartment and is innervated by the superficial peroneal nerve, not tibial nerve."},{"id": 795,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Common peroneal nerve is derived from which divisions?","options": [{"key": "A","text": "Posterior divisions L2, L3, L4"},{"key": "B","text": "Posterior divisions L4, L5, S1, S2"},{"key": "C","text": "Anterior divisions L4, L5, S1, S2"},{"key": "D","text": "Anterior divisions L2, L3, L4"}],"correct": "B","explanation": "Common peroneal nerve arises from posterior divisions (dorsal divisions) of L4, L5, S1, S2 of the sciatic nerve."},{"id": 796,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Common peroneal nerve winds around:","options": [{"key": "A","text": "Head of tibia"},{"key": "B","text": "Neck of fibula"},{"key": "C","text": "Medial malleolus"},{"key": "D","text": "Lateral malleolus"}],"correct": "B","explanation": "Common peroneal nerve wraps around the posterior aspect of the fibular neck, making it vulnerable to compression."},{"id": 797,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Foot drop is caused by injury to:","options": [{"key": "A","text": "Tibial nerve"},{"key": "B","text": "Sciatic nerve at S1 level"},{"key": "C","text": "Femoral nerve"},{"key": "D","text": "Common peroneal nerve"}],"correct": "D","explanation": "Common peroneal nerve injury causes foot drop (inability to dorsiflex ankle) due to paralysis of anterior compartment muscles."},{"id": 798,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Common peroneal nerve divides into which two branches?","options": [{"key": "A","text": "Medial and lateral sural nerves"},{"key": "B","text": "Deep and superficial peroneal nerves"},{"key": "C","text": "Tibial and fibular nerves"},{"key": "D","text": "Saphenous and sural nerves"}],"correct": "B","explanation": "Common peroneal nerve divides into deep peroneal (anterior compartment) and superficial peroneal (lateral compartment) nerves."},{"id": 799,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Deep peroneal nerve supplies:","options": [{"key": "A","text": "Posterior compartment muscles"},{"key": "B","text": "Anterior compartment muscles and first web space sensation"},{"key": "C","text": "Intrinsic foot muscles"},{"key": "D","text": "Lateral compartment muscles"}],"correct": "B","explanation": "Deep peroneal nerve innervates anterior compartment (tibialis anterior, EHL, EDL, peroneus tertius) and first web space skin."},{"id": 800,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Superficial peroneal nerve supplies:","options": [{"key": "A","text": "Deep posterior leg muscles"},{"key": "B","text": "Anterior leg muscles"},{"key": "C","text": "Lateral compartment muscles and dorsum of foot sensation"},{"key": "D","text": "First web space only"}],"correct": "C","explanation": "Superficial peroneal nerve innervates peroneus longus and brevis, and provides sensation to most of the dorsum of foot."},{"id": 801,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Anterior tarsal tunnel syndrome involves compression of:","options": [{"key": "A","text": "Tibial nerve"},{"key": "B","text": "Deep peroneal nerve under inferior extensor retinaculum"},{"key": "C","text": "Superficial peroneal nerve"},{"key": "D","text": "Sural nerve"}],"correct": "B","explanation": "Anterior tarsal tunnel syndrome is entrapment of the deep peroneal nerve beneath the inferior extensor retinaculum on the dorsum of foot."},{"id": 802,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "Common peroneal nerve injury at fibular neck causes sensory loss over:","options": [{"key": "A","text": "Posterior thigh"},{"key": "B","text": "Medial leg"},{"key": "C","text": "Sole of foot"},{"key": "D","text": "Dorsum of foot and lateral leg"}],"correct": "D","explanation": "Peroneal nerve injury at the fibular neck causes sensory loss over the dorsum of foot and lateral leg."},{"id": 803,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The most common cause of common peroneal nerve palsy is:","options": [{"key": "A","text": "Prolonged leg crossing / fibular neck compression"},{"key": "B","text": "Deep vein thrombosis"},{"key": "C","text": "Diabetes"},{"key": "D","text": "L4-L5 disc herniation alone"}],"correct": "A","explanation": "External compression at the fibular neck (habitual leg crossing, prolonged squatting, plaster cast) is the most common cause."},{"id": 804,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Deep peroneal nerve provides sensation ONLY to:","options": [{"key": "A","text": "First web space (between first and second toes)"},{"key": "B","text": "Medial sole"},{"key": "C","text": "Lateral sole"},{"key": "D","text": "Lateral 2 toes"}],"correct": "A","explanation": "Deep peroneal nerve has a very limited cutaneous area: only the first dorsal web space (adjacent sides of 1st and 2nd toes)."},{"id": 805,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Foot drop gait pattern is characterized by:","options": [{"key": "A","text": "Antalgic gait"},{"key": "B","text": "Steppage gait (high stepping)"},{"key": "C","text": "Trendelenburg gait"},{"key": "D","text": "Scissor gait"}],"correct": "B","explanation": "Foot drop causes steppage gait: excessive hip and knee flexion to clear the foot during swing phase to avoid tripping."},{"id": 806,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Peroneus longus and brevis are innervated by:","options": [{"key": "A","text": "Superficial peroneal nerve"},{"key": "B","text": "Tibial nerve"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Deep peroneal nerve"}],"correct": "A","explanation": "Peroneus longus and brevis (lateral compartment) are innervated by the superficial peroneal nerve (L5, S1)."},{"id": 807,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Common peroneal nerve can be palpated at:","options": [{"key": "A","text": "Anterior knee"},{"key": "B","text": "Lateral malleolus"},{"key": "C","text": "Popliteal fossa only"},{"key": "D","text": "Posterior to the fibular head / fibular neck"}],"correct": "D","explanation": "Common peroneal nerve is palpable as it winds around the fibular neck just distal to the fibular head."},{"id": 808,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Tibialis anterior is innervated by:","options": [{"key": "A","text": "Deep peroneal nerve"},{"key": "B","text": "Tibial nerve"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Superficial peroneal nerve"}],"correct": "A","explanation": "Tibialis anterior (anterior compartment, primary ankle dorsiflexor) is innervated by the deep peroneal nerve (L4, L5)."},{"id": 809,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Extensor hallucis longus is innervated by:","options": [{"key": "A","text": "Superficial peroneal nerve"},{"key": "B","text": "Tibial nerve"},{"key": "C","text": "Deep peroneal nerve"},{"key": "D","text": "Sural nerve"}],"correct": "C","explanation": "EHL (extends great toe, assists dorsiflexion) is innervated by the deep peroneal nerve (L5)."},{"id": 810,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "L5 nerve root compression specifically weakens:","options": [{"key": "A","text": "Great toe extension (EHL) and ankle dorsiflexion"},{"key": "B","text": "Ankle plantarflexion"},{"key": "C","text": "Knee extension"},{"key": "D","text": "Foot inversion by tibialis posterior"}],"correct": "A","explanation": "L5 supplies EHL (via deep peroneal) and contributes to tibialis anterior; L5 compression causes weak great toe extension and dorsiflexion."},{"id": 811,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Superficial peroneal nerve becomes subcutaneous at:","options": [{"key": "A","text": "Knee level"},{"key": "B","text": "Ankle level"},{"key": "C","text": "Junction of middle and lower thirds of the lateral leg"},{"key": "D","text": "Fibular neck"}],"correct": "C","explanation": "Superficial peroneal nerve pierces the deep fascia at the junction of the middle and distal thirds of the lateral leg."},{"id": 812,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Lateral ankle sprain can injure:","options": [{"key": "A","text": "Saphenous nerve"},{"key": "B","text": "Tibial nerve"},{"key": "C","text": "Sural nerve and superficial peroneal nerve"},{"key": "D","text": "Deep peroneal nerve"}],"correct": "C","explanation": "Lateral ankle sprain (inversion injury) can stretch or injure the sural nerve and superficial peroneal nerve."},{"id": 813,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Common peroneal nerve injury in acute compartment syndrome of the anterior compartment causes:","options": [{"key": "A","text": "Foot drop and dorsal foot numbness"},{"key": "B","text": "Calf weakness"},{"key": "C","text": "Knee flexion weakness"},{"key": "D","text": "Loss of plantarflexion"}],"correct": "A","explanation": "Anterior compartment syndrome compresses the deep peroneal nerve, causing foot drop and first web space numbness."},{"id": 814,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Peroneal nerve conduction study for foot drop should be performed at:","options": [{"key": "A","text": "Fibular head, popliteal fossa, and below-knee sites"},{"key": "B","text": "Only popliteal fossa"},{"key": "C","text": "Ankle and below-knee sites only"},{"key": "D","text": "Thigh level only"}],"correct": "A","explanation": "NCS for peroneal nerve foot drop should include stimulation at ankle, fibular head, and popliteal fossa to localize the lesion."},{"id": 815,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "AFO (ankle-foot orthosis) is prescribed for foot drop to maintain ankle at:","options": [{"key": "A","text": "Neutral (90 degrees) or slight dorsiflexion"},{"key": "B","text": "Inversion"},{"key": "C","text": "Plantarflexion"},{"key": "D","text": "Full dorsiflexion"}],"correct": "A","explanation": "AFO for foot drop holds the ankle at neutral/slight dorsiflexion to enable clearance during swing and stable heel strike."},{"id": 816,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Hard","question": "Recurrent peroneal nerve at the ankle is a branch of:","options": [{"key": "A","text": "Tibial nerve"},{"key": "B","text": "Superficial peroneal nerve"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Deep peroneal nerve"}],"correct": "D","explanation": "Recurrent articular branch of deep peroneal nerve supplies the ankle joint."},{"id": 817,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Peroneal nerve is most vulnerable to injury at:","options": [{"key": "A","text": "Mid-thigh"},{"key": "B","text": "Popliteal fossa"},{"key": "C","text": "Fibular neck"},{"key": "D","text": "Ankle"}],"correct": "C","explanation": "The fibular neck is the most vulnerable site: nerve is superficial, fixed, and adjacent to bone — susceptible to compression/traction."},{"id": 818,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Nerve to extensor digitorum brevis is from:","options": [{"key": "A","text": "Lateral plantar nerve"},{"key": "B","text": "Superficial peroneal nerve"},{"key": "C","text": "Deep peroneal nerve"},{"key": "D","text": "Tibial nerve"}],"correct": "C","explanation": "Extensor digitorum brevis (dorsal intrinsic foot muscle) is innervated by the deep peroneal nerve (L5, S1)."},{"id": 819,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In peroneal nerve palsy, which movement is preserved?","options": [{"key": "A","text": "Great toe extension"},{"key": "B","text": "Ankle dorsiflexion"},{"key": "C","text": "Ankle plantarflexion and inversion (tibial nerve function)"},{"key": "D","text": "Foot eversion"}],"correct": "C","explanation": "Peroneal nerve palsy preserves tibial nerve functions: plantarflexion (gastrocnemius/soleus) and inversion (tibialis posterior)."},{"id": 820,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "How many cervical vertebrae are there in the human spine?","options": [{"key": "A","text": "8"},{"key": "B","text": "6"},{"key": "C","text": "7"},{"key": "D","text": "5"}],"correct": "C","explanation": "There are 7 cervical vertebrae (C1-C7), the smallest and most mobile vertebrae of the spinal column."},{"id": 821,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The atlas (C1) is unique because it has:","options": [{"key": "A","text": "Two spinous processes"},{"key": "B","text": "A large vertebral body"},{"key": "C","text": "No vertebral body and no spinous process"},{"key": "D","text": "A vertebral body and spinous process"}],"correct": "C","explanation": "Atlas has no vertebral body (replaced by anterior arch) and no true spinous process (replaced by posterior tubercle)."},{"id": 822,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The dens (odontoid process) is a projection of:","options": [{"key": "A","text": "Occiput"},{"key": "B","text": "C1 (Atlas)"},{"key": "C","text": "C2 (Axis)"},{"key": "D","text": "C3"}],"correct": "C","explanation": "The dens (odontoid process) is a toothlike projection of C2 (axis) that articulates with the anterior arch of C1."},{"id": 823,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "Which cervical vertebra has the largest and most prominent spinous process?","options": [{"key": "A","text": "C7 (vertebra prominens)"},{"key": "B","text": "C5"},{"key": "C","text": "C6"},{"key": "D","text": "C3"}],"correct": "A","explanation": "C7 is called vertebra prominens because it has the longest, most prominent non-bifid spinous process, palpable at the base of the neck."},{"id": 824,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Bifid spinous processes are a characteristic feature of which cervical vertebrae?","options": [{"key": "A","text": "C2 to C7"},{"key": "B","text": "C6 and C7"},{"key": "C","text": "C3 to C6"},{"key": "D","text": "C1 and C2"}],"correct": "C","explanation": "Cervical vertebrae C3-C6 typically have bifid (split/forked) spinous processes, unlike C7 which is non-bifid."},{"id": 825,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The transverse foramen (foramen transversarium) transmits:","options": [{"key": "A","text": "Anterior spinal artery"},{"key": "B","text": "Lymphatics only"},{"key": "C","text": "Spinal nerves"},{"key": "D","text": "Vertebral artery and vein (C1-C6)"}],"correct": "D","explanation": "Transverse foramen transmits vertebral artery, vertebral vein, and sympathetic plexus. Vertebral artery enters at C6 (typically)."},{"id": 826,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The uncinate processes (joints of Luschka) are found on:","options": [{"key": "A","text": "Sacrum"},{"key": "B","text": "Lateral aspects of cervical vertebral bodies (C3-C7)"},{"key": "C","text": "Thoracic vertebrae"},{"key": "D","text": "Lumbar vertebrae"}],"correct": "B","explanation": "Uncinate processes (uncovertebral joints/Luschka joints) are bony projections on the superolateral cervical vertebral bodies C3-C7."},{"id": 827,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The normal cervical lordosis angle is approximately:","options": [{"key": "A","text": "50-60 degrees"},{"key": "B","text": "10-20 degrees"},{"key": "C","text": "30-40 degrees"},{"key": "D","text": "0-10 degrees"}],"correct": "C","explanation": "Normal cervical lordosis measures approximately 30-40 degrees (Cobb angle C2-C7), creating the characteristic C-shaped curve."},{"id": 828,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "The vertebral artery typically enters the transverse foramen at which level?","options": [{"key": "A","text": "C5"},{"key": "B","text": "C6"},{"key": "C","text": "C7"},{"key": "D","text": "C4"}],"correct": "B","explanation": "The vertebral artery typically enters the transverse foramen at C6, though variations occur; it does NOT enter at C7."},{"id": 829,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The atlantoaxial joint (C1-C2) primarily allows which movement?","options": [{"key": "A","text": "Lateral flexion"},{"key": "B","text": "Flexion and extension"},{"key": "C","text": "Rotation (50% of total cervical rotation)"},{"key": "D","text": "Protraction"}],"correct": "C","explanation": "The atlantoaxial joint provides approximately 50% of total cervical rotation (about 45 degrees each side)."},{"id": 830,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The atlantooccipital joint (C0-C1) primarily allows:","options": [{"key": "A","text": "Lateral flexion"},{"key": "B","text": "Nodding (flexion-extension — 'yes' movement)"},{"key": "C","text": "Rotation"},{"key": "D","text": "All movements equally"}],"correct": "B","explanation": "Atlantooccipital joint allows nodding (flexion-extension), contributing about 15 degrees of flexion and 25 degrees of extension."},{"id": 831,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Superior articular facets of C1 (atlas) are oriented to articulate with:","options": [{"key": "A","text": "C3 vertebra"},{"key": "B","text": "Dens of axis"},{"key": "C","text": "C2 inferior facets (flat, horizontal)"},{"key": "D","text": "Occipital condyles (concave, facing superomedially)"}],"correct": "D","explanation": "C1 superior articular facets are concave and kidney-shaped, articulating with the convex occipital condyles."},{"id": 832,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The pedicles of cervical vertebrae project:","options": [{"key": "A","text": "Posterolaterally at an oblique angle"},{"key": "B","text": "Directly posteriorly"},{"key": "C","text": "Directly laterally"},{"key": "D","text": "Anteromedially"}],"correct": "A","explanation": "Cervical pedicles project posterolaterally, forming the boundaries of the intervertebral foramen."},{"id": 833,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Jefferson fracture involves:","options": [{"key": "A","text": "C2 dens fracture"},{"key": "B","text": "Burst fracture of C1 (atlas) ring"},{"key": "C","text": "Odontoid fracture"},{"key": "D","text": "C7 compression fracture"}],"correct": "B","explanation": "Jefferson fracture is a burst fracture of the C1 ring caused by axial loading (e.g., diving into shallow water), splitting it into fragments."},{"id": 834,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Hangman's fracture involves:","options": [{"key": "A","text": "C6-C7 dislocation"},{"key": "B","text": "Bilateral C2 pedicle fracture (traumatic spondylolisthesis of axis)"},{"key": "C","text": "Atlas fracture"},{"key": "D","text": "Dens type II fracture"}],"correct": "B","explanation": "Hangman's fracture is bilateral fracture through C2 pedicles (traumatic spondylolisthesis of axis), caused by hyperextension."},{"id": 835,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The spinal canal is largest at which cervical level?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C5"},{"key": "C","text": "C4"},{"key": "D","text": "C1"}],"correct": "D","explanation": "The spinal canal is largest at C1 (atlas) where it accommodates the dens anteriorly and spinal cord posteriorly."},{"id": 836,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Cervical disc height is greatest at which level?","options": [{"key": "A","text": "C2-C3"},{"key": "B","text": "C4-C5"},{"key": "C","text": "C5-C6"},{"key": "D","text": "C6-C7"}],"correct": "C","explanation": "C5-C6 disc is the most mobile and largest cervical disc, and most commonly herniated level."},{"id": 837,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The uncovertebral joints (Luschka) are considered:","options": [{"key": "A","text": "Fibrous joints"},{"key": "B","text": "True synovial joints from birth"},{"key": "C","text": "Acquired clefts/joints developing in second decade"},{"key": "D","text": "Cartilaginous joints"}],"correct": "C","explanation": "Luschka joints are not present at birth; they develop as acquired fissures in the lateral annulus during the second decade of life."},{"id": 838,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Most common level of cervical disc herniation is:","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "C4-C5"},{"key": "C","text": "C7-T1"},{"key": "D","text": "C3-C4"}],"correct": "A","explanation": "C5-C6 is the most common level of cervical disc herniation, affecting the C6 nerve root."},{"id": 839,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Cervical vertebrae have a characteristic triangular-shaped vertebral foramen compared to:","options": [{"key": "A","text": "Both thoracic and lumbar (oval)"},{"key": "B","text": "Thoracic (circular) and lumbar (triangular)"},{"key": "C","text": "Both thoracic and lumbar (circular)"},{"key": "D","text": "Thoracic (triangular) and lumbar (circular)"}],"correct": "B","explanation": "Cervical vertebral foramen is triangular, thoracic is circular/round (smallest), and lumbar is triangular (largest)."},{"id": 840,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The transverse process of cervical vertebrae is formed by:","options": [{"key": "A","text": "Fusion of true transverse process and costal element (costotransverse bar)"},{"key": "B","text": "Pedicle and lamina"},{"key": "C","text": "Only true transverse process"},{"key": "D","text": "Only costal element"}],"correct": "A","explanation": "Cervical transverse processes have anterior and posterior tubercles connected by a costotransverse bar (costal element) forming the transverse foramen."},{"id": 841,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "Cervical rib originates from which structure?","options": [{"key": "A","text": "C5 transverse process"},{"key": "B","text": "T1 rib"},{"key": "C","text": "C6 costal element"},{"key": "D","text": "C7 costal element (enlarged)"}],"correct": "D","explanation": "Cervical rib is an enlarged costal element of C7 vertebra that may compress the brachial plexus or subclavian artery (thoracic outlet syndrome)."},{"id": 842,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "The apophyseal (zygapophyseal/facet) joints of the cervical spine are oriented at:","options": [{"key": "A","text": "45 degrees (between horizontal and vertical)"},{"key": "B","text": "90 degrees (horizontal)"},{"key": "C","text": "Vertical (90 degrees from horizontal)"},{"key": "D","text": "Variable angles"}],"correct": "A","explanation": "Cervical facet joints are oriented at approximately 45 degrees from horizontal, allowing flexion, extension, rotation, and lateral flexion."},{"id": 843,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "The spinal cord ends (conus medullaris) at which level in adults?","options": [{"key": "A","text": "S1"},{"key": "B","text": "L1-L2"},{"key": "C","text": "L4-L5"},{"key": "D","text": "C7-T1"}],"correct": "B","explanation": "The conus medullaris typically ends at L1-L2 in adults, though the cauda equina extends to S2."},{"id": 844,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "The ratio of spinal canal diameter to vertebral body diameter (Pavlov's ratio) below which myelopathy risk increases:","options": [{"key": "A","text": "Below 0.8"},{"key": "B","text": "Below 0.5"},{"key": "C","text": "Below 1.5"},{"key": "D","text": "Below 1.0"}],"correct": "A","explanation": "Pavlov's ratio (spinal canal AP diameter / vertebral body AP diameter) below 0.8 indicates developmental canal stenosis with myelopathy risk."},{"id": 845,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The transverse ligament of the atlas holds the dens against:","options": [{"key": "A","text": "Anterior arch of C1"},{"key": "B","text": "C2 body posteriorly"},{"key": "C","text": "Occipital bone"},{"key": "D","text": "Posterior arch of C1"}],"correct": "A","explanation": "Transverse ligament holds the dens firmly against the posterior surface of the anterior arch of C1, preventing posterior subluxation."},{"id": 846,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The cruciform (cruciate) ligament of the atlas consists of:","options": [{"key": "A","text": "Transverse ligament only"},{"key": "B","text": "Alar ligaments + transverse ligament"},{"key": "C","text": "Tectorial membrane + transverse ligament"},{"key": "D","text": "Transverse ligament + superior and inferior longitudinal bands"}],"correct": "D","explanation": "Cruciform ligament = transverse ligament of atlas + superior band (to occiput) + inferior band (to C2 body)."},{"id": 847,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Alar ligaments connect:","options": [{"key": "A","text": "Dens of axis to lateral margins of foramen magnum"},{"key": "B","text": "C1 to C2"},{"key": "C","text": "C2 to C3"},{"key": "D","text": "Occiput to C1"}],"correct": "A","explanation": "Alar ligaments run from the apex of the dens to the lateral margins of the foramen magnum, limiting rotation."},{"id": 848,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The tectorial membrane is the upward continuation of:","options": [{"key": "A","text": "Ligamentum flavum"},{"key": "B","text": "Supraspinous ligament"},{"key": "C","text": "Posterior longitudinal ligament"},{"key": "D","text": "Anterior longitudinal ligament"}],"correct": "C","explanation": "Tectorial membrane is the cranial continuation of the posterior longitudinal ligament, attaching to the occipital bone."},{"id": 849,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Ligamentum flavum is composed of:","options": [{"key": "A","text": "Elastin fibers (80%) and collagen"},{"key": "B","text": "Dense irregular connective tissue"},{"key": "C","text": "Fibrocartilage"},{"key": "D","text": "Collagen type I fibers"}],"correct": "A","explanation": "Ligamentum flavum has the highest elastin content (80%) of any ligament in the body, allowing spine to return to neutral after flexion."},{"id": 850,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The posterior longitudinal ligament (PLL) is:","options": [{"key": "A","text": "Broader at disc levels, narrower at vertebral bodies"},{"key": "B","text": "Narrower at disc levels, broader at vertebral bodies"},{"key": "C","text": "Only present in cervical spine"},{"key": "D","text": "Uniform throughout"}],"correct": "A","explanation": "PLL is broad at disc levels (2x width) and narrow at vertebral bodies, making lateral disc herniation more common."},{"id": 851,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "OPLL (Ossification of Posterior Longitudinal Ligament) is most common in:","options": [{"key": "A","text": "Thoracic spine"},{"key": "B","text": "Sacrum"},{"key": "C","text": "Cervical spine"},{"key": "D","text": "Lumbar spine"}],"correct": "C","explanation": "OPLL is most common in the cervical spine, particularly in East Asian populations, causing cervical myelopathy."},{"id": 852,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The anterior atlanto-axial membrane is an extension of:","options": [{"key": "A","text": "Tectorial membrane"},{"key": "B","text": "Posterior longitudinal ligament"},{"key": "C","text": "Anterior longitudinal ligament (cranially)"},{"key": "D","text": "Ligamentum flavum"}],"correct": "C","explanation": "Anterior atlanto-axial membrane continues the anterior longitudinal ligament between the anterior arches of C1 and C2."},{"id": 853,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cervical facet joint capsule laxity contributes to:","options": [{"key": "A","text": "Cervical instability and whiplash injury"},{"key": "B","text": "Disc herniation"},{"key": "C","text": "Vertebral artery compression"},{"key": "D","text": "Cord compression"}],"correct": "A","explanation": "Facet joint capsule laxity (especially C2-C5) contributes to cervical instability following whiplash or repetitive microtrauma."},{"id": 854,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Atlanto-axial instability (AAI) is associated with:","options": [{"key": "A","text": "Ankylosing spondylitis"},{"key": "B","text": "Down syndrome (trisomy 21)"},{"key": "C","text": "Both B and C"},{"key": "D","text": "Rheumatoid arthritis only"}],"correct": "C","explanation": "AAI is associated with both Down syndrome (ligamentous laxity) and rheumatoid arthritis (synovial joint erosion of transverse ligament)."},{"id": 855,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "The intervertebral disc of the cervical spine has a relatively thin:","options": [{"key": "A","text": "Anterior annulus"},{"key": "B","text": "Annulus fibrosus in the posterior lateral region"},{"key": "C","text": "Nucleus pulposus"},{"key": "D","text": "Cartilaginous endplate"}],"correct": "B","explanation": "The posterolateral annulus is thinnest in the cervical spine, making it the most common site for disc herniation and nerve root compression."},{"id": 856,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Uncinate process hypertrophy (spondylosis) in cervical spine most commonly causes:","options": [{"key": "A","text": "Vertebral artery occlusion"},{"key": "B","text": "Foraminal stenosis and nerve root compression"},{"key": "C","text": "Disc herniation"},{"key": "D","text": "Cord compression alone"}],"correct": "B","explanation": "Osteophyte formation at the uncovertebral joints (Luschka) narrows the intervertebral foramen causing radiculopathy."},{"id": 857,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In whiplash injury, which structure is most commonly damaged?","options": [{"key": "A","text": "Vertebral artery"},{"key": "B","text": "Ligamentum flavum"},{"key": "C","text": "Anterior longitudinal ligament only"},{"key": "D","text": "Facet joint capsules and disc"}],"correct": "D","explanation": "Whiplash (hyperextension-flexion injury) primarily damages facet joint capsules, disc, and paraspinal muscles."},{"id": 858,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The intervertebral foramen of the cervical spine is bounded by:","options": [{"key": "A","text": "Pedicles above and below, disc and vertebral body anteriorly, facet joint posteriorly"},{"key": "B","text": "Only pedicles"},{"key": "C","text": "Laminae and pedicles"},{"key": "D","text": "Vertebral bodies only"}],"correct": "A","explanation": "Cervical IVF boundaries: pedicles (superior/inferior), vertebral body + disc (anterior), facet joint capsule (posterior)."},{"id": 859,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Spondylolysis in the cervical spine refers to:","options": [{"key": "A","text": "Cord compression"},{"key": "B","text": "Defect in the pars interarticularis (rare in cervical spine)"},{"key": "C","text": "Facet joint arthritis"},{"key": "D","text": "Disc degeneration"}],"correct": "B","explanation": "Spondylolysis is a stress fracture/defect in the pars interarticularis; very rare in cervical spine unlike lumbar spine."},{"id": 860,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The apical ligament of the dens connects:","options": [{"key": "A","text": "C1 to occiput"},{"key": "B","text": "Tip of dens to anterior margin of foramen magnum"},{"key": "C","text": "Dens to alar ligaments"},{"key": "D","text": "Dens to transverse ligament"}],"correct": "B","explanation": "Apical dental ligament connects the tip (apex) of the dens to the anterior margin of the foramen magnum."},{"id": 861,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Cervical spine hypomobility pattern in facet joint dysfunction causes:","options": [{"key": "A","text": "Extension most limited"},{"key": "B","text": "Capsular pattern: rotation most limited, then lateral flexion"},{"key": "C","text": "Equally limited in all directions"},{"key": "D","text": "Flexion most limited"}],"correct": "B","explanation": "Cervical facet joint restriction follows a capsular pattern with rotation most limited, followed by lateral flexion."},{"id": 862,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The intervertebral disc nucleus pulposus is composed of:","options": [{"key": "A","text": "Elastin predominantly"},{"key": "B","text": "Hydrophilic proteoglycans and Type II collagen"},{"key": "C","text": "Dense collagen (Type I)"},{"key": "D","text": "Fibrocartilage throughout"}],"correct": "B","explanation": "Nucleus pulposus contains water-attracting proteoglycans (aggrecan) and Type II collagen, giving it high water content (70-90%)."},{"id": 863,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Normal ADI (atlanto-dens interval) in adults is:","options": [{"key": "A","text": "5-10 mm"},{"key": "B","text": "Less than 1 mm"},{"key": "C","text": "Less than 3 mm"},{"key": "D","text": "Less than 5 mm"}],"correct": "C","explanation": "Normal ADI (distance between anterior arch of C1 and dens) is less than 3 mm in adults; greater than 3 mm indicates ligamentous instability."},{"id": 864,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "In children, normal ADI (atlanto-dens interval) is:","options": [{"key": "A","text": "Less than 7 mm"},{"key": "B","text": "Less than 3 mm"},{"key": "C","text": "Less than 5 mm"},{"key": "D","text": "Less than 10 mm"}],"correct": "C","explanation": "In children, normal ADI can be up to 5 mm due to greater ligamentous laxity; adults 3 mm threshold applies differently."},{"id": 865,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The cervical zygapophyseal (facet) joints are classified as:","options": [{"key": "A","text": "Condyloid joints"},{"key": "B","text": "Fibrous joints"},{"key": "C","text": "Synovial plane joints"},{"key": "D","text": "Cartilaginous joints"}],"correct": "C","explanation": "Cervical facet joints are synovial plane (gliding) joints with a joint capsule, synovial membrane, and articular cartilage."},{"id": 866,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Cervical instability is defined radiologically as translation greater than:","options": [{"key": "A","text": "3.5 mm or angulation >11 degrees"},{"key": "B","text": "2 mm"},{"key": "C","text": "5 mm"},{"key": "D","text": "1 mm"}],"correct": "A","explanation": "White and Panjabi criteria: cervical instability = translation >3.5 mm or angular difference >11 degrees on flexion-extension X-ray."},{"id": 867,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "The subaxial cervical spine (C3-C7) allows maximum rotation at which level?","options": [{"key": "A","text": "C6-C7"},{"key": "B","text": "Equal at all levels"},{"key": "C","text": "C3-C4"},{"key": "D","text": "C4-C5"}],"correct": "D","explanation": "C4-C5 level contributes significantly to cervical rotation; however, combined C3-C5 segments provide greatest subaxial rotation."},{"id": 868,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Rheumatoid arthritis affects the cervical spine most commonly at:","options": [{"key": "A","text": "C6-C7 facets"},{"key": "B","text": "Cervicothoracic junction"},{"key": "C","text": "Atlantoaxial joint (C1-C2)"},{"key": "D","text": "C5-C6 disc"}],"correct": "C","explanation": "RA most commonly causes atlantoaxial subluxation due to synovitis eroding the transverse ligament holding the dens."},{"id": 869,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The posterior atlanto-occipital membrane covers:","options": [{"key": "A","text": "Foramen magnum posteriorly and connects to C1 posterior arch"},{"key": "B","text": "Anterior foramen magnum"},{"key": "C","text": "Entire posterior cervical spine"},{"key": "D","text": "C1 to C2 posteriorly"}],"correct": "A","explanation": "Posterior atlanto-occipital membrane spans from the posterior margin of foramen magnum to the posterior arch of C1."},{"id": 870,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Sternocleidomastoid (SCM) originates from:","options": [{"key": "A","text": "Cervical vertebrae and mastoid"},{"key": "B","text": "Sternum and clavicle, inserts into mastoid process and superior nuchal line"},{"key": "C","text": "Mastoid process only"},{"key": "D","text": "Occiput and mastoid"}],"correct": "B","explanation": "SCM has two heads: sternal head (manubrium) and clavicular head, inserting into mastoid process and superior nuchal line."},{"id": 871,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Unilateral contraction of SCM produces:","options": [{"key": "A","text": "Bilateral flexion"},{"key": "B","text": "Contralateral lateral flexion only"},{"key": "C","text": "Ipsilateral rotation"},{"key": "D","text": "Ipsilateral lateral flexion and contralateral rotation"}],"correct": "D","explanation": "SCM acting unilaterally: lateral flexes head to same side and rotates face to opposite side."},{"id": 872,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "SCM is innervated by:","options": [{"key": "A","text": "Accessory nerve (CN XI) and C2, C3"},{"key": "B","text": "Vagus nerve (CN X)"},{"key": "C","text": "Hypoglossal nerve (CN XII)"},{"key": "D","text": "Facial nerve (CN VII)"}],"correct": "A","explanation": "SCM is supplied by spinal accessory nerve (CN XI) for motor function and C2, C3 for proprioception/pain."},{"id": 873,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The deepest layer of cervical muscles (suboccipital muscles) includes:","options": [{"key": "A","text": "Longus colli and longus capitis"},{"key": "B","text": "Rectus capitis posterior major/minor and obliquus capitis superior/inferior"},{"key": "C","text": "Semispinalis capitis and splenius"},{"key": "D","text": "Trapezius and SCM"}],"correct": "B","explanation": "Suboccipital muscles: rectus capitis posterior major, rectus capitis posterior minor, obliquus capitis superior, obliquus capitis inferior."},{"id": 874,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The suboccipital triangle is bounded by:","options": [{"key": "A","text": "Three SCM muscles"},{"key": "B","text": "Trapezius and semispinalis"},{"key": "C","text": "Splenius capitis and semispinalis"},{"key": "D","text": "Rectus capitis posterior major, obliquus capitis superior, obliquus capitis inferior"}],"correct": "D","explanation": "Suboccipital triangle borders: RCP major (medial), obliquus superior (lateral), obliquus inferior (inferior); contains vertebral artery and suboccipital nerve."},{"id": 875,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The suboccipital nerve (C1 dorsal ramus) supplies:","options": [{"key": "A","text": "Suboccipital muscles (motor only)"},{"key": "B","text": "Semispinalis capitis"},{"key": "C","text": "SCM and trapezius"},{"key": "D","text": "Skin of posterior head"}],"correct": "A","explanation": "C1 dorsal ramus (suboccipital nerve) is purely motor, supplying the four suboccipital muscles with no cutaneous branch."},{"id": 876,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Longus colli and longus capitis are:","options": [{"key": "A","text": "Superficial flexors"},{"key": "B","text": "Posterior cervical muscles"},{"key": "C","text": "Lateral cervical muscles"},{"key": "D","text": "Deep anterior (prevertebral) cervical flexors"}],"correct": "D","explanation": "Longus colli and longus capitis are deep prevertebral muscles — primary deep cervical flexors stabilizing the craniovertebral junction."},{"id": 877,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cranio-cervical flexion test (CCFT) assesses the function of:","options": [{"key": "A","text": "SCM and anterior scalenes"},{"key": "B","text": "Trapezius upper fibers"},{"key": "C","text": "Suboccipital muscles"},{"key": "D","text": "Deep cervical flexors (longus colli, longus capitis)"}],"correct": "D","explanation": "CCFT uses pressure biofeedback to assess deep cervical flexor (longus colli/capitis) activation during nodding, important in neck pain."},{"id": 878,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The scalene muscles originate from cervical transverse processes and insert into:","options": [{"key": "A","text": "First and second ribs"},{"key": "B","text": "Clavicle"},{"key": "C","text": "Sternum"},{"key": "D","text": "Manubrium"}],"correct": "A","explanation": "Anterior and middle scalenes insert into the first rib; posterior scalene inserts into the second rib."},{"id": 879,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scalene muscles function as:","options": [{"key": "A","text": "Primary cervical flexors"},{"key": "B","text": "Neck rotators only"},{"key": "C","text": "Primary cervical extensors"},{"key": "D","text": "Accessory inspiratory muscles and lateral cervical flexors"}],"correct": "D","explanation": "Scalenes elevate the first and second ribs (inspiration) and flex/laterally flex the cervical spine."},{"id": 880,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Cervical scalene muscle tightness can compress the brachial plexus causing:","options": [{"key": "A","text": "Thoracic outlet syndrome"},{"key": "B","text": "Carpal tunnel syndrome"},{"key": "C","text": "Cervical myelopathy"},{"key": "D","text": "Ulnar nerve entrapment at elbow"}],"correct": "A","explanation": "Tight scalenes can compress the brachial plexus between anterior and middle scalenes (interscalene triangle), causing thoracic outlet syndrome."},{"id": 881,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Trapezius is innervated by:","options": [{"key": "A","text": "Long thoracic nerve"},{"key": "B","text": "C3, C4 nerve roots only"},{"key": "C","text": "Dorsal scapular nerve"},{"key": "D","text": "Spinal accessory nerve (CN XI) and C3, C4"}],"correct": "D","explanation": "Trapezius is supplied by spinal accessory nerve (CN XI) for motor and C3, C4 for proprioception and sensation."},{"id": 882,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Semispinalis capitis is the largest muscle of the:","options": [{"key": "A","text": "Lateral neck"},{"key": "B","text": "Posterior neck (nuchal region)"},{"key": "C","text": "Deep prevertebral region"},{"key": "D","text": "Anterior neck"}],"correct": "B","explanation": "Semispinalis capitis is the largest and most superficial of the deep cervical extensors in the posterior neck."},{"id": 883,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The greater occipital nerve (C2 dorsal ramus) supplies:","options": [{"key": "A","text": "Face and forehead"},{"key": "B","text": "Posterior scalp sensation and suboccipital area"},{"key": "C","text": "Anterior scalp"},{"key": "D","text": "Anterior neck skin"}],"correct": "B","explanation": "Greater occipital nerve (medial branch of C2 dorsal ramus) supplies sensation to posterior scalp up to vertex of head."},{"id": 884,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Occipital neuralgia involves irritation of:","options": [{"key": "A","text": "Supraorbital nerve"},{"key": "B","text": "Lesser occipital nerve only"},{"key": "C","text": "Auriculotemporal nerve"},{"key": "D","text": "Greater occipital nerve (C2)"}],"correct": "D","explanation": "Occipital neuralgia is characterized by paroxysmal shooting pain in the C2 (greater occipital nerve) distribution over the posterior scalp."},{"id": 885,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The nerve to subclavius and phrenic nerve arise from:","options": [{"key": "A","text": "Brachial plexus"},{"key": "B","text": "Cranial nerves"},{"key": "C","text": "Thoracic plexus"},{"key": "D","text": "Cervical plexus (C3, C4, C5)"}],"correct": "D","explanation": "Phrenic nerve arises from C3, C4, C5 (cervical plexus); C4 is the primary root. Nerve to subclavius from C5."},{"id": 886,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "During cervical stabilization exercises, the 'chin tuck' exercise activates:","options": [{"key": "A","text": "Upper trapezius and SCM"},{"key": "B","text": "Suboccipital extensors"},{"key": "C","text": "Scalenes primarily"},{"key": "D","text": "Deep cervical flexors (longus colli)"}],"correct": "D","explanation": "Chin tuck (craniocervical flexion) activates deep cervical flexors (especially longus colli) and inhibits superficial flexors (SCM)."},{"id": 887,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Levator scapulae originates from:","options": [{"key": "A","text": "Occiput and C1"},{"key": "B","text": "Spinous processes C4-C7"},{"key": "C","text": "Spinous processes C1-C4"},{"key": "D","text": "Transverse processes C1-C4"}],"correct": "D","explanation": "Levator scapulae originates from transverse processes of C1-C4 and inserts into the medial border/superior angle of the scapula."},{"id": 888,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Splenius capitis muscle action:","options": [{"key": "A","text": "Only lateral flexion"},{"key": "B","text": "Bilateral — flex neck; unilateral — rotate to opposite side"},{"key": "C","text": "Bilateral — extend head and neck; unilateral — rotate and laterally flex to same side"},{"key": "D","text": "Protrudes head forward"}],"correct": "C","explanation": "Splenius capitis bilaterally extends the head; unilaterally it rotates and laterally flexes the head to the same side."},{"id": 889,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The anterior scalene muscle interval (interscalene triangle) is bounded by:","options": [{"key": "A","text": "Scalenes and SCM"},{"key": "B","text": "Two scalenes and clavicle"},{"key": "C","text": "Anterior scalene (medially), middle scalene (laterally), first rib (inferiorly)"},{"key": "D","text": "SCM anteriorly, trapezius posteriorly"}],"correct": "C","explanation": "Interscalene triangle: anterior scalene medially, middle scalene laterally, first rib inferiorly — brachial plexus and subclavian artery pass through it."},{"id": 890,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Multifidus in the cervical spine plays a primary role in:","options": [{"key": "A","text": "Neck rotation"},{"key": "B","text": "Intersegmental stability and proprioception"},{"key": "C","text": "Head extension"},{"key": "D","text": "Gross movement generation"}],"correct": "B","explanation": "Cervical multifidus provides fine intersegmental control and spinal stability; its dysfunction is associated with chronic neck pain."},{"id": 891,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Easy","question": "Torticollis (wry neck) most commonly involves spasm of:","options": [{"key": "A","text": "Levator scapulae"},{"key": "B","text": "Scalenes"},{"key": "C","text": "SCM (sternocleidomastoid)"},{"key": "D","text": "Trapezius"}],"correct": "C","explanation": "Torticollis presents with head tilted to ipsilateral side and face rotated to contralateral side due to SCM spasm/contracture."},{"id": 892,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Congenital muscular torticollis is caused by:","options": [{"key": "A","text": "SCM nerve palsy"},{"key": "B","text": "Suboccipital muscle spasm"},{"key": "C","text": "C1-C2 bony anomaly"},{"key": "D","text": "Fibrosis of SCM (from birth trauma or ischemia)"}],"correct": "D","explanation": "Congenital muscular torticollis results from fibrosis and shortening of the SCM, often from difficult delivery or intrauterine positioning."},{"id": 893,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The rectus capitis posterior minor connects:","options": [{"key": "A","text": "C1 lateral mass to occiput"},{"key": "B","text": "C2 to C1"},{"key": "C","text": "C1 posterior tubercle to occiput (medial inferior nuchal line)"},{"key": "D","text": "C2 spinous process to occiput"}],"correct": "C","explanation": "Rectus capitis posterior minor originates from C1 posterior tubercle and inserts into medial inferior nuchal line of occiput."},{"id": 894,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which muscle group is responsible for forward head posture perpetuation?","options": [{"key": "A","text": "SCM bilaterally"},{"key": "B","text": "Deep cervical flexors"},{"key": "C","text": "Suboccipital extensors and upper trapezius (short/tight)"},{"key": "D","text": "Scalene muscles"}],"correct": "C","explanation": "Forward head posture involves tight suboccipital extensors/upper trapezius and weak deep cervical flexors, creating a characteristic muscle imbalance."},{"id": 895,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The cervical plexus is formed by ventral rami of:","options": [{"key": "A","text": "C1-C4"},{"key": "B","text": "C2-C5"},{"key": "C","text": "C1-C5"},{"key": "D","text": "C1-C3"}],"correct": "A","explanation": "Cervical plexus is formed by the ventral (anterior) rami of C1-C4 spinal nerves."},{"id": 896,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "The brachial plexus is formed by ventral rami of:","options": [{"key": "A","text": "C4-C8"},{"key": "B","text": "C5-T1"},{"key": "C","text": "C4-T1"},{"key": "D","text": "C5-T2"}],"correct": "B","explanation": "Brachial plexus arises from ventral rami of C5, C6, C7, C8, and T1 nerve roots."},{"id": 897,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "C5 nerve root compression (C4-C5 disc) causes weakness of:","options": [{"key": "A","text": "Elbow extension"},{"key": "B","text": "Shoulder abduction (deltoid) and elbow flexion"},{"key": "C","text": "Wrist extensors"},{"key": "D","text": "Finger extensors"}],"correct": "B","explanation": "C5 radiculopathy: weakness of deltoid (axillary n.) and biceps (musculocutaneous n.) with sensory loss over lateral arm."},{"id": 898,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "C6 nerve root compression (C5-C6 disc) causes weakness of:","options": [{"key": "A","text": "Wrist extension (ECRL, ECRB) and elbow flexion, with lateral forearm/thumb numbness"},{"key": "B","text": "Finger extension"},{"key": "C","text": "Elbow extension and wrist flexion"},{"key": "D","text": "Intrinsic hand muscles"}],"correct": "A","explanation": "C6 radiculopathy: weak wrist extensors and biceps, reduced brachioradialis reflex, sensory loss in lateral forearm, thumb and index finger."},{"id": 899,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "C7 nerve root compression (C6-C7 disc) causes weakness of:","options": [{"key": "A","text": "Intrinsic hand muscles"},{"key": "B","text": "Elbow extension (triceps) and wrist flexion, with middle finger numbness"},{"key": "C","text": "Wrist extension"},{"key": "D","text": "Shoulder abduction"}],"correct": "B","explanation": "C7 radiculopathy: weak triceps and wrist flexors, reduced triceps reflex, sensory loss in middle finger."},{"id": 900,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "C8 nerve root compression (C7-T1 disc) causes:","options": [{"key": "A","text": "Shoulder weakness"},{"key": "B","text": "Intrinsic hand muscle weakness (interossei) with medial forearm/ring-little finger numbness"},{"key": "C","text": "Wrist extension weakness"},{"key": "D","text": "Biceps weakness"}],"correct": "B","explanation": "C8 radiculopathy: weak intrinsics (finger abduction/adduction), reduced finger flexor reflex, sensory loss in medial forearm and ring/little fingers."},{"id": 901,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The reflex tested for C5-C6 level is:","options": [{"key": "A","text": "Biceps and brachioradialis reflex"},{"key": "B","text": "Triceps reflex"},{"key": "C","text": "Jaw jerk"},{"key": "D","text": "Finger flexor reflex"}],"correct": "A","explanation": "Biceps reflex tests C5-C6; brachioradialis reflex primarily tests C6."},{"id": 902,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "The triceps reflex tests which nerve root?","options": [{"key": "A","text": "C5"},{"key": "B","text": "C6"},{"key": "C","text": "C8"},{"key": "D","text": "C7"}],"correct": "D","explanation": "Triceps jerk tests C7 nerve root via the radial nerve."},{"id": 903,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Horner's syndrome in cervical spine lesions involves:","options": [{"key": "A","text": "C3-C4 level"},{"key": "B","text": "C5-C6 sympathetic fibers"},{"key": "C","text": "Vagus nerve"},{"key": "D","text": "C8-T1 sympathetic fiber involvement (stellate ganglion)"}],"correct": "D","explanation": "Cervical sympathetic chain (stellate ganglion at C7-T1) injury causes Horner's: ptosis, miosis, anhidrosis, enophthalmos."},{"id": 904,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The phrenic nerve (C3, C4, C5) innervates the diaphragm; injury above C4 causes:","options": [{"key": "A","text": "Partial respiratory weakness"},{"key": "B","text": "No respiratory effect"},{"key": "C","text": "Intercostal muscle weakness only"},{"key": "D","text": "Complete respiratory paralysis (ventilator dependence)"}],"correct": "D","explanation": "Complete cervical cord injury above C4 paralyzes the phrenic nerve, causing apnea and requiring mechanical ventilation."},{"id": 905,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cervical myelopathy signs include all EXCEPT:","options": [{"key": "A","text": "Hoffman's sign"},{"key": "B","text": "L'hermitte's sign"},{"key": "C","text": "Hyporeflexia below lesion"},{"key": "D","text": "Hyperreflexia below lesion"}],"correct": "C","explanation": "Myelopathy (UMN lesion) causes hyperreflexia, positive Hoffman's sign, L'hermitte's sign, and clonus — NOT hyporeflexia."},{"id": 906,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Hoffman's sign tests for:","options": [{"key": "A","text": "Upper motor neuron lesion (cervical myelopathy)"},{"key": "B","text": "Lower motor neuron lesion"},{"key": "C","text": "Peripheral neuropathy"},{"key": "D","text": "Nerve root compression"}],"correct": "A","explanation": "Hoffman's sign: flicking the middle fingernail produces reflex flexion of thumb and index finger, indicating UMN/myelopathy."},{"id": 907,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "L'hermitte's sign (barber chair phenomenon) is:","options": [{"key": "A","text": "Arm pain with Valsalva"},{"key": "B","text": "Shoulder pain with rotation"},{"key": "C","text": "Pain on neck extension radiating to arms"},{"key": "D","text": "Electric shock-like sensation down the spine with neck flexion"}],"correct": "D","explanation": "L'hermitte's sign: neck flexion causes electric shock-like sensation down the spine/limbs due to mechanical irritation of posterior columns."},{"id": 908,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Spurling's test (cervical compression test) is positive when:","options": [{"key": "A","text": "Distraction relieves arm pain"},{"key": "B","text": "Axial compression + lateral flexion toward symptomatic side reproduces arm pain"},{"key": "C","text": "Pain increases with neck flexion"},{"key": "D","text": "Rotation away from pain reproduces symptoms"}],"correct": "B","explanation": "Spurling's: axial load with lateral flexion toward painful side narrows the foramen and reproduces radicular arm pain."},{"id": 909,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Cervical distraction test is positive when:","options": [{"key": "A","text": "Arm pain increases with traction"},{"key": "B","text": "Arm pain is relieved by manual traction (reduces foraminal compression)"},{"key": "C","text": "Neck pain increases"},{"key": "D","text": "Headache worsens"}],"correct": "B","explanation": "Cervical distraction test: manual upward traction opens the foramina; relief of arm/radicular pain = positive (suggests radiculopathy)."},{"id": 910,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Upper limb tension test (ULTT1) primarily tests which nerve?","options": [{"key": "A","text": "Median nerve (C6, C7)"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "A","explanation": "ULTT1 (median nerve bias): shoulder depression, abduction, ER, elbow extension, wrist/finger extension — tests median nerve mechanosensitivity."},{"id": 911,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The dorsal root ganglion (DRG) of cervical nerve roots is located:","options": [{"key": "A","text": "Within the vertebral canal only"},{"key": "B","text": "In the intervertebral foramen"},{"key": "C","text": "Posterior to the vertebral body"},{"key": "D","text": "Within the spinal cord"}],"correct": "B","explanation": "DRG is located in the intervertebral foramen (or just medial to it), making it susceptible to compression from disc herniation or osteophytes."},{"id": 912,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "C2 nerve root emerges between:","options": [{"key": "A","text": "C1 posterior arch"},{"key": "B","text": "C1 and C2 (above C2 pedicle)"},{"key": "C","text": "Occiput and C1"},{"key": "D","text": "C2 and C3"}],"correct": "B","explanation": "C2 nerve root emerges between the posterior arch of C1 and the lamina of C2 (above C2 pedicle), unlike lower cervical roots."},{"id": 913,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "In the cervical spine, nerve roots exit:","options": [{"key": "A","text": "Between same-numbered vertebrae"},{"key": "B","text": "Above their corresponding vertebrae (C1 exits above C1)"},{"key": "C","text": "Below their corresponding vertebrae except C1-C7 exit above; C8 exits below C7"},{"key": "D","text": "Always below the corresponding vertebra"}],"correct": "C","explanation": "C1-C7 roots exit above their corresponding vertebra; C8 exits between C7 and T1 (there is no C8 vertebra)."},{"id": 914,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The greater auricular nerve (C2, C3) supplies sensation to:","options": [{"key": "A","text": "Posterior scalp"},{"key": "B","text": "Skin over parotid, ear, and angle of mandible"},{"key": "C","text": "Anterior neck"},{"key": "D","text": "Skin of upper chest"}],"correct": "B","explanation": "Greater auricular nerve (cervical plexus C2, C3) supplies skin over parotid gland, lower ear, and angle of mandible."},{"id": 915,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Axillary nerve (C5, C6) arises from:","options": [{"key": "A","text": "Cervical plexus"},{"key": "B","text": "Posterior cord of brachial plexus"},{"key": "C","text": "Lateral cord of brachial plexus"},{"key": "D","text": "Medial cord of brachial plexus"}],"correct": "B","explanation": "Axillary nerve arises from the posterior cord (C5, C6) of brachial plexus and supplies deltoid and teres minor."},{"id": 916,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Erb's palsy (upper brachial plexus palsy) involves:","options": [{"key": "A","text": "C8, T1 roots"},{"key": "B","text": "C5, C6 roots"},{"key": "C","text": "C6, C7 roots"},{"key": "D","text": "C7 root isolated"}],"correct": "B","explanation": "Erb's palsy results from traction injury to C5-C6 roots; classic 'waiter's tip' position: arm adducted, IR, extended, pronated."},{"id": 917,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Klumpke's palsy (lower brachial plexus palsy) involves:","options": [{"key": "A","text": "C5, C6 roots"},{"key": "B","text": "C5, C6, C7 roots"},{"key": "C","text": "C7 root only"},{"key": "D","text": "C8, T1 roots (with possible Horner's syndrome)"}],"correct": "D","explanation": "Klumpke's palsy (C8-T1) causes intrinsic hand weakness and claw hand; Horner's syndrome if T1 sympathetic fibers involved."},{"id": 918,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Thoracic outlet syndrome involving neurogenic type most commonly compresses:","options": [{"key": "A","text": "Lower trunk of brachial plexus (C8-T1) at thoracic outlet"},{"key": "B","text": "Median nerve in carpal tunnel"},{"key": "C","text": "Ulnar nerve at cubital tunnel"},{"key": "D","text": "Radial nerve at lateral epicondyle"}],"correct": "A","explanation": "Neurogenic TOS compresses the lower trunk (C8-T1) between anterior/middle scalenes or cervical rib, causing medial arm/hand symptoms."},{"id": 919,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The nerve root most commonly affected in cervical disc herniation is:","options": [{"key": "A","text": "C5"},{"key": "B","text": "C8"},{"key": "C","text": "C6 (at C5-C6 level)"},{"key": "D","text": "C4"}],"correct": "C","explanation": "C6 nerve root is most commonly compressed in cervical disc herniation (C5-C6 being the most common herniation level)."},{"id": 920,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "How many thoracic vertebrae are present in human spine?","options": [{"key": "A","text": "12"},{"key": "B","text": "7"},{"key": "C","text": "14"},{"key": "D","text": "10"}],"correct": "A","explanation": "Thoracic spine has 12 vertebrae (T1-T12), each articulating with a pair of ribs."},{"id": 921,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which feature is unique to thoracic vertebrae?","options": [{"key": "A","text": "Transverse foramen"},{"key": "B","text": "Large vertebral body"},{"key": "C","text": "Bifid spinous process"},{"key": "D","text": "Costal facets for rib articulation"}],"correct": "D","explanation": "Costal facets (superior, inferior, and transverse) are unique to thoracic vertebrae for rib attachment."},{"id": 922,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The spinous processes of mid-thoracic vertebrae (T5-T8) are directed:","options": [{"key": "A","text": "Superiorly"},{"key": "B","text": "Laterally"},{"key": "C","text": "Steeply inferiorly"},{"key": "D","text": "Horizontally"}],"correct": "C","explanation": "T5-T8 spinous processes are steeply inferiorly directed, overlapping the vertebra below."},{"id": 923,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Which thoracic vertebra has the longest spinous process?","options": [{"key": "A","text": "T7"},{"key": "B","text": "T12"},{"key": "C","text": "T10"},{"key": "D","text": "T1"}],"correct": "A","explanation": "T7 has the longest and most inferiorly directed spinous process in the thoracic region."},{"id": 924,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "The vertebra prominens refers to which vertebra?","options": [{"key": "A","text": "T1"},{"key": "B","text": "T2"},{"key": "C","text": "C7"},{"key": "D","text": "C6"}],"correct": "C","explanation": "C7 is called vertebra prominens due to its long, non-bifid spinous process, easily palpable."},{"id": 925,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which thoracic vertebrae have ONLY superior and inferior costal facets (no transverse costal facet)?","options": [{"key": "A","text": "T1 and T2"},{"key": "B","text": "T3 and T4"},{"key": "C","text": "T5 and T6"},{"key": "D","text": "T10, T11, T12"}],"correct": "D","explanation": "T10-T12 ribs articulate only with the body (not transverse process), so no transverse costal facets."},{"id": 926,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The pedicles of thoracic vertebrae arise from:","options": [{"key": "A","text": "Posterior body"},{"key": "B","text": "Junction of body and lamina"},{"key": "C","text": "Transverse process"},{"key": "D","text": "Upper part of vertebral body"}],"correct": "D","explanation": "Pedicles arise from the upper part of the posterior surface of vertebral body in thoracic region."},{"id": 927,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "T1 vertebra resembles which cervical vertebra in structure?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C3"},{"key": "C","text": "C4"},{"key": "D","text": "C5"}],"correct": "A","explanation": "T1 has a long non-bifid spinous process and a large superior costal facet, resembling C7."},{"id": 928,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which feature distinguishes T12 from other thoracic vertebrae?","options": [{"key": "A","text": "Has transverse foramen"},{"key": "B","text": "Has no costal facets"},{"key": "C","text": "Has inferior articular facets like lumbar"},{"key": "D","text": "Has bifid spinous process"}],"correct": "C","explanation": "T12 has inferior articular facets oriented like lumbar vertebrae (laterally facing), aiding transition."},{"id": 929,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The superior costal facets of thoracic vertebrae are located:","options": [{"key": "A","text": "On inferior pedicle"},{"key": "B","text": "On transverse process"},{"key": "C","text": "On upper posterolateral body"},{"key": "D","text": "On lamina"}],"correct": "C","explanation": "Superior costal facets are on the upper posterolateral part of the vertebral body."},{"id": 930,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "How many lumbar vertebrae are typically present?","options": [{"key": "A","text": "3"},{"key": "B","text": "6"},{"key": "C","text": "5"},{"key": "D","text": "4"}],"correct": "C","explanation": "There are 5 lumbar vertebrae (L1-L5) in the normal human spine."},{"id": 931,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "The largest vertebrae in the vertebral column are:","options": [{"key": "A","text": "Lumbar"},{"key": "B","text": "Thoracic"},{"key": "C","text": "Cervical"},{"key": "D","text": "Sacral"}],"correct": "A","explanation": "Lumbar vertebrae have the largest and most massive bodies to bear maximum body weight."},{"id": 932,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The accessory process in lumbar vertebrae is a remnant of:","options": [{"key": "A","text": "Spinous process"},{"key": "B","text": "Costal element"},{"key": "C","text": "Superior articular process"},{"key": "D","text": "Transverse process"}],"correct": "B","explanation": "The accessory process is a remnant of the true transverse process (costal element)."},{"id": 933,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The mamillary process is found on which structure of lumbar vertebra?","options": [{"key": "A","text": "Superior articular process"},{"key": "B","text": "Transverse process"},{"key": "C","text": "Inferior articular process"},{"key": "D","text": "Spinous process"}],"correct": "A","explanation": "Mamillary process is a bony projection on the posterior surface of the superior articular process."},{"id": 934,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The orientation of lumbar facet joints is:","options": [{"key": "A","text": "Coronal plane"},{"key": "B","text": "Sagittal/parasagittal plane"},{"key": "C","text": "Sagittal plane"},{"key": "D","text": "Oblique 45°"}],"correct": "B","explanation": "Lumbar facets are oriented in the sagittal/parasagittal plane, limiting rotation but allowing flexion/extension."},{"id": 935,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Which lumbar vertebra is most commonly involved in spondylolysis?","options": [{"key": "A","text": "L1"},{"key": "B","text": "L3"},{"key": "C","text": "L2"},{"key": "D","text": "L5"}],"correct": "D","explanation": "L5 is most commonly affected in spondylolysis, a defect in the pars interarticularis."},{"id": 936,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The lumbosacral angle is normally:","options": [{"key": "A","text": "20-22°"},{"key": "B","text": "10-15°"},{"key": "C","text": "45-50°"},{"key": "D","text": "30-34°"}],"correct": "D","explanation": "Normal lumbosacral angle (Ferguson's angle) is approximately 30-34°."},{"id": 937,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The transverse processes of lumbar vertebrae are homologous to:","options": [{"key": "A","text": "Costal processes (rudimentary ribs)"},{"key": "B","text": "Ribs"},{"key": "C","text": "Laminae"},{"key": "D","text": "Pedicles"}],"correct": "A","explanation": "Lumbar transverse processes are costal processes — homologous to rudimentary ribs."},{"id": 938,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "L5-S1 facet joint orientation is:","options": [{"key": "A","text": "Horizontal"},{"key": "B","text": "More coronal"},{"key": "C","text": "More sagittal"},{"key": "D","text": "Pure transverse"}],"correct": "B","explanation": "L5-S1 facets are more coronally oriented compared to upper lumbar levels, aiding stability."},{"id": 939,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The spinal canal is largest in which region?","options": [{"key": "A","text": "Lumbar"},{"key": "B","text": "Equal throughout"},{"key": "C","text": "Thoracic"},{"key": "D","text": "Cervical"}],"correct": "A","explanation": "The lumbar spinal canal is the largest in cross-sectional area among all vertebral regions."},{"id": 940,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The nucleus pulposus is derived from:","options": [{"key": "A","text": "Dermatome"},{"key": "B","text": "Neural crest"},{"key": "C","text": "Notochord"},{"key": "D","text": "Sclerotome"}],"correct": "C","explanation": "Nucleus pulposus is a remnant of the embryonic notochord, present in the center of the disc."},{"id": 941,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The annulus fibrosus is composed of:","options": [{"key": "A","text": "Dense irregular CT"},{"key": "B","text": "Hyaline cartilage"},{"key": "C","text": "Fibrocartilage with concentric lamellae"},{"key": "D","text": "Elastic cartilage"}],"correct": "C","explanation": "Annulus fibrosus consists of fibrocartilage arranged in concentric lamellae (15-25 layers)."},{"id": 942,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "What percentage of intervertebral disc is water in young adults?","options": [{"key": "A","text": "20-30%"},{"key": "B","text": "70-90%"},{"key": "C","text": "40-50%"},{"key": "D","text": "50-60%"}],"correct": "B","explanation": "Nucleus pulposus in young adults is 70-90% water, providing hydrostatic pressure and shock absorption."},{"id": 943,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The annular fibers in adjacent lamellae are oriented at approximately:","options": [{"key": "A","text": "Same direction"},{"key": "B","text": "Alternating 30° to disc plane"},{"key": "C","text": "45° to each other"},{"key": "D","text": "90° to each other"}],"correct": "B","explanation": "Adjacent lamellae have fibers alternating at ~30° inclinations, resisting torsional forces."},{"id": 944,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which region has the thinnest intervertebral discs?","options": [{"key": "A","text": "Lumbar"},{"key": "B","text": "Thoracic"},{"key": "C","text": "Cervical"},{"key": "D","text": "Lumbosacral"}],"correct": "B","explanation": "Thoracic discs are the thinnest, being approximately 5mm in height."},{"id": 945,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The disc-to-vertebral body height ratio is greatest in:","options": [{"key": "A","text": "Sacral region"},{"key": "B","text": "Cervical region"},{"key": "C","text": "Thoracic region"},{"key": "D","text": "Lumbar region"}],"correct": "D","explanation": "Lumbar region has the highest disc-to-body ratio (~1:3), contributing to greater mobility."},{"id": 946,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The cartilaginous endplate functions to:","options": [{"key": "A","text": "Provide rotation"},{"key": "B","text": "Connect disc to periosteum"},{"key": "C","text": "Allow nutrient diffusion and anchor disc"},{"key": "D","text": "None of the above"}],"correct": "C","explanation": "Endplates allow nutrient diffusion (discs are avascular) and anchor the disc to adjacent vertebral bodies."},{"id": 947,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Disc herniation most commonly occurs in which direction?","options": [{"key": "A","text": "Direct posterior"},{"key": "B","text": "Lateral"},{"key": "C","text": "Posterolateral"},{"key": "D","text": "Anterior"}],"correct": "C","explanation": "Posterolateral herniation is most common as the posterior longitudinal ligament is thinner/absent here."},{"id": 948,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which spinal level has the highest incidence of disc herniation?","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "L1-L2"},{"key": "C","text": "T10-T11"},{"key": "D","text": "L4-L5 and L5-S1"}],"correct": "D","explanation": "L4-L5 and L5-S1 account for >90% of lumbar disc herniations due to maximum stress."},{"id": 949,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The nucleus pulposus in adults is avascular and receives nutrition by:","options": [{"key": "A","text": "Imbibition and diffusion"},{"key": "B","text": "Venous plexus"},{"key": "C","text": "Direct arterial supply"},{"key": "D","text": "Lymphatics"}],"correct": "A","explanation": "Avascular nucleus pulposus receives nutrients by diffusion and imbibition through cartilaginous endplates."},{"id": 950,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Schmorl's nodes represent:","options": [{"key": "A","text": "Osteophyte formation"},{"key": "B","text": "Herniation of disc into vertebral body"},{"key": "C","text": "Disc calcification"},{"key": "D","text": "Annular tear"}],"correct": "B","explanation": "Schmorl's nodes are vertical disc herniations through the endplate into the vertebral body."},{"id": 951,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The outer one-third of annulus fibrosus is innervated by:","options": [{"key": "A","text": "Both A and B"},{"key": "B","text": "Posterior primary ramus"},{"key": "C","text": "Recurrent meningeal nerve"},{"key": "D","text": "Sinuvertebral nerve"}],"correct": "A","explanation": "Both the sinuvertebral (recurrent meningeal) nerve innervates the outer annulus, making tears painful."},{"id": 952,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The largest disc in the spine is located at:","options": [{"key": "A","text": "L5-S1"},{"key": "B","text": "C5-C6"},{"key": "C","text": "L4-L5"},{"key": "D","text": "T12-L1"}],"correct": "A","explanation": "L5-S1 has the largest intervertebral disc in the spine in terms of cross-sectional area."},{"id": 953,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "During aging, nucleus pulposus becomes:","options": [{"key": "A","text": "Fibrotic and dehydrated"},{"key": "B","text": "More hydrated"},{"key": "C","text": "Softer and gelatinous"},{"key": "D","text": "More vascular"}],"correct": "A","explanation": "With aging, nucleus pulposus loses water content, becomes fibrotic, reducing shock-absorbing capacity."},{"id": 954,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Intradiscal pressure is highest during:","options": [{"key": "A","text": "Sitting with flexion"},{"key": "B","text": "Lying supine"},{"key": "C","text": "Standing"},{"key": "D","text": "Walking"}],"correct": "A","explanation": "Sitting with forward flexion produces the highest intradiscal pressure (Nachemson's studies)."},{"id": 955,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The anterior longitudinal ligament (ALL) extends from:","options": [{"key": "A","text": "Occiput to sacrum"},{"key": "B","text": "C1 to sacrum"},{"key": "C","text": "C3 to L5"},{"key": "D","text": "Atlas to coccyx"}],"correct": "A","explanation": "ALL extends from the basilar part of occiput (anterior tubercle of atlas) to the sacrum."},{"id": 956,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The posterior longitudinal ligament (PLL) is broader at:","options": [{"key": "A","text": "Lower lumbar levels"},{"key": "B","text": "Mid-thoracic"},{"key": "C","text": "Cervical region"},{"key": "D","text": "Upper levels"}],"correct": "D","explanation": "PLL is broader superiorly and becomes narrower at lower lumbar levels, predisposing to posterolateral disc herniation."},{"id": 957,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The ligamentum flavum is composed predominantly of:","options": [{"key": "A","text": "Collagen type II"},{"key": "B","text": "Collagen type I"},{"key": "C","text": "Fibrocartilage"},{"key": "D","text": "Elastin fibers"}],"correct": "D","explanation": "Ligamentum flavum is ~80% elastin, giving it yellow color and elasticity, preventing disc buckling during extension."},{"id": 958,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Ligamentum flavum connects:","options": [{"key": "A","text": "Transverse processes"},{"key": "B","text": "Adjacent pedicles"},{"key": "C","text": "Adjacent laminae"},{"key": "D","text": "Spinous processes"}],"correct": "C","explanation": "Ligamentum flavum connects adjacent laminae of thoracic and lumbar vertebrae."},{"id": 959,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The interspinous ligament connects:","options": [{"key": "A","text": "Adjacent spinous processes"},{"key": "B","text": "Lamina to pedicle"},{"key": "C","text": "Spinous process to lamina"},{"key": "D","text": "Adjacent transverse processes"}],"correct": "A","explanation": "Interspinous ligament connects adjacent spinous processes from root to apex."},{"id": 960,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The supraspinous ligament extends from:","options": [{"key": "A","text": "Occiput to C7"},{"key": "B","text": "C1 to sacrum"},{"key": "C","text": "T1 to L5"},{"key": "D","text": "C7 to L5 or sacrum"}],"correct": "D","explanation": "Supraspinous ligament runs from C7 to L5 (or sacrum), connecting tips of spinous processes."},{"id": 961,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The ligamentum nuchae is the cervical continuation of:","options": [{"key": "A","text": "Interspinous ligament"},{"key": "B","text": "Posterior longitudinal ligament"},{"key": "C","text": "Ligamentum flavum"},{"key": "D","text": "Supraspinous ligament"}],"correct": "D","explanation": "Ligamentum nuchae is the expanded supraspinous ligament in the cervical region."},{"id": 962,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The intertransverse ligament connects:","options": [{"key": "A","text": "Adjacent spinous processes"},{"key": "B","text": "Adjacent laminae"},{"key": "C","text": "Transverse process to rib"},{"key": "D","text": "Adjacent transverse processes"}],"correct": "D","explanation": "Intertransverse ligament connects adjacent transverse processes, limiting lateral flexion."},{"id": 963,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Which ligament is taut in flexion of spine?","options": [{"key": "A","text": "Ligamentum flavum"},{"key": "B","text": "Posterior longitudinal ligament"},{"key": "C","text": "Anterior longitudinal ligament"},{"key": "D","text": "Both B and C"}],"correct": "D","explanation": "Both ligamentum flavum and PLL become taut during spinal flexion, resisting excessive movement."},{"id": 964,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The ALL is taut in which spinal movement?","options": [{"key": "A","text": "Lateral flexion"},{"key": "B","text": "Extension"},{"key": "C","text": "Flexion"},{"key": "D","text": "Rotation"}],"correct": "B","explanation": "The anterior longitudinal ligament becomes taut during spinal extension, resisting hyperextension."},{"id": 965,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Ossification of the posterior longitudinal ligament (OPLL) most commonly occurs in:","options": [{"key": "A","text": "Thoracic spine"},{"key": "B","text": "Cervical spine"},{"key": "C","text": "Lumbosacral junction"},{"key": "D","text": "Lumbar spine"}],"correct": "B","explanation": "OPLL most commonly affects the cervical spine and can cause myelopathy."},{"id": 966,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which spinal ligament prevents excessive hyperextension?","options": [{"key": "A","text": "Ligamentum flavum"},{"key": "B","text": "Anterior longitudinal ligament"},{"key": "C","text": "Posterior longitudinal ligament"},{"key": "D","text": "Intertransverse"}],"correct": "B","explanation": "The ALL is the primary restraint against hyperextension of the vertebral column."},{"id": 967,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The costotransverse ligament connects:","options": [{"key": "A","text": "Rib tubercle to transverse process"},{"key": "B","text": "Rib to spinous process"},{"key": "C","text": "Rib head to vertebral body"},{"key": "D","text": "Rib to lamina"}],"correct": "A","explanation": "Costotransverse ligament connects the rib tubercle to the transverse process of the corresponding vertebra."},{"id": 968,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Hypertrophy of ligamentum flavum contributes to:","options": [{"key": "A","text": "Lumbar spinal stenosis"},{"key": "B","text": "Disc herniation"},{"key": "C","text": "Scoliosis"},{"key": "D","text": "Spondylolisthesis"}],"correct": "A","explanation": "Ligamentum flavum hypertrophy is a major cause of acquired lumbar spinal canal stenosis."},{"id": 969,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The radiate ligament of head of rib connects:","options": [{"key": "A","text": "Rib to transverse process"},{"key": "B","text": "Rib to PLL"},{"key": "C","text": "Rib to lamina"},{"key": "D","text": "Rib head to two adjacent vertebral bodies and disc"}],"correct": "D","explanation": "The radiate ligament fans from rib head to the bodies of two adjacent vertebrae and the intervening disc."},{"id": 970,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Normal thoracic kyphosis angle is approximately:","options": [{"key": "A","text": "40-50°"},{"key": "B","text": "50-70°"},{"key": "C","text": "10-20°"},{"key": "D","text": "20-40°"}],"correct": "D","explanation": "Normal thoracic kyphosis measured by Cobb method is approximately 20-40°."},{"id": 971,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Which movement is most restricted in the thoracic spine?","options": [{"key": "A","text": "Flexion"},{"key": "B","text": "Extension"},{"key": "C","text": "Rotation"},{"key": "D","text": "Lateral flexion"}],"correct": "C","explanation": "Rotation is most limited in thoracic spine due to rib cage, coronally oriented facets, and overlapping spinous processes."},{"id": 972,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "The coupled motion in thoracic spine is:","options": [{"key": "A","text": "Lateral flexion with ipsilateral rotation"},{"key": "B","text": "Flexion with rotation"},{"key": "C","text": "Rotation with lateral flexion to same side"},{"key": "D","text": "Lateral flexion with contralateral rotation"}],"correct": "D","explanation": "In upper thoracic spine, lateral flexion couples with contralateral rotation."},{"id": 973,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The thoracic spine contributes approximately how much to total spinal rotation?","options": [{"key": "A","text": "70°"},{"key": "B","text": "50°"},{"key": "C","text": "35°"},{"key": "D","text": "15°"}],"correct": "C","explanation": "Thoracic spine contributes approximately 35° (each side) to total spinal axial rotation."},{"id": 974,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Normal lumbar lordosis angle is:","options": [{"key": "A","text": "20-45°"},{"key": "B","text": "50-70°"},{"key": "C","text": "10-20°"},{"key": "D","text": "40-60°"}],"correct": "D","explanation": "Normal lumbar lordosis is approximately 40-60°, with significant individual variation."},{"id": 975,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "Which movement is maximum in lumbar spine?","options": [{"key": "A","text": "Circumduction"},{"key": "B","text": "Flexion-Extension"},{"key": "C","text": "Rotation"},{"key": "D","text": "Lateral flexion"}],"correct": "B","explanation": "Flexion-extension is maximum in lumbar spine; rotation is highly restricted by sagittal facets."},{"id": 976,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The lumbar spine contributes approximately how much total rotation?","options": [{"key": "A","text": "30° per side"},{"key": "B","text": "45° per side"},{"key": "C","text": "15-20° per side"},{"key": "D","text": "5° per side"}],"correct": "D","explanation": "Total lumbar rotation is only ~5° per side, limited by sagittally-oriented facet joints."},{"id": 977,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "During lumbar extension, the nucleus pulposus moves:","options": [{"key": "A","text": "Superiorly"},{"key": "B","text": "Remains stationary"},{"key": "C","text": "Anteriorly"},{"key": "D","text": "Posteriorly"}],"correct": "C","explanation": "During extension, the disc is compressed posteriorly, pushing nucleus anteriorly."},{"id": 978,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The instant axis of rotation for lumbar flexion-extension is located in:","options": [{"key": "A","text": "Nucleus pulposus"},{"key": "B","text": "Spinous process"},{"key": "C","text": "Anterior vertebral body"},{"key": "D","text": "Posterior annulus"}],"correct": "A","explanation": "The instantaneous axis of rotation for lumbar segmental motion is within the nucleus pulposus."},{"id": 979,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "L4-L5 disc herniation most commonly compresses:","options": [{"key": "A","text": "L3 nerve root"},{"key": "B","text": "S1 nerve root"},{"key": "C","text": "L5 nerve root"},{"key": "D","text": "L4 nerve root"}],"correct": "C","explanation": "At L4-L5 level, a posterolateral disc herniation compresses the traversing L5 nerve root."},{"id": 980,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "L5-S1 disc herniation most commonly compresses:","options": [{"key": "A","text": "L5 nerve root"},{"key": "B","text": "L4 nerve root"},{"key": "C","text": "S1 nerve root"},{"key": "D","text": "S2 nerve root"}],"correct": "C","explanation": "At L5-S1, the traversing S1 nerve root is most commonly compressed by posterolateral herniation."},{"id": 981,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Cauda equina syndrome is caused by:","options": [{"key": "A","text": "Foraminal stenosis at L5"},{"key": "B","text": "L1-L2 disc herniation laterally"},{"key": "C","text": "Massive central disc herniation at L4-L5 or below"},{"key": "D","text": "Facet joint arthritis"}],"correct": "C","explanation": "Large central disc herniation compresses multiple cauda equina nerve roots, causing CES."},{"id": 982,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The straight leg raise (SLR) test stretches which nerve root?","options": [{"key": "A","text": "S2-S3"},{"key": "B","text": "L4-S1 (sciatic nerve)"},{"key": "C","text": "L3-L4"},{"key": "D","text": "L2-L3"}],"correct": "B","explanation": "SLR stretches L4, L5, S1 nerve roots via the sciatic nerve; positive if pain reproduces below knee."},{"id": 983,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Crossed straight leg raise (CSLR) is more specific for:","options": [{"key": "A","text": "Piriformis syndrome"},{"key": "B","text": "Large central or paracentral disc herniation"},{"key": "C","text": "Facet joint pain"},{"key": "D","text": "Lateral disc herniation"}],"correct": "B","explanation": "CSLR (contralateral leg raising reproducing ipsilateral leg pain) indicates large medial disc herniation."},{"id": 984,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The conus medullaris typically ends at which vertebral level in adults?","options": [{"key": "A","text": "L4"},{"key": "B","text": "L1-L2"},{"key": "C","text": "L3"},{"key": "D","text": "T12"}],"correct": "B","explanation": "The spinal cord typically ends at L1-L2 in adults (conus medullaris level)."},{"id": 985,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The cauda equina occupies which space?","options": [{"key": "A","text": "Intradural-extramedullary space"},{"key": "B","text": "Subarachnoid space"},{"key": "C","text": "Subdural space"},{"key": "D","text": "Epidural space"}],"correct": "B","explanation": "Cauda equina nerve roots descend within the subarachnoid (thecal) space."},{"id": 986,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Epidural space contains:","options": [{"key": "A","text": "Fat, venous plexus, lymphatics, nerve roots"},{"key": "B","text": "Spinal cord only"},{"key": "C","text": "Dural sac"},{"key": "D","text": "CSF"}],"correct": "A","explanation": "Epidural space contains fat, internal vertebral venous plexus, lymphatics, and spinal nerve roots."},{"id": 987,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The dural sac in adults typically ends at:","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "S2-S3"},{"key": "C","text": "L4-L5"},{"key": "D","text": "S1-S2"}],"correct": "D","explanation": "The dural sac typically ends at S1-S2, below which is the filum terminale externum."},{"id": 988,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The intervertebral foramen of the lumbar spine is bounded anteriorly by:","options": [{"key": "A","text": "Pedicles superiorly and inferiorly"},{"key": "B","text": "Facet joint"},{"key": "C","text": "Intervertebral disc and vertebral bodies"},{"key": "D","text": "Ligamentum flavum"}],"correct": "C","explanation": "The IVF is bounded anteriorly by the intervertebral disc and adjacent vertebral bodies."},{"id": 989,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Ossification of vertebral body begins from:","options": [{"key": "A","text": "Endochondral ossification in epiphyseal ring"},{"key": "B","text": "Primary ossification center in centrum"},{"key": "C","text": "Membranous ossification"},{"key": "D","text": "Secondary ossification centers in neural arches"}],"correct": "B","explanation": "Primary ossification center appears in the centrum of vertebral body during fetal life."},{"id": 990,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Ring apophysis of vertebra appears at approximately:","options": [{"key": "A","text": "12-14 years"},{"key": "B","text": "18-20 years"},{"key": "C","text": "5 years"},{"key": "D","text": "8 years"}],"correct": "A","explanation": "Ring apophysis (secondary ossification center at disc-body junction) appears at puberty (12-14 years)."},{"id": 991,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Spina bifida occulta most commonly occurs at:","options": [{"key": "A","text": "L3"},{"key": "B","text": "T12"},{"key": "C","text": "L5-S1"},{"key": "D","text": "L1"}],"correct": "C","explanation": "Spina bifida occulta most commonly occurs at L5 or S1 due to failure of posterior arch fusion."},{"id": 992,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Hemivertebra is a congenital anomaly due to:","options": [{"key": "A","text": "Absence of pedicle"},{"key": "B","text": "Failure of formation of half the vertebra"},{"key": "C","text": "Disc calcification"},{"key": "D","text": "Failure of segmentation"}],"correct": "B","explanation": "Hemivertebra results from failure of formation/development of one half of a vertebra, causing congenital scoliosis."},{"id": 993,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Lumbar facet (zygapophyseal) joints are classified as:","options": [{"key": "A","text": "Cartilaginous joints"},{"key": "B","text": "Fibrous joints"},{"key": "C","text": "Amphiarthrosis"},{"key": "D","text": "Synovial joints"}],"correct": "D","explanation": "Facet joints are true synovial joints with hyaline cartilage, joint capsule, and synovial membrane."},{"id": 994,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which nerve innervates lumbar facet joints?","options": [{"key": "A","text": "Medial branch of posterior primary ramus"},{"key": "B","text": "Sinuvertebral nerve"},{"key": "C","text": "Anterior primary ramus"},{"key": "D","text": "Lateral branch of posterior primary ramus"}],"correct": "A","explanation": "Each facet joint is innervated by medial branches of posterior rami from two adjacent levels."},{"id": 995,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Hard","question": "In the thoracic spine, the superior articular facets face:","options": [{"key": "A","text": "Anteriorly and slightly laterally"},{"key": "B","text": "Inferiorly"},{"key": "C","text": "Superiorly"},{"key": "D","text": "Posteriorly and slightly medially"}],"correct": "D","explanation": "Thoracic superior articular facets face posteriorly and slightly laterally, limiting flexion-extension."},{"id": 996,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The intervertebral foramen transmits:","options": [{"key": "A","text": "Spinal nerve, spinal artery, veins, sinuvertebral nerve"},{"key": "B","text": "Only dorsal root ganglion"},{"key": "C","text": "Only venous plexus"},{"key": "D","text": "Only sinuvertebral nerve"}],"correct": "A","explanation": "The IVF transmits: spinal nerve (and DRG), radicular arteries/veins, and sinuvertebral nerve."},{"id": 997,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "The spinal cord occupies what proportion of the spinal canal in thoracic region?","options": [{"key": "A","text": "50-60%"},{"key": "B","text": "10-20%"},{"key": "C","text": "75-80%"},{"key": "D","text": "30-40%"}],"correct": "A","explanation": "The spinal cord occupies about 50-60% of the thoracic canal (less CSF reserve than cervical)."},{"id": 998,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The thoracic kyphosis and lumbar lordosis are classified as:","options": [{"key": "A","text": "Primary and primary curves"},{"key": "B","text": "Secondary and secondary curves"},{"key": "C","text": "Both secondary curves"},{"key": "D","text": "Primary (kyphosis) and secondary (lordosis)"}],"correct": "D","explanation": "Thoracic kyphosis is a primary (fetal) curve; lumbar lordosis develops secondarily (when walking)."},{"id": 999,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "Scoliosis is defined as lateral curvature of spine more than:","options": [{"key": "A","text": "20°"},{"key": "B","text": "10°"},{"key": "C","text": "5°"},{"key": "D","text": "15°"}],"correct": "B","explanation": "Scoliosis is defined as a lateral curvature of >10° measured by Cobb method on X-ray."},{"id": 1000,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The Cobb angle in scoliosis is measured between:","options": [{"key": "A","text": "Two adjacent vertebrae"},{"key": "B","text": "Apical vertebrae"},{"key": "C","text": "Neutral vertebrae"},{"key": "D","text": "End vertebrae of the curve"}],"correct": "D","explanation": "Cobb angle is measured between the superior endplate of the uppermost and inferior endplate of lowermost vertebra of the curve."},{"id": 1001,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The artery of Adamkiewicz is a major feeder of:","options": [{"key": "A","text": "Sacral cord"},{"key": "B","text": "Thoracolumbar spinal cord"},{"key": "C","text": "Cervical cord"},{"key": "D","text": "Cauda equina only"}],"correct": "B","explanation": "Artery of Adamkiewicz (arteria radicularis magna) is the major feeder of the lower thoracic and lumbar cord."},{"id": 1002,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The artery of Adamkiewicz typically arises from the aorta at:","options": [{"key": "A","text": "T1-T4"},{"key": "B","text": "T5-T8"},{"key": "C","text": "L1-L3"},{"key": "D","text": "T9-T12 (left side)"}],"correct": "D","explanation": "It usually arises from the left intercostal/lumbar artery at T9-T12 (80% on left side)."},{"id": 1003,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The internal vertebral venous plexus (Batson's plexus) is:","options": [{"key": "A","text": "Part of portal system"},{"key": "B","text": "Arterial plexus"},{"key": "C","text": "Valveless venous plexus"},{"key": "D","text": "Valved venous system"}],"correct": "C","explanation": "Batson's plexus is a valveless venous plexus, allowing retrograde spread of tumor/infection to spine."},{"id": 1004,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The thoracolumbar fascia encases which muscles?","options": [{"key": "A","text": "Psoas only"},{"key": "B","text": "Rectus abdominis"},{"key": "C","text": "Erector spinae and quadratus lumborum"},{"key": "D","text": "Obliques only"}],"correct": "C","explanation": "Thoracolumbar fascia (posterior and anterior layers) encases erector spinae and quadratus lumborum."},{"id": 1005,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The multifidus muscle is most developed in which spinal region?","options": [{"key": "A","text": "Thoracic"},{"key": "B","text": "Lumbar"},{"key": "C","text": "Cervical"},{"key": "D","text": "Sacral"}],"correct": "B","explanation": "Multifidus is most massive in the lumbar region, providing segmental stability."},{"id": 1006,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Spondylolysis is a defect in:","options": [{"key": "A","text": "Pedicle"},{"key": "B","text": "Transverse process"},{"key": "C","text": "Vertebral body"},{"key": "D","text": "Pars interarticularis"}],"correct": "D","explanation": "Spondylolysis is a stress fracture or defect in the pars interarticularis (isthmus) of the neural arch."},{"id": 1007,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Spondylolisthesis refers to:","options": [{"key": "A","text": "Fracture of vertebral body"},{"key": "B","text": "Lateral displacement"},{"key": "C","text": "Forward slippage of one vertebra over another"},{"key": "D","text": "Posterior displacement"}],"correct": "C","explanation": "Spondylolisthesis is the anterior displacement of a vertebra relative to the one below it."},{"id": 1008,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Meyerding Grade II spondylolisthesis is:","options": [{"key": "A","text": "51-75% slip"},{"key": "B","text": "0-25% slip"},{"key": "C","text": "26-50% slip"},{"key": "D","text": "76-100% slip"}],"correct": "C","explanation": "Meyerding Grade II = 26-50% forward slippage of the vertebral body."},{"id": 1009,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Degenerative spondylolisthesis most commonly occurs at:","options": [{"key": "A","text": "L2-L3"},{"key": "B","text": "L4-L5"},{"key": "C","text": "L5-S1"},{"key": "D","text": "L3-L4"}],"correct": "B","explanation": "Degenerative spondylolisthesis (without pars defect) most commonly occurs at L4-L5."},{"id": 1010,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scheuermann's disease involves:","options": [{"key": "A","text": "Scoliosis with vertebral rotation"},{"key": "B","text": "Thoracic hyperkyphosis with anterior vertebral wedging >5° at ≥3 consecutive levels"},{"key": "C","text": "Spondylolysis at T10"},{"key": "D","text": "Disc calcification in children"}],"correct": "B","explanation": "Scheuermann's disease is adolescent kyphosis defined by >5° anterior wedging at ≥3 consecutive thoracic vertebrae."},{"id": 1011,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The L4 nerve root exits:","options": [{"key": "A","text": "Above L4 pedicle"},{"key": "B","text": "Below L4 pedicle (L4-L5 foramen)"},{"key": "C","text": "At L3-L4 foramen"},{"key": "D","text": "Below L5 pedicle"}],"correct": "B","explanation": "In lumbar spine, nerve roots exit below the same-numbered pedicle (L4 exits via L4-L5 foramen)."},{"id": 1012,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The dermatomal distribution of L4 nerve root includes:","options": [{"key": "A","text": "Lateral aspect of foot and heel"},{"key": "B","text": "Lateral leg and dorsum of foot"},{"key": "C","text": "Posterior thigh"},{"key": "D","text": "Medial leg and great toe"}],"correct": "D","explanation": "L4 dermatome covers medial leg, medial malleolus, and medial foot to great toe."},{"id": 1013,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The L5 nerve root supplies which muscle (key muscle)?","options": [{"key": "A","text": "Biceps femoris"},{"key": "B","text": "Gastrocnemius"},{"key": "C","text": "Extensor hallucis longus"},{"key": "D","text": "Tibialis anterior"}],"correct": "C","explanation": "Extensor hallucis longus (big toe extension) is the key muscle for L5 nerve root testing."},{"id": 1014,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "Diminished ankle jerk (Achilles reflex) indicates involvement of:","options": [{"key": "A","text": "S1 root"},{"key": "B","text": "L5 root"},{"key": "C","text": "L4 root"},{"key": "D","text": "L3 root"}],"correct": "A","explanation": "Ankle jerk (Achilles reflex) is mediated by S1 nerve root; absent/diminished in S1 compression."},{"id": 1015,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The pedicle-to-pedicle distance on AP X-ray represents:","options": [{"key": "A","text": "Foraminal width"},{"key": "B","text": "Vertebral body width"},{"key": "C","text": "Interpediculate distance"},{"key": "D","text": "Spinal canal width"}],"correct": "C","explanation": "Interpediculate distance on AP view = the transverse diameter of spinal canal at that level."},{"id": 1016,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The gold standard investigation for lumbar disc herniation is:","options": [{"key": "A","text": "Plain X-ray"},{"key": "B","text": "CT scan"},{"key": "C","text": "Myelography"},{"key": "D","text": "MRI spine"}],"correct": "D","explanation": "MRI is the gold standard for evaluating disc herniation, nerve root compression, and soft tissue."},{"id": 1017,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "On MRI T2 images, a normal hydrated disc appears:","options": [{"key": "A","text": "Absent signal"},{"key": "B","text": "Hyperintense (bright/white)"},{"key": "C","text": "Isointense"},{"key": "D","text": "Hypointense (dark)"}],"correct": "B","explanation": "Normal hydrated nucleus pulposus is bright (hyperintense) on T2 MRI due to high water content."},{"id": 1018,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The spinal canal sagittal diameter in lumbar region is normally:","options": [{"key": "A","text": "6-8 mm"},{"key": "B","text": "8-10 mm"},{"key": "C","text": "12-14 mm"},{"key": "D","text": "15-25 mm"}],"correct": "D","explanation": "Normal lumbar spinal canal sagittal diameter is 15-25 mm; <12 mm = absolute stenosis."},{"id": 1019,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The thoracolumbar junction is considered to be:","options": [{"key": "A","text": "T10-T11"},{"key": "B","text": "T9-T10"},{"key": "C","text": "T11-L1"},{"key": "D","text": "L1-L2"}],"correct": "C","explanation": "T11-L1 constitutes the thoracolumbar junction, a common site for fractures and transitional stress."},{"id": 1020,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Burst fractures are most common at:","options": [{"key": "A","text": "Thoracolumbar junction"},{"key": "B","text": "Upper thoracic"},{"key": "C","text": "Cervical spine"},{"key": "D","text": "Mid-lumbar"}],"correct": "A","explanation": "Thoracolumbar junction (T11-L2) is the most common site for burst fractures due to transitional biomechanics."},{"id": 1021,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The Denis three-column model of spinal stability includes:","options": [{"key": "A","text": "Anterior, posterior, lateral columns"},{"key": "B","text": "Left, right, middle columns"},{"key": "C","text": "Osseous, ligamentous, disc columns"},{"key": "D","text": "Anterior, middle, posterior columns"}],"correct": "D","explanation": "Denis described anterior, middle, and posterior columns; injury to ≥2 columns = unstable."},{"id": 1022,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The thoracic vertebrae participate in which joints with the ribs?","options": [{"key": "A","text": "Costo-sternal joints"},{"key": "B","text": "Costochondral joints only"},{"key": "C","text": "Costovertebral and costotransverse joints"},{"key": "D","text": "Sternochondral joints"}],"correct": "C","explanation": "Ribs articulate with thoracic vertebrae via costovertebral (head) and costotransverse (tubercle) joints."},{"id": 1023,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Which ligament prevents excessive distraction of vertebral bodies?","options": [{"key": "A","text": "Posterior longitudinal ligament"},{"key": "B","text": "Ligamentum flavum"},{"key": "C","text": "ALL"},{"key": "D","text": "Interspinous ligament"}],"correct": "C","explanation": "ALL resists distraction (separation) of vertebral bodies and hyperextension."},{"id": 1024,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "The posterior tension band of the spine consists of:","options": [{"key": "A","text": "Vertebral body alone"},{"key": "B","text": "ALL and disc"},{"key": "C","text": "Facet joints, posterior ligaments, and paraspinal muscles"},{"key": "D","text": "Anterior longitudinal ligament only"}],"correct": "C","explanation": "The posterior tension band includes posterior ligamentous complex, facets, and muscles, resisting flexion forces."},{"id": 1025,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Segmental instability in lumbar spine on flexion-extension X-rays is defined as translation of:","options": [{"key": "A","text": ">4 mm"},{"key": "B","text": ">5 mm"},{"key": "C","text": ">3 mm"},{"key": "D","text": ">2 mm"}],"correct": "A","explanation": "Lumbar instability is defined as >4 mm translation or >10° angulation on dynamic (flexion-extension) X-rays."},{"id": 1026,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The sinuvertebral (recurrent meningeal) nerve re-enters the spinal canal through:","options": [{"key": "A","text": "Sacral hiatus"},{"key": "B","text": "Posterior foramen"},{"key": "C","text": "Anterior foramen"},{"key": "D","text": "Intervertebral foramen"}],"correct": "D","explanation": "The sinuvertebral nerve branches from the spinal nerve and re-enters the IVF to innervate dura, PLL, and outer annulus."},{"id": 1027,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Easy","question": "How many sacral vertebrae fuse to form the sacrum?","options": [{"key": "A","text": "3"},{"key": "B","text": "5"},{"key": "C","text": "4"},{"key": "D","text": "6"}],"correct": "B","explanation": "Sacrum is formed by fusion of 5 sacral vertebrae (S1-S5), usually complete by age 25-30."},{"id": 1028,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sacral promontory is the anterior edge of:","options": [{"key": "A","text": "Sacral base"},{"key": "B","text": "S3 body"},{"key": "C","text": "S2 body"},{"key": "D","text": "S1 superior surface"}],"correct": "D","explanation": "Sacral promontory is the prominent anterior edge of S1 superior surface; landmark for pelvic measurements."},{"id": 1029,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Easy","question": "The base of sacrum articulates with:","options": [{"key": "A","text": "L5 vertebra"},{"key": "B","text": "L4 vertebra"},{"key": "C","text": "Ilium"},{"key": "D","text": "Coccyx"}],"correct": "A","explanation": "The base (superior surface) of sacrum articulates with L5 vertebra at the lumbosacral joint."},{"id": 1030,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Easy","question": "The apex of sacrum articulates with:","options": [{"key": "A","text": "Ilium"},{"key": "B","text": "L5"},{"key": "C","text": "Ischium"},{"key": "D","text": "Coccyx"}],"correct": "D","explanation": "The apex (inferior tip) of sacrum articulates with the base of the coccyx."},{"id": 1031,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The anterior sacral foramina transmit:","options": [{"key": "A","text": "Dorsal sacral nerves only"},{"key": "B","text": "Only blood vessels"},{"key": "C","text": "Anterior rami of sacral nerves and lateral sacral vessels"},{"key": "D","text": "Posterior rami of sacral nerves"}],"correct": "C","explanation": "Anterior sacral foramina transmit anterior (ventral) rami of S1-S4 and lateral sacral vessels."},{"id": 1032,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The posterior sacral foramina transmit:","options": [{"key": "A","text": "Posterior rami of sacral nerves"},{"key": "B","text": "Pudendal nerve"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Anterior rami of sacral nerves"}],"correct": "A","explanation": "Posterior sacral foramina transmit posterior (dorsal) rami of S1-S4 sacral nerves."},{"id": 1033,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "How many pairs of anterior sacral foramina are present?","options": [{"key": "A","text": "2"},{"key": "B","text": "4"},{"key": "C","text": "5"},{"key": "D","text": "3"}],"correct": "B","explanation": "There are 4 pairs of anterior sacral foramina (S1-S4); S5 exits via sacral hiatus."},{"id": 1034,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sacral canal is a continuation of:","options": [{"key": "A","text": "Pelvic cavity"},{"key": "B","text": "Spinal canal/vertebral canal"},{"key": "C","text": "Epidural space only"},{"key": "D","text": "Sacral hiatus"}],"correct": "B","explanation": "Sacral canal is the continuation of the vertebral (spinal) canal within the sacrum."},{"id": 1035,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The sacral hiatus is formed by failure of fusion of laminae of:","options": [{"key": "A","text": "S4-S5"},{"key": "B","text": "S3-S4"},{"key": "C","text": "S1-S2"},{"key": "D","text": "S5 (and often S4)"}],"correct": "D","explanation": "Sacral hiatus is a gap in the posterior wall at S5 (and often S4) due to unfused laminae."},{"id": 1036,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The sacral cornua are remnants of:","options": [{"key": "A","text": "Spinous processes of S5"},{"key": "B","text": "Inferior articular processes of S5"},{"key": "C","text": "Pedicles of S5"},{"key": "D","text": "Transverse processes of S5"}],"correct": "B","explanation": "Sacral cornua are the inferior articular processes of S5, flanking the sacral hiatus."},{"id": 1037,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sacral hiatus is the site of entry for:","options": [{"key": "A","text": "Pudendal nerve block"},{"key": "B","text": "Lumbar epidural only"},{"key": "C","text": "Caudal epidural anaesthesia"},{"key": "D","text": "Spinal anaesthesia"}],"correct": "C","explanation": "Caudal epidural anaesthesia is administered through the sacral hiatus into the sacral canal."},{"id": 1038,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Easy","question": "The auricular surface of sacrum articulates with:","options": [{"key": "A","text": "L5"},{"key": "B","text": "Coccyx"},{"key": "C","text": "Ischium"},{"key": "D","text": "Ilium"}],"correct": "D","explanation": "The ear-shaped auricular surface on the lateral sacrum articulates with the ilium at the SI joint."},{"id": 1039,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The sacral tuberosity (roughened area behind auricular surface) provides attachment to:","options": [{"key": "A","text": "Interosseous sacroiliac ligament"},{"key": "B","text": "Sacrospinous ligament"},{"key": "C","text": "Anterior sacroiliac ligament"},{"key": "D","text": "Sacrotuberous ligament"}],"correct": "A","explanation": "The interosseous SI ligament, the strongest ligament in the body, attaches to the sacral tuberosity."},{"id": 1040,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Easy","question": "The pelvic surface of sacrum is:","options": [{"key": "A","text": "Concave"},{"key": "B","text": "Flat"},{"key": "C","text": "Convex"},{"key": "D","text": "Irregular"}],"correct": "A","explanation": "The pelvic (anterior) surface of sacrum is concave, forming the posterior wall of the pelvic cavity."},{"id": 1041,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The median sacral crest represents fused:","options": [{"key": "A","text": "Pedicles"},{"key": "B","text": "Transverse processes"},{"key": "C","text": "Laminae"},{"key": "D","text": "Spinous processes"}],"correct": "D","explanation": "Median sacral crest represents the fused rudimentary spinous processes of sacral vertebrae."},{"id": 1042,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The lateral sacral crest represents fused:","options": [{"key": "A","text": "Transverse processes"},{"key": "B","text": "Articular processes"},{"key": "C","text": "Laminae"},{"key": "D","text": "Spinous processes"}],"correct": "A","explanation": "Lateral sacral crests are formed by the fused transverse processes of the sacral vertebrae."},{"id": 1043,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The intermediate sacral crest represents fused:","options": [{"key": "A","text": "Transverse processes"},{"key": "B","text": "Laminae"},{"key": "C","text": "Articular processes"},{"key": "D","text": "Spinous processes"}],"correct": "C","explanation": "Intermediate sacral crest is formed by the fused articular processes of sacral vertebrae."},{"id": 1044,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The sacrum tilts anteriorly; the angle between sacral axis and horizontal is called:","options": [{"key": "A","text": "Pelvic incidence"},{"key": "B","text": "Ferguson's angle"},{"key": "C","text": "Sacral slope"},{"key": "D","text": "Cobb angle"}],"correct": "C","explanation": "Sacral slope is the angle between the superior S1 endplate and horizontal, normally ~40°."},{"id": 1045,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The sacral index (SI) represents:","options": [{"key": "A","text": "Sacral canal diameter"},{"key": "B","text": "None of the above"},{"key": "C","text": "Sacral promontory angle"},{"key": "D","text": "Ratio of sacral width to height"}],"correct": "D","explanation": "Sacral index = (maximum sacral width / sacral length) × 100; used in sex determination."},{"id": 1046,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "Sexing of sacrum: female sacrum compared to male is:","options": [{"key": "A","text": "Longer and narrower"},{"key": "B","text": "Shorter, wider, and less curved"},{"key": "C","text": "Taller and more curved"},{"key": "D","text": "Identical"}],"correct": "B","explanation": "Female sacrum is shorter, wider, less curved (flatter), with a wider sacral canal than male."},{"id": 1047,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The coccyx is formed by fusion of how many rudimentary vertebrae?","options": [{"key": "A","text": "4-6"},{"key": "B","text": "2"},{"key": "C","text": "2-3"},{"key": "D","text": "3-5"}],"correct": "D","explanation": "Coccyx typically consists of 3-5 (usually 4) fused rudimentary coccygeal vertebrae."},{"id": 1048,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The coccyx articulates superiorly with:","options": [{"key": "A","text": "Sacral apex (S5)"},{"key": "B","text": "Ischium"},{"key": "C","text": "L5"},{"key": "D","text": "S4"}],"correct": "A","explanation": "Coccyx articulates with the apex of the sacrum (S5) via the sacrococcygeal joint."},{"id": 1049,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The coccygeal cornua articulate with:","options": [{"key": "A","text": "Pubic symphysis"},{"key": "B","text": "Sacral cornua"},{"key": "C","text": "Sacral hiatus"},{"key": "D","text": "Ischial tuberosity"}],"correct": "B","explanation": "Coccygeal cornua (superior articular processes of Co1) articulate with the sacral cornua."},{"id": 1050,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The gluteus maximus attaches to the coccyx via:","options": [{"key": "A","text": "Coccygeal cornua"},{"key": "B","text": "Lateral border and posterior surface of coccyx"},{"key": "C","text": "Sacrospinous ligament"},{"key": "D","text": "Posterior sacrococcygeal ligament"}],"correct": "B","explanation": "Gluteus maximus has an origin from the lateral border and posterior surface of the lower sacrum and coccyx."},{"id": 1051,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Coccydynia refers to:","options": [{"key": "A","text": "Piriformis pain"},{"key": "B","text": "Sacroiliac joint pain"},{"key": "C","text": "Pain in the coccygeal region"},{"key": "D","text": "Lumbar nerve pain"}],"correct": "C","explanation": "Coccydynia is pain in and around the coccyx region, often after direct trauma or childbirth."},{"id": 1052,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The muscle arising from the anterior (pelvic) surface of coccyx is:","options": [{"key": "A","text": "Obturator internus"},{"key": "B","text": "Coccygeus"},{"key": "C","text": "Piriformis"},{"key": "D","text": "Levator ani"}],"correct": "B","explanation": "Coccygeus muscle arises from the ischial spine and inserts into the lateral border of coccyx and sacrum."},{"id": 1053,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The sacrococcygeal joint is classified as:","options": [{"key": "A","text": "Synovial"},{"key": "B","text": "Fibrous"},{"key": "C","text": "Pivot joint"},{"key": "D","text": "Synchondrosis (cartilaginous)"}],"correct": "D","explanation": "Sacrococcygeal joint is a symphysis (secondary cartilaginous/fibrocartilaginous joint)."},{"id": 1054,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The filum terminale externum attaches to the:","options": [{"key": "A","text": "Sacral cornua"},{"key": "B","text": "Posterior coccyx"},{"key": "C","text": "Sacral hiatus"},{"key": "D","text": "Coccygeal apex"}],"correct": "D","explanation": "Filum terminale externum (extension of dura) blends with periosteum at the coccygeal apex."},{"id": 1055,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Anococcygeal ligament/raphe connects:","options": [{"key": "A","text": "Coccyx to anal sphincter and perineal body"},{"key": "B","text": "Coccyx to pubis"},{"key": "C","text": "Coccyx to ischium"},{"key": "D","text": "Coccyx to sacrum"}],"correct": "A","explanation": "Anococcygeal raphe/ligament connects the coccyx to the external anal sphincter."},{"id": 1056,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The coccygeal plexus is formed by:","options": [{"key": "A","text": "S3, S4, S5"},{"key": "B","text": "S4, S5, Co1 nerve roots"},{"key": "C","text": "L5, S1, S2"},{"key": "D","text": "S1, S2, S3"}],"correct": "B","explanation": "The coccygeal plexus is formed by the anterior rami of S4, S5, and Co1."},{"id": 1057,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The sacroiliac (SI) joint is classified as:","options": [{"key": "A","text": "Synovial joint (diarthrosis)"},{"key": "B","text": "Fibrous joint only"},{"key": "C","text": "Mixed joint — partly synovial, partly syndesmosis"},{"key": "D","text": "Pure synchondrosis"}],"correct": "C","explanation": "SI joint has an anterior synovial portion and a posterior syndesmotic (interosseous ligament) portion."},{"id": 1058,"subject": "Anatomy","topic": "Histology & Embryology","difficulty": "Hard","question": "The articular cartilage on the sacral side of SI joint is:","options": [{"key": "A","text": "Hyaline cartilage (thicker)"},{"key": "B","text": "Fibrocartilage"},{"key": "C","text": "No cartilage"},{"key": "D","text": "Elastic cartilage"}],"correct": "A","explanation": "Sacral articular surface is hyaline cartilage (2-3x thicker); iliac side is fibrocartilage."},{"id": 1059,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The synovial portion of SI joint occupies:","options": [{"key": "A","text": "Entire joint"},{"key": "B","text": "Anterior and inferior part"},{"key": "C","text": "Superior part only"},{"key": "D","text": "Posterior 1/3 only"}],"correct": "B","explanation": "The synovial part of SI joint is in the anterior-inferior portion; posterior is ligamentous."},{"id": 1060,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The strongest ligament of the body is:","options": [{"key": "A","text": "Interosseous sacroiliac ligament"},{"key": "B","text": "Posterior sacroiliac ligament"},{"key": "C","text": "Anterior sacroiliac ligament"},{"key": "D","text": "Sacrotuberous ligament"}],"correct": "A","explanation": "The interosseous sacroiliac ligament is the strongest ligament in the human body."},{"id": 1061,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The interosseous sacroiliac ligament lies:","options": [{"key": "A","text": "Inferior to the joint"},{"key": "B","text": "Posterior to the joint surface (in the sacral tuberosity region)"},{"key": "C","text": "Anterior to the joint"},{"key": "D","text": "Superior to the joint"}],"correct": "B","explanation": "Interosseous SI ligament lies deep, filling the space between sacral tuberosity and iliac tuberosity."},{"id": 1062,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The anterior sacroiliac ligament is a thickening of:","options": [{"key": "A","text": "Sacrotuberous ligament"},{"key": "B","text": "Joint capsule anteriorly"},{"key": "C","text": "Interosseous ligament"},{"key": "D","text": "Iliolumbar ligament"}],"correct": "B","explanation": "The anterior sacroiliac ligament is a thickening of the anterior and inferior joint capsule."},{"id": 1063,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The posterior sacroiliac ligament is divided into:","options": [{"key": "A","text": "It is a single band"},{"key": "B","text": "Short and long posterior SI ligaments"},{"key": "C","text": "Medial and lateral parts"},{"key": "D","text": "Superior and inferior parts"}],"correct": "B","explanation": "The posterior SI ligament has short (horizontal) and long (vertical/oblique) parts."},{"id": 1064,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The long posterior sacroiliac ligament blends with:","options": [{"key": "A","text": "Sacrotuberous ligament"},{"key": "B","text": "Anterior longitudinal ligament"},{"key": "C","text": "Sacrospinous ligament"},{"key": "D","text": "Iliolumbar ligament"}],"correct": "A","explanation": "The long posterior SI ligament blends inferiorly with the sacrotuberous ligament."},{"id": 1065,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sacrotuberous ligament connects:","options": [{"key": "A","text": "Sacrum/coccyx/PSIS to ischial tuberosity"},{"key": "B","text": "Ilium to ischium"},{"key": "C","text": "Sacrum to ischial spine"},{"key": "D","text": "Sacrum to pubis"}],"correct": "A","explanation": "Sacrotuberous ligament connects the lateral sacrum, coccyx, and PSIS to the ischial tuberosity."},{"id": 1066,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sacrospinous ligament connects:","options": [{"key": "A","text": "Sacrum to ischial tuberosity"},{"key": "B","text": "Ilium to sacrum"},{"key": "C","text": "Sacrum/coccyx to ischial spine"},{"key": "D","text": "PSIS to ASIS"}],"correct": "C","explanation": "Sacrospinous ligament connects the lateral sacrum and coccyx to the ischial spine."},{"id": 1067,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The sacrospinous and sacrotuberous ligaments convert the greater sciatic notch into the:","options": [{"key": "A","text": "Pudendal canal"},{"key": "B","text": "Obturator foramen"},{"key": "C","text": "Lesser sciatic foramen"},{"key": "D","text": "Greater sciatic foramen"}],"correct": "D","explanation": "These ligaments convert the greater sciatic notch into the greater sciatic foramen."},{"id": 1068,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Which structure passes through the greater sciatic foramen ABOVE piriformis?","options": [{"key": "A","text": "Pudendal nerve"},{"key": "B","text": "Inferior gluteal nerve"},{"key": "C","text": "Sciatic nerve"},{"key": "D","text": "Superior gluteal nerve and vessels"}],"correct": "D","explanation": "Superior gluteal nerve and vessels pass above piriformis through the greater sciatic foramen."},{"id": 1069,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The iliolumbar ligament connects:","options": [{"key": "A","text": "L4-L5 transverse processes to iliac crest"},{"key": "B","text": "L5 transverse process to iliac crest"},{"key": "C","text": "PSIS to L5"},{"key": "D","text": "Ilium to sacrum"}],"correct": "B","explanation": "Iliolumbar ligament runs from L5 transverse process (primarily) to the iliac crest."},{"id": 1070,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The iliolumbar ligament resists:","options": [{"key": "A","text": "Posterior translation of L5"},{"key": "B","text": "Anterior translation and axial rotation of L5 on sacrum"},{"key": "C","text": "Extension of lumbar spine"},{"key": "D","text": "Lateral flexion only"}],"correct": "B","explanation": "Iliolumbar ligament is the primary restraint against anterior translation and rotation of L5 on sacrum."},{"id": 1071,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Innervation of the SI joint is by branches from:","options": [{"key": "A","text": "S1-S4 anterior rami only"},{"key": "B","text": "Pudendal nerve"},{"key": "C","text": "L2-L4 roots"},{"key": "D","text": "L4-S2 posterior and anterior rami"}],"correct": "D","explanation": "SI joint innervation is complex: posterior capsule by L4-S1 posterior rami; anterior by L4-S2 anterior rami."},{"id": 1072,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The primary movement at the SI joint is:","options": [{"key": "A","text": "Rotation"},{"key": "B","text": "Gliding"},{"key": "C","text": "Translation"},{"key": "D","text": "Nutation and counternutation"}],"correct": "D","explanation": "The SI joint's primary movements are nutation (sacral flexion) and counternutation (sacral extension)."},{"id": 1073,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "Nutation of sacrum refers to:","options": [{"key": "A","text": "Sacral base moves posteriorly, apex anteriorly"},{"key": "B","text": "Sacral base moves anteriorly, apex posteriorly"},{"key": "C","text": "No movement"},{"key": "D","text": "Sacrum rotates laterally"}],"correct": "B","explanation": "Nutation: sacral base tilts anteriorly-inferiorly, apex moves posteriorly (like nodding forward)."},{"id": 1074,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "Counternutation of sacrum refers to:","options": [{"key": "A","text": "Sacral base moves anteriorly"},{"key": "B","text": "Lateral rotation of sacrum"},{"key": "C","text": "Caudal translation"},{"key": "D","text": "Sacral base moves posteriorly, apex anteriorly"}],"correct": "D","explanation": "Counternutation is the reverse: sacral base moves posteriorly, apex anteriorly."},{"id": 1075,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Nutation tightens which ligaments?","options": [{"key": "A","text": "Posterior sacroiliac ligament"},{"key": "B","text": "Iliolumbar ligament only"},{"key": "C","text": "Sacrotuberous and sacrospinous ligaments"},{"key": "D","text": "Anterior sacroiliac ligament"}],"correct": "C","explanation": "Nutation tightens sacrotuberous, sacrospinous, and interosseous SI ligaments, stabilizing the joint."},{"id": 1076,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "During standing, the sacrum tends to:","options": [{"key": "A","text": "Remain neutral"},{"key": "B","text": "Nutate"},{"key": "C","text": "Rotate laterally"},{"key": "D","text": "Counternutate"}],"correct": "B","explanation": "Weight bearing in standing causes nutation of the sacrum (self-locking mechanism of the SI joint)."},{"id": 1077,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The 'form closure' of SI joint refers to:","options": [{"key": "A","text": "Bony configuration and joint surface geometry providing stability"},{"key": "B","text": "Muscle contraction stability"},{"key": "C","text": "Ligamentous tension creating stability"},{"key": "D","text": "All of the above"}],"correct": "A","explanation": "Form closure = stability from the interlocking shape of bony surfaces and cartilage (passive mechanism)."},{"id": 1078,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The 'force closure' of SI joint refers to:","options": [{"key": "A","text": "Joint fluid pressure"},{"key": "B","text": "Bony locking mechanism"},{"key": "C","text": "Capsular tension only"},{"key": "D","text": "Compression by muscles and ligaments (active mechanism)"}],"correct": "D","explanation": "Force closure = additional compression/stability provided by muscles (biceps femoris, gluteus maximus, etc.)."},{"id": 1079,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The total range of motion at SI joint is approximately:","options": [{"key": "A","text": "20-30°"},{"key": "B","text": "10-15°"},{"key": "C","text": "0° (no movement)"},{"key": "D","text": "1-4°"}],"correct": "D","explanation": "SI joint has very limited mobility: approximately 1-4° of rotation and 1-2 mm translation."},{"id": 1080,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which muscle is considered a key 'force closure' stabilizer of SI joint?","options": [{"key": "A","text": "Psoas major"},{"key": "B","text": "Rectus femoris"},{"key": "C","text": "Sartorius"},{"key": "D","text": "Biceps femoris (long head)"}],"correct": "D","explanation": "Biceps femoris (via sacrotuberous ligament) and gluteus maximus are key force closure muscles of SI joint."},{"id": 1081,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Hard","question": "Pelvic incidence (PI) is defined as:","options": [{"key": "A","text": "Pelvic tilt angle"},{"key": "B","text": "Angle between sacral endplate and horizontal"},{"key": "C","text": "Lumbar lordosis angle"},{"key": "D","text": "Angle between a line perpendicular to sacral endplate and a line from midpoint of sacral endplate to femoral head center"}],"correct": "D","explanation": "Pelvic incidence = angle between perpendicular to S1 endplate and line to femoral head axis; it is a fixed anatomical parameter."},{"id": 1082,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "Posterior pelvic pain during pregnancy is most commonly due to:","options": [{"key": "A","text": "Coccydynia"},{"key": "B","text": "Piriformis syndrome"},{"key": "C","text": "SI joint dysfunction due to relaxin-induced ligament laxity"},{"key": "D","text": "Lumbar disc herniation"}],"correct": "C","explanation": "Relaxin hormone causes SI joint ligament laxity in pregnancy, leading to posterior pelvic/SI pain."},{"id": 1083,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The FABER (Patrick's) test provokes:","options": [{"key": "A","text": "Lumbar disc pain"},{"key": "B","text": "Hip joint and SI joint pain"},{"key": "C","text": "Femoral nerve stretch"},{"key": "D","text": "Piriformis only"}],"correct": "B","explanation": "FABER (Flexion, ABduction, External Rotation) stresses both the hip joint and SI joint."},{"id": 1084,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The FADIR test is used to assess:","options": [{"key": "A","text": "SI joint dysfunction"},{"key": "B","text": "Lumbar stenosis"},{"key": "C","text": "Piriformis syndrome and hip impingement"},{"key": "D","text": "Coccydynia"}],"correct": "C","explanation": "FADIR (Flexion, ADduction, Internal Rotation) tests for hip impingement and piriformis syndrome."},{"id": 1085,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Gaenslen's test is specific for:","options": [{"key": "A","text": "Hip pathology"},{"key": "B","text": "Sacroiliac joint dysfunction"},{"key": "C","text": "Piriformis"},{"key": "D","text": "L4-L5 disc herniation"}],"correct": "B","explanation": "Gaenslen's test (one hip in hyperextension, other in flexion) stresses the SI joint."},{"id": 1086,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The posterior shear (thigh thrust) test for SI joint involves:","options": [{"key": "A","text": "Rotation of pelvis"},{"key": "B","text": "Flexion of trunk"},{"key": "C","text": "Extension of hip"},{"key": "D","text": "Axial load through flexed hip applying posterior shear to SI joint"}],"correct": "D","explanation": "Thigh thrust test applies posterior shear through the femur to provoke SI joint pain."},{"id": 1087,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The compression test for SI joint is performed by applying:","options": [{"key": "A","text": "Medially directed force on iliac crests (belt test)"},{"key": "B","text": "Anterior-posterior force on ASIS"},{"key": "C","text": "Distraction force on iliac crests"},{"key": "D","text": "Downward pressure on symphysis"}],"correct": "A","explanation": "SI compression test compresses the iliac crests medially to stress the posterior SI structures."},{"id": 1088,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The distraction test for SI joint stresses:","options": [{"key": "A","text": "Anterior capsule"},{"key": "B","text": "Anterior SI ligaments"},{"key": "C","text": "Posterior SI ligaments and interosseous ligament"},{"key": "D","text": "Sacrotuberous ligament only"}],"correct": "B","explanation": "Distraction (gapping) test stretches the anterior SI ligaments by pushing ASIS laterally."},{"id": 1089,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Ankylosing spondylitis classically starts at:","options": [{"key": "A","text": "Sacroiliac joints bilaterally"},{"key": "B","text": "Lumbar spine"},{"key": "C","text": "Cervical spine"},{"key": "D","text": "Hip joints"}],"correct": "A","explanation": "Ankylosing spondylitis (AS) characteristically begins with bilateral sacroiliitis and ascends."},{"id": 1090,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "On X-ray, sacroiliitis grading system uses how many grades?","options": [{"key": "A","text": "4"},{"key": "B","text": "6"},{"key": "C","text": "5"},{"key": "D","text": "3"}],"correct": "C","explanation": "NY criteria grades sacroiliitis 0-IV: 0=normal, I=suspicious, II=minimal, III=moderate, IV=ankylosis."},{"id": 1091,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The HLA-B27 antigen is strongly associated with:","options": [{"key": "A","text": "Infective sacroiliitis"},{"key": "B","text": "Rheumatoid arthritis of SI joint"},{"key": "C","text": "Ankylosing spondylitis and spondyloarthropathies"},{"key": "D","text": "Osteoarthritis of SI joint"}],"correct": "C","explanation": "HLA-B27 is present in ~90% of ankylosing spondylitis patients; strongly linked to spondyloarthropathies."},{"id": 1092,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "The 'bamboo spine' appearance on X-ray is due to:","options": [{"key": "A","text": "Osteophyte formation"},{"key": "B","text": "Disc calcification"},{"key": "C","text": "Posterior element fusion only"},{"key": "D","text": "Ossification of annulus fibrosus (syndesmophytes) in AS"}],"correct": "D","explanation": "Bamboo spine in AS = bridging syndesmophytes along the spine, creating a bamboo-like appearance."},{"id": 1093,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Osteitis condensans ilii (OCI) affects:","options": [{"key": "A","text": "SI joint unilaterally"},{"key": "B","text": "Sacrum bilaterally"},{"key": "C","text": "Entire ilium"},{"key": "D","text": "Inferior iliac portion adjacent to SI joint bilaterally"}],"correct": "D","explanation": "OCI = triangular sclerosis of the inferior iliac bone near the SI joint, usually bilateral in multiparous women."},{"id": 1094,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Piriformis muscle originates from:","options": [{"key": "A","text": "Ischial tuberosity"},{"key": "B","text": "Posterior ilium"},{"key": "C","text": "Sacral cornua"},{"key": "D","text": "Anterior surface of S2-S4 and greater sciatic notch"}],"correct": "D","explanation": "Piriformis originates from the pelvic surface (anterior) of S2-S4 sacral segments and greater sciatic notch."},{"id": 1095,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Piriformis syndrome causes pain due to:","options": [{"key": "A","text": "Compression of femoral nerve"},{"key": "B","text": "Irritation/compression of sciatic nerve by piriformis"},{"key": "C","text": "L5 disc herniation"},{"key": "D","text": "SI joint hypermobility"}],"correct": "B","explanation": "Piriformis syndrome occurs when the piriformis irritates/compresses the sciatic nerve in the gluteal region."},{"id": 1096,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The Pace test (resisted abduction-ER of hip in seated position) is positive in:","options": [{"key": "A","text": "Greater trochanteric bursitis"},{"key": "B","text": "Hip osteoarthritis"},{"key": "C","text": "SI joint pain"},{"key": "D","text": "Piriformis syndrome"}],"correct": "D","explanation": "Pace test reproduces pain by activating the piriformis against resistance, suggesting piriformis syndrome."},{"id": 1097,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Easy","question": "The sciatic nerve is formed by:","options": [{"key": "A","text": "L4-S3 nerve roots"},{"key": "B","text": "S1-S3 roots only"},{"key": "C","text": "L5-S2 roots only"},{"key": "D","text": "L2-L4 nerve roots"}],"correct": "A","explanation": "Sciatic nerve = L4, L5, S1, S2, S3 roots; the largest nerve in the body."},{"id": 1098,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The pudendal nerve arises from:","options": [{"key": "A","text": "S1-S3"},{"key": "B","text": "L2-L4"},{"key": "C","text": "L5-S1"},{"key": "D","text": "S2-S4"}],"correct": "D","explanation": "Pudendal nerve arises from S2, S3, S4 anterior rami and exits through the greater sciatic foramen."},{"id": 1099,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Alcock's canal (pudendal canal) is located in:","options": [{"key": "A","text": "Lesser sciatic foramen"},{"key": "B","text": "Greater sciatic foramen"},{"key": "C","text": "Lateral wall of ischiorectal fossa (obturator fascia)"},{"key": "D","text": "Sacral canal"}],"correct": "C","explanation": "Alcock's canal is a fascial canal in the lateral wall of the ischiorectal fossa transmitting the pudendal nerve."},{"id": 1100,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The nerve to piriformis arises from:","options": [{"key": "A","text": "L5-S1"},{"key": "B","text": "S1-S2"},{"key": "C","text": "L4-L5"},{"key": "D","text": "S2-S3"}],"correct": "B","explanation": "The nerve to piriformis arises from S1 and S2 anterior rami directly."},{"id": 1101,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The superior gluteal nerve (L4-S1) exits:","options": [{"key": "A","text": "Through lesser sciatic foramen"},{"key": "B","text": "Below piriformis"},{"key": "C","text": "Above piriformis through greater sciatic foramen"},{"key": "D","text": "Through obturator foramen"}],"correct": "C","explanation": "Superior gluteal nerve and vessels exit the greater sciatic foramen ABOVE piriformis."},{"id": 1102,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "The inferior gluteal nerve exits:","options": [{"key": "A","text": "Below piriformis through greater sciatic foramen"},{"key": "B","text": "Above piriformis"},{"key": "C","text": "Through obturator foramen"},{"key": "D","text": "Through lesser sciatic foramen"}],"correct": "A","explanation": "Inferior gluteal nerve (L5-S2) exits BELOW piriformis through the greater sciatic foramen."},{"id": 1103,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The nerve to obturator internus arises from:","options": [{"key": "A","text": "L5-S2"},{"key": "B","text": "S2-S3"},{"key": "C","text": "L3-L4"},{"key": "D","text": "S1-S2"}],"correct": "A","explanation": "Nerve to obturator internus arises from L5, S1, S2 and exits via greater sciatic foramen below piriformis."},{"id": 1104,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Sacral sparing in spinal cord injury indicates:","options": [{"key": "A","text": "Injury below S1"},{"key": "B","text": "No significance"},{"key": "C","text": "Incomplete injury with preserved S4-S5 function"},{"key": "D","text": "Complete injury"}],"correct": "C","explanation": "Sacral sparing (preserved perianal sensation/rectal tone/great toe flexion) indicates incomplete SCI."},{"id": 1105,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The dermatome for perianal and perineal sensation is:","options": [{"key": "A","text": "L5"},{"key": "B","text": "S3"},{"key": "C","text": "S4-S5"},{"key": "D","text": "S1"}],"correct": "C","explanation": "Perianal and perineal sensation is supplied by S4-S5 dermatomes (saddle area)."},{"id": 1106,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The true pelvis is bounded superiorly by:","options": [{"key": "A","text": "Sacral promontory only"},{"key": "B","text": "Pelvic inlet (linea terminalis)"},{"key": "C","text": "Iliac crest"},{"key": "D","text": "Pelvic floor"}],"correct": "B","explanation": "True pelvis is bounded superiorly by the pelvic inlet (linea terminalis/pelvic brim)."},{"id": 1107,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Hard","question": "The pelvic inlet (brim) is formed by:","options": [{"key": "A","text": "Sacral promontory, ala of sacrum, arcuate line, pectineal line, pubic crest"},{"key": "B","text": "Iliac crests"},{"key": "C","text": "Coccyx and pubis"},{"key": "D","text": "Ischial tuberosities only"}],"correct": "A","explanation": "Pelvic inlet = sacral promontory + ala of sacrum + arcuate line + pectineal line + pubic symphysis superior."},{"id": 1108,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The obstetric conjugate (true conjugate) is measured from:","options": [{"key": "A","text": "Sacral promontory to inferior symphysis"},{"key": "B","text": "Coccyx to pubic arch"},{"key": "C","text": "Sacral promontory to posterior superior pubic symphysis"},{"key": "D","text": "S2 to pubic symphysis"}],"correct": "C","explanation": "Obstetric conjugate = shortest AP diameter of pelvis; from sacral promontory to posterior surface of pubic symphysis."},{"id": 1109,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The diagonal conjugate is measured from:","options": [{"key": "A","text": "S2 to pubis"},{"key": "B","text": "Coccyx to symphysis"},{"key": "C","text": "Sacral promontory to inferior margin of symphysis pubis"},{"key": "D","text": "Sacral promontory to superior symphysis"}],"correct": "C","explanation": "Diagonal conjugate (clinically measurable) = sacral promontory to inferior border of pubic symphysis; normally >12.5 cm."},{"id": 1110,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The pelvic outlet is bounded by:","options": [{"key": "A","text": "Iliac wings"},{"key": "B","text": "Ischial spines only"},{"key": "C","text": "Symphysis pubis, ischial tuberosities, sacrotuberous ligament, coccyx"},{"key": "D","text": "Pelvic brim anteriorly"}],"correct": "C","explanation": "Pelvic outlet boundaries: symphysis pubis (anterior), ischial tuberosities (lateral), sacrotuberous ligaments, coccyx (posterior)."},{"id": 1111,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The interspinous diameter of the pelvis (narrowest diameter) is between:","options": [{"key": "A","text": "Ischial tuberosities"},{"key": "B","text": "Sacral ala"},{"key": "C","text": "Ischial spines"},{"key": "D","text": "Iliac crests"}],"correct": "C","explanation": "The interspinous diameter (between ischial spines) is the narrowest pelvic diameter, normally ≥10.5 cm."},{"id": 1112,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The gold standard imaging for sacroiliac joint inflammation is:","options": [{"key": "A","text": "Plain X-ray"},{"key": "B","text": "Bone scan"},{"key": "C","text": "MRI with STIR sequence"},{"key": "D","text": "CT scan"}],"correct": "C","explanation": "MRI (STIR/T2 fat-suppressed) is gold standard for detecting early sacroiliitis (bone marrow edema)."},{"id": 1113,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "CT scan of SI joint is best for detecting:","options": [{"key": "A","text": "Nerve root compression"},{"key": "B","text": "Bone marrow edema"},{"key": "C","text": "Structural/bony changes: erosions, sclerosis, ankylosis"},{"key": "D","text": "Soft tissue inflammation"}],"correct": "C","explanation": "CT is superior for structural changes (erosions, sclerosis, joint space changes) in sacroiliitis."},{"id": 1114,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Ferguson's view (X-ray) is used for:","options": [{"key": "A","text": "Sacroiliac joint visualization"},{"key": "B","text": "Lumbar disc"},{"key": "C","text": "Coccyx lateral view"},{"key": "D","text": "Lumbar lordosis measurement"}],"correct": "A","explanation": "Ferguson's view (AP pelvis with 25-30° cephalad angulation) provides en-face view of SI joints."},{"id": 1115,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "On MRI, active sacroiliitis shows as:","options": [{"key": "A","text": "T1 hypointense, T2/STIR hyperintense (bone marrow edema)"},{"key": "B","text": "Only T1 changes"},{"key": "C","text": "T1 hyperintense"},{"key": "D","text": "Normal signal"}],"correct": "A","explanation": "Active sacroiliitis = subchondral bone marrow edema: T1 low, STIR/T2 fat-sat high signal."},{"id": 1116,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Sacral insufficiency fracture is best diagnosed by:","options": [{"key": "A","text": "MRI or bone scan"},{"key": "B","text": "Plain X-ray"},{"key": "C","text": "Ultrasound"},{"key": "D","text": "CT scan"}],"correct": "A","explanation": "Sacral insufficiency fractures (in osteoporosis) are best seen on MRI or bone scan; X-rays often miss them."},{"id": 1117,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Zone I sacral fractures (Denis classification) involve:","options": [{"key": "A","text": "Sacral canal"},{"key": "B","text": "Coccyx"},{"key": "C","text": "Sacral ala (lateral to neural foramina)"},{"key": "D","text": "Neural foramina"}],"correct": "C","explanation": "Denis Zone I = lateral sacral ala, lateral to neural foramina; least neurological risk."},{"id": 1118,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Zone II sacral fractures involve:","options": [{"key": "A","text": "Through the neural foramina"},{"key": "B","text": "Coccyx only"},{"key": "C","text": "Lateral to foramina"},{"key": "D","text": "The sacral canal (central)"}],"correct": "A","explanation": "Denis Zone II fractures pass through the sacral neural foramina; risk of root injury."},{"id": 1119,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Zone III sacral fractures (Denis) involve:","options": [{"key": "A","text": "Foramina only"},{"key": "B","text": "Coccyx"},{"key": "C","text": "Central sacral canal"},{"key": "D","text": "Lateral ala"}],"correct": "C","explanation": "Denis Zone III = central fractures involving the sacral canal; highest risk of cauda equina injury."},{"id": 1120,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "H-type (bilateral Zone II + transverse) sacral fracture is associated with:","options": [{"key": "A","text": "Only pelvic ring disruption"},{"key": "B","text": "Bilateral sacral root injury and cauda equina syndrome"},{"key": "C","text": "Coccydynia"},{"key": "D","text": "Isolated L5 injury"}],"correct": "B","explanation": "H-type (U-type) sacral fracture = bilateral vertical + transverse component; high risk of neurological injury."},{"id": 1121,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Sacrococcygeal teratoma is most common in:","options": [{"key": "A","text": "Adults only"},{"key": "B","text": "Female infants"},{"key": "C","text": "Male infants"},{"key": "D","text": "Equal in both sexes"}],"correct": "B","explanation": "Sacrococcygeal teratoma is the most common neonatal tumor; 3-4x more common in females."},{"id": 1122,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tarlov cysts are:","options": [{"key": "A","text": "Meningeal cysts along sacral nerve root sleeves"},{"key": "B","text": "SI joint ganglia"},{"key": "C","text": "Epidermoid cysts in sacral canal"},{"key": "D","text": "Disc cysts"}],"correct": "A","explanation": "Tarlov (perineural) cysts are dilated nerve root sleeve/meningeal cysts, common at sacral levels."},{"id": 1123,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The sacral hiatus is used clinically NOT only for caudal epidural but also for:","options": [{"key": "A","text": "All of the above"},{"key": "B","text": "Sacral nerve root blocks"},{"key": "C","text": "Lumbar puncture"},{"key": "D","text": "Intrathecal drug delivery only at sacral level"}],"correct": "B","explanation": "The sacral hiatus is also used for sacral nerve root blocks and caudal corticosteroid injections."},{"id": 1124,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Alar dysgenesis (sacral agenesis) is associated with maternal:","options": [{"key": "A","text": "Diabetes mellitus"},{"key": "B","text": "Hypertension"},{"key": "C","text": "Hypothyroidism"},{"key": "D","text": "Rubella infection"}],"correct": "A","explanation": "Sacral agenesis/caudal regression syndrome is strongly associated with maternal diabetes mellitus."},{"id": 1125,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Hard","question": "The 'trident sacrum' configuration on X-ray suggests:","options": [{"key": "A","text": "Normal variant"},{"key": "B","text": "Achondroplasia"},{"key": "C","text": "Sacral agenesis"},{"key": "D","text": "Down syndrome"}],"correct": "D","explanation": "Trident sacrum (short sacrum with hypoplastic S1) is a feature of Down syndrome."},{"id": 1126,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The erector spinae muscle group attaches to sacrum via:","options": [{"key": "A","text": "Sacrotuberous ligament"},{"key": "B","text": "Posterior SI ligament"},{"key": "C","text": "Sacrospinous ligament"},{"key": "D","text": "Thoracolumbar fascia and sacral crest"}],"correct": "D","explanation": "Erector spinae (iliocostalis, longissimus, spinalis) attach to sacrum via thoracolumbar fascia and sacral crests."},{"id": 1127,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The levator ani muscle attaches to:","options": [{"key": "A","text": "Ischial spine"},{"key": "B","text": "Coccyx and anococcygeal raphe"},{"key": "C","text": "Sacral promontory"},{"key": "D","text": "Sacral cornua only"}],"correct": "B","explanation": "Levator ani (including coccygeus) inserts into the coccyx and anococcygeal raphe, forming the pelvic floor."},{"id": 1128,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The gluteus maximus originates from:","options": [{"key": "A","text": "Posterior ilium, sacrum, coccyx, and sacrotuberous ligament"},{"key": "B","text": "Ischial tuberosity"},{"key": "C","text": "Greater trochanter"},{"key": "D","text": "ASIS only"}],"correct": "A","explanation": "Gluteus maximus has a broad origin from the posterior ilium, sacrum, coccyx, and sacrotuberous ligament."},{"id": 1129,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Hard","question": "Which muscle's contraction can cause counternutation of sacrum?","options": [{"key": "A","text": "Psoas major"},{"key": "B","text": "Multifidus alone"},{"key": "C","text": "Erector spinae and gluteus maximus"},{"key": "D","text": "Rectus abdominis and hip flexors"}],"correct": "D","explanation": "Rectus abdominis (flexion) and hip flexors cause posterior pelvic tilt/counternutation of sacrum."},{"id": 1130,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The lumbosacral trunk is formed by:","options": [{"key": "A","text": "Part of L4 and all of L5 anterior rami"},{"key": "B","text": "L3-L5 anterior rami"},{"key": "C","text": "L5 anterior ramus only"},{"key": "D","text": "L4-L5 posterior rami"}],"correct": "A","explanation": "Lumbosacral trunk = part of L4 + entire L5 anterior rami; joins sacral plexus."},{"id": 1131,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Sacral spinal stenosis most commonly causes:","options": [{"key": "A","text": "Lumbar radiculopathy"},{"key": "B","text": "Upper motor neuron signs"},{"key": "C","text": "Myelopathy"},{"key": "D","text": "Cauda equina syndrome and neurogenic claudication"}],"correct": "D","explanation": "Stenosis at sacral level compresses cauda equina roots, causing neurogenic claudication/CES."},{"id": 1132,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The pelvic splanchnic nerves (nervi erigentes) arise from:","options": [{"key": "A","text": "L1-L2 only"},{"key": "B","text": "S1-S2"},{"key": "C","text": "S2-S4 (parasympathetic)"},{"key": "D","text": "T10-L2 (sympathetic)"}],"correct": "C","explanation": "Pelvic splanchnic nerves carry parasympathetic supply to pelvic organs, arising from S2, S3, S4."},{"id": 1133,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The presacral nerve (superior hypogastric plexus) is located at:","options": [{"key": "A","text": "L5-S1 anterior to sacral promontory"},{"key": "B","text": "S2-S3 level"},{"key": "C","text": "Posterior sacrum"},{"key": "D","text": "L1-L2 level"}],"correct": "A","explanation": "Superior hypogastric plexus (presacral nerve) lies anterior to the sacral promontory at L5-S1."},{"id": 1134,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Referred pain from SI joint is most commonly felt in:","options": [{"key": "A","text": "Foot and ankle"},{"key": "B","text": "Anterior thigh"},{"key": "C","text": "Groin only"},{"key": "D","text": "Posterior thigh to knee, buttock, and lower lumbar region"}],"correct": "D","explanation": "SI joint pain refers to the posterior thigh (above knee), buttock, and lower lumbar/sacral region."},{"id": 1135,"subject": "Anatomy","topic": "Lower Limb","difficulty": "Medium","question": "Active SLR (straight leg raise) test is used to assess:","options": [{"key": "A","text": "Hamstring flexibility"},{"key": "B","text": "Hip flexor strength only"},{"key": "C","text": "Disc herniation"},{"key": "D","text": "Load transfer through pelvis and SI joint stability"}],"correct": "D","explanation": "Active SLR test evaluates force closure of the SI joint; positive if pain with raising leg from supine."},{"id": 1136,"subject": "Anatomy","topic": "Abdomen & Pelvis","difficulty": "Medium","question": "The P4 (posterior pelvic pain provocation) test applies load through:","options": [{"key": "A","text": "Flexed hip with posterior shear on SI joint"},{"key": "B","text": "Coccyx"},{"key": "C","text": "Symphysis pubis"},{"key": "D","text": "ASIS"}],"correct": "A","explanation": "P4/thigh thrust test: examiner applies posterior shear via the femur through the flexed hip onto SI joint."},{"id": 1137,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which set of 5 SI joint provocation tests, if 3/5 positive, is most diagnostic?","options": [{"key": "A","text": "SLR, FADIR, Pace, Thomas, Ober"},{"key": "B","text": "Distraction, thigh thrust, compression, Gaenslen, sacral thrust"},{"key": "C","text": "None standardized"},{"key": "D","text": "FABER, SLR, Gaenslen, distraction, compression"}],"correct": "B","explanation": "Laslett's cluster of 5 SI tests (distraction, thigh thrust, compression, Gaenslen's, sacral thrust): ≥3/5 positive is diagnostic."},{"id": 1138,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "How many pairs of ribs are present in the human thoracic cage?","options": [{"key": "A","text": "11"},{"key": "B","text": "12"},{"key": "C","text": "10"},{"key": "D","text": "14"}],"correct": "B","explanation": "There are 12 pairs of ribs in the human thoracic cage (24 ribs total)."},{"id": 1139,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "True ribs are those that:","options": [{"key": "A","text": "Float freely"},{"key": "B","text": "Articulate with sternum via costal cartilage directly"},{"key": "C","text": "Do not articulate with sternum"},{"key": "D","text": "Articulate only with vertebrae"}],"correct": "B","explanation": "True ribs (1-7) have their own costal cartilage connecting directly to the sternum."},{"id": 1140,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "False ribs include which rib numbers?","options": [{"key": "A","text": "8-12"},{"key": "B","text": "11-12"},{"key": "C","text": "8-10"},{"key": "D","text": "1-7"}],"correct": "A","explanation": "False ribs (8-12) either join the cartilage above (8-10) or are floating (11-12)."},{"id": 1141,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Floating ribs are:","options": [{"key": "A","text": "Ribs 9-12"},{"key": "B","text": "Ribs 10 and 11"},{"key": "C","text": "Ribs 10-12"},{"key": "D","text": "Ribs 11 and 12"}],"correct": "D","explanation": "Floating ribs (11 and 12) have no anterior attachment; their costal cartilages are free."},{"id": 1142,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The head of a typical rib articulates with:","options": [{"key": "A","text": "Two adjacent vertebral bodies and the intervertebral disc"},{"key": "B","text": "Sternum"},{"key": "C","text": "Transverse process only"},{"key": "D","text": "One vertebral body only"}],"correct": "A","explanation": "A typical rib head (2-9) articulates with two adjacent vertebral bodies and the intervening disc."},{"id": 1143,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The tubercle of a rib articulates with:","options": [{"key": "A","text": "Transverse process of corresponding vertebra"},{"key": "B","text": "Costal cartilage"},{"key": "C","text": "Adjacent vertebral body"},{"key": "D","text": "Sternum"}],"correct": "A","explanation": "The rib tubercle articulates with the transverse process of the numerically corresponding vertebra."},{"id": 1144,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The costal groove is located on the:","options": [{"key": "A","text": "Outer surface of rib"},{"key": "B","text": "Superior surface of rib"},{"key": "C","text": "Anterior surface of rib"},{"key": "D","text": "Inferior inner surface of rib"}],"correct": "D","explanation": "The costal groove on the inferior inner border of the rib lodges the intercostal vein, artery, and nerve (VAN from above)."},{"id": 1145,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The order of structures in the costal groove (superior to inferior) is:","options": [{"key": "A","text": "Vein, Nerve, Artery"},{"key": "B","text": "Artery, Vein, Nerve"},{"key": "C","text": "Nerve, Artery, Vein"},{"key": "D","text": "Vein, Artery, Nerve"}],"correct": "D","explanation": "VAN = Vein (most superior), Artery, Nerve (most inferior) in the costal groove."},{"id": 1146,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The angle of the rib is the site where the rib:","options": [{"key": "A","text": "Gives origin to intercostal muscle"},{"key": "B","text": "Connects to costal cartilage"},{"key": "C","text": "Bends sharply anterolaterally"},{"key": "D","text": "Articulates with vertebra"}],"correct": "C","explanation": "The angle of the rib is the point of sharpest curvature, where erector spinae attach and the rib bends forward."},{"id": 1147,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "Which rib is the shortest and broadest?","options": [{"key": "A","text": "Rib 2"},{"key": "B","text": "Rib 7"},{"key": "C","text": "Rib 12"},{"key": "D","text": "Rib 1"}],"correct": "D","explanation": "Rib 1 is the shortest, broadest, and most curved of all ribs."},{"id": 1148,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The groove for the subclavian artery is found on:","options": [{"key": "A","text": "Clavicle"},{"key": "B","text": "Rib 3"},{"key": "C","text": "Rib 2"},{"key": "D","text": "Rib 1 (posterior surface)"}],"correct": "D","explanation": "Rib 1 has a groove for the subclavian artery on its superior surface (posterior to the scalene tubercle)."},{"id": 1149,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The scalene tubercle (Lisfranc tubercle) is an attachment for:","options": [{"key": "A","text": "Scalenus anterior (anterior scalene)"},{"key": "B","text": "Serratus anterior"},{"key": "C","text": "Scalenus medius"},{"key": "D","text": "Subclavius"}],"correct": "A","explanation": "Scalene tubercle on the superior surface of rib 1 is the insertion of the scalenus anterior muscle."},{"id": 1150,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Which rib has the highest risk of injury to the brachial plexus and subclavian vessels when fractured?","options": [{"key": "A","text": "Rib 4"},{"key": "B","text": "Rib 1"},{"key": "C","text": "Rib 7"},{"key": "D","text": "Rib 12"}],"correct": "B","explanation": "Fracture of rib 1 risks injury to the brachial plexus and subclavian vessels due to proximity."},{"id": 1151,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "Cervical rib is an anomalous rib arising from:","options": [{"key": "A","text": "T1"},{"key": "B","text": "C6"},{"key": "C","text": "C5"},{"key": "D","text": "C7"}],"correct": "D","explanation": "Cervical rib arises from C7 vertebra; can compress subclavian artery/brachial plexus (thoracic outlet syndrome)."},{"id": 1152,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The costal cartilage of which rib is the longest?","options": [{"key": "A","text": "Rib 10"},{"key": "B","text": "Rib 1"},{"key": "C","text": "Rib 7"},{"key": "D","text": "Rib 5"}],"correct": "C","explanation": "Rib 7 has the longest costal cartilage among the true ribs."},{"id": 1153,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The neck of the rib connects:","options": [{"key": "A","text": "Tubercle to angle"},{"key": "B","text": "Head to tubercle"},{"key": "C","text": "Head to body (shaft)"},{"key": "D","text": "Costal cartilage to body"}],"correct": "B","explanation": "The neck is the constricted portion connecting the head to the tubercle of the rib."},{"id": 1154,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The costovertebral joint is classified as:","options": [{"key": "A","text": "Synovial plane joint"},{"key": "B","text": "Cartilaginous joint"},{"key": "C","text": "Pivot joint"},{"key": "D","text": "Fibrous joint"}],"correct": "A","explanation": "Costovertebral joints (head of rib with vertebral body) are synovial plane joints."},{"id": 1155,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The intra-articular ligament of the costovertebral joint divides the joint into:","options": [{"key": "A","text": "Three compartments"},{"key": "B","text": "Anterior and posterior parts"},{"key": "C","text": "Two cavities (superior and inferior)"},{"key": "D","text": "No division"}],"correct": "C","explanation": "The intra-articular ligament divides the costovertebral joint into two synovial cavities (for the two vertebral facets)."},{"id": 1156,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Ribs 10, 11, and 12 differ from typical ribs because:","options": [{"key": "A","text": "They lack a tubercle"},{"key": "B","text": "Both B and C for 11 and 12"},{"key": "C","text": "They are floating"},{"key": "D","text": "They have only one facet on the head"}],"correct": "B","explanation": "Ribs 11 and 12 have a single head facet and no tubercle (no costotransverse joint); rib 10 has a single facet only."},{"id": 1157,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The pump handle movement of ribs primarily increases:","options": [{"key": "A","text": "Vertical diameter of thorax"},{"key": "B","text": "AP (anteroposterior) diameter of thorax"},{"key": "C","text": "Oblique diameter"},{"key": "D","text": "Transverse diameter of thorax"}],"correct": "B","explanation": "Upper ribs move in a pump-handle manner, elevating the sternum and increasing AP diameter."},{"id": 1158,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The bucket handle movement of ribs primarily increases:","options": [{"key": "A","text": "AP diameter"},{"key": "B","text": "Vertical diameter"},{"key": "C","text": "Transverse diameter of thorax"},{"key": "D","text": "No change in diameter"}],"correct": "C","explanation": "Lower ribs move in a bucket-handle manner, swinging outward to increase transverse (lateral) diameter."},{"id": 1159,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The caliper movement is seen in:","options": [{"key": "A","text": "Floating ribs (11-12)"},{"key": "B","text": "Upper ribs"},{"key": "C","text": "Rib 1"},{"key": "D","text": "Middle ribs"}],"correct": "A","explanation": "Floating ribs (11-12) move in a caliper (pincer) motion, moving laterally during inspiration."},{"id": 1160,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The sternum consists of how many parts?","options": [{"key": "A","text": "2"},{"key": "B","text": "3"},{"key": "C","text": "4"},{"key": "D","text": "5"}],"correct": "B","explanation": "Sternum has 3 parts: manubrium, body (gladiolus), and xiphoid process."},{"id": 1161,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sternal angle (angle of Louis/Ludwig) is the junction between:","options": [{"key": "A","text": "Rib 1 and manubrium"},{"key": "B","text": "Manubrium and clavicle"},{"key": "C","text": "Body and xiphoid process"},{"key": "D","text": "Manubrium and body of sternum"}],"correct": "D","explanation": "Sternal angle (of Louis) = manubriosternal joint; at level of T4-T5 disc and 2nd costal cartilage."},{"id": 1162,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sternal angle is a landmark for:","options": [{"key": "A","text": "Rib 2 costal cartilage, carina, aortic arch, T4-T5 level"},{"key": "B","text": "Rib 1 attachment"},{"key": "C","text": "Xiphoid process"},{"key": "D","text": "Rib 3 attachment"}],"correct": "A","explanation": "Sternal angle is a key landmark: marks rib 2 cartilage, bifurcation of trachea (carina), aortic arch, T4-T5 disc."},{"id": 1163,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The xiphisternal joint is at the level of:","options": [{"key": "A","text": "T10"},{"key": "B","text": "T8"},{"key": "C","text": "T7"},{"key": "D","text": "T9"}],"correct": "D","explanation": "The xiphisternal junction (body-xiphoid) is at the level of T9."},{"id": 1164,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The jugular (suprasternal) notch is at the level of:","options": [{"key": "A","text": "T1-T2"},{"key": "B","text": "T2-T3"},{"key": "C","text": "T4"},{"key": "D","text": "T3"}],"correct": "B","explanation": "The jugular notch of the manubrium is at the level of the T2-T3 intervertebral disc."},{"id": 1165,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The manubrium articulates with which ribs?","options": [{"key": "A","text": "Rib 1 only"},{"key": "B","text": "Ribs 1 and upper half of rib 2"},{"key": "C","text": "Ribs 1-3"},{"key": "D","text": "Ribs 1 and 2 only"}],"correct": "B","explanation": "The manubrium articulates with rib 1 (directly) and the upper part of rib 2 at the sternal angle."},{"id": 1166,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The body of sternum articulates with which ribs?","options": [{"key": "A","text": "Ribs 2-7"},{"key": "B","text": "Ribs 3-7"},{"key": "C","text": "Ribs 1-6"},{"key": "D","text": "Lower half of rib 2 through rib 7"}],"correct": "D","explanation": "The sternal body articulates with lower half of rib 2 cartilage through rib 7 cartilage."},{"id": 1167,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The xiphoid process ossifies completely by approximately:","options": [{"key": "A","text": "40 years"},{"key": "B","text": "Birth"},{"key": "C","text": "20 years"},{"key": "D","text": "60 years"}],"correct": "A","explanation": "Xiphoid process is cartilaginous at birth, begins ossifying in early adulthood, completes ~40 years."},{"id": 1168,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Sternal angle is a synovial joint of type:","options": [{"key": "A","text": "Saddle"},{"key": "B","text": "Ball and socket"},{"key": "C","text": "Hinge"},{"key": "D","text": "Plane (gliding)"}],"correct": "D","explanation": "Manubriosternal joint is a symphysis (fibrocartilaginous) or synovial plane joint; allows slight angular movement."},{"id": 1169,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The primary ossification center of the sternum develops from:","options": [{"key": "A","text": "Neural crest cells"},{"key": "B","text": "Single central bar"},{"key": "C","text": "Membranous ossification"},{"key": "D","text": "Two lateral sternal bars that fuse"}],"correct": "D","explanation": "Sternum develops from two lateral sternal bars derived from mesoderm that fuse in the midline."},{"id": 1170,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Pectus excavatum (funnel chest) is a deformity of:","options": [{"key": "A","text": "Sternum depressed inward (posterior displacement)"},{"key": "B","text": "Laterally displaced sternum"},{"key": "C","text": "Ribs only"},{"key": "D","text": "Manubrium only"}],"correct": "A","explanation": "Pectus excavatum = posterior depression of sternum, reducing AP thoracic diameter."},{"id": 1171,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Pectus carinatum (pigeon chest) refers to:","options": [{"key": "A","text": "Posterior sternal depression"},{"key": "B","text": "Anterior protrusion of sternum"},{"key": "C","text": "Lateral rib flaring"},{"key": "D","text": "Rib absence"}],"correct": "B","explanation": "Pectus carinatum = anterior protrusion of sternum (like a bird keel), opposite of pectus excavatum."},{"id": 1172,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The external intercostal muscle fibers run in which direction?","options": [{"key": "A","text": "Horizontally"},{"key": "B","text": "Downward and backward (posteroinferior)"},{"key": "C","text": "Upward and forward"},{"key": "D","text": "Downward and forward (anteroinferior)"}],"correct": "D","explanation": "External intercostal fibers run downward and forward (like hands in pockets); active in inspiration."},{"id": 1173,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The internal intercostal muscle fibers run in which direction?","options": [{"key": "A","text": "Upward and backward"},{"key": "B","text": "Downward and backward (at right angles to external)"},{"key": "C","text": "Same as external intercostals"},{"key": "D","text": "Horizontally"}],"correct": "B","explanation": "Internal intercostal fibers run downward and backward (perpendicular to external), active in forced expiration."},{"id": 1174,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The innermost intercostal muscles are separated from internal intercostals by:","options": [{"key": "A","text": "Intercostal vein"},{"key": "B","text": "Parietal pleura"},{"key": "C","text": "Intercostal nerve and vessels"},{"key": "D","text": "Endothoracic fascia"}],"correct": "C","explanation": "The intercostal nerve (and vessels) run between the internal and innermost intercostal muscles."},{"id": 1175,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The external intercostal muscle is replaced anteriorly (near sternum) by:","options": [{"key": "A","text": "External intercostal membrane"},{"key": "B","text": "Transversus thoracis"},{"key": "C","text": "Internal intercostal"},{"key": "D","text": "Innermost intercostal"}],"correct": "A","explanation": "Anteriorly, the external intercostal is replaced by the external intercostal membrane (aponeurosis)."},{"id": 1176,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The internal intercostal muscle is replaced posteriorly (near vertebral column) by:","options": [{"key": "A","text": "Transversus thoracis"},{"key": "B","text": "Innermost intercostal"},{"key": "C","text": "Internal intercostal membrane"},{"key": "D","text": "Erector spinae"}],"correct": "C","explanation": "Posteriorly, the internal intercostal is replaced by the internal intercostal membrane (aponeurosis)."},{"id": 1177,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Transversus thoracis (sternocostalis) lies on the:","options": [{"key": "A","text": "Inner surface of anterior thoracic wall"},{"key": "B","text": "Lateral thoracic wall"},{"key": "C","text": "Posterior thoracic wall"},{"key": "D","text": "Outer thoracic wall"}],"correct": "A","explanation": "Transversus thoracis is on the inner surface of the anterior chest wall, deep to internal intercostals."},{"id": 1178,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The subcostal muscles are located:","options": [{"key": "A","text": "Laterally"},{"key": "B","text": "Posteriorly (near angles of ribs)"},{"key": "C","text": "Along the costal margin"},{"key": "D","text": "Anteriorly"}],"correct": "B","explanation": "Subcostal muscles are found in the posterior thorax near rib angles; they span 2-3 intercostal spaces."},{"id": 1179,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "Which intercostal muscles are the primary muscles of quiet inspiration?","options": [{"key": "A","text": "External intercostals"},{"key": "B","text": "Internal intercostals"},{"key": "C","text": "Innermost intercostals"},{"key": "D","text": "Subcostal muscles"}],"correct": "A","explanation": "External intercostal muscles elevate the ribs during quiet inspiration, increasing thoracic volume."},{"id": 1180,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The interchondral part of the internal intercostal muscle is active in:","options": [{"key": "A","text": "Quiet inspiration"},{"key": "B","text": "No respiratory role"},{"key": "C","text": "Forced expiration only"},{"key": "D","text": "Quiet expiration"}],"correct": "A","explanation": "The interchondral (parasternal) portion of internal intercostals paradoxically aids inspiration."},{"id": 1181,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The intercostal nerve is the anterior ramus of which spinal nerve?","options": [{"key": "A","text": "Ventral root only"},{"key": "B","text": "Anterior ramus of thoracic spinal nerve (T1-T11)"},{"key": "C","text": "Posterior ramus of thoracic spinal nerve"},{"key": "D","text": "Mixed spinal nerve"}],"correct": "B","explanation": "Intercostal nerves are the anterior (ventral) rami of thoracic spinal nerves T1-T11."},{"id": 1182,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The subcostal nerve is the anterior ramus of:","options": [{"key": "A","text": "T11"},{"key": "B","text": "T12"},{"key": "C","text": "T10"},{"key": "D","text": "L1"}],"correct": "B","explanation": "The subcostal nerve is the anterior ramus of T12, running below rib 12."},{"id": 1183,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The intercostal nerve gives a lateral cutaneous branch at:","options": [{"key": "A","text": "Angle of the rib"},{"key": "B","text": "Anterior axillary line"},{"key": "C","text": "Posterior axillary line"},{"key": "D","text": "Midaxillary line"}],"correct": "D","explanation": "The lateral cutaneous branch pierces the intercostal muscles at the midaxillary line."},{"id": 1184,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The first intercostal nerve differs from others because it:","options": [{"key": "A","text": "Has no lateral cutaneous branch and most fibers join brachial plexus"},{"key": "B","text": "Is purely motor"},{"key": "C","text": "Has no anterior cutaneous branch"},{"key": "D","text": "Supplies two intercostal spaces"}],"correct": "A","explanation": "The 1st intercostal nerve mostly joins the brachial plexus; it has no significant lateral cutaneous branch."},{"id": 1185,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The intercostal arteries arise primarily from:","options": [{"key": "A","text": "Internal thoracic and aorta (posterior intercostal)"},{"key": "B","text": "Axillary artery"},{"key": "C","text": "Pulmonary artery"},{"key": "D","text": "Subclavian artery only"}],"correct": "A","explanation": "Anterior intercostal arteries from internal thoracic; posterior intercostal arteries from thoracic aorta (3-11)."},{"id": 1186,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The internal thoracic (mammary) artery is a branch of:","options": [{"key": "A","text": "Brachiocephalic trunk"},{"key": "B","text": "Subclavian artery"},{"key": "C","text": "Axillary artery"},{"key": "D","text": "Aorta"}],"correct": "B","explanation": "Internal thoracic artery arises from the first part of the subclavian artery."},{"id": 1187,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "Intercostal nerve block is performed:","options": [{"key": "A","text": "All of the above"},{"key": "B","text": "At the rib angle posteriorly"},{"key": "C","text": "At midaxillary line"},{"key": "D","text": "At costal margin anteriorly"}],"correct": "B","explanation": "Intercostal nerve block is most effectively performed at the angle of the rib (posterior) where the nerve is most accessible."},{"id": 1188,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "Intercostal drain (chest tube) is inserted in which intercostal space typically for pneumothorax?","options": [{"key": "A","text": "5th ICS, anterior axillary line (safe triangle)"},{"key": "B","text": "7th ICS, posterior axillary line"},{"key": "C","text": "1st ICS"},{"key": "D","text": "2nd ICS, midclavicular line"}],"correct": "A","explanation": "For pneumothorax, chest drain is placed in the 'safe triangle' — 5th ICS, anterior axillary line."},{"id": 1189,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The 'safe triangle' for chest tube insertion is bounded by:","options": [{"key": "A","text": "Pectoralis major, latissimus dorsi, axillary apex"},{"key": "B","text": "Midaxillary line only"},{"key": "C","text": "Anterior border latissimus dorsi, lateral border pectoralis major, above nipple line"},{"key": "D","text": "Rib 5 only"}],"correct": "C","explanation": "Safe triangle = anterior border of latissimus dorsi, lateral pectoralis major, above rib 5 (nipple level)."},{"id": 1190,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "During thoracocentesis, the needle should be inserted:","options": [{"key": "A","text": "Above the upper border of the rib"},{"key": "B","text": "Just above the lower rib (superior to lower rib of space)"},{"key": "C","text": "In the middle of the intercostal space"},{"key": "D","text": "Below the upper rib"}],"correct": "B","explanation": "Needle is inserted above the upper border of the LOWER rib to avoid VAN (vein, artery, nerve) in the costal groove."},{"id": 1191,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The diaphragm is the primary muscle of:","options": [{"key": "A","text": "Both inspiration and expiration equally"},{"key": "B","text": "Stabilization only"},{"key": "C","text": "Expiration"},{"key": "D","text": "Inspiration"}],"correct": "D","explanation": "The diaphragm is the primary muscle of inspiration, responsible for ~75% of tidal breathing."},{"id": 1192,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The diaphragm descends from which embryological structure?","options": [{"key": "A","text": "Septum transversum, pleuroperitoneal folds, mesentery of esophagus, body wall"},{"key": "B","text": "Neural crest only"},{"key": "C","text": "Splanchnic mesoderm only"},{"key": "D","text": "Somitic myoblasts alone"}],"correct": "A","explanation": "Diaphragm develops from: septum transversum (central tendon), pleuroperitoneal folds, esophageal mesentery, and body wall."},{"id": 1193,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The central tendon of the diaphragm is derived from:","options": [{"key": "A","text": "Pleuroperitoneal folds"},{"key": "B","text": "Septum transversum"},{"key": "C","text": "Somites"},{"key": "D","text": "Neural crest"}],"correct": "B","explanation": "The central tendon (trefoil-shaped) is derived from the septum transversum."},{"id": 1194,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The crura of the diaphragm arise from:","options": [{"key": "A","text": "Sacrum"},{"key": "B","text": "Lower ribs"},{"key": "C","text": "Iliac crest"},{"key": "D","text": "Lumbar vertebrae (L1-L3 on right, L1-L2 on left)"}],"correct": "D","explanation": "Right crus arises from L1-L3; left crus from L1-L2 lumbar vertebral bodies and intervertebral discs."},{"id": 1195,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The median arcuate ligament of the diaphragm is formed by:","options": [{"key": "A","text": "Fusion of the two crura over the aorta"},{"key": "B","text": "Lateral lumbocostal arch"},{"key": "C","text": "Rib attachment"},{"key": "D","text": "Medial lumbocostal arch"}],"correct": "A","explanation": "Median arcuate ligament = fibrous arch formed by the two crura crossing over the aorta."},{"id": 1196,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The medial arcuate ligament of the diaphragm arches over:","options": [{"key": "A","text": "Psoas major muscle"},{"key": "B","text": "Aorta"},{"key": "C","text": "Kidney"},{"key": "D","text": "Quadratus lumborum"}],"correct": "A","explanation": "Medial arcuate ligament arches over the psoas major muscle (from vertebral body to transverse process)."},{"id": 1197,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The lateral arcuate ligament of the diaphragm arches over:","options": [{"key": "A","text": "Quadratus lumborum muscle"},{"key": "B","text": "Aorta"},{"key": "C","text": "Kidney"},{"key": "D","text": "Psoas major"}],"correct": "A","explanation": "Lateral arcuate ligament arches over the quadratus lumborum (from transverse process to rib 12)."},{"id": 1198,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The aortic opening (hiatus) in the diaphragm is at level:","options": [{"key": "A","text": "T8"},{"key": "B","text": "T10"},{"key": "C","text": "L1"},{"key": "D","text": "T12"}],"correct": "D","explanation": "The aortic hiatus is at T12, transmitting the aorta, thoracic duct, and azygos vein."},{"id": 1199,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The oesophageal opening in the diaphragm is at level:","options": [{"key": "A","text": "T10"},{"key": "B","text": "L1"},{"key": "C","text": "T8"},{"key": "D","text": "T12"}],"correct": "A","explanation": "The oesophageal hiatus is at T10, transmitting the oesophagus and vagal trunks."},{"id": 1200,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The caval opening (for inferior vena cava) in the diaphragm is at level:","options": [{"key": "A","text": "T6"},{"key": "B","text": "T10"},{"key": "C","text": "T12"},{"key": "D","text": "T8"}],"correct": "D","explanation": "The caval opening is at T8 in the central tendon, transmitting the IVC and right phrenic nerve."},{"id": 1201,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "Which structure passes through the aortic hiatus of diaphragm?","options": [{"key": "A","text": "IVC, right phrenic nerve"},{"key": "B","text": "Aorta, thoracic duct, azygos vein"},{"key": "C","text": "Oesophagus, vagus"},{"key": "D","text": "Sympathetic chain"}],"correct": "B","explanation": "Aortic hiatus (T12) transmits: descending aorta, thoracic duct, and azygos vein."},{"id": 1202,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which structure passes through the oesophageal hiatus?","options": [{"key": "A","text": "IVC and phrenic nerve"},{"key": "B","text": "Aorta and thoracic duct"},{"key": "C","text": "Oesophagus and vagal trunks (anterior and posterior)"},{"key": "D","text": "Sympathetic chain only"}],"correct": "C","explanation": "Oesophageal hiatus (T10) transmits: oesophagus and vagal trunks (anterior=left vagus, posterior=right vagus)."},{"id": 1203,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The right phrenic nerve pierces the diaphragm through:","options": [{"key": "A","text": "Caval opening (central tendon)"},{"key": "B","text": "Separate muscular opening"},{"key": "C","text": "Oesophageal hiatus"},{"key": "D","text": "Aortic hiatus"}],"correct": "A","explanation": "Right phrenic nerve passes through the caval opening (T8) along with the IVC."},{"id": 1204,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The left phrenic nerve pierces the diaphragm:","options": [{"key": "A","text": "Through caval opening"},{"key": "B","text": "Through the muscle itself (separate opening left of centre)"},{"key": "C","text": "Through oesophageal hiatus"},{"key": "D","text": "Through aortic hiatus"}],"correct": "B","explanation": "Left phrenic nerve pierces the muscular part of the diaphragm separately, left of centre."},{"id": 1205,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The sympathetic chain passes behind the diaphragm under:","options": [{"key": "A","text": "Directly through the crus"},{"key": "B","text": "Medial arcuate ligament"},{"key": "C","text": "Lateral arcuate ligament"},{"key": "D","text": "Median arcuate ligament"}],"correct": "B","explanation": "Sympathetic trunks pass deep to the medial arcuate ligament on each side."},{"id": 1206,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The splanchnic nerves pierce the diaphragm:","options": [{"key": "A","text": "Lateral arcuate ligament"},{"key": "B","text": "Through aortic hiatus"},{"key": "C","text": "Medial arcuate ligament"},{"key": "D","text": "Through the crura"}],"correct": "D","explanation": "Splanchnic nerves (greater, lesser, least) pierce the crura of the diaphragm to reach the abdomen."},{"id": 1207,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The motor nerve supply to the diaphragm is:","options": [{"key": "A","text": "Phrenic nerve (C3, C4, C5)"},{"key": "B","text": "Vagus nerve"},{"key": "C","text": "Intercostal nerves only"},{"key": "D","text": "Thoracic sympathetic"}],"correct": "A","explanation": "Phrenic nerve (C3, C4, C5) provides ENTIRE motor supply to diaphragm. Mnemonic: C3,4,5 keeps you alive."},{"id": 1208,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The sensory supply to the central part of the diaphragm is by:","options": [{"key": "A","text": "Phrenic nerve (C3-C5)"},{"key": "B","text": "Intercostal nerves"},{"key": "C","text": "Vagus nerve"},{"key": "D","text": "Subcostal nerve"}],"correct": "A","explanation": "The phrenic nerve (C3-C5) provides sensory supply to the central diaphragm and pericardium."},{"id": 1209,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The peripheral diaphragm receives sensory supply from:","options": [{"key": "A","text": "Subcostal nerve only"},{"key": "B","text": "Lower 6 intercostal nerves (T7-T12)"},{"key": "C","text": "Vagus nerve"},{"key": "D","text": "Phrenic nerve"}],"correct": "B","explanation": "Peripheral diaphragm (musculotendinous rim) is supplied sensory by lower 6 intercostal nerves."},{"id": 1210,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Referred pain from diaphragmatic irritation (e.g., subphrenic abscess) is felt at:","options": [{"key": "A","text": "Epigastrium"},{"key": "B","text": "Groin"},{"key": "C","text": "Shoulder tip (C3-C4 dermatome)"},{"key": "D","text": "Lumbar region"}],"correct": "C","explanation": "Diaphragmatic irritation refers pain to the shoulder tip via the phrenic nerve (C3-C4)."},{"id": 1211,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The diaphragm descends during inspiration because:","options": [{"key": "A","text": "Rib cage contracts"},{"key": "B","text": "Abdominal muscles contract"},{"key": "C","text": "Central tendon is pulled inferiorly by muscular contraction"},{"key": "D","text": "Intercostals pull it down"}],"correct": "C","explanation": "Diaphragm contraction causes the dome to descend (central tendon moves caudally), increasing vertical thoracic diameter."},{"id": 1212,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "During quiet breathing, the diaphragm descends approximately:","options": [{"key": "A","text": "1 cm"},{"key": "B","text": "1.5 cm"},{"key": "C","text": "8-10 cm"},{"key": "D","text": "3-5 cm"}],"correct": "B","explanation": "Diaphragm excursion during quiet breathing is about 1.5 cm; deep breathing up to 7-10 cm."},{"id": 1213,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "The right dome of diaphragm is higher than left because:","options": [{"key": "A","text": "Stomach pushes left dome down"},{"key": "B","text": "Liver pushes it up from below"},{"key": "C","text": "Heart pushes it up"},{"key": "D","text": "Spleen on right"}],"correct": "B","explanation": "The liver (right lobe) supports and elevates the right dome; stomach gas depresses the left dome."},{"id": 1214,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The right dome of the diaphragm is normally at the level of:","options": [{"key": "A","text": "7th rib"},{"key": "B","text": "4th rib"},{"key": "C","text": "6th rib"},{"key": "D","text": "5th rib (mid-clavicular line)"}],"correct": "D","explanation": "Right dome of the diaphragm is at the 5th rib in the mid-clavicular line (at end-expiration)."},{"id": 1215,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "A congenital diaphragmatic hernia (Bochdalek hernia) occurs through:","options": [{"key": "A","text": "Pleuroperitoneal canal (posterolateral defect)"},{"key": "B","text": "Oesophageal hiatus"},{"key": "C","text": "Central tendon"},{"key": "D","text": "Foramen of Morgagni"}],"correct": "A","explanation": "Bochdalek hernia is a posterolateral defect (left > right) due to failure of closure of pleuroperitoneal canal."},{"id": 1216,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Foramen of Morgagni hernia is located:","options": [{"key": "A","text": "Posteriorly"},{"key": "B","text": "Anteriorly (parasternal, between sternal and costal origins)"},{"key": "C","text": "Posterolateral"},{"key": "D","text": "Centrally"}],"correct": "B","explanation": "Morgagni hernia is an anterior parasternal defect, between the sternal and costal diaphragm origins."},{"id": 1217,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Sliding hiatus hernia is most common type and involves:","options": [{"key": "A","text": "Entire stomach in thorax"},{"key": "B","text": "Gastro-oesophageal junction sliding into thorax"},{"key": "C","text": "Stomach fundus herniating alongside oesophagus"},{"key": "D","text": "Only oesophagus herniation"}],"correct": "B","explanation": "Sliding (Type I) hiatus hernia = GE junction and cardia of stomach slide into thorax through oesophageal hiatus."},{"id": 1218,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Para-oesophageal (rolling) hiatus hernia involves:","options": [{"key": "A","text": "Stomach fundus herniating alongside oesophagus (GE junction stays in abdomen)"},{"key": "B","text": "Entire bowel herniation"},{"key": "C","text": "Diaphragm paralysis"},{"key": "D","text": "GE junction herniation"}],"correct": "A","explanation": "Para-oesophageal hernia: fundus of stomach rolls through hiatus while GE junction remains below diaphragm."},{"id": 1219,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The costodiaphragmatic recess is:","options": [{"key": "A","text": "Behind the sternum"},{"key": "B","text": "The lowest pleural recess between costal and diaphragmatic pleura"},{"key": "C","text": "Between two lobes of lung"},{"key": "D","text": "The space between lung and pericardium"}],"correct": "B","explanation": "Costodiaphragmatic recess is the most dependent pleural recess; fluid collects here first."},{"id": 1220,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "During maximal inspiration, the diaphragm can descend up to:","options": [{"key": "A","text": "7-10 cm"},{"key": "B","text": "5 cm"},{"key": "C","text": "3 cm"},{"key": "D","text": "15 cm"}],"correct": "A","explanation": "In deep/maximal inspiration, diaphragm can descend 7-10 cm below its resting position."},{"id": 1221,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Boyle's law as applied to breathing states:","options": [{"key": "A","text": "Pressure equals volume"},{"key": "B","text": "Temperature determines lung volume"},{"key": "C","text": "At constant temperature, pressure and volume are inversely proportional"},{"key": "D","text": "Pressure is proportional to volume"}],"correct": "C","explanation": "Boyle's law: P∝1/V (constant temp); as thoracic volume increases during inspiration, pressure drops below atmospheric."},{"id": 1222,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Tidal volume in a normal adult at rest is approximately:","options": [{"key": "A","text": "200 mL"},{"key": "B","text": "1200 mL"},{"key": "C","text": "2500 mL"},{"key": "D","text": "500 mL"}],"correct": "D","explanation": "Normal tidal volume (TV) is approximately 500 mL (0.5 L) during quiet breathing."},{"id": 1223,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Functional residual capacity (FRC) is:","options": [{"key": "A","text": "VC + RV"},{"key": "B","text": "TLC - TV"},{"key": "C","text": "ERV + RV"},{"key": "D","text": "TV + IRV"}],"correct": "C","explanation": "FRC = Expiratory Reserve Volume + Residual Volume; the volume remaining after normal quiet expiration."},{"id": 1224,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Quiet expiration is:","options": [{"key": "A","text": "Driven by intercostal muscles"},{"key": "B","text": "Active process requiring muscular contraction"},{"key": "C","text": "Driven by abdominal muscles"},{"key": "D","text": "Passive process (elastic recoil of lungs and chest wall)"}],"correct": "D","explanation": "Quiet expiration is passive, driven by elastic recoil of lungs and chest wall (no muscular effort needed)."},{"id": 1225,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Accessory muscles of inspiration include:","options": [{"key": "A","text": "Abdominal muscles and internal intercostals"},{"key": "B","text": "Sternocleidomastoid, scalenes, pectoralis minor"},{"key": "C","text": "Erector spinae only"},{"key": "D","text": "Latissimus dorsi and gluteus maximus"}],"correct": "B","explanation": "Accessory inspiratory muscles: SCM, scalenes, pectoralis minor, serratus anterior activate during forced/labored breathing."},{"id": 1226,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Primary muscles of forced expiration are:","options": [{"key": "A","text": "Abdominal muscles (rectus, obliques, transversus) and internal intercostals"},{"key": "B","text": "Scalenes and SCM"},{"key": "C","text": "External intercostals and diaphragm"},{"key": "D","text": "Pectoralis major"}],"correct": "A","explanation": "Forced expiration uses abdominal muscles (to push diaphragm up) and internal intercostal muscles."},{"id": 1227,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Paradoxical breathing (see-saw respiration) is characterized by:","options": [{"key": "A","text": "Increased tidal volume"},{"key": "B","text": "Chest falls and abdomen rises during inspiration (diaphragm paralysis)"},{"key": "C","text": "Chest and abdomen both rise together"},{"key": "D","text": "Abdomen only moves"}],"correct": "B","explanation": "Paradoxical breathing: diaphragm paralysis causes abdomen to fall and chest to rise during inspiration abnormally."},{"id": 1228,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The diaphragm performs which action on the abdominal compartment during inspiration?","options": [{"key": "A","text": "No effect"},{"key": "B","text": "Decreases intra-abdominal pressure"},{"key": "C","text": "Lateral expansion of abdomen"},{"key": "D","text": "Increases intra-abdominal pressure (viscera compressed)"}],"correct": "D","explanation": "Diaphragm descent during inspiration compresses abdominal contents, increasing intra-abdominal pressure."},{"id": 1229,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "A tension pneumothorax causes the mediastinum to shift:","options": [{"key": "A","text": "No mediastinal shift"},{"key": "B","text": "Toward the affected side"},{"key": "C","text": "Inferiorly"},{"key": "D","text": "Away from the affected side"}],"correct": "D","explanation": "Tension pneumothorax causes mediastinal shift AWAY from the affected side due to increasing pressure."},{"id": 1230,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Flail chest occurs when:","options": [{"key": "A","text": "Two or more ribs fractured in two or more places (segment loses bony continuity)"},{"key": "B","text": "Single rib fracture"},{"key": "C","text": "Sternum fractures only"},{"key": "D","text": "Diaphragm rupture"}],"correct": "A","explanation": "Flail chest = ≥3 consecutive ribs fractured in ≥2 places, creating a free-floating segment with paradoxical movement."},{"id": 1231,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The most common site for rib fractures is:","options": [{"key": "A","text": "Posterior (near costovertebral joint)"},{"key": "B","text": "Anterior (near sternum)"},{"key": "C","text": "At the neck of rib"},{"key": "D","text": "Lateral (near angle of rib)"}],"correct": "D","explanation": "Ribs fracture most commonly at the angle (lateral), the weakest and most prominent part."},{"id": 1232,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "A pleural effusion of more than how much fluid is detectable on a plain chest X-ray?","options": [{"key": "A","text": "100 mL"},{"key": "B","text": "200-300 mL"},{"key": "C","text": "500 mL"},{"key": "D","text": "50 mL"}],"correct": "B","explanation": "Approximately 200-300 mL of pleural fluid is needed before it becomes visible on an erect PA chest X-ray."},{"id": 1233,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The angle of Louis is used clinically to:","options": [{"key": "A","text": "Locate rib 1 only"},{"key": "B","text": "Measure lordosis"},{"key": "C","text": "None of the above"},{"key": "D","text": "Locate rib 2, carina, aortic arch, T4-T5 level"}],"correct": "D","explanation": "Sternal angle of Louis is an important clinical landmark for locating rib 2, carina, aortic arch, and T4-T5 disc."},{"id": 1234,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Diaphragmatic palsy (hemidiaphragm paralysis) is detected on X-ray as:","options": [{"key": "A","text": "Mediastinal shift away from lesion"},{"key": "B","text": "Elevated ipsilateral hemidiaphragm"},{"key": "C","text": "Rib notching"},{"key": "D","text": "Lowered ipsilateral hemidiaphragm"}],"correct": "B","explanation": "Paralyzed hemidiaphragm appears elevated on chest X-ray and moves paradoxically on fluoroscopy (sniff test)."},{"id": 1235,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "Rib notching on chest X-ray (inferior rib margins) is a sign of:","options": [{"key": "A","text": "Ankylosing spondylitis"},{"key": "B","text": "Rickets"},{"key": "C","text": "Osteoporosis"},{"key": "D","text": "Coarctation of aorta"}],"correct": "D","explanation": "Rib notching (inferior rib cortical erosions) is caused by dilated intercostal collateral vessels in coarctation of aorta."},{"id": 1236,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "Cervical rib can cause thoracic outlet syndrome compressing:","options": [{"key": "A","text": "Radial nerve only"},{"key": "B","text": "Femoral nerve and artery"},{"key": "C","text": "Phrenic nerve"},{"key": "D","text": "Brachial plexus (lower trunk) and subclavian artery"}],"correct": "D","explanation": "Cervical rib compresses the lower trunk of brachial plexus (C8-T1) and/or subclavian artery."},{"id": 1237,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The 'bucket handle' tear in meniscus is named after:","options": [{"key": "A","text": "Rib movement pattern in breathing"},{"key": "B","text": "Shape of tear resembling rib bucket-handle motion"},{"key": "C","text": "Both"},{"key": "D","text": "Neither"}],"correct": "A","explanation": "The bucket handle meniscal tear is named after the rib bucket-handle movement in respiration."},{"id": 1238,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tietze syndrome is:","options": [{"key": "A","text": "Painful swelling of costochondral junctions (usually 2nd-3rd rib)"},{"key": "B","text": "Rib osteomyelitis"},{"key": "C","text": "Rib stress fracture"},{"key": "D","text": "Costochondral cartilage inflammation without swelling"}],"correct": "A","explanation": "Tietze syndrome = painful non-suppurative swelling of one or more costochondral junctions (usually 2nd-3rd)."},{"id": 1239,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Costochondritis differs from Tietze syndrome because:","options": [{"key": "A","text": "It involves multiple rib joints with tenderness but no swelling"},{"key": "B","text": "It is more painful"},{"key": "C","text": "It is infectious"},{"key": "D","text": "It lacks swelling/tenderness at a specific cartilage"}],"correct": "A","explanation": "Costochondritis = multiple costochondral junction pain/tenderness WITHOUT visible/palpable swelling (unlike Tietze)."},{"id": 1240,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Ribs ossify from:","options": [{"key": "A","text": "Membranous ossification"},{"key": "B","text": "Three primary centers"},{"key": "C","text": "One primary and two secondary centers"},{"key": "D","text": "One primary centre in the angle"}],"correct": "C","explanation": "Ribs ossify from one primary center (body) and secondary centers at head and tubercle."},{"id": 1241,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Failure of fusion of sternal bars results in:","options": [{"key": "A","text": "Sternal foramen only"},{"key": "B","text": "Pectus carinatum"},{"key": "C","text": "Sternal cleft (bifid sternum)"},{"key": "D","text": "Pectus excavatum"}],"correct": "C","explanation": "Failure of fusion of lateral sternal bars results in sternal cleft (bifid sternum)."},{"id": 1242,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Sternal foramen is:","options": [{"key": "A","text": "A common normal variant (foramina in body of sternum)"},{"key": "B","text": "Related to malignancy"},{"key": "C","text": "Always pathological"},{"key": "D","text": "Due to trauma always"}],"correct": "A","explanation": "Sternal foramen is a common normal variant (benign) occurring in ~6% of people; important to recognize on imaging."},{"id": 1243,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Serratus anterior originates from:","options": [{"key": "A","text": "Sternum"},{"key": "B","text": "Outer surfaces of upper 8-9 ribs"},{"key": "C","text": "Scapula"},{"key": "D","text": "Clavicle"}],"correct": "B","explanation": "Serratus anterior arises from the outer surfaces of the lateral aspects of the upper 8-9 ribs."},{"id": 1244,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Pectoralis minor originates from:","options": [{"key": "A","text": "Coracoid process"},{"key": "B","text": "3rd-5th ribs (outer surface)"},{"key": "C","text": "Manubrium"},{"key": "D","text": "Clavicle"}],"correct": "B","explanation": "Pectoralis minor arises from the 3rd, 4th, and 5th ribs and inserts into the coracoid process."},{"id": 1245,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The subclavius muscle is attached to:","options": [{"key": "A","text": "Rib 2"},{"key": "B","text": "Rib 3"},{"key": "C","text": "Rib 1 (junction of rib and costal cartilage)"},{"key": "D","text": "Clavicle and sternum"}],"correct": "C","explanation": "Subclavius arises from the junction of rib 1 and its costal cartilage and inserts into the clavicle."},{"id": 1246,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The levatores costarum muscles elevate the ribs and are innervated by:","options": [{"key": "A","text": "Vagus nerve"},{"key": "B","text": "Intercostal nerves"},{"key": "C","text": "Phrenic nerve"},{"key": "D","text": "Posterior rami of thoracic spinal nerves"}],"correct": "D","explanation": "Levatores costarum (short and long) are innervated by the posterior (dorsal) rami of thoracic spinal nerves."},{"id": 1247,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "The sternocostal joints (between costal cartilages and sternum) are classified as:","options": [{"key": "A","text": "All fibrous"},{"key": "B","text": "Cartilaginous (synchondrosis) for rib 1; synovial for 2-7"},{"key": "C","text": "Synovial only"},{"key": "D","text": "Fibrous"}],"correct": "B","explanation": "1st sternocostal joint is a primary cartilaginous joint (synchondrosis); 2nd-7th are synovial plane joints."},{"id": 1248,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The internal thoracic artery terminates by dividing into:","options": [{"key": "A","text": "Phrenic arteries"},{"key": "B","text": "Musculophrenic and superior epigastric arteries"},{"key": "C","text": "Lateral thoracic artery"},{"key": "D","text": "Anterior intercostal arteries"}],"correct": "B","explanation": "Internal thoracic artery divides at 6th intercostal space into musculophrenic and superior epigastric arteries."},{"id": 1249,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The azygos vein drains into:","options": [{"key": "A","text": "SVC at T4 level"},{"key": "B","text": "Portal vein"},{"key": "C","text": "IVC"},{"key": "D","text": "Brachiocephalic vein"}],"correct": "A","explanation": "Azygos vein arches over the root of right lung and drains into the SVC at the level of T4."},{"id": 1250,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Easy","question": "Winged scapula results from injury to which nerve that runs on the thoracic wall?","options": [{"key": "A","text": "Long thoracic nerve (of Bell) — C5, C6, C7"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Suprascapular nerve"},{"key": "D","text": "Thoracodorsal nerve"}],"correct": "A","explanation": "Long thoracic nerve (C5, C6, C7) runs on the lateral thoracic wall supplying serratus anterior; injury causes winged scapula."},{"id": 1251,"subject": "Anatomy","topic": "Thorax","difficulty": "Easy","question": "During expiration, the diaphragm:","options": [{"key": "A","text": "Descends more"},{"key": "B","text": "Remains stationary"},{"key": "C","text": "Relaxes and ascends"},{"key": "D","text": "Contracts further"}],"correct": "C","explanation": "During expiration, the diaphragm relaxes and passively ascends due to elastic recoil of the lungs."},{"id": 1252,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The phrenic nerve arises from which cervical nerve roots?","options": [{"key": "A","text": "C3, C4, C5"},{"key": "B","text": "C5, C6, C7"},{"key": "C","text": "C4, C5, C6"},{"key": "D","text": "C2, C3, C4"}],"correct": "A","explanation": "Phrenic nerve = C3, C4, C5 (mainly C4). Mnemonic: C3,4,5 keeps the diaphragm alive."},{"id": 1253,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "The thoracic duct enters the thorax through:","options": [{"key": "A","text": "Caval opening"},{"key": "B","text": "Separate opening between crura"},{"key": "C","text": "Oesophageal hiatus"},{"key": "D","text": "Aortic hiatus"}],"correct": "D","explanation": "The thoracic duct enters the thorax through the aortic hiatus (T12) alongside the aorta."},{"id": 1254,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The costo-diaphragmatic angle on chest X-ray is obliterated by:","options": [{"key": "A","text": "Pleural effusion"},{"key": "B","text": "Normal in most"},{"key": "C","text": "Pneumothorax"},{"key": "D","text": "Consolidation only"}],"correct": "A","explanation": "Pleural effusion fills the costo-diaphragmatic recess, obliterating the costophrenic angle on X-ray."},{"id": 1255,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which bone forms the forehead?","options": [{"key": "A","text": "Frontal bone"},{"key": "B","text": "Temporal bone"},{"key": "C","text": "Occipital bone"},{"key": "D","text": "Parietal bone"}],"correct": "A","explanation": "Frontal bone forms the forehead and roof of orbits."},{"id": 1256,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "How many bones form the neurocranium?","options": [{"key": "A","text": "8"},{"key": "B","text": "14"},{"key": "C","text": "6"},{"key": "D","text": "22"}],"correct": "A","explanation": "The neurocranium (cranial vault) is formed by 8 bones."},{"id": 1257,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which suture lies between the two parietal bones?","options": [{"key": "A","text": "Coronal suture"},{"key": "B","text": "Squamous suture"},{"key": "C","text": "Sagittal suture"},{"key": "D","text": "Lambdoid suture"}],"correct": "C","explanation": "Sagittal suture joins the two parietal bones in midline."},{"id": 1258,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The coronal suture lies between which bones?","options": [{"key": "A","text": "Temporal and parietal"},{"key": "B","text": "Frontal and parietal"},{"key": "C","text": "Frontal and temporal"},{"key": "D","text": "Parietal and occipital"}],"correct": "B","explanation": "Coronal suture separates frontal bone from the two parietal bones."},{"id": 1259,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Lambdoid suture is found between which bones?","options": [{"key": "A","text": "Parietal and occipital"},{"key": "B","text": "Frontal and parietal"},{"key": "C","text": "Parietal and temporal"},{"key": "D","text": "Temporal and occipital"}],"correct": "A","explanation": "Lambdoid suture lies between parietal bones and occipital bone."},{"id": 1260,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Pterion is a clinically important junction of how many bones?","options": [{"key": "A","text": "4"},{"key": "B","text": "3"},{"key": "C","text": "5"},{"key": "D","text": "2"}],"correct": "A","explanation": "Pterion is the meeting point of frontal, parietal, temporal and sphenoid bones (4 bones)."},{"id": 1261,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which artery runs deep to the pterion, making it clinically significant?","options": [{"key": "A","text": "Middle meningeal artery"},{"key": "B","text": "Maxillary artery"},{"key": "C","text": "Superficial temporal artery"},{"key": "D","text": "Occipital artery"}],"correct": "A","explanation": "Middle meningeal artery runs beneath the pterion and is vulnerable to injury here."},{"id": 1262,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The foramen magnum is located in which bone?","options": [{"key": "A","text": "Ethmoid"},{"key": "B","text": "Sphenoid"},{"key": "C","text": "Temporal"},{"key": "D","text": "Occipital"}],"correct": "D","explanation": "Foramen magnum is a large opening in the occipital bone transmitting the spinal cord."},{"id": 1263,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which structure passes through the foramen magnum?","options": [{"key": "A","text": "Facial nerve"},{"key": "B","text": "Vagus nerve"},{"key": "C","text": "Spinal cord"},{"key": "D","text": "Glossopharyngeal nerve"}],"correct": "C","explanation": "The spinal cord, vertebral arteries and spinal roots of accessory nerve pass through foramen magnum."},{"id": 1264,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The mastoid process is part of which bone?","options": [{"key": "A","text": "Sphenoid bone"},{"key": "B","text": "Temporal bone"},{"key": "C","text": "Occipital bone"},{"key": "D","text": "Frontal bone"}],"correct": "B","explanation": "Mastoid process is a projection of the temporal bone, site of SCM insertion."},{"id": 1265,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which bone houses the organs of hearing and balance?","options": [{"key": "A","text": "Occipital"},{"key": "B","text": "Ethmoid"},{"key": "C","text": "Sphenoid"},{"key": "D","text": "Temporal"}],"correct": "D","explanation": "Temporal bone contains the middle and inner ear structures."},{"id": 1266,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The external occipital protuberance is a landmark on which bone?","options": [{"key": "A","text": "Parietal"},{"key": "B","text": "Frontal"},{"key": "C","text": "Temporal"},{"key": "D","text": "Occipital"}],"correct": "D","explanation": "It is a midline bony prominence on the squamous part of occipital bone."},{"id": 1267,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Superior nuchal line is the attachment site for which muscle?","options": [{"key": "A","text": "Splenius capitis"},{"key": "B","text": "Trapezius"},{"key": "C","text": "Longus capitis"},{"key": "D","text": "Levator scapulae"}],"correct": "B","explanation": "Trapezius attaches along the superior nuchal line of the occipital bone."},{"id": 1268,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which cranial fossa contains the cerebellum?","options": [{"key": "A","text": "None of the above"},{"key": "B","text": "Anterior cranial fossa"},{"key": "C","text": "Posterior cranial fossa"},{"key": "D","text": "Middle cranial fossa"}],"correct": "C","explanation": "Posterior cranial fossa houses the cerebellum, pons and medulla."},{"id": 1269,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The styloid process serves as attachment for how many muscles?","options": [{"key": "A","text": "2"},{"key": "B","text": "4"},{"key": "C","text": "3"},{"key": "D","text": "5"}],"correct": "B","explanation": "Three muscles attach: stylohyoid, styloglossus and stylopharyngeus."},{"id": 1270,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Easy","question": "Which bone forms the chin (mandible) joint with the skull called?","options": [{"key": "A","text": "Temporomandibular joint"},{"key": "B","text": "Zygomatic joint"},{"key": "C","text": "Atlanto-occipital joint"},{"key": "D","text": "Sternoclavicular joint"}],"correct": "A","explanation": "TMJ is formed between the mandibular condyle and temporal bone."},{"id": 1271,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The zygomatic arch is formed by processes of which two bones?","options": [{"key": "A","text": "Temporal and zygomatic"},{"key": "B","text": "Frontal and maxilla"},{"key": "C","text": "Parietal and sphenoid"},{"key": "D","text": "Maxilla and palatine"}],"correct": "A","explanation": "Zygomatic arch is formed by the temporal process of zygomatic bone and zygomatic process of temporal bone."},{"id": 1272,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Easy","question": "Which is the only movable bone of the skull?","options": [{"key": "A","text": "Vomer"},{"key": "B","text": "Zygomatic bone"},{"key": "C","text": "Mandible"},{"key": "D","text": "Maxilla"}],"correct": "C","explanation": "Mandible articulates at the TMJ and is the only freely movable skull bone."},{"id": 1273,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "The foramen ovale transmits which cranial nerve?","options": [{"key": "A","text": "Mandibular nerve (V3)"},{"key": "B","text": "Maxillary nerve (V2)"},{"key": "C","text": "Facial nerve (VII)"},{"key": "D","text": "Ophthalmic nerve (V1)"}],"correct": "A","explanation": "Foramen ovale in the sphenoid bone transmits the mandibular division of trigeminal nerve."},{"id": 1274,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Glabella is a landmark located on which bone?","options": [{"key": "A","text": "Frontal bone"},{"key": "B","text": "Ethmoid bone"},{"key": "C","text": "Maxilla"},{"key": "D","text": "Nasal bone"}],"correct": "A","explanation": "Glabella is the smooth area between the eyebrows on the frontal bone."},{"id": 1275,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Inion refers to which bony landmark?","options": [{"key": "A","text": "Glabella"},{"key": "B","text": "Mastoid process"},{"key": "C","text": "External occipital protuberance"},{"key": "D","text": "Bregma"}],"correct": "C","explanation": "Inion is the anatomical name for the external occipital protuberance."},{"id": 1276,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Bregma is the meeting point of which sutures?","options": [{"key": "A","text": "Coronal and sagittal"},{"key": "B","text": "Coronal and squamous"},{"key": "C","text": "Lambdoid and squamous"},{"key": "D","text": "Sagittal and lambdoid"}],"correct": "A","explanation": "Bregma is where coronal and sagittal sutures intersect."},{"id": 1277,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Asterion is the junction of which sutures?","options": [{"key": "A","text": "Squamous, frontal, parietal"},{"key": "B","text": "Lambdoid, occipitomastoid, parietomastoid"},{"key": "C","text": "Coronal, sagittal, squamous"},{"key": "D","text": "Sagittal, lambdoid, coronal"}],"correct": "B","explanation": "Asterion marks the junction of lambdoid, occipitomastoid and parietomastoid sutures."},{"id": 1278,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "Which skull landmark is used to assess head posture clinically?","options": [{"key": "A","text": "Glabella"},{"key": "B","text": "Bregma"},{"key": "C","text": "Tragus of ear"},{"key": "D","text": "Inion"}],"correct": "C","explanation": "The tragus is commonly used as a bony landmark for forward head posture assessment."},{"id": 1279,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "The hyoid bone is suspended in the neck and connected to the skull by which muscle group?","options": [{"key": "A","text": "Infrahyoid muscles"},{"key": "B","text": "Suprahyoid muscles"},{"key": "C","text": "Prevertebral muscles"},{"key": "D","text": "Scalene muscles"}],"correct": "B","explanation": "Suprahyoid muscles (e.g., digastric, mylohyoid) connect the hyoid bone to the skull/mandible."},{"id": 1280,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "How many cervical vertebrae are present in the human spine?","options": [{"key": "A","text": "7"},{"key": "B","text": "6"},{"key": "C","text": "8"},{"key": "D","text": "5"}],"correct": "A","explanation": "There are 7 cervical vertebrae, C1 to C7."},{"id": 1281,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "Which cervical vertebra is known as the Atlas?","options": [{"key": "A","text": "C6"},{"key": "B","text": "C1"},{"key": "C","text": "C2"},{"key": "D","text": "C7"}],"correct": "B","explanation": "C1 is called the Atlas as it supports the skull like the mythological figure."},{"id": 1282,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "Which cervical vertebra is known as the Axis?","options": [{"key": "A","text": "C2"},{"key": "B","text": "C1"},{"key": "C","text": "C7"},{"key": "D","text": "C5"}],"correct": "A","explanation": "C2 is called the Axis due to the odontoid process (dens) around which Atlas rotates."},{"id": 1283,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "The Atlas vertebra lacks which typical vertebral feature?","options": [{"key": "A","text": "Vertebral body"},{"key": "B","text": "Articular facets"},{"key": "C","text": "Lamina"},{"key": "D","text": "Transverse process"}],"correct": "A","explanation": "Atlas has no vertebral body; it is a ring-shaped bone."},{"id": 1284,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "The odontoid process (dens) is found on which vertebra?","options": [{"key": "A","text": "C2"},{"key": "B","text": "C1"},{"key": "C","text": "C7"},{"key": "D","text": "C3"}],"correct": "A","explanation": "Dens projects upward from the body of axis (C2) and articulates with anterior arch of atlas."},{"id": 1285,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which ligament holds the dens against the anterior arch of atlas?","options": [{"key": "A","text": "Anterior longitudinal ligament"},{"key": "B","text": "Transverse ligament of atlas"},{"key": "C","text": "Ligamentum flavum"},{"key": "D","text": "Nuchal ligament"}],"correct": "B","explanation": "Transverse ligament of atlas stabilizes the dens, preventing posterior displacement."},{"id": 1286,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "C7 vertebra is also known as?","options": [{"key": "A","text": "Atlas"},{"key": "B","text": "Vertebra prominens"},{"key": "C","text": "Typical vertebra"},{"key": "D","text": "Axis"}],"correct": "B","explanation": "C7 has a long, palpable spinous process, hence called vertebra prominens."},{"id": 1287,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which joint allows the major part of cervical rotation movement?","options": [{"key": "A","text": "Atlanto-occipital joint"},{"key": "B","text": "Atlanto-axial joint"},{"key": "C","text": "C3-C4 facet joint"},{"key": "D","text": "C6-C7 facet joint"}],"correct": "B","explanation": "Atlanto-axial joint accounts for nearly 50% of total cervical rotation."},{"id": 1288,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which movement primarily occurs at the atlanto-occipital joint?","options": [{"key": "A","text": "Lateral flexion"},{"key": "B","text": "Flexion-extension (nodding)"},{"key": "C","text": "Circumduction"},{"key": "D","text": "Rotation"}],"correct": "B","explanation": "Atlanto-occipital joint allows nodding (flexion-extension), the 'yes' movement."},{"id": 1289,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Uncovertebral joints (joints of Luschka) are typically found at which spinal level?","options": [{"key": "A","text": "Lumbar spine"},{"key": "B","text": "Sacral spine"},{"key": "C","text": "Thoracic spine"},{"key": "D","text": "Cervical spine (C3-C7)"}],"correct": "D","explanation": "Uncovertebral joints are unique to the cervical spine, located at C3 to C7."},{"id": 1290,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The transverse foramen in cervical vertebrae transmits which structure?","options": [{"key": "A","text": "Vertebral artery"},{"key": "B","text": "Internal carotid artery"},{"key": "C","text": "Sympathetic chain"},{"key": "D","text": "Spinal nerve"}],"correct": "A","explanation": "Vertebral artery and accompanying veins pass through the transverse foramina of C1-C6."},{"id": 1291,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "At which cervical level does the vertebral artery typically NOT pass through the transverse foramen?","options": [{"key": "A","text": "C6"},{"key": "B","text": "C3"},{"key": "C","text": "C5"},{"key": "D","text": "C7"}],"correct": "D","explanation": "Vertebral artery usually enters the transverse foramen at C6 and ascends; C7 transverse foramen usually transmits only a small vein."},{"id": 1292,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Easy","question": "Which cervical vertebra has the largest spinous process?","options": [{"key": "A","text": "C3"},{"key": "B","text": "C1"},{"key": "C","text": "C5"},{"key": "D","text": "C7"}],"correct": "D","explanation": "C7 has the longest and most prominent spinous process among cervical vertebrae."},{"id": 1293,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The cervical lordosis curve is classified as which type of curve?","options": [{"key": "A","text": "Secondary curve"},{"key": "B","text": "Fixed curve"},{"key": "C","text": "Pathological curve"},{"key": "D","text": "Primary curve"}],"correct": "A","explanation": "Cervical lordosis is a secondary (compensatory) curve that develops after birth."},{"id": 1294,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Spondylosis commonly affects which cervical level due to high mobility?","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "C7-T1"},{"key": "C","text": "C1-C2"},{"key": "D","text": "C3-C4"}],"correct": "A","explanation": "C5-C6 is a common site of degenerative changes due to high mechanical stress."},{"id": 1295,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Which ligament limits excessive flexion of the cervical spine?","options": [{"key": "A","text": "Ligamentum nuchae"},{"key": "B","text": "Anterior longitudinal ligament"},{"key": "C","text": "Transverse ligament"},{"key": "D","text": "Posterior longitudinal ligament"}],"correct": "A","explanation": "Ligamentum nuchae, along with posterior structures, limits excessive cervical flexion."},{"id": 1296,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "The ligamentum nuchae is a continuation of which ligament in the neck region?","options": [{"key": "A","text": "Anterior longitudinal ligament"},{"key": "B","text": "Supraspinous ligament"},{"key": "C","text": "Interspinous ligament"},{"key": "D","text": "Posterior longitudinal ligament"}],"correct": "B","explanation": "Ligamentum nuchae is the cervical continuation of the supraspinous ligament."},{"id": 1297,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Cervical spinal nerves exit above their corresponding vertebra except which one?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C8"},{"key": "C","text": "C4"},{"key": "D","text": "C6"}],"correct": "B","explanation": "C8 nerve root exits below C7 vertebra since there is no C8 vertebra; all others exit above."},{"id": 1298,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Whiplash injury most commonly affects which spinal region?","options": [{"key": "A","text": "Sacral spine"},{"key": "B","text": "Lumbar spine"},{"key": "C","text": "Cervical spine"},{"key": "D","text": "Thoracic spine"}],"correct": "C","explanation": "Whiplash is a hyperextension-hyperflexion injury commonly affecting the cervical spine."},{"id": 1299,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which test assesses the integrity of the transverse ligament of atlas?","options": [{"key": "A","text": "Lhermitte's sign"},{"key": "B","text": "Sharp-Purser test"},{"key": "C","text": "Spurling's test"},{"key": "D","text": "Vertebral artery test"}],"correct": "B","explanation": "Sharp-Purser test evaluates atlanto-axial instability due to transverse ligament laxity."},{"id": 1300,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Klippel-Feil syndrome is characterized by congenital fusion of which structures?","options": [{"key": "A","text": "Thoracic ribs"},{"key": "B","text": "Lumbar vertebrae"},{"key": "C","text": "Cervical vertebrae"},{"key": "D","text": "Sacral vertebrae"}],"correct": "C","explanation": "Klippel-Feil syndrome involves congenital fusion of two or more cervical vertebrae."},{"id": 1301,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which cervical vertebrae are considered 'typical' cervical vertebrae?","options": [{"key": "A","text": "C6 and C7"},{"key": "B","text": "C1 and C7"},{"key": "C","text": "C1 and C2"},{"key": "D","text": "C3 to C6"}],"correct": "D","explanation": "C3 to C6 share common typical features unlike the atypical C1, C2, C7."},{"id": 1302,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The bifid spinous process is a characteristic feature of which vertebrae?","options": [{"key": "A","text": "Lumbar vertebrae"},{"key": "B","text": "Thoracic vertebrae"},{"key": "C","text": "Typical cervical vertebrae (C2-C6)"},{"key": "D","text": "C1 and C2"}],"correct": "C","explanation": "Most cervical vertebrae (C2-C6) have a bifid (split) spinous process tip."},{"id": 1303,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Hard","question": "Facet joint orientation in cervical spine favours which combined movement pattern?","options": [{"key": "A","text": "Pure rotation only"},{"key": "B","text": "Coupled lateral flexion with rotation to the same side"},{"key": "C","text": "Pure flexion only"},{"key": "D","text": "Coupled flexion with extension"}],"correct": "B","explanation": "Cervical facet orientation produces coupled motion: lateral flexion and rotation occur to the same side."},{"id": 1304,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Cervical spine forward head posture increases load on which structures?","options": [{"key": "A","text": "Anterior cervical muscles only"},{"key": "B","text": "Posterior cervical extensors and upper trapezius"},{"key": "C","text": "Lumbar discs only"},{"key": "D","text": "Hip flexors"}],"correct": "B","explanation": "Forward head posture increases compressive and tensile load on posterior cervical extensors and upper trapezius."},{"id": 1305,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Sternocleidomastoid (SCM) muscle has how many heads of origin?","options": [{"key": "A","text": "Two"},{"key": "B","text": "Four"},{"key": "C","text": "Three"},{"key": "D","text": "One"}],"correct": "A","explanation": "SCM has a sternal head and a clavicular head of origin."},{"id": 1306,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The sternal head of SCM originates from?","options": [{"key": "A","text": "Manubrium sterni"},{"key": "B","text": "Mastoid process"},{"key": "C","text": "Medial third of clavicle"},{"key": "D","text": "Superior nuchal line"}],"correct": "A","explanation": "Sternal head arises from the anterior surface of the manubrium sterni."},{"id": 1307,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "The clavicular head of SCM originates from?","options": [{"key": "A","text": "Acromion process"},{"key": "B","text": "Manubrium sterni"},{"key": "C","text": "Coracoid process"},{"key": "D","text": "Medial 1/3 of clavicle"}],"correct": "D","explanation": "Clavicular head arises from the medial third (superior surface) of the clavicle."},{"id": 1308,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Where does the sternocleidomastoid insert?","options": [{"key": "A","text": "Spinous process of C7"},{"key": "B","text": "Acromion process"},{"key": "C","text": "Mastoid process and lateral half of superior nuchal line"},{"key": "D","text": "Hyoid bone"}],"correct": "C","explanation": "SCM inserts onto the mastoid process and lateral half of the superior nuchal line."},{"id": 1309,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Which nerve provides motor innervation to SCM?","options": [{"key": "A","text": "Facial nerve (CN VII)"},{"key": "B","text": "Vagus nerve (CN X)"},{"key": "C","text": "Hypoglossal nerve (CN XII)"},{"key": "D","text": "Accessory nerve (CN XI)"}],"correct": "D","explanation": "Spinal accessory nerve (CN XI) supplies motor innervation to SCM."},{"id": 1310,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Sensory (proprioceptive) supply to SCM is from which spinal nerves?","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "C3-C4"},{"key": "C","text": "C2-C3"},{"key": "D","text": "C1-C2"}],"correct": "C","explanation": "Ventral rami of C2-C3 provide proprioceptive fibers to SCM."},{"id": 1311,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Unilateral contraction of SCM produces which movement?","options": [{"key": "A","text": "Ipsilateral rotation"},{"key": "B","text": "Ipsilateral lateral flexion with contralateral rotation"},{"key": "C","text": "Bilateral extension"},{"key": "D","text": "Bilateral neck flexion"}],"correct": "B","explanation": "Unilateral SCM action causes lateral flexion to same side with rotation of face to opposite side."},{"id": 1312,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Bilateral contraction of SCM produces which action?","options": [{"key": "A","text": "Lateral flexion"},{"key": "B","text": "Rotation only"},{"key": "C","text": "Neck extension"},{"key": "D","text": "Neck flexion (and assists in forced inspiration)"}],"correct": "D","explanation": "Bilateral SCM contraction flexes the cervical spine and elevates the sternum during forced inspiration."},{"id": 1313,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which condition is associated with shortening/fibrosis of SCM in infants?","options": [{"key": "A","text": "Torticollis"},{"key": "B","text": "Cervical rib"},{"key": "C","text": "Klippel-Feil syndrome"},{"key": "D","text": "Whiplash"}],"correct": "A","explanation": "Congenital muscular torticollis results from fibrosis/shortening of SCM, causing head tilt."},{"id": 1314,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In congenital torticollis due to right SCM tightness, the head typically tilts to which side?","options": [{"key": "A","text": "Right side with chin pointing left"},{"key": "B","text": "Straight with no tilt"},{"key": "C","text": "Left side with chin pointing right"},{"key": "D","text": "Right side with chin pointing right"}],"correct": "A","explanation": "Tight right SCM causes ipsilateral (right) lateral flexion with contralateral (left) rotation of chin."},{"id": 1315,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "SCM forms the boundary between which two triangles of the neck?","options": [{"key": "A","text": "Muscular and carotid triangle"},{"key": "B","text": "Occipital and supraclavicular triangle"},{"key": "C","text": "Submandibular and carotid triangle"},{"key": "D","text": "Anterior and posterior triangle"}],"correct": "D","explanation": "SCM divides the neck into anterior and posterior triangles."},{"id": 1316,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which artery lies deep to the SCM muscle?","options": [{"key": "A","text": "Vertebral artery"},{"key": "B","text": "Facial artery"},{"key": "C","text": "Common carotid artery"},{"key": "D","text": "Subclavian artery"}],"correct": "C","explanation": "Common carotid artery and internal jugular vein lie deep to SCM within the carotid sheath."},{"id": 1317,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Easy","question": "Torticollis caused by SCM is also known as?","options": [{"key": "A","text": "Whiplash neck"},{"key": "B","text": "Military neck"},{"key": "C","text": "Swan neck"},{"key": "D","text": "Wry neck"}],"correct": "D","explanation": "Torticollis due to SCM dysfunction is commonly called wry neck."},{"id": 1318,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which special test helps assess SCM tightness in infants?","options": [{"key": "A","text": "Spurling's test"},{"key": "B","text": "Adam's forward bend test"},{"key": "C","text": "Passive cervical rotation/lateral flexion ROM test"},{"key": "D","text": "Romberg's test"}],"correct": "C","explanation": "Assessing passive cervical lateral flexion and rotation ROM helps detect SCM tightness in torticollis."},{"id": 1319,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Accessory nerve (CN XI) after supplying SCM continues to supply which other muscle?","options": [{"key": "A","text": "Rhomboid major"},{"key": "B","text": "Trapezius"},{"key": "C","text": "Splenius capitis"},{"key": "D","text": "Levator scapulae"}],"correct": "B","explanation": "CN XI passes through posterior triangle to also innervate the trapezius muscle."},{"id": 1320,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "SCM acts as an accessory muscle of which physiological function?","options": [{"key": "A","text": "Swallowing"},{"key": "B","text": "Mastication"},{"key": "C","text": "Phonation"},{"key": "D","text": "Forced inspiration"}],"correct": "D","explanation": "SCM elevates the sternum and assists forced/deep inspiration when neck is fixed."},{"id": 1321,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "In which surgical/clinical procedure is the SCM commonly used as a landmark?","options": [{"key": "A","text": "Hip replacement"},{"key": "B","text": "Central venous catheterization (internal jugular vein)"},{"key": "C","text": "Knee arthroscopy"},{"key": "D","text": "Lumbar puncture"}],"correct": "B","explanation": "SCM triangle landmarks are used for internal jugular vein central line placement."},{"id": 1322,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Tightness of both SCM muscles bilaterally commonly contributes to which postural deformity?","options": [{"key": "A","text": "Forward head posture"},{"key": "B","text": "Kyphosis of thoracic spine"},{"key": "C","text": "Scoliosis"},{"key": "D","text": "Genu valgum"}],"correct": "A","explanation": "Bilateral SCM tightness contributes to forward head posture due to its flexor action on lower cervical spine."},{"id": 1323,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Hard","question": "Which muscle works synergistically with SCM during contralateral rotation of the neck?","options": [{"key": "A","text": "Contralateral levator scapulae"},{"key": "B","text": "Ipsilateral splenius capitis"},{"key": "C","text": "Contralateral splenius capitis"},{"key": "D","text": "Ipsilateral trapezius"}],"correct": "B","explanation": "SCM and ipsilateral splenius capitis act together to rotate the head to the same side as splenius."},{"id": 1324,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Physiotherapy management of congenital torticollis primarily includes?","options": [{"key": "A","text": "Surgical release only"},{"key": "B","text": "Strengthening of tight SCM"},{"key": "C","text": "Passive stretching and positioning exercises"},{"key": "D","text": "Heat therapy only"}],"correct": "C","explanation": "Conservative management of torticollis emphasizes passive stretching, positioning, and active ROM exercises."},{"id": 1325,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Easy","question": "How many scalene muscles are present on each side of the neck?","options": [{"key": "A","text": "Two"},{"key": "B","text": "Five"},{"key": "C","text": "Three"},{"key": "D","text": "Four"}],"correct": "C","explanation": "There are three scalene muscles: anterior, middle, and posterior scalene."},{"id": 1326,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scalenus anterior originates from which structures?","options": [{"key": "A","text": "Transverse processes of C2-C7"},{"key": "B","text": "Spinous processes of C3-C6"},{"key": "C","text": "Transverse processes of C3-C6"},{"key": "D","text": "Transverse processes of C4-C6"}],"correct": "C","explanation": "Scalenus anterior arises from anterior tubercles of transverse processes of C3-C6."},{"id": 1327,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scalenus anterior inserts onto which structure?","options": [{"key": "A","text": "Clavicle"},{"key": "B","text": "Manubrium sterni"},{"key": "C","text": "Second rib"},{"key": "D","text": "First rib (scalene tubercle)"}],"correct": "D","explanation": "Scalenus anterior inserts on the scalene tubercle of the first rib."},{"id": 1328,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scalenus medius is the largest and longest of the scalene muscles, inserting onto?","options": [{"key": "A","text": "First rib (posterior to subclavian artery groove)"},{"key": "B","text": "Clavicle"},{"key": "C","text": "Manubrium"},{"key": "D","text": "Second rib"}],"correct": "A","explanation": "Scalenus medius inserts on the first rib, posterior to the subclavian artery groove."},{"id": 1329,"subject": "Anatomy","topic": "Thorax","difficulty": "Medium","question": "Scalenus posterior inserts onto which rib?","options": [{"key": "A","text": "Third rib"},{"key": "B","text": "Fourth rib"},{"key": "C","text": "First rib"},{"key": "D","text": "Second rib"}],"correct": "D","explanation": "Scalenus posterior, the smallest scalene, inserts on the outer surface of the second rib."},{"id": 1330,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which structures pass between scalenus anterior and scalenus medius?","options": [{"key": "A","text": "Brachial plexus and subclavian artery"},{"key": "B","text": "Vagus nerve"},{"key": "C","text": "Phrenic nerve only"},{"key": "D","text": "Subclavian vein only"}],"correct": "A","explanation": "The interscalene triangle transmits the brachial plexus trunks and subclavian artery."},{"id": 1331,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "The subclavian vein passes in relation to scalenus anterior how?","options": [{"key": "A","text": "Lateral to scalenus medius"},{"key": "B","text": "Through scalenus anterior"},{"key": "C","text": "Anterior to scalenus anterior"},{"key": "D","text": "Posterior to scalenus anterior"}],"correct": "C","explanation": "Subclavian vein passes anterior to scalenus anterior, while subclavian artery passes posterior to it."},{"id": 1332,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which nerve runs on the anterior surface of scalenus anterior muscle?","options": [{"key": "A","text": "Vagus nerve"},{"key": "B","text": "Accessory nerve"},{"key": "C","text": "Phrenic nerve"},{"key": "D","text": "Hypoglossal nerve"}],"correct": "C","explanation": "Phrenic nerve (C3-C5) runs obliquely on the anterior surface of scalenus anterior."},{"id": 1333,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Medium","question": "Compression of the brachial plexus and subclavian vessels between scalene muscles and first rib is known as?","options": [{"key": "A","text": "Cubital tunnel syndrome"},{"key": "B","text": "Carpal tunnel syndrome"},{"key": "C","text": "Piriformis syndrome"},{"key": "D","text": "Thoracic outlet syndrome"}],"correct": "D","explanation": "Thoracic outlet syndrome can result from neurovascular compression in the interscalene triangle."},{"id": 1334,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Which clinical test is used to assess thoracic outlet syndrome involving scalene muscles?","options": [{"key": "A","text": "Adson's test"},{"key": "B","text": "Ober's test"},{"key": "C","text": "Lachman test"},{"key": "D","text": "Thomas test"}],"correct": "A","explanation": "Adson's test assesses radial pulse changes with neck rotation/extension to detect TOS."},{"id": 1335,"subject": "Anatomy","topic": "Back & Spine","difficulty": "Medium","question": "Bilateral contraction of scalene muscles produces which action on the cervical spine?","options": [{"key": "A","text": "Extension"},{"key": "B","text": "Rotation only"},{"key": "C","text": "Lateral flexion only"},{"key": "D","text": "Flexion"}],"correct": "D","explanation": "Bilateral scalene contraction flexes the cervical spine (with fixed ribs) and assists inspiration."},{"id": 1336,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Scalene muscles are innervated by which nerves?","options": [{"key": "A","text": "Accessory nerve only"},{"key": "B","text": "Vagus nerve"},{"key": "C","text": "Cervical plexus and brachial plexus branches (C3-C8 ventral rami)"},{"key": "D","text": "Phrenic nerve only"}],"correct": "C","explanation": "Scalenes receive direct branches from cervical and brachial plexus ventral rami (C3-C8)."},{"id": 1337,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Scalene muscles act as accessory muscles of which respiratory function?","options": [{"key": "A","text": "Swallowing"},{"key": "B","text": "Forced expiration"},{"key": "C","text": "Forced inspiration (elevate ribs 1 and 2)"},{"key": "D","text": "Normal quiet expiration"}],"correct": "C","explanation": "Scalenes elevate the first and second ribs to assist forced inspiration."},{"id": 1338,"subject": "Anatomy","topic": "Upper Limb","difficulty": "Hard","question": "Which scalene muscle is most implicated in compressing the brachial plexus in thoracic outlet syndrome?","options": [{"key": "A","text": "Scalenus posterior"},{"key": "B","text": "All equally"},{"key": "C","text": "Scalenus medius"},{"key": "D","text": "Scalenus anterior"}],"correct": "D","explanation": "Scalenus anterior tightness/hypertrophy is most commonly implicated in neurogenic TOS."},{"id": 1339,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "The interscalene triangle is bounded anteriorly, posteriorly and inferiorly by which structures?","options": [{"key": "A","text": "Scalenus medius, scalenus posterior, second rib"},{"key": "B","text": "SCM, trapezius, clavicle"},{"key": "C","text": "Longus colli, longus capitis, hyoid"},{"key": "D","text": "Scalenus anterior, scalenus medius, first rib"}],"correct": "D","explanation": "Interscalene triangle boundaries: scalenus anterior (front), scalenus medius (back), first rib (base)."},{"id": 1340,"subject": "Anatomy","topic": "Thorax","difficulty": "Hard","question": "A cervical rib, when present, most commonly arises from which vertebra and predisposes to which condition?","options": [{"key": "A","text": "C5; whiplash"},{"key": "B","text": "C6; carpal tunnel syndrome"},{"key": "C","text": "C1; torticollis"},{"key": "D","text": "C7; thoracic outlet syndrome"}],"correct": "D","explanation": "A cervical rib usually arises from C7 and can compress the brachial plexus, causing TOS."},{"id": 1341,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "In physiotherapy, scalene stretching is commonly prescribed to relieve symptoms of?","options": [{"key": "A","text": "Thoracic outlet syndrome"},{"key": "B","text": "Lateral epicondylitis"},{"key": "C","text": "Plantar fasciitis"},{"key": "D","text": "De Quervain's tenosynovitis"}],"correct": "A","explanation": "Scalene stretching helps decompress the interscalene triangle in TOS management."},{"id": 1342,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which muscle lies posterior to scalenus medius, forming part of the floor of posterior triangle?","options": [{"key": "A","text": "Levator scapulae"},{"key": "B","text": "Trapezius"},{"key": "C","text": "Splenius cervicis"},{"key": "D","text": "Longus colli"}],"correct": "A","explanation": "Levator scapulae lies posterior to scalenus medius, both forming the floor of posterior triangle of neck."},{"id": 1343,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Costoclavicular syndrome, a form of TOS, involves compression between which structures?","options": [{"key": "A","text": "Cervical rib and clavicle"},{"key": "B","text": "Pectoralis minor and ribs"},{"key": "C","text": "Clavicle and first rib"},{"key": "D","text": "Scalene muscles only"}],"correct": "C","explanation": "Costoclavicular syndrome involves compression of neurovascular bundle between clavicle and first rib."},{"id": 1344,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "Scalene muscles are classified functionally as part of which muscle group of the neck?","options": [{"key": "A","text": "Infrahyoid group"},{"key": "B","text": "Lateral flexor/accessory respiratory group"},{"key": "C","text": "Suprahyoid group"},{"key": "D","text": "Posterior extensor group"}],"correct": "B","explanation": "Scalenes act as lateral flexors of the cervical spine and accessory muscles of respiration."},{"id": 1345,"subject": "Anatomy","topic": "Head & Neck","difficulty": "Medium","question": "Which deep neck flexor muscle is commonly weak in patients with forward head posture?","options": [{"key": "A","text": "Levator scapulae"},{"key": "B","text": "Longus colli"},{"key": "C","text": "Splenius capitis"},{"key": "D","text": "Trapezius"}],"correct": "B","explanation": "Longus colli (deep cervical flexor) is often weak/inhibited in forward head posture."},{"id": 1346,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Trapezius muscle is innervated by which cranial nerve?","options": [{"key": "A","text": "Vagus nerve (CN X)"},{"key": "B","text": "Hypoglossal nerve (CN XII)"},{"key": "C","text": "Accessory nerve (CN XI)"},{"key": "D","text": "Facial nerve (CN VII)"}],"correct": "C","explanation": "Spinal accessory nerve (CN XI) provides primary motor supply to trapezius."},{"id": 1347,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Levator scapulae originates from transverse processes of which vertebrae?","options": [{"key": "A","text": "C5-T1"},{"key": "B","text": "C1-C2"},{"key": "C","text": "C1-C4"},{"key": "D","text": "C3-C7"}],"correct": "C","explanation": "Levator scapulae arises from transverse processes of C1-C4 and inserts on the medial border of scapula."},{"id": 1348,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Splenius capitis muscle action when contracting bilaterally is?","options": [{"key": "A","text": "Rotation only"},{"key": "B","text": "Extension of head and neck"},{"key": "C","text": "Lateral flexion only"},{"key": "D","text": "Flexion of neck"}],"correct": "B","explanation": "Bilateral splenius capitis contraction extends the head and neck."},{"id": 1349,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Suboccipital triangle is formed by which three muscles?","options": [{"key": "A","text": "Rectus capitis posterior major, obliquus capitis superior, obliquus capitis inferior"},{"key": "B","text": "SCM, trapezius, splenius capitis"},{"key": "C","text": "Scalenus anterior, medius, posterior"},{"key": "D","text": "Rectus capitis posterior minor, longus capitis, longus colli"}],"correct": "A","explanation": "The suboccipital triangle boundaries are rectus capitis posterior major, obliquus capitis superior and inferior."},{"id": 1350,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Hard","question": "Which artery lies within the suboccipital triangle?","options": [{"key": "A","text": "Common carotid artery"},{"key": "B","text": "Vertebral artery"},{"key": "C","text": "External carotid artery"},{"key": "D","text": "Subclavian artery"}],"correct": "B","explanation": "Vertebral artery (third part) and suboccipital nerve lie within the suboccipital triangle."},{"id": 1351,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Greater occipital nerve, often involved in cervicogenic headache, arises from which spinal level?","options": [{"key": "A","text": "C1 dorsal ramus"},{"key": "B","text": "C4 dorsal ramus"},{"key": "C","text": "C2 dorsal ramus"},{"key": "D","text": "C3 dorsal ramus"}],"correct": "C","explanation": "Greater occipital nerve is the medial branch of the dorsal ramus of C2."},{"id": 1352,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Cervicogenic headache commonly involves referred pain from which upper cervical structures?","options": [{"key": "A","text": "Thoracic spine only"},{"key": "B","text": "Lumbar spine"},{"key": "C","text": "Upper cervical (C1-C3) joints and muscles"},{"key": "D","text": "Lower cervical (C5-C7) joints"}],"correct": "C","explanation": "Cervicogenic headache typically originates from C1-C3 spinal segments and associated structures."},{"id": 1353,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Longus colli and longus capitis are classified as which type of cervical muscles?","options": [{"key": "A","text": "Lateral rotators"},{"key": "B","text": "Suprahyoid muscles"},{"key": "C","text": "Deep anterior (flexor) muscles"},{"key": "D","text": "Superficial extensors"}],"correct": "C","explanation": "Longus colli and longus capitis are deep prevertebral flexor muscles of the cervical spine."},{"id": 1354,"subject": "Anatomy","topic": "General Anatomy","difficulty": "Medium","question": "Craniocervical flexion test (CCFT) is primarily used to assess function of which muscle?","options": [{"key": "A","text": "Deep cervical flexors (longus colli/capitis)"},{"key": "B","text": "Splenius capitis"},{"key": "C","text": "Scalenus anterior"},{"key": "D","text": "Upper trapezius"}],"correct": "A","explanation": "CCFT assesses the endurance and activation of deep cervical flexor muscles."},{"id": 1355,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Which part of the brain is responsible for voluntary motor control?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Primary motor cortex (precentral gyrus)"},{"key": "C","text": "Thalamus"},{"key": "D","text": "Hypothalamus"}],"correct": "B","explanation": "Primary motor cortex in the precentral gyrus (Brodmann area 4) controls voluntary movement."},{"id": 1356,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Primary motor cortex is located in which lobe?","options": [{"key": "A","text": "Parietal lobe"},{"key": "B","text": "Frontal lobe"},{"key": "C","text": "Temporal lobe"},{"key": "D","text": "Occipital lobe"}],"correct": "B","explanation": "Precentral gyrus of the frontal lobe houses the primary motor cortex."},{"id": 1357,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Primary somatosensory cortex is located in which gyrus?","options": [{"key": "A","text": "Postcentral gyrus"},{"key": "B","text": "Precentral gyrus"},{"key": "C","text": "Cingulate gyrus"},{"key": "D","text": "Superior temporal gyrus"}],"correct": "A","explanation": "Postcentral gyrus of parietal lobe is the primary somatosensory cortex."},{"id": 1358,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Broca's area, responsible for speech production, is located in which lobe?","options": [{"key": "A","text": "Temporal lobe"},{"key": "B","text": "Parietal lobe"},{"key": "C","text": "Occipital lobe"},{"key": "D","text": "Frontal lobe"}],"correct": "D","explanation": "Broca's area lies in the inferior frontal gyrus, usually left hemisphere."},{"id": 1359,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Wernicke's area, responsible for language comprehension, is located in which lobe?","options": [{"key": "A","text": "Parietal lobe"},{"key": "B","text": "Frontal lobe"},{"key": "C","text": "Temporal lobe"},{"key": "D","text": "Occipital lobe"}],"correct": "C","explanation": "Wernicke's area is located in the posterior superior temporal gyrus."},{"id": 1360,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Primary visual cortex is located in which lobe?","options": [{"key": "A","text": "Frontal lobe"},{"key": "B","text": "Temporal lobe"},{"key": "C","text": "Parietal lobe"},{"key": "D","text": "Occipital lobe"}],"correct": "D","explanation": "Primary visual cortex (V1) lies around the calcarine sulcus of occipital lobe."},{"id": 1361,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Primary auditory cortex is located in which gyrus?","options": [{"key": "A","text": "Precentral gyrus"},{"key": "B","text": "Postcentral gyrus"},{"key": "C","text": "Superior temporal gyrus"},{"key": "D","text": "Cingulate gyrus"}],"correct": "C","explanation": "Primary auditory cortex lies in the superior temporal gyrus (Heschl's gyrus)."},{"id": 1362,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Which part of the brain coordinates balance and fine motor movements?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Medulla oblongata"},{"key": "C","text": "Hypothalamus"},{"key": "D","text": "Cerebrum"}],"correct": "A","explanation": "Cerebellum is responsible for coordination, balance, and fine-tuning of voluntary movement."},{"id": 1363,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Damage to the cerebellum typically results in which clinical sign?","options": [{"key": "A","text": "Ataxia and dysmetria"},{"key": "B","text": "Sensory loss"},{"key": "C","text": "Spastic paralysis"},{"key": "D","text": "Aphasia"}],"correct": "A","explanation": "Cerebellar lesions cause ataxia, dysmetria, and intention tremor."},{"id": 1364,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The basal ganglia are primarily involved in?","options": [{"key": "A","text": "Hearing"},{"key": "B","text": "Regulation of voluntary movement"},{"key": "C","text": "Sensory processing"},{"key": "D","text": "Memory formation"}],"correct": "B","explanation": "Basal ganglia help regulate and modulate voluntary movement and motor planning."},{"id": 1365,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Parkinson's disease results from degeneration of which structure?","options": [{"key": "A","text": "Hippocampus"},{"key": "B","text": "Substantia nigra"},{"key": "C","text": "Cerebellum"},{"key": "D","text": "Corpus callosum"}],"correct": "B","explanation": "Loss of dopaminergic neurons in substantia nigra causes Parkinson's disease."},{"id": 1366,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The thalamus functions primarily as?","options": [{"key": "A","text": "Memory storage center"},{"key": "B","text": "Relay station for sensory information"},{"key": "C","text": "Motor control center"},{"key": "D","text": "Respiratory center"}],"correct": "B","explanation": "Thalamus relays and processes most sensory information to the cerebral cortex."},{"id": 1367,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The hypothalamus regulates which of the following?","options": [{"key": "A","text": "Autonomic functions and homeostasis"},{"key": "B","text": "Voluntary movement"},{"key": "C","text": "Hearing"},{"key": "D","text": "Vision"}],"correct": "A","explanation": "Hypothalamus controls autonomic nervous system, temperature, hunger, and endocrine function via pituitary."},{"id": 1368,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Which brainstem structure controls vital functions like heart rate and respiration?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Midbrain"},{"key": "C","text": "Pons"},{"key": "D","text": "Medulla oblongata"}],"correct": "D","explanation": "Medulla oblongata contains cardiac and respiratory centers controlling vital functions."},{"id": 1369,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The corpus callosum primarily functions to?","options": [{"key": "A","text": "Control respiration"},{"key": "B","text": "Relay sensory information"},{"key": "C","text": "Connect the two cerebral hemispheres"},{"key": "D","text": "Connect cerebellum to brainstem"}],"correct": "C","explanation": "Corpus callosum is the largest white matter tract connecting left and right cerebral hemispheres."},{"id": 1370,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Which cranial nerve nuclei are located in the midbrain?","options": [{"key": "A","text": "CN V and VI"},{"key": "B","text": "CN IX and X"},{"key": "C","text": "CN XI and XII"},{"key": "D","text": "CN III and IV"}],"correct": "D","explanation": "Oculomotor (III) and trochlear (IV) nerve nuclei are located in the midbrain."},{"id": 1371,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Which cranial nerve nuclei are primarily located in the pons?","options": [{"key": "A","text": "CN I and II"},{"key": "B","text": "CN IX and X"},{"key": "C","text": "CN XI and XII"},{"key": "D","text": "CN V, VI, VII, VIII"}],"correct": "D","explanation": "Trigeminal, abducens, facial and vestibulocochlear nerve nuclei lie in the pons."},{"id": 1372,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Which cranial nerves arise from the medulla oblongata?","options": [{"key": "A","text": "CN III, IV"},{"key": "B","text": "CN I, II"},{"key": "C","text": "CN V, VI"},{"key": "D","text": "CN IX, X, XI, XII"}],"correct": "D","explanation": "Glossopharyngeal, vagus, accessory and hypoglossal nerves arise from the medulla."},{"id": 1373,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The limbic system is primarily associated with which function?","options": [{"key": "A","text": "Hearing"},{"key": "B","text": "Emotion and memory"},{"key": "C","text": "Balance"},{"key": "D","text": "Motor coordination"}],"correct": "B","explanation": "Limbic system (hippocampus, amygdala, cingulate gyrus) regulates emotion and memory."},{"id": 1374,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The hippocampus is primarily responsible for?","options": [{"key": "A","text": "Visual processing"},{"key": "B","text": "Memory formation"},{"key": "C","text": "Hearing"},{"key": "D","text": "Motor planning"}],"correct": "B","explanation": "Hippocampus plays a key role in formation of new long-term memories."},{"id": 1375,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Internal capsule contains which important pathway?","options": [{"key": "A","text": "Corticospinal tract fibers"},{"key": "B","text": "Cerebellar fibers only"},{"key": "C","text": "Optic nerve fibers only"},{"key": "D","text": "Auditory fibers only"}],"correct": "A","explanation": "Internal capsule carries ascending and descending fibers including the corticospinal tract."},{"id": 1376,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "A stroke affecting the internal capsule commonly results in?","options": [{"key": "A","text": "Ipsilateral hemiplegia"},{"key": "B","text": "Pure sensory loss only"},{"key": "C","text": "Contralateral hemiplegia"},{"key": "D","text": "Bilateral paralysis"}],"correct": "C","explanation": "Lesions of internal capsule cause contralateral hemiplegia due to corticospinal tract involvement."},{"id": 1377,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The Circle of Willis is formed by anastomosis of which arteries?","options": [{"key": "A","text": "Carotid and vertebrobasilar systems"},{"key": "B","text": "Carotid arteries only"},{"key": "C","text": "Vertebral arteries only"},{"key": "D","text": "Subclavian arteries only"}],"correct": "A","explanation": "Circle of Willis is formed by anastomosis between internal carotid and vertebrobasilar arterial systems."},{"id": 1378,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Middle cerebral artery occlusion most commonly affects which area function?","options": [{"key": "A","text": "Lower limb motor/sensory function"},{"key": "B","text": "Vision only"},{"key": "C","text": "Face and upper limb motor/sensory function"},{"key": "D","text": "Hearing only"}],"correct": "C","explanation": "MCA supplies the lateral cerebral cortex controlling face and upper limb, hence face/arm weakness predominates."},{"id": 1379,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Anterior cerebral artery occlusion most commonly affects which area function?","options": [{"key": "A","text": "Lower limb motor/sensory function"},{"key": "B","text": "Vision"},{"key": "C","text": "Face and upper limb"},{"key": "D","text": "Hearing"}],"correct": "A","explanation": "ACA supplies medial cerebral cortex, controlling the lower limb, causing leg weakness predominantly."},{"id": 1380,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "CSF is primarily produced by which structure?","options": [{"key": "A","text": "Arachnoid villi"},{"key": "B","text": "Dura mater"},{"key": "C","text": "Pia mater"},{"key": "D","text": "Choroid plexus"}],"correct": "D","explanation": "Choroid plexus in the ventricles produces cerebrospinal fluid."},{"id": 1381,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "CSF is reabsorbed into venous circulation through which structure?","options": [{"key": "A","text": "Arachnoid villi"},{"key": "B","text": "Pia mater"},{"key": "C","text": "Choroid plexus"},{"key": "D","text": "Falx cerebri"}],"correct": "A","explanation": "Arachnoid villi/granulations reabsorb CSF into the dural venous sinuses."},{"id": 1382,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The reticular activating system (RAS), responsible for consciousness/arousal, is located in?","options": [{"key": "A","text": "Occipital lobe"},{"key": "B","text": "Brainstem"},{"key": "C","text": "Hippocampus"},{"key": "D","text": "Cerebellum"}],"correct": "B","explanation": "RAS is located in the brainstem and regulates wakefulness and arousal."},{"id": 1383,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Which lobe of the brain is primarily responsible for executive functions and personality?","options": [{"key": "A","text": "Temporal lobe"},{"key": "B","text": "Occipital lobe"},{"key": "C","text": "Frontal lobe"},{"key": "D","text": "Parietal lobe"}],"correct": "C","explanation": "Frontal lobe (prefrontal cortex) governs executive function, judgment, and personality."},{"id": 1384,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Decorticate posturing (arms flexed, legs extended) indicates a lesion at which level?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Below the level of red nucleus (brainstem)"},{"key": "C","text": "Spinal cord"},{"key": "D","text": "Above the level of red nucleus (cerebral hemispheres/internal capsule)"}],"correct": "D","explanation": "Decorticate posturing indicates lesion above red nucleus, while decerebrate indicates brainstem lesion below it."},{"id": 1385,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The spinal cord extends from foramen magnum to which vertebral level in adults?","options": [{"key": "A","text": "S1-S2"},{"key": "B","text": "L4-L5"},{"key": "C","text": "L1-L2"},{"key": "D","text": "T12-L1"}],"correct": "C","explanation": "Adult spinal cord typically terminates at the level of L1-L2 vertebra (conus medullaris)."},{"id": 1386,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The tapering end of the spinal cord is called?","options": [{"key": "A","text": "Conus medullaris"},{"key": "B","text": "Medullary cone"},{"key": "C","text": "Cauda equina"},{"key": "D","text": "Filum terminale"}],"correct": "A","explanation": "Conus medullaris is the cone-shaped termination of the spinal cord."},{"id": 1387,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Cauda equina refers to?","options": [{"key": "A","text": "The central canal of spinal cord"},{"key": "B","text": "The tapering tip of spinal cord"},{"key": "C","text": "A fold of dura mater"},{"key": "D","text": "Bundle of nerve roots below conus medullaris"}],"correct": "D","explanation": "Cauda equina is the bundle of lumbar, sacral and coccygeal nerve roots below the conus medullaris."},{"id": 1388,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "How many pairs of spinal nerves arise from the spinal cord?","options": [{"key": "A","text": "33 pairs"},{"key": "B","text": "29 pairs"},{"key": "C","text": "31 pairs"},{"key": "D","text": "35 pairs"}],"correct": "C","explanation": "There are 31 pairs of spinal nerves: 8 cervical, 12 thoracic, 5 lumbar, 5 sacral, 1 coccygeal."},{"id": 1389,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "How many pairs of cervical spinal nerves are there?","options": [{"key": "A","text": "6"},{"key": "B","text": "8"},{"key": "C","text": "9"},{"key": "D","text": "7"}],"correct": "B","explanation": "There are 8 pairs of cervical spinal nerves despite only 7 cervical vertebrae."},{"id": 1390,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "The corticospinal tract is primarily responsible for?","options": [{"key": "A","text": "Vibration sense"},{"key": "B","text": "Voluntary motor control"},{"key": "C","text": "Pain and temperature sensation"},{"key": "D","text": "Proprioception"}],"correct": "B","explanation": "Corticospinal (pyramidal) tract carries voluntary motor commands from cortex to spinal cord."},{"id": 1391,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Where do most corticospinal tract fibers decussate?","options": [{"key": "A","text": "Spinal cord"},{"key": "B","text": "Pons"},{"key": "C","text": "Pyramids of medulla oblongata"},{"key": "D","text": "Midbrain"}],"correct": "C","explanation": "Approximately 85-90% of corticospinal fibers cross at the pyramidal decussation in the medulla."},{"id": 1392,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The lateral corticospinal tract controls which type of movement?","options": [{"key": "A","text": "Reflexes only"},{"key": "B","text": "Axial/proximal muscles"},{"key": "C","text": "Distal limb muscles (fine voluntary movement)"},{"key": "D","text": "Autonomic functions"}],"correct": "C","explanation": "Lateral corticospinal tract, after decussation, controls distal limb muscles for fine voluntary movement."},{"id": 1393,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The dorsal column-medial lemniscus pathway carries which type of sensation?","options": [{"key": "A","text": "Pain and temperature"},{"key": "B","text": "Crude touch only"},{"key": "C","text": "Fine touch, vibration, and proprioception"},{"key": "D","text": "Autonomic sensation"}],"correct": "C","explanation": "Dorsal columns carry fine touch, vibration, and conscious proprioception."},{"id": 1394,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Where does the dorsal column-medial lemniscus pathway decussate?","options": [{"key": "A","text": "Pons"},{"key": "B","text": "Medulla oblongata"},{"key": "C","text": "Spinal cord"},{"key": "D","text": "Thalamus"}],"correct": "B","explanation": "DCML pathway fibers cross in the medulla as internal arcuate fibers forming the medial lemniscus."},{"id": 1395,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The spinothalamic tract primarily carries which sensations?","options": [{"key": "A","text": "Fine touch and proprioception"},{"key": "B","text": "Stereognosis"},{"key": "C","text": "Vibration"},{"key": "D","text": "Pain and temperature"}],"correct": "D","explanation": "Lateral spinothalamic tract carries pain and temperature sensation."},{"id": 1396,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Where does the spinothalamic tract decussate?","options": [{"key": "A","text": "Thalamus"},{"key": "B","text": "Within 1-2 spinal cord segments of entry"},{"key": "C","text": "Medulla oblongata"},{"key": "D","text": "Pons"}],"correct": "B","explanation": "Spinothalamic tract fibers cross within 1-2 segments at the level of the spinal cord."},{"id": 1397,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Brown-Sequard syndrome results from?","options": [{"key": "A","text": "Hemisection of the spinal cord"},{"key": "B","text": "Anterior cord compression only"},{"key": "C","text": "Complete spinal cord transection"},{"key": "D","text": "Posterior column lesion only"}],"correct": "A","explanation": "Brown-Sequard syndrome is caused by hemisection of the spinal cord."},{"id": 1398,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "In Brown-Sequard syndrome, ipsilateral loss occurs in which modalities?","options": [{"key": "A","text": "Temperature only"},{"key": "B","text": "Pain and temperature"},{"key": "C","text": "Pain only"},{"key": "D","text": "Motor function and proprioception/vibration"}],"correct": "D","explanation": "Ipsilateral loss occurs in motor (corticospinal) and proprioception/vibration (dorsal column) below lesion."},{"id": 1399,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "In Brown-Sequard syndrome, contralateral loss occurs in which modality?","options": [{"key": "A","text": "Motor function"},{"key": "B","text": "Pain and temperature"},{"key": "C","text": "Proprioception"},{"key": "D","text": "Vibration"}],"correct": "B","explanation": "Contralateral pain and temperature loss occurs due to crossed spinothalamic tract below the lesion."},{"id": 1400,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Anterior cord syndrome typically spares which sensory modality?","options": [{"key": "A","text": "Motor function"},{"key": "B","text": "Crude touch"},{"key": "C","text": "Proprioception and vibration sense (dorsal columns)"},{"key": "D","text": "Pain and temperature"}],"correct": "C","explanation": "Anterior cord syndrome spares dorsal column function (proprioception/vibration) but affects motor and pain/temp."},{"id": 1401,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Central cord syndrome classically presents with weakness more pronounced in which limbs?","options": [{"key": "A","text": "Equal in all four limbs"},{"key": "B","text": "Only one limb"},{"key": "C","text": "Upper limbs more than lower limbs"},{"key": "D","text": "Lower limbs more than upper limbs"}],"correct": "C","explanation": "Central cord syndrome causes greater weakness in upper limbs than lower limbs due to central tract organization."},{"id": 1402,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "The spinal cord is protected by three meningeal layers; name them from outer to inner.","options": [{"key": "A","text": "Pia, arachnoid, dura"},{"key": "B","text": "Dura, arachnoid, pia"},{"key": "C","text": "Arachnoid, dura, pia"},{"key": "D","text": "Dura, pia, arachnoid"}],"correct": "B","explanation": "From outermost to innermost: dura mater, arachnoid mater, pia mater."},{"id": 1403,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Cerebrospinal fluid in the spinal cord is found in which space?","options": [{"key": "A","text": "Epidural space"},{"key": "B","text": "Subarachnoid space"},{"key": "C","text": "Subdural space"},{"key": "D","text": "Subpial space"}],"correct": "B","explanation": "CSF circulates within the subarachnoid space surrounding the spinal cord."},{"id": 1404,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Lumbar puncture is commonly performed at which vertebral level to avoid spinal cord injury?","options": [{"key": "A","text": "T12-L1"},{"key": "B","text": "L1-L2"},{"key": "C","text": "S1-S2"},{"key": "D","text": "L3-L4 or L4-L5"}],"correct": "D","explanation": "Lumbar puncture is done below the conus medullaris, typically at L3-L4 or L4-L5."},{"id": 1405,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Autonomic dysreflexia is a clinical concern in spinal cord injuries above which level?","options": [{"key": "A","text": "C2"},{"key": "B","text": "L1"},{"key": "C","text": "S1"},{"key": "D","text": "T6"}],"correct": "D","explanation": "Autonomic dysreflexia commonly occurs in SCI at or above T6 level."},{"id": 1406,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Spinal shock following spinal cord injury is characterized by?","options": [{"key": "A","text": "Temporary loss of all reflexes below the lesion"},{"key": "B","text": "Hyperreflexia immediately after injury"},{"key": "C","text": "Increased muscle tone immediately"},{"key": "D","text": "Permanent loss of sensation only"}],"correct": "A","explanation": "Spinal shock causes temporary areflexia and flaccid paralysis below the level of injury."},{"id": 1407,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "The first reflex to return after spinal shock is typically?","options": [{"key": "A","text": "Achilles reflex"},{"key": "B","text": "Babinski reflex"},{"key": "C","text": "Patellar reflex"},{"key": "D","text": "Bulbocavernosus reflex"}],"correct": "D","explanation": "Bulbocavernosus reflex is usually the first reflex to return, signaling the end of spinal shock."},{"id": 1408,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Complete spinal cord injury at C4 level would most critically affect which function?","options": [{"key": "A","text": "Independent breathing (diaphragm function)"},{"key": "B","text": "Ankle dorsiflexion"},{"key": "C","text": "Hip flexion"},{"key": "D","text": "Hand grip"}],"correct": "A","explanation": "C4 level injury severely compromises diaphragm function (C3-C5 phrenic nerve), risking respiratory failure."},{"id": 1409,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "ASIA Impairment Scale grade A indicates?","options": [{"key": "A","text": "Normal motor and sensory function"},{"key": "B","text": "Motor incomplete below level"},{"key": "C","text": "Complete motor and sensory loss"},{"key": "D","text": "Sensory incomplete, motor complete"}],"correct": "C","explanation": "ASIA A indicates a complete spinal cord injury with no motor or sensory function preserved in S4-S5."},{"id": 1410,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Dermatome is defined as?","options": [{"key": "A","text": "Area of skin supplied by a single spinal nerve"},{"key": "B","text": "Area supplied by cranial nerves only"},{"key": "C","text": "Area of skin supplied by a single muscle"},{"key": "D","text": "Area of muscle supplied by a single nerve root"}],"correct": "A","explanation": "A dermatome is the area of skin innervated by sensory fibers of a single spinal nerve root."},{"id": 1411,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The C5 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Nipple line"},{"key": "B","text": "Lateral aspect of upper arm (deltoid area)"},{"key": "C","text": "Thumb"},{"key": "D","text": "Little finger"}],"correct": "B","explanation": "C5 dermatome covers the lateral arm over the deltoid region."},{"id": 1412,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The C6 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Axilla"},{"key": "B","text": "Thumb and lateral forearm"},{"key": "C","text": "Little finger"},{"key": "D","text": "Medial arm"}],"correct": "B","explanation": "C6 dermatome covers the thumb, index finger, and lateral forearm."},{"id": 1413,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The C7 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Lateral forearm"},{"key": "B","text": "Thumb"},{"key": "C","text": "Little finger"},{"key": "D","text": "Middle finger"}],"correct": "D","explanation": "C7 dermatome covers the middle finger."},{"id": 1414,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The C8 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Middle finger"},{"key": "B","text": "Lateral arm"},{"key": "C","text": "Thumb"},{"key": "D","text": "Little finger and medial forearm"}],"correct": "D","explanation": "C8 dermatome covers the little finger and medial side of the hand/forearm."},{"id": 1415,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The T4 dermatome level corresponds to which landmark?","options": [{"key": "A","text": "Umbilicus"},{"key": "B","text": "Xiphoid process"},{"key": "C","text": "Inguinal region"},{"key": "D","text": "Nipple line"}],"correct": "D","explanation": "T4 dermatome corresponds to the nipple line."},{"id": 1416,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The T10 dermatome level corresponds to which landmark?","options": [{"key": "A","text": "Xiphoid process"},{"key": "B","text": "Nipple line"},{"key": "C","text": "Umbilicus"},{"key": "D","text": "Pubic region"}],"correct": "C","explanation": "T10 dermatome corresponds to the level of the umbilicus."},{"id": 1417,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The L1 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Anterior thigh"},{"key": "B","text": "Medial leg"},{"key": "C","text": "Inguinal/groin region"},{"key": "D","text": "Lateral foot"}],"correct": "C","explanation": "L1 dermatome covers the inguinal/groin region."},{"id": 1418,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The L4 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Buttock"},{"key": "B","text": "Medial leg and medial malleolus"},{"key": "C","text": "Posterior thigh"},{"key": "D","text": "Lateral foot"}],"correct": "B","explanation": "L4 dermatome covers the medial leg including the medial malleolus."},{"id": 1419,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The L5 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Lateral malleolus/little toe"},{"key": "B","text": "Dorsum of foot and great toe"},{"key": "C","text": "Posterior thigh"},{"key": "D","text": "Medial malleolus"}],"correct": "B","explanation": "L5 dermatome covers the dorsum of the foot and great toe."},{"id": 1420,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The S1 dermatome typically corresponds to which area?","options": [{"key": "A","text": "Lateral foot, heel and little toe"},{"key": "B","text": "Anterior thigh"},{"key": "C","text": "Medial leg"},{"key": "D","text": "Dorsum of foot"}],"correct": "A","explanation": "S1 dermatome covers the lateral foot, heel and little toe (sole region)."},{"id": 1421,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "The perianal/saddle region corresponds to which dermatomes?","options": [{"key": "A","text": "T12-L1"},{"key": "B","text": "S1-S2"},{"key": "C","text": "L4-L5"},{"key": "D","text": "S3-S5"}],"correct": "D","explanation": "Saddle area sensation corresponds to S3-S5 dermatomes; saddle anesthesia suggests cauda equina syndrome."},{"id": 1422,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Saddle anesthesia is a red flag sign for which condition?","options": [{"key": "A","text": "Thoracic outlet syndrome"},{"key": "B","text": "Cauda equina syndrome"},{"key": "C","text": "Cervical radiculopathy"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "B","explanation": "Saddle anesthesia (S3-S5) is a hallmark red flag for cauda equina syndrome requiring urgent referral."},{"id": 1423,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Herpes zoster (shingles) rash typically follows the distribution of?","options": [{"key": "A","text": "A myotome"},{"key": "B","text": "Multiple dermatomes randomly"},{"key": "C","text": "A single dermatome"},{"key": "D","text": "A peripheral nerve"}],"correct": "C","explanation": "Herpes zoster reactivates in a dorsal root ganglion and presents along a single dermatome."},{"id": 1424,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Dermatome mapping is clinically useful for diagnosing which condition?","options": [{"key": "A","text": "Muscle strain"},{"key": "B","text": "Tendon rupture"},{"key": "C","text": "Nerve root compression/radiculopathy"},{"key": "D","text": "Ligament sprain"}],"correct": "C","explanation": "Sensory testing along dermatomes helps localize the level of nerve root compression in radiculopathy."},{"id": 1425,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which dermatome is tested by sensation over the nipple line during a neurological exam?","options": [{"key": "A","text": "T4"},{"key": "B","text": "T10"},{"key": "C","text": "T12"},{"key": "D","text": "T6"}],"correct": "A","explanation": "T4 dermatome level is classically tested at the nipple line."},{"id": 1426,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "The axilla region corresponds approximately to which dermatome?","options": [{"key": "A","text": "C8"},{"key": "B","text": "C5"},{"key": "C","text": "L1"},{"key": "D","text": "T1-T2"}],"correct": "D","explanation": "The axilla and medial arm correspond approximately to T1-T2 dermatomes."},{"id": 1427,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Dermatomal pattern of pain radiating down the posterior thigh and lateral leg to the foot suggests irritation of which nerve root?","options": [{"key": "A","text": "C7"},{"key": "B","text": "L4"},{"key": "C","text": "T12"},{"key": "D","text": "L5/S1"}],"correct": "D","explanation": "Sciatic pain radiating posteriorly to the foot commonly follows L5/S1 dermatomal distribution."},{"id": 1428,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "In a patient with numbness over the lateral three and a half fingers, which dermatome/nerve is likely involved?","options": [{"key": "A","text": "C8/ulnar nerve distribution"},{"key": "B","text": "L5 distribution"},{"key": "C","text": "T1 distribution"},{"key": "D","text": "C6/median nerve distribution"}],"correct": "D","explanation": "Numbness over thumb, index, middle and half of ring finger suggests C6 dermatome/median nerve involvement."},{"id": 1429,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "A patient presents with numbness of the little finger and medial forearm; which nerve root is most likely affected?","options": [{"key": "A","text": "C8"},{"key": "B","text": "C6"},{"key": "C","text": "C7"},{"key": "D","text": "C5"}],"correct": "A","explanation": "C8 dermatome covers the little finger and medial forearm, often involving ulnar nerve pathway."},{"id": 1430,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Hard","question": "Dermatomes overlap significantly such that loss of a single nerve root typically causes?","options": [{"key": "A","text": "No sensory change at all"},{"key": "B","text": "Hyperesthesia only"},{"key": "C","text": "Complete anesthesia in that area"},{"key": "D","text": "Partial sensory loss due to overlap from adjacent roots"}],"correct": "D","explanation": "Due to dermatomal overlap, a single root lesion usually causes partial rather than complete sensory loss."},{"id": 1431,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Easy","question": "Myotome is defined as?","options": [{"key": "A","text": "A single muscle's nerve supply"},{"key": "B","text": "Sensory distribution of a dermatome"},{"key": "C","text": "Group of muscles supplied by a single spinal nerve root"},{"key": "D","text": "Area of skin supplied by a nerve root"}],"correct": "C","explanation": "A myotome is the group of muscles innervated by a single spinal nerve root."},{"id": 1432,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for shoulder abduction (deltoid)?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C5"},{"key": "C","text": "C6"},{"key": "D","text": "C4"}],"correct": "B","explanation": "C5 myotome primarily tests shoulder abduction via deltoid muscle."},{"id": 1433,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for elbow flexion (biceps)?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C8"},{"key": "C","text": "C6"},{"key": "D","text": "C5"}],"correct": "C","explanation": "C6 myotome is tested via elbow flexion (biceps) and wrist extension."},{"id": 1434,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for elbow extension (triceps)?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C6"},{"key": "C","text": "C8"},{"key": "D","text": "C5"}],"correct": "A","explanation": "C7 myotome is tested via elbow extension (triceps) and wrist flexion."},{"id": 1435,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for finger flexion?","options": [{"key": "A","text": "C6"},{"key": "B","text": "C7"},{"key": "C","text": "T1"},{"key": "D","text": "C8"}],"correct": "D","explanation": "C8 myotome is tested via finger flexion (flexor digitorum)."},{"id": 1436,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for finger abduction (small hand muscles)?","options": [{"key": "A","text": "C8"},{"key": "B","text": "C7"},{"key": "C","text": "T1"},{"key": "D","text": "T2"}],"correct": "C","explanation": "T1 myotome is tested via finger abduction using intrinsic hand muscles."},{"id": 1437,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is primarily responsible for diaphragm function?","options": [{"key": "A","text": "C3-C5"},{"key": "B","text": "C6-C8"},{"key": "C","text": "T1-T2"},{"key": "D","text": "C2-C3"}],"correct": "A","explanation": "Phrenic nerve from C3-C5 ('C3,4,5 keep the diaphragm alive') innervates the diaphragm."},{"id": 1438,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for hip flexion?","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "L1-L2"},{"key": "C","text": "L5-S1"},{"key": "D","text": "L4-L5"}],"correct": "B","explanation": "L1-L2 myotome is primarily tested via hip flexion (iliopsoas)."},{"id": 1439,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for knee extension (quadriceps)?","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "S1"},{"key": "C","text": "L5"},{"key": "D","text": "L2"}],"correct": "A","explanation": "L3-L4 myotome is tested via knee extension using the quadriceps muscle."},{"id": 1440,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for ankle dorsiflexion (tibialis anterior)?","options": [{"key": "A","text": "L3"},{"key": "B","text": "S1"},{"key": "C","text": "L5"},{"key": "D","text": "L4"}],"correct": "D","explanation": "L4 myotome is classically tested via ankle dorsiflexion (tibialis anterior)."},{"id": 1441,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for great toe extension (extensor hallucis longus)?","options": [{"key": "A","text": "L4"},{"key": "B","text": "S2"},{"key": "C","text": "L3"},{"key": "D","text": "L5"}],"correct": "D","explanation": "L5 myotome is tested via great toe extension (extensor hallucis longus)."},{"id": 1442,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is responsible for ankle plantarflexion (gastrocnemius/soleus)?","options": [{"key": "A","text": "S2"},{"key": "B","text": "S1"},{"key": "C","text": "L5"},{"key": "D","text": "L4"}],"correct": "B","explanation": "S1 myotome is tested via ankle plantarflexion and eversion."},{"id": 1443,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which myotome is primarily responsible for knee flexion?","options": [{"key": "A","text": "S2-S3"},{"key": "B","text": "L5-S1"},{"key": "C","text": "L3-L4"},{"key": "D","text": "L1-L2"}],"correct": "B","explanation": "Knee flexion (hamstrings) is primarily mediated by L5-S1 myotome."},{"id": 1444,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Loss of ankle jerk reflex is associated with which nerve root lesion?","options": [{"key": "A","text": "L4"},{"key": "B","text": "S1"},{"key": "C","text": "S2"},{"key": "D","text": "L3"}],"correct": "B","explanation": "Ankle jerk (Achilles reflex) primarily tests S1 nerve root integrity."},{"id": 1445,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Loss of knee jerk reflex is associated with which nerve root lesion?","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "S1-S2"},{"key": "C","text": "L2-L4"},{"key": "D","text": "L5-S1"}],"correct": "C","explanation": "Knee jerk (patellar reflex) primarily tests L2-L4 (mainly L3-L4) nerve root integrity."},{"id": 1446,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Loss of biceps jerk reflex is associated with which nerve root?","options": [{"key": "A","text": "T1-T2"},{"key": "B","text": "C8-T1"},{"key": "C","text": "C5-C6"},{"key": "D","text": "C7-C8"}],"correct": "C","explanation": "Biceps reflex tests primarily C5-C6 nerve root integrity."},{"id": 1447,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Loss of triceps jerk reflex is associated with which nerve root?","options": [{"key": "A","text": "C6-C7"},{"key": "B","text": "C8-T1"},{"key": "C","text": "C5-C6"},{"key": "D","text": "C7-C8"}],"correct": "D","explanation": "Triceps reflex primarily tests C7-C8 nerve root integrity."},{"id": 1448,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Myotomal testing in physiotherapy is done primarily using which method?","options": [{"key": "A","text": "Reflex hammer testing only"},{"key": "B","text": "Resisted isometric muscle testing"},{"key": "C","text": "Light touch sensation testing"},{"key": "D","text": "Passive range of motion"}],"correct": "B","explanation": "Myotome testing is performed via resisted isometric contraction of key muscles for each spinal level."},{"id": 1449,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "A patient unable to perform resisted ankle dorsiflexion likely has involvement of which nerve root?","options": [{"key": "A","text": "S1"},{"key": "B","text": "L4"},{"key": "C","text": "L5"},{"key": "D","text": "L3"}],"correct": "B","explanation": "Weakness of ankle dorsiflexion (tibialis anterior) indicates L4 myotome involvement (or deep peroneal nerve)."},{"id": 1450,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Footdrop with weak ankle dorsiflexion and toe extension most commonly indicates lesion at which level?","options": [{"key": "A","text": "S3-S4"},{"key": "B","text": "L3"},{"key": "C","text": "L4-L5"},{"key": "D","text": "S1-S2"}],"correct": "C","explanation": "Footdrop typically results from L4-L5 nerve root or common peroneal nerve dysfunction."},{"id": 1451,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Myotome testing is clinically combined with which other assessments for complete neurological examination?","options": [{"key": "A","text": "Range of motion testing only"},{"key": "B","text": "Vital sign monitoring"},{"key": "C","text": "Dermatome testing and deep tendon reflexes"},{"key": "D","text": "Special orthopedic tests only"}],"correct": "C","explanation": "A complete neurological exam includes myotome (motor), dermatome (sensory), and reflex testing together."},{"id": 1452,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Cervical myotome C4 is primarily responsible for which action?","options": [{"key": "A","text": "Finger flexion"},{"key": "B","text": "Shoulder elevation (trapezius/shoulder shrug)"},{"key": "C","text": "Wrist extension"},{"key": "D","text": "Elbow flexion"}],"correct": "B","explanation": "C4 myotome is tested via shoulder shrug/elevation, mediated through trapezius and levator scapulae."},{"id": 1453,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "Which spinal tract is responsible for unconscious proprioception to the cerebellum?","options": [{"key": "A","text": "Corticospinal tract"},{"key": "B","text": "Spinocerebellar tract"},{"key": "C","text": "Lateral spinothalamic tract"},{"key": "D","text": "Dorsal column tract"}],"correct": "B","explanation": "Spinocerebellar tracts carry unconscious proprioceptive information to the cerebellum for coordination."},{"id": 1454,"subject": "Anatomy","topic": "Neuroanatomy","difficulty": "Medium","question": "The femoral nerve, testing knee extension, arises primarily from which myotome level?","options": [{"key": "A","text": "L2-L4"},{"key": "B","text": "S2-S3"},{"key": "C","text": "L1-L2"},{"key": "D","text": "L5-S1"}],"correct": "A","explanation": "Femoral nerve arises from L2-L4 ventral rami, innervating quadriceps for knee extension."},{"id": 1455,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The surgical neck of humerus is closely related to which nerve, injury of which causes deltoid paralysis?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Axillary nerve"}],"correct": "D","explanation": "Axillary nerve winds around the surgical neck of humerus and is vulnerable in fractures here."},{"id": 1456,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Radial nerve injury at the radial (spiral) groove of humerus most commonly results in?","options": [{"key": "A","text": "Winging of scapula"},{"key": "B","text": "Ape thumb deformity"},{"key": "C","text": "Claw hand"},{"key": "D","text": "Wrist drop"}],"correct": "D","explanation": "Radial nerve injury in spiral groove causes wrist drop due to paralysis of wrist/finger extensors."},{"id": 1457,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which carpal bone is most commonly fractured following a fall on outstretched hand?","options": [{"key": "A","text": "Hamate"},{"key": "B","text": "Lunate"},{"key": "C","text": "Scaphoid"},{"key": "D","text": "Trapezium"}],"correct": "C","explanation": "Scaphoid is the most commonly fractured carpal bone, often missed on initial X-ray."},{"id": 1458,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Avascular necrosis is a common complication of fracture of which carpal bone due to retrograde blood supply?","options": [{"key": "A","text": "Pisiform"},{"key": "B","text": "Triquetrum"},{"key": "C","text": "Scaphoid"},{"key": "D","text": "Capitate"}],"correct": "C","explanation": "Scaphoid has retrograde blood supply, making proximal pole fractures prone to avascular necrosis."},{"id": 1459,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The radial styloid process is normally longer/more distal than the ulnar styloid by approximately?","options": [{"key": "A","text": "Equal length"},{"key": "B","text": "5 cm"},{"key": "C","text": "2.5 cm"},{"key": "D","text": "1 cm"}],"correct": "D","explanation": "Radial styloid is normally about 1 cm more distal than the ulnar styloid process."},{"id": 1460,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "In a Colles' fracture, the distal fragment of radius is typically displaced in which direction?","options": [{"key": "A","text": "Medially"},{"key": "B","text": "Posteriorly (dorsally)"},{"key": "C","text": "Laterally only"},{"key": "D","text": "Anteriorly (volarly)"}],"correct": "B","explanation": "Colles' fracture shows dorsal (posterior) displacement of the distal radial fragment, the classic 'dinner fork' deformity."},{"id": 1461,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The carrying angle of the elbow is increased in which condition?","options": [{"key": "A","text": "Genu varum"},{"key": "B","text": "Cubitus valgus"},{"key": "C","text": "Cubitus varus"},{"key": "D","text": "Genu valgum"}],"correct": "B","explanation": "Cubitus valgus refers to an increased carrying angle at the elbow."},{"id": 1462,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which ligament of the shoulder is most commonly injured in anterior shoulder dislocation?","options": [{"key": "A","text": "Transverse humeral ligament"},{"key": "B","text": "Inferior glenohumeral ligament"},{"key": "C","text": "Coracoclavicular ligament"},{"key": "D","text": "Coracoacromial ligament"}],"correct": "B","explanation": "Inferior glenohumeral ligament complex is the primary stabilizer injured in anterior dislocation."},{"id": 1463,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "A Bankart lesion refers to injury of which structure following anterior shoulder dislocation?","options": [{"key": "A","text": "Rotator cuff tendon"},{"key": "B","text": "Anteroinferior glenoid labrum"},{"key": "C","text": "Acromioclavicular ligament"},{"key": "D","text": "Long head of biceps tendon"}],"correct": "B","explanation": "Bankart lesion is detachment of the anteroinferior glenoid labrum from recurrent anterior dislocation."},{"id": 1464,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "A Hill-Sachs lesion is a compression fracture occurring at which site after anterior dislocation?","options": [{"key": "A","text": "Posterolateral humeral head"},{"key": "B","text": "Coracoid process"},{"key": "C","text": "Glenoid rim"},{"key": "D","text": "Acromion"}],"correct": "A","explanation": "Hill-Sachs lesion is an impaction fracture of the posterolateral humeral head against the glenoid rim."},{"id": 1465,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The elbow joint is classified as which type of synovial joint?","options": [{"key": "A","text": "Hinge (uniaxial)"},{"key": "B","text": "Ball and socket"},{"key": "C","text": "Saddle"},{"key": "D","text": "Pivot"}],"correct": "A","explanation": "Humeroulnar joint of the elbow is a uniaxial hinge joint allowing flexion-extension."},{"id": 1466,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The proximal radioulnar joint is classified as which type of joint?","options": [{"key": "A","text": "Plane joint"},{"key": "B","text": "Pivot joint"},{"key": "C","text": "Saddle joint"},{"key": "D","text": "Hinge joint"}],"correct": "B","explanation": "Proximal radioulnar joint is a pivot joint allowing pronation and supination."},{"id": 1467,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which wrist ligament tear is most associated with scapholunate instability?","options": [{"key": "A","text": "Triangular fibrocartilage complex"},{"key": "B","text": "Radial collateral ligament"},{"key": "C","text": "Scapholunate interosseous ligament"},{"key": "D","text": "Ulnar collateral ligament"}],"correct": "C","explanation": "Scapholunate interosseous ligament injury causes scapholunate dissociation/instability."},{"id": 1468,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which special test is used to detect a SLAP lesion of the shoulder?","options": [{"key": "A","text": "Drop arm test"},{"key": "B","text": "O'Brien's test"},{"key": "C","text": "Neer's test"},{"key": "D","text": "Empty can test"}],"correct": "B","explanation": "O'Brien's (active compression) test is used to detect superior labrum anterior-posterior (SLAP) lesions."},{"id": 1469,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which rotator cuff muscle is the primary initiator of shoulder abduction in the first 15 degrees?","options": [{"key": "A","text": "Infraspinatus"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Teres minor"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Supraspinatus initiates the first 15 degrees of shoulder abduction before deltoid takes over."},{"id": 1470,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which rotator cuff muscle is the primary internal rotator of the shoulder?","options": [{"key": "A","text": "Supraspinatus"},{"key": "B","text": "Infraspinatus"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Teres minor"}],"correct": "C","explanation": "Subscapularis is the main internal rotator among rotator cuff muscles."},{"id": 1471,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The long head of biceps brachii originates from which structure?","options": [{"key": "A","text": "Supraglenoid tubercle of scapula"},{"key": "B","text": "Glenoid neck"},{"key": "C","text": "Coracoid process"},{"key": "D","text": "Infraglenoid tubercle of scapula"}],"correct": "A","explanation": "Long head of biceps arises from the supraglenoid tubercle of the scapula."},{"id": 1472,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Triceps brachii is innervated by which nerve?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Radial nerve"}],"correct": "D","explanation": "All three heads of triceps brachii are supplied by the radial nerve."},{"id": 1473,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which forearm muscle is the primary supinator independent of elbow position?","options": [{"key": "A","text": "Brachioradialis"},{"key": "B","text": "Biceps brachii"},{"key": "C","text": "Pronator teres"},{"key": "D","text": "Supinator"}],"correct": "D","explanation": "Supinator muscle works independent of elbow flexion angle, unlike biceps which is more effective when elbow flexed."},{"id": 1474,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Pronator teres is innervated by which nerve?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "B","explanation": "Pronator teres receives innervation from the median nerve."},{"id": 1475,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which intrinsic hand muscles are supplied by the median nerve (LOAF muscles) except?","options": [{"key": "A","text": "Lateral 2 lumbricals"},{"key": "B","text": "Flexor digiti minimi"},{"key": "C","text": "Abductor pollicis brevis"},{"key": "D","text": "Opponens pollicis"}],"correct": "B","explanation": "Flexor digiti minimi is supplied by ulnar nerve, not part of median-innervated LOAF muscles."},{"id": 1476,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Erb's palsy results from injury to which roots of the brachial plexus?","options": [{"key": "A","text": "C8-T1"},{"key": "B","text": "C5-C6"},{"key": "C","text": "C7-C8"},{"key": "D","text": "C6-C7"}],"correct": "B","explanation": "Erb's palsy (waiter's tip deformity) results from upper trunk (C5-C6) injury."},{"id": 1477,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Klumpke's palsy results from injury to which roots of the brachial plexus?","options": [{"key": "A","text": "C7-C8"},{"key": "B","text": "C6-C7"},{"key": "C","text": "C5-C6"},{"key": "D","text": "C8-T1"}],"correct": "D","explanation": "Klumpke's palsy results from lower trunk (C8-T1) injury, causing claw hand."},{"id": 1478,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Median nerve injury at the wrist classically produces which deformity on attempted fist making?","options": [{"key": "A","text": "Claw hand"},{"key": "B","text": "Wrist drop"},{"key": "C","text": "Winged scapula"},{"key": "D","text": "Ape thumb deformity"}],"correct": "D","explanation": "Median nerve injury causes ape thumb deformity due to loss of thenar muscle function."},{"id": 1479,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Ulnar nerve injury at the wrist produces which classic hand deformity?","options": [{"key": "A","text": "Ape thumb deformity"},{"key": "B","text": "Claw hand (ulnar claw)"},{"key": "C","text": "Wrist drop"},{"key": "D","text": "Pope's blessing sign"}],"correct": "B","explanation": "Ulnar nerve injury causes claw hand due to unopposed action of extensor digitorum on ring/little fingers."},{"id": 1480,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Radial nerve provides sensory innervation to which area of the hand?","options": [{"key": "A","text": "Dorsal web space between thumb and index finger"},{"key": "B","text": "Palmar aspect of thumb"},{"key": "C","text": "Medial palm"},{"key": "D","text": "Palmar aspect of little finger"}],"correct": "A","explanation": "Radial nerve's superficial branch supplies sensation to the dorsal first web space."},{"id": 1481,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Carpal tunnel syndrome results from compression of which nerve?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Radial nerve"}],"correct": "C","explanation": "Carpal tunnel syndrome is caused by median nerve compression beneath the flexor retinaculum."},{"id": 1482,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Winging of scapula is caused by paralysis of which muscle, innervated by the long thoracic nerve?","options": [{"key": "A","text": "Levator scapulae"},{"key": "B","text": "Rhomboid major"},{"key": "C","text": "Serratus anterior"},{"key": "D","text": "Trapezius"}],"correct": "C","explanation": "Serratus anterior paralysis (long thoracic nerve injury) causes medial winging of the scapula."},{"id": 1483,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The femoral neck is most vulnerable to fracture in elderly due to which factor?","options": [{"key": "A","text": "Increased cortical thickness"},{"key": "B","text": "Thick periosteum"},{"key": "C","text": "Osteoporosis and retrograde blood supply"},{"key": "D","text": "Strong ligamentous support"}],"correct": "C","explanation": "Osteoporosis combined with tenuous retrograde blood supply via retinacular vessels predisposes to femoral neck fractures."},{"id": 1484,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which artery is the primary blood supply to the femoral head in adults?","options": [{"key": "A","text": "Medial circumflex femoral artery"},{"key": "B","text": "Obturator artery via ligamentum teres"},{"key": "C","text": "Inferior gluteal artery"},{"key": "D","text": "Lateral circumflex femoral artery"}],"correct": "A","explanation": "Medial circumflex femoral artery provides the major blood supply to the femoral head via retinacular vessels."},{"id": 1485,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which tibial landmark serves as the attachment site for the patellar ligament?","options": [{"key": "A","text": "Medial tibial condyle"},{"key": "B","text": "Medial malleolus"},{"key": "C","text": "Tibial plateau"},{"key": "D","text": "Tibial tuberosity"}],"correct": "D","explanation": "Patellar ligament attaches to the tibial tuberosity."},{"id": 1486,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The fibula does not bear significant body weight but serves as attachment for which structures?","options": [{"key": "A","text": "Quadriceps muscles"},{"key": "B","text": "Patellar ligament"},{"key": "C","text": "Anterior cruciate ligament"},{"key": "D","text": "Lateral collateral ligament and several leg muscles"}],"correct": "D","explanation": "Fibula provides attachment for lateral collateral ligament and muscles like biceps femoris, peroneal muscles."},{"id": 1487,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which tarsal bone is the largest and forms the heel?","options": [{"key": "A","text": "Navicular"},{"key": "B","text": "Cuboid"},{"key": "C","text": "Calcaneus"},{"key": "D","text": "Talus"}],"correct": "C","explanation": "Calcaneus is the largest tarsal bone, forming the heel and bearing weight during stance."},{"id": 1488,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The talus articulates with the tibia and fibula to form which joint?","options": [{"key": "A","text": "Subtalar joint"},{"key": "B","text": "Tarsometatarsal joint"},{"key": "C","text": "Ankle (talocrural) joint"},{"key": "D","text": "Midtarsal joint"}],"correct": "C","explanation": "Talus articulates superiorly with tibia and fibula forming the talocrural (ankle) joint."},{"id": 1489,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Avascular necrosis of the talus is a known risk after fracture due to which feature?","options": [{"key": "A","text": "Rich periosteal blood supply"},{"key": "B","text": "No cartilage covering"},{"key": "C","text": "Strong muscular attachments"},{"key": "D","text": "Retrograde blood supply with limited collateral circulation"}],"correct": "D","explanation": "Talus has limited blood supply with no muscular attachments, making it prone to avascular necrosis after fracture."},{"id": 1490,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The hip joint is classified as which type of synovial joint?","options": [{"key": "A","text": "Hinge joint"},{"key": "B","text": "Saddle joint"},{"key": "C","text": "Condyloid joint"},{"key": "D","text": "Ball and socket joint"}],"correct": "D","explanation": "Hip joint is a multiaxial ball and socket joint between femoral head and acetabulum."},{"id": 1491,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which ligament of the hip is the strongest and prevents excessive extension?","options": [{"key": "A","text": "Pubofemoral ligament"},{"key": "B","text": "Iliofemoral ligament (Y-ligament of Bigelow)"},{"key": "C","text": "Ligamentum teres"},{"key": "D","text": "Ischiofemoral ligament"}],"correct": "B","explanation": "Iliofemoral ligament is the strongest ligament of the body, limiting hip extension."},{"id": 1492,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The knee joint's anterior cruciate ligament primarily prevents which movement?","options": [{"key": "A","text": "Anterior translation of tibia on femur"},{"key": "B","text": "Valgus stress"},{"key": "C","text": "Posterior translation of tibia"},{"key": "D","text": "Varus stress"}],"correct": "A","explanation": "ACL primarily resists anterior translation of the tibia relative to the femur."},{"id": 1493,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which special test is most sensitive for detecting ACL rupture?","options": [{"key": "A","text": "McMurray test"},{"key": "B","text": "Valgus stress test"},{"key": "C","text": "Thomas test"},{"key": "D","text": "Lachman test"}],"correct": "D","explanation": "Lachman test is considered the most sensitive clinical test for ACL integrity."},{"id": 1494,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The unhappy triad (O'Donoghue's triad) of knee injury involves ACL, MCL and which structure?","options": [{"key": "A","text": "PCL"},{"key": "B","text": "Medial meniscus"},{"key": "C","text": "Lateral meniscus"},{"key": "D","text": "Patellar tendon"}],"correct": "B","explanation": "Unhappy triad classically involves ACL, MCL, and medial meniscus injury together."},{"id": 1495,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The ankle joint is most stable in which position due to talar dome shape?","options": [{"key": "A","text": "Dorsiflexion"},{"key": "B","text": "Neutral position"},{"key": "C","text": "Plantarflexion"},{"key": "D","text": "Eversion"}],"correct": "A","explanation": "The wider anterior talar dome fits snugly into the mortise during dorsiflexion, making the ankle most stable."},{"id": 1496,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which ligament of the ankle is most commonly sprained in an inversion injury?","options": [{"key": "A","text": "Anterior talofibular ligament"},{"key": "B","text": "Calcaneofibular ligament"},{"key": "C","text": "Posterior talofibular ligament"},{"key": "D","text": "Deltoid ligament"}],"correct": "A","explanation": "Anterior talofibular ligament is the most frequently injured ligament in ankle inversion sprains."},{"id": 1497,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which quadriceps muscle is the only one that crosses both hip and knee joints?","options": [{"key": "A","text": "Vastus medialis"},{"key": "B","text": "Vastus intermedius"},{"key": "C","text": "Rectus femoris"},{"key": "D","text": "Vastus lateralis"}],"correct": "C","explanation": "Rectus femoris is biarticular, crossing both the hip and knee joints."},{"id": 1498,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Hamstring muscles are innervated by which nerve, except the short head of biceps femoris?","options": [{"key": "A","text": "Obturator nerve"},{"key": "B","text": "Common peroneal division of sciatic nerve"},{"key": "C","text": "Tibial division of sciatic nerve"},{"key": "D","text": "Femoral nerve"}],"correct": "C","explanation": "Tibial division of sciatic nerve supplies most hamstrings; short head of biceps femoris is innervated by common peroneal division."},{"id": 1499,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Gluteus medius is most important for preventing which gait abnormality?","options": [{"key": "A","text": "Steppage gait"},{"key": "B","text": "Trendelenburg gait"},{"key": "C","text": "Antalgic gait"},{"key": "D","text": "Scissor gait"}],"correct": "B","explanation": "Weak gluteus medius causes a Trendelenburg gait with pelvic drop on the contralateral side during stance."},{"id": 1500,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which gluteal muscle is the primary hip extensor used in climbing stairs and rising from sitting?","options": [{"key": "A","text": "Gluteus minimus"},{"key": "B","text": "Tensor fasciae latae"},{"key": "C","text": "Gluteus medius"},{"key": "D","text": "Gluteus maximus"}],"correct": "D","explanation": "Gluteus maximus is the prime mover for powerful hip extension activities like stair climbing."},{"id": 1501,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The gastrocnemius muscle crosses which two joints?","options": [{"key": "A","text": "Hip and ankle"},{"key": "B","text": "Ankle only"},{"key": "C","text": "Knee and ankle"},{"key": "D","text": "Hip and knee"}],"correct": "C","explanation": "Gastrocnemius is biarticular, crossing both the knee and ankle joints."},{"id": 1502,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which calf muscle is most active during standing balance and is mono-articular (crosses ankle only)?","options": [{"key": "A","text": "Popliteus"},{"key": "B","text": "Gastrocnemius"},{"key": "C","text": "Soleus"},{"key": "D","text": "Plantaris"}],"correct": "C","explanation": "Soleus crosses only the ankle joint and is key for postural stability during quiet standing."},{"id": 1503,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Achilles tendon is formed by the union of which muscles' tendons?","options": [{"key": "A","text": "Tibialis posterior and flexor digitorum longus"},{"key": "B","text": "Gastrocnemius and soleus"},{"key": "C","text": "Popliteus and plantaris"},{"key": "D","text": "Peroneus longus and brevis"}],"correct": "B","explanation": "Achilles (calcaneal) tendon is formed by the conjoined tendons of gastrocnemius and soleus."},{"id": 1504,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Femoral nerve injury most significantly impairs which movement?","options": [{"key": "A","text": "Knee extension"},{"key": "B","text": "Hip adduction"},{"key": "C","text": "Ankle dorsiflexion"},{"key": "D","text": "Hip extension"}],"correct": "A","explanation": "Femoral nerve supplies quadriceps; injury impairs knee extension significantly."},{"id": 1505,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Sciatic nerve is formed from which nerve roots?","options": [{"key": "A","text": "L2-L4"},{"key": "B","text": "S2-S4"},{"key": "C","text": "L4-S3"},{"key": "D","text": "L1-L3"}],"correct": "C","explanation": "Sciatic nerve arises from ventral rami of L4-S3."},{"id": 1506,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Common peroneal nerve is most vulnerable to injury at which anatomical site?","options": [{"key": "A","text": "Tarsal tunnel"},{"key": "B","text": "Neck of fibula"},{"key": "C","text": "Adductor canal"},{"key": "D","text": "Popliteal fossa"}],"correct": "B","explanation": "Common peroneal nerve winds around the neck of fibula, making it superficial and vulnerable there."},{"id": 1507,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Injury to the common peroneal nerve classically results in which deformity?","options": [{"key": "A","text": "Pes cavus"},{"key": "B","text": "Foot drop"},{"key": "C","text": "Claw foot"},{"key": "D","text": "Hammer toe"}],"correct": "B","explanation": "Common peroneal nerve injury causes foot drop due to paralysis of dorsiflexors and evertors."},{"id": 1508,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Tibial nerve injury results in loss of which movement?","options": [{"key": "A","text": "Knee extension"},{"key": "B","text": "Hip abduction"},{"key": "C","text": "Ankle plantarflexion and toe flexion"},{"key": "D","text": "Ankle dorsiflexion"}],"correct": "C","explanation": "Tibial nerve supplies posterior leg muscles responsible for plantarflexion and toe flexion."},{"id": 1509,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Tarsal tunnel syndrome involves compression of which nerve?","options": [{"key": "A","text": "Saphenous nerve"},{"key": "B","text": "Posterior tibial nerve"},{"key": "C","text": "Superficial peroneal nerve"},{"key": "D","text": "Sural nerve"}],"correct": "B","explanation": "Tarsal tunnel syndrome results from posterior tibial nerve compression behind the medial malleolus."},{"id": 1510,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Meralgia paresthetica results from compression of which nerve?","options": [{"key": "A","text": "Lateral femoral cutaneous nerve"},{"key": "B","text": "Femoral nerve"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Saphenous nerve"}],"correct": "A","explanation": "Meralgia paresthetica is caused by compression of the lateral femoral cutaneous nerve near the inguinal ligament."},{"id": 1511,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which cervical level accounts for approximately 50% of total cervical spine rotation?","options": [{"key": "A","text": "C6-C7"},{"key": "B","text": "C0-C1 (atlanto-occipital joint)"},{"key": "C","text": "C4-C5"},{"key": "D","text": "C1-C2 (atlanto-axial joint)"}],"correct": "D","explanation": "Atlanto-axial (C1-C2) joint contributes about 50% of total cervical rotation."},{"id": 1512,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The vertebral artery typically enters the transverse foramen first at which cervical level?","options": [{"key": "A","text": "C4"},{"key": "B","text": "C3"},{"key": "C","text": "C5"},{"key": "D","text": "C6"}],"correct": "D","explanation": "Vertebral artery usually enters the transverse foramen at C6 in most individuals."},{"id": 1513,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Cervical radiculopathy at C6 nerve root classically presents with weakness of which muscle?","options": [{"key": "A","text": "Finger flexors"},{"key": "B","text": "Triceps"},{"key": "C","text": "Biceps brachii and wrist extensors"},{"key": "D","text": "Intrinsic hand muscles"}],"correct": "C","explanation": "C6 radiculopathy presents with biceps and wrist extensor weakness along with thumb/index sensory changes."},{"id": 1514,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Spurling's test is used clinically to assess for?","options": [{"key": "A","text": "Cervical nerve root compression"},{"key": "B","text": "Rotator cuff tear"},{"key": "C","text": "Thoracic outlet syndrome"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "A","explanation": "Spurling's test (cervical compression with extension/lateral flexion) reproduces radicular symptoms in nerve root compression."},{"id": 1515,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Vertebrobasilar insufficiency testing before cervical manipulation primarily screens for compromise of which vessels?","options": [{"key": "A","text": "Subclavian arteries"},{"key": "B","text": "Jugular veins"},{"key": "C","text": "Vertebral arteries"},{"key": "D","text": "Carotid arteries"}],"correct": "C","explanation": "Pre-manipulative testing screens for vertebrobasilar (vertebral artery) insufficiency to avoid stroke risk."},{"id": 1516,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Intervertebral discs are avascular structures that primarily receive nutrition by which mechanism?","options": [{"key": "A","text": "Synovial fluid exchange"},{"key": "B","text": "Diffusion through vertebral endplates"},{"key": "C","text": "Direct capillary supply"},{"key": "D","text": "Lymphatic drainage"}],"correct": "B","explanation": "Adult intervertebral discs are avascular and rely on diffusion through cartilaginous endplates for nutrition."},{"id": 1517,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Posterolateral disc herniation most commonly compresses which nerve root relative to vertebral level (e.g., L4-L5 disc)?","options": [{"key": "A","text": "Both nerve roots equally"},{"key": "B","text": "The traversing nerve root of the level below (e.g., L5)"},{"key": "C","text": "No nerve root, only the cord"},{"key": "D","text": "The nerve root exiting above the disc level"}],"correct": "B","explanation": "Posterolateral herniation typically compresses the traversing (descending) nerve root, e.g., L4-L5 disc affects L5 root."},{"id": 1518,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The annulus fibrosus of the intervertebral disc is composed of which tissue arrangement?","options": [{"key": "A","text": "Loose areolar connective tissue"},{"key": "B","text": "Hydrated gel without fibers"},{"key": "C","text": "Hyaline cartilage plates only"},{"key": "D","text": "Concentric lamellae of fibrocartilage with alternating fiber orientation"}],"correct": "D","explanation": "Annulus fibrosus consists of concentric lamellae with collagen fibers oriented at alternating angles for strength."},{"id": 1519,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Lumbar spinal stenosis classically produces symptoms that are relieved by which posture?","options": [{"key": "A","text": "Spinal extension"},{"key": "B","text": "Lateral flexion"},{"key": "C","text": "Spinal flexion (e.g., leaning forward, sitting)"},{"key": "D","text": "Prolonged standing"}],"correct": "C","explanation": "Lumbar stenosis symptoms (neurogenic claudication) typically improve with flexion as it increases canal diameter."},{"id": 1520,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which ligament, if it ossifies, is implicated in spinal canal stenosis especially in the cervical/thoracic spine?","options": [{"key": "A","text": "Supraspinous ligament"},{"key": "B","text": "Posterior longitudinal ligament"},{"key": "C","text": "Iliolumbar ligament"},{"key": "D","text": "Anterior longitudinal ligament"}],"correct": "B","explanation": "Ossification of posterior longitudinal ligament (OPLL) can cause significant spinal canal stenosis."},{"id": 1521,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Spondylolisthesis most commonly occurs at which lumbar level due to mechanical stress?","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "L1-L2"},{"key": "C","text": "L5-S1"},{"key": "D","text": "L2-L3"}],"correct": "C","explanation": "L5-S1 is the most common site for spondylolisthesis due to high mechanical shear forces."},{"id": 1522,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The pars interarticularis defect associated with spondylolysis is best visualized on which X-ray view?","options": [{"key": "A","text": "AP view"},{"key": "B","text": "Lateral view"},{"key": "C","text": "Oblique view ('Scottie dog' sign)"},{"key": "D","text": "Flexion-extension view"}],"correct": "C","explanation": "Oblique lumbar spine X-ray shows the 'Scottie dog' appearance, with a collar representing pars interarticularis defect."},{"id": 1523,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The sacroiliac joint is classified as which type of joint?","options": [{"key": "A","text": "Synovial plane joint with fibrous reinforcement (combination joint)"},{"key": "B","text": "Pure synovial ball and socket joint"},{"key": "C","text": "Pure cartilaginous joint"},{"key": "D","text": "Pure fibrous joint"}],"correct": "A","explanation": "SI joint is a combination joint - synovial anteriorly and fibrous/ligamentous posteriorly, providing strong stability."},{"id": 1524,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which test is commonly used clinically to provoke sacroiliac joint pain?","options": [{"key": "A","text": "Thomas test"},{"key": "B","text": "FABER (Patrick's) test"},{"key": "C","text": "Lachman test"},{"key": "D","text": "Spurling's test"}],"correct": "B","explanation": "FABER/Patrick's test (Flexion, Abduction, External Rotation) is used to provoke SI joint pathology."},{"id": 1525,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The coccyx typically consists of how many fused vertebral segments?","options": [{"key": "A","text": "8-9"},{"key": "B","text": "2-3"},{"key": "C","text": "3-5"},{"key": "D","text": "6-7"}],"correct": "C","explanation": "Coccyx usually consists of 3 to 5 fused rudimentary vertebral segments."},{"id": 1526,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Coccydynia is most commonly caused by which mechanism?","options": [{"key": "A","text": "Shoulder impingement"},{"key": "B","text": "Repetitive overhead activity"},{"key": "C","text": "Cervical disc herniation"},{"key": "D","text": "Direct trauma from fall onto coccyx or childbirth"}],"correct": "D","explanation": "Coccydynia commonly results from direct trauma (fall) or childbirth-related injury to the coccyx."},{"id": 1527,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Nutation of the sacrum (sacral base moving anteriorly/inferiorly) occurs during which phase of gait/activity?","options": [{"key": "A","text": "Hip extension only"},{"key": "B","text": "Trunk flexion and weight-bearing through pelvis"},{"key": "C","text": "Standing on one leg only"},{"key": "D","text": "Trunk extension"}],"correct": "B","explanation": "Sacral nutation typically occurs with trunk flexion and increased load transmission through the pelvis, enhancing SI joint stability (self-locking mechanism)."},{"id": 1528,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "How many pairs of ribs are classified as 'true ribs' attaching directly to the sternum?","options": [{"key": "A","text": "10 pairs"},{"key": "B","text": "5 pairs"},{"key": "C","text": "7 pairs"},{"key": "D","text": "12 pairs"}],"correct": "C","explanation": "Ribs 1-7 are true ribs, attaching directly to the sternum via individual costal cartilages."},{"id": 1529,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Ribs 11 and 12 are classified as which type of ribs?","options": [{"key": "A","text": "False ribs (vertebrochondral)"},{"key": "B","text": "Floating ribs"},{"key": "C","text": "True ribs"},{"key": "D","text": "Atypical true ribs"}],"correct": "B","explanation": "Ribs 11 and 12 are floating ribs as they have no anterior attachment to the sternum or costal cartilage chain."},{"id": 1530,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The diaphragm receives motor innervation from which nerve?","options": [{"key": "A","text": "Intercostal nerves"},{"key": "B","text": "Phrenic nerve (C3-C5)"},{"key": "C","text": "Vagus nerve"},{"key": "D","text": "Thoracodorsal nerve"}],"correct": "B","explanation": "Phrenic nerve, arising from C3-C5, provides sole motor supply to the diaphragm."},{"id": 1531,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "During quiet inspiration, contraction of the diaphragm causes which change in thoracic dimension?","options": [{"key": "A","text": "Decrease in transverse dimension"},{"key": "B","text": "No change in thoracic volume"},{"key": "C","text": "Increase in vertical dimension of thoracic cavity"},{"key": "D","text": "Decrease in vertical dimension"}],"correct": "C","explanation": "Diaphragmatic contraction flattens the dome, increasing the vertical dimension of the thoracic cavity for inspiration."},{"id": 1532,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "External intercostal muscles primarily assist in which respiratory phase?","options": [{"key": "A","text": "Forced expiration"},{"key": "B","text": "Swallowing"},{"key": "C","text": "Quiet expiration only"},{"key": "D","text": "Inspiration (elevating ribs)"}],"correct": "D","explanation": "External intercostals elevate the ribs, assisting inspiration (bucket-handle and pump-handle movements)."},{"id": 1533,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Internal intercostal muscles primarily assist in which respiratory phase?","options": [{"key": "A","text": "Quiet inspiration"},{"key": "B","text": "Forced expiration (depressing ribs)"},{"key": "C","text": "Diaphragmatic breathing only"},{"key": "D","text": "Swallowing"}],"correct": "B","explanation": "Internal intercostals depress the ribs, contributing to forced expiration."},{"id": 1534,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "The sternal angle (angle of Louis) corresponds to which important anatomical landmark?","options": [{"key": "A","text": "Xiphisternal joint"},{"key": "B","text": "T4-T5 disc level only"},{"key": "C","text": "Articulation of 2nd costal cartilage with sternum; level of tracheal bifurcation"},{"key": "D","text": "Level of diaphragm only"}],"correct": "C","explanation": "Sternal angle marks the 2nd rib articulation and approximates the level of tracheal bifurcation (T4-T5)."},{"id": 1535,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Pterion, a clinically important thin region of the skull, overlies which artery?","options": [{"key": "A","text": "Posterior auricular artery"},{"key": "B","text": "Superficial temporal artery"},{"key": "C","text": "Middle meningeal artery"},{"key": "D","text": "Occipital artery"}],"correct": "C","explanation": "Middle meningeal artery runs deep to the pterion and is vulnerable to injury causing epidural hematoma."},{"id": 1536,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Bilateral weakness of sternocleidomastoid most significantly impairs which function?","options": [{"key": "A","text": "Neck flexion against resistance and forced inspiration"},{"key": "B","text": "Lateral flexion only"},{"key": "C","text": "Head rotation only"},{"key": "D","text": "Neck extension"}],"correct": "A","explanation": "Bilateral SCM weakness impairs neck flexion strength and accessory inspiratory function."},{"id": 1537,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Thoracic outlet syndrome caused by scalene muscle hypertrophy most commonly compresses which neurovascular structures?","options": [{"key": "A","text": "Brachial plexus trunks and subclavian artery in the interscalene triangle"},{"key": "B","text": "Internal jugular vein"},{"key": "C","text": "Vertebral artery only"},{"key": "D","text": "Phrenic nerve only"}],"correct": "A","explanation": "Tight/hypertrophied scalenus anterior and medius can compress brachial plexus trunks and subclavian artery in the interscalene triangle."},{"id": 1538,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Greater occipital neuralgia, a cause of cervicogenic headache, involves irritation of a branch from which nerve root?","options": [{"key": "A","text": "C1 dorsal ramus"},{"key": "B","text": "C4 dorsal ramus"},{"key": "C","text": "C6 dorsal ramus"},{"key": "D","text": "C2 dorsal ramus"}],"correct": "D","explanation": "Greater occipital nerve, the medial branch of C2 dorsal ramus, is implicated in occipital neuralgia/cervicogenic headache."},{"id": 1539,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Brown-Sequard syndrome (spinal cord hemisection) produces contralateral loss of which sensory modality below the lesion?","options": [{"key": "A","text": "Fine touch"},{"key": "B","text": "Vibration"},{"key": "C","text": "Pain and temperature"},{"key": "D","text": "Proprioception"}],"correct": "C","explanation": "Contralateral pain/temperature loss occurs due to crossed spinothalamic tract fibers below a hemisection lesion."},{"id": 1540,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "A lesion of the corticospinal tract above the level of decussation in the medulla produces weakness on which side?","options": [{"key": "A","text": "No motor deficit"},{"key": "B","text": "Contralateral side"},{"key": "C","text": "Ipsilateral side"},{"key": "D","text": "Bilateral equally"}],"correct": "B","explanation": "Lesions above the pyramidal decussation cause contralateral weakness since fibers cross in the medulla."},{"id": 1541,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Cauda equina syndrome, presenting with saddle anesthesia and bowel/bladder dysfunction, involves compression of nerve roots below which level?","options": [{"key": "A","text": "S1 only"},{"key": "B","text": "L5 only"},{"key": "C","text": "T12"},{"key": "D","text": "L1-L2 (conus medullaris level)"}],"correct": "D","explanation": "Cauda equina syndrome results from compression of nerve roots below the conus medullaris (around L1-L2)."},{"id": 1542,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which dermatome correlates with sensory loss commonly seen in carpal tunnel syndrome (median nerve)?","options": [{"key": "A","text": "C6"},{"key": "B","text": "C8"},{"key": "C","text": "T1"},{"key": "D","text": "C7"}],"correct": "A","explanation": "Median nerve sensory symptoms in carpal tunnel syndrome typically correspond to C6-C7 dermatomal/median distribution, primarily thumb/index (C6)."},{"id": 1543,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Weakness of ankle dorsiflexion combined with diminished sensation over the dorsum of the foot suggests involvement of which nerve root?","options": [{"key": "A","text": "L3"},{"key": "B","text": "L4"},{"key": "C","text": "S1"},{"key": "D","text": "L5"}],"correct": "D","explanation": "L5 nerve root involvement classically presents with weak dorsiflexion of the great toe/ankle and dorsal foot sensory changes."},{"id": 1544,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Absent ankle jerk reflex combined with weakness of plantarflexion suggests pathology at which nerve root level?","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "S3-S4"},{"key": "C","text": "L4-L5"},{"key": "D","text": "S1-S2"}],"correct": "D","explanation": "S1-S2 nerve root lesions classically present with diminished ankle reflex and plantarflexor weakness."},{"id": 1545,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "A patient with Brown-Sequard syndrome shows ipsilateral spastic paralysis below the lesion due to involvement of which tract?","options": [{"key": "A","text": "Lateral spinothalamic tract"},{"key": "B","text": "Dorsal column tract"},{"key": "C","text": "Lateral corticospinal tract"},{"key": "D","text": "Spinocerebellar tract"}],"correct": "C","explanation": "Ipsilateral motor weakness below a hemisection lesion results from interruption of the lateral corticospinal tract, which has already decussated above."},{"id": 1546,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Quadrilateral space syndrome results from compression of which nerve and artery?","options": [{"key": "A","text": "Axillary nerve and posterior circumflex humeral artery"},{"key": "B","text": "Musculocutaneous nerve and brachial artery"},{"key": "C","text": "Suprascapular nerve and artery"},{"key": "D","text": "Radial nerve and profunda brachii artery"}],"correct": "A","explanation": "Quadrilateral space syndrome involves compression of axillary nerve and posterior circumflex humeral artery."},{"id": 1547,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Guyon's canal syndrome results from compression of which nerve at the wrist?","options": [{"key": "A","text": "Anterior interosseous nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Guyon's canal (ulnar tunnel) syndrome is caused by ulnar nerve compression at the wrist."},{"id": 1548,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Piriformis syndrome classically mimics symptoms of which condition due to sciatic nerve irritation?","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "Meralgia paresthetica"},{"key": "C","text": "Tarsal tunnel syndrome"},{"key": "D","text": "Lumbar disc herniation/sciatica"}],"correct": "D","explanation": "Piriformis syndrome causes sciatica-like symptoms due to sciatic nerve compression/irritation by the piriformis muscle."},{"id": 1549,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Genu valgum deformity places increased stress on which knee compartment and ligament?","options": [{"key": "A","text": "Posterior compartment and PCL"},{"key": "B","text": "Anterior compartment and ACL"},{"key": "C","text": "Lateral compartment and LCL"},{"key": "D","text": "Medial compartment and MCL"}],"correct": "C","explanation": "Genu valgum (knock knee) increases lateral compartment loading and stresses the lateral collateral ligament."},{"id": 1550,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Posterior cruciate ligament injury is classically tested using which special test?","options": [{"key": "A","text": "Valgus stress test"},{"key": "B","text": "McMurray test"},{"key": "C","text": "Posterior drawer test"},{"key": "D","text": "Anterior drawer test"}],"correct": "C","explanation": "Posterior drawer test assesses posterior tibial translation, indicating PCL integrity."},{"id": 1551,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which thoracic spine segment is most commonly associated with Scheuermann's kyphosis due to vertebral wedging?","options": [{"key": "A","text": "Sacral spine"},{"key": "B","text": "Mid-to-lower thoracic spine"},{"key": "C","text": "Lumbar spine"},{"key": "D","text": "Upper cervical spine"}],"correct": "B","explanation": "Scheuermann's disease typically affects the mid-to-lower thoracic vertebrae causing wedge-shaped vertebrae and kyphosis."},{"id": 1552,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Costotransverse joints are formed between ribs and which part of thoracic vertebrae?","options": [{"key": "A","text": "Vertebral body"},{"key": "B","text": "Transverse process"},{"key": "C","text": "Spinous process"},{"key": "D","text": "Lamina"}],"correct": "B","explanation": "Costotransverse joints articulate the rib tubercle with the transverse process of the corresponding thoracic vertebra."},{"id": 1553,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "Which suboccipital muscle, when tight, is implicated in cervicogenic headache via dural connections?","options": [{"key": "A","text": "Scalenus medius"},{"key": "B","text": "Levator scapulae"},{"key": "C","text": "Rectus capitis posterior minor"},{"key": "D","text": "Longus colli"}],"correct": "C","explanation": "Rectus capitis posterior minor has fascial/myodural connections to the spinal dura and is implicated in cervicogenic headache."},{"id": 1554,"subject": "Anatomy","topic": "Mixed Revision","difficulty": "Hard","question": "In central cord syndrome, the corticospinal tract fibers for which body region are most centrally located and thus most affected?","options": [{"key": "A","text": "Face only"},{"key": "B","text": "Lower limb"},{"key": "C","text": "Upper limb"},{"key": "D","text": "Trunk only"}],"correct": "C","explanation": "Upper limb corticospinal fibers are positioned more centrally in the spinal cord, making them most affected in central cord syndrome."},{"id": 1555,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Which type of transport requires ATP directly to move molecules against their concentration gradient?","options": [{"key": "A","text": "Primary active transport"},{"key": "B","text": "Facilitated diffusion"},{"key": "C","text": "Simple diffusion"},{"key": "D","text": "Osmosis"}],"correct": "A","explanation": "Primary active transport uses ATP hydrolysis directly, e.g., Na+-K+ ATPase pump."},{"id": 1556,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Na+-K+ ATPase pump moves how many Na+ ions out and K+ ions in per cycle?","options": [{"key": "A","text": "3 Na+ out, 2 K+ in"},{"key": "B","text": "3 Na+ out, 3 K+ in"},{"key": "C","text": "2 Na+ out, 2 K+ in"},{"key": "D","text": "2 Na+ out, 3 K+ in"}],"correct": "A","explanation": "The pump extrudes 3 Na+ ions and brings in 2 K+ ions per ATP hydrolyzed."},{"id": 1557,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Resting membrane potential of a typical skeletal muscle fiber is approximately:","options": [{"key": "A","text": "-50 mV"},{"key": "B","text": "-30 mV"},{"key": "C","text": "-90 mV"},{"key": "D","text": "0 mV"}],"correct": "C","explanation": "Skeletal muscle RMP is about -90 mV, close to K+ equilibrium potential."},{"id": 1558,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which ion is mainly responsible for establishing the resting membrane potential?","options": [{"key": "A","text": "Potassium"},{"key": "B","text": "Chloride"},{"key": "C","text": "Sodium"},{"key": "D","text": "Calcium"}],"correct": "A","explanation": "High resting membrane permeability to K+ makes it the major determinant of RMP."},{"id": 1559,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The equilibrium potential for an ion is calculated using which equation?","options": [{"key": "A","text": "Starling equation"},{"key": "B","text": "Nernst equation"},{"key": "C","text": "Henderson-Hasselbalch"},{"key": "D","text": "Fick's law"}],"correct": "B","explanation": "Nernst equation calculates the equilibrium potential of an ion across a membrane."},{"id": 1560,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Goldman-Hodgkin-Katz equation accounts for the membrane potential considering:","options": [{"key": "A","text": "Only K+ permeability"},{"key": "B","text": "Only Na+ permeability"},{"key": "C","text": "Only Cl- permeability"},{"key": "D","text": "Permeability of multiple ions simultaneously"}],"correct": "D","explanation": "GHK equation considers relative permeabilities of Na+, K+, and Cl- together."},{"id": 1561,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "During the rising phase of an action potential, membrane permeability increases mainly for:","options": [{"key": "A","text": "Calcium"},{"key": "B","text": "Chloride"},{"key": "C","text": "Potassium"},{"key": "D","text": "Sodium"}],"correct": "D","explanation": "Voltage-gated Na+ channels open rapidly causing depolarization."},{"id": 1562,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "Repolarization of the action potential is primarily due to:","options": [{"key": "A","text": "K+ efflux"},{"key": "B","text": "Ca2+ influx"},{"key": "C","text": "Cl- influx"},{"key": "D","text": "Na+ influx"}],"correct": "A","explanation": "Delayed opening of K+ channels causes efflux of K+, restoring negative potential."},{"id": 1563,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The absolute refractory period corresponds to:","options": [{"key": "A","text": "Time when a stronger stimulus can elicit a response"},{"key": "B","text": "Hyperpolarization phase only"},{"key": "C","text": "Time when no stimulus, however strong, can elicit a new action potential"},{"key": "D","text": "Resting state"}],"correct": "C","explanation": "During absolute refractory period, Na+ channels are inactivated, preventing new AP."},{"id": 1564,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Threshold potential for initiating an action potential in a typical neuron is around:","options": [{"key": "A","text": "-70 mV"},{"key": "B","text": "-30 mV"},{"key": "C","text": "-55 mV"},{"key": "D","text": "-90 mV"}],"correct": "C","explanation": "Threshold is usually around -55 mV in many neurons."},{"id": 1565,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which gate of the voltage-gated Na+ channel closes during the inactivated state?","options": [{"key": "A","text": "Selectivity filter"},{"key": "B","text": "Activation gate (m gate)"},{"key": "C","text": "Inactivation gate (h gate)"},{"key": "D","text": "Both gates open"}],"correct": "C","explanation": "h gate (inactivation gate) closes during inactivated state of Na+ channel."},{"id": 1566,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Hyperpolarization after an action potential is caused by:","options": [{"key": "A","text": "Ca2+ efflux"},{"key": "B","text": "Excess Na+ influx"},{"key": "C","text": "Continued K+ efflux beyond resting level"},{"key": "D","text": "Cl- influx alone"}],"correct": "C","explanation": "Slow closing of K+ channels causes after-hyperpolarization."},{"id": 1567,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Which type of membrane transport does NOT require a carrier protein?","options": [{"key": "A","text": "Facilitated diffusion"},{"key": "B","text": "Simple diffusion"},{"key": "C","text": "Secondary active transport"},{"key": "D","text": "Primary active transport"}],"correct": "B","explanation": "Simple diffusion occurs directly through lipid bilayer or channel without carrier."},{"id": 1568,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Osmosis refers to the movement of:","options": [{"key": "A","text": "Proteins via vesicles"},{"key": "B","text": "Solute particles across membrane"},{"key": "C","text": "Ions via channels"},{"key": "D","text": "Water across a semipermeable membrane along concentration gradient"}],"correct": "D","explanation": "Osmosis is the passive movement of water across a semipermeable membrane."},{"id": 1569,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Which of the following best describes facilitated diffusion?","options": [{"key": "A","text": "Passive transport via carrier proteins down concentration gradient"},{"key": "B","text": "Active transport using ATP"},{"key": "C","text": "Vesicular transport"},{"key": "D","text": "Movement of water only"}],"correct": "A","explanation": "Facilitated diffusion uses carrier/channel proteins without ATP, along the gradient."},{"id": 1570,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "Secondary active transport derives its energy from:","options": [{"key": "A","text": "Direct ATP hydrolysis"},{"key": "B","text": "Electrochemical gradient created by primary active transport"},{"key": "C","text": "Osmotic pressure"},{"key": "D","text": "Hydrostatic pressure"}],"correct": "B","explanation": "Secondary active transport uses gradients (e.g., Na+) established by primary active transport."},{"id": 1571,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "An example of secondary active transport (symport) is:","options": [{"key": "A","text": "Na+-glucose cotransporter (SGLT)"},{"key": "B","text": "Ca2+ ATPase"},{"key": "C","text": "H+-K+ ATPase"},{"key": "D","text": "Na+-K+ ATPase"}],"correct": "A","explanation": "SGLT uses Na+ gradient to co-transport glucose into the cell."},{"id": 1572,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which of the following is an example of an antiport mechanism?","options": [{"key": "A","text": "Na+-glucose cotransport"},{"key": "B","text": "Facilitated glucose transport"},{"key": "C","text": "Na+-K+-2Cl- cotransporter"},{"key": "D","text": "Na+-Ca2+ exchanger"}],"correct": "D","explanation": "Na+-Ca2+ exchanger moves ions in opposite directions, an antiport."},{"id": 1573,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "The phospholipid bilayer of the cell membrane is best described as:","options": [{"key": "A","text": "Fluid mosaic"},{"key": "B","text": "Solid crystalline"},{"key": "C","text": "Rigid and static"},{"key": "D","text": "Purely protein-based"}],"correct": "A","explanation": "Singer-Nicolson fluid mosaic model describes the membrane structure."},{"id": 1574,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Integral membrane proteins differ from peripheral proteins in that they:","options": [{"key": "A","text": "Span the lipid bilayer"},{"key": "B","text": "Never function as channels"},{"key": "C","text": "Are loosely attached to membrane surface"},{"key": "D","text": "Are found only outside the cell"}],"correct": "A","explanation": "Integral proteins are embedded within or span the lipid bilayer."},{"id": 1575,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Which transport process involves engulfing extracellular fluid via membrane invagination?","options": [{"key": "A","text": "Pinocytosis"},{"key": "B","text": "Diffusion"},{"key": "C","text": "Phagocytosis"},{"key": "D","text": "Exocytosis"}],"correct": "A","explanation": "Pinocytosis is 'cell drinking', uptake of fluid via vesicle formation."},{"id": 1576,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Phagocytosis is primarily carried out by which cells?","options": [{"key": "A","text": "Hepatocytes"},{"key": "B","text": "Erythrocytes"},{"key": "C","text": "Neutrophils and macrophages"},{"key": "D","text": "Platelets"}],"correct": "C","explanation": "Neutrophils and macrophages engulf large particles like bacteria via phagocytosis."},{"id": 1577,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Exocytosis is the process by which:","options": [{"key": "A","text": "Ions diffuse passively"},{"key": "B","text": "Intracellular vesicles fuse with membrane to release contents"},{"key": "C","text": "Cell engulfs extracellular material"},{"key": "D","text": "Water moves out of the cell"}],"correct": "B","explanation": "Exocytosis releases vesicle contents to the exterior by membrane fusion."},{"id": 1578,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Which law governs the rate of diffusion of a substance across a membrane?","options": [{"key": "A","text": "Ohm's law"},{"key": "B","text": "Fick's law of diffusion"},{"key": "C","text": "Boyle's law"},{"key": "D","text": "Starling's law"}],"correct": "B","explanation": "Fick's law states diffusion rate is proportional to concentration gradient and area."},{"id": 1579,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "According to Fick's law, the rate of diffusion is inversely proportional to:","options": [{"key": "A","text": "Concentration gradient"},{"key": "B","text": "Membrane thickness"},{"key": "C","text": "Diffusion coefficient"},{"key": "D","text": "Surface area"}],"correct": "B","explanation": "Thicker membranes slow diffusion rate, an inverse relationship."},{"id": 1580,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Tonicity of a solution refers to its effect on:","options": [{"key": "A","text": "Cell volume due to osmotic water movement"},{"key": "B","text": "Membrane potential"},{"key": "C","text": "Cell pH"},{"key": "D","text": "Protein synthesis"}],"correct": "A","explanation": "Tonicity describes how a solution affects cell volume via osmosis."},{"id": 1581,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "A red blood cell placed in a hypotonic solution will:","options": [{"key": "A","text": "Remain unchanged"},{"key": "B","text": "Become rigid"},{"key": "C","text": "Swell and may lyse"},{"key": "D","text": "Shrink (crenate)"}],"correct": "C","explanation": "Hypotonic solution causes water influx into RBC causing swelling/lysis."},{"id": 1582,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "A red blood cell placed in a hypertonic solution will:","options": [{"key": "A","text": "Remain unchanged"},{"key": "B","text": "Swell and lyse"},{"key": "C","text": "Undergo mitosis"},{"key": "D","text": "Shrink (crenate)"}],"correct": "D","explanation": "Hypertonic solution draws water out of RBC, causing crenation."},{"id": 1583,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Isotonic solution has the same effective osmotic pressure as:","options": [{"key": "A","text": "Distilled water"},{"key": "B","text": "Plasma/intracellular fluid"},{"key": "C","text": "Hypertonic saline"},{"key": "D","text": "Pure glucose solution"}],"correct": "B","explanation": "Isotonic solutions match plasma osmolarity, causing no net water shift."},{"id": 1584,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal osmolarity of human plasma is approximately:","options": [{"key": "A","text": "500 mOsm/L"},{"key": "B","text": "100 mOsm/L"},{"key": "C","text": "300 mOsm/L (285-295)"},{"key": "D","text": "200 mOsm/L"}],"correct": "C","explanation": "Plasma osmolarity normally ranges around 285-295 mOsm/L."},{"id": 1585,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which of the following channels is voltage-gated and responsible for rapid depolarization in nerve cells?","options": [{"key": "A","text": "Voltage-gated Na+ channel"},{"key": "B","text": "K+ leak channel"},{"key": "C","text": "Aquaporin"},{"key": "D","text": "Ligand-gated Cl- channel"}],"correct": "A","explanation": "Voltage-gated Na+ channels open upon depolarization, driving the AP upstroke."},{"id": 1586,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Saltatory conduction occurs in:","options": [{"key": "A","text": "Myelinated nerve fibers, jumping between nodes of Ranvier"},{"key": "B","text": "Unmyelinated nerve fibers"},{"key": "C","text": "Cardiac muscle only"},{"key": "D","text": "Smooth muscle only"}],"correct": "A","explanation": "Myelination allows AP to jump between nodes of Ranvier, speeding conduction."},{"id": 1587,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Conduction velocity of a nerve fiber is directly related to:","options": [{"key": "A","text": "Cell shape"},{"key": "B","text": "Fiber diameter and myelination"},{"key": "C","text": "Extracellular Na+ concentration only"},{"key": "D","text": "Resting membrane potential only"}],"correct": "B","explanation": "Larger diameter and myelination both increase conduction velocity."},{"id": 1588,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which homeostatic mechanism best exemplifies a negative feedback loop?","options": [{"key": "A","text": "Childbirth labor contractions"},{"key": "B","text": "Action potential generation"},{"key": "C","text": "Blood clotting cascade"},{"key": "D","text": "Regulation of blood glucose by insulin and glucagon"}],"correct": "D","explanation": "Insulin/glucagon maintain blood glucose within a narrow range via negative feedback."},{"id": 1589,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which of the following is a classic example of positive feedback in physiology?","options": [{"key": "A","text": "Blood pressure regulation via baroreceptors"},{"key": "B","text": "Oxytocin release during labor"},{"key": "C","text": "Thermoregulation"},{"key": "D","text": "Osmoregulation by ADH"}],"correct": "B","explanation": "Oxytocin enhances uterine contractions in a self-amplifying positive feedback loop."},{"id": 1590,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The set point in a homeostatic control system refers to:","options": [{"key": "A","text": "Feedback loop start time"},{"key": "B","text": "Sensory receptor location"},{"key": "C","text": "The desired/normal physiological value being maintained"},{"key": "D","text": "The maximum value an effector can produce"}],"correct": "C","explanation": "Set point is the target/normal value the system regulates around."},{"id": 1591,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which component of a feedback system detects deviations from the set point?","options": [{"key": "A","text": "Integrator only"},{"key": "B","text": "Hormone"},{"key": "C","text": "Effector"},{"key": "D","text": "Receptor/sensor"}],"correct": "D","explanation": "Receptors/sensors detect change and relay information to the control center."},{"id": 1592,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The 'milieu interieur' concept, fundamental to homeostasis, was proposed by:","options": [{"key": "A","text": "Otto Loewi"},{"key": "B","text": "Claude Bernard"},{"key": "C","text": "Ernest Starling"},{"key": "D","text": "Walter Cannon"}],"correct": "B","explanation": "Claude Bernard introduced the concept of constancy of the internal environment."},{"id": 1593,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The term 'homeostasis' was coined by:","options": [{"key": "A","text": "Arthur Guyton"},{"key": "B","text": "Walter Cannon"},{"key": "C","text": "Claude Bernard"},{"key": "D","text": "Ivan Pavlov"}],"correct": "B","explanation": "Walter Cannon coined the term homeostasis in the early 20th century."},{"id": 1594,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Aquaporins are membrane channels specifically permeable to:","options": [{"key": "A","text": "Amino acids"},{"key": "B","text": "Glucose"},{"key": "C","text": "Sodium ions"},{"key": "D","text": "Water"}],"correct": "D","explanation": "Aquaporins are water channel proteins facilitating rapid water transport."},{"id": 1595,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "GLUT4 transporter, responsible for insulin-mediated glucose uptake, is mainly found in:","options": [{"key": "A","text": "Liver only"},{"key": "B","text": "Renal tubules only"},{"key": "C","text": "Pancreatic beta cells"},{"key": "D","text": "Skeletal muscle and adipose tissue"}],"correct": "D","explanation": "GLUT4 is insulin-sensitive and present mainly in muscle and fat tissue."},{"id": 1596,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Which of the following best describes the sodium equilibrium potential (ENa) in a typical neuron?","options": [{"key": "A","text": "Around -55 mV"},{"key": "B","text": "Around +60 mV"},{"key": "C","text": "Around 0 mV"},{"key": "D","text": "Around -90 mV"}],"correct": "B","explanation": "ENa is approximately +60 mV due to high extracellular Na+ concentration."},{"id": 1597,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The chloride equilibrium potential in most neurons is close to:","options": [{"key": "A","text": "0 mV"},{"key": "B","text": "+30 mV"},{"key": "C","text": "+60 mV"},{"key": "D","text": "RMP (around -70 to -90 mV)"}],"correct": "D","explanation": "ECl is close to resting membrane potential in most neurons."},{"id": 1598,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "All-or-none law of action potential states that:","options": [{"key": "A","text": "Once threshold is reached, AP amplitude is constant regardless of stimulus strength"},{"key": "B","text": "Amplitude varies with stimulus strength"},{"key": "C","text": "AP can be partially generated"},{"key": "D","text": "Subthreshold stimuli also produce full AP"}],"correct": "A","explanation": "Action potentials fire fully or not at all once threshold is crossed."},{"id": 1599,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Local anesthetics like lidocaine act primarily by blocking:","options": [{"key": "A","text": "Voltage-gated Na+ channels"},{"key": "B","text": "Cl- channels"},{"key": "C","text": "Voltage-gated K+ channels"},{"key": "D","text": "Ca2+ channels"}],"correct": "A","explanation": "Local anesthetics block Na+ channels, preventing depolarization and AP propagation."},{"id": 1600,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Tetrodotoxin (TTX) selectively blocks which channel?","options": [{"key": "A","text": "Ca2+ channel"},{"key": "B","text": "Cl- channel"},{"key": "C","text": "Voltage-gated Na+ channel"},{"key": "D","text": "K+ channel"}],"correct": "C","explanation": "TTX is a potent and selective blocker of voltage-gated Na+ channels."},{"id": 1601,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which ion channel blocker is commonly used experimentally to study pure Na+ currents by blocking K+ channels?","options": [{"key": "A","text": "Tetrodotoxin"},{"key": "B","text": "Tetraethylammonium (TEA)"},{"key": "C","text": "Verapamil"},{"key": "D","text": "Ouabain"}],"correct": "B","explanation": "TEA selectively blocks voltage-gated K+ channels."},{"id": 1602,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Ouabain is a specific inhibitor of:","options": [{"key": "A","text": "Ca2+ ATPase"},{"key": "B","text": "SERCA pump"},{"key": "C","text": "Na+-K+ ATPase"},{"key": "D","text": "H+-K+ ATPase"}],"correct": "C","explanation": "Ouabain is a cardiac glycoside that inhibits the Na+-K+ ATPase pump."},{"id": 1603,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The relative refractory period is characterized by:","options": [{"key": "A","text": "No response to any stimulus"},{"key": "B","text": "Maximum excitability"},{"key": "C","text": "A stronger-than-normal stimulus can elicit another action potential"},{"key": "D","text": "Complete inactivation of all channels"}],"correct": "C","explanation": "During relative refractory period, threshold is elevated but AP can still occur."},{"id": 1604,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Which transport mechanism is responsible for glucose reabsorption coupled to Na+ in renal proximal tubule?","options": [{"key": "A","text": "Primary active transport"},{"key": "B","text": "Secondary active transport (SGLT)"},{"key": "C","text": "Simple diffusion"},{"key": "D","text": "Osmosis"}],"correct": "B","explanation": "SGLT cotransports glucose with Na+ down its electrochemical gradient."},{"id": 1605,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "The cell membrane's selective permeability is mainly attributed to:","options": [{"key": "A","text": "Cytoskeleton"},{"key": "B","text": "Glycocalyx only"},{"key": "C","text": "Lipid bilayer with embedded transport proteins"},{"key": "D","text": "Cholesterol alone"}],"correct": "C","explanation": "Lipid bilayer with specific channel/carrier proteins regulates selective permeability."},{"id": 1606,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which of the following increases membrane fluidity?","options": [{"key": "A","text": "Low temperature"},{"key": "B","text": "Saturated fatty acid chains"},{"key": "C","text": "High cholesterol content"},{"key": "D","text": "Unsaturated fatty acid chains"}],"correct": "D","explanation": "Unsaturated fatty acids introduce kinks that increase membrane fluidity."},{"id": 1607,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which feedback mechanism controls body temperature via hypothalamic thermoregulatory center?","options": [{"key": "A","text": "Positive feedback"},{"key": "B","text": "Negative feedback"},{"key": "C","text": "Feed-forward only"},{"key": "D","text": "No feedback"}],"correct": "B","explanation": "Body temperature is regulated through a negative feedback loop centered in hypothalamus."},{"id": 1608,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In feed-forward regulation, the response occurs:","options": [{"key": "A","text": "Randomly"},{"key": "B","text": "After the disturbance has already occurred"},{"key": "C","text": "In anticipation of a change before it occurs"},{"key": "D","text": "Only during sleep"}],"correct": "C","explanation": "Feed-forward control anticipates changes and prepares the body in advance."},{"id": 1609,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Down-regulation of receptors typically occurs in response to:","options": [{"key": "A","text": "Chronic low hormone levels"},{"key": "B","text": "Receptor mutation only"},{"key": "C","text": "Chronically elevated hormone levels"},{"key": "D","text": "Acute hormone deficiency"}],"correct": "C","explanation": "Persistently high hormone levels cause receptor down-regulation to reduce sensitivity."},{"id": 1610,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Which of the following best defines 'permissive action' of a hormone in homeostasis?","options": [{"key": "A","text": "A hormone directly causes an effect"},{"key": "B","text": "A hormone enables another hormone to exert its full effect"},{"key": "C","text": "A hormone antagonizes another hormone"},{"key": "D","text": "A hormone has no physiological role"}],"correct": "B","explanation": "Permissive action means one hormone must be present for another to act fully (e.g., cortisol permits catecholamine action)."},{"id": 1611,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "The lipid bilayer's hydrophobic interior primarily restricts the passive diffusion of:","options": [{"key": "A","text": "Oxygen and carbon dioxide"},{"key": "B","text": "Lipid-soluble gases"},{"key": "C","text": "Charged ions and polar molecules"},{"key": "D","text": "Steroid hormones"}],"correct": "C","explanation": "Polar/charged molecules cannot easily cross the hydrophobic lipid core without channels."},{"id": 1612,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which membrane potential phase is associated with the absolute refractory period coinciding mainly with:","options": [{"key": "A","text": "Resting phase"},{"key": "B","text": "Depolarization and early repolarization (Na+ channel inactivation)"},{"key": "C","text": "Hyperpolarization only"},{"key": "D","text": "After potential only"}],"correct": "B","explanation": "Na+ channel inactivation during depolarization/early repolarization underlies absolute refractoriness."},{"id": 1613,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Chvostek's sign, related to altered membrane excitability, is associated with which electrolyte abnormality?","options": [{"key": "A","text": "Hyperkalemia"},{"key": "B","text": "Hypernatremia"},{"key": "C","text": "Hypocalcemia"},{"key": "D","text": "Hyperchloremia"}],"correct": "C","explanation": "Hypocalcemia increases neuromuscular excitability, producing Chvostek's sign."},{"id": 1614,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hyperkalemia affects the resting membrane potential by:","options": [{"key": "A","text": "Depolarizing the membrane (less negative RMP)"},{"key": "B","text": "Increasing K+ equilibrium potential negativity"},{"key": "C","text": "Hyperpolarizing the membrane"},{"key": "D","text": "No effect on RMP"}],"correct": "A","explanation": "Elevated extracellular K+ reduces the K+ gradient, depolarizing the resting membrane."},{"id": 1615,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal hemoglobin concentration in an adult male is approximately:","options": [{"key": "A","text": "18-22 g/dL"},{"key": "B","text": "9-11 g/dL"},{"key": "C","text": "6-8 g/dL"},{"key": "D","text": "13-17 g/dL"}],"correct": "D","explanation": "Normal Hb in adult males ranges around 13-17 g/dL."},{"id": 1616,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal hemoglobin concentration in an adult female is approximately:","options": [{"key": "A","text": "16-20 g/dL"},{"key": "B","text": "9-10 g/dL"},{"key": "C","text": "12-15 g/dL"},{"key": "D","text": "20-22 g/dL"}],"correct": "C","explanation": "Adult female normal Hb range is about 12-15 g/dL."},{"id": 1617,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "The lifespan of a normal red blood cell is approximately:","options": [{"key": "A","text": "60 days"},{"key": "B","text": "30 days"},{"key": "C","text": "120 days"},{"key": "D","text": "200 days"}],"correct": "C","explanation": "RBCs live approximately 120 days in circulation before destruction."},{"id": 1618,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Erythropoiesis is primarily stimulated by which hormone?","options": [{"key": "A","text": "Aldosterone"},{"key": "B","text": "Cortisol"},{"key": "C","text": "Thrombopoietin"},{"key": "D","text": "Erythropoietin"}],"correct": "D","explanation": "Erythropoietin, mainly from kidney, stimulates RBC production in bone marrow."},{"id": 1619,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Erythropoietin is mainly produced by which organ?","options": [{"key": "A","text": "Kidney (peritubular cells)"},{"key": "B","text": "Liver"},{"key": "C","text": "Bone marrow"},{"key": "D","text": "Spleen"}],"correct": "A","explanation": "Kidneys produce about 90% of erythropoietin in response to hypoxia."},{"id": 1620,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which vitamin deficiency leads to megaloblastic anemia due to impaired DNA synthesis?","options": [{"key": "A","text": "Vitamin K"},{"key": "B","text": "Vitamin D"},{"key": "C","text": "Vitamin C"},{"key": "D","text": "Vitamin B12/Folate"}],"correct": "D","explanation": "B12 and folate deficiency impair DNA synthesis causing megaloblastic anemia."},{"id": 1621,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Intrinsic factor required for vitamin B12 absorption is secreted by:","options": [{"key": "A","text": "Parietal cells of stomach"},{"key": "B","text": "Hepatocytes"},{"key": "C","text": "Pancreatic acinar cells"},{"key": "D","text": "Chief cells of stomach"}],"correct": "A","explanation": "Gastric parietal cells secrete both HCl and intrinsic factor."},{"id": 1622,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Iron deficiency anemia is characterized by which type of red blood cells?","options": [{"key": "A","text": "Macrocytic normochromic"},{"key": "B","text": "Microcytic hypochromic"},{"key": "C","text": "Macrocytic hyperchromic"},{"key": "D","text": "Normocytic normochromic"}],"correct": "B","explanation": "Iron deficiency causes small, pale RBCs - microcytic hypochromic anemia."},{"id": 1623,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The site of RBC destruction (extravascular hemolysis) is mainly:","options": [{"key": "A","text": "Bone marrow"},{"key": "B","text": "Liver"},{"key": "C","text": "Kidney"},{"key": "D","text": "Spleen"}],"correct": "D","explanation": "Spleen is the primary site for removal of old/damaged RBCs."},{"id": 1624,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Globin chains of adult hemoglobin (HbA) consist of:","options": [{"key": "A","text": "2 alpha and 2 beta chains"},{"key": "B","text": "4 alpha chains"},{"key": "C","text": "4 beta chains"},{"key": "D","text": "2 alpha and 2 gamma chains"}],"correct": "A","explanation": "HbA is composed of 2 alpha and 2 beta globin chains."},{"id": 1625,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Fetal hemoglobin (HbF) is composed of:","options": [{"key": "A","text": "2 alpha and 2 beta chains"},{"key": "B","text": "4 gamma chains"},{"key": "C","text": "2 alpha and 2 delta chains"},{"key": "D","text": "2 alpha and 2 gamma chains"}],"correct": "D","explanation": "HbF consists of 2 alpha and 2 gamma chains, has higher O2 affinity."},{"id": 1626,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "Each hemoglobin molecule can bind a maximum of how many oxygen molecules?","options": [{"key": "A","text": "2"},{"key": "B","text": "4"},{"key": "C","text": "8"},{"key": "D","text": "1"}],"correct": "B","explanation": "Hemoglobin has 4 heme groups, each binding one O2 molecule."},{"id": 1627,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Iron in hemoglobin is normally present in which form for oxygen binding?","options": [{"key": "A","text": "Fe0 (elemental)"},{"key": "B","text": "Fe4+"},{"key": "C","text": "Fe3+ (ferric)"},{"key": "D","text": "Fe2+ (ferrous)"}],"correct": "D","explanation": "Functional hemoglobin contains iron in ferrous (Fe2+) state."},{"id": 1628,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Methemoglobin differs from normal hemoglobin in that iron is in which state?","options": [{"key": "A","text": "Fe3+"},{"key": "B","text": "Fe2+"},{"key": "C","text": "No iron present"},{"key": "D","text": "Fe0"}],"correct": "A","explanation": "Methemoglobin has iron oxidized to ferric (Fe3+) state, unable to bind O2."},{"id": 1629,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which test is used to measure the percentage of RBC volume in whole blood?","options": [{"key": "A","text": "Bleeding time"},{"key": "B","text": "Reticulocyte count"},{"key": "C","text": "Hematocrit (PCV)"},{"key": "D","text": "ESR"}],"correct": "C","explanation": "Hematocrit/PCV measures the proportion of blood volume occupied by RBCs."},{"id": 1630,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal hematocrit value in adult males is approximately:","options": [{"key": "A","text": "65-70%"},{"key": "B","text": "40-50%"},{"key": "C","text": "25-30%"},{"key": "D","text": "55-60%"}],"correct": "B","explanation": "Normal hematocrit in adult males ranges from about 40-50%."},{"id": 1631,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Reticulocytes are:","options": [{"key": "A","text": "Immature RBCs released from bone marrow"},{"key": "B","text": "Mature RBCs"},{"key": "C","text": "Platelet precursors"},{"key": "D","text": "White blood cells"}],"correct": "A","explanation": "Reticulocytes are young RBCs with residual RNA, indicating marrow activity."},{"id": 1632,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal reticulocyte count in peripheral blood is approximately:","options": [{"key": "A","text": "0.5-1.5%"},{"key": "B","text": "5-10%"},{"key": "C","text": "15-20%"},{"key": "D","text": "25-30%"}],"correct": "A","explanation": "Normal reticulocyte percentage is roughly 0.5-1.5% of total RBCs."},{"id": 1633,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "Which cell is the precursor of erythrocytes in bone marrow that loses its nucleus before entering circulation?","options": [{"key": "A","text": "Promyelocyte"},{"key": "B","text": "Reticulocyte/Normoblast"},{"key": "C","text": "Megakaryocyte"},{"key": "D","text": "Myeloblast"}],"correct": "B","explanation": "Normoblasts mature into reticulocytes, extruding the nucleus before release."},{"id": 1634,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Erythrocyte sedimentation rate (ESR) is increased in which condition?","options": [{"key": "A","text": "Inflammation/infection"},{"key": "B","text": "Spherocytosis"},{"key": "C","text": "Sickle cell anemia"},{"key": "D","text": "Polycythemia"}],"correct": "A","explanation": "ESR rises in inflammatory states due to increased fibrinogen and globulins."},{"id": 1635,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal total leukocyte count (WBC count) in adults is approximately:","options": [{"key": "A","text": "25,000-30,000/µL"},{"key": "B","text": "1,000-3,000/µL"},{"key": "C","text": "4,000-11,000/µL"},{"key": "D","text": "15,000-20,000/µL"}],"correct": "C","explanation": "Normal WBC count ranges from about 4,000-11,000 cells per microliter."},{"id": 1636,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Most abundant type of white blood cell in normal peripheral blood is:","options": [{"key": "A","text": "Monocytes"},{"key": "B","text": "Neutrophils"},{"key": "C","text": "Lymphocytes"},{"key": "D","text": "Eosinophils"}],"correct": "B","explanation": "Neutrophils typically constitute 50-70% of total WBCs."},{"id": 1637,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which WBC type increases characteristically in parasitic infections and allergic reactions?","options": [{"key": "A","text": "Eosinophils"},{"key": "B","text": "Monocytes"},{"key": "C","text": "Neutrophils"},{"key": "D","text": "Basophils"}],"correct": "A","explanation": "Eosinophils rise in parasitic infestations and allergic/hypersensitivity reactions."},{"id": 1638,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "Which white blood cell is responsible for releasing histamine and heparin, similar to mast cells?","options": [{"key": "A","text": "Lymphocyte"},{"key": "B","text": "Neutrophil"},{"key": "C","text": "Basophil"},{"key": "D","text": "Monocyte"}],"correct": "C","explanation": "Basophils contain granules with histamine and heparin like tissue mast cells."},{"id": 1639,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Monocytes differentiate into which cells upon entering tissues?","options": [{"key": "A","text": "Platelets"},{"key": "B","text": "Neutrophils"},{"key": "C","text": "Lymphocytes"},{"key": "D","text": "Macrophages"}],"correct": "D","explanation": "Monocytes migrate into tissues and differentiate into macrophages."},{"id": 1640,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "B lymphocytes primarily mediate which type of immunity?","options": [{"key": "A","text": "Humoral (antibody-mediated) immunity"},{"key": "B","text": "Cell-mediated immunity"},{"key": "C","text": "Innate immunity only"},{"key": "D","text": "Phagocytosis"}],"correct": "A","explanation": "B lymphocytes differentiate into plasma cells that produce antibodies."},{"id": 1641,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "T lymphocytes are primarily responsible for:","options": [{"key": "A","text": "Cell-mediated immunity"},{"key": "B","text": "Histamine release"},{"key": "C","text": "Phagocytosis of bacteria"},{"key": "D","text": "Antibody production"}],"correct": "A","explanation": "T cells mediate cellular immunity, including cytotoxic and helper functions."},{"id": 1642,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Neutrophilia (increased neutrophils) is most commonly associated with:","options": [{"key": "A","text": "Viral infections"},{"key": "B","text": "Allergic reactions"},{"key": "C","text": "Parasitic infections"},{"key": "D","text": "Acute bacterial infections"}],"correct": "D","explanation": "Acute bacterial infections typically cause a rise in neutrophil count."},{"id": 1643,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Lymphocytosis (increased lymphocytes) is characteristically seen in:","options": [{"key": "A","text": "Acute hemorrhage"},{"key": "B","text": "Allergic reactions"},{"key": "C","text": "Viral infections"},{"key": "D","text": "Acute bacterial infection"}],"correct": "C","explanation": "Viral infections commonly cause a relative or absolute lymphocytosis."},{"id": 1644,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal platelet count in peripheral blood is approximately:","options": [{"key": "A","text": "500,000-700,000/µL"},{"key": "B","text": "1,000,000/µL"},{"key": "C","text": "50,000-100,000/µL"},{"key": "D","text": "150,000-450,000/µL"}],"correct": "D","explanation": "Normal platelet count ranges from 150,000 to 450,000 per microliter."},{"id": 1645,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Platelets are derived from which bone marrow precursor cell?","options": [{"key": "A","text": "Myeloblast"},{"key": "B","text": "Proerythroblast"},{"key": "C","text": "Lymphoblast"},{"key": "D","text": "Megakaryocyte"}],"correct": "D","explanation": "Megakaryocytes fragment their cytoplasm to release platelets."},{"id": 1646,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "The hormone primarily responsible for stimulating platelet production is:","options": [{"key": "A","text": "Erythropoietin"},{"key": "B","text": "Interleukin-2"},{"key": "C","text": "Thrombopoietin"},{"key": "D","text": "Granulocyte colony-stimulating factor"}],"correct": "C","explanation": "Thrombopoietin, mainly from liver, regulates megakaryocyte and platelet production."},{"id": 1647,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Primary hemostasis mainly refers to:","options": [{"key": "A","text": "Clot retraction"},{"key": "B","text": "Formation of fibrin clot"},{"key": "C","text": "Fibrinolysis"},{"key": "D","text": "Platelet plug formation"}],"correct": "D","explanation": "Primary hemostasis involves vascular spasm and platelet plug formation."},{"id": 1648,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which step initiates platelet adhesion to exposed subendothelial collagen?","options": [{"key": "A","text": "Von Willebrand factor binding to platelet GPIb receptor"},{"key": "B","text": "Thrombin activation"},{"key": "C","text": "Vitamin K activation"},{"key": "D","text": "Fibrinogen binding"}],"correct": "A","explanation": "vWF bridges platelet GPIb receptors to exposed collagen, initiating adhesion."},{"id": 1649,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Platelet aggregation is mediated mainly via which receptor binding fibrinogen?","options": [{"key": "A","text": "Thrombin receptor only"},{"key": "B","text": "GPIa"},{"key": "C","text": "GPIb"},{"key": "D","text": "GPIIb/IIIa"}],"correct": "D","explanation": "Activated GPIIb/IIIa receptors bind fibrinogen, linking platelets together."},{"id": 1650,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The extrinsic pathway of coagulation is initiated by:","options": [{"key": "A","text": "Calcium alone"},{"key": "B","text": "Tissue factor (Factor III) release"},{"key": "C","text": "Factor XII activation"},{"key": "D","text": "Platelet activation alone"}],"correct": "B","explanation": "Tissue factor released from damaged tissue initiates the extrinsic pathway via Factor VII."},{"id": 1651,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The intrinsic pathway of coagulation is initiated by contact activation of:","options": [{"key": "A","text": "Factor VII"},{"key": "B","text": "Factor V"},{"key": "C","text": "Factor XII"},{"key": "D","text": "Factor X"}],"correct": "C","explanation": "Intrinsic pathway begins with contact activation of Factor XII (Hageman factor)."},{"id": 1652,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The common pathway of coagulation begins with activation of:","options": [{"key": "A","text": "Factor XIII"},{"key": "B","text": "Factor X"},{"key": "C","text": "Factor VII"},{"key": "D","text": "Factor XII"}],"correct": "B","explanation": "Both pathways converge to activate Factor X, starting the common pathway."},{"id": 1653,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which factor converts fibrinogen to fibrin?","options": [{"key": "A","text": "Thrombin (Factor IIa)"},{"key": "B","text": "Factor X"},{"key": "C","text": "Factor XII"},{"key": "D","text": "Factor V"}],"correct": "A","explanation": "Thrombin cleaves fibrinogen into fibrin monomers, forming the clot mesh."},{"id": 1654,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Factor XIII is responsible for:","options": [{"key": "A","text": "Initiating intrinsic pathway"},{"key": "B","text": "Cross-linking and stabilizing fibrin clot"},{"key": "C","text": "Inhibiting clot formation"},{"key": "D","text": "Activating prothrombin"}],"correct": "B","explanation": "Factor XIII (fibrin-stabilizing factor) cross-links fibrin strands for stability."},{"id": 1655,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Vitamin K is essential for synthesis of which clotting factors?","options": [{"key": "A","text": "Factor XIII only"},{"key": "B","text": "Factors XI, XII"},{"key": "C","text": "Factors V, VIII"},{"key": "D","text": "Factors II, VII, IX, X"}],"correct": "D","explanation": "Vitamin K is required for carboxylation of factors II, VII, IX, and X."},{"id": 1656,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Hemophilia A is due to deficiency of which clotting factor?","options": [{"key": "A","text": "Factor IX"},{"key": "B","text": "Factor VII"},{"key": "C","text": "Factor XI"},{"key": "D","text": "Factor VIII"}],"correct": "D","explanation": "Hemophilia A results from deficiency of Factor VIII (antihemophilic factor)."},{"id": 1657,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hemophilia B is due to deficiency of which clotting factor?","options": [{"key": "A","text": "Factor X"},{"key": "B","text": "Factor IX"},{"key": "C","text": "Factor XII"},{"key": "D","text": "Factor VIII"}],"correct": "B","explanation": "Hemophilia B (Christmas disease) is caused by Factor IX deficiency."},{"id": 1658,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which clotting test primarily evaluates the extrinsic and common pathways?","options": [{"key": "A","text": "Activated Partial Thromboplastin Time (aPTT)"},{"key": "B","text": "Platelet count"},{"key": "C","text": "Prothrombin Time (PT)"},{"key": "D","text": "Bleeding time"}],"correct": "C","explanation": "PT assesses extrinsic pathway (Factor VII) and common pathway function."},{"id": 1659,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which clotting test primarily evaluates the intrinsic and common pathways?","options": [{"key": "A","text": "Prothrombin time"},{"key": "B","text": "Bleeding time"},{"key": "C","text": "INR"},{"key": "D","text": "Activated Partial Thromboplastin Time (aPTT)"}],"correct": "D","explanation": "aPTT evaluates intrinsic pathway factors (VIII, IX, XI, XII) and common pathway."},{"id": 1660,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Warfarin, an anticoagulant, acts by inhibiting:","options": [{"key": "A","text": "Platelet aggregation"},{"key": "B","text": "Thrombin directly"},{"key": "C","text": "Vitamin K epoxide reductase"},{"key": "D","text": "Factor XIII"}],"correct": "C","explanation": "Warfarin blocks vitamin K recycling, reducing synthesis of factors II, VII, IX, X."},{"id": 1661,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Heparin acts as an anticoagulant primarily by potentiating the action of:","options": [{"key": "A","text": "Antithrombin III"},{"key": "B","text": "Protein C"},{"key": "C","text": "Plasmin"},{"key": "D","text": "Vitamin K"}],"correct": "A","explanation": "Heparin enhances antithrombin III activity, inactivating thrombin and Factor Xa."},{"id": 1662,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Plasmin, responsible for clot breakdown (fibrinolysis), is formed from:","options": [{"key": "A","text": "Fibrinogen"},{"key": "B","text": "Plasminogen"},{"key": "C","text": "Protein C"},{"key": "D","text": "Prothrombin"}],"correct": "B","explanation": "Plasminogen is converted to active plasmin, which degrades fibrin clots."},{"id": 1663,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Tissue plasminogen activator (tPA) is used clinically to:","options": [{"key": "A","text": "Dissolve existing clots (thrombolysis)"},{"key": "B","text": "Increase platelet count"},{"key": "C","text": "Stop bleeding"},{"key": "D","text": "Promote clotting"}],"correct": "A","explanation": "tPA activates plasminogen to plasmin, used therapeutically to dissolve clots."},{"id": 1664,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "ABO blood grouping is based on the presence of which substances on RBC surface?","options": [{"key": "A","text": "A and B antigens (agglutinogens)"},{"key": "B","text": "HLA antigens"},{"key": "C","text": "Platelet antigens"},{"key": "D","text": "Rh antigens"}],"correct": "A","explanation": "ABO system is determined by presence/absence of A and B surface antigens."},{"id": 1665,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A person with blood group AB is considered the universal:","options": [{"key": "A","text": "Donor"},{"key": "B","text": "Neither donor nor recipient"},{"key": "C","text": "Both donor and recipient equally"},{"key": "D","text": "Recipient"}],"correct": "D","explanation": "AB individuals lack anti-A and anti-B antibodies, making them universal recipients."},{"id": 1666,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A person with blood group O is considered the universal:","options": [{"key": "A","text": "Neither"},{"key": "B","text": "Both equally"},{"key": "C","text": "Donor"},{"key": "D","text": "Recipient"}],"correct": "C","explanation": "O group RBCs lack A and B antigens, making them universal donors."},{"id": 1667,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Blood group O individuals have which antibodies in their plasma?","options": [{"key": "A","text": "Anti-B only"},{"key": "B","text": "No antibodies"},{"key": "C","text": "Both anti-A and anti-B antibodies"},{"key": "D","text": "Anti-A only"}],"correct": "C","explanation": "O group plasma contains both anti-A and anti-B antibodies naturally."},{"id": 1668,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Rh incompatibility between an Rh-negative mother and Rh-positive fetus can cause:","options": [{"key": "A","text": "Sickle cell disease"},{"key": "B","text": "Hemophilia"},{"key": "C","text": "Thalassemia"},{"key": "D","text": "Hemolytic disease of the newborn (erythroblastosis fetalis)"}],"correct": "D","explanation": "Maternal anti-D antibodies cross placenta and hemolyze fetal Rh+ RBCs."},{"id": 1669,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Anti-D immunoglobulin is given to Rh-negative mothers to prevent:","options": [{"key": "A","text": "Thrombocytopenia"},{"key": "B","text": "Rh sensitization in future pregnancies"},{"key": "C","text": "Iron deficiency anemia"},{"key": "D","text": "ABO incompatibility"}],"correct": "B","explanation": "Anti-D prophylaxis prevents maternal sensitization against fetal Rh-positive RBCs."},{"id": 1670,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The most common blood group in the general population worldwide is typically:","options": [{"key": "A","text": "Rare in most populations"},{"key": "B","text": "AB"},{"key": "C","text": "A or O (varies by population)"},{"key": "D","text": "B"}],"correct": "C","explanation": "A and O groups are generally most prevalent, varying by population/ethnicity."},{"id": 1671,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Crossmatching before blood transfusion primarily tests for:","options": [{"key": "A","text": "Platelet function"},{"key": "B","text": "Hemoglobin level"},{"key": "C","text": "Compatibility between donor RBCs and recipient serum"},{"key": "D","text": "WBC count"}],"correct": "C","explanation": "Crossmatch detects antibody-antigen incompatibility to prevent transfusion reaction."},{"id": 1672,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A hemolytic transfusion reaction due to ABO mismatch is primarily caused by:","options": [{"key": "A","text": "Recipient antibodies attacking donor RBCs"},{"key": "B","text": "Donor antibodies attacking recipient RBCs"},{"key": "C","text": "Excess platelets"},{"key": "D","text": "Low hemoglobin"}],"correct": "A","explanation": "Pre-formed recipient antibodies attack and hemolyze incompatible donor RBCs."},{"id": 1673,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "Sickle cell anemia results from a mutation in which gene/protein?","options": [{"key": "A","text": "Gamma globin chain"},{"key": "B","text": "Alpha globin chain"},{"key": "C","text": "Beta globin chain (Glu to Val substitution)"},{"key": "D","text": "Heme synthesis enzyme"}],"correct": "C","explanation": "A single amino acid substitution in beta globin causes HbS, leading to sickling."},{"id": 1674,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Thalassemia is a disorder caused by:","options": [{"key": "A","text": "Iron overload primarily"},{"key": "B","text": "Vitamin B12 deficiency"},{"key": "C","text": "Reduced or absent synthesis of globin chains"},{"key": "D","text": "Abnormal globin chain structure"}],"correct": "C","explanation": "Thalassemia results from reduced/absent production of alpha or beta globin chains."},{"id": 1675,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Aplastic anemia is characterized by:","options": [{"key": "A","text": "Bone marrow failure leading to pancytopenia"},{"key": "B","text": "Excess WBC production only"},{"key": "C","text": "Increased RBC production"},{"key": "D","text": "Hemolysis of RBCs"}],"correct": "A","explanation": "Aplastic anemia involves bone marrow failure causing deficiency of all blood cell lines."},{"id": 1676,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Pernicious anemia is caused by deficiency of:","options": [{"key": "A","text": "Vitamin C"},{"key": "B","text": "Iron due to poor diet"},{"key": "C","text": "Intrinsic factor leading to B12 malabsorption"},{"key": "D","text": "Folate due to alcoholism"}],"correct": "C","explanation": "Autoimmune destruction of parietal cells reduces intrinsic factor, impairing B12 absorption."},{"id": 1677,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Hemolytic anemia is characterized by:","options": [{"key": "A","text": "Decreased RBC production"},{"key": "B","text": "Iron deficiency"},{"key": "C","text": "Increased RBC destruction"},{"key": "D","text": "Vitamin deficiency"}],"correct": "C","explanation": "Hemolytic anemia results from premature destruction of red blood cells."},{"id": 1678,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Polycythemia vera is a condition characterized by:","options": [{"key": "A","text": "Anemia with low hemoglobin"},{"key": "B","text": "Excessive proliferation of RBCs (myeloproliferative disorder)"},{"key": "C","text": "Decreased hematocrit"},{"key": "D","text": "Decreased RBC mass"}],"correct": "B","explanation": "Polycythemia vera is a clonal disorder causing excessive RBC production."},{"id": 1679,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Bleeding time primarily tests the function of:","options": [{"key": "A","text": "Fibrinolysis"},{"key": "B","text": "Iron stores"},{"key": "C","text": "Platelets and vascular function"},{"key": "D","text": "Coagulation factors"}],"correct": "C","explanation": "Bleeding time assesses platelet plug formation and vascular integrity."},{"id": 1680,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Von Willebrand disease results in defective:","options": [{"key": "A","text": "Platelet adhesion due to deficient vWF"},{"key": "B","text": "RBC membrane"},{"key": "C","text": "Coagulation cascade only"},{"key": "D","text": "WBC function"}],"correct": "A","explanation": "vWF deficiency impairs platelet adhesion to subendothelial collagen."},{"id": 1681,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Hard","question": "The P50 value, indicating hemoglobin's affinity for oxygen, refers to the:","options": [{"key": "A","text": "PO2 at 100% saturation"},{"key": "B","text": "CO2 partial pressure"},{"key": "C","text": "PO2 at 50% Hb saturation"},{"key": "D","text": "Hb concentration at 50% saturation"}],"correct": "C","explanation": "P50 is the partial pressure of O2 at which hemoglobin is 50% saturated."},{"id": 1682,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "A rightward shift of the oxygen-hemoglobin dissociation curve indicates:","options": [{"key": "A","text": "Increased CO2 binding only"},{"key": "B","text": "No change in affinity"},{"key": "C","text": "Increased O2 affinity"},{"key": "D","text": "Decreased O2 affinity, facilitating O2 release to tissues"}],"correct": "D","explanation": "Rightward shift (e.g., due to increased CO2, H+, temperature) reduces Hb-O2 affinity."},{"id": 1683,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Which factor causes a leftward shift of the oxygen dissociation curve?","options": [{"key": "A","text": "Increased H+ concentration"},{"key": "B","text": "Decreased temperature"},{"key": "C","text": "Increased 2,3-DPG"},{"key": "D","text": "Increased temperature"}],"correct": "B","explanation": "Decreased temperature increases Hb's affinity for O2, shifting curve left."},{"id": 1684,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "2,3-diphosphoglycerate (2,3-DPG) in RBCs functions to:","options": [{"key": "A","text": "Increase Hb-O2 affinity"},{"key": "B","text": "Stabilize fetal hemoglobin"},{"key": "C","text": "Increase CO2 transport only"},{"key": "D","text": "Decrease Hb-O2 affinity, promoting O2 unloading"}],"correct": "D","explanation": "2,3-DPG binds deoxyhemoglobin, reducing O2 affinity and aiding tissue O2 delivery."},{"id": 1685,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "Carbon monoxide poisoning is dangerous because CO has much higher affinity for hemoglobin than oxygen, forming:","options": [{"key": "A","text": "Methemoglobin"},{"key": "B","text": "Carboxyhemoglobin"},{"key": "C","text": "Sulfhemoglobin"},{"key": "D","text": "Oxyhemoglobin"}],"correct": "B","explanation": "CO binds hemoglobin ~200x more strongly than O2, forming carboxyhemoglobin."},{"id": 1686,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The bone marrow site for erythropoiesis primarily shifts to which locations in adults?","options": [{"key": "A","text": "Long bone shafts"},{"key": "B","text": "Flat bones (vertebrae, sternum, pelvis)"},{"key": "C","text": "Lymph nodes"},{"key": "D","text": "Liver and spleen only"}],"correct": "B","explanation": "In adults, active marrow (red marrow) is mainly confined to flat/axial bones."},{"id": 1687,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "In a complete blood count, MCV (Mean Corpuscular Volume) indicates:","options": [{"key": "A","text": "Hemoglobin concentration per cell"},{"key": "B","text": "Platelet size"},{"key": "C","text": "Total RBC count"},{"key": "D","text": "Average size of red blood cells"}],"correct": "D","explanation": "MCV reflects the average volume/size of individual red blood cells."},{"id": 1688,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A high MCV value typically indicates which type of anemia?","options": [{"key": "A","text": "Microcytic anemia"},{"key": "B","text": "Normocytic anemia"},{"key": "C","text": "Macrocytic anemia"},{"key": "D","text": "No anemia"}],"correct": "C","explanation": "Elevated MCV indicates larger than normal RBCs, seen in macrocytic anemia."},{"id": 1689,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "MCHC (Mean Corpuscular Hemoglobin Concentration) measures:","options": [{"key": "A","text": "Total hemoglobin amount"},{"key": "B","text": "Concentration of hemoglobin within RBCs"},{"key": "C","text": "RBC count per volume"},{"key": "D","text": "Platelet concentration"}],"correct": "B","explanation": "MCHC indicates hemoglobin concentration relative to RBC volume."},{"id": 1690,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which leukocyte is the first line of defense against acute bacterial infection through phagocytosis?","options": [{"key": "A","text": "Eosinophil"},{"key": "B","text": "Neutrophil"},{"key": "C","text": "Basophil"},{"key": "D","text": "Lymphocyte"}],"correct": "B","explanation": "Neutrophils rapidly migrate to infection sites and phagocytose bacteria."},{"id": 1691,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The process by which blood clot shrinks and squeezes out serum is called:","options": [{"key": "A","text": "Fibrinolysis"},{"key": "B","text": "Coagulation"},{"key": "C","text": "Clot retraction"},{"key": "D","text": "Hemostasis"}],"correct": "C","explanation": "Clot retraction is mediated by platelet contractile proteins, stabilizing the clot."},{"id": 1692,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Protein C and Protein S act as natural anticoagulants by inactivating which factors?","options": [{"key": "A","text": "Factors Va and VIIIa"},{"key": "B","text": "Factor XIII"},{"key": "C","text": "Factors II and X"},{"key": "D","text": "Factor XII only"}],"correct": "A","explanation": "Activated Protein C, with Protein S as cofactor, degrades Factors Va and VIIIa."},{"id": 1693,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Antithrombin III primarily inhibits which clotting factors?","options": [{"key": "A","text": "Factor XIII only"},{"key": "B","text": "Thrombin and Factor Xa"},{"key": "C","text": "Factor VII only"},{"key": "D","text": "Platelets"}],"correct": "B","explanation": "Antithrombin III neutralizes thrombin and activated Factor X, limiting coagulation."},{"id": 1694,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Which condition results from excessive destruction of platelets, leading to bleeding tendency?","options": [{"key": "A","text": "Thrombocytopenia"},{"key": "B","text": "Polycythemia"},{"key": "C","text": "Leukocytosis"},{"key": "D","text": "Erythrocytosis"}],"correct": "A","explanation": "Thrombocytopenia, low platelet count, predisposes to bruising and bleeding."},{"id": 1695,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "Conduction velocity is fastest in which type of nerve fiber?","options": [{"key": "A","text": "Type C fibers"},{"key": "B","text": "Type A-alpha fibers"},{"key": "C","text": "Type B fibers"},{"key": "D","text": "Type A-delta fibers"}],"correct": "B","explanation": "A-alpha fibers are largest, myelinated, with fastest conduction velocity."},{"id": 1696,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Which nerve fiber type is unmyelinated and conducts pain (slow/dull pain) sensation?","options": [{"key": "A","text": "A-alpha"},{"key": "B","text": "A-beta"},{"key": "C","text": "C fibers"},{"key": "D","text": "A-delta"}],"correct": "C","explanation": "C fibers are unmyelinated, conducting slow, dull, burning pain."},{"id": 1697,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A-delta fibers are responsible for transmitting:","options": [{"key": "A","text": "Proprioception"},{"key": "B","text": "Touch only"},{"key": "C","text": "Motor signals to skeletal muscle"},{"key": "D","text": "Fast, sharp pain and temperature"}],"correct": "D","explanation": "A-delta fibers are thinly myelinated, conducting fast sharp pain and temperature."},{"id": 1698,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "Saltatory conduction increases nerve conduction velocity by:","options": [{"key": "A","text": "Decreasing axon diameter"},{"key": "B","text": "Continuous depolarization along the axon"},{"key": "C","text": "Reducing myelin thickness"},{"key": "D","text": "Jumping of impulse between nodes of Ranvier"}],"correct": "D","explanation": "Myelin insulation allows AP to jump node to node, speeding conduction."},{"id": 1699,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "Which factor does NOT increase nerve conduction velocity?","options": [{"key": "A","text": "Myelination"},{"key": "B","text": "Increased temperature (within physiological range)"},{"key": "C","text": "Increased axon diameter"},{"key": "D","text": "Demyelination"}],"correct": "D","explanation": "Demyelination slows or blocks conduction, e.g., in multiple sclerosis."},{"id": 1700,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "The neuromuscular junction (NMJ) neurotransmitter released from motor neuron terminals is:","options": [{"key": "A","text": "Dopamine"},{"key": "B","text": "GABA"},{"key": "C","text": "Acetylcholine"},{"key": "D","text": "Norepinephrine"}],"correct": "C","explanation": "Acetylcholine is the neurotransmitter at the skeletal muscle NMJ."},{"id": 1701,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Acetylcholine at the NMJ binds to which receptor type on the muscle membrane?","options": [{"key": "A","text": "Nicotinic receptor (nicotinic-N2)"},{"key": "B","text": "Muscarinic receptor"},{"key": "C","text": "Adrenergic receptor"},{"key": "D","text": "GABA receptor"}],"correct": "A","explanation": "Nicotinic ACh receptors at the motor end plate mediate skeletal muscle contraction."},{"id": 1702,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "The enzyme responsible for breaking down acetylcholine at the NMJ is:","options": [{"key": "A","text": "Adenylate cyclase"},{"key": "B","text": "Acetylcholinesterase"},{"key": "C","text": "Catechol-O-methyltransferase"},{"key": "D","text": "Monoamine oxidase"}],"correct": "B","explanation": "Acetylcholinesterase rapidly hydrolyzes ACh, terminating its action at the synapse."},{"id": 1703,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Myasthenia gravis is caused by autoimmune destruction of which receptors?","options": [{"key": "A","text": "GABA receptors"},{"key": "B","text": "Nicotinic acetylcholine receptors at NMJ"},{"key": "C","text": "Muscarinic receptors"},{"key": "D","text": "Dopamine receptors"}],"correct": "B","explanation": "Antibodies against nicotinic ACh receptors impair neuromuscular transmission in myasthenia gravis."},{"id": 1704,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Botulinum toxin causes paralysis by:","options": [{"key": "A","text": "Blocking ACh receptors"},{"key": "B","text": "Preventing ACh release from presynaptic terminal"},{"key": "C","text": "Increasing ACh release"},{"key": "D","text": "Blocking acetylcholinesterase"}],"correct": "B","explanation": "Botulinum toxin cleaves SNARE proteins, preventing vesicle fusion and ACh release."},{"id": 1705,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Organophosphate poisoning causes prolonged muscle stimulation by:","options": [{"key": "A","text": "Preventing ACh synthesis"},{"key": "B","text": "Inhibiting acetylcholinesterase"},{"key": "C","text": "Blocking ACh receptors"},{"key": "D","text": "Blocking calcium channels"}],"correct": "B","explanation": "Organophosphates inhibit AChE, causing accumulation of ACh and continuous stimulation."},{"id": 1706,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The end plate potential (EPP) at NMJ is an example of which type of potential?","options": [{"key": "A","text": "Graded, non-propagated potential"},{"key": "B","text": "All-or-none action potential"},{"key": "C","text": "Hyperpolarizing potential"},{"key": "D","text": "Pacemaker potential"}],"correct": "A","explanation": "EPP is a graded depolarization that, if threshold is reached, triggers a muscle AP."},{"id": 1707,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Calcium influx at the presynaptic terminal of NMJ is mediated through which channel?","options": [{"key": "A","text": "Voltage-gated Ca2+ channel"},{"key": "B","text": "Aquaporin"},{"key": "C","text": "Voltage-gated Na+ channel"},{"key": "D","text": "Ligand-gated K+ channel"}],"correct": "A","explanation": "Depolarization opens voltage-gated Ca2+ channels, triggering vesicle fusion and ACh release."},{"id": 1708,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "The structural and functional unit of skeletal muscle contraction is the:","options": [{"key": "A","text": "Motor unit"},{"key": "B","text": "Sarcomere"},{"key": "C","text": "Sarcoplasmic reticulum"},{"key": "D","text": "Myofibril"}],"correct": "B","explanation": "The sarcomere, between two Z-lines, is the basic contractile unit."},{"id": 1709,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In a sarcomere, the A band represents:","options": [{"key": "A","text": "Thick filaments (myosin), including overlap region"},{"key": "B","text": "Thin filaments only"},{"key": "C","text": "Z-line region"},{"key": "D","text": "Region with thin filaments only (I band)"}],"correct": "A","explanation": "A band corresponds to the length of myosin (thick) filaments."},{"id": 1710,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The I band of a sarcomere contains:","options": [{"key": "A","text": "Only thin filaments (actin)"},{"key": "B","text": "Both thick and thin filaments overlapping fully"},{"key": "C","text": "M line only"},{"key": "D","text": "Only thick filaments"}],"correct": "A","explanation": "I band consists of thin actin filaments not overlapped by myosin."},{"id": 1711,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "During muscle contraction, which band shortens while the A band length remains constant?","options": [{"key": "A","text": "I band"},{"key": "B","text": "Sarcomere length increases"},{"key": "C","text": "A band"},{"key": "D","text": "M line width"}],"correct": "A","explanation": "I band shortens as actin filaments slide over myosin, per sliding filament theory."},{"id": 1712,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "The sliding filament theory of muscle contraction states that:","options": [{"key": "A","text": "Myofilaments shorten individually"},{"key": "B","text": "Sarcomeres elongate during contraction"},{"key": "C","text": "Actin filaments slide over myosin filaments without changing filament length"},{"key": "D","text": "Myosin filaments shorten"}],"correct": "C","explanation": "Filaments slide past each other; their individual lengths remain unchanged."},{"id": 1713,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "Calcium ions for skeletal muscle contraction are primarily released from:","options": [{"key": "A","text": "Mitochondria"},{"key": "B","text": "Nucleus"},{"key": "C","text": "Sarcoplasmic reticulum"},{"key": "D","text": "Extracellular fluid mainly"}],"correct": "C","explanation": "Sarcoplasmic reticulum stores and releases Ca2+ upon depolarization via T-tubules."},{"id": 1714,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "The protein that binds calcium to initiate skeletal muscle contraction is:","options": [{"key": "A","text": "Myosin"},{"key": "B","text": "Troponin C"},{"key": "C","text": "Actin"},{"key": "D","text": "Tropomyosin"}],"correct": "B","explanation": "Troponin C binds Ca2+, causing conformational change that moves tropomyosin."},{"id": 1715,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Tropomyosin's role in muscle contraction at rest is to:","options": [{"key": "A","text": "Form cross bridges"},{"key": "B","text": "Hydrolyze ATP"},{"key": "C","text": "Block myosin binding sites on actin"},{"key": "D","text": "Bind calcium"}],"correct": "C","explanation": "Tropomyosin covers actin's myosin-binding sites, preventing contraction at rest."},{"id": 1716,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The cross-bridge cycle begins with myosin head binding to actin, which requires:","options": [{"key": "A","text": "ATP binding to myosin"},{"key": "B","text": "Potassium efflux"},{"key": "C","text": "Sodium influx"},{"key": "D","text": "Calcium binding to troponin exposing binding sites"}],"correct": "D","explanation": "Calcium-troponin binding shifts tropomyosin, exposing actin sites for myosin binding."},{"id": 1717,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "ATP hydrolysis during the cross-bridge cycle is required for:","options": [{"key": "A","text": "Calcium release only"},{"key": "B","text": "Sodium pump function only"},{"key": "C","text": "Cocking of the myosin head (power stroke preparation)"},{"key": "D","text": "Acetylcholine release"}],"correct": "C","explanation": "ATP hydrolysis energizes the myosin head, priming it for the power stroke."},{"id": 1718,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Rigor mortis occurs due to:","options": [{"key": "A","text": "Excess calcium removal"},{"key": "B","text": "Excess ATP availability"},{"key": "C","text": "Loss of troponin"},{"key": "D","text": "Absence of ATP preventing myosin head detachment from actin"}],"correct": "D","explanation": "Without ATP, myosin heads remain bound to actin, causing muscle stiffness after death."},{"id": 1719,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "T-tubules in skeletal muscle function to:","options": [{"key": "A","text": "Synthesize proteins"},{"key": "B","text": "Produce ATP"},{"key": "C","text": "Store calcium"},{"key": "D","text": "Conduct action potential deep into the muscle fiber"}],"correct": "D","explanation": "T-tubules transmit the surface action potential into the muscle fiber interior."},{"id": 1720,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The triad in skeletal muscle consists of:","options": [{"key": "A","text": "One T-tubule and two terminal cisternae of sarcoplasmic reticulum"},{"key": "B","text": "Three sarcoplasmic reticula"},{"key": "C","text": "Two myofibrils and one nucleus"},{"key": "D","text": "Two T-tubules and one sarcoplasmic reticulum"}],"correct": "A","explanation": "A triad is one T-tubule flanked by two terminal cisternae of SR."},{"id": 1721,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The dihydropyridine receptor (DHPR) in skeletal muscle T-tubules is mechanically linked to which receptor on SR?","options": [{"key": "A","text": "Muscarinic receptor"},{"key": "B","text": "Adrenergic receptor"},{"key": "C","text": "Nicotinic receptor"},{"key": "D","text": "Ryanodine receptor"}],"correct": "D","explanation": "DHPR senses depolarization and mechanically opens ryanodine receptors, releasing Ca2+."},{"id": 1722,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Easy","question": "A motor unit is defined as:","options": [{"key": "A","text": "A single muscle fiber"},{"key": "B","text": "One neuromuscular junction only"},{"key": "C","text": "One motor neuron and all muscle fibers it innervates"},{"key": "D","text": "A group of sarcomeres"}],"correct": "C","explanation": "Motor unit = one alpha motor neuron plus all the muscle fibers it supplies."},{"id": 1723,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Small motor units (few muscle fibers per neuron) are typically found in muscles requiring:","options": [{"key": "A","text": "Fine, precise control (e.g., extraocular muscles)"},{"key": "B","text": "Sustained heavy lifting"},{"key": "C","text": "Gross power movements"},{"key": "D","text": "Maximum force generation only"}],"correct": "A","explanation": "Fine motor control muscles have small motor units for precision."},{"id": 1724,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "The 'all-or-none' law applies to which level of skeletal muscle contraction?","options": [{"key": "A","text": "Whole muscle"},{"key": "B","text": "Individual muscle fiber"},{"key": "C","text": "Motor unit recruitment overall"},{"key": "D","text": "Tendon"}],"correct": "B","explanation": "Individual muscle fibers follow all-or-none; whole muscle force is graded by recruitment."},{"id": 1725,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Graded contraction (variable force) in whole skeletal muscle is achieved mainly through:","options": [{"key": "A","text": "Recruitment of motor units and frequency of stimulation (summation)"},{"key": "B","text": "Single fiber length change only"},{"key": "C","text": "Variation in resting membrane potential"},{"key": "D","text": "Variation in action potential amplitude"}],"correct": "A","explanation": "Force grading occurs via motor unit recruitment and temporal summation of twitches."},{"id": 1726,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Tetanus (sustained contraction) in skeletal muscle occurs due to:","options": [{"key": "A","text": "Complete relaxation between stimuli"},{"key": "B","text": "High-frequency stimulation causing fused summation of twitches"},{"key": "C","text": "Low-frequency stimulation"},{"key": "D","text": "Single twitch summation absent"}],"correct": "B","explanation": "Rapid repeated stimuli prevent relaxation, fusing twitches into sustained tetanic contraction."},{"id": 1727,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The latent period in a muscle twitch refers to:","options": [{"key": "A","text": "Refractory period of muscle"},{"key": "B","text": "Brief delay between stimulus and onset of contraction"},{"key": "C","text": "Relaxation phase only"},{"key": "D","text": "Time of peak tension"}],"correct": "B","explanation": "Latent period is the time between stimulus application and beginning of tension development."},{"id": 1728,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Isometric contraction is characterized by:","options": [{"key": "A","text": "Tension increases but muscle length remains constant"},{"key": "B","text": "Only eccentric movement"},{"key": "C","text": "No tension generated"},{"key": "D","text": "Change in muscle length without tension change"}],"correct": "A","explanation": "Isometric contraction generates force without a change in overall muscle length."},{"id": 1729,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Isotonic contraction is characterized by:","options": [{"key": "A","text": "No cross-bridge cycling"},{"key": "B","text": "Constant muscle length"},{"key": "C","text": "Constant tension with change in muscle length"},{"key": "D","text": "Only happens in cardiac muscle"}],"correct": "C","explanation": "Isotonic contraction involves constant tension while muscle length changes (shortening/lengthening)."},{"id": 1730,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Concentric contraction refers to:","options": [{"key": "A","text": "Muscle lengthening while generating tension"},{"key": "B","text": "Muscle shortening while generating tension"},{"key": "C","text": "Only passive stretching"},{"key": "D","text": "No movement at all"}],"correct": "B","explanation": "Concentric contraction is shortening of muscle against a load."},{"id": 1731,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Eccentric contraction refers to:","options": [{"key": "A","text": "Isometric holding only"},{"key": "B","text": "Muscle shortening under tension"},{"key": "C","text": "Muscle lengthening while still generating tension (e.g., lowering a weight)"},{"key": "D","text": "Resting muscle state"}],"correct": "C","explanation": "Eccentric contraction involves muscle lengthening while resisting/generating force."},{"id": 1732,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Type I (slow oxidative) muscle fibers are characterized by:","options": [{"key": "A","text": "Slow contraction, fatigue resistant, rely on oxidative metabolism"},{"key": "B","text": "Pale color due to low myoglobin"},{"key": "C","text": "Fast contraction, fatigue quickly, anaerobic metabolism"},{"key": "D","text": "Absence of mitochondria"}],"correct": "A","explanation": "Type I fibers are red, mitochondria-rich, fatigue-resistant, used for endurance activities."},{"id": 1733,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Type IIb (fast glycolytic) muscle fibers are characterized by:","options": [{"key": "A","text": "Slow twitch speed"},{"key": "B","text": "High myoglobin content"},{"key": "C","text": "High fatigue resistance"},{"key": "D","text": "Rapid, powerful contraction relying on anaerobic glycolysis, fatigue quickly"}],"correct": "D","explanation": "Type IIb fibers are white, glycolytic, fast but fatigue rapidly."},{"id": 1734,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Smooth muscle differs from skeletal muscle in that it lacks:","options": [{"key": "A","text": "Calcium dependency"},{"key": "B","text": "Troponin complex (uses calmodulin instead)"},{"key": "C","text": "Actin and myosin filaments"},{"key": "D","text": "Contractile ability"}],"correct": "B","explanation": "Smooth muscle uses calcium-calmodulin and lacks the troponin system of skeletal muscle."},{"id": 1735,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Calcium activation of smooth muscle contraction occurs via binding to:","options": [{"key": "A","text": "Calmodulin, which activates myosin light chain kinase"},{"key": "B","text": "Troponin C"},{"key": "C","text": "Tropomyosin directly"},{"key": "D","text": "Actin directly"}],"correct": "A","explanation": "Ca2+-calmodulin complex activates MLCK, phosphorylating myosin light chains for contraction."},{"id": 1736,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Myosin light chain kinase (MLCK) in smooth muscle contraction functions to:","options": [{"key": "A","text": "Remove calcium from the cell"},{"key": "B","text": "Phosphorylate myosin light chains enabling cross-bridge cycling"},{"key": "C","text": "Block actin binding sites"},{"key": "D","text": "Hydrolyze acetylcholine"}],"correct": "B","explanation": "MLCK phosphorylates myosin light chains, allowing myosin-actin interaction in smooth muscle."},{"id": 1737,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Smooth muscle relaxation occurs when myosin light chains are dephosphorylated by:","options": [{"key": "A","text": "Acetylcholinesterase"},{"key": "B","text": "Myosin light chain kinase"},{"key": "C","text": "Adenylate cyclase"},{"key": "D","text": "Myosin light chain phosphatase"}],"correct": "D","explanation": "Myosin light chain phosphatase removes phosphate, promoting smooth muscle relaxation."},{"id": 1738,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Single-unit (visceral) smooth muscle is characterized by:","options": [{"key": "A","text": "No spontaneous activity"},{"key": "B","text": "Independent contraction of each cell"},{"key": "C","text": "Presence of distinct neuromuscular junctions on each cell"},{"key": "D","text": "Cells connected via gap junctions, contracting as a syncytium"}],"correct": "D","explanation": "Visceral smooth muscle cells are electrically coupled via gap junctions, functioning as a unit."},{"id": 1739,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Multi-unit smooth muscle, found in structures like the iris, is characterized by:","options": [{"key": "A","text": "Spontaneous pacemaker activity throughout"},{"key": "B","text": "Each fiber innervated separately, contracting independently"},{"key": "C","text": "Absence of innervation"},{"key": "D","text": "Cells acting as a syncytium"}],"correct": "B","explanation": "Multi-unit smooth muscle fibers are individually innervated, allowing fine, graded control."},{"id": 1740,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Cardiac muscle cells are connected to each other structurally and electrically by:","options": [{"key": "A","text": "Myelin sheath"},{"key": "B","text": "Intercalated discs containing gap junctions"},{"key": "C","text": "Tendons"},{"key": "D","text": "Synapses"}],"correct": "B","explanation": "Intercalated discs with gap junctions allow electrical continuity between cardiac cells."},{"id": 1741,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The pacemaker potential of the SA node is primarily due to which current?","options": [{"key": "A","text": "Funny current (If) - slow inward Na+/K+ mixed current"},{"key": "B","text": "Fast Ca2+ current only"},{"key": "C","text": "K+ efflux only"},{"key": "D","text": "Fast Na+ current"}],"correct": "A","explanation": "The 'funny current' (If) causes the slow spontaneous depolarization of pacemaker cells."},{"id": 1742,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The plateau phase of the cardiac action potential in ventricular myocytes is due to:","options": [{"key": "A","text": "K+ influx alone"},{"key": "B","text": "Cl- influx"},{"key": "C","text": "Rapid Na+ influx"},{"key": "D","text": "Balance between Ca2+ influx and K+ efflux"}],"correct": "D","explanation": "Plateau phase results from sustained Ca2+ entry balanced by slow K+ efflux."},{"id": 1743,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Cardiac muscle has a long refractory period mainly to:","options": [{"key": "A","text": "Allow tetanic contraction"},{"key": "B","text": "Increase heart rate"},{"key": "C","text": "Prevent tetanic contraction and allow adequate filling time"},{"key": "D","text": "Decrease contractility"}],"correct": "C","explanation": "Long refractory period prevents summation/tetany, ensuring proper diastolic filling."},{"id": 1744,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which ion channel blocker class is responsible for slowing SA/AV nodal conduction by blocking calcium channels?","options": [{"key": "A","text": "Calcium channel blockers (e.g., verapamil)"},{"key": "B","text": "Sodium channel blockers"},{"key": "C","text": "Potassium channel blockers"},{"key": "D","text": "Beta blockers"}],"correct": "A","explanation": "Calcium channel blockers reduce conduction velocity through SA and AV nodes."},{"id": 1745,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The Frank-Starling law of the heart relates to:","options": [{"key": "A","text": "Decreased contractility with stretch"},{"key": "B","text": "Afterload reduction only"},{"key": "C","text": "Increased preload leading to increased force of contraction"},{"key": "D","text": "No relation between length and tension"}],"correct": "C","explanation": "Frank-Starling mechanism states greater venous return (preload) increases stroke volume."},{"id": 1746,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Hard","question": "Excitation-contraction coupling in cardiac muscle involves calcium-induced calcium release, where extracellular Ca2+ entering via:","options": [{"key": "A","text": "L-type Ca2+ channels triggers further Ca2+ release from SR"},{"key": "B","text": "Only SR calcium is needed"},{"key": "C","text": "Na+ channels release calcium directly"},{"key": "D","text": "T-tubules block calcium entry"}],"correct": "A","explanation": "Ca2+ influx through L-type channels triggers larger Ca2+ release from SR via ryanodine receptors."},{"id": 1747,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "A nerve fiber's absolute refractory period prevents:","options": [{"key": "A","text": "Repolarization"},{"key": "B","text": "Initiation of a new action potential regardless of stimulus strength"},{"key": "C","text": "Hyperpolarization"},{"key": "D","text": "Resting potential restoration"}],"correct": "B","explanation": "During absolute refractory period, no stimulus can generate a new AP."},{"id": 1748,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Wallerian degeneration refers to:","options": [{"key": "A","text": "Degeneration of the axon distal to a nerve injury"},{"key": "B","text": "Muscle atrophy without nerve damage"},{"key": "C","text": "Regeneration of a cut nerve"},{"key": "D","text": "Demyelination of central neurons only"}],"correct": "A","explanation": "After axonal injury, the distal segment undergoes degeneration known as Wallerian degeneration."},{"id": 1749,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Nerve regeneration after peripheral injury is primarily guided by:","options": [{"key": "A","text": "Oligodendrocytes"},{"key": "B","text": "Schwann cells forming a guidance tube (band of Bungner)"},{"key": "C","text": "Astrocytes"},{"key": "D","text": "Microglia"}],"correct": "B","explanation": "Schwann cells proliferate and guide regrowing axons in peripheral nerve regeneration."},{"id": 1750,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Multiple sclerosis primarily affects which structure, slowing nerve conduction?","options": [{"key": "A","text": "Peripheral nerve axons"},{"key": "B","text": "Neuromuscular junction"},{"key": "C","text": "Skeletal muscle fibers"},{"key": "D","text": "Myelin sheath of CNS neurons (oligodendrocytes)"}],"correct": "D","explanation": "MS is an autoimmune demyelinating disease affecting CNS myelin produced by oligodendrocytes."},{"id": 1751,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Medium","question": "Curare, a neuromuscular blocking agent, acts by:","options": [{"key": "A","text": "Competitively blocking nicotinic ACh receptors at NMJ"},{"key": "B","text": "Increasing ACh release"},{"key": "C","text": "Stimulating ACh receptors"},{"key": "D","text": "Inhibiting acetylcholinesterase"}],"correct": "A","explanation": "Curare competitively antagonizes nicotinic receptors, preventing muscle depolarization."},{"id": 1752,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Succinylcholine causes muscle paralysis by acting as a:","options": [{"key": "A","text": "Calcium channel blocker"},{"key": "B","text": "Depolarizing agonist causing prolonged depolarization block"},{"key": "C","text": "Competitive antagonist at ACh receptor"},{"key": "D","text": "Acetylcholinesterase inhibitor only"}],"correct": "B","explanation": "Succinylcholine persistently depolarizes the end plate, leading to depolarization blockade."},{"id": 1753,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The resting length-tension relationship of skeletal muscle shows maximum tension is generated at:","options": [{"key": "A","text": "Minimal sarcomere length"},{"key": "B","text": "Any length equally"},{"key": "C","text": "Optimal sarcomere length with optimal actin-myosin overlap"},{"key": "D","text": "Maximally stretched length"}],"correct": "C","explanation": "Maximum tension occurs at optimal overlap allowing maximal cross-bridge formation."},{"id": 1754,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Smooth muscle exhibits 'stress-relaxation' property, meaning:","options": [{"key": "A","text": "Tension decreases over time despite continued stretch, allowing accommodation of volume"},{"key": "B","text": "It cannot relax once contracted"},{"key": "C","text": "It contracts faster than skeletal muscle"},{"key": "D","text": "It requires no calcium for relaxation"}],"correct": "A","explanation": "Stress-relaxation allows hollow organs like bladder to accommodate increasing volume with little tension rise."},{"id": 1755,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Pacemaker potential is a feature of which smooth muscle/cardiac tissue activity?","options": [{"key": "A","text": "Striated muscle exclusively"},{"key": "B","text": "Only neurons"},{"key": "C","text": "Spontaneous depolarization in certain smooth muscle and cardiac pacemaker cells"},{"key": "D","text": "Skeletal muscle only"}],"correct": "C","explanation": "Pacemaker potentials drive spontaneous rhythmic activity in cardiac SA node and some smooth muscle."},{"id": 1756,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The thick filament of skeletal muscle is primarily composed of:","options": [{"key": "A","text": "Myosin"},{"key": "B","text": "Troponin"},{"key": "C","text": "Actin"},{"key": "D","text": "Tropomyosin"}],"correct": "A","explanation": "Thick filaments are composed mainly of myosin protein."},{"id": 1757,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The thin filament of skeletal muscle is primarily composed of:","options": [{"key": "A","text": "Titin only"},{"key": "B","text": "Actin, troponin, and tropomyosin"},{"key": "C","text": "Desmin only"},{"key": "D","text": "Myosin"}],"correct": "B","explanation": "Thin filaments consist of actin with regulatory proteins troponin and tropomyosin."},{"id": 1758,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Titin (connectin) protein in sarcomeres functions to:","options": [{"key": "A","text": "Generate active tension"},{"key": "B","text": "Hydrolyze ATP"},{"key": "C","text": "Bind calcium for contraction"},{"key": "D","text": "Provide passive elasticity and structural support, connecting Z-line to M-line"}],"correct": "D","explanation": "Titin acts as a molecular spring providing passive tension and sarcomere stability."},{"id": 1759,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Z-line in a sarcomere serves to:","options": [{"key": "A","text": "Anchor thin (actin) filaments, defining sarcomere boundary"},{"key": "B","text": "Store calcium"},{"key": "C","text": "Generate ATP"},{"key": "D","text": "Anchor thick filaments"}],"correct": "A","explanation": "Z-lines anchor actin filaments and mark the boundaries of each sarcomere."},{"id": 1760,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Denervated skeletal muscle undergoes which process over time?","options": [{"key": "A","text": "Atrophy due to disuse and loss of trophic influence"},{"key": "B","text": "No change"},{"key": "C","text": "Increased strength"},{"key": "D","text": "Hypertrophy"}],"correct": "A","explanation": "Loss of nerve supply leads to progressive muscle atrophy."},{"id": 1761,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Fasciculation refers to:","options": [{"key": "A","text": "Visible spontaneous twitching of a motor unit"},{"key": "B","text": "Rigor mortis"},{"key": "C","text": "Sustained tetanic contraction"},{"key": "D","text": "Muscle paralysis"}],"correct": "A","explanation": "Fasciculations are involuntary contractions of single motor units, visible under skin."},{"id": 1762,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Fibrillation (muscle) refers to:","options": [{"key": "A","text": "Tetanic contraction"},{"key": "B","text": "Coordinated muscle contraction"},{"key": "C","text": "Spontaneous contraction of individual denervated muscle fibers, not visible externally"},{"key": "D","text": "Visible twitching of motor units"}],"correct": "C","explanation": "Fibrillations occur in denervated fibers due to membrane hypersensitivity, detected by EMG."},{"id": 1763,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The neurotransmitter at autonomic ganglia (both sympathetic and parasympathetic preganglionic) is:","options": [{"key": "A","text": "Serotonin"},{"key": "B","text": "Norepinephrine"},{"key": "C","text": "Acetylcholine acting on nicotinic receptors"},{"key": "D","text": "Dopamine"}],"correct": "C","explanation": "Preganglionic autonomic fibers release ACh acting on nicotinic receptors at ganglia."},{"id": 1764,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Hard","question": "Smooth muscle, unlike skeletal muscle, can maintain prolonged contraction with low ATP consumption due to:","options": [{"key": "A","text": "Continuous calcium influx only"},{"key": "B","text": "Absence of cross-bridge cycling"},{"key": "C","text": "Lack of myosin"},{"key": "D","text": "The 'latch state' mechanism"}],"correct": "D","explanation": "Latch state allows sustained tension with reduced cross-bridge cycling and ATP use."},{"id": 1765,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which property describes smooth muscle's ability to maintain constant tension over a wide range of lengths?","options": [{"key": "A","text": "Summation"},{"key": "B","text": "Stress-relaxation"},{"key": "C","text": "Plasticity"},{"key": "D","text": "Tetanus"}],"correct": "C","explanation": "Plasticity allows smooth muscle to adjust tension despite changes in length."},{"id": 1766,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Sympathetic stimulation of cardiac muscle increases heart rate primarily via which receptor?","options": [{"key": "A","text": "Nicotinic receptor"},{"key": "B","text": "Muscarinic M2 receptor"},{"key": "C","text": "Alpha-1 adrenergic receptor"},{"key": "D","text": "Beta-1 adrenergic receptor"}],"correct": "D","explanation": "Beta-1 receptors mediate sympathetic increase in heart rate and contractility."},{"id": 1767,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Parasympathetic stimulation slows heart rate via acetylcholine acting on which receptor?","options": [{"key": "A","text": "Nicotinic receptor"},{"key": "B","text": "Alpha-2 receptor"},{"key": "C","text": "Muscarinic M2 receptor"},{"key": "D","text": "Beta-1 receptor"}],"correct": "C","explanation": "Vagal ACh acts on M2 muscarinic receptors in SA/AV node, slowing heart rate."},{"id": 1768,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The refractory period of skeletal muscle is much shorter than cardiac muscle, allowing skeletal muscle to:","options": [{"key": "A","text": "Avoid fatigue completely"},{"key": "B","text": "Undergo tetanic (summated) contraction"},{"key": "C","text": "Never contract repeatedly"},{"key": "D","text": "Function without calcium"}],"correct": "B","explanation": "Short refractory period in skeletal muscle permits summation and tetanus, unlike cardiac muscle."},{"id": 1769,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Excitation-contraction coupling refers to the process linking:","options": [{"key": "A","text": "Nerve growth to muscle development"},{"key": "B","text": "Electrical excitation (action potential) to mechanical contraction"},{"key": "C","text": "Blood flow to muscle metabolism"},{"key": "D","text": "Muscle relaxation to ATP depletion"}],"correct": "B","explanation": "E-C coupling links the electrical signal (AP) to the mechanical contractile response."},{"id": 1770,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Calcium is removed from the sarcoplasm after contraction mainly via:","options": [{"key": "A","text": "Mitochondrial uptake exclusively"},{"key": "B","text": "Diffusion out of the cell only"},{"key": "C","text": "SERCA pump actively transporting Ca2+ back into sarcoplasmic reticulum"},{"key": "D","text": "Passive leak channels only"}],"correct": "C","explanation": "SERCA (Ca2+ ATPase) pumps calcium back into the SR, allowing muscle relaxation."},{"id": 1771,"subject": "Physiology","topic": "Nerve & Muscle Physiology","difficulty": "Hard","question": "The neuromuscular junction synaptic cleft width compared to a typical CNS synapse is:","options": [{"key": "A","text": "Non-existent"},{"key": "B","text": "Filled with myelin"},{"key": "C","text": "Much narrower"},{"key": "D","text": "Similar or slightly wider"}],"correct": "D","explanation": "NMJ has a relatively wider synaptic cleft compared to many CNS synapses."},{"id": 1772,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Quantal release of acetylcholine at NMJ refers to:","options": [{"key": "A","text": "Release of ACh in discrete packets (vesicles)"},{"key": "B","text": "Calcium release only"},{"key": "C","text": "Release of single molecules only"},{"key": "D","text": "Continuous graded release"}],"correct": "A","explanation": "ACh is released in quanta, each corresponding to the contents of one synaptic vesicle."},{"id": 1773,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Miniature end plate potentials (MEPPs) result from:","options": [{"key": "A","text": "Action potential propagation"},{"key": "B","text": "Muscle contraction directly"},{"key": "C","text": "Calcium channel blockade"},{"key": "D","text": "Spontaneous release of single ACh vesicles at rest"}],"correct": "D","explanation": "MEPPs are small depolarizations from spontaneous single-vesicle ACh release."},{"id": 1774,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The H zone of the sarcomere represents:","options": [{"key": "A","text": "Z-line region"},{"key": "B","text": "Region of thin filaments only"},{"key": "C","text": "M-line only"},{"key": "D","text": "Central region of thick filaments not overlapped by thin filaments"}],"correct": "D","explanation": "H zone is the central part of the A band where only thick filaments are present."},{"id": 1775,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The M-line in a sarcomere functions to:","options": [{"key": "A","text": "Anchor and stabilize myosin (thick) filaments at the center of sarcomere"},{"key": "B","text": "Initiate action potentials"},{"key": "C","text": "Store calcium"},{"key": "D","text": "Anchor actin filaments"}],"correct": "A","explanation": "M-line proteins cross-link myosin filaments, maintaining their alignment."},{"id": 1776,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A 'twitch' in skeletal muscle physiology refers to:","options": [{"key": "A","text": "Resting muscle tone"},{"key": "B","text": "Continuous fasciculation"},{"key": "C","text": "Brief contraction-relaxation cycle in response to a single stimulus"},{"key": "D","text": "Sustained tetanic contraction"}],"correct": "C","explanation": "A twitch is the mechanical response to a single action potential stimulus."},{"id": 1777,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Wave summation in skeletal muscle occurs when:","options": [{"key": "A","text": "A second stimulus arrives before complete relaxation from the first, increasing tension"},{"key": "B","text": "Only a single stimulus is given"},{"key": "C","text": "Stimuli are spaced far apart allowing full relaxation"},{"key": "D","text": "Calcium is completely removed between stimuli"}],"correct": "A","explanation": "Summation occurs when successive twitches overlap, building higher tension."},{"id": 1778,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Cardiac muscle differs from skeletal muscle in that it is:","options": [{"key": "A","text": "Involuntary and non-striated"},{"key": "B","text": "Voluntary, striated, multinucleated"},{"key": "C","text": "Involuntary, striated, typically uninucleated, with intercalated discs"},{"key": "D","text": "Voluntary and non-striated"}],"correct": "C","explanation": "Cardiac muscle is involuntary, striated, mostly single-nucleated, connected via intercalated discs."},{"id": 1779,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Smooth muscle is classified as:","options": [{"key": "A","text": "Striated, involuntary"},{"key": "B","text": "Striated, voluntary"},{"key": "C","text": "Non-striated, involuntary"},{"key": "D","text": "Non-striated, voluntary"}],"correct": "C","explanation": "Smooth muscle lacks visible striations and is under involuntary (autonomic) control."},{"id": 1780,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The autonomic neurotransmitter acting on smooth muscle of the gut to increase motility is mainly:","options": [{"key": "A","text": "Dopamine"},{"key": "B","text": "Epinephrine"},{"key": "C","text": "Norepinephrine"},{"key": "D","text": "Acetylcholine (parasympathetic)"}],"correct": "D","explanation": "Parasympathetic ACh stimulates increased gut smooth muscle motility."},{"id": 1781,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Pacemaker cells of the gut (interstitial cells of Cajal) generate which electrical activity?","options": [{"key": "A","text": "Plateau potentials only"},{"key": "B","text": "No electrical activity"},{"key": "C","text": "Action potentials only"},{"key": "D","text": "Slow waves (basic electrical rhythm)"}],"correct": "D","explanation": "Interstitial cells of Cajal generate slow wave rhythmic depolarizations controlling gut motility."},{"id": 1782,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The contraction velocity of skeletal muscle is inversely related to:","options": [{"key": "A","text": "ATP availability only"},{"key": "B","text": "Calcium concentration"},{"key": "C","text": "Load/afterload on the muscle"},{"key": "D","text": "Fiber length"}],"correct": "C","explanation": "Higher load decreases the velocity of muscle shortening (force-velocity relationship)."},{"id": 1783,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "According to the force-velocity relationship, maximum velocity of shortening occurs at:","options": [{"key": "A","text": "Zero load"},{"key": "B","text": "Isometric condition"},{"key": "C","text": "Maximum isometric tension"},{"key": "D","text": "Maximum load"}],"correct": "A","explanation": "At zero load, muscle shortens at its maximum possible velocity."},{"id": 1784,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Treppe (staircase phenomenon) in skeletal muscle refers to:","options": [{"key": "A","text": "Sudden muscle fatigue"},{"key": "B","text": "Progressive increase in twitch tension with repeated stimuli at constant frequency, due to rising calcium"},{"key": "C","text": "Loss of excitability"},{"key": "D","text": "Progressive decrease in twitch tension with repeated stimuli"}],"correct": "B","explanation": "Treppe results from increasing intracellular calcium with successive twitches, raising tension."},{"id": 1785,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Duration of one complete cardiac cycle at a heart rate of 75 beats/min is approximately:","options": [{"key": "A","text": "1.0 sec"},{"key": "B","text": "0.6 sec"},{"key": "C","text": "0.8 sec"},{"key": "D","text": "1.2 sec"}],"correct": "C","explanation": "At 75 bpm, cycle length = 60/75 = 0.8 sec."},{"id": 1786,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "During isovolumetric contraction, the status of the heart valves is:","options": [{"key": "A","text": "Both AV and semilunar valves open"},{"key": "B","text": "AV valves closed, semilunar open"},{"key": "C","text": "AV valves open, semilunar closed"},{"key": "D","text": "Both AV and semilunar valves closed"}],"correct": "D","explanation": "Ventricular pressure rises with no change in volume as all valves remain closed."},{"id": 1787,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Approximate duration of ventricular systole and diastole (at 75 bpm) respectively is:","options": [{"key": "A","text": "0.4 sec and 0.4 sec"},{"key": "B","text": "0.3 sec and 0.5 sec"},{"key": "C","text": "0.2 sec and 0.6 sec"},{"key": "D","text": "0.5 sec and 0.3 sec"}],"correct": "B","explanation": "Systole lasts about 0.3 sec and diastole about 0.5 sec of the 0.8 sec cycle."},{"id": 1788,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Hard","question": "Which AV valve normally closes slightly earlier during the cardiac cycle?","options": [{"key": "A","text": "Both close simultaneously"},{"key": "B","text": "Mitral valve"},{"key": "C","text": "Tricuspid valve"},{"key": "D","text": "Pulmonary valve"}],"correct": "B","explanation": "The mitral valve closes fractionally before the tricuspid valve."},{"id": 1789,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The 'a' wave in the jugular venous pulse corresponds to:","options": [{"key": "A","text": "Atrial contraction"},{"key": "B","text": "Atrial relaxation"},{"key": "C","text": "Ventricular systole"},{"key": "D","text": "Rapid ventricular filling"}],"correct": "A","explanation": "The a wave is produced by right atrial contraction."},{"id": 1790,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Hard","question": "The 'c' wave in the jugular venous pulse is due to:","options": [{"key": "A","text": "Closure of aortic valve"},{"key": "B","text": "Atrial relaxation"},{"key": "C","text": "Opening of the AV valve"},{"key": "D","text": "Bulging of the tricuspid valve into the atrium during isovolumetric contraction"}],"correct": "D","explanation": "Rising ventricular pressure pushes the closed tricuspid valve slightly into the atrium."},{"id": 1791,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The 'v' wave in the jugular venous pulse represents:","options": [{"key": "A","text": "Rapid ventricular ejection"},{"key": "B","text": "Atrial contraction"},{"key": "C","text": "Atrial filling against a closed tricuspid valve"},{"key": "D","text": "Ventricular contraction"}],"correct": "C","explanation": "Blood accumulates in the atrium against the closed AV valve, raising atrial pressure."},{"id": 1792,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The 'x' descent in the JVP curve is caused by:","options": [{"key": "A","text": "Opening of AV valve"},{"key": "B","text": "Closure of semilunar valves"},{"key": "C","text": "Atrial relaxation and downward displacement of the ventricle"},{"key": "D","text": "Rapid atrial filling"}],"correct": "C","explanation": "Atrial relaxation plus the pulling down of the AV ring during ventricular systole causes the x descent."},{"id": 1793,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The 'y' descent in the JVP curve occurs due to:","options": [{"key": "A","text": "Atrial contraction"},{"key": "B","text": "Closure of the AV valve"},{"key": "C","text": "Isovolumetric relaxation"},{"key": "D","text": "Opening of the AV valve and rapid emptying of the atrium"}],"correct": "D","explanation": "When the AV valve opens, blood rushes from atrium to ventricle, causing atrial pressure to fall (y descent)."},{"id": 1794,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Rapid ventricular filling phase is normally associated with which heart sound?","options": [{"key": "A","text": "S2"},{"key": "B","text": "S4"},{"key": "C","text": "S3"},{"key": "D","text": "S1"}],"correct": "C","explanation": "The third heart sound (S3), when audible, occurs during rapid ventricular filling."},{"id": 1795,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Isovolumetric relaxation occurs between which two events?","options": [{"key": "A","text": "Aortic valve opening and mitral valve closure"},{"key": "B","text": "P wave and QRS complex"},{"key": "C","text": "Mitral valve opening and closing"},{"key": "D","text": "Aortic valve closure and mitral valve opening"}],"correct": "D","explanation": "Ventricular pressure falls with all valves closed, between aortic closure and mitral opening."},{"id": 1796,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The dicrotic notch on the aortic pressure curve is produced by:","options": [{"key": "A","text": "Closure of the aortic valve"},{"key": "B","text": "Closure of the mitral valve"},{"key": "C","text": "Opening of the aortic valve"},{"key": "D","text": "Atrial contraction"}],"correct": "A","explanation": "A brief backflow of blood closes the aortic valve, producing the notch."},{"id": 1797,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Atrial systole occurs in which part of the ECG-cardiac cycle relationship?","options": [{"key": "A","text": "After the T wave"},{"key": "B","text": "During the T wave"},{"key": "C","text": "Immediately after the P wave"},{"key": "D","text": "During the QRS complex"}],"correct": "C","explanation": "Atrial depolarization (P wave) is followed almost immediately by atrial contraction."},{"id": 1798,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal end-diastolic volume (EDV) of the left ventricle is approximately:","options": [{"key": "A","text": "180 ml"},{"key": "B","text": "60 ml"},{"key": "C","text": "130 ml"},{"key": "D","text": "90 ml"}],"correct": "C","explanation": "EDV is normally about 120-130 ml."},{"id": 1799,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal end-systolic volume (ESV) of the left ventricle is approximately:","options": [{"key": "A","text": "30 ml"},{"key": "B","text": "90 ml"},{"key": "C","text": "60 ml"},{"key": "D","text": "110 ml"}],"correct": "C","explanation": "ESV is normally about 50-60 ml, remaining after ejection."},{"id": 1800,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Stroke volume is calculated as:","options": [{"key": "A","text": "ESV - EDV"},{"key": "B","text": "EDV x ESV"},{"key": "C","text": "EDV + ESV"},{"key": "D","text": "EDV - ESV"}],"correct": "D","explanation": "Stroke volume = End diastolic volume minus end systolic volume."},{"id": 1801,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal resting ejection fraction of the left ventricle is:","options": [{"key": "A","text": "55-65%"},{"key": "B","text": "40-50%"},{"key": "C","text": "70-80%"},{"key": "D","text": "25-35%"}],"correct": "A","explanation": "Ejection fraction (SV/EDV x 100) is normally 55-65%."},{"id": 1802,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Atrial contraction ('atrial kick') contributes approximately how much to ventricular filling at rest?","options": [{"key": "A","text": "20-30%"},{"key": "B","text": "50%"},{"key": "C","text": "70%"},{"key": "D","text": "5%"}],"correct": "A","explanation": "Atrial systole normally contributes about 20-30% of ventricular filling."},{"id": 1803,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The longest phase of the cardiac cycle at normal resting heart rate is:","options": [{"key": "A","text": "Diastole (filling period)"},{"key": "B","text": "Isovolumetric relaxation"},{"key": "C","text": "Ejection phase"},{"key": "D","text": "Isovolumetric contraction"}],"correct": "A","explanation": "Diastole (~0.5 sec) is longer than systole (~0.3 sec) at rest."},{"id": 1804,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The Wiggers diagram classically plots which of the following against time in a single cardiac cycle?","options": [{"key": "A","text": "Only ventricular volume"},{"key": "B","text": "Only ECG"},{"key": "C","text": "Only heart sounds"},{"key": "D","text": "Aortic, atrial and ventricular pressures, ventricular volume, ECG and heart sounds"}],"correct": "D","explanation": "Wiggers diagram integrates pressure, volume, ECG and phonocardiogram events across the cycle."},{"id": 1805,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The P wave of the ECG represents:","options": [{"key": "A","text": "Ventricular repolarization"},{"key": "B","text": "Ventricular depolarization"},{"key": "C","text": "Atrial repolarization"},{"key": "D","text": "Atrial depolarization"}],"correct": "D","explanation": "P wave corresponds to spread of depolarization over the atria."},{"id": 1806,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The QRS complex of the ECG represents:","options": [{"key": "A","text": "Ventricular repolarization"},{"key": "B","text": "Atrial repolarization"},{"key": "C","text": "Atrial depolarization"},{"key": "D","text": "Ventricular depolarization"}],"correct": "D","explanation": "QRS complex reflects rapid depolarization of the ventricles."},{"id": 1807,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The T wave of the ECG represents:","options": [{"key": "A","text": "Ventricular depolarization"},{"key": "B","text": "Ventricular repolarization"},{"key": "C","text": "SA nodal discharge"},{"key": "D","text": "Atrial depolarization"}],"correct": "B","explanation": "T wave corresponds to ventricular repolarization."},{"id": 1808,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal duration of the PR interval is:","options": [{"key": "A","text": "0.20-0.30 sec"},{"key": "B","text": "0.12-0.20 sec"},{"key": "C","text": "0.04-0.08 sec"},{"key": "D","text": "0.30-0.40 sec"}],"correct": "B","explanation": "PR interval normally measures 0.12 to 0.20 seconds."},{"id": 1809,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal duration of the QRS complex is:","options": [{"key": "A","text": "0.20-0.30 sec"},{"key": "B","text": "0.12-0.20 sec"},{"key": "C","text": "0.06-0.10 sec"},{"key": "D","text": "0.02-0.04 sec"}],"correct": "C","explanation": "Normal QRS duration is 0.06 to 0.10 seconds."},{"id": 1810,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The QT interval represents:","options": [{"key": "A","text": "Atrial depolarization only"},{"key": "B","text": "Total duration of ventricular depolarization and repolarization"},{"key": "C","text": "Ventricular repolarization only"},{"key": "D","text": "AV nodal delay"}],"correct": "B","explanation": "QT interval spans from onset of ventricular depolarization to end of repolarization."},{"id": 1811,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Atrial repolarization is not usually visible on a surface ECG because:","options": [{"key": "A","text": "It occurs simultaneously with the P wave"},{"key": "B","text": "It is buried within the larger QRS complex"},{"key": "C","text": "It does not occur"},{"key": "D","text": "It occurs after the T wave"}],"correct": "B","explanation": "The small atrial repolarization wave is masked by the much larger QRS complex."},{"id": 1812,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Hard","question": "The U wave, when present on ECG, is thought to be due to:","options": [{"key": "A","text": "SA nodal depolarization"},{"key": "B","text": "Repolarization of papillary muscles/Purkinje fibers"},{"key": "C","text": "Atrial depolarization"},{"key": "D","text": "AV nodal repolarization"}],"correct": "B","explanation": "The U wave is attributed to slow repolarization of papillary muscles or Purkinje fibers."},{"id": 1813,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Standard limb lead I records the potential difference between:","options": [{"key": "A","text": "Right arm and left leg"},{"key": "B","text": "Left arm and left leg"},{"key": "C","text": "Right arm and right leg"},{"key": "D","text": "Right arm and left arm"}],"correct": "D","explanation": "Lead I = Left arm (positive) minus Right arm (negative)."},{"id": 1814,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The augmented limb leads of a standard 12-lead ECG are:","options": [{"key": "A","text": "V4, V5, V6"},{"key": "B","text": "aVR, aVL, aVF"},{"key": "C","text": "I, II, III"},{"key": "D","text": "V1, V2, V3"}],"correct": "B","explanation": "aVR, aVL and aVF are the three augmented unipolar limb leads."},{"id": 1815,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The total number of standard chest (precordial) leads in a 12-lead ECG is:","options": [{"key": "A","text": "12"},{"key": "B","text": "9"},{"key": "C","text": "6"},{"key": "D","text": "3"}],"correct": "C","explanation": "There are six chest leads, V1 through V6."},{"id": 1816,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Standard ECG paper speed is:","options": [{"key": "A","text": "50 mm/sec"},{"key": "B","text": "12.5 mm/sec"},{"key": "C","text": "100 mm/sec"},{"key": "D","text": "25 mm/sec"}],"correct": "D","explanation": "Standard recording speed is 25 mm per second."},{"id": 1817,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "At standard paper speed, one small square on ECG paper corresponds to:","options": [{"key": "A","text": "0.40 sec"},{"key": "B","text": "0.04 sec"},{"key": "C","text": "0.20 sec"},{"key": "D","text": "0.01 sec"}],"correct": "B","explanation": "One small square (1 mm) = 0.04 seconds at 25 mm/sec."},{"id": 1818,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "At standard paper speed, one large square on ECG paper corresponds to:","options": [{"key": "A","text": "0.20 sec"},{"key": "B","text": "0.50 sec"},{"key": "C","text": "0.10 sec"},{"key": "D","text": "0.04 sec"}],"correct": "A","explanation": "One large square (5 mm) = 0.20 seconds at 25 mm/sec."},{"id": 1819,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "A quick method to estimate heart rate from a regular ECG is:","options": [{"key": "A","text": "60 divided by PR interval"},{"key": "B","text": "1500 divided by QRS duration"},{"key": "C","text": "300 divided by number of large squares between R waves"},{"key": "D","text": "HR = P wave rate x 2"}],"correct": "C","explanation": "Heart rate (bpm) = 300 / number of large squares between successive R waves."},{"id": 1820,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The normal intrinsic firing rate of the SA node is:","options": [{"key": "A","text": "20-40/min"},{"key": "B","text": "100-120/min"},{"key": "C","text": "60-100/min"},{"key": "D","text": "40-60/min"}],"correct": "C","explanation": "The SA node, the primary pacemaker, normally discharges at 60-100 beats/min."},{"id": 1821,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The intrinsic firing rate of the AV node (in absence of SA node input) is approximately:","options": [{"key": "A","text": "40-60/min"},{"key": "B","text": "15-40/min"},{"key": "C","text": "60-100/min"},{"key": "D","text": "100-140/min"}],"correct": "A","explanation": "The AV node's intrinsic pacemaker rate is about 40-60/min."},{"id": 1822,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The intrinsic firing rate of the Purkinje fiber system is approximately:","options": [{"key": "A","text": "40-60/min"},{"key": "B","text": "80-100/min"},{"key": "C","text": "60-80/min"},{"key": "D","text": "15-40/min"}],"correct": "D","explanation": "Purkinje fibers have the slowest intrinsic rate, about 15-40/min."},{"id": 1823,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The first negative deflection of the QRS complex, if present, is called:","options": [{"key": "A","text": "Q wave"},{"key": "B","text": "R wave"},{"key": "C","text": "S wave"},{"key": "D","text": "T wave"}],"correct": "A","explanation": "The Q wave is the initial downward deflection of the QRS complex."},{"id": 1824,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The ST segment normally represents:","options": [{"key": "A","text": "Ventricular depolarization"},{"key": "B","text": "AV nodal conduction delay"},{"key": "C","text": "The plateau phase when the entire ventricle is depolarized"},{"key": "D","text": "Atrial repolarization"}],"correct": "C","explanation": "ST segment is isoelectric, corresponding to the plateau phase of the ventricular action potential."},{"id": 1825,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Cardiac output is calculated as:","options": [{"key": "A","text": "Heart rate x Stroke volume"},{"key": "B","text": "Heart rate / Stroke volume"},{"key": "C","text": "Heart rate + Stroke volume"},{"key": "D","text": "Stroke volume / Heart rate"}],"correct": "A","explanation": "CO (L/min) = Heart rate (beats/min) x Stroke volume (L/beat)."},{"id": 1826,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Normal resting cardiac output in an average adult is approximately:","options": [{"key": "A","text": "5 L/min"},{"key": "B","text": "12 L/min"},{"key": "C","text": "2 L/min"},{"key": "D","text": "8 L/min"}],"correct": "A","explanation": "Resting cardiac output averages about 5 L/min."},{"id": 1827,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Cardiac index is defined as:","options": [{"key": "A","text": "Cardiac output / heart rate"},{"key": "B","text": "Cardiac output / body surface area"},{"key": "C","text": "Stroke volume / body surface area"},{"key": "D","text": "Cardiac output x body surface area"}],"correct": "B","explanation": "Cardiac index normalizes cardiac output to body surface area (CO/BSA)."},{"id": 1828,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Normal value of cardiac index is approximately:","options": [{"key": "A","text": "9-10 L/min/m2"},{"key": "B","text": "3-3.5 L/min/m2"},{"key": "C","text": "1-1.5 L/min/m2"},{"key": "D","text": "6-7 L/min/m2"}],"correct": "B","explanation": "Normal cardiac index is about 3.0-3.5 L/min/m2."},{"id": 1829,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The Fick principle for measuring cardiac output uses which formula?","options": [{"key": "A","text": "CO = Oxygen consumption / (Arterial O2 content - Venous O2 content)"},{"key": "B","text": "CO = HR x SV"},{"key": "C","text": "CO = EDV - ESV"},{"key": "D","text": "CO = MAP / TPR"}],"correct": "A","explanation": "Fick's principle: CO = VO2 (ml/min) divided by the arteriovenous O2 content difference."},{"id": 1830,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Which method of cardiac output measurement uses injection of a known substance and measures its concentration downstream over time?","options": [{"key": "A","text": "Echocardiography"},{"key": "B","text": "Doppler method"},{"key": "C","text": "Fick method"},{"key": "D","text": "Indicator (dye) dilution method"}],"correct": "D","explanation": "The indicator/dye dilution method calculates CO from the dilution curve of an injected indicator."},{"id": 1831,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Preload is best defined as:","options": [{"key": "A","text": "The force of ventricular contraction"},{"key": "B","text": "Resistance against which the ventricle ejects blood"},{"key": "C","text": "The degree of ventricular filling/stretch before contraction (end-diastolic volume)"},{"key": "D","text": "Heart rate before systole"}],"correct": "C","explanation": "Preload corresponds to end-diastolic fiber length/volume, i.e., ventricular filling."},{"id": 1832,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Afterload is best defined as:","options": [{"key": "A","text": "Heart rate after exercise"},{"key": "B","text": "The load/resistance the ventricle must overcome to eject blood"},{"key": "C","text": "Venous return to the heart"},{"key": "D","text": "End diastolic volume"}],"correct": "B","explanation": "Afterload is the resistance (e.g., aortic pressure, TPR) opposing ventricular ejection."},{"id": 1833,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The Frank-Starling law of the heart states that:","options": [{"key": "A","text": "Contractility is independent of fiber length"},{"key": "B","text": "Within limits, increased venous return (preload) increases the force of ventricular contraction"},{"key": "C","text": "Afterload has no effect on stroke volume"},{"key": "D","text": "Increased heart rate always increases stroke volume"}],"correct": "B","explanation": "Greater stretch of cardiac muscle fibers (within limits) produces a stronger contraction."},{"id": 1834,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A positive inotropic agent primarily causes:","options": [{"key": "A","text": "Decreased conduction velocity"},{"key": "B","text": "Increased heart rate"},{"key": "C","text": "Decreased preload"},{"key": "D","text": "Increased force of myocardial contraction"}],"correct": "D","explanation": "Inotropy refers to the contractile strength of the myocardium."},{"id": 1835,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "An acute increase in afterload, with contractility and preload constant, tends to:","options": [{"key": "A","text": "Decrease stroke volume"},{"key": "B","text": "Have no effect on stroke volume"},{"key": "C","text": "Increase stroke volume"},{"key": "D","text": "Double the stroke volume"}],"correct": "A","explanation": "Higher resistance to ejection reduces stroke volume if other factors are unchanged."},{"id": 1836,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Bainbridge reflex refers to:","options": [{"key": "A","text": "Increase in heart rate due to increased venous return/atrial stretch"},{"key": "B","text": "Decrease in heart rate due to increased arterial pressure"},{"key": "C","text": "Increase in blood pressure due to hypoxia"},{"key": "D","text": "Decrease in heart rate due to carotid sinus stimulation"}],"correct": "A","explanation": "Stretch of the right atrium increases heart rate via the Bainbridge reflex."},{"id": 1837,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A chronotropic effect refers to a change in:","options": [{"key": "A","text": "Force of contraction"},{"key": "B","text": "Excitability"},{"key": "C","text": "Heart rate"},{"key": "D","text": "Conduction velocity"}],"correct": "C","explanation": "Chronotropic effects alter the rate of the heartbeat."},{"id": 1838,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The three principal determinants of stroke volume are:","options": [{"key": "A","text": "Afterload, heart rate, and respiration rate"},{"key": "B","text": "Preload, afterload, and contractility"},{"key": "C","text": "Contractility, ECG, and blood pressure"},{"key": "D","text": "Heart rate, preload, and blood volume"}],"correct": "B","explanation": "Stroke volume is governed by preload, afterload, and myocardial contractility."},{"id": 1839,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Normal resting stroke volume in an average adult is approximately:","options": [{"key": "A","text": "70 ml"},{"key": "B","text": "30 ml"},{"key": "C","text": "120 ml"},{"key": "D","text": "150 ml"}],"correct": "A","explanation": "Resting stroke volume averages about 70 ml per beat."},{"id": 1840,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Cardiac reserve refers to:","options": [{"key": "A","text": "The volume of blood in the pulmonary circulation"},{"key": "B","text": "The resting cardiac output"},{"key": "C","text": "The ejection fraction at rest"},{"key": "D","text": "The maximum percentage that cardiac output can increase above resting level"}],"correct": "D","explanation": "Cardiac reserve is the heart's capacity to increase output above normal during exertion."},{"id": 1841,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "During strenuous exercise, cardiac output in a healthy young adult may increase up to approximately:","options": [{"key": "A","text": "4-6 times resting value"},{"key": "B","text": "2 times resting value"},{"key": "C","text": "1.5 times resting value"},{"key": "D","text": "10-15 times resting value"}],"correct": "A","explanation": "Cardiac output can rise about 4 to 6 fold during maximal exercise."},{"id": 1842,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Hard","question": "Venous return to the heart is primarily determined by:","options": [{"key": "A","text": "Left ventricular ejection fraction"},{"key": "B","text": "Right atrial pressure and mean systemic filling pressure"},{"key": "C","text": "Pulmonary capillary wedge pressure"},{"key": "D","text": "Aortic valve area"}],"correct": "B","explanation": "Venous return depends on the pressure gradient between mean systemic filling pressure and right atrial pressure."},{"id": 1843,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Sympathetic stimulation of the heart produces which effect on contractility?","options": [{"key": "A","text": "Negative inotropic effect"},{"key": "B","text": "Positive inotropic effect"},{"key": "C","text": "Only chronotropic effect"},{"key": "D","text": "No effect on contractility"}],"correct": "B","explanation": "Sympathetic (noradrenaline) stimulation increases myocardial contractility."},{"id": 1844,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The thermodilution method for measuring cardiac output involves:","options": [{"key": "A","text": "Injecting cold saline into the right atrium and measuring temperature change downstream"},{"key": "B","text": "Injecting a dye and measuring its concentration in arterial blood"},{"key": "C","text": "Measuring oxygen consumption at the mouth"},{"key": "D","text": "Ultrasound measurement of aortic flow"}],"correct": "A","explanation": "A bolus of cold saline is injected, and the resulting temperature change in the pulmonary artery is used to calculate CO."},{"id": 1845,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Normal adult resting arterial blood pressure is considered to be approximately:","options": [{"key": "A","text": "90/60 mmHg"},{"key": "B","text": "140/90 mmHg"},{"key": "C","text": "120/80 mmHg"},{"key": "D","text": "160/100 mmHg"}],"correct": "C","explanation": "Normal blood pressure is conventionally taken as 120/80 mmHg."},{"id": 1846,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Mean arterial pressure (MAP) is calculated as:","options": [{"key": "A","text": "SBP + DBP"},{"key": "B","text": "DBP + 1/3(SBP - DBP)"},{"key": "C","text": "SBP - DBP"},{"key": "D","text": "(SBP + DBP)/3"}],"correct": "B","explanation": "MAP = Diastolic BP + one-third of pulse pressure."},{"id": 1847,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Pulse pressure is defined as:","options": [{"key": "A","text": "MAP - DBP"},{"key": "B","text": "SBP + DBP"},{"key": "C","text": "SBP - DBP"},{"key": "D","text": "SBP x DBP"}],"correct": "C","explanation": "Pulse pressure equals systolic minus diastolic blood pressure."},{"id": 1848,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Arterial baroreceptors are primarily located in:","options": [{"key": "A","text": "Renal afferent arterioles"},{"key": "B","text": "Pulmonary artery"},{"key": "C","text": "Carotid sinus and aortic arch"},{"key": "D","text": "Right atrium"}],"correct": "C","explanation": "Baroreceptors sensing arterial pressure are located in the carotid sinus and aortic arch."},{"id": 1849,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "An acute rise in arterial blood pressure activates the baroreceptor reflex, resulting in:","options": [{"key": "A","text": "Increased sympathetic outflow only"},{"key": "B","text": "No change in heart rate"},{"key": "C","text": "Decreased heart rate and vasodilation"},{"key": "D","text": "Increased heart rate and vasoconstriction"}],"correct": "C","explanation": "Baroreceptor stimulation increases vagal tone and decreases sympathetic outflow, lowering HR and causing vasodilation."},{"id": 1850,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Peripheral chemoreceptors involved in cardiovascular regulation are located in:","options": [{"key": "A","text": "Carotid and aortic bodies"},{"key": "B","text": "Medulla only"},{"key": "C","text": "Renal cortex"},{"key": "D","text": "Hypothalamus"}],"correct": "A","explanation": "Chemoreceptors sensitive to blood gases are found in the carotid and aortic bodies."},{"id": 1851,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Peripheral chemoreceptors are primarily stimulated by:","options": [{"key": "A","text": "Increased pH"},{"key": "B","text": "Decreased pO2, increased pCO2, and decreased pH"},{"key": "C","text": "Increased pO2"},{"key": "D","text": "Decreased pCO2"}],"correct": "B","explanation": "Hypoxia, hypercapnia, and acidosis stimulate the carotid and aortic body chemoreceptors."},{"id": 1852,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Short-term (second-to-minute) regulation of blood pressure is mainly achieved by:","options": [{"key": "A","text": "Kidney fluid excretion"},{"key": "B","text": "Erythropoietin release"},{"key": "C","text": "Renin-angiotensin-aldosterone system"},{"key": "D","text": "Baroreceptor reflex"}],"correct": "D","explanation": "The baroreceptor reflex provides rapid, moment-to-moment control of blood pressure."},{"id": 1853,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Long-term regulation of blood pressure is primarily achieved through:","options": [{"key": "A","text": "Baroreceptor reflex"},{"key": "B","text": "Chemoreceptor reflex"},{"key": "C","text": "Bainbridge reflex"},{"key": "D","text": "Renal control of body fluid volume (pressure-natriuresis / RAAS)"}],"correct": "D","explanation": "Over days, renal mechanisms controlling blood volume dominate long-term BP regulation."},{"id": 1854,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The renin-angiotensin-aldosterone system is triggered mainly by:","options": [{"key": "A","text": "Increased renal blood flow"},{"key": "B","text": "Increased blood volume"},{"key": "C","text": "Decreased renal perfusion pressure/blood flow"},{"key": "D","text": "Hyperkalemia only"}],"correct": "C","explanation": "Reduced renal perfusion stimulates renin release from the juxtaglomerular apparatus."},{"id": 1855,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Angiotensin II produces which of the following effects?","options": [{"key": "A","text": "Vasodilation and decreased aldosterone"},{"key": "B","text": "Vasoconstriction and stimulation of aldosterone release"},{"key": "C","text": "Bradycardia only"},{"key": "D","text": "Natriuresis"}],"correct": "B","explanation": "Angiotensin II is a potent vasoconstrictor and stimulates aldosterone secretion."},{"id": 1856,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "Aldosterone acts on the kidney to cause:","options": [{"key": "A","text": "Potassium retention only"},{"key": "B","text": "Sodium and water loss"},{"key": "C","text": "Sodium and water retention"},{"key": "D","text": "Decreased blood volume"}],"correct": "C","explanation": "Aldosterone promotes renal sodium (and secondary water) reabsorption, raising blood volume/pressure."},{"id": 1857,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Antidiuretic hormone (ADH/vasopressin) is released from the:","options": [{"key": "A","text": "Adrenal medulla"},{"key": "B","text": "Anterior pituitary"},{"key": "C","text": "Adrenal cortex"},{"key": "D","text": "Posterior pituitary (synthesized in hypothalamus)"}],"correct": "D","explanation": "ADH is synthesized in the hypothalamus and released from the posterior pituitary."},{"id": 1858,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The main cardiovascular effects of ADH (vasopressin) are:","options": [{"key": "A","text": "Vasodilation and diuresis"},{"key": "B","text": "Vasoconstriction and water retention"},{"key": "C","text": "No cardiovascular effect"},{"key": "D","text": "Bradycardia and natriuresis"}],"correct": "B","explanation": "ADH causes vasoconstriction and promotes renal water reabsorption."},{"id": 1859,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The primary vasomotor center regulating blood pressure is located in the:","options": [{"key": "A","text": "Cerebral cortex"},{"key": "B","text": "Hypothalamus"},{"key": "C","text": "Medulla oblongata"},{"key": "D","text": "Cerebellum"}],"correct": "C","explanation": "The vasomotor (cardiovascular) center is located in the medulla oblongata."},{"id": 1860,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Cushing reflex, seen with raised intracranial pressure, is characterized by:","options": [{"key": "A","text": "Hypertension and bradycardia"},{"key": "B","text": "Hypotension and bradycardia"},{"key": "C","text": "Hypotension and tachycardia"},{"key": "D","text": "Hypertension and tachycardia"}],"correct": "A","explanation": "Raised ICP triggers a rise in BP with reflex bradycardia (Cushing reflex/triad)."},{"id": 1861,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "On standing up suddenly, the initial transient fall in blood pressure is normally corrected by:","options": [{"key": "A","text": "Bainbridge reflex"},{"key": "B","text": "Baroreceptor reflex"},{"key": "C","text": "Chemoreceptor reflex"},{"key": "D","text": "Renin-angiotensin system only"}],"correct": "B","explanation": "The baroreceptor reflex rapidly compensates for the gravitational pooling of blood on standing."},{"id": 1862,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Orthostatic (postural) hypotension typically results from:","options": [{"key": "A","text": "Hyperaldosteronism"},{"key": "B","text": "Failure/delay of the baroreceptor reflex on standing"},{"key": "C","text": "Overactive baroreceptor reflex"},{"key": "D","text": "Excess parasympathetic tone"}],"correct": "B","explanation": "Inadequate or delayed baroreceptor-mediated compensation causes BP to drop on standing."},{"id": 1863,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Atrial natriuretic peptide (ANP) is released in response to:","options": [{"key": "A","text": "Decreased atrial stretch"},{"key": "B","text": "Increased atrial stretch (volume overload)"},{"key": "C","text": "Hypotension"},{"key": "D","text": "Hypoglycemia"}],"correct": "B","explanation": "ANP is secreted by atrial myocytes when the atria are stretched by increased blood volume."},{"id": 1864,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The overall effect of atrial natriuretic peptide (ANP) on blood pressure is:","options": [{"key": "A","text": "Increases blood pressure via vasoconstriction"},{"key": "B","text": "No effect on blood pressure"},{"key": "C","text": "Decreases blood pressure via natriuresis and vasodilation"},{"key": "D","text": "Increases aldosterone secretion"}],"correct": "C","explanation": "ANP promotes sodium/water excretion and vasodilation, lowering blood pressure."},{"id": 1865,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The first heart sound (S1) is produced by:","options": [{"key": "A","text": "Closure of the semilunar valves"},{"key": "B","text": "Opening of the AV valves"},{"key": "C","text": "Closure of the atrioventricular (mitral and tricuspid) valves"},{"key": "D","text": "Atrial contraction"}],"correct": "C","explanation": "S1 ('lub') results from closure of the mitral and tricuspid valves at the start of systole."},{"id": 1866,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "The second heart sound (S2) is produced by:","options": [{"key": "A","text": "Rapid ventricular filling"},{"key": "B","text": "Closure of the AV valves"},{"key": "C","text": "Closure of the aortic and pulmonary (semilunar) valves"},{"key": "D","text": "Opening of the semilunar valves"}],"correct": "C","explanation": "S2 ('dub') results from closure of the aortic and pulmonary valves at the end of systole."},{"id": 1867,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "A physiological third heart sound (S3) is caused by:","options": [{"key": "A","text": "Turbulence at semilunar valves"},{"key": "B","text": "Closure of AV valves"},{"key": "C","text": "Rapid ventricular filling in early diastole"},{"key": "D","text": "Atrial contraction"}],"correct": "C","explanation": "S3 arises from vibrations during the rapid filling phase and is normal in children/young adults."},{"id": 1868,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The fourth heart sound (S4), when pathological, is associated with:","options": [{"key": "A","text": "Rapid ventricular filling"},{"key": "B","text": "Atrial contraction against a stiff, non-compliant ventricle"},{"key": "C","text": "Closure of semilunar valves"},{"key": "D","text": "Mitral valve opening"}],"correct": "B","explanation": "S4 occurs just before S1, produced by atrial contraction against a hypertrophied/stiff ventricle."},{"id": 1869,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Physiological splitting of the second heart sound is due to:","options": [{"key": "A","text": "Mitral valve closing after tricuspid"},{"key": "B","text": "Aortic valve closing after pulmonary valve, widening with expiration"},{"key": "C","text": "Simultaneous closure of both semilunar valves at all times"},{"key": "D","text": "Pulmonary valve closing slightly after the aortic valve, widening with inspiration"}],"correct": "D","explanation": "The pulmonary valve normally closes slightly later than the aortic valve; the gap widens on inspiration."},{"id": 1870,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Wide splitting of S2 is characteristically seen with:","options": [{"key": "A","text": "Deep inspiration and right bundle branch block"},{"key": "B","text": "Deep expiration only"},{"key": "C","text": "Mitral stenosis"},{"key": "D","text": "Aortic stenosis"}],"correct": "A","explanation": "Inspiration delays pulmonic closure further; RBBB also delays right ventricular depolarization/ejection."},{"id": 1871,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The best auscultatory site for the mitral valve is:","options": [{"key": "A","text": "4th intercostal space, left sternal border"},{"key": "B","text": "2nd intercostal space, left sternal border"},{"key": "C","text": "2nd intercostal space, right sternal border"},{"key": "D","text": "5th intercostal space, left midclavicular line (apex)"}],"correct": "D","explanation": "The mitral area corresponds to the cardiac apex, 5th left intercostal space midclavicular line."},{"id": 1872,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The best auscultatory site for the aortic valve is:","options": [{"key": "A","text": "Apex"},{"key": "B","text": "2nd intercostal space, right sternal border"},{"key": "C","text": "5th intercostal space, left sternal border"},{"key": "D","text": "2nd intercostal space, left sternal border"}],"correct": "B","explanation": "The aortic area is the 2nd right intercostal space near the sternal border."},{"id": 1873,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The best auscultatory site for the pulmonary valve is:","options": [{"key": "A","text": "2nd intercostal space, left sternal border"},{"key": "B","text": "Apex"},{"key": "C","text": "2nd intercostal space, right sternal border"},{"key": "D","text": "Right lower sternal border"}],"correct": "A","explanation": "The pulmonary area is the 2nd left intercostal space near the sternal border."},{"id": 1874,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The best auscultatory site for the tricuspid valve is:","options": [{"key": "A","text": "4th-5th intercostal space, left lower sternal border"},{"key": "B","text": "Apex"},{"key": "C","text": "2nd intercostal space, right sternal border"},{"key": "D","text": "2nd intercostal space, left sternal border"}],"correct": "A","explanation": "The tricuspid area is at the lower left sternal border, 4th-5th intercostal space."},{"id": 1875,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "A cardiac murmur is best described as:","options": [{"key": "A","text": "A synonym for S1"},{"key": "B","text": "A normal heart sound heard in all individuals"},{"key": "C","text": "An abnormal sound produced by turbulent blood flow"},{"key": "D","text": "The sound of atrial contraction"}],"correct": "C","explanation": "Murmurs arise from turbulent, often high-velocity blood flow across abnormal valves or defects."},{"id": 1876,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A murmur heard between S1 and S2 is classified as:","options": [{"key": "A","text": "Presystolic murmur only"},{"key": "B","text": "Continuous murmur"},{"key": "C","text": "Systolic murmur"},{"key": "D","text": "Diastolic murmur"}],"correct": "C","explanation": "Murmurs occurring during ventricular systole (between S1 and S2) are systolic murmurs."},{"id": 1877,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A murmur heard between S2 and the next S1 is classified as:","options": [{"key": "A","text": "Diastolic murmur"},{"key": "B","text": "Systolic murmur"},{"key": "C","text": "Ejection murmur only"},{"key": "D","text": "No murmur possible in this period"}],"correct": "A","explanation": "Murmurs occurring during diastole (between S2 and the following S1) are diastolic murmurs."},{"id": 1878,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A pathological S3 in an adult most commonly indicates:","options": [{"key": "A","text": "Aortic stenosis"},{"key": "B","text": "Normal aging"},{"key": "C","text": "Mitral valve prolapse"},{"key": "D","text": "Volume overload/ventricular (heart) failure"}],"correct": "D","explanation": "In adults, an audible S3 is often a sign of volume overload or systolic heart failure."},{"id": 1879,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A pathological S4 most commonly indicates:","options": [{"key": "A","text": "Normal young healthy heart"},{"key": "B","text": "Tricuspid stenosis"},{"key": "C","text": "Decreased ventricular compliance, as in hypertension or hypertrophy"},{"key": "D","text": "Aortic regurgitation"}],"correct": "C","explanation": "S4 reflects atrial contraction against a stiff ventricle, seen in hypertension/left ventricular hypertrophy."},{"id": 1880,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Coronary blood flow to the left ventricle occurs predominantly during:","options": [{"key": "A","text": "Diastole"},{"key": "B","text": "Equally in systole and diastole"},{"key": "C","text": "Systole"},{"key": "D","text": "Isovolumetric contraction"}],"correct": "A","explanation": "Left ventricular coronary flow occurs mainly in diastole, as systolic compression impedes flow."},{"id": 1881,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Resting coronary blood flow is approximately what percentage of total cardiac output?","options": [{"key": "A","text": "5%"},{"key": "B","text": "15%"},{"key": "C","text": "1%"},{"key": "D","text": "25%"}],"correct": "A","explanation": "Coronary blood flow is normally about 200-250 ml/min, roughly 4-5% of resting cardiac output."},{"id": 1882,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The major determinant of coronary perfusion is:","options": [{"key": "A","text": "Pulmonary artery pressure"},{"key": "B","text": "Aortic diastolic pressure (coronary perfusion pressure)"},{"key": "C","text": "Central venous pressure"},{"key": "D","text": "Systolic aortic pressure"}],"correct": "B","explanation": "Since most coronary flow occurs in diastole, aortic diastolic pressure is the main driving pressure."},{"id": 1883,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Coronary blood flow is chiefly regulated by:","options": [{"key": "A","text": "Sympathetic nervous system exclusively"},{"key": "B","text": "Circulating angiotensin II"},{"key": "C","text": "Renal blood flow"},{"key": "D","text": "Local metabolic factors (autoregulation), especially adenosine"}],"correct": "D","explanation": "Coronary flow is closely matched to myocardial oxygen demand through local metabolic autoregulation."},{"id": 1884,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Adenosine, released during myocardial hypoxia, causes:","options": [{"key": "A","text": "No change in coronary tone"},{"key": "B","text": "Coronary vasoconstriction"},{"key": "C","text": "Systemic vasoconstriction only"},{"key": "D","text": "Coronary vasodilation"}],"correct": "D","explanation": "Adenosine is a potent local vasodilator that increases coronary blood flow during hypoxia."},{"id": 1885,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The left coronary artery predominantly supplies:","options": [{"key": "A","text": "The right ventricle and SA node"},{"key": "B","text": "The pulmonary trunk"},{"key": "C","text": "The right atrium only"},{"key": "D","text": "The left ventricle and interventricular septum"}],"correct": "D","explanation": "The left coronary artery (via LAD and circumflex branches) mainly supplies the left ventricle and septum."},{"id": 1886,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "In most individuals, the SA node is supplied by branches of the:","options": [{"key": "A","text": "Right coronary artery"},{"key": "B","text": "Circumflex artery only"},{"key": "C","text": "Left anterior descending artery"},{"key": "D","text": "Pulmonary artery"}],"correct": "A","explanation": "In about 55-60% of individuals, the SA nodal artery arises from the right coronary artery."},{"id": 1887,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Resting total cerebral blood flow is approximately:","options": [{"key": "A","text": "150 ml/min"},{"key": "B","text": "350 ml/min"},{"key": "C","text": "750 ml/min"},{"key": "D","text": "1500 ml/min"}],"correct": "C","explanation": "Cerebral blood flow at rest is approximately 750 ml/min, about 15% of cardiac output."},{"id": 1888,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Cerebral blood flow autoregulation maintains fairly constant flow over a mean arterial pressure range of approximately:","options": [{"key": "A","text": "60-140 mmHg"},{"key": "B","text": "40-80 mmHg"},{"key": "C","text": "100-180 mmHg"},{"key": "D","text": "20-60 mmHg"}],"correct": "A","explanation": "Cerebral autoregulation keeps flow constant between roughly 60 and 140 mmHg MAP."},{"id": 1889,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The most powerful chemical regulator of cerebral blood flow is:","options": [{"key": "A","text": "Carbon dioxide tension (pCO2)"},{"key": "B","text": "Oxygen tension (pO2)"},{"key": "C","text": "Serum sodium"},{"key": "D","text": "Serum calcium"}],"correct": "A","explanation": "Arterial pCO2 is the most potent regulator; CO2 is a strong cerebral vasodilator."},{"id": 1890,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Hypercapnia (increased pCO2) causes which effect on cerebral vessels?","options": [{"key": "A","text": "Vasoconstriction"},{"key": "B","text": "No effect"},{"key": "C","text": "Autoregulation failure"},{"key": "D","text": "Vasodilation"}],"correct": "D","explanation": "Increased CO2 (and consequent fall in pH) produces cerebral vasodilation, increasing blood flow."},{"id": 1891,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hyperventilation, by lowering pCO2, causes cerebral vessels to:","options": [{"key": "A","text": "Dilate, increasing blood flow"},{"key": "B","text": "Show no change"},{"key": "C","text": "Rupture"},{"key": "D","text": "Constrict, decreasing blood flow"}],"correct": "D","explanation": "Reduced pCO2 from hyperventilation causes cerebral vasoconstriction and reduced blood flow."},{"id": 1892,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The dominant mechanism responsible for cerebral blood flow autoregulation is thought to be:","options": [{"key": "A","text": "Hormonal control by aldosterone"},{"key": "B","text": "Baroreceptor reflex"},{"key": "C","text": "Purely neural control"},{"key": "D","text": "Myogenic mechanism (and local metabolic factors)"}],"correct": "D","explanation": "Intrinsic myogenic responses of cerebral vessels, along with local metabolites, maintain autoregulation."},{"id": 1893,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Compared to the systemic circulation, the pulmonary circulation is characterized by:","options": [{"key": "A","text": "High pressure, high resistance"},{"key": "B","text": "High pressure, low resistance"},{"key": "C","text": "Low pressure, low resistance"},{"key": "D","text": "Low pressure, high resistance"}],"correct": "C","explanation": "The pulmonary circulation is a low-pressure, low-resistance system compared to systemic circulation."},{"id": 1894,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Normal mean pulmonary artery pressure is approximately:","options": [{"key": "A","text": "40 mmHg"},{"key": "B","text": "15 mmHg"},{"key": "C","text": "5 mmHg"},{"key": "D","text": "70 mmHg"}],"correct": "B","explanation": "Mean pulmonary artery pressure is normally about 15 mmHg (systolic/diastolic ~25/8 mmHg)."},{"id": 1895,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Alveolar hypoxia produces which characteristic response in pulmonary vessels?","options": [{"key": "A","text": "Vasoconstriction, opposite to the systemic response"},{"key": "B","text": "No change in vascular tone"},{"key": "C","text": "Vasodilation, unlike systemic vessels"},{"key": "D","text": "Immediate vessel rupture"}],"correct": "A","explanation": "Hypoxic pulmonary vasoconstriction is unique, diverting blood away from poorly ventilated alveoli."},{"id": 1896,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The physiological purpose of hypoxic pulmonary vasoconstriction is to:","options": [{"key": "A","text": "Increase blood flow to poorly ventilated alveoli"},{"key": "B","text": "Decrease systemic blood pressure"},{"key": "C","text": "Match perfusion to ventilation by diverting blood from poorly ventilated areas"},{"key": "D","text": "Increase pulmonary compliance"}],"correct": "C","explanation": "It optimizes ventilation-perfusion matching by redirecting blood to better-ventilated alveoli."},{"id": 1897,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Total pulmonary blood volume is approximately what fraction of total blood volume?","options": [{"key": "A","text": "About 25%"},{"key": "B","text": "About 9%"},{"key": "C","text": "About 1%"},{"key": "D","text": "About 50%"}],"correct": "B","explanation": "The pulmonary circulation normally contains around 450 ml, roughly 9% of total blood volume."},{"id": 1898,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Cutaneous (skin) blood flow is chiefly regulated for the purpose of:","options": [{"key": "A","text": "Hormone synthesis"},{"key": "B","text": "Digestion"},{"key": "C","text": "Waste excretion"},{"key": "D","text": "Thermoregulation"}],"correct": "D","explanation": "Skin blood flow is primarily controlled by the sympathetic nervous system for body temperature regulation."},{"id": 1899,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "During strenuous exercise, skeletal muscle blood flow may increase up to approximately:","options": [{"key": "A","text": "5 times resting value"},{"key": "B","text": "2 times resting value"},{"key": "C","text": "20 times resting value"},{"key": "D","text": "50 times resting value"}],"correct": "C","explanation": "Muscle blood flow can rise roughly 15-20 fold during maximal exercise due to local vasodilation."},{"id": 1900,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Shock is best defined as:","options": [{"key": "A","text": "A state of inadequate tissue perfusion to meet cellular metabolic demands"},{"key": "B","text": "Loss of consciousness only"},{"key": "C","text": "Any episode of tachycardia"},{"key": "D","text": "A state of elevated blood pressure"}],"correct": "A","explanation": "Shock is a syndrome of inadequate perfusion leading to cellular hypoxia and dysfunction."},{"id": 1901,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The major categories of shock include all of the following EXCEPT:","options": [{"key": "A","text": "Distributive (septic/anaphylactic/neurogenic)"},{"key": "B","text": "Hypovolemic"},{"key": "C","text": "Cardiogenic"},{"key": "D","text": "Hypertensive"}],"correct": "D","explanation": "Hypertensive shock is not a recognized category; the main types are hypovolemic, cardiogenic, distributive, and obstructive."},{"id": 1902,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Hypovolemic shock is primarily caused by:","options": [{"key": "A","text": "Massive vasodilation"},{"key": "B","text": "Obstruction to venous return"},{"key": "C","text": "Pump (myocardial) failure"},{"key": "D","text": "Loss of blood or fluid volume"}],"correct": "D","explanation": "Hypovolemic shock results from significant blood or fluid loss reducing circulating volume."},{"id": 1903,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Cardiogenic shock is primarily caused by:","options": [{"key": "A","text": "Severe hemorrhage"},{"key": "B","text": "Massive allergic reaction"},{"key": "C","text": "Spinal cord injury"},{"key": "D","text": "Failure of the heart as a pump, e.g., after myocardial infarction"}],"correct": "D","explanation": "Cardiogenic shock arises when the heart cannot pump sufficient blood to meet demand."},{"id": 1904,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Anaphylactic shock primarily results from:","options": [{"key": "A","text": "Loss of sympathetic tone after spinal injury"},{"key": "B","text": "Massive histamine release causing widespread vasodilation and increased permeability"},{"key": "C","text": "Pulmonary embolism"},{"key": "D","text": "Myocardial infarction"}],"correct": "B","explanation": "A severe allergic reaction triggers histamine-mediated vasodilation and capillary leak."},{"id": 1905,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Neurogenic shock is characteristically caused by:","options": [{"key": "A","text": "Acute blood loss"},{"key": "B","text": "Sudden loss of sympathetic vascular tone (e.g., spinal cord injury), causing vasodilation and bradycardia"},{"key": "C","text": "Cardiac tamponade"},{"key": "D","text": "Bacterial toxin release"}],"correct": "B","explanation": "Loss of sympathetic outflow leads to vasodilation and often bradycardia in neurogenic shock."},{"id": 1906,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Septic shock is primarily caused by:","options": [{"key": "A","text": "Cardiac arrhythmia"},{"key": "B","text": "Anaphylaxis"},{"key": "C","text": "Acute hemorrhage"},{"key": "D","text": "Severe infection leading to systemic vasodilation via inflammatory mediators/endotoxins"}],"correct": "D","explanation": "Septic shock results from an overwhelming infection triggering widespread inflammatory vasodilation."},{"id": 1907,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Early compensatory mechanisms activated in shock typically include:","options": [{"key": "A","text": "Immediate cardiac arrest"},{"key": "B","text": "Decreased sympathetic activity"},{"key": "C","text": "Tachycardia, peripheral vasoconstriction, and tachypnea"},{"key": "D","text": "Bradycardia and vasodilation"}],"correct": "C","explanation": "The body compensates for falling perfusion with sympathetically-mediated tachycardia and vasoconstriction."},{"id": 1908,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Irreversible shock is characterized by:","options": [{"key": "A","text": "Complete recovery with fluid replacement"},{"key": "B","text": "Mild, self-limiting hypotension"},{"key": "C","text": "Increased urine output"},{"key": "D","text": "Cellular and organ damage so severe that death occurs despite treatment"}],"correct": "D","explanation": "In irreversible shock, cellular injury has progressed to the point that therapy cannot prevent death."},{"id": 1909,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Progressive shock is characterized by:","options": [{"key": "A","text": "Self-correcting positive feedback loops that improve perfusion"},{"key": "B","text": "Absence of any compensatory mechanism"},{"key": "C","text": "Positive feedback (vicious cycle) mechanisms that worsen the shock state"},{"key": "D","text": "Complete return to normal without intervention"}],"correct": "C","explanation": "In progressive shock, deteriorating perfusion triggers vicious cycles that further reduce cardiac output."},{"id": 1910,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "A common renal finding in shock, due to reduced renal perfusion, is:","options": [{"key": "A","text": "Polyuria"},{"key": "B","text": "Oliguria (reduced urine output)"},{"key": "C","text": "Glucosuria"},{"key": "D","text": "Normal urine output"}],"correct": "B","explanation": "Reduced renal blood flow in shock leads to decreased glomerular filtration and oliguria."},{"id": 1911,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "According to ATLS classification, Class I hemorrhage involves blood loss of approximately:","options": [{"key": "A","text": "Less than 15% of blood volume"},{"key": "B","text": "30-40% of blood volume"},{"key": "C","text": "More than 40% of blood volume"},{"key": "D","text": "15-30% of blood volume"}],"correct": "A","explanation": "Class I hemorrhage is defined as blood loss of up to 15% of total blood volume."},{"id": 1912,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "According to ATLS classification, Class II hemorrhage involves blood loss of approximately:","options": [{"key": "A","text": "More than 40%"},{"key": "B","text": "15-30%"},{"key": "C","text": "Less than 15%"},{"key": "D","text": "30-40%"}],"correct": "B","explanation": "Class II hemorrhage corresponds to a blood loss of 15-30% of total blood volume."},{"id": 1913,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cold, clammy skin is a classic clinical sign of which type of shock?","options": [{"key": "A","text": "Neurogenic shock"},{"key": "B","text": "Hypovolemic or cardiogenic shock (due to intense vasoconstriction)"},{"key": "C","text": "Anaphylactic shock"},{"key": "D","text": "Septic shock (warm phase)"}],"correct": "B","explanation": "Marked sympathetic vasoconstriction in hypovolemic/cardiogenic shock produces cold, clammy skin."},{"id": 1914,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Warm, flushed skin is typically seen in the early stage of which type of shock?","options": [{"key": "A","text": "Septic (distributive) shock"},{"key": "B","text": "Hypovolemic shock"},{"key": "C","text": "Cardiogenic shock"},{"key": "D","text": "Obstructive shock"}],"correct": "A","explanation": "Early (warm) septic shock is characterized by vasodilation, producing warm, flushed skin."},{"id": 1915,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "The functional unit of the kidney is the:","options": [{"key": "A","text": "Glomerulus alone"},{"key": "B","text": "Renal pyramid"},{"key": "C","text": "Collecting duct"},{"key": "D","text": "Nephron"}],"correct": "D","explanation": "The nephron, comprising the renal corpuscle and tubule, is the basic functional unit of the kidney."},{"id": 1916,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Approximate total number of nephrons per kidney is:","options": [{"key": "A","text": "10,000"},{"key": "B","text": "10 million"},{"key": "C","text": "1.2 million"},{"key": "D","text": "100,000"}],"correct": "C","explanation": "Each kidney contains approximately 1 to 1.2 million nephrons."},{"id": 1917,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The two main types of nephrons, based on the location of their glomeruli, are:","options": [{"key": "A","text": "Cortical and juxtamedullary nephrons"},{"key": "B","text": "Proximal and distal nephrons"},{"key": "C","text": "Afferent and efferent nephrons"},{"key": "D","text": "Short and long loop nephrons only"}],"correct": "A","explanation": "Nephrons are classified as cortical (short loops) or juxtamedullary (long loops extending into the medulla)."},{"id": 1918,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Juxtamedullary nephrons, compared to cortical nephrons, are characterized by:","options": [{"key": "A","text": "Absence of a loop of Henle"},{"key": "B","text": "Longer loops of Henle extending deep into the medulla, important for urine concentration"},{"key": "C","text": "Location entirely within the cortex"},{"key": "D","text": "Shorter loops of Henle"}],"correct": "B","explanation": "Juxtamedullary nephrons have long loops of Henle that create the medullary concentration gradient."},{"id": 1919,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Blood entering the glomerulus arrives via the:","options": [{"key": "A","text": "Renal vein"},{"key": "B","text": "Afferent arteriole"},{"key": "C","text": "Efferent arteriole"},{"key": "D","text": "Vasa recta"}],"correct": "B","explanation": "The afferent arteriole carries blood into the glomerular capillary tuft."},{"id": 1920,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Blood leaves the glomerulus via the:","options": [{"key": "A","text": "Efferent arteriole"},{"key": "B","text": "Renal artery"},{"key": "C","text": "Afferent arteriole"},{"key": "D","text": "Interlobular vein"}],"correct": "A","explanation": "The efferent arteriole carries blood away from the glomerulus toward the peritubular capillaries."},{"id": 1921,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The juxtaglomerular apparatus is composed of:","options": [{"key": "A","text": "Only podocytes"},{"key": "B","text": "Only the loop of Henle"},{"key": "C","text": "Only the macula densa"},{"key": "D","text": "Macula densa, juxtaglomerular cells, and extraglomerular mesangial cells"}],"correct": "D","explanation": "The JGA consists of the macula densa (distal tubule), juxtaglomerular cells (afferent arteriole), and mesangial cells."},{"id": 1922,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The macula densa is located in the wall of the:","options": [{"key": "A","text": "Bowman's capsule"},{"key": "B","text": "Thick ascending limb of the loop of Henle / early distal tubule"},{"key": "C","text": "Collecting duct"},{"key": "D","text": "Proximal convoluted tubule"}],"correct": "B","explanation": "The macula densa is a specialized segment of the thick ascending limb/early distal tubule adjacent to its own glomerulus."},{"id": 1923,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Juxtaglomerular cells, located in the afferent arteriole wall, primarily secrete:","options": [{"key": "A","text": "Aldosterone"},{"key": "B","text": "Renin"},{"key": "C","text": "Antidiuretic hormone"},{"key": "D","text": "Erythropoietin"}],"correct": "B","explanation": "Juxtaglomerular (granular) cells synthesize and release renin in response to decreased renal perfusion."},{"id": 1924,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Podocytes are specialized cells found in the:","options": [{"key": "A","text": "Loop of Henle"},{"key": "B","text": "Proximal tubule"},{"key": "C","text": "Collecting duct"},{"key": "D","text": "Visceral layer of Bowman's capsule, forming part of the filtration barrier"}],"correct": "D","explanation": "Podocytes wrap around glomerular capillaries with foot processes, forming filtration slits."},{"id": 1925,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "The glomerular filtration barrier consists of which three layers?","options": [{"key": "A","text": "Proximal tubule epithelium only"},{"key": "B","text": "Only podocytes and mesangial cells"},{"key": "C","text": "Only the basement membrane"},{"key": "D","text": "Fenestrated capillary endothelium, glomerular basement membrane, and podocyte filtration slits"}],"correct": "D","explanation": "The filtration barrier comprises the fenestrated endothelium, basement membrane, and podocyte slit diaphragms."},{"id": 1926,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Approximately what percentage of resting cardiac output is delivered to the kidneys?","options": [{"key": "A","text": "50%"},{"key": "B","text": "20-25%"},{"key": "C","text": "5%"},{"key": "D","text": "75%"}],"correct": "B","explanation": "The kidneys receive a disproportionately large share, about 20-25% of resting cardiac output, despite their small mass."},{"id": 1927,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Normal renal blood flow is approximately:","options": [{"key": "A","text": "3000 ml/min"},{"key": "B","text": "1200 ml/min"},{"key": "C","text": "250 ml/min"},{"key": "D","text": "500 ml/min"}],"correct": "B","explanation": "Total renal blood flow is normally around 1200 ml/min (about 20-25% of cardiac output)."},{"id": 1928,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The vasa recta are specialized capillaries associated with:","options": [{"key": "A","text": "The afferent arteriole only"},{"key": "B","text": "The loops of Henle of juxtamedullary nephrons, important for the countercurrent exchange system"},{"key": "C","text": "Bowman's capsule"},{"key": "D","text": "Cortical nephrons only"}],"correct": "B","explanation": "Vasa recta run parallel to juxtamedullary loops of Henle and help preserve the medullary osmotic gradient."},{"id": 1929,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Which segment of the nephron is primarily responsible for bulk (about two-thirds) reabsorption of filtered water, sodium, and glucose?","options": [{"key": "A","text": "Thin descending limb"},{"key": "B","text": "Proximal convoluted tubule"},{"key": "C","text": "Collecting duct"},{"key": "D","text": "Distal convoluted tubule"}],"correct": "B","explanation": "The proximal convoluted tubule reabsorbs about 65-70% of filtered sodium, water, and virtually all glucose under normal conditions."},{"id": 1930,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "Glomerular filtration rate (GFR) is defined as:","options": [{"key": "A","text": "Volume of blood flowing through the kidneys per minute"},{"key": "B","text": "Volume of plasma cleared of a substance per minute (same as GFR concept but distinct definition)"},{"key": "C","text": "Volume of urine excreted per minute"},{"key": "D","text": "Volume of filtrate formed by both kidneys per minute"}],"correct": "D","explanation": "GFR is the total volume of plasma filtered by all glomeruli per unit time."},{"id": 1931,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "Normal GFR in an average adult is approximately:","options": [{"key": "A","text": "125 ml/min"},{"key": "B","text": "50 ml/min"},{"key": "C","text": "300 ml/min"},{"key": "D","text": "600 ml/min"}],"correct": "A","explanation": "Normal GFR is approximately 120-125 ml/min (about 180 L/day)."},{"id": 1932,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "The three forces determining net filtration pressure at the glomerulus include all of the following EXCEPT:","options": [{"key": "A","text": "Bowman's capsule hydrostatic pressure"},{"key": "B","text": "Glomerular capillary hydrostatic pressure"},{"key": "C","text": "Glomerular capillary oncotic (colloid osmotic) pressure"},{"key": "D","text": "Renal tubular fluid flow rate"}],"correct": "D","explanation": "Net filtration pressure depends on glomerular capillary hydrostatic pressure, Bowman's capsule pressure, and capillary oncotic pressure - not tubular flow rate directly."},{"id": 1933,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Net filtration pressure at the glomerulus is calculated as:","options": [{"key": "A","text": "Bowman's capsule pressure - Glomerular hydrostatic pressure"},{"key": "B","text": "Glomerular hydrostatic pressure + Bowman's capsule pressure + Glomerular oncotic pressure"},{"key": "C","text": "Glomerular hydrostatic pressure - Bowman's capsule pressure - Glomerular oncotic pressure"},{"key": "D","text": "Glomerular oncotic pressure alone"}],"correct": "C","explanation": "NFP = Glomerular capillary hydrostatic pressure - Bowman's capsule hydrostatic pressure - Glomerular capillary oncotic pressure."},{"id": 1934,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal glomerular capillary hydrostatic pressure is approximately:","options": [{"key": "A","text": "100 mmHg"},{"key": "B","text": "60 mmHg"},{"key": "C","text": "10 mmHg"},{"key": "D","text": "18 mmHg"}],"correct": "B","explanation": "Glomerular capillary hydrostatic pressure is normally about 60 mmHg, higher than typical systemic capillaries."},{"id": 1935,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "An ideal substance used to measure GFR by clearance methods should be:","options": [{"key": "A","text": "Actively reabsorbed only"},{"key": "B","text": "Bound extensively to plasma proteins"},{"key": "C","text": "Freely filtered, and neither reabsorbed nor secreted by the tubules"},{"key": "D","text": "Actively secreted only"}],"correct": "C","explanation": "A GFR marker must be freely filtered at the glomerulus with no net tubular reabsorption or secretion, such as inulin."},{"id": 1936,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "The gold-standard exogenous substance for measuring GFR is:","options": [{"key": "A","text": "Sodium"},{"key": "B","text": "Glucose"},{"key": "C","text": "Urea"},{"key": "D","text": "Inulin"}],"correct": "D","explanation": "Inulin is freely filtered and neither reabsorbed nor secreted, making its clearance equal to GFR."},{"id": 1937,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "Clinically, GFR is most commonly estimated using the clearance of:","options": [{"key": "A","text": "Glucose"},{"key": "B","text": "Inulin"},{"key": "C","text": "Albumin"},{"key": "D","text": "Creatinine"}],"correct": "D","explanation": "Creatinine clearance, though slightly overestimating true GFR due to minor tubular secretion, is the standard clinical estimate."},{"id": 1938,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Clearance of a substance is calculated using the formula:","options": [{"key": "A","text": "Clearance = Plasma concentration x Urine flow rate"},{"key": "B","text": "Clearance = Urine flow rate only"},{"key": "C","text": "Clearance = (Urine concentration x Urine flow rate) / Plasma concentration"},{"key": "D","text": "Clearance = Plasma concentration / Urine concentration"}],"correct": "C","explanation": "Renal clearance = (Urine concentration x Urine flow rate) / Plasma concentration of the substance."},{"id": 1939,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "If the clearance of a substance is less than the GFR (as measured by inulin), the substance is likely:","options": [{"key": "A","text": "Net reabsorbed by the tubules"},{"key": "B","text": "Actively secreted"},{"key": "C","text": "Neither filtered nor reabsorbed"},{"key": "D","text": "Toxic to the kidney"}],"correct": "A","explanation": "A clearance lower than GFR indicates net tubular reabsorption of the substance."},{"id": 1940,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "If the clearance of a substance exceeds GFR, the substance is likely:","options": [{"key": "A","text": "Net secreted by the tubules"},{"key": "B","text": "Not filtered at all"},{"key": "C","text": "Net reabsorbed"},{"key": "D","text": "Bound to plasma proteins completely"}],"correct": "A","explanation": "A clearance greater than GFR indicates net tubular secretion adds to the filtered amount."},{"id": 1941,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Para-aminohippuric acid (PAH) clearance is used clinically to estimate:","options": [{"key": "A","text": "Tubular reabsorption of glucose"},{"key": "B","text": "Urine osmolality"},{"key": "C","text": "Glomerular filtration rate"},{"key": "D","text": "Effective renal plasma flow"}],"correct": "D","explanation": "PAH is almost completely cleared from plasma in one pass (filtered + secreted), so its clearance approximates renal plasma flow."},{"id": 1942,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Autoregulation of GFR and renal blood flow is maintained over a mean arterial pressure range of approximately:","options": [{"key": "A","text": "20-40 mmHg"},{"key": "B","text": "40-60 mmHg"},{"key": "C","text": "200-250 mmHg"},{"key": "D","text": "80-180 mmHg"}],"correct": "D","explanation": "Renal autoregulation keeps GFR/RBF relatively constant across a MAP range of roughly 80 to 180 mmHg."},{"id": 1943,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "The myogenic mechanism of renal autoregulation refers to:","options": [{"key": "A","text": "Tubuloglomerular feedback via the macula densa"},{"key": "B","text": "Sympathetic nervous control only"},{"key": "C","text": "Vasodilation of afferent arterioles in response to decreased pressure/stretch"},{"key": "D","text": "Hormonal regulation by aldosterone"}],"correct": "C","explanation": "The myogenic mechanism causes vascular smooth muscle to constrict when stretched by increased pressure and relax when pressure falls, stabilizing flow."},{"id": 1944,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Tubuloglomerular feedback involves signaling from the:","options": [{"key": "A","text": "Proximal tubule to the efferent arteriole"},{"key": "B","text": "Collecting duct to the renal artery"},{"key": "C","text": "Loop of Henle to the renal vein"},{"key": "D","text": "Macula densa (sensing distal tubular NaCl) to the afferent arteriole"}],"correct": "D","explanation": "Increased NaCl delivery to the macula densa triggers afferent arteriolar constriction, reducing GFR (tubuloglomerular feedback)."},{"id": 1945,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Constriction of the afferent arteriole would be expected to:","options": [{"key": "A","text": "Decrease GFR"},{"key": "B","text": "Have no effect on GFR"},{"key": "C","text": "Increase GFR"},{"key": "D","text": "Only affect renal blood flow, not GFR"}],"correct": "A","explanation": "Afferent arteriolar constriction reduces glomerular blood flow and hydrostatic pressure, decreasing GFR."},{"id": 1946,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Mild to moderate constriction of the efferent arteriole would be expected to:","options": [{"key": "A","text": "Increase GFR (by raising glomerular hydrostatic pressure)"},{"key": "B","text": "Have no effect on filtration"},{"key": "C","text": "Decrease GFR"},{"key": "D","text": "Stop filtration completely"}],"correct": "A","explanation": "Moderate efferent constriction increases glomerular capillary pressure, initially raising GFR (though renal blood flow falls)."},{"id": 1947,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Hard","question": "Severe/marked constriction of the efferent arteriole ultimately causes GFR to:","options": [{"key": "A","text": "Remain completely unaffected"},{"key": "B","text": "Fall, due to increased filtration fraction raising plasma oncotic pressure and reduced renal blood flow"},{"key": "C","text": "Immediately double"},{"key": "D","text": "Continue rising indefinitely"}],"correct": "B","explanation": "With severe efferent constriction, reduced renal plasma flow and rising oncotic pressure eventually reduce net filtration."},{"id": 1948,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Filtration fraction is defined as:","options": [{"key": "A","text": "Renal plasma flow / GFR"},{"key": "B","text": "Urine flow rate / GFR"},{"key": "C","text": "GFR / Renal plasma flow"},{"key": "D","text": "GFR x Renal blood flow"}],"correct": "C","explanation": "Filtration fraction = GFR divided by renal plasma flow, normally about 0.2 (20%)."},{"id": 1949,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Normal filtration fraction is approximately:","options": [{"key": "A","text": "5%"},{"key": "B","text": "50%"},{"key": "C","text": "20%"},{"key": "D","text": "80%"}],"correct": "C","explanation": "Filtration fraction is normally around 20%, meaning about one-fifth of plasma flowing through the glomerulus is filtered."},{"id": 1950,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The majority of filtered sodium is reabsorbed in the:","options": [{"key": "A","text": "Distal convoluted tubule"},{"key": "B","text": "Proximal convoluted tubule"},{"key": "C","text": "Loop of Henle only"},{"key": "D","text": "Collecting duct"}],"correct": "B","explanation": "About 65-70% of filtered sodium is reabsorbed in the proximal convoluted tubule."},{"id": 1951,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Glucose is normally reabsorbed almost entirely in the:","options": [{"key": "A","text": "Proximal convoluted tubule via sodium-glucose cotransporters"},{"key": "B","text": "Loop of Henle"},{"key": "C","text": "Distal tubule"},{"key": "D","text": "Collecting duct"}],"correct": "A","explanation": "Nearly 100% of filtered glucose is reabsorbed in the proximal tubule via SGLT cotransport with sodium."},{"id": 1952,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "The renal threshold for glucose (plasma concentration above which glucose appears in urine) is approximately:","options": [{"key": "A","text": "180 mg/dl"},{"key": "B","text": "300 mg/dl"},{"key": "C","text": "100 mg/dl"},{"key": "D","text": "60 mg/dl"}],"correct": "A","explanation": "Glucosuria typically begins when plasma glucose exceeds the renal threshold of about 180 mg/dl."},{"id": 1953,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Tubular maximum (Tm) refers to:","options": [{"key": "A","text": "The minimum concentration required for filtration"},{"key": "B","text": "The maximum rate at which a substance can be actively reabsorbed or secreted by the tubules due to transporter saturation"},{"key": "C","text": "The maximum rate at which a substance can be filtered"},{"key": "D","text": "The maximum urine flow rate"}],"correct": "B","explanation": "Tm is the transport maximum, reflecting saturation of carrier-mediated tubular transport systems."},{"id": 1954,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The thick ascending limb of the loop of Henle is characterized by:","options": [{"key": "A","text": "Impermeability to water with active reabsorption of Na+, K+, and Cl- (via the Na-K-2Cl cotransporter)"},{"key": "B","text": "High permeability to water"},{"key": "C","text": "No reabsorption of any solutes"},{"key": "D","text": "Complete permeability to urea only"}],"correct": "A","explanation": "The thick ascending limb actively reabsorbs NaCl via NKCC2 transporters but remains impermeable to water, diluting tubular fluid."},{"id": 1955,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The primary site of action of loop diuretics (e.g., furosemide) is:","options": [{"key": "A","text": "Distal convoluted tubule sodium-chloride cotransporter"},{"key": "B","text": "Collecting duct principal cells"},{"key": "C","text": "Proximal convoluted tubule"},{"key": "D","text": "Thick ascending limb of the loop of Henle (inhibiting Na-K-2Cl cotransporter)"}],"correct": "D","explanation": "Loop diuretics block the Na-K-2Cl cotransporter in the thick ascending limb, reducing NaCl reabsorption."},{"id": 1956,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The distal convoluted tubule primarily reabsorbs sodium and chloride via which transporter, which is the target of thiazide diuretics?","options": [{"key": "A","text": "Na-Cl cotransporter"},{"key": "B","text": "Na-K-2Cl cotransporter"},{"key": "C","text": "Na-H exchanger"},{"key": "D","text": "Epithelial sodium channel (ENaC)"}],"correct": "A","explanation": "Thiazide diuretics inhibit the Na-Cl cotransporter in the distal convoluted tubule."},{"id": 1957,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Aldosterone acts on which nephron segment(s) to increase sodium reabsorption and potassium secretion?","options": [{"key": "A","text": "Bowman's capsule"},{"key": "B","text": "Late distal tubule and cortical collecting duct (principal cells)"},{"key": "C","text": "Loop of Henle"},{"key": "D","text": "Proximal convoluted tubule"}],"correct": "B","explanation": "Aldosterone acts on principal cells of the late distal tubule and collecting duct, increasing ENaC-mediated Na+ reabsorption and K+ secretion."},{"id": 1958,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Potassium-sparing diuretics, such as spironolactone, act by:","options": [{"key": "A","text": "Blocking the Na-Cl cotransporter"},{"key": "B","text": "Inhibiting carbonic anhydrase"},{"key": "C","text": "Antagonizing aldosterone receptors in the collecting duct"},{"key": "D","text": "Blocking the Na-K-2Cl cotransporter"}],"correct": "C","explanation": "Spironolactone is an aldosterone receptor antagonist, reducing sodium reabsorption while sparing potassium."},{"id": 1959,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Tubular secretion refers to:","options": [{"key": "A","text": "Movement of substances from the tubular lumen back into peritubular capillary blood"},{"key": "B","text": "Formation of urine in the bladder"},{"key": "C","text": "Filtration at the glomerulus"},{"key": "D","text": "Movement of substances from peritubular capillary blood into the tubular lumen"}],"correct": "D","explanation": "Secretion moves solutes from blood/interstitium into the tubular fluid, the reverse of reabsorption."},{"id": 1960,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Hydrogen ions and potassium ions are notably handled by the kidney primarily through:","options": [{"key": "A","text": "Tubular secretion"},{"key": "B","text": "No renal handling at all"},{"key": "C","text": "Filtration only"},{"key": "D","text": "Passive diffusion in Bowman's capsule only"}],"correct": "A","explanation": "Both H+ and K+ are actively secreted into the tubular lumen, particularly in the distal nephron."},{"id": 1961,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Almost all filtered proteins in the healthy kidney are:","options": [{"key": "A","text": "Actively secreted into the tubule"},{"key": "B","text": "Converted to glucose"},{"key": "C","text": "Not filtered at all due to the size/charge-selective glomerular barrier, and any filtered protein is reabsorbed in the proximal tubule"},{"key": "D","text": "Excreted in urine"}],"correct": "C","explanation": "Healthy glomeruli largely exclude plasma proteins, and the small amount filtered is reabsorbed by proximal tubular cells."},{"id": 1962,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Reabsorption of water in the proximal convoluted tubule occurs by:","options": [{"key": "A","text": "Passive osmosis following active solute (mainly sodium) reabsorption"},{"key": "B","text": "Filtration"},{"key": "C","text": "Facilitated diffusion of water alone without solute"},{"key": "D","text": "Active transport only"}],"correct": "A","explanation": "Water follows the osmotic gradient created by active sodium reabsorption ('obligatory' water reabsorption) in the proximal tubule."},{"id": 1963,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Antidiuretic hormone (ADH) increases water permeability primarily in the:","options": [{"key": "A","text": "Bowman's capsule"},{"key": "B","text": "Late distal tubule and collecting duct via aquaporin-2 channels"},{"key": "C","text": "Thick ascending limb"},{"key": "D","text": "Proximal convoluted tubule"}],"correct": "B","explanation": "ADH inserts aquaporin-2 water channels into the luminal membrane of the late distal tubule/collecting duct principal cells."},{"id": 1964,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Hard","question": "Urea recycling contributes significantly to which renal function?","options": [{"key": "A","text": "Maintenance of the medullary interstitial osmotic gradient for urine concentration"},{"key": "B","text": "Filtration of proteins"},{"key": "C","text": "Glucose reabsorption"},{"key": "D","text": "Potassium secretion"}],"correct": "A","explanation": "Urea recycled from the collecting duct into the medullary interstitium contributes substantially to the osmotic gradient needed for concentrating urine."},{"id": 1965,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Approximately what percentage of filtered water is normally reabsorbed by the kidneys?","options": [{"key": "A","text": "99%"},{"key": "B","text": "50%"},{"key": "C","text": "10%"},{"key": "D","text": "75%"}],"correct": "A","explanation": "Roughly 99% of the approximately 180 L/day of glomerular filtrate is reabsorbed, leaving about 1-1.5 L of urine."},{"id": 1966,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Amino acids are reabsorbed almost entirely by which nephron segment, similar to glucose?","options": [{"key": "A","text": "Collecting duct"},{"key": "B","text": "Distal convoluted tubule"},{"key": "C","text": "Proximal convoluted tubule"},{"key": "D","text": "Loop of Henle"}],"correct": "C","explanation": "Like glucose, amino acids are almost completely reabsorbed in the proximal tubule via specific cotransport systems."},{"id": 1967,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Which of the following substances is typically both filtered and secreted, resulting in a clearance greater than GFR?","options": [{"key": "A","text": "Inulin"},{"key": "B","text": "Para-aminohippuric acid (PAH)"},{"key": "C","text": "Albumin"},{"key": "D","text": "Glucose (normally)"}],"correct": "B","explanation": "PAH is filtered and also actively secreted, so essentially all of it is removed from plasma in one renal pass."},{"id": 1968,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Osmotic diuretics, such as mannitol, increase urine output primarily by:","options": [{"key": "A","text": "Blocking aldosterone receptors"},{"key": "B","text": "Blocking the Na-K-2Cl cotransporter"},{"key": "C","text": "Inhibiting carbonic anhydrase"},{"key": "D","text": "Being filtered but poorly reabsorbed, holding water in the tubular lumen osmotically"}],"correct": "D","explanation": "Mannitol is freely filtered but not reabsorbed, creating osmotic pressure in the tubule that retains water and increases urine volume."},{"id": 1969,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Carbonic anhydrase inhibitors (e.g., acetazolamide) reduce reabsorption primarily in the:","options": [{"key": "A","text": "Loop of Henle"},{"key": "B","text": "Collecting duct only"},{"key": "C","text": "Bowman's capsule"},{"key": "D","text": "Proximal convoluted tubule, by inhibiting bicarbonate reabsorption"}],"correct": "D","explanation": "Acetazolamide inhibits carbonic anhydrase, reducing proximal tubular bicarbonate (and secondary sodium/water) reabsorption."},{"id": 1970,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Normal arterial blood pH is maintained within the range of:","options": [{"key": "A","text": "8.0-8.5"},{"key": "B","text": "7.35-7.45"},{"key": "C","text": "7.5-7.8"},{"key": "D","text": "6.8-7.0"}],"correct": "B","explanation": "Normal arterial pH is tightly regulated between 7.35 and 7.45."},{"id": 1971,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The most important extracellular buffer system in the blood is the:","options": [{"key": "A","text": "Protein buffer system"},{"key": "B","text": "Hemoglobin buffer system alone"},{"key": "C","text": "Phosphate buffer system"},{"key": "D","text": "Bicarbonate-carbonic acid buffer system"}],"correct": "D","explanation": "The bicarbonate/carbonic acid (HCO3-/H2CO3) system is the principal extracellular fluid buffer."},{"id": 1972,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Henderson-Hasselbalch equation relating pH to the bicarbonate buffer system is:","options": [{"key": "A","text": "pH = [HCO3-] x [H2CO3]"},{"key": "B","text": "pH = pKa - log([HCO3-]/[H2CO3])"},{"key": "C","text": "pH = pKa / [HCO3-]"},{"key": "D","text": "pH = pKa + log([HCO3-]/[H2CO3])"}],"correct": "D","explanation": "pH = pKa + log([HCO3-]/[dissolved CO2]); a ratio of about 20:1 gives normal pH of 7.4."},{"id": 1973,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The normal ratio of bicarbonate to dissolved CO2 (H2CO3) required to maintain normal pH is approximately:","options": [{"key": "A","text": "5:1"},{"key": "B","text": "50:1"},{"key": "C","text": "1:1"},{"key": "D","text": "20:1"}],"correct": "D","explanation": "A bicarbonate-to-carbonic acid ratio of about 20:1 maintains blood pH at 7.4."},{"id": 1974,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Respiratory acidosis is caused primarily by:","options": [{"key": "A","text": "Excess vomiting"},{"key": "B","text": "Loss of bicarbonate through diarrhea"},{"key": "C","text": "Hyperventilation"},{"key": "D","text": "Hypoventilation, leading to CO2 retention"}],"correct": "D","explanation": "Inadequate ventilation causes CO2 (and hence carbonic acid) to accumulate, lowering pH."},{"id": 1975,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Respiratory alkalosis is caused primarily by:","options": [{"key": "A","text": "Hypoventilation"},{"key": "B","text": "Hyperventilation, causing excessive CO2 loss"},{"key": "C","text": "Renal bicarbonate retention"},{"key": "D","text": "Diabetic ketoacidosis"}],"correct": "B","explanation": "Excessive ventilation blows off CO2 faster than it is produced, raising blood pH."},{"id": 1976,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Metabolic acidosis is characterized by:","options": [{"key": "A","text": "Primary decrease in pCO2"},{"key": "B","text": "Primary decrease in plasma bicarbonate (or accumulation of fixed acids)"},{"key": "C","text": "Primary increase in pH"},{"key": "D","text": "Primary increase in plasma bicarbonate"}],"correct": "B","explanation": "Metabolic acidosis results from a primary fall in plasma bicarbonate or gain of non-volatile acid."},{"id": 1977,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Metabolic alkalosis is characterized by:","options": [{"key": "A","text": "Primary increase in plasma bicarbonate"},{"key": "B","text": "Primary increase in pCO2"},{"key": "C","text": "Primary decrease in pH"},{"key": "D","text": "Primary decrease in plasma bicarbonate"}],"correct": "A","explanation": "Metabolic alkalosis results from a primary rise in plasma bicarbonate concentration (or loss of acid)."},{"id": 1978,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A common cause of metabolic acidosis is:","options": [{"key": "A","text": "Prolonged vomiting"},{"key": "B","text": "Diabetic ketoacidosis"},{"key": "C","text": "Excessive antacid ingestion"},{"key": "D","text": "Hyperventilation"}],"correct": "B","explanation": "Accumulation of ketoacids in uncontrolled diabetes is a classic cause of metabolic (high anion gap) acidosis."},{"id": 1979,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "A common cause of metabolic alkalosis is:","options": [{"key": "A","text": "Prolonged vomiting, with loss of gastric hydrochloric acid"},{"key": "B","text": "Diarrhea"},{"key": "C","text": "Diabetic ketoacidosis"},{"key": "D","text": "Renal failure"}],"correct": "A","explanation": "Loss of acidic gastric contents through vomiting raises plasma bicarbonate, causing metabolic alkalosis."},{"id": 1980,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "The kidney compensates for metabolic acidosis primarily by:","options": [{"key": "A","text": "Excreting bicarbonate and retaining hydrogen ions"},{"key": "B","text": "Decreasing ammonia production"},{"key": "C","text": "Retaining chloride ions only"},{"key": "D","text": "Increasing hydrogen ion excretion and generating new bicarbonate"}],"correct": "D","explanation": "In metabolic acidosis, the kidneys increase H+ secretion and bicarbonate synthesis/reabsorption to raise plasma pH."},{"id": 1981,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The lungs compensate for metabolic acidosis by:","options": [{"key": "A","text": "No respiratory compensation occurs"},{"key": "B","text": "Hypoventilating to retain CO2"},{"key": "C","text": "Hyperventilating to reduce pCO2 and raise pH"},{"key": "D","text": "Increasing dead space"}],"correct": "C","explanation": "Increased ventilation lowers pCO2, providing rapid partial compensation for metabolic acidosis."},{"id": 1982,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Renal compensation for a primary respiratory disturbance (e.g., respiratory acidosis) typically takes:","options": [{"key": "A","text": "Minutes"},{"key": "B","text": "Seconds"},{"key": "C","text": "Immediately, within one breath"},{"key": "D","text": "Several hours to days"}],"correct": "D","explanation": "Renal compensatory changes in bicarbonate handling are slow, taking hours to days to become fully effective."},{"id": 1983,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "The renal mechanism for excreting hydrogen ions and generating new bicarbonate mainly involves:","options": [{"key": "A","text": "Tubular secretion of H+ buffered by phosphate and ammonia (titratable acid and ammonium excretion)"},{"key": "B","text": "Excretion of potassium only"},{"key": "C","text": "Simple filtration of H+ ions"},{"key": "D","text": "Reabsorption of all filtered H+"}],"correct": "A","explanation": "The kidneys excrete H+ bound to urinary buffers (phosphate) and as ammonium (NH4+), while generating new bicarbonate."},{"id": 1984,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Ammonia (NH3) produced by renal tubular cells, mainly from glutamine, serves to:","options": [{"key": "A","text": "Directly raise blood pH by absorption into blood"},{"key": "B","text": "Increase bicarbonate excretion"},{"key": "C","text": "Combine with secreted H+ to form ammonium (NH4+), facilitating hydrogen ion excretion in urine"},{"key": "D","text": "Decrease renal blood flow"}],"correct": "C","explanation": "Ammonia buffers secreted H+ in the tubular lumen, forming NH4+, which is then excreted, allowing continued H+ secretion."},{"id": 1985,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The anion gap is calculated as:","options": [{"key": "A","text": "[Cl-] - [Na+]"},{"key": "B","text": "[Na+] + [Cl-] + [HCO3-]"},{"key": "C","text": "[Na+] - ([Cl-] + [HCO3-])"},{"key": "D","text": "[HCO3-] - [Cl-]"}],"correct": "C","explanation": "Anion gap = [Na+] - ([Cl-] + [HCO3-]), normally about 8-16 mEq/L, used to classify metabolic acidosis."},{"id": 1986,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A high anion gap metabolic acidosis is typically caused by:","options": [{"key": "A","text": "Diarrhea with bicarbonate loss"},{"key": "B","text": "Accumulation of an unmeasured acid, such as lactic acid or ketoacids"},{"key": "C","text": "Renal tubular acidosis with normal anion gap"},{"key": "D","text": "Hyperchloremia alone"}],"correct": "B","explanation": "High anion gap acidosis results from accumulation of acids like lactate or ketones, not accompanied by chloride retention."},{"id": 1987,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A normal anion gap (hyperchloremic) metabolic acidosis is classically caused by:","options": [{"key": "A","text": "Diabetic ketoacidosis"},{"key": "B","text": "Severe diarrhea with bicarbonate loss (or renal tubular acidosis)"},{"key": "C","text": "Lactic acidosis"},{"key": "D","text": "Aspirin overdose"}],"correct": "B","explanation": "Loss of bicarbonate-rich fluid, as in diarrhea, causes acidosis with a compensatory rise in chloride, keeping the anion gap normal."},{"id": 1988,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which buffer system is most important for buffering hydrogen ions within body cells (intracellular buffering)?","options": [{"key": "A","text": "Phosphate and protein buffer systems"},{"key": "B","text": "Bicarbonate buffer"},{"key": "C","text": "Ammonia buffer only"},{"key": "D","text": "Hemoglobin buffer only"}],"correct": "A","explanation": "Intracellular buffering relies heavily on proteins and phosphate compounds."},{"id": 1989,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hemoglobin acts as an important buffer primarily within:","options": [{"key": "A","text": "Renal tubular fluid"},{"key": "B","text": "Cerebrospinal fluid"},{"key": "C","text": "Red blood cells, buffering hydrogen ions generated from CO2 transport"},{"key": "D","text": "Plasma"}],"correct": "C","explanation": "Hemoglobin buffers H+ produced from carbonic acid dissociation as CO2 is picked up in tissues."},{"id": 1990,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "The countercurrent multiplier mechanism responsible for urine concentration is located primarily in the:","options": [{"key": "A","text": "Loop of Henle"},{"key": "B","text": "Proximal convoluted tubule"},{"key": "C","text": "Bowman's capsule"},{"key": "D","text": "Renal artery"}],"correct": "A","explanation": "The loop of Henle, through countercurrent multiplication, establishes the medullary osmotic gradient."},{"id": 1991,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The descending limb of the loop of Henle is characterized by:","options": [{"key": "A","text": "Impermeability to water but active solute transport"},{"key": "B","text": "Complete impermeability to both water and solutes"},{"key": "C","text": "High permeability to water but low permeability to solutes"},{"key": "D","text": "Active water secretion"}],"correct": "C","explanation": "The thin descending limb is freely permeable to water, allowing water to leave as fluid moves into the hyperosmotic medulla."},{"id": 1992,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The ascending limb of the loop of Henle is characterized by:","options": [{"key": "A","text": "Impermeability to solutes"},{"key": "B","text": "Impermeability to water with active/passive NaCl reabsorption"},{"key": "C","text": "High permeability to water"},{"key": "D","text": "Active water reabsorption via ADH"}],"correct": "B","explanation": "The ascending limb reabsorbs NaCl but remains water-impermeable, diluting tubular fluid as it ascends."},{"id": 1993,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Maximum osmolality achievable in the renal medullary interstitium in humans is approximately:","options": [{"key": "A","text": "600 mOsm/L"},{"key": "B","text": "1200-1400 mOsm/L"},{"key": "C","text": "3000 mOsm/L"},{"key": "D","text": "300 mOsm/L"}],"correct": "B","explanation": "The human renal medulla can achieve an osmolality of about 1200-1400 mOsm/L at the papillary tip."},{"id": 1994,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "The countercurrent exchanger mechanism, which helps preserve the medullary osmotic gradient, is carried out by the:","options": [{"key": "A","text": "Bowman's capsule"},{"key": "B","text": "Peritubular capillaries of the cortex"},{"key": "C","text": "Glomerular capillaries"},{"key": "D","text": "Vasa recta"}],"correct": "D","explanation": "The hairpin-shaped vasa recta passively exchange solutes and water, minimizing washout of the medullary gradient."},{"id": 1995,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In the absence of ADH, the collecting duct is:","options": [{"key": "A","text": "Maximally permeable to urea only"},{"key": "B","text": "Completely impermeable to all solutes"},{"key": "C","text": "Relatively impermeable to water, resulting in large volumes of dilute urine"},{"key": "D","text": "Highly permeable to water, producing concentrated urine"}],"correct": "C","explanation": "Without ADH, water cannot be reabsorbed in the collecting duct, so dilute urine is excreted in large volume."},{"id": 1996,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "ADH increases water reabsorption in the collecting duct by promoting insertion of which channel into the luminal membrane?","options": [{"key": "A","text": "Na-K-2Cl cotransporter"},{"key": "B","text": "Epithelial sodium channel (ENaC) exclusively"},{"key": "C","text": "Aquaporin-2"},{"key": "D","text": "Sodium-glucose cotransporter"}],"correct": "C","explanation": "ADH triggers insertion of aquaporin-2 water channels into the apical membrane of collecting duct principal cells."},{"id": 1997,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Maximally concentrated human urine can reach an osmolality of approximately:","options": [{"key": "A","text": "300 mOsm/L"},{"key": "B","text": "1200-1400 mOsm/L"},{"key": "C","text": "900 mOsm/L"},{"key": "D","text": "600 mOsm/L"}],"correct": "B","explanation": "In maximal antidiuresis, urine osmolality can approach 1200-1400 mOsm/L, matching the deep medullary interstitium."},{"id": 1998,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "Minimum (maximally dilute) urine osmolality achievable is approximately:","options": [{"key": "A","text": "150 mOsm/L"},{"key": "B","text": "50 mOsm/L"},{"key": "C","text": "300 mOsm/L"},{"key": "D","text": "600 mOsm/L"}],"correct": "B","explanation": "In maximal water diuresis (absence of ADH), urine osmolality can fall to as low as 50 mOsm/L."},{"id": 1999,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Hard","question": "Free water clearance being positive indicates that the kidney is:","options": [{"key": "A","text": "Concentrating urine"},{"key": "B","text": "Reabsorbing all filtered water"},{"key": "C","text": "Producing no urine"},{"key": "D","text": "Excreting dilute urine (excreting more water than is needed to excrete solute isosmotically)"}],"correct": "D","explanation": "A positive free water clearance means dilute urine is being excreted, removing 'free' water beyond isosmotic requirements."},{"id": 2000,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A patient with central diabetes insipidus, due to deficient ADH secretion, would be expected to produce:","options": [{"key": "A","text": "Small volumes of highly concentrated urine"},{"key": "B","text": "Large volumes of dilute urine"},{"key": "C","text": "No urine at all"},{"key": "D","text": "Normal urine output and concentration"}],"correct": "B","explanation": "Without ADH, the collecting duct cannot reabsorb water, resulting in polyuria with dilute urine."},{"id": 2001,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Nephrogenic diabetes insipidus results from:","options": [{"key": "A","text": "Deficient ADH secretion by the pituitary"},{"key": "B","text": "Excess ADH secretion"},{"key": "C","text": "Renal collecting duct unresponsiveness to ADH despite normal or high ADH levels"},{"key": "D","text": "Excess aldosterone secretion"}],"correct": "C","explanation": "In nephrogenic DI, the kidneys fail to respond to ADH due to receptor or aquaporin defects, causing polyuria."},{"id": 2002,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Urea contributes significantly to medullary hyperosmolality mainly because of:","options": [{"key": "A","text": "Complete exclusion of urea from the nephron"},{"key": "B","text": "Its rapid destruction by renal enzymes"},{"key": "C","text": "Active secretion of urea by the proximal tubule"},{"key": "D","text": "Recycling of urea between the inner medullary collecting duct and the loop of Henle"}],"correct": "D","explanation": "Urea recycled from the collecting duct back into the loop of Henle and interstitium contributes about 40-50% of medullary osmolality."},{"id": 2003,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "A high protein diet, which increases urea production, tends to:","options": [{"key": "A","text": "Have no effect on urine concentration"},{"key": "B","text": "Cause immediate diabetes insipidus"},{"key": "C","text": "Enhance the kidney's maximum urine-concentrating ability by contributing more urea to the medullary gradient"},{"key": "D","text": "Impair the kidney's ability to concentrate urine"}],"correct": "C","explanation": "Increased urea availability strengthens the medullary osmotic gradient, aiding maximal urine concentration."},{"id": 2004,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The primary physiological stimulus for ADH release is:","options": [{"key": "A","text": "Decreased body temperature"},{"key": "B","text": "Increased plasma osmolality, sensed by hypothalamic osmoreceptors"},{"key": "C","text": "Increased blood glucose"},{"key": "D","text": "Decreased plasma osmolality"}],"correct": "B","explanation": "A rise in plasma osmolality stimulates hypothalamic osmoreceptors, triggering ADH release to conserve water."},{"id": 2005,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Renin is released from the juxtaglomerular cells primarily in response to:","options": [{"key": "A","text": "Increased blood volume"},{"key": "B","text": "Increased aldosterone levels"},{"key": "C","text": "Increased renal perfusion pressure"},{"key": "D","text": "Decreased renal perfusion pressure/decreased NaCl delivery to the macula densa"}],"correct": "D","explanation": "Reduced renal blood flow, reduced blood pressure, or decreased distal NaCl delivery all stimulate renin secretion."},{"id": 2006,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Renin acts enzymatically to convert which substrate into angiotensin I?","options": [{"key": "A","text": "Angiotensin-converting enzyme"},{"key": "B","text": "Bradykinin"},{"key": "C","text": "Angiotensinogen"},{"key": "D","text": "Aldosterone"}],"correct": "C","explanation": "Renin cleaves circulating angiotensinogen (from the liver) to form angiotensin I."},{"id": 2007,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Angiotensin-converting enzyme (ACE), located mainly in the pulmonary vascular endothelium, converts:","options": [{"key": "A","text": "Renin to angiotensinogen"},{"key": "B","text": "Angiotensin II to angiotensin I"},{"key": "C","text": "Angiotensin I to angiotensin II"},{"key": "D","text": "Angiotensinogen to angiotensin I"}],"correct": "C","explanation": "ACE converts the relatively inactive angiotensin I into the potent angiotensin II."},{"id": 2008,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Angiotensin II exerts which of the following effects?","options": [{"key": "A","text": "Decreased sympathetic activity"},{"key": "B","text": "Vasodilation and decreased aldosterone secretion"},{"key": "C","text": "Inhibition of ADH release"},{"key": "D","text": "Potent vasoconstriction and stimulation of aldosterone secretion from the adrenal cortex"}],"correct": "D","explanation": "Angiotensin II is a powerful vasoconstrictor and a major stimulus for aldosterone release."},{"id": 2009,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "Aldosterone, released from the zona glomerulosa of the adrenal cortex, acts on the kidney to promote:","options": [{"key": "A","text": "Sodium reabsorption and potassium (and hydrogen ion) secretion"},{"key": "B","text": "Water excretion without sodium change"},{"key": "C","text": "Sodium excretion and potassium retention"},{"key": "D","text": "Calcium excretion"}],"correct": "A","explanation": "Aldosterone increases distal nephron sodium reabsorption while promoting potassium and hydrogen ion secretion."},{"id": 2010,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The overall physiological effect of RAAS activation is to:","options": [{"key": "A","text": "Have no effect on blood pressure"},{"key": "B","text": "Increase blood pressure and blood volume through vasoconstriction and sodium/water retention"},{"key": "C","text": "Decrease sympathetic nervous activity"},{"key": "D","text": "Decrease blood pressure and blood volume"}],"correct": "B","explanation": "RAAS activation raises blood pressure and volume via vasoconstriction (angiotensin II) and salt/water retention (aldosterone)."},{"id": 2011,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "ACE inhibitor drugs (e.g., enalapril) used in hypertension work by:","options": [{"key": "A","text": "Preventing conversion of angiotensin I to angiotensin II"},{"key": "B","text": "Blocking renin release"},{"key": "C","text": "Increasing sodium reabsorption"},{"key": "D","text": "Blocking aldosterone receptors"}],"correct": "A","explanation": "ACE inhibitors block the enzyme that converts angiotensin I to the active vasoconstrictor angiotensin II."},{"id": 2012,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Angiotensin receptor blockers (ARBs) act by:","options": [{"key": "A","text": "Stimulating aldosterone release"},{"key": "B","text": "Blocking angiotensin II from binding its AT1 receptor"},{"key": "C","text": "Inhibiting ACE"},{"key": "D","text": "Directly inhibiting renin"}],"correct": "B","explanation": "ARBs directly block the AT1 receptor, preventing angiotensin II's vasoconstrictive and aldosterone-stimulating actions."},{"id": 2013,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Angiotensin II also stimulates thirst and release of which hormone from the posterior pituitary?","options": [{"key": "A","text": "Growth hormone"},{"key": "B","text": "Prolactin"},{"key": "C","text": "Antidiuretic hormone (ADH)"},{"key": "D","text": "Oxytocin"}],"correct": "C","explanation": "Angiotensin II promotes thirst and stimulates ADH release, complementing its volume-conserving effects."},{"id": 2014,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The primary factor that switches off (inhibits) renin secretion is:","options": [{"key": "A","text": "Restoration of normal renal perfusion pressure and NaCl delivery (negative feedback)"},{"key": "B","text": "Decreased angiotensin II levels only"},{"key": "C","text": "Decreased blood pressure"},{"key": "D","text": "Increased sympathetic stimulation"}],"correct": "A","explanation": "As blood pressure/volume normalize, renal perfusion and macula densa NaCl sensing reduce further renin release via negative feedback."},{"id": 2015,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal tidal volume at rest is approximately:","options": [{"key": "A","text": "3000 ml"},{"key": "B","text": "500 ml"},{"key": "C","text": "1200 ml"},{"key": "D","text": "150 ml"}],"correct": "B","explanation": "Tidal volume, the air moved in a normal quiet breath, is about 500 ml."},{"id": 2016,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Inspiratory reserve volume (IRV) is defined as:","options": [{"key": "A","text": "Air that can be forcibly expired after normal expiration"},{"key": "B","text": "Air remaining after normal expiration"},{"key": "C","text": "Air remaining after maximal expiration"},{"key": "D","text": "Air inspired forcibly after a normal tidal inspiration"}],"correct": "D","explanation": "IRV is the extra volume that can be inhaled above normal tidal volume by maximal effort."},{"id": 2017,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Expiratory reserve volume (ERV) is defined as:","options": [{"key": "A","text": "Air that can be forcibly expired after a normal tidal expiration"},{"key": "B","text": "Air remaining in lungs after maximal expiration"},{"key": "C","text": "Total lung capacity minus vital capacity"},{"key": "D","text": "Air inspired forcibly beyond tidal volume"}],"correct": "A","explanation": "ERV is the additional air that can be exhaled by forceful effort after normal expiration."},{"id": 2018,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Residual volume (RV) is defined as:","options": [{"key": "A","text": "Air remaining in the lungs after a maximal forced expiration"},{"key": "B","text": "Air inspired during a normal breath"},{"key": "C","text": "Air expired after normal inspiration"},{"key": "D","text": "Total capacity of the lung"}],"correct": "A","explanation": "RV is the volume of air that cannot be expelled even by maximal forced expiration."},{"id": 2019,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Approximate normal value of residual volume is:","options": [{"key": "A","text": "1200 ml"},{"key": "B","text": "3500 ml"},{"key": "C","text": "2500 ml"},{"key": "D","text": "500 ml"}],"correct": "A","explanation": "Residual volume is normally about 1200 ml."},{"id": 2020,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Vital capacity (VC) is the sum of:","options": [{"key": "A","text": "Tidal volume + Residual volume"},{"key": "B","text": "Total lung capacity + Residual volume"},{"key": "C","text": "IRV + Tidal volume + ERV"},{"key": "D","text": "IRV + ERV + Residual volume"}],"correct": "C","explanation": "VC = Inspiratory reserve volume + Tidal volume + Expiratory reserve volume."},{"id": 2021,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal vital capacity in an average young adult male is approximately:","options": [{"key": "A","text": "6000 ml"},{"key": "B","text": "1500 ml"},{"key": "C","text": "4600 ml"},{"key": "D","text": "2500 ml"}],"correct": "C","explanation": "Vital capacity is normally around 4500-4800 ml in young adult males."},{"id": 2022,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "Total lung capacity (TLC) equals:","options": [{"key": "A","text": "Vital capacity + Residual volume"},{"key": "B","text": "Tidal volume + Residual volume"},{"key": "C","text": "Functional residual capacity + Tidal volume"},{"key": "D","text": "IRV + ERV"}],"correct": "A","explanation": "TLC = Vital capacity + Residual volume (the sum of all four lung volumes)."},{"id": 2023,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "Normal total lung capacity is approximately:","options": [{"key": "A","text": "8000 ml"},{"key": "B","text": "3500 ml"},{"key": "C","text": "2300 ml"},{"key": "D","text": "5800 ml"}],"correct": "D","explanation": "TLC is normally about 5800-6000 ml in a young adult male."},{"id": 2024,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Functional residual capacity (FRC) is defined as:","options": [{"key": "A","text": "Tidal volume + ERV"},{"key": "B","text": "IRV + ERV + RV"},{"key": "C","text": "ERV + Residual volume"},{"key": "D","text": "IRV + Tidal volume"}],"correct": "C","explanation": "FRC is the volume of air remaining in the lungs after a normal tidal expiration (ERV + RV)."},{"id": 2025,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal functional residual capacity is approximately:","options": [{"key": "A","text": "2300 ml"},{"key": "B","text": "3500 ml"},{"key": "C","text": "4600 ml"},{"key": "D","text": "1200 ml"}],"correct": "A","explanation": "FRC is normally about 2300 ml, providing a buffer for gas exchange between breaths."},{"id": 2026,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Inspiratory capacity (IC) is defined as:","options": [{"key": "A","text": "Tidal volume + Inspiratory reserve volume"},{"key": "B","text": "Total lung capacity - Vital capacity"},{"key": "C","text": "ERV + Residual volume"},{"key": "D","text": "Tidal volume + ERV"}],"correct": "A","explanation": "IC = Tidal volume + Inspiratory reserve volume, the maximum air that can be inspired from resting FRC level."},{"id": 2027,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Which lung volume/capacity cannot be measured directly by simple spirometry?","options": [{"key": "A","text": "Residual volume (and capacities containing it)"},{"key": "B","text": "Expiratory reserve volume"},{"key": "C","text": "Inspiratory reserve volume"},{"key": "D","text": "Tidal volume"}],"correct": "A","explanation": "Residual volume (and hence FRC, TLC) cannot be measured by spirometry alone; it requires methods like helium dilution, nitrogen washout, or body plethysmography."},{"id": 2028,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which of the following is a standard method for measuring functional residual capacity?","options": [{"key": "A","text": "Peak flow meter"},{"key": "B","text": "Helium dilution technique"},{"key": "C","text": "Simple spirometry alone"},{"key": "D","text": "Sphygmomanometry"}],"correct": "B","explanation": "The helium dilution (closed-circuit) method is a classic technique for measuring FRC/RV."},{"id": 2029,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Forced expiratory volume in one second (FEV1) normally represents what percentage of forced vital capacity (FVC)?","options": [{"key": "A","text": "About 60%"},{"key": "B","text": "About 80%"},{"key": "C","text": "About 40%"},{"key": "D","text": "About 100%"}],"correct": "B","explanation": "FEV1/FVC ratio is normally about 75-80% in healthy individuals."},{"id": 2030,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A reduced FEV1/FVC ratio is characteristic of:","options": [{"key": "A","text": "Anemia"},{"key": "B","text": "Normal aging alone"},{"key": "C","text": "Obstructive lung disease"},{"key": "D","text": "Restrictive lung disease"}],"correct": "C","explanation": "Obstructive diseases (e.g., asthma, COPD) reduce airflow, lowering the FEV1/FVC ratio."},{"id": 2031,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "In restrictive lung disease, which of the following is typically observed?","options": [{"key": "A","text": "Reduced TLC and vital capacity with normal or increased FEV1/FVC ratio"},{"key": "B","text": "Reduced FEV1/FVC ratio with normal/increased TLC"},{"key": "C","text": "No change in lung volumes"},{"key": "D","text": "Increased residual volume with normal TLC"}],"correct": "A","explanation": "Restrictive diseases reduce lung volumes (TLC, VC) while the FEV1/FVC ratio remains normal or high."},{"id": 2032,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Anatomical dead space refers to:","options": [{"key": "A","text": "Alveoli that are ventilated but not perfused"},{"key": "B","text": "Total volume of both lungs"},{"key": "C","text": "Air trapped after maximal expiration"},{"key": "D","text": "Volume of the conducting airways where no gas exchange occurs"}],"correct": "D","explanation": "Anatomical dead space is the volume of the conducting airways (nose to terminal bronchioles) not participating in gas exchange."},{"id": 2033,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal anatomical dead space volume is approximately:","options": [{"key": "A","text": "50 ml"},{"key": "B","text": "1000 ml"},{"key": "C","text": "150 ml"},{"key": "D","text": "500 ml"}],"correct": "C","explanation": "Anatomical dead space is normally about 150 ml, roughly equal to 2 ml/kg body weight."},{"id": 2034,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Physiological dead space is defined as:","options": [{"key": "A","text": "Anatomical dead space plus alveolar dead space (ventilated but underperfused alveoli)"},{"key": "B","text": "Anatomical dead space alone"},{"key": "C","text": "The residual volume"},{"key": "D","text": "Only alveolar dead space"}],"correct": "A","explanation": "Physiological dead space = anatomical dead space + alveolar dead space; in healthy lungs the two are nearly equal."},{"id": 2035,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Minute ventilation is calculated as:","options": [{"key": "A","text": "Tidal volume x Respiratory rate"},{"key": "B","text": "FEV1 x FVC"},{"key": "C","text": "Vital capacity x Respiratory rate"},{"key": "D","text": "Tidal volume / Respiratory rate"}],"correct": "A","explanation": "Minute (pulmonary) ventilation = Tidal volume x Respiratory rate."},{"id": 2036,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal minute ventilation at rest is approximately:","options": [{"key": "A","text": "2 L/min"},{"key": "B","text": "12 L/min"},{"key": "C","text": "6 L/min"},{"key": "D","text": "20 L/min"}],"correct": "C","explanation": "At rest, with TV ~500 ml and RR ~12/min, minute ventilation is about 6 L/min."},{"id": 2037,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Alveolar ventilation is calculated as:","options": [{"key": "A","text": "Tidal volume + Dead space"},{"key": "B","text": "Tidal volume x Respiratory rate"},{"key": "C","text": "Vital capacity - Dead space"},{"key": "D","text": "(Tidal volume - Dead space) x Respiratory rate"}],"correct": "D","explanation": "Alveolar ventilation = (Tidal volume - Physiological dead space) x Respiratory rate."},{"id": 2038,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which breathing pattern change would increase alveolar ventilation the most for a given minute ventilation?","options": [{"key": "A","text": "No difference between the two"},{"key": "B","text": "Rapid, shallow breathing"},{"key": "C","text": "Breath holding"},{"key": "D","text": "Slow, deep breathing"}],"correct": "D","explanation": "Slower, deeper breaths reduce the relative impact of fixed dead space, improving alveolar ventilation efficiency."},{"id": 2039,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Peak expiratory flow rate (PEFR) is most useful clinically for assessing:","options": [{"key": "A","text": "Diffusion capacity"},{"key": "B","text": "Residual volume"},{"key": "C","text": "Cardiac output"},{"key": "D","text": "Degree of airway obstruction (e.g., in asthma)"}],"correct": "D","explanation": "PEFR reflects large airway caliber and is widely used to monitor obstructive airway disease."},{"id": 2040,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Gas exchange between alveoli and pulmonary capillary blood occurs primarily by:","options": [{"key": "A","text": "Osmosis"},{"key": "B","text": "Simple diffusion along partial pressure gradients"},{"key": "C","text": "Active transport"},{"key": "D","text": "Facilitated diffusion"}],"correct": "B","explanation": "O2 and CO2 move across the alveolar-capillary membrane by passive diffusion down their partial pressure gradients."},{"id": 2041,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "Normal partial pressure of oxygen (pO2) in alveolar air is approximately:","options": [{"key": "A","text": "60 mmHg"},{"key": "B","text": "150 mmHg"},{"key": "C","text": "40 mmHg"},{"key": "D","text": "100 mmHg"}],"correct": "D","explanation": "Alveolar pO2 is normally about 100-104 mmHg."},{"id": 2042,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "Normal partial pressure of carbon dioxide (pCO2) in alveolar air is approximately:","options": [{"key": "A","text": "20 mmHg"},{"key": "B","text": "60 mmHg"},{"key": "C","text": "80 mmHg"},{"key": "D","text": "40 mmHg"}],"correct": "D","explanation": "Alveolar pCO2 is normally about 40 mmHg, closely matching arterial pCO2."},{"id": 2043,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Normal partial pressure of oxygen in mixed venous blood is approximately:","options": [{"key": "A","text": "40 mmHg"},{"key": "B","text": "80 mmHg"},{"key": "C","text": "60 mmHg"},{"key": "D","text": "100 mmHg"}],"correct": "A","explanation": "Mixed venous pO2 is normally about 40 mmHg."},{"id": 2044,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "According to Fick's law of diffusion, the rate of gas diffusion across the respiratory membrane is directly proportional to all of the following EXCEPT:","options": [{"key": "A","text": "Partial pressure gradient of the gas"},{"key": "B","text": "Thickness of the membrane"},{"key": "C","text": "Surface area of the membrane"},{"key": "D","text": "Diffusion coefficient of the gas"}],"correct": "B","explanation": "Diffusion rate is inversely, not directly, proportional to membrane thickness."},{"id": 2045,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Compared to oxygen, carbon dioxide diffuses across the respiratory membrane:","options": [{"key": "A","text": "About 20 times faster due to higher solubility"},{"key": "B","text": "Only during exercise"},{"key": "C","text": "At exactly the same rate"},{"key": "D","text": "About 20 times slower"}],"correct": "A","explanation": "CO2's higher solubility in tissue fluids gives it a diffusion rate about 20 times that of O2, despite a similar molecular weight."},{"id": 2046,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The normal thickness of the respiratory (alveolar-capillary) membrane is approximately:","options": [{"key": "A","text": "20-30 micrometers"},{"key": "B","text": "50-100 micrometers"},{"key": "C","text": "5-10 micrometers"},{"key": "D","text": "0.2-0.6 micrometers"}],"correct": "D","explanation": "The respiratory membrane is extremely thin, about 0.2-0.6 micrometers, facilitating rapid diffusion."},{"id": 2047,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Diffusing capacity of the lung for oxygen (DLO2) refers to:","options": [{"key": "A","text": "Volume of oxygen that diffuses across the respiratory membrane per minute per mmHg pressure gradient"},{"key": "B","text": "Maximum oxygen content of blood"},{"key": "C","text": "Oxygen consumption at rest"},{"key": "D","text": "Total lung capacity available for oxygen storage"}],"correct": "A","explanation": "Diffusing capacity quantifies how readily a gas crosses the respiratory membrane per unit pressure difference."},{"id": 2048,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Diffusing capacity for oxygen typically increases during exercise mainly because of:","options": [{"key": "A","text": "Decreased alveolar ventilation"},{"key": "B","text": "Increased dead space"},{"key": "C","text": "Recruitment of previously closed pulmonary capillaries, increasing surface area"},{"key": "D","text": "Decreased cardiac output"}],"correct": "C","explanation": "Exercise opens/dilates additional pulmonary capillaries, increasing the area available for diffusion."},{"id": 2049,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Ventilation-perfusion (V/Q) ratio for the lung as a whole at rest is approximately:","options": [{"key": "A","text": "0.8"},{"key": "B","text": "0.2"},{"key": "C","text": "1.5"},{"key": "D","text": "2.5"}],"correct": "A","explanation": "The overall V/Q ratio at rest is approximately 0.8 (alveolar ventilation ~4.2 L/min, cardiac output ~5 L/min)."},{"id": 2050,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Hard","question": "In the upright lung, compared to the base, the apex of the lung has:","options": [{"key": "A","text": "Equal ventilation and perfusion"},{"key": "B","text": "Lower ventilation but relatively higher V/Q ratio"},{"key": "C","text": "No ventilation at all"},{"key": "D","text": "Higher ventilation and higher perfusion"}],"correct": "B","explanation": "The apex is relatively underperfused compared to its ventilation, giving it a higher V/Q ratio than the base."},{"id": 2051,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A V/Q ratio of zero (perfusion without ventilation) is termed:","options": [{"key": "A","text": "Diffusion block"},{"key": "B","text": "Normal gas exchange unit"},{"key": "C","text": "Shunt"},{"key": "D","text": "Dead space"}],"correct": "C","explanation": "When alveoli are perfused but not ventilated, blood passes without oxygenation - a shunt."},{"id": 2052,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A V/Q ratio approaching infinity (ventilation without perfusion) is termed:","options": [{"key": "A","text": "Alveolar dead space"},{"key": "B","text": "Shunt"},{"key": "C","text": "Diffusion limitation"},{"key": "D","text": "Normal unit"}],"correct": "A","explanation": "Ventilated but unperfused alveoli constitute alveolar dead space."},{"id": 2053,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The main factor determining the direction of gas movement across the alveolar-capillary membrane is:","options": [{"key": "A","text": "Blood pH alone"},{"key": "B","text": "Body temperature"},{"key": "C","text": "Molecular weight of the gas"},{"key": "D","text": "The partial pressure gradient of the gas"}],"correct": "D","explanation": "Gases diffuse from an area of higher to lower partial pressure."},{"id": 2054,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Surfactant, produced by type II alveolar cells, primarily functions to:","options": [{"key": "A","text": "Increase mucus production"},{"key": "B","text": "Increase diffusion distance"},{"key": "C","text": "Reduce alveolar surface tension and prevent alveolar collapse"},{"key": "D","text": "Increase alveolar surface tension"}],"correct": "C","explanation": "Surfactant lowers surface tension, stabilizing alveoli and preventing collapse (atelectasis), especially in small alveoli."},{"id": 2055,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "According to Laplace's law applied to alveoli, collapsing pressure is:","options": [{"key": "A","text": "Directly proportional to surface tension and inversely proportional to radius"},{"key": "B","text": "Directly proportional to both radius and surface tension"},{"key": "C","text": "Independent of both surface tension and radius"},{"key": "D","text": "Directly proportional to radius and inversely proportional to surface tension"}],"correct": "A","explanation": "Laplace's law: Pressure = 2T/r, so smaller alveoli need more surfactant effect to avoid collapse."},{"id": 2056,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Pulmonary compliance is defined as:","options": [{"key": "A","text": "Change in lung volume per unit change in pressure"},{"key": "B","text": "Total lung capacity divided by vital capacity"},{"key": "C","text": "Airway resistance during expiration"},{"key": "D","text": "Change in pressure per unit change in volume"}],"correct": "A","explanation": "Compliance = ΔVolume/ΔPressure, reflecting the distensibility of the lungs."},{"id": 2057,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Decreased lung compliance (stiffer lungs) is characteristic of:","options": [{"key": "A","text": "Asthma"},{"key": "B","text": "Emphysema"},{"key": "C","text": "Normal aging alone"},{"key": "D","text": "Pulmonary fibrosis"}],"correct": "D","explanation": "Fibrotic lung disease stiffens lung tissue, decreasing compliance and increasing the work of breathing."},{"id": 2058,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Increased lung compliance is characteristically seen in:","options": [{"key": "A","text": "Pulmonary edema"},{"key": "B","text": "Emphysema"},{"key": "C","text": "Pulmonary fibrosis"},{"key": "D","text": "ARDS"}],"correct": "B","explanation": "Emphysema destroys elastic tissue, making the lungs abnormally compliant (easy to inflate)."},{"id": 2059,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "The primary cause of hypoxemia in a right-to-left cardiac shunt is:","options": [{"key": "A","text": "High altitude exposure"},{"key": "B","text": "Diffusion limitation"},{"key": "C","text": "Hypoventilation"},{"key": "D","text": "Mixing of deoxygenated blood directly with oxygenated arterial blood, bypassing the lungs"}],"correct": "D","explanation": "In a right-to-left shunt, unoxygenated blood bypasses ventilated alveoli and mixes with arterial blood, lowering pO2."},{"id": 2060,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "The majority of oxygen in blood is transported:","options": [{"key": "A","text": "Bound to plasma proteins"},{"key": "B","text": "As bicarbonate ion"},{"key": "C","text": "Dissolved in plasma"},{"key": "D","text": "Bound to hemoglobin"}],"correct": "D","explanation": "About 98-99% of blood oxygen is carried bound to hemoglobin; only a small fraction is dissolved in plasma."},{"id": 2061,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Each gram of fully saturated hemoglobin can carry approximately how much oxygen?","options": [{"key": "A","text": "3.4 ml O2"},{"key": "B","text": "1.34 ml O2"},{"key": "C","text": "0.34 ml O2"},{"key": "D","text": "13.4 ml O2"}],"correct": "B","explanation": "Each gram of hemoglobin can bind about 1.34 ml of oxygen when fully saturated."},{"id": 2062,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Normal arterial oxygen saturation (SaO2) at sea level is approximately:","options": [{"key": "A","text": "50-60%"},{"key": "B","text": "80-85%"},{"key": "C","text": "70-75%"},{"key": "D","text": "97-100%"}],"correct": "D","explanation": "Arterial blood is normally 97-100% saturated with oxygen."},{"id": 2063,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Easy","question": "The oxygen-hemoglobin dissociation curve has a characteristic shape described as:","options": [{"key": "A","text": "Linear"},{"key": "B","text": "Exponential decay"},{"key": "C","text": "Sigmoid (S-shaped)"},{"key": "D","text": "Hyperbolic"}],"correct": "C","explanation": "The O2-Hb dissociation curve is sigmoid, reflecting cooperative binding of O2 to hemoglobin's four subunits."},{"id": 2064,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "A rightward shift of the oxygen-hemoglobin dissociation curve indicates:","options": [{"key": "A","text": "No change in oxygen affinity"},{"key": "B","text": "Decreased affinity of hemoglobin for oxygen, facilitating O2 unloading to tissues"},{"key": "C","text": "Increased carbon monoxide binding"},{"key": "D","text": "Increased affinity of hemoglobin for oxygen"}],"correct": "B","explanation": "A rightward shift reduces Hb-O2 affinity, promoting oxygen release to tissues."},{"id": 2065,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Which of the following factors causes a RIGHTWARD shift of the oxygen-hemoglobin dissociation curve?","options": [{"key": "A","text": "Increased pCO2 and decreased pH (Bohr effect)"},{"key": "B","text": "Decreased 2,3-DPG"},{"key": "C","text": "Decreased pCO2"},{"key": "D","text": "Decreased temperature"}],"correct": "A","explanation": "Increased CO2 and decreased pH shift the curve right, aiding O2 release in metabolically active tissue."},{"id": 2066,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Bohr effect refers to:","options": [{"key": "A","text": "The effect of pH/CO2 changes on hemoglobin's affinity for oxygen"},{"key": "B","text": "The effect of 2,3-DPG on CO2 transport"},{"key": "C","text": "The effect of altitude on ventilation"},{"key": "D","text": "The effect of temperature on hemoglobin-oxygen affinity"}],"correct": "A","explanation": "The Bohr effect describes how increased CO2/decreased pH reduces hemoglobin's oxygen affinity."},{"id": 2067,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Increased 2,3-diphosphoglycerate (2,3-DPG) in red blood cells causes:","options": [{"key": "A","text": "Leftward shift of the O2-Hb curve"},{"key": "B","text": "No effect on oxygen affinity"},{"key": "C","text": "Increased hemoglobin synthesis only"},{"key": "D","text": "Rightward shift of the O2-Hb curve, facilitating O2 release"}],"correct": "D","explanation": "2,3-DPG binds deoxyhemoglobin and decreases its oxygen affinity, shifting the curve rightward."},{"id": 2068,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Fetal hemoglobin (HbF) has, compared to adult hemoglobin (HbA):","options": [{"key": "A","text": "Higher affinity for oxygen, facilitating placental oxygen transfer"},{"key": "B","text": "Identical oxygen affinity"},{"key": "C","text": "No ability to bind oxygen"},{"key": "D","text": "Lower affinity for oxygen"}],"correct": "A","explanation": "HbF binds 2,3-DPG less avidly, giving it higher O2 affinity, favoring O2 transfer from maternal blood."},{"id": 2069,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Carbon monoxide's affinity for hemoglobin compared to oxygen is approximately:","options": [{"key": "A","text": "About 1000 times less"},{"key": "B","text": "About 200-250 times greater"},{"key": "C","text": "Equal to oxygen"},{"key": "D","text": "About 10 times greater"}],"correct": "B","explanation": "CO binds hemoglobin with roughly 200-250 times the affinity of oxygen, causing severe hypoxia even at low CO levels."},{"id": 2070,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "The P50 of the oxygen-hemoglobin dissociation curve refers to:","options": [{"key": "A","text": "The pH at 50% saturation"},{"key": "B","text": "The pCO2 at 50% saturation"},{"key": "C","text": "The pO2 at which hemoglobin is 50% saturated"},{"key": "D","text": "The pO2 at which hemoglobin is 100% saturated"}],"correct": "C","explanation": "P50 is the partial pressure of oxygen at which hemoglobin is half-saturated; normally about 26-27 mmHg."},{"id": 2071,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal P50 value for adult hemoglobin is approximately:","options": [{"key": "A","text": "60 mmHg"},{"key": "B","text": "10 mmHg"},{"key": "C","text": "26-27 mmHg"},{"key": "D","text": "100 mmHg"}],"correct": "C","explanation": "The normal P50 (pO2 at 50% saturation) is about 26-27 mmHg."},{"id": 2072,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Carbon dioxide is transported in the blood mainly in which forms?","options": [{"key": "A","text": "Dissolved CO2, carbaminohemoglobin, and bicarbonate ion"},{"key": "B","text": "Only bound to plasma albumin"},{"key": "C","text": "Only dissolved in plasma"},{"key": "D","text": "Only as carboxyhemoglobin"}],"correct": "A","explanation": "CO2 is carried as dissolved gas (~7%), carbamino compounds (~23%), and bicarbonate (~70%)."},{"id": 2073,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The majority (approximately 70%) of CO2 in blood is transported as:","options": [{"key": "A","text": "Carbonic acid"},{"key": "B","text": "Dissolved CO2 in plasma"},{"key": "C","text": "Bicarbonate ion (HCO3-)"},{"key": "D","text": "Carbaminohemoglobin"}],"correct": "C","explanation": "Most CO2 is converted to bicarbonate ion within red blood cells and transported in plasma."},{"id": 2074,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "The enzyme responsible for converting CO2 and water to carbonic acid within red blood cells is:","options": [{"key": "A","text": "Cytochrome oxidase"},{"key": "B","text": "Carbonic anhydrase"},{"key": "C","text": "Hemoglobinase"},{"key": "D","text": "Lactate dehydrogenase"}],"correct": "B","explanation": "Carbonic anhydrase catalyzes CO2 + H2O to H2CO3, which dissociates into H+ and HCO3-."},{"id": 2075,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The chloride shift refers to:","options": [{"key": "A","text": "Movement of oxygen out of red blood cells"},{"key": "B","text": "Diffusion of CO2 into plasma"},{"key": "C","text": "Movement of chloride into red blood cells in exchange for bicarbonate moving out"},{"key": "D","text": "Exchange of sodium for potassium"}],"correct": "C","explanation": "As bicarbonate exits red cells into plasma, chloride ions enter to maintain electrical neutrality (chloride/Hamburger shift)."},{"id": 2076,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Haldane effect describes:","options": [{"key": "A","text": "The effect of oxygenation on hemoglobin's capacity to carry CO2"},{"key": "B","text": "The effect of CO2 on oxygen affinity of hemoglobin"},{"key": "C","text": "The effect of temperature on CO2 solubility"},{"key": "D","text": "The effect of altitude on hemoglobin synthesis"}],"correct": "A","explanation": "Oxygenated hemoglobin has a reduced ability to bind CO2 and H+, promoting CO2 release in the lungs (Haldane effect)."},{"id": 2077,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Deoxygenated hemoglobin, compared to oxygenated hemoglobin, has:","options": [{"key": "A","text": "Higher affinity for oxygen"},{"key": "B","text": "No difference in CO2/H+ binding"},{"key": "C","text": "Higher affinity for CO2 and H+, facilitating CO2 transport from tissues"},{"key": "D","text": "Lower affinity for CO2 and H+"}],"correct": "C","explanation": "Deoxyhemoglobin binds CO2 and H+ more readily, aiding CO2 uptake in peripheral tissues."},{"id": 2078,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "Normal arterial CO2 content is transported at a partial pressure of approximately:","options": [{"key": "A","text": "20 mmHg"},{"key": "B","text": "60 mmHg"},{"key": "C","text": "80 mmHg"},{"key": "D","text": "40 mmHg"}],"correct": "D","explanation": "Normal arterial pCO2 is about 40 mmHg."},{"id": 2079,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "The amount of oxygen dissolved in plasma (not bound to Hb) is proportional to pO2 according to:","options": [{"key": "A","text": "Fick's law"},{"key": "B","text": "Boyle's law"},{"key": "C","text": "Dalton's law"},{"key": "D","text": "Henry's law"}],"correct": "D","explanation": "Henry's law states that the amount of gas dissolved in a liquid is proportional to its partial pressure."},{"id": 2080,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Hard","question": "Total oxygen content of arterial blood is calculated using the formula:","options": [{"key": "A","text": "(Hb x 1.34 x SaO2) + (0.003 x pO2)"},{"key": "B","text": "Hb x pO2 only"},{"key": "C","text": "SaO2 x pO2"},{"key": "D","text": "Hb / pO2"}],"correct": "A","explanation": "Arterial O2 content = (Hb concentration x 1.34 x % saturation) + dissolved O2 (0.003 x pO2)."},{"id": 2081,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Hard","question": "In carbon monoxide poisoning, the oxygen-hemoglobin dissociation curve typically shifts:","options": [{"key": "A","text": "Does not shift"},{"key": "B","text": "To the right"},{"key": "C","text": "Becomes linear"},{"key": "D","text": "To the left, further impairing O2 unloading to tissues"}],"correct": "D","explanation": "CO binding shifts the curve left, increasing the remaining hemoglobin's affinity for O2 and worsening tissue hypoxia."},{"id": 2082,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Which factor causes a LEFTWARD shift of the oxygen-hemoglobin dissociation curve?","options": [{"key": "A","text": "Decreased temperature and decreased pCO2"},{"key": "B","text": "Acidosis"},{"key": "C","text": "Increased 2,3-DPG"},{"key": "D","text": "Increased temperature"}],"correct": "A","explanation": "Decreased temperature, decreased pCO2 and alkalosis shift the curve left, increasing Hb-O2 affinity."},{"id": 2083,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Myoglobin's oxygen dissociation curve, compared to hemoglobin's, is:","options": [{"key": "A","text": "Identical to hemoglobin's curve"},{"key": "B","text": "Hyperbolic, with higher oxygen affinity, releasing O2 only at very low pO2"},{"key": "C","text": "Flat with no oxygen binding"},{"key": "D","text": "Sigmoid, similar to hemoglobin"}],"correct": "B","explanation": "Myoglobin has a hyperbolic curve and very high O2 affinity, serving as an oxygen store in muscle."},{"id": 2084,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Normal oxygen consumption at rest in an average adult is approximately:","options": [{"key": "A","text": "1500 ml/min"},{"key": "B","text": "250 ml/min"},{"key": "C","text": "750 ml/min"},{"key": "D","text": "50 ml/min"}],"correct": "B","explanation": "Resting oxygen consumption (VO2) is approximately 250 ml/min."},{"id": 2085,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The primary respiratory rhythm-generating center is located in the:","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Hypothalamus"},{"key": "C","text": "Medulla oblongata"},{"key": "D","text": "Cerebral cortex"}],"correct": "C","explanation": "The medullary respiratory center (dorsal and ventral respiratory groups) generates the basic rhythm of breathing."},{"id": 2086,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The pneumotaxic center, which limits inspiration and helps control respiratory rate, is located in the:","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Spinal cord"},{"key": "C","text": "Medulla"},{"key": "D","text": "Upper pons"}],"correct": "D","explanation": "The pneumotaxic center in the upper pons regulates the switch from inspiration to expiration."},{"id": 2087,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The apneustic center, which promotes prolonged inspiratory gasps when unopposed, is located in the:","options": [{"key": "A","text": "Midbrain"},{"key": "B","text": "Lower pons"},{"key": "C","text": "Upper pons"},{"key": "D","text": "Medulla"}],"correct": "B","explanation": "The apneustic center in the lower pons sends signals that prolong inspiration."},{"id": 2088,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The most important chemical stimulus for regulation of ventilation under normal conditions is:","options": [{"key": "A","text": "Arterial pCO2 (via central chemoreceptors and CSF pH)"},{"key": "B","text": "Arterial pO2"},{"key": "C","text": "Body temperature"},{"key": "D","text": "Blood glucose"}],"correct": "A","explanation": "Under normal conditions, arterial pCO2 (through its effect on CSF/brain pH) is the dominant driver of ventilation."},{"id": 2089,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Central chemoreceptors, located near the medulla, respond primarily to changes in:","options": [{"key": "A","text": "Hydrogen ion concentration of the CSF (reflecting CO2 levels)"},{"key": "B","text": "Arterial pO2"},{"key": "C","text": "Blood glucose"},{"key": "D","text": "Blood pressure"}],"correct": "A","explanation": "Central chemoreceptors sense the pH of the surrounding CSF, which changes with CO2 diffusion across the blood-brain barrier."},{"id": 2090,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Peripheral chemoreceptors (carotid and aortic bodies) are the primary sensors for:","options": [{"key": "A","text": "Decreased arterial pO2 (hypoxia)"},{"key": "B","text": "Blood volume changes"},{"key": "C","text": "Body temperature"},{"key": "D","text": "Increased arterial pO2"}],"correct": "A","explanation": "Peripheral chemoreceptors are chiefly responsible for detecting hypoxemia and stimulating ventilation."},{"id": 2091,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Medium","question": "Peripheral chemoreceptors become the dominant drive for ventilation when arterial pO2 falls below approximately:","options": [{"key": "A","text": "40 mmHg"},{"key": "B","text": "80 mmHg"},{"key": "C","text": "100 mmHg"},{"key": "D","text": "60 mmHg"}],"correct": "D","explanation": "Peripheral chemoreceptor stimulation of ventilation becomes significant when pO2 drops below about 60 mmHg."},{"id": 2092,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The Hering-Breuer reflex is initiated by:","options": [{"key": "A","text": "Muscle spindles in respiratory muscles"},{"key": "B","text": "Stretch receptors in the lungs/airways during lung inflation, inhibiting further inspiration"},{"key": "C","text": "Chemoreceptors sensing high CO2"},{"key": "D","text": "Baroreceptors in the carotid sinus"}],"correct": "B","explanation": "Pulmonary stretch receptors, activated by lung inflation, send inhibitory signals to prevent overinflation."},{"id": 2093,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In patients with chronic CO2 retention (e.g., severe COPD), the primary drive to breathe may shift to:","options": [{"key": "A","text": "Blood pH alone"},{"key": "B","text": "Hypoxia (the 'hypoxic drive')"},{"key": "C","text": "Body temperature"},{"key": "D","text": "Hypercapnia (as in normal individuals)"}],"correct": "B","explanation": "With chronically elevated CO2, central chemoreceptor sensitivity to CO2 may blunt, making hypoxia the main respiratory stimulus."},{"id": 2094,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The J (juxtacapillary) receptors, located near pulmonary capillaries, are stimulated by:","options": [{"key": "A","text": "Low blood pressure"},{"key": "B","text": "Muscle exercise"},{"key": "C","text": "High altitude only"},{"key": "D","text": "Pulmonary capillary congestion/edema, causing rapid shallow breathing"}],"correct": "D","explanation": "J receptors respond to interstitial fluid accumulation in the lung, producing rapid shallow breathing and dyspnea sensation."},{"id": 2095,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "During voluntary breath-holding, the breaking point is primarily determined by:","options": [{"key": "A","text": "Fatigue of respiratory muscles alone"},{"key": "B","text": "Rising arterial pCO2 (and falling pO2) stimulating chemoreceptors"},{"key": "C","text": "A fixed time limit set by the cortex"},{"key": "D","text": "Decreased body temperature"}],"correct": "B","explanation": "Breath-holding ends mainly when rising CO2 (and to a lesser extent falling O2) overcomes voluntary inhibition."},{"id": 2096,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Hard","question": "Hyperventilation before breath-holding (as in shallow-water blackout) is dangerous because it:","options": [{"key": "A","text": "Has no effect on chemoreceptors"},{"key": "B","text": "Increases carbon dioxide stores"},{"key": "C","text": "Increases arterial pO2 substantially"},{"key": "D","text": "Lowers arterial pCO2 without significantly raising pO2, delaying the urge to breathe while hypoxia progresses"}],"correct": "D","explanation": "Pre-hyperventilation lowers CO2 (delaying the breathing urge) while O2 stores are still limited, risking hypoxic blackout before the urge to breathe returns."},{"id": 2097,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Voluntary control of breathing (e.g., during speech) originates from the:","options": [{"key": "A","text": "Cerebral cortex, via corticospinal pathways bypassing the medullary centers"},{"key": "B","text": "Medulla only"},{"key": "C","text": "Hypothalamus exclusively"},{"key": "D","text": "Cerebellum exclusively"}],"correct": "A","explanation": "Voluntary breathing control involves direct corticospinal pathways to respiratory motor neurons, distinct from automatic medullary control."},{"id": 2098,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Exercise-induced hyperventilation is primarily triggered, at least initially, by:","options": [{"key": "A","text": "A fall in arterial pH below normal"},{"key": "B","text": "Decreased body temperature"},{"key": "C","text": "A rise in arterial pCO2"},{"key": "D","text": "Neural factors (motor cortex activation and joint/muscle receptor input) rather than chemical changes"}],"correct": "D","explanation": "Early in exercise, ventilation increases abruptly due to neural/anticipatory signals before significant chemical changes occur."},{"id": 2099,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal resting respiratory rate in an adult is approximately:","options": [{"key": "A","text": "4-8 breaths/min"},{"key": "B","text": "12-16 breaths/min"},{"key": "C","text": "35-40 breaths/min"},{"key": "D","text": "25-30 breaths/min"}],"correct": "B","explanation": "Normal resting respiratory rate in adults is about 12-16 breaths per minute."},{"id": 2100,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The dorsal respiratory group of the medulla is primarily responsible for:","options": [{"key": "A","text": "Voluntary breath holding"},{"key": "B","text": "Pneumotaxic limitation of inspiration"},{"key": "C","text": "Active forced expiration only"},{"key": "D","text": "Generating the basic inspiratory rhythm"}],"correct": "D","explanation": "The dorsal respiratory group primarily controls the basic rhythmic inspiratory drive."},{"id": 2101,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The ventral respiratory group of the medulla becomes especially active during:","options": [{"key": "A","text": "Quiet resting breathing only"},{"key": "B","text": "Breath holding"},{"key": "C","text": "Forced (active) expiration and increased ventilatory demand"},{"key": "D","text": "Sleep only"}],"correct": "C","explanation": "The ventral respiratory group is largely inactive at rest but recruits expiratory muscles during increased ventilatory demand."},{"id": 2102,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "An increase in blood hydrogen ion concentration (metabolic acidosis) stimulates ventilation primarily via:","options": [{"key": "A","text": "Central chemoreceptors, since H+ crosses the blood-brain barrier easily"},{"key": "B","text": "Stretch receptors only"},{"key": "C","text": "Peripheral chemoreceptors, since H+ does not readily cross the blood-brain barrier"},{"key": "D","text": "No chemoreceptor involvement"}],"correct": "C","explanation": "H+ ions cross the blood-brain barrier poorly, so metabolic acidosis is sensed mainly by peripheral chemoreceptors."},{"id": 2103,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In contrast, a rise in blood CO2 stimulates central chemoreceptors mainly because CO2:","options": [{"key": "A","text": "Directly stimulates peripheral chemoreceptors only"},{"key": "B","text": "Cannot cross the blood-brain barrier"},{"key": "C","text": "Readily diffuses across the blood-brain barrier and generates H+ in the CSF via carbonic anhydrase"},{"key": "D","text": "Has no effect on CSF pH"}],"correct": "C","explanation": "CO2 diffuses freely into CSF, where it forms carbonic acid, lowering CSF pH and stimulating central chemoreceptors."},{"id": 2104,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cheyne-Stokes breathing, a pattern of waxing and waning ventilation with periods of apnea, is commonly associated with:","options": [{"key": "A","text": "Acute exercise hyperventilation"},{"key": "B","text": "Healthy young athletes during exercise"},{"key": "C","text": "Normal sleep in all individuals"},{"key": "D","text": "Severe heart failure or brain injury affecting respiratory control"}],"correct": "D","explanation": "Cheyne-Stokes respiration reflects delayed feedback to respiratory centers, seen in heart failure, stroke, or high altitude."},{"id": 2105,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Hypoxic hypoxia (hypoxemic hypoxia) is characterized by:","options": [{"key": "A","text": "Normal arterial pO2 with reduced hemoglobin"},{"key": "B","text": "Reduced blood flow to tissues"},{"key": "C","text": "Reduced arterial pO2 due to inadequate oxygenation of blood in the lungs"},{"key": "D","text": "Normal oxygen delivery but impaired tissue utilization"}],"correct": "C","explanation": "Hypoxic hypoxia results from insufficient oxygenation of arterial blood, e.g., at high altitude or lung disease."},{"id": 2106,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Anemic hypoxia is characterized by:","options": [{"key": "A","text": "Inability of tissues to use oxygen"},{"key": "B","text": "Normal arterial pO2 but reduced oxygen-carrying capacity of blood (e.g., low hemoglobin)"},{"key": "C","text": "Reduced arterial pO2"},{"key": "D","text": "Reduced blood flow to tissues"}],"correct": "B","explanation": "In anemic hypoxia, arterial pO2 is normal, but reduced hemoglobin limits total oxygen content."},{"id": 2107,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Stagnant (circulatory) hypoxia results from:","options": [{"key": "A","text": "Reduced blood flow to tissues, e.g., in heart failure or shock"},{"key": "B","text": "Reduced hemoglobin concentration"},{"key": "C","text": "Inhibition of cellular respiratory enzymes"},{"key": "D","text": "Reduced arterial pO2"}],"correct": "A","explanation": "Stagnant hypoxia occurs when blood flow is too slow to deliver adequate oxygen, despite normal oxygen content."},{"id": 2108,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Histotoxic hypoxia occurs when:","options": [{"key": "A","text": "Blood flow to tissues is reduced"},{"key": "B","text": "Arterial pO2 is reduced"},{"key": "C","text": "Tissue cells are unable to utilize oxygen even though delivery is adequate (e.g., cyanide poisoning)"},{"key": "D","text": "Hemoglobin concentration is reduced"}],"correct": "C","explanation": "Histotoxic hypoxia results from poisoning of cellular oxidative enzymes (e.g., cyanide blocking cytochrome oxidase), impairing O2 utilization despite normal delivery."},{"id": 2109,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "At high altitude, the primary cause of hypoxia is:","options": [{"key": "A","text": "Cyanide-like enzyme poisoning"},{"key": "B","text": "Reduced hemoglobin concentration"},{"key": "C","text": "Increased blood flow to tissues"},{"key": "D","text": "Reduced barometric pressure lowering the partial pressure of inspired oxygen"}],"correct": "D","explanation": "Although the percentage of oxygen in air stays the same, the lower total barometric pressure at altitude reduces the partial pressure of oxygen."},{"id": 2110,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A key physiological (acclimatization) response to chronic high-altitude hypoxia is:","options": [{"key": "A","text": "Increased erythropoietin secretion, leading to polycythemia"},{"key": "B","text": "Decreased red blood cell production"},{"key": "C","text": "Decreased ventilation"},{"key": "D","text": "Decreased 2,3-DPG levels"}],"correct": "A","explanation": "Chronic hypoxia stimulates renal erythropoietin release, increasing red cell mass to enhance oxygen-carrying capacity."},{"id": 2111,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cyanosis, a bluish discoloration of skin/mucosa, typically becomes evident when deoxygenated hemoglobin in capillary blood exceeds approximately:","options": [{"key": "A","text": "5 g/dl"},{"key": "B","text": "20 g/dl"},{"key": "C","text": "10 g/dl"},{"key": "D","text": "1 g/dl"}],"correct": "A","explanation": "Cyanosis is usually apparent when deoxygenated hemoglobin concentration exceeds about 5 g/dl."},{"id": 2112,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "In severe anemia, cyanosis may be absent despite significant tissue hypoxia because:","options": [{"key": "A","text": "Arterial pO2 is very high"},{"key": "B","text": "There is insufficient total hemoglobin to produce the 5 g/dl deoxygenated threshold needed for visible cyanosis"},{"key": "C","text": "Deoxyhemoglobin is chemically different in anemia"},{"key": "D","text": "Anemia always increases oxygen saturation"}],"correct": "B","explanation": "With low total hemoglobin, even fully desaturated blood may not reach the absolute amount of deoxyhemoglobin required for visible cyanosis."},{"id": 2113,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Carbon monoxide poisoning causes hypoxia primarily by:","options": [{"key": "A","text": "Competing with oxygen for hemoglobin binding sites, forming carboxyhemoglobin"},{"key": "B","text": "Increasing 2,3-DPG production"},{"key": "C","text": "Directly damaging alveolar walls"},{"key": "D","text": "Causing bronchoconstriction"}],"correct": "A","explanation": "CO binds hemoglobin with very high affinity, drastically reducing the oxygen-carrying capacity of blood (a form of hypoxic/anemic hypoxia)."},{"id": 2114,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which of the following is a classic early symptom/sign of acute hypoxia?","options": [{"key": "A","text": "Hypothermia"},{"key": "B","text": "Decreased respiratory rate"},{"key": "C","text": "Bradycardia and hypotension"},{"key": "D","text": "Tachycardia, tachypnea, and impaired judgment/mental confusion"}],"correct": "D","explanation": "Early hypoxia typically triggers compensatory tachycardia and tachypnea along with early cognitive impairment."},{"id": 2115,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Spermatogenesis occurs within the:","options": [{"key": "A","text": "Epididymis"},{"key": "B","text": "Vas deferens"},{"key": "C","text": "Prostate gland"},{"key": "D","text": "Seminiferous tubules of the testis"}],"correct": "D","explanation": "Sperm production takes place in the seminiferous tubules of the testes."},{"id": 2116,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Sertoli cells in the testis primarily function to:","options": [{"key": "A","text": "Secrete testosterone"},{"key": "B","text": "Support, nourish, and regulate developing germ cells and form the blood-testis barrier"},{"key": "C","text": "Produce luteinizing hormone"},{"key": "D","text": "Store mature sperm"}],"correct": "B","explanation": "Sertoli cells provide structural and nutritional support to spermatogenic cells and form the blood-testis barrier."},{"id": 2117,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Leydig (interstitial) cells of the testis primarily secrete:","options": [{"key": "A","text": "Testosterone"},{"key": "B","text": "Follicle-stimulating hormone"},{"key": "C","text": "Inhibin"},{"key": "D","text": "Estrogen predominantly"}],"correct": "A","explanation": "Leydig cells, located in the interstitium between seminiferous tubules, are the main source of testosterone."},{"id": 2118,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Approximate total time required for complete spermatogenesis (from spermatogonium to mature sperm) is:","options": [{"key": "A","text": "64-74 days"},{"key": "B","text": "6 months"},{"key": "C","text": "24 days"},{"key": "D","text": "1 week"}],"correct": "A","explanation": "The full process of spermatogenesis takes approximately 64 to 74 days in humans."},{"id": 2119,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Luteinizing hormone (LH) in the male primarily stimulates:","options": [{"key": "A","text": "Spermatogonia directly"},{"key": "B","text": "Sertoli cells to produce inhibin"},{"key": "C","text": "The prostate gland"},{"key": "D","text": "Leydig cells to secrete testosterone"}],"correct": "D","explanation": "LH acts on Leydig cells to stimulate testosterone synthesis and secretion."},{"id": 2120,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Follicle-stimulating hormone (FSH) in the male primarily acts on:","options": [{"key": "A","text": "Sertoli cells to support spermatogenesis"},{"key": "B","text": "The epididymis directly"},{"key": "C","text": "The hypothalamus"},{"key": "D","text": "Leydig cells to produce testosterone"}],"correct": "A","explanation": "FSH stimulates Sertoli cells, promoting spermatogenesis and secretion of factors like inhibin."},{"id": 2121,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Inhibin, secreted by Sertoli cells, functions to:","options": [{"key": "A","text": "Stimulate testosterone production directly"},{"key": "B","text": "Increase LH secretion"},{"key": "C","text": "Stimulate FSH release from the pituitary"},{"key": "D","text": "Provide negative feedback inhibition of FSH secretion"}],"correct": "D","explanation": "Inhibin selectively suppresses FSH secretion from the anterior pituitary as part of a negative feedback loop."},{"id": 2122,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Sperm undergo maturation and acquire motility primarily during their passage through the:","options": [{"key": "A","text": "Seminiferous tubules"},{"key": "B","text": "Urethra"},{"key": "C","text": "Prostate gland"},{"key": "D","text": "Epididymis"}],"correct": "D","explanation": "Sperm gain motility and fertilizing capability during storage and transit through the epididymis."},{"id": 2123,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The majority of seminal fluid volume is contributed by the:","options": [{"key": "A","text": "Bulbourethral glands alone"},{"key": "B","text": "Testes"},{"key": "C","text": "Epididymis"},{"key": "D","text": "Seminal vesicles and prostate gland"}],"correct": "D","explanation": "The seminal vesicles and prostate gland together contribute the bulk of seminal fluid volume."},{"id": 2124,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Capacitation of sperm refers to:","options": [{"key": "A","text": "Functional changes sperm undergo in the female reproductive tract enabling fertilization"},{"key": "B","text": "The process of spermatogenesis"},{"key": "C","text": "Formation of the acrosome"},{"key": "D","text": "Sperm storage in the epididymis"}],"correct": "A","explanation": "Capacitation involves biochemical changes to sperm within the female tract that are necessary before fertilization can occur."},{"id": 2125,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Medium","question": "The acrosome of a sperm cell contains enzymes primarily important for:","options": [{"key": "A","text": "Providing energy for sperm motility"},{"key": "B","text": "Determining genetic sex only"},{"key": "C","text": "Penetrating the zona pellucida of the ovum during fertilization"},{"key": "D","text": "Producing testosterone"}],"correct": "C","explanation": "The acrosomal cap contains hydrolytic enzymes that help sperm penetrate the oocyte's outer layers."},{"id": 2126,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Testosterone is essential during fetal development for:","options": [{"key": "A","text": "Development of female internal genitalia"},{"key": "B","text": "Development of the mammary glands"},{"key": "C","text": "Formation of the placenta"},{"key": "D","text": "Differentiation of male internal genitalia (Wolffian duct derivatives) and external genitalia"}],"correct": "D","explanation": "Fetal testosterone drives development of male internal and external genital structures."},{"id": 2127,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The blood-testis barrier, formed by tight junctions between Sertoli cells, primarily functions to:","options": [{"key": "A","text": "Prevent testosterone secretion"},{"key": "B","text": "Prevent hormones from reaching the testis"},{"key": "C","text": "Protect developing germ cells from the immune system and maintain a controlled microenvironment"},{"key": "D","text": "Block blood supply to the testis"}],"correct": "C","explanation": "The barrier isolates developing germ cells (which express novel surface antigens) from immune surveillance."},{"id": 2128,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Anti-Müllerian hormone, secreted by fetal Sertoli cells, functions to:","options": [{"key": "A","text": "Stimulate testosterone secretion"},{"key": "B","text": "Promote formation of the epididymis"},{"key": "C","text": "Stimulate development of female reproductive structures"},{"key": "D","text": "Cause regression of the Müllerian (paramesonephric) ducts in the male fetus"}],"correct": "D","explanation": "Anti-Müllerian hormone causes regression of the Müllerian ducts, preventing development of female internal structures in males."},{"id": 2129,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal semen volume per ejaculate is approximately:","options": [{"key": "A","text": "10-15 ml"},{"key": "B","text": "2-5 ml"},{"key": "C","text": "0.5 ml"},{"key": "D","text": "20-30 ml"}],"correct": "B","explanation": "A typical ejaculate volume is around 2 to 5 ml."},{"id": 2130,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Oogenesis begins during fetal life with oogonia arresting in prophase of meiosis I until:","options": [{"key": "A","text": "Birth"},{"key": "B","text": "Puberty"},{"key": "C","text": "Just before ovulation, when the LH surge triggers resumption of meiosis"},{"key": "D","text": "Menopause"}],"correct": "C","explanation": "Primary oocytes remain arrested in prophase I from fetal life until the preovulatory LH surge triggers resumption of meiosis."},{"id": 2131,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A woman is born with her maximum number of oocytes, which then progressively decreases through a process called:","options": [{"key": "A","text": "Fertilization"},{"key": "B","text": "Ovulation only"},{"key": "C","text": "Atresia"},{"key": "D","text": "Implantation"}],"correct": "C","explanation": "Most oocytes undergo atresia (degeneration) throughout life, with only a small fraction ever ovulated."},{"id": 2132,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The dominant follicle destined for ovulation is typically selected during which phase of the ovarian cycle?","options": [{"key": "A","text": "During menstruation only"},{"key": "B","text": "Early to mid-follicular phase"},{"key": "C","text": "Immediately after ovulation"},{"key": "D","text": "Luteal phase"}],"correct": "B","explanation": "Follicular selection and dominance occur during the follicular phase, under FSH influence."},{"id": 2133,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Granulosa cells of the ovarian follicle primarily secrete which hormone in response to FSH?","options": [{"key": "A","text": "Estrogen (estradiol)"},{"key": "B","text": "Human chorionic gonadotropin"},{"key": "C","text": "Testosterone"},{"key": "D","text": "Progesterone predominantly before ovulation"}],"correct": "A","explanation": "FSH stimulates granulosa cells to convert androgens (from theca cells) into estrogen via aromatase."},{"id": 2134,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Theca cells of the ovarian follicle primarily produce, under LH stimulation:","options": [{"key": "A","text": "Progesterone exclusively"},{"key": "B","text": "Androgens, which are converted to estrogen by neighboring granulosa cells"},{"key": "C","text": "Estrogen directly"},{"key": "D","text": "Inhibin only"}],"correct": "B","explanation": "LH stimulates theca cells to produce androgens, which diffuse to granulosa cells for aromatization to estrogen (two-cell, two-gonadotropin theory)."},{"id": 2135,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Ovulation is triggered primarily by:","options": [{"key": "A","text": "A surge in luteinizing hormone (LH surge)"},{"key": "B","text": "A rise in progesterone before estrogen peaks"},{"key": "C","text": "A surge in FSH only"},{"key": "D","text": "A fall in estrogen"}],"correct": "A","explanation": "The LH surge, triggered by peak estrogen levels via positive feedback, precipitates ovulation."},{"id": 2136,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Following ovulation, the ruptured follicle transforms into the:","options": [{"key": "A","text": "Corpus albicans"},{"key": "B","text": "Primary follicle"},{"key": "C","text": "Graafian follicle"},{"key": "D","text": "Corpus luteum"}],"correct": "D","explanation": "The corpus luteum forms from the remnants of the ovulated follicle and secretes progesterone."},{"id": 2137,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "The corpus luteum primarily secretes which hormone to maintain the endometrium?","options": [{"key": "A","text": "Estrogen only"},{"key": "B","text": "Follicle-stimulating hormone"},{"key": "C","text": "Prolactin"},{"key": "D","text": "Progesterone"}],"correct": "D","explanation": "The corpus luteum secretes progesterone (and some estrogen) to maintain the secretory endometrium."},{"id": 2138,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In the absence of fertilization, the corpus luteum degenerates into the:","options": [{"key": "A","text": "Antral follicle"},{"key": "B","text": "Corpus albicans"},{"key": "C","text": "Graafian follicle"},{"key": "D","text": "Primary follicle"}],"correct": "B","explanation": "Without hCG support from a pregnancy, the corpus luteum regresses into scar tissue called the corpus albicans."},{"id": 2139,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Estrogen's effect on the endometrium during the follicular phase is primarily to cause:","options": [{"key": "A","text": "Proliferation of the endometrial lining"},{"key": "B","text": "Decidualization"},{"key": "C","text": "Sloughing of the endometrium"},{"key": "D","text": "Secretory changes"}],"correct": "A","explanation": "Estrogen drives proliferative growth of the endometrium in the first half of the cycle."},{"id": 2140,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Progesterone's effect on the endometrium during the luteal phase is primarily to promote:","options": [{"key": "A","text": "Endometrial shedding immediately"},{"key": "B","text": "Vasoconstriction leading to menstruation directly"},{"key": "C","text": "Continued proliferation"},{"key": "D","text": "Secretory transformation, preparing the endometrium for implantation"}],"correct": "D","explanation": "Progesterone converts the proliferative endometrium into a secretory, implantation-ready state."},{"id": 2141,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Estrogen exerts positive feedback on LH secretion when its levels are:","options": [{"key": "A","text": "Low and rising slowly"},{"key": "B","text": "High and sustained, as occurs just before ovulation"},{"key": "C","text": "Absent"},{"key": "D","text": "Falling rapidly"}],"correct": "B","explanation": "Sustained high estrogen levels in the late follicular phase switch feedback on the hypothalamic-pituitary axis from negative to positive, triggering the LH surge."},{"id": 2142,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "At normal (lower) concentrations, estrogen and progesterone act on the hypothalamic-pituitary axis primarily through:","options": [{"key": "A","text": "Negative feedback, suppressing GnRH/LH/FSH secretion"},{"key": "B","text": "Positive feedback, increasing GnRH/LH/FSH secretion"},{"key": "C","text": "No feedback effect at all"},{"key": "D","text": "Only stimulating prolactin"}],"correct": "A","explanation": "Under most circumstances, ovarian steroids exert negative feedback to regulate gonadotropin secretion."},{"id": 2143,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The cervical mucus around the time of ovulation typically becomes:","options": [{"key": "A","text": "Absent entirely"},{"key": "B","text": "Thick and scant, blocking sperm passage"},{"key": "C","text": "Thin, clear, and stretchy (spinnbarkeit), facilitating sperm transport"},{"key": "D","text": "Acidic and hostile to sperm"}],"correct": "C","explanation": "High estrogen at ovulation produces thin, elastic cervical mucus favorable for sperm penetration."},{"id": 2144,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Basal body temperature typically rises after ovulation due to the thermogenic effect of:","options": [{"key": "A","text": "LH"},{"key": "B","text": "Estrogen"},{"key": "C","text": "Progesterone"},{"key": "D","text": "FSH"}],"correct": "C","explanation": "Progesterone secreted by the corpus luteum after ovulation raises basal body temperature slightly, used to track ovulation."},{"id": 2145,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The average length of the human menstrual cycle is approximately:","options": [{"key": "A","text": "21 days"},{"key": "B","text": "40 days"},{"key": "C","text": "28 days"},{"key": "D","text": "14 days"}],"correct": "C","explanation": "The menstrual cycle averages about 28 days, though normal variation is common."},{"id": 2146,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The menstrual cycle is conventionally divided into which phases (ovarian cycle perspective)?","options": [{"key": "A","text": "Follicular and luteal phases"},{"key": "B","text": "Implantation and gestational phases"},{"key": "C","text": "Menstrual and ovulatory phases only"},{"key": "D","text": "Proliferative and secretory phases only"}],"correct": "A","explanation": "From the ovarian perspective, the cycle consists of the follicular phase and luteal phase, separated by ovulation."},{"id": 2147,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "From the endometrial perspective, the two main phases of the menstrual cycle are the:","options": [{"key": "A","text": "Proliferative and secretory phases"},{"key": "B","text": "Implantation and regression phases"},{"key": "C","text": "Follicular and luteal phases"},{"key": "D","text": "Menstrual and ovulatory phases"}],"correct": "A","explanation": "The endometrium undergoes proliferative (estrogen-driven) and secretory (progesterone-driven) phases."},{"id": 2148,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Ovulation typically occurs approximately how many days before the onset of the next menstrual period, in a regular 28-day cycle?","options": [{"key": "A","text": "3-4 days"},{"key": "B","text": "14 days"},{"key": "C","text": "21 days"},{"key": "D","text": "28 days"}],"correct": "B","explanation": "The luteal phase is relatively fixed at about 14 days, so ovulation occurs roughly 14 days before the next menses regardless of cycle length."},{"id": 2149,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The follicular phase of the ovarian cycle is characterized by:","options": [{"key": "A","text": "A constant hormone profile"},{"key": "B","text": "Rising progesterone and falling estrogen"},{"key": "C","text": "Dominance of the corpus luteum"},{"key": "D","text": "Rising FSH stimulating follicular growth and increasing estrogen secretion"}],"correct": "D","explanation": "During the follicular phase, FSH stimulates follicle development, and estrogen levels rise progressively."},{"id": 2150,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The luteal phase of the ovarian cycle is characterized by:","options": [{"key": "A","text": "Continued follicular growth"},{"key": "B","text": "The LH surge occurring at its midpoint"},{"key": "C","text": "Peak estrogen with no progesterone"},{"key": "D","text": "Dominance of the corpus luteum secreting progesterone"}],"correct": "D","explanation": "After ovulation, the corpus luteum dominates, primarily secreting progesterone (with some estrogen)."},{"id": 2151,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Menstruation (endometrial shedding) occurs due to:","options": [{"key": "A","text": "The LH surge"},{"key": "B","text": "Peak FSH levels"},{"key": "C","text": "Withdrawal of estrogen and progesterone as the corpus luteum regresses, causing spiral artery constriction and ischemia"},{"key": "D","text": "Sustained high progesterone levels"}],"correct": "C","explanation": "Falling steroid hormone levels at the end of the luteal phase cause spiral artery vasoconstriction, ischemia, and shedding of the functional endometrial layer."},{"id": 2152,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The average duration of menstrual flow is approximately:","options": [{"key": "A","text": "15 days"},{"key": "B","text": "3-5 days"},{"key": "C","text": "1 day"},{"key": "D","text": "10-12 days"}],"correct": "B","explanation": "Menstrual bleeding typically lasts about 3 to 5 days."},{"id": 2153,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Average blood loss during a normal menstrual period is approximately:","options": [{"key": "A","text": "500 ml"},{"key": "B","text": "5-10 ml"},{"key": "C","text": "150-200 ml"},{"key": "D","text": "30-40 ml"}],"correct": "D","explanation": "Average menstrual blood loss is estimated at about 30-40 ml per cycle."},{"id": 2154,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Which hormone shows a characteristic mid-cycle surge that directly triggers ovulation?","options": [{"key": "A","text": "Prolactin"},{"key": "B","text": "Luteinizing hormone"},{"key": "C","text": "Progesterone"},{"key": "D","text": "Follicle-stimulating hormone (as the dominant surge)"}],"correct": "B","explanation": "The LH surge, occurring about 24-36 hours before ovulation, is the direct trigger for follicular rupture."},{"id": 2155,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Gonadotropin-releasing hormone (GnRH) is secreted by the hypothalamus in a characteristic pattern described as:","options": [{"key": "A","text": "Pulsatile secretion"},{"key": "B","text": "A single large surge only at puberty"},{"key": "C","text": "Continuous, steady secretion"},{"key": "D","text": "Only during pregnancy"}],"correct": "A","explanation": "GnRH is released in discrete pulses, and this pulsatile pattern is essential for normal gonadotropin secretion."},{"id": 2156,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Continuous (non-pulsatile) administration of GnRH or its analogs results in:","options": [{"key": "A","text": "Sustained stimulation of LH/FSH secretion"},{"key": "B","text": "No effect on the pituitary"},{"key": "C","text": "Immediate ovulation"},{"key": "D","text": "Downregulation and eventual suppression of LH/FSH secretion"}],"correct": "D","explanation": "Continuous GnRH exposure desensitizes pituitary receptors, paradoxically suppressing gonadotropin secretion - the basis for GnRH agonist therapy."},{"id": 2157,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "During the proliferative phase, the endometrium primarily thickens under the influence of:","options": [{"key": "A","text": "Estrogen"},{"key": "B","text": "hCG"},{"key": "C","text": "Progesterone"},{"key": "D","text": "Prolactin"}],"correct": "A","explanation": "Estrogen secreted by the growing follicle drives proliferative regrowth of the endometrium after menstruation."},{"id": 2158,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "During the secretory phase, endometrial glands become coiled and begin secreting glycogen-rich fluid under the influence of:","options": [{"key": "A","text": "FSH"},{"key": "B","text": "LH"},{"key": "C","text": "Estrogen alone"},{"key": "D","text": "Progesterone (with estrogen)"}],"correct": "D","explanation": "Progesterone, secreted by the corpus luteum, transforms the endometrium into a secretory state suited for implantation."},{"id": 2159,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "If fertilization and implantation occur, the corpus luteum is rescued from regression primarily by:","options": [{"key": "A","text": "Rising FSH levels"},{"key": "B","text": "Prolactin"},{"key": "C","text": "Human chorionic gonadotropin (hCG) secreted by the developing trophoblast"},{"key": "D","text": "Estrogen from the ovary alone"}],"correct": "C","explanation": "hCG from the implanting embryo maintains the corpus luteum, sustaining progesterone secretion to support early pregnancy."},{"id": 2160,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Mittelschmerz refers to:","options": [{"key": "A","text": "Pain during implantation"},{"key": "B","text": "Pain during menstruation"},{"key": "C","text": "Labor pain"},{"key": "D","text": "Mid-cycle pelvic pain associated with ovulation"}],"correct": "D","explanation": "Mittelschmerz is unilateral pelvic pain some women experience around the time of ovulation."},{"id": 2161,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "In an anovulatory cycle, which hormone characteristically fails to show its usual rise?","options": [{"key": "A","text": "Progesterone (due to absence of a functional corpus luteum)"},{"key": "B","text": "Estrogen"},{"key": "C","text": "GnRH"},{"key": "D","text": "FSH"}],"correct": "A","explanation": "Without ovulation, no corpus luteum forms, so the characteristic luteal-phase rise in progesterone does not occur."},{"id": 2162,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "The negative feedback effect of low-to-moderate estrogen levels on the hypothalamic-pituitary axis primarily suppresses secretion of:","options": [{"key": "A","text": "GnRH, and consequently FSH and LH"},{"key": "B","text": "Prolactin only"},{"key": "C","text": "hCG"},{"key": "D","text": "Oxytocin"}],"correct": "A","explanation": "Estrogen at typical follicular-phase levels suppresses GnRH pulsatility and pituitary gonadotropin release."},{"id": 2163,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which of the following best describes the change in basal body temperature across the menstrual cycle?","options": [{"key": "A","text": "Rises steadily throughout, independent of ovulation"},{"key": "B","text": "Lower in the follicular phase, rising after ovulation due to progesterone"},{"key": "C","text": "Higher in the follicular phase, falling after ovulation"},{"key": "D","text": "No change throughout the cycle"}],"correct": "B","explanation": "Basal body temperature is relatively low pre-ovulation and rises by about 0.3-0.5°C after ovulation due to progesterone's thermogenic effect."},{"id": 2164,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Climacteric changes associated with menopause result primarily from:","options": [{"key": "A","text": "Depletion of ovarian follicles, leading to declining estrogen and progesterone with rising FSH/LH"},{"key": "B","text": "Excessive ovarian estrogen production"},{"key": "C","text": "Increased corpus luteum activity"},{"key": "D","text": "Pituitary failure to secrete gonadotropins"}],"correct": "A","explanation": "Menopause results from exhaustion of ovarian follicular reserve, causing falling estrogen/progesterone and compensatory rises in FSH/LH."},{"id": 2165,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Fertilization normally occurs in which part of the female reproductive tract?","options": [{"key": "A","text": "Ampulla of the fallopian tube"},{"key": "B","text": "Cervix"},{"key": "C","text": "Uterine cavity"},{"key": "D","text": "Ovary"}],"correct": "A","explanation": "Fertilization typically takes place in the ampullary region of the fallopian tube."},{"id": 2166,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Implantation of the blastocyst into the endometrium typically occurs approximately how many days after fertilization?","options": [{"key": "A","text": "6-7 days"},{"key": "B","text": "1-2 days"},{"key": "C","text": "14-15 days"},{"key": "D","text": "21-28 days"}],"correct": "A","explanation": "Implantation usually occurs around 6 to 7 days after fertilization, once the blastocyst reaches the uterus."},{"id": 2167,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Human chorionic gonadotropin (hCG), the hormone detected in pregnancy tests, is secreted by:","options": [{"key": "A","text": "The maternal pituitary"},{"key": "B","text": "The trophoblast/placenta"},{"key": "C","text": "The corpus luteum directly"},{"key": "D","text": "The maternal ovary"}],"correct": "B","explanation": "hCG is produced by the syncytiotrophoblast of the developing placenta shortly after implantation."},{"id": 2168,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The primary function of hCG in early pregnancy is to:","options": [{"key": "A","text": "Suppress maternal immune response only"},{"key": "B","text": "Maintain the corpus luteum, ensuring continued progesterone secretion"},{"key": "C","text": "Trigger labor"},{"key": "D","text": "Stimulate fetal growth hormone"}],"correct": "B","explanation": "hCG rescues and maintains the corpus luteum until the placenta itself can take over steroid hormone production."},{"id": 2169,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "By approximately which week of pregnancy does the placenta typically take over as the primary source of progesterone, allowing the corpus luteum to regress?","options": [{"key": "A","text": "8-10 weeks"},{"key": "B","text": "20 weeks"},{"key": "C","text": "36 weeks"},{"key": "D","text": "2-3 weeks"}],"correct": "A","explanation": "The placenta gradually assumes progesterone production, becoming the dominant source by about 8-10 weeks (the 'luteal-placental shift')."},{"id": 2170,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Human placental lactogen (hPL) primarily functions to:","options": [{"key": "A","text": "Trigger labor onset"},{"key": "B","text": "Promote maternal metabolic adaptations, including increased maternal insulin resistance to spare glucose for the fetus"},{"key": "C","text": "Stimulate maternal milk ejection"},{"key": "D","text": "Suppress fetal growth"}],"correct": "B","explanation": "hPL alters maternal metabolism, promoting lipolysis and insulin resistance to ensure adequate glucose supply to the fetus."},{"id": 2171,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Relaxin, secreted during pregnancy mainly by the corpus luteum and placenta, functions to:","options": [{"key": "A","text": "Increase maternal blood pressure"},{"key": "B","text": "Increase uterine contractions"},{"key": "C","text": "Stimulate milk production"},{"key": "D","text": "Soften the cervix and relax pelvic ligaments in preparation for delivery"}],"correct": "D","explanation": "Relaxin helps soften the cervix and loosen pelvic connective tissue and ligaments before childbirth."},{"id": 2172,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Maternal blood volume during a normal pregnancy typically increases by approximately:","options": [{"key": "A","text": "30-50%"},{"key": "B","text": "20%"},{"key": "C","text": "100%"},{"key": "D","text": "5-10%"}],"correct": "A","explanation": "Maternal blood volume rises substantially, by about 30-50%, over the course of a normal pregnancy."},{"id": 2173,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Progesterone during pregnancy plays a key role in:","options": [{"key": "A","text": "Maintaining uterine quiescence by inhibiting myometrial contractility"},{"key": "B","text": "Stimulating strong uterine contractions"},{"key": "C","text": "Suppressing placental development"},{"key": "D","text": "Triggering the onset of labor"}],"correct": "A","explanation": "Progesterone suppresses uterine contractility throughout most of pregnancy, helping to prevent premature labor."},{"id": 2174,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The onset of labor is associated with a shift favoring:","options": [{"key": "A","text": "Complete absence of oxytocin"},{"key": "B","text": "Increased estrogen-to-progesterone ratio and rising oxytocin/prostaglandin activity promoting contractions"},{"key": "C","text": "Falling prostaglandin levels"},{"key": "D","text": "Progesterone dominance suppressing contractions"}],"correct": "B","explanation": "Labor onset involves relative increases in estrogen, oxytocin sensitivity, and prostaglandins that promote coordinated uterine contractions."},{"id": 2175,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Oxytocin, released from the posterior pituitary, stimulates labor primarily by:","options": [{"key": "A","text": "Causing rhythmic contraction of uterine smooth muscle"},{"key": "B","text": "Softening the cervix directly"},{"key": "C","text": "Inhibiting prostaglandin synthesis"},{"key": "D","text": "Relaxing the myometrium"}],"correct": "A","explanation": "Oxytocin acts on myometrial receptors to stimulate strong, coordinated uterine contractions during labor."},{"id": 2176,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The Ferguson reflex describes:","options": [{"key": "A","text": "A positive feedback loop where cervical/vaginal stretching during labor stimulates further oxytocin release"},{"key": "B","text": "Suppression of oxytocin release by cervical stretch"},{"key": "C","text": "Inhibition of uterine contractions by fetal movement"},{"key": "D","text": "A reflex controlling milk ejection only"}],"correct": "A","explanation": "Mechanical stretching of the cervix and vagina during labor reflexively increases oxytocin secretion, reinforcing contractions."},{"id": 2177,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "The primary hormone responsible for milk synthesis (milk production) by the mammary alveolar cells is:","options": [{"key": "A","text": "Oxytocin"},{"key": "B","text": "Estrogen"},{"key": "C","text": "Progesterone"},{"key": "D","text": "Prolactin"}],"correct": "D","explanation": "Prolactin, secreted by the anterior pituitary, stimulates milk protein and component synthesis in alveolar cells."},{"id": 2178,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "The primary hormone responsible for milk ejection (let-down reflex) is:","options": [{"key": "A","text": "Oxytocin"},{"key": "B","text": "Follicle-stimulating hormone"},{"key": "C","text": "Prolactin"},{"key": "D","text": "Growth hormone"}],"correct": "A","explanation": "Oxytocin causes contraction of myoepithelial cells around alveoli, ejecting milk into the ducts."},{"id": 2179,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "During pregnancy, despite high prolactin levels, significant milk production is prevented mainly by:","options": [{"key": "A","text": "High circulating levels of estrogen and progesterone inhibiting prolactin's action on the breast"},{"key": "B","text": "Low prolactin secretion"},{"key": "C","text": "Absence of oxytocin"},{"key": "D","text": "Low maternal blood volume"}],"correct": "A","explanation": "High estrogen and progesterone during pregnancy block prolactin's lactogenic effect on breast tissue."},{"id": 2180,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "After delivery, the abrupt fall in which hormones allows lactation to begin?","options": [{"key": "A","text": "Estrogen and progesterone"},{"key": "B","text": "Prolactin and oxytocin"},{"key": "C","text": "Cortisol and growth hormone"},{"key": "D","text": "FSH and LH"}],"correct": "A","explanation": "The sharp drop in placental estrogen and progesterone after delivery removes the inhibition on prolactin's action, allowing lactation to start."},{"id": 2181,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Suckling by the infant stimulates milk production and ejection through a neuroendocrine reflex that increases secretion of:","options": [{"key": "A","text": "Only FSH and LH"},{"key": "B","text": "Only cortisol"},{"key": "C","text": "Only growth hormone"},{"key": "D","text": "Both prolactin and oxytocin"}],"correct": "D","explanation": "Nipple stimulation from suckling reflexively increases both prolactin (production) and oxytocin (ejection) release."},{"id": 2182,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The 'let-down reflex' can be triggered even before or without direct suckling, for example by:","options": [{"key": "A","text": "Cold temperature exposure"},{"key": "B","text": "Increased blood glucose"},{"key": "C","text": "Sensory or psychological stimuli associated with the infant, such as its cry"},{"key": "D","text": "Physical exercise"}],"correct": "C","explanation": "Conditioned stimuli, such as hearing an infant cry, can trigger oxytocin release and milk ejection."},{"id": 2183,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Breastfeeding-associated suppression of ovulation (lactational amenorrhea) is primarily due to:","options": [{"key": "A","text": "Increased progesterone from the ovary"},{"key": "B","text": "Prolactin-mediated suppression of GnRH pulsatility, reducing LH/FSH secretion"},{"key": "C","text": "Increased FSH secretion"},{"key": "D","text": "Increased estrogen secretion"}],"correct": "B","explanation": "Elevated prolactin during frequent breastfeeding suppresses hypothalamic GnRH pulses, inhibiting ovulation."},{"id": 2184,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Colostrum, the first secretion produced by the mammary gland after delivery, is characterized by:","options": [{"key": "A","text": "Higher protein and immunoglobulin (particularly IgA) content than mature milk, providing passive immunity"},{"key": "B","text": "Lower protein and immunoglobulin content than mature milk"},{"key": "C","text": "Higher fat content than mature milk"},{"key": "D","text": "Absence of any nutritional value"}],"correct": "A","explanation": "Colostrum is rich in protein and secretory IgA, offering the newborn important passive immune protection."},{"id": 2185,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which glands contribute maximum volume of saliva at rest?","options": [{"key": "A","text": "Sublingual"},{"key": "B","text": "Buccal"},{"key": "C","text": "Submandibular"},{"key": "D","text": "Parotid"}],"correct": "C","explanation": "Submandibular glands secrete ~70% of resting saliva."},{"id": 2186,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Parotid gland secretes saliva that is:","options": [{"key": "A","text": "Watery mucous"},{"key": "B","text": "Mixed serous and mucous"},{"key": "C","text": "Purely serous"},{"key": "D","text": "Purely mucous"}],"correct": "C","explanation": "Parotid gland is a pure serous (watery, enzyme-rich) gland."},{"id": 2187,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Which enzyme in saliva initiates carbohydrate digestion?","options": [{"key": "A","text": "Lipase"},{"key": "B","text": "Pepsin"},{"key": "C","text": "Salivary amylase (ptyalin)"},{"key": "D","text": "Trypsin"}],"correct": "C","explanation": "Salivary amylase breaks starch into maltose and dextrins."},{"id": 2188,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Daily secretion of saliva is approximately:","options": [{"key": "A","text": "3000-3500 ml"},{"key": "B","text": "2000-2500 ml"},{"key": "C","text": "50-100 ml"},{"key": "D","text": "500-1000 ml"}],"correct": "D","explanation": "Normal daily saliva secretion is about 800-1500 ml (approx 1L)."},{"id": 2189,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Saliva is characteristically:","options": [{"key": "A","text": "Hypotonic to plasma"},{"key": "B","text": "Isotonic to plasma"},{"key": "C","text": "Equal in Na+ to plasma"},{"key": "D","text": "Hypertonic to plasma"}],"correct": "A","explanation": "Saliva is hypotonic because ductal cells reabsorb Na+/Cl- more than they secrete K+/HCO3-."},{"id": 2190,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which ion is secreted in higher concentration in saliva compared to plasma?","options": [{"key": "A","text": "Calcium"},{"key": "B","text": "Sodium"},{"key": "C","text": "Potassium and Bicarbonate"},{"key": "D","text": "Chloride"}],"correct": "C","explanation": "Salivary ducts secrete K+ and HCO3- while reabsorbing Na+ and Cl-."},{"id": 2191,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Salivary secretion is under control of:","options": [{"key": "A","text": "Hormonal control only"},{"key": "B","text": "Both sympathetic and parasympathetic NS"},{"key": "C","text": "Only sympathetic NS"},{"key": "D","text": "Only parasympathetic NS"}],"correct": "B","explanation": "Both autonomic divisions stimulate saliva secretion, though parasympathetic effect is stronger."},{"id": 2192,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Parasympathetic stimulation of salivary glands causes:","options": [{"key": "A","text": "Thick mucous secretion"},{"key": "B","text": "No secretion"},{"key": "C","text": "Decreased blood flow"},{"key": "D","text": "Copious watery secretion"}],"correct": "D","explanation": "Parasympathetic stimulation produces profuse watery, enzyme-rich saliva with vasodilation."},{"id": 2193,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Sympathetic stimulation of salivary glands produces:","options": [{"key": "A","text": "Complete cessation of saliva"},{"key": "B","text": "No change in saliva"},{"key": "C","text": "Small volume thick mucous saliva"},{"key": "D","text": "Copious watery saliva"}],"correct": "C","explanation": "Sympathetic stimulation gives small volume of thick, mucous-rich saliva."},{"id": 2194,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The lingual lipase is secreted by glands located in:","options": [{"key": "A","text": "Submandibular gland"},{"key": "B","text": "Von Ebner's glands of tongue"},{"key": "C","text": "Parotid gland"},{"key": "D","text": "Sublingual gland"}],"correct": "B","explanation": "Lingual lipase is secreted by Von Ebner's glands on the tongue's dorsal surface."},{"id": 2195,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "pH of saliva is approximately:","options": [{"key": "A","text": "8.5-9.0"},{"key": "B","text": "2.0-3.0"},{"key": "C","text": "6.0-7.4"},{"key": "D","text": "3.0-4.0"}],"correct": "C","explanation": "Resting saliva pH is slightly acidic to neutral (6.0-7.4)."},{"id": 2196,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which reflex mainly controls salivary secretion?","options": [{"key": "A","text": "Baroreceptor reflex"},{"key": "B","text": "Only spinal reflex"},{"key": "C","text": "Only local reflex"},{"key": "D","text": "Conditioned and unconditioned reflex"}],"correct": "D","explanation": "Salivation occurs via unconditioned (food in mouth) and conditioned (sight/smell) reflexes."},{"id": 2197,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Function of saliva does NOT include:","options": [{"key": "A","text": "Lubrication of food"},{"key": "B","text": "Digestion of starch"},{"key": "C","text": "Digestion of protein"},{"key": "D","text": "Antibacterial action"}],"correct": "C","explanation": "Saliva has no proteolytic enzyme; protein digestion begins in stomach."},{"id": 2198,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Salivary secretion is decreased in:","options": [{"key": "A","text": "Fear/anxiety"},{"key": "B","text": "Sleep"},{"key": "C","text": "Sight of food"},{"key": "D","text": "Chewing"}],"correct": "A","explanation": "Sympathetic dominance during fear/anxiety reduces salivary flow, causing dry mouth."},{"id": 2199,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Xerostomia refers to:","options": [{"key": "A","text": "Salivary stone"},{"key": "B","text": "Excess salivation"},{"key": "C","text": "Dryness of mouth due to reduced saliva"},{"key": "D","text": "Salivary gland tumor"}],"correct": "C","explanation": "Xerostomia is dry mouth caused by decreased salivary secretion."},{"id": 2200,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "HCl is secreted by which cells of gastric mucosa?","options": [{"key": "A","text": "Mucous neck cells"},{"key": "B","text": "Parietal (oxyntic) cells"},{"key": "C","text": "G cells"},{"key": "D","text": "Chief cells"}],"correct": "B","explanation": "Parietal cells secrete hydrochloric acid and intrinsic factor."},{"id": 2201,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Pepsinogen is secreted by:","options": [{"key": "A","text": "G cells"},{"key": "B","text": "Enterochromaffin-like cells"},{"key": "C","text": "Parietal cells"},{"key": "D","text": "Chief (peptic) cells"}],"correct": "D","explanation": "Chief cells secrete pepsinogen, the inactive precursor of pepsin."},{"id": 2202,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Intrinsic factor, essential for Vitamin B12 absorption, is secreted by:","options": [{"key": "A","text": "Chief cells"},{"key": "B","text": "Mucous cells"},{"key": "C","text": "G cells"},{"key": "D","text": "Parietal cells"}],"correct": "D","explanation": "Parietal cells secrete intrinsic factor along with HCl."},{"id": 2203,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Gastrin is secreted by which cells?","options": [{"key": "A","text": "Chief cells"},{"key": "B","text": "D cells"},{"key": "C","text": "G cells"},{"key": "D","text": "Parietal cells"}],"correct": "C","explanation": "G cells located in antrum of stomach secrete gastrin hormone."},{"id": 2204,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Gastrin stimulates gastric acid secretion mainly by acting on:","options": [{"key": "A","text": "Parietal cells directly and via histamine release from ECL cells"},{"key": "B","text": "Chief cells only"},{"key": "C","text": "Mucous cells only"},{"key": "D","text": "G cells themselves"}],"correct": "A","explanation": "Gastrin acts directly on parietal cells and indirectly via ECL-cell histamine release."},{"id": 2205,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Which substance is the most potent stimulator of gastric acid secretion?","options": [{"key": "A","text": "Secretin"},{"key": "B","text": "Histamine"},{"key": "C","text": "Acetylcholine"},{"key": "D","text": "Gastrin"}],"correct": "B","explanation": "Histamine (via H2 receptors) is the most potent acid secretagogue, potentiating gastrin/ACh."},{"id": 2206,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Cephalic phase of gastric secretion is mediated by:","options": [{"key": "A","text": "Cholecystokinin"},{"key": "B","text": "Local reflexes only"},{"key": "C","text": "Secretin"},{"key": "D","text": "Vagus nerve"}],"correct": "D","explanation": "Cephalic phase (sight, smell, thought of food) is mediated via vagal stimulation."},{"id": 2207,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Which phase of gastric secretion contributes the largest proportion of total gastric juice?","options": [{"key": "A","text": "Gastric phase"},{"key": "B","text": "Cephalic phase"},{"key": "C","text": "Basal phase"},{"key": "D","text": "Intestinal phase"}],"correct": "A","explanation": "Gastric phase contributes about 60-70% of total gastric secretion."},{"id": 2208,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Distension of stomach stimulates acid secretion via:","options": [{"key": "A","text": "Local and vagovagal reflexes"},{"key": "B","text": "Secretin release"},{"key": "C","text": "Sympathetic inhibition only"},{"key": "D","text": "CCK release"}],"correct": "A","explanation": "Gastric distension triggers local enteric reflexes and long vagovagal reflexes releasing gastrin."},{"id": 2209,"subject": "Physiology","topic": "GI Physiology","difficulty": "Hard","question": "Intestinal phase of gastric secretion is initially:","options": [{"key": "A","text": "Excitatory"},{"key": "B","text": "Only hormonal"},{"key": "C","text": "Absent"},{"key": "D","text": "Purely inhibitory"}],"correct": "A","explanation": "Intestinal phase begins excitatory (chyme entering duodenum stimulates gastrin release) then becomes inhibitory."},{"id": 2210,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Which hormone inhibits gastric acid secretion during intestinal phase?","options": [{"key": "A","text": "Acetylcholine"},{"key": "B","text": "Histamine"},{"key": "C","text": "Gastrin"},{"key": "D","text": "Secretin"}],"correct": "D","explanation": "Secretin, released due to acidic chyme in duodenum, inhibits gastric acid secretion."},{"id": 2211,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Enterogastric reflex causes:","options": [{"key": "A","text": "Increased pepsinogen secretion only"},{"key": "B","text": "Increased gastric motility"},{"key": "C","text": "Decreased gastric motility and secretion"},{"key": "D","text": "Increased HCl secretion"}],"correct": "C","explanation": "Enterogastric reflex, triggered by duodenal distension/acidity, inhibits gastric emptying and secretion."},{"id": 2212,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Somatostatin secreted by D cells of stomach acts to:","options": [{"key": "A","text": "Stimulate gastrin release"},{"key": "B","text": "Increase mucus secretion only"},{"key": "C","text": "Stimulate pepsinogen release"},{"key": "D","text": "Inhibit gastrin and acid secretion"}],"correct": "D","explanation": "Somatostatin inhibits gastrin release and directly inhibits parietal cell acid secretion."},{"id": 2213,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The final common pathway for HCl secretion from parietal cells involves which pump?","options": [{"key": "A","text": "H+/K+ ATPase (proton pump)"},{"key": "B","text": "Ca2+ ATPase"},{"key": "C","text": "Cl-/HCO3- exchanger only"},{"key": "D","text": "Na+/K+ ATPase"}],"correct": "A","explanation": "H+/K+ ATPase (proton pump) on canalicular membrane actively secretes H+ into stomach lumen."},{"id": 2214,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Which cells secrete mucus and bicarbonate to protect gastric mucosa?","options": [{"key": "A","text": "Parietal cells"},{"key": "B","text": "G cells"},{"key": "C","text": "Mucous neck and surface mucous cells"},{"key": "D","text": "Chief cells"}],"correct": "C","explanation": "Surface mucous cells secrete alkaline mucus forming a protective barrier against acid."},{"id": 2215,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Basal Acid Output (BAO) is normally measured over how many hours?","options": [{"key": "A","text": "12 hours"},{"key": "B","text": "1 hour"},{"key": "C","text": "6 hours"},{"key": "D","text": "24 hours"}],"correct": "B","explanation": "BAO is measured as acid output collected over 1 hour under basal fasting conditions."},{"id": 2216,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Zollinger-Ellison syndrome is caused by tumor secreting excess:","options": [{"key": "A","text": "Gastrin"},{"key": "B","text": "Cholecystokinin"},{"key": "C","text": "Somatostatin"},{"key": "D","text": "Secretin"}],"correct": "A","explanation": "Gastrin-secreting tumor (gastrinoma) causes excessive HCl secretion and peptic ulcers."},{"id": 2217,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "The 'alkaline tide' refers to:","options": [{"key": "A","text": "Alkaline saliva production"},{"key": "B","text": "Decrease in blood pH after meals"},{"key": "C","text": "Increase in blood alkalinity following gastric acid secretion"},{"key": "D","text": "Alkaline pancreatic juice release"}],"correct": "C","explanation": "During HCl secretion, HCO3- is released into blood causing transient venous alkalinity, the alkaline tide."},{"id": 2218,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Pancreatic juice is characteristically:","options": [{"key": "A","text": "Alkaline"},{"key": "B","text": "Neutral"},{"key": "C","text": "Highly hypotonic"},{"key": "D","text": "Acidic"}],"correct": "A","explanation": "Pancreatic juice is alkaline (pH 8.0) due to high bicarbonate content."},{"id": 2219,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Bicarbonate-rich pancreatic juice is secreted mainly by:","options": [{"key": "A","text": "Islet cells"},{"key": "B","text": "Ductal (centroacinar) cells"},{"key": "C","text": "Goblet cells"},{"key": "D","text": "Acinar cells"}],"correct": "B","explanation": "Ductal epithelial cells secrete bicarbonate-rich watery fluid."},{"id": 2220,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Pancreatic acinar cells secrete:","options": [{"key": "A","text": "Insulin and glucagon"},{"key": "B","text": "Mucus only"},{"key": "C","text": "Digestive enzymes"},{"key": "D","text": "Bicarbonate only"}],"correct": "C","explanation": "Acinar cells secrete digestive enzymes (amylase, lipase, proteases)."},{"id": 2221,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Which hormone stimulates bicarbonate-rich pancreatic secretion?","options": [{"key": "A","text": "Secretin"},{"key": "B","text": "Motilin"},{"key": "C","text": "Cholecystokinin"},{"key": "D","text": "Gastrin"}],"correct": "A","explanation": "Secretin, released by acid in duodenum, stimulates ductal cells to secrete bicarbonate."},{"id": 2222,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Which hormone stimulates enzyme-rich pancreatic secretion?","options": [{"key": "A","text": "Somatostatin"},{"key": "B","text": "Secretin"},{"key": "C","text": "Gastrin"},{"key": "D","text": "Cholecystokinin (CCK)"}],"correct": "D","explanation": "CCK, released by fatty acids/amino acids in duodenum, stimulates acinar enzyme secretion."},{"id": 2223,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Trypsinogen is activated to trypsin by:","options": [{"key": "A","text": "Enterokinase (enteropeptidase)"},{"key": "B","text": "Pepsin"},{"key": "C","text": "Bile salts"},{"key": "D","text": "HCl"}],"correct": "A","explanation": "Enterokinase secreted by duodenal mucosa converts trypsinogen to active trypsin."},{"id": 2224,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Once formed, trypsin can activate:","options": [{"key": "A","text": "Only lipase"},{"key": "B","text": "Only trypsinogen"},{"key": "C","text": "Only amylase"},{"key": "D","text": "Chymotrypsinogen, procarboxypeptidase and more trypsinogen"}],"correct": "D","explanation": "Trypsin autocatalytically activates other trypsinogen and other proenzymes."},{"id": 2225,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Pancreatic amylase digests:","options": [{"key": "A","text": "Nucleic acids"},{"key": "B","text": "Starch/carbohydrates"},{"key": "C","text": "Proteins"},{"key": "D","text": "Fats"}],"correct": "B","explanation": "Pancreatic amylase hydrolyzes starch to maltose and oligosaccharides."},{"id": 2226,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Pancreatic lipase requires which cofactor for optimal activity?","options": [{"key": "A","text": "Trypsin"},{"key": "B","text": "Enterokinase"},{"key": "C","text": "Colipase"},{"key": "D","text": "Secretin"}],"correct": "C","explanation": "Colipase helps pancreatic lipase bind to fat droplets, especially in presence of bile salts."},{"id": 2227,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Daily secretion of pancreatic juice is approximately:","options": [{"key": "A","text": "3000 ml"},{"key": "B","text": "100-200 ml"},{"key": "C","text": "1200-1500 ml"},{"key": "D","text": "500 ml"}],"correct": "C","explanation": "Normal pancreatic secretion is about 1200-1500 ml/day."},{"id": 2228,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Trypsin inhibitor present in pancreatic juice/acinar cells prevents:","options": [{"key": "A","text": "Starch digestion"},{"key": "B","text": "Fat digestion"},{"key": "C","text": "Autodigestion of pancreas"},{"key": "D","text": "Bicarbonate secretion"}],"correct": "C","explanation": "Trypsin inhibitor prevents premature activation of trypsinogen inside the pancreas, protecting it from autodigestion."},{"id": 2229,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cephalic phase of pancreatic secretion is mediated by:","options": [{"key": "A","text": "Vagal stimulation"},{"key": "B","text": "Gastrin only"},{"key": "C","text": "CCK only"},{"key": "D","text": "Secretin only"}],"correct": "A","explanation": "Vagal (parasympathetic) stimulation during cephalic phase causes enzyme-rich pancreatic secretion."},{"id": 2230,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which phase contributes the largest volume of pancreatic secretion?","options": [{"key": "A","text": "Intestinal phase"},{"key": "B","text": "Gastric phase"},{"key": "C","text": "Cephalic phase"},{"key": "D","text": "Basal phase"}],"correct": "A","explanation": "Intestinal phase, via secretin and CCK, accounts for about 70-80% of pancreatic secretion."},{"id": 2231,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Bicarbonate secretion from pancreas mainly neutralizes:","options": [{"key": "A","text": "Bile acids"},{"key": "B","text": "Salivary amylase"},{"key": "C","text": "Acidic chyme entering duodenum from stomach"},{"key": "D","text": "Pepsin activity"}],"correct": "C","explanation": "Pancreatic bicarbonate neutralizes acidic gastric chyme, protecting duodenal mucosa and optimizing enzyme activity."},{"id": 2232,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Acute pancreatitis is commonly associated with premature activation of:","options": [{"key": "A","text": "Bile salts"},{"key": "B","text": "Lipase in intestine"},{"key": "C","text": "Amylase"},{"key": "D","text": "Trypsinogen within the pancreas"}],"correct": "D","explanation": "Premature intrapancreatic activation of trypsinogen leads to autodigestion seen in acute pancreatitis."},{"id": 2233,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Bile is secreted by:","options": [{"key": "A","text": "Gallbladder"},{"key": "B","text": "Pancreas"},{"key": "C","text": "Hepatocytes (liver cells)"},{"key": "D","text": "Duodenal glands"}],"correct": "C","explanation": "Bile is continuously secreted by hepatocytes and stored/concentrated in gallbladder."},{"id": 2234,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Primary function of bile salts in digestion is:","options": [{"key": "A","text": "Protein digestion"},{"key": "B","text": "Neutralizing stomach acid"},{"key": "C","text": "Carbohydrate digestion"},{"key": "D","text": "Emulsification and absorption of fats"}],"correct": "D","explanation": "Bile salts emulsify fats and form micelles aiding fat digestion and absorption."},{"id": 2235,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Gallbladder concentrates bile mainly by absorbing:","options": [{"key": "A","text": "Cholesterol"},{"key": "B","text": "Water and electrolytes"},{"key": "C","text": "Bile salts"},{"key": "D","text": "Bilirubin"}],"correct": "B","explanation": "Gallbladder epithelium actively absorbs Na+ and water, concentrating bile up to 5-20 times."},{"id": 2236,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Contraction of gallbladder is primarily stimulated by:","options": [{"key": "A","text": "Secretin"},{"key": "B","text": "Gastrin"},{"key": "C","text": "Cholecystokinin (CCK)"},{"key": "D","text": "Motilin"}],"correct": "C","explanation": "CCK released from duodenum causes gallbladder contraction and sphincter of Oddi relaxation."},{"id": 2237,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Enterohepatic circulation refers to:","options": [{"key": "A","text": "Circulation of pancreatic enzymes"},{"key": "B","text": "Recycling of bile salts between intestine and liver"},{"key": "C","text": "Blood flow to liver from intestine"},{"key": "D","text": "Bile flow from liver to gallbladder"}],"correct": "B","explanation": "Bile salts are reabsorbed in terminal ileum and returned to liver via portal blood for reuse."},{"id": 2238,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Majority of bile salts are reabsorbed in which part of intestine?","options": [{"key": "A","text": "Colon"},{"key": "B","text": "Jejunum"},{"key": "C","text": "Duodenum"},{"key": "D","text": "Terminal ileum"}],"correct": "D","explanation": "Terminal ileum has specific active transporters for bile salt reabsorption."},{"id": 2239,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Bilirubin in bile is derived from breakdown of:","options": [{"key": "A","text": "Hemoglobin"},{"key": "B","text": "Bile salts"},{"key": "C","text": "Lecithin"},{"key": "D","text": "Cholesterol"}],"correct": "A","explanation": "Bilirubin is a breakdown product of heme from senescent red blood cells."},{"id": 2240,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Conjugation of bilirubin in liver occurs with:","options": [{"key": "A","text": "Phosphate"},{"key": "B","text": "Sulfate"},{"key": "C","text": "Glycine"},{"key": "D","text": "Glucuronic acid"}],"correct": "D","explanation": "Bilirubin is conjugated with glucuronic acid by glucuronyl transferase to become water-soluble."},{"id": 2241,"subject": "Physiology","topic": "GI Physiology","difficulty": "Hard","question": "Which enzyme deficiency causes unconjugated hyperbilirubinemia (e.g. Gilbert syndrome)?","options": [{"key": "A","text": "Lipase"},{"key": "B","text": "Trypsin"},{"key": "C","text": "Amylase"},{"key": "D","text": "UDP-glucuronyl transferase"}],"correct": "D","explanation": "Deficient/reduced glucuronyl transferase activity impairs bilirubin conjugation."},{"id": 2242,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Sphincter of Oddi relaxation allowing bile flow into duodenum is caused mainly by:","options": [{"key": "A","text": "Gastrin"},{"key": "B","text": "Cholecystokinin"},{"key": "C","text": "Secretin"},{"key": "D","text": "Somatostatin"}],"correct": "B","explanation": "CCK relaxes sphincter of Oddi along with gallbladder contraction to release bile."},{"id": 2243,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Bile helps activate which pancreatic enzyme along with colipase?","options": [{"key": "A","text": "Chymotrypsin"},{"key": "B","text": "Pancreatic lipase"},{"key": "C","text": "Trypsin"},{"key": "D","text": "Amylase"}],"correct": "B","explanation": "Bile salts assist colipase in anchoring and activating pancreatic lipase at the fat-water interface."},{"id": 2244,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Daily bile secretion by liver is approximately:","options": [{"key": "A","text": "600-1000 ml"},{"key": "B","text": "2000-2500 ml"},{"key": "C","text": "250-300 ml"},{"key": "D","text": "50-100 ml"}],"correct": "A","explanation": "Liver secretes approximately 600-1000 ml of bile per day."},{"id": 2245,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Obstruction of bile duct leads to which type of jaundice?","options": [{"key": "A","text": "Hepatocellular"},{"key": "B","text": "Hemolytic (prehepatic)"},{"key": "C","text": "Obstructive (posthepatic)"},{"key": "D","text": "Physiological jaundice of newborn"}],"correct": "C","explanation": "Blockage of bile flow after its formation causes obstructive/posthepatic jaundice."},{"id": 2246,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Bile pigments give characteristic color to:","options": [{"key": "A","text": "Saliva"},{"key": "B","text": "Gastric juice"},{"key": "C","text": "Urine only"},{"key": "D","text": "Stool (feces)"}],"correct": "D","explanation": "Stercobilin, derived from bile pigments, gives brown color to stool."},{"id": 2247,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Cholecystokinin was formerly also known as:","options": [{"key": "A","text": "Secretin II"},{"key": "B","text": "Enterogastrone"},{"key": "C","text": "Pancreozymin"},{"key": "D","text": "Motilin"}],"correct": "C","explanation": "CCK was earlier called pancreozymin due to its pancreatic enzyme-stimulating action."},{"id": 2248,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Swallowing (deglutition) center is located in:","options": [{"key": "A","text": "Cerebral cortex"},{"key": "B","text": "Cerebellum"},{"key": "C","text": "Medulla oblongata and lower pons"},{"key": "D","text": "Hypothalamus"}],"correct": "C","explanation": "Deglutition center lies in medulla and lower pons, coordinating swallowing reflex."},{"id": 2249,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Peristalsis in esophagus that occurs in response to a swallow is called:","options": [{"key": "A","text": "Tertiary peristalsis"},{"key": "B","text": "Retroperistalsis"},{"key": "C","text": "Secondary peristalsis"},{"key": "D","text": "Primary peristalsis"}],"correct": "D","explanation": "Primary peristaltic wave is initiated by swallowing and is a continuation of pharyngeal peristalsis."},{"id": 2250,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Secondary peristalsis in esophagus occurs due to:","options": [{"key": "A","text": "Local distension by retained food/reflux"},{"key": "B","text": "Vagal cephalic reflex"},{"key": "C","text": "Voluntary swallowing"},{"key": "D","text": "Gastric emptying"}],"correct": "A","explanation": "Secondary peristalsis is a local response to esophageal distension when food remains after primary wave."},{"id": 2251,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Lower esophageal sphincter (LES) pressure is normally:","options": [{"key": "A","text": "Lower than gastric pressure allowing reflux"},{"key": "B","text": "Zero at all times"},{"key": "C","text": "Equal to atmospheric pressure"},{"key": "D","text": "Higher than gastric pressure, preventing reflux"}],"correct": "D","explanation": "LES maintains higher tone than stomach to prevent gastroesophageal reflux."},{"id": 2252,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Migrating Motor Complex (MMC) occurs during:","options": [{"key": "A","text": "Fed state"},{"key": "B","text": "Only during sleep"},{"key": "C","text": "Only in stomach"},{"key": "D","text": "Fasting/interdigestive state"}],"correct": "D","explanation": "MMC is a cyclical motility pattern occurring during fasting to sweep residual contents through GI tract."},{"id": 2253,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Receptive relaxation of stomach is mediated by:","options": [{"key": "A","text": "Gastrin release"},{"key": "B","text": "Sympathetic stimulation"},{"key": "C","text": "Local myogenic reflex only"},{"key": "D","text": "Vagovagal reflex (vago-vagal)"}],"correct": "D","explanation": "Vagovagal reflex relaxes gastric fundus to accommodate food without much pressure rise."},{"id": 2254,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Gastric emptying is slowed mainly by presence of which nutrient in duodenum?","options": [{"key": "A","text": "Fiber only"},{"key": "B","text": "Water"},{"key": "C","text": "Carbohydrates"},{"key": "D","text": "Fat"}],"correct": "D","explanation": "Fat in duodenum triggers CCK/enterogastric reflex causing delayed gastric emptying."},{"id": 2255,"subject": "Physiology","topic": "GI Physiology","difficulty": "Hard","question": "Basic electrical rhythm (slow waves) of stomach originates from:","options": [{"key": "A","text": "Pyloric antrum"},{"key": "B","text": "Duodenal mucosa"},{"key": "C","text": "Myenteric plexus neurons directly"},{"key": "D","text": "Interstitial cells of Cajal in the greater curvature/corpus"}],"correct": "D","explanation": "Interstitial cells of Cajal act as pacemaker cells generating slow waves controlling GI motility."},{"id": 2256,"subject": "Physiology","topic": "GI Physiology","difficulty": "Hard","question": "Frequency of gastric slow waves is approximately:","options": [{"key": "A","text": "1 per minute"},{"key": "B","text": "12 per minute"},{"key": "C","text": "20 per minute"},{"key": "D","text": "3 per minute"}],"correct": "D","explanation": "Gastric basic electrical rhythm occurs at about 3 cycles per minute."},{"id": 2257,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Segmentation contractions in small intestine mainly serve to:","options": [{"key": "A","text": "Propel chyme rapidly forward"},{"key": "B","text": "Relax the ileocecal valve"},{"key": "C","text": "Empty stomach"},{"key": "D","text": "Mix chyme with digestive juices"}],"correct": "D","explanation": "Segmentation contractions mix intestinal contents rather than propelling them forward significantly."},{"id": 2258,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Gastrocolic reflex refers to:","options": [{"key": "A","text": "Reflex vomiting"},{"key": "B","text": "Relaxation of stomach on gastric filling"},{"key": "C","text": "Emptying of gallbladder after meal"},{"key": "D","text": "Increased colonic motility following gastric distension"}],"correct": "D","explanation": "Gastrocolic reflex increases mass movements in colon in response to stomach distension after eating."},{"id": 2259,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The ileocecal valve primarily functions to:","options": [{"key": "A","text": "Increase gastric emptying"},{"key": "B","text": "Secrete digestive enzymes"},{"key": "C","text": "Allow free bidirectional flow"},{"key": "D","text": "Prevent backflow of colonic contents into ileum"}],"correct": "D","explanation": "Ileocecal valve prevents reflux of bacteria-laden colonic contents into the small intestine."},{"id": 2260,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Mass movements in the colon typically occur how many times per day?","options": [{"key": "A","text": "Once a week"},{"key": "B","text": "1-3 times per day"},{"key": "C","text": "Continuously all day"},{"key": "D","text": "10-15 times per day"}],"correct": "B","explanation": "Mass movements are strong peristaltic waves in colon occurring about 1-3 times daily, often after meals."},{"id": 2261,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Defecation reflex is primarily coordinated by:","options": [{"key": "A","text": "Cerebral cortex only"},{"key": "B","text": "Sympathetic thoracic outflow"},{"key": "C","text": "Vagus nerve alone"},{"key": "D","text": "Sacral spinal cord (parasympathetic) reflex"}],"correct": "D","explanation": "Defecation reflex is a spinal reflex involving sacral parasympathetic outflow, reinforced by intrinsic myenteric reflex."},{"id": 2262,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Vomiting center is located in:","options": [{"key": "A","text": "Medulla oblongata"},{"key": "B","text": "Cerebellum"},{"key": "C","text": "Cerebral cortex"},{"key": "D","text": "Spinal cord"}],"correct": "A","explanation": "Vomiting center in medulla coordinates the complex reflex of emesis."},{"id": 2263,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Maximum absorption of nutrients occurs in which part of GIT?","options": [{"key": "A","text": "Stomach"},{"key": "B","text": "Duodenum and jejunum"},{"key": "C","text": "Ileum"},{"key": "D","text": "Colon"}],"correct": "B","explanation": "Duodenum and jejunum are the primary sites for most nutrient absorption due to large surface area."},{"id": 2264,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Vitamin B12 is absorbed in the:","options": [{"key": "A","text": "Colon"},{"key": "B","text": "Jejunum"},{"key": "C","text": "Duodenum"},{"key": "D","text": "Terminal ileum"}],"correct": "D","explanation": "Vitamin B12 bound to intrinsic factor is absorbed specifically in terminal ileum."},{"id": 2265,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Iron is absorbed mainly in which form and site?","options": [{"key": "A","text": "Fe2+ (ferrous) in duodenum and upper jejunum"},{"key": "B","text": "Fe2+ in colon"},{"key": "C","text": "Fe3+ in ileum"},{"key": "D","text": "Fe3+ in duodenum"}],"correct": "A","explanation": "Ferrous (Fe2+) iron is absorbed more efficiently, mainly in duodenum and upper jejunum."},{"id": 2266,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Structures that increase absorptive surface area of small intestine include:","options": [{"key": "A","text": "Plicae circulares, villi, and microvilli"},{"key": "B","text": "Rugae"},{"key": "C","text": "Villi and microvilli only"},{"key": "D","text": "Haustra"}],"correct": "A","explanation": "Plicae circulares, villi, and microvilli together increase small intestinal surface area up to ~600 fold."},{"id": 2267,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Glucose and galactose are absorbed from intestinal lumen by:","options": [{"key": "A","text": "Passive facilitated diffusion only"},{"key": "B","text": "SGLT1 (sodium-glucose cotransporter)"},{"key": "C","text": "GLUT5 transporter"},{"key": "D","text": "Simple diffusion"}],"correct": "B","explanation": "SGLT1 co-transports glucose/galactose with sodium via secondary active transport across apical membrane."},{"id": 2268,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Fructose is absorbed from intestinal lumen mainly by:","options": [{"key": "A","text": "SGLT1"},{"key": "B","text": "Active transport with sodium"},{"key": "C","text": "Simple diffusion only"},{"key": "D","text": "GLUT5 (facilitated diffusion)"}],"correct": "D","explanation": "Fructose absorption occurs via GLUT5 transporter through facilitated diffusion, independent of sodium."},{"id": 2269,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Amino acids are absorbed in intestine mainly via:","options": [{"key": "A","text": "Pinocytosis only"},{"key": "B","text": "Simple diffusion only"},{"key": "C","text": "Sodium-dependent active transport (co-transport)"},{"key": "D","text": "Passive osmosis"}],"correct": "C","explanation": "Amino acids are absorbed by multiple sodium-coupled secondary active transport systems."},{"id": 2270,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Long-chain fatty acids after absorption into enterocytes are re-esterified and packaged as:","options": [{"key": "A","text": "Free fatty acids in blood"},{"key": "B","text": "VLDL directly"},{"key": "C","text": "Micelles"},{"key": "D","text": "Chylomicrons"}],"correct": "D","explanation": "Inside enterocytes, fatty acids/monoglycerides are re-esterified to triglycerides and packaged into chylomicrons."},{"id": 2271,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Chylomicrons formed in enterocytes are absorbed into:","options": [{"key": "A","text": "Portal blood capillaries"},{"key": "B","text": "Hepatic artery"},{"key": "C","text": "Lacteals (lymphatics)"},{"key": "D","text": "Bile ducts"}],"correct": "C","explanation": "Chylomicrons are too large for blood capillaries and enter the lymphatic lacteals."},{"id": 2272,"subject": "Physiology","topic": "GI Physiology","difficulty": "Easy","question": "Calcium absorption in intestine is facilitated by:","options": [{"key": "A","text": "Vitamin B12"},{"key": "B","text": "Vitamin K"},{"key": "C","text": "Vitamin D (calcitriol)"},{"key": "D","text": "Vitamin C only"}],"correct": "C","explanation": "Active vitamin D (calcitriol) enhances calcium absorption via calbindin synthesis in enterocytes."},{"id": 2273,"subject": "Physiology","topic": "GI Physiology","difficulty": "Medium","question": "Water absorption in intestine occurs mainly by:","options": [{"key": "A","text": "Active transport"},{"key": "B","text": "Pinocytosis"},{"key": "C","text": "Osmosis, following absorption of solutes"},{"key": "D","text": "Facilitated diffusion"}],"correct": "C","explanation": "Water absorption is passive, following osmotic gradients created by solute (Na+, glucose) absorption."},{"id": 2274,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Short chain fatty acids produced by colonic bacterial fermentation are absorbed in:","options": [{"key": "A","text": "Colon"},{"key": "B","text": "Ileum"},{"key": "C","text": "Jejunum"},{"key": "D","text": "Duodenum"}],"correct": "A","explanation": "Colonic bacteria ferment undigested carbohydrates producing SCFAs absorbed by colonic mucosa."},{"id": 2275,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Pituitary gland is located in which bony fossa?","options": [{"key": "A","text": "Sella turcica"},{"key": "B","text": "Petrous temporal bone"},{"key": "C","text": "Foramen magnum"},{"key": "D","text": "Cribriform plate"}],"correct": "A","explanation": "Pituitary gland sits in the sella turcica of sphenoid bone."},{"id": 2276,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Anterior pituitary is also known as:","options": [{"key": "A","text": "Infundibulum"},{"key": "B","text": "Adenohypophysis"},{"key": "C","text": "Pars nervosa"},{"key": "D","text": "Neurohypophysis"}],"correct": "B","explanation": "Anterior pituitary is called adenohypophysis, developing from Rathke's pouch."},{"id": 2277,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Posterior pituitary is also called:","options": [{"key": "A","text": "Neurohypophysis"},{"key": "B","text": "Adenohypophysis"},{"key": "C","text": "Pars distalis"},{"key": "D","text": "Pars intermedia"}],"correct": "A","explanation": "Posterior pituitary (neurohypophysis) is neural tissue, an extension of hypothalamus."},{"id": 2278,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Anterior pituitary hormones are regulated by:","options": [{"key": "A","text": "Hypothalamic releasing/inhibiting hormones via hypophyseal portal system"},{"key": "B","text": "Blood supply from posterior pituitary"},{"key": "C","text": "Autonomous secretion only"},{"key": "D","text": "Direct neural connection from hypothalamus"}],"correct": "A","explanation": "Hypothalamic hormones reach anterior pituitary via hypophyseal portal blood vessels."},{"id": 2279,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Which hormones are stored/released (not synthesized) by posterior pituitary?","options": [{"key": "A","text": "ACTH and TSH"},{"key": "B","text": "Oxytocin and ADH (vasopressin)"},{"key": "C","text": "GH and Prolactin"},{"key": "D","text": "FSH and LH"}],"correct": "B","explanation": "Oxytocin and ADH are synthesized in hypothalamus and transported to posterior pituitary for release."},{"id": 2280,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "ADH (vasopressin) is synthesized in which hypothalamic nucleus mainly?","options": [{"key": "A","text": "Arcuate nucleus"},{"key": "B","text": "Suprachiasmatic nucleus"},{"key": "C","text": "Ventromedial nucleus"},{"key": "D","text": "Supraoptic nucleus"}],"correct": "D","explanation": "Supraoptic nucleus is the main site of ADH synthesis, with some contribution from paraventricular nucleus."},{"id": 2281,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Oxytocin is synthesized mainly in which hypothalamic nucleus?","options": [{"key": "A","text": "Preoptic nucleus"},{"key": "B","text": "Paraventricular nucleus"},{"key": "C","text": "Arcuate nucleus"},{"key": "D","text": "Supraoptic nucleus"}],"correct": "B","explanation": "Paraventricular nucleus is the primary site of oxytocin synthesis."},{"id": 2282,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Which anterior pituitary hormone is under predominant tonic inhibitory control (not stimulatory)?","options": [{"key": "A","text": "Growth hormone"},{"key": "B","text": "TSH"},{"key": "C","text": "Prolactin"},{"key": "D","text": "ACTH"}],"correct": "C","explanation": "Prolactin secretion is tonically inhibited by dopamine from hypothalamus."},{"id": 2283,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Hypothalamic hormone that inhibits prolactin secretion is:","options": [{"key": "A","text": "TRH"},{"key": "B","text": "Dopamine (PIF)"},{"key": "C","text": "GnRH"},{"key": "D","text": "CRH"}],"correct": "B","explanation": "Dopamine acts as prolactin-inhibiting factor (PIF) suppressing prolactin release."},{"id": 2284,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "TSH secretion from anterior pituitary is stimulated by:","options": [{"key": "A","text": "TRH from hypothalamus"},{"key": "B","text": "Dopamine"},{"key": "C","text": "Somatostatin"},{"key": "D","text": "CRH"}],"correct": "A","explanation": "Thyrotropin-releasing hormone (TRH) stimulates TSH synthesis and release."},{"id": 2285,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "ACTH secretion is stimulated by which hypothalamic hormone?","options": [{"key": "A","text": "TRH"},{"key": "B","text": "GHRH"},{"key": "C","text": "GnRH"},{"key": "D","text": "CRH (corticotropin-releasing hormone)"}],"correct": "D","explanation": "CRH from hypothalamus stimulates ACTH secretion from anterior pituitary."},{"id": 2286,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Diabetes insipidus results from deficiency of:","options": [{"key": "A","text": "Insulin"},{"key": "B","text": "Aldosterone"},{"key": "C","text": "ADH (vasopressin)"},{"key": "D","text": "Oxytocin"}],"correct": "C","explanation": "ADH deficiency (central) or renal insensitivity (nephrogenic) causes diabetes insipidus with excess dilute urine."},{"id": 2287,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Excess ADH secretion leads to a condition known as:","options": [{"key": "A","text": "SIADH (Syndrome of Inappropriate ADH secretion)"},{"key": "B","text": "Cushing syndrome"},{"key": "C","text": "Diabetes insipidus"},{"key": "D","text": "Diabetes mellitus"}],"correct": "A","explanation": "SIADH causes water retention and hyponatremia due to excess ADH."},{"id": 2288,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Oxytocin causes which physiological action?","options": [{"key": "A","text": "Increases water reabsorption in kidney"},{"key": "B","text": "Uterine contraction and milk ejection reflex"},{"key": "C","text": "Increases blood glucose"},{"key": "D","text": "Stimulates thyroid gland"}],"correct": "B","explanation": "Oxytocin causes uterine smooth muscle contraction during labor and milk ejection during lactation."},{"id": 2289,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "ADH acts on kidney mainly via which receptor to increase water reabsorption?","options": [{"key": "A","text": "Beta receptor"},{"key": "B","text": "Alpha receptor"},{"key": "C","text": "V2 receptor"},{"key": "D","text": "V1 receptor"}],"correct": "C","explanation": "V2 receptors on renal collecting duct mediate water reabsorption by inserting aquaporin-2 channels."},{"id": 2290,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Which anterior pituitary cell type secretes growth hormone?","options": [{"key": "A","text": "Gonadotrophs"},{"key": "B","text": "Corticotrophs"},{"key": "C","text": "Somatotrophs"},{"key": "D","text": "Lactotrophs"}],"correct": "C","explanation": "Somatotroph cells, the most abundant anterior pituitary cell type, secrete growth hormone."},{"id": 2291,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Prolactin secretion is increased by:","options": [{"key": "A","text": "Bromocriptine"},{"key": "B","text": "Suckling/breastfeeding stimulus"},{"key": "C","text": "Somatostatin"},{"key": "D","text": "Dopamine"}],"correct": "B","explanation": "Suckling reflex reduces hypothalamic dopamine, thereby increasing prolactin secretion for lactation."},{"id": 2292,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Pituitary gland receives blood supply from hypophyseal portal system primarily for:","options": [{"key": "A","text": "Neither lobe"},{"key": "B","text": "Posterior pituitary"},{"key": "C","text": "Anterior pituitary"},{"key": "D","text": "Both equally via same vessels"}],"correct": "C","explanation": "Anterior pituitary depends on hypophyseal portal system for hypothalamic hormone delivery; posterior pituitary has direct arterial supply."},{"id": 2293,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "A pituitary tumor causing bitemporal hemianopia compresses which structure?","options": [{"key": "A","text": "Cavernous sinus only"},{"key": "B","text": "Optic nerve only"},{"key": "C","text": "Oculomotor nerve"},{"key": "D","text": "Optic chiasma"}],"correct": "D","explanation": "Pituitary tumors expanding superiorly can compress the optic chiasma, causing bitemporal visual field loss."},{"id": 2294,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Which of the following is NOT an anterior pituitary hormone?","options": [{"key": "A","text": "TSH"},{"key": "B","text": "GH"},{"key": "C","text": "ACTH"},{"key": "D","text": "Oxytocin"}],"correct": "D","explanation": "Oxytocin is a posterior pituitary hormone; the others are anterior pituitary hormones."},{"id": 2295,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Thyroid hormones T3 and T4 are synthesized using which essential element?","options": [{"key": "A","text": "Iron"},{"key": "B","text": "Iodine"},{"key": "C","text": "Calcium"},{"key": "D","text": "Zinc"}],"correct": "B","explanation": "Iodine is essential for synthesis of thyroxine (T4) and triiodothyronine (T3)."},{"id": 2296,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Which cells of thyroid gland secrete thyroid hormones?","options": [{"key": "A","text": "Follicular epithelial cells"},{"key": "B","text": "Stromal cells"},{"key": "C","text": "Both equally"},{"key": "D","text": "Parafollicular (C) cells"}],"correct": "A","explanation": "Follicular epithelial cells synthesize and secrete T3/T4 using thyroglobulin."},{"id": 2297,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Calcitonin is secreted by which thyroid cells?","options": [{"key": "A","text": "Stromal cells"},{"key": "B","text": "Parafollicular (C) cells"},{"key": "C","text": "Colloid cells"},{"key": "D","text": "Follicular cells"}],"correct": "B","explanation": "Parafollicular or C cells secrete calcitonin, which lowers blood calcium."},{"id": 2298,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "The predominant hormone secreted by thyroid gland by amount is:","options": [{"key": "A","text": "T4 (thyroxine)"},{"key": "B","text": "T3"},{"key": "C","text": "TSH"},{"key": "D","text": "Calcitonin"}],"correct": "A","explanation": "Thyroid gland secretes mostly T4, with T3 mainly formed by peripheral conversion."},{"id": 2299,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Most active/potent thyroid hormone at tissue level is:","options": [{"key": "A","text": "Thyroglobulin"},{"key": "B","text": "T4"},{"key": "C","text": "T3"},{"key": "D","text": "Reverse T3"}],"correct": "C","explanation": "T3 is more potent and biologically active than T4, though T4 is secreted in larger amounts."},{"id": 2300,"subject": "Physiology","topic": "GI Physiology","difficulty": "Hard","question": "Peripheral conversion of T4 to T3 occurs by action of enzyme:","options": [{"key": "A","text": "Thyroglobulinase"},{"key": "B","text": "Iodinase"},{"key": "C","text": "5' deiodinase"},{"key": "D","text": "TPO (thyroid peroxidase)"}],"correct": "C","explanation": "5'-deiodinase enzyme converts T4 to the more active T3 in peripheral tissues."},{"id": 2301,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Iodide trapping into thyroid follicular cells occurs via:","options": [{"key": "A","text": "Facilitated diffusion by GLUT"},{"key": "B","text": "Passive osmosis"},{"key": "C","text": "Simple diffusion"},{"key": "D","text": "Sodium-iodide symporter (NIS)"}],"correct": "D","explanation": "Sodium-iodide symporter actively transports iodide into thyroid cells against gradient."},{"id": 2302,"subject": "Physiology","topic": "GI Physiology","difficulty": "Hard","question": "Thyroid peroxidase enzyme is responsible for:","options": [{"key": "A","text": "Thyroglobulin synthesis"},{"key": "B","text": "Oxidation of iodide and iodination of tyrosine residues"},{"key": "C","text": "TSH receptor binding"},{"key": "D","text": "Iodide trapping"}],"correct": "B","explanation": "TPO catalyzes oxidation of iodide and its organification onto tyrosine residues of thyroglobulin."},{"id": 2303,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Majority of circulating T4 is transported bound to:","options": [{"key": "A","text": "Free in plasma"},{"key": "B","text": "Albumin only"},{"key": "C","text": "Hemoglobin"},{"key": "D","text": "Thyroxine-binding globulin (TBG)"}],"correct": "D","explanation": "Most T4 (and T3) circulates bound to thyroxine-binding globulin."},{"id": 2304,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Thyroid hormone secretion is regulated by negative feedback mainly via:","options": [{"key": "A","text": "Autonomic nervous system alone"},{"key": "B","text": "Adrenal cortex"},{"key": "C","text": "Hypothalamic-pituitary-thyroid axis"},{"key": "D","text": "Renin-angiotensin system"}],"correct": "C","explanation": "TRH-TSH-thyroid hormone feedback loop regulates thyroid hormone levels."},{"id": 2305,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Basal metabolic rate is primarily increased by:","options": [{"key": "A","text": "Thyroid hormones"},{"key": "B","text": "Insulin"},{"key": "C","text": "Aldosterone"},{"key": "D","text": "Calcitonin"}],"correct": "A","explanation": "Thyroid hormones increase basal metabolic rate by increasing cellular oxygen consumption and Na-K ATPase activity."},{"id": 2306,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Hypothyroidism in adults commonly presents with:","options": [{"key": "A","text": "Heat intolerance"},{"key": "B","text": "Weight gain, cold intolerance and lethargy"},{"key": "C","text": "Exophthalmos"},{"key": "D","text": "Weight loss and tachycardia"}],"correct": "B","explanation": "Hypothyroidism causes decreased metabolism leading to weight gain, cold intolerance, and lethargy."},{"id": 2307,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Graves' disease is an example of:","options": [{"key": "A","text": "Autoimmune hyperthyroidism due to TSH receptor antibodies"},{"key": "B","text": "Iodine deficiency disorder"},{"key": "C","text": "Pituitary tumor"},{"key": "D","text": "Primary hypothyroidism"}],"correct": "A","explanation": "Graves' disease involves TSH-receptor stimulating antibodies causing hyperthyroidism."},{"id": 2308,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cretinism refers to:","options": [{"key": "A","text": "Thyroid cancer"},{"key": "B","text": "Congenital/childhood hypothyroidism causing impaired growth and mental development"},{"key": "C","text": "Adult hypothyroidism"},{"key": "D","text": "Hyperthyroidism in children"}],"correct": "B","explanation": "Cretinism is severe hypothyroidism from birth/infancy causing stunted growth and mental retardation."},{"id": 2309,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Exophthalmos (protruding eyeballs) is characteristically seen in:","options": [{"key": "A","text": "Hypothyroidism"},{"key": "B","text": "Hashimoto's thyroiditis"},{"key": "C","text": "Graves' disease (hyperthyroidism)"},{"key": "D","text": "Simple goiter"}],"correct": "C","explanation": "Exophthalmos results from retro-orbital tissue inflammation/deposition seen classically in Graves' disease."},{"id": 2310,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Simple/endemic goiter commonly results from:","options": [{"key": "A","text": "Excess TSH secretion by tumor"},{"key": "B","text": "Iodine deficiency"},{"key": "C","text": "Excess iodine intake"},{"key": "D","text": "Autoimmune destruction"}],"correct": "B","explanation": "Iodine deficiency reduces thyroid hormone synthesis, causing compensatory TSH rise and goiter formation."},{"id": 2311,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Calcitonin's primary action is to:","options": [{"key": "A","text": "Increase blood phosphate only"},{"key": "B","text": "Increase blood calcium"},{"key": "C","text": "Stimulate parathyroid hormone"},{"key": "D","text": "Decrease blood calcium by inhibiting osteoclast activity"}],"correct": "D","explanation": "Calcitonin lowers blood calcium by inhibiting bone resorption (osteoclast activity)."},{"id": 2312,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Thyroid hormones are essential for normal development of which system in fetus/infant?","options": [{"key": "A","text": "Central nervous system"},{"key": "B","text": "Skeletal system only"},{"key": "C","text": "Cardiovascular system only"},{"key": "D","text": "Renal system only"}],"correct": "A","explanation": "Adequate thyroid hormone is critical for normal brain/CNS development in fetal and neonatal life."},{"id": 2313,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "TSH acts on thyroid follicular cells via which second messenger system?","options": [{"key": "A","text": "cAMP"},{"key": "B","text": "Direct gene transcription without receptor"},{"key": "C","text": "Steroid receptor mechanism"},{"key": "D","text": "IP3/Calcium"}],"correct": "A","explanation": "TSH binds to G-protein coupled receptor activating adenylyl cyclase/cAMP pathway."},{"id": 2314,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Which test is most sensitive for evaluating thyroid function/dysfunction?","options": [{"key": "A","text": "Serum T3 only"},{"key": "B","text": "Radioactive iodine uptake only"},{"key": "C","text": "Serum T4 only"},{"key": "D","text": "Serum TSH"}],"correct": "D","explanation": "Serum TSH is the most sensitive indicator of thyroid function due to feedback amplification."},{"id": 2315,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Parathyroid glands are typically how many in number?","options": [{"key": "A","text": "Six"},{"key": "B","text": "One"},{"key": "C","text": "Four"},{"key": "D","text": "Two"}],"correct": "C","explanation": "Normally there are four parathyroid glands, located posterior to thyroid lobes."},{"id": 2316,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Parathyroid hormone (PTH) is secreted by which cells?","options": [{"key": "A","text": "Oxyphil cells"},{"key": "B","text": "Parafollicular cells"},{"key": "C","text": "Chief cells"},{"key": "D","text": "Follicular cells"}],"correct": "C","explanation": "Chief cells of parathyroid gland synthesize and secrete PTH."},{"id": 2317,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Primary stimulus for PTH secretion is:","options": [{"key": "A","text": "High blood calcium"},{"key": "B","text": "High blood phosphate"},{"key": "C","text": "Low blood calcium"},{"key": "D","text": "Low blood potassium"}],"correct": "C","explanation": "Decreased serum ionized calcium is the principal stimulus for PTH release."},{"id": 2318,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "PTH increases blood calcium by which action on bone?","options": [{"key": "A","text": "No effect on bone"},{"key": "B","text": "Stimulating osteoblasts only"},{"key": "C","text": "Stimulating osteoclastic bone resorption"},{"key": "D","text": "Inhibiting osteoclasts"}],"correct": "C","explanation": "PTH promotes osteoclastic activity, releasing calcium and phosphate from bone into blood."},{"id": 2319,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Medium","question": "PTH acts on kidney to:","options": [{"key": "A","text": "Increase calcium reabsorption and decrease phosphate reabsorption"},{"key": "B","text": "Increase both calcium and phosphate reabsorption"},{"key": "C","text": "Decrease calcium reabsorption and increase phosphate reabsorption"},{"key": "D","text": "Decrease both calcium and phosphate reabsorption"}],"correct": "A","explanation": "PTH enhances renal calcium reabsorption while promoting phosphate excretion (phosphaturic effect)."},{"id": 2320,"subject": "Physiology","topic": "GI Physiology","difficulty": "Hard","question": "PTH increases intestinal calcium absorption indirectly by stimulating:","options": [{"key": "A","text": "Active vitamin D (1,25-dihydroxycholecalciferol/calcitriol) synthesis in kidney"},{"key": "B","text": "Cortisol synthesis"},{"key": "C","text": "Thyroid hormone synthesis"},{"key": "D","text": "Calcitonin synthesis"}],"correct": "A","explanation": "PTH stimulates renal 1-alpha-hydroxylase, converting vitamin D to its active calcitriol form, enhancing gut calcium absorption."},{"id": 2321,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hypoparathyroidism leads to which electrolyte abnormality?","options": [{"key": "A","text": "Hypercalcemia"},{"key": "B","text": "Hypocalcemia and hyperphosphatemia"},{"key": "C","text": "Hypocalcemia and hypophosphatemia"},{"key": "D","text": "Hyperkalemia"}],"correct": "B","explanation": "PTH deficiency causes low blood calcium and elevated phosphate due to reduced bone resorption and renal phosphate retention."},{"id": 2322,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Chvostek's sign and Trousseau's sign are clinical features of:","options": [{"key": "A","text": "Hypercalcemia"},{"key": "B","text": "Hyponatremia"},{"key": "C","text": "Hypocalcemia/tetany"},{"key": "D","text": "Hyperkalemia"}],"correct": "C","explanation": "These signs indicate neuromuscular excitability due to hypocalcemia, seen in hypoparathyroidism."},{"id": 2323,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Primary hyperparathyroidism most commonly results from:","options": [{"key": "A","text": "Vitamin D toxicity"},{"key": "B","text": "Parathyroid adenoma"},{"key": "C","text": "Renal failure"},{"key": "D","text": "Thyroid carcinoma"}],"correct": "B","explanation": "A benign parathyroid adenoma is the most common cause of primary hyperparathyroidism, causing excess PTH."},{"id": 2324,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Secondary hyperparathyroidism commonly occurs in setting of:","options": [{"key": "A","text": "Vitamin D excess"},{"key": "B","text": "Chronic renal failure with hypocalcemia"},{"key": "C","text": "Excess calcitonin"},{"key": "D","text": "Hyperthyroidism"}],"correct": "B","explanation": "Chronic kidney disease causes hypocalcemia and hyperphosphatemia, stimulating compensatory parathyroid hyperplasia."},{"id": 2325,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "PTH secretion is inhibited by:","options": [{"key": "A","text": "Low serum phosphate"},{"key": "B","text": "High serum calcium"},{"key": "C","text": "Low serum calcium"},{"key": "D","text": "Vitamin D deficiency"}],"correct": "B","explanation": "High serum calcium suppresses PTH secretion via negative feedback on calcium-sensing receptors."},{"id": 2326,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Osteitis fibrosa cystica is a bone disorder associated with:","options": [{"key": "A","text": "Calcitonin excess"},{"key": "B","text": "Chronic excess PTH (hyperparathyroidism)"},{"key": "C","text": "Vitamin D toxicity"},{"key": "D","text": "Hypoparathyroidism"}],"correct": "B","explanation": "Chronic excessive PTH causes excessive bone resorption leading to osteitis fibrosa cystica."},{"id": 2327,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Tetany due to hypocalcemia is characterized by:","options": [{"key": "A","text": "Bradycardia only"},{"key": "B","text": "Loss of deep tendon reflexes"},{"key": "C","text": "Increased neuromuscular excitability and spasms"},{"key": "D","text": "Muscle weakness and flaccidity"}],"correct": "C","explanation": "Low calcium increases neuronal membrane excitability causing tetany with muscle spasms."},{"id": 2328,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Which hormone acts antagonistically to PTH in calcium regulation?","options": [{"key": "A","text": "Aldosterone"},{"key": "B","text": "Glucagon"},{"key": "C","text": "Calcitonin"},{"key": "D","text": "Cortisol"}],"correct": "C","explanation": "Calcitonin lowers blood calcium, opposing the calcium-raising action of PTH."},{"id": 2329,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Normal total serum calcium level is approximately:","options": [{"key": "A","text": "15-20 mg/dl"},{"key": "B","text": "8.5-10.5 mg/dl"},{"key": "C","text": "25-30 mg/dl"},{"key": "D","text": "2-4 mg/dl"}],"correct": "B","explanation": "Normal total serum calcium ranges approximately 8.5-10.5 mg/dl."},{"id": 2330,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Adrenal cortex is derived embryologically from:","options": [{"key": "A","text": "Neural crest"},{"key": "B","text": "Neuroectoderm"},{"key": "C","text": "Mesoderm"},{"key": "D","text": "Endoderm"}],"correct": "C","explanation": "Adrenal cortex arises from mesoderm, unlike medulla which is neural crest derived."},{"id": 2331,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Adrenal medulla is derived from:","options": [{"key": "A","text": "Notochord"},{"key": "B","text": "Endoderm"},{"key": "C","text": "Neural crest cells"},{"key": "D","text": "Mesoderm"}],"correct": "C","explanation": "Adrenal medulla develops from neural crest cells, functioning as a sympathetic ganglion equivalent."},{"id": 2332,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Outermost zone of adrenal cortex is:","options": [{"key": "A","text": "Zona glomerulosa"},{"key": "B","text": "Zona reticularis"},{"key": "C","text": "Zona fasciculata"},{"key": "D","text": "Medulla"}],"correct": "A","explanation": "Zona glomerulosa is the outermost layer secreting mineralocorticoids (aldosterone)."},{"id": 2333,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Zona fasciculata (middle layer) of adrenal cortex mainly secretes:","options": [{"key": "A","text": "Glucocorticoids (cortisol)"},{"key": "B","text": "Androgens only"},{"key": "C","text": "Aldosterone"},{"key": "D","text": "Catecholamines"}],"correct": "A","explanation": "Zona fasciculata is the thickest layer, primarily secreting cortisol under ACTH control."},{"id": 2334,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Zona reticularis (innermost cortical layer) mainly secretes:","options": [{"key": "A","text": "Epinephrine"},{"key": "B","text": "Aldosterone"},{"key": "C","text": "Cortisol"},{"key": "D","text": "Adrenal androgens (DHEA)"}],"correct": "D","explanation": "Zona reticularis secretes adrenal androgens like DHEA and small amounts of estrogens."},{"id": 2335,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Mnemonic for adrenal cortex zones (outer to inner) and their secretions is:","options": [{"key": "A","text": "GFR - Salt, Sugar, Sex"},{"key": "B","text": "RGF - Sex, Sugar, Salt"},{"key": "C","text": "GRF - Salt, Sex, Sugar"},{"key": "D","text": "FGR - Sugar, Salt, Sex"}],"correct": "A","explanation": "Glomerulosa-Fasciculata-Reticularis (GFR) corresponds to Salt (aldosterone)-Sugar (cortisol)-Sex (androgens)."},{"id": 2336,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Aldosterone secretion is primarily regulated by:","options": [{"key": "A","text": "Renin-angiotensin system and plasma potassium"},{"key": "B","text": "ACTH"},{"key": "C","text": "TSH"},{"key": "D","text": "Growth hormone"}],"correct": "A","explanation": "Aldosterone secretion is mainly controlled by the renin-angiotensin-aldosterone system and serum K+ levels."},{"id": 2337,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Cortisol secretion is primarily regulated by:","options": [{"key": "A","text": "Aldosterone levels"},{"key": "B","text": "Renin-angiotensin system"},{"key": "C","text": "ACTH from anterior pituitary"},{"key": "D","text": "Serum potassium"}],"correct": "C","explanation": "ACTH stimulates cortisol synthesis and release from zona fasciculata."},{"id": 2338,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cortisol secretion follows which pattern during the day?","options": [{"key": "A","text": "Highest at midnight"},{"key": "B","text": "Constant throughout day"},{"key": "C","text": "Random with no pattern"},{"key": "D","text": "Diurnal variation, highest in early morning"}],"correct": "D","explanation": "Cortisol shows diurnal rhythm, peaking in early morning hours (around 6-8 AM) and lowest at night."},{"id": 2339,"subject": "Physiology","topic": "Renal Physiology","difficulty": "Easy","question": "Major action of aldosterone on kidney is to:","options": [{"key": "A","text": "Increase potassium reabsorption"},{"key": "B","text": "Increase sodium reabsorption and potassium excretion in distal tubule/collecting duct"},{"key": "C","text": "Decrease sodium reabsorption"},{"key": "D","text": "Increase glucose reabsorption"}],"correct": "B","explanation": "Aldosterone acts on principal cells of distal nephron increasing Na+ reabsorption and K+/H+ secretion."},{"id": 2340,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cortisol's metabolic actions include:","options": [{"key": "A","text": "Gluconeogenesis and hyperglycemia"},{"key": "B","text": "Increased glucose uptake by cells"},{"key": "C","text": "Decreased protein breakdown"},{"key": "D","text": "Increased insulin sensitivity"}],"correct": "A","explanation": "Cortisol promotes gluconeogenesis, protein catabolism, and lipolysis, raising blood glucose (anti-insulin action)."},{"id": 2341,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Cortisol has which effect on immune system?","options": [{"key": "A","text": "Stimulates inflammation"},{"key": "B","text": "Increases WBC production only"},{"key": "C","text": "No effect on immunity"},{"key": "D","text": "Anti-inflammatory and immunosuppressive"}],"correct": "D","explanation": "Cortisol suppresses inflammatory and immune responses, used therapeutically as anti-inflammatory."},{"id": 2342,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Addison's disease results from:","options": [{"key": "A","text": "Pheochromocytoma"},{"key": "B","text": "Excess aldosterone secretion"},{"key": "C","text": "Primary adrenal insufficiency (deficient cortisol and aldosterone)"},{"key": "D","text": "Excess cortisol secretion"}],"correct": "C","explanation": "Addison's disease is primary adrenocortical insufficiency causing deficient cortisol and aldosterone."},{"id": 2343,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cushing's syndrome results from:","options": [{"key": "A","text": "Excess insulin"},{"key": "B","text": "Deficient aldosterone"},{"key": "C","text": "Excess cortisol secretion"},{"key": "D","text": "Deficient cortisol"}],"correct": "C","explanation": "Cushing's syndrome is due to chronic excess cortisol, from tumor, exogenous steroids, or ACTH excess."},{"id": 2344,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Characteristic clinical features of Cushing's syndrome include:","options": [{"key": "A","text": "Hypoglycemia"},{"key": "B","text": "Hyperpigmentation and weight loss"},{"key": "C","text": "Weight loss and hypotension"},{"key": "D","text": "Central obesity, moon face, buffalo hump, hypertension"}],"correct": "D","explanation": "Cushing's syndrome features include truncal obesity, moon facies, buffalo hump, hypertension and hyperglycemia."},{"id": 2345,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hyperpigmentation of skin is a characteristic feature of:","options": [{"key": "A","text": "Pheochromocytoma"},{"key": "B","text": "Conn's syndrome"},{"key": "C","text": "Addison's disease (primary adrenal insufficiency)"},{"key": "D","text": "Cushing's syndrome"}],"correct": "C","explanation": "In Addison's disease, elevated ACTH (and MSH-like activity) causes skin hyperpigmentation."},{"id": 2346,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Conn's syndrome is caused by:","options": [{"key": "A","text": "Adrenal adenoma secreting excess aldosterone (primary hyperaldosteronism)"},{"key": "B","text": "Pituitary tumor"},{"key": "C","text": "Adrenal adenoma secreting excess cortisol"},{"key": "D","text": "Deficiency of aldosterone"}],"correct": "A","explanation": "Conn's syndrome is primary hyperaldosteronism, usually due to an aldosterone-secreting adrenal adenoma."},{"id": 2347,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Conn's syndrome typically presents with:","options": [{"key": "A","text": "Hypertension, hypokalemia, and metabolic alkalosis"},{"key": "B","text": "Hyperglycemia and weight loss"},{"key": "C","text": "Hypotension and hyperkalemia"},{"key": "D","text": "Hyperpigmentation"}],"correct": "A","explanation": "Excess aldosterone causes sodium/water retention (hypertension), potassium loss (hypokalemia), and alkalosis."},{"id": 2348,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Adrenal medulla secretes which hormones?","options": [{"key": "A","text": "Epinephrine and norepinephrine (catecholamines)"},{"key": "B","text": "Cortisol and aldosterone"},{"key": "C","text": "Calcitonin"},{"key": "D","text": "Androgens"}],"correct": "A","explanation": "Adrenal medulla, a modified sympathetic ganglion, secretes catecholamines - mainly epinephrine."},{"id": 2349,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Predominant catecholamine secreted by adrenal medulla is:","options": [{"key": "A","text": "Serotonin"},{"key": "B","text": "Epinephrine (adrenaline)"},{"key": "C","text": "Norepinephrine"},{"key": "D","text": "Dopamine"}],"correct": "B","explanation": "Adrenal medulla secretes mainly epinephrine (about 80%), with lesser norepinephrine."},{"id": 2350,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Adrenal medulla secretion is stimulated by:","options": [{"key": "A","text": "Sympathetic preganglionic fibers (via acetylcholine)"},{"key": "B","text": "Vagus nerve"},{"key": "C","text": "Parasympathetic preganglionic fibers"},{"key": "D","text": "Somatic motor neurons"}],"correct": "A","explanation": "Sympathetic preganglionic fibers directly innervate chromaffin cells, releasing acetylcholine to trigger catecholamine secretion."},{"id": 2351,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Pheochromocytoma is a tumor of:","options": [{"key": "A","text": "Chromaffin cells of adrenal medulla secreting catecholamines"},{"key": "B","text": "Adrenal cortex secreting cortisol"},{"key": "C","text": "Thyroid gland"},{"key": "D","text": "Parathyroid gland"}],"correct": "A","explanation": "Pheochromocytoma is a catecholamine-secreting tumor of adrenal medulla chromaffin cells, causing episodic hypertension."},{"id": 2352,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Epinephrine's actions include all EXCEPT:","options": [{"key": "A","text": "Bronchodilation"},{"key": "B","text": "Increased heart rate"},{"key": "C","text": "Decreased heart rate"},{"key": "D","text": "Increased blood glucose"}],"correct": "C","explanation": "Epinephrine increases heart rate (positive chronotropic effect) via beta-1 receptors, not decreases it."},{"id": 2353,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Adrenal androgens contribute mainly to which physiological process?","options": [{"key": "A","text": "Primary sexual development in males"},{"key": "B","text": "Pubic/axillary hair growth (adrenarche) and mild androgenic effects"},{"key": "C","text": "Spermatogenesis"},{"key": "D","text": "Ovulation"}],"correct": "B","explanation": "Adrenal androgens (DHEA) contribute to adrenarche - pubic and axillary hair growth, especially in females."},{"id": 2354,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "ACTH's action on adrenal cortex is mediated via which second messenger?","options": [{"key": "A","text": "cAMP"},{"key": "B","text": "Steroid receptor binding on cell surface"},{"key": "C","text": "Tyrosine kinase"},{"key": "D","text": "IP3/Calcium"}],"correct": "A","explanation": "ACTH binds melanocortin-2 receptor activating adenylyl cyclase/cAMP pathway to stimulate steroidogenesis."},{"id": 2355,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Insulin is secreted by which cells of pancreatic islets?","options": [{"key": "A","text": "Beta cells"},{"key": "B","text": "Delta cells"},{"key": "C","text": "Alpha cells"},{"key": "D","text": "PP cells"}],"correct": "A","explanation": "Beta cells, the most numerous islet cells, secrete insulin."},{"id": 2356,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Glucagon is secreted by which cells of pancreatic islets?","options": [{"key": "A","text": "Acinar cells"},{"key": "B","text": "Beta cells"},{"key": "C","text": "Delta cells"},{"key": "D","text": "Alpha cells"}],"correct": "D","explanation": "Alpha cells of pancreatic islets secrete glucagon."},{"id": 2357,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Somatostatin in pancreatic islets is secreted by:","options": [{"key": "A","text": "Alpha cells"},{"key": "B","text": "Delta cells"},{"key": "C","text": "Beta cells"},{"key": "D","text": "PP cells"}],"correct": "B","explanation": "Delta cells secrete somatostatin, which locally inhibits both insulin and glucagon secretion."},{"id": 2358,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Primary stimulus for insulin secretion is:","options": [{"key": "A","text": "Low blood glucose"},{"key": "B","text": "High blood ketones only"},{"key": "C","text": "High blood glucose"},{"key": "D","text": "Low blood amino acids"}],"correct": "C","explanation": "Rising blood glucose is the principal stimulus for insulin release from beta cells."},{"id": 2359,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Glucose enters beta cells mainly via which transporter to trigger insulin release?","options": [{"key": "A","text": "SGLT1"},{"key": "B","text": "GLUT4"},{"key": "C","text": "GLUT5"},{"key": "D","text": "GLUT2"}],"correct": "D","explanation": "GLUT2 transporter allows glucose entry into beta cells, initiating the insulin secretion cascade."},{"id": 2360,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Insulin release from beta cells occurs via which mechanism after glucose metabolism?","options": [{"key": "A","text": "Sodium channel closure"},{"key": "B","text": "Direct diffusion without receptors"},{"key": "C","text": "Increased ATP closing K-ATP channels causing depolarization and calcium influx"},{"key": "D","text": "Decreased ATP closing K+ channels"}],"correct": "C","explanation": "Glucose metabolism raises ATP, closing K-ATP channels, causing depolarization, calcium influx, and insulin exocytosis."},{"id": 2361,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Insulin's principal action on cells is to:","options": [{"key": "A","text": "Stimulate gluconeogenesis"},{"key": "B","text": "Facilitate cellular glucose uptake and decrease blood glucose"},{"key": "C","text": "Increase blood glucose"},{"key": "D","text": "Stimulate glycogenolysis"}],"correct": "B","explanation": "Insulin promotes glucose uptake (mainly via GLUT4) into muscle/fat and lowers blood glucose."},{"id": 2362,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Insulin promotes glucose uptake into skeletal muscle and adipose tissue via which transporter?","options": [{"key": "A","text": "GLUT1"},{"key": "B","text": "GLUT2"},{"key": "C","text": "GLUT4"},{"key": "D","text": "GLUT5"}],"correct": "C","explanation": "Insulin stimulates translocation of GLUT4 transporters to cell membrane in muscle and fat tissue."},{"id": 2363,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Insulin's effect on liver includes:","options": [{"key": "A","text": "Stimulating ketogenesis"},{"key": "B","text": "Stimulating glycogenolysis"},{"key": "C","text": "Stimulating protein breakdown"},{"key": "D","text": "Stimulating glycogen synthesis and inhibiting gluconeogenesis"}],"correct": "D","explanation": "Insulin promotes hepatic glycogen synthesis and suppresses gluconeogenesis, lowering blood glucose."},{"id": 2364,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Insulin has which effect on fat metabolism?","options": [{"key": "A","text": "Stimulates ketogenesis"},{"key": "B","text": "Promotes lipogenesis and inhibits lipolysis"},{"key": "C","text": "No effect on fat"},{"key": "D","text": "Stimulates lipolysis"}],"correct": "B","explanation": "Insulin favors fat storage (lipogenesis) and inhibits breakdown of fat (lipolysis)."},{"id": 2365,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Glucagon's principal action is to:","options": [{"key": "A","text": "Increase insulin secretion"},{"key": "B","text": "Raise blood glucose via glycogenolysis and gluconeogenesis"},{"key": "C","text": "Increase fat storage"},{"key": "D","text": "Lower blood glucose"}],"correct": "B","explanation": "Glucagon raises blood glucose by stimulating hepatic glycogen breakdown and gluconeogenesis."},{"id": 2366,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Glucagon secretion is stimulated by:","options": [{"key": "A","text": "High blood sodium"},{"key": "B","text": "High insulin levels"},{"key": "C","text": "High blood glucose"},{"key": "D","text": "Low blood glucose (hypoglycemia)"}],"correct": "D","explanation": "Falling blood glucose stimulates alpha cells to secrete glucagon, counter-regulating hypoglycemia."},{"id": 2367,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Glucagon acts on liver via which second messenger?","options": [{"key": "A","text": "IP3/Calcium"},{"key": "B","text": "Tyrosine kinase autophosphorylation"},{"key": "C","text": "cAMP"},{"key": "D","text": "Steroid mechanism"}],"correct": "C","explanation": "Glucagon binds G-protein coupled receptors activating adenylyl cyclase/cAMP pathway in hepatocytes."},{"id": 2368,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Insulin receptor mechanism of action involves:","options": [{"key": "A","text": "Steroid nuclear receptor"},{"key": "B","text": "Receptor tyrosine kinase activity"},{"key": "C","text": "G-protein coupled receptor/cAMP"},{"key": "D","text": "Ligand-gated ion channel"}],"correct": "B","explanation": "Insulin receptor is a tyrosine kinase receptor that autophosphorylates and activates downstream signaling (e.g., IRS proteins)."},{"id": 2369,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Type 1 diabetes mellitus is characterized by:","options": [{"key": "A","text": "Absolute insulin deficiency due to autoimmune beta cell destruction"},{"key": "B","text": "Excess insulin secretion"},{"key": "C","text": "Glucagon deficiency"},{"key": "D","text": "Insulin resistance with normal secretion"}],"correct": "A","explanation": "Type 1 DM results from autoimmune destruction of pancreatic beta cells causing absolute insulin deficiency."},{"id": 2370,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Type 2 diabetes mellitus is primarily characterized by:","options": [{"key": "A","text": "Autoimmune destruction of alpha cells"},{"key": "B","text": "Insulin resistance with relative insulin deficiency"},{"key": "C","text": "Absolute insulin deficiency"},{"key": "D","text": "Excess glucagon deficiency only"}],"correct": "B","explanation": "Type 2 DM involves peripheral insulin resistance along with progressive beta cell dysfunction."},{"id": 2371,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Which hormone is considered the only hormone that directly lowers blood glucose?","options": [{"key": "A","text": "Cortisol"},{"key": "B","text": "Glucagon"},{"key": "C","text": "Growth hormone"},{"key": "D","text": "Insulin"}],"correct": "D","explanation": "Insulin is the primary and only hormone whose main action directly lowers blood glucose levels."},{"id": 2372,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Hard","question": "Insulin secretion is also stimulated by which gut hormones (incretin effect)?","options": [{"key": "A","text": "Gastrin and motilin"},{"key": "B","text": "GLP-1 and GIP (incretins)"},{"key": "C","text": "Somatostatin"},{"key": "D","text": "Secretin and CCK"}],"correct": "B","explanation": "Incretin hormones GLP-1 and GIP, released from gut after meals, potentiate glucose-stimulated insulin secretion."},{"id": 2373,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Diabetic ketoacidosis occurs due to:","options": [{"key": "A","text": "Excess insulin causing hypoglycemia"},{"key": "B","text": "Excess glucagon suppression"},{"key": "C","text": "Severe insulin deficiency causing unchecked lipolysis and ketone body formation"},{"key": "D","text": "Excess glucose uptake by cells"}],"correct": "C","explanation": "Lack of insulin promotes uncontrolled lipolysis, generating excess ketone bodies leading to ketoacidosis, typical of Type 1 DM."},{"id": 2374,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal fasting blood glucose level is approximately:","options": [{"key": "A","text": "40-60 mg/dl"},{"key": "B","text": "250-300 mg/dl"},{"key": "C","text": "70-100 mg/dl"},{"key": "D","text": "150-200 mg/dl"}],"correct": "C","explanation": "Normal fasting plasma glucose is approximately 70-100 mg/dl (3.9-5.6 mmol/L)."},{"id": 2375,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Growth hormone (GH) is secreted by which anterior pituitary cells?","options": [{"key": "A","text": "Thyrotrophs"},{"key": "B","text": "Corticotrophs"},{"key": "C","text": "Lactotrophs"},{"key": "D","text": "Somatotrophs"}],"correct": "D","explanation": "Somatotrophs, the most abundant cell type in anterior pituitary, secrete growth hormone."},{"id": 2376,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "GH secretion is stimulated by which hypothalamic hormone?","options": [{"key": "A","text": "TRH"},{"key": "B","text": "GHRH (growth hormone-releasing hormone)"},{"key": "C","text": "Somatostatin"},{"key": "D","text": "Dopamine"}],"correct": "B","explanation": "GHRH from hypothalamus stimulates GH synthesis and secretion from somatotrophs."},{"id": 2377,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "GH secretion is inhibited by which hypothalamic hormone?","options": [{"key": "A","text": "GHRH"},{"key": "B","text": "CRH"},{"key": "C","text": "GnRH"},{"key": "D","text": "Somatostatin (GH-inhibiting hormone)"}],"correct": "D","explanation": "Somatostatin inhibits GH release, providing balance to GHRH stimulation."},{"id": 2378,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Most of GH's growth-promoting actions are mediated indirectly via:","options": [{"key": "A","text": "Aldosterone"},{"key": "B","text": "Insulin-like growth factor-1 (IGF-1) from liver"},{"key": "C","text": "Cortisol"},{"key": "D","text": "Thyroid hormone"}],"correct": "B","explanation": "GH stimulates hepatic IGF-1 production, which mediates most of GH's anabolic and growth-promoting effects."},{"id": 2379,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "GH secretion shows peak levels during:","options": [{"key": "A","text": "Fasting state only during day"},{"key": "B","text": "Daytime activity"},{"key": "C","text": "Deep sleep (slow wave sleep)"},{"key": "D","text": "Immediately after meals"}],"correct": "C","explanation": "GH secretion peaks during deep (slow wave) sleep, particularly in early hours of sleep."},{"id": 2380,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "GH's direct metabolic effects include:","options": [{"key": "A","text": "Increased lipolysis and increased blood glucose (anti-insulin effect)"},{"key": "B","text": "Increased glucose uptake by cells"},{"key": "C","text": "Decreased protein synthesis"},{"key": "D","text": "Decreased amino acid uptake"}],"correct": "A","explanation": "GH directly promotes lipolysis and has diabetogenic (anti-insulin) action raising blood glucose, alongside protein anabolism via IGF-1."},{"id": 2381,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Excess GH secretion in adults (after epiphyseal closure) causes:","options": [{"key": "A","text": "Cretinism"},{"key": "B","text": "Dwarfism"},{"key": "C","text": "Acromegaly"},{"key": "D","text": "Gigantism"}],"correct": "C","explanation": "In adults with fused epiphyses, GH excess causes acromegaly with bone thickening and organ enlargement."},{"id": 2382,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Excess GH secretion in children (before epiphyseal closure) causes:","options": [{"key": "A","text": "Acromegaly"},{"key": "B","text": "Myxedema"},{"key": "C","text": "Gigantism"},{"key": "D","text": "Dwarfism"}],"correct": "C","explanation": "In children, GH excess before epiphyseal plate closure causes excessive linear growth - gigantism."},{"id": 2383,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "GH deficiency in childhood leads to:","options": [{"key": "A","text": "Gigantism"},{"key": "B","text": "Pituitary dwarfism"},{"key": "C","text": "Acromegaly"},{"key": "D","text": "Precocious puberty"}],"correct": "B","explanation": "Deficient GH in childhood results in proportionate short stature known as pituitary dwarfism."},{"id": 2384,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "GH promotes longitudinal bone growth primarily by acting on:","options": [{"key": "A","text": "Epiphyseal growth plate (cartilage)"},{"key": "B","text": "Diaphysis of long bones"},{"key": "C","text": "Bone marrow only"},{"key": "D","text": "Periosteum only"}],"correct": "A","explanation": "GH (via IGF-1) stimulates chondrocyte proliferation at the epiphyseal growth plate, causing bone lengthening."},{"id": 2385,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Spinal cord in adults typically ends at which vertebral level?","options": [{"key": "A","text": "L4-L5"},{"key": "B","text": "T12 only"},{"key": "C","text": "L1-L2"},{"key": "D","text": "S2"}],"correct": "C","explanation": "Spinal cord (conus medullaris) usually terminates around L1-L2 vertebral level in adults."},{"id": 2386,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Dorsal (posterior) horn of spinal cord grey matter is mainly concerned with:","options": [{"key": "A","text": "Autonomic function only"},{"key": "B","text": "Motor function"},{"key": "C","text": "Reflex integration only"},{"key": "D","text": "Sensory function"}],"correct": "D","explanation": "Dorsal horn receives sensory afferent fibers and processes sensory information."},{"id": 2387,"subject": "Physiology","topic": "Cell Physiology","difficulty": "Easy","question": "Ventral (anterior) horn of spinal cord contains cell bodies of:","options": [{"key": "A","text": "Interneurons only"},{"key": "B","text": "Sensory neurons"},{"key": "C","text": "Lower motor neurons"},{"key": "D","text": "Autonomic preganglionic neurons only"}],"correct": "C","explanation": "Anterior horn cells are lower motor neurons innervating skeletal muscles."},{"id": 2388,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Lateral horn of spinal cord (present in thoracolumbar segments) contains:","options": [{"key": "A","text": "Sensory neurons"},{"key": "B","text": "Sympathetic preganglionic neurons"},{"key": "C","text": "Somatic motor neurons"},{"key": "D","text": "Parasympathetic neurons only"}],"correct": "B","explanation": "Lateral horn houses sympathetic preganglionic neuron cell bodies (T1-L2)."},{"id": 2389,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Corticospinal tract is primarily concerned with:","options": [{"key": "A","text": "Proprioception"},{"key": "B","text": "Voluntary motor control"},{"key": "C","text": "Pain and temperature sensation"},{"key": "D","text": "Sensory transmission"}],"correct": "B","explanation": "Corticospinal (pyramidal) tract carries voluntary motor commands from cortex to spinal cord."},{"id": 2390,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Dorsal column-medial lemniscus pathway carries which type of sensation?","options": [{"key": "A","text": "Pain and temperature"},{"key": "B","text": "Fine touch, vibration and proprioception"},{"key": "C","text": "Crude touch only"},{"key": "D","text": "Autonomic sensation"}],"correct": "B","explanation": "Dorsal columns carry discriminative touch, vibration sense, and proprioception."},{"id": 2391,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Lateral spinothalamic tract carries which sensation?","options": [{"key": "A","text": "Fine touch"},{"key": "B","text": "Pain and temperature"},{"key": "C","text": "Proprioception"},{"key": "D","text": "Vibration sense"}],"correct": "B","explanation": "Lateral spinothalamic tract transmits pain and temperature sensation to thalamus."},{"id": 2392,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Anterior spinothalamic tract carries which sensation?","options": [{"key": "A","text": "Crude/light touch and pressure"},{"key": "B","text": "Pain sensation"},{"key": "C","text": "Proprioception"},{"key": "D","text": "Fine touch"}],"correct": "A","explanation": "Anterior spinothalamic tract carries crude touch and pressure sensation."},{"id": 2393,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Decussation of dorsal column pathway (fibers crossing) occurs at level of:","options": [{"key": "A","text": "Thalamus"},{"key": "B","text": "Spinal cord segment of entry"},{"key": "C","text": "Midbrain"},{"key": "D","text": "Medulla oblongata (internal arcuate fibers)"}],"correct": "D","explanation": "Second order neurons of dorsal column pathway decussate in medulla as internal arcuate fibers."},{"id": 2394,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Spinothalamic tract fibers decussate at which level?","options": [{"key": "A","text": "Medulla"},{"key": "B","text": "Within 1-2 spinal segments of entry (in spinal cord)"},{"key": "C","text": "Thalamus"},{"key": "D","text": "Pons"}],"correct": "B","explanation": "Spinothalamic tract fibers cross within a few segments after entering spinal cord."},{"id": 2395,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Complete transection of spinal cord results in loss of all sensory and motor function below the lesion, a condition called:","options": [{"key": "A","text": "Tabes dorsalis"},{"key": "B","text": "Syringomyelia"},{"key": "C","text": "Brown-Sequard syndrome"},{"key": "D","text": "Complete spinal cord transection/paraplegia"}],"correct": "D","explanation": "Complete cord transection causes total loss of sensory-motor function below the level of injury."},{"id": 2396,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Brown-Sequard syndrome results from:","options": [{"key": "A","text": "Hemisection of the spinal cord"},{"key": "B","text": "Complete spinal cord transection"},{"key": "C","text": "Anterior cord syndrome only"},{"key": "D","text": "Central cord lesion only"}],"correct": "A","explanation": "Brown-Sequard syndrome is caused by hemisection of spinal cord, causing ipsilateral motor/proprioceptive loss and contralateral pain/temperature loss."},{"id": 2397,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "In Brown-Sequard syndrome, loss of pain and temperature sensation occurs:","options": [{"key": "A","text": "Not affected"},{"key": "B","text": "Ipsilateral to lesion"},{"key": "C","text": "Contralateral to lesion"},{"key": "D","text": "Bilaterally"}],"correct": "C","explanation": "Since spinothalamic tract already crossed before ascending, contralateral pain/temperature loss occurs below lesion."},{"id": 2398,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Spinal shock refers to:","options": [{"key": "A","text": "Permanent loss of spinal reflexes"},{"key": "B","text": "Excessive reflex activity immediately after injury"},{"key": "C","text": "Autonomic hyperreflexia"},{"key": "D","text": "Temporary loss of all reflex activity below level of acute spinal cord injury"}],"correct": "D","explanation": "Spinal shock is transient areflexia and flaccid paralysis following acute spinal cord injury, before reflexes gradually return."},{"id": 2399,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Autonomic dysreflexia is a complication seen in spinal cord injury at or above which level?","options": [{"key": "A","text": "Below L2"},{"key": "B","text": "At or above T6"},{"key": "C","text": "Only lumbar level"},{"key": "D","text": "Only cervical level"}],"correct": "B","explanation": "Autonomic dysreflexia typically occurs in injuries at or above T6 due to unchecked sympathetic reflex activity."},{"id": 2400,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Primary motor cortex is located in which lobe/gyrus?","options": [{"key": "A","text": "Precentral gyrus of frontal lobe"},{"key": "B","text": "Postcentral gyrus of parietal lobe"},{"key": "C","text": "Occipital lobe"},{"key": "D","text": "Superior temporal gyrus"}],"correct": "A","explanation": "Primary motor cortex (area 4) lies in precentral gyrus of frontal lobe."},{"id": 2401,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Primary somatosensory cortex is located in:","options": [{"key": "A","text": "Temporal lobe"},{"key": "B","text": "Occipital lobe"},{"key": "C","text": "Postcentral gyrus of parietal lobe"},{"key": "D","text": "Precentral gyrus"}],"correct": "C","explanation": "Primary somatosensory cortex (areas 3,1,2) is located in postcentral gyrus."},{"id": 2402,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Broca's area, responsible for speech production, is located in:","options": [{"key": "A","text": "Parietal lobe"},{"key": "B","text": "Occipital lobe"},{"key": "C","text": "Inferior frontal gyrus (frontal lobe)"},{"key": "D","text": "Temporal lobe"}],"correct": "C","explanation": "Broca's area lies in the inferior frontal gyrus, typically in the dominant (usually left) hemisphere."},{"id": 2403,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Wernicke's area, responsible for language comprehension, is located in:","options": [{"key": "A","text": "Frontal lobe"},{"key": "B","text": "Parietal lobe only"},{"key": "C","text": "Superior temporal gyrus (temporal lobe)"},{"key": "D","text": "Occipital lobe"}],"correct": "C","explanation": "Wernicke's area is located in the posterior superior temporal gyrus of the dominant hemisphere."},{"id": 2404,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Damage to Broca's area typically results in:","options": [{"key": "A","text": "Non-fluent (expressive) aphasia with intact comprehension"},{"key": "B","text": "Fluent but nonsensical speech"},{"key": "C","text": "Complete loss of comprehension"},{"key": "D","text": "Loss of vision"}],"correct": "A","explanation": "Broca's aphasia causes difficulty producing speech (non-fluent), while comprehension remains relatively intact."},{"id": 2405,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Damage to Wernicke's area typically results in:","options": [{"key": "A","text": "Fluent but nonsensical speech with impaired comprehension (receptive aphasia)"},{"key": "B","text": "Loss of hearing only"},{"key": "C","text": "Complete motor paralysis"},{"key": "D","text": "Non-fluent aphasia with intact comprehension"}],"correct": "A","explanation": "Wernicke's aphasia is fluent but meaningless speech with poor comprehension."},{"id": 2406,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Primary visual cortex is located in which lobe?","options": [{"key": "A","text": "Occipital lobe (around calcarine sulcus)"},{"key": "B","text": "Parietal lobe"},{"key": "C","text": "Temporal lobe"},{"key": "D","text": "Frontal lobe"}],"correct": "A","explanation": "Primary visual cortex (area 17) is located in occipital lobe around the calcarine fissure."},{"id": 2407,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Primary auditory cortex is located in:","options": [{"key": "A","text": "Parietal lobe"},{"key": "B","text": "Occipital lobe"},{"key": "C","text": "Frontal lobe"},{"key": "D","text": "Superior temporal gyrus (temporal lobe)"}],"correct": "D","explanation": "Primary auditory cortex (areas 41, 42) is located in the superior temporal gyrus."},{"id": 2408,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Corpus callosum functions to:","options": [{"key": "A","text": "Connect the two cerebral hemispheres"},{"key": "B","text": "Connect cerebrum to cerebellum"},{"key": "C","text": "Relay sensory information from spinal cord"},{"key": "D","text": "Connect thalamus to cortex"}],"correct": "A","explanation": "Corpus callosum is the major white matter tract connecting left and right cerebral hemispheres."},{"id": 2409,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Thalamus functions primarily as:","options": [{"key": "A","text": "Major relay and processing station for sensory information to cortex"},{"key": "B","text": "Hormone secretion center"},{"key": "C","text": "Motor output center"},{"key": "D","text": "Memory storage center"}],"correct": "A","explanation": "Thalamus relays and processes almost all sensory information (except olfaction) before reaching cortex."},{"id": 2410,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hypothalamus functions include all EXCEPT:","options": [{"key": "A","text": "Regulation of hunger and thirst"},{"key": "B","text": "Control of autonomic nervous system and endocrine functions"},{"key": "C","text": "Primary center for voluntary motor control"},{"key": "D","text": "Temperature regulation"}],"correct": "C","explanation": "Hypothalamus is involved in autonomic, endocrine, and homeostatic control, not primary voluntary motor control (that's motor cortex)."},{"id": 2411,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Limbic system is primarily associated with:","options": [{"key": "A","text": "Primary sensory processing"},{"key": "B","text": "Emotion, memory, and behavior"},{"key": "C","text": "Voluntary motor control"},{"key": "D","text": "Balance and coordination"}],"correct": "B","explanation": "Limbic system (hippocampus, amygdala, cingulate gyrus etc.) governs emotion, memory, and motivational behavior."},{"id": 2412,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hippocampus is primarily responsible for:","options": [{"key": "A","text": "Balance and coordination"},{"key": "B","text": "Primary vision processing"},{"key": "C","text": "Voluntary motor control"},{"key": "D","text": "Formation of new long-term memories"}],"correct": "D","explanation": "Hippocampus plays a crucial role in consolidation of new declarative/long-term memories."},{"id": 2413,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Which lobe of cerebrum, when damaged, commonly causes personality changes and impaired judgment?","options": [{"key": "A","text": "Parietal lobe"},{"key": "B","text": "Temporal lobe only"},{"key": "C","text": "Frontal lobe"},{"key": "D","text": "Occipital lobe"}],"correct": "C","explanation": "Frontal lobe, particularly prefrontal cortex, governs personality, judgment, and executive function."},{"id": 2414,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The dominant hemisphere for language in majority of right-handed individuals is:","options": [{"key": "A","text": "Left hemisphere"},{"key": "B","text": "Both equally dominant"},{"key": "C","text": "Neither hemisphere"},{"key": "D","text": "Right hemisphere"}],"correct": "A","explanation": "In most right-handed (and many left-handed) individuals, the left hemisphere is dominant for language."},{"id": 2415,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Primary function of cerebellum is:","options": [{"key": "A","text": "Sensory perception"},{"key": "B","text": "Higher cognitive function only"},{"key": "C","text": "Voluntary initiation of movement"},{"key": "D","text": "Coordination, balance, and fine-tuning of movement"}],"correct": "D","explanation": "Cerebellum coordinates and fine-tunes movement, maintaining balance and posture without initiating movement."},{"id": 2416,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Damage to cerebellum characteristically produces:","options": [{"key": "A","text": "Loss of sensation"},{"key": "B","text": "Ataxia (incoordination) and intention tremor"},{"key": "C","text": "Spastic paralysis"},{"key": "D","text": "Aphasia"}],"correct": "B","explanation": "Cerebellar lesions cause ataxia, dysmetria, intention tremor, and other coordination deficits."},{"id": 2417,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which part of cerebellum is primarily concerned with control of axial/trunk muscles and balance?","options": [{"key": "A","text": "Neocerebellum only"},{"key": "B","text": "Vestibulocerebellum (flocculonodular lobe)"},{"key": "C","text": "Spinocerebellum (vermis and intermediate zone)"},{"key": "D","text": "Cerebrocerebellum (lateral hemispheres)"}],"correct": "B","explanation": "Vestibulocerebellum (flocculonodular lobe) controls balance and eye movements via vestibular connections."},{"id": 2418,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Spinocerebellum is primarily involved in:","options": [{"key": "A","text": "Control of muscle tone and coordination of ongoing movement using proprioceptive feedback"},{"key": "B","text": "Cognitive processing"},{"key": "C","text": "Balance and equilibrium only"},{"key": "D","text": "Planning of movement"}],"correct": "A","explanation": "Spinocerebellum receives proprioceptive input and regulates muscle tone and movement execution."},{"id": 2419,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Cerebrocerebellum (lateral hemispheres) is mainly involved in:","options": [{"key": "A","text": "Planning and timing of complex voluntary movements"},{"key": "B","text": "Reflex control"},{"key": "C","text": "Muscle tone regulation only"},{"key": "D","text": "Balance"}],"correct": "A","explanation": "Cerebrocerebellum, connected to cerebral cortex via pons, is involved in motor planning and coordination of skilled movements."},{"id": 2420,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Dysdiadochokinesia refers to:","options": [{"key": "A","text": "Inability to perform rapid alternating movements"},{"key": "B","text": "Loss of pain sensation"},{"key": "C","text": "Tremor at rest"},{"key": "D","text": "Loss of vision"}],"correct": "A","explanation": "Dysdiadochokinesia is impaired ability to perform rapid alternating movements, a sign of cerebellar dysfunction."},{"id": 2421,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Intention tremor, characteristic of cerebellar disease, is:","options": [{"key": "A","text": "Present at rest and disappears with movement"},{"key": "B","text": "Absent at rest, appears/worsens during voluntary movement toward a target"},{"key": "C","text": "Only present during sleep"},{"key": "D","text": "Same as resting tremor of Parkinson's disease"}],"correct": "B","explanation": "Intention tremor worsens as the limb approaches its target during voluntary movement, typical of cerebellar lesions."},{"id": 2422,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cerebellum receives major input from which pathway carrying proprioceptive information?","options": [{"key": "A","text": "Spinothalamic tract"},{"key": "B","text": "Spinocerebellar tracts"},{"key": "C","text": "Corticospinal tract"},{"key": "D","text": "Rubrospinal tract"}],"correct": "B","explanation": "Spinocerebellar tracts carry unconscious proprioceptive information from muscles/joints to cerebellum."},{"id": 2423,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Nystagmus (involuntary rhythmic eye movements) can result from lesion of:","options": [{"key": "A","text": "Frontal lobe"},{"key": "B","text": "Vestibulocerebellum"},{"key": "C","text": "Parietal lobe"},{"key": "D","text": "Occipital lobe"}],"correct": "B","explanation": "Vestibulocerebellar lesions disrupt eye movement control causing nystagmus."},{"id": 2424,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Romberg's test primarily assesses:","options": [{"key": "A","text": "Muscle strength"},{"key": "B","text": "Proprioceptive/dorsal column function (patient sways more with eyes closed if positive)"},{"key": "C","text": "Cranial nerve function"},{"key": "D","text": "Cerebellar function only"}],"correct": "B","explanation": "A positive Romberg's sign indicates impaired proprioception (dorsal column) rather than pure cerebellar dysfunction, as patient relies on vision to compensate."},{"id": 2425,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Basal ganglia primarily function in:","options": [{"key": "A","text": "Sensory perception"},{"key": "B","text": "Hearing"},{"key": "C","text": "Regulation and control of voluntary movement, muscle tone and posture"},{"key": "D","text": "Memory formation"}],"correct": "C","explanation": "Basal ganglia regulate initiation, execution and smoothness of voluntary movement, along with muscle tone."},{"id": 2426,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Major components of basal ganglia include:","options": [{"key": "A","text": "Hippocampus and amygdala"},{"key": "B","text": "Caudate nucleus, putamen, globus pallidus"},{"key": "C","text": "Cerebellar vermis"},{"key": "D","text": "Thalamus and hypothalamus"}],"correct": "B","explanation": "Basal ganglia consist mainly of caudate nucleus, putamen (together = striatum), and globus pallidus, along with substantia nigra and subthalamic nucleus functionally."},{"id": 2427,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Caudate nucleus and putamen together are known as:","options": [{"key": "A","text": "Globus pallidus"},{"key": "B","text": "Substantia nigra"},{"key": "C","text": "Lentiform nucleus"},{"key": "D","text": "Striatum (neostriatum)"}],"correct": "D","explanation": "Caudate and putamen together form the striatum, the main input structure of basal ganglia."},{"id": 2428,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Putamen and globus pallidus together are known as:","options": [{"key": "A","text": "Amygdala"},{"key": "B","text": "Striatum"},{"key": "C","text": "Corpus striatum"},{"key": "D","text": "Lentiform nucleus"}],"correct": "D","explanation": "Putamen and globus pallidus together form the lentiform (lenticular) nucleus."},{"id": 2429,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Parkinson's disease results from degeneration of dopaminergic neurons in:","options": [{"key": "A","text": "Subthalamic nucleus"},{"key": "B","text": "Substantia nigra (pars compacta)"},{"key": "C","text": "Caudate nucleus"},{"key": "D","text": "Globus pallidus"}],"correct": "B","explanation": "Parkinson's disease is caused by loss of dopamine-producing neurons in substantia nigra pars compacta."},{"id": 2430,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Cardinal features of Parkinson's disease include:","options": [{"key": "A","text": "Intention tremor and ataxia"},{"key": "B","text": "Chorea and hemiballismus"},{"key": "C","text": "Hyperkinetic dance-like movements"},{"key": "D","text": "Resting tremor, rigidity, bradykinesia and postural instability"}],"correct": "D","explanation": "Parkinson's disease is characterized by resting tremor, rigidity, bradykinesia, and postural instability (TRAP)."},{"id": 2431,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Huntington's disease is characterized by degeneration of neurons in:","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Substantia nigra"},{"key": "C","text": "Hippocampus"},{"key": "D","text": "Caudate nucleus and putamen (striatum)"}],"correct": "D","explanation": "Huntington's disease involves progressive degeneration of striatal (caudate/putamen) neurons, causing chorea."},{"id": 2432,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Chorea (involuntary jerky dance-like movements) is characteristically seen in:","options": [{"key": "A","text": "Huntington's disease"},{"key": "B","text": "Multiple sclerosis"},{"key": "C","text": "Parkinson's disease"},{"key": "D","text": "Cerebellar ataxia"}],"correct": "A","explanation": "Huntington's disease classically presents with chorea due to striatal degeneration."},{"id": 2433,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Hemiballismus (violent flinging movements of one side of body) results from lesion of:","options": [{"key": "A","text": "Substantia nigra"},{"key": "B","text": "Cerebellum"},{"key": "C","text": "Frontal cortex"},{"key": "D","text": "Subthalamic nucleus"}],"correct": "D","explanation": "Hemiballismus results from lesion of contralateral subthalamic nucleus."},{"id": 2434,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Basal ganglia disorders are broadly classified into hypokinetic and hyperkinetic types; Parkinson's disease is an example of:","options": [{"key": "A","text": "Hypokinetic disorder"},{"key": "B","text": "Hyperkinetic disorder"},{"key": "C","text": "Both equally"},{"key": "D","text": "Neither"}],"correct": "A","explanation": "Parkinson's disease is a hypokinetic disorder characterized by reduced/slowed movement (bradykinesia)."},{"id": 2435,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A reflex arc's simplest form consists of minimum how many neurons (monosynaptic reflex)?","options": [{"key": "A","text": "Two neurons (afferent and efferent, e.g. knee jerk)"},{"key": "B","text": "Three neurons"},{"key": "C","text": "One neuron"},{"key": "D","text": "Four neurons"}],"correct": "A","explanation": "Monosynaptic reflex (e.g. stretch/knee jerk reflex) involves a single synapse between afferent sensory and efferent motor neuron."},{"id": 2436,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Knee jerk (patellar) reflex is an example of:","options": [{"key": "A","text": "Polysynaptic reflex"},{"key": "B","text": "Withdrawal reflex"},{"key": "C","text": "Monosynaptic stretch reflex"},{"key": "D","text": "Autonomic reflex"}],"correct": "C","explanation": "Knee jerk is a classic monosynaptic deep tendon (stretch) reflex, testing L2-L4 nerve roots."},{"id": 2437,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Ankle jerk reflex primarily tests which spinal nerve root level?","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "T10-T12"},{"key": "C","text": "S1-S2"},{"key": "D","text": "L2-L4"}],"correct": "C","explanation": "Ankle (Achilles) jerk reflex tests S1-S2 nerve root integrity."},{"id": 2438,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Biceps jerk reflex tests which spinal segment?","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "T1-T2"},{"key": "C","text": "L2-L4"},{"key": "D","text": "C7-C8"}],"correct": "A","explanation": "Biceps reflex primarily tests C5-C6 nerve roots."},{"id": 2439,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Withdrawal (flexor) reflex is an example of:","options": [{"key": "A","text": "Autonomic reflex only"},{"key": "B","text": "Conditioned reflex"},{"key": "C","text": "Polysynaptic reflex"},{"key": "D","text": "Monosynaptic reflex"}],"correct": "C","explanation": "Withdrawal reflex involves multiple interneurons (polysynaptic) to coordinate flexor muscle contraction upon painful stimulus."},{"id": 2440,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Golgi tendon organ primarily senses:","options": [{"key": "A","text": "Joint position"},{"key": "B","text": "Muscle length"},{"key": "C","text": "Pain"},{"key": "D","text": "Muscle tension/force"}],"correct": "D","explanation": "Golgi tendon organs detect changes in muscle tension, providing feedback to prevent excessive force/damage."},{"id": 2441,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Muscle spindle primarily detects:","options": [{"key": "A","text": "Changes in muscle length and rate of stretch"},{"key": "B","text": "Joint angle only"},{"key": "C","text": "Pain sensation"},{"key": "D","text": "Muscle tension"}],"correct": "A","explanation": "Muscle spindles are stretch receptors detecting changes in muscle length, essential for stretch reflex."},{"id": 2442,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Reciprocal inhibition during stretch reflex refers to:","options": [{"key": "A","text": "Simultaneous contraction of agonist and antagonist"},{"key": "B","text": "Inhibition of antagonist muscle while agonist contracts"},{"key": "C","text": "Inhibition of the agonist muscle"},{"key": "D","text": "No effect on antagonist"}],"correct": "B","explanation": "Reciprocal inhibition relaxes the antagonist muscle while the agonist contracts, enabling smooth movement."},{"id": 2443,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Babinski reflex (sign) in adults is considered:","options": [{"key": "A","text": "Sign of lower motor neuron lesion"},{"key": "B","text": "Abnormal, indicating upper motor neuron lesion"},{"key": "C","text": "Normal only in elderly"},{"key": "D","text": "Normal finding"}],"correct": "B","explanation": "Extensor plantar response (Babinski sign) in adults indicates upper motor neuron/corticospinal tract lesion; it's normal in infants."},{"id": 2444,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Deep tendon reflexes are typically diminished/absent in:","options": [{"key": "A","text": "Upper motor neuron lesions"},{"key": "B","text": "Basal ganglia lesions only"},{"key": "C","text": "Cerebellar lesions only"},{"key": "D","text": "Lower motor neuron lesions"}],"correct": "D","explanation": "Lower motor neuron lesions interrupt the reflex arc, causing hyporeflexia/areflexia."},{"id": 2445,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Deep tendon reflexes are typically exaggerated (hyperreflexia) in:","options": [{"key": "A","text": "Muscular dystrophy"},{"key": "B","text": "Peripheral neuropathy"},{"key": "C","text": "Lower motor neuron lesions"},{"key": "D","text": "Upper motor neuron lesions"}],"correct": "D","explanation": "Upper motor neuron lesions remove inhibitory cortical control, causing hyperreflexia and spasticity."},{"id": 2446,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Crossed extensor reflex occurs simultaneously with which reflex?","options": [{"key": "A","text": "Withdrawal/flexor reflex on opposite limb"},{"key": "B","text": "Pupillary reflex"},{"key": "C","text": "Golgi tendon reflex"},{"key": "D","text": "Stretch reflex"}],"correct": "A","explanation": "Crossed extensor reflex causes extension of the opposite limb to maintain balance while the stimulated limb withdraws."},{"id": 2447,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Corneal reflex tests the function of which cranial nerves?","options": [{"key": "A","text": "CN II and III"},{"key": "B","text": "CN III and IV"},{"key": "C","text": "CN IX and X"},{"key": "D","text": "CN V (afferent) and CN VII (efferent)"}],"correct": "D","explanation": "Corneal reflex has trigeminal nerve (V) as afferent and facial nerve (VII) as efferent limb."},{"id": 2448,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Pupillary light reflex has which cranial nerve as afferent limb?","options": [{"key": "A","text": "Trigeminal nerve (CN V)"},{"key": "B","text": "Optic nerve (CN II)"},{"key": "C","text": "Facial nerve (CN VII)"},{"key": "D","text": "Oculomotor nerve (CN III)"}],"correct": "B","explanation": "Optic nerve (CN II) carries the afferent light signal; oculomotor nerve (CN III) mediates the efferent pupillary constriction."},{"id": 2449,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Gag reflex tests the function of which cranial nerves?","options": [{"key": "A","text": "CN V and VII"},{"key": "B","text": "CN IX (afferent) and CN X (efferent)"},{"key": "C","text": "CN VII and VIII"},{"key": "D","text": "CN XI and XII"}],"correct": "B","explanation": "Gag reflex involves glossopharyngeal nerve (IX) as afferent and vagus nerve (X) as efferent."},{"id": 2450,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Light-sensitive photoreceptor cells of retina are:","options": [{"key": "A","text": "Pigment epithelial cells"},{"key": "B","text": "Horizontal and amacrine cells"},{"key": "C","text": "Bipolar and ganglion cells"},{"key": "D","text": "Rods and cones"}],"correct": "D","explanation": "Rods and cones are the primary photoreceptors converting light into electrical signals."},{"id": 2451,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Rods are primarily responsible for:","options": [{"key": "A","text": "Central/foveal vision"},{"key": "B","text": "High visual acuity in daylight"},{"key": "C","text": "Vision in dim light (scotopic vision), lacking color discrimination"},{"key": "D","text": "Color vision in bright light"}],"correct": "C","explanation": "Rods are highly sensitive photoreceptors for dim light vision but do not discriminate colors."},{"id": 2452,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Cones are primarily responsible for:","options": [{"key": "A","text": "Peripheral vision only"},{"key": "B","text": "Vision in dim light"},{"key": "C","text": "Dark adaptation"},{"key": "D","text": "Color vision and high visual acuity in bright light (photopic vision)"}],"correct": "D","explanation": "Cones function best in bright light and mediate color vision and fine visual acuity."},{"id": 2453,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Photopigment present in rods is:","options": [{"key": "A","text": "Melanopsin"},{"key": "B","text": "Rhodopsin"},{"key": "C","text": "Iodopsin"},{"key": "D","text": "Opsin only"}],"correct": "B","explanation": "Rhodopsin (visual purple) is the photopigment in rods, composed of opsin and retinal."},{"id": 2454,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Area of retina with highest visual acuity, containing only cones, is:","options": [{"key": "A","text": "Ora serrata"},{"key": "B","text": "Peripheral retina"},{"key": "C","text": "Optic disc"},{"key": "D","text": "Fovea centralis"}],"correct": "D","explanation": "Fovea centralis, the central pit of macula, contains only densely packed cones providing sharpest vision."},{"id": 2455,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Optic disc (blind spot) corresponds to:","options": [{"key": "A","text": "Area with maximum cones"},{"key": "B","text": "Area where optic nerve fibers exit, lacking photoreceptors"},{"key": "C","text": "Fovea"},{"key": "D","text": "Macula lutea"}],"correct": "B","explanation": "Optic disc is where retinal ganglion cell axons converge to form optic nerve; it lacks photoreceptors, creating a blind spot."},{"id": 2456,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Refraction of light entering the eye occurs maximally at:","options": [{"key": "A","text": "Cornea"},{"key": "B","text": "Lens"},{"key": "C","text": "Vitreous humor"},{"key": "D","text": "Aqueous humor"}],"correct": "A","explanation": "Cornea provides the majority (~2/3) of the eye's total refractive power due to its curvature and air-tear interface."},{"id": 2457,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Accommodation of lens for near vision involves:","options": [{"key": "A","text": "No change in lens shape"},{"key": "B","text": "Relaxation of ciliary muscle, lens flattens"},{"key": "C","text": "Constriction of pupil only, no lens change"},{"key": "D","text": "Contraction of ciliary muscle, lens becomes more convex/rounded"}],"correct": "D","explanation": "For near vision, ciliary muscle contracts, relaxing zonular fibers, allowing lens to become more spherical/convex."},{"id": 2458,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Myopia (nearsightedness) occurs due to:","options": [{"key": "A","text": "Eyeball too short or refractive power too weak"},{"key": "B","text": "Eyeball too long or refractive power too strong, image focuses in front of retina"},{"key": "C","text": "Loss of lens elasticity with age"},{"key": "D","text": "Corneal opacity"}],"correct": "B","explanation": "In myopia, light focuses in front of retina due to excessive axial length or refractive power; corrected with concave (diverging) lens."},{"id": 2459,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hypermetropia (farsightedness) occurs due to:","options": [{"key": "A","text": "Corneal scarring"},{"key": "B","text": "Eyeball too short or weak refractive power, image focuses behind retina"},{"key": "C","text": "Eyeball too long"},{"key": "D","text": "Excessive lens curvature"}],"correct": "B","explanation": "In hypermetropia, light focuses behind the retina; corrected using convex (converging) lens."},{"id": 2460,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Presbyopia is caused by:","options": [{"key": "A","text": "Increased vitreous pressure"},{"key": "B","text": "Corneal curvature changes"},{"key": "C","text": "Retinal degeneration"},{"key": "D","text": "Age-related loss of lens elasticity, reducing accommodation for near vision"}],"correct": "D","explanation": "Presbyopia results from age-related hardening/loss of elasticity of the lens, impairing near vision accommodation."},{"id": 2461,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Astigmatism results from:","options": [{"key": "A","text": "Irregular curvature of cornea (or lens) causing unequal refraction in different meridians"},{"key": "B","text": "Retinal detachment"},{"key": "C","text": "Optic nerve damage"},{"key": "D","text": "Cataract formation"}],"correct": "A","explanation": "Astigmatism is due to irregular corneal/lens curvature causing light to focus at multiple points rather than one."},{"id": 2462,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Aqueous humor is produced by:","options": [{"key": "A","text": "Retina"},{"key": "B","text": "Ciliary body (ciliary processes)"},{"key": "C","text": "Choroid"},{"key": "D","text": "Cornea"}],"correct": "B","explanation": "Ciliary processes of the ciliary body secrete aqueous humor, which nourishes cornea and lens."},{"id": 2463,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Increased intraocular pressure due to impaired aqueous humor drainage causes:","options": [{"key": "A","text": "Cataract"},{"key": "B","text": "Glaucoma"},{"key": "C","text": "Retinal detachment"},{"key": "D","text": "Macular degeneration"}],"correct": "B","explanation": "Glaucoma results from raised intraocular pressure, often due to obstructed aqueous humor outflow, damaging optic nerve."},{"id": 2464,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Dark adaptation of the eye is primarily related to regeneration of:","options": [{"key": "A","text": "Rhodopsin in rods"},{"key": "B","text": "Iodopsin in cones"},{"key": "C","text": "Melanin in retina"},{"key": "D","text": "Aqueous humor"}],"correct": "A","explanation": "Dark adaptation involves regeneration of rhodopsin in rods, increasing retinal sensitivity to low light."},{"id": 2465,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Visual pathway fibers from nasal retina of each eye:","options": [{"key": "A","text": "Do not reach the brain"},{"key": "B","text": "Remain uncrossed"},{"key": "C","text": "Terminate in ipsilateral thalamus without crossing"},{"key": "D","text": "Cross at optic chiasma to opposite side"}],"correct": "D","explanation": "Nasal retinal fibers decussate at the optic chiasma, carrying information from the temporal (opposite side) visual field."},{"id": 2466,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Lesion of one optic nerve (before chiasma) causes:","options": [{"key": "A","text": "Homonymous hemianopia"},{"key": "B","text": "No visual deficit"},{"key": "C","text": "Complete blindness in that eye"},{"key": "D","text": "Bitemporal hemianopia"}],"correct": "C","explanation": "Complete optic nerve transection causes total monocular blindness in the affected eye."},{"id": 2467,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Lesion at the optic chiasma (e.g., pituitary tumor) typically causes:","options": [{"key": "A","text": "Homonymous hemianopia"},{"key": "B","text": "Bitemporal hemianopia"},{"key": "C","text": "Central scotoma only"},{"key": "D","text": "Monocular blindness"}],"correct": "B","explanation": "Optic chiasma lesions damage crossing nasal fibers from both eyes, causing bitemporal (peripheral) visual field loss."},{"id": 2468,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Lesion of optic tract (after chiasma) typically causes:","options": [{"key": "A","text": "Homonymous hemianopia (same side field loss in both eyes)"},{"key": "B","text": "Bitemporal hemianopia"},{"key": "C","text": "Central scotoma"},{"key": "D","text": "Total blindness"}],"correct": "A","explanation": "Post-chiasmal lesions affect fibers from same-side visual field of both eyes, causing homonymous hemianopia."},{"id": 2469,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Organ of Corti, the receptor organ for hearing, is located in:","options": [{"key": "A","text": "Cochlea (in the inner ear)"},{"key": "B","text": "Middle ear ossicles"},{"key": "C","text": "Semicircular canals"},{"key": "D","text": "Vestibule"}],"correct": "A","explanation": "Organ of Corti, situated on the basilar membrane inside the cochlea, is the sensory receptor for hearing."},{"id": 2470,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Sound-sensitive hair cells of the organ of Corti are stimulated by movement of which membrane?","options": [{"key": "A","text": "Round window"},{"key": "B","text": "Oval window"},{"key": "C","text": "Reissner's membrane"},{"key": "D","text": "Basilar membrane relative to tectorial membrane"}],"correct": "D","explanation": "Vibration of the basilar membrane relative to the tectorial membrane bends stereocilia of hair cells, generating signals."},{"id": 2471,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Middle ear ossicles, in order from tympanic membrane to oval window, are:","options": [{"key": "A","text": "Incus, malleus, stapes"},{"key": "B","text": "Malleus, incus, stapes"},{"key": "C","text": "Malleus, stapes, incus"},{"key": "D","text": "Stapes, incus, malleus"}],"correct": "B","explanation": "Sound vibrations pass from malleus (attached to tympanic membrane) to incus to stapes (attached to oval window)."},{"id": 2472,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Function of middle ear ossicles is primarily to:","options": [{"key": "A","text": "Maintain balance"},{"key": "B","text": "Amplify and transmit sound vibrations from tympanic membrane to oval window, overcoming impedance mismatch"},{"key": "C","text": "Convert sound to nerve impulses"},{"key": "D","text": "Produce endolymph"}],"correct": "B","explanation": "Ossicles amplify sound pressure to efficiently transmit vibrations from air-filled middle ear to fluid-filled inner ear."},{"id": 2473,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "High-frequency sounds are detected maximally at which part of basilar membrane?","options": [{"key": "A","text": "Apex (near helicotrema)"},{"key": "B","text": "Uniformly throughout"},{"key": "C","text": "Middle portion only"},{"key": "D","text": "Base (near oval window)"}],"correct": "D","explanation": "High-frequency sounds cause maximum basilar membrane vibration near the base, close to the oval window."},{"id": 2474,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Low-frequency sounds are detected maximally at which part of basilar membrane?","options": [{"key": "A","text": "Uniformly throughout"},{"key": "B","text": "Apex (near helicotrema)"},{"key": "C","text": "Base"},{"key": "D","text": "Middle ear ossicles"}],"correct": "B","explanation": "Low-frequency sounds produce maximum vibration near the apex of the basilar membrane, which is wider and less stiff."},{"id": 2475,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Endolymph, the fluid inside the membranous labyrinth of the inner ear, has high concentration of:","options": [{"key": "A","text": "Sodium"},{"key": "B","text": "Potassium"},{"key": "C","text": "Calcium"},{"key": "D","text": "Chloride only"}],"correct": "B","explanation": "Endolymph is unique in having high potassium and low sodium concentration, similar to intracellular fluid."},{"id": 2476,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Conductive hearing loss typically results from a problem in:","options": [{"key": "A","text": "External or middle ear (e.g., wax, ossicle fixation)"},{"key": "B","text": "Cochlea or auditory nerve"},{"key": "C","text": "Auditory cortex"},{"key": "D","text": "Brainstem only"}],"correct": "A","explanation": "Conductive hearing loss arises from external/middle ear pathology impairing sound conduction to inner ear."},{"id": 2477,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Sensorineural hearing loss typically results from a problem in:","options": [{"key": "A","text": "Middle ear ossicles"},{"key": "B","text": "Cochlea or auditory (vestibulocochlear) nerve"},{"key": "C","text": "External ear canal"},{"key": "D","text": "Tympanic membrane perforation"}],"correct": "B","explanation": "Sensorineural hearing loss occurs due to defects in cochlea, hair cells, or the auditory nerve pathway."},{"id": 2478,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Rinne's test compares:","options": [{"key": "A","text": "Speech discrimination"},{"key": "B","text": "Weber's test result only"},{"key": "C","text": "Air conduction versus bone conduction in the same ear"},{"key": "D","text": "Bone conduction between two ears"}],"correct": "C","explanation": "Rinne's test compares air conduction to bone conduction hearing in the same ear (normally air > bone conduction)."},{"id": 2479,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In conductive hearing loss, Rinne's test result is typically:","options": [{"key": "A","text": "Equal in both ears always"},{"key": "B","text": "Positive (air conduction > bone conduction)"},{"key": "C","text": "Absent response"},{"key": "D","text": "Negative (bone conduction > air conduction)"}],"correct": "D","explanation": "Conductive hearing loss shows negative Rinne's test as bone conduction exceeds impaired air conduction."},{"id": 2480,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Weber's test in unilateral conductive hearing loss shows lateralization to:","options": [{"key": "A","text": "Both ears equally, always"},{"key": "B","text": "The affected (diseased) ear"},{"key": "C","text": "The unaffected/normal ear"},{"key": "D","text": "No lateralization"}],"correct": "B","explanation": "In conductive loss, Weber's test lateralizes to the affected ear due to reduced masking by ambient sound."},{"id": 2481,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Weber's test in unilateral sensorineural hearing loss shows lateralization to:","options": [{"key": "A","text": "The affected ear"},{"key": "B","text": "No lateralization"},{"key": "C","text": "The normal (unaffected) ear"},{"key": "D","text": "Both ears equally"}],"correct": "C","explanation": "In sensorineural hearing loss, sound lateralizes to the better/normal hearing ear."},{"id": 2482,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Vestibulocochlear nerve (CN VIII) carries which two functional components?","options": [{"key": "A","text": "Taste and smell"},{"key": "B","text": "Facial movement and hearing"},{"key": "C","text": "Vision and hearing"},{"key": "D","text": "Hearing (cochlear) and balance/equilibrium (vestibular)"}],"correct": "D","explanation": "CN VIII has cochlear division for hearing and vestibular division for balance and equilibrium."},{"id": 2483,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Primary auditory pathway relay includes which brainstem nucleus before reaching thalamus (medial geniculate body)?","options": [{"key": "A","text": "Red nucleus"},{"key": "B","text": "Vestibular nuclei only"},{"key": "C","text": "Substantia nigra"},{"key": "D","text": "Superior olivary nucleus/inferior colliculus"}],"correct": "D","explanation": "Auditory pathway relays through cochlear nuclei, superior olivary complex, and inferior colliculus before the medial geniculate body/thalamus."},{"id": 2484,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Taste receptor cells are located within structures called:","options": [{"key": "A","text": "Olfactory epithelium"},{"key": "B","text": "Taste buds"},{"key": "C","text": "Circumvallate ridges alone"},{"key": "D","text": "Papillae only, without buds"}],"correct": "B","explanation": "Taste buds, located mainly on tongue papillae, contain specialized taste receptor cells."},{"id": 2485,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The five basic taste qualities include sweet, sour, salty, bitter and:","options": [{"key": "A","text": "Metallic"},{"key": "B","text": "Astringent"},{"key": "C","text": "Spicy"},{"key": "D","text": "Umami (savory)"}],"correct": "D","explanation": "Umami, the taste of glutamate (savory taste), is the fifth basic taste quality alongside sweet, sour, salty, and bitter."},{"id": 2486,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Taste sensation from anterior two-thirds of tongue is carried by which cranial nerve?","options": [{"key": "A","text": "Trigeminal nerve (CN V)"},{"key": "B","text": "Vagus nerve (CN X)"},{"key": "C","text": "Glossopharyngeal nerve (CN IX)"},{"key": "D","text": "Facial nerve (CN VII) via chorda tympani"}],"correct": "D","explanation": "Chorda tympani branch of facial nerve (CN VII) carries taste sensation from anterior two-thirds of tongue."},{"id": 2487,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Taste sensation from posterior one-third of tongue is carried by:","options": [{"key": "A","text": "Trigeminal nerve"},{"key": "B","text": "Facial nerve"},{"key": "C","text": "Glossopharyngeal nerve (CN IX)"},{"key": "D","text": "Hypoglossal nerve"}],"correct": "C","explanation": "Glossopharyngeal nerve (CN IX) carries taste sensation from posterior third of the tongue."},{"id": 2488,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Taste transduction mechanism for sweet, bitter, and umami involves:","options": [{"key": "A","text": "Simple diffusion of tastant"},{"key": "B","text": "Ion channels only"},{"key": "C","text": "G-protein coupled receptors"},{"key": "D","text": "Direct depolarization without receptors"}],"correct": "C","explanation": "Sweet, bitter, and umami tastes are detected via G-protein coupled receptors (unlike salty/sour which use ion channels)."},{"id": 2489,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Olfactory receptor cells are located in:","options": [{"key": "A","text": "Olfactory epithelium in the roof of nasal cavity"},{"key": "B","text": "Nasal septum cartilage"},{"key": "C","text": "Sinuses only"},{"key": "D","text": "Nasal turbinate bone"}],"correct": "A","explanation": "Specialized olfactory epithelium in the superior nasal cavity contains olfactory receptor neurons."},{"id": 2490,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Olfactory receptor neurons are unique among sensory receptors because they are:","options": [{"key": "A","text": "Photoreceptor-like cells"},{"key": "B","text": "Modified epithelial cells only"},{"key": "C","text": "Non-neural sensory cells"},{"key": "D","text": "True bipolar neurons capable of regeneration"}],"correct": "D","explanation": "Olfactory receptor cells are true bipolar neurons, notable for their capacity to regenerate throughout life."},{"id": 2491,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Olfactory signals reach the brain via which cranial nerve?","options": [{"key": "A","text": "Facial nerve (CN VII)"},{"key": "B","text": "Olfactory nerve (CN I)"},{"key": "C","text": "Trigeminal nerve (CN V)"},{"key": "D","text": "Vagus nerve (CN X)"}],"correct": "B","explanation": "Olfactory nerve (CN I) carries smell signals from olfactory epithelium to olfactory bulb."},{"id": 2492,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Unlike other sensory pathways, olfactory pathway reaches cortex:","options": [{"key": "A","text": "Directly, without an obligatory thalamic relay before reaching primary olfactory cortex"},{"key": "B","text": "Only through the cerebellum"},{"key": "C","text": "Via obligatory thalamic relay first"},{"key": "D","text": "Through the spinal cord first"}],"correct": "A","explanation": "Olfaction is unique in that olfactory bulb projects directly to primary olfactory (piriform) cortex without first synapsing in thalamus."},{"id": 2493,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Anosmia refers to:","options": [{"key": "A","text": "Loss of hearing"},{"key": "B","text": "Loss or absence of sense of smell"},{"key": "C","text": "Loss of taste sensation"},{"key": "D","text": "Loss of vision"}],"correct": "B","explanation": "Anosmia is the complete loss of the sense of smell."},{"id": 2494,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which type of hair cells in the cochlea are primarily responsible for sound amplification (cochlear amplifier)?","options": [{"key": "A","text": "Inner hair cells"},{"key": "B","text": "Outer hair cells"},{"key": "C","text": "Vestibular hair cells"},{"key": "D","text": "Supporting cells"}],"correct": "B","explanation": "Outer hair cells actively amplify basilar membrane vibrations (cochlear amplifier), enhancing sensitivity and frequency selectivity, while inner hair cells are the main sensory transducers."},{"id": 2495,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Normal core body temperature is approximately:","options": [{"key": "A","text": "39.0°C"},{"key": "B","text": "33.0°C"},{"key": "C","text": "37.0°C (98.6°F)"},{"key": "D","text": "35.0°C"}],"correct": "C","explanation": "Normal core body temperature averages around 37.0°C (98.6°F), with diurnal variation."},{"id": 2496,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The main thermoregulatory center of the body is located in:","options": [{"key": "A","text": "Hypothalamus"},{"key": "B","text": "Medulla oblongata"},{"key": "C","text": "Cerebellum"},{"key": "D","text": "Basal ganglia"}],"correct": "A","explanation": "Hypothalamus, particularly preoptic/anterior region, acts as the body's thermostat."},{"id": 2497,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Heat-losing center of hypothalamus is located in:","options": [{"key": "A","text": "Mammillary bodies"},{"key": "B","text": "Anterior hypothalamus (preoptic area)"},{"key": "C","text": "Posterior hypothalamus"},{"key": "D","text": "Lateral hypothalamus"}],"correct": "B","explanation": "Anterior hypothalamic/preoptic area functions as the heat-loss center, activated by warming."},{"id": 2498,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Heat-promoting/conserving center of hypothalamus is located in:","options": [{"key": "A","text": "Anterior hypothalamus"},{"key": "B","text": "Supraoptic nucleus"},{"key": "C","text": "Posterior hypothalamus"},{"key": "D","text": "Arcuate nucleus"}],"correct": "C","explanation": "Posterior hypothalamus functions as the heat-conserving/heat-production center, activated by cold."},{"id": 2499,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Body temperature is normally lowest during:","options": [{"key": "A","text": "Midnight"},{"key": "B","text": "Midday"},{"key": "C","text": "Evening"},{"key": "D","text": "Early morning (around 4-6 AM)"}],"correct": "D","explanation": "Core body temperature follows a circadian rhythm, reaching its nadir in early morning hours."},{"id": 2500,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Primary mechanism of heat loss from body surface in a warm room (normal conditions) is:","options": [{"key": "A","text": "Sweating only"},{"key": "B","text": "Evaporation"},{"key": "C","text": "Radiation and conduction/convection"},{"key": "D","text": "Panting"}],"correct": "C","explanation": "At rest in moderate temperatures, radiation and conduction/convection account for most heat loss."},{"id": 2501,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "In high ambient temperature, the main mechanism of heat loss becomes:","options": [{"key": "A","text": "Evaporation (sweating)"},{"key": "B","text": "Conduction"},{"key": "C","text": "Radiation"},{"key": "D","text": "Convection only"}],"correct": "A","explanation": "When ambient temperature approaches/exceeds body temperature, evaporative heat loss (sweating) becomes dominant."},{"id": 2502,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Sweat glands are stimulated by which type of nerve fibers?","options": [{"key": "A","text": "Somatic motor fibers"},{"key": "B","text": "Sympathetic adrenergic fibers"},{"key": "C","text": "Parasympathetic fibers"},{"key": "D","text": "Sympathetic cholinergic fibers"}],"correct": "D","explanation": "Sweat glands are unique in being sympathetically innervated but using acetylcholine as neurotransmitter."},{"id": 2503,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Shivering thermogenesis is primarily controlled by which hypothalamic region and produces heat via:","options": [{"key": "A","text": "Lateral hypothalamus; vasodilation"},{"key": "B","text": "Preoptic area; sweating"},{"key": "C","text": "Posterior hypothalamus; involuntary rhythmic muscle contractions increasing heat production"},{"key": "D","text": "Anterior hypothalamus; muscle relaxation"}],"correct": "C","explanation": "Posterior hypothalamus initiates shivering, generating heat through involuntary skeletal muscle contractions."},{"id": 2504,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Non-shivering thermogenesis primarily occurs in:","options": [{"key": "A","text": "White adipose tissue"},{"key": "B","text": "Skeletal muscle"},{"key": "C","text": "Brown adipose tissue"},{"key": "D","text": "Liver only"}],"correct": "C","explanation": "Brown adipose tissue generates heat via uncoupling protein (thermogenin) without muscle contraction, especially important in infants."},{"id": 2505,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Cutaneous vasodilation in response to heat helps by:","options": [{"key": "A","text": "Reducing sweat gland activity"},{"key": "B","text": "Decreasing blood flow to skin, conserving heat"},{"key": "C","text": "Stimulating shivering"},{"key": "D","text": "Increasing blood flow to skin, promoting heat loss"}],"correct": "D","explanation": "Vasodilation increases skin blood flow, facilitating heat transfer to environment via radiation/convection."},{"id": 2506,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Fever is caused by resetting of hypothalamic thermostat mainly due to action of:","options": [{"key": "A","text": "Cold exposure"},{"key": "B","text": "Decreased metabolic rate"},{"key": "C","text": "Pyrogens (e.g., interleukin-1 and other cytokines)"},{"key": "D","text": "Increased physical activity"}],"correct": "C","explanation": "Pyrogens released during infection/inflammation reset the hypothalamic set point higher, causing fever."},{"id": 2507,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Heat stroke is a life-threatening condition characterized by:","options": [{"key": "A","text": "Failure of thermoregulation with very high body temperature and often absent sweating"},{"key": "B","text": "Hypothermia"},{"key": "C","text": "Normal sweating with mild fever"},{"key": "D","text": "Excessive shivering"}],"correct": "A","explanation": "Heat stroke involves thermoregulatory failure, hyperthermia (often >40°C), and CNS dysfunction, often with cessation of sweating."},{"id": 2508,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Hypothermia is generally defined as core body temperature below:","options": [{"key": "A","text": "35°C"},{"key": "B","text": "37°C"},{"key": "C","text": "40°C"},{"key": "D","text": "38°C"}],"correct": "A","explanation": "Hypothermia is typically defined as core temperature falling below 35°C (95°F)."},{"id": 2509,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "During exercise, the main compensatory mechanism to prevent excessive rise in body temperature is:","options": [{"key": "A","text": "Increased sweating and cutaneous vasodilation"},{"key": "B","text": "Vasoconstriction of skin vessels"},{"key": "C","text": "Decreased respiratory rate"},{"key": "D","text": "Shivering"}],"correct": "A","explanation": "Exercise-induced heat is dissipated mainly through increased sweating and skin vasodilation."},{"id": 2510,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Easy","question": "During moderate to heavy exercise, cardiac output increases primarily due to:","options": [{"key": "A","text": "Increased heart rate only, stroke volume unchanged"},{"key": "B","text": "Increased heart rate and stroke volume"},{"key": "C","text": "Decreased venous return"},{"key": "D","text": "Decreased heart rate and stroke volume"}],"correct": "B","explanation": "Exercise increases both heart rate and stroke volume, substantially raising cardiac output to meet metabolic demand."},{"id": 2511,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Maximum oxygen consumption (VO2 max) is considered the best index of:","options": [{"key": "A","text": "Muscular strength"},{"key": "B","text": "Flexibility"},{"key": "C","text": "Anaerobic capacity only"},{"key": "D","text": "Cardiorespiratory/aerobic fitness"}],"correct": "D","explanation": "VO2 max reflects the body's maximal capacity to take up, transport, and utilize oxygen, indicating aerobic fitness."},{"id": 2512,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "During exercise, blood flow is redistributed primarily to:","options": [{"key": "A","text": "Skeletal muscles, at the expense of splanchnic and renal circulation"},{"key": "B","text": "Bone marrow"},{"key": "C","text": "Skin and kidneys"},{"key": "D","text": "Gastrointestinal tract"}],"correct": "A","explanation": "Exercise causes vasodilation in active muscles and vasoconstriction in splanchnic/renal beds to prioritize muscle perfusion."},{"id": 2513,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Medium","question": "Oxygen debt (excess post-exercise oxygen consumption) is primarily related to:","options": [{"key": "A","text": "Decreased ventilation post-exercise"},{"key": "B","text": "Immediate return of heart rate to normal"},{"key": "C","text": "Replenishment of ATP-PC stores and removal of accumulated lactate after anaerobic exercise"},{"key": "D","text": "Excess CO2 production"}],"correct": "C","explanation": "Oxygen debt reflects the extra oxygen needed post-exercise to restore energy stores and metabolize lactate."},{"id": 2514,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Primary energy source for very short, high-intensity exercise (few seconds) is:","options": [{"key": "A","text": "Protein catabolism"},{"key": "B","text": "Aerobic oxidation of fats"},{"key": "C","text": "Glycolysis (anaerobic)"},{"key": "D","text": "ATP-phosphocreatine (ATP-PC) system"}],"correct": "D","explanation": "ATP-PC system provides immediate energy for very brief, maximal efforts lasting only a few seconds."},{"id": 2515,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Primary energy source for moderate-intensity exercise lasting several minutes is predominantly:","options": [{"key": "A","text": "Anaerobic glycolysis only"},{"key": "B","text": "Aerobic metabolism (oxidative phosphorylation)"},{"key": "C","text": "Ketone body oxidation only"},{"key": "D","text": "ATP-PC system"}],"correct": "B","explanation": "Sustained moderate exercise relies mainly on aerobic oxidative metabolism of carbohydrates and fats."},{"id": 2516,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Lactic acid accumulation during intense exercise results from:","options": [{"key": "A","text": "Decreased glucose utilization"},{"key": "B","text": "Anaerobic glycolysis when oxygen demand exceeds supply"},{"key": "C","text": "Increased fat oxidation"},{"key": "D","text": "Excess oxygen supply"}],"correct": "B","explanation": "When oxygen delivery cannot meet demand, muscles rely on anaerobic glycolysis, producing lactic acid as byproduct."},{"id": 2517,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Regular aerobic training characteristically causes which cardiovascular adaptation?","options": [{"key": "A","text": "Decreased stroke volume"},{"key": "B","text": "Increased resting heart rate"},{"key": "C","text": "No change in cardiac parameters"},{"key": "D","text": "Decreased resting heart rate and increased stroke volume"}],"correct": "D","explanation": "Endurance training causes bradycardia at rest and increased stroke volume due to cardiac hypertrophy/efficiency."},{"id": 2518,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Muscle fiber type predominantly recruited during endurance/aerobic exercise is:","options": [{"key": "A","text": "Type IIb (fast glycolytic) fibers"},{"key": "B","text": "Cardiac muscle fibers"},{"key": "C","text": "Type IIa only"},{"key": "D","text": "Type I (slow oxidative) fibers"}],"correct": "D","explanation": "Type I slow-twitch oxidative fibers are fatigue-resistant and preferentially recruited for sustained aerobic activity."},{"id": 2519,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Muscle fiber type predominantly recruited during short burst, high-intensity activity is:","options": [{"key": "A","text": "Type IIb (fast glycolytic) fibers"},{"key": "B","text": "Smooth muscle fibers"},{"key": "C","text": "Cardiac fibers"},{"key": "D","text": "Type I (slow oxidative) fibers"}],"correct": "A","explanation": "Fast glycolytic (Type IIb) fibers generate rapid, powerful contractions but fatigue quickly, ideal for sprinting/power activities."},{"id": 2520,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "During exercise, ventilation increases primarily to:","options": [{"key": "A","text": "Decrease heart rate"},{"key": "B","text": "Increase blood pH excessively"},{"key": "C","text": "Decrease oxygen delivery"},{"key": "D","text": "Meet increased oxygen demand and eliminate excess CO2"}],"correct": "D","explanation": "Increased ventilation during exercise matches rising metabolic demands for O2 and CO2 elimination."},{"id": 2521,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Second wind phenomenon during exercise refers to:","options": [{"key": "A","text": "Relief of initial breathlessness/discomfort as the body adapts to sustained exercise"},{"key": "B","text": "Cessation of exercise capacity"},{"key": "C","text": "Complete exhaustion"},{"key": "D","text": "Sudden fatigue onset"}],"correct": "A","explanation": "Second wind describes reduced perceived exertion/breathlessness after initial discomfort, as circulatory-respiratory adjustments stabilize."},{"id": 2522,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Training-induced increase in mitochondrial density and oxidative enzymes primarily improves:","options": [{"key": "A","text": "Muscle bulk exclusively"},{"key": "B","text": "Muscle's aerobic capacity to utilize oxygen and produce ATP efficiently"},{"key": "C","text": "Speed of muscle contraction only"},{"key": "D","text": "Anaerobic capacity only"}],"correct": "B","explanation": "Aerobic training increases mitochondrial density and oxidative enzyme activity, enhancing aerobic ATP production capacity."},{"id": 2523,"subject": "Physiology","topic": "Cardiovascular Physiology","difficulty": "Hard","question": "Cardiac output during maximal exercise in trained athletes can increase up to approximately:","options": [{"key": "A","text": "4-6 times resting value (or more)"},{"key": "B","text": "2 times resting value"},{"key": "C","text": "1.5 times resting value"},{"key": "D","text": "No significant increase"}],"correct": "A","explanation": "In trained individuals, cardiac output can increase severalfold (4-6x or higher) during maximal exercise."},{"id": 2524,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Anaerobic threshold refers to the exercise intensity at which:","options": [{"key": "A","text": "Ventilation decreases suddenly"},{"key": "B","text": "Heart rate stops increasing"},{"key": "C","text": "Blood lactate begins to accumulate disproportionately due to increased reliance on anaerobic metabolism"},{"key": "D","text": "Oxygen consumption plateaus completely"}],"correct": "C","explanation": "Anaerobic threshold marks the exercise intensity where lactate production exceeds clearance, indicating shift toward anaerobic metabolism."},{"id": 2525,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "The primary physiological problem at high altitude is due to:","options": [{"key": "A","text": "Increased temperature"},{"key": "B","text": "Increased oxygen concentration"},{"key": "C","text": "Increased barometric pressure"},{"key": "D","text": "Decreased barometric/partial pressure of oxygen (hypobaric hypoxia)"}],"correct": "D","explanation": "At high altitude, though oxygen percentage remains ~21%, the lower total barometric pressure reduces partial pressure of oxygen, causing hypoxia."},{"id": 2526,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Immediate physiological response to acute high-altitude hypoxia includes:","options": [{"key": "A","text": "Decreased ventilation"},{"key": "B","text": "Decreased cardiac output"},{"key": "C","text": "Hyperventilation (increased respiratory rate/depth)"},{"key": "D","text": "Bradycardia"}],"correct": "C","explanation": "Hypoxia stimulates peripheral chemoreceptors causing hyperventilation to increase oxygen intake."},{"id": 2527,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Chronic adaptation to high altitude includes increased production of:","options": [{"key": "A","text": "Erythropoietin and red blood cells (polycythemia)"},{"key": "B","text": "Platelets only"},{"key": "C","text": "Leukocytes"},{"key": "D","text": "Bile pigments"}],"correct": "A","explanation": "Chronic hypoxia stimulates renal erythropoietin release, increasing RBC production (polycythemia) to enhance oxygen-carrying capacity."},{"id": 2528,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Acute Mountain Sickness (AMS) commonly presents with:","options": [{"key": "A","text": "Fever and cough only"},{"key": "B","text": "Bradycardia and hypertension"},{"key": "C","text": "Increased appetite"},{"key": "D","text": "Headache, nausea, fatigue and dizziness"}],"correct": "D","explanation": "AMS typically presents with headache, nausea, fatigue, dizziness, and sleep disturbance upon rapid ascent to altitude."},{"id": 2529,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "High-Altitude Pulmonary Edema (HAPE) results from:","options": [{"key": "A","text": "Systemic vasodilation only"},{"key": "B","text": "Decreased pulmonary artery pressure"},{"key": "C","text": "Excess oxygen in alveoli"},{"key": "D","text": "Hypoxia-induced pulmonary vasoconstriction leading to increased pulmonary capillary pressure and fluid leakage"}],"correct": "D","explanation": "Hypoxic pulmonary vasoconstriction raises pulmonary vascular pressure unevenly, causing capillary leakage and pulmonary edema."},{"id": 2530,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "High-Altitude Cerebral Edema (HACE) is a severe complication resulting from:","options": [{"key": "A","text": "Excess cerebral blood flow with vascular leakage causing brain swelling due to hypoxia"},{"key": "B","text": "Excess CSF production only"},{"key": "C","text": "Dehydration alone"},{"key": "D","text": "Decreased intracranial pressure"}],"correct": "A","explanation": "HACE results from hypoxia-induced cerebral vasodilation and increased vascular permeability causing brain edema, a medical emergency."},{"id": 2531,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Hard","question": "A leftward shift of oxygen-hemoglobin dissociation curve at high altitude (initially) would:","options": [{"key": "A","text": "Decrease hemoglobin's affinity for oxygen"},{"key": "B","text": "Increase hemoglobin's affinity for oxygen, aiding oxygen loading in lungs despite low PO2"},{"key": "C","text": "Have no effect"},{"key": "D","text": "Only affect CO2 transport"}],"correct": "B","explanation": "Initial altitude-induced respiratory alkalosis shifts the curve left, increasing Hb-O2 affinity, useful for oxygen loading in lungs."},{"id": 2532,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Hard","question": "2,3-DPG levels increase during chronic altitude acclimatization, causing which shift in oxygen dissociation curve?","options": [{"key": "A","text": "Left shift"},{"key": "B","text": "Curve becomes flat"},{"key": "C","text": "Right shift, facilitating oxygen release to tissues"},{"key": "D","text": "No shift"}],"correct": "C","explanation": "Increased 2,3-DPG during acclimatization shifts curve right, promoting oxygen unloading at tissue level despite low PO2."},{"id": 2533,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Deep sea diving exposes the body to which major physiological stress?","options": [{"key": "A","text": "Increased temperature only"},{"key": "B","text": "Decreased barometric pressure"},{"key": "C","text": "Increased barometric/hydrostatic pressure"},{"key": "D","text": "Decreased oxygen availability only"}],"correct": "C","explanation": "Diving underwater increases hydrostatic pressure substantially with depth, affecting gas solubility and volumes."},{"id": 2534,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Decompression sickness ('the bends') occurs due to:","options": [{"key": "A","text": "Rapid ascent causing dissolved nitrogen to form bubbles in blood/tissues"},{"key": "B","text": "Hypothermia"},{"key": "C","text": "Excess carbon dioxide retention"},{"key": "D","text": "Oxygen toxicity"}],"correct": "A","explanation": "Rapid ascent from depth causes dissolved nitrogen (under high pressure) to come out of solution forming bubbles, causing decompression sickness."},{"id": 2535,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Nitrogen narcosis during deep diving is caused by:","options": [{"key": "A","text": "Low nitrogen partial pressure"},{"key": "B","text": "High partial pressure of nitrogen at depth causing anesthetic-like CNS effects"},{"key": "C","text": "Oxygen deficiency"},{"key": "D","text": "Carbon dioxide excess only"}],"correct": "B","explanation": "At great depths, elevated nitrogen partial pressure produces narcotic effects on CNS, impairing judgment (like alcohol intoxication)."},{"id": 2536,"subject": "Physiology","topic": "Respiratory Physiology","difficulty": "Hard","question": "Oxygen toxicity in deep sea diving can occur due to:","options": [{"key": "A","text": "Breathing oxygen at very high partial pressures for prolonged periods"},{"key": "B","text": "Low inspired oxygen pressure"},{"key": "C","text": "Low barometric pressure"},{"key": "D","text": "Nitrogen narcosis"}],"correct": "A","explanation": "At high partial pressures (as encountered in deep diving with compressed air), oxygen becomes toxic to CNS and lungs."},{"id": 2537,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "According to Boyle's law, as a diver ascends and pressure decreases, gas volume in body cavities (e.g., lungs) will:","options": [{"key": "A","text": "Remain constant"},{"key": "B","text": "Decrease"},{"key": "C","text": "Increase, risking barotrauma if breath is held"},{"key": "D","text": "Convert to liquid"}],"correct": "C","explanation": "Boyle's law states gas volume is inversely proportional to pressure; ascent (decreasing pressure) causes trapped gas to expand, risking lung rupture if breath-holding."},{"id": 2538,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Prevention of decompression sickness in divers primarily involves:","options": [{"key": "A","text": "Increasing depth further"},{"key": "B","text": "Rapid ascent to surface"},{"key": "C","text": "Slow, staged ascent allowing gradual nitrogen elimination"},{"key": "D","text": "Breathing pure nitrogen"}],"correct": "C","explanation": "Gradual staged ascent (decompression stops) allows dissolved nitrogen to be eliminated safely via lungs, preventing bubble formation."},{"id": 2539,"subject": "Physiology","topic": "General Physiology","difficulty": "Hard","question": "Which gas mixture is often used in deep diving to reduce risk of nitrogen narcosis?","options": [{"key": "A","text": "Pure oxygen"},{"key": "B","text": "Carbon dioxide-oxygen mixture"},{"key": "C","text": "Helium-oxygen mixture (heliox)"},{"key": "D","text": "Pure nitrogen"}],"correct": "C","explanation": "Helium, being less narcotic than nitrogen, is substituted in gas mixtures (heliox) for deep diving to reduce nitrogen narcosis risk."},{"id": 2540,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Sleep is broadly classified into which two major types?","options": [{"key": "A","text": "Active sleep and passive sleep"},{"key": "B","text": "REM (Rapid Eye Movement) and NREM (Non-REM) sleep"},{"key": "C","text": "Light sleep and deep sleep"},{"key": "D","text": "Alpha sleep and beta sleep"}],"correct": "B","explanation": "Sleep consists of REM sleep and NREM sleep (further divided into stages), alternating in cycles through the night."},{"id": 2541,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "NREM sleep is further divided into how many stages (per traditional classification)?","options": [{"key": "A","text": "Six stages"},{"key": "B","text": "Two stages"},{"key": "C","text": "Three to four stages (N1-N3, or historically stages 1-4)"},{"key": "D","text": "Five stages"}],"correct": "C","explanation": "NREM sleep is classically divided into stages N1, N2, and N3 (slow wave sleep), previously stages 1-4."},{"id": 2542,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "EEG pattern of deep NREM (slow wave) sleep is characterized by:","options": [{"key": "A","text": "High amplitude, low frequency delta waves"},{"key": "B","text": "Sawtooth waves"},{"key": "C","text": "Low amplitude, high frequency beta waves"},{"key": "D","text": "Alpha waves only"}],"correct": "A","explanation": "Slow wave sleep (N3) shows high-amplitude, low-frequency delta waves on EEG, indicating deep sleep."},{"id": 2543,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "REM sleep is characterized by which EEG pattern?","options": [{"key": "A","text": "Only sleep spindles"},{"key": "B","text": "High amplitude delta waves, similar to deep sleep"},{"key": "C","text": "Absence of any brain activity"},{"key": "D","text": "Low amplitude, fast, desynchronized waves resembling wakefulness"}],"correct": "D","explanation": "REM sleep EEG resembles wakefulness (low amplitude, high frequency, desynchronized activity), hence called 'paradoxical sleep'."},{"id": 2544,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Dreams most vividly occur during which stage of sleep?","options": [{"key": "A","text": "REM sleep"},{"key": "B","text": "NREM stage 1"},{"key": "C","text": "Wakeful relaxation, not sleep"},{"key": "D","text": "NREM stage 3 (slow wave sleep)"}],"correct": "A","explanation": "Vivid dreaming is most characteristic of REM sleep, though some dreaming can occur in NREM too."},{"id": 2545,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Skeletal muscle tone during REM sleep is characteristically:","options": [{"key": "A","text": "Markedly decreased (atonia), except for eye muscles and diaphragm"},{"key": "B","text": "Absent entirely including diaphragm"},{"key": "C","text": "Increased (hypertonia)"},{"key": "D","text": "Same as wakefulness"}],"correct": "A","explanation": "REM sleep is associated with profound skeletal muscle atonia to prevent acting out dreams, sparing extraocular muscles and diaphragm."},{"id": 2546,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Sleep spindles and K-complexes on EEG are characteristic of which sleep stage?","options": [{"key": "A","text": "REM sleep"},{"key": "B","text": "NREM stage 2"},{"key": "C","text": "NREM stage 3 (deep sleep)"},{"key": "D","text": "Wakefulness"}],"correct": "B","explanation": "Sleep spindles and K-complexes are hallmark EEG features of NREM stage 2 sleep."},{"id": 2547,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "A normal sleep cycle (from NREM through REM) in adults typically lasts approximately:","options": [{"key": "A","text": "90-100 minutes"},{"key": "B","text": "6 hours"},{"key": "C","text": "10-20 minutes"},{"key": "D","text": "3-4 hours"}],"correct": "A","explanation": "A complete sleep cycle through NREM and REM stages typically lasts about 90 minutes, repeating 4-5 times per night."},{"id": 2548,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Medium","question": "Growth hormone secretion is maximal during which sleep stage?","options": [{"key": "A","text": "Stage 1 NREM"},{"key": "B","text": "Deep NREM (slow wave) sleep, especially early in the night"},{"key": "C","text": "REM sleep"},{"key": "D","text": "Immediately upon waking"}],"correct": "B","explanation": "GH secretion peaks during deep slow wave sleep, particularly in the first few hours of sleep."},{"id": 2549,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "The suprachiasmatic nucleus of hypothalamus functions as the body's:","options": [{"key": "A","text": "Thermoregulatory center"},{"key": "B","text": "Master circadian clock/pacemaker regulating sleep-wake cycle"},{"key": "C","text": "Thirst center"},{"key": "D","text": "Hunger center"}],"correct": "B","explanation": "Suprachiasmatic nucleus (SCN) is the primary circadian pacemaker, synchronized by light input via retina."},{"id": 2550,"subject": "Physiology","topic": "Endocrine Physiology","difficulty": "Easy","question": "Melatonin, a hormone regulating sleep-wake cycle, is secreted by:","options": [{"key": "A","text": "Pineal gland"},{"key": "B","text": "Adrenal gland"},{"key": "C","text": "Thyroid gland"},{"key": "D","text": "Pituitary gland"}],"correct": "A","explanation": "Pineal gland secretes melatonin, particularly during darkness, promoting sleep onset."},{"id": 2551,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Melatonin secretion is characteristically:","options": [{"key": "A","text": "Constant throughout day and night"},{"key": "B","text": "Suppressed by darkness"},{"key": "C","text": "Suppressed by light and increased during darkness"},{"key": "D","text": "Increased by bright light only"}],"correct": "C","explanation": "Light suppresses melatonin secretion via retinohypothalamic pathway to SCN, while darkness promotes its release."},{"id": 2552,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Sleep deprivation commonly leads to which of the following effects?","options": [{"key": "A","text": "Increased immune function only"},{"key": "B","text": "Impaired concentration, memory and mood disturbances"},{"key": "C","text": "No significant physiological effect"},{"key": "D","text": "Improved cognitive performance"}],"correct": "B","explanation": "Chronic sleep deprivation impairs cognitive function, memory consolidation, mood, and overall physiological health."},{"id": 2553,"subject": "Physiology","topic": "General Physiology","difficulty": "Easy","question": "Insomnia is defined as:","options": [{"key": "A","text": "Excessive daytime sleepiness"},{"key": "B","text": "Sleepwalking disorder"},{"key": "C","text": "Sleep paralysis"},{"key": "D","text": "Difficulty initiating or maintaining sleep, or non-restorative sleep"}],"correct": "D","explanation": "Insomnia refers to persistent difficulty falling asleep, staying asleep, or achieving restorative sleep."},{"id": 2554,"subject": "Physiology","topic": "General Physiology","difficulty": "Medium","question": "Sleep apnea is characterized by:","options": [{"key": "A","text": "Absence of dreaming"},{"key": "B","text": "Repeated episodes of breathing cessation/reduction during sleep"},{"key": "C","text": "Excessive REM sleep"},{"key": "D","text": "Increased slow wave sleep"}],"correct": "B","explanation": "Sleep apnea involves repetitive pauses or reductions in airflow during sleep, commonly due to upper airway obstruction (obstructive sleep apnea)."},{"id": 2555,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Biomechanics is best defined as the study of:","options": [{"key": "A","text": "Blood flow in vessels"},{"key": "B","text": "Electrical activity of nerves"},{"key": "C","text": "Forces and their effects on living systems"},{"key": "D","text": "Chemical reactions in muscle"}],"correct": "C","explanation": "Biomechanics applies mechanical principles to forces acting on/within biological systems."},{"id": 2556,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Kinematics is concerned with:","options": [{"key": "A","text": "Description of motion without reference to forces"},{"key": "B","text": "Forces causing motion"},{"key": "C","text": "Energy expenditure"},{"key": "D","text": "Muscle strength only"}],"correct": "A","explanation": "Kinematics describes motion (displacement, velocity, acceleration) irrespective of causative forces."},{"id": 2557,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Kinetics deals primarily with:","options": [{"key": "A","text": "Motion description only"},{"key": "B","text": "Muscle origin and insertion"},{"key": "C","text": "Forces that cause or tend to cause motion"},{"key": "D","text": "Joint range of motion"}],"correct": "C","explanation": "Kinetics studies the forces, torques and other causes underlying motion."},{"id": 2558,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The anatomical position is used as a reference because it provides a:","options": [{"key": "A","text": "Standard starting reference for describing movement"},{"key": "B","text": "Position of maximum joint stability"},{"key": "C","text": "Position used only in gait analysis"},{"key": "D","text": "Comfortable resting posture"}],"correct": "A","explanation": "Anatomical position is the universal reference posture for describing planes, axes and movements."},{"id": 2559,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The sagittal plane divides the body into:","options": [{"key": "A","text": "Right and left parts"},{"key": "B","text": "Upper and lower parts"},{"key": "C","text": "Superficial and deep parts"},{"key": "D","text": "Anterior and posterior parts"}],"correct": "A","explanation": "The sagittal plane runs anteroposteriorly, dividing the body into right and left sections."},{"id": 2560,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The frontal (coronal) plane divides the body into:","options": [{"key": "A","text": "Anterior and posterior parts"},{"key": "B","text": "Medial and lateral parts"},{"key": "C","text": "Superior and inferior parts"},{"key": "D","text": "Right and left parts"}],"correct": "A","explanation": "The frontal plane runs side to side, separating the body into anterior and posterior parts."},{"id": 2561,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The transverse plane divides the body into:","options": [{"key": "A","text": "Right and left parts"},{"key": "B","text": "Anterior and posterior parts"},{"key": "C","text": "Superior and inferior parts"},{"key": "D","text": "Proximal and distal parts"}],"correct": "C","explanation": "The transverse (horizontal) plane separates the body into upper and lower sections."},{"id": 2562,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Flexion and extension of the knee occur in which plane?","options": [{"key": "A","text": "Frontal"},{"key": "B","text": "Transverse"},{"key": "C","text": "Sagittal"},{"key": "D","text": "Oblique"}],"correct": "C","explanation": "Flexion-extension movements occur in the sagittal plane about a mediolateral axis."},{"id": 2563,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Abduction and adduction of the hip occur in which plane?","options": [{"key": "A","text": "Sagittal"},{"key": "B","text": "Frontal"},{"key": "C","text": "Transverse"},{"key": "D","text": "Horizontal"}],"correct": "B","explanation": "Abduction/adduction occurs in the frontal plane about an anteroposterior axis."},{"id": 2564,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Internal and external rotation of the shoulder occur in which plane?","options": [{"key": "A","text": "Coronal"},{"key": "B","text": "Sagittal"},{"key": "C","text": "Transverse"},{"key": "D","text": "Frontal"}],"correct": "C","explanation": "Rotational movements occur in the transverse plane about a longitudinal (vertical) axis."},{"id": 2565,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The axis about which sagittal plane motion occurs is the:","options": [{"key": "A","text": "Longitudinal axis"},{"key": "B","text": "Oblique axis"},{"key": "C","text": "Mediolateral axis"},{"key": "D","text": "Anteroposterior axis"}],"correct": "C","explanation": "Sagittal plane movements (flexion/extension) occur about a mediolateral (frontal) axis."},{"id": 2566,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The axis about which frontal plane motion occurs is the:","options": [{"key": "A","text": "Mediolateral axis"},{"key": "B","text": "Vertical axis"},{"key": "C","text": "Anteroposterior axis"},{"key": "D","text": "Diagonal axis"}],"correct": "C","explanation": "Frontal plane movements (abduction/adduction) occur about an anteroposterior (sagittal) axis."},{"id": 2567,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The axis about which transverse plane motion occurs is the:","options": [{"key": "A","text": "Mediolateral axis"},{"key": "B","text": "Anteroposterior axis"},{"key": "C","text": "Frontal axis"},{"key": "D","text": "Longitudinal (vertical) axis"}],"correct": "D","explanation": "Rotational movements in the transverse plane occur about the longitudinal axis."},{"id": 2568,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "A scalar quantity is one that has:","options": [{"key": "A","text": "Neither magnitude nor direction"},{"key": "B","text": "Only direction"},{"key": "C","text": "Magnitude and direction"},{"key": "D","text": "Only magnitude"}],"correct": "D","explanation": "Scalars (e.g., mass, speed, distance) are described by magnitude alone."},{"id": 2569,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "A vector quantity is one that has:","options": [{"key": "A","text": "Only direction"},{"key": "B","text": "Only magnitude"},{"key": "C","text": "Magnitude and direction"},{"key": "D","text": "No physical meaning"}],"correct": "C","explanation": "Vectors (e.g., force, velocity, displacement) require both magnitude and direction."},{"id": 2570,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which of the following is a vector quantity?","options": [{"key": "A","text": "Mass"},{"key": "B","text": "Speed"},{"key": "C","text": "Displacement"},{"key": "D","text": "Distance"}],"correct": "C","explanation": "Displacement has both magnitude and direction, making it a vector; distance is scalar."},{"id": 2571,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which of the following is a scalar quantity?","options": [{"key": "A","text": "Velocity"},{"key": "B","text": "Acceleration"},{"key": "C","text": "Speed"},{"key": "D","text": "Force"}],"correct": "C","explanation": "Speed indicates only magnitude of motion, without direction, making it scalar."},{"id": 2572,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Distance differs from displacement in that distance is:","options": [{"key": "A","text": "The total path length while displacement is the shortest straight-line change in position"},{"key": "B","text": "Always greater than displacement"},{"key": "C","text": "A vector while displacement is scalar"},{"key": "D","text": "Measured in different units"}],"correct": "A","explanation": "Distance is total path length (scalar); displacement is the net change in position with direction (vector)."},{"id": 2573,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Linear (translatory) motion in which all points move the same distance in the same direction along a straight line is called:","options": [{"key": "A","text": "Rectilinear motion"},{"key": "B","text": "Angular motion"},{"key": "C","text": "General motion"},{"key": "D","text": "Curvilinear motion"}],"correct": "A","explanation": "Rectilinear motion is straight-line translation where every point moves an equal distance simultaneously."},{"id": 2574,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Linear motion along a curved path is termed:","options": [{"key": "A","text": "Rotary motion"},{"key": "B","text": "Rectilinear motion"},{"key": "C","text": "Angular motion"},{"key": "D","text": "Curvilinear motion"}],"correct": "D","explanation": "Curvilinear motion refers to translation of a body along a curved line."},{"id": 2575,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Angular (rotary) motion occurs when a body:","options": [{"key": "A","text": "Rotates about a fixed axis"},{"key": "B","text": "Remains stationary"},{"key": "C","text": "Moves along a curved path with no fixed axis"},{"key": "D","text": "Moves in a straight line"}],"correct": "A","explanation": "In angular motion, all points of the body move through the same angle about a fixed axis."},{"id": 2576,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Most human movement is best classified as:","options": [{"key": "A","text": "Pure angular motion"},{"key": "B","text": "General motion (a combination of linear and angular)"},{"key": "C","text": "Pure rectilinear motion"},{"key": "D","text": "Pure curvilinear motion"}],"correct": "B","explanation": "Human movement typically combines rotation at joints with translation of body segments, termed general motion."},{"id": 2577,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "The unit of angular displacement in the SI system is:","options": [{"key": "A","text": "Meter"},{"key": "B","text": "Newton"},{"key": "C","text": "Radian"},{"key": "D","text": "Joule"}],"correct": "C","explanation": "Angular displacement is measured in radians (or degrees) in biomechanics."},{"id": 2578,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Velocity is defined as:","options": [{"key": "A","text": "Rate of change of acceleration"},{"key": "B","text": "Force per unit mass"},{"key": "C","text": "Rate of change of speed"},{"key": "D","text": "Rate of change of displacement with respect to time"}],"correct": "D","explanation": "Velocity = displacement/time, describing both speed and direction of motion."},{"id": 2579,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Acceleration is defined as:","options": [{"key": "A","text": "Total distance covered per unit time"},{"key": "B","text": "Rate of change of displacement"},{"key": "C","text": "Rate of change of force"},{"key": "D","text": "Rate of change of velocity with respect to time"}],"correct": "D","explanation": "Acceleration is the rate at which velocity changes over time."},{"id": 2580,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Angular velocity is expressed in units of:","options": [{"key": "A","text": "kg·m/s"},{"key": "B","text": "m/s"},{"key": "C","text": "N·m"},{"key": "D","text": "rad/s"}],"correct": "D","explanation": "Angular velocity is the rate of change of angular displacement, measured in radians per second."},{"id": 2581,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which term describes the number of independent movements possible at a joint?","options": [{"key": "A","text": "Range of motion"},{"key": "B","text": "Degrees of freedom"},{"key": "C","text": "Close-packed position"},{"key": "D","text": "Joint play"}],"correct": "B","explanation": "Degrees of freedom refer to the independent directions of motion (translation/rotation) allowed at a joint."},{"id": 2582,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "A joint that allows movement in one plane only (e.g., elbow flexion-extension) has how many degrees of freedom?","options": [{"key": "A","text": "Two"},{"key": "B","text": "One"},{"key": "C","text": "Three"},{"key": "D","text": "Six"}],"correct": "B","explanation": "Uniaxial (hinge) joints like the elbow permit motion in a single plane, giving one degree of freedom."},{"id": 2583,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The hip joint, being a ball-and-socket joint, has how many rotational degrees of freedom?","options": [{"key": "A","text": "One"},{"key": "B","text": "Two"},{"key": "C","text": "Three"},{"key": "D","text": "Four"}],"correct": "C","explanation": "Ball-and-socket joints like the hip allow flexion/extension, abduction/adduction, and rotation—three degrees of freedom."},{"id": 2584,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Osteokinematics refers to:","options": [{"key": "A","text": "Movement between joint surfaces"},{"key": "B","text": "Movement of bones relative to the cardinal planes"},{"key": "C","text": "Muscle contraction mechanics"},{"key": "D","text": "Nerve conduction during movement"}],"correct": "B","explanation": "Osteokinematics describes gross bone movement (e.g., flexion, abduction) in relation to the three cardinal planes."},{"id": 2585,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Arthrokinematics refers to:","options": [{"key": "A","text": "Muscle fiber shortening"},{"key": "B","text": "Motion occurring between joint articulating surfaces"},{"key": "C","text": "Movement of the whole limb"},{"key": "D","text": "Movement of the axis of rotation only"}],"correct": "B","explanation": "Arthrokinematics describes the small accessory motions (roll, slide, spin) between joint surfaces."},{"id": 2586,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In biomechanics, 'closed kinematic chain' refers to a situation where:","options": [{"key": "A","text": "No movement occurs at all"},{"key": "B","text": "Both ends are free to move"},{"key": "C","text": "The proximal segment is fixed and distal segment moves freely"},{"key": "D","text": "The distal segment is fixed and proximal segment moves"}],"correct": "D","explanation": "In a closed chain, the distal end is fixed against a surface, so movement occurs proximally (e.g., squatting)."},{"id": 2587,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Open kinematic chain' refers to a situation where:","options": [{"key": "A","text": "Both segments are fixed"},{"key": "B","text": "The distal segment is fixed"},{"key": "C","text": "Movement occurs only at the axial skeleton"},{"key": "D","text": "The distal segment moves freely in space"}],"correct": "D","explanation": "In open chain movement, the distal segment is free to move, unconstrained by ground/external resistance (e.g., kicking a ball)."},{"id": 2588,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "An example of a closed kinetic chain exercise for the lower limb is:","options": [{"key": "A","text": "Leg extension in sitting"},{"key": "B","text": "Straight leg raise"},{"key": "C","text": "Seated knee flexion"},{"key": "D","text": "Squatting"}],"correct": "D","explanation": "Squatting keeps the feet fixed on the ground while proximal joints move, making it a closed chain activity."},{"id": 2589,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The term 'goniometry' refers to measurement of:","options": [{"key": "A","text": "Muscle strength"},{"key": "B","text": "Body segment mass"},{"key": "C","text": "Joint angles/range of motion"},{"key": "D","text": "Ground reaction force"}],"correct": "C","explanation": "Goniometry is the clinical measurement of joint angles using a goniometer."},{"id": 2590,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which of the following best defines 'mechanics' in the context of biomechanics?","options": [{"key": "A","text": "Study of living tissue chemistry"},{"key": "B","text": "Study of psychological effects of movement"},{"key": "C","text": "Study of nerve impulses"},{"key": "D","text": "Branch of physics dealing with forces and motion"}],"correct": "D","explanation": "Mechanics is the branch of physics concerned with the effects of forces on bodies and motion."},{"id": 2591,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Statics is the branch of mechanics that deals with:","options": [{"key": "A","text": "Bodies at rest or in equilibrium (constant velocity)"},{"key": "B","text": "Joint lubrication"},{"key": "C","text": "Muscle fatigue"},{"key": "D","text": "Bodies in motion with acceleration"}],"correct": "A","explanation": "Statics studies systems in equilibrium, i.e., at rest or moving with constant velocity (zero net force/acceleration)."},{"id": 2592,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Dynamics is the branch of mechanics that deals with:","options": [{"key": "A","text": "Bodies undergoing acceleration"},{"key": "B","text": "Forces without motion"},{"key": "C","text": "Bodies at rest only"},{"key": "D","text": "Joint anatomy"}],"correct": "A","explanation": "Dynamics studies systems undergoing acceleration, encompassing both kinematics and kinetics of moving bodies."},{"id": 2593,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which subdivision of dynamics studies motion without considering the forces causing it?","options": [{"key": "A","text": "Kinematics"},{"key": "B","text": "Equilibrium analysis"},{"key": "C","text": "Statics"},{"key": "D","text": "Kinetics"}],"correct": "A","explanation": "Kinematics is a subdivision of dynamics focusing purely on the geometry/description of motion."},{"id": 2594,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "In the anatomical position, the palms face:","options": [{"key": "A","text": "Forward"},{"key": "B","text": "Toward the thighs"},{"key": "C","text": "Medially"},{"key": "D","text": "Backward"}],"correct": "A","explanation": "In standard anatomical position, the body stands erect, arms at sides, palms facing forward (anteriorly)."},{"id": 2595,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which plane passes through the body dividing it into equal right and left halves?","options": [{"key": "A","text": "Midsagittal plane"},{"key": "B","text": "Oblique plane"},{"key": "C","text": "Frontal plane"},{"key": "D","text": "Transverse plane"}],"correct": "A","explanation": "The midsagittal (median) plane is the specific sagittal plane that creates two equal, symmetrical halves."},{"id": 2596,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Wrist radial and ulnar deviation occur in which plane?","options": [{"key": "A","text": "Frontal"},{"key": "B","text": "Horizontal"},{"key": "C","text": "Transverse"},{"key": "D","text": "Sagittal"}],"correct": "A","explanation": "Radial/ulnar deviation is a frontal plane motion about an anteroposterior axis at the wrist."},{"id": 2597,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Trunk rotation (twisting) occurs primarily in which plane?","options": [{"key": "A","text": "Transverse"},{"key": "B","text": "Frontal"},{"key": "C","text": "Coronal"},{"key": "D","text": "Sagittal"}],"correct": "A","explanation": "Trunk rotation occurs in the transverse plane about the longitudinal axis of the spine."},{"id": 2598,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The term 'anthropometry' refers to:","options": [{"key": "A","text": "Analysis of ground reaction forces"},{"key": "B","text": "Study of joint mechanics"},{"key": "C","text": "Study of muscle electrical activity"},{"key": "D","text": "Measurement of body segment dimensions, mass, and proportions"}],"correct": "D","explanation": "Anthropometry involves measuring physical dimensions and mass properties of the human body, used in biomechanical modeling."},{"id": 2599,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which of the following is NOT one of the three cardinal planes?","options": [{"key": "A","text": "Frontal"},{"key": "B","text": "Transverse"},{"key": "C","text": "Sagittal"},{"key": "D","text": "Longitudinal"}],"correct": "D","explanation": "Longitudinal is an axis, not a plane; the three cardinal planes are sagittal, frontal, and transverse."},{"id": 2600,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A goniometer's stationary arm is typically aligned with the:","options": [{"key": "A","text": "Moving body segment"},{"key": "B","text": "Axis of rotation only"},{"key": "C","text": "Muscle belly"},{"key": "D","text": "Fixed proximal reference segment"}],"correct": "D","explanation": "The stationary arm aligns with the fixed/proximal segment while the moving arm follows the distal segment."},{"id": 2601,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Speed is calculated as:","options": [{"key": "A","text": "Velocity divided by acceleration"},{"key": "B","text": "Distance divided by time"},{"key": "C","text": "Displacement divided by time"},{"key": "D","text": "Force divided by mass"}],"correct": "B","explanation": "Speed is a scalar quantity calculated as total distance traveled divided by time taken."},{"id": 2602,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "If a runner completes one full lap of a circular track and returns to the starting point, their displacement is:","options": [{"key": "A","text": "Undefined"},{"key": "B","text": "Half the distance covered"},{"key": "C","text": "Zero"},{"key": "D","text": "Equal to the distance covered"}],"correct": "C","explanation": "Since start and end positions coincide, net displacement is zero even though distance covered is positive."},{"id": 2603,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Uniform velocity implies that a body covers:","options": [{"key": "A","text": "Zero displacement"},{"key": "B","text": "Increasing displacement over time"},{"key": "C","text": "Variable direction with constant speed"},{"key": "D","text": "Equal displacements in equal time intervals in the same direction"}],"correct": "D","explanation": "Uniform velocity means constant speed and constant direction, i.e., equal displacement in equal time intervals."},{"id": 2604,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A negative acceleration is also referred to as:","options": [{"key": "A","text": "Deceleration (in the context of decreasing speed)"},{"key": "B","text": "Terminal velocity"},{"key": "C","text": "Zero velocity"},{"key": "D","text": "Positive velocity"}],"correct": "A","explanation": "Negative acceleration indicates velocity is decreasing in the direction of motion, commonly called deceleration."},{"id": 2605,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The study of internal forces (e.g., muscle and joint reaction forces) acting on the body falls under:","options": [{"key": "A","text": "Kinematics"},{"key": "B","text": "Internal kinetics"},{"key": "C","text": "External kinetics only"},{"key": "D","text": "Anthropometry"}],"correct": "B","explanation": "Internal kinetics examines forces produced within the body, such as muscle tension and joint reaction forces."},{"id": 2606,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Ground reaction force is an example of:","options": [{"key": "A","text": "Elastic force"},{"key": "B","text": "External force"},{"key": "C","text": "Internal force"},{"key": "D","text": "Muscle force"}],"correct": "B","explanation": "Ground reaction force is exerted by an external surface (ground) on the body, making it an external force."},{"id": 2607,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'rigid body' in biomechanical modeling assumes that:","options": [{"key": "A","text": "The body cannot rotate"},{"key": "B","text": "The body has no mass"},{"key": "C","text": "The body deforms under load"},{"key": "D","text": "Distance between any two points on the body remains constant"}],"correct": "D","explanation": "Rigid body models simplify analysis by assuming no deformation, so all internal distances stay fixed under load."},{"id": 2608,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following best describes 'equilibrium'?","options": [{"key": "A","text": "A state of maximum acceleration"},{"key": "B","text": "A state achievable only when a body is stationary"},{"key": "C","text": "A state where net force and net torque acting on a body are both zero"},{"key": "D","text": "A state of constant velocity change"}],"correct": "C","explanation": "Equilibrium exists when the sum of forces and sum of torques acting on a body are both zero, whether at rest or moving at constant velocity."},{"id": 2609,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "Static equilibrium refers to a body that is:","options": [{"key": "A","text": "At rest with zero net force and torque"},{"key": "B","text": "Accelerating uniformly"},{"key": "C","text": "Moving with increasing velocity"},{"key": "D","text": "Rotating continuously"}],"correct": "A","explanation": "Static equilibrium describes a body at complete rest with balanced forces and torques."},{"id": 2610,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Dynamic equilibrium refers to a body:","options": [{"key": "A","text": "At complete rest"},{"key": "B","text": "Under unbalanced torque"},{"key": "C","text": "Moving with constant velocity and zero net force"},{"key": "D","text": "Undergoing acceleration"}],"correct": "C","explanation": "Dynamic equilibrium occurs when a body moves at constant velocity, meaning net force and acceleration are zero."},{"id": 2611,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In biomechanics, 'plane of motion' and 'axis of motion' are related such that:","options": [{"key": "A","text": "Motion can occur without any axis"},{"key": "B","text": "They are always identical"},{"key": "C","text": "Axes exist independently of planes"},{"key": "D","text": "Each plane of motion has a corresponding perpendicular axis"}],"correct": "D","explanation": "Every cardinal plane of motion has a corresponding axis that is perpendicular to it, about which the rotation occurs."},{"id": 2612,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Shoulder flexion to overhead position occurs in which plane?","options": [{"key": "A","text": "Transverse"},{"key": "B","text": "Horizontal"},{"key": "C","text": "Sagittal"},{"key": "D","text": "Frontal"}],"correct": "C","explanation": "Shoulder flexion is a sagittal plane motion occurring about a mediolateral axis."},{"id": 2613,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Circumduction is best described as:","options": [{"key": "A","text": "Movement restricted to one plane"},{"key": "B","text": "A translatory glide"},{"key": "C","text": "Pure rotation only"},{"key": "D","text": "A sequential combination of flexion, abduction, extension, and adduction producing a conical motion"}],"correct": "D","explanation": "Circumduction combines motions from multiple planes in sequence, tracing a cone-like path, seen at ball-and-socket and condyloid joints."},{"id": 2614,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following pairs is correctly matched (plane – example movement)?","options": [{"key": "A","text": "Frontal – hip abduction"},{"key": "B","text": "Frontal – trunk rotation"},{"key": "C","text": "Sagittal – shoulder abduction"},{"key": "D","text": "Transverse – knee flexion"}],"correct": "A","explanation": "Hip abduction/adduction occurs in the frontal plane about an anteroposterior axis, correctly matching plane and movement."},{"id": 2615,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Force is defined as:","options": [{"key": "A","text": "Any push or pull that tends to change the state of rest or motion of a body"},{"key": "B","text": "Energy stored in a muscle"},{"key": "C","text": "Mass times distance"},{"key": "D","text": "Rate of change of momentum only in rotation"}],"correct": "A","explanation": "Force is a vector quantity representing any interaction that changes or tends to change a body's motion."},{"id": 2616,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "The SI unit of force is the:","options": [{"key": "A","text": "Pascal"},{"key": "B","text": "Watt"},{"key": "C","text": "Joule"},{"key": "D","text": "Newton"}],"correct": "D","explanation": "Force is measured in Newtons (N), defined as kg·m/s²."},{"id": 2617,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "One Newton is defined as the force required to give a mass of:","options": [{"key": "A","text": "1 g an acceleration of 1 cm/s²"},{"key": "B","text": "1 kg an acceleration of 9.8 m/s²"},{"key": "C","text": "1 kg an acceleration of 1 m/s²"},{"key": "D","text": "10 kg an acceleration of 1 m/s²"}],"correct": "C","explanation": "1 N = force needed to accelerate 1 kg of mass at 1 m/s², per Newton's second law."},{"id": 2618,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Which of the following is an example of an internal force in the human body?","options": [{"key": "A","text": "Gravity"},{"key": "B","text": "Muscle tension"},{"key": "C","text": "Ground reaction force"},{"key": "D","text": "Air resistance"}],"correct": "B","explanation": "Muscle tension is generated within the body, classifying it as an internal force."},{"id": 2619,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Gravity is best classified as:","options": [{"key": "A","text": "A frictional force"},{"key": "B","text": "An external non-contact force"},{"key": "C","text": "A reaction force only"},{"key": "D","text": "An internal contact force"}],"correct": "B","explanation": "Gravity acts at a distance without direct contact, making it an external, non-contact force."},{"id": 2620,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Torque (moment of force) is calculated as:","options": [{"key": "A","text": "Mass multiplied by acceleration"},{"key": "B","text": "Force multiplied by time"},{"key": "C","text": "Force divided by distance"},{"key": "D","text": "Force multiplied by perpendicular distance from the axis of rotation"}],"correct": "D","explanation": "Torque = Force × perpendicular distance (moment arm) from the axis of rotation."},{"id": 2621,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "The perpendicular distance from the axis of rotation to the line of force application is called the:","options": [{"key": "A","text": "Center of mass"},{"key": "B","text": "Base of support"},{"key": "C","text": "Lever arm/moment arm"},{"key": "D","text": "Line of gravity"}],"correct": "C","explanation": "The moment arm (lever arm) is the perpendicular distance used in torque calculation."},{"id": 2622,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "The SI unit of torque is:","options": [{"key": "A","text": "Joule"},{"key": "B","text": "Newton-meter"},{"key": "C","text": "Newton"},{"key": "D","text": "Watt"}],"correct": "B","explanation": "Torque is expressed in Newton-meters (N·m), reflecting force multiplied by distance."},{"id": 2623,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "If the angle of muscle pull relative to bone is 90 degrees, the entire force component is:","options": [{"key": "A","text": "Zero"},{"key": "B","text": "Rotatory (producing maximum torque)"},{"key": "C","text": "Translatory only"},{"key": "D","text": "Stabilizing only"}],"correct": "B","explanation": "At 90°, the muscle force is entirely rotatory (perpendicular), producing the maximal torque for a given force."},{"id": 2624,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "When a muscle pulls at an angle less than 90° to the bone, its force can be resolved into:","options": [{"key": "A","text": "Rotatory and stabilizing (or dislocating) components"},{"key": "B","text": "No components, force is lost"},{"key": "C","text": "Only a rotatory component"},{"key": "D","text": "Only a translatory component"}],"correct": "A","explanation": "Oblique muscle pull is resolved into a rotatory component (perpendicular) and a translatory/stabilizing component (parallel to bone)."},{"id": 2625,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "A first-class lever has which arrangement?","options": [{"key": "A","text": "Fulcrum between effort and resistance"},{"key": "B","text": "No fulcrum required"},{"key": "C","text": "Effort between fulcrum and resistance"},{"key": "D","text": "Resistance between fulcrum and effort"}],"correct": "A","explanation": "In a first-class lever, the fulcrum lies between the effort and the resistance (e.g., head nodding at atlanto-occipital joint)."},{"id": 2626,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A second-class lever has which arrangement?","options": [{"key": "A","text": "Resistance between fulcrum and effort"},{"key": "B","text": "Effort between fulcrum and resistance"},{"key": "C","text": "Effort and resistance at the same point"},{"key": "D","text": "Fulcrum between effort and resistance"}],"correct": "A","explanation": "In second-class levers, resistance lies between the fulcrum and effort, giving mechanical advantage >1 (e.g., raising the body on toes)."},{"id": 2627,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "A third-class lever has which arrangement?","options": [{"key": "A","text": "Effort between fulcrum and resistance"},{"key": "B","text": "Resistance between fulcrum and effort"},{"key": "C","text": "Fulcrum between effort and resistance"},{"key": "D","text": "Fulcrum at the resistance point"}],"correct": "A","explanation": "In third-class levers, the effort lies between the fulcrum and resistance—the most common lever type in the human body (e.g., elbow flexion by biceps)."},{"id": 2628,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Which class of lever is most common in the human musculoskeletal system?","options": [{"key": "A","text": "First class"},{"key": "B","text": "Fourth class"},{"key": "C","text": "Second class"},{"key": "D","text": "Third class"}],"correct": "D","explanation": "Most limb muscles insert close to joints, making third-class levers (favoring speed/range over force) the most common in the body."},{"id": 2629,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A classic clinical example of a second-class lever in the body is:","options": [{"key": "A","text": "Elbow flexion by the biceps"},{"key": "B","text": "Standing on tiptoes (raising body weight on the forefoot)"},{"key": "C","text": "Forearm flexion against resistance"},{"key": "D","text": "Nodding of the head at the atlanto-occipital joint"}],"correct": "B","explanation": "Standing on toes uses the metatarsal heads as fulcrum, with resistance (body weight) between fulcrum and the effort (calf muscles), a second-class lever."},{"id": 2630,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Mechanical advantage (MA) is defined as the ratio of:","options": [{"key": "A","text": "Effort force to body weight"},{"key": "B","text": "Resistance arm to effort arm"},{"key": "C","text": "Resistance to acceleration"},{"key": "D","text": "Effort arm to resistance arm"}],"correct": "D","explanation": "MA = Effort arm (force arm) / Resistance arm (resistance moment arm)."},{"id": 2631,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A mechanical advantage greater than 1 indicates that the lever:","options": [{"key": "A","text": "Cannot produce motion"},{"key": "B","text": "Has no effect on force required"},{"key": "C","text": "Requires less effort force than resistance to balance it"},{"key": "D","text": "Requires more effort force than resistance"}],"correct": "C","explanation": "MA > 1 means the effort arm is longer than the resistance arm, so less effort force is needed to balance a given resistance."},{"id": 2632,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Most third-class levers in the body have a mechanical advantage:","options": [{"key": "A","text": "Greater than 1"},{"key": "B","text": "Less than 1"},{"key": "C","text": "Undefined"},{"key": "D","text": "Equal to 1"}],"correct": "B","explanation": "Since effort arm is shorter than resistance arm in third-class levers, MA is less than 1, favoring speed and range of motion over force."},{"id": 2633,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A lever system with MA < 1 is best suited for producing:","options": [{"key": "A","text": "Greater force output at the cost of speed"},{"key": "B","text": "Zero net motion"},{"key": "C","text": "Greater speed and range of motion at the cost of force"},{"key": "D","text": "Only static holding"}],"correct": "C","explanation": "MA < 1 systems require more force input but produce faster, larger movements at the distal end—typical of limb muscles."},{"id": 2634,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "In the biceps curl, the elbow joint acts as the:","options": [{"key": "A","text": "Fulcrum"},{"key": "B","text": "Effort"},{"key": "C","text": "Load arm"},{"key": "D","text": "Resistance"}],"correct": "A","explanation": "The elbow joint serves as the fulcrum (axis of rotation) in a third-class lever system during a biceps curl."},{"id": 2635,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Torque produced by a muscle can be increased by:","options": [{"key": "A","text": "Decreasing the muscle force only"},{"key": "B","text": "Reducing joint angle to less than 90°"},{"key": "C","text": "Aligning the force parallel to the bone"},{"key": "D","text": "Increasing the moment arm (perpendicular distance) for a given force"}],"correct": "D","explanation": "Since torque = force × moment arm, increasing the perpendicular moment arm increases torque for the same muscle force."},{"id": 2636,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The point in the range of motion where a muscle's moment arm is greatest is called the:","options": [{"key": "A","text": "Point of maximal mechanical advantage (peak torque angle)"},{"key": "B","text": "Angle of pull"},{"key": "C","text": "Angle of insertion"},{"key": "D","text": "Zero moment point"}],"correct": "A","explanation": "This is the joint angle at which the muscle's moment arm is largest, producing peak torque for a given muscle force."},{"id": 2637,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A force couple consists of:","options": [{"key": "A","text": "A single force acting alone"},{"key": "B","text": "Two equal, parallel forces acting in the same direction"},{"key": "C","text": "Two equal, parallel forces acting in opposite directions, producing pure rotation"},{"key": "D","text": "Two unequal forces at the same point"}],"correct": "C","explanation": "A force couple is formed by two equal and opposite parallel forces that create rotation without translation (e.g., scapular upward rotation by upper/lower trapezius and serratus anterior)."},{"id": 2638,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Concurrent forces are forces that:","options": [{"key": "A","text": "Act at the same point but in different directions"},{"key": "B","text": "Act only in parallel"},{"key": "C","text": "Never intersect"},{"key": "D","text": "Act along the same line"}],"correct": "A","explanation": "Concurrent forces share a common point of application while acting in different directions, and their resultant can be found via vector addition."},{"id": 2639,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The resultant of two or more forces is:","options": [{"key": "A","text": "A single force that has the same effect as the combination of individual forces"},{"key": "B","text": "Always equal to the largest individual force"},{"key": "C","text": "The average of all forces"},{"key": "D","text": "Only relevant in linear motion"}],"correct": "A","explanation": "The resultant force is a single equivalent force representing the net effect of all forces acting on a body, found via vector addition."},{"id": 2640,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Resolution of forces refers to:","options": [{"key": "A","text": "Combining two forces into one resultant"},{"key": "B","text": "Measuring force magnitude only"},{"key": "C","text": "Breaking a single force into two or more component forces"},{"key": "D","text": "Cancelling opposite forces"}],"correct": "C","explanation": "Force resolution decomposes a single force into perpendicular components (e.g., rotatory and stabilizing components of muscle pull)."},{"id": 2641,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "According to the parallelogram law, the resultant of two forces acting at a point is represented by:","options": [{"key": "A","text": "The sum of their magnitudes only"},{"key": "B","text": "The perpendicular bisector of the two forces"},{"key": "C","text": "The diagonal of the parallelogram formed by the two forces as adjacent sides"},{"key": "D","text": "The difference of the two forces"}],"correct": "C","explanation": "The parallelogram law states the resultant is the diagonal of the parallelogram constructed with the two forces as sides."},{"id": 2642,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "A stabilizing (compressive) component of muscle force acts:","options": [{"key": "A","text": "Away from the joint axis only"},{"key": "B","text": "Perpendicular to the bone"},{"key": "C","text": "Parallel to the bone, pulling joint surfaces together"},{"key": "D","text": "Only during eccentric contraction"}],"correct": "C","explanation": "The stabilizing component runs parallel/along the long axis of the bone, compressing joint surfaces together and enhancing joint stability."},{"id": 2643,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "A dislocating (distracting) component of muscle force occurs when the angle of pull is:","options": [{"key": "A","text": "Exactly 90°"},{"key": "B","text": "Greater than 90°, directing force away from the joint"},{"key": "C","text": "Less than 90° only"},{"key": "D","text": "Zero degrees"}],"correct": "B","explanation": "When the angle of pull exceeds 90°, the parallel component pulls the bone away from the joint surface, creating a distracting/dislocating tendency."},{"id": 2644,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Friction is a force that acts:","options": [{"key": "A","text": "In the direction of motion"},{"key": "B","text": "Perpendicular to the surface only"},{"key": "C","text": "Only in fluids"},{"key": "D","text": "Opposite to the direction of relative motion or tendency of motion between surfaces"}],"correct": "D","explanation": "Friction opposes relative motion or the tendency of motion between two contacting surfaces."},{"id": 2645,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Static friction is the friction that:","options": [{"key": "A","text": "Prevents a stationary body from starting to move"},{"key": "B","text": "Only occurs in fluids"},{"key": "C","text": "Is always less than kinetic friction"},{"key": "D","text": "Acts on a body already in motion"}],"correct": "A","explanation": "Static friction resists the initiation of motion between two surfaces in contact."},{"id": 2646,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Kinetic (dynamic) friction acts:","options": [{"key": "A","text": "Before motion begins"},{"key": "B","text": "While two surfaces are in relative motion"},{"key": "C","text": "On stationary bodies only"},{"key": "D","text": "Only in a vacuum"}],"correct": "B","explanation": "Kinetic friction opposes relative sliding motion once the body is already moving."},{"id": 2647,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The coefficient of friction depends primarily on:","options": [{"key": "A","text": "The nature/roughness of the two contacting surfaces"},{"key": "B","text": "The velocity of the object"},{"key": "C","text": "The color of the surfaces"},{"key": "D","text": "The temperature of the body only"}],"correct": "A","explanation": "The coefficient of friction is a property of the two surfaces in contact (their material and roughness), not velocity or mass."},{"id": 2648,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Which formula correctly represents the frictional force?","options": [{"key": "A","text": "F = μ/N"},{"key": "B","text": "F = μN, where N is normal reaction force"},{"key": "C","text": "F = N/μ"},{"key": "D","text": "F = μ + N"}],"correct": "B","explanation": "Frictional force equals the coefficient of friction (μ) multiplied by the normal reaction force (N)."},{"id": 2649,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "In rehabilitation, friction at a joint surface that is excessive can lead to:","options": [{"key": "A","text": "Increased mechanical advantage"},{"key": "B","text": "Improved lubrication"},{"key": "C","text": "Cartilage wear and joint damage"},{"key": "D","text": "Increased range of motion"}],"correct": "C","explanation": "Excessive friction at articular surfaces accelerates wear of cartilage and can contribute to joint degeneration."},{"id": 2650,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Work, in the mechanical sense, is defined as:","options": [{"key": "A","text": "Force applied over time"},{"key": "B","text": "Energy consumed by a muscle at rest"},{"key": "C","text": "Force multiplied by the displacement in the direction of the force"},{"key": "D","text": "Mass multiplied by velocity"}],"correct": "C","explanation": "Mechanical work = Force × displacement (in the direction of the applied force)."},{"id": 2651,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The SI unit of work is the:","options": [{"key": "A","text": "Watt"},{"key": "B","text": "Pascal"},{"key": "C","text": "Newton"},{"key": "D","text": "Joule"}],"correct": "D","explanation": "Work is measured in Joules (J), where 1 J = 1 N·m."},{"id": 2652,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "If a person holds a heavy weight stationary overhead, the mechanical work done on the weight is:","options": [{"key": "A","text": "Dependent on holding time only"},{"key": "B","text": "Equal to the force applied"},{"key": "C","text": "Zero, since there is no displacement"},{"key": "D","text": "Maximum"}],"correct": "C","explanation": "Since work requires displacement, holding a weight statically (no movement) means zero mechanical work is done, despite muscular effort."},{"id": 2653,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Energy is defined as:","options": [{"key": "A","text": "The same as power"},{"key": "B","text": "The rate of doing work"},{"key": "C","text": "The capacity to do work"},{"key": "D","text": "Force multiplied by distance only"}],"correct": "C","explanation": "Energy is the capacity or ability of a system to perform work."},{"id": 2654,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Kinetic energy is the energy possessed by a body due to its:","options": [{"key": "A","text": "Deformation only"},{"key": "B","text": "Motion"},{"key": "C","text": "Temperature"},{"key": "D","text": "Position"}],"correct": "B","explanation": "Kinetic energy (KE = ½mv²) depends on the mass and velocity of a moving body."},{"id": 2655,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Potential energy is the energy possessed by a body due to its:","options": [{"key": "A","text": "Frictional resistance"},{"key": "B","text": "Motion"},{"key": "C","text": "Position or configuration (e.g., height, elastic deformation)"},{"key": "D","text": "Acceleration"}],"correct": "C","explanation": "Potential energy depends on position (gravitational PE) or deformation (elastic/strain PE), not motion."},{"id": 2656,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "The formula for kinetic energy is:","options": [{"key": "A","text": "KE = ½mv²"},{"key": "B","text": "KE = mgh"},{"key": "C","text": "KE = mv"},{"key": "D","text": "KE = Fd"}],"correct": "A","explanation": "Kinetic energy is calculated as one-half mass times velocity squared."},{"id": 2657,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The formula for gravitational potential energy is:","options": [{"key": "A","text": "PE = mgh"},{"key": "B","text": "PE = Fd"},{"key": "C","text": "PE = ½mv²"},{"key": "D","text": "PE = m/v"}],"correct": "A","explanation": "Gravitational potential energy equals mass × gravitational acceleration × height above a reference point."},{"id": 2658,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "According to the law of conservation of energy, in the absence of external forces like friction, total mechanical energy of a system:","options": [{"key": "A","text": "Increases continuously"},{"key": "B","text": "Decreases continuously"},{"key": "C","text": "Remains constant (converts between kinetic and potential forms)"},{"key": "D","text": "Becomes zero"}],"correct": "C","explanation": "Total mechanical energy (KE + PE) remains constant in an ideal, frictionless system, though it may convert between forms."},{"id": 2659,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Power is defined as:","options": [{"key": "A","text": "Energy stored in muscle"},{"key": "B","text": "The rate of doing work (work done per unit time)"},{"key": "C","text": "Force multiplied by distance"},{"key": "D","text": "The capacity to do work"}],"correct": "B","explanation": "Power = Work / Time, representing how quickly work is performed."},{"id": 2660,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The SI unit of power is the:","options": [{"key": "A","text": "Joule"},{"key": "B","text": "Watt"},{"key": "C","text": "Newton"},{"key": "D","text": "Newton-meter"}],"correct": "B","explanation": "Power is measured in Watts (W), where 1 W = 1 J/s."},{"id": 2661,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A physiotherapy exercise performed quickly (same work, less time) results in:","options": [{"key": "A","text": "Zero power"},{"key": "B","text": "Higher power output"},{"key": "C","text": "Lower power output"},{"key": "D","text": "No change in power"}],"correct": "B","explanation": "Since power = work/time, performing the same work in less time increases power output."},{"id": 2662,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Momentum is defined as:","options": [{"key": "A","text": "Mass multiplied by velocity"},{"key": "B","text": "Force multiplied by time"},{"key": "C","text": "Mass multiplied by acceleration"},{"key": "D","text": "Force divided by mass"}],"correct": "A","explanation": "Linear momentum (p) = mass × velocity, a vector quantity in the direction of motion."},{"id": 2663,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The impulse-momentum relationship states that impulse equals:","options": [{"key": "A","text": "Change in torque"},{"key": "B","text": "Change in kinetic energy"},{"key": "C","text": "Change in potential energy"},{"key": "D","text": "Change in momentum"}],"correct": "D","explanation": "Impulse (Force × time) equals the change in momentum of a body, per Newton's second law in its impulse form."},{"id": 2664,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Angular momentum is the rotational equivalent of:","options": [{"key": "A","text": "Linear momentum"},{"key": "B","text": "Kinetic energy"},{"key": "C","text": "Linear velocity"},{"key": "D","text": "Torque only"}],"correct": "A","explanation": "Angular momentum (moment of inertia × angular velocity) is the rotational analogue of linear momentum."},{"id": 2665,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Increasing the time over which a force acts to bring a moving body to rest will:","options": [{"key": "A","text": "Increase the force of impact"},{"key": "B","text": "Have no effect on impact force"},{"key": "C","text": "Decrease the force of impact (for the same change in momentum)"},{"key": "D","text": "Increase momentum"}],"correct": "C","explanation": "Since impulse (F×t) equals the fixed change in momentum, increasing time reduces the required force—the principle behind cushioning/landing techniques."},{"id": 2666,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The principle of increasing time to reduce impact force is clinically applied in:","options": [{"key": "A","text": "Shock-absorbing footwear and proper landing technique"},{"key": "B","text": "Rigid casting only"},{"key": "C","text": "Static stretching"},{"key": "D","text": "Isometric exercise"}],"correct": "A","explanation": "Cushioned footwear and bent-knee landings extend the time of force application, reducing peak impact forces on joints."},{"id": 2667,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Which class of lever, if any, always has a mechanical advantage greater than 1?","options": [{"key": "A","text": "None; it varies with fulcrum position"},{"key": "B","text": "First class only"},{"key": "C","text": "Second class"},{"key": "D","text": "Third class"}],"correct": "C","explanation": "Second-class levers always have the resistance closer to the fulcrum than the effort, giving MA > 1."},{"id": 2668,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "First-class levers can have mechanical advantage that is:","options": [{"key": "A","text": "Always exactly equal to 1"},{"key": "B","text": "Always greater than 1"},{"key": "C","text": "Always less than 1"},{"key": "D","text": "Greater than, less than, or equal to 1, depending on fulcrum position"}],"correct": "D","explanation": "In first-class levers, MA depends on where the fulcrum sits relative to effort and resistance, so MA can vary above or below 1."},{"id": 2669,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "When using a wheelbarrow, which lever class is best represented?","options": [{"key": "A","text": "No lever action involved"},{"key": "B","text": "Third class"},{"key": "C","text": "First class"},{"key": "D","text": "Second class"}],"correct": "D","explanation": "A wheelbarrow's wheel acts as fulcrum, load is between fulcrum and effort (hands), representing a second-class lever."},{"id": 2670,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A pair of scissors is an example of which type of lever?","options": [{"key": "A","text": "Third class"},{"key": "B","text": "Fourth class"},{"key": "C","text": "Second class"},{"key": "D","text": "First class"}],"correct": "D","explanation": "Scissors have the pivot (fulcrum) between the effort (handles) and resistance (blades cutting), a first-class lever."},{"id": 2671,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Using tweezers to pick up a small object is an example of which lever class?","options": [{"key": "A","text": "Second class"},{"key": "B","text": "First class"},{"key": "C","text": "None of the above"},{"key": "D","text": "Third class"}],"correct": "D","explanation": "Tweezers have effort applied between the fulcrum (bend) and resistance (tips), a third-class lever."},{"id": 2672,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The efficiency of a lever system in the body is often sacrificed for:","options": [{"key": "A","text": "Increased speed and range of motion of the distal segment"},{"key": "B","text": "Reduced energy expenditure"},{"key": "C","text": "Greater joint stability only"},{"key": "D","text": "Increased force output"}],"correct": "A","explanation": "Most body levers (third-class) trade mechanical force advantage for greater speed and range of movement at the distal end."},{"id": 2673,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In clinical practice, lengthening a resistance arm (e.g., using a longer exercise handle) will:","options": [{"key": "A","text": "Eliminate the need for a fulcrum"},{"key": "B","text": "Decrease the torque required to move it"},{"key": "C","text": "Increase the torque (effort) required for the same resistance force"},{"key": "D","text": "Have no effect on torque"}],"correct": "C","explanation": "A longer resistance arm increases the resistive torque, requiring greater muscular effort/torque to overcome it."},{"id": 2674,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Applying resistance farther from the joint axis during manual muscle testing increases:","options": [{"key": "A","text": "The angle of pull only"},{"key": "B","text": "The muscle's force-velocity relationship"},{"key": "C","text": "The coefficient of friction"},{"key": "D","text": "The resistance moment arm and therefore the torque needed to be overcome"}],"correct": "D","explanation": "Placing resistance farther from the axis lengthens the resistance arm, increasing the torque the muscle must generate to move it."},{"id": 2675,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why bent-knee sit-ups are easier than straight-leg sit-ups?","options": [{"key": "A","text": "Reduced resistance arm/torque at the hip due to shorter effective lever of the legs"},{"key": "B","text": "Decreased gravitational force"},{"key": "C","text": "Increased muscle length"},{"key": "D","text": "Increased coefficient of friction"}],"correct": "A","explanation": "Bending the knees shortens the effective resistance lever arm of the legs and trunk, reducing the torque the hip flexors/abdominals must overcome."},{"id": 2676,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Torque is a vector quantity whose direction is conventionally described as:","options": [{"key": "A","text": "Clockwise or counterclockwise (or using the right-hand rule)"},{"key": "B","text": "Undefined in biomechanics"},{"key": "C","text": "Always horizontal"},{"key": "D","text": "Always vertical"}],"correct": "A","explanation": "Torque direction is typically described as clockwise/counterclockwise, or via the right-hand rule for 3D analysis."},{"id": 2677,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Net torque about a joint is zero when a limb is:","options": [{"key": "A","text": "Accelerating angularly"},{"key": "B","text": "In rotational (angular) equilibrium"},{"key": "C","text": "Undergoing maximum velocity"},{"key": "D","text": "Never possible in the body"}],"correct": "B","explanation": "Zero net torque indicates rotational (angular) equilibrium, whether the segment is static or moving at constant angular velocity."},{"id": 2678,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following increases the mechanical advantage of the quadriceps at the knee during extension?","options": [{"key": "A","text": "Reducing muscle cross-sectional area"},{"key": "B","text": "Increasing joint friction"},{"key": "C","text": "The patella increasing the quadriceps tendon's moment arm from the knee axis"},{"key": "D","text": "Decreasing the patella's lever arm effect"}],"correct": "C","explanation": "The patella acts as an anatomical pulley, increasing the moment arm of the quadriceps tendon and thus improving extensor torque."},{"id": 2679,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "A patient with reduced patellar mobility (e.g., post-surgery) may show reduced quadriceps torque output primarily because:","options": [{"key": "A","text": "The patella's normal lever-arm-enhancing function is compromised"},{"key": "B","text": "Muscle fiber type changes"},{"key": "C","text": "Ligament laxity increases force"},{"key": "D","text": "Increased joint friction alone explains it"}],"correct": "A","explanation": "If the patella cannot glide/track normally, its mechanical role in increasing the quadriceps moment arm is impaired, reducing extensor torque efficiency."},{"id": 2680,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Two people push a swinging door from opposite sides at equal but opposite forces at the same distance from the hinge. This is an example of:","options": [{"key": "A","text": "Zero force scenario"},{"key": "B","text": "A resultant force"},{"key": "C","text": "A force couple producing zero net rotation (balanced) or pure rotation if forces align to same rotational direction"},{"key": "D","text": "Only linear motion"}],"correct": "C","explanation": "Equal, opposite, parallel forces at different points can form a force couple; whether net rotation is zero or maximal pure rotation depends on their relative directions."},{"id": 2681,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Which best describes 'line of action' of a force?","options": [{"key": "A","text": "The joint at which the force is applied"},{"key": "B","text": "The muscle belly length"},{"key": "C","text": "The resultant of two perpendicular forces"},{"key": "D","text": "An imaginary line extending infinitely in both directions along the direction of the force, passing through its point of application"}],"correct": "D","explanation": "The line of action represents the straight line along which a force acts, important in determining its moment arm about any axis."},{"id": 2682,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following is true regarding force platforms used in gait labs?","options": [{"key": "A","text": "They measure ground reaction forces in three orthogonal directions"},{"key": "B","text": "They measure joint angles directly"},{"key": "C","text": "They measure only muscle activity"},{"key": "D","text": "They calculate mechanical advantage only"}],"correct": "A","explanation": "Force platforms record ground reaction forces (vertical, anteroposterior, mediolateral) used to analyze external forces during gait."},{"id": 2683,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The 'angle of pull' of a muscle refers to the angle between:","options": [{"key": "A","text": "The muscle's line of pull and the long axis of the bone it acts on"},{"key": "B","text": "Two different muscles"},{"key": "C","text": "The joint axis and gravity"},{"key": "D","text": "Two joint surfaces"}],"correct": "A","explanation": "Angle of pull describes the angle formed between a muscle's tendon direction and the bone's long axis, determining rotatory vs stabilizing force components."},{"id": 2684,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "When the angle of pull of a muscle is 90°, the mechanical advantage for producing torque is:","options": [{"key": "A","text": "Undefined"},{"key": "B","text": "Maximum for that instant, since all force contributes to rotation"},{"key": "C","text": "Minimum"},{"key": "D","text": "Zero"}],"correct": "B","explanation": "At a 90° angle of pull, 100% of the muscle force acts perpendicular to the bone, maximizing the rotatory component and hence torque for that force magnitude."},{"id": 2685,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "A therapist applying manual resistance perpendicular to the limb throughout the entire range of motion (an isokinetic-like principle) ensures:","options": [{"key": "A","text": "Constant torque despite varying muscle force capability"},{"key": "B","text": "Zero resistance throughout"},{"key": "C","text": "Maximum friction only"},{"key": "D","text": "Constant muscle force regardless of position"}],"correct": "A","explanation": "Applying resistance perpendicular to the limb (via isokinetic dynamometers, for instance) allows torque measurement to reflect true muscular capability across the range."},{"id": 2686,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which of the following best distinguishes mass from weight?","options": [{"key": "A","text": "Weight is constant everywhere, mass varies"},{"key": "B","text": "Mass and weight are identical"},{"key": "C","text": "Mass is measured in Newtons"},{"key": "D","text": "Mass is a measure of inertia (constant), weight is the gravitational force on that mass (varies with gravity)"}],"correct": "D","explanation": "Mass (kg) is an invariant measure of inertia; weight (N) is the gravitational force on that mass, which varies with local gravitational acceleration."},{"id": 2687,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A astronaut's mass on the moon compared to Earth is:","options": [{"key": "A","text": "Reduced to one-sixth"},{"key": "B","text": "The same as on Earth"},{"key": "C","text": "Increased six-fold"},{"key": "D","text": "Zero"}],"correct": "B","explanation": "Mass remains constant regardless of location; only weight changes due to differing gravitational acceleration."},{"id": 2688,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "Compressive force at a joint is best described as a force that:","options": [{"key": "A","text": "Causes rotation only"},{"key": "B","text": "Is always harmful"},{"key": "C","text": "Pushes joint surfaces together"},{"key": "D","text": "Pulls joint surfaces apart"}],"correct": "C","explanation": "Compressive forces push articulating surfaces together, which is normal and often beneficial (e.g., promoting cartilage nutrition) within physiological limits."},{"id": 2689,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Shear force at a joint is a force that acts:","options": [{"key": "A","text": "Only during isometric contraction"},{"key": "B","text": "Parallel to the joint surface, tending to slide one surface over another"},{"key": "C","text": "Perpendicular to the joint surface, pushing surfaces together"},{"key": "D","text": "Only in the vertical plane"}],"correct": "B","explanation": "Shear force acts tangentially/parallel to a joint surface, tending to cause one surface to slide relative to the other."},{"id": 2690,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Excessive shear force at the knee joint is of particular clinical concern in relation to which structure?","options": [{"key": "A","text": "Iliotibial band only"},{"key": "B","text": "Patella"},{"key": "C","text": "Anterior cruciate ligament (ACL)"},{"key": "D","text": "Quadriceps tendon only"}],"correct": "C","explanation": "Anterior shear force at the tibia relative to the femur is resisted primarily by the ACL, making excessive shear a key concern in ACL injury mechanisms."},{"id": 2691,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A see-saw balanced with a heavier child sitting closer to the fulcrum than a lighter child illustrates the principle of:","options": [{"key": "A","text": "Conservation of momentum"},{"key": "B","text": "Newton's third law only"},{"key": "C","text": "Balancing torques (equal and opposite moments about the fulcrum)"},{"key": "D","text": "Friction reduction"}],"correct": "C","explanation": "For the see-saw to balance, the torques (force × distance) on each side about the fulcrum must be equal and opposite."},{"id": 2692,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "If Force A has a magnitude of 100 N applied at a moment arm of 0.05 m, the torque produced is:","options": [{"key": "A","text": "500 N·m"},{"key": "B","text": "5 N·m"},{"key": "C","text": "2000 N·m"},{"key": "D","text": "50 N·m"}],"correct": "B","explanation": "Torque = Force × moment arm = 100 N × 0.05 m = 5 N·m."},{"id": 2693,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "A muscle generates 400 N of force with a moment arm of 0.02 m at the joint. The resulting joint torque is:","options": [{"key": "A","text": "800 N·m"},{"key": "B","text": "8 N·m"},{"key": "C","text": "0.02 N·m"},{"key": "D","text": "20 N·m"}],"correct": "B","explanation": "Torque = 400 N × 0.02 m = 8 N·m."},{"id": 2694,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "A resistance of 150 N acts at 0.3 m from a joint axis. For equilibrium, an effort force acting at a moment arm of 0.05 m must be at least:","options": [{"key": "A","text": "900 N"},{"key": "B","text": "25 N"},{"key": "C","text": "150 N"},{"key": "D","text": "45 N"}],"correct": "A","explanation": "For balance: Effort × 0.05 = 150 × 0.3, so Effort = 45/0.05 = 900 N."},{"id": 2695,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "Center of gravity (COG) is defined as:","options": [{"key": "A","text": "A fixed anatomical landmark, same for all individuals"},{"key": "B","text": "The center of the base of support"},{"key": "C","text": "The highest point of the body"},{"key": "D","text": "The point at which the entire weight of the body is considered to be concentrated"}],"correct": "D","explanation": "COG is the theoretical point where the body's total weight/mass can be considered concentrated for analysis of balance."},{"id": 2696,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "In an average standing adult in anatomical position, the center of gravity is located approximately:","options": [{"key": "A","text": "At the level of C7"},{"key": "B","text": "At the level of the umbilicus"},{"key": "C","text": "At the sternum"},{"key": "D","text": "Anterior to the second sacral vertebra (S2)"}],"correct": "D","explanation": "In standing, COG typically lies just anterior to the S2 vertebra, roughly 55% of standing height in most adults."},{"id": 2697,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The center of gravity in females is generally located:","options": [{"key": "A","text": "Lower than in males, due to a relatively lower center of mass distribution"},{"key": "B","text": "Higher than in males"},{"key": "C","text": "At the exact same point as males"},{"key": "D","text": "Outside the body"}],"correct": "A","explanation": "Females typically have a slightly lower COG than males due to differing proportional distribution of mass in the pelvis and lower limbs."},{"id": 2698,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Line of gravity (LOG) is best described as:","options": [{"key": "A","text": "A line connecting the two feet"},{"key": "B","text": "The outline of the body's silhouette"},{"key": "C","text": "A horizontal line through the base of support"},{"key": "D","text": "A vertical line passing through the center of gravity toward the earth's center"}],"correct": "D","explanation": "LOG is an imaginary vertical line extending from the COG toward the center of the earth, used to assess postural alignment."},{"id": 2699,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Base of support (BOS) refers to:","options": [{"key": "A","text": "The height of the center of gravity"},{"key": "B","text": "The area beneath a body that is bounded by points of contact with the supporting surface"},{"key": "C","text": "The line of gravity's exact location"},{"key": "D","text": "The total body weight"}],"correct": "B","explanation": "BOS is the area encompassed by contact points between the body and the supporting surface, such as the feet in standing."},{"id": 2700,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Widening the base of support during standing generally results in:","options": [{"key": "A","text": "Increased stability"},{"key": "B","text": "No change in stability"},{"key": "C","text": "Decreased stability"},{"key": "D","text": "Increased center of gravity height"}],"correct": "A","explanation": "A wider BOS increases the margin within which the line of gravity can shift before balance is lost, enhancing stability."},{"id": 2701,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "Lowering the center of gravity generally results in:","options": [{"key": "A","text": "Increased stability"},{"key": "B","text": "Increased risk of falling"},{"key": "C","text": "No effect on stability"},{"key": "D","text": "Decreased stability"}],"correct": "A","explanation": "A lower COG reduces the tendency to topple, thereby increasing stability (e.g., a sumo wrestler's stance)."},{"id": 2702,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "For maximal stability, the line of gravity should ideally fall:","options": [{"key": "A","text": "At the edge of the base of support"},{"key": "B","text": "Outside the base of support"},{"key": "C","text": "Near the center of the base of support"},{"key": "D","text": "Above the center of gravity"}],"correct": "C","explanation": "Stability is maximized when the LOG falls within and close to the center of the BOS, giving the greatest margin before tipping."},{"id": 2703,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "A person will lose balance and fall when the line of gravity:","options": [{"key": "A","text": "Remains vertical"},{"key": "B","text": "Coincides with the center of gravity"},{"key": "C","text": "Falls outside the base of support without compensatory adjustment"},{"key": "D","text": "Passes through the center of the base of support"}],"correct": "C","explanation": "Loss of balance occurs when the LOG shifts outside the BOS and cannot be corrected by postural adjustments."},{"id": 2704,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following increases stability the most for a standing person?","options": [{"key": "A","text": "Raising the arms overhead"},{"key": "B","text": "Standing with feet wide apart and knees slightly flexed (lower COG)"},{"key": "C","text": "Standing on toes"},{"key": "D","text": "Standing on one leg with feet together"}],"correct": "B","explanation": "A wide stance combined with a lowered COG maximizes both BOS area and stability margin."},{"id": 2705,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "The four determinants of stability in a biomechanical sense include all of the following EXCEPT:","options": [{"key": "A","text": "Location of line of gravity relative to base of support"},{"key": "B","text": "Color of the supporting surface"},{"key": "C","text": "Height of center of gravity"},{"key": "D","text": "Size of base of support"}],"correct": "B","explanation": "Stability determinants include COG height, BOS size, LOG location relative to BOS, and body weight/mass—surface color is irrelevant."},{"id": 2706,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Increasing body mass, while keeping other factors constant, generally:","options": [{"key": "A","text": "Increases stability due to greater force needed to disturb equilibrium"},{"key": "B","text": "Has no effect on stability"},{"key": "C","text": "Decreases stability"},{"key": "D","text": "Only affects balance in water"}],"correct": "A","explanation": "Greater mass requires a larger disturbing force/torque to overcome resistance to movement, contributing to increased stability."},{"id": 2707,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which stance provides the LEAST stability for a standing individual?","options": [{"key": "A","text": "Feet shoulder-width apart"},{"key": "B","text": "Standing on one foot (single-leg stance)"},{"key": "C","text": "Wide stance, feet parallel"},{"key": "D","text": "Staggered stance (one foot forward)"}],"correct": "B","explanation": "Single-leg stance drastically reduces the base of support area, making it the least stable of the listed options."},{"id": 2708,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "A staggered stance (one foot ahead of the other) is often taught in rehabilitation to improve stability in which direction?","options": [{"key": "A","text": "Vertical direction only"},{"key": "B","text": "Anteroposterior direction"},{"key": "C","text": "Mediolateral direction"},{"key": "D","text": "Rotational direction only"}],"correct": "B","explanation": "A staggered stance enlarges the base of support in the anteroposterior direction, improving forward-backward stability."},{"id": 2709,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "A wide stance (feet apart side to side) primarily improves stability in which direction?","options": [{"key": "A","text": "Mediolateral direction"},{"key": "B","text": "Rotational direction only"},{"key": "C","text": "Anteroposterior direction"},{"key": "D","text": "Vertical direction"}],"correct": "A","explanation": "Widening the feet laterally increases the base of support side-to-side, enhancing mediolateral stability."},{"id": 2710,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The 'righting reactions' in balance control refer to:","options": [{"key": "A","text": "Voluntary movements to reach for objects"},{"key": "B","text": "Reactions occurring only in infants"},{"key": "C","text": "Automatic postural responses that restore the head and body to normal alignment"},{"key": "D","text": "Reflexes triggered only by visual stimuli"}],"correct": "C","explanation": "Righting reactions are automatic postural responses that maintain or restore normal head/body orientation in space."},{"id": 2711,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "'Equilibrium reactions' in postural control refer to:","options": [{"key": "A","text": "Static holding of a joint position"},{"key": "B","text": "Voluntary muscle contractions only"},{"key": "C","text": "Reflexes limited to the vestibular system alone"},{"key": "D","text": "Automatic responses that maintain balance when the center of gravity shifts beyond the base of support"}],"correct": "D","explanation": "Equilibrium reactions are automatic postural adjustments (ankle, hip, or stepping strategies) that restore balance when COG threatens to move outside BOS."},{"id": 2712,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The 'ankle strategy' for balance control is typically used in response to:","options": [{"key": "A","text": "Complete loss of the base of support"},{"key": "B","text": "Loss of vision only"},{"key": "C","text": "Large, fast perturbations"},{"key": "D","text": "Small perturbations, with the body acting like an inverted pendulum pivoting at the ankle"}],"correct": "D","explanation": "The ankle strategy is employed for small, slow postural sway, using ankle musculature to control body sway about a relatively fixed base."},{"id": 2713,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The 'hip strategy' for balance control is typically used in response to:","options": [{"key": "A","text": "Sitting balance only"},{"key": "B","text": "Very small, slow perturbations"},{"key": "C","text": "Standing perfectly still with eyes closed"},{"key": "D","text": "Larger or faster perturbations that exceed the capacity of the ankle strategy"}],"correct": "D","explanation": "The hip strategy involves flexion/extension at the hips to rapidly reposition the COG when perturbations are too large for ankle control alone."},{"id": 2714,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The 'stepping strategy' for balance control is used when:","options": [{"key": "A","text": "No perturbation exists at all"},{"key": "B","text": "The person is lying down"},{"key": "C","text": "The perturbation is very small"},{"key": "D","text": "The center of gravity moves beyond the base of support such that ankle and hip strategies are insufficient"}],"correct": "D","explanation": "Stepping strategy involves taking a step to enlarge/relocate the base of support when COG displacement exceeds the limits correctable by ankle or hip strategies."},{"id": 2715,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Postural sway refers to:","options": [{"key": "A","text": "The continuous, small oscillations of the body's center of gravity during quiet standing"},{"key": "B","text": "Complete loss of balance"},{"key": "C","text": "Only voluntary trunk movements"},{"key": "D","text": "The rigid, unchanging posture of the body"}],"correct": "A","explanation": "Postural sway describes the natural, small continuous fluctuations of COG that occur even during seemingly still standing."},{"id": 2716,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Closing the eyes during a standing balance test typically:","options": [{"key": "A","text": "Increases postural sway due to loss of visual input"},{"key": "B","text": "Improves balance due to reduced distraction"},{"key": "C","text": "Only affects seated balance"},{"key": "D","text": "Has no measurable effect"}],"correct": "A","explanation": "Removing visual input increases reliance on vestibular and somatosensory systems, generally increasing postural sway."},{"id": 2717,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The Romberg test assesses balance primarily by evaluating the contribution of which sensory system when vision is removed?","options": [{"key": "A","text": "Visual system"},{"key": "B","text": "Proprioceptive (somatosensory) and vestibular systems"},{"key": "C","text": "Auditory system"},{"key": "D","text": "Gustatory system"}],"correct": "B","explanation": "The Romberg test isolates proprioceptive and vestibular contributions to balance by eliminating visual input (eyes closed)."},{"id": 2718,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "Which three sensory systems primarily contribute to maintaining postural balance?","options": [{"key": "A","text": "Visual, vestibular, somatosensory (proprioceptive)"},{"key": "B","text": "Vestibular, gustatory, olfactory"},{"key": "C","text": "Visual, auditory, gustatory"},{"key": "D","text": "Olfactory, visual, auditory"}],"correct": "A","explanation": "Balance is maintained through integration of visual, vestibular, and somatosensory/proprioceptive information."},{"id": 2719,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The vestibular system primarily detects:","options": [{"key": "A","text": "Head position and movement relative to gravity and space"},{"key": "B","text": "Muscle length changes"},{"key": "C","text": "Visual contrast"},{"key": "D","text": "Joint angle changes only"}],"correct": "A","explanation": "The vestibular apparatus in the inner ear senses head position, linear/angular acceleration, and orientation relative to gravity."},{"id": 2720,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Proprioceptors that provide information about joint position and muscle length include:","options": [{"key": "A","text": "Rods and cones"},{"key": "B","text": "Semicircular canals"},{"key": "C","text": "Muscle spindles and Golgi tendon organs"},{"key": "D","text": "Otolith organs"}],"correct": "C","explanation": "Muscle spindles detect muscle length/stretch, and Golgi tendon organs detect tension, both contributing proprioceptive input for balance."},{"id": 2721,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "Stability is defined in biomechanics as the ability of a body to:","options": [{"key": "A","text": "Move quickly in any direction"},{"key": "B","text": "Maintain constant velocity only"},{"key": "C","text": "Generate maximum force"},{"key": "D","text": "Return to equilibrium or resist displacement after a disturbing force"}],"correct": "D","explanation": "Stability reflects resistance to a change in equilibrium state when subjected to a disturbing force."},{"id": 2722,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "Balance is best defined as:","options": [{"key": "A","text": "Maximum muscular strength"},{"key": "B","text": "The process of maintaining the center of gravity within the base of support (or controlling it during movement)"},{"key": "C","text": "The static position of the body only"},{"key": "D","text": "The location of the line of gravity only"}],"correct": "B","explanation": "Balance is the dynamic process by which the body maintains its COG within or controls it relative to the BOS during static or dynamic activities."},{"id": 2723,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "A high center of gravity combined with a narrow base of support results in:","options": [{"key": "A","text": "Decreased stability (more prone to toppling)"},{"key": "B","text": "Improved postural control automatically"},{"key": "C","text": "No change in balance requirements"},{"key": "D","text": "Increased stability"}],"correct": "A","explanation": "A high COG and narrow BOS reduce the stability margin, making the body more susceptible to loss of balance."},{"id": 2724,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Why do elderly individuals often adopt a wider stance and shorter stride during gait?","options": [{"key": "A","text": "To decrease energy expenditure only"},{"key": "B","text": "To compensate for reduced balance control by increasing the base of support"},{"key": "C","text": "Purely a habitual preference unrelated to biomechanics"},{"key": "D","text": "To increase speed"}],"correct": "B","explanation": "A wider stance increases BOS, providing a greater safety margin to compensate for age-related declines in balance and proprioception."},{"id": 2725,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The 'limits of stability' refer to:","options": [{"key": "A","text": "The maximum speed a person can walk"},{"key": "B","text": "The height of the center of gravity only"},{"key": "C","text": "The boundary within which the body can maintain balance without changing the base of support"},{"key": "D","text": "A fixed value identical for all individuals"}],"correct": "C","explanation": "Limits of stability describe the maximal distance in any direction a person can move their COG without losing balance or altering the BOS."},{"id": 2726,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following would decrease a person's stability the most?","options": [{"key": "A","text": "Bending the knees slightly"},{"key": "B","text": "Standing on a narrow beam with feet together"},{"key": "C","text": "Lowering the arms to the sides"},{"key": "D","text": "Standing with a wide stance"}],"correct": "B","explanation": "Standing on a narrow beam drastically reduces BOS width, significantly reducing stability compared to other options."},{"id": 2727,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During pregnancy, the line of gravity shifts due to increased abdominal mass, commonly resulting in compensatory:","options": [{"key": "A","text": "No postural change at all"},{"key": "B","text": "Increased lumbar lordosis to keep the LOG within the base of support"},{"key": "C","text": "Complete loss of the lumbar curve"},{"key": "D","text": "Increased thoracic kyphosis only"}],"correct": "B","explanation": "As the abdomen enlarges anteriorly, pregnant women often increase lumbar lordosis to shift COG posteriorly and keep LOG over the BOS."},{"id": 2728,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "In wheelchair users, stability of the wheelchair-user system depends on the combined center of gravity of the:","options": [{"key": "A","text": "Wheelchair and user combined as a system"},{"key": "B","text": "Wheelchair alone"},{"key": "C","text": "User alone"},{"key": "D","text": "Neither, stability is irrelevant"}],"correct": "A","explanation": "Wheelchair stability analysis must consider the combined COG of the user and wheelchair, since both contribute to the overall system's balance."},{"id": 2729,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A therapist teaching a patient to use a wide-based quad cane is primarily aiming to:","options": [{"key": "A","text": "Increase the base of support to enhance stability"},{"key": "B","text": "Increase center of gravity height"},{"key": "C","text": "Reduce proprioceptive input"},{"key": "D","text": "Decrease the base of support"}],"correct": "A","explanation": "Assistive devices such as quad canes are designed to enlarge the effective base of support, improving stability during ambulation."},{"id": 2730,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The concept of 'stability limits' becomes clinically important when assessing risk of:","options": [{"key": "A","text": "Cardiovascular fitness"},{"key": "B","text": "Falls in elderly or neurologically impaired patients"},{"key": "C","text": "Muscle hypertrophy"},{"key": "D","text": "Bone density loss only"}],"correct": "B","explanation": "Understanding a patient's limits of stability helps clinicians assess fall risk and design appropriate balance interventions."},{"id": 2731,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "When standing on one leg, the base of support is:","options": [{"key": "A","text": "The area under both feet"},{"key": "B","text": "The height of the pelvis"},{"key": "C","text": "The distance between both feet"},{"key": "D","text": "The area under the single stance foot only"}],"correct": "D","explanation": "In single-leg stance, BOS is confined to the contact area of the one supporting foot, considerably smaller than in double-leg stance."},{"id": 2732,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Tai Chi and similar balance training programs are believed to improve stability in older adults primarily by:","options": [{"key": "A","text": "Increasing center of gravity height"},{"key": "B","text": "Reducing muscle strength requirements"},{"key": "C","text": "Enhancing sensory integration, proprioception, and postural control strategies"},{"key": "D","text": "Increasing joint stiffness"}],"correct": "C","explanation": "Such programs train the sensory-motor systems (vestibular, visual, proprioceptive integration) and strengthen postural strategies, improving balance."},{"id": 2733,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why a tightrope walker often carries a long balancing pole?","options": [{"key": "A","text": "To lower and extend the effective base of support/moment of inertia, aiding balance control"},{"key": "B","text": "To increase walking speed"},{"key": "C","text": "To increase muscle strength"},{"key": "D","text": "To reduce visual distraction"}],"correct": "A","explanation": "The pole increases the moment of inertia about the rope and can be used to shift the combined COG, giving the walker more time and control to correct sway."},{"id": 2734,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "The term 'center of mass' (COM) differs from 'center of gravity' (COG) in that:","options": [{"key": "A","text": "COM is the balance point of mass distribution, while COG specifically factors in the direction of gravitational pull; in a uniform gravitational field they coincide"},{"key": "B","text": "COM changes with gravity while COG does not"},{"key": "C","text": "They are entirely unrelated concepts"},{"key": "D","text": "COG only applies to inanimate objects"}],"correct": "A","explanation": "COM and COG coincide under a uniform gravitational field, as is generally assumed on Earth's surface for biomechanical analysis; strictly, COG considers gravity's directional pull."},{"id": 2735,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "During single-limb stance in gait, the pelvis on the unsupported side tends to drop unless counteracted by which muscle group?","options": [{"key": "A","text": "Quadriceps"},{"key": "B","text": "Gastrocnemius"},{"key": "C","text": "Hamstrings"},{"key": "D","text": "Hip abductors (e.g., gluteus medius)"}],"correct": "D","explanation": "The hip abductors, especially gluteus medius, contract on the stance side to prevent contralateral pelvic drop and maintain balance (Trendelenburg mechanism)."},{"id": 2736,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "A positive Trendelenburg sign indicates weakness of which muscle on the stance leg side?","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Ankle plantarflexors"},{"key": "C","text": "Knee extensors"},{"key": "D","text": "Hip abductors (gluteus medius/minimus)"}],"correct": "D","explanation": "A positive Trendelenburg sign—contralateral pelvic drop during single-leg stance—reflects weakness of the ipsilateral hip abductors."},{"id": 2737,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Postural control strategies (ankle, hip, stepping) form a continuum typically organized based on:","options": [{"key": "A","text": "The size, speed, and direction of the postural perturbation"},{"key": "B","text": "Patient's age only"},{"key": "C","text": "Random selection"},{"key": "D","text": "Visual acuity only"}],"correct": "A","explanation": "The nervous system selects among ankle, hip, or stepping strategies based on the magnitude, velocity, and direction of the balance disturbance."},{"id": 2738,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following surfaces would make maintaining balance most challenging?","options": [{"key": "A","text": "Soft, compliant, unstable surface (e.g., foam pad)"},{"key": "B","text": "Carpeted stable floor"},{"key": "C","text": "Firm, flat, stationary floor"},{"key": "D","text": "Wide tiled floor"}],"correct": "A","explanation": "Compliant/unstable surfaces reduce reliable somatosensory feedback and challenge postural control more than firm, stable surfaces."},{"id": 2739,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "In static balance assessment, 'sway area' or 'sway path' measured by a force platform reflects:","options": [{"key": "A","text": "The size of the base of support only"},{"key": "B","text": "The magnitude and pattern of center of pressure movement during quiet standing"},{"key": "C","text": "Muscle strength directly"},{"key": "D","text": "Joint range of motion"}],"correct": "B","explanation": "Sway area/path quantifies excursions of the center of pressure (a proxy for COG control) recorded on a force platform during standing."},{"id": 2740,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Center of pressure (COP) is best described as:","options": [{"key": "A","text": "The point of application of the resultant ground reaction force on the supporting surface"},{"key": "B","text": "The highest point of the body"},{"key": "C","text": "A fixed anatomical marker"},{"key": "D","text": "The exact location of the center of gravity"}],"correct": "A","explanation": "COP represents the location where the net ground reaction force acts, continuously adjusting to control balance around the COG."},{"id": 2741,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The relationship between COG and COP during quiet standing is such that:","options": [{"key": "A","text": "They are always at the exact same point"},{"key": "B","text": "COG is always outside the base of support"},{"key": "C","text": "COP is unrelated to balance"},{"key": "D","text": "COP moves around COG's projection to keep it within the base of support"}],"correct": "D","explanation": "COP shifts continuously (often ahead of and around the COG's vertical projection) as the nervous system makes small corrections to keep COG controlled within the BOS."},{"id": 2742,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "A below-knee amputee using a prosthesis may show altered center of gravity control mainly due to:","options": [{"key": "A","text": "Increased proprioceptive feedback from the prosthetic foot"},{"key": "B","text": "Only visual changes are relevant"},{"key": "C","text": "No change occurs with a well-fitted prosthesis"},{"key": "D","text": "Loss of sensory feedback and altered limb mass distribution on the prosthetic side"}],"correct": "D","explanation": "Amputation alters limb mass distribution and removes normal sensory feedback from the missing segment, both affecting COG control and balance strategies."},{"id": 2743,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "Which factor is LEAST likely to influence an individual's overall stability?","options": [{"key": "A","text": "Eye color"},{"key": "B","text": "Size and shape of base of support"},{"key": "C","text": "Height of center of gravity"},{"key": "D","text": "Body weight"}],"correct": "A","explanation": "Eye color has no biomechanical relevance to stability; COG height, BOS, and body mass are all recognized determinants of stability."},{"id": 2744,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Functional reach test is used clinically to assess:","options": [{"key": "A","text": "Cardiovascular endurance"},{"key": "B","text": "Range of motion of the shoulder only"},{"key": "C","text": "Muscle strength of the upper limb"},{"key": "D","text": "Dynamic balance by measuring the maximal distance a person can reach forward without losing balance or stepping"}],"correct": "D","explanation": "The Functional Reach Test measures the anterior limit of stability by having the patient reach forward as far as possible while maintaining a fixed base of support."},{"id": 2745,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Newton's First Law of Motion is also known as the:","options": [{"key": "A","text": "Law of gravitation"},{"key": "B","text": "Law of acceleration"},{"key": "C","text": "Law of action-reaction"},{"key": "D","text": "Law of inertia"}],"correct": "D","explanation": "Newton's First Law states a body remains at rest or in uniform motion unless acted upon by an external force, hence 'law of inertia'."},{"id": 2746,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Inertia is best defined as:","options": [{"key": "A","text": "The tendency of a body to resist a change in its state of motion"},{"key": "B","text": "The energy possessed by a moving body"},{"key": "C","text": "The force causing motion"},{"key": "D","text": "The rate of change of velocity"}],"correct": "A","explanation": "Inertia is the inherent property of matter that resists changes to its existing state of rest or motion."},{"id": 2747,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The magnitude of inertia a body possesses is directly related to its:","options": [{"key": "A","text": "Displacement"},{"key": "B","text": "Acceleration"},{"key": "C","text": "Velocity"},{"key": "D","text": "Mass"}],"correct": "D","explanation": "Greater mass means greater inertia, i.e., greater resistance to a change in motion."},{"id": 2748,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A passenger lurching forward when a bus suddenly stops illustrates:","options": [{"key": "A","text": "Newton's Second Law"},{"key": "B","text": "Newton's Third Law"},{"key": "C","text": "Newton's First Law (inertia)"},{"key": "D","text": "The law of conservation of energy"}],"correct": "C","explanation": "The passenger's body tends to continue moving forward due to inertia even though the bus has stopped, illustrating Newton's First Law."},{"id": 2749,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Easy","question": "Newton's Second Law of Motion states that acceleration of a body is:","options": [{"key": "A","text": "Directly proportional to net force and inversely proportional to mass"},{"key": "B","text": "Inversely proportional to force and directly proportional to mass"},{"key": "C","text": "Independent of both force and mass"},{"key": "D","text": "Always constant regardless of force"}],"correct": "A","explanation": "Newton's Second Law: a = F/m, meaning acceleration increases with force and decreases with increasing mass."},{"id": 2750,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The mathematical expression of Newton's Second Law is:","options": [{"key": "A","text": "F = ma"},{"key": "B","text": "F = mv"},{"key": "C","text": "F = m/a"},{"key": "D","text": "F = a/m"}],"correct": "A","explanation": "Force equals mass multiplied by acceleration (F = ma) is the standard expression of the Second Law."},{"id": 2751,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "If the same force is applied to two objects of different mass, the object with greater mass will experience:","options": [{"key": "A","text": "Lesser acceleration"},{"key": "B","text": "Zero acceleration"},{"key": "C","text": "Greater acceleration"},{"key": "D","text": "The same acceleration"}],"correct": "A","explanation": "Since acceleration = Force/mass, a larger mass results in smaller acceleration for the same applied force."},{"id": 2752,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Newton's Third Law of Motion states that:","options": [{"key": "A","text": "Every action has an equal and opposite reaction"},{"key": "B","text": "Force equals mass times acceleration"},{"key": "C","text": "Momentum is conserved only in collisions"},{"key": "D","text": "A body at rest remains at rest"}],"correct": "A","explanation": "Newton's Third Law states that for every action force, there is an equal and opposite reaction force."},{"id": 2753,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "During walking, the foot pushes backward against the ground; by Newton's Third Law, the ground pushes:","options": [{"key": "A","text": "Forward on the foot (propelling the body ahead)"},{"key": "B","text": "In the same direction as the foot's push"},{"key": "C","text": "Downward only"},{"key": "D","text": "Nowhere, as no reaction occurs"}],"correct": "A","explanation": "The ground reaction force acts forward (and upward) on the foot in reaction to the backward push, propelling the body forward during gait."},{"id": 2754,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of Newton's laws best explains why a swimmer pushes water backward to move forward?","options": [{"key": "A","text": "First Law"},{"key": "B","text": "Third Law"},{"key": "C","text": "Law of conservation of energy"},{"key": "D","text": "Second Law"}],"correct": "B","explanation": "The swimmer pushes water backward (action); the water pushes the swimmer forward (reaction), illustrating the Third Law."},{"id": 2755,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A rocket propels forward by expelling gas backward, which is a direct application of:","options": [{"key": "A","text": "The law of friction"},{"key": "B","text": "Newton's First Law"},{"key": "C","text": "Newton's Third Law"},{"key": "D","text": "Newton's Second Law only"}],"correct": "C","explanation": "Expelling gas backward (action) generates an equal, opposite forward reaction force propelling the rocket, per Newton's Third Law."},{"id": 2756,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A patient in a wheelchair pushing on the wheel rims to propel forward is applying which of Newton's laws?","options": [{"key": "A","text": "Second Law only"},{"key": "B","text": "None of the laws apply"},{"key": "C","text": "First Law only"},{"key": "D","text": "Third Law (reaction force from wheel/ground propels the chair)"}],"correct": "D","explanation": "The backward push on the rim/ground generates an equal, forward reaction force that propels the wheelchair, per Newton's Third Law."},{"id": 2757,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "According to Newton's First Law, a ball rolling on a frictionless, level surface would:","options": [{"key": "A","text": "Slow down and stop eventually"},{"key": "B","text": "Reverse its direction"},{"key": "C","text": "Continue moving at constant velocity indefinitely"},{"key": "D","text": "Accelerate spontaneously"}],"correct": "C","explanation": "In the idealized absence of friction or other forces, a moving body continues at constant velocity, per the law of inertia."},{"id": 2758,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A heavier patient requires greater muscular force to achieve the same acceleration during a sit-to-stand transfer compared to a lighter patient. This is best explained by:","options": [{"key": "A","text": "Newton's Third Law"},{"key": "B","text": "The concept of friction only"},{"key": "C","text": "Newton's Second Law (F = ma)"},{"key": "D","text": "The law of conservation of momentum"}],"correct": "C","explanation": "Since greater mass requires greater force for the same acceleration (F = ma), heavier patients need more muscular force for equivalent movement speed."},{"id": 2759,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Newton's law of gravitation states that every object attracts every other object with a force that is:","options": [{"key": "A","text": "Independent of mass and distance"},{"key": "B","text": "Directly proportional to the product of their masses and inversely proportional to the square of the distance between them"},{"key": "C","text": "Inversely proportional to their masses"},{"key": "D","text": "Only relevant to planetary bodies"}],"correct": "B","explanation": "Newton's law of universal gravitation: F = G(m1m2)/r², where force increases with mass and decreases with the square of distance."},{"id": 2760,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best illustrates Newton's First Law in a clinical context?","options": [{"key": "A","text": "Two muscles contracting simultaneously"},{"key": "B","text": "A patient with paralysis unable to initiate movement, remaining still until an external force (e.g., therapist assistance) is applied"},{"key": "C","text": "A joint reaction force during walking"},{"key": "D","text": "A muscle contracting to lift a weight"}],"correct": "B","explanation": "A paralyzed limb remains motionless (state of inertia) until acted upon by an external force, directly reflecting Newton's First Law."},{"id": 2761,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "A therapist applying a quick stretch to facilitate a muscle contraction (as in PNF techniques) relies on principles related to:","options": [{"key": "A","text": "Constant velocity motion"},{"key": "B","text": "Newton's Third Law only"},{"key": "C","text": "Zero net force conditions"},{"key": "D","text": "Overcoming inertia to initiate a change in the muscle's resting state"}],"correct": "D","explanation": "A quick stretch helps overcome the muscle/limb's inertia (resistance to change in state), facilitating a more effective contraction response."},{"id": 2762,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "If a 10 kg object experiences a net force of 20 N, its acceleration will be:","options": [{"key": "A","text": "20 m/s²"},{"key": "B","text": "0.5 m/s²"},{"key": "C","text": "200 m/s²"},{"key": "D","text": "2 m/s²"}],"correct": "D","explanation": "Using a = F/m = 20 N / 10 kg = 2 m/s²."},{"id": 2763,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "A net force of 50 N produces an acceleration of 5 m/s² in an object. The mass of the object is:","options": [{"key": "A","text": "250 kg"},{"key": "B","text": "10 kg"},{"key": "C","text": "25 kg"},{"key": "D","text": "5 kg"}],"correct": "B","explanation": "Mass = Force/Acceleration = 50/5 = 10 kg."},{"id": 2764,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Friction between two surfaces primarily arises due to:","options": [{"key": "A","text": "Microscopic irregularities and molecular adhesion between contacting surfaces"},{"key": "B","text": "Air resistance"},{"key": "C","text": "Magnetic forces"},{"key": "D","text": "Gravitational pull between the surfaces"}],"correct": "A","explanation": "Friction results from interlocking surface irregularities and molecular-level adhesion between the two contacting materials."},{"id": 2765,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Rolling friction is generally __________ compared to sliding friction between the same surfaces.","options": [{"key": "A","text": "Unrelated to"},{"key": "B","text": "Less than"},{"key": "C","text": "Greater than"},{"key": "D","text": "Equal to"}],"correct": "B","explanation": "Rolling friction is typically much less than sliding friction, which is why wheels/rollers reduce resistance compared to dragging."},{"id": 2766,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In prosthetic and orthotic devices, reducing friction at articulating joints is important primarily to:","options": [{"key": "A","text": "Increase noise during movement"},{"key": "B","text": "Reduce wear and improve smoothness/efficiency of movement"},{"key": "C","text": "Decrease the device's lifespan"},{"key": "D","text": "Increase resistance for muscle strengthening"}],"correct": "B","explanation": "Reduced friction at prosthetic/orthotic joints minimizes wear, energy loss, and promotes smoother, more natural movement."},{"id": 2767,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "Which factor does NOT influence the frictional force between two surfaces?","options": [{"key": "A","text": "Coefficient of friction"},{"key": "B","text": "Surface area of contact (in most classical friction models)"},{"key": "C","text": "Normal reaction force"},{"key": "D","text": "Nature of the contacting surfaces (roughness)"}],"correct": "B","explanation": "Classical (Coulomb) friction theory considers friction largely independent of the apparent contact area; it depends on normal force and coefficient of friction."},{"id": 2768,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A physiotherapist applying talcum powder to a treatment table before a sliding transfer technique aims to:","options": [{"key": "A","text": "Increase the coefficient of friction"},{"key": "B","text": "Increase friction for safety"},{"key": "C","text": "Have no biomechanical effect"},{"key": "D","text": "Decrease friction to ease the sliding motion"}],"correct": "D","explanation": "Talcum powder reduces the coefficient of friction between skin/sheet and the table surface, easing sliding transfers."},{"id": 2769,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Anti-slip mats used under wheelchairs or walking aids function by:","options": [{"key": "A","text": "Increasing the coefficient of friction to prevent slipping"},{"key": "B","text": "Eliminating normal force"},{"key": "C","text": "Reducing the coefficient of friction"},{"key": "D","text": "Increasing body weight"}],"correct": "A","explanation": "Anti-slip surfaces increase friction (higher coefficient of friction) between the device and floor, reducing slipping risk."},{"id": 2770,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Work done against friction during movement is converted primarily into:","options": [{"key": "A","text": "Electrical energy"},{"key": "B","text": "Kinetic energy gain"},{"key": "C","text": "Heat energy"},{"key": "D","text": "Potential energy"}],"correct": "C","explanation": "Frictional work is dissipated mainly as heat energy at the interacting surfaces, representing an energy loss from the mechanical system."},{"id": 2771,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "If a force is applied to an object but no displacement occurs (e.g., pushing against an immovable wall), the mechanical work done is:","options": [{"key": "A","text": "Maximum"},{"key": "B","text": "Dependent on time only"},{"key": "C","text": "Zero"},{"key": "D","text": "Equal to the applied force"}],"correct": "C","explanation": "Since work requires displacement in the direction of force, no displacement means zero mechanical work is performed, regardless of effort exerted."},{"id": 2772,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Positive work is done on an object when the force and displacement are:","options": [{"key": "A","text": "Perpendicular to each other"},{"key": "B","text": "Both zero"},{"key": "C","text": "In the same direction (or have a component in the same direction)"},{"key": "D","text": "In opposite directions"}],"correct": "C","explanation": "Positive work occurs when the force has a component acting in the same direction as the resulting displacement."},{"id": 2773,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Negative work is done when the force and displacement are:","options": [{"key": "A","text": "Perpendicular"},{"key": "B","text": "Equal in magnitude"},{"key": "C","text": "In opposite directions (e.g., eccentric muscle contraction controlling a descending load)"},{"key": "D","text": "In the same direction"}],"correct": "C","explanation": "Negative work occurs when force opposes the direction of displacement, as during eccentric contractions controlling a lowering movement."},{"id": 2774,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "An eccentric muscle contraction while lowering a weight in a controlled manner is an example of:","options": [{"key": "A","text": "Negative work by the muscle"},{"key": "B","text": "Isometric work only"},{"key": "C","text": "Positive work by the muscle"},{"key": "D","text": "Zero work performed"}],"correct": "A","explanation": "During eccentric contraction, the muscle force acts opposite to the direction of movement (the load is descending), representing negative work by the muscle."},{"id": 2775,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which activity involves zero mechanical work despite muscular effort being expended?","options": [{"key": "A","text": "Walking up a ramp"},{"key": "B","text": "Lifting a box from the floor to a shelf"},{"key": "C","text": "Pushing a cart across a room"},{"key": "D","text": "Isometric holding of a weight in a fixed position"}],"correct": "D","explanation": "Since isometric contraction produces force without any displacement of the load, no mechanical work is done, even though metabolic energy is consumed."},{"id": 2776,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The area under a force-displacement graph represents:","options": [{"key": "A","text": "Velocity"},{"key": "B","text": "Work done"},{"key": "C","text": "Momentum"},{"key": "D","text": "Power"}],"correct": "B","explanation": "The integral of force over displacement (area under the F-d curve) equals the total mechanical work done."},{"id": 2777,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Elastic (strain) potential energy is stored in structures such as:","options": [{"key": "A","text": "Cartilage during static loading only"},{"key": "B","text": "Tendons and ligaments when stretched"},{"key": "C","text": "Muscles during isometric contraction only"},{"key": "D","text": "Bone under compression only"}],"correct": "B","explanation": "Elastic potential energy is stored in deformable tissues like tendons and ligaments when they are stretched, later released during recoil (e.g., stretch-shortening cycle)."},{"id": 2778,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "The stretch-shortening cycle in muscle-tendon units utilizes which type of energy to enhance subsequent concentric contraction?","options": [{"key": "A","text": "Stored elastic potential energy from the preceding eccentric phase"},{"key": "B","text": "Electrical energy"},{"key": "C","text": "Heat energy"},{"key": "D","text": "Chemical energy only"}],"correct": "A","explanation": "In the stretch-shortening cycle, elastic energy stored during rapid eccentric loading is released to augment the force/power of the following concentric contraction."},{"id": 2779,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A pendulum at its highest point of swing has:","options": [{"key": "A","text": "Zero total mechanical energy"},{"key": "B","text": "Equal kinetic and potential energy"},{"key": "C","text": "Maximum potential energy and minimum (zero) kinetic energy"},{"key": "D","text": "Maximum kinetic energy and minimum potential energy"}],"correct": "C","explanation": "At the highest point, the pendulum momentarily stops (zero velocity, zero KE), while height is maximal, giving maximum PE."},{"id": 2780,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "During normal gait, the body's center of gravity exchanges energy between kinetic and potential forms in a manner similar to:","options": [{"key": "A","text": "A rigid lever system only"},{"key": "B","text": "Pure translational motion with no energy exchange"},{"key": "C","text": "An inverted pendulum mechanism"},{"key": "D","text": "Random energy dissipation with no pattern"}],"correct": "C","explanation": "The body's COG during stance phase behaves like an inverted pendulum, exchanging kinetic and potential energy to conserve mechanical energy and reduce metabolic cost."},{"id": 2781,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Power output is highest when a given amount of work is performed:","options": [{"key": "A","text": "Over a shorter period of time"},{"key": "B","text": "At a constant, slow rate"},{"key": "C","text": "Over a longer period of time"},{"key": "D","text": "Only during isometric contraction"}],"correct": "A","explanation": "Since Power = Work/Time, completing the same work in less time yields higher power output."},{"id": 2782,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following activities would demonstrate the highest power output?","options": [{"key": "A","text": "Explosive vertical jump performed in under 1 second"},{"key": "B","text": "Slow, controlled squat over 10 seconds"},{"key": "C","text": "Slow walking on a treadmill"},{"key": "D","text": "Static wall sit for 30 seconds"}],"correct": "A","explanation": "An explosive jump involves large force and displacement completed in very little time, yielding high power output compared to slower activities."},{"id": 2783,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A weightlifter performing a rapid clean-and-jerk versus a slow deadlift with the same load and displacement demonstrates:","options": [{"key": "A","text": "No relationship between speed and power"},{"key": "B","text": "Equal power output in both lifts"},{"key": "C","text": "Greater power output in the faster lift"},{"key": "D","text": "Equal work but greater power in the slower lift"}],"correct": "C","explanation": "Since work may be similar but time is shorter in the faster lift, power output (work/time) is greater in the explosive lift."},{"id": 2784,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "1 horsepower is approximately equal to how many watts?","options": [{"key": "A","text": "7460 W"},{"key": "B","text": "746 W"},{"key": "C","text": "373 W"},{"key": "D","text": "74.6 W"}],"correct": "B","explanation": "1 horsepower (mechanical) is approximately equal to 746 watts."},{"id": 2785,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Linear momentum is a __________ quantity.","options": [{"key": "A","text": "Vector"},{"key": "B","text": "Dimensionless"},{"key": "C","text": "Neither scalar nor vector"},{"key": "D","text": "Scalar"}],"correct": "A","explanation": "Momentum (mass × velocity) has both magnitude and direction, making it a vector quantity."},{"id": 2786,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The law of conservation of momentum states that in the absence of external forces, the total momentum of a system:","options": [{"key": "A","text": "Becomes zero"},{"key": "B","text": "Remains constant"},{"key": "C","text": "Decreases over time"},{"key": "D","text": "Increases over time"}],"correct": "B","explanation": "Total momentum of an isolated system (no external forces) remains constant before and after any interaction, such as a collision."},{"id": 2787,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In an elastic collision, which of the following is conserved?","options": [{"key": "A","text": "Only momentum"},{"key": "B","text": "Neither momentum nor kinetic energy"},{"key": "C","text": "Only kinetic energy"},{"key": "D","text": "Both momentum and kinetic energy"}],"correct": "D","explanation": "Elastic collisions conserve both total momentum and total kinetic energy of the system."},{"id": 2788,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In an inelastic collision, which of the following is generally NOT conserved?","options": [{"key": "A","text": "Total momentum"},{"key": "B","text": "Mass"},{"key": "C","text": "Total kinetic energy (some is converted to heat/deformation)"},{"key": "D","text": "Total energy overall"}],"correct": "C","explanation": "In inelastic collisions, momentum is conserved, but kinetic energy is not, as some converts to heat, sound, or deformation."},{"id": 2789,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Impulse is defined as the product of:","options": [{"key": "A","text": "Force and the time over which it acts"},{"key": "B","text": "Mass and velocity"},{"key": "C","text": "Mass and acceleration"},{"key": "D","text": "Force and displacement"}],"correct": "A","explanation": "Impulse = Force × time, and it equals the resulting change in momentum of a body."},{"id": 2790,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Bending the knees when landing from a jump helps reduce injury risk primarily by:","options": [{"key": "A","text": "Increasing body mass momentarily"},{"key": "B","text": "Decreasing the time of impact, thus increasing peak force"},{"key": "C","text": "Eliminating momentum entirely"},{"key": "D","text": "Increasing the time over which momentum changes to zero, thus reducing peak impact force"}],"correct": "D","explanation": "Flexing the knees during landing prolongs the deceleration time, which reduces the peak force needed to bring the body's momentum to zero (impulse-momentum relationship)."},{"id": 2791,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Padded flooring in a gym or fall-prevention setting reduces injury by:","options": [{"key": "A","text": "Increasing the impact force"},{"key": "B","text": "Increasing the time of impact, thereby decreasing peak force for a given change in momentum"},{"key": "C","text": "Increasing body momentum"},{"key": "D","text": "Decreasing the coefficient of friction only"}],"correct": "B","explanation": "Cushioned surfaces extend the duration of impact, reducing the peak force experienced for the same momentum change, per the impulse-momentum relationship."},{"id": 2792,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A football player being tackled experiences less injury risk if the tackle:","options": [{"key": "A","text": "Increases the peak force applied"},{"key": "B","text": "Occurs very abruptly with minimal follow-through"},{"key": "C","text": "Involves 'rolling with the impact' to extend the duration of force application"},{"key": "D","text": "Has no relation to time of impact"}],"correct": "C","explanation": "Extending the duration over which the impact force is applied (as in rolling with a fall/tackle) reduces peak force for a given momentum change."},{"id": 2793,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Angular impulse equals the change in:","options": [{"key": "A","text": "Angular momentum"},{"key": "B","text": "Linear velocity"},{"key": "C","text": "Kinetic energy"},{"key": "D","text": "Linear momentum"}],"correct": "A","explanation": "Angular impulse (torque × time) produces a corresponding change in angular momentum, the rotational analogue of the impulse-momentum relationship."},{"id": 2794,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "A figure skater pulling in their arms during a spin increases their angular velocity due to:","options": [{"key": "A","text": "Loss of angular momentum"},{"key": "B","text": "Increased friction with the ice"},{"key": "C","text": "Conservation of angular momentum with decreased moment of inertia"},{"key": "D","text": "Increased moment of inertia"}],"correct": "C","explanation": "As the skater reduces their moment of inertia by pulling in the limbs, angular momentum is conserved, so angular velocity increases correspondingly."},{"id": 2795,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "In diving or gymnastics, tucking the body during a somersault primarily serves to:","options": [{"key": "A","text": "Decrease moment of inertia, thereby increasing angular velocity for faster rotation"},{"key": "B","text": "Increase moment of inertia and slow rotation"},{"key": "C","text": "Increase air resistance for control"},{"key": "D","text": "Eliminate angular momentum"}],"correct": "A","explanation": "Tucking reduces the body's moment of inertia about the rotation axis, and by conservation of angular momentum, angular velocity increases, allowing faster somersaults."},{"id": 2796,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of Newton's laws directly underlies the impulse-momentum relationship?","options": [{"key": "A","text": "Third Law"},{"key": "B","text": "First Law"},{"key": "C","text": "Second Law (expressed in terms of momentum change)"},{"key": "D","text": "Law of gravitation"}],"correct": "C","explanation": "Newton's Second Law, when expressed as F = Δ(mv)/Δt, directly gives rise to the impulse-momentum relationship."},{"id": 2797,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "A therapist using a slow, sustained stretch rather than a fast, ballistic stretch to elongate a tight muscle is applying the principle that:","options": [{"key": "A","text": "Momentum change is unaffected by speed"},{"key": "B","text": "Slower movement reduces momentum and associated forces, minimizing risk of tissue injury"},{"key": "C","text": "Fast stretching always improves flexibility better"},{"key": "D","text": "Momentum has no relevance to stretching technique"}],"correct": "B","explanation": "Slower stretching minimizes momentum and the resultant forces on tissue, reducing the risk of micro-trauma compared to fast, ballistic stretching."},{"id": 2798,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Static friction coefficient is generally __________ kinetic friction coefficient for the same pair of surfaces.","options": [{"key": "A","text": "Always exactly equal to"},{"key": "B","text": "Unrelated to"},{"key": "C","text": "Greater than or equal to"},{"key": "D","text": "Less than or equal to"}],"correct": "C","explanation": "Static friction coefficient is typically greater than or equal to kinetic friction coefficient, meaning more force is needed to start motion than to sustain it."},{"id": 2799,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which scenario best demonstrates conservation of mechanical energy (assuming negligible friction)?","options": [{"key": "A","text": "A block sliding to rest on a rough surface"},{"key": "B","text": "A car braking to a stop"},{"key": "C","text": "A ball rolling to a stop on a carpeted floor"},{"key": "D","text": "A pendulum swinging back and forth, converting kinetic and potential energy without loss"}],"correct": "D","explanation": "In an idealized frictionless pendulum, total mechanical energy (KE+PE) is conserved as it interchanges forms during the swing."},{"id": 2800,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The work-energy theorem states that the net work done on an object equals:","options": [{"key": "A","text": "Its total momentum"},{"key": "B","text": "Its total power output"},{"key": "C","text": "Its change in potential energy"},{"key": "D","text": "Its change in kinetic energy"}],"correct": "D","explanation": "The work-energy theorem states that net work done on a body equals the resulting change in its kinetic energy."},{"id": 2801,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "If a physiotherapy exercise increases a limb's velocity from rest to a certain speed, the work done by the muscle equals:","options": [{"key": "A","text": "The frictional force only"},{"key": "B","text": "Zero, since muscles cannot do work"},{"key": "C","text": "The kinetic energy gained by the limb (assuming no other losses)"},{"key": "D","text": "The final potential energy of the limb"}],"correct": "C","explanation": "Per the work-energy theorem, the work done by the muscle converts to the kinetic energy gained by the moving limb (ignoring losses like friction/heat)."},{"id": 2802,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Metabolic energy expenditure during isometric exercise, despite zero mechanical work being done, occurs because:","options": [{"key": "A","text": "There is no metabolic cost during isometric holds"},{"key": "B","text": "Muscles perform mechanical work internally that is not externally visible"},{"key": "C","text": "Isometric contraction requires no ATP"},{"key": "D","text": "The body still expends chemical (metabolic) energy for cross-bridge cycling and force maintenance, even without external displacement"}],"correct": "D","explanation": "Even without external mechanical work, muscle fibers continuously expend metabolic energy (ATP) to sustain cross-bridge cycling and force production during isometric contraction."},{"id": 2803,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "A 5 kg object moving at 4 m/s has a linear momentum of:","options": [{"key": "A","text": "20 kg·m/s"},{"key": "B","text": "9 kg·m/s"},{"key": "C","text": "45 kg·m/s"},{"key": "D","text": "1.25 kg·m/s"}],"correct": "A","explanation": "Momentum = mass × velocity = 5 kg × 4 m/s = 20 kg·m/s."},{"id": 2804,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "A force of 30 N acts on an object for 2 seconds. The impulse delivered is:","options": [{"key": "A","text": "32 N·s"},{"key": "B","text": "60 N·s"},{"key": "C","text": "15 N·s"},{"key": "D","text": "900 N·s"}],"correct": "B","explanation": "Impulse = Force × time = 30 N × 2 s = 60 N·s."},{"id": 2805,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "If 200 J of work is done in 4 seconds, the power output is:","options": [{"key": "A","text": "196 W"},{"key": "B","text": "50 W"},{"key": "C","text": "800 W"},{"key": "D","text": "204 W"}],"correct": "B","explanation": "Power = Work/Time = 200 J / 4 s = 50 W."},{"id": 2806,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "A 2 kg object moving at 3 m/s has kinetic energy of:","options": [{"key": "A","text": "6 J"},{"key": "B","text": "3 J"},{"key": "C","text": "9 J"},{"key": "D","text": "18 J"}],"correct": "C","explanation": "KE = ½mv² = ½ × 2 × 3² = ½ × 2 × 9 = 9 J."},{"id": 2807,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "An object of mass 10 kg is raised to a height of 2 m. Taking g = 9.8 m/s², its gravitational potential energy is approximately:","options": [{"key": "A","text": "196 J"},{"key": "B","text": "19.6 J"},{"key": "C","text": "20 J"},{"key": "D","text": "98 J"}],"correct": "A","explanation": "PE = mgh = 10 × 9.8 × 2 = 196 J."},{"id": 2808,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A physiotherapist explaining to a patient why it is harder to start pushing a loaded wheelchair than to keep it moving is describing the difference between:","options": [{"key": "A","text": "Torque and force"},{"key": "B","text": "Mass and weight"},{"key": "C","text": "Static friction and kinetic friction"},{"key": "D","text": "Kinetic and potential energy"}],"correct": "C","explanation": "Static friction (resisting the start of motion) is generally greater than kinetic friction (resisting motion once moving), explaining why starting is harder than sustaining motion."},{"id": 2809,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "When a physiotherapist applies resistance manually and gradually increases the speed of a limb's movement against that resistance, keeping force constant, they are increasing:","options": [{"key": "A","text": "The coefficient of friction"},{"key": "B","text": "Torque only"},{"key": "C","text": "Mechanical power (since power = force × velocity)"},{"key": "D","text": "Momentum only, with no change in power"}],"correct": "C","explanation": "Since Power = Force × velocity (for constant force), increasing movement speed while maintaining resistance force increases the mechanical power generated."},{"id": 2810,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "An external force acting on a system in the direction opposite to its motion will:","options": [{"key": "A","text": "Only affect potential energy"},{"key": "B","text": "Have no effect on momentum"},{"key": "C","text": "Increase the system's momentum"},{"key": "D","text": "Decrease the system's momentum (decelerate it)"}],"correct": "D","explanation": "A force opposing motion produces a negative impulse, thereby decreasing the momentum (decelerating) the system over time."},{"id": 2811,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why it is easier to push a patient's wheelchair on a smooth tiled floor compared to a thick carpeted floor?","options": [{"key": "A","text": "Tiled floors increase the wheelchair's momentum automatically"},{"key": "B","text": "Carpeted floors have zero friction"},{"key": "C","text": "There is no difference between the two surfaces"},{"key": "D","text": "Tiled floors have a lower coefficient of friction, requiring less force to overcome resistance"}],"correct": "D","explanation": "Smooth tile has a lower coefficient of friction than carpet, reducing the frictional force that must be overcome to move the wheelchair."},{"id": 2812,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "In manual therapy, applying a sudden high-velocity, low-amplitude thrust technique relies on generating a large force over a very short time, which corresponds to a:","options": [{"key": "A","text": "Effective impulse achieved through high force despite very brief contact time"},{"key": "B","text": "Purely frictional technique"},{"key": "C","text": "Large impulse with long duration"},{"key": "D","text": "Zero impulse technique"}],"correct": "A","explanation": "HVLA thrust techniques achieve an effective mechanical impulse (force × brief time) sufficient to produce the intended joint effect despite the short duration of force application."},{"id": 2813,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A ball dropped from a height bounces to a lower height each time due to:","options": [{"key": "A","text": "Newton's First Law alone"},{"key": "B","text": "Energy losses (mostly as heat and sound) during each inelastic collision with the ground"},{"key": "C","text": "Gain of energy with each bounce"},{"key": "D","text": "Increase in momentum with each bounce"}],"correct": "B","explanation": "Each bounce is an inelastic collision where some kinetic energy converts to heat and sound, so the ball never regains its original height."},{"id": 2814,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Which best explains why a physiotherapist recommends a gradual increase in walking speed for a deconditioned cardiac patient rather than an abrupt fast pace?","options": [{"key": "A","text": "To decrease patient's body weight"},{"key": "B","text": "To avoid a sudden spike in required force and cardiovascular/metabolic demand associated with rapid acceleration and higher power output"},{"key": "C","text": "To eliminate all frictional forces during walking"},{"key": "D","text": "To maximize momentum immediately"}],"correct": "B","explanation": "Gradual increases in speed avoid sudden high force/power demands (and associated cardiovascular strain) linked with rapid acceleration, consistent with F=ma and power=work/time principles."},{"id": 2815,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Arthrokinematics refers to the study of:","options": [{"key": "A","text": "Muscle contraction mechanics"},{"key": "B","text": "Nerve conduction across joints"},{"key": "C","text": "Gross movement of body segments"},{"key": "D","text": "Motion occurring between joint articulating surfaces"}],"correct": "D","explanation": "Arthrokinematics describes the small accessory movements (roll, slide, spin) that occur between the actual articulating joint surfaces."},{"id": 2816,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The three basic types of arthrokinematic motion are:","options": [{"key": "A","text": "Roll, slide (glide), and spin"},{"key": "B","text": "Concave, convex, and neutral"},{"key": "C","text": "Flexion, extension, rotation"},{"key": "D","text": "Abduction, adduction, circumduction"}],"correct": "A","explanation": "Arthrokinematic motion at joint surfaces occurs as roll, slide/glide, and spin, either singly or in combination."},{"id": 2817,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Roll' in arthrokinematics is defined as:","options": [{"key": "A","text": "A single point on one surface contacting multiple points on another"},{"key": "B","text": "Multiple points on one surface contacting multiple points on another surface at successive intervals"},{"key": "C","text": "Rotation of a bone about a stationary mechanical axis"},{"key": "D","text": "A translatory glide only"}],"correct": "B","explanation": "Rolling occurs when new points on one articular surface meet new points on the opposing surface, similar to a tire rolling on the ground."},{"id": 2818,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Slide' (glide) in arthrokinematics is defined as:","options": [{"key": "A","text": "Multiple points on both surfaces contacting each other simultaneously and sequentially"},{"key": "B","text": "A pure rotation without translation"},{"key": "C","text": "A single point on one surface contacting a series of new points on the opposing surface"},{"key": "D","text": "A change in joint shape"}],"correct": "C","explanation": "During sliding, one point on a surface contacts a changing series of points on the opposing surface, similar to a tire skidding."},{"id": 2819,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Spin' in arthrokinematics refers to:","options": [{"key": "A","text": "Rotation of a bone around a stationary mechanical axis, similar to a spinning top"},{"key": "B","text": "Motion occurring only at hinge joints"},{"key": "C","text": "A combination of roll and slide only"},{"key": "D","text": "Translation of a bone along a joint surface"}],"correct": "A","explanation": "Spin involves a bone rotating about its own longitudinal mechanical axis while remaining relatively fixed at one point of contact, like a top spinning in place."},{"id": 2820,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "An example of pure spin arthrokinematics in the body is:","options": [{"key": "A","text": "Knee flexion"},{"key": "B","text": "Shoulder abduction"},{"key": "C","text": "Hip flexion"},{"key": "D","text": "Radial head rotation during forearm pronation/supination"}],"correct": "D","explanation": "During pronation/supination, the radial head spins on the capitulum of the humerus around its own longitudinal axis, a classic example of pure spin."},{"id": 2821,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The concave-convex rule describes the relationship between:","options": [{"key": "A","text": "Ligament laxity and capsular pattern"},{"key": "B","text": "Muscle length and joint angle"},{"key": "C","text": "The direction of roll and slide of joint surfaces based on whether the moving surface is concave or convex"},{"key": "D","text": "Bone density and joint stability"}],"correct": "C","explanation": "The concave-convex rule predicts whether roll and glide occur in the same or opposite directions, based on the shape (concave or convex) of the moving articular surface."},{"id": 2822,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "According to the concave-convex rule, when a CONVEX joint surface moves on a fixed concave surface, roll and slide occur:","options": [{"key": "A","text": "In opposite directions"},{"key": "B","text": "Only as spin, never as roll or slide"},{"key": "C","text": "Independently with no relationship"},{"key": "D","text": "In the same direction"}],"correct": "D","explanation": "When the convex surface is the moving segment, roll and glide occur in the same direction."},{"id": 2823,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "According to the concave-convex rule, when a CONCAVE joint surface moves on a fixed convex surface, roll and slide occur:","options": [{"key": "A","text": "Not at all"},{"key": "B","text": "In opposite directions"},{"key": "C","text": "In the same direction"},{"key": "D","text": "Only as pure spin"}],"correct": "B","explanation": "When the concave surface is the moving segment, roll and glide occur in opposite directions."},{"id": 2824,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "In shoulder abduction, the convex humeral head moves on the relatively fixed concave glenoid fossa. According to the concave-convex rule, the humeral head should roll superiorly and glide:","options": [{"key": "A","text": "Superiorly (same direction as roll)"},{"key": "B","text": "Anteriorly only"},{"key": "C","text": "Not at all"},{"key": "D","text": "Inferiorly (opposite direction to roll)"}],"correct": "D","explanation": "Since the humeral head (convex) moves on a fixed concave glenoid, roll and glide are in opposite directions—here, the head rolls up but glides down (inferiorly)."},{"id": 2825,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "During knee extension in an open kinetic chain (non-weight-bearing), the convex femoral condyles are fixed and the concave tibial plateau moves. The tibia's roll and glide during extension occur:","options": [{"key": "A","text": "In opposite directions"},{"key": "B","text": "In the same direction (both anteriorly)"},{"key": "C","text": "Only as spin"},{"key": "D","text": "There is no arthrokinematic motion"}],"correct": "B","explanation": "In open-chain knee extension, the tibia (concave surface moving on a relatively fixed convex femur) rolls and glides anteriorly in the same direction, per the concave-convex rule for concave-on-convex motion... Note: tibia is concave surface moving, so roll and glide are actually in the SAME direction as it moves on a convex surface only if applying the rule for CONCAVE-moving-on-CONVEX which gives SAME direction. This reflects standard teaching for open-chain tibiofemoral extension."},{"id": 2826,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "During closed-chain knee extension (e.g., standing up from a squat), the convex femoral condyles move on the relatively fixed concave tibial plateau. The femur's roll and glide occur:","options": [{"key": "A","text": "In the same direction"},{"key": "B","text": "Only as pure spin"},{"key": "C","text": "Only as pure roll with no glide"},{"key": "D","text": "In opposite directions (femur rolls anteriorly, glides posteriorly)"}],"correct": "D","explanation": "In closed-chain knee extension, the femur (convex, moving) rolls anteriorly but glides posteriorly on the fixed tibia, preventing the femoral condyles from rolling off the tibial plateau."},{"id": 2827,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The primary biomechanical purpose of the combined roll-glide motion (rather than pure rolling) at joints is to:","options": [{"key": "A","text": "Keep the articulating surfaces in congruent contact and prevent the moving bone from rolling off the joint surface"},{"key": "B","text": "Increase joint friction"},{"key": "C","text": "Decrease range of motion"},{"key": "D","text": "Eliminate the need for ligaments"}],"correct": "A","explanation": "Combined roll and glide keep the joint surfaces appropriately apposed throughout the range of motion, preventing the convex surface from rolling off the concave surface's edge."},{"id": 2828,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "'Joint play' refers to:","options": [{"key": "A","text": "Muscle strength around a joint"},{"key": "B","text": "The capsular pattern of restriction"},{"key": "C","text": "Voluntary active range of motion"},{"key": "D","text": "Small involuntary movements available at a joint that cannot be produced by active muscle contraction alone"}],"correct": "D","explanation": "Joint play describes small passive accessory motions (e.g., distraction, glide) necessary for normal joint function but not achievable through voluntary muscle action."},{"id": 2829,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "Joint play movements are also known as:","options": [{"key": "A","text": "Accessory movements"},{"key": "B","text": "Osteokinematic movements"},{"key": "C","text": "Voluntary movements"},{"key": "D","text": "Physiological movements"}],"correct": "A","explanation": "Joint play is synonymous with accessory motion—small passive movements distinct from the larger physiological (osteokinematic) movements."},{"id": 2830,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Assessment of joint play is primarily useful clinically to:","options": [{"key": "A","text": "Measure cardiovascular endurance"},{"key": "B","text": "Measure muscle strength"},{"key": "C","text": "Assess nerve conduction velocity"},{"key": "D","text": "Assess the integrity of the joint capsule, ligaments, and detect restrictions not evident with active movement testing"}],"correct": "D","explanation": "Joint play assessment helps identify capsular or ligamentous restrictions and joint mobility deficits that active range of motion testing alone may not reveal."},{"id": 2831,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The 'close-packed position' of a joint is defined as the position in which:","options": [{"key": "A","text": "The articular surfaces are maximally congruent and the ligaments/capsule are maximally taut"},{"key": "B","text": "Joint play is maximal"},{"key": "C","text": "The joint is most vulnerable to injury"},{"key": "D","text": "The joint capsule and ligaments are most lax"}],"correct": "A","explanation": "In close-packed position, joint surfaces fit together most congruently, and surrounding ligaments/capsule are under maximum tension, providing greatest joint stability."},{"id": 2832,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The 'open-packed (loose-packed) position' of a joint is defined as the position where:","options": [{"key": "A","text": "Ligaments and capsule are maximally taut"},{"key": "B","text": "No joint movement is possible"},{"key": "C","text": "Joint surfaces are most congruent"},{"key": "D","text": "The joint capsule is most relaxed, allowing for maximum joint play"}],"correct": "D","explanation": "In the loose-packed position, the capsule and ligaments are most relaxed, allowing for greatest available joint play/accessory motion, ideal for mobilization techniques."},{"id": 2833,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Joint mobilization techniques are typically performed with the joint in which position?","options": [{"key": "A","text": "Only in full flexion"},{"key": "B","text": "Any random position"},{"key": "C","text": "Loose-packed (resting) position, to allow maximal joint play"},{"key": "D","text": "Close-packed position"}],"correct": "C","explanation": "Mobilizations are usually performed in the joint's loose-packed/resting position, where the capsule is most relaxed, allowing effective assessment and treatment of joint play."},{"id": 2834,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The close-packed position of the knee joint is:","options": [{"key": "A","text": "Neutral rotation only"},{"key": "B","text": "Full flexion"},{"key": "C","text": "20 degrees of flexion"},{"key": "D","text": "Full extension with slight external rotation of the tibia ('screw-home' mechanism)"}],"correct": "D","explanation": "Full knee extension, combined with the screw-home mechanism (slight tibial external rotation), represents the close-packed, most stable position of the knee."},{"id": 2835,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The close-packed position of the shoulder (glenohumeral) joint is:","options": [{"key": "A","text": "Full adduction"},{"key": "B","text": "Full internal rotation only"},{"key": "C","text": "Full abduction and external rotation"},{"key": "D","text": "Neutral position"}],"correct": "C","explanation": "Full abduction combined with external rotation places the glenohumeral joint in its close-packed, maximally congruent and stable position."},{"id": 2836,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The close-packed position of the hip joint is:","options": [{"key": "A","text": "Flexion and adduction"},{"key": "B","text": "Neutral rotation with flexion"},{"key": "C","text": "Flexion, abduction, and external rotation"},{"key": "D","text": "Full extension, internal rotation, and abduction"}],"correct": "D","explanation": "The hip's close-packed position is full extension with internal rotation and slight abduction, maximizing congruency and ligamentous tension."},{"id": 2837,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The close-packed position of the ankle (talocrural) joint is:","options": [{"key": "A","text": "Plantarflexion"},{"key": "B","text": "Maximum dorsiflexion"},{"key": "C","text": "Full inversion"},{"key": "D","text": "Neutral (mid) position"}],"correct": "B","explanation": "Maximum dorsiflexion is the close-packed position of the talocrural joint, where the wider anterior talus is wedged into the mortise, providing maximal stability."},{"id": 2838,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The loose-packed (resting) position of the glenohumeral joint is approximately:","options": [{"key": "A","text": "Full flexion"},{"key": "B","text": "Full abduction and external rotation"},{"key": "C","text": "Full adduction and internal rotation"},{"key": "D","text": "55 degrees abduction and 30 degrees horizontal adduction (approximately mid-range)"}],"correct": "D","explanation": "The glenohumeral resting position is generally cited as around 55° abduction and 30° horizontal adduction, allowing maximum capsular laxity."},{"id": 2839,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The loose-packed (resting) position of the knee joint is approximately:","options": [{"key": "A","text": "Full extension"},{"key": "B","text": "Full flexion"},{"key": "C","text": "90 degrees of flexion only"},{"key": "D","text": "25-30 degrees of flexion"}],"correct": "D","explanation": "The knee's resting position is approximately 25-30° of flexion, where the capsule and ligaments are most relaxed."},{"id": 2840,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Capsular pattern' refers to:","options": [{"key": "A","text": "A specific, proportional pattern of motion restriction characteristic of a joint when the entire capsule is affected (e.g., by arthritis)"},{"key": "B","text": "A random pattern of joint restriction seen only in trauma"},{"key": "C","text": "A pattern seen only with ligamentous injury"},{"key": "D","text": "A pattern of muscle weakness"}],"correct": "A","explanation": "Capsular pattern describes a joint-specific, characteristic proportion of restricted motions occurring when the whole joint capsule is involved, as in osteoarthritis or capsulitis."},{"id": 2841,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'non-capsular pattern' of restriction suggests that the limitation is likely due to:","options": [{"key": "A","text": "Generalized capsulitis or synovitis"},{"key": "B","text": "A more localized pathology, such as an internal derangement, ligament sprain, or adhesion not involving the whole capsule"},{"key": "C","text": "Normal joint physiology"},{"key": "D","text": "Systemic arthritis"}],"correct": "B","explanation": "When restriction does not follow the classic capsular ratio, it suggests localized pathology (e.g., meniscal tear, ligament sprain, or loose body) rather than diffuse capsular involvement."},{"id": 2842,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The classic capsular pattern of the glenohumeral joint (Cyriax) is:","options": [{"key": "A","text": "Only abduction is limited"},{"key": "B","text": "Internal rotation most limited, then abduction, then external rotation"},{"key": "C","text": "Equal limitation in all directions"},{"key": "D","text": "External rotation most limited, followed by abduction, then internal rotation least limited"}],"correct": "D","explanation": "The shoulder's capsular pattern shows greatest restriction in external rotation, followed by abduction, with internal rotation least affected."},{"id": 2843,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The classic capsular pattern of the hip joint is:","options": [{"key": "A","text": "Internal rotation and flexion most limited, followed by abduction; extension least limited"},{"key": "B","text": "Equal restriction of all hip motions"},{"key": "C","text": "External rotation most limited only"},{"key": "D","text": "Extension most limited, then flexion, then abduction"}],"correct": "A","explanation": "The hip capsular pattern classically presents with marked limitation of internal rotation and flexion, some limitation of abduction, with extension relatively less affected."},{"id": 2844,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The classic capsular pattern of the knee joint is:","options": [{"key": "A","text": "Extension more limited than flexion"},{"key": "B","text": "Equal limitation of flexion and extension"},{"key": "C","text": "Flexion more limited than extension"},{"key": "D","text": "Only rotation is limited"}],"correct": "C","explanation": "The knee's capsular pattern shows flexion more markedly limited than extension."},{"id": 2845,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The classic capsular pattern of the ankle (talocrural) joint is:","options": [{"key": "A","text": "Dorsiflexion and plantarflexion equally limited, with plantarflexion often more restricted"},{"key": "B","text": "No pattern exists at this joint"},{"key": "C","text": "Only eversion limited"},{"key": "D","text": "Only inversion limited"}],"correct": "A","explanation": "The ankle capsular pattern typically shows greater limitation of plantarflexion than dorsiflexion, though both are restricted."},{"id": 2846,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The classic capsular pattern of the first carpometacarpal (thumb) joint is:","options": [{"key": "A","text": "Abduction and extension most limited"},{"key": "B","text": "Equal limitation of all motions"},{"key": "C","text": "Opposition limited only"},{"key": "D","text": "Flexion most limited only"}],"correct": "A","explanation": "The thumb CMC joint's capsular pattern involves greatest restriction of abduction and extension."},{"id": 2847,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The capsular pattern of the elbow joint typically shows:","options": [{"key": "A","text": "Pronation more limited than supination"},{"key": "B","text": "Extension more limited than flexion"},{"key": "C","text": "Flexion more limited than extension"},{"key": "D","text": "Equal limitation of flexion and extension"}],"correct": "C","explanation": "The elbow's capsular pattern shows flexion more restricted than extension."},{"id": 2848,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following joints is considered to have NO true capsular pattern due to unique biomechanics (per Cyriax classification)?","options": [{"key": "A","text": "Sacroiliac joint"},{"key": "B","text": "Hip"},{"key": "C","text": "Knee"},{"key": "D","text": "Shoulder"}],"correct": "A","explanation": "The sacroiliac joint, due to its unique, minimal-motion biomechanics, does not exhibit a classic Cyriax capsular pattern."},{"id": 2849,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which of the following best describes an 'osteokinematic' movement as opposed to an arthrokinematic one?","options": [{"key": "A","text": "Roll occurring in isolation"},{"key": "B","text": "Small accessory glide at the joint surface"},{"key": "C","text": "Gross visible movement of a bone/limb segment, such as flexion or abduction"},{"key": "D","text": "Spin occurring at the joint surface only"}],"correct": "C","explanation": "Osteokinematics refers to the larger, observable movement of bones relative to the cardinal planes, distinct from the smaller accessory arthrokinematic motions."},{"id": 2850,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Mobilization grades (e.g., Maitland's Grades I-IV) are primarily used to describe:","options": [{"key": "A","text": "Muscle strength grading"},{"key": "B","text": "The severity of a fracture"},{"key": "C","text": "The amplitude and range of oscillatory passive movement applied relative to the total available range"},{"key": "D","text": "Ligament laxity only"}],"correct": "C","explanation": "Maitland's grading system describes the amplitude of passive oscillatory movements applied within the joint's available range, from small (Grade I) to large (Grade IV) amplitude."},{"id": 2851,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In Maitland's mobilization grading, Grade I refers to:","options": [{"key": "A","text": "A small-amplitude movement performed at the beginning of range"},{"key": "B","text": "A sustained stretch at the end range"},{"key": "C","text": "A thrust technique"},{"key": "D","text": "A large-amplitude movement performed at the end of range"}],"correct": "A","explanation": "Grade I is a small-amplitude oscillation performed within the early part of the available range, typically used for pain relief."},{"id": 2852,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In Maitland's mobilization grading, Grade IV refers to:","options": [{"key": "A","text": "A large-amplitude movement through most of the range"},{"key": "B","text": "A small-amplitude movement performed at the very end of available range, into resistance"},{"key": "C","text": "A distraction technique only"},{"key": "D","text": "A small-amplitude movement at the beginning of range"}],"correct": "B","explanation": "Grade IV is a small-amplitude oscillation performed at the very end of range, into tissue resistance, typically used to address stiffness."},{"id": 2853,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Kaltenborn's joint mobilization grading system uses three grades, where Grade I refers to:","options": [{"key": "A","text": "A distraction that separates joint surfaces to take up the slack without actual separation stress"},{"key": "B","text": "A thrust manipulation"},{"key": "C","text": "Active range of motion only"},{"key": "D","text": "A large oscillatory movement"}],"correct": "A","explanation": "Kaltenborn's Grade I is a gentle traction that nullifies compressive forces on the joint without actually stretching the capsule (used to relieve pain)."},{"id": 2854,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Kaltenborn's Grade III mobilization involves:","options": [{"key": "A","text": "Taking up slack in the joint capsule only"},{"key": "B","text": "Stretching the joint capsule beyond the slack to increase mobility"},{"key": "C","text": "No tissue stretch at all"},{"key": "D","text": "Movement only within the resting position"}],"correct": "B","explanation": "Grade III involves stretching the capsule and surrounding tissue beyond the available slack, aiming to increase joint mobility."},{"id": 2855,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which structure primarily limits joint play/accessory motion at the end of available range?","options": [{"key": "A","text": "Muscle tissue only"},{"key": "B","text": "Cartilage thickness alone"},{"key": "C","text": "Bone density"},{"key": "D","text": "The joint capsule and associated ligaments"}],"correct": "D","explanation": "The capsule and ligaments provide the primary passive restraint that limits accessory joint motion at the end of the available range."},{"id": 2856,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "A 'hard end feel' during passive joint motion, such as elbow extension limited by bony contact (olecranon in fossa), indicates:","options": [{"key": "A","text": "Bone-on-bone contact"},{"key": "B","text": "Muscular tightness"},{"key": "C","text": "Synovial effusion"},{"key": "D","text": "Capsular tightness"}],"correct": "A","explanation": "A hard, abrupt end feel typically indicates bony approximation, such as the olecranon process contacting the olecranon fossa at full elbow extension."},{"id": 2857,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'capsular (firm) end feel' is characterized by:","options": [{"key": "A","text": "A firm but slightly yielding sensation with some give, typical of capsular/ligamentous tissue stretch"},{"key": "B","text": "A soft, mushy stop due to muscle bulk"},{"key": "C","text": "A sudden hard stop"},{"key": "D","text": "No resistance at all"}],"correct": "A","explanation": "Capsular end feel has a firm quality with a small amount of give, reflecting normal stretch of the joint capsule and ligaments at end range."},{"id": 2858,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'soft end feel' during passive movement, such as knee flexion limited by soft tissue approximation, is due to:","options": [{"key": "A","text": "Bony block"},{"key": "B","text": "Capsular tightness"},{"key": "C","text": "Ligament rupture"},{"key": "D","text": "Muscle bulk or soft tissue apposition"}],"correct": "D","explanation": "Soft end feel results from soft tissue (e.g., muscle bulk of the hamstrings/calf) approximating, as in full knee flexion."},{"id": 2859,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "An 'empty end feel' during passive joint assessment indicates that:","options": [{"key": "A","text": "The joint has excessive stability"},{"key": "B","text": "No abnormality is present"},{"key": "C","text": "Normal tissue resistance is felt"},{"key": "D","text": "Movement is limited by the patient's pain response before any true tissue resistance is reached, often indicating serious pathology"}],"correct": "D","explanation": "Empty end feel occurs when pain prevents further movement before any true mechanical resistance is felt, often signaling significant pathology such as acute inflammation, fracture, or tumor."},{"id": 2860,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "A 'springy block' end feel, typically seen with a meniscal tear blocking knee extension, indicates:","options": [{"key": "A","text": "An internal derangement causing a rebound sensation at the end of range"},{"key": "B","text": "Normal capsular restriction"},{"key": "C","text": "Muscle spasm only"},{"key": "D","text": "Bony block"}],"correct": "A","explanation": "A springy, rebound-like end feel suggests a mechanical block from loose intra-articular tissue (e.g., a torn meniscus fragment), termed internal derangement."},{"id": 2861,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "A 'muscle spasm end feel' is characterized by:","options": [{"key": "A","text": "A sudden, sharp, vice-like stop, often accompanied by pain, due to protective muscle guarding"},{"key": "B","text": "A soft, mushy stop"},{"key": "C","text": "No resistance whatsoever"},{"key": "D","text": "A gradual, firm stop with slight give"}],"correct": "A","explanation": "Spasm end feel presents as an abrupt, guarding-type stop, often invoked reflexively to protect an irritated or inflamed structure."},{"id": 2862,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "Which joint surface shape is generally considered 'convex'?","options": [{"key": "A","text": "A flat surface only"},{"key": "B","text": "A surface that curves inward, like a socket"},{"key": "C","text": "A surface with no curvature"},{"key": "D","text": "A surface that curves outward, like a ball"}],"correct": "D","explanation": "A convex surface curves outward (e.g., humeral head, femoral condyles), analogous to the outer surface of a ball."},{"id": 2863,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "Which joint surface shape is generally considered 'concave'?","options": [{"key": "A","text": "A surface with maximum convexity"},{"key": "B","text": "A surface that curves outward"},{"key": "C","text": "A perfectly flat surface"},{"key": "D","text": "A surface that curves inward, like a socket or cup"}],"correct": "D","explanation": "A concave surface curves inward, forming a socket-like shape (e.g., glenoid fossa, acetabulum, tibial plateau)."},{"id": 2864,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "In the glenohumeral joint, which surface is convex and which is concave?","options": [{"key": "A","text": "Humeral head is concave; glenoid fossa is convex"},{"key": "B","text": "Humeral head is convex; glenoid fossa is concave"},{"key": "C","text": "Both surfaces are concave"},{"key": "D","text": "Both surfaces are convex"}],"correct": "B","explanation": "The humeral head is convex, articulating with the concave glenoid fossa of the scapula."},{"id": 2865,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "In the hip joint, which surface is convex and which is concave?","options": [{"key": "A","text": "Femoral head is concave; acetabulum is convex"},{"key": "B","text": "Femoral head is convex; acetabulum is concave"},{"key": "C","text": "Both are concave"},{"key": "D","text": "Both are convex"}],"correct": "B","explanation": "The femoral head is convex, fitting into the concave acetabulum of the pelvis."},{"id": 2866,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "In the tibiofemoral (knee) joint, the femoral condyles are __________ and the tibial plateau is __________.","options": [{"key": "A","text": "Both flat"},{"key": "B","text": "Convex; relatively concave (flat to slightly concave)"},{"key": "C","text": "Both convex"},{"key": "D","text": "Concave; convex"}],"correct": "B","explanation": "The femoral condyles are convex, articulating with the relatively flat-to-concave tibial plateau surface."},{"id": 2867,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "In the radiocarpal (wrist) joint, the distal radius is __________ and the proximal carpal row is __________.","options": [{"key": "A","text": "Convex; concave"},{"key": "B","text": "Both convex"},{"key": "C","text": "Concave; convex"},{"key": "D","text": "Both concave"}],"correct": "C","explanation": "The distal radius presents a concave surface articulating with the convex proximal carpal row (scaphoid, lunate, triquetrum)."},{"id": 2868,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "In the talocrural (ankle) joint, the talar dome is __________ and the mortise (formed by tibia/fibula) is __________.","options": [{"key": "A","text": "Convex; concave"},{"key": "B","text": "Both flat"},{"key": "C","text": "Concave; convex"},{"key": "D","text": "Both convex"}],"correct": "A","explanation": "The talar dome is convex, fitting within the concave mortise formed by the distal tibia and fibula."},{"id": 2869,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Understanding the concave-convex rule is clinically important because it helps determine:","options": [{"key": "A","text": "Radiographic interpretation only"},{"key": "B","text": "The correct direction to apply a glide during joint mobilization to improve a specific motion"},{"key": "C","text": "Muscle strength testing procedures"},{"key": "D","text": "Nerve conduction studies"}],"correct": "B","explanation": "Knowing whether the moving joint surface is concave or convex allows the clinician to apply mobilization glides in the correct direction to restore the intended physiological motion."},{"id": 2870,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "To improve shoulder abduction range of motion using joint mobilization (convex humeral head on concave glenoid), the therapist would typically apply a glide in which direction?","options": [{"key": "A","text": "No glide is needed since it's a convex surface"},{"key": "B","text": "Inferior glide, opposite direction to the limited osteokinematic motion"},{"key": "C","text": "Anterior glide only"},{"key": "D","text": "Superior glide, same direction as the limited motion"}],"correct": "B","explanation": "Since the humeral head is convex moving on a concave glenoid, glide occurs opposite to the direction of the bone's physiological movement—an inferior glide is used to facilitate abduction."},{"id": 2871,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "To improve knee extension range of motion in an open-chain scenario (concave tibia on convex femur), the therapist would apply an anterior glide of the tibia because:","options": [{"key": "A","text": "Only spin can be used at the knee"},{"key": "B","text": "The concave surface's glide always opposes its movement"},{"key": "C","text": "The concave surface's glide occurs in the same direction as its physiological (roll) movement"},{"key": "D","text": "Direction of glide is irrelevant to concave surfaces"}],"correct": "C","explanation": "Since the tibia (concave) is the moving segment on the relatively fixed convex femur, its glide occurs in the same direction as the physiological motion (anterior, for extension)."},{"id": 2872,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "'Congruency' of a joint refers to:","options": [{"key": "A","text": "The strength of the surrounding muscles"},{"key": "B","text": "The number of ligaments crossing the joint"},{"key": "C","text": "How well the shapes of the two articulating surfaces fit together"},{"key": "D","text": "The presence of synovial fluid only"}],"correct": "C","explanation": "Congruency describes the degree of fit/match between the shapes of two opposing articular surfaces, which is greatest in the close-packed position."},{"id": 2873,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Increased joint congruency generally results in:","options": [{"key": "A","text": "Increased joint stability but often reduced available joint play"},{"key": "B","text": "Decreased joint stability"},{"key": "C","text": "No relationship to stability or joint play"},{"key": "D","text": "Increased joint play with no change in stability"}],"correct": "A","explanation": "Greater congruency (as in close-packed position) enhances stability by maximizing surface contact, but simultaneously reduces the available accessory motion (joint play)."},{"id": 2874,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Traction (distraction) mobilization technique applied perpendicular to the treatment plane primarily aims to:","options": [{"key": "A","text": "Produce a capsular pattern"},{"key": "B","text": "Separate joint surfaces to relieve pain and/or increase mobility"},{"key": "C","text": "Increase muscle strength"},{"key": "D","text": "Compress joint surfaces"}],"correct": "B","explanation": "Distraction/traction mobilizations separate the joint surfaces along a line perpendicular to the treatment plane, used for pain relief or to increase joint mobility."},{"id": 2875,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'treatment plane' in manual therapy is best described as:","options": [{"key": "A","text": "A plane that lies along the concave articular surface, perpendicular to a line from the center of the convex surface to the center of the concave surface"},{"key": "B","text": "A plane defined only by ligament orientation"},{"key": "C","text": "A plane perpendicular to the long axis of the moving bone"},{"key": "D","text": "The sagittal plane of the whole body"}],"correct": "A","explanation": "The treatment plane is defined relative to the concave articular surface and is used as the reference for applying glide and traction mobilization forces."},{"id": 2876,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Gliding mobilizations are typically applied:","options": [{"key": "A","text": "Parallel to the treatment plane"},{"key": "B","text": "Only in the close-packed position"},{"key": "C","text": "Perpendicular to the treatment plane"},{"key": "D","text": "At a random angle unrelated to joint shape"}],"correct": "A","explanation": "Glide mobilizations are applied parallel to the treatment plane (along the concave surface), consistent with the direction predicted by the concave-convex rule."},{"id": 2877,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "A joint effusion (increased synovial fluid) commonly results in the joint adopting:","options": [{"key": "A","text": "The close-packed position for comfort"},{"key": "B","text": "A fixed abnormal position unrelated to capsule tension"},{"key": "C","text": "No positional preference"},{"key": "D","text": "The loose-packed (resting) position, as it accommodates the greatest joint volume"}],"correct": "D","explanation": "Patients with joint effusion often hold the joint in its resting/loose-packed position, which accommodates maximum intracapsular volume and minimizes capsular tension and pain."},{"id": 2878,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which of the following is an example of combined roll and glide occurring in the SAME direction, consistent with a convex surface moving on a concave surface?","options": [{"key": "A","text": "None of the above"},{"key": "B","text": "Tibiofemoral extension with fixed femur, moving concave tibia"},{"key": "C","text": "Glenohumeral abduction (humeral head convex on glenoid concave)"},{"key": "D","text": "Radiocarpal flexion (concave radius, convex carpal row moving)"}],"correct": "D","explanation": "At the wrist, the convex proximal carpal row moves on the relatively fixed concave radius; per the rule, roll and glide occur in the same direction here, correctly matching the convex-on-concave pattern."},{"id": 2879,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During active shoulder abduction beyond 90 degrees, upward rotation of the scapula is necessary primarily to:","options": [{"key": "A","text": "Eliminate the need for rotator cuff activity"},{"key": "B","text": "Increase joint play at the glenohumeral joint"},{"key": "C","text": "Prevent impingement of the greater tuberosity against the acromion by maintaining space in the subacromial region"},{"key": "D","text": "Reduce muscle activity of the deltoid"}],"correct": "C","explanation": "Scapular upward rotation (part of scapulohumeral rhythm) helps maintain adequate subacromial space, reducing the risk of impingement during arm elevation."},{"id": 2880,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The scapulohumeral rhythm describes the ratio of glenohumeral to scapulothoracic motion during arm elevation, classically cited as approximately:","options": [{"key": "A","text": "No fixed ratio exists at all"},{"key": "B","text": "2:1 (glenohumeral to scapulothoracic) overall"},{"key": "C","text": "1:1 throughout the entire range"},{"key": "D","text": "4:1 with scapula moving more than the humerus"}],"correct": "B","explanation": "The classic scapulohumeral rhythm describes an overall ratio of approximately 2:1 between glenohumeral and scapulothoracic motion during full arm elevation."},{"id": 2881,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which of the following joint pairings is correctly matched with its close-packed position?","options": [{"key": "A","text": "Wrist – full extension"},{"key": "B","text": "Hip – flexion with adduction"},{"key": "C","text": "Ankle – plantarflexion"},{"key": "D","text": "Wrist – flexion"}],"correct": "A","explanation": "Full wrist extension is the close-packed, most congruent and stable position of the radiocarpal joint."},{"id": 2882,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which of the following joint pairings is correctly matched with its close-packed position?","options": [{"key": "A","text": "Elbow – mid-range flexion"},{"key": "B","text": "Elbow – full flexion"},{"key": "C","text": "Elbow – pronation only"},{"key": "D","text": "Elbow – full extension"}],"correct": "D","explanation": "Full extension (with supination) is generally described as the close-packed position of the elbow (humeroulnar joint)."},{"id": 2883,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which of the following statements about the 'zig-zag' or S-shaped articular surfaces (as in the saddle-shaped carpometacarpal joint of the thumb) is true regarding the concave-convex rule?","options": [{"key": "A","text": "The rule cannot be applied at all to saddle joints"},{"key": "B","text": "The rule must be applied separately for each plane of motion, since the surface is convex in one plane and concave in the perpendicular plane"},{"key": "C","text": "Saddle joints have no roll or glide"},{"key": "D","text": "Only spin occurs at saddle joints"}],"correct": "B","explanation": "At sellar (saddle) joints, the surface is convex in one direction and concave in the perpendicular direction, so the concave-convex rule must be applied independently to each plane of movement."},{"id": 2884,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Peripheral joint mobilization techniques are contraindicated in the presence of:","options": [{"key": "A","text": "Chronic mild stiffness"},{"key": "B","text": "Acute joint inflammation, infection, or unhealed fracture in the region"},{"key": "C","text": "Normal joint play"},{"key": "D","text": "Mild capsular tightness"}],"correct": "B","explanation": "Mobilization is contraindicated with active infection, unhealed fracture, or acute inflammatory conditions, where forces could exacerbate tissue damage."},{"id": 2885,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which grade of Kaltenborn's mobilization is best used primarily for pain relief in an acutely irritable joint?","options": [{"key": "A","text": "Grade I"},{"key": "B","text": "Grade II"},{"key": "C","text": "Grade IV"},{"key": "D","text": "Grade III"}],"correct": "A","explanation": "Kaltenborn's Grade I (small-amplitude distraction without stretching the capsule) is used mainly to relieve pain in highly irritable or acute joint conditions."},{"id": 2886,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "A therapist wanting to increase overall joint mobility (not just relieve pain) in a chronic capsular restriction would typically progress toward using:","options": [{"key": "A","text": "Grade II mobilization only"},{"key": "B","text": "No mobilization at all"},{"key": "C","text": "Grade I mobilization only"},{"key": "D","text": "Grade III mobilization, which stretches the capsule"}],"correct": "D","explanation": "Grade III mobilization involves sustained stretch beyond the tissue slack, appropriate for addressing chronic capsular tightness and increasing range of motion."},{"id": 2887,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which best explains why joint mobilization is performed in the resting (loose-packed) position rather than the close-packed position?","options": [{"key": "A","text": "The close-packed position offers greater joint play, making mobilization easier"},{"key": "B","text": "There is no biomechanical reason; either position works equally well"},{"key": "C","text": "Close-packed position is always used for safety"},{"key": "D","text": "The loose-packed position offers maximal capsular laxity and joint play, allowing effective assessment and treatment"}],"correct": "D","explanation": "The loose-packed position provides maximum available joint play due to capsular laxity, which is essential for effectively assessing and performing mobilization techniques."},{"id": 2888,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "In the sacroiliac joint, which is largely a non-synovial or minimally mobile joint in some contexts, arthrokinematic motions described include:","options": [{"key": "A","text": "Small movements such as nutation and counter-nutation"},{"key": "B","text": "Pure spin only"},{"key": "C","text": "No movement occurs under any condition"},{"key": "D","text": "Large rotations of over 45 degrees"}],"correct": "A","explanation": "The SIJ exhibits small accessory motions termed nutation (anterior sacral tilt relative to ilium) and counter-nutation (posterior tilt), rather than large-range classic roll-glide-spin motions."},{"id": 2889,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Nutation of the sacrum refers to:","options": [{"key": "A","text": "Anterior tilting/nodding of the sacral base relative to the ilium, which tightens the SIJ ligaments"},{"key": "B","text": "Posterior tilting of the sacral base relative to the ilium"},{"key": "C","text": "Lateral rotation of the sacrum"},{"key": "D","text": "Complete immobility of the sacrum"}],"correct": "A","explanation": "Nutation describes the sacral base tilting anteriorly (nodding forward) relative to the ilia, which increases tension in the SIJ ligaments and enhances stability."},{"id": 2890,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Counter-nutation of the sacrum refers to:","options": [{"key": "A","text": "Posterior tilting of the sacral base relative to the ilium, which loosens the SIJ ligaments"},{"key": "B","text": "Anterior tilting of the sacral base"},{"key": "C","text": "A synonym for nutation"},{"key": "D","text": "A pathological movement only"}],"correct": "A","explanation": "Counter-nutation describes posterior tilting of the sacral base relative to the ilia, generally associated with reduced ligamentous tension at the SIJ."},{"id": 2891,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The presence of a capsular pattern on clinical examination is most suggestive of:","options": [{"key": "A","text": "A ligament sprain isolated to one part of the joint"},{"key": "B","text": "A meniscal tear only"},{"key": "C","text": "Involvement of the entire joint capsule, such as in osteoarthritis or capsulitis"},{"key": "D","text": "Muscle strain only"}],"correct": "C","explanation": "A true capsular pattern (proportional restriction of multiple motions) indicates the entire capsule is involved, typically from arthritic or inflammatory processes."},{"id": 2892,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Testing passive accessory movements (joint play) rather than only active/passive physiological movements is valuable because it can detect:","options": [{"key": "A","text": "Only muscular weakness"},{"key": "B","text": "Restrictions or hypermobility at the joint surface level that active movement testing alone might miss"},{"key": "C","text": "Cardiovascular fitness"},{"key": "D","text": "Bone mineral density"}],"correct": "B","explanation": "Accessory movement testing can reveal subtle joint-surface-level restrictions or excessive mobility not always apparent through gross active/passive range of motion testing alone."},{"id": 2893,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "A hypomobile joint on accessory motion testing, in the absence of a capsular pattern, most likely suggests:","options": [{"key": "A","text": "Generalized capsulitis"},{"key": "B","text": "A localized adhesion or specific structural restriction rather than diffuse capsular involvement"},{"key": "C","text": "Systemic inflammatory arthritis"},{"key": "D","text": "Normal joint function"}],"correct": "B","explanation": "Isolated hypomobility without a full capsular pattern points toward a localized restriction (e.g., an adhesion) rather than a diffuse, whole-capsule problem."},{"id": 2894,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which best describes the relationship between joint congruency and inherent (passive) stability?","options": [{"key": "A","text": "Only ligaments determine stability, not surface shape"},{"key": "B","text": "Greater congruency always decreases stability"},{"key": "C","text": "Congruency has no relationship to stability"},{"key": "D","text": "Greater congruency generally increases passive stability of a joint"}],"correct": "D","explanation": "Joints with higher congruency (close bony fit) generally rely more on bony/articular stability, while less congruent joints depend more on ligamentous and muscular support."},{"id": 2895,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Stress, in biomechanics, is defined as:","options": [{"key": "A","text": "Force per unit area"},{"key": "B","text": "Deformation per unit length"},{"key": "C","text": "Energy stored per unit volume"},{"key": "D","text": "Force multiplied by time"}],"correct": "A","explanation": "Stress is the internal resistance force per unit cross-sectional area developed within a material in response to an applied load."},{"id": 2896,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Strain is defined as:","options": [{"key": "A","text": "Force per unit area"},{"key": "B","text": "Rate of loading"},{"key": "C","text": "Force multiplied by distance"},{"key": "D","text": "The ratio of change in length to original length (deformation)"}],"correct": "D","explanation": "Strain represents the relative deformation of a material, calculated as change in length divided by original length."},{"id": 2897,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "A stress-strain curve is used to characterize a material's:","options": [{"key": "A","text": "Electrical conductivity"},{"key": "B","text": "Color and texture"},{"key": "C","text": "Chemical composition only"},{"key": "D","text": "Mechanical behavior under load, including elasticity, yield point, and failure"}],"correct": "D","explanation": "The stress-strain curve graphically depicts a material's mechanical response to loading, revealing properties like stiffness, elastic limit, and ultimate failure point."},{"id": 2898,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'elastic region' of a stress-strain curve represents the range in which:","options": [{"key": "A","text": "The material undergoes permanent deformation"},{"key": "B","text": "The material returns to its original shape once the load is removed"},{"key": "C","text": "Stress is independent of strain"},{"key": "D","text": "The material has already failed"}],"correct": "B","explanation": "In the elastic region, deformation is reversible, and the material returns to its original dimensions upon unloading."},{"id": 2899,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'plastic region' of a stress-strain curve represents the range in which:","options": [{"key": "A","text": "The material undergoes permanent (irreversible) deformation beyond the elastic limit"},{"key": "B","text": "No deformation occurs"},{"key": "C","text": "The material is at its strongest"},{"key": "D","text": "Deformation is completely reversible"}],"correct": "A","explanation": "Beyond the yield point, the material enters the plastic region where deformation becomes permanent even after the load is removed."},{"id": 2900,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'yield point' on a stress-strain curve marks the transition between:","options": [{"key": "A","text": "Toughness and brittleness"},{"key": "B","text": "Stress and strain axes"},{"key": "C","text": "Tension and compression"},{"key": "D","text": "The elastic and plastic regions"}],"correct": "D","explanation": "The yield point is where the material transitions from reversible (elastic) to permanent (plastic) deformation."},{"id": 2901,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Ultimate tensile strength' refers to:","options": [{"key": "A","text": "The stress at the yield point"},{"key": "B","text": "The stiffness of the material"},{"key": "C","text": "The maximum stress a material can withstand before failure"},{"key": "D","text": "The strain at failure"}],"correct": "C","explanation": "Ultimate tensile strength represents the peak stress a material can sustain before breaking or failing."},{"id": 2902,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Young's modulus (modulus of elasticity) represents:","options": [{"key": "A","text": "The strain at failure"},{"key": "B","text": "The area under the stress-strain curve"},{"key": "C","text": "The stiffness of a material, calculated as the slope of the stress-strain curve in the elastic region"},{"key": "D","text": "The maximum load a material can bear"}],"correct": "C","explanation": "Young's modulus quantifies a material's stiffness—the ratio of stress to strain within the elastic (linear) region."},{"id": 2903,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A material with a steep slope on the elastic portion of its stress-strain curve is described as:","options": [{"key": "A","text": "Highly flexible"},{"key": "B","text": "Stiff (high Young's modulus)"},{"key": "C","text": "Weak"},{"key": "D","text": "Ductile only"}],"correct": "B","explanation": "A steeper slope indicates greater stress is required for a given strain, reflecting higher stiffness (higher Young's modulus)."},{"id": 2904,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Toughness' of a material refers to:","options": [{"key": "A","text": "Its stiffness alone"},{"key": "B","text": "Its ultimate strength only"},{"key": "C","text": "Its yield point only"},{"key": "D","text": "The total energy absorbed before failure, represented by the total area under the stress-strain curve"}],"correct": "D","explanation": "Toughness represents the total energy a material can absorb before fracturing, corresponding to the entire area under the stress-strain curve."},{"id": 2905,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Viscoelasticity' refers to a material property in which the mechanical behavior:","options": [{"key": "A","text": "Is purely elastic with no time dependency"},{"key": "B","text": "Depends on both elastic and time/rate-dependent (viscous) characteristics"},{"key": "C","text": "Only applies to bone tissue"},{"key": "D","text": "Is independent of the rate of loading"}],"correct": "B","explanation": "Viscoelastic materials, like most soft connective tissues, exhibit both elastic and viscous (time-dependent) mechanical behavior."},{"id": 2906,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Creep' in viscoelastic tissue refers to:","options": [{"key": "A","text": "Progressive deformation (elongation) of tissue under a constant, sustained load over time"},{"key": "B","text": "Immediate deformation followed by immediate recovery"},{"key": "C","text": "Increased stiffness of tissue with repeated loading"},{"key": "D","text": "Sudden tissue rupture under load"}],"correct": "A","explanation": "Creep describes the gradual increase in deformation/length of viscoelastic tissue when subjected to a constant sustained load over time."},{"id": 2907,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Stress relaxation' in viscoelastic tissue refers to:","options": [{"key": "A","text": "Progressive increase in length under constant load"},{"key": "B","text": "Increased force generation over time"},{"key": "C","text": "Immediate return to original shape"},{"key": "D","text": "A decrease in internal stress over time when the tissue is held at a constant length (deformation)"}],"correct": "D","explanation": "Stress relaxation occurs when tissue is held at a fixed elongation, and the internal stress required to maintain that length gradually decreases over time."},{"id": 2908,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Hysteresis' in viscoelastic tissue refers to:","options": [{"key": "A","text": "Identical loading and unloading curves"},{"key": "B","text": "The energy loss represented by the difference between the loading and unloading curves on a stress-strain graph"},{"key": "C","text": "A property only seen in bone"},{"key": "D","text": "The absence of any elastic recoil"}],"correct": "B","explanation": "Hysteresis represents the energy dissipated as heat due to internal friction, seen as the gap between the loading and unloading curves in viscoelastic tissues."},{"id": 2909,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Repeated loading and unloading cycles of viscoelastic tissue (e.g., during warm-up stretching) that progressively reduce resistance to stretch is termed:","options": [{"key": "A","text": "Creep only"},{"key": "B","text": "Stress-strain reversal"},{"key": "C","text": "Cyclic loading effect / 'preconditioning'"},{"key": "D","text": "Fatigue failure"}],"correct": "C","explanation": "Repeated submaximal loading cycles gradually reduce tissue stiffness temporarily, a phenomenon termed preconditioning, useful clinically during warm-up."},{"id": 2910,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Bone is best classified biomechanically as a material that is:","options": [{"key": "A","text": "Purely elastic with no time-dependent properties"},{"key": "B","text": "Isotropic in all directions with identical strength"},{"key": "C","text": "Anisotropic, viscoelastic, and capable of some plastic deformation before failure"},{"key": "D","text": "Purely brittle with no plastic deformation"}],"correct": "C","explanation": "Bone exhibits anisotropic (direction-dependent) strength, some viscoelastic behavior, and limited plastic deformation before ultimate failure."},{"id": 2911,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Anisotropic' material behavior means that:","options": [{"key": "A","text": "The material cannot bear any load"},{"key": "B","text": "Mechanical properties are the same in all directions"},{"key": "C","text": "Mechanical properties (e.g., strength, stiffness) differ depending on the direction of applied load"},{"key": "D","text": "The material is purely fluid"}],"correct": "C","explanation": "Anisotropic materials, like bone, have direction-dependent mechanical properties—stronger along some axes than others."},{"id": 2912,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Bone is generally strongest in resisting which type of loading?","options": [{"key": "A","text": "Tension"},{"key": "B","text": "Shear"},{"key": "C","text": "Compression"},{"key": "D","text": "Bending"}],"correct": "C","explanation": "Bone is biomechanically strongest under compressive loading compared to tension or shear."},{"id": 2913,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Bone is generally weakest in resisting which type of loading?","options": [{"key": "A","text": "Shear"},{"key": "B","text": "Compression"},{"key": "C","text": "Tension"},{"key": "D","text": "Bone is weakest under shear loading compared to tension or compression"}],"correct": "A","explanation": "Bone is comparatively weakest when subjected to shear forces, making it more prone to failure from shear-type loading."},{"id": 2914,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Wolff's Law states that bone:","options": [{"key": "A","text": "Remodels and adapts its structure in response to the mechanical demands (stresses) placed upon it"},{"key": "B","text": "Is unaffected by exercise or immobilization"},{"key": "C","text": "Never changes its structure regardless of loading"},{"key": "D","text": "Only grows during childhood"}],"correct": "A","explanation": "Wolff's Law describes bone's ability to remodel internally and externally in response to the mechanical loads it experiences, becoming stronger with increased load and weaker with disuse."},{"id": 2915,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Prolonged immobilization or disuse (e.g., prolonged bed rest) typically results in bone that is:","options": [{"key": "A","text": "Stronger and denser"},{"key": "B","text": "Weaker, less dense (osteopenic), due to reduced mechanical loading"},{"key": "C","text": "Only affected in the upper limb"},{"key": "D","text": "Unaffected by disuse"}],"correct": "B","explanation": "Per Wolff's Law, reduced mechanical stress from disuse leads to bone resorption and decreased density (disuse osteopenia)."},{"id": 2916,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Weight-bearing exercise is recommended for osteoporosis prevention primarily because it:","options": [{"key": "A","text": "Decreases bone remodeling activity"},{"key": "B","text": "Provides mechanical loading stimulus that promotes bone formation and density per Wolff's Law"},{"key": "C","text": "Only strengthens muscles, not bone"},{"key": "D","text": "Has no effect on bone density"}],"correct": "B","explanation": "Mechanical loading from weight-bearing activity stimulates osteoblastic activity and bone formation, helping maintain or increase bone mineral density."},{"id": 2917,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A bending load applied to a long bone typically produces which combination of stresses across its cross-section?","options": [{"key": "A","text": "Uniform tension throughout"},{"key": "B","text": "Tension on the convex side and compression on the concave side"},{"key": "C","text": "Uniform compression throughout"},{"key": "D","text": "Pure shear only"}],"correct": "B","explanation": "Bending creates tensile stress on the convex (outer curve) side and compressive stress on the concave (inner curve) side of the bone."},{"id": 2918,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A torsional (twisting) load applied to a long bone produces primarily which type of stress?","options": [{"key": "A","text": "No internal stress"},{"key": "B","text": "Shear stress, often resulting in a spiral fracture pattern"},{"key": "C","text": "Pure compression"},{"key": "D","text": "Pure tension"}],"correct": "B","explanation": "Torsional loading generates shear stresses throughout the bone, commonly producing a characteristic spiral fracture when failure occurs."},{"id": 2919,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A fracture caused by a combination of compression on one side and tension on the other, typically from a bending force, is classically called a:","options": [{"key": "A","text": "Transverse or oblique (bending) fracture"},{"key": "B","text": "Greenstick fracture only in adults"},{"key": "C","text": "Comminuted fracture only"},{"key": "D","text": "Spiral fracture"}],"correct": "A","explanation": "Bending forces typically cause transverse or oblique fractures, reflecting the combined tension-compression stress pattern across the bone."},{"id": 2920,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Articular cartilage is composed primarily of:","options": [{"key": "A","text": "Muscle fibers and tendons"},{"key": "B","text": "Nerve tissue and blood vessels"},{"key": "C","text": "Chondrocytes within an extracellular matrix of collagen (mainly type II) and proteoglycans, with high water content"},{"key": "D","text": "Bone matrix and calcium"}],"correct": "C","explanation": "Articular cartilage consists of chondrocytes embedded in a matrix rich in type II collagen and proteoglycans, with substantial water content contributing to its mechanical behavior."},{"id": 2921,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The high water content of articular cartilage contributes primarily to its ability to:","options": [{"key": "A","text": "Conduct nerve impulses"},{"key": "B","text": "Distribute load and provide shock absorption through fluid pressurization"},{"key": "C","text": "Contract like a muscle"},{"key": "D","text": "Generate active muscle force"}],"correct": "B","explanation": "Water within the cartilage matrix helps distribute compressive loads and provides a cushioning, shock-absorbing effect through fluid pressurization under load."},{"id": 2922,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Articular cartilage is generally considered to be:","options": [{"key": "A","text": "Only present in synovial joints of the spine"},{"key": "B","text": "Composed mainly of bone tissue"},{"key": "C","text": "Avascular and aneural"},{"key": "D","text": "Highly vascularized and richly innervated"}],"correct": "C","explanation": "Articular cartilage lacks blood vessels and nerves, relying on diffusion from synovial fluid for nutrition, which also limits its healing capacity."},{"id": 2923,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Because articular cartilage is avascular, its capacity for self-repair after injury is generally:","options": [{"key": "A","text": "Excellent, similar to bone healing"},{"key": "B","text": "Identical to muscle healing"},{"key": "C","text": "Unaffected by the lack of blood supply"},{"key": "D","text": "Limited/poor compared to vascularized tissues"}],"correct": "D","explanation": "The absence of direct blood supply significantly limits cartilage's regenerative and healing capacity compared to vascularized tissues like bone or muscle."},{"id": 2924,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Cyclic (intermittent) compressive loading of articular cartilage, as occurs during normal joint movement, is generally considered:","options": [{"key": "A","text": "Beneficial, as it helps pump nutrients into the avascular cartilage via synovial fluid exchange"},{"key": "B","text": "Harmful and should always be avoided"},{"key": "C","text": "Irrelevant to cartilage health"},{"key": "D","text": "Only relevant in pathological joints"}],"correct": "A","explanation": "Intermittent loading and unloading during movement helps pump synovial fluid in and out of cartilage, aiding nutrient exchange in the absence of direct blood supply."},{"id": 2925,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Prolonged, sustained (static) compressive loading of articular cartilage, in contrast to cyclic loading, tends to:","options": [{"key": "A","text": "Impair fluid exchange and nutrient diffusion, potentially harming cartilage health over time"},{"key": "B","text": "Only affect bone, not cartilage"},{"key": "C","text": "Improve nutrient exchange"},{"key": "D","text": "Have identical effects to cyclic loading"}],"correct": "A","explanation": "Sustained static compression can impede the normal fluid exchange process, potentially compromising cartilage nutrition and health with prolonged application."},{"id": 2926,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Ligaments primarily connect:","options": [{"key": "A","text": "Bone to bone"},{"key": "B","text": "Muscle to bone"},{"key": "C","text": "Nerve to muscle"},{"key": "D","text": "Muscle to muscle"}],"correct": "A","explanation": "Ligaments are dense connective tissue structures that connect one bone to another, providing joint stability."},{"id": 2927,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Tendons primarily connect:","options": [{"key": "A","text": "Bone to bone"},{"key": "B","text": "Muscle to bone"},{"key": "C","text": "Nerve to bone"},{"key": "D","text": "Cartilage to cartilage"}],"correct": "B","explanation": "Tendons are connective tissue structures that attach muscle to bone, transmitting muscular force to produce joint movement."},{"id": 2928,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Ligaments and tendons are both composed primarily of which type of collagen?","options": [{"key": "A","text": "Type III collagen only"},{"key": "B","text": "Type I collagen"},{"key": "C","text": "Type II collagen"},{"key": "D","text": "Type IV collagen only"}],"correct": "B","explanation": "Both ligaments and tendons are composed predominantly of Type I collagen, arranged to resist tensile loading."},{"id": 2929,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best distinguishes tendons from ligaments in terms of collagen fiber arrangement?","options": [{"key": "A","text": "Ligaments have parallel fibers while tendons are random"},{"key": "B","text": "Tendons have highly parallel, uniaxial collagen fiber orientation suited for unidirectional tensile load; ligaments often have a more varied, multidirectional arrangement"},{"key": "C","text": "Both have identical, random fiber arrangements"},{"key": "D","text": "Neither structure has organized collagen"}],"correct": "B","explanation": "Tendon fibers are arranged in parallel bundles suited to withstand strong unidirectional tensile forces, while ligament fibers may be more varied to resist multidirectional stresses at a joint."},{"id": 2930,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The characteristic 'toe region' seen at the beginning of a ligament or tendon's stress-strain curve represents:","options": [{"key": "A","text": "Immediate tissue failure"},{"key": "B","text": "Maximum tissue stiffness"},{"key": "C","text": "Complete plastic deformation"},{"key": "D","text": "The straightening out of the normally wavy (crimped) collagen fibers before they bear significant load"}],"correct": "D","explanation": "The toe region reflects the initial straightening of the crimped collagen fiber pattern, requiring relatively little force before the fibers become taut and begin bearing substantial load."},{"id": 2931,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Beyond the toe region, the linear portion of a ligament/tendon's stress-strain curve represents:","options": [{"key": "A","text": "Only the crimped fiber pattern"},{"key": "B","text": "No mechanical resistance"},{"key": "C","text": "Complete failure of the tissue"},{"key": "D","text": "The region where collagen fibers are being progressively recruited and stretched, exhibiting relatively constant stiffness"}],"correct": "D","explanation": "In the linear region, the straightened collagen fibers stretch together, giving the tissue a relatively constant stiffness (slope) until approaching the yield point."},{"id": 2932,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Ligament sprains are commonly graded (Grade I-III) based on:","options": [{"key": "A","text": "Muscle strength loss only"},{"key": "B","text": "Duration of symptoms only"},{"key": "C","text": "Bone involvement only"},{"key": "D","text": "The severity of fiber disruption, ranging from mild stretching (Grade I) to complete rupture (Grade III)"}],"correct": "D","explanation": "Ligament sprain grading reflects the extent of structural damage: Grade I is mild stretching/microtearing, Grade II is partial tear, and Grade III is complete rupture."},{"id": 2933,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Tendons are generally __________ stiff and __________ strong compared to the muscle they attach to.","options": [{"key": "A","text": "Less stiff; weaker"},{"key": "B","text": "Less stiff; stronger"},{"key": "C","text": "Equally stiff; equally strong"},{"key": "D","text": "More stiff; stronger (able to withstand greater tensile stress) for their cross-sectional area"}],"correct": "D","explanation": "Tendons are considerably stiffer and stronger in tension per unit cross-sectional area compared to the contractile muscle tissue they attach to."},{"id": 2934,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Immobilization of a joint has been shown to result in ligaments/tendons that are:","options": [{"key": "A","text": "Unaffected mechanically"},{"key": "B","text": "Improved in collagen organization"},{"key": "C","text": "Weaker, with reduced tensile strength and stiffness over time"},{"key": "D","text": "Stronger and stiffer"}],"correct": "C","explanation": "Prolonged immobilization leads to a decrease in collagen content, disorganization of fiber arrangement, and reduced mechanical strength/stiffness of ligaments and tendons."},{"id": 2935,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Controlled, progressive loading/exercise of ligaments and tendons after injury is generally believed to promote:","options": [{"key": "A","text": "Weaker collagen formation"},{"key": "B","text": "Complete tissue degeneration"},{"key": "C","text": "No change in tissue properties"},{"key": "D","text": "Improved collagen fiber alignment, cross-linking, and mechanical strength during healing"}],"correct": "D","explanation": "Appropriate mechanical loading during rehabilitation stimulates favorable collagen remodeling, improving fiber alignment and overall tensile strength of healing tissue."},{"id": 2936,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Skeletal muscle is classified biomechanically as a material capable of:","options": [{"key": "A","text": "Only plastic deformation with no elasticity"},{"key": "B","text": "Only viscous behavior with no elasticity"},{"key": "C","text": "Only passive elastic behavior"},{"key": "D","text": "Both active (contractile) force generation and passive elastic/viscoelastic behavior"}],"correct": "D","explanation": "Muscle uniquely combines active contractile force production (via cross-bridge cycling) with passive elastic and viscoelastic mechanical properties from its connective tissue components."},{"id": 2937,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The passive elastic properties of muscle are largely attributed to which structures?","options": [{"key": "A","text": "Blood vessels supplying the muscle"},{"key": "B","text": "Only the sarcomere's contractile proteins"},{"key": "C","text": "Connective tissue components such as the endomysium, perimysium, epimysium, and the protein titin"},{"key": "D","text": "Nerve endings within the muscle"}],"correct": "C","explanation": "Passive tension in muscle arises largely from its connective tissue framework (endo-, peri-, epimysium) and elastic proteins like titin within the sarcomere."},{"id": 2938,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A material that returns to its original shape immediately and completely after unloading, with no time-dependent behavior, is described as:","options": [{"key": "A","text": "Purely (linearly) elastic"},{"key": "B","text": "Plastic"},{"key": "C","text": "Viscoelastic"},{"key": "D","text": "Anisotropic"}],"correct": "A","explanation": "A purely elastic material exhibits instantaneous, complete recovery upon unloading, without any time-dependent (viscous) component."},{"id": 2939,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which connective tissue structure typically has the HIGHEST tensile strength per unit area?","options": [{"key": "A","text": "Articular cartilage"},{"key": "B","text": "Loose areolar connective tissue"},{"key": "C","text": "Tendon"},{"key": "D","text": "Ligament"}],"correct": "C","explanation": "Tendons, with their densely packed, parallel Type I collagen fibers, generally exhibit the highest tensile strength per cross-sectional area among the listed connective tissues."},{"id": 2940,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Fatigue failure' of a material refers to failure occurring due to:","options": [{"key": "A","text": "Repeated submaximal loading cycles over time, even below the material's ultimate strength"},{"key": "B","text": "A single, massive overload"},{"key": "C","text": "Complete absence of loading"},{"key": "D","text": "Immediate rupture on first load application"}],"correct": "A","explanation": "Fatigue failure develops from cumulative microdamage caused by repeated cyclic loading below the material's ultimate strength, eventually leading to structural failure (e.g., stress fractures)."},{"id": 2941,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A stress fracture in a runner is a classic clinical example of:","options": [{"key": "A","text": "Fatigue failure of bone due to repetitive submaximal loading exceeding the bone's remodeling capacity"},{"key": "B","text": "A fracture caused purely by osteoporosis"},{"key": "C","text": "A fracture with no mechanical basis"},{"key": "D","text": "Acute traumatic fracture from a single impact"}],"correct": "A","explanation": "Stress fractures result from repeated cyclic loading (as in running) that outpaces the bone's ability to remodel and repair, representing a classic fatigue failure."},{"id": 2942,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The rate at which a load is applied to connective tissue (strain rate) affects its mechanical response such that, generally, tissues loaded rapidly:","options": [{"key": "A","text": "Become more compliant/flexible"},{"key": "B","text": "Behave identically to slowly loaded tissue"},{"key": "C","text": "Tend to be stiffer and may fail at a higher load but with more brittle characteristics"},{"key": "D","text": "Show no viscoelastic rate-dependence"}],"correct": "C","explanation": "Due to their viscoelastic nature, connective tissues typically exhibit increased stiffness and altered failure characteristics (more brittle behavior) when loaded at higher strain rates."},{"id": 2943,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Slow, sustained stretching techniques used clinically to improve flexibility take advantage of which viscoelastic property of soft tissue?","options": [{"key": "A","text": "Creep (progressive elongation under sustained load)"},{"key": "B","text": "Ultimate tensile strength"},{"key": "C","text": "Anisotropy only"},{"key": "D","text": "Fatigue failure"}],"correct": "A","explanation": "Sustained stretch relies on the creep phenomenon, whereby tissue gradually elongates over time under a constant applied load, improving flexibility."},{"id": 2944,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Cartilage is generally categorized into three types; which type is found at the ends of long bones in synovial joints?","options": [{"key": "A","text": "Fibrocartilage"},{"key": "B","text": "Elastic cartilage"},{"key": "C","text": "Hyaline (articular) cartilage"},{"key": "D","text": "Calcified cartilage only"}],"correct": "C","explanation": "Hyaline cartilage, also termed articular cartilage in this context, covers the articulating ends of bones in synovial joints, providing a smooth, low-friction surface."},{"id": 2945,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Fibrocartilage, found in structures such as the intervertebral disc and menisci, is characterized biomechanically by:","options": [{"key": "A","text": "Only elastic fiber content"},{"key": "B","text": "Absence of any collagen"},{"key": "C","text": "A combination of dense collagen (Type I) fiber bundles providing high tensile strength along with some compressive resistance"},{"key": "D","text": "Pure hyaline structure with no collagen"}],"correct": "C","explanation": "Fibrocartilage contains dense Type I collagen bundles, giving it substantial tensile strength while also providing compressive load resistance, suited to structures like the menisci and IV discs."},{"id": 2946,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The intervertebral disc's nucleus pulposus functions biomechanically primarily to:","options": [{"key": "A","text": "Generate active muscular force"},{"key": "B","text": "Distribute compressive loads hydrostatically and allow for some multi-directional flexibility between vertebrae"},{"key": "C","text": "Provide rigid bony support"},{"key": "D","text": "Conduct electrical nerve signals"}],"correct": "B","explanation": "The gel-like nucleus pulposus distributes axial compressive loads via hydrostatic pressure, allowing the disc to absorb and transmit forces while permitting spinal motion."},{"id": 2947,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The annulus fibrosus of the intervertebral disc is structurally composed of:","options": [{"key": "A","text": "Bone tissue only"},{"key": "B","text": "Purely elastic cartilage with no collagen"},{"key": "C","text": "A single layer of hyaline cartilage"},{"key": "D","text": "Concentric layers (lamellae) of collagen fibers oriented in alternating directions, providing multidirectional tensile strength"}],"correct": "D","explanation": "The annulus fibrosus consists of multiple concentric lamellae with alternating collagen fiber orientations, allowing it to resist tensile and torsional stresses in various directions."},{"id": 2948,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Repeated flexion combined with compressive loading of the spine (as in improper lifting) is particularly associated with which type of disc injury pattern?","options": [{"key": "A","text": "Posterolateral disc herniation due to increased posterior annular stress and nuclear migration"},{"key": "B","text": "Injury restricted only to the vertebral body"},{"key": "C","text": "No increased risk of injury"},{"key": "D","text": "Injury only to the anterior annulus"}],"correct": "A","explanation": "Combined flexion and compression increase stress on the posterior annulus, promoting posterior/posterolateral migration of the nucleus and increasing herniation risk—hence the emphasis on proper lifting mechanics."},{"id": 2949,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A meniscus in the knee functions biomechanically to:","options": [{"key": "A","text": "Replace the function of the ACL entirely"},{"key": "B","text": "Increase joint congruency, distribute compressive load, and provide some shock absorption between femur and tibia"},{"key": "C","text": "Generate active contractile force"},{"key": "D","text": "Conduct nerve impulses only"}],"correct": "B","explanation": "The menisci deepen the tibial articulating surface, improve congruency with the femoral condyles, and help distribute and absorb compressive loads across the knee joint."},{"id": 2950,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Removal (meniscectomy) of a significant portion of the meniscus is associated with:","options": [{"key": "A","text": "No change in joint contact stress"},{"key": "B","text": "Decreased risk of osteoarthritis"},{"key": "C","text": "Improved shock absorption"},{"key": "D","text": "A significant increase in peak contact stress on the articular cartilage, predisposing to degenerative changes"}],"correct": "D","explanation": "Loss of meniscal tissue reduces the load-distributing surface area, increasing localized contact stress on the articular cartilage and elevating osteoarthritis risk over time."},{"id": 2951,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which best describes the general mechanical relationship between collagen content/organization and tissue tensile strength?","options": [{"key": "A","text": "More collagen always decreases tensile strength"},{"key": "B","text": "Collagen content has no bearing on tensile strength"},{"key": "C","text": "Greater, more organized collagen content generally correlates with greater tensile strength"},{"key": "D","text": "Only cross-sectional area matters, not collagen content"}],"correct": "C","explanation": "Tissues with denser, well-organized (parallel) collagen fiber content generally demonstrate greater tensile strength, as seen in tendon compared to less organized tissues."},{"id": 2952,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Aging is generally associated with connective tissue changes including:","options": [{"key": "A","text": "Improved viscoelastic recovery"},{"key": "B","text": "Decreased collagen turnover, increased stiffness, and reduced tensile strength/elasticity of tissues"},{"key": "C","text": "No change in tissue mechanical properties"},{"key": "D","text": "Increased collagen cross-linking flexibility and improved elasticity"}],"correct": "B","explanation": "Aging tissues typically show altered collagen cross-linking, reduced turnover, and diminished elasticity and tensile strength, contributing to increased injury susceptibility."},{"id": 2953,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why tendons are more prone to overuse injury (tendinopathy) with repetitive loading compared to acute rupture from a single load?","options": [{"key": "A","text": "Repetitive loading always strengthens tendons with no risk"},{"key": "B","text": "Tendons cannot bear any repetitive load"},{"key": "C","text": "Tendons regenerate perfectly regardless of load"},{"key": "D","text": "Cumulative microtrauma from repetitive submaximal loading can outpace the tissue's capacity to remodel/repair, leading to degenerative changes"}],"correct": "D","explanation": "Repeated submaximal loading without adequate recovery can cause cumulative microdamage exceeding the tendon's repair capacity, resulting in degenerative tendinopathy rather than acute rupture."},{"id": 2954,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Compression of a bone beyond its elastic limit but insufficient to cause complete fracture, sometimes seen in pediatric bone, is termed:","options": [{"key": "A","text": "A stress fracture only"},{"key": "B","text": "A spiral fracture"},{"key": "C","text": "A greenstick or buckle (torus) fracture, reflecting bone's greater plasticity in children"},{"key": "D","text": "A comminuted fracture"}],"correct": "C","explanation": "Children's bones, being more porous and pliable, can sustain incomplete fractures such as greenstick or buckle fractures rather than complete fracture under similar loads compared to adult bone."},{"id": 2955,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The mineral component of bone (hydroxyapatite) primarily contributes to bone's resistance to:","options": [{"key": "A","text": "Shear loading exclusively"},{"key": "B","text": "Compressive loading and overall stiffness"},{"key": "C","text": "Tensile loading only"},{"key": "D","text": "Torsional loading exclusively"}],"correct": "B","explanation": "The mineral (hydroxyapatite) component provides bone with its rigidity and compressive strength, while the organic collagen component contributes tensile and elastic properties."},{"id": 2956,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The organic (mainly collagen) component of bone contributes primarily to its:","options": [{"key": "A","text": "Cartilage-like lubrication"},{"key": "B","text": "Compressive strength only"},{"key": "C","text": "Electrical conductivity"},{"key": "D","text": "Tensile strength and some flexibility/toughness"}],"correct": "D","explanation": "Collagen within bone provides tensile strength and a degree of flexibility/toughness, complementing the compressive strength provided by mineral content."},{"id": 2957,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A bone that has lost mineral content (e.g., in osteomalacia) while maintaining collagen would be expected to become:","options": [{"key": "A","text": "Unaffected mechanically"},{"key": "B","text": "Stiffer and more brittle"},{"key": "C","text": "Softer and more prone to bending deformity, with reduced stiffness"},{"key": "D","text": "Completely rigid"}],"correct": "C","explanation": "Reduced mineralization decreases bone stiffness, making it softer and more prone to bending or deformity, as classically seen in osteomalacia/rickets."},{"id": 2958,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Excessive mineralization or loss of collagen's contribution (as in some brittle bone conditions) would be expected to make bone:","options": [{"key": "A","text": "Unaffected in strength"},{"key": "B","text": "Only weaker in compression"},{"key": "C","text": "Stiffer but more brittle, with reduced capacity to absorb energy before fracture"},{"key": "D","text": "More flexible and less likely to fracture"}],"correct": "C","explanation": "Loss of the collagen (organic) component's contribution to toughness, with relatively greater mineral dominance, results in a stiffer but more brittle bone prone to fracture with less energy absorption."},{"id": 2959,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Cortical (compact) bone, compared to cancellous (trabecular) bone, is generally:","options": [{"key": "A","text": "Denser, stiffer, and stronger, but less able to absorb energy through deformation"},{"key": "B","text": "Less dense and more porous"},{"key": "C","text": "Identical in mechanical properties"},{"key": "D","text": "Found only in the skull"}],"correct": "A","explanation": "Cortical bone is dense and stiff, providing strength, while cancellous bone is more porous, offering greater capacity to deform and absorb energy, aiding shock absorption at joint ends."},{"id": 2960,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Cancellous (trabecular) bone is predominantly found at:","options": [{"key": "A","text": "Only within ligaments"},{"key": "B","text": "The ends (epiphyses/metaphyses) of long bones and within vertebral bodies"},{"key": "C","text": "The shaft (diaphysis) of long bones"},{"key": "D","text": "Only within tendons"}],"correct": "B","explanation": "Cancellous bone's porous, trabecular architecture is concentrated at the metaphyseal/epiphyseal regions of long bones and throughout vertebral bodies, well-suited to absorb and distribute loads near joints."},{"id": 2961,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which structural arrangement gives cortical bone its characteristic strength and organization?","options": [{"key": "A","text": "Random collagen fibers with no organization"},{"key": "B","text": "Isolated chondrocytes in lacunae only"},{"key": "C","text": "Osteons (Haversian systems) consisting of concentric lamellae surrounding a central Haversian canal"},{"key": "D","text": "Loose areolar tissue arrangement"}],"correct": "C","explanation": "Cortical bone is organized into osteons (Haversian systems), with concentric bony lamellae arranged around a central canal, contributing to its strength and resistance to loading."},{"id": 2962,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The general biomechanical principle that 'form follows function' in connective tissue is best exemplified by:","options": [{"key": "A","text": "Identical tissue architecture at all anatomical sites"},{"key": "B","text": "No relationship between structure and mechanical demand"},{"key": "C","text": "Structures like tendons having parallel collagen fibers optimized for uniaxial tension, while cartilage matrix is optimized for compressive load distribution"},{"key": "D","text": "Random tissue distribution regardless of load"}],"correct": "C","explanation": "Connective tissues develop structural arrangements (e.g., collagen orientation, matrix composition) specifically suited to the predominant type of mechanical loading they experience."},{"id": 2963,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which best explains why a ligament sprain (e.g., ankle inversion sprain) commonly occurs at a rate faster than voluntary muscular protection can respond?","options": [{"key": "A","text": "Ligament injury is unrelated to movement speed"},{"key": "B","text": "Ligaments have very slow load response times"},{"key": "C","text": "Muscles always react before ligament strain occurs"},{"key": "D","text": "The injurious force/movement often occurs faster than the neuromuscular reflex latency needed for protective muscular contraction"}],"correct": "D","explanation": "Sudden, high-velocity movements (like an ankle roll) can exceed the reflex response time of stabilizing muscles, leaving the ligament to absorb the load directly, increasing injury risk."},{"id": 2964,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The concept of a tissue's 'safety factor' in biomechanics refers to:","options": [{"key": "A","text": "The ratio between the load a tissue can withstand and the load it typically experiences during normal activity"},{"key": "B","text": "The color-coding used for exercise resistance bands"},{"key": "C","text": "A measure of nerve conduction velocity"},{"key": "D","text": "The exact load at which failure always occurs"}],"correct": "A","explanation": "Safety factor reflects the margin between a tissue's failure threshold and the loads normally encountered, providing a buffer against injury during typical activity."},{"id": 2965,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "The functional contractile unit of skeletal muscle is the:","options": [{"key": "A","text": "Fascicle"},{"key": "B","text": "Sarcomere"},{"key": "C","text": "Endomysium"},{"key": "D","text": "Myofibril"}],"correct": "B","explanation": "The sarcomere, bounded by two Z-lines, is the basic contractile unit where actin and myosin interact to produce force."},{"id": 2966,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "According to the sliding filament theory, muscle contraction occurs due to:","options": [{"key": "A","text": "Actin filaments sliding over myosin filaments, without the filaments themselves shortening"},{"key": "B","text": "Breakdown of the Z-line"},{"key": "C","text": "Shortening of actin and myosin filaments themselves"},{"key": "D","text": "Lengthening of the sarcomere"}],"correct": "A","explanation": "The sliding filament theory states that thin (actin) filaments slide past thick (myosin) filaments via cross-bridge cycling, without either filament changing its own length."},{"id": 2967,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "The length-tension relationship of skeletal muscle describes:","options": [{"key": "A","text": "The relationship between muscle mass and bone density"},{"key": "B","text": "How the force a muscle can generate varies depending on its length (degree of actin-myosin overlap)"},{"key": "C","text": "The rate of ATP consumption during contraction"},{"key": "D","text": "The relationship between muscle force output and the speed of contraction"}],"correct": "B","explanation": "The length-tension relationship shows that a muscle's force-generating capacity depends on its length, which determines the degree of actin-myosin cross-bridge overlap."},{"id": 2968,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Maximum active tension in a muscle is typically generated at:","options": [{"key": "A","text": "Very short muscle lengths, with minimal overlap"},{"key": "B","text": "Maximum muscle stretch, at the longest possible length"},{"key": "C","text": "A resting or near-optimal length, where actin-myosin overlap is optimal for maximal cross-bridge formation"},{"key": "D","text": "Only during eccentric contraction"}],"correct": "C","explanation": "Peak active tension occurs near the muscle's optimal (resting) length, where the greatest number of actin-myosin cross-bridges can form."},{"id": 2969,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "At very short muscle lengths, active tension decreases primarily because:","options": [{"key": "A","text": "Actin filaments overlap each other, reducing effective cross-bridge formation, and the muscle may reach the limits of shortening"},{"key": "B","text": "Cross-bridges increase in number"},{"key": "C","text": "ATP is unavailable"},{"key": "D","text": "The muscle fiber is at its optimal length"}],"correct": "A","explanation": "At very short lengths, thin filaments from opposite ends overlap and interfere with each other, and the muscle nears its shortening limit, both reducing effective force generation."},{"id": 2970,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "At very long (overstretched) muscle lengths, active tension decreases primarily because:","options": [{"key": "A","text": "ATP production increases excessively"},{"key": "B","text": "There is excessive actin-myosin overlap"},{"key": "C","text": "There is insufficient actin-myosin overlap for adequate cross-bridge formation"},{"key": "D","text": "The Z-lines disappear entirely"}],"correct": "C","explanation": "Excessive muscle lengthening reduces the overlap between actin and myosin filaments, decreasing the number of cross-bridges that can form and thus reducing active tension."},{"id": 2971,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Passive tension in a stretched muscle arises primarily from:","options": [{"key": "A","text": "Active cross-bridge cycling"},{"key": "B","text": "The resistance of non-contractile connective tissue elements (e.g., titin, endomysium, perimysium)"},{"key": "C","text": "Motor neuron firing rate"},{"key": "D","text": "ATP hydrolysis"}],"correct": "B","explanation": "Passive tension results from the elastic resistance of muscle's connective tissue components (titin, fascia) as the muscle is stretched beyond its resting length, independent of active contraction."},{"id": 2972,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The 'total tension' curve of a muscle at any given length represents:","options": [{"key": "A","text": "Only passive tension"},{"key": "B","text": "Only active tension"},{"key": "C","text": "Neither active nor passive tension"},{"key": "D","text": "The sum of active and passive tension at that length"}],"correct": "D","explanation": "Total tension is the combined contribution of both active (contractile) tension and passive (elastic connective tissue) tension at a given muscle length."},{"id": 2973,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "A muscle that is passively stretched to a very long length before contraction will exhibit __________ passive tension and potentially __________ active tension.","options": [{"key": "A","text": "Zero; maximal"},{"key": "B","text": "High; potentially reduced (if beyond optimal overlap)"},{"key": "C","text": "Low; high"},{"key": "D","text": "High; unchanged always"}],"correct": "B","explanation": "At very long lengths, passive (connective tissue) tension increases substantially, while active tension may decrease if the length exceeds the optimal actin-myosin overlap range."},{"id": 2974,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The active insufficiency of a two-joint muscle occurs when the muscle is:","options": [{"key": "A","text": "Stretched over both joints simultaneously, allowing maximal tension"},{"key": "B","text": "Shortened over both joints simultaneously, reducing its ability to generate additional useful tension"},{"key": "C","text": "Passively stretched only"},{"key": "D","text": "At its resting length at both joints"}],"correct": "B","explanation": "Active insufficiency occurs when a multi-joint muscle shortens over both joints at once, reaching a length too short to generate effective additional force (e.g., finger flexors weak when wrist is also flexed)."},{"id": 2975,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Passive insufficiency of a two-joint muscle occurs when the muscle is:","options": [{"key": "A","text": "At its optimal length"},{"key": "B","text": "Shortened at both joints"},{"key": "C","text": "Stretched over both joints simultaneously, limiting the range of motion at one joint because the muscle cannot lengthen further"},{"key": "D","text": "Unaffected by joint position"}],"correct": "C","explanation": "Passive insufficiency occurs when a two-joint muscle is lengthened over both joints to the point where it restricts further motion, since it cannot stretch beyond its extensibility limit."},{"id": 2976,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "A classic clinical example of active insufficiency is:","options": [{"key": "A","text": "The hamstrings limiting hip flexion when the knee is extended (straight leg raise)"},{"key": "B","text": "The rectus femoris limiting hip extension with the knee flexed"},{"key": "C","text": "The finger flexors being unable to make a full fist when the wrist is also fully flexed"},{"key": "D","text": "The gastrocnemius limiting dorsiflexion with the knee extended"}],"correct": "C","explanation": "When the wrist is flexed, the finger flexors shorten over both the wrist and finger joints, reducing their ability to generate a strong grip—classic active insufficiency."},{"id": 2977,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "A classic clinical example of passive insufficiency is:","options": [{"key": "A","text": "The hamstrings limiting the ability to achieve full hip flexion with the knee extended (limited straight leg raise)"},{"key": "B","text": "Maximal grip strength with wrist flexed"},{"key": "C","text": "Full fist formation with the wrist extended"},{"key": "D","text": "Unlimited ROM regardless of muscle length"}],"correct": "A","explanation": "With the knee extended, the two-joint hamstrings are already lengthened over the knee, limiting further hip flexion range due to passive insufficiency."},{"id": 2978,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "The force-velocity relationship of skeletal muscle describes the inverse relationship between:","options": [{"key": "A","text": "Muscle length and passive tension"},{"key": "B","text": "Muscle fiber type and fiber diameter"},{"key": "C","text": "The velocity of muscle shortening and the force the muscle can produce during concentric contraction"},{"key": "D","text": "Muscle temperature and fatigue"}],"correct": "C","explanation": "The force-velocity curve shows that as the speed of concentric muscle shortening increases, the maximum force the muscle can generate decreases."},{"id": 2979,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "According to the force-velocity relationship, the greatest force a muscle can generate concentrically occurs at:","options": [{"key": "A","text": "Maximum shortening velocity"},{"key": "B","text": "Moderate shortening velocity only"},{"key": "C","text": "Only during eccentric contraction"},{"key": "D","text": "Zero velocity (isometric contraction), which represents the upper limit as velocity approaches zero on the concentric side"}],"correct": "D","explanation": "As shortening velocity approaches zero, the concentric force capacity approaches its maximum, consistent with the classic hyperbolic force-velocity curve (Hill's equation)."},{"id": 2980,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "During eccentric muscle contraction, as the velocity of lengthening increases, the force the muscle can generate:","options": [{"key": "A","text": "Drops to zero immediately"},{"key": "B","text": "Continues to decrease, as in concentric contraction"},{"key": "C","text": "Remains exactly equal to concentric force at the same speed"},{"key": "D","text": "Initially increases and can exceed the maximum isometric force"}],"correct": "D","explanation": "Unlike concentric contraction, eccentric force capacity increases with lengthening velocity (up to a point) and can exceed maximal isometric force, a key distinguishing feature of the eccentric force-velocity relationship."},{"id": 2981,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which type of contraction generally allows a muscle to generate the greatest force output?","options": [{"key": "A","text": "Eccentric"},{"key": "B","text": "Isometric"},{"key": "C","text": "Isotonic at high speed"},{"key": "D","text": "Concentric"}],"correct": "A","explanation": "Eccentric contractions typically allow generation of the greatest force among contraction types, due to the unique mechanical behavior of muscle when actively lengthening under load."},{"id": 2982,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "A concentric contraction is defined as one in which:","options": [{"key": "A","text": "No tension is produced"},{"key": "B","text": "The muscle lengthens while producing tension"},{"key": "C","text": "The muscle length remains constant"},{"key": "D","text": "The muscle shortens while producing tension, moving the joint in the direction of the contraction"}],"correct": "D","explanation": "Concentric contraction involves muscle shortening while generating force, producing joint movement in the direction of the muscle pull (e.g., biceps shortening during elbow flexion against gravity)."},{"id": 2983,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "An eccentric contraction is defined as one in which:","options": [{"key": "A","text": "The muscle length remains completely unchanged"},{"key": "B","text": "The muscle lengthens while producing tension, controlling movement against an external force (e.g., lowering a weight)"},{"key": "C","text": "The muscle shortens while producing tension"},{"key": "D","text": "No motor units are activated"}],"correct": "B","explanation": "Eccentric contraction occurs when a muscle actively lengthens while generating tension, typically to control or decelerate a movement, such as lowering a weight in a controlled manner."},{"id": 2984,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "An isometric contraction is defined as one in which:","options": [{"key": "A","text": "The muscle generates tension without a significant change in muscle length or joint angle"},{"key": "B","text": "The muscle changes length significantly"},{"key": "C","text": "The muscle always lengthens"},{"key": "D","text": "The muscle always shortens"}],"correct": "A","explanation": "Isometric contraction produces tension while muscle length and joint angle remain essentially unchanged, as in a static hold."},{"id": 2985,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The term 'isotonic contraction' classically refers to a contraction in which:","options": [{"key": "A","text": "Muscle tension remains theoretically constant throughout the range of motion while the muscle changes length"},{"key": "B","text": "Muscle length remains constant"},{"key": "C","text": "No movement occurs"},{"key": "D","text": "Tension varies but length is constant"}],"correct": "A","explanation": "Isotonic contraction traditionally describes constant tension throughout a changing muscle length, though in practice tension actually varies somewhat with joint angle changes (moment arm)."},{"id": 2986,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "An 'isokinetic' contraction is characterized by:","options": [{"key": "A","text": "Constant angular velocity of joint movement, with resistance accommodating to allow maximal muscle effort throughout range"},{"key": "B","text": "Zero velocity throughout"},{"key": "C","text": "Only eccentric loading"},{"key": "D","text": "Constant muscle length with varying tension"}],"correct": "A","explanation": "Isokinetic contraction, typically performed using specialized dynamometers, maintains a constant angular velocity while providing accommodating resistance matched to the muscle's force output throughout the range."},{"id": 2987,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Eccentric exercise is often used clinically in tendinopathy rehabilitation (e.g., Achilles tendinopathy) primarily because it is believed to promote:","options": [{"key": "A","text": "Beneficial tendon remodeling and collagen realignment, along with increased tendon load tolerance"},{"key": "B","text": "Decreased tendon stiffness only"},{"key": "C","text": "Muscle atrophy"},{"key": "D","text": "Rapid tendon rupture"}],"correct": "A","explanation": "Controlled eccentric loading protocols are thought to stimulate favorable collagen remodeling and improve the tendon's capacity to tolerate load, aiding recovery from tendinopathy."},{"id": 2988,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Delayed onset muscle soreness (DOMS) is most strongly associated with which type of muscle contraction?","options": [{"key": "A","text": "Isokinetic contraction at low speed"},{"key": "B","text": "Eccentric contraction, particularly unaccustomed or high-intensity eccentric loading"},{"key": "C","text": "Isometric contraction"},{"key": "D","text": "Concentric contraction"}],"correct": "B","explanation": "Eccentric contractions, especially when unaccustomed or high-force, are most strongly linked to microtrauma and the resultant delayed onset muscle soreness."},{"id": 2989,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Motor unit recruitment refers to:","options": [{"key": "A","text": "Passive stretching of the muscle"},{"key": "B","text": "The process of activating an increasing number of motor units to increase the force of contraction"},{"key": "C","text": "Muscle fiber hypertrophy"},{"key": "D","text": "The rate of ATP breakdown"}],"correct": "B","explanation": "Motor unit recruitment describes the progressive activation of additional motor units as greater force output is required from a muscle."},{"id": 2990,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'size principle' of motor unit recruitment states that motor units are typically recruited in order of:","options": [{"key": "A","text": "Smallest (low-threshold, fatigue-resistant) to largest (high-threshold, fast-fatiguing), as force demand increases"},{"key": "B","text": "Largest to smallest"},{"key": "C","text": "Fastest to slowest only"},{"key": "D","text": "Random order regardless of size"}],"correct": "A","explanation": "The size principle describes that smaller, lower-threshold motor units (often slow-twitch) are recruited first, with larger, higher-threshold motor units recruited as greater force is needed."},{"id": 2991,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Rate coding' refers to:","options": [{"key": "A","text": "The rate of passive muscle stretch"},{"key": "B","text": "The frequency of action potentials (firing rate) of an already-recruited motor unit, which influences force output"},{"key": "C","text": "The speed of muscle shortening only"},{"key": "D","text": "The number of motor units recruited"}],"correct": "B","explanation": "Rate coding describes the modulation of firing frequency of motor neurons, where higher firing rates produce greater summation of twitches and increased force output."},{"id": 2992,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "A single action potential delivered to a muscle fiber produces a:","options": [{"key": "A","text": "Tetanic contraction"},{"key": "B","text": "No contraction at all"},{"key": "C","text": "Single twitch contraction, consisting of a brief contraction followed by relaxation"},{"key": "D","text": "Sustained isometric hold indefinitely"}],"correct": "C","explanation": "A single stimulus produces a twitch—a brief contraction-relaxation cycle—which is the basic unit of muscle mechanical response."},{"id": 2993,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Wave summation' occurs when:","options": [{"key": "A","text": "Successive stimuli arrive before the muscle fully relaxes from the previous twitch, resulting in increased (summated) tension"},{"key": "B","text": "A single twitch produces maximal force"},{"key": "C","text": "The muscle is completely relaxed between every stimulus"},{"key": "D","text": "Only eccentric contractions occur"}],"correct": "A","explanation": "Wave summation occurs when repeated stimuli are delivered rapidly enough that the muscle doesn't fully relax between twitches, leading to progressively increased tension."},{"id": 2994,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "'Tetanus' (tetanic contraction) in muscle physiology refers to:","options": [{"key": "A","text": "A single isolated twitch"},{"key": "B","text": "A contraction that only occurs eccentrically"},{"key": "C","text": "A sustained, fused maximal contraction resulting from a sufficiently high stimulation frequency that individual twitches fuse together"},{"key": "D","text": "Complete muscle relaxation"}],"correct": "C","explanation": "Tetanus is a smooth, sustained maximal contraction produced when the stimulation frequency is high enough that successive twitches fuse into one continuous contraction."},{"id": 2995,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "Muscle fiber types are broadly classified into:","options": [{"key": "A","text": "Type A and Type B fibers only"},{"key": "B","text": "Red fibers and white fibers with no functional difference"},{"key": "C","text": "Only one uniform fiber type exists"},{"key": "D","text": "Type I (slow-twitch, fatigue-resistant) and Type II (fast-twitch, more easily fatigued)"}],"correct": "D","explanation": "Skeletal muscle fibers are broadly categorized as Type I (slow oxidative, fatigue-resistant) and Type II (fast glycolytic/oxidative, more rapidly fatiguing but higher force/speed)."},{"id": 2996,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Type I muscle fibers are best suited for activities requiring:","options": [{"key": "A","text": "Short bursts of maximal power"},{"key": "B","text": "Sustained, low-intensity activity requiring endurance (e.g., postural maintenance)"},{"key": "C","text": "Only eccentric contraction"},{"key": "D","text": "Rapid, explosive contraction only"}],"correct": "B","explanation": "Type I (slow-twitch) fibers are fatigue-resistant and well-suited for prolonged, low-intensity activities such as maintaining posture."},{"id": 2997,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Type II muscle fibers are best suited for activities requiring:","options": [{"key": "A","text": "Rapid, powerful, short-duration contractions (e.g., sprinting, jumping), but with quicker fatigue"},{"key": "B","text": "Only isometric holding for long durations"},{"key": "C","text": "Prolonged, low-intensity endurance activity"},{"key": "D","text": "No mechanical contribution to movement"}],"correct": "A","explanation": "Type II (fast-twitch) fibers generate force rapidly and powerfully but fatigue more quickly than Type I fibers, suiting explosive, short-duration activities."},{"id": 2998,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Muscle physiological cross-sectional area (PCSA) is directly related to a muscle's capacity to generate:","options": [{"key": "A","text": "Fatigue resistance only"},{"key": "B","text": "Range of motion"},{"key": "C","text": "Maximal force (force-generating capacity is roughly proportional to PCSA)"},{"key": "D","text": "Speed of contraction"}],"correct": "C","explanation": "A muscle's maximal force output is roughly proportional to its physiological cross-sectional area, reflecting the total number of sarcomeres arranged in parallel."},{"id": 2999,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "Pennate (pennation) muscle architecture, in which fibers are arranged at an angle to the tendon, generally results in:","options": [{"key": "A","text": "Greater range of motion and speed of shortening compared to fiber length equivalent parallel muscles"},{"key": "B","text": "Greater force-generating capacity for a given muscle volume, due to increased PCSA, but reduced excursion/speed compared to a parallel-fibered muscle of the same volume"},{"key": "C","text": "No functional difference from parallel muscle fibers"},{"key": "D","text": "Complete inability to generate active tension"}],"correct": "B","explanation": "Pennate architecture packs more fibers into a given muscle volume (increasing PCSA and force potential), though at the cost of reduced fiber excursion and shortening velocity compared to longitudinally arranged fibers."},{"id": 3000,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Fusiform (parallel-fibered) muscles, such as the biceps brachii, are generally better suited for:","options": [{"key": "A","text": "No functional movement capability"},{"key": "B","text": "Only isometric contraction"},{"key": "C","text": "Maximal force production per unit volume"},{"key": "D","text": "Greater range of motion and faster shortening velocity, at the expense of maximal force relative to pennate muscles of similar volume"}],"correct": "D","explanation": "Fusiform muscles have longer fibers running roughly parallel to the tendon, allowing greater excursion and faster shortening speed, though generally producing less force per unit volume than pennate muscles."},{"id": 3001,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The angle of pennation in a pennate muscle refers to:","options": [{"key": "A","text": "The joint angle during contraction"},{"key": "B","text": "The angle of the muscle's origin relative to bone"},{"key": "C","text": "The angle between the muscle fiber and the muscle's tendon (line of pull)"},{"key": "D","text": "The angle between two separate muscles"}],"correct": "C","explanation": "Pennation angle describes the angle at which individual muscle fibers are oriented relative to the tendon's overall line of pull."},{"id": 3002,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "As pennation angle increases, the effective force transmitted to the tendon along its line of pull for a given fiber tension tends to:","options": [{"key": "A","text": "Increase proportionally with angle"},{"key": "B","text": "Decrease, since only the force component parallel to the tendon contributes to effective pull (cosine of the pennation angle)"},{"key": "C","text": "Remain unaffected by angle"},{"key": "D","text": "Become negative"}],"correct": "B","explanation": "Since only the component of fiber force parallel to the tendon direction contributes effectively, increasing pennation angle reduces the effective force transmission (force × cos(angle))."},{"id": 3003,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Muscle stiffness generally __________ with increasing activation (contraction intensity).","options": [{"key": "A","text": "Becomes negative"},{"key": "B","text": "Decreases"},{"key": "C","text": "Increases"},{"key": "D","text": "Remains completely unchanged"}],"correct": "C","explanation": "As a muscle actively contracts and increases its level of activation, its overall stiffness increases due to greater cross-bridge attachment and connective tissue tension."},{"id": 3004,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'stretch-shortening cycle' (SSC) refers to a movement pattern involving:","options": [{"key": "A","text": "Only concentric contraction"},{"key": "B","text": "Only isometric holding"},{"key": "C","text": "Passive stretching with no active contraction"},{"key": "D","text": "A rapid eccentric (lengthening) contraction immediately followed by a concentric (shortening) contraction, enhancing power output"}],"correct": "D","explanation": "The SSC utilizes a quick eccentric pre-stretch followed immediately by concentric contraction, allowing elastic energy storage/release and reflexive potentiation to enhance subsequent force/power output (e.g., countermovement jump)."},{"id": 3005,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A countermovement jump (dipping down before jumping up) typically results in a __________ jump height compared to a squat jump (starting from a static, held position).","options": [{"key": "A","text": "Lower"},{"key": "B","text": "Higher, due to utilization of the stretch-shortening cycle"},{"key": "C","text": "Completely unpredictable"},{"key": "D","text": "Identical"}],"correct": "B","explanation": "The countermovement jump benefits from the stretch-shortening cycle (rapid eccentric loading followed by concentric contraction), enhancing power output and jump height compared to a static squat jump."},{"id": 3006,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "Muscle fatigue is best defined as:","options": [{"key": "A","text": "Permanent loss of contractile ability"},{"key": "B","text": "A temporary, reversible decline in the force-generating capacity of a muscle with continued activity"},{"key": "C","text": "Instantaneous muscle rupture"},{"key": "D","text": "A condition unrelated to exercise intensity or duration"}],"correct": "B","explanation": "Fatigue represents a temporary, reversible reduction in a muscle's ability to generate force, occurring with sustained or repeated activity and recovering with rest."},{"id": 3007,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best describes 'electromechanical delay'?","options": [{"key": "A","text": "The brief time lag between the onset of electrical activation (EMG signal) of a muscle and the actual onset of mechanical force/tension development"},{"key": "B","text": "The delay in nerve conduction from the brain to spinal cord"},{"key": "C","text": "A synonym for reaction time to a visual stimulus"},{"key": "D","text": "The time between removal of a stimulus and muscle relaxation"}],"correct": "A","explanation": "Electromechanical delay describes the short time interval between muscle electrical activation (detectable via EMG) and the resulting generation of measurable mechanical tension/force."},{"id": 3008,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "A muscle's 'optimal length' for tension generation typically corresponds closely to its:","options": [{"key": "A","text": "Resting length within the body, near the peak of the length-tension curve"},{"key": "B","text": "A length that varies randomly with no biomechanical basis"},{"key": "C","text": "Fully passively stretched length only"},{"key": "D","text": "Maximally shortened length"}],"correct": "A","explanation": "A muscle's optimal length for maximal active tension generally corresponds closely to its normal physiological resting length in vivo, at the peak of the length-tension curve."},{"id": 3009,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which best explains why performing a bicep curl feels 'easiest' in the middle of the range and often feels weaker near full extension or full flexion?","options": [{"key": "A","text": "Muscle fatigue occurs mid-range"},{"key": "B","text": "The length-tension relationship, combined with the changing moment arm/torque throughout the range, creates a 'sticking point' region of relative weakness at the extremes"},{"key": "C","text": "Tendon length changes randomly"},{"key": "D","text": "Blood flow is reduced mid-range"}],"correct": "B","explanation": "The combined effect of the muscle's length-tension properties and the changing mechanical advantage (moment arm) throughout the joint range creates points of relative strength and weakness across the range of motion."},{"id": 3010,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Static stretching held for a prolonged duration primarily targets which viscoelastic property to increase muscle-tendon extensibility?","options": [{"key": "A","text": "Creep, allowing gradual elongation under sustained tension"},{"key": "B","text": "Motor unit recruitment"},{"key": "C","text": "Fatigue resistance"},{"key": "D","text": "Rate coding"}],"correct": "A","explanation": "Prolonged static stretching relies on the creep phenomenon of viscoelastic tissue, allowing gradual lengthening under a sustained, constant stretching force."},{"id": 3011,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Ballistic (bouncing) stretching differs from static stretching in that it involves:","options": [{"key": "A","text": "No movement at all"},{"key": "B","text": "Only isometric contraction"},{"key": "C","text": "Rapid, repetitive bouncing movements at end range, which may activate the stretch reflex and increase injury risk in some cases"},{"key": "D","text": "Slow, sustained holds at end range"}],"correct": "C","explanation": "Ballistic stretching uses fast, repetitive bouncing motions, which can trigger the stretch reflex (via muscle spindles) and potentially increase risk of injury compared to slower static stretching."},{"id": 3012,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Proprioceptive neuromuscular facilitation (PNF) stretching techniques, such as contract-relax, are thought to enhance flexibility partly through:","options": [{"key": "A","text": "Increasing muscle spindle sensitivity only"},{"key": "B","text": "Eliminating all connective tissue resistance permanently"},{"key": "C","text": "Autogenic inhibition via Golgi tendon organ activation, temporarily reducing reflexive muscle resistance to stretch"},{"key": "D","text": "Increasing pennation angle"}],"correct": "C","explanation": "PNF techniques utilize autogenic inhibition, where GTO activation during the contraction phase temporarily reduces the muscle's reflexive resistance, facilitating greater subsequent stretch."},{"id": 3013,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The muscle spindle is a sensory receptor primarily responsible for detecting:","options": [{"key": "A","text": "Joint pressure only"},{"key": "B","text": "Changes in muscle length and the rate of length change (stretch)"},{"key": "C","text": "Skin temperature"},{"key": "D","text": "Muscle tension only"}],"correct": "B","explanation": "Muscle spindles are stretch receptors embedded within muscle that detect changes in muscle length and the velocity of stretching, triggering reflexive responses."},{"id": 3014,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The Golgi tendon organ (GTO) is a sensory receptor located primarily within:","options": [{"key": "A","text": "The muscle belly, detecting length changes"},{"key": "B","text": "The skin, detecting touch"},{"key": "C","text": "The joint capsule, detecting joint position"},{"key": "D","text": "The musculotendinous junction, detecting changes in muscle tension"}],"correct": "D","explanation": "GTOs are located at the junction between muscle and tendon, primarily sensitive to changes in muscular tension rather than length."},{"id": 3015,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Excessive tension detected by the GTO can trigger a protective reflex called:","options": [{"key": "A","text": "Autogenic inhibition, causing reflexive relaxation of the associated muscle"},{"key": "B","text": "The stretch reflex (myotatic reflex)"},{"key": "C","text": "Reciprocal inhibition of the antagonist only"},{"key": "D","text": "The withdrawal reflex"}],"correct": "A","explanation": "When GTO senses excessive tension, it can trigger autogenic inhibition—a protective reflex that causes the associated muscle to relax, reducing risk of tissue damage from excessive force."},{"id": 3016,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The stretch (myotatic) reflex, mediated by the muscle spindle, results in:","options": [{"key": "A","text": "No neuromuscular response"},{"key": "B","text": "Reflexive relaxation of the stretched muscle"},{"key": "C","text": "Reflexive contraction of the muscle being rapidly stretched, helping resist the stretch"},{"key": "D","text": "Contraction of the antagonist muscle only"}],"correct": "C","explanation": "The myotatic (stretch) reflex causes the rapidly stretched muscle to reflexively contract, helping to resist further stretch and protect the muscle from potential overstretch injury."},{"id": 3017,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Reciprocal inhibition refers to the neurophysiological phenomenon in which:","options": [{"key": "A","text": "The stretch reflex is eliminated entirely"},{"key": "B","text": "Contraction of an agonist muscle is accompanied by simultaneous reflexive inhibition (relaxation) of its direct antagonist"},{"key": "C","text": "Both agonist and antagonist contract maximally together at all times"},{"key": "D","text": "Only the antagonist muscle is ever active"}],"correct": "B","explanation": "Reciprocal inhibition describes the spinal reflex mechanism by which activation of an agonist muscle is accompanied by simultaneous relaxation/inhibition of its antagonist, facilitating smooth movement."},{"id": 3018,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Co-contraction of agonist and antagonist muscles around a joint primarily serves to:","options": [{"key": "A","text": "Maximize speed of movement"},{"key": "B","text": "Eliminate all joint movement permanently"},{"key": "C","text": "Decrease metabolic demand"},{"key": "D","text": "Increase joint stability, particularly useful in situations requiring fine control or protection against unexpected perturbations"}],"correct": "D","explanation": "Simultaneous agonist-antagonist co-contraction increases joint stiffness and stability, which is often utilized for postural control, balance, or protecting an unstable/injured joint."},{"id": 3019,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "A muscle acting as a 'prime mover' (agonist) for a given movement is the muscle that:","options": [{"key": "A","text": "Opposes the desired movement"},{"key": "B","text": "Is primarily responsible for producing the desired movement"},{"key": "C","text": "Only stabilizes a proximal joint"},{"key": "D","text": "Has no direct role in the movement"}],"correct": "B","explanation": "The agonist (prime mover) is the muscle primarily responsible for generating the force needed to produce a specific desired movement."},{"id": 3020,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "A muscle acting as a 'synergist' during a movement functions to:","options": [{"key": "A","text": "Assist the prime mover, often by stabilizing a joint or preventing unwanted secondary movement"},{"key": "B","text": "Directly oppose the prime mover"},{"key": "C","text": "Only act eccentrically"},{"key": "D","text": "Provide no functional contribution"}],"correct": "A","explanation": "Synergist muscles assist the agonist, often by stabilizing adjacent joints or counteracting unwanted secondary actions, to ensure efficient, controlled movement."},{"id": 3021,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "A muscle acting as a 'stabilizer' (fixator) primarily functions to:","options": [{"key": "A","text": "Directly oppose the agonist at all times"},{"key": "B","text": "Produce the primary joint movement"},{"key": "C","text": "Hold one segment (often a proximal bone/joint) stationary so that another muscle can effectively act on a distal segment"},{"key": "D","text": "Only function during eccentric contraction"}],"correct": "C","explanation": "Stabilizer (fixator) muscles maintain a fixed position of a proximal segment, providing a stable base from which other muscles can effectively produce movement distally."},{"id": 3022,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Muscle power is calculated as the product of:","options": [{"key": "A","text": "Force and velocity of muscle shortening"},{"key": "B","text": "Force and displacement only"},{"key": "C","text": "Mass and acceleration"},{"key": "D","text": "Length and cross-sectional area"}],"correct": "A","explanation": "Muscular power output equals the force generated multiplied by the velocity at which the muscle shortens (Power = Force × Velocity)."},{"id": 3023,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "According to the force-velocity relationship, the point of maximal mechanical power output for a muscle typically occurs at:","options": [{"key": "A","text": "Only during eccentric loading"},{"key": "B","text": "Maximum possible shortening velocity"},{"key": "C","text": "Zero velocity (pure isometric contraction)"},{"key": "D","text": "An intermediate velocity and force, reflecting the trade-off described by the force-velocity curve"}],"correct": "D","explanation": "Since power = force × velocity, and both extremes (max force at zero velocity, max velocity at zero force) yield zero power, peak power occurs at an intermediate combination of force and velocity."},{"id": 3024,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "Muscle contraction that produces movement of a body segment against gravity or resistance, without the joint angle changing (e.g., holding a weight steady midway through a curl), is termed:","options": [{"key": "A","text": "Isometric contraction"},{"key": "B","text": "Isokinetic contraction only"},{"key": "C","text": "Concentric contraction"},{"key": "D","text": "Passive stretch"}],"correct": "A","explanation": "Holding a position without joint angle change, despite active muscular effort against a load, defines isometric contraction."},{"id": 3025,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "When a muscle contracts but its overall length remains unchanged because the load exceeds the force it can generate, this describes:","options": [{"key": "A","text": "An isometric contraction occurring involuntarily due to load exceeding capacity, sometimes termed a 'break' or failed contraction"},{"key": "B","text": "Passive relaxation"},{"key": "C","text": "A successful concentric contraction"},{"key": "D","text": "Isokinetic contraction"}],"correct": "A","explanation": "If the applied resistance exceeds what the muscle can overcome, the muscle may contract isometrically (or even lengthen eccentrically) despite the intended concentric effort, since it cannot generate sufficient force to shorten against the load."},{"id": 3026,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The load-velocity relationship in resistance training states that, generally, as external load increases, movement velocity:","options": [{"key": "A","text": "Decreases, consistent with the force-velocity relationship of muscle"},{"key": "B","text": "Becomes negative"},{"key": "C","text": "Increases proportionally"},{"key": "D","text": "Remains unaffected by load"}],"correct": "A","explanation": "As external resistance increases, the velocity at which the muscle can move the load decreases, mirroring the inverse force-velocity relationship of muscle physiology."},{"id": 3027,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which best explains why a person can lift a heavier load with an eccentric-only contraction than with a concentric contraction of the same muscle?","options": [{"key": "A","text": "There is no difference between eccentric and concentric force capacity"},{"key": "B","text": "The muscle's capacity to generate force during active lengthening (eccentric) exceeds its capacity during active shortening (concentric), per the force-velocity relationship"},{"key": "C","text": "Eccentric contractions use different muscle fibers entirely"},{"key": "D","text": "Concentric contractions always produce more force"}],"correct": "B","explanation": "Due to the unique mechanical properties of muscle described by the force-velocity curve, eccentric contractions can produce greater force than concentric contractions of the same muscle at a comparable speed, allowing heavier loads to be controlled eccentrically."},{"id": 3028,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Delayed-onset muscle soreness following eccentric exercise is thought to result primarily from:","options": [{"key": "A","text": "Complete absence of muscle activation"},{"key": "B","text": "Microscopic structural damage (micro-tears) to muscle fibers and connective tissue, followed by an inflammatory response"},{"key": "C","text": "Excessive isometric holding only"},{"key": "D","text": "Lactic acid accumulation alone"}],"correct": "B","explanation": "DOMS is now understood to arise mainly from mechanical microtrauma to sarcomeres and connective tissue during eccentric loading, followed by a secondary inflammatory and repair response, rather than lactic acid buildup."},{"id": 3029,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "Which factor does NOT directly influence a muscle's maximal force-generating capacity?","options": [{"key": "A","text": "Skin color overlying the muscle"},{"key": "B","text": "Number of motor units recruited"},{"key": "C","text": "Muscle cross-sectional area"},{"key": "D","text": "Muscle length (length-tension relationship)"}],"correct": "A","explanation": "Skin color has no biomechanical relevance to muscle force capacity; cross-sectional area, length, and motor unit recruitment are all recognized determinants of force output."},{"id": 3030,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A physiotherapy strengthening program that progressively increases resistance over time is based on the principle of:","options": [{"key": "A","text": "Specificity of training only"},{"key": "B","text": "Progressive overload, which stimulates continued strength adaptation"},{"key": "C","text": "Reversibility"},{"key": "D","text": "Detraining"}],"correct": "B","explanation": "Progressive overload—gradually increasing the demand placed on a muscle—is a fundamental principle driving continued strength and hypertrophy adaptations."},{"id": 3031,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Specificity of training' in exercise prescription refers to the principle that:","options": [{"key": "A","text": "All types of exercise produce identical adaptations"},{"key": "B","text": "Strength gains occur regardless of exercise type"},{"key": "C","text": "Training adaptations are specific to the type of exercise/stress performed (e.g., speed, type of contraction, muscle group used)"},{"key": "D","text": "Only aerobic training improves strength"}],"correct": "C","explanation": "The principle of specificity states that physiological adaptations closely match the type, intensity, and mode of training performed, so training should mimic the desired functional outcome."},{"id": 3032,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "In isokinetic testing, peak torque is typically measured to assess:","options": [{"key": "A","text": "Reflex latency"},{"key": "B","text": "Only endurance capacity"},{"key": "C","text": "Passive range of motion only"},{"key": "D","text": "Maximal muscular force output at a controlled, constant angular velocity"}],"correct": "D","explanation": "Isokinetic dynamometry measures peak torque generated by a muscle group while moving at a fixed, controlled angular velocity, providing an objective measure of strength across a range."},{"id": 3033,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "As isokinetic test velocity increases, peak torque output generally:","options": [{"key": "A","text": "Remains completely unaffected"},{"key": "B","text": "Increases progressively without limit"},{"key": "C","text": "Decreases, consistent with the concentric force-velocity relationship of muscle"},{"key": "D","text": "Only affects eccentric testing"}],"correct": "C","explanation": "Consistent with the classic concentric force-velocity relationship, peak torque measured isokinetically tends to decrease as the set test velocity increases."},{"id": 3034,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "Which of the following best explains reduced muscular force output observed immediately after prolonged static stretching (acute stretch-induced force deficit)?","options": [{"key": "A","text": "Temporary alterations in muscle-tendon stiffness and neuromuscular activation following prolonged stretch, which may transiently reduce force/power output"},{"key": "B","text": "Permanent muscle damage"},{"key": "C","text": "Increased motor unit recruitment"},{"key": "D","text": "Complete loss of contractile proteins"}],"correct": "A","explanation": "Research suggests that prolonged static stretching can acutely and temporarily reduce muscle-tendon stiffness and alter neural drive, contributing to a short-term decrease in maximal force or power output."},{"id": 3035,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Muscle hypertrophy (increase in cross-sectional area) with resistance training primarily contributes to increased force production by:","options": [{"key": "A","text": "Increasing muscle fiber length exclusively"},{"key": "B","text": "Increasing the number of sarcomeres arranged in parallel, increasing PCSA"},{"key": "C","text": "Decreasing motor unit recruitment"},{"key": "D","text": "Reducing muscle fiber number"}],"correct": "B","explanation": "Hypertrophy primarily involves increased sarcomeres arranged in parallel within fibers, increasing the muscle's physiological cross-sectional area and thus its force-generating capacity."},{"id": 3036,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Chronic stretching-induced increases in flexibility over weeks to months are thought to involve, in addition to viscoelastic changes, an adaptation in:","options": [{"key": "A","text": "Ligament calcification"},{"key": "B","text": "Bone density only"},{"key": "C","text": "Sarcomere number arranged in series along the muscle fiber, and increased stretch tolerance (sensory adaptation)"},{"key": "D","text": "Cartilage thickness"}],"correct": "C","explanation": "Long-term flexibility gains are thought to involve both increased sarcomeres in series (allowing greater functional muscle length) and altered neural/sensory tolerance to the sensation of stretch."},{"id": 3037,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "Immobilizing a muscle in a shortened position for a prolonged period tends to result in:","options": [{"key": "A","text": "A decrease in the number of sarcomeres in series, and adaptive shortening of the muscle-tendon unit"},{"key": "B","text": "Immediate hypertrophy"},{"key": "C","text": "An increase in the number of sarcomeres in series"},{"key": "D","text": "No structural change to the muscle"}],"correct": "A","explanation": "Prolonged immobilization in a shortened position leads to a reduction in serial sarcomere number, contributing to adaptive shortening and reduced functional muscle length."},{"id": 3038,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "Immobilizing a muscle in a lengthened position for a prolonged period tends to result in:","options": [{"key": "A","text": "Immediate atrophy with no other changes"},{"key": "B","text": "A decrease in the number of sarcomeres in series"},{"key": "C","text": "An increase in the number of sarcomeres in series, as the muscle adapts to the imposed longer length"},{"key": "D","text": "No structural adaptation"}],"correct": "C","explanation": "Muscles immobilized in a lengthened position tend to add sarcomeres in series, adapting their optimal length to the imposed stretched position."},{"id": 3039,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which best explains why a squat performed with a very deep knee flexion angle may feel biomechanically more demanding at certain points in the range?","options": [{"key": "A","text": "There is no biomechanical explanation, it is purely psychological"},{"key": "B","text": "Ligaments actively generate force"},{"key": "C","text": "Muscle temperature changes suddenly"},{"key": "D","text": "The combined effects of the length-tension relationship, changing moment arms of the quadriceps/hip extensors, and increasing external resistance torque throughout the range create points of peak mechanical demand"}],"correct": "D","explanation": "As joint angles change during a deep squat, both muscle length (affecting active tension capacity) and joint moment arms (affecting resistance torque) vary, creating specific 'sticking points' of peak mechanical demand."},{"id": 3040,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "A muscle generating force while its overall length is decreasing, but at a joint angle where its moment arm is simultaneously increasing, illustrates that overall joint torque depends on:","options": [{"key": "A","text": "The combined interaction of muscle force (influenced by length-tension and force-velocity properties) and the moment arm at that specific joint angle"},{"key": "B","text": "Only the joint's range of motion"},{"key": "C","text": "Muscle force alone, independent of moment arm"},{"key": "D","text": "Passive tension exclusively"}],"correct": "A","explanation": "Net joint torque results from the product of the muscle's force output (itself dependent on length and velocity) and its instantaneous moment arm, both of which change throughout the range of motion."},{"id": 3041,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which best summarizes the clinical relevance of understanding a two-joint muscle's active and passive insufficiency for a physiotherapist designing a stretching or strengthening program?","options": [{"key": "A","text": "It only applies to spinal muscles"},{"key": "B","text": "It helps the therapist select joint positions that optimize either stretch (avoiding passive insufficiency limiting range) or strength testing/training (avoiding active insufficiency limiting force), depending on the treatment goal"},{"key": "C","text": "Only single-joint muscles are relevant to rehabilitation"},{"key": "D","text": "It has no clinical relevance"}],"correct": "B","explanation": "Understanding these concepts allows therapists to position joints appropriately—for example, positioning to avoid active insufficiency during strength assessment, or accounting for passive insufficiency when interpreting limited range of motion in stretching or straight-leg-raise type tests."},{"id": 3042,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which of the following best describes 'muscle tone' in a biomechanical/neurophysiological sense?","options": [{"key": "A","text": "The resting level of low-grade, continuous partial muscle contraction/stiffness, maintained partly via reflex activity and passive tissue properties"},{"key": "B","text": "Maximal voluntary contraction"},{"key": "C","text": "Complete absence of muscle activity at rest"},{"key": "D","text": "A property found only in pathological states"}],"correct": "A","explanation": "Muscle tone reflects the baseline resting tension of a muscle, arising from a combination of passive tissue elasticity and low-level involuntary neural activity."},{"id": 3043,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "Spasticity, a velocity-dependent increase in resistance to passive stretch seen in some neurological conditions, is primarily related to abnormal function of which reflex?","options": [{"key": "A","text": "An exaggerated stretch (myotatic) reflex due to upper motor neuron lesion"},{"key": "B","text": "The withdrawal reflex"},{"key": "C","text": "The Golgi tendon organ reflex (autogenic inhibition)"},{"key": "D","text": "The vestibulo-ocular reflex"}],"correct": "A","explanation": "Spasticity is characterized by an exaggerated, velocity-dependent stretch reflex response resulting from loss of normal upper motor neuron inhibitory control."},{"id": 3044,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which best explains why isokinetic exercise equipment is often used in rehabilitation to assess strength across a joint's range rather than relying solely on a single maximal isometric test?","options": [{"key": "A","text": "There is no difference between the two testing methods"},{"key": "B","text": "Isokinetic devices are simpler to operate than manual muscle testing"},{"key": "C","text": "Isometric testing gives a complete picture of strength throughout the range"},{"key": "D","text": "Isokinetic testing captures how force output varies throughout the range of motion at a controlled velocity, reflecting real functional strength variations due to length-tension and moment arm changes"}],"correct": "D","explanation": "Since muscle force capacity varies with joint angle (length-tension relationship) and moment arm, isokinetic testing provides a more comprehensive strength profile across the range than a single-angle isometric test."},{"id": 3045,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "A gait cycle is defined as the period between:","options": [{"key": "A","text": "Heel strike of one foot to heel strike of the opposite foot"},{"key": "B","text": "Successive points of initial contact (heel strike) of the same foot"},{"key": "C","text": "Toe-off to toe-off of opposite feet"},{"key": "D","text": "Two successive foot flat positions"}],"correct": "B","explanation": "A complete gait cycle is measured from initial contact of one foot to the next initial contact of the SAME foot."},{"id": 3046,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "A gait cycle is also referred to as a:","options": [{"key": "A","text": "Stride"},{"key": "B","text": "Step"},{"key": "C","text": "Double support period"},{"key": "D","text": "Single support period"}],"correct": "A","explanation": "A stride equals one complete gait cycle, i.e., from initial contact of one limb to the next initial contact of the same limb."},{"id": 3047,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "A 'step' in gait is defined as:","options": [{"key": "A","text": "One complete gait cycle"},{"key": "B","text": "The distance/time from initial contact of one foot to initial contact of the opposite foot"},{"key": "C","text": "The period of double support only"},{"key": "D","text": "The swing phase only"}],"correct": "B","explanation": "A step is measured from initial contact of one foot to initial contact of the contralateral foot, representing half of a stride/gait cycle."},{"id": 3048,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "The two main phases of the gait cycle are:","options": [{"key": "A","text": "Heel strike and toe-off"},{"key": "B","text": "Single support and initial contact"},{"key": "C","text": "Stance phase and swing phase"},{"key": "D","text": "Loading response and terminal stance"}],"correct": "C","explanation": "The gait cycle is broadly divided into stance phase (foot in contact with ground) and swing phase (foot advancing through the air)."},{"id": 3049,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "In normal walking gait, the stance phase constitutes approximately what percentage of the gait cycle?","options": [{"key": "A","text": "60%"},{"key": "B","text": "40%"},{"key": "C","text": "20%"},{"key": "D","text": "80%"}],"correct": "A","explanation": "Stance phase normally comprises approximately 60% of the gait cycle, with swing phase making up the remaining 40%."},{"id": 3050,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "In normal walking gait, the swing phase constitutes approximately what percentage of the gait cycle?","options": [{"key": "A","text": "80%"},{"key": "B","text": "60%"},{"key": "C","text": "20%"},{"key": "D","text": "40%"}],"correct": "D","explanation": "Swing phase typically comprises approximately 40% of the normal gait cycle."},{"id": 3051,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Double support (double limb stance) refers to the period when:","options": [{"key": "A","text": "Neither foot is in contact with the ground"},{"key": "B","text": "Both feet are simultaneously in contact with the ground"},{"key": "C","text": "One foot is in swing phase only"},{"key": "D","text": "Only one foot is in contact with the ground"}],"correct": "B","explanation": "Double support occurs when both feet are in contact with the ground simultaneously, occurring twice per gait cycle in normal walking."},{"id": 3052,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Double support normally constitutes approximately what percentage of the total gait cycle during normal-speed walking?","options": [{"key": "A","text": "25%"},{"key": "B","text": "50%"},{"key": "C","text": "0%"},{"key": "D","text": "10%"}],"correct": "D","explanation": "Double support periods together account for approximately 10-12% of the total gait cycle during normal-paced walking (about 20-24% combined across both instances, though often cited per cycle as roughly 10% each of two periods)."},{"id": 3053,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "During running, unlike walking, there is a period of:","options": [{"key": "A","text": "Single support only, with an added period of double float (no contact with ground by either foot)"},{"key": "B","text": "Double support only"},{"key": "C","text": "Continuous ground contact"},{"key": "D","text": "No swing phase at all"}],"correct": "A","explanation": "Running is distinguished from walking by the presence of a 'float' or 'flight' phase where neither foot contacts the ground, replacing the double support phase seen in walking."},{"id": 3054,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The Ranchos Los Amigos (RLA) system divides the gait cycle into how many phases?","options": [{"key": "A","text": "10 phases"},{"key": "B","text": "4 phases"},{"key": "C","text": "8 phases"},{"key": "D","text": "6 phases"}],"correct": "C","explanation": "The Ranchos Los Amigos system divides the gait cycle into 8 phases: initial contact, loading response, mid-stance, terminal stance, pre-swing, initial swing, mid-swing, and terminal swing."},{"id": 3055,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "According to the Ranchos Los Amigos terminology, which of the following is the correct sequence of the stance phase subdivisions?","options": [{"key": "A","text": "Initial contact, loading response, mid-stance, terminal stance, pre-swing"},{"key": "B","text": "Pre-swing, initial contact, mid-stance, terminal stance, loading response"},{"key": "C","text": "Loading response, initial contact, terminal stance, mid-stance, pre-swing"},{"key": "D","text": "Terminal stance, mid-stance, loading response, initial contact, pre-swing"}],"correct": "A","explanation": "The correct stance phase sequence is: initial contact → loading response → mid-stance → terminal stance → pre-swing."},{"id": 3056,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "According to the Ranchos Los Amigos terminology, which of the following is the correct sequence of the swing phase subdivisions?","options": [{"key": "A","text": "Initial swing, terminal swing, mid-swing"},{"key": "B","text": "Terminal swing, mid-swing, initial swing"},{"key": "C","text": "Initial swing, mid-swing, terminal swing"},{"key": "D","text": "Mid-swing, terminal swing, initial swing"}],"correct": "C","explanation": "Swing phase progresses in the order: initial swing → mid-swing → terminal swing."},{"id": 3057,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "'Initial contact' (heel strike) refers to the instant when:","options": [{"key": "A","text": "The foot first touches the ground, beginning the stance phase"},{"key": "B","text": "The opposite limb is in mid-swing only"},{"key": "C","text": "The body's center of gravity is at its lowest"},{"key": "D","text": "The foot leaves the ground"}],"correct": "A","explanation": "Initial contact marks the beginning of the stance phase, when the foot (typically the heel in normal gait) first touches the ground."},{"id": 3058,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "'Loading response' refers to the phase of gait in which:","options": [{"key": "A","text": "Toe-off occurs"},{"key": "B","text": "The limb accepts body weight while the foot progresses from initial contact to foot flat, with the opposite limb still in terminal stance/pre-swing"},{"key": "C","text": "The limb is in mid-swing"},{"key": "D","text": "The limb is entirely unweighted"}],"correct": "B","explanation": "Loading response is the initial double-support period after initial contact, during which the stance limb absorbs body weight as the foot moves toward full contact."},{"id": 3059,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Mid-stance' refers to the phase when:","options": [{"key": "A","text": "Toe-off is occurring"},{"key": "B","text": "The opposite foot is making initial contact"},{"key": "C","text": "The body passes directly over the fixed stance foot, with the limb providing single-limb support"},{"key": "D","text": "The body weight is being accepted immediately after initial contact"}],"correct": "C","explanation": "Mid-stance is a single-support phase during which the body's center of mass moves directly over the stance foot."},{"id": 3060,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Terminal stance' refers to the phase when:","options": [{"key": "A","text": "Body weight moves ahead of the stance foot, with the heel beginning to rise (heel-off)"},{"key": "B","text": "The foot is flat with body weight centered over it"},{"key": "C","text": "The limb is in mid-swing"},{"key": "D","text": "Initial contact occurs"}],"correct": "A","explanation": "During terminal stance, the body's weight advances ahead of the forefoot, and the heel rises off the ground in preparation for pre-swing/toe-off."},{"id": 3061,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Pre-swing' refers to the phase when:","options": [{"key": "A","text": "Single-limb support occurs"},{"key": "B","text": "The foot makes initial contact"},{"key": "C","text": "The limb is unloaded and rapidly prepares for swing, ending with toe-off, while the opposite limb accepts weight"},{"key": "D","text": "Mid-swing occurs"}],"correct": "C","explanation": "Pre-swing is the second double-support period, where the stance limb is rapidly unweighted as the contralateral limb takes over weight-bearing, culminating in toe-off."},{"id": 3062,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Initial swing' refers to the phase when:","options": [{"key": "A","text": "The foot is in contact with the ground"},{"key": "B","text": "Terminal stance occurs on the same limb"},{"key": "C","text": "Heel strike occurs"},{"key": "D","text": "The limb accelerates as the foot lifts off the ground, and the swinging limb begins advancing forward"}],"correct": "D","explanation": "Initial swing begins at toe-off, characterized by rapid limb acceleration and initial forward advancement of the swinging leg."},{"id": 3063,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Mid-swing' refers to the phase when:","options": [{"key": "A","text": "Loading response occurs"},{"key": "B","text": "Initial contact occurs on the swinging limb"},{"key": "C","text": "The limb is in double support"},{"key": "D","text": "The swinging limb passes directly beneath the body, with the tibia approximately vertical"}],"correct": "D","explanation": "Mid-swing occurs as the advancing limb passes underneath the body, typically with the tibia oriented roughly vertically."},{"id": 3064,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Terminal swing' refers to the phase when:","options": [{"key": "A","text": "The limb is accelerating immediately after toe-off"},{"key": "B","text": "Loading response occurs"},{"key": "C","text": "Mid-stance occurs"},{"key": "D","text": "The limb decelerates in preparation for initial contact, completing forward limb advancement"}],"correct": "D","explanation": "Terminal swing is the final swing subphase, during which the advancing limb decelerates to prepare for a controlled initial contact."},{"id": 3065,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "In normal gait, at initial contact (heel strike), the ankle is typically positioned in:","options": [{"key": "A","text": "Full inversion"},{"key": "B","text": "Maximal dorsiflexion"},{"key": "C","text": "Neutral or slight dorsiflexion, with the heel contacting the ground first"},{"key": "D","text": "Full plantarflexion"}],"correct": "C","explanation": "At initial contact, the ankle is typically near neutral or slightly dorsiflexed, allowing the heel to make first contact with the ground."},{"id": 3066,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Immediately after heel strike, the foot typically undergoes controlled plantarflexion (foot slap prevention) through the action of which muscle group, contracting eccentrically?","options": [{"key": "A","text": "Quadriceps"},{"key": "B","text": "Dorsiflexors (tibialis anterior), contracting eccentrically to lower the foot to the ground in a controlled manner"},{"key": "C","text": "Gastrocnemius/soleus (plantarflexors)"},{"key": "D","text": "Hip abductors"}],"correct": "B","explanation": "The dorsiflexors (primarily tibialis anterior) contract eccentrically after heel strike to control the rate of foot plantarflexion, preventing an uncontrolled 'foot slap'."},{"id": 3067,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During loading response, the knee is typically:","options": [{"key": "A","text": "Fully extended and locked"},{"key": "B","text": "Slightly flexed (approximately 15-20 degrees), acting as a shock absorber"},{"key": "C","text": "In hyperextension"},{"key": "D","text": "Maximally flexed to 90 degrees"}],"correct": "B","explanation": "The knee flexes slightly (about 15-20°) during loading response, which helps absorb the shock of weight acceptance."},{"id": 3068,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "During loading response, knee flexion is controlled by eccentric contraction of which muscle group?","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Quadriceps (particularly vastus muscles), contracting eccentrically to control the rate of knee flexion"},{"key": "C","text": "Gastrocnemius only"},{"key": "D","text": "Hamstrings"}],"correct": "B","explanation": "The quadriceps contract eccentrically during loading response to control the degree and rate of knee flexion, preventing buckling under the newly accepted body weight."},{"id": 3069,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "During mid-stance, which muscle group is primarily active to control forward progression of the tibia over the fixed foot (controlling excessive dorsiflexion)?","options": [{"key": "A","text": "Plantarflexors (gastrocnemius/soleus), contracting eccentrically"},{"key": "B","text": "Hip flexors"},{"key": "C","text": "Hamstrings only"},{"key": "D","text": "Quadriceps only"}],"correct": "A","explanation": "During mid-stance, the plantarflexors act eccentrically to control the rate of tibial advancement over the stance foot, preventing excessive forward movement (falling forward)."},{"id": 3070,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During terminal stance, the plantarflexors (gastrocnemius/soleus) contract to:","options": [{"key": "A","text": "Cause knee hyperextension"},{"key": "B","text": "Control tibial advancement eccentrically only"},{"key": "C","text": "Provide no significant contribution"},{"key": "D","text": "Concentrically contract, contributing to heel rise and propelling the body forward"}],"correct": "D","explanation": "In terminal stance, the plantarflexors shift to a more concentric role, contributing to heel-off and forward propulsion of the body."},{"id": 3071,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During pre-swing, the primary function of the plantarflexors is to:","options": [{"key": "A","text": "Prevent knee flexion"},{"key": "B","text": "Provide the 'push-off' force, contributing to forward propulsion as the limb prepares to unweight for swing"},{"key": "C","text": "Only stabilize the ankle in dorsiflexion"},{"key": "D","text": "Control hip flexion only"}],"correct": "B","explanation": "The plantarflexors provide a significant portion of the propulsive force during pre-swing ('push-off'), aiding forward progression as the limb unloads for swing."},{"id": 3072,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "During pre-swing and initial swing, knee flexion is primarily achieved through:","options": [{"key": "A","text": "Active hamstring contraction alone"},{"key": "B","text": "Quadriceps contraction"},{"key": "C","text": "Passive mechanisms (momentum from hip flexion and the 'whip' effect of push-off) along with some rectus femoris relaxation, with minimal active knee flexor effort needed initially"},{"key": "D","text": "Gastrocnemius contraction only"}],"correct": "C","explanation": "Initial knee flexion for swing is largely a passive result of the pre-swing push-off momentum and limb dynamics, requiring relatively little direct active hamstring contraction at this specific point."},{"id": 3073,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "During initial swing, hip flexion is primarily produced by concentric contraction of:","options": [{"key": "A","text": "Gluteus maximus"},{"key": "B","text": "Hamstrings only"},{"key": "C","text": "Gastrocnemius only"},{"key": "D","text": "Hip flexors, particularly iliopsoas and rectus femoris"}],"correct": "D","explanation": "The hip flexors (iliopsoas, rectus femoris, and others) concentrically contract during initial swing to advance the thigh forward."},{"id": 3074,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During mid-swing, the ankle dorsiflexors (tibialis anterior) contract primarily to:","options": [{"key": "A","text": "Control knee extension"},{"key": "B","text": "Dorsiflex the ankle/foot to ensure adequate toe clearance from the ground"},{"key": "C","text": "Plantarflex the ankle"},{"key": "D","text": "Provide push-off force"}],"correct": "B","explanation": "Dorsiflexors contract during swing to lift the foot (dorsiflexion), ensuring the toes clear the ground as the limb advances."},{"id": 3075,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Inadequate ankle dorsiflexion during swing phase (e.g., due to dorsiflexor weakness or drop foot) commonly results in which compensatory gait pattern?","options": [{"key": "A","text": "Excessive hip extension"},{"key": "B","text": "Trendelenburg gait"},{"key": "C","text": "Steppage gait, characterized by exaggerated hip and knee flexion to help the foot clear the ground"},{"key": "D","text": "Vaulting gait only"}],"correct": "C","explanation": "Steppage gait, involving increased hip/knee flexion, is a common compensation for insufficient active dorsiflexion (foot drop) to prevent toe-dragging during swing."},{"id": 3076,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "During terminal swing, which muscle group acts eccentrically to decelerate the advancing lower leg in preparation for initial contact?","options": [{"key": "A","text": "Quadriceps concentrically"},{"key": "B","text": "Hamstrings, contracting eccentrically to control (decelerate) knee extension and hip flexion"},{"key": "C","text": "Gastrocnemius concentrically"},{"key": "D","text": "Hip abductors only"}],"correct": "B","explanation": "The hamstrings contract eccentrically during terminal swing to decelerate the swinging leg, controlling the rate of knee extension and limiting excessive hip flexion just before heel strike."},{"id": 3077,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which muscle group is critically important for controlling frontal plane pelvic stability (preventing contralateral pelvic drop) during single-limb stance?","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Ankle plantarflexors only"},{"key": "C","text": "Hamstrings only"},{"key": "D","text": "Hip abductors (gluteus medius and minimus)"}],"correct": "D","explanation": "The hip abductors, particularly gluteus medius, are essential for stabilizing the pelvis in the frontal plane and preventing excessive contralateral pelvic drop during single-limb support."},{"id": 3078,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "The 'compensated Trendelenburg' gait pattern (also called gluteus medius lurch) involves the trunk leaning:","options": [{"key": "A","text": "Toward the weak-sided stance limb, shifting the body's center of gravity over the hip to reduce the demand on the weak abductors"},{"key": "B","text": "Backward excessively"},{"key": "C","text": "Forward excessively only"},{"key": "D","text": "Away from the weak-sided stance limb"}],"correct": "A","explanation": "In compensated Trendelenburg gait, the patient leans their trunk toward the affected (weak) stance side, shifting COG over the hip joint to reduce the torque demand on the weakened abductors."},{"id": 3079,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "The normal range of pelvic rotation (transverse plane) during a gait cycle is approximately:","options": [{"key": "A","text": "Approximately 8 degrees total (about 4 degrees forward rotation on each side)"},{"key": "B","text": "90 degrees"},{"key": "C","text": "0 degrees (no rotation)"},{"key": "D","text": "40 degrees"}],"correct": "A","explanation": "Normal pelvic rotation in the transverse plane during gait is relatively small, approximately 8 degrees total range, contributing to smooth forward progression and stride length."},{"id": 3080,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Pelvic obliquity (frontal plane pelvic tilt) during normal gait typically shows the pelvis dropping slightly on the:","options": [{"key": "A","text": "Stance limb side"},{"key": "B","text": "Both sides equally at the same time"},{"key": "C","text": "Neither side, remaining level throughout"},{"key": "D","text": "Swing limb side, by approximately 5 degrees, controlled by the stance-side hip abductors"}],"correct": "D","explanation": "During normal gait, the pelvis drops slightly (~5°) on the swing-limb side, which is controlled and limited by the stance-limb hip abductors preventing excessive drop."},{"id": 3081,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The center of gravity of the body during normal walking moves in which characteristic pattern?","options": [{"key": "A","text": "Random, non-repeating movement"},{"key": "B","text": "A smooth, sinusoidal pattern with both vertical and lateral (side-to-side) oscillations"},{"key": "C","text": "A straight horizontal line with no vertical or lateral displacement"},{"key": "D","text": "Purely vertical oscillation with no lateral movement"}],"correct": "B","explanation": "The body's COG follows a smooth sinusoidal path during gait, displaying both vertical (up-down) and lateral (side-to-side) oscillations that repeat with each stride."},{"id": 3082,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The normal vertical displacement of the center of gravity during walking is approximately:","options": [{"key": "A","text": "20-30 cm"},{"key": "B","text": "50 cm"},{"key": "C","text": "0 cm (no vertical movement)"},{"key": "D","text": "2-5 cm, with the COG highest during mid-stance and lowest during double support"}],"correct": "D","explanation": "Normal vertical COG excursion during gait is approximately 2-5 cm, being highest at mid-stance (single support) and lowest during periods of double support."},{"id": 3083,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The normal lateral (side-to-side) displacement of the center of gravity during walking is approximately:","options": [{"key": "A","text": "0 cm"},{"key": "B","text": "2-4 cm, shifting toward the stance limb during each single-support phase"},{"key": "C","text": "30 cm"},{"key": "D","text": "15-20 cm"}],"correct": "B","explanation": "Lateral COG displacement during normal gait is approximately 2-4 cm per side, as the body's weight shifts toward the stance limb during single support."},{"id": 3084,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Saunders and colleagues described 'six determinants of gait' that are believed to minimize the energy cost of walking by reducing the excursion of the body's center of gravity. Which of the following is one of these six determinants?","options": [{"key": "A","text": "Elimination of ankle motion entirely"},{"key": "B","text": "Constant knee hyperextension throughout stance"},{"key": "C","text": "Pelvic rotation"},{"key": "D","text": "Excessive vertical head bobbing"}],"correct": "C","explanation": "Pelvic rotation is one of the six classic determinants of gait (along with pelvic tilt, knee flexion in stance, and foot/ankle/knee mechanisms), which together help smooth and minimize the vertical/lateral excursions of the COG."},{"id": 3085,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Which of the following is also considered one of the classic 'six determinants of gait'?","options": [{"key": "A","text": "Continuous double support throughout the cycle"},{"key": "B","text": "Excessive trunk rotation with no pelvic involvement"},{"key": "C","text": "Complete elimination of hip motion"},{"key": "D","text": "Knee flexion during stance phase, which helps flatten the arc of the COG's vertical excursion"}],"correct": "D","explanation": "Knee flexion during stance (approximately 15-20°) is a key determinant that helps smooth and reduce the vertical rise of the body's center of gravity during gait."},{"id": 3086,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "The 'compass gait' model, describing walking as if the legs were rigid pendulums with no knee or ankle motion, is used to illustrate that without the determinants of gait, vertical COG displacement would be:","options": [{"key": "A","text": "Identical to normal gait"},{"key": "B","text": "Eliminated entirely"},{"key": "C","text": "Reduced compared to normal gait"},{"key": "D","text": "Significantly greater, resulting in higher energy expenditure"}],"correct": "D","explanation": "The compass gait model demonstrates that without mechanisms like pelvic rotation, pelvic tilt, and knee flexion, the vertical excursion of the COG—and thus energy cost—would be substantially greater than in normal gait."},{"id": 3087,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "Cadence in gait analysis refers to:","options": [{"key": "A","text": "The width of the base of support during walking"},{"key": "B","text": "The number of steps taken per unit time (e.g., steps per minute)"},{"key": "C","text": "The angle of foot placement"},{"key": "D","text": "The distance covered in one stride"}],"correct": "B","explanation": "Cadence is a temporal gait parameter representing the number of steps taken per minute."},{"id": 3088,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Normal adult walking cadence is approximately:","options": [{"key": "A","text": "90-120 steps/min"},{"key": "B","text": "30-40 steps/min"},{"key": "C","text": "200+ steps/min"},{"key": "D","text": "60-70 steps/min"}],"correct": "A","explanation": "Typical adult walking cadence ranges from approximately 90 to 120 steps per minute, depending on individual factors like age, height, and walking speed."},{"id": 3089,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "Stride length refers to:","options": [{"key": "A","text": "The distance from initial contact of one foot to initial contact of the contralateral foot"},{"key": "B","text": "The vertical displacement of the COG"},{"key": "C","text": "The distance covered during one complete gait cycle (initial contact of one foot to the next initial contact of the SAME foot)"},{"key": "D","text": "The width of the base of support"}],"correct": "C","explanation": "Stride length is the linear distance covered during one full gait cycle, from initial contact of one foot to the next initial contact of the same foot."},{"id": 3090,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Step length refers to:","options": [{"key": "A","text": "The total distance walked in a session"},{"key": "B","text": "The width between the two feet"},{"key": "C","text": "The distance covered in one full gait cycle"},{"key": "D","text": "The linear distance between successive points of initial contact of opposite feet"}],"correct": "D","explanation": "Step length is the distance between successive initial contact points of the two different (opposite) feet."},{"id": 3091,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Under normal symmetrical gait conditions, stride length is approximately:","options": [{"key": "A","text": "Unrelated to step length"},{"key": "B","text": "Equal to the sum of the right and left step lengths (i.e., approximately twice the step length)"},{"key": "C","text": "Half of step length"},{"key": "D","text": "Always shorter than step length"}],"correct": "B","explanation": "In symmetric gait, stride length equals the sum of two successive step lengths (right + left), so it is approximately double a single step length."},{"id": 3092,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "'Step width' (base of support width) in gait refers to:","options": [{"key": "A","text": "The distance between the heel centers of two consecutive footprints from opposite feet, measured perpendicular to the line of progression"},{"key": "B","text": "The time taken for one step"},{"key": "C","text": "The length of a single step"},{"key": "D","text": "The angle of foot placement relative to the line of progression"}],"correct": "A","explanation": "Step width measures the mediolateral distance between the two feet during walking, contributing to the base of support and lateral stability."},{"id": 3093,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Foot progression angle' (toe-out angle) refers to:","options": [{"key": "A","text": "The angle between the two feet at initial contact"},{"key": "B","text": "The angle of ankle dorsiflexion"},{"key": "C","text": "The angle between the long axis of the foot and the line of progression during walking"},{"key": "D","text": "The angle of hip rotation only"}],"correct": "C","explanation": "Foot progression angle describes the degree to which the foot is externally (toe-out) or internally (toe-in) rotated relative to the direction of walking progression."},{"id": 3094,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Normal foot progression angle (toe-out) during walking is approximately:","options": [{"key": "A","text": "20 degrees of internal rotation (toe-in)"},{"key": "B","text": "5-7 degrees of external rotation (toe-out)"},{"key": "C","text": "30 degrees of external rotation"},{"key": "D","text": "0 degrees (foot perfectly parallel to line of progression)"}],"correct": "B","explanation": "A normal foot progression angle is approximately 5-7 degrees of toe-out relative to the line of progression."},{"id": 3095,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Walking velocity is calculated as the product of:","options": [{"key": "A","text": "Cadence alone"},{"key": "B","text": "Double support time alone"},{"key": "C","text": "Stride length and cadence (with appropriate unit conversion)"},{"key": "D","text": "Step width and stride length"}],"correct": "C","explanation": "Walking velocity is derived from the combination of stride length (distance) and cadence (steps per unit time), representing overall walking speed."},{"id": 3096,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Normal comfortable adult walking speed is approximately:","options": [{"key": "A","text": "3.0-4.0 m/s"},{"key": "B","text": "1.2-1.4 m/s"},{"key": "C","text": "0.2-0.5 m/s"},{"key": "D","text": "5.0+ m/s"}],"correct": "B","explanation": "Typical comfortable walking speed for healthy adults is approximately 1.2 to 1.4 meters per second."},{"id": 3097,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "As walking speed increases (within a normal range), which gait parameters typically both increase?","options": [{"key": "A","text": "Both cadence and stride length typically increase"},{"key": "B","text": "Only cadence increases; stride length remains fixed"},{"key": "C","text": "Neither parameter changes with speed"},{"key": "D","text": "Only stride length increases; cadence remains fixed"}],"correct": "A","explanation": "Increased walking speed is generally achieved through a combination of increased cadence and increased stride length, up to a point where further increases in speed rely more heavily on cadence."},{"id": 3098,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Ground reaction force (GRF) during normal walking typically shows a characteristic vertical force curve with:","options": [{"key": "A","text": "A single smooth peak"},{"key": "B","text": "Two peaks (during loading response and terminal stance/push-off) with a relative trough (mid-stance) between them, sometimes called the 'M-shaped' curve"},{"key": "C","text": "Continuous, unchanging force throughout stance"},{"key": "D","text": "No measurable force at any point"}],"correct": "B","explanation": "The vertical GRF curve during walking classically shows an 'M' shape, with two peaks corresponding to weight acceptance and push-off, separated by a mid-stance trough."},{"id": 3099,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The first peak of the vertical ground reaction force during walking typically occurs during:","options": [{"key": "A","text": "Loading response, as the body rapidly accepts weight onto the limb"},{"key": "B","text": "Terminal swing"},{"key": "C","text": "Mid-stance"},{"key": "D","text": "Pre-swing only"}],"correct": "A","explanation": "The first vertical GRF peak occurs during loading response, reflecting the rapid weight acceptance and associated impact force onto the newly loaded limb."},{"id": 3100,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The second peak of the vertical ground reaction force during walking typically occurs during:","options": [{"key": "A","text": "Terminal stance/pre-swing, associated with active push-off"},{"key": "B","text": "Loading response"},{"key": "C","text": "Mid-swing"},{"key": "D","text": "Initial contact"}],"correct": "A","explanation": "The second vertical GRF peak occurs during terminal stance/pre-swing, corresponding to the active push-off phase as the body propels forward."},{"id": 3101,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Hard","question": "The vertical ground reaction force during mid-stance typically shows a relative trough (dip) below body weight, reflecting:","options": [{"key": "A","text": "Increased loading at that instant"},{"key": "B","text": "Maximum push-off force"},{"key": "C","text": "Complete unweighting of the limb"},{"key": "D","text": "The body's center of gravity moving through its highest point with reduced vertical acceleration/deceleration demands at that instant"}],"correct": "D","explanation": "During mid-stance, as the COG passes over its highest point with relatively steady vertical velocity, the vertical GRF dips slightly below body weight before rising again toward terminal stance."},{"id": 3102,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The anteroposterior (horizontal, fore-aft) component of ground reaction force during early stance is typically directed:","options": [{"key": "A","text": "Posteriorly (a braking/decelerating force) as the limb decelerates forward momentum after initial contact"},{"key": "B","text": "Laterally only"},{"key": "C","text": "Anteriorly (propulsive)"},{"key": "D","text": "Purely vertically with no horizontal component"}],"correct": "A","explanation": "In early stance (loading response), the horizontal GRF acts posteriorly, representing a braking force that decelerates the body's forward momentum."},{"id": 3103,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The anteroposterior (horizontal) component of ground reaction force during late stance (terminal stance/pre-swing) is typically directed:","options": [{"key": "A","text": "Posteriorly (braking)"},{"key": "B","text": "Laterally only"},{"key": "C","text": "Anteriorly (propulsive), reflecting active push-off that accelerates the body forward"},{"key": "D","text": "Purely vertically"}],"correct": "C","explanation": "During late stance, the horizontal GRF shifts to a propulsive (anteriorly directed) force as push-off accelerates the body forward for the next step."},{"id": 3104,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The mediolateral (side-to-side) component of ground reaction force during gait is generally the __________ of the three GRF components.","options": [{"key": "A","text": "Largest"},{"key": "B","text": "Equal in magnitude to the vertical component"},{"key": "C","text": "Non-existent"},{"key": "D","text": "Smallest in magnitude, though still functionally important for balance control"}],"correct": "D","explanation": "The mediolateral GRF component is typically the smallest of the three components (vertical, anteroposterior, mediolateral), though it still plays an important role in lateral balance control."},{"id": 3105,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Electromyographic (EMG) studies of normal gait show the quadriceps to be most active during which phase(s)?","options": [{"key": "A","text": "Terminal swing and mid-stance only"},{"key": "B","text": "Only during swing phase"},{"key": "C","text": "Throughout the entire gait cycle at constant intensity"},{"key": "D","text": "Terminal swing (through initial contact) and loading response, controlling knee stability and shock absorption"}],"correct": "D","explanation": "Quadriceps EMG activity peaks around terminal swing (preparing the knee for contact) and continues through loading response, controlling knee flexion and providing stability during weight acceptance."},{"id": 3106,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "EMG studies of normal gait show the tibialis anterior (dorsiflexors) to be most active during which phases?","options": [{"key": "A","text": "Initial contact/loading response (eccentric control of foot lowering) and throughout swing phase (to ensure toe clearance)"},{"key": "B","text": "Only mid-stance"},{"key": "C","text": "Continuously throughout the entire stance phase at high intensity"},{"key": "D","text": "Only terminal stance"}],"correct": "A","explanation": "Tibialis anterior shows two periods of activity: eccentrically after initial contact to control foot lowering, and throughout swing to maintain dorsiflexion for toe clearance."},{"id": 3107,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "EMG studies of normal gait show the gastrocnemius/soleus (plantarflexors) to be most active during which phase?","options": [{"key": "A","text": "Initial contact"},{"key": "B","text": "Terminal swing only"},{"key": "C","text": "Mid-stance through terminal stance/pre-swing, contributing to stability and propulsion (push-off)"},{"key": "D","text": "Initial swing only"}],"correct": "C","explanation": "Plantarflexor activity increases through mid-stance to terminal stance, controlling tibial advancement and then contributing to propulsive push-off during pre-swing."},{"id": 3108,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "EMG studies of normal gait show the gluteus maximus to be most active during which phase?","options": [{"key": "A","text": "Late swing through loading response/early stance, stabilizing the hip and controlling forward trunk momentum at initial contact"},{"key": "B","text": "Throughout swing phase only"},{"key": "C","text": "Mid-swing"},{"key": "D","text": "Terminal stance only"}],"correct": "A","explanation": "Gluteus maximus activity peaks around late swing into early stance, helping decelerate the swinging limb and stabilize the hip/control the trunk as weight is accepted."},{"id": 3109,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "EMG studies of normal gait show the hip abductors (e.g., gluteus medius) to be most active during which phase?","options": [{"key": "A","text": "Stance phase, particularly loading response through mid-stance, stabilizing the pelvis in the frontal plane during single-limb support"},{"key": "B","text": "Only during double support"},{"key": "C","text": "Swing phase of the same limb"},{"key": "D","text": "Only at initial contact"}],"correct": "A","explanation": "Hip abductors are most active during the stance phase (loading response to mid-stance) of the same limb, controlling pelvic stability during single-limb support."},{"id": 3110,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "In normal gait, the hip joint moves through a range of approximately how many degrees of flexion-extension across the gait cycle?","options": [{"key": "A","text": "5-10 degrees"},{"key": "B","text": "120 degrees"},{"key": "C","text": "40-45 degrees (approximately 30° flexion at initial contact to about 10-15° extension at terminal stance)"},{"key": "D","text": "90 degrees"}],"correct": "C","explanation": "The hip typically moves through roughly 40-45° of total sagittal-plane motion during a normal gait cycle, from about 30° flexion at initial contact to about 10-15° extension in terminal stance."},{"id": 3111,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "In normal gait, the knee joint shows a characteristic 'double-bump' flexion pattern, with two flexion peaks occurring during:","options": [{"key": "A","text": "Loading response (~15-20° flexion for shock absorption) and swing phase (~60-70° flexion for toe clearance and limb advancement)"},{"key": "B","text": "Only mid-stance"},{"key": "C","text": "Only at initial contact"},{"key": "D","text": "Only pre-swing"}],"correct": "A","explanation": "The knee shows two flexion peaks per gait cycle: a smaller peak during loading response (shock absorption) and a larger peak during swing phase (allowing toe clearance and rapid limb advancement)."},{"id": 3112,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "In normal gait, the ankle joint's total range of sagittal plane motion during the gait cycle is approximately:","options": [{"key": "A","text": "5 degrees"},{"key": "B","text": "25-30 degrees, moving between dorsiflexion and plantarflexion at different phases"},{"key": "C","text": "90 degrees"},{"key": "D","text": "60 degrees"}],"correct": "B","explanation": "The ankle moves through roughly 25-30° of combined dorsiflexion-plantarflexion excursion across the gait cycle."},{"id": 3113,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "The 'rocker' mechanisms of the foot/ankle during stance phase describe how the foot pivots to allow smooth forward progression; the first (heel) rocker occurs during:","options": [{"key": "A","text": "Pre-swing"},{"key": "B","text": "Mid-swing"},{"key": "C","text": "Initial contact/loading response, as the foot pivots over the heel into plantarflexion"},{"key": "D","text": "Terminal stance"}],"correct": "C","explanation": "The heel rocker (first rocker) occurs immediately after initial contact, as the foot rotates over the rounded heel into plantarflexion during loading response."},{"id": 3114,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The second (ankle) rocker occurs during which phase, as the tibia rotates forward over the fixed foot?","options": [{"key": "A","text": "Terminal swing"},{"key": "B","text": "Pre-swing"},{"key": "C","text": "Mid-stance, controlled eccentrically by the plantarflexors"},{"key": "D","text": "Initial contact"}],"correct": "C","explanation": "The ankle rocker occurs during mid-stance, as the tibia advances forward over the stationary foot, controlled eccentrically by the plantarflexors."},{"id": 3115,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The third (forefoot) rocker occurs during which phase, as the heel rises and the foot pivots over the metatarsal heads?","options": [{"key": "A","text": "Loading response"},{"key": "B","text": "Mid-swing"},{"key": "C","text": "Terminal stance/pre-swing, contributing to push-off"},{"key": "D","text": "Initial swing"}],"correct": "C","explanation": "The forefoot rocker occurs during terminal stance into pre-swing, as the heel lifts and the body pivots forward over the metatarsal heads, aiding push-off."},{"id": 3116,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "During weight-bearing, the subtalar joint typically moves into __________ during early stance (loading response), then into __________ during mid to terminal stance.","options": [{"key": "A","text": "Inversion; further inversion"},{"key": "B","text": "Neutral throughout; no change occurs"},{"key": "C","text": "Pronation; supination"},{"key": "D","text": "Supination; pronation"}],"correct": "C","explanation": "The subtalar joint pronates during early stance (aiding shock absorption and adaptation to terrain) and then re-supinates during mid to terminal stance, creating a more rigid lever for push-off."},{"id": 3117,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Subtalar joint pronation during early stance helps the foot to:","options": [{"key": "A","text": "Become a mobile adapter, absorbing shock and accommodating variable terrain"},{"key": "B","text": "Become a rigid lever for push-off"},{"key": "C","text": "Lock completely, preventing any motion"},{"key": "D","text": "Actively propel the body forward"}],"correct": "A","explanation": "Pronation early in stance allows the foot to act as a flexible shock absorber, adapting to ground contours and dissipating impact forces."},{"id": 3118,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Subtalar joint supination during terminal stance helps the foot to:","options": [{"key": "A","text": "Reduce ground reaction force to zero"},{"key": "B","text": "Remain maximally mobile and flexible"},{"key": "C","text": "Become a rigid lever, transmitting force effectively for efficient push-off"},{"key": "D","text": "Absorb shock primarily"}],"correct": "C","explanation": "Re-supination in terminal stance locks the midtarsal joints, converting the foot into a rigid lever that efficiently transmits push-off forces."},{"id": 3119,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'windlass mechanism' of the foot describes how dorsiflexion of the toes (as occurs during terminal stance/push-off) causes:","options": [{"key": "A","text": "Complete collapse of the foot arch"},{"key": "B","text": "Tightening of the plantar fascia, which raises and stabilizes the medial longitudinal arch, aiding push-off efficiency"},{"key": "C","text": "No effect on the plantar fascia"},{"key": "D","text": "Relaxation of the plantar fascia and flattening of the medial longitudinal arch"}],"correct": "B","explanation": "Toe dorsiflexion during push-off tightens the plantar fascia around the metatarsal heads (windlass mechanism), which elevates and stabilizes the medial longitudinal arch, improving mechanical efficiency during propulsion."},{"id": 3120,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Energy expenditure during walking is generally considered most economical at:","options": [{"key": "A","text": "A speed unrelated to metabolic considerations"},{"key": "B","text": "A person's freely chosen, comfortable walking speed, which typically minimizes metabolic cost per unit distance"},{"key": "C","text": "Very slow walking speeds"},{"key": "D","text": "Maximum possible walking speed"}],"correct": "B","explanation": "Research shows that self-selected comfortable walking speed tends to correspond closely to the speed that minimizes metabolic energy cost per distance traveled."},{"id": 3121,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Walking at speeds significantly slower or faster than one's naturally preferred speed generally results in:","options": [{"key": "A","text": "No change in energy expenditure"},{"key": "B","text": "Complete elimination of gait deviations"},{"key": "C","text": "Decreased metabolic energy cost per unit distance"},{"key": "D","text": "Increased metabolic energy cost per unit distance compared to the optimal, preferred speed"}],"correct": "D","explanation": "Deviating from the naturally preferred walking speed, whether faster or slower, generally increases the metabolic energy cost per unit distance traveled."},{"id": 3122,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following age-related gait changes is commonly observed in healthy older adults compared to younger adults?","options": [{"key": "A","text": "Complete elimination of double support"},{"key": "B","text": "Identical gait parameters to younger adults"},{"key": "C","text": "Decreased walking speed, shorter stride length, and increased double support time"},{"key": "D","text": "Increased walking speed and stride length"}],"correct": "C","explanation": "Healthy aging is commonly associated with reduced walking speed, shorter strides, and a relatively greater proportion of time spent in double support, often as an adaptation to enhance stability."},{"id": 3123,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best describes normal arm swing during gait?","options": [{"key": "A","text": "The arms remain completely still throughout walking"},{"key": "B","text": "The arms swing reciprocally, generally opposite in phase to the ipsilateral leg (right arm forward with left leg forward), aiding balance and counteracting trunk rotation"},{"key": "C","text": "Both arms swing forward simultaneously with both legs"},{"key": "D","text": "Arm swing has no biomechanical function"}],"correct": "B","explanation": "Normal gait involves reciprocal arm swing, with each arm moving opposite to the same-side leg, helping to counterbalance the rotational forces generated by the legs and trunk."},{"id": 3124,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "The primary biomechanical function of normal reciprocal arm swing during gait is to:","options": [{"key": "A","text": "Help counterbalance the angular momentum generated by leg and pelvic rotation, improving efficiency and reducing the metabolic cost of walking"},{"key": "B","text": "Increase walking speed directly"},{"key": "C","text": "Provide the majority of forward propulsion"},{"key": "D","text": "Stabilize the head only"}],"correct": "A","explanation": "Reciprocal arm swing serves to counteract the rotational (angular momentum) effects of the lower limbs and pelvis during gait, contributing to smoother, more energy-efficient walking."},{"id": 3125,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Trunk rotation during normal gait typically occurs:","options": [{"key": "A","text": "Only during double support"},{"key": "B","text": "Not at all; the trunk remains fixed"},{"key": "C","text": "In phase with (same direction as) pelvic rotation"},{"key": "D","text": "Out of phase with (opposite direction to) pelvic rotation, contributing to counter-rotation that helps conserve angular momentum"}],"correct": "D","explanation": "The trunk typically rotates in the opposite direction to the pelvis during gait (counter-rotation), which helps balance angular momentum and contributes to smooth, efficient walking mechanics."},{"id": 3126,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "In normal gait, lateral pelvic tilt (pelvic list) helps to:","options": [{"key": "A","text": "Reduce the vertical excursion of the center of gravity by dropping the pelvis slightly on the swing side, flattening the arc of COG movement"},{"key": "B","text": "Increase the vertical excursion of the center of gravity"},{"key": "C","text": "Have no effect on COG movement"},{"key": "D","text": "Only occur in pathological gait"}],"correct": "A","explanation": "Controlled pelvic tilt/list (drop on the swing side) is one of the classic determinants of gait that helps flatten and smooth the vertical trajectory of the center of gravity."},{"id": 3127,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Which of the following best describes normal knee motion in the coronal (frontal) plane during stance phase of gait?","options": [{"key": "A","text": "Motion occurring only during swing phase"},{"key": "B","text": "Small-amplitude motion, generally only a few degrees of varus/valgus movement, important for shock absorption and stability"},{"key": "C","text": "No motion whatsoever in the frontal plane"},{"key": "D","text": "Large-amplitude abduction/adduction of approximately 20-30 degrees"}],"correct": "B","explanation": "Normal frontal-plane knee motion during stance is relatively small (a few degrees), contributing subtly to shock absorption and joint stability during weight-bearing."},{"id": 3128,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Excessive genu valgum (knock-knee) alignment during stance phase of gait can increase mechanical stress on which knee structure?","options": [{"key": "A","text": "Lateral collateral ligament primarily reduced stress"},{"key": "B","text": "Medial compartment structures reduced stress but increased lateral compartment/patellofemoral stress and medial ligament tension"},{"key": "C","text": "No structures are affected by frontal plane alignment"},{"key": "D","text": "Only the posterior cruciate ligament"}],"correct": "B","explanation": "Excessive valgus alignment increases stress on lateral compartment structures and patellofemoral joint, while also increasing tensile load on medial stabilizing structures, altering typical loading patterns."},{"id": 3129,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best explains why a slower walking speed is often recommended during early gait training after lower limb injury or surgery?","options": [{"key": "A","text": "Slower speed has no biomechanical advantage"},{"key": "B","text": "Walking speed does not affect joint loading"},{"key": "C","text": "Slower speed increases joint loading forces significantly"},{"key": "D","text": "Slower speed generally reduces peak ground reaction forces, joint moments, and muscular demands, allowing safer, more controlled movement during tissue healing"}],"correct": "D","explanation": "Reducing walking speed generally decreases peak forces and joint torques experienced during gait, allowing a more protected loading environment appropriate for early-stage rehabilitation."},{"id": 3130,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "The 'gait cycle' concept is clinically important for physiotherapists primarily because it:","options": [{"key": "A","text": "It cannot be measured or observed clinically"},{"key": "B","text": "It only applies to elite athletes"},{"key": "C","text": "Has no relevance to rehabilitation practice"},{"key": "D","text": "Provides a standardized framework for identifying, describing, and analyzing normal versus deviant movement patterns to guide targeted intervention"}],"correct": "D","explanation": "Understanding the normal gait cycle framework allows clinicians to systematically identify specific deviations from normal patterns and target appropriate interventions."},{"id": 3131,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best represents the correct order of events within a single stance phase, from initial contact to toe-off?","options": [{"key": "A","text": "Initial contact, loading response, mid-stance, terminal stance, pre-swing"},{"key": "B","text": "Terminal stance, loading response, mid-stance, pre-swing, initial contact"},{"key": "C","text": "Loading response, initial contact, pre-swing, mid-stance, terminal stance"},{"key": "D","text": "Pre-swing, mid-stance, initial contact, loading response, terminal stance"}],"correct": "A","explanation": "The correct chronological order of stance phase subdivisions is: initial contact → loading response → mid-stance → terminal stance → pre-swing."},{"id": 3132,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "A patient exhibiting reduced hip extension range of motion (hip flexion contracture) during terminal stance will most likely show which compensatory gait change?","options": [{"key": "A","text": "Increased stride length on the affected side"},{"key": "B","text": "Complete absence of any compensation"},{"key": "C","text": "Early/excessive heel rise, anterior pelvic tilt, or increased lumbar lordosis to compensate for limited terminal hip extension"},{"key": "D","text": "Decreased cadence with no other changes"}],"correct": "C","explanation": "Limited hip extension often results in compensatory strategies such as early heel rise, increased anterior pelvic tilt, or exaggerated lumbar lordosis to functionally achieve forward progression during terminal stance."},{"id": 3133,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Antalgic gait, commonly seen with painful lower limb conditions, is characterized primarily by:","options": [{"key": "A","text": "Increased swing phase duration on the unaffected limb only"},{"key": "B","text": "Complete absence of a limp"},{"key": "C","text": "A shortened stance phase on the painful limb, as the patient minimizes weight-bearing time and load on that side"},{"key": "D","text": "Prolonged stance phase on the painful limb"}],"correct": "C","explanation": "Antalgic gait involves a shortened stance duration on the painful limb, as the individual instinctively reduces the time and load borne on that side to minimize pain."},{"id": 3134,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A patient walking with a shortened step length bilaterally and increased cadence, often seen in Parkinsonian gait, primarily reflects:","options": [{"key": "A","text": "Increased single-limb stance time"},{"key": "B","text": "No relationship to underlying neurological status"},{"key": "C","text": "Normal aging changes only"},{"key": "D","text": "An adaptive/pathological pattern often associated with reduced trunk rotation, decreased arm swing, and postural instability"}],"correct": "D","explanation": "Parkinsonian gait characteristically presents with short, shuffling steps, increased cadence, reduced arm swing, and diminished trunk rotation, reflecting underlying basal ganglia dysfunction affecting movement initiation and amplitude."},{"id": 3135,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "Antalgic gait is best described as:","options": [{"key": "A","text": "A gait pattern caused by muscle weakness"},{"key": "B","text": "A gait pattern with no identifiable cause"},{"key": "C","text": "A pain-avoidance gait pattern characterized by a shortened stance phase on the painful limb"},{"key": "D","text": "A gait pattern seen only in children"}],"correct": "C","explanation": "Antalgic gait is a protective, pain-driven pattern in which the patient minimizes time and weight-bearing on the painful limb, shortening its stance phase."},{"id": 3136,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "Trendelenburg gait is caused primarily by weakness of which muscle(s)?","options": [{"key": "A","text": "Ankle plantarflexors"},{"key": "B","text": "Hip flexors"},{"key": "C","text": "Hip abductors (gluteus medius/minimus) on the stance limb side"},{"key": "D","text": "Quadriceps"}],"correct": "C","explanation": "Weak hip abductors on the stance side fail to stabilize the pelvis, resulting in contralateral pelvic drop during single-limb stance — the hallmark of Trendelenburg gait."},{"id": 3137,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "In true (uncompensated) Trendelenburg gait, during stance on the affected limb, the pelvis on the opposite (swing) side:","options": [{"key": "A","text": "Rises"},{"key": "B","text": "Remains level"},{"key": "C","text": "Rotates only in the transverse plane"},{"key": "D","text": "Drops excessively due to inadequate hip abductor stabilization"}],"correct": "D","explanation": "With weak stance-side hip abductors, the unsupported side of the pelvis drops during single-limb stance instead of being held level or slightly elevated."},{"id": 3138,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Compensated Trendelenburg (gluteus medius lurch) gait involves which trunk movement?","options": [{"key": "A","text": "No trunk movement occurs"},{"key": "B","text": "Trunk leans away from the affected stance limb"},{"key": "C","text": "Trunk leans toward the affected (weak) stance limb to reduce the demand on weak hip abductors"},{"key": "D","text": "Trunk remains rigidly upright"}],"correct": "C","explanation": "Leaning the trunk over the weak stance hip reduces the external adduction moment/demand on the compromised hip abductors, functionally compensating for their weakness."},{"id": 3139,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "Steppage (foot drop) gait is characterized by:","options": [{"key": "A","text": "Reduced stance time on the healthy limb"},{"key": "B","text": "Exaggerated hip and knee flexion during swing phase to help the drooping (dorsiflexor-weak) foot clear the ground"},{"key": "C","text": "Excessive plantarflexion during swing"},{"key": "D","text": "Increased double support only"}],"correct": "B","explanation": "With dorsiflexor weakness/foot drop, the patient compensates by increasing hip and knee flexion during swing to lift the foot enough to avoid dragging the toes."},{"id": 3140,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "Steppage gait is most commonly associated with weakness or paralysis of which muscle?","options": [{"key": "A","text": "Tibialis anterior (dorsiflexors), often due to common peroneal (fibular) nerve injury"},{"key": "B","text": "Quadriceps"},{"key": "C","text": "Gastrocnemius"},{"key": "D","text": "Gluteus medius"}],"correct": "A","explanation": "Weakness of the dorsiflexors, classically from common peroneal nerve palsy, causes foot drop and the resulting compensatory steppage gait pattern."},{"id": 3141,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "A 'foot slap' during loading response occurs due to weakness of which muscle group, resulting in an uncontrolled, audible slap of the foot onto the ground?","options": [{"key": "A","text": "Plantarflexors, contracting excessively"},{"key": "B","text": "Quadriceps"},{"key": "C","text": "Dorsiflexors, unable to eccentrically control the rate of foot plantarflexion after heel strike"},{"key": "D","text": "Hip abductors"}],"correct": "C","explanation": "Foot slap occurs when weak dorsiflexors cannot eccentrically control the foot's descent after heel strike, resulting in the forefoot slapping down uncontrolled."},{"id": 3142,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Gluteus maximus (hip extensor) weakness commonly produces which compensatory gait pattern at initial contact/loading response?","options": [{"key": "A","text": "A posterior trunk lurch (leaning the trunk backward at initial contact) to keep the hip extension moment passively controlled by ligamentous/gravitational forces"},{"key": "B","text": "Excessive knee flexion"},{"key": "C","text": "Excessive hip flexion throughout stance"},{"key": "D","text": "Vaulting gait"}],"correct": "A","explanation": "With weak gluteus maximus, patients often lean the trunk backward at heel strike, shifting the body's line of gravity posterior to the hip joint to passively maintain hip extension without requiring active extensor muscle force."},{"id": 3143,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Quadriceps weakness commonly leads to which compensatory gait strategy during stance to avoid knee buckling?","options": [{"key": "A","text": "No compensation is typically seen"},{"key": "B","text": "Increasing knee flexion during stance"},{"key": "C","text": "Hyperextending (locking) the knee, and/or leaning the trunk forward to shift the ground reaction force line anterior to the knee joint"},{"key": "D","text": "Excessive hip abduction"}],"correct": "C","explanation": "With weak quadriceps, patients often stabilize the knee passively by hyperextending it (locking) or shifting trunk weight forward, moving the GRF line anterior to the knee axis to create a passive extension moment."},{"id": 3144,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A 'vaulting' gait pattern, in which the patient rises up on the toes of the stance limb, is a compensatory strategy commonly used to:","options": [{"key": "A","text": "Reduce stride length"},{"key": "B","text": "Increase clearance for a functionally longer swing limb (e.g., due to leg length discrepancy or inadequate knee/hip/ankle flexion for clearance)"},{"key": "C","text": "Increase double support time"},{"key": "D","text": "Reduce cadence"}],"correct": "B","explanation": "Vaulting (rising onto the stance-limb toes) elevates the body to provide additional ground clearance for the contralateral swinging limb when normal shortening mechanisms (knee flexion, hip flexion, ankle dorsiflexion) are insufficient."},{"id": 3145,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Circumduction gait, in which the swinging limb moves in a lateral arc/semicircle, is a compensatory strategy commonly used for:","options": [{"key": "A","text": "Excess hip flexor strength"},{"key": "B","text": "Inadequate ability to shorten the limb for clearance during swing (e.g., due to knee stiffness, weak dorsiflexors, or a stiff hip/knee), often seen with hemiplegia"},{"key": "C","text": "Reduced walking speed only"},{"key": "D","text": "Excess ankle dorsiflexion range"}],"correct": "B","explanation": "Circumduction allows the limb to clear the ground by swinging outward and around rather than through normal hip/knee flexion, commonly compensating for limited knee flexion or dorsiflexor weakness (e.g., in hemiplegic gait)."},{"id": 3146,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Hip hiking, in which the pelvis on the swing side is elevated by lateral trunk muscles/quadratus lumborum, is a compensatory strategy used primarily to:","options": [{"key": "A","text": "Provide additional limb clearance during swing when knee/hip/ankle flexion is insufficient"},{"key": "B","text": "Increase step width"},{"key": "C","text": "Increase double support time"},{"key": "D","text": "Decrease walking speed intentionally"}],"correct": "A","explanation": "Hip hiking elevates the pelvis on the swing side to functionally shorten and lift the limb for adequate ground clearance when normal joint flexion mechanisms are inadequate."},{"id": 3147,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Excessive lateral trunk lean toward the stance limb during gait (Trendelenburg-type lurch) can be seen bilaterally in patients with:","options": [{"key": "A","text": "Isolated foot drop"},{"key": "B","text": "Unilateral ankle sprain only"},{"key": "C","text": "Isolated knee ligament injury"},{"key": "D","text": "Bilateral hip abductor weakness (e.g., in some myopathies), producing a characteristic 'waddling gait'"}],"correct": "D","explanation": "Bilateral hip abductor weakness, as seen in certain myopathies (e.g., muscular dystrophy), produces a waddling gait with alternating trunk lurches to each side during stance."},{"id": 3148,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Genu recurvatum (knee hyperextension) during stance phase is commonly a compensatory mechanism for:","options": [{"key": "A","text": "Weak quadriceps and/or plantarflexor tightness/spasticity, providing passive knee stability"},{"key": "B","text": "Normal gait variant with no pathological significance"},{"key": "C","text": "Excessive hamstring flexibility only"},{"key": "D","text": "Strong quadriceps"}],"correct": "A","explanation": "Knee hyperextension in stance often compensates for quadriceps weakness (locking the knee passively) or can result from plantarflexor tightness/spasticity pushing the tibia posteriorly."},{"id": 3149,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Excessive/premature knee flexion during stance phase (crouch gait) is commonly seen in patients with:","options": [{"key": "A","text": "Normal healthy adult gait"},{"key": "B","text": "Hamstring or hip flexor tightness/spasticity, combined with weak plantarflexors (e.g., in cerebral palsy)"},{"key": "C","text": "Isolated hip abductor weakness only"},{"key": "D","text": "Isolated ankle sprain"}],"correct": "B","explanation": "Crouch gait, with excessive stance-phase knee flexion, commonly results from hamstring/hip flexor contractures or spasticity combined with weak plantarflexors, frequently seen in cerebral palsy."},{"id": 3150,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Toe-walking (persistent forefoot/toe contact with reduced/absent heel strike) is a classic gait deviation seen in patients with:","options": [{"key": "A","text": "Hip flexor weakness"},{"key": "B","text": "Plantarflexor spasticity/contracture (e.g., in cerebral palsy) or heel cord tightness"},{"key": "C","text": "Normal variation with no clinical significance in adults"},{"key": "D","text": "Isolated dorsiflexor weakness only"}],"correct": "B","explanation": "Persistent toe-walking is classically associated with plantarflexor spasticity or Achilles tendon/heel cord tightness, common in conditions like cerebral palsy."},{"id": 3151,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A scissoring gait pattern, in which the legs cross the midline during swing due to excessive hip adductor activity, is characteristically seen in:","options": [{"key": "A","text": "Normal pediatric gait development"},{"key": "B","text": "Peripheral nerve injury only"},{"key": "C","text": "Spastic diplegia/cerebral palsy, due to hip adductor spasticity"},{"key": "D","text": "Isolated ankle injury"}],"correct": "C","explanation": "Scissoring gait, with legs crossing during swing, results from spasticity of the hip adductors, classically seen in spastic diplegic cerebral palsy."},{"id": 3152,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Parkinsonian (festinating) gait is characterized by:","options": [{"key": "A","text": "Long strides with reduced cadence"},{"key": "B","text": "Wide-based unsteady steps only"},{"key": "C","text": "Excessive hip circumduction"},{"key": "D","text": "Short, shuffling steps, reduced arm swing, stooped posture, and a tendency to progressively speed up (festination)"}],"correct": "D","explanation": "Parkinsonian gait classically shows short shuffling steps, diminished arm swing, flexed/stooped posture, and festination (an involuntary tendency to quicken pace while shortening steps)."},{"id": 3153,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Ataxic (cerebellar) gait is characterized by:","options": [{"key": "A","text": "Reduced step width to enhance stability"},{"key": "B","text": "Narrow base of support with smooth, coordinated steps"},{"key": "C","text": "A wide base of support, staggering, irregular steps with poor coordination and balance"},{"key": "D","text": "Consistent rhythmic stepping with no variability"}],"correct": "C","explanation": "Cerebellar ataxia produces an uncoordinated, wide-based, staggering gait due to impaired coordination of movement and balance."},{"id": 3154,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A high-stepping, wide-based gait with the patient watching their feet (relying heavily on visual input) is characteristic of which type of gait disorder?","options": [{"key": "A","text": "Trendelenburg gait"},{"key": "B","text": "Parkinsonian gait"},{"key": "C","text": "Ataxic (sensory) gait due to proprioceptive loss (e.g., in tabes dorsalis or peripheral neuropathy)"},{"key": "D","text": "Antalgic gait"}],"correct": "C","explanation": "Sensory (proprioceptive) ataxia produces a high-stepping, wide-based gait with visual compensation for lost proprioceptive feedback, classically seen in conditions like tabes dorsalis or severe peripheral neuropathy."},{"id": 3155,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Hemiplegic gait, commonly seen after stroke, is often characterized by which combination of features on the affected side?","options": [{"key": "A","text": "Normal knee flexion with excessive ankle dorsiflexion during swing"},{"key": "B","text": "Circumduction of a stiff, extended lower limb with plantarflexed/inverted foot posture and reduced arm swing"},{"key": "C","text": "Increased cadence with shortened stance time bilaterally"},{"key": "D","text": "Excessive hip flexion with normal arm swing"}],"correct": "B","explanation": "Hemiplegic gait typically presents with a stiff, extended limb that circumducts during swing due to limited knee/hip flexion, along with a plantarflexed/inverted foot posture and diminished arm swing on the affected side."},{"id": 3156,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Diplegic gait (as seen in spastic diplegic cerebral palsy) is often characterized by:","options": [{"key": "A","text": "Unilateral limb involvement only"},{"key": "B","text": "Purely upper limb involvement"},{"key": "C","text": "Complete absence of any spasticity"},{"key": "D","text": "Bilateral lower limb spasticity with scissoring, crouched posture, and toe-walking"}],"correct": "D","explanation": "Diplegic gait involves bilateral lower limb spasticity, commonly producing scissoring, a crouched stance posture, and toe-walking patterns."},{"id": 3157,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Waddling gait, characterized by an exaggerated side-to-side trunk sway during walking, is classically associated with which condition affecting proximal muscle strength?","options": [{"key": "A","text": "Cerebellar disease only"},{"key": "B","text": "Peripheral neuropathy"},{"key": "C","text": "Isolated peripheral nerve entrapment"},{"key": "D","text": "Proximal myopathies (e.g., muscular dystrophy) causing bilateral hip girdle weakness"}],"correct": "D","explanation": "Waddling gait results from bilateral weakness of proximal hip girdle muscles (notably hip abductors), commonly seen in muscular dystrophies and other proximal myopathies."},{"id": 3158,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A patient with a leg length discrepancy commonly demonstrates which of the following compensatory gait strategies?","options": [{"key": "A","text": "No compensation is typically necessary"},{"key": "B","text": "Reduced cadence only, with no other change"},{"key": "C","text": "Vaulting on the longer limb's stance side, or circumduction/hip hiking/toe-walking on the shorter limb's swing side, to achieve adequate clearance"},{"key": "D","text": "Increased double support time only"}],"correct": "C","explanation": "Common compensations for leg length discrepancy include vaulting over the longer stance limb, or circumduction, hip hiking, and toe-walking of the shorter limb to achieve adequate swing-phase clearance."},{"id": 3159,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Antalgic gait secondary to hip pathology (e.g., hip osteoarthritis) commonly presents with which combination of trunk and stance changes on the affected side?","options": [{"key": "A","text": "Trunk leaning toward the painful hip (reducing joint reaction force) combined with shortened stance time on that limb"},{"key": "B","text": "Trunk leaning away from the painful hip, with normal or slightly prolonged stance time"},{"key": "C","text": "No trunk lean, with prolonged stance time"},{"key": "D","text": "Excessive trunk rotation only"}],"correct": "A","explanation": "Painful hip pathology commonly leads to a compensatory trunk lean toward the affected hip (reducing joint compressive forces) along with a shortened stance duration to minimize pain-provoking load and time."},{"id": 3160,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which gait deviation is most likely with an isolated, painful knee effusion limiting full knee extension?","options": [{"key": "A","text": "Circumduction of the unaffected limb"},{"key": "B","text": "A flexed-knee gait pattern throughout stance, avoiding full extension to reduce intra-articular pressure/pain"},{"key": "C","text": "Toe-walking bilaterally"},{"key": "D","text": "Excessive knee hyperextension in stance"}],"correct": "B","explanation": "Knee effusion increases intra-articular pressure, particularly uncomfortable in full extension; patients often adopt a flexed-knee gait to minimize pain, avoiding full stance-phase extension."},{"id": 3161,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Reduced arm swing on one side during gait, combined with a stooped, festinating gait pattern, is most suggestive of:","options": [{"key": "A","text": "Early-stage Parkinsonism, where asymmetric arm swing reduction can be an early clinical sign"},{"key": "B","text": "Cerebellar ataxia exclusively"},{"key": "C","text": "Normal variation of no clinical significance"},{"key": "D","text": "Peripheral nerve injury of the arm"}],"correct": "A","explanation": "Asymmetric reduction in arm swing is a recognized early sign of Parkinson's disease, often preceding more overt gait changes, and can be combined with other classic Parkinsonian gait features as the disease progresses."},{"id": 3162,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A 'lurching' gait, characterized by abrupt trunk movements to compensate for weakness of key stabilizing muscles, is a general term that can be seen with weakness of which muscle groups (among others)?","options": [{"key": "A","text": "Only the intrinsic hand muscles"},{"key": "B","text": "Only the neck flexors"},{"key": "C","text": "Only the wrist extensors"},{"key": "D","text": "Hip abductors, hip extensors, or quadriceps, depending on the specific compensatory pattern"}],"correct": "D","explanation": "Lurching gait patterns broadly describe trunk compensations for weakness of key proximal lower-limb stabilizers, including hip abductors (lateral lurch), hip extensors (posterior lurch), and sometimes knee extensors."},{"id": 3163,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Reduced push-off (weak terminal stance/pre-swing propulsion) is commonly seen with weakness of which muscle group, often resulting in shortened step length on the opposite (forward-stepping) side?","options": [{"key": "A","text": "Hip abductors"},{"key": "B","text": "Neck extensors"},{"key": "C","text": "Ankle plantarflexors (gastrocnemius/soleus)"},{"key": "D","text": "Wrist flexors"}],"correct": "C","explanation": "Weak plantarflexors reduce the propulsive push-off force generated during terminal stance/pre-swing, often shortening the resulting step length of the contralateral advancing limb."},{"id": 3164,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following gait deviations is commonly associated with excessive genu valgum and associated increased Q-angle stress at the knee during stance?","options": [{"key": "A","text": "Increased lateral knee thrust only, with reduced medial stress"},{"key": "B","text": "No effect on the knee during gait"},{"key": "C","text": "Increased medial knee thrust during stance, potentially increasing medial ligament and lateral compartment stress"},{"key": "D","text": "Complete elimination of knee loading"}],"correct": "C","explanation": "Excessive dynamic valgus alignment during stance increases medial-directed thrust at the knee, elevating stress on medial stabilizing structures and altering compartmental loading patterns."},{"id": 3165,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "An excessively wide-based gait pattern (increased step width) is a common compensatory strategy for:","options": [{"key": "A","text": "Improved speed of walking"},{"key": "B","text": "Enhanced confidence with no underlying issue"},{"key": "C","text": "Impaired balance/stability, as seen in cerebellar disorders, sensory ataxia, or fear of falling in elderly patients"},{"key": "D","text": "Normal, healthy young adult gait"}],"correct": "C","explanation": "A widened base of support is a common adaptive strategy to enhance lateral stability in the presence of balance impairments, sensory deficits, or fear of falling."},{"id": 3166,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which gait pattern is characteristically described in patients with ankylosing spondylitis or significant thoracolumbar spinal stiffness, involving reduced trunk rotation and reciprocal arm swing?","options": [{"key": "A","text": "A stiff, robotic-appearing gait with minimal trunk rotation and reduced reciprocal arm swing"},{"key": "B","text": "Excessive lateral trunk lean bilaterally"},{"key": "C","text": "Increased trunk rotation with exaggerated arm swing"},{"key": "D","text": "Normal, unaffected gait pattern"}],"correct": "A","explanation": "Significant spinal stiffness (as in advanced ankylosing spondylitis) reduces normal trunk rotation during gait, producing a stiff, less fluid walking pattern with diminished reciprocal arm swing."},{"id": 3167,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A patient who exhibits toe-first contact instead of normal heel-first contact at initial contact, in the absence of any neurological cause, could suggest which of the following?","options": [{"key": "A","text": "Definite cerebellar pathology"},{"key": "B","text": "Normal gait pattern requiring no further assessment"},{"key": "C","text": "Possible plantarflexor tightness, ankle joint restriction, or pain avoidance at the heel/ankle region"},{"key": "D","text": "Definite hip pathology only"}],"correct": "C","explanation": "Toe-first initial contact in a non-neurological context may indicate reduced ankle dorsiflexion range (tight plantarflexors/joint restriction) or pain avoidance strategies related to the heel/ankle region."},{"id": 3168,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Excessive anterior pelvic tilt observed throughout the gait cycle may be compensatory for which impairment?","options": [{"key": "A","text": "Hip flexion contracture or tight hip flexors, requiring increased lumbar lordosis/anterior pelvic tilt to achieve apparent hip extension"},{"key": "B","text": "Excessive ankle dorsiflexion range"},{"key": "C","text": "Excessive hamstring flexibility"},{"key": "D","text": "Normal, unremarkable gait"}],"correct": "A","explanation": "Limited true hip extension range (due to hip flexor tightness/contracture) is often compensated for by increasing anterior pelvic tilt and lumbar lordosis to create the appearance of adequate terminal stance hip extension."},{"id": 3169,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A shortened stance phase with a correspondingly prolonged relative swing phase on one limb is most consistent with which gait pattern?","options": [{"key": "A","text": "Steppage gait exclusively"},{"key": "B","text": "Antalgic gait, in which the patient minimizes weight-bearing time on the painful limb"},{"key": "C","text": "Trendelenburg gait exclusively"},{"key": "D","text": "Ataxic gait exclusively"}],"correct": "B","explanation": "In antalgic gait, the affected limb characteristically shows a shortened stance phase (minimizing loading time/pain) with a relatively longer swing phase, distinguishing it from the other listed gait patterns."},{"id": 3170,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A gait pattern demonstrating a 'drop foot' with excessive hip and knee flexion during swing, but normal stance phase mechanics otherwise, most specifically isolates a deficit at which phase and structure?","options": [{"key": "A","text": "Stance phase, hip abductors"},{"key": "B","text": "Stance phase, plantarflexors"},{"key": "C","text": "Swing phase, ankle dorsiflexors (tibialis anterior)"},{"key": "D","text": "Loading response, quadriceps"}],"correct": "C","explanation": "Isolated dorsiflexor weakness manifests specifically during swing phase (inadequate foot clearance, compensated by increased hip/knee flexion), while stance phase mechanics generally remain relatively preserved."},{"id": 3171,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Post-stroke patients with hemiplegic gait may show reduced or absent normal knee flexion during swing (a 'stiff-knee gait'), commonly attributed to:","options": [{"key": "A","text": "Complete absence of any muscle activity"},{"key": "B","text": "Weak quadriceps allowing excessive knee flexion"},{"key": "C","text": "Overactive/spastic rectus femoris interfering with normal knee flexion during pre-swing/initial swing"},{"key": "D","text": "Normal, unaffected knee mechanics"}],"correct": "C","explanation": "Inappropriate/prolonged rectus femoris activity during pre-swing and initial swing (a common post-stroke abnormality) restricts normal knee flexion, contributing to a stiff-knee gait pattern and often requiring compensatory circumduction or hip hiking."},{"id": 3172,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Which of the following best explains why patients with painful plantar fasciitis often demonstrate an antalgic gait with reduced terminal stance heel-rise/push-off?","options": [{"key": "A","text": "Increased dorsiflexion range eliminates any gait change"},{"key": "B","text": "Pain during the windlass mechanism (toe dorsiflexion tensioning the plantar fascia during push-off) leads to a protective reduction in normal push-off mechanics"},{"key": "C","text": "Plantar fasciitis has no effect on gait mechanics"},{"key": "D","text": "Increased plantarflexor strength compensates fully with no gait change"}],"correct": "B","explanation": "Since the windlass mechanism tensions the inflamed plantar fascia during toe dorsiflexion/push-off, patients often reduce heel-rise and push-off intensity to avoid pain, altering normal terminal stance/pre-swing mechanics."},{"id": 3173,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "A patient recovering from ACL reconstruction who avoids full knee extension during terminal stance (adopting a persistent slight knee flexion pattern, sometimes called 'quadriceps avoidance gait') is likely doing so to:","options": [{"key": "A","text": "Increase quadriceps demand deliberately"},{"key": "B","text": "Reduce anterior tibial translation/shear stress on the healing graft by minimizing quadriceps-dominant knee extension moments near full extension"},{"key": "C","text": "Increase patellofemoral joint stress intentionally"},{"key": "D","text": "Improve gait speed"}],"correct": "B","explanation": "Quadriceps avoidance gait reduces the knee extension moment near terminal extension (where quadriceps pull can increase anterior tibial shear), theoretically protecting a healing ACL graft, though it can create its own compensatory issues over time."},{"id": 3174,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "In children, an intoeing gait pattern (excessive internal foot progression angle) can result from several levels of rotational malalignment; which of the following is a recognized contributing factor?","options": [{"key": "A","text": "Ankle plantarflexor weakness exclusively"},{"key": "B","text": "Excessive external tibial torsion only"},{"key": "C","text": "Femoral anteversion, internal tibial torsion, or metatarsus adductus"},{"key": "D","text": "Only acquired adult-onset conditions"}],"correct": "C","explanation": "Intoeing gait in children commonly arises from one or more rotational alignment factors including increased femoral anteversion, internal tibial torsion, or forefoot adduction (metatarsus adductus)."},{"id": 3175,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Excessive out-toeing gait pattern may be associated with which of the following, among other possible causes?","options": [{"key": "A","text": "Increased femoral anteversion only"},{"key": "B","text": "Only neurological causes"},{"key": "C","text": "Only cerebellar ataxia"},{"key": "D","text": "External tibial torsion, decreased femoral anteversion (relative retroversion), or compensatory positioning due to hip pathology"}],"correct": "D","explanation": "Out-toeing can result from structural rotational factors such as external tibial torsion or reduced femoral anteversion, and can also be a compensatory positioning strategy in certain hip pathologies."},{"id": 3176,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Which of the following best describes a 'jump knee' or 'stiff knee' gait pattern sometimes seen in cerebral palsy, where the knee shows minimal flexion throughout the gait cycle?","options": [{"key": "A","text": "Complete flaccid paralysis of the entire limb"},{"key": "B","text": "Only affects the ankle, not the knee"},{"key": "C","text": "Co-contraction/spasticity of both quadriceps and hamstrings limiting the normal range of knee flexion-extension throughout the cycle"},{"key": "D","text": "Excessive hamstring weakness allowing hyperflexion"}],"correct": "C","explanation": "Simultaneous spasticity/co-contraction of the quadriceps and hamstrings restricts the knee's normal flexion-extension excursion throughout the gait cycle, producing a stiff-appearing knee pattern."},{"id": 3177,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A patient with weak hip flexors will most likely show which compensatory strategy to advance the limb during swing phase?","options": [{"key": "A","text": "Excessive knee extension throughout swing"},{"key": "B","text": "No compensation is possible; the limb cannot advance at all"},{"key": "C","text": "Using trunk momentum (e.g., posterior pelvic tilt or trunk extension followed by 'flinging' the leg forward) or circumduction to substitute for inadequate hip flexor power"},{"key": "D","text": "Increased plantarflexor activity only"}],"correct": "C","explanation": "With weak hip flexors, patients often generate momentum through trunk movements or substitute compensatory strategies like circumduction to functionally advance the limb during swing."},{"id": 3178,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Easy","question": "A markedly asymmetric gait with a shortened stance phase and step length on one side, combined with reports of localized pain, most strongly suggests which broad category of gait deviation?","options": [{"key": "A","text": "Antalgic (pain-related) gait deviation"},{"key": "B","text": "Neurological gait disorder"},{"key": "C","text": "Ataxic gait disorder"},{"key": "D","text": "Myopathic gait disorder"}],"correct": "A","explanation": "The combination of pain reports with a shortened stance/step length pattern on the affected side is the hallmark presentation of antalgic gait, distinguishing it from primarily neurological or myopathic patterns."},{"id": 3179,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Which of the following observational gait analysis findings would be LEAST consistent with a diagnosis of simple antalgic gait due to unilateral knee osteoarthritis pain?","options": [{"key": "A","text": "Trunk lean toward or away from the affected side to offload the painful joint"},{"key": "B","text": "Reduced walking velocity overall"},{"key": "C","text": "Bilateral, symmetric reduction in stance time on both limbs equally, with no side-to-side asymmetry"},{"key": "D","text": "Shortened stance time on the affected limb"}],"correct": "C","explanation": "True antalgic gait from unilateral pathology typically produces clear side-to-side asymmetry (shortened stance on the affected side); a perfectly symmetric bilateral reduction would be inconsistent with a purely unilateral pain source."},{"id": 3180,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Assistive devices such as a cane are typically prescribed to be used in the hand:","options": [{"key": "A","text": "Contralateral to the affected/weak lower limb, to reduce joint reaction forces on the affected side and normalize the gait pattern (e.g., reciprocal arm-leg pattern)"},{"key": "B","text": "Ipsilateral to the affected/weak lower limb"},{"key": "C","text": "In either hand with no functional difference"},{"key": "D","text": "Only in the dominant hand regardless of limb involvement"}],"correct": "A","explanation": "A cane is generally used in the hand opposite the affected limb, allowing a more normal reciprocal gait pattern and effectively reducing the joint reaction force/load on the affected hip or knee during stance."},{"id": 3181,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Use of a contralateral cane can reduce hip joint reaction force on the affected stance-limb hip primarily by:","options": [{"key": "A","text": "Only affecting the knee, not the hip"},{"key": "B","text": "Having no biomechanical effect on hip joint forces"},{"key": "C","text": "Increasing the effective lever arm of body weight, thereby increasing hip joint force"},{"key": "D","text": "Creating an additional external abductor moment/support force that reduces the demand on the hip abductor muscles, thus lowering the compressive joint reaction force"}],"correct": "D","explanation": "The cane, used contralaterally, provides an external force that reduces the required abductor muscle force needed to stabilize the pelvis during stance, thereby decreasing the resultant hip joint compressive/reaction force."},{"id": 3182,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which gait deviation would most likely be observed in a patient with an isolated, painful bunion (hallux valgus) affecting the great toe?","options": [{"key": "A","text": "No change in gait pattern whatsoever"},{"key": "B","text": "Excessive heel strike force only"},{"key": "C","text": "Reduced great toe dorsiflexion tolerance during terminal stance, often leading to a lateral weight shift and reduced push-off through the first ray"},{"key": "D","text": "Increased weight-bearing on the medial forefoot/great toe during terminal stance push-off"}],"correct": "C","explanation": "Painful hallux valgus limits comfortable great toe dorsiflexion needed for normal windlass/push-off mechanics, often causing patients to shift weight laterally and reduce loading through the first ray during terminal stance."},{"id": 3183,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A patient demonstrating excessive lateral trunk sway to BOTH sides alternately during gait, without significant pain complaints, and with proximal muscle weakness on examination, most likely has which underlying gait pattern?","options": [{"key": "A","text": "Ataxic gait due to cerebellar disease"},{"key": "B","text": "Isolated foot drop gait"},{"key": "C","text": "Bilateral (myopathic) waddling gait"},{"key": "D","text": "Unilateral antalgic gait"}],"correct": "C","explanation": "Bilateral proximal (particularly hip abductor) weakness without significant pain, producing alternating side-to-side trunk sway, is characteristic of myopathic waddling gait."},{"id": 3184,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Reduced single-limb stance time on a specific side during gait analysis is a sensitive but nonspecific finding that could indicate which of the following possibilities?","options": [{"key": "A","text": "Pain, weakness, or instability affecting that limb, requiring further clinical correlation to determine the specific cause"},{"key": "B","text": "Only normal variation with no clinical relevance"},{"key": "C","text": "Only cerebellar pathology"},{"key": "D","text": "Only a leg length discrepancy"}],"correct": "A","explanation": "Reduced single-limb stance time is a general finding seen with various underlying causes (pain, weakness, instability), requiring further clinical assessment to pinpoint the specific etiology."},{"id": 3185,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best describes the clinical value of observational/visual gait analysis in physiotherapy practice?","options": [{"key": "A","text": "It provides a systematic, valuable method to identify deviations from normal gait and helps generate hypotheses about underlying impairments, which are then confirmed with further examination"},{"key": "B","text": "It can only be performed using expensive motion capture equipment"},{"key": "C","text": "It replaces the need for any other clinical examination"},{"key": "D","text": "It has no diagnostic value whatsoever"}],"correct": "A","explanation": "Observational gait analysis is a practical, valuable clinical tool for identifying deviations and forming hypotheses about underlying impairments, which are subsequently confirmed through more detailed examination and testing."},{"id": 3186,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A patient walking with markedly reduced trunk rotation, reduced arm swing bilaterally, small shuffling steps, and difficulty initiating gait ('freezing') most likely has which underlying condition?","options": [{"key": "A","text": "Guillain-Barré syndrome"},{"key": "B","text": "Parkinson's disease"},{"key": "C","text": "Isolated peripheral nerve injury"},{"key": "D","text": "Simple mechanical low back pain"}],"correct": "B","explanation": "This combination of reduced trunk rotation, diminished arm swing, small shuffling steps, and freezing episodes is characteristic of Parkinsonian gait due to Parkinson's disease."},{"id": 3187,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "A patient who demonstrates a wide-based, unsteady gait with a positive Romberg's test (worsening balance with eyes closed) most likely has an underlying deficit primarily in which system?","options": [{"key": "A","text": "Cerebellar system exclusively"},{"key": "B","text": "Purely muscular weakness"},{"key": "C","text": "Proprioceptive/dorsal column (sensory) pathway, as loss of visual compensation unmasks the underlying sensory ataxia"},{"key": "D","text": "Purely visual system pathology"}],"correct": "C","explanation": "A positive Romberg's sign (worsened balance specifically with eyes closed) points toward impaired proprioceptive/somatosensory input, since removing visual compensation reveals the underlying sensory deficit — distinguishing sensory from cerebellar ataxia (which typically remains impaired even with eyes open)."},{"id": 3188,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A patient with peripheral neuropathy affecting sensation in the feet may adopt which compensatory gait strategy to improve safety?","options": [{"key": "A","text": "Faster, less careful walking"},{"key": "B","text": "Increased visual monitoring of foot placement, often with a wider base of support and more cautious, deliberate stepping"},{"key": "C","text": "Reduced visual attention to foot placement"},{"key": "D","text": "No change in gait pattern is typically needed"}],"correct": "B","explanation": "With diminished proprioceptive/sensory feedback from the feet, patients often compensate by relying more heavily on visual input and adopting a wider, more cautious gait pattern to maintain safety and balance."},{"id": 3189,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best distinguishes a myopathic (waddling) gait from a neurogenic (steppage) gait pattern?","options": [{"key": "A","text": "Myopathic gait involves bilateral proximal weakness with trunk sway, while neurogenic steppage gait involves distal weakness (foot drop) with exaggerated hip/knee flexion during swing"},{"key": "B","text": "Both patterns are clinically identical"},{"key": "C","text": "Myopathic gait always involves foot drop"},{"key": "D","text": "Neurogenic gait always involves bilateral trunk sway"}],"correct": "A","explanation": "Myopathic gait typically reflects proximal (hip girdle) weakness with characteristic trunk sway, whereas neurogenic steppage gait reflects distal (ankle dorsiflexor) weakness requiring exaggerated proximal joint flexion for foot clearance."},{"id": 3190,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following gait training strategies would be most appropriate for a patient with mild antalgic gait due to knee osteoarthritis, aiming to reduce joint loading?","options": [{"key": "A","text": "Discouraging any use of assistive devices"},{"key": "B","text": "Encouraging faster walking speed to build tolerance"},{"key": "C","text": "Immediate return to high-impact activity without modification"},{"key": "D","text": "Use of an appropriate assistive device (e.g., contralateral cane), weight management guidance, and gradual, pain-monitored progressive activity"}],"correct": "D","explanation": "Appropriate management of antalgic gait from knee OA typically includes reducing joint loading through assistive devices, addressing modifiable factors like body weight, and progressing activity gradually while monitoring pain response."},{"id": 3191,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which best explains why prolonged compensatory gait patterns (e.g., long-standing Trendelenburg or vaulting gait) can lead to secondary problems over time?","options": [{"key": "A","text": "Compensatory patterns always resolve spontaneously with no lasting effect"},{"key": "B","text": "They only affect psychological wellbeing, not physical structures"},{"key": "C","text": "Sustained abnormal loading and altered biomechanics from compensatory patterns can contribute to secondary pain, joint degeneration, or overuse injuries in other body regions over time"},{"key": "D","text": "Compensatory patterns have no long-term consequences"}],"correct": "C","explanation": "Long-standing compensatory gait patterns alter normal joint loading and movement mechanics, which can contribute to secondary musculoskeletal problems (e.g., low back pain, contralateral joint overuse) if left unaddressed over time."},{"id": 3192,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes 'push-off' insufficiency and its typical compensatory effect on the contralateral limb's step length?","options": [{"key": "A","text": "Push-off insufficiency only affects arm swing"},{"key": "B","text": "Weak push-off always lengthens the opposite step"},{"key": "C","text": "Reduced propulsive push-off on one side typically shortens the step length of the opposite (forward-advancing) limb, since less forward momentum is generated"},{"key": "D","text": "Weak plantarflexor push-off has no effect on the opposite limb"}],"correct": "C","explanation": "Since forward propulsion during push-off contributes momentum for the next step, reduced plantarflexor push-off commonly results in a shortened step length on the contralateral advancing limb."},{"id": 3193,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "A patient with painful first metatarsophalangeal joint arthritis (hallux rigidus) limiting toe dorsiflexion will most likely show which compensatory gait change during terminal stance?","options": [{"key": "A","text": "No change in weight-bearing pattern"},{"key": "B","text": "Excessive heel-first loading throughout stance"},{"key": "C","text": "A lateral weight shift with reduced windlass-mechanism engagement and diminished push-off through the first ray"},{"key": "D","text": "Increased great toe dorsiflexion range with normal push-off"}],"correct": "C","explanation": "Restricted great toe dorsiflexion in hallux rigidus impairs the windlass mechanism, prompting patients to shift weight laterally and reduce loading/push-off through the affected first ray during terminal stance."},{"id": 3194,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following is a key reason physiotherapists perform gait analysis before and after an intervention (e.g., orthotic prescription or strengthening program)?","options": [{"key": "A","text": "Only imaging studies can evaluate intervention effectiveness"},{"key": "B","text": "Gait analysis is only useful for research, not clinical practice"},{"key": "C","text": "To objectively document changes in gait parameters/patterns and evaluate the effectiveness of the intervention"},{"key": "D","text": "Gait analysis has no role in evaluating intervention outcomes"}],"correct": "C","explanation": "Pre- and post-intervention gait analysis allows clinicians to objectively document changes in gait patterns and parameters, providing measurable evidence of intervention effectiveness."},{"id": 3195,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Posture is best defined as:","options": [{"key": "A","text": "The strength of postural muscles"},{"key": "B","text": "The relative arrangement of body parts/segments at a given moment, whether static or dynamic"},{"key": "C","text": "Only the standing position of the body"},{"key": "D","text": "The maximal voluntary range of motion of a joint"}],"correct": "B","explanation": "Posture refers to the position or alignment of body segments relative to one another and to the environment, applicable to static or dynamic conditions."},{"id": 3196,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "'Good' or ideal posture is generally defined as one that:","options": [{"key": "A","text": "Minimizes stress and strain on supporting structures while maintaining balance with minimal energy expenditure"},{"key": "B","text": "Only applies to standing posture"},{"key": "C","text": "Is identical for every individual regardless of body type"},{"key": "D","text": "Requires maximal muscular effort to maintain"}],"correct": "A","explanation": "Ideal posture is characterized by efficient alignment that minimizes mechanical stress on joints, muscles, and ligaments while maintaining balance with minimal energy cost."},{"id": 3197,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In ideal standing posture (lateral view), the line of gravity typically passes through or near which of the following landmarks?","options": [{"key": "A","text": "Ear lobe, shoulder (acromion), midpoint of the trunk, greater trochanter of the hip, slightly anterior to the knee axis, and slightly anterior to the lateral malleolus"},{"key": "B","text": "Only the feet"},{"key": "C","text": "Only the cervical spine"},{"key": "D","text": "Only the lumbar spine"}],"correct": "A","explanation": "The classic plumb line of ideal standing posture passes approximately through the earlobe, shoulder, hip (greater trochanter), just anterior to the knee axis, and just anterior to the lateral malleolus."},{"id": 3198,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The normal spinal curves in the sagittal plane, from superior to inferior, are classically described as:","options": [{"key": "A","text": "All regions lordotic"},{"key": "B","text": "Lordotic cervical, kyphotic thoracic, lordotic lumbar, kyphotic sacral"},{"key": "C","text": "Kyphotic cervical, lordotic thoracic, kyphotic lumbar"},{"key": "D","text": "All regions kyphotic"}],"correct": "B","explanation": "Normal sagittal spinal alignment alternates: cervical lordosis, thoracic kyphosis, lumbar lordosis, and sacral kyphosis."},{"id": 3199,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'lordotic' curve is best described as a curve that is:","options": [{"key": "A","text": "Concave posteriorly (convex anteriorly)"},{"key": "B","text": "Only found in the thoracic spine"},{"key": "C","text": "Absent of any curvature"},{"key": "D","text": "Convex posteriorly"}],"correct": "A","explanation": "Lordosis refers to a curve that is concave posteriorly (or convex anteriorly), as seen normally in the cervical and lumbar regions."},{"id": 3200,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'kyphotic' curve is best described as a curve that is:","options": [{"key": "A","text": "Absent of any curvature"},{"key": "B","text": "Only found in the cervical spine"},{"key": "C","text": "Convex posteriorly (concave anteriorly)"},{"key": "D","text": "Concave posteriorly"}],"correct": "C","explanation": "Kyphosis describes a curve convex posteriorly (concave anteriorly), normally present in the thoracic and sacral regions."},{"id": 3201,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The purpose of the normal spinal curves (alternating lordosis and kyphosis) is primarily to:","options": [{"key": "A","text": "Increase the spine's resistance to axial compressive loads and improve shock absorption compared to a straight column"},{"key": "B","text": "Restrict all spinal movement"},{"key": "C","text": "Decrease the spine's overall strength"},{"key": "D","text": "Eliminate the need for supporting musculature"}],"correct": "A","explanation": "The alternating curves increase the spine's capacity to absorb and distribute compressive loads (following an engineering principle where a curved column has greater load tolerance than a straight one) compared to a perfectly straight column."},{"id": 3202,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Excessive thoracic kyphosis is clinically termed:","options": [{"key": "A","text": "Kyphosis (hyperkyphosis)"},{"key": "B","text": "Spondylolisthesis"},{"key": "C","text": "Scoliosis"},{"key": "D","text": "Lordosis"}],"correct": "A","explanation": "An exaggerated posterior convex curve in the thoracic spine beyond normal limits is termed hyperkyphosis."},{"id": 3203,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Excessive lumbar lordosis is clinically termed:","options": [{"key": "A","text": "Scoliosis"},{"key": "B","text": "Torticollis"},{"key": "C","text": "Hyperlordosis (swayback-type posture, when combined with other findings)"},{"key": "D","text": "Hyperkyphosis"}],"correct": "C","explanation": "An exaggerated anterior convex (posteriorly concave) curve in the lumbar spine is termed hyperlordosis."},{"id": 3204,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Scoliosis is best described as:","options": [{"key": "A","text": "An abnormal lateral (coronal plane) curvature of the spine, often with associated rotation"},{"key": "B","text": "A normal variant requiring no clinical attention"},{"key": "C","text": "Excessive sagittal plane kyphosis"},{"key": "D","text": "A pure sagittal plane lordotic deformity"}],"correct": "A","explanation": "Scoliosis is a three-dimensional spinal deformity primarily characterized by lateral curvature in the coronal plane, typically also involving vertebral rotation."},{"id": 3205,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Forward head posture' is characterized by:","options": [{"key": "A","text": "Anterior translation of the head relative to the shoulders/trunk, often with increased cervical lordosis lower down and upper cervical extension"},{"key": "B","text": "Only lateral flexion of the head"},{"key": "C","text": "The head positioned posterior to the shoulders"},{"key": "D","text": "No change in head position relative to normal alignment"}],"correct": "A","explanation": "Forward head posture involves the head being displaced anteriorly relative to the shoulder line, commonly associated with a lower cervical flexion and upper cervical hyperextension pattern."},{"id": 3206,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Forward head posture is commonly associated with which compensatory upper body changes?","options": [{"key": "A","text": "Increased thoracic kyphosis, protracted/rounded shoulders, and altered scapular positioning"},{"key": "B","text": "Decreased cervical lordosis only"},{"key": "C","text": "Decreased thoracic kyphosis and retracted scapulae"},{"key": "D","text": "No compensatory changes elsewhere in the spine"}],"correct": "A","explanation": "Forward head posture frequently occurs together with increased thoracic kyphosis and protracted (rounded) shoulders, forming a commonly observed postural pattern."},{"id": 3207,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Forward head posture increases mechanical stress on the cervical spine primarily because it:","options": [{"key": "A","text": "Increases the moment arm of the head's weight relative to the cervical spine, requiring greater posterior neck muscle force to maintain the head's position"},{"key": "B","text": "Only affects the lumbar spine"},{"key": "C","text": "Decreases the effective weight of the head relative to the spine"},{"key": "D","text": "Has no effect on cervical muscular demand"}],"correct": "A","explanation": "As the head translates forward, its weight acts through an increasingly longer moment arm relative to the cervical spine, requiring greater sustained posterior cervical muscle activity to support the head against gravity."},{"id": 3208,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Swayback' posture (posterior pelvic tilt with thoracic-lumbar issue) is classically characterized by:","options": [{"key": "A","text": "Anterior pelvic tilt and lumbar hyperlordosis with hip flexion"},{"key": "B","text": "Posterior pelvic tilt, flattened lumbar lordosis, hip extension with the pelvis shifted anteriorly relative to the ankles, and increased thoracic kyphosis"},{"key": "C","text": "Excessive lumbar lordosis without any thoracic change"},{"key": "D","text": "Perfectly neutral alignment throughout"}],"correct": "B","explanation": "Swayback posture involves posterior pelvic tilt with a flattened or absent lumbar lordosis, hip extension with anterior pelvic translation, and increased thoracic kyphosis with forward head posture."},{"id": 3209,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Flat back' posture is characterized primarily by:","options": [{"key": "A","text": "Excessive scoliotic curvature"},{"key": "B","text": "Excessive lumbar lordosis"},{"key": "C","text": "Excessive cervical lordosis only"},{"key": "D","text": "A reduction or flattening of the normal lumbar lordotic curve, often with posterior pelvic tilt"}],"correct": "D","explanation": "Flat back posture is defined by a diminished or absent normal lumbar lordosis, frequently accompanied by posterior pelvic tilt."},{"id": 3210,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Kyphotic-lordotic' posture (military-type posture variant) is characterized by:","options": [{"key": "A","text": "Absence of any pelvic tilt"},{"key": "B","text": "Flattening of both thoracic and lumbar curves"},{"key": "C","text": "Increased thoracic kyphosis combined with increased lumbar lordosis and anterior pelvic tilt"},{"key": "D","text": "Reduced curves throughout the spine"}],"correct": "C","explanation": "This postural type shows an exaggeration of both the thoracic kyphosis and lumbar lordosis, typically with anterior pelvic tilt."},{"id": 3211,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Anterior pelvic tilt is defined as a movement of the pelvis in which the:","options": [{"key": "A","text": "Anterior superior iliac spines (ASIS) tilt anteriorly and inferiorly relative to the posterior superior iliac spines (PSIS)"},{"key": "B","text": "Pelvis rotates purely in the transverse plane"},{"key": "C","text": "Posterior superior iliac spines (PSIS) move upward relative to the anterior superior iliac spines (ASIS)"},{"key": "D","text": "Pelvis shifts purely laterally with no rotation"}],"correct": "A","explanation": "Anterior pelvic tilt involves the ASIS moving downward and forward relative to the PSIS, typically increasing lumbar lordosis."},{"id": 3212,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Posterior pelvic tilt is defined as a movement of the pelvis in which the:","options": [{"key": "A","text": "No sagittal plane motion of the pelvis occurs"},{"key": "B","text": "Pelvis tilts purely laterally"},{"key": "C","text": "ASIS moves anteriorly and inferiorly"},{"key": "D","text": "PSIS moves inferiorly while the ASIS moves superiorly and posteriorly, generally flattening the lumbar lordosis"}],"correct": "D","explanation": "Posterior pelvic tilt describes the ASIS rotating upward/backward relative to the PSIS, typically reducing or flattening lumbar lordosis."},{"id": 3213,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Excessive anterior pelvic tilt is commonly associated with tightness of which muscle group and weakness of which opposing group?","options": [{"key": "A","text": "Tight hip extensors; weak hip flexors"},{"key": "B","text": "Tight hip flexors and lumbar erector spinae; weak abdominal muscles and hip extensors"},{"key": "C","text": "Tight abdominals; weak hip flexors"},{"key": "D","text": "No specific muscular pattern is typically associated"}],"correct": "B","explanation": "Excessive anterior pelvic tilt is classically linked to tight hip flexors and lumbar erector spinae, combined with relative weakness of the abdominal muscles and hip extensors (gluteals), part of the classic 'lower crossed syndrome'."},{"id": 3214,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The 'lower crossed syndrome' (Janda's model) describes a pattern of muscle imbalance involving:","options": [{"key": "A","text": "Tight abdominals and weak hip flexors"},{"key": "B","text": "A pattern seen only in the cervical spine"},{"key": "C","text": "Tight hamstrings and weak quadriceps only"},{"key": "D","text": "Tight hip flexors/lumbar extensors crossed with weak abdominals/gluteals, contributing to anterior pelvic tilt and increased lumbar lordosis"}],"correct": "D","explanation": "Lower crossed syndrome describes a diagonal pattern of tightness (hip flexors, lumbar erector spinae) crossed with weakness (abdominals, gluteus maximus/medius), contributing to characteristic postural changes including increased anterior pelvic tilt and lumbar lordosis."},{"id": 3215,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The 'upper crossed syndrome' (Janda's model) describes a pattern of muscle imbalance involving:","options": [{"key": "A","text": "Tight upper trapezius/levator scapulae/pectoralis muscles crossed with weak deep cervical flexors and lower trapezius/serratus anterior, contributing to forward head and rounded shoulder posture"},{"key": "B","text": "Tight hip extensors and weak hip flexors"},{"key": "C","text": "A pattern seen only in the lumbar spine"},{"key": "D","text": "Tight abdominals and weak hip flexors"}],"correct": "A","explanation": "Upper crossed syndrome describes tightness of the upper trapezius, levator scapulae, and pectoral muscles combined with weakness of deep cervical flexors and scapular stabilizers (lower trapezius, serratus anterior), contributing to forward head and rounded shoulder posture."},{"id": 3216,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Postural control refers to the ability to:","options": [{"key": "A","text": "Move as fast as possible in any direction"},{"key": "B","text": "Maximize muscular strength only"},{"key": "C","text": "Control the body's position in space for the purposes of stability (maintaining COG within the base of support) and orientation (maintaining appropriate relationship between body segments and the environment)"},{"key": "D","text": "Achieve maximal joint range of motion"}],"correct": "C","explanation": "Postural control encompasses both stability (balance) and orientation (appropriate alignment relative to gravity, the support surface, and visual surroundings)."},{"id": 3217,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "'Postural stability' specifically refers to the ability to:","options": [{"key": "A","text": "Achieve maximal flexibility"},{"key": "B","text": "Maintain the body's center of gravity within its base of support, whether in static or dynamic conditions"},{"key": "C","text": "Rotate the trunk maximally"},{"key": "D","text": "Only apply to standing balance, never sitting or dynamic tasks"}],"correct": "B","explanation": "Postural stability is the capacity to control the body's COG relative to the BOS during both static and dynamic activities, maintaining equilibrium."},{"id": 3218,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Postural orientation' specifically refers to the ability to:","options": [{"key": "A","text": "Prevent any movement of body segments"},{"key": "B","text": "Maintain an appropriate relationship between the body segments, and between the body and the environment (gravity, support surface, visual surround), for a given task"},{"key": "C","text": "Maintain balance only"},{"key": "D","text": "Only apply to spinal alignment"}],"correct": "B","explanation": "Postural orientation involves aligning body segments appropriately relative to gravity, the support surface, and the visual environment, tailored to the specific task being performed."},{"id": 3219,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Anticipatory postural adjustments (APAs) are defined as:","options": [{"key": "A","text": "Reflexes limited to the vestibular system"},{"key": "B","text": "Random muscle activity with no functional purpose"},{"key": "C","text": "Preparatory postural muscle activations that occur just before a voluntary movement, in order to counteract the expected destabilizing effects of that movement"},{"key": "D","text": "Reactive muscle responses that occur after a perturbation has already displaced the COG"}],"correct": "C","explanation": "APAs are feedforward postural muscle activations that precede a voluntary movement, preparing the body to counteract the anticipated disturbance to balance caused by that movement."},{"id": 3220,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A classic example of an anticipatory postural adjustment is:","options": [{"key": "A","text": "A reflexive stumble correction after tripping"},{"key": "B","text": "The stretch reflex in an isolated muscle"},{"key": "C","text": "Purely voluntary movement with no preparatory activity"},{"key": "D","text": "Activation of postural trunk/leg muscles slightly before a rapid arm-raising movement, to counteract the expected reactive forces on the body's balance"}],"correct": "D","explanation": "Before a rapid voluntary arm movement, postural muscles (e.g., in the legs and trunk) typically activate slightly ahead of the prime mover, anticipating and counteracting the resulting reactive forces on balance."},{"id": 3221,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Compensatory (reactive) postural adjustments differ from anticipatory postural adjustments in that they:","options": [{"key": "A","text": "Occur before a voluntary movement"},{"key": "B","text": "Never involve muscle activation"},{"key": "C","text": "Occur after an unexpected external perturbation has already begun to displace the body's center of gravity, as a corrective response"},{"key": "D","text": "Are identical in timing and function to APAs"}],"correct": "C","explanation": "Compensatory postural adjustments are reactive responses triggered after an unexpected balance disturbance has occurred, aiming to restore equilibrium, in contrast to the feedforward nature of APAs."},{"id": 3222,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which sensory systems are integrated by the central nervous system to achieve effective postural control?","options": [{"key": "A","text": "Only the auditory system"},{"key": "B","text": "Only the visual system"},{"key": "C","text": "Only the gustatory and olfactory systems"},{"key": "D","text": "Visual, vestibular, and somatosensory (proprioceptive) systems"}],"correct": "D","explanation": "Effective postural control relies on the central integration of visual, vestibular, and somatosensory (proprioceptive) information about body position and movement."},{"id": 3223,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Sensory reweighting in postural control refers to the CNS's ability to:","options": [{"key": "A","text": "Only occur in pathological conditions"},{"key": "B","text": "Rely on a single fixed sensory system regardless of circumstances"},{"key": "C","text": "Dynamically shift reliance among the visual, vestibular, and somatosensory systems depending on which is providing the most accurate/reliable information in a given context"},{"key": "D","text": "Ignore all sensory input during quiet standing"}],"correct": "C","explanation": "Sensory reweighting describes the CNS's adaptive process of adjusting the relative reliance on each sensory system for postural control, based on the accuracy and availability of information from each source in a given situation."},{"id": 3224,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Standing on a compliant (foam) surface with eyes open challenges postural control primarily by reducing the reliability of which sensory input, requiring greater reliance on vision and vestibular input?","options": [{"key": "A","text": "Auditory input"},{"key": "B","text": "Somatosensory/proprioceptive input from the feet and ankles"},{"key": "C","text": "Vestibular input specifically"},{"key": "D","text": "Visual input"}],"correct": "B","explanation": "A compliant surface distorts and reduces the reliability of somatosensory feedback from the feet/ankles, requiring the CNS to rely more heavily on visual and vestibular information to maintain balance."},{"id": 3225,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Standing with eyes closed on a firm, stable surface primarily challenges postural control by removing:","options": [{"key": "A","text": "Visual input, requiring greater reliance on vestibular and somatosensory information"},{"key": "B","text": "Somatosensory input entirely"},{"key": "C","text": "All sensory input simultaneously"},{"key": "D","text": "Vestibular input entirely"}],"correct": "A","explanation": "Closing the eyes eliminates visual feedback, requiring the CNS to rely more heavily on vestibular and somatosensory information to maintain postural control."},{"id": 3226,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'sensory organization test' (SOT), often performed using computerized posturography, evaluates a person's ability to:","options": [{"key": "A","text": "Only test cognitive function"},{"key": "B","text": "Measure joint range of motion exclusively"},{"key": "C","text": "Only assess muscle strength"},{"key": "D","text": "Maintain balance under varying conditions that selectively challenge or eliminate visual and/or somatosensory input, assessing the individual's reliance on and integration of different sensory systems"}],"correct": "D","explanation": "The SOT systematically manipulates visual and support-surface conditions to assess how well an individual can maintain balance when relying on different combinations/accuracy of sensory information."},{"id": 3227,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Postural sway during quiet standing is typically measured using which type of equipment?","options": [{"key": "A","text": "MRI scanner"},{"key": "B","text": "Force platform (posturography), which records center of pressure movement"},{"key": "C","text": "Goniometer"},{"key": "D","text": "Electromyography exclusively"}],"correct": "B","explanation": "Force platforms are commonly used to quantify postural sway by recording the movement of the center of pressure during quiet standing or other balance tasks."},{"id": 3228,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Ideal sitting posture is generally characterized by:","options": [{"key": "A","text": "Requires the same alignment regardless of the seat/chair design"},{"key": "B","text": "Excessive thoracic kyphosis with the pelvis rolled fully posterior"},{"key": "C","text": "Maintenance of a relatively normal lumbar lordosis, with the hips and knees flexed to approximately 90 degrees and feet supported on the floor"},{"key": "D","text": "Complete flattening (loss) of the lumbar lordosis"}],"correct": "C","explanation": "Ideal sitting posture aims to preserve a near-normal lumbar lordosis (often aided by lumbar support), with hips/knees at approximately 90° and feet adequately supported."},{"id": 3229,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Prolonged slouched sitting (posterior pelvic tilt with flattened/reversed lumbar lordosis) tends to increase mechanical stress on which spinal structure?","options": [{"key": "A","text": "The posterior elements (facet joints) primarily"},{"key": "B","text": "The intervertebral discs, particularly increasing posterior disc pressure/loading and stress on posterior ligamentous structures"},{"key": "C","text": "No structure is significantly affected"},{"key": "D","text": "Only the cervical spine is affected"}],"correct": "B","explanation": "Slouched sitting with a flattened/reversed lumbar lordosis increases stress on the posterior intervertebral disc and associated ligamentous structures due to the altered flexed spinal alignment."},{"id": 3230,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The provision of a lumbar support/roll in a chair is intended to:","options": [{"key": "A","text": "Eliminate the need for good postural habits"},{"key": "B","text": "Increase thoracic kyphosis"},{"key": "C","text": "Help maintain the normal lumbar lordosis during prolonged sitting, reducing stress on posterior spinal structures"},{"key": "D","text": "Increase lumbar flexion"}],"correct": "C","explanation": "Lumbar support is designed to encourage maintenance of the natural lumbar curve during sitting, thereby reducing abnormal stress on posterior spinal structures associated with a flattened/flexed lumbar posture."},{"id": 3231,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following postural habits is most likely to contribute to increased intradiscal pressure in the lumbar spine?","options": [{"key": "A","text": "Standing with normal lumbar lordosis"},{"key": "B","text": "Prolonged slouched sitting with lumbar flexion"},{"key": "C","text": "Lying supine with knees supported"},{"key": "D","text": "Standing with slight lumbar extension"}],"correct": "B","explanation": "Slouched sitting with lumbar flexion has been shown in classic intradiscal pressure studies (e.g., Nachemson) to increase pressure within the lumbar intervertebral discs compared to more neutral or extended postures."},{"id": 3232,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "According to classic intradiscal pressure research, which position generally results in the LOWEST lumbar disc pressure?","options": [{"key": "A","text": "Sitting while leaning forward without support"},{"key": "B","text": "Supine lying position"},{"key": "C","text": "Unsupported sitting, slouched"},{"key": "D","text": "Standing upright with normal lordosis"}],"correct": "B","explanation": "Classic intradiscal pressure studies have shown that supine lying generally produces the lowest lumbar disc pressures compared to sitting or standing positions."},{"id": 3233,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "According to classic intradiscal pressure research, which position generally results in the HIGHEST lumbar disc pressure?","options": [{"key": "A","text": "Standing upright"},{"key": "B","text": "Unsupported sitting while leaning forward, especially with added weight in the hands"},{"key": "C","text": "Standing with a slight forward lean and hands on hips"},{"key": "D","text": "Supine lying"}],"correct": "B","explanation": "Forward-leaning, unsupported sitting (particularly when combined with lifting or holding weight) has been shown to produce the highest lumbar intradiscal pressures among common postures."},{"id": 3234,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Postural muscles (often termed 'tonic' or 'stabilizer' muscles) are generally characterized by which of the following properties compared to 'phasic' (mobilizer) muscles?","options": [{"key": "A","text": "No functional difference from phasic muscles"},{"key": "B","text": "Complete absence of any fiber type distinction"},{"key": "C","text": "A tendency toward tightness/shortening with overuse or dysfunction, a predominance of slow-twitch (Type I) fibers, and a primary role in sustained postural support"},{"key": "D","text": "A tendency toward weakness and lengthening with disuse, and a predominance of fast-twitch fibers"}],"correct": "C","explanation": "Postural (tonic) muscles tend to shorten/tighten with dysfunction, contain a higher proportion of fatigue-resistant Type I fibers, and are specialized for sustained, low-level activity to support posture."},{"id": 3235,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Phasic (mobilizer) muscles, in contrast to postural (tonic) muscles, are generally characterized by:","options": [{"key": "A","text": "Predominantly Type I fiber composition"},{"key": "B","text": "Identical function to postural muscles"},{"key": "C","text": "A tendency toward weakness/lengthening (inhibition) with dysfunction, and a role primarily in producing movement rather than sustained postural support"},{"key": "D","text": "A tendency toward tightness with dysfunction"}],"correct": "C","explanation": "Phasic muscles tend to weaken and become inhibited with dysfunction/disuse and are primarily specialized for generating movement rather than providing sustained postural support."},{"id": 3236,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which of the following is generally classified as a 'postural' (tonic-tendency) muscle, prone to tightness with dysfunction?","options": [{"key": "A","text": "Vastus medialis"},{"key": "B","text": "Iliopsoas (hip flexor)"},{"key": "C","text": "Gluteus maximus"},{"key": "D","text": "Serratus anterior"}],"correct": "B","explanation": "Iliopsoas is classically categorized among postural (tonic) muscles that tend toward tightness and shortening with dysfunction, in Janda's classification model."},{"id": 3237,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which of the following is generally classified as a 'phasic' (mobilizer-tendency) muscle, prone to weakness/inhibition with dysfunction?","options": [{"key": "A","text": "Hamstrings"},{"key": "B","text": "Hip flexors (iliopsoas)"},{"key": "C","text": "Upper trapezius"},{"key": "D","text": "Gluteus maximus"}],"correct": "D","explanation": "Gluteus maximus is classically categorized among phasic muscles prone to weakness and inhibition with dysfunction, per Janda's classification model."},{"id": 3238,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following postural deviations is commonly associated with pregnancy, due to the added anterior abdominal weight?","options": [{"key": "A","text": "Decreased thoracic kyphosis exclusively"},{"key": "B","text": "No change in maternal posture typically occurs"},{"key": "C","text": "Posterior pelvic tilt with flattened lumbar lordosis"},{"key": "D","text": "Increased anterior pelvic tilt and lumbar lordosis to shift the line of gravity posteriorly and maintain balance over the base of support"}],"correct": "D","explanation": "As abdominal weight increases anteriorly during pregnancy, many women adopt an increased anterior pelvic tilt and lumbar lordosis to help keep the overall line of gravity within the base of support."},{"id": 3239,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Occupational postures involving prolonged, repetitive forward head and rounded shoulder positioning (e.g., prolonged computer/desk work) are commonly associated with the development of:","options": [{"key": "A","text": "No musculoskeletal consequences"},{"key": "B","text": "Upper crossed syndrome-type postural changes and associated musculoskeletal discomfort (e.g., neck/shoulder pain)"},{"key": "C","text": "Only lower limb postural changes"},{"key": "D","text": "Improved postural muscle balance over time"}],"correct": "B","explanation": "Sustained forward head and rounded shoulder postures common in desk-based occupations are strongly associated with the development of upper crossed syndrome patterns and related musculoskeletal symptoms."},{"id": 3240,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Ergonomic recommendations for computer workstation setup (e.g., monitor at eye level, adequate lumbar support, feet flat on floor) primarily aim to:","options": [{"key": "A","text": "Have no biomechanical rationale"},{"key": "B","text": "Increase postural stress deliberately"},{"key": "C","text": "Minimize sustained abnormal postural loading and reduce risk of associated musculoskeletal discomfort during prolonged sitting/computer use"},{"key": "D","text": "Only improve aesthetic appearance of the workstation"}],"correct": "C","explanation": "Ergonomic workstation guidelines are designed to promote more neutral, less stressful postural alignment during prolonged tasks, reducing cumulative musculoskeletal strain."},{"id": 3241,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why static postures (e.g., prolonged standing or sitting in one position) can be more fatiguing over time than dynamic activity, despite lower peak muscular forces?","options": [{"key": "A","text": "Static postures require no muscular activity at all"},{"key": "B","text": "Static postures always use less energy overall with no downside"},{"key": "C","text": "Dynamic movement always causes more fatigue than static postures"},{"key": "D","text": "Sustained low-level muscle contraction required to maintain a static position can impair local blood flow and lead to cumulative fatigue and discomfort, unlike the intermittent contraction-relaxation cycles of dynamic movement"}],"correct": "D","explanation": "Prolonged static muscle contraction can compromise local circulation (reducing oxygen/nutrient delivery and metabolite clearance), contributing to cumulative fatigue and discomfort, whereas dynamic movement's alternating contraction-relaxation cycles support better circulation."},{"id": 3242,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "Which best describes the concept of 'postural sway velocity' as measured on a force platform?","options": [{"key": "A","text": "The maximum single displacement of the center of pressure"},{"key": "B","text": "The total time of the standing trial only"},{"key": "C","text": "The average speed at which the center of pressure moves during a quiet standing trial, often used as an indicator of postural control efficiency"},{"key": "D","text": "The height of the person being tested"}],"correct": "C","explanation": "Sway velocity quantifies how quickly the center of pressure moves on average during a balance assessment, with greater sway velocity often indicating reduced postural control efficiency."},{"id": 3243,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the general relationship between aging and postural control?","options": [{"key": "A","text": "Only vestibular changes occur with aging, with no effect on other systems"},{"key": "B","text": "Postural control remains completely unaffected by the aging process"},{"key": "C","text": "Aging typically improves postural control due to accumulated experience"},{"key": "D","text": "Aging is generally associated with a decline in postural control, related to sensory (visual, vestibular, proprioceptive), musculoskeletal, and neuromuscular changes"}],"correct": "D","explanation": "Age-related declines in multiple contributing systems (sensory input, muscle strength, neuromuscular response times) generally lead to a measurable decline in postural control with advancing age."},{"id": 3244,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Postural control assessment and training are important components of physiotherapy management for which of the following patient populations, among others?","options": [{"key": "A","text": "Only pediatric patients"},{"key": "B","text": "Postural training has no clinical application in physiotherapy"},{"key": "C","text": "Only elite athletes with no other patient group relevant"},{"key": "D","text": "Older adults at risk of falls, patients with neurological conditions (e.g., stroke, Parkinson's), and individuals recovering from lower limb or vestibular injuries"}],"correct": "D","explanation": "Postural control assessment and targeted training are clinically important across many populations, including older adults with fall risk, neurological patients, and those recovering from musculoskeletal or vestibular impairments."},{"id": 3245,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A physiotherapist assessing a patient's static standing posture from the side (sagittal view) primarily looks to evaluate alignment of the:","options": [{"key": "A","text": "Only the feet"},{"key": "B","text": "Only the pelvis"},{"key": "C","text": "Ear, shoulder, hip, knee, and ankle relative to an ideal plumb line, along with the natural spinal curves"},{"key": "D","text": "Only the head position with no reference to other landmarks"}],"correct": "C","explanation": "Sagittal-plane static postural assessment involves evaluating the alignment of key body landmarks (ear, shoulder, hip, knee, ankle) relative to the ideal plumb line, along with observation of the natural spinal curves."},{"id": 3246,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A physiotherapist assessing static standing posture from behind (posterior view) primarily looks to evaluate:","options": [{"key": "A","text": "Only ankle dorsiflexion range"},{"key": "B","text": "Symmetry of shoulder height, scapular position, pelvic level, and spinal alignment in the frontal plane (e.g., screening for scoliosis)"},{"key": "C","text": "Only sagittal spinal curves"},{"key": "D","text": "Only hip flexion range"}],"correct": "B","explanation": "Posterior-view postural assessment focuses on frontal-plane symmetry, including shoulder and pelvic height, scapular position, and spinal alignment, useful for screening conditions like scoliosis."},{"id": 3247,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes why maintaining ideal postural alignment is considered biomechanically advantageous over prolonged periods (e.g., standing for extended durations)?","options": [{"key": "A","text": "It only benefits appearance, with no true biomechanical advantage"},{"key": "B","text": "It allows the body's weight to be more efficiently transmitted through bones and ligaments with minimal ongoing muscular energy expenditure needed for support"},{"key": "C","text": "It requires maximal ongoing muscular effort at all times"},{"key": "D","text": "It has no relationship to energy expenditure or joint stress"}],"correct": "B","explanation": "Ideal alignment allows gravitational forces to be transmitted efficiently through the skeletal and ligamentous system, reducing the ongoing muscular effort needed for support and thereby conserving energy over sustained periods."},{"id": 3248,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "A 'military posture' variant, characterized by an exaggerated erect stance with excessive thoracic extension (flattened kyphosis) and increased lumbar lordosis, can potentially increase stress on which spinal structures?","options": [{"key": "A","text": "Posterior facet joints and posterior elements, due to increased extension throughout the spine"},{"key": "B","text": "No structures are affected by this postural variant"},{"key": "C","text": "Only the cervical spine is affected"},{"key": "D","text": "Anterior vertebral bodies primarily"}],"correct": "A","explanation": "Excessive spinal extension throughout the thoracic and lumbar regions in this posture type increases compressive loading on the posterior facet joints and associated structures."},{"id": 3249,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains the biomechanical rationale for teaching a patient with chronic low back pain to avoid prolonged, unsupported, slouched sitting?","options": [{"key": "A","text": "There is no clinical rationale for this advice"},{"key": "B","text": "Slouched sitting has no measurable effect on spinal loading"},{"key": "C","text": "Slouched sitting always reduces spinal stress compared to standing"},{"key": "D","text": "Slouched sitting tends to increase flexion-related stress on lumbar discs and posterior ligamentous structures, which may aggravate certain types of low back pain"}],"correct": "D","explanation": "Prolonged flexed, slouched sitting increases stress on lumbar discs and posterior spinal ligaments, which can be a contributing/aggravating factor for certain presentations of low back pain, informing common postural advice."},{"id": 3250,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The concept of 'postural endurance' refers to a muscle's or muscle group's capacity to:","options": [{"key": "A","text": "Generate maximal force in a single contraction"},{"key": "B","text": "Perform only eccentric contractions"},{"key": "C","text": "Achieve maximal shortening velocity"},{"key": "D","text": "Sustain a contraction against a submaximal load over a prolonged period without significant fatigue, important for maintaining posture over time"}],"correct": "D","explanation": "Postural endurance describes the capacity of postural (tonic) muscles to sustain low-level contractions over extended periods without significant fatigue, essential for maintaining posture throughout daily activities."},{"id": 3251,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Reduced postural (core/trunk) muscle endurance has been associated in research with an increased risk of which of the following?","options": [{"key": "A","text": "Improved athletic performance with no downside"},{"key": "B","text": "No clinical significance whatsoever"},{"key": "C","text": "Only improved postural alignment"},{"key": "D","text": "Increased risk of low back pain and reduced spinal stability during functional activities"}],"correct": "D","explanation": "Diminished endurance capacity of core/trunk postural musculature has been linked in research to reduced spinal stability and an increased risk of developing low back pain."},{"id": 3252,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which best explains the biomechanical benefit of core stability exercises in the management of certain low back pain presentations?","options": [{"key": "A","text": "Core exercises have no biomechanical rationale"},{"key": "B","text": "Improved endurance and coordinated activation of trunk musculature can enhance spinal stability, potentially reducing excessive segmental motion and associated pain in some patients"},{"key": "C","text": "Core stability exercises only affect upper limb function"},{"key": "D","text": "Core exercises always worsen spinal stability"}],"correct": "B","explanation": "Core stabilization training aims to improve the endurance and coordinated timing of trunk muscle activation, which is thought to enhance spinal segmental stability and may benefit certain low back pain presentations."},{"id": 3253,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Which of the following best describes the biomechanical difference between static and dynamic posture?","options": [{"key": "A","text": "There is no meaningful distinction between the two terms"},{"key": "B","text": "Static posture refers to a fixed, non-moving body position (e.g., quiet standing), while dynamic posture refers to alignment and control of body segments during movement (e.g., walking, lifting)"},{"key": "C","text": "Dynamic posture only applies to athletes"},{"key": "D","text": "Static posture refers only to lying down, while dynamic posture refers only to running"}],"correct": "B","explanation": "Static posture describes body alignment at rest without movement, while dynamic posture refers to how body segments are aligned and controlled during active movement tasks."},{"id": 3254,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A therapist instructing a patient in proper lifting mechanics to 'keep the load close to the body' is applying which biomechanical principle related to postural control and spinal loading?","options": [{"key": "A","text": "Only affects upper limb muscle activity"},{"key": "B","text": "Increasing the moment arm of the load relative to the spine, thereby increasing spinal torque demand"},{"key": "C","text": "Minimizing the moment arm/lever arm of the external load relative to the spine, thereby reducing the resultant torque and compressive force on the lumbar spine"},{"key": "D","text": "This instruction has no biomechanical basis"}],"correct": "C","explanation": "Keeping a lifted load close to the body minimizes its moment arm relative to the spine's axis of rotation, reducing the torque (and consequently the compressive muscular/joint force) required at the lumbar spine."},{"id": 3255,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The functional spinal unit (motion segment) consists of:","options": [{"key": "A","text": "Only the intervertebral disc"},{"key": "B","text": "A single vertebra only"},{"key": "C","text": "The entire vertebral column"},{"key": "D","text": "Two adjacent vertebrae and the intervening intervertebral disc and ligaments/facet joints"}],"correct": "D","explanation": "A functional spinal unit (motion segment) comprises two adjacent vertebrae along with the intervertebral disc, facet joints, and connecting ligaments between them."},{"id": 3256,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The vertebral body is primarily responsible for bearing which type of load?","options": [{"key": "A","text": "Rotational load exclusively"},{"key": "B","text": "Tensile load only"},{"key": "C","text": "Shear load exclusively"},{"key": "D","text": "Compressive load, transmitting axial forces through the spine"}],"correct": "D","explanation": "The vertebral body, being relatively large and composed of both cortical and cancellous bone, is primarily designed to bear compressive axial loads."},{"id": 3257,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The intervertebral disc functions primarily to:","options": [{"key": "A","text": "Conduct nerve impulses"},{"key": "B","text": "Absorb shock, distribute compressive loads, and allow multi-directional spinal motion between vertebrae"},{"key": "C","text": "Provide direct muscle attachment"},{"key": "D","text": "Generate active contractile force"}],"correct": "B","explanation": "The intervertebral disc serves as a shock absorber and load distributor between vertebral bodies while also permitting a degree of intersegmental motion."},{"id": 3258,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The nucleus pulposus of the intervertebral disc behaves biomechanically most like a:","options": [{"key": "A","text": "Rigid bony structure"},{"key": "B","text": "Hydrostatic gel that redistributes compressive load radially outward to the annulus fibrosus"},{"key": "C","text": "Purely elastic band with no fluid properties"},{"key": "D","text": "A structure with no functional role in load transmission"}],"correct": "B","explanation": "The nucleus pulposus, being a hydrated gel-like structure, behaves hydrostatically under compression, distributing pressure radially outward onto the surrounding annulus fibrosus."},{"id": 3259,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The annulus fibrosus surrounds the nucleus pulposus and functions primarily to:","options": [{"key": "A","text": "Contain the nucleus pulposus and resist tensile and torsional stresses through its concentric, alternating collagen lamellae"},{"key": "B","text": "Provide a purely compressive load-bearing function only"},{"key": "C","text": "Generate active muscle contraction"},{"key": "D","text": "Conduct proprioceptive signals exclusively with no mechanical role"}],"correct": "A","explanation": "The annulus fibrosus's multiple concentric collagen layers, oriented in alternating directions, allow it to contain the nucleus and resist multidirectional tensile and torsional stresses."},{"id": 3260,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "With aging, the intervertebral disc typically undergoes which of the following changes?","options": [{"key": "A","text": "No measurable changes occur with age"},{"key": "B","text": "Increased nucleus pulposus mobility with age"},{"key": "C","text": "Increased water content and improved elasticity"},{"key": "D","text": "Decreased water content (dehydration), reduced proteoglycan content, and diminished disc height/shock-absorbing capacity"}],"correct": "D","explanation": "Age-related disc degeneration involves progressive dehydration, reduced proteoglycan content, and loss of disc height, diminishing its normal shock-absorbing and load-distributing capacity."},{"id": 3261,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Combined spinal flexion with axial compression (as in improper lifting with a rounded back) tends to increase stress predominantly on which part of the intervertebral disc?","options": [{"key": "A","text": "Posterior and posterolateral annulus, increasing risk of nuclear migration and posterior disc bulging/herniation"},{"key": "B","text": "The nucleus pulposus uniformly in all directions with no directional bias"},{"key": "C","text": "The vertebral body only"},{"key": "D","text": "Anterior annulus"}],"correct": "A","explanation": "Combined flexion and compression increase stress on the posterior/posterolateral annular fibers and can promote posterior migration of nuclear material, elevating herniation risk—hence advice to avoid flexed-spine lifting."},{"id": 3262,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Facet (zygapophyseal) joints in the spine primarily function to:","options": [{"key": "A","text": "Serve only a cosmetic/structural role with no biomechanical function"},{"key": "B","text": "Generate active contractile force"},{"key": "C","text": "Guide and limit the direction of intervertebral motion, and share a portion of compressive/shear load, particularly in extension and rotation"},{"key": "D","text": "Bear the majority of axial compressive load under normal conditions"}],"correct": "C","explanation": "Facet joints guide the specific pattern of motion allowed at each spinal level and share load-bearing responsibility (particularly compressive and shear loads) especially during extension and rotation."},{"id": 3263,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The orientation of the facet joints in the cervical spine (relatively horizontal, approximately 45 degrees) primarily facilitates:","options": [{"key": "A","text": "A greater combined range of flexion-extension, lateral flexion, and rotation compared to other spinal regions"},{"key": "B","text": "Pure axial rotation only"},{"key": "C","text": "Pure flexion-extension with no rotation or lateral flexion"},{"key": "D","text": "Complete restriction of all motion"}],"correct": "A","explanation": "The relatively flatter (more horizontal) orientation of cervical facet joints allows for a greater combined range of multi-planar motion, including significant rotation and lateral flexion coupled with flexion-extension."},{"id": 3264,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The orientation of the facet joints in the thoracic spine (more vertical/coronal, approximately 60 degrees) primarily facilitates greater:","options": [{"key": "A","text": "Distraction only"},{"key": "B","text": "Lateral flexion exclusively"},{"key": "C","text": "Rotation, while limiting flexion-extension range (which is further restricted by the rib cage)"},{"key": "D","text": "Flexion-extension range"}],"correct": "C","explanation": "Thoracic facet orientation, combined with rib cage attachments, favors rotational movement while comparatively limiting flexion-extension range at this spinal region."},{"id": 3265,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The orientation of the facet joints in the lumbar spine (more sagittal, approximately 90 degrees) primarily facilitates greater:","options": [{"key": "A","text": "Rotation"},{"key": "B","text": "Complete restriction of all lumbar motion"},{"key": "C","text": "Only lateral flexion"},{"key": "D","text": "Flexion-extension, while limiting axial rotation"}],"correct": "D","explanation": "The more sagittally oriented lumbar facet joints favor flexion-extension movement while substantially restricting axial rotation at this spinal region compared to the cervical spine."},{"id": 3266,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Coupled motion in the spine refers to the phenomenon in which:","options": [{"key": "A","text": "Only pure, single-plane movement occurs at every level"},{"key": "B","text": "Coupled motion only occurs pathologically"},{"key": "C","text": "No relationship exists between different planes of spinal movement"},{"key": "D","text": "Movement in one plane (e.g., lateral flexion) is consistently accompanied by movement in another plane (e.g., axial rotation) at a given spinal region"}],"correct": "D","explanation": "Coupled motion describes the normal biomechanical phenomenon where movement in one plane is consistently linked with movement in another plane, with characteristic patterns differing by spinal region."},{"id": 3267,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "In the upper/mid cervical spine, lateral flexion and axial rotation are typically coupled such that they occur:","options": [{"key": "A","text": "With no consistent relationship"},{"key": "B","text": "Only in the presence of pathology"},{"key": "C","text": "To the same side (e.g., left lateral flexion coupled with left rotation)"},{"key": "D","text": "To opposite sides (e.g., left lateral flexion coupled with right rotation)"}],"correct": "C","explanation": "In the cervical spine (particularly mid-cervical region), lateral flexion and rotation are typically coupled ipsilaterally (to the same side)."},{"id": 3268,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "In the lumbar spine, coupled motion patterns between lateral flexion and axial rotation are generally considered to be:","options": [{"key": "A","text": "Consistently ipsilateral at all lumbar levels, identical to the cervical spine"},{"key": "B","text": "More variable and less consistent than in the cervical spine, with some studies suggesting contralateral coupling especially in the upper lumbar spine"},{"key": "C","text": "Identical in pattern to the thoracic spine"},{"key": "D","text": "Completely absent, with no coupling occurring in the lumbar spine"}],"correct": "B","explanation": "Lumbar spine coupling patterns between lateral flexion and rotation are less consistent than in the cervical spine, with research showing variability (sometimes contralateral, particularly in upper lumbar segments) across studies and individuals."},{"id": 3269,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The atlanto-occipital joint (C0-C1) primarily allows which movement?","options": [{"key": "A","text": "Predominantly axial rotation"},{"key": "B","text": "No movement; it is a fused joint"},{"key": "C","text": "Predominantly lateral flexion only"},{"key": "D","text": "Predominantly flexion and extension (nodding movement, e.g., 'yes' motion), with minimal rotation"}],"correct": "D","explanation": "The atlanto-occipital joint's convex occipital condyles articulating with the concave superior facets of the atlas primarily allow flexion-extension (nodding), with very limited rotation."},{"id": 3270,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The atlantoaxial joint (C1-C2) primarily allows which movement?","options": [{"key": "A","text": "Predominantly axial rotation (e.g., 'no' head-shaking motion), accounting for a significant portion of total cervical rotation"},{"key": "B","text": "No movement at this level"},{"key": "C","text": "Predominantly lateral flexion"},{"key": "D","text": "Predominantly flexion-extension"}],"correct": "A","explanation": "The atlantoaxial joint, via the dens (odontoid process) pivoting within the ring of the atlas, is specialized for axial rotation, contributing approximately 50% of total cervical rotation."},{"id": 3271,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Approximately what percentage of total cervical spine flexion-extension range of motion occurs at the atlanto-occipital joint (C0-C1)?","options": [{"key": "A","text": "Nearly 100%"},{"key": "B","text": "A relatively small proportion, with most flexion-extension occurring at lower cervical segments, though C0-C1 contributes meaningfully to the 'nodding' component"},{"key": "C","text": "Exactly 50%"},{"key": "D","text": "0%, since C0-C1 permits only rotation"}],"correct": "B","explanation": "While C0-C1 contributes a notable portion of the nodding (flexion-extension) component, the majority of total cervical flexion-extension range occurs across the lower and mid-cervical segments collectively."},{"id": 3272,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The uncovertebral joints (joints of Luschka), found in the lower cervical spine, primarily function to:","options": [{"key": "A","text": "Serve no functional biomechanical role"},{"key": "B","text": "Bear the majority of axial compressive load"},{"key": "C","text": "Guide cervical motion and provide some stability, limiting excessive lateral translation, while a degenerative site relevant to cervical spondylosis"},{"key": "D","text": "Only exist in the lumbar spine"}],"correct": "C","explanation": "Uncovertebral joints in the cervical spine help guide segmental motion and provide stability against excessive lateral translation, and are a common site of degenerative change (osteophyte formation) in cervical spondylosis."},{"id": 3273,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The lumbar spine is generally considered to bear greater compressive loads than the cervical or thoracic spine primarily because:","options": [{"key": "A","text": "It has smaller vertebral bodies than other spinal regions"},{"key": "B","text": "It lacks intervertebral discs"},{"key": "C","text": "It has the least range of motion of any spinal region"},{"key": "D","text": "It supports the cumulative weight of all more superior body segments, and correspondingly has larger vertebral bodies to accommodate this greater load"}],"correct": "D","explanation": "The lumbar spine bears the cumulative weight of the head, trunk, and upper limbs above it, and its vertebral bodies are correspondingly the largest in the spine to accommodate this greater compressive load."},{"id": 3274,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The lumbosacral junction (L5-S1) experiences relatively high shear stress primarily due to:","options": [{"key": "A","text": "Absence of any facet joints at this level"},{"key": "B","text": "The purely vertical orientation of the sacral base"},{"key": "C","text": "The angulation of the sacral base (lumbosacral angle), which creates a forward-sliding tendency for L5 relative to the sacrum under axial load"},{"key": "D","text": "Complete absence of any intervertebral disc at this level"}],"correct": "C","explanation": "The inclined orientation of the sacral base at the lumbosacral junction creates an anterior shear force component under axial loading, contributing to relatively higher shear stress at this level (relevant to conditions like spondylolisthesis)."},{"id": 3275,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Spondylolisthesis refers to:","options": [{"key": "A","text": "Complete dislocation of a facet joint only"},{"key": "B","text": "The anterior (or occasionally posterior) displacement/slippage of one vertebra relative to the adjacent vertebra below it, often due to a defect in the pars interarticularis"},{"key": "C","text": "A benign disc bulge with no vertebral displacement"},{"key": "D","text": "A fracture of the vertebral body"}],"correct": "B","explanation": "Spondylolisthesis describes forward (or less commonly backward) slippage of a vertebra relative to the one below, frequently associated with a pars interarticularis defect (spondylolysis), often at L5-S1."},{"id": 3276,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Spondylolysis refers specifically to:","options": [{"key": "A","text": "Disc herniation only"},{"key": "B","text": "Complete vertebral dislocation"},{"key": "C","text": "A stress fracture or defect in the pars interarticularis of a vertebra, which can predispose to subsequent spondylolisthesis"},{"key": "D","text": "Facet joint arthritis exclusively"}],"correct": "C","explanation": "Spondylolysis is a defect (often a fatigue/stress fracture) in the pars interarticularis, a common precursor to spondylolisthesis if the resulting instability allows vertebral slippage."},{"id": 3277,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Repetitive lumbar hyperextension activities (e.g., in gymnasts or fast bowlers in cricket) are particularly associated with increased risk of:","options": [{"key": "A","text": "Cervical spondylosis"},{"key": "B","text": "Thoracic kyphosis only"},{"key": "C","text": "Anterior disc herniation"},{"key": "D","text": "Spondylolysis/pars interarticularis stress fracture, due to repetitive posterior element loading"}],"correct": "D","explanation": "Repeated hyperextension loading concentrates stress on the posterior elements, particularly the pars interarticularis, increasing the risk of spondylolysis with repetitive extension-based activities."},{"id": 3278,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The sacroiliac joint (SIJ) is classified structurally as a:","options": [{"key": "A","text": "A purely cartilaginous joint with no synovial component"},{"key": "B","text": "A combination synovial and syndesmotic (fibrous) joint, characterized by a small range of motion and significant inherent stability due to strong ligamentous support and irregular joint surfaces"},{"key": "C","text": "Simple hinge (uniaxial) synovial joint with large range of motion"},{"key": "D","text": "A ball-and-socket joint"}],"correct": "B","explanation": "The SIJ has both synovial (anterior/inferior portion) and syndesmotic/ligamentous (posterior/superior portion) characteristics, with irregular, interlocking joint surfaces and strong ligamentous reinforcement contributing to its inherent stability and limited mobility."},{"id": 3279,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The primary function of the sacroiliac joint is to:","options": [{"key": "A","text": "Allow extensive rotational movement similar to the hip joint"},{"key": "B","text": "Provide the majority of trunk flexion-extension range of motion"},{"key": "C","text": "Transmit load between the spine and lower limbs while providing shock absorption and a degree of stress dissipation, with only small amounts of accessory motion"},{"key": "D","text": "Serve no significant biomechanical function"}],"correct": "C","explanation": "The SIJ's primary biomechanical role is to transmit and distribute forces between the axial skeleton (spine) and the lower extremities, providing shock absorption despite its limited range of motion."},{"id": 3280,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "The 'form closure' mechanism contributing to sacroiliac joint stability refers to:","options": [{"key": "A","text": "Inherent stability arising from the close-fitting, irregular bony/cartilaginous surface anatomy of the joint itself"},{"key": "B","text": "Stability provided by active muscle contraction alone"},{"key": "C","text": "Stability provided entirely by ligaments with no contribution from joint shape"},{"key": "D","text": "A pathological mechanism only seen in SIJ dysfunction"}],"correct": "A","explanation": "Form closure describes the passive stability inherent to the SIJ's interlocking, irregular joint surface shape, which resists shear forces independent of muscular or ligamentous tension."},{"id": 3281,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "The 'force closure' mechanism contributing to sacroiliac joint stability refers to:","options": [{"key": "A","text": "Additional dynamic stability provided by the compressive forces generated through ligamentous tension and surrounding muscle activity (e.g., transversus abdominis, multifidus, gluteus maximus, pelvic floor)"},{"key": "B","text": "Only relevant during sleep"},{"key": "C","text": "Stability from bony shape alone"},{"key": "D","text": "A mechanism unrelated to muscle or ligament function"}],"correct": "A","explanation": "Force closure describes the dynamic compression added to the SIJ through coordinated ligamentous tension and muscular activation, enhancing joint stability beyond the passive form closure provided by joint shape alone."},{"id": 3282,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "Nutation of the sacrum (anterior sacral base tilt relative to the ilia) generally results in which effect on sacroiliac ligament tension and joint stability?","options": [{"key": "A","text": "Increases tension in key SIJ ligaments (e.g., sacrotuberous, sacrospinous, interosseous), thereby enhancing joint stability ('close-packing' the SIJ)"},{"key": "B","text": "Has no effect on the ligaments"},{"key": "C","text": "Only affects the pubic symphysis, not the SIJ"},{"key": "D","text": "Decreases ligamentous tension and joint stability"}],"correct": "A","explanation": "Nutation tightens key stabilizing SIJ ligaments, increasing joint stability, which is why this position is often considered analogous to the close-packed position of the SIJ."},{"id": 3283,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Counter-nutation of the sacrum (posterior sacral base tilt relative to the ilia) generally results in:","options": [{"key": "A","text": "Increased force closure automatically"},{"key": "B","text": "Increased ligamentous tension and stability"},{"key": "C","text": "No change in ligament tension"},{"key": "D","text": "Decreased tension in the SIJ ligaments, reducing inherent passive joint stability"}],"correct": "D","explanation": "Counter-nutation reduces tension in the key SIJ-stabilizing ligaments, decreasing the passive stability provided at the joint in this position."},{"id": 3284,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "During single-leg standing/gait, the sacroiliac joint on the stance side experiences which typical movement pattern to help maintain stability under the asymmetric load?","options": [{"key": "A","text": "A combination of nutation and force closure mechanisms (via muscular/ligamentous engagement) that help stabilize the joint under the shifted load"},{"key": "B","text": "Excessive counter-nutation with reduced stability"},{"key": "C","text": "Complete immobility with no adaptive response"},{"key": "D","text": "Dislocation under normal physiological loads"}],"correct": "A","explanation": "During single-limb loading, coordinated nutation and force closure mechanisms help stabilize the SIJ against the asymmetric loading demands of stance phase."},{"id": 3285,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "Which muscle is considered particularly important for providing dynamic force closure stability to the posterior sacroiliac joint, given its broad attachment to the sacrotuberous ligament?","options": [{"key": "A","text": "Rectus abdominis"},{"key": "B","text": "Gluteus maximus"},{"key": "C","text": "Biceps brachii"},{"key": "D","text": "Tibialis anterior"}],"correct": "B","explanation": "Gluteus maximus has fascial connections to the sacrotuberous ligament, and its contraction is thought to contribute to dynamic force closure and stability of the posterior SIJ."},{"id": 3286,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'lumbopelvic rhythm' describes the coordinated movement relationship between:","options": [{"key": "A","text": "The cervical spine and thoracic spine only"},{"key": "B","text": "Lumbar spine motion and pelvic (hip) motion during forward bending and return to upright, ensuring smooth, coordinated trunk flexion-extension"},{"key": "C","text": "The shoulder and elbow joints"},{"key": "D","text": "Only the sacroiliac joint in isolation"}],"correct": "B","explanation": "Lumbopelvic rhythm describes the coordinated sequencing of lumbar spinal flexion combined with pelvic (hip) rotation during forward bending, analogous to scapulohumeral rhythm at the shoulder, allowing efficient, controlled trunk movement."},{"id": 3287,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "During forward bending (trunk flexion) from standing, the typical sequence of the lumbopelvic rhythm involves:","options": [{"key": "A","text": "Simultaneous and equal contribution of lumbar and pelvic motion at every point of the range with no ordered pattern"},{"key": "B","text": "Initial lumbar spine flexion followed by increasing pelvic (hip) rotation, with the lumbar spine often reaching near end-range flexion before hip flexion contributes the remaining range in a full forward bend"},{"key": "C","text": "Only lumbar flexion, with the pelvis remaining completely fixed throughout"},{"key": "D","text": "Only pelvic rotation, with the lumbar spine remaining completely still"}],"correct": "B","explanation": "In a typical forward bending pattern, lumbar spine flexion tends to initiate the movement, with increasing pelvic/hip flexion contributing more substantially as the bend progresses toward full forward flexion."},{"id": 3288,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "During return from full forward flexion to upright standing, the typical order of the lumbopelvic rhythm reversal involves:","options": [{"key": "A","text": "Lumbar extension initiating before hip extension"},{"key": "B","text": "Hip extension (pelvic rotation posteriorly) initiating the return movement, with lumbar extension completing the motion as the trunk approaches upright"},{"key": "C","text": "Only lumbar extension occurs, with no hip contribution"},{"key": "D","text": "No coordinated pattern; both occur randomly"}],"correct": "B","explanation": "The return from flexion to upright typically begins with hip extension (posterior pelvic rotation), with lumbar spine extension completing the movement as the trunk approaches the upright position."},{"id": 3289,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'flexion-relaxation phenomenon' observed in the lumbar erector spinae muscles during full forward bending refers to:","options": [{"key": "A","text": "Increased extensor muscle activity specifically at end-range flexion"},{"key": "B","text": "Continuously increasing muscle activity throughout the entire range of forward flexion"},{"key": "C","text": "A phenomenon observed only in pathological populations, never in healthy individuals"},{"key": "D","text": "A reduction (relative silence) in lumbar extensor muscle EMG activity near full/end-range flexion, as the load is increasingly borne by passive structures (ligaments, facet joints, posterior annulus) rather than active muscle contraction"}],"correct": "D","explanation": "In normal individuals, lumbar erector spinae EMG activity typically decreases (flexion-relaxation) as full forward flexion is approached, with the load shifting to passive posterior spinal structures rather than active muscular support."},{"id": 3290,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Absence of the normal flexion-relaxation phenomenon (i.e., continued high erector spinae activity even at full flexion) is sometimes observed clinically in patients with:","options": [{"key": "A","text": "Only in elite athletes with superior control"},{"key": "B","text": "Completely normal, healthy spines with no clinical significance"},{"key": "C","text": "No known clinical association"},{"key": "D","text": "Chronic low back pain, potentially reflecting altered neuromuscular control strategies"}],"correct": "D","explanation": "Absence or alteration of the normal flexion-relaxation response has been observed in some patients with chronic low back pain, thought to reflect altered motor control or guarding strategies, though its precise clinical significance continues to be researched."},{"id": 3291,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'neutral zone' of a spinal motion segment refers to:","options": [{"key": "A","text": "The initial portion of the range of motion where minimal internal resistance is offered by the spinal structures, before the tissues begin to substantially resist further movement"},{"key": "B","text": "The entire available range of motion at that segment"},{"key": "C","text": "A pathological finding only, never present in healthy segments"},{"key": "D","text": "The position of maximal ligamentous tension"}],"correct": "A","explanation": "The neutral zone describes the part of a joint's range of motion, close to the neutral/resting position, where movement occurs with minimal passive tissue resistance, distinct from the 'elastic zone' where resistance increases toward end range."},{"id": 3292,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "An increase in the size of the neutral zone at a given spinal motion segment, as can occur with ligamentous injury or degeneration, is generally associated with:","options": [{"key": "A","text": "No clinical significance"},{"key": "B","text": "Increased spinal segmental stability"},{"key": "C","text": "Increased spinal segmental instability, as the segment moves through a larger range with less inherent passive resistance/control before tissue restraint engages"},{"key": "D","text": "Decreased risk of pain or dysfunction"}],"correct": "C","explanation": "An enlarged neutral zone reflects reduced passive segmental control/stability, which is associated with clinical spinal instability and has been linked to conditions involving degeneration or ligamentous injury."},{"id": 3293,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Panjabi's model of spinal stability describes three interacting subsystems that contribute to overall spinal stability; these are:","options": [{"key": "A","text": "Only the neural (nervous system) subsystem"},{"key": "B","text": "Only the active (muscular) subsystem"},{"key": "C","text": "Only the passive (ligamentous/osseous) subsystem"},{"key": "D","text": "The passive subsystem (vertebrae, discs, ligaments, joint capsules), the active subsystem (muscles and tendons), and the neural control subsystem (coordinating the active subsystem's response)"}],"correct": "D","explanation": "Panjabi's model describes spinal stability as arising from the interaction of passive structures, active musculature, and the neural control system that coordinates appropriate muscular responses for stability."},{"id": 3294,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "According to Panjabi's model, clinical spinal instability can arise from dysfunction in which of the following?","options": [{"key": "A","text": "Only the neural control subsystem"},{"key": "B","text": "Instability cannot occur if the passive subsystem is intact, regardless of muscular or neural function"},{"key": "C","text": "Any of the three subsystems (passive, active, or neural control), since they function interdependently to maintain overall spinal stability"},{"key": "D","text": "Only the passive subsystem, since muscles and nerves are irrelevant to spinal stability"}],"correct": "C","explanation": "Since the three subsystems function interdependently, dysfunction or impairment in any one of them (passive structures, active muscles, or neural control) can contribute to overall clinical spinal instability."},{"id": 3295,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The transversus abdominis muscle is often emphasized in lumbar spine stability training due to its:","options": [{"key": "A","text": "Superficial location with primarily a cosmetic function"},{"key": "B","text": "Primary role in producing trunk flexion torque"},{"key": "C","text": "Exclusive role in respiration with no relevance to spinal stability"},{"key": "D","text": "Deep location and role in increasing intra-abdominal pressure and providing segmental spinal stability through its attachment to the thoracolumbar fascia, often activating in a feedforward manner before limb movement"}],"correct": "D","explanation": "Transversus abdominis is thought to contribute to spinal stability through increased intra-abdominal pressure and tensioning of the thoracolumbar fascia, and research has shown it often activates in a feedforward (anticipatory) manner prior to limb movements in healthy individuals."},{"id": 3296,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The multifidus muscle contributes to lumbar spine stability primarily through its:","options": [{"key": "A","text": "Sole function as a respiratory muscle"},{"key": "B","text": "Complete absence of any attachment to the lumbar spine"},{"key": "C","text": "Deep, segmental attachments providing intersegmental control and stiffness at each specific spinal level"},{"key": "D","text": "Large, superficial cross-sectional area generating large torque for gross movement"}],"correct": "C","explanation": "Multifidus's deep, short segmental fascicles attach directly between adjacent vertebrae, allowing it to provide fine intersegmental control and stiffness important for local spinal stability."},{"id": 3297,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "Research has shown that in some patients with acute low back pain, there can be a delay in the onset of contraction of which muscle relative to limb movement, potentially impairing normal feedforward spinal stabilization?","options": [{"key": "A","text": "Rectus abdominis"},{"key": "B","text": "Biceps brachii"},{"key": "C","text": "Latissimus dorsi"},{"key": "D","text": "Transversus abdominis"}],"correct": "D","explanation": "Studies have demonstrated delayed onset of transversus abdominis activation relative to limb movements in some individuals with low back pain, suggesting impaired feedforward stabilization strategies."},{"id": 3298,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "The thoracolumbar fascia is thought to contribute to spinal stability and load transfer through which mechanism?","options": [{"key": "A","text": "It exclusively connects the cervical spine to the skull"},{"key": "B","text": "It only functions during respiration"},{"key": "C","text": "It links the abdominal and back musculature, and tension generated through its layers (influenced by muscles like transversus abdominis and latissimus dorsi) can enhance segmental stiffness and assist in load transfer between the trunk and limbs"},{"key": "D","text": "It has no biomechanical function, serving only as a covering"}],"correct": "C","explanation": "The thoracolumbar fascia serves as a connective structure linking multiple trunk and limb muscles, and tension generated through it (influenced by attached musculature) is thought to enhance spinal stiffness and assist force transfer across the lumbopelvic region."},{"id": 3299,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following spinal movements generally produces the greatest increase in intradiscal pressure, according to classic biomechanical research (Nachemson)?","options": [{"key": "A","text": "Sitting while leaning forward and lifting a weight with extended arms"},{"key": "B","text": "Standing at rest"},{"key": "C","text": "Standing with slight lumbar extension"},{"key": "D","text": "Lying supine"}],"correct": "A","explanation": "Combined forward-leaning trunk flexion with lifting a weight at a distance from the body (long lever arm) generates the greatest recorded intradiscal pressures among common postures/activities studied."},{"id": 3300,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why lifting with a 'straight back and bent knees' technique is often recommended over a 'stooped/rounded back' technique?","options": [{"key": "A","text": "Straight back lifting always eliminates all spinal loading"},{"key": "B","text": "Maintaining a more neutral lumbar spine position during lifting helps distribute load more evenly across the disc and reduces flexion-related stress on posterior spinal structures, compared to a fully flexed (stooped) spine position"},{"key": "C","text": "Bent knees increase disc pressure compared to a stooped back"},{"key": "D","text": "It has no actual biomechanical benefit"}],"correct": "B","explanation": "Maintaining relative lumbar neutrality during lifting is thought to promote more even load distribution across the disc and reduce excessive stress on posterior annular and ligamentous structures compared to lifting with a fully flexed (rounded) lumbar spine."},{"id": 3301,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The cervical spine's overall range of flexion-extension is approximately:","options": [{"key": "A","text": "220 degrees"},{"key": "B","text": "10-15 degrees"},{"key": "C","text": "150 degrees"},{"key": "D","text": "80-90 degrees combined (across the entire cervical spine)"}],"correct": "D","explanation": "The cervical spine as a whole typically permits approximately 80-90 degrees of combined flexion-extension range of motion."},{"id": 3302,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The cervical spine's overall range of axial rotation (to one side) is approximately:","options": [{"key": "A","text": "5 degrees"},{"key": "B","text": "150 degrees to one side alone"},{"key": "C","text": "10 degrees"},{"key": "D","text": "80-90 degrees to each side (approximately 160-180 degrees combined bilaterally)"}],"correct": "D","explanation": "The cervical spine allows a substantial range of axial rotation, approximately 80-90 degrees to each side, reflecting its relatively mobile facet orientation, especially at C1-C2."},{"id": 3303,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Thoracic spine axial rotation range of motion is generally __________ than lumbar spine axial rotation range.","options": [{"key": "A","text": "Less than"},{"key": "B","text": "Identical to"},{"key": "C","text": "Impossible to compare, since the thoracic spine has no facet joints"},{"key": "D","text": "Greater than, due to more favorable facet joint orientation for rotation despite rib cage constraints"}],"correct": "D","explanation": "Despite rib cage constraints, the more coronally-oriented thoracic facet joints allow considerably greater rotational range compared to the more sagittally-oriented, rotation-restricting lumbar facets."},{"id": 3304,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Lumbar spine flexion range of motion is generally __________ than lumbar spine extension range.","options": [{"key": "A","text": "Impossible to determine"},{"key": "B","text": "Identical to extension range at every level"},{"key": "C","text": "Greater than, due to the sagittal facet orientation and disc/ligament anatomy generally permitting more flexion than extension"},{"key": "D","text": "Less than"}],"correct": "C","explanation": "The lumbar spine typically demonstrates a greater range of flexion than extension, related to its facet orientation and the mechanical properties of the disc and posterior ligamentous structures."},{"id": 3305,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which spinal ligament is primarily responsible for limiting excessive spinal flexion?","options": [{"key": "A","text": "Anterior longitudinal ligament"},{"key": "B","text": "Only the anterior longitudinal ligament"},{"key": "C","text": "No ligament limits flexion; only muscles do"},{"key": "D","text": "Posterior longitudinal ligament, ligamentum flavum, interspinous and supraspinous ligaments, and facet joint capsules"}],"correct": "D","explanation": "Multiple posterior spinal ligamentous structures (posterior longitudinal ligament, ligamentum flavum, interspinous/supraspinous ligaments) along with facet capsules collectively resist and limit excessive spinal flexion."},{"id": 3306,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which spinal ligament is primarily responsible for limiting excessive spinal extension?","options": [{"key": "A","text": "Interspinous ligament exclusively"},{"key": "B","text": "Posterior longitudinal ligament"},{"key": "C","text": "Ligamentum flavum exclusively"},{"key": "D","text": "Anterior longitudinal ligament"}],"correct": "D","explanation": "The anterior longitudinal ligament, running along the anterior vertebral bodies, is the primary structure resisting and limiting excessive spinal extension."},{"id": 3307,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The ligamentum flavum is unique among spinal ligaments in that it contains a relatively high proportion of:","options": [{"key": "A","text": "Type I collagen only, with no elastic fibers"},{"key": "B","text": "Only cartilage cells"},{"key": "C","text": "No connective tissue proteins at all"},{"key": "D","text": "Elastin (elastic fibers), which allows it to maintain tension and resist buckling into the spinal canal during extension and return to a taut state during flexion"}],"correct": "D","explanation": "The ligamentum flavum's high elastin content allows it to remain relatively taut across the range of motion, helping prevent it from buckling into the spinal canal during extension, unlike most predominantly collagenous ligaments."},{"id": 3308,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following best describes the primary biomechanical function of the rib cage in relation to thoracic spine stability?","options": [{"key": "A","text": "The rib cage has no effect on thoracic spine mechanics"},{"key": "B","text": "The rib cage decreases thoracic spine stability"},{"key": "C","text": "The rib cage significantly increases the stiffness and stability of the thoracic spine, while also somewhat restricting its overall range of motion compared to the more mobile cervical and lumbar regions"},{"key": "D","text": "The rib cage only affects respiratory function, not spinal biomechanics"}],"correct": "C","explanation": "The rib cage's attachments to the thoracic vertebrae substantially increase thoracic spinal stiffness and stability, while also contributing to the comparatively restricted range of motion at this spinal region relative to the cervical and lumbar spine."},{"id": 3309,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A vertebral compression fracture, commonly seen in osteoporotic patients, typically results from excessive:","options": [{"key": "A","text": "Compressive (axial) loading exceeding the weakened bone's strength, often causing anterior wedging of the vertebral body"},{"key": "B","text": "Torsional loading exclusively"},{"key": "C","text": "Tensile loading of the vertebral body"},{"key": "D","text": "Shear loading of the disc only"}],"correct": "A","explanation": "Osteoporotic compression fractures typically result from axial compressive loads exceeding the reduced strength of demineralized bone, often producing characteristic anterior wedging of the vertebral body."},{"id": 3310,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which spinal region is most commonly affected by osteoporotic compression fractures, given typical loading patterns and bone density distribution?","options": [{"key": "A","text": "Cervical spine"},{"key": "B","text": "Sacrum exclusively"},{"key": "C","text": "Thoracolumbar junction and mid-to-lower thoracic spine"},{"key": "D","text": "Coccyx exclusively"}],"correct": "C","explanation": "The thoracolumbar junction and mid-to-lower thoracic spine are common sites for osteoporotic compression fractures, related to the biomechanical transition zone and typical loading patterns in this region."},{"id": 3311,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Whiplash-associated injury of the cervical spine typically results from which type of biomechanical loading mechanism?","options": [{"key": "A","text": "Slow, sustained axial compression"},{"key": "B","text": "Rapid acceleration-deceleration forces (often from rear-end vehicle collisions), producing a combination of hyperextension followed by hyperflexion (or vice versa) of the cervical spine"},{"key": "C","text": "Pure rotational loading only"},{"key": "D","text": "Chronic, low-level static loading over years"}],"correct": "B","explanation": "Whiplash injury classically results from rapid acceleration-deceleration forces, commonly from rear-end collisions, producing a characteristic sequence of cervical hyperextension followed by hyperflexion (or the reverse pattern in frontal impacts)."},{"id": 3312,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'S-curve' deformation pattern sometimes described in early-phase whiplash injury refers to:","options": [{"key": "A","text": "A pattern with no relevance to whiplash biomechanics"},{"key": "B","text": "A curve seen only in chronic degenerative conditions"},{"key": "C","text": "A phenomenon in which lower cervical segments extend while upper cervical segments flex (or vice versa) in the initial milliseconds of the injury, creating localized regions of abnormal segmental motion"},{"key": "D","text": "A uniform, single-direction bending of the entire cervical spine"}],"correct": "C","explanation": "Early-phase whiplash research has described a transient 'S-shaped' deformation, where different cervical segments move in opposing directions (e.g., lower segments extending while upper segments flex) during the very early phase of the injury, potentially concentrating stress at specific levels."},{"id": 3313,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Central spinal canal narrowing (spinal stenosis) in the lumbar spine often results in symptoms that are characteristically worsened by which position?","options": [{"key": "A","text": "Position has no relevance to stenotic symptoms"},{"key": "B","text": "Flexion (e.g., leaning forward), since flexion tends to increase canal dimensions"},{"key": "C","text": "Both flexion and extension equally worsen symptoms with no positional variation"},{"key": "D","text": "Extension (e.g., standing upright or walking), since extension tends to decrease the available space within the spinal canal"}],"correct": "D","explanation": "Extension tends to reduce the cross-sectional area of the spinal canal (due to ligamentum flavum buckling and disc bulging), often worsening stenotic symptoms, while flexion tends to increase canal space and relieve symptoms — explaining why patients with neurogenic claudication often prefer a flexed posture (e.g., leaning on a shopping cart)."},{"id": 3314,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Neurogenic claudication associated with lumbar spinal stenosis is classically relieved by which position/activity?","options": [{"key": "A","text": "Lying prone with the spine extended"},{"key": "B","text": "Forward flexion of the lumbar spine (e.g., sitting, leaning forward, or walking with a flexed posture)"},{"key": "C","text": "Standing upright and walking briskly"},{"key": "D","text": "Running at high speed"}],"correct": "B","explanation": "Since flexion increases available space within the stenotic canal, patients with neurogenic claudication typically find relief with forward flexion postures/activities and worsening symptoms with extension-related activities like standing/walking upright."},{"id": 3315,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best describes the biomechanical rationale for spinal extension exercises (e.g., McKenzie-based extension protocols) in some patients with lumbar disc-related symptoms?","options": [{"key": "A","text": "In certain presentations, repeated extension movements may help promote a relatively anterior migration of nuclear material and reduce pressure on posterior/posterolateral structures, potentially reducing radicular symptoms (this varies by individual presentation, hence the importance of assessment)"},{"key": "B","text": "Extension exercises have no plausible biomechanical rationale"},{"key": "C","text": "Flexion and extension exercises always produce identical effects on the disc"},{"key": "D","text": "Extension exercises always worsen posterior disc herniation"}],"correct": "A","explanation": "In select disc-related presentations (often centralizing with extension), repeated extension movements are theorized to help shift nuclear material anteriorly and reduce compressive/tensile stress on posterior structures irritating a nerve root — although individual assessment is essential since this is not universally appropriate for all presentations."},{"id": 3316,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following best explains why maintaining core/trunk muscular endurance and coordinated activation patterns is emphasized in rehabilitation programs targeting spinal stability, according to Panjabi's model?","options": [{"key": "A","text": "Because only the neural subsystem matters, independent of muscular strength or endurance"},{"key": "B","text": "Because the passive subsystem alone provides sufficient stability regardless of muscular function"},{"key": "C","text": "Because muscular activation has no role in spinal stability according to this model"},{"key": "D","text": "Because coordinated, well-timed activation of the active (muscular) subsystem is essential to compensate for and support the passive subsystem, particularly important when passive structures are compromised (e.g., by injury or degeneration)"}],"correct": "D","explanation": "Since the three subsystems interact, rehabilitation targeting coordinated, adequately enduring muscular activation aims to support and compensate for any deficits in the passive structural subsystem, enhancing overall functional spinal stability."},{"id": 3317,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Excessive repetitive lumbar flexion combined with lateral bending and rotation (as in certain occupational tasks) has been associated in biomechanical research with increased risk of:","options": [{"key": "A","text": "Only affecting the cervical spine, not the lumbar region"},{"key": "B","text": "No increased risk compared to purely sagittal-plane movements"},{"key": "C","text": "Improved disc health with no injury risk"},{"key": "D","text": "Increased risk of disc herniation and other low back injury, due to cumulative multidirectional stress on the annulus fibrosus"}],"correct": "D","explanation": "Combined multi-planar loading (flexion with lateral bending and rotation) has been associated with increased cumulative stress on the annular fibers and elevated risk of disc-related injury in occupational biomechanics research."},{"id": 3318,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the biomechanical function of the interspinous and supraspinous ligaments?","options": [{"key": "A","text": "Have no functional role in spinal biomechanics"},{"key": "B","text": "Primarily resist axial rotation exclusively"},{"key": "C","text": "Primarily resist excessive flexion by limiting the separation of adjacent spinous processes"},{"key": "D","text": "Primarily resist compressive loading"}],"correct": "C","explanation": "These posterior ligaments, connecting adjacent spinous processes, primarily function to resist and limit excessive spinal flexion by restraining the separation of the spinous processes."},{"id": 3319,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The iliolumbar ligament primarily functions to stabilize which spinal region/junction?","options": [{"key": "A","text": "The lumbosacral/L5-iliac junction, helping resist excessive motion of L5 relative to the ilium"},{"key": "B","text": "The cervical spine"},{"key": "C","text": "The atlanto-occipital joint"},{"key": "D","text": "The thoracic spine exclusively"}],"correct": "A","explanation": "The iliolumbar ligament connects the L5 (and sometimes L4) transverse process to the ilium, providing important stability to the lumbosacral junction, particularly resisting excessive L5 motion."},{"id": 3320,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "Which of the following best describes the sacrotuberous ligament's role in sacroiliac joint stability?","options": [{"key": "A","text": "It resists nutation-related counter-forces and, along with tension generated through associated muscle attachments (e.g., biceps femoris, gluteus maximus), contributes to force closure stability of the SIJ"},{"key": "B","text": "It solely provides blood supply to the pelvis"},{"key": "C","text": "It has no role in SIJ stability"},{"key": "D","text": "It only functions during upper limb movement"}],"correct": "A","explanation": "The sacrotuberous ligament, with connections to muscles like the biceps femoris and gluteus maximus, contributes to dynamic force closure stability of the SIJ, resisting excessive counter-nutation and enhancing joint stability during loading."},{"id": 3321,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes normal cervical lordosis's biomechanical purpose, similar to the lumbar lordosis?","options": [{"key": "A","text": "To help distribute axial compressive loads (e.g., the weight of the head) and absorb shock, similar to the function of lumbar lordosis in load-bearing"},{"key": "B","text": "To eliminate the need for cervical musculature"},{"key": "C","text": "To restrict all cervical motion"},{"key": "D","text": "To increase disc herniation risk deliberately"}],"correct": "A","explanation": "Cervical lordosis, like lumbar lordosis, helps the spine more effectively distribute and absorb axial compressive loads (in this case, largely the weight of the head) compared to a straight column."},{"id": 3322,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Loss of normal cervical lordosis (e.g., a 'military neck' or straightened cervical curve) has been associated with:","options": [{"key": "A","text": "Complete elimination of any cervical spine loading"},{"key": "B","text": "Improved shock absorption capacity"},{"key": "C","text": "Altered load distribution through the cervical spine, potentially increasing stress on certain structures and being associated with neck pain in some patients (though causation is debated in research)"},{"key": "D","text": "No biomechanical consequence whatsoever"}],"correct": "C","explanation": "Loss of normal cervical lordosis alters the typical load distribution pattern through the cervical spine and has been associated with neck pain and dysfunction in various studies, although the precise causal relationship remains a topic of ongoing research and debate."},{"id": 3323,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which best explains the biomechanical rationale for encouraging deep cervical flexor muscle strengthening (e.g., craniocervical flexion exercises) in patients with forward head posture and associated neck pain?","options": [{"key": "A","text": "Deep flexor strengthening always worsens neck pain"},{"key": "B","text": "Only superficial neck muscles are relevant to cervical stability"},{"key": "C","text": "Deep cervical flexors have no relevance to cervical spine stability"},{"key": "D","text": "Improved endurance and activation of the deep cervical flexors (e.g., longus colli, longus capitis) is thought to enhance segmental cervical stability and may help counteract dysfunctional patterns associated with forward head posture and chronic neck pain"}],"correct": "D","explanation": "Deep cervical flexor muscles are thought to provide important segmental stabilization to the cervical spine, and their improved activation/endurance is a common rehabilitation target for patients with forward head posture and associated chronic neck pain, based on research showing altered function of these muscles in such populations."},{"id": 3324,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which best explains why the cervical spine, despite having a relatively large range of motion, is considered more vulnerable to certain traumatic injuries compared to the more constrained thoracic spine?","options": [{"key": "A","text": "The cervical spine has no ligamentous support at all"},{"key": "B","text": "The cervical spine's greater mobility (less inherent bony/facet constraint, no rib cage support) allows for larger, potentially more damaging ranges of abnormal motion under traumatic loading (e.g., whiplash) compared to the more rigidly constrained, rib-cage-supported thoracic spine"},{"key": "C","text": "Cervical vertebrae are structurally identical to thoracic vertebrae"},{"key": "D","text": "The cervical spine has thicker, stronger vertebral bodies than the thoracic spine"}],"correct": "B","explanation": "The cervical spine's inherent mobility, lacking the additional rib cage stabilization present in the thoracic spine, allows for greater ranges of abnormal motion under traumatic forces, contributing to its relative vulnerability to certain injury mechanisms like whiplash."},{"id": 3325,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best summarizes the overall biomechanical relationship between the lumbar spine, pelvis, and hip joints during functional activities such as bending and lifting?","options": [{"key": "A","text": "These structures function completely independently with no biomechanical interaction"},{"key": "B","text": "These structures function as an interdependent kinetic chain, with coordinated (lumbopelvic rhythm) movement and stability contributions from each region being essential for efficient, safe performance of functional tasks"},{"key": "C","text": "Only the lumbar spine contributes to functional bending tasks"},{"key": "D","text": "The pelvis and hips have no role in trunk flexion activities"}],"correct": "B","explanation": "Effective, low-stress performance of functional tasks like bending and lifting depends on the coordinated, interdependent function of the lumbar spine, pelvis, and hip joints, working together through mechanisms like lumbopelvic rhythm and combined stability contributions."},{"id": 3326,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the general relationship between intervertebral disc height and the amount of motion available at a given spinal segment?","options": [{"key": "A","text": "Thinner discs always allow greater motion"},{"key": "B","text": "Disc height has no relationship to segmental mobility"},{"key": "C","text": "Disc height only affects compressive strength, not mobility"},{"key": "D","text": "Greater disc height is generally associated with greater segmental mobility, as seen in the comparatively more mobile cervical and lumbar regions versus the thoracic spine"}],"correct": "D","explanation": "Regions with relatively taller intervertebral discs relative to vertebral body height (such as the cervical and lumbar spine) tend to permit greater segmental mobility compared to the thoracic spine, where discs are relatively thinner."},{"id": 3327,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which structure is primarily responsible for resisting excessive lateral flexion of the spine on the side opposite to the direction of bending?","options": [{"key": "A","text": "Ligaments and muscles on the side opposite to (contralateral to) the direction of bending, which are placed under tension"},{"key": "B","text": "The nucleus pulposus exclusively"},{"key": "C","text": "Ligaments on the same side as the bending direction"},{"key": "D","text": "The vertebral body alone"}],"correct": "A","explanation": "During lateral flexion, tissues on the convex (contralateral) side are placed under tension and resist further bending, while tissues on the concave side are relatively unloaded/compressed."},{"id": 3328,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'burst fracture' of a vertebral body, in contrast to a simple compression (wedge) fracture, typically results from:","options": [{"key": "A","text": "High-energy axial compressive loading severe enough to cause the vertebral body to fracture in multiple directions, often with retropulsion of bone fragments into the spinal canal"},{"key": "B","text": "Pure tensile loading"},{"key": "C","text": "Chronic, low-level repetitive loading only"},{"key": "D","text": "Pure rotational loading with no axial component"}],"correct": "A","explanation": "Burst fractures result from severe axial compressive forces that shatter the vertebral body in multiple planes, often causing posterior fragment retropulsion into the spinal canal, distinguishing them from simple anterior wedge compression fractures."},{"id": 3329,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why maintaining adequate hip flexibility (particularly hamstring and hip flexor extensibility) is often emphasized in patients with recurrent low back pain?","options": [{"key": "A","text": "Reduced hip flexibility always improves lumbar spine protection"},{"key": "B","text": "Limited hip mobility can force greater compensatory motion through the lumbar spine during functional activities (e.g., bending, squatting), potentially increasing cumulative lumbar spinal stress over time"},{"key": "C","text": "Hip flexibility has no relationship to lumbar spine mechanics"},{"key": "D","text": "Hip flexibility only affects the cervical spine"}],"correct": "B","explanation": "When hip range of motion is limited, the lumbar spine may be required to compensate with greater motion during functional tasks, potentially increasing cumulative stress on lumbar structures over time — hence the clinical emphasis on adequate hip mobility as part of lumbar spine care."},{"id": 3330,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the general biomechanical effect of prolonged bed rest or spinal immobilization on the intervertebral discs and supporting ligaments?","options": [{"key": "A","text": "Reduced mechanical loading can lead to disc dehydration changes and reduced ligament/connective tissue strength over time, similar to disuse effects seen in other musculoskeletal tissues"},{"key": "B","text": "No measurable effect on spinal tissues"},{"key": "C","text": "Improved disc nutrition and increased ligament strength"},{"key": "D","text": "Immediate, permanent tissue damage within hours"}],"correct": "A","explanation": "Similar to disuse effects seen elsewhere in the musculoskeletal system, prolonged immobilization or reduced loading can lead to unfavorable changes in disc hydration/nutrition and reduced strength of supporting ligamentous tissues over time."},{"id": 3331,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A physiotherapist assessing segmental spinal mobility using passive intervertebral motion testing is primarily evaluating:","options": [{"key": "A","text": "Nerve conduction velocity"},{"key": "B","text": "The relative quality and quantity of accessory motion available at a specific spinal segment, which can help identify hypomobile or hypermobile levels"},{"key": "C","text": "Muscle strength around the spine"},{"key": "D","text": "Cardiovascular fitness"}],"correct": "B","explanation": "Passive intervertebral motion (PIVM) testing allows clinicians to assess segment-specific accessory mobility, helping identify areas of relative hypomobility or hypermobility that may guide treatment."},{"id": 3332,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best describes why the cervical spine is particularly susceptible to degenerative changes (cervical spondylosis) at the mid-to-lower segments (e.g., C5-C6, C6-C7)?","options": [{"key": "A","text": "These segments have no intervertebral discs"},{"key": "B","text": "Degenerative changes occur randomly with no biomechanical basis"},{"key": "C","text": "These segments experience the least mechanical stress of the entire cervical spine"},{"key": "D","text": "These segments experience relatively higher mechanical stress due to their position at the transition between the more mobile upper cervical spine and the relatively fixed thoracic spine, accumulating greater cumulative loading and motion over time"}],"correct": "D","explanation": "The mid-to-lower cervical segments, situated at the biomechanical transition zone between the highly mobile upper cervical spine and the relatively fixed thoracic spine, tend to experience greater cumulative mechanical stress, contributing to a higher prevalence of degenerative changes at these levels."},{"id": 3333,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following is most consistent with the biomechanical rationale for avoiding prolonged, repetitive end-range lumbar flexion in occupational settings involving frequent bending (e.g., repetitive stooping)?","options": [{"key": "A","text": "End-range flexion always strengthens the posterior annulus with no downside"},{"key": "B","text": "Repetitive end-range flexion has no cumulative effect on spinal tissues"},{"key": "C","text": "Repeated loading near end-range flexion increases cumulative stress on posterior annular fibers and posterior ligamentous structures, which may contribute over time to tissue fatigue and increased injury risk"},{"key": "D","text": "Only single, isolated flexion movements pose any biomechanical risk"}],"correct": "C","explanation": "Cumulative, repetitive loading near end-range lumbar flexion concentrates stress on posterior spinal structures, and over time this repetitive stress has been associated with tissue fatigue and increased risk of injury in occupational biomechanics research."},{"id": 3334,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best describes the biomechanical significance of the 'instantaneous axis of rotation' (IAR) concept when applied to spinal segmental motion?","options": [{"key": "A","text": "The IAR concept only applies to peripheral joints, never to the spine"},{"key": "B","text": "The IAR is a fixed, unchanging point identical at every joint angle throughout the range of motion"},{"key": "C","text": "The IAR is unrelated to joint mechanics or pathology"},{"key": "D","text": "The IAR represents the momentary center about which a spinal segment rotates at a specific point in its range, and its location can shift throughout the range of motion, with abnormal IAR patterns sometimes indicating altered or pathological joint mechanics"}],"correct": "D","explanation": "The instantaneous axis of rotation describes the momentary pivot point of a moving segment at a given instant, which can shift throughout the range of motion; alterations in the normal IAR pattern at a spinal segment may reflect abnormal or pathological joint mechanics."},{"id": 3335,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The shoulder complex is composed of how many articulations that work together to allow shoulder motion?","options": [{"key": "A","text": "Two"},{"key": "B","text": "Three"},{"key": "C","text": "Five"},{"key": "D","text": "Four (glenohumeral, acromioclavicular, sternoclavicular, and scapulothoracic)"}],"correct": "D","explanation": "The shoulder complex comprises four articulations: glenohumeral, acromioclavicular, sternoclavicular, and the scapulothoracic 'joint' (a functional, non-synovial articulation)."},{"id": 3336,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "The glenohumeral joint is classified structurally as a:","options": [{"key": "A","text": "Plane (gliding) joint"},{"key": "B","text": "Saddle joint"},{"key": "C","text": "Ball-and-socket (multiaxial) synovial joint"},{"key": "D","text": "Hinge joint"}],"correct": "C","explanation": "The glenohumeral joint is a ball-and-socket synovial joint, allowing extensive multiplanar motion including flexion-extension, abduction-adduction, and rotation."},{"id": 3337,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The glenoid fossa is relatively shallow compared to the size of the humeral head, providing the glenohumeral joint with:","options": [{"key": "A","text": "Great mobility at the expense of inherent bony stability, requiring significant soft tissue support for stability"},{"key": "B","text": "No functional mobility"},{"key": "C","text": "Equal stability and mobility, similar to the hip joint"},{"key": "D","text": "Maximal inherent bony stability but minimal mobility"}],"correct": "A","explanation": "The shallow glenoid relative to the large humeral head allows extensive glenohumeral mobility, but this comes at the cost of reduced inherent bony stability, requiring substantial soft tissue (labrum, capsule, rotator cuff) support."},{"id": 3338,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The glenoid labrum functions primarily to:","options": [{"key": "A","text": "Generate active muscle force"},{"key": "B","text": "Replace the function of the rotator cuff entirely"},{"key": "C","text": "Provide the sole source of joint lubrication"},{"key": "D","text": "Deepen the glenoid fossa and increase the contact area/congruency with the humeral head, enhancing joint stability"}],"correct": "D","explanation": "The fibrocartilaginous glenoid labrum increases the effective depth and surface area of the glenoid, improving congruency with the humeral head and contributing to glenohumeral stability."},{"id": 3339,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The rotator cuff muscles (supraspinatus, infraspinatus, teres minor, subscapularis) contribute to glenohumeral stability primarily by:","options": [{"key": "A","text": "Only producing gross movement with no stabilizing role"},{"key": "B","text": "Preventing any glenohumeral motion"},{"key": "C","text": "Providing the majority of joint compressive force to keep the humeral head centered within the glenoid ('concavity compression') during dynamic movement"},{"key": "D","text": "Acting exclusively as antagonists to each other with no combined function"}],"correct": "C","explanation": "The rotator cuff muscles work synergistically to compress the humeral head into the glenoid fossa (concavity compression), providing crucial dynamic stability throughout the range of shoulder motion."},{"id": 3340,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The 'force couple' formed between the deltoid and rotator cuff during shoulder abduction functions to:","options": [{"key": "A","text": "Cause superior migration of the humeral head with no counterbalancing force"},{"key": "B","text": "Prevent any shoulder abduction from occurring"},{"key": "C","text": "Balance the superior shear force of the deltoid with the inferior/compressive stabilizing force of the rotator cuff, maintaining proper humeral head positioning within the glenoid during elevation"},{"key": "D","text": "Only involve the deltoid, with no rotator cuff contribution"}],"correct": "C","explanation": "During abduction, the deltoid's upward pull is balanced by the rotator cuff's inferior and compressive pull, together forming a force couple that maintains centered humeral head position within the glenoid throughout elevation."},{"id": 3341,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Rotator cuff weakness or dysfunction commonly leads to which abnormal humeral head migration pattern during arm elevation?","options": [{"key": "A","text": "Posterior migration exclusively"},{"key": "B","text": "Superior migration of the humeral head, potentially leading to subacromial impingement"},{"key": "C","text": "Inferior migration only"},{"key": "D","text": "No change in humeral head position"}],"correct": "B","explanation": "Insufficient rotator cuff force to counteract the deltoid's superior pull can result in superior humeral head migration during elevation, narrowing the subacromial space and increasing impingement risk."},{"id": 3342,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Scapulohumeral rhythm describes the coordinated relationship between:","options": [{"key": "A","text": "Elbow flexion and shoulder abduction"},{"key": "B","text": "Wrist motion and shoulder motion"},{"key": "C","text": "Cervical spine motion and shoulder motion"},{"key": "D","text": "Glenohumeral joint motion and scapulothoracic (scapular) motion during arm elevation"}],"correct": "D","explanation": "Scapulohumeral rhythm describes the coordinated ratio and timing of glenohumeral versus scapulothoracic motion that occurs during arm elevation."},{"id": 3343,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The classically cited overall ratio of glenohumeral to scapulothoracic motion during full arm abduction (180 degrees) is approximately:","options": [{"key": "A","text": "5:1"},{"key": "B","text": "1:5"},{"key": "C","text": "2:1 (glenohumeral to scapulothoracic)"},{"key": "D","text": "1:1"}],"correct": "C","explanation": "The traditionally cited overall scapulohumeral rhythm ratio is approximately 2:1, meaning for every 2 degrees of glenohumeral motion, approximately 1 degree of scapulothoracic motion occurs, though this ratio varies throughout the range."},{"id": 3344,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During the first approximately 30 degrees of arm abduction, scapular motion is generally:","options": [{"key": "A","text": "Equal in proportion to glenohumeral motion"},{"key": "B","text": "Completely absent throughout the entire range"},{"key": "C","text": "Minimal, as the glenohumeral joint contributes the majority of the initial motion (sometimes termed the 'setting phase')"},{"key": "D","text": "Greater than glenohumeral motion"}],"correct": "C","explanation": "During the initial phase of abduction (roughly the first 30°), the scapula tends to stabilize (a 'setting phase') while the glenohumeral joint contributes the majority of the early motion."},{"id": 3345,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Scapular upward rotation during arm elevation is important primarily because it helps to:","options": [{"key": "A","text": "Decrease the range of shoulder flexion achievable"},{"key": "B","text": "Eliminate the need for rotator cuff activity"},{"key": "C","text": "Increase compression on the rotator cuff tendons"},{"key": "D","text": "Maintain adequate subacromial space and optimal glenoid orientation relative to the humeral head throughout the elevation range"}],"correct": "D","explanation": "Coordinated scapular upward rotation helps preserve subacromial space and orient the glenoid appropriately beneath the elevating humerus, both important for avoiding impingement and maintaining efficient glenohumeral mechanics."},{"id": 3346,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The muscles primarily responsible for scapular upward rotation during arm elevation are the:","options": [{"key": "A","text": "Only the deltoid"},{"key": "B","text": "Latissimus dorsi and teres major"},{"key": "C","text": "Rhomboids and levator scapulae"},{"key": "D","text": "Upper trapezius, lower trapezius, and serratus anterior, acting as a force couple"}],"correct": "D","explanation": "Upward rotation of the scapula results from the coordinated force couple action of upper trapezius, lower trapezius, and serratus anterior."},{"id": 3347,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The serratus anterior muscle contributes to scapular motion primarily by producing:","options": [{"key": "A","text": "Only scapular elevation"},{"key": "B","text": "Glenohumeral internal rotation exclusively"},{"key": "C","text": "Scapular protraction and upward rotation, along with holding the scapula against the thoracic wall"},{"key": "D","text": "Scapular downward rotation and retraction"}],"correct": "C","explanation": "Serratus anterior is a key contributor to scapular protraction and upward rotation, and it also plays a crucial role in stabilizing the scapula against the rib cage (preventing 'winging')."},{"id": 3348,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Weakness or paralysis of the serratus anterior (e.g., long thoracic nerve injury) classically results in which clinical sign?","options": [{"key": "A","text": "Excessive scapular depression only"},{"key": "B","text": "Increased scapular upward rotation with normal positioning"},{"key": "C","text": "No observable change in scapular position"},{"key": "D","text": "Scapular winging, in which the medial border of the scapula protrudes away from the thoracic wall, particularly evident during forward pushing or arm elevation"}],"correct": "D","explanation": "Serratus anterior weakness classically produces scapular winging, where the medial scapular border lifts away from the rib cage, especially noticeable when pushing against resistance (e.g., a wall push-up test)."},{"id": 3349,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The acromioclavicular (AC) joint allows for which type of motion during arm elevation?","options": [{"key": "A","text": "A relatively small amount of gliding/rotational motion, contributing to overall scapular positioning changes during arm elevation"},{"key": "B","text": "Motion identical in magnitude to the glenohumeral joint"},{"key": "C","text": "The majority of total shoulder complex motion"},{"key": "D","text": "No motion at all; it is a fully fused joint"}],"correct": "A","explanation": "The AC joint permits a modest amount of accessory motion (gliding and some rotation) that contributes to the overall repositioning of the scapula during arm elevation."},{"id": 3350,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The sternoclavicular (SC) joint is the only direct bony/articular connection between:","options": [{"key": "A","text": "The cervical spine and the scapula"},{"key": "B","text": "The glenohumeral joint and the elbow"},{"key": "C","text": "The scapula and humerus"},{"key": "D","text": "The upper extremity (via the clavicle) and the axial skeleton (sternum)"}],"correct": "D","explanation": "The SC joint represents the sole direct articulation connecting the upper extremity (through the clavicle) to the axial skeleton, making it biomechanically important for transmitting forces between the arm and trunk."},{"id": 3351,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Clavicular elevation and rotation at the sternoclavicular joint are essential components of normal:","options": [{"key": "A","text": "Hip flexion"},{"key": "B","text": "Elbow flexion"},{"key": "C","text": "Wrist extension"},{"key": "D","text": "Full overhead arm elevation, since adequate clavicular motion is required for proper scapular positioning throughout the range"}],"correct": "D","explanation": "Normal clavicular elevation and posterior rotation at the SC joint are necessary to allow the scapula to achieve appropriate positioning during full overhead arm elevation."},{"id": 3352,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The subacromial space, located between the acromion/coracoacromial arch superiorly and the humeral head inferiorly, contains which key structures?","options": [{"key": "A","text": "The supraspinatus tendon, subacromial bursa, and portions of the long head of biceps tendon"},{"key": "B","text": "Only the axillary nerve"},{"key": "C","text": "Only the deltoid muscle"},{"key": "D","text": "Only bone, with no soft tissue structures"}],"correct": "A","explanation": "The subacromial space houses important soft tissue structures including the supraspinatus tendon, subacromial bursa, and (in part) the long head of biceps tendon, all vulnerable to compression/impingement in this region."},{"id": 3353,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Subacromial impingement syndrome is generally understood to result from:","options": [{"key": "A","text": "Complete absence of any rotator cuff tissue"},{"key": "B","text": "Repeated compression/mechanical irritation of subacromial structures (e.g., supraspinatus tendon, bursa) between the humeral head and the coracoacromial arch, often related to reduced subacromial space or altered scapulohumeral mechanics"},{"key": "C","text": "Only occurring in the lower extremity"},{"key": "D","text": "Excessive subacromial space with no compression of structures"}],"correct": "B","explanation": "Impingement syndrome results from repetitive mechanical compression of subacromial soft tissues against the coracoacromial arch, often related to factors reducing available subacromial space or disrupting normal scapulohumeral rhythm."},{"id": 3354,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which factor is commonly implicated in contributing to reduced subacromial space and increased impingement risk?","options": [{"key": "A","text": "Complete absence of any anatomical variation"},{"key": "B","text": "Excessive lower trapezius and serratus anterior strength"},{"key": "C","text": "Poor scapular upward rotation/posterior tilt control, rotator cuff weakness, or a hooked/curved acromion morphology"},{"key": "D","text": "Excessive glenohumeral internal rotation range of motion only"}],"correct": "C","explanation": "Factors such as inadequate scapular upward rotation and posterior tilt, rotator cuff weakness (altering humeral head centering), and certain acromion morphologies (e.g., hooked/curved type) have all been implicated in reducing subacromial space and increasing impingement risk."},{"id": 3355,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The long head of the biceps brachii tendon, which passes through the bicipital (intertubercular) groove and glenohumeral joint, contributes to shoulder function primarily by:","options": [{"key": "A","text": "Only functioning as a passive structure with no dynamic contribution"},{"key": "B","text": "Producing the majority of shoulder abduction torque"},{"key": "C","text": "Providing some dynamic stabilization to the glenohumeral joint, particularly resisting superior humeral head translation, in addition to its role in elbow flexion/forearm supination"},{"key": "D","text": "Having no functional role at the shoulder"}],"correct": "C","explanation": "Beyond its primary elbow/forearm actions, the long head of biceps is thought to contribute to dynamic glenohumeral stability, particularly helping resist excessive superior humeral head translation."},{"id": 3356,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The coracoacromial ligament, connecting the coracoid process to the acromion, functions primarily to:","options": [{"key": "A","text": "Form part of the coracoacromial arch, serving as a passive restraint that helps prevent superior humeral head migration beyond a certain point, while also being a site relevant to impingement pathology"},{"key": "B","text": "Serve as the primary shoulder flexor"},{"key": "C","text": "Provide active dynamic stabilization to the shoulder"},{"key": "D","text": "Attach directly to the humeral head"}],"correct": "A","explanation": "This ligament forms part of the coracoacromial arch, providing a passive restraint against excessive superior humeral head migration, while also representing an anatomical structure clinically relevant in impingement syndromes."},{"id": 3357,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "The glenohumeral joint capsule and associated ligaments (superior, middle, inferior glenohumeral ligaments) provide passive stability primarily in which positions?","options": [{"key": "A","text": "Only during pure internal rotation"},{"key": "B","text": "No positional variation in restraint function exists"},{"key": "C","text": "Only in the fully adducted, neutral rotation position"},{"key": "D","text": "Different portions of the capsuloligamentous complex provide primary restraint at different arm positions, with the inferior glenohumeral ligament complex being particularly important in abduction with external rotation"}],"correct": "D","explanation": "The capsuloligamentous structures of the glenohumeral joint have position-dependent restraint functions, with different ligamentous bands (superior, middle, inferior glenohumeral ligaments) providing primary stability at different arm positions—the inferior glenohumeral ligament complex is especially important in the abducted, externally rotated position (relevant to anterior instability)."},{"id": 3358,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Anterior shoulder dislocation, the most common direction of glenohumeral dislocation, typically occurs with the arm positioned in:","options": [{"key": "A","text": "Abduction and external rotation, which places maximal stress on the anterior capsuloligamentous structures (particularly the inferior glenohumeral ligament)"},{"key": "B","text": "Neutral position with no external force"},{"key": "C","text": "Full flexion with pronation"},{"key": "D","text": "Adduction and internal rotation"}],"correct": "A","explanation": "The classic mechanism for anterior shoulder dislocation involves forced abduction and external rotation, which places maximal stress on the anteroinferior capsuloligamentous structures, predisposing to anterior humeral head displacement."},{"id": 3359,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A Bankart lesion refers to:","options": [{"key": "A","text": "A fracture of the coracoid process"},{"key": "B","text": "Detachment/avulsion of the anteroinferior glenoid labrum (often with the associated capsuloligamentous complex) from the glenoid rim, commonly associated with anterior shoulder dislocation"},{"key": "C","text": "A fracture of the greater tuberosity"},{"key": "D","text": "A tear of the supraspinatus tendon"}],"correct": "B","explanation": "A Bankart lesion involves detachment of the anteroinferior labrum (and often the attached inferior glenohumeral ligament complex) from the glenoid rim, a common structural consequence of anterior shoulder dislocation."},{"id": 3360,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A Hill-Sachs lesion refers to:","options": [{"key": "A","text": "A fracture of the clavicle"},{"key": "B","text": "A labral tear only"},{"key": "C","text": "A tear of the biceps tendon"},{"key": "D","text": "A compression fracture/defect on the posterolateral aspect of the humeral head, caused by impaction against the anterior glenoid rim during an anterior dislocation event"}],"correct": "D","explanation": "A Hill-Sachs lesion is a characteristic compression injury to the posterolateral humeral head, resulting from forceful impaction against the anterior glenoid rim during anterior dislocation."},{"id": 3361,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Multidirectional instability of the shoulder refers to a condition in which:","options": [{"key": "A","text": "Excessive glenohumeral translation/instability occurs in more than one direction (e.g., anterior, posterior, and/or inferior), often related to generalized capsular laxity"},{"key": "B","text": "The glenohumeral joint is excessively unstable in only one specific direction"},{"key": "C","text": "The joint is completely rigid with no translation possible"},{"key": "D","text": "Only the acromioclavicular joint is affected"}],"correct": "A","explanation": "Multidirectional instability describes excessive pathological translation of the humeral head in multiple directions, often due to underlying generalized capsuloligamentous laxity."},{"id": 3362,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The sulcus sign, a clinical test for inferior glenohumeral instability, is performed by:","options": [{"key": "A","text": "Testing resisted external rotation strength"},{"key": "B","text": "Applying an anterior force to the humeral head with the arm abducted"},{"key": "C","text": "Applying a downward (inferior) traction force to the arm with the patient relaxed, observing for a visible/palpable indentation (sulcus) below the acromion indicating excessive inferior humeral head translation"},{"key": "D","text": "Testing passive internal rotation range of motion only"}],"correct": "C","explanation": "The sulcus sign test involves applying inferior traction to the relaxed arm and observing for an abnormal gap/indentation beneath the acromion, indicating excessive inferior glenohumeral translation/laxity."},{"id": 3363,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During shoulder external rotation with the arm at the side (0 degrees abduction), the primary muscles responsible are the:","options": [{"key": "A","text": "Subscapularis and pectoralis major"},{"key": "B","text": "Infraspinatus and teres minor"},{"key": "C","text": "Supraspinatus and deltoid"},{"key": "D","text": "Latissimus dorsi and teres major"}],"correct": "B","explanation": "Infraspinatus and teres minor are the primary external rotators of the glenohumeral joint, particularly tested with the arm at the side."},{"id": 3364,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During shoulder internal rotation, the primary muscles responsible include:","options": [{"key": "A","text": "Middle deltoid exclusively"},{"key": "B","text": "Supraspinatus exclusively"},{"key": "C","text": "Infraspinatus and teres minor"},{"key": "D","text": "Subscapularis, pectoralis major, latissimus dorsi, and teres major"}],"correct": "D","explanation": "Internal rotation of the glenohumeral joint is produced primarily by subscapularis, along with contributions from pectoralis major, latissimus dorsi, and teres major."},{"id": 3365,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The supraspinatus muscle's primary action, in addition to its stabilizing role, is:","options": [{"key": "A","text": "Initiating and assisting shoulder abduction, particularly in the first 15-30 degrees, and providing compressive stabilization throughout the range"},{"key": "B","text": "Elbow flexion"},{"key": "C","text": "Shoulder extension"},{"key": "D","text": "Shoulder internal rotation exclusively"}],"correct": "A","explanation": "Supraspinatus is classically described as initiating shoulder abduction (particularly the first 15-30°) alongside the deltoid, while also providing important dynamic glenohumeral stabilization throughout the range."},{"id": 3366,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "The deltoid muscle, particularly its middle fibers, is the prime mover for which shoulder motion?","options": [{"key": "A","text": "Adduction"},{"key": "B","text": "Internal rotation exclusively"},{"key": "C","text": "Horizontal adduction exclusively"},{"key": "D","text": "Abduction, especially from approximately 15-90 degrees and beyond with rotator cuff assistance"}],"correct": "D","explanation": "The middle deltoid is the primary abductor of the glenohumeral joint through most of the abduction range, working synergistically with the rotator cuff for stabilization."},{"id": 3367,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which muscle is primarily responsible for scapular downward rotation and retraction, often working in opposition to serratus anterior/upper trapezius during arm lowering?","options": [{"key": "A","text": "Supraspinatus"},{"key": "B","text": "Rhomboids (major and minor), along with levator scapulae contributing to downward rotation"},{"key": "C","text": "Deltoid"},{"key": "D","text": "Serratus anterior"}],"correct": "B","explanation": "The rhomboids, together with levator scapulae, contribute to scapular downward rotation and retraction, functioning in coordinated opposition to the upward rotators during controlled arm lowering."},{"id": 3368,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'painful arc' phenomenon, in which shoulder pain is reported specifically within a mid-range of abduction (e.g., approximately 60-120 degrees) but not at the very beginning or end of range, is classically associated with:","options": [{"key": "A","text": "Complete rotator cuff tear with no remaining function"},{"key": "B","text": "Acromioclavicular joint dislocation exclusively"},{"key": "C","text": "Cervical radiculopathy exclusively"},{"key": "D","text": "Subacromial impingement of structures (e.g., supraspinatus tendon or bursa) as they pass beneath the coracoacromial arch during this specific portion of the range"}],"correct": "D","explanation": "The painful arc reflects the specific range during which subacromial structures are most compressed beneath the coracoacromial arch, classically implicating impingement-related pathology of the rotator cuff or subacromial bursa."},{"id": 3369,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "A painful arc localized to the very end range of full overhead elevation (rather than the mid-range) is more suggestive of:","options": [{"key": "A","text": "No clinical significance"},{"key": "B","text": "Subacromial impingement exclusively"},{"key": "C","text": "Rotator cuff tendinopathy exclusively"},{"key": "D","text": "Acromioclavicular joint pathology, since AC joint compression tends to occur at the extremes of elevation"}],"correct": "D","explanation": "Pain occurring specifically at the very top of the elevation range is more suggestive of acromioclavicular joint involvement, as this joint experiences increased compressive stress at the extremes of overhead motion."},{"id": 3370,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the biomechanical rationale for scapular stabilization exercises (e.g., targeting serratus anterior and lower trapezius) in patients with shoulder impingement syndrome?","options": [{"key": "A","text": "Scapular stabilization exercises have no relevance to impingement management"},{"key": "B","text": "Only glenohumeral joint mobility matters in impingement management"},{"key": "C","text": "Scapular exercises always worsen impingement symptoms"},{"key": "D","text": "Improving scapular upward rotation, posterior tilt, and overall control can help optimize subacromial space and normalize scapulohumeral rhythm, potentially reducing mechanical impingement of subacromial structures"}],"correct": "D","explanation": "Since inadequate scapular upward rotation/posterior tilt control can contribute to reduced subacromial space, targeted scapular stabilization exercises aim to restore optimal scapulohumeral mechanics and reduce impingement risk."},{"id": 3371,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Rotator cuff tears most commonly affect which tendon first, given its relatively higher biomechanical stress and vascular watershed zone?","options": [{"key": "A","text": "Infraspinatus exclusively, with no supraspinatus involvement"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Supraspinatus is the most commonly torn rotator cuff tendon, related to both its mechanically vulnerable position beneath the acromion and a relatively hypovascular ('critical zone') region near its insertion."},{"id": 3372,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'critical zone' of the supraspinatus tendon refers to:","options": [{"key": "A","text": "An area unrelated to any clinical pathology"},{"key": "B","text": "A relatively hypovascular area near the tendon's insertion on the greater tuberosity, thought to contribute to the tendon's vulnerability to degeneration and tearing"},{"key": "C","text": "A region with excellent blood supply"},{"key": "D","text": "A region found only in the biceps tendon"}],"correct": "B","explanation": "The critical zone describes a relatively poorly vascularized segment of the supraspinatus tendon near its insertion, considered a contributing factor to this tendon's susceptibility to degenerative changes and tears."},{"id": 3373,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which of the following positions places the greatest tensile stress on the anterior capsuloligamentous structures of the glenohumeral joint, relevant to anterior instability assessment (e.g., apprehension test)?","options": [{"key": "A","text": "Adduction and internal rotation"},{"key": "B","text": "Full flexion with pronation"},{"key": "C","text": "Abduction (approximately 90 degrees) combined with external rotation"},{"key": "D","text": "Neutral position at the side"}],"correct": "C","explanation": "The combination of abduction and external rotation stresses the anterior capsuloligamentous complex maximally, which is the basis for the classic apprehension test used to assess anterior glenohumeral instability."},{"id": 3374,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'relocation test', often performed alongside the apprehension test, helps confirm anterior glenohumeral instability by:","options": [{"key": "A","text": "Assessing only passive range of motion with no force application"},{"key": "B","text": "Applying a posteriorly directed force to the humeral head during the apprehension position, and noting relief of apprehension/symptoms, supporting an anterior instability diagnosis"},{"key": "C","text": "Applying an anteriorly directed force and observing for increased apprehension/pain"},{"key": "D","text": "Testing purely for posterior instability with no relevance to anterior findings"}],"correct": "B","explanation": "The relocation test involves applying posterior pressure to the humeral head during the apprehension position; relief of apprehension/symptoms with this maneuver supports a diagnosis of anterior glenohumeral instability."},{"id": 3375,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Adhesive capsulitis (frozen shoulder) biomechanically results in which characteristic pattern of motion restriction?","options": [{"key": "A","text": "A capsular pattern of restriction, with external rotation most limited, followed by abduction, and internal rotation relatively least limited"},{"key": "B","text": "Complete absence of any restriction, with normal range in all planes"},{"key": "C","text": "Isolated restriction of internal rotation only, with normal external rotation and abduction"},{"key": "D","text": "Restriction limited exclusively to the scapulothoracic joint"}],"correct": "A","explanation": "Adhesive capsulitis classically follows the shoulder's capsular pattern, with external rotation most severely restricted, followed by abduction, and internal rotation comparatively least affected."},{"id": 3376,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "In adhesive capsulitis, the underlying pathophysiology involves:","options": [{"key": "A","text": "Purely a nerve conduction abnormality with no capsular involvement"},{"key": "B","text": "Only rotator cuff tendon tearing with normal capsule"},{"key": "C","text": "Progressive fibrosis and contracture of the glenohumeral joint capsule, reducing its normal volume and compliance, thereby restricting motion in multiple planes"},{"key": "D","text": "Complete absence of any capsular changes"}],"correct": "C","explanation": "Adhesive capsulitis involves progressive capsular fibrosis and contracture, reducing capsular volume and compliance, which mechanically restricts glenohumeral range of motion in a capsular pattern."},{"id": 3377,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains the biomechanical rationale for restoring adequate posterior capsule flexibility in overhead athletes (e.g., baseball pitchers) with glenohumeral internal rotation deficit (GIRD)?","options": [{"key": "A","text": "GIRD is unrelated to any injury risk in overhead athletes"},{"key": "B","text": "Posterior capsule tightness always improves throwing performance with no downside"},{"key": "C","text": "Posterior capsule tightness can alter the normal glenohumeral rotational arc and humeral head position, potentially increasing stress on anterior structures and altering scapular mechanics during the throwing motion"},{"key": "D","text": "Posterior capsule tightness has no relevance to overhead throwing mechanics"}],"correct": "C","explanation": "Posterior capsular tightness contributing to GIRD can shift the humeral head position and rotational arc, potentially increasing stress on anterior stabilizing structures and altering scapular mechanics, which has been associated with increased injury risk in overhead throwing athletes."},{"id": 3378,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'scapular plane' (scaption), approximately 30-45 degrees anterior to the frontal plane, is often preferred over pure frontal-plane abduction during shoulder exercise/rehabilitation because it:","options": [{"key": "A","text": "Better aligns with the natural resting orientation of the glenoid fossa, potentially optimizing the length-tension relationship of the rotator cuff and deltoid while reducing impingement risk"},{"key": "B","text": "Increases subacromial impingement risk compared to pure abduction"},{"key": "C","text": "Has no biomechanical advantage over pure frontal plane abduction"},{"key": "D","text": "Only applies to the lower extremity"}],"correct": "A","explanation": "Movement in the scapular plane aligns more closely with the natural anteverted orientation of the glenoid, which is thought to optimize rotator cuff and deltoid length-tension relationships and may reduce impingement risk compared to pure frontal-plane abduction."},{"id": 3379,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following muscles is primarily responsible for scapular elevation?","options": [{"key": "A","text": "Upper trapezius and levator scapulae"},{"key": "B","text": "Pectoralis minor exclusively"},{"key": "C","text": "Serratus anterior and lower trapezius"},{"key": "D","text": "Rhomboids exclusively"}],"correct": "A","explanation": "Upper trapezius and levator scapulae are the primary muscles responsible for elevating the scapula."},{"id": 3380,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following muscles is primarily responsible for scapular depression?","options": [{"key": "A","text": "Rhomboids exclusively"},{"key": "B","text": "Lower trapezius and serratus anterior (lower fibers), along with pectoralis minor"},{"key": "C","text": "Upper trapezius and levator scapulae"},{"key": "D","text": "Supraspinatus exclusively"}],"correct": "B","explanation": "Scapular depression is produced primarily by lower trapezius, the lower fibers of serratus anterior, and pectoralis minor."},{"id": 3381,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Pectoralis minor tightness is commonly associated with which scapular positional fault?","options": [{"key": "A","text": "Excessive scapular upward rotation and posterior tilt"},{"key": "B","text": "No effect on scapular positioning"},{"key": "C","text": "Excessive scapular retraction only"},{"key": "D","text": "Increased scapular anterior tilt and downward rotation/protraction, potentially contributing to reduced subacromial space"}],"correct": "D","explanation": "Tight pectoralis minor can pull the scapula into increased anterior tilt and downward rotation/protraction, a positional fault that may contribute to reduced subacromial space and altered shoulder mechanics."},{"id": 3382,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "During the throwing motion (e.g., baseball pitch), the glenohumeral joint experiences its highest angular velocities during which phase?","options": [{"key": "A","text": "Wind-up phase"},{"key": "B","text": "Follow-through phase exclusively"},{"key": "C","text": "Acceleration phase, immediately preceding ball release, during which internal rotation velocity can reach extremely high values"},{"key": "D","text": "Cocking phase"}],"correct": "C","explanation": "The acceleration phase of throwing involves extremely rapid glenohumeral internal rotation, among the highest angular velocities recorded in human movement, occurring just before ball release."},{"id": 3383,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "During the deceleration/follow-through phase of throwing, which structures experience particularly high eccentric loading demands to control the rapidly decelerating arm?","options": [{"key": "A","text": "Internal rotators and anterior structures"},{"key": "B","text": "Only the wrist flexors are loaded during this phase"},{"key": "C","text": "Posterior rotator cuff muscles (infraspinatus, teres minor) and posterior capsule, working eccentrically to decelerate the arm"},{"key": "D","text": "No significant loading occurs during this phase"}],"correct": "C","explanation": "The posterior shoulder structures (posterior rotator cuff and capsule) must generate substantial eccentric force during the deceleration phase to control and slow the rapidly internally rotating, forward-moving arm after ball release."},{"id": 3384,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the concept of 'scapular dyskinesis'?","options": [{"key": "A","text": "A condition that always requires surgical correction"},{"key": "B","text": "A condition affecting only the wrist joint"},{"key": "C","text": "A term with no clinical relevance to shoulder function"},{"key": "D","text": "An observable alteration in the normal position or motion pattern of the scapula during shoulder movement, which may be associated with various shoulder pathologies though its precise clinical significance and causality remain debated"}],"correct": "D","explanation": "Scapular dyskinesis describes visible alterations in normal scapular positioning or motion patterns during arm movement, often observed alongside various shoulder conditions, although the precise cause-and-effect relationship with pathology remains an active area of clinical research and debate."},{"id": 3385,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why full passive glenohumeral internal rotation is often reduced when tested with the shoulder in 90 degrees of abduction (compared to at the side) in individuals with posterior capsule tightness?","options": [{"key": "A","text": "At 90 degrees abduction, the posterior capsule is placed under greater relative tension during internal rotation, making any existing tightness more apparent/limiting in this position"},{"key": "B","text": "Testing position has no effect on the range of motion measured"},{"key": "C","text": "Internal rotation range is always greater at 90 degrees abduction than at the side"},{"key": "D","text": "Posterior capsule tightness has no effect at 90 degrees abduction"}],"correct": "A","explanation": "Testing internal rotation in 90° of abduction places the posterior capsule under increased relative tension, making restrictions due to posterior capsule tightness (as seen in conditions like GIRD) more apparent than when testing at the side."},{"id": 3386,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'empty can test' (Jobe's test), used clinically to assess supraspinatus function/pathology, is performed with the shoulder positioned in which combination?","options": [{"key": "A","text": "Approximately 90 degrees of scapular plane abduction with the arm internally rotated (thumb pointing down)"},{"key": "B","text": "Full adduction and external rotation"},{"key": "C","text": "Full flexion with forearm supination"},{"key": "D","text": "Neutral position with elbow flexed"}],"correct": "A","explanation": "The empty can test positions the shoulder in scaption with internal rotation (thumb down), a position that biomechanically isolates and stresses the supraspinatus, testing for weakness or pain suggestive of supraspinatus pathology."},{"id": 3387,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why resisted shoulder abduction testing in the empty can position may be more provocative for supraspinatus impingement than testing in external rotation (full can position)?","options": [{"key": "A","text": "External rotation always increases impingement risk more than internal rotation"},{"key": "B","text": "Internal rotation of the humerus tends to rotate the greater tuberosity anteriorly, potentially narrowing the subacromial space and increasing mechanical compression of the supraspinatus tendon during this test position"},{"key": "C","text": "Testing position has no relevance to subacromial space"},{"key": "D","text": "Internal rotation increases subacromial space significantly"}],"correct": "B","explanation": "Internally rotating the humerus during the empty can test position rotates the greater tuberosity (and attached supraspinatus) anteriorly beneath the acromion, which can narrow the subacromial space and increase compressive stress on the tendon during testing."},{"id": 3388,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which of the following best describes the primary biomechanical function of the axillary pouch (inferior recess) of the glenohumeral joint capsule?","options": [{"key": "A","text": "It restricts all overhead motion"},{"key": "B","text": "It solely contains blood vessels with no mechanical role"},{"key": "C","text": "It provides no functional role"},{"key": "D","text": "It allows the capsule to unfold and accommodate the increased joint volume/positional demands as the arm is elevated, preventing premature capsular restriction of motion"}],"correct": "D","explanation": "The axillary pouch, a redundant fold of capsule in the inferior/adducted position, unfolds as the arm elevates, accommodating the necessary capsular length changes and preventing premature restriction of overhead motion."},{"id": 3389,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A patient presenting with weakness specifically on resisted shoulder external rotation with the elbow at the side, combined with a positive lag sign on external rotation testing, is most suggestive of pathology involving:","options": [{"key": "A","text": "Subscapularis exclusively"},{"key": "B","text": "Only the long head of biceps tendon"},{"key": "C","text": "Infraspinatus and/or teres minor"},{"key": "D","text": "Pectoralis major exclusively"}],"correct": "C","explanation": "Weakness on resisted external rotation combined with an external rotation lag sign (inability to actively maintain passively achieved external rotation) points toward infraspinatus and/or teres minor dysfunction or tearing."},{"id": 3390,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'lift-off test', used clinically to assess subscapularis integrity, requires the patient to:","options": [{"key": "A","text": "Flex the elbow against resistance"},{"key": "B","text": "Internally rotate the arm behind the back and lift the hand away from the lower back, testing the subscapularis's ability to actively maintain/produce this internally rotated position"},{"key": "C","text": "Abduct the arm to 90 degrees against resistance"},{"key": "D","text": "Externally rotate the arm against resistance at the side"}],"correct": "B","explanation": "The lift-off test assesses subscapularis function by having the patient actively lift the hand away from the lower back from a position of internal rotation behind the back, a movement primarily dependent on adequate subscapularis strength."},{"id": 3391,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following best describes the general biomechanical relationship between glenohumeral joint mobility and shoulder complex stability?","options": [{"key": "A","text": "Greater mobility always corresponds to greater stability, with no trade-off"},{"key": "B","text": "Stability and mobility are entirely unrelated concepts at the shoulder"},{"key": "C","text": "Mobility has no bearing on injury risk at the shoulder"},{"key": "D","text": "There is generally an inherent trade-off, whereby the glenohumeral joint's substantial mobility comes at some cost to its inherent (bony) stability, requiring significant compensatory soft tissue support for adequate functional stability"}],"correct": "D","explanation": "The shoulder exemplifies the classic mobility-stability trade-off in joint biomechanics: its extensive range of motion is afforded by relatively little inherent bony constraint, necessitating substantial soft tissue (capsuloligamentous and muscular) contributions to maintain adequate functional stability."},{"id": 3392,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'drop arm test' is used clinically to assess:","options": [{"key": "A","text": "Bicipital tendon integrity"},{"key": "B","text": "Acromioclavicular joint stability"},{"key": "C","text": "Gross rotator cuff tear (often supraspinatus), where the patient is unable to smoothly lower the arm from an abducted position, resulting in a sudden 'drop'"},{"key": "D","text": "Cervical nerve root function"}],"correct": "C","explanation": "In the drop arm test, inability to smoothly control lowering of the arm from abduction (resulting in a sudden drop) suggests a significant rotator cuff tear, most often involving the supraspinatus."},{"id": 3393,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Neer's impingement sign is elicited by:","options": [{"key": "A","text": "Resisted shoulder abduction only"},{"key": "B","text": "Passive extension of the shoulder"},{"key": "C","text": "Resisted external rotation at the side"},{"key": "D","text": "Passive forward flexion of the internally rotated arm by the examiner, which compresses subacromial structures against the anteroinferior acromion"}],"correct": "D","explanation": "Neer's test involves passively flexing the internally rotated arm, mechanically compressing the greater tuberosity and attached soft tissues against the anteroinferior acromion, provoking impingement symptoms if present."},{"id": 3394,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Hawkins-Kennedy impingement test is performed by:","options": [{"key": "A","text": "Resisting shoulder abduction against gravity"},{"key": "B","text": "Passively flexing the shoulder to 90 degrees, then internally rotating the arm, which drives the greater tuberosity against the coracoacromial ligament"},{"key": "C","text": "Passively extending the shoulder fully"},{"key": "D","text": "Testing passive external rotation only"}],"correct": "B","explanation": "The Hawkins-Kennedy test positions the shoulder in 90° flexion followed by passive internal rotation, mechanically compressing subacromial structures against the coracoacromial ligament to reproduce impingement symptoms."},{"id": 3395,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which of the following best explains why the sternoclavicular joint, despite its small size, is able to withstand the substantial forces transmitted through the upper limb during activities like pushing or falling on an outstretched hand?","options": [{"key": "A","text": "It relies purely on muscular support with no ligamentous contribution"},{"key": "B","text": "It has no ligamentous support at all"},{"key": "C","text": "It is reinforced by strong surrounding ligaments (e.g., costoclavicular, interclavicular, and capsular ligaments) that provide considerable stability despite the joint's minimal bony congruity"},{"key": "D","text": "It is a completely rigid, immobile joint with no capacity for force transmission"}],"correct": "C","explanation": "Despite having relatively poor bony congruity, the SC joint is stabilized by robust ligamentous structures (costoclavicular, interclavicular, capsular), allowing it to withstand and transmit substantial forces from the upper limb to the axial skeleton."},{"id": 3396,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A fall onto an outstretched hand (FOOSH) can transmit force proximally through the upper limb; excessive force at the shoulder girdle in this mechanism is most classically associated with which type of injury?","options": [{"key": "A","text": "Isolated glenoid labrum tear only"},{"key": "B","text": "Clavicle fracture or acromioclavicular joint injury, due to force transmission through the relatively vulnerable clavicle/AC joint region"},{"key": "C","text": "No injury risk to the shoulder girdle from this mechanism"},{"key": "D","text": "Isolated rotator cuff tendinopathy only"}],"correct": "B","explanation": "Forces transmitted proximally through the upper limb during a FOOSH mechanism can concentrate stress at the clavicle or AC joint, common sites of fracture or ligamentous injury from this type of trauma."},{"id": 3397,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which grade of acromioclavicular joint injury (Rockwood classification) involves complete disruption of both the AC and coracoclavicular ligaments with significant superior displacement of the clavicle?","options": [{"key": "A","text": "Grade I (sprain with no ligament disruption)"},{"key": "B","text": "Grade III (complete disruption of both AC and coracoclavicular ligaments)"},{"key": "C","text": "There is no such classification system for AC joint injuries"},{"key": "D","text": "Grade II (AC ligament disruption with intact coracoclavicular ligament)"}],"correct": "B","explanation": "Grade III AC joint separations involve complete disruption of both the AC and coracoclavicular ligaments, resulting in noticeable superior displacement of the clavicle relative to the acromion."},{"id": 3398,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The coracoclavicular ligaments (conoid and trapezoid) primarily function to:","options": [{"key": "A","text": "Have no functional role in shoulder biomechanics"},{"key": "B","text": "Provide the majority of glenohumeral joint stability"},{"key": "C","text": "Stabilize the sternoclavicular joint exclusively"},{"key": "D","text": "Provide vertical stability to the acromioclavicular joint, resisting superior displacement of the clavicle relative to the scapula"}],"correct": "D","explanation": "The coracoclavicular ligaments provide crucial vertical (superior-inferior) stability at the AC joint, resisting excessive superior clavicular displacement relative to the scapula/acromion."},{"id": 3399,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which of the following best describes the biomechanical consequence of a complete AC joint separation (Grade III or higher) on scapulothoracic and glenohumeral mechanics?","options": [{"key": "A","text": "Loss of normal clavicular-scapular linkage can disrupt normal force transmission and scapular positioning during arm elevation, potentially altering overall shoulder complex mechanics"},{"key": "B","text": "No functional consequence occurs"},{"key": "C","text": "Glenohumeral motion increases to fully compensate with no deficit"},{"key": "D","text": "Scapular motion becomes completely unaffected"}],"correct": "A","explanation": "Disruption of the coracoclavicular ligaments in higher-grade AC separations compromises the normal mechanical linkage between clavicle and scapula, which can adversely affect force transmission and scapular positioning during arm movement."},{"id": 3400,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following muscles contributes to horizontal adduction of the shoulder, commonly tested/strengthened with exercises like the bench press or chest fly?","options": [{"key": "A","text": "Pectoralis major (particularly the sternal/clavicular fibers) and anterior deltoid"},{"key": "B","text": "Rhomboids"},{"key": "C","text": "Posterior deltoid"},{"key": "D","text": "Infraspinatus"}],"correct": "A","explanation": "Horizontal adduction of the shoulder is produced primarily by pectoralis major and the anterior deltoid fibers."},{"id": 3401,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following muscles contributes to horizontal abduction of the shoulder, commonly tested/strengthened with exercises like reverse flys?","options": [{"key": "A","text": "Posterior deltoid, along with infraspinatus and teres minor contribution"},{"key": "B","text": "Pectoralis major"},{"key": "C","text": "Biceps brachii"},{"key": "D","text": "Anterior deltoid"}],"correct": "A","explanation": "Horizontal abduction is produced primarily by the posterior deltoid, with assistance from infraspinatus and teres minor."},{"id": 3402,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The latissimus dorsi, in addition to its role in shoulder extension and internal rotation, is notably active during which type of functional activity requiring depression of the shoulder girdle?","options": [{"key": "A","text": "Isolated elbow flexion"},{"key": "B","text": "Overhead reaching only"},{"key": "C","text": "Cervical spine rotation"},{"key": "D","text": "Activities like pushing up from a chair or crutch-walking, where the arm helps support/elevate the trunk relative to a fixed hand position (closed-chain shoulder depression)"}],"correct": "D","explanation": "Latissimus dorsi is particularly active in closed-chain activities requiring the trunk to move relative to a fixed hand (e.g., pushing up from a chair, crutch ambulation), functioning to depress/stabilize the shoulder girdle and assist trunk elevation."},{"id": 3403,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes why patients using axillary crutches are cautioned against excessive pressure in the axilla during ambulation?","options": [{"key": "A","text": "Sustained compression in the axilla can potentially compress the radial nerve and axillary vessels passing through this region, risking neurovascular injury ('crutch palsy')"},{"key": "B","text": "Axillary pressure only affects the shoulder joint capsule"},{"key": "C","text": "Excessive axillary pressure improves circulation with no risk"},{"key": "D","text": "There is no risk associated with axillary pressure"}],"correct": "A","explanation": "Prolonged or excessive compressive force in the axillary region from crutch use can compress neurovascular structures (notably the radial nerve), risking a condition sometimes termed 'crutch palsy'—hence proper crutch fitting emphasizes weight-bearing through the hands, not the axilla."},{"id": 3404,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best summarizes the overall biomechanical importance of coordinated function among the four shoulder complex articulations (glenohumeral, acromioclavicular, sternoclavicular, scapulothoracic) for normal arm elevation?","options": [{"key": "A","text": "All four joints function completely independently with no interaction"},{"key": "B","text": "Full, pain-free, efficient overhead arm elevation depends on the coordinated, interdependent contribution and motion of all four articulations working together; dysfunction at any one can compromise overall shoulder complex mechanics"},{"key": "C","text": "The scapulothoracic joint has no relevance to arm elevation"},{"key": "D","text": "Only the glenohumeral joint's function matters; the others are biomechanically irrelevant"}],"correct": "B","explanation": "Achieving normal, efficient overhead arm motion requires coordinated contribution from all four shoulder complex articulations; impairment at any single articulation can disrupt the overall mechanics and efficiency of arm elevation."},{"id": 3405,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "The elbow joint complex consists of which three articulations?","options": [{"key": "A","text": "Carpometacarpal, metacarpophalangeal, and interphalangeal"},{"key": "B","text": "Glenohumeral, acromioclavicular, and sternoclavicular"},{"key": "C","text": "Humeroulnar, humeroradial, and proximal radioulnar joints"},{"key": "D","text": "Radiocarpal, midcarpal, and distal radioulnar"}],"correct": "C","explanation": "The elbow complex comprises the humeroulnar, humeroradial, and proximal radioulnar joints, all enclosed within a common joint capsule."},{"id": 3406,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "The humeroulnar joint is classified structurally as a:","options": [{"key": "A","text": "Multiaxial joint with three degrees of freedom"},{"key": "B","text": "Ball-and-socket joint"},{"key": "C","text": "Uniaxial hinge joint, primarily allowing flexion-extension"},{"key": "D","text": "Saddle joint"}],"correct": "C","explanation": "The humeroulnar joint is a hinge (ginglymus) joint, permitting motion primarily in one plane—flexion and extension."},{"id": 3407,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The humeroradial joint is classified structurally as a:","options": [{"key": "A","text": "Hinge joint only"},{"key": "B","text": "A joint that functions in conjunction with both flexion-extension (with the humeroulnar joint) and pronation-supination (with the radioulnar joints), given the radial head's rounded shape"},{"key": "C","text": "A pure ball-and-socket joint with unrestricted three-dimensional motion"},{"key": "D","text": "A saddle joint"}],"correct": "B","explanation": "The rounded radial head articulating with the capitulum allows the humeroradial joint to participate in both elbow flexion-extension and forearm pronation-supination."},{"id": 3408,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The proximal radioulnar joint is classified structurally as a:","options": [{"key": "A","text": "Hinge joint"},{"key": "B","text": "Plane joint"},{"key": "C","text": "Ball-and-socket joint"},{"key": "D","text": "Pivot (trochoid) joint, allowing the radial head to rotate within the radial notch of the ulna, primarily responsible for pronation-supination"}],"correct": "D","explanation": "The proximal radioulnar joint is a pivot joint where the radial head rotates within the annular ligament and the ulna's radial notch, enabling forearm pronation-supination."},{"id": 3409,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The normal carrying angle of the elbow (in full extension, forearm supinated) is typically described as an angle of:","options": [{"key": "A","text": "0 degrees (perfectly straight)"},{"key": "B","text": "Approximately 5-15 degrees of valgus (cubitus valgus), generally greater in females than males"},{"key": "C","text": "45 degrees of valgus"},{"key": "D","text": "20 degrees of varus"}],"correct": "B","explanation": "The normal elbow carrying angle is approximately 5-15° of valgus, allowing the forearm to clear the hips during arm swing, and is typically slightly greater in females than males."},{"id": 3410,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "An increased carrying angle beyond normal limits is termed:","options": [{"key": "A","text": "Cubitus rectus"},{"key": "B","text": "Cubitus varus"},{"key": "C","text": "Cubitus valgus"},{"key": "D","text": "Genu valgum"}],"correct": "C","explanation": "An exaggerated valgus carrying angle at the elbow is termed cubitus valgus."},{"id": 3411,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A decreased or reversed carrying angle (angulation toward varus) is termed:","options": [{"key": "A","text": "Cubitus varus (sometimes described as a 'gunstock deformity' when severe, often post-traumatic)"},{"key": "B","text": "Cubitus valgus"},{"key": "C","text": "Cubitus rectus"},{"key": "D","text": "Genu varum"}],"correct": "A","explanation": "A reduced or reversed (varus) carrying angle is termed cubitus varus, classically associated with malunion following supracondylar humeral fractures."},{"id": 3412,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal elbow flexion range of motion is approximately:","options": [{"key": "A","text": "180 degrees"},{"key": "B","text": "140-150 degrees"},{"key": "C","text": "90 degrees"},{"key": "D","text": "30 degrees"}],"correct": "B","explanation": "Normal elbow flexion range is typically cited as approximately 140-150 degrees."},{"id": 3413,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which structure primarily limits full elbow extension in the normal joint, providing a characteristic 'hard' end feel?","options": [{"key": "A","text": "Bony contact of the olecranon process within the olecranon fossa"},{"key": "B","text": "Anterior capsule tension only"},{"key": "C","text": "Medial collateral ligament exclusively"},{"key": "D","text": "Biceps brachii muscle bulk"}],"correct": "A","explanation": "Full elbow extension is normally limited by bony approximation of the olecranon process into the olecranon fossa of the humerus, producing a classic hard end feel."},{"id": 3414,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which structure primarily limits full elbow flexion in the normal joint, producing a characteristic 'soft' end feel?","options": [{"key": "A","text": "The lateral collateral ligament"},{"key": "B","text": "The annular ligament"},{"key": "C","text": "Soft tissue approximation of the anterior forearm/biceps against the anterior arm musculature"},{"key": "D","text": "Bony contact between the coronoid process and coronoid fossa alone"}],"correct": "C","explanation": "Full elbow flexion is normally limited primarily by soft tissue bulk approximation of the forearm against the arm, producing a soft end feel (with some contribution from coronoid process/fossa contact)."},{"id": 3415,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The elbow's medial (ulnar) collateral ligament primarily resists which type of stress?","options": [{"key": "A","text": "Varus stress"},{"key": "B","text": "Valgus stress, particularly important during activities like throwing that place repetitive valgus load on the medial elbow"},{"key": "C","text": "Compressive load only"},{"key": "D","text": "Rotational stress exclusively"}],"correct": "B","explanation": "The ulnar (medial) collateral ligament is the primary passive restraint against valgus stress at the elbow, and is of particular clinical importance in throwing athletes subjected to repetitive valgus loading."},{"id": 3416,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The elbow's lateral (radial) collateral ligament complex primarily resists which type of stress?","options": [{"key": "A","text": "Valgus stress"},{"key": "B","text": "Only compressive loading"},{"key": "C","text": "Varus stress and, along with other lateral structures, posterolateral rotatory instability"},{"key": "D","text": "Only pronation-supination motion"}],"correct": "C","explanation": "The lateral collateral ligament complex resists varus stress and contributes to preventing posterolateral rotatory instability of the elbow."},{"id": 3417,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Repetitive valgus stress at the elbow, as seen in overhead throwing athletes, is particularly associated with injury to which structure, sometimes requiring surgical reconstruction (e.g., 'Tommy John surgery')?","options": [{"key": "A","text": "Interosseous membrane"},{"key": "B","text": "Lateral collateral ligament"},{"key": "C","text": "Ulnar (medial) collateral ligament"},{"key": "D","text": "Annular ligament"}],"correct": "C","explanation": "Chronic repetitive valgus stress during throwing is classically associated with ulnar collateral ligament injury, sometimes necessitating surgical reconstruction."},{"id": 3418,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Lateral epicondylalgia ('tennis elbow') typically involves pathology of which tendon origin?","options": [{"key": "A","text": "Triceps tendon insertion"},{"key": "B","text": "Common flexor tendon origin at the medial epicondyle"},{"key": "C","text": "Biceps tendon insertion"},{"key": "D","text": "Common extensor tendon origin at the lateral epicondyle, particularly involving extensor carpi radialis brevis"}],"correct": "D","explanation": "Lateral epicondylalgia classically involves degenerative changes at the common extensor tendon origin, most notably extensor carpi radialis brevis, at the lateral epicondyle."},{"id": 3419,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Medial epicondylalgia ('golfer's elbow') typically involves pathology of which tendon origin?","options": [{"key": "A","text": "Common extensor tendon origin"},{"key": "B","text": "Common flexor-pronator tendon origin at the medial epicondyle"},{"key": "C","text": "Brachioradialis origin"},{"key": "D","text": "Triceps tendon insertion"}],"correct": "B","explanation": "Medial epicondylalgia involves degenerative changes at the common flexor-pronator tendon origin at the medial epicondyle."},{"id": 3420,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why lateral epicondylalgia is commonly aggravated by activities involving repetitive wrist extension or gripping (e.g., using a screwdriver)?","options": [{"key": "A","text": "Repetitive wrist extensor muscle contraction (particularly ECRB) generates tensile load at its common origin near the lateral epicondyle, which can contribute to cumulative microtrauma and degenerative tendon changes"},{"key": "B","text": "Gripping activities primarily stress the flexor tendon origin, not the extensor origin"},{"key": "C","text": "These activities have no relationship to the extensor tendon origin"},{"key": "D","text": "Wrist extension has no biomechanical link to elbow pathology"}],"correct": "A","explanation": "Repetitive loading of the wrist extensors (particularly ECRB) during gripping/wrist extension activities generates tensile stress at their common origin, contributing over time to the degenerative changes characteristic of lateral epicondylalgia."},{"id": 3421,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Forearm pronation and supination occur through combined motion at which joints?","options": [{"key": "A","text": "The proximal and distal radioulnar joints, with the radius rotating around the relatively fixed ulna"},{"key": "B","text": "Only the humeroulnar joint"},{"key": "C","text": "Only the humeroradial joint in isolation"},{"key": "D","text": "Only the wrist joint"}],"correct": "A","explanation": "Pronation-supination results from coordinated rotation at both the proximal and distal radioulnar joints, with the radius rotating around the ulna while the ulna remains relatively stationary."},{"id": 3422,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "During forearm pronation, the radius:","options": [{"key": "A","text": "Both radius and ulna rotate equally in the same direction"},{"key": "B","text": "Neither bone moves during pronation"},{"key": "C","text": "Rotates around the relatively fixed ulna, crossing over it distally"},{"key": "D","text": "Remains completely stationary while the ulna rotates"}],"correct": "C","explanation": "During pronation, the radius rotates around the relatively stationary ulna, with its distal end crossing over the ulna, bringing the palm to face posteriorly (in anatomical reference)."},{"id": 3423,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The normal combined range of forearm pronation-supination (each direction from neutral) is approximately:","options": [{"key": "A","text": "10-20 degrees each direction"},{"key": "B","text": "150 degrees each direction"},{"key": "C","text": "80-90 degrees each direction"},{"key": "D","text": "5 degrees each direction"}],"correct": "C","explanation": "Normal forearm rotation is approximately 80-90 degrees each of pronation and supination from the neutral (thumb-up) position."},{"id": 3424,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The interosseous membrane connecting the radius and ulna functions biomechanically to:","options": [{"key": "A","text": "Provide the primary means of elbow flexion"},{"key": "B","text": "Transmit load between the radius and ulna (particularly from radius to ulna during axial loading, e.g., a fall on an outstretched hand) and provide additional forearm stability"},{"key": "C","text": "Only function during pronation, not during axial loading"},{"key": "D","text": "Serve no functional role in force transmission"}],"correct": "B","explanation": "The interosseous membrane's oblique fiber orientation allows it to transmit compressive load from the radius to the ulna (important during axial loading, e.g., FOOSH) while also contributing to overall forearm stability."},{"id": 3425,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which forearm muscle is the primary agonist for supination when the elbow is extended?","options": [{"key": "A","text": "Flexor carpi radialis"},{"key": "B","text": "Biceps brachii and supinator, with biceps particularly dominant when the elbow is flexed and resistance is applied"},{"key": "C","text": "Pronator teres"},{"key": "D","text": "Pronator quadratus"}],"correct": "B","explanation": "Supinator and biceps brachii are the primary supinators, with biceps contributing especially strong torque when the elbow is flexed (e.g., turning a screwdriver with the elbow bent)."},{"id": 3426,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which forearm muscles are the primary agonists for pronation?","options": [{"key": "A","text": "Pronator teres and pronator quadratus"},{"key": "B","text": "Brachioradialis exclusively"},{"key": "C","text": "Supinator and biceps brachii"},{"key": "D","text": "Triceps brachii and anconeus"}],"correct": "A","explanation": "Pronator teres and pronator quadratus are the primary muscles responsible for forearm pronation."},{"id": 3427,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The wrist (radiocarpal) joint is classified structurally as a:","options": [{"key": "A","text": "Hinge joint with one degree of freedom"},{"key": "B","text": "Condyloid (ellipsoid) joint, allowing flexion-extension and radial-ulnar deviation (biaxial motion)"},{"key": "C","text": "Saddle joint"},{"key": "D","text": "Pivot joint"}],"correct": "B","explanation": "The radiocarpal joint is a condyloid/ellipsoid joint permitting biaxial motion: flexion-extension and radial-ulnar deviation."},{"id": 3428,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which carpal bones typically articulate with the distal radius at the radiocarpal joint?","options": [{"key": "A","text": "Trapezium and trapezoid"},{"key": "B","text": "Pisiform and hamate"},{"key": "C","text": "Scaphoid and lunate (with the triquetrum articulating mainly with the articular disc rather than the radius directly)"},{"key": "D","text": "Capitate and hamate"}],"correct": "C","explanation": "The proximal carpal row's scaphoid and lunate primarily articulate with the distal radius, while the triquetrum typically articulates with the triangular fibrocartilage complex rather than the radius directly."},{"id": 3429,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal wrist flexion range of motion is approximately:","options": [{"key": "A","text": "10-20 degrees"},{"key": "B","text": "5 degrees"},{"key": "C","text": "150 degrees"},{"key": "D","text": "70-90 degrees"}],"correct": "D","explanation": "Normal wrist flexion is typically cited as approximately 70-90 degrees."},{"id": 3430,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal wrist extension range of motion is approximately:","options": [{"key": "A","text": "150 degrees"},{"key": "B","text": "70-90 degrees"},{"key": "C","text": "0 degrees"},{"key": "D","text": "10 degrees"}],"correct": "B","explanation": "Normal wrist extension is typically cited as approximately 70-90 degrees, similar in magnitude to flexion."},{"id": 3431,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal wrist radial deviation range of motion is approximately:","options": [{"key": "A","text": "90 degrees"},{"key": "B","text": "0 degrees"},{"key": "C","text": "15-20 degrees"},{"key": "D","text": "70 degrees"}],"correct": "C","explanation": "Normal radial deviation is typically cited as approximately 15-20 degrees, considerably less than ulnar deviation."},{"id": 3432,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal wrist ulnar deviation range of motion is approximately:","options": [{"key": "A","text": "5 degrees"},{"key": "B","text": "90 degrees"},{"key": "C","text": "0 degrees"},{"key": "D","text": "30-35 degrees, generally greater than radial deviation"}],"correct": "D","explanation": "Normal ulnar deviation is typically cited as approximately 30-35 degrees, greater than the available radial deviation range."},{"id": 3433,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The 'dart-throwing motion' of the wrist, a functional movement pattern combining extension with radial deviation transitioning to flexion with ulnar deviation, is notable because:","options": [{"key": "A","text": "It occurs purely at the radiocarpal joint with no midcarpal contribution"},{"key": "B","text": "It has no functional relevance to daily activities"},{"key": "C","text": "It only occurs in pathological wrist conditions"},{"key": "D","text": "It occurs largely through the midcarpal joint, with relatively less stress on the radiocarpal joint, making it a functionally important motion plane in certain wrist rehabilitation protocols (e.g., after ligament injury)"}],"correct": "D","explanation": "The dart-throwing motion occurs predominantly through the midcarpal joint, sparing relative stress on the radiocarpal joint, making it functionally important and sometimes emphasized early in certain wrist rehabilitation protocols."},{"id": 3434,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A fall onto an outstretched hand (FOOSH) commonly results in which classic wrist fracture, involving dorsal displacement of the distal radius fragment?","options": [{"key": "A","text": "Smith's fracture"},{"key": "B","text": "Colles' fracture"},{"key": "C","text": "Bennett's fracture"},{"key": "D","text": "Boxer's fracture"}],"correct": "B","explanation": "A Colles' fracture, the classic FOOSH injury, involves a distal radius fracture with dorsal (posterior) displacement/angulation of the distal fragment."},{"id": 3435,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A Smith's fracture, in contrast to a Colles' fracture, involves which displacement pattern of the distal radius?","options": [{"key": "A","text": "Lateral displacement only"},{"key": "B","text": "Dorsal displacement"},{"key": "C","text": "No displacement at all"},{"key": "D","text": "Volar (palmar/anterior) displacement of the distal fragment, often from a fall onto a flexed wrist"}],"correct": "D","explanation": "Smith's fracture is essentially the reverse of Colles' fracture, with volar displacement of the distal radial fragment, typically resulting from a fall onto a flexed wrist."},{"id": 3436,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The scaphoid is the most commonly fractured carpal bone, largely because it:","options": [{"key": "A","text": "Never experiences any loading during normal wrist function"},{"key": "B","text": "Has excellent blood supply and bears minimal load"},{"key": "C","text": "Is located entirely outside the normal load-bearing pathway of the wrist"},{"key": "D","text": "Bridges the proximal and distal carpal rows, experiences significant mechanical stress (particularly with wrist extension/FOOSH mechanisms), and has a precarious, largely distal-to-proximal blood supply predisposing to avascular necrosis if fractured"}],"correct": "D","explanation": "The scaphoid's biomechanical position bridging the carpal rows makes it highly loaded (especially in extension/FOOSH), while its blood supply pattern (entering distally, supplying proximally) predisposes to avascular necrosis if fractured."},{"id": 3437,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The carpal tunnel is bounded by which structures?","options": [{"key": "A","text": "Only the extensor retinaculum"},{"key": "B","text": "The interosseous membrane exclusively"},{"key": "C","text": "The carpal bones (forming a concave floor/sides) and the flexor retinaculum (transverse carpal ligament) forming the roof"},{"key": "D","text": "Only the flexor retinaculum superiorly with no bony boundaries"}],"correct": "C","explanation": "The carpal tunnel is formed by the concave arrangement of carpal bones as the floor/sides and the flexor retinaculum bridging across as the roof, creating a tunnel for passage of the median nerve and flexor tendons."},{"id": 3438,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "Carpal tunnel syndrome results from compression of which nerve as it passes through the carpal tunnel?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "A","explanation": "Carpal tunnel syndrome results from compression of the median nerve within the confined space of the carpal tunnel."},{"id": 3439,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which wrist position has been shown to increase pressure within the carpal tunnel, potentially exacerbating carpal tunnel syndrome symptoms?","options": [{"key": "A","text": "Both full wrist flexion and full wrist extension tend to increase carpal tunnel pressure compared to a neutral position"},{"key": "B","text": "Wrist positioning has no effect on carpal tunnel pressure"},{"key": "C","text": "Neutral wrist position"},{"key": "D","text": "Only mild wrist flexion, with extension having no effect"}],"correct": "A","explanation": "Research has demonstrated that both extreme flexion and extension of the wrist increase pressure within the carpal tunnel compared to a neutral position, informing ergonomic and splinting recommendations for carpal tunnel syndrome management."},{"id": 3440,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The first carpometacarpal (CMC) joint of the thumb is classified structurally as a:","options": [{"key": "A","text": "Hinge joint"},{"key": "B","text": "Saddle (sellar) joint, allowing a wide range of motion including flexion-extension, abduction-adduction, and opposition"},{"key": "C","text": "Ball-and-socket joint"},{"key": "D","text": "Plane joint with minimal motion"}],"correct": "B","explanation": "The thumb CMC joint is a saddle joint, whose reciprocally curved surfaces allow for extensive multiplanar motion including the unique combined movement of opposition."},{"id": 3441,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Opposition of the thumb is a complex combined movement involving:","options": [{"key": "A","text": "Pure flexion only"},{"key": "B","text": "A combination of abduction, flexion, and internal (medial) rotation of the thumb CMC joint, allowing the thumb pad to contact the fingertips"},{"key": "C","text": "Pure extension only"},{"key": "D","text": "No rotational component whatsoever"}],"correct": "B","explanation": "Thumb opposition uniquely combines abduction, flexion, and internal rotation at the CMC joint, enabled by the saddle joint's biaxial mobility, allowing functional pad-to-pad contact with the fingers."},{"id": 3442,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The saddle shape of the thumb CMC joint means that, per the concave-convex rule, the joint surfaces are:","options": [{"key": "A","text": "Entirely flat with no curvature"},{"key": "B","text": "Uniformly convex in all directions"},{"key": "C","text": "Convex in one plane and concave in the perpendicular plane on both articulating surfaces (trapezium and first metacarpal), requiring the concave-convex rule to be applied independently to each plane"},{"key": "D","text": "Uniformly concave in all directions"}],"correct": "C","explanation": "Sellar (saddle) joints like the thumb CMC have reciprocally curved surfaces that are convex in one direction and concave in the perpendicular direction on each bone, requiring the concave-convex rule to be applied separately for each plane of motion."},{"id": 3443,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Metacarpophalangeal (MCP) joints of the fingers are classified structurally as:","options": [{"key": "A","text": "Condyloid joints, allowing flexion-extension and abduction-adduction (biaxial motion)"},{"key": "B","text": "Saddle joints identical to the thumb CMC"},{"key": "C","text": "Hinge joints with one degree of freedom"},{"key": "D","text": "Pivot joints"}],"correct": "A","explanation": "The finger MCP joints are condyloid joints, permitting flexion-extension and abduction-adduction of the fingers."},{"id": 3444,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Interphalangeal (IP) joints of the fingers (both proximal and distal) are classified structurally as:","options": [{"key": "A","text": "Condyloid joints with biaxial motion"},{"key": "B","text": "Saddle joints"},{"key": "C","text": "Hinge joints, permitting motion primarily in flexion-extension only (uniaxial)"},{"key": "D","text": "Ball-and-socket joints"}],"correct": "C","explanation": "The IP joints of the fingers are simple hinge joints, allowing motion essentially only in flexion-extension."},{"id": 3445,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The extensor mechanism (extensor hood/expansion) of the fingers is a complex structure that allows coordinated:","options": [{"key": "A","text": "Extension of the MCP, PIP, and DIP joints through a combination of extrinsic extensor tendon and intrinsic muscle (lumbricals, interossei) contributions"},{"key": "B","text": "Only flexion of all finger joints"},{"key": "C","text": "Only MCP joint flexion"},{"key": "D","text": "No functional contribution to finger movement"}],"correct": "A","explanation": "The extensor mechanism integrates extrinsic extensor tendon force with intrinsic muscle contributions (lumbricals and interossei) to allow coordinated extension across the MCP, PIP, and DIP joints."},{"id": 3446,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "A 'boutonniere deformity' of the finger, characterized by PIP joint flexion with DIP joint hyperextension, typically results from disruption of which structure?","options": [{"key": "A","text": "The central slip of the extensor tendon at the PIP joint, allowing the lateral bands to migrate volarly and alter their mechanical function"},{"key": "B","text": "The volar plate of the MCP joint"},{"key": "C","text": "The flexor digitorum profundus tendon"},{"key": "D","text": "The flexor digitorum superficialis tendon"}],"correct": "A","explanation": "Boutonniere deformity results from central slip disruption at the PIP joint; the lateral bands subsequently migrate volarly (below the joint's axis), converting their action from extension to flexion at the PIP joint while causing DIP hyperextension."},{"id": 3447,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "A 'swan-neck deformity' of the finger, characterized by PIP joint hyperextension with DIP joint flexion, can result from imbalance involving which structures?","options": [{"key": "A","text": "Volar plate laxity at the PIP joint and/or intrinsic muscle tightness, altering the normal balance of extensor and flexor forces across the finger joints"},{"key": "B","text": "No specific structural cause is recognized"},{"key": "C","text": "Central slip disruption exclusively"},{"key": "D","text": "Only DIP joint injury with no PIP involvement"}],"correct": "A","explanation": "Swan-neck deformity often results from volar plate laxity at the PIP joint combined with relative intrinsic muscle tightness, disrupting the normal balance of forces and producing characteristic PIP hyperextension with DIP flexion."},{"id": 3448,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The lumbrical muscles of the hand have a unique biomechanical action of simultaneously producing:","options": [{"key": "A","text": "MCP flexion and IP (PIP and DIP) extension"},{"key": "B","text": "Only finger abduction"},{"key": "C","text": "Only thumb opposition"},{"key": "D","text": "MCP extension and IP flexion"}],"correct": "A","explanation": "Lumbricals uniquely flex the MCP joints while extending the interphalangeal joints, an action essential for functional hand movements like the intrinsic-plus hand position."},{"id": 3449,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The interossei muscles of the hand contribute to which combined actions?","options": [{"key": "A","text": "Only wrist flexion"},{"key": "B","text": "Only thumb opposition"},{"key": "C","text": "Only elbow flexion"},{"key": "D","text": "Finger abduction/adduction (dorsal interossei abduct, palmar interossei adduct) along with contributing to MCP flexion and IP extension similar to the lumbricals"}],"correct": "D","explanation": "Dorsal interossei abduct the fingers (DAB - dorsal abduct) while palmar interossei adduct them (PAD - palmar adduct), and both groups also contribute to MCP flexion with IP extension via the extensor mechanism."},{"id": 3450,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Grip strength is generally optimized (strongest) with the wrist positioned in:","options": [{"key": "A","text": "Radial deviation with wrist flexion"},{"key": "B","text": "Full ulnar deviation with wrist flexion"},{"key": "C","text": "Slight extension (approximately 20-30 degrees) combined with slight ulnar deviation"},{"key": "D","text": "Full flexion"}],"correct": "C","explanation": "Grip strength is biomechanically optimized with the wrist in a position of slight extension and slight ulnar deviation, which optimizes the length-tension relationship of the finger flexor muscles crossing the wrist."},{"id": 3451,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Attempting to grip forcefully with the wrist in full flexion typically results in:","options": [{"key": "A","text": "No change in grip strength"},{"key": "B","text": "Complete inability to flex the fingers at all"},{"key": "C","text": "Decreased grip strength, due to active insufficiency of the finger flexors, which are already shortened over the wrist and cannot generate additional effective tension across the finger joints"},{"key": "D","text": "Increased grip strength compared to a neutral/extended wrist position"}],"correct": "C","explanation": "Gripping with the wrist flexed places the finger flexor tendons in a shortened position (active insufficiency), substantially reducing the muscles' capacity to generate additional useful tension for gripping."},{"id": 3452,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The concept of 'tenodesis action' at the wrist and fingers refers to the phenomenon in which:","options": [{"key": "A","text": "Only active muscle contraction can produce any finger movement"},{"key": "B","text": "Tenodesis action only applies to the elbow joint"},{"key": "C","text": "Passive wrist extension produces passive finger flexion (and vice versa, wrist flexion produces finger extension) due to the fixed length of the multi-joint finger flexor and extensor tendons crossing both the wrist and fingers"},{"key": "D","text": "Wrist and finger movements are completely independent of each other"}],"correct": "C","explanation": "Because finger flexor/extensor tendons cross both the wrist and finger joints with a relatively fixed excursion, passive wrist extension tensions the flexor tendons (producing passive finger flexion), and passive wrist flexion has the opposite effect—a principle sometimes used functionally in patients with certain hand paralysis (e.g., some tetraplegic patients)."},{"id": 3453,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains the clinical relevance of tenodesis action for a patient with a C6 spinal cord injury who has functional wrist extensors but no active finger flexors?","options": [{"key": "A","text": "Tenodesis grasp requires normal finger flexor strength to function"},{"key": "B","text": "The patient may be able to use active wrist extension to passively generate functional finger flexion for grasping (tenodesis grasp), an important functional adaptation often preserved and trained in rehabilitation"},{"key": "C","text": "Tenodesis action has no clinical relevance for this population"},{"key": "D","text": "This mechanism only works with active finger flexor function present"}],"correct": "B","explanation": "Patients with preserved wrist extensor function but absent active finger flexors can utilize the tenodesis effect: active wrist extension passively tensions the finger flexor tendons, producing functional passive finger flexion useful for grasping objects—an important rehabilitation consideration in appropriate spinal cord injury levels."},{"id": 3454,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The 'mallet finger' deformity, characterized by DIP joint flexion with inability to actively extend the DIP joint, results from disruption of:","options": [{"key": "A","text": "The central slip at the PIP joint"},{"key": "B","text": "The volar plate of the MCP joint"},{"key": "C","text": "The terminal extensor tendon at its insertion on the distal phalanx"},{"key": "D","text": "The flexor digitorum profundus tendon insertion"}],"correct": "C","explanation": "Mallet finger results from disruption (rupture or avulsion) of the terminal extensor tendon at its insertion on the distal phalanx, leaving the DIP joint unable to actively extend."},{"id": 3455,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the biomechanical advantage of the human opposable thumb for functional hand use?","options": [{"key": "A","text": "It eliminates the need for finger flexor muscle function"},{"key": "B","text": "It allows precision and power grip patterns (e.g., pad-to-pad pinch, tip pinch, power grasp) essential for fine motor tasks and forceful grip, distinguishing human hand function"},{"key": "C","text": "It has no functional advantage over other primates' hands"},{"key": "D","text": "It only allows power grip, not precision grip"}],"correct": "B","explanation": "The unique mobility of the opposable human thumb (via its saddle CMC joint) enables a wide variety of functional precision and power grip patterns essential for skilled manual tasks."},{"id": 3456,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Ulnar deviation deformity of the fingers at the MCP joints, commonly seen in advanced rheumatoid arthritis, results biomechanically from a combination of:","options": [{"key": "A","text": "Chronic synovitis weakening supporting structures, combined with the natural ulnar pull of extrinsic flexor/extensor tendons and mechanical forces from repetitive hand use, gradually displacing the fingers ulnarly at the MCP joints"},{"key": "B","text": "Only tendon rupture with no joint capsule involvement"},{"key": "C","text": "No identifiable biomechanical cause"},{"key": "D","text": "Purely bony changes with no soft tissue contribution"}],"correct": "A","explanation": "Chronic inflammatory synovitis weakens the MCP joint's supporting structures (volar plate, collateral ligaments), and the combination of this laxity with the natural ulnar-directed pull of tendons and forces from functional hand use gradually produces the characteristic ulnar drift deformity."},{"id": 3457,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why splinting the wrist in a neutral or slightly extended position is often recommended for patients recovering from certain wrist/hand injuries or with conditions like carpal tunnel syndrome?","options": [{"key": "A","text": "This position tends to minimize carpal tunnel pressure and maintain the finger flexor/extensor tendons in a more functionally advantageous length-tension relationship compared to extreme flexed or extended positions"},{"key": "B","text": "Neutral/slight extension has no biomechanical benefit"},{"key": "C","text": "Splint position has no effect on nerve compression or tendon function"},{"key": "D","text": "Full wrist flexion is always the optimal splinting position"}],"correct": "A","explanation": "A neutral or slightly extended wrist splinting position helps minimize carpal tunnel pressure (reducing median nerve compression) while also maintaining more favorable length-tension conditions for the finger flexor/extensor tendons compared to extreme wrist positions."},{"id": 3458,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the biomechanical role of the triangular fibrocartilage complex (TFCC) at the wrist?","options": [{"key": "A","text": "It provides cushioning/load transmission at the ulnar side of the wrist (between the ulna and carpal bones), stabilizes the distal radioulnar joint, and helps distribute load, particularly during ulnar deviation and forearm rotation"},{"key": "B","text": "It is located at the radial side of the wrist exclusively"},{"key": "C","text": "It has no functional role at the wrist"},{"key": "D","text": "It only functions during thumb opposition"}],"correct": "A","explanation": "The TFCC is a key ulnar-sided wrist structure providing cushioning and load distribution between the ulna and carpal bones, while also stabilizing the distal radioulnar joint, particularly relevant during ulnar deviation and forearm rotation."},{"id": 3459,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best describes 'ulnar variance' and its relevance to wrist biomechanics?","options": [{"key": "A","text": "Ulnar variance describes the relative length of the ulna compared to the radius at the wrist; positive ulnar variance (relatively longer ulna) has been associated with increased ulnar-sided load and TFCC stress, while negative variance has been linked to conditions like Kienbock's disease (lunate avascular necrosis)"},{"key": "B","text": "Ulnar variance has no relationship to any wrist pathology"},{"key": "C","text": "Ulnar variance refers to a fixed value identical in all individuals with no clinical relevance"},{"key": "D","text": "Ulnar variance only refers to forearm rotation range"}],"correct": "A","explanation": "Ulnar variance describes the relative radial-ulnar length relationship at the wrist; positive variance increases ulnar-sided loading (relevant to TFCC stress), while negative variance has been associated with increased radial-sided (lunate) loading, implicated in conditions like Kienbock's disease."},{"id": 3460,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why pronator teres syndrome (median nerve compression near the elbow/proximal forearm) may produce different symptom patterns than carpal tunnel syndrome, despite both involving the median nerve?","options": [{"key": "A","text": "There is no difference in symptom pattern between the two conditions"},{"key": "B","text": "Both conditions always produce complete median nerve palsy with no distinguishing features"},{"key": "C","text": "The compression site's location relative to the origin of the palmar cutaneous branch of the median nerve (which branches proximal to the carpal tunnel) can result in different patterns of sensory involvement, since carpal tunnel syndrome typically spares palmar sensation while pronator teres syndrome may not"},{"key": "D","text": "Symptom location is unrelated to the level of nerve compression"}],"correct": "C","explanation": "Since the palmar cutaneous branch of the median nerve arises proximal to the carpal tunnel, compression at the level of pronator teres (proximal forearm) can affect palmar sensation, which is typically spared in isolated carpal tunnel syndrome (where compression occurs within the tunnel, distal to this branch)."},{"id": 3461,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which of the following best describes the biomechanical function of the annular ligament at the proximal radioulnar joint?","options": [{"key": "A","text": "It encircles the radial head, holding it in place against the radial notch of the ulna while allowing the radial head to rotate freely within it during pronation-supination"},{"key": "B","text": "It restricts elbow flexion-extension exclusively"},{"key": "C","text": "It has no functional role at the elbow/forearm"},{"key": "D","text": "It only functions during wrist motion"}],"correct": "A","explanation": "The annular ligament forms a supportive ring around the radial head, maintaining its position against the ulna's radial notch while permitting the necessary rotational motion of the radial head during pronation-supination."},{"id": 3462,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "'Nursemaid's elbow' (radial head subluxation), common in young children, typically results from which mechanism?","options": [{"key": "A","text": "A sudden longitudinal traction/pulling force on the extended, pronated forearm/arm, which can cause the radial head to partially slip beneath the annular ligament"},{"key": "B","text": "Direct axial compression of the elbow"},{"key": "C","text": "Repetitive valgus stress over time"},{"key": "D","text": "Chronic overuse with no acute traumatic mechanism"}],"correct": "A","explanation": "This condition classically results from a sudden pulling force on the extended and pronated arm (e.g., a caregiver lifting a child by the hand), causing the relatively lax annular ligament in young children to partially slip over the radial head."},{"id": 3463,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why the annular ligament is more prone to allowing radial head subluxation in young children compared to adults?","options": [{"key": "A","text": "Children's annular ligaments are thicker and stronger than adults'"},{"key": "B","text": "There is no difference between children's and adults' annular ligament properties"},{"key": "C","text": "In young children, the radial head is not yet fully developed/ossified and the annular ligament is relatively looser, making it more susceptible to allowing the radial head to slip partially through under traction forces"},{"key": "D","text": "Adults have looser annular ligaments than children"}],"correct": "C","explanation": "The relatively underdeveloped radial head and looser annular ligament in young children create conditions more conducive to radial head subluxation under traction forces, a vulnerability that decreases as the child matures."},{"id": 3464,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best summarizes the overall biomechanical importance of coordinated elbow, forearm, and wrist function for effective hand use in daily activities?","options": [{"key": "A","text": "Each joint functions in complete isolation with no interdependence"},{"key": "B","text": "Effective positioning and function of the hand for daily tasks depends on the coordinated interaction of elbow flexion-extension, forearm pronation-supination, and wrist motion, allowing the hand to be optimally oriented in space for a given task"},{"key": "C","text": "Coordinated motion across these joints has no bearing on functional hand tasks"},{"key": "D","text": "Only wrist motion matters for hand function; elbow and forearm are irrelevant"}],"correct": "B","explanation": "Functional positioning of the hand for daily activities relies on the coordinated interplay of elbow, forearm, and wrist motion, allowing appropriate spatial orientation and reach for the hand to perform its intended task."},{"id": 3465,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "The hip joint is classified structurally as a:","options": [{"key": "A","text": "Hinge joint"},{"key": "B","text": "Condyloid joint"},{"key": "C","text": "Saddle joint"},{"key": "D","text": "Ball-and-socket (multiaxial) synovial joint, similar to but more inherently stable than the shoulder"}],"correct": "D","explanation": "The hip is a ball-and-socket joint, allowing motion in three planes, but with substantially greater inherent bony congruity and stability compared to the shoulder."},{"id": 3466,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Compared to the glenohumeral joint, the hip joint is generally considered to have:","options": [{"key": "A","text": "No functional similarity to the shoulder joint"},{"key": "B","text": "Greater inherent stability due to the deep acetabulum closely enclosing the femoral head, at some cost to overall mobility compared to the shoulder"},{"key": "C","text": "Identical mobility and stability characteristics"},{"key": "D","text": "Greater mobility but less stability"}],"correct": "B","explanation": "The hip's deep, well-congruent acetabulum provides substantially greater inherent bony stability than the shallow glenoid of the shoulder, though this comes with somewhat reduced overall mobility compared to the shoulder."},{"id": 3467,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The acetabular labrum functions similarly to the glenoid labrum by:","options": [{"key": "A","text": "Providing no functional contribution"},{"key": "B","text": "Preventing all hip motion"},{"key": "C","text": "Replacing the function of the hip capsule entirely"},{"key": "D","text": "Deepening the acetabulum and increasing the contact area/congruency with the femoral head, enhancing joint stability and load distribution"}],"correct": "D","explanation": "The acetabular labrum increases the effective depth of the acetabulum and enhances congruency with the femoral head, contributing to joint stability, negative intra-articular pressure (suction seal effect), and load distribution."},{"id": 3468,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "The hip joint capsule and its associated ligaments (iliofemoral, pubofemoral, ischiofemoral) are notable for being among the strongest ligamentous structures in the body, providing significant passive stability especially in which position?","options": [{"key": "A","text": "Full extension, where the ligaments typically become maximally taut, contributing to the close-packed position"},{"key": "B","text": "Full abduction only"},{"key": "C","text": "No position provides significant ligamentous tension"},{"key": "D","text": "Full flexion"}],"correct": "A","explanation": "The hip capsular ligaments become maximally taut in full extension (the close-packed position), providing substantial passive stability in this commonly loaded position (e.g., standing)."},{"id": 3469,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The iliofemoral ligament (Y-ligament of Bigelow), one of the strongest ligaments in the body, primarily functions to limit which motion?","options": [{"key": "A","text": "Internal rotation exclusively"},{"key": "B","text": "Hip flexion"},{"key": "C","text": "Hip abduction exclusively"},{"key": "D","text": "Hip extension and, to some degree, external rotation, being particularly important in preventing excessive posterior pelvic tilt during standing"}],"correct": "D","explanation": "The iliofemoral ligament, especially taut in extension, primarily resists excessive hip extension, helping maintain upright standing posture with minimal muscular effort by preventing the pelvis from rotating posteriorly over the femur."},{"id": 3470,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The normal angle of inclination of the femoral neck (relative to the femoral shaft) in a typical adult is approximately:","options": [{"key": "A","text": "45 degrees"},{"key": "B","text": "90 degrees"},{"key": "C","text": "125 degrees"},{"key": "D","text": "180 degrees"}],"correct": "C","explanation": "The normal femoral neck-shaft angle in adults is approximately 125 degrees, though this varies somewhat between individuals."},{"id": 3471,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "An increased femoral neck-shaft angle (greater than normal, e.g., >125-135 degrees) is termed:","options": [{"key": "A","text": "Genu valgum"},{"key": "B","text": "Coxa normal"},{"key": "C","text": "Coxa valga"},{"key": "D","text": "Coxa vara"}],"correct": "C","explanation": "An increased neck-shaft angle beyond normal limits is termed coxa valga, which alters hip joint biomechanics including changes in the hip abductor moment arm."},{"id": 3472,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A decreased femoral neck-shaft angle (less than normal, e.g., <120 degrees) is termed:","options": [{"key": "A","text": "Coxa valga"},{"key": "B","text": "Coxa normal"},{"key": "C","text": "Coxa vara"},{"key": "D","text": "Genu varum"}],"correct": "C","explanation": "A decreased neck-shaft angle is termed coxa vara, which alters hip biomechanics and can affect abductor muscle function and gait."},{"id": 3473,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Coxa vara is biomechanically significant because it tends to:","options": [{"key": "A","text": "Have no effect on abductor muscle function"},{"key": "B","text": "Only affect the knee joint, not the hip"},{"key": "C","text": "Increase the abductor muscle's mechanical advantage"},{"key": "D","text": "Decrease the abductor muscle's effective moment arm and functional length, potentially contributing to abductor weakness and a Trendelenburg-type gait pattern"}],"correct": "D","explanation": "Coxa vara alters the geometric relationship between the greater trochanter (abductor insertion) and the hip joint center, generally reducing the abductor's effective mechanical advantage and potentially contributing to functional weakness."},{"id": 3474,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Coxa valga is biomechanically significant because it tends to:","options": [{"key": "A","text": "Increase the abductor muscle's effective moment arm"},{"key": "B","text": "Have no biomechanical consequence"},{"key": "C","text": "Decrease the abductor muscle's effective moment arm, similar in principle to coxa vara but through a different mechanism, and can also increase shear stress at the femoral neck"},{"key": "D","text": "Only affect the ankle joint"}],"correct": "C","explanation": "Coxa valga alters the femoral neck orientation such that the abductor moment arm may be reduced, and the more vertically oriented femoral neck can experience increased shear stress, potentially predisposing to certain hip conditions."},{"id": 3475,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The normal angle of anteversion of the femoral neck (relative to the femoral condyles/transverse knee axis) in a typical adult is approximately:","options": [{"key": "A","text": "45 degrees"},{"key": "B","text": "0 degrees"},{"key": "C","text": "90 degrees"},{"key": "D","text": "12-15 degrees of anterior angulation"}],"correct": "D","explanation": "Normal femoral anteversion in adults is approximately 12-15 degrees, representing the forward angulation of the femoral neck relative to the transverse axis of the femoral condyles."},{"id": 3476,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Excessive femoral anteversion (greater than normal) commonly contributes to which observable clinical/postural finding?","options": [{"key": "A","text": "Excessive out-toeing gait and increased hip external rotation range with limited internal rotation"},{"key": "B","text": "Only affects upper limb positioning"},{"key": "C","text": "No observable clinical effect"},{"key": "D","text": "Intoeing gait pattern, with increased hip internal rotation range of motion and correspondingly limited external rotation"}],"correct": "D","explanation": "Increased femoral anteversion is commonly associated with intoeing gait and a clinical presentation of increased internal rotation range with limited external rotation range at the hip."},{"id": 3477,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Femoral retroversion (reduced or reversed anteversion angle) commonly contributes to which observable clinical finding?","options": [{"key": "A","text": "No observable clinical effect"},{"key": "B","text": "Intoeing gait with increased internal rotation"},{"key": "C","text": "Out-toeing gait pattern, with increased hip external rotation range of motion and correspondingly limited internal rotation"},{"key": "D","text": "Only affects the shoulder joint"}],"correct": "C","explanation": "Femoral retroversion is associated with out-toeing gait and increased external rotation range with limited internal rotation at the hip."},{"id": 3478,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal hip flexion range of motion (with the knee flexed) is approximately:","options": [{"key": "A","text": "30 degrees"},{"key": "B","text": "120-135 degrees"},{"key": "C","text": "180 degrees"},{"key": "D","text": "60 degrees"}],"correct": "B","explanation": "Normal hip flexion, particularly when tested with the knee flexed (removing hamstring tension), is typically cited as approximately 120-135 degrees."},{"id": 3479,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal hip extension range of motion (measured from neutral, typically in prone) is approximately:","options": [{"key": "A","text": "30-40 degrees"},{"key": "B","text": "150 degrees"},{"key": "C","text": "90 degrees"},{"key": "D","text": "0-10 degrees"}],"correct": "D","explanation": "Normal hip extension range beyond the neutral (anatomical) position is relatively limited, typically cited as approximately 0-10 to 20 degrees depending on measurement technique."},{"id": 3480,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal hip abduction range of motion is approximately:","options": [{"key": "A","text": "90 degrees"},{"key": "B","text": "40-45 degrees"},{"key": "C","text": "150 degrees"},{"key": "D","text": "10 degrees"}],"correct": "B","explanation": "Normal hip abduction range is typically cited as approximately 40-45 degrees."},{"id": 3481,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal hip adduction range of motion (crossing the midline) is approximately:","options": [{"key": "A","text": "20-30 degrees"},{"key": "B","text": "90 degrees"},{"key": "C","text": "60 degrees"},{"key": "D","text": "0 degrees"}],"correct": "A","explanation": "Normal hip adduction range, crossing the midline from neutral, is typically cited as approximately 20-30 degrees."},{"id": 3482,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "During single-limb stance, the body's line of gravity typically falls __________ to the hip joint's axis in the frontal plane, creating an adduction moment that must be counteracted by the hip abductors.","options": [{"key": "A","text": "Lateral to the hip joint's axis"},{"key": "B","text": "Medial to (closer to the midline than) the hip joint's axis, since the stance-limb hip is offset laterally from the body's central line of gravity"},{"key": "C","text": "Directly through"},{"key": "D","text": "There is no adduction moment created during single-limb stance"}],"correct": "B","explanation": "During single-limb stance, the body's center of gravity (located centrally) falls medial to the stance hip joint's axis, creating an external adduction moment/torque that the hip abductors must counteract to maintain pelvic level."},{"id": 3483,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Hard","question": "According to classic hip joint biomechanics models (e.g., based on lever arm principles), the hip abductor muscle force required to maintain pelvic stability during single-limb stance is generally __________ body weight, given the shorter abductor moment arm compared to the body weight's moment arm.","options": [{"key": "A","text": "Less than"},{"key": "B","text": "Unrelated to body weight in any way"},{"key": "C","text": "Considerably greater than (often cited as approximately 2-3 times or more), due to the abductor's relatively short lever arm compared to the longer lever arm through which body weight acts"},{"key": "D","text": "Exactly equal to"}],"correct": "C","explanation": "Because the hip abductor's moment arm (from the greater trochanter to the hip joint center) is considerably shorter than the moment arm through which body weight acts (from the hip joint center to the body's center of gravity), the abductors must generate a force substantially greater than body weight to maintain equilibrium (a classic lever-based hip biomechanics calculation)."},{"id": 3484,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Hip joint reaction force (the compressive force experienced at the hip joint) during single-limb stance is approximately what multiple of body weight, considering both body weight and the required abductor muscle force?","options": [{"key": "A","text": "Less than half of body weight"},{"key": "B","text": "Equal to body weight only"},{"key": "C","text": "Zero, since the joint is non-weight-bearing during single-limb stance"},{"key": "D","text": "Approximately 2.5 to 3 times body weight (or more), due to the combined contribution of body weight and the substantial abductor muscle force required for pelvic stability"}],"correct": "D","explanation": "Since hip joint reaction force must balance both body weight and the abductor muscle force (which itself is a multiple of body weight), the resultant compressive joint force during single-limb stance is estimated at approximately 2.5-3 times body weight or more."},{"id": 3485,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "A cane used in the hand contralateral to a painful/weak hip reduces hip joint reaction force primarily by:","options": [{"key": "A","text": "Only affecting the knee joint, not the hip"},{"key": "B","text": "Creating an additional external force/moment on the opposite side of the body that reduces the abductor muscle force needed to balance the pelvis, thereby lowering the resultant hip joint compressive force"},{"key": "C","text": "Having no biomechanical effect on hip joint loading"},{"key": "D","text": "Increasing the demand on the hip abductors"}],"correct": "B","explanation": "A contralateral cane provides an additional stabilizing moment that reduces the demand on the ipsilateral hip abductors, thereby decreasing the overall hip joint reaction force during stance on the affected side."},{"id": 3486,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Carrying a load (e.g., a bag) in the hand ipsilateral to a painful hip, compared to carrying it contralaterally, tends to:","options": [{"key": "A","text": "Only affect the contralateral hip"},{"key": "B","text": "Have no effect on hip joint loading"},{"key": "C","text": "Increase hip joint reaction force on the painful side further"},{"key": "D","text": "Decrease hip joint reaction force on the painful side, since the ipsilateral load shifts the body's center of gravity closer to the stance hip's axis, reducing the required abductor force"}],"correct": "D","explanation": "Carrying a load on the same side as the stance hip shifts the body's overall center of gravity closer to that hip's axis, reducing the abductor moment arm demand and consequently reducing joint reaction force—unlike a contralateral load, which increases the demand."},{"id": 3487,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best explains why increased body weight (obesity) is associated with increased hip joint loading during activities like walking?","options": [{"key": "A","text": "Since hip joint reaction force is proportional to body weight (multiplied by the biomechanical amplification factor from muscle lever arms), any increase in body weight directly and proportionally increases the compressive forces experienced at the hip joint during weight-bearing activity"},{"key": "B","text": "Body weight has no relationship to hip joint forces"},{"key": "C","text": "Increased body weight only affects the spine, not the hip"},{"key": "D","text": "Hip joint forces decrease with increased body weight due to compensatory changes"}],"correct": "A","explanation": "Since hip joint reaction force calculations directly incorporate body weight (amplified by the muscular lever-arm relationship), any increase in body weight results in a corresponding, often disproportionately amplified, increase in hip joint compressive loading."},{"id": 3488,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "The primary hip flexor muscle, contributing significantly to hip flexion torque, is:","options": [{"key": "A","text": "Iliopsoas (iliacus and psoas major)"},{"key": "B","text": "Biceps femoris"},{"key": "C","text": "Gluteus maximus"},{"key": "D","text": "Gluteus medius"}],"correct": "A","explanation": "Iliopsoas is the primary and strongest hip flexor muscle."},{"id": 3489,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "The primary hip extensor muscle, particularly important for activities like rising from a chair or climbing stairs, is:","options": [{"key": "A","text": "Iliopsoas"},{"key": "B","text": "Sartorius"},{"key": "C","text": "Tensor fasciae latae"},{"key": "D","text": "Gluteus maximus"}],"correct": "D","explanation": "Gluteus maximus is the primary hip extensor, especially important for powerful extension movements against resistance (e.g., stair climbing, rising from sitting)."},{"id": 3490,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Easy","question": "The primary hip abductor muscles, critical for frontal-plane pelvic stability during single-limb stance, are:","options": [{"key": "A","text": "Sartorius exclusively"},{"key": "B","text": "Gluteus medius and gluteus minimus"},{"key": "C","text": "Adductor longus and adductor magnus"},{"key": "D","text": "Piriformis and obturator internus exclusively"}],"correct": "B","explanation": "Gluteus medius and gluteus minimus are the primary hip abductors, essential for maintaining pelvic stability in the frontal plane during single-limb support."},{"id": 3491,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "The hip adductor muscle group (adductor longus, brevis, magnus, gracilis, pectineus) primarily functions to:","options": [{"key": "A","text": "Adduct the hip and contribute to hip flexion and/or extension depending on the specific muscle and hip position, along with providing some rotational contribution"},{"key": "B","text": "Have no functional role at the hip"},{"key": "C","text": "Only abduct the hip"},{"key": "D","text": "Only flex the knee"}],"correct": "A","explanation": "The adductor group's primary action is hip adduction, though individual muscles also contribute variably to hip flexion, extension, and rotation depending on their specific anatomy and the joint's position."},{"id": 3492,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Groin strain injuries commonly involve which muscle group, particularly in activities requiring rapid changes of direction or forceful adduction against resistance (e.g., soccer/football)?","options": [{"key": "A","text": "Hip abductors"},{"key": "B","text": "Hip flexors exclusively"},{"key": "C","text": "Hip adductors, particularly adductor longus"},{"key": "D","text": "Hip external rotators exclusively"}],"correct": "C","explanation": "The hip adductor group, especially adductor longus, is commonly implicated in groin strain injuries, particularly in sports involving rapid cutting, kicking, or forceful adduction."},{"id": 3493,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The deep hip external rotator muscles (piriformis, obturator internus/externus, gemelli, quadratus femoris) primarily function to:","options": [{"key": "A","text": "Externally rotate the hip and provide dynamic stabilization to the femoral head within the acetabulum, analogous in some respects to the rotator cuff's stabilizing role at the shoulder"},{"key": "B","text": "Internally rotate the hip"},{"key": "C","text": "Have no stabilizing function"},{"key": "D","text": "Abduct the hip exclusively"}],"correct": "A","explanation": "These deep external rotators produce hip external rotation while also contributing important dynamic stability to the femoral head within the acetabulum, sometimes likened functionally to the rotator cuff of the shoulder."},{"id": 3494,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Piriformis syndrome, involving compression or irritation of the sciatic nerve by the piriformis muscle, is biomechanically relevant because:","options": [{"key": "A","text": "This condition has no relevance to hip biomechanics"},{"key": "B","text": "The sciatic nerve has no anatomical relationship to the piriformis muscle"},{"key": "C","text": "The sciatic nerve typically passes beneath (and in some anatomical variants, through) the piriformis muscle, making piriformis tightness or hypertrophy a potential source of sciatic nerve compression/irritation"},{"key": "D","text": "Piriformis syndrome only affects the femoral nerve"}],"correct": "C","explanation": "The close anatomical relationship between the sciatic nerve and piriformis muscle (with some individuals having anatomical variants where the nerve passes through the muscle) makes piriformis dysfunction a potential contributor to sciatic nerve irritation."},{"id": 3495,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Tensor fasciae latae (TFL), along with gluteus maximus, contributes to tension in which structure that runs along the lateral thigh, important for lateral hip/knee stability?","options": [{"key": "A","text": "The patellar tendon"},{"key": "B","text": "The iliotibial (IT) band"},{"key": "C","text": "The medial collateral ligament"},{"key": "D","text": "The pes anserine tendon complex"}],"correct": "B","explanation": "TFL and the upper fibers of gluteus maximus insert into the iliotibial band, generating tension that contributes to lateral hip and knee stability, particularly during single-limb stance and gait."},{"id": 3496,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Iliotibial band syndrome, common in runners, is generally attributed to:","options": [{"key": "A","text": "Repetitive friction/compression of the distal IT band against the lateral femoral epicondyle during repeated knee flexion-extension cycles, often related to biomechanical factors like hip abductor weakness or running mechanics"},{"key": "B","text": "Only affecting the hip joint, never the knee region"},{"key": "C","text": "Complete absence of any biomechanical cause"},{"key": "D","text": "Excessive IT band flexibility with no friction involved"}],"correct": "A","explanation": "ITB syndrome is thought to result from repetitive friction or compression of the distal IT band against the lateral femoral epicondyle during running, often influenced by contributing biomechanical factors such as hip abductor weakness altering pelvic/limb mechanics."},{"id": 3497,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Femoroacetabular impingement (FAI) is a condition biomechanically characterized by:","options": [{"key": "A","text": "A condition with no relationship to bony morphology"},{"key": "B","text": "Only occurring in the shoulder, not the hip"},{"key": "C","text": "Abnormal contact/friction between the proximal femur and acetabular rim during hip motion (particularly flexion and internal rotation), due to structural abnormalities of the femoral head-neck junction (cam-type) and/or acetabulum (pincer-type)"},{"key": "D","text": "Excessive acetabular depth with no bony contact issues"}],"correct": "C","explanation": "FAI results from abnormal bony morphology (cam lesion on the femoral head-neck junction and/or pincer lesion of the acetabular rim) causing pathological contact and impingement during normal hip range of motion, particularly deep flexion and internal rotation."},{"id": 3498,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why individuals with cam-type femoroacetabular impingement often experience symptoms particularly during deep hip flexion combined with internal rotation (e.g., deep squatting)?","options": [{"key": "A","text": "This position has no relationship to the cam lesion's location"},{"key": "B","text": "Deep flexion always reduces stress at the hip regardless of bony morphology"},{"key": "C","text": "The cam lesion (a bony prominence at the femoral head-neck junction) makes contact with the acetabular rim/labrum specifically during this combined motion, causing mechanical impingement and potential labral damage"},{"key": "D","text": "Cam lesions only cause symptoms during hip extension"}],"correct": "C","explanation": "The cam lesion's typical location on the anterolateral femoral head-neck junction causes it to engage and abut against the acetabular rim specifically during combined deep flexion and internal rotation, provoking impingement symptoms and potential labral injury."},{"id": 3499,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Hip osteoarthritis commonly follows which capsular pattern of motion restriction, as classically described?","options": [{"key": "A","text": "Equal restriction of all hip movements"},{"key": "B","text": "Extension most limited, followed by abduction, then flexion"},{"key": "C","text": "Internal rotation and flexion most limited, some limitation of abduction, with extension relatively least limited"},{"key": "D","text": "Only external rotation is affected"}],"correct": "C","explanation": "The hip's classic capsular pattern (Cyriax) shows greatest restriction of internal rotation and flexion, moderate limitation of abduction, and comparatively less restriction of extension."},{"id": 3500,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Total hip replacement (arthroplasty) biomechanically aims to restore which key parameters for optimal function?","options": [{"key": "A","text": "Appropriate femoral offset, leg length, and neck-shaft angle to optimize the abductor muscle's mechanical advantage and minimize abnormal joint reaction forces"},{"key": "B","text": "Complete elimination of the need for any muscular function around the hip"},{"key": "C","text": "Only cosmetic appearance, with no biomechanical considerations"},{"key": "D","text": "Only the range of motion, with no attention to joint reaction forces"}],"correct": "A","explanation": "Successful hip arthroplasty aims to restore appropriate femoral offset, leg length, and neck-shaft geometry to optimize the abductor mechanism's effectiveness and avoid excessive/abnormal joint reaction forces postoperatively."},{"id": 3501,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Reduced femoral offset following hip replacement surgery (compared to the patient's natural anatomy) can result in which biomechanical consequence?","options": [{"key": "A","text": "Improved abductor muscle mechanical advantage"},{"key": "B","text": "Reduced abductor muscle moment arm/mechanical advantage, potentially contributing to abductor weakness, increased joint reaction force, and a higher risk of postoperative limp (Trendelenburg-type gait)"},{"key": "C","text": "No effect on abductor function"},{"key": "D","text": "Only affects knee joint mechanics"}],"correct": "B","explanation": "Insufficient femoral offset after hip replacement reduces the effective abductor moment arm, potentially compromising abductor mechanical efficiency and contributing to postoperative gait abnormalities and increased joint loading."},{"id": 3502,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The Trendelenburg test, used clinically to assess hip abductor function, involves observing the position of the pelvis while the patient stands on:","options": [{"key": "A","text": "One leg (single-limb stance), observing whether the contralateral (unsupported) side of the pelvis remains level or drops"},{"key": "B","text": "Neither leg (seated position)"},{"key": "C","text": "Both legs simultaneously"},{"key": "D","text": "Only during active gait, never in static stance"}],"correct": "A","explanation": "The Trendelenburg test assesses hip abductor function by having the patient stand on one leg and observing whether the pelvis on the unsupported side remains level (normal/negative test) or drops (positive test, indicating abductor weakness)."},{"id": 3503,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Avascular necrosis (osteonecrosis) of the femoral head is biomechanically significant because it can lead to:","options": [{"key": "A","text": "No structural consequences whatsoever"},{"key": "B","text": "Improved bone strength in the affected region"},{"key": "C","text": "Structural collapse/deformation of the femoral head due to loss of blood supply and subsequent bone death, potentially altering joint congruency and predisposing to secondary osteoarthritis"},{"key": "D","text": "Only affects the acetabulum, never the femoral head itself"}],"correct": "C","explanation": "Avascular necrosis compromises the structural integrity of the femoral head due to bone death from inadequate blood supply, which can lead to collapse, altered joint congruency, and accelerated secondary osteoarthritis if untreated."},{"id": 3504,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Legg-Calvé-Perthes disease, a pediatric condition involving avascular necrosis of the proximal femoral epiphysis, is of particular biomechanical concern because:","options": [{"key": "A","text": "During the vulnerable revascularization/healing phase, the softened femoral head is susceptible to deformation under normal weight-bearing forces, potentially resulting in a non-spherical femoral head and altered long-term hip joint congruency/mechanics"},{"key": "B","text": "It only affects the acetabulum"},{"key": "C","text": "This condition resolves completely with no biomechanical management required"},{"key": "D","text": "It has no long-term consequence on hip joint shape"}],"correct": "A","explanation": "During the healing phase of Perthes disease, the femoral head is mechanically vulnerable to deformation under normal loading, and management strategies (e.g., containment bracing) often aim to protect the femoral head's shape during this critical period to preserve long-term hip joint congruency."},{"id": 3505,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Slipped capital femoral epiphysis (SCFE), typically occurring in adolescents, biomechanically involves:","options": [{"key": "A","text": "Complete dislocation of the hip joint"},{"key": "B","text": "A condition unrelated to any mechanical factors"},{"key": "C","text": "Displacement (slippage) of the proximal femoral epiphysis relative to the femoral neck through the vulnerable growth plate, often related to increased shear stress at this region during the adolescent growth period, sometimes exacerbated by obesity"},{"key": "D","text": "A fracture through the femoral shaft"}],"correct": "C","explanation": "SCFE involves epiphyseal displacement through the growth plate, with increased shear stress at this mechanically vulnerable region during adolescent growth (often compounded by increased body weight/obesity) considered a contributing biomechanical factor."},{"id": 3506,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why hip abductor strengthening is commonly emphasized in rehabilitation programs for conditions such as patellofemoral pain syndrome, despite the primary symptoms being at the knee?","options": [{"key": "A","text": "Hip abductor strength has no relationship to knee mechanics"},{"key": "B","text": "Hip abductors only affect ankle mechanics, not the knee"},{"key": "C","text": "Strengthening hip abductors always worsens knee symptoms"},{"key": "D","text": "Weak hip abductors can allow excessive hip adduction and internal rotation during weight-bearing activities, which can increase dynamic knee valgus and altered patellofemoral joint stress, contributing to knee symptoms"}],"correct": "D","explanation": "Inadequate hip abductor control can permit excessive dynamic hip adduction/internal rotation during functional activities, contributing to increased dynamic knee valgus and altered patellofemoral joint loading patterns, which is why proximal (hip) strengthening is often incorporated in knee-focused rehabilitation programs."},{"id": 3507,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "During the gait cycle, hip joint reaction forces typically show peaks during which phase(s)?","options": [{"key": "A","text": "Only during double support with no other peaks"},{"key": "B","text": "Only during swing phase, when the limb is unloaded"},{"key": "C","text": "Loading response and terminal stance/pre-swing (push-off), corresponding to the periods of peak muscular demand and body weight transfer"},{"key": "D","text": "Joint reaction force remains constant throughout the entire gait cycle"}],"correct": "C","explanation": "Hip joint reaction forces typically peak during loading response (as weight is rapidly accepted) and again during terminal stance/push-off, corresponding to phases of increased muscular activity and force transmission."},{"id": 3508,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why patients are often advised to avoid combined hip flexion, adduction, and internal rotation in the early postoperative period following a posterior-approach total hip replacement?","options": [{"key": "A","text": "Combined flexion, adduction, and internal rotation always increases stability regardless of surgical approach"},{"key": "B","text": "This position places stress on the posterior structures repaired during a posterior surgical approach, increasing the risk of postoperative posterior hip dislocation"},{"key": "C","text": "This combined position has no relevance to hip stability after this surgical approach"},{"key": "D","text": "This precaution is only relevant for anterior surgical approaches"}],"correct": "B","explanation": "Following a posterior-approach hip replacement, the posterior capsule/structures are surgically disrupted and repaired; the combined position of flexion, adduction, and internal rotation stresses these repaired structures and increases the risk of posterior dislocation during the healing period."},{"id": 3509,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best summarizes the overall biomechanical importance of the hip abductor mechanism for functional activities such as walking and stair climbing?","options": [{"key": "A","text": "Hip abductor function only matters during running, not walking"},{"key": "B","text": "Only hip flexors are relevant to walking; abductors play no role"},{"key": "C","text": "Hip abductors have no functional relevance to gait or stair climbing"},{"key": "D","text": "Adequate hip abductor strength and function are essential for maintaining frontal-plane pelvic stability during single-limb support phases of gait and functional activities, and weakness commonly results in compensatory gait patterns and increased joint stress"}],"correct": "D","explanation": "The hip abductor mechanism is fundamental for maintaining pelvic stability during the single-limb support phases inherent to walking, stair climbing, and similar functional activities; its dysfunction commonly results in compensatory gait patterns (e.g., Trendelenburg) and altered joint loading."},{"id": 3510,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the biomechanical concept of 'hip precautions' following certain hip surgeries, in general terms?","options": [{"key": "A","text": "Precautions are arbitrary and have no biomechanical rationale"},{"key": "B","text": "Precautions apply identically regardless of surgical approach"},{"key": "C","text": "Specific movement combinations that stress the surgically repaired structures (e.g., posterior capsule after posterior approach, or anterior structures after anterior approach) are temporarily restricted to protect healing tissue and reduce dislocation risk during the early postoperative period"},{"key": "D","text": "Hip precautions have no relationship to the surgical approach used"}],"correct": "C","explanation": "Hip precautions are tailored to protect the specific structures disrupted and repaired during a given surgical approach (e.g., avoiding flexion/adduction/internal rotation after posterior approach), reducing dislocation risk while tissues heal."},{"id": 3511,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which of the following muscles, in addition to its role as a hip flexor, also contributes to hip external rotation and is sometimes called the 'tailor's muscle' due to its role in achieving a cross-legged sitting position?","options": [{"key": "A","text": "Rectus femoris"},{"key": "B","text": "Sartorius"},{"key": "C","text": "Semitendinosus"},{"key": "D","text": "Vastus lateralis"}],"correct": "B","explanation": "Sartorius, the longest muscle in the body, contributes to hip flexion, abduction, and external rotation, classically associated with the cross-legged 'tailor's position'."},{"id": 3512,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which of the following best explains why the hip joint is generally less prone to traumatic dislocation than the shoulder joint under normal activity, despite both being ball-and-socket joints?","options": [{"key": "A","text": "The hip has weaker ligamentous support than the shoulder"},{"key": "B","text": "The hip joint has no ligamentous support at all"},{"key": "C","text": "Hip dislocation is actually more common than shoulder dislocation under normal activity"},{"key": "D","text": "The hip's deeper acetabular socket, stronger surrounding ligaments, and larger surrounding musculature provide substantially greater inherent stability compared to the shallow glenoid and comparatively looser capsule of the shoulder"}],"correct": "D","explanation": "The hip's greater bony congruity (deep acetabulum), stronger ligamentous support, and substantial surrounding musculature make it inherently more stable and less prone to dislocation under normal activity loads compared to the more mobile but less constrained shoulder joint."},{"id": 3513,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A posterior hip dislocation (the most common direction of traumatic hip dislocation) classically results from a force applied to the hip while it is positioned in:","options": [{"key": "A","text": "Neutral position with no flexion"},{"key": "B","text": "Flexion, adduction, and internal rotation (e.g., a 'dashboard injury' in a motor vehicle collision with the knee flexed against the dashboard)"},{"key": "C","text": "Full extension and abduction"},{"key": "D","text": "Extension and external rotation"}],"correct": "B","explanation": "Posterior hip dislocation classically occurs when a posteriorly directed force is applied to a flexed, adducted, and internally rotated hip, the classic mechanism seen in dashboard-type motor vehicle injuries."},{"id": 3514,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains the biomechanical rationale for restricting hip flexion beyond 90 degrees combined with adduction and internal rotation in the early postoperative period after a posterior-approach total hip arthroplasty?","options": [{"key": "A","text": "This specific combined position most closely replicates the classic mechanism of posterior hip dislocation, directly stressing the surgically repaired posterior capsule and short external rotators"},{"key": "B","text": "This combination of movements is actually protective and encouraged after this approach"},{"key": "C","text": "Only isolated flexion beyond 90 degrees poses any risk, with adduction and rotation being irrelevant"},{"key": "D","text": "This position combination has no relevance to the repaired posterior structures"}],"correct": "A","explanation": "This combined position mirrors the classic mechanical pathway to posterior hip dislocation, directly loading and stressing the repaired posterior capsule/short external rotators, which is why this specific combination is restricted during early healing after a posterior surgical approach."},{"id": 3515,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Easy","question": "The knee joint complex consists of which two main articulations?","options": [{"key": "A","text": "Only the tibiofemoral joint"},{"key": "B","text": "The proximal and distal tibiofibular joints"},{"key": "C","text": "Only the patellofemoral joint"},{"key": "D","text": "The tibiofemoral joint and the patellofemoral joint"}],"correct": "D","explanation": "The knee joint complex is composed of the tibiofemoral joint (femur-tibia articulation) and the patellofemoral joint (patella-femoral trochlear groove articulation)."},{"id": 3516,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The tibiofemoral joint is classified structurally as a:","options": [{"key": "A","text": "A saddle joint"},{"key": "B","text": "A ball-and-socket joint"},{"key": "C","text": "Simple hinge joint with only one degree of freedom"},{"key": "D","text": "A modified hinge joint permitting flexion-extension as the primary motion, along with some accessory rotation and gliding, making it functionally biaxial/triaxial to a degree"}],"correct": "D","explanation": "While primarily functioning as a hinge for flexion-extension, the tibiofemoral joint also permits some accessory rotation (particularly with knee flexion) and gliding, giving it more complex motion characteristics than a pure hinge."},{"id": 3517,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Normal knee flexion range of motion is approximately:","options": [{"key": "A","text": "135-150 degrees"},{"key": "B","text": "30 degrees"},{"key": "C","text": "180 degrees"},{"key": "D","text": "90 degrees only"}],"correct": "A","explanation": "Normal active knee flexion range of motion is typically cited as approximately 135-150 degrees, with slightly greater passive range often available."},{"id": 3518,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Normal knee extension is generally considered to be:","options": [{"key": "A","text": "Impossible to achieve 0 degrees under normal conditions"},{"key": "B","text": "Always 45 degrees of flexion"},{"key": "C","text": "Always at least 20 degrees of flexion"},{"key": "D","text": "0 degrees (full extension) or slightly beyond into a few degrees of hyperextension in some individuals"}],"correct": "D","explanation": "Normal knee extension typically reaches 0 degrees, with some individuals demonstrating a few degrees of physiological hyperextension."},{"id": 3519,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'screw-home mechanism' of the knee refers to:","options": [{"key": "A","text": "A purely pathological finding never seen in healthy knees"},{"key": "B","text": "An automatic external rotation of the tibia (or internal rotation of the femur) that occurs during the final few degrees of knee extension, resulting in a close-packed, locked position"},{"key": "C","text": "A mechanism unrelated to knee stability"},{"key": "D","text": "An automatic internal rotation of the tibia during flexion only"}],"correct": "B","explanation": "During terminal knee extension, the tibia rotates externally relative to the femur (or the femur rotates internally relative to the tibia) due to the differing shapes/lengths of the femoral condyles, locking the knee into its stable, close-packed position."},{"id": 3520,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The screw-home mechanism occurs due to:","options": [{"key": "A","text": "The medial femoral condyle being longer (having a greater articular surface curvature/length) than the lateral femoral condyle, causing asymmetric motion during the final phase of extension"},{"key": "B","text": "The action of the ACL alone with no contribution from condylar shape"},{"key": "C","text": "Random variation with no consistent anatomical basis"},{"key": "D","text": "Identical size and shape of the medial and lateral femoral condyles"}],"correct": "A","explanation": "The medial femoral condyle's greater length/curvature compared to the lateral condyle causes it to continue moving after the lateral condyle's motion has essentially finished, producing the automatic rotation characteristic of the screw-home mechanism."},{"id": 3521,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "To initiate knee flexion from the fully extended, locked (screw-home) position, which muscle is thought to be particularly important for 'unlocking' the knee by initiating the reverse rotation?","options": [{"key": "A","text": "Tensor fasciae latae"},{"key": "B","text": "Popliteus, which produces internal rotation of the tibia (or external rotation of the femur) to unlock the screw-home mechanism"},{"key": "C","text": "Quadriceps femoris"},{"key": "D","text": "Gastrocnemius exclusively"}],"correct": "B","explanation": "Popliteus is classically described as the muscle responsible for 'unlocking' the knee by initiating the reverse rotation (internal tibial rotation) needed to begin flexion from the fully extended, screw-home locked position."},{"id": 3522,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The medial and lateral menisci of the knee function biomechanically to:","options": [{"key": "A","text": "Generate active contractile force"},{"key": "B","text": "Only provide proprioceptive feedback with no mechanical function"},{"key": "C","text": "Improve joint congruency between the femoral condyles and relatively flat tibial plateau, distribute compressive load, absorb shock, and contribute to joint stability and lubrication"},{"key": "D","text": "Serve no functional role in load transmission"}],"correct": "C","explanation": "The menisci deepen the articulation between the convex femoral condyles and relatively flat tibial plateau, improving congruency, distributing compressive loads over a larger area, absorbing shock, and contributing to overall knee stability and joint lubrication."},{"id": 3523,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Approximately what percentage of compressive load through the knee joint is estimated to be transmitted through the menisci (versus direct femoral-tibial articular contact) in a normal, intact knee?","options": [{"key": "A","text": "Menisci play no role in load transmission whatsoever"},{"key": "B","text": "100%, with no load transmitted directly through the articular cartilage"},{"key": "C","text": "0%"},{"key": "D","text": "Approximately 45-70% (a substantial proportion), depending on knee flexion angle and loading conditions"}],"correct": "D","explanation": "Research estimates that the menisci transmit a substantial proportion (often cited as approximately 45-70%, varying with knee position) of the total compressive load through the knee joint, highlighting their significant load-bearing role."},{"id": 3524,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Partial or complete meniscectomy (surgical removal of meniscal tissue) has been shown to result in which biomechanical consequence for the knee joint?","options": [{"key": "A","text": "Decreased contact stress on the articular cartilage"},{"key": "B","text": "Complete elimination of any future joint degeneration risk"},{"key": "C","text": "No change in joint contact stress"},{"key": "D","text": "A significant increase in peak contact stress on the articular cartilage due to reduced load-distributing surface area, increasing the risk of subsequent osteoarthritis"}],"correct": "D","explanation": "Removal of meniscal tissue reduces the surface area available for load distribution, concentrating stress onto a smaller area of articular cartilage and significantly increasing the long-term risk of degenerative joint changes."},{"id": 3525,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The medial meniscus is generally considered to be __________ mobile than the lateral meniscus, and correspondingly __________ prone to traumatic injury.","options": [{"key": "A","text": "Equally mobile; equally prone to injury"},{"key": "B","text": "More; less"},{"key": "C","text": "Less mobile (due to firmer peripheral attachments including to the medial collateral ligament); more prone to injury"},{"key": "D","text": "More mobile; less prone to injury"}],"correct": "C","explanation": "The medial meniscus has firmer peripheral attachments (including to the deep MCL), reducing its mobility compared to the lateral meniscus, which is thought to contribute to its higher relative injury rate."},{"id": 3526,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The anterior cruciate ligament (ACL) primarily functions to resist which motion of the tibia relative to the femur?","options": [{"key": "A","text": "Posterior translation of the tibia"},{"key": "B","text": "Only lateral translation"},{"key": "C","text": "Anterior translation of the tibia relative to the femur, and also contributes to resisting excessive internal rotation and varus/valgus stress"},{"key": "D","text": "Only knee flexion"}],"correct": "C","explanation": "The ACL is the primary restraint against anterior tibial translation relative to the femur, while also providing secondary restraint against excessive internal rotation and rotational/varus-valgus stresses."},{"id": 3527,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The posterior cruciate ligament (PCL) primarily functions to resist which motion of the tibia relative to the femur?","options": [{"key": "A","text": "Only lateral translation"},{"key": "B","text": "Only knee extension"},{"key": "C","text": "Anterior translation of the tibia"},{"key": "D","text": "Posterior translation of the tibia relative to the femur, being generally considered the strongest ligament of the knee"}],"correct": "D","explanation": "The PCL is the primary restraint against posterior tibial translation relative to the femur and is generally regarded as the strongest of the four major knee ligaments."},{"id": 3528,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The classic mechanism of ACL injury commonly involves which combination of forces/movements?","options": [{"key": "A","text": "A non-contact mechanism involving deceleration, valgus collapse, and rotation of the knee, often during cutting, pivoting, or landing from a jump"},{"key": "B","text": "Pure varus stress with the knee flexed"},{"key": "C","text": "Direct posterior blow to the tibia with the knee flexed 90 degrees"},{"key": "D","text": "Pure axial compression with the knee in full extension"}],"correct": "A","explanation": "The majority of ACL injuries occur via a non-contact mechanism involving deceleration combined with dynamic knee valgus and rotational stress, commonly during cutting, pivoting, or landing maneuvers in sport."},{"id": 3529,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Female athletes have been shown in research to have a higher incidence of non-contact ACL injury compared to male athletes; among the proposed contributing factors is:","options": [{"key": "A","text": "Only equipment differences explain any variation"},{"key": "B","text": "Complete absence of any sex-based difference in ACL injury rates"},{"key": "C","text": "A combination of anatomical (e.g., increased Q-angle, smaller intercondylar notch), hormonal, and neuromuscular control factors (e.g., greater dynamic valgus collapse during landing) that may increase relative ACL loading"},{"key": "D","text": "Identical neuromuscular control patterns between sexes with no difference in injury rates"}],"correct": "C","explanation": "Multiple proposed factors, including anatomical differences (larger Q-angle, notch width), hormonal influences, and neuromuscular control patterns (such as greater landing valgus), have been studied as potential contributors to the higher relative rate of non-contact ACL injury observed in female athletes."},{"id": 3530,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The classic mechanism of PCL injury commonly involves:","options": [{"key": "A","text": "A non-contact valgus/rotation mechanism, identical to ACL injury"},{"key": "B","text": "No identifiable traumatic mechanism, occurring purely from overuse"},{"key": "C","text": "Pure axial compression with the knee locked in extension only"},{"key": "D","text": "A direct blow to the anterior tibia with the knee flexed (e.g., a 'dashboard injury'), or forced hyperflexion/hyperextension of the knee"}],"correct": "D","explanation": "PCL injury classically results from a direct posteriorly-directed force to the proximal anterior tibia with the knee flexed (dashboard-type injury), or from forced hyperflexion or hyperextension mechanisms."},{"id": 3531,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The medial collateral ligament (MCL) primarily resists which stress at the knee?","options": [{"key": "A","text": "Posterior tibial translation exclusively"},{"key": "B","text": "Anterior tibial translation exclusively"},{"key": "C","text": "Valgus stress, being the primary restraint against excessive medial joint gapping"},{"key": "D","text": "Varus stress"}],"correct": "C","explanation": "The MCL is the primary passive restraint against valgus (medially-directed) stress at the knee, resisting excessive opening of the medial joint line."},{"id": 3532,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The lateral collateral ligament (LCL) primarily resists which stress at the knee?","options": [{"key": "A","text": "Varus stress, being the primary restraint against excessive lateral joint gapping"},{"key": "B","text": "Anterior tibial translation exclusively"},{"key": "C","text": "Rotational stress exclusively"},{"key": "D","text": "Valgus stress"}],"correct": "A","explanation": "The LCL is the primary passive restraint against varus (laterally-directed) stress at the knee, resisting excessive opening of the lateral joint line."},{"id": 3533,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "A classic combined injury pattern sometimes described as the 'unhappy triad' (O'Donoghue's triad) involves simultaneous injury to which three structures, classically resulting from a combined valgus and rotational force?","options": [{"key": "A","text": "ACL, LCL, and lateral meniscus"},{"key": "B","text": "LCL, PCL, and lateral meniscus"},{"key": "C","text": "ACL, MCL, and medial meniscus"},{"key": "D","text": "ACL, PCL, and lateral meniscus"}],"correct": "C","explanation": "The classic 'unhappy triad' describes combined injury to the ACL, MCL, and medial meniscus, classically resulting from a lateral blow to the knee producing combined valgus and rotational stress."},{"id": 3534,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why the medial meniscus is particularly vulnerable to injury in combination with MCL and ACL injury (as in the unhappy triad)?","options": [{"key": "A","text": "The medial meniscus's firm attachment to the deep fibers of the MCL means that valgus stress causing MCL injury can simultaneously transmit tensile/compressive stress to the attached medial meniscus"},{"key": "B","text": "The medial meniscus is located entirely separate from the MCL with no direct connection"},{"key": "C","text": "Combined injury patterns are purely coincidental with no anatomical basis"},{"key": "D","text": "The medial meniscus has no anatomical relationship to the MCL"}],"correct": "A","explanation": "Because the medial meniscus is firmly attached to the deep MCL fibers, forces sufficient to injure the MCL (as in valgus/rotational trauma) can be directly transmitted to and injure the attached medial meniscus as well, explaining the frequent co-occurrence of these injuries."},{"id": 3535,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The Lachman test, a clinical test for ACL integrity, is performed with the knee positioned in approximately:","options": [{"key": "A","text": "Full flexion (135+ degrees)"},{"key": "B","text": "Full extension (0 degrees)"},{"key": "C","text": "20-30 degrees of flexion, which is considered more sensitive than testing at 90 degrees (anterior drawer test) due to reduced hamstring/capsular restraint at this angle"},{"key": "D","text": "90 degrees of flexion exclusively"}],"correct": "C","explanation": "The Lachman test is performed at 20-30° of knee flexion, a position where the ACL is the primary restraint to anterior translation with less interference from secondary restraints, making it generally more sensitive than the anterior drawer test performed at 90°."},{"id": 3536,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The anterior drawer test for ACL integrity is performed with the knee positioned at approximately:","options": [{"key": "A","text": "90 degrees of flexion"},{"key": "B","text": "180 degrees"},{"key": "C","text": "0 degrees"},{"key": "D","text": "Only in full weight-bearing standing"}],"correct": "A","explanation": "The anterior drawer test is classically performed with the knee flexed to 90 degrees, applying an anteriorly directed force to the tibia to assess for excessive anterior translation."},{"id": 3537,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why the anterior drawer test may be less sensitive for detecting ACL injury compared to the Lachman test?","options": [{"key": "A","text": "The anterior drawer test always produces false positive results"},{"key": "B","text": "There is no difference in sensitivity between the two tests"},{"key": "C","text": "The Lachman test is actually less accurate than the anterior drawer test"},{"key": "D","text": "At 90 degrees of knee flexion, secondary restraints (e.g., hamstrings, posterior capsule, menisci) can better resist anterior tibial translation even in the presence of ACL deficiency, potentially masking laxity that would be more apparent at the Lachman test's 20-30 degree position"}],"correct": "D","explanation": "At 90° flexion, secondary stabilizing structures are better positioned to resist anterior tibial translation, which can mask ACL-related laxity that is more readily detected at the 20-30° position used in the Lachman test, where the ACL functions as the primary restraint with less secondary compensation."},{"id": 3538,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The patellofemoral joint's primary biomechanical function is to:","options": [{"key": "A","text": "Generate active muscle contraction independently of the quadriceps"},{"key": "B","text": "Provide the majority of knee flexion range of motion"},{"key": "C","text": "Increase the mechanical advantage (moment arm) of the quadriceps tendon, thereby enhancing knee extensor torque, in addition to protecting the anterior knee"},{"key": "D","text": "Serve no functional role beyond anatomical covering"}],"correct": "C","explanation": "The patella functions as a biomechanical pulley, increasing the quadriceps tendon's effective moment arm about the knee's axis of rotation, thereby enhancing the mechanical efficiency and torque output of knee extension."},{"id": 3539,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Removal of the patella (patellectomy) would be expected to result in which biomechanical consequence for knee extensor function?","options": [{"key": "A","text": "Complete loss of any knee extension capability"},{"key": "B","text": "Increased quadriceps mechanical advantage and torque output"},{"key": "C","text": "Decreased quadriceps mechanical advantage (reduced moment arm), requiring greater quadriceps muscle force to produce the same knee extension torque"},{"key": "D","text": "No change in quadriceps function"}],"correct": "C","explanation": "Without the patella's pulley effect increasing the quadriceps tendon's moment arm, greater quadriceps muscle force would be required to generate equivalent knee extension torque, representing a biomechanical disadvantage."},{"id": 3540,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Patellofemoral joint reaction force (compressive stress between the patella and femoral trochlea) generally __________ as knee flexion angle increases.","options": [{"key": "A","text": "Remains constant throughout the range of motion"},{"key": "B","text": "Decreases progressively"},{"key": "C","text": "Becomes zero at end-range flexion"},{"key": "D","text": "Increases progressively, reaching particularly high values during deep flexion activities like squatting or stair descent"}],"correct": "D","explanation": "Patellofemoral joint reaction force increases substantially with increasing knee flexion, as both the quadriceps force required and the effective compression angle increase, explaining why deep-flexion activities are often symptomatic in patellofemoral pain conditions."},{"id": 3541,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The Q-angle (quadriceps angle) is measured as the angle between:","options": [{"key": "A","text": "A line from the ASIS to the tibial tuberosity, and a line from the tibial tuberosity to the mid-patella"},{"key": "B","text": "The line of the patellar tendon and the ACL"},{"key": "C","text": "A line from the PSIS to the ankle, and the tibial shaft"},{"key": "D","text": "The femoral shaft and tibial shaft only, with no reference to the patella"}],"correct": "A","explanation": "The Q-angle is measured between a line from the ASIS through the center of the patella, and a line from the center of the patella to the tibial tuberosity, representing the net lateral pull vector on the patella."},{"id": 3542,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "An increased Q-angle is generally associated with:","options": [{"key": "A","text": "No effect on patellar tracking"},{"key": "B","text": "Decreased lateral pull on the patella"},{"key": "C","text": "Increased lateral pull/tracking force on the patella, potentially contributing to patellofemoral maltracking and associated pain or instability"},{"key": "D","text": "Only affects the hip joint, not the patella"}],"correct": "C","explanation": "A larger Q-angle reflects a greater net lateral force vector acting on the patella during quadriceps contraction, which can predispose to lateral patellar maltracking, instability, or patellofemoral pain."},{"id": 3543,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Normal Q-angle values are generally cited as approximately:","options": [{"key": "A","text": "45 degrees in both sexes"},{"key": "B","text": "0 degrees in all individuals"},{"key": "C","text": "10-15 degrees in males, slightly greater (approximately 15-20 degrees) in females, related to differences in pelvic width"},{"key": "D","text": "90 degrees in both sexes"}],"correct": "C","explanation": "Normal Q-angle is typically cited as approximately 10-15° in males and slightly greater (approximately 15-20°) in females, related to the generally wider female pelvis."},{"id": 3544,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The vastus medialis obliquus (VMO), a distinct portion of the vastus medialis with more horizontally/obliquely oriented fibers, is thought to be particularly important for:","options": [{"key": "A","text": "Producing the majority of knee extension torque"},{"key": "B","text": "Having no distinct functional role separate from the rest of vastus medialis"},{"key": "C","text": "Only functioning during knee flexion"},{"key": "D","text": "Providing a medially-directed stabilizing force to counteract the lateral pull on the patella, helping maintain proper patellar tracking within the trochlear groove"}],"correct": "D","explanation": "The VMO's more oblique fiber orientation is thought to provide an important medially-directed stabilizing force on the patella, helping counterbalance the lateral pull generated by the overall quadriceps mechanism and Q-angle."},{"id": 3545,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Patellofemoral pain syndrome has been associated in research with which of the following contributing biomechanical factors, among others?","options": [{"key": "A","text": "No biomechanical factors are relevant to this condition"},{"key": "B","text": "A combination of local factors (e.g., quadriceps imbalance, patellar tracking), and proximal factors (e.g., hip abductor/external rotator weakness contributing to dynamic knee valgus), and distal factors (e.g., excessive foot pronation)"},{"key": "C","text": "Exclusively genetic factors with no biomechanical contribution"},{"key": "D","text": "Only isolated local patellar cartilage abnormalities with no proximal or distal contributing factors"}],"correct": "B","explanation": "Patellofemoral pain is now understood as a condition with multifactorial biomechanical contributions spanning local (patellar tracking, quadriceps balance), proximal (hip control), and distal (foot/ankle mechanics) factors."},{"id": 3546,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Genu valgum (knock-knee) alignment tends to increase compressive/tensile stress on which knee structures?","options": [{"key": "A","text": "No structures are affected by frontal-plane knee alignment"},{"key": "B","text": "Lateral compartment articular structures (increased compression) and medial structures (increased tensile/ligamentous stress), along with increased lateral patellar tracking forces"},{"key": "C","text": "Medial compartment structures primarily, with reduced lateral compartment stress"},{"key": "D","text": "Only the posterior cruciate ligament is affected"}],"correct": "B","explanation": "Genu valgum increases compressive loading on the lateral tibiofemoral compartment while placing the medial structures under increased tensile stress, and also tends to increase the effective Q-angle, promoting greater lateral patellar tracking forces."},{"id": 3547,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Genu varum (bow-leg) alignment tends to increase compressive stress on which knee compartment?","options": [{"key": "A","text": "Neither compartment is affected"},{"key": "B","text": "Lateral compartment"},{"key": "C","text": "Only the patellofemoral joint is affected"},{"key": "D","text": "Medial tibiofemoral compartment, which is a recognized risk factor for medial compartment osteoarthritis progression"}],"correct": "D","explanation": "Genu varum shifts the mechanical axis medially, increasing compressive load on the medial tibiofemoral compartment, a well-established contributing factor to medial compartment knee osteoarthritis."},{"id": 3548,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "The 'mechanical axis' of the lower limb refers to a line drawn from:","options": [{"key": "A","text": "The center of the femoral head to the center of the ankle joint, ideally passing very close to the center of the knee joint in normal alignment"},{"key": "B","text": "The patella to the tibial tuberosity"},{"key": "C","text": "The greater trochanter to the lateral malleolus only"},{"key": "D","text": "The ankle to the hip, passing through the knee"}],"correct": "A","explanation": "The mechanical axis is defined as the line from the center of the femoral head to the center of the ankle joint (talus), and in ideal alignment this line passes very close to the center of the knee joint."},{"id": 3549,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A mechanical axis that passes medial to the center of the knee (associated with genu varum) results in:","options": [{"key": "A","text": "Equal load distribution between compartments"},{"key": "B","text": "No change in compartmental loading"},{"key": "C","text": "Increased load on the lateral compartment"},{"key": "D","text": "Increased load on the medial compartment of the knee"}],"correct": "D","explanation": "When the mechanical axis deviates medially (as in varus alignment), a greater proportion of load is directed through the medial tibiofemoral compartment."},{"id": 3550,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "High tibial osteotomy, a surgical procedure sometimes used to treat medial compartment knee osteoarthritis, aims to:","options": [{"key": "A","text": "Realign the mechanical axis, shifting load away from the degenerated medial compartment toward the relatively healthier lateral compartment, by correcting varus alignment"},{"key": "B","text": "Increase medial compartment loading further"},{"key": "C","text": "Completely eliminate all weight-bearing through the knee"},{"key": "D","text": "Have no relationship to knee joint loading distribution"}],"correct": "A","explanation": "High tibial osteotomy surgically corrects varus malalignment, shifting the mechanical axis laterally to redistribute load away from the degenerated medial compartment toward the lateral compartment."},{"id": 3551,"subject": "Biomechanics","topic": "Kinematics & Kinetics","difficulty": "Medium","question": "The patellar tendon-quadriceps mechanism functions as an extensor lever system; the patella itself functions biomechanically most similarly to which type of structure?","options": [{"key": "A","text": "A fulcrum with no force-transmission role"},{"key": "B","text": "A muscle belly generating active contractile force"},{"key": "C","text": "A ligament connecting two bones directly"},{"key": "D","text": "A sesamoid bone acting as an anatomical pulley, redirecting and increasing the mechanical advantage of the quadriceps force applied to the tibial tuberosity via the patellar tendon"}],"correct": "D","explanation": "The patella functions as a sesamoid bone serving a pulley-like role, redirecting the quadriceps force around the femoral condyles and increasing its mechanical advantage for producing knee extension torque via the patellar tendon."},{"id": 3552,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Patellar tendinopathy ('jumper's knee'), common in athletes involved in repetitive jumping activities, primarily affects which region of the patellar tendon?","options": [{"key": "A","text": "Most commonly the proximal patellar tendon near its origin at the inferior pole of the patella, related to high tensile/repetitive loading during activities like jumping and landing"},{"key": "B","text": "The quadriceps tendon, not the patellar tendon"},{"key": "C","text": "The tibial tuberosity insertion exclusively, with no involvement of the proximal tendon"},{"key": "D","text": "The mid-substance of the tendon exclusively"}],"correct": "A","explanation": "Patellar tendinopathy most commonly affects the proximal patellar tendon at its origin from the inferior pole of the patella, a region subjected to high repetitive tensile loading during jumping and landing activities."},{"id": 3553,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Osgood-Schlatter disease, common in adolescents during growth spurts, involves traction-related stress and inflammation at which anatomical site?","options": [{"key": "A","text": "The tibial tuberosity, at the patellar tendon insertion, related to repetitive traction stress during a period of relative skeletal vulnerability at the growth plate"},{"key": "B","text": "The fibular head"},{"key": "C","text": "The femoral condyles"},{"key": "D","text": "The medial femoral epicondyle"}],"correct": "A","explanation": "Osgood-Schlatter disease involves traction apophysitis at the tibial tuberosity (patellar tendon insertion site), thought to result from repetitive quadriceps/patellar tendon traction stress during the adolescent growth period when this apophyseal region is relatively vulnerable."},{"id": 3554,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which of the following best explains why deep knee flexion activities (e.g., squatting, kneeling) are often symptomatic in patients with patellofemoral joint degeneration/osteoarthritis?","options": [{"key": "A","text": "Patellofemoral degeneration is unrelated to knee flexion angle"},{"key": "B","text": "Deep flexion decreases patellofemoral joint reaction force"},{"key": "C","text": "Deep flexion substantially increases patellofemoral joint reaction force and contact stress, provoking symptoms in a joint with compromised articular cartilage"},{"key": "D","text": "Deep flexion has no relationship to patellofemoral joint stress"}],"correct": "C","explanation": "Since patellofemoral joint reaction force increases substantially with greater knee flexion, deep-flexion activities generate high contact stresses that are particularly symptomatic in the presence of compromised/degenerated patellofemoral articular cartilage."},{"id": 3555,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Easy","question": "The knee's primary muscles for extension (concentric contraction, e.g., standing from a chair) are:","options": [{"key": "A","text": "Popliteus exclusively"},{"key": "B","text": "Hamstrings (biceps femoris, semitendinosus, semimembranosus)"},{"key": "C","text": "Gastrocnemius exclusively"},{"key": "D","text": "Quadriceps femoris (rectus femoris, vastus lateralis, vastus medialis, vastus intermedius)"}],"correct": "D","explanation": "The quadriceps femoris group is the primary knee extensor, generating the torque needed for activities like standing, stair climbing, and walking."},{"id": 3556,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Easy","question": "The knee's primary muscles for flexion are:","options": [{"key": "A","text": "Hamstrings (biceps femoris, semitendinosus, semimembranosus), with assistance from gastrocnemius and other secondary flexors"},{"key": "B","text": "Tibialis anterior"},{"key": "C","text": "Only the gastrocnemius"},{"key": "D","text": "Quadriceps femoris"}],"correct": "A","explanation": "The hamstring muscle group is the primary knee flexor, with the gastrocnemius (and other muscles like sartorius, gracilis, popliteus) providing secondary contribution."},{"id": 3557,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which knee flexor muscle also crosses the ankle joint, contributing to ankle plantarflexion as a secondary action?","options": [{"key": "A","text": "Sartorius"},{"key": "B","text": "Biceps femoris"},{"key": "C","text": "Gastrocnemius"},{"key": "D","text": "Semitendinosus"}],"correct": "C","explanation": "Gastrocnemius, as a two-joint muscle, crosses both the knee (contributing to flexion) and the ankle (as the primary plantarflexor contributor along with soleus)."},{"id": 3558,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "The hamstring muscles, being two-joint muscles crossing both the hip and knee, can experience active insufficiency when attempting to simultaneously produce which combined movements?","options": [{"key": "A","text": "Hip extension and knee flexion simultaneously (their normal combined synergistic action)"},{"key": "B","text": "Hip flexion and knee flexion (e.g., attempting to actively achieve both maximal hip flexion and maximal knee flexion simultaneously)"},{"key": "C","text": "Hip flexion and knee extension simultaneously"},{"key": "D","text": "Hip extension and knee extension simultaneously"}],"correct": "B","explanation": "Since the hamstrings flex the knee but extend the hip, attempting simultaneous maximal hip flexion and knee flexion shortens the muscle over both joints, resulting in active insufficiency and reduced effective force generation."},{"id": 3559,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "The straight leg raise test's range is commonly limited by passive insufficiency of which two-joint muscle group when the knee is kept extended?","options": [{"key": "A","text": "Iliopsoas exclusively"},{"key": "B","text": "Hamstrings, since they are lengthened over both the hip (flexed) and knee (extended) simultaneously during this test"},{"key": "C","text": "Gastrocnemius exclusively"},{"key": "D","text": "Quadriceps"}],"correct": "B","explanation": "During a straight leg raise with the knee extended, the hamstrings are lengthened over both the hip and knee simultaneously, and their passive insufficiency (inability to stretch further) commonly limits the achievable range of hip flexion in this test position."},{"id": 3560,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best describes why quadriceps strengthening exercises are often initially performed with limited knee flexion range (e.g., terminal knee extension, 0-30 degrees) in early post-injury/post-surgical rehabilitation for certain patellofemoral or ACL-related conditions?","options": [{"key": "A","text": "This range generally produces lower patellofemoral joint reaction forces and, in ACL-related contexts, involves less anterior tibial shear stress from quadriceps contraction compared to more flexed positions, making it relatively lower-risk during early healing"},{"key": "B","text": "Deep flexion always produces the lowest patellofemoral stress"},{"key": "C","text": "Limiting range has no biomechanical rationale"},{"key": "D","text": "This range is chosen arbitrarily with no relation to joint forces"}],"correct": "A","explanation": "Limited-range quadriceps exercises performed near terminal extension generally involve relatively lower patellofemoral joint reaction forces, and in ACL rehabilitation contexts, this range is associated with reduced anterior tibial shear stress from quadriceps activation, making it a relatively protected exercise range during early-stage rehabilitation."},{"id": 3561,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why open-chain knee extension exercises (e.g., seated leg extension machine) near terminal extension may be approached cautiously in early ACL reconstruction rehabilitation?","options": [{"key": "A","text": "Open-chain exercises are always safer than closed-chain exercises for the ACL"},{"key": "B","text": "Isolated quadriceps contraction against resistance near terminal knee extension can generate significant anterior tibial shear force, potentially stressing a healing ACL graft, in contrast to closed-chain exercises which tend to generate more balanced hamstring co-contraction"},{"key": "C","text": "Open-chain extension near terminal range has no relevance to ACL graft stress"},{"key": "D","text": "Anterior tibial shear force only occurs during closed-chain exercises"}],"correct": "B","explanation": "Open-chain quadriceps contraction, particularly near terminal extension, can generate substantial anterior tibial shear force due to the patellar tendon's angle of pull, potentially stressing a healing ACL graft; closed-chain exercises tend to promote more balanced quadriceps-hamstring co-contraction, generally producing comparatively less isolated anterior shear stress."},{"id": 3562,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes the biomechanical rationale for including hamstring strengthening as part of ACL injury prevention and rehabilitation programs?","options": [{"key": "A","text": "Hamstring strength has no relationship to ACL loading"},{"key": "B","text": "Hamstring contraction always increases anterior tibial translation"},{"key": "C","text": "Only quadriceps strength is relevant to ACL protection"},{"key": "D","text": "The hamstrings, via their posterior pull on the tibia, can act as a dynamic antagonist to anterior tibial translation (the primary motion resisted by the ACL), so adequate hamstring strength/co-contraction may help reduce ACL loading during dynamic activities"}],"correct": "D","explanation": "Since hamstring contraction produces a posteriorly-directed pull on the tibia (opposing anterior tibial translation, which the ACL resists), adequate hamstring strength and appropriate co-contraction timing are thought to provide a protective, ACL-unloading effect during dynamic movements, informing their inclusion in prevention and rehabilitation programs."},{"id": 3563,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best describes 'dynamic knee valgus', a movement pattern often assessed during functional tasks like single-leg squats or landing?","options": [{"key": "A","text": "A purely static frontal-plane alignment finding with no relationship to movement"},{"key": "B","text": "A protective movement pattern that reduces injury risk"},{"key": "C","text": "A movement pattern in which the knee collapses medially relative to the hip and foot during dynamic loading tasks, often attributed to a combination of hip, knee, and ankle/foot control factors, and considered a potential risk factor for conditions like ACL injury and patellofemoral pain"},{"key": "D","text": "A term with no established clinical relevance"}],"correct": "C","explanation": "Dynamic knee valgus describes medial knee collapse relative to the hip and foot during functional loading tasks, thought to arise from a combination of proximal (hip control) and distal (foot/ankle) factors, and is considered a potential biomechanical risk factor for several knee conditions including ACL injury and patellofemoral pain."},{"id": 3564,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains the biomechanical rationale for incorporating hip and core strengthening/control exercises into ACL injury prevention programs, despite the ACL being a structure local to the knee?","options": [{"key": "A","text": "Hip and core exercises are included purely for general fitness with no ACL-specific rationale"},{"key": "B","text": "Improved proximal (hip and trunk) control can reduce dynamic knee valgus and associated abnormal loading patterns during high-risk movements (e.g., landing, cutting), thereby potentially reducing the mechanical stress placed on the ACL during these activities"},{"key": "C","text": "Hip and core strength have no relationship to knee joint loading during dynamic tasks"},{"key": "D","text": "Only ankle strengthening is relevant to ACL injury prevention"}],"correct": "B","explanation": "Since proximal (hip/trunk) control influences the degree of dynamic knee valgus and overall lower limb alignment during high-risk movements, improving this control is thought to help reduce the abnormal loading patterns that increase ACL injury risk during activities like landing and cutting."},{"id": 3565,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following best explains why isolated hamstring strengthening alone, without addressing quadriceps strength/balance, might not be sufficient for comprehensive knee rehabilitation following certain injuries?","options": [{"key": "A","text": "Quadriceps strength is irrelevant to functional knee performance"},{"key": "B","text": "Quadriceps and hamstrings have identical biomechanical functions with no complementary relationship"},{"key": "C","text": "Hamstring strength alone is always sufficient for full functional knee recovery"},{"key": "D","text": "Comprehensive knee function depends on balanced strength and coordinated activation of both the quadriceps and hamstrings (as well as other surrounding musculature), since both muscle groups contribute complementary and sometimes opposing biomechanical roles important for stability and function"}],"correct": "D","explanation": "Since the quadriceps and hamstrings play complementary (and sometimes opposing) roles in knee extension/flexion and dynamic stability, comprehensive rehabilitation typically requires balanced attention to both muscle groups (and surrounding musculature) rather than isolated focus on just one."},{"id": 3566,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Medium","question": "Which of the following best describes the general biomechanical effect of increasing walking speed on knee joint loading during gait?","options": [{"key": "A","text": "Knee joint loading is completely independent of gait speed"},{"key": "B","text": "Walking speed has no relationship to knee joint loading"},{"key": "C","text": "Increased walking speed decreases knee joint loading"},{"key": "D","text": "Increased walking speed generally increases peak knee joint forces and moments, due to greater ground reaction forces and muscular demands associated with faster movement"}],"correct": "D","explanation": "Faster walking speeds are generally associated with increased peak ground reaction forces and greater muscular/joint force demands at the knee, resulting in higher overall knee joint loading compared to slower walking."},{"id": 3567,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Stair descent generally places __________ demand on the quadriceps (eccentric control) compared to stair ascent (concentric quadriceps demand), and correspondingly tends to produce __________ patellofemoral joint stress.","options": [{"key": "A","text": "Substantial eccentric; lower"},{"key": "B","text": "No; equal"},{"key": "C","text": "Lower; lower"},{"key": "D","text": "Substantial eccentric; often higher, due to the combination of increased knee flexion angles and the eccentric loading pattern"}],"correct": "D","explanation": "Stair descent requires substantial eccentric quadriceps control to lower the body in a controlled manner, and the combination of this eccentric loading pattern with the knee flexion angles involved often results in higher patellofemoral joint stress compared to ascent, explaining why descent is frequently more symptomatic in patellofemoral pain patients."},{"id": 3568,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why patients with patellofemoral pain often report increased symptoms with prolonged sitting with the knees flexed ('theater sign' or 'movie sign')?","options": [{"key": "A","text": "Prolonged knee flexion has no relationship to patellofemoral joint stress"},{"key": "B","text": "Sitting always decreases patellofemoral joint stress compared to standing"},{"key": "C","text": "This symptom pattern has no established biomechanical explanation"},{"key": "D","text": "Sustained knee flexion maintains increased patellofemoral joint compressive stress over a prolonged period, which can provoke symptoms related to the compromised patellofemoral joint"}],"correct": "D","explanation": "Since patellofemoral joint compressive stress increases with knee flexion, sustained flexed positions during prolonged sitting maintain this elevated stress over time, which can provoke symptoms in patients with patellofemoral joint dysfunction—the classic 'theater sign'."},{"id": 3569,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best summarizes the interdependent biomechanical relationship between the tibiofemoral and patellofemoral joints during normal knee function?","options": [{"key": "A","text": "The two joints function completely independently with no biomechanical interaction"},{"key": "B","text": "Quadriceps force acting through the patellofemoral mechanism directly produces the torque needed for tibiofemoral extension, meaning dysfunction or altered mechanics at either joint can influence the function and loading of the other"},{"key": "C","text": "The patellofemoral joint has no relationship to knee extension torque production"},{"key": "D","text": "Only the tibiofemoral joint contributes to functional knee movement; the patellofemoral joint is irrelevant"}],"correct": "B","explanation": "Since the quadriceps mechanism transmits its extensor force through the patellofemoral joint to ultimately produce tibiofemoral extension torque via the patellar tendon, these two joints are biomechanically interdependent, with dysfunction at one often influencing mechanics and loading at the other."},{"id": 3570,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which of the following best describes the biomechanical concept of 'knee joint laxity' as distinguished from 'knee joint instability'?","options": [{"key": "A","text": "Laxity refers to the passive, measurable amount of joint movement/translation (which can be normal or excessive), while instability refers to a functional/symptomatic complaint of the knee 'giving way' during activity, which may or may not directly correlate with measured laxity"},{"key": "B","text": "Laxity always indicates a pathological, symptomatic condition"},{"key": "C","text": "The two terms are interchangeable with no meaningful distinction"},{"key": "D","text": "Instability refers only to a radiographic finding with no functional component"}],"correct": "A","explanation": "Laxity describes the objectively measurable passive translation/motion at a joint (which can be within normal limits or excessive), whereas instability describes the functional experience of the joint 'giving way,' and the relationship between measured laxity and reported functional instability is not always directly proportional."},{"id": 3571,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "The tibial plateau is generally described as having which relative shape on its medial versus lateral aspects?","options": [{"key": "A","text": "The tibial plateau has no distinguishable shape variation"},{"key": "B","text": "Both medial and lateral plateaus are equally convex"},{"key": "C","text": "The medial tibial plateau is relatively concave, while the lateral tibial plateau is relatively convex (or flatter), contributing to differing contact mechanics between the two compartments"},{"key": "D","text": "Both plateaus are identically concave"}],"correct": "C","explanation": "The medial tibial plateau tends to be relatively concave while the lateral plateau is comparatively flatter or slightly convex, contributing to different congruency and contact mechanics between the medial and lateral tibiofemoral compartments."},{"id": 3572,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Hard","question": "Which of the following best describes the popliteus muscle's biomechanical role beyond initiating knee 'unlocking'?","options": [{"key": "A","text": "It also assists in controlling excessive anterior tibial translation and external rotation, contributing to posterolateral knee stability, particularly during the early phase of knee flexion"},{"key": "B","text": "It functions exclusively at the hip joint"},{"key": "C","text": "It has no other functional role"},{"key": "D","text": "It functions exclusively as a knee extensor"}],"correct": "A","explanation": "Beyond unlocking the screw-home mechanism, popliteus also contributes to posterolateral knee stability, including some restraint against excessive anterior tibial translation and external tibial rotation."},{"id": 3573,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "A 'bucket-handle' meniscal tear refers to:","options": [{"key": "A","text": "A longitudinal tear pattern in which a displaced fragment of meniscus can flip into the intercondylar notch, potentially causing mechanical locking of the knee"},{"key": "B","text": "A small, peripheral tear with no displacement"},{"key": "C","text": "A tear that never causes any mechanical symptoms"},{"key": "D","text": "A tear affecting only the anterior horn"}],"correct": "A","explanation": "A bucket-handle tear is a longitudinal meniscal tear in which the inner fragment can displace centrally into the intercondylar notch, often causing mechanical locking or a block to full knee extension."},{"id": 3574,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why a displaced bucket-handle meniscal tear commonly presents with a mechanical block to full knee extension ('locked knee')?","options": [{"key": "A","text": "The torn fragment has no effect on joint space"},{"key": "B","text": "Meniscal tears never affect knee range of motion"},{"key": "C","text": "Locking only occurs with ligamentous injury, never meniscal pathology"},{"key": "D","text": "The displaced meniscal fragment can physically occupy the intercondylar notch space needed for the femur and tibia to achieve full extension, mechanically blocking the terminal degrees of motion"}],"correct": "D","explanation": "When the displaced bucket-handle fragment sits within the intercondylar notch, it physically occupies space required for full extension, creating a mechanical block that prevents the knee from reaching its normal terminal extension range."},{"id": 3575,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best describes the general biomechanical difference in injury susceptibility between the medial and lateral menisci during combined rotational and valgus/varus loading?","options": [{"key": "A","text": "Both menisci are equally susceptible to injury under all loading conditions"},{"key": "B","text": "The medial meniscus, being less mobile and attached to the MCL, is particularly vulnerable during combined valgus and rotational loading, while the lateral meniscus (more mobile) is comparatively more resistant to this specific mechanism but can be injured under different loading patterns"},{"key": "C","text": "The lateral meniscus is always more commonly injured than the medial meniscus"},{"key": "D","text": "Neither meniscus is susceptible to rotational injury"}],"correct": "B","explanation": "The medial meniscus's relative immobility (due to firm peripheral/MCL attachment) makes it particularly vulnerable during combined valgus-rotational loading, whereas the more mobile lateral meniscus tends to be comparatively more resistant to this specific injury mechanism, though it remains susceptible to other loading patterns."},{"id": 3576,"subject": "Biomechanics","topic": "Posture & Balance","difficulty": "Medium","question": "Which of the following best describes the biomechanical function of the knee joint capsule in providing overall joint stability?","options": [{"key": "A","text": "It only provides stability during non-weight-bearing conditions"},{"key": "B","text": "It provides no stabilizing function whatsoever"},{"key": "C","text": "It functions purely as a covering with no mechanical role"},{"key": "D","text": "It provides passive restraint against excessive motion in multiple directions and, along with its synovial lining, helps maintain joint lubrication and nutrition, working alongside the ligaments and menisci for overall stability"}],"correct": "D","explanation": "The knee joint capsule contributes passive restraint against excessive multidirectional motion and, through its synovial lining, supports joint lubrication and cartilage nutrition, functioning together with the ligaments and menisci to provide comprehensive joint stability."},{"id": 3577,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains why isokinetic testing of the knee extensors/flexors is often performed at multiple angular velocities during clinical assessment?","options": [{"key": "A","text": "Velocity has no effect on measured knee torque"},{"key": "B","text": "Testing at a single velocity provides complete information about muscle function"},{"key": "C","text": "Since the force-velocity relationship means muscle torque output varies with movement speed, testing at multiple velocities provides a more comprehensive profile of strength across functionally relevant speeds (e.g., slower velocities for maximal force capacity, faster velocities more reflective of functional/athletic movement speeds)"},{"key": "D","text": "Isokinetic testing can only be performed at one fixed velocity by definition"}],"correct": "C","explanation": "Because muscle torque output varies with contraction velocity (force-velocity relationship), testing across multiple velocities gives a more complete picture of a muscle group's functional capacity, from near-maximal force production at slower speeds to more functionally relevant output at faster speeds."},{"id": 3578,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Hard","question": "Which of the following best explains the biomechanical rationale for functional knee bracing after ACL reconstruction in some rehabilitation protocols?","options": [{"key": "A","text": "Certain functional braces are designed to provide some mechanical resistance to excessive anterior tibial translation and rotational stress, potentially offering additional protection to the healing graft during controlled return to activity, though evidence on their overall effectiveness varies"},{"key": "B","text": "Braces are only used for cosmetic purposes with no biomechanical function"},{"key": "C","text": "Functional bracing eliminates all need for rehabilitation exercise"},{"key": "D","text": "Bracing has no biomechanical rationale and is purely a placebo intervention"}],"correct": "A","explanation": "Functional ACL braces are designed with the biomechanical rationale of providing additional mechanical resistance to anterior tibial translation and rotational stress during the return-to-activity phase, though the overall evidence regarding their effectiveness in preventing re-injury or graft stress remains an area of ongoing research and some debate."},{"id": 3579,"subject": "Biomechanics","topic": "Gait Analysis","difficulty": "Hard","question": "Which of the following best describes the concept of 'quadriceps avoidance gait' sometimes observed in patients with ACL deficiency?","options": [{"key": "A","text": "A gait pattern unrelated to any knee ligament status"},{"key": "B","text": "An adaptive gait pattern in which the patient minimizes quadriceps activation near terminal extension (sometimes maintaining slight knee flexion through stance) to reduce anterior tibial shear force associated with quadriceps contraction in an ACL-deficient knee"},{"key": "C","text": "A gait pattern with excessive quadriceps activation throughout stance phase"},{"key": "D","text": "A pattern only seen after successful ACL reconstruction, never in ACL-deficient patients"}],"correct": "B","explanation": "Quadriceps avoidance gait describes a compensatory pattern where patients with ACL deficiency reduce quadriceps activation (particularly near terminal extension) to minimize the anterior tibial shear forces that unopposed quadriceps contraction can generate in the absence of a functional ACL."},{"id": 3580,"subject": "Biomechanics","topic": "Muscle Mechanics","difficulty": "Medium","question": "Which of the following best explains why co-contraction of the quadriceps and hamstrings is often emphasized during functional rehabilitation exercises following ACL injury or reconstruction?","options": [{"key": "A","text": "Co-contraction has no relevance to ACL protection"},{"key": "B","text": "Co-contraction always increases anterior tibial shear force with no protective benefit"},{"key": "C","text": "Simultaneous hamstring activation can help counteract/offset the anterior tibial shear force generated by quadriceps contraction, thereby providing dynamic protection to the ACL (or ACL graft) during functional movement"},{"key": "D","text": "Only isolated quadriceps activation is relevant to ACL rehabilitation"}],"correct": "C","explanation": "Since hamstring contraction produces a posteriorly-directed pull on the tibia that can counteract the anterior shear force generated by quadriceps activation, promoting appropriate quadriceps-hamstring co-contraction is a common strategy in ACL rehabilitation to provide dynamic protective loading to the healing ligament/graft."},{"id": 3581,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Hard","question": "Which of the following best describes the general biomechanical trend in tibiofemoral joint contact area as the knee moves from full extension into increasing flexion?","options": [{"key": "A","text": "Contact area is always greatest in full extension with no variation through the range"},{"key": "B","text": "Contact area remains constant throughout the range of motion"},{"key": "C","text": "Contact area becomes zero at any flexion angle beyond 90 degrees"},{"key": "D","text": "Contact area and its location on the tibial plateau/femoral condyles change throughout the range, generally with different contact patterns at full extension (where the screw-home mechanism locks the joint) compared to mid-to-deep flexion"}],"correct": "D","explanation": "The area and location of tibiofemoral contact change dynamically throughout the range of motion, influenced by factors like the screw-home mechanism at full extension and the rolling/gliding mechanics of the femoral condyles during flexion, rather than remaining fixed."},{"id": 3582,"subject": "Biomechanics","topic": "General Biomechanics","difficulty": "Medium","question": "Which of the following best explains why maintaining adequate quadriceps strength is particularly emphasized in the management of knee osteoarthritis?","options": [{"key": "A","text": "Adequate quadriceps strength helps provide dynamic shock absorption and joint stability during functional activities, and quadriceps weakness has been associated in research with increased pain, reduced function, and potentially increased disease progression risk in knee osteoarthritis"},{"key": "B","text": "Quadriceps weakness always improves knee osteoarthritis symptoms"},{"key": "C","text": "Quadriceps strength has no relationship to knee osteoarthritis symptoms or function"},{"key": "D","text": "Only hamstring strength is relevant to knee osteoarthritis management"}],"correct": "A","explanation": "Since the quadriceps provide important dynamic shock absorption and stability during weight-bearing activities, and quadriceps weakness has been linked in research to worse pain, function, and potentially disease progression in knee OA, quadriceps strengthening is a cornerstone of conservative knee OA management."},{"id": 3583,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "A 'knee joint effusion' (excess synovial fluid within the joint) commonly results in which biomechanical/clinical finding related to quadriceps function?","options": [{"key": "A","text": "Only affects hamstring function, not quadriceps"},{"key": "B","text": "Reflexive quadriceps inhibition (sometimes called arthrogenic muscle inhibition), reducing the muscle's ability to fully activate, even in the absence of direct muscle damage"},{"key": "C","text": "No effect on quadriceps function whatsoever"},{"key": "D","text": "Improved quadriceps activation and strength"}],"correct": "B","explanation": "Joint effusion is associated with arthrogenic muscle inhibition, a reflexive neural mechanism that reduces the quadriceps' ability to fully activate, contributing to functional weakness independent of any direct muscle tissue damage."},{"id": 3584,"subject": "Biomechanics","topic": "Joint Biomechanics","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical relevance of understanding knee joint biomechanics for physiotherapy practice?","options": [{"key": "A","text": "A solid understanding of knee joint biomechanics (including ligamentous function, meniscal role, patellofemoral mechanics, and muscular contributions) underpins accurate clinical assessment, appropriate exercise prescription, and evidence-informed rehabilitation progression for a wide range of knee conditions"},{"key": "B","text": "Knee biomechanics knowledge is only relevant for elite athletic populations"},{"key": "C","text": "Knee biomechanics has minimal practical relevance to physiotherapy assessment or treatment"},{"key": "D","text": "Only surgeons need to understand knee biomechanics, not physiotherapists"}],"correct": "A","explanation": "A thorough grasp of knee joint biomechanics is foundational for physiotherapists to accurately assess knee dysfunction, select appropriate and safe rehabilitation exercises, and make evidence-informed decisions when progressing patients through recovery from a wide range of knee conditions and injuries."},{"id": 3585,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Which type of cell death is characterized by cell swelling, karyolysis, and inflammation?","options": [{"key": "A","text": "Necrosis"},{"key": "B","text": "Pyknosis"},{"key": "C","text": "Autophagy"},{"key": "D","text": "Apoptosis"}],"correct": "A","explanation": "Necrosis is passive, causes membrane rupture and triggers inflammation, unlike apoptosis."},{"id": 3586,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Irreversible cell injury is first indicated by damage to which organelle?","options": [{"key": "A","text": "Lysosome"},{"key": "B","text": "Mitochondria"},{"key": "C","text": "Nucleus"},{"key": "D","text": "Golgi apparatus"}],"correct": "B","explanation": "Mitochondrial permeability transition marks the point of no return in cell injury."},{"id": 3587,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Coagulative necrosis is typically seen in which organ following infarction?","options": [{"key": "A","text": "Spinal cord"},{"key": "B","text": "Heart"},{"key": "C","text": "Lung"},{"key": "D","text": "Brain"}],"correct": "B","explanation": "Coagulative necrosis preserves tissue architecture and is classic in solid organs like heart/kidney."},{"id": 3588,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Liquefactive necrosis is characteristic of infarcts in which tissue?","options": [{"key": "A","text": "Spleen"},{"key": "B","text": "Kidney"},{"key": "C","text": "Brain"},{"key": "D","text": "Liver"}],"correct": "C","explanation": "Brain infarcts undergo liquefactive necrosis due to high lipid content and autolytic enzymes."},{"id": 3589,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Caseous necrosis is most commonly associated with which disease?","options": [{"key": "A","text": "Pancreatitis"},{"key": "B","text": "Gangrene"},{"key": "C","text": "Tuberculosis"},{"key": "D","text": "Fat necrosis"}],"correct": "C","explanation": "TB granulomas show cheese-like caseous necrosis with amorphous debris."},{"id": 3590,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Which enzyme is a marker of fat necrosis in pancreatitis?","options": [{"key": "A","text": "Lipase"},{"key": "B","text": "LDH"},{"key": "C","text": "ALP"},{"key": "D","text": "CPK"}],"correct": "A","explanation": "Lipase released from injured pancreatic cells causes fat necrosis (saponification)."},{"id": 3591,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Apoptosis is characterized by all EXCEPT:","options": [{"key": "A","text": "Chromatin condensation"},{"key": "B","text": "Inflammatory response"},{"key": "C","text": "Apoptotic bodies"},{"key": "D","text": "Cell shrinkage"}],"correct": "B","explanation": "Apoptosis is a non-inflammatory, programmed form of cell death."},{"id": 3592,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Hard","question": "Which protein family regulates the intrinsic pathway of apoptosis?","options": [{"key": "A","text": "NF-kB"},{"key": "B","text": "Bcl-2 family"},{"key": "C","text": "TNF receptors"},{"key": "D","text": "Caspases only"}],"correct": "B","explanation": "Bcl-2 family proteins control mitochondrial outer membrane permeabilization in intrinsic apoptosis."},{"id": 3593,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hydropic swelling (cellular swelling) occurs due to failure of which pump?","options": [{"key": "A","text": "Proton pump"},{"key": "B","text": "Calcium pump"},{"key": "C","text": "Potassium channel"},{"key": "D","text": "Na+/K+ ATPase"}],"correct": "D","explanation": "ATP depletion impairs Na+/K+ ATPase causing intracellular Na+ and water accumulation."},{"id": 3594,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Metaplasia is best defined as:","options": [{"key": "A","text": "Decrease in cell number"},{"key": "B","text": "Increase in cell size"},{"key": "C","text": "Reversible change of one differentiated cell type to another"},{"key": "D","text": "Irreversible cell death"}],"correct": "C","explanation": "Metaplasia is an adaptive, reversible replacement of one mature cell type by another."},{"id": 3595,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Squamous metaplasia of respiratory epithelium is commonly seen in:","options": [{"key": "A","text": "Chronic smokers"},{"key": "B","text": "Vitamin C deficiency"},{"key": "C","text": "Iron deficiency"},{"key": "D","text": "Vitamin A deficiency"}],"correct": "A","explanation": "Chronic irritation from smoking causes ciliated columnar epithelium to change to squamous type."},{"id": 3596,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Barrett's esophagus is an example of:","options": [{"key": "A","text": "Hyperplasia"},{"key": "B","text": "Squamous metaplasia"},{"key": "C","text": "Dysplasia only"},{"key": "D","text": "Columnar (glandular) metaplasia"}],"correct": "D","explanation": "Chronic acid reflux causes squamous to columnar metaplasia in the lower esophagus."},{"id": 3597,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Hypertrophy of skeletal muscle in athletes occurs due to:","options": [{"key": "A","text": "Atrophy of fibers"},{"key": "B","text": "Increase in cell size"},{"key": "C","text": "Increase in cell number"},{"key": "D","text": "Metaplasia"}],"correct": "B","explanation": "Physiological hypertrophy results from increased size of individual muscle fibers, not number."},{"id": 3598,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Disuse atrophy of muscle, as seen after prolonged immobilization, is due to:","options": [{"key": "A","text": "Decreased protein synthesis and increased degradation"},{"key": "B","text": "Increased innervation"},{"key": "C","text": "Hyperplasia of fibers"},{"key": "D","text": "Increased blood supply"}],"correct": "A","explanation": "Disuse leads to reduced protein synthesis and enhanced ubiquitin-proteasome mediated degradation."},{"id": 3599,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Dystrophic calcification occurs in:","options": [{"key": "A","text": "Hypercalcemia with normal tissue"},{"key": "B","text": "Normal calcium metabolism with dead tissue"},{"key": "C","text": "Hyperparathyroidism"},{"key": "D","text": "Vitamin D toxicity"}],"correct": "B","explanation": "Dystrophic calcification occurs in dead/damaged tissue despite normal serum calcium levels."},{"id": 3600,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Metastatic calcification is associated with:","options": [{"key": "A","text": "Aging tendons"},{"key": "B","text": "Hypercalcemia"},{"key": "C","text": "Local tissue necrosis only"},{"key": "D","text": "Normal calcium levels"}],"correct": "B","explanation": "Metastatic calcification occurs in normal tissue due to elevated serum calcium levels."},{"id": 3601,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Free radical injury to cells is mediated mainly through:","options": [{"key": "A","text": "Protein synthesis inhibition"},{"key": "B","text": "Lipid peroxidation of membranes"},{"key": "C","text": "Increased ATP production"},{"key": "D","text": "Decreased calcium influx"}],"correct": "B","explanation": "Reactive oxygen species cause lipid peroxidation, damaging cell membranes."},{"id": 3602,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which of the following is an antioxidant enzyme protecting against free radical injury?","options": [{"key": "A","text": "Superoxide dismutase"},{"key": "B","text": "Alkaline phosphatase"},{"key": "C","text": "Amylase"},{"key": "D","text": "Lipase"}],"correct": "A","explanation": "SOD converts superoxide radicals to hydrogen peroxide, reducing oxidative damage."},{"id": 3603,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Pyknosis refers to:","options": [{"key": "A","text": "Nuclear fragmentation"},{"key": "B","text": "Cytoplasmic swelling"},{"key": "C","text": "Nuclear dissolution"},{"key": "D","text": "Nuclear shrinkage with chromatin condensation"}],"correct": "D","explanation": "Pyknosis is irreversible nuclear condensation seen in necrosis and apoptosis."},{"id": 3604,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Karyorrhexis refers to:","options": [{"key": "A","text": "Nuclear swelling"},{"key": "B","text": "Fading of nucleus"},{"key": "C","text": "Nuclear fragmentation into small pieces"},{"key": "D","text": "Chromatin condensation only"}],"correct": "C","explanation": "Karyorrhexis follows pyknosis, with fragmentation of the condensed nucleus."},{"id": 3605,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Gangrenous necrosis with superadded bacterial infection is termed:","options": [{"key": "A","text": "Wet gangrene"},{"key": "B","text": "Fibrinoid necrosis"},{"key": "C","text": "Gas gangrene"},{"key": "D","text": "Dry gangrene"}],"correct": "A","explanation": "Wet gangrene occurs when necrotic tissue is infected by putrefactive bacteria."},{"id": 3606,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Gas gangrene is classically caused by:","options": [{"key": "A","text": "Clostridium perfringens"},{"key": "B","text": "Staphylococcus aureus"},{"key": "C","text": "E. coli"},{"key": "D","text": "Streptococcus pyogenes"}],"correct": "A","explanation": "Clostridium perfringens produces gas-forming toxins causing gas gangrene."},{"id": 3607,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Hard","question": "Fibrinoid necrosis is typically seen in:","options": [{"key": "A","text": "Tuberculosis"},{"key": "B","text": "Brain infarcts"},{"key": "C","text": "Immune complex-mediated vasculitis"},{"key": "D","text": "Fat necrosis"}],"correct": "C","explanation": "Fibrinoid necrosis results from antigen-antibody deposition in vessel walls, seen in vasculitis/malignant hypertension."},{"id": 3608,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "The most important intracellular target of ischemic cell injury is:","options": [{"key": "A","text": "Golgi body"},{"key": "B","text": "Nucleus"},{"key": "C","text": "Ribosome"},{"key": "D","text": "Mitochondria"}],"correct": "D","explanation": "Mitochondrial dysfunction with ATP depletion is central to ischemic cell injury."},{"id": 3609,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Reversible cell injury includes:","options": [{"key": "A","text": "Membrane rupture"},{"key": "B","text": "Cellular swelling and fatty change"},{"key": "C","text": "Nuclear pyknosis"},{"key": "D","text": "Karyolysis"}],"correct": "B","explanation": "Cellular/hydropic swelling and fatty change are reversible changes seen in early injury."},{"id": 3610,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Which is the hallmark of irreversible cell injury?","options": [{"key": "A","text": "Ribosomal detachment"},{"key": "B","text": "Membrane damage with calcium influx"},{"key": "C","text": "Fatty change"},{"key": "D","text": "Mild ATP depletion"}],"correct": "B","explanation": "Severe membrane damage causing massive calcium influx marks irreversibility."},{"id": 3611,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Atrophy due to loss of nerve supply is termed:","options": [{"key": "A","text": "Denervation atrophy"},{"key": "B","text": "Nutritional atrophy"},{"key": "C","text": "Physiological atrophy"},{"key": "D","text": "Pressure atrophy"}],"correct": "A","explanation": "Denervation atrophy occurs following loss of neural stimulation to muscle, as in peripheral nerve injury."},{"id": 3612,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Compensatory hyperplasia is best exemplified by:","options": [{"key": "A","text": "Prostatic hyperplasia"},{"key": "B","text": "Liver regeneration after partial hepatectomy"},{"key": "C","text": "Endometrial hyperplasia"},{"key": "D","text": "Muscle hypertrophy in bodybuilders"}],"correct": "B","explanation": "Liver regeneration after resection is a classic compensatory hyperplasia example."},{"id": 3613,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Autophagy in cell injury refers to:","options": [{"key": "A","text": "Cell division"},{"key": "B","text": "Self-digestion of cell components via lysosomes"},{"key": "C","text": "Nuclear fragmentation"},{"key": "D","text": "Cell eating another cell"}],"correct": "B","explanation": "Autophagy is a survival mechanism where cells digest their own organelles for nutrients under stress."},{"id": 3614,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Which of the following best distinguishes apoptosis from necrosis?","options": [{"key": "A","text": "Absence of inflammation"},{"key": "B","text": "Loss of membrane integrity"},{"key": "C","text": "Cell swelling"},{"key": "D","text": "Random DNA degradation"}],"correct": "A","explanation": "Apoptosis does not elicit inflammation as membrane integrity is initially preserved."},{"id": 3615,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which chemical mediator is primarily responsible for vasodilation in acute inflammation?","options": [{"key": "A","text": "Bradykinin"},{"key": "B","text": "Histamine"},{"key": "C","text": "Prostaglandins"},{"key": "D","text": "All of the above"}],"correct": "D","explanation": "Histamine, bradykinin and prostaglandins all contribute to vasodilation in acute inflammation."},{"id": 3616,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The cardinal sign 'rubor' in acute inflammation is due to:","options": [{"key": "A","text": "Fibrin deposition"},{"key": "B","text": "Increased vascular permeability"},{"key": "C","text": "Vasodilation causing increased blood flow"},{"key": "D","text": "Leukocyte infiltration"}],"correct": "C","explanation": "Rubor (redness) results from vasodilation increasing blood flow to the site."},{"id": 3617,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The first cell type to arrive at the site of acute inflammation is:","options": [{"key": "A","text": "Macrophage"},{"key": "B","text": "Lymphocyte"},{"key": "C","text": "Eosinophil"},{"key": "D","text": "Neutrophil"}],"correct": "D","explanation": "Neutrophils are the first responders, arriving within hours of acute inflammation."},{"id": 3618,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Margination and rolling of leukocytes is mediated by:","options": [{"key": "A","text": "Integrins"},{"key": "B","text": "Cadherins"},{"key": "C","text": "Selectins"},{"key": "D","text": "Chemokines"}],"correct": "C","explanation": "Selectins on endothelium mediate the initial rolling of leukocytes along vessel walls."},{"id": 3619,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Firm adhesion of leukocytes to endothelium is mediated by:","options": [{"key": "A","text": "Cadherins"},{"key": "B","text": "Selectins"},{"key": "C","text": "Collagen"},{"key": "D","text": "Integrins"}],"correct": "D","explanation": "Integrins on leukocytes bind ICAM-1/VCAM-1 for firm adhesion before transmigration."},{"id": 3620,"subject": "Pathology","topic": "Infectious Disease","difficulty": "Medium","question": "Chemotaxis of neutrophils toward bacteria is guided by:","options": [{"key": "A","text": "Fibrinogen"},{"key": "B","text": "Histamine"},{"key": "C","text": "C5a and leukotriene B4"},{"key": "D","text": "Serotonin"}],"correct": "C","explanation": "C5a and LTB4 are potent chemotactic factors for neutrophils."},{"id": 3621,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which is the predominant cell in chronic inflammation?","options": [{"key": "A","text": "Macrophage"},{"key": "B","text": "Neutrophil"},{"key": "C","text": "Eosinophil"},{"key": "D","text": "Basophil"}],"correct": "A","explanation": "Macrophages and lymphocytes dominate chronic inflammatory infiltrates."},{"id": 3622,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Granuloma formation is a classic feature of which type of inflammation?","options": [{"key": "A","text": "Chronic granulomatous"},{"key": "B","text": "Serous"},{"key": "C","text": "Acute suppurative"},{"key": "D","text": "Fibrinous"}],"correct": "A","explanation": "Granulomas, collections of epithelioid macrophages, characterize chronic granulomatous inflammation like TB."},{"id": 3623,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Epithelioid cells in a granuloma are derived from:","options": [{"key": "A","text": "Lymphocytes"},{"key": "B","text": "Neutrophils"},{"key": "C","text": "Fibroblasts"},{"key": "D","text": "Activated macrophages"}],"correct": "D","explanation": "Macrophages transform into epithelioid cells under chronic antigenic stimulation."},{"id": 3624,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Langhans giant cells are formed by fusion of:","options": [{"key": "A","text": "Fibroblasts"},{"key": "B","text": "Neutrophils"},{"key": "C","text": "Epithelioid cells/macrophages"},{"key": "D","text": "Lymphocytes"}],"correct": "C","explanation": "Multiple epithelioid macrophages fuse to form multinucleated Langhans giant cells."},{"id": 3625,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which prostaglandin is responsible for fever during inflammation?","options": [{"key": "A","text": "PGI2"},{"key": "B","text": "PGD2"},{"key": "C","text": "Thromboxane A2"},{"key": "D","text": "PGE2"}],"correct": "D","explanation": "PGE2 acts on the hypothalamus to reset the thermoregulatory set point, causing fever."},{"id": 3626,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pus is a collection of:","options": [{"key": "A","text": "Fibrin only"},{"key": "B","text": "Dead neutrophils, bacteria and necrotic debris"},{"key": "C","text": "Lymphocytes only"},{"key": "D","text": "Plasma proteins only"}],"correct": "B","explanation": "Purulent exudate (pus) contains dead neutrophils, necrotic tissue, and microbes."},{"id": 3627,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "An abscess is best defined as:","options": [{"key": "A","text": "Localized collection of pus"},{"key": "B","text": "Diffuse spread of pus in tissue"},{"key": "C","text": "Fibrous scar formation"},{"key": "D","text": "Serous fluid collection"}],"correct": "A","explanation": "An abscess is a localized, walled-off collection of pus within a tissue."},{"id": 3628,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which acute phase reactant is used clinically to monitor inflammation?","options": [{"key": "A","text": "Hemoglobin"},{"key": "B","text": "Albumin"},{"key": "C","text": "Amylase"},{"key": "D","text": "C-reactive protein"}],"correct": "D","explanation": "CRP rises rapidly in inflammation and is a widely used marker to monitor disease activity."},{"id": 3629,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Erythrocyte sedimentation rate (ESR) rises in inflammation mainly due to:","options": [{"key": "A","text": "Decreased globulins"},{"key": "B","text": "Decreased fibrinogen"},{"key": "C","text": "Increased albumin"},{"key": "D","text": "Increased fibrinogen causing rouleaux formation"}],"correct": "D","explanation": "Elevated fibrinogen promotes RBC rouleaux formation, increasing ESR."},{"id": 3630,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Serous inflammation is characterized by:","options": [{"key": "A","text": "Pus formation"},{"key": "B","text": "Thin, protein-poor fluid exudation"},{"key": "C","text": "Fibrin-rich exudate"},{"key": "D","text": "Necrosis"}],"correct": "B","explanation": "Serous inflammation produces a watery, protein-poor effusion, as in a blister."},{"id": 3631,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Fibrinous inflammation is commonly seen in which condition?","options": [{"key": "A","text": "Common cold"},{"key": "B","text": "Pericarditis"},{"key": "C","text": "Fracture healing"},{"key": "D","text": "Osteoarthritis"}],"correct": "B","explanation": "Fibrinous pericarditis, with a fibrin-rich exudate, occurs after MI or uremia."},{"id": 3632,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which interleukin is a major mediator of fever and acute phase response?","options": [{"key": "A","text": "IL-4"},{"key": "B","text": "IL-2"},{"key": "C","text": "IL-10"},{"key": "D","text": "IL-6"}],"correct": "D","explanation": "IL-6 stimulates hepatic acute phase protein synthesis and contributes to fever."},{"id": 3633,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Resolution of acute inflammation is favored by:","options": [{"key": "A","text": "Persistent infection"},{"key": "B","text": "Foreign body presence"},{"key": "C","text": "Minimal tissue damage and regenerative capacity"},{"key": "D","text": "Extensive necrosis"}],"correct": "C","explanation": "Resolution occurs when tissue damage is limited and the tissue can regenerate to original structure."},{"id": 3634,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Chronic granulomatous inflammation with caseation necrosis is a hallmark of:","options": [{"key": "A","text": "Rheumatoid arthritis"},{"key": "B","text": "Leprosy"},{"key": "C","text": "Tuberculosis"},{"key": "D","text": "Sarcoidosis"}],"correct": "C","explanation": "Caseating granulomas are characteristic of tuberculosis, unlike non-caseating granulomas in sarcoidosis."},{"id": 3635,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Wound healing by primary intention occurs in wounds that are:","options": [{"key": "A","text": "Left open to granulate"},{"key": "B","text": "Infected wounds"},{"key": "C","text": "Contaminated with tissue loss"},{"key": "D","text": "Clean, sutured surgical incisions"}],"correct": "D","explanation": "Primary intention healing occurs in clean, approximated wound edges like surgical incisions."},{"id": 3636,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Secondary intention healing differs from primary by:","options": [{"key": "A","text": "Faster healing"},{"key": "B","text": "No scar formation"},{"key": "C","text": "Presence of large tissue defect and granulation tissue"},{"key": "D","text": "Absence of inflammation"}],"correct": "C","explanation": "Secondary intention involves large gaps requiring extensive granulation tissue and wound contraction."},{"id": 3637,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Granulation tissue is composed mainly of:","options": [{"key": "A","text": "Dead neutrophils only"},{"key": "B","text": "New capillaries, fibroblasts and inflammatory cells"},{"key": "C","text": "Mature collagen only"},{"key": "D","text": "Adipose tissue"}],"correct": "B","explanation": "Granulation tissue is pink, granular tissue with proliferating capillaries and fibroblasts."},{"id": 3638,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Which cell type is primarily responsible for wound contraction?","options": [{"key": "A","text": "Myofibroblast"},{"key": "B","text": "Fibroblast"},{"key": "C","text": "Endothelial cell"},{"key": "D","text": "Neutrophil"}],"correct": "A","explanation": "Myofibroblasts, containing actin filaments, contract the wound edges together."},{"id": 3639,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "The predominant collagen type in early wound healing (granulation tissue) is:","options": [{"key": "A","text": "Type III"},{"key": "B","text": "Type IV"},{"key": "C","text": "Type II"},{"key": "D","text": "Type I"}],"correct": "A","explanation": "Type III collagen predominates early and is later replaced by stronger Type I collagen."},{"id": 3640,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Mature scar tissue is composed predominantly of which collagen type?","options": [{"key": "A","text": "Type II"},{"key": "B","text": "Type IV"},{"key": "C","text": "Type I"},{"key": "D","text": "Type III"}],"correct": "C","explanation": "Remodeling replaces Type III with the stronger, more organized Type I collagen."},{"id": 3641,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Which growth factor is most important for angiogenesis in wound healing?","options": [{"key": "A","text": "ACTH"},{"key": "B","text": "TSH"},{"key": "C","text": "VEGF"},{"key": "D","text": "Insulin"}],"correct": "C","explanation": "Vascular endothelial growth factor (VEGF) drives new capillary formation during repair."},{"id": 3642,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Labile cells, which continuously regenerate, include:","options": [{"key": "A","text": "Cardiac myocytes"},{"key": "B","text": "Epidermal cells"},{"key": "C","text": "Skeletal muscle"},{"key": "D","text": "Neurons"}],"correct": "B","explanation": "Epidermis and GI epithelium are labile tissues with continuous cell turnover."},{"id": 3643,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Stable (quiescent) cells that can re-enter the cell cycle when needed include:","options": [{"key": "A","text": "Neurons"},{"key": "B","text": "Hepatocytes"},{"key": "C","text": "Skin epithelium"},{"key": "D","text": "Bone marrow cells"}],"correct": "B","explanation": "Hepatocytes and renal tubular cells are stable, capable of regeneration on demand."},{"id": 3644,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Permanent cells that cannot regenerate after injury include:","options": [{"key": "A","text": "Epidermis"},{"key": "B","text": "Intestinal epithelium"},{"key": "C","text": "Hepatocytes"},{"key": "D","text": "Neurons and cardiac myocytes"}],"correct": "D","explanation": "Neurons and cardiac myocytes are permanent cells, replaced by scar tissue after injury."},{"id": 3645,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Vitamin C deficiency impairs wound healing primarily by affecting:","options": [{"key": "A","text": "Fibrinogen synthesis"},{"key": "B","text": "Epithelialization only"},{"key": "C","text": "Collagen hydroxylation"},{"key": "D","text": "Platelet aggregation"}],"correct": "C","explanation": "Vitamin C is essential as a cofactor for proline/lysine hydroxylation in collagen synthesis."},{"id": 3646,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Which factor delays wound healing in diabetic patients?","options": [{"key": "A","text": "Excess vitamin C"},{"key": "B","text": "Impaired neutrophil function and microangiopathy"},{"key": "C","text": "Increased blood supply"},{"key": "D","text": "Increased collagen synthesis"}],"correct": "B","explanation": "Diabetes impairs leukocyte function and causes microvascular disease, delaying healing."},{"id": 3647,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Keloid formation results from:","options": [{"key": "A","text": "Poor vascular supply"},{"key": "B","text": "Wound infection only"},{"key": "C","text": "Deficient collagen synthesis"},{"key": "D","text": "Excessive collagen deposition beyond wound margins"}],"correct": "D","explanation": "Keloids show excess collagen extending beyond the original wound boundary."},{"id": 3648,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hypertrophic scar differs from keloid in that it:","options": [{"key": "A","text": "Occurs only in old age"},{"key": "B","text": "Extends beyond wound margins"},{"key": "C","text": "Remains within the wound margins"},{"key": "D","text": "Never regresses"}],"correct": "C","explanation": "Hypertrophic scars stay confined to the wound site and may regress over time, unlike keloids."},{"id": 3649,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Dehiscence of a surgical wound refers to:","options": [{"key": "A","text": "Contracture"},{"key": "B","text": "Rupture/separation of a wound along suture line"},{"key": "C","text": "Excess scar formation"},{"key": "D","text": "Keloid formation"}],"correct": "B","explanation": "Wound dehiscence is mechanical failure/splitting of a healing wound, often due to infection or poor nutrition."},{"id": 3650,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Which vitamin deficiency is linked to poor collagen cross-linking and wound dehiscence?","options": [{"key": "A","text": "Vitamin D"},{"key": "B","text": "Vitamin C"},{"key": "C","text": "Vitamin A"},{"key": "D","text": "Vitamin K"}],"correct": "B","explanation": "Vitamin C deficiency (scurvy) impairs collagen hydroxylation leading to weak, poorly healing wounds."},{"id": 3651,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Hard","question": "Zinc deficiency in wound healing primarily affects:","options": [{"key": "A","text": "Bone mineralization"},{"key": "B","text": "Epithelialization and collagen synthesis"},{"key": "C","text": "Platelet function"},{"key": "D","text": "RBC production"}],"correct": "B","explanation": "Zinc is a cofactor for metalloproteinases and DNA/RNA polymerases essential for epithelial regeneration."},{"id": 3652,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Contracture, an exaggerated wound contraction causing deformity, is classically seen after:","options": [{"key": "A","text": "Minor abrasions"},{"key": "B","text": "Bruises"},{"key": "C","text": "Clean surgical incisions"},{"key": "D","text": "Burns"}],"correct": "D","explanation": "Burn wounds are prone to excessive contraction causing joint contractures, important in physiotherapy rehab."},{"id": 3653,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "The phase of wound healing characterized by neutrophil and macrophage infiltration is:","options": [{"key": "A","text": "Hemostasis"},{"key": "B","text": "Proliferative phase"},{"key": "C","text": "Inflammatory phase"},{"key": "D","text": "Remodeling phase"}],"correct": "C","explanation": "The inflammatory phase (day 0-3) involves neutrophil then macrophage infiltration to clear debris."},{"id": 3654,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "The remodeling phase of wound healing can last up to:","options": [{"key": "A","text": "24 hours"},{"key": "B","text": "1-2 years"},{"key": "C","text": "1 week"},{"key": "D","text": "1 month only"}],"correct": "B","explanation": "Remodeling, involving collagen reorganization and cross-linking, can continue for up to 1-2 years."},{"id": 3655,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which cell releases growth factors like PDGF and TGF-beta during the hemostasis phase?","options": [{"key": "A","text": "Neutrophils"},{"key": "B","text": "Platelets"},{"key": "C","text": "Erythrocytes"},{"key": "D","text": "Lymphocytes"}],"correct": "B","explanation": "Platelets, upon degranulation, release PDGF and TGF-beta initiating the repair cascade."},{"id": 3656,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Chronic non-healing wounds (e.g., diabetic ulcers) are commonly stuck in which phase?","options": [{"key": "A","text": "Prolonged inflammatory phase"},{"key": "B","text": "Epithelialization only"},{"key": "C","text": "Remodeling"},{"key": "D","text": "Hemostasis"}],"correct": "A","explanation": "Chronic wounds often remain in a persistent inflammatory state, preventing progression to proliferation."},{"id": 3657,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Which of the following best promotes tensile strength recovery of a wound over time?","options": [{"key": "A","text": "Persistent neutrophil infiltration"},{"key": "B","text": "Increase in collagen amount and cross-linking"},{"key": "C","text": "Decrease in fibroblast number"},{"key": "D","text": "Increase in water content"}],"correct": "B","explanation": "Tensile strength increases as collagen is deposited and cross-linked during remodeling, not just its quantity."},{"id": 3658,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Hard","question": "At what post-wound week does tensile strength typically reach about 70-80% of unwounded skin (maximum)?","options": [{"key": "A","text": "3 weeks"},{"key": "B","text": "24 hours"},{"key": "C","text": "1 week"},{"key": "D","text": "6-12 months"}],"correct": "D","explanation": "Wound tensile strength continues improving up to 70-80% by several months due to ongoing collagen remodeling."},{"id": 3659,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Fibroblast proliferation and collagen synthesis predominate in which phase of healing?","options": [{"key": "A","text": "Proliferative phase"},{"key": "B","text": "Hemostasis"},{"key": "C","text": "Inflammatory phase"},{"key": "D","text": "Maturation only"}],"correct": "A","explanation": "The proliferative phase (day 3-3 weeks) features fibroblast activity, angiogenesis, and granulation tissue formation."},{"id": 3660,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "A wound healing complication where an epithelial-lined tract forms between two hollow organs is called:","options": [{"key": "A","text": "Contracture"},{"key": "B","text": "Fistula"},{"key": "C","text": "Ulcer"},{"key": "D","text": "Keloid"}],"correct": "B","explanation": "A fistula is an abnormal epithelialized communication between organs or organ and skin."},{"id": 3661,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Poor wound healing in a malnourished (protein-deficient) patient is mainly due to:","options": [{"key": "A","text": "Excess granulation tissue"},{"key": "B","text": "Increased angiogenesis"},{"key": "C","text": "Reduced collagen synthesis and fibroblast proliferation"},{"key": "D","text": "Increased scar strength"}],"correct": "C","explanation": "Protein deficiency impairs synthesis of collagen and other structural proteins needed for repair."},{"id": 3662,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Steroid use delays wound healing primarily by:","options": [{"key": "A","text": "Increasing granulation tissue"},{"key": "B","text": "Inhibiting inflammation and fibroblast proliferation"},{"key": "C","text": "Increasing angiogenesis"},{"key": "D","text": "Enhancing collagen synthesis"}],"correct": "B","explanation": "Corticosteroids suppress inflammatory response and fibroblast activity, impairing healing."},{"id": 3663,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Hard","question": "Which matrix metalloproteinase activity is essential during wound remodeling?","options": [{"key": "A","text": "Synthesizes new DNA"},{"key": "B","text": "Forms platelet plug"},{"key": "C","text": "Degrades and remodels excess collagen/ECM"},{"key": "D","text": "Produces hemoglobin"}],"correct": "C","explanation": "MMPs degrade excess ECM components allowing organized collagen remodeling and scar maturation."},{"id": 3664,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "The best clinical indicator of adequate wound healing progress in physiotherapy practice is:","options": [{"key": "A","text": "Pain intensity alone"},{"key": "B","text": "Wound size reduction and granulation tissue appearance"},{"key": "C","text": "Patient's age"},{"key": "D","text": "Body temperature"}],"correct": "B","explanation": "Progressive wound contraction and healthy granulation tissue indicate satisfactory healing progress."},{"id": 3665,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Edema due to increased hydrostatic pressure is classically seen in:","options": [{"key": "A","text": "Nephrotic syndrome"},{"key": "B","text": "Lymphatic obstruction"},{"key": "C","text": "Congestive heart failure"},{"key": "D","text": "Liver cirrhosis with hypoalbuminemia"}],"correct": "C","explanation": "CHF raises venous hydrostatic pressure, pushing fluid into the interstitium."},{"id": 3666,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Edema due to decreased plasma oncotic pressure is seen in:","options": [{"key": "A","text": "Nephrotic syndrome"},{"key": "B","text": "Right heart failure"},{"key": "C","text": "Deep vein thrombosis"},{"key": "D","text": "Filariasis"}],"correct": "A","explanation": "Nephrotic syndrome causes hypoalbuminemia, lowering oncotic pressure and causing generalized edema."},{"id": 3667,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Lymphedema following mastectomy with axillary lymph node dissection results from:","options": [{"key": "A","text": "Increased hydrostatic pressure"},{"key": "B","text": "Lymphatic obstruction"},{"key": "C","text": "Decreased oncotic pressure"},{"key": "D","text": "Sodium retention"}],"correct": "B","explanation": "Removal of lymph nodes obstructs lymphatic drainage, causing localized lymphedema of the arm."},{"id": 3668,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pitting edema is best explained by:","options": [{"key": "A","text": "Fibrous tissue proliferation"},{"key": "B","text": "Fluid accumulation in loose connective tissue"},{"key": "C","text": "Muscle hypertrophy"},{"key": "D","text": "Bone thickening"}],"correct": "B","explanation": "Pitting occurs as fluid is displaced from loose interstitial tissue when pressure is applied."},{"id": 3669,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Non-pitting edema is characteristically seen in:","options": [{"key": "A","text": "Cardiac failure"},{"key": "B","text": "Nephrotic syndrome"},{"key": "C","text": "DVT"},{"key": "D","text": "Myxedema (hypothyroidism)"}],"correct": "D","explanation": "Myxedema causes accumulation of mucopolysaccharides producing firm, non-pitting edema."},{"id": 3670,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Virchow's triad for thrombosis includes all EXCEPT:","options": [{"key": "A","text": "Hypercoagulability"},{"key": "B","text": "Stasis of blood flow"},{"key": "C","text": "Increased oncotic pressure"},{"key": "D","text": "Endothelial injury"}],"correct": "C","explanation": "Virchow's triad comprises endothelial injury, abnormal blood flow (stasis/turbulence), and hypercoagulability."},{"id": 3671,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Deep vein thrombosis most commonly occurs due to:","options": [{"key": "A","text": "Venous stasis (e.g., prolonged immobilization)"},{"key": "B","text": "Arterial injury"},{"key": "C","text": "High shear stress"},{"key": "D","text": "Arterial hypertension"}],"correct": "A","explanation": "Prolonged immobilization causes venous stasis, a major risk factor for DVT."},{"id": 3672,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Prolonged bed rest/immobilization predisposes to DVT primarily through which mechanism of Virchow's triad?","options": [{"key": "A","text": "Hypercoagulability"},{"key": "B","text": "Turbulence"},{"key": "C","text": "Endothelial injury"},{"key": "D","text": "Stasis of blood flow"}],"correct": "D","explanation": "Immobility reduces venous return causing blood stasis, a key DVT risk factor relevant to physiotherapy patients."},{"id": 3673,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "A line of Zahn is a microscopic feature that helps differentiate:","options": [{"key": "A","text": "White from red infarct"},{"key": "B","text": "Antemortem thrombus from postmortem clot"},{"key": "C","text": "Fresh from old infarct"},{"key": "D","text": "Arterial from venous thrombus"}],"correct": "B","explanation": "Alternating layers of platelets/fibrin and RBCs (lines of Zahn) indicate an antemortem thrombus."},{"id": 3674,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The most common source of pulmonary embolism is:","options": [{"key": "A","text": "Right atrium"},{"key": "B","text": "Cerebral veins"},{"key": "C","text": "Pelvic veins only"},{"key": "D","text": "Deep leg veins"}],"correct": "D","explanation": "Thrombi from deep veins of the leg (femoral, popliteal) commonly embolize to the lungs."},{"id": 3675,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "A fat embolism classically occurs after:","options": [{"key": "A","text": "Long bone fractures"},{"key": "B","text": "Renal failure"},{"key": "C","text": "Cerebral hemorrhage"},{"key": "D","text": "Myocardial infarction"}],"correct": "A","explanation": "Fracture of long bones releases marrow fat globules into circulation causing fat embolism syndrome."},{"id": 3676,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Amniotic fluid embolism occurs during:","options": [{"key": "A","text": "Air travel"},{"key": "B","text": "Deep sea diving"},{"key": "C","text": "Labor and delivery"},{"key": "D","text": "Long bone fracture"}],"correct": "C","explanation": "Amniotic fluid entering maternal circulation during labor/delivery can cause a rare, severe embolism."},{"id": 3677,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Decompression sickness (Caisson disease) results from embolism by:","options": [{"key": "A","text": "Amniotic fluid"},{"key": "B","text": "Fat globules"},{"key": "C","text": "Nitrogen gas bubbles"},{"key": "D","text": "Cholesterol crystals"}],"correct": "C","explanation": "Rapid ascent from high pressure environments causes dissolved nitrogen to form gas emboli."},{"id": 3678,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "White (anemic) infarcts typically occur in organs with:","options": [{"key": "A","text": "Dual blood supply"},{"key": "B","text": "Single (end-arterial) blood supply and solid consistency"},{"key": "C","text": "Extensive collateral circulation"},{"key": "D","text": "Loose spongy tissue"}],"correct": "B","explanation": "Solid organs with single arterial supply (heart, kidney, spleen) develop white infarcts."},{"id": 3679,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Red (hemorrhagic) infarcts are typically seen in:","options": [{"key": "A","text": "Spleen"},{"key": "B","text": "Kidney"},{"key": "C","text": "Heart"},{"key": "D","text": "Lung (dual circulation, loose tissue)"}],"correct": "D","explanation": "Organs with dual blood supply or loose tissue, like lungs, develop red hemorrhagic infarcts."},{"id": 3680,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which type of shock results from severe blood/fluid loss?","options": [{"key": "A","text": "Septic shock"},{"key": "B","text": "Neurogenic shock"},{"key": "C","text": "Hypovolemic shock"},{"key": "D","text": "Cardiogenic shock"}],"correct": "C","explanation": "Hypovolemic shock occurs due to reduced circulating blood volume from hemorrhage or fluid loss."},{"id": 3681,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Cardiogenic shock occurs due to:","options": [{"key": "A","text": "Spinal cord injury"},{"key": "B","text": "Pump failure of the heart (e.g., massive MI)"},{"key": "C","text": "Blood loss"},{"key": "D","text": "Sepsis"}],"correct": "B","explanation": "Cardiogenic shock results from the heart's inability to pump sufficient blood, e.g., after large MI."},{"id": 3682,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neurogenic shock following spinal cord injury occurs due to:","options": [{"key": "A","text": "Blood loss"},{"key": "B","text": "Loss of sympathetic vascular tone causing vasodilation"},{"key": "C","text": "Cardiac pump failure"},{"key": "D","text": "Bacterial toxins"}],"correct": "B","explanation": "Spinal injury disrupts sympathetic outflow, causing widespread vasodilation and hypotension — highly relevant in physiotherapy/rehab settings."},{"id": 3683,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Septic shock is primarily mediated by:","options": [{"key": "A","text": "Cardiac muscle damage"},{"key": "B","text": "Nerve transection"},{"key": "C","text": "Bacterial endotoxins triggering massive vasodilation"},{"key": "D","text": "Direct blood loss"}],"correct": "C","explanation": "Endotoxin-triggered cytokine release causes widespread vasodilation and distributive shock."},{"id": 3684,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The earliest compensatory response in hypovolemic shock is:","options": [{"key": "A","text": "Tachycardia and vasoconstriction"},{"key": "B","text": "Vasodilation"},{"key": "C","text": "Renal failure"},{"key": "D","text": "Bradycardia"}],"correct": "A","explanation": "Sympathetic activation causes tachycardia and peripheral vasoconstriction to maintain perfusion."},{"id": 3685,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Irreversible shock is characterized by:","options": [{"key": "A","text": "Reversible hypotension"},{"key": "B","text": "Complete recovery with fluids"},{"key": "C","text": "Multi-organ failure and cell death"},{"key": "D","text": "Mild tachycardia only"}],"correct": "C","explanation": "In the irreversible stage, prolonged hypoperfusion leads to widespread cellular injury and organ failure."},{"id": 3686,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which of the following best describes 'stasis' as a component of Virchow's triad relevant to bedridden/paralyzed patients?","options": [{"key": "A","text": "Slow or turbulent blood flow promoting clot formation"},{"key": "B","text": "Decreased fibrinogen"},{"key": "C","text": "Fast arterial flow"},{"key": "D","text": "Increased platelet destruction"}],"correct": "A","explanation": "Reduced venous flow in immobile patients allows clotting factors to accumulate, promoting thrombosis."},{"id": 3687,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hyperemia differs from congestion in that hyperemia is:","options": [{"key": "A","text": "Seen only in chronic conditions"},{"key": "B","text": "Always pathological"},{"key": "C","text": "A passive process due to impaired venous outflow"},{"key": "D","text": "An active process due to arteriolar dilation"}],"correct": "D","explanation": "Hyperemia is active (increased arterial inflow, e.g., exercising muscle), while congestion is passive venous outflow impairment."},{"id": 3688,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Chronic passive congestion of the lungs, as in left heart failure, leads to the presence of:","options": [{"key": "A","text": "Reed-Sternberg cells"},{"key": "B","text": "Foam cells only"},{"key": "C","text": "Heart failure cells (hemosiderin-laden macrophages)"},{"key": "D","text": "Langhans giant cells"}],"correct": "C","explanation": "Chronic pulmonary congestion causes microhemorrhages, with macrophages engulfing hemosiderin forming 'heart failure cells'."},{"id": 3689,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Petechiae are best described as:","options": [{"key": "A","text": "Localized swelling"},{"key": "B","text": "Pinpoint hemorrhages in skin/mucosa"},{"key": "C","text": "Venous thrombi"},{"key": "D","text": "Large bruises"}],"correct": "B","explanation": "Petechiae are 1-2mm hemorrhagic spots often due to thrombocytopenia or vasculitis."},{"id": 3690,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "A hematoma refers to:","options": [{"key": "A","text": "Accumulation of blood within a tissue forming a mass"},{"key": "B","text": "Superficial capillary dilation"},{"key": "C","text": "Bruise under 1cm"},{"key": "D","text": "Small pinpoint hemorrhage"}],"correct": "A","explanation": "Hematoma is a larger, localized collection of extravasated blood within tissue."},{"id": 3691,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "DIC (Disseminated Intravascular Coagulation) is characterized by:","options": [{"key": "A","text": "Localized thrombus formation only"},{"key": "B","text": "Pure hypercoagulable state without bleeding"},{"key": "C","text": "Widespread microthrombi followed by consumption coagulopathy and bleeding"},{"key": "D","text": "Isolated bleeding only"}],"correct": "C","explanation": "DIC involves simultaneous widespread clotting that consumes platelets/factors, leading to subsequent bleeding."},{"id": 3692,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which of the following increases risk of venous thromboembolism in a post-operative physiotherapy patient?","options": [{"key": "A","text": "Active ankle exercises"},{"key": "B","text": "Prolonged immobility and bed rest"},{"key": "C","text": "Compression stockings"},{"key": "D","text": "Early mobilization"}],"correct": "B","explanation": "Prolonged immobility promotes venous stasis, a major modifiable DVT risk factor addressed by physiotherapy."},{"id": 3693,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The primary rationale for early mobilization and ankle pump exercises post-surgery is to prevent:","options": [{"key": "A","text": "Muscle atrophy only"},{"key": "B","text": "Deep vein thrombosis via improved venous return"},{"key": "C","text": "Pressure ulcers only"},{"key": "D","text": "Joint stiffness only"}],"correct": "B","explanation": "Ankle pump exercises activate the calf muscle pump, enhancing venous return and reducing DVT risk."},{"id": 3694,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Reperfusion injury after restoring blood flow to ischemic tissue occurs mainly due to:","options": [{"key": "A","text": "Improved ATP synthesis only"},{"key": "B","text": "Generation of oxygen free radicals"},{"key": "C","text": "Decreased calcium influx"},{"key": "D","text": "Reduced inflammatory response"}],"correct": "B","explanation": "Reintroduction of oxygen generates reactive oxygen species causing additional tissue damage upon reperfusion."},{"id": 3695,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "A benign tumor arising from glandular epithelium is termed:","options": [{"key": "A","text": "Carcinoma in situ"},{"key": "B","text": "Sarcoma"},{"key": "C","text": "Adenoma"},{"key": "D","text": "Adenocarcinoma"}],"correct": "C","explanation": "Benign glandular epithelial tumors are named adenomas; malignant counterparts are adenocarcinomas."},{"id": 3696,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "A malignant tumor of connective tissue/mesenchymal origin is called:","options": [{"key": "A","text": "Adenoma"},{"key": "B","text": "Carcinoma"},{"key": "C","text": "Papilloma"},{"key": "D","text": "Sarcoma"}],"correct": "D","explanation": "Sarcomas arise from mesenchymal tissue (bone, muscle, fat), while carcinomas arise from epithelium."},{"id": 3697,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "Osteosarcoma is a malignant tumor of:","options": [{"key": "A","text": "Muscle"},{"key": "B","text": "Fibrous tissue"},{"key": "C","text": "Cartilage"},{"key": "D","text": "Bone"}],"correct": "D","explanation": "Osteosarcoma is the most common primary malignant bone tumor, producing osteoid."},{"id": 3698,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Rhabdomyosarcoma arises from:","options": [{"key": "A","text": "Cartilage"},{"key": "B","text": "Smooth muscle"},{"key": "C","text": "Skeletal muscle"},{"key": "D","text": "Cardiac muscle"}],"correct": "C","explanation": "Rhabdomyosarcoma is a malignant tumor of skeletal muscle origin, common in children."},{"id": 3699,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "Leiomyoma is a benign tumor of:","options": [{"key": "A","text": "Bone"},{"key": "B","text": "Cartilage"},{"key": "C","text": "Skeletal muscle"},{"key": "D","text": "Smooth muscle"}],"correct": "D","explanation": "Leiomyoma, commonly of the uterus, arises from smooth muscle."},{"id": 3700,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "Which feature best distinguishes malignant from benign tumors?","options": [{"key": "A","text": "Encapsulation"},{"key": "B","text": "Well-differentiated cells"},{"key": "C","text": "Ability to invade and metastasize"},{"key": "D","text": "Slow growth"}],"correct": "C","explanation": "Invasion and metastatic potential are the defining features distinguishing malignant tumors."},{"id": 3701,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Anaplasia refers to:","options": [{"key": "A","text": "Complete tissue destruction"},{"key": "B","text": "Slow tumor growth"},{"key": "C","text": "Loss of differentiation of tumor cells"},{"key": "D","text": "Encapsulation of tumor"}],"correct": "C","explanation": "Anaplasia describes a lack of cellular differentiation, a hallmark of malignancy."},{"id": 3702,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The most common route of metastasis for carcinomas is:","options": [{"key": "A","text": "Perineural spread only"},{"key": "B","text": "Direct seeding"},{"key": "C","text": "Lymphatic spread"},{"key": "D","text": "Hematogenous spread only"}],"correct": "C","explanation": "Carcinomas typically metastasize via lymphatics first, unlike sarcomas which favor hematogenous spread."},{"id": 3703,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Sarcomas typically metastasize via:","options": [{"key": "A","text": "Direct seeding only"},{"key": "B","text": "Hematogenous (blood) spread"},{"key": "C","text": "Lymphatic spread"},{"key": "D","text": "They do not metastasize"}],"correct": "B","explanation": "Sarcomas, being mesenchymal, preferentially spread through the bloodstream, often to lungs."},{"id": 3704,"subject": "Pathology","topic": "Neoplasia","difficulty": "Hard","question": "Krukenberg tumor refers to metastasis to the ovary, typically from:","options": [{"key": "A","text": "Breast only"},{"key": "B","text": "Thyroid"},{"key": "C","text": "Stomach (signet ring cell carcinoma)"},{"key": "D","text": "Lung"}],"correct": "C","explanation": "Krukenberg tumors are bilateral ovarian metastases classically from gastric signet-ring cell carcinoma."},{"id": 3705,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The most common site of skeletal metastasis is:","options": [{"key": "A","text": "Skull"},{"key": "B","text": "Vertebral column"},{"key": "C","text": "Hands"},{"key": "D","text": "Feet"}],"correct": "B","explanation": "The vertebral column, rich in red marrow with Batson's venous plexus, is the most common site of bone metastasis."},{"id": 3706,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which cancers most commonly metastasize to bone?","options": [{"key": "A","text": "Colon only"},{"key": "B","text": "Brain tumors only"},{"key": "C","text": "Breast, prostate, lung, kidney, thyroid"},{"key": "D","text": "Skin only"}],"correct": "C","explanation": "These five cancers (mnemonic: 'BLT with a Kosher Pickle') are the classic bone-metastasizing tumors, important for physiotherapy pathological fracture risk assessment."},{"id": 3707,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteolytic (lytic) bone metastases are most typical of:","options": [{"key": "A","text": "Prostate cancer"},{"key": "B","text": "Thyroid cancer only"},{"key": "C","text": "No cancer causes this"},{"key": "D","text": "Lung and breast cancer"}],"correct": "D","explanation": "Lung and breast cancer metastases typically cause lytic, bone-destroying lesions, risking pathological fracture."},{"id": 3708,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteoblastic (sclerotic) bone metastases are classically caused by:","options": [{"key": "A","text": "Prostate cancer"},{"key": "B","text": "Multiple myeloma"},{"key": "C","text": "Renal cell carcinoma"},{"key": "D","text": "Lung cancer"}],"correct": "A","explanation": "Prostate cancer metastases characteristically stimulate osteoblastic activity, producing sclerotic bone lesions."},{"id": 3709,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Which tumor marker is associated with hepatocellular carcinoma?","options": [{"key": "A","text": "PSA"},{"key": "B","text": "Alpha-fetoprotein (AFP)"},{"key": "C","text": "CA-125"},{"key": "D","text": "CEA"}],"correct": "B","explanation": "AFP is elevated in hepatocellular carcinoma and germ cell tumors."},{"id": 3710,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "CA-125 is a tumor marker primarily associated with:","options": [{"key": "A","text": "Ovarian cancer"},{"key": "B","text": "Prostate cancer"},{"key": "C","text": "Pancreatic cancer"},{"key": "D","text": "Colon cancer"}],"correct": "A","explanation": "CA-125 is used to monitor ovarian carcinoma, though not specific for diagnosis."},{"id": 3711,"subject": "Pathology","topic": "Immunology","difficulty": "Easy","question": "PSA (Prostate Specific Antigen) is used as a marker for:","options": [{"key": "A","text": "Prostate cancer"},{"key": "B","text": "Testicular cancer"},{"key": "C","text": "Lung cancer"},{"key": "D","text": "Breast cancer"}],"correct": "A","explanation": "PSA is used for screening and monitoring prostate cancer, though it can be elevated in BPH too."},{"id": 3712,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "CEA (Carcinoembryonic antigen) is most associated with which cancer?","options": [{"key": "A","text": "Ovarian cancer"},{"key": "B","text": "Thyroid cancer"},{"key": "C","text": "Colorectal cancer"},{"key": "D","text": "Testicular cancer"}],"correct": "C","explanation": "CEA is used mainly to monitor recurrence in colorectal carcinoma."},{"id": 3713,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "CA 19-9 is a tumor marker associated with:","options": [{"key": "A","text": "Pancreatic cancer"},{"key": "B","text": "Lung cancer"},{"key": "C","text": "Breast cancer"},{"key": "D","text": "Prostate cancer"}],"correct": "A","explanation": "CA 19-9 is elevated in pancreatic and biliary tract carcinomas."},{"id": 3714,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Which oncogene is classically associated with Burkitt lymphoma?","options": [{"key": "A","text": "p53"},{"key": "B","text": "c-myc"},{"key": "C","text": "Rb"},{"key": "D","text": "BRCA1"}],"correct": "B","explanation": "Burkitt lymphoma is characterized by c-myc translocation, typically t(8;14)."},{"id": 3715,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "The most commonly mutated tumor suppressor gene across human cancers is:","options": [{"key": "A","text": "Rb"},{"key": "B","text": "p53"},{"key": "C","text": "APC"},{"key": "D","text": "BRCA1"}],"correct": "B","explanation": "p53 ('guardian of the genome') is the most frequently mutated tumor suppressor gene in cancers."},{"id": 3716,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Retinoblastoma gene (Rb) mutation classically follows which genetic model?","options": [{"key": "A","text": "Two-hit hypothesis (Knudson)"},{"key": "B","text": "X-linked recessive only"},{"key": "C","text": "Mitochondrial inheritance"},{"key": "D","text": "Single hit dominant model"}],"correct": "A","explanation": "Knudson's two-hit hypothesis explains that both alleles of Rb must be inactivated for tumor development."},{"id": 3717,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "Which virus is strongly associated with cervical carcinoma?","options": [{"key": "A","text": "EBV"},{"key": "B","text": "HPV (Human Papillomavirus)"},{"key": "C","text": "HIV"},{"key": "D","text": "HBV"}],"correct": "B","explanation": "High-risk HPV types (16, 18) are strongly linked to cervical cancer development."},{"id": 3718,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Hepatitis B virus is a known risk factor for which cancer?","options": [{"key": "A","text": "Burkitt lymphoma"},{"key": "B","text": "Cervical cancer"},{"key": "C","text": "Nasopharyngeal carcinoma"},{"key": "D","text": "Hepatocellular carcinoma"}],"correct": "D","explanation": "Chronic HBV infection is a major risk factor for hepatocellular carcinoma."},{"id": 3719,"subject": "Pathology","topic": "Infectious Disease","difficulty": "Medium","question": "EBV (Epstein-Barr virus) is associated with which malignancy?","options": [{"key": "A","text": "Hepatocellular carcinoma"},{"key": "B","text": "Burkitt lymphoma and nasopharyngeal carcinoma"},{"key": "C","text": "Cervical cancer"},{"key": "D","text": "Prostate cancer"}],"correct": "B","explanation": "EBV is linked to Burkitt lymphoma, nasopharyngeal carcinoma, and some Hodgkin lymphomas."},{"id": 3720,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Asbestos exposure is a well-known risk factor for which cancers?","options": [{"key": "A","text": "Breast cancer"},{"key": "B","text": "Colon cancer"},{"key": "C","text": "Thyroid cancer"},{"key": "D","text": "Mesothelioma and lung cancer"}],"correct": "D","explanation": "Occupational asbestos exposure strongly predisposes to malignant mesothelioma and bronchogenic carcinoma."},{"id": 3721,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Cachexia in cancer patients is primarily mediated by:","options": [{"key": "A","text": "TNF-alpha and other cytokines"},{"key": "B","text": "Increased insulin"},{"key": "C","text": "Vitamin deficiency alone"},{"key": "D","text": "Decreased metabolic rate"}],"correct": "A","explanation": "Cytokines like TNF-alpha drive the profound weight loss and muscle wasting seen in cancer cachexia, relevant to physiotherapy rehabilitation planning."},{"id": 3722,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Paraneoplastic syndrome causing hypercalcemia is most commonly due to:","options": [{"key": "A","text": "Increased calcitonin"},{"key": "B","text": "PTHrP secretion by tumor (e.g., squamous cell lung carcinoma)"},{"key": "C","text": "Renal failure"},{"key": "D","text": "Vitamin D excess"}],"correct": "B","explanation": "Certain tumors secrete parathyroid hormone-related peptide (PTHrP), causing hypercalcemia of malignancy."},{"id": 3723,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Grading of a tumor refers to:","options": [{"key": "A","text": "Presence of lymph node involvement"},{"key": "B","text": "Extent of spread in the body"},{"key": "C","text": "Degree of differentiation of tumor cells"},{"key": "D","text": "Size of the primary tumor only"}],"correct": "C","explanation": "Tumor grading assesses histological differentiation, indicating how aggressive the tumor appears."},{"id": 3724,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Staging of a tumor (e.g., TNM system) refers to:","options": [{"key": "A","text": "Degree of cellular differentiation"},{"key": "B","text": "Extent of tumor spread in the body"},{"key": "C","text": "Tumor color"},{"key": "D","text": "Tumor consistency"}],"correct": "B","explanation": "Staging (TNM: Tumor, Node, Metastasis) describes the anatomical extent of disease spread."},{"id": 3725,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "Which of the following tumors is benign despite rapid growth potential?","options": [{"key": "A","text": "Osteosarcoma"},{"key": "B","text": "Uterine leiomyoma"},{"key": "C","text": "Malignant melanoma"},{"key": "D","text": "Glioblastoma"}],"correct": "B","explanation": "Leiomyoma (fibroid) is a common benign smooth muscle tumor, though it can grow substantially in size."},{"id": 3726,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Multiple myeloma primarily affects which cell line and causes bone lesions due to:","options": [{"key": "A","text": "Osteoclast-activating factors from malignant plasma cells"},{"key": "B","text": "Osteoblast overactivity"},{"key": "C","text": "Excess calcitonin"},{"key": "D","text": "Excess vitamin D"}],"correct": "A","explanation": "Malignant plasma cells secrete factors (like RANKL) that activate osteoclasts, causing punched-out lytic bone lesions and pathological fractures."},{"id": 3727,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Type I hypersensitivity reaction is mediated primarily by:","options": [{"key": "A","text": "Immune complexes"},{"key": "B","text": "IgG and complement"},{"key": "C","text": "T cells"},{"key": "D","text": "IgE antibodies and mast cells"}],"correct": "D","explanation": "Type I (immediate) hypersensitivity involves IgE-sensitized mast cells releasing histamine, as in anaphylaxis and allergies."},{"id": 3728,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Anaphylactic shock is an example of which hypersensitivity type?","options": [{"key": "A","text": "Type I"},{"key": "B","text": "Type IV"},{"key": "C","text": "Type III"},{"key": "D","text": "Type II"}],"correct": "A","explanation": "Anaphylaxis is a severe systemic Type I hypersensitivity reaction."},{"id": 3729,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Type II hypersensitivity reaction involves:","options": [{"key": "A","text": "Antibody-mediated cytotoxicity against cell surface antigens"},{"key": "B","text": "IgE-mediated mast cell degranulation"},{"key": "C","text": "T-cell mediated delayed reaction"},{"key": "D","text": "Immune complex deposition"}],"correct": "A","explanation": "Type II hypersensitivity involves IgG/IgM antibodies directly attacking cell surface antigens, e.g., hemolytic anemia."},{"id": 3730,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Rheumatic heart disease is an example of which hypersensitivity mechanism?","options": [{"key": "A","text": "Type I"},{"key": "B","text": "Type IV"},{"key": "C","text": "Type II (molecular mimicry)"},{"key": "D","text": "Type III"}],"correct": "C","explanation": "Antibodies against streptococcal antigens cross-react with cardiac tissue (molecular mimicry) — a Type II mechanism."},{"id": 3731,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Type III hypersensitivity reactions are mediated by:","options": [{"key": "A","text": "IgE and mast cells"},{"key": "B","text": "Direct cytotoxic T cells"},{"key": "C","text": "Immune complex deposition activating complement"},{"key": "D","text": "Antibody against cell surface antigen"}],"correct": "C","explanation": "Type III reactions involve antigen-antibody complexes depositing in tissues, causing inflammation, as in serum sickness."},{"id": 3732,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Systemic Lupus Erythematosus is primarily driven by which hypersensitivity mechanism?","options": [{"key": "A","text": "Type II"},{"key": "B","text": "Type I"},{"key": "C","text": "Type IV"},{"key": "D","text": "Type III (immune complex mediated)"}],"correct": "D","explanation": "SLE involves immune complex deposition in vessels/tissues, activating complement and causing widespread inflammation."},{"id": 3733,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Type IV hypersensitivity is mediated by:","options": [{"key": "A","text": "IgM antibodies"},{"key": "B","text": "IgE antibodies"},{"key": "C","text": "T lymphocytes (delayed-type)"},{"key": "D","text": "Immune complexes"}],"correct": "C","explanation": "Type IV is a cell-mediated, delayed hypersensitivity involving sensitized T cells, e.g., tuberculin test, contact dermatitis."},{"id": 3734,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The Mantoux (tuberculin) test is based on which hypersensitivity reaction?","options": [{"key": "A","text": "Type III"},{"key": "B","text": "Type IV"},{"key": "C","text": "Type II"},{"key": "D","text": "Type I"}],"correct": "B","explanation": "The tuberculin skin test reflects a delayed-type (Type IV) T-cell mediated hypersensitivity response."},{"id": 3735,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Rheumatoid arthritis is best classified as which type of immune-mediated disorder?","options": [{"key": "A","text": "Infectious disease only"},{"key": "B","text": "Autoimmune disease with Type III/IV hypersensitivity features"},{"key": "C","text": "Purely Type I allergic disease"},{"key": "D","text": "Genetic metabolic disorder"}],"correct": "B","explanation": "RA involves autoantibodies (rheumatoid factor), immune complexes, and T-cell mediated joint inflammation."},{"id": 3736,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Rheumatoid factor is an antibody directed against:","options": [{"key": "A","text": "Red blood cell antigens"},{"key": "B","text": "Fc portion of IgG"},{"key": "C","text": "Nuclear antigens"},{"key": "D","text": "Basement membrane"}],"correct": "B","explanation": "Rheumatoid factor is typically an IgM antibody against the Fc portion of IgG."},{"id": 3737,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Anti-nuclear antibody (ANA) is a screening test primarily for:","options": [{"key": "A","text": "Myasthenia gravis"},{"key": "B","text": "Multiple sclerosis"},{"key": "C","text": "Rheumatoid arthritis"},{"key": "D","text": "Systemic Lupus Erythematosus"}],"correct": "D","explanation": "ANA is highly sensitive (though not specific) for SLE and other connective tissue diseases."},{"id": 3738,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Anti-dsDNA antibody is highly specific for:","options": [{"key": "A","text": "Rheumatoid arthritis"},{"key": "B","text": "Scleroderma"},{"key": "C","text": "Sjogren syndrome"},{"key": "D","text": "Systemic Lupus Erythematosus"}],"correct": "D","explanation": "Anti-double stranded DNA antibodies are highly specific for SLE and correlate with disease activity/lupus nephritis."},{"id": 3739,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Myasthenia gravis results from autoantibodies against:","options": [{"key": "A","text": "Muscle spindle"},{"key": "B","text": "Acetylcholine receptors at neuromuscular junction"},{"key": "C","text": "Motor neuron cell body"},{"key": "D","text": "Presynaptic calcium channels"}],"correct": "B","explanation": "MG is caused by autoantibodies blocking/destroying postsynaptic acetylcholine receptors, causing fatigable muscle weakness — key for physiotherapy assessment."},{"id": 3740,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Lambert-Eaton myasthenic syndrome involves autoantibodies against:","options": [{"key": "A","text": "Muscle fibers directly"},{"key": "B","text": "Presynaptic voltage-gated calcium channels"},{"key": "C","text": "Acetylcholine receptors"},{"key": "D","text": "Motor cortex"}],"correct": "B","explanation": "Unlike myasthenia gravis, Lambert-Eaton syndrome targets presynaptic calcium channels, often paraneoplastic (small cell lung cancer)."},{"id": 3741,"subject": "Pathology","topic": "Immunology","difficulty": "Easy","question": "Multiple sclerosis is an autoimmune disease targeting:","options": [{"key": "A","text": "Muscle fibers"},{"key": "B","text": "Peripheral nerve myelin only"},{"key": "C","text": "Myelin sheath of CNS neurons"},{"key": "D","text": "Joint synovium"}],"correct": "C","explanation": "MS involves autoimmune demyelination of CNS white matter, causing varied neurological deficits."},{"id": 3742,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Guillain-Barre syndrome is an autoimmune disorder affecting:","options": [{"key": "A","text": "Muscle fibers directly"},{"key": "B","text": "Neuromuscular junction"},{"key": "C","text": "CNS myelin only"},{"key": "D","text": "Peripheral nerve myelin (often post-infectious)"}],"correct": "D","explanation": "GBS involves autoimmune demyelination of peripheral nerves, often following an infection, causing ascending paralysis."},{"id": 3743,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Ankylosing spondylitis is strongly associated with which HLA antigen?","options": [{"key": "A","text": "HLA-DR3"},{"key": "B","text": "HLA-DR4"},{"key": "C","text": "HLA-B27"},{"key": "D","text": "HLA-B8"}],"correct": "C","explanation": "Ankylosing spondylitis shows strong association with HLA-B27, relevant to spinal mobility issues in physiotherapy."},{"id": 3744,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Sjogren syndrome is characterized by autoimmune destruction of:","options": [{"key": "A","text": "Thyroid gland"},{"key": "B","text": "Pancreatic islets"},{"key": "C","text": "Adrenal cortex"},{"key": "D","text": "Lacrimal and salivary glands"}],"correct": "D","explanation": "Sjogren syndrome causes lymphocytic infiltration and destruction of exocrine glands, leading to dry eyes and mouth."},{"id": 3745,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Scleroderma (systemic sclerosis) is characterized by:","options": [{"key": "A","text": "Excessive fibrosis of skin and internal organs"},{"key": "B","text": "Demyelination"},{"key": "C","text": "Muscle hypertrophy"},{"key": "D","text": "Destruction of joints only"}],"correct": "A","explanation": "Scleroderma involves autoimmune-triggered excessive collagen deposition causing skin/organ fibrosis, impacting mobility."},{"id": 3746,"subject": "Pathology","topic": "Immunology","difficulty": "Easy","question": "Polymyositis and dermatomyositis are autoimmune conditions primarily affecting:","options": [{"key": "A","text": "Joints only"},{"key": "B","text": "Cardiac muscle only"},{"key": "C","text": "Skeletal muscle (with skin involvement in dermatomyositis)"},{"key": "D","text": "Peripheral nerves"}],"correct": "C","explanation": "These are inflammatory myopathies causing proximal muscle weakness, of direct relevance to physiotherapy management."},{"id": 3747,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Graft-versus-host disease occurs when:","options": [{"key": "A","text": "Transplanted immune cells attack the recipient's tissues"},{"key": "B","text": "Host antibodies attack the graft only"},{"key": "C","text": "No immune response occurs"},{"key": "D","text": "Recipient rejects the graft"}],"correct": "A","explanation": "GVHD occurs in bone marrow/stem cell transplants when donor T cells attack recipient tissues."},{"id": 3748,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Hyperacute graft rejection occurs due to:","options": [{"key": "A","text": "Pre-existing antibodies against donor antigens"},{"key": "B","text": "No immune involvement"},{"key": "C","text": "Delayed T-cell response"},{"key": "D","text": "Chronic fibrosis only"}],"correct": "A","explanation": "Hyperacute rejection occurs within minutes due to pre-formed antibodies reacting with donor endothelium."},{"id": 3749,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which immunoglobulin is most involved in Type I hypersensitivity reactions?","options": [{"key": "A","text": "IgA"},{"key": "B","text": "IgG"},{"key": "C","text": "IgM"},{"key": "D","text": "IgE"}],"correct": "D","explanation": "IgE binds to mast cells/basophils and triggers degranulation upon allergen exposure."},{"id": 3750,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Complement activation in Type II hypersensitivity leads to cell lysis via:","options": [{"key": "A","text": "T-cell cytotoxicity"},{"key": "B","text": "Membrane attack complex (C5b-C9)"},{"key": "C","text": "Histamine release"},{"key": "D","text": "Mast cell degranulation"}],"correct": "B","explanation": "The complement membrane attack complex creates pores in target cell membranes causing lysis."},{"id": 3751,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Autoimmune hemolytic anemia is an example of which hypersensitivity type?","options": [{"key": "A","text": "Type III"},{"key": "B","text": "Type IV"},{"key": "C","text": "Type II"},{"key": "D","text": "Type I"}],"correct": "C","explanation": "Antibodies directly target RBC surface antigens, causing their destruction — a Type II reaction."},{"id": 3752,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Contact dermatitis (e.g., to nickel or poison ivy) is mediated by which hypersensitivity type?","options": [{"key": "A","text": "Type III"},{"key": "B","text": "Type I"},{"key": "C","text": "Type II"},{"key": "D","text": "Type IV"}],"correct": "D","explanation": "Contact dermatitis is a classic delayed-type (Type IV) T-cell mediated hypersensitivity reaction."},{"id": 3753,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Down syndrome is caused by:","options": [{"key": "A","text": "Monosomy X"},{"key": "B","text": "Trisomy of chromosome 13"},{"key": "C","text": "Trisomy of chromosome 18"},{"key": "D","text": "Trisomy of chromosome 21"}],"correct": "D","explanation": "Down syndrome results from an extra copy of chromosome 21 (trisomy 21)."},{"id": 3754,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Edward syndrome is caused by trisomy of chromosome:","options": [{"key": "A","text": "18"},{"key": "B","text": "X"},{"key": "C","text": "13"},{"key": "D","text": "21"}],"correct": "A","explanation": "Edward syndrome (trisomy 18) is associated with severe multiple congenital anomalies."},{"id": 3755,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Patau syndrome is caused by trisomy of chromosome:","options": [{"key": "A","text": "21"},{"key": "B","text": "13"},{"key": "C","text": "18"},{"key": "D","text": "22"}],"correct": "B","explanation": "Patau syndrome (trisomy 13) presents with severe midline defects and poor prognosis."},{"id": 3756,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Turner syndrome karyotype is typically:","options": [{"key": "A","text": "47,XXX"},{"key": "B","text": "46,XY"},{"key": "C","text": "47,XXY"},{"key": "D","text": "45,X"}],"correct": "D","explanation": "Turner syndrome results from a single X chromosome (monosomy X), causing short stature and gonadal dysgenesis."},{"id": 3757,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Klinefelter syndrome karyotype is typically:","options": [{"key": "A","text": "47,XXX"},{"key": "B","text": "46,XX"},{"key": "C","text": "47,XXY"},{"key": "D","text": "45,X"}],"correct": "C","explanation": "Klinefelter syndrome (47,XXY) presents with hypogonadism and tall stature in males."},{"id": 3758,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Duchenne muscular dystrophy is inherited in which pattern?","options": [{"key": "A","text": "Autosomal dominant"},{"key": "B","text": "X-linked recessive"},{"key": "C","text": "Autosomal recessive"},{"key": "D","text": "Mitochondrial"}],"correct": "B","explanation": "DMD follows X-linked recessive inheritance due to dystrophin gene mutation, primarily affecting males."},{"id": 3759,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The defective gene product in Duchenne muscular dystrophy is:","options": [{"key": "A","text": "Dystrophin"},{"key": "B","text": "Myosin"},{"key": "C","text": "Troponin"},{"key": "D","text": "Actin"}],"correct": "A","explanation": "DMD results from absent/deficient dystrophin, a structural protein maintaining muscle membrane integrity."},{"id": 3760,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Becker muscular dystrophy differs from Duchenne in that it involves:","options": [{"key": "A","text": "X-linked dominant inheritance"},{"key": "B","text": "No muscle involvement"},{"key": "C","text": "Partially functional dystrophin (milder course)"},{"key": "D","text": "Complete absence of dystrophin (more severe)"}],"correct": "C","explanation": "Becker MD involves a partially functional dystrophin protein, causing a milder, later-onset disease than DMD."},{"id": 3761,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Marfan syndrome is caused by a defect in which gene/protein?","options": [{"key": "A","text": "Elastin only"},{"key": "B","text": "Dystrophin"},{"key": "C","text": "Collagen type I"},{"key": "D","text": "Fibrillin-1"}],"correct": "D","explanation": "Marfan syndrome results from fibrillin-1 gene mutations affecting connective tissue, causing skeletal, ocular and cardiovascular features."},{"id": 3762,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Osteogenesis imperfecta is primarily due to a defect in:","options": [{"key": "A","text": "Type II collagen"},{"key": "B","text": "Type I collagen"},{"key": "C","text": "Fibrillin"},{"key": "D","text": "Dystrophin"}],"correct": "B","explanation": "OI results from mutations affecting Type I collagen synthesis, causing brittle bones and fractures."},{"id": 3763,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ehlers-Danlos syndrome is characterized by defects in:","options": [{"key": "A","text": "Myosin"},{"key": "B","text": "Collagen synthesis/structure"},{"key": "C","text": "Dystrophin"},{"key": "D","text": "Fibrillin only"}],"correct": "B","explanation": "EDS involves various collagen gene defects causing hyperextensible skin and joint hypermobility."},{"id": 3764,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Sickle cell anemia results from a mutation in which gene?","options": [{"key": "A","text": "Beta-globin gene"},{"key": "B","text": "Alpha-globin gene"},{"key": "C","text": "Fibrillin gene"},{"key": "D","text": "Dystrophin gene"}],"correct": "A","explanation": "A point mutation in the beta-globin gene causes glutamic acid to be replaced by valine, forming HbS."},{"id": 3765,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Sickle cell disease follows which inheritance pattern?","options": [{"key": "A","text": "Mitochondrial"},{"key": "B","text": "Autosomal dominant"},{"key": "C","text": "X-linked recessive"},{"key": "D","text": "Autosomal recessive"}],"correct": "D","explanation": "Sickle cell disease is inherited in an autosomal recessive manner; heterozygotes have sickle trait."},{"id": 3766,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Phenylketonuria (PKU) results from deficiency of which enzyme?","options": [{"key": "A","text": "Tyrosinase"},{"key": "B","text": "Hexosaminidase"},{"key": "C","text": "Galactosidase"},{"key": "D","text": "Phenylalanine hydroxylase"}],"correct": "D","explanation": "PKU is caused by deficient phenylalanine hydroxylase, leading to phenylalanine accumulation and intellectual disability if untreated."},{"id": 3767,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Down syndrome risk increases significantly with:","options": [{"key": "A","text": "Paternal age only"},{"key": "B","text": "Low birth weight"},{"key": "C","text": "Advanced maternal age"},{"key": "D","text": "Consanguinity only"}],"correct": "C","explanation": "The risk of trisomy 21 (Down syndrome) rises markedly with increasing maternal age due to nondisjunction."},{"id": 3768,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Fragile X syndrome is caused by:","options": [{"key": "A","text": "Trinucleotide repeat expansion (CGG) on the X chromosome"},{"key": "B","text": "Point mutation in dystrophin"},{"key": "C","text": "Trisomy of X chromosome"},{"key": "D","text": "Deletion of chromosome 5"}],"correct": "A","explanation": "Fragile X syndrome results from CGG repeat expansion in the FMR1 gene, causing intellectual disability, common in males."},{"id": 3769,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Cystic fibrosis is inherited as:","options": [{"key": "A","text": "Autosomal dominant"},{"key": "B","text": "X-linked recessive"},{"key": "C","text": "Mitochondrial"},{"key": "D","text": "Autosomal recessive"}],"correct": "D","explanation": "CF results from mutations in the CFTR gene, inherited in an autosomal recessive pattern."},{"id": 3770,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Huntington disease is inherited as:","options": [{"key": "A","text": "Autosomal recessive"},{"key": "B","text": "X-linked recessive"},{"key": "C","text": "Mitochondrial"},{"key": "D","text": "Autosomal dominant with trinucleotide repeat expansion"}],"correct": "D","explanation": "Huntington disease follows autosomal dominant inheritance with CAG trinucleotide repeat expansion causing progressive neurodegeneration."},{"id": 3771,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Mitochondrial disorders are inherited through:","options": [{"key": "A","text": "X-linked pattern"},{"key": "B","text": "Autosomal dominant pattern"},{"key": "C","text": "Maternal lineage only"},{"key": "D","text": "Paternal lineage only"}],"correct": "C","explanation": "Mitochondrial DNA is inherited exclusively from the mother, so mitochondrial disorders show maternal transmission."},{"id": 3772,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Achondroplasia, a common cause of dwarfism, is inherited as:","options": [{"key": "A","text": "Mitochondrial"},{"key": "B","text": "Autosomal dominant"},{"key": "C","text": "X-linked recessive"},{"key": "D","text": "Autosomal recessive"}],"correct": "B","explanation": "Achondroplasia results from FGFR3 gene mutation, inherited in an autosomal dominant manner, causing short-limbed dwarfism."},{"id": 3773,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Spinal muscular atrophy is caused by degeneration of:","options": [{"key": "A","text": "Peripheral sensory nerves"},{"key": "B","text": "Cerebellum"},{"key": "C","text": "Anterior horn cells of the spinal cord"},{"key": "D","text": "Posterior column neurons"}],"correct": "C","explanation": "SMA is an autosomal recessive disorder causing progressive loss of anterior horn motor neurons, leading to muscle weakness — important in physiotherapy management."},{"id": 3774,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Charcot-Marie-Tooth disease primarily affects:","options": [{"key": "A","text": "Cardiac muscle"},{"key": "B","text": "Peripheral motor and sensory nerves"},{"key": "C","text": "CNS myelin only"},{"key": "D","text": "Neuromuscular junction"}],"correct": "B","explanation": "CMT is a hereditary peripheral neuropathy causing distal muscle weakness and sensory loss, of high relevance in physiotherapy practice."},{"id": 3775,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which chromosomal analysis technique is used to detect numerical and structural abnormalities?","options": [{"key": "A","text": "Karyotyping"},{"key": "B","text": "ELISA"},{"key": "C","text": "Western blot"},{"key": "D","text": "PCR for point mutations only"}],"correct": "A","explanation": "Karyotyping visualizes chromosome number and gross structural changes like translocations and deletions."},{"id": 3776,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Osteoporosis is characterized by:","options": [{"key": "A","text": "Increased osteoblast activity"},{"key": "B","text": "Decreased bone mass with normal mineralization"},{"key": "C","text": "Defective mineralization only"},{"key": "D","text": "Increased bone density"}],"correct": "B","explanation": "Osteoporosis involves reduced bone mass but normal mineral-to-matrix ratio, increasing fracture risk."},{"id": 3777,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Post-menopausal osteoporosis is primarily due to:","options": [{"key": "A","text": "Decreased PTH"},{"key": "B","text": "Vitamin D excess"},{"key": "C","text": "Increased calcitonin"},{"key": "D","text": "Estrogen deficiency increasing osteoclastic activity"}],"correct": "D","explanation": "Estrogen deficiency after menopause upregulates osteoclast activity via RANKL, accelerating bone loss."},{"id": 3778,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which is the gold standard investigation for diagnosing osteoporosis?","options": [{"key": "A","text": "DEXA scan (bone mineral density)"},{"key": "B","text": "MRI"},{"key": "C","text": "X-ray"},{"key": "D","text": "CT scan"}],"correct": "A","explanation": "DEXA scan measures bone mineral density and is the gold standard for osteoporosis diagnosis (T-score)."},{"id": 3779,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "A T-score of -2.5 or lower on DEXA scan indicates:","options": [{"key": "A","text": "Normal bone density"},{"key": "B","text": "Osteoporosis"},{"key": "C","text": "Osteopenia"},{"key": "D","text": "Osteomalacia"}],"correct": "B","explanation": "A T-score ≤ -2.5 SD below young adult mean defines osteoporosis per WHO criteria."},{"id": 3780,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Osteomalacia is caused by:","options": [{"key": "A","text": "Excess PTH only"},{"key": "B","text": "Excess vitamin D"},{"key": "C","text": "Vitamin D deficiency causing defective bone mineralization"},{"key": "D","text": "Estrogen deficiency"}],"correct": "C","explanation": "Osteomalacia results from inadequate mineralization of osteoid due to vitamin D deficiency in adults (rickets in children)."},{"id": 3781,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Rickets is the pediatric equivalent of which adult bone disease?","options": [{"key": "A","text": "Osteopetrosis"},{"key": "B","text": "Osteoporosis"},{"key": "C","text": "Paget's disease"},{"key": "D","text": "Osteomalacia"}],"correct": "D","explanation": "Rickets in children and osteomalacia in adults both result from vitamin D deficiency affecting bone mineralization."},{"id": 3782,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Osteopetrosis ('marble bone disease') results from a defect in:","options": [{"key": "A","text": "Osteoblast function"},{"key": "B","text": "Osteoclast function"},{"key": "C","text": "Collagen synthesis"},{"key": "D","text": "Vitamin D metabolism"}],"correct": "B","explanation": "Osteopetrosis is caused by defective osteoclastic bone resorption, leading to abnormally dense but brittle bones."},{"id": 3783,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Paget's disease of bone is characterized by:","options": [{"key": "A","text": "Pure bone loss only"},{"key": "B","text": "Disorganized excessive bone remodeling (osteoclastic then osteoblastic)"},{"key": "C","text": "Absence of osteoclasts"},{"key": "D","text": "Pure mineralization defect"}],"correct": "B","explanation": "Paget's disease shows chaotic, excessive bone turnover creating a mosaic pattern, causing bone pain and deformity."},{"id": 3784,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Osteoarthritis primarily involves degeneration of:","options": [{"key": "A","text": "Synovium primarily"},{"key": "B","text": "Bone marrow"},{"key": "C","text": "Articular cartilage"},{"key": "D","text": "Ligaments only"}],"correct": "C","explanation": "OA is a degenerative joint disease with progressive loss of articular cartilage and subchondral bone changes."},{"id": 3785,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteophytes (bone spurs) in osteoarthritis form due to:","options": [{"key": "A","text": "Bone resorption"},{"key": "B","text": "Synovial inflammation only"},{"key": "C","text": "Cartilage regeneration"},{"key": "D","text": "Reactive new bone formation at joint margins"}],"correct": "D","explanation": "OA triggers reactive osteophyte formation at joint margins as an attempted repair response."},{"id": 3786,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Rheumatoid arthritis primarily affects which joints in a characteristic pattern?","options": [{"key": "A","text": "Small joints of hands/feet, symmetrically"},{"key": "B","text": "Spine only"},{"key": "C","text": "Large weight-bearing joints only"},{"key": "D","text": "DIP joints primarily"}],"correct": "A","explanation": "RA classically causes symmetric polyarthritis of small joints (PIP, MCP), sparing DIP joints, unlike OA."},{"id": 3787,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pannus formation in rheumatoid arthritis refers to:","options": [{"key": "A","text": "Normal synovial fluid"},{"key": "B","text": "Inflammatory granulation tissue invading and destroying joint cartilage/bone"},{"key": "C","text": "Cartilage regeneration"},{"key": "D","text": "Bone spur formation"}],"correct": "B","explanation": "Pannus is proliferative, inflamed synovial tissue that erodes articular cartilage and bone in RA."},{"id": 3788,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Swan neck and boutonniere deformities are classic findings in:","options": [{"key": "A","text": "Ankylosing spondylitis"},{"key": "B","text": "Osteoarthritis"},{"key": "C","text": "Gout"},{"key": "D","text": "Rheumatoid arthritis"}],"correct": "D","explanation": "These characteristic finger deformities result from chronic joint/tendon damage in rheumatoid arthritis."},{"id": 3789,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Gout is caused by deposition of which crystals in joints?","options": [{"key": "A","text": "Calcium oxalate"},{"key": "B","text": "Monosodium urate crystals"},{"key": "C","text": "Cholesterol crystals"},{"key": "D","text": "Calcium pyrophosphate crystals"}],"correct": "B","explanation": "Gout results from hyperuricemia leading to monosodium urate crystal deposition in joints, classically the great toe (podagra)."},{"id": 3790,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pseudogout is caused by deposition of which crystals?","options": [{"key": "A","text": "Calcium oxalate"},{"key": "B","text": "Calcium pyrophosphate dihydrate (CPPD) crystals"},{"key": "C","text": "Monosodium urate"},{"key": "D","text": "Cholesterol crystals"}],"correct": "B","explanation": "Pseudogout results from CPPD crystal deposition in joints, commonly affecting the knee."},{"id": 3791,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Under polarized light microscopy, gout crystals are:","options": [{"key": "A","text": "Round and non-birefringent"},{"key": "B","text": "Amorphous"},{"key": "C","text": "Rhomboid and positively birefringent"},{"key": "D","text": "Needle-shaped and negatively birefringent"}],"correct": "D","explanation": "Monosodium urate crystals appear needle-shaped with strong negative birefringence under polarized light."},{"id": 3792,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Ankylosing spondylitis primarily affects:","options": [{"key": "A","text": "Hands and feet symmetrically"},{"key": "B","text": "Sacroiliac joints and spine"},{"key": "C","text": "Hip joint only"},{"key": "D","text": "Knee joint only"}],"correct": "B","explanation": "AS is a seronegative spondyloarthropathy causing progressive fusion of sacroiliac joints and spine, leading to 'bamboo spine'."},{"id": 3793,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "'Bamboo spine' on X-ray is a classic radiological finding in:","options": [{"key": "A","text": "Rheumatoid arthritis"},{"key": "B","text": "Ankylosing spondylitis"},{"key": "C","text": "Osteoarthritis"},{"key": "D","text": "Osteoporosis"}],"correct": "B","explanation": "Progressive syndesmophyte formation and vertebral fusion in AS produces the classic bamboo spine appearance."},{"id": 3794,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Osteomyelitis is most commonly caused by which organism?","options": [{"key": "A","text": "Streptococcus pneumoniae"},{"key": "B","text": "Pseudomonas aeruginosa"},{"key": "C","text": "Staphylococcus aureus"},{"key": "D","text": "E. coli"}],"correct": "C","explanation": "S. aureus is the most common causative organism of acute and chronic osteomyelitis."},{"id": 3795,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Sequestrum in osteomyelitis refers to:","options": [{"key": "A","text": "Piece of dead, necrotic bone separated from viable bone"},{"key": "B","text": "Synovial thickening"},{"key": "C","text": "Cartilage destruction"},{"key": "D","text": "New bone formation around infection"}],"correct": "A","explanation": "A sequestrum is devitalized bone that has separated from living bone during chronic osteomyelitis."},{"id": 3796,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Involucrum in osteomyelitis refers to:","options": [{"key": "A","text": "Dead bone fragment"},{"key": "B","text": "Pus collection"},{"key": "C","text": "Joint space narrowing"},{"key": "D","text": "New periosteal bone formation surrounding a sequestrum"}],"correct": "D","explanation": "Involucrum is a shell of new bone that forms around the sequestrum as a reactive periosteal response."},{"id": 3797,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Duchenne muscular dystrophy typically presents with:","options": [{"key": "A","text": "Sensory loss"},{"key": "B","text": "Progressive proximal muscle weakness and pseudohypertrophy of calves"},{"key": "C","text": "Distal muscle weakness only"},{"key": "D","text": "Joint hypermobility only"}],"correct": "B","explanation": "DMD classically presents in early childhood with proximal weakness, Gowers' sign, and calf pseudohypertrophy."},{"id": 3798,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Gowers' sign, seen in muscular dystrophies, indicates weakness of:","options": [{"key": "A","text": "Pelvic girdle and proximal lower limb muscles"},{"key": "B","text": "Distal hand muscles"},{"key": "C","text": "Ocular muscles"},{"key": "D","text": "Facial muscles only"}],"correct": "A","explanation": "Gowers' sign (using hands to 'climb up' the body when rising) reflects proximal hip and thigh muscle weakness."},{"id": 3799,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Polymyositis characteristically causes:","options": [{"key": "A","text": "Joint deformity only"},{"key": "B","text": "Distal weakness with normal CPK"},{"key": "C","text": "Sensory loss without weakness"},{"key": "D","text": "Symmetric proximal muscle weakness with elevated CPK"}],"correct": "D","explanation": "Polymyositis is an inflammatory myopathy causing proximal weakness with elevated creatine phosphokinase levels."},{"id": 3800,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Fibromyalgia is characterized by:","options": [{"key": "A","text": "Chronic widespread musculoskeletal pain with specific tender points"},{"key": "B","text": "Muscle atrophy on biopsy"},{"key": "C","text": "Elevated inflammatory markers"},{"key": "D","text": "Joint erosion on X-ray"}],"correct": "A","explanation": "Fibromyalgia presents with diffuse pain and tenderness without objective inflammatory or structural findings."},{"id": 3801,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Compartment syndrome results in muscle/nerve damage primarily due to:","options": [{"key": "A","text": "Direct bacterial infection"},{"key": "B","text": "Autoimmune destruction"},{"key": "C","text": "Chronic degeneration"},{"key": "D","text": "Increased pressure within a closed fascial space compromising perfusion"}],"correct": "D","explanation": "Elevated intracompartmental pressure impairs capillary perfusion, causing ischemic muscle and nerve injury — a physiotherapy emergency concern."},{"id": 3802,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Rhabdomyolysis is characterized by:","options": [{"key": "A","text": "Nerve demyelination"},{"key": "B","text": "Cartilage degeneration"},{"key": "C","text": "Bone breakdown only"},{"key": "D","text": "Breakdown of skeletal muscle releasing myoglobin into circulation"}],"correct": "D","explanation": "Rhabdomyolysis involves muscle fiber necrosis releasing myoglobin, which can cause acute kidney injury."},{"id": 3803,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which enzyme is markedly elevated in rhabdomyolysis and muscle injury?","options": [{"key": "A","text": "Creatine kinase (CK)"},{"key": "B","text": "Alkaline phosphatase"},{"key": "C","text": "Amylase"},{"key": "D","text": "Lipase"}],"correct": "A","explanation": "CK is released from damaged muscle fibers and is the key diagnostic marker for rhabdomyolysis/muscle injury."},{"id": 3804,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteosarcoma most commonly occurs in which age group and location?","options": [{"key": "A","text": "Elderly, axial skeleton"},{"key": "B","text": "Infants, skull"},{"key": "C","text": "Adolescents, metaphysis of long bones (distal femur/proximal tibia)"},{"key": "D","text": "Middle-aged, hands"}],"correct": "C","explanation": "Osteosarcoma typically affects adolescents at the metaphysis of long bones during rapid growth periods."},{"id": 3805,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "'Codman triangle' and 'sunburst appearance' on X-ray are classic for:","options": [{"key": "A","text": "Osteoporosis"},{"key": "B","text": "Osteosarcoma"},{"key": "C","text": "Osteoarthritis"},{"key": "D","text": "Rheumatoid arthritis"}],"correct": "B","explanation": "These radiological signs reflect aggressive periosteal reaction seen in osteosarcoma."},{"id": 3806,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Ewing sarcoma classically shows which radiological finding?","options": [{"key": "A","text": "Ground-glass appearance"},{"key": "B","text": "Codman triangle only"},{"key": "C","text": "Bamboo spine"},{"key": "D","text": "Onion-skin periosteal reaction"}],"correct": "D","explanation": "Ewing sarcoma classically produces a lamellated 'onion-skin' periosteal reaction on X-ray."},{"id": 3807,"subject": "Pathology","topic": "Neoplasia","difficulty": "Hard","question": "Giant cell tumor of bone typically occurs at:","options": [{"key": "A","text": "Epiphysis of long bones (near knee) after growth plate closure"},{"key": "B","text": "Skull only"},{"key": "C","text": "Diaphysis in children"},{"key": "D","text": "Vertebrae only"}],"correct": "A","explanation": "Giant cell tumor characteristically arises in the epiphyseal region of long bones in young adults."},{"id": 3808,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Chondrosarcoma is a malignant tumor arising from:","options": [{"key": "A","text": "Muscle"},{"key": "B","text": "Cartilage"},{"key": "C","text": "Bone marrow"},{"key": "D","text": "Synovium"}],"correct": "B","explanation": "Chondrosarcoma produces malignant cartilage matrix, typically affecting middle-aged/older adults in pelvis/proximal long bones."},{"id": 3809,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteoid osteoma classically presents with:","options": [{"key": "A","text": "No pain at all"},{"key": "B","text": "Night pain relieved dramatically by NSAIDs"},{"key": "C","text": "Painless swelling only"},{"key": "D","text": "Pain worsened by rest"}],"correct": "B","explanation": "Osteoid osteoma causes characteristic nocturnal pain due to prostaglandin production, relieved by NSAIDs."},{"id": 3810,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Frozen shoulder (adhesive capsulitis) primarily involves:","options": [{"key": "A","text": "Bony ankylosis"},{"key": "B","text": "Labral tear"},{"key": "C","text": "Fibrosis and contracture of the glenohumeral joint capsule"},{"key": "D","text": "Rotator cuff tear only"}],"correct": "C","explanation": "Adhesive capsulitis causes progressive capsular fibrosis and contracture, severely limiting shoulder ROM — key physiotherapy condition."},{"id": 3811,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Rotator cuff tendinopathy most commonly affects which tendon?","options": [{"key": "A","text": "Teres minor"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Infraspinatus only"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "The supraspinatus tendon is most vulnerable to impingement and degenerative tears due to its anatomical course."},{"id": 3812,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Tennis elbow (lateral epicondylitis) involves degeneration of which tendon origin?","options": [{"key": "A","text": "Triceps tendon"},{"key": "B","text": "Biceps tendon"},{"key": "C","text": "Flexor carpi radialis"},{"key": "D","text": "Extensor carpi radialis brevis"}],"correct": "D","explanation": "Lateral epicondylitis involves microtears and degeneration at the ECRB tendon origin from repetitive wrist extension."},{"id": 3813,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Golfer's elbow (medial epicondylitis) affects which muscle group origin?","options": [{"key": "A","text": "Common extensor tendon origin"},{"key": "B","text": "Biceps insertion"},{"key": "C","text": "Triceps insertion"},{"key": "D","text": "Common flexor-pronator tendon origin"}],"correct": "D","explanation": "Medial epicondylitis involves the flexor-pronator tendon origin from repetitive wrist flexion/pronation."},{"id": 3814,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Achilles tendinopathy histologically shows:","options": [{"key": "A","text": "Complete tendon calcification"},{"key": "B","text": "Degenerative changes with disorganized collagen (tendinosis), often non-inflammatory"},{"key": "C","text": "Pure acute inflammation only"},{"key": "D","text": "Bone formation within tendon"}],"correct": "B","explanation": "Chronic Achilles tendinopathy is largely a degenerative process (tendinosis) rather than pure inflammation."},{"id": 3815,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Plantar fasciitis is characterized by:","options": [{"key": "A","text": "Nerve entrapment only"},{"key": "B","text": "Bone tumor"},{"key": "C","text": "Bacterial infection of the foot"},{"key": "D","text": "Degenerative thickening and microtears of the plantar fascia at calcaneal origin"}],"correct": "D","explanation": "Repetitive strain causes microtears and thickening of the plantar fascia at its calcaneal attachment."},{"id": 3816,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Carpal tunnel syndrome results from compression of which nerve?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "A","explanation": "CTS results from median nerve compression within the carpal tunnel, causing numbness in the thumb-radial fingers."},{"id": 3817,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cubital tunnel syndrome involves compression of which nerve?","options": [{"key": "A","text": "Axillary nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Ulnar nerve entrapment at the elbow (cubital tunnel) causes numbness in the ring/little fingers."},{"id": 3818,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Meniscal tears of the knee most commonly affect which meniscus due to lower mobility?","options": [{"key": "A","text": "Lateral meniscus"},{"key": "B","text": "Neither, they don't tear"},{"key": "C","text": "Medial meniscus"},{"key": "D","text": "Both equally always"}],"correct": "C","explanation": "The medial meniscus is more firmly attached and less mobile, making it more susceptible to tears."},{"id": 3819,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Anterior cruciate ligament (ACL) injury commonly results from:","options": [{"key": "A","text": "Direct anterior blow to tibia only"},{"key": "B","text": "Sudden deceleration with pivoting/twisting of the knee"},{"key": "C","text": "Aging degeneration only"},{"key": "D","text": "Chronic overuse only"}],"correct": "B","explanation": "ACL tears classically occur with non-contact pivoting or sudden deceleration mechanisms in sports."},{"id": 3820,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Osteochondritis dissecans involves:","options": [{"key": "A","text": "Separation of a fragment of articular cartilage and subchondral bone due to avascular necrosis"},{"key": "B","text": "Ligament rupture"},{"key": "C","text": "Bone infection"},{"key": "D","text": "Pure cartilage inflammation"}],"correct": "A","explanation": "OCD results from localized avascular necrosis causing a bone-cartilage fragment to separate, often in the knee of young athletes."},{"id": 3821,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Avascular necrosis of the femoral head is commonly associated with:","options": [{"key": "A","text": "Estrogen excess"},{"key": "B","text": "Corticosteroid use and alcohol abuse"},{"key": "C","text": "Vitamin A toxicity"},{"key": "D","text": "Vitamin C deficiency"}],"correct": "B","explanation": "Chronic steroid use and alcoholism are major risk factors for femoral head avascular necrosis by disrupting blood supply."},{"id": 3822,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Legg-Calve-Perthes disease is avascular necrosis of the femoral head occurring in:","options": [{"key": "A","text": "Neonates"},{"key": "B","text": "Children (typically 4-10 years)"},{"key": "C","text": "Adults over 60"},{"key": "D","text": "Adolescent females only"}],"correct": "B","explanation": "Perthes disease is idiopathic femoral head AVN in young children, causing hip pain and limp."},{"id": 3823,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Slipped capital femoral epiphysis typically occurs in:","options": [{"key": "A","text": "Neonates"},{"key": "B","text": "Young children under 5"},{"key": "C","text": "Obese adolescents during growth spurt"},{"key": "D","text": "Elderly patients"}],"correct": "C","explanation": "SCFE occurs when the femoral epiphysis slips through the growth plate, common in obese adolescent boys."},{"id": 3824,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Developmental dysplasia of the hip (DDH) refers to:","options": [{"key": "A","text": "Adult hip osteoarthritis"},{"key": "B","text": "Femoral fracture"},{"key": "C","text": "Avascular necrosis in adults"},{"key": "D","text": "Abnormal development of the hip joint leading to instability/dislocation in infants"}],"correct": "D","explanation": "DDH is a spectrum from mild instability to complete hip dislocation present from infancy, requiring early physiotherapy screening."},{"id": 3825,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Scoliosis is defined as:","options": [{"key": "A","text": "Lateral curvature of the spine with vertebral rotation"},{"key": "B","text": "Forward curvature of the spine only"},{"key": "C","text": "Loss of lumbar lordosis only"},{"key": "D","text": "Fusion of vertebral bodies"}],"correct": "A","explanation": "Scoliosis involves an abnormal lateral spinal curve, often combined with vertebral rotation."},{"id": 3826,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Kyphosis refers to:","options": [{"key": "A","text": "Exaggerated posterior (outward) curvature of the thoracic spine"},{"key": "B","text": "Fusion of the spine"},{"key": "C","text": "Lateral curvature"},{"key": "D","text": "Exaggerated lumbar lordosis"}],"correct": "A","explanation": "Kyphosis is an excessive convex curvature typically of the thoracic spine, e.g., in osteoporotic compression fractures."},{"id": 3827,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Spondylolisthesis refers to:","options": [{"key": "A","text": "Forward slippage of one vertebra over another"},{"key": "B","text": "Fusion of facet joints"},{"key": "C","text": "Disc herniation only"},{"key": "D","text": "Lateral curvature of spine"}],"correct": "A","explanation": "Spondylolisthesis is anterior displacement of a vertebral body relative to the one below, often due to pars defect."},{"id": 3828,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Intervertebral disc herniation most commonly compresses which structure causing sciatica?","options": [{"key": "A","text": "Nerve root (e.g., L5 or S1)"},{"key": "B","text": "Spinal artery only"},{"key": "C","text": "Vertebral body"},{"key": "D","text": "Anterior longitudinal ligament"}],"correct": "A","explanation": "Posterolateral disc herniation commonly compresses the exiting/traversing nerve root, causing radicular sciatic pain."},{"id": 3829,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cauda equina syndrome results from compression of:","options": [{"key": "A","text": "Cervical spinal cord"},{"key": "B","text": "Brainstem"},{"key": "C","text": "Lumbosacral nerve roots below the conus medullaris"},{"key": "D","text": "Cerebral cortex"}],"correct": "C","explanation": "Cauda equina syndrome is a surgical emergency from compression of the lumbosacral nerve root bundle, causing bowel/bladder dysfunction."},{"id": 3830,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Torticollis (wry neck) in infants is commonly due to:","options": [{"key": "A","text": "Brachial plexus injury"},{"key": "B","text": "Fibrosis/shortening of the sternocleidomastoid muscle"},{"key": "C","text": "Congenital scoliosis"},{"key": "D","text": "Cervical vertebral fracture"}],"correct": "B","explanation": "Congenital muscular torticollis results from SCM fibrosis, often from intrauterine positioning or birth trauma."},{"id": 3831,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Dupuytren's contracture involves fibrotic thickening of:","options": [{"key": "A","text": "Rotator cuff"},{"key": "B","text": "Palmar fascia"},{"key": "C","text": "Achilles tendon"},{"key": "D","text": "Plantar fascia"}],"correct": "B","explanation": "Dupuytren's contracture is progressive fibrosis of the palmar fascia causing finger flexion deformity."},{"id": 3832,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Trigger finger results from:","options": [{"key": "A","text": "Nodular thickening of the flexor tendon causing catching in the pulley"},{"key": "B","text": "Bone spur formation"},{"key": "C","text": "Extensor tendon rupture"},{"key": "D","text": "Nerve entrapment only"}],"correct": "A","explanation": "A nodule on the flexor tendon catches at the A1 pulley, causing the finger to lock/trigger during movement."},{"id": 3833,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Costochondritis refers to inflammation of:","options": [{"key": "A","text": "Sternoclavicular joint only"},{"key": "B","text": "Costochondral (rib-cartilage) junctions"},{"key": "C","text": "Vertebral joints"},{"key": "D","text": "Shoulder joint"}],"correct": "B","explanation": "Costochondritis is inflammation at the junction of ribs and costal cartilage, causing localized chest wall pain."},{"id": 3834,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Myositis ossificans is characterized by:","options": [{"key": "A","text": "Muscle atrophy only"},{"key": "B","text": "Heterotopic bone formation within muscle tissue after trauma"},{"key": "C","text": "Joint fusion"},{"key": "D","text": "Tendon calcification only"}],"correct": "B","explanation": "Myositis ossificans involves abnormal bone formation within injured muscle, important for physiotherapy timing of mobilization."},{"id": 3835,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which of the following is a classic complication of prolonged immobilization relevant to physiotherapy?","options": [{"key": "A","text": "Muscle hypertrophy"},{"key": "B","text": "Improved joint mobility"},{"key": "C","text": "Muscle atrophy, joint contracture, and osteoporosis"},{"key": "D","text": "Increased bone density"}],"correct": "C","explanation": "Prolonged immobility causes disuse atrophy, contractures, and accelerated bone loss, all central concerns in rehabilitation."},{"id": 3836,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Heterotopic ossification following spinal cord injury or severe trauma refers to:","options": [{"key": "A","text": "Cartilage degeneration"},{"key": "B","text": "Loss of bone density"},{"key": "C","text": "Abnormal bone formation in soft tissue around joints"},{"key": "D","text": "Muscle wasting"}],"correct": "C","explanation": "Heterotopic ossification is ectopic bone formation in periarticular soft tissue, a known complication after SCI/trauma affecting rehab."},{"id": 3837,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Septic arthritis is a medical emergency most commonly caused by:","options": [{"key": "A","text": "Neisseria meningitidis"},{"key": "B","text": "Staphylococcus aureus"},{"key": "C","text": "Streptococcus viridans"},{"key": "D","text": "Mycobacterium tuberculosis"}],"correct": "B","explanation": "S. aureus is the leading cause of septic arthritis, requiring urgent drainage to prevent cartilage destruction."},{"id": 3838,"subject": "Pathology","topic": "Infectious Disease","difficulty": "Medium","question": "Reactive arthritis classically follows infection of which systems?","options": [{"key": "A","text": "Respiratory tract only"},{"key": "B","text": "Gastrointestinal or genitourinary tract"},{"key": "C","text": "Skin only"},{"key": "D","text": "CNS only"}],"correct": "B","explanation": "Reactive arthritis develops after GI (Salmonella, Shigella) or GU (Chlamydia) infections, part of seronegative spondyloarthropathies."},{"id": 3839,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Psoriatic arthritis characteristically causes which finger deformity?","options": [{"key": "A","text": "Swan neck deformity only"},{"key": "B","text": "Boutonniere deformity only"},{"key": "C","text": "Dactylitis (sausage digit)"},{"key": "D","text": "Heberden's nodes only"}],"correct": "C","explanation": "Psoriatic arthritis causes diffuse swelling of an entire digit (dactylitis), a distinguishing feature."},{"id": 3840,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Heberden's nodes in osteoarthritis occur at which joint?","options": [{"key": "A","text": "Metacarpophalangeal joints"},{"key": "B","text": "Wrist joint"},{"key": "C","text": "Proximal interphalangeal joints"},{"key": "D","text": "Distal interphalangeal (DIP) joints"}],"correct": "D","explanation": "Heberden's nodes are bony swellings at the DIP joints, classic in hand osteoarthritis."},{"id": 3841,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Bouchard's nodes occur at which joint in osteoarthritis?","options": [{"key": "A","text": "Distal interphalangeal joints"},{"key": "B","text": "Wrist"},{"key": "C","text": "Proximal interphalangeal (PIP) joints"},{"key": "D","text": "Metacarpophalangeal joints"}],"correct": "C","explanation": "Bouchard's nodes are bony enlargements at the PIP joints, distinguishing from Heberden's nodes at DIP."},{"id": 3842,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Fracture healing begins with formation of which initial structure?","options": [{"key": "A","text": "Hematoma"},{"key": "B","text": "Woven bone"},{"key": "C","text": "Callus"},{"key": "D","text": "Lamellar bone"}],"correct": "A","explanation": "Fracture healing starts with hematoma formation at the fracture site within hours of injury."},{"id": 3843,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "The soft callus stage of fracture healing is composed mainly of:","options": [{"key": "A","text": "Cartilage and fibrous tissue"},{"key": "B","text": "Compact cortical bone"},{"key": "C","text": "Mature lamellar bone"},{"key": "D","text": "Hematoma only"}],"correct": "A","explanation": "Soft callus (procallus) consists of fibrocartilage bridging the fracture, later ossified into hard callus."},{"id": 3844,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Nonunion of a fracture refers to:","options": [{"key": "A","text": "Failure of bone healing beyond expected time with no radiographic progression"},{"key": "B","text": "Delayed but eventual complete healing"},{"key": "C","text": "Excess bone formation"},{"key": "D","text": "Malalignment with healing"}],"correct": "A","explanation": "Nonunion is complete failure of the healing process, requiring surgical intervention."},{"id": 3845,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Malunion of a fracture refers to:","options": [{"key": "A","text": "Complete failure to heal"},{"key": "B","text": "Healing in an abnormal/deformed position"},{"key": "C","text": "Infection at fracture site"},{"key": "D","text": "Excess callus formation only"}],"correct": "B","explanation": "Malunion describes a fracture that heals but in unacceptable alignment, angulation, or rotation."},{"id": 3846,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "A greenstick fracture is characteristic of:","options": [{"key": "A","text": "Elderly osteoporotic bone"},{"key": "B","text": "Stress fracture in athletes"},{"key": "C","text": "Pathological fracture from tumor"},{"key": "D","text": "Pediatric bone (incomplete fracture with bending)"}],"correct": "D","explanation": "Greenstick fractures occur in children due to the greater flexibility and incomplete ossification of young bone."},{"id": 3847,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pathological fracture refers to a fracture that occurs:","options": [{"key": "A","text": "Only in children"},{"key": "B","text": "Only in athletes"},{"key": "C","text": "Through bone already weakened by disease (e.g., tumor, osteoporosis)"},{"key": "D","text": "Due to a single high-impact trauma in normal bone"}],"correct": "C","explanation": "Pathological fractures occur with minimal trauma in bone weakened by an underlying condition like metastasis or osteoporosis."},{"id": 3848,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Stress fracture results from:","options": [{"key": "A","text": "Bone tumor"},{"key": "B","text": "Repetitive submaximal loading causing microdamage accumulation"},{"key": "C","text": "Single acute high-energy trauma"},{"key": "D","text": "Infection"}],"correct": "B","explanation": "Stress fractures develop from repeated mechanical loading exceeding the bone's repair capacity, common in athletes/military recruits."},{"id": 3849,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Colles' fracture involves fracture of the distal radius with:","options": [{"key": "A","text": "Volar (anterior) displacement"},{"key": "B","text": "Fracture of the ulna only"},{"key": "C","text": "Dorsal (posterior) displacement"},{"key": "D","text": "No displacement"}],"correct": "C","explanation": "Colles' fracture, typically from a fall on an outstretched hand, shows dorsal displacement of the distal fragment ('dinner fork' deformity)."},{"id": 3850,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Smith's fracture differs from Colles' fracture in that it shows:","options": [{"key": "A","text": "Fracture of the scaphoid"},{"key": "B","text": "Volar (anterior) displacement of the distal radius"},{"key": "C","text": "Dorsal displacement"},{"key": "D","text": "Fracture of the ulna styloid only"}],"correct": "B","explanation": "Smith's fracture is the reverse of Colles', with volar displacement, typically from a fall onto a flexed wrist."},{"id": 3851,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Hard","question": "The scaphoid bone is prone to avascular necrosis after fracture due to:","options": [{"key": "A","text": "No blood supply at all"},{"key": "B","text": "Retrograde blood supply entering distally"},{"key": "C","text": "Direct arterial supply to all poles"},{"key": "D","text": "Rich proximal blood supply"}],"correct": "B","explanation": "The scaphoid's blood supply enters distally and flows retrograde, making the proximal pole vulnerable to AVN after fracture."},{"id": 3852,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Which muscle disease shows characteristic 'ragged red fibers' on biopsy?","options": [{"key": "A","text": "Polymyositis"},{"key": "B","text": "Duchenne muscular dystrophy"},{"key": "C","text": "Mitochondrial myopathy"},{"key": "D","text": "Myasthenia gravis"}],"correct": "C","explanation": "Ragged red fibers on modified Gomori trichrome stain are characteristic of mitochondrial myopathies."},{"id": 3853,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Congenital myotonic dystrophy is characterized by:","options": [{"key": "A","text": "Pure sensory loss"},{"key": "B","text": "Joint hypermobility only"},{"key": "C","text": "Delayed muscle relaxation after contraction (myotonia) with progressive weakness"},{"key": "D","text": "Bone deformity only"}],"correct": "C","explanation": "Myotonic dystrophy causes sustained muscle contraction (myotonia) along with progressive muscle weakness and wasting."},{"id": 3854,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Polio (poliomyelitis) causes paralysis due to destruction of:","options": [{"key": "A","text": "Peripheral nerve myelin only"},{"key": "B","text": "Sensory dorsal root ganglia"},{"key": "C","text": "Neuromuscular junction"},{"key": "D","text": "Anterior horn motor neurons"}],"correct": "D","explanation": "Poliovirus selectively destroys anterior horn cells, causing asymmetric flaccid paralysis without sensory loss."},{"id": 3855,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Post-polio syndrome refers to:","options": [{"key": "A","text": "Complete recovery without sequelae"},{"key": "B","text": "Immediate paralysis during acute infection"},{"key": "C","text": "A different viral infection"},{"key": "D","text": "New weakness/fatigue decades after initial polio recovery"}],"correct": "D","explanation": "Post-polio syndrome presents as new muscle weakness and fatigue years after apparent recovery from acute polio."},{"id": 3856,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Erb's palsy results from injury to which brachial plexus roots?","options": [{"key": "A","text": "C7 only"},{"key": "B","text": "C8-T1"},{"key": "C","text": "C5-C6"},{"key": "D","text": "T1-T2"}],"correct": "C","explanation": "Erb's palsy (upper brachial plexus injury) affects C5-C6, causing the classic 'waiter's tip' arm posture."},{"id": 3857,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Klumpke's palsy results from injury to which brachial plexus roots?","options": [{"key": "A","text": "C8-T1"},{"key": "B","text": "C4 only"},{"key": "C","text": "C6-C7"},{"key": "D","text": "C5-C6"}],"correct": "A","explanation": "Klumpke's palsy (lower plexus injury) affects C8-T1, causing claw hand deformity with intrinsic hand muscle weakness."},{"id": 3858,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Foot drop is most commonly caused by injury to which nerve?","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Common peroneal (fibular) nerve"},{"key": "D","text": "Tibial nerve"}],"correct": "C","explanation": "Common peroneal nerve injury, often at the fibular head, causes weakness of ankle dorsiflexion resulting in foot drop."},{"id": 3859,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Waddling (Trendelenburg) gait is characteristic of weakness in which muscle?","options": [{"key": "A","text": "Tibialis anterior"},{"key": "B","text": "Gastrocnemius"},{"key": "C","text": "Quadriceps femoris"},{"key": "D","text": "Gluteus medius"}],"correct": "D","explanation": "Gluteus medius weakness fails to stabilize the pelvis during single-limb stance, producing a Trendelenburg gait pattern."},{"id": 3860,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Which of the following best differentiates neuropathic from myopathic muscle weakness on EMG?","options": [{"key": "A","text": "Both show identical EMG findings"},{"key": "B","text": "Neuropathic shows no denervation changes"},{"key": "C","text": "Myopathic shows increased motor unit amplitude"},{"key": "D","text": "Neuropathic shows large amplitude, long duration motor unit potentials with fibrillations"}],"correct": "D","explanation": "Neuropathic disorders show denervation potentials (fibrillations) and reinnervation changes with large motor units; myopathies show small, short-duration units."},{"id": 3861,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Charcot joint (neuropathic arthropathy) results from:","options": [{"key": "A","text": "Autoimmune synovitis"},{"key": "B","text": "Bone tumor"},{"key": "C","text": "Loss of proprioceptive/pain sensation leading to repeated joint trauma"},{"key": "D","text": "Bacterial infection"}],"correct": "C","explanation": "Sensory neuropathy (e.g., diabetes, syringomyelia) leads to unrecognized repetitive joint trauma and destruction."},{"id": 3862,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Ischemic stroke is most commonly caused by:","options": [{"key": "A","text": "Venous sinus thrombosis only"},{"key": "B","text": "Vasculitis only"},{"key": "C","text": "Rupture of a cerebral vessel"},{"key": "D","text": "Thrombotic or embolic occlusion of cerebral arteries"}],"correct": "D","explanation": "Ischemic stroke, the most common stroke type, results from thrombus or embolus occluding cerebral blood flow."},{"id": 3863,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Hemorrhagic stroke most commonly results from:","options": [{"key": "A","text": "Atherosclerotic plaque embolization"},{"key": "B","text": "Vasospasm only"},{"key": "C","text": "Rupture of blood vessel, often due to chronic hypertension"},{"key": "D","text": "Venous stasis"}],"correct": "C","explanation": "Chronic hypertension causes microaneurysms (Charcot-Bouchard) that rupture, leading to intracerebral hemorrhage."},{"id": 3864,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Charcot-Bouchard aneurysms are classically found in which vessels?","options": [{"key": "A","text": "Small penetrating arteries of the basal ganglia/thalamus"},{"key": "B","text": "Carotid artery"},{"key": "C","text": "Aorta"},{"key": "D","text": "Circle of Willis large vessels"}],"correct": "A","explanation": "These microaneurysms develop in small vessels due to chronic hypertension, predisposing to intracerebral hemorrhage."},{"id": 3865,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "A transient ischemic attack (TIA) is defined as:","options": [{"key": "A","text": "Permanent neurological deficit"},{"key": "B","text": "Progressive neurodegeneration"},{"key": "C","text": "Deficit lasting more than 24 hours"},{"key": "D","text": "Neurological deficit resolving completely within 24 hours without infarction"}],"correct": "D","explanation": "TIA involves temporary ischemia with symptom resolution and no evidence of permanent infarction on imaging."},{"id": 3866,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Middle cerebral artery (MCA) stroke commonly causes:","options": [{"key": "A","text": "Bilateral leg paralysis"},{"key": "B","text": "Contralateral face and arm weakness more than leg"},{"key": "C","text": "Contralateral leg weakness more than arm"},{"key": "D","text": "Isolated visual loss only"}],"correct": "B","explanation": "MCA territory strokes affect the lateral cortex controlling face/arm more than the leg (which is supplied by ACA)."},{"id": 3867,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Anterior cerebral artery (ACA) stroke characteristically causes:","options": [{"key": "A","text": "Contralateral face weakness more than leg"},{"key": "B","text": "Contralateral leg weakness more than arm/face"},{"key": "C","text": "Isolated aphasia only"},{"key": "D","text": "Homonymous hemianopia primarily"}],"correct": "B","explanation": "ACA supplies the medial cortex controlling the leg, so ACA strokes cause leg-predominant weakness."},{"id": 3868,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Posterior cerebral artery (PCA) stroke typically causes:","options": [{"key": "A","text": "Aphasia primarily"},{"key": "B","text": "Pure motor weakness of arm"},{"key": "C","text": "Contralateral homonymous hemianopia"},{"key": "D","text": "Isolated leg weakness"}],"correct": "C","explanation": "PCA supplies the occipital lobe/visual cortex, so its occlusion causes visual field deficits like homonymous hemianopia."},{"id": 3869,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Brown-Sequard syndrome results from hemisection of the spinal cord causing:","options": [{"key": "A","text": "Ipsilateral motor/proprioceptive loss and contralateral pain/temperature loss"},{"key": "B","text": "Bilateral complete paralysis"},{"key": "C","text": "Isolated bladder dysfunction"},{"key": "D","text": "Only sensory loss bilaterally"}],"correct": "A","explanation": "Hemisection damages ipsilateral corticospinal/dorsal column and contralateral spinothalamic tract fibers, producing this classic dissociated pattern."},{"id": 3870,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Complete spinal cord transection results in loss of all function below the lesion, termed:","options": [{"key": "A","text": "Spinal shock followed by paraplegia/tetraplegia"},{"key": "B","text": "Localized sensory loss only"},{"key": "C","text": "Normal function preserved"},{"key": "D","text": "Isolated motor loss with normal sensation"}],"correct": "A","explanation": "Complete transection causes initial spinal shock, followed by permanent loss of motor/sensory/autonomic function below the level."},{"id": 3871,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Anterior cord syndrome typically results in:","options": [{"key": "A","text": "Loss of motor function and pain/temperature sensation with preserved proprioception"},{"key": "B","text": "Loss of proprioception only"},{"key": "C","text": "Pure sensory loss with normal motor function"},{"key": "D","text": "Loss of motor function only, no sensory loss"}],"correct": "A","explanation": "Anterior spinal artery infarction affects the anterior 2/3 of the cord, sparing the posterior columns (proprioception/vibration)."},{"id": 3872,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Central cord syndrome classically causes:","options": [{"key": "A","text": "Greater weakness in lower limbs than upper limbs"},{"key": "B","text": "Pure sensory loss without motor involvement"},{"key": "C","text": "Greater weakness in upper limbs than lower limbs"},{"key": "D","text": "Complete paralysis of all limbs equally"}],"correct": "C","explanation": "Central cord syndrome, often from hyperextension injury in cervical spondylosis, disproportionately affects upper limb motor function."},{"id": 3873,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Parkinson's disease pathologically involves degeneration of which structure?","options": [{"key": "A","text": "Anterior horn cells"},{"key": "B","text": "Substantia nigra (dopaminergic neurons)"},{"key": "C","text": "Corpus callosum"},{"key": "D","text": "Cerebellum"}],"correct": "B","explanation": "Parkinson's disease results from loss of dopaminergic neurons in the substantia nigra pars compacta."},{"id": 3874,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Lewy bodies, the pathological hallmark of Parkinson's disease, are composed mainly of:","options": [{"key": "A","text": "Alpha-synuclein aggregates"},{"key": "B","text": "Tau protein"},{"key": "C","text": "Prion protein"},{"key": "D","text": "Amyloid-beta"}],"correct": "A","explanation": "Lewy bodies are eosinophilic intracytoplasmic inclusions primarily composed of misfolded alpha-synuclein."},{"id": 3875,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Alzheimer's disease is characterized pathologically by:","options": [{"key": "A","text": "Lewy bodies"},{"key": "B","text": "Anterior horn cell loss"},{"key": "C","text": "Demyelination of white matter"},{"key": "D","text": "Amyloid plaques and neurofibrillary tangles (tau)"}],"correct": "D","explanation": "Alzheimer's shows extracellular amyloid-beta plaques and intracellular tau-based neurofibrillary tangles."},{"id": 3876,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Amyotrophic lateral sclerosis (ALS) involves degeneration of:","options": [{"key": "A","text": "Basal ganglia only"},{"key": "B","text": "Sensory neurons only"},{"key": "C","text": "Both upper and lower motor neurons"},{"key": "D","text": "Cerebellum only"}],"correct": "C","explanation": "ALS is a progressive motor neuron disease affecting both upper (corticospinal) and lower (anterior horn) motor neurons, sparing sensation."},{"id": 3877,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Multiple sclerosis lesions (plaques) are best visualized using which imaging modality?","options": [{"key": "A","text": "Ultrasound"},{"key": "B","text": "X-ray"},{"key": "C","text": "MRI"},{"key": "D","text": "CT scan"}],"correct": "C","explanation": "MRI is highly sensitive for detecting demyelinating plaques in MS, particularly on T2/FLAIR sequences."},{"id": 3878,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Charcot's neurologic triad (in classic MS presentation) includes:","options": [{"key": "A","text": "Rigidity, bradykinesia, tremor"},{"key": "B","text": "Weakness, spasticity, hyperreflexia only"},{"key": "C","text": "Nystagmus, intention tremor, scanning speech"},{"key": "D","text": "Ataxia, areflexia, sensory loss"}],"correct": "C","explanation": "The classic Charcot triad reflects cerebellar involvement in multiple sclerosis."},{"id": 3879,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Guillain-Barre syndrome typically presents with:","options": [{"key": "A","text": "Ascending symmetric flaccid paralysis with areflexia"},{"key": "B","text": "Descending paralysis starting from face"},{"key": "C","text": "Pure sensory symptoms without weakness"},{"key": "D","text": "Asymmetric spastic paralysis"}],"correct": "A","explanation": "GBS classically causes rapidly progressive ascending weakness starting distally, with loss of deep tendon reflexes."},{"id": 3880,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Cerebral palsy results from:","options": [{"key": "A","text": "Progressive neurodegeneration in adulthood"},{"key": "B","text": "Non-progressive brain injury occurring during the perinatal period"},{"key": "C","text": "Genetic muscular dystrophy"},{"key": "D","text": "Autoimmune demyelination"}],"correct": "B","explanation": "CP is a static encephalopathy from brain injury/malformation around birth, causing motor impairment though non-progressive."},{"id": 3881,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Spastic cerebral palsy, the most common type, results from damage to:","options": [{"key": "A","text": "Cerebellum primarily"},{"key": "B","text": "Upper motor neurons/corticospinal tract"},{"key": "C","text": "Basal ganglia primarily"},{"key": "D","text": "Peripheral nerves"}],"correct": "B","explanation": "Spastic CP results from upper motor neuron damage causing increased muscle tone and hyperreflexia."},{"id": 3882,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Dyskinetic (athetoid) cerebral palsy results from damage to which structure?","options": [{"key": "A","text": "Basal ganglia"},{"key": "B","text": "Peripheral nerves"},{"key": "C","text": "Corticospinal tract only"},{"key": "D","text": "Spinal cord"}],"correct": "A","explanation": "Athetoid CP results from basal ganglia injury (often kernicterus), causing involuntary writhing movements."},{"id": 3883,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ataxic cerebral palsy results from damage to which structure?","options": [{"key": "A","text": "Peripheral nerve"},{"key": "B","text": "Corticospinal tract"},{"key": "C","text": "Cerebellum"},{"key": "D","text": "Basal ganglia"}],"correct": "C","explanation": "Ataxic CP results from cerebellar damage/dysfunction, causing impaired coordination and balance."},{"id": 3884,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Kernicterus, a cause of dyskinetic cerebral palsy, results from:","options": [{"key": "A","text": "Hypoxic injury to cortex"},{"key": "B","text": "Bilirubin toxicity to basal ganglia in neonates"},{"key": "C","text": "Congenital infection"},{"key": "D","text": "Traumatic brain injury"}],"correct": "B","explanation": "Severe neonatal hyperbilirubinemia deposits in basal ganglia, causing kernicterus and subsequent dyskinetic CP."},{"id": 3885,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Spina bifida occulta is characterized by:","options": [{"key": "A","text": "Complete absence of vertebrae"},{"key": "B","text": "Incomplete closure of vertebral arch without protrusion of neural tissue"},{"key": "C","text": "Absence of the brain"},{"key": "D","text": "Complete protrusion of spinal cord and meninges"}],"correct": "B","explanation": "Spina bifida occulta is the mildest form, with a vertebral defect but no herniation of neural elements."},{"id": 3886,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Meningomyelocele, a severe form of spina bifida, involves protrusion of:","options": [{"key": "A","text": "Brain tissue only"},{"key": "B","text": "No neural tissue at all"},{"key": "C","text": "Meninges and spinal cord/nerve roots through the vertebral defect"},{"key": "D","text": "Meninges only"}],"correct": "C","explanation": "Meningomyelocele is a severe neural tube defect with herniation of both meninges and neural tissue, causing significant motor/sensory deficits."},{"id": 3887,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Syringomyelia refers to:","options": [{"key": "A","text": "Formation of a fluid-filled cavity (syrinx) within the spinal cord"},{"key": "B","text": "Spinal cord infarction"},{"key": "C","text": "Demyelination of peripheral nerves"},{"key": "D","text": "Vertebral fracture"}],"correct": "A","explanation": "Syringomyelia creates a cystic cavity in the cord, classically causing 'cape-like' loss of pain/temperature sensation."},{"id": 3888,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Glioblastoma multiforme is the most aggressive tumor arising from:","options": [{"key": "A","text": "Ependymal cells"},{"key": "B","text": "Meninges"},{"key": "C","text": "Schwann cells"},{"key": "D","text": "Astrocytes"}],"correct": "D","explanation": "GBM is a highly malignant astrocytoma, the most common primary malignant brain tumor in adults."},{"id": 3889,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Meningioma arises from which cell type?","options": [{"key": "A","text": "Oligodendrocytes"},{"key": "B","text": "Astrocytes"},{"key": "C","text": "Arachnoid cap cells of the meninges"},{"key": "D","text": "Neurons"}],"correct": "C","explanation": "Meningiomas are typically benign tumors arising from arachnoid cap cells, usually extra-axial."},{"id": 3890,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Schwannoma (acoustic neuroma) most commonly affects which cranial nerve?","options": [{"key": "A","text": "Trigeminal nerve (CN V)"},{"key": "B","text": "Vestibulocochlear nerve (CN VIII)"},{"key": "C","text": "Facial nerve (CN VII)"},{"key": "D","text": "Optic nerve (CN II)"}],"correct": "B","explanation": "Acoustic neuromas arise from Schwann cells of the vestibular portion of CN VIII, causing hearing loss and balance issues."},{"id": 3891,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Bacterial meningitis in adults is most commonly caused by:","options": [{"key": "A","text": "Listeria monocytogenes"},{"key": "B","text": "Streptococcus pneumoniae"},{"key": "C","text": "Neisseria gonorrhoeae"},{"key": "D","text": "Haemophilus influenzae"}],"correct": "B","explanation": "S. pneumoniae is the leading cause of community-acquired bacterial meningitis in adults."},{"id": 3892,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "CSF findings in bacterial meningitis typically show:","options": [{"key": "A","text": "Normal cell count with high glucose"},{"key": "B","text": "Increased neutrophils, increased protein, decreased glucose"},{"key": "C","text": "Decreased protein with normal glucose"},{"key": "D","text": "Increased lymphocytes, normal glucose"}],"correct": "B","explanation": "Bacterial meningitis classically shows neutrophilic pleocytosis, elevated protein, and low glucose (bacteria consume glucose)."},{"id": 3893,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Viral meningitis CSF typically shows:","options": [{"key": "A","text": "No cells at all"},{"key": "B","text": "Neutrophilic pleocytosis with low glucose"},{"key": "C","text": "Lymphocytic pleocytosis with normal glucose"},{"key": "D","text": "Extremely high protein with low glucose"}],"correct": "C","explanation": "Viral meningitis shows a lymphocyte-predominant CSF with normal glucose, distinguishing it from bacterial meningitis."},{"id": 3894,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Epilepsy is defined as:","options": [{"key": "A","text": "Loss of consciousness from any cause"},{"key": "B","text": "Fever-induced seizure in children"},{"key": "C","text": "A tendency toward recurrent unprovoked seizures"},{"key": "D","text": "A single seizure episode only"}],"correct": "C","explanation": "Epilepsy is a chronic condition characterized by recurrent, unprovoked epileptic seizures."},{"id": 3895,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Status epilepticus is defined as:","options": [{"key": "A","text": "Seizure with full recovery within seconds"},{"key": "B","text": "A single brief seizure"},{"key": "C","text": "Continuous seizure activity lasting more than 5 minutes or recurrent seizures without recovery"},{"key": "D","text": "Seizure lasting less than 1 minute"}],"correct": "C","explanation": "Status epilepticus is a neurological emergency requiring immediate treatment to prevent neuronal damage."},{"id": 3896,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Migraine headache is classically characterized by:","options": [{"key": "A","text": "Sudden 'thunderclap' onset always"},{"key": "B","text": "Unilateral, pulsating headache often with photophobia/phonophobia"},{"key": "C","text": "Bilateral band-like tightness without nausea"},{"key": "D","text": "Fixed, constant severe pain with fever"}],"correct": "B","explanation": "Migraines typically present as unilateral throbbing pain accompanied by sensory sensitivities and sometimes aura."},{"id": 3897,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Tension-type headache is characteristically described as:","options": [{"key": "A","text": "Bilateral, band-like/pressing pain without significant nausea"},{"key": "B","text": "Unilateral pulsating pain with aura"},{"key": "C","text": "Periorbital pain with lacrimation"},{"key": "D","text": "Explosive 'worst headache of life'"}],"correct": "A","explanation": "Tension headaches present as bilateral, non-throbbing tight/pressing pain, typically the most common headache type."},{"id": 3898,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Subarachnoid hemorrhage classically presents with:","options": [{"key": "A","text": "Chronic dull headache"},{"key": "B","text": "Gradual progressive headache over weeks"},{"key": "C","text": "Sudden severe 'thunderclap' headache"},{"key": "D","text": "Painless vision loss only"}],"correct": "C","explanation": "SAH, often from aneurysm rupture, causes an abrupt, severe headache described as 'the worst headache of my life'."},{"id": 3899,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Myasthenia gravis characteristically causes weakness that:","options": [{"key": "A","text": "Is constant regardless of activity"},{"key": "B","text": "Improves with activity"},{"key": "C","text": "Only affects sensory function"},{"key": "D","text": "Worsens with sustained activity and improves with rest (fatigability)"}],"correct": "D","explanation": "MG shows fatigable weakness due to autoantibody-mediated destruction of postsynaptic ACh receptors, worsening with repeated use."},{"id": 3900,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The edrophonium (Tensilon) test is used to diagnose:","options": [{"key": "A","text": "Multiple sclerosis"},{"key": "B","text": "Guillain-Barre syndrome"},{"key": "C","text": "Myasthenia gravis"},{"key": "D","text": "Parkinson's disease"}],"correct": "C","explanation": "Edrophonium, a short-acting acetylcholinesterase inhibitor, transiently improves strength in myasthenia gravis, aiding diagnosis."},{"id": 3901,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Diabetic peripheral neuropathy classically presents with:","options": [{"key": "A","text": "Sudden onset unilateral paralysis"},{"key": "B","text": "Pure motor deficit without sensory loss"},{"key": "C","text": "Asymmetric proximal weakness only"},{"key": "D","text": "Symmetric distal sensory loss in a 'stocking-glove' distribution"}],"correct": "D","explanation": "Chronic hyperglycemia causes symmetric length-dependent sensorimotor neuropathy, starting distally in feet/hands."},{"id": 3902,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Wallerian degeneration refers to:","options": [{"key": "A","text": "Degeneration proximal to the injury site"},{"key": "B","text": "Degeneration of the nerve fiber distal to the site of injury"},{"key": "C","text": "Death of the neuron cell body only"},{"key": "D","text": "Regeneration of myelin only"}],"correct": "B","explanation": "After axonal injury, the distal segment undergoes Wallerian degeneration while the proximal segment may regenerate."},{"id": 3903,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neurapraxia, per Seddon's classification of nerve injury, involves:","options": [{"key": "A","text": "Complete nerve transection"},{"key": "B","text": "Temporary conduction block without axonal disruption, with full recovery expected"},{"key": "C","text": "Permanent nerve damage without recovery"},{"key": "D","text": "Axonal disruption with intact connective tissue"}],"correct": "B","explanation": "Neurapraxia is the mildest nerve injury, a temporary physiological block that resolves completely, common in compression injuries."},{"id": 3904,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Axonotmesis, per Seddon's classification, involves:","options": [{"key": "A","text": "Axonal disruption with preserved connective tissue framework, allowing regeneration"},{"key": "B","text": "Instant complete recovery"},{"key": "C","text": "Complete transection of the nerve and its sheath"},{"key": "D","text": "No axonal damage at all"}],"correct": "A","explanation": "Axonotmesis disrupts the axon but preserves the surrounding connective tissue (endoneurium), allowing gradual regeneration."},{"id": 3905,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neurotmesis, the most severe nerve injury per Seddon's classification, involves:","options": [{"key": "A","text": "Complete transection of the axon and all supporting connective tissue"},{"key": "B","text": "Full spontaneous recovery expected"},{"key": "C","text": "Mild myelin damage only"},{"key": "D","text": "Temporary conduction block only"}],"correct": "A","explanation": "Neurotmesis is complete nerve disruption requiring surgical repair, with poor spontaneous recovery."},{"id": 3906,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Bell's palsy results from dysfunction of which cranial nerve?","options": [{"key": "A","text": "Hypoglossal nerve (CN XII)"},{"key": "B","text": "Trigeminal nerve (CN V)"},{"key": "C","text": "Vagus nerve (CN X)"},{"key": "D","text": "Facial nerve (CN VII)"}],"correct": "D","explanation": "Bell's palsy is an idiopathic (often viral-associated) lower motor neuron facial nerve palsy causing unilateral facial weakness."},{"id": 3907,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Vascular dementia differs from Alzheimer's dementia in that it typically shows:","options": [{"key": "A","text": "Stepwise decline related to cerebrovascular events"},{"key": "B","text": "Gradual, continuous progressive decline"},{"key": "C","text": "Amyloid plaques as the primary pathology"},{"key": "D","text": "Onset only before age 40"}],"correct": "A","explanation": "Vascular dementia often progresses in a stepwise fashion corresponding to successive ischemic events, unlike the gradual Alzheimer's course."},{"id": 3908,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Huntington's disease chorea results from degeneration primarily of which structure?","options": [{"key": "A","text": "Hippocampus"},{"key": "B","text": "Substantia nigra"},{"key": "C","text": "Caudate nucleus (striatum)"},{"key": "D","text": "Cerebellum"}],"correct": "C","explanation": "Huntington's disease causes atrophy of the caudate nucleus and putamen, producing characteristic choreiform movements."},{"id": 3909,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cerebellar lesions classically produce which movement abnormality?","options": [{"key": "A","text": "Spasticity with hyperreflexia"},{"key": "B","text": "Chorea"},{"key": "C","text": "Ataxia and dysmetria"},{"key": "D","text": "Resting tremor and rigidity"}],"correct": "C","explanation": "Cerebellar damage causes incoordination (ataxia), dysmetria, and intention tremor, distinct from basal ganglia disorders."},{"id": 3910,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Basal ganglia lesions (e.g., Parkinson's disease) classically produce:","options": [{"key": "A","text": "Ataxia and dysmetria"},{"key": "B","text": "Pure sensory loss"},{"key": "C","text": "Resting tremor, rigidity, and bradykinesia"},{"key": "D","text": "Hyperreflexia with spasticity only"}],"correct": "C","explanation": "The classic Parkinsonian triad reflects basal ganglia dopaminergic dysfunction."},{"id": 3911,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Upper motor neuron lesions classically present with:","options": [{"key": "A","text": "Spasticity, hyperreflexia, and Babinski sign present"},{"key": "B","text": "Normal reflexes throughout"},{"key": "C","text": "Flaccid paralysis with hyporeflexia"},{"key": "D","text": "Fasciculations and muscle atrophy"}],"correct": "A","explanation": "UMN lesions disinhibit spinal reflexes, causing spasticity, hyperreflexia, and an upgoing plantar (Babinski) response."},{"id": 3912,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Lower motor neuron lesions classically present with:","options": [{"key": "A","text": "Spasticity and hyperreflexia"},{"key": "B","text": "Babinski sign positive"},{"key": "C","text": "Flaccid paralysis, hyporeflexia, fasciculations, and muscle atrophy"},{"key": "D","text": "Increased muscle tone"}],"correct": "C","explanation": "LMN lesions cause loss of the direct connection to muscle, resulting in flaccidity, wasting, and reduced/absent reflexes."},{"id": 3913,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Traumatic brain injury with diffuse axonal injury typically results from:","options": [{"key": "A","text": "Localized skull fracture only"},{"key": "B","text": "Chronic degeneration"},{"key": "C","text": "Rapid acceleration-deceleration forces shearing axons"},{"key": "D","text": "Infection"}],"correct": "C","explanation": "DAI results from rotational/shearing forces during rapid deceleration, common in high-speed accidents, causing widespread axonal damage."},{"id": 3914,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "A subdural hematoma classically results from rupture of:","options": [{"key": "A","text": "Bridging veins"},{"key": "B","text": "Circle of Willis aneurysm"},{"key": "C","text": "Middle meningeal artery"},{"key": "D","text": "Basilar artery"}],"correct": "A","explanation": "Subdural hematomas arise from tearing of bridging veins between the dura and arachnoid, often after trauma, especially in elderly/atrophic brains."},{"id": 3915,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "An epidural hematoma classically results from rupture of:","options": [{"key": "A","text": "Bridging veins"},{"key": "B","text": "Posterior cerebral artery"},{"key": "C","text": "Middle meningeal artery"},{"key": "D","text": "Cerebral venous sinus"}],"correct": "C","explanation": "Epidural hematomas typically result from middle meningeal artery injury following temporal bone fracture, causing rapid arterial bleeding."},{"id": 3916,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The classic 'lucid interval' followed by rapid neurological deterioration is seen in:","options": [{"key": "A","text": "Chronic subdural hematoma"},{"key": "B","text": "Ischemic stroke"},{"key": "C","text": "Simple concussion"},{"key": "D","text": "Epidural hematoma"}],"correct": "D","explanation": "Epidural hematomas often show initial consciousness (lucid interval) before rapid deterioration as the arterial bleed expands."},{"id": 3917,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Friedreich's ataxia is inherited as:","options": [{"key": "A","text": "Autosomal dominant"},{"key": "B","text": "Mitochondrial"},{"key": "C","text": "X-linked recessive"},{"key": "D","text": "Autosomal recessive with trinucleotide (GAA) repeat expansion"}],"correct": "D","explanation": "Friedreich's ataxia results from GAA repeat expansion in the frataxin gene, causing progressive ataxia and cardiomyopathy."},{"id": 3918,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Hard","question": "Tabes dorsalis, a form of neurosyphilis, causes degeneration of:","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Anterior horn cells"},{"key": "C","text": "Corticospinal tract"},{"key": "D","text": "Posterior (dorsal) columns of the spinal cord"}],"correct": "D","explanation": "Tabes dorsalis affects the dorsal columns causing loss of proprioception and vibration sense, with sensory ataxia."},{"id": 3919,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Subacute combined degeneration of the spinal cord is caused by deficiency of:","options": [{"key": "A","text": "Vitamin B12"},{"key": "B","text": "Vitamin D"},{"key": "C","text": "Folate deficiency alone without B12"},{"key": "D","text": "Vitamin B1 (thiamine)"}],"correct": "A","explanation": "B12 deficiency causes demyelination of the dorsal columns and corticospinal tracts, producing combined sensory-motor deficits."},{"id": 3920,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Wernicke's encephalopathy results from deficiency of:","options": [{"key": "A","text": "Vitamin C"},{"key": "B","text": "Vitamin D"},{"key": "C","text": "Thiamine (Vitamin B1)"},{"key": "D","text": "Vitamin B12"}],"correct": "C","explanation": "Thiamine deficiency, often in alcoholics, causes Wernicke's encephalopathy with confusion, ataxia, and ophthalmoplegia."},{"id": 3921,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Erb-Duchenne palsy classically produces which characteristic arm position?","options": [{"key": "A","text": "Claw hand deformity"},{"key": "B","text": "Complete flaccid paralysis of the whole arm"},{"key": "C","text": "Wrist drop"},{"key": "D","text": "'Waiter's tip' position (arm adducted, internally rotated, extended)"}],"correct": "D","explanation": "Erb's palsy (C5-C6 injury) causes the classic waiter's tip posture due to loss of shoulder abduction/external rotation and elbow flexion."},{"id": 3922,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Radial nerve injury (e.g., 'Saturday night palsy') classically presents with:","options": [{"key": "A","text": "Foot drop"},{"key": "B","text": "Ape hand deformity"},{"key": "C","text": "Wrist drop"},{"key": "D","text": "Claw hand"}],"correct": "C","explanation": "Radial nerve palsy causes loss of wrist and finger extension, producing the characteristic wrist drop."},{"id": 3923,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ulnar nerve injury classically presents with which hand deformity?","options": [{"key": "A","text": "Simian hand"},{"key": "B","text": "Ape hand"},{"key": "C","text": "Claw hand (ulnar claw)"},{"key": "D","text": "Wrist drop"}],"correct": "C","explanation": "Ulnar nerve injury causes hyperextension of MCP joints and flexion of IP joints in the ring/little fingers (claw hand)."},{"id": 3924,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Median nerve injury at the wrist classically produces which hand deformity?","options": [{"key": "A","text": "Wrist drop"},{"key": "B","text": "Ape hand (loss of thenar opposition)"},{"key": "C","text": "Foot drop"},{"key": "D","text": "Claw hand"}],"correct": "B","explanation": "Median nerve injury impairs thumb opposition and abduction, leading to flattening of the thenar eminence ('ape hand')."},{"id": 3925,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Sciatic nerve injury commonly results from which of the following?","options": [{"key": "A","text": "Wrist trauma"},{"key": "B","text": "Elbow dislocation only"},{"key": "C","text": "Improperly placed intramuscular gluteal injection or hip dislocation"},{"key": "D","text": "Facial trauma"}],"correct": "C","explanation": "The sciatic nerve, coursing through the buttock, is vulnerable to injury from posterior hip dislocation or misplaced injections."},{"id": 3926,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Meralgia paresthetica results from entrapment of which nerve?","options": [{"key": "A","text": "Lateral femoral cutaneous nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Sciatic nerve"},{"key": "D","text": "Femoral nerve"}],"correct": "A","explanation": "Compression of the lateral femoral cutaneous nerve near the inguinal ligament causes anterolateral thigh numbness/tingling."},{"id": 3927,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Autonomic dysreflexia is a potentially life-threatening condition seen in patients with spinal cord injury at or above which level?","options": [{"key": "A","text": "Only in complete injuries below T10"},{"key": "B","text": "Only cervical injuries below C7"},{"key": "C","text": "Below L1"},{"key": "D","text": "T6 level or above"}],"correct": "D","explanation": "Autonomic dysreflexia occurs in SCI at or above T6, causing dangerous hypertension in response to noxious stimuli below the lesion — a critical physiotherapy safety concern."},{"id": 3928,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neurogenic bladder following spinal cord injury above the sacral level typically results in:","options": [{"key": "A","text": "Normal voluntary voiding"},{"key": "B","text": "Complete bladder areflexia always"},{"key": "C","text": "Reflexive (spastic) bladder with detrusor hyperreflexia"},{"key": "D","text": "No effect on bladder function"}],"correct": "C","explanation": "Upper motor neuron (suprasacral) SCI causes a spastic/reflexive bladder due to loss of higher inhibitory control."},{"id": 3929,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Spasticity following upper motor neuron lesions is best described as:","options": [{"key": "A","text": "Fixed, non-velocity dependent stiffness"},{"key": "B","text": "Complete loss of muscle tone"},{"key": "C","text": "Random involuntary jerking only"},{"key": "D","text": "Velocity-dependent increase in muscle tone/resistance to passive stretch"}],"correct": "D","explanation": "Spasticity is characterized by increased resistance to stretch that intensifies with the speed of passive movement, a key UMN sign."},{"id": 3930,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Rigidity, as seen in Parkinsonism, differs from spasticity in that it is:","options": [{"key": "A","text": "Only present at high velocity of movement"},{"key": "B","text": "Absent at rest"},{"key": "C","text": "Present throughout the range of motion regardless of velocity ('lead-pipe' or 'cogwheel')"},{"key": "D","text": "Only seen in lower limb muscles"}],"correct": "C","explanation": "Parkinsonian rigidity is velocity-independent, present uniformly through range, unlike the velocity-dependent nature of spasticity."},{"id": 3931,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Clonus, a sign of upper motor neuron lesion, is best described as:","options": [{"key": "A","text": "Sign of lower motor neuron disease"},{"key": "B","text": "Random muscle twitching at rest"},{"key": "C","text": "Rhythmic, involuntary muscle contractions in response to sustained stretch"},{"key": "D","text": "Voluntary rhythmic movement"}],"correct": "C","explanation": "Clonus reflects hyperexcitable stretch reflexes from UMN lesions, commonly elicited at the ankle."},{"id": 3932,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Fasciculations, indicating lower motor neuron pathology, are best described as:","options": [{"key": "A","text": "Sustained muscle contraction"},{"key": "B","text": "Increased deep tendon reflexes"},{"key": "C","text": "Visible spontaneous twitching of a motor unit"},{"key": "D","text": "Rhythmic oscillation with stretch"}],"correct": "C","explanation": "Fasciculations result from spontaneous discharge of denervated/reinnervating motor units, seen in conditions like ALS."},{"id": 3933,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Which of the following best describes decorticate posturing?","options": [{"key": "A","text": "Arms extended, legs extended, indicating brainstem lesion"},{"key": "B","text": "Arms flexed, legs extended, indicating lesion above the red nucleus"},{"key": "C","text": "Complete flaccidity"},{"key": "D","text": "Normal voluntary posture"}],"correct": "B","explanation": "Decorticate posturing (flexed arms) indicates a lesion above the midbrain red nucleus, less severe than decerebrate posturing."},{"id": 3934,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Decerebrate posturing, indicating a more severe brainstem lesion, is characterized by:","options": [{"key": "A","text": "Flexion of arms with leg extension"},{"key": "B","text": "Flaccid paralysis of all limbs"},{"key": "C","text": "Normal tone throughout"},{"key": "D","text": "Extension of both arms and legs"}],"correct": "D","explanation": "Decerebrate posturing (all extremities extended) indicates a lesion at or below the level of the red nucleus, a poor prognostic sign."},{"id": 3935,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Glasgow Coma Scale is used to assess:","options": [{"key": "A","text": "Degree of spasticity"},{"key": "B","text": "Level of consciousness after brain injury"},{"key": "C","text": "Muscle strength grading"},{"key": "D","text": "Balance and coordination"}],"correct": "B","explanation": "GCS assesses eye-opening, verbal, and motor responses to quantify consciousness level, widely used in TBI assessment."},{"id": 3936,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "A GCS score of 8 or less generally indicates:","options": [{"key": "A","text": "Mild head injury"},{"key": "B","text": "Normal consciousness"},{"key": "C","text": "Severe traumatic brain injury (comatose state)"},{"key": "D","text": "No brain injury"}],"correct": "C","explanation": "A GCS ≤ 8 is generally considered indicative of severe brain injury/coma, often requiring airway protection."},{"id": 3937,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Peripheral neuropathy due to chronic alcohol use is primarily attributed to:","options": [{"key": "A","text": "Excess vitamin intake"},{"key": "B","text": "Bacterial infection"},{"key": "C","text": "Thiamine and other B-vitamin deficiencies with direct neurotoxic effects"},{"key": "D","text": "Autoimmune destruction"}],"correct": "C","explanation": "Chronic alcohol use causes nutritional deficiencies (especially thiamine) and direct neurotoxicity leading to peripheral neuropathy."},{"id": 3938,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Cerebral edema following stroke or trauma is best classified into which main types?","options": [{"key": "A","text": "Interstitial edema only"},{"key": "B","text": "Only vasogenic edema exists"},{"key": "C","text": "Only cytotoxic edema exists"},{"key": "D","text": "Cytotoxic and vasogenic edema"}],"correct": "D","explanation": "Cerebral edema is broadly classified as cytotoxic (cellular swelling from ischemia) and vasogenic (from blood-brain barrier disruption)."},{"id": 3939,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hydrocephalus refers to:","options": [{"key": "A","text": "Excess blood within the brain"},{"key": "B","text": "Brain tissue atrophy only"},{"key": "C","text": "Abnormal accumulation of CSF within the ventricular system"},{"key": "D","text": "Infection of brain parenchyma"}],"correct": "C","explanation": "Hydrocephalus results from CSF overproduction, obstruction, or impaired absorption, causing ventricular dilation and raised ICP."},{"id": 3940,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Normal pressure hydrocephalus classically presents with the triad of:","options": [{"key": "A","text": "Ataxia, nystagmus, and dysarthria"},{"key": "B","text": "Tremor, rigidity, and bradykinesia"},{"key": "C","text": "Fever, headache, and neck stiffness"},{"key": "D","text": "Gait disturbance, urinary incontinence, and dementia"}],"correct": "D","explanation": "NPH's classic triad ('wet, wobbly, and wacky') includes gait apraxia, incontinence, and cognitive decline, often reversible with shunting."},{"id": 3941,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Atherosclerosis primarily affects which layer of the arterial wall?","options": [{"key": "A","text": "Adventitia only"},{"key": "B","text": "Intima"},{"key": "C","text": "Media only"},{"key": "D","text": "All layers equally from onset"}],"correct": "B","explanation": "Atherosclerosis begins as lipid accumulation and plaque formation within the intimal layer of arteries."},{"id": 3942,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The earliest visible lesion in atherosclerosis is called:","options": [{"key": "A","text": "Fibrous plaque"},{"key": "B","text": "Calcified plaque"},{"key": "C","text": "Complicated plaque"},{"key": "D","text": "Fatty streak"}],"correct": "D","explanation": "Fatty streaks, composed of lipid-laden macrophages (foam cells), are the earliest atherosclerotic lesions, seen even in children."},{"id": 3943,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Foam cells in atherosclerotic plaques are derived from:","options": [{"key": "A","text": "Neutrophils"},{"key": "B","text": "Lymphocytes"},{"key": "C","text": "Fibroblasts"},{"key": "D","text": "Macrophages that have ingested oxidized LDL"}],"correct": "D","explanation": "Macrophages engulf oxidized LDL cholesterol, becoming lipid-laden foam cells characteristic of atherosclerotic lesions."},{"id": 3944,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The most significant modifiable risk factor for atherosclerosis is:","options": [{"key": "A","text": "Age"},{"key": "B","text": "Family history"},{"key": "C","text": "Male gender"},{"key": "D","text": "Hyperlipidemia (elevated LDL cholesterol)"}],"correct": "D","explanation": "Elevated LDL cholesterol is the most important modifiable risk factor driving atherosclerotic plaque development."},{"id": 3945,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Myocardial infarction most commonly results from:","options": [{"key": "A","text": "Congenital heart defect"},{"key": "B","text": "Viral myocarditis only"},{"key": "C","text": "Cardiac valve disease"},{"key": "D","text": "Thrombosis over a ruptured atherosclerotic plaque"}],"correct": "D","explanation": "Acute plaque rupture with superimposed thrombus formation is the most common cause of MI."},{"id": 3946,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The earliest cardiac biomarker to rise after myocardial infarction is:","options": [{"key": "A","text": "Troponin I"},{"key": "B","text": "Myoglobin"},{"key": "C","text": "CK-MB"},{"key": "D","text": "LDH"}],"correct": "B","explanation": "Myoglobin rises earliest (within 1-2 hours) but lacks cardiac specificity; troponin remains the gold standard for diagnosis."},{"id": 3947,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Troponin I/T levels remain elevated for how long after acute MI, making them useful for late diagnosis?","options": [{"key": "A","text": "2-4 hours only"},{"key": "B","text": "30 minutes"},{"key": "C","text": "Never elevated beyond a day"},{"key": "D","text": "7-10 days"}],"correct": "D","explanation": "Troponins remain elevated for 7-10 days post-MI, useful for both early and late diagnosis of myocardial injury."},{"id": 3948,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Hard","question": "Coagulative necrosis of myocardium following MI is typically visible microscopically after:","options": [{"key": "A","text": "Immediately (within minutes)"},{"key": "B","text": "1 week"},{"key": "C","text": "72 hours only"},{"key": "D","text": "4-12 hours"}],"correct": "D","explanation": "Microscopic evidence of coagulative necrosis in MI typically becomes apparent after 4-12 hours of ischemia."},{"id": 3949,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The most common complication causing death within the first hour of acute MI is:","options": [{"key": "A","text": "Papillary muscle rupture"},{"key": "B","text": "Fatal arrhythmia (ventricular fibrillation)"},{"key": "C","text": "Cardiac rupture"},{"key": "D","text": "Pericarditis"}],"correct": "B","explanation": "Ventricular fibrillation is the leading cause of sudden cardiac death in the earliest phase of acute MI."},{"id": 3950,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Cardiac rupture as a complication of MI typically occurs during which time period post-infarct?","options": [{"key": "A","text": "Immediately at onset"},{"key": "B","text": "After 6 months"},{"key": "C","text": "Within the first hour"},{"key": "D","text": "3-7 days (when necrotic tissue is weakest)"}],"correct": "D","explanation": "Cardiac rupture risk peaks 3-7 days post-MI when the infarcted myocardium is maximally weakened before scar formation."},{"id": 3951,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Cardiac rehabilitation (physiotherapy) after MI is important primarily to:","options": [{"key": "A","text": "Improve functional capacity and reduce future cardiovascular risk"},{"key": "B","text": "Increase risk of arrhythmia"},{"key": "C","text": "Delay scar formation"},{"key": "D","text": "Increase infarct size"}],"correct": "A","explanation": "Structured cardiac rehab improves exercise tolerance, reduces risk factors, and improves quality of life after MI."},{"id": 3952,"subject": "Pathology","topic": "Immunology","difficulty": "Easy","question": "Rheumatic heart disease results from an immune reaction following infection with:","options": [{"key": "A","text": "Group A Streptococcus (pharyngitis)"},{"key": "B","text": "E. coli"},{"key": "C","text": "Streptococcus viridans (directly)"},{"key": "D","text": "Staphylococcus aureus"}],"correct": "A","explanation": "Rheumatic fever/heart disease follows an autoimmune cross-reaction (molecular mimicry) after group A strep pharyngitis."},{"id": 3953,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which cardiac valve is most commonly affected in rheumatic heart disease?","options": [{"key": "A","text": "Tricuspid valve"},{"key": "B","text": "Aortic valve alone"},{"key": "C","text": "Pulmonary valve"},{"key": "D","text": "Mitral valve"}],"correct": "D","explanation": "The mitral valve is most frequently and severely affected in chronic rheumatic heart disease, often causing mitral stenosis."},{"id": 3954,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Aschoff bodies, the pathognomonic lesion of rheumatic fever, are found in:","options": [{"key": "A","text": "Liver"},{"key": "B","text": "Lungs"},{"key": "C","text": "Kidney"},{"key": "D","text": "Myocardium"}],"correct": "D","explanation": "Aschoff bodies are granulomatous lesions with characteristic Anitschkow cells found in the myocardium during acute rheumatic fever."},{"id": 3955,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Infective endocarditis most commonly affects which valve in intravenous drug users?","options": [{"key": "A","text": "Mitral valve"},{"key": "B","text": "Aortic valve"},{"key": "C","text": "Tricuspid valve"},{"key": "D","text": "Pulmonary valve only"}],"correct": "C","explanation": "IV drug use introduces bacteria directly into venous circulation, predisposing to right-sided (tricuspid) endocarditis."},{"id": 3956,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hypertension is classified as primary (essential) in what percentage of cases?","options": [{"key": "A","text": "About 50%"},{"key": "B","text": "About 90-95%"},{"key": "C","text": "About 10%"},{"key": "D","text": "Less than 5%"}],"correct": "B","explanation": "The vast majority (90-95%) of hypertension cases are primary/essential with no identifiable single cause."},{"id": 3957,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Secondary hypertension is most commonly caused by which condition?","options": [{"key": "A","text": "Genetic predisposition alone"},{"key": "B","text": "Aging alone"},{"key": "C","text": "Renal artery stenosis/renal disease"},{"key": "D","text": "Idiopathic causes"}],"correct": "C","explanation": "Renal disease, particularly renal artery stenosis, is the most common identifiable cause of secondary hypertension."},{"id": 3958,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Malignant hypertension is characterized by markedly elevated blood pressure with:","options": [{"key": "A","text": "Papilledema and acute end-organ damage"},{"key": "B","text": "Slowly progressive organ damage over years"},{"key": "C","text": "Normal fundoscopic findings"},{"key": "D","text": "No symptoms at all"}],"correct": "A","explanation": "Malignant hypertension causes rapid, severe end-organ damage including papilledema, requiring emergency management."},{"id": 3959,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Left ventricular hypertrophy is a common compensatory response to chronic:","options": [{"key": "A","text": "Anemia only"},{"key": "B","text": "Hypertension (increased afterload)"},{"key": "C","text": "Hyperthyroidism only"},{"key": "D","text": "Hypotension"}],"correct": "B","explanation": "Sustained hypertension increases cardiac afterload, causing compensatory concentric LV hypertrophy."},{"id": 3960,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Congestive heart failure with reduced ejection fraction primarily results from:","options": [{"key": "A","text": "Excess ejection fraction"},{"key": "B","text": "Normal cardiac output with high demand"},{"key": "C","text": "Bradycardia alone"},{"key": "D","text": "Impaired systolic contractile function of the heart"}],"correct": "D","explanation": "HFrEF results from impaired myocardial contractility, reducing the heart's ability to eject blood effectively."},{"id": 3961,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Right-sided heart failure classically causes which peripheral finding?","options": [{"key": "A","text": "Pulmonary edema primarily"},{"key": "B","text": "Hemoptysis primarily"},{"key": "C","text": "Orthopnea as the main symptom"},{"key": "D","text": "Peripheral (dependent) edema and jugular venous distension"}],"correct": "D","explanation": "Right heart failure causes systemic venous congestion, manifesting as peripheral edema and elevated JVP."},{"id": 3962,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Left-sided heart failure classically causes which pulmonary finding?","options": [{"key": "A","text": "Pulmonary edema and orthopnea"},{"key": "B","text": "Hepatomegaly primarily"},{"key": "C","text": "Ascites primarily"},{"key": "D","text": "Peripheral edema primarily"}],"correct": "A","explanation": "Left heart failure causes blood backup into pulmonary circulation, resulting in pulmonary congestion/edema and orthopnea."},{"id": 3963,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "BNP (B-type natriuretic peptide) is a useful biomarker for diagnosing:","options": [{"key": "A","text": "Congestive heart failure"},{"key": "B","text": "Myocardial infarction specifically"},{"key": "C","text": "Rheumatic fever"},{"key": "D","text": "Pericarditis"}],"correct": "A","explanation": "BNP is released from stretched ventricular myocardium in heart failure and is used to support its diagnosis."},{"id": 3964,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cardiac tamponade results from:","options": [{"key": "A","text": "Valve stenosis"},{"key": "B","text": "Coronary artery occlusion"},{"key": "C","text": "Accumulation of fluid in the pericardial sac compressing the heart"},{"key": "D","text": "Myocardial hypertrophy"}],"correct": "C","explanation": "Rapid fluid accumulation in the pericardial space impairs ventricular filling, causing life-threatening tamponade."},{"id": 3965,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Pulsus paradoxus, a sign of cardiac tamponade, refers to:","options": [{"key": "A","text": "Irregular heart rhythm"},{"key": "B","text": "Exaggerated fall in systolic BP (>10mmHg) during inspiration"},{"key": "C","text": "Increased BP during inspiration"},{"key": "D","text": "No change in BP with respiration"}],"correct": "B","explanation": "Pulsus paradoxus reflects exaggerated ventricular interdependence during tamponade, causing an abnormal inspiratory BP drop."},{"id": 3966,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Angina pectoris is best defined as:","options": [{"key": "A","text": "Chest pain due to reversible myocardial ischemia without infarction"},{"key": "B","text": "Permanent myocardial cell death"},{"key": "C","text": "Pericardial inflammation"},{"key": "D","text": "Valve dysfunction"}],"correct": "A","explanation": "Angina represents transient, reversible myocardial ischemia typically relieved by rest/nitrates, unlike infarction."},{"id": 3967,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Peripheral arterial disease (PAD) most commonly presents with which symptom relevant to physiotherapy assessment?","options": [{"key": "A","text": "Constant burning pain unrelated to activity"},{"key": "B","text": "Resting chest pain"},{"key": "C","text": "Intermittent claudication (exertional leg pain relieved by rest)"},{"key": "D","text": "Sudden loss of consciousness"}],"correct": "C","explanation": "PAD causes exertional muscle ischemia manifesting as intermittent claudication, a key symptom guiding exercise-based physiotherapy programs."},{"id": 3968,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pericarditis pain classically worsens with which position and improves with which?","options": [{"key": "A","text": "No positional variation"},{"key": "B","text": "Worsens lying supine, improves leaning forward"},{"key": "C","text": "Worsens standing, improves lying flat"},{"key": "D","text": "Worsens leaning forward, improves lying supine"}],"correct": "B","explanation": "Pericarditis pain classically worsens with lying flat/supine and is relieved by sitting up and leaning forward."},{"id": 3969,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "A pericardial friction rub is a classic auscultatory finding in:","options": [{"key": "A","text": "Mitral stenosis"},{"key": "B","text": "Aortic regurgitation only"},{"key": "C","text": "Acute pericarditis"},{"key": "D","text": "Ventricular septal defect"}],"correct": "C","explanation": "A scratchy, triphasic friction rub is heard in pericarditis due to inflamed pericardial layers rubbing together."},{"id": 3970,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Dilated cardiomyopathy is characterized by:","options": [{"key": "A","text": "Valve stenosis only"},{"key": "B","text": "Ventricular wall thickening with preserved function"},{"key": "C","text": "Restrictive filling with normal wall thickness"},{"key": "D","text": "Ventricular dilation with impaired systolic (contractile) function"}],"correct": "D","explanation": "Dilated cardiomyopathy shows a large, weakly contracting ventricle, the most common cause of systolic heart failure."},{"id": 3971,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hypertrophic cardiomyopathy is characterized by:","options": [{"key": "A","text": "Fibrous restriction of ventricular filling"},{"key": "B","text": "Asymmetric septal hypertrophy causing outflow obstruction"},{"key": "C","text": "Ventricular dilation with thin walls"},{"key": "D","text": "Valve regurgitation as primary defect"}],"correct": "B","explanation": "HCM involves disorganized myocyte hypertrophy, often asymmetric septal thickening, which can cause outflow tract obstruction and sudden cardiac death in athletes."},{"id": 3972,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Restrictive cardiomyopathy is characterized by:","options": [{"key": "A","text": "Valve stenosis as primary defect"},{"key": "B","text": "Impaired ventricular filling (diastolic dysfunction) with normal/near-normal systolic function"},{"key": "C","text": "Ventricular dilation as primary feature"},{"key": "D","text": "Impaired systolic function primarily"}],"correct": "B","explanation": "Restrictive cardiomyopathy causes stiff ventricles that resist filling, often due to infiltrative diseases like amyloidosis."},{"id": 3973,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Mitral stenosis classically causes which murmur?","options": [{"key": "A","text": "Early diastolic decrescendo murmur"},{"key": "B","text": "Continuous machinery murmur"},{"key": "C","text": "Pansystolic murmur"},{"key": "D","text": "Mid-diastolic rumbling murmur"}],"correct": "D","explanation": "Mitral stenosis, most commonly from rheumatic heart disease, produces a characteristic low-pitched mid-diastolic murmur."},{"id": 3974,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Mitral regurgitation classically causes which murmur?","options": [{"key": "A","text": "Holosystolic (pansystolic) murmur radiating to axilla"},{"key": "B","text": "Mid-diastolic murmur"},{"key": "C","text": "Early diastolic murmur"},{"key": "D","text": "Continuous murmur"}],"correct": "A","explanation": "Mitral regurgitation produces a blowing holosystolic murmur best heard at the apex, radiating to the axilla."},{"id": 3975,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Aortic stenosis classically causes which murmur?","options": [{"key": "A","text": "Diastolic rumbling murmur"},{"key": "B","text": "Pansystolic murmur at apex"},{"key": "C","text": "Crescendo-decrescendo systolic ejection murmur radiating to carotids"},{"key": "D","text": "Continuous machinery murmur"}],"correct": "C","explanation": "AS produces a harsh systolic ejection murmur best heard at the right upper sternal border, radiating to the carotids."},{"id": 3976,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Aortic regurgitation classically causes which murmur?","options": [{"key": "A","text": "Early diastolic decrescendo murmur"},{"key": "B","text": "Continuous murmur"},{"key": "C","text": "Systolic ejection murmur"},{"key": "D","text": "Mid-diastolic rumbling murmur"}],"correct": "A","explanation": "Aortic regurgitation produces a high-pitched, blowing early diastolic murmur best heard at the left sternal border."},{"id": 3977,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Patent ductus arteriosus classically produces which murmur?","options": [{"key": "A","text": "Early systolic click only"},{"key": "B","text": "Continuous 'machinery' murmur"},{"key": "C","text": "Pansystolic murmur only"},{"key": "D","text": "Mid-diastolic murmur"}],"correct": "B","explanation": "PDA causes a continuous machinery-like murmur due to persistent flow between the aorta and pulmonary artery throughout the cardiac cycle."},{"id": 3978,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Tetralogy of Fallot includes which four features?","options": [{"key": "A","text": "PDA, aortic stenosis, RV hypertrophy, ASD"},{"key": "B","text": "ASD, mitral stenosis, LV hypertrophy, aortic coarctation"},{"key": "C","text": "VSD, pulmonary stenosis, overriding aorta, right ventricular hypertrophy"},{"key": "D","text": "VSD only with normal pulmonary vasculature"}],"correct": "C","explanation": "TOF is the classic cyanotic congenital heart defect comprising these four anatomical abnormalities."},{"id": 3979,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Coarctation of the aorta classically causes:","options": [{"key": "A","text": "Equal blood pressure in all limbs"},{"key": "B","text": "Hypotension throughout the body"},{"key": "C","text": "Hypertension in lower limbs only"},{"key": "D","text": "Hypertension in upper limbs with weak/delayed femoral pulses"}],"correct": "D","explanation": "Aortic coarctation, a narrowing typically distal to the left subclavian artery, causes differential BP and pulse findings between upper and lower limbs."},{"id": 3980,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ventricular septal defect (VSD), the most common congenital heart defect, causes shunting of blood:","options": [{"key": "A","text": "Left to right (acyanotic initially)"},{"key": "B","text": "No shunting occurs"},{"key": "C","text": "Right to left (cyanotic initially)"},{"key": "D","text": "Bidirectional only from birth"}],"correct": "A","explanation": "VSD initially causes left-to-right shunting due to higher LV pressure, which can reverse (Eisenmenger syndrome) if left uncorrected."},{"id": 3981,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Eisenmenger syndrome refers to:","options": [{"key": "A","text": "Congenital absence of a cardiac chamber"},{"key": "B","text": "Reversal of a left-to-right shunt to right-to-left due to pulmonary hypertension"},{"key": "C","text": "Rheumatic valve disease"},{"key": "D","text": "A type of valve stenosis"}],"correct": "B","explanation": "Chronic left-to-right shunting causes pulmonary vascular resistance to rise, eventually reversing the shunt direction and causing cyanosis."},{"id": 3982,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Deep vein thrombosis prophylaxis in immobilized/post-surgical patients commonly includes:","options": [{"key": "A","text": "High-dose steroids"},{"key": "B","text": "Prolonged strict bed rest only"},{"key": "C","text": "Early mobilization, compression stockings, and anticoagulation"},{"key": "D","text": "Avoiding all limb movement"}],"correct": "C","explanation": "A combination of physiotherapy-driven early mobilization, mechanical compression, and pharmacologic prophylaxis reduces DVT risk."},{"id": 3983,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which cardiovascular parameter is most important to monitor during exercise-based cardiac rehabilitation?","options": [{"key": "A","text": "Only resting heart rate"},{"key": "B","text": "Heart rate, blood pressure, and symptoms of exertional intolerance"},{"key": "C","text": "Only body temperature"},{"key": "D","text": "Only respiratory rate"}],"correct": "B","explanation": "Monitoring heart rate/BP response and symptoms ensures safe progression of exercise intensity in cardiac rehab patients."},{"id": 3984,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Orthostatic (postural) hypotension is defined as a drop in systolic BP of at least how much upon standing?","options": [{"key": "A","text": "5 mmHg"},{"key": "B","text": "50 mmHg"},{"key": "C","text": "20 mmHg (or diastolic drop of 10 mmHg)"},{"key": "D","text": "No defined threshold exists"}],"correct": "C","explanation": "Orthostatic hypotension is diagnosed with a systolic BP drop ≥20 mmHg or diastolic drop ≥10 mmHg within 3 minutes of standing, important in physiotherapy fall-risk assessment."},{"id": 3985,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Raynaud's phenomenon involves episodic vasospasm most commonly affecting:","options": [{"key": "A","text": "Renal arteries"},{"key": "B","text": "Cerebral arteries"},{"key": "C","text": "Coronary arteries"},{"key": "D","text": "Digital arteries of fingers/toes"}],"correct": "D","explanation": "Raynaud's phenomenon causes reversible digital vasospasm triggered by cold/stress, producing color changes in fingers/toes."},{"id": 3986,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Buerger's disease (thromboangiitis obliterans) is strongly associated with:","options": [{"key": "A","text": "Hyperlipidemia primarily"},{"key": "B","text": "Tobacco/cigarette smoking"},{"key": "C","text": "Hypertension"},{"key": "D","text": "Diabetes primarily"}],"correct": "B","explanation": "Buerger's disease, causing small/medium vessel inflammation and thrombosis in the limbs, is very strongly linked to smoking."},{"id": 3987,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Varicose veins result from:","options": [{"key": "A","text": "Lymphatic obstruction primarily"},{"key": "B","text": "Increased arterial pressure"},{"key": "C","text": "Incompetent venous valves causing blood pooling and vein dilation"},{"key": "D","text": "Arterial occlusion"}],"correct": "C","explanation": "Valve incompetence in superficial veins leads to venous reflux, pooling, and progressive vein dilation."},{"id": 3988,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Chronic venous insufficiency can lead to which skin complication relevant to wound care in physiotherapy?","options": [{"key": "A","text": "No skin complications occur"},{"key": "B","text": "Neuropathic ulcers on the heel"},{"key": "C","text": "Arterial ulcers on the toes"},{"key": "D","text": "Venous stasis ulcers, typically near the medial malleolus"}],"correct": "D","explanation": "Chronic venous hypertension causes skin changes and stasis ulcers, classically located near the medial malleolus."},{"id": 3989,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Arterial (ischemic) ulcers differ from venous ulcers in that they are typically:","options": [{"key": "A","text": "Painless with irregular borders near the ankle"},{"key": "B","text": "Painful, well-demarcated, located distally (toes) with poor pulses"},{"key": "C","text": "Always associated with edema"},{"key": "D","text": "Located at the knee only"}],"correct": "B","explanation": "Arterial ulcers are painful, punched-out lesions at distal sites with diminished pulses, reflecting poor arterial perfusion."},{"id": 3990,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The Ankle-Brachial Index (ABI) is used clinically to assess:","options": [{"key": "A","text": "Lymphatic function"},{"key": "B","text": "Cardiac ejection fraction"},{"key": "C","text": "Peripheral arterial disease severity"},{"key": "D","text": "Venous insufficiency only"}],"correct": "C","explanation": "ABI, comparing ankle to brachial systolic pressures, helps diagnose and grade the severity of peripheral arterial disease."},{"id": 3991,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "An ABI value below 0.9 is generally indicative of:","options": [{"key": "A","text": "Venous insufficiency"},{"key": "B","text": "Normal arterial function"},{"key": "C","text": "Peripheral arterial disease"},{"key": "D","text": "Lymphedema"}],"correct": "C","explanation": "An ABI <0.9 suggests significant arterial insufficiency, important before initiating aggressive exercise therapy in PAD patients."},{"id": 3992,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic exposure to cold and vibration (e.g., in certain occupations) can predispose to:","options": [{"key": "A","text": "Raynaud's phenomenon (secondary)"},{"key": "B","text": "Rheumatic fever"},{"key": "C","text": "Cardiomyopathy"},{"key": "D","text": "Varicose veins only"}],"correct": "A","explanation": "Occupational vibration exposure is a recognized cause of secondary Raynaud's phenomenon (vibration white finger)."},{"id": 3993,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Postural orthostatic tachycardia syndrome (POTS) is characterized by:","options": [{"key": "A","text": "Bradycardia upon standing"},{"key": "B","text": "No autonomic involvement"},{"key": "C","text": "Excessive heart rate increase upon standing without significant BP drop"},{"key": "D","text": "Significant hypotension with normal heart rate"}],"correct": "C","explanation": "POTS involves an abnormal, excessive heart rate rise (usually >30 bpm) on standing due to autonomic dysregulation."},{"id": 3994,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Exercise-induced cardiac arrhythmia risk is particularly important to screen for in patients with a history of:","options": [{"key": "A","text": "Hypertrophic cardiomyopathy"},{"key": "B","text": "Mild anemia only"},{"key": "C","text": "Osteoarthritis only"},{"key": "D","text": "Simple tension headache"}],"correct": "A","explanation": "HCM carries risk of exercise-induced sudden cardiac death, requiring careful screening before exercise prescription in physiotherapy."},{"id": 3995,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Chronic obstructive pulmonary disease (COPD) primarily includes which two conditions?","options": [{"key": "A","text": "Tuberculosis and pneumothorax"},{"key": "B","text": "Pulmonary embolism and edema"},{"key": "C","text": "Asthma and pneumonia"},{"key": "D","text": "Chronic bronchitis and emphysema"}],"correct": "D","explanation": "COPD is an umbrella term encompassing chronic bronchitis and emphysema, both causing airflow obstruction."},{"id": 3996,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic bronchitis is clinically defined as productive cough for at least:","options": [{"key": "A","text": "1 week"},{"key": "B","text": "3 months in 2 consecutive years"},{"key": "C","text": "1 month total"},{"key": "D","text": "6 months in a single year"}],"correct": "B","explanation": "Chronic bronchitis is a clinical diagnosis based on chronic productive cough for 3 months in 2 successive years."},{"id": 3997,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Emphysema is pathologically characterized by:","options": [{"key": "A","text": "Excess mucus gland hypertrophy only"},{"key": "B","text": "Permanent enlargement of airspaces distal to terminal bronchioles with wall destruction"},{"key": "C","text": "Bronchial wall fibrosis without airspace change"},{"key": "D","text": "Increased alveolar surface area with intact walls"}],"correct": "B","explanation": "Emphysema involves destruction of alveolar walls, permanently enlarging airspaces and reducing gas exchange surface area."},{"id": 3998,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Centriacinar (centrilobular) emphysema is most strongly associated with:","options": [{"key": "A","text": "Pulmonary fibrosis"},{"key": "B","text": "Asthma"},{"key": "C","text": "Alpha-1 antitrypsin deficiency"},{"key": "D","text": "Cigarette smoking"}],"correct": "D","explanation": "Centriacinar emphysema predominantly affects upper lung zones and is classically linked to smoking."},{"id": 3999,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Panacinar emphysema is classically associated with:","options": [{"key": "A","text": "Cigarette smoking primarily"},{"key": "B","text": "Alpha-1 antitrypsin deficiency"},{"key": "C","text": "Asbestos exposure"},{"key": "D","text": "Tuberculosis"}],"correct": "B","explanation": "Panacinar emphysema, affecting the entire acinus uniformly (often lower lobes), is the classic pattern in alpha-1 antitrypsin deficiency."},{"id": 4000,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "'Pink puffer' clinical phenotype classically describes patients with predominant:","options": [{"key": "A","text": "Emphysema"},{"key": "B","text": "Chronic bronchitis"},{"key": "C","text": "Asthma"},{"key": "D","text": "Pulmonary fibrosis"}],"correct": "A","explanation": "Emphysema patients ('pink puffers') tend to be thin with pursed-lip breathing and relatively preserved oxygenation despite dyspnea."},{"id": 4001,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "'Blue bloater' clinical phenotype classically describes patients with predominant:","options": [{"key": "A","text": "Pulmonary embolism"},{"key": "B","text": "Emphysema"},{"key": "C","text": "Chronic bronchitis"},{"key": "D","text": "Simple asthma"}],"correct": "C","explanation": "Chronic bronchitis patients ('blue bloaters') often show cyanosis and edema due to hypoxemia and cor pulmonale."},{"id": 4002,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Asthma is characterized by:","options": [{"key": "A","text": "Pure restrictive lung disease"},{"key": "B","text": "Irreversible airway destruction"},{"key": "C","text": "Fixed airflow limitation only"},{"key": "D","text": "Reversible airway obstruction due to bronchial hyperresponsiveness and inflammation"}],"correct": "D","explanation": "Asthma involves reversible bronchoconstriction, airway inflammation, and hyperresponsiveness to triggers."},{"id": 4003,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Curschmann spirals and Charcot-Leyden crystals in sputum are characteristic findings in:","options": [{"key": "A","text": "COPD only"},{"key": "B","text": "Bronchial asthma"},{"key": "C","text": "Tuberculosis"},{"key": "D","text": "Pneumonia"}],"correct": "B","explanation": "These findings reflect mucus plugs (Curschmann spirals) and eosinophil breakdown products (Charcot-Leyden crystals) seen in asthma."},{"id": 4004,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pulmonary tuberculosis is caused by which organism?","options": [{"key": "A","text": "Haemophilus influenzae"},{"key": "B","text": "Streptococcus pneumoniae"},{"key": "C","text": "Klebsiella pneumoniae"},{"key": "D","text": "Mycobacterium tuberculosis"}],"correct": "D","explanation": "TB is caused by the acid-fast bacillus Mycobacterium tuberculosis, spread via airborne droplets."},{"id": 4005,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The primary (Ghon) complex in TB consists of a peripheral lung lesion combined with:","options": [{"key": "A","text": "Miliary spread"},{"key": "B","text": "Pleural effusion only"},{"key": "C","text": "Hilar lymph node involvement"},{"key": "D","text": "Cavitary lesion only"}],"correct": "C","explanation": "The Ghon complex comprises the primary parenchymal lesion (Ghon focus) plus involved draining hilar lymph nodes."},{"id": 4006,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Miliary tuberculosis refers to:","options": [{"key": "A","text": "TB confined to lymph nodes only"},{"key": "B","text": "Widespread hematogenous dissemination of TB producing small nodules throughout organs"},{"key": "C","text": "Localized cavitary lung disease only"},{"key": "D","text": "TB of bone only"}],"correct": "B","explanation": "Miliary TB results from blood-borne spread, producing numerous millet-seed-sized granulomas across multiple organs."},{"id": 4007,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pott's disease refers to tuberculosis affecting:","options": [{"key": "A","text": "The brain only"},{"key": "B","text": "The lungs only"},{"key": "C","text": "The kidneys only"},{"key": "D","text": "The spine (vertebral bodies)"}],"correct": "D","explanation": "Pott's disease is skeletal TB of the spine, causing vertebral destruction, kyphotic deformity, and potential cord compression — highly relevant to physiotherapy."},{"id": 4008,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pneumonia is best defined as:","options": [{"key": "A","text": "Acute infection/inflammation of the lung parenchyma"},{"key": "B","text": "Chronic airway obstruction"},{"key": "C","text": "Pleural fluid collection only"},{"key": "D","text": "Vascular occlusion of pulmonary artery"}],"correct": "A","explanation": "Pneumonia is an acute infectious inflammation of lung tissue, commonly bacterial, viral, or fungal in origin."},{"id": 4009,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Lobar pneumonia classically shows which pattern of consolidation?","options": [{"key": "A","text": "Diffuse bilateral ground-glass only"},{"key": "B","text": "No radiological consolidation"},{"key": "C","text": "Consolidation of an entire lobe"},{"key": "D","text": "Patchy bronchial distribution"}],"correct": "C","explanation": "Lobar pneumonia, classically caused by S. pneumoniae, involves consolidation of a complete lung lobe."},{"id": 4010,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Bronchopneumonia is characterized by:","options": [{"key": "A","text": "Cavitation as the primary feature"},{"key": "B","text": "Patchy consolidation centered around bronchi/bronchioles"},{"key": "C","text": "Consolidation of an entire lobe"},{"key": "D","text": "Isolated pleural effusion"}],"correct": "B","explanation": "Bronchopneumonia shows a patchy, multifocal distribution of consolidation around airways, often in elderly/debilitated patients."},{"id": 4011,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The most common causative organism of community-acquired pneumonia is:","options": [{"key": "A","text": "Streptococcus pneumoniae"},{"key": "B","text": "Pseudomonas aeruginosa"},{"key": "C","text": "Klebsiella pneumoniae"},{"key": "D","text": "Mycobacterium tuberculosis"}],"correct": "A","explanation": "S. pneumoniae remains the most common bacterial cause of community-acquired pneumonia."},{"id": 4012,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Aspiration pneumonia commonly occurs in patients with:","options": [{"key": "A","text": "Impaired swallowing/consciousness (e.g., stroke patients)"},{"key": "B","text": "Chronic hypertension only"},{"key": "C","text": "Well-controlled diabetes only"},{"key": "D","text": "Normal swallowing function"}],"correct": "A","explanation": "Impaired airway protective reflexes, common after stroke, predispose to aspiration of oropharyngeal contents causing pneumonia — important for physiotherapy dysphagia screening."},{"id": 4013,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Atelectasis refers to:","options": [{"key": "A","text": "Pleural fluid accumulation"},{"key": "B","text": "Excess air trapping in alveoli"},{"key": "C","text": "Consolidation of lung parenchyma"},{"key": "D","text": "Collapse of previously expanded lung tissue"}],"correct": "D","explanation": "Atelectasis is incomplete lung expansion or collapse of previously aerated lung, common post-surgery and addressed with breathing exercises."},{"id": 4014,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Postoperative atelectasis is commonly prevented/treated with which physiotherapy intervention?","options": [{"key": "A","text": "Prolonged bed rest"},{"key": "B","text": "Avoiding all respiratory exercises"},{"key": "C","text": "Chest strapping"},{"key": "D","text": "Incentive spirometry and deep breathing exercises"}],"correct": "D","explanation": "Incentive spirometry and deep breathing/coughing exercises help re-expand collapsed alveoli and prevent postoperative atelectasis."},{"id": 4015,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pleural effusion refers to:","options": [{"key": "A","text": "Consolidation of lung tissue"},{"key": "B","text": "Collapse of lung parenchyma"},{"key": "C","text": "Air in the pleural space"},{"key": "D","text": "Abnormal accumulation of fluid in the pleural space"}],"correct": "D","explanation": "Pleural effusion is excess fluid accumulation between the visceral and parietal pleura, from various causes including CHF and infection."},{"id": 4016,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pneumothorax refers to:","options": [{"key": "A","text": "Presence of air in the pleural space causing lung collapse"},{"key": "B","text": "Pulmonary embolism"},{"key": "C","text": "Consolidation of the lung"},{"key": "D","text": "Fluid accumulation in pleural space"}],"correct": "A","explanation": "Pneumothorax occurs when air enters the pleural space, disrupting the negative pressure and causing partial/complete lung collapse."},{"id": 4017,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Tension pneumothorax is a medical emergency characterized by:","options": [{"key": "A","text": "Small stable air pocket without symptoms"},{"key": "B","text": "Fluid accumulation only"},{"key": "C","text": "Chronic slow-developing air leak"},{"key": "D","text": "Progressive air accumulation causing mediastinal shift and cardiovascular compromise"}],"correct": "D","explanation": "In tension pneumothorax, a one-way valve mechanism causes progressive air trapping, shifting the mediastinum and compromising venous return."},{"id": 4018,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Bronchiectasis is characterized by:","options": [{"key": "A","text": "Pleural fibrosis"},{"key": "B","text": "Reversible bronchoconstriction"},{"key": "C","text": "Alveolar wall destruction only"},{"key": "D","text": "Permanent, abnormal dilation of bronchi due to chronic infection/inflammation"}],"correct": "D","explanation": "Bronchiectasis results from recurrent infection/inflammation causing irreversible bronchial dilation and impaired mucus clearance."},{"id": 4019,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Cystic fibrosis leads to bronchiectasis primarily due to:","options": [{"key": "A","text": "Direct bacterial destruction of cartilage"},{"key": "B","text": "Excess surfactant production"},{"key": "C","text": "Autoimmune bronchial destruction"},{"key": "D","text": "Thick, viscous mucus impairing mucociliary clearance and promoting chronic infection"}],"correct": "D","explanation": "CFTR dysfunction causes thick mucus secretions that obstruct airways and predispose to recurrent infections, leading to bronchiectasis."},{"id": 4020,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Hard","question": "Idiopathic pulmonary fibrosis pathologically shows which characteristic pattern?","options": [{"key": "A","text": "Pure emphysematous change"},{"key": "B","text": "Granuloma formation as the primary feature"},{"key": "C","text": "Uniform, diffuse acute inflammation only"},{"key": "D","text": "Usual interstitial pneumonia pattern with patchy fibrosis and honeycombing"}],"correct": "D","explanation": "IPF classically demonstrates a usual interstitial pneumonia (UIP) pattern with patchy fibrosis, fibroblastic foci, and honeycomb changes."},{"id": 4021,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Restrictive lung diseases like pulmonary fibrosis are characterized on pulmonary function testing by:","options": [{"key": "A","text": "Reduced FEV1/FVC ratio primarily"},{"key": "B","text": "Reduced lung volumes with normal or increased FEV1/FVC ratio"},{"key": "C","text": "Increased total lung capacity"},{"key": "D","text": "Normal lung volumes with reduced ratio"}],"correct": "B","explanation": "Restrictive diseases reduce overall lung volumes (FVC, TLC) while the FEV1/FVC ratio remains normal or is even increased, unlike obstructive disease."},{"id": 4022,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Obstructive lung diseases like COPD/asthma are characterized on pulmonary function testing by:","options": [{"key": "A","text": "Reduced FEV1/FVC ratio with air trapping"},{"key": "B","text": "Normal residual volume always"},{"key": "C","text": "Increased FEV1/FVC ratio"},{"key": "D","text": "Reduced total lung capacity"}],"correct": "A","explanation": "Obstructive diseases cause disproportionately reduced FEV1 relative to FVC, lowering the FEV1/FVC ratio, with air trapping increasing residual volume."},{"id": 4023,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Acute Respiratory Distress Syndrome (ARDS) is characterized by:","options": [{"key": "A","text": "Diffuse alveolar damage causing bilateral pulmonary edema and severe hypoxemia"},{"key": "B","text": "Localized lobar consolidation"},{"key": "C","text": "Chronic airway obstruction only"},{"key": "D","text": "Pleural effusion as the primary feature"}],"correct": "A","explanation": "ARDS results from diffuse alveolar-capillary damage causing non-cardiogenic pulmonary edema and refractory hypoxemia."},{"id": 4024,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hyaline membrane disease (neonatal respiratory distress syndrome) results from deficiency of:","options": [{"key": "A","text": "Collagen"},{"key": "B","text": "Surfactant"},{"key": "C","text": "Elastin"},{"key": "D","text": "Mucus"}],"correct": "B","explanation": "Insufficient surfactant in premature infants causes alveolar collapse and hyaline membrane formation, impairing gas exchange."},{"id": 4025,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pneumoconiosis refers to lung disease caused by:","options": [{"key": "A","text": "Bacterial infection"},{"key": "B","text": "Chronic inhalation of inorganic dust particles"},{"key": "C","text": "Viral infection"},{"key": "D","text": "Allergic response to pollen"}],"correct": "B","explanation": "Pneumoconiosis encompasses occupational lung diseases from prolonged inhalation of mineral dusts like silica, coal, or asbestos."},{"id": 4026,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Silicosis is an occupational lung disease caused by inhalation of:","options": [{"key": "A","text": "Coal dust"},{"key": "B","text": "Cotton fibers"},{"key": "C","text": "Silica dust (e.g., in mining, sandblasting)"},{"key": "D","text": "Asbestos fibers"}],"correct": "C","explanation": "Silicosis results from chronic silica dust exposure, causing nodular pulmonary fibrosis, common in miners and stone workers."},{"id": 4027,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Hard","question": "Asbestosis characteristically causes fibrosis predominantly in which lung zones?","options": [{"key": "A","text": "No zonal preference"},{"key": "B","text": "Middle zones only"},{"key": "C","text": "Upper lung zones"},{"key": "D","text": "Lower lung zones"}],"correct": "D","explanation": "Asbestosis typically shows a lower zone-predominant interstitial fibrosis pattern, unlike silicosis which favors upper zones."},{"id": 4028,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Coal worker's pneumoconiosis ('black lung disease') results from chronic inhalation of:","options": [{"key": "A","text": "Coal dust"},{"key": "B","text": "Silica alone"},{"key": "C","text": "Cotton dust"},{"key": "D","text": "Asbestos fibers"}],"correct": "A","explanation": "Prolonged coal dust inhalation causes pigment-laden macrophage accumulation and progressive massive fibrosis in miners."},{"id": 4029,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Byssinosis, an occupational lung disease, is caused by exposure to:","options": [{"key": "A","text": "Silica"},{"key": "B","text": "Coal dust"},{"key": "C","text": "Asbestos"},{"key": "D","text": "Cotton dust"}],"correct": "D","explanation": "Byssinosis ('brown lung disease') results from chronic cotton, flax, or hemp dust exposure, common in textile workers."},{"id": 4030,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic exposure to asbestos increases risk of which malignancy in addition to asbestosis?","options": [{"key": "A","text": "Osteosarcoma"},{"key": "B","text": "Renal cell carcinoma"},{"key": "C","text": "Hepatocellular carcinoma"},{"key": "D","text": "Malignant mesothelioma"}],"correct": "D","explanation": "Asbestos exposure is the leading cause of malignant mesothelioma, a cancer of the pleura/peritoneum."},{"id": 4031,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Diaphragmatic breathing exercises are particularly beneficial in patients with which condition?","options": [{"key": "A","text": "Acute pneumothorax only"},{"key": "B","text": "COPD (to reduce work of breathing and improve ventilation)"},{"key": "C","text": "Severe rib fracture only"},{"key": "D","text": "Active tuberculosis with hemoptysis"}],"correct": "B","explanation": "Diaphragmatic breathing helps COPD patients reduce accessory muscle use and improve ventilation efficiency, a core physiotherapy intervention."},{"id": 4032,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pursed-lip breathing technique in COPD patients primarily helps by:","options": [{"key": "A","text": "Decreasing tidal volume drastically"},{"key": "B","text": "Preventing airway collapse during expiration and reducing air trapping"},{"key": "C","text": "Increasing respiratory rate"},{"key": "D","text": "Increasing oxygen consumption"}],"correct": "B","explanation": "Pursed-lip breathing creates back-pressure that keeps airways open longer during exhalation, reducing dynamic airway collapse in emphysema."},{"id": 4033,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Chest physiotherapy techniques like postural drainage and percussion are most beneficial for patients with:","options": [{"key": "A","text": "Pneumothorax with active air leak"},{"key": "B","text": "Acute pulmonary embolism"},{"key": "C","text": "Excessive bronchial secretions (e.g., bronchiectasis, cystic fibrosis)"},{"key": "D","text": "Simple viral upper respiratory infection"}],"correct": "C","explanation": "These airway clearance techniques mobilize and drain retained secretions, particularly beneficial in bronchiectasis and CF patients."},{"id": 4034,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cor pulmonale refers to:","options": [{"key": "A","text": "Right ventricular hypertrophy/failure secondary to chronic lung disease"},{"key": "B","text": "Left ventricular failure from hypertension"},{"key": "C","text": "Congenital heart defect"},{"key": "D","text": "Isolated valve disease"}],"correct": "A","explanation": "Cor pulmonale develops when chronic pulmonary hypertension (from lung disease like COPD) causes right ventricular strain and failure."},{"id": 4035,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Kartagener syndrome, causing recurrent respiratory infections, results from a defect in:","options": [{"key": "A","text": "Surfactant production"},{"key": "B","text": "Ciliary structure/motility (primary ciliary dyskinesia)"},{"key": "C","text": "Collagen synthesis"},{"key": "D","text": "Alveolar wall integrity"}],"correct": "B","explanation": "Kartagener syndrome involves defective ciliary dynein arms, impairing mucociliary clearance and causing situs inversus, sinusitis, and bronchiectasis."},{"id": 4036,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Whooping cough (pertussis) is caused by which organism?","options": [{"key": "A","text": "Haemophilus influenzae"},{"key": "B","text": "Streptococcus pneumoniae"},{"key": "C","text": "Mycobacterium tuberculosis"},{"key": "D","text": "Bordetella pertussis"}],"correct": "D","explanation": "Pertussis, caused by Bordetella pertussis, produces a characteristic paroxysmal cough with an inspiratory 'whoop'."},{"id": 4037,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Sarcoidosis is characterized pathologically by:","options": [{"key": "A","text": "Pure eosinophilic infiltration"},{"key": "B","text": "Caseating granulomas exclusively"},{"key": "C","text": "Diffuse alveolar hemorrhage"},{"key": "D","text": "Non-caseating granulomas in multiple organs, especially lungs and lymph nodes"}],"correct": "D","explanation": "Sarcoidosis is an idiopathic multisystem disease with non-caseating granulomas, commonly affecting hilar lymph nodes and lung parenchyma."},{"id": 4038,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pulmonary embolism classically presents with which triad of symptoms?","options": [{"key": "A","text": "Fever, cough, and sputum production"},{"key": "B","text": "Wheezing, cyanosis, and clubbing"},{"key": "C","text": "Chronic cough with weight loss"},{"key": "D","text": "Dyspnea, pleuritic chest pain, and hemoptysis"}],"correct": "D","explanation": "Acute PE classically presents with sudden dyspnea, pleuritic chest pain, and occasionally hemoptysis, though presentation varies widely."},{"id": 4039,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which is the most sensitive early sign of hypoxemia during physiotherapy exercise sessions to monitor?","options": [{"key": "A","text": "Patient's subjective fatigue alone"},{"key": "B","text": "Oxygen saturation (SpO2) via pulse oximetry"},{"key": "C","text": "Blood pressure alone"},{"key": "D","text": "Skin color changes only"}],"correct": "B","explanation": "Continuous pulse oximetry monitoring provides objective, early detection of desaturation during exercise, guiding safe intensity in pulmonary rehab."},{"id": 4040,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Digital clubbing is a clinical sign most classically associated with:","options": [{"key": "A","text": "Normal aging alone"},{"key": "B","text": "Simple asthma without complications"},{"key": "C","text": "Acute viral pharyngitis"},{"key": "D","text": "Chronic hypoxemic lung/heart disease (e.g., bronchiectasis, lung cancer, cyanotic heart disease)"}],"correct": "D","explanation": "Clubbing reflects chronic tissue hypoxia and is associated with conditions like bronchiectasis, lung cancer, and cyanotic congenital heart disease."},{"id": 4041,"subject": "Pathology","topic": "Neoplasia","difficulty": "Easy","question": "Bronchogenic carcinoma is most strongly associated with which risk factor?","options": [{"key": "A","text": "Genetic predisposition alone"},{"key": "B","text": "Viral infection primarily"},{"key": "C","text": "Occupational cotton exposure"},{"key": "D","text": "Cigarette smoking"}],"correct": "D","explanation": "Cigarette smoking is the single most important risk factor for lung cancer, accounting for the vast majority of cases."},{"id": 4042,"subject": "Pathology","topic": "Neoplasia","difficulty": "Hard","question": "Small cell lung carcinoma is characterized by:","options": [{"key": "A","text": "Excellent prognosis with surgery alone"},{"key": "B","text": "Rapid growth, early metastasis, and strong association with paraneoplastic syndromes"},{"key": "C","text": "Non-smoking association primarily"},{"key": "D","text": "Slow growth with late metastasis"}],"correct": "B","explanation": "Small cell carcinoma is highly aggressive, typically presents with early widespread metastasis, and is linked to paraneoplastic syndromes like SIADH."},{"id": 4043,"subject": "Pathology","topic": "Neoplasia","difficulty": "Hard","question": "Pancoast tumor, a lung cancer at the lung apex, can cause which characteristic syndrome due to sympathetic chain involvement?","options": [{"key": "A","text": "Carcinoid syndrome"},{"key": "B","text": "Cushing syndrome"},{"key": "C","text": "SIADH"},{"key": "D","text": "Horner's syndrome"}],"correct": "D","explanation": "Apical lung tumors can invade the sympathetic chain causing Horner's syndrome (ptosis, miosis, anhidrosis)."},{"id": 4044,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pulmonary rehabilitation programs for COPD patients primarily aim to improve:","options": [{"key": "A","text": "Exercise tolerance, dyspnea, and quality of life"},{"key": "B","text": "Cure the underlying disease"},{"key": "C","text": "Eliminate need for all medications"},{"key": "D","text": "Reverse existing alveolar destruction"}],"correct": "A","explanation": "Pulmonary rehab improves functional capacity and symptom management, though it cannot reverse the structural lung damage already present."},{"id": 4045,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Incentive spirometry works by encouraging patients to perform:","options": [{"key": "A","text": "Slow, deep sustained inspiration"},{"key": "B","text": "Coughing exercises only"},{"key": "C","text": "Breath holding without inhalation"},{"key": "D","text": "Rapid forceful exhalation"}],"correct": "A","explanation": "Incentive spirometry promotes sustained maximal inhalation to expand alveoli and prevent/treat atelectasis."},{"id": 4046,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Hypoxic pulmonary vasoconstriction is a physiological response where:","options": [{"key": "A","text": "Systemic vessels alone respond to hypoxia"},{"key": "B","text": "Vessels dilate in hypoxic areas"},{"key": "C","text": "Pulmonary vessels constrict in poorly ventilated lung areas to redirect blood flow"},{"key": "D","text": "No vascular response occurs to hypoxia"}],"correct": "C","explanation": "This unique pulmonary reflex diverts blood away from poorly ventilated alveoli toward better-ventilated areas, optimizing gas exchange, though chronic hypoxia (e.g., COPD) can cause pulmonary hypertension."},{"id": 4047,"subject": "Pathology","topic": "Hematology","difficulty": "Easy","question": "Iron deficiency anemia is characterized by which red cell morphology?","options": [{"key": "A","text": "Microcytic hyperchromic"},{"key": "B","text": "Microcytic hypochromic"},{"key": "C","text": "Macrocytic normochromic"},{"key": "D","text": "Normocytic normochromic"}],"correct": "B","explanation": "Iron deficiency impairs hemoglobin synthesis, producing small, pale (microcytic, hypochromic) red blood cells."},{"id": 4048,"subject": "Pathology","topic": "Hematology","difficulty": "Easy","question": "Megaloblastic anemia (B12/folate deficiency) is characterized by which red cell morphology?","options": [{"key": "A","text": "Spherocytic"},{"key": "B","text": "Normocytic"},{"key": "C","text": "Macrocytic"},{"key": "D","text": "Microcytic"}],"correct": "C","explanation": "B12/folate deficiency impairs DNA synthesis, producing large, immature megaloblastic red cells."},{"id": 4049,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Pernicious anemia results from deficiency of intrinsic factor, causing malabsorption of:","options": [{"key": "A","text": "Iron"},{"key": "B","text": "Vitamin B12"},{"key": "C","text": "Folate"},{"key": "D","text": "Vitamin C"}],"correct": "B","explanation": "Autoimmune destruction of gastric parietal cells reduces intrinsic factor, impairing B12 absorption and causing pernicious anemia."},{"id": 4050,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Sickle cell anemia results in red cells that sickle under conditions of:","options": [{"key": "A","text": "High oxygen tension only"},{"key": "B","text": "Normal physiological conditions"},{"key": "C","text": "Hypoxia, dehydration, and acidosis"},{"key": "D","text": "Cold exposure only"}],"correct": "C","explanation": "Deoxygenated HbS polymerizes causing red cells to sickle, particularly triggered by hypoxia, dehydration, and acidosis."},{"id": 4051,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Sickle cell crisis causing severe bone pain is termed:","options": [{"key": "A","text": "Vaso-occlusive crisis"},{"key": "B","text": "Sequestration crisis"},{"key": "C","text": "Hemolytic crisis"},{"key": "D","text": "Aplastic crisis"}],"correct": "A","explanation": "Vaso-occlusive crisis occurs when sickled cells obstruct microvasculature, causing ischemic bone/organ pain, a key physiotherapy pain management consideration."},{"id": 4052,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Thalassemia results from a defect in:","options": [{"key": "A","text": "Heme synthesis"},{"key": "B","text": "Iron absorption"},{"key": "C","text": "Globin chain synthesis (alpha or beta)"},{"key": "D","text": "Vitamin B12 metabolism"}],"correct": "C","explanation": "Thalassemias are inherited disorders of reduced or absent alpha or beta globin chain production, causing hemolytic anemia."},{"id": 4053,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hereditary spherocytosis results from a defect in which red cell component?","options": [{"key": "A","text": "Iron transport proteins"},{"key": "B","text": "Hemoglobin globin chains"},{"key": "C","text": "Red cell membrane cytoskeleton (spectrin)"},{"key": "D","text": "White cell membrane"}],"correct": "C","explanation": "Spectrin/ankyrin defects weaken the red cell membrane, causing spherical, fragile cells prone to splenic destruction."},{"id": 4054,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Aplastic anemia is characterized by:","options": [{"key": "A","text": "Normal marrow with peripheral destruction only"},{"key": "B","text": "Isolated red cell deficiency only"},{"key": "C","text": "Excess white cell production"},{"key": "D","text": "Bone marrow failure with pancytopenia"}],"correct": "D","explanation": "Aplastic anemia results from bone marrow hypoplasia, causing deficiency of all three cell lines (pancytopenia)."},{"id": 4055,"subject": "Pathology","topic": "Hematology","difficulty": "Hard","question": "Anemia of chronic disease is characterized by which iron study pattern?","options": [{"key": "A","text": "Normal iron studies throughout"},{"key": "B","text": "Low serum iron, low/normal TIBC, normal/high ferritin"},{"key": "C","text": "High serum iron with low ferritin"},{"key": "D","text": "Low ferritin with high TIBC"}],"correct": "B","explanation": "Chronic inflammation causes iron sequestration (via hepcidin), showing low iron but preserved/elevated ferritin, unlike true iron deficiency."},{"id": 4056,"subject": "Pathology","topic": "Hematology","difficulty": "Hard","question": "Hemolytic anemia is characterized biochemically by:","options": [{"key": "A","text": "Elevated indirect bilirubin and LDH with reduced haptoglobin"},{"key": "B","text": "Normal LDH and bilirubin"},{"key": "C","text": "Elevated haptoglobin"},{"key": "D","text": "Elevated direct bilirubin only"}],"correct": "A","explanation": "Increased red cell destruction releases hemoglobin breakdown products, raising indirect bilirubin/LDH while consuming haptoglobin."},{"id": 4057,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Acute lymphoblastic leukemia (ALL) is most common in which age group?","options": [{"key": "A","text": "Neonates only"},{"key": "B","text": "Children"},{"key": "C","text": "Elderly adults only"},{"key": "D","text": "Middle-aged adults only"}],"correct": "B","explanation": "ALL is the most common childhood malignancy, with a peak incidence in early childhood."},{"id": 4058,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic lymphocytic leukemia (CLL) typically affects which age group?","options": [{"key": "A","text": "Adolescents primarily"},{"key": "B","text": "Older adults"},{"key": "C","text": "Young children"},{"key": "D","text": "Neonates"}],"correct": "B","explanation": "CLL is a disease of the elderly, characterized by accumulation of mature-appearing but dysfunctional lymphocytes."},{"id": 4059,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic myeloid leukemia (CML) is characterized by which genetic abnormality?","options": [{"key": "A","text": "Philadelphia chromosome (BCR-ABL translocation)"},{"key": "B","text": "c-myc translocation"},{"key": "C","text": "Deletion of chromosome 5"},{"key": "D","text": "Trisomy 21"}],"correct": "A","explanation": "CML is defined by the t(9;22) translocation producing the BCR-ABL fusion gene (Philadelphia chromosome), driving uncontrolled myeloid proliferation."},{"id": 4060,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Acute myeloid leukemia (AML) is characterized by which cell type finding on peripheral smear?","options": [{"key": "A","text": "Lymphoblasts only"},{"key": "B","text": "Smudge cells"},{"key": "C","text": "Mature neutrophils only"},{"key": "D","text": "Myeloblasts with Auer rods"}],"correct": "D","explanation": "Auer rods, needle-like azurophilic cytoplasmic inclusions, are a characteristic finding in AML myeloblasts."},{"id": 4061,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hodgkin lymphoma is characterized histologically by the presence of:","options": [{"key": "A","text": "Reed-Sternberg cells"},{"key": "B","text": "Smudge cells"},{"key": "C","text": "Auer rods"},{"key": "D","text": "Sickle cells"}],"correct": "A","explanation": "Reed-Sternberg cells, large binucleate cells with prominent nucleoli ('owl-eye'), are pathognomonic for Hodgkin lymphoma."},{"id": 4062,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Multiple myeloma is a malignancy of which cell type?","options": [{"key": "A","text": "T lymphocytes"},{"key": "B","text": "Myeloid precursors"},{"key": "C","text": "Plasma cells"},{"key": "D","text": "B lymphocytes (immature)"}],"correct": "C","explanation": "Multiple myeloma involves malignant proliferation of plasma cells producing monoclonal immunoglobulin (M protein)."},{"id": 4063,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Multiple myeloma classically causes bone pain and lytic lesions primarily due to:","options": [{"key": "A","text": "Vitamin D toxicity"},{"key": "B","text": "Osteoblast overactivity"},{"key": "C","text": "Direct bone infection"},{"key": "D","text": "Osteoclast activation by cytokines (e.g., RANKL) from malignant plasma cells"}],"correct": "D","explanation": "Malignant plasma cells stimulate osteoclastic bone resorption, causing characteristic 'punched-out' lytic lesions and pathological fractures."},{"id": 4064,"subject": "Pathology","topic": "Hematology","difficulty": "Easy","question": "Hemophilia A results from deficiency of which clotting factor?","options": [{"key": "A","text": "Von Willebrand factor primarily"},{"key": "B","text": "Factor VIII"},{"key": "C","text": "Factor XI"},{"key": "D","text": "Factor IX"}],"correct": "B","explanation": "Hemophilia A is an X-linked recessive disorder due to Factor VIII deficiency, causing prolonged bleeding, especially hemarthroses."},{"id": 4065,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Hemophilia B results from deficiency of which clotting factor?","options": [{"key": "A","text": "Factor VII"},{"key": "B","text": "Factor IX"},{"key": "C","text": "Factor X"},{"key": "D","text": "Factor VIII"}],"correct": "B","explanation": "Hemophilia B (Christmas disease) is caused by Factor IX deficiency, clinically similar to Hemophilia A."},{"id": 4066,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Recurrent hemarthrosis (joint bleeding) in hemophilia most commonly affects which joint?","options": [{"key": "A","text": "Wrist joint"},{"key": "B","text": "Knee joint"},{"key": "C","text": "Hip joint only"},{"key": "D","text": "Shoulder joint"}],"correct": "B","explanation": "The knee is the most commonly affected joint in hemophilic hemarthrosis, leading to chronic hemophilic arthropathy requiring physiotherapy management."},{"id": 4067,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Von Willebrand disease is characterized by deficiency/dysfunction of:","options": [{"key": "A","text": "Vitamin K-dependent factors"},{"key": "B","text": "Fibrinogen"},{"key": "C","text": "Factor VIII only"},{"key": "D","text": "Von Willebrand factor, impairing platelet adhesion"}],"correct": "D","explanation": "VWD is the most common inherited bleeding disorder, causing mucocutaneous bleeding due to impaired platelet adhesion."},{"id": 4068,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Immune thrombocytopenic purpura (ITP) results from:","options": [{"key": "A","text": "Bone marrow failure"},{"key": "B","text": "Autoimmune destruction of platelets"},{"key": "C","text": "Vitamin K deficiency"},{"key": "D","text": "Factor VIII deficiency"}],"correct": "B","explanation": "ITP involves autoantibodies against platelets, causing their destruction and resultant thrombocytopenia with mucocutaneous bleeding."},{"id": 4069,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Vitamin K deficiency impairs synthesis of which clotting factors?","options": [{"key": "A","text": "Von Willebrand factor only"},{"key": "B","text": "Factors II, VII, IX, X"},{"key": "C","text": "Fibrinogen only"},{"key": "D","text": "Factor VIII only"}],"correct": "B","explanation": "Vitamin K is essential for gamma-carboxylation of factors II, VII, IX, and X in the liver, needed for their activity."},{"id": 4070,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Polycythemia vera is characterized by:","options": [{"key": "A","text": "Isolated platelet increase only"},{"key": "B","text": "Isolated white cell increase only"},{"key": "C","text": "Pancytopenia"},{"key": "D","text": "Clonal overproduction of red blood cells (often with elevated WBC/platelets too)"}],"correct": "D","explanation": "Polycythemia vera is a myeloproliferative disorder causing excessive RBC production, often with thrombosis risk requiring careful physiotherapy exercise planning."},{"id": 4071,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which physiotherapy precaution is important for patients with severe thrombocytopenia?","options": [{"key": "A","text": "Prioritize deep tissue massage"},{"key": "B","text": "Avoid high-impact/contact activities that risk bleeding or bruising"},{"key": "C","text": "No precautions are needed"},{"key": "D","text": "Encourage maximal resistance training"}],"correct": "B","explanation": "Low platelet counts increase bleeding risk, so physiotherapists must modify exercise intensity and avoid high-impact/contact activities."},{"id": 4072,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Disseminated intravascular coagulation (DIC) laboratory findings classically show:","options": [{"key": "A","text": "Shortened PT/PTT with normal fibrinogen"},{"key": "B","text": "Elevated fibrinogen with normal D-dimer"},{"key": "C","text": "Normal PT/PTT with high platelets"},{"key": "D","text": "Prolonged PT/PTT, low fibrinogen, low platelets, elevated D-dimer"}],"correct": "D","explanation": "DIC consumes clotting factors and platelets while activating fibrinolysis, producing this characteristic lab pattern."},{"id": 4073,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Warfarin therapy is monitored using which laboratory test?","options": [{"key": "A","text": "INR (International Normalized Ratio) based on PT"},{"key": "B","text": "Platelet count"},{"key": "C","text": "Bleeding time"},{"key": "D","text": "aPTT"}],"correct": "A","explanation": "Warfarin affects vitamin K-dependent factors, monitored via PT/INR to guide dosing and assess bleeding risk."},{"id": 4074,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Heparin therapy is monitored using which laboratory test?","options": [{"key": "A","text": "Bleeding time"},{"key": "B","text": "aPTT (activated partial thromboplastin time)"},{"key": "C","text": "INR/PT"},{"key": "D","text": "D-dimer"}],"correct": "B","explanation": "Heparin affects the intrinsic pathway, monitored using aPTT to ensure therapeutic anticoagulation without excessive bleeding risk."},{"id": 4075,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Patients on anticoagulant therapy require which precaution during physiotherapy sessions?","options": [{"key": "A","text": "Encourage aggressive deep tissue massage"},{"key": "B","text": "Increase manual resistance training intensity"},{"key": "C","text": "No special precautions needed"},{"key": "D","text": "Careful monitoring for bruising/bleeding and avoiding high-impact/contact techniques"}],"correct": "D","explanation": "Anticoagulated patients have elevated bleeding risk, requiring gentle handling and vigilance for bruising during rehabilitation."},{"id": 4076,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Burkitt lymphoma is associated with which chromosomal translocation?","options": [{"key": "A","text": "t(15;17)"},{"key": "B","text": "t(8;14) involving c-myc"},{"key": "C","text": "t(14;18)"},{"key": "D","text": "t(9;22) Philadelphia chromosome"}],"correct": "B","explanation": "Burkitt lymphoma is characterized by the t(8;14) translocation activating the c-myc oncogene."},{"id": 4077,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Follicular lymphoma is classically associated with which translocation?","options": [{"key": "A","text": "t(9;22)"},{"key": "B","text": "t(15;17)"},{"key": "C","text": "t(8;14)"},{"key": "D","text": "t(14;18) involving BCL-2"}],"correct": "D","explanation": "Follicular lymphoma's t(14;18) translocation overexpresses BCL-2, an anti-apoptotic protein, promoting lymphoma cell survival."},{"id": 4078,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Acute promyelocytic leukemia (APL) is associated with which translocation?","options": [{"key": "A","text": "t(15;17) involving PML-RARA"},{"key": "B","text": "t(9;22)"},{"key": "C","text": "t(14;18)"},{"key": "D","text": "t(8;14)"}],"correct": "A","explanation": "APL's t(15;17) fusion disrupts retinoic acid receptor function, and treatment includes all-trans retinoic acid (ATRA)."},{"id": 4079,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Splenomegaly is a common finding in which of the following hematologic conditions?","options": [{"key": "A","text": "Isolated iron deficiency anemia only"},{"key": "B","text": "Uncomplicated hemophilia"},{"key": "C","text": "Chronic myeloid leukemia and hemolytic anemias"},{"key": "D","text": "Simple vitamin deficiency without hemolysis"}],"correct": "C","explanation": "Splenomegaly occurs with increased splenic workload from destroying abnormal cells (hemolysis) or extramedullary hematopoiesis (CML)."},{"id": 4080,"subject": "Pathology","topic": "Hematology","difficulty": "Easy","question": "Which of the following is a common physiotherapy consideration for patients with severe anemia?","options": [{"key": "A","text": "Monitor for fatigue/dyspnea and pace exercise intensity accordingly"},{"key": "B","text": "Push maximal exercise intensity regardless of symptoms"},{"key": "C","text": "Avoid all monitoring of vital signs"},{"key": "D","text": "No modification needed for exercise prescription"}],"correct": "A","explanation": "Reduced oxygen-carrying capacity in anemia necessitates careful pacing and monitoring during physical therapy sessions to avoid overexertion."},{"id": 4081,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neutropenia (low neutrophil count), often seen after chemotherapy, requires which precaution in physiotherapy practice?","options": [{"key": "A","text": "Encourage group therapy sessions without precautions"},{"key": "B","text": "Strict infection control measures and hand hygiene during patient contact"},{"key": "C","text": "No special precaution needed"},{"key": "D","text": "Avoid hand hygiene protocols"}],"correct": "B","explanation": "Neutropenic patients have high infection risk, requiring meticulous infection control practices during any physical contact/therapy."},{"id": 4082,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Which type of anemia is most likely in a strict vegetarian/vegan patient due to dietary restriction?","options": [{"key": "A","text": "Vitamin B12 deficiency anemia"},{"key": "B","text": "Thalassemia"},{"key": "C","text": "Sickle cell anemia"},{"key": "D","text": "Iron deficiency from excess red meat"}],"correct": "A","explanation": "Vitamin B12 is found almost exclusively in animal products, making strict vegans prone to B12 deficiency and resultant megaloblastic anemia."},{"id": 4083,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Reticulocyte count is a useful marker of:","options": [{"key": "A","text": "Bone marrow's red cell production response"},{"key": "B","text": "Platelet aggregation"},{"key": "C","text": "White cell function"},{"key": "D","text": "Clotting factor activity"}],"correct": "A","explanation": "Elevated reticulocytes indicate active marrow response (e.g., in hemolysis/blood loss), while low counts suggest impaired production."},{"id": 4084,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Direct Coombs test is used to detect:","options": [{"key": "A","text": "Clotting factor deficiencies"},{"key": "B","text": "Antibodies free in plasma only"},{"key": "C","text": "Antibodies bound to the surface of red blood cells"},{"key": "D","text": "Platelet antibodies specifically"}],"correct": "C","explanation": "Direct Coombs test detects antibody/complement already attached to RBCs, useful in diagnosing autoimmune hemolytic anemia."},{"id": 4085,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Beta-thalassemia major classically presents in early childhood with:","options": [{"key": "A","text": "Severe anemia requiring regular blood transfusions and skeletal changes"},{"key": "B","text": "Mild, asymptomatic anemia only"},{"key": "C","text": "No clinical manifestations"},{"key": "D","text": "Isolated bleeding tendency"}],"correct": "A","explanation": "Beta-thalassemia major causes severe transfusion-dependent anemia along with skeletal deformities from marrow expansion ('chipmunk facies')."},{"id": 4086,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic blood transfusions in thalassemia major can lead to which complication requiring monitoring?","options": [{"key": "A","text": "Iron deficiency"},{"key": "B","text": "Vitamin toxicity unrelated to iron"},{"key": "C","text": "Excess platelet production only"},{"key": "D","text": "Iron overload (hemosiderosis) affecting heart, liver, and endocrine organs"}],"correct": "D","explanation": "Repeated transfusions cause progressive iron accumulation in organs, requiring chelation therapy to prevent cardiac/hepatic damage."},{"id": 4087,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Extramedullary hematopoiesis, seen in severe thalassemia, refers to:","options": [{"key": "A","text": "Blood cell production occurring outside the bone marrow (e.g., liver, spleen)"},{"key": "B","text": "Complete cessation of blood cell production"},{"key": "C","text": "Hematopoiesis confined only to long bones"},{"key": "D","text": "Increased marrow production only"}],"correct": "A","explanation": "When marrow demand exceeds capacity, the liver and spleen resume fetal-type blood cell production, causing organomegaly."},{"id": 4088,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which of the following best distinguishes leukemia from lymphoma in general terms?","options": [{"key": "A","text": "Leukemia never involves the blood"},{"key": "B","text": "Lymphoma always involves bone marrow exclusively"},{"key": "C","text": "Both are identical in presentation always"},{"key": "D","text": "Leukemia primarily involves bone marrow/blood; lymphoma primarily involves lymph nodes/tissues"}],"correct": "D","explanation": "Leukemias arise in and circulate through bone marrow/peripheral blood, while lymphomas typically form solid tumor masses in lymphoid tissue, though overlap can occur."},{"id": 4089,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Gastroesophageal reflux disease (GERD) is caused primarily by:","options": [{"key": "A","text": "Incompetent lower esophageal sphincter allowing acid reflux"},{"key": "B","text": "Delayed gastric emptying only"},{"key": "C","text": "Excess saliva production"},{"key": "D","text": "Bacterial infection"}],"correct": "A","explanation": "GERD results from a weak/relaxed lower esophageal sphincter allowing gastric acid to reflux into the esophagus."},{"id": 4090,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Barrett's esophagus is a premalignant condition that increases risk of which cancer?","options": [{"key": "A","text": "Gastric lymphoma"},{"key": "B","text": "Esophageal squamous cell carcinoma"},{"key": "C","text": "Esophageal adenocarcinoma"},{"key": "D","text": "Colorectal cancer"}],"correct": "C","explanation": "Barrett's metaplastic columnar epithelium predisposes to dysplasia and subsequent esophageal adenocarcinoma."},{"id": 4091,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Peptic ulcer disease is most commonly caused by:","options": [{"key": "A","text": "Excess mucus production"},{"key": "B","text": "Helicobacter pylori infection"},{"key": "C","text": "Autoimmune destruction"},{"key": "D","text": "Viral infection"}],"correct": "B","explanation": "H. pylori infection is the leading cause of peptic ulcers, along with NSAID use as another major contributor."},{"id": 4092,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "NSAID-induced peptic ulcers occur primarily due to:","options": [{"key": "A","text": "Excess acid production alone"},{"key": "B","text": "Inhibition of prostaglandin synthesis reducing mucosal protection"},{"key": "C","text": "Increased mucus secretion"},{"key": "D","text": "Direct bacterial infection"}],"correct": "B","explanation": "NSAIDs inhibit COX enzymes, reducing protective prostaglandins and weakening the gastric mucosal barrier."},{"id": 4093,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Gastric ulcers classically show which relationship between pain and eating?","options": [{"key": "A","text": "Pain improves with eating and recurs 2-3 hours later"},{"key": "B","text": "Pain worsens with eating"},{"key": "C","text": "Pain occurs only at night, unrelated to meals"},{"key": "D","text": "No relationship with food intake"}],"correct": "B","explanation": "Gastric ulcer pain typically worsens shortly after eating, unlike duodenal ulcers which are relieved by food."},{"id": 4094,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Duodenal ulcers classically show which relationship between pain and eating?","options": [{"key": "A","text": "Pain worsens immediately with eating"},{"key": "B","text": "Pain only during fasting states with no recurrence"},{"key": "C","text": "Pain improves with eating, recurring 2-3 hours later (night pain common)"},{"key": "D","text": "No relationship with meals at all"}],"correct": "C","explanation": "Duodenal ulcer pain is typically relieved by food and recurs a few hours later, often causing nocturnal pain."},{"id": 4095,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Peptic ulcer perforation classically presents with:","options": [{"key": "A","text": "Sudden severe abdominal pain with rigid ('board-like') abdomen"},{"key": "B","text": "Painless bleeding only"},{"key": "C","text": "Chronic intermittent bloating"},{"key": "D","text": "Gradual onset of mild discomfort"}],"correct": "A","explanation": "Perforation causes peritonitis, presenting with sudden severe pain and rigid abdominal wall guarding, a surgical emergency."},{"id": 4096,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ulcerative colitis characteristically involves which part of the GI tract?","options": [{"key": "A","text": "Only the esophagus"},{"key": "B","text": "Skip lesions throughout the entire GI tract"},{"key": "C","text": "Transmural inflammation of small bowel primarily"},{"key": "D","text": "Continuous inflammation limited to the colon/rectum (mucosal layer)"}],"correct": "D","explanation": "UC causes continuous, mucosal-only inflammation confined to the colon, typically starting from the rectum."},{"id": 4097,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Crohn's disease characteristically shows which pattern of GI involvement?","options": [{"key": "A","text": "Only affects the esophagus"},{"key": "B","text": "Only affects the stomach"},{"key": "C","text": "Skip lesions with transmural inflammation anywhere from mouth to anus"},{"key": "D","text": "Continuous mucosal inflammation limited to colon"}],"correct": "C","explanation": "Crohn's disease can affect any part of the GI tract with discontinuous 'skip lesions' and full-thickness (transmural) inflammation."},{"id": 4098,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which extraintestinal manifestation is commonly associated with inflammatory bowel disease and relevant to physiotherapy?","options": [{"key": "A","text": "Cataracts only"},{"key": "B","text": "Isolated hearing loss"},{"key": "C","text": "Hair loss only"},{"key": "D","text": "Peripheral arthritis and ankylosing spondylitis"}],"correct": "D","explanation": "IBD (both UC and Crohn's) is associated with joint manifestations including peripheral arthritis and axial spondyloarthropathy."},{"id": 4099,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Celiac disease results from immune-mediated damage to the small intestine triggered by:","options": [{"key": "A","text": "Excess dietary fat"},{"key": "B","text": "Lactose"},{"key": "C","text": "Red meat protein"},{"key": "D","text": "Gluten (in wheat, barley, rye)"}],"correct": "D","explanation": "Celiac disease is an autoimmune reaction to gluten causing villous atrophy and malabsorption in the small intestine."},{"id": 4100,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Villous atrophy in celiac disease primarily leads to:","options": [{"key": "A","text": "Isolated vitamin K deficiency only"},{"key": "B","text": "No functional impairment"},{"key": "C","text": "Malabsorption of nutrients"},{"key": "D","text": "Excess nutrient absorption"}],"correct": "C","explanation": "Destruction of intestinal villi reduces the absorptive surface area, causing malabsorption of various nutrients."},{"id": 4101,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Acute pancreatitis is most commonly caused by which two conditions?","options": [{"key": "A","text": "Gallstones and chronic alcohol use"},{"key": "B","text": "Peptic ulcer and GERD"},{"key": "C","text": "Viral hepatitis and diabetes"},{"key": "D","text": "Colorectal cancer and IBD"}],"correct": "A","explanation": "Gallstones and alcohol abuse together account for the vast majority of acute pancreatitis cases."},{"id": 4102,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which pancreatic enzymes are elevated in acute pancreatitis and used for diagnosis?","options": [{"key": "A","text": "Troponin and CK-MB"},{"key": "B","text": "AST and ALT"},{"key": "C","text": "Alkaline phosphatase and GGT"},{"key": "D","text": "Amylase and lipase"}],"correct": "D","explanation": "Serum amylase and lipase, particularly lipase (more specific), are elevated and used to diagnose acute pancreatitis."},{"id": 4103,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic pancreatitis eventually leads to which endocrine/exocrine complications?","options": [{"key": "A","text": "Only hyperthyroidism"},{"key": "B","text": "Only hepatic failure"},{"key": "C","text": "Diabetes mellitus and malabsorption/steatorrhea"},{"key": "D","text": "No long-term complications"}],"correct": "C","explanation": "Chronic pancreatic damage impairs both insulin production (causing diabetes) and digestive enzyme secretion (causing malabsorption/steatorrhea)."},{"id": 4104,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Cirrhosis of the liver is best defined as:","options": [{"key": "A","text": "Isolated bile duct obstruction"},{"key": "B","text": "Acute inflammation of liver only"},{"key": "C","text": "Diffuse fibrosis with regenerative nodules replacing normal liver architecture"},{"key": "D","text": "Fatty infiltration without fibrosis"}],"correct": "C","explanation": "Cirrhosis represents the end-stage of chronic liver injury, with fibrous septa and regenerative nodules disrupting normal architecture."},{"id": 4105,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The most common cause of cirrhosis worldwide is:","options": [{"key": "A","text": "Hemochromatosis alone"},{"key": "B","text": "Autoimmune hepatitis alone"},{"key": "C","text": "Chronic viral hepatitis (B and C) and alcohol use"},{"key": "D","text": "Wilson's disease alone"}],"correct": "C","explanation": "Chronic viral hepatitis and alcoholic liver disease together account for the majority of cirrhosis cases globally."},{"id": 4106,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Portal hypertension, a complication of cirrhosis, classically leads to which findings?","options": [{"key": "A","text": "No effect on venous system"},{"key": "B","text": "Hypertension in systemic circulation only"},{"key": "C","text": "Isolated peripheral edema only"},{"key": "D","text": "Esophageal varices, splenomegaly, and ascites"}],"correct": "D","explanation": "Increased resistance to portal blood flow causes collateral vessel formation (varices), splenic congestion, and fluid accumulation (ascites)."},{"id": 4107,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hepatic encephalopathy, a complication of liver failure, results from accumulation of:","options": [{"key": "A","text": "Excess bilirubin only"},{"key": "B","text": "Excess copper only"},{"key": "C","text": "Ammonia and other nitrogenous toxins"},{"key": "D","text": "Excess iron"}],"correct": "C","explanation": "Impaired hepatic clearance of ammonia (from protein metabolism) leads to neurotoxicity and altered mental status."},{"id": 4108,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Asterixis (flapping tremor) is a characteristic neurological sign of:","options": [{"key": "A","text": "Hepatic encephalopathy"},{"key": "B","text": "Peripheral neuropathy"},{"key": "C","text": "Parkinson's disease"},{"key": "D","text": "Cerebellar ataxia"}],"correct": "A","explanation": "Asterixis reflects metabolic encephalopathy, classically seen in hepatic failure due to ammonia toxicity affecting motor pathways."},{"id": 4109,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Jaundice results from accumulation of which substance in the blood/tissues?","options": [{"key": "A","text": "Creatinine"},{"key": "B","text": "Ammonia"},{"key": "C","text": "Bilirubin"},{"key": "D","text": "Urea"}],"correct": "C","explanation": "Jaundice (yellow discoloration of skin/sclera) reflects elevated serum bilirubin from various hepatic or hemolytic causes."},{"id": 4110,"subject": "Pathology","topic": "Infectious Disease","difficulty": "Easy","question": "Hepatitis A virus is transmitted primarily via:","options": [{"key": "A","text": "Sexual contact primarily"},{"key": "B","text": "Blood transfusion"},{"key": "C","text": "Fecal-oral route (contaminated food/water)"},{"key": "D","text": "Vertical (mother to child) transmission"}],"correct": "C","explanation": "HAV spreads through the fecal-oral route, typically via contaminated food or water, causing acute (usually self-limiting) hepatitis."},{"id": 4111,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hepatitis B and C viruses are primarily transmitted via:","options": [{"key": "A","text": "Blood/body fluids (parenteral, sexual, vertical transmission)"},{"key": "B","text": "Insect vectors"},{"key": "C","text": "Airborne droplets"},{"key": "D","text": "Fecal-oral route"}],"correct": "A","explanation": "HBV and HCV spread through blood and body fluid exposure, and can become chronic, leading to cirrhosis and hepatocellular carcinoma."},{"id": 4112,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Wilson's disease results from abnormal accumulation of which metal in the liver, brain, and cornea?","options": [{"key": "A","text": "Copper"},{"key": "B","text": "Iron"},{"key": "C","text": "Zinc"},{"key": "D","text": "Calcium"}],"correct": "A","explanation": "Wilson's disease is an autosomal recessive disorder of copper metabolism causing hepatic and neurological damage, plus Kayser-Fleischer rings in the eye."},{"id": 4113,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hemochromatosis results from excessive accumulation of which substance, causing organ damage?","options": [{"key": "A","text": "Bilirubin"},{"key": "B","text": "Copper"},{"key": "C","text": "Iron"},{"key": "D","text": "Ammonia"}],"correct": "C","explanation": "Hereditary hemochromatosis causes excess iron absorption/deposition in liver, heart, pancreas, and joints, sometimes called 'bronze diabetes'."},{"id": 4114,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cholelithiasis (gallstones) most commonly consists of which composition?","options": [{"key": "A","text": "Cholesterol stones"},{"key": "B","text": "Pure bilirubin (pigment) stones only"},{"key": "C","text": "Uric acid stones"},{"key": "D","text": "Calcium oxalate stones"}],"correct": "A","explanation": "Cholesterol gallstones are the most common type in Western populations, related to bile cholesterol supersaturation."},{"id": 4115,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Acute appendicitis classically presents with pain that migrates from:","options": [{"key": "A","text": "Chest to left arm"},{"key": "B","text": "Left lower quadrant to back"},{"key": "C","text": "Periumbilical region to right iliac fossa (McBurney's point)"},{"key": "D","text": "Right upper quadrant to epigastrium"}],"correct": "C","explanation": "Appendicitis classically begins as vague periumbilical pain that later localizes to McBurney's point in the right lower quadrant."},{"id": 4116,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Diverticulitis most commonly affects which part of the colon?","options": [{"key": "A","text": "Transverse colon"},{"key": "B","text": "Cecum only"},{"key": "C","text": "Ascending colon"},{"key": "D","text": "Sigmoid colon"}],"correct": "D","explanation": "Diverticulitis, inflammation of colonic diverticula, most commonly occurs in the sigmoid colon due to higher intraluminal pressure there."},{"id": 4117,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Colorectal cancer screening and surveillance is particularly important in patients with which predisposing condition?","options": [{"key": "A","text": "Simple acute gastroenteritis"},{"key": "B","text": "Isolated hiatal hernia"},{"key": "C","text": "Uncomplicated GERD"},{"key": "D","text": "Long-standing ulcerative colitis"}],"correct": "D","explanation": "Chronic ulcerative colitis significantly increases the risk of colorectal carcinoma, warranting regular surveillance colonoscopy."},{"id": 4118,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Gastric adenocarcinoma is strongly associated with which infectious agent?","options": [{"key": "A","text": "EBV primarily"},{"key": "B","text": "Hepatitis B virus"},{"key": "C","text": "HPV"},{"key": "D","text": "Helicobacter pylori"}],"correct": "D","explanation": "Chronic H. pylori infection causes gastritis progressing to atrophy, metaplasia, and increased risk of gastric adenocarcinoma."},{"id": 4119,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Virchow's node (left supraclavicular lymph node enlargement) is classically associated with metastasis from:","options": [{"key": "A","text": "Skin cancer only"},{"key": "B","text": "Thyroid cancer only"},{"key": "C","text": "Lung cancer only"},{"key": "D","text": "Gastric carcinoma (and other abdominal malignancies)"}],"correct": "D","explanation": "Virchow's node reflects lymphatic spread from abdominal cancers, classically gastric carcinoma, via the thoracic duct."},{"id": 4120,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Hepatocellular carcinoma is most strongly associated with which underlying conditions?","options": [{"key": "A","text": "Isolated peptic ulcer disease"},{"key": "B","text": "Simple fatty liver without fibrosis"},{"key": "C","text": "Chronic hepatitis B/C infection and cirrhosis"},{"key": "D","text": "Celiac disease"}],"correct": "C","explanation": "Chronic viral hepatitis and cirrhosis from any cause are the leading risk factors for hepatocellular carcinoma."},{"id": 4121,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ascites, a common complication of cirrhosis, results primarily from:","options": [{"key": "A","text": "Excess protein synthesis"},{"key": "B","text": "Increased oncotic pressure only"},{"key": "C","text": "Decreased hydrostatic pressure"},{"key": "D","text": "Portal hypertension and hypoalbuminemia"}],"correct": "D","explanation": "Portal hypertension increases splanchnic capillary pressure while reduced albumin synthesis lowers oncotic pressure, both favoring ascitic fluid accumulation."},{"id": 4122,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Spontaneous bacterial peritonitis is a serious complication seen in patients with:","options": [{"key": "A","text": "Simple constipation"},{"key": "B","text": "Isolated peptic ulcer without complication"},{"key": "C","text": "Uncomplicated GERD"},{"key": "D","text": "Cirrhotic ascites"}],"correct": "D","explanation": "Ascitic fluid in cirrhotic patients is prone to bacterial infection due to impaired immune defenses, causing SBP."},{"id": 4123,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Gilbert syndrome is a benign condition causing mild jaundice due to:","options": [{"key": "A","text": "Reduced conjugation of bilirubin (mild UGT1A1 deficiency)"},{"key": "B","text": "Biliary obstruction"},{"key": "C","text": "Hemolysis of red cells"},{"key": "D","text": "Complete absence of bilirubin conjugation"}],"correct": "A","explanation": "Gilbert syndrome causes intermittent, mild unconjugated hyperbilirubinemia due to partial deficiency of the conjugating enzyme, generally benign."},{"id": 4124,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ischemic bowel disease (mesenteric ischemia) most commonly results from:","options": [{"key": "A","text": "Venous congestion of the portal vein only"},{"key": "B","text": "Excess dietary fiber"},{"key": "C","text": "Chronic constipation"},{"key": "D","text": "Occlusion of the superior mesenteric artery"}],"correct": "D","explanation": "Acute mesenteric ischemia is often due to embolic or thrombotic occlusion of the SMA, a surgical emergency."},{"id": 4125,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hiatal hernia refers to:","options": [{"key": "A","text": "Protrusion of intestine through the abdominal wall"},{"key": "B","text": "Protrusion of part of the stomach through the diaphragmatic esophageal hiatus into the thorax"},{"key": "C","text": "Protrusion of the rectum through the anus"},{"key": "D","text": "Herniation of a lumbar disc"}],"correct": "B","explanation": "Hiatal hernia involves upward displacement of the stomach through the diaphragm, contributing to GERD symptoms."},{"id": 4126,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Achalasia is characterized by:","options": [{"key": "A","text": "Failure of lower esophageal sphincter relaxation with loss of esophageal peristalsis"},{"key": "B","text": "Excess LES relaxation causing reflux"},{"key": "C","text": "Isolated gastric outlet obstruction"},{"key": "D","text": "Hypermotility of the entire GI tract"}],"correct": "A","explanation": "Achalasia results from degeneration of myenteric plexus neurons, causing failure of LES relaxation and impaired esophageal motility, producing dysphagia."},{"id": 4127,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Irritable bowel syndrome (IBS) is best characterized as:","options": [{"key": "A","text": "An inflammatory bowel disease with mucosal ulceration"},{"key": "B","text": "An infectious disease requiring antibiotics"},{"key": "C","text": "A malignant condition"},{"key": "D","text": "A functional GI disorder with altered bowel habits without structural/inflammatory pathology"}],"correct": "D","explanation": "IBS is a functional disorder causing abdominal pain and altered bowel habits, without identifiable structural or biochemical abnormality."},{"id": 4128,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Lactose intolerance results from deficiency of which enzyme?","options": [{"key": "A","text": "Amylase"},{"key": "B","text": "Sucrase only"},{"key": "C","text": "Lactase"},{"key": "D","text": "Lipase"}],"correct": "C","explanation": "Lactase deficiency impairs breakdown of lactose, causing undigested sugar to ferment in the colon, producing bloating and diarrhea."},{"id": 4129,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Post-abdominal surgery, early ambulation and breathing exercises are important physiotherapy interventions primarily to prevent:","options": [{"key": "A","text": "Excess scar tissue only"},{"key": "B","text": "Increased pain sensitivity"},{"key": "C","text": "Postoperative ileus, atelectasis, and DVT"},{"key": "D","text": "Wound infection directly"}],"correct": "C","explanation": "Early mobilization stimulates bowel motility and reduces pulmonary/thromboembolic complications following abdominal surgery."},{"id": 4130,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which nutritional deficiency is a common concern in patients with chronic malabsorptive conditions (e.g., celiac disease, Crohn's) relevant to bone health?","options": [{"key": "A","text": "Excess iron absorption"},{"key": "B","text": "Vitamin C excess"},{"key": "C","text": "No skeletal impact at all"},{"key": "D","text": "Vitamin D and calcium deficiency leading to osteoporosis/osteomalacia"}],"correct": "D","explanation": "Chronic malabsorption impairs vitamin D and calcium uptake, increasing risk of metabolic bone disease, a key physiotherapy consideration."},{"id": 4131,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Peritonitis classically presents with which clinical sign on abdominal examination?","options": [{"key": "A","text": "Absent bowel sounds with soft, non-tender abdomen"},{"key": "B","text": "Rebound tenderness and guarding"},{"key": "C","text": "Painless abdominal distension only"},{"key": "D","text": "No abdominal findings at all"}],"correct": "B","explanation": "Peritoneal inflammation causes rebound tenderness and involuntary guarding due to irritation of the peritoneal lining."},{"id": 4132,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Intestinal obstruction classically presents with which combination of symptoms?","options": [{"key": "A","text": "Painless diarrhea only"},{"key": "B","text": "Abdominal distension, colicky pain, vomiting, and absent flatus/stool"},{"key": "C","text": "Chronic mild constipation only"},{"key": "D","text": "Isolated fever without GI symptoms"}],"correct": "B","explanation": "Mechanical bowel obstruction produces this classic symptom complex due to blocked luminal flow and back-pressure."},{"id": 4133,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Fatty liver disease (steatosis) is most commonly associated with which two conditions?","options": [{"key": "A","text": "Isolated osteoporosis"},{"key": "B","text": "Obesity/metabolic syndrome and chronic alcohol use"},{"key": "C","text": "Isolated hypertension"},{"key": "D","text": "Vitamin C deficiency and anemia"}],"correct": "B","explanation": "Non-alcoholic fatty liver disease (linked to obesity/metabolic syndrome) and alcoholic fatty liver are the two leading causes of hepatic steatosis."},{"id": 4134,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Acute glomerulonephritis classically presents with which triad of findings?","options": [{"key": "A","text": "Excess urine output with no other findings"},{"key": "B","text": "Hematuria, hypertension, and edema"},{"key": "C","text": "Painless hematuria only"},{"key": "D","text": "Isolated proteinuria without hematuria"}],"correct": "B","explanation": "Acute GN, often post-streptococcal, causes this classic nephritic syndrome triad due to glomerular inflammation."},{"id": 4135,"subject": "Pathology","topic": "Infectious Disease","difficulty": "Medium","question": "Post-streptococcal glomerulonephritis typically occurs after infection with:","options": [{"key": "A","text": "Group A Streptococcus (throat or skin infection)"},{"key": "B","text": "Staphylococcus aureus"},{"key": "C","text": "Mycobacterium tuberculosis"},{"key": "D","text": "E. coli"}],"correct": "A","explanation": "PSGN develops 1-3 weeks after streptococcal pharyngitis or skin infection due to immune complex deposition in glomeruli."},{"id": 4136,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Nephrotic syndrome is characterized by which key features?","options": [{"key": "A","text": "Massive proteinuria, hypoalbuminemia, edema, and hyperlipidemia"},{"key": "B","text": "Hematuria and hypertension primarily"},{"key": "C","text": "Normal serum protein levels"},{"key": "D","text": "Absence of edema"}],"correct": "A","explanation": "Nephrotic syndrome results from severe glomerular protein leakage, causing this classic tetrad of findings."},{"id": 4137,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Minimal change disease, the most common cause of nephrotic syndrome in children, shows which finding on electron microscopy?","options": [{"key": "A","text": "Effacement (fusion) of podocyte foot processes"},{"key": "B","text": "Crescent formation"},{"key": "C","text": "Thickened glomerular basement membrane"},{"key": "D","text": "Immune complex deposits"}],"correct": "A","explanation": "Minimal change disease shows normal light microscopy but diffuse podocyte foot process effacement on EM."},{"id": 4138,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Diabetic nephropathy is a leading cause of chronic kidney disease, characterized histologically by:","options": [{"key": "A","text": "Crescent formation"},{"key": "B","text": "Minimal change only"},{"key": "C","text": "Amyloid deposition primarily"},{"key": "D","text": "Kimmelstiel-Wilson nodules (nodular glomerulosclerosis)"}],"correct": "D","explanation": "Diabetic nephropathy shows characteristic nodular glomerulosclerosis (Kimmelstiel-Wilson lesions) from chronic hyperglycemia-induced damage."},{"id": 4139,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Acute kidney injury (AKI) is classified into which three main categories based on cause?","options": [{"key": "A","text": "Only intrarenal causes exist"},{"key": "B","text": "Prerenal, intrarenal (renal), and postrenal"},{"key": "C","text": "Only prerenal causes exist"},{"key": "D","text": "Congenital and acquired only"}],"correct": "B","explanation": "AKI is classified by whether the cause is reduced renal perfusion (prerenal), intrinsic kidney damage (renal), or obstruction (postrenal)."},{"id": 4140,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Acute tubular necrosis (ATN), a common cause of intrarenal AKI, most commonly results from:","options": [{"key": "A","text": "Glomerular immune complex deposition only"},{"key": "B","text": "Ischemia or nephrotoxic injury to renal tubular cells"},{"key": "C","text": "Congenital malformation"},{"key": "D","text": "Ureteral obstruction"}],"correct": "B","explanation": "ATN results from ischemic or toxic (drugs, contrast, myoglobin) injury directly damaging renal tubular epithelial cells."},{"id": 4141,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Rhabdomyolysis can cause acute kidney injury primarily through which mechanism?","options": [{"key": "A","text": "Ureteral stone formation"},{"key": "B","text": "Glomerular immune complex deposition"},{"key": "C","text": "Myoglobin-induced tubular obstruction and direct toxicity"},{"key": "D","text": "Renal artery embolism"}],"correct": "C","explanation": "Released myoglobin from damaged muscle is nephrotoxic and can precipitate in renal tubules, causing ATN — important for physiotherapy patients after crush injury/severe exertion."},{"id": 4142,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic kidney disease (CKD) is defined as reduced kidney function or damage persisting for at least:","options": [{"key": "A","text": "24 hours"},{"key": "B","text": "1 week"},{"key": "C","text": "1 month only"},{"key": "D","text": "3 months"}],"correct": "D","explanation": "CKD is defined by decreased GFR or markers of kidney damage present for 3 months or longer."},{"id": 4143,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which stage of CKD is defined by GFR less than 15 mL/min/1.73m2, typically requiring dialysis/transplant?","options": [{"key": "A","text": "Stage 2"},{"key": "B","text": "Stage 3a"},{"key": "C","text": "Stage 1"},{"key": "D","text": "Stage 5 (end-stage renal disease)"}],"correct": "D","explanation": "CKD stage 5 (ESRD) reflects near-complete loss of kidney function, generally requiring renal replacement therapy."},{"id": 4144,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Renal osteodystrophy, a complication of chronic kidney disease, results from disturbances in:","options": [{"key": "A","text": "Calcium, phosphate, and vitamin D metabolism with secondary hyperparathyroidism"},{"key": "B","text": "Excess vitamin D production only"},{"key": "C","text": "Iron overload only"},{"key": "D","text": "Isolated protein metabolism"}],"correct": "A","explanation": "CKD impairs phosphate excretion and vitamin D activation, causing secondary hyperparathyroidism and bone mineral abnormalities affecting physiotherapy management."},{"id": 4145,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Renal calculi (kidney stones) are most commonly composed of:","options": [{"key": "A","text": "Uric acid exclusively"},{"key": "B","text": "Cystine exclusively"},{"key": "C","text": "Struvite exclusively"},{"key": "D","text": "Calcium oxalate"}],"correct": "D","explanation": "Calcium oxalate stones are the most common type of renal calculi, though other compositions occur in specific conditions."},{"id": 4146,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Renal colic, the classic pain of ureteric stone passage, is characteristically described as:","options": [{"key": "A","text": "Painless hematuria only"},{"key": "B","text": "Bilateral symmetric back pain"},{"key": "C","text": "Constant dull ache without radiation"},{"key": "D","text": "Severe, colicky flank pain radiating to the groin"}],"correct": "D","explanation": "Ureteric stones cause intense, wave-like flank-to-groin pain as the stone moves through the ureter causing intermittent obstruction."},{"id": 4147,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Polycystic kidney disease (autosomal dominant form) typically presents with:","options": [{"key": "A","text": "Onset exclusively in infancy with rapid death"},{"key": "B","text": "No effect on kidney function"},{"key": "C","text": "Isolated unilateral cyst without progression"},{"key": "D","text": "Multiple bilateral renal cysts progressing to renal failure in adulthood"}],"correct": "D","explanation": "ADPKD causes progressive bilateral cystic enlargement of the kidneys, typically leading to ESRD in mid-to-late adulthood."},{"id": 4148,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Wilms tumor (nephroblastoma) is a malignant kidney tumor primarily affecting:","options": [{"key": "A","text": "Adolescents primarily"},{"key": "B","text": "Children (typically under 5 years)"},{"key": "C","text": "Neonates exclusively"},{"key": "D","text": "Elderly adults"}],"correct": "B","explanation": "Wilms tumor is the most common pediatric renal malignancy, usually diagnosed before age 5."},{"id": 4149,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Renal cell carcinoma is most strongly associated with which risk factor?","options": [{"key": "A","text": "Viral infection primarily"},{"key": "B","text": "Autoimmune disease"},{"key": "C","text": "Congenital anomaly exclusively"},{"key": "D","text": "Cigarette smoking"}],"correct": "D","explanation": "Smoking is the most significant modifiable risk factor for renal cell carcinoma, along with obesity and hypertension."},{"id": 4150,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Urinary incontinence in elderly or neurologically impaired patients is an important physiotherapy focus area, with stress incontinence resulting from:","options": [{"key": "A","text": "Overactive detrusor contractions only"},{"key": "B","text": "Complete urinary retention"},{"key": "C","text": "Weak pelvic floor muscles allowing leakage with increased abdominal pressure"},{"key": "D","text": "Bladder infection exclusively"}],"correct": "C","explanation": "Stress incontinence results from insufficient pelvic floor/sphincter support, causing leakage during coughing, sneezing, or exertion — directly treatable with physiotherapy (Kegel exercises)."},{"id": 4151,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Pelvic floor muscle training (Kegel exercises) is a first-line physiotherapy intervention for which condition?","options": [{"key": "A","text": "Acute pyelonephritis"},{"key": "B","text": "Renal calculi"},{"key": "C","text": "Stress urinary incontinence"},{"key": "D","text": "Nephrotic syndrome"}],"correct": "C","explanation": "Strengthening pelvic floor muscles improves urethral support and sphincter control, effectively treating stress incontinence."},{"id": 4152,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Urge incontinence results from:","options": [{"key": "A","text": "Overactive detrusor muscle contractions causing sudden urge to void"},{"key": "B","text": "Structural anatomical defect only"},{"key": "C","text": "Weak pelvic floor muscles only"},{"key": "D","text": "Complete bladder outlet obstruction"}],"correct": "A","explanation": "Urge incontinence (overactive bladder) results from involuntary detrusor contractions, distinct from the mechanical cause of stress incontinence."},{"id": 4153,"subject": "Pathology","topic": "Infectious Disease","difficulty": "Medium","question": "Acute pyelonephritis, an infection of the renal parenchyma, most commonly presents with:","options": [{"key": "A","text": "Fever, flank pain, and costovertebral angle tenderness"},{"key": "B","text": "Chronic slowly progressive symptoms only"},{"key": "C","text": "Painless hematuria only"},{"key": "D","text": "Isolated peripheral edema"}],"correct": "A","explanation": "Pyelonephritis causes an acute systemic infection with characteristic fever and flank pain with CVA tenderness on examination."},{"id": 4154,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Rapidly progressive glomerulonephritis (RPGN) is histologically characterized by:","options": [{"key": "A","text": "Foam cell accumulation"},{"key": "B","text": "Crescent formation in glomeruli"},{"key": "C","text": "Nodular sclerosis"},{"key": "D","text": "Minimal change with normal light microscopy"}],"correct": "B","explanation": "RPGN shows characteristic epithelial crescents in Bowman's space, reflecting severe glomerular injury with rapid decline in function."},{"id": 4155,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Goodpasture syndrome involves autoantibodies against which structure, affecting both kidney and lung?","options": [{"key": "A","text": "Podocytes only"},{"key": "B","text": "Glomerular and alveolar basement membrane (anti-GBM antibodies)"},{"key": "C","text": "Renal tubular cells only"},{"key": "D","text": "Mesangial cells only"}],"correct": "B","explanation": "Anti-GBM antibodies target collagen in both glomerular and alveolar basement membranes, causing simultaneous nephritis and pulmonary hemorrhage."},{"id": 4156,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "IgA nephropathy (Berger disease), the most common glomerulonephritis worldwide, classically presents with:","options": [{"key": "A","text": "Nephrotic-range proteinuria exclusively"},{"key": "B","text": "Isolated hypertension without hematuria"},{"key": "C","text": "Painless microscopic hematuria only, never gross"},{"key": "D","text": "Episodic gross hematuria following upper respiratory infection"}],"correct": "D","explanation": "IgA nephropathy classically causes recurrent hematuria closely following URIs, due to IgA immune complex deposition in the mesangium."},{"id": 4157,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Focal segmental glomerulosclerosis (FSGS) is an important cause of nephrotic syndrome, particularly in which population?","options": [{"key": "A","text": "African American adults and patients with HIV/heroin use"},{"key": "B","text": "Only in patients with diabetes"},{"key": "C","text": "Exclusively young children"},{"key": "D","text": "Exclusively elderly women"}],"correct": "A","explanation": "FSGS disproportionately affects African American populations and is linked to HIV nephropathy and other secondary causes, along with idiopathic forms."},{"id": 4158,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Membranous nephropathy, a common cause of nephrotic syndrome in adults, shows which histological feature?","options": [{"key": "A","text": "Isolated mesangial proliferation only"},{"key": "B","text": "Diffuse thickening of the glomerular basement membrane with subepithelial immune deposits"},{"key": "C","text": "Complete absence of immune deposits"},{"key": "D","text": "Crescent formation exclusively"}],"correct": "B","explanation": "Membranous nephropathy shows characteristic 'spike and dome' subepithelial deposits with GBM thickening on electron microscopy."},{"id": 4159,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hydronephrosis refers to:","options": [{"key": "A","text": "Dilation of the renal pelvis and calyces due to obstruction of urine flow"},{"key": "B","text": "Renal artery stenosis"},{"key": "C","text": "Cystic kidney disease"},{"key": "D","text": "Glomerular inflammation"}],"correct": "A","explanation": "Hydronephrosis results from urinary tract obstruction causing back-pressure and dilation of the collecting system."},{"id": 4160,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Benign prostatic hyperplasia (BPH), a common cause of urinary outflow obstruction in older men, primarily affects which zone of the prostate?","options": [{"key": "A","text": "Peripheral zone"},{"key": "B","text": "Anterior fibromuscular zone"},{"key": "C","text": "Central zone exclusively"},{"key": "D","text": "Transitional zone"}],"correct": "D","explanation": "BPH characteristically affects the periurethral transitional zone, causing urinary obstruction symptoms, unlike prostate cancer which favors the peripheral zone."},{"id": 4161,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neurogenic bladder dysfunction is a common complication in patients with which condition, requiring physiotherapy-guided bladder training?","options": [{"key": "A","text": "Uncomplicated stress incontinence only"},{"key": "B","text": "Isolated benign prostatic hyperplasia"},{"key": "C","text": "Simple urinary tract infection"},{"key": "D","text": "Spinal cord injury or multiple sclerosis"}],"correct": "D","explanation": "Neurological conditions disrupting bladder innervation cause various patterns of dysfunction, requiring specialized bladder training and pelvic floor rehabilitation."},{"id": 4162,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Renal artery stenosis is an important cause of secondary hypertension, most commonly due to which underlying pathology in older adults?","options": [{"key": "A","text": "Autoimmune vasculitis exclusively"},{"key": "B","text": "Congenital anomaly only"},{"key": "C","text": "Fibromuscular dysplasia exclusively"},{"key": "D","text": "Atherosclerosis"}],"correct": "D","explanation": "Atherosclerotic renal artery stenosis is the most common cause in older patients, while fibromuscular dysplasia is more typical in younger women."},{"id": 4163,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Amyloidosis affecting the kidney can cause nephrotic syndrome due to:","options": [{"key": "A","text": "Direct bacterial infection of nephrons"},{"key": "B","text": "Deposition of amyloid protein in the glomeruli disrupting filtration"},{"key": "C","text": "Tubular calcification"},{"key": "D","text": "Excess mesangial cell proliferation only"}],"correct": "B","explanation": "Systemic amyloidosis deposits amorphous protein material in glomeruli, impairing the filtration barrier and causing proteinuria."},{"id": 4164,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Type 1 diabetes mellitus results from:","options": [{"key": "A","text": "Pituitary dysfunction"},{"key": "B","text": "Autoimmune destruction of pancreatic beta cells"},{"key": "C","text": "Peripheral insulin resistance primarily"},{"key": "D","text": "Excess glucagon production only"}],"correct": "B","explanation": "Type 1 DM is an autoimmune condition destroying insulin-producing beta cells, leading to absolute insulin deficiency."},{"id": 4165,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Type 2 diabetes mellitus primarily results from:","options": [{"key": "A","text": "Pituitary tumor"},{"key": "B","text": "Complete autoimmune beta cell destruction"},{"key": "C","text": "Adrenal insufficiency"},{"key": "D","text": "Peripheral insulin resistance with relative insulin deficiency"}],"correct": "D","explanation": "Type 2 DM involves insulin resistance in peripheral tissues combined with progressive beta cell dysfunction, unlike the autoimmune Type 1."},{"id": 4166,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Diabetic ketoacidosis is a life-threatening complication most commonly seen in which type of diabetes?","options": [{"key": "A","text": "Type 2 diabetes exclusively"},{"key": "B","text": "Type 1 diabetes"},{"key": "C","text": "Never occurs in diabetes"},{"key": "D","text": "Gestational diabetes only"}],"correct": "B","explanation": "DKA typically occurs in Type 1 diabetics due to absolute insulin deficiency, causing excessive ketone production and metabolic acidosis."},{"id": 4167,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "HbA1c (glycated hemoglobin) reflects average blood glucose control over approximately:","options": [{"key": "A","text": "2-3 months"},{"key": "B","text": "1 year"},{"key": "C","text": "24 hours"},{"key": "D","text": "1 week"}],"correct": "A","explanation": "HbA1c reflects glucose binding to hemoglobin over the RBC lifespan (~120 days), providing an average of 2-3 months of glycemic control."},{"id": 4168,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Diabetic peripheral neuropathy classically causes sensory loss in which distribution, important for physiotherapy foot care?","options": [{"key": "A","text": "Stocking-glove distribution (distal symmetric)"},{"key": "B","text": "Unilateral dermatomal pattern only"},{"key": "C","text": "Proximal limb weakness only"},{"key": "D","text": "Isolated cranial nerve involvement"}],"correct": "A","explanation": "Diabetic neuropathy causes symmetric, length-dependent sensory loss starting distally, increasing risk of unnoticed foot injuries/ulcers."},{"id": 4169,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Diabetic foot ulcers are primarily a consequence of which combination of factors?","options": [{"key": "A","text": "Excess vitamin D only"},{"key": "B","text": "Isolated hyperglycemia without vascular/nerve involvement"},{"key": "C","text": "Peripheral neuropathy and peripheral arterial disease"},{"key": "D","text": "Bone density loss alone"}],"correct": "C","explanation": "Loss of protective sensation combined with impaired blood supply predisposes diabetic patients to unrecognized trauma and poor healing, causing foot ulcers."},{"id": 4170,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Charcot foot (neuropathic arthropathy) in diabetic patients results from:","options": [{"key": "A","text": "Bacterial infection primarily"},{"key": "B","text": "Repeated unrecognized microtrauma due to loss of protective sensation"},{"key": "C","text": "Vascular occlusion alone"},{"key": "D","text": "Autoimmune joint destruction"}],"correct": "B","explanation": "Diabetic sensory neuropathy allows repeated unnoticed trauma, leading to progressive joint destruction and foot deformity requiring specialized physiotherapy/offloading."},{"id": 4171,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Diabetic retinopathy is a leading cause of blindness resulting from:","options": [{"key": "A","text": "Optic nerve tumor"},{"key": "B","text": "Cataract formation exclusively"},{"key": "C","text": "Microvascular damage to retinal blood vessels"},{"key": "D","text": "Corneal scarring"}],"correct": "C","explanation": "Chronic hyperglycemia damages retinal microvasculature, causing progressive retinopathy that can lead to vision loss."},{"id": 4172,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Regular exercise/physiotherapy in Type 2 diabetes management primarily helps by:","options": [{"key": "A","text": "Only benefiting cardiovascular fitness, not glucose control"},{"key": "B","text": "Improving insulin sensitivity and glycemic control"},{"key": "C","text": "Increasing insulin resistance"},{"key": "D","text": "Having no effect on blood glucose"}],"correct": "B","explanation": "Physical activity enhances glucose uptake by muscles and improves insulin sensitivity, a cornerstone of Type 2 diabetes management."},{"id": 4173,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hyperthyroidism (e.g., Graves' disease) classically presents with which clinical features relevant to physiotherapy assessment?","options": [{"key": "A","text": "Heat intolerance, tremor, weight loss, and proximal muscle weakness"},{"key": "B","text": "Cold intolerance and weight gain"},{"key": "C","text": "Bradycardia and lethargy"},{"key": "D","text": "Constipation and dry skin"}],"correct": "A","explanation": "Excess thyroid hormone increases metabolic rate, causing tremor, weight loss, tachycardia, and often proximal myopathy."},{"id": 4174,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Graves' disease, the most common cause of hyperthyroidism, results from:","options": [{"key": "A","text": "Autoimmune destruction of thyroid follicles"},{"key": "B","text": "Autoantibodies (TSI) stimulating the TSH receptor"},{"key": "C","text": "Pituitary adenoma secreting TSH"},{"key": "D","text": "Iodine deficiency"}],"correct": "B","explanation": "Graves' disease involves thyroid-stimulating immunoglobulins that activate TSH receptors, causing diffuse thyroid hyperfunction."},{"id": 4175,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hypothyroidism classically presents with which clinical features?","options": [{"key": "A","text": "Exophthalmos and heat intolerance"},{"key": "B","text": "Cold intolerance, weight gain, fatigue, and delayed reflexes"},{"key": "C","text": "Heat intolerance and weight loss"},{"key": "D","text": "Tremor and tachycardia"}],"correct": "B","explanation": "Decreased thyroid hormone slows metabolism, causing these classic hypometabolic symptoms including delayed relaxation phase of deep tendon reflexes."},{"id": 4176,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hashimoto's thyroiditis, the most common cause of hypothyroidism in iodine-sufficient areas, results from:","options": [{"key": "A","text": "Autoimmune lymphocytic infiltration and destruction of thyroid tissue"},{"key": "B","text": "Iodine excess only"},{"key": "C","text": "Pituitary tumor"},{"key": "D","text": "Viral infection primarily"}],"correct": "A","explanation": "Hashimoto's thyroiditis is an autoimmune condition causing chronic lymphocytic infiltration and progressive thyroid gland destruction."},{"id": 4177,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Myxedema, seen in severe hypothyroidism, refers to:","options": [{"key": "A","text": "Pitting edema from fluid overload"},{"key": "B","text": "Excess sweating"},{"key": "C","text": "Non-pitting edema due to mucopolysaccharide accumulation in skin/tissues"},{"key": "D","text": "Muscle wasting only"}],"correct": "C","explanation": "Severe hypothyroidism causes deposition of glycosaminoglycans in tissues, producing characteristic non-pitting myxedematous swelling."},{"id": 4178,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Thyroid storm is a life-threatening exacerbation of which condition?","options": [{"key": "A","text": "Hypothyroidism"},{"key": "B","text": "Diabetes mellitus"},{"key": "C","text": "Adrenal insufficiency"},{"key": "D","text": "Hyperthyroidism"}],"correct": "D","explanation": "Thyroid storm is a severe, acute exacerbation of thyrotoxicosis, presenting with high fever, tachycardia, and altered mental status."},{"id": 4179,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Myxedema coma is a life-threatening complication of severe:","options": [{"key": "A","text": "Addison's disease"},{"key": "B","text": "Hyperthyroidism"},{"key": "C","text": "Cushing syndrome"},{"key": "D","text": "Hypothyroidism"}],"correct": "D","explanation": "Myxedema coma represents extreme, decompensated hypothyroidism, presenting with hypothermia, altered consciousness, and cardiovascular collapse."},{"id": 4180,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cushing syndrome results from:","options": [{"key": "A","text": "Excess cortisol exposure (endogenous or exogenous)"},{"key": "B","text": "Thyroid hormone excess"},{"key": "C","text": "Excess aldosterone only"},{"key": "D","text": "Cortisol deficiency"}],"correct": "A","explanation": "Cushing syndrome results from chronic glucocorticoid excess, commonly from exogenous steroid use or endogenous overproduction."},{"id": 4181,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cushing syndrome classically causes which musculoskeletal complications relevant to physiotherapy?","options": [{"key": "A","text": "Distal muscle hypertrophy"},{"key": "B","text": "Increased bone density"},{"key": "C","text": "Proximal muscle weakness and osteoporosis"},{"key": "D","text": "No musculoskeletal effects"}],"correct": "C","explanation": "Chronic cortisol excess causes catabolic muscle wasting (especially proximal) and accelerated bone loss, both important physiotherapy considerations."},{"id": 4182,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Addison's disease (primary adrenal insufficiency) results from:","options": [{"key": "A","text": "Excess cortisol production"},{"key": "B","text": "Destruction of the adrenal cortex (often autoimmune), causing deficient cortisol and aldosterone"},{"key": "C","text": "Thyroid gland destruction"},{"key": "D","text": "Pituitary tumor secreting excess ACTH"}],"correct": "B","explanation": "Addison's disease involves adrenal cortex failure, causing combined glucocorticoid and mineralocorticoid deficiency with characteristic hyperpigmentation."},{"id": 4183,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Addisonian crisis, a life-threatening complication of adrenal insufficiency, classically presents with:","options": [{"key": "A","text": "Slow, gradual symptom onset without acute deterioration"},{"key": "B","text": "Excess weight gain only"},{"key": "C","text": "Severe hypertension"},{"key": "D","text": "Severe hypotension, hypoglycemia, and shock"}],"correct": "D","explanation": "Acute adrenal crisis causes cardiovascular collapse due to sudden severe cortisol/mineralocorticoid deficiency, a medical emergency."},{"id": 4184,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Primary hyperparathyroidism, most commonly caused by a parathyroid adenoma, leads to which biochemical abnormality?","options": [{"key": "A","text": "Hypercalcemia with hypophosphatemia"},{"key": "B","text": "Normal calcium with elevated phosphate"},{"key": "C","text": "Hypocalcemia with hyperphosphatemia"},{"key": "D","text": "No effect on calcium/phosphate levels"}],"correct": "A","explanation": "Excess PTH increases bone resorption and renal calcium reabsorption while reducing phosphate reabsorption, causing hypercalcemia with hypophosphatemia."},{"id": 4185,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Hyperparathyroidism can cause which skeletal complication relevant to physiotherapy, characterized by subperiosteal bone resorption?","options": [{"key": "A","text": "Osteitis fibrosa cystica"},{"key": "B","text": "Achondroplasia"},{"key": "C","text": "Paget's disease"},{"key": "D","text": "Osteopetrosis"}],"correct": "A","explanation": "Chronic PTH excess causes excessive osteoclastic resorption, leading to characteristic bone lesions and increased fracture risk."},{"id": 4186,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hypoparathyroidism results in hypocalcemia, classically causing which neuromuscular sign elicited by tapping the facial nerve?","options": [{"key": "A","text": "Gowers' sign"},{"key": "B","text": "Trousseau's sign only"},{"key": "C","text": "Chvostek's sign (facial muscle twitching)"},{"key": "D","text": "Babinski sign"}],"correct": "C","explanation": "Hypocalcemia increases neuromuscular excitability, producing Chvostek's sign (facial twitch) and Trousseau's sign (carpal spasm with BP cuff inflation)."},{"id": 4187,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Acromegaly results from excess secretion of which hormone in adults after growth plate closure?","options": [{"key": "A","text": "Thyroid hormone"},{"key": "B","text": "Insulin"},{"key": "C","text": "Growth hormone"},{"key": "D","text": "Cortisol"}],"correct": "C","explanation": "Excess GH (typically from a pituitary adenoma) in adults causes acromegaly, with enlargement of hands, feet, and facial features."},{"id": 4188,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Gigantism, resulting from excess growth hormone before growth plate closure, causes:","options": [{"key": "A","text": "No effect on height"},{"key": "B","text": "Excessive linear growth in children/adolescents"},{"key": "C","text": "Normal growth with only facial changes"},{"key": "D","text": "Short stature"}],"correct": "B","explanation": "GH excess before epiphyseal closure causes proportional excessive skeletal growth, resulting in gigantism."},{"id": 4189,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which musculoskeletal complication is commonly seen in acromegaly, relevant to physiotherapy assessment?","options": [{"key": "A","text": "Complete joint immobility from birth"},{"key": "B","text": "Osteoarthritis and carpal tunnel syndrome from soft tissue/bone overgrowth"},{"key": "C","text": "Osteoporosis exclusively"},{"key": "D","text": "No musculoskeletal involvement"}],"correct": "B","explanation": "Excess GH causes cartilage and soft tissue overgrowth, predisposing to early degenerative joint disease and nerve entrapment syndromes."},{"id": 4190,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteomalacia due to hypovitaminosis D can result from which endocrine-related mechanism, in addition to dietary deficiency?","options": [{"key": "A","text": "Excess parathyroid hormone alone"},{"key": "B","text": "Excess growth hormone"},{"key": "C","text": "Excess thyroid hormone"},{"key": "D","text": "Chronic kidney disease impairing vitamin D activation"}],"correct": "D","explanation": "The kidneys perform the final hydroxylation step activating vitamin D, so chronic kidney disease impairs this process, contributing to renal osteodystrophy/osteomalacia."},{"id": 4191,"subject": "Pathology","topic": "Neoplasia","difficulty": "Hard","question": "Pheochromocytoma, a tumor of the adrenal medulla, classically causes episodic symptoms due to excess secretion of:","options": [{"key": "A","text": "Catecholamines (epinephrine/norepinephrine)"},{"key": "B","text": "Cortisol"},{"key": "C","text": "Aldosterone"},{"key": "D","text": "Thyroid hormone"}],"correct": "A","explanation": "Pheochromocytoma causes paroxysmal hypertension, palpitations, headache, and sweating due to excessive catecholamine release."},{"id": 4192,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Conn's syndrome (primary hyperaldosteronism) classically causes:","options": [{"key": "A","text": "Hyperglycemia as the primary feature"},{"key": "B","text": "Normal blood pressure with normal potassium"},{"key": "C","text": "Hypotension with hyperkalemia"},{"key": "D","text": "Hypertension with hypokalemia"}],"correct": "D","explanation": "Excess aldosterone increases sodium/water retention (causing hypertension) while promoting potassium excretion (causing hypokalemia)."},{"id": 4193,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hypokalemia from endocrine disorders like Conn's syndrome can cause which muscular symptom relevant to physiotherapy?","options": [{"key": "A","text": "Muscle hypertrophy"},{"key": "B","text": "No muscular effect"},{"key": "C","text": "Muscle weakness and cramps"},{"key": "D","text": "Increased muscle tone/spasticity"}],"correct": "C","explanation": "Low potassium impairs normal muscle membrane excitability, causing weakness, cramping, and in severe cases, paralysis."},{"id": 4194,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Marasmus, a severe form of protein-energy malnutrition, is characterized by:","options": [{"key": "A","text": "Edema with preserved muscle mass"},{"key": "B","text": "Normal growth with isolated vitamin deficiency"},{"key": "C","text": "Excess fat deposition only"},{"key": "D","text": "Severe overall wasting of muscle and fat with no edema"}],"correct": "D","explanation": "Marasmus results from total caloric deficiency, causing generalized wasting without the edema seen in kwashiorkor."},{"id": 4195,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Kwashiorkor, a form of severe malnutrition, is characterized by:","options": [{"key": "A","text": "Edema, hypoalbuminemia, and relatively preserved fat stores despite protein deficiency"},{"key": "B","text": "Total absence of edema"},{"key": "C","text": "Excess protein intake"},{"key": "D","text": "Complete absence of subcutaneous fat"}],"correct": "A","explanation": "Kwashiorkor results from severe protein deficiency despite adequate calories, causing hypoalbuminemia and characteristic edema."},{"id": 4196,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Vitamin A deficiency classically causes which ocular complication?","options": [{"key": "A","text": "Glaucoma"},{"key": "B","text": "Color blindness"},{"key": "C","text": "Night blindness (nyctalopia) and xerophthalmia"},{"key": "D","text": "Cataracts only"}],"correct": "C","explanation": "Vitamin A is essential for rhodopsin synthesis in rod cells; deficiency impairs dark adaptation and can progress to corneal damage."},{"id": 4197,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Vitamin D deficiency in adults causes osteomalacia, while in children it causes:","options": [{"key": "A","text": "Osteoporosis"},{"key": "B","text": "Rickets"},{"key": "C","text": "Osteopetrosis"},{"key": "D","text": "Paget's disease"}],"correct": "B","explanation": "Vitamin D deficiency during the growth period impairs mineralization of growing bone, causing rickets with characteristic skeletal deformities."},{"id": 4198,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Beriberi, resulting from thiamine (Vitamin B1) deficiency, presents in which two main forms?","options": [{"key": "A","text": "Only a skin manifestation"},{"key": "B","text": "Only affects vision"},{"key": "C","text": "Only causes bleeding disorders"},{"key": "D","text": "Wet beriberi (cardiac) and dry beriberi (neurological)"}],"correct": "D","explanation": "Thiamine deficiency causes wet beriberi (high-output cardiac failure) and dry beriberi (peripheral neuropathy), both relevant to physiotherapy assessment."},{"id": 4199,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pellagra, caused by niacin (Vitamin B3) deficiency, is classically characterized by which triad?","options": [{"key": "A","text": "Muscle weakness only"},{"key": "B","text": "Bleeding, bruising, and joint pain"},{"key": "C","text": "Bone pain, fracture, and deformity"},{"key": "D","text": "Dermatitis, diarrhea, and dementia"}],"correct": "D","explanation": "The classic pellagra triad ('3 D's') reflects niacin's essential role in cellular energy metabolism across skin, GI tract, and CNS."},{"id": 4200,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Scurvy, resulting from Vitamin C deficiency, classically presents with:","options": [{"key": "A","text": "Peripheral neuropathy primarily"},{"key": "B","text": "Night blindness"},{"key": "C","text": "Bleeding gums, poor wound healing, and perifollicular hemorrhages"},{"key": "D","text": "Bone deformity from birth"}],"correct": "C","explanation": "Vitamin C deficiency impairs collagen synthesis, causing capillary fragility, gum bleeding, and delayed wound healing."},{"id": 4201,"subject": "Pathology","topic": "Immunology","difficulty": "Hard","question": "Severe combined immunodeficiency (SCID) results in dysfunction of which components of the immune system?","options": [{"key": "A","text": "Complement system only"},{"key": "B","text": "Both B and T lymphocytes"},{"key": "C","text": "B cells only, with normal T cells"},{"key": "D","text": "T cells only, with normal B cells"}],"correct": "B","explanation": "SCID is a group of disorders causing combined failure of both humoral (B cell) and cell-mediated (T cell) immunity, resulting in severe infections."},{"id": 4202,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "DiGeorge syndrome results in immunodeficiency due to:","options": [{"key": "A","text": "Excess complement activity"},{"key": "B","text": "Absent B cells only"},{"key": "C","text": "Thymic hypoplasia causing deficient T cell development"},{"key": "D","text": "Normal immune function with only cardiac defects"}],"correct": "C","explanation": "DiGeorge syndrome (22q11 deletion) causes thymic aplasia/hypoplasia, impairing T cell maturation and causing recurrent infections."},{"id": 4203,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Chronic granulomatous disease results from a defect in which cellular function?","options": [{"key": "A","text": "Neutrophil oxidative burst (NADPH oxidase deficiency)"},{"key": "B","text": "Antibody production"},{"key": "C","text": "T cell receptor signaling"},{"key": "D","text": "Complement activation"}],"correct": "A","explanation": "CGD impairs the neutrophil's ability to generate reactive oxygen species, causing recurrent catalase-positive bacterial and fungal infections."},{"id": 4204,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which of the following best describes the process of cellular aging (senescence)?","options": [{"key": "A","text": "Increased proliferative capacity with age"},{"key": "B","text": "No change in cellular function with age"},{"key": "C","text": "Immediate cell death upon reaching adulthood"},{"key": "D","text": "Progressive decline in cellular replicative capacity and function over time"}],"correct": "D","explanation": "Cellular senescence involves telomere shortening and accumulated damage, gradually reducing regenerative capacity as organisms age."},{"id": 4205,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Telomere shortening with each cell division is thought to contribute to:","options": [{"key": "A","text": "No biological effect"},{"key": "B","text": "Cellular aging and replicative senescence"},{"key": "C","text": "Enhanced tissue regeneration"},{"key": "D","text": "Cancer prevention exclusively"}],"correct": "B","explanation": "Progressive telomere shortening limits the number of times a cell can divide, contributing to the aging process."},{"id": 4206,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Sarcopenia, the age-related loss of muscle mass and strength, is an important physiotherapy concern because it leads to:","options": [{"key": "A","text": "No functional consequence"},{"key": "B","text": "Increased bone density"},{"key": "C","text": "Increased fall risk and functional decline in elderly patients"},{"key": "D","text": "Improved balance and strength"}],"correct": "C","explanation": "Sarcopenia significantly impairs mobility, strength, and balance in older adults, making it a key target for physiotherapy exercise interventions."},{"id": 4207,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Resistance training in elderly patients is an effective physiotherapy intervention primarily to combat:","options": [{"key": "A","text": "Osteopetrosis"},{"key": "B","text": "Acute infections"},{"key": "C","text": "Congenital disorders"},{"key": "D","text": "Sarcopenia and associated functional decline"}],"correct": "D","explanation": "Progressive resistance exercise helps maintain/rebuild muscle mass and strength, directly countering age-related sarcopenia."},{"id": 4208,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Free radical theory of aging proposes that cellular damage accumulates due to:","options": [{"key": "A","text": "Enhanced DNA repair mechanisms"},{"key": "B","text": "Reactive oxygen species causing cumulative oxidative damage to cellular components"},{"key": "C","text": "Excess antioxidant activity"},{"key": "D","text": "Complete absence of metabolic activity"}],"correct": "B","explanation": "This theory suggests that ongoing oxidative stress from metabolic byproducts progressively damages DNA, proteins, and lipids over a lifetime."},{"id": 4209,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Xerostomia (dry mouth), common in aging and certain autoimmune conditions, primarily results from:","options": [{"key": "A","text": "Increased taste bud sensitivity"},{"key": "B","text": "Excess saliva production"},{"key": "C","text": "Reduced salivary gland function/secretion"},{"key": "D","text": "Improved oral hygiene"}],"correct": "C","explanation": "Diminished salivary flow, whether from aging, medications, or conditions like Sjogren syndrome, causes dry mouth and associated complications."},{"id": 4210,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Presbycusis, age-related hearing loss, primarily results from degeneration of:","options": [{"key": "A","text": "Cochlear hair cells"},{"key": "B","text": "External ear canal"},{"key": "C","text": "Tympanic membrane only"},{"key": "D","text": "Middle ear ossicles exclusively"}],"correct": "A","explanation": "Progressive loss of cochlear hair cells with age causes sensorineural hearing loss, typically affecting high frequencies first."},{"id": 4211,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Which of the following best describes hormesis in the context of exercise and aging?","options": [{"key": "A","text": "Exercise has no effect on cellular aging"},{"key": "B","text": "Only extreme exercise provides benefit"},{"key": "C","text": "All physical stress is harmful regardless of dose"},{"key": "D","text": "Low-dose stressors (like moderate exercise) can trigger beneficial adaptive cellular responses"}],"correct": "D","explanation": "Hormesis describes how mild stressors, including regular moderate exercise, can stimulate protective adaptive responses beneficial for healthy aging."},{"id": 4212,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Chronic low-grade inflammation associated with aging is sometimes termed:","options": [{"key": "A","text": "Presbyopia"},{"key": "B","text": "Cachexia"},{"key": "C","text": "Sarcopenia"},{"key": "D","text": "Inflammaging"}],"correct": "D","explanation": "'Inflammaging' describes the persistent, low-level pro-inflammatory state observed in aging that contributes to chronic disease risk."},{"id": 4213,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Apoptosis plays a normal physiological role in which of the following processes?","options": [{"key": "A","text": "Only in pathological disease states"},{"key": "B","text": "Embryonic development and removal of damaged/unwanted cells"},{"key": "C","text": "Exclusively in cancer cells"},{"key": "D","text": "Never occurs under normal conditions"}],"correct": "B","explanation": "Apoptosis is a tightly regulated, physiological process essential for normal development, tissue homeostasis, and immune regulation."},{"id": 4214,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Muscle strains are graded from I to III based on severity; a Grade III strain indicates:","options": [{"key": "A","text": "Mild overstretching without tissue damage"},{"key": "B","text": "Partial tear with some fiber disruption"},{"key": "C","text": "No structural damage at all"},{"key": "D","text": "Complete tear/rupture of the muscle-tendon unit"}],"correct": "D","explanation": "Grade III represents complete disruption, often requiring surgical repair, unlike Grade I (mild) or Grade II (partial tear)."},{"id": 4215,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ligament sprains are graded I to III; a Grade II sprain indicates:","options": [{"key": "A","text": "No ligament damage at all"},{"key": "B","text": "Complete ligament rupture with gross instability"},{"key": "C","text": "Partial tear with some joint laxity but intact ligament continuity"},{"key": "D","text": "Only muscle involvement, not ligament"}],"correct": "C","explanation": "Grade II sprains show partial fiber disruption causing moderate laxity, distinguishing them from mild Grade I and complete Grade III tears."},{"id": 4216,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Bursitis refers to:","options": [{"key": "A","text": "Inflammation of a fluid-filled sac that reduces friction between tissues"},{"key": "B","text": "Bone infection"},{"key": "C","text": "Inflammation of the joint capsule only"},{"key": "D","text": "Tendon calcification"}],"correct": "A","explanation": "Bursae cushion areas of friction between bone, muscle, and tendon; their inflammation (bursitis) causes localized pain and swelling."},{"id": 4217,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Prepatellar bursitis ('housemaid's knee') classically results from:","options": [{"key": "A","text": "Bone fracture"},{"key": "B","text": "Cartilage degeneration only"},{"key": "C","text": "Repetitive kneeling/direct pressure on the front of the knee"},{"key": "D","text": "Ligament tear"}],"correct": "C","explanation": "Repeated kneeling causes friction and inflammation of the prepatellar bursa, common in certain occupations."},{"id": 4218,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Trochanteric bursitis presents with pain over which anatomical region?","options": [{"key": "A","text": "Lateral hip over the greater trochanter"},{"key": "B","text": "Anterior knee"},{"key": "C","text": "Posterior shoulder"},{"key": "D","text": "Medial elbow"}],"correct": "A","explanation": "Trochanteric bursitis causes lateral hip pain, often aggravated by lying on the affected side or prolonged walking."},{"id": 4219,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Achilles tendon rupture classically presents with:","options": [{"key": "A","text": "Gradual painless swelling only"},{"key": "B","text": "Isolated numbness without pain"},{"key": "C","text": "Sudden sharp pain often described as being 'kicked' in the back of the ankle, with a palpable gap"},{"key": "D","text": "No functional limitation"}],"correct": "C","explanation": "Complete Achilles rupture typically occurs during sudden forceful plantarflexion, causing acute pain and a palpable tendon defect."},{"id": 4220,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The Thompson test is used clinically to assess for rupture of which structure?","options": [{"key": "A","text": "Rotator cuff"},{"key": "B","text": "Achilles tendon"},{"key": "C","text": "Meniscus"},{"key": "D","text": "ACL"}],"correct": "B","explanation": "The Thompson test (calf squeeze test) assesses for absent plantarflexion response, indicating Achilles tendon rupture."},{"id": 4221,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Lachman test is a clinical test used to assess integrity of which ligament?","options": [{"key": "A","text": "Medial collateral ligament"},{"key": "B","text": "Lateral collateral ligament"},{"key": "C","text": "Anterior cruciate ligament (ACL)"},{"key": "D","text": "Posterior cruciate ligament"}],"correct": "C","explanation": "The Lachman test assesses anterior tibial translation relative to the femur, a sensitive test for ACL rupture."},{"id": 4222,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Total hip/knee replacement (arthroplasty) is most commonly indicated for which condition?","options": [{"key": "A","text": "Mild early-stage osteoarthritis"},{"key": "B","text": "Severe osteoarthritis with functional limitation and pain refractory to conservative treatment"},{"key": "C","text": "Acute ligament sprain only"},{"key": "D","text": "Simple muscle strain"}],"correct": "B","explanation": "Joint replacement is reserved for advanced degenerative joint disease causing significant pain and disability despite conservative management."},{"id": 4223,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "A common early complication following total hip replacement that physiotherapists must monitor for is:","options": [{"key": "A","text": "Hip dislocation, especially with certain movement combinations"},{"key": "B","text": "Guaranteed permanent stiffness"},{"key": "C","text": "Immediate bone healing without restriction"},{"key": "D","text": "Complete absence of any movement precautions"}],"correct": "A","explanation": "Certain hip flexion/adduction/rotation combinations risk prosthetic dislocation post-surgery, requiring specific movement precautions during early rehabilitation."},{"id": 4224,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Deep vein thrombosis and pulmonary embolism are significant risks following which orthopedic procedure, requiring early mobilization protocols?","options": [{"key": "A","text": "Minor finger fracture"},{"key": "B","text": "Simple ankle sprain treatment"},{"key": "C","text": "Total knee/hip arthroplasty"},{"key": "D","text": "Uncomplicated tendon strain"}],"correct": "C","explanation": "Major joint replacement surgery carries substantial VTE risk, making early physiotherapist-guided mobilization a key preventive strategy."},{"id": 4225,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Spinal stenosis, causing neurogenic claudication, results from:","options": [{"key": "A","text": "Isolated muscle weakness without structural cause"},{"key": "B","text": "Narrowing of the spinal canal compressing neural elements"},{"key": "C","text": "Ligament laxity without bony involvement"},{"key": "D","text": "Widening of the spinal canal"}],"correct": "B","explanation": "Degenerative changes narrow the spinal canal, compressing nerve roots/cauda equina and causing symptoms that worsen with standing/walking."},{"id": 4226,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neurogenic claudication from lumbar spinal stenosis classically improves with which position, distinguishing it from vascular claudication?","options": [{"key": "A","text": "Lying flat on the back"},{"key": "B","text": "Standing upright"},{"key": "C","text": "Flexion (e.g., leaning forward, sitting)"},{"key": "D","text": "No positional relief occurs"}],"correct": "C","explanation": "Flexing the spine increases canal diameter, relieving neurogenic claudication symptoms, unlike vascular claudication which improves simply with rest regardless of position."},{"id": 4227,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Whiplash injury, commonly from rear-end vehicle collisions, primarily affects which region?","options": [{"key": "A","text": "Peripheral joints only"},{"key": "B","text": "Thoracic spine exclusively"},{"key": "C","text": "Cervical spine soft tissues (muscles, ligaments)"},{"key": "D","text": "Lumbar spine exclusively"}],"correct": "C","explanation": "Whiplash results from rapid acceleration-deceleration forces causing cervical soft tissue strain/sprain, a common physiotherapy referral."},{"id": 4228,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Piriformis syndrome causes sciatica-like symptoms due to:","options": [{"key": "A","text": "Compression of the sciatic nerve by the piriformis muscle"},{"key": "B","text": "Bone fracture"},{"key": "C","text": "Direct nerve tumor"},{"key": "D","text": "Disc herniation exclusively"}],"correct": "A","explanation": "The piriformis muscle can compress or irritate the underlying sciatic nerve, mimicking lumbar radiculopathy symptoms."},{"id": 4229,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Iliotibial band syndrome, common in runners, causes pain primarily at:","options": [{"key": "A","text": "Medial aspect of the knee"},{"key": "B","text": "Anterior aspect of the knee only"},{"key": "C","text": "Posterior aspect of the ankle"},{"key": "D","text": "Lateral aspect of the knee"}],"correct": "D","explanation": "Repetitive friction of the IT band over the lateral femoral epicondyle causes characteristic lateral knee pain in runners/cyclists."},{"id": 4230,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Patellofemoral pain syndrome ('runner's knee') is characterized by:","options": [{"key": "A","text": "Lateral ankle instability"},{"key": "B","text": "Posterior knee pain only"},{"key": "C","text": "Isolated hip pain"},{"key": "D","text": "Anterior knee pain aggravated by activities like squatting, stair climbing"}],"correct": "D","explanation": "PFPS results from abnormal patellar tracking/loading, causing pain around or behind the kneecap during loaded knee flexion activities."},{"id": 4231,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Shin splints (medial tibial stress syndrome) classically present with pain along:","options": [{"key": "A","text": "The posteromedial border of the tibia"},{"key": "B","text": "The Achilles tendon"},{"key": "C","text": "The lateral malleolus"},{"key": "D","text": "The patellar tendon"}],"correct": "A","explanation": "Repetitive stress on the tibia and surrounding musculature/periosteum causes characteristic medial tibial pain, common in runners."},{"id": 4232,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osgood-Schlatter disease, common in adolescent athletes, causes pain and swelling at:","options": [{"key": "A","text": "The tibial tuberosity"},{"key": "B","text": "The medial malleolus"},{"key": "C","text": "The greater trochanter"},{"key": "D","text": "The patella itself"}],"correct": "A","explanation": "Repetitive quadriceps traction on the immature tibial tuberosity apophysis causes this common adolescent overuse condition."},{"id": 4233,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Sever's disease, an apophysitis common in active children, affects which structure?","options": [{"key": "A","text": "Patella"},{"key": "B","text": "Iliac crest"},{"key": "C","text": "Tibial tuberosity"},{"key": "D","text": "Calcaneal apophysis (heel)"}],"correct": "D","explanation": "Sever's disease is a traction apophysitis at the calcaneal growth plate from repetitive Achilles tendon pull, common in young athletes."},{"id": 4234,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which of the following describes the RICE protocol commonly used in acute soft tissue injury management?","options": [{"key": "A","text": "Range of motion, Ice, Compression, Extension"},{"key": "B","text": "Rest, Immobilization, Compression, Exercise"},{"key": "C","text": "Rest, Ice, Compression, Elevation"},{"key": "D","text": "Rest, Ice, Circulation, Elevation"}],"correct": "C","explanation": "RICE is a foundational first-aid approach for acute musculoskeletal injuries to minimize swelling and promote early healing."},{"id": 4235,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Restless leg syndrome is characterized by:","options": [{"key": "A","text": "Improvement of symptoms with inactivity"},{"key": "B","text": "An uncomfortable urge to move the legs, typically worse at rest and evening/night"},{"key": "C","text": "Constant leg pain unrelated to rest"},{"key": "D","text": "Symptoms exclusively during physical activity"}],"correct": "B","explanation": "RLS causes an irresistible urge to move the legs, classically worsening with rest and improving temporarily with movement."},{"id": 4236,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Trigeminal neuralgia causes severe, brief episodes of facial pain typically triggered by:","options": [{"key": "A","text": "Rest without any stimulus"},{"key": "B","text": "Cold weather exclusively"},{"key": "C","text": "Light touch or stimulation of the face (e.g., chewing, brushing teeth)"},{"key": "D","text": "Deep pressure only"}],"correct": "C","explanation": "Trigeminal neuralgia produces sudden, electric shock-like facial pain often triggered by minor sensory stimuli in the nerve's distribution."},{"id": 4237,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Complex regional pain syndrome (CRPS) commonly develops after which type of event, requiring careful physiotherapy management?","options": [{"key": "A","text": "Only in patients over 80 years old"},{"key": "B","text": "Only spontaneous, unrelated to any injury"},{"key": "C","text": "Exclusively from genetic causes"},{"key": "D","text": "Limb trauma or surgery, often disproportionate to the initial injury"}],"correct": "D","explanation": "CRPS is a chronic pain condition, often following trauma/surgery, with pain disproportionate to the initial injury plus autonomic/trophic changes."},{"id": 4238,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Which of the following autonomic/trophic changes may be seen in complex regional pain syndrome?","options": [{"key": "A","text": "Skin color/temperature changes, swelling, and abnormal sweating in the affected limb"},{"key": "B","text": "Isolated hair growth increase without other changes"},{"key": "C","text": "Complete absence of any skin changes"},{"key": "D","text": "Only muscle hypertrophy"}],"correct": "A","explanation": "CRPS involves autonomic dysregulation causing vasomotor, sudomotor, and trophic skin/nail/hair changes in the affected limb."},{"id": 4239,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Vestibular neuritis, causing acute vertigo, results from:","options": [{"key": "A","text": "Inflammation of the vestibular nerve, often viral in origin"},{"key": "B","text": "Cervical spine dysfunction exclusively"},{"key": "C","text": "Bacterial infection of the inner ear ossicles"},{"key": "D","text": "Central brainstem lesion primarily"}],"correct": "A","explanation": "Vestibular neuritis causes sudden severe vertigo due to presumed viral inflammation of the vestibular portion of CN VIII."},{"id": 4240,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Benign paroxysmal positional vertigo (BPPV) results from:","options": [{"key": "A","text": "Cervical muscle spasm only"},{"key": "B","text": "Central brainstem stroke"},{"key": "C","text": "Vestibular nerve inflammation"},{"key": "D","text": "Displaced otoconia (calcium crystals) in the semicircular canals"}],"correct": "D","explanation": "BPPV occurs when otoliths dislodge into the semicircular canals, causing brief vertigo with specific head position changes, treatable with canalith repositioning (Epley maneuver)."},{"id": 4241,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The Epley maneuver, a physiotherapy technique, is used to treat which condition?","options": [{"key": "A","text": "Vestibular neuritis"},{"key": "B","text": "Meniere's disease"},{"key": "C","text": "Migraine-associated vertigo"},{"key": "D","text": "Benign paroxysmal positional vertigo (BPPV)"}],"correct": "D","explanation": "The Epley maneuver repositions displaced otoconia out of the semicircular canal, effectively treating posterior canal BPPV."},{"id": 4242,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Meniere's disease is characterized by the triad of:","options": [{"key": "A","text": "Headache, photophobia, and nausea only"},{"key": "B","text": "Vertigo, tinnitus, and fluctuating hearing loss"},{"key": "C","text": "Facial weakness and hearing loss without vertigo"},{"key": "D","text": "Ataxia and dysarthria only"}],"correct": "B","explanation": "Meniere's disease results from endolymphatic hydrops, causing this characteristic episodic triad affecting the inner ear."},{"id": 4243,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Dysarthria refers to:","options": [{"key": "A","text": "Difficulty understanding language"},{"key": "B","text": "Difficulty swallowing exclusively"},{"key": "C","text": "Complete loss of voice"},{"key": "D","text": "Difficulty with articulation of speech due to muscular/neurological impairment"}],"correct": "D","explanation": "Dysarthria results from impaired motor control of speech muscles, distinct from aphasia which involves language comprehension/production."},{"id": 4244,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Aphasia refers to:","options": [{"key": "A","text": "Loss of swallowing function"},{"key": "B","text": "Difficulty with muscle coordination for speech articulation"},{"key": "C","text": "Impairment of language comprehension and/or production due to brain damage"},{"key": "D","text": "Loss of hearing"}],"correct": "C","explanation": "Aphasia results from damage to language centers (e.g., Broca's or Wernicke's areas), affecting the ability to understand or produce language."},{"id": 4245,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Broca's aphasia is characterized by:","options": [{"key": "A","text": "Fluent speech with impaired comprehension"},{"key": "B","text": "Non-fluent, effortful speech with relatively preserved comprehension"},{"key": "C","text": "Complete inability to produce any sound"},{"key": "D","text": "Normal speech and comprehension"}],"correct": "B","explanation": "Broca's (expressive) aphasia results from damage to the frontal language area, causing labored, non-fluent speech despite understanding language."},{"id": 4246,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Wernicke's aphasia is characterized by:","options": [{"key": "A","text": "Normal language function"},{"key": "B","text": "Non-fluent, effortful speech with good comprehension"},{"key": "C","text": "Complete muteness"},{"key": "D","text": "Fluent but nonsensical speech with impaired comprehension"}],"correct": "D","explanation": "Wernicke's (receptive) aphasia results from temporal lobe damage, causing fluent but meaningless speech and poor comprehension."},{"id": 4247,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Dysphagia, difficulty swallowing, is a common complication after stroke, requiring physiotherapy/speech therapy collaboration primarily to prevent:","options": [{"key": "A","text": "Aspiration pneumonia"},{"key": "B","text": "Bone density loss"},{"key": "C","text": "Muscle atrophy exclusively"},{"key": "D","text": "Joint contracture"}],"correct": "A","explanation": "Impaired swallowing increases risk of food/liquid entering the airway, so dysphagia management focuses on preventing aspiration pneumonia."},{"id": 4248,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Apraxia refers to:","options": [{"key": "A","text": "Inability to perform learned, purposeful movements despite intact motor and sensory function"},{"key": "B","text": "Weakness of a specific muscle group"},{"key": "C","text": "Loss of sensation only"},{"key": "D","text": "Complete paralysis"}],"correct": "A","explanation": "Apraxia reflects a higher-order motor planning deficit, where the patient cannot execute purposeful movements despite having the physical capacity to do so."},{"id": 4249,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Neglect syndrome, commonly seen after right parietal lobe stroke, causes patients to:","options": [{"key": "A","text": "Ignore or fail to attend to stimuli on the left side of space/body"},{"key": "B","text": "Show no cognitive impairment at all"},{"key": "C","text": "Have isolated hearing loss"},{"key": "D","text": "Have complete paralysis of both sides equally"}],"correct": "A","explanation": "Hemispatial neglect results from non-dominant (usually right) parietal damage, causing inattention to the contralateral side, significantly impacting rehabilitation approach."},{"id": 4250,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Homonymous hemianopia refers to:","options": [{"key": "A","text": "Complete blindness in one eye only"},{"key": "B","text": "Loss of peripheral vision in both eyes symmetrically"},{"key": "C","text": "Loss of central vision only"},{"key": "D","text": "Loss of the same half of the visual field in both eyes"}],"correct": "D","explanation": "Homonymous hemianopia results from damage posterior to the optic chiasm (e.g., PCA stroke), causing loss of the same visual field in both eyes."},{"id": 4251,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which balance assessment consideration is important for stroke patients with hemianopia during physiotherapy gait training?","options": [{"key": "A","text": "Only affects reading ability, not mobility"},{"key": "B","text": "No impact on balance or gait safety"},{"key": "C","text": "Increased fall risk due to unrecognized obstacles in the affected visual field"},{"key": "D","text": "Improved spatial awareness compared to normal vision"}],"correct": "C","explanation": "Visual field loss significantly increases fall risk during ambulation, requiring specific safety strategies and environmental awareness training in rehab."},{"id": 4252,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Delirium, an acute confusional state sometimes seen in hospitalized elderly patients, is characterized by:","options": [{"key": "A","text": "Normal attention with isolated memory loss"},{"key": "B","text": "Acute onset, fluctuating course, and impaired attention"},{"key": "C","text": "Chronic, gradual progressive decline"},{"key": "D","text": "Permanent, irreversible cognitive change always"}],"correct": "B","explanation": "Delirium is distinguished from dementia by its acute onset and fluctuating course, often reversible once the underlying cause is treated."},{"id": 4253,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Atrial fibrillation is characterized on ECG by:","options": [{"key": "A","text": "Fixed PR interval prolongation only"},{"key": "B","text": "Complete heart block pattern"},{"key": "C","text": "Irregularly irregular rhythm with absent P waves"},{"key": "D","text": "Regular rhythm with normal P waves"}],"correct": "C","explanation": "AF results from chaotic atrial electrical activity, producing an irregularly irregular ventricular rhythm without discrete P waves."},{"id": 4254,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Atrial fibrillation significantly increases the risk of which complication relevant to physiotherapy screening?","options": [{"key": "A","text": "Stroke due to embolism from atrial thrombus formation"},{"key": "B","text": "No increased health risks"},{"key": "C","text": "Decreased clotting risk"},{"key": "D","text": "Improved cardiac output always"}],"correct": "A","explanation": "Stasis of blood in the fibrillating atria (especially the left atrial appendage) predisposes to thrombus formation and embolic stroke."},{"id": 4255,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "First-degree AV block on ECG is characterized by:","options": [{"key": "A","text": "Progressive PR prolongation until a dropped beat"},{"key": "B","text": "Random dropped QRS complexes without pattern"},{"key": "C","text": "Complete dissociation of P waves and QRS complexes"},{"key": "D","text": "Prolonged PR interval (>200ms) with all beats conducted"}],"correct": "D","explanation": "First-degree block shows delayed but complete conduction through the AV node, without any dropped beats."},{"id": 4256,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Third-degree (complete) heart block is characterized by:","options": [{"key": "A","text": "Normal 1:1 conduction with prolonged PR interval"},{"key": "B","text": "Occasional dropped beats only"},{"key": "C","text": "Complete dissociation between atrial and ventricular activity"},{"key": "D","text": "Fast, regular narrow complex rhythm"}],"correct": "C","explanation": "In complete heart block, atrial and ventricular contractions occur independently since no impulses conduct through the AV node."},{"id": 4257,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Bradycardia during exercise-based physiotherapy sessions should prompt which immediate action?","options": [{"key": "A","text": "Immediately begin CPR without assessment"},{"key": "B","text": "Ignore it if the patient reports no symptoms"},{"key": "C","text": "Stop the activity and assess the patient's symptoms/vital signs"},{"key": "D","text": "Continue increasing exercise intensity"}],"correct": "C","explanation": "Unexpected bradycardia during exertion requires immediate cessation of activity and clinical assessment to rule out significant cardiac compromise."},{"id": 4258,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Exercise stress testing is used clinically to primarily assess:","options": [{"key": "A","text": "Baseline resting heart function only"},{"key": "B","text": "The heart's response to increasing physical demand, useful for detecting ischemia"},{"key": "C","text": "Kidney function"},{"key": "D","text": "Pulmonary function exclusively"}],"correct": "B","explanation": "Stress testing evaluates cardiovascular response and can reveal exercise-induced ischemia not apparent at rest."},{"id": 4259,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Target heart rate for aerobic exercise prescription is commonly calculated using which formula-based method?","options": [{"key": "A","text": "Respiratory rate alone"},{"key": "B","text": "Blood pressure alone"},{"key": "C","text": "Random guess without calculation"},{"key": "D","text": "Karvonen formula (heart rate reserve method)"}],"correct": "D","explanation": "The Karvonen formula incorporates resting and maximum heart rate to calculate an appropriate target heart rate range for exercise prescription."},{"id": 4260,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Contraindications to starting an exercise program in cardiac patients include:","options": [{"key": "A","text": "Unstable angina or recent decompensated heart failure"},{"key": "B","text": "Age alone regardless of cardiac status"},{"key": "C","text": "Stable, well-controlled hypertension"},{"key": "D","text": "Mild, well-managed diabetes"}],"correct": "A","explanation": "Unstable cardiac conditions require medical stabilization before initiating exercise-based rehabilitation to avoid triggering acute events."},{"id": 4261,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The Borg Rating of Perceived Exertion (RPE) scale is used in cardiac/pulmonary rehabilitation to:","options": [{"key": "A","text": "Measure objective oxygen saturation"},{"key": "B","text": "Replace heart rate monitoring entirely"},{"key": "C","text": "Subjectively gauge exercise intensity based on patient perception of effort"},{"key": "D","text": "Assess cognitive function"}],"correct": "C","explanation": "The Borg scale provides a practical, subjective measure of exertion that correlates well with physiological exercise intensity, useful when heart rate response is altered by medications (e.g., beta-blockers)."},{"id": 4262,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Beta-blocker medications, commonly prescribed for cardiac patients, can affect physiotherapy exercise assessment by:","options": [{"key": "A","text": "Blunting the normal heart rate response to exercise"},{"key": "B","text": "Increasing maximum exercise heart rate significantly"},{"key": "C","text": "Causing exaggerated tachycardia during exercise"},{"key": "D","text": "Having no effect on cardiovascular parameters"}],"correct": "A","explanation": "Beta-blockers reduce heart rate response, making RPE scales more reliable than target heart rate zones for monitoring exercise intensity in these patients."},{"id": 4263,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Claudication distance, an important outcome measure in peripheral arterial disease rehabilitation, refers to:","options": [{"key": "A","text": "The distance a patient can walk before onset of ischemic leg pain"},{"key": "B","text": "A measure unrelated to exercise tolerance"},{"key": "C","text": "Total distance walked regardless of pain"},{"key": "D","text": "Distance walked only on a treadmill"}],"correct": "A","explanation": "Tracking claudication distance helps quantify functional limitation and monitor improvement with supervised exercise therapy in PAD."},{"id": 4264,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Supervised exercise therapy is considered first-line treatment for which vascular condition, aiming to improve collateral circulation?","options": [{"key": "A","text": "Intermittent claudication (peripheral arterial disease)"},{"key": "B","text": "Aortic dissection"},{"key": "C","text": "Acute deep vein thrombosis"},{"key": "D","text": "Acute arterial occlusion requiring emergency surgery"}],"correct": "A","explanation": "Structured walking programs stimulate collateral vessel development and improve walking distance in patients with claudication from PAD."},{"id": 4265,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Aortic dissection classically presents with:","options": [{"key": "A","text": "Sudden severe tearing chest/back pain"},{"key": "B","text": "Painless presentation with incidental findings only"},{"key": "C","text": "Gradual, mild chest discomfort over weeks"},{"key": "D","text": "Isolated peripheral edema without pain"}],"correct": "A","explanation": "Aortic dissection causes an abrupt, severe tearing pain, often radiating to the back, representing a surgical emergency."},{"id": 4266,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Abdominal aortic aneurysm is most strongly associated with which risk factors?","options": [{"key": "A","text": "Smoking, atherosclerosis, and advanced age"},{"key": "B","text": "Young age and female gender primarily"},{"key": "C","text": "Viral infection primarily"},{"key": "D","text": "Absence of cardiovascular risk factors"}],"correct": "A","explanation": "AAA develops from progressive weakening of the aortic wall, strongly linked to smoking, atherosclerosis, and increasing age, especially in men."},{"id": 4267,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Which vital sign monitoring parameter is essential before, during, and after physiotherapy sessions for patients with known cardiovascular disease?","options": [{"key": "A","text": "Only respiratory rate without heart rate"},{"key": "B","text": "No monitoring required if asymptomatic"},{"key": "C","text": "Heart rate and blood pressure"},{"key": "D","text": "Only body temperature"}],"correct": "C","explanation": "Regular vital sign monitoring allows physiotherapists to detect abnormal cardiovascular responses and adjust exercise intensity safely."},{"id": 4268,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Apoptosis is executed primarily through activation of which enzyme family?","options": [{"key": "A","text": "Phosphatases"},{"key": "B","text": "Lipases"},{"key": "C","text": "Kinases"},{"key": "D","text": "Caspases"}],"correct": "D","explanation": "Caspases are cysteine-aspartic proteases that execute the apoptotic program by cleaving key cellular substrates."},{"id": 4269,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Hard","question": "The extrinsic pathway of apoptosis is triggered by binding of which type of receptor?","options": [{"key": "A","text": "Death receptors (e.g., Fas, TNF receptor)"},{"key": "B","text": "Toll-like receptors"},{"key": "C","text": "G-protein coupled receptors"},{"key": "D","text": "Growth factor receptors"}],"correct": "A","explanation": "Extrinsic apoptosis is initiated by ligand binding to death receptors on the cell surface, activating caspase-8."},{"id": 4270,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Easy","question": "Which necrosis type is characteristic of ischemic injury to the brain?","options": [{"key": "A","text": "Coagulative necrosis"},{"key": "B","text": "Caseous necrosis"},{"key": "C","text": "Liquefactive necrosis"},{"key": "D","text": "Fat necrosis"}],"correct": "C","explanation": "Brain tissue, being lipid-rich with abundant hydrolytic enzymes, undergoes liquefactive necrosis following ischemic injury."},{"id": 4271,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Metaplasia involving replacement of ciliated columnar epithelium with squamous epithelium is termed:","options": [{"key": "A","text": "Myeloid metaplasia"},{"key": "B","text": "Columnar metaplasia"},{"key": "C","text": "Osseous metaplasia"},{"key": "D","text": "Squamous metaplasia"}],"correct": "D","explanation": "Chronic irritation converts fragile columnar epithelium into more durable but less protective squamous epithelium."},{"id": 4272,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Free radicals cause cellular injury primarily through which mechanism affecting cell membranes?","options": [{"key": "A","text": "Increased ATP production"},{"key": "B","text": "DNA repair stimulation"},{"key": "C","text": "Protein synthesis enhancement"},{"key": "D","text": "Lipid peroxidation"}],"correct": "D","explanation": "Reactive oxygen species attack polyunsaturated lipids in membranes, causing peroxidation and structural damage."},{"id": 4273,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Cellular adaptation in which cell number increases is termed:","options": [{"key": "A","text": "Metaplasia"},{"key": "B","text": "Atrophy"},{"key": "C","text": "Hyperplasia"},{"key": "D","text": "Hypertrophy"}],"correct": "C","explanation": "Hyperplasia refers to an increase in the number of cells in an organ or tissue, distinct from hypertrophy (increased cell size)."},{"id": 4274,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which of the following best describes dystrophic calcification?","options": [{"key": "A","text": "Calcium deposition in normal tissue with elevated serum calcium"},{"key": "B","text": "Calcium deposition in dying/dead tissue with normal serum calcium"},{"key": "C","text": "A condition unrelated to tissue injury"},{"key": "D","text": "Calcium deposition exclusively in bone"}],"correct": "B","explanation": "Dystrophic calcification occurs locally in damaged tissue regardless of systemic calcium levels, as seen in atherosclerotic plaques or old infarcts."},{"id": 4275,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which cytokine is a major mediator of fever, acting on the hypothalamus during inflammation?","options": [{"key": "A","text": "IL-10"},{"key": "B","text": "IL-1"},{"key": "C","text": "TGF-beta"},{"key": "D","text": "IL-4"}],"correct": "B","explanation": "IL-1, along with TNF-alpha and IL-6, induces prostaglandin E2 production in the hypothalamus, resetting the thermoregulatory set point."},{"id": 4276,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Which type of collagen predominates in mature, remodeled scar tissue?","options": [{"key": "A","text": "Type I"},{"key": "B","text": "Type II"},{"key": "C","text": "Type IV"},{"key": "D","text": "Type III"}],"correct": "A","explanation": "During remodeling, weaker Type III collagen is progressively replaced by stronger, more organized Type I collagen."},{"id": 4277,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chemotaxis of leukocytes toward the site of injury is guided primarily by which class of molecules?","options": [{"key": "A","text": "Hormones like insulin"},{"key": "B","text": "Neurotransmitters"},{"key": "C","text": "Chemokines and complement fragments (e.g., C5a)"},{"key": "D","text": "Structural proteins like collagen"}],"correct": "C","explanation": "Chemotactic factors including chemokines and C5a create a gradient guiding leukocyte migration to the injury site."},{"id": 4278,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Selectins mediate which initial step of leukocyte extravasation?","options": [{"key": "A","text": "Chemotaxis within tissue"},{"key": "B","text": "Transmigration through the vessel wall"},{"key": "C","text": "Rolling along the endothelium"},{"key": "D","text": "Firm adhesion"}],"correct": "C","explanation": "Selectins mediate the initial, weak, reversible rolling interaction between leukocytes and activated endothelium."},{"id": 4279,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Granulation tissue is characterized by proliferation of which two main cell types?","options": [{"key": "A","text": "Fibroblasts and new capillaries (angiogenesis)"},{"key": "B","text": "Neutrophils and eosinophils"},{"key": "C","text": "Hepatocytes and Kupffer cells"},{"key": "D","text": "Osteoblasts and osteoclasts"}],"correct": "A","explanation": "Granulation tissue consists of proliferating fibroblasts and new capillary sprouts, giving it a characteristic granular, pink appearance."},{"id": 4280,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Keloid scars differ from hypertrophic scars primarily by:","options": [{"key": "A","text": "Never containing excess collagen"},{"key": "B","text": "Extending beyond the original wound margins"},{"key": "C","text": "Occurring only in children"},{"key": "D","text": "Remaining confined within the original wound margins"}],"correct": "B","explanation": "Keloids grow beyond the boundaries of the original injury, unlike hypertrophic scars which stay within the wound margins."},{"id": 4281,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Virchow's triad component describing abnormal blood flow includes both stasis and:","options": [{"key": "A","text": "Turbulence"},{"key": "B","text": "Decreased platelet count"},{"key": "C","text": "Increased fibrinolysis"},{"key": "D","text": "Increased viscosity only"}],"correct": "A","explanation": "Both stasis and turbulence represent abnormal blood flow patterns predisposing to thrombosis within Virchow's triad."},{"id": 4282,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "An embolus that originates from deep leg veins and travels to the lungs is termed a:","options": [{"key": "A","text": "Fat embolus"},{"key": "B","text": "Systemic embolus"},{"key": "C","text": "Pulmonary embolus"},{"key": "D","text": "Paradoxical embolus"}],"correct": "C","explanation": "Venous emboli from the legs travel through the right heart to lodge in the pulmonary arterial circulation, causing pulmonary embolism."},{"id": 4283,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "A paradoxical embolus refers to an embolus that:","options": [{"key": "A","text": "Always originates in the lungs"},{"key": "B","text": "Passes from venous to arterial circulation through a cardiac defect (e.g., PFO)"},{"key": "C","text": "Never causes any clinical symptoms"},{"key": "D","text": "Is composed exclusively of air"}],"correct": "B","explanation": "Paradoxical embolism occurs when a venous embolus crosses a septal defect (e.g., patent foramen ovale) to enter systemic arterial circulation."},{"id": 4284,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Grading of malignant tumors is based primarily on:","options": [{"key": "A","text": "Patient age at diagnosis"},{"key": "B","text": "Degree of cellular differentiation"},{"key": "C","text": "Tumor color"},{"key": "D","text": "Anatomical extent of spread"}],"correct": "B","explanation": "Tumor grade reflects how closely tumor cells resemble their tissue of origin, an indicator of aggressiveness."},{"id": 4285,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "The TNM staging system evaluates tumor extent based on:","options": [{"key": "A","text": "Tumor type, Number of mitoses, and Margin status"},{"key": "B","text": "Tumor size, lymph Node involvement, and Metastasis"},{"key": "C","text": "Tumor grade, Nuclear atypia, and Mitotic rate"},{"key": "D","text": "Tissue origin, Necrosis, and Mutation status"}],"correct": "B","explanation": "TNM staging is a widely used system describing primary tumor size (T), regional lymph node involvement (N), and distant metastasis (M)."},{"id": 4286,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Cancer cachexia is mediated significantly by which cytokine, contributing to profound wasting?","options": [{"key": "A","text": "TNF-alpha"},{"key": "B","text": "IL-10"},{"key": "C","text": "TGF-beta"},{"key": "D","text": "IL-4"}],"correct": "A","explanation": "TNF-alpha (originally called cachectin) plays a central role in mediating the metabolic changes underlying cancer cachexia."},{"id": 4287,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Osteoclast-mediated bone resorption in osteoporosis is primarily driven by which signaling pathway?","options": [{"key": "A","text": "Wnt signaling exclusively"},{"key": "B","text": "RANK-RANKL-OPG axis"},{"key": "C","text": "Notch signaling"},{"key": "D","text": "Hedgehog signaling"}],"correct": "B","explanation": "The RANKL-RANK interaction on osteoclast precursors drives their differentiation and activity, with osteoprotegerin (OPG) acting as a decoy receptor to inhibit this process."},{"id": 4288,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Rheumatoid arthritis is associated with which autoantibody in addition to rheumatoid factor, offering higher specificity?","options": [{"key": "A","text": "Anti-dsDNA antibody"},{"key": "B","text": "Anti-Smith antibody"},{"key": "C","text": "Anti-cyclic citrullinated peptide (anti-CCP) antibody"},{"key": "D","text": "Anti-centromere antibody"}],"correct": "C","explanation": "Anti-CCP antibodies are more specific than rheumatoid factor for diagnosing rheumatoid arthritis and can predict more erosive disease."},{"id": 4289,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Gouty tophi are composed of deposits of:","options": [{"key": "A","text": "Monosodium urate crystals surrounded by inflammatory reaction"},{"key": "B","text": "Amyloid protein"},{"key": "C","text": "Cholesterol crystals"},{"key": "D","text": "Calcium pyrophosphate crystals"}],"correct": "A","explanation": "Tophi are chronic deposits of urate crystals surrounded by a granulomatous inflammatory reaction, typically in soft tissue and joints."},{"id": 4290,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Multiple sclerosis lesions primarily involve demyelination of which type of fibers?","options": [{"key": "A","text": "Both CNS and peripheral fibers equally"},{"key": "B","text": "CNS white matter fibers (oligodendrocyte-myelinated)"},{"key": "C","text": "Peripheral nerve fibers (Schwann cell-myelinated)"},{"key": "D","text": "Unmyelinated C fibers exclusively"}],"correct": "B","explanation": "MS is a CNS demyelinating disease targeting oligodendrocyte-produced myelin, distinct from peripheral neuropathies affecting Schwann cell myelin."},{"id": 4291,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The primary neurotransmitter deficient in Parkinson's disease is:","options": [{"key": "A","text": "Serotonin"},{"key": "B","text": "Acetylcholine"},{"key": "C","text": "GABA"},{"key": "D","text": "Dopamine"}],"correct": "D","explanation": "Loss of dopaminergic neurons in the substantia nigra leads to striatal dopamine deficiency, the core pathophysiology of Parkinson's disease."},{"id": 4292,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Alzheimer's disease neurofibrillary tangles are composed of abnormally phosphorylated:","options": [{"key": "A","text": "Amyloid-beta protein"},{"key": "B","text": "Prion protein"},{"key": "C","text": "Tau protein"},{"key": "D","text": "Alpha-synuclein"}],"correct": "C","explanation": "Hyperphosphorylated tau protein aggregates intracellularly to form the neurofibrillary tangles characteristic of Alzheimer's disease."},{"id": 4293,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Amyotrophic lateral sclerosis (ALS) selectively affects which type of neurons?","options": [{"key": "A","text": "Interneurons exclusively"},{"key": "B","text": "Autonomic neurons exclusively"},{"key": "C","text": "Both upper and lower motor neurons"},{"key": "D","text": "Sensory neurons exclusively"}],"correct": "C","explanation": "ALS is characterized by progressive degeneration of upper motor neurons in the cortex and lower motor neurons in the brainstem/spinal cord, sparing sensory pathways."},{"id": 4294,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The most reliable and specific biomarker for diagnosing acute myocardial infarction is:","options": [{"key": "A","text": "LDH"},{"key": "B","text": "AST"},{"key": "C","text": "Cardiac troponin"},{"key": "D","text": "Total CK"}],"correct": "C","explanation": "Cardiac troponin (I or T) is highly specific to myocardial injury and remains the gold standard biomarker for diagnosing MI."},{"id": 4295,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Left ventricular hypertrophy develops as a compensatory response to chronically increased:","options": [{"key": "A","text": "Heart rate only"},{"key": "B","text": "Blood volume alone without pressure change"},{"key": "C","text": "Preload only"},{"key": "D","text": "Afterload (e.g., from hypertension or aortic stenosis)"}],"correct": "D","explanation": "Sustained pressure overload (increased afterload) stimulates concentric LV hypertrophy as a compensatory mechanism."},{"id": 4296,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Aschoff bodies, pathognomonic for rheumatic fever, are typically found in which cardiac layer?","options": [{"key": "A","text": "Endocardium exclusively"},{"key": "B","text": "Cardiac valves exclusively"},{"key": "C","text": "Pericardium exclusively"},{"key": "D","text": "Myocardium"}],"correct": "D","explanation": "Aschoff bodies are granulomatous inflammatory foci found in the myocardium during acute rheumatic carditis."},{"id": 4297,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Emphysema results in permanent enlargement of airspaces due to destruction of walls distal to which structure?","options": [{"key": "A","text": "Main bronchi"},{"key": "B","text": "Terminal bronchioles"},{"key": "C","text": "Trachea"},{"key": "D","text": "Larynx"}],"correct": "B","explanation": "Emphysema is defined by permanent enlargement of airspaces distal to the terminal bronchioles, with destruction of alveolar walls."},{"id": 4298,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "The primary organism causing community-acquired lobar pneumonia is:","options": [{"key": "A","text": "Streptococcus pneumoniae"},{"key": "B","text": "Legionella pneumophila"},{"key": "C","text": "Mycobacterium tuberculosis"},{"key": "D","text": "Pseudomonas aeruginosa"}],"correct": "A","explanation": "S. pneumoniae remains the most common cause of typical community-acquired lobar pneumonia."},{"id": 4299,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Bronchiectasis is characterized pathologically by:","options": [{"key": "A","text": "Normal bronchial architecture with mucus plugging only"},{"key": "B","text": "Reversible bronchoconstriction"},{"key": "C","text": "Alveolar collapse without airway involvement"},{"key": "D","text": "Permanent abnormal dilation of bronchi with wall destruction"}],"correct": "D","explanation": "Chronic infection/inflammation causes irreversible structural damage and dilation of bronchial walls in bronchiectasis."},{"id": 4300,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Sickle cell disease results from a single amino acid substitution where glutamic acid is replaced by:","options": [{"key": "A","text": "Alanine"},{"key": "B","text": "Valine"},{"key": "C","text": "Leucine"},{"key": "D","text": "Lysine"}],"correct": "B","explanation": "A point mutation causes substitution of valine for glutamic acid at position 6 of the beta-globin chain, producing HbS."},{"id": 4301,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The Philadelphia chromosome, characteristic of CML, results from translocation between chromosomes:","options": [{"key": "A","text": "14 and 18"},{"key": "B","text": "9 and 22"},{"key": "C","text": "15 and 17"},{"key": "D","text": "8 and 14"}],"correct": "B","explanation": "The t(9;22) translocation creates the BCR-ABL fusion gene, driving chronic myeloid leukemia."},{"id": 4302,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Reed-Sternberg cells, diagnostic of Hodgkin lymphoma, characteristically show which nuclear appearance?","options": [{"key": "A","text": "Absence of any visible nucleus"},{"key": "B","text": "Single small dense nucleus"},{"key": "C","text": "Binucleate with prominent 'owl-eye' nucleoli"},{"key": "D","text": "Multiple small nuclei without nucleoli"}],"correct": "C","explanation": "Reed-Sternberg cells are large cells with bilobed nuclei and prominent eosinophilic nucleoli, giving an 'owl-eye' appearance."},{"id": 4303,"subject": "Pathology","topic": "Infectious Disease","difficulty": "Easy","question": "Chronic peptic ulcers are most commonly associated with infection by:","options": [{"key": "A","text": "Helicobacter pylori"},{"key": "B","text": "Escherichia coli"},{"key": "C","text": "Salmonella typhi"},{"key": "D","text": "Clostridium difficile"}],"correct": "A","explanation": "H. pylori infection is the leading identifiable cause of chronic peptic ulcer disease, alongside NSAID use."},{"id": 4304,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Easy","question": "Cirrhosis represents the end stage of chronic liver disease, characterized by fibrosis and:","options": [{"key": "A","text": "Regenerative nodules disrupting normal architecture"},{"key": "B","text": "Complete absence of any nodularity"},{"key": "C","text": "Isolated bile duct proliferation only"},{"key": "D","text": "Pure fatty infiltration without fibrosis"}],"correct": "A","explanation": "Cirrhosis involves diffuse fibrous septa surrounding regenerative parenchymal nodules, destroying the normal hepatic lobular architecture."},{"id": 4305,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hepatitis B and C viruses are most concerning long-term due to their association with progression to:","options": [{"key": "A","text": "Chronic hepatitis, cirrhosis, and hepatocellular carcinoma"},{"key": "B","text": "No long-term sequelae"},{"key": "C","text": "Acute self-limiting illness only"},{"key": "D","text": "Isolated gallstone formation"}],"correct": "A","explanation": "Chronic HBV/HCV infection can progress through chronic hepatitis to cirrhosis and significantly increases hepatocellular carcinoma risk."},{"id": 4306,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Nephrotic syndrome is characterized by heavy proteinuria exceeding approximately:","options": [{"key": "A","text": "0.5 g/day"},{"key": "B","text": "3.5 g/day"},{"key": "C","text": "1 g/week"},{"key": "D","text": "10 mg/day"}],"correct": "B","explanation": "Nephrotic-range proteinuria is generally defined as greater than 3.5 grams per day in adults."},{"id": 4307,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Minimal change disease shows which finding on light microscopy despite significant proteinuria?","options": [{"key": "A","text": "Essentially normal-appearing glomeruli"},{"key": "B","text": "Nodular sclerosis"},{"key": "C","text": "Crescent formation"},{"key": "D","text": "Diffuse mesangial proliferation"}],"correct": "A","explanation": "Minimal change disease is characterized by normal light microscopy findings, with the pathology only visible as podocyte foot process effacement on electron microscopy."},{"id": 4308,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Chronic kidney disease is staged based primarily on which laboratory parameter?","options": [{"key": "A","text": "Serum albumin level"},{"key": "B","text": "Hemoglobin level"},{"key": "C","text": "Estimated glomerular filtration rate (eGFR)"},{"key": "D","text": "Serum sodium level"}],"correct": "C","explanation": "CKD staging (1-5) is based on eGFR, reflecting the degree of kidney function impairment."},{"id": 4309,"subject": "Pathology","topic": "Immunology","difficulty": "Easy","question": "Type 1 diabetes mellitus results from autoimmune destruction of which pancreatic cells?","options": [{"key": "A","text": "Beta cells of the islets of Langerhans"},{"key": "B","text": "Alpha cells"},{"key": "C","text": "Acinar cells"},{"key": "D","text": "Delta cells"}],"correct": "A","explanation": "T-cell mediated autoimmune destruction specifically targets insulin-producing beta cells, causing absolute insulin deficiency."},{"id": 4310,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Graves' disease results from autoantibodies that stimulate which receptor?","options": [{"key": "A","text": "Growth hormone receptor"},{"key": "B","text": "Insulin receptor"},{"key": "C","text": "TSH receptor"},{"key": "D","text": "Acetylcholine receptor"}],"correct": "C","explanation": "Thyroid-stimulating immunoglobulins bind and activate TSH receptors, causing excessive thyroid hormone production in Graves' disease."},{"id": 4311,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Cushing syndrome results from chronic excess exposure to which hormone?","options": [{"key": "A","text": "Thyroid hormone"},{"key": "B","text": "Growth hormone"},{"key": "C","text": "Aldosterone"},{"key": "D","text": "Cortisol"}],"correct": "D","explanation": "Cushing syndrome is caused by prolonged glucocorticoid (cortisol) excess, whether endogenous or from exogenous steroid use."},{"id": 4312,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "A DEXA T-score between -1.0 and -2.5 SD is classified as:","options": [{"key": "A","text": "Osteomalacia"},{"key": "B","text": "Osteopenia"},{"key": "C","text": "Normal bone density"},{"key": "D","text": "Osteoporosis"}],"correct": "B","explanation": "T-scores between -1.0 and -2.5 indicate osteopenia, a lower-than-normal bone density that has not yet reached the osteoporosis threshold."},{"id": 4313,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Paget's disease of bone shows which characteristic histological pattern reflecting chaotic remodeling?","options": [{"key": "A","text": "Pure cartilaginous tissue"},{"key": "B","text": "Uniform woven bone only"},{"key": "C","text": "Mosaic pattern of lamellar bone"},{"key": "D","text": "Complete absence of osteoblasts"}],"correct": "C","explanation": "The disorganized, rapid bone turnover in Paget's disease produces a characteristic mosaic pattern of cement lines visible histologically."},{"id": 4314,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteosarcoma most frequently arises in which location during adolescence?","options": [{"key": "A","text": "Metaphysis of long bones (e.g., distal femur)"},{"key": "B","text": "Diaphysis of short bones"},{"key": "C","text": "Epiphysis after growth plate closure"},{"key": "D","text": "Flat bones of the skull"}],"correct": "A","explanation": "Osteosarcoma classically develops in the metaphyseal region of long bones near the growth plate during periods of rapid bone growth in adolescence."},{"id": 4315,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Ewing sarcoma is associated with which characteristic chromosomal translocation?","options": [{"key": "A","text": "t(15;17)"},{"key": "B","text": "t(9;22)"},{"key": "C","text": "t(14;18)"},{"key": "D","text": "t(11;22)"}],"correct": "D","explanation": "Ewing sarcoma is characterized by the t(11;22) translocation producing the EWS-FLI1 fusion gene."},{"id": 4316,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Osteomyelitis in children most commonly affects which region of long bones due to vascular anatomy?","options": [{"key": "A","text": "Epiphysis exclusively"},{"key": "B","text": "Diaphysis"},{"key": "C","text": "Metaphysis"},{"key": "D","text": "Articular cartilage only"}],"correct": "C","explanation": "The metaphysis has a rich but sluggish blood supply with vascular loops, making it particularly susceptible to hematogenous bacterial seeding in children."},{"id": 4317,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Duchenne muscular dystrophy is caused by mutation in the gene encoding:","options": [{"key": "A","text": "Titin"},{"key": "B","text": "Troponin C"},{"key": "C","text": "Myosin heavy chain"},{"key": "D","text": "Dystrophin"}],"correct": "D","explanation": "DMD results from mutations in the dystrophin gene on the X chromosome, causing absence of this critical structural muscle protein."},{"id": 4318,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Achondroplasia, the most common form of dwarfism, results from mutation in which gene?","options": [{"key": "A","text": "FGFR3"},{"key": "B","text": "Dystrophin"},{"key": "C","text": "COL1A1"},{"key": "D","text": "Fibrillin-1"}],"correct": "A","explanation": "Achondroplasia results from activating mutations in the FGFR3 gene, which inhibits endochondral bone growth."},{"id": 4319,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Ischemic stroke most commonly results from thrombosis superimposed on which underlying vascular pathology?","options": [{"key": "A","text": "Amyloid deposition"},{"key": "B","text": "Congenital malformation"},{"key": "C","text": "Vasculitis"},{"key": "D","text": "Atherosclerosis"}],"correct": "D","explanation": "Atherosclerotic plaque with superimposed thrombosis is the most common cause of large-vessel ischemic stroke."},{"id": 4320,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Charcot-Bouchard microaneurysms, associated with hypertensive hemorrhage, typically develop in which vessels?","options": [{"key": "A","text": "Pulmonary arteries"},{"key": "B","text": "Coronary arteries"},{"key": "C","text": "Small penetrating arteries of the basal ganglia and thalamus"},{"key": "D","text": "Large vessels of the Circle of Willis"}],"correct": "C","explanation": "Chronic hypertension causes microaneurysm formation in small penetrating vessels, predisposing to intracerebral hemorrhage in these regions."},{"id": 4321,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Guillain-Barre syndrome is characterized pathologically by autoimmune-mediated damage to:","options": [{"key": "A","text": "Peripheral nerve myelin"},{"key": "B","text": "Neuromuscular junction receptors"},{"key": "C","text": "Anterior horn cell bodies"},{"key": "D","text": "Central nervous system myelin exclusively"}],"correct": "A","explanation": "GBS involves autoimmune attack on peripheral nerve myelin (or axons in some variants), typically following an infectious trigger."},{"id": 4322,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Meningiomas typically arise from which cell type within the meninges?","options": [{"key": "A","text": "Dural fibroblasts"},{"key": "B","text": "Ependymal cells"},{"key": "C","text": "Arachnoid cap cells"},{"key": "D","text": "Microglia"}],"correct": "C","explanation": "Meningiomas, usually benign, originate from arachnoid cap cells and are typically extra-axial in location."},{"id": 4323,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Glioblastoma multiforme is characterized by which histological feature distinguishing it from lower-grade astrocytomas?","options": [{"key": "A","text": "Pseudopalisading necrosis with microvascular proliferation"},{"key": "B","text": "Complete absence of necrosis"},{"key": "C","text": "Presence of Reed-Sternberg cells"},{"key": "D","text": "Uniform, well-differentiated cell morphology"}],"correct": "A","explanation": "GBM shows characteristic areas of necrosis surrounded by densely packed tumor cells (pseudopalisading) along with prominent microvascular proliferation."},{"id": 4324,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Epidural hematoma classically results from injury to which vessel following temporal bone fracture?","options": [{"key": "A","text": "Superior sagittal sinus"},{"key": "B","text": "Middle meningeal artery"},{"key": "C","text": "Bridging veins"},{"key": "D","text": "Posterior cerebral artery"}],"correct": "B","explanation": "The middle meningeal artery runs beneath the temporal bone and is vulnerable to laceration with temporal skull fractures, causing rapid arterial epidural bleeding."},{"id": 4325,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "The earliest atherosclerotic lesion, the fatty streak, is composed of accumulated:","options": [{"key": "A","text": "Calcified debris"},{"key": "B","text": "Lipid-laden macrophages (foam cells)"},{"key": "C","text": "Fibrin clots"},{"key": "D","text": "Cholesterol crystals alone without cells"}],"correct": "B","explanation": "Fatty streaks consist of macrophages that have engulfed oxidized LDL, becoming lipid-laden foam cells, representing the earliest visible atherosclerotic change."},{"id": 4326,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Mitral valve stenosis is most commonly caused by which disease process?","options": [{"key": "A","text": "Bacterial endocarditis exclusively"},{"key": "B","text": "Chronic rheumatic heart disease"},{"key": "C","text": "Age-related calcification exclusively"},{"key": "D","text": "Congenital malformation exclusively"}],"correct": "B","explanation": "Chronic rheumatic heart disease remains the leading cause of mitral stenosis, resulting from fibrosis and fusion of valve leaflets after recurrent rheumatic fever."},{"id": 4327,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cardiac tamponade develops when fluid accumulation in the pericardial space causes:","options": [{"key": "A","text": "No hemodynamic consequence"},{"key": "B","text": "Isolated valve dysfunction"},{"key": "C","text": "Impaired ventricular filling and reduced cardiac output"},{"key": "D","text": "Increased ventricular filling capacity"}],"correct": "C","explanation": "Rapid pericardial fluid accumulation raises intrapericardial pressure, restricting ventricular filling and compromising cardiac output."},{"id": 4328,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Right-sided heart failure classically produces which systemic finding due to venous congestion?","options": [{"key": "A","text": "Peripheral edema and jugular venous distension"},{"key": "B","text": "Hemoptysis as the primary finding"},{"key": "C","text": "Orthopnea as the dominant symptom"},{"key": "D","text": "Pulmonary edema as the primary finding"}],"correct": "A","explanation": "Right heart failure causes backup of blood into the systemic venous system, producing peripheral edema and elevated jugular venous pressure."},{"id": 4329,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Coarctation of the aorta typically causes which clinical finding pattern?","options": [{"key": "A","text": "Generalized hypotension in all extremities"},{"key": "B","text": "Lower extremity hypertension with normal upper limb pulses"},{"key": "C","text": "Equal blood pressure throughout all extremities"},{"key": "D","text": "Upper extremity hypertension with diminished femoral pulses"}],"correct": "D","explanation": "Aortic coarctation, usually distal to the left subclavian artery, causes higher pressure proximal to the narrowing (upper limbs) and reduced pressure/pulses distally (lower limbs)."},{"id": 4330,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "ARDS (Acute Respiratory Distress Syndrome) results primarily from diffuse damage to which structure?","options": [{"key": "A","text": "Pleural lining exclusively"},{"key": "B","text": "Bronchial cartilage exclusively"},{"key": "C","text": "Alveolar-capillary membrane"},{"key": "D","text": "Tracheal epithelium exclusively"}],"correct": "C","explanation": "ARDS involves diffuse alveolar damage disrupting the alveolar-capillary barrier, causing non-cardiogenic pulmonary edema and severe hypoxemia."},{"id": 4331,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Asbestos exposure is a well-established risk factor for which malignancy of the pleura?","options": [{"key": "A","text": "Squamous cell carcinoma of skin"},{"key": "B","text": "Renal cell carcinoma"},{"key": "C","text": "Hepatocellular carcinoma"},{"key": "D","text": "Malignant mesothelioma"}],"correct": "D","explanation": "Chronic asbestos fiber inhalation is strongly linked to the development of malignant mesothelioma, a pleural/peritoneal malignancy."},{"id": 4332,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Hard","question": "Silicosis characteristically produces which pattern of pulmonary fibrosis?","options": [{"key": "A","text": "Lower lobe-predominant fibrosis"},{"key": "B","text": "Diffuse fibrosis with no zonal preference"},{"key": "C","text": "Upper lobe-predominant nodular fibrosis"},{"key": "D","text": "Fibrosis limited to the pleura only"}],"correct": "C","explanation": "Chronic silica dust exposure classically produces upper lobe-predominant nodular fibrotic lesions."},{"id": 4333,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Tension pneumothorax is a medical emergency caused by which pathophysiological mechanism?","options": [{"key": "A","text": "Complete lung collapse without any pressure gradient change"},{"key": "B","text": "A one-way valve air leak causing progressive intrapleural air accumulation and mediastinal shift"},{"key": "C","text": "Simple accumulation of fluid without pressure buildup"},{"key": "D","text": "Gradual, slow air leak without hemodynamic effect"}],"correct": "B","explanation": "A one-way valve mechanism allows air to enter but not exit the pleural space, causing progressively rising pressure that shifts the mediastinum and compromises venous return."},{"id": 4334,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Beta-thalassemia results from reduced or absent synthesis of which globin chain?","options": [{"key": "A","text": "Alpha-globin"},{"key": "B","text": "Beta-globin"},{"key": "C","text": "Gamma-globin"},{"key": "D","text": "Delta-globin exclusively"}],"correct": "B","explanation": "Beta-thalassemia results from mutations reducing or eliminating beta-globin chain production, causing imbalanced hemoglobin synthesis."},{"id": 4335,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hereditary spherocytosis results from a defect in which structural component of the red cell?","options": [{"key": "A","text": "Mitochondrial DNA"},{"key": "B","text": "Glycolytic enzymes"},{"key": "C","text": "Hemoglobin globin chains"},{"key": "D","text": "Membrane cytoskeleton proteins (e.g., spectrin)"}],"correct": "D","explanation": "Defects in spectrin, ankyrin, or related membrane cytoskeletal proteins weaken the red cell membrane, producing spherical, fragile cells."},{"id": 4336,"subject": "Pathology","topic": "Hematology","difficulty": "Medium","question": "Immune thrombocytopenic purpura (ITP) results from which mechanism causing low platelet counts?","options": [{"key": "A","text": "Bone marrow failure to produce platelets"},{"key": "B","text": "Excessive platelet consumption in clotting only"},{"key": "C","text": "Autoantibody-mediated platelet destruction"},{"key": "D","text": "Vitamin K deficiency"}],"correct": "C","explanation": "ITP is an autoimmune condition where antibodies target platelet surface antigens, leading to their premature destruction, primarily in the spleen."},{"id": 4337,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Von Willebrand disease, the most common inherited bleeding disorder, primarily impairs which process?","options": [{"key": "A","text": "Vitamin K-dependent factor synthesis"},{"key": "B","text": "Red blood cell production"},{"key": "C","text": "Fibrin cross-linking exclusively"},{"key": "D","text": "Platelet adhesion to damaged vessel walls"}],"correct": "D","explanation": "Von Willebrand factor is essential for platelet adhesion to subendothelial collagen; its deficiency impairs this primary hemostatic step."},{"id": 4338,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Barrett's esophagus is a premalignant condition predisposing to which cancer type?","options": [{"key": "A","text": "Esophageal adenocarcinoma"},{"key": "B","text": "Gastric lymphoma"},{"key": "C","text": "Colorectal adenocarcinoma"},{"key": "D","text": "Esophageal squamous cell carcinoma"}],"correct": "A","explanation": "Barrett's metaplasia (columnar replacing squamous epithelium) increases risk of progression to esophageal adenocarcinoma."},{"id": 4339,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Crohn's disease is characterized by which distinctive pattern of bowel involvement compared to ulcerative colitis?","options": [{"key": "A","text": "Continuous mucosal-only inflammation limited to the colon"},{"key": "B","text": "Transmural inflammation with skip lesions anywhere in the GI tract"},{"key": "C","text": "Inflammation limited exclusively to the stomach"},{"key": "D","text": "Inflammation limited exclusively to the esophagus"}],"correct": "B","explanation": "Crohn's disease can affect any part of the GI tract with characteristic skip lesions and full-thickness (transmural) inflammation, unlike the continuous, colon-limited, mucosal disease of ulcerative colitis."},{"id": 4340,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Acute pancreatitis is most commonly caused by which two etiologies combined?","options": [{"key": "A","text": "Viral infection and autoimmune disease"},{"key": "B","text": "Gallstones and chronic alcohol consumption"},{"key": "C","text": "Genetic mutation exclusively"},{"key": "D","text": "Trauma and medication toxicity only"}],"correct": "B","explanation": "Gallstones and alcohol abuse together account for the vast majority of acute pancreatitis cases worldwide."},{"id": 4341,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Portal hypertension, a complication of cirrhosis, leads to formation of esophageal varices due to:","options": [{"key": "A","text": "Reduced hepatic arterial flow only"},{"key": "B","text": "Direct arterial hypertension in the esophagus"},{"key": "C","text": "Development of portosystemic collateral venous circulation"},{"key": "D","text": "Isolated muscular hypertrophy of the esophagus"}],"correct": "C","explanation": "Elevated portal pressure causes blood to seek alternative pathways through portosystemic collaterals, including esophageal varices, which are prone to rupture."},{"id": 4342,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Diabetic nephropathy characteristically shows which histological lesion on kidney biopsy?","options": [{"key": "A","text": "Minimal change with normal light microscopy"},{"key": "B","text": "Amyloid deposition exclusively"},{"key": "C","text": "Crescent formation exclusively"},{"key": "D","text": "Kimmelstiel-Wilson nodules (nodular glomerulosclerosis)"}],"correct": "D","explanation": "Diabetic nephropathy classically produces nodular glomerulosclerosis (Kimmelstiel-Wilson lesions) from chronic hyperglycemic damage to glomerular structures."},{"id": 4343,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Acute tubular necrosis, a common cause of intrarenal acute kidney injury, most often results from:","options": [{"key": "A","text": "Congenital renal malformation"},{"key": "B","text": "Ureteral obstruction exclusively"},{"key": "C","text": "Glomerular immune complex deposition exclusively"},{"key": "D","text": "Ischemic or nephrotoxic injury to tubular epithelial cells"}],"correct": "D","explanation": "ATN results from direct ischemic or toxic damage to renal tubular cells, a common and often reversible cause of intrarenal AKI."},{"id": 4344,"subject": "Pathology","topic": "Neoplasia","difficulty": "Medium","question": "Renal cell carcinoma is most strongly associated with which modifiable risk factor?","options": [{"key": "A","text": "Autoimmune disease"},{"key": "B","text": "Cigarette smoking"},{"key": "C","text": "Congenital anomaly"},{"key": "D","text": "Viral infection"}],"correct": "B","explanation": "Smoking is the most significant modifiable risk factor for renal cell carcinoma development."},{"id": 4345,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Primary hyperparathyroidism, most commonly from a parathyroid adenoma, produces which characteristic biochemical pattern?","options": [{"key": "A","text": "Normal calcium with elevated phosphate"},{"key": "B","text": "Hypercalcemia with hyperphosphatemia"},{"key": "C","text": "Hypocalcemia with hyperphosphatemia"},{"key": "D","text": "Hypercalcemia with hypophosphatemia"}],"correct": "D","explanation": "Excess PTH increases bone resorption and renal calcium reabsorption while decreasing phosphate reabsorption, producing hypercalcemia with hypophosphatemia."},{"id": 4346,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Addison's disease (primary adrenal insufficiency) results in deficiency of both cortisol and:","options": [{"key": "A","text": "Insulin"},{"key": "B","text": "Thyroid hormone"},{"key": "C","text": "Aldosterone"},{"key": "D","text": "Growth hormone"}],"correct": "C","explanation": "Primary adrenal cortex destruction in Addison's disease causes combined glucocorticoid (cortisol) and mineralocorticoid (aldosterone) deficiency."},{"id": 4347,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Systemic lupus erythematosus is predominantly mediated by which hypersensitivity mechanism?","options": [{"key": "A","text": "Type III (immune complex-mediated)"},{"key": "B","text": "Type II (antibody-mediated cytotoxicity) exclusively"},{"key": "C","text": "Type IV (T-cell mediated) exclusively"},{"key": "D","text": "Type I (IgE-mediated)"}],"correct": "A","explanation": "SLE involves widespread immune complex deposition in tissues and vessels, activating complement and causing inflammation, characteristic of Type III hypersensitivity."},{"id": 4348,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Myasthenia gravis results from autoantibodies targeting which structure at the neuromuscular junction?","options": [{"key": "A","text": "Postsynaptic acetylcholine receptors"},{"key": "B","text": "Presynaptic calcium channels"},{"key": "C","text": "Motor neuron cell bodies"},{"key": "D","text": "Muscle spindle fibers"}],"correct": "A","explanation": "MG is caused by autoantibodies that block or destroy postsynaptic nicotinic acetylcholine receptors, impairing neuromuscular transmission."},{"id": 4349,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Anaphylaxis is a severe, life-threatening example of which hypersensitivity type?","options": [{"key": "A","text": "Type I"},{"key": "B","text": "Type III"},{"key": "C","text": "Type IV"},{"key": "D","text": "Type II"}],"correct": "A","explanation": "Anaphylaxis represents an extreme systemic manifestation of IgE-mediated Type I hypersensitivity."},{"id": 4350,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Contact dermatitis, such as from poison ivy exposure, is classically mediated by which hypersensitivity mechanism?","options": [{"key": "A","text": "Type I (immediate, IgE-mediated)"},{"key": "B","text": "Type III (immune complex-mediated)"},{"key": "C","text": "Type II (antibody-mediated)"},{"key": "D","text": "Type IV (delayed-type, T-cell mediated)"}],"correct": "D","explanation": "Contact dermatitis is a classic delayed-type hypersensitivity reaction mediated by sensitized T lymphocytes."},{"id": 4351,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Down syndrome most commonly results from which chromosomal abnormality?","options": [{"key": "A","text": "Monosomy 21"},{"key": "B","text": "Deletion of chromosome 21"},{"key": "C","text": "Trisomy 21 (nondisjunction)"},{"key": "D","text": "Translocation exclusively"}],"correct": "C","explanation": "The vast majority of Down syndrome cases result from meiotic nondisjunction producing trisomy 21, with translocation and mosaicism being less common causes."},{"id": 4352,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Marfan syndrome is caused by mutations affecting which structural protein?","options": [{"key": "A","text": "Spectrin"},{"key": "B","text": "Fibrillin-1"},{"key": "C","text": "Dystrophin"},{"key": "D","text": "Collagen type I"}],"correct": "B","explanation": "Marfan syndrome results from mutations in the FBN1 gene encoding fibrillin-1, a key component of connective tissue microfibrils."},{"id": 4353,"subject": "Pathology","topic": "Inflammation & Repair","difficulty": "Medium","question": "Cystic fibrosis is inherited in which pattern and affects which gene?","options": [{"key": "A","text": "Mitochondrial inheritance, unspecified gene"},{"key": "B","text": "Autosomal dominant, CFTR gene"},{"key": "C","text": "Autosomal recessive, CFTR gene"},{"key": "D","text": "X-linked recessive, dystrophin gene"}],"correct": "C","explanation": "CF is an autosomal recessive disorder caused by mutations in the CFTR chloride channel gene, causing thick secretions in multiple organ systems."},{"id": 4354,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Fragile X syndrome, a common cause of inherited intellectual disability, results from expansion of which type of repeat sequence?","options": [{"key": "A","text": "CAG repeat in the huntingtin gene"},{"key": "B","text": "GAA repeat in the frataxin gene"},{"key": "C","text": "CGG trinucleotide repeat in the FMR1 gene"},{"key": "D","text": "CTG repeat in the DMPK gene"}],"correct": "C","explanation": "Fragile X syndrome results from expansion of CGG trinucleotide repeats in the FMR1 gene, leading to gene silencing."},{"id": 4355,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Wilson's disease results from abnormal accumulation of which metal, affecting liver and brain?","options": [{"key": "A","text": "Iron"},{"key": "B","text": "Zinc"},{"key": "C","text": "Copper"},{"key": "D","text": "Manganese"}],"correct": "C","explanation": "Wilson's disease is caused by defective copper transport (ATP7B gene mutation), leading to toxic accumulation in liver, brain, and eyes."},{"id": 4356,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Hemochromatosis is characterized by excessive absorption and deposition of which substance?","options": [{"key": "A","text": "Copper"},{"key": "B","text": "Calcium"},{"key": "C","text": "Uric acid"},{"key": "D","text": "Iron"}],"correct": "D","explanation": "Hereditary hemochromatosis causes excess intestinal iron absorption, leading to deposition in liver, heart, pancreas, and joints."},{"id": 4357,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Peutz-Jeghers syndrome is characterized by intestinal hamartomatous polyps combined with:","options": [{"key": "A","text": "Retinal angiomas"},{"key": "B","text": "Cutaneous neurofibromas"},{"key": "C","text": "Mucocutaneous pigmentation"},{"key": "D","text": "Café-au-lait spots exclusively"}],"correct": "C","explanation": "Peutz-Jeghers syndrome combines GI hamartomatous polyposis with characteristic mucocutaneous melanin pigmentation, particularly around the lips."},{"id": 4358,"subject": "Pathology","topic": "Neoplasia","difficulty": "Hard","question": "Familial adenomatous polyposis is caused by mutation in which tumor suppressor gene?","options": [{"key": "A","text": "Rb gene"},{"key": "B","text": "APC gene"},{"key": "C","text": "p53 gene"},{"key": "D","text": "BRCA1 gene"}],"correct": "B","explanation": "FAP results from germline mutations in the APC (adenomatous polyposis coli) tumor suppressor gene, causing hundreds to thousands of colonic polyps."},{"id": 4359,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Li-Fraumeni syndrome, predisposing to multiple early-onset cancers, results from germline mutation in which gene?","options": [{"key": "A","text": "Rb"},{"key": "B","text": "APC"},{"key": "C","text": "BRCA1"},{"key": "D","text": "p53"}],"correct": "D","explanation": "Li-Fraumeni syndrome results from inherited p53 tumor suppressor gene mutations, predisposing to a wide spectrum of cancers at young ages."},{"id": 4360,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Compartment syndrome causes tissue ischemia primarily through which mechanism?","options": [{"key": "A","text": "Direct arterial laceration exclusively"},{"key": "B","text": "Elevated pressure within a closed fascial compartment compromising capillary perfusion"},{"key": "C","text": "Venous thrombosis exclusively"},{"key": "D","text": "Bacterial infection of muscle tissue"}],"correct": "B","explanation": "Increased intracompartmental pressure exceeds capillary perfusion pressure, causing ischemic injury to muscle and nerve within the closed fascial space."},{"id": 4361,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Rhabdomyolysis can lead to acute kidney injury primarily through the nephrotoxic effects of released:","options": [{"key": "A","text": "Hemoglobin exclusively"},{"key": "B","text": "Lactate dehydrogenase directly"},{"key": "C","text": "Myoglobin"},{"key": "D","text": "Creatine kinase directly"}],"correct": "C","explanation": "Myoglobin released from damaged muscle fibers is directly nephrotoxic and can precipitate within renal tubules, causing acute tubular injury."},{"id": 4362,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Avascular necrosis of the femoral head is most strongly associated with which two risk factors?","options": [{"key": "A","text": "Vitamin C deficiency and iron overload"},{"key": "B","text": "Excess vitamin D and hypercalcemia"},{"key": "C","text": "Corticosteroid use and chronic alcohol abuse"},{"key": "D","text": "Low-impact exercise and vegetarian diet"}],"correct": "C","explanation": "Chronic corticosteroid use and alcoholism are the most significant risk factors for femoral head avascular necrosis by disrupting the microvascular blood supply."},{"id": 4363,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Charcot joint (neuropathic arthropathy) results primarily from loss of which sensory modality leading to repeated joint trauma?","options": [{"key": "A","text": "Vision exclusively"},{"key": "B","text": "Proprioception and pain sensation"},{"key": "C","text": "Hearing exclusively"},{"key": "D","text": "Taste exclusively"}],"correct": "B","explanation": "Loss of protective pain and proprioceptive sensation, as in diabetic neuropathy, allows repeated unrecognized joint trauma leading to progressive destruction."},{"id": 4364,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Osteochondritis dissecans involves separation of a bone-cartilage fragment due to:","options": [{"key": "A","text": "Localized avascular necrosis of subchondral bone"},{"key": "B","text": "Autoimmune synovial destruction"},{"key": "C","text": "Bacterial infection of the joint"},{"key": "D","text": "Direct traumatic fracture through the joint line only"}],"correct": "A","explanation": "OCD results from focal subchondral avascular necrosis, causing the overlying cartilage-bone fragment to separate, commonly affecting the knee in young athletes."},{"id": 4365,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Cauda equina syndrome results from compression of nerve roots below which spinal level?","options": [{"key": "A","text": "Cervical spinal cord"},{"key": "B","text": "Thoracic spinal cord"},{"key": "C","text": "Brainstem"},{"key": "D","text": "Conus medullaris (typically below L1-L2)"}],"correct": "D","explanation": "Cauda equina syndrome results from compression of the lumbosacral nerve root bundle below the conus medullaris, a surgical emergency."},{"id": 4366,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Brown-Sequard syndrome, resulting from spinal cord hemisection, causes which characteristic sensory pattern?","options": [{"key": "A","text": "Isolated bilateral motor loss without any sensory change"},{"key": "B","text": "Contralateral proprioceptive loss with ipsilateral pain/temperature loss"},{"key": "C","text": "Bilateral complete sensory loss below the lesion"},{"key": "D","text": "Ipsilateral proprioceptive loss with contralateral pain/temperature loss"}],"correct": "D","explanation": "Hemisection damages the ipsilateral dorsal columns (proprioception) and the crossing contralateral spinothalamic tract fibers (pain/temperature), producing this classic dissociated sensory pattern."},{"id": 4367,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Central cord syndrome, often from hyperextension injury in a stenotic cervical spine, classically produces:","options": [{"key": "A","text": "Greater weakness in the lower extremities than upper extremities"},{"key": "B","text": "Complete equal paralysis of all four limbs"},{"key": "C","text": "Isolated sensory loss without any motor weakness"},{"key": "D","text": "Greater weakness in the upper extremities than lower extremities"}],"correct": "D","explanation": "Central cord syndrome disproportionately affects the centrally located cervical fibers controlling upper limb function, producing arm-predominant weakness."},{"id": 4368,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Anterior cord syndrome, resulting from anterior spinal artery infarction, causes loss of motor function and pain/temperature sensation while sparing:","options": [{"key": "A","text": "All sensory modalities equally"},{"key": "B","text": "Bladder function exclusively"},{"key": "C","text": "Proprioception and vibration sense (posterior columns)"},{"key": "D","text": "Cranial nerve function"}],"correct": "C","explanation": "Anterior spinal artery infarction affects the anterior two-thirds of the cord, sparing the posterior column-mediated proprioception and vibration sense."},{"id": 4369,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Wallerian degeneration describes degenerative changes occurring in which segment of an injured axon?","options": [{"key": "A","text": "The distal segment, away from the cell body"},{"key": "B","text": "The myelin sheath of uninjured neighboring axons"},{"key": "C","text": "The proximal segment only"},{"key": "D","text": "The cell body exclusively"}],"correct": "A","explanation": "Following axonal injury, the distal segment (disconnected from the cell body's metabolic support) undergoes Wallerian degeneration, while the proximal segment may regenerate."},{"id": 4370,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Cerebral palsy is best defined as a static (non-progressive) motor impairment resulting from:","options": [{"key": "A","text": "An autoimmune demyelinating condition"},{"key": "B","text": "A purely genetic muscular disorder"},{"key": "C","text": "A progressive neurodegenerative process in adulthood"},{"key": "D","text": "Brain injury or malformation occurring during the perinatal period"}],"correct": "D","explanation": "CP results from a non-progressive insult to the developing brain around the time of birth, though the resulting motor impairment can change in presentation as the child grows."},{"id": 4371,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Spastic cerebral palsy, the most common subtype, results from damage primarily to which neural pathway?","options": [{"key": "A","text": "Peripheral motor nerves exclusively"},{"key": "B","text": "Basal ganglia pathways exclusively"},{"key": "C","text": "Cerebellar pathways exclusively"},{"key": "D","text": "Corticospinal (upper motor neuron) tract"}],"correct": "D","explanation": "Spastic CP results from upper motor neuron (corticospinal tract) damage, producing increased muscle tone and hyperreflexia."},{"id": 4372,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Kernicterus, a cause of dyskinetic cerebral palsy, results from bilirubin toxicity affecting which brain structure?","options": [{"key": "A","text": "Basal ganglia"},{"key": "B","text": "Hippocampus exclusively"},{"key": "C","text": "Cerebellum exclusively"},{"key": "D","text": "Corticospinal tract exclusively"}],"correct": "A","explanation": "Severe neonatal hyperbilirubinemia deposits preferentially in the basal ganglia, causing kernicterus and subsequent dyskinetic movement patterns."},{"id": 4373,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Syringomyelia, characterized by a fluid-filled cavity within the spinal cord, classically causes which pattern of sensory loss?","options": [{"key": "A","text": "Complete sensory loss below the lesion level only"},{"key": "B","text": "Isolated loss of proprioception only"},{"key": "C","text": "Loss of vision without any somatic sensory involvement"},{"key": "D","text": "Cape-like (bilateral upper limb) loss of pain and temperature sensation"}],"correct": "D","explanation": "The centrally located syrinx disrupts crossing spinothalamic fibers, producing a characteristic cape-like distribution of pain/temperature sensory loss while sparing proprioception (posterior columns) and touch initially."},{"id": 4374,"subject": "Pathology","topic": "Cell Injury & Death","difficulty": "Medium","question": "Subacute combined degeneration of the spinal cord results from deficiency of which vitamin?","options": [{"key": "A","text": "Vitamin B1 (thiamine)"},{"key": "B","text": "Vitamin D"},{"key": "C","text": "Vitamin B12"},{"key": "D","text": "Vitamin C"}],"correct": "C","explanation": "B12 deficiency causes demyelination of the dorsal columns and lateral corticospinal tracts, producing combined sensory and motor deficits."},{"id": 4375,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Wernicke's encephalopathy, associated with chronic alcoholism, results from deficiency of which vitamin?","options": [{"key": "A","text": "Thiamine (Vitamin B1)"},{"key": "B","text": "Vitamin B12"},{"key": "C","text": "Vitamin C"},{"key": "D","text": "Folate exclusively"}],"correct": "A","explanation": "Thiamine deficiency, commonly seen in chronic alcoholics, causes Wernicke's encephalopathy with the classic triad of confusion, ataxia, and ophthalmoplegia."},{"id": 4376,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Multiple myeloma causes characteristic 'punched-out' lytic bone lesions primarily through which mechanism?","options": [{"key": "A","text": "Direct bone infection by plasma cells"},{"key": "B","text": "Vitamin D toxicity secondary to the malignancy"},{"key": "C","text": "Excess osteoblast activity from tumor cells"},{"key": "D","text": "Osteoclast activation by cytokines (e.g., RANKL) secreted by malignant plasma cells"}],"correct": "D","explanation": "Malignant plasma cells secrete osteoclast-activating factors, stimulating bone resorption and producing the characteristic lytic lesions of multiple myeloma."},{"id": 4377,"subject": "Pathology","topic": "Immunology","difficulty": "Medium","question": "Ankylosing spondylitis shows strong association with which HLA antigen?","options": [{"key": "A","text": "HLA-B8"},{"key": "B","text": "HLA-B27"},{"key": "C","text": "HLA-DR3"},{"key": "D","text": "HLA-DR4"}],"correct": "B","explanation": "Ankylosing spondylitis has one of the strongest known HLA associations, with the majority of patients carrying HLA-B27."},{"id": 4378,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Osteoarthritis is best characterized as a degenerative joint disease primarily affecting which structure initially?","options": [{"key": "A","text": "Articular cartilage"},{"key": "B","text": "Ligaments primarily"},{"key": "C","text": "Synovium primarily"},{"key": "D","text": "Bone marrow primarily"}],"correct": "A","explanation": "OA begins with progressive degeneration and loss of articular cartilage, with secondary changes in subchondral bone and other joint structures."},{"id": 4379,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Osteomalacia in adults results from inadequate mineralization of osteoid due to deficiency of:","options": [{"key": "A","text": "Vitamin B12"},{"key": "B","text": "Vitamin C"},{"key": "C","text": "Vitamin K"},{"key": "D","text": "Vitamin D"}],"correct": "D","explanation": "Osteomalacia results from insufficient vitamin D leading to impaired calcium/phosphate absorption and inadequate mineralization of newly formed bone matrix (osteoid)."},{"id": 4380,"subject": "Pathology","topic": "General Pathology","difficulty": "Hard","question": "Osteopetrosis, sometimes called 'marble bone disease,' results from a defect in which cell type's function?","options": [{"key": "A","text": "Chondrocytes"},{"key": "B","text": "Osteoblasts"},{"key": "C","text": "Fibroblasts"},{"key": "D","text": "Osteoclasts"}],"correct": "D","explanation": "Osteopetrosis results from defective osteoclastic bone resorption, causing abnormally dense but structurally weak and brittle bone."},{"id": 4381,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Gout results from tissue deposition of which crystal type due to hyperuricemia?","options": [{"key": "A","text": "Calcium pyrophosphate crystals"},{"key": "B","text": "Cholesterol crystals"},{"key": "C","text": "Monosodium urate crystals"},{"key": "D","text": "Calcium oxalate crystals"}],"correct": "C","explanation": "Gout is caused by monosodium urate crystal deposition in joints and soft tissue as a result of chronic hyperuricemia."},{"id": 4382,"subject": "Pathology","topic": "General Pathology","difficulty": "Medium","question": "Pseudogout differs from gout in being caused by deposition of which crystal type?","options": [{"key": "A","text": "Monosodium urate crystals"},{"key": "B","text": "Cholesterol crystals"},{"key": "C","text": "Calcium pyrophosphate dihydrate crystals"},{"key": "D","text": "Hydroxyapatite crystals exclusively"}],"correct": "C","explanation": "Pseudogout results from calcium pyrophosphate dihydrate (CPPD) crystal deposition, most commonly affecting the knee joint."},{"id": 4383,"subject": "Pathology","topic": "General Pathology","difficulty": "Easy","question": "Septic arthritis, a medical emergency, is most commonly caused by which organism in adults?","options": [{"key": "A","text": "Mycobacterium tuberculosis"},{"key": "B","text": "Neisseria meningitidis"},{"key": "C","text": "Staphylococcus aureus"},{"key": "D","text": "Streptococcus viridans"}],"correct": "C","explanation": "S. aureus is the leading bacterial cause of septic arthritis, requiring urgent treatment to prevent rapid joint destruction."},{"id": 4384,"subject": "Pathology","topic": "Immunology","difficulty": "Easy","question": "Rheumatic heart disease develops as an autoimmune consequence of infection with which organism?","options": [{"key": "A","text": "Escherichia coli"},{"key": "B","text": "Group A Streptococcus"},{"key": "C","text": "Streptococcus viridans directly"},{"key": "D","text": "Staphylococcus aureus"}],"correct": "B","explanation": "Rheumatic fever and subsequent rheumatic heart disease result from an autoimmune cross-reaction (molecular mimicry) following group A streptococcal pharyngitis."},{"id": 4385,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which type of muscle contraction occurs when muscle tension increases without a change in muscle length?","options": [{"key": "A","text": "Isometric contraction"},{"key": "B","text": "Isotonic concentric contraction"},{"key": "C","text": "Isotonic eccentric contraction"},{"key": "D","text": "Isokinetic contraction"}],"correct": "A","explanation": "Isometric contraction generates force without joint movement or change in muscle length, useful for early-stage strengthening."},{"id": 4386,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Easy","question": "Concentric contraction is best described as:","options": [{"key": "A","text": "Muscle shortening while generating tension"},{"key": "B","text": "No change in muscle length with tension"},{"key": "C","text": "Muscle lengthening while generating tension"},{"key": "D","text": "Complete muscle relaxation"}],"correct": "A","explanation": "In concentric contraction, the muscle shortens as it develops tension to overcome resistance, e.g., the lifting phase of a bicep curl."},{"id": 4387,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Easy","question": "Eccentric contraction is best described as:","options": [{"key": "A","text": "No tension development at all"},{"key": "B","text": "Muscle shortening while generating tension"},{"key": "C","text": "Static muscle contraction without movement"},{"key": "D","text": "Muscle lengthening while generating tension to control movement"}],"correct": "D","explanation": "Eccentric contractions lengthen the muscle under tension, often used to control deceleration, as in the lowering phase of a squat."},{"id": 4388,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which type of contraction is most associated with delayed onset muscle soreness (DOMS)?","options": [{"key": "A","text": "Eccentric contraction"},{"key": "B","text": "Isometric contraction"},{"key": "C","text": "Concentric contraction only"},{"key": "D","text": "Isokinetic contraction at low speed"}],"correct": "A","explanation": "Eccentric loading causes greater microscopic muscle damage, contributing to the delayed soreness typically felt 24-72 hours post-exercise."},{"id": 4389,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Medium","question": "Isokinetic exercise is characterized by:","options": [{"key": "A","text": "Resistance only at the end of range"},{"key": "B","text": "Constant angular velocity of movement with variable resistance throughout range"},{"key": "C","text": "Constant resistance with variable speed"},{"key": "D","text": "No movement at all"}],"correct": "B","explanation": "Isokinetic devices control movement speed while accommodating resistance to match the muscle's force output through the range of motion."},{"id": 4390,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Easy","question": "Progressive resistance exercise (PRE) is based on the principle of:","options": [{"key": "A","text": "Decreasing resistance progressively over time"},{"key": "B","text": "Keeping resistance constant regardless of improvement"},{"key": "C","text": "Random variation of resistance without a systematic plan"},{"key": "D","text": "Gradually increasing resistance/load as strength improves to promote continued adaptation"}],"correct": "D","explanation": "PRE follows the overload principle, systematically increasing demand on the muscle to stimulate ongoing strength gains."},{"id": 4391,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "The DeLorme technique of progressive resistance exercise uses which loading pattern across three sets?","options": [{"key": "A","text": "Same load for all sets with increasing repetitions"},{"key": "B","text": "Random load selection each session"},{"key": "C","text": "Increasing load each set based on a percentage of 10 repetition maximum (10RM)"},{"key": "D","text": "Decreasing load each set"}],"correct": "C","explanation": "DeLorme's method progressively increases load across three sets (50%, 75%, 100% of 10RM), a classic PRE protocol."},{"id": 4392,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "The Oxford technique of progressive resistance exercise differs from DeLorme's technique in that it uses:","options": [{"key": "A","text": "No structured loading pattern"},{"key": "B","text": "Decreasing load across sets, starting with the heaviest first"},{"key": "C","text": "Constant load throughout"},{"key": "D","text": "Increasing load across sets"}],"correct": "B","explanation": "The Oxford technique reverses DeLorme's approach, starting with 100% of 10RM and decreasing load in subsequent sets to reduce fatigue-related risk."},{"id": 4393,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "Proprioceptive neuromuscular facilitation (PNF) stretching techniques primarily utilize which physiological principle?","options": [{"key": "A","text": "Autogenic inhibition and reciprocal inhibition via muscle spindle/Golgi tendon organ activity"},{"key": "B","text": "Ballistic bouncing movements"},{"key": "C","text": "Complete muscle paralysis"},{"key": "D","text": "Pure static muscle lengthening without neural involvement"}],"correct": "A","explanation": "PNF techniques like contract-relax exploit neurophysiological reflexes (via GTO and muscle spindles) to achieve greater range of motion than static stretching alone."},{"id": 4394,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "The 'contract-relax' PNF stretching technique involves:","options": [{"key": "A","text": "Contraction of the antagonist muscle only"},{"key": "B","text": "Only passive stretching without any contraction"},{"key": "C","text": "Rapid bouncing stretches"},{"key": "D","text": "An isometric contraction of the target muscle followed by relaxation and further passive stretch"}],"correct": "D","explanation": "This technique uses autogenic inhibition — contracting the tight muscle before relaxing it — to allow a deeper subsequent stretch."},{"id": 4395,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which stretching technique carries the highest risk of muscle injury due to rapid, uncontrolled movements?","options": [{"key": "A","text": "Ballistic stretching"},{"key": "B","text": "Static stretching"},{"key": "C","text": "Active isolated stretching"},{"key": "D","text": "PNF stretching"}],"correct": "A","explanation": "Ballistic stretching's rapid bouncing motions can exceed tissue extensibility limits quickly, increasing injury risk compared to controlled static or PNF methods."},{"id": 4396,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Static stretching is generally recommended to be avoided immediately before which type of activity due to potential temporary strength/power reduction?","options": [{"key": "A","text": "Post-exercise cool-down"},{"key": "B","text": "Activities requiring flexibility as the primary component"},{"key": "C","text": "Gentle rehabilitation exercises"},{"key": "D","text": "High-intensity or power-based athletic activity"}],"correct": "D","explanation": "Research suggests prolonged static stretching immediately pre-activity may transiently reduce muscle power output, making dynamic warm-ups preferable before explosive sports."},{"id": 4397,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Continuous passive motion (CPM) machines are commonly used post-operatively, especially after which type of surgery?","options": [{"key": "A","text": "Total knee replacement"},{"key": "B","text": "Simple wrist fracture casting"},{"key": "C","text": "Minor skin laceration repair"},{"key": "D","text": "Uncomplicated tendon repair without joint involvement"}],"correct": "A","explanation": "CPM devices provide controlled passive joint movement after major joint surgery like TKA, helping maintain range of motion and reduce stiffness/adhesion formation."},{"id": 4398,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Active range of motion (AROM) exercises differ from passive range of motion (PROM) in that AROM involves:","options": [{"key": "A","text": "No movement at all"},{"key": "B","text": "The therapist moving the joint without patient effort"},{"key": "C","text": "The patient actively moving the joint using their own muscle power"},{"key": "D","text": "Movement only against maximal resistance"}],"correct": "C","explanation": "AROM requires voluntary muscle contraction from the patient, useful for maintaining strength and mobility, unlike therapist-assisted PROM."},{"id": 4399,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Active-assisted range of motion (AAROM) exercises are indicated when a patient:","options": [{"key": "A","text": "Cannot tolerate any movement at all"},{"key": "B","text": "Has weak musculature and needs some external assistance to complete the movement"},{"key": "C","text": "Has full strength and needs no assistance"},{"key": "D","text": "Requires only passive movement with no active effort"}],"correct": "B","explanation": "AAROM bridges the gap between passive and active exercise, providing assistance when muscle strength is insufficient to complete full range independently."},{"id": 4400,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Frenkel's exercises are specifically designed to improve which impairment?","options": [{"key": "A","text": "Muscle bulk in hypertrophy training"},{"key": "B","text": "Cardiovascular endurance"},{"key": "C","text": "Bone density in osteoporosis"},{"key": "D","text": "Coordination deficits in patients with ataxia (e.g., cerebellar or sensory ataxia)"}],"correct": "D","explanation": "Frenkel's exercises use repetitive, precise movement patterns with visual/sensory cues to retrain coordination in ataxic patients."},{"id": 4401,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which principle underlies the use of graded exercise/activity programs in rehabilitation following injury?","options": [{"key": "A","text": "Random variation without progression logic"},{"key": "B","text": "Gradual, systematic progression of load/intensity to safely restore function without re-injury"},{"key": "C","text": "Complete avoidance of all movement indefinitely"},{"key": "D","text": "Immediate return to full pre-injury activity level"}],"correct": "B","explanation": "Graded exercise progression balances tissue healing timelines with functional restoration, minimizing re-injury risk while promoting recovery."},{"id": 4402,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Closed kinetic chain exercises, such as a squat, are characterized by:","options": [{"key": "A","text": "Isolated single-joint movement only"},{"key": "B","text": "The distal segment (e.g., foot) being fixed against a surface while the body moves"},{"key": "C","text": "Complete absence of joint loading"},{"key": "D","text": "The distal segment moving freely in space"}],"correct": "B","explanation": "CKC exercises fix the distal limb, promoting co-contraction of muscles around multiple joints and often greater joint stability, useful in early ACL rehab."},{"id": 4403,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Open kinetic chain exercises, such as a leg extension machine, are characterized by:","options": [{"key": "A","text": "The distal segment moving freely while the proximal segment is fixed"},{"key": "B","text": "The distal segment being fixed against a surface"},{"key": "C","text": "Only bilateral limb involvement"},{"key": "D","text": "No isolated joint movement occurring"}],"correct": "A","explanation": "OKC exercises allow the distal limb to move freely in space, isolating specific muscle groups, though sometimes contraindicated in early ACL reconstruction due to shear forces."},{"id": 4404,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise therapy principle states that specific types of training produce specific physiological adaptations relevant to that activity?","options": [{"key": "A","text": "Reversibility principle exclusively"},{"key": "B","text": "Overload principle exclusively"},{"key": "C","text": "Principle of individual variation exclusively"},{"key": "D","text": "SAID principle (Specific Adaptation to Imposed Demand)"}],"correct": "D","explanation": "The SAID principle guides therapists to tailor exercise programs to match the specific functional demands the patient needs to return to."},{"id": 4405,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The principle of reversibility in exercise therapy states that:","options": [{"key": "A","text": "Only elderly patients experience detraining effects"},{"key": "B","text": "Gains in strength/fitness are lost if training stops or is significantly reduced"},{"key": "C","text": "Fitness gains are permanent once achieved"},{"key": "D","text": "Reversibility only applies to cardiovascular fitness, not strength"}],"correct": "B","explanation": "Detraining effects mean therapeutic exercise gains diminish without continued training stimulus, emphasizing the importance of maintenance programs."},{"id": 4406,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Aerobic (cardiovascular) exercise training principally improves fitness through adaptations in which primary system?","options": [{"key": "A","text": "Nervous system exclusively"},{"key": "B","text": "Cardiorespiratory system (heart, lungs, and oxidative muscle metabolism)"},{"key": "C","text": "Integumentary system exclusively"},{"key": "D","text": "Skeletal system exclusively"}],"correct": "B","explanation": "Sustained aerobic training enhances cardiac output, pulmonary efficiency, and mitochondrial/oxidative capacity of skeletal muscle."},{"id": 4407,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "McKenzie method (Mechanical Diagnosis and Therapy) for spinal conditions primarily uses which type of movement assessment/treatment?","options": [{"key": "A","text": "Isolated strength testing only"},{"key": "B","text": "Repeated end-range movements to assess centralization/peripheralization of symptoms"},{"key": "C","text": "Passive modalities exclusively without active movement"},{"key": "D","text": "Only static postural correction without movement"}],"correct": "B","explanation": "The McKenzie approach uses repeated movement testing to identify directional preference, guiding a movement-based treatment strategy for spinal pain."},{"id": 4408,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Core stability training primarily targets which muscle groups to improve spinal segmental control?","options": [{"key": "A","text": "Transversus abdominis, multifidus, and other deep trunk stabilizers"},{"key": "B","text": "Only the upper trapezius"},{"key": "C","text": "Only superficial rectus abdominis"},{"key": "D","text": "Only the gluteal muscles"}],"correct": "A","explanation": "Deep stabilizing muscles like transversus abdominis and multifidus provide segmental spinal control, a key focus in low back pain rehabilitation programs."},{"id": 4409,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which is an appropriate exercise therapy consideration for a patient with acute inflammatory joint pain (e.g., active rheumatoid arthritis flare)?","options": [{"key": "A","text": "High-impact activity to 'work through' the pain"},{"key": "B","text": "Gentle range of motion exercises with rest during acute flares, avoiding aggressive strengthening"},{"key": "C","text": "Complete immobilization indefinitely even after the flare resolves"},{"key": "D","text": "Aggressive resistance training regardless of flare status"}],"correct": "B","explanation": "During acute inflammatory flares, gentle ROM exercises help maintain mobility while avoiding excessive joint stress that could worsen inflammation."},{"id": 4410,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which principle guides the appropriate progression of exercise intensity to avoid overtraining or injury?","options": [{"key": "A","text": "No progression at all throughout the rehabilitation program"},{"key": "B","text": "Rapid maximal progression regardless of symptoms"},{"key": "C","text": "Progression based solely on calendar time without reassessment"},{"key": "D","text": "Gradual, individualized progression based on patient response and tissue tolerance"}],"correct": "D","explanation": "Effective exercise prescription requires ongoing reassessment and gradual progression tailored to the individual patient's tolerance and healing stage."},{"id": 4411,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Easy","question": "Which exercise parameter is primarily manipulated to improve muscular endurance rather than maximal strength?","options": [{"key": "A","text": "Long rest periods between single heavy lifts"},{"key": "B","text": "Isometric holds only"},{"key": "C","text": "Higher repetitions with lower resistance"},{"key": "D","text": "Very low repetitions with maximal resistance"}],"correct": "C","explanation": "Endurance training protocols typically use higher rep ranges (15-20+) with lighter loads, as opposed to low-rep, high-load strength protocols."},{"id": 4412,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which exercise parameter combination is classically used for maximal strength gains?","options": [{"key": "A","text": "Very light resistance with unlimited repetitions"},{"key": "B","text": "High repetitions with low resistance"},{"key": "C","text": "No resistance with maximal speed"},{"key": "D","text": "Low repetitions (1-6) with high resistance/load"}],"correct": "D","explanation": "Strength-focused training uses heavy loads with fewer repetitions to maximize motor unit recruitment and neural adaptations."},{"id": 4413,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Plyometric exercises primarily aim to improve:","options": [{"key": "A","text": "Pure muscular endurance"},{"key": "B","text": "Flexibility exclusively"},{"key": "C","text": "Power through rapid eccentric-to-concentric muscle contraction (stretch-shortening cycle)"},{"key": "D","text": "Balance exclusively without power component"}],"correct": "C","explanation": "Plyometrics exploit the stretch-shortening cycle, storing elastic energy during rapid eccentric loading and releasing it explosively during the concentric phase."},{"id": 4414,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Before initiating plyometric training, a patient should generally have adequate:","options": [{"key": "A","text": "Only cardiovascular fitness, not musculoskeletal readiness"},{"key": "B","text": "No baseline strength requirement at all"},{"key": "C","text": "Complete absence of any previous injury history"},{"key": "D","text": "Baseline strength and joint stability to tolerate high-impact forces"}],"correct": "D","explanation": "Plyometrics generate significant joint loading forces, so adequate strength and stability are prerequisites to minimize injury risk."},{"id": 4415,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which balance training principle involves progressively reducing the base of support to increase difficulty?","options": [{"key": "A","text": "Narrowing the stance or standing on one leg to challenge postural control"},{"key": "B","text": "Only performing balance exercises while seated"},{"key": "C","text": "Widening the stance only, without progression"},{"key": "D","text": "Avoiding all balance challenges"}],"correct": "A","explanation": "Reducing base of support (e.g., tandem stance, single-leg stance) systematically increases postural control demands during balance rehabilitation."},{"id": 4416,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which sensory system's contribution can be selectively challenged during balance training by having a patient close their eyes?","options": [{"key": "A","text": "Auditory system"},{"key": "B","text": "Visual system"},{"key": "C","text": "Somatosensory system exclusively"},{"key": "D","text": "Vestibular system exclusively"}],"correct": "B","explanation": "Removing visual input forces greater reliance on vestibular and proprioceptive (somatosensory) input, a common balance training progression technique."},{"id": 4417,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Gait training with an assistive device (e.g., cane) is typically taught with the device held in which hand relative to the affected/weaker leg?","options": [{"key": "A","text": "The same hand as the affected leg"},{"key": "B","text": "Either hand makes no difference"},{"key": "C","text": "The hand opposite to the affected leg"},{"key": "D","text": "Bilateral devices are always required regardless of unilateral weakness"}],"correct": "C","explanation": "Holding a cane in the hand opposite the affected leg allows a more normal reciprocal gait pattern and effectively widens the base of support on the weak side."},{"id": 4418,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 'three-point gait pattern' with crutches is typically used for patients with which type of weight-bearing status?","options": [{"key": "A","text": "Complete bilateral non-weight-bearing status"},{"key": "B","text": "Full weight-bearing bilaterally without restriction"},{"key": "C","text": "No weight-bearing restriction of any kind"},{"key": "D","text": "Non-weight-bearing or partial weight-bearing on one leg"}],"correct": "D","explanation": "The three-point pattern (both crutches plus the unaffected leg, then the affected leg) accommodates unilateral weight-bearing restrictions."},{"id": 4419,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Therapeutic exercise dosage parameters typically include which of the following components in a prescription?","options": [{"key": "A","text": "Frequency, intensity, time (duration), and type (FITT principle)"},{"key": "B","text": "Random selection without systematic parameters"},{"key": "C","text": "Only the type of exercise without other parameters"},{"key": "D","text": "Only patient age and gender"}],"correct": "A","explanation": "The FITT principle provides a structured framework for systematically prescribing and progressing therapeutic exercise programs."},{"id": 4420,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following best describes 'muscle energy techniques' used in manual/exercise therapy?","options": [{"key": "A","text": "Techniques requiring general anesthesia"},{"key": "B","text": "Purely passive stretching without patient participation"},{"key": "C","text": "Techniques that avoid any muscle contraction entirely"},{"key": "D","text": "Techniques using voluntary patient muscle contraction against a controlled counterforce to achieve therapeutic effect"}],"correct": "D","explanation": "Muscle energy techniques utilize the patient's own controlled muscle contractions (often isometric) against therapist resistance to improve mobility or reduce muscle tension."},{"id": 4421,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Deep breathing and diaphragmatic breathing exercises are commonly incorporated into exercise therapy programs primarily to:","options": [{"key": "A","text": "Replace all other forms of exercise"},{"key": "B","text": "Increase heart rate maximally"},{"key": "C","text": "Improve ventilation efficiency and reduce accessory muscle use"},{"key": "D","text": "Have no physiological benefit beyond relaxation"}],"correct": "C","explanation": "These breathing techniques optimize respiratory mechanics, particularly valuable for patients with pulmonary conditions or post-surgical recovery."},{"id": 4422,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise therapy consideration is essential when working with a patient who has osteoporosis?","options": [{"key": "A","text": "Encourage maximal spinal flexion exercises with heavy resistance"},{"key": "B","text": "Recommend only high-impact jumping activities"},{"key": "C","text": "No precautions are needed regardless of bone density status"},{"key": "D","text": "Avoid high-impact activities and excessive spinal flexion under load to reduce fracture risk"}],"correct": "D","explanation": "Osteoporotic bone is at increased fracture risk, so exercise programs should avoid excessive spinal flexion loading and high-impact forces while still promoting weight-bearing activity for bone health."},{"id": 4423,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Weight-bearing exercise is generally recommended in osteoporosis management because it helps:","options": [{"key": "A","text": "Have no effect on skeletal health"},{"key": "B","text": "Only benefit cardiovascular fitness, not bone health"},{"key": "C","text": "Decrease bone density further"},{"key": "D","text": "Stimulate bone remodeling and maintain/improve bone mineral density"}],"correct": "D","explanation": "Mechanical loading through weight-bearing activity stimulates osteoblastic activity, helping to maintain or slow the decline of bone mineral density."},{"id": 4424,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise modification is appropriate for a patient in the early post-operative phase following rotator cuff repair?","options": [{"key": "A","text": "Immediate full active resistance training"},{"key": "B","text": "Protected passive/active-assisted range of motion within surgeon-specified limits, avoiding active resistance too early"},{"key": "C","text": "Complete immobilization with no movement for months"},{"key": "D","text": "Aggressive stretching beyond pain tolerance immediately"}],"correct": "B","explanation": "Early rotator cuff repair rehabilitation prioritizes protecting the healing tendon repair with controlled, limited motion before progressing to active strengthening."},{"id": 4425,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Functional Independence Measure (FIM) is commonly used in rehabilitation settings to assess:","options": [{"key": "A","text": "Cardiovascular fitness exclusively"},{"key": "B","text": "A patient's level of disability and need for assistance in performing daily activities"},{"key": "C","text": "Range of motion exclusively"},{"key": "D","text": "Muscle strength grading exclusively"}],"correct": "B","explanation": "FIM is a standardized outcome measure assessing physical and cognitive independence across various functional tasks in rehabilitation."},{"id": 4426,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The Borg CR10 scale differs from the original Borg RPE (6-20) scale primarily in that it:","options": [{"key": "A","text": "Uses a 0-10 category ratio scale, often easier for patients to understand"},{"key": "B","text": "Cannot be used for dyspnea assessment"},{"key": "C","text": "Only measures heart rate directly"},{"key": "D","text": "Is identical in scoring range to the original scale"}],"correct": "A","explanation": "The CR10 scale provides a simpler 0-10 range often used for rating both exertion and dyspnea, complementing the traditional 6-20 Borg scale."},{"id": 4427,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise therapy approaches would be most appropriate immediately following an acute ankle sprain (within first 48-72 hours)?","options": [{"key": "A","text": "High-intensity plyometric training immediately"},{"key": "B","text": "Protected weight-bearing as tolerated with gentle range of motion, avoiding aggressive stretching of the injured ligament"},{"key": "C","text": "Immediate aggressive stretching of the injured ligament"},{"key": "D","text": "Complete non-weight-bearing for 6 weeks regardless of severity"}],"correct": "B","explanation": "Early management focuses on protecting healing tissue while maintaining safe mobility, progressing gradually as pain and swelling subside."},{"id": 4428,"subject": "Exercise Therapy","topic": "Stretching & Flexibility","difficulty": "Medium","question": "Current general guidelines recommend holding a static stretch for approximately how long to improve flexibility?","options": [{"key": "A","text": "No specific duration matters"},{"key": "B","text": "10 minutes continuously"},{"key": "C","text": "1-2 seconds only"},{"key": "D","text": "15-30 seconds"}],"correct": "D","explanation": "Research generally supports 15-30 second static stretch holds, repeated multiple times, as effective for improving flexibility."},{"id": 4429,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "A proper exercise warm-up primarily serves to:","options": [{"key": "A","text": "Immediately maximize strength output without preparation"},{"key": "B","text": "Have no physiological benefit before activity"},{"key": "C","text": "Gradually increase muscle temperature, blood flow, and prepare the cardiovascular system for activity"},{"key": "D","text": "Replace the need for a cool-down"}],"correct": "C","explanation": "Warm-ups increase tissue temperature and blood flow, improving muscle elasticity and reducing injury risk before more vigorous activity."},{"id": 4430,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "A proper cool-down after exercise primarily helps to:","options": [{"key": "A","text": "Increase risk of post-exercise hypotension"},{"key": "B","text": "Replace the need for a warm-up in future sessions"},{"key": "C","text": "Immediately stop all physiological processes abruptly"},{"key": "D","text": "Gradually return heart rate/blood pressure to baseline and reduce blood pooling in extremities"}],"correct": "D","explanation": "Gradual cool-down prevents venous pooling and sudden blood pressure drops that can occur with abrupt cessation of vigorous exercise."},{"id": 4431,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Aquatic therapy (hydrotherapy) is particularly beneficial for patients with which condition, due to buoyancy reducing joint loading?","options": [{"key": "A","text": "Severe uncontrolled seizure disorder"},{"key": "B","text": "Osteoarthritis with painful weight-bearing"},{"key": "C","text": "Open wounds with active infection risk"},{"key": "D","text": "Uncontrolled cardiac arrhythmia"}],"correct": "B","explanation": "Water's buoyancy reduces effective body weight and joint compressive forces, allowing painful joints to move with less load, benefiting arthritis patients."},{"id": 4432,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which property of water provides resistance during aquatic exercise, useful for strengthening?","options": [{"key": "A","text": "Buoyancy alone"},{"key": "B","text": "Viscosity and drag force"},{"key": "C","text": "Water temperature alone"},{"key": "D","text": "Hydrostatic pressure alone"}],"correct": "B","explanation": "Water's viscosity creates resistance proportional to movement speed, allowing for adjustable-intensity strengthening exercises in the pool."},{"id": 4433,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Suspension therapy (e.g., using slings) is a technique that primarily uses which principle to assist or resist movement?","options": [{"key": "A","text": "Counterbalancing body segment weight through slings to modify the effective load"},{"key": "B","text": "Complete removal of gravity's effect entirely"},{"key": "C","text": "Only manual resistance from the therapist"},{"key": "D","text": "Electrical stimulation of muscles"}],"correct": "A","explanation": "Suspension therapy uses slings to support or offset limb weight, allowing graded assistance or resistance during therapeutic exercise."},{"id": 4434,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Manual resistance exercise, provided directly by the therapist's hands, offers which advantage over machine-based resistance?","options": [{"key": "A","text": "Complete elimination of therapist involvement"},{"key": "B","text": "Only usable for lower extremity exercises"},{"key": "C","text": "Ability to vary resistance in real-time based on patient's changing capability through the range"},{"key": "D","text": "Fixed, unchangeable resistance throughout the exercise"}],"correct": "C","explanation": "Manual resistance allows dynamic, responsive adjustment of force application based on immediate patient feedback and movement quality."},{"id": 4435,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Exercise prescription for pregnant patients generally recommends avoiding which position during later pregnancy due to risk of reduced venous return?","options": [{"key": "A","text": "Standing exercises"},{"key": "B","text": "Side-lying positioning"},{"key": "C","text": "Prolonged supine positioning"},{"key": "D","text": "Seated exercises"}],"correct": "C","explanation": "Prolonged supine positioning in later pregnancy can compress the inferior vena cava, reducing venous return and causing supine hypotensive syndrome."},{"id": 4436,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Pediatric exercise therapy programs must account for which developmental consideration compared to adult programs?","options": [{"key": "A","text": "Age-appropriate motor development stages and attention span, often using play-based approaches"},{"key": "B","text": "Identical protocols to adult strength training programs"},{"key": "C","text": "Only passive range of motion, never active participation"},{"key": "D","text": "No modification needed regardless of age"}],"correct": "A","explanation": "Children's therapeutic exercise must be tailored to developmental stage, often incorporating play and shorter, engaging activities to maintain participation."},{"id": 4437,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Exercise therapy for geriatric patients should particularly emphasize which components to reduce fall risk?","options": [{"key": "A","text": "Only maximal cardiovascular endurance training"},{"key": "B","text": "Complete avoidance of resistance training regardless of ability"},{"key": "C","text": "Only isolated single-joint strengthening without functional components"},{"key": "D","text": "Balance, strength, and functional mobility training"}],"correct": "D","explanation": "Given the high prevalence of falls in older adults, combined balance and strength training is a key evidence-based intervention to reduce fall risk."},{"id": 4438,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best describes 'functional exercise' in a rehabilitation context?","options": [{"key": "A","text": "Exercise focused solely on isolated muscle groups without task relevance"},{"key": "B","text": "Exercise that has no connection to the patient's goals"},{"key": "C","text": "Exercise performed only in a gym setting unrelated to daily tasks"},{"key": "D","text": "Exercise that mimics or directly trains movements needed for daily activities/occupational tasks"}],"correct": "D","explanation": "Functional exercises are designed to closely replicate the specific movement patterns and demands the patient needs for their daily life or occupation."},{"id": 4439,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "A 'home exercise program' (HEP) is important in physiotherapy rehabilitation primarily because it:","options": [{"key": "A","text": "Has no impact on treatment outcomes"},{"key": "B","text": "Reinforces gains between supervised sessions and promotes long-term adherence to exercise"},{"key": "C","text": "Replaces the need for any supervised therapy sessions entirely"},{"key": "D","text": "Is only relevant for cardiac rehabilitation patients"}],"correct": "B","explanation": "HEPs extend the therapeutic benefit beyond clinic visits, supporting continued progress and habit formation for long-term functional improvement."},{"id": 4440,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which factor is most important to assess before progressing a patient's exercise program to a more challenging level?","options": [{"key": "A","text": "The patient's current response, symptoms, and tolerance to the existing exercise level"},{"key": "B","text": "Random selection without clinical reasoning"},{"key": "C","text": "The patient's age alone, regardless of function"},{"key": "D","text": "Only the calendar date since starting therapy"}],"correct": "A","explanation": "Safe progression relies on clinical reassessment of how the patient is tolerating current exercises before advancing intensity or complexity."},{"id": 4441,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following represents an appropriate use of active-assisted exercise in the context of a patient recovering from stroke with significant hemiparesis?","options": [{"key": "A","text": "Assisting the weak limb through range while encouraging as much active patient effort as possible"},{"key": "B","text": "Avoiding movement of the weak side entirely"},{"key": "C","text": "Requiring full independent strength before any exercise begins"},{"key": "D","text": "Complete passive movement with no patient effort ever attempted"}],"correct": "A","explanation": "AAROM allows appropriate challenge for a weakened limb, encouraging neuromuscular re-education while providing needed support to complete the movement."},{"id": 4442,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Task-specific training in neurological rehabilitation (e.g., after stroke) is based on the principle that:","options": [{"key": "A","text": "Only passive range of motion produces functional recovery"},{"key": "B","text": "Generic strengthening alone is equally effective as task practice"},{"key": "C","text": "Practicing the actual functional task promotes neuroplasticity and skill relearning specific to that task"},{"key": "D","text": "Neuroplasticity does not occur in adult patients"}],"correct": "C","explanation": "Task-specific training leverages activity-dependent neuroplasticity, where repeated practice of meaningful tasks drives motor relearning more effectively than isolated non-specific exercises."},{"id": 4443,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes the 'overload principle' in exercise therapy?","options": [{"key": "A","text": "A tissue/system must be stressed beyond its accustomed level to stimulate adaptation and improvement"},{"key": "B","text": "Only cardiovascular systems respond to the overload principle"},{"key": "C","text": "Exercise intensity should always remain constant to avoid injury"},{"key": "D","text": "Reducing exercise load below baseline promotes the fastest gains"}],"correct": "A","explanation": "The overload principle is fundamental to strength and conditioning, requiring progressively greater demand than the tissue is currently accustomed to for continued adaptation."},{"id": 4444,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The principle of specificity in exercise training states that:","options": [{"key": "A","text": "Training adaptations are specific to the type of exercise, muscle groups, and energy systems used"},{"key": "B","text": "All exercises produce identical adaptations regardless of type"},{"key": "C","text": "Specificity applies only to elite athletes"},{"key": "D","text": "Only aerobic exercise produces any measurable adaptation"}],"correct": "A","explanation": "Training effects are specific to the demands imposed — for example, endurance training improves aerobic capacity while resistance training improves strength."},{"id": 4445,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best exemplifies the principle of individual variation in exercise prescription?","options": [{"key": "A","text": "Exercise response is completely uniform across all individuals"},{"key": "B","text": "Different patients may respond differently to the same exercise program based on genetics, fitness level, and health status"},{"key": "C","text": "All patients must follow an identical exercise protocol regardless of differences"},{"key": "D","text": "Individual variation only applies to age, not other factors"}],"correct": "B","explanation": "Recognizing that responses to training vary between individuals allows therapists to tailor programs for optimal, safe progress for each patient."},{"id": 4446,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Circuit training, incorporating multiple exercise stations performed in sequence, is primarily used to improve:","options": [{"key": "A","text": "Only balance without any strength component"},{"key": "B","text": "Only flexibility with no strength/endurance component"},{"key": "C","text": "A combination of muscular endurance and cardiovascular fitness"},{"key": "D","text": "Only maximal single-repetition strength"}],"correct": "C","explanation": "Circuit training's format of varied exercises with minimal rest between stations effectively challenges both muscular endurance and cardiovascular systems simultaneously."},{"id": 4447,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Interval training, alternating periods of high and low intensity exercise, is particularly effective for improving:","options": [{"key": "A","text": "Only isolated muscle strength without cardiovascular benefit"},{"key": "B","text": "Only flexibility"},{"key": "C","text": "Both aerobic and anaerobic fitness components"},{"key": "D","text": "Only balance and coordination"}],"correct": "C","explanation": "Interval training's varied intensity structure trains both aerobic and anaerobic energy systems, making it efficient for overall cardiovascular conditioning."},{"id": 4448,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "When designing an exercise program for a patient with chronic low back pain, which general principle is currently emphasized based on evidence?","options": [{"key": "A","text": "Only passive modalities without active exercise"},{"key": "B","text": "Complete avoidance of any spinal movement indefinitely"},{"key": "C","text": "Strict prolonged bed rest until complete pain resolution"},{"key": "D","text": "Encouraging early return to activity and general exercise rather than prolonged rest"}],"correct": "D","explanation": "Current evidence supports active exercise and early mobilization over prolonged rest for most chronic low back pain, improving function and reducing disability."},{"id": 4449,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important safety consideration when prescribing resistance exercise for a patient with uncontrolled hypertension?","options": [{"key": "A","text": "Encourage maximal isometric holds with breath-holding"},{"key": "B","text": "Avoid exercises involving prolonged breath-holding (Valsalva maneuver) which can spike blood pressure further"},{"key": "C","text": "No blood pressure monitoring is needed during resistance training"},{"key": "D","text": "Prescribe only maximal effort lifts regardless of BP status"}],"correct": "B","explanation": "The Valsalva maneuver during heavy resistance exercise can cause dangerous acute blood pressure spikes, requiring caution in hypertensive patients with proper breathing technique instruction."},{"id": 4450,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Easy","question": "Which breathing pattern is generally recommended during the concentric (lifting) phase of a resistance exercise to avoid excessive blood pressure elevation?","options": [{"key": "A","text": "Inhaling forcefully only during lifting"},{"key": "B","text": "Exhaling during the exertion (lifting) phase"},{"key": "C","text": "No specific breathing pattern matters at all"},{"key": "D","text": "Holding the breath throughout the entire lift"}],"correct": "B","explanation": "Exhaling during the effort phase helps avoid the Valsalva maneuver's blood pressure-elevating effects, an important safety teaching point in exercise prescription."},{"id": 4451,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following exercise modifications would be appropriate for a patient with significant balance impairment during early gait rehabilitation?","options": [{"key": "A","text": "Immediately progressing to unsupported single-limb activities"},{"key": "B","text": "Practicing only in completely dark environments"},{"key": "C","text": "Providing parallel bars or an assistive device with close supervision"},{"key": "D","text": "Avoiding any weight-bearing or gait practice at all"}],"correct": "C","explanation": "Providing external support and supervision during early gait training reduces fall risk while allowing the patient to practice functional movement safely."},{"id": 4452,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which outcome measure is commonly used in physiotherapy to assess a patient's dynamic balance and fall risk through a series of functional tasks?","options": [{"key": "A","text": "Goniometric range of motion measurement"},{"key": "B","text": "Visual Analog Scale (pain)"},{"key": "C","text": "Manual muscle testing grade"},{"key": "D","text": "Berg Balance Scale"}],"correct": "D","explanation": "The Berg Balance Scale assesses functional balance across 14 tasks and is widely used to identify fall risk in various patient populations."},{"id": 4453,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Timed Up and Go (TUG) test is used clinically to assess:","options": [{"key": "A","text": "Pulmonary function exclusively"},{"key": "B","text": "Cognitive function exclusively"},{"key": "C","text": "Functional mobility, balance, and fall risk based on time to stand, walk, turn, and sit"},{"key": "D","text": "Isolated upper limb strength only"}],"correct": "C","explanation": "The TUG test provides a quick, practical measure of functional mobility and is a validated predictor of fall risk in older adults and various patient populations."},{"id": 4454,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Easy","question": "Manual muscle testing (MMT) grades muscle strength on which commonly used numeric scale?","options": [{"key": "A","text": "A pass/fail binary scale only"},{"key": "B","text": "0 to 10"},{"key": "C","text": "0 to 5 (Medical Research Council scale)"},{"key": "D","text": "1 to 100 percent"}],"correct": "C","explanation": "The MRC 0-5 grading scale is the standard clinical method for documenting manual muscle strength testing findings in physiotherapy practice."},{"id": 4455,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "On manual muscle testing, a grade of 3/5 indicates that the patient can:","options": [{"key": "A","text": "Move only with gravity eliminated"},{"key": "B","text": "Move the joint through full range against gravity but not against any additional resistance"},{"key": "C","text": "Show only a muscle contraction with no joint movement at all"},{"key": "D","text": "Move the joint through full range against gravity and resistance"}],"correct": "B","explanation": "Grade 3 reflects the ability to complete full active range against gravity alone, without tolerating manual resistance, a key threshold in strength grading."},{"id": 4456,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "A manual muscle test grade of 2/5 indicates:","options": [{"key": "A","text": "Full range against gravity but not resistance"},{"key": "B","text": "Full range of motion achieved only with gravity eliminated (e.g., in a horizontal plane)"},{"key": "C","text": "No muscle contraction detectable at all"},{"key": "D","text": "Full range against gravity and moderate resistance"}],"correct": "B","explanation": "Grade 2 requires positioning the limb to remove gravitational resistance, as the muscle cannot yet overcome gravity's effect on its own."},{"id": 4457,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "A manual muscle test grade of 4/5 indicates that the patient can move against gravity and:","options": [{"key": "A","text": "Maximal resistance identical to a normal 5/5 muscle"},{"key": "B","text": "Moderate resistance, though less than normal strength"},{"key": "C","text": "Only gravity-eliminated positioning"},{"key": "D","text": "No resistance at all"}],"correct": "B","explanation": "Grade 4 reflects good but not full strength, tolerating some manual resistance while being weaker than a normal (Grade 5) muscle."},{"id": 4458,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Goniometry is the clinical tool used to measure:","options": [{"key": "A","text": "Joint range of motion in degrees"},{"key": "B","text": "Balance performance"},{"key": "C","text": "Muscle strength grade"},{"key": "D","text": "Cardiovascular endurance"}],"correct": "A","explanation": "A goniometer quantifies joint angles, providing an objective measurement of active or passive range of motion during assessment."},{"id": 4459,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "When measuring range of motion with a goniometer, the stationary arm of the device is typically aligned with:","options": [{"key": "A","text": "Neither segment, only the joint axis"},{"key": "B","text": "The distal segment only"},{"key": "C","text": "The proximal segment of the joint being measured"},{"key": "D","text": "A completely arbitrary external landmark"}],"correct": "C","explanation": "Proper goniometric technique aligns the stationary arm with the proximal bony segment and the moving arm with the distal segment, centered at the joint axis."},{"id": 4460,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "A capsular pattern of restricted motion at a joint suggests which type of underlying pathology?","options": [{"key": "A","text": "Pure muscle strain without joint involvement"},{"key": "B","text": "Arthritic or capsular joint restriction affecting the entire joint capsule"},{"key": "C","text": "Isolated ligament sprain only"},{"key": "D","text": "Nerve entrapment exclusively"}],"correct": "B","explanation": "Capsular patterns reflect proportional restriction across multiple movements at a joint, characteristic of conditions like osteoarthritis or capsulitis affecting the whole capsule."},{"id": 4461,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes a 'non-capsular' pattern of joint restriction, as opposed to a capsular pattern?","options": [{"key": "A","text": "Restriction affecting all movements equally"},{"key": "B","text": "Restriction limited to specific movements not following the proportional capsular ratio, suggesting other pathology like internal derangement"},{"key": "C","text": "Complete absence of any movement restriction"},{"key": "D","text": "Only seen in advanced arthritis"}],"correct": "B","explanation": "Non-capsular patterns (e.g., from a loose body or meniscal tear) show selective movement limitation, helping differentiate the underlying pathology from capsular restriction."},{"id": 4462,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Passive range of motion exercises are particularly indicated in early rehabilitation when a patient:","options": [{"key": "A","text": "Should never receive any therapeutic exercise"},{"key": "B","text": "Has an acute unstable fracture that should not be moved at all"},{"key": "C","text": "Has full active strength and needs no assistance"},{"key": "D","text": "Cannot yet actively move the joint due to pain, weakness, or paralysis, but movement is needed to maintain tissue mobility"}],"correct": "D","explanation": "PROM helps maintain joint and soft tissue mobility, prevent contracture, and provide sensory input when active movement is not yet possible or appropriate."},{"id": 4463,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is a potential adverse effect of prolonged, complete immobilization of a joint that exercise therapy aims to prevent?","options": [{"key": "A","text": "Improved muscle strength"},{"key": "B","text": "Joint contracture and cartilage degeneration"},{"key": "C","text": "Enhanced cardiovascular fitness"},{"key": "D","text": "Increased joint range of motion"}],"correct": "B","explanation": "Extended immobilization leads to soft tissue shortening (contracture) and can accelerate cartilage degeneration from lack of normal joint nutrition/movement."},{"id": 4464,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Which of the following best describes the purpose of joint mobilization techniques (e.g., Maitland grades) often used alongside exercise therapy?","options": [{"key": "A","text": "Restoring normal accessory joint movement (roll, glide, spin) to improve overall joint mobility and reduce pain"},{"key": "B","text": "Only used for strengthening muscles, not joint mobility"},{"key": "C","text": "Solely for cardiovascular conditioning"},{"key": "D","text": "Complete joint fusion"}],"correct": "A","explanation": "Joint mobilizations target the accessory motions within a joint that are not under voluntary control, complementing exercise therapy in restoring functional range of motion."},{"id": 4465,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes appropriate exercise progression after ACL reconstruction during the early phase (weeks 0-2)?","options": [{"key": "A","text": "Immediate return to running and pivoting sports"},{"key": "B","text": "Complete immobilization with no exercise at all"},{"key": "C","text": "Aggressive open-chain resistance exercise at maximum load"},{"key": "D","text": "Focus on controlling swelling, achieving full knee extension, and gentle quadriceps activation"}],"correct": "D","explanation": "Early ACL rehab prioritizes protecting the graft while restoring extension and preventing quadriceps atrophy, before progressing to more demanding exercises."},{"id": 4466,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Quadriceps setting exercises, a common early post-operative knee exercise, involve:","options": [{"key": "A","text": "Eccentric loading through full range"},{"key": "B","text": "Passive knee flexion only"},{"key": "C","text": "Full active knee extension against resistance"},{"key": "D","text": "An isometric contraction of the quadriceps without joint movement"}],"correct": "D","explanation": "Quad sets are a safe, early isometric exercise to activate the quadriceps muscle without stressing a healing joint or graft through movement."},{"id": 4467,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Straight leg raise (SLR) exercises are commonly used early in rehabilitation to strengthen which muscle group without significant knee joint stress?","options": [{"key": "A","text": "Gastrocnemius exclusively"},{"key": "B","text": "Hip flexors and quadriceps (isometrically stabilizing the knee)"},{"key": "C","text": "Gluteal muscles exclusively"},{"key": "D","text": "Hamstrings exclusively"}],"correct": "B","explanation": "SLR exercises engage the quadriceps isometrically to stabilize the knee while primarily working hip flexor strength, useful when knee joint movement is limited."},{"id": 4468,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which precaution is important before initiating a straight leg raise exercise post knee surgery?","options": [{"key": "A","text": "Avoiding any hip flexion movement at all times"},{"key": "B","text": "Ensuring the patient can achieve an adequate quadriceps contraction to prevent a knee extensor lag"},{"key": "C","text": "No precaution needed regardless of quadriceps strength"},{"key": "D","text": "Ensuring maximum external resistance is applied immediately"}],"correct": "B","explanation": "Without sufficient quadriceps activation, attempting SLR can result in an extensor lag (inability to maintain full knee extension during the lift), reducing exercise effectiveness."},{"id": 4469,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Scapular stabilization exercises are particularly important in the rehabilitation of which condition?","options": [{"key": "A","text": "Isolated ankle sprain"},{"key": "B","text": "Shoulder impingement syndrome and rotator cuff pathology"},{"key": "C","text": "Lumbar disc herniation exclusively"},{"key": "D","text": "Carpal tunnel syndrome exclusively"}],"correct": "B","explanation": "Poor scapular control/positioning contributes to altered shoulder mechanics and impingement, making scapular stabilization a key component of shoulder rehabilitation programs."},{"id": 4470,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which exercise is commonly used to strengthen the gluteus medius, important for correcting a Trendelenburg gait pattern?","options": [{"key": "A","text": "Standing calf raises"},{"key": "B","text": "Side-lying hip abduction"},{"key": "C","text": "Seated knee extension"},{"key": "D","text": "Prone knee flexion"}],"correct": "B","explanation": "Side-lying hip abduction directly targets the gluteus medius, the primary hip stabilizer whose weakness causes a Trendelenburg gait pattern."},{"id": 4471,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Bridging exercises (supine hip extension) primarily strengthen which muscle group, useful in low back and pelvic rehabilitation?","options": [{"key": "A","text": "Anterior tibialis exclusively"},{"key": "B","text": "Quadriceps exclusively"},{"key": "C","text": "Gluteal muscles and hamstrings"},{"key": "D","text": "Biceps brachii"}],"correct": "C","explanation": "Bridging engages the posterior chain, particularly the glutes and hamstrings, important for pelvic stability and lumbar spine support."},{"id": 4472,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise position is typically used to isolate and strengthen the hip flexors while minimizing lumbar spine stress?","options": [{"key": "A","text": "Standing with excessive lumbar extension"},{"key": "B","text": "Side-lying hip abduction"},{"key": "C","text": "Prone position with hip extension"},{"key": "D","text": "Supine with the lumbar spine stabilized (e.g., posterior pelvic tilt) during hip flexion"}],"correct": "D","explanation": "Stabilizing the lumbar spine during hip flexor exercises prevents compensatory lumbar hyperextension, protecting the low back while isolating the target muscle."},{"id": 4473,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Wall slides or wall squats are commonly used therapeutic exercises to strengthen which muscle group with reduced patellofemoral joint stress compared to deep squats?","options": [{"key": "A","text": "Quadriceps (in a limited, controlled range)"},{"key": "B","text": "Hamstrings exclusively"},{"key": "C","text": "Gastrocnemius exclusively"},{"key": "D","text": "Deltoid"}],"correct": "A","explanation": "Wall slides allow controlled quadriceps strengthening through a limited range, often better tolerated in patients with patellofemoral pain than full-depth squats."},{"id": 4474,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Codman's (pendulum) exercises are commonly prescribed early after shoulder injury or surgery primarily to:","options": [{"key": "A","text": "Completely immobilize the shoulder joint"},{"key": "B","text": "Provide maximal strengthening resistance"},{"key": "C","text": "Replace the need for any formal rehabilitation program"},{"key": "D","text": "Promote gentle passive joint movement and reduce stiffness using gravity-assisted momentum"}],"correct": "D","explanation": "Pendulum exercises use gravity and body momentum to gently mobilize the shoulder joint with minimal muscular effort, useful very early in rehabilitation."},{"id": 4475,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which exercise therapy technique uses rhythmic, alternating resistance applied by the therapist to improve coordination and stability around a joint?","options": [{"key": "A","text": "Isolated isotonic strengthening only"},{"key": "B","text": "Passive range of motion exclusively"},{"key": "C","text": "Static stretching only"},{"key": "D","text": "Rhythmic stabilization (a PNF technique)"}],"correct": "D","explanation": "Rhythmic stabilization applies alternating isometric resistance in different directions, challenging co-contraction and joint stability, a PNF-based technique."},{"id": 4476,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Which of the following best describes 'D1' and 'D2' patterns used in PNF exercise techniques?","options": [{"key": "A","text": "Diagonal movement patterns combining multiple joint motions to mimic functional movement"},{"key": "B","text": "Techniques used only for the lower extremity"},{"key": "C","text": "Purely single-plane, single-joint isolated movements"},{"key": "D","text": "Static positions without any movement"}],"correct": "A","explanation": "PNF diagonal patterns (D1, D2) combine flexion/extension with rotation and ab/adduction across multiple joints, closely mimicking natural functional movement patterns."},{"id": 4477,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following outcome measures is used to assess a patient's self-reported level of disability specifically related to low back pain?","options": [{"key": "A","text": "Goniometry"},{"key": "B","text": "Oswestry Disability Index"},{"key": "C","text": "Manual muscle testing"},{"key": "D","text": "Berg Balance Scale"}],"correct": "B","explanation": "The Oswestry Disability Index is a validated, widely-used questionnaire assessing functional limitation specifically due to low back pain."},{"id": 4478,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The DASH (Disabilities of the Arm, Shoulder, and Hand) questionnaire is used to assess:","options": [{"key": "A","text": "Patient-reported functional limitation and symptoms related to upper extremity conditions"},{"key": "B","text": "Cognitive function only"},{"key": "C","text": "Lower extremity balance only"},{"key": "D","text": "Cardiovascular fitness only"}],"correct": "A","explanation": "The DASH is a self-report outcome measure capturing the impact of upper limb musculoskeletal conditions on daily function."},{"id": 4479,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following is a key component of an effective patient education strategy when initiating a new home exercise program?","options": [{"key": "A","text": "Skipping education entirely to save time"},{"key": "B","text": "Providing only verbal instructions without any demonstration"},{"key": "C","text": "Clear demonstration, written/visual instructions, and verification of correct technique through teach-back"},{"key": "D","text": "Assuming the patient will independently research correct technique"}],"correct": "C","explanation": "Effective patient education combines demonstration, written materials, and confirmation of understanding to maximize safe, correct home exercise performance and adherence."},{"id": 4480,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise therapy consideration is important when treating a patient with peripheral neuropathy and reduced foot sensation?","options": [{"key": "A","text": "Ignoring any skin changes since sensation is already impaired"},{"key": "B","text": "No special footwear or inspection precautions needed"},{"key": "C","text": "Encouraging barefoot high-impact running"},{"key": "D","text": "Regular skin inspection and avoiding high-impact activities that risk unnoticed trauma"}],"correct": "D","explanation": "Reduced protective sensation increases risk of unnoticed injury, so exercise programs must incorporate skin checks and appropriate footwear/activity selection."},{"id": 4481,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes the concept of 'motor learning' as applied in exercise therapy for neurological rehabilitation?","options": [{"key": "A","text": "Purely passive observation without any active practice"},{"key": "B","text": "A concept relevant only to healthy athletes, not patients with neurological impairment"},{"key": "C","text": "The process by which practice and experience lead to relatively permanent changes in the capability for movement"},{"key": "D","text": "A one-time instructional session with no practice required"}],"correct": "C","explanation": "Motor learning theory underpins neurorehabilitation, emphasizing that repeated, meaningful practice drives lasting improvements in movement capability."},{"id": 4482,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Blocked practice versus random practice are two approaches in motor learning; random practice is generally believed to promote:","options": [{"key": "A","text": "Better long-term retention and transfer of skills despite slower initial acquisition"},{"key": "B","text": "No difference in learning outcomes compared to blocked practice"},{"key": "C","text": "Only applicable to non-clinical athletic training"},{"key": "D","text": "Faster initial performance with poor long-term retention"}],"correct": "A","explanation": "Random practice (varying tasks) creates more contextual interference during learning, which, despite appearing less efficient initially, tends to produce better retention and transfer."},{"id": 4483,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Feedback provided during exercise therapy (e.g., verbal cues, visual feedback from a mirror) primarily serves to:","options": [{"key": "A","text": "Help the patient understand and correct movement errors to improve performance"},{"key": "B","text": "Only benefit patients with intact cognition, never those with impairment"},{"key": "C","text": "Have no effect on motor skill acquisition"},{"key": "D","text": "Replace the need for active patient participation"}],"correct": "A","explanation": "Appropriate feedback helps patients recognize movement errors and make corrections, an essential component of motor skill acquisition during rehabilitation."},{"id": 4484,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes an appropriate physiotherapy approach for a patient presenting with acute, severe, unremitting back pain accompanied by saddle anesthesia and bladder dysfunction?","options": [{"key": "A","text": "Immediate medical/surgical referral due to possible cauda equina syndrome, deferring routine exercise therapy"},{"key": "B","text": "Reassure the patient and continue routine exercise as planned"},{"key": "C","text": "Begin an aggressive standard low back exercise program immediately"},{"key": "D","text": "Apply only passive stretching without further evaluation"}],"correct": "A","explanation": "Saddle anesthesia with bladder dysfunction are red flag symptoms suggesting cauda equina syndrome, a surgical emergency requiring urgent referral rather than routine exercise therapy."},{"id": 4485,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The energy system predominantly used during the first few seconds of maximal effort exercise is:","options": [{"key": "A","text": "Aerobic oxidative system"},{"key": "B","text": "Anaerobic glycolysis primarily"},{"key": "C","text": "None, energy is stored only in glucose"},{"key": "D","text": "ATP-PCr (phosphagen) system"}],"correct": "D","explanation": "The phosphagen system provides immediate, short-duration energy (0-10 seconds) via stored ATP and phosphocreatine."},{"id": 4486,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Anaerobic glycolysis becomes the predominant energy system during activities lasting approximately:","options": [{"key": "A","text": "10 seconds to 2 minutes"},{"key": "B","text": "Only during complete rest"},{"key": "C","text": "More than 10 minutes"},{"key": "D","text": "Less than 5 seconds"}],"correct": "A","explanation": "Anaerobic glycolysis fuels moderate-to-high intensity efforts of intermediate duration, producing lactate as a byproduct."},{"id": 4487,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The aerobic (oxidative) energy system becomes dominant during activities lasting longer than approximately:","options": [{"key": "A","text": "2-3 minutes"},{"key": "B","text": "Less than 10 seconds"},{"key": "C","text": "Never becomes dominant"},{"key": "D","text": "Only during isometric holds"}],"correct": "A","explanation": "Sustained, lower-intensity activity relies increasingly on aerobic metabolism as duration extends beyond a few minutes."},{"id": 4488,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "VO2 max is best defined as:","options": [{"key": "A","text": "Total lung capacity"},{"key": "B","text": "Resting oxygen consumption"},{"key": "C","text": "Maximum heart rate achievable"},{"key": "D","text": "The maximum rate of oxygen consumption during maximal exertion"}],"correct": "D","explanation": "VO2 max reflects the body's maximum capacity to transport and utilize oxygen during intense exercise, a key indicator of aerobic fitness."},{"id": 4489,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which physiological adaptation occurs with regular aerobic endurance training?","options": [{"key": "A","text": "Reduced oxidative enzyme activity"},{"key": "B","text": "Decreased capillary density"},{"key": "C","text": "Decreased stroke volume"},{"key": "D","text": "Increased mitochondrial density and capillarization in skeletal muscle"}],"correct": "D","explanation": "Chronic aerobic training enhances the muscle's oxidative capacity through increased mitochondria and capillary networks, improving endurance performance."},{"id": 4490,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Cardiac output is calculated as the product of:","options": [{"key": "A","text": "Heart rate and stroke volume"},{"key": "B","text": "Stroke volume and blood pressure"},{"key": "C","text": "Blood pressure and heart rate"},{"key": "D","text": "Respiratory rate and tidal volume"}],"correct": "A","explanation": "Cardiac output (HR x SV) determines the total blood volume pumped per minute, a key determinant of exercise capacity."},{"id": 4491,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which training adaptation increases stroke volume, contributing to a lower resting heart rate in trained individuals?","options": [{"key": "A","text": "Decreased myocardial contractility"},{"key": "B","text": "Reduced venous return"},{"key": "C","text": "Increased peripheral vascular resistance only"},{"key": "D","text": "Increased ventricular chamber size/contractility from endurance training"}],"correct": "D","explanation": "Endurance training enhances cardiac remodeling (larger, more efficient ventricles), allowing greater stroke volume and thus lower resting heart rate for the same cardiac output."},{"id": 4492,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 'training effect' or improvement in fitness occurs due to which fundamental physiological principle?","options": [{"key": "A","text": "Random, unstructured activity"},{"key": "B","text": "Constant exercise without any rest"},{"key": "C","text": "Complete avoidance of any physical stress"},{"key": "D","text": "Supercompensation following an adequate training stimulus and recovery period"}],"correct": "D","explanation": "Supercompensation describes the body's adaptive response exceeding baseline fitness following appropriate training stress and sufficient recovery."},{"id": 4493,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following muscle fiber types is best suited for sustained, low-intensity aerobic activity due to high oxidative capacity?","options": [{"key": "A","text": "Type I (slow-twitch) fibers"},{"key": "B","text": "Type IIx (fast-twitch, glycolytic) fibers"},{"key": "C","text": "Cardiac muscle fibers only"},{"key": "D","text": "Type IIb fibers exclusively"}],"correct": "A","explanation": "Type I fibers have high mitochondrial density and oxidative enzyme activity, making them fatigue-resistant and suited for endurance activities."},{"id": 4494,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Type II (fast-twitch) muscle fibers are best suited for which type of activity?","options": [{"key": "A","text": "Short-duration, high-intensity, powerful movements"},{"key": "B","text": "Postural stabilization exclusively"},{"key": "C","text": "Sustained, low-intensity endurance activity"},{"key": "D","text": "Only isometric holding without movement"}],"correct": "A","explanation": "Type II fibers generate force rapidly but fatigue quickly, making them ideal for explosive, high-intensity efforts rather than sustained activity."},{"id": 4495,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Muscle hypertrophy in response to resistance training primarily results from:","options": [{"key": "A","text": "Loss of muscle fiber size"},{"key": "B","text": "Increased size of individual muscle fibers due to increased protein synthesis"},{"key": "C","text": "Decreased protein synthesis"},{"key": "D","text": "Increased number of muscle fibers (hyperplasia) as the primary mechanism"}],"correct": "B","explanation": "Resistance training primarily increases the cross-sectional area of existing muscle fibers through enhanced myofibrillar protein synthesis."},{"id": 4496,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Neural adaptations, rather than muscle hypertrophy, are primarily responsible for strength gains observed during which phase of a resistance training program?","options": [{"key": "A","text": "Never occur; strength gains are purely hypertrophy-driven"},{"key": "B","text": "Only after several years of training"},{"key": "C","text": "Only in elderly populations"},{"key": "D","text": "The initial weeks of training (before significant hypertrophy occurs)"}],"correct": "D","explanation": "Early strength gains largely reflect improved motor unit recruitment and neural efficiency, preceding measurable muscle hypertrophy which develops over subsequent weeks."},{"id": 4497,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Which physiological mechanism explains the initial rapid strength gains seen in resistance training programs, particularly relevant to early rehabilitation?","options": [{"key": "A","text": "Complete muscle fiber type conversion within the first week"},{"key": "B","text": "Tendon lengthening"},{"key": "C","text": "Improved motor unit recruitment and synchronization"},{"key": "D","text": "Muscle fiber hyperplasia occurring within days"}],"correct": "C","explanation": "Enhanced neural drive and motor unit recruitment efficiency account for rapid early strength improvements before structural muscle changes occur."},{"id": 4498,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The 'all-or-none' principle in muscle physiology states that:","options": [{"key": "A","text": "A motor unit's muscle fibers either fully contract or do not contract at all in response to a stimulus"},{"key": "B","text": "Muscle fibers can partially contract based on stimulus strength"},{"key": "C","text": "Only the largest motor units are ever recruited"},{"key": "D","text": "Muscle contraction force is always graded and never absolute"}],"correct": "A","explanation": "Individual muscle fibers within a motor unit follow the all-or-none law; graded force output overall results from varying motor unit recruitment, not partial fiber contraction."},{"id": 4499,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The size principle of motor unit recruitment states that:","options": [{"key": "A","text": "Motor unit recruitment order is random"},{"key": "B","text": "Smaller, lower-threshold motor units (Type I) are recruited before larger, higher-threshold units (Type II) as force demand increases"},{"key": "C","text": "Only Type II units are ever recruited during any activity"},{"key": "D","text": "Larger motor units are always recruited first regardless of force needed"}],"correct": "B","explanation": "The size principle describes an orderly recruitment pattern from smaller/fatigue-resistant to larger/powerful motor units as force requirements increase, important for understanding graded exercise progression."},{"id": 4500,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Detraining effects on cardiovascular fitness typically begin to manifest after approximately what period of training cessation?","options": [{"key": "A","text": "Immediately within hours"},{"key": "B","text": "Detraining never occurs regardless of time"},{"key": "C","text": "1-2 weeks"},{"key": "D","text": "Several years"}],"correct": "C","explanation": "Measurable declines in cardiovascular fitness parameters can begin within just 1-2 weeks of significantly reduced or stopped training."},{"id": 4501,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following best describes 'periodization' in exercise program design?","options": [{"key": "A","text": "Keeping every training variable completely constant year-round"},{"key": "B","text": "A concept applicable only to elite athletes, never in rehabilitation"},{"key": "C","text": "Systematic variation of training variables (volume, intensity) over planned time periods to optimize adaptation and prevent overtraining"},{"key": "D","text": "Random, unplanned variation of exercises without structure"}],"correct": "C","explanation": "Periodization structures training phases to balance progressive overload with adequate recovery, applicable in both athletic training and rehabilitation progression planning."},{"id": 4502,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Delayed onset muscle soreness (DOMS) typically peaks at approximately which time point after unaccustomed exercise?","options": [{"key": "A","text": "Immediately during the exercise itself"},{"key": "B","text": "DOMS never has a defined time course"},{"key": "C","text": "Only after 2 weeks"},{"key": "D","text": "24-72 hours post-exercise"}],"correct": "D","explanation": "DOMS results from microtrauma (especially with eccentric loading), with peak soreness typically occurring 24-72 hours after the causative exercise session."},{"id": 4503,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an appropriate management strategy for DOMS, based on current evidence?","options": [{"key": "A","text": "Gentle activity/light exercise and gradual return to normal training, avoiding harsh treatments"},{"key": "B","text": "Aggressive deep tissue massage causing significant additional pain"},{"key": "C","text": "Prolonged complete immobilization until soreness completely resolves"},{"key": "D","text": "Ice baths as the only definitively proven effective treatment"}],"correct": "A","explanation": "Light activity and gradual progression are generally well-tolerated for DOMS management, while evidence for many specific interventions remains limited/mixed."},{"id": 4504,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The term 'exercise-induced muscle damage' primarily refers to microscopic damage occurring predominantly with which type of muscle action?","options": [{"key": "A","text": "Eccentric muscle actions"},{"key": "B","text": "Complete muscle relaxation"},{"key": "C","text": "Isometric holds exclusively at low intensity"},{"key": "D","text": "Concentric muscle actions exclusively"}],"correct": "A","explanation": "Eccentric loading, where muscle lengthens under tension, causes greater mechanical stress and microscopic damage to muscle fibers compared to concentric or isometric actions."},{"id": 4505,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes 'auto-assisted' range of motion exercise?","options": [{"key": "A","text": "No assistance of any kind is used"},{"key": "B","text": "The therapist provides all movement assistance"},{"key": "C","text": "Only machines can provide auto-assistance"},{"key": "D","text": "The patient uses the unaffected limb or a device to assist movement of the affected limb"}],"correct": "D","explanation": "Auto-assisted ROM allows patients to independently assist their affected limb using the opposite limb, a wand, or pulley system, promoting self-management."},{"id": 4506,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Pulley exercises are a common form of which type of range of motion exercise for the shoulder?","options": [{"key": "A","text": "Plyometric exercise"},{"key": "B","text": "Auto-assisted active range of motion"},{"key": "C","text": "Purely passive range of motion by the therapist"},{"key": "D","text": "Isokinetic resistance exercise"}],"correct": "B","explanation": "Overhead pulley systems allow patients to use their stronger arm to assist movement of the weaker/affected shoulder through an available range."},{"id": 4507,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which is an important precaution when performing passive range of motion on a joint with significant osteoporosis?","options": [{"key": "A","text": "Applying maximal force to achieve full range quickly"},{"key": "B","text": "Using gentle, controlled forces to avoid fracture risk from excessive force application"},{"key": "C","text": "No precautions are necessary regardless of bone density"},{"key": "D","text": "Avoiding all joint movement permanently"}],"correct": "B","explanation": "Fragile osteoporotic bone requires gentle handling during PROM to minimize fracture risk while still working to maintain joint mobility."},{"id": 4508,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercises would be classified as a closed kinetic chain exercise for the upper extremity?","options": [{"key": "A","text": "Bicep curl with a dumbbell"},{"key": "B","text": "Seated tricep extension with a cable machine"},{"key": "C","text": "Shoulder external rotation with a resistance band, arm free in space"},{"key": "D","text": "Push-up against a wall or floor"}],"correct": "D","explanation": "A push-up fixes the hand against a surface while the body moves, meeting the definition of a closed kinetic chain exercise for the upper extremity."},{"id": 4509,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following is a key rationale for using closed kinetic chain exercises early in ACL rehabilitation compared to open kinetic chain knee extension?","options": [{"key": "A","text": "CKC exercises always generate more shear force than OKC exercises"},{"key": "B","text": "There is no biomechanical difference between CKC and OKC exercises"},{"key": "C","text": "OKC exercises are always safer regardless of the healing phase"},{"key": "D","text": "CKC exercises generate less anterior tibial shear force on the healing ACL graft"}],"correct": "D","explanation": "Closed chain exercises like squats produce co-contraction of hamstrings and quadriceps, reducing anterior tibial translation forces compared to isolated open-chain quad exercises, protecting the healing ACL graft."},{"id": 4510,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Static stretching, held without movement, is generally contrasted with dynamic stretching, which involves:","options": [{"key": "A","text": "Only passive movement by a therapist"},{"key": "B","text": "Rapid uncontrolled bouncing movements"},{"key": "C","text": "Complete absence of any movement"},{"key": "D","text": "Controlled, active movements through a range of motion, often used in warm-ups"}],"correct": "D","explanation": "Dynamic stretching uses controlled active movement through increasing ranges, commonly incorporated into warm-up routines before activity, as opposed to static holds."},{"id": 4511,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following stretching approaches is generally preferred immediately prior to activities requiring maximal power output, based on current evidence?","options": [{"key": "A","text": "Prolonged static stretching (over 60 seconds per muscle)"},{"key": "B","text": "No warm-up or stretching at all"},{"key": "C","text": "Dynamic stretching/warm-up movements"},{"key": "D","text": "Ballistic stretching exclusively"}],"correct": "C","explanation": "Dynamic stretching prepares muscles for activity without the potential transient strength/power reduction associated with prolonged static stretching immediately pre-performance."},{"id": 4512,"subject": "Exercise Therapy","topic": "Stretching & Flexibility","difficulty": "Easy","question": "Which muscle group is commonly targeted with a standing calf stretch against a wall, useful for patients with limited ankle dorsiflexion?","options": [{"key": "A","text": "Hamstrings"},{"key": "B","text": "Quadriceps"},{"key": "C","text": "Hip flexors"},{"key": "D","text": "Gastrocnemius and soleus"}],"correct": "D","explanation": "The classic wall calf stretch targets the posterior lower leg muscles (gastrocnemius/soleus), commonly tight in conditions limiting ankle dorsiflexion like plantar fasciitis."},{"id": 4513,"subject": "Exercise Therapy","topic": "Stretching & Flexibility","difficulty": "Easy","question": "A hamstring stretch performed with the knee extended and hip flexed (e.g., straight leg raise stretch) primarily targets:","options": [{"key": "A","text": "Only the gastrocnemius"},{"key": "B","text": "Only the hip flexors"},{"key": "C","text": "The hamstring muscle group across both hip and knee joints"},{"key": "D","text": "Only the quadriceps"}],"correct": "C","explanation": "Since hamstrings cross both the hip and knee, stretching with hip flexion and knee extension maximally lengthens this two-joint muscle group."},{"id": 4514,"subject": "Exercise Therapy","topic": "Stretching & Flexibility","difficulty": "Hard","question": "Which stretching technique specifically utilizes contraction of the antagonist muscle to facilitate relaxation and stretch of the target (agonist) muscle via reciprocal inhibition?","options": [{"key": "A","text": "Agonist contraction-relax PNF technique (also called 'contract-relax-antagonist-contract' in some protocols)"},{"key": "B","text": "Passive stretching by a machine only"},{"key": "C","text": "Static stretching without any muscle contraction"},{"key": "D","text": "Ballistic stretching"}],"correct": "A","explanation": "Certain PNF variations use antagonist muscle contraction to reflexively inhibit the tight agonist muscle, potentially allowing a deeper stretch through reciprocal inhibition."},{"id": 4515,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes appropriate progression of resistance exercise intensity for a beginner patient in a rehabilitation program?","options": [{"key": "A","text": "Starting with lower resistance/higher repetitions and gradually increasing load as tolerated and strength improves"},{"key": "B","text": "Beginning immediately with maximal resistance regardless of baseline fitness"},{"key": "C","text": "No progression is needed; intensity should remain fixed throughout"},{"key": "D","text": "Randomly alternating between very light and very heavy loads without a systematic plan"}],"correct": "A","explanation": "Safe, effective rehabilitation progression starts conservatively and advances resistance based on the patient's demonstrated tolerance and improving strength."},{"id": 4516,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Hard","question": "Which of the following best describes 'accommodating resistance' as provided by isokinetic exercise equipment?","options": [{"key": "A","text": "No resistance is provided at any point in the range"},{"key": "B","text": "Resistance only occurs during the eccentric phase"},{"key": "C","text": "Resistance automatically adjusts to match the force the patient applies at a constant velocity"},{"key": "D","text": "Resistance remains completely fixed regardless of the force applied"}],"correct": "C","explanation": "Isokinetic devices provide resistance that matches the patient's force output at a set speed, allowing maximal loading throughout the range without exceeding a fixed velocity."},{"id": 4517,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following is a potential advantage of using free weights over machine-based resistance training in functional rehabilitation?","options": [{"key": "A","text": "Machines always provide better functional carryover than free weights"},{"key": "B","text": "Free weights eliminate the need for any spotting or supervision"},{"key": "C","text": "Machines require more balance and coordination than free weights"},{"key": "D","text": "Free weights require greater stabilizer muscle activation, more closely mimicking functional movement demands"}],"correct": "D","explanation": "Free weights demand additional stabilizing muscle activity to control the movement path, which can better translate to functional tasks compared to the fixed path of machines."},{"id": 4518,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following resistance training variables would be adjusted to specifically target power development rather than pure strength?","options": [{"key": "A","text": "Focusing exclusively on very high repetitions with minimal resistance"},{"key": "B","text": "Using only isometric holds without any movement"},{"key": "C","text": "Moving the load as quickly as possible against moderate resistance"},{"key": "D","text": "Moving the load as slowly as possible against maximal resistance"}],"correct": "C","explanation": "Power training emphasizes the rate of force development, combining moderate load with maximal movement speed, distinct from pure maximal strength training approaches."},{"id": 4519,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Medium","question": "Which of the following exercises would be an appropriate way to progress a patient from isometric quadriceps exercises to more functional strengthening?","options": [{"key": "A","text": "Returning to complete immobilization"},{"key": "B","text": "Skipping directly to maximal one-repetition max testing"},{"key": "C","text": "Progressing to partial-range mini-squats or short-arc quad exercises"},{"key": "D","text": "Immediately jumping to plyometric box jumps"}],"correct": "C","explanation": "A logical progression moves from isometric activation to controlled, limited-range functional movements before advancing to higher-demand activities."},{"id": 4520,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "PNF (Proprioceptive Neuromuscular Facilitation) is based on which fundamental neurophysiological concept?","options": [{"key": "A","text": "Complete inhibition of all reflex activity"},{"key": "B","text": "Only applicable to strengthen isolated single muscles"},{"key": "C","text": "Purely psychological motivation techniques without neurophysiological basis"},{"key": "D","text": "Facilitating movement responses through stimulation of proprioceptors"}],"correct": "D","explanation": "PNF techniques exploit proprioceptive input (from muscle spindles, Golgi tendon organs, joint receptors) to facilitate or inhibit muscle activity and movement patterns."},{"id": 4521,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "The 'hold-relax' PNF technique is primarily used to:","options": [{"key": "A","text": "Replace the need for any other stretching technique entirely"},{"key": "B","text": "Increase muscle bulk through repeated concentric contractions"},{"key": "C","text": "Increase range of motion by using isometric contraction followed by relaxation and passive movement into new range"},{"key": "D","text": "Only assess muscle strength without any therapeutic effect"}],"correct": "C","explanation": "Hold-relax uses an isometric contraction of the restricted muscle against resistance, followed by relaxation, allowing greater passive range via autogenic inhibition."},{"id": 4522,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "The 'slow reversal' PNF technique involves:","options": [{"key": "A","text": "Complete relaxation of all muscle groups throughout"},{"key": "B","text": "Only passive movement in one direction"},{"key": "C","text": "Isometric holding only, without any dynamic movement"},{"key": "D","text": "Alternating concentric contractions of agonist and antagonist muscle groups without relaxation between the two"}],"correct": "D","explanation": "Slow reversal alternates active concentric contractions between opposing muscle groups, promoting increased strength and coordination through reversal of antagonists."},{"id": 4523,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Rhythmic initiation, a PNF technique, is particularly useful for patients who have difficulty:","options": [{"key": "A","text": "Only patients with normal, unimpaired movement initiation"},{"key": "B","text": "Initiating movement due to rigidity, spasticity, or apraxia"},{"key": "C","text": "Only used for cardiovascular conditioning"},{"key": "D","text": "Patients needing pure strength training only"}],"correct": "B","explanation": "Rhythmic initiation guides the patient through passive, then active-assisted, then active movement, helping overcome initiation difficulties seen in conditions like Parkinson's disease."},{"id": 4524,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Which PNF technique uses repeated quick stretches to facilitate a weak muscle contraction during a movement?","options": [{"key": "A","text": "Slow reversal hold"},{"key": "B","text": "Repeated stretch (repeated contractions) technique"},{"key": "C","text": "Rhythmic stabilization"},{"key": "D","text": "Hold-relax technique"}],"correct": "B","explanation": "The repeated stretch technique applies a quick additional stretch during the movement to facilitate greater muscle recruitment in a weak muscle group."},{"id": 4525,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "In PNF diagonal patterns, the upper extremity D1 flexion pattern typically combines shoulder flexion, adduction, and external rotation with which forearm/wrist motion?","options": [{"key": "A","text": "No forearm or wrist component at all"},{"key": "B","text": "Forearm supination with wrist flexion"},{"key": "C","text": "Forearm pronation with wrist extension"},{"key": "D","text": "Only elbow flexion without any distal component"}],"correct": "B","explanation": "The D1 flexion pattern is a diagonal combination incorporating proximal shoulder motion with coordinated distal forearm/wrist movement, mimicking functional reaching patterns."},{"id": 4526,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "PNF techniques are considered particularly valuable in rehabilitation because they typically incorporate which type of movement pattern, closely mimicking functional activities?","options": [{"key": "A","text": "Diagonal and rotational movement patterns across multiple joints"},{"key": "B","text": "Purely single-plane, single-joint isolated movements"},{"key": "C","text": "Static positions without any dynamic component"},{"key": "D","text": "Movements that avoid any rotational component entirely"}],"correct": "A","explanation": "Unlike isolated single-joint exercises, PNF diagonal patterns combine multiple joints and rotational components, more closely replicating natural functional movement."},{"id": 4527,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "Which of the following patient populations might particularly benefit from PNF techniques targeting improved coordination and strength during functional movement retraining?","options": [{"key": "A","text": "Only healthy elite athletes with no impairment"},{"key": "B","text": "Patients with no functional movement goals"},{"key": "C","text": "Patients with neurological conditions such as stroke or incomplete spinal cord injury"},{"key": "D","text": "Patients requiring isolated joint immobilization only"}],"correct": "C","explanation": "PNF's functional, diagonal movement patterns are widely used in neurological rehabilitation to promote coordinated, meaningful movement recovery."},{"id": 4528,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "The 'contract-relax-active contraction' variant of PNF stretching differs from simple 'contract-relax' in that it additionally requires:","options": [{"key": "A","text": "Complete relaxation with no further muscle activity"},{"key": "B","text": "No muscle contraction of any kind throughout the technique"},{"key": "C","text": "An active contraction of the agonist muscle into the new range immediately after the stretch"},{"key": "D","text": "Only passive movement performed by the therapist"}],"correct": "C","explanation": "This variant adds an active concentric contraction of the target muscle group into the newly gained range, potentially enhancing both flexibility and strength simultaneously."},{"id": 4529,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Rhythmic stabilization, a PNF technique used to improve joint stability, primarily involves which type of muscle contraction?","options": [{"key": "A","text": "Purely concentric contractions in a single direction"},{"key": "B","text": "Purely eccentric contractions only"},{"key": "C","text": "Alternating isometric contractions in multiple directions around a joint"},{"key": "D","text": "Complete absence of any muscle contraction"}],"correct": "C","explanation": "Rhythmic stabilization applies alternating resistance requiring isometric co-contraction of muscles around a joint, enhancing stability and proprioceptive control."},{"id": 4530,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Static balance refers to the ability to:","options": [{"key": "A","text": "Maintain stability while moving through space"},{"key": "B","text": "Only relevant for upper extremity function"},{"key": "C","text": "Only applies during walking activities"},{"key": "D","text": "Maintain a stable position while stationary"}],"correct": "D","explanation": "Static balance involves maintaining postural control in a stationary position, such as standing still, as opposed to dynamic balance during movement."},{"id": 4531,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Dynamic balance refers to the ability to:","options": [{"key": "A","text": "Applies only to seated activities"},{"key": "B","text": "Maintain stability while the body is moving or transitioning between positions"},{"key": "C","text": "Has no relevance to functional mobility"},{"key": "D","text": "Only maintain balance while completely motionless"}],"correct": "B","explanation": "Dynamic balance is required during activities involving movement, such as walking, turning, or reaching, representing a more functionally complex skill than static balance."},{"id": 4532,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following exercises would be an appropriate early-stage static balance training activity for a patient with mild balance impairment?","options": [{"key": "A","text": "Jumping and landing on one leg"},{"key": "B","text": "Standing with feet together, eyes open, on a stable surface"},{"key": "C","text": "Walking on an uneven surface while carrying objects"},{"key": "D","text": "Standing on one leg on a foam surface with eyes closed"}],"correct": "B","explanation": "Simple double-leg stance on a stable, firm surface represents an appropriate starting point before progressing to more challenging balance conditions."},{"id": 4533,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following would appropriately increase the difficulty of a standing balance exercise?","options": [{"key": "A","text": "Closing the eyes is never used to increase difficulty"},{"key": "B","text": "Providing full external support with both hands"},{"key": "C","text": "Widening the base of support significantly"},{"key": "D","text": "Narrowing the base of support and/or altering the support surface (e.g., foam)"}],"correct": "D","explanation": "Reducing the base of support and altering surface stability are established methods to progressively challenge the postural control system."},{"id": 4534,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Reactive balance training, which involves responding to unexpected perturbations, is important for improving:","options": [{"key": "A","text": "Only upper extremity coordination"},{"key": "B","text": "Only cardiovascular fitness"},{"key": "C","text": "Only static standing balance"},{"key": "D","text": "The ability to recover from unexpected slips or trips, reducing fall risk"}],"correct": "D","explanation": "Reactive balance training specifically targets the rapid postural responses needed to prevent falls following unexpected external perturbations, a distinct skill from proactive/anticipatory balance control."},{"id": 4535,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following gait deviations might be observed in a patient with quadriceps weakness, requiring compensation during the stance phase?","options": [{"key": "A","text": "Excessive knee flexion throughout stance"},{"key": "B","text": "Increased hip flexion during stance only"},{"key": "C","text": "No observable compensation of any kind"},{"key": "D","text": "Hyperextension of the knee (genu recurvatum) during stance to lock the joint"}],"correct": "D","explanation": "Weak quadriceps may lead patients to compensate by hyperextending the knee during stance to achieve passive joint stability, a common compensatory gait pattern."},{"id": 4536,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Steppage gait, characterized by excessive hip and knee flexion during swing phase, is typically seen in patients with:","options": [{"key": "A","text": "Foot drop (weakness of ankle dorsiflexors)"},{"key": "B","text": "Normal, unimpaired gait"},{"key": "C","text": "Quadriceps weakness only"},{"key": "D","text": "Hip abductor weakness only (Trendelenburg pattern)"}],"correct": "A","explanation": "To clear the foot during swing despite dorsiflexor weakness (foot drop), patients compensate with excessive hip/knee flexion, producing a high-stepping gait pattern."},{"id": 4537,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Antalgic gait, characterized by a shortened stance phase on the painful limb, is primarily a compensation for:","options": [{"key": "A","text": "Purely a balance deficit unrelated to pain"},{"key": "B","text": "Muscle weakness without pain"},{"key": "C","text": "Pain during weight-bearing on the affected limb"},{"key": "D","text": "Visual impairment"}],"correct": "C","explanation": "Patients with a painful lower limb condition shorten the stance phase on that side to minimize weight-bearing time and reduce pain, characterizing an antalgic gait pattern."},{"id": 4538,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Easy","question": "Which of the following gait training progressions would typically follow parallel bar walking as a patient's balance and strength improve?","options": [{"key": "A","text": "Regression back to wheelchair use only"},{"key": "B","text": "Progression to a walker, then possibly a cane, with decreasing levels of external support"},{"key": "C","text": "No further progression is typically needed after parallel bars"},{"key": "D","text": "Immediate return to unassisted running"}],"correct": "B","explanation": "Gait training typically progresses from higher-support devices (parallel bars, walkers) toward less restrictive devices (canes) and eventually independent ambulation as function improves."},{"id": 4539,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 'four-point gait pattern' used with a walker or bilateral canes involves which sequence of movement?","options": [{"key": "A","text": "Alternating advancement of one device and the opposite leg, then the other device and leg"},{"key": "B","text": "Moving both devices and both legs simultaneously"},{"key": "C","text": "Only using a single device with no leg advancement pattern"},{"key": "D","text": "Complete avoidance of any device advancement sequence"}],"correct": "A","explanation": "The four-point pattern provides maximal stability through a reciprocal, alternating sequence, suitable for patients needing significant support but able to bear weight on both legs."},{"id": 4540,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 'two-point gait pattern' with bilateral canes typically involves:","options": [{"key": "A","text": "Using only one cane at a time regardless of pattern"},{"key": "B","text": "Simultaneous advancement of one cane with the opposite leg, alternating sides"},{"key": "C","text": "No coordination between upper and lower limb movement"},{"key": "D","text": "Advancing all four points (two canes, two legs) simultaneously"}],"correct": "B","explanation": "The two-point pattern pairs a cane with the contralateral leg advancing together, providing a faster, more natural reciprocal gait pattern than the four-point pattern."},{"id": 4541,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Coordination exercises such as finger-to-nose testing are commonly used to assess and train function of which neurological structure?","options": [{"key": "A","text": "Spinal cord anterior horn cells"},{"key": "B","text": "Peripheral motor nerves exclusively"},{"key": "C","text": "Basal ganglia exclusively"},{"key": "D","text": "Cerebellum"}],"correct": "D","explanation": "Finger-to-nose and similar coordination tests assess cerebellar function, which governs smooth, accurate, coordinated movement."},{"id": 4542,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Heel-to-shin testing is commonly used clinically to assess coordination of which body region?","options": [{"key": "A","text": "Trunk stability exclusively"},{"key": "B","text": "Upper extremity exclusively"},{"key": "C","text": "Cervical spine mobility"},{"key": "D","text": "Lower extremity, particularly cerebellar-mediated coordination"}],"correct": "D","explanation": "Heel-to-shin testing evaluates lower limb coordination, helping identify cerebellar or proprioceptive deficits affecting smooth, accurate movement."},{"id": 4543,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Rapid alternating movement tests (e.g., rapid hand pronation/supination) are used to assess for which sign of cerebellar dysfunction?","options": [{"key": "A","text": "Dysdiadochokinesia (impaired rapid alternating movements)"},{"key": "B","text": "Fasciculations"},{"key": "C","text": "Spasticity"},{"key": "D","text": "Sensory loss"}],"correct": "A","explanation": "Dysdiadochokinesia refers specifically to the impaired ability to perform rapid alternating movements, a classic sign of cerebellar dysfunction."},{"id": 4544,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes the purpose of incorporating dual-task training (e.g., walking while performing a cognitive task) in balance/gait rehabilitation?","options": [{"key": "A","text": "Improving the ability to maintain balance and gait safety under more realistic, functionally demanding conditions"},{"key": "B","text": "Only relevant for patients without any cognitive impairment"},{"key": "C","text": "Purely for cognitive assessment with no motor benefit"},{"key": "D","text": "Has no relationship to real-world fall risk"}],"correct": "A","explanation": "Dual-task training addresses the reality that daily activities often require simultaneous cognitive and motor demands, and can reveal or address balance/gait vulnerabilities not apparent with single-task testing alone."},{"id": 4545,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Vestibular rehabilitation exercises (e.g., gaze stabilization exercises) are primarily used to treat patients with:","options": [{"key": "A","text": "Dizziness/vertigo due to vestibular dysfunction"},{"key": "B","text": "Cardiovascular deconditioning exclusively"},{"key": "C","text": "Isolated muscular weakness without vestibular involvement"},{"key": "D","text": "Isolated visual acuity problems unrelated to vestibular function"}],"correct": "A","explanation": "Vestibular rehabilitation uses specific exercises to promote central compensation for vestibular deficits, reducing dizziness and improving gaze/postural stability."},{"id": 4546,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Gaze stabilization exercises, a component of vestibular rehabilitation, typically involve:","options": [{"key": "A","text": "Complete avoidance of head movement indefinitely"},{"key": "B","text": "Moving the head while maintaining visual fixation on a stationary target"},{"key": "C","text": "Only performed with the eyes closed throughout"},{"key": "D","text": "Moving the eyes only, without any head movement"}],"correct": "B","explanation": "These exercises train the vestibulo-ocular reflex by challenging the patient to maintain clear vision on a target while moving the head, promoting vestibular compensation."},{"id": 4547,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following functional tasks would represent an appropriate advanced balance training progression for a patient recovering well from lower limb injury?","options": [{"key": "A","text": "Sitting balance on a stable chair"},{"key": "B","text": "Lying supine without any postural challenge"},{"key": "C","text": "Single-leg stance on an unstable surface while catching/throwing a ball"},{"key": "D","text": "Double-leg stance on a firm, stable surface with eyes open"}],"correct": "C","explanation": "Combining single-limb support, unstable surfaces, and a reactive/dual-task component (catching a ball) represents a significantly advanced balance challenge appropriate for later rehabilitation stages."},{"id": 4548,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Community ambulation training, an advanced stage of gait rehabilitation, typically focuses on preparing patients for which real-world challenges?","options": [{"key": "A","text": "Only walking on a smooth, flat treadmill indefinitely"},{"key": "B","text": "Complete avoidance of any outdoor environment"},{"key": "C","text": "Navigating uneven terrain, curbs, varying surfaces, and environmental distractions"},{"key": "D","text": "Only seated mobility tasks"}],"correct": "C","explanation": "Community ambulation training addresses the complex, variable demands of real-world environments beyond the controlled clinical setting, essential for functional independence."},{"id": 4549,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following is a common component of fall prevention exercise programs for community-dwelling older adults?","options": [{"key": "A","text": "Complete avoidance of standing balance exercises"},{"key": "B","text": "Combined strength, balance, and gait training with functional task practice"},{"key": "C","text": "Only cognitive training without any physical component"},{"key": "D","text": "Only bed rest and passive range of motion"}],"correct": "B","explanation": "Evidence-based fall prevention programs integrate multiple exercise components (strength, balance, functional mobility) shown to reduce fall incidence in older populations."},{"id": 4550,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which approach to neurological rehabilitation emphasizes facilitating normal movement patterns while inhibiting abnormal reflex activity and spasticity?","options": [{"key": "A","text": "Complete immobilization of affected limbs"},{"key": "B","text": "Neurodevelopmental Treatment (Bobath approach)"},{"key": "C","text": "Isolated passive range of motion only"},{"key": "D","text": "Purely resistance-based strength training without movement facilitation"}],"correct": "B","explanation": "The Bobath/NDT approach focuses on facilitating more normal movement patterns and postural control while managing abnormal muscle tone in neurological conditions."},{"id": 4551,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Constraint-induced movement therapy (CIMT), used after stroke, involves:","options": [{"key": "A","text": "Restraining the less-affected limb to force use of the more affected limb"},{"key": "B","text": "Only used for lower extremity rehabilitation"},{"key": "C","text": "Avoiding any limb use during therapy"},{"key": "D","text": "Restraining the more affected limb to protect it from overuse"}],"correct": "A","explanation": "CIMT restrains the unaffected/less-affected limb to encourage intensive, repetitive use of the affected limb, promoting use-dependent neuroplasticity."},{"id": 4552,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is a key principle underlying constraint-induced movement therapy's effectiveness?","options": [{"key": "A","text": "Complete avoidance of using the affected limb permanently"},{"key": "B","text": "Requires no active patient participation"},{"key": "C","text": "Overcoming 'learned non-use' of the affected limb through forced, repetitive practice"},{"key": "D","text": "Only effective if applied within the first 24 hours post-stroke"}],"correct": "C","explanation": "CIMT addresses the phenomenon of learned non-use, where patients avoid using a weakened limb, by mandating its use to drive functional recovery."},{"id": 4553,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate approach for treating a patient with significant spasticity during exercise therapy sessions?","options": [{"key": "A","text": "Rapid, forceful stretching to quickly overcome the increased tone"},{"key": "B","text": "Complete avoidance of any stretching or positioning intervention"},{"key": "C","text": "Encouraging maximal resistance training regardless of tone level"},{"key": "D","text": "Slow, controlled stretching and positioning techniques to manage tone, combined with functional activity practice"}],"correct": "D","explanation": "Managing spasticity requires gentle, sustained techniques rather than rapid forceful stretching, which can actually increase reflexive muscle tone (stretch reflex activation)."},{"id": 4554,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Weight-bearing through an affected limb is often incorporated early in neurological rehabilitation (e.g., after stroke) primarily to:","options": [{"key": "A","text": "Increase spasticity intentionally"},{"key": "B","text": "Provide proprioceptive input and facilitate more normal muscle tone/postural responses"},{"key": "C","text": "Have no therapeutic rationale, purely for positioning comfort"},{"key": "D","text": "Avoid any sensory stimulation to the affected limb"}],"correct": "B","explanation": "Weight-bearing provides important proprioceptive and sensory feedback that can help normalize tone and facilitate postural and motor responses in neurological rehabilitation."},{"id": 4555,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following best describes 'mirror therapy' as used in neurological or complex regional pain syndrome rehabilitation?","options": [{"key": "A","text": "Using a mirror to create a visual illusion of normal movement in the affected limb by reflecting the unaffected limb"},{"key": "B","text": "A technique requiring no visual component at all"},{"key": "C","text": "A purely passive treatment with no active patient involvement"},{"key": "D","text": "Only used to assess cognitive function"}],"correct": "A","explanation": "Mirror therapy exploits visual feedback to create an illusion of normal movement, potentially helping to reduce pain or improve motor function through altered central processing."},{"id": 4556,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Robotic-assisted gait training is being increasingly used in neurological rehabilitation primarily to provide:","options": [{"key": "A","text": "Treatment exclusively for patients with fully normal gait"},{"key": "B","text": "A complete replacement for all conventional physiotherapy"},{"key": "C","text": "Only passive movement with no functional relevance"},{"key": "D","text": "High-repetition, consistent, and often intensive practice of gait patterns for patients with significant impairment"}],"correct": "D","explanation": "Robotic devices can provide the high volume of repetitive, task-specific practice thought to be important for driving neuroplasticity in patients unable to independently generate sufficient practice repetitions."},{"id": 4557,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise considerations is important for a patient with Parkinson's disease showing bradykinesia and rigidity?","options": [{"key": "A","text": "Avoiding any external cueing strategies"},{"key": "B","text": "Incorporating rhythmic cueing (auditory/visual) to improve movement initiation and gait speed"},{"key": "C","text": "Complete avoidance of exercise due to rigidity"},{"key": "D","text": "Only isolated strength training without functional movement practice"}],"correct": "B","explanation": "External cueing strategies (rhythmic auditory or visual cues) have shown particular benefit in improving gait parameters and reducing freezing episodes in Parkinson's disease."},{"id": 4558,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Freezing of gait, a symptom seen in advanced Parkinson's disease, can sometimes be helped during exercise therapy sessions by which strategy?","options": [{"key": "A","text": "Avoiding any environmental modification"},{"key": "B","text": "Encouraging the patient to move as quickly as possible without any cues"},{"key": "C","text": "Complete cessation of all gait training"},{"key": "D","text": "Using visual cues (e.g., stepping over lines) or auditory cueing to trigger movement initiation"}],"correct": "D","explanation": "External cues can help bypass the disrupted internal movement initiation pathways affected in Parkinson's disease, temporarily overcoming freezing episodes."},{"id": 4559,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Task-oriented training in stroke rehabilitation emphasizes practicing which type of activities?","options": [{"key": "A","text": "Purely passive treatments without active patient participation"},{"key": "B","text": "Only isolated, non-functional muscle strengthening exercises"},{"key": "C","text": "Tasks unrelated to the patient's actual functional needs"},{"key": "D","text": "Meaningful, functional tasks relevant to the patient's daily life and goals"}],"correct": "D","explanation": "Task-oriented training aligns with motor learning principles, emphasizing practice of real, meaningful functional activities to promote better carryover and neuroplastic change."},{"id": 4560,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes the concept of 'neuroplasticity' as it relates to rehabilitation after neurological injury?","options": [{"key": "A","text": "A phenomenon unrelated to exercise or rehabilitation practice"},{"key": "B","text": "A concept only relevant to the pediatric brain, not adults"},{"key": "C","text": "Complete inability of the nervous system to change after maturity"},{"key": "D","text": "The nervous system's capacity to reorganize and form new neural connections in response to learning and experience"}],"correct": "D","explanation": "Neuroplasticity underlies the potential for functional recovery after neurological injury, and is a key rationale for intensive, repetitive, task-specific rehabilitation approaches."},{"id": 4561,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which factor is generally considered important for maximizing neuroplasticity-driven recovery during rehabilitation exercise?","options": [{"key": "A","text": "High repetition and intensity of task-specific practice"},{"key": "B","text": "Minimal repetition with long rest periods between single attempts"},{"key": "C","text": "Practicing tasks unrelated to any functional goal"},{"key": "D","text": "Complete passivity without active patient engagement"}],"correct": "A","explanation": "Research supports that sufficient repetition, intensity, and specificity of practice are important factors in promoting neuroplastic changes that underlie functional motor recovery."},{"id": 4562,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise therapy consideration is important for a patient with significant cognitive impairment participating in a rehabilitation exercise program?","options": [{"key": "A","text": "Providing complex, multi-step verbal instructions without any simplification"},{"key": "B","text": "Simplifying instructions, using consistent routines, and providing appropriate supervision for safety"},{"key": "C","text": "Complete avoidance of any physical activity regardless of safety measures"},{"key": "D","text": "Assuming no modification to standard programs is needed"}],"correct": "B","explanation": "Cognitive impairment may require simplified communication, consistent structured routines, and careful safety supervision to ensure safe and effective participation in exercise."},{"id": 4563,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important safety consideration during exercise therapy for a patient with autonomic dysreflexia risk (spinal cord injury at or above T6)?","options": [{"key": "A","text": "No monitoring is needed for this specific population"},{"key": "B","text": "Monitoring for signs of sudden hypertension and being prepared to address triggering stimuli immediately"},{"key": "C","text": "Ignoring any changes in blood pressure during exercise"},{"key": "D","text": "Encouraging bladder distension as part of the exercise routine"}],"correct": "B","explanation": "Given the risk of dangerous hypertensive episodes, therapists must closely monitor for autonomic dysreflexia signs and promptly address potential triggers (e.g., bladder/bowel distension) during sessions."},{"id": 4564,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise approach might be particularly beneficial for improving trunk control in a patient with incomplete spinal cord injury?","options": [{"key": "A","text": "Progressive sitting balance activities and trunk stabilization exercises"},{"key": "B","text": "Only upper extremity exercises with no trunk component"},{"key": "C","text": "Complete avoidance of any trunk-focused exercise"},{"key": "D","text": "Immediate progression to unsupported standing without addressing sitting balance first"}],"correct": "A","explanation": "Building trunk control through graded sitting balance and stabilization work provides a foundation before progressing to more demanding standing and gait activities in SCI rehabilitation."},{"id": 4565,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following is an appropriate exercise therapy consideration for a patient with multiple sclerosis who experiences heat sensitivity and worsening symptoms with elevated core temperature (Uhthoff's phenomenon)?","options": [{"key": "A","text": "Encouraging exercise in a hot environment to build tolerance"},{"key": "B","text": "Complete avoidance of all physical activity regardless of environmental conditions"},{"key": "C","text": "Ignoring any temperature-related symptom changes"},{"key": "D","text": "Exercising in a cool environment and monitoring for symptom exacerbation with rising body temperature"}],"correct": "D","explanation": "Uhthoff's phenomenon describes temporary symptom worsening with increased core temperature in MS; exercising in cooler conditions and monitoring symptoms helps maintain safe, effective participation."},{"id": 4566,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes the Bobath (Neurodevelopmental Treatment) approach to neurological rehabilitation?","options": [{"key": "A","text": "Purely strength training without attention to movement quality"},{"key": "B","text": "Facilitating normal movement patterns while inhibiting abnormal tone/reflexes through handling techniques"},{"key": "C","text": "Complete immobilization to prevent abnormal movement"},{"key": "D","text": "Only used for pediatric patients, never adults"}],"correct": "B","explanation": "The Bobath approach emphasizes normalizing muscle tone and facilitating more typical movement patterns through specific handling and positioning techniques, historically used in stroke and cerebral palsy rehabilitation."},{"id": 4567,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Constraint-induced movement therapy (CIMT) for stroke rehabilitation involves:","options": [{"key": "A","text": "Restraining the affected limb to protect it from overuse"},{"key": "B","text": "Restraining the less-affected limb to force use of the affected limb"},{"key": "C","text": "Complete avoidance of using either upper limb"},{"key": "D","text": "Equal bilateral limb use without any restraint"}],"correct": "B","explanation": "CIMT intentionally restrains the stronger limb, forcing intensive, repetitive practice with the affected limb to promote use-dependent neuroplasticity."},{"id": 4568,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which principle underlies the effectiveness of constraint-induced movement therapy in overcoming 'learned non-use' after stroke?","options": [{"key": "A","text": "Learned non-use cannot be reversed through any intervention"},{"key": "B","text": "Only passive movement, never active use, addresses learned non-use"},{"key": "C","text": "Complete rest of the affected limb allows spontaneous recovery"},{"key": "D","text": "Forced, repetitive practice of the affected limb promotes cortical reorganization and functional improvement"}],"correct": "D","explanation": "CIMT directly addresses learned non-use by mandating intensive active use of the affected limb, driving activity-dependent neural reorganization."},{"id": 4569,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise approaches is commonly used to address spasticity management in neurological rehabilitation, in conjunction with medical treatments?","options": [{"key": "A","text": "Sustained stretching and positioning to maintain soft tissue length and reduce hypertonicity"},{"key": "B","text": "Rapid ballistic stretching to maximize stretch reflex activation"},{"key": "C","text": "High-speed resistance training exclusively to increase spasticity further"},{"key": "D","text": "Complete avoidance of any stretching or positioning intervention"}],"correct": "A","explanation": "Prolonged, gentle stretching and proper positioning help manage spasticity and prevent secondary contractures, complementing pharmacological spasticity management."},{"id": 4570,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Weight-bearing exercises through an affected upper limb after stroke may help reduce spasticity primarily through which mechanism?","options": [{"key": "A","text": "Increasing reflexive stretch responses to worsen spasticity"},{"key": "B","text": "Providing sustained proprioceptive input and sensory feedback that can help normalize tone"},{"key": "C","text": "Having no effect on muscle tone whatsoever"},{"key": "D","text": "Only benefiting the unaffected limb"}],"correct": "B","explanation": "Weight-bearing provides sustained joint compression and proprioceptive input, which can have a tone-normalizing effect in spastic limbs during neurological rehabilitation."},{"id": 4571,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise approach would be most appropriate for a patient with ataxia due to cerebellar dysfunction, aiming to improve movement control?","options": [{"key": "A","text": "Complete avoidance of any coordination-specific training"},{"key": "B","text": "Purely passive range of motion without active participation"},{"key": "C","text": "Frenkel's exercises using repetitive, precise movement patterns with visual feedback"},{"key": "D","text": "High-speed, unpredictable plyometric training"}],"correct": "C","explanation": "Frenkel's exercises are specifically designed to retrain coordination in ataxic patients through structured, precise, and progressively challenging movement sequences."},{"id": 4572,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "In early-stage rehabilitation following acute stroke, which positioning strategy is important to prevent complications such as shoulder subluxation?","options": [{"key": "A","text": "Complete immobilization in a sling at all times without any movement"},{"key": "B","text": "Allowing the affected arm to hang unsupported for extended periods"},{"key": "C","text": "No positioning precautions are necessary"},{"key": "D","text": "Proper support and positioning of the affected shoulder, avoiding prolonged unsupported arm dangling"}],"correct": "D","explanation": "Flaccid shoulder musculature after stroke is vulnerable to subluxation from gravitational pull, so proper support and careful positioning/handling are essential early interventions."},{"id": 4573,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise/therapy approaches focuses on repetitive, task-specific practice to promote motor recovery based on principles of activity-dependent neuroplasticity?","options": [{"key": "A","text": "Purely passive modalities without active practice"},{"key": "B","text": "Random, non-specific general exercise unrelated to functional goals"},{"key": "C","text": "Complete rest without any therapeutic intervention"},{"key": "D","text": "Task-specific training"}],"correct": "D","explanation": "Task-specific training directly practices meaningful functional activities, leveraging neuroplasticity principles that favor use-dependent, specific skill practice for optimal motor recovery."},{"id": 4574,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Mirror therapy, used in neurological and pain rehabilitation, works by:","options": [{"key": "A","text": "Only being effective for lower extremity conditions"},{"key": "B","text": "Requiring the patient to avoid looking at either limb"},{"key": "C","text": "Using visual feedback of the unaffected limb's movement reflected to create the illusion of normal affected limb movement"},{"key": "D","text": "Providing tactile stimulation only, without any visual component"}],"correct": "C","explanation": "Mirror therapy creates a visual illusion that can help modulate cortical reorganization and reduce pain or improve motor function, used in conditions like stroke hemiparesis and phantom limb pain."},{"id": 4575,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with Parkinson's disease experiencing bradykinesia and rigidity?","options": [{"key": "A","text": "Complete avoidance of any exercise program"},{"key": "B","text": "Avoiding any external cueing strategies"},{"key": "C","text": "Incorporating large-amplitude movement training and rhythmic cueing strategies to improve movement initiation and size"},{"key": "D","text": "Encouraging small, minimal movements exclusively"}],"correct": "C","explanation": "Large-amplitude movement training (e.g., LSVT BIG approach) and external rhythmic cues (auditory/visual) are evidence-based strategies to address the characteristic movement deficits in Parkinson's disease."},{"id": 4576,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "External cueing strategies (e.g., rhythmic auditory cues, visual floor markers) are particularly useful for patients with Parkinson's disease experiencing which gait feature?","options": [{"key": "A","text": "Absence of any gait impairment"},{"key": "B","text": "Excessive stride length"},{"key": "C","text": "Freezing of gait"},{"key": "D","text": "Increased gait speed beyond normal"}],"correct": "C","explanation": "External cues can help bypass impaired internal movement generation mechanisms in Parkinson's disease, particularly helpful for overcoming freezing episodes during gait."},{"id": 4577,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise considerations is important for patients with multiple sclerosis experiencing heat sensitivity (Uhthoff's phenomenon)?","options": [{"key": "A","text": "Monitoring for symptom worsening with increased body temperature and considering cooling strategies during exercise"},{"key": "B","text": "No temperature-related precautions are necessary"},{"key": "C","text": "Complete avoidance of any physical activity"},{"key": "D","text": "Encouraging exercise in hot environments to build heat tolerance"}],"correct": "A","explanation": "Many MS patients experience temporary symptom worsening with increased core body temperature, so exercise programs should consider cooling strategies and appropriate environmental conditions."},{"id": 4578,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following exercise therapy approaches would be appropriate for a patient with Guillain-Barre syndrome during the acute/recovery phase, given the risk of overwork weakness?","options": [{"key": "A","text": "Gradual, carefully monitored progressive exercise avoiding excessive fatigue"},{"key": "B","text": "Aggressive maximal resistance training regardless of fatigue level"},{"key": "C","text": "Complete immobilization throughout the recovery period"},{"key": "D","text": "Only passive modalities with no active exercise ever"}],"correct": "A","explanation": "GBS patients are susceptible to overwork weakness if overexerted during recovery, requiring carefully graded exercise progression with close monitoring for fatigue."},{"id": 4579,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "For patients with incomplete spinal cord injury, which exercise therapy principle underlies partial body-weight supported treadmill training?","options": [{"key": "A","text": "This technique is only used for patients with complete, non-recovering spinal cord injury"},{"key": "B","text": "Providing controlled body weight support allows practice of stepping patterns while promoting spinal cord plasticity"},{"key": "C","text": "Complete removal of any load-bearing eliminates the potential for neurological recovery"},{"key": "D","text": "No neuroplasticity occurs below the level of spinal cord injury"}],"correct": "B","explanation": "Body-weight supported treadmill training allows repetitive, task-specific stepping practice even with residual weakness, leveraging spinal cord plasticity mechanisms in incomplete injuries."},{"id": 4580,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which precaution is essential when initiating any exercise program for a patient with spinal cord injury at or above T6, given the risk of autonomic dysreflexia?","options": [{"key": "A","text": "Monitoring for signs of autonomic dysreflexia and identifying/removing any noxious stimuli promptly"},{"key": "B","text": "Autonomic dysreflexia only occurs during complete rest, never during exercise"},{"key": "C","text": "Encouraging exercises that intentionally trigger noxious stimuli"},{"key": "D","text": "No precautions are needed for exercise in this population"}],"correct": "A","explanation": "Exercise or any noxious stimulus below the level of injury can trigger autonomic dysreflexia in high-level SCI, requiring vigilant monitoring during physical activity."},{"id": 4581,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Following total knee arthroplasty, early physiotherapy focus (days 0-2) typically emphasizes:","options": [{"key": "A","text": "Aggressive stretching beyond tolerable pain limits"},{"key": "B","text": "Immediate high-intensity resistance training"},{"key": "C","text": "Pain management, achieving knee extension, and early mobilization"},{"key": "D","text": "Complete immobilization for the first two weeks"}],"correct": "C","explanation": "Early TKA rehabilitation prioritizes controlling pain/swelling, restoring extension range (critical for normal gait), and getting the patient moving safely."},{"id": 4582,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Achieving full knee extension is considered particularly critical after total knee arthroplasty because inadequate extension can lead to:","options": [{"key": "A","text": "Enhanced quadriceps strength automatically"},{"key": "B","text": "Improved walking efficiency"},{"key": "C","text": "An abnormal, inefficient gait pattern requiring compensatory movement"},{"key": "D","text": "No functional consequence"}],"correct": "C","explanation": "Failure to regain full knee extension after TKA typically results in a flexed-knee gait pattern, increasing energy expenditure and quadriceps demand during walking."},{"id": 4583,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Following total hip arthroplasty via a posterior surgical approach, patients are typically advised to avoid which combination of movements to reduce dislocation risk?","options": [{"key": "A","text": "Only avoiding hip abduction movements"},{"key": "B","text": "Hip extension combined with external rotation"},{"key": "C","text": "Hip flexion beyond 90 degrees combined with adduction and internal rotation"},{"key": "D","text": "Any hip movement whatsoever"}],"correct": "C","explanation": "The posterior approach disrupts posterior capsule/muscle structures, making combined flexion, adduction, and internal rotation particularly risky for posterior dislocation."},{"id": 4584,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Following rotator cuff repair surgery, the initial rehabilitation phase (protection phase) typically prioritizes:","options": [{"key": "A","text": "Overhead throwing activities immediately post-surgery"},{"key": "B","text": "Protecting the surgical repair while addressing pain and passive/gentle range of motion within specified limits"},{"key": "C","text": "Complete shoulder immobilization for 6 months without any movement"},{"key": "D","text": "Immediate aggressive active resistance exercise"}],"correct": "B","explanation": "Early rotator cuff repair rehabilitation protects the healing tendon-bone interface while gradually introducing controlled movement per surgeon-specific protocols."},{"id": 4585,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which structure's healing timeline is a primary consideration guiding the phased progression of rotator cuff repair rehabilitation?","options": [{"key": "A","text": "The cervical spine"},{"key": "B","text": "The lumbar spine"},{"key": "C","text": "The repaired tendon-to-bone healing interface"},{"key": "D","text": "The unaffected contralateral shoulder"}],"correct": "C","explanation": "Tendon-to-bone healing after rotator cuff repair follows a biological timeline (often 8-12 weeks for adequate strength), directly guiding when active loading can safely begin."},{"id": 4586,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Following ACL reconstruction, which criterion is commonly used, in addition to time since surgery, to determine readiness for return to sport?","options": [{"key": "A","text": "Complete absence of any need for functional testing"},{"key": "B","text": "Achieving specific strength symmetry and functional performance benchmarks compared to the uninvolved limb"},{"key": "C","text": "Only the calendar date since surgery, regardless of function"},{"key": "D","text": "Patient's subjective feeling of readiness alone without objective testing"}],"correct": "B","explanation": "Modern ACL return-to-sport criteria emphasize objective functional and strength testing (e.g., limb symmetry index) rather than relying solely on time elapsed since surgery."},{"id": 4587,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important precaution during early rehabilitation following a meniscal repair (as opposed to meniscectomy)?","options": [{"key": "A","text": "Complete avoidance of any range of motion exercise"},{"key": "B","text": "Restricting deep knee flexion and/or weight-bearing per protocol to protect the healing repair"},{"key": "C","text": "No precautions of any kind are necessary"},{"key": "D","text": "Immediate full weight-bearing with unrestricted deep squatting"}],"correct": "B","explanation": "Meniscal repairs require protection of the healing tissue, often with temporary restrictions on deep flexion and loading, unlike the more rapid rehabilitation typically allowed after simple meniscectomy."},{"id": 4588,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Following ankle fracture with open reduction internal fixation (ORIF), the timing of weight-bearing progression is primarily determined by:","options": [{"key": "A","text": "Complete non-weight-bearing indefinitely regardless of healing"},{"key": "B","text": "The patient's personal preference regardless of surgical findings"},{"key": "C","text": "Surgeon protocol based on fracture stability and healing as confirmed by imaging"},{"key": "D","text": "Immediate full weight-bearing on day one universally"}],"correct": "C","explanation": "Weight-bearing status after ORIF depends on the specific fracture pattern, fixation stability, and radiographic healing progress, guided by surgeon-specific protocols."},{"id": 4589,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate early exercise therapy focus following lumbar spinal fusion surgery?","options": [{"key": "A","text": "Immediate return to unrestricted heavy lifting"},{"key": "B","text": "Complete bed rest for several months"},{"key": "C","text": "Aggressive spinal flexion/extension exercises immediately post-operatively"},{"key": "D","text": "Gentle early mobilization with attention to appropriate spinal precautions (e.g., avoiding excessive bending/twisting/lifting)"}],"correct": "D","explanation": "Early post-fusion rehabilitation balances the need for mobilization with protecting the healing fusion site, typically avoiding excessive spinal loading/twisting initially."},{"id": 4590,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Following carpal tunnel release surgery, early physiotherapy typically focuses on:","options": [{"key": "A","text": "Aggressive wrist manipulation beyond pain tolerance"},{"key": "B","text": "Immediate heavy grip strengthening"},{"key": "C","text": "Complete hand immobilization for several months"},{"key": "D","text": "Edema control, gentle tendon gliding exercises, and gradual return of hand function"}],"correct": "D","explanation": "Post-carpal tunnel release rehabilitation addresses swelling and promotes tendon mobility through gentle gliding exercises before progressing to strengthening as healing allows."},{"id": 4591,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate rehabilitation consideration following an Achilles tendon repair?","options": [{"key": "A","text": "Aggressive early stretching into full dorsiflexion immediately post-surgery"},{"key": "B","text": "Gradual progression through protected weight-bearing and controlled range of motion per a structured protocol, avoiding early aggressive dorsiflexion stretching"},{"key": "C","text": "Immediate unrestricted running and jumping"},{"key": "D","text": "Complete avoidance of any ankle movement for 6 months"}],"correct": "B","explanation": "Achilles repair protocols carefully control loading and dorsiflexion range early on to protect the healing tendon while progressively restoring function over an extended timeline."},{"id": 4592,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Following a distal radius fracture treated with casting (non-surgical), which exercises are typically encouraged even while the cast remains in place?","options": [{"key": "A","text": "Complete avoidance of movement in any joint of the affected arm"},{"key": "B","text": "Aggressive wrist movement despite the cast"},{"key": "C","text": "Active range of motion of the fingers, elbow, and shoulder to prevent stiffness in uninvolved joints"},{"key": "D","text": "Only lower extremity exercise, ignoring the upper extremity entirely"}],"correct": "C","explanation": "Maintaining mobility in adjacent uninvolved joints (fingers, elbow, shoulder) during immobilization helps prevent secondary stiffness while the fracture site heals within the cast."},{"id": 4593,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to exercise therapy following a hip fracture surgically repaired with internal fixation in an elderly patient?","options": [{"key": "A","text": "Early mobilization as tolerated, balancing fracture stability with the risks of prolonged immobility (e.g., pneumonia, deconditioning)"},{"key": "B","text": "Immediate unrestricted high-impact activity"},{"key": "C","text": "No physiotherapy involvement is needed post-surgery"},{"key": "D","text": "Complete strict bed rest for several months regardless of fixation stability"}],"correct": "A","explanation": "Given the significant risks of complications from prolonged bed rest in elderly patients, early safe mobilization is generally prioritized following stable surgical fixation."},{"id": 4594,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important consideration when designing an exercise program for a patient following a Colles' fracture once the cast is removed?","options": [{"key": "A","text": "Immediate return to maximal resistance training without progression"},{"key": "B","text": "Gradual restoration of wrist range of motion and grip strength, addressing any stiffness that developed during immobilization"},{"key": "C","text": "Focusing exclusively on the unaffected arm"},{"key": "D","text": "Complete avoidance of any wrist movement even after cast removal"}],"correct": "B","explanation": "Post-immobilization rehabilitation addresses the expected stiffness and weakness from the casting period, gradually restoring functional wrist mobility and strength."},{"id": 4595,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is a key rehabilitation consideration following shoulder dislocation, particularly to reduce recurrence risk?","options": [{"key": "A","text": "Strengthening the rotator cuff and periscapular musculature for dynamic joint stability"},{"key": "B","text": "Avoiding all shoulder strengthening exercises indefinitely"},{"key": "C","text": "Encouraging immediate return to overhead throwing activities"},{"key": "D","text": "Only addressing pain without any strengthening component"}],"correct": "A","explanation": "Dynamic stabilizers (rotator cuff, scapular muscles) play a crucial role in shoulder joint stability, and their strengthening is emphasized to help reduce the risk of recurrent dislocation."},{"id": 4596,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Phase I cardiac rehabilitation typically occurs during which setting/timeframe?","options": [{"key": "A","text": "Inpatient hospital setting immediately following a cardiac event or surgery"},{"key": "B","text": "Only in a home setting years after the cardiac event"},{"key": "C","text": "Exclusively via telehealth without any in-person component"},{"key": "D","text": "Only in an outpatient gym setting months later"}],"correct": "A","explanation": "Phase I cardiac rehab begins in the hospital, focusing on early, safe mobilization and patient education shortly after an acute cardiac event or surgery."},{"id": 4597,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Phase II cardiac rehabilitation typically involves:","options": [{"key": "A","text": "Exclusively unsupervised home exercise without any monitoring"},{"key": "B","text": "Only inpatient bed rest"},{"key": "C","text": "A lifelong program with no defined endpoint"},{"key": "D","text": "Supervised outpatient exercise training with continuous monitoring, usually beginning weeks after the cardiac event"}],"correct": "D","explanation": "Phase II is a structured, monitored outpatient program that builds functional capacity following the initial hospital phase, typically over several weeks to months."},{"id": 4598,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Phase III (maintenance) cardiac rehabilitation is characterized by:","options": [{"key": "A","text": "Exclusively supervised inpatient sessions"},{"key": "B","text": "Complete discontinuation of any structured exercise"},{"key": "C","text": "Only occurring immediately post-surgery in the ICU"},{"key": "D","text": "Longer-term, often less intensively monitored exercise to maintain fitness gains and cardiovascular health"}],"correct": "D","explanation": "Phase III represents the transition to independent, ongoing exercise maintenance after completing the more closely supervised earlier phases of cardiac rehabilitation."},{"id": 4599,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following signs/symptoms would warrant immediate cessation of exercise during a cardiac rehabilitation session?","options": [{"key": "A","text": "Onset of chest pain, significant dyspnea, or dizziness"},{"key": "B","text": "Mild, expected increase in heart rate with exertion"},{"key": "C","text": "Normal post-exercise fatigue that resolves with rest"},{"key": "D","text": "Slight increase in respiratory rate within normal limits"}],"correct": "A","explanation": "New or worsening cardiac symptoms during exercise are red flags requiring immediate cessation of activity and clinical assessment to ensure patient safety."},{"id": 4600,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Pulmonary rehabilitation programs for patients with COPD typically combine which components?","options": [{"key": "A","text": "Only surgical intervention"},{"key": "B","text": "Complete rest without any active intervention"},{"key": "C","text": "Only medication management without any exercise component"},{"key": "D","text": "Exercise training, breathing retraining, and patient education"}],"correct": "D","explanation": "Comprehensive pulmonary rehab integrates supervised exercise, breathing technique training, and education to improve functional capacity and quality of life in COPD."},{"id": 4601,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which type of exercise training is emphasized in pulmonary rehabilitation to improve exercise tolerance in COPD patients?","options": [{"key": "A","text": "Only isolated respiratory muscle training without any limb exercise"},{"key": "B","text": "Only maximal-intensity interval training regardless of tolerance"},{"key": "C","text": "Combined aerobic (endurance) and resistance/strength training"},{"key": "D","text": "Complete avoidance of any physical exertion"}],"correct": "C","explanation": "Evidence supports combining lower/upper limb aerobic and resistance training to improve overall functional capacity in COPD patients undergoing pulmonary rehabilitation."},{"id": 4602,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Oxygen saturation monitoring during exercise in patients with significant pulmonary disease is important primarily to:","options": [{"key": "A","text": "Have no clinical relevance to exercise safety"},{"key": "B","text": "Replace the need for monitoring heart rate entirely"},{"key": "C","text": "Only relevant for patients without any lung disease"},{"key": "D","text": "Detect exercise-induced desaturation and guide safe exercise intensity/supplemental oxygen needs"}],"correct": "D","explanation": "Continuous pulse oximetry helps identify unsafe desaturation during exertion, allowing appropriate adjustment of exercise intensity or supplemental oxygen use."},{"id": 4603,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Inspiratory muscle training, sometimes used in pulmonary rehabilitation, specifically targets strengthening of which muscle group?","options": [{"key": "A","text": "The diaphragm and other respiratory muscles involved in inspiration"},{"key": "B","text": "Only the upper trapezius"},{"key": "C","text": "Only the abdominal muscles"},{"key": "D","text": "Only the quadriceps"}],"correct": "A","explanation": "Inspiratory muscle training uses resistive breathing devices to specifically strengthen the diaphragm and accessory inspiratory muscles, potentially reducing dyspnea and improving endurance."},{"id": 4604,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise modifications might be necessary for a cardiac rehabilitation patient taking a beta-blocker medication?","options": [{"key": "A","text": "Assuming the medication has no effect on exercise response"},{"key": "B","text": "Avoiding all forms of exercise while on this medication class"},{"key": "C","text": "Relying solely on heart rate targets without any other consideration"},{"key": "D","text": "Using the Borg RPE scale rather than target heart rate zones to gauge exercise intensity, since heart rate response is blunted"}],"correct": "D","explanation": "Beta-blockers blunt the normal heart rate response to exertion, making perceived exertion scales more reliable indicators of appropriate exercise intensity in these patients."},{"id": 4605,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important safety consideration before initiating an exercise program for a patient recently diagnosed with unstable angina?","options": [{"key": "A","text": "No medical clearance is needed before starting exercise"},{"key": "B","text": "Immediate initiation of high-intensity exercise regardless of stability"},{"key": "C","text": "Exercise should generally be deferred until the condition is medically stabilized"},{"key": "D","text": "Unstable angina has no bearing on exercise program timing"}],"correct": "C","explanation": "Unstable angina represents an acute, potentially dangerous cardiac condition requiring medical stabilization before considering structured exercise therapy."},{"id": 4606,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 6-minute walk test is a commonly used functional outcome measure in cardiopulmonary rehabilitation primarily assessing:","options": [{"key": "A","text": "Submaximal functional exercise capacity"},{"key": "B","text": "Cognitive function exclusively"},{"key": "C","text": "Maximal oxygen consumption (VO2 max) directly"},{"key": "D","text": "Isolated upper extremity strength"}],"correct": "A","explanation": "The 6MWT provides a practical, submaximal measure of functional exercise capacity, useful for tracking progress in cardiac and pulmonary rehabilitation populations."},{"id": 4607,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following would be an appropriate exercise therapy modification for a patient with peripheral edema secondary to right heart failure?","options": [{"key": "A","text": "Recommending maximal-intensity lower limb exercise regardless of symptoms"},{"key": "B","text": "Encouraging prolonged standing without any position changes"},{"key": "C","text": "Ignoring the edema entirely during exercise prescription"},{"key": "D","text": "Elevating the legs during rest periods and monitoring for symptom changes during activity progression"}],"correct": "D","explanation": "Addressing dependent edema through positioning strategies alongside careful monitoring helps ensure safe, appropriate exercise progression in patients with right heart failure."},{"id": 4608,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which breathing technique is commonly taught to patients with COPD to help control dyspnea during activity?","options": [{"key": "A","text": "Pursed-lip breathing combined with pacing of activity"},{"key": "B","text": "Rapid, shallow breathing during exertion"},{"key": "C","text": "Avoiding any structured breathing technique"},{"key": "D","text": "Complete breath-holding during physical activity"}],"correct": "A","explanation": "Pursed-lip breathing combined with activity pacing helps COPD patients manage dyspnea and maintain better oxygenation during functional tasks."},{"id": 4609,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes appropriate exercise progression for a patient recovering from open-heart surgery (e.g., CABG) regarding sternal precautions?","options": [{"key": "A","text": "Immediate unrestricted heavy upper body resistance training"},{"key": "B","text": "No specific precautions are needed following sternotomy"},{"key": "C","text": "Complete avoidance of any upper body movement indefinitely"},{"key": "D","text": "Avoiding heavy lifting, pushing, or pulling with the arms, and limiting excessive shoulder range initially per surgeon guidance"}],"correct": "D","explanation": "Sternal precautions protect the healing sternotomy site from excessive stress during the early postoperative period, typically limiting certain arm movements and loading for several weeks."},{"id": 4610,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Exercise therapy for children with cerebral palsy commonly incorporates which approach to address both impairment and functional goals?","options": [{"key": "A","text": "Complete avoidance of any strength training due to spasticity concerns"},{"key": "B","text": "Task-specific, goal-directed functional training combined with strengthening and stretching as needed"},{"key": "C","text": "Only isolated muscle strengthening without functional context"},{"key": "D","text": "Purely passive treatment without any active participation"}],"correct": "B","explanation": "Modern pediatric CP rehabilitation emphasizes functional, meaningful goal-directed practice, incorporating strengthening (shown to be safe and beneficial) alongside addressing spasticity/contracture."},{"id": 4611,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Serial casting is sometimes used in pediatric physiotherapy to address which musculoskeletal issue?","options": [{"key": "A","text": "Balance training exclusively"},{"key": "B","text": "Muscle/joint contractures, gradually increasing range of motion over time"},{"key": "C","text": "Muscle strengthening exclusively"},{"key": "D","text": "Cardiovascular conditioning"}],"correct": "B","explanation": "Serial casting applies progressive, sustained stretch through sequential cast changes to gradually improve range of motion in contracted joints, common in pediatric neurological conditions."},{"id": 4612,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important consideration when prescribing exercise for a child with Duchenne muscular dystrophy?","options": [{"key": "A","text": "Avoiding high-resistance/eccentric exercise that may accelerate muscle damage, favoring moderate aerobic and functional activity"},{"key": "B","text": "Encouraging maximal resistance training to build muscle strength aggressively"},{"key": "C","text": "Complete avoidance of any physical activity"},{"key": "D","text": "Only providing passive range of motion without any active component"}],"correct": "A","explanation": "Given DMD's progressive muscle degeneration, high-intensity or eccentric-heavy resistance training may accelerate damage, so moderate, functional activity is generally favored."},{"id": 4613,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise therapy approaches is appropriate for a child with developmental coordination disorder?","options": [{"key": "A","text": "Purely passive treatment without active practice"},{"key": "B","text": "Task-specific motor skill practice targeting functional activities relevant to the child's daily life"},{"key": "C","text": "Only addressing cognitive skills without any motor component"},{"key": "D","text": "Avoiding any motor skill practice due to coordination difficulty"}],"correct": "B","explanation": "Task-oriented approaches, practicing specific functional motor skills the child needs, are generally supported for improving performance in developmental coordination disorder."},{"id": 4614,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Easy","question": "Which exercise consideration is important for elderly patients with age-related sarcopenia when prescribing resistance training?","options": [{"key": "A","text": "Assuming no benefit exists for this population"},{"key": "B","text": "Avoiding resistance training entirely due to age"},{"key": "C","text": "Starting with appropriate, individualized loads and progressing gradually while monitoring tolerance"},{"key": "D","text": "Using only maximal loads regardless of baseline fitness"}],"correct": "C","explanation": "Even frail elderly patients can safely benefit from appropriately dosed, progressive resistance training to counter sarcopenia, with careful individualization and monitoring."},{"id": 4615,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is a common barrier to exercise participation in elderly patients that physiotherapists should address in program design?","options": [{"key": "A","text": "Complete absence of any comorbidities"},{"key": "B","text": "Excessive enthusiasm for high-intensity training"},{"key": "C","text": "Fear of falling, which may require starting with supported/safer exercise conditions"},{"key": "D","text": "Only relevant to younger patient populations"}],"correct": "C","explanation": "Fear of falling is a well-recognized barrier in older adults; addressing this through graded, supported exercise progression can improve participation and outcomes."},{"id": 4616,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Pelvic floor exercises during pregnancy are commonly recommended primarily to help prevent or manage:","options": [{"key": "A","text": "Preeclampsia"},{"key": "B","text": "Gestational diabetes exclusively"},{"key": "C","text": "Fetal growth restriction"},{"key": "D","text": "Urinary incontinence and support pelvic organ function during and after pregnancy"}],"correct": "D","explanation": "Pregnancy-related hormonal and mechanical changes stress the pelvic floor, making targeted strengthening exercises beneficial for preventing/managing incontinence."},{"id": 4617,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise precautions is important for pregnant patients regarding core exercises involving significant abdominal wall tension?","options": [{"key": "A","text": "Being cautious with exercises that may exacerbate diastasis recti (abdominal separation)"},{"key": "B","text": "No modification of core exercise is needed during pregnancy"},{"key": "C","text": "Encouraging maximal abdominal crunching exercises throughout pregnancy"},{"key": "D","text": "Complete avoidance of any core-related exercise, including gentle activation"}],"correct": "A","explanation": "Certain high-tension abdominal exercises can worsen diastasis recti, a common pregnancy-related condition, so exercise modification and gentler core activation techniques are often recommended."},{"id": 4618,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is a general exercise recommendation for postpartum patients returning to exercise after vaginal delivery without complications?","options": [{"key": "A","text": "No individualized consideration is needed regardless of delivery type"},{"key": "B","text": "Gradual return to activity based on individual recovery, often beginning with gentle pelvic floor and light activity within the first weeks"},{"key": "C","text": "Complete avoidance of any physical activity for one full year"},{"key": "D","text": "Immediate return to pre-pregnancy high-intensity training on day one"}],"correct": "B","explanation": "Postpartum exercise progression should be individualized based on recovery, delivery type, and any complications, typically starting gently before progressing to more vigorous activity."},{"id": 4619,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Return-to-sport testing following an athletic injury commonly includes assessment of which functional components?","options": [{"key": "A","text": "Only resting heart rate"},{"key": "B","text": "Cognitive testing exclusively without any physical assessment"},{"key": "C","text": "Only passive range of motion without any functional testing"},{"key": "D","text": "Strength symmetry, hop tests, and sport-specific movement quality"}],"correct": "D","explanation": "Comprehensive return-to-sport criteria typically combine strength, functional hop testing, and movement quality assessment to determine readiness beyond simple time-based criteria."},{"id": 4620,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate approach to youth (adolescent) resistance training from a safety perspective?","options": [{"key": "A","text": "Complete avoidance of any resistance training until adulthood"},{"key": "B","text": "Encouraging maximal, unsupervised heavy lifting regardless of technique"},{"key": "C","text": "Resistance training in youth always causes growth plate damage"},{"key": "D","text": "Properly supervised, technique-focused resistance training with appropriate progression is generally considered safe and beneficial"}],"correct": "D","explanation": "Current evidence and professional guidelines support properly supervised, well-designed resistance training programs as safe and beneficial for healthy youth athletes."},{"id": 4621,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important consideration for exercise therapy in an athlete recovering from a concussion?","options": [{"key": "A","text": "Complete indefinite avoidance of any physical activity regardless of symptom resolution"},{"key": "B","text": "Following a structured, graded return-to-play protocol with progressive exertion while monitoring for symptom recurrence"},{"key": "C","text": "Ignoring any symptoms that occur during the graded return process"},{"key": "D","text": "Immediate full-intensity return to sport with no graded progression"}],"correct": "B","explanation": "Concussion management protocols use a stepwise increase in physical exertion, closely monitoring for symptom return before progressing to the next stage, to ensure safe return to sport."},{"id": 4622,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is a key consideration in exercise prescription for an obese patient beginning a rehabilitation program?","options": [{"key": "A","text": "Immediately prescribing high-impact running regardless of joint stress"},{"key": "B","text": "Choosing lower-impact activities initially to reduce joint stress while building tolerance progressively"},{"key": "C","text": "Assuming no modification from a standard program is needed"},{"key": "D","text": "Avoiding any form of exercise until significant weight loss occurs"}],"correct": "B","explanation": "Lower-impact activity options (e.g., cycling, aquatic exercise) can reduce excessive joint loading in obese patients while still providing effective cardiovascular and strength benefits during initial program phases."},{"id": 4623,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important consideration when designing exercise therapy for an athlete with a history of exercise-induced bronchospasm?","options": [{"key": "A","text": "Assuming no modification to standard exercise prescription is necessary"},{"key": "B","text": "Avoiding all forms of exercise indefinitely"},{"key": "C","text": "Ignoring any respiratory symptoms during activity"},{"key": "D","text": "Ensuring appropriate pre-exercise medication use (if prescribed) and monitoring for respiratory symptoms during activity"}],"correct": "D","explanation": "Athletes with exercise-induced bronchospasm often benefit from appropriate pre-treatment and monitoring strategies, allowing continued safe participation in physical activity."},{"id": 4624,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The Visual Analog Scale (VAS) is a commonly used outcome measure primarily assessing:","options": [{"key": "A","text": "Objective muscle strength"},{"key": "B","text": "Joint range of motion directly"},{"key": "C","text": "Patient-reported pain intensity"},{"key": "D","text": "Cardiovascular endurance"}],"correct": "C","explanation": "The VAS is a simple, widely used self-report tool where patients mark their perceived pain intensity along a continuous line, typically 0-10cm."},{"id": 4625,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The Numeric Pain Rating Scale (NPRS) differs from the Visual Analog Scale primarily in that it:","options": [{"key": "A","text": "Cannot be used to assess pain at all"},{"key": "B","text": "Requires specialized equipment unavailable in most clinics"},{"key": "C","text": "Only assesses joint range of motion"},{"key": "D","text": "Uses a numbered scale (typically 0-10) for the patient to verbally or in writing indicate pain intensity"}],"correct": "D","explanation": "The NPRS is a simple, easy-to-administer verbal/written numeric rating tool, often preferred for its practicality compared to the VAS's need for precise line measurement."},{"id": 4626,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Patient-Specific Functional Scale (PSFS) is unique among outcome measures in that it:","options": [{"key": "A","text": "Cannot be used to track progress over time"},{"key": "B","text": "Uses a fixed, standardized list of activities identical for every patient"},{"key": "C","text": "Only assesses pain, not function"},{"key": "D","text": "Allows patients to identify and rate their own specific functional activities affected by their condition"}],"correct": "D","explanation": "The PSFS individualizes assessment by having patients nominate meaningful activities specific to their own functional limitations, then rating difficulty, allowing personalized progress tracking."},{"id": 4627,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Lower Extremity Functional Scale (LEFS) is a self-report outcome measure used to assess:","options": [{"key": "A","text": "Cardiovascular endurance exclusively"},{"key": "B","text": "Functional limitations related to lower extremity musculoskeletal conditions"},{"key": "C","text": "Upper extremity function exclusively"},{"key": "D","text": "Cognitive function exclusively"}],"correct": "B","explanation": "The LEFS is a validated questionnaire capturing patient-perceived difficulty with various functional activities due to lower limb musculoskeletal conditions."},{"id": 4628,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Neck Disability Index (NDI) is specifically designed to assess functional limitation related to:","options": [{"key": "A","text": "Lower extremity conditions exclusively"},{"key": "B","text": "Cervical spine (neck) conditions"},{"key": "C","text": "Shoulder conditions exclusively"},{"key": "D","text": "Lumbar spine conditions exclusively"}],"correct": "B","explanation": "The NDI is a well-validated self-report questionnaire assessing the impact of neck pain/dysfunction on various daily activities."},{"id": 4629,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best describes the purpose of using standardized, validated outcome measures in physiotherapy practice?","options": [{"key": "A","text": "Only relevant for research purposes, not clinical practice"},{"key": "B","text": "Replacing the need for any clinical judgment entirely"},{"key": "C","text": "Providing objective, reliable tracking of patient progress and supporting evidence-based clinical decision-making"},{"key": "D","text": "Having no bearing on communication with other healthcare providers"}],"correct": "C","explanation": "Standardized outcome measures provide objective data to track progress, guide treatment decisions, and facilitate communication among the healthcare team, complementing clinical judgment."},{"id": 4630,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes 'minimal clinically important difference' (MCID) in the context of outcome measures?","options": [{"key": "A","text": "The maximum possible score on any outcome measure"},{"key": "B","text": "A value that has no clinical relevance to patient care"},{"key": "C","text": "The smallest change in an outcome score that represents a meaningful improvement to the patient"},{"key": "D","text": "Only applicable to laboratory-based measures, not clinical outcome tools"}],"correct": "C","explanation": "MCID represents the threshold change considered meaningful from the patient's perspective, helping clinicians interpret whether observed score changes reflect true clinical improvement."},{"id": 4631,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 30-second sit-to-stand test is commonly used to assess:","options": [{"key": "A","text": "Functional lower extremity strength and power in a practical clinical setting"},{"key": "B","text": "Static balance exclusively without any strength component"},{"key": "C","text": "Cognitive processing speed exclusively"},{"key": "D","text": "Upper extremity strength exclusively"}],"correct": "A","explanation": "This test counts the number of stand-to-sit repetitions completed in 30 seconds, providing a practical measure of functional lower limb strength/power, especially useful in older adult assessment."},{"id": 4632,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Functional Reach Test is used clinically to assess:","options": [{"key": "A","text": "Dynamic balance by measuring how far a person can reach forward without losing balance"},{"key": "B","text": "Cognitive function"},{"key": "C","text": "Isolated muscle strength grading"},{"key": "D","text": "Cardiovascular endurance"}],"correct": "A","explanation": "This simple test measures the maximum forward reach distance a person can achieve while maintaining a fixed base of support, correlating with fall risk."},{"id": 4633,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following outcome measures would be most appropriate for assessing overall health-related quality of life, rather than a specific body region or condition?","options": [{"key": "A","text": "DASH questionnaire specifically"},{"key": "B","text": "Oswestry Disability Index specifically"},{"key": "C","text": "SF-36 (Short Form 36 Health Survey)"},{"key": "D","text": "LEFS specifically"}],"correct": "C","explanation": "The SF-36 is a generic, comprehensive health status questionnaire assessing multiple domains of quality of life, unlike condition-specific tools focused on a particular body region."},{"id": 4634,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Modified Ashworth Scale is a clinical tool used to assess:","options": [{"key": "A","text": "Balance performance"},{"key": "B","text": "Muscle strength grading"},{"key": "C","text": "Joint range of motion in degrees"},{"key": "D","text": "Degree of muscle spasticity/resistance to passive movement"}],"correct": "D","explanation": "The Modified Ashworth Scale grades resistance felt during passive muscle stretch on a 0-4 scale, widely used to quantify spasticity in neurological conditions."},{"id": 4635,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following best describes test-retest reliability as applied to outcome measures used in physiotherapy?","options": [{"key": "A","text": "The consistency of results obtained when the same test is repeated under similar conditions"},{"key": "B","text": "The cost-effectiveness of using the test"},{"key": "C","text": "The ability of a test to measure what it claims to measure"},{"key": "D","text": "The ease of administering the test"}],"correct": "A","explanation": "Test-retest reliability specifically refers to the consistency/reproducibility of scores when a measure is repeated, an important psychometric property for tracking genuine change over time."},{"id": 4636,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following best describes the concept of 'validity' as applied to an outcome measure?","options": [{"key": "A","text": "The extent to which the measure actually assesses what it is intended to assess"},{"key": "B","text": "Whether the same result is obtained on repeated testing"},{"key": "C","text": "The cost associated with using the measure"},{"key": "D","text": "How quickly the test can be administered"}],"correct": "A","explanation": "Validity concerns whether a tool truly captures the construct it intends to measure (e.g., whether a 'function' questionnaire genuinely reflects functional ability)."},{"id": 4637,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Grip strength dynamometry is commonly used as an outcome measure, particularly relevant for assessing:","options": [{"key": "A","text": "Balance performance exclusively"},{"key": "B","text": "Overall upper extremity strength and, in some populations, general frailty/nutritional status"},{"key": "C","text": "Only isolated wrist range of motion"},{"key": "D","text": "Cardiovascular fitness exclusively"}],"correct": "B","explanation": "Handheld dynamometry provides an objective measure of grip strength, useful for tracking hand/upper limb rehabilitation progress and as a broader marker of overall strength/frailty in some populations."},{"id": 4638,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The Visual Analog Scale (VAS) is commonly used in physiotherapy practice to assess:","options": [{"key": "A","text": "Range of motion in degrees"},{"key": "B","text": "Cardiovascular endurance"},{"key": "C","text": "Objective muscle strength"},{"key": "D","text": "Patient's subjective pain intensity"}],"correct": "D","explanation": "The VAS provides a simple, widely used method for patients to rate their pain intensity along a continuous scale, aiding treatment monitoring."},{"id": 4639,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The Numeric Pain Rating Scale (NPRS) typically asks patients to rate their pain on a scale of:","options": [{"key": "A","text": "0 to 10"},{"key": "B","text": "1 to 100"},{"key": "C","text": "Only 'mild, moderate, severe' categories"},{"key": "D","text": "A to E"}],"correct": "A","explanation": "The NPRS is a simple 0-10 scale where patients numerically rate pain intensity, widely used due to its ease of administration and interpretation."},{"id": 4640,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "A Modified Ashworth Scale score of 0 indicates:","options": [{"key": "A","text": "No increase in muscle tone (normal tone)"},{"key": "B","text": "Complete inability to move the limb passively"},{"key": "C","text": "Slight increase in tone with a catch at end of range"},{"key": "D","text": "Severe spasticity with rigid resistance throughout range"}],"correct": "A","explanation": "A score of 0 represents normal muscle tone with no resistance to passive movement, the baseline of the Ashworth grading scale."},{"id": 4641,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 10-Meter Walk Test is commonly used to assess:","options": [{"key": "A","text": "Static balance only"},{"key": "B","text": "Isolated upper extremity function"},{"key": "C","text": "Gait speed over a set distance"},{"key": "D","text": "Pulmonary function exclusively"}],"correct": "C","explanation": "This straightforward, validated test measures the time taken to walk 10 meters, providing an objective gait speed measurement useful across many patient populations."},{"id": 4642,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Gait speed, as measured by tests like the 10-meter walk test, has been shown in research to correlate with:","options": [{"key": "A","text": "Cognitive function exclusively, unrelated to physical health"},{"key": "B","text": "No meaningful clinical significance"},{"key": "C","text": "Only relevant to elite athletic performance"},{"key": "D","text": "Overall functional status and health outcomes in various populations, sometimes called a 'vital sign'"}],"correct": "D","explanation": "Gait speed has emerged as a strong predictor of functional decline, hospitalization, and mortality risk in various populations, earning it recognition as a potential 'sixth vital sign'."},{"id": 4643,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The Fugl-Meyer Assessment is a standardized outcome measure commonly used to assess motor recovery in which patient population?","options": [{"key": "A","text": "Healthy athletes"},{"key": "B","text": "Stroke patients"},{"key": "C","text": "Patients with pulmonary disease exclusively"},{"key": "D","text": "Patients with isolated peripheral musculoskeletal injuries only"}],"correct": "B","explanation": "The Fugl-Meyer Assessment is a well-established tool for quantifying motor impairment and recovery specifically in stroke rehabilitation."},{"id": 4644,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Manual muscle testing and goniometry are both examples of which broad category of physiotherapy assessment tools?","options": [{"key": "A","text": "Purely participation-level measures"},{"key": "B","text": "Purely activity-level (functional) measures"},{"key": "C","text": "Purely psychosocial assessment tools"},{"key": "D","text": "Impairment-level measures (assessing body structure/function)"}],"correct": "D","explanation": "MMT and goniometry assess specific impairments in strength and range of motion at the body structure/function level, distinct from broader activity or participation-level outcome measures."},{"id": 4645,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 6-Minute Walk Test and Timed Up and Go test are best classified as which category of outcome measure?","options": [{"key": "A","text": "Purely participation-level/quality-of-life measures"},{"key": "B","text": "Purely psychological assessment tools"},{"key": "C","text": "Activity-level (functional performance) measures"},{"key": "D","text": "Purely impairment-level measures"}],"correct": "C","explanation": "These tests assess the patient's functional performance during real-world-relevant activities, situating them at the activity level of the International Classification of Functioning (ICF) framework."},{"id": 4646,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The International Classification of Functioning, Disability and Health (ICF) framework categorizes health-related concepts into which broad domains?","options": [{"key": "A","text": "Body structure/function, activity, and participation"},{"key": "B","text": "Only pain and range of motion"},{"key": "C","text": "Only cardiovascular and pulmonary parameters"},{"key": "D","text": "Only psychological and cognitive domains"}],"correct": "A","explanation": "The ICF provides a comprehensive framework for understanding health and disability across body function/structure, activity, and participation domains, widely used to guide holistic physiotherapy assessment and goal-setting."},{"id": 4647,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best describes the purpose of using standardized outcome measures repeatedly throughout a course of physiotherapy treatment?","options": [{"key": "A","text": "Purely for billing/administrative purposes with no clinical value"},{"key": "B","text": "Objectively tracking a patient's progress and guiding clinical decision-making regarding treatment effectiveness"},{"key": "C","text": "Standardized measures cannot detect meaningful clinical change"},{"key": "D","text": "Only for initial diagnosis with no ongoing relevance"}],"correct": "B","explanation": "Serial administration of validated outcome measures allows therapists to objectively document progress, informing decisions about continuing, modifying, or discharging from treatment."},{"id": 4648,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Minimal clinically important difference (MCID) refers to:","options": [{"key": "A","text": "A measure only relevant to statistical significance, not clinical relevance"},{"key": "B","text": "The maximum possible score on any outcome measure"},{"key": "C","text": "A value that is identical across all outcome measures and conditions"},{"key": "D","text": "The smallest change in an outcome measure score considered meaningful to the patient"}],"correct": "D","explanation": "MCID represents the threshold of change that patients or clinicians would consider a clinically meaningful improvement, distinct from purely statistical significance."},{"id": 4649,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Reliability of an outcome measure refers to:","options": [{"key": "A","text": "The consistency of results when the measure is repeated under similar conditions"},{"key": "B","text": "Whether the measure accurately assesses what it claims to measure"},{"key": "C","text": "The ease of administering the test"},{"key": "D","text": "The cost of using the assessment tool"}],"correct": "A","explanation": "Reliability specifically addresses measurement consistency/reproducibility, a distinct psychometric property from validity (which addresses accuracy of what is being measured)."},{"id": 4650,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Validity of an outcome measure refers to:","options": [{"key": "A","text": "The consistency of repeated measurements"},{"key": "B","text": "How quickly the test can be administered"},{"key": "C","text": "The measure's popularity among clinicians"},{"key": "D","text": "Whether the tool accurately measures the construct it is intended to assess"}],"correct": "D","explanation": "Validity addresses whether a tool truly captures the underlying construct of interest (e.g., does a 'balance' test actually measure balance ability), distinct from reliability."},{"id": 4651,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which energy system replenishes phosphocreatine stores most rapidly during rest intervals between high-intensity exercise bouts?","options": [{"key": "A","text": "Only occurs during sleep"},{"key": "B","text": "Aerobic (oxidative) system"},{"key": "C","text": "The system does not replenish without complete days of rest"},{"key": "D","text": "Anaerobic glycolysis exclusively"}],"correct": "B","explanation": "Phosphocreatine resynthesis primarily relies on aerobic metabolism during recovery periods, which is why rest interval duration matters in interval training design."},{"id": 4652,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Excess post-exercise oxygen consumption (EPOC) refers to:","options": [{"key": "A","text": "A phenomenon unrelated to exercise intensity"},{"key": "B","text": "Complete absence of any metabolic cost after exercise ends"},{"key": "C","text": "The elevated oxygen consumption that persists after exercise to restore the body to baseline (repay oxygen debt)"},{"key": "D","text": "Oxygen consumption only during the exercise bout itself"}],"correct": "C","explanation": "EPOC reflects the ongoing metabolic cost of recovery processes (e.g., restoring ATP-PCr, clearing lactate) following exercise, contributing to overall caloric expenditure."},{"id": 4653,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The lactate threshold refers to the exercise intensity at which:","options": [{"key": "A","text": "The heart rate reaches its absolute maximum"},{"key": "B","text": "Only aerobic metabolism is active with zero lactate production"},{"key": "C","text": "Lactate production completely stops"},{"key": "D","text": "Blood lactate begins to accumulate disproportionately faster than it can be cleared"}],"correct": "D","explanation": "Lactate threshold marks the point where lactate production exceeds clearance capacity, often used to guide training intensity zones for endurance athletes."},{"id": 4654,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes 'active recovery' following intense exercise?","options": [{"key": "A","text": "Immediately repeating the same high-intensity exercise"},{"key": "B","text": "Only stretching without any movement"},{"key": "C","text": "Performing low-intensity activity to promote blood flow and metabolic waste clearance"},{"key": "D","text": "Complete inactivity/rest immediately following exercise"}],"correct": "C","explanation": "Active recovery uses gentle continued movement to maintain circulation, which may help facilitate clearance of metabolic byproducts compared to complete immediate rest."},{"id": 4655,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercises would be classified as an open kinetic chain exercise for the lower extremity?","options": [{"key": "A","text": "Seated knee extension with the foot free in space"},{"key": "B","text": "Lunges with the front foot fixed"},{"key": "C","text": "Standing calf raises"},{"key": "D","text": "Squatting with feet fixed on the ground"}],"correct": "A","explanation": "Seated knee extension moves the distal segment (foot/lower leg) freely, meeting the definition of an open kinetic chain exercise."},{"id": 4656,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an appropriate rationale for progressing a patient from open kinetic chain to closed kinetic chain exercises during lower extremity rehabilitation?","options": [{"key": "A","text": "There is no meaningful biomechanical difference between the two exercise types"},{"key": "B","text": "Open chain exercises always better replicate functional activity"},{"key": "C","text": "Closed chain exercises often better simulate functional weight-bearing activities and promote co-contraction for joint stability"},{"key": "D","text": "Closed chain exercises are always contraindicated in early rehabilitation"}],"correct": "C","explanation": "Closed chain exercises typically offer greater functional carryover to daily activities requiring weight-bearing, along with beneficial co-contraction patterns for joint stability."},{"id": 4657,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "A muscle energy technique using 'reciprocal inhibition' involves contracting which muscle to help relax and lengthen its antagonist?","options": [{"key": "A","text": "The antagonist muscle of the tight/restricted muscle"},{"key": "B","text": "No muscle contraction is used in this technique"},{"key": "C","text": "The tight muscle itself"},{"key": "D","text": "Only muscles unrelated to the restricted joint"}],"correct": "A","explanation": "Reciprocal inhibition techniques have the patient contract the antagonist to the tight muscle, which reflexively facilitates relaxation of the tight muscle through neurological inhibition."},{"id": 4658,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which stretching technique would be contraindicated immediately following acute muscle strain injury (within the first 24-48 hours)?","options": [{"key": "A","text": "Rest and protection of the injured area"},{"key": "B","text": "Gentle, pain-free range of motion within tolerance"},{"key": "C","text": "Aggressive, forceful stretching of the injured muscle"},{"key": "D","text": "Ice application to the injured area"}],"correct": "C","explanation": "Aggressive stretching during the acute inflammatory phase can worsen tissue damage; gentle, protected movement within pain-free limits is generally more appropriate initially."},{"id": 4659,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which balance training progression would be appropriate immediately after a patient successfully masters double-leg stance on a firm, stable surface with eyes open?","options": [{"key": "A","text": "Double-leg stance on a firm surface with eyes closed, or single-leg stance on a stable surface"},{"key": "B","text": "Immediately progressing to single-leg stance on an unstable surface with eyes closed"},{"key": "C","text": "No further progression is needed after mastering basic stance"},{"key": "D","text": "Regressing to seated balance activities"}],"correct": "A","explanation": "Balance training should progress systematically, introducing one additional challenge at a time (e.g., removing vision or narrowing base of support) rather than combining multiple difficult variables at once."},{"id": 4660,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which gait deviation might be observed in a patient with hip flexor weakness during the swing phase of gait?","options": [{"key": "A","text": "Excessive hip flexion during swing"},{"key": "B","text": "Only affects the stance phase, not swing"},{"key": "C","text": "Reduced hip and knee flexion during swing, potentially causing toe drag or compensatory hip hiking"},{"key": "D","text": "No effect on swing phase mechanics"}],"correct": "C","explanation": "Weak hip flexors impair the ability to adequately flex the hip and advance the limb during swing, potentially causing toe drag or compensatory strategies like hip hiking or circumduction."},{"id": 4661,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Circumduction gait pattern, where the leg swings outward in a semicircular arc during swing phase, is commonly seen as a compensation for:","options": [{"key": "A","text": "Inadequate knee flexion or hip flexion during swing phase (e.g., from spasticity or weakness)"},{"key": "B","text": "Normal, unimpaired gait mechanics"},{"key": "C","text": "Isolated ankle sprain only"},{"key": "D","text": "Excessive flexibility of the hip joint"}],"correct": "A","explanation": "Circumduction is a compensatory strategy allowing the limb to clear the ground when normal hip/knee flexion during swing is insufficient, often seen with spasticity or significant weakness."},{"id": 4662,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the primary goal of proprioceptive training exercises following an ankle sprain?","options": [{"key": "A","text": "Retraining joint position sense and neuromuscular control to reduce risk of re-injury"},{"key": "B","text": "Eliminating any need for balance-related rehabilitation"},{"key": "C","text": "Purely improving cardiovascular fitness"},{"key": "D","text": "Only increasing muscle bulk around the ankle"}],"correct": "A","explanation": "Ankle sprains commonly impair proprioceptive feedback from joint mechanoreceptors; targeted proprioceptive/balance training helps restore neuromuscular control and reduce recurrent sprain risk."},{"id": 4663,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following would be an appropriate exercise therapy consideration for a patient with a diagnosed vestibular schwannoma affecting balance?","options": [{"key": "A","text": "Assuming exercise therapy has no role in this condition"},{"key": "B","text": "Complete avoidance of any balance training regardless of symptoms"},{"key": "C","text": "Immediate aggressive vestibular exercises without any medical coordination"},{"key": "D","text": "Coordination with the medical team regarding surgical/treatment plans, with balance/vestibular rehabilitation often indicated post-intervention"}],"correct": "D","explanation": "Vestibular schwannoma management often involves surgery or other medical intervention, with balance rehabilitation frequently indicated as part of the broader treatment and recovery plan."},{"id": 4664,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate approach to functional electrical stimulation combined with exercise therapy in patients with foot drop from stroke?","options": [{"key": "A","text": "Using stimulation only during static sitting with no functional gait component"},{"key": "B","text": "Using stimulation timed with the gait cycle to assist ankle dorsiflexion during swing phase, alongside active gait training"},{"key": "C","text": "Providing continuous, non-timed stimulation regardless of gait phase"},{"key": "D","text": "Avoiding any combination of stimulation with active exercise"}],"correct": "B","explanation": "Functional electrical stimulation devices are typically timed to activate ankle dorsiflexors specifically during the swing phase of gait, complementing active gait rehabilitation for foot drop."},{"id": 4665,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an appropriate consideration when progressing a patient with chronic obstructive pulmonary disease through an aerobic exercise program?","options": [{"key": "A","text": "Immediate high-intensity training regardless of respiratory symptoms"},{"key": "B","text": "Complete avoidance of aerobic exercise due to lung disease"},{"key": "C","text": "Gradual progression of duration/intensity while closely monitoring dyspnea and oxygen saturation"},{"key": "D","text": "No need to monitor oxygen saturation during exercise sessions"}],"correct": "C","explanation": "COPD exercise progression should be gradual and closely monitored, as respiratory limitations may require slower advancement compared to patients without pulmonary impairment."},{"id": 4666,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes an appropriate physiotherapy exercise consideration for a patient with fibromyalgia?","options": [{"key": "A","text": "Starting with low-intensity aerobic and gentle strengthening exercise, progressing very gradually due to symptom sensitivity"},{"key": "B","text": "Complete avoidance of any exercise due to widespread pain"},{"key": "C","text": "Only passive treatment without any active exercise component"},{"key": "D","text": "Immediate high-intensity training regardless of symptom flare risk"}],"correct": "A","explanation": "Fibromyalgia patients often have heightened pain sensitivity to exercise; a gentle, gradually progressive approach helps build tolerance while minimizing symptom exacerbation."},{"id": 4667,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'graded exposure' as sometimes used in exercise therapy for patients with significant fear-avoidance behavior related to pain?","options": [{"key": "A","text": "A concept with no relevance to physiotherapy practice"},{"key": "B","text": "Immediately forcing maximal painful movements without gradual progression"},{"key": "C","text": "Avoiding all potentially painful movements indefinitely"},{"key": "D","text": "Gradually and systematically exposing the patient to previously feared movements/activities to reduce fear and disability"}],"correct": "D","explanation": "Graded exposure applies principles from psychology to gradually reintroduce feared movements in a controlled, systematic way, helping reduce fear-avoidance behavior and associated disability in chronic pain conditions."},{"id": 4668,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise therapy considerations would be important for a patient with hemophilia participating in a strengthening program?","options": [{"key": "A","text": "Choosing lower-impact activities and avoiding high-risk contact/collision activities to minimize bleeding risk"},{"key": "B","text": "Encouraging high-impact contact sports without modification"},{"key": "C","text": "Assuming no precautions are needed regardless of bleeding disorder status"},{"key": "D","text": "Complete avoidance of any physical activity indefinitely"}],"correct": "A","explanation": "Given the bleeding risk associated with hemophilia, exercise selection should favor lower-impact, controlled activities while avoiding high-risk contact sports that could trigger hemarthrosis."},{"id": 4669,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best describes an appropriate goal-setting approach in physiotherapy exercise prescription?","options": [{"key": "A","text": "Goals unrelated to the patient's actual functional priorities"},{"key": "B","text": "Collaborative, patient-centered goals that are specific, measurable, achievable, relevant, and time-bound (SMART)"},{"key": "C","text": "Goals determined entirely by the therapist without patient input"},{"key": "D","text": "Vague, non-specific goals without any measurable criteria"}],"correct": "B","explanation": "SMART goal-setting, developed collaboratively with the patient, helps ensure exercise therapy is meaningful, trackable, and aligned with the patient's actual priorities and needs."},{"id": 4670,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Which of the following describes the primary rationale for using low-load, blood flow restriction (BFR) resistance training in certain rehabilitation settings?","options": [{"key": "A","text": "Achieving strength/hypertrophy benefits similar to heavy resistance training using much lower loads, useful when heavy loading is contraindicated"},{"key": "B","text": "Complete restriction of all blood flow indefinitely during exercise"},{"key": "C","text": "A technique with no scientific rationale or evidence"},{"key": "D","text": "Only used for cardiovascular conditioning with no strength benefit"}],"correct": "A","explanation": "BFR training combines light loads with partial venous restriction to create metabolic stress that stimulates strength/hypertrophy gains, useful post-surgically when heavy loading may not yet be appropriate."},{"id": 4671,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which population might particularly benefit from blood flow restriction training as an adjunct to traditional rehabilitation exercise?","options": [{"key": "A","text": "Post-surgical patients unable to tolerate heavy loading but needing to prevent excessive muscle atrophy"},{"key": "B","text": "Only elite powerlifters with no rehabilitation needs"},{"key": "C","text": "Patients with no restrictions on loading capacity"},{"key": "D","text": "Patients with untreated deep vein thrombosis"}],"correct": "A","explanation": "BFR is particularly useful in early post-surgical rehabilitation, allowing meaningful strength stimulus despite load restrictions, though appropriate screening for contraindications like DVT is essential."},{"id": 4672,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following represents an important contraindication to consider before implementing blood flow restriction training?","options": [{"key": "A","text": "Presence of mild, well-controlled hypertension only"},{"key": "B","text": "History of deep vein thrombosis or significant cardiovascular risk factors"},{"key": "C","text": "Patient preference for lower exercise intensity"},{"key": "D","text": "Simple post-operative muscle weakness alone"}],"correct": "B","explanation": "Given the restricted venous return during BFR training, patients with clotting risk factors require careful screening and often exclusion from this technique."},{"id": 4673,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise therapy considerations applies to a patient with a recent total shoulder arthroplasty regarding early passive range of motion?","options": [{"key": "A","text": "No protocol considerations are needed regardless of surgical approach"},{"key": "B","text": "Complete immobilization with no passive movement for months"},{"key": "C","text": "Following surgeon-specific protocols that typically limit certain movements (e.g., external rotation) to protect the repair initially"},{"key": "D","text": "Immediate unrestricted full range of motion in all directions"}],"correct": "C","explanation": "Total shoulder arthroplasty protocols typically restrict certain movements (particularly external rotation if subscapularis was repaired) during early healing to protect the surgical repair."},{"id": 4674,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate approach to therapeutic exercise for a patient with chronic fatigue syndrome/myalgic encephalomyelitis?","options": [{"key": "A","text": "Complete avoidance of any physical activity indefinitely"},{"key": "B","text": "Ignoring any post-exertional symptom worsening"},{"key": "C","text": "Very gradual, carefully paced activity progression with close attention to avoiding post-exertional symptom exacerbation"},{"key": "D","text": "Aggressive graded exercise therapy regardless of symptom response"}],"correct": "C","explanation": "Current understanding emphasizes cautious, individualized pacing in this population due to the risk of post-exertional malaise, differing from more standard graded exercise approaches used in other conditions."},{"id": 4675,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following exercise therapy considerations is important for a patient with ehlers-danlos syndrome (joint hypermobility) undergoing strengthening exercise?","options": [{"key": "A","text": "Avoiding all strengthening exercise entirely"},{"key": "B","text": "Encouraging maximal end-range stretching to further increase flexibility"},{"key": "C","text": "Assuming no modification is needed compared to a hypomobile patient"},{"key": "D","text": "Emphasizing proprioceptive and stability training alongside strengthening to protect hypermobile joints from excessive strain"}],"correct": "D","explanation": "Given the increased joint instability risk in EDS, exercise programs typically emphasize proprioception, controlled stability training, and cautious strengthening rather than further increasing flexibility."},{"id": 4676,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following is an appropriate exercise therapy consideration for a patient with a diagnosed abdominal aortic aneurysm below a certain size threshold, participating in supervised exercise?","options": [{"key": "A","text": "Following physician clearance and avoiding excessive Valsalva/straining during resistance exercise"},{"key": "B","text": "Ignoring any blood pressure considerations during exercise"},{"key": "C","text": "Immediate high-intensity resistance training with heavy Valsalva breathing"},{"key": "D","text": "Complete avoidance of any physical activity regardless of aneurysm size"}],"correct": "A","explanation": "Patients with AAA require medical clearance and careful avoidance of exercises causing significant blood pressure spikes (e.g., heavy Valsalva-associated lifting) to minimize aneurysm-related risk."},{"id": 4677,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate rationale for incorporating dual-task gait training in patients with mild cognitive impairment or early dementia?","options": [{"key": "A","text": "Contraindicated in this population due to cognitive impairment"},{"key": "B","text": "Only relevant for young, cognitively intact patients"},{"key": "C","text": "Purely for cognitive assessment with no functional/motor relevance"},{"key": "D","text": "Practicing gait under realistic conditions requiring simultaneous cognitive-motor demands, similar to real-world community ambulation"}],"correct": "D","explanation": "Dual-task training addresses the realistic demands of community ambulation, which often requires simultaneous attention to cognitive tasks (e.g., conversation) while walking, relevant across cognitive ability levels including mild impairment."},{"id": 4678,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration for exercise prescription in a patient with a implanted cardiac pacemaker?","options": [{"key": "A","text": "Ignoring manufacturer or physician guidance regarding activity limitations"},{"key": "B","text": "Assuming no restrictions apply regardless of recent implantation"},{"key": "C","text": "Following any device-specific activity restrictions (e.g., limiting overhead arm movement early post-implantation) as advised by the cardiology team"},{"key": "D","text": "Complete avoidance of any exercise indefinitely"}],"correct": "C","explanation": "Pacemaker implantation typically involves temporary restrictions on ipsilateral arm movement/overhead activity to allow lead stabilization, requiring coordination with the cardiology team regarding safe exercise progression."},{"id": 4679,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes an appropriate physiotherapy exercise consideration for a patient with a diagnosed lymphedema following axillary lymph node dissection?","options": [{"key": "A","text": "Complete avoidance of any exercise involving the affected limb"},{"key": "B","text": "Using controlled, graded exercise combined with compression garments, avoiding excessive uncontrolled overexertion of the affected limb"},{"key": "C","text": "Removing compression garments during all exercise sessions"},{"key": "D","text": "Encouraging maximal high-intensity resistance training without any monitoring"}],"correct": "B","explanation": "Contrary to older beliefs, controlled progressive exercise (often combined with compression) is now recognized as beneficial and safe for patients with lymphedema, rather than requiring complete limb rest."},{"id": 4680,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes a key difference between 'strength' and 'power' in the context of exercise therapy terminology?","options": [{"key": "A","text": "Strength and power are identical concepts with no meaningful distinction"},{"key": "B","text": "Strength always requires faster movement than power exercises"},{"key": "C","text": "Power refers only to endurance capacity"},{"key": "D","text": "Power incorporates the rate/speed of force production, while strength refers to maximal force regardless of speed"}],"correct": "D","explanation": "Power is the product of force and velocity (rate of force development), distinguishing it from pure maximal strength which does not account for movement speed."},{"id": 4681,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following exercise parameters would be prioritized when designing a program specifically to improve muscular power in an older adult at risk of falls?","options": [{"key": "A","text": "Maximal load with slow, controlled movement only"},{"key": "B","text": "Moderate load with fast, controlled movement velocity"},{"key": "C","text": "Isometric holds exclusively without any dynamic component"},{"key": "D","text": "Minimal load with no attention to movement speed"}],"correct": "B","explanation": "Power training for fall-risk reduction in older adults typically uses moderate loads performed with intentional speed, as power (not just strength) has been linked to functional fall-risk-related outcomes."},{"id": 4682,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best describes an appropriate use of resistance bands in a home exercise program compared to free weights?","options": [{"key": "A","text": "Providing identical resistance to free weights at all points in the range"},{"key": "B","text": "Only usable for isometric exercises"},{"key": "C","text": "Requiring the same equipment cost and space as a full home gym"},{"key": "D","text": "Providing accessible, portable, variable resistance that can be easily progressed by using different band tensions"}],"correct": "D","explanation": "Resistance bands offer an accessible, progressive alternative to free weights for home exercise programs, though the resistance profile differs (increasing with band stretch) compared to gravity-based free weight resistance."},{"id": 4683,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an important consideration regarding exercise adherence when designing a home exercise program?","options": [{"key": "A","text": "Ignoring patient preferences entirely when selecting exercises"},{"key": "B","text": "Keeping the program appropriately simple and time-efficient to maximize the likelihood of consistent patient adherence"},{"key": "C","text": "Prescribing the maximum number of exercises possible regardless of patient capacity"},{"key": "D","text": "Assuming adherence is not influenced by program complexity"}],"correct": "B","explanation": "Program complexity and time burden significantly influence adherence; simpler, well-explained programs tailored to patient capability and preference tend to have better long-term compliance."},{"id": 4684,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes 'self-efficacy' as it relates to exercise therapy adherence and outcomes?","options": [{"key": "A","text": "A measure of muscle strength only"},{"key": "B","text": "Only relevant to elite athletic performance"},{"key": "C","text": "A patient's belief in their own capability to successfully perform a given exercise or activity"},{"key": "D","text": "A concept unrelated to exercise participation or outcomes"}],"correct": "C","explanation": "Self-efficacy, a patient's confidence in their ability to perform tasks, has been shown to significantly influence exercise adherence and rehabilitation outcomes across various conditions."},{"id": 4685,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following behavioral strategies might a physiotherapist use to enhance a patient's self-efficacy regarding a new exercise program?","options": [{"key": "A","text": "Beginning with the most difficult exercises to test the patient's limits immediately"},{"key": "B","text": "Assuming self-efficacy cannot be influenced by therapist behavior"},{"key": "C","text": "Avoiding any positive feedback regardless of patient performance"},{"key": "D","text": "Starting with achievable exercises that provide early success experiences, then gradually progressing difficulty"}],"correct": "D","explanation": "Building early mastery experiences through appropriately graded, achievable tasks is a well-established strategy for enhancing self-efficacy and subsequent exercise engagement."},{"id": 4686,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes an appropriate initial exercise therapy approach for a patient presenting with acute low back pain without red flag symptoms?","options": [{"key": "A","text": "Avoiding any patient education about the benign nature of most acute back pain"},{"key": "B","text": "Strict bed rest until complete pain resolution"},{"key": "C","text": "Encouraging continued activity and movement within tolerable limits, avoiding prolonged bed rest"},{"key": "D","text": "Immediate aggressive spinal manipulation regardless of presentation"}],"correct": "C","explanation": "Current evidence-based guidelines for uncomplicated acute low back pain favor continued activity and reassurance over prolonged rest, which can actually worsen outcomes and prolong disability."},{"id": 4687,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate physiotherapy exercise therapy approach for a patient with chronic pain who demonstrates significant kinesiophobia (fear of movement)?","options": [{"key": "A","text": "Gradual, graded exposure to movement combined with education addressing pain-related fear and misconceptions"},{"key": "B","text": "Reinforcing the belief that movement will definitely cause further tissue damage"},{"key": "C","text": "Avoiding any discussion of the psychological aspects of pain"},{"key": "D","text": "Immediate return to full, unrestricted activity without any graded approach"}],"correct": "A","explanation": "Addressing kinesiophobia requires a combined approach of education (correcting maladaptive beliefs) and graded exposure to movement, helping patients safely re-engage with previously feared activities."},{"id": 4688,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best describes the biopsychosocial model as applied to exercise therapy for chronic pain conditions?","options": [{"key": "A","text": "Recognizing that biological, psychological, and social factors all contribute to a patient's pain experience and response to treatment"},{"key": "B","text": "A model that ignores any psychological contribution to pain"},{"key": "C","text": "A model only relevant to acute injuries, not chronic conditions"},{"key": "D","text": "A model focused exclusively on biological/tissue pathology"}],"correct": "A","explanation": "The biopsychosocial model guides comprehensive chronic pain management, recognizing that effective exercise therapy must address psychological and social factors alongside purely biomechanical/tissue considerations."},{"id": 4689,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following is an important consideration in exercise prescription for a patient with significant anxiety or depression alongside a musculoskeletal condition?","options": [{"key": "A","text": "Recognizing that psychological factors may influence pain perception, motivation, and exercise engagement, potentially requiring a collaborative, multidisciplinary approach"},{"key": "B","text": "Avoiding any communication with mental health providers involved in the patient's care"},{"key": "C","text": "Assuming psychological factors are irrelevant to physiotherapy treatment"},{"key": "D","text": "Providing identical treatment regardless of any psychological comorbidity"}],"correct": "A","explanation": "Mental health comorbidities can significantly influence rehabilitation engagement and outcomes, often warranting a collaborative approach between physiotherapy and mental health providers for optimal care."},{"id": 4690,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with rotator cuff tendinopathy (non-surgical management)?","options": [{"key": "A","text": "Immediate high-intensity overhead lifting regardless of symptoms"},{"key": "B","text": "Progressive loading exercise program, often including eccentric strengthening, guided by symptom response"},{"key": "C","text": "Complete rest and immobilization of the shoulder indefinitely"},{"key": "D","text": "Avoiding any resistance exercise permanently"}],"correct": "B","explanation": "Evidence supports progressive, often eccentric-focused loading programs for tendinopathy management, guided by a symptom-monitoring approach rather than complete rest."},{"id": 4691,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Hard","question": "Which of the following describes the general dosing principle often used when introducing eccentric exercise for tendinopathy (e.g., Alfredson protocol for Achilles tendinopathy)?","options": [{"key": "A","text": "Performing a structured program with defined sets/repetitions daily, gradually increasing load over weeks"},{"key": "B","text": "Avoiding any structured protocol or progression"},{"key": "C","text": "A single session with no repetition or progression"},{"key": "D","text": "Only performing eccentric exercise once per month"}],"correct": "A","explanation": "Established eccentric loading protocols (such as the Alfredson protocol) prescribe specific daily repetitions over an extended period (often 12 weeks), with gradual load progression as tolerated."},{"id": 4692,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for lateral epicondylalgia (tennis elbow)?","options": [{"key": "A","text": "Avoiding any strengthening exercise, focusing exclusively on stretching"},{"key": "B","text": "Progressive strengthening of the wrist extensors, often starting with isometric exercise and progressing to eccentric/concentric loading"},{"key": "C","text": "Immediate maximal resistance training regardless of pain response"},{"key": "D","text": "Complete immobilization of the wrist and elbow for several months"}],"correct": "B","explanation": "Current evidence-based management of lateral epicondylalgia emphasizes a structured progressive loading program for the wrist extensors, beginning with isometrics before advancing to more dynamic loading."},{"id": 4693,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate physiotherapy exercise consideration for plantar fasciitis management?","options": [{"key": "A","text": "Combination of calf/plantar fascia stretching, intrinsic foot muscle strengthening, and gradual activity modification"},{"key": "B","text": "Complete avoidance of any weight-bearing activity indefinitely"},{"key": "C","text": "Aggressive stretching to the point of significant pain with no modification"},{"key": "D","text": "Ignoring footwear or activity modification entirely"}],"correct": "A","explanation": "Plantar fasciitis management typically combines targeted stretching, foot intrinsic strengthening, and activity/load modification as part of a comprehensive conservative treatment approach."},{"id": 4694,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy approach for a patient with patellofemoral pain syndrome?","options": [{"key": "A","text": "Only strengthening the quadriceps in isolation without any hip component"},{"key": "B","text": "Complete avoidance of any lower limb strengthening exercise"},{"key": "C","text": "Immediate return to high-impact running regardless of symptom status"},{"key": "D","text": "Strengthening of the hip abductors/external rotators and quadriceps (particularly VMO), addressing altered lower limb mechanics"}],"correct": "D","explanation": "Current evidence emphasizes a comprehensive approach targeting both local knee mechanics and proximal hip strength/control, given the recognized role of hip weakness in patellofemoral pain."},{"id": 4695,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise consideration for a patient with subacromial impingement syndrome?","options": [{"key": "A","text": "Only stretching without any strengthening component"},{"key": "B","text": "Scapular stabilization and rotator cuff strengthening exercises, along with addressing posture and movement patterns contributing to impingement"},{"key": "C","text": "Immediate aggressive overhead pressing exercises regardless of symptoms"},{"key": "D","text": "Complete avoidance of any shoulder exercise indefinitely"}],"correct": "B","explanation": "Subacromial impingement management typically addresses the underlying contributing factors (scapular dyskinesis, rotator cuff weakness, posture) through a comprehensive strengthening and movement retraining program."},{"id": 4696,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy approach for chronic mechanical neck pain?","options": [{"key": "A","text": "Avoiding any exercise addressing postural factors"},{"key": "B","text": "Only passive modalities without any active exercise component"},{"key": "C","text": "A combination of strengthening (particularly deep neck flexors), stretching, and postural correction exercises"},{"key": "D","text": "Complete immobilization of the cervical spine"}],"correct": "C","explanation": "Evidence supports active exercise programs targeting deep cervical flexor strengthening along with general conditioning and postural correction for managing chronic mechanical neck pain."},{"id": 4697,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate physiotherapy exercise consideration for temporomandibular joint (TMJ) dysfunction?","options": [{"key": "A","text": "Complete avoidance of any jaw movement or exercise"},{"key": "B","text": "Gentle jaw mobility exercises, postural correction, and addressing contributing muscle tension in the jaw/neck region"},{"key": "C","text": "Only addressing the jaw in isolation without considering cervical/postural factors"},{"key": "D","text": "Aggressive forceful jaw manipulation regardless of pain response"}],"correct": "B","explanation": "TMJ dysfunction management often benefits from a holistic approach addressing jaw mobility, muscle tension, and related cervical/postural factors, alongside gentle therapeutic exercise."},{"id": 4698,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from a whiplash-associated disorder?","options": [{"key": "A","text": "Complete avoidance of any neck movement or exercise"},{"key": "B","text": "Immediate aggressive manipulation regardless of acute symptom severity"},{"key": "C","text": "Early, gentle active range of motion and gradual return to normal activity, avoiding prolonged immobilization"},{"key": "D","text": "Prolonged cervical collar immobilization for several months"}],"correct": "C","explanation": "Evidence supports early active mobilization and encouragement of normal activity following whiplash injury, as prolonged immobilization is associated with worse long-term outcomes."},{"id": 4699,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with mechanical thoracic spine pain and associated postural dysfunction?","options": [{"key": "A","text": "Thoracic mobility exercises combined with postural correction and scapular stabilization strengthening"},{"key": "B","text": "Complete avoidance of any thoracic spine movement"},{"key": "C","text": "Only cervical spine exercises without addressing the thoracic region"},{"key": "D","text": "Immediate aggressive high-velocity thrust manipulation without any active exercise component"}],"correct": "A","explanation": "Thoracic spine pain related to postural dysfunction often benefits from a combined approach of mobility work and strengthening exercises targeting the muscles responsible for postural support."},{"id": 4700,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with ankylosing spondylitis?","options": [{"key": "A","text": "Immediate high-impact activity regardless of disease activity"},{"key": "B","text": "Only flexion-based exercises without any extension component"},{"key": "C","text": "Regular spinal mobility and extension-focused exercises combined with postural training to counteract progressive kyphotic deformity"},{"key": "D","text": "Complete avoidance of any spinal movement"}],"correct": "C","explanation": "AS management emphasizes maintaining spinal mobility and extension to counteract the tendency toward progressive kyphosis and spinal fusion characteristic of the disease."},{"id": 4701,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with rheumatoid arthritis during a period of disease remission (not active flare)?","options": [{"key": "A","text": "Regular strengthening and aerobic exercise, which has been shown to be safe and beneficial without worsening joint damage"},{"key": "B","text": "Aggressive high-impact activity without any joint protection considerations"},{"key": "C","text": "Only passive range of motion regardless of disease activity level"},{"key": "D","text": "Complete avoidance of all exercise due to the arthritic diagnosis"}],"correct": "A","explanation": "During remission, regular therapeutic exercise (strengthening and aerobic) is well-supported as safe and beneficial for RA patients, improving function without accelerating joint damage."},{"id": 4702,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with gout during an acute flare affecting the great toe?","options": [{"key": "A","text": "Complete avoidance of any exercise for the rest of the patient's life"},{"key": "B","text": "Rest and protection of the affected joint during the acute flare, with gentle range of motion introduced as inflammation subsides"},{"key": "C","text": "Ignoring the acute inflammatory presentation entirely"},{"key": "D","text": "Immediate aggressive weight-bearing exercise on the affected joint"}],"correct": "B","explanation": "During an acute gout flare, protecting the inflamed joint is prioritized, with gentle mobility exercises reintroduced gradually as the acute inflammation resolves."},{"id": 4703,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with osteoarthritis of the knee?","options": [{"key": "A","text": "Complete avoidance of any exercise due to joint degeneration"},{"key": "B","text": "Avoiding any strengthening exercise regardless of muscle weakness"},{"key": "C","text": "A combination of quadriceps strengthening, low-impact aerobic exercise, and range of motion exercises"},{"key": "D","text": "Only high-impact activities to 'toughen' the joint"}],"correct": "C","explanation": "Evidence strongly supports combined strengthening (particularly quadriceps), aerobic conditioning, and mobility exercises as first-line conservative management for knee osteoarthritis."},{"id": 4704,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the rationale for quadriceps strengthening specifically in knee osteoarthritis management?","options": [{"key": "A","text": "Stronger quadriceps may help absorb joint loading forces and improve functional stability, potentially reducing symptoms"},{"key": "B","text": "Quadriceps strength has no relationship to knee osteoarthritis symptoms"},{"key": "C","text": "Strengthening exercise is contraindicated in any arthritic joint"},{"key": "D","text": "Quadriceps weakness always worsens with strengthening exercise"}],"correct": "A","explanation": "Quadriceps weakness is a well-established contributing factor to knee OA symptoms and progression; strengthening this muscle group can improve joint loading distribution and functional outcomes."},{"id": 4705,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with fibrous ankylosis following prolonged joint immobilization?","options": [{"key": "A","text": "Gentle, progressive mobilization within tolerable limits, recognizing that full range recovery may be limited depending on the degree of fibrosis"},{"key": "B","text": "Assuming full range of motion will always be restored regardless of fibrosis severity"},{"key": "C","text": "Immediate aggressive forceful manipulation to break up all fibrous tissue"},{"key": "D","text": "Complete avoidance of any further mobilization attempts"}],"correct": "A","explanation": "Fibrous ankylosis represents established fibrotic joint restriction; gentle progressive mobilization is appropriate, though full range restoration may be limited depending on the extent and chronicity of fibrosis."},{"id": 4706,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration for exercise therapy following a burn injury, particularly regarding scar tissue and contracture prevention?","options": [{"key": "A","text": "Aggressive stretching immediately over an open, unhealed burn wound"},{"key": "B","text": "Ignoring positioning considerations during the healing process"},{"key": "C","text": "Complete immobilization until the burn wound is fully healed"},{"key": "D","text": "Early, appropriately timed range of motion exercises and positioning to prevent contracture formation as the wound heals"}],"correct": "D","explanation": "Burn rehabilitation emphasizes early, carefully timed mobility exercises and positioning strategies to prevent the contractures that commonly develop as burn scars mature and contract."},{"id": 4707,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with peripheral vascular disease and intermittent claudication regarding walking-based exercise programs?","options": [{"key": "A","text": "Walking to the point of moderate claudication pain, resting, then resuming, repeated over a structured session"},{"key": "B","text": "Avoiding any walking that produces claudication symptoms"},{"key": "C","text": "Complete avoidance of any exercise due to vascular disease"},{"key": "D","text": "Walking only to the point of first symptom onset, never progressing further"}],"correct": "A","explanation": "Structured walking programs for claudication typically involve walking to a moderate pain level, resting, then continuing, which has been shown to improve walking distance and collateral circulation over time."},{"id": 4708,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration for exercise therapy in a patient with a diagnosed pressure injury (bedsore) affecting mobility?","options": [{"key": "A","text": "Ignoring the pressure injury and continuing standard exercise without modification"},{"key": "B","text": "Complete avoidance of any mobility or positioning intervention"},{"key": "C","text": "Assuming pressure injuries have no relevance to physiotherapy exercise planning"},{"key": "D","text": "Addressing positioning/pressure relief strategies alongside appropriate mobility exercise to prevent further injury progression while promoting healing"}],"correct": "D","explanation": "Physiotherapists play an important role in pressure injury prevention/management through positioning education and appropriate mobility strategies that balance healing needs with maintaining function."},{"id": 4709,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise consideration for a patient with a below-knee amputation regarding residual limb care?","options": [{"key": "A","text": "Ignoring residual limb shape/volume management entirely"},{"key": "B","text": "Complete avoidance of any residual limb exercise until full wound healing occurs years later"},{"key": "C","text": "Immediate weight-bearing on the residual limb without any preparatory conditioning"},{"key": "D","text": "Residual limb strengthening, desensitization, and shaping exercises in preparation for prosthetic fitting"}],"correct": "D","explanation": "Pre-prosthetic rehabilitation focuses on strengthening, desensitizing, and shaping the residual limb to optimize prosthetic fit and function once fitting occurs."},{"id": 4710,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an important exercise therapy consideration for a patient with a transfemoral (above-knee) amputation regarding hip extensor/abductor strength?","options": [{"key": "A","text": "Strengthening these muscle groups is important for prosthetic gait control and preventing compensatory gait patterns"},{"key": "B","text": "Hip strengthening should be avoided in this population"},{"key": "C","text": "These muscle groups have no relevance to prosthetic gait"},{"key": "D","text": "Only upper extremity strength matters for prosthetic use"}],"correct": "A","explanation": "Adequate hip extensor and abductor strength is crucial for controlling the prosthetic limb during stance phase and preventing compensatory gait deviations like circumduction or lateral trunk lean."},{"id": 4711,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy approach for phantom limb pain following amputation?","options": [{"key": "A","text": "Ignoring the patient's reported pain since the limb is absent"},{"key": "B","text": "Techniques such as mirror therapy and graded motor imagery may be used alongside standard rehabilitation"},{"key": "C","text": "Complete avoidance of any specific intervention, as phantom pain is untreatable"},{"key": "D","text": "Only pharmacological management with no role for exercise therapy"}],"correct": "B","explanation": "Phantom limb pain has shown response to certain physiotherapy-based interventions like mirror therapy and graded motor imagery, complementing broader pain management strategies."},{"id": 4712,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate physiotherapy exercise consideration for a patient with a burn contracture affecting elbow extension?","options": [{"key": "A","text": "Progressive stretching and splinting combined with active range of motion exercises, carefully timed with wound/scar maturation"},{"key": "B","text": "Ignoring the contracture and focusing only on unaffected joints"},{"key": "C","text": "Aggressive forceful stretching immediately over fresh, unhealed burn tissue"},{"key": "D","text": "Complete avoidance of any stretching regardless of contracture severity"}],"correct": "A","explanation": "Burn contracture management requires careful balance of stretching, splinting, and exercise timed appropriately with tissue healing to optimize functional range recovery."},{"id": 4713,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with cerebral palsy and significant lower limb spasticity being considered for selective dorsal rhizotomy?","options": [{"key": "A","text": "The surgery eliminates any further need for physiotherapy intervention"},{"key": "B","text": "Physiotherapy has no role before or after this surgical procedure"},{"key": "C","text": "Pre- and post-operative physiotherapy including strengthening is important, as the surgery reduces spasticity but does not address pre-existing weakness"},{"key": "D","text": "Strengthening exercise is contraindicated following this procedure"}],"correct": "C","explanation": "Selective dorsal rhizotomy reduces spasticity by cutting select sensory nerve rootlets, but comprehensive physiotherapy remains essential to address the underlying muscle weakness often unmasked or persisting after the procedure."},{"id": 4714,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the purpose of orthotic devices (e.g., ankle-foot orthosis) often used alongside exercise therapy in patients with foot drop?","options": [{"key": "A","text": "Having no functional benefit during ambulation"},{"key": "B","text": "Only used for cosmetic purposes without functional benefit"},{"key": "C","text": "Replacing the need for any exercise therapy entirely"},{"key": "D","text": "Providing mechanical support to maintain proper foot position during gait, complementing strengthening and gait training"}],"correct": "D","explanation": "AFOs provide mechanical assistance for ankle positioning during gait, working alongside rather than replacing therapeutic exercise aimed at strengthening and gait retraining."},{"id": 4715,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed peripheral nerve injury undergoing recovery, regarding strengthening timing?","options": [{"key": "A","text": "Strengthening exercises are typically introduced once there is evidence of reinnervation, following appropriate nerve regeneration timelines"},{"key": "B","text": "Immediate maximal strengthening regardless of nerve regeneration status"},{"key": "C","text": "Complete avoidance of any exercise throughout the entire recovery period"},{"key": "D","text": "Strengthening exercise has no relevance to peripheral nerve injury recovery"}],"correct": "A","explanation": "Given the biological timeline of nerve regeneration (typically 1mm/day), strengthening exercises are appropriately introduced as reinnervation signs appear, following realistic recovery timelines."},{"id": 4716,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from Guillain-Barre syndrome during the recovery phase?","options": [{"key": "A","text": "Immediate maximal resistance training regardless of fatigue signs"},{"key": "B","text": "Gradual, carefully monitored strengthening avoiding overwork weakness, given the potential for fatigue in recovering motor units"},{"key": "C","text": "Ignoring any signs of fatigue during exercise sessions"},{"key": "D","text": "Complete avoidance of any exercise throughout the recovery period"}],"correct": "B","explanation": "GBS recovery requires careful, graded strengthening due to the risk of 'overwork weakness' in recovering motor units, requiring close monitoring for fatigue during the rehabilitation process."},{"id": 4717,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an important consideration for exercise therapy in a patient with myasthenia gravis regarding exercise timing relative to medication?","options": [{"key": "A","text": "Complete avoidance of any exercise regardless of medication timing"},{"key": "B","text": "Scheduling exercise sessions to coincide with peak medication effect (e.g., after acetylcholinesterase inhibitor dosing) may optimize participation and reduce fatigue"},{"key": "C","text": "Exercise should always be performed immediately before medication dosing"},{"key": "D","text": "Exercise timing has no relationship to medication effect in this condition"}],"correct": "B","explanation": "Since MG symptoms fluctuate with medication levels, timing exercise sessions to align with peak medication effect can help optimize muscle strength during therapy and reduce excessive fatigue."},{"id": 4718,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with post-polio syndrome experiencing new muscle weakness/fatigue?","options": [{"key": "A","text": "Assuming exercise has no role in managing post-polio syndrome symptoms"},{"key": "B","text": "Judicious, non-fatiguing exercise programs, avoiding overwork of already-compromised motor units"},{"key": "C","text": "Complete avoidance of any physical activity indefinitely"},{"key": "D","text": "Aggressive maximal strengthening to 'push through' the new weakness"}],"correct": "B","explanation": "Post-polio syndrome management emphasizes careful, non-fatiguing exercise dosing to avoid further overworking already vulnerable motor units, differing from more aggressive strengthening approaches used in other conditions."},{"id": 4719,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with hereditary neuropathy (e.g., Charcot-Marie-Tooth disease)?","options": [{"key": "A","text": "Maximal high-intensity resistance training regardless of fatigue response"},{"key": "B","text": "Moderate-intensity strengthening and functional exercise, avoiding excessive fatigue while addressing distal weakness and potential foot deformity"},{"key": "C","text": "Complete avoidance of any exercise due to the progressive nature of the condition"},{"key": "D","text": "Ignoring any foot/ankle considerations despite the characteristic distal weakness pattern"}],"correct": "B","explanation": "CMT management typically includes moderate, carefully dosed strengthening and functional exercise, along with attention to foot/ankle bracing needs given the characteristic distal muscle weakness pattern."},{"id": 4720,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an important exercise therapy consideration for a patient recovering from a traumatic brain injury with associated cognitive-communication deficits?","options": [{"key": "A","text": "Avoiding any physical exercise until cognition fully normalizes"},{"key": "B","text": "Assuming cognitive deficits have no bearing on exercise therapy delivery"},{"key": "C","text": "Providing only complex multi-step instructions regardless of cognitive status"},{"key": "D","text": "Simplifying instructions, using consistent cues, and incorporating cognitive-motor dual-tasking as appropriate to the recovery stage"}],"correct": "D","explanation": "TBI rehabilitation often requires tailored communication strategies and consideration of cognitive-motor interaction, adapting standard exercise delivery to the patient's current cognitive capacity."},{"id": 4721,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a spinal cord injury regarding cardiovascular fitness training, given altered autonomic responses?","options": [{"key": "A","text": "Using standard age-predicted heart rate formulas without any modification"},{"key": "B","text": "Careful monitoring of heart rate/blood pressure response, recognizing that standard target heart rate formulas may not apply due to altered sympathetic innervation"},{"key": "C","text": "Assuming cardiovascular training has no role in SCI rehabilitation"},{"key": "D","text": "Complete avoidance of any aerobic exercise regardless of injury level"}],"correct": "B","explanation": "SCI, particularly at higher levels, can disrupt normal sympathetic cardiac innervation, altering typical heart rate responses to exercise and requiring modified monitoring approaches (e.g., using RPE) for safe cardiovascular training."},{"id": 4722,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a wheelchair-dependent patient regarding upper extremity overuse injury prevention?","options": [{"key": "A","text": "Encouraging excessive, unmodified wheelchair propulsion volume without any technique consideration"},{"key": "B","text": "Ignoring upper extremity considerations since the lower limbs are primarily affected"},{"key": "C","text": "Assuming overuse injury is not a concern in wheelchair users"},{"key": "D","text": "Incorporating shoulder strengthening (particularly posterior cuff/scapular muscles) and proper wheelchair propulsion technique training"}],"correct": "D","explanation": "Wheelchair users face elevated risk of upper extremity overuse injuries (particularly shoulder) due to repetitive propulsion demands, making targeted strengthening and technique training important preventive strategies."},{"id": 4723,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic kidney disease undergoing dialysis, regarding exercise timing relative to dialysis sessions?","options": [{"key": "A","text": "Complete avoidance of any exercise due to kidney disease"},{"key": "B","text": "Exercise is often better tolerated and may be incorporated on non-dialysis days or carefully timed around dialysis sessions based on patient tolerance"},{"key": "C","text": "Exercise timing has no relevance to dialysis patients' tolerance or safety"},{"key": "D","text": "Exercise should always be performed immediately during dialysis regardless of tolerance"}],"correct": "B","explanation": "Fatigue and hemodynamic changes around dialysis sessions can affect exercise tolerance, so scheduling and intensity should be individualized considering the patient's dialysis schedule and response."},{"id": 4724,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with liver cirrhosis and associated muscle wasting (sarcopenia)?","options": [{"key": "A","text": "Only passive treatment without any active exercise component"},{"key": "B","text": "Assuming exercise has no role in managing cirrhosis-related sarcopenia"},{"key": "C","text": "Complete avoidance of exercise due to the severity of liver disease"},{"key": "D","text": "Incorporating resistance and functional exercise to help counteract disease-related muscle wasting, alongside appropriate medical management"}],"correct": "D","explanation": "Given the significant sarcopenia often accompanying advanced liver disease, appropriately dosed resistance and functional exercise can help address muscle wasting as part of comprehensive management."},{"id": 4725,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with cancer-related fatigue during active treatment (e.g., chemotherapy)?","options": [{"key": "A","text": "Exercise should only be considered after treatment is fully completed"},{"key": "B","text": "Complete rest and avoidance of any activity is always recommended during active cancer treatment"},{"key": "C","text": "Regular, moderate-intensity exercise as tolerated has been shown to help reduce cancer-related fatigue and improve quality of life"},{"key": "D","text": "Aggressive high-intensity training regardless of treatment side effects"}],"correct": "C","explanation": "Contrary to older recommendations for complete rest, current evidence supports safe, moderate exercise during cancer treatment to help manage fatigue and support overall function and quality of life."},{"id": 4726,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an important safety consideration for exercise therapy in a cancer patient with known bone metastases?","options": [{"key": "A","text": "Avoiding high-impact or high-load activities at sites of significant bony metastatic involvement to reduce pathological fracture risk"},{"key": "B","text": "Complete avoidance of all exercise regardless of metastatic location or extent"},{"key": "C","text": "Encouraging maximal high-impact activity regardless of metastatic bone involvement"},{"key": "D","text": "Assuming bone metastases have no bearing on exercise prescription"}],"correct": "A","explanation": "Bone metastases significantly increase pathological fracture risk at affected sites, requiring careful modification of exercise type/intensity to avoid excessive loading at vulnerable skeletal locations."},{"id": 4727,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chemotherapy-induced peripheral neuropathy affecting balance?","options": [{"key": "A","text": "Balance and proprioceptive training, along with appropriate footwear and fall-risk precautions given sensory impairment"},{"key": "B","text": "Complete avoidance of any balance-related exercise"},{"key": "C","text": "Assuming chemotherapy-induced neuropathy has no impact on balance training needs"},{"key": "D","text": "Ignoring sensory deficits when designing exercise programs"}],"correct": "A","explanation": "Chemotherapy-induced peripheral neuropathy can significantly impair proprioceptive feedback and balance, warranting targeted balance training and fall-prevention strategies similar to other peripheral neuropathies."},{"id": 4728,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with HIV/AIDS-related muscle wasting?","options": [{"key": "A","text": "Resistance training has been shown to help improve muscle mass and function in this population when appropriately supervised"},{"key": "B","text": "Only aerobic exercise should ever be considered, with no role for resistance training"},{"key": "C","text": "Complete avoidance of exercise due to immunocompromised status"},{"key": "D","text": "Assuming resistance training provides no benefit in this population"}],"correct": "A","explanation": "Research supports supervised resistance training as beneficial for addressing HIV-related muscle wasting and improving functional capacity, alongside standard medical management."},{"id": 4729,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic heart failure regarding exercise intensity monitoring?","options": [{"key": "A","text": "Using a combination of heart rate reserve/RPE while watching closely for signs of decompensation such as excessive dyspnea or fatigue"},{"key": "B","text": "Avoiding any structured monitoring since heart failure patients cannot safely exercise"},{"key": "C","text": "Prescribing exercise intensity based solely on age without considering cardiac status"},{"key": "D","text": "Ignoring any signs of decompensation during exercise sessions"}],"correct": "A","explanation": "Heart failure patients benefit from carefully monitored exercise programs, using combined objective (heart rate) and subjective (RPE) measures while watching for signs of clinical decompensation."},{"id": 4730,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration for exercise therapy in a patient recently diagnosed with atrial fibrillation who is anticoagulated?","options": [{"key": "A","text": "Ignoring bleeding risk considerations entirely during exercise prescription"},{"key": "B","text": "Being aware of increased bleeding risk with high-impact/contact activities while still encouraging appropriate aerobic exercise"},{"key": "C","text": "Only high-impact contact activities are appropriate for this population"},{"key": "D","text": "Complete avoidance of any exercise due to anticoagulation"}],"correct": "B","explanation": "Anticoagulated patients require awareness of bleeding risk with high-impact/contact activities, while appropriately dosed aerobic exercise remains generally beneficial and encouraged."},{"id": 4731,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a recently implanted left ventricular assist device (LVAD)?","options": [{"key": "A","text": "Following device-specific exercise guidelines and precautions, often involving gradual, medically supervised progression"},{"key": "B","text": "Assuming standard exercise protocols apply without any device-specific modification"},{"key": "C","text": "Immediate unrestricted high-intensity exercise regardless of device precautions"},{"key": "D","text": "Complete avoidance of any exercise indefinitely following LVAD implantation"}],"correct": "A","explanation": "LVAD patients require specialized, medically coordinated exercise programming that accounts for device-specific precautions and hemodynamic considerations unique to this population."},{"id": 4732,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with pulmonary hypertension regarding exercise intensity?","options": [{"key": "A","text": "Assuming pulmonary hypertension has no bearing on appropriate exercise intensity"},{"key": "B","text": "Immediate high-intensity aerobic training regardless of pulmonary pressures"},{"key": "C","text": "Complete avoidance of any exercise regardless of disease severity"},{"key": "D","text": "Conservative, closely monitored low-to-moderate intensity exercise, given the risk of exercise-induced right heart strain"}],"correct": "D","explanation": "Given the risk of right ventricular strain with excessive exertion in pulmonary hypertension, exercise programs are typically conservative and closely monitored under appropriate medical guidance."},{"id": 4733,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with interstitial lung disease regarding oxygen supplementation during exercise?","options": [{"key": "A","text": "Assuming oxygen supplementation has no role in exercise therapy for this population"},{"key": "B","text": "Complete avoidance of any exercise regardless of oxygen needs"},{"key": "C","text": "Using supplemental oxygen as prescribed to maintain adequate saturation during exercise, allowing safer participation in higher-intensity activity"},{"key": "D","text": "Avoiding supplemental oxygen even if desaturation occurs during exercise"}],"correct": "C","explanation": "Appropriate supplemental oxygen use during exercise can help maintain safe saturation levels in patients with significant interstitial lung disease, supporting safer and more effective exercise participation."},{"id": 4734,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with cystic fibrosis regarding airway clearance and exercise timing?","options": [{"key": "A","text": "Coordinating exercise sessions with airway clearance techniques may enhance mucus mobilization and overall respiratory benefit"},{"key": "B","text": "Airway clearance has no relevance to exercise prescription in this population"},{"key": "C","text": "Exercise is contraindicated in cystic fibrosis regardless of disease severity"},{"key": "D","text": "Exercise and airway clearance techniques should never be combined"}],"correct": "A","explanation": "Combining exercise with airway clearance techniques can have synergistic benefits for mucus mobilization, making coordinated timing a valuable consideration in cystic fibrosis management."},{"id": 4735,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a pediatric patient with asthma regarding exercise-induced bronchospasm prevention?","options": [{"key": "A","text": "Complete avoidance of any physical activity due to asthma diagnosis"},{"key": "B","text": "Assuming asthma has no bearing on exercise program design"},{"key": "C","text": "Appropriate pre-exercise medication use (if prescribed) combined with a proper warm-up may help reduce exercise-induced bronchospasm risk"},{"key": "D","text": "Ignoring any warm-up considerations before exercise"}],"correct": "C","explanation": "With appropriate premedication and warm-up strategies, most children with asthma can safely participate in regular physical activity, and complete avoidance is rarely necessary or recommended."},{"id": 4736,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an obese pediatric patient regarding exercise prescription?","options": [{"key": "A","text": "Immediate high-intensity structured training regardless of the child's preferences or developmental stage"},{"key": "B","text": "Avoiding any physical activity recommendation until significant weight loss occurs first"},{"key": "C","text": "Assuming exercise prescription for children is identical to that for adults"},{"key": "D","text": "Emphasizing enjoyable, sustainable physical activities appropriate to the child's developmental level to promote long-term healthy habits"}],"correct": "D","explanation": "Pediatric exercise prescription for weight management emphasizes enjoyable, developmentally appropriate activity that promotes sustainable long-term habits rather than adult-style structured training regimens."},{"id": 4737,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with Down syndrome regarding joint laxity, particularly atlantoaxial instability?","options": [{"key": "A","text": "Encouraging unrestricted participation in all high-risk cervical spine-loading activities"},{"key": "B","text": "Screening for atlantoaxial instability and avoiding high-risk activities (e.g., certain gymnastics, diving) that stress the cervical spine in at-risk individuals"},{"key": "C","text": "Assuming atlantoaxial instability has no relevance to exercise program design"},{"key": "D","text": "Complete avoidance of all physical activity regardless of screening results"}],"correct": "B","explanation": "Down syndrome is associated with increased risk of atlantoaxial instability, requiring screening and appropriate activity modification to avoid high-risk cervical spine-loading activities in affected individuals."},{"id": 4738,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a preterm infant in a neonatal intensive care unit regarding developmental positioning and handling?","options": [{"key": "A","text": "Gentle, developmentally appropriate positioning and handling techniques to support motor development while minimizing physiological stress"},{"key": "B","text": "Assuming positioning has no bearing on preterm infant development"},{"key": "C","text": "Complete avoidance of any physical therapy involvement in the NICU setting"},{"key": "D","text": "Aggressive, adult-style range of motion exercises regardless of the infant's physiological stability"}],"correct": "A","explanation": "NICU physiotherapy for preterm infants focuses on gentle, developmentally supportive positioning and handling that promotes motor development while respecting the infant's physiological stability and stress tolerance."},{"id": 4739,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an adolescent athlete with a diagnosed stress fracture?","options": [{"key": "A","text": "Ignoring the diagnosis and continuing unmodified training"},{"key": "B","text": "Immediate return to full sport participation regardless of healing status"},{"key": "C","text": "Complete permanent cessation of the sport regardless of healing progress"},{"key": "D","text": "A period of relative rest/activity modification followed by a structured, gradual return-to-sport progression once healing is confirmed"}],"correct": "D","explanation": "Stress fracture management requires an appropriate period of load modification/rest followed by careful, graded return-to-sport progression guided by clinical and often imaging-based healing confirmation."},{"id": 4740,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a female athlete presenting with signs of Relative Energy Deficiency in Sport (RED-S)?","options": [{"key": "A","text": "Assuming RED-S has no relevance to exercise prescription decisions"},{"key": "B","text": "Addressing the underlying energy deficit through a multidisciplinary approach, with appropriate modification of training load as part of comprehensive management"},{"key": "C","text": "Immediately maximizing training volume to 'push through' the underlying issue"},{"key": "D","text": "Ignoring the condition and continuing unmodified high-intensity training"}],"correct": "B","explanation": "RED-S requires a comprehensive, multidisciplinary approach addressing the underlying energy availability issue, with appropriate, often temporary, modification of training load as part of management."},{"id": 4741,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a history of exertional heat illness during outdoor exercise programming?","options": [{"key": "A","text": "Encouraging exercise during peak heat conditions regardless of prior heat illness history"},{"key": "B","text": "Implementing appropriate acclimatization strategies, hydration protocols, and environmental monitoring to reduce recurrence risk"},{"key": "C","text": "Ignoring environmental conditions during exercise prescription"},{"key": "D","text": "Assuming heat illness history has no bearing on future exercise program design"}],"correct": "B","explanation": "Given the risk of recurrent heat illness, appropriate acclimatization, hydration strategies, and environmental monitoring are important considerations for patients with this history participating in outdoor exercise programs."},{"id": 4742,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed vestibular migraine affecting balance and triggered by certain movements?","options": [{"key": "A","text": "Immediate aggressive exposure to all triggering movements without gradual progression"},{"key": "B","text": "Assuming vestibular rehabilitation principles have no application to this condition"},{"key": "C","text": "Complete avoidance of any movement that could potentially trigger symptoms"},{"key": "D","text": "Gradual habituation exercises targeting specific triggering movements, alongside broader vestibular rehabilitation principles"}],"correct": "D","explanation": "Vestibular migraine management often incorporates graded habituation exercises targeting specific symptom triggers, applying similar principles to standard vestibular rehabilitation approaches."},{"id": 4743,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which type of lever system does the elbow joint represent during a bicep curl, with the fulcrum between the effort and resistance?","options": [{"key": "A","text": "Second-class lever"},{"key": "B","text": "First-class lever"},{"key": "C","text": "No lever system applies to joint movement"},{"key": "D","text": "Third-class lever"}],"correct": "D","explanation": "In a third-class lever, the effort is applied between the fulcrum and the resistance, as seen at the elbow during forearm flexion, common in the body's musculoskeletal levers."},{"id": 4744,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which type of lever system is exemplified by the action of standing calf raises, with the resistance between the fulcrum and effort?","options": [{"key": "A","text": "Third-class lever"},{"key": "B","text": "Second-class lever"},{"key": "C","text": "First-class lever"},{"key": "D","text": "No lever system applies"}],"correct": "B","explanation": "In a second-class lever, resistance sits between the fulcrum and effort, as seen at the ankle during a calf raise where body weight (resistance) is between the toe fulcrum and calf muscle effort."},{"id": 4745,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following best describes the concept of a 'first-class lever' in human biomechanics, as exemplified by the head balancing on the atlas (C1)?","options": [{"key": "A","text": "The fulcrum is positioned between the effort and the resistance"},{"key": "B","text": "The resistance is between the effort and fulcrum"},{"key": "C","text": "No fulcrum exists in this arrangement"},{"key": "D","text": "The effort is between the fulcrum and resistance"}],"correct": "A","explanation": "First-class levers have the fulcrum centrally located between effort and resistance, as seen with the atlanto-occipital joint balancing the head's weight against posterior neck muscle effort."},{"id": 4746,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the biomechanical principle of 'moment arm' as it relates to muscle force and joint torque?","options": [{"key": "A","text": "A concept unrelated to joint movement or torque"},{"key": "B","text": "Only relevant to isometric contractions, not dynamic movement"},{"key": "C","text": "The perpendicular distance from the joint axis to the line of muscle force application, influencing the torque produced"},{"key": "D","text": "The total length of the muscle regardless of joint position"}],"correct": "C","explanation": "The moment arm determines the mechanical advantage a muscle has at a given joint angle, directly influencing the torque generated for a given amount of muscular force."},{"id": 4747,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes how changing a joint's position can affect a muscle's mechanical advantage during exercise (e.g., varying moment arm through range)?","options": [{"key": "A","text": "The moment arm, and thus torque-producing capacity, changes throughout the range of motion, making certain joint angles biomechanically more/less challenging"},{"key": "B","text": "Joint position has no effect on muscle mechanical advantage"},{"key": "C","text": "Only isometric exercises are affected by changes in joint position"},{"key": "D","text": "The moment arm remains completely constant throughout the entire range of motion"}],"correct": "A","explanation": "As a joint moves through its range, the muscle's moment arm relative to the joint axis changes, altering the torque-producing capacity and explaining why certain exercise positions feel more or less challenging."},{"id": 4748,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'center of mass' relevant to balance and postural control exercises?","options": [{"key": "A","text": "Only relevant during completely static positions, never during movement"},{"key": "B","text": "A fixed point that never changes regardless of body position"},{"key": "C","text": "A concept only relevant to inanimate objects, not the human body"},{"key": "D","text": "The point representing the average position of an object's or body's mass distribution, important for stability considerations"}],"correct": "D","explanation": "Understanding center of mass position relative to the base of support is fundamental to balance training, as stability depends on maintaining the center of mass within the base of support."},{"id": 4749,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the relationship between base of support and stability in balance training progression?","options": [{"key": "A","text": "Only the height of the center of mass matters, not the base of support size"},{"key": "B","text": "Base of support has no relationship to postural stability"},{"key": "C","text": "A larger base of support generally provides greater stability, while a smaller base increases challenge/difficulty"},{"key": "D","text": "A smaller base of support always provides greater stability"}],"correct": "C","explanation": "Reducing the base of support (e.g., progressing from double-leg to single-leg stance) is a fundamental principle used to systematically increase balance training difficulty."},{"id": 4750,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'ground reaction force' as relevant to gait analysis and exercise therapy?","options": [{"key": "A","text": "Only relevant to elite athletic performance analysis"},{"key": "B","text": "A force that only exists during non-weight-bearing exercise"},{"key": "C","text": "A concept unrelated to gait or functional movement analysis"},{"key": "D","text": "The force exerted by the ground on the body in response to the body's force on the ground, important for understanding loading during weight-bearing activities"}],"correct": "D","explanation": "Ground reaction force analysis helps physiotherapists understand loading patterns during gait and weight-bearing exercise, informing rehabilitation strategies for various musculoskeletal conditions."},{"id": 4751,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an important biomechanical consideration when teaching a patient proper squat technique to protect the lumbar spine?","options": [{"key": "A","text": "Maintaining a relatively neutral spine position while hinging primarily at the hips and knees"},{"key": "B","text": "Encouraging maximal lumbar flexion throughout the movement"},{"key": "C","text": "Ignoring spinal position entirely during the exercise"},{"key": "D","text": "Only knee movement matters, with no consideration for hip or spine positioning"}],"correct": "A","explanation": "Proper squat mechanics emphasize hip-hinging with a relatively neutral spine to distribute load appropriately and minimize excessive lumbar flexion stress during the movement."},{"id": 4752,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an important biomechanical consideration regarding knee alignment during squatting or lunging exercises, relevant to injury prevention?","options": [{"key": "A","text": "Only ankle position matters, not knee alignment"},{"key": "B","text": "Encouraging maximal knee valgus throughout the exercise"},{"key": "C","text": "Knee alignment has no relevance to injury risk during these exercises"},{"key": "D","text": "Avoiding excessive dynamic knee valgus (inward collapse) during the movement"}],"correct": "D","explanation": "Dynamic knee valgus during loaded activities is associated with increased injury risk (e.g., ACL injury, patellofemoral pain), making proper knee alignment cueing an important exercise therapy consideration."},{"id": 4753,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following muscles are considered primary 'hip extensors' important for controlling knee valgus and pelvic stability during functional movements like squatting?","options": [{"key": "A","text": "Tibialis anterior"},{"key": "B","text": "Rectus femoris exclusively"},{"key": "C","text": "Gluteus maximus and hamstrings"},{"key": "D","text": "Gastrocnemius exclusively"}],"correct": "C","explanation": "The gluteus maximus and hamstrings serve as primary hip extensors that also play a key role in controlling frontal plane knee alignment and pelvic stability during functional lower limb movements."},{"id": 4754,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'kinetic chain' as applied to exercise therapy and injury analysis?","options": [{"key": "A","text": "A term with no practical application to exercise therapy"},{"key": "B","text": "The interconnected series of joints and muscles working together to produce or control movement throughout the body"},{"key": "C","text": "A concept only relevant to upper extremity movement"},{"key": "D","text": "Only a single isolated joint's movement without any connection to other body segments"}],"correct": "B","explanation": "Understanding the kinetic chain concept helps therapists recognize how dysfunction at one joint/segment can affect movement and loading patterns throughout the connected chain, informing comprehensive assessment and treatment."},{"id": 4755,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an example of a 'proximal to distal' dysfunction pattern relevant to the kinetic chain concept in lower extremity injuries?","options": [{"key": "A","text": "Ankle sprains always causing hip pathology"},{"key": "B","text": "No relationship exists between proximal and distal joint function"},{"key": "C","text": "Hip weakness contributing to altered knee mechanics and subsequent knee pain/injury"},{"key": "D","text": "Only distal joint dysfunction can affect proximal segments, never the reverse"}],"correct": "C","explanation": "This example illustrates how proximal hip weakness/dysfunction can alter mechanics at more distal joints (knee), a well-recognized pattern in conditions like patellofemoral pain and ACL injury risk."},{"id": 4756,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Which of the following describes an appropriate use of the 'timing for emphasis' technique in PNF, where a specific component of a movement pattern is emphasized?","options": [{"key": "A","text": "Providing manual resistance selectively to strengthen a weaker component within an otherwise stronger movement pattern"},{"key": "B","text": "A technique with no practical clinical application"},{"key": "C","text": "A technique used only for passive stretching, not active movement facilitation"},{"key": "D","text": "Applying equal resistance uniformly throughout the entire pattern regardless of relative component strength"}],"correct": "A","explanation": "Timing for emphasis allows therapists to selectively resist a weaker link within a functional movement pattern while facilitating the overall coordinated pattern, useful for addressing specific weaknesses."},{"id": 4757,"subject": "Exercise Therapy","topic": "Stretching & Flexibility","difficulty": "Hard","question": "Which of the following describes the physiological basis for why a prolonged static stretch (e.g., 30 seconds) may be more effective for increasing range of motion than a very brief stretch?","options": [{"key": "A","text": "Only neural factors matter, with no viscoelastic tissue component to stretching"},{"key": "B","text": "Muscle tissue does not respond differently based on stretch duration"},{"key": "C","text": "Allowing sufficient time for viscoelastic tissue creep and reduced neural reflexive resistance to the stretch"},{"key": "D","text": "Brief stretches always provide equal or superior results compared to prolonged holds"}],"correct": "C","explanation": "Sustained stretching allows time-dependent viscoelastic deformation (creep) of connective tissue along with reduced reflexive muscular resistance, contributing to greater range of motion gains than very brief stretches."},{"id": 4758,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration when addressing hip flexor tightness commonly associated with prolonged sitting?","options": [{"key": "A","text": "Complete avoidance of any hip-related exercise regardless of presentation"},{"key": "B","text": "Only stretching without addressing any associated weakness in opposing muscle groups"},{"key": "C","text": "Assuming hip flexor tightness has no relationship to associated muscle imbalances"},{"key": "D","text": "Regular hip flexor stretching combined with hip extensor/gluteal strengthening to address the associated muscle imbalance"}],"correct": "D","explanation": "Addressing the common pattern of tight hip flexors alongside weak gluteal muscles (often from prolonged sitting) typically requires a combined stretching and strengthening approach for effective correction."},{"id": 4759,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise consideration for a patient presenting with upper crossed syndrome (forward head posture, rounded shoulders)?","options": [{"key": "A","text": "Complete avoidance of any postural correction exercise"},{"key": "B","text": "Stretching tight anterior chest/neck muscles combined with strengthening weak deep neck flexors and scapular retractors"},{"key": "C","text": "Ignoring the muscle imbalance pattern entirely"},{"key": "D","text": "Only stretching without any strengthening component"}],"correct": "B","explanation": "Upper crossed syndrome involves a characteristic pattern of tight anterior/weak posterior muscles, requiring a combined stretching and strengthening approach to address the underlying postural imbalance."},{"id": 4760,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise consideration for lower crossed syndrome (anterior pelvic tilt, tight hip flexors/lumbar extensors, weak abdominals/glutes)?","options": [{"key": "A","text": "Assuming no muscle imbalance pattern exists in this presentation"},{"key": "B","text": "Only strengthening the already-tight muscle groups"},{"key": "C","text": "Stretching tight hip flexors and lumbar extensors combined with strengthening weak abdominal and gluteal muscles"},{"key": "D","text": "Complete avoidance of any exercise addressing this pattern"}],"correct": "C","explanation": "Lower crossed syndrome similarly involves a reciprocal pattern of tightness and weakness requiring targeted stretching of tight structures alongside strengthening of the corresponding weak muscle groups."},{"id": 4761,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy approach when a patient demonstrates limited ankle dorsiflexion range contributing to compensatory movement patterns during squatting?","options": [{"key": "A","text": "Assuming ankle mobility has no relationship to squat mechanics"},{"key": "B","text": "Targeted calf muscle stretching and ankle mobility exercises to address the underlying restriction before/alongside functional strengthening"},{"key": "C","text": "Ignoring the ankle restriction and focusing only on strengthening exercises"},{"key": "D","text": "Complete avoidance of squatting exercises indefinitely without addressing the restriction"}],"correct": "B","explanation": "Limited ankle dorsiflexion is a common contributor to compensatory movement patterns (e.g., heel rise, excessive forward trunk lean) during squatting, making targeted mobility work an important component of a comprehensive approach."},{"id": 4762,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'muscle imbalance' as it relates to exercise therapy assessment and treatment planning?","options": [{"key": "A","text": "A pattern of relative tightness in some muscle groups combined with weakness in opposing/synergistic groups, potentially contributing to altered movement and pain"},{"key": "B","text": "A term with no practical relevance to clinical exercise therapy practice"},{"key": "C","text": "A condition where all muscles are equally weak throughout the body"},{"key": "D","text": "Only relevant to elite athletes, never in general rehabilitation populations"}],"correct": "A","explanation": "Recognizing patterns of muscle imbalance (relative tightness/weakness) is a fundamental component of many exercise therapy assessment approaches, guiding targeted treatment addressing both flexibility and strength deficits."},{"id": 4763,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The 'bird dog' exercise, commonly used in core stabilization programs, primarily challenges which aspect of trunk control?","options": [{"key": "A","text": "Only upper body strength without any core component"},{"key": "B","text": "Purely flexibility of the lumbar spine"},{"key": "C","text": "Maintaining a stable, neutral spine position while moving the limbs (dynamic stability)"},{"key": "D","text": "Only static abdominal muscle activation without any limb movement"}],"correct": "C","explanation": "The bird dog exercise challenges the ability to maintain trunk/spinal stability while opposite arm and leg move, training dynamic core control relevant to functional activities."},{"id": 4764,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The 'dead bug' exercise is commonly used to train which aspect of core control?","options": [{"key": "A","text": "Only upper body power"},{"key": "B","text": "Maintaining a stable lumbar spine position (often in a posterior pelvic tilt) while moving the limbs"},{"key": "C","text": "Only hip flexor flexibility"},{"key": "D","text": "Purely balance training without any core stability component"}],"correct": "B","explanation": "The dead bug exercise trains anti-extension core control, teaching patients to maintain lumbar spine stability against the destabilizing forces of limb movement."},{"id": 4765,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The plank exercise primarily challenges the core musculature to resist which type of movement/force?","options": [{"key": "A","text": "Only lateral flexion"},{"key": "B","text": "Purely hip flexor strengthening"},{"key": "C","text": "Extension (anti-extension core stability)"},{"key": "D","text": "Only rotation"}],"correct": "C","explanation": "The standard plank primarily challenges the core's ability to resist spinal extension/sagging, an anti-extension stability exercise."},{"id": 4766,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "The side plank exercise primarily challenges the core musculature to resist which type of movement/force?","options": [{"key": "A","text": "Only spinal flexion"},{"key": "B","text": "Only rotation"},{"key": "C","text": "Purely hip extensor strengthening"},{"key": "D","text": "Lateral flexion (anti-lateral flexion core stability)"}],"correct": "D","explanation": "The side plank specifically challenges the lateral trunk muscles (obliques, quadratus lumborum) to resist lateral flexion/sagging of the trunk."},{"id": 4767,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Pallof press exercises, using resistance bands or cables, are primarily designed to train which core stability component?","options": [{"key": "A","text": "Only isolated hip strength"},{"key": "B","text": "Anti-rotation stability of the trunk"},{"key": "C","text": "Purely upper extremity power"},{"key": "D","text": "Only spinal flexion strength"}],"correct": "B","explanation": "The Pallof press challenges the core to resist rotational forces from the resistance, training important anti-rotation stability relevant to many functional and sporting activities."},{"id": 4768,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate progression from a basic plank exercise to increase core stability challenge?","options": [{"key": "A","text": "Reducing hold time without any other modification"},{"key": "B","text": "Adding limb movement (e.g., alternating arm/leg lifts) while maintaining the plank position"},{"key": "C","text": "Immediately progressing to a completely different, unrelated exercise"},{"key": "D","text": "Removing all core engagement from the exercise"}],"correct": "B","explanation": "Adding controlled limb movement while maintaining trunk stability in the plank position is a common progression strategy that increases the core stability demand."},{"id": 4769,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the primary purpose of the 'abdominal drawing-in maneuver' often taught early in core stabilization programs?","options": [{"key": "A","text": "Maximizing rectus abdominis hypertrophy"},{"key": "B","text": "Facilitating activation of the deep transversus abdominis muscle for spinal segmental stability"},{"key": "C","text": "Training explosive abdominal power"},{"key": "D","text": "Only used for aesthetic purposes without any stability function"}],"correct": "B","explanation": "This maneuver specifically targets activation of the deep transversus abdominis, important for providing segmental spinal stability, distinct from more superficial rectus abdominis-focused exercises."},{"id": 4770,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate progression consideration when a patient has mastered basic core stabilization exercises performed in supine/quadruped positions?","options": [{"key": "A","text": "Only continuing static positions indefinitely without functional progression"},{"key": "B","text": "Regressing to less challenging positions regardless of demonstrated mastery"},{"key": "C","text": "Progressing to more functional, upright positions and dynamic activities that better simulate real-world demands"},{"key": "D","text": "Assuming no further progression is needed once basic positions are mastered"}],"correct": "C","explanation": "Progressing core stabilization training toward upright, dynamic, functionally relevant positions helps ensure better carryover to the patient's actual daily activities and goals."},{"id": 4771,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'proximal stability for distal mobility' as applied to core/trunk exercise therapy?","options": [{"key": "A","text": "Adequate core/trunk stability provides a stable base allowing more effective and controlled movement of the extremities"},{"key": "B","text": "Proximal stability is only relevant for the lower extremities, not upper extremities"},{"key": "C","text": "Distal mobility should always be trained in isolation from proximal stability"},{"key": "D","text": "Core stability has no relationship to extremity movement quality"}],"correct": "A","explanation": "This principle recognizes that a stable trunk/core provides the necessary foundation for efficient, controlled movement of the arms and legs during functional activities."},{"id": 4772,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise consideration for a patient with significant low back pain who has difficulty performing standard core stabilization exercises in supine due to positional discomfort?","options": [{"key": "A","text": "Abandoning core stabilization training entirely due to positional discomfort"},{"key": "B","text": "Modifying the exercise position (e.g., using a supported position or alternative starting posture) while maintaining the core stability training goal"},{"key": "C","text": "Forcing the standard position regardless of reported discomfort"},{"key": "D","text": "Assuming position has no relevance to patient tolerance or comfort"}],"correct": "B","explanation": "Adapting exercise position while maintaining the underlying therapeutic goal helps ensure patients can safely and comfortably engage in core stabilization training despite initial positional limitations."},{"id": 4773,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the general purpose of a functional movement screening tool used prior to designing an exercise/training program?","options": [{"key": "A","text": "Diagnosing specific tissue pathology definitively"},{"key": "B","text": "Only relevant for elite athletes, never general rehabilitation populations"},{"key": "C","text": "Identifying movement pattern limitations or asymmetries that may increase injury risk or guide program design"},{"key": "D","text": "Replacing the need for any clinical examination"}],"correct": "C","explanation": "Functional movement screens help identify fundamental movement limitations or asymmetries that can inform targeted corrective exercise strategies within a broader exercise program."},{"id": 4774,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate use of a BOSU ball (half-dome balance trainer) in exercise therapy programming?","options": [{"key": "A","text": "Providing a completely stable, unchanging surface for exercise"},{"key": "B","text": "Introducing an unstable surface to progressively challenge balance and proprioception during various exercises"},{"key": "C","text": "A tool with no practical application in rehabilitation"},{"key": "D","text": "Only usable for upper extremity exercises"}],"correct": "B","explanation": "BOSU balls provide an accessible way to introduce surface instability, progressively challenging balance and neuromuscular control during a variety of therapeutic exercises."},{"id": 4775,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate use of a wobble board in balance/ankle rehabilitation programming?","options": [{"key": "A","text": "Providing a multidirectional unstable surface to challenge ankle/lower limb proprioception and control"},{"key": "B","text": "A device with no relevance to ankle rehabilitation"},{"key": "C","text": "Only usable for upper extremity strengthening"},{"key": "D","text": "Providing a completely fixed, stable surface"}],"correct": "A","explanation": "Wobble boards create multidirectional instability that specifically challenges ankle and lower limb proprioceptive control, commonly used in ankle sprain and balance rehabilitation programs."},{"id": 4776,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate use of a foam roller in exercise therapy, based on current understanding of self-myofascial release?","options": [{"key": "A","text": "Only used for cardiovascular conditioning"},{"key": "B","text": "A tool with no evidence-based rationale for use"},{"key": "C","text": "Applying sustained or rolling pressure to soft tissue, potentially providing temporary improvements in tissue extensibility/perceived tightness"},{"key": "D","text": "A technique that permanently alters muscle tissue structure"}],"correct": "C","explanation": "Foam rolling is commonly used for self-myofascial release, with evidence suggesting temporary benefits in perceived muscle tightness/extensibility, often used adjunctively with other exercise interventions."},{"id": 4777,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate use of therapy putty or hand therapy resistance tools in upper extremity rehabilitation?","options": [{"key": "A","text": "Only usable for lower extremity strengthening"},{"key": "B","text": "A tool with no practical clinical application"},{"key": "C","text": "Providing graded resistance for fine motor and grip strengthening exercises, particularly useful in hand/wrist rehabilitation"},{"key": "D","text": "Only appropriate for pediatric patients, never adults"}],"correct": "C","explanation": "Therapy putty and similar resistance tools provide accessible, gradable resistance specifically useful for targeting hand intrinsic muscles, grip strength, and fine motor control in upper extremity rehabilitation."},{"id": 4778,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate use of a treadmill with body-weight support in gait rehabilitation for patients with significant weakness?","options": [{"key": "A","text": "Allowing controlled practice of gait patterns while reducing the full weight-bearing demand, useful in early neurological or orthopedic rehabilitation"},{"key": "B","text": "Providing no meaningful benefit compared to standard overground gait training"},{"key": "C","text": "A tool contraindicated for any rehabilitation purpose"},{"key": "D","text": "Only usable for elite athletic conditioning"}],"correct": "A","explanation": "Body-weight supported treadmill training allows patients with significant weakness to practice gait mechanics with reduced loading demand, often used in early stroke or spinal cord injury rehabilitation before progressing to full weight-bearing."},{"id": 4779,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration when using an underwater treadmill (aquatic treadmill) for gait rehabilitation?","options": [{"key": "A","text": "Aquatic treadmills are only appropriate for elite athletes"},{"key": "B","text": "Buoyancy reduces effective body weight/joint loading while water resistance can add a strengthening component to gait training"},{"key": "C","text": "Water provides no meaningful physiological benefit compared to standard treadmill training"},{"key": "D","text": "Complete absence of any resistance occurs during aquatic treadmill walking"}],"correct": "B","explanation": "Aquatic treadmill training combines buoyancy-related load reduction with water's resistive properties, offering unique benefits for patients needing reduced joint loading while still challenging strength/endurance."},{"id": 4780,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate use of a stationary recumbent bike in early cardiac or orthopedic rehabilitation?","options": [{"key": "A","text": "A modality with no role in early rehabilitation settings"},{"key": "B","text": "Providing a lower-impact aerobic conditioning option with reduced joint loading and cardiovascular demand compared to some other modalities"},{"key": "C","text": "Only appropriate for elite athletic training"},{"key": "D","text": "Providing identical demand to high-impact running regardless of positioning"}],"correct": "B","explanation": "The recumbent bike's supported, low-impact design makes it a useful early aerobic conditioning tool for patients who may not yet tolerate more demanding weight-bearing cardiovascular activities."},{"id": 4781,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with pelvic organ prolapse?","options": [{"key": "A","text": "Encouraging maximal intra-abdominal pressure exercises regardless of prolapse severity"},{"key": "B","text": "Complete avoidance of any exercise indefinitely"},{"key": "C","text": "Assuming pelvic floor exercise has no role in prolapse management"},{"key": "D","text": "Pelvic floor muscle strengthening combined with avoidance of excessive intra-abdominal pressure during exercise (e.g., modifying heavy lifting technique)"}],"correct": "D","explanation": "Pelvic floor strengthening combined with mindful management of intra-abdominal pressure during exercise is a cornerstone of conservative prolapse management."},{"id": 4782,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy approach for diastasis recti abdominis in the postpartum period?","options": [{"key": "A","text": "Complete avoidance of any abdominal exercise indefinitely"},{"key": "B","text": "Maximal traditional crunches immediately postpartum regardless of separation severity"},{"key": "C","text": "Gentle, progressive core activation exercises (e.g., transversus abdominis engagement) while avoiding exercises that excessively increase intra-abdominal pressure or doming"},{"key": "D","text": "Assuming diastasis recti has no relevance to exercise selection"}],"correct": "C","explanation": "Postpartum diastasis recti management emphasizes gentle, functional core activation while avoiding exercises (like traditional crunches) that may exacerbate abdominal wall doming or separation."},{"id": 4783,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for pregnancy-related pelvic girdle pain?","options": [{"key": "A","text": "Ignoring any positional modification considerations"},{"key": "B","text": "Complete avoidance of any exercise throughout pregnancy"},{"key": "C","text": "Pelvic stabilization exercises and activity modification, often avoiding asymmetrical loading positions that provoke symptoms"},{"key": "D","text": "Aggressive high-impact exercise regardless of symptom provocation"}],"correct": "C","explanation": "Pregnancy-related pelvic girdle pain management typically involves targeted stabilization exercises and thoughtful activity modification to minimize symptom-provoking positions and movements."},{"id": 4784,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with stress urinary incontinence related to weak pelvic floor muscles?","options": [{"key": "A","text": "Complete avoidance of any exercise intervention"},{"key": "B","text": "Immediate surgical referral without attempting conservative exercise-based management first"},{"key": "C","text": "Assuming pelvic floor exercise has no evidence supporting its use"},{"key": "D","text": "A structured pelvic floor muscle training program (e.g., Kegel exercises) is considered a first-line conservative treatment"}],"correct": "D","explanation": "Pelvic floor muscle training is well-supported as an effective first-line conservative intervention for stress urinary incontinence, often recommended before considering surgical options."},{"id": 4785,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an important consideration when teaching a patient to correctly perform a pelvic floor (Kegel) contraction?","options": [{"key": "A","text": "Ensuring the patient isolates the pelvic floor muscles without excessively contracting the gluteal, abdominal, or thigh muscles"},{"key": "B","text": "Assuming correct technique does not require any specific instruction or feedback"},{"key": "C","text": "Encouraging maximal simultaneous contraction of all surrounding muscle groups"},{"key": "D","text": "Ignoring whether the patient is performing the correct muscle contraction"}],"correct": "A","explanation": "Proper Kegel exercise technique requires isolated pelvic floor activation; compensatory use of surrounding muscle groups can reduce exercise effectiveness and requires correction through appropriate cueing/feedback."},{"id": 4786,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a new prosthetic user regarding gait training progression?","options": [{"key": "A","text": "Immediate independent ambulation without any graded assistive device progression"},{"key": "B","text": "Assuming standard gait training principles do not apply to prosthetic rehabilitation"},{"key": "C","text": "Complete avoidance of gait training until the prosthesis is 'perfectly' fitted"},{"key": "D","text": "Progressing from parallel bars to less restrictive assistive devices as balance and confidence with the prosthesis improve"}],"correct": "D","explanation": "Prosthetic gait training typically follows a graded progression of assistive device support as the patient develops confidence, balance, and appropriate prosthetic control."},{"id": 4787,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an important exercise therapy consideration regarding residual limb volume management in a new lower limb amputee?","options": [{"key": "A","text": "Consistent use of compression wrapping/shrinker socks combined with appropriate exercise to manage volume fluctuation affecting prosthetic fit"},{"key": "B","text": "Avoiding any compression garment use during the rehabilitation process"},{"key": "C","text": "Ignoring volume changes since they have no bearing on prosthetic fit"},{"key": "D","text": "Assuming residual limb volume remains completely constant regardless of intervention"}],"correct": "A","explanation": "Managing residual limb volume through compression techniques is important for maintaining consistent prosthetic socket fit, directly impacting comfort and gait quality during rehabilitation."},{"id": 4788,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate wheelchair skills training component for a new manual wheelchair user?","options": [{"key": "A","text": "Only practicing propulsion on a completely flat, obstacle-free surface indefinitely"},{"key": "B","text": "Practicing propulsion technique, transfers, and negotiating environmental obstacles (curbs, ramps) in a graded, supervised manner"},{"key": "C","text": "Assuming wheelchair skills require no specific training beyond basic propulsion"},{"key": "D","text": "Immediate unsupervised practice of complex environmental navigation without any graded progression"}],"correct": "B","explanation": "Comprehensive wheelchair skills training addresses the range of functional demands (propulsion, transfers, obstacle negotiation) needed for safe, independent community mobility."},{"id": 4789,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for proper wheelchair propulsion technique to minimize upper extremity overuse injury risk?","options": [{"key": "A","text": "Using a smooth, efficient stroke pattern with appropriate hand placement on the push rim, avoiding excessive shoulder strain"},{"key": "B","text": "Encouraging maximal speed regardless of technique quality"},{"key": "C","text": "Assuming propulsion technique has no bearing on injury risk"},{"key": "D","text": "Ignoring any biomechanical considerations during wheelchair skills training"}],"correct": "A","explanation": "Teaching efficient, biomechanically sound propulsion technique is an important preventive strategy against the high rates of upper extremity overuse injury seen in long-term wheelchair users."},{"id": 4790,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient transitioning from a manual to a power wheelchair due to progressive upper extremity weakness (e.g., in ALS)?","options": [{"key": "A","text": "Ensuring appropriate positioning, seating, and safe operation training for the power wheelchair while addressing the patient's evolving functional needs"},{"key": "B","text": "Continuing to insist on manual wheelchair use despite significant progressive weakness"},{"key": "C","text": "Ignoring seating/positioning considerations during the transition"},{"key": "D","text": "Assuming the transition requires no specific therapeutic input or training"}],"correct": "A","explanation": "As progressive conditions like ALS advance, appropriate and timely transition to power mobility, along with proper seating/positioning assessment, is an important physiotherapy consideration for maintaining function and safety."},{"id": 4791,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Dynamic Gait Index (DGI) is used clinically to assess:","options": [{"key": "A","text": "Pulmonary function exclusively"},{"key": "B","text": "Isolated static balance only"},{"key": "C","text": "A patient's ability to modify gait in response to changing task demands, useful for fall risk assessment"},{"key": "D","text": "Upper extremity strength exclusively"}],"correct": "C","explanation": "The DGI evaluates gait adaptability across various challenging tasks (e.g., changing speeds, turning, stepping over obstacles), providing insight into functional gait-related fall risk."},{"id": 4792,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Activities-specific Balance Confidence (ABC) Scale is a self-report measure assessing:","options": [{"key": "A","text": "Objective muscle strength grading"},{"key": "B","text": "Cognitive function exclusively"},{"key": "C","text": "A patient's confidence in performing various activities without losing balance"},{"key": "D","text": "Cardiovascular endurance capacity"}],"correct": "C","explanation": "The ABC Scale captures the patient's own perceived balance confidence across a range of daily activities, complementing objective performance-based balance measures."},{"id": 4793,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Lower Extremity Functional Scale (LEFS) is a patient-reported outcome measure used to assess:","options": [{"key": "A","text": "Cardiovascular fitness exclusively"},{"key": "B","text": "Functional limitations related to lower extremity musculoskeletal conditions"},{"key": "C","text": "Upper extremity function exclusively"},{"key": "D","text": "Cognitive function"}],"correct": "B","explanation": "The LEFS captures patient-perceived difficulty with various functional activities related to lower limb conditions, useful for tracking progress across many orthopedic diagnoses."},{"id": 4794,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The Knee Injury and Osteoarthritis Outcome Score (KOOS) is a condition-specific outcome measure used for patients with:","options": [{"key": "A","text": "Isolated shoulder conditions"},{"key": "B","text": "Isolated pulmonary conditions"},{"key": "C","text": "Isolated cognitive impairment"},{"key": "D","text": "Knee-related pathology, including osteoarthritis and ligamentous injury"}],"correct": "D","explanation": "The KOOS is specifically designed to capture patient-reported outcomes related to knee conditions across multiple domains including pain, symptoms, and function."},{"id": 4795,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Shoulder Pain and Disability Index (SPADI) is used clinically to assess:","options": [{"key": "A","text": "Patient-reported pain and functional disability specifically related to shoulder conditions"},{"key": "B","text": "General health-related quality of life without condition specificity"},{"key": "C","text": "Lower extremity function exclusively"},{"key": "D","text": "Cognitive function exclusively"}],"correct": "A","explanation": "The SPADI is a condition-specific outcome measure capturing both pain and disability domains relevant to various shoulder pathologies."},{"id": 4796,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The Neck Disability Index (NDI) is a self-report outcome measure specifically used to assess functional limitation related to:","options": [{"key": "A","text": "Cervical spine conditions"},{"key": "B","text": "Isolated lower extremity conditions"},{"key": "C","text": "Isolated shoulder conditions"},{"key": "D","text": "Lumbar spine conditions exclusively"}],"correct": "A","explanation": "The NDI is widely used to capture patient-perceived disability specifically related to neck pain and cervical spine dysfunction."},{"id": 4797,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 5-Times Sit-to-Stand Test is commonly used clinically as a measure of:","options": [{"key": "A","text": "Functional lower extremity strength and power, along with associated fall risk implications"},{"key": "B","text": "Cardiovascular endurance exclusively"},{"key": "C","text": "Cognitive processing speed"},{"key": "D","text": "Isolated upper extremity strength"}],"correct": "A","explanation": "This simple, practical test measures the time to complete five chair rises, correlating with lower extremity strength/power and providing insight into functional mobility and fall risk."},{"id": 4798,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "The Star Excursion Balance Test is commonly used in sports rehabilitation to assess:","options": [{"key": "A","text": "Cardiovascular fitness exclusively"},{"key": "B","text": "Isolated static balance only"},{"key": "C","text": "Upper extremity power exclusively"},{"key": "D","text": "Dynamic postural control and lower extremity reach capability in multiple directions"}],"correct": "D","explanation": "This test challenges dynamic single-leg balance while reaching in multiple directions, commonly used to assess readiness for return to sport and identify asymmetries."},{"id": 4799,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Grip strength dynamometry is commonly used clinically as:","options": [{"key": "A","text": "Only relevant to isolated hand pathology assessment"},{"key": "B","text": "A measure of cardiovascular fitness"},{"key": "C","text": "A measure of balance"},{"key": "D","text": "A measure of overall hand/forearm strength, sometimes also used as a general indicator of overall health/frailty status"}],"correct": "D","explanation": "Beyond assessing hand-specific conditions, grip strength has been increasingly recognized as a broader marker correlating with overall health status and frailty in various populations."},{"id": 4800,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best describes the purpose of using a standardized, validated outcome measure rather than a therapist's subjective clinical impression alone to track patient progress?","options": [{"key": "A","text": "Providing objective, reproducible data that reduces bias and supports evidence-based clinical decision-making"},{"key": "B","text": "Standardized measures are always inferior to purely subjective clinical judgment"},{"key": "C","text": "Standardized outcome measures cannot be used to communicate progress to other providers"},{"key": "D","text": "Objective measures have no advantage over subjective impressions"}],"correct": "A","explanation": "Validated outcome measures provide objective, consistent data supporting more reliable tracking of progress and communication among healthcare providers, complementing (not replacing) clinical judgment."},{"id": 4801,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Maitland's grades of joint mobilization I and II are typically used primarily to address:","options": [{"key": "A","text": "Only muscle strengthening, not joint mobility"},{"key": "B","text": "Pain, using small-amplitude oscillatory movements within the available range"},{"key": "C","text": "Complete joint fusion"},{"key": "D","text": "Significant joint stiffness requiring large-amplitude movements into resistance"}],"correct": "B","explanation": "Grades I and II are gentle, small-amplitude oscillations performed within the pain-free range, primarily used to help modulate pain rather than aggressively increase range."},{"id": 4802,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Maitland's grades of joint mobilization III and IV are typically used primarily to address:","options": [{"key": "A","text": "Only used for acute, highly irritable conditions"},{"key": "B","text": "Pain relief exclusively without any effect on stiffness"},{"key": "C","text": "Joint stiffness, using larger-amplitude movements into the tissue resistance/end range"},{"key": "D","text": "Muscle strengthening exclusively"}],"correct": "C","explanation": "Grades III and IV involve larger movements into or through the tissue resistance, primarily aimed at addressing joint stiffness/hypomobility rather than pure pain modulation."},{"id": 4803,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "Which of the following describes an appropriate rationale for combining joint mobilization techniques with therapeutic exercise in a comprehensive treatment plan?","options": [{"key": "A","text": "Mobilization and exercise should never be used together within the same treatment session"},{"key": "B","text": "Joint mobilization has no relationship to exercise effectiveness"},{"key": "C","text": "Exercise should always precede mobilization to avoid any therapeutic benefit"},{"key": "D","text": "Mobilization may help address joint mobility restrictions, allowing more effective subsequent exercise to reinforce and maintain the gained range"}],"correct": "D","explanation": "Combining mobilization to address specific joint restrictions with subsequent therapeutic exercise can help reinforce and functionally utilize any mobility gains achieved, representing a complementary treatment approach."},{"id": 4804,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate rationale for applying a heat modality (e.g., moist heat pack) prior to a stretching exercise session?","options": [{"key": "A","text": "Heat modalities are contraindicated before any stretching exercise"},{"key": "B","text": "Heat application has no physiological effect on tissue extensibility"},{"key": "C","text": "Increasing tissue temperature and extensibility, potentially enhancing the effectiveness of subsequent stretching"},{"key": "D","text": "Heat should always be applied only after exercise, never before stretching"}],"correct": "C","explanation": "Pre-stretching heat application can increase collagen extensibility and reduce tissue viscosity, potentially enhancing the effectiveness of subsequent stretching interventions."},{"id": 4805,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate rationale for applying cryotherapy (ice) following an acute exercise-related soft tissue injury?","options": [{"key": "A","text": "Increasing tissue temperature to enhance blood flow immediately post-injury"},{"key": "B","text": "Helping to manage acute pain and swelling in the early post-injury period"},{"key": "C","text": "Cryotherapy has no role in acute soft tissue injury management"},{"key": "D","text": "Ice should always be applied for several hours continuously without interruption"}],"correct": "B","explanation": "Cryotherapy is commonly used in the acute phase to help manage pain and limit swelling, complementing the broader management approach for acute soft tissue injuries."},{"id": 4806,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate consideration regarding the use of therapeutic ultrasound as an adjunct to exercise therapy for certain musculoskeletal conditions?","options": [{"key": "A","text": "Ultrasound should always replace exercise therapy entirely"},{"key": "B","text": "Ultrasound has definitively proven superior efficacy compared to all other treatment modalities"},{"key": "C","text": "Ultrasound alone is considered superior to active exercise therapy for most musculoskeletal conditions"},{"key": "D","text": "May be used by some clinicians as an adjunctive modality, though current evidence for its independent effectiveness is often considered limited compared to active exercise interventions"}],"correct": "D","explanation": "While therapeutic ultrasound continues to be used adjunctively by some clinicians, current evidence generally supports active exercise therapy as having stronger evidence for effectiveness in most musculoskeletal conditions."},{"id": 4807,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate use of kinesiology taping as an adjunct to exercise therapy?","options": [{"key": "A","text": "Kinesiology tape provides definitive proven structural support equivalent to rigid bracing"},{"key": "B","text": "Kinesiology taping has no plausible physiological rationale for use"},{"key": "C","text": "May be used to provide sensory feedback or support during functional movement, though evidence for its specific mechanical effects remains debated"},{"key": "D","text": "Taping should always replace active exercise and strengthening approaches"}],"correct": "C","explanation": "Kinesiology taping is sometimes used to provide sensory/proprioceptive feedback during movement, though it should generally complement rather than replace active exercise-based rehabilitation approaches."},{"id": 4808,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration when treating a patient with a healing surgical incision, regarding scar tissue mobility?","options": [{"key": "A","text": "Scar tissue has no potential impact on subsequent movement or exercise tolerance"},{"key": "B","text": "Aggressive scar manipulation should begin immediately over an open, unhealed incision"},{"key": "C","text": "Once appropriately healed, gentle scar mobilization techniques may be incorporated alongside exercise to address adhesions affecting movement"},{"key": "D","text": "Scar tissue should never be addressed regardless of its impact on movement"}],"correct": "C","explanation": "Once adequately healed, addressing scar tissue mobility through appropriate techniques can help improve any adhesion-related movement restrictions, complementing broader exercise therapy goals."},{"id": 4809,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Work conditioning/hardening programs in physiotherapy primarily aim to:","options": [{"key": "A","text": "Focus exclusively on pain management without any functional/work-related goals"},{"key": "B","text": "Only provide passive treatment without any active exercise component"},{"key": "C","text": "Progressively build a patient's functional capacity to meet the specific physical demands of their job for safe return to work"},{"key": "D","text": "Guarantee immediate full return to work regardless of functional capacity"}],"correct": "C","explanation": "Work conditioning programs use progressive, job-specific exercise to systematically build the strength, endurance, and functional capacity needed for safe return to occupational demands."},{"id": 4810,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "A functional capacity evaluation (FCE) is used in occupational rehabilitation primarily to:","options": [{"key": "A","text": "Diagnose a specific medical condition"},{"key": "B","text": "Only assess psychological readiness for work, not physical capacity"},{"key": "C","text": "Objectively assess a patient's physical abilities in relation to specific job demands"},{"key": "D","text": "Replace the need for any physician involvement in return-to-work decisions"}],"correct": "C","explanation": "FCEs provide standardized, objective assessment of functional physical capabilities, informing return-to-work planning and identifying any gaps relative to job demands."},{"id": 4811,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate ergonomic consideration when addressing a patient with work-related low back pain from prolonged sitting?","options": [{"key": "A","text": "Ignoring workstation setup considerations entirely"},{"key": "B","text": "Recommending the patient remain in a single fixed position for the entire workday"},{"key": "C","text": "Assuming ergonomic modification has no relevance to symptom management"},{"key": "D","text": "Educating on proper workstation setup, including chair height/support and encouraging regular position changes/breaks"}],"correct": "D","explanation": "Ergonomic education addressing workstation setup and encouraging regular movement/position changes is an important component of managing and preventing work-related musculoskeletal symptoms."},{"id": 4812,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a repetitive strain injury related to their occupation (e.g., typing-related wrist pain)?","options": [{"key": "A","text": "Only providing rest without any addressing of contributing occupational factors"},{"key": "B","text": "Ignoring the need for any ergonomic modification recommendations"},{"key": "C","text": "Assuming occupational factors have no relevance to the treatment plan"},{"key": "D","text": "Addressing contributing biomechanical/ergonomic factors alongside targeted strengthening and flexibility exercise for the affected structures"}],"correct": "D","explanation": "Effective management of repetitive strain injuries typically requires addressing both the tissue-specific impairment through exercise and the underlying occupational/ergonomic factors contributing to the condition."},{"id": 4813,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of graded work exposure/simulation in occupational rehabilitation?","options": [{"key": "A","text": "A concept with no practical application to occupational rehabilitation"},{"key": "B","text": "Complete avoidance of any work-related task simulation during rehabilitation"},{"key": "C","text": "Immediate full return to unmodified work duties regardless of current functional capacity"},{"key": "D","text": "Gradually reintroducing job-specific tasks/demands in a controlled, progressive manner to build tolerance and confidence for return to actual work"}],"correct": "D","explanation": "Graded work exposure allows patients to progressively build tolerance to specific job demands within a controlled rehabilitation setting before transitioning to actual full work duties."},{"id": 4814,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the Schroth method, a specialized exercise approach used in scoliosis management?","options": [{"key": "A","text": "A purely passive bracing technique without any active exercise component"},{"key": "B","text": "An approach used exclusively for treating osteoarthritis"},{"key": "C","text": "A technique with no evidence base for scoliosis management"},{"key": "D","text": "A three-dimensional, curve-specific exercise approach aimed at correcting posture and improving respiratory function in scoliosis"}],"correct": "D","explanation": "The Schroth method uses individualized, curve-pattern-specific exercises addressing three-dimensional postural correction and breathing patterns in scoliosis management."},{"id": 4815,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with mild-to-moderate idiopathic scoliosis being monitored (not requiring bracing/surgery)?","options": [{"key": "A","text": "Postural awareness exercises and general strengthening/flexibility, sometimes combined with curve-specific approaches like Schroth exercises"},{"key": "B","text": "Complete avoidance of any exercise due to the spinal curvature diagnosis"},{"key": "C","text": "Assuming exercise has no potential role in scoliosis management"},{"key": "D","text": "Only bracing is appropriate, with exercise having no complementary role"}],"correct": "A","explanation": "Exercise-based approaches, including general conditioning and specialized curve-specific programs, may play a complementary role in managing mild-to-moderate scoliosis alongside monitoring and other interventions."},{"id": 4816,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed vertebral compression fracture secondary to osteoporosis?","options": [{"key": "A","text": "Avoiding spinal flexion-based exercises initially, favoring extension-oriented and postural exercises with appropriate pain-guided progression"},{"key": "B","text": "Assuming fracture history has no bearing on appropriate exercise selection"},{"key": "C","text": "Complete avoidance of any exercise indefinitely following the fracture"},{"key": "D","text": "Encouraging maximal spinal flexion exercises immediately post-fracture"}],"correct": "A","explanation": "Given the increased fracture risk with flexion loading in osteoporotic spines, extension-biased and postural exercises are generally favored over flexion-based approaches following vertebral compression fracture."},{"id": 4817,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'frailty' as relevant to geriatric exercise therapy planning?","options": [{"key": "A","text": "A state of increased vulnerability to stressors due to decline across multiple physiological systems, often assessed through measures like gait speed and grip strength"},{"key": "B","text": "A concept only relevant to bedridden patients"},{"key": "C","text": "A condition unrelated to exercise capacity or fall risk"},{"key": "D","text": "A term synonymous simply with advanced chronological age regardless of functional status"}],"correct": "A","explanation": "Frailty represents a multidimensional decline in physiological reserve, distinct from age alone, and is often assessed through functional measures relevant to exercise therapy planning and risk stratification."},{"id": 4818,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a frail older adult beginning a rehabilitation program?","options": [{"key": "A","text": "Immediately prescribing standard, non-modified exercise intensity regardless of frailty status"},{"key": "B","text": "Starting with lower-intensity, closely supervised exercise and progressing very gradually based on individual tolerance"},{"key": "C","text": "Avoiding all forms of exercise due to frailty concerns"},{"key": "D","text": "Assuming frailty status has no bearing on exercise program design"}],"correct": "B","explanation": "Frail older adults benefit from carefully graded, closely supervised exercise progression that accounts for their increased vulnerability while still working to build functional capacity."},{"id": 4819,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with sarcopenic obesity (low muscle mass combined with excess adiposity)?","options": [{"key": "A","text": "Assuming this combined condition requires no specific exercise modification"},{"key": "B","text": "Only resistance training without any aerobic component"},{"key": "C","text": "Combined resistance and aerobic exercise addressing both muscle mass/strength and overall body composition"},{"key": "D","text": "Only aerobic exercise without any resistance training component"}],"correct": "C","explanation": "Sarcopenic obesity benefits from a combined exercise approach targeting both muscle strengthening (to address sarcopenia) and aerobic conditioning (to address overall body composition and metabolic health)."},{"id": 4820,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient experiencing polypharmacy-related dizziness affecting balance and exercise participation?","options": [{"key": "A","text": "Assuming medication effects have no relevance to exercise therapy planning"},{"key": "B","text": "Ignoring any reported dizziness during exercise sessions"},{"key": "C","text": "Immediately discontinuing all physiotherapy involvement due to medication complexity"},{"key": "D","text": "Awareness of potential medication side effects on balance/blood pressure, coordinating with the medical team while implementing appropriate safety precautions during exercise"}],"correct": "D","explanation": "Recognizing potential medication-related contributors to balance impairment and appropriately coordinating care while implementing safety precautions is an important aspect of comprehensive geriatric exercise therapy."},{"id": 4821,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an older adult with orthostatic hypotension participating in an exercise program?","options": [{"key": "A","text": "Incorporating position change precautions (e.g., gradual transitions from lying to standing) and monitoring blood pressure response"},{"key": "B","text": "Assuming orthostatic hypotension has no bearing on exercise therapy safety"},{"key": "C","text": "Encouraging rapid position changes regardless of reported symptoms"},{"key": "D","text": "Avoiding all forms of exercise due to this condition"}],"correct": "A","explanation": "Given the fall risk associated with orthostatic hypotension, incorporating gradual position change strategies and appropriate monitoring helps ensure safe exercise participation in affected individuals."},{"id": 4822,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with age-related presbyopia or other visual impairment affecting balance training?","options": [{"key": "A","text": "Considering alternative sensory cues (e.g., verbal, tactile) and appropriate environmental safety modifications during balance/gait training"},{"key": "B","text": "Avoiding any balance training due to visual impairment"},{"key": "C","text": "Relying exclusively on visual demonstration without any alternative cueing strategies"},{"key": "D","text": "Assuming visual impairment has no bearing on balance training approach"}],"correct": "A","explanation": "Visual impairment can significantly affect balance training approaches, requiring consideration of alternative sensory cues and appropriate environmental modifications to ensure safe, effective training."},{"id": 4823,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an older adult with mild cognitive changes affecting exercise instruction retention?","options": [{"key": "A","text": "Assuming cognitive status has no bearing on exercise instruction approach"},{"key": "B","text": "Avoiding any exercise program due to mild cognitive changes"},{"key": "C","text": "Providing complex, lengthy verbal instructions regardless of cognitive status"},{"key": "D","text": "Using simple, consistent instructions with appropriate repetition and demonstration to support learning and safe participation"}],"correct": "D","explanation": "Adapting instructional approaches (simplification, repetition, demonstration) helps support safe and effective exercise participation in older adults experiencing mild cognitive changes."},{"id": 4824,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with De Quervain's tenosynovitis?","options": [{"key": "A","text": "Activity modification and progressive strengthening of the thumb/wrist musculature once acute inflammation subsides, along with addressing contributing repetitive movements"},{"key": "B","text": "Ignoring any contributing repetitive activity factors"},{"key": "C","text": "Complete avoidance of any exercise indefinitely"},{"key": "D","text": "Immediate aggressive resistance training regardless of acute inflammation status"}],"correct": "A","explanation": "De Quervain's management typically progresses from activity modification and gentle range of motion during acute inflammation to progressive strengthening, while addressing repetitive movement patterns that may have contributed to the condition."},{"id": 4825,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a hamstring strain injury during the subacute healing phase?","options": [{"key": "A","text": "Immediate return to maximal sprinting regardless of healing stage"},{"key": "B","text": "Aggressive stretching to the point of significant pain immediately post-injury"},{"key": "C","text": "Complete avoidance of any exercise until full healing is presumed complete"},{"key": "D","text": "Progressive, pain-guided stretching and strengthening, with careful attention to avoiding re-injury from premature aggressive loading"}],"correct": "D","explanation": "Hamstring strain rehabilitation follows a graded progression through healing phases, with careful, symptom-guided advancement of loading to minimize the well-recognized risk of re-injury."},{"id": 4826,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with groin strain (adductor injury)?","options": [{"key": "A","text": "Complete avoidance of any lower limb exercise"},{"key": "B","text": "Immediate return to full sporting activity without any graded rehabilitation"},{"key": "C","text": "Progressive adductor strengthening exercises, often including both isometric and dynamic loading as tolerated"},{"key": "D","text": "Only stretching without any strengthening component"}],"correct": "C","explanation": "Groin/adductor strain rehabilitation typically follows a structured progression of strengthening exercises, often beginning with isometrics before advancing to more dynamic, sport-specific loading."},{"id": 4827,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a calf muscle strain (gastrocnemius/soleus)?","options": [{"key": "A","text": "Immediate return to running regardless of healing status"},{"key": "B","text": "Ignoring any graded progression principles during rehabilitation"},{"key": "C","text": "Progressive loading program addressing both strength and flexibility, with gradual return to functional/sporting activities as tolerated"},{"key": "D","text": "Complete avoidance of any calf-related exercise indefinitely"}],"correct": "C","explanation": "Calf strain management follows similar principles to other muscle strains, with progressive loading and functional restoration guided by tissue healing timelines and symptom response."},{"id": 4828,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a stress reaction (early-stage stress fracture) of the tibia?","options": [{"key": "A","text": "Immediate return to full training intensity without any modification"},{"key": "B","text": "Continuing unmodified high-impact training regardless of the diagnosis"},{"key": "C","text": "Complete permanent cessation of any physical activity"},{"key": "D","text": "A period of relative load reduction/modification, often including cross-training with lower-impact activities, followed by gradual return to full loading"}],"correct": "D","explanation": "Stress reaction management typically involves temporary load modification (often incorporating alternative lower-impact training) to allow bone healing before gradually progressing back to full activity."},{"id": 4829,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed labral tear of the hip?","options": [{"key": "A","text": "Addressing hip strength/stability and movement patterns, with treatment approach influenced by whether surgical or conservative management is planned"},{"key": "B","text": "Complete avoidance of any hip-related exercise regardless of management approach"},{"key": "C","text": "Assuming labral tears have no relevance to exercise therapy planning"},{"key": "D","text": "Immediate high-impact activity regardless of symptom status"}],"correct": "A","explanation": "Hip labral tear management varies based on the overall treatment plan (conservative vs. surgical), but generally involves addressing hip strength, stability, and movement pattern contributions to the condition."},{"id": 4830,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for femoroacetabular impingement (FAI) syndrome?","options": [{"key": "A","text": "Encouraging maximal hip flexion range of motion exercises regardless of symptom provocation"},{"key": "B","text": "Assuming movement pattern has no relevance to FAI symptom management"},{"key": "C","text": "Addressing hip and core strength/control along with movement pattern modification to reduce symptomatic impingement positions"},{"key": "D","text": "Complete avoidance of any hip exercise"}],"correct": "C","explanation": "FAI management often emphasizes strengthening and movement pattern retraining to reduce provocative positions/loads at the hip, complementing any indicated medical/surgical management."},{"id": 4831,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed SLAP tear (superior labrum anterior-posterior) of the shoulder?","options": [{"key": "A","text": "Complete avoidance of any shoulder exercise"},{"key": "B","text": "Addressing rotator cuff and scapular strength/control, with specific exercise selection guided by symptom provocation and any surgical considerations"},{"key": "C","text": "Immediate aggressive overhead activity regardless of symptoms"},{"key": "D","text": "Assuming scapular control has no relevance to this condition"}],"correct": "B","explanation": "SLAP tear management typically addresses the broader shoulder complex strength and control, with careful attention to positions/movements that provoke labral symptoms during exercise progression."},{"id": 4832,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an infant with torticollis regarding positioning during play/tummy time?","options": [{"key": "A","text": "Avoiding any positioning intervention for this condition"},{"key": "B","text": "Complete avoidance of tummy time indefinitely"},{"key": "C","text": "Assuming positioning has no relevance to torticollis management"},{"key": "D","text": "Encouraging tummy time and positioning that promotes active neck rotation/stretching away from the tight side under supervision"}],"correct": "D","explanation": "Structured tummy time and positioning strategies that encourage active movement away from the tight side are core components of conservative torticollis management in infants."},{"id": 4833,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child with hypotonia (low muscle tone) affecting gross motor development?","options": [{"key": "A","text": "Assuming hypotonia has no bearing on exercise program design"},{"key": "B","text": "Only passive range of motion without any active strengthening component"},{"key": "C","text": "Activities promoting postural stability, strengthening, and functional gross motor skill development appropriate to the child's developmental stage"},{"key": "D","text": "Complete avoidance of any physical activity due to low tone"}],"correct": "C","explanation": "Pediatric physiotherapy for hypotonia typically emphasizes active strengthening and stability-promoting activities to support gross motor skill acquisition appropriate to the child's developmental level."},{"id": 4834,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following developmental gross motor milestones would typically be expected by around 12 months of age, relevant to pediatric physiotherapy assessment?","options": [{"key": "A","text": "Independent walking (though a range of normal variation exists)"},{"key": "B","text": "Independent running with good coordination"},{"key": "C","text": "Complex hopping/skipping patterns"},{"key": "D","text": "Riding a bicycle independently"}],"correct": "A","explanation": "While normal variation exists, independent walking typically emerges around 12 months, representing a key gross motor milestone assessed in pediatric physiotherapy evaluation."},{"id": 4835,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child with juvenile idiopathic arthritis during a period of active joint inflammation?","options": [{"key": "A","text": "Assuming active inflammation has no bearing on appropriate exercise selection"},{"key": "B","text": "Gentle range of motion exercises to maintain mobility while avoiding excessive loading of actively inflamed joints"},{"key": "C","text": "Complete immobilization of all joints indefinitely"},{"key": "D","text": "Aggressive high-impact activity regardless of active inflammation"}],"correct": "B","explanation": "During active JIA flares, gentle mobility work helps maintain joint range while avoiding excessive stress on inflamed joints, with more aggressive strengthening reserved for periods of better disease control."},{"id": 4836,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child recovering from a supracondylar humerus fracture once cleared for mobilization?","options": [{"key": "A","text": "Complete avoidance of any exercise for an extended period after clearance"},{"key": "B","text": "Immediate full unrestricted activity regardless of healing stage"},{"key": "C","text": "Gradual, progressive range of motion and strengthening exercises following the surgeon's specific protocol and healing timeline"},{"key": "D","text": "Ignoring any surgeon-specific protocol considerations"}],"correct": "C","explanation": "Pediatric fracture rehabilitation follows structured, gradual progression per surgical/medical guidance, similar in principle to adult fracture rehabilitation but with attention to pediatric-specific healing considerations."},{"id": 4837,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child with autism spectrum disorder participating in a physical therapy program?","options": [{"key": "A","text": "Avoiding any physical therapy involvement for children with autism spectrum disorder"},{"key": "B","text": "Ignoring any sensory sensitivities during exercise session planning"},{"key": "C","text": "Assuming standard adult-style instruction is equally effective regardless of the child's needs"},{"key": "D","text": "Adapting communication style, using consistent routines, and considering sensory preferences/sensitivities to optimize engagement"}],"correct": "D","explanation": "Effective pediatric physiotherapy for children with autism spectrum disorder often requires individualized communication and sensory considerations to support successful engagement and therapeutic outcomes."},{"id": 4838,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following best describes 'central sensitization' as it relates to chronic pain and exercise therapy planning?","options": [{"key": "A","text": "A condition affecting only peripheral tissue, unrelated to nervous system processing"},{"key": "B","text": "A term with no clinical relevance to exercise therapy for chronic pain patients"},{"key": "C","text": "An increased responsiveness of the central nervous system to sensory input, potentially amplifying pain perception beyond what tissue pathology alone would suggest"},{"key": "D","text": "A condition indicating exercise therapy should never be attempted"}],"correct": "C","explanation": "Central sensitization reflects nervous system-level changes amplifying pain sensitivity, an important concept for understanding and appropriately managing chronic pain conditions through carefully graded exercise approaches."},{"id": 4839,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy approach for a patient with chronic pain and evidence of central sensitization?","options": [{"key": "A","text": "A graded, education-informed approach addressing both physical function and pain-related beliefs, often progressing more gradually than typical acute injury rehabilitation"},{"key": "B","text": "Complete avoidance of any exercise or movement"},{"key": "C","text": "Ignoring any educational component and focusing exclusively on physical exercise prescription"},{"key": "D","text": "Aggressive rapid progression identical to standard acute injury protocols"}],"correct": "A","explanation": "Managing central sensitization-related chronic pain typically requires a combined approach of pain education and carefully graded exercise progression, differing from more straightforward acute injury rehabilitation approaches."},{"id": 4840,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'pain neuroscience education' as sometimes incorporated into exercise therapy for chronic pain?","options": [{"key": "A","text": "Providing no explanation of pain mechanisms, focusing purely on physical exercise"},{"key": "B","text": "An approach only relevant to acute injuries, not chronic pain"},{"key": "C","text": "A technique proven to have no impact on patient outcomes"},{"key": "D","text": "Providing patients with an understanding of pain mechanisms to help reduce fear, catastrophizing, and support engagement with therapeutic exercise"}],"correct": "D","explanation": "Pain neuroscience education helps patients understand that pain does not always directly correlate with tissue damage, which can reduce fear-avoidance behaviors and support more effective engagement with exercise therapy."},{"id": 4841,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate approach when a patient reports increased pain during a new exercise, without any signs of significant tissue damage or red flags?","options": [{"key": "A","text": "Providing reassurance about the difference between pain and harm, potentially modifying but not necessarily discontinuing the exercise entirely"},{"key": "B","text": "Immediately stopping all exercise therapy permanently"},{"key": "C","text": "Assuming any reported pain always indicates the exercise must be causing tissue damage"},{"key": "D","text": "Ignoring the patient's reported pain entirely without any response"}],"correct": "A","explanation": "In the absence of red flags, appropriately addressing reported pain with reassurance and thoughtful modification (rather than complete cessation) supports continued therapeutic progress while validating the patient's experience."},{"id": 4842,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'catastrophizing' as it relates to pain and potential impact on exercise therapy engagement?","options": [{"key": "A","text": "A term only relevant to psychiatric diagnosis, not physiotherapy practice"},{"key": "B","text": "A concept with no relationship to rehabilitation outcomes"},{"key": "C","text": "An exaggerated negative cognitive/emotional response to actual or anticipated pain, which may be associated with poorer rehabilitation outcomes"},{"key": "D","text": "A normal, universally beneficial response to any pain experience"}],"correct": "C","explanation": "Pain catastrophizing (excessive negative anticipation/rumination about pain) has been associated with poorer outcomes in various musculoskeletal conditions, making it a relevant consideration in comprehensive exercise therapy planning."},{"id": 4843,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from COVID-19 with persistent fatigue and exertional symptoms (long COVID)?","options": [{"key": "A","text": "Ignoring any reported post-exertional symptom worsening"},{"key": "B","text": "Complete avoidance of any physical activity indefinitely"},{"key": "C","text": "Very gradual, carefully paced activity progression with close monitoring for post-exertional symptom exacerbation"},{"key": "D","text": "Immediate aggressive graded exercise therapy regardless of symptom response"}],"correct": "C","explanation": "Current understanding of long COVID emphasizes cautious, individualized pacing given the risk of post-exertional malaise in some patients, similar in principle to chronic fatigue syndrome management approaches."},{"id": 4844,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with post-COVID pulmonary fibrosis affecting exercise tolerance?","options": [{"key": "A","text": "Immediate high-intensity training regardless of respiratory limitation"},{"key": "B","text": "Gradual aerobic reconditioning with close monitoring of oxygen saturation and symptoms, similar in principle to other interstitial lung disease rehabilitation approaches"},{"key": "C","text": "Complete avoidance of any exercise due to pulmonary involvement"},{"key": "D","text": "Assuming no monitoring is needed during exercise sessions"}],"correct": "B","explanation": "Post-COVID pulmonary fibrosis rehabilitation follows similar principles to other interstitial lung disease management, emphasizing gradual reconditioning with appropriate respiratory monitoring."},{"id": 4845,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an athlete returning to sport following a concussion who has passed the graded return-to-play protocol?","options": [{"key": "A","text": "Immediate cessation of all future monitoring regardless of any new symptoms"},{"key": "B","text": "Ignoring any symptoms that occur after formal clearance"},{"key": "C","text": "Continued monitoring for any delayed symptom recurrence even after clearance, given individual variability in recovery"},{"key": "D","text": "Assuming complete recovery is guaranteed once cleared with no further monitoring needed"}],"correct": "C","explanation": "Even after successful completion of a graded return-to-play protocol, continued awareness of potential delayed symptom recurrence remains an important safety consideration in concussion management."},{"id": 4846,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for female athletes at higher risk of ACL injury based on movement pattern analysis?","options": [{"key": "A","text": "Assuming injury prevention programs provide no meaningful risk reduction"},{"key": "B","text": "Implementing neuromuscular training programs targeting landing mechanics, hip/knee control, and movement quality as injury prevention strategies"},{"key": "C","text": "Ignoring any movement pattern analysis findings in program design"},{"key": "D","text": "Only addressing injury after it occurs, with no preventive component"}],"correct": "B","explanation": "Evidence supports structured neuromuscular training programs targeting landing/movement mechanics as effective strategies for reducing ACL injury risk, particularly in higher-risk populations like female athletes in cutting/pivoting sports."},{"id": 4847,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an athlete with a history of recurrent ankle sprains?","options": [{"key": "A","text": "Complete avoidance of any further athletic participation"},{"key": "B","text": "Ignoring proprioceptive deficits that commonly persist after ankle sprain"},{"key": "C","text": "Assuming previous sprains have no bearing on future injury prevention planning"},{"key": "D","text": "Ongoing proprioceptive/balance training and potentially bracing/taping as part of a comprehensive injury prevention strategy"}],"correct": "D","explanation": "Given the well-documented risk of recurrent ankle sprain and associated chronic ankle instability, ongoing proprioceptive training and appropriate protective strategies are important components of long-term management."},{"id": 4848,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an athlete experiencing overtraining syndrome (persistent fatigue and performance decline despite continued training)?","options": [{"key": "A","text": "Ignoring the diagnosis and maintaining unmodified training volume"},{"key": "B","text": "Continuing to increase training intensity to 'push through' the symptoms"},{"key": "C","text": "A period of reduced training load/recovery, addressing the underlying training imbalance alongside gradual, monitored return to full training"},{"key": "D","text": "Complete permanent cessation of all athletic activity"}],"correct": "C","explanation": "Overtraining syndrome management requires addressing the underlying training load imbalance through appropriate recovery periods before gradually and carefully returning to full training volume."},{"id": 4849,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Active cycle of breathing technique (ACBT), used in chest physiotherapy, combines which components?","options": [{"key": "A","text": "A technique used exclusively for cardiac rehabilitation, not pulmonary conditions"},{"key": "B","text": "Only coughing exercises without any breathing control"},{"key": "C","text": "Only deep breathing without any expiratory component"},{"key": "D","text": "Breathing control, thoracic expansion exercises, and forced expiration technique (huffing)"}],"correct": "D","explanation": "ACBT is a structured cycle combining relaxed breathing, deep breaths for lung expansion, and controlled forced expiration (huffing) to mobilize and clear secretions."},{"id": 4850,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "The 'huffing' technique used within active cycle of breathing is designed to:","options": [{"key": "A","text": "Replace the need for any postural drainage positioning"},{"key": "B","text": "Only used for upper airway congestion, not lower airway secretions"},{"key": "C","text": "Help mobilize and clear airway secretions with less fatigue than repeated coughing"},{"key": "D","text": "Increase heart rate for cardiovascular conditioning"}],"correct": "C","explanation": "Huffing (forced expiration technique) uses an open glottis forced exhalation to move secretions toward larger airways for easier clearance, often less fatiguing than repeated forceful coughing."},{"id": 4851,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Postural drainage positions used in chest physiotherapy are designed to:","options": [{"key": "A","text": "Replace the need for any breathing exercises entirely"},{"key": "B","text": "Only provide comfort positioning with no drainage-related benefit"},{"key": "C","text": "Use gravity to help drain secretions from specific lung segments toward larger airways for clearance"},{"key": "D","text": "Increase secretion production rather than aid clearance"}],"correct": "C","explanation": "Postural drainage utilizes specific gravity-assisted positions corresponding to different lung segments to facilitate secretion movement toward the central airways for more effective clearance."},{"id": 4852,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Manual chest percussion, sometimes used alongside postural drainage, is intended to:","options": [{"key": "A","text": "Help loosen and mobilize retained secretions within the airways"},{"key": "B","text": "Only provide a relaxation effect with no secretion-related benefit"},{"key": "C","text": "Increase pain without any therapeutic purpose"},{"key": "D","text": "Replace the need for any postural positioning"}],"correct": "A","explanation": "Manual percussion applies rhythmic mechanical force to the chest wall, intended to help loosen adherent secretions to facilitate their movement and subsequent clearance."},{"id": 4853,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Positive expiratory pressure (PEP) devices used in airway clearance therapy work by:","options": [{"key": "A","text": "Requiring no patient effort or technique for effective use"},{"key": "B","text": "Providing resistance only during inhalation"},{"key": "C","text": "Creating resistance during exhalation to help maintain airway patency and mobilize secretions"},{"key": "D","text": "Having no effect on airway secretion clearance"}],"correct": "C","explanation": "PEP devices create expiratory resistance that helps stent open airways and mobilize secretions, an alternative or adjunct to traditional postural drainage/percussion techniques."},{"id": 4854,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Autogenic drainage, an airway clearance technique, primarily relies on:","options": [{"key": "A","text": "Positioning changes using gravity as the primary mechanism"},{"key": "B","text": "Manual percussion applied by a therapist"},{"key": "C","text": "Continuous positive airway pressure devices exclusively"},{"key": "D","text": "Controlled breathing at varying lung volumes to mobilize secretions from smaller to larger airways without external assistance"}],"correct": "D","explanation": "Autogenic drainage uses a specific sequence of controlled breathing at different lung volumes, allowing the patient to independently mobilize secretions progressively toward larger airways."},{"id": 4855,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with unilateral vestibular hypofunction regarding gaze stabilization exercise progression?","options": [{"key": "A","text": "Keeping exercise difficulty completely static without any progression"},{"key": "B","text": "Progressing exercise difficulty by increasing head movement speed and changing background visual complexity as tolerated"},{"key": "C","text": "Assuming vestibular exercises require no systematic progression approach"},{"key": "D","text": "Avoiding any exercise involving head movement indefinitely"}],"correct": "B","explanation": "Vestibular rehabilitation exercises are systematically progressed through increasing head movement speed, changing visual backgrounds, and altering positions to promote central vestibular compensation."},{"id": 4856,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for canalith repositioning treatment failure in a patient with suspected BPPV?","options": [{"key": "A","text": "Repeating the identical maneuver indefinitely without any reassessment"},{"key": "B","text": "Assuming all vertigo is BPPV regardless of maneuver response"},{"key": "C","text": "Reassessing for the correct affected canal or considering alternative diagnoses if standard repositioning maneuvers are unsuccessful"},{"key": "D","text": "Assuming the diagnosis must be incorrect and abandoning any further vestibular assessment"}],"correct": "C","explanation": "When standard repositioning maneuvers fail, reassessment for the specific affected canal or consideration of alternative underlying causes of vertigo is an appropriate clinical reasoning approach."},{"id": 4857,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with cervicogenic dizziness (dizziness related to cervical spine dysfunction)?","options": [{"key": "A","text": "Assuming cervical spine has no relationship to balance/dizziness symptoms"},{"key": "B","text": "Only addressing vestibular rehabilitation without any cervical spine consideration"},{"key": "C","text": "Complete avoidance of any cervical spine-related exercise"},{"key": "D","text": "Addressing cervical spine mobility/strength alongside balance training, given the contribution of cervical proprioceptive input to postural control"}],"correct": "D","explanation": "Cervicogenic dizziness recognizes the cervical spine's role in providing proprioceptive input relevant to postural control, making combined cervical and balance-focused exercise approaches appropriate."},{"id": 4858,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with hemiplegic shoulder pain following stroke?","options": [{"key": "A","text": "Aggressive overhead stretching regardless of pain or subluxation status"},{"key": "B","text": "Ignoring any shoulder subluxation or positioning considerations"},{"key": "C","text": "Careful, pain-free range of motion and appropriate positioning/handling to protect the shoulder joint while addressing any underlying subluxation or soft tissue impairment"},{"key": "D","text": "Complete immobilization of the affected shoulder indefinitely"}],"correct": "C","explanation": "Hemiplegic shoulder pain management requires careful attention to positioning, gentle pain-free mobility, and addressing contributing factors like subluxation to prevent further injury while supporting functional recovery."},{"id": 4859,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for shoulder subluxation following stroke?","options": [{"key": "A","text": "Immediate aggressive resistance training of the shoulder regardless of subluxation status"},{"key": "B","text": "Complete avoidance of any exercise or positioning intervention"},{"key": "C","text": "Appropriate positioning support (e.g., slings, arm troughs during sitting) combined with muscle re-education exercises targeting the shoulder stabilizers"},{"key": "D","text": "Assuming subluxation has no relevance to exercise program design"}],"correct": "C","explanation": "Managing post-stroke shoulder subluxation typically combines supportive positioning strategies with targeted exercise to re-educate and strengthen the shoulder stabilizing musculature."},{"id": 4860,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with post-stroke pusher syndrome (lateropulsion)?","options": [{"key": "A","text": "Assuming pusher syndrome requires no distinct treatment approach from standard hemiparesis"},{"key": "B","text": "Complete avoidance of any balance/postural retraining"},{"key": "C","text": "Specific visual feedback and postural retraining techniques addressing the patient's altered perception of vertical/body position"},{"key": "D","text": "Standard balance training without any specific modification for this presentation"}],"correct": "C","explanation": "Pusher syndrome requires specialized treatment approaches using visual feedback and specific postural retraining techniques to address the patient's altered internal perception of postural vertical."},{"id": 4861,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration following lumbar microdiscectomy surgery?","options": [{"key": "A","text": "Early gentle mobilization avoiding excessive spinal flexion/twisting initially, with gradual progression to core stabilization exercise as healing allows"},{"key": "B","text": "Immediate return to heavy lifting and unrestricted activity on the first postoperative day"},{"key": "C","text": "Complete bed rest for several months following surgery"},{"key": "D","text": "Aggressive spinal flexion exercises immediately after surgery"}],"correct": "A","explanation": "Post-discectomy rehabilitation typically begins with gentle, protected mobilization before progressing to core stabilization exercises as the surgical site heals appropriately."},{"id": 4862,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration following elbow arthroscopy for loose body removal?","options": [{"key": "A","text": "Ignoring range of motion considerations during early rehabilitation"},{"key": "B","text": "Immediate aggressive resistance training regardless of postoperative swelling"},{"key": "C","text": "Complete immobilization of the elbow for an extended period"},{"key": "D","text": "Early range of motion exercises to prevent stiffness, progressing to strengthening as pain and swelling allow"}],"correct": "D","explanation": "Elbow arthroscopy rehabilitation typically prioritizes early range of motion to prevent the joint stiffness this joint is particularly prone to, before progressing to strengthening exercises."},{"id": 4863,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration following ankle arthroscopy?","options": [{"key": "A","text": "Complete non-weight-bearing indefinitely regardless of the specific procedure performed"},{"key": "B","text": "Assuming standard protocols apply without considering the specific arthroscopic findings/procedure"},{"key": "C","text": "Progressive weight-bearing and range of motion exercises per surgeon protocol, addressing any identified impingement or instability findings"},{"key": "D","text": "Immediate unrestricted full weight-bearing and running regardless of surgical findings"}],"correct": "C","explanation": "Post-ankle arthroscopy rehabilitation is guided by the specific surgical findings and procedure performed, following a progressive weight-bearing and range of motion protocol as directed by the surgical team."},{"id": 4864,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration following a first-time anterior shoulder dislocation managed conservatively (non-surgically)?","options": [{"key": "A","text": "Assuming strengthening exercise has no role in reducing recurrent dislocation risk"},{"key": "B","text": "Complete avoidance of any shoulder exercise indefinitely"},{"key": "C","text": "Progressive strengthening of the rotator cuff and periscapular muscles once acute symptoms allow, to enhance dynamic joint stability"},{"key": "D","text": "Immediate return to full overhead athletic activity regardless of stability status"}],"correct": "C","explanation": "Conservative management of shoulder dislocation emphasizes progressive strengthening of dynamic stabilizers to help compensate for the compromised static (capsular/labral) restraints and reduce recurrence risk."},{"id": 4865,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration following spinal cord decompression surgery for cervical myelopathy?","options": [{"key": "A","text": "Immediate aggressive cervical range of motion exercises regardless of surgical precautions"},{"key": "B","text": "Assuming standard cervical spine protocols apply without considering the underlying myelopathy"},{"key": "C","text": "Complete avoidance of any physiotherapy involvement following this surgery"},{"key": "D","text": "Careful, graded mobilization addressing any pre-existing neurological deficits, with attention to overall functional recovery goals"}],"correct": "D","explanation": "Rehabilitation following cervical decompression surgery requires careful, individualized progression addressing both surgical precautions and any pre-existing neurological deficits from the underlying myelopathy."},{"id": 4866,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration following a fasciotomy for compartment syndrome?","options": [{"key": "A","text": "Immediate full activity without any consideration for wound healing"},{"key": "B","text": "Gradual wound healing-appropriate mobilization and progressive strengthening once the surgical site permits, addressing any residual muscle/nerve involvement"},{"key": "C","text": "Ignoring any residual neurological deficits that may have resulted from the compartment syndrome"},{"key": "D","text": "Complete immobilization indefinitely regardless of healing progress"}],"correct": "B","explanation": "Post-fasciotomy rehabilitation must balance appropriate wound healing considerations with progressive mobilization, while also addressing any residual muscle or nerve dysfunction resulting from the original compartment syndrome."},{"id": 4867,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'repetition maximum' (RM) as used in resistance exercise prescription?","options": [{"key": "A","text": "A fixed percentage of body weight used for all patients"},{"key": "B","text": "The total number of repetitions performed regardless of weight used"},{"key": "C","text": "A measure only relevant to isometric exercise"},{"key": "D","text": "The maximum amount of weight that can be lifted for a specified number of repetitions with proper form"}],"correct": "D","explanation": "Repetition maximum (e.g., 1RM, 10RM) quantifies the heaviest load that can be lifted for a given number of repetitions, commonly used to guide resistance training intensity prescription."},{"id": 4868,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Which of the following describes an appropriate approach to determining a working resistance training load without performing a true maximal 1RM test in a rehabilitation setting (where maximal testing may be inappropriate)?","options": [{"key": "A","text": "Always requiring a true 1RM test regardless of the patient's condition or safety considerations"},{"key": "B","text": "Using a completely arbitrary load with no systematic estimation method"},{"key": "C","text": "Using a submaximal repetition testing approach (e.g., estimating from a comfortable multi-repetition set) to estimate an appropriate working load"},{"key": "D","text": "Assuming resistance load cannot be estimated without maximal testing"}],"correct": "C","explanation": "Submaximal testing approaches allow estimation of appropriate working loads without the potential risks associated with true maximal lifts, particularly relevant in early or higher-risk rehabilitation populations."},{"id": 4869,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration regarding exercise volume (sets x repetitions x load) when designing a strengthening program?","options": [{"key": "A","text": "Balancing sufficient volume to stimulate adaptation against the risk of excessive fatigue or overtraining, particularly important in rehabilitation populations"},{"key": "B","text": "Volume should remain completely fixed throughout an entire rehabilitation program"},{"key": "C","text": "Always maximizing volume regardless of patient tolerance or recovery capacity"},{"key": "D","text": "Volume has no meaningful relationship to training adaptation"}],"correct": "A","explanation": "Appropriate volume prescription balances the stimulus needed for adaptation with the patient's capacity to recover, an important consideration distinct from simply maximizing training volume."},{"id": 4870,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes the concept of 'rest interval' in resistance training prescription and its general relationship to training goals?","options": [{"key": "A","text": "Rest intervals should always be identical regardless of the training goal"},{"key": "B","text": "Longer rest intervals are always used for endurance training goals"},{"key": "C","text": "Rest interval length has no relationship to training goals"},{"key": "D","text": "Shorter rest intervals are often used for muscular endurance goals, while longer rest intervals typically support maximal strength/power development"}],"correct": "D","explanation": "Rest interval duration is typically manipulated based on training goals, with shorter rests supporting endurance-focused adaptations and longer rests allowing more complete recovery for strength/power-focused training."},{"id": 4871,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes the general concept of 'training frequency' in exercise prescription?","options": [{"key": "A","text": "The specific type of exercise equipment used"},{"key": "B","text": "The number of training sessions performed per week (or specified time period) targeting a particular goal or muscle group"},{"key": "C","text": "The total duration of a single training session"},{"key": "D","text": "A concept only relevant to cardiovascular training, not resistance training"}],"correct": "B","explanation": "Training frequency refers to how often exercise sessions occur, an important prescription variable alongside intensity, volume, and type when designing a comprehensive exercise program."},{"id": 4872,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate consideration regarding allowing adequate recovery time between resistance training sessions targeting the same muscle group?","options": [{"key": "A","text": "Recovery time considerations only apply to elite athletes, not rehabilitation patients"},{"key": "B","text": "No recovery time is needed between sessions targeting the same muscle group"},{"key": "C","text": "Sufficient recovery (often 48 hours) helps allow tissue repair/adaptation and reduces injury/overtraining risk"},{"key": "D","text": "Recovery time should always be minimized to maximize training frequency"}],"correct": "C","explanation": "Allowing appropriate recovery between sessions targeting the same muscle groups supports tissue adaptation and reduces the risk of overtraining or injury, an important consideration in program design."},{"id": 4873,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration when fitting a standard cane for a patient?","options": [{"key": "A","text": "The cane should always be as tall as the patient's shoulder"},{"key": "B","text": "The cane should be fitted without any regard to the patient's arm length"},{"key": "C","text": "Cane height has no bearing on proper use or safety"},{"key": "D","text": "The cane handle should be positioned at approximately the level of the patient's wrist crease when standing with arms relaxed at the sides"}],"correct": "D","explanation": "Proper cane height (typically wrist crease level) ensures approximately 20-30 degrees of elbow flexion during use, supporting efficient and safe weight-bearing assistance."},{"id": 4874,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration when fitting axillary crutches for a patient?","options": [{"key": "A","text": "Ensuring approximately two finger-widths of space between the axilla and the crutch top to avoid excessive pressure on the brachial plexus/axillary structures"},{"key": "B","text": "Crutch height has no relevance to potential nerve compression risk"},{"key": "C","text": "Ensuring the crutch top presses tightly against the axilla to maximize stability"},{"key": "D","text": "Allowing the crutch top to rest firmly against the axilla for maximum support"}],"correct": "A","explanation": "Proper crutch fitting avoids excessive pressure in the axilla, which could compress the brachial plexus/axillary vessels, instead directing weight-bearing through the hands on the grips."},{"id": 4875,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate progression consideration when transitioning a patient from a standard walker to a single-point cane?","options": [{"key": "A","text": "Ensuring adequate improvement in strength, balance, and confidence before reducing the level of external support provided"},{"key": "B","text": "Making this transition immediately regardless of the patient's current functional status"},{"key": "C","text": "Skipping any intermediate assessment of readiness for device transition"},{"key": "D","text": "Assuming device progression should never be based on functional assessment"}],"correct": "A","explanation": "Progressing to less supportive assistive devices should be based on demonstrated functional improvement in strength and balance, ensuring continued safety during the transition."},{"id": 4876,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for teaching stair ascent/descent with a single cane for a patient with unilateral lower extremity weakness?","options": [{"key": "A","text": "Ascending and descending stairs with no specific limb sequence consideration"},{"key": "B","text": "Using the weaker limb to lead ascent regardless of strength considerations"},{"key": "C","text": "Using the mnemonic 'up with the good, down with the bad' regarding which limb leads on stairs, with the cane typically used with the affected side sequence"},{"key": "D","text": "Assuming stair navigation requires no specific instructional strategy"}],"correct": "C","explanation": "This common teaching mnemonic helps patients remember the appropriate limb sequencing for safe stair navigation, leading with the stronger limb going up and the weaker/affected limb going down first."},{"id": 4877,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for teaching a patient to use a rolling walker safely on an incline or ramp?","options": [{"key": "A","text": "Avoiding practice on any inclines during gait training regardless of the patient's environmental needs"},{"key": "B","text": "Ignoring the increased fall risk associated with ramp navigation"},{"key": "C","text": "Assuming ramp/incline navigation requires no specific instruction beyond flat-ground walker use"},{"key": "D","text": "Providing instruction on appropriate weight-bearing distribution and control techniques specific to the increased challenge of inclines"}],"correct": "D","explanation": "Given the increased balance and control demands of ramp/incline navigation, specific instruction addressing this challenge is an important component of comprehensive functional gait training with assistive devices."},{"id": 4878,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a recently placed coronary stent (percutaneous coronary intervention)?","options": [{"key": "A","text": "Requiring identical sternal precautions to open-heart surgery patients"},{"key": "B","text": "Following standard phase-based cardiac rehabilitation progression, typically with an earlier resumption of activity compared to open-heart surgery given the less invasive nature of the procedure"},{"key": "C","text": "Complete avoidance of any exercise for several months following stent placement"},{"key": "D","text": "Immediate return to maximal exertion without any structured cardiac rehabilitation involvement"}],"correct": "B","explanation": "Patients following PCI/stent placement generally progress through structured cardiac rehabilitation, often with a somewhat faster initial activity progression compared to those recovering from open-heart surgery, given the less invasive nature of the procedure."},{"id": 4879,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with peripheral edema related to chronic venous insufficiency?","options": [{"key": "A","text": "Ignoring the edema entirely during exercise program design"},{"key": "B","text": "Encouraging prolonged standing without any positional variation"},{"key": "C","text": "Incorporating ankle pump exercises and appropriate limb elevation alongside compression therapy to support venous return"},{"key": "D","text": "Avoiding any lower limb exercise due to the edema"}],"correct": "C","explanation": "Ankle pump exercises activate the calf muscle pump mechanism, supporting venous return, and are commonly incorporated alongside compression and elevation strategies for managing chronic venous insufficiency-related edema."},{"id": 4880,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from deep vein thrombosis who has been cleared for mobilization by their medical team?","options": [{"key": "A","text": "Assuming physiotherapy has no role once DVT has been diagnosed"},{"key": "B","text": "Immediate return to high-intensity exercise without any medical clearance consideration"},{"key": "C","text": "Complete strict bed rest indefinitely regardless of medical clearance"},{"key": "D","text": "Gradual, medically cleared mobilization and appropriate exercise progression, often alongside continued anticoagulation as prescribed"}],"correct": "D","explanation": "Once medically cleared and appropriately anticoagulated, gradual mobilization and exercise progression is generally supported for DVT patients, differing from older practices of prolonged strict bed rest."},{"id": 4881,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with lymphedema regarding compression garment use during exercise sessions?","options": [{"key": "A","text": "Compression garments should only be worn while resting, never during activity"},{"key": "B","text": "Always removing compression garments during any physical activity"},{"key": "C","text": "Generally continuing to wear prescribed compression garments during exercise unless specifically advised otherwise by the treating team"},{"key": "D","text": "Assuming compression garment use has no relevance to exercise therapy sessions"}],"correct": "C","explanation": "Compression garments are typically continued during exercise for lymphedema management unless specific contraindications exist, supporting continued lymphatic drainage during activity."},{"id": 4882,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with critical limb ischemia (severe peripheral arterial disease) regarding exercise prescription?","options": [{"key": "A","text": "Assuming exercise therapy has no role once critical limb ischemia is diagnosed"},{"key": "B","text": "Requiring careful medical evaluation and often more conservative exercise approaches compared to less severe claudication, given the higher risk of tissue compromise"},{"key": "C","text": "Complete avoidance of any medical evaluation prior to exercise prescription"},{"key": "D","text": "Standard claudication exercise protocols apply identically regardless of ischemia severity"}],"correct": "B","explanation": "Critical limb ischemia represents a more severe presentation requiring careful medical evaluation, as standard claudication exercise protocols may not be appropriate given the higher risk of tissue compromise in this population."},{"id": 4883,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate use of a force plate/posturography system in balance assessment?","options": [{"key": "A","text": "A tool used exclusively for cardiovascular assessment"},{"key": "B","text": "Providing objective, quantifiable data on postural sway and balance strategies under various sensory conditions"},{"key": "C","text": "Only providing subjective clinical impressions without any objective data"},{"key": "D","text": "A device with no practical application in balance rehabilitation planning"}],"correct": "B","explanation": "Force plate posturography provides objective, quantifiable measurement of postural control strategies, useful for detailed balance assessment and monitoring progress in complex cases."},{"id": 4884,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate use of a treadmill with visual perturbation/virtual reality feedback in balance rehabilitation?","options": [{"key": "A","text": "A technology with no evidence-based application to balance training"},{"key": "B","text": "Only usable for cardiovascular conditioning without any balance-specific application"},{"key": "C","text": "Requiring no safety harness or support system regardless of patient fall risk"},{"key": "D","text": "Providing controlled, progressive visual-motor challenges to retrain balance responses in a safe, supported environment"}],"correct": "D","explanation": "Virtual reality/perturbation-based treadmill training allows controlled, progressive challenge to balance systems in a safe, supported environment, an emerging tool in comprehensive balance rehabilitation."},{"id": 4885,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient using a suspended harness system during balance/gait training?","options": [{"key": "A","text": "Providing a safety net allowing more challenging balance activities to be practiced with reduced fall risk"},{"key": "B","text": "Providing no meaningful safety benefit during challenging exercise"},{"key": "C","text": "Replacing the need for any therapist supervision during sessions"},{"key": "D","text": "Only usable for patients with no balance impairment"}],"correct": "A","explanation": "Harness support systems allow patients to safely practice more challenging balance and gait activities that might otherwise carry excessive fall risk without such support, expanding the range of appropriate exercise challenges."},{"id": 4886,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for optokinetic stimulation (moving visual field) sometimes used in vestibular rehabilitation?","options": [{"key": "A","text": "Avoiding any visual stimulation during vestibular rehabilitation"},{"key": "B","text": "Assuming visual stimuli have no relevance to vestibular symptom management"},{"key": "C","text": "Providing maximal visual stimulation intensity immediately without any graded approach"},{"key": "D","text": "Gradually habituating the patient to visually-induced dizziness/motion sensitivity through controlled, progressive exposure"}],"correct": "D","explanation": "Optokinetic stimulation techniques use controlled, progressive exposure to moving visual fields to help habituate patients to visually-provoked dizziness, complementing standard vestibular rehabilitation exercises."},{"id": 4887,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with fibrodysplasia ossificans progressiva regarding exercise/manual therapy?","options": [{"key": "A","text": "Assuming this rare condition has no bearing on exercise therapy approach"},{"key": "B","text": "Extreme caution avoiding any trauma, forceful stretching, or intramuscular injections that could trigger heterotopic ossification flare-ups"},{"key": "C","text": "Standard aggressive stretching and strengthening protocols apply without modification"},{"key": "D","text": "Encouraging maximal resistance training regardless of the diagnosis"}],"correct": "B","explanation": "FOP is a rare, severe genetic condition where minor trauma can trigger progressive heterotopic bone formation; extreme caution avoiding any tissue trauma including forceful exercise/manual therapy is essential."},{"id": 4888,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with osteogenesis imperfecta regarding exercise prescription?","options": [{"key": "A","text": "Low-impact, carefully controlled exercise avoiding excessive force/impact given the significantly increased fracture risk"},{"key": "B","text": "Standard high-impact exercise protocols without any modification"},{"key": "C","text": "Complete avoidance of any physical activity indefinitely"},{"key": "D","text": "Assuming fracture risk has no bearing on appropriate exercise selection"}],"correct": "A","explanation": "Given the significantly increased fracture risk in osteogenesis imperfecta, exercise programs require careful selection of low-impact activities with appropriate force/loading precautions."},{"id": 4889,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with Marfan syndrome regarding exercise intensity and type?","options": [{"key": "A","text": "Complete avoidance of any physical activity indefinitely"},{"key": "B","text": "Assuming cardiovascular considerations have no bearing on exercise prescription in this population"},{"key": "C","text": "Encouraging maximal isometric strength training regardless of cardiovascular risk"},{"key": "D","text": "Avoiding high-intensity isometric exercise and contact sports due to increased cardiovascular (aortic) risk, favoring moderate aerobic activity"}],"correct": "D","explanation": "Given the increased aortic dilation/dissection risk in Marfan syndrome, exercise recommendations typically avoid high-intensity isometric activities and contact sports, favoring moderate aerobic exercise with appropriate medical guidance."},{"id": 4890,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with Ehlers-Danlos syndrome experiencing frequent joint subluxations during functional activities?","options": [{"key": "A","text": "Assuming joint protection strategies are irrelevant to this population"},{"key": "B","text": "Encouraging maximal end-range stretching regardless of subluxation frequency"},{"key": "C","text": "Emphasizing proprioceptive training, joint protection strategies, and controlled strengthening within safe ranges"},{"key": "D","text": "Complete avoidance of any physical activity or exercise"}],"correct": "C","explanation": "Given the joint instability inherent to EDS, exercise approaches emphasize proprioceptive control and joint protection alongside careful strengthening, rather than further increasing already-excessive joint mobility."},{"id": 4891,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with mitochondrial myopathy experiencing significant exercise intolerance?","options": [{"key": "A","text": "Very gradual, individualized aerobic conditioning with close monitoring, given the impaired cellular energy metabolism underlying this condition"},{"key": "B","text": "Assuming standard exercise prescription applies without modification for this population"},{"key": "C","text": "Complete avoidance of any exercise indefinitely"},{"key": "D","text": "Aggressive high-intensity training regardless of the underlying metabolic limitation"}],"correct": "A","explanation": "Mitochondrial myopathies impair cellular energy production, necessitating a very gradual, carefully monitored approach to exercise conditioning that respects the underlying metabolic limitations."},{"id": 4892,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate motivational interviewing technique that a physiotherapist might use to support behavior change around exercise adherence?","options": [{"key": "A","text": "Using open-ended questions and reflective listening to help the patient explore their own motivation for change"},{"key": "B","text": "Assuming motivational techniques have no role in physiotherapy practice"},{"key": "C","text": "Only using closed yes/no questions throughout the conversation"},{"key": "D","text": "Providing directive commands without exploring the patient's own perspective"}],"correct": "A","explanation": "Motivational interviewing techniques, including open-ended questions and reflective listening, help patients explore and strengthen their own motivation for exercise behavior change, rather than relying solely on directive instruction."},{"id": 4893,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate strategy for improving long-term exercise adherence following formal physiotherapy discharge?","options": [{"key": "A","text": "Assuming adherence naturally continues without any specific planning or support"},{"key": "B","text": "Ignoring potential barriers the patient may face in continuing exercise independently"},{"key": "C","text": "Providing only verbal instructions with no written or visual reference materials"},{"key": "D","text": "Providing clear, written home exercise instructions along with strategies for self-monitoring and addressing potential barriers to continued adherence"}],"correct": "D","explanation": "Supporting long-term adherence after discharge often requires clear instructional materials combined with proactive planning for self-monitoring and addressing anticipated barriers to continued independent exercise."},{"id": 4894,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate approach when a patient expresses significant apprehension about starting a new exercise program due to fear of pain?","options": [{"key": "A","text": "Validating the patient's concern while providing clear education and starting with an appropriately graded, achievable level of challenge"},{"key": "B","text": "Immediately abandoning the exercise program due to the expressed apprehension"},{"key": "C","text": "Forcing the patient to perform maximally challenging exercises despite their expressed fear"},{"key": "D","text": "Dismissing the patient's concerns entirely without addressing them"}],"correct": "A","explanation": "Acknowledging patient concerns while providing appropriate education and a graded, achievable starting point helps build confidence and supports successful engagement with the exercise program."},{"id": 4895,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration when using technology (e.g., mobile apps, wearable devices) to support a patient's home exercise program?","options": [{"key": "A","text": "Selecting technology appropriate to the patient's comfort level and access, while ensuring it supports rather than complicates program adherence"},{"key": "B","text": "Assuming all patients have equal access to and comfort with technology-based exercise support"},{"key": "C","text": "Ignoring individual patient differences in technology comfort/access"},{"key": "D","text": "Requiring technology use regardless of patient preference or access limitations"}],"correct": "A","explanation": "Technology-based exercise support tools can enhance adherence and monitoring for appropriate patients, but should be selected thoughtfully considering individual access, comfort, and preference rather than universally mandated."},{"id": 4896,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with degenerative disc disease presenting with flexion-intolerant symptoms?","options": [{"key": "A","text": "Assuming directional preference has no relevance to exercise selection"},{"key": "B","text": "Complete avoidance of any spinal exercise"},{"key": "C","text": "Encouraging maximal repeated flexion exercises regardless of symptom response"},{"key": "D","text": "Emphasizing extension-based exercises and avoiding prolonged/repeated flexion positions that provoke symptoms"}],"correct": "D","explanation": "Identifying a patient's directional preference (in this case avoiding flexion, favoring extension) helps guide appropriate exercise selection to reduce symptom provocation while promoting functional improvement."},{"id": 4897,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with lumbar spinal stenosis presenting with extension-intolerant symptoms (worse with standing/walking, better with sitting/flexion)?","options": [{"key": "A","text": "Assuming positional preference has no relevance to this condition's management"},{"key": "B","text": "Complete avoidance of any exercise or postural modification"},{"key": "C","text": "Encouraging maximal spinal extension exercises regardless of symptom response"},{"key": "D","text": "Emphasizing flexion-biased exercises and postures that reduce neurogenic claudication symptoms"}],"correct": "D","explanation": "Patients with lumbar stenosis typically show a flexion preference (reducing canal narrowing), making flexion-biased exercises and postural strategies appropriate for symptom management."},{"id": 4898,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the McKenzie concept of 'centralization' as it relates to exercise assessment for spinal pain?","options": [{"key": "A","text": "Progressive movement of peripheral/radiating symptoms toward the spine's midline with repeated movement testing, generally indicating a favorable prognosis"},{"key": "B","text": "Peripheral symptoms spreading further away from the spine with movement"},{"key": "C","text": "A concept only relevant to cervical spine assessment, not lumbar"},{"key": "D","text": "A phenomenon with no prognostic significance"}],"correct": "A","explanation": "Centralization, where symptoms retreat toward the spine's center with repeated directional movement testing, is a favorable prognostic sign guiding McKenzie-based treatment approach selection."},{"id": 4899,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient demonstrating 'peripheralization' of symptoms during repeated movement testing?","options": [{"key": "A","text": "This finding always indicates a need for immediate surgical referral"},{"key": "B","text": "Peripheralization has no clinical significance for guiding treatment direction"},{"key": "C","text": "This finding generally suggests the tested direction should be avoided, as it is worsening rather than centralizing the patient's symptoms"},{"key": "D","text": "This finding indicates the tested direction should be repeated more aggressively"}],"correct": "C","explanation": "Peripheralization (symptoms spreading further from the spine) during directional testing suggests that movement direction is aggravating the condition and should generally be avoided in the treatment approach."},{"id": 4900,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with forward head posture contributing to upper back and neck discomfort?","options": [{"key": "A","text": "Only addressing the cervical spine without any consideration of scapular/upper back musculature"},{"key": "B","text": "Complete avoidance of any postural-related exercise intervention"},{"key": "C","text": "Postural correction exercises combined with deep neck flexor and scapular retractor strengthening"},{"key": "D","text": "Assuming forward head posture has no relationship to reported symptoms"}],"correct": "C","explanation": "Forward head posture is often addressed through a combined approach targeting deep neck flexor strength, scapular retractor strengthening, and general postural awareness training."},{"id": 4901,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a significant thoracic kyphosis affecting respiratory function and posture?","options": [{"key": "A","text": "Thoracic extension mobility exercises combined with postural strengthening to help optimize both posture and respiratory mechanics"},{"key": "B","text": "Complete avoidance of any thoracic spine exercise"},{"key": "C","text": "Assuming kyphosis has no relationship to respiratory mechanics"},{"key": "D","text": "Only addressing respiratory function without any postural component"}],"correct": "A","explanation": "Excessive thoracic kyphosis can compromise respiratory mechanics; addressing thoracic mobility and postural strength can help optimize both spinal alignment and breathing efficiency."},{"id": 4902,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with trigger finger following corticosteroid injection or splinting as initial management?","options": [{"key": "A","text": "Aggressive resistance training immediately regardless of the acute presentation"},{"key": "B","text": "Gentle tendon gliding exercises to maintain mobility while avoiding aggressive forceful movement that could exacerbate irritation"},{"key": "C","text": "Complete immobilization of the entire hand indefinitely"},{"key": "D","text": "Ignoring any exercise-based component of conservative trigger finger management"}],"correct": "B","explanation": "Conservative trigger finger management often incorporates gentle tendon gliding exercises to maintain mobility while avoiding aggravating forceful movements during the healing process."},{"id": 4903,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration following flexor tendon repair surgery in the hand?","options": [{"key": "A","text": "Ignoring the risk of tendon adhesion formation during the recovery process"},{"key": "B","text": "Complete immobilization with absolutely no movement for several months"},{"key": "C","text": "Following a carefully protocol-driven rehabilitation approach (e.g., controlled passive motion protocols) to protect the repair while preventing adhesion formation"},{"key": "D","text": "Immediate aggressive active resistance regardless of the tendon repair's healing stage"}],"correct": "C","explanation": "Flexor tendon repair rehabilitation follows carefully structured protocols balancing protection of the healing repair with early controlled motion to minimize adhesion formation, a critical balance in hand therapy."},{"id": 4904,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with complex regional pain syndrome affecting the hand following a distal radius fracture?","options": [{"key": "A","text": "Graded motor imagery and desensitization techniques combined with gentle functional movement, given the heightened pain sensitivity characteristic of this condition"},{"key": "B","text": "Ignoring the unique pain processing changes characteristic of CRPS"},{"key": "C","text": "Aggressive forceful range of motion exercises regardless of pain response"},{"key": "D","text": "Complete immobilization of the affected hand indefinitely"}],"correct": "A","explanation": "CRPS management often incorporates specialized approaches like graded motor imagery alongside gentle desensitization and functional movement, recognizing the altered pain processing characteristic of this condition."},{"id": 4905,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for intrinsic hand muscle strengthening following a peripheral nerve injury affecting hand function?","options": [{"key": "A","text": "Assuming all hand muscles are equally affected regardless of the specific nerve involved"},{"key": "B","text": "Complete avoidance of any hand-specific exercise following nerve injury"},{"key": "C","text": "Generic hand strengthening without consideration of the specific nerve injury pattern"},{"key": "D","text": "Targeted exercises addressing the specific intrinsic muscles affected, guided by the pattern of nerve involvement (e.g., median, ulnar)"}],"correct": "D","explanation": "Hand rehabilitation following peripheral nerve injury requires targeted exercise addressing the specific muscles affected by the particular nerve injury pattern (e.g., ulnar-innervated intrinsics vs. median-innervated thenar muscles)."},{"id": 4906,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic ankle instability performing single-leg balance training?","options": [{"key": "A","text": "Progressing from stable to unstable surfaces while incorporating reactive/perturbation-based challenges as tolerance improves"},{"key": "B","text": "Assuming surface progression has no relevance to ankle instability rehabilitation"},{"key": "C","text": "Only performing exercises on a completely stable surface indefinitely"},{"key": "D","text": "Avoiding any single-leg activities regardless of the specific instability pattern"}],"correct": "A","explanation": "Progressive surface and perturbation challenges during single-leg balance training help retrain the proprioceptive deficits characteristic of chronic ankle instability."},{"id": 4907,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for hip abductor strengthening in a runner with iliotibial band syndrome?","options": [{"key": "A","text": "Complete avoidance of any strengthening exercise for this condition"},{"key": "B","text": "Only addressing local knee-area tissue without any proximal strength assessment"},{"key": "C","text": "Assuming hip strength has no relationship to ITB syndrome development"},{"key": "D","text": "Addressing hip abductor weakness, which is commonly implicated in altered running mechanics contributing to ITB syndrome"}],"correct": "D","explanation": "Hip abductor weakness is commonly implicated in the altered lower limb mechanics (increased hip adduction/internal rotation) contributing to ITB syndrome, making proximal strengthening an important treatment component."},{"id": 4908,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for shin splints (medial tibial stress syndrome) in a runner?","options": [{"key": "A","text": "Ignoring any training load or biomechanical contributing factors"},{"key": "B","text": "Complete avoidance of any strengthening exercise"},{"key": "C","text": "Immediate return to unmodified training volume regardless of symptoms"},{"key": "D","text": "Addressing training load modification alongside calf/tibialis posterior strengthening and appropriate footwear/surface considerations"}],"correct": "D","explanation": "MTSS management typically combines load modification with targeted strengthening of muscles supporting the tibia, along with addressing biomechanical/training factors that may have contributed to the condition."},{"id": 4909,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a swimmer with shoulder pain related to swimmer's shoulder (impingement)?","options": [{"key": "A","text": "Complete avoidance of any shoulder-related exercise"},{"key": "B","text": "Ignoring stroke technique considerations entirely"},{"key": "C","text": "Addressing scapular stability, rotator cuff strength, and stroke technique modification alongside appropriate training load management"},{"key": "D","text": "Immediate return to full training volume regardless of symptoms"}],"correct": "C","explanation": "Swimmer's shoulder management typically requires a comprehensive approach addressing scapular/rotator cuff function, stroke mechanics, and training load, given the repetitive overhead demands of swimming."},{"id": 4910,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a cyclist experiencing patellofemoral pain related to bike fit issues?","options": [{"key": "A","text": "Ignoring bike fit considerations and only addressing strengthening"},{"key": "B","text": "Assuming bike positioning has no relationship to patellofemoral symptoms"},{"key": "C","text": "Complete avoidance of any cycling-related exercise"},{"key": "D","text": "Addressing bike fit/positioning alongside quadriceps and hip strengthening exercises"}],"correct": "D","explanation": "Cyclist-related patellofemoral pain often benefits from addressing both bike fit/positioning factors and targeted strengthening, recognizing the biomechanical contribution of improper bike setup."},{"id": 4911,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a golfer with low back pain related to their swing mechanics?","options": [{"key": "A","text": "Addressing core stability, hip/thoracic rotation mobility, and swing mechanic modification as part of a comprehensive approach"},{"key": "B","text": "Ignoring any biomechanical contribution to the reported symptoms"},{"key": "C","text": "Only addressing pain without any consideration of swing mechanics"},{"key": "D","text": "Complete avoidance of golf-related activity indefinitely regardless of symptom improvement"}],"correct": "A","explanation": "Golf-related low back pain often relates to repetitive rotational loading; addressing core stability, mobility, and swing mechanics collectively supports both symptom resolution and injury prevention."},{"id": 4912,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a baseball pitcher recovering from an ulnar collateral ligament sprain treated conservatively?","options": [{"key": "A","text": "Assuming a structured throwing progression has no relevance to recovery"},{"key": "B","text": "Complete avoidance of any throwing-related activity indefinitely"},{"key": "C","text": "A structured, gradual interval throwing program alongside strengthening focused on the shoulder/elbow/scapular complex"},{"key": "D","text": "Immediate return to full-velocity pitching without any graded progression"}],"correct": "C","explanation": "UCL sprain rehabilitation typically follows a carefully graded interval throwing program combined with comprehensive upper extremity strengthening before full return to competitive pitching."},{"id": 4913,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a basketball player recovering from patellar tendinopathy (jumper's knee)?","options": [{"key": "A","text": "Progressive loading program, often incorporating both isometric and heavy slow resistance training, guided by symptom response"},{"key": "B","text": "Assuming loading progression has no relevance to tendinopathy management"},{"key": "C","text": "Complete rest without any structured loading program"},{"key": "D","text": "Immediate return to full jumping/landing activity regardless of symptoms"}],"correct": "A","explanation": "Patellar tendinopathy management follows evidence-based progressive loading principles similar to other tendinopathies, often incorporating isometric and heavy slow resistance approaches based on current research."},{"id": 4914,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a tennis player with lateral epicondylalgia related to their backhand technique?","options": [{"key": "A","text": "Addressing both the tendon loading rehabilitation and potential technique modification to reduce recurrence risk"},{"key": "B","text": "Ignoring any technique-related contributing factors"},{"key": "C","text": "Only addressing the tendon pathology without any consideration of technique"},{"key": "D","text": "Complete avoidance of any tennis-related activity indefinitely"}],"correct": "A","explanation": "Tennis-related lateral epicondylalgia often benefits from addressing both the local tendon pathology through progressive loading and any contributing technique factors to reduce future recurrence risk."},{"id": 4915,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a weightlifter with low back pain related to lifting technique?","options": [{"key": "A","text": "Assuming lifting technique has no relationship to reported symptoms"},{"key": "B","text": "Complete avoidance of any weightlifting-related activity indefinitely regardless of improvement"},{"key": "C","text": "Addressing lifting technique/form alongside core stability and appropriate load progression"},{"key": "D","text": "Ignoring any technique considerations and focusing only on passive treatment"}],"correct": "C","explanation": "Weightlifting-related back pain often benefits from addressing lifting mechanics/form alongside core stabilization training, recognizing the biomechanical contribution of technique to symptom development."},{"id": 4916,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a dancer with hip impingement-related symptoms during high-flexibility positions?","options": [{"key": "A","text": "Ignoring the specific movement demands of dance in favor of generic exercise prescription"},{"key": "B","text": "Assuming dance-specific movement demands have no relevance to exercise therapy planning"},{"key": "C","text": "Complete avoidance of any hip-related exercise or dance participation"},{"key": "D","text": "Addressing hip strength/control and movement pattern modification while considering the specific demands of the dance discipline"}],"correct": "D","explanation": "Dance-related hip impingement management should consider the specific extreme range-of-motion demands of the discipline, addressing strength/control within the context of these movement requirements."},{"id": 4917,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with progressive supranuclear palsy regarding fall risk?","options": [{"key": "A","text": "Complete avoidance of any balance training due to fall risk"},{"key": "B","text": "Very high fall risk requiring careful balance training with close supervision, given the characteristic backward falling tendency and impaired postural reflexes"},{"key": "C","text": "Assuming fall risk is not elevated in this condition compared to other parkinsonian syndromes"},{"key": "D","text": "Standard balance training without any specific modification for this condition"}],"correct": "B","explanation": "PSP is characterized by particularly high fall risk with a tendency toward backward falls due to impaired postural reflexes, requiring especially careful, closely supervised balance training approaches."},{"id": 4918,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with multiple system atrophy regarding autonomic dysfunction during exercise?","options": [{"key": "A","text": "Assuming autonomic dysfunction has no bearing on exercise therapy safety"},{"key": "B","text": "Careful monitoring for orthostatic hypotension and other autonomic symptoms during position changes and exercise"},{"key": "C","text": "Complete avoidance of any exercise due to this diagnosis"},{"key": "D","text": "Standard exercise prescription without any autonomic monitoring considerations"}],"correct": "B","explanation": "MSA involves significant autonomic dysfunction, including orthostatic hypotension, requiring careful monitoring during exercise and position changes to ensure safe participation."},{"id": 4919,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with corticobasal syndrome affecting one side of the body asymmetrically?","options": [{"key": "A","text": "Addressing the asymmetric motor and sensory impairments with individualized, side-specific exercise approaches"},{"key": "B","text": "Ignoring the characteristic asymmetric presentation when designing the exercise program"},{"key": "C","text": "Complete avoidance of any exercise due to the complexity of this condition"},{"key": "D","text": "Assuming symmetric exercise prescription applies despite the asymmetric presentation"}],"correct": "A","explanation": "Corticobasal syndrome's characteristic asymmetric presentation requires individualized exercise approaches addressing the specific pattern of motor and sensory impairment on the more affected side."},{"id": 4920,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with dystonia affecting functional movement?","options": [{"key": "A","text": "Ignoring any medical management that may be coordinated with the physiotherapy plan"},{"key": "B","text": "Assuming exercise therapy has no role in dystonia management"},{"key": "C","text": "Complete avoidance of any movement-based intervention"},{"key": "D","text": "Addressing the abnormal movement patterns through targeted exercise while considering any medical management (e.g., botulinum toxin) that may influence timing of certain interventions"}],"correct": "D","explanation": "Dystonia management often involves physiotherapy addressing functional movement patterns, potentially coordinated with medical interventions like botulinum toxin injections that may create a therapeutic window for more effective exercise."},{"id": 4921,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed baker's cyst affecting knee flexion?","options": [{"key": "A","text": "Addressing any underlying intra-articular pathology while incorporating gentle range of motion exercises within comfortable limits"},{"key": "B","text": "Aggressive forceful flexion exercises regardless of associated discomfort"},{"key": "C","text": "Assuming the cyst has no bearing on appropriate exercise selection"},{"key": "D","text": "Complete avoidance of any knee-related exercise"}],"correct": "A","explanation": "Baker's cyst is often secondary to underlying knee joint pathology; addressing the underlying condition alongside gentle mobility exercises within comfortable limits is a reasonable exercise therapy approach."},{"id": 4922,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed Morton's neuroma affecting the forefoot?","options": [{"key": "A","text": "Complete avoidance of any weight-bearing activity indefinitely"},{"key": "B","text": "Addressing footwear modification and forefoot mechanics alongside appropriate mobility/strengthening exercises"},{"key": "C","text": "Ignoring any footwear considerations during exercise prescription"},{"key": "D","text": "Aggressive forefoot loading exercises regardless of symptom provocation"}],"correct": "B","explanation": "Morton's neuroma management typically includes footwear modification addressing forefoot compression alongside general mobility and strengthening as tolerated."},{"id": 4923,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with hallux valgus (bunion) affecting gait mechanics?","options": [{"key": "A","text": "Complete avoidance of any foot-related exercise"},{"key": "B","text": "Ignoring any gait mechanics considerations related to this deformity"},{"key": "C","text": "Aggressive forceful correction of the deformity through manual stretching alone"},{"key": "D","text": "Addressing intrinsic foot muscle strengthening and appropriate footwear alongside gait pattern assessment"}],"correct": "D","explanation": "Hallux valgus management often incorporates intrinsic foot strengthening and appropriate footwear guidance alongside addressing any compensatory gait pattern changes related to the deformity."},{"id": 4924,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with posterior tibial tendon dysfunction affecting arch support?","options": [{"key": "A","text": "Ignoring any orthotic or footwear considerations"},{"key": "B","text": "Progressive strengthening of the posterior tibialis muscle combined with appropriate orthotic/footwear support as indicated"},{"key": "C","text": "Complete avoidance of any lower limb strengthening exercise"},{"key": "D","text": "Aggressive high-impact activity regardless of symptom severity"}],"correct": "B","explanation": "PTTD management typically combines targeted strengthening of the posterior tibialis with supportive footwear/orthotic strategies to address the functional arch support deficit."},{"id": 4925,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed stress fracture of the fifth metatarsal (Jones fracture)?","options": [{"key": "A","text": "Complete disregard for medical weight-bearing guidance"},{"key": "B","text": "Assuming this fracture location has no unique healing considerations compared to other metatarsal fractures"},{"key": "C","text": "Immediate unrestricted weight-bearing regardless of the specific fracture location"},{"key": "D","text": "Following appropriate weight-bearing restrictions per medical guidance given this fracture's known healing challenges, before progressive rehabilitation"}],"correct": "D","explanation": "Jones fractures are known for delayed healing/nonunion risk due to relatively poor blood supply at this location, requiring careful adherence to medical weight-bearing restrictions before progressive rehabilitation."},{"id": 4926,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with extensive burn scarring affecting axillary region mobility?","options": [{"key": "A","text": "Aggressive stretching over open, unhealed burn wounds"},{"key": "B","text": "Assuming axillary scarring has no functional consequence"},{"key": "C","text": "Complete avoidance of any shoulder movement during scar maturation"},{"key": "D","text": "Positioning and stretching to maintain shoulder abduction range, preventing axillary web contracture formation"}],"correct": "D","explanation": "Axillary burn scarring is prone to web contracture formation limiting shoulder abduction; proactive positioning and stretching once appropriate for wound status helps preserve functional range."},{"id": 4927,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for hypertrophic scarring following a burn injury, regarding pressure garment therapy?","options": [{"key": "A","text": "Complete avoidance of any garment use regardless of scar presentation"},{"key": "B","text": "Assuming pressure garment therapy has no relationship to exercise-based scar management"},{"key": "C","text": "Pressure garments are often used alongside exercise/stretching to help manage scar hypertrophy and maintain tissue mobility"},{"key": "D","text": "Pressure garments should always be removed during any exercise session"}],"correct": "C","explanation": "Pressure garment therapy is commonly used in conjunction with exercise and stretching as part of comprehensive burn scar management to help minimize hypertrophic scarring and maintain mobility."},{"id": 4928,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient in the acute phase following a large surface area burn regarding positioning?","options": [{"key": "A","text": "Assuming positioning has no role in burn rehabilitation"},{"key": "B","text": "Positioning burns in whatever position is most comfortable regardless of contracture risk"},{"key": "C","text": "Anti-contracture positioning (e.g., specific joint positioning to counteract the pull of healing burn tissue) alongside appropriate wound care coordination"},{"key": "D","text": "Ignoring positioning considerations until the burn is completely healed"}],"correct": "C","explanation": "Anti-contracture positioning is a critical early intervention in burn rehabilitation, addressing the known tendency for burn tissue to contract in ways that limit future functional movement."},{"id": 4929,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for pain management during burn wound care and associated exercise/stretching sessions?","options": [{"key": "A","text": "Assuming pain has no bearing on exercise participation in burn patients"},{"key": "B","text": "Ignoring pain medication timing considerations entirely"},{"key": "C","text": "Avoiding any exercise or stretching until all pain has completely resolved"},{"key": "D","text": "Coordinating exercise/stretching timing with pain medication administration to optimize patient comfort and participation"}],"correct": "D","explanation": "Given the significant pain associated with burn wound care and movement, coordinating exercise timing with analgesic administration helps optimize patient comfort and participation in essential rehabilitation activities."},{"id": 4930,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration regarding the 'talk test' as a practical method for gauging aerobic exercise intensity?","options": [{"key": "A","text": "The talk test has no practical clinical application for gauging exercise intensity"},{"key": "B","text": "Being able to talk but not sing comfortably generally indicates a moderate exercise intensity"},{"key": "C","text": "Being able to sing comfortably indicates a vigorous exercise intensity level"},{"key": "D","text": "Being unable to speak at all indicates an appropriately low exercise intensity"}],"correct": "B","explanation": "The talk test provides a simple, practical way to estimate exercise intensity, with the ability to talk but not sing comfortably generally corresponding to a moderate intensity level."},{"id": 4931,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration for a patient recently started on a new antihypertensive medication regarding exercise blood pressure response?","options": [{"key": "A","text": "Assuming all antihypertensive medications produce identical exercise blood pressure effects"},{"key": "B","text": "Ignoring blood pressure entirely during exercise sessions"},{"key": "C","text": "Assuming no monitoring adjustment is needed regardless of recent medication changes"},{"key": "D","text": "Monitoring blood pressure response to exercise, as medication changes may alter typical exercise-related blood pressure patterns until effects stabilize"}],"correct": "D","explanation": "New antihypertensive medications may alter typical blood pressure responses to exercise, warranting continued monitoring especially during the medication adjustment period."},{"id": 4932,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for monitoring exercise response in a patient with diabetes regarding blood glucose levels?","options": [{"key": "A","text": "Being aware of potential hypoglycemia risk during/after exercise, particularly in patients using insulin or certain oral medications"},{"key": "B","text": "Ignoring any reported symptoms of hypoglycemia during exercise sessions"},{"key": "C","text": "Assuming blood glucose has no relevance to exercise therapy safety"},{"key": "D","text": "Assuming all diabetic patients have identical blood glucose responses to exercise"}],"correct": "A","explanation": "Exercise can significantly affect blood glucose levels, particularly increasing hypoglycemia risk in patients on certain diabetes medications, making appropriate monitoring and patient education important safety considerations."},{"id": 4933,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate consideration for exercise therapy timing relative to meals in a patient with diabetes to help manage blood glucose response?","options": [{"key": "A","text": "Exercise should always be performed on a completely empty stomach regardless of medication regimen"},{"key": "B","text": "Considering the timing of exercise relative to meals and medication dosing as part of individualized blood glucose management strategy"},{"key": "C","text": "Exercise timing considerations only apply to Type 1 diabetes, never Type 2"},{"key": "D","text": "Exercise timing relative to meals has no relevance to blood glucose management"}],"correct": "B","explanation": "Coordinating exercise timing with meals and medication can help optimize blood glucose management and reduce hypo/hyperglycemia risk during and after physical activity in diabetic patients."},{"id": 4934,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diabetic foot ulcer regarding offloading during rehabilitation exercise?","options": [{"key": "A","text": "Assuming offloading has no relevance to exercise prescription in this population"},{"key": "B","text": "Complete avoidance of any exercise or mobility until the ulcer is fully healed"},{"key": "C","text": "Encouraging unrestricted weight-bearing directly on the ulcer site regardless of healing status"},{"key": "D","text": "Using appropriate offloading devices/footwear during weight-bearing exercise to protect the ulcer site while maintaining functional mobility"}],"correct": "D","explanation": "Appropriate offloading strategies protect the ulcer site from excessive pressure during necessary weight-bearing activity, balancing wound healing needs with maintaining functional mobility."},{"id": 4935,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a pressure injury on the sacrum regarding positioning during exercise sessions?","options": [{"key": "A","text": "Requiring the patient to remain in direct contact with the affected area throughout all exercise"},{"key": "B","text": "Complete avoidance of any exercise until the pressure injury has fully healed"},{"key": "C","text": "Ignoring positioning considerations during exercise sessions"},{"key": "D","text": "Minimizing prolonged direct pressure on the affected area during exercise positioning while still promoting appropriate mobility"}],"correct": "D","explanation": "Thoughtful positioning during exercise sessions helps minimize additional pressure on a healing pressure injury while still allowing beneficial mobility and functional activity."},{"id": 4936,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a venous leg ulcer regarding exercise and compression therapy?","options": [{"key": "A","text": "Removing compression therapy during all exercise sessions"},{"key": "B","text": "Assuming exercise has no role in venous ulcer management alongside compression"},{"key": "C","text": "Complete avoidance of any lower limb exercise due to the ulcer"},{"key": "D","text": "Combining appropriate ankle pump/calf exercises with prescribed compression therapy to support venous return and wound healing"}],"correct": "D","explanation": "Calf muscle pump exercises combined with appropriate compression therapy work synergistically to support venous return, an important component of comprehensive venous ulcer management."},{"id": 4937,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child with clubfoot (talipes equinovarus) following Ponseti method casting/bracing?","options": [{"key": "A","text": "Encouraging removal of the brace for extended periods against medical recommendation"},{"key": "B","text": "Ignoring gait development considerations in this population"},{"key": "C","text": "Assuming exercise therapy has no role once casting/bracing has begun"},{"key": "D","text": "Supporting the prescribed bracing protocol adherence while monitoring for appropriate range of motion and gait development"}],"correct": "D","explanation": "Physiotherapy support for clubfoot management often involves reinforcing the critical importance of brace adherence following Ponseti casting, alongside monitoring functional development."},{"id": 4938,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child with Legg-Calve-Perthes disease during the active disease phase?","options": [{"key": "A","text": "Encouraging unrestricted high-impact activity regardless of disease phase"},{"key": "B","text": "Activity modification to reduce excessive joint loading while maintaining hip range of motion through appropriate exercise, guided by orthopedic management"},{"key": "C","text": "Complete immobilization of the hip indefinitely"},{"key": "D","text": "Assuming exercise has no role in Perthes disease management"}],"correct": "B","explanation": "Perthes disease management often involves activity modification to protect the vulnerable femoral head while using appropriate exercise to maintain hip mobility, guided by the orthopedic treatment plan."},{"id": 4939,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child recovering from surgical correction of slipped capital femoral epiphysis?","options": [{"key": "A","text": "Complete avoidance of any physiotherapy involvement following this surgery"},{"key": "B","text": "Assuming standard adult hip protocols apply without pediatric-specific consideration"},{"key": "C","text": "Following surgeon-specific weight-bearing and activity protocols, with gradual progression as healing allows"},{"key": "D","text": "Immediate unrestricted weight-bearing regardless of surgical fixation status"}],"correct": "C","explanation": "Post-surgical SCFE rehabilitation follows structured, surgeon-guided protocols for weight-bearing and activity progression, similar in principle to other pediatric orthopedic surgical rehabilitation approaches."},{"id": 4940,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'muscle spindle' function relevant to stretching and reflexive muscle responses?","options": [{"key": "A","text": "Muscle spindles are located exclusively in tendons, not muscle bellies"},{"key": "B","text": "Muscle spindles only detect muscle tension, not length changes"},{"key": "C","text": "Muscle spindles have no role in reflexive muscle responses"},{"key": "D","text": "Muscle spindles detect changes in muscle length and rate of stretch, triggering a reflexive contraction (stretch reflex) to resist rapid stretching"}],"correct": "D","explanation": "Muscle spindles are sensory receptors within muscle bellies that detect stretch, triggering the stretch reflex (myotatic reflex) that resists rapid or excessive muscle lengthening."},{"id": 4941,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'Golgi tendon organ' function relevant to muscle tension monitoring?","options": [{"key": "A","text": "Golgi tendon organs detect muscle tension and can trigger reflexive inhibition (autogenic inhibition) to protect against excessive force"},{"key": "B","text": "Golgi tendon organs have no protective reflexive function"},{"key": "C","text": "Golgi tendon organs detect only muscle length changes, not tension"},{"key": "D","text": "Golgi tendon organs are located within the muscle belly, not near the tendon"}],"correct": "A","explanation": "GTOs are located near the muscle-tendon junction and monitor tension, triggering autogenic inhibition (relaxation) when excessive tension is detected, a protective mechanism exploited in certain PNF stretching techniques."},{"id": 4942,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'reciprocal inhibition' as a normal neurophysiological mechanism during movement?","options": [{"key": "A","text": "This mechanism has no relevance to normal movement coordination"},{"key": "B","text": "When an agonist muscle contracts, its antagonist is reflexively inhibited to allow smooth, coordinated movement"},{"key": "C","text": "Reciprocal inhibition only occurs during pathological conditions, not normal movement"},{"key": "D","text": "Both agonist and antagonist muscles always contract with equal force simultaneously"}],"correct": "B","explanation": "Reciprocal inhibition is a fundamental neurophysiological mechanism allowing smooth movement by inhibiting the antagonist muscle during agonist contraction, exploited therapeutically in certain stretching and facilitation techniques."},{"id": 4943,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'motor unit' as a fundamental unit of muscle contraction?","options": [{"key": "A","text": "A single isolated muscle fiber without any neural connection"},{"key": "B","text": "A motor neuron and all the muscle fibers it innervates, which contract together as a functional unit"},{"key": "C","text": "A term referring only to sensory receptors within muscle"},{"key": "D","text": "The entire muscle belly regardless of neural innervation pattern"}],"correct": "B","explanation": "A motor unit comprises a single motor neuron and all the muscle fibers it innervates, representing the smallest functional unit of voluntary muscle contraction."},{"id": 4944,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the relationship between motor unit size and the type of movement typically controlled?","options": [{"key": "A","text": "Smaller motor units (fewer muscle fibers per neuron) typically control fine, precise movements, while larger motor units control gross, powerful movements"},{"key": "B","text": "Larger motor units always control the most precise, fine movements"},{"key": "C","text": "All motor units are identical in size regardless of the muscle or movement type"},{"key": "D","text": "Motor unit size has no relationship to movement precision or force output"}],"correct": "A","explanation": "Small motor unit size (e.g., in eye muscles, intrinsic hand muscles) allows fine motor control, while larger motor units (e.g., in large limb muscles) are suited to generating greater force for gross movements."},{"id": 4945,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which stretching position would appropriately target the piriformis muscle, useful in managing piriformis syndrome symptoms?","options": [{"key": "A","text": "Hip extension and external rotation"},{"key": "B","text": "Hip flexion, adduction, and internal rotation (e.g., figure-4 stretch position)"},{"key": "C","text": "Ankle plantarflexion with knee flexion"},{"key": "D","text": "Hip abduction with knee extension"}],"correct": "B","explanation": "The piriformis muscle is effectively stretched through combined hip flexion, adduction, and internal rotation positioning, commonly used in managing piriformis-related sciatic symptoms."},{"id": 4946,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which stretching position would appropriately target the iliopsoas (hip flexor) muscle group?","options": [{"key": "A","text": "Hip abduction with external rotation"},{"key": "B","text": "Hip extension combined with maintaining a neutral or slightly posteriorly tilted pelvis (e.g., lunge-based stretch)"},{"key": "C","text": "Ankle dorsiflexion with knee extension"},{"key": "D","text": "Hip flexion with knee extension"}],"correct": "B","explanation": "Effective hip flexor stretching requires hip extension while controlling pelvic position to avoid compensatory lumbar hyperextension, commonly performed in a lunge-based position."},{"id": 4947,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which stretching position would appropriately target the quadriceps muscle group, particularly rectus femoris (a two-joint muscle)?","options": [{"key": "A","text": "Hip flexion combined with knee extension"},{"key": "B","text": "Ankle plantarflexion alone"},{"key": "C","text": "Hip extension combined with knee flexion"},{"key": "D","text": "Hip abduction with knee flexion"}],"correct": "C","explanation": "Since rectus femoris crosses both the hip and knee, maximal stretch requires combining hip extension with knee flexion, unlike the single-joint vasti muscles."},{"id": 4948,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which stretching position would appropriately target the pectoralis major/minor muscles, commonly tight in patients with rounded shoulder posture?","options": [{"key": "A","text": "Wrist flexion with elbow extension"},{"key": "B","text": "Shoulder extension with elbow flexion"},{"key": "C","text": "Shoulder horizontal abduction/external rotation, often performed in a doorway stretch position"},{"key": "D","text": "Shoulder horizontal adduction and internal rotation"}],"correct": "C","explanation": "Doorway-style stretches using shoulder horizontal abduction and external rotation effectively lengthen the commonly tight pectoral muscles associated with rounded shoulder posture."},{"id": 4949,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which stretching position would appropriately target the upper trapezius muscle, often tight in patients with forward head posture and neck tension?","options": [{"key": "A","text": "Cervical lateral flexion toward the tight side"},{"key": "B","text": "Shoulder elevation combined with cervical extension"},{"key": "C","text": "Cervical lateral flexion away from the tight side combined with slight rotation and depression of the shoulder"},{"key": "D","text": "Cervical extension only without any lateral component"}],"correct": "C","explanation": "Upper trapezius stretching involves lateral flexion away from the tight side while stabilizing/depressing the shoulder, commonly used for tension-related neck and shoulder discomfort."},{"id": 4950,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise would appropriately target the serratus anterior muscle, important for scapular upward rotation and preventing winging?","options": [{"key": "A","text": "Push-up plus (protraction at end range with a push-up)"},{"key": "B","text": "Standard bicep curl"},{"key": "C","text": "Seated row"},{"key": "D","text": "Standing calf raise"}],"correct": "A","explanation": "The 'push-up plus' involves additional scapular protraction at the top of a push-up, specifically targeting serratus anterior activation important for scapular stability."},{"id": 4951,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which exercise would appropriately target the rhomboid muscles, important for scapular retraction?","options": [{"key": "A","text": "Seated or standing row with scapular retraction emphasis"},{"key": "B","text": "Overhead shoulder press"},{"key": "C","text": "Bicep curl"},{"key": "D","text": "Standing calf raise"}],"correct": "A","explanation": "Rowing exercises with conscious scapular retraction effectively target the rhomboid muscles, important for counteracting rounded shoulder posture."},{"id": 4952,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which exercise would appropriately target the gluteus maximus specifically for hip extension strengthening?","options": [{"key": "A","text": "Hip thrusts or bridges with a focus on gluteal contraction"},{"key": "B","text": "Standing hip flexion with resistance"},{"key": "C","text": "Seated knee extension"},{"key": "D","text": "Standing calf raise"}],"correct": "A","explanation": "Hip thrust and bridge variations, performed with attention to gluteal (rather than hamstring-dominant) activation, effectively target gluteus maximus strengthening."},{"id": 4953,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise would appropriately target the vastus medialis obliquus (VMO), often emphasized in patellofemoral pain rehabilitation?","options": [{"key": "A","text": "Seated hip abduction"},{"key": "B","text": "Standing calf raises"},{"key": "C","text": "Terminal knee extension exercises performed in the final 30 degrees of knee extension"},{"key": "D","text": "Deep squatting through full range only"}],"correct": "C","explanation": "Terminal knee extension in the last 30 degrees of range preferentially recruits the VMO, a commonly emphasized exercise in patellofemoral pain rehabilitation programs."},{"id": 4954,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise would appropriately target the tibialis posterior muscle, important in supporting the medial longitudinal arch of the foot?","options": [{"key": "A","text": "Toe curls with a towel"},{"key": "B","text": "Resisted ankle eversion exercises"},{"key": "C","text": "Resisted ankle inversion exercises"},{"key": "D","text": "Standing calf raises with eyes closed"}],"correct": "C","explanation": "Resisted inversion specifically targets the tibialis posterior, an important muscle for supporting the medial arch, commonly weakened in posterior tibial tendon dysfunction."},{"id": 4955,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which exercise would appropriately target the peroneal (fibularis) muscles, important for lateral ankle stability?","options": [{"key": "A","text": "Resisted ankle eversion exercises"},{"key": "B","text": "Resisted ankle inversion exercises"},{"key": "C","text": "Toe curls"},{"key": "D","text": "Standing heel raises with eyes open"}],"correct": "A","explanation": "Resisted eversion exercises target the peroneal muscle group, commonly weakened following ankle sprains and important for lateral ankle stability retraining."},{"id": 4956,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'co-contraction' as relevant to joint stability during exercise?","options": [{"key": "A","text": "Simultaneous contraction of agonist and antagonist muscles around a joint to enhance stability"},{"key": "B","text": "Only the agonist muscle contracts while the antagonist remains completely relaxed"},{"key": "C","text": "Co-contraction only occurs during isometric exercise, never dynamic movement"},{"key": "D","text": "A concept with no relevance to joint stability training"}],"correct": "A","explanation": "Co-contraction of opposing muscle groups around a joint enhances dynamic stability, an important consideration in exercises targeting joint protection, particularly in early rehabilitation phases."},{"id": 4957,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate consideration for using closed-chain co-contraction exercises early in ACL rehabilitation?","options": [{"key": "A","text": "These exercises isolate only the quadriceps without any hamstring involvement"},{"key": "B","text": "Co-contraction exercises are contraindicated in all phases of ACL rehabilitation"},{"key": "C","text": "These exercises provide no meaningful benefit for joint stability"},{"key": "D","text": "These exercises promote quadriceps-hamstring co-contraction, providing dynamic knee stability while minimizing excessive anterior tibial shear force"}],"correct": "D","explanation": "Closed-chain exercises that promote simultaneous quadriceps-hamstring activity help protect the healing ACL graft by reducing the shear forces associated with isolated quadriceps contraction."},{"id": 4958,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'muscle synergies' relevant to functional movement retraining, particularly in neurological rehabilitation?","options": [{"key": "A","text": "Coordinated patterns of multiple muscle activation working together to produce functional movement"},{"key": "B","text": "Isolated activation of a single muscle without any coordination with other muscles"},{"key": "C","text": "A concept only relevant to healthy individuals, not neurological rehabilitation"},{"key": "D","text": "Muscle synergies have no relevance to exercise therapy planning"}],"correct": "A","explanation": "Understanding muscle synergy patterns helps therapists design exercises that promote coordinated, functional movement patterns rather than isolated muscle activation, particularly relevant in neurological rehabilitation."},{"id": 4959,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes the concept of 'compensatory movement pattern' that physiotherapists should identify and address during exercise therapy?","options": [{"key": "A","text": "A movement pattern identical to normal, unimpaired movement"},{"key": "B","text": "An altered movement strategy that a patient adopts to accomplish a task despite an underlying impairment, which may need correction to avoid secondary issues"},{"key": "C","text": "A pattern that always requires no intervention regardless of its long-term implications"},{"key": "D","text": "A concept only relevant to elite athletic performance"}],"correct": "B","explanation": "Identifying compensatory movement patterns (adopted to work around an impairment) is important, as these patterns, while sometimes initially adaptive, may contribute to secondary issues if not appropriately addressed."},{"id": 4960,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration when a patient demonstrates a compensatory movement pattern during a functional task (e.g., substituting trunk lateral flexion for adequate hip abduction during gait)?","options": [{"key": "A","text": "Focusing exclusively on the compensation without addressing the underlying impairment"},{"key": "B","text": "Addressing the underlying impairment (e.g., hip abductor weakness) through targeted exercise while providing cues to reduce the compensatory pattern"},{"key": "C","text": "Assuming compensatory patterns never require correction regardless of their functional implications"},{"key": "D","text": "Ignoring the compensatory pattern since the task is still being completed"}],"correct": "B","explanation": "Effective treatment addresses the root cause of a compensatory pattern (the underlying impairment) rather than simply cueing pattern correction without addressing why the compensation developed in the first place."},{"id": 4961,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed diaphragmatic paralysis affecting breathing mechanics?","options": [{"key": "A","text": "Assuming diaphragmatic paralysis has no bearing on breathing exercise strategy"},{"key": "B","text": "Emphasizing accessory muscle breathing techniques and possibly positioning strategies to optimize ventilation given the compromised primary respiratory muscle"},{"key": "C","text": "Complete avoidance of any respiratory exercise intervention"},{"key": "D","text": "Standard diaphragmatic breathing exercises without any modification"}],"correct": "B","explanation": "When diaphragmatic function is compromised, alternative breathing strategies emphasizing accessory respiratory muscles and appropriate positioning become important therapeutic considerations."},{"id": 4962,"subject": "Exercise Therapy","topic": "PNF & Manual Techniques","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a ventilator-dependent patient regarding early mobilization in the intensive care setting?","options": [{"key": "A","text": "Ignoring any monitoring considerations during early ICU mobilization"},{"key": "B","text": "Assuming mobilization has no role until the patient is fully weaned from ventilation"},{"key": "C","text": "Early, carefully monitored mobilization (even while ventilated) is increasingly recognized as beneficial for reducing ICU-acquired weakness"},{"key": "D","text": "Complete immobilization is always required for ventilated patients"}],"correct": "C","explanation": "Current evidence supports early, appropriately monitored mobilization even in ventilated ICU patients to help reduce the significant risk of ICU-acquired weakness and improve functional outcomes."},{"id": 4963,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with post-intubation tracheal stenosis affecting airway clearance?","options": [{"key": "A","text": "Assuming airway stenosis has no bearing on respiratory physiotherapy approach"},{"key": "B","text": "Coordinating with the medical team regarding airway management while incorporating appropriate breathing/airway clearance techniques as clinically indicated"},{"key": "C","text": "Ignoring any medical coordination considerations for this complex condition"},{"key": "D","text": "Complete avoidance of any breathing exercise intervention"}],"correct": "B","explanation": "Post-intubation tracheal stenosis requires careful coordination with the medical team, with respiratory physiotherapy techniques adapted appropriately to the specific airway considerations present."},{"id": 4964,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from thoracic surgery regarding early breathing exercises?","options": [{"key": "A","text": "Encouraging deep breathing and coughing exercises, often with incentive spirometry, to prevent postoperative atelectasis and pneumonia"},{"key": "B","text": "Assuming postoperative breathing exercises have no relevance to pulmonary complication prevention"},{"key": "C","text": "Complete avoidance of any respiratory intervention until the surgical incision is fully healed"},{"key": "D","text": "Avoiding any deep breathing exercises due to postoperative pain"}],"correct": "A","explanation": "Early breathing exercises and incentive spirometry are core components of postoperative thoracic surgery care, helping prevent common complications like atelectasis and pneumonia."},{"id": 4965,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration regarding splinting techniques for pain management during coughing/deep breathing after abdominal or thoracic surgery?","options": [{"key": "A","text": "Complete avoidance of any patient education regarding pain management during breathing exercises"},{"key": "B","text": "Teaching the patient to support (splint) the incision area with a pillow or hands during coughing to reduce pain while still achieving effective secretion clearance"},{"key": "C","text": "Assuming splinting techniques have no relevance to postoperative respiratory exercise"},{"key": "D","text": "Avoiding any coughing exercises due to expected postoperative pain"}],"correct": "B","explanation": "Teaching incision splinting techniques helps patients perform necessary deep breathing and coughing exercises with reduced pain, supporting effective airway clearance during postoperative recovery."},{"id": 4966,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for reducing fall risk related to environmental hazards, as part of a comprehensive falls prevention program?","options": [{"key": "A","text": "Ignoring any home safety assessment as part of physiotherapy practice"},{"key": "B","text": "Only addressing exercise-based strength/balance training without any environmental consideration"},{"key": "C","text": "Combining exercise-based interventions with home safety assessment and modification recommendations"},{"key": "D","text": "Assuming environmental factors have no relevance to comprehensive fall prevention"}],"correct": "C","explanation": "Comprehensive fall prevention programs combine exercise-based interventions with attention to environmental/home safety factors, recognizing that both intrinsic and extrinsic factors contribute to fall risk."},{"id": 4967,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the Otago Exercise Programme, a well-established falls prevention exercise intervention for older adults?","options": [{"key": "A","text": "An approach with no evidence supporting its effectiveness for fall prevention"},{"key": "B","text": "A program focused exclusively on cardiovascular conditioning without any strength/balance component"},{"key": "C","text": "A single-session balance assessment with no ongoing exercise component"},{"key": "D","text": "A structured, individually prescribed program of strength and balance exercises, often combined with a walking plan, delivered progressively over time"}],"correct": "D","explanation": "The Otago Exercise Programme is a well-researched, individually tailored strength and balance exercise program with demonstrated effectiveness in reducing falls among older adults."},{"id": 4968,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an older adult who has experienced a fall, regarding addressing fear of falling in subsequent exercise participation?","options": [{"key": "A","text": "Immediately exposing the patient to maximal balance challenges without any graded approach"},{"key": "B","text": "Avoiding any balance-challenging activities indefinitely following a fall"},{"key": "C","text": "Assuming fear of falling has no bearing on exercise program design or participation"},{"key": "D","text": "Providing graded exposure to balance challenges alongside education and confidence-building strategies to address post-fall anxiety"}],"correct": "D","explanation": "Post-fall anxiety (post-fall syndrome) can significantly limit activity and independence; addressing this through graded, confidence-building exercise exposure is an important component of comprehensive fall recovery."},{"id": 4969,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for group-based versus individual exercise programs for community-dwelling older adults?","options": [{"key": "A","text": "Individual programs are always superior regardless of social engagement considerations"},{"key": "B","text": "Program format has no bearing on patient adherence or outcomes"},{"key": "C","text": "Group-based programs are always superior regardless of individual patient needs"},{"key": "D","text": "Group-based programs can provide social engagement benefits alongside exercise, while individual programs may better address specific impairments"}],"correct": "D","explanation": "Both group and individual exercise formats offer distinct potential benefits (social engagement vs. individualized attention), and selection should consider the specific patient's needs, preferences, and impairment complexity."},{"id": 4970,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes general aerobic exercise guidelines commonly recommended for healthy adults by major health organizations?","options": [{"key": "A","text": "No specific weekly duration recommendation exists"},{"key": "B","text": "Only vigorous-intensity activity is recommended, with no role for moderate intensity"},{"key": "C","text": "At least 150 minutes of moderate-intensity aerobic activity per week, or equivalent vigorous activity"},{"key": "D","text": "At least 10 minutes of activity performed once per month"}],"correct": "C","explanation": "Widely referenced guidelines (e.g., WHO, ACSM) recommend at least 150 minutes of moderate-intensity aerobic activity weekly (or 75 minutes vigorous) for general health benefits in healthy adults."},{"id": 4971,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes general resistance training frequency guidelines commonly recommended for healthy adults?","options": [{"key": "A","text": "Resistance training should be performed every single day without any rest days"},{"key": "B","text": "Resistance training is not recommended for general health guidelines"},{"key": "C","text": "Resistance training targeting major muscle groups at least 2 days per week"},{"key": "D","text": "Resistance training frequency has no established general guideline"}],"correct": "C","explanation": "Common guidelines recommend resistance training for major muscle groups at least 2 days per week, allowing appropriate recovery between sessions targeting the same muscle groups."},{"id": 4972,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate consideration when a patient's exercise program needs modification due to an acute illness (e.g., viral infection with fever)?","options": [{"key": "A","text": "Generally recommending rest and avoiding vigorous exercise until symptoms resolve, particularly with systemic symptoms like fever"},{"key": "B","text": "Assuming acute illness has no bearing on appropriate exercise modification"},{"key": "C","text": "Continuing unmodified vigorous exercise regardless of acute illness symptoms"},{"key": "D","text": "Immediately discontinuing all future exercise participation permanently due to a temporary illness"}],"correct": "A","explanation": "Temporary modification or cessation of vigorous exercise during acute illness with systemic symptoms (particularly fever) is a generally accepted safety precaution, with gradual return once symptoms resolve."},{"id": 4973,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with well-controlled asthma regarding general exercise participation?","options": [{"key": "A","text": "Exercise is always contraindicated in any patient with an asthma diagnosis"},{"key": "B","text": "Regular exercise, with appropriate premedication/warm-up strategies if needed, is generally safe and beneficial for most patients with well-controlled asthma"},{"key": "C","text": "Assuming well-controlled asthma requires no exercise-related precautions whatsoever"},{"key": "D","text": "Complete avoidance of all exercise regardless of asthma control status"}],"correct": "B","explanation": "With appropriate management strategies, regular exercise participation is generally safe and beneficial for patients with well-controlled asthma, though awareness of exercise-induced bronchospasm risk remains relevant."},{"id": 4974,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with incomplete spinal cord injury showing some preserved motor function below the level of injury?","options": [{"key": "A","text": "Emphasizing activity-based therapy and task-specific practice to maximize potential neuroplastic recovery of the preserved pathways"},{"key": "B","text": "Ignoring any preserved motor function during rehabilitation planning"},{"key": "C","text": "Complete avoidance of any exercise targeting the affected areas"},{"key": "D","text": "Assuming no further neurological recovery is possible and focusing solely on compensatory strategies"}],"correct": "A","explanation": "Incomplete SCI retains some potential for neuroplastic recovery through preserved neural pathways, making activity-based, task-specific therapy an important component alongside compensatory strategy training."},{"id": 4975,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for locomotor training approaches (e.g., body-weight supported treadmill training) in incomplete spinal cord injury rehabilitation?","options": [{"key": "A","text": "Only appropriate for complete spinal cord injuries, never incomplete injuries"},{"key": "B","text": "A technique with no theoretical basis for promoting neurological recovery"},{"key": "C","text": "Providing repetitive, task-specific stepping practice that may help promote spinal cord plasticity and improve walking function"},{"key": "D","text": "Assuming locomotor training provides no functional benefit regardless of injury completeness"}],"correct": "C","explanation": "Locomotor training approaches leverage the concept of activity-dependent plasticity within spinal cord circuits, potentially promoting improved stepping and walking function particularly in incomplete SCI."},{"id": 4976,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with traumatic brain injury experiencing significant behavioral/emotional dysregulation affecting therapy participation?","options": [{"key": "A","text": "Collaborating with the broader care team (psychology, behavioral specialists) while adapting exercise therapy delivery to support safe, effective engagement"},{"key": "B","text": "Immediately discontinuing all physiotherapy involvement due to behavioral challenges"},{"key": "C","text": "Ignoring any collaborative care team involvement"},{"key": "D","text": "Assuming behavioral dysregulation has no bearing on physiotherapy delivery"}],"correct": "A","explanation": "TBI-related behavioral/emotional changes often require a collaborative, multidisciplinary approach, with physiotherapy delivery adapted to support safe and effective participation within this broader care context."},{"id": 4977,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with hemispatial neglect during functional mobility training?","options": [{"key": "A","text": "Only training mobility skills on the non-neglected side"},{"key": "B","text": "Assuming neglect has no bearing on functional mobility training safety or approach"},{"key": "C","text": "Providing cues and structuring the environment to draw attention to the neglected side, alongside functional practice"},{"key": "D","text": "Ignoring the neglected side entirely during therapy sessions"}],"correct": "C","explanation": "Addressing hemispatial neglect during functional training often involves specific strategies to draw attention to the neglected side, important for both safety and functional recovery."},{"id": 4978,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic exertional compartment syndrome?","options": [{"key": "A","text": "Standard strengthening exercise alone reliably resolves this condition without any other intervention"},{"key": "B","text": "Assuming exercise therapy has no role in this condition's management"},{"key": "C","text": "Complete avoidance of any physical activity permanently resolves the underlying pathology"},{"key": "D","text": "Activity modification and gait retraining may provide some symptom relief, though surgical fasciotomy is often required for definitive management in persistent cases"}],"correct": "D","explanation": "Chronic exertional compartment syndrome often has limited response to conservative measures alone, with surgical fasciotomy frequently needed for definitive relief, though gait retraining/activity modification may provide some benefit."},{"id": 4979,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed snapping hip syndrome (external type, involving the iliotibial band)?","options": [{"key": "A","text": "Complete avoidance of any hip-related exercise"},{"key": "B","text": "Ignoring any IT band flexibility considerations"},{"key": "C","text": "Addressing IT band flexibility and hip abductor strength/control as part of a comprehensive management approach"},{"key": "D","text": "Immediate surgical referral without attempting conservative management first"}],"correct": "C","explanation": "External snapping hip syndrome, related to IT band snapping over the greater trochanter, often responds to conservative management addressing flexibility and hip muscle strength/control."},{"id": 4980,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed adhesive capsulitis (frozen shoulder) in the 'freezing' (acute, painful) stage?","options": [{"key": "A","text": "Assuming stage of the condition has no bearing on appropriate exercise intensity"},{"key": "B","text": "Gentle range of motion within pain tolerance, avoiding aggressive stretching that may exacerbate the inflammatory process"},{"key": "C","text": "Complete immobilization of the shoulder throughout this stage"},{"key": "D","text": "Aggressive forceful stretching to quickly restore full range regardless of pain response"}],"correct": "B","explanation": "During the acute, painful freezing stage of adhesive capsulitis, gentle rather than aggressive stretching is generally recommended to avoid exacerbating the underlying inflammatory process."},{"id": 4981,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with adhesive capsulitis in the 'thawing' (resolution) stage?","options": [{"key": "A","text": "Continuing only the most gentle exercises regardless of the improving stage"},{"key": "B","text": "Progressive stretching and strengthening as the condition gradually improves and tolerance for more aggressive intervention increases"},{"key": "C","text": "Complete cessation of any physiotherapy involvement once thawing begins"},{"key": "D","text": "Assuming no change in exercise approach is needed across the different stages"}],"correct": "B","explanation": "As adhesive capsulitis progresses into the thawing stage with reducing pain/inflammation, exercise approach can typically progress to more assertive stretching and strengthening as tolerated."},{"id": 4982,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with calcific tendinitis of the rotator cuff during an acute, highly painful phase?","options": [{"key": "A","text": "Complete avoidance of any physiotherapy involvement during this condition"},{"key": "B","text": "Gentle pain-relieving positioning and range of motion, often deferring aggressive strengthening until the acute phase resolves"},{"key": "C","text": "Aggressive immediate strengthening regardless of the acute inflammatory presentation"},{"key": "D","text": "Assuming acute calcific tendinitis requires no modification from standard rotator cuff protocols"}],"correct": "B","explanation": "Acute calcific tendinitis can present with severe pain requiring a gentler initial approach, with more assertive strengthening typically introduced once the acute inflammatory phase subsides."},{"id": 4983,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an infant with brachial plexus birth palsy (Erb's palsy)?","options": [{"key": "A","text": "Gentle range of motion exercises to prevent contracture while monitoring for spontaneous recovery, often over the first several months"},{"key": "B","text": "Complete avoidance of any exercise or positioning intervention"},{"key": "C","text": "Aggressive forceful stretching immediately regardless of the infant's tolerance"},{"key": "D","text": "Assuming spontaneous recovery potential has no bearing on the treatment approach"}],"correct": "A","explanation": "Most brachial plexus birth injuries show some spontaneous recovery over the first months; gentle range of motion exercises help prevent contracture while this recovery process unfolds."},{"id": 4984,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a child with spina bifida (myelomeningocele) regarding lower extremity exercise?","options": [{"key": "A","text": "Addressing the specific pattern of motor/sensory involvement based on the neurological level, often combined with orthotic/mobility device training"},{"key": "B","text": "Ignoring any orthotic or mobility device considerations"},{"key": "C","text": "Assuming standard exercise prescription applies regardless of the specific neurological level involved"},{"key": "D","text": "Complete avoidance of any lower extremity exercise"}],"correct": "A","explanation": "Spina bifida presents with variable patterns of motor and sensory involvement depending on the lesion level, requiring individualized exercise approaches often integrated with appropriate orthotic and mobility device training."},{"id": 4985,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a child with congenital muscular torticollis who has not fully responded to conservative stretching by around 6 months of age?","options": [{"key": "A","text": "Ignoring any need for reassessment despite limited treatment response"},{"key": "B","text": "Assuming all cases resolve with unlimited continued conservative treatment regardless of response"},{"key": "C","text": "Complete cessation of any further intervention if initial treatment shows limited progress"},{"key": "D","text": "Continued monitoring with possible reassessment for other contributing factors or consideration of surgical referral if conservative treatment has been insufficient"}],"correct": "D","explanation": "Persistent torticollis despite appropriate conservative treatment may warrant further evaluation for other contributing factors or consideration of surgical referral, following established clinical pathways."},{"id": 4986,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a child with a diagnosed brachial plexus injury showing signs of incomplete recovery affecting shoulder function?","options": [{"key": "A","text": "Assuming no further intervention is beneficial once initial recovery has plateaued"},{"key": "B","text": "Ongoing strengthening and functional training addressing the specific pattern of residual weakness, potentially informed by nerve conduction studies"},{"key": "C","text": "Ignoring any diagnostic information regarding the specific pattern of nerve involvement"},{"key": "D","text": "Complete avoidance of any further shoulder-related exercise"}],"correct": "B","explanation": "For children with residual weakness following brachial plexus injury, targeted strengthening and functional training addressing the specific affected muscle groups remains an important ongoing physiotherapy focus."},{"id": 4987,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a known history of exercise-induced ventricular arrhythmia?","options": [{"key": "A","text": "Assuming this history has no bearing on appropriate exercise setting or monitoring"},{"key": "B","text": "Standard unsupervised exercise prescription without any additional precautions"},{"key": "C","text": "Complete avoidance of any medical involvement in exercise planning"},{"key": "D","text": "Requiring careful medical clearance and often closely monitored/supervised exercise settings given the elevated risk profile"}],"correct": "D","explanation": "A history of exercise-induced ventricular arrhythmia represents a significant risk factor requiring careful medical clearance and typically more closely supervised exercise settings for safety."},{"id": 4988,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with an implantable cardioverter-defibrillator (ICD) regarding exercise intensity thresholds?","options": [{"key": "A","text": "Encouraging maximal exercise intensity regardless of device programming"},{"key": "B","text": "Assuming ICD presence has no bearing on appropriate exercise heart rate targets"},{"key": "C","text": "Being aware of the device's programmed heart rate threshold for shock delivery and avoiding exercise intensities that could approach this threshold inappropriately"},{"key": "D","text": "Ignoring any potential interaction between exercise intensity and device function"}],"correct": "C","explanation": "Understanding the specific heart rate threshold programmed into a patient's ICD is important for appropriate exercise intensity prescription, avoiding inappropriate device shock delivery during exercise."},{"id": 4989,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for monitoring a patient with a history of syncope during exercise-based rehabilitation?","options": [{"key": "A","text": "Continuing exercise progression regardless of any concerning symptoms"},{"key": "B","text": "Close symptom and vital sign monitoring, with immediate cessation of activity and appropriate positioning if any pre-syncopal symptoms occur"},{"key": "C","text": "Ignoring any reported pre-syncopal symptoms during exercise"},{"key": "D","text": "Assuming syncope history has no bearing on exercise monitoring approach"}],"correct": "B","explanation": "A history of syncope warrants heightened vigilance for pre-syncopal symptoms during exercise, with prompt appropriate response (cessation, positioning) if such symptoms occur."},{"id": 4990,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a recently diagnosed long QT syndrome regarding exercise participation?","options": [{"key": "A","text": "Standard unrestricted exercise participation without any cardiology involvement"},{"key": "B","text": "Assuming this diagnosis has no bearing on appropriate exercise guidance"},{"key": "C","text": "Complete avoidance of any physical activity assessment or clearance process"},{"key": "D","text": "Requiring careful cardiology-guided clearance and often specific activity/intensity guidance given the arrhythmia risk associated with this condition"}],"correct": "D","explanation": "Long QT syndrome carries significant arrhythmia risk, particularly with certain types of exertion, requiring careful cardiology-guided clearance and activity recommendations before exercise program initiation."},{"id": 4991,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate use of ankle weights during a therapeutic exercise program?","options": [{"key": "A","text": "Providing graded resistance progression for lower extremity strengthening exercises as tolerance improves"},{"key": "B","text": "Only usable for upper extremity exercises"},{"key": "C","text": "Providing identical resistance regardless of the amount of weight used"},{"key": "D","text": "A modality with no practical application in rehabilitation"}],"correct": "A","explanation": "Ankle weights offer a simple, accessible way to provide graded resistance progression for various lower extremity strengthening exercises in a rehabilitation setting."},{"id": 4992,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate use of a slide board (lateral training device) in rehabilitation exercise programming?","options": [{"key": "A","text": "A device with no practical rehabilitation application"},{"key": "B","text": "Providing a frontal plane, lateral movement training option, useful for certain sport-specific or balance/coordination goals"},{"key": "C","text": "Only usable for sagittal plane movement training"},{"key": "D","text": "Providing resistance only in the vertical plane"}],"correct": "B","explanation": "Slide boards allow controlled frontal plane lateral movement training, useful for certain functional or sport-specific rehabilitation goals not addressed by purely sagittal plane exercises."},{"id": 4993,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate use of a stability ball (Swiss ball) in core/postural exercise programming?","options": [{"key": "A","text": "A tool with no practical application to core stability training"},{"key": "B","text": "Only usable as a substitute for a standard chair with no exercise-specific benefit"},{"key": "C","text": "Providing a completely stable, fixed surface for exercise"},{"key": "D","text": "Providing an unstable surface that challenges core stabilization during various exercise positions"}],"correct": "D","explanation": "Stability balls introduce surface instability that challenges core stabilizing muscles during a variety of exercise positions, commonly used in progressive core training programs."},{"id": 4994,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate use of a suspension trainer (e.g., TRX-style device) in rehabilitation exercise programming?","options": [{"key": "A","text": "Providing an adjustable, bodyweight-based resistance system useful for a range of strengthening and stability exercises"},{"key": "B","text": "Only usable for maximal strength training with external weights"},{"key": "C","text": "A device requiring no consideration of patient body weight or leverage"},{"key": "D","text": "A tool with no practical rehabilitation application"}],"correct": "A","explanation": "Suspension training systems allow adjustable-intensity bodyweight exercise through altering body angle/leverage, offering versatility across a range of rehabilitation strengthening and stability goals."},{"id": 4995,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the Transtheoretical Model (Stages of Change) as applied to exercise behavior counseling?","options": [{"key": "A","text": "A model asserting all patients are equally ready to begin exercise immediately"},{"key": "B","text": "A framework describing stages (precontemplation, contemplation, preparation, action, maintenance) that individuals progress through when adopting new health behaviors"},{"key": "C","text": "A model only relevant to smoking cessation, not exercise behavior"},{"key": "D","text": "A framework with no practical application to exercise counseling"}],"correct": "B","explanation": "The Transtheoretical Model helps therapists tailor their approach based on a patient's current readiness stage for behavior change, informing more effective, individualized exercise counseling strategies."},{"id": 4996,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate counseling approach for a patient in the 'contemplation' stage of readiness for exercise behavior change (considering change but not yet acting)?","options": [{"key": "A","text": "Assuming the patient's stage of readiness has no bearing on the counseling approach"},{"key": "B","text": "Exploring the patient's perceived pros/cons of change and building motivation, rather than immediately prescribing a detailed action plan"},{"key": "C","text": "Dismissing the patient's ambivalence about change entirely"},{"key": "D","text": "Immediately providing a detailed, structured exercise prescription regardless of readiness"}],"correct": "B","explanation": "Patients in the contemplation stage benefit from exploring their ambivalence and building motivation before moving to detailed action planning, which is more appropriate once they reach the preparation/action stages."},{"id": 4997,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes the concept of 'locus of control' as it may relate to a patient's engagement with an exercise-based rehabilitation program?","options": [{"key": "A","text": "A patient's belief about whether their health outcomes are primarily controlled by their own actions (internal) versus external factors (external)"},{"key": "B","text": "A term describing only physical balance control, unrelated to psychology"},{"key": "C","text": "A concept only relevant to psychiatric assessment, not physiotherapy"},{"key": "D","text": "A concept with no relevance to exercise program engagement"}],"correct": "A","explanation": "Understanding a patient's locus of control beliefs can help therapists tailor communication and goal-setting approaches to support more effective engagement with self-managed exercise programs."},{"id": 4998,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate approach for supporting a patient with an external locus of control belief regarding their exercise program engagement?","options": [{"key": "A","text": "Providing minimal structure and follow-up, expecting full patient self-direction"},{"key": "B","text": "Dismissing the relevance of this psychological factor to program design"},{"key": "C","text": "Providing clear structure, regular follow-up, and helping the patient recognize the connection between their efforts and outcomes achieved"},{"key": "D","text": "Assuming no adaptation to communication approach is needed regardless of locus of control beliefs"}],"correct": "C","explanation": "Patients with a more external locus of control may benefit from additional structure and support to help build recognition of how their own engagement directly influences their outcomes."},{"id": 4999,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic obstructive pulmonary disease regarding upper extremity exercise?","options": [{"key": "A","text": "Avoiding all upper extremity activity due to dyspnea concerns"},{"key": "B","text": "Assuming upper extremity exercise has no relevance to COPD rehabilitation"},{"key": "C","text": "Incorporating upper extremity strengthening, as arm activities can be particularly dyspnea-provoking in COPD due to accessory muscle demands"},{"key": "D","text": "Only lower extremity exercise should ever be included in COPD programs"}],"correct": "C","explanation": "Upper extremity strengthening is an important component of pulmonary rehabilitation, as arm activities requiring accessory respiratory muscles for stabilization can be particularly dyspnea-provoking in COPD."},{"id": 5000,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for interval versus continuous aerobic training approaches in severely deconditioned pulmonary rehabilitation patients?","options": [{"key": "A","text": "Interval training has no evidence supporting its use in pulmonary rehabilitation"},{"key": "B","text": "Assuming training format has no bearing on patient tolerance or outcomes"},{"key": "C","text": "Interval training (alternating higher and lower intensity periods) may allow better tolerance and higher overall training stimulus in patients unable to sustain continuous higher-intensity exercise"},{"key": "D","text": "Continuous training is always superior regardless of patient tolerance"}],"correct": "C","explanation": "Interval training approaches can allow severely deconditioned patients to achieve higher overall training intensity/stimulus than they could sustain continuously, an important consideration in pulmonary rehabilitation program design."},{"id": 5001,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a tracheostomy regarding exercise participation?","options": [{"key": "A","text": "Assuming tracheostomy presence precludes any exercise participation"},{"key": "B","text": "Coordinating with the medical team regarding tracheostomy care/management while incorporating appropriate exercise as clinically indicated"},{"key": "C","text": "Complete avoidance of any medical team coordination for this population"},{"key": "D","text": "Ignoring any tracheostomy-specific considerations during exercise sessions"}],"correct": "B","explanation": "Patients with tracheostomies can often safely participate in appropriately coordinated exercise programs, requiring collaboration with the medical team regarding tracheostomy-specific care considerations."},{"id": 5002,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from a pneumothorax once medically cleared for activity?","options": [{"key": "A","text": "Complete avoidance of any exercise indefinitely following pneumothorax resolution"},{"key": "B","text": "Assuming no gradual progression approach is needed once medically cleared"},{"key": "C","text": "Immediate return to maximal exertion without any medical clearance consideration"},{"key": "D","text": "Gradual return to activity following medical clearance, with attention to any residual respiratory symptoms during progression"}],"correct": "D","explanation": "Following appropriate medical clearance, gradual return to activity with attention to symptom response is a reasonable approach for patients recovering from pneumothorax."},{"id": 5003,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with hip osteoarthritis regarding aquatic exercise as part of management?","options": [{"key": "A","text": "Aquatic exercise can allow pain-reduced movement and strengthening due to buoyancy, complementing land-based exercise approaches"},{"key": "B","text": "Assuming buoyancy has no relevance to exercise tolerance in this population"},{"key": "C","text": "Aquatic exercise should always replace land-based exercise entirely"},{"key": "D","text": "Aquatic exercise has no evidence supporting its use in hip osteoarthritis management"}],"correct": "A","explanation": "Aquatic exercise's buoyancy-related load reduction can allow hip OA patients to exercise with less pain, often used as a valuable complement to land-based strengthening and aerobic programs."},{"id": 5004,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with shoulder impingement syndrome regarding overhead activity modification during the acute symptomatic phase?","options": [{"key": "A","text": "Encouraging continued unmodified overhead activity despite symptom provocation"},{"key": "B","text": "Temporarily modifying or avoiding provocative overhead positions while addressing underlying strength/mobility impairments"},{"key": "C","text": "Complete avoidance of any shoulder movement indefinitely"},{"key": "D","text": "Assuming activity modification has no role in acute impingement management"}],"correct": "B","explanation": "Temporary modification of symptom-provoking overhead activities, combined with addressing underlying strength and movement impairments, is a standard component of acute shoulder impingement management."},{"id": 5005,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic non-specific low back pain regarding exercise type selection based on current evidence?","options": [{"key": "A","text": "Only one specific exercise type has been proven effective, with all others considered ineffective"},{"key": "B","text": "Exercise therapy has no evidence supporting its use in chronic low back pain"},{"key": "C","text": "A variety of exercise types (general strengthening, aerobic, motor control) show similar effectiveness, suggesting individualized selection based on patient preference/presentation is reasonable"},{"key": "D","text": "Assuming exercise type selection has no bearing on patient adherence or outcomes"}],"correct": "C","explanation": "Current evidence suggests various exercise approaches (general conditioning, motor control training, etc.) show comparable effectiveness for chronic low back pain, supporting individualized selection based on patient factors and preference."},{"id": 5006,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with knee osteoarthritis regarding the relationship between exercise-induced pain and joint damage?","options": [{"key": "A","text": "Some exercise-related discomfort is common and does not necessarily indicate worsening joint damage, though significant pain increases should prompt program review"},{"key": "B","text": "Assuming pain response has no relevance to exercise program monitoring"},{"key": "C","text": "Exercise should never produce any discomfort in osteoarthritic joints"},{"key": "D","text": "All exercise-related pain always indicates progressive joint damage requiring immediate cessation"}],"correct": "A","explanation": "Mild, transient exercise-related discomfort is common in OA rehabilitation and doesn't necessarily indicate harm, though significant or persistent pain increases warrant program reassessment."},{"id": 5007,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from a total ankle arthroplasty?","options": [{"key": "A","text": "Following a structured, surgeon-guided protocol progressing from protected weight-bearing to functional strengthening and gait training"},{"key": "B","text": "Assuming this procedure requires no distinct protocol from a standard ankle sprain"},{"key": "C","text": "Immediate unrestricted high-impact activity following surgery"},{"key": "D","text": "Complete non-weight-bearing indefinitely regardless of the healing timeline"}],"correct": "A","explanation": "Total ankle arthroplasty rehabilitation follows a carefully staged protocol addressing the specific surgical healing requirements, progressing systematically from protected loading to full functional activity."},{"id": 5008,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed rotator cuff arthropathy (cuff tear with associated arthritis)?","options": [{"key": "A","text": "Complete avoidance of any shoulder exercise regardless of functional goals"},{"key": "B","text": "Assuming combined pathology has no bearing on treatment approach modification"},{"key": "C","text": "Standard rotator cuff repair protocols apply without modification"},{"key": "D","text": "Addressing functional strengthening within the patient's available range and tolerance, often with modified goals given the combined pathology"}],"correct": "D","explanation": "Rotator cuff arthropathy represents a complex combined pathology often requiring modified treatment goals and approaches compared to isolated rotator cuff tears or isolated arthritis."},{"id": 5009,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed thoracic outlet syndrome affecting the neurovascular bundle?","options": [{"key": "A","text": "Addressing postural correction, first rib mobility, and scalene/pectoralis minor flexibility as part of a comprehensive conservative approach"},{"key": "B","text": "Complete avoidance of any exercise intervention for this condition"},{"key": "C","text": "Aggressive strengthening without addressing any postural or flexibility considerations"},{"key": "D","text": "Assuming this condition requires no distinct approach from standard neck pain management"}],"correct": "A","explanation": "Thoracic outlet syndrome management often addresses the specific anatomical factors contributing to neurovascular compression, including posture, first rib position, and relevant muscle flexibility."},{"id": 5010,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed cervical radiculopathy affecting upper extremity strength?","options": [{"key": "A","text": "Assuming the cervical source of symptoms has no bearing on treatment approach"},{"key": "B","text": "Addressing cervical spine mechanics alongside targeted strengthening of the affected myotome, guided by symptom response"},{"key": "C","text": "Complete avoidance of any cervical or upper extremity exercise"},{"key": "D","text": "Only addressing upper extremity strength without any cervical spine consideration"}],"correct": "B","explanation": "Cervical radiculopathy management typically addresses both the cervical spine source of nerve compression and any resulting extremity weakness through targeted, symptom-guided exercise."},{"id": 5011,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with lumbar radiculopathy affecting lower extremity strength and sensation?","options": [{"key": "A","text": "Assuming radicular symptoms require no distinct approach from non-radicular back pain"},{"key": "B","text": "Only addressing lower extremity symptoms without any lumbar spine consideration"},{"key": "C","text": "Addressing lumbar spine mechanics alongside monitoring/addressing any resulting motor or sensory deficits in the affected distribution"},{"key": "D","text": "Complete avoidance of any lumbar or lower extremity exercise"}],"correct": "C","explanation": "Lumbar radiculopathy management addresses both the spinal source of nerve root involvement and any resulting extremity impairments, with careful monitoring of neurological status throughout treatment."},{"id": 5012,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with progressive neurological deficit during a course of conservative treatment for radiculopathy?","options": [{"key": "A","text": "Assuming progressive weakness has no bearing on treatment planning decisions"},{"key": "B","text": "Prompt reassessment and appropriate referral, as progressive neurological deficit may indicate need for more urgent medical/surgical evaluation"},{"key": "C","text": "Ignoring any neurological changes during ongoing conservative management"},{"key": "D","text": "Continuing unmodified conservative treatment regardless of progressive deficit"}],"correct": "B","explanation": "Progressive neurological deficit during conservative radiculopathy treatment is a red flag warranting prompt reassessment and appropriate referral, as this may indicate a need for more urgent intervention."},{"id": 5013,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for return-to-work planning following a musculoskeletal injury with residual functional limitations?","options": [{"key": "A","text": "Assuming return-to-work timing should be based solely on time since injury regardless of functional status"},{"key": "B","text": "Requiring complete resolution of all symptoms before any work-related discussion occurs"},{"key": "C","text": "Ignoring any job-specific demands during rehabilitation planning"},{"key": "D","text": "Collaborative goal-setting considering both the patient's recovery trajectory and specific job demands, potentially including graded work exposure"}],"correct": "D","explanation": "Effective return-to-work planning integrates the patient's functional recovery with specific occupational demands, often incorporating graded exposure strategies to support safe, successful return."},{"id": 5014,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed rotator cuff tear opting for conservative (non-surgical) management?","options": [{"key": "A","text": "Assuming conservative management always requires complete avoidance of any strengthening exercise"},{"key": "B","text": "Complete immobilization of the shoulder as the primary conservative treatment approach"},{"key": "C","text": "Immediate aggressive strengthening regardless of tear size or symptom presentation"},{"key": "D","text": "A structured strengthening program addressing the remaining functional rotator cuff and scapular musculature to optimize function despite the tear"}],"correct": "D","explanation": "Conservative rotator cuff tear management often focuses on optimizing the strength and function of remaining intact rotator cuff and scapular muscles to compensate functionally despite the structural tear."},{"id": 5015,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with degenerative meniscal changes (without acute traumatic tear) and mild symptoms?","options": [{"key": "A","text": "Assuming exercise therapy has no role in degenerative meniscal condition management"},{"key": "B","text": "A trial of strengthening and activity modification is often appropriate before considering more invasive interventions, given the common presence of asymptomatic degenerative changes"},{"key": "C","text": "Immediate surgical referral is required for any identified degenerative meniscal change"},{"key": "D","text": "Complete avoidance of any knee exercise regardless of symptom severity"}],"correct": "B","explanation": "Given the high prevalence of asymptomatic degenerative meniscal changes on imaging, a trial of conservative exercise-based management is often appropriate before considering more invasive options for mild symptoms."},{"id": 5016,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with generalized joint hypermobility (without a specific connective tissue disorder diagnosis) experiencing recurrent minor joint injuries?","options": [{"key": "A","text": "Complete avoidance of any physical activity due to hypermobility"},{"key": "B","text": "Assuming hypermobility has no relevance to exercise program design"},{"key": "C","text": "Encouraging further stretching to increase already-excessive joint range of motion"},{"key": "D","text": "Emphasizing proprioceptive training and controlled strengthening to improve dynamic joint stability and control"}],"correct": "D","explanation": "Generalized joint hypermobility management typically emphasizes proprioceptive and strengthening exercise to improve dynamic control, rather than further increasing the already-excessive passive joint mobility."},{"id": 5017,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed rotator cuff-related shoulder pain (an umbrella term encompassing various cuff pathologies) based on current evidence-informed practice?","options": [{"key": "A","text": "Treatment approach should be based exclusively on specific imaging findings rather than clinical presentation"},{"key": "B","text": "A structured, progressive loading exercise program is generally recommended as a first-line approach regardless of the specific underlying structural finding"},{"key": "C","text": "Complete rest is the preferred first-line treatment approach"},{"key": "D","text": "Surgical intervention should always be pursued before attempting exercise-based management"}],"correct": "B","explanation": "Current evidence-informed practice for rotator cuff-related shoulder pain generally supports structured exercise therapy as an effective first-line approach, often regardless of the specific structural pathology identified on imaging."},{"id": 5018,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed hamstring syndrome (proximal hamstring tendinopathy) involving pain with sitting?","options": [{"key": "A","text": "Activity/positional modification to reduce compressive loading combined with progressive tendon loading exercise"},{"key": "B","text": "Assuming positional factors have no relevance to this condition's management"},{"key": "C","text": "Complete avoidance of any hamstring-related exercise"},{"key": "D","text": "Encouraging prolonged sitting without any modification"}],"correct": "A","explanation": "Proximal hamstring tendinopathy often involves compressive loading sensitivity (e.g., with sitting), making positional modification alongside progressive loading exercise an important management component."},{"id": 5019,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed high ankle sprain (syndesmotic injury) compared to a standard lateral ankle sprain?","options": [{"key": "A","text": "Assuming syndesmotic injuries require no distinct consideration from lateral ligament sprains"},{"key": "B","text": "Identical rehabilitation timeline and approach to standard lateral ankle sprains"},{"key": "C","text": "Typically requires a more prolonged, cautious rehabilitation timeline given the structural differences and healing demands of syndesmotic injuries"},{"key": "D","text": "Immediate return to full activity given the location of injury"}],"correct": "C","explanation": "High ankle (syndesmotic) sprains generally require a more cautious, extended rehabilitation timeline compared to standard lateral ankle sprains, given the different structural considerations and healing demands."},{"id": 5020,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed Achilles tendinopathy with insertional involvement (at the calcaneal attachment)?","options": [{"key": "A","text": "Careful attention to avoiding excessive ankle dorsiflexion stretching, which may aggravate insertional tendinopathy differently than mid-portion tendinopathy"},{"key": "B","text": "Standard mid-portion Achilles tendinopathy protocols apply without any modification"},{"key": "C","text": "Complete avoidance of any calf-related exercise regardless of the specific tendinopathy location"},{"key": "D","text": "Assuming insertional location has no bearing on appropriate exercise modification"}],"correct": "A","explanation": "Insertional Achilles tendinopathy requires modified exercise approach compared to mid-portion tendinopathy, as excessive dorsiflexion stretching may aggravate symptoms at the calcaneal insertion differently."},{"id": 5021,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed medial tibial stress syndrome who continues to have pain despite initial conservative management?","options": [{"key": "A","text": "Assuming persistent symptoms after initial treatment require no further reassessment"},{"key": "B","text": "Continuing unmodified training regardless of persistent symptoms"},{"key": "C","text": "Immediate surgical referral without further conservative reassessment"},{"key": "D","text": "Reassessing training load, biomechanics, and considering further diagnostic workup to rule out progression to stress fracture"}],"correct": "D","explanation": "Persistent MTSS symptoms despite initial conservative management warrant reassessment of contributing factors and consideration of further workup to rule out progression to a stress fracture."},{"id": 5022,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed rotator cuff tear who has significant pseudoparalysis (inability to actively elevate the arm despite passive range being available)?","options": [{"key": "A","text": "Pseudoparalysis has no bearing on prognosis or treatment urgency"},{"key": "B","text": "Assuming pseudoparalysis always resolves with simple passive range of motion exercises alone"},{"key": "C","text": "Standard conservative strengthening protocols apply without any modification"},{"key": "D","text": "This finding often indicates a more extensive tear requiring careful evaluation and potentially more urgent surgical consideration"}],"correct": "D","explanation": "Pseudoparalysis in the context of a rotator cuff tear often signals a more extensive tear pattern, warranting careful evaluation and consideration of more urgent surgical referral given the functional implications."},{"id": 5023,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed greater trochanteric pain syndrome (encompassing trochanteric bursitis and gluteal tendinopathy)?","options": [{"key": "A","text": "Progressive hip abductor loading exercise combined with activity modification to reduce compressive/friction-based irritation"},{"key": "B","text": "Aggressive stretching into hip adduction, which may increase compressive loading"},{"key": "C","text": "Complete avoidance of any hip-related exercise indefinitely"},{"key": "D","text": "Assuming this condition requires no distinct approach from standard hip osteoarthritis"}],"correct": "A","explanation": "GTPS management emphasizes progressive gluteal tendon loading while addressing positions/activities that increase compressive stress on the lateral hip structures, differing from generic hip OA approaches."},{"id": 5024,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed cervical spondylotic myelopathy regarding exercise intensity and type?","options": [{"key": "A","text": "Assuming myelopathy has no bearing on appropriate exercise selection or intensity"},{"key": "B","text": "Standard aggressive cervical range of motion and manipulation techniques apply without modification"},{"key": "C","text": "Complete avoidance of any exercise or movement"},{"key": "D","text": "Cautious approach avoiding high-velocity cervical manipulation/extremes of motion, given the spinal cord involvement, with careful monitoring of neurological status"}],"correct": "D","explanation": "Cervical myelopathy involves spinal cord compression, requiring cautious exercise approaches avoiding high-risk positions/techniques, with vigilant monitoring for any neurological changes."},{"id": 5025,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed lumbar spondylolisthesis (grade I-II) regarding exercise selection?","options": [{"key": "A","text": "Assuming spondylolisthesis grade has no bearing on appropriate exercise approach"},{"key": "B","text": "Complete avoidance of any lumbar spine exercise"},{"key": "C","text": "Encouraging maximal repetitive lumbar extension exercises regardless of symptom response"},{"key": "D","text": "Core stabilization exercises emphasizing segmental control, often avoiding excessive repetitive extension that may aggravate symptoms in some patients"}],"correct": "D","explanation": "Lower-grade spondylolisthesis management often emphasizes core stabilization for segmental control, with attention to individual symptom response regarding extension-based movements that may aggravate some patients."},{"id": 5026,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed facet joint syndrome (lumbar) presenting with extension-provoked pain?","options": [{"key": "A","text": "Assuming facet joint pathology requires no distinct exercise approach from disc-related pain"},{"key": "B","text": "Emphasizing flexion-biased exercises and postural modification to reduce facet joint loading/compression"},{"key": "C","text": "Complete avoidance of any lumbar exercise regardless of directional preference"},{"key": "D","text": "Encouraging maximal repetitive extension exercises despite symptom provocation"}],"correct": "B","explanation": "Facet joint-related pain that is provoked by extension often responds to flexion-biased exercise and postural strategies that reduce compressive loading on the affected facet joints."},{"id": 5027,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed sacroiliac joint dysfunction contributing to low back/buttock pain?","options": [{"key": "A","text": "Assuming SI joint dysfunction requires no distinct approach from generalized low back pain"},{"key": "B","text": "Addressing pelvic stabilization and symmetric muscle activation patterns, potentially combined with SI joint-specific mobility/stability exercises"},{"key": "C","text": "Aggressive manipulation without any exercise-based component"},{"key": "D","text": "Complete avoidance of any pelvic or hip-related exercise"}],"correct": "B","explanation": "SIJ dysfunction management typically addresses pelvic stability and symmetric muscular control patterns, sometimes combined with joint-specific techniques, as part of a comprehensive rehabilitation approach."},{"id": 5028,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed hip osteitis pubis (athletic pubalgia)?","options": [{"key": "A","text": "Progressive core and hip adductor strengthening, along with activity modification, addressing the underlying muscular imbalance contributing to pubic symphysis stress"},{"key": "B","text": "Assuming this condition requires no distinct approach from generalized groin strain"},{"key": "C","text": "Complete avoidance of any core or hip-related exercise"},{"key": "D","text": "Aggressive immediate return to full training regardless of symptom status"}],"correct": "A","explanation": "Athletic pubalgia/osteitis pubis often benefits from a comprehensive approach addressing core and adductor strength imbalances that contribute to excessive pubic symphysis stress during athletic activity."},{"id": 5029,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed rectus femoris strain (direct anterior thigh injury)?","options": [{"key": "A","text": "Standard quadriceps strain protocol without any consideration of the two-joint nature of this muscle"},{"key": "B","text": "Progressive loading addressing both the hip flexion and knee extension functions of this two-joint muscle, given its unique injury/rehabilitation considerations"},{"key": "C","text": "Assuming single-joint muscle strain principles apply identically to this two-joint muscle"},{"key": "D","text": "Complete avoidance of any quadriceps-related exercise"}],"correct": "B","explanation": "Rectus femoris, being a two-joint muscle (crossing both hip and knee), requires rehabilitation consideration of both its hip flexion and knee extension functions, distinct from single-joint vasti muscle strains."},{"id": 5030,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed gluteus medius tear (partial) affecting hip abductor function?","options": [{"key": "A","text": "Assuming standard gluteal strengthening protocols require no modification based on tear severity"},{"key": "B","text": "Complete avoidance of any hip abductor exercise regardless of tear extent"},{"key": "C","text": "Progressive strengthening addressing the specific pattern of weakness, potentially informed by whether conservative or surgical management is pursued"},{"key": "D","text": "Ignoring any distinction between partial and complete tears in treatment planning"}],"correct": "C","explanation": "Gluteus medius tear management is informed by the extent of the tear and whether conservative or surgical management is chosen, with strengthening approaches tailored accordingly."},{"id": 5031,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed biceps tendinopathy (long head) contributing to anterior shoulder pain?","options": [{"key": "A","text": "Assuming biceps tendinopathy occurs in isolation without any relationship to shoulder mechanics"},{"key": "B","text": "Progressive loading of the biceps tendon alongside addressing broader shoulder complex strength/mechanics, particularly the rotator cuff and scapular musculature"},{"key": "C","text": "Aggressive isolated biceps curls without any broader shoulder consideration"},{"key": "D","text": "Complete avoidance of any elbow or shoulder-related exercise"}],"correct": "B","explanation": "Long head biceps tendinopathy often occurs alongside broader shoulder dysfunction, making a comprehensive approach addressing both local tendon loading and overall shoulder mechanics appropriate."},{"id": 5032,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed triceps tendinopathy at the olecranon insertion?","options": [{"key": "A","text": "Progressive loading exercise for the triceps, with attention to any contributing factors such as repetitive elbow extension activities"},{"key": "B","text": "Assuming this less common tendinopathy requires no distinct approach from general elbow pain management"},{"key": "C","text": "Aggressive immediate maximal resistance training regardless of symptom status"},{"key": "D","text": "Complete avoidance of any elbow-related exercise"}],"correct": "A","explanation": "Triceps tendinopathy management follows similar progressive loading principles to other tendinopathies, with attention to activity modification for any identified aggravating repetitive movements."},{"id": 5033,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed extensor carpi ulnaris tendinopathy/subluxation affecting wrist function?","options": [{"key": "A","text": "Complete avoidance of any wrist-related exercise regardless of presentation"},{"key": "B","text": "Standard tennis elbow protocol applies without any distinction for this specific tendon involvement"},{"key": "C","text": "Assuming tendon subluxation has no bearing on appropriate treatment approach"},{"key": "D","text": "Addressing wrist stabilization and progressive strengthening while considering any structural instability that may require different management approach"}],"correct": "D","explanation": "ECU tendinopathy/subluxation requires distinct consideration from lateral epicondylalgia, particularly regarding any structural instability that may influence the appropriate treatment and exercise approach."},{"id": 5034,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed anterior tibial tendinopathy affecting ankle dorsiflexion function?","options": [{"key": "A","text": "Progressive loading of the anterior tibialis alongside addressing any contributing biomechanical/training factors"},{"key": "B","text": "Aggressive resistance training immediately regardless of symptom presentation"},{"key": "C","text": "Assuming anterior tibial tendinopathy is identical in management to posterior tibial tendon dysfunction"},{"key": "D","text": "Complete avoidance of any ankle-related exercise"}],"correct": "A","explanation": "Anterior tibialis tendinopathy management follows progressive tendon loading principles, distinct from posterior tibial tendon dysfunction given the different functional role of this muscle in ankle dorsiflexion."},{"id": 5035,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed flexor hallucis longus tendinopathy (common in dancers) affecting great toe flexion?","options": [{"key": "A","text": "Assuming this condition has no relationship to specific activity demands like dance positions"},{"key": "B","text": "Standard plantar fasciitis protocol applies without any distinction for this specific tendon"},{"key": "C","text": "Complete avoidance of any foot-related exercise regardless of the specific diagnosis"},{"key": "D","text": "Addressing tendon loading progression alongside any contributing biomechanical factors specific to the patient's activity (e.g., dance positions)"}],"correct": "D","explanation": "FHL tendinopathy, common in dancers due to repetitive demi-pointe positions, requires attention to both general tendon loading principles and the specific biomechanical demands of the causative activity."},{"id": 5036,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed adductor longus tendinopathy in a soccer player?","options": [{"key": "A","text": "Assuming kicking technique has no relationship to this common soccer-related injury"},{"key": "B","text": "Immediate unrestricted return to full training regardless of loading progression"},{"key": "C","text": "Progressive adductor loading program, often incorporating both isometric and dynamic exercises, alongside addressing any contributing kicking technique factors"},{"key": "D","text": "Complete avoidance of any adductor-related exercise or soccer participation"}],"correct": "C","explanation": "Adductor tendinopathy in soccer players benefits from progressive loading programs combined with attention to kicking technique and training load factors that may have contributed to the condition."},{"id": 5037,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed quadratus lumborum strain contributing to unilateral low back pain?","options": [{"key": "A","text": "Aggressive contralateral stretching regardless of symptom response"},{"key": "B","text": "Complete avoidance of any trunk-related exercise"},{"key": "C","text": "Assuming this condition requires no distinct approach from generalized low back pain"},{"key": "D","text": "Addressing lateral trunk stability and flexibility, along with identifying any contributing movement/postural factors"}],"correct": "D","explanation": "Quadratus lumborum-related pain often benefits from addressing lateral trunk stability and flexibility, along with identifying and modifying contributing movement or postural patterns."},{"id": 5038,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed levator scapulae strain contributing to neck/upper back pain?","options": [{"key": "A","text": "Aggressive isolated stretching without any postural or scapular consideration"},{"key": "B","text": "Complete avoidance of any cervical or scapular exercise"},{"key": "C","text": "Addressing scapular positioning and cervical/upper back postural factors alongside appropriate stretching and strengthening"},{"key": "D","text": "Assuming this condition requires no distinct approach from generalized cervical pain"}],"correct": "C","explanation": "Levator scapulae-related pain often responds to a combined approach addressing scapular positioning, postural factors, and targeted stretching/strengthening of the affected region."},{"id": 5039,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed serratus anterior strain/weakness contributing to scapular winging?","options": [{"key": "A","text": "Ignoring any potential nerve involvement in cases of scapular winging"},{"key": "B","text": "Assuming all scapular winging cases require identical treatment regardless of etiology"},{"key": "C","text": "Complete avoidance of any scapular exercise regardless of the underlying cause"},{"key": "D","text": "Progressive serratus anterior strengthening exercises (e.g., push-up plus variations) alongside addressing any contributing nerve involvement (e.g., long thoracic nerve)"}],"correct": "D","explanation": "Serratus anterior weakness/winging management should consider the underlying etiology (muscular vs. nerve-related, e.g., long thoracic nerve palsy) alongside progressive strengthening exercises targeting this muscle."},{"id": 5040,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed cervical facet joint syndrome contributing to neck pain and stiffness?","options": [{"key": "A","text": "Addressing cervical mobility and postural strengthening while considering positions/movements that provoke symptoms"},{"key": "B","text": "Complete avoidance of any cervical spine exercise"},{"key": "C","text": "Assuming cervical facet syndrome requires no distinct approach from cervical disc-related pain"},{"key": "D","text": "Aggressive high-velocity manipulation as the sole treatment approach"}],"correct": "A","explanation": "Cervical facet-related pain often benefits from a combined approach of mobility exercise and postural strengthening, with attention to specific movement directions that provoke symptoms."},{"id": 5041,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed occipital neuralgia contributing to headache symptoms?","options": [{"key": "A","text": "Assuming this condition has no relationship to cervical spine factors"},{"key": "B","text": "Addressing upper cervical mobility and posture, along with suboccipital muscle tension, as part of a comprehensive approach"},{"key": "C","text": "Aggressive stretching regardless of symptom provocation"},{"key": "D","text": "Complete avoidance of any cervical spine exercise or intervention"}],"correct": "B","explanation": "Occipital neuralgia is often related to upper cervical spine and suboccipital muscle factors, making mobility and tension-reduction exercises a relevant component of comprehensive management."},{"id": 5042,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed cervicogenic headache?","options": [{"key": "A","text": "Assuming cervicogenic headaches have no relationship to cervical spine dysfunction"},{"key": "B","text": "Addressing upper cervical spine mobility/strength alongside postural correction, given the cervical spine origin of these headaches"},{"key": "C","text": "Standard migraine management protocols apply without any cervical spine consideration"},{"key": "D","text": "Complete avoidance of any exercise-based intervention for headache management"}],"correct": "B","explanation": "Cervicogenic headaches originate from cervical spine dysfunction, making targeted upper cervical mobility, strengthening, and postural correction exercises an appropriate physiotherapy-based management approach."},{"id": 5043,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed jaw clenching/bruxism contributing to TMJ and cervical muscle tension?","options": [{"key": "A","text": "Aggressive forceful jaw manipulation regardless of the underlying behavioral component"},{"key": "B","text": "Assuming bruxism has no relationship to musculoskeletal tension patterns"},{"key": "C","text": "Complete avoidance of any jaw or cervical exercise"},{"key": "D","text": "Addressing relaxation techniques, postural awareness, and gentle jaw/cervical mobility exercises as part of a comprehensive approach"}],"correct": "D","explanation": "Bruxism-related tension often benefits from a combined approach of relaxation strategies, postural awareness, and gentle mobility exercises addressing both jaw and cervical regions."},{"id": 5044,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed costovertebral joint dysfunction contributing to thoracic/rib pain?","options": [{"key": "A","text": "Assuming this condition requires no distinct approach from generalized chest pain"},{"key": "B","text": "Aggressive forceful manipulation without any exercise-based component"},{"key": "C","text": "Complete avoidance of any thoracic spine or rib-related exercise"},{"key": "D","text": "Addressing thoracic spine and rib mobility through targeted exercise and breathing techniques"}],"correct": "D","explanation": "Costovertebral joint dysfunction often responds to targeted mobility exercises addressing the thoracic spine and rib articulations, sometimes combined with specific breathing techniques."},{"id": 5045,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed slipping rib syndrome contributing to lower rib pain?","options": [{"key": "A","text": "Complete avoidance of any trunk-related exercise"},{"key": "B","text": "Assuming this uncommon condition requires no specific exercise therapy consideration"},{"key": "C","text": "Aggressive stretching of the affected rib region regardless of symptom provocation"},{"key": "D","text": "Addressing core/trunk stability alongside activity modification to reduce provocative movements affecting the hypermobile rib cartilage"}],"correct": "D","explanation": "Slipping rib syndrome, involving hypermobility of lower rib cartilage, often benefits from core stability work and activity modification addressing movements that provoke the abnormal rib motion."},{"id": 5046,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed wrist ganglion cyst affecting range of motion?","options": [{"key": "A","text": "Complete avoidance of any wrist-related exercise"},{"key": "B","text": "Gentle range of motion exercises within comfortable limits, with definitive treatment often being medical/surgical if significantly symptomatic"},{"key": "C","text": "Aggressive forceful stretching to attempt to rupture the cyst"},{"key": "D","text": "Assuming exercise therapy is the definitive treatment for symptomatic ganglion cysts"}],"correct": "B","explanation": "Ganglion cysts are typically managed with gentle mobility exercise for associated stiffness, while definitive treatment for significantly symptomatic cysts is often medical or surgical intervention."},{"id": 5047,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed intersection syndrome (wrist tendinopathy at the crossing point of certain forearm tendons)?","options": [{"key": "A","text": "Standard De Quervain's protocol applies without any distinction for this different condition"},{"key": "B","text": "Complete avoidance of any wrist-related exercise regardless of the specific diagnosis"},{"key": "C","text": "Activity modification and progressive loading similar to other tendinopathies, along with addressing repetitive wrist movements that may have contributed"},{"key": "D","text": "Assuming this condition requires no activity modification consideration"}],"correct": "C","explanation": "Intersection syndrome, while anatomically distinct from De Quervain's tenosynovitis, follows similar general tendinopathy management principles of activity modification and progressive loading."},{"id": 5048,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed thumb basal joint (CMC) osteoarthritis affecting pinch/grip function?","options": [{"key": "A","text": "Joint protection strategies combined with intrinsic hand muscle strengthening and appropriate splinting as indicated"},{"key": "B","text": "Complete avoidance of any hand-related exercise"},{"key": "C","text": "Assuming joint protection has no relevance to this condition's management"},{"key": "D","text": "Aggressive forceful thumb range of motion exercises regardless of pain"}],"correct": "A","explanation": "Thumb CMC osteoarthritis management typically combines joint protection education, targeted strengthening, and appropriate splinting to support functional pinch and grip activities."},{"id": 5049,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed lateral plantar nerve entrapment (Baxter's nerve) contributing to heel pain?","options": [{"key": "A","text": "Considering this differential in cases of persistent heel pain not responding to standard plantar fasciitis treatment, with nerve-specific management approaches as indicated"},{"key": "B","text": "Ignoring nerve entrapment as a potential cause of persistent heel pain"},{"key": "C","text": "Assuming all heel pain is plantar fasciitis requiring identical treatment"},{"key": "D","text": "Complete avoidance of any foot-related exercise regardless of the underlying diagnosis"}],"correct": "A","explanation": "Baxter's nerve entrapment should be considered in cases of heel pain unresponsive to standard plantar fasciitis management, requiring a different, nerve-focused treatment approach."},{"id": 5050,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed tarsal tunnel syndrome affecting foot sensation and function?","options": [{"key": "A","text": "Complete avoidance of any exercise-based intervention for this condition"},{"key": "B","text": "Assuming nerve gliding exercises have no role in peripheral nerve entrapment management"},{"key": "C","text": "Standard plantar fasciitis protocol applies without any distinction for this nerve-related condition"},{"key": "D","text": "Addressing nerve mobility/gliding exercises alongside identifying and modifying any contributing compressive factors"}],"correct": "D","explanation": "Tarsal tunnel syndrome, involving posterior tibial nerve compression, may benefit from nerve mobility exercises alongside addressing any identifiable compressive factors contributing to the entrapment."},{"id": 5051,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed sinus tarsi syndrome contributing to lateral ankle/hindfoot pain?","options": [{"key": "A","text": "Complete avoidance of any ankle or hindfoot exercise"},{"key": "B","text": "Standard lateral ankle sprain protocol applies without any distinction for this specific syndrome"},{"key": "C","text": "Assuming sinus tarsi syndrome has no relationship to previous ankle injury history"},{"key": "D","text": "Addressing hindfoot/subtalar joint mechanics and proprioception, often related to previous ankle sprain history"}],"correct": "D","explanation": "Sinus tarsi syndrome often develops following ankle sprain and involves subtalar joint dysfunction, making hindfoot mechanics and proprioceptive training relevant components of management."},{"id": 5052,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed os trigonum syndrome (posterior ankle impingement) affecting plantarflexion?","options": [{"key": "A","text": "Standard anterior ankle impingement protocol applies without distinction for this posterior condition"},{"key": "B","text": "Complete avoidance of any ankle-related exercise"},{"key": "C","text": "Aggressive forceful plantarflexion stretching regardless of pain provocation"},{"key": "D","text": "Addressing posterior ankle mobility within pain-free limits alongside activity modification, given the bony impingement mechanism"}],"correct": "D","explanation": "Posterior ankle impingement from an os trigonum requires careful management avoiding excessive provocative plantarflexion, differing from anterior impingement which is provoked by dorsiflexion."},{"id": 5053,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed anterior ankle impingement affecting dorsiflexion?","options": [{"key": "A","text": "Aggressive forceful dorsiflexion stretching regardless of pain provocation"},{"key": "B","text": "Addressing ankle mobility within tolerable limits alongside strengthening, given the bony/soft tissue impingement provoked by dorsiflexion"},{"key": "C","text": "Complete avoidance of any ankle-related exercise"},{"key": "D","text": "Assuming this condition is identical in presentation and management to posterior impingement"}],"correct": "B","explanation": "Anterior ankle impingement is provoked by dorsiflexion (opposite to posterior impingement), requiring careful, graded mobility approaches that respect this specific movement-related symptom pattern."},{"id": 5054,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed peroneal tendon subluxation affecting lateral ankle stability?","options": [{"key": "A","text": "Standard ankle sprain protocol applies without any distinction for tendon subluxation"},{"key": "B","text": "Complete avoidance of any peroneal-related exercise"},{"key": "C","text": "Assuming subluxation always resolves with conservative exercise alone regardless of severity"},{"key": "D","text": "Addressing peroneal strengthening and proprioception while considering any structural instability that may warrant surgical evaluation"}],"correct": "D","explanation": "Peroneal tendon subluxation requires distinct consideration from simple ankle sprain, as significant structural instability may require surgical evaluation alongside conservative strengthening approaches."},{"id": 5055,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed meralgia paresthetica affecting anterolateral thigh sensation?","options": [{"key": "A","text": "Addressing any contributing compressive factors (e.g., tight clothing, obesity) alongside nerve gliding exercises as appropriate"},{"key": "B","text": "Aggressive strengthening exercise as the primary treatment approach"},{"key": "C","text": "Assuming this sensory nerve condition requires identical management to a motor nerve injury"},{"key": "D","text": "Complete avoidance of any exercise-based intervention for this condition"}],"correct": "A","explanation": "Meralgia paresthetica, involving lateral femoral cutaneous nerve compression, often benefits from addressing contributing compressive factors alongside appropriate nerve mobility techniques."},{"id": 5056,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed obturator nerve entrapment contributing to groin pain in athletes?","options": [{"key": "A","text": "Considering this differential in cases of exercise-induced groin pain with sensory symptoms, with nerve-specific management as indicated"},{"key": "B","text": "Ignoring nerve entrapment as a potential cause of athletic groin pain"},{"key": "C","text": "Assuming standard groin strain protocols apply without any nerve-specific consideration"},{"key": "D","text": "Complete avoidance of any exercise-based intervention regardless of the specific diagnosis"}],"correct": "A","explanation": "Obturator nerve entrapment should be considered in athletes with groin pain accompanied by sensory symptoms, warranting a nerve-specific management approach distinct from simple muscular groin strain."},{"id": 5057,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed ilioinguinal nerve entrapment following abdominal/inguinal surgery?","options": [{"key": "A","text": "Addressing scar mobility and nerve gliding techniques alongside gradual return to functional activity"},{"key": "B","text": "Aggressive stretching regardless of symptom provocation"},{"key": "C","text": "Complete avoidance of any exercise-based intervention for post-surgical nerve entrapment"},{"key": "D","text": "Assuming post-surgical nerve entrapment requires no distinct consideration from standard post-operative rehabilitation"}],"correct": "A","explanation": "Post-surgical ilioinguinal nerve entrapment may benefit from scar tissue mobility work and nerve gliding techniques, integrated within the broader post-operative rehabilitation progression."},{"id": 5058,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed suprascapular nerve entrapment affecting shoulder external rotation/abduction strength?","options": [{"key": "A","text": "Assuming nerve entrapment has no bearing on appropriate exercise selection"},{"key": "B","text": "Standard rotator cuff tear protocol applies without any distinction for this nerve-related weakness pattern"},{"key": "C","text": "Complete avoidance of any shoulder-related exercise"},{"key": "D","text": "Addressing the specific pattern of infraspinatus/supraspinatus weakness while considering the underlying compressive etiology (e.g., ganglion cyst, repetitive overhead activity)"}],"correct": "D","explanation": "Suprascapular nerve entrapment produces a specific weakness pattern requiring consideration of the underlying compressive cause alongside targeted strengthening of the affected muscles."},{"id": 5059,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed axillary nerve injury following shoulder dislocation, affecting deltoid function?","options": [{"key": "A","text": "Immediate maximal deltoid resistance training regardless of nerve recovery status"},{"key": "B","text": "Assuming nerve injury has no bearing on appropriate exercise timing or progression"},{"key": "C","text": "Complete avoidance of any shoulder exercise throughout the recovery period"},{"key": "D","text": "Addressing deltoid strengthening as reinnervation occurs, following appropriate nerve recovery timelines, alongside maintaining shoulder mobility"}],"correct": "D","explanation": "Axillary nerve injury following shoulder dislocation requires monitoring for reinnervation signs before introducing targeted deltoid strengthening, while maintaining passive/active-assisted mobility during the recovery period."},{"id": 5060,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed long thoracic nerve palsy affecting serratus anterior function and causing scapular winging?","options": [{"key": "A","text": "Assuming this nerve palsy requires no distinct rehabilitation approach from other causes of scapular winging"},{"key": "B","text": "Complete avoidance of any scapular exercise throughout the recovery process"},{"key": "C","text": "Immediate maximal strengthening regardless of nerve recovery status"},{"key": "D","text": "Progressive serratus anterior strengthening as reinnervation allows, alongside scapular support strategies (e.g., taping) during the recovery period"}],"correct": "D","explanation": "Long thoracic nerve palsy requires a recovery-timeline-appropriate approach to serratus anterior strengthening, often combined with scapular support strategies to manage functional limitations during the reinnervation period."},{"id": 5061,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed spinal accessory nerve injury (e.g., following neck surgery) affecting trapezius function?","options": [{"key": "A","text": "Progressive trapezius strengthening as reinnervation allows, addressing the resulting scapular dysfunction and shoulder mechanics"},{"key": "B","text": "Assuming this nerve injury has no functional impact requiring rehabilitation"},{"key": "C","text": "Immediate maximal resistance training regardless of nerve recovery status"},{"key": "D","text": "Complete avoidance of any shoulder/scapular exercise throughout recovery"}],"correct": "A","explanation": "Spinal accessory nerve injury affecting trapezius function requires a recovery-timeline-appropriate strengthening approach addressing the resulting scapular and shoulder mechanical alterations."},{"id": 5062,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed radial nerve palsy following humeral shaft fracture, affecting wrist/finger extension?","options": [{"key": "A","text": "Assuming this common fracture-associated nerve injury requires no specific rehabilitation consideration"},{"key": "B","text": "Immediate maximal wrist extensor strengthening regardless of nerve status"},{"key": "C","text": "Complete avoidance of any hand/wrist positioning or exercise intervention"},{"key": "D","text": "Wrist support/splinting combined with maintaining passive range while monitoring for reinnervation signs before introducing active strengthening"}],"correct": "D","explanation": "Radial nerve palsy following humeral fracture requires supportive splinting to prevent overstretching of denervated extensors, combined with appropriate monitoring and progressive strengthening as reinnervation occurs."},{"id": 5063,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed anterior interosseous nerve syndrome affecting specific thumb/finger flexion?","options": [{"key": "A","text": "Complete avoidance of any hand-related exercise regardless of the specific presentation"},{"key": "B","text": "Standard carpal tunnel syndrome protocol applies without any distinction for this different nerve branch involvement"},{"key": "C","text": "Assuming immediate surgical intervention is always required for this condition"},{"key": "D","text": "Addressing the specific pattern of weakness (thumb IP and index DIP flexion) while monitoring for spontaneous recovery, common in this typically self-limiting condition"}],"correct": "D","explanation": "AIN syndrome produces a distinctive weakness pattern affecting specific thumb/index finger flexion, often resolving spontaneously, requiring monitoring and appropriate exercise as recovery progresses."},{"id": 5064,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed posterior interosseous nerve syndrome affecting finger extension without wrist drop?","options": [{"key": "A","text": "Addressing the specific pattern of finger extensor weakness while monitoring recovery, distinguishing this from more proximal radial nerve palsy affecting wrist extension"},{"key": "B","text": "Assuming this condition always requires identical management to complete radial nerve palsy"},{"key": "C","text": "Complete avoidance of any hand-related exercise regardless of the specific nerve level involved"},{"key": "D","text": "Standard radial nerve palsy protocol with full wrist splinting applies without distinction"}],"correct": "A","explanation": "PIN syndrome affects finger extension while sparing wrist extension (unlike more proximal radial nerve injury), requiring recognition of this distinct pattern to guide appropriate splinting and exercise approach."},{"id": 5065,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed pronator teres syndrome affecting median nerve function proximally in the forearm?","options": [{"key": "A","text": "Addressing the specific proximal median nerve compression pattern, which may present differently from carpal tunnel syndrome, guiding targeted intervention"},{"key": "B","text": "Assuming this condition requires no differentiation from distal median nerve compression"},{"key": "C","text": "Complete avoidance of any forearm-related exercise regardless of presentation"},{"key": "D","text": "Standard carpal tunnel syndrome splinting and exercise protocol applies without any distinction"}],"correct": "A","explanation": "Pronator teres syndrome involves proximal median nerve compression with potentially different symptom patterns than carpal tunnel syndrome, requiring appropriate differentiation to guide targeted treatment."},{"id": 5066,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed cubital tunnel syndrome with associated intrinsic hand muscle weakness?","options": [{"key": "A","text": "Assuming intrinsic muscle weakness requires no specific rehabilitation consideration"},{"key": "B","text": "Addressing ulnar nerve gliding, elbow positioning modification, and progressive intrinsic muscle strengthening as recovery allows"},{"key": "C","text": "Complete avoidance of any elbow or hand-related exercise"},{"key": "D","text": "Standard carpal tunnel protocol applies without any distinction for this different nerve entrapment location"}],"correct": "B","explanation": "Cubital tunnel syndrome management addresses ulnar nerve mobility and elbow positioning factors, along with progressive strengthening of affected intrinsic hand muscles as nerve function recovers."},{"id": 5067,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a heart transplant recipient during cardiac rehabilitation, given the denervated heart's altered response to exercise?","options": [{"key": "A","text": "Complete avoidance of any exercise-based rehabilitation following transplant"},{"key": "B","text": "Using standard target heart rate zones without any modification"},{"key": "C","text": "Relying more heavily on RPE rather than target heart rate zones, since the denervated heart shows a blunted/delayed heart rate response to exercise"},{"key": "D","text": "Assuming transplant recipients require no distinct monitoring approach from other cardiac patients"}],"correct": "C","explanation": "The denervated transplanted heart lacks normal autonomic nervous system control, causing a blunted and delayed heart rate response to exercise, making RPE-based monitoring particularly important in this population."},{"id": 5068,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with congenital heart disease (repaired) participating in an exercise program as an adult?","options": [{"key": "A","text": "Complete avoidance of any exercise regardless of successful repair"},{"key": "B","text": "Standard exercise prescription without any consideration of the specific congenital condition"},{"key": "C","text": "Individualized exercise prescription informed by the specific cardiac lesion, repair type, and any residual hemodynamic considerations, often with cardiology guidance"},{"key": "D","text": "Assuming all congenital heart conditions require identical exercise restrictions"}],"correct": "C","explanation": "Adults with repaired congenital heart disease require individualized exercise guidance considering their specific cardiac anatomy, repair, and any residual issues, often necessitating cardiology input."},{"id": 5069,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with hypertrophic cardiomyopathy regarding competitive/vigorous athletic participation?","options": [{"key": "A","text": "Complete avoidance of any physical activity regardless of intensity level"},{"key": "B","text": "Assuming this diagnosis has no bearing on appropriate exercise intensity recommendations"},{"key": "C","text": "Generally requiring cardiology clearance and often significant restriction from high-intensity competitive sports given the risk of exercise-related sudden cardiac events"},{"key": "D","text": "Standard unrestricted athletic participation without any cardiology involvement"}],"correct": "C","explanation": "HCM carries elevated risk of exercise-related sudden cardiac events, generally warranting cardiology-guided restriction from high-intensity competitive athletics, though moderate activity may be appropriate for some patients."},{"id": 5070,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a history of aortic valve replacement (mechanical valve) on long-term anticoagulation, regarding exercise participation?","options": [{"key": "A","text": "Standard exercise participation is generally appropriate with awareness of bleeding risk during high-impact/contact activities, similar to other anticoagulated patients"},{"key": "B","text": "Immediate high-intensity contact sport participation without any precaution"},{"key": "C","text": "Complete avoidance of any exercise due to the mechanical valve"},{"key": "D","text": "Assuming anticoagulation has no bearing on appropriate activity selection"}],"correct": "A","explanation": "Patients with mechanical valves on anticoagulation can generally participate in regular exercise, with the same bleeding risk precautions regarding high-impact/contact activities as other anticoagulated patients."},{"id": 5071,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed patent foramen ovale (PFO) regarding exercise-related risk, particularly with certain activities?","options": [{"key": "A","text": "Complete avoidance of any exercise due to this common finding"},{"key": "B","text": "Being aware of a potential (though generally low) association with certain conditions during activities involving significant Valsalva or pressure changes (e.g., deep diving), though standard exercise is not typically restricted"},{"key": "C","text": "Requiring cardiology clearance before any form of physical activity regardless of activity type"},{"key": "D","text": "Assuming PFO has significant bearing on standard land-based exercise prescription"}],"correct": "B","explanation": "PFO is a relatively common finding with minimal impact on standard exercise participation, though awareness of specific activities involving significant pressure changes (like diving) may be relevant in certain contexts."},{"id": 5072,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed bicuspid aortic valve regarding exercise intensity and type?","options": [{"key": "A","text": "Complete avoidance of any exercise regardless of associated aortic findings"},{"key": "B","text": "Standard exercise prescription without any consideration of this valve variant"},{"key": "C","text": "Individualized guidance based on associated aortic dimensions/function, often with cardiology input regarding appropriate intensity limits"},{"key": "D","text": "Assuming bicuspid valve has no bearing on appropriate exercise guidance"}],"correct": "C","explanation": "Bicuspid aortic valve can be associated with aortic dilation, requiring individualized, often cardiology-guided exercise recommendations based on the specific aortic dimensions and valve function."},{"id": 5073,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with alpha-1 antitrypsin deficiency-related emphysema regarding exercise programming?","options": [{"key": "A","text": "Assuming this genetic form of emphysema requires no pulmonary rehabilitation involvement"},{"key": "B","text": "Complete avoidance of any exercise regardless of the specific emphysema etiology"},{"key": "C","text": "Standard exercise prescription without any consideration of the underlying genetic cause"},{"key": "D","text": "Following similar pulmonary rehabilitation principles to other emphysema patients, with awareness of the potentially earlier onset and progression seen in this genetic condition"}],"correct": "D","explanation": "While the general pulmonary rehabilitation approach is similar, awareness of the potentially earlier onset and different progression pattern of alpha-1 antitrypsin deficiency-related emphysema is a relevant clinical consideration."},{"id": 5074,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with pulmonary arterial hypertension regarding supervised exercise program structure?","options": [{"key": "A","text": "Assuming this condition requires no specific exercise program modification"},{"key": "B","text": "Standard unsupervised community exercise programs are appropriate"},{"key": "C","text": "Complete avoidance of any exercise regardless of disease severity or specialized program availability"},{"key": "D","text": "Very carefully monitored, low-intensity exercise programs, often within specialized settings given the significant risk profile of this condition"}],"correct": "D","explanation": "Pulmonary arterial hypertension carries significant risk with exertion, generally requiring carefully monitored, low-intensity exercise programs often within specialized supervised settings."},{"id": 5075,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with bronchopulmonary dysplasia (a chronic lung condition originating in premature infancy) as they grow into childhood/adolescence?","options": [{"key": "A","text": "Age-appropriate exercise programming with awareness of potentially reduced pulmonary reserve, guided by ongoing pulmonary assessment"},{"key": "B","text": "Standard adult pulmonary rehabilitation protocols apply without pediatric modification"},{"key": "C","text": "Complete avoidance of any physical activity throughout childhood"},{"key": "D","text": "Assuming this condition resolves completely with no bearing on later exercise capacity"}],"correct": "A","explanation": "Children with a history of bronchopulmonary dysplasia may have some degree of ongoing reduced pulmonary reserve, requiring age-appropriate exercise programming informed by their evolving respiratory status."},{"id": 5076,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an older adult with moderate dementia regarding exercise program structure?","options": [{"key": "A","text": "Complete avoidance of any physical activity for this population"},{"key": "B","text": "Complex, novel exercise routines requiring significant learning and memory"},{"key": "C","text": "Simple, repetitive, familiar exercises with consistent routine and appropriate supervision, adapted to the patient's cognitive capacity"},{"key": "D","text": "Assuming exercise participation is not possible or beneficial once dementia progresses to a moderate stage"}],"correct": "C","explanation": "Exercise programming for moderate dementia should emphasize simplicity, familiarity, and routine, adapted to support safe and effective participation despite cognitive limitations, as exercise remains beneficial in this population."},{"id": 5077,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for an older adult experiencing sundowning (increased confusion/agitation in late afternoon/evening) regarding exercise session timing?","options": [{"key": "A","text": "Scheduling exercise sessions earlier in the day when cognitive status and participation may be more optimal"},{"key": "B","text": "Scheduling all exercise sessions in the late afternoon/evening regardless of sundowning pattern"},{"key": "C","text": "Assuming timing of exercise sessions has no relevance to patients experiencing sundowning"},{"key": "D","text": "Complete avoidance of any exercise programming for patients with this symptom pattern"}],"correct": "A","explanation": "Given the pattern of increased confusion/agitation later in the day with sundowning, scheduling exercise sessions earlier when the patient's cognitive status is typically better may support more effective participation."},{"id": 5078,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for an older adult with significant hearing impairment participating in a group exercise class?","options": [{"key": "A","text": "Using visual demonstration, appropriate positioning for lip-reading, and written/visual instructional aids alongside verbal cues"},{"key": "B","text": "Excluding patients with hearing impairment from group exercise participation entirely"},{"key": "C","text": "Relying exclusively on verbal instruction without any visual demonstration"},{"key": "D","text": "Assuming hearing impairment has no bearing on exercise instruction approach"}],"correct": "A","explanation": "Adapting instructional approaches with visual demonstration and appropriate positioning supports safe, effective exercise participation for patients with hearing impairment in group settings."},{"id": 5079,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with generalized deconditioning following a prolonged hospital stay (unrelated to a specific primary diagnosis)?","options": [{"key": "A","text": "Assuming deconditioning from hospitalization requires no specific rehabilitation approach"},{"key": "B","text": "Complete avoidance of any exercise following prolonged hospitalization"},{"key": "C","text": "Immediate return to pre-hospitalization activity level regardless of the deconditioning that occurred"},{"key": "D","text": "Gradual, systematic reconditioning addressing cardiovascular endurance, strength, and functional mobility, starting from the patient's current baseline capacity"}],"correct": "D","explanation": "Post-hospitalization deconditioning is a common and significant issue requiring systematic, graded reconditioning addressing multiple domains of physical function, tailored to the patient's current capacity."},{"id": 5080,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with ICU-acquired weakness following a prolonged critical illness stay?","options": [{"key": "A","text": "Gradual, progressive strengthening and functional mobility training, often beginning even before ICU discharge when appropriate"},{"key": "B","text": "Complete avoidance of any exercise until the patient returns to their pre-illness baseline"},{"key": "C","text": "Immediate maximal resistance training regardless of the severity of critical illness myopathy/neuropathy"},{"key": "D","text": "Assuming full strength recovery occurs spontaneously without any targeted intervention"}],"correct": "A","explanation": "ICU-acquired weakness, a significant complication of critical illness, benefits from early and progressive rehabilitation, ideally beginning during the ICU stay when clinically appropriate and continuing through recovery."},{"id": 5081,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from sepsis with associated significant fatigue and weakness?","options": [{"key": "A","text": "Complete avoidance of any exercise programming following sepsis"},{"key": "B","text": "Assuming sepsis recovery requires no specific rehabilitation considerations"},{"key": "C","text": "Immediate aggressive exercise progression regardless of the severity of the preceding illness"},{"key": "D","text": "Gradual, symptom-guided reconditioning program, recognizing the substantial physical deconditioning that often accompanies severe sepsis"}],"correct": "D","explanation": "Post-sepsis recovery often involves significant physical deconditioning requiring a carefully graded, symptom-guided approach to rebuilding strength and endurance."},{"id": 5082,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient recovering from major abdominal surgery regarding core/abdominal exercise progression?","options": [{"key": "A","text": "Complete avoidance of any core-related exercise indefinitely following abdominal surgery"},{"key": "B","text": "Assuming surgical incision healing has no bearing on appropriate core exercise progression"},{"key": "C","text": "Gradual progression of core engagement exercises, avoiding excessive intra-abdominal pressure increases until adequate surgical site healing has occurred"},{"key": "D","text": "Immediate maximal core strengthening regardless of surgical healing status"}],"correct": "C","explanation": "Post-abdominal surgery core exercise progression must respect the healing surgical site, gradually increasing intensity as tissue integrity allows, similar to principles applied after cesarean section or other abdominal procedures."},{"id": 5083,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient following cesarean section delivery regarding early postpartum exercise?","options": [{"key": "A","text": "Gentle pelvic floor and gradual core activation exercises, with more vigorous abdominal exercise delayed until adequate surgical healing"},{"key": "B","text": "Immediate maximal abdominal exercise on the first postpartum day"},{"key": "C","text": "Complete avoidance of any exercise for one full year following cesarean delivery"},{"key": "D","text": "Assuming cesarean delivery requires no distinct exercise progression from vaginal delivery"}],"correct": "A","explanation": "Cesarean section recovery requires respecting the surgical incision healing timeline, with gentler initial exercise progression compared to potentially earlier resumption following uncomplicated vaginal delivery."},{"id": 5084,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with significant postpartum diastasis recti persisting beyond the typical early postpartum period?","options": [{"key": "A","text": "Continued progressive core rehabilitation, potentially with more specific consessment/exercise strategies if the separation remains functionally significant"},{"key": "B","text": "Assuming no further core rehabilitation is beneficial once the early postpartum period has passed"},{"key": "C","text": "Complete avoidance of any core exercise given the persistent separation"},{"key": "D","text": "Assuming diastasis recti always resolves spontaneously without requiring any targeted intervention"}],"correct": "A","explanation": "Persistent diastasis recti may benefit from continued, targeted core rehabilitation approaches, as some degree of separation can persist beyond the earliest postpartum weeks and respond to appropriate exercise intervention."},{"id": 5085,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed vulvodynia affecting pelvic floor muscle function?","options": [{"key": "A","text": "Complete avoidance of any pelvic floor-related exercise intervention"},{"key": "B","text": "Assuming all pelvic floor dysfunction requires identical strengthening-focused treatment"},{"key": "C","text": "Standard pelvic floor strengthening (Kegel) exercises apply without any distinction for this condition"},{"key": "D","text": "Pelvic floor relaxation/down-training techniques rather than strengthening, given the often hypertonic pelvic floor presentation in this condition"}],"correct": "D","explanation": "Vulvodynia is often associated with pelvic floor hypertonicity, making relaxation/down-training techniques more appropriate than standard strengthening (Kegel) exercises typically used for weakness-related conditions."},{"id": 5086,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic pelvic pain syndrome affecting pelvic floor muscle tone?","options": [{"key": "A","text": "Standard Kegel exercises apply universally regardless of the specific muscle tone presentation"},{"key": "B","text": "Complete avoidance of any pelvic floor assessment or intervention"},{"key": "C","text": "Assessment-guided treatment addressing whether the pelvic floor presents with hypertonicity or weakness, as the appropriate exercise approach differs significantly between these presentations"},{"key": "D","text": "Assuming all chronic pelvic pain requires identical pelvic floor strengthening exercises"}],"correct": "C","explanation": "Chronic pelvic pain management requires careful assessment to distinguish hypertonic from weak pelvic floor presentations, as the appropriate exercise approach (relaxation vs. strengthening) differs substantially between these different clinical pictures."},{"id": 5087,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for male patients with pelvic floor dysfunction contributing to chronic prostatitis-like pelvic pain symptoms?","options": [{"key": "A","text": "Standard prostate-focused medical treatment alone without any physiotherapy involvement"},{"key": "B","text": "Assuming pelvic floor physiotherapy is only relevant for female patients"},{"key": "C","text": "Pelvic floor assessment and appropriately targeted intervention (relaxation or strengthening based on findings), recognizing this condition also affects male patients"},{"key": "D","text": "Complete avoidance of any pelvic floor assessment in male patients"}],"correct": "C","explanation": "Male pelvic floor dysfunction, contributing to conditions like chronic pelvic pain syndrome/prostatitis-like symptoms, is an increasingly recognized area where physiotherapy assessment and targeted intervention can provide benefit."},{"id": 5088,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed piriformis syndrome affecting hip external rotator function and causing sciatic-like symptoms?","options": [{"key": "A","text": "Addressing piriformis flexibility, hip strengthening (particularly external rotators/abductors), and correcting contributing postural/movement patterns"},{"key": "B","text": "Complete avoidance of any hip-related exercise"},{"key": "C","text": "Aggressive stretching regardless of symptom provocation"},{"key": "D","text": "Standard lumbar disc herniation protocol applies without any distinction for this different etiology"}],"correct": "A","explanation": "Piriformis syndrome management combines targeted stretching, hip strengthening, and correction of contributing movement patterns, distinct from lumbar disc-related sciatica management."},{"id": 5089,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed hip flexor tendinopathy (iliopsoas) affecting functional hip flexion strength?","options": [{"key": "A","text": "Progressive loading of the iliopsoas tendon, addressing any contributing training/movement factors"},{"key": "B","text": "Assuming hip flexor tendinopathy requires no distinct approach from other tendinopathies"},{"key": "C","text": "Complete avoidance of any hip flexor-related exercise"},{"key": "D","text": "Aggressive immediate maximal resistance training regardless of symptom status"}],"correct": "A","explanation": "Iliopsoas tendinopathy follows general tendinopathy management principles of progressive loading, combined with addressing any training or biomechanical factors contributing to the condition."},{"id": 5090,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed hamstring tendinopathy at the ischial tuberosity insertion (proximal hamstring tendinopathy)?","options": [{"key": "A","text": "Complete avoidance of any hamstring-related exercise"},{"key": "B","text": "Progressive tendon loading avoiding excessive hip flexion/stretch positions that increase compressive load at the insertion, particularly early in treatment"},{"key": "C","text": "Aggressive stretching into deep hip flexion as the primary treatment approach"},{"key": "D","text": "Assuming this condition is identical in management to mid-belly hamstring strain"}],"correct": "B","explanation": "Proximal hamstring tendinopathy requires careful attention to compressive loading positions (like deep hip flexion) that can aggravate the insertional tendon, differing from typical mid-belly hamstring strain management."},{"id": 5091,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed gluteal tendinopathy who has difficulty with side-lying sleep positions due to compressive pain?","options": [{"key": "A","text": "Ignoring sleep positioning considerations entirely"},{"key": "B","text": "Providing positioning advice (e.g., pillow between knees) alongside progressive loading exercise, addressing the compressive nature of this tendinopathy"},{"key": "C","text": "Standard hip osteoarthritis protocol applies without any distinction for this compressive tendinopathy"},{"key": "D","text": "Complete avoidance of any hip-related exercise or positioning advice"}],"correct": "B","explanation": "Gluteal tendinopathy's compressive nature makes side-lying sleep positioning relevant; providing supportive positioning advice alongside progressive loading exercise addresses both symptom management and underlying tissue healing."},{"id": 5092,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed quadriceps tendinopathy affecting knee extension strength?","options": [{"key": "A","text": "Standard patellofemoral pain syndrome protocol applies without any distinction for this tendon-specific condition"},{"key": "B","text": "Progressive loading program similar to patellar tendinopathy management, addressing the proximal quadriceps tendon insertion"},{"key": "C","text": "Aggressive immediate maximal resistance training regardless of symptom status"},{"key": "D","text": "Complete avoidance of any quadriceps-related exercise"}],"correct": "B","explanation": "Quadriceps tendinopathy follows similar progressive loading principles to patellar tendinopathy, though addressing the proximal (quadriceps) rather than distal (patellar) tendon attachment."},{"id": 5093,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed pes anserine bursitis/tendinopathy affecting medial knee function?","options": [{"key": "A","text": "Aggressive stretching regardless of symptom provocation"},{"key": "B","text": "Standard lateral knee pain protocol applies without any distinction for this medial-sided condition"},{"key": "C","text": "Complete avoidance of any knee-related exercise"},{"key": "D","text": "Addressing the combined tendon/bursa pathology through progressive loading and activity modification, often associated with biomechanical factors like genu valgum"}],"correct": "D","explanation": "Pes anserine pathology, often related to biomechanical factors like genu valgum, requires targeted management addressing both the tendon/bursa complex and any contributing lower limb alignment issues."},{"id": 5094,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed popliteus tendinopathy affecting posterolateral knee stability?","options": [{"key": "A","text": "Addressing progressive loading of the popliteus alongside broader knee stability training, given this muscle's role in controlling tibial rotation"},{"key": "B","text": "Aggressive stretching regardless of symptom provocation"},{"key": "C","text": "Standard hamstring strain protocol applies without any distinction for this less common condition"},{"key": "D","text": "Complete avoidance of any knee-related exercise"}],"correct": "A","explanation": "Popliteus tendinopathy, though less common, requires attention to this muscle's specific role in controlling tibial rotation and posterolateral knee stability during rehabilitation."},{"id": 5095,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed fabella syndrome (impingement related to a sesamoid bone behind the knee) affecting posterior knee function?","options": [{"key": "A","text": "Addressing any contributing biomechanical factors alongside appropriate activity modification and progressive exercise as tolerated"},{"key": "B","text": "Aggressive immediate maximal resistance training regardless of symptom status"},{"key": "C","text": "Standard patellar tendinopathy protocol applies without any distinction for this different condition"},{"key": "D","text": "Complete avoidance of any knee-related exercise regardless of symptom severity"}],"correct": "A","explanation": "Fabella syndrome, a less common cause of posterior knee pain, benefits from an individualized approach addressing contributing factors alongside appropriately graded exercise progression."},{"id": 5096,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed plica syndrome (synovial plica irritation) affecting knee function?","options": [{"key": "A","text": "Complete avoidance of any knee-related exercise regardless of conservative treatment response"},{"key": "B","text": "Assuming plica syndrome requires no distinct approach from generalized knee pain"},{"key": "C","text": "Activity modification and progressive strengthening addressing any contributing factors, with surgical referral considered if conservative management is unsuccessful"},{"key": "D","text": "Immediate surgical referral without attempting conservative management first"}],"correct": "C","explanation": "Plica syndrome often responds to conservative management including activity modification and strengthening, with surgical options considered if adequate conservative treatment does not provide sufficient improvement."},{"id": 5097,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed superior labral anterior-posterior (SLAP) lesion managed conservatively, regarding overhead athletic activity?","options": [{"key": "A","text": "Gradual, criteria-based progression through a structured strengthening and interval sport-specific program before full return to overhead activity"},{"key": "B","text": "Immediate unrestricted return to overhead throwing/activity regardless of strength/symptom status"},{"key": "C","text": "Assuming conservative management requires no structured progression protocol"},{"key": "D","text": "Complete avoidance of any shoulder exercise or overhead activity indefinitely"}],"correct": "A","explanation": "Conservative SLAP lesion management for overhead athletes typically follows a structured, criteria-based progression addressing strength and control before returning to sport-specific overhead demands."},{"id": 5098,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed internal impingement of the shoulder (posterosuperior glenoid impingement) common in overhead athletes?","options": [{"key": "A","text": "Addressing posterior shoulder tightness and scapular control alongside appropriate throwing/overhead mechanics modification"},{"key": "B","text": "Aggressive anterior capsule stretching regardless of the posterior-based mechanism"},{"key": "C","text": "Complete avoidance of any shoulder exercise or overhead activity"},{"key": "D","text": "Standard subacromial impingement protocol applies without any distinction for this different impingement mechanism"}],"correct": "A","explanation": "Internal impingement, distinct from subacromial impingement, often relates to posterior capsule tightness and altered throwing mechanics, requiring a different targeted treatment approach."},{"id": 5099,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed multidirectional shoulder instability (as opposed to unidirectional traumatic instability)?","options": [{"key": "A","text": "Immediate surgical referral without attempting conservative strengthening first"},{"key": "B","text": "Assuming multidirectional instability requires identical management to traumatic unidirectional dislocation"},{"key": "C","text": "Complete avoidance of any shoulder exercise regardless of the instability pattern"},{"key": "D","text": "Emphasizing dynamic stabilizer (rotator cuff/scapular) strengthening as a primary conservative treatment approach, given the often atraumatic, ligamentous laxity-related etiology"}],"correct": "D","explanation": "Multidirectional instability, often related to underlying capsular laxity rather than a single traumatic event, typically emphasizes dynamic stabilizer strengthening as the primary conservative treatment approach before considering surgical options."},{"id": 5100,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed scapulothoracic bursitis (snapping scapula syndrome)?","options": [{"key": "A","text": "Assuming this condition requires no distinct approach from generalized shoulder pain"},{"key": "B","text": "Complete avoidance of any scapular-related exercise"},{"key": "C","text": "Addressing scapular mechanics, postural factors, and periscapular muscle balance alongside activity modification"},{"key": "D","text": "Aggressive forceful scapular manipulation regardless of symptom provocation"}],"correct": "C","explanation": "Snapping scapula syndrome often relates to altered scapular mechanics and muscle imbalance, requiring a comprehensive approach addressing these factors alongside appropriate activity modification."},{"id": 5101,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed acromioclavicular joint sprain (mild, Type I-II) regarding early management?","options": [{"key": "A","text": "Relative rest and activity modification followed by progressive range of motion and strengthening as symptoms allow"},{"key": "B","text": "Immediate aggressive strengthening regardless of acute symptom status"},{"key": "C","text": "Assuming AC joint sprains require identical management to glenohumeral dislocation"},{"key": "D","text": "Complete surgical referral required for any AC joint sprain grade"}],"correct": "A","explanation": "Mild AC joint sprains typically respond well to conservative management with relative rest followed by progressive rehabilitation, generally not requiring the more aggressive intervention needed for higher-grade injuries."},{"id": 5102,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed sternoclavicular joint dysfunction affecting shoulder girdle mechanics?","options": [{"key": "A","text": "Aggressive forceful joint manipulation as the sole treatment approach"},{"key": "B","text": "Complete avoidance of any exercise addressing this joint"},{"key": "C","text": "Standard AC joint protocol applies without any distinction for this different articulation"},{"key": "D","text": "Addressing joint mobility and surrounding muscle balance as part of a comprehensive shoulder girdle approach"}],"correct": "D","explanation": "Sternoclavicular joint dysfunction, while less commonly addressed than AC joint issues, benefits from targeted mobility work and surrounding muscle balance as part of comprehensive shoulder girdle rehabilitation."},{"id": 5103,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed radial tunnel syndrome (posterior interosseous nerve compression at the elbow) affecting forearm/wrist function?","options": [{"key": "A","text": "Standard lateral epicondylalgia protocol applies without any distinction, as they can present similarly"},{"key": "B","text": "Assuming radial tunnel syndrome always requires immediate surgical intervention"},{"key": "C","text": "Addressing nerve mobility and identifying/modifying contributing repetitive forearm rotation activities"},{"key": "D","text": "Complete avoidance of any forearm-related exercise regardless of the specific diagnosis"}],"correct": "C","explanation": "Radial tunnel syndrome can mimic lateral epicondylalgia but requires distinct consideration of nerve mobility and repetitive movement factors, as management approach differs from purely tendon-based lateral elbow pain."},{"id": 5104,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed medial epicondyle apophysitis (Little League elbow) in a young throwing athlete?","options": [{"key": "A","text": "Complete permanent cessation of any throwing activity regardless of healing progress"},{"key": "B","text": "Immediate return to full throwing volume regardless of symptom status"},{"key": "C","text": "Activity modification/rest from throwing combined with appropriate strengthening once acute symptoms resolve, given the vulnerable growth plate involved"},{"key": "D","text": "Assuming this pediatric condition requires identical management to adult medial epicondylalgia"}],"correct": "C","explanation": "Little League elbow involves stress on the vulnerable medial epicondyle growth plate in young throwers, requiring activity modification during the acute phase before returning to a carefully progressed throwing program."},{"id": 5105,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed olecranon bursitis affecting elbow function?","options": [{"key": "A","text": "Assuming olecranon bursitis always requires surgical drainage regardless of presentation"},{"key": "B","text": "Aggressive forceful elbow flexion exercises regardless of bursal swelling"},{"key": "C","text": "Addressing any contributing repetitive pressure/trauma factors alongside gentle range of motion exercises as tolerated"},{"key": "D","text": "Complete avoidance of any elbow-related exercise or activity modification advice"}],"correct": "C","explanation": "Olecranon bursitis often responds to addressing contributing pressure/trauma factors alongside gentle exercise, with more invasive intervention reserved for cases not responding to conservative management or with signs of infection."},{"id": 5106,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed elbow flexion contracture following prolonged immobilization?","options": [{"key": "A","text": "Assuming full range of motion will always be restored regardless of contracture duration/severity"},{"key": "B","text": "Progressive stretching and mobilization within tolerable limits, recognizing that full range restoration may require sustained, patient approach given connective tissue changes"},{"key": "C","text": "Aggressive forceful manipulation to immediately restore full range"},{"key": "D","text": "Complete avoidance of any further intervention once a contracture has developed"}],"correct": "B","explanation": "Established elbow contractures often require sustained, progressive stretching approaches, with the degree of ultimate range restoration depending on the underlying contracture severity and chronicity."},{"id": 5107,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed distal biceps tendon rupture managed surgically?","options": [{"key": "A","text": "Complete immobilization indefinitely regardless of surgical repair"},{"key": "B","text": "Immediate maximal resistance training regardless of surgical repair status"},{"key": "C","text": "Assuming this injury requires no distinct rehabilitation approach from proximal biceps tendon issues"},{"key": "D","text": "Following surgeon-specific protocol with protected range of motion progressing to strengthening as the repair heals"}],"correct": "D","explanation": "Distal biceps tendon rupture repair requires a structured, protocol-driven rehabilitation approach protecting the surgical repair before progressive strengthening, similar in principle to other tendon repair rehabilitation."},{"id": 5108,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed triceps tendon rupture managed surgically?","options": [{"key": "A","text": "Following surgeon-specific protocol with protected elbow flexion range before progressive triceps strengthening as healing allows"},{"key": "B","text": "Immediate full active elbow flexion range regardless of surgical repair timeline"},{"key": "C","text": "Complete avoidance of any elbow exercise following this less common injury"},{"key": "D","text": "Assuming triceps tendon rupture requires no protective rehabilitation approach"}],"correct": "A","explanation": "Triceps tendon rupture repair requires protecting the healing tendon by limiting early elbow flexion range (which stresses the repair), before progressive strengthening as tissue healing allows."},{"id": 5109,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed radial head fracture (non-displaced, managed conservatively)?","options": [{"key": "A","text": "Early gentle range of motion exercises to prevent stiffness, as prolonged immobilization increases the risk of significant elbow contracture with this fracture type"},{"key": "B","text": "Immediate aggressive resistance training regardless of fracture stability"},{"key": "C","text": "Assuming this fracture requires identical management to more severe elbow injuries requiring surgery"},{"key": "D","text": "Prolonged strict immobilization for several months to ensure adequate healing"}],"correct": "A","explanation": "Radial head fractures, even when managed conservatively, benefit from relatively early gentle mobilization given the elbow's particular susceptibility to stiffness with prolonged immobilization."},{"id": 5110,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed elbow dislocation (simple, without associated fracture) following closed reduction?","options": [{"key": "A","text": "Complete immobilization for several months regardless of dislocation severity"},{"key": "B","text": "Assuming simple elbow dislocations require no specific rehabilitation protocol"},{"key": "C","text": "Early protected range of motion within a stable arc, progressing as healing allows, to minimize stiffness while protecting the healing ligamentous structures"},{"key": "D","text": "Immediate full unrestricted range of motion on the first day post-reduction"}],"correct": "C","explanation": "Simple elbow dislocations require balancing early protected mobilization (to prevent the elbow's characteristic stiffness tendency) with adequate protection of healing ligamentous structures during the early recovery phase."},{"id": 5111,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed valgus extension overload syndrome in a throwing athlete affecting elbow function?","options": [{"key": "A","text": "Immediate unrestricted return to throwing regardless of symptom status"},{"key": "B","text": "Complete permanent cessation of throwing activity regardless of symptom resolution"},{"key": "C","text": "Assuming this overuse condition requires no distinct approach from acute elbow trauma"},{"key": "D","text": "Addressing throwing mechanics and progressive strengthening of elbow/shoulder stabilizers, alongside appropriate activity modification during symptomatic periods"}],"correct": "D","explanation": "Valgus extension overload, common in throwing athletes, requires addressing the underlying throwing mechanics and strengthening needs alongside appropriate activity modification during periods of symptom flare."},{"id": 5112,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed scapholunate ligament injury affecting wrist stability?","options": [{"key": "A","text": "Assuming this ligament injury always resolves with simple conservative management regardless of severity"},{"key": "B","text": "Complete avoidance of any wrist exercise regardless of injury severity"},{"key": "C","text": "Standard wrist sprain protocol applies without any distinction for this specific ligament involvement"},{"key": "D","text": "Addressing wrist stabilization exercises while considering whether the injury requires surgical stabilization based on severity"}],"correct": "D","explanation": "Scapholunate ligament injury severity significantly influences management approach, requiring consideration of surgical stabilization for more severe injuries alongside appropriate wrist stabilization exercise for those managed conservatively."},{"id": 5113,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed triangular fibrocartilage complex (TFCC) injury affecting ulnar-sided wrist function?","options": [{"key": "A","text": "Activity modification avoiding provocative forearm rotation/loading positions, combined with progressive strengthening as tolerated"},{"key": "B","text": "Aggressive immediate maximal resistance training regardless of symptom status"},{"key": "C","text": "Assuming TFCC injuries require identical management to radial-sided wrist conditions"},{"key": "D","text": "Complete avoidance of any wrist or forearm exercise regardless of injury severity"}],"correct": "A","explanation": "TFCC injury management typically involves activity modification for provocative positions (forearm rotation, ulnar deviation with loading) alongside progressive strengthening as symptoms allow."},{"id": 5114,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed wrist extensor tendinopathy related to repetitive computer keyboard use?","options": [{"key": "A","text": "Ignoring ergonomic factors and only addressing the tendon pathology in isolation"},{"key": "B","text": "Complete avoidance of any keyboard use indefinitely regardless of symptom improvement"},{"key": "C","text": "Assuming ergonomic modification has no relevance to this occupational condition"},{"key": "D","text": "Ergonomic workstation modification alongside progressive wrist extensor loading exercise"}],"correct": "D","explanation": "Repetitive strain-related wrist extensor tendinopathy benefits from addressing both the ergonomic contributing factors and the local tendon pathology through progressive loading exercise."},{"id": 5115,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed boutonniere deformity following an untreated central slip injury?","options": [{"key": "A","text": "Standard finger sprain protocol applies without any distinction for this specific deformity"},{"key": "B","text": "Addressing the resulting extensor mechanism imbalance through targeted splinting/exercise, recognizing that established deformity may require different management than acute injury"},{"key": "C","text": "Complete avoidance of any finger exercise regardless of the deformity stage"},{"key": "D","text": "Assuming this deformity always resolves with simple stretching regardless of chronicity"}],"correct": "B","explanation": "Established boutonniere deformity requires recognition of the underlying extensor mechanism disruption, with treatment approach differing based on whether the injury is acute or has progressed to a fixed deformity."},{"id": 5116,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed mallet finger injury (DIP joint extensor tendon injury)?","options": [{"key": "A","text": "Immediate unrestricted finger movement including DIP flexion during the healing period"},{"key": "B","text": "Assuming mallet finger requires no specific splinting protocol distinct from other finger injuries"},{"key": "C","text": "Complete immobilization of the entire hand including all other digits"},{"key": "D","text": "Following the prescribed splinting protocol (typically continuous DIP extension splinting) while maintaining PIP joint mobility"}],"correct": "D","explanation": "Mallet finger management requires strict adherence to continuous DIP extension splinting to allow tendon healing, while actively maintaining PIP joint mobility to prevent secondary stiffness."},{"id": 5117,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed skier's thumb (ulnar collateral ligament injury of the thumb MCP joint)?","options": [{"key": "A","text": "Complete avoidance of any thumb-related exercise regardless of injury severity"},{"key": "B","text": "Addressing thumb stability through appropriate splinting/bracing and progressive strengthening, with severity guiding conservative versus surgical management"},{"key": "C","text": "Standard finger sprain protocol applies without any distinction for this specific thumb ligament injury"},{"key": "D","text": "Assuming this injury always requires immediate surgical repair regardless of severity"}],"correct": "B","explanation": "Skier's thumb severity (partial vs. complete tear) significantly influences management approach, with conservative splinting/strengthening appropriate for many cases while more severe injuries may require surgical repair."},{"id": 5118,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed swan neck deformity related to intrinsic muscle tightness?","options": [{"key": "A","text": "Addressing intrinsic muscle stretching alongside splinting strategies to correct the imbalance contributing to this deformity pattern"},{"key": "B","text": "Standard mallet finger protocol applies without any distinction for this different deformity pattern"},{"key": "C","text": "Assuming intrinsic tightness has no relationship to this deformity presentation"},{"key": "D","text": "Complete avoidance of any finger exercise regardless of the deformity's underlying cause"}],"correct": "A","explanation": "Swan neck deformity related to intrinsic tightness requires addressing this specific muscular imbalance through targeted stretching and appropriate splinting strategies."},{"id": 5119,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed thumb CMC joint instability following ligament injury?","options": [{"key": "A","text": "Assuming CMC instability requires identical management to simple sprain without instability"},{"key": "B","text": "Complete avoidance of any thumb-related exercise regardless of functional demands"},{"key": "C","text": "Aggressive stretching to increase already-excessive joint mobility"},{"key": "D","text": "Progressive strengthening of thumb stabilizing musculature alongside appropriate splinting/taping support during functional activities"}],"correct": "D","explanation": "Thumb CMC instability requires a distinct approach emphasizing dynamic muscular support and protective strategies during function, given the underlying structural laxity present."},{"id": 5120,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed extensor tendon adhesion following hand surgery, limiting finger flexion?","options": [{"key": "A","text": "Assuming tendon adhesions resolve spontaneously without requiring any targeted intervention"},{"key": "B","text": "Progressive tendon gliding and scar mobilization techniques to address the adhesion while protecting the healed tendon repair"},{"key": "C","text": "Aggressive forceful manipulation immediately following surgery regardless of healing status"},{"key": "D","text": "Complete avoidance of any hand exercise regardless of the adhesion's functional impact"}],"correct": "B","explanation": "Extensor tendon adhesions following surgical repair often benefit from targeted gliding exercises and scar mobilization techniques, carefully balanced with protecting the underlying tendon repair integrity."},{"id": 5121,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed complex regional pain syndrome affecting the foot/ankle following trauma?","options": [{"key": "A","text": "Assuming lower extremity CRPS requires no distinct consideration from other musculoskeletal foot injuries"},{"key": "B","text": "Complete immobilization of the affected foot/ankle indefinitely"},{"key": "C","text": "Graded motor imagery, desensitization, and gentle functional movement, similar in principle to upper extremity CRPS management approaches"},{"key": "D","text": "Aggressive forceful range of motion regardless of pain response"}],"correct": "C","explanation": "Lower extremity CRPS follows similar management principles to upper extremity presentations, emphasizing graded, pain-science-informed approaches given the altered pain processing characteristic of this condition."},{"id": 5122,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed chronic regional pain syndrome affecting function despite multiple prior treatment attempts?","options": [{"key": "A","text": "Complete avoidance of any further physiotherapy involvement"},{"key": "B","text": "Considering a comprehensive, potentially multidisciplinary approach incorporating pain science education, graded exposure, and functional restoration goals"},{"key": "C","text": "Immediate aggressive intervention identical to acute CRPS management regardless of chronicity"},{"key": "D","text": "Assuming no further intervention is beneficial once initial treatments have not resolved the condition"}],"correct": "B","explanation": "Chronic, treatment-resistant CRPS often benefits from a comprehensive, multidisciplinary approach addressing both physical function and the broader pain experience through education and graded functional restoration."},{"id": 5123,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed reflex sympathetic dystrophy (an older term for CRPS) affecting hand function and fine motor tasks?","options": [{"key": "A","text": "Addressing fine motor function through graded functional task practice alongside broader CRPS management principles"},{"key": "B","text": "Assuming this condition requires no distinct approach from simple hand stiffness"},{"key": "C","text": "Complete avoidance of any fine motor task practice"},{"key": "D","text": "Aggressive forceful manipulation of stiff joints regardless of pain response"}],"correct": "A","explanation": "CRPS affecting hand function benefits from graded functional task practice targeting fine motor skills, integrated within the broader comprehensive CRPS management approach."},{"id": 5124,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with fibromyalgia regarding aerobic exercise intensity progression?","options": [{"key": "A","text": "Assuming standard exercise progression rates apply without any modification"},{"key": "B","text": "Starting at a very low intensity and progressing extremely gradually, given the heightened symptom sensitivity often seen with exercise in this population"},{"key": "C","text": "Immediate high-intensity training regardless of symptom flare risk"},{"key": "D","text": "Complete avoidance of any aerobic exercise indefinitely"}],"correct": "B","explanation": "Fibromyalgia patients often require a much slower, more gradual approach to exercise intensity progression than typically used in other populations, given their characteristic heightened sensitivity to exercise-related symptom flares."},{"id": 5125,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with fibromyalgia regarding warm water aquatic exercise?","options": [{"key": "A","text": "Only cold water exercise is appropriate for this population"},{"key": "B","text": "Assuming water-based exercise provides no unique benefit compared to land-based exercise in fibromyalgia"},{"key": "C","text": "Aquatic exercise is contraindicated in fibromyalgia regardless of water temperature"},{"key": "D","text": "Warm water aquatic exercise is often well-tolerated and may provide symptom relief alongside the exercise benefit, given the combined effects of buoyancy and warmth"}],"correct": "D","explanation": "Warm water aquatic exercise is frequently well-tolerated in fibromyalgia, combining the benefits of reduced joint loading (buoyancy) with the soothing effect of warmth on widespread muscle tenderness."},{"id": 5126,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic widespread pain who has had negative experiences with exercise in the past leading to significant hesitancy?","options": [{"key": "A","text": "Avoiding any further discussion of exercise given the patient's hesitancy"},{"key": "B","text": "Ignoring the patient's past negative experiences and immediately implementing a standard exercise protocol"},{"key": "C","text": "Building trust through education, very gradual introduction of activity, and close collaboration on goal-setting to rebuild confidence in movement"},{"key": "D","text": "Assuming past negative experiences have no bearing on current treatment approach"}],"correct": "C","explanation": "Addressing past negative exercise experiences through trust-building, education, and collaborative goal-setting is important for supporting successful re-engagement with therapeutic exercise in patients with chronic pain-related hesitancy."},{"id": 5127,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with chronic fatigue syndrome regarding the concept of 'pacing' as an activity management strategy?","options": [{"key": "A","text": "Always completing the full prescribed exercise session regardless of fatigue symptoms"},{"key": "B","text": "Encouraging maximal exertion whenever the patient has sufficient energy on a given day"},{"key": "C","text": "Assuming pacing has no relevance to this population's activity management"},{"key": "D","text": "Balancing activity and rest to avoid triggering post-exertional malaise, rather than pushing through fatigue to complete a predetermined exercise target"}],"correct": "D","explanation": "Pacing strategies help patients with chronic fatigue syndrome manage their limited energy reserves, prioritizing symptom stability over rigid adherence to predetermined activity targets that might trigger post-exertional malaise."},{"id": 5128,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed mast cell activation syndrome affecting exercise tolerance?","options": [{"key": "A","text": "Standard exercise prescription without any consideration of this condition"},{"key": "B","text": "Assuming this rare condition has no bearing on exercise program design"},{"key": "C","text": "Complete avoidance of any exercise regardless of individual tolerance"},{"key": "D","text": "Careful, individualized exercise introduction with awareness of potential trigger factors and appropriate medical coordination given the variable presentation of this condition"}],"correct": "D","explanation": "Mast cell activation syndrome can present with variable exercise tolerance and potential triggers, requiring careful, individualized exercise introduction with appropriate medical coordination."},{"id": 5129,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with postural orthostatic tachycardia syndrome (POTS) regarding exercise positioning?","options": [{"key": "A","text": "Complete avoidance of any exercise regardless of positioning considerations"},{"key": "B","text": "Assuming positioning has no bearing on exercise tolerance in POTS"},{"key": "C","text": "Often beginning with recumbent or semi-recumbent exercise positions before progressing to upright activity, given the orthostatic intolerance characteristic of this condition"},{"key": "D","text": "Standard upright exercise positioning without any modification"}],"correct": "C","explanation": "POTS management often begins with recumbent exercise positions (e.g., recumbent bike, rowing) to minimize orthostatic symptoms, gradually progressing toward upright activity as tolerance improves."},{"id": 5130,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with Ehlers-Danlos syndrome experiencing autonomic dysfunction (dysautonomia) alongside joint hypermobility?","options": [{"key": "A","text": "Assuming autonomic symptoms have no bearing on exercise program design for this population"},{"key": "B","text": "Only addressing joint hypermobility without any consideration of autonomic symptoms"},{"key": "C","text": "Addressing both the joint stability/proprioceptive needs and any autonomic symptom considerations (e.g., orthostatic intolerance) in an integrated exercise approach"},{"key": "D","text": "Complete avoidance of any exercise given the complexity of combined presentations"}],"correct": "C","explanation": "EDS patients with coexisting dysautonomia require an integrated approach addressing both joint stability needs and any autonomic symptom considerations like orthostatic intolerance during exercise prescription."},{"id": 5131,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed mitochondrial disease affecting multiple organ systems, participating in exercise therapy?","options": [{"key": "A","text": "Complete avoidance of any exercise regardless of the specific presentation"},{"key": "B","text": "Highly individualized, carefully monitored exercise given the potential for significant multi-system involvement and variable exercise tolerance"},{"key": "C","text": "Standard exercise prescription applies without any individualization"},{"key": "D","text": "Assuming multi-system involvement has no bearing on appropriate exercise monitoring"}],"correct": "B","explanation": "Mitochondrial diseases can affect multiple organ systems with highly variable presentation, requiring individualized, carefully monitored exercise approaches tailored to each patient's specific tolerance and limitations."},{"id": 5132,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed rare neuromuscular disease of uncertain classification presenting with progressive weakness?","options": [{"key": "A","text": "Immediate aggressive strengthening regardless of the uncertain underlying pathophysiology"},{"key": "B","text": "Complete avoidance of any exercise until diagnostic uncertainty is resolved"},{"key": "C","text": "Collaborating with the medical/genetics team for diagnostic clarity while providing supportive, function-focused physiotherapy addressing the patient's current presentation"},{"key": "D","text": "Assuming physiotherapy has no role until a definitive diagnosis is established"}],"correct": "C","explanation": "Even with diagnostic uncertainty, supportive, function-focused physiotherapy addressing the patient's current presentation remains valuable, while collaborating with the broader medical team for ongoing diagnostic clarification."},{"id": 5133,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for documentation and communication when a patient's exercise program is modified due to an adverse response during a session?","options": [{"key": "A","text": "Assuming no documentation is needed if the session simply ends early"},{"key": "B","text": "Clearly documenting the specific response, modification made, and rationale, while communicating relevant changes to other involved healthcare providers as appropriate"},{"key": "C","text": "Ignoring any need to communicate the incident to other healthcare providers"},{"key": "D","text": "Providing only verbal handoff without any written documentation"}],"correct": "B","explanation": "Clear documentation of adverse responses and resulting program modifications, along with appropriate interprofessional communication, supports patient safety and continuity of care."},{"id": 5134,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for obtaining informed consent before initiating a new exercise program, particularly one involving some inherent risk (e.g., high-intensity cardiac rehabilitation)?","options": [{"key": "A","text": "Skipping any explanation of risks to avoid causing patient anxiety"},{"key": "B","text": "Explaining the exercise plan, potential risks/benefits, and addressing any patient questions or concerns before proceeding"},{"key": "C","text": "Assuming implied consent is always sufficient regardless of program risk level"},{"key": "D","text": "Providing consent information only after the exercise session has already begun"}],"correct": "B","explanation": "Appropriate informed consent involves clearly explaining the planned intervention, associated risks and benefits, and ensuring patient understanding and agreement before proceeding, particularly important for higher-risk exercise programs."},{"id": 5135,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration when a patient's goals appear to conflict with what the therapist believes is clinically appropriate (e.g., patient wants to return to running before adequate healing)?","options": [{"key": "A","text": "Ignoring clinical concerns entirely and proceeding with whatever the patient requests regardless of risk"},{"key": "B","text": "Making the decision unilaterally without any discussion with the patient"},{"key": "C","text": "Engaging in collaborative discussion, providing clear clinical rationale, and working together to find an approach that respects patient autonomy while addressing safety concerns"},{"key": "D","text": "Simply refusing to work with the patient until they agree with the therapist's recommendations"}],"correct": "C","explanation": "Navigating goal conflicts requires collaborative communication, respecting patient autonomy while providing clear clinical guidance, working toward a mutually acceptable and appropriately safe approach."},{"id": 5136,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for cultural sensitivity when working with a patient whose cultural background influences their preferences around exercise attire or same-gender treatment providers?","options": [{"key": "A","text": "Ignoring any expressed cultural or religious preferences"},{"key": "B","text": "Assuming all patients have identical preferences and requiring a completely standardized approach"},{"key": "C","text": "Refusing to treat patients with specific cultural accommodation needs"},{"key": "D","text": "Respecting and accommodating reasonable patient preferences related to cultural or religious considerations where feasible within the clinical setting"}],"correct": "D","explanation": "Culturally sensitive practice involves respecting and reasonably accommodating patient preferences related to cultural or religious factors, supporting comfortable and effective engagement with therapy."},{"id": 5137,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration when working with a patient who has limited health literacy regarding exercise instructions?","options": [{"key": "A","text": "Assuming health literacy has no bearing on effective exercise instruction"},{"key": "B","text": "Providing only written instructions without any verbal explanation or demonstration"},{"key": "C","text": "Using plain language, teach-back techniques, and visual aids to ensure understanding rather than relying on complex medical terminology"},{"key": "D","text": "Assuming all patients have equal understanding of medical/exercise terminology"}],"correct": "C","explanation": "Adapting communication to the patient's health literacy level, using plain language and confirmation techniques like teach-back, supports better understanding and safer, more effective exercise program engagement."},{"id": 5138,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration when a language barrier exists between the therapist and patient?","options": [{"key": "A","text": "Utilizing professional interpreter services when available, rather than relying solely on informal translation by family members for clinical communication"},{"key": "B","text": "Assuming gestures alone are always sufficient for effective communication regardless of complexity"},{"key": "C","text": "Avoiding treatment of patients who do not share the therapist's primary language"},{"key": "D","text": "Relying exclusively on family member translation for all clinical communication regardless of complexity or sensitivity"}],"correct": "A","explanation": "Professional interpreter services help ensure accurate, appropriate clinical communication, particularly important for informed consent and safety-related instructions, compared to potentially inconsistent informal translation."},{"id": 5139,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for telehealth-delivered exercise therapy sessions?","options": [{"key": "A","text": "Ensuring adequate visualization of the patient's movement, appropriate safety precautions for the home environment, and clear instructional communication given the remote format"},{"key": "B","text": "Complete avoidance of any exercise prescription via telehealth regardless of patient suitability"},{"key": "C","text": "Ignoring any safety considerations specific to the home exercise environment"},{"key": "D","text": "Assuming telehealth delivery requires no modification from standard in-person session structure"}],"correct": "A","explanation": "Effective telehealth exercise therapy requires attention to adequate visualization for movement assessment, home environment safety, and clear communication strategies adapted to the remote delivery format."},{"id": 5140,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for determining patient suitability for telehealth-delivered rehabilitation versus requiring in-person sessions?","options": [{"key": "A","text": "Assuming all patients and conditions are equally suitable for telehealth delivery"},{"key": "B","text": "Assuming telehealth is never appropriate for any physiotherapy intervention"},{"key": "C","text": "Making this determination without considering any patient-specific factors"},{"key": "D","text": "Considering factors like the complexity of hands-on assessment/intervention needs, patient safety risk, and technology access/comfort"}],"correct": "D","explanation": "Appropriate triage for telehealth suitability considers the specific clinical needs, safety considerations, and patient factors (technology access/comfort) relevant to each individual case."},{"id": 5141,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for maintaining professional boundaries while building therapeutic rapport with patients during exercise sessions?","options": [{"key": "A","text": "Assuming professional boundaries have no relevance to effective therapeutic relationships"},{"key": "B","text": "Ignoring the importance of maintaining appropriate professional boundaries"},{"key": "C","text": "Encouraging personal relationships with patients outside the clinical context as beneficial for rapport"},{"key": "D","text": "Maintaining a professional, supportive relationship focused on the patient's rehabilitation goals while avoiding relationships or communication that blur appropriate professional boundaries"}],"correct": "D","explanation": "Building therapeutic rapport while maintaining clear professional boundaries supports both effective treatment and appropriate professional conduct throughout the therapeutic relationship."},{"id": 5142,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed pectoralis major tendon rupture managed surgically?","options": [{"key": "A","text": "Immediate maximal resistance training regardless of surgical repair timeline"},{"key": "B","text": "Assuming this less common injury requires no specific protective rehabilitation approach"},{"key": "C","text": "Complete avoidance of any shoulder exercise indefinitely following this injury"},{"key": "D","text": "Following surgeon-specific protected range of motion protocol before progressive strengthening as the repair heals"}],"correct": "D","explanation": "Pectoralis major tendon rupture repair requires a structured, protected rehabilitation approach similar in principle to other major tendon repairs, protecting the healing tissue before progressive strengthening."},{"id": 5143,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed latissimus dorsi strain affecting shoulder/trunk function in an overhead athlete?","options": [{"key": "A","text": "Immediate unrestricted return to overhead activity regardless of healing status"},{"key": "B","text": "Complete avoidance of any shoulder or trunk exercise"},{"key": "C","text": "Assuming this less common strain requires no distinct rehabilitation approach from generalized shoulder pain"},{"key": "D","text": "Progressive loading addressing both the local muscle strain and any contributing overhead movement mechanics"}],"correct": "D","explanation": "Latissimus dorsi strain rehabilitation addresses progressive loading of the affected muscle alongside any contributing movement pattern factors relevant to the athlete's specific overhead activity demands."},{"id": 5144,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed rhomboid strain contributing to interscapular pain?","options": [{"key": "A","text": "Assuming rhomboid strain requires identical management to rotator cuff pathology"},{"key": "B","text": "Complete avoidance of any scapular exercise regardless of the acute presentation"},{"key": "C","text": "Addressing scapular retraction strength and postural factors alongside appropriate activity modification during the acute phase"},{"key": "D","text": "Aggressive immediate maximal resistance training regardless of symptom status"}],"correct": "C","explanation": "Rhomboid strain management addresses scapular retraction strength and contributing postural factors, following general muscle strain principles with attention to the specific functional role of this muscle."},{"id": 5145,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed serratus posterior strain contributing to upper back discomfort?","options": [{"key": "A","text": "Complete avoidance of any upper back exercise regardless of presentation"},{"key": "B","text": "Standard rhomboid strain protocol applies identically without any distinction"},{"key": "C","text": "Assuming this less commonly discussed muscle strain requires no targeted management approach"},{"key": "D","text": "Addressing the affected muscle through gentle stretching/strengthening while considering contributing postural or breathing pattern factors"}],"correct": "D","explanation": "Serratus posterior strain, while less frequently discussed, benefits from similar general principles of gentle progressive exercise addressing the affected muscle and any contributing biomechanical factors."},{"id": 5146,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed multifidus dysfunction/atrophy identified in association with chronic low back pain?","options": [{"key": "A","text": "Complete avoidance of any lumbar spine exercise"},{"key": "B","text": "Targeted motor control exercises aimed at re-activating and strengthening this deep spinal stabilizing muscle"},{"key": "C","text": "Only addressing superficial trunk muscles without any consideration of deep stabilizers"},{"key": "D","text": "Assuming multifidus dysfunction has no relevance to chronic low back pain management"}],"correct": "B","explanation": "Multifidus dysfunction, commonly identified in chronic low back pain, is often addressed through targeted motor control exercises aimed at improving activation and strength of this important deep spinal stabilizer."},{"id": 5147,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed erector spinae strain contributing to acute low back pain?","options": [{"key": "A","text": "Encouraging continued movement/activity within tolerance alongside gradual strengthening as the acute strain resolves"},{"key": "B","text": "Immediate aggressive strengthening regardless of the acute inflammatory presentation"},{"key": "C","text": "Assuming this common strain requires identical management to a herniated disc"},{"key": "D","text": "Strict prolonged bed rest until complete symptom resolution"}],"correct": "A","explanation": "Acute erector spinae strain generally responds well to continued activity within tolerable limits, following current evidence supporting movement over prolonged rest, with gradual strengthening as symptoms allow."},{"id": 5148,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed transverse abdominis dysfunction identified during core assessment for chronic low back pain?","options": [{"key": "A","text": "Complete avoidance of any abdominal exercise regardless of the identified dysfunction"},{"key": "B","text": "Only high-load abdominal exercises without any low-load activation training"},{"key": "C","text": "Targeted low-load activation exercises (e.g., abdominal drawing-in) to improve motor control of this deep stabilizing muscle"},{"key": "D","text": "Assuming this deep muscle has no relevance to spinal stability or low back pain"}],"correct": "C","explanation": "Transverse abdominis dysfunction is commonly addressed through specific low-load motor control exercises aimed at improving activation of this deep stabilizing muscle, relevant in certain chronic low back pain presentations."},{"id": 5149,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed obliques strain contributing to lateral trunk pain, common in rotational sports like cricket/baseball?","options": [{"key": "A","text": "Immediate unrestricted return to full rotational sport activity regardless of healing status"},{"key": "B","text": "Progressive loading addressing rotational trunk strength, alongside any contributing technique factors specific to the athlete's sport"},{"key": "C","text": "Complete avoidance of any trunk rotation exercise indefinitely"},{"key": "D","text": "Assuming oblique strains require identical management to erector spinae strains"}],"correct": "B","explanation": "Oblique muscle strains, common in rotational sports, require progressive rotational strengthening alongside attention to any sport-specific technique factors that may have contributed to the injury."},{"id": 5150,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed diaphragm strain/spasm (side stitch) affecting exercise tolerance during running?","options": [{"key": "A","text": "Complete avoidance of any running or aerobic exercise indefinitely"},{"key": "B","text": "Addressing breathing pattern technique and pacing strategies, as this common exercise-related discomfort often relates to breathing mechanics during exertion"},{"key": "C","text": "Assuming this common phenomenon has no relationship to breathing technique"},{"key": "D","text": "Ignoring any pacing or breathing strategy considerations for this common symptom"}],"correct": "B","explanation": "Exercise-related transient abdominal pain (side stitch) is often related to breathing mechanics during exertion, making breathing technique and pacing strategy education a relevant physiotherapy consideration."},{"id": 5151,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed hip flexor-related snapping hip syndrome (internal type, involving the iliopsoas tendon)?","options": [{"key": "A","text": "Assuming internal and external snapping hip syndromes require identical treatment approaches"},{"key": "B","text": "Complete avoidance of any hip-related exercise regardless of the specific type"},{"key": "C","text": "Addressing iliopsoas flexibility and hip strength/control, potentially combined with activity modification during symptomatic periods"},{"key": "D","text": "Standard external snapping hip (IT band) protocol applies without any distinction for this different mechanism"}],"correct": "C","explanation": "Internal snapping hip syndrome, involving the iliopsoas tendon, requires a distinct treatment approach from external (IT band-related) snapping hip, focusing on iliopsoas flexibility and hip strength/control."},{"id": 5152,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed gluteal muscle atrophy secondary to prolonged disuse (e.g., following extended bed rest)?","options": [{"key": "A","text": "Immediate maximal resistance training regardless of the degree of deconditioning"},{"key": "B","text": "Progressive gluteal strengthening exercise as part of a broader reconditioning program addressing the deconditioning that occurred"},{"key": "C","text": "Complete avoidance of any lower extremity strengthening exercise"},{"key": "D","text": "Assuming atrophy from disuse cannot be addressed through exercise intervention"}],"correct": "B","explanation": "Disuse-related muscle atrophy, including gluteal weakness following prolonged inactivity, generally responds well to progressive strengthening exercise as part of a comprehensive reconditioning approach."},{"id": 5153,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed piriformis muscle hypertrophy (rather than simple tightness) contributing to sciatic nerve compression?","options": [{"key": "A","text": "Addressing this less common presentation with appropriate stretching/strengthening balance while considering whether further diagnostic workup is needed given the atypical etiology"},{"key": "B","text": "Standard piriformis syndrome protocol applies without any consideration of the underlying hypertrophy"},{"key": "C","text": "Assuming muscle hypertrophy as a cause of piriformis syndrome requires no distinct consideration"},{"key": "D","text": "Complete avoidance of any exercise regardless of the specific underlying cause"}],"correct": "A","explanation": "While less common than simple tightness, piriformis hypertrophy as a cause of sciatic compression may warrant additional consideration regarding underlying etiology alongside standard conservative management approaches."},{"id": 5154,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed vastus lateralis strain affecting lateral thigh function?","options": [{"key": "A","text": "Complete avoidance of any quadriceps exercise regardless of the specific muscle involved"},{"key": "B","text": "Progressive loading following general muscle strain principles, addressing the specific quadriceps component involved"},{"key": "C","text": "Standard rectus femoris protocol applies identically without any distinction for this single-joint muscle"},{"key": "D","text": "Assuming vastus lateralis strains require no rehabilitation approach distinct from ligament injuries"}],"correct": "B","explanation": "Vastus lateralis strain, being a single-joint muscle unlike the two-joint rectus femoris, follows general muscle strain rehabilitation principles with attention to its specific functional role in knee extension."},{"id": 5155,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed sartorius strain affecting hip flexion/external rotation function?","options": [{"key": "A","text": "Assuming sartorius strains require no consideration of this muscle's unique multi-planar function"},{"key": "B","text": "Complete avoidance of any hip-related exercise regardless of the specific muscle involved"},{"key": "C","text": "Progressive loading addressing this muscle's unique combined hip flexion, abduction, and external rotation function during rehabilitation exercise selection"},{"key": "D","text": "Standard hip flexor (iliopsoas) protocol applies identically without distinction for this different muscle's unique action"}],"correct": "C","explanation": "Sartorius, with its unique combined action across hip flexion, abduction, and external rotation, requires rehabilitation exercise selection that addresses this specific multi-planar functional role."},{"id": 5156,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed gracilis strain affecting hip adduction/knee flexion function?","options": [{"key": "A","text": "Progressive loading addressing this two-joint muscle's combined hip adduction and knee flexion function during rehabilitation"},{"key": "B","text": "Standard adductor longus protocol applies identically without consideration of gracilis's unique two-joint action"},{"key": "C","text": "Assuming gracilis strains require no consideration of its combined hip and knee function"},{"key": "D","text": "Complete avoidance of any adductor-related exercise regardless of the specific muscle involved"}],"correct": "A","explanation": "Gracilis, as a two-joint muscle crossing both the hip and knee, requires rehabilitation consideration of its combined adduction and knee flexion functions, similar in principle to other two-joint muscle strain management."},{"id": 5157,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed biceps femoris strain (lateral hamstring) affecting knee flexion/external rotation function?","options": [{"key": "A","text": "Standard semitendinosus/semimembranosus protocol applies identically without any distinction"},{"key": "B","text": "Progressive loading addressing this specific hamstring component's combined knee flexion and external rotation function"},{"key": "C","text": "Assuming biceps femoris strains require no consideration of its unique rotational function"},{"key": "D","text": "Complete avoidance of any hamstring exercise regardless of the specific muscle involved"}],"correct": "B","explanation": "Biceps femoris, contributing to knee external rotation in addition to flexion (unlike the medial hamstrings which contribute to internal rotation), requires rehabilitation consideration of this specific functional distinction."},{"id": 5158,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed semimembranosus strain (medial hamstring) affecting knee flexion/internal rotation function?","options": [{"key": "A","text": "Progressive loading addressing this specific hamstring component's combined knee flexion and internal rotation function"},{"key": "B","text": "Standard biceps femoris protocol applies identically without any distinction for this different medial hamstring component"},{"key": "C","text": "Complete avoidance of any hamstring exercise regardless of the specific muscle involved"},{"key": "D","text": "Assuming semimembranosus strains require no consideration of its unique rotational function"}],"correct": "A","explanation": "Semimembranosus, along with semitendinosus, contributes to knee internal rotation (distinct from biceps femoris's external rotation contribution), an important functional distinction in comprehensive hamstring rehabilitation."},{"id": 5159,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following describes an appropriate final exercise therapy consideration when a patient successfully completes a rehabilitation program and is preparing for discharge?","options": [{"key": "A","text": "Assuming no further guidance is needed once formal treatment sessions conclude"},{"key": "B","text": "Assuming all patients require identical discharge instructions regardless of their specific condition or goals"},{"key": "C","text": "Providing a comprehensive maintenance/home exercise program along with education on recognizing and appropriately managing any symptom recurrence"},{"key": "D","text": "Providing no discharge planning or ongoing self-management education"}],"correct": "C","explanation": "Comprehensive discharge planning includes an appropriate maintenance program and education on self-management/recurrence recognition, supporting long-term success beyond the formal treatment episode."},{"id": 5160,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed gastrocnemius strain (tennis leg) affecting calf function?","options": [{"key": "A","text": "Assuming gastrocnemius strains require no consideration of its combined knee and ankle function"},{"key": "B","text": "Complete avoidance of any calf-related exercise regardless of healing stage"},{"key": "C","text": "Standard soleus strain protocol applies identically without distinction for this different two-joint muscle"},{"key": "D","text": "Progressive loading following general muscle strain principles, with attention to the two-joint nature of gastrocnemius crossing both knee and ankle"}],"correct": "D","explanation": "Gastrocnemius, as a two-joint muscle crossing the knee and ankle, requires rehabilitation consideration of both joints' positions during exercise progression, distinct from the single-joint soleus."},{"id": 5161,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed soleus strain affecting ankle plantarflexion function?","options": [{"key": "A","text": "Standard gastrocnemius strain protocol applies identically without any distinction"},{"key": "B","text": "Assuming soleus strains require identical positioning considerations to gastrocnemius strains"},{"key": "C","text": "Progressive loading with knee flexed positioning to selectively target the soleus, distinct from gastrocnemius-focused exercises performed with knee extended"},{"key": "D","text": "Complete avoidance of any calf-related exercise regardless of the specific muscle involved"}],"correct": "C","explanation": "Soleus, being a single-joint muscle (unlike gastrocnemius), is selectively targeted with knee-flexed exercise positioning, an important distinction for effective, muscle-specific calf rehabilitation."},{"id": 5162,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient completing this comprehensive rehabilitation exercise education, regarding integration of biomechanical, physiological, and psychosocial principles?","options": [{"key": "A","text": "Effective exercise therapy integrates understanding of tissue healing, biomechanics, exercise physiology, and psychosocial factors to provide truly comprehensive, individualized patient care"},{"key": "B","text": "Psychosocial factors have no meaningful role in physical rehabilitation outcomes"},{"key": "C","text": "Effective exercise therapy relies exclusively on biomechanical principles without any other consideration"},{"key": "D","text": "Exercise physiology principles are irrelevant to musculoskeletal rehabilitation planning"}],"correct": "A","explanation": "Comprehensive, evidence-informed physiotherapy practice integrates multiple domains of knowledge, recognizing that effective patient care extends beyond purely biomechanical considerations to encompass physiological and psychosocial factors."},{"id": 5163,"subject": "Exercise Therapy","topic": "Muscle Contraction Types","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed tibialis anterior strain affecting ankle dorsiflexion during eccentric loading activities (e.g., downhill walking)?","options": [{"key": "A","text": "Assuming eccentric loading has no relevance to this specific strain mechanism"},{"key": "B","text": "Progressive eccentric loading rehabilitation addressing the specific mechanism of injury common with downhill/deceleration activities"},{"key": "C","text": "Standard posterior tibial tendon protocol applies identically without distinction for this different muscle/mechanism"},{"key": "D","text": "Complete avoidance of any ankle-related exercise regardless of the mechanism of injury"}],"correct": "B","explanation": "Tibialis anterior strains often relate to eccentric loading demands (e.g., controlling foot descent during downhill activities), requiring rehabilitation exercise that addresses this specific mechanism."},{"id": 5164,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed flexor digitorum longus strain affecting toe flexion function?","options": [{"key": "A","text": "Standard flexor hallucis longus protocol applies identically without any distinction for this different toe flexor muscle"},{"key": "B","text": "Complete avoidance of any foot-related exercise regardless of the specific muscle involved"},{"key": "C","text": "Progressive loading addressing this muscle's role in toe flexion, considering any contributing biomechanical or footwear factors"},{"key": "D","text": "Assuming this less commonly discussed strain requires no targeted rehabilitation approach"}],"correct": "C","explanation": "Flexor digitorum longus strain, while less frequently discussed than FHL, follows similar general tendon/muscle loading principles with attention to its specific role in lesser toe flexion."},{"id": 5165,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed extensor digitorum longus strain affecting toe extension/ankle dorsiflexion assistance?","options": [{"key": "A","text": "Complete avoidance of any foot/ankle exercise regardless of the specific muscle involved"},{"key": "B","text": "Assuming this less commonly discussed strain requires no targeted rehabilitation approach"},{"key": "C","text": "Progressive loading addressing this muscle's combined role in toe extension and ankle dorsiflexion assistance"},{"key": "D","text": "Standard tibialis anterior protocol applies identically without any distinction for this different dorsiflexor muscle"}],"correct": "C","explanation": "Extensor digitorum longus, contributing to both toe extension and ankle dorsiflexion assistance, requires rehabilitation consideration of this combined functional role distinct from the primary dorsiflexor tibialis anterior."},{"id": 5166,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient nearing completion of a comprehensive lower extremity rehabilitation program, regarding final functional testing before full return to sport?","options": [{"key": "A","text": "Incorporating sport-specific functional tests (e.g., hop tests, agility drills) alongside strength symmetry assessment to comprehensively evaluate readiness"},{"key": "B","text": "Assuming strength testing alone is sufficient without any sport-specific functional assessment"},{"key": "C","text": "Skipping any formal return-to-sport testing process entirely"},{"key": "D","text": "Relying solely on time elapsed since injury without any functional testing"}],"correct": "A","explanation": "Comprehensive return-to-sport readiness assessment combines strength testing with sport-specific functional tests, providing a more complete picture of a patient's preparedness for full unrestricted activity."},{"id": 5167,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best summarizes the overarching goal of therapeutic exercise prescription across the diverse conditions and populations covered in comprehensive physiotherapy practice?","options": [{"key": "A","text": "Applying an identical, standardized exercise protocol regardless of patient presentation or goals"},{"key": "B","text": "Prescribing exercise without any need for ongoing reassessment or individualization"},{"key": "C","text": "Focusing exclusively on symptom elimination without any consideration of functional outcomes"},{"key": "D","text": "Restoring or optimizing function, reducing symptoms, and improving quality of life through individualized, evidence-informed movement-based intervention"}],"correct": "D","explanation": "The unifying goal across the wide range of physiotherapy exercise applications is individualized, evidence-informed intervention aimed at restoring function, managing symptoms, and enhancing overall quality of life for each specific patient."},{"id": 5168,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed abductor digiti minimi strain (small foot muscle) affecting lateral foot function?","options": [{"key": "A","text": "Standard plantar fasciitis protocol applies identically without distinction for this different structure"},{"key": "B","text": "Progressive loading following general small muscle strain principles, considering any contributing footwear or biomechanical factors"},{"key": "C","text": "Assuming small intrinsic foot muscle strains require no targeted rehabilitation consideration"},{"key": "D","text": "Complete avoidance of any foot exercise regardless of the specific small muscle involved"}],"correct": "B","explanation": "Even less commonly discussed small intrinsic foot muscle strains benefit from progressive loading principles and attention to contributing biomechanical factors, similar to other muscle strain management approaches."},{"id": 5169,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed interosseous muscle strain of the foot affecting toe stability?","options": [{"key": "A","text": "Assuming intrinsic foot muscle strains require no targeted rehabilitation approach"},{"key": "B","text": "Standard extrinsic muscle strain protocol applies identically without distinction for these intrinsic foot muscles"},{"key": "C","text": "Complete avoidance of any foot-related exercise regardless of the specific intrinsic muscle involved"},{"key": "D","text": "Progressive intrinsic foot muscle strengthening addressing this muscle group's role in toe stability and arch support"}],"correct": "D","explanation": "Foot interosseous muscle involvement requires targeted intrinsic foot strengthening addressing their specific contribution to toe stability and dynamic arch support during functional activities."},{"id": 5170,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed quadratus femoris strain (deep hip external rotator) affecting hip function?","options": [{"key": "A","text": "Standard piriformis syndrome protocol applies identically without any distinction for this different deep hip rotator"},{"key": "B","text": "Progressive loading addressing this deep external rotator's function, distinct from the more commonly addressed piriformis"},{"key": "C","text": "Complete avoidance of any hip external rotation exercise regardless of the specific muscle involved"},{"key": "D","text": "Assuming quadratus femoris strains require no consideration distinct from generalized hip pain"}],"correct": "B","explanation": "Quadratus femoris, one of several deep hip external rotators, requires rehabilitation consideration distinct from the more frequently discussed piriformis, though following similar general deep rotator strengthening principles."},{"id": 5171,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed obturator internus strain affecting deep hip rotator function?","options": [{"key": "A","text": "Assuming obturator internus strains require no targeted rehabilitation approach"},{"key": "B","text": "Complete avoidance of any hip-related exercise regardless of the specific deep rotator involved"},{"key": "C","text": "Progressive loading of this deep hip rotator alongside broader hip stability training as part of comprehensive rehabilitation"},{"key": "D","text": "Standard superficial gluteal muscle protocol applies identically without distinction for this deep rotator"}],"correct": "C","explanation": "Obturator internus, another deep hip external rotator, benefits from progressive loading integrated within broader hip stability training, following general principles applicable to this muscle group."},{"id": 5172,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following best reflects the comprehensive scope of therapeutic exercise knowledge required for effective physiotherapy practice across musculoskeletal, neurological, cardiopulmonary, and other conditions?","options": [{"key": "A","text": "Complete reliance on standardized protocols without any need for clinical reasoning or individualization"},{"key": "B","text": "A narrow focus limited to only musculoskeletal conditions without any other systems knowledge"},{"key": "C","text": "Assuming identical exercise principles apply uniformly regardless of the underlying condition or patient population"},{"key": "D","text": "A broad, integrated understanding spanning tissue healing, biomechanics, exercise physiology, neuroscience, and patient-centered communication across the lifespan and diverse clinical populations"}],"correct": "D","explanation": "Comprehensive physiotherapy exercise practice requires broad, integrated knowledge across multiple physiological systems and clinical populations, combined with strong clinical reasoning and patient-centered communication skills."},{"id": 5173,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed gemellus muscle strain (deep hip external rotator) affecting hip stability?","options": [{"key": "A","text": "Progressive loading of this deep rotator as part of comprehensive hip external rotator rehabilitation"},{"key": "B","text": "Assuming gemellus strains require no targeted rehabilitation consideration"},{"key": "C","text": "Standard adductor strain protocol applies identically without any distinction for this different rotator muscle"},{"key": "D","text": "Complete avoidance of any hip-related exercise regardless of the specific deep rotator involved"}],"correct": "A","explanation": "The gemellus muscles, part of the deep hip external rotator group, follow similar general rehabilitation principles to other deep rotators, integrated within comprehensive hip stability programming."},{"id": 5174,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Medium","question": "Which of the following describes an appropriate final exercise therapy consideration when synthesizing a comprehensive rehabilitation plan for a patient with multiple co-existing conditions (e.g., diabetes, osteoarthritis, and cardiovascular disease)?","options": [{"key": "A","text": "Assuming co-existing conditions have no bearing on how the exercise program should be structured"},{"key": "B","text": "Addressing each condition with a completely separate, unrelated exercise program without integration"},{"key": "C","text": "Focusing exclusively on one condition while ignoring the others entirely"},{"key": "D","text": "Integrating consideration of all relevant conditions into a single, individualized exercise plan that addresses safety precautions and functional goals holistically"}],"correct": "D","explanation": "Effective management of patients with multiple co-existing conditions requires an integrated, holistic exercise plan that appropriately addresses the combined safety considerations and functional goals relevant to all conditions present."},{"id": 5175,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best describes the fundamental clinical reasoning process physiotherapists use to select appropriate therapeutic exercise for an individual patient?","options": [{"key": "A","text": "Combining assessment findings, evidence-based principles, and patient goals/preferences to individualize the exercise prescription"},{"key": "B","text": "Basing exercise selection solely on the patient's diagnosis without any other consideration"},{"key": "C","text": "Applying a single universal exercise protocol to all patients regardless of presentation"},{"key": "D","text": "Selecting exercises randomly without any systematic clinical reasoning process"}],"correct": "A","explanation": "Sound clinical reasoning integrates thorough assessment, current evidence, and individual patient factors (goals, preferences, context) to arrive at a truly individualized and appropriate exercise therapy plan."},{"id": 5176,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed pectineus strain (hip flexor/adductor) affecting groin function?","options": [{"key": "A","text": "Assuming this less commonly isolated strain requires no targeted rehabilitation approach"},{"key": "B","text": "Standard adductor longus protocol applies identically without any consideration of pectineus's combined action"},{"key": "C","text": "Complete avoidance of any groin-related exercise regardless of the specific muscle involved"},{"key": "D","text": "Progressive loading addressing this muscle's combined hip flexion and adduction function, following general adductor group rehabilitation principles"}],"correct": "D","explanation": "Pectineus, contributing to both hip flexion and adduction, requires rehabilitation consideration of this combined action, generally following similar principles to broader adductor group strain management."},{"id": 5177,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed adductor magnus strain affecting hip adduction/extension function?","options": [{"key": "A","text": "Assuming adductor magnus strains require no consideration of its unique combined function"},{"key": "B","text": "Standard adductor longus protocol applies identically without distinction for this muscle's additional extension function"},{"key": "C","text": "Complete avoidance of any adductor-related exercise regardless of the specific muscle involved"},{"key": "D","text": "Progressive loading addressing this muscle's combined adduction and extension function, given its unique dual role compared to other adductors"}],"correct": "D","explanation": "Adductor magnus, with its posterior fibers contributing to hip extension in addition to adduction, requires rehabilitation exercise selection addressing this broader functional role compared to the purely adductor longus."},{"id": 5178,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best summarizes the appropriate approach to prescribing therapeutic exercise for the great majority of conditions discussed across this comprehensive review of exercise therapy principles?","options": [{"key": "A","text": "A completely standardized, one-size-fits-all protocol applied uniformly regardless of condition or individual presentation"},{"key": "B","text": "Immediate maximal intensity exercise regardless of the specific condition or healing stage"},{"key": "C","text": "Exercise progression based solely on time elapsed since injury without any clinical reassessment"},{"key": "D","text": "An individualized, evidence-informed, progressively graded approach that considers tissue healing, patient goals, and safety throughout the rehabilitation continuum"}],"correct": "D","explanation": "Across the vast range of conditions and populations addressed in physiotherapy practice, the consistent underlying principle is individualized, evidence-informed, progressively graded exercise prescription tailored to each patient's specific needs and presentation."},{"id": 5179,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed articularis genus strain (small knee stabilizer muscle) affecting suprapatellar pouch function?","options": [{"key": "A","text": "Complete avoidance of any knee-related exercise regardless of this small muscle's involvement"},{"key": "B","text": "Assuming this rarely isolated small muscle strain requires no rehabilitation consideration"},{"key": "C","text": "Progressive quadriceps-integrated loading, as this small muscle works alongside vastus intermedius to retract the suprapatellar pouch during knee extension"},{"key": "D","text": "Standard patellar tendinopathy protocol applies identically without any distinction for this different small stabilizer"}],"correct": "C","explanation": "Articularis genus, though small and rarely isolated in clinical presentation, is functionally integrated with vastus intermedius during knee extension, following general quadriceps rehabilitation principles."},{"id": 5180,"subject": "Exercise Therapy","topic": "Strengthening & Conditioning","difficulty": "Medium","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed subscapularis strain affecting internal rotation strength of the shoulder?","options": [{"key": "A","text": "Complete avoidance of any shoulder exercise regardless of the specific rotator cuff muscle involved"},{"key": "B","text": "Standard supraspinatus protocol applies identically without distinction for this different rotator cuff muscle's function"},{"key": "C","text": "Assuming subscapularis strains require no consideration of its specific internal rotation role"},{"key": "D","text": "Progressive internal rotation strengthening addressing this important anterior rotator cuff component, alongside broader shoulder stability training"}],"correct": "D","explanation": "Subscapularis, the primary internal rotator among the rotator cuff muscles, requires targeted strengthening addressing this specific function, complementing broader rotator cuff and shoulder stability rehabilitation."},{"id": 5181,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best captures the essential clinical competency physiotherapists develop through comprehensive study of exercise therapy across the full range of conditions and populations reviewed?","options": [{"key": "A","text": "The ability to apply identical treatment regardless of patient-specific factors"},{"key": "B","text": "Knowledge limited exclusively to musculoskeletal conditions without broader systemic understanding"},{"key": "C","text": "The ability to safely, effectively, and compassionately apply evidence-informed, individualized movement-based interventions to optimize function and quality of life across diverse patient presentations"},{"key": "D","text": "Memorization of a fixed set of exercises without any need for clinical reasoning"}],"correct": "C","explanation": "This final synthesis reflects the core competency of physiotherapy exercise practice: applying broad, integrated clinical knowledge with sound reasoning and compassionate, individualized care across the diverse conditions and populations physiotherapists encounter."},{"id": 5182,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed coracobrachialis strain affecting shoulder flexion/adduction function?","options": [{"key": "A","text": "Complete avoidance of any shoulder exercise regardless of the specific muscle involved"},{"key": "B","text": "Assuming coracobrachialis strains require no targeted rehabilitation consideration"},{"key": "C","text": "Standard biceps strain protocol applies identically without distinction for this different muscle"},{"key": "D","text": "Progressive loading addressing this less commonly isolated muscle's combined shoulder flexion and adduction role"}],"correct": "D","explanation": "Coracobrachialis, though rarely isolated in strain injuries, follows general shoulder muscle rehabilitation principles addressing its combined flexion/adduction function."},{"id": 5183,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Hard","question": "Which of the following describes an appropriate exercise therapy consideration for a patient with a diagnosed teres major strain affecting shoulder extension/internal rotation function?","options": [{"key": "A","text": "Standard latissimus dorsi protocol applies identically without any consideration of teres major's distinct attachment"},{"key": "B","text": "Progressive loading addressing this muscle's combined shoulder extension, adduction, and internal rotation function"},{"key": "C","text": "Complete avoidance of any shoulder exercise regardless of the specific muscle involved"},{"key": "D","text": "Assuming teres major strains require no targeted rehabilitation approach"}],"correct": "B","explanation": "Teres major, sometimes called the 'lat's little helper' due to similar actions, requires rehabilitation addressing its combined extension, adduction, and internal rotation function at the shoulder."},{"id": 5184,"subject": "Exercise Therapy","topic": "General Exercise Therapy","difficulty": "Easy","question": "Which of the following best represents the concluding principle for applying therapeutic exercise knowledge in physiotherapy clinical practice?","options": [{"key": "A","text": "Assuming the same exercise approach applies regardless of patient progress or changing needs"},{"key": "B","text": "A fixed, unchanging exercise prescription determined at the first visit and never modified"},{"key": "C","text": "Exercise selection based purely on convention without consideration of current evidence or patient response"},{"key": "D","text": "Continual clinical reasoning, ongoing reassessment, and individualized adaptation of exercise prescription throughout the patient's rehabilitation journey"}],"correct": "D","explanation": "Effective physiotherapy practice requires ongoing clinical reasoning and reassessment, with exercise prescription continually adapted based on the patient's progress, response, and evolving goals throughout their care."},{"id": 5185,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Electric current is defined as:","options": [{"key": "A","text": "The resistance offered by a conductor"},{"key": "B","text": "The capacity of a material to store charge"},{"key": "C","text": "The rate of flow of electric charge (electrons) through a conductor"},{"key": "D","text": "The potential difference between two points"}],"correct": "C","explanation": "Electric current is the rate of flow of charge, conventionally measured as the flow of electrons through a conductor per unit time."},{"id": 5186,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "The SI unit of electric current is the:","options": [{"key": "A","text": "Ohm"},{"key": "B","text": "Coulomb"},{"key": "C","text": "Ampere"},{"key": "D","text": "Volt"}],"correct": "C","explanation": "Current is measured in Amperes (A), representing one coulomb of charge passing a point per second."},{"id": 5187,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "The SI unit of electric charge is the:","options": [{"key": "A","text": "Watt"},{"key": "B","text": "Coulomb"},{"key": "C","text": "Volt"},{"key": "D","text": "Ampere"}],"correct": "B","explanation": "Electric charge is measured in Coulombs (C)."},{"id": 5188,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Voltage (electromotive force/potential difference) is defined as:","options": [{"key": "A","text": "The rate of energy consumption"},{"key": "B","text": "The opposition to current flow"},{"key": "C","text": "The rate of flow of charge"},{"key": "D","text": "The work done per unit charge in moving it between two points in a circuit"}],"correct": "D","explanation": "Voltage represents the energy (work) required to move a unit charge between two points, driving current flow through a circuit."},{"id": 5189,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "The SI unit of voltage (potential difference) is the:","options": [{"key": "A","text": "Watt"},{"key": "B","text": "Ampere"},{"key": "C","text": "Volt"},{"key": "D","text": "Ohm"}],"correct": "C","explanation": "Voltage is measured in Volts (V)."},{"id": 5190,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Resistance is defined as:","options": [{"key": "A","text": "The storage capacity of a capacitor"},{"key": "B","text": "The rate of flow of current"},{"key": "C","text": "The opposition offered by a material to the flow of electric current"},{"key": "D","text": "The work done per unit charge"}],"correct": "C","explanation": "Resistance is the property of a material that opposes/impedes the flow of electric current through it."},{"id": 5191,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "The SI unit of electrical resistance is the:","options": [{"key": "A","text": "Ohm"},{"key": "B","text": "Volt"},{"key": "C","text": "Ampere"},{"key": "D","text": "Farad"}],"correct": "A","explanation": "Resistance is measured in Ohms (Ω)."},{"id": 5192,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Ohm's Law states that:","options": [{"key": "A","text": "Power equals voltage times resistance"},{"key": "B","text": "Resistance is directly proportional to voltage only"},{"key": "C","text": "Current is inversely proportional to voltage at constant resistance"},{"key": "D","text": "Voltage is directly proportional to current, with resistance as the constant of proportionality (V = IR)"}],"correct": "D","explanation": "Ohm's Law: V = IR, stating that voltage across a conductor is directly proportional to the current flowing through it, with resistance as the proportionality constant."},{"id": 5193,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "According to Ohm's Law, if resistance is held constant, increasing voltage will:","options": [{"key": "A","text": "Have no effect on current"},{"key": "B","text": "Decrease current"},{"key": "C","text": "Increase current proportionally"},{"key": "D","text": "Decrease resistance"}],"correct": "C","explanation": "Since V = IR, at constant resistance, current increases proportionally with an increase in applied voltage."},{"id": 5194,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "If a circuit has a voltage of 12V and a resistance of 4 ohms, the current flowing is:","options": [{"key": "A","text": "48 amperes"},{"key": "B","text": "16 amperes"},{"key": "C","text": "0.33 amperes"},{"key": "D","text": "3 amperes"}],"correct": "D","explanation": "Using Ohm's Law: I = V/R = 12/4 = 3 amperes."},{"id": 5195,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Electrical power is calculated using which formula?","options": [{"key": "A","text": "P = V - I"},{"key": "B","text": "P = V + I"},{"key": "C","text": "P = V/I"},{"key": "D","text": "P = V × I (also expressible as P = I²R or P = V²/R)"}],"correct": "D","explanation": "Power (in watts) equals voltage multiplied by current, and can also be expressed using Ohm's Law substitutions as I²R or V²/R."},{"id": 5196,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "The SI unit of electrical power is the:","options": [{"key": "A","text": "Coulomb"},{"key": "B","text": "Watt"},{"key": "C","text": "Farad"},{"key": "D","text": "Joule"}],"correct": "B","explanation": "Electrical power is measured in Watts (W), where 1 W = 1 joule per second."},{"id": 5197,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "A conductor is a material that:","options": [{"key": "A","text": "Converts electrical energy to chemical energy exclusively"},{"key": "B","text": "Strongly resists the flow of electric current"},{"key": "C","text": "Allows electric current to flow through it relatively easily, due to availability of free electrons"},{"key": "D","text": "Stores electric charge"}],"correct": "C","explanation": "Conductors (e.g., metals, body tissues with high fluid/electrolyte content) have free electrons that allow relatively easy current flow."},{"id": 5198,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "An insulator is a material that:","options": [{"key": "A","text": "Only conducts current in one direction"},{"key": "B","text": "Allows current to flow freely"},{"key": "C","text": "Stores charge indefinitely with no resistance"},{"key": "D","text": "Strongly resists/prevents the flow of electric current, due to tightly bound electrons"}],"correct": "D","explanation": "Insulators have tightly bound electrons, offering high resistance and effectively preventing current flow under normal conditions."},{"id": 5199,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "In the human body, which tissue generally offers the LEAST electrical resistance (i.e., is the best conductor)?","options": [{"key": "A","text": "Bone"},{"key": "B","text": "Dry skin (stratum corneum)"},{"key": "C","text": "Fat"},{"key": "D","text": "Blood and nerve tissue (due to high fluid/electrolyte content)"}],"correct": "D","explanation": "Blood and nerve tissue, having high water/electrolyte content, offer relatively low resistance to electrical current compared to tissues like bone, fat, or dry skin."},{"id": 5200,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "The skin, particularly the stratum corneum, generally offers __________ resistance to electrical current compared to deeper tissues.","options": [{"key": "A","text": "Equal"},{"key": "B","text": "Lower"},{"key": "C","text": "Higher, acting as a significant barrier that must be overcome for effective current penetration during electrotherapy"},{"key": "D","text": "No resistance at all"}],"correct": "C","explanation": "Dry skin (stratum corneum) has relatively high electrical resistance, which is why techniques like skin preparation/moistening are used clinically to reduce this barrier and improve current flow during treatment."},{"id": 5201,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Direct current (DC) is characterized by:","options": [{"key": "A","text": "Current that flows in one direction only, with a relatively constant magnitude over time"},{"key": "B","text": "Current that oscillates in a sinusoidal pattern"},{"key": "C","text": "Current that continuously reverses direction"},{"key": "D","text": "Current with zero net charge flow"}],"correct": "A","explanation": "Direct current flows unidirectionally, maintaining polarity, in contrast to alternating current which periodically reverses direction."},{"id": 5202,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Alternating current (AC) is characterized by:","options": [{"key": "A","text": "Current with no waveform pattern"},{"key": "B","text": "Current that flows in one direction only"},{"key": "C","text": "Current that is always used for iontophoresis"},{"key": "D","text": "Current that periodically reverses direction, typically in a sinusoidal or other repeating waveform pattern"}],"correct": "D","explanation": "Alternating current periodically reverses its direction of flow, commonly in a sinusoidal pattern, distinguishing it from unidirectional direct current."},{"id": 5203,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Pulsed current, commonly used in therapeutic electrical stimulation, is characterized by:","options": [{"key": "A","text": "Current identical to pure direct current with no on/off pattern"},{"key": "B","text": "Current flow that is interrupted periodically, consisting of discrete pulses separated by periods of no current flow (interpulse intervals)"},{"key": "C","text": "Continuous, unbroken current flow with no interruption"},{"key": "D","text": "Current that flows only in the reverse direction"}],"correct": "B","explanation": "Pulsed current consists of individual pulses of current separated by periods of zero current flow, distinguishing it from continuous DC or AC."},{"id": 5204,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "A monophasic pulsed current is characterized by:","options": [{"key": "A","text": "Pulses that deflect in only one direction from the baseline (isoelectric line)"},{"key": "B","text": "Pulses that deflect in both positive and negative directions from baseline"},{"key": "C","text": "Continuous, unbroken current flow"},{"key": "D","text": "Pulses with no measurable amplitude"}],"correct": "A","explanation": "Monophasic current pulses deflect in a single direction (either entirely positive or entirely negative) from the zero/baseline reference line."},{"id": 5205,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "A biphasic pulsed current is characterized by:","options": [{"key": "A","text": "Continuous direct current with no pulsing"},{"key": "B","text": "Pulses that deflect in only one direction"},{"key": "C","text": "A current used exclusively for iontophoresis"},{"key": "D","text": "Pulses that deflect in both positive and negative directions from the baseline within a single pulse cycle"}],"correct": "D","explanation": "Biphasic current pulses have both a positive and negative phase within each pulse cycle, deflecting in both directions from the baseline."},{"id": 5206,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "A symmetrical biphasic pulsed current is one in which:","options": [{"key": "A","text": "The positive and negative phases of each pulse are mirror images of each other in terms of shape, amplitude, and duration"},{"key": "B","text": "There is no net charge in either phase"},{"key": "C","text": "Only the positive phase exists"},{"key": "D","text": "The two phases have different shapes and amplitudes"}],"correct": "A","explanation": "In a symmetrical biphasic waveform, the negative phase is an exact mirror image of the positive phase in shape, amplitude, and duration, resulting in balanced (typically zero net) charge."},{"id": 5207,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "An asymmetrical biphasic pulsed current is one in which:","options": [{"key": "A","text": "This waveform type does not exist in clinical practice"},{"key": "B","text": "Both phases are identical mirror images"},{"key": "C","text": "The two phases differ in shape and/or amplitude, though the current may still be balanced (net zero charge) or unbalanced depending on design"},{"key": "D","text": "Only a single phase is present"}],"correct": "C","explanation": "Asymmetrical biphasic currents have phases that differ from each other in shape/amplitude; they can be designed as either balanced (equal charge in each phase) or unbalanced."},{"id": 5208,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "'Pulse duration' (pulse width) refers to:","options": [{"key": "A","text": "The total treatment time"},{"key": "B","text": "The time between the start of one pulse and the start of the next pulse"},{"key": "C","text": "The amplitude of the current"},{"key": "D","text": "The time duration of a single pulse, from its beginning to its end"}],"correct": "D","explanation": "Pulse duration (or pulse width) is the length of time that a single pulse lasts, from onset to termination."},{"id": 5209,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "'Interpulse interval' refers to:","options": [{"key": "A","text": "The duration of a single pulse"},{"key": "B","text": "The amplitude between two pulses"},{"key": "C","text": "The total number of pulses delivered"},{"key": "D","text": "The period of zero current flow between the end of one pulse and the beginning of the next pulse"}],"correct": "D","explanation": "Interpulse interval is the time gap of no current flow occurring between successive pulses."},{"id": 5210,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "'Pulse frequency' (or pulse rate) refers to:","options": [{"key": "A","text": "The number of pulses delivered per second, typically measured in pulses per second (pps) or Hertz (Hz)"},{"key": "B","text": "The duration of a single pulse"},{"key": "C","text": "The amplitude of individual pulses"},{"key": "D","text": "The total treatment duration"}],"correct": "A","explanation": "Pulse frequency describes how many pulses occur per second, expressed in pulses per second (pps) or Hertz (Hz)."},{"id": 5211,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "Amplitude (intensity) of an electrical stimulus refers to:","options": [{"key": "A","text": "The magnitude (peak value) of the current or voltage of the stimulus"},{"key": "B","text": "The frequency of pulse delivery"},{"key": "C","text": "The total charge delivered over an entire treatment session"},{"key": "D","text": "The duration of a single pulse"}],"correct": "A","explanation": "Amplitude describes the peak magnitude of the electrical current or voltage being delivered during stimulation."},{"id": 5212,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "'Rise time' of a pulse refers to:","options": [{"key": "A","text": "The time between successive pulses"},{"key": "B","text": "The time it takes for the pulse to rise from baseline to its peak amplitude"},{"key": "C","text": "The total pulse duration"},{"key": "D","text": "The time from the peak of the pulse to zero"}],"correct": "B","explanation": "Rise time describes how quickly a pulse ascends from zero (baseline) to its maximum amplitude."},{"id": 5213,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "A pulse with a very rapid (steep) rise time is generally associated with:","options": [{"key": "A","text": "A greater likelihood of effectively depolarizing nerve tissue and eliciting a response, since a fast rise time doesn't allow the nerve membrane time to accommodate"},{"key": "B","text": "Reduced likelihood of triggering nerve depolarization"},{"key": "C","text": "No relevance to nerve excitation"},{"key": "D","text": "Only relevance to muscle tissue, not nerves"}],"correct": "A","explanation": "A rapid rise time is more effective at triggering nerve depolarization because it does not give the nerve membrane time to accommodate (adapt) to the gradually rising stimulus, unlike a slow-rising pulse."},{"id": 5214,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "'Accommodation' in the context of nerve excitation refers to the phenomenon in which:","options": [{"key": "A","text": "Nerves become more excitable with slowly rising stimuli"},{"key": "B","text": "Accommodation only applies to muscle tissue, not nerve"},{"key": "C","text": "Nerve tissue is unaffected by the rate of rise of a stimulus"},{"key": "D","text": "A nerve's threshold for excitation increases in response to a slowly rising stimulus, making it less likely to depolarize compared to a rapidly rising stimulus of the same final intensity"}],"correct": "D","explanation": "Accommodation describes the nerve's ability to adapt/raise its threshold when a stimulus rises slowly, making slowly-rising currents less effective at producing depolarization compared to rapidly rising currents of equivalent final amplitude."},{"id": 5215,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "'Rheobase' is defined as:","options": [{"key": "A","text": "The maximum current intensity a tissue can tolerate"},{"key": "B","text": "The minimum pulse duration required to stimulate a tissue at any intensity"},{"key": "C","text": "The time constant of a capacitor"},{"key": "D","text": "The minimum current intensity required to produce a minimal visible/palpable muscle contraction, using a pulse of infinitely long (or very long) duration"}],"correct": "D","explanation": "Rheobase is the minimum current intensity capable of producing a threshold response when applied for a sufficiently long (theoretically infinite) duration."},{"id": 5216,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "'Chronaxie' is defined as:","options": [{"key": "A","text": "The maximum tolerable pulse duration"},{"key": "B","text": "The minimum pulse duration required to stimulate a tissue when the current intensity is set at twice the rheobase value"},{"key": "C","text": "The frequency at which tetanic contraction occurs"},{"key": "D","text": "The minimum current intensity required for stimulation"}],"correct": "B","explanation": "Chronaxie is the minimum time (pulse duration) needed to stimulate excitable tissue when the current intensity is set at double the rheobase."},{"id": 5217,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Chronaxie values are clinically useful primarily because they help to:","options": [{"key": "A","text": "Differentiate between normally innervated and denervated muscle tissue, since denervated muscle typically shows a markedly prolonged chronaxie"},{"key": "B","text": "Measure blood pressure"},{"key": "C","text": "Measure joint range of motion"},{"key": "D","text": "Assess cardiovascular fitness"}],"correct": "A","explanation": "Chronaxie measurement is used in electrodiagnosis to help distinguish normally innervated muscle (short chronaxie) from denervated muscle (which typically shows a significantly prolonged chronaxie due to loss of nerve supply)."},{"id": 5218,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "A denervated muscle (having lost its nerve supply) typically shows which change in its strength-duration curve compared to normal innervated muscle?","options": [{"key": "A","text": "A curve shifted to the right, with a markedly prolonged chronaxie, reflecting the muscle's altered excitability properties following denervation"},{"key": "B","text": "Complete absence of any response regardless of stimulus parameters"},{"key": "C","text": "A curve shifted to the left, with shorter chronaxie"},{"key": "D","text": "No change in the strength-duration curve"}],"correct": "A","explanation": "Denervated muscle displays a strength-duration curve shifted to the right, requiring longer pulse durations (prolonged chronaxie) to achieve a minimal contraction, reflecting altered membrane excitability after loss of nerve supply."},{"id": 5219,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "A strength-duration (SD) curve is a graphical representation of:","options": [{"key": "A","text": "The relationship between stimulus intensity (strength) and the minimum pulse duration required to produce a threshold response"},{"key": "B","text": "The relationship between treatment time and pain relief"},{"key": "C","text": "The relationship between pulse frequency and muscle fatigue"},{"key": "D","text": "The relationship between electrode size and current density"}],"correct": "A","explanation": "The SD curve plots the minimum current intensity needed to produce a threshold (minimal) contraction against varying pulse durations, characterizing tissue excitability."},{"id": 5220,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Capacitance is defined as:","options": [{"key": "A","text": "The total resistance of a circuit"},{"key": "B","text": "The rate of current flow"},{"key": "C","text": "The opposition to current flow"},{"key": "D","text": "The ability of a system/component to store electrical charge"}],"correct": "D","explanation": "Capacitance describes a material or component's capacity to store electric charge when a voltage is applied across it."},{"id": 5221,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "The SI unit of capacitance is the:","options": [{"key": "A","text": "Farad"},{"key": "B","text": "Ohm"},{"key": "C","text": "Henry"},{"key": "D","text": "Watt"}],"correct": "A","explanation": "Capacitance is measured in Farads (F)."},{"id": 5222,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "In the context of the human body, cell membranes exhibit properties analogous to a capacitor primarily because:","options": [{"key": "A","text": "The lipid bilayer acts as an insulating layer separating charged ions on either side, allowing a degree of charge storage and contributing to membrane capacitance relevant to nerve/muscle excitability"},{"key": "B","text": "Cell membranes only conduct current, never store charge"},{"key": "C","text": "Cell membranes have no electrical properties"},{"key": "D","text": "They are perfect conductors with no resistance"}],"correct": "A","explanation": "The insulating lipid bilayer separating intracellular and extracellular ionic charge gives the cell membrane capacitor-like properties, which is relevant to understanding nerve and muscle excitation."},{"id": 5223,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Impedance is best described as:","options": [{"key": "A","text": "A term with no relevance to electrotherapy"},{"key": "B","text": "The total opposition to current flow in an AC circuit, incorporating both resistance and reactance (from capacitive and/or inductive elements)"},{"key": "C","text": "Identical in meaning to resistance with no distinction"},{"key": "D","text": "A term used exclusively for direct current circuits"}],"correct": "B","explanation": "Impedance is the total opposition to alternating current flow, combining resistance with reactance (the opposition due to capacitance and/or inductance), and is relevant to how tissues respond to AC-based therapeutic currents."},{"id": 5224,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "Which of the following best explains why skin resistance/impedance tends to decrease with increased frequency of the applied alternating current?","options": [{"key": "A","text": "Skin resistance is entirely independent of the applied current's characteristics"},{"key": "B","text": "Higher frequency currents always encounter more resistance, not less"},{"key": "C","text": "Frequency has no relationship to tissue impedance"},{"key": "D","text": "Capacitive reactance (a component of tissue impedance related to the skin's capacitor-like properties) decreases as frequency increases, resulting in reduced overall tissue impedance at higher frequencies"}],"correct": "D","explanation": "Since capacitive reactance is inversely related to frequency, higher frequency currents encounter less capacitive opposition from the skin, resulting in reduced overall tissue impedance—relevant to why higher-frequency currents (e.g., in interferential therapy) can achieve deeper, more comfortable penetration."},{"id": 5225,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Series and parallel circuits differ in that, in a series circuit:","options": [{"key": "A","text": "Voltage is identical across all components"},{"key": "B","text": "Components are connected end-to-end along a single path, so the same current flows through each component"},{"key": "C","text": "Total resistance is calculated using reciprocal addition"},{"key": "D","text": "Components are connected along multiple parallel paths"}],"correct": "B","explanation": "In a series circuit, components are connected sequentially along a single path, meaning the same current flows through each component in turn."},{"id": 5226,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "In a parallel circuit:","options": [{"key": "A","text": "Components are connected across common points, providing multiple pathways for current, with the same voltage across each parallel branch"},{"key": "B","text": "Components share a single current pathway"},{"key": "C","text": "Total resistance is calculated by simple addition of individual resistances"},{"key": "D","text": "Current is identical through each component regardless of its resistance"}],"correct": "A","explanation": "In a parallel circuit, multiple branches provide alternative current pathways, with each branch experiencing the same voltage while current divides among the branches according to each branch's resistance."},{"id": 5227,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "The 'law of Grotthus-Draper' in the context of therapeutic electromagnetic energy (e.g., light-based modalities) states that:","options": [{"key": "A","text": "Energy must be reflected to have any biological effect"},{"key": "B","text": "Only energy that is absorbed by tissue can produce a biological/chemical effect; energy that is reflected or transmitted through tissue without absorption produces no effect"},{"key": "C","text": "All energy directed at tissue is automatically therapeutic"},{"key": "D","text": "This law applies exclusively to electrical current, not electromagnetic energy"}],"correct": "B","explanation": "The Grotthus-Draper law states that only absorbed electromagnetic energy can produce a photochemical/biological effect in tissue; reflected or transmitted (non-absorbed) energy has no such effect—relevant to modalities like laser and UV therapy."},{"id": 5228,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "The 'inverse square law' as applied to radiant energy (e.g., infrared, ultraviolet) states that:","options": [{"key": "A","text": "Intensity remains constant regardless of distance from the source"},{"key": "B","text": "This law only applies to electrical current, not radiant energy"},{"key": "C","text": "Intensity of radiation is inversely proportional to the square of the distance from the source, meaning intensity decreases rapidly as distance increases"},{"key": "D","text": "Intensity of radiation is directly proportional to the square of the distance from the source"}],"correct": "C","explanation": "The inverse square law describes how radiant energy intensity diminishes with the square of the distance from its source, an important consideration for appropriate positioning of lamps/radiant sources in electrotherapy."},{"id": 5229,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "The 'cosine law' (Lambert's cosine law), relevant to radiant energy modalities, states that the intensity of radiation striking a surface is greatest when:","options": [{"key": "A","text": "Radiation is always most intense at a 45-degree angle"},{"key": "B","text": "The radiation strikes the surface at an oblique (angled) incidence"},{"key": "C","text": "The angle of incidence has no effect on intensity"},{"key": "D","text": "The radiation strikes the surface perpendicularly (at a 90-degree angle of incidence)"}],"correct": "D","explanation": "The cosine law states that radiant energy intensity on a surface is maximal when the radiation source is positioned perpendicular (90°) to that surface, with intensity decreasing as the angle becomes more oblique."},{"id": 5230,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Electrode size in therapeutic electrical stimulation influences treatment primarily through its effect on:","options": [{"key": "A","text": "Frequency of the stimulus"},{"key": "B","text": "Current density (current per unit area of electrode), where smaller electrodes concentrate current into a smaller area, producing higher current density and potentially more intense/localized effects (and increased risk of skin irritation) compared to larger electrodes at the same total current"},{"key": "C","text": "Total treatment time required"},{"key": "D","text": "Pulse duration exclusively"}],"correct": "B","explanation": "Since current density equals current divided by electrode surface area, smaller electrodes concentrate a given current into a smaller area, resulting in higher current density and more intense localized stimulation, with increased risk of skin irritation compared to larger electrodes carrying the same total current."},{"id": 5231,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "When electrodes of unequal size are used in a circuit (e.g., a small active electrode and a larger dispersive electrode), the current density will be:","options": [{"key": "A","text": "Equal at both electrodes"},{"key": "B","text": "Greater at the smaller electrode, potentially causing a more intense sensation/effect there compared to the larger dispersive electrode"},{"key": "C","text": "Greater at the larger electrode"},{"key": "D","text": "Zero at the smaller electrode"}],"correct": "B","explanation": "With unequal electrode sizes carrying the same total current, the smaller electrode has higher current density, producing a more concentrated, intense effect at that site compared to the larger dispersive electrode."},{"id": 5232,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best explains why moistening the skin or using conductive gel is recommended before applying electrical stimulation electrodes?","options": [{"key": "A","text": "Moisture has no effect on the treatment"},{"key": "B","text": "Moisture increases skin resistance, which is beneficial for treatment"},{"key": "C","text": "This practice is purely for hygiene with no electrical rationale"},{"key": "D","text": "Moisture/gel reduces the skin's electrical resistance (particularly the high-resistance stratum corneum), improving current conduction into the tissue and enhancing patient comfort by avoiding excessive current concentration at high-resistance points"}],"correct": "D","explanation": "Since dry skin (stratum corneum) presents high electrical resistance, moistening the skin or using conductive gel reduces this resistance, improving current flow into underlying tissue and reducing the risk of uncomfortable current concentration or skin irritation."},{"id": 5233,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best summarizes why understanding basic electrical principles (current, voltage, resistance, waveform characteristics) is foundational for safe and effective clinical use of electrotherapy modalities?","options": [{"key": "A","text": "Electrical principles only apply to engineering, not to clinical rehabilitation practice"},{"key": "B","text": "These principles have no practical relevance to clinical practice"},{"key": "C","text": "A solid understanding of these principles allows clinicians to appropriately select, adjust, and safely apply electrotherapy parameters (e.g., intensity, pulse duration, frequency) to achieve desired therapeutic effects while minimizing risk of adverse effects such as burns or excessive discomfort"},{"key": "D","text": "Only manufacturers need to understand these principles, not clinicians"}],"correct": "C","explanation": "A foundational understanding of basic electrical principles enables clinicians to make informed decisions regarding modality selection and parameter settings, optimizing therapeutic benefit while ensuring patient safety during electrotherapy treatment."},{"id": 5234,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best describes 'polarity' in the context of direct current (DC)?","options": [{"key": "A","text": "Polarity only applies to alternating current"},{"key": "B","text": "Polarity changes randomly during DC application"},{"key": "C","text": "DC has a fixed polarity, with one electrode consistently acting as the positive (anode) pole and the other as the negative (cathode) pole for the duration of current flow, which is clinically relevant for techniques like iontophoresis"},{"key": "D","text": "DC has no polarity, unlike AC"}],"correct": "C","explanation": "Direct current maintains a fixed, unidirectional polarity, with consistent anode and cathode designations, which is clinically exploited in techniques such as iontophoresis to drive charged ions in a specific direction."},{"id": 5235,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Galvanic current is best described as:","options": [{"key": "A","text": "A continuous, unidirectional direct current with constant polarity"},{"key": "B","text": "A current that periodically reverses direction"},{"key": "C","text": "A pulsed alternating current"},{"key": "D","text": "A high-frequency current used only in diathermy"}],"correct": "A","explanation": "Galvanic current is a classic term for continuous direct current (DC) that flows unidirectionally with fixed polarity."},{"id": 5236,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Under the positive electrode (anode) during direct current application, which physiological/chemical reaction predominates?","options": [{"key": "A","text": "No chemical reaction occurs at the anode"},{"key": "B","text": "Formation of an acidic reaction (hydrochloric acid formation), leading to hardening/sclerotic effect on tissue, and reduced nerve excitability"},{"key": "C","text": "Only heat production, with no chemical reaction"},{"key": "D","text": "Formation of alkali (sodium hydroxide) with associated tissue softening"}],"correct": "B","explanation": "At the anode, electrolysis produces an acidic reaction (attracting chloride ions to form HCl), which has a hardening (sclerotic) effect on tissue and tends to decrease nerve excitability."},{"id": 5237,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Under the negative electrode (cathode) during direct current application, which physiological/chemical reaction predominates?","options": [{"key": "A","text": "Formation of an alkaline reaction (sodium hydroxide formation), leading to softening of tissue and increased nerve excitability"},{"key": "B","text": "No chemical reaction occurs at the cathode"},{"key": "C","text": "An acidic reaction with tissue hardening"},{"key": "D","text": "Only cooling effect, with no chemical change"}],"correct": "A","explanation": "At the cathode, electrolysis produces an alkaline reaction (sodium hydroxide formation), which softens tissue and tends to increase nerve excitability."},{"id": 5238,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which electrode (anode or cathode) is generally considered to have an analgesic (pain-relieving) effect due to reduced nerve excitability?","options": [{"key": "A","text": "Anode (positive electrode), due to its acidic, sedative effect on nerve tissue"},{"key": "B","text": "Cathode (negative electrode)"},{"key": "C","text": "Neither electrode has any analgesic effect"},{"key": "D","text": "Both electrodes produce identical analgesic effects"}],"correct": "A","explanation": "The anode's acidic chemical effect is associated with decreased nerve excitability, contributing to its traditionally described sedative/analgesic properties in classic galvanic current application."},{"id": 5239,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which electrode (anode or cathode) is generally considered to have a stimulating effect, increasing nerve excitability?","options": [{"key": "A","text": "Cathode, due to its alkaline chemical effect which increases nerve membrane excitability"},{"key": "B","text": "Neither electrode affects nerve excitability"},{"key": "C","text": "Both electrodes produce identical stimulating effects"},{"key": "D","text": "Anode"}],"correct": "A","explanation": "The cathode's alkaline chemical reaction is associated with increased nerve excitability, giving it a traditionally described stimulating effect."},{"id": 5240,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "Iontophoresis is defined as:","options": [{"key": "A","text": "A form of alternating current stimulation for muscle strengthening"},{"key": "B","text": "A technique using ultrasound to enhance drug penetration"},{"key": "C","text": "The use of high-frequency current to generate deep heat"},{"key": "D","text": "The use of a direct current to drive charged ions of a medication through the skin into underlying tissue for therapeutic purposes"}],"correct": "D","explanation": "Iontophoresis utilizes the principle that like charges repel: a DC current drives ions of a charged medication placed under an electrode of the same polarity into the skin and underlying tissue."},{"id": 5241,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "The fundamental electrical principle underlying iontophoresis is:","options": [{"key": "A","text": "Electrical current has no effect on charged particles"},{"key": "B","text": "Like charges attract each other"},{"key": "C","text": "Only alternating current can move ions"},{"key": "D","text": "Like charges repel each other, so a positively charged medication ion is placed under the positive electrode (anode) to be driven into the tissue, and vice versa for negatively charged ions"}],"correct": "D","explanation": "Since like charges repel, a positively charged drug ion is placed beneath the anode (positive electrode) so the electrical field repels/pushes it into the tissue; negatively charged ions are placed under the cathode."},{"id": 5242,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "To administer a positively charged medication ion via iontophoresis, the medication should be placed under which electrode?","options": [{"key": "A","text": "The cathode (negative electrode)"},{"key": "B","text": "Either electrode, as polarity is irrelevant"},{"key": "C","text": "The anode (positive electrode), since like charges repel and will push the positive ion into the tissue"},{"key": "D","text": "The medication should be placed midway between both electrodes"}],"correct": "C","explanation": "A positively charged ion is repelled by the positive electrode (anode), driving it into the tissue when placed beneath that electrode."},{"id": 5243,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "To administer a negatively charged medication ion via iontophoresis, the medication should be placed under which electrode?","options": [{"key": "A","text": "Neither electrode; iontophoresis cannot deliver negatively charged ions"},{"key": "B","text": "The cathode (negative electrode), since like charges repel and will push the negative ion into the tissue"},{"key": "C","text": "Either electrode"},{"key": "D","text": "The anode"}],"correct": "B","explanation": "A negatively charged ion is repelled by the negative electrode (cathode), driving it into the tissue when placed beneath that electrode."},{"id": 5244,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Dexamethasone sodium phosphate, commonly used in iontophoresis for its anti-inflammatory effect, carries which charge, determining its electrode placement?","options": [{"key": "A","text": "No charge; it is a neutral molecule"},{"key": "B","text": "Positive charge, requiring placement under the anode"},{"key": "C","text": "Negative charge, requiring placement under the cathode"},{"key": "D","text": "Variable charge depending on skin pH only"}],"correct": "C","explanation": "Dexamethasone sodium phosphate is negatively charged and is therefore administered from the cathode (negative electrode) during iontophoresis."},{"id": 5245,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Lidocaine hydrochloride, sometimes used in iontophoresis for local anesthetic effect, carries which charge?","options": [{"key": "A","text": "Negative charge, requiring cathodal delivery"},{"key": "B","text": "Positive charge, requiring anodal delivery (placement under the positive electrode)"},{"key": "C","text": "No charge"},{"key": "D","text": "A charge that varies randomly"}],"correct": "B","explanation": "Lidocaine hydrochloride is positively charged and is therefore delivered from the anode during iontophoresis."},{"id": 5246,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "A significant clinical risk associated with direct current application, particularly with prolonged treatment or excessive current density, is:","options": [{"key": "A","text": "Chemical/electrical burns of the skin, due to the sustained unidirectional flow of current and associated electrolytic/chemical reactions at the electrodes"},{"key": "B","text": "Complete absence of any risk"},{"key": "C","text": "Improved circulation with no adverse effects"},{"key": "D","text": "Muscle hypertrophy"}],"correct": "A","explanation": "Because DC current maintains constant polarity and produces ongoing electrolytic chemical reactions at the electrode-skin interface, there is a risk of chemical/electrical burns, particularly with high current density or prolonged application."},{"id": 5247,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following precautions is important to reduce the risk of skin burns during direct current (including iontophoresis) treatment?","options": [{"key": "A","text": "Ensuring even, secure electrode contact, using appropriately sized electrodes to maintain safe current density, and closely monitoring current intensity and treatment duration"},{"key": "B","text": "Avoiding skin inspection before and after treatment"},{"key": "C","text": "Using the smallest possible electrode to concentrate current"},{"key": "D","text": "Increasing current intensity as high as tolerated regardless of sensation"}],"correct": "A","explanation": "Proper electrode sizing/contact and careful monitoring of current density, intensity, and treatment duration are essential precautions to minimize the risk of chemical/electrical burns during DC-based treatments."},{"id": 5248,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Uneven or poor electrode-skin contact during direct current application increases the risk of burns primarily because:","options": [{"key": "A","text": "Poor contact always reduces the therapeutic effect with no safety concern"},{"key": "B","text": "Areas of poor contact experience higher local current density (since current concentrates at points of contact), which can lead to localized tissue damage/burns at those specific points"},{"key": "C","text": "It reduces overall current flow to safe levels"},{"key": "D","text": "Electrode contact quality has no relationship to current density"}],"correct": "B","explanation": "Uneven contact causes current to concentrate at the points of actual electrode-skin contact, creating localized areas of high current density that increase burn risk at those specific points."},{"id": 5249,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Absolute contraindications to iontophoresis/direct current application generally include:","options": [{"key": "A","text": "Known allergy or hypersensitivity to the specific medication ion being used, and broken/damaged skin at the treatment site"},{"key": "B","text": "Mild localized inflammation"},{"key": "C","text": "Chronic pain conditions"},{"key": "D","text": "Normal, intact skin"}],"correct": "A","explanation": "A known allergy to the specific medication being delivered, and open/damaged skin (which alters current flow patterns and increases burn/infection risk), are important contraindications to iontophoresis."},{"id": 5250,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following skin conditions should generally be assessed and considered a caution/contraindication before applying direct current or iontophoresis?","options": [{"key": "A","text": "Skin with cuts, abrasions, recent scars, or significant sensory impairment (reduced ability to report abnormal sensation, increasing burn risk)"},{"key": "B","text": "Well-hydrated, intact skin with no abnormalities"},{"key": "C","text": "Normal, uninjured skin over a muscle belly"},{"key": "D","text": "Skin that has been properly cleaned prior to treatment"}],"correct": "A","explanation": "Broken skin, recent scarring, or areas of impaired sensation (which would prevent the patient from reporting excessive/abnormal sensation) are important considerations that may contraindicate or require caution with DC-based treatments."},{"id": 5251,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "The presence of metal implants (e.g., orthopedic hardware) near the treatment area is generally considered a caution/contraindication for direct current application because:","options": [{"key": "A","text": "Metal always blocks all current flow completely, eliminating any treatment effect"},{"key": "B","text": "Metal is highly conductive and can concentrate current flow, potentially increasing local current density and risk of tissue damage/burns near the implant"},{"key": "C","text": "Metal has no relationship to electrical current flow"},{"key": "D","text": "Metal implants improve current distribution safely with no additional risk"}],"correct": "B","explanation": "Since metal is highly conductive, its presence near the treatment area can cause current to preferentially flow through/around it, potentially concentrating current density and increasing burn risk in the surrounding tissue."},{"id": 5252,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following is generally considered a therapeutic use of direct current (galvanic stimulation), historically and in some current practice?","options": [{"key": "A","text": "Wound healing stimulation (via promotion of cellular migration and other biological effects), iontophoresis for localized drug delivery, and in some cases, denervated muscle stimulation"},{"key": "B","text": "Only for deep heating of tissue"},{"key": "C","text": "Exclusively for pain assessment with no therapeutic application"},{"key": "D","text": "Only muscle strengthening in healthy, normally innervated individuals"}],"correct": "A","explanation": "Direct current has documented therapeutic applications including wound healing stimulation, iontophoretic drug delivery, and (historically, with specific parameters) stimulation of denervated muscle."},{"id": 5253,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "Which of the following best explains why direct current, rather than typical pulsed or alternating current, has historically been used for stimulation of denervated muscle in certain contexts?","options": [{"key": "A","text": "Alternating current is always more effective for denervated muscle than direct current"},{"key": "B","text": "Denervated muscle has altered excitability properties (prolonged chronaxie) and generally requires a current with a sufficiently long duration/slow rise, which is a characteristic more readily achieved with certain DC-based (interrupted galvanic) stimulation parameters, compared to typical short-duration pulsed currents designed for normally innervated muscle/nerve"},{"key": "C","text": "Direct current cannot stimulate any muscle tissue under any circumstances"},{"key": "D","text": "Denervated muscle responds identically to all current types with no difference"}],"correct": "B","explanation": "Given denervated muscle's prolonged chronaxie and altered excitability (requiring longer duration stimuli for effective depolarization since the muscle itself, not the nerve, must be directly stimulated), certain interrupted galvanic/DC-based protocols with appropriately long pulse durations have historically been used, in contrast to typical short-duration currents effective for normally innervated tissue."},{"id": 5254,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "The term 'galvanotaxis' refers to the phenomenon in which:","options": [{"key": "A","text": "Certain cells (e.g., involved in wound healing, such as fibroblasts, keratinocytes, and inflammatory cells) demonstrate directed migration in response to an applied electrical field, which is thought to contribute to the wound-healing effects of direct current stimulation"},{"key": "B","text": "Galvanotaxis refers exclusively to muscle contraction"},{"key": "C","text": "Cells are unaffected by electrical fields"},{"key": "D","text": "Only nerve cells respond to electrical fields"}],"correct": "A","explanation": "Galvanotaxis describes the directed migration of certain cell types in response to an electrical field, a phenomenon thought to underlie some of the proposed wound-healing benefits of direct current electrical stimulation."},{"id": 5255,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "'High-volt pulsed current' (HVPC), sometimes used in wound care and pain management, is technically classified as a form of:","options": [{"key": "A","text": "Continuous alternating current"},{"key": "B","text": "Low-voltage biphasic current only"},{"key": "C","text": "Monophasic pulsed current, characterized by twin-peaked (paired) pulses of very short duration and relatively high voltage/amplitude"},{"key": "D","text": "Direct current with continuous, unbroken flow"}],"correct": "C","explanation": "HVPC uses monophasic, twin-peaked pulses of very short duration delivered at relatively high voltage, distinguishing it from continuous galvanic (DC) current while still maintaining unidirectional polarity characteristics that can be clinically relevant for certain applications like wound care."},{"id": 5256,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "Which of the following best describes a key clinical advantage of HVPC's very short pulse duration (typically measured in microseconds) compared to continuous galvanic current, particularly regarding patient comfort?","options": [{"key": "A","text": "Short pulse duration always increases discomfort compared to continuous current"},{"key": "B","text": "Short-duration pulses cannot produce any therapeutic effect"},{"key": "C","text": "The very brief pulse duration reduces the total electrical charge delivered per pulse, generally allowing for more comfortable application at higher peak amplitudes compared to continuous DC, while still achieving therapeutic depolarization"},{"key": "D","text": "Pulse duration has no relationship to patient comfort during stimulation"}],"correct": "C","explanation": "Because the very brief pulse duration of HVPC limits the total charge delivered per pulse, higher peak amplitudes can often be applied more comfortably compared to continuous galvanic current, while still achieving effective tissue stimulation."},{"id": 5257,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "Which of the following best describes the general clinical dosage consideration (current intensity/density) recommended for iontophoresis treatments to balance efficacy with safety?","options": [{"key": "A","text": "Current density is generally kept within established safe limits (often cited around 0.5 mA/cm² or lower for the active electrode, depending on specific device/protocol guidelines), balancing adequate ion delivery against the risk of skin irritation or burns"},{"key": "B","text": "Current intensity has no relationship to treatment safety"},{"key": "C","text": "Maximum tolerable intensity should always be used regardless of any dosage guidelines"},{"key": "D","text": "There are no established dosage considerations for iontophoresis"}],"correct": "A","explanation": "Iontophoresis protocols generally follow established safe current density guidelines (commonly cited limits around or below approximately 0.5 mA/cm² for the active electrode, varying by specific device/protocol) to balance effective ion delivery with minimizing risk of skin irritation or burns."},{"id": 5258,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the biophysical basis for using a buffer electrode/reservoir system in modern iontophoresis devices?","options": [{"key": "A","text": "Buffer electrodes eliminate the need for any current flow"},{"key": "B","text": "Buffer electrode systems are designed to help control/minimize the pH changes and byproducts (e.g., acid/alkali formation) that occur during electrolysis at the electrode-skin interface, reducing risk of chemical skin irritation compared to using bare metal electrodes directly on the skin"},{"key": "C","text": "Buffer systems increase the risk of chemical burns compared to bare electrodes"},{"key": "D","text": "Buffer systems have no functional purpose"}],"correct": "B","explanation": "Modern iontophoresis electrode/reservoir systems are designed to help manage and buffer the pH changes and electrolytic byproducts generated during treatment, reducing the risk of chemical skin irritation compared to using unbuffered bare metal electrodes."},{"id": 5259,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Total charge delivered during iontophoresis is generally calculated as the product of:","options": [{"key": "A","text": "Current intensity (mA) and treatment time (minutes), often expressed in units of mA-minutes, which is a key dosage parameter for iontophoresis protocols"},{"key": "B","text": "Electrode size alone"},{"key": "C","text": "Frequency and pulse duration only"},{"key": "D","text": "Voltage and resistance only"}],"correct": "A","explanation": "Iontophoresis dosage is commonly quantified in mA-minutes, calculated as current intensity (mA) multiplied by treatment duration (minutes), reflecting the total electrical charge delivered."},{"id": 5260,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "If an iontophoresis treatment is delivered at 4 mA for 10 minutes, the total dosage delivered is:","options": [{"key": "A","text": "14 mA-minutes"},{"key": "B","text": "40 mA-minutes"},{"key": "C","text": "4 mA-minutes"},{"key": "D","text": "2.5 mA-minutes"}],"correct": "B","explanation": "Dosage (mA-minutes) = current (mA) × time (minutes) = 4 × 10 = 40 mA-minutes."},{"id": 5261,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following patient populations would generally warrant additional caution or be considered a relative contraindication for iontophoresis due to potential cardiac risk if electrodes were placed transthoracically or near implanted cardiac devices?","options": [{"key": "A","text": "Patients with no significant medical history"},{"key": "B","text": "Patients with an intact, healthy cardiovascular system and no implanted devices"},{"key": "C","text": "Iontophoresis has no cardiac-related contraindications regardless of patient history"},{"key": "D","text": "Patients with cardiac pacemakers or implantable cardioverter-defibrillators, due to the theoretical risk of electrical interference with the device if current is applied near it"}],"correct": "D","explanation": "As with many forms of electrical stimulation, patients with implanted cardiac devices (pacemakers, ICDs) warrant caution due to the theoretical risk of electrical interference if treatment is applied in proximity to the device or in a transthoracic current pathway."},{"id": 5262,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best describes why pregnancy is generally considered a contraindication for direct current/iontophoresis application over or near the abdominal/pelvic/lumbar region?","options": [{"key": "A","text": "This precaution only applies to alternating current, not direct current"},{"key": "B","text": "There is no established concern regarding electrical stimulation during pregnancy"},{"key": "C","text": "Electrical current has been definitively proven completely safe for fetal development in all circumstances"},{"key": "D","text": "The potential effects of electrical current on a developing fetus are not well established, so as a precaution, treatment over the abdomen, pelvis, or lumbar spine is generally avoided during pregnancy"}],"correct": "D","explanation": "Given the uncertain and not well-established effects of electrical stimulation on fetal development, standard precaution avoids applying direct current or other electrical stimulation over the abdomen, pelvis, or low back region during pregnancy."},{"id": 5263,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Malignancy (active cancer) in or near the treatment area is generally considered a contraindication to direct current stimulation and most other electrotherapy modalities primarily due to:","options": [{"key": "A","text": "Malignant tissue is completely unresponsive to any electrical current"},{"key": "B","text": "No established concern; electrical stimulation is always safe over malignant tissue"},{"key": "C","text": "Theoretical concerns that increased local blood flow/cellular activity stimulated by the treatment could potentially promote tumor growth or metastatic spread, though definitive evidence is limited; this remains a standard precautionary contraindication"},{"key": "D","text": "This contraindication only applies to modalities other than direct current"}],"correct": "C","explanation": "As a standard precaution across most electrotherapy modalities, treatment over or near known malignancy is generally avoided due to theoretical concerns about stimulating increased local blood flow/cellular activity that could potentially influence tumor behavior, even though definitive clinical evidence is limited."},{"id": 5264,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Areas of active or recent hemorrhage are generally considered a contraindication to direct current and most electrotherapy modalities primarily because:","options": [{"key": "A","text": "Electrical stimulation has no effect on bleeding tissue"},{"key": "B","text": "Electrical stimulation always stops all bleeding immediately"},{"key": "C","text": "This is only a concern for alternating current, not direct current"},{"key": "D","text": "Increased local blood flow/circulation stimulated by treatment could potentially exacerbate bleeding in an area of active or recent hemorrhage"}],"correct": "D","explanation": "Since many electrotherapy modalities can increase local blood flow, treatment over areas of active or very recent hemorrhage is generally avoided due to the theoretical risk of exacerbating bleeding."},{"id": 5265,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Deep vein thrombosis (DVT) or suspected DVT in the treatment area is generally considered a contraindication to electrical stimulation modalities primarily because:","options": [{"key": "A","text": "Electrical stimulation always dissolves blood clots safely"},{"key": "B","text": "There is no established concern regarding DVT and electrotherapy"},{"key": "C","text": "This contraindication is specific only to iontophoresis, not other electrical modalities"},{"key": "D","text": "Increased local circulation and/or muscle contraction from stimulation could theoretically dislodge a thrombus, risking embolism"}],"correct": "D","explanation": "Due to the theoretical risk that increased local circulation or muscle contraction could dislodge a thrombus and cause embolism, treatment over an area of known or suspected DVT is generally contraindicated across most electrical stimulation modalities."},{"id": 5266,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Areas of active infection are generally considered a contraindication to direct current stimulation primarily because:","options": [{"key": "A","text": "This is a concern only for iontophoresis, not general galvanic stimulation"},{"key": "B","text": "Electrical stimulation has no relationship to infection spread"},{"key": "C","text": "Increased local circulation stimulated by treatment could theoretically promote the spread of infection to surrounding tissue"},{"key": "D","text": "Electrical stimulation always eliminates infection completely"}],"correct": "C","explanation": "Similar to the rationale for other vascular-related precautions, increased local circulation from stimulation could theoretically promote spread of an active infection, making this a standard contraindication."},{"id": 5267,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "Which of the following best describes the concept of 'polarity effect' as a distinguishing feature of direct current compared to alternating or most pulsed currents?","options": [{"key": "A","text": "Because direct current maintains fixed polarity over time, it produces sustained, direction-specific chemical/physiological effects at each electrode (e.g., acidic/sclerotic at anode, alkaline/stimulating at cathode), a distinguishing feature not typically seen with balanced biphasic/alternating currents where such polarity-specific chemical effects are minimized or absent"},{"key": "B","text": "Alternating current produces identical polarity effects to direct current"},{"key": "C","text": "Polarity effect has no clinical relevance in electrotherapy"},{"key": "D","text": "Polarity effect refers to a phenomenon exclusive to alternating current"}],"correct": "A","explanation": "The sustained fixed polarity of direct current produces distinctive, direction-dependent chemical and physiological effects at each electrode over time, a characteristic not typically observed with balanced biphasic currents, where the alternating polarity largely cancels out such sustained polarity-specific effects."},{"id": 5268,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best explains why continuous direct current is generally used cautiously and for relatively short treatment durations, compared to some pulsed current modalities used for longer sessions?","options": [{"key": "A","text": "Treatment duration has no bearing on the safety of direct current application"},{"key": "B","text": "Direct current has no time-related safety considerations"},{"key": "C","text": "Direct current is inherently safer for longer durations than pulsed current"},{"key": "D","text": "The sustained, uninterrupted flow of DC produces ongoing electrolytic/chemical changes at the electrode-skin interface, and prolonged exposure increases cumulative risk of chemical burns/skin irritation compared to interrupted pulsed currents which allow tissue recovery time between pulses"}],"correct": "D","explanation": "Since continuous DC produces ongoing, uninterrupted electrolytic changes at the electrodes, longer treatment durations increase the cumulative risk of chemical skin irritation/burns, in contrast to pulsed currents which have interpulse intervals allowing some tissue recovery."},{"id": 5269,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general purpose of performing a 'skin patch test' or checking for medication sensitivity before administering iontophoresis with a specific drug?","options": [{"key": "A","text": "To screen for potential allergic/hypersensitivity reactions to the specific medication ion being delivered, since iontophoresis introduces the medication systemically/locally and an unrecognized allergy could result in an adverse reaction"},{"key": "B","text": "This step is unnecessary and never performed in clinical practice"},{"key": "C","text": "This test assesses only electrical, not chemical, sensitivity"},{"key": "D","text": "Skin patch testing is only relevant for oral medications, not iontophoresis"}],"correct": "A","explanation": "Screening for medication allergy/sensitivity before iontophoresis is an important safety consideration, since the treatment introduces the specific pharmacological agent into the patient's tissue, and an unrecognized allergy could provoke an adverse reaction."},{"id": 5270,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the general evidence-based perspective on the depth of tissue penetration typically achieved by iontophoresis?","options": [{"key": "A","text": "Iontophoresis has no capacity to deliver any medication into tissue"},{"key": "B","text": "Iontophoresis is generally understood to deliver medication primarily to relatively superficial tissue depths, with the exact depth and clinical efficacy for various conditions remaining an area of ongoing research and some debate"},{"key": "C","text": "Depth of penetration is entirely unrelated to any treatment parameters"},{"key": "D","text": "Iontophoresis reliably delivers medication to deep structures several centimeters below the skin, equivalent to injection"}],"correct": "B","explanation": "Current understanding suggests iontophoresis primarily achieves relatively superficial tissue penetration, and questions remain in the research literature regarding the precise depth of effective delivery and resulting clinical efficacy for various conditions, informing appropriate patient selection and expectation-setting."},{"id": 5271,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best summarizes the primary distinguishing clinical rationale for choosing iontophoresis over a standard topical medication application for localized drug delivery?","options": [{"key": "A","text": "Iontophoresis always delivers less medication than simple topical application"},{"key": "B","text": "Iontophoresis is proposed to enhance transdermal drug delivery beyond what passive topical absorption alone would achieve, by using an electrical driving force to actively transport charged medication ions through the skin, potentially improving local tissue drug concentration compared to passive absorption alone"},{"key": "C","text": "Topical application and iontophoresis use entirely different medications with no overlap"},{"key": "D","text": "There is no meaningful difference between iontophoresis and simple topical application"}],"correct": "B","explanation": "The proposed clinical advantage of iontophoresis lies in its active electrical transport mechanism, which is theorized to enhance transdermal delivery of charged medication ions beyond what would be achieved through passive topical absorption alone."},{"id": 5272,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best describes appropriate patient education regarding sensations to expect and report during direct current/iontophoresis treatment?","options": [{"key": "A","text": "Burning sensation is a normal, expected part of treatment that should not be reported"},{"key": "B","text": "Patients should expect no sensation whatsoever during treatment"},{"key": "C","text": "Patients should be informed that a mild tingling or prickling sensation is generally expected, but should be instructed to immediately report any sharp, burning, or excessively uncomfortable sensation, which may indicate excessive current density or inadequate electrode contact requiring immediate adjustment"},{"key": "D","text": "Any sensation reported by the patient should be ignored to ensure adequate dosage is delivered"}],"correct": "C","explanation": "Proper patient education includes setting expectations for a mild tingling sensation while emphasizing the importance of immediately reporting any sharp or burning sensation, which could indicate a safety concern requiring prompt intervention."},{"id": 5273,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best explains the clinical rationale for gradually increasing (ramping) current intensity at the start of a direct current/iontophoresis treatment, rather than immediately applying the full target intensity?","options": [{"key": "A","text": "Gradual increase allows patient tolerance to be assessed progressively and reduces the likelihood of triggering an uncomfortable or excessive sensory/pain response that could occur with an abrupt jump to full intensity"},{"key": "B","text": "Immediate full-intensity application is always preferred for efficacy with no downside"},{"key": "C","text": "Ramping intensity only applies to alternating current, not direct current"},{"key": "D","text": "Gradual ramping has no clinical rationale and is unnecessary"}],"correct": "A","explanation": "Gradually increasing current intensity allows the clinician to continuously monitor and titrate to the patient's individual tolerance, reducing the risk of provoking an uncomfortable or excessive response that might occur with an abrupt application of full target intensity."},{"id": 5274,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best describes an appropriate post-treatment skin check following direct current or iontophoresis application?","options": [{"key": "A","text": "Skin inspection is unnecessary after treatment"},{"key": "B","text": "Skin checks are only relevant for alternating current treatments, not direct current"},{"key": "C","text": "Only the electrode itself needs to be inspected, not the patient's skin"},{"key": "D","text": "The treatment area should be inspected for any signs of excessive redness (erythema beyond mild, expected reaction), blistering, or other skin irritation, which would warrant documentation and modification of subsequent treatment parameters"}],"correct": "D","explanation": "Post-treatment skin inspection is an important safety practice to identify any excessive skin reaction (beyond the mild, expected redness), which would need to be documented and considered when planning any subsequent treatment."},{"id": 5275,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical role of direct current-based modalities (including iontophoresis) within a comprehensive physiotherapy treatment plan?","options": [{"key": "A","text": "Direct current modalities have no legitimate clinical role in modern physiotherapy practice"},{"key": "B","text": "Direct current modalities are always the primary and sole intervention needed for all conditions"},{"key": "C","text": "Direct current-based modalities can serve as a useful adjunct within a broader treatment plan (e.g., for localized anti-inflammatory drug delivery via iontophoresis, or wound healing support), but should be applied with appropriate clinical reasoning, patient selection, and integration with other evidence-based interventions such as exercise and manual therapy"},{"key": "D","text": "Direct current is only ever used in isolation, never combined with other treatment approaches"}],"correct": "C","explanation": "Direct current-based modalities, including iontophoresis, are generally most appropriately used as an adjunct within a comprehensive, individualized treatment plan, integrated thoughtfully alongside other evidence-based interventions rather than as a standalone solution."},{"id": 5276,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the term 'electrophoresis' as it relates to iontophoresis?","options": [{"key": "A","text": "Electrophoresis refers exclusively to muscle stimulation, not ion movement"},{"key": "B","text": "Electrophoresis broadly refers to the movement of charged particles under the influence of an electric field, a principle that underlies (and is sometimes used interchangeably in older literature with) the clinical technique of iontophoresis for driving charged medication ions into tissue"},{"key": "C","text": "Electrophoresis only applies to laboratory diagnostic techniques, never clinical treatment"},{"key": "D","text": "Electrophoresis and iontophoresis are entirely unrelated concepts"}],"correct": "B","explanation": "Electrophoresis describes the general physical principle of charged particle movement under an electric field, which forms the theoretical basis for the clinical application known as iontophoresis."},{"id": 5277,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following medications is commonly cited as being delivered via iontophoresis for its local anti-inflammatory effect in conditions such as tendinopathy or bursitis?","options": [{"key": "A","text": "Only antihypertensive medications"},{"key": "B","text": "Dexamethasone sodium phosphate, a corticosteroid commonly used for its local anti-inflammatory properties"},{"key": "C","text": "Only oral analgesics, which cannot be delivered via iontophoresis"},{"key": "D","text": "Only antibiotics"}],"correct": "B","explanation": "Dexamethasone sodium phosphate is a commonly cited corticosteroid used in iontophoresis protocols aimed at delivering local anti-inflammatory effects for conditions such as tendinopathy or bursitis."},{"id": 5278,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Acetic acid (used in iontophoresis for conditions such as calcific tendinopathy) carries which charge, determining its electrode placement?","options": [{"key": "A","text": "A charge that varies unpredictably"},{"key": "B","text": "Negative charge, requiring cathodal delivery, based on theorized effects on calcium deposit dissolution"},{"key": "C","text": "Positive charge, requiring anodal delivery"},{"key": "D","text": "No charge at all"}],"correct": "B","explanation": "Acetic acid is negatively charged and is therefore administered from the cathode, with proposed (though not definitively proven) effects related to facilitating dissolution of calcific deposits."},{"id": 5279,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why iontophoresis treatment protocols typically specify a maximum recommended treatment duration (e.g., commonly cited ranges such as 10-40 minutes depending on device/protocol) rather than unlimited treatment time?","options": [{"key": "A","text": "Treatment duration limits only apply to alternating current modalities"},{"key": "B","text": "There is no relationship between treatment duration and safety in iontophoresis"},{"key": "C","text": "Longer treatment durations always improve efficacy with no safety trade-off"},{"key": "D","text": "Since total charge delivered (and associated cumulative chemical/electrolytic effects at the skin) increases with treatment duration, limiting the treatment time helps keep the total delivered dosage and associated skin reaction within safe, tolerable limits"}],"correct": "D","explanation": "Since cumulative electrolytic/chemical effects at the skin increase with total charge delivered (a function of both intensity and time), treatment duration limits are established to keep the overall dosage within safe limits while balancing therapeutic efficacy."},{"id": 5280,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is generally considered good clinical practice regarding electrode reservoir/pad preparation prior to iontophoresis treatment?","options": [{"key": "A","text": "Reservoir preparation has no bearing on treatment safety or efficacy"},{"key": "B","text": "The medication reservoir/pad should be prepared according to manufacturer and prescribed protocol guidelines regarding drug concentration and volume, to ensure both treatment efficacy and safety"},{"key": "C","text": "Any medication can be substituted freely without considering its specific compatibility with the iontophoresis device"},{"key": "D","text": "Reservoirs should be loaded with the maximum possible drug concentration regardless of manufacturer guidelines"}],"correct": "B","explanation": "Following established manufacturer and clinical protocol guidelines for medication concentration and reservoir preparation is important for ensuring both the intended therapeutic effect and patient safety during iontophoresis."},{"id": 5281,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes a key difference between traditional iontophoresis using external power supplies/leads and newer self-contained, wearable iontophoresis patch systems?","options": [{"key": "A","text": "Wearable patch systems cannot deliver any medication ions"},{"key": "B","text": "There is no meaningful difference between the two delivery systems"},{"key": "C","text": "Traditional lead-based systems are always safer than wearable patch systems"},{"key": "D","text": "Wearable patch systems typically use a low, constant, self-contained current source integrated into an adhesive patch, allowing more prolonged, portable treatment (e.g., over several hours) compared to traditional clinic-based systems using external leads and typically shorter treatment sessions"}],"correct": "D","explanation": "Modern wearable iontophoresis patches integrate a low-level, self-contained current source directly into an adhesive delivery system, enabling more prolonged and portable treatment compared to traditional clinic-based systems that use external power supplies and leads over shorter sessions."},{"id": 5282,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best describes why careful, symmetric electrode placement (e.g., avoiding placement directly over bony prominences with minimal soft tissue) is recommended for direct current/iontophoresis application?","options": [{"key": "A","text": "Bony prominences are always the ideal electrode placement site for maximum efficacy"},{"key": "B","text": "Areas with minimal soft tissue over bony prominences may have altered current density/distribution and increased risk of discomfort or skin irritation compared to areas with more substantial soft tissue coverage"},{"key": "C","text": "Electrode placement is determined randomly with no clinical rationale"},{"key": "D","text": "Electrode placement has no bearing on patient comfort or safety"}],"correct": "B","explanation": "Careful attention to electrode placement, including avoiding areas with minimal soft tissue coverage over bony prominences, helps reduce the risk of altered current distribution and associated discomfort or skin irritation."},{"id": 5283,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best summarizes the overall strength of current research evidence supporting the clinical efficacy of iontophoresis for various musculoskeletal conditions?","options": [{"key": "A","text": "Research evidence for iontophoresis efficacy varies by condition and specific medication used, with some studies showing modest benefit and others showing limited or inconclusive results, reflecting an area where clinical decision-making should integrate available evidence with individual patient factors"},{"key": "B","text": "Iontophoresis has been conclusively proven ineffective for all conditions studied"},{"key": "C","text": "There is no research evidence whatsoever regarding iontophoresis efficacy"},{"key": "D","text": "Research evidence is universally strong and conclusively supports iontophoresis as a first-line treatment for all musculoskeletal conditions"}],"correct": "A","explanation": "The evidence base for iontophoresis efficacy is mixed and condition/medication-dependent, with some studies showing modest benefit and others showing limited or inconclusive findings, highlighting the importance of integrating available evidence with clinical judgment and individual patient factors when considering this modality."},{"id": 5284,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration when selecting candidates for iontophoresis based on skin integrity and sensation?","options": [{"key": "A","text": "Only patients with impaired sensation should be selected for iontophoresis, to avoid discomfort"},{"key": "B","text": "Skin and sensory assessment is only relevant for alternating current treatments"},{"key": "C","text": "Skin integrity and sensation have no bearing on candidate selection for iontophoresis"},{"key": "D","text": "Patients should have intact skin without significant lesions/wounds at the treatment site (unless using a wound-specific protocol) and adequate sensory function to reliably report abnormal or excessive sensation during treatment, both important for treatment safety"}],"correct": "D","explanation": "Appropriate candidate selection for iontophoresis includes confirming intact skin integrity (for standard protocols) and adequate sensory function, since the patient's ability to reliably report abnormal sensation is an important safety mechanism during treatment."},{"id": 5285,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Easy","question": "Faradic current, in classical electrotherapy terminology, refers to:","options": [{"key": "A","text": "A current used only for iontophoresis"},{"key": "B","text": "An interrupted, asymmetrical (or symmetrical) pulsed current traditionally used to stimulate contraction of normally innervated (neurologically intact) skeletal muscle"},{"key": "C","text": "A continuous direct current"},{"key": "D","text": "A high-frequency current used exclusively for deep heating"}],"correct": "B","explanation": "Faradic current classically describes an interrupted pulsed current, historically used to produce contraction of normally innervated skeletal muscle via stimulation of the motor nerve."},{"id": 5286,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Easy","question": "Neuromuscular electrical stimulation (NMES) is defined as:","options": [{"key": "A","text": "The use of ultrasound to stimulate muscle"},{"key": "B","text": "A technique used only for pain modulation with no motor effect"},{"key": "C","text": "Electrical stimulation applied to elicit a muscle contraction via activation of the peripheral motor nerve (or, in some cases, direct muscle stimulation), typically used for strengthening, re-education, or reducing atrophy"},{"key": "D","text": "A form of continuous direct current used for iontophoresis"}],"correct": "C","explanation": "NMES uses electrical current to stimulate motor nerves (most commonly) to produce a functional muscle contraction, applied for goals such as strengthening, motor re-education, or preventing/reducing disuse atrophy."},{"id": 5287,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "NMES typically produces muscle contraction primarily by stimulating:","options": [{"key": "A","text": "Only the neuromuscular junction's postsynaptic receptors directly"},{"key": "B","text": "Sensory nerve fibers only, with no motor effect"},{"key": "C","text": "Directly stimulating denervated muscle fibers exclusively"},{"key": "D","text": "The motor nerve (alpha motor neuron axons), which is more easily depolarized (has a lower threshold) than muscle fibers themselves in normally innervated muscle"}],"correct": "D","explanation": "In normally innervated muscle, motor nerve axons have a lower depolarization threshold than muscle fibers, so NMES typically produces contraction by stimulating the motor nerve rather than directly depolarizing muscle tissue."},{"id": 5288,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which type of nerve fiber is generally recruited FIRST (at lowest stimulus intensity) during electrical stimulation, according to the size principle as it applies to artificial (electrical) stimulation?","options": [{"key": "A","text": "Small-diameter, deeper motor nerve fibers"},{"key": "B","text": "Fibers are recruited in a completely random, unpredictable pattern"},{"key": "C","text": "Large-diameter nerve fibers located superficially (closer to the electrode), since electrical stimulation tends to preferentially recruit larger, more superficial fibers first, in a pattern that can differ from the natural (voluntary) size-based recruitment order"},{"key": "D","text": "Only sensory C-fibers"}],"correct": "C","explanation": "Unlike natural voluntary recruitment, electrical stimulation tends to preferentially activate larger-diameter, more superficially located nerve fibers first, since they generally have lower electrical thresholds and are typically closer to the stimulating electrode."},{"id": 5289,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes how electrically-induced muscle recruitment order can differ from the normal physiological (voluntary) recruitment order (Henneman's size principle)?","options": [{"key": "A","text": "Recruitment order has no clinical relevance to NMES application"},{"key": "B","text": "Voluntary contraction typically recruits smaller, fatigue-resistant motor units first (progressing to larger units with increasing effort), whereas electrical stimulation tends to preferentially recruit larger, more fatigable motor units at lower relative intensities, contributing to the comparatively rapid fatigue sometimes observed with NMES"},{"key": "C","text": "Both follow identical recruitment patterns with no meaningful difference"},{"key": "D","text": "Electrical stimulation always recruits smaller motor units first, identical to voluntary contraction"}],"correct": "B","explanation": "This reversed/non-physiological recruitment pattern (larger, more fatigable units activated relatively early with electrical stimulation) is a key reason why NMES-induced contractions can fatigue more quickly than equivalent voluntary contractions, an important clinical consideration for stimulation parameter selection."},{"id": 5290,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Common clinical indications for NMES include all of the following EXCEPT:","options": [{"key": "A","text": "Muscle re-education/facilitation (e.g., quadriceps activation after knee surgery)"},{"key": "B","text": "Increasing active range of motion by direct stimulation and augmentation of muscle strength/endurance"},{"key": "C","text": "Prevention or reduction of disuse muscle atrophy (e.g., following injury/immobilization)"},{"key": "D","text": "Definitive, curative treatment of complete peripheral nerve lesions with no other intervention needed"}],"correct": "D","explanation": "While NMES can be a valuable adjunct for various goals (atrophy prevention, re-education, strengthening), it is not considered a standalone curative treatment for complete peripheral nerve lesions, which require broader, comprehensive management."},{"id": 5291,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "NMES applied to the quadriceps muscle following knee surgery (e.g., ACL reconstruction) is commonly used clinically primarily to:","options": [{"key": "A","text": "Help counteract quadriceps activation deficits (arthrogenic muscle inhibition) and reduce associated atrophy, often used as an adjunct alongside voluntary exercise"},{"key": "B","text": "Increase joint range of motion directly through passive stretching"},{"key": "C","text": "Replace the need for any voluntary exercise entirely"},{"key": "D","text": "Only provide pain relief, with no effect on muscle strength"}],"correct": "A","explanation": "NMES is commonly used post-surgically to help address quadriceps activation deficits related to arthrogenic muscle inhibition and to help mitigate associated disuse atrophy, typically as an adjunct to (not a replacement for) voluntary exercise."},{"id": 5292,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "'Arthrogenic muscle inhibition' refers to the phenomenon in which:","options": [{"key": "A","text": "Muscle strength is unaffected by joint pathology"},{"key": "B","text": "Only voluntary muscle weakness occurs, unrelated to any joint pathology"},{"key": "C","text": "Joint pathology/effusion/injury leads to a reflexive, ongoing inhibition of surrounding muscle activation (particularly quadriceps around the knee), contributing to muscle weakness that may not fully resolve with voluntary exercise alone"},{"key": "D","text": "This phenomenon only occurs in denervated muscle"}],"correct": "C","explanation": "Arthrogenic muscle inhibition describes a reflex-mediated reduction in muscle activation capacity secondary to joint pathology (e.g., effusion, injury), which can persist despite the muscle itself remaining structurally and neurologically intact, and is a key rationale for using NMES to help overcome this inhibition."},{"id": 5293,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "For an NMES protocol aimed at muscle strengthening, which combination of parameters is generally recommended to produce a strong, tetanic contraction capable of producing strength gains?","options": [{"key": "A","text": "Very low frequency (e.g., 1-2 pps) with long rest periods only"},{"key": "B","text": "A pulse frequency sufficient to produce smooth tetanic contraction (commonly cited in ranges around 35-50 pps or higher, depending on protocol), sufficient intensity to recruit an adequate proportion of muscle fibers, and adequate on/off (duty cycle) timing to manage fatigue"},{"key": "C","text": "Frequency has no relevance to the strength of contraction produced"},{"key": "D","text": "Continuous, unbroken current with no on/off cycling at any frequency"}],"correct": "B","explanation": "Effective NMES strengthening protocols typically use a frequency sufficient for smooth tetanic contraction, adequate intensity for meaningful fiber recruitment, and an appropriate on/off duty cycle to balance contraction strength against fatigue."},{"id": 5294,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "A pulse frequency of approximately 1-10 pps (pulses per second) during electrical stimulation typically produces which type of muscle response?","options": [{"key": "A","text": "No muscle response whatsoever"},{"key": "B","text": "Individual muscle twitches, as the frequency is too low to produce fusion (summation) into a smooth tetanic contraction"},{"key": "C","text": "A smooth, fused tetanic contraction"},{"key": "D","text": "A response identical to that produced at 50 pps"}],"correct": "B","explanation": "At low frequencies (approximately 1-10 pps), individual muscle twitches remain discernible rather than fusing into a smooth, sustained (tetanic) contraction."},{"id": 5295,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "As stimulation frequency increases (e.g., toward and beyond approximately 20-50 pps, depending on the muscle), individual twitches progressively:","options": [{"key": "A","text": "Disappear entirely with no contraction produced"},{"key": "B","text": "Undergo increasing summation, eventually fusing into a smooth, sustained tetanic contraction once a sufficient frequency ('fusion frequency') is reached"},{"key": "C","text": "Become more distinct and separated"},{"key": "D","text": "Are unaffected by frequency changes"}],"correct": "B","explanation": "As frequency increases, successive twitches summate more completely, eventually fusing into a smooth tetanic contraction once the muscle's fusion frequency threshold is reached."},{"id": 5296,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "'Duty cycle' in the context of NMES refers to:","options": [{"key": "A","text": "The total treatment session duration"},{"key": "B","text": "The ratio of 'on time' (active stimulation) to the total cycle time (on time plus off time), often expressed as a ratio (e.g., 1:3) or percentage"},{"key": "C","text": "The pulse duration of individual pulses"},{"key": "D","text": "The frequency of stimulation"}],"correct": "B","explanation": "Duty cycle describes the proportion of time the current is actively 'on' (stimulating) relative to the total on-plus-off cycle time, expressed as a ratio or percentage (e.g., a 1:3 ratio means 'on' time is one-third the length of 'off' time, or specific % on-time notation may be used depending on convention)."},{"id": 5297,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "A relatively low duty cycle (e.g., a longer 'off' time relative to 'on' time, such as 1:3 or 1:5 ratio) during NMES treatment is generally used primarily to:","options": [{"key": "A","text": "Reduce the intensity of each individual contraction"},{"key": "B","text": "Allow adequate rest between contractions, helping to delay the onset of muscle fatigue and permit a greater total volume of effective contractions during the treatment session"},{"key": "C","text": "Eliminate the need for any rest periods"},{"key": "D","text": "Increase overall muscle fatigue as quickly as possible"}],"correct": "B","explanation": "A lower duty cycle (longer relative rest/off time) helps manage and delay fatigue by allowing the muscle adequate recovery time between contractions, which is particularly important given NMES's tendency to fatigue muscle more rapidly than voluntary contraction."},{"id": 5298,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "'On:off time' in NMES parameters refers to:","options": [{"key": "A","text": "The total treatment duration only"},{"key": "B","text": "The ramp time only"},{"key": "C","text": "The specific duration (in seconds) of the active stimulation period (on time) and the specific duration of the rest period (off time) within each contraction cycle"},{"key": "D","text": "The pulse duration of a single pulse"}],"correct": "C","explanation": "On:off time specifies the actual duration in seconds of the active contraction phase and the subsequent rest phase within each stimulation cycle, which together determine the duty cycle ratio."},{"id": 5299,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "'Ramp time' (ramp up/ramp down) in NMES parameters refers to:","options": [{"key": "A","text": "The frequency of stimulation"},{"key": "B","text": "The gradual increase in current amplitude at the beginning of the 'on' phase (ramp up) and/or gradual decrease at the end (ramp down), rather than an abrupt on/off transition"},{"key": "C","text": "The total treatment session length"},{"key": "D","text": "The pulse duration"}],"correct": "B","explanation": "Ramp time describes the gradual rise (and often gradual fall) of stimulation intensity at the start/end of each 'on' cycle, producing a more comfortable, gradually building/subsiding contraction rather than an abrupt onset/offset."},{"id": 5300,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best explains the clinical rationale for including a ramp time in NMES protocols, rather than using an abrupt on/off transition?","options": [{"key": "A","text": "Ramp time is only relevant for TENS, not NMES"},{"key": "B","text": "Ramp time always reduces the effectiveness of the contraction with no benefit"},{"key": "C","text": "A gradual ramp improves patient comfort by avoiding an abrupt, potentially startling or uncomfortable jump to full contraction intensity, and may also more closely mimic the gradual recruitment pattern of a natural voluntary contraction"},{"key": "D","text": "Ramp time has no clinical benefit and is purely cosmetic"}],"correct": "C","explanation": "Including a ramp time improves patient comfort and tolerance by avoiding an abrupt onset of full-intensity contraction, and can provide a more gradual, physiologically appropriate build-up of muscle tension."},{"id": 5301,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "For NMES aimed at improving muscular endurance (rather than maximal strength), which general parameter adjustment is typically employed compared to a strengthening protocol?","options": [{"key": "A","text": "Higher intensity with fewer total contractions"},{"key": "B","text": "Complete elimination of any rest period between contractions"},{"key": "C","text": "Relatively lower intensity contractions with a higher number of repetitions/longer total treatment duration and potentially a higher duty cycle (shorter relative rest), consistent with training principles for endurance versus strength adaptation"},{"key": "D","text": "Identical parameters to a strengthening protocol with no adjustment needed"}],"correct": "C","explanation": "Endurance-focused NMES protocols generally use comparatively lower intensity with a greater number of contractions/longer session duration, consistent with general endurance training principles, in contrast to higher-intensity, lower-repetition strengthening protocols."},{"id": 5302,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following muscle types/groups is often specifically targeted with NMES following certain neurological or orthopedic conditions to address common significant weakness, such as after stroke or knee surgery?","options": [{"key": "A","text": "Muscles demonstrating significant activation deficits relevant to the specific condition, such as ankle dorsiflexors after stroke (to address foot drop) or quadriceps after knee surgery (to address arthrogenic inhibition)"},{"key": "B","text": "NMES is never targeted to any specific muscle group"},{"key": "C","text": "Only respiratory muscles regardless of condition"},{"key": "D","text": "Only distal hand intrinsic muscles regardless of the primary condition"}],"correct": "A","explanation": "NMES application is typically targeted to muscles demonstrating clinically significant activation deficits relevant to the patient's specific condition, such as ankle dorsiflexors in stroke-related foot drop or quadriceps following knee surgery."},{"id": 5303,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "'Functional electrical stimulation' (FES) differs from general NMES primarily in that FES:","options": [{"key": "A","text": "Has no relationship to NMES principles"},{"key": "B","text": "Is used exclusively for pain relief with no motor component"},{"key": "C","text": "Uses only direct current, never pulsed current"},{"key": "D","text": "Is specifically applied in a manner timed to assist or substitute for a functional movement/task during the activity itself (e.g., stimulating ankle dorsiflexors during the swing phase of gait to correct foot drop), rather than being applied as an isolated strengthening exercise outside of functional activity"}],"correct": "D","explanation": "FES represents an application of electrical stimulation principles specifically timed and applied to directly assist or substitute for a functional movement or task (e.g., gait-triggered stimulation for foot drop correction), distinguishing it from more general NMES strengthening protocols applied outside of functional activity."},{"id": 5304,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "A classic clinical example of functional electrical stimulation (FES) is:","options": [{"key": "A","text": "Continuous stimulation of the quadriceps while the patient is seated and inactive"},{"key": "B","text": "A foot drop stimulator that activates ankle dorsiflexors in a gait-cycle-triggered pattern during the swing phase of walking, to assist toe clearance in patients with certain neurological conditions (e.g., stroke, incomplete spinal cord injury)"},{"key": "C","text": "Iontophoresis for localized anti-inflammatory drug delivery"},{"key": "D","text": "TENS applied for chronic pain management"}],"correct": "B","explanation": "A foot drop stimulator, triggered to activate ankle dorsiflexors specifically during the swing phase of gait, exemplifies FES by directly assisting a functional movement (toe clearance) during the activity itself."},{"id": 5305,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Russian current (originally described by Kots) is a specific NMES waveform historically characterized by:","options": [{"key": "A","text": "A waveform used only for wound healing, with no motor stimulation component"},{"key": "B","text": "A medium-frequency (often cited around 2500 Hz) alternating current, delivered in bursts, originally promoted for producing greater strength gains than other stimulation forms, though later research has questioned some of the originally claimed unique benefits"},{"key": "C","text": "Direct current used for iontophoresis exclusively"},{"key": "D","text": "Low-frequency monophasic pulses"}],"correct": "B","explanation": "Russian current uses a medium-frequency (~2500 Hz) burst-modulated alternating current; while originally promoted (by Kots) as producing superior strength gains compared to other stimulation forms, subsequent research has generally not confirmed unique superiority over other well-designed NMES protocols using comparable intensity/parameters."},{"id": 5306,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best explains the theoretical rationale for using a medium-frequency alternating current (such as in Russian current) delivered in bursts, rather than a lower-frequency pulsed current, for NMES?","options": [{"key": "A","text": "Frequency of the carrier current has no relationship to tissue penetration or comfort"},{"key": "B","text": "Medium-frequency current always produces weaker contractions than low-frequency current"},{"key": "C","text": "Medium-frequency current cannot produce any muscle contraction"},{"key": "D","text": "Medium-frequency current is theorized to allow deeper tissue penetration with potentially improved patient comfort (due to reduced skin impedance at higher carrier frequencies), while the burst-modulation still allows an effective lower-frequency-equivalent stimulation pattern for muscle activation"}],"correct": "D","explanation": "The higher carrier frequency is theorized to reduce skin impedance (improving comfort and penetration), while burst-modulating this carrier at an effective lower frequency still provides the physiological stimulation pattern needed to produce muscle contraction."},{"id": 5307,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following is a relative or absolute contraindication for NMES/faradic stimulation application?","options": [{"key": "A","text": "Application directly over or near a cardiac pacemaker/implanted cardiac device, due to risk of electrical interference"},{"key": "B","text": "Application following orthopedic surgery with clinician clearance for the specific protocol"},{"key": "C","text": "Application to a normally innervated, healthy muscle for strengthening purposes"},{"key": "D","text": "Application over intact skin with normal sensation"}],"correct": "A","explanation": "Placement of stimulating electrodes over or near an implanted cardiac device (pacemaker/ICD) is a recognized contraindication due to the risk of electrical interference with the device's function."},{"id": 5308,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following is generally considered a contraindication or requires significant caution for NMES application, related to seizure risk?","options": [{"key": "A","text": "NMES has no relationship to seizure risk in any patient population"},{"key": "B","text": "All patients with any neurological history are absolutely contraindicated from ever receiving NMES"},{"key": "C","text": "Seizure disorder is only relevant to modalities applied directly to the head/neck, with no relevance elsewhere in the body"},{"key": "D","text": "Application in patients with a known seizure disorder (epilepsy) generally warrants caution, given theoretical concerns, though this is often considered a relative rather than absolute contraindication depending on clinical context and stimulation site/parameters"}],"correct": "D","explanation": "While generally considered a relative rather than absolute contraindication (context-dependent), caution is typically advised when applying NMES in patients with known seizure disorders, and clinical judgment regarding stimulation parameters and site is important."},{"id": 5309,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "NMES application over the carotid sinus region is generally contraindicated primarily due to the risk of:","options": [{"key": "A","text": "Improved circulation with no associated risk"},{"key": "B","text": "Muscle spasm only"},{"key": "C","text": "Triggering a reflexive drop in heart rate/blood pressure via stimulation of baroreceptors in this region, potentially causing significant cardiovascular effects (e.g., syncope, bradycardia)"},{"key": "D","text": "This is not actually a recognized contraindication"}],"correct": "C","explanation": "The carotid sinus region contains baroreceptors sensitive to pressure/stimulation, and electrical stimulation in this area risks triggering a reflexive cardiovascular response (e.g., bradycardia, hypotension), making this a recognized contraindication site."},{"id": 5310,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "NMES application directly over the abdomen or pelvis during pregnancy is generally:","options": [{"key": "A","text": "Contraindicated, following standard precaution given the uncertain and not well-established effects of electrical stimulation on fetal development"},{"key": "B","text": "Only contraindicated in the third trimester, but safe earlier in pregnancy"},{"key": "C","text": "Recommended as a standard treatment approach during pregnancy"},{"key": "D","text": "Considered completely safe with no precautions needed"}],"correct": "A","explanation": "Similar to other electrical stimulation modalities, standard precaution avoids abdominal/pelvic application during pregnancy due to the uncertain effects of electrical stimulation on fetal development."},{"id": 5311,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes an important safety consideration regarding NMES electrode placement relative to the phrenic nerve and diaphragm/respiratory function?","options": [{"key": "A","text": "Phrenic nerve stimulation is a desired therapeutic goal of NMES in all patients"},{"key": "B","text": "This consideration only applies to iontophoresis, not NMES"},{"key": "C","text": "Placement of electrodes in a manner that could stimulate the phrenic nerve (potentially affecting diaphragmatic/respiratory function) should be avoided, particularly in regions of the neck/upper chest where this nerve courses superficially"},{"key": "D","text": "Electrode placement has no relationship to respiratory function regardless of location"}],"correct": "C","explanation": "Care should be taken to avoid electrode placement that could inadvertently stimulate the phrenic nerve (particularly in superficial neck/upper chest regions), given its role in diaphragmatic and respiratory function."},{"id": 5312,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following is generally considered an appropriate precaution when applying NMES over areas of significantly reduced sensation (e.g., peripheral neuropathy)?","options": [{"key": "A","text": "Reduced sensation always makes NMES completely safe with higher tolerable intensities"},{"key": "B","text": "Extra caution is warranted since the patient's reduced ability to accurately perceive and report excessive or uncomfortable stimulation increases the risk of skin irritation or injury going unnoticed during treatment"},{"key": "C","text": "No special precautions are needed regardless of sensory status"},{"key": "D","text": "Sensory status has no bearing on NMES safety considerations"}],"correct": "B","explanation": "Impaired sensation reduces the patient's ability to provide reliable feedback about excessive or uncomfortable stimulation, increasing the risk that skin irritation or other adverse effects could go unnoticed, warranting extra caution and closer monitoring."},{"id": 5313,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general biomechanical/physiological effect that NMES-induced muscle contraction can have on local blood flow?","options": [{"key": "A","text": "Local blood flow is completely independent of muscle contraction activity"},{"key": "B","text": "NMES-induced contraction always decreases local blood flow"},{"key": "C","text": "Rhythmic muscle contraction (and subsequent relaxation) produced by NMES is thought to promote local circulation via a pumping-like mechanism, similar in principle to the effect of voluntary muscle contraction on venous return"},{"key": "D","text": "NMES has no effect on local blood flow"}],"correct": "C","explanation": "Similar to the effect of voluntary muscle activity, the rhythmic contraction-relaxation cycle produced by NMES is thought to promote local circulation through a pumping-type mechanism, which is one proposed benefit for applications such as edema management."},{"id": 5314,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best explains a common clinical application of NMES for edema management following injury or surgery, particularly for the lower extremity?","options": [{"key": "A","text": "NMES always worsens edema and should never be used for this purpose"},{"key": "B","text": "Edema management with NMES only applies to the upper extremity, never the lower extremity"},{"key": "C","text": "NMES has no established role in edema management"},{"key": "D","text": "Rhythmic NMES-induced muscle contraction (e.g., of the calf muscles) can promote venous return via the pumping mechanism, potentially assisting in reducing peripheral edema, often used as an adjunct alongside elevation, compression, and other standard interventions"}],"correct": "D","explanation": "NMES applied to promote rhythmic contraction of muscles such as the calf can assist venous return and help manage peripheral edema, typically used as an adjunct alongside other standard edema management strategies like elevation and compression."},{"id": 5315,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes a key parameter consideration when selecting pulse duration for NMES aimed at stimulating normally innervated (as opposed to denervated) skeletal muscle?","options": [{"key": "A","text": "Since normally innervated muscle is stimulated primarily via the motor nerve (which has relatively short chronaxie), relatively short pulse durations (commonly cited in ranges of approximately 150-400 microseconds for many NMES applications) are typically sufficient and comfortable for effective nerve depolarization"},{"key": "B","text": "Pulse duration is irrelevant to muscle stimulation efficacy"},{"key": "C","text": "Pulse duration must always exceed 1 second for any effective NMES stimulation"},{"key": "D","text": "Extremely long pulse durations (several hundred milliseconds) are always required for any muscle stimulation"}],"correct": "A","explanation": "Because normally innervated muscle is stimulated via the motor nerve (which has a relatively short chronaxie/excitability threshold), relatively brief pulse durations are typically sufficient for effective, comfortable stimulation in standard NMES applications."},{"id": 5316,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes why patient positioning and joint stabilization are important considerations during NMES treatment aimed at producing a strong muscle contraction (e.g., for strengthening)?","options": [{"key": "A","text": "Joint stabilization is only relevant for manual therapy, never for electrical stimulation"},{"key": "B","text": "Patients should always be positioned in a completely unsupported, unstable position during NMES"},{"key": "C","text": "Positioning and stabilization have no relevance to NMES treatment"},{"key": "D","text": "Proper positioning/stabilization helps ensure the intended muscle contraction can be effectively produced and, where appropriate, resisted (e.g., isometric resistance), optimizing the therapeutic training stimulus and reducing risk of unwanted compensatory movement or joint stress"}],"correct": "D","explanation": "Appropriate positioning and stabilization ensure that the NMES-induced contraction is effectively directed toward the intended therapeutic goal (e.g., producing adequate resistance for a strengthening effect) while minimizing unwanted compensatory movement or excessive joint stress."},{"id": 5317,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the concept of 'overflow' or generalized muscle recruitment sometimes observed with electrical stimulation, particularly at higher intensities?","options": [{"key": "A","text": "At higher stimulation intensities, current can spread to and activate nearby muscles beyond the intended target muscle, which may be an intended effect in some protocols (e.g., broader muscle group activation) or an unwanted effect requiring parameter/electrode adjustment in others (e.g., when precise, isolated muscle targeting is desired)"},{"key": "B","text": "Overflow refers to excessive current leaking from the device, unrelated to muscle recruitment"},{"key": "C","text": "Overflow only occurs with direct current, never with pulsed NMES"},{"key": "D","text": "Overflow has no clinical relevance to electrode placement decisions"}],"correct": "A","explanation": "At higher intensities, current can spread beyond the immediately targeted area, recruiting nearby muscles; depending on the clinical goal, this may be intentional (broader activation) or require adjustment of electrode placement/parameters if isolated targeting of a specific muscle is desired."},{"id": 5318,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best explains why electrode placement directly over the motor point of a muscle is often recommended for NMES applications targeting that specific muscle?","options": [{"key": "A","text": "The motor point represents the area where the motor nerve enters the muscle and is generally the most electrically excitable point, so placement here typically allows for effective muscle activation at comparatively lower stimulation intensities, improving efficiency and comfort"},{"key": "B","text": "Motor point location has no relevance to stimulation efficiency"},{"key": "C","text": "Motor points do not exist and are a discredited historical concept"},{"key": "D","text": "Placement away from the motor point is always preferred for optimal muscle activation"}],"correct": "A","explanation": "The motor point, where the motor nerve enters the muscle, generally has the lowest excitation threshold, so electrode placement at or near this point typically allows for effective muscle contraction at relatively lower, more comfortable stimulation intensities."},{"id": 5319,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best summarizes the general relationship between NMES-induced strength gains and the underlying physiological mechanisms, based on current understanding?","options": [{"key": "A","text": "Strength gains from NMES are always identical in magnitude to voluntary resistance training across all populations and conditions"},{"key": "B","text": "NMES has been definitively proven incapable of producing any measurable strength gains in any population"},{"key": "C","text": "NMES produces strength gains through mechanisms completely unrelated to those involved in voluntary resistance training"},{"key": "D","text": "NMES-induced strength gains are thought to occur through mechanisms with some overlap with voluntary resistance training (e.g., neural adaptations, some hypertrophic changes), though the specific relative contribution of different mechanisms and optimal parameters for maximizing gains continue to be researched, particularly given NMES's non-physiological recruitment pattern"}],"correct": "D","explanation": "While NMES can produce measurable strength gains through mechanisms sharing some overlap with voluntary training (including neural and some hypertrophic adaptations), the precise relative contributions and optimal application parameters remain areas of ongoing research, particularly given the distinct, non-physiological muscle fiber recruitment pattern characteristic of electrical stimulation."},{"id": 5320,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the relationship between NMES stimulation intensity and the resultant force of muscle contraction produced?","options": [{"key": "A","text": "Within the physiological range, increasing stimulation intensity generally increases the number of motor units/fibers recruited (up to a maximum), thereby increasing the resultant force of contraction, until a plateau or maximum tolerable intensity is reached"},{"key": "B","text": "Contraction force is always maximal regardless of stimulation intensity"},{"key": "C","text": "Increasing intensity always decreases contraction force"},{"key": "D","text": "Intensity has no relationship to contraction force"}],"correct": "A","explanation": "As stimulation intensity increases, progressively more motor axons/fibers are recruited, generally increasing contraction force up to a plateau determined by maximal fiber recruitment or patient tolerance limits."},{"id": 5321,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes why patient tolerance is often a limiting factor in achieving maximal NMES-induced contraction force, particularly compared to voluntary maximal contraction?","options": [{"key": "A","text": "NMES-induced contractions are always more comfortable than voluntary contractions at equivalent force levels"},{"key": "B","text": "As NMES intensity increases toward levels needed to recruit a large proportion of muscle fibers, the associated sensory discomfort often becomes a limiting factor before true physiological maximal fiber recruitment is achieved, in contrast to voluntary contraction where central nervous system drive can typically achieve fuller recruitment without this same discomfort barrier"},{"key": "C","text": "Tolerance is only a consideration for TENS, not NMES"},{"key": "D","text": "Patient tolerance has no bearing on achievable NMES contraction force"}],"correct": "B","explanation": "Because increasing NMES intensity toward levels needed for substantial fiber recruitment is often accompanied by increasing sensory discomfort, patient tolerance frequently becomes the practical limiting factor before the theoretical maximal fiber recruitment (achievable with less discomfort during voluntary contraction) is reached."},{"id": 5322,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following NMES parameters would generally need to be adjusted to help minimize patient discomfort while still achieving an adequate therapeutic muscle contraction?","options": [{"key": "A","text": "A combination of parameters including pulse duration, frequency, ramp time, and electrode placement/size may be adjusted, along with careful, gradual intensity titration, to help optimize the balance between effective contraction and patient comfort"},{"key": "B","text": "Only pulse duration, with no consideration of other parameters"},{"key": "C","text": "Only frequency, with all other parameters fixed and non-adjustable"},{"key": "D","text": "Comfort cannot be improved through any parameter adjustment"}],"correct": "A","explanation": "Multiple interacting NMES parameters (pulse duration, frequency, ramp time, electrode configuration) along with careful intensity titration can be adjusted to help optimize the balance between achieving an effective therapeutic contraction and maintaining acceptable patient comfort."},{"id": 5323,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the term 'co-contraction' as it might be intentionally elicited using NMES in certain rehabilitation contexts (e.g., for a joint requiring additional dynamic stability)?","options": [{"key": "A","text": "Co-contraction refers to simultaneous stimulation of agonist and antagonist muscle groups around a joint, sometimes used therapeutically to enhance dynamic joint stability"},{"key": "B","text": "Co-contraction always refers to bilateral stimulation of the same muscle on both sides of the body"},{"key": "C","text": "Co-contraction refers to stimulating only a single muscle in isolation"},{"key": "D","text": "Co-contraction is a term with no relevance to NMES application"}],"correct": "A","explanation": "Co-contraction in this context describes the simultaneous electrical stimulation of both agonist and antagonist muscles around a joint, sometimes used as a therapeutic strategy to enhance dynamic joint stability."},{"id": 5324,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes why NMES parameters used for muscle re-education/facilitation (e.g., helping a patient learn to voluntarily activate a previously inhibited muscle) might differ from parameters used purely for passive strengthening?","options": [{"key": "A","text": "Muscle re-education never involves any voluntary patient participation"},{"key": "B","text": "Re-education protocols often incorporate the stimulation as a cue/trigger timed with the patient's simultaneous voluntary attempt at contraction (biofeedback-assisted or triggered stimulation), rather than relying solely on passive, involuntary muscle activation as in some pure strengthening protocols"},{"key": "C","text": "There is no meaningful parameter difference between these two goals"},{"key": "D","text": "Re-education protocols always use identical parameters to denervated muscle stimulation protocols"}],"correct": "B","explanation": "Muscle re-education protocols often specifically incorporate the patient's simultaneous voluntary effort alongside the electrical stimulus (sometimes using EMG-triggered or biofeedback-assisted stimulation), aiming to reinforce voluntary motor control, in contrast to purely passive strengthening approaches."},{"id": 5325,"subject": "Electrotherapy","topic": "Electrodiagnosis","difficulty": "Medium","question": "EMG-triggered (biofeedback-assisted) electrical stimulation is a specific application in which:","options": [{"key": "A","text": "Stimulation is delivered continuously regardless of the patient's voluntary muscle activity"},{"key": "B","text": "EMG signals are used only for diagnostic purposes, never to trigger stimulation"},{"key": "C","text": "This technique is identical to standard NMES with no distinguishing feature"},{"key": "D","text": "The electrical stimulus is triggered to activate only once the patient's own voluntary EMG activity reaches a pre-set threshold, reinforcing and augmenting the patient's own active attempt at muscle contraction"}],"correct": "D","explanation": "EMG-triggered stimulation links the delivery of the electrical stimulus to the patient's own voluntary muscle activation reaching a set threshold, reinforcing and augmenting active voluntary effort rather than producing a purely passive contraction."},{"id": 5326,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes a potential clinical advantage of EMG-triggered stimulation over standard (non-triggered) NMES for certain rehabilitation goals?","options": [{"key": "A","text": "EMG-triggered stimulation always produces weaker contractions than standard NMES"},{"key": "B","text": "There is no advantage; both techniques are functionally identical"},{"key": "C","text": "By requiring and reinforcing the patient's own voluntary effort as a prerequisite for stimulation delivery, this approach may help promote more active patient engagement and potentially enhance motor learning/re-education compared to purely passive stimulation"},{"key": "D","text": "This technique eliminates the need for any patient participation"}],"correct": "C","explanation": "Since EMG-triggered stimulation requires the patient to actively initiate a voluntary contraction to trigger the stimulus, it may promote greater active engagement and potentially support motor re-learning more effectively than purely passive stimulation in appropriate candidates."},{"id": 5327,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to progressing NMES treatment parameters over the course of a rehabilitation program, as a patient's tolerance and strength improve?","options": [{"key": "A","text": "Parameters should remain completely fixed throughout the entire treatment course with no adjustment"},{"key": "B","text": "Parameters such as intensity, duty cycle, and treatment duration/frequency of sessions may be progressively adjusted based on the patient's improving tolerance, strength gains, and evolving clinical goals, similar in principle to progressive overload in traditional resistance training"},{"key": "C","text": "Progression of NMES parameters has no established rationale"},{"key": "D","text": "NMES parameters can only ever be decreased over time, never increased"}],"correct": "B","explanation": "As with traditional resistance training principles, NMES treatment parameters are often progressively adjusted over the course of rehabilitation to reflect the patient's improving tolerance and strength, and to continue providing an appropriately challenging therapeutic stimulus."},{"id": 5328,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes a key difference in typical treatment goals/parameters between NMES applied for strengthening a normally innervated muscle versus electrical stimulation applied to a completely denervated muscle?","options": [{"key": "A","text": "Electrical stimulation parameters are identical regardless of the muscle's innervation status"},{"key": "B","text": "Denervated muscle requires direct muscle fiber stimulation (given loss of motor nerve function) typically necessitating longer pulse durations, whereas normally innervated muscle is stimulated via the motor nerve using comparatively shorter pulse durations, and the overall goals differ (e.g., maintaining muscle viability/preventing severe atrophy during denervation versus building strength in innervated muscle)"},{"key": "C","text": "There is no meaningful difference in either goals or parameters between these two applications"},{"key": "D","text": "Denervated muscle always requires shorter pulse durations than normally innervated muscle"}],"correct": "B","explanation": "Since denervated muscle lacks functional motor nerve input, direct muscle fiber stimulation with longer pulse durations is typically required, and the treatment goals differ (e.g., maintaining tissue viability during the denervation period versus strengthening/re-education in innervated muscle), reflecting fundamentally different underlying physiology."},{"id": 5329,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the general clinical consensus regarding the effectiveness of electrical stimulation for completely denervated muscle in preventing long-term muscle atrophy/fibrotic changes, pending nerve regeneration?","options": [{"key": "A","text": "Electrical stimulation has been definitively proven to completely prevent all atrophy in denervated muscle with no controversy"},{"key": "B","text": "The evidence and clinical opinion regarding the effectiveness of electrical stimulation for denervated muscle remain mixed/debated, with some studies suggesting potential benefit in maintaining muscle mass/reducing fibrotic changes during the denervation period, while other research questions the magnitude of benefit, making this an area of ongoing clinical and research interest"},{"key": "C","text": "This question has no relevance to clinical electrotherapy practice"},{"key": "D","text": "Electrical stimulation has been proven completely ineffective for denervated muscle with no potential benefit whatsoever"}],"correct": "B","explanation": "The clinical and research literature regarding electrical stimulation of denervated muscle remains an area of ongoing debate, with mixed evidence regarding the magnitude of benefit in preserving muscle mass/reducing degenerative changes during the period awaiting nerve regeneration."},{"id": 5330,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes a common clinical application combining NMES with cycling or other functional movement in patients with certain neurological conditions (e.g., incomplete spinal cord injury)?","options": [{"key": "A","text": "NMES-assisted/FES cycling, in which electrical stimulation of leg muscles is timed and coordinated to assist pedaling movement, providing both a functional exercise modality and potential cardiovascular/muscular conditioning benefits"},{"key": "B","text": "FES cycling refers exclusively to stimulation of upper extremity muscles"},{"key": "C","text": "NMES has no application in combination with cycling or similar functional activities"},{"key": "D","text": "This combined approach is used only for pain management, with no functional/exercise component"}],"correct": "A","explanation": "FES-assisted cycling combines timed electrical stimulation of leg muscles with cycling movement, providing a functional exercise approach that can offer conditioning and other potential benefits in appropriate patients with certain neurological conditions."},{"id": 5331,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general safety profile of well-parameterized NMES when applied by a trained clinician following standard guidelines, in an appropriately screened patient?","options": [{"key": "A","text": "NMES is inherently dangerous and should essentially never be used in clinical practice"},{"key": "B","text": "NMES is generally considered a safe modality when applied appropriately by a trained clinician following standard screening, contraindication, and parameter guidelines, though as with any electrical modality, attention to proper application and patient-specific factors remains important"},{"key": "C","text": "Safety considerations for NMES are identical to those for surgical interventions"},{"key": "D","text": "NMES carries no risk whatsoever under any circumstances, eliminating the need for any screening or precautions"}],"correct": "B","explanation": "When applied by a trained clinician following appropriate screening and parameter guidelines, NMES is generally considered a safe therapeutic modality, though ongoing attention to contraindications, proper technique, and individual patient factors remains an important part of safe clinical practice."},{"id": 5332,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the term 'M-wave' as sometimes referenced in the context of electrically evoked muscle responses?","options": [{"key": "A","text": "The M-wave has no relationship to electrical stimulation of any kind"},{"key": "B","text": "The M-wave is a term used only in the context of ultrasound therapy"},{"key": "C","text": "The M-wave refers to the compound muscle action potential recorded via EMG in direct response to electrical stimulation of the motor nerve, used in some research and clinical neurophysiological contexts to assess nerve/muscle response characteristics"},{"key": "D","text": "The M-wave refers to a type of manual muscle testing grade"}],"correct": "C","explanation": "The M-wave refers to the compound muscle action potential (CMAP) recorded electromyographically in response to electrical stimulation of a motor nerve, providing information about the resultant muscle fiber response, used in certain research and clinical neurophysiological assessment contexts."},{"id": 5333,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best summarizes an important clinical documentation practice following NMES treatment sessions?","options": [{"key": "A","text": "Only the total treatment time needs to be documented, with no other parameters relevant"},{"key": "B","text": "Documentation should include the specific stimulation parameters used (e.g., waveform, frequency, pulse duration, intensity, on:off time, electrode placement), patient tolerance/response, and any observed skin reaction, supporting continuity of care and appropriate progression of treatment"},{"key": "C","text": "Documentation is unnecessary for electrotherapy modalities since no adverse effects are possible"},{"key": "D","text": "Documentation should exclude any information about patient-reported comfort or tolerance"}],"correct": "B","explanation": "Thorough documentation of specific stimulation parameters, patient response/tolerance, and any skin findings supports continuity of care, allows appropriate treatment progression, and provides an important record for clinical reasoning and communication among the care team."},{"id": 5334,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical role of NMES within a comprehensive rehabilitation program for a patient with significant post-surgical quadriceps weakness?","options": [{"key": "A","text": "NMES should only be introduced after all voluntary strengthening goals have already been fully achieved through other means"},{"key": "B","text": "NMES has no evidence-based role in post-surgical rehabilitation programs"},{"key": "C","text": "NMES is generally most effectively used as an adjunct within a comprehensive rehabilitation program, working alongside voluntary exercise, functional training, and other appropriate interventions to help address specific impairments such as activation deficits and disuse atrophy"},{"key": "D","text": "NMES should always be used as the sole intervention, replacing the need for any voluntary exercise program"}],"correct": "C","explanation": "NMES is most appropriately integrated as one component of a comprehensive, individualized rehabilitation program, complementing voluntary exercise and functional training to address specific impairments such as activation deficits and disuse atrophy following surgery."},{"id": 5335,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Easy","question": "TENS stands for:","options": [{"key": "A","text": "Therapeutic Electrical Neural Stimulation"},{"key": "B","text": "Transcutaneous Electrical Nerve Stimulation"},{"key": "C","text": "Trans-Epidermal Nerve Stimulation"},{"key": "D","text": "Total Electrical Nerve Stimulation"}],"correct": "B","explanation": "TENS refers to Transcutaneous Electrical Nerve Stimulation, a modality used primarily for pain modulation via surface electrode application."},{"id": 5336,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Easy","question": "The primary clinical purpose of TENS is:","options": [{"key": "A","text": "Wound healing exclusively"},{"key": "B","text": "Muscle strengthening"},{"key": "C","text": "Pain modulation/relief"},{"key": "D","text": "Iontophoretic drug delivery"}],"correct": "C","explanation": "TENS is primarily used as a pain management modality, aiming to reduce pain perception through electrical stimulation of sensory nerves."},{"id": 5337,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Conventional (high-frequency, low-intensity) TENS is theorized to relieve pain primarily through which physiological mechanism?","options": [{"key": "A","text": "The Gate Control Theory of pain, whereby stimulation of large-diameter A-beta sensory afferents inhibits transmission of nociceptive (pain) signals at the spinal cord dorsal horn level"},{"key": "B","text": "Direct destruction of pain receptors"},{"key": "C","text": "Muscle relaxation exclusively, with no direct effect on pain pathways"},{"key": "D","text": "Endogenous opioid release exclusively"}],"correct": "A","explanation": "Conventional TENS is theorized to work primarily via the Gate Control Theory, stimulating large-diameter A-beta afferents to presynaptically inhibit nociceptive transmission at the dorsal horn."},{"id": 5338,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "The Gate Control Theory of pain, proposed by Melzack and Wall, suggests that:","options": [{"key": "A","text": "Activity in large-diameter, fast-conducting sensory fibers (A-beta) can inhibit/'close the gate' on the transmission of pain signals carried by smaller-diameter fibers (A-delta and C fibers) at the spinal cord dorsal horn level"},{"key": "B","text": "Only chemical mediators determine pain perception"},{"key": "C","text": "Pain perception occurs exclusively in peripheral tissue with no central nervous system involvement"},{"key": "D","text": "Pain signals always reach conscious perception unimpeded"}],"correct": "A","explanation": "The Gate Control Theory proposes a spinal cord 'gating' mechanism where large-diameter afferent activity can inhibit ('close the gate' on) the ascending transmission of pain signals from smaller nociceptive fibers."},{"id": 5339,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which parameters are typically used for conventional (Gate Control-based) TENS?","options": [{"key": "A","text": "High frequency (commonly cited ranges around 80-150 Hz), low intensity (sensory level, producing a comfortable tingling without motor contraction), and relatively short pulse duration"},{"key": "B","text": "Low frequency (1-5 Hz) with high intensity, producing visible muscle twitching"},{"key": "C","text": "Very low frequency with long pulse duration exclusively"},{"key": "D","text": "No specific parameters are associated with conventional TENS"}],"correct": "A","explanation": "Conventional TENS typically uses high pulse frequency, low (sensory-level) intensity, and relatively short pulse duration to selectively stimulate large-diameter sensory afferents without producing motor contraction."},{"id": 5340,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "The onset of pain relief with conventional (Gate Control) TENS is generally characterized as:","options": [{"key": "A","text": "Completely unrelated to the timing of stimulation"},{"key": "B","text": "Delayed by several hours after stimulation begins"},{"key": "C","text": "Relatively rapid, often occurring during or shortly after stimulation begins, but with a correspondingly rapid offset/cessation of effect once stimulation stops"},{"key": "D","text": "Permanent, with effects lasting indefinitely after a single treatment"}],"correct": "C","explanation": "Conventional TENS is generally associated with relatively rapid onset of analgesic effect during stimulation, but this effect tends to diminish relatively quickly once stimulation ceases, consistent with a primarily gate-control-mediated mechanism."},{"id": 5341,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Acupuncture-like TENS (AL-TENS) is theorized to relieve pain primarily through which physiological mechanism?","options": [{"key": "A","text": "No established mechanism; this is a purely placebo-based technique"},{"key": "B","text": "Direct anesthetic-like blockade of all nerve conduction"},{"key": "C","text": "Stimulation of small-diameter afferents (often at a motor/strong sensory intensity) leading to release of endogenous opioids (e.g., endorphins, enkephalins), producing a systemic, longer-lasting analgesic effect"},{"key": "D","text": "The Gate Control Theory exclusively, with no other mechanism involved"}],"correct": "C","explanation": "AL-TENS is theorized to work primarily through activation of descending pain inhibitory pathways involving endogenous opioid release, distinct from the primarily segmental gate-control mechanism of conventional TENS."},{"id": 5342,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which parameters are typically used for acupuncture-like TENS (AL-TENS)?","options": [{"key": "A","text": "Low frequency (commonly cited ranges around 1-4 Hz), higher intensity sufficient to produce a visible/palpable muscle twitch, and typically longer pulse duration compared to conventional TENS"},{"key": "B","text": "High frequency, low intensity, short pulse duration"},{"key": "C","text": "Extremely high frequency exceeding 500 Hz with minimal intensity"},{"key": "D","text": "No specific parameters distinguish AL-TENS from conventional TENS"}],"correct": "A","explanation": "AL-TENS typically uses low frequency, motor-level (twitch-producing) intensity, and relatively longer pulse duration compared to the sensory-level, high-frequency parameters of conventional TENS."},{"id": 5343,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "The onset of pain relief with acupuncture-like TENS (AL-TENS), consistent with an opioid-mediated mechanism, is generally characterized as:","options": [{"key": "A","text": "Identical in onset and offset timing to conventional TENS"},{"key": "B","text": "Somewhat delayed in onset compared to conventional TENS, but often producing a longer-lasting analgesic effect that may persist for some time after stimulation ends, consistent with a systemic opioid-mediated mechanism"},{"key": "C","text": "Never producing any measurable analgesic effect"},{"key": "D","text": "Immediate, with effect lasting only during stimulation"}],"correct": "B","explanation": "Consistent with its proposed opioid-mediated mechanism, AL-TENS analgesia is often somewhat delayed in onset but may produce a more prolonged post-stimulation analgesic effect compared to the more immediate but shorter-lived effect of conventional TENS."},{"id": 5344,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Brief-intense TENS is characterized by which combination of parameters?","options": [{"key": "A","text": "Low frequency, low intensity, short pulse duration"},{"key": "B","text": "Low frequency, high intensity with very short pulse duration exclusively"},{"key": "C","text": "Parameters identical to conventional TENS"},{"key": "D","text": "High frequency, high (near-maximal tolerable) intensity, and relatively long pulse duration, typically used for short-duration, rapid-onset analgesia (e.g., during a brief painful procedure)"}],"correct": "D","explanation": "Brief-intense TENS uses high frequency combined with high intensity and longer pulse duration, aiming to produce rapid, strong analgesia typically for brief painful procedures, though this mode is often less comfortable for prolonged use."},{"id": 5345,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Burst-mode TENS (sometimes overlapping conceptually with certain AL-TENS protocols) is characterized by:","options": [{"key": "A","text": "A mode with parameters identical to brief-intense TENS"},{"key": "B","text": "A mode used exclusively for iontophoresis"},{"key": "C","text": "Delivery of pulses grouped into repeating 'bursts' (groups of high-frequency pulses delivered at a lower burst repetition rate), which is theorized to combine some characteristics of both segmental (gate control) and opioid-mediated mechanisms, and to potentially improve accommodation/comfort compared to plain continuous stimulation"},{"key": "D","text": "Continuous, unbroken stimulation with no burst pattern"}],"correct": "C","explanation": "Burst-mode TENS groups pulses into repeating bursts, which is theorized to engage both gate-control and opioid-related mechanisms while potentially reducing accommodation and improving comfort compared to continuous stimulation at a single frequency."},{"id": 5346,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "'Modulated' TENS refers to a mode in which:","options": [{"key": "A","text": "This mode has no distinguishing characteristic from conventional TENS"},{"key": "B","text": "One or more stimulation parameters (e.g., frequency, intensity, pulse duration) are automatically and continuously varied throughout the treatment session, which is theorized to help reduce accommodation (adaptation) of nerve fibers to a constant stimulus"},{"key": "C","text": "Stimulation parameters remain completely fixed and unchanging throughout the entire treatment"},{"key": "D","text": "Modulated TENS refers exclusively to iontophoresis-based stimulation"}],"correct": "B","explanation": "Modulated TENS automatically varies one or more parameters over time during treatment, which is theorized to help minimize sensory accommodation/adaptation that can occur with prolonged exposure to constant, unchanging stimulation parameters."},{"id": 5347,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best explains why sensory accommodation (adaptation) can become a clinical issue during prolonged conventional TENS application with constant, unchanging parameters?","options": [{"key": "A","text": "Accommodation only affects motor nerve fibers, never sensory fibers"},{"key": "B","text": "Accommodation has no clinical relevance to TENS effectiveness over time"},{"key": "C","text": "With prolonged exposure to an unchanging stimulus, sensory nerve fibers can adapt and become progressively less responsive, potentially reducing the perceived intensity/effectiveness of the stimulation over time, which is one rationale for using modulated parameters or periodically adjusting settings during treatment"},{"key": "D","text": "Accommodation improves the effectiveness of TENS over time with no downside"}],"correct": "C","explanation": "Sensory nerve accommodation to a constant, unvarying stimulus can reduce perceived stimulation intensity/effectiveness over time, which is a key rationale for using modulated TENS parameters or periodically adjusting the device settings during a prolonged treatment session."},{"id": 5348,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Electrode placement for TENS is commonly directed over which anatomical location(s), among various clinically used strategies?","options": [{"key": "A","text": "Directly over or around the area of pain, over relevant dermatomes/peripheral nerve distributions, over trigger points, or at acupuncture-like points, depending on the specific clinical presentation and chosen approach"},{"key": "B","text": "Only at a fixed, standardized location regardless of the pain presentation"},{"key": "C","text": "Only over the exact painful area, with no other options ever considered"},{"key": "D","text": "Electrode placement has no established clinical rationale for TENS"}],"correct": "A","explanation": "TENS electrode placement is individualized based on the clinical presentation and may include placement directly over/around the pain site, along relevant dermatomes or nerve distributions, over trigger points, or at specific points used in acupuncture-like approaches."},{"id": 5349,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to determining TENS intensity for conventional (Gate Control) parameters?","options": [{"key": "A","text": "Intensity should generally be set to a strong, comfortable sensory (tingling) level, without producing visible muscle contraction, consistent with the goal of selectively stimulating large-diameter sensory afferents"},{"key": "B","text": "Intensity should always be set below the patient's sensory threshold, so no sensation is perceived at all"},{"key": "C","text": "Intensity has no bearing on the effectiveness of conventional TENS"},{"key": "D","text": "Intensity should always be set to the maximum tolerable level regardless of the specific TENS mode being used"}],"correct": "A","explanation": "For conventional TENS, intensity is generally set to produce a strong but comfortable sensory (tingling) sensation, without eliciting a visible motor response, consistent with the goal of selectively engaging large-diameter A-beta sensory fibers."},{"id": 5350,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following is a commonly cited relative or absolute contraindication for TENS application, related to cardiac devices?","options": [{"key": "A","text": "TENS has no established contraindications related to cardiac devices"},{"key": "B","text": "This contraindication only applies to NMES, not TENS"},{"key": "C","text": "TENS is always safe to apply directly over any cardiac device with no precaution needed"},{"key": "D","text": "Application over or near a cardiac pacemaker/implanted cardioverter-defibrillator, or in a transthoracic current pathway, due to the risk of electrical interference with the device"}],"correct": "D","explanation": "As with other forms of electrical stimulation, TENS application near cardiac pacemakers/ICDs, or in a pathway that could direct current transthoracically, carries a risk of device interference and is generally contraindicated or requires significant caution/consultation."},{"id": 5351,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "TENS application over the carotid sinus region is generally contraindicated for the same reason cited for other electrical stimulation modalities, namely:","options": [{"key": "A","text": "Risk of causing a seizure"},{"key": "B","text": "Risk of triggering a reflexive cardiovascular response (e.g., bradycardia, hypotension) via stimulation of baroreceptors in this region"},{"key": "C","text": "Risk of muscle spasm only"},{"key": "D","text": "No actual risk exists; this is not a genuine contraindication"}],"correct": "B","explanation": "The carotid sinus baroreceptors are sensitive to stimulation, and electrical current in this region risks provoking a reflexive drop in heart rate/blood pressure, making this a standard contraindication site for TENS as with other electrical modalities."},{"id": 5352,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "TENS application over the abdomen/pelvis/lumbar region during pregnancy is generally:","options": [{"key": "A","text": "Approached with standard caution/contraindication, given the not well-established effects of electrical stimulation on fetal development, though TENS is sometimes specifically used (with appropriate clinical guidance) for labor pain management in later pregnancy under different considerations"},{"key": "B","text": "Considered completely safe with no precautions"},{"key": "C","text": "Recommended universally throughout all stages of pregnancy with no restriction"},{"key": "D","text": "Only a concern for direct current, not TENS"}],"correct": "A","explanation": "While general precaution avoids TENS over the abdomen/pelvis/lumbar region during pregnancy given uncertain fetal effects, TENS is sometimes specifically used for labor pain management under different clinical considerations and typically applied to the lower back once appropriate for that purpose, reflecting a more nuanced clinical context than a blanket prohibition throughout all of pregnancy."},{"id": 5353,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "TENS is generally considered contraindicated for application directly over areas of known or suspected malignancy primarily due to:","options": [{"key": "A","text": "This contraindication only applies to modalities producing heat, not TENS"},{"key": "B","text": "The same theoretical concern applied broadly across electrotherapy modalities, that increased local blood flow/cellular activity from stimulation could potentially influence tumor behavior, though definitive evidence specific to TENS remains limited"},{"key": "C","text": "TENS is known to definitively worsen all malignancies with strong supporting evidence"},{"key": "D","text": "No established concern; this is a myth with no basis"}],"correct": "B","explanation": "Similar to the general precaution applied across many electrotherapy modalities, TENS application over known/suspected malignancy is generally avoided due to theoretical concerns about stimulating local blood flow/cellular activity, despite limited definitive evidence specific to TENS itself."},{"id": 5354,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following is generally considered a contraindication for TENS application, related to seizure risk and electrode placement?","options": [{"key": "A","text": "Placement of TENS electrodes directly over/around the head or in a transcerebral pathway in patients with epilepsy/seizure disorder generally warrants significant caution or is considered contraindicated"},{"key": "B","text": "TENS has no relationship to seizure risk regardless of application site"},{"key": "C","text": "TENS applied anywhere on the body poses an identical seizure risk regardless of electrode placement"},{"key": "D","text": "Seizure disorder has no relevance to TENS electrode placement decisions"}],"correct": "A","explanation": "Particular caution or contraindication is generally applied to TENS electrode placement over/around the head or in a pathway that could direct current transcerebrally in patients with a seizure disorder, given the theoretical risk in this specific context."},{"id": 5355,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an important safety consideration regarding TENS use and undiagnosed pain of unknown origin?","options": [{"key": "A","text": "This consideration is irrelevant since TENS has no capacity to mask any underlying pathology"},{"key": "B","text": "TENS should always be applied immediately for any reported pain without further evaluation"},{"key": "C","text": "TENS should generally not be used to mask or manage undiagnosed pain until an appropriate medical evaluation has ruled out serious underlying pathology, since symptomatic pain relief could potentially delay recognition/diagnosis of a serious condition"},{"key": "D","text": "Only diagnosed chronic pain conditions warrant caution; acute undiagnosed pain has no such concern"}],"correct": "C","explanation": "Using TENS to manage pain of unclear or undiagnosed origin risks masking symptoms that could otherwise prompt timely medical evaluation and diagnosis of a potentially serious underlying condition, making appropriate diagnostic workup an important prerequisite."},{"id": 5356,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the evidence-based perspective on TENS effectiveness for chronic pain management, based on the broader body of research?","options": [{"key": "A","text": "The research evidence regarding TENS effectiveness for chronic pain is mixed, with some studies showing benefit and others showing limited or inconclusive results, and methodological factors (e.g., adequacy of dosing/intensity used in trials) have been raised as potential contributors to this variability, making TENS efficacy for chronic pain an area of continued research and clinical debate"},{"key": "B","text": "There is no research evidence whatsoever regarding TENS for chronic pain"},{"key": "C","text": "TENS has been definitively proven completely ineffective for all pain conditions in all circumstances"},{"key": "D","text": "Research evidence universally and conclusively supports TENS as highly effective for all chronic pain conditions with no controversy"}],"correct": "A","explanation": "The evidence base for TENS in chronic pain management remains mixed, and methodological considerations (including whether adequate, individualized dosing was used in various trials) have been discussed as potential contributors to inconsistent findings, reflecting an area of ongoing research interest and clinical debate."},{"id": 5357,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes why individualized, patient-specific dosing (rather than a fixed, standardized protocol) is increasingly emphasized in TENS research and clinical guidelines?","options": [{"key": "A","text": "TENS intensity has no bearing on its clinical effectiveness"},{"key": "B","text": "A fixed, standardized protocol is always superior to any individualized approach"},{"key": "C","text": "Since optimal TENS parameters (particularly intensity, which should generally be maximized within comfortable tolerance) can vary between individuals, and effectiveness may depend on achieving an adequately strong, individually-tolerated intensity, standardized low-intensity protocols used in some research may underestimate the modality's true potential effectiveness when properly individualized"},{"key": "D","text": "Individualized dosing has no relevance to TENS effectiveness"}],"correct": "C","explanation": "Since individual variation in optimal parameters (especially the importance of using a sufficiently strong, comfortably tolerated intensity) can significantly influence outcomes, standardized protocols using lower, non-individualized intensities in some research may not fully reflect the modality's potential effectiveness when properly dosed for each patient."},{"id": 5358,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general recommendation regarding TENS intensity dosing based on current understanding of dose-response relationships for pain modulation?","options": [{"key": "A","text": "TENS intensity has no established dose-response relationship with analgesic effect"},{"key": "B","text": "Only very brief treatment durations of a few seconds are ever recommended, regardless of intensity"},{"key": "C","text": "Lower intensity is always preferred regardless of patient tolerance, since higher intensity provides no additional benefit"},{"key": "D","text": "Current understanding generally suggests that a stronger, maximally tolerated comfortable intensity tends to be associated with greater analgesic effect compared to a barely perceptible or very low intensity, informing clinical dosing recommendations to encourage adequately strong stimulation within patient tolerance"}],"correct": "D","explanation": "Current clinical guidance generally recommends dosing TENS at a strong, maximally comfortable tolerated intensity, since evidence suggests this is associated with greater analgesic benefit compared to using only a minimal, barely perceptible intensity."},{"id": 5359,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes patient education regarding the expected duration of TENS analgesic effect, particularly for conventional (Gate Control) TENS, to set appropriate expectations?","options": [{"key": "A","text": "Patients should be told that TENS provides permanent, lasting pain relief after a single brief treatment"},{"key": "B","text": "TENS analgesic effects are always permanent regardless of the specific TENS mode used"},{"key": "C","text": "Patients should generally be informed that conventional TENS analgesia is often relatively short-lived, tending to diminish once stimulation stops, so TENS is typically used as needed throughout the day or during specific painful activities, rather than expecting a single treatment to provide prolonged, lasting relief"},{"key": "D","text": "Patient education regarding expected duration of effect is unnecessary and irrelevant to TENS use"}],"correct": "C","explanation": "Since conventional TENS analgesia (via the gate control mechanism) tends to be relatively short-lived once stimulation stops, appropriate patient education includes explaining that repeated or ongoing use throughout the day (or during specific painful activities) is often more realistic than expecting a single treatment to provide prolonged, lasting relief."},{"id": 5360,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an appropriate skin care/monitoring consideration for patients using TENS for extended daily wear (e.g., home-use devices worn for many hours)?","options": [{"key": "A","text": "Regular skin inspection for irritation/allergic reaction to electrodes or adhesive, along with periodic electrode repositioning, is generally recommended for patients using TENS for extended or frequent daily wear, to reduce risk of skin breakdown or irritation"},{"key": "B","text": "Skin care and monitoring are unnecessary for TENS regardless of duration of use"},{"key": "C","text": "Electrode repositioning should never be done, as it reduces treatment effectiveness"},{"key": "D","text": "Skin irritation from TENS electrodes is never a clinically relevant concern"}],"correct": "A","explanation": "For patients using TENS extensively (e.g., prolonged daily home use), regular skin inspection and periodic electrode repositioning are generally recommended to help identify and reduce the risk of skin irritation or allergic reaction associated with prolonged electrode/adhesive contact."},{"id": 5361,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes a common self-adhesive TENS electrode material consideration relevant to skin reactions in some patients?","options": [{"key": "A","text": "Electrode material has no relationship to skin reactions in any patient"},{"key": "B","text": "Some patients may develop localized skin irritation or allergic-type reactions to electrode gel/adhesive components, so awareness of this possibility and appropriate skin monitoring is part of responsible clinical practice, particularly for prolonged or repeated use"},{"key": "C","text": "All TENS electrodes are made of an identical, universally hypoallergenic material with zero reaction risk"},{"key": "D","text": "Skin reactions to TENS electrodes only occur with iontophoresis, never with standard TENS"}],"correct": "B","explanation": "Awareness that some patients may develop localized skin irritation or allergic-type reactions to electrode components (gel/adhesive) is an important part of responsible clinical practice, particularly relevant for patients using TENS extensively or repeatedly."},{"id": 5362,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the concept of 'placebo TENS' as sometimes used in research study designs?","options": [{"key": "A","text": "Placebo TENS is a term with no established meaning in electrotherapy research"},{"key": "B","text": "Placebo TENS refers to a device that delivers a genuine, full-intensity therapeutic current identical to active treatment"},{"key": "C","text": "Placebo TENS refers exclusively to iontophoresis studies"},{"key": "D","text": "Placebo TENS typically refers to a sham condition in research (e.g., a device that appears active but delivers minimal or no genuine therapeutic current), used as a control condition to help assess the specific treatment effect of TENS beyond any non-specific/placebo response"}],"correct": "D","explanation": "In research contexts, placebo (sham) TENS conditions are used as a control to help distinguish the specific physiological treatment effect of active TENS from non-specific placebo responses, an important methodological consideration when interpreting TENS research findings."},{"id": 5363,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes an important methodological challenge in designing rigorous, well-blinded TENS research studies?","options": [{"key": "A","text": "There are no methodological challenges specific to TENS research design"},{"key": "B","text": "Blinding is irrelevant to the interpretation of TENS clinical trial results"},{"key": "C","text": "TENS research is inherently free of any blinding-related challenges due to its non-invasive nature"},{"key": "D","text": "Because active TENS typically produces a perceptible sensory sensation (tingling), it can be difficult to create a truly convincing sham/placebo condition that adequately blinds participants, which is a recognized methodological challenge when interpreting the TENS research literature"}],"correct": "D","explanation": "Since genuine TENS produces a noticeable sensory sensation, effectively blinding participants in a sham-controlled trial is methodologically challenging, and this consideration is important when critically appraising and interpreting findings from the TENS research literature."},{"id": 5364,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general clinical role of TENS within a comprehensive pain management approach for a patient with chronic musculoskeletal pain?","options": [{"key": "A","text": "TENS has no legitimate role in any modern comprehensive pain management program"},{"key": "B","text": "TENS is generally most appropriately considered as one component of a broader, multimodal pain management approach that may also include exercise, education, manual therapy, and other evidence-based interventions, rather than as a standalone comprehensive solution"},{"key": "C","text": "TENS should always be used as the sole and complete treatment approach, replacing the need for any other intervention"},{"key": "D","text": "TENS should only ever be used in acute pain, never in chronic pain conditions"}],"correct": "B","explanation": "TENS is generally best utilized as one component within a broader, multimodal approach to chronic pain management, complementing other evidence-based interventions such as exercise, education, and manual therapy, rather than serving as a standalone comprehensive treatment."},{"id": 5365,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes why patients are generally instructed not to apply TENS while driving, operating heavy machinery, or in other situations requiring full alertness/coordination?","options": [{"key": "A","text": "Depending on the intensity and placement, TENS stimulation (particularly if producing any degree of paresthesia, distraction, or unexpected sensation) could theoretically interfere with attention, coordination, or safe operation of machinery/vehicles, warranting this general safety precaution"},{"key": "B","text": "TENS always causes immediate loss of consciousness, making this precaution necessary"},{"key": "C","text": "This instruction has no valid clinical rationale"},{"key": "D","text": "This precaution only applies to NMES, never to TENS"}],"correct": "A","explanation": "As a general safety precaution, patients are typically advised against using TENS while driving or operating machinery, given the potential for the stimulation sensation to be distracting or to theoretically interfere with the attention and coordination required for these activities."},{"id": 5366,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to educating a patient about self-management/home use of a TENS unit for chronic pain?","options": [{"key": "A","text": "No education is necessary; patients can figure out appropriate use entirely on their own"},{"key": "B","text": "Education should include appropriate electrode placement, safe parameter settings, recognized contraindications/precautions, expected effects and their typical duration, and when to seek further clinical guidance, supporting safe and effective independent use"},{"key": "C","text": "Home TENS use requires no different education than supervised clinic-based use"},{"key": "D","text": "Patients should never be permitted to use TENS independently at home under any circumstances"}],"correct": "B","explanation": "Comprehensive patient education for home TENS use should cover proper electrode placement, safe parameter selection, relevant contraindications/precautions, realistic expectations regarding effects, and guidance on when to seek further clinical input, supporting safe and effective self-management."},{"id": 5367,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes 'high-frequency' versus 'low-frequency' TENS in terms of the general frequency ranges typically referenced in clinical literature?","options": [{"key": "A","text": "High-frequency TENS typically refers to ranges around 1-4 Hz, and low-frequency to ranges around 100 Hz"},{"key": "B","text": "High-frequency (conventional-type) TENS is generally associated with ranges roughly above 50 Hz (often cited around 80-150 Hz), while low-frequency (acupuncture-like) TENS is generally associated with ranges roughly below 10 Hz (often cited around 1-4 Hz)"},{"key": "C","text": "Frequency has no bearing on the classification of TENS modes"},{"key": "D","text": "There is no meaningful distinction between high and low frequency TENS in clinical literature"}],"correct": "B","explanation": "Clinical literature generally associates conventional (Gate Control) TENS with higher frequency ranges (commonly cited around 80-150 Hz) and acupuncture-like TENS with lower frequency ranges (commonly cited around 1-4 Hz), consistent with their differing proposed mechanisms."},{"id": 5368,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the concept of 'hyperstimulation analgesia' as it may relate to certain intense electrical stimulation techniques?","options": [{"key": "A","text": "Hyperstimulation analgesia refers exclusively to a surgical pain management technique unrelated to electrical stimulation"},{"key": "B","text": "This term has no established meaning in the context of electrical stimulation for pain"},{"key": "C","text": "Hyperstimulation analgesia refers to pain relief achieved through the application of relatively intense, sometimes brief, stimulation (which may include certain TENS modes or related techniques), theorized to engage strong counter-stimulation and/or opioid-related mechanisms"},{"key": "D","text": "Hyperstimulation analgesia refers to pain relief achieved through very low-intensity, barely perceptible stimulation"}],"correct": "C","explanation": "Hyperstimulation analgesia describes pain relief achieved through relatively intense stimulation techniques, thought to engage strong counter-stimulation and/or opioid-related pain modulation mechanisms, conceptually related to certain higher-intensity TENS approaches (e.g., brief-intense TENS)."},{"id": 5369,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best explains why TENS electrode placement directly over an area of significantly compromised/absent skin sensation is generally approached with caution?","options": [{"key": "A","text": "Reduced sensation impairs the patient's ability to accurately perceive and report excessive or uncomfortable stimulation intensity, increasing the risk of unrecognized skin irritation or other adverse effects during treatment"},{"key": "B","text": "This caution applies only to NMES, not to TENS"},{"key": "C","text": "Placement over areas of reduced sensation always produces a stronger, more effective therapeutic response with no added risk"},{"key": "D","text": "Sensory status has no bearing on TENS electrode placement safety"}],"correct": "A","explanation": "As with other electrical stimulation modalities, reduced sensation impairs the patient's ability to reliably report excessive or uncomfortable stimulation, increasing the risk that adverse effects (e.g., skin irritation) could go unrecognized during treatment."},{"id": 5370,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general clinical use of TENS for post-surgical acute pain management?","options": [{"key": "A","text": "TENS is always contraindicated in the immediate post-surgical period under all circumstances"},{"key": "B","text": "TENS is only appropriate for chronic pain, never for acute post-surgical pain"},{"key": "C","text": "TENS is sometimes used as an adjunct for acute post-surgical pain management, potentially helping to reduce pain and, in some contexts, reduce reliance on pharmacological analgesics, though it is typically integrated within a broader, multimodal post-surgical pain management approach rather than used in isolation"},{"key": "D","text": "TENS has no established application for acute post-surgical pain"}],"correct": "C","explanation": "TENS is sometimes used as part of a multimodal approach to acute post-surgical pain management, potentially contributing to pain reduction and, in some contexts, helping to reduce reliance on pharmacological analgesics, though appropriate integration within the overall post-surgical care plan (including consideration of the surgical site and any relevant precautions) is important."},{"id": 5371,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best summarizes an appropriate clinical reasoning approach when selecting a specific TENS mode (conventional, AL-TENS, burst, brief-intense) for an individual patient?","options": [{"key": "A","text": "A single, universally standardized TENS mode and parameter set should always be used for every patient regardless of their presentation"},{"key": "B","text": "TENS mode selection has no bearing on clinical outcomes and can be chosen entirely at random"},{"key": "C","text": "Selection should consider the specific clinical presentation, pain characteristics, patient preference/tolerance, and desired onset/duration of effect, recognizing that different TENS modes are theorized to work through somewhat different mechanisms and may be more or less suited to different clinical scenarios"},{"key": "D","text": "Only conventional TENS parameters should ever be used, regardless of the clinical scenario"}],"correct": "C","explanation": "Thoughtful selection among the various TENS modes should be individualized based on the specific clinical presentation, pain characteristics, patient tolerance/preference, and desired treatment goals (e.g., rapid but short-lived relief versus potentially more delayed but longer-lasting effect), reflecting the differing proposed mechanisms underlying each mode."},{"id": 5372,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the term 'segmental' versus 'extrasegmental' (or 'heterosegmental') electrode placement strategies for TENS?","options": [{"key": "A","text": "Segmental placement refers to positioning electrodes within the same spinal segment/dermatome as the pain source (e.g., directly over or around the painful area), whereas extrasegmental placement uses points outside the affected segment (e.g., contralateral limb or distant acupuncture-like points), which may be useful when direct segmental placement is impractical (e.g., due to hypersensitivity)"},{"key": "B","text": "Segmental and extrasegmental refer to identical placement strategies with no meaningful distinction"},{"key": "C","text": "Extrasegmental placement is never used in clinical TENS practice"},{"key": "D","text": "Segmental placement always refers to electrode placement on the spine itself"}],"correct": "A","explanation": "Segmental placement targets the same neurological segment as the pain source, while extrasegmental (heterosegmental) placement uses more distant points, which can be a useful alternative strategy when direct placement over/near the painful area is impractical or poorly tolerated (e.g., due to hypersensitivity or open wounds)."},{"id": 5373,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an appropriate strategy for TENS electrode placement when the primary painful area itself is too hypersensitive (allodynic) to tolerate direct electrode contact?","options": [{"key": "A","text": "Only extremely high intensity should be used directly on the hypersensitive area to overcome the sensitivity"},{"key": "B","text": "TENS should always be applied directly on the most hypersensitive point regardless of tolerance"},{"key": "C","text": "TENS cannot be used at all in any patient with area-specific hypersensitivity"},{"key": "D","text": "Electrodes can be placed proximally, along the relevant nerve distribution/dermatome away from the hypersensitive area, or using a contralateral/extrasegmental approach, to still engage relevant neural pathways while avoiding direct stimulation of the intolerant area"}],"correct": "D","explanation": "When the primary painful area is too hypersensitive for direct electrode placement, alternative strategies such as proximal, dermatomal, or contralateral/extrasegmental placement can allow continued use of TENS while avoiding direct stimulation of the intolerant region."},{"id": 5374,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best explains the rationale for sometimes placing TENS electrodes at classic acupuncture point locations, particularly for AL-TENS approaches?","options": [{"key": "A","text": "Acupuncture point-based placement is used exclusively for conventional (Gate Control) TENS, never for AL-TENS"},{"key": "B","text": "Acupuncture points have no established relationship to TENS electrode placement strategies"},{"key": "C","text": "Some AL-TENS protocols draw on traditional acupuncture point locations as a framework for electrode placement, theorized (along with the low-frequency, motor-level stimulation parameters) to help engage similar physiological pain-modulating pathways, including opioid-related mechanisms"},{"key": "D","text": "This placement strategy has been completely abandoned and has no current clinical relevance"}],"correct": "C","explanation": "AL-TENS protocols sometimes incorporate traditional acupuncture point locations as an electrode placement framework, theorized to work alongside the characteristic low-frequency, motor-level stimulation parameters to engage pain-modulating pathways including endogenous opioid mechanisms."},{"id": 5375,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general recommendation regarding TENS pulse duration selection across different modes (e.g., conventional vs. AL-TENS)?","options": [{"key": "A","text": "Only a single universal pulse duration setting exists across all TENS devices"},{"key": "B","text": "Pulse duration has no relationship to which nerve fiber types are preferentially recruited"},{"key": "C","text": "Pulse duration is identical and fixed across all TENS modes with no variation"},{"key": "D","text": "Pulse duration is often adjusted depending on the specific mode and desired fiber recruitment (e.g., relatively shorter durations for conventional TENS targeting large sensory afferents, and potentially longer durations for modes aiming to recruit motor fibers, such as AL-TENS), though specific recommended ranges vary by device and protocol"}],"correct": "D","explanation": "Pulse duration selection can vary depending on the specific TENS mode and the type of fiber recruitment desired, generally shorter for conventional sensory-level stimulation and potentially longer for modes aiming to recruit motor fibers, such as AL-TENS."},{"id": 5376,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes a reasonable clinical approach when a patient reports diminishing TENS effectiveness over the course of a single prolonged treatment session (suggestive of accommodation)?","options": [{"key": "A","text": "Nothing can be done; TENS effectiveness always inevitably declines with no possible adjustment"},{"key": "B","text": "The device should always be turned off permanently once any accommodation is noted, with no further adjustment attempted"},{"key": "C","text": "The clinician/patient can consider adjusting stimulation parameters (e.g., switching to a modulated mode, changing frequency/intensity, or slightly repositioning electrodes) to help counteract accommodation and potentially restore perceived treatment effectiveness"},{"key": "D","text": "Increasing pulse duration to an extreme, unsafe level is the only possible solution"}],"correct": "C","explanation": "When accommodation is suspected during a prolonged session, adjusting parameters (e.g., using a modulated mode, varying frequency/intensity, or repositioning electrodes slightly) can help counteract this adaptation and potentially restore the perceived effectiveness of stimulation."},{"id": 5377,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding TENS use in patients with cognitive impairment or communication difficulties that limit their ability to reliably report discomfort?","options": [{"key": "A","text": "TENS should always be applied at maximum intensity in cognitively impaired patients to ensure adequate dosing"},{"key": "B","text": "Extra caution and closer clinician monitoring are generally warranted, since the patient's reduced ability to reliably communicate excessive discomfort or adverse sensation increases the risk that a problem could go unrecognized during treatment"},{"key": "C","text": "This consideration is only relevant for iontophoresis, not TENS"},{"key": "D","text": "Cognitive/communication status has no relevance to TENS safety considerations"}],"correct": "B","explanation": "Similar to concerns regarding impaired sensation, patients with cognitive or communication difficulties that limit their ability to reliably report discomfort warrant extra caution and closer monitoring during TENS treatment, given the reduced safety margin provided by patient feedback."},{"id": 5378,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general safety consideration regarding simultaneous use of TENS with other electrical or electronic medical devices worn by the patient?","options": [{"key": "A","text": "There is never any interaction risk between TENS and other electronic medical devices"},{"key": "B","text": "All electronic medical devices are completely unaffected by any nearby electrical stimulation under all circumstances"},{"key": "C","text": "This consideration only applies to cardiac pacemakers, with no relevance to any other type of device"},{"key": "D","text": "Potential electromagnetic interference between TENS and certain other implanted or worn electronic medical devices should be considered, and manufacturer guidance/clinical consultation regarding specific device compatibility is generally recommended when relevant devices are present"}],"correct": "D","explanation": "Given the potential for electromagnetic interference between TENS and certain other implanted/worn electronic medical devices (beyond just cardiac devices), appropriate consideration of device compatibility and manufacturer/clinical guidance is recommended when relevant devices are present."},{"id": 5379,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes the concept of 'diffuse noxious inhibitory control' (DNIC) as it may relate to certain intense electrical stimulation approaches for pain, such as brief-intense TENS?","options": [{"key": "A","text": "DNIC refers to a purely peripheral, local mechanism with no central nervous system involvement"},{"key": "B","text": "DNIC refers to a mechanism that increases, rather than decreases, pain perception"},{"key": "C","text": "DNIC describes a phenomenon whereby a strong, noxious/counter-stimulus applied at one body site can produce a generalized, centrally-mediated inhibitory effect on pain perception at other, more distant sites, which has been proposed as a potential contributing mechanism for certain intense stimulation techniques including some TENS applications"},{"key": "D","text": "DNIC is a term used exclusively in the context of iontophoresis, unrelated to TENS"}],"correct": "C","explanation": "DNIC describes a centrally-mediated phenomenon whereby a sufficiently strong counter-stimulus can produce widespread inhibitory effects on pain perception at distant sites, which has been proposed as a potential contributing mechanism for certain intense electrical stimulation approaches to pain management."},{"id": 5380,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes why TENS is sometimes used as an adjunct alongside, rather than as a replacement for, pharmacological pain management in patients with significant pain?","options": [{"key": "A","text": "TENS has no potential role in reducing reliance on pharmacological analgesics in any clinical context"},{"key": "B","text": "TENS may help reduce overall pain and, in some patients/contexts, contribute to reduced reliance on pharmacological analgesics, but is generally best considered as one component of a comprehensive, individualized pain management plan rather than a guaranteed complete substitute for medication in all cases"},{"key": "C","text": "TENS always eliminates the need for any pharmacological pain management in every patient"},{"key": "D","text": "Pharmacological and non-pharmacological pain management approaches are always mutually exclusive and cannot be combined"}],"correct": "B","explanation": "TENS is generally best integrated as part of a comprehensive, multimodal pain management approach, potentially contributing to reduced pain and, in some contexts, reduced reliance on medication, but not necessarily serving as a guaranteed complete substitute for pharmacological management in every patient."},{"id": 5381,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes an appropriate initial approach when introducing a new patient to TENS for the first time in a clinical setting?","options": [{"key": "A","text": "Begin with a lower intensity and gradually increase while explaining the expected sensation, allowing the patient to become familiar with and comfortable with the stimulation, and to provide feedback throughout the process"},{"key": "B","text": "Immediately set the device to maximum intensity without any patient orientation"},{"key": "C","text": "Apply the device without any explanation of what sensation to expect"},{"key": "D","text": "Skip any intensity titration and rely solely on a fixed, pre-set standard intensity for all patients"}],"correct": "A","explanation": "A gradual, patient-centered introduction to TENS—starting at lower intensity, explaining expected sensations, and incorporating ongoing patient feedback—supports both comfort and appropriate individualized dosing during initial treatment."},{"id": 5382,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general relationship between TENS electrode size and current density considerations, similar to principles discussed for other electrical stimulation modalities?","options": [{"key": "A","text": "Electrode size has no bearing on current density or patient comfort for TENS"},{"key": "B","text": "Smaller electrodes concentrate a given current into a smaller area, increasing current density, which could increase discomfort or risk of skin irritation if intensity is not appropriately adjusted relative to electrode size"},{"key": "C","text": "Larger electrodes always produce more concentrated, higher current density than smaller electrodes"},{"key": "D","text": "Current density considerations are only relevant to NMES, not TENS"}],"correct": "B","explanation": "As with other electrical stimulation modalities, smaller TENS electrodes concentrate current into a smaller area (higher current density), which may increase discomfort or skin irritation risk if intensity is not appropriately calibrated relative to the electrode size being used."},{"id": 5383,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes why patient-reported outcome measures (e.g., pain intensity scales, functional questionnaires) are important when evaluating the effectiveness of a TENS treatment plan over time?","options": [{"key": "A","text": "Systematically tracking patient-reported outcomes helps objectively assess whether TENS is providing meaningful clinical benefit for the individual patient, supporting informed decisions about continuing, modifying, or discontinuing the intervention as part of evidence-based practice"},{"key": "B","text": "Only the clinician's subjective impression matters, with no role for patient-reported measures"},{"key": "C","text": "Outcome measures have no relevance to evaluating TENS effectiveness in clinical practice"},{"key": "D","text": "Outcome measures are only relevant for research studies, never for routine clinical practice"}],"correct": "A","explanation": "Systematic use of patient-reported outcome measures supports evidence-based clinical decision-making regarding the ongoing use of TENS, helping to objectively determine whether meaningful benefit is being achieved for the individual patient over time."},{"id": 5384,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical reasoning process a physiotherapist should apply when considering TENS for a given patient?","options": [{"key": "A","text": "TENS decisions should be made without considering the patient's specific pain presentation or medical history"},{"key": "B","text": "A comprehensive clinical reasoning process should include appropriate patient assessment/diagnosis, consideration of contraindications/precautions, individualized selection of TENS mode and parameters, integration within a broader treatment plan, and ongoing evaluation of outcomes to guide continued use"},{"key": "C","text": "Clinical reasoning is unnecessary since all patients respond identically to a single standardized TENS protocol"},{"key": "D","text": "TENS should be applied to every patient reporting any pain, without further individualized clinical reasoning"}],"correct": "B","explanation": "Sound clinical reasoning for TENS use encompasses thorough assessment, contraindication screening, individualized mode/parameter selection, integration within the broader treatment plan, and ongoing outcome evaluation—reflecting a comprehensive, patient-centered approach rather than a one-size-fits-all application."},{"id": 5385,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Easy","question": "Interferential current therapy (IFT) is defined as:","options": [{"key": "A","text": "A form of direct current used for iontophoresis"},{"key": "B","text": "A single low-frequency current applied through one pair of electrodes"},{"key": "C","text": "A technique that uses only one electrode"},{"key": "D","text": "A technique using two medium-frequency alternating currents of slightly different frequencies, applied via two separate electrode pairs, which intersect/interfere within the tissue to produce a resultant low-frequency 'beat' current at the point of intersection"}],"correct": "D","explanation": "IFT applies two medium-frequency currents of slightly differing frequency through crossing electrode pairs; their interference within the tissue produces an amplitude-modulated low-frequency 'beat' effect at the intersection point."},{"id": 5386,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "The two medium-frequency carrier currents used in classic (4-pole) IFT are typically in the range of:","options": [{"key": "A","text": "Approximately 4000-4100 Hz (with one fixed carrier, e.g., 4000 Hz, and the other varying, e.g., 4000-4150 Hz, to produce the desired beat frequency)"},{"key": "B","text": "500,000 Hz or higher"},{"key": "C","text": "1-10 Hz"},{"key": "D","text": "50-60 Hz (standard mains frequency)"}],"correct": "A","explanation": "Classic 4-pole IFT typically uses two medium-frequency carrier currents around 4000 Hz, with one fixed and the other varied slightly to produce the desired resultant beat frequency, commonly in ranges such as 4000 and 4000-4150 Hz."},{"id": 5387,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "The 'beat frequency' produced by the interference of the two medium-frequency currents in IFT is calculated as:","options": [{"key": "A","text": "The sum of the two carrier frequencies"},{"key": "B","text": "The average of the two carrier frequencies"},{"key": "C","text": "The mathematical difference between the two carrier frequencies (e.g., a 4000 Hz current interfering with a 4100 Hz current produces a 100 Hz beat frequency)"},{"key": "D","text": "Always a fixed value of exactly 4000 Hz regardless of the carrier frequencies used"}],"correct": "C","explanation": "The resultant beat frequency equals the numerical difference between the two interfering medium-frequency carrier currents (e.g., 4100 Hz minus 4000 Hz = 100 Hz beat frequency)."},{"id": 5388,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "A key theoretical advantage of using medium-frequency carrier currents (rather than directly applying a low-frequency current) in IFT is:","options": [{"key": "A","text": "Medium-frequency currents cannot penetrate skin at all"},{"key": "B","text": "Medium-frequency currents always produce weaker, less effective stimulation"},{"key": "C","text": "Medium-frequency current is thought to meet less skin impedance/resistance, allowing more comfortable current penetration to deeper tissue, while the interference effect still produces the desired low-frequency physiological stimulation at the intersection point deep within the tissue"},{"key": "D","text": "There is no theoretical advantage to using medium-frequency carrier currents"}],"correct": "C","explanation": "Since tissue impedance (particularly skin's capacitive reactance) decreases at higher frequencies, the medium-frequency carrier currents encounter comparatively less resistance, allowing more comfortable penetration, while their interference still produces the intended low-frequency physiological effect deep within the tissue at the crossing point."},{"id": 5389,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "Classic (4-pole) IFT requires how many electrodes, arranged in how many circuits/channels?","options": [{"key": "A","text": "Four electrodes arranged in two separate circuits/channels, positioned so the two currents cross within the tissue"},{"key": "B","text": "A single electrode with a return pad"},{"key": "C","text": "Two electrodes in a single circuit"},{"key": "D","text": "Six electrodes in three circuits"}],"correct": "A","explanation": "Classic 4-pole IFT uses four electrodes (two pairs, forming two separate circuits) positioned so that the two medium-frequency currents cross within the target tissue, producing the interference effect at their intersection."},{"id": 5390,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "In classic 4-pole IFT, the two electrode pairs (circuits) should ideally be positioned so that the currents:","options": [{"key": "A","text": "Are positioned on the exact same line with no angular offset"},{"key": "B","text": "Cross each other at approximately a 45-90 degree angle within the target tissue, so that the point of maximal interference (and thus maximal 'beat' effect) occurs at the desired treatment area/depth"},{"key": "C","text": "Run parallel to each other, never crossing"},{"key": "D","text": "Never actually intersect within the body"}],"correct": "B","explanation": "For effective interference, the two circuits should be positioned so their current pathways cross (commonly described as crossing at a roughly perpendicular or oblique angle) within the tissue, placing the treatment area at or near the point of maximal interference."},{"id": 5391,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "'Premodulated' (2-pole) interferential current refers to a technique in which:","options": [{"key": "A","text": "This technique requires six electrodes"},{"key": "B","text": "Two separate medium-frequency currents are applied via four electrodes and interfere within the tissue"},{"key": "C","text": "No interference effect occurs with this technique"},{"key": "D","text": "The interference/amplitude modulation of the two medium-frequency currents is performed electronically within the device itself before delivery, allowing the already-modulated current to be applied via a single electrode pair (two electrodes, one circuit)"}],"correct": "D","explanation": "Premodulated (2-pole) IFT performs the amplitude modulation electronically inside the stimulator, so the resultant modulated current can be delivered through just one electrode pair (two electrodes), rather than requiring two separate crossing circuits."},{"id": 5392,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "A potential limitation of premodulated (2-pole) IFT compared to classic 4-pole IFT is:","options": [{"key": "A","text": "Premodulated IFT always penetrates deeper into tissue than 4-pole IFT"},{"key": "B","text": "Premodulated IFT requires more electrodes than 4-pole IFT"},{"key": "C","text": "Since the interference/modulation occurs within the device before the current reaches the tissue, the true physiological interference effect occurring specifically at depth within the tissue (as with 4-pole IFT) is not replicated in the same way, meaning the treatment effect may be more superficially concentrated, similar in some respects to other pre-modulated low-frequency currents"},{"key": "D","text": "There is no meaningful difference between premodulated and 4-pole IFT"}],"correct": "C","explanation": "Because premodulated IFT delivers an already-modulated current (rather than producing true interference within the tissue itself), some clinicians and theorists suggest it may not replicate the deep tissue interference effect proposed for classic 4-pole IFT, potentially resulting in effects more comparable to other superficially-modulated low-frequency currents."},{"id": 5393,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "The primary proposed therapeutic effects of IFT include:","options": [{"key": "A","text": "IFT has no proposed therapeutic mechanism"},{"key": "B","text": "Pain modulation (via mechanisms similar to those proposed for TENS, given the resultant low 'beat' frequency), and potentially improved circulation/edema reduction"},{"key": "C","text": "Only wound healing, with no other proposed effects"},{"key": "D","text": "Only muscle strengthening, with no effect on pain"}],"correct": "B","explanation": "IFT's proposed benefits include pain modulation (through mechanisms analogous to those underlying TENS, given the low resultant beat frequency) and effects on circulation, with some clinical use also directed toward edema management."},{"id": 5394,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "The proposed mechanism of pain relief with IFT set at a beat frequency in the range of approximately 80-150 Hz is most similar to which TENS mechanism?","options": [{"key": "A","text": "Acupuncture-like (opioid-mediated) mechanism"},{"key": "B","text": "There is no established mechanism at this frequency range"},{"key": "C","text": "Gate Control Theory mechanism, given the similarity to conventional (high-frequency) TENS parameters"},{"key": "D","text": "Direct anesthetic nerve blockade"}],"correct": "C","explanation": "A beat frequency in the higher range (e.g., ~80-150 Hz) is theorized to engage a gate-control-type mechanism, analogous to conventional high-frequency TENS."},{"id": 5395,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "The proposed mechanism of pain relief with IFT set at a lower beat frequency (e.g., approximately 1-5 Hz) is most similar to which TENS mechanism?","options": [{"key": "A","text": "Gate Control Theory mechanism exclusively"},{"key": "B","text": "There is no established mechanism at low beat frequencies"},{"key": "C","text": "Acupuncture-like (opioid-mediated) mechanism, analogous to low-frequency AL-TENS"},{"key": "D","text": "Direct anesthetic nerve blockade"}],"correct": "C","explanation": "A lower beat frequency setting (e.g., ~1-5 Hz) is theorized to engage mechanisms more analogous to acupuncture-like TENS, potentially involving endogenous opioid-related pain modulation."},{"id": 5396,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "'Sweep' (or 'scan') mode in IFT refers to a feature in which:","options": [{"key": "A","text": "The beat frequency remains completely fixed and unchanging throughout treatment"},{"key": "B","text": "This feature refers exclusively to varying the intensity, never the frequency"},{"key": "C","text": "The beat frequency is automatically and continuously varied between two pre-set values throughout the treatment session, which is theorized to help minimize accommodation and potentially engage a broader range of physiological effects associated with different frequency ranges"},{"key": "D","text": "Sweep mode is unique to premodulated IFT and cannot be used with 4-pole IFT"}],"correct": "C","explanation": "Sweep (scan) mode automatically varies the beat frequency between two set values during treatment, theorized to help reduce accommodation and potentially provide a combination of physiological effects associated with the different frequencies traversed during the sweep."},{"id": 5397,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "The 'vector field' or 'dynamic interference pattern' produced by classic 4-pole IFT refers to:","options": [{"key": "A","text": "A pattern used exclusively in premodulated IFT"},{"key": "B","text": "A completely static, unchanging pattern of maximal interference at a single fixed point"},{"key": "C","text": "The pattern of interference that forms a clover-leaf-shaped (four-lobed) distribution around the crossing point of the two currents, with the zone of maximal interference intensity varying/rotating in position as the phase relationship between the two currents cycles, theoretically distributing treatment effect over a broader area than a single fixed point"},{"key": "D","text": "A term with no established meaning in interferential current theory"}],"correct": "C","explanation": "The interference pattern in classic 4-pole IFT forms a characteristic four-lobed (clover-leaf) distribution, with the zone of peak interference intensity continuously varying in position as the phase relationship between the two currents cycles, theoretically distributing the treatment effect over a broader tissue area than a single static point."},{"id": 5398,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following is a proposed advantage of the dynamic, rotating interference pattern produced by classic 4-pole IFT, compared to a stimulus concentrated at a single fixed point?","options": [{"key": "A","text": "It has no proposed advantage over fixed-point stimulation"},{"key": "B","text": "It only affects superficial tissue, never deeper structures"},{"key": "C","text": "It concentrates all stimulation intensity at a single unchanging point, maximizing localized effect"},{"key": "D","text": "It is theorized to distribute the treatment effect across a broader area of tissue and potentially reduce accommodation, since the point(s) of maximal stimulation intensity continuously shift position during treatment"}],"correct": "D","explanation": "The continuously shifting zone of maximal interference intensity is theorized to provide a broader distribution of treatment effect across the tissue and potentially help reduce accommodation compared to stimulation concentrated at a single fixed point."},{"id": 5399,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general depth of tissue penetration typically attributed to IFT, compared to standard low-frequency TENS?","options": [{"key": "A","text": "IFT only affects skin, with no penetration to any deeper tissue"},{"key": "B","text": "IFT's medium-frequency carrier currents are theorized to allow relatively deeper tissue penetration compared to typical low-frequency TENS currents, due to reduced skin impedance at the higher carrier frequency, though the actual clinical significance and degree of this difference continues to be studied/debated"},{"key": "C","text": "IFT and standard TENS have been definitively proven to produce identical tissue penetration with no difference whatsoever"},{"key": "D","text": "IFT is generally considered incapable of any meaningful tissue penetration"}],"correct": "B","explanation": "IFT's use of medium-frequency carrier currents is theorized to allow comparatively deeper, more comfortable tissue penetration than standard low-frequency TENS (due to reduced skin impedance at higher frequency), though the precise clinical magnitude of this theoretical advantage remains an area of ongoing research interest."},{"id": 5400,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes appropriate patient positioning/electrode arrangement considerations for classic 4-pole IFT when treating a joint such as the knee?","options": [{"key": "A","text": "Electrode pairs are typically arranged so the two circuits cross diagonally around the joint (e.g., one pair placed medial-lateral, the other placed in a crossing diagonal pattern), positioning the joint at the anticipated area of maximal interference"},{"key": "B","text": "Only a single electrode pair should ever be used for joint treatment, regardless of the IFT mode selected"},{"key": "C","text": "Electrodes should always be placed randomly with no consideration of anatomical crossing pattern"},{"key": "D","text": "Electrode crossing pattern has no relevance to treatment effectiveness"}],"correct": "A","explanation": "For effective 4-pole IFT around a joint, electrode pairs are typically arranged in a crossing pattern (e.g., diagonally positioned circuits) so that the joint/target area falls within the zone of maximal current interference."},{"id": 5401,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best explains why suction electrodes are sometimes used in IFT application, particularly for certain body regions?","options": [{"key": "A","text": "Suction electrodes have no functional advantage over standard adhesive electrodes"},{"key": "B","text": "Suction electrodes are used exclusively for direct current/iontophoresis, never for IFT"},{"key": "C","text": "Suction electrodes eliminate the need for any conductive medium/gel"},{"key": "D","text": "Suction electrodes can help maintain secure, even electrode contact (particularly over irregularly contoured body areas) without requiring adhesive or manual strapping, which may improve consistency of current delivery"}],"correct": "D","explanation": "Suction-cup style electrodes can provide secure, even contact over irregularly shaped body areas without relying on adhesive, which may help maintain consistent electrode positioning and current delivery during IFT treatment."},{"id": 5402,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is a commonly cited contraindication for IFT, similar to other electrical stimulation modalities, related to cardiac devices?","options": [{"key": "A","text": "IFT has no established contraindications related to cardiac devices"},{"key": "B","text": "Application over or near a cardiac pacemaker/implantable cardioverter-defibrillator, or in a pathway that could direct current transthoracically, due to risk of electrical interference with the device"},{"key": "C","text": "This contraindication is unique to IFT and does not apply to other electrical stimulation modalities"},{"key": "D","text": "IFT is always completely safe to apply directly over any cardiac device with no precaution needed"}],"correct": "B","explanation": "As with other electrical stimulation modalities, IFT application near cardiac pacemakers/ICDs or in a transthoracic pathway carries a risk of device interference and is generally contraindicated or requires significant caution."},{"id": 5403,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "IFT is generally contraindicated over the abdomen/pelvis/lumbar region during pregnancy for the same rationale applied to other electrical stimulation modalities, namely:","options": [{"key": "A","text": "The uncertain and not well-established effects of electrical current on fetal development, leading to standard precautionary avoidance in this region during pregnancy"},{"key": "B","text": "This precaution only applies to premodulated IFT, not classic 4-pole IFT"},{"key": "C","text": "There is no established concern regarding IFT and pregnancy"},{"key": "D","text": "IFT has been definitively proven safe during pregnancy in all circumstances with strong supporting evidence"}],"correct": "A","explanation": "Consistent with the general precaution applied to most electrical stimulation modalities, IFT application over the abdomen/pelvis/lumbar region is generally avoided during pregnancy given the uncertain effects on fetal development."},{"id": 5404,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "IFT electrode placement directly over the carotid sinus region is contraindicated for the same reason cited for other electrical modalities, namely the risk of:","options": [{"key": "A","text": "Muscle spasm exclusively, with no cardiovascular concern"},{"key": "B","text": "Triggering a reflexive cardiovascular response (e.g., bradycardia, hypotension) via stimulation of baroreceptors in this region"},{"key": "C","text": "No actual risk; this is a myth without clinical basis"},{"key": "D","text": "Causing an immediate seizure"}],"correct": "B","explanation": "The carotid sinus baroreceptors are sensitive to electrical stimulation, and current in this region risks provoking a reflexive drop in heart rate/blood pressure, making this a standard contraindication for IFT electrode placement as with other electrical modalities."},{"id": 5405,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "IFT application directly over or near a known/suspected malignancy is generally considered a contraindication primarily due to:","options": [{"key": "A","text": "No established concern; there is no theoretical basis for this precaution"},{"key": "B","text": "This contraindication only applies to modalities that produce significant heat, not IFT"},{"key": "C","text": "The general theoretical concern (applied broadly across electrotherapy modalities) that increased local blood flow/cellular activity from stimulation could potentially influence tumor behavior, despite limited definitive evidence specific to IFT"},{"key": "D","text": "IFT is proven to definitively worsen all malignancies with strong supporting clinical evidence"}],"correct": "C","explanation": "Similar to the standard precaution applied across most electrotherapy modalities, IFT over known/suspected malignancy is generally avoided due to theoretical concerns about stimulating local blood flow/cellular activity, despite limited definitive IFT-specific evidence."},{"id": 5406,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "IFT application over areas of active or suspected deep vein thrombosis (DVT) is generally contraindicated primarily due to:","options": [{"key": "A","text": "IFT is known to definitively dissolve blood clots safely"},{"key": "B","text": "This precaution applies only to NMES, not IFT"},{"key": "C","text": "The theoretical risk that increased local circulation/muscle activity stimulated by treatment could dislodge a thrombus, risking embolism"},{"key": "D","text": "No established concern regarding DVT and IFT"}],"correct": "C","explanation": "As with other electrical stimulation modalities capable of increasing local circulation or producing muscle activity, IFT over an area of known/suspected DVT is generally contraindicated due to the theoretical risk of dislodging a thrombus."},{"id": 5407,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following patient populations warrants particular caution with IFT electrode placement over/around the head, related to seizure risk?","options": [{"key": "A","text": "IFT has no established relationship to seizure risk under any circumstances"},{"key": "B","text": "Patients with any history of epilepsy/seizure disorder generally warrant caution or contraindication for placement in a transcerebral pathway, similar to precautions for other electrical stimulation modalities in this context"},{"key": "C","text": "Seizure disorder is only relevant to modalities producing heat, not IFT"},{"key": "D","text": "This precaution applies only to premodulated IFT, not classic 4-pole IFT"}],"correct": "B","explanation": "Consistent with precautions for other electrical stimulation modalities, caution or contraindication generally applies to IFT electrode placement in a transcerebral pathway for patients with a known seizure disorder."},{"id": 5408,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes appropriate patient sensation expectations for IFT treatment, similar to expectations set for conventional TENS?","options": [{"key": "A","text": "Patients should always experience significant pain during effective IFT treatment"},{"key": "B","text": "Patients typically experience a comfortable tingling or 'pins and needles' type sensation, and should be instructed to report any sharp, burning, or excessively uncomfortable sensation immediately, which may indicate a parameter or electrode contact issue requiring adjustment"},{"key": "C","text": "Sensation during IFT has no relevance to appropriate parameter selection"},{"key": "D","text": "Patients should expect complete numbness with no perceptible sensation whatsoever"}],"correct": "B","explanation": "Similar to TENS, IFT typically produces a comfortable tingling sensation at appropriate intensity, and patients should be educated to report any sharp or burning sensation immediately, as this may signal an issue requiring parameter or electrode adjustment."},{"id": 5409,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best describes the general clinical dosing approach for IFT intensity, similar to principles used for TENS?","options": [{"key": "A","text": "Intensity is generally adjusted to achieve a strong but comfortable sensory (or, for some applications, mild motor-level) response, tailored to the specific treatment goal and beat frequency setting being used"},{"key": "B","text": "Intensity has no bearing on the therapeutic effectiveness of IFT"},{"key": "C","text": "Intensity should always be kept at the lowest possible, barely perceptible level regardless of the treatment goal"},{"key": "D","text": "IFT intensity must always be set identically regardless of the specific frequency parameters chosen"}],"correct": "A","explanation": "As with TENS, IFT intensity is generally titrated to achieve a strong, comfortable sensory response (or, in some protocols, a mild motor response), individualized to the specific treatment goal and selected frequency parameters."},{"id": 5410,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes a key difference between the electrical characteristics of IFT and conventional low-frequency TENS at the level of current delivered to the skin surface?","options": [{"key": "A","text": "IFT delivers medium-frequency current to the skin surface (with the low-frequency 'beat' effect occurring through interference within deeper tissue for 4-pole IFT), whereas conventional TENS delivers the low-frequency (or higher-frequency, sensory-level) pulsed current directly to the skin without this interference mechanism"},{"key": "B","text": "There is no meaningful difference; both modalities deliver identical low-frequency current directly to the skin"},{"key": "C","text": "IFT delivers only direct current to the skin, unlike TENS which delivers alternating current"},{"key": "D","text": "TENS always uses medium-frequency carrier currents identical to IFT"}],"correct": "A","explanation": "A key distinguishing feature of classic 4-pole IFT is that medium-frequency current (rather than the resultant low-frequency signal directly) is what is actually delivered to the skin surface via each circuit, with the physiologically relevant low-frequency interference effect occurring within the tissue at the crossing point, unlike conventional TENS which directly delivers its pulsed current characteristics to the skin."},{"id": 5411,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best summarizes the current state of research evidence regarding whether classic 4-pole IFT provides genuinely superior clinical outcomes compared to other electrical stimulation modalities (e.g., TENS) for pain management?","options": [{"key": "A","text": "IFT has been definitively proven completely ineffective compared to all other modalities in every study conducted"},{"key": "B","text": "The comparative research evidence is mixed, with some studies suggesting potential benefits of IFT for certain applications while others show no clear superiority over other modalities like TENS, making this an area of continued research interest rather than a definitively settled question"},{"key": "C","text": "Research evidence conclusively and universally proves IFT is superior to all other electrical stimulation modalities for every condition"},{"key": "D","text": "There is no research evidence whatsoever comparing IFT to other electrical stimulation modalities"}],"correct": "B","explanation": "The comparative effectiveness research for IFT versus other electrical stimulation modalities (such as TENS) shows mixed results, without clear, definitive evidence of consistent superiority, reflecting an area of ongoing research and clinical discussion rather than settled consensus."},{"id": 5412,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes a proposed clinical application of IFT for edema management, and its theorized mechanism?","options": [{"key": "A","text": "IFT is known to always worsen edema with no potential benefit"},{"key": "B","text": "Edema management applications are unique to direct current, never applicable to IFT"},{"key": "C","text": "IFT has no proposed application for edema management"},{"key": "D","text": "Certain IFT parameters/protocols have been proposed to help promote local circulation and lymphatic/venous return through rhythmic stimulation effects, theoretically assisting in edema reduction, though the strength of specific supporting evidence for this application varies"}],"correct": "D","explanation": "IFT has been proposed as a potential adjunct for edema management, theorized to work through rhythmic stimulation effects promoting local circulation and lymphatic/venous return, though the strength and consistency of supporting evidence for this specific application varies across the literature."},{"id": 5413,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the term 'quadripolar' IFT technique, as another name sometimes used for classic 4-pole IFT?","options": [{"key": "A","text": "Quadripolar IFT is simply another descriptive term for classic 4-pole IFT, referring to the four electrodes arranged in two separate circuits that cross within the tissue to produce true interference"},{"key": "B","text": "Quadripolar refers to a technique using only two electrodes"},{"key": "C","text": "This term has no established meaning in interferential current terminology"},{"key": "D","text": "Quadripolar IFT refers exclusively to premodulated (2-pole) IFT"}],"correct": "A","explanation": "'Quadripolar' is essentially synonymous with classic 4-pole IFT, referring to the four-electrode, two-circuit arrangement used to produce genuine tissue interference at the crossing point."},{"id": 5414,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes 'bipolar' IFT, as another term sometimes used to describe the premodulated technique?","options": [{"key": "A","text": "This term has no established relationship to premodulated IFT"},{"key": "B","text": "Bipolar IFT refers exclusively to classic 4-pole IFT"},{"key": "C","text": "Bipolar IFT is another term for premodulated (2-pole) IFT, referring to the single electrode pair (two electrodes, one circuit) used to deliver the already internally-modulated current"},{"key": "D","text": "Bipolar IFT refers to a technique using six electrodes in three circuits"}],"correct": "C","explanation": "'Bipolar' IFT is essentially synonymous with premodulated (2-pole) IFT, referring to the single electrode pair/circuit configuration used to deliver the internally pre-modulated current."},{"id": 5415,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding IFT electrode placement to ensure the treatment area falls within the effective zone of current crossing/interference in classic 4-pole IFT?","options": [{"key": "A","text": "Only a single electrode circuit is ever needed regardless of the desired treatment depth"},{"key": "B","text": "IFT electrodes should always be placed as far apart as possible with no consideration of crossing pattern"},{"key": "C","text": "Electrode placement is completely arbitrary with no bearing on treatment effectiveness"},{"key": "D","text": "The two electrode circuits must be positioned such that their current pathways actually cross at or near the target treatment area/depth, since interference (and thus the therapeutic low-frequency 'beat' effect) only occurs at the point(s) where the two currents intersect"}],"correct": "D","explanation": "Since the therapeutic interference effect in classic 4-pole IFT specifically occurs at the point(s) where the two current pathways cross, careful electrode placement is essential to ensure this crossing zone coincides with the intended treatment area and depth."},{"id": 5416,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes the general parameter range considerations for selecting a beat frequency in IFT for a primarily acute, highly irritable pain presentation, drawing on principles similar to TENS mode selection?","options": [{"key": "A","text": "Only a single, universal beat frequency setting exists regardless of clinical presentation"},{"key": "B","text": "Beat frequency selection has no relationship to the irritability or acuity of the presenting condition"},{"key": "C","text": "A very low, motor-level beat frequency should always be used regardless of irritability level"},{"key": "D","text": "A higher beat frequency (e.g., in ranges more consistent with a gate-control type mechanism) at a comfortable sensory intensity is often favored for acute, highly irritable presentations, similar to the rationale for using conventional TENS parameters in such cases"}],"correct": "D","explanation": "Similar to TENS mode selection principles, higher beat frequency settings (gate-control-type parameters) at a comfortable sensory intensity are often favored for acute, highly irritable presentations, reserving lower-frequency, more intense parameters for situations where a longer-lasting, opioid-mediated effect may be more appropriate."},{"id": 5417,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes why some clinicians may select a sweep/scan mode with a wide frequency range (e.g., spanning from a low to a higher beat frequency) for certain IFT applications?","options": [{"key": "A","text": "Sweep mode with a wide range always produces a weaker treatment effect than a single fixed frequency"},{"key": "B","text": "A wide sweep range may be used to theoretically engage a broader combination of physiological mechanisms (spanning gate-control and opioid-related effects) within a single treatment session, while also helping to reduce accommodation"},{"key": "C","text": "Sweep mode is only ever used with a very narrow frequency range, never a wide range"},{"key": "D","text": "Frequency range selection within sweep mode has no bearing on the treatment approach"}],"correct": "B","explanation": "A wide sweep range is sometimes selected to theoretically combine potential benefits across different frequency-dependent mechanisms (gate control and opioid-related effects) within one session, in addition to the general accommodation-reducing benefit of sweep/scan modes."},{"id": 5418,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate clinical approach to selecting between classic 4-pole IFT and premodulated (2-pole) IFT for a specific patient presentation?","options": [{"key": "A","text": "There is no meaningful clinical distinction to consider when choosing between these two techniques"},{"key": "B","text": "2-pole IFT should always be used exclusively regardless of any other consideration"},{"key": "C","text": "The choice may depend on factors such as the treatment area's size/shape (e.g., 2-pole may be more practical for smaller, localized areas), equipment availability, and clinician preference/training, recognizing the theoretical differences in how each technique produces its effect"},{"key": "D","text": "4-pole IFT should always be used exclusively, regardless of the clinical scenario, treatment area, or equipment availability"}],"correct": "C","explanation": "Selection between 4-pole and 2-pole (premodulated) IFT often depends on practical factors such as the size/shape of the treatment area, available equipment, and clinician preference, alongside consideration of the theoretical differences between true tissue interference and internally pre-modulated current delivery."},{"id": 5419,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important documentation practice following IFT treatment, similar to other electrical stimulation modalities?","options": [{"key": "A","text": "IFT documentation should never include any information about patient-reported sensation or tolerance"},{"key": "B","text": "Documentation is unnecessary for IFT since it carries no risk of adverse effects"},{"key": "C","text": "Only the total treatment time needs to be recorded, with no other parameters relevant"},{"key": "D","text": "Documentation should include the specific parameters used (e.g., carrier frequency, beat frequency/sweep range, intensity, electrode configuration/placement, treatment duration), patient tolerance/response, and any relevant skin findings"}],"correct": "D","explanation": "Thorough documentation of IFT parameters, patient response, and any skin findings supports continuity of care, appropriate treatment progression, and communication among the healthcare team, similar to documentation practices for other electrical stimulation modalities."},{"id": 5420,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Hard","question": "Which of the following best describes why IFT is sometimes proposed as potentially more comfortable for patients who find standard low-frequency TENS uncomfortable at higher intensities?","options": [{"key": "A","text": "Comfort level has no relationship to the underlying carrier frequency used in electrical stimulation"},{"key": "B","text": "IFT is universally proven to always be more comfortable than TENS in every patient, with no exceptions"},{"key": "C","text": "Since IFT's medium-frequency carrier current is theorized to encounter less skin impedance, some patients may tolerate a higher effective intensity more comfortably compared to a directly-applied low-frequency current, potentially allowing more robust dosing in some individuals, though patient response varies"},{"key": "D","text": "IFT is always less comfortable than standard TENS in every patient"}],"correct": "C","explanation": "The theorized reduced skin impedance encountered by IFT's medium-frequency carrier current may allow some patients to tolerate higher effective stimulation intensity more comfortably compared to directly-applied low-frequency current, though individual patient response and comfort can vary considerably."},{"id": 5421,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general principle behind selecting electrode size for IFT treatment of a larger versus smaller target area?","options": [{"key": "A","text": "Larger electrodes should always be used regardless of the specific treatment area, with no consideration of current density"},{"key": "B","text": "Electrode size and spacing are generally adjusted based on the size and location of the target treatment area, ensuring the crossing pattern of the circuits appropriately encompasses the intended zone of treatment while considering current density implications"},{"key": "C","text": "Electrode size selection has no relevance to IFT treatment planning"},{"key": "D","text": "A single fixed electrode size must always be used regardless of the treatment area's size"}],"correct": "B","explanation": "Electrode size and placement/spacing should be thoughtfully selected based on the target area's size and location, ensuring the interference crossing pattern appropriately covers the intended treatment zone while considering appropriate current density for patient comfort and safety."},{"id": 5422,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes a reasonable approach to monitoring and adjusting IFT treatment during a session, particularly regarding patient comfort and perceived effectiveness?","options": [{"key": "A","text": "Only the clinician's observation matters; patient-reported sensation should be disregarded during treatment"},{"key": "B","text": "No monitoring or adjustment should ever occur once treatment parameters are initially set"},{"key": "C","text": "Adjustments during treatment are never appropriate or necessary for IFT"},{"key": "D","text": "Ongoing communication with the patient regarding comfort, sensation, and perceived effect allows the clinician to make appropriate real-time adjustments to intensity or other parameters as needed throughout the treatment session"}],"correct": "D","explanation": "Ongoing patient communication throughout the IFT session supports appropriate real-time parameter adjustments, helping optimize both comfort and therapeutic effectiveness during treatment."},{"id": 5423,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the relevance of understanding the underlying physics of interference (wave superposition) for clinicians using IFT clinically?","options": [{"key": "A","text": "Understanding the underlying physics has no practical relevance to clinical IFT application"},{"key": "B","text": "The physics of wave interference is completely irrelevant to achieving effective clinical outcomes with IFT"},{"key": "C","text": "Only engineers need to understand the physics of interference; clinicians require no such understanding"},{"key": "D","text": "A basic understanding of how the interference of two slightly different frequency currents produces the resultant beat frequency helps clinicians make informed decisions about parameter selection (carrier and beat frequencies) and electrode placement to achieve the intended physiological effect at the appropriate treatment depth/location"}],"correct": "D","explanation": "A foundational understanding of the interference principle underlying IFT supports informed clinical decision-making regarding parameter selection and electrode placement, helping ensure the interference effect is appropriately directed to achieve the intended therapeutic outcome."},{"id": 5424,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general safety profile of IFT when applied by a trained clinician following standard guidelines in an appropriately screened patient?","options": [{"key": "A","text": "IFT carries no risk whatsoever under any circumstances, eliminating the need for any screening or precautions"},{"key": "B","text": "Safety considerations for IFT are entirely unrelated to those applicable to other electrical stimulation modalities"},{"key": "C","text": "IFT is inherently dangerous and should essentially never be used in clinical practice under any circumstances"},{"key": "D","text": "IFT is generally considered a safe modality when applied appropriately by a trained clinician following standard screening, contraindication, and parameter guidelines, though as with any electrical modality, attention to proper technique and individual patient factors remains important"}],"correct": "D","explanation": "When applied appropriately by a trained clinician following standard screening and guidelines, IFT is generally considered a safe therapeutic modality, though ongoing attention to contraindications, proper technique, and individual patient factors remains an important part of safe clinical practice, similar to other electrical stimulation modalities."},{"id": 5425,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate consideration regarding treatment duration for a typical IFT session, based on general clinical practice guidelines?","options": [{"key": "A","text": "IFT sessions must always be exactly 60 seconds in duration with no variation permitted"},{"key": "B","text": "IFT sessions should always last several hours regardless of the clinical goal"},{"key": "C","text": "Typical IFT treatment sessions are commonly cited in ranges of approximately 10-20 minutes, though specific duration may be adjusted based on the clinical goal, patient tolerance, and specific protocol/parameters being used"},{"key": "D","text": "Treatment duration has no bearing on IFT's therapeutic effect or safety"}],"correct": "C","explanation": "While specific protocols vary, IFT treatment sessions are commonly cited in general ranges of approximately 10-20 minutes, with adjustments made based on the specific clinical goal, patient tolerance, and chosen parameters."},{"id": 5426,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical role of IFT within a comprehensive physiotherapy treatment plan for a patient with musculoskeletal pain?","options": [{"key": "A","text": "IFT should always be used as the sole and complete treatment approach, replacing the need for any other intervention"},{"key": "B","text": "IFT has no legitimate role in any modern evidence-based physiotherapy practice"},{"key": "C","text": "IFT is generally most appropriately used as an adjunct within a broader, comprehensive treatment plan that may also include exercise, education, manual therapy, and other evidence-based interventions, rather than as a standalone comprehensive solution"},{"key": "D","text": "IFT should only ever be used in isolation, never combined with any other treatment approach"}],"correct": "C","explanation": "IFT is generally best integrated as one component within a comprehensive, individualized treatment plan, complementing other evidence-based interventions such as exercise, education, and manual therapy, rather than serving as a standalone comprehensive treatment approach."},{"id": 5427,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate skin inspection practice before and after IFT treatment?","options": [{"key": "A","text": "Skin inspection is unnecessary for IFT since it poses no risk of skin reaction"},{"key": "B","text": "The treatment area should be inspected before treatment for any contraindications (e.g., broken skin, significant sensory impairment) and after treatment for any excessive redness, irritation, or other adverse skin reaction, which should be documented and considered for subsequent treatment planning"},{"key": "C","text": "Skin inspection is only relevant for direct current-based modalities, not IFT"},{"key": "D","text": "Only the electrodes themselves need to be inspected, never the patient's skin"}],"correct": "B","explanation": "Pre- and post-treatment skin inspection is an important safety practice for IFT, helping identify contraindications before treatment and any adverse skin reactions afterward, both of which should be documented and factored into ongoing treatment planning."},{"id": 5428,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why IFT electrode gel/coupling medium is important for effective treatment delivery?","options": [{"key": "A","text": "Conductive gel is only relevant for iontophoresis, never for IFT"},{"key": "B","text": "Adequate conductive gel/coupling medium helps ensure good electrical contact between the electrode and skin, reducing localized high-resistance points that could cause discomfort or uneven current distribution"},{"key": "C","text": "IFT does not require any conductive medium between the electrode and skin"},{"key": "D","text": "Coupling medium has no relevance to IFT treatment delivery"}],"correct": "B","explanation": "As with most surface electrical stimulation modalities, adequate conductive gel/coupling medium is important for IFT to ensure good electrode-skin contact, reducing the risk of localized high-resistance points that could cause discomfort or uneven, inefficient current distribution."},{"id": 5429,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the relevance of skin temperature/moisture assessment before applying IFT electrodes?","options": [{"key": "A","text": "Skin condition assessment has no bearing on IFT electrode application"},{"key": "B","text": "Only the treatment device's settings matter, with no relevance to the patient's skin condition"},{"key": "C","text": "Skin assessment is only relevant for thermal modalities, never for electrical stimulation"},{"key": "D","text": "Assessing skin condition (e.g., excessive dryness, moisture, or temperature abnormalities) can help identify factors that might affect electrode contact quality or indicate other relevant clinical findings (e.g., signs of circulatory compromise) prior to treatment"}],"correct": "D","explanation": "Assessing the treatment area's skin condition, including moisture and temperature, can help identify factors affecting electrode contact quality and may reveal other clinically relevant findings prior to initiating IFT treatment."},{"id": 5430,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why patients with significantly impaired circulation in the treatment area may warrant additional caution with IFT application?","options": [{"key": "A","text": "Impaired circulation has no relevance to IFT safety considerations"},{"key": "B","text": "This consideration is only relevant for thermal modalities, never for electrical stimulation like IFT"},{"key": "C","text": "IFT is always completely safe regardless of the patient's circulatory status, with no need for additional caution"},{"key": "D","text": "Compromised local circulation could theoretically affect tissue tolerance to electrical stimulation and normal physiological responses (e.g., to any local heating or stimulation effects), warranting careful clinical judgment and possibly modified parameters or caution in this population"}],"correct": "D","explanation": "Similar to considerations for other electrotherapy modalities, significantly impaired local circulation may affect tissue tolerance to stimulation and warrants careful clinical judgment, potentially including modified parameters or additional caution when considering IFT for such patients."},{"id": 5431,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate approach for a clinician when a patient reports no perceptible sensation despite an apparently adequate intensity setting on the IFT device during treatment?","options": [{"key": "A","text": "The clinician should systematically troubleshoot possible causes, such as inadequate electrode contact, device malfunction, incorrect parameter settings, or reduced patient sensation, before proceeding further with treatment"},{"key": "B","text": "This scenario never occurs in clinical practice and requires no troubleshooting approach"},{"key": "C","text": "The intensity should always be immediately increased to the absolute maximum without any further assessment"},{"key": "D","text": "This finding should always be ignored, since sensation is irrelevant to IFT effectiveness"}],"correct": "A","explanation": "When a patient reports no perceptible sensation despite an apparently adequate intensity setting, systematic troubleshooting (checking electrode contact, device function, parameter settings, and patient sensory status) is an appropriate clinical response before proceeding further with treatment."},{"id": 5432,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general clinical reasoning process a physiotherapist should apply when considering IFT for a given patient's musculoskeletal pain presentation?","options": [{"key": "A","text": "IFT should be applied to every patient reporting any type of pain, without further individualized clinical reasoning"},{"key": "B","text": "IFT decisions should be made without considering the patient's specific pain presentation or medical history"},{"key": "C","text": "Clinical reasoning is unnecessary since all patients respond identically to a single standardized IFT protocol"},{"key": "D","text": "A comprehensive clinical reasoning process should include appropriate patient assessment, consideration of contraindications/precautions, individualized selection of IFT mode and parameters (carrier frequency, beat frequency, sweep settings, intensity), integration within a broader treatment plan, and ongoing evaluation of outcomes"}],"correct": "D","explanation": "Sound clinical reasoning for IFT use encompasses thorough assessment, contraindication screening, individualized parameter selection, integration within the broader treatment plan, and ongoing outcome evaluation, reflecting a comprehensive, patient-centered approach rather than a one-size-fits-all application."},{"id": 5433,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes why the term 'amplitude modulated frequency' (AMF) is sometimes used interchangeably with 'beat frequency' in IFT terminology?","options": [{"key": "A","text": "This terminology is used only in direct current applications, never in IFT"},{"key": "B","text": "AMF describes the same phenomenon as beat frequency—the resultant low-frequency envelope produced by the interference/summation of the two slightly different medium-frequency carrier currents, representing the frequency at which the amplitude of the combined signal rhythmically rises and falls"},{"key": "C","text": "AMF and beat frequency refer to entirely unrelated concepts with no overlap"},{"key": "D","text": "AMF refers exclusively to the carrier frequency, never to the resultant interference frequency"}],"correct": "B","explanation": "'Amplitude modulated frequency' (AMF) and 'beat frequency' are essentially interchangeable terms describing the same resultant low-frequency envelope produced by the interference of the two medium-frequency carrier currents in IFT."},{"id": 5434,"subject": "Electrotherapy","topic": "Electrical Stimulation","difficulty": "Medium","question": "Which of the following best summarizes an appropriate overall conclusion regarding the theoretical versus definitively proven clinical advantages of IFT over other, potentially simpler electrical stimulation modalities such as TENS?","options": [{"key": "A","text": "While IFT has plausible theoretical advantages based on its underlying biophysical principles, the definitive clinical superiority of these theoretical advantages over simpler modalities remains an area of ongoing research and some debate, and clinical decision-making should integrate available evidence with sound clinical reasoning and individual patient factors"},{"key": "B","text": "IFT has been definitively proven clinically inferior to all other electrical stimulation modalities in every study conducted"},{"key": "C","text": "There is no theoretical or clinical basis whatsoever for any of IFT's proposed mechanisms of action"},{"key": "D","text": "IFT's proposed theoretical advantages (e.g., deeper penetration, broader treatment area via the dynamic interference pattern) are well-established and definitively supported by strong, conclusive clinical evidence in all contexts"}],"correct": "A","explanation": "While IFT's underlying biophysical rationale offers plausible theoretical advantages, definitive clinical evidence establishing consistent superiority over other modalities remains an area of ongoing research and discussion, underscoring the importance of integrating available evidence with sound clinical reasoning when selecting among electrical stimulation options for individual patients."},{"id": 5435,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Easy","question": "Therapeutic ultrasound uses sound waves at frequencies:","options": [{"key": "A","text": "Above the range of human hearing (typically 1-3 MHz for therapeutic purposes)"},{"key": "B","text": "Only in the microwave frequency range"},{"key": "C","text": "Below the range of human hearing (infrasound)"},{"key": "D","text": "Exactly within the audible human hearing range"}],"correct": "A","explanation": "Therapeutic ultrasound uses high-frequency sound waves, typically in the range of 1-3 MHz, well above the audible range of human hearing (which extends up to approximately 20 kHz)."},{"id": 5436,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Ultrasound waves are generated in a therapeutic device via which physical phenomenon occurring within the transducer's crystal (typically piezoelectric ceramic)?","options": [{"key": "A","text": "Electromagnetic induction"},{"key": "B","text": "The piezoelectric effect, whereby an applied alternating electrical current causes the crystal to rapidly expand and contract, generating mechanical sound waves"},{"key": "C","text": "The Doppler effect"},{"key": "D","text": "Nuclear magnetic resonance"}],"correct": "B","explanation": "The piezoelectric effect describes how certain crystals (e.g., quartz or ceramic materials used in ultrasound transducers) mechanically deform when an alternating electrical current is applied, generating the high-frequency sound waves used therapeutically."},{"id": 5437,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Easy","question": "Commonly used therapeutic ultrasound frequencies are typically in the range of:","options": [{"key": "A","text": "10-20 MHz for all applications"},{"key": "B","text": "500-1000 kHz exclusively"},{"key": "C","text": "1-3 MHz, with 1 MHz generally used for deeper tissue and 3 MHz for more superficial tissue"},{"key": "D","text": "1-3 Hz"}],"correct": "C","explanation": "Standard therapeutic ultrasound devices typically offer 1 MHz and 3 MHz frequency settings, with 1 MHz generally penetrating deeper and 3 MHz being absorbed more superficially."},{"id": 5438,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes the relationship between ultrasound frequency and depth of tissue penetration?","options": [{"key": "A","text": "Higher frequency (e.g., 3 MHz) generally penetrates deeper than lower frequency (e.g., 1 MHz)"},{"key": "B","text": "Frequency has no relationship to depth of penetration"},{"key": "C","text": "Both 1 MHz and 3 MHz penetrate to an identical depth"},{"key": "D","text": "Lower frequency (e.g., 1 MHz) generally penetrates deeper into tissue than higher frequency (e.g., 3 MHz), since lower-frequency waves are absorbed more gradually as they travel through tissue"}],"correct": "D","explanation": "Lower frequency ultrasound (1 MHz) is absorbed more gradually and therefore penetrates deeper into tissue, while higher frequency ultrasound (3 MHz) is absorbed more rapidly and is used for more superficial targets."},{"id": 5439,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "For treating a relatively deep structure (e.g., approximately 3-5 cm depth), which ultrasound frequency would generally be more appropriate?","options": [{"key": "A","text": "Frequency selection is irrelevant to treatment depth"},{"key": "B","text": "Both frequencies penetrate identically regardless of tissue depth"},{"key": "C","text": "3 MHz"},{"key": "D","text": "1 MHz, since it penetrates more deeply before being significantly absorbed"}],"correct": "D","explanation": "1 MHz ultrasound, having a greater depth of penetration before significant absorption occurs, is generally selected for treating deeper tissue targets."},{"id": 5440,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "For treating a relatively superficial structure (e.g., approximately 1-2 cm depth), which ultrasound frequency would generally be more appropriate?","options": [{"key": "A","text": "Neither frequency can effectively treat superficial structures"},{"key": "B","text": "Frequency selection has no bearing on superficial versus deep targeting"},{"key": "C","text": "3 MHz, since it is absorbed more rapidly, concentrating energy delivery in more superficial tissue"},{"key": "D","text": "1 MHz"}],"correct": "C","explanation": "3 MHz ultrasound is absorbed more rapidly, concentrating its energy delivery within more superficial tissue layers, making it appropriate for treating shallower targets."},{"id": 5441,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Easy","question": "Continuous ultrasound refers to a mode in which:","options": [{"key": "A","text": "No ultrasound energy is being delivered at any time"},{"key": "B","text": "The ultrasound beam is delivered in an on/off (pulsed) pattern"},{"key": "C","text": "Ultrasound energy is delivered continuously, without interruption, throughout the 'on' period of treatment"},{"key": "D","text": "Ultrasound is delivered only during brief microsecond pulses separated by long rest intervals"}],"correct": "C","explanation": "Continuous mode ultrasound delivers the sound wave energy without interruption throughout the treatment's 'on' duration, in contrast to pulsed mode which interrupts delivery periodically."},{"id": 5442,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Easy","question": "Pulsed ultrasound refers to a mode in which:","options": [{"key": "A","text": "This mode is used exclusively for cavitation-based tissue destruction"},{"key": "B","text": "Ultrasound energy is delivered continuously and uninterrupted"},{"key": "C","text": "No sound waves are produced at any point during treatment"},{"key": "D","text": "Ultrasound energy delivery is interrupted periodically, alternating between brief 'on' periods and 'off' periods, characterized by the duty cycle (percentage of time the ultrasound is actively 'on')"}],"correct": "D","explanation": "Pulsed ultrasound periodically interrupts the delivery of sound wave energy, alternating between on and off periods according to the selected duty cycle."},{"id": 5443,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "'Duty cycle' in the context of therapeutic ultrasound refers to:","options": [{"key": "A","text": "The intensity of the ultrasound beam"},{"key": "B","text": "The frequency of the ultrasound waves"},{"key": "C","text": "The percentage of time the ultrasound energy is actively 'on' relative to the total on-plus-off cycle time (e.g., a 20% duty cycle means the ultrasound is on for 2 out of every 10 milliseconds, with the remainder being off time)"},{"key": "D","text": "The total treatment session duration"}],"correct": "C","explanation": "Duty cycle describes the proportion of total cycle time during which ultrasound energy is actively being delivered (on), expressed as a percentage, in pulsed mode applications."},{"id": 5444,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Continuous ultrasound (100% duty cycle) is generally associated with which primary proposed physiological effect, given the relatively greater average energy delivery?","options": [{"key": "A","text": "Effects identical to a very low duty cycle pulsed mode"},{"key": "B","text": "No physiological effect whatsoever"},{"key": "C","text": "A relatively greater thermal (heating) effect, due to the continuous, uninterrupted energy delivery, compared to pulsed modes at lower duty cycles"},{"key": "D","text": "Purely non-thermal effects with no heating whatsoever"}],"correct": "C","explanation": "Since continuous ultrasound delivers energy without interruption, it is generally associated with a greater cumulative thermal effect compared to pulsed modes, which deliver less average energy per unit time due to the interspersed 'off' periods."},{"id": 5445,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Pulsed ultrasound at lower duty cycles (e.g., 20%) is generally associated with which primary proposed effect, given the reduced average energy delivery and interspersed off periods allowing heat dissipation?","options": [{"key": "A","text": "Effects identical to continuous ultrasound at 100% duty cycle"},{"key": "B","text": "Predominantly thermal (heating) effects, similar to or greater than continuous mode"},{"key": "C","text": "No physiological effect whatsoever"},{"key": "D","text": "Predominantly non-thermal effects (e.g., mechanical/cavitation-related effects thought to influence tissue repair processes), since the interspersed off periods allow dissipated heat, minimizing significant temperature rise"}],"correct": "D","explanation": "Lower duty cycle pulsed ultrasound is generally associated with predominantly non-thermal proposed effects, since the interspersed off periods allow generated heat to dissipate, minimizing significant tissue temperature rise while still potentially producing mechanical/non-thermal bioeffects."},{"id": 5446,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following are proposed thermal effects of therapeutic ultrasound when using parameters designed to produce tissue heating (e.g., continuous mode, higher intensity)?","options": [{"key": "A","text": "Decreased tissue extensibility and decreased local blood flow"},{"key": "B","text": "Increased tissue extensibility (particularly of collagen-rich structures like tendons/joint capsules), increased local blood flow, mild analgesic effect, and potentially increased metabolic rate in the heated tissue"},{"key": "C","text": "No measurable physiological effects of any kind"},{"key": "D","text": "Complete elimination of pain with no other physiological changes"}],"correct": "B","explanation": "Thermal ultrasound effects are proposed to include increased extensibility of collagenous tissue, enhanced local blood flow, a mild analgesic effect, and increased local metabolic activity, similar in principle to other deep-heating modalities."},{"id": 5447,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following are proposed non-thermal effects of therapeutic ultrasound, theorized to occur particularly with pulsed, lower-intensity parameters?","options": [{"key": "A","text": "Cavitation, microstreaming, and acoustic streaming, which are theorized to influence cell membrane permeability and potentially stimulate cellular processes relevant to tissue repair (e.g., fibroblast activity, protein synthesis)"},{"key": "B","text": "Effects limited exclusively to bone tissue, with no relevance to soft tissue"},{"key": "C","text": "Only effects related to tissue heating"},{"key": "D","text": "Complete absence of any biological effect at the cellular level"}],"correct": "A","explanation": "Non-thermal ultrasound effects are proposed to include cavitation and microstreaming/acoustic streaming phenomena, theorized to influence cell membrane permeability and potentially stimulate various cellular processes relevant to tissue healing."},{"id": 5448,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "'Cavitation' in the context of therapeutic ultrasound refers to:","options": [{"key": "A","text": "A term describing the physical construction of the ultrasound transducer head"},{"key": "B","text": "A phenomenon that occurs only with continuous mode ultrasound, never with pulsed mode"},{"key": "C","text": "The formation and behavior of gas-filled microbubbles within tissue fluid in response to the ultrasound wave's pressure oscillations"},{"key": "D","text": "The process of heat generation exclusively, with no relationship to bubble formation"}],"correct": "C","explanation": "Cavitation describes the formation and oscillatory behavior of small gas bubbles within tissue fluids, occurring in response to the alternating pressure changes produced by the ultrasound wave."},{"id": 5449,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "'Stable cavitation' refers to a pattern in which microbubbles:","options": [{"key": "A","text": "Remain completely static with no size change whatsoever"},{"key": "B","text": "Oscillate in size in a relatively controlled, non-violent manner over multiple cycles, without collapsing violently, and is generally considered to be associated with beneficial, non-destructive bioeffects at appropriate therapeutic intensities"},{"key": "C","text": "Only occur with therapeutic ultrasound frequencies above 10 MHz"},{"key": "D","text": "Rapidly grow and then violently collapse, potentially causing tissue damage"}],"correct": "B","explanation": "Stable cavitation describes a relatively controlled oscillation of microbubble size over successive cycles without violent collapse, generally considered to be associated with the beneficial, non-destructive bioeffects sought in therapeutic ultrasound applications."},{"id": 5450,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "'Unstable (transient/inertial) cavitation' refers to a pattern in which microbubbles:","options": [{"key": "A","text": "Never occur under any circumstances with therapeutic ultrasound"},{"key": "B","text": "Are the desired mechanism for all standard therapeutic ultrasound protocols"},{"key": "C","text": "Rapidly grow in size and then violently collapse, releasing significant localized energy that could potentially cause tissue damage if occurring at inappropriate intensities/parameters"},{"key": "D","text": "Oscillate gently with no significant size change"}],"correct": "C","explanation": "Unstable (inertial) cavitation involves rapid bubble growth followed by violent collapse, releasing significant localized energy; this pattern is generally considered potentially damaging to tissue if it occurs at inappropriate (typically higher, diagnostic-range) intensities, and standard therapeutic protocols aim to avoid triggering this destructive pattern."},{"id": 5451,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "'Microstreaming' refers to:","options": [{"key": "A","text": "A phenomenon exclusive to diagnostic (not therapeutic) ultrasound"},{"key": "B","text": "The bulk movement of blood through vessels"},{"key": "C","text": "A term describing the manufacturing process of ultrasound transducers"},{"key": "D","text": "Small-scale fluid movement/circulation patterns generated around oscillating microbubbles (associated with stable cavitation) or along cell membranes, theorized to influence cellular activity and membrane permeability"}],"correct": "D","explanation": "Microstreaming describes small-scale fluid movement patterns generated by oscillating microbubbles or ultrasound wave interactions at the cellular level, theorized to contribute to non-thermal bioeffects by influencing local cellular environment and membrane permeability."},{"id": 5452,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "The 'BNR' (Beam Nonuniformity Ratio) of an ultrasound transducer is defined as:","options": [{"key": "A","text": "The ratio of the transducer's diameter to its treatment area"},{"key": "B","text": "The ratio of continuous to pulsed mode duty cycles"},{"key": "C","text": "The ratio of the peak (spatial maximum) intensity within the ultrasound beam to the average intensity across the entire effective radiating area, reflecting the uniformity/nonuniformity of energy distribution across the transducer face"},{"key": "D","text": "The frequency ratio between 1 MHz and 3 MHz settings"}],"correct": "C","explanation": "BNR quantifies how uniformly (or non-uniformly) ultrasound energy is distributed across the transducer's effective radiating area, calculated as the ratio of the peak spatial intensity to the spatial average intensity."},{"id": 5453,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "A LOWER BNR value for an ultrasound transducer is generally considered:","options": [{"key": "A","text": "Completely irrelevant to clinical treatment quality"},{"key": "B","text": "More favorable, indicating a more uniform distribution of ultrasound energy across the transducer face, which is generally associated with reduced risk of localized 'hot spots' and improved patient comfort/safety"},{"key": "C","text": "Less favorable, indicating poor energy distribution uniformity"},{"key": "D","text": "Only relevant to diagnostic, not therapeutic, ultrasound devices"}],"correct": "B","explanation": "A lower BNR indicates more uniform energy distribution across the transducer face (closer to an ideal ratio of 1:1 between peak and average intensity), which is generally considered more favorable, reducing the risk of localized energy 'hot spots' during treatment."},{"id": 5454,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "The 'effective radiating area' (ERA) of an ultrasound transducer refers to:","options": [{"key": "A","text": "The maximum depth of tissue penetration achievable with the transducer"},{"key": "B","text": "A measure of the total treatment area covered during an entire treatment session"},{"key": "C","text": "The actual portion of the transducer face that effectively emits ultrasound energy, which is typically somewhat smaller than the total physical face area of the transducer head"},{"key": "D","text": "The total physical surface area of the transducer head, including any non-emitting border/casing"}],"correct": "C","explanation": "ERA refers specifically to the portion of the transducer surface that actively emits ultrasound energy, which is generally smaller than the total physical dimensions of the transducer head (which includes a non-emitting border/casing)."},{"id": 5455,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Ultrasound intensity is typically expressed in units of:","options": [{"key": "A","text": "Volts"},{"key": "B","text": "Hertz"},{"key": "C","text": "Ohms"},{"key": "D","text": "Watts per square centimeter (W/cm²)"}],"correct": "D","explanation": "Ultrasound intensity is conventionally expressed as power per unit area, in Watts per square centimeter (W/cm²)."},{"id": 5456,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "'Spatial average intensity' (SAI) refers to:","options": [{"key": "A","text": "The maximum possible intensity a device can produce"},{"key": "B","text": "The average intensity calculated across the entire effective radiating area of the transducer, providing a general representation of the overall energy output per unit area"},{"key": "C","text": "A measure unrelated to the physical dimensions of the transducer"},{"key": "D","text": "The intensity measured at a single specific point within the beam"}],"correct": "B","explanation": "Spatial average intensity represents the average ultrasound energy output distributed across the entire effective radiating area of the transducer."},{"id": 5457,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "A coupling medium (e.g., ultrasound gel) is essential for effective ultrasound transmission primarily because:","options": [{"key": "A","text": "Air is a very poor transmitter of ultrasound energy, so a coupling medium is needed to eliminate air gaps between the transducer and skin, ensuring efficient transmission of the sound waves into the tissue"},{"key": "B","text": "It has no actual functional purpose beyond patient comfort"},{"key": "C","text": "Coupling medium is only relevant for phonophoresis, not standard ultrasound treatment"},{"key": "D","text": "Gel increases the frequency of the ultrasound waves"}],"correct": "A","explanation": "Since air poorly transmits ultrasound energy (reflecting most of it at an air-tissue interface), an appropriate coupling medium is essential to eliminate air gaps and ensure efficient transmission of sound energy from the transducer into the underlying tissue."},{"id": 5458,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following is generally considered an effective ultrasound coupling medium?","options": [{"key": "A","text": "Water-based ultrasound gel, or in some cases water immersion (e.g., for irregularly contoured body areas)"},{"key": "B","text": "Any oil-based lotion regardless of its acoustic transmission properties"},{"key": "C","text": "No coupling medium is ever needed for effective ultrasound transmission"},{"key": "D","text": "Air alone, with no gel or liquid required"}],"correct": "A","explanation": "Water-based ultrasound gel is the standard coupling medium for direct contact treatment, while water immersion technique may be used for irregularly shaped body areas (e.g., hand, foot) where direct transducer contact is difficult to maintain."},{"id": 5459,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "The underwater (immersion) technique for ultrasound application is particularly useful for treating:","options": [{"key": "A","text": "Areas where gel coupling would be equally or more effective"},{"key": "B","text": "Irregularly contoured body areas (e.g., hand, wrist, foot, ankle) where maintaining consistent direct transducer-to-skin contact with gel alone would be difficult"},{"key": "C","text": "Only flat, easily accessible body surfaces"},{"key": "D","text": "Only very deep structures inaccessible by any other technique"}],"correct": "B","explanation": "The underwater technique is particularly valuable for irregularly shaped body areas where maintaining consistent, even direct contact between the transducer and skin (using gel alone) is difficult, such as the hand, wrist, or foot."},{"id": 5460,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "During ultrasound application using the direct contact technique, maintaining constant transducer movement (rather than holding it stationary) is important primarily to:","options": [{"key": "A","text": "Avoid concentrating excessive energy at a single point, which could increase the risk of tissue damage (e.g., periosteal pain, localized overheating) and standing wave formation"},{"key": "B","text": "Constant movement is unnecessary and stationary application is always preferred"},{"key": "C","text": "Decrease the overall effectiveness of treatment with no safety rationale"},{"key": "D","text": "Increase the total treatment time required"}],"correct": "A","explanation": "Continuous transducer movement helps distribute ultrasound energy evenly across the treatment area, reducing the risk of localized energy concentration, standing wave formation, and associated tissue damage or discomfort (e.g., periosteal pain) that could occur with a stationary transducer."},{"id": 5461,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "'Standing waves' in the context of ultrasound application refer to a phenomenon in which:","options": [{"key": "A","text": "A phenomenon that always improves treatment safety and effectiveness"},{"key": "B","text": "Incident and reflected ultrasound waves interact to create stationary zones of alternating high and low pressure/intensity, which can occur particularly with a stationary transducer or at tissue interfaces with significant acoustic impedance mismatch, and are generally considered undesirable due to potential for localized tissue damage"},{"key": "C","text": "A term used only in diagnostic ultrasound, with no relevance to therapeutic applications"},{"key": "D","text": "Ultrasound waves travel only in one direction with no reflection"}],"correct": "B","explanation": "Standing waves form when incident and reflected ultrasound waves interact, creating stationary zones of alternating high and low pressure/energy concentration; this phenomenon is generally considered undesirable in therapeutic ultrasound due to the potential for localized tissue damage at points of high-pressure concentration."},{"id": 5462,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following techniques helps reduce the risk of standing wave formation during ultrasound treatment?","options": [{"key": "A","text": "Standing waves cannot be prevented or reduced by any technique"},{"key": "B","text": "Holding the transducer completely stationary throughout the entire treatment"},{"key": "C","text": "Continuously moving the transducer during application, which helps prevent the sustained, fixed wave interactions necessary for standing wave formation"},{"key": "D","text": "Increasing the treatment intensity to the maximum possible level"}],"correct": "C","explanation": "Continuous transducer movement during treatment is a key technique for reducing standing wave risk, since it prevents the sustained, fixed conditions necessary for this potentially damaging wave interaction pattern to develop."},{"id": 5463,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Reflection of ultrasound energy is particularly significant at interfaces between tissues with markedly different:","options": [{"key": "A","text": "Acoustic impedance (a property related to tissue density and the speed of sound through that tissue), such as the interface between soft tissue and bone"},{"key": "B","text": "Color"},{"key": "C","text": "Temperature"},{"key": "D","text": "Electrical resistance"}],"correct": "A","explanation": "Significant ultrasound reflection occurs at interfaces where there is a substantial difference in acoustic impedance between adjacent tissues, classically illustrated at soft tissue-bone interfaces, which is relevant to understanding potential energy concentration (and periosteal pain risk) near bony surfaces."},{"id": 5464,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best explains why patients sometimes report a deep, aching 'periosteal pain' sensation during ultrasound treatment over an area with underlying bone close to the skin surface?","options": [{"key": "A","text": "Periosteal pain is unrelated to any ultrasound physical principles and occurs randomly"},{"key": "B","text": "This sensation indicates the ultrasound device is malfunctioning and must be replaced"},{"key": "C","text": "Significant ultrasound reflection occurs at the soft tissue-bone interface (due to the marked acoustic impedance difference), which can lead to localized energy concentration and heating near the periosteum, sometimes producing an aching sensation, particularly at higher intensities or with prolonged stationary application"},{"key": "D","text": "This sensation only occurs with pulsed mode ultrasound, never with continuous mode"}],"correct": "C","explanation": "The significant acoustic impedance mismatch at the soft tissue-bone interface causes substantial ultrasound reflection, which can concentrate energy and heating near the periosteum, sometimes producing a characteristic aching sensation, particularly if intensity is too high or the transducer is not adequately moved."},{"id": 5465,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following is generally recommended as an appropriate clinical response if a patient reports periosteal (deep aching) pain during ultrasound treatment?","options": [{"key": "A","text": "Reduce the treatment intensity and/or reposition/increase the speed of transducer movement, since this sensation may indicate excessive energy concentration near bone that warrants parameter adjustment"},{"key": "B","text": "Immediately increase intensity to overcome the discomfort"},{"key": "C","text": "Continue treatment at the same intensity, since this sensation is always harmless and expected"},{"key": "D","text": "Periosteal pain should always be ignored completely, regardless of severity"}],"correct": "A","explanation": "If periosteal pain is reported, reducing intensity and/or adjusting transducer technique (e.g., increasing movement speed, repositioning) is generally recommended to address the underlying excessive energy concentration near bone."},{"id": 5466,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Bone growth plates (epiphyseal plates) in children/adolescents are generally considered a relative contraindication or require caution with therapeutic ultrasound primarily due to:","options": [{"key": "A","text": "This precaution only applies to diagnostic, not therapeutic, ultrasound"},{"key": "B","text": "No established concern regarding growth plates and ultrasound"},{"key": "C","text": "Theoretical concerns regarding potential effects of ultrasound energy on the actively growing/developing tissue of the epiphyseal plate, leading to general caution or avoidance of direct application over open growth plates in skeletally immature patients"},{"key": "D","text": "Ultrasound is proven to always be completely safe over growth plates with strong supporting evidence"}],"correct": "C","explanation": "Given theoretical concerns regarding potential effects on actively developing epiphyseal tissue, caution or avoidance of direct therapeutic ultrasound application over open growth plates in skeletally immature patients is a standard clinical precaution."},{"id": 5467,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Application of therapeutic ultrasound directly over the pregnant uterus/abdomen is generally:","options": [{"key": "A","text": "Contraindicated, given the established/theoretical concerns regarding potential effects of ultrasound energy on the developing fetus in this specific application context (distinct from the different parameters/purpose of diagnostic obstetric ultrasound)"},{"key": "B","text": "Considered completely safe with no precautions needed"},{"key": "C","text": "Only a concern with 3 MHz frequency, not 1 MHz"},{"key": "D","text": "Recommended as a standard treatment approach during pregnancy"}],"correct": "A","explanation": "Therapeutic ultrasound (with its distinct parameters and purpose compared to diagnostic obstetric ultrasound) is contraindicated for direct application over the pregnant uterus/abdomen, given established precautions regarding potential fetal effects."},{"id": 5468,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Therapeutic ultrasound application directly over or near a known malignancy is generally considered a contraindication primarily due to:","options": [{"key": "A","text": "Ultrasound is definitively proven to always cure malignancy with strong supporting evidence"},{"key": "B","text": "The theoretical concern that increased local blood flow and cellular activity stimulated by ultrasound could potentially influence tumor growth or metastatic spread, consistent with the general precaution applied across many electrotherapy/physical modalities near malignancy"},{"key": "C","text": "This precaution only applies to pulsed mode ultrasound, never continuous mode"},{"key": "D","text": "No established concern; this is a baseless precaution"}],"correct": "B","explanation": "Similar to the general precaution applied across various physical modalities, ultrasound over known/suspected malignancy is generally avoided due to theoretical concerns about stimulating local blood flow/cellular activity that could influence tumor behavior."},{"id": 5469,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Therapeutic ultrasound is generally contraindicated for application directly over the eyes primarily due to:","options": [{"key": "A","text": "The risk of significant tissue damage to sensitive ocular structures (e.g., cavitation effects within the relatively fluid-filled eye, or excessive heating), given the eye's unique anatomical and physiological characteristics"},{"key": "B","text": "No established concern regarding ocular application"},{"key": "C","text": "Ultrasound is definitively proven to always improve vision when applied to the eyes"},{"key": "D","text": "This precaution applies only to 3 MHz frequency, not 1 MHz"}],"correct": "A","explanation": "Given the unique anatomical characteristics of the eye (including its fluid content, which could be susceptible to cavitation effects, and sensitivity to heating), direct application of therapeutic ultrasound over the eyes is contraindicated due to significant tissue damage risk."},{"id": 5470,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Therapeutic ultrasound is generally contraindicated for application directly over the heart/cardiac region and over a cardiac pacemaker primarily due to:","options": [{"key": "A","text": "Theoretical risk of adverse cardiac effects from direct cardiac application, and the risk of potential interference/damage to an implanted pacemaker device from ultrasound energy in that specific region"},{"key": "B","text": "This precaution only applies to continuous mode ultrasound, never pulsed mode"},{"key": "C","text": "No established concern regarding these applications"},{"key": "D","text": "Ultrasound has been proven to always improve cardiac function when applied directly over the heart"}],"correct": "A","explanation": "Direct application over the heart carries theoretical risk of adverse cardiac effects, and application near an implanted pacemaker carries a risk of device interference/damage, making both contraindicated applications for therapeutic ultrasound."},{"id": 5471,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Therapeutic ultrasound application directly over a known deep vein thrombosis (DVT) or area of thrombophlebitis is generally contraindicated primarily due to:","options": [{"key": "A","text": "The theoretical risk that increased local circulation/mechanical effects from ultrasound could dislodge a thrombus, risking embolism"},{"key": "B","text": "This precaution only applies to phonophoresis, not standard ultrasound"},{"key": "C","text": "Ultrasound is proven to always safely dissolve blood clots with strong supporting evidence"},{"key": "D","text": "No established concern regarding DVT and ultrasound"}],"correct": "A","explanation": "As with other modalities capable of influencing local circulation, ultrasound over an area of known/suspected DVT is contraindicated due to the theoretical risk of dislodging a thrombus and causing embolism."},{"id": 5472,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Therapeutic ultrasound is generally contraindicated for direct application over areas of active infection primarily due to:","options": [{"key": "A","text": "No established concern regarding infection and ultrasound application"},{"key": "B","text": "Ultrasound is proven to always eliminate infection completely with strong supporting evidence"},{"key": "C","text": "This precaution only applies to pulsed mode, never continuous mode ultrasound"},{"key": "D","text": "The theoretical concern that increased local circulation/cellular activity could promote the spread of infection to surrounding tissue"}],"correct": "D","explanation": "Similar to the rationale for other modalities capable of increasing local circulation, direct ultrasound application over areas of active infection is generally contraindicated due to theoretical concerns about promoting infection spread."},{"id": 5473,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "Therapeutic ultrasound is generally contraindicated for direct application over areas with cemented joint prostheses/metal implants using older cementing techniques primarily due to:","options": [{"key": "A","text": "This precaution has been completely disproven and is no longer considered relevant in any context"},{"key": "B","text": "Theoretical concerns regarding potential effects on the bone-cement or bone-implant interface, and/or altered heating patterns near metal, though contemporary understanding and specific implant materials/techniques can influence the degree of actual concern in individual cases"},{"key": "C","text": "No established concern regarding metal implants and ultrasound"},{"key": "D","text": "Ultrasound always causes immediate implant failure with strong supporting evidence in every case"}],"correct": "B","explanation": "Caution regarding therapeutic ultrasound over areas with certain joint replacement components (particularly relating to older cementing techniques and potential interface/heating effects) is a recognized clinical consideration, though understanding and specific recommendations can vary depending on implant type/materials and are subject to evolving evidence."},{"id": 5474,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Phonophoresis is defined as:","options": [{"key": "A","text": "The use of direct current to drive medication ions through the skin"},{"key": "B","text": "A form of electrical muscle stimulation"},{"key": "C","text": "The use of ultrasound energy to enhance the transdermal delivery of a topically applied medication (e.g., an anti-inflammatory gel) into underlying tissue"},{"key": "D","text": "A technique used exclusively for diagnostic imaging"}],"correct": "C","explanation": "Phonophoresis uses ultrasound energy, rather than electrical current, as the driving mechanism to enhance transdermal penetration of a topically applied therapeutic medication."},{"id": 5475,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best distinguishes phonophoresis from iontophoresis in terms of the underlying mechanism used to enhance drug delivery?","options": [{"key": "A","text": "Both techniques use an identical electrical current-based mechanism"},{"key": "B","text": "Phonophoresis uses ultrasound (mechanical/acoustic) energy as the driving force for enhanced drug delivery, whereas iontophoresis uses direct electrical current to drive charged medication ions"},{"key": "C","text": "Phonophoresis requires no medication whatsoever, unlike iontophoresis"},{"key": "D","text": "Phonophoresis and iontophoresis are simply two different names for the exact same technique"}],"correct": "B","explanation": "The key distinguishing feature is the driving mechanism: phonophoresis uses ultrasound (mechanical/acoustic) energy, while iontophoresis uses direct electrical current to drive charged medication ions through the skin."},{"id": 5476,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Corticosteroid preparations (e.g., hydrocortisone) are among the medications sometimes used in phonophoresis primarily for their proposed:","options": [{"key": "A","text": "Muscle-strengthening effect"},{"key": "B","text": "Antibiotic effect against local infection"},{"key": "C","text": "Direct analgesic nerve-blocking effect identical to a local anesthetic"},{"key": "D","text": "Local anti-inflammatory effect, similar to the rationale for using corticosteroids in iontophoresis"}],"correct": "D","explanation": "Corticosteroids are used in phonophoresis primarily for their local anti-inflammatory properties, aiming to enhance transdermal delivery to underlying inflamed tissue via the ultrasound mechanism."},{"id": 5477,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the general state of evidence regarding phonophoresis's ability to effectively deliver clinically significant medication concentrations to target tissue depths?","options": [{"key": "A","text": "There is no research evidence whatsoever regarding phonophoresis effectiveness"},{"key": "B","text": "Phonophoresis has been definitively proven completely ineffective for delivering any medication under any circumstances"},{"key": "C","text": "Research evidence regarding the depth and clinical significance of medication delivery achieved via phonophoresis remains mixed and is an area of ongoing debate, with questions raised about whether clinically meaningful concentrations reliably reach target tissue depths in all applications"},{"key": "D","text": "Research evidence conclusively and universally proves phonophoresis reliably delivers therapeutic medication concentrations to any desired tissue depth"}],"correct": "C","explanation": "Similar to some of the questions raised regarding iontophoresis, the evidence and clinical consensus regarding phonophoresis's ability to reliably deliver clinically significant medication concentrations to intended tissue depths remains mixed, representing an area of ongoing research interest and some debate."},{"id": 5478,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes an important safety consideration specific to phonophoresis, beyond standard ultrasound precautions?","options": [{"key": "A","text": "Screening for medication allergy/sensitivity to the specific topical agent being used is an important additional safety consideration, similar to the rationale applied for iontophoresis"},{"key": "B","text": "No additional safety considerations apply beyond standard ultrasound precautions"},{"key": "C","text": "Allergy screening is only relevant for oral medications, never for topically-applied phonophoresis agents"},{"key": "D","text": "Phonophoresis requires no medication screening since ultrasound alone eliminates any allergy risk"}],"correct": "A","explanation": "Since phonophoresis introduces a specific pharmacological agent, screening for known allergy/sensitivity to that particular medication is an important additional safety consideration beyond standard ultrasound precautions."},{"id": 5479,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "Which of the following best describes the general goal of low-intensity pulsed ultrasound (LIPUS) as used in some specific clinical applications, such as fracture healing stimulation?","options": [{"key": "A","text": "LIPUS aims to produce maximal tissue heating for pain relief"},{"key": "B","text": "LIPUS uses low-intensity, non-thermal parameters theorized to stimulate cellular processes relevant to bone healing (e.g., osteoblast activity) through non-thermal, mechanical bioeffects, and has some specific clinical/research support for certain fracture healing applications"},{"key": "C","text": "LIPUS is identical in all respects to standard continuous-mode therapeutic ultrasound used for soft tissue heating"},{"key": "D","text": "LIPUS has no established clinical application whatsoever"}],"correct": "B","explanation": "LIPUS specifically uses low-intensity, non-thermal parameters, with some research support for applications such as stimulating bone healing processes in certain fracture scenarios, distinct from the thermal-effect-focused parameters used in standard soft tissue ultrasound treatment."},{"id": 5480,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes why calibration and regular maintenance/testing of therapeutic ultrasound equipment is clinically important?","options": [{"key": "A","text": "Equipment calibration has no bearing on treatment safety or efficacy"},{"key": "B","text": "Poorly calibrated equipment could deliver inaccurate/inconsistent intensity or fail to meet stated BNR specifications, potentially compromising both treatment effectiveness and patient safety"},{"key": "C","text": "Ultrasound devices never require any calibration or maintenance once purchased"},{"key": "D","text": "Calibration is only relevant for diagnostic ultrasound equipment, never therapeutic devices"}],"correct": "B","explanation": "Regular calibration and maintenance help ensure that ultrasound equipment delivers accurate, consistent intensity and maintains appropriate beam characteristics (e.g., BNR), which is important for both treatment efficacy and patient safety."},{"id": 5481,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes the general treatment area size consideration relative to the transducer's effective radiating area (ERA) for typical ultrasound application technique?","options": [{"key": "A","text": "The treatment area should always be many times larger than the transducer's ERA, regardless of any technique guidance"},{"key": "B","text": "Treatment area size has no relevance to appropriate technique or achievable energy delivery"},{"key": "C","text": "The transducer should always be held stationary over an area many times larger than its ERA"},{"key": "D","text": "A commonly cited general guideline suggests the treatment area should typically not significantly exceed a certain multiple of the transducer's ERA (e.g., often cited as approximately 2-3 times the ERA) to help ensure adequate, consistent energy delivery across the entire intended treatment area within a reasonable treatment time"}],"correct": "D","explanation": "General clinical guidance suggests keeping the treatment area within a reasonable multiple (often cited around 2-3 times) of the transducer's effective radiating area, helping ensure the entire intended area receives adequate, relatively consistent energy delivery within a practical treatment timeframe using proper moving technique."},{"id": 5482,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes typical treatment duration considerations for a standard therapeutic ultrasound session over a given treatment area?","options": [{"key": "A","text": "Treatment duration is always fixed at exactly 60 minutes regardless of area size, intensity, or clinical goal"},{"key": "B","text": "Treatment duration has no bearing on the therapeutic effect or safety of ultrasound treatment"},{"key": "C","text": "Typical treatment durations are commonly cited in ranges of approximately 3-10 minutes per treatment area (with the specific duration influenced by factors such as treatment area size, ERA, and duty cycle/intensity), though specific protocols vary"},{"key": "D","text": "Treatment sessions must always last less than 10 seconds to be considered safe"}],"correct": "C","explanation": "While specific protocols vary based on clinical goals and parameters, typical therapeutic ultrasound treatment durations for a given area are commonly cited in general ranges of approximately 3-10 minutes, influenced by factors such as treatment area size relative to the transducer's ERA and the chosen duty cycle/intensity."},{"id": 5483,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "Which of the following best explains why ultrasound intensity may need to be reduced when using pulsed mode with a very low duty cycle compared to continuous mode, if a similar level of non-thermal bioeffect (without significant heating) is desired?","options": [{"key": "A","text": "Intensity should always remain completely unchanged regardless of duty cycle selection"},{"key": "B","text": "Pulsed mode ultrasound is always incapable of producing any thermal effect regardless of intensity or duty cycle settings"},{"key": "C","text": "Since a lower duty cycle already substantially reduces average energy delivery (allowing heat dissipation during off periods), a very low duty cycle combined with high intensity could still theoretically approach thermal-effect-producing energy levels during the 'on' periods, so some clinicians may consider intensity adjustments based on the specific balance of duty cycle and desired thermal versus non-thermal effect"},{"key": "D","text": "Duty cycle and intensity are completely independent parameters with no interacting effect on tissue heating"}],"correct": "C","explanation": "Since duty cycle and intensity interact to determine overall average energy delivery and heating potential, thoughtful consideration of how these parameters combine is important when aiming for predominantly non-thermal effects, recognizing that sufficiently high intensity even at low duty cycles could still contribute to some degree of thermal effect during the 'on' periods."},{"id": 5484,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical role of therapeutic ultrasound within a comprehensive physiotherapy treatment plan, considering the evolving evidence base for this modality?","options": [{"key": "A","text": "Therapeutic ultrasound is generally considered an adjunctive modality, and given ongoing questions and mixed evidence regarding its clinical efficacy for various specific applications, its use should be based on sound clinical reasoning, integrated within a broader evidence-based treatment plan that includes exercise and other interventions with generally stronger supporting evidence, rather than relied upon as a primary treatment strategy"},{"key": "B","text": "Therapeutic ultrasound should always be used as the primary, most important intervention for every musculoskeletal condition, given overwhelming and conclusive supporting evidence"},{"key": "C","text": "Therapeutic ultrasound has been definitively proven completely ineffective for all clinical applications with no exceptions"},{"key": "D","text": "Therapeutic ultrasound should never be combined with any other physiotherapy intervention under any circumstances"}],"correct": "A","explanation": "Given the mixed and evolving evidence base for therapeutic ultrasound's clinical efficacy across various applications, it is generally best considered an adjunctive modality integrated thoughtfully within a broader, evidence-based treatment plan, rather than relied upon as a primary treatment strategy, with active interventions like exercise generally carrying stronger evidence support for many musculoskeletal conditions."},{"id": 5485,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes the general purpose of pretreatment skin/area assessment before applying therapeutic ultrasound?","options": [{"key": "A","text": "Only the ultrasound device settings matter, with no relevance to the patient's clinical presentation"},{"key": "B","text": "Assessment is only relevant for phonophoresis, never for standard ultrasound"},{"key": "C","text": "Pretreatment assessment helps identify contraindications (e.g., malignancy, DVT, pacemaker, pregnancy over the treatment region, impaired sensation) and confirms the treatment area is appropriate before proceeding with ultrasound application"},{"key": "D","text": "Skin assessment is unnecessary since ultrasound carries no risk of adverse skin reaction"}],"correct": "C","explanation": "Thorough pretreatment assessment helps identify relevant contraindications and confirms the appropriateness of the treatment area, supporting safe and effective clinical decision-making before proceeding with ultrasound application."},{"id": 5486,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes why adequate sensation in the treatment area is generally required before applying therapeutic ultrasound, particularly with thermal (continuous mode, higher intensity) parameters?","options": [{"key": "A","text": "This consideration only applies to electrical stimulation modalities, never to ultrasound"},{"key": "B","text": "Sensation has no bearing on ultrasound treatment safety"},{"key": "C","text": "Ultrasound is always completely safe regardless of the patient's sensory status"},{"key": "D","text": "Adequate sensation allows the patient to reliably report excessive heating or discomfort, which is an important safety mechanism given the potential for tissue damage from excessive thermal or mechanical energy if not appropriately monitored"}],"correct": "D","explanation": "Reliable patient feedback regarding sensation (particularly excessive heat or discomfort) is an important safety mechanism during thermal ultrasound application, making adequate sensory function in the treatment area an important pretreatment consideration."},{"id": 5487,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes the appropriate transducer angle relative to the skin surface for standard direct-contact ultrasound application?","options": [{"key": "A","text": "The transducer should generally be held perpendicular (approximately 90 degrees) to the skin surface, which helps maximize efficient transmission of ultrasound energy into the underlying tissue and minimizes reflection losses"},{"key": "B","text": "The transducer should never maintain contact with the skin at any angle"},{"key": "C","text": "Transducer angle has no bearing on the efficiency of ultrasound energy transmission"},{"key": "D","text": "The transducer should always be held at a sharp, oblique angle to the skin"}],"correct": "A","explanation": "Maintaining a perpendicular transducer angle relative to the skin surface generally optimizes efficient transmission of ultrasound energy into the tissue, minimizing energy loss from excessive reflection that can occur at more oblique angles."},{"id": 5488,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes the general clinical rationale for combining therapeutic ultrasound with subsequent stretching exercises when targeting increased extensibility of a tight, collagen-rich structure (e.g., joint capsule)?","options": [{"key": "A","text": "Ultrasound always decreases tissue extensibility, making subsequent stretching counterproductive"},{"key": "B","text": "Applying thermal ultrasound is theorized to increase the extensibility of collagenous tissue, and performing stretching promptly after this heating (while tissue temperature remains elevated) is thought to potentially enhance the effectiveness of the stretch, similar to the rationale for combining other heating modalities with stretching"},{"key": "C","text": "There is no established rationale for combining these interventions"},{"key": "D","text": "Ultrasound and stretching should never be used within the same treatment session"}],"correct": "B","explanation": "Consistent with the general principle of combining heat with stretching, applying thermal ultrasound (theorized to increase collagen extensibility) followed promptly by stretching while tissue remains warm is a commonly cited clinical rationale, similar to approaches used with other heating modalities."},{"id": 5489,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding treatment area selection when a patient has an area of significantly reduced local blood flow (e.g., peripheral vascular disease) in the region being considered for thermal ultrasound treatment?","options": [{"key": "A","text": "Thermal ultrasound is always completely safe regardless of the patient's local circulatory status"},{"key": "B","text": "This consideration is only relevant for cryotherapy, never for thermal modalities like ultrasound"},{"key": "C","text": "Reduced blood flow has no relevance to thermal ultrasound treatment planning"},{"key": "D","text": "Compromised local circulation may impair the tissue's ability to dissipate heat effectively, potentially increasing the risk of excessive, localized temperature rise and tissue damage, warranting caution or modified parameters in this population"}],"correct": "D","explanation": "Since adequate local blood flow helps dissipate heat generated during thermal ultrasound treatment, significantly compromised circulation in the treatment area raises the theoretical risk of excessive localized temperature rise, warranting careful clinical judgment and possibly modified parameters."},{"id": 5490,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes the general recommendation regarding ultrasound treatment over recently fractured bone that has not yet achieved sufficient union/stability, outside of specific LIPUS bone-healing protocols?","options": [{"key": "A","text": "Ultrasound is always completely contraindicated in any patient with a history of fracture, regardless of healing stage"},{"key": "B","text": "This consideration has no established clinical basis"},{"key": "C","text": "Standard soft-tissue-focused ultrasound application directly over an unstable, unhealed fracture site is generally approached with caution or avoided (distinct from the specific, different parameters used in dedicated LIPUS bone-healing protocols), given theoretical concerns and the importance of not interfering with normal fracture healing processes"},{"key": "D","text": "Standard thermal/soft tissue ultrasound parameters should always be applied directly over an unstable, recent fracture site with no caution needed"}],"correct": "C","explanation": "General caution or avoidance of standard soft-tissue ultrasound parameters directly over an unstable, unhealed fracture site is a recognized clinical consideration, distinct from the specific, different application of dedicated low-intensity pulsed ultrasound protocols specifically designed and researched for certain fracture-healing applications."},{"id": 5491,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "Which of the following best describes why therapeutic ultrasound is generally avoided or approached with significant caution over an area with a total joint replacement using a plastic (non-cemented, non-metal) component in certain contexts?","options": [{"key": "A","text": "This consideration is unique to electrical stimulation and never applies to ultrasound"},{"key": "B","text": "Similar to concerns regarding cemented/metal components, some caution regarding potential effects on component interfaces or altered energy absorption near prosthetic materials is a recognized consideration, though specific recommendations can vary depending on component type/materials and evolving evidence"},{"key": "C","text": "Ultrasound is always completely safe over any type of joint replacement without exception"},{"key": "D","text": "There is never any consideration needed regarding joint replacement components and ultrasound"}],"correct": "B","explanation": "General caution regarding potential effects on prosthetic component interfaces or altered ultrasound energy absorption/behavior near various joint replacement materials is a recognized clinical consideration, with specific guidance potentially varying based on component materials and ongoing evidence in this area."},{"id": 5492,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes appropriate patient education regarding sensations to expect during a typical thermal ultrasound treatment?","options": [{"key": "A","text": "Patients should be informed that a mild, gradually building warmth is generally expected with thermal parameters, and instructed to immediately report any sharp pain, excessive/rapidly increasing heat, or aching sensation, which may indicate a technique or parameter issue requiring adjustment"},{"key": "B","text": "Patients should expect significant pain as a normal, unavoidable part of effective ultrasound treatment"},{"key": "C","text": "Patients should expect no sensation whatsoever during treatment"},{"key": "D","text": "Any reported sensation during treatment should be disregarded entirely"}],"correct": "A","explanation": "Appropriate patient education for thermal ultrasound includes setting expectations for mild, gradual warmth while emphasizing the importance of promptly reporting any sharp pain or excessive/rapidly building heat, which could indicate a need for technique or parameter adjustment."},{"id": 5493,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best summarizes an appropriate approach to selecting ultrasound parameters (frequency, mode, intensity, duty cycle) for a specific patient presentation?","options": [{"key": "A","text": "Parameter selection is entirely arbitrary and has no bearing on treatment outcomes"},{"key": "B","text": "A single, universally standardized parameter set should always be used for every patient and condition, regardless of treatment depth or clinical goal"},{"key": "C","text": "Only intensity needs to be considered; frequency and duty cycle are irrelevant to clinical outcomes"},{"key": "D","text": "Parameter selection should be individualized based on factors such as the target tissue depth (frequency selection), desired thermal versus non-thermal effect (mode/duty cycle selection), and patient tolerance/presentation (intensity selection), reflecting thoughtful, evidence-informed clinical reasoning"}],"correct": "D","explanation": "Thoughtful, individualized parameter selection—considering target tissue depth, desired thermal versus non-thermal effect, and patient-specific factors—reflects sound clinical reasoning in the application of therapeutic ultrasound."},{"id": 5494,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best describes an important documentation practice following therapeutic ultrasound treatment?","options": [{"key": "A","text": "Only the total treatment time needs to be recorded, with no other parameters relevant"},{"key": "B","text": "Ultrasound treatment documentation should never include information about patient-reported sensation"},{"key": "C","text": "Documentation is unnecessary for ultrasound treatment since it carries no risk of adverse effects"},{"key": "D","text": "Documentation should include the specific parameters used (frequency, mode, duty cycle, intensity, treatment duration, transducer size, treatment area), patient tolerance/response, and any relevant findings, supporting continuity of care and appropriate treatment progression"}],"correct": "D","explanation": "Comprehensive documentation of ultrasound treatment parameters, patient response, and relevant findings supports continuity of care, appropriate treatment progression, and effective communication among the healthcare team."},{"id": 5495,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "Short wave diathermy (SWD) uses electromagnetic energy in which frequency range?","options": [{"key": "A","text": "Visible light frequency range"},{"key": "B","text": "High-frequency radio waves, most commonly at an internationally allocated frequency of 27.12 MHz"},{"key": "C","text": "Frequencies identical to therapeutic ultrasound (1-3 MHz)"},{"key": "D","text": "Extremely low frequency (below 100 Hz)"}],"correct": "B","explanation": "SWD utilizes high-frequency electromagnetic (radio wave) energy, most commonly standardized internationally at 27.12 MHz for medical therapeutic use."},{"id": 5496,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "The primary therapeutic effect of short wave diathermy is:","options": [{"key": "A","text": "Deep tissue heating, produced through the conversion of high-frequency electromagnetic energy into heat within the tissue"},{"key": "B","text": "Non-thermal mechanical stimulation only"},{"key": "C","text": "Photochemical effects similar to laser therapy"},{"key": "D","text": "Direct electrical stimulation of motor nerves for muscle contraction"}],"correct": "A","explanation": "SWD is primarily a deep-heating modality, converting high-frequency electromagnetic energy into thermal energy within the tissue through which it passes."},{"id": 5497,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Compared to superficial heating modalities (e.g., hot packs, infrared), short wave diathermy is generally able to:","options": [{"key": "A","text": "Produce heating at a greater tissue depth, since electromagnetic energy can penetrate more deeply than the conductive/radiant heat transfer mechanisms of superficial modalities"},{"key": "B","text": "Produce identical heating depth to superficial modalities with no advantage"},{"key": "C","text": "Only be used for cooling, never for heating"},{"key": "D","text": "Produce heating only at the very surface of the skin, with no deeper penetration"}],"correct": "A","explanation": "SWD is classified as a deep-heating modality, capable of producing therapeutic temperature increases at greater tissue depths compared to superficial heating modalities that rely on conduction or radiant heat transfer limited largely to surface tissue."},{"id": 5498,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "The two primary methods of applying short wave diathermy are:","options": [{"key": "A","text": "Only a single universal application method exists for SWD"},{"key": "B","text": "Continuous mode and pulsed mode exclusively, with no other distinguishing application methods"},{"key": "C","text": "Direct contact application and immersion technique only"},{"key": "D","text": "The capacitive (condenser field) method and the inductive (coil field) method"}],"correct": "D","explanation": "SWD can be applied using either the capacitive method (patient tissue acts as part of a capacitor/condenser field between two electrode plates) or the inductive method (using a coil to induce eddy currents within the tissue)."},{"id": 5499,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "In the capacitive (condenser field) method of SWD application, the patient's tissue functions as:","options": [{"key": "A","text": "The coil generating the magnetic field"},{"key": "B","text": "The power source for the treatment device"},{"key": "C","text": "A dielectric material positioned between two electrode plates, effectively forming part of a capacitor within the electrical circuit"},{"key": "D","text": "A completely inert material with no role in the circuit"}],"correct": "C","explanation": "In capacitive application, the patient's tissue is positioned between two electrode plates and functions as the dielectric material of a capacitor, with the alternating electric field passing through the tissue generating heat."},{"id": 5500,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "In the capacitive method of SWD, tissues with higher electrical resistance (e.g., fat) relative to tissues with lower resistance (e.g., muscle, due to higher water/electrolyte content) tend to:","options": [{"key": "A","text": "Show no difference in heating regardless of resistance"},{"key": "B","text": "Never generate any heat regardless of resistance"},{"key": "C","text": "Heat MORE than the lower-resistance tissue, since capacitive heating follows principles similar to resistive (I²R-type) heating, where higher-resistance tissue generates more heat for a given current"},{"key": "D","text": "Heat less than the lower-resistance tissue"}],"correct": "C","explanation": "Since capacitive SWD heating follows principles related to resistive heating, tissues with relatively higher electrical resistance (e.g., subcutaneous fat) tend to absorb/generate proportionally more heat compared to lower-resistance tissues like muscle, an important clinical consideration for the capacitive technique."},{"id": 5501,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Hard","question": "Which of the following best describes a clinical implication of the capacitive method's tendency to preferentially heat higher-resistance (e.g., fatty) tissue?","options": [{"key": "A","text": "Since subcutaneous fat can absorb proportionally more heat with the capacitive method, patients with a thicker fat layer may experience more superficial heating and increased risk of fat layer discomfort/burns relative to the depth of heating achieved in deeper muscle tissue, an important consideration for technique selection and monitoring"},{"key": "B","text": "This tendency has no clinical relevance to treatment planning"},{"key": "C","text": "The capacitive method always produces identical heating in fat and muscle tissue regardless of individual patient anatomy"},{"key": "D","text": "This consideration only applies to the inductive method, never the capacitive method"}],"correct": "A","explanation": "Because the capacitive method tends to preferentially heat higher-resistance fatty tissue, patients with a thicker subcutaneous fat layer are at increased risk of disproportionate superficial heating/discomfort relative to the depth of heating achieved in deeper muscle, an important consideration when selecting technique and monitoring treatment."},{"id": 5502,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "In the inductive (coil field) method of SWD, heat is generated within the tissue primarily via:","options": [{"key": "A","text": "Electromagnetic induction, whereby the alternating magnetic field produced by the coil induces circulating (eddy) currents within the conductive tissue, generating heat"},{"key": "B","text": "A completely different, non-electromagnetic thermal mechanism"},{"key": "C","text": "Direct current flow through electrode plates"},{"key": "D","text": "Direct contact conduction from a heated coil surface"}],"correct": "A","explanation": "The inductive method uses a coil to generate an alternating magnetic field, which induces eddy currents within the tissue via electromagnetic induction; these induced currents generate heat as they encounter tissue resistance."},{"id": 5503,"subject": "Electrotherapy","topic": "Basic Electricity Concepts","difficulty": "Hard","question": "In the inductive method of SWD, tissues with higher electrical conductivity (lower resistance, e.g., muscle, due to higher water/electrolyte content) tend to:","options": [{"key": "A","text": "Heat MORE than lower-conductivity tissue, since higher conductivity allows greater induced eddy current flow, and heat generation is related to current flow through the tissue's resistance in this induction-based mechanism"},{"key": "B","text": "Show no difference in heating regardless of tissue conductivity"},{"key": "C","text": "Heat less than lower-conductivity tissue (e.g., fat)"},{"key": "D","text": "Never generate any heat regardless of conductivity"}],"correct": "A","explanation": "Since the inductive method's heating depends on induced eddy current flow (which is greater in more conductive tissue), tissues with higher conductivity (e.g., muscle) tend to generate proportionally more heat compared to less conductive fatty tissue, differing from the pattern seen with the capacitive method."},{"id": 5504,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best summarizes the general difference in tissue heating pattern between the capacitive and inductive methods of SWD application?","options": [{"key": "A","text": "The capacitive method tends to preferentially heat higher-resistance tissue (e.g., fat), while the inductive method tends to preferentially heat lower-resistance, more conductive tissue (e.g., muscle)"},{"key": "B","text": "Both methods produce identical heating patterns with no meaningful difference"},{"key": "C","text": "Neither method produces any significant tissue heating"},{"key": "D","text": "The capacitive method always heats muscle preferentially, and the inductive method always heats fat preferentially (the opposite of the correct relationship)"}],"correct": "B","explanation": "This intentionally frames option A as correct: capacitive preferentially heats higher-resistance fatty tissue, while inductive preferentially heats lower-resistance, more conductive tissue like muscle, reflecting their differing underlying physical mechanisms."},{"id": 5505,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Hard","question": "The inductive method of SWD may therefore be generally preferred over the capacitive method when the primary treatment goal is to heat:","options": [{"key": "A","text": "Superficial subcutaneous fat specifically"},{"key": "B","text": "Bone tissue specifically, in preference to any surrounding soft tissue"},{"key": "C","text": "Only the skin surface, with no deeper heating desired"},{"key": "D","text": "Deeper, more conductive muscle tissue, given the inductive method's tendency to preferentially heat lower-resistance, higher-conductivity tissue such as muscle"}],"correct": "D","explanation": "Since the inductive method tends to preferentially heat more conductive tissue like muscle, it may be favored when the primary clinical goal is heating deeper muscular tissue rather than more superficial, higher-resistance fatty tissue."},{"id": 5506,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Hard","question": "Which of the following best describes the physical principle underlying pulsed short wave diathermy (PSWD), sometimes marketed with claims of predominantly non-thermal effects?","options": [{"key": "A","text": "PSWD uses an entirely different electromagnetic frequency range than continuous SWD"},{"key": "B","text": "PSWD has no established underlying physical principle"},{"key": "C","text": "PSWD delivers the same high-frequency (e.g., 27.12 MHz) energy in interrupted pulses (with periods of no energy delivery between pulses), which reduces the average energy delivered over time (similar in principle to pulsed ultrasound), theoretically allowing application at intensities producing minimal or no significant thermal effect while still potentially producing other proposed non-thermal bioeffects"},{"key": "D","text": "PSWD always produces greater heating than continuous SWD at any given average power setting"}],"correct": "C","explanation": "Similar in principle to pulsed ultrasound, PSWD interrupts the delivery of the same high-frequency carrier energy, reducing average power delivery and theoretically allowing predominantly non-thermal application, though the specific claimed non-thermal bioeffects and their clinical significance remain subjects of ongoing research and discussion."},{"id": 5507,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following is a proposed thermal effect of short wave diathermy, similar to other deep-heating modalities?","options": [{"key": "A","text": "Decreased tissue temperature"},{"key": "B","text": "Increased local blood flow, increased tissue extensibility (particularly of collagenous structures), mild analgesic effect, and increased local metabolic activity"},{"key": "C","text": "Complete elimination of all inflammation with no other effects"},{"key": "D","text": "Decreased local blood flow"}],"correct": "B","explanation": "SWD's thermal effects are proposed to include increased local blood flow, enhanced tissue extensibility, a mild analgesic effect, and increased local metabolic activity, consistent with general principles of therapeutic deep heating."},{"id": 5508,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is a general contraindication for short wave diathermy related to the presence of metal in or near the treatment area?","options": [{"key": "A","text": "Metal always blocks all electromagnetic energy completely, eliminating any treatment effect or risk"},{"key": "B","text": "Metal has no relationship to SWD safety considerations"},{"key": "C","text": "Metal implants improve SWD treatment safety and effectiveness with no additional risk"},{"key": "D","text": "Metal implants/objects (e.g., jewelry, orthopedic hardware, intrauterine devices) in or near the treatment field are generally contraindicated, since metal can concentrate the electromagnetic field, leading to excessive localized heating and risk of tissue burns"}],"correct": "D","explanation": "Since metal can concentrate/distort the electromagnetic field produced by SWD, leading to excessive localized heating, the presence of metal implants or objects in or near the treatment field is a significant, widely recognized contraindication."},{"id": 5509,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best explains the physical basis for the concern regarding metal implants and short wave diathermy?","options": [{"key": "A","text": "Metal is highly conductive, and the alternating electromagnetic field of SWD can induce concentrated eddy currents within metal objects, generating significant, potentially dangerous localized heat around the metal, particularly relevant for the inductive method"},{"key": "B","text": "Metal has no interaction with electromagnetic fields of any kind"},{"key": "C","text": "This concern applies exclusively to the capacitive method, never the inductive method"},{"key": "D","text": "Metal always completely absorbs 100% of the SWD energy with no risk to surrounding tissue"}],"correct": "A","explanation": "Metal's high conductivity makes it particularly susceptible to induced eddy currents from SWD's alternating electromagnetic field, which can generate significant, concentrated localized heating around the metal object—a risk relevant to both application methods but often specifically emphasized regarding the inductive technique's magnetic field mechanism."},{"id": 5510,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Cardiac pacemakers and other implanted electronic devices represent a significant contraindication for SWD primarily due to:","options": [{"key": "A","text": "No established risk; this is a myth without clinical basis"},{"key": "B","text": "The risk of electromagnetic interference with the device's electronic circuitry, potentially causing device malfunction, in addition to the general metal-related heating concerns"},{"key": "C","text": "SWD is proven to always improve pacemaker function with strong supporting evidence"},{"key": "D","text": "This contraindication only applies to the capacitive method, never the inductive method"}],"correct": "B","explanation": "Beyond the general concern regarding metal and induced heating, SWD's electromagnetic field poses a risk of interfering with the electronic circuitry of implanted devices like pacemakers, potentially causing malfunction, making this a significant contraindication regardless of application method."},{"id": 5511,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Short wave diathermy is generally contraindicated during pregnancy for application over the abdomen/pelvis/lumbar region primarily due to:","options": [{"key": "A","text": "No established concern regarding SWD and pregnancy"},{"key": "B","text": "SWD is proven to always be completely safe during pregnancy with strong supporting evidence"},{"key": "C","text": "The established risk of significant tissue heating from SWD potentially harming fetal development, making this a well-recognized and important contraindication during pregnancy for this treatment region"},{"key": "D","text": "This contraindication only applies to pulsed SWD, never continuous SWD"}],"correct": "C","explanation": "Given the established significant tissue-heating capacity of SWD and the associated risk to fetal development, application over the abdomen/pelvis/lumbar region during pregnancy is a well-recognized, important contraindication."},{"id": 5512,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Short wave diathermy is generally contraindicated for application over or near malignancy primarily due to:","options": [{"key": "A","text": "No established concern; this is a baseless precaution"},{"key": "B","text": "SWD is proven to always cure malignancy with strong supporting evidence"},{"key": "C","text": "The theoretical concern that increased local blood flow/cellular activity from significant tissue heating could potentially influence tumor growth or metastatic spread"},{"key": "D","text": "This contraindication only applies to the inductive method, never the capacitive method"}],"correct": "C","explanation": "Consistent with the general precaution applied across many heating and electrotherapy modalities, SWD over known/suspected malignancy is contraindicated due to theoretical concerns about stimulating local blood flow/cellular activity that could influence tumor behavior."},{"id": 5513,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Short wave diathermy is generally contraindicated for application directly over areas of active bleeding/hemorrhage or acute inflammation primarily due to:","options": [{"key": "A","text": "SWD is proven to always safely stop bleeding with strong supporting evidence"},{"key": "B","text": "This contraindication only applies to superficial heating modalities, never to deep heating like SWD"},{"key": "C","text": "No established concern regarding these conditions and SWD"},{"key": "D","text": "The risk that significant local heating and increased blood flow could exacerbate bleeding or acute inflammatory processes"}],"correct": "D","explanation": "Since SWD produces significant local heating and increased blood flow, application over areas of active bleeding or acute inflammation is contraindicated due to the risk of exacerbating these conditions."},{"id": 5514,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Short wave diathermy is generally contraindicated for application over areas of impaired sensation primarily due to:","options": [{"key": "A","text": "The patient's reduced ability to accurately perceive and report excessive/uncomfortable heating increases the risk that a significant burn could occur without adequate warning to the clinician"},{"key": "B","text": "This consideration is only relevant to superficial heating modalities, never to deep heating like SWD"},{"key": "C","text": "SWD is always completely safe regardless of the patient's sensory status in the treatment area"},{"key": "D","text": "Impaired sensation has no bearing on SWD safety"}],"correct": "A","explanation": "Since patient-reported sensation of appropriate warmth (and prompt reporting of excessive heat) is a critical safety mechanism during SWD treatment, application over areas with significantly impaired sensation is contraindicated due to increased burn risk."},{"id": 5515,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Short wave diathermy is generally contraindicated for application over areas of significantly impaired local circulation primarily due to:","options": [{"key": "A","text": "SWD is always completely safe regardless of the patient's local circulatory status"},{"key": "B","text": "Impaired circulation has no bearing on SWD treatment safety"},{"key": "C","text": "This consideration is only relevant to superficial heating modalities, never applicable to SWD"},{"key": "D","text": "Compromised circulation impairs the tissue's ability to effectively dissipate the heat generated by SWD, increasing the risk of excessive, potentially damaging local temperature rise"}],"correct": "D","explanation": "Since adequate local circulation is important for dissipating heat generated during SWD treatment, significantly compromised circulation increases the risk of excessive, potentially damaging localized temperature rise, making this a recognized contraindication."},{"id": 5516,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Short wave diathermy is generally contraindicated over areas with significant edema/fluid accumulation primarily due to:","options": [{"key": "A","text": "No established concern regarding edema and SWD application"},{"key": "B","text": "Fluid can concentrate/preferentially absorb electromagnetic energy, potentially leading to excessive, uneven localized heating in edematous tissue"},{"key": "C","text": "This consideration only applies to inductive SWD, never capacitive SWD"},{"key": "D","text": "SWD always eliminates edema completely with no associated risk"}],"correct": "B","explanation": "Since tissue fluid can preferentially absorb and concentrate electromagnetic energy, application over areas of significant edema carries increased risk of excessive, uneven localized heating, making this a recognized precaution/contraindication."},{"id": 5517,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best explains why patients are generally instructed to remove all metal jewelry, hearing aids, and similar metal objects, as well as clothing containing metal fibers, before SWD treatment?","options": [{"key": "A","text": "Metal objects are always completely unaffected by electromagnetic fields with no interaction whatsoever"},{"key": "B","text": "Retained metal objects in or near the treatment field can concentrate the electromagnetic field, leading to significant, potentially dangerous localized heating and burn risk"},{"key": "C","text": "This instruction only applies when using the capacitive method, never the inductive method"},{"key": "D","text": "This instruction has no genuine safety rationale and is purely a formality"}],"correct": "B","explanation": "Since metal objects can concentrate SWD's electromagnetic field and generate significant localized heating, thorough removal of all metal items from the treatment area (and ideally from anywhere within the general treatment field) is an essential safety precaution."},{"id": 5518,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why patients undergoing SWD treatment are generally positioned on non-metal furniture/equipment (e.g., wooden treatment tables) rather than standard metal-framed furniture?","options": [{"key": "A","text": "Metal furniture always improves SWD treatment effectiveness with no associated risk"},{"key": "B","text": "Metal furniture/equipment in proximity to the SWD field could similarly concentrate the electromagnetic field and generate unwanted localized heating, similar to the concern with metal on the patient's body"},{"key": "C","text": "Furniture material has no relevance to SWD treatment safety"},{"key": "D","text": "This consideration only applies to very old SWD equipment, with no relevance to modern devices"}],"correct": "B","explanation": "Similar to the concern regarding metal objects on the patient, nearby metal furniture or equipment within the SWD electromagnetic field could concentrate the field and generate unwanted, potentially hazardous localized heating, informing the general practice of using non-metal treatment furniture."},{"id": 5519,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes an important consideration regarding the treatment room environment when using short wave diathermy?","options": [{"key": "A","text": "SWD has no capacity to interact with or affect any nearby electronic equipment"},{"key": "B","text": "This consideration is only relevant for extremely old SWD devices, never modern equipment"},{"key": "C","text": "The treatment room environment has no relevance to SWD application"},{"key": "D","text": "SWD's electromagnetic field can potentially interfere with other nearby electronic equipment, and appropriate spacing/shielding considerations may be relevant in a clinical environment with multiple electronic devices in use"}],"correct": "D","explanation": "Given SWD's significant electromagnetic field output, consideration of potential interference with other nearby electronic equipment in the treatment environment is a relevant practical/safety consideration in clinical settings."},{"id": 5520,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general treatment duration considerations for a typical continuous SWD session aimed at producing therapeutic tissue heating?","options": [{"key": "A","text": "Typical treatment durations are commonly cited in ranges of approximately 15-30 minutes, though specific duration may be adjusted based on the clinical goal, intensity/dose selected, and patient tolerance"},{"key": "B","text": "SWD sessions must always last several hours to achieve any therapeutic effect"},{"key": "C","text": "Treatment duration is always fixed at exactly 5 seconds regardless of clinical goal"},{"key": "D","text": "Treatment duration has no bearing on the therapeutic effect or safety of SWD treatment"}],"correct": "A","explanation": "While specific protocols vary, typical continuous SWD treatment sessions are commonly cited in general ranges of approximately 15-30 minutes, with adjustments made based on the specific clinical goal, dosage/intensity, and patient tolerance."},{"id": 5521,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes the general dosage classification system sometimes used to describe the intensity of thermal SWD treatment, based on the patient's subjective sensation of warmth?","options": [{"key": "A","text": "A commonly referenced dosage classification describes intensity levels ranging from a mild, barely perceptible warmth (lower dose, often used for acute conditions) up to a strong, vigorous heat sensation just short of discomfort (higher dose, often reserved for chronic conditions), based on patient-reported subjective thermal sensation"},{"key": "B","text": "Only a single, fixed intensity level exists for all SWD treatments regardless of the clinical condition being addressed"},{"key": "C","text": "Dosage classification has no relevance to SWD clinical application or patient safety"},{"key": "D","text": "Dosage is always described using a purely numerical wattage value with no subjective component considered"}],"correct": "A","explanation": "A commonly referenced subjective dosage classification system for thermal SWD ranges from mild warmth (often used cautiously for more acute presentations) to a vigorous, strong heat sensation (often considered appropriate for more chronic presentations), guiding intensity selection based on patient-reported thermal sensation and clinical presentation."},{"id": 5522,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes why lower-intensity SWD dosing (mild warmth) is generally recommended for more acute conditions/presentations, while higher-intensity dosing (vigorous heat) may be considered for more chronic presentations?","options": [{"key": "A","text": "Higher intensity is always recommended regardless of whether the condition is acute or chronic"},{"key": "B","text": "Only chronic conditions can ever be safely treated with SWD, with acute conditions being an absolute contraindication"},{"key": "C","text": "Dosage selection has no relationship to the acuity of the clinical condition being treated"},{"key": "D","text": "Lower intensity is generally favored for acute conditions to avoid excessive stimulation of an already irritable/inflamed area, while higher intensity may be better tolerated and potentially more beneficial for chronic conditions where more vigorous heating effects (e.g., greater extensibility gains, stronger circulatory effects) may be desired"}],"correct": "D","explanation": "Matching dosage intensity to the acuity of the presenting condition (lower intensity for acute, more irritable presentations; higher intensity potentially appropriate for chronic presentations) reflects a general principle applied across various heating modalities, aiming to avoid excessive stimulation of acute conditions while allowing more vigorous, potentially more impactful heating for appropriate chronic presentations."},{"id": 5523,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate skin inspection practice before and after short wave diathermy treatment?","options": [{"key": "A","text": "Only the SWD device settings need to be checked, never the patient's skin"},{"key": "B","text": "The treatment area should be inspected before treatment for contraindications (e.g., metal, impaired sensation, significant moisture) and after treatment for any excessive redness or signs of burn, which should be documented and considered for subsequent treatment planning"},{"key": "C","text": "Skin inspection is unnecessary for SWD since it poses no risk of skin reaction/burn"},{"key": "D","text": "Skin inspection is only relevant for superficial heating modalities, never for SWD"}],"correct": "B","explanation": "Pre- and post-treatment skin inspection is an important safety practice for SWD, given its significant heating capacity, helping identify contraindications before treatment and any excessive skin reaction afterward, both of which should inform ongoing treatment planning."},{"id": 5524,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding patient clothing/toweling during SWD treatment?","options": [{"key": "A","text": "Patients should always be treated with wet clothing directly against the skin for optimal SWD effectiveness"},{"key": "B","text": "Clothing/toweling has no relevance to SWD treatment technique or safety"},{"key": "C","text": "Clothing considerations are only relevant for capacitive SWD, never for inductive SWD"},{"key": "D","text": "Adequate dry toweling is generally placed between the applicator and skin (following manufacturer/protocol guidance for the specific application method), while excessive moisture (e.g., sweating) in the treatment area should be avoided/addressed, since moisture can affect field distribution and heating patterns"}],"correct": "D","explanation": "Appropriate use of dry toweling/spacing (per specific technique and manufacturer guidance) and avoidance of excessive moisture in the treatment area are important technique considerations for SWD, since moisture can affect the electromagnetic field distribution and resultant heating pattern."},{"id": 5525,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why perspiration/sweating in the treatment area is generally considered undesirable during SWD application?","options": [{"key": "A","text": "Perspiration has no effect on SWD treatment technique or outcomes"},{"key": "B","text": "Perspiration always improves the uniformity of SWD heating with no downside"},{"key": "C","text": "This consideration only applies to the inductive method, never the capacitive method"},{"key": "D","text": "Moisture from perspiration is highly conductive and can create localized areas of altered/concentrated field distribution and heating, potentially increasing the risk of uneven or excessive localized heating and discomfort"}],"correct": "D","explanation": "Since perspiration is highly conductive, its presence in the treatment area can alter the electromagnetic field distribution, potentially concentrating energy and heating unevenly, which is why maintaining a dry treatment area (using appropriate toweling) is generally emphasized during SWD application."},{"id": 5526,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes appropriate spacing between the SWD applicator/electrode and the patient's skin surface for the capacitive method, as commonly recommended?","options": [{"key": "A","text": "Some air gap spacing (using appropriate spacer pads/toweling per manufacturer guidance) is often incorporated for the capacitive method, which can influence the field distribution pattern and depth of heating achieved"},{"key": "B","text": "Air gap spacing has no relevance to the capacitive method's heating pattern"},{"key": "C","text": "The electrode should always be in direct, firm contact with the skin with zero air gap"},{"key": "D","text": "The electrode must always be positioned at least one meter away from the skin surface for capacitive SWD"}],"correct": "A","explanation": "Appropriate air gap spacing (using spacer pads/toweling per specific technique guidance) is often incorporated in capacitive SWD application, influencing the field distribution and resultant heating pattern within the tissue."},{"id": 5527,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical role of short wave diathermy within a comprehensive physiotherapy treatment plan, considering practical and evidence-based factors?","options": [{"key": "A","text": "SWD should never be combined with any other physiotherapy intervention under any circumstances"},{"key": "B","text": "SWD is generally considered an adjunctive deep-heating modality with a fairly extensive list of contraindications/precautions (particularly regarding metal and implanted devices) and practical application considerations, so its use should be based on careful patient screening and sound clinical reasoning, integrated within a broader, evidence-based treatment plan"},{"key": "C","text": "SWD has been definitively proven completely ineffective for all clinical applications with no exceptions"},{"key": "D","text": "SWD should always be used as the primary, essential intervention for every musculoskeletal condition, given overwhelming supporting evidence and no practical limitations"}],"correct": "B","explanation": "Given SWD's significant heating capacity, extensive contraindication list (particularly regarding metal/implanted devices), and practical application considerations, its use requires careful patient screening and sound clinical reasoning, generally serving as an adjunctive modality within a broader, comprehensive treatment plan."},{"id": 5528,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the frequency of microwave diathermy relative to short wave diathermy, both being classified as deep-heating electromagnetic modalities?","options": [{"key": "A","text": "Microwave diathermy uses a higher frequency (commonly cited around 2450 MHz for medical use) than short wave diathermy (27.12 MHz), placing it further along the electromagnetic spectrum toward higher-frequency radiation"},{"key": "B","text": "Both modalities use an identical frequency with no distinction"},{"key": "C","text": "Microwave diathermy uses a lower frequency than SWD"},{"key": "D","text": "Frequency has no relevance to distinguishing these two modalities"}],"correct": "A","explanation": "Microwave diathermy operates at a considerably higher frequency (commonly around 2450 MHz) than short wave diathermy (27.12 MHz), reflecting their different positions along the electromagnetic spectrum, though both are used for deep tissue heating."},{"id": 5529,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Hard","question": "Which of the following best describes a key safety-related distinction between SWD and standard therapeutic ultrasound regarding contraindications related to metal implants?","options": [{"key": "A","text": "Metal implants have no relevance to either SWD or ultrasound safety considerations"},{"key": "B","text": "Metal implants pose a particularly significant, well-established contraindication for SWD (due to induced eddy currents/field concentration), whereas the relationship between metal implants and ultrasound safety involves different physical considerations that are generally considered less universally severe, though caution may still be relevant depending on specific implant type/materials"},{"key": "C","text": "Metal implants are a greater concern for ultrasound than for SWD"},{"key": "D","text": "Metal implants pose an identical, equally severe concern for both SWD and standard therapeutic ultrasound, with no meaningful distinction"}],"correct": "B","explanation": "While both modalities warrant consideration regarding metal implants, SWD's electromagnetic induction mechanism creates a particularly significant, well-established risk of dangerous localized heating around metal, generally considered a more universally severe contraindication compared to the different physical considerations relevant to ultrasound and metal implants."},{"id": 5530,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate clinical response if a patient reports excessive, rapidly increasing heat sensation during SWD treatment?","options": [{"key": "A","text": "Continue treatment at the same intensity, since this sensation is always expected and harmless"},{"key": "B","text": "Excessive heat sensation should always be ignored unless the patient loses consciousness"},{"key": "C","text": "Immediately reduce or discontinue the treatment intensity/session and inspect the treatment area, since excessive or rapidly increasing heat may indicate a safety concern (e.g., unrecognized metal, equipment malfunction, or inappropriate technique) requiring prompt attention"},{"key": "D","text": "Increase the intensity further to determine the patient's maximum tolerance"}],"correct": "C","explanation": "Excessive or rapidly increasing heat sensation during SWD warrants immediate reduction/discontinuation of treatment and prompt inspection of the treatment area, since this could indicate an underlying safety concern requiring immediate attention."},{"id": 5531,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why SWD is generally contraindicated for direct application over areas with significant open wounds or non-intact skin (outside of specific specialized wound-healing protocols)?","options": [{"key": "A","text": "This consideration only applies to the capacitive method, never the inductive method"},{"key": "B","text": "Open skin has no relevance to SWD application safety"},{"key": "C","text": "Standard SWD parameters and technique are generally not designed or validated for direct application over open wounds, and altered tissue characteristics/moisture in this context could contribute to unpredictable heating patterns and increased risk"},{"key": "D","text": "SWD is always the preferred, first-line treatment for all open wounds with no precaution needed"}],"correct": "C","explanation": "Standard thermal SWD application is generally not appropriate for direct application over open wounds, given the altered tissue characteristics and moisture present, which could contribute to unpredictable heating patterns and increased risk in this specific context."},{"id": 5532,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes an important consideration regarding SWD treatment planning for a patient with a large body habitus/significant adiposity, particularly when using the capacitive method?","options": [{"key": "A","text": "SWD should never be used in any patient regardless of body habitus"},{"key": "B","text": "Given the capacitive method's tendency to preferentially heat higher-resistance fatty tissue, patients with significant adiposity may be at increased risk of excessive superficial fat heating relative to achieving adequate deeper muscle heating, which may influence technique selection (e.g., favoring the inductive method) or careful intensity monitoring"},{"key": "C","text": "The inductive method always poses greater risk than the capacitive method regardless of body habitus"},{"key": "D","text": "Body habitus has no relevance to SWD treatment planning"}],"correct": "B","explanation": "Recognizing the capacitive method's tendency toward preferential fatty tissue heating, careful consideration of technique selection (potentially favoring the inductive method) or vigilant intensity monitoring is warranted for patients with significant adiposity to help ensure appropriate, safe treatment."},{"id": 5533,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate patient positioning consideration during SWD treatment to help minimize burn risk?","options": [{"key": "A","text": "Positioning is only relevant for the capacitive method, never for the inductive method"},{"key": "B","text": "Ensuring the patient is positioned comfortably with the treatment area appropriately exposed/accessible, avoiding unnecessary pressure or contact that could create uneven tissue-electrode relationships, and enabling ongoing communication/monitoring throughout treatment"},{"key": "C","text": "Patient positioning has no relevance to SWD treatment safety"},{"key": "D","text": "Patients should always be positioned in a manner that makes communication with the clinician impossible during treatment"}],"correct": "B","explanation": "Appropriate patient positioning that ensures comfort, proper treatment area exposure/accessibility, and ongoing communication/monitoring capability throughout the session supports safe SWD treatment delivery."},{"id": 5534,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why continuous clinician monitoring/availability (rather than leaving the patient unattended) is generally recommended during SWD treatment?","options": [{"key": "A","text": "Patients should always be left completely unattended for the duration of SWD treatment with no clinician monitoring"},{"key": "B","text": "Given the significant heating capacity of SWD and reliance on patient-reported sensation as a key safety mechanism, ongoing clinician availability to respond promptly to any patient concerns or reported excessive heating is an important safety practice"},{"key": "C","text": "Continuous monitoring is unnecessary since SWD carries no risk once initial parameters are set"},{"key": "D","text": "Clinician monitoring is only relevant for pulsed SWD, never for continuous SWD"}],"correct": "B","explanation": "Given SWD's significant heating capacity and the importance of patient-reported sensation as a safety mechanism, maintaining ongoing clinician availability during treatment supports prompt response to any patient concerns, an important safety practice for this modality."},{"id": 5535,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the concept of 'reactive hyperemia' as it might relate to the vascular response following SWD or other deep-heating treatment?","options": [{"key": "A","text": "Reactive hyperemia refers to a decrease in blood flow following treatment"},{"key": "B","text": "Reactive hyperemia refers exclusively to a cardiac-related phenomenon unrelated to local tissue heating"},{"key": "C","text": "Reactive hyperemia describes an increase in local blood flow that can occur in response to tissue heating, contributing to some of the proposed circulatory benefits associated with deep-heating modalities like SWD"},{"key": "D","text": "This term has no relevance to any electrotherapy or thermal modality"}],"correct": "C","explanation": "Reactive hyperemia describes the local increase in blood flow that can occur following tissue heating, contributing to the proposed circulatory benefits associated with deep-heating modalities such as SWD."},{"id": 5536,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration when SWD is being considered for a patient with a history of recent surgery in or near the proposed treatment area?","options": [{"key": "A","text": "SWD should always be applied immediately regardless of recent surgical history, with no additional screening needed"},{"key": "B","text": "Recent surgical history has no relevance to SWD treatment planning"},{"key": "C","text": "Careful consideration of the surgical history, including presence of any metal hardware/implants from the surgery, wound healing status, and any other relevant precautions, is important before proceeding with SWD in this context"},{"key": "D","text": "This consideration is only relevant for the inductive method, never the capacitive method"}],"correct": "C","explanation": "Given the significant contraindications related to metal implants and open/healing wounds, careful review of any recent surgical history (including hardware placement and wound status) is an important part of appropriate pretreatment screening before considering SWD."},{"id": 5537,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding SWD treatment and the presence of a wet/damp treatment environment (e.g., following hydrotherapy)?","options": [{"key": "A","text": "A wet treatment environment has no relevance to SWD safety or technique"},{"key": "B","text": "SWD should always be performed immediately in a wet environment for optimal therapeutic effect"},{"key": "C","text": "Ensuring the treatment area and immediate environment are appropriately dry before SWD application is important, since moisture is highly conductive and could contribute to altered field distribution, uneven heating, or other safety concerns"},{"key": "D","text": "This consideration is only relevant for pulsed SWD, never continuous SWD"}],"correct": "C","explanation": "Given moisture's high conductivity and potential to alter electromagnetic field distribution, ensuring an appropriately dry treatment area and environment is an important technique and safety consideration before SWD application."},{"id": 5538,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate clinical documentation practice following SWD treatment?","options": [{"key": "A","text": "Only the total treatment time needs to be recorded, with no other parameters relevant"},{"key": "B","text": "SWD documentation should never include information about patient-reported sensation or tolerance"},{"key": "C","text": "Documentation should include the application method used (capacitive/inductive), intensity/dosage level, treatment duration, patient tolerance/response, and any relevant skin findings, supporting continuity of care and safety monitoring"},{"key": "D","text": "Documentation is unnecessary for SWD since it carries no notable risk profile"}],"correct": "C","explanation": "Thorough documentation of SWD application method, dosage, duration, patient response, and skin findings supports continuity of care and ongoing safety monitoring, reflecting good clinical practice for this modality."},{"id": 5539,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why SWD's relatively extensive list of contraindications and technical/safety considerations has contributed to a general decline in its routine clinical use in many contemporary physiotherapy practice settings, relative to some other modalities?","options": [{"key": "A","text": "SWD has no notable contraindications or technical considerations, and its use has actually increased dramatically in recent years with no explanation needed"},{"key": "B","text": "This decline has occurred due to reasons entirely unrelated to any safety, practical, or evidence-based considerations"},{"key": "C","text": "The combination of significant contraindications (particularly metal/implanted devices), equipment/space requirements, and mixed evidence regarding unique clinical benefit relative to other available interventions has contributed to many practice settings favoring other modalities or approaches with fewer complicating factors, though SWD remains a recognized, taught modality in many curricula"},{"key": "D","text": "All contraindications and technical considerations for SWD have been definitively proven to be complete myths with no clinical basis"}],"correct": "C","explanation": "A combination of SWD's significant contraindication profile (particularly regarding metal/implanted devices), practical equipment/space requirements, and evolving evidence regarding relative clinical benefit compared to alternative interventions has contributed to many contemporary practice settings favoring other approaches, even though SWD remains a recognized and taught modality within physiotherapy education."},{"id": 5540,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the clinical rationale for combining SWD-induced tissue heating with subsequent stretching or joint mobilization techniques, similar to the rationale applied to other deep-heating modalities?","options": [{"key": "A","text": "There is no established rationale for combining SWD with subsequent manual techniques"},{"key": "B","text": "Applying heat is theorized to increase collagen tissue extensibility, and performing stretching/mobilization promptly after SWD (while tissue temperature remains elevated) is thought to potentially enhance the effectiveness of these techniques, similar to the rationale applied with other deep-heating modalities like ultrasound"},{"key": "C","text": "SWD always decreases tissue extensibility, making subsequent stretching counterproductive"},{"key": "D","text": "SWD and subsequent manual techniques should never be used within the same treatment session"}],"correct": "B","explanation": "Consistent with the general principle applied to other deep-heating modalities, combining SWD's proposed collagen-extensibility-enhancing thermal effect with promptly-performed stretching or mobilization is a commonly cited clinical rationale for sequencing these interventions together."},{"id": 5541,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why careful attention to the manufacturer's specific operating instructions and safety guidelines is particularly important when using SWD equipment?","options": [{"key": "A","text": "Manufacturer instructions have no relevance to safe SWD equipment use"},{"key": "B","text": "Manufacturer instructions are only relevant for the inductive method, never for the capacitive method"},{"key": "C","text": "All SWD devices operate identically with no need to consult device-specific instructions"},{"key": "D","text": "Given SWD's significant power output, electromagnetic field characteristics, and the variation in specific technique/application details between different device models, careful adherence to manufacturer-specific guidance is important for safe, effective, and consistent treatment delivery"}],"correct": "D","explanation": "Given the variation in specific technical characteristics and application details between different SWD device models, careful adherence to manufacturer-specific operating and safety guidance is important for safe, effective, and consistent clinical use of this modality."},{"id": 5542,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding informed consent and patient education prior to SWD treatment, given the modality's notable contraindication profile?","options": [{"key": "A","text": "Given SWD's significant heating capacity and relatively extensive contraindication list, thorough patient screening, clear communication regarding the treatment process/expected sensations, and appropriate informed consent discussion are important components of responsible clinical practice"},{"key": "B","text": "Informed consent and education are unnecessary for SWD since it carries no meaningful risk"},{"key": "C","text": "Informed consent is only relevant for surgical procedures, never for physiotherapy modalities like SWD"},{"key": "D","text": "Patient education prior to SWD treatment should never include any discussion of expected sensations"}],"correct": "A","explanation": "Given SWD's significant contraindication profile and heating capacity, thorough patient screening combined with clear communication and informed consent discussion prior to treatment reflects responsible, patient-centered clinical practice for this modality."},{"id": 5543,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general clinical reasoning process a physiotherapist should apply when considering SWD for a given patient presentation, given its distinct risk profile compared to some other modalities?","options": [{"key": "A","text": "SWD decisions should be made without considering the patient's specific medical history or presentation"},{"key": "B","text": "SWD should be applied to any patient reporting musculoskeletal symptoms, without any individualized screening or clinical reasoning process"},{"key": "C","text": "A thorough clinical reasoning process should include careful screening for the modality's specific contraindications (particularly metal/implanted devices, pregnancy, malignancy, impaired sensation/circulation), consideration of alternative modalities with potentially more favorable risk profiles, and integration within a broader, evidence-based treatment plan if SWD is deemed appropriate"},{"key": "D","text": "Clinical reasoning is unnecessary for SWD since it has an identical risk profile to all other electrotherapy modalities"}],"correct": "C","explanation": "Given SWD's distinct and notable contraindication profile, sound clinical reasoning requires thorough screening, consideration of alternative modalities, and thoughtful integration within the broader treatment plan if SWD is ultimately selected as an appropriate intervention for the individual patient."},{"id": 5544,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best summarizes the relationship between SWD's classification as a 'deep-heating' modality and its clinical indications, similar in principle to other deep-heating options like therapeutic ultrasound?","options": [{"key": "A","text": "As a deep-heating modality, SWD is generally considered for conditions where increasing temperature in deeper tissue structures (e.g., large muscle groups, deep joint structures) is a desired therapeutic goal, similar in general principle to other deep-heating modalities, though specific modality selection should consider the relative advantages, contraindications, and practical factors of each available option"},{"key": "B","text": "Deep-heating classification is irrelevant to clinical decision-making regarding modality selection"},{"key": "C","text": "SWD is indicated primarily for conditions requiring superficial, not deep, tissue effects"},{"key": "D","text": "SWD has no established relationship between its heating depth classification and clinical indication selection"}],"correct": "A","explanation": "SWD's classification as a deep-heating modality generally informs its consideration for conditions where increasing temperature in deeper tissue structures is a therapeutic goal, though selection among available deep-heating options should thoughtfully weigh each modality's relative advantages, contraindications, and practical considerations for the individual patient."},{"id": 5545,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Easy","question": "Microwave diathermy uses electromagnetic energy at a frequency that is:","options": [{"key": "A","text": "Identical to short wave diathermy at 27.12 MHz"},{"key": "B","text": "Lower than short wave diathermy"},{"key": "C","text": "Within the audible sound wave range"},{"key": "D","text": "Higher than short wave diathermy, commonly cited at approximately 2450 MHz (2.45 GHz) for medical therapeutic use"}],"correct": "D","explanation": "Microwave diathermy operates at a considerably higher frequency (commonly around 2450 MHz) than short wave diathermy (27.12 MHz), placing it further along the electromagnetic spectrum."},{"id": 5546,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Microwave diathermy energy is delivered to the patient via:","options": [{"key": "A","text": "Ingested capsules containing a microwave-emitting device"},{"key": "B","text": "A director/applicator that emits electromagnetic energy through the air toward the treatment area, without requiring direct skin contact"},{"key": "C","text": "Direct skin contact electrodes, similar to capacitive SWD"},{"key": "D","text": "An implanted electrode requiring a surgical procedure"}],"correct": "B","explanation": "Microwave diathermy is applied using a director (applicator) that radiates electromagnetic energy through the air toward the treatment area, distinguishing its application from the direct-contact techniques used in SWD."},{"id": 5547,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Compared to short wave diathermy, microwave diathermy generally penetrates to:","options": [{"key": "A","text": "An identical depth to SWD with no meaningful difference"},{"key": "B","text": "A more superficial tissue depth than SWD, due to its higher frequency being absorbed more readily by superficial tissue layers"},{"key": "C","text": "A greater tissue depth than SWD"},{"key": "D","text": "No measurable depth whatsoever; it only affects the outermost skin layer"}],"correct": "B","explanation": "Due to its higher frequency, microwave energy is generally absorbed more readily by superficial tissue, resulting in a comparatively shallower depth of effective heating compared to short wave diathermy."},{"id": 5548,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Microwave diathermy is generally considered particularly effective at heating tissues with high water content, such as muscle, primarily because:","options": [{"key": "A","text": "Water strongly reflects microwave energy with no absorption"},{"key": "B","text": "Water molecules readily absorb microwave energy (related to the interaction between the electromagnetic field and polar water molecules), converting it into heat within water-rich tissue"},{"key": "C","text": "Microwave energy has no interaction with water content in any tissue"},{"key": "D","text": "Only bone tissue absorbs microwave energy effectively"}],"correct": "B","explanation": "Microwave energy is particularly well absorbed by tissue with high water content (such as muscle) due to the interaction between the oscillating electromagnetic field and polar water molecules, which generates heat as these molecules attempt to align with the rapidly changing field."},{"id": 5549,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following tissues is generally considered relatively LESS effectively heated by microwave diathermy, given its comparatively lower water content?","options": [{"key": "A","text": "Synovial fluid"},{"key": "B","text": "Muscle tissue"},{"key": "C","text": "Adipose (fat) tissue, though this can create complexities regarding energy distribution when fat and muscle layers are both present in the treatment field"},{"key": "D","text": "Blood"}],"correct": "C","explanation": "Fat tissue, having relatively lower water content than muscle, is generally heated less effectively by microwave energy compared to more water-rich tissues, though the interaction between fat and muscle layers in a treatment field can create complex heating patterns."},{"id": 5550,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is a significant, well-established contraindication for microwave diathermy, similar in rationale to the concern with short wave diathermy?","options": [{"key": "A","text": "Application to normal, healthy muscle tissue"},{"key": "B","text": "Application to areas with abundant water content, since this always eliminates any treatment effect"},{"key": "C","text": "Presence of metal implants/objects in or near the treatment field, due to risk of excessive localized heating around the metal"},{"key": "D","text": "Application during a completely dry treatment environment with no moisture present"}],"correct": "C","explanation": "Similar to the concern with SWD, metal implants/objects can interact with microwave electromagnetic energy in ways that risk excessive, potentially dangerous localized heating, making this a significant contraindication."},{"id": 5551,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is a contraindication for microwave diathermy, related to its particular tissue absorption characteristics and specific vulnerable body structures?","options": [{"key": "A","text": "Application is only contraindicated over areas with very low water content"},{"key": "B","text": "Application over dry, low-water-content bone tissue exclusively, with no other structure-specific concerns"},{"key": "C","text": "Application over the eyes, given the eye's high fluid/water content and potential vulnerability to microwave-related heating effects (e.g., theoretical cataract risk with excessive/inappropriate exposure)"},{"key": "D","text": "Microwave diathermy has no structure-specific contraindications of any kind"}],"correct": "C","explanation": "Given the eye's high fluid content and particular sensitivity, along with historical concerns regarding potential microwave-related effects on ocular tissue (e.g., theoretical cataract risk with excessive exposure), application over the eyes is a specifically recognized contraindication for microwave diathermy."},{"id": 5552,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Similar to short wave diathermy, microwave diathermy is generally contraindicated over the abdomen/pelvis/lumbar region during pregnancy primarily due to:","options": [{"key": "A","text": "Microwave diathermy is proven to always be completely safe during pregnancy with strong supporting evidence"},{"key": "B","text": "No established concern regarding microwave diathermy and pregnancy"},{"key": "C","text": "The established risk of significant tissue heating from microwave energy potentially harming fetal development, making this an important contraindication during pregnancy for this treatment region"},{"key": "D","text": "This contraindication is unique to SWD and does not apply to microwave diathermy"}],"correct": "C","explanation": "Given the established significant tissue-heating capacity of microwave diathermy, application over the abdomen/pelvis/lumbar region during pregnancy is contraindicated, similar to the established precaution for SWD."},{"id": 5553,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Similar to short wave diathermy, microwave diathermy is generally contraindicated near cardiac pacemakers and other implanted electronic devices primarily due to:","options": [{"key": "A","text": "No established risk; this is a myth without clinical basis for microwave diathermy specifically"},{"key": "B","text": "Microwave diathermy is proven to always improve pacemaker function with strong supporting evidence"},{"key": "C","text": "The risk of electromagnetic interference with the device's electronic circuitry, potentially causing device malfunction"},{"key": "D","text": "This contraindication only applies to SWD, never to microwave diathermy"}],"correct": "C","explanation": "Similar to the concern with SWD, microwave diathermy's electromagnetic field poses a risk of interfering with the electronic circuitry of implanted devices like pacemakers, making this a significant, well-established contraindication."},{"id": 5554,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is a contraindication for microwave diathermy related to malignancy, consistent with the general precaution applied across many heating/electrotherapy modalities?","options": [{"key": "A","text": "This contraindication only applies to modalities other than microwave diathermy"},{"key": "B","text": "Microwave diathermy is proven to always cure malignancy with strong supporting evidence"},{"key": "C","text": "Application over or near known/suspected malignancy is generally contraindicated, due to theoretical concerns that increased local blood flow/cellular activity could potentially influence tumor behavior"},{"key": "D","text": "No established concern regarding malignancy and microwave diathermy"}],"correct": "C","explanation": "Consistent with the general precaution applied across various heating and electrotherapy modalities, microwave diathermy over known/suspected malignancy is contraindicated due to theoretical concerns about influencing local blood flow/cellular activity relevant to tumor behavior."},{"id": 5555,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is a contraindication for microwave diathermy related to impaired patient sensation in the treatment area?","options": [{"key": "A","text": "Microwave diathermy is always completely safe regardless of the patient's sensory status"},{"key": "B","text": "This consideration is only relevant to short wave diathermy, never to microwave diathermy"},{"key": "C","text": "Impaired sensation has no bearing on microwave diathermy safety"},{"key": "D","text": "Application over areas of significantly impaired sensation is contraindicated, since the patient's reduced ability to accurately perceive and report excessive/uncomfortable heating increases burn risk"}],"correct": "D","explanation": "Similar to the rationale for SWD, reliable patient-reported sensation is an important safety mechanism during microwave diathermy treatment, making application over areas of significantly impaired sensation a contraindication due to increased burn risk."},{"id": 5556,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following is a contraindication for microwave diathermy related to impaired local circulation in the treatment area?","options": [{"key": "A","text": "This consideration is only relevant to superficial heating modalities, never to microwave diathermy"},{"key": "B","text": "Application over areas of significantly impaired local circulation is contraindicated, since compromised circulation impairs the tissue's ability to dissipate the heat generated, increasing risk of excessive, potentially damaging local temperature rise"},{"key": "C","text": "Impaired circulation has no bearing on microwave diathermy safety"},{"key": "D","text": "Microwave diathermy is always completely safe regardless of the patient's local circulatory status"}],"correct": "B","explanation": "Similar to the rationale applied to other heating modalities, significantly impaired local circulation increases the risk of excessive, damaging temperature rise during microwave diathermy, since heat dissipation is compromised, making this a recognized contraindication."},{"id": 5557,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding treatment area moisture (e.g., perspiration) during microwave diathermy application, similar to considerations relevant to SWD?","options": [{"key": "A","text": "This consideration is unique to SWD and irrelevant to microwave diathermy"},{"key": "B","text": "Moisture always improves the uniformity of microwave heating with no downside"},{"key": "C","text": "Since moisture can influence how microwave energy is absorbed and distributed, an appropriately dry treatment area is generally desirable to help promote more predictable, even heating patterns"},{"key": "D","text": "Moisture has no relevance to microwave diathermy treatment technique or safety"}],"correct": "C","explanation": "Similar to considerations relevant to SWD, treatment area moisture can influence microwave energy absorption/distribution patterns, so maintaining an appropriately dry area is generally desirable for more predictable, even heating."},{"id": 5558,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate distance/positioning consideration for the microwave diathermy applicator relative to the patient's skin surface?","options": [{"key": "A","text": "Applicator distance has no relevance to the effectiveness or safety of microwave diathermy treatment"},{"key": "B","text": "The applicator should always be in direct, firm contact with the skin with zero air gap, identical to standard capacitive SWD technique"},{"key": "C","text": "The applicator must always be positioned at least 10 meters away from the patient for safe treatment"},{"key": "D","text": "A specific air gap distance (per manufacturer/protocol guidance) is generally maintained between the applicator and the skin surface, since microwave energy is delivered through the air to the treatment area rather than via direct contact"}],"correct": "D","explanation": "Since microwave diathermy delivers energy through the air via a director/applicator (rather than requiring direct skin contact), maintaining an appropriate, specified air gap distance per manufacturer/protocol guidance is an important technique consideration."},{"id": 5559,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general treatment duration considerations for a typical microwave diathermy session aimed at producing therapeutic tissue heating?","options": [{"key": "A","text": "Microwave diathermy sessions must always last several hours to achieve any therapeutic effect"},{"key": "B","text": "Treatment duration is always fixed at exactly 1 second regardless of clinical goal"},{"key": "C","text": "Typical treatment durations are commonly cited in ranges roughly comparable to those used for SWD (e.g., approximately 15-20 minutes), though specific duration may be adjusted based on the clinical goal, intensity, and patient tolerance"},{"key": "D","text": "Treatment duration has no bearing on the therapeutic effect or safety of microwave diathermy"}],"correct": "C","explanation": "While specific protocols vary, typical microwave diathermy treatment durations are commonly cited in ranges generally comparable to SWD (e.g., approximately 15-20 minutes), with adjustments based on the specific clinical goal and patient tolerance."},{"id": 5560,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes an important safety consideration regarding clinician and bystander protection during microwave diathermy treatment delivery, given that energy is radiated through the air?","options": [{"key": "A","text": "Since microwave energy is radiated through the air (unlike direct-contact modalities), appropriate consideration of exposure to the clinician and any bystanders in proximity to the treatment field is a relevant safety consideration, distinct from concerns unique to direct-contact modalities"},{"key": "B","text": "This consideration only applies to short wave diathermy, never to microwave diathermy"},{"key": "C","text": "Only the patient's exposure matters; clinician/bystander exposure is never a relevant consideration"},{"key": "D","text": "No protective measures are ever necessary for anyone present in the treatment room"}],"correct": "A","explanation": "Because microwave energy is radiated through the air toward the treatment area (rather than being confined to direct patient contact), appropriate awareness of and precautions regarding clinician/bystander exposure represents a relevant safety consideration somewhat distinct from concerns specific to direct-contact modalities."},{"id": 5561,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why the historical use of microwave diathermy has declined somewhat in many contemporary physiotherapy practice settings, relative to its earlier more widespread clinical use?","options": [{"key": "A","text": "A combination of significant contraindications (particularly metal implants and specific structures like the eyes), practical/technical considerations, and evolving evidence regarding relative clinical benefit compared to alternative interventions has contributed to many practice settings favoring other modalities or approaches"},{"key": "B","text": "All safety considerations for microwave diathermy have been definitively proven to be complete myths with no clinical basis"},{"key": "C","text": "This decline has occurred due to reasons entirely unrelated to any safety, practical, or evidence-based considerations"},{"key": "D","text": "Microwave diathermy has no notable safety considerations, and its use has actually increased dramatically with no explanation needed"}],"correct": "A","explanation": "Similar to the trend observed with SWD, a combination of notable contraindications, practical/technical considerations, and evolving evidence regarding relative clinical benefit has contributed to reduced routine use of microwave diathermy in many contemporary practice settings, though it remains a recognized modality within physiotherapy education and select practice."},{"id": 5562,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general clinical indications historically proposed for microwave diathermy, given its heating characteristics?","options": [{"key": "A","text": "Microwave diathermy is indicated exclusively for treating dry, low-water-content tissues like tendon and ligament, with no relevance to muscle"},{"key": "B","text": "Microwave diathermy is used exclusively for wound healing, with no thermal/heating-related indications"},{"key": "C","text": "Similar to other deep(er)-heating modalities, proposed indications historically included conditions where increased local tissue temperature (particularly in muscle, given its water content) was considered a desired therapeutic goal, such as certain musculoskeletal conditions benefiting from thermal effects (e.g., increased extensibility, pain modulation, circulatory effects)"},{"key": "D","text": "Microwave diathermy has no proposed clinical indications of any kind"}],"correct": "C","explanation": "Historically, microwave diathermy's proposed indications generally paralleled those of other deep-heating modalities, targeting conditions where increased tissue temperature (particularly benefiting water-rich tissues like muscle) was a desired therapeutic goal for effects such as increased extensibility, pain modulation, and enhanced circulation."},{"id": 5563,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate pretreatment screening consideration specific to microwave diathermy, paralleling considerations relevant to SWD?","options": [{"key": "A","text": "Pretreatment screening is unnecessary for microwave diathermy since it carries no notable risk profile"},{"key": "B","text": "No screening is needed beyond confirming the patient has no known allergies"},{"key": "C","text": "Thorough screening for contraindications including metal implants, pregnancy (if treating the relevant body region), cardiac devices, malignancy, and impaired sensation/circulation, along with specific attention to eye protection/avoidance given the modality's particular structure-specific contraindication, is important before proceeding with treatment"},{"key": "D","text": "Screening considerations for microwave diathermy are completely unrelated to those relevant for SWD"}],"correct": "C","explanation": "Comprehensive pretreatment screening for microwave diathermy should address the range of general contraindications shared with SWD, along with specific attention to eye-related precautions given this modality's particular structure-specific contraindication profile."},{"id": 5564,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important documentation practice following microwave diathermy treatment?","options": [{"key": "A","text": "Only the total treatment time needs to be recorded, with no other parameters relevant"},{"key": "B","text": "Documentation should include the applicator type/positioning, intensity/dosage, treatment duration, patient tolerance/response, and any relevant skin findings, supporting continuity of care and safety monitoring"},{"key": "C","text": "Microwave diathermy documentation should never include information about patient-reported sensation or tolerance"},{"key": "D","text": "Documentation is unnecessary for microwave diathermy since it carries no notable risk profile"}],"correct": "B","explanation": "Thorough documentation of microwave diathermy application parameters, patient response, and relevant findings supports continuity of care and ongoing safety monitoring, similar to documentation practices for other deep-heating modalities."},{"id": 5565,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best summarizes an appropriate overall clinical approach to selecting between short wave diathermy and microwave diathermy when a deep-heating modality is considered clinically appropriate for a given patient?","options": [{"key": "A","text": "The two modalities are functionally and practically identical, so selection is entirely arbitrary with no meaningful clinical considerations"},{"key": "B","text": "Microwave diathermy should always be selected over SWD regardless of any other consideration"},{"key": "C","text": "Selection should consider factors such as the target tissue depth and composition (e.g., microwave's relatively more superficial penetration and particular effectiveness in water-rich tissue versus SWD's generally somewhat greater depth capability), specific contraindications relevant to each modality, and equipment availability/clinician familiarity"},{"key": "D","text": "SWD should always be selected over microwave diathermy regardless of any other consideration"}],"correct": "C","explanation": "Thoughtful selection between SWD and microwave diathermy should consider each modality's specific tissue penetration/absorption characteristics, relevant contraindications, and practical factors such as equipment availability, reflecting individualized clinical reasoning rather than an arbitrary or universally fixed choice."},{"id": 5566,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes why microwave diathermy is generally considered less suitable than short wave diathermy for treating a target structure located beneath a substantial layer of subcutaneous fat?","options": [{"key": "A","text": "Given microwave energy's relatively superficial penetration and reduced absorption in lower-water-content fat tissue, a substantial fat layer may limit effective energy delivery to a deeper target structure, making SWD (particularly the inductive method) potentially more suitable in such cases"},{"key": "B","text": "Fat layer thickness has no bearing on modality selection for deep-heating treatment"},{"key": "C","text": "Fat has no relevance to microwave diathermy's heating pattern or effectiveness"},{"key": "D","text": "Microwave diathermy always penetrates fat layers more effectively than SWD with no limitation"}],"correct": "A","explanation": "Since microwave energy's relatively superficial penetration and reduced fat tissue absorption can limit effective delivery to deeper targets beneath a substantial fat layer, SWD (particularly the inductive method, which favors conductive tissue like muscle) may be considered more suitable in such scenarios."},{"id": 5567,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes the general safety profile of microwave diathermy when applied by a trained clinician following standard guidelines in an appropriately screened patient?","options": [{"key": "A","text": "Microwave diathermy is inherently dangerous and should essentially never be used in clinical practice under any circumstances"},{"key": "B","text": "Microwave diathermy is generally considered a safe modality when applied appropriately by a trained clinician following standard screening, contraindication, and parameter guidelines, though as with SWD, attention to its specific contraindication profile and proper technique remains important"},{"key": "C","text": "Microwave diathermy carries no risk whatsoever under any circumstances, eliminating the need for any screening or precautions"},{"key": "D","text": "Safety considerations for microwave diathermy are entirely unrelated to those applicable to other deep-heating modalities"}],"correct": "B","explanation": "When applied appropriately by a trained clinician following standard screening and guidelines, microwave diathermy is generally considered a safe therapeutic modality, though careful attention to its specific contraindication profile and proper application technique remains important, similar to considerations for SWD."},{"id": 5568,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate patient education point regarding expected sensation during microwave diathermy treatment?","options": [{"key": "A","text": "Any sensation reported during treatment should be entirely disregarded by the clinician"},{"key": "B","text": "Patients should be informed that a gradually building, comfortable warmth is generally expected, and instructed to immediately report any sharp pain or excessive/rapidly increasing heat, which may indicate a need for parameter or positioning adjustment"},{"key": "C","text": "Patients should expect significant pain as a normal, unavoidable part of effective microwave diathermy treatment"},{"key": "D","text": "Patients should expect no sensation whatsoever during treatment"}],"correct": "B","explanation": "Similar to patient education practices for other deep-heating modalities, setting expectations for gradual, comfortable warmth while emphasizing prompt reporting of any excessive or sharp sensation supports safe, effective microwave diathermy treatment delivery."},{"id": 5569,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why microwave diathermy is generally contraindicated for application over areas with significant edema/fluid accumulation, similar to the rationale applied to SWD?","options": [{"key": "A","text": "Microwave diathermy always eliminates edema completely with no associated risk"},{"key": "B","text": "Given microwave energy's particular absorption by water-rich tissue, areas of significant edema could experience excessive, uneven, or unpredictable localized heating"},{"key": "C","text": "This consideration only applies to SWD, never to microwave diathermy"},{"key": "D","text": "No established concern regarding edema and microwave diathermy application"}],"correct": "B","explanation": "Since microwave energy is particularly well-absorbed by water-rich tissue, areas of significant edema present an increased risk of excessive or unpredictable localized heating, making this a relevant contraindication/precaution similar to that recognized for SWD."},{"id": 5570,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate clinical response if microwave diathermy equipment is suspected of malfunctioning (e.g., inconsistent output, unusual sounds) during patient treatment?","options": [{"key": "A","text": "Continue treatment regardless of any suspected equipment malfunction, since patient safety is not affected by device issues"},{"key": "B","text": "Treatment should be discontinued promptly, the equipment inspected/serviced as needed, and the device should not be used again until confirmed to be functioning safely and appropriately"},{"key": "C","text": "Only the patient's subjective report matters; equipment malfunction indicators should always be ignored"},{"key": "D","text": "Equipment malfunctions have no relevance to patient safety during microwave diathermy treatment"}],"correct": "B","explanation": "Prompt discontinuation of treatment and appropriate equipment inspection/servicing in response to any suspected device malfunction is an important safety practice, given the significant energy output and associated risks of deep-heating modalities like microwave diathermy."},{"id": 5571,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding microwave diathermy use in patients who are unable to reliably communicate (e.g., due to sedation, severe cognitive impairment, or language barriers without adequate interpretation)?","options": [{"key": "A","text": "Microwave diathermy should always be applied at standard parameters regardless of the patient's communication ability"},{"key": "B","text": "Communication ability has no relevance to microwave diathermy safety considerations"},{"key": "C","text": "Since reliable patient-reported sensation is a key safety mechanism for this modality, significant limitations in a patient's ability to communicate discomfort warrant additional caution, closer monitoring, or reconsideration of whether this modality is appropriate for the individual patient"},{"key": "D","text": "This consideration is only relevant to SWD, never to microwave diathermy"}],"correct": "C","explanation": "Given the importance of reliable patient-reported sensation as a safety mechanism, significant communication limitations warrant additional caution, closer monitoring, or reconsideration of modality appropriateness when considering microwave diathermy for an individual patient."},{"id": 5572,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best summarizes the overall clinical role of microwave diathermy within contemporary evidence-based physiotherapy practice, considering its distinct risk profile and relatively more limited routine clinical use compared to some other modalities?","options": [{"key": "A","text": "Microwave diathermy has no legitimate role whatsoever in physiotherapy education or practice"},{"key": "B","text": "Microwave diathermy should always be used as a first-line, primary intervention for every musculoskeletal condition, given overwhelming and conclusive supporting evidence"},{"key": "C","text": "Given its specific contraindication profile, relatively more limited routine clinical use in many contemporary settings, and the availability of alternative deep-heating options, microwave diathermy is generally considered a modality requiring careful, individualized clinical reasoning if selected, integrated thoughtfully within a broader evidence-based treatment approach"},{"key": "D","text": "Microwave diathermy should never be combined with any other physiotherapy intervention under any circumstances"}],"correct": "C","explanation": "Reflecting its specific contraindication profile and relatively more limited routine contemporary clinical use, microwave diathermy generally warrants careful, individualized clinical reasoning if selected for a patient, integrated thoughtfully within a broader evidence-based treatment approach alongside consideration of alternative available options."},{"id": 5573,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Medium","question": "Which of the following best describes why understanding the shared underlying principles of electromagnetic energy (frequency, wavelength, and their relationship to tissue penetration/absorption) is valuable for clinicians comparing modalities such as SWD, microwave diathermy, and other electromagnetic-based treatments?","options": [{"key": "A","text": "This understanding has no practical clinical relevance to modality selection or application"},{"key": "B","text": "A foundational understanding of how frequency and wavelength relate to tissue penetration and absorption characteristics helps clinicians make informed, evidence-based decisions when selecting among available deep-heating modalities for a specific clinical goal and target tissue"},{"key": "C","text": "These underlying principles are identical for all electromagnetic modalities with no meaningful distinctions relevant to clinical practice"},{"key": "D","text": "Only engineers need to understand these underlying principles; clinicians require no such understanding"}],"correct": "B","explanation": "A solid foundational understanding of how electromagnetic frequency and wavelength relate to tissue penetration and absorption supports informed, evidence-based clinical decision-making when selecting among available deep-heating modality options for a specific patient and treatment goal."},{"id": 5574,"subject": "Electrotherapy","topic": "General Electrotherapy","difficulty": "Hard","question": "Which of the following best describes the general regulatory/allocation context for the specific frequencies used in medical short wave and microwave diathermy (e.g., 27.12 MHz and 2450 MHz)?","options": [{"key": "A","text": "These frequencies are selected entirely randomly with no formal allocation or regulatory basis"},{"key": "B","text": "These frequencies change randomly on a daily basis with no fixed allocation"},{"key": "C","text": "These specific frequencies are part of internationally allocated bands (Industrial, Scientific, and Medical bands) designated for these types of applications, helping minimize interference with other communication/broadcast services operating at nearby frequencies"},{"key": "D","text": "There is no formal international allocation system for these therapeutic frequencies"}],"correct": "C","explanation": "The specific frequencies used in medical short wave and microwave diathermy are part of internationally allocated Industrial, Scientific, and Medical (ISM) frequency bands, a regulatory framework designed to help minimize interference with other communication and broadcast services."},{"id": 5575,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Easy","question": "Infrared radiation is a form of electromagnetic energy located on the spectrum:","options": [{"key": "A","text": "Identical to the frequency range used in ultrasound therapy"},{"key": "B","text": "Between visible light and microwave radiation, with a wavelength longer than visible red light"},{"key": "C","text": "Between radio waves and microwaves"},{"key": "D","text": "Between X-rays and ultraviolet light"}],"correct": "B","explanation": "Infrared radiation occupies the region of the electromagnetic spectrum with wavelengths longer than visible light (beyond red) but shorter than microwaves."},{"id": 5576,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Infrared radiation is generally classified into which two main types based on wavelength, relevant to therapeutic application?","options": [{"key": "A","text": "Type A (short wave) and Type B (long wave) infrared, referring to differences in penetration depth"},{"key": "B","text": "Type X and Type Y infrared, with no established wavelength-based distinction"},{"key": "C","text": "Only a single type of infrared radiation exists, with no further subclassification"},{"key": "D","text": "Near infrared (IRA, shorter wavelength) and far infrared (IRC, longer wavelength), with differing penetration and heating characteristics"}],"correct": "D","explanation": "Infrared radiation used therapeutically is generally classified into near infrared (shorter wavelength, e.g., from luminous generators) and far infrared (longer wavelength, e.g., from non-luminous generators), which differ in their tissue penetration and heating characteristics."},{"id": 5577,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Near infrared (shorter wavelength) radiation generally penetrates:","options": [{"key": "A","text": "Less deeply than far infrared radiation"},{"key": "B","text": "More deeply into tissue than far infrared radiation, though still classified as a superficial heating modality overall compared to deep-heating modalities like SWD/ultrasound"},{"key": "C","text": "Identically to far infrared, with no difference in penetration depth"},{"key": "D","text": "To a depth of several centimeters, comparable to short wave diathermy"}],"correct": "B","explanation": "Near infrared, having a comparatively shorter wavelength within the infrared spectrum, generally penetrates somewhat more deeply into tissue than far infrared, though infrared overall remains classified as a superficial heating modality relative to deep-heating options like SWD or ultrasound."},{"id": 5578,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Far infrared (longer wavelength) radiation is generally:","options": [{"key": "A","text": "Not absorbed by tissue at all"},{"key": "B","text": "Absorbed more superficially (largely at the skin surface) compared to near infrared radiation, due to its longer wavelength characteristics"},{"key": "C","text": "Used exclusively for deep muscle heating, similar to short wave diathermy"},{"key": "D","text": "Absorbed more deeply than near infrared"}],"correct": "B","explanation": "Far infrared, having a longer wavelength, is generally absorbed more superficially (predominantly at or very near the skin surface) compared to the somewhat deeper-penetrating near infrared radiation."},{"id": 5579,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Luminous infrared generators (e.g., infrared lamps that produce visible light along with infrared radiation) are generally associated with producing predominantly:","options": [{"key": "A","text": "A combination that includes a greater proportion of near infrared radiation (along with some visible light and far infrared), given their higher operating temperature"},{"key": "B","text": "Far infrared radiation exclusively, with no near infrared component"},{"key": "C","text": "Only ultraviolet radiation, with no infrared component"},{"key": "D","text": "No radiation of any kind"}],"correct": "A","explanation": "Luminous generators, operating at higher temperatures and producing visible light alongside infrared, tend to emit a greater proportion of near infrared radiation compared to non-luminous generators."},{"id": 5580,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Non-luminous infrared generators (e.g., heating elements that produce infrared without visible light, glowing only a dull red or not at all) are generally associated with producing predominantly:","options": [{"key": "A","text": "Only visible light, with no infrared component"},{"key": "B","text": "Ultraviolet radiation exclusively"},{"key": "C","text": "Far infrared radiation, given their lower operating temperature compared to luminous generators"},{"key": "D","text": "Near infrared radiation exclusively"}],"correct": "C","explanation": "Non-luminous generators, operating at lower temperatures than luminous sources, tend to emit predominantly far infrared radiation."},{"id": 5581,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Easy","question": "The primary therapeutic effect of infrared therapy is:","options": [{"key": "A","text": "Superficial heating of the skin and immediately underlying tissue, since infrared radiation is largely absorbed at or near the skin surface"},{"key": "B","text": "Deep tissue heating comparable to short wave diathermy"},{"key": "C","text": "Photochemical (non-thermal) effects identical to laser therapy"},{"key": "D","text": "Direct electrical stimulation of nerve tissue"}],"correct": "A","explanation": "Infrared therapy is classified as a superficial heating modality, producing thermal effects largely confined to the skin and immediately underlying superficial tissue, given infrared's limited depth of penetration and absorption pattern."},{"id": 5582,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Proposed physiological effects of infrared therapy, consistent with its superficial heating mechanism, include:","options": [{"key": "A","text": "Deep muscle relaxation exclusively, with no effect on skin or superficial circulation"},{"key": "B","text": "No measurable physiological effect of any kind"},{"key": "C","text": "Complete elimination of all pain throughout the body, unrelated to the treated area"},{"key": "D","text": "Increased superficial blood flow (erythema), mild local analgesic effect, and some increase in superficial tissue extensibility, along with general relaxation/comfort"}],"correct": "D","explanation": "Consistent with its superficial heating mechanism, infrared therapy's proposed effects include increased local superficial blood flow (visible as erythema), mild analgesic benefit, some increase in superficial tissue extensibility, and general relaxation/comfort."},{"id": 5583,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "The inverse square law, as it applies to infrared lamp positioning, states that:","options": [{"key": "A","text": "Intensity of radiation increases as distance from the source increases"},{"key": "B","text": "Intensity remains completely constant regardless of the distance between the lamp and the treatment area"},{"key": "C","text": "Intensity of radiation is inversely proportional to the square of the distance from the source, meaning intensity decreases rapidly as the lamp is moved farther from the treatment area"},{"key": "D","text": "Distance has no relevance to infrared lamp intensity or safety"}],"correct": "C","explanation": "Per the inverse square law, radiant intensity decreases rapidly (inversely proportional to the square of distance) as an infrared lamp is positioned farther from the treatment surface, an important consideration for both dosing and safety."},{"id": 5584,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes a practical application of the inverse square law when positioning an infrared lamp for treatment?","options": [{"key": "A","text": "The lamp should always be positioned in direct contact with the skin for optimal treatment"},{"key": "B","text": "Distance from the lamp to the skin has no bearing on treatment intensity or safety, so any distance is acceptable"},{"key": "C","text": "Appropriate lamp-to-skin distance must be carefully considered and maintained (per standard guidelines, often in ranges of approximately 45-60 cm depending on lamp type/wattage) to deliver an appropriately therapeutic, safe intensity, since moving the lamp closer significantly increases intensity while moving it farther significantly decreases intensity"},{"key": "D","text": "Only the treatment duration matters; lamp distance is entirely irrelevant to dosing"}],"correct": "C","explanation": "Given the significant effect of distance on radiant intensity (per the inverse square law), maintaining an appropriate, standard lamp-to-skin distance is an important practical consideration for safe, effective infrared dosing."},{"id": 5585,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "The cosine law (Lambert's cosine law), as it applies to infrared therapy, states that radiant intensity on a treated surface is greatest when:","options": [{"key": "A","text": "The infrared lamp's rays strike the treatment surface perpendicularly (at a 90-degree angle of incidence)"},{"key": "B","text": "The lamp is always positioned at exactly a 45-degree angle for maximal intensity"},{"key": "C","text": "Angle of the lamp relative to the surface has no bearing on intensity"},{"key": "D","text": "The infrared lamp is positioned at an oblique (angled) orientation to the treatment surface"}],"correct": "A","explanation": "Per the cosine law, radiant intensity on a surface is maximal when the radiation source is oriented perpendicular (90°) to that surface, with intensity decreasing as the angle of incidence becomes more oblique."},{"id": 5586,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following is a significant, well-established contraindication for infrared therapy related to patient sensation?","options": [{"key": "A","text": "Infrared therapy has no relationship to patient sensation or safety considerations"},{"key": "B","text": "Infrared therapy is always completely safe regardless of the patient's sensory status"},{"key": "C","text": "Application over areas of significantly impaired sensation is contraindicated, since the patient's reduced ability to accurately perceive and report excessive heat increases burn risk"},{"key": "D","text": "This consideration is only relevant to deep-heating modalities, never to infrared therapy"}],"correct": "C","explanation": "Since reliable patient-reported sensation of appropriate warmth (and prompt reporting of excessive heat) is a critical safety mechanism for infrared therapy, application over areas of significantly impaired sensation is contraindicated due to increased burn risk."},{"id": 5587,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Infrared therapy is generally contraindicated for application over areas of impaired local circulation primarily due to:","options": [{"key": "A","text": "Infrared therapy is always completely safe regardless of the patient's local circulatory status"},{"key": "B","text": "This consideration is only relevant to deep-heating modalities, never to superficial heating like infrared"},{"key": "C","text": "Compromised circulation impairs the tissue's ability to effectively dissipate heat, increasing the risk of excessive, potentially damaging local temperature rise"},{"key": "D","text": "Impaired circulation has no bearing on infrared therapy safety"}],"correct": "C","explanation": "Since adequate local circulation is important for dissipating heat generated during infrared therapy, significantly compromised circulation increases the risk of excessive, potentially damaging localized temperature rise, making this a recognized contraindication."},{"id": 5588,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Infrared therapy directly over the eyes (without appropriate protection) is generally contraindicated primarily due to:","options": [{"key": "A","text": "Infrared radiation always improves vision when applied directly to the eyes"},{"key": "B","text": "Risk of thermal damage to sensitive ocular structures from direct or excessive infrared exposure"},{"key": "C","text": "No established concern regarding ocular exposure to infrared radiation"},{"key": "D","text": "This precaution is unnecessary since infrared radiation cannot reach the eyes under any circumstances"}],"correct": "B","explanation": "Given the potential for thermal damage to sensitive ocular structures, direct infrared exposure to the eyes without appropriate protection (e.g., protective eyewear/goggles when treating the face) is contraindicated."},{"id": 5589,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following is an appropriate safety practice when infrared therapy is applied to the facial region, given the proximity to the eyes?","options": [{"key": "A","text": "The patient's eyes should be protected (e.g., with appropriate eye coverings/goggles or by keeping the eyes closed with additional protective measures as per protocol) during treatment"},{"key": "B","text": "Facial infrared treatment should never involve any consideration of eye protection"},{"key": "C","text": "No special precautions are needed regardless of proximity to the eyes"},{"key": "D","text": "The patient should always be instructed to look directly at the infrared lamp throughout treatment"}],"correct": "A","explanation": "Given the risk of thermal damage to ocular structures, appropriate eye protection is an important safety practice when applying infrared therapy to the facial region."},{"id": 5590,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Infrared therapy is generally contraindicated over the abdomen/pelvis/lumbar region during pregnancy, consistent with general precautions applied to other heat-producing modalities, primarily due to:","options": [{"key": "A","text": "Infrared therapy is proven to always be completely safe during pregnancy with strong supporting evidence in every clinical context"},{"key": "B","text": "This contraindication only applies to near infrared, never to far infrared"},{"key": "C","text": "No established concern regarding infrared therapy and pregnancy"},{"key": "D","text": "The general precaution regarding potential effects of significant, sustained tissue heating on fetal development, though infrared's more superficial heating profile may involve somewhat different risk considerations than deep-heating modalities"}],"correct": "D","explanation": "Consistent with general precautions applied to heat-producing modalities, caution or contraindication is generally recommended for infrared application over the abdomen/pelvis/lumbar region during pregnancy, though the specific risk profile may differ somewhat from deep-heating modalities given infrared's more superficial heating characteristics."},{"id": 5591,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Infrared therapy is generally contraindicated for application over or near known malignancy primarily due to:","options": [{"key": "A","text": "This contraindication only applies to far infrared, never to near infrared"},{"key": "B","text": "The theoretical concern (applied broadly across many heating/electrotherapy modalities) that increased local blood flow/cellular activity could potentially influence tumor behavior"},{"key": "C","text": "No established concern; this is a baseless precaution"},{"key": "D","text": "Infrared therapy is proven to always cure malignancy with strong supporting evidence"}],"correct": "B","explanation": "Consistent with the general precaution applied across various heating modalities, infrared therapy over known/suspected malignancy is generally avoided due to theoretical concerns about stimulating local blood flow/cellular activity relevant to tumor behavior."},{"id": 5592,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Infrared therapy is generally contraindicated for application over areas of active bleeding/hemorrhage or acute inflammation primarily due to:","options": [{"key": "A","text": "The risk that local heating and increased blood flow could exacerbate bleeding or acute inflammatory processes"},{"key": "B","text": "No established concern regarding these conditions and infrared therapy"},{"key": "C","text": "Infrared therapy always safely stops bleeding with strong supporting evidence"},{"key": "D","text": "This contraindication only applies to deep-heating modalities, never to infrared therapy"}],"correct": "A","explanation": "Since infrared therapy produces local heating and increased superficial blood flow, application over areas of active bleeding or acute inflammation is generally contraindicated due to the risk of exacerbating these conditions."},{"id": 5593,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following is generally considered an appropriate consideration for infrared therapy in patients with significant skin conditions (e.g., dermatitis, significant sunburn) in the treatment area?","options": [{"key": "A","text": "Skin condition has no relevance to infrared therapy treatment planning"},{"key": "B","text": "Caution or avoidance may be warranted, since already compromised/inflamed skin may have altered heat tolerance and be at increased risk of further irritation or damage from additional thermal exposure"},{"key": "C","text": "Infrared therapy is always the recommended first-line treatment for any skin condition regardless of its nature"},{"key": "D","text": "This consideration is only relevant to deep-heating modalities, never to infrared therapy"}],"correct": "B","explanation": "Given the potential for already compromised or inflamed skin to have altered heat tolerance, caution or avoidance of infrared therapy over significant skin conditions in the treatment area is a reasonable clinical consideration."},{"id": 5594,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate skin inspection practice before and during infrared therapy treatment?","options": [{"key": "A","text": "The treatment area should be inspected before treatment for contraindications and periodically monitored during treatment for any excessive redness or discomfort, with prompt adjustment or discontinuation if concerning findings are noted"},{"key": "B","text": "Only the lamp settings need to be checked, never the patient's skin"},{"key": "C","text": "Skin inspection is unnecessary for infrared therapy since it poses no risk of skin reaction/burn"},{"key": "D","text": "Skin inspection is only relevant for deep-heating modalities, never for infrared therapy"}],"correct": "A","explanation": "Pre-treatment and ongoing periodic skin inspection during infrared therapy is an important safety practice, allowing prompt identification and response to any excessive skin reaction during treatment."},{"id": 5595,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes typical treatment duration considerations for a standard infrared therapy session?","options": [{"key": "A","text": "Treatment duration has no bearing on the therapeutic effect or safety of infrared therapy"},{"key": "B","text": "Infrared therapy sessions must always last several hours to achieve any therapeutic effect"},{"key": "C","text": "Treatment duration is always fixed at exactly 1 second regardless of clinical goal"},{"key": "D","text": "Typical treatment durations are commonly cited in ranges of approximately 15-30 minutes, though specific duration may be adjusted based on the clinical goal, lamp distance/intensity, and patient tolerance"}],"correct": "D","explanation": "While specific protocols vary, typical infrared therapy treatment durations are commonly cited in general ranges of approximately 15-30 minutes, with adjustments based on the specific clinical goal, lamp positioning/intensity, and patient tolerance."},{"id": 5596,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate patient positioning consideration during infrared therapy to help ensure safety and consistent dosing?","options": [{"key": "A","text": "Patient positioning has no relevance to infrared therapy treatment safety or effectiveness"},{"key": "B","text": "Patients should always be encouraged to move freely and change position frequently throughout infrared treatment"},{"key": "C","text": "The patient should be positioned comfortably and stably, with the treatment area appropriately exposed and the lamp positioned at the correct distance/angle per guidelines, minimizing risk of inadvertent position changes that could alter the effective dose or increase burn risk"},{"key": "D","text": "Positioning is only relevant for deep-heating modalities, never for infrared therapy"}],"correct": "C","explanation": "Stable, comfortable patient positioning with appropriate lamp distance/angle helps ensure consistent, safe dosing throughout infrared therapy treatment, minimizing risk associated with inadvertent position changes."},{"id": 5597,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best explains why continuous or frequent clinician monitoring is generally recommended during infrared therapy, rather than leaving the patient completely unattended for the entire session?","options": [{"key": "A","text": "Given infrared therapy's reliance on patient-reported sensation as a key safety mechanism and the potential for lamp position to shift or patient position to change during treatment, periodic clinician checking supports prompt identification and response to any developing safety concerns"},{"key": "B","text": "Patients should always be left completely unattended for the duration of infrared treatment with no clinician monitoring"},{"key": "C","text": "Clinician monitoring is only relevant for deep-heating modalities, never for infrared therapy"},{"key": "D","text": "Continuous or frequent monitoring is unnecessary since infrared therapy carries no risk once initial parameters are set"}],"correct": "A","explanation": "Periodic clinician monitoring during infrared therapy supports prompt identification and response to any developing safety concerns (e.g., excessive heat, positional changes), reflecting good safety practice for this modality."},{"id": 5598,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes the general clinical use of infrared therapy as a preparatory modality before other interventions, such as manual therapy or exercise?","options": [{"key": "A","text": "Infrared therapy always eliminates the need for any subsequent manual therapy or exercise intervention"},{"key": "B","text": "This use is unique to far infrared, with no relevance to near infrared"},{"key": "C","text": "Infrared's superficial heating and associated proposed effects (e.g., mild analgesia, increased superficial tissue extensibility, general relaxation) are sometimes utilized as a preparatory step before manual therapy or stretching, similar in principle to other superficial heating options like hot packs"},{"key": "D","text": "Infrared therapy has no established role as a preparatory modality"}],"correct": "C","explanation": "Similar to other superficial heating modalities, infrared therapy's proposed effects (mild analgesia, some increase in superficial extensibility, general relaxation) are sometimes utilized as a preparatory step before manual therapy or stretching interventions."},{"id": 5599,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an important difference between infrared therapy and other superficial heating modalities like hot packs, in terms of the mode of heat transfer?","options": [{"key": "A","text": "Infrared therapy always requires direct skin contact, identical to hot packs"},{"key": "B","text": "Hot packs use radiant heat transfer, while infrared uses conductive heat transfer (the opposite of the correct relationship)"},{"key": "C","text": "Infrared therapy transfers heat via electromagnetic radiation (radiant heat transfer) without requiring direct contact, whereas hot packs transfer heat primarily via conduction, requiring direct contact with the skin"},{"key": "D","text": "Infrared and hot packs use an identical heat transfer mechanism with no meaningful distinction"}],"correct": "C","explanation": "A key distinguishing feature is the heat transfer mechanism: infrared therapy uses radiant heat transfer via electromagnetic radiation without requiring direct contact, while hot packs rely primarily on conductive heat transfer requiring direct skin contact."},{"id": 5600,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes a potential clinical advantage of infrared therapy's non-contact (radiant) heat transfer mechanism compared to contact-based modalities like hot packs, particularly relevant for certain patients?","options": [{"key": "A","text": "Non-contact application may be advantageous for patients where direct contact/pressure is poorly tolerated (e.g., significant skin sensitivity, certain wound presentations, or when direct pressure from a hot pack would be uncomfortable or contraindicated)"},{"key": "B","text": "This consideration is entirely irrelevant to clinical decision-making regarding modality selection"},{"key": "C","text": "Non-contact heat transfer always produces significantly less therapeutic benefit than contact-based heating"},{"key": "D","text": "There is no potential advantage to non-contact heat transfer in any clinical scenario"}],"correct": "A","explanation": "Infrared's non-contact heat delivery may offer a practical advantage for patients where direct contact or pressure (as with a hot pack) would be poorly tolerated or contraindicated, such as certain skin sensitivities or specific wound presentations."},{"id": 5601,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding infrared lamp equipment maintenance and safety checks?","options": [{"key": "A","text": "Equipment safety checks are only relevant for deep-heating modalities, never for infrared therapy"},{"key": "B","text": "Equipment maintenance has no bearing on infrared therapy safety or effectiveness"},{"key": "C","text": "Regular checking of lamp function, secure mounting/positioning mechanisms, and electrical safety is important to ensure consistent, safe treatment delivery and to prevent equipment-related hazards (e.g., lamp falling, electrical malfunction)"},{"key": "D","text": "Infrared lamps never require any maintenance once installed"}],"correct": "C","explanation": "Regular equipment maintenance and safety checks (lamp function, secure positioning mechanisms, electrical safety) are important practical considerations for safe, consistent infrared therapy delivery."},{"id": 5602,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an important documentation practice following infrared therapy treatment?","options": [{"key": "A","text": "Only the total treatment time needs to be recorded, with no other parameters relevant"},{"key": "B","text": "Documentation is unnecessary for infrared therapy since it carries no notable risk profile"},{"key": "C","text": "Infrared therapy documentation should never include information about patient-reported sensation or tolerance"},{"key": "D","text": "Documentation should include lamp type/distance/positioning, treatment duration, patient tolerance/response, and any relevant skin findings, supporting continuity of care and safety monitoring"}],"correct": "D","explanation": "Thorough documentation of infrared therapy application parameters, patient response, and relevant skin findings supports continuity of care and ongoing safety monitoring, reflecting good clinical practice for this modality."},{"id": 5603,"subject": "Electrotherapy","topic": "Ultrasound Therapy","difficulty": "Medium","question": "Which of the following best summarizes an appropriate approach to selecting between infrared therapy and a deep-heating modality (e.g., SWD or ultrasound) when heat is considered a desired therapeutic intervention for a given patient presentation?","options": [{"key": "A","text": "Infrared therapy should always be selected over any deep-heating modality regardless of the target tissue depth"},{"key": "B","text": "Selection should consider the depth of the target tissue/structure requiring therapeutic heating (superficial versus deep), relevant contraindications for each modality, and practical factors, recognizing that infrared is generally most appropriate when a superficial heating effect is the clinical goal"},{"key": "C","text": "Deep-heating modalities should always be selected over infrared therapy regardless of the target tissue depth"},{"key": "D","text": "Infrared and deep-heating modalities are functionally identical, so selection is entirely arbitrary with no meaningful clinical considerations"}],"correct": "B","explanation": "Thoughtful modality selection between infrared therapy and deep-heating options should consider the depth of the target structure requiring therapeutic heating, along with relevant contraindications and practical factors, recognizing infrared's role as an appropriate choice when a superficial heating effect aligns with the clinical goal."},{"id": 5604,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Hard","question": "Which of the following best describes why infrared therapy is generally considered to have a relatively favorable safety profile compared to some deep-heating electromagnetic modalities (e.g., SWD, microwave diathermy), particularly regarding metal implants?","options": [{"key": "A","text": "Metal implants pose an even greater risk with infrared therapy than with SWD or microwave diathermy"},{"key": "B","text": "Since infrared therapy does not rely on the same electromagnetic induction/capacitive mechanisms that create the significant metal-related heating risk associated with SWD and microwave diathermy, metal implants are generally not considered a comparable safety concern for infrared therapy"},{"key": "C","text": "Infrared therapy is completely incapable of producing any heating effect, eliminating all safety considerations entirely"},{"key": "D","text": "Infrared therapy carries an identical, equally significant risk profile regarding metal implants as SWD and microwave diathermy"}],"correct": "B","explanation": "Because infrared therapy's heat transfer mechanism (radiant, largely absorbed at the skin surface) differs fundamentally from the electromagnetic induction/capacitive mechanisms of SWD and microwave diathermy, metal implants do not pose the same significant localized heating risk, contributing to infrared's comparatively more limited contraindication profile in this regard."},{"id": 5605,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate consideration regarding infrared therapy dosing intensity for patients with darker skin pigmentation, given that erythema (redness) is often used as a visual indicator of thermal response?","options": [{"key": "A","text": "Skin pigmentation has no relevance to infrared therapy dosing or monitoring"},{"key": "B","text": "Infrared therapy should never be used in any patient with darker skin pigmentation"},{"key": "C","text": "Erythema is always equally visible regardless of skin pigmentation, so no adjustment in monitoring approach is needed"},{"key": "D","text": "Since erythema may be less visually apparent in darker skin tones, clinicians should place greater reliance on patient-reported sensation and other monitoring methods (e.g., palpation for warmth) rather than relying primarily on visual erythema assessment alone"}],"correct": "D","explanation": "Recognizing that erythema may be less visually apparent in darker skin tones, clinicians should place appropriate emphasis on patient-reported sensation and other monitoring approaches rather than relying primarily on visual erythema assessment when monitoring thermal response during infrared therapy."},{"id": 5606,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes the general relationship between infrared lamp wattage and the appropriate treatment distance/duration for a given therapeutic dose?","options": [{"key": "A","text": "Lamp wattage has no relationship to appropriate treatment distance or duration"},{"key": "B","text": "Higher wattage lamps generally require greater distance and/or shorter duration to achieve a comparable therapeutic intensity compared to lower wattage lamps, reflecting the need to individualize parameters based on the specific equipment being used"},{"key": "C","text": "All infrared lamps, regardless of wattage, should always be used at an identical fixed distance and duration"},{"key": "D","text": "Lower wattage lamps always require greater distance than higher wattage lamps for equivalent dosing"}],"correct": "B","explanation": "Since lamp wattage influences the radiant intensity produced, higher wattage lamps generally require greater treatment distance and/or shorter duration (compared to lower wattage lamps) to achieve a comparable, safe therapeutic dose, highlighting the importance of individualizing parameters to the specific equipment in use."},{"id": 5607,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate approach when a patient reports a burning or excessively hot sensation during infrared therapy?","options": [{"key": "A","text": "Continue treatment at the same parameters, since this sensation is always expected and harmless"},{"key": "B","text": "Immediately increase the lamp distance and/or discontinue treatment, and inspect the treatment area for any signs of excessive heating or skin reaction"},{"key": "C","text": "Increase the lamp intensity further to determine the patient's maximum tolerance"},{"key": "D","text": "Burning sensation should always be ignored unless visible blistering has already occurred"}],"correct": "B","explanation": "A burning or excessively hot sensation warrants immediate adjustment (increasing distance) or discontinuation of treatment, along with prompt inspection of the treatment area, reflecting appropriate priority given to patient safety."},{"id": 5608,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes why infrared therapy is sometimes used clinically as an adjunct for pain management in conditions such as mild musculoskeletal strain, alongside other interventions?","options": [{"key": "A","text": "Infrared's proposed mild analgesic effect, along with its general relaxation and comfort-promoting properties, may provide a modest adjunctive benefit for some patients with mild musculoskeletal discomfort, typically used alongside other evidence-based interventions rather than as a standalone comprehensive treatment"},{"key": "B","text": "Infrared therapy always worsens pain and should never be used for any pain-related condition"},{"key": "C","text": "Infrared therapy has no established role in pain management applications"},{"key": "D","text": "Infrared therapy is proven to be a complete, standalone cure for all types of pain with no need for any other intervention"}],"correct": "A","explanation": "Infrared therapy's proposed mild analgesic and relaxation-promoting effects may offer modest adjunctive benefit for some patients with mild musculoskeletal discomfort, generally used alongside other evidence-based interventions rather than as a standalone treatment."},{"id": 5609,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding infrared therapy use in very young children or elderly patients with potentially thinner or more fragile skin?","options": [{"key": "A","text": "Age has no relevance to infrared therapy safety considerations"},{"key": "B","text": "Infrared therapy should always be applied at maximum intensity regardless of the patient's age or skin characteristics"},{"key": "C","text": "Additional caution regarding appropriate dosing parameters and closer monitoring may be warranted, given the potential for altered skin thickness/sensitivity and thermal tolerance in these populations"},{"key": "D","text": "This consideration is only relevant to deep-heating modalities, never to infrared therapy"}],"correct": "C","explanation": "Given the potential for altered skin characteristics and thermal tolerance in very young or elderly patients, additional caution regarding dosing parameters and closer treatment monitoring may be warranted in these populations."},{"id": 5610,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes the general clinical reasoning process a physiotherapist should apply when considering infrared therapy for a given patient presentation?","options": [{"key": "A","text": "Infrared therapy should be applied to any patient reporting any type of discomfort, without further individualized clinical reasoning"},{"key": "B","text": "Clinical reasoning is unnecessary since all patients respond identically to a single standardized infrared protocol"},{"key": "C","text": "Infrared therapy decisions should be made without considering the patient's specific presentation or relevant medical history"},{"key": "D","text": "A comprehensive clinical reasoning process should include appropriate patient assessment, consideration of contraindications/precautions, individualized parameter selection (lamp type, distance, duration), and integration within a broader treatment plan, along with ongoing evaluation of patient response"}],"correct": "D","explanation": "Sound clinical reasoning for infrared therapy use encompasses thorough assessment, contraindication screening, individualized parameter selection, and integration within the broader treatment plan, reflecting a comprehensive, patient-centered approach."},{"id": 5611,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes why infrared therapy is generally considered a relatively low-risk, accessible modality within many physiotherapy practice settings, compared to some other electrotherapy options?","options": [{"key": "A","text": "Infrared therapy carries no risk whatsoever under any circumstances, eliminating the need for any screening or precautions"},{"key": "B","text": "Infrared therapy is never used in any contemporary physiotherapy practice setting"},{"key": "C","text": "Infrared therapy's relatively simpler underlying mechanism (superficial radiant heating without electromagnetic induction concerns), comparatively more limited contraindication profile (e.g., no significant metal-implant-related risk), and straightforward equipment requirements contribute to its relatively accessible, lower-risk status in many practice settings"},{"key": "D","text": "Infrared therapy carries an equally extensive and severe contraindication profile as deep-heating electromagnetic modalities like SWD"}],"correct": "C","explanation": "Infrared therapy's comparatively simpler mechanism, more limited contraindication profile (particularly regarding metal implants), and straightforward equipment requirements contribute to its relatively accessible, lower-risk status compared to some other electrotherapy modalities, while still requiring appropriate clinical screening and technique."},{"id": 5612,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an appropriate consideration regarding combining infrared therapy with topical products (e.g., liniments, certain creams) applied to the skin before treatment?","options": [{"key": "A","text": "Topical products have no relevance to infrared therapy safety or effectiveness"},{"key": "B","text": "Certain topical products (e.g., some liniments/rubefacients) could potentially interact with the thermal effects of infrared therapy in ways that increase risk of skin irritation or excessive heating sensation, so awareness of any recently applied topical products is a relevant pretreatment consideration"},{"key": "C","text": "All topical products always enhance infrared therapy effectiveness with no associated risk"},{"key": "D","text": "Topical products are only relevant to iontophoresis and phonophoresis, never to infrared therapy"}],"correct": "B","explanation": "Awareness of any topical products recently applied to the treatment area is a relevant pretreatment consideration for infrared therapy, since certain products could potentially interact with thermal effects in ways that increase irritation or excessive heat sensation risk."},{"id": 5613,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best summarizes the overall evidence-based clinical role of infrared therapy within contemporary physiotherapy practice, considering its generally modest, primarily superficial proposed effects?","options": [{"key": "A","text": "Infrared therapy has been definitively proven completely ineffective and has no legitimate role in any clinical context"},{"key": "B","text": "Infrared therapy should never be combined with any other physiotherapy intervention under any circumstances"},{"key": "C","text": "Given its generally modest, primarily superficial proposed physiological effects, infrared therapy is typically considered a minor adjunctive modality (e.g., for preparatory heating or general comfort) rather than a primary treatment intervention, and should be integrated thoughtfully within a broader, evidence-based treatment plan that includes interventions with generally stronger supporting evidence, such as exercise"},{"key": "D","text": "Infrared therapy should always be considered a primary, essential intervention for every musculoskeletal condition, given overwhelming and conclusive supporting evidence for significant therapeutic benefit"}],"correct": "C","explanation": "Reflecting its generally modest, primarily superficial proposed effects, infrared therapy is typically best considered a minor adjunctive modality within a broader, evidence-based treatment plan, rather than a primary treatment strategy on its own."},{"id": 5614,"subject": "Electrotherapy","topic": "Thermotherapy","difficulty": "Medium","question": "Which of the following best describes an important practical consideration regarding infrared lamp cord/equipment placement in the treatment area, related to general electrical and patient safety?","options": [{"key": "A","text": "Cords should always be placed directly across walkways for convenience, regardless of any tripping hazard"},{"key": "B","text": "Electrical safety considerations are irrelevant to infrared therapy equipment specifically"},{"key": "C","text": "Cords and equipment should be positioned to avoid tripping hazards and should be kept away from any water sources or areas where they could pose an electrical safety risk, consistent with general electrical safety practices in the clinical environment"},{"key": "D","text": "Cord and equipment placement has no relevance to patient or clinician safety"}],"correct": "C","explanation": "Appropriate placement of infrared lamp cords and equipment to avoid tripping hazards and electrical safety risks (e.g., proximity to water) reflects general good practice for safe clinical equipment use in the treatment environment."},{"id": 5615,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Easy","question": "The primary motor cortex is located in which region?","options": [{"key": "A","text": "Precentral gyrus of frontal lobe"},{"key": "B","text": "Postcentral gyrus of parietal lobe"},{"key": "C","text": "Occipital lobe"},{"key": "D","text": "Superior temporal gyrus"}],"correct": "A","explanation": "Primary motor cortex (Brodmann area 4) lies in the precentral gyrus, controlling voluntary movement."},{"id": 5616,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "The primary somatosensory cortex is located in which region?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Temporal lobe"},{"key": "C","text": "Precentral gyrus of frontal lobe"},{"key": "D","text": "Postcentral gyrus of parietal lobe"}],"correct": "D","explanation": "Primary somatosensory cortex (Brodmann areas 3,1,2) lies in the postcentral gyrus, processing sensory information."},{"id": 5617,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "The 'homunculus' representation on the motor cortex shows which body part with disproportionately large representation?","options": [{"key": "A","text": "Thigh"},{"key": "B","text": "Trunk"},{"key": "C","text": "Hand and face"},{"key": "D","text": "Upper arm"}],"correct": "C","explanation": "The motor homunculus shows disproportionately large representation for hand and face, reflecting fine motor control needs."},{"id": 5618,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Broca's area, responsible for speech production, is located in which lobe?","options": [{"key": "A","text": "Frontal lobe (inferior frontal gyrus)"},{"key": "B","text": "Temporal lobe"},{"key": "C","text": "Parietal lobe"},{"key": "D","text": "Occipital lobe"}],"correct": "A","explanation": "Broca's area is located in the posterior inferior frontal gyrus, typically in the dominant (usually left) hemisphere."},{"id": 5619,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Wernicke's area, involved in language comprehension, is located in which lobe?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Occipital lobe"},{"key": "C","text": "Frontal lobe"},{"key": "D","text": "Superior temporal gyrus (temporal lobe)"}],"correct": "D","explanation": "Wernicke's area lies in the posterior superior temporal gyrus, typically dominant hemisphere, responsible for language comprehension."},{"id": 5620,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The corticospinal tract primarily controls:","options": [{"key": "A","text": "Sensory processing"},{"key": "B","text": "Autonomic function"},{"key": "C","text": "Voluntary skilled movement of limbs"},{"key": "D","text": "Balance and posture only"}],"correct": "C","explanation": "The corticospinal (pyramidal) tract is the principal pathway for voluntary, skilled limb movement."},{"id": 5621,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Where does the majority of corticospinal tract fibers decussate (cross)?","options": [{"key": "A","text": "Pons"},{"key": "B","text": "Within the spinal cord at each segment"},{"key": "C","text": "Pyramidal decussation at the medulla-spinal cord junction"},{"key": "D","text": "Midbrain"}],"correct": "C","explanation": "Approximately 85-90% of corticospinal fibers cross at the pyramidal decussation in the lower medulla, forming the lateral corticospinal tract."},{"id": 5622,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The anterior (ventral) corticospinal tract, which does not decussate at the medulla, crosses at which level?","options": [{"key": "A","text": "At the level of the spinal segment it innervates"},{"key": "B","text": "At the midbrain"},{"key": "C","text": "Never crosses"},{"key": "D","text": "At the level of C1 only"}],"correct": "A","explanation": "The uncrossed anterior corticospinal tract fibers decussate at the specific spinal cord segment level near their termination."},{"id": 5623,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The spinothalamic tract is primarily responsible for carrying which sensory modality?","options": [{"key": "A","text": "Vibration sense"},{"key": "B","text": "Two-point discrimination"},{"key": "C","text": "Pain and temperature"},{"key": "D","text": "Fine touch and proprioception"}],"correct": "C","explanation": "The (anterolateral) spinothalamic tract carries pain and temperature sensation, decussating near the level of entry."},{"id": 5624,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The dorsal column-medial lemniscus pathway carries which sensory modalities?","options": [{"key": "A","text": "Only crude touch"},{"key": "B","text": "Pain and temperature"},{"key": "C","text": "Fine touch, proprioception, and vibration sense"},{"key": "D","text": "Autonomic sensation"}],"correct": "C","explanation": "Dorsal columns carry fine touch, vibration, and proprioception, ascending ipsilaterally before decussating at the medulla (as the medial lemniscus)."},{"id": 5625,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Damage to the dorsal columns would primarily result in loss of:","options": [{"key": "A","text": "Pain and temperature on the opposite side"},{"key": "B","text": "Motor function only"},{"key": "C","text": "Proprioception and vibration sense on the same side below the lesion"},{"key": "D","text": "Autonomic function only"}],"correct": "C","explanation": "Dorsal column pathway is ipsilateral until the medulla; lesions cause ipsilateral loss of proprioception/vibration below the lesion level."},{"id": 5626,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Brown-Sequard syndrome (spinal cord hemisection) classically presents with:","options": [{"key": "A","text": "Only motor loss without sensory changes"},{"key": "B","text": "Ipsilateral motor/proprioceptive loss and contralateral pain/temperature loss below the lesion"},{"key": "C","text": "Bilateral symmetric loss of all modalities"},{"key": "D","text": "Only sensory loss without motor changes"}],"correct": "B","explanation": "Hemisection affects ipsilateral corticospinal (motor) and dorsal column pathways, while spinothalamic fibers (already crossed) cause contralateral pain/temperature loss."},{"id": 5627,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The cerebellum primarily functions to:","options": [{"key": "A","text": "Control higher cognitive language function"},{"key": "B","text": "Process primary sensory information"},{"key": "C","text": "Initiate voluntary movement"},{"key": "D","text": "Coordinate movement, balance, and motor learning"}],"correct": "D","explanation": "Cerebellum coordinates movement timing/accuracy, maintains balance, and contributes to motor learning, without initiating voluntary movement itself."},{"id": 5628,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Cerebellar lesions typically produce symptoms on which side of the body?","options": [{"key": "A","text": "No lateralization occurs"},{"key": "B","text": "Ipsilateral side"},{"key": "C","text": "Bilateral always"},{"key": "D","text": "Contralateral side"}],"correct": "B","explanation": "Unlike cerebral lesions, cerebellar lesions produce ipsilateral signs due to double decussation of cerebellar pathways."},{"id": 5629,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Hard","question": "The basal ganglia are primarily involved in:","options": [{"key": "A","text": "Balance exclusively, unrelated to movement initiation"},{"key": "B","text": "Primary sensory processing"},{"key": "C","text": "Regulation and modulation of voluntary movement, particularly initiation and smoothness"},{"key": "D","text": "Direct muscle contraction control"}],"correct": "C","explanation": "Basal ganglia circuits modulate cortical motor output, playing key roles in movement initiation, smoothness, and suppression of unwanted movement."},{"id": 5630,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "Which basal ganglia structure shows characteristic dopaminergic neuron loss in Parkinson's disease?","options": [{"key": "A","text": "Putamen exclusively"},{"key": "B","text": "Globus pallidus externus exclusively"},{"key": "C","text": "Substantia nigra pars compacta"},{"key": "D","text": "Caudate nucleus"}],"correct": "C","explanation": "Parkinson's disease is characterized by degeneration of dopaminergic neurons in the substantia nigra pars compacta."},{"id": 5631,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The thalamus functions primarily as:","options": [{"key": "A","text": "The center for balance exclusively"},{"key": "B","text": "A relay station for sensory (and some motor) information to the cortex"},{"key": "C","text": "The primary language processing center"},{"key": "D","text": "The primary site of motor initiation"}],"correct": "B","explanation": "Thalamus relays and processes sensory information (and basal ganglia/cerebellar output) en route to the cerebral cortex."},{"id": 5632,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The hypothalamus primarily regulates:","options": [{"key": "A","text": "Language production"},{"key": "B","text": "Voluntary motor control"},{"key": "C","text": "Primary sensory processing"},{"key": "D","text": "Autonomic function, temperature, and endocrine control via pituitary"}],"correct": "D","explanation": "Hypothalamus regulates autonomic nervous system function, body temperature, and hormonal control via the pituitary gland."},{"id": 5633,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The reticular activating system, located in the brainstem, is primarily responsible for:","options": [{"key": "A","text": "Language comprehension"},{"key": "B","text": "Primary visual processing"},{"key": "C","text": "Fine motor coordination"},{"key": "D","text": "Maintaining arousal/consciousness and sleep-wake regulation"}],"correct": "D","explanation": "RAS regulates the sleep-wake cycle and overall level of consciousness/arousal."},{"id": 5634,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which cranial nerve is responsible for eye movement, specifically superior oblique muscle innervation?","options": [{"key": "A","text": "Abducens nerve (CN VI)"},{"key": "B","text": "Trochlear nerve (CN IV)"},{"key": "C","text": "Trigeminal nerve (CN V)"},{"key": "D","text": "Oculomotor nerve (CN III)"}],"correct": "B","explanation": "CN IV (trochlear) innervates the superior oblique muscle, controlling intorsion and downward gaze when adducted."},{"id": 5635,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which cranial nerve innervates the lateral rectus muscle for eye abduction?","options": [{"key": "A","text": "Facial nerve (CN VII)"},{"key": "B","text": "Trochlear nerve (CN IV)"},{"key": "C","text": "Abducens nerve (CN VI)"},{"key": "D","text": "Oculomotor nerve (CN III)"}],"correct": "C","explanation": "CN VI (abducens) innervates the lateral rectus muscle, responsible for eye abduction."},{"id": 5636,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The facial nerve (CN VII) is responsible for which functions?","options": [{"key": "A","text": "Muscles of mastication"},{"key": "B","text": "Tongue movement"},{"key": "C","text": "Facial expression muscles, taste (anterior 2/3 tongue), and parasympathetic secretomotor function"},{"key": "D","text": "Facial sensation only"}],"correct": "C","explanation": "CN VII controls facial expression muscles, carries taste sensation from the anterior tongue, and provides parasympathetic innervation to lacrimal/salivary glands."},{"id": 5637,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The trigeminal nerve (CN V) is primarily responsible for:","options": [{"key": "A","text": "Eye movement"},{"key": "B","text": "Facial expression muscles"},{"key": "C","text": "Taste sensation"},{"key": "D","text": "Facial sensation and muscles of mastication"}],"correct": "D","explanation": "CN V provides facial sensation (three divisions) and motor innervation to the muscles of mastication."},{"id": 5638,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The vestibulocochlear nerve (CN VIII) is responsible for:","options": [{"key": "A","text": "Hearing and balance/vestibular function"},{"key": "B","text": "Taste sensation"},{"key": "C","text": "Eye movement"},{"key": "D","text": "Facial movement"}],"correct": "A","explanation": "CN VIII carries auditory and vestibular (balance) information from the inner ear to the brainstem."},{"id": 5639,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The vagus nerve (CN X) provides parasympathetic innervation to which organs?","options": [{"key": "A","text": "Only skeletal muscle"},{"key": "B","text": "Only the skin"},{"key": "C","text": "Most thoracic and abdominal viscera (heart, lungs, GI tract)"},{"key": "D","text": "Only the eye"}],"correct": "C","explanation": "CN X provides extensive parasympathetic innervation to thoracic and abdominal organs, along with motor/sensory functions in the pharynx/larynx."},{"id": 5640,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The hypoglossal nerve (CN XII) is responsible for:","options": [{"key": "A","text": "Facial expression"},{"key": "B","text": "Swallowing sensation"},{"key": "C","text": "Tongue movement (intrinsic and most extrinsic muscles)"},{"key": "D","text": "Eye movement"}],"correct": "C","explanation": "CN XII innervates the tongue muscles, controlling its movement essential for speech and swallowing."},{"id": 5641,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The upper motor neuron (UMN) lesion typically presents with which combination of signs?","options": [{"key": "A","text": "Flaccidity, hyporeflexia, and fasciculations"},{"key": "B","text": "Normal tone with weakness only"},{"key": "C","text": "Only sensory loss without motor signs"},{"key": "D","text": "Spasticity, hyperreflexia, and Babinski sign present"}],"correct": "D","explanation": "UMN lesions classically show increased tone (spasticity), hyperreflexia, and pathological reflexes like Babinski sign."},{"id": 5642,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Lower motor neuron (LMN) lesion typically presents with which combination of signs?","options": [{"key": "A","text": "Babinski sign present"},{"key": "B","text": "Spasticity and hyperreflexia"},{"key": "C","text": "Flaccidity, hyporeflexia/areflexia, fasciculations, and muscle atrophy"},{"key": "D","text": "Increased tone with normal reflexes"}],"correct": "C","explanation": "LMN lesions show flaccid weakness, reduced/absent reflexes, fasciculations, and significant muscle wasting due to direct denervation."},{"id": 5643,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A resting membrane potential of a typical neuron is approximately:","options": [{"key": "A","text": "-70mV"},{"key": "B","text": "+30mV"},{"key": "C","text": "-200mV"},{"key": "D","text": "0mV"}],"correct": "A","explanation": "Neuronal resting membrane potential is typically around -70mV, maintained by ion gradients and the Na+/K+ pump."},{"id": 5644,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Depolarization of a neuron primarily results from which ion influx?","options": [{"key": "A","text": "Sodium (Na+) influx"},{"key": "B","text": "Chloride (Cl-) influx"},{"key": "C","text": "Potassium (K+) influx"},{"key": "D","text": "Calcium (Ca2+) efflux"}],"correct": "A","explanation": "Rapid Na+ influx through voltage-gated channels drives the depolarization phase of the action potential."},{"id": 5645,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Repolarization of the neuronal action potential primarily results from:","options": [{"key": "A","text": "Chloride (Cl-) influx"},{"key": "B","text": "Potassium (K+) efflux"},{"key": "C","text": "Calcium (Ca2+) influx"},{"key": "D","text": "Sodium (Na+) influx"}],"correct": "B","explanation": "K+ efflux through voltage-gated potassium channels restores the negative membrane potential during repolarization."},{"id": 5646,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Saltatory conduction refers to:","options": [{"key": "A","text": "Slow conduction in unmyelinated fibers"},{"key": "B","text": "Retrograde conduction along the axon"},{"key": "C","text": "Action potential 'jumping' between nodes of Ranvier in myelinated axons, increasing conduction velocity"},{"key": "D","text": "Conduction that occurs only in the cell body"}],"correct": "C","explanation": "Saltatory conduction, occurring in myelinated fibers, allows the action potential to jump between nodes of Ranvier, significantly speeding conduction."},{"id": 5647,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which type of nerve fiber conducts impulses fastest?","options": [{"key": "A","text": "Fibers without any myelin regardless of diameter"},{"key": "B","text": "Fiber diameter has no effect on conduction velocity"},{"key": "C","text": "Small diameter, unmyelinated fibers (C fibers)"},{"key": "D","text": "Large diameter, heavily myelinated fibers (e.g., A-alpha)"}],"correct": "D","explanation": "Conduction velocity increases with fiber diameter and myelination; A-alpha fibers (proprioception, motor) are the fastest conducting."},{"id": 5648,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "C fibers, which are unmyelinated and slow-conducting, primarily carry which sensory modality?","options": [{"key": "A","text": "Fine touch and vibration"},{"key": "B","text": "Motor efferent signals"},{"key": "C","text": "Fast, sharp pain and proprioception"},{"key": "D","text": "Dull, aching pain and temperature"}],"correct": "D","explanation": "C fibers are small, unmyelinated fibers conducting slow, dull/aching pain and temperature sensation."},{"id": 5649,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "A-delta fibers, thinly myelinated, primarily carry which type of pain sensation?","options": [{"key": "A","text": "Fine touch exclusively"},{"key": "B","text": "Fast, sharp, well-localized pain"},{"key": "C","text": "Motor signals exclusively"},{"key": "D","text": "Slow, dull, poorly-localized pain"}],"correct": "B","explanation": "A-delta fibers are responsible for the rapid, sharp 'first pain' sensation, being thinly myelinated for faster conduction than C fibers."},{"id": 5650,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The neuromuscular junction utilizes which neurotransmitter for signal transmission?","options": [{"key": "A","text": "GABA"},{"key": "B","text": "Dopamine"},{"key": "C","text": "Serotonin"},{"key": "D","text": "Acetylcholine"}],"correct": "D","explanation": "Acetylcholine is released from motor neuron terminals at the neuromuscular junction, binding nicotinic receptors on muscle fibers to trigger contraction."},{"id": 5651,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Myasthenia gravis results from autoimmune attack on which structure?","options": [{"key": "A","text": "Presynaptic calcium channels"},{"key": "B","text": "Postsynaptic acetylcholine receptors at the neuromuscular junction"},{"key": "C","text": "Motor neuron cell body"},{"key": "D","text": "Muscle spindle"}],"correct": "B","explanation": "MG involves antibodies against postsynaptic nicotinic acetylcholine receptors, impairing neuromuscular transmission."},{"id": 5652,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Lambert-Eaton myasthenic syndrome differs from myasthenia gravis in that it involves antibodies against:","options": [{"key": "A","text": "Presynaptic voltage-gated calcium channels"},{"key": "B","text": "Postsynaptic acetylcholine receptors"},{"key": "C","text": "Muscle spindle fibers"},{"key": "D","text": "Motor neuron cell bodies"}],"correct": "A","explanation": "LEMS involves autoantibodies against presynaptic voltage-gated calcium channels, impairing acetylcholine release, often paraneoplastic."},{"id": 5653,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Muscle spindles are primarily responsible for detecting:","options": [{"key": "A","text": "Muscle length and rate of length change"},{"key": "B","text": "Joint position exclusively"},{"key": "C","text": "Skin pressure"},{"key": "D","text": "Muscle tension/force"}],"correct": "A","explanation": "Muscle spindles are intrafusal fiber-based stretch receptors, sensing muscle length and the velocity of length change."},{"id": 5654,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Golgi tendon organs are primarily responsible for detecting:","options": [{"key": "A","text": "Joint position exclusively"},{"key": "B","text": "Muscle length"},{"key": "C","text": "Muscle tension/force during contraction"},{"key": "D","text": "Skin vibration"}],"correct": "C","explanation": "GTOs, located at the musculotendinous junction, detect tension generated during muscle contraction, providing autogenic inhibition feedback."},{"id": 5655,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Easy","question": "The stretch reflex (myotatic reflex) is mediated by which type of afferent fiber from the muscle spindle?","options": [{"key": "A","text": "A-delta fibers"},{"key": "B","text": "Ia afferent fibers (primary spindle afferents)"},{"key": "C","text": "C fibers"},{"key": "D","text": "Ib afferent fibers (from GTO)"}],"correct": "B","explanation": "The monosynaptic stretch reflex is mediated by Ia afferents from muscle spindle primary endings, synapsing directly onto alpha motor neurons."},{"id": 5656,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "The autogenic inhibition reflex (from Golgi tendon organ activation) is mediated by which afferent fibers, producing which effect?","options": [{"key": "A","text": "Ib afferents, causing inhibition of the agonist muscle (protective reflex)"},{"key": "B","text": "C fibers, causing pain sensation only"},{"key": "C","text": "Ia afferents, causing excitation of the agonist"},{"key": "D","text": "A-delta fibers, causing withdrawal reflex"}],"correct": "A","explanation": "Ib afferents from GTOs typically produce disynaptic inhibition of the same muscle, protecting against excessive tension (autogenic inhibition)."},{"id": 5657,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Reciprocal inhibition refers to the neurological phenomenon where:","options": [{"key": "A","text": "Both agonist and antagonist contract simultaneously always"},{"key": "B","text": "Contraction of an agonist muscle is accompanied by relaxation/inhibition of its antagonist"},{"key": "C","text": "Applies only to postural muscles"},{"key": "D","text": "Only sensory neurons are involved, no motor effect"}],"correct": "B","explanation": "Reciprocal inhibition allows smooth coordinated movement by inhibiting the antagonist when the agonist contracts, mediated by Ia inhibitory interneurons."},{"id": 5658,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The blood-brain barrier is primarily formed by:","options": [{"key": "A","text": "Tight junctions between cerebral capillary endothelial cells"},{"key": "B","text": "Only astrocyte cell bodies without endothelial involvement"},{"key": "C","text": "Loose junctions allowing free molecule passage"},{"key": "D","text": "Only the meninges"}],"correct": "A","explanation": "Tight junctions between endothelial cells of cerebral capillaries form the primary structural basis of the blood-brain barrier, regulating substance passage."},{"id": 5659,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Cerebrospinal fluid (CSF) is primarily produced by:","options": [{"key": "A","text": "Dura mater"},{"key": "B","text": "Arachnoid villi"},{"key": "C","text": "Pia mater"},{"key": "D","text": "Choroid plexus"}],"correct": "D","explanation": "CSF is produced mainly by the choroid plexus within the brain's ventricles."},{"id": 5660,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "CSF is primarily reabsorbed into venous circulation via:","options": [{"key": "A","text": "Arachnoid villi/granulations"},{"key": "B","text": "Dura mater directly"},{"key": "C","text": "Choroid plexus"},{"key": "D","text": "Pia mater directly"}],"correct": "A","explanation": "Arachnoid villi/granulations allow CSF reabsorption into the venous sinuses (particularly the superior sagittal sinus)."},{"id": 5661,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The middle cerebral artery predominantly supplies which brain regions?","options": [{"key": "A","text": "Occipital lobe primarily"},{"key": "B","text": "Cerebellum primarily"},{"key": "C","text": "Lateral surface of frontal, parietal, and temporal lobes"},{"key": "D","text": "Medial frontal and parietal lobes"}],"correct": "C","explanation": "MCA supplies the majority of the lateral cerebral hemisphere surface, including areas critical for motor, sensory, and language function."},{"id": 5662,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The anterior cerebral artery predominantly supplies which brain region, important for lower limb motor/sensory function?","options": [{"key": "A","text": "Occipital lobe"},{"key": "B","text": "Lateral temporal lobe"},{"key": "C","text": "Cerebellum"},{"key": "D","text": "Medial surface of frontal and parietal lobes"}],"correct": "D","explanation": "ACA supplies the medial cerebral surface, corresponding to the lower limb representation in the motor/sensory homunculus."},{"id": 5663,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The posterior cerebral artery predominantly supplies which region, important for visual processing?","options": [{"key": "A","text": "Temporal lobe laterally"},{"key": "B","text": "Parietal lobe laterally"},{"key": "C","text": "Frontal lobe"},{"key": "D","text": "Occipital lobe"}],"correct": "D","explanation": "PCA primarily supplies the occipital lobe (visual cortex) and parts of the temporal lobe."},{"id": 5664,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The circle of Willis provides which important function in cerebral circulation?","options": [{"key": "A","text": "CSF production"},{"key": "B","text": "Collateral blood flow/anastomosis between major cerebral arteries"},{"key": "C","text": "Blood-brain barrier formation"},{"key": "D","text": "Direct venous drainage of the brain"}],"correct": "B","explanation": "Circle of Willis connects anterior and posterior cerebral circulation, providing potential collateral flow if one vessel is compromised."},{"id": 5665,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The spinal cord typically terminates (conus medullaris) at approximately which vertebral level in adults?","options": [{"key": "A","text": "C7"},{"key": "B","text": "S1-S2"},{"key": "C","text": "T12 exclusively"},{"key": "D","text": "L1-L2"}],"correct": "D","explanation": "The adult spinal cord conus medullaris typically ends around the L1-L2 vertebral level, with the cauda equina continuing below."},{"id": 5666,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The cauda equina consists of:","options": [{"key": "A","text": "Cranial nerve roots exclusively"},{"key": "B","text": "The spinal cord itself continuing to S5"},{"key": "C","text": "Only cervical nerve roots"},{"key": "D","text": "Lumbar and sacral nerve roots extending below the conus medullaris"}],"correct": "D","explanation": "Cauda equina ('horse's tail') comprises the lumbosacral nerve roots that continue within the spinal canal below the conus medullaris."},{"id": 5667,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "An extradural (epidural) hematoma classically results from injury to which vessel?","options": [{"key": "A","text": "Cerebral venous sinuses primarily"},{"key": "B","text": "Bridging veins"},{"key": "C","text": "Middle meningeal artery"},{"key": "D","text": "Circle of Willis vessels"}],"correct": "C","explanation": "Epidural hematoma classically results from middle meningeal artery injury, often associated with temporal bone fracture."},{"id": 5668,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A subdural hematoma classically results from injury to which vessel?","options": [{"key": "A","text": "Bridging veins"},{"key": "B","text": "Vertebral artery"},{"key": "C","text": "Middle meningeal artery"},{"key": "D","text": "Anterior cerebral artery"}],"correct": "A","explanation": "Subdural hematomas typically result from tearing of bridging veins between the dura and brain surface, often from acceleration-deceleration injury."},{"id": 5669,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "A neuron's axon hillock is significant because it:","options": [{"key": "A","text": "Is where synapses primarily occur"},{"key": "B","text": "Is the site of action potential initiation due to high density of voltage-gated sodium channels"},{"key": "C","text": "Contains the nucleus"},{"key": "D","text": "Has no functional significance"}],"correct": "B","explanation": "The axon hillock has the lowest threshold for action potential generation due to a high density of voltage-gated Na+ channels."},{"id": 5670,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "Which neurotransmitter is primarily deficient in Parkinson's disease?","options": [{"key": "A","text": "Serotonin"},{"key": "B","text": "GABA"},{"key": "C","text": "Acetylcholine"},{"key": "D","text": "Dopamine"}],"correct": "D","explanation": "Parkinson's disease results from progressive loss of dopaminergic neurons, causing dopamine deficiency in the nigrostriatal pathway."},{"id": 5671,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "GABA is the primary neurotransmitter involved in which type of synaptic activity?","options": [{"key": "A","text": "Excitatory synaptic transmission exclusively"},{"key": "B","text": "Neuromuscular transmission exclusively"},{"key": "C","text": "Sensory transduction exclusively"},{"key": "D","text": "Inhibitory synaptic transmission"}],"correct": "D","explanation": "GABA (gamma-aminobutyric acid) is the principal inhibitory neurotransmitter in the central nervous system."},{"id": 5672,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Glutamate is the primary neurotransmitter involved in which type of synaptic activity?","options": [{"key": "A","text": "Excitatory synaptic transmission"},{"key": "B","text": "Autonomic transmission exclusively"},{"key": "C","text": "Inhibitory synaptic transmission exclusively"},{"key": "D","text": "Neuromuscular transmission exclusively"}],"correct": "A","explanation": "Glutamate is the principal excitatory neurotransmitter in the central nervous system."},{"id": 5673,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The autonomic nervous system is divided into which two main divisions?","options": [{"key": "A","text": "Afferent and efferent only"},{"key": "B","text": "Cranial and spinal only"},{"key": "C","text": "Somatic and central"},{"key": "D","text": "Sympathetic and parasympathetic"}],"correct": "D","explanation": "ANS comprises sympathetic (fight-or-flight) and parasympathetic (rest-and-digest) divisions, working antagonistically to regulate visceral function."},{"id": 5674,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Neuroplasticity refers to the nervous system's ability to:","options": [{"key": "A","text": "Remain completely fixed and unchangeable after development"},{"key": "B","text": "Only regenerate peripheral nerves, never central pathways"},{"key": "C","text": "Only occur during infancy"},{"key": "D","text": "Reorganize and adapt structurally/functionally in response to experience or injury"}],"correct": "D","explanation": "Neuroplasticity describes the CNS's capacity for structural and functional reorganization, forming the basis for motor learning and recovery after injury, occurring throughout life though more prominent in development."},{"id": 5675,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Easy","question": "The Modified Ashworth Scale grades muscle tone from:","options": [{"key": "A","text": "0 to 10"},{"key": "B","text": "0 to 100"},{"key": "C","text": "0 to 4"},{"key": "D","text": "1 to 5"}],"correct": "C","explanation": "Modified Ashworth Scale grades spasticity/resistance to passive stretch from 0 (no increase in tone) to 4 (rigid in flexion/extension)."},{"id": 5676,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "A Modified Ashworth Scale grade of '1+' indicates:","options": [{"key": "A","text": "Considerable increase in tone, passive movement difficult"},{"key": "B","text": "Rigid limb in flexion or extension"},{"key": "C","text": "Slight increase in tone with catch followed by minimal resistance through remainder of ROM"},{"key": "D","text": "No increase in tone"}],"correct": "C","explanation": "Grade 1+ describes a catch followed by minimal resistance through the remaining range, distinguishing it from simple Grade 1."},{"id": 5677,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Hypotonia (reduced muscle tone) is typically associated with which type of lesion?","options": [{"key": "A","text": "Lower motor neuron or cerebellar lesion"},{"key": "B","text": "Never occurs in neurological conditions"},{"key": "C","text": "Basal ganglia lesion causing rigidity"},{"key": "D","text": "Upper motor neuron lesion"}],"correct": "A","explanation": "Hypotonia is classically associated with LMN lesions, cerebellar disease, or acute/spinal shock phase of UMN lesions."},{"id": 5678,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Rigidity, as seen in Parkinson's disease, is characterized by:","options": [{"key": "A","text": "Absent resistance to passive movement"},{"key": "B","text": "Only present at end range"},{"key": "C","text": "Resistance that increases with movement velocity (spasticity)"},{"key": "D","text": "Increased resistance to passive movement throughout the range, velocity-independent"}],"correct": "D","explanation": "Rigidity is velocity-independent resistance present throughout the range of passive movement, distinguishing it from velocity-dependent spasticity."},{"id": 5679,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "'Cogwheel rigidity' refers to:","options": [{"key": "A","text": "Resistance only at the beginning of range"},{"key": "B","text": "A ratchet-like, jerky quality of resistance during passive movement, often with superimposed tremor"},{"key": "C","text": "Complete absence of resistance"},{"key": "D","text": "Smooth uniform resistance throughout range"}],"correct": "B","explanation": "Cogwheel rigidity describes the characteristic jerky resistance pattern seen in Parkinson's disease, thought to result from superimposed tremor on lead-pipe rigidity."},{"id": 5680,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "'Lead-pipe rigidity' refers to:","options": [{"key": "A","text": "Smooth, uniform resistance throughout the range of passive movement"},{"key": "B","text": "No resistance at all"},{"key": "C","text": "Resistance that varies with movement speed"},{"key": "D","text": "Jerky, ratchet-like resistance"}],"correct": "A","explanation": "Lead-pipe rigidity describes uniform resistance throughout range, without the superimposed jerkiness of cogwheel rigidity."},{"id": 5681,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Spasticity is best described as:","options": [{"key": "A","text": "A feature exclusively of LMN lesions"},{"key": "B","text": "Reduced muscle tone"},{"key": "C","text": "Velocity-dependent increase in resistance to passive stretch, part of UMN syndrome"},{"key": "D","text": "Velocity-independent resistance throughout range"}],"correct": "C","explanation": "Spasticity is a velocity-dependent increase in tonic stretch reflexes, a hallmark feature of upper motor neuron syndrome."},{"id": 5682,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "Deep tendon reflexes are graded on a scale typically from:","options": [{"key": "A","text": "0 to 4+"},{"key": "B","text": "No standard grading exists"},{"key": "C","text": "0 to 10"},{"key": "D","text": "1 to 3 only"}],"correct": "A","explanation": "DTRs are conventionally graded 0 (absent) to 4+ (hyperreflexic with clonus)."},{"id": 5683,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Clonus, a rhythmic involuntary muscle contraction elicited by sudden stretch, is indicative of:","options": [{"key": "A","text": "Lower motor neuron lesion"},{"key": "B","text": "Cerebellar dysfunction specifically"},{"key": "C","text": "Normal physiological finding in all individuals"},{"key": "D","text": "Upper motor neuron lesion with hyperreflexia"}],"correct": "D","explanation": "Sustained clonus (particularly at the ankle) is a classic sign of UMN pathology with hyperexcitable stretch reflexes."},{"id": 5684,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The Babinski sign (extensor plantar response) is elicited by:","options": [{"key": "A","text": "Tapping the patellar tendon"},{"key": "B","text": "Passive dorsiflexion of the ankle"},{"key": "C","text": "Percussion over the tibial nerve"},{"key": "D","text": "Stroking the lateral sole of the foot from heel to toe"}],"correct": "D","explanation": "Babinski's test involves stroking the lateral plantar surface; a positive response (great toe extension, fanning of other toes) indicates UMN pathology in adults."},{"id": 5685,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "A positive Babinski sign in an adult indicates:","options": [{"key": "A","text": "Normal physiological finding"},{"key": "B","text": "Lower motor neuron lesion"},{"key": "C","text": "Upper motor neuron lesion"},{"key": "D","text": "Peripheral nerve injury exclusively"}],"correct": "C","explanation": "Positive Babinski (extensor plantar response) beyond infancy indicates corticospinal tract (UMN) pathology."},{"id": 5686,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Hoffman's sign, another indicator of UMN pathology in the upper limb, is elicited by:","options": [{"key": "A","text": "Tapping the biceps tendon"},{"key": "B","text": "Passive wrist extension"},{"key": "C","text": "Stroking the palm"},{"key": "D","text": "Flicking the terminal phalanx of the middle finger and observing thumb/index finger flexion"}],"correct": "D","explanation": "A positive Hoffman's sign (thumb/index finger flexion response) suggests cervical myelopathy or other UMN pathology."},{"id": 5687,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "The Glasgow Coma Scale (GCS) assesses which three components?","options": [{"key": "A","text": "Only pupillary reaction"},{"key": "B","text": "Eye opening, verbal response, motor response"},{"key": "C","text": "Reflexes, tone, and coordination"},{"key": "D","text": "Only motor response"}],"correct": "B","explanation": "GCS scores eye opening (1-4), verbal response (1-5), and motor response (1-6), totaling 3-15, assessing level of consciousness."},{"id": 5688,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A GCS score of 8 or below is generally considered to indicate:","options": [{"key": "A","text": "Only relevant for spinal cord injury assessment"},{"key": "B","text": "No significant neurological impairment"},{"key": "C","text": "Severe brain injury/coma requiring urgent airway management consideration"},{"key": "D","text": "Mild brain injury"}],"correct": "C","explanation": "GCS ≤8 is classically used as a threshold indicating severe impairment of consciousness, often warranting airway protection consideration."},{"id": 5689,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Hard","question": "Cranial nerve testing of pupillary light reflex primarily assesses function of which cranial nerves?","options": [{"key": "A","text": "Only CN III bilaterally"},{"key": "B","text": "Abducens nerve exclusively"},{"key": "C","text": "Trigeminal (CN V) and facial (CN VII)"},{"key": "D","text": "Optic nerve (CN II, afferent) and oculomotor nerve (CN III, efferent)"}],"correct": "D","explanation": "Pupillary light reflex requires intact CN II (sensing light) and CN III (parasympathetic pupillary constriction)."},{"id": 5690,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Testing facial sensation across the three divisions (ophthalmic, maxillary, mandibular) assesses which cranial nerve?","options": [{"key": "A","text": "Trigeminal nerve (CN V)"},{"key": "B","text": "Glossopharyngeal nerve (CN IX)"},{"key": "C","text": "Vagus nerve (CN X)"},{"key": "D","text": "Facial nerve (CN VII)"}],"correct": "A","explanation": "CN V has three sensory divisions covering facial sensation: ophthalmic, maxillary, and mandibular."},{"id": 5691,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Asking a patient to smile, raise eyebrows, and puff out cheeks assesses which cranial nerve?","options": [{"key": "A","text": "Facial nerve (CN VII)"},{"key": "B","text": "Vagus nerve (CN X)"},{"key": "C","text": "Trigeminal nerve (CN V)"},{"key": "D","text": "Hypoglossal nerve (CN XII)"}],"correct": "A","explanation": "CN VII controls facial expression muscles, tested through symmetric facial movements."},{"id": 5692,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "Assessing the gag reflex primarily tests which cranial nerves?","options": [{"key": "A","text": "Glossopharyngeal (CN IX) and vagus (CN X)"},{"key": "B","text": "Optic nerve (CN II)"},{"key": "C","text": "Facial (CN VII) and trigeminal (CN V)"},{"key": "D","text": "Hypoglossal (CN XII) exclusively"}],"correct": "A","explanation": "Gag reflex involves sensory afferent via CN IX and motor efferent via CN X (pharyngeal muscles)."},{"id": 5693,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Asking the patient to protrude the tongue and observing for deviation assesses which cranial nerve?","options": [{"key": "A","text": "Hypoglossal nerve (CN XII)"},{"key": "B","text": "Glossopharyngeal nerve (CN IX)"},{"key": "C","text": "Vagus nerve (CN X)"},{"key": "D","text": "Facial nerve (CN VII)"}],"correct": "A","explanation": "CN XII controls tongue movement; unilateral LMN lesion causes tongue deviation toward the affected (weak) side on protrusion."},{"id": 5694,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Shoulder shrug against resistance and head rotation against resistance assess which cranial nerve?","options": [{"key": "A","text": "Vagus nerve (CN X)"},{"key": "B","text": "Spinal accessory nerve (CN XI)"},{"key": "C","text": "Hypoglossal nerve (CN XII)"},{"key": "D","text": "Facial nerve (CN VII)"}],"correct": "B","explanation": "CN XI innervates trapezius (shoulder shrug) and sternocleidomastoid (head rotation)."},{"id": 5695,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Testing sense of smell assesses which cranial nerve?","options": [{"key": "A","text": "Optic nerve (CN II)"},{"key": "B","text": "Olfactory nerve (CN I)"},{"key": "C","text": "Trigeminal nerve (CN V)"},{"key": "D","text": "Facial nerve (CN VII)"}],"correct": "B","explanation": "CN I (olfactory) is responsible for smell sensation, tested using identifiable non-irritating odors."},{"id": 5696,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Finger-to-nose test primarily assesses function of the:","options": [{"key": "A","text": "Basal ganglia exclusively"},{"key": "B","text": "Cerebellum (coordination/dysmetria)"},{"key": "C","text": "Corticospinal tract strength"},{"key": "D","text": "Sensory dorsal columns exclusively"}],"correct": "B","explanation": "Finger-to-nose test assesses coordination and detects dysmetria/intention tremor associated with cerebellar dysfunction."},{"id": 5697,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Dysdiadochokinesia' refers to:","options": [{"key": "A","text": "Increased muscle tone"},{"key": "B","text": "Abnormal gait pattern only"},{"key": "C","text": "Impaired ability to perform rapid alternating movements"},{"key": "D","text": "Loss of sensation"}],"correct": "C","explanation": "Dysdiadochokinesia describes difficulty with rapid alternating movements (e.g., hand pronation-supination), a cerebellar sign."},{"id": 5698,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The heel-to-shin test primarily assesses:","options": [{"key": "A","text": "Lower limb coordination (cerebellar function)"},{"key": "B","text": "Sensory proprioception exclusively"},{"key": "C","text": "Ankle strength"},{"key": "D","text": "Hip flexor strength"}],"correct": "A","explanation": "Heel-to-shin test assesses lower limb coordination, revealing cerebellar dysmetria/ataxia if impaired."},{"id": 5699,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Romberg's test assesses:","options": [{"key": "A","text": "Proprioceptive/vestibular contribution to balance by removing visual input"},{"key": "B","text": "Cerebellar coordination exclusively"},{"key": "C","text": "Cranial nerve function"},{"key": "D","text": "Muscle strength"}],"correct": "A","explanation": "Romberg's test (standing with eyes closed) isolates proprioceptive/vestibular balance contribution by removing visual compensation; positive test suggests sensory ataxia rather than cerebellar ataxia (which is typically positive with eyes open too)."},{"id": 5700,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "A positive Romberg's test (increased sway/fall with eyes closed) suggests dysfunction primarily in:","options": [{"key": "A","text": "Motor cortex exclusively"},{"key": "B","text": "Cerebellum exclusively (would be positive with eyes open too)"},{"key": "C","text": "Basal ganglia exclusively"},{"key": "D","text": "Proprioceptive (dorsal column) or vestibular pathways"}],"correct": "D","explanation": "Since cerebellar ataxia typically shows unsteadiness regardless of vision, a Romberg's test that worsens specifically with eyes closed points more to sensory (proprioceptive/vestibular) pathway dysfunction."},{"id": 5701,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The rapid alternating movement test (e.g., hand pronation-supination) primarily assesses:","options": [{"key": "A","text": "Cranial nerve function"},{"key": "B","text": "Muscle strength grading"},{"key": "C","text": "Sensory discrimination"},{"key": "D","text": "Cerebellar coordination"}],"correct": "D","explanation": "Rapid alternating movements test cerebellar function, with impairment (dysdiadochokinesia) suggesting cerebellar pathology."},{"id": 5702,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Two-point discrimination testing assesses which sensory modality/pathway?","options": [{"key": "A","text": "Vestibular function"},{"key": "B","text": "Fine touch discrimination (dorsal column-medial lemniscus pathway)"},{"key": "C","text": "Motor coordination"},{"key": "D","text": "Pain and temperature (spinothalamic tract)"}],"correct": "B","explanation": "Two-point discrimination is a cortical sensory test requiring intact dorsal column-medial lemniscus pathway and parietal cortex processing."},{"id": 5703,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Testing for graphesthesia (identifying numbers/letters traced on skin) assesses:","options": [{"key": "A","text": "Cranial nerve function"},{"key": "B","text": "Primary pain sensation"},{"key": "C","text": "Cerebellar function"},{"key": "D","text": "Cortical sensory integration (parietal lobe function)"}],"correct": "D","explanation": "Graphesthesia requires intact primary sensation plus higher-order cortical (parietal) processing to identify the traced pattern."},{"id": 5704,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Stereognosis testing (identifying objects by touch alone) assesses:","options": [{"key": "A","text": "Motor strength"},{"key": "B","text": "Cranial nerve function exclusively"},{"key": "C","text": "Cortical sensory integration, requiring intact primary sensation and parietal lobe function"},{"key": "D","text": "Cerebellar coordination"}],"correct": "C","explanation": "Stereognosis requires intact peripheral sensation combined with parietal cortical processing to recognize objects tactilely."},{"id": 5705,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Dermatome mapping is used clinically to help identify:","options": [{"key": "A","text": "Cerebellar function"},{"key": "B","text": "The specific spinal nerve root level associated with a sensory deficit"},{"key": "C","text": "Peripheral nerve distribution exclusively"},{"key": "D","text": "Muscle strength grading"}],"correct": "B","explanation": "Dermatomes represent skin areas innervated by specific spinal nerve roots, helping localize nerve root level in radiculopathy."},{"id": 5706,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Myotome testing assesses:","options": [{"key": "A","text": "Cerebellar coordination"},{"key": "B","text": "Sensory function of a specific dermatome"},{"key": "C","text": "Muscle strength associated with a specific spinal nerve root level"},{"key": "D","text": "Cranial nerve function"}],"correct": "C","explanation": "Myotomes represent muscle groups innervated by specific nerve roots, tested via resisted movements to help localize radiculopathy level."},{"id": 5707,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "The Modified Ashworth Scale grade '2' indicates:","options": [{"key": "A","text": "More marked increase in tone through most of ROM, but affected part still easily moved"},{"key": "B","text": "Considerable increase, passive movement difficult"},{"key": "C","text": "Slight increase with catch only"},{"key": "D","text": "No increase in tone"}],"correct": "A","explanation": "Grade 2 describes more pronounced tone increase through most of the range while the limb remains relatively easily moved."},{"id": 5708,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing coordination via the finger-nose-finger test (alternating between examiner's finger and patient's nose) helps detect:","options": [{"key": "A","text": "Bradykinesia specifically"},{"key": "B","text": "Rigidity specifically"},{"key": "C","text": "Resting tremor specifically"},{"key": "D","text": "Intention tremor and dysmetria"}],"correct": "D","explanation": "This test can reveal intention tremor (worsening as target is approached) and dysmetria (overshoot/undershoot), classic cerebellar signs."},{"id": 5709,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Resting tremor, characteristic of Parkinson's disease, is best described as:","options": [{"key": "A","text": "Tremor only present during sustained postures"},{"key": "B","text": "Tremor unaffected by rest or activity"},{"key": "C","text": "Tremor present at rest, diminishing with voluntary movement"},{"key": "D","text": "Tremor that worsens with movement toward a target"}],"correct": "C","explanation": "Parkinsonian resting tremor is present when the limb is at rest and typically reduces or disappears with voluntary movement."},{"id": 5710,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "Postural (action) tremor differs from resting tremor in that it:","options": [{"key": "A","text": "Occurs when maintaining a position against gravity, e.g., outstretched arms"},{"key": "B","text": "Never occurs in any neurological condition"},{"key": "C","text": "Is exclusively seen in cerebellar disease"},{"key": "D","text": "Only occurs at complete rest"}],"correct": "A","explanation": "Postural tremor emerges when maintaining a posture against gravity (e.g., essential tremor), distinct from Parkinsonian resting tremor."},{"id": 5711,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Intention tremor, associated with cerebellar dysfunction, is characterized by:","options": [{"key": "A","text": "Tremor present only at rest"},{"key": "B","text": "Tremor that worsens as the limb approaches its target during goal-directed movement"},{"key": "C","text": "Tremor that improves as target is approached"},{"key": "D","text": "Tremor unrelated to movement"}],"correct": "B","explanation": "Intention tremor increases in amplitude as the movement approaches its target, a hallmark of cerebellar pathology."},{"id": 5712,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "Assessing muscle power using the Medical Research Council (MRC) scale grades strength from:","options": [{"key": "A","text": "0 to 10"},{"key": "B","text": "1 to 3"},{"key": "C","text": "0 to 100"},{"key": "D","text": "0 to 5"}],"correct": "D","explanation": "MRC scale grades muscle power 0 (no contraction) to 5 (normal power against full resistance)."},{"id": 5713,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "An MRC grade of 3 indicates:","options": [{"key": "A","text": "Active movement against gravity, without added resistance"},{"key": "B","text": "Full ROM with gravity eliminated only"},{"key": "C","text": "Trace contraction only, no movement"},{"key": "D","text": "Normal power against full resistance"}],"correct": "A","explanation": "MRC Grade 3 = movement through full range against gravity, but unable to overcome any additional manual resistance."},{"id": 5714,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Sensory examination for light touch typically uses which tool?","options": [{"key": "A","text": "Pin/sharp object"},{"key": "B","text": "Tuning fork"},{"key": "C","text": "Reflex hammer"},{"key": "D","text": "Cotton wool or soft brush"}],"correct": "D","explanation": "Light touch is assessed using cotton wool or a soft brush applied lightly to the skin."},{"id": 5715,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Vibration sense is tested clinically using:","options": [{"key": "A","text": "Cotton wool"},{"key": "B","text": "Reflex hammer"},{"key": "C","text": "A tuning fork (typically 128Hz) applied over bony prominences"},{"key": "D","text": "A pin"}],"correct": "C","explanation": "A vibrating tuning fork placed over bony prominences (e.g., malleolus) assesses vibration sense, part of dorsal column function testing."},{"id": 5716,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Proprioception (joint position sense) testing typically involves:","options": [{"key": "A","text": "Applying a vibrating tuning fork"},{"key": "B","text": "Light touch with cotton wool"},{"key": "C","text": "Passively moving a joint (e.g., toe/finger) and asking patient to identify direction without visual input"},{"key": "D","text": "Testing with a sharp pin"}],"correct": "C","explanation": "Proprioception is assessed by passively moving a distal joint up/down and asking the patient (eyes closed) to identify the direction of movement."},{"id": 5717,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which grading system is commonly used to classify the completeness of spinal cord injury based on motor/sensory function?","options": [{"key": "A","text": "Glasgow Coma Scale"},{"key": "B","text": "Modified Ashworth Scale"},{"key": "C","text": "ASIA Impairment Scale (AIS)"},{"key": "D","text": "MRC scale"}],"correct": "C","explanation": "ASIA Impairment Scale (A-E) classifies spinal cord injury completeness based on standardized motor and sensory testing."},{"id": 5718,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "ASIA Impairment Scale Grade A indicates:","options": [{"key": "A","text": "Complete injury - no motor or sensory function preserved in sacral segments S4-S5"},{"key": "B","text": "Normal neurological examination"},{"key": "C","text": "Complete preservation of motor/sensory function"},{"key": "D","text": "Incomplete injury with significant motor sparing"}],"correct": "A","explanation": "ASIA A = complete injury, with no sensory or motor function preserved in the lowest sacral segments (S4-S5)."},{"id": 5719,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Hard","question": "ASIA Impairment Scale Grade E indicates:","options": [{"key": "A","text": "Insufficient data to classify"},{"key": "B","text": "Incomplete injury with motor function below neurological level"},{"key": "C","text": "Complete injury"},{"key": "D","text": "Normal motor and sensory function"}],"correct": "D","explanation": "ASIA E indicates normal sensory and motor function throughout, used when a patient with prior deficits has recovered fully."},{"id": 5720,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "The neurological level of injury in spinal cord injury classification refers to:","options": [{"key": "A","text": "The level of vertebral fracture"},{"key": "B","text": "The most caudal segment with normal sensory AND motor function bilaterally"},{"key": "C","text": "Only the sensory level"},{"key": "D","text": "Only the motor level"}],"correct": "B","explanation": "Neurological level is defined as the most caudal spinal segment with intact sensation and antigravity (grade 3+) motor function bilaterally."},{"id": 5721,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Autonomic dysreflexia is a serious complication seen in spinal cord injuries typically at or above which level?","options": [{"key": "A","text": "C1 exclusively"},{"key": "B","text": "S2"},{"key": "C","text": "L1"},{"key": "D","text": "T6"}],"correct": "D","explanation": "Autonomic dysreflexia typically occurs in SCI at or above T6, due to unopposed sympathetic response to noxious stimuli below the injury level."},{"id": 5722,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing for ataxic gait (wide-based, unsteady gait) primarily suggests dysfunction in which system?","options": [{"key": "A","text": "Basal ganglia system exclusively"},{"key": "B","text": "Cerebellar system (or sensory/proprioceptive pathways)"},{"key": "C","text": "Neuromuscular junction exclusively"},{"key": "D","text": "Peripheral nerve motor function exclusively"}],"correct": "B","explanation": "Ataxic gait patterns are classically associated with cerebellar dysfunction or, in sensory ataxia, proprioceptive pathway impairment."},{"id": 5723,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Festinating gait, characterized by short shuffling steps with progressive acceleration, is characteristic of:","options": [{"key": "A","text": "Parkinson's disease"},{"key": "B","text": "Upper motor neuron lesion causing spastic gait"},{"key": "C","text": "Peripheral neuropathy"},{"key": "D","text": "Cerebellar ataxia"}],"correct": "A","explanation": "Festinating gait, with shuffling steps and forward-flexed posture, is a classic feature of Parkinson's disease."},{"id": 5724,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "Spastic (scissoring) gait, seen in conditions like cerebral palsy or spinal cord injury, is characterized by:","options": [{"key": "A","text": "Shuffling gait with festination"},{"key": "B","text": "Stiff-legged gait with hip adduction causing legs to cross"},{"key": "C","text": "High-stepping gait to clear the foot"},{"key": "D","text": "Wide-based unsteady gait"}],"correct": "B","explanation": "Spastic diplegic gait shows characteristic hip adductor spasticity causing a scissoring pattern during ambulation."},{"id": 5725,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Steppage gait (high-stepping to clear a dropped foot) suggests weakness of which muscle group?","options": [{"key": "A","text": "Knee extensors"},{"key": "B","text": "Hip abductors"},{"key": "C","text": "Hip flexors"},{"key": "D","text": "Ankle dorsiflexors (e.g., from common peroneal nerve injury)"}],"correct": "D","explanation": "Foot drop from dorsiflexor weakness necessitates increased hip/knee flexion during swing to clear the foot, producing steppage gait."},{"id": 5726,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Sensory examination findings of stocking-glove distribution sensory loss is classically associated with:","options": [{"key": "A","text": "Cerebral cortex lesion"},{"key": "B","text": "Cerebellar lesion"},{"key": "C","text": "Single nerve root lesion"},{"key": "D","text": "Peripheral polyneuropathy"}],"correct": "D","explanation": "Symmetric distal 'stocking-glove' sensory loss pattern is characteristic of length-dependent peripheral polyneuropathy (e.g., diabetic neuropathy)."},{"id": 5727,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing for pronator drift (arm drift with pronation when held outstretched with eyes closed) suggests:","options": [{"key": "A","text": "Normal finding requiring no further workup"},{"key": "B","text": "Peripheral nerve injury exclusively"},{"key": "C","text": "Subtle upper motor neuron weakness"},{"key": "D","text": "Cerebellar dysfunction primarily"}],"correct": "C","explanation": "Pronator drift is a sensitive sign of subtle UMN (corticospinal tract) weakness."},{"id": 5728,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The Mini-Mental State Examination (MMSE) is used clinically to assess:","options": [{"key": "A","text": "Cognitive function/screening for cognitive impairment"},{"key": "B","text": "Sensory function"},{"key": "C","text": "Motor strength"},{"key": "D","text": "Cranial nerve function"}],"correct": "A","explanation": "MMSE is a widely used brief cognitive screening tool assessing orientation, memory, attention, language, and visuospatial skills."},{"id": 5729,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The Montreal Cognitive Assessment (MoCA) is considered more sensitive than MMSE for detecting:","options": [{"key": "A","text": "Sensory deficits"},{"key": "B","text": "Mild cognitive impairment"},{"key": "C","text": "Motor deficits"},{"key": "D","text": "Severe dementia only"}],"correct": "B","explanation": "MoCA is generally considered more sensitive than MMSE for detecting milder degrees of cognitive impairment."},{"id": 5730,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Assessing muscle bulk/wasting is particularly important in differentiating which type of motor lesion?","options": [{"key": "A","text": "Only relevant for cerebellar lesions"},{"key": "B","text": "Not clinically useful"},{"key": "C","text": "Lower motor neuron lesion (significant atrophy) versus upper motor neuron lesion (disuse atrophy less prominent initially)"},{"key": "D","text": "Only relevant for sensory lesions"}],"correct": "C","explanation": "Significant, often rapid muscle wasting is characteristic of LMN lesions (direct denervation), differing from the milder, slower disuse atrophy pattern in UMN lesions."},{"id": 5731,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Fasciculations (visible spontaneous muscle twitches) are associated with:","options": [{"key": "A","text": "Normal physiological finding always requiring no investigation"},{"key": "B","text": "Cerebellar pathology exclusively"},{"key": "C","text": "Lower motor neuron pathology (e.g., motor neuron disease)"},{"key": "D","text": "Upper motor neuron pathology exclusively"}],"correct": "C","explanation": "Fasciculations reflect spontaneous motor unit discharge, classically associated with LMN pathology like motor neuron disease, though benign fasciculations can occur in healthy individuals too."},{"id": 5732,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing for nystagmus (involuntary rhythmic eye movement) can help identify pathology in which systems?","options": [{"key": "A","text": "Basal ganglia exclusively"},{"key": "B","text": "Neuromuscular junction exclusively"},{"key": "C","text": "Vestibular system or cerebellum/brainstem"},{"key": "D","text": "Peripheral nerve motor function exclusively"}],"correct": "C","explanation": "Nystagmus can result from vestibular dysfunction (peripheral) or central causes (cerebellar/brainstem pathology)."},{"id": 5733,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The Dix-Hallpike maneuver is used clinically to assess for:","options": [{"key": "A","text": "Peripheral neuropathy"},{"key": "B","text": "Cerebellar ataxia"},{"key": "C","text": "Benign Paroxysmal Positional Vertigo (BPPV)"},{"key": "D","text": "Motor strength"}],"correct": "C","explanation": "Dix-Hallpike test provokes characteristic nystagmus/vertigo in BPPV by repositioning otoconia within the semicircular canals."},{"id": 5734,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Assessing swallowing function (dysphagia screening) is particularly important following which neurological event?","options": [{"key": "A","text": "Isolated cerebellar lesion only"},{"key": "B","text": "Stroke, given risk of aspiration"},{"key": "C","text": "Peripheral nerve injury only"},{"key": "D","text": "Not relevant to neurological assessment"}],"correct": "B","explanation": "Dysphagia screening is a critical component of stroke assessment due to significant aspiration pneumonia risk if swallowing is impaired."},{"id": 5735,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Easy","question": "The Berg Balance Scale is commonly used in neurological rehabilitation to assess:","options": [{"key": "A","text": "Functional balance ability and fall risk"},{"key": "B","text": "Muscle strength directly"},{"key": "C","text": "Cognitive function"},{"key": "D","text": "Sensory discrimination"}],"correct": "A","explanation": "Berg Balance Scale is a widely validated tool assessing functional balance performance across various tasks relevant to fall risk in neurological populations."},{"id": 5736,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The Functional Independence Measure (FIM) is used to assess:","options": [{"key": "A","text": "Level of independence in activities of daily living/functional tasks"},{"key": "B","text": "Cognitive function exclusively"},{"key": "C","text": "Muscle strength exclusively"},{"key": "D","text": "Sensory function exclusively"}],"correct": "A","explanation": "FIM assesses functional independence across motor and cognitive domains, widely used in rehabilitation settings to track progress."},{"id": 5737,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Assessing muscle tone in the acute phase immediately following a stroke often reveals:","options": [{"key": "A","text": "Rigidity from onset"},{"key": "B","text": "Flaccidity (hypotonia) initially, which may later develop into spasticity"},{"key": "C","text": "Immediate severe spasticity from onset"},{"key": "D","text": "No change in tone ever"}],"correct": "B","explanation": "Acute stroke often presents with an initial flaccid phase, with spasticity typically developing over subsequent days to weeks as reflexes become hyperactive."},{"id": 5738,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "'Spinal shock' following acute spinal cord injury is characterized by:","options": [{"key": "A","text": "Temporary loss of all reflex activity below the level of injury, including flaccidity and areflexia"},{"key": "B","text": "Only sensory loss without motor involvement"},{"key": "C","text": "Permanent, unchanging neurological status"},{"key": "D","text": "Immediate spasticity from the moment of injury"}],"correct": "A","explanation": "Spinal shock describes a temporary state of areflexia/flaccidity below the injury level, typically resolving over days to weeks as reflexes return (often then becoming hyperreflexic)."},{"id": 5739,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Hard","question": "The bulbocavernosus reflex returning is a clinically significant sign indicating:","options": [{"key": "A","text": "The end of spinal shock phase"},{"key": "B","text": "Permanent complete paralysis"},{"key": "C","text": "Complete recovery from spinal cord injury"},{"key": "D","text": "Onset of autonomic dysreflexia"}],"correct": "A","explanation": "Return of the bulbocavernosus reflex is a classic clinical indicator that spinal shock has resolved, allowing more accurate assessment of injury completeness."},{"id": 5740,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Testing for ankle clonus involves:","options": [{"key": "A","text": "Resisted dorsiflexion"},{"key": "B","text": "Rapid passive dorsiflexion of the ankle, observing for rhythmic beats of plantarflexion-dorsiflexion"},{"key": "C","text": "Tapping the Achilles tendon once"},{"key": "D","text": "Passive plantarflexion only"}],"correct": "B","explanation": "Sustained ankle clonus is elicited by a brisk, sustained dorsiflexion stretch, with rhythmic oscillation indicating hyperreflexia/UMN pathology."},{"id": 5741,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing higher cortical function for apraxia (impaired ability to perform learned motor tasks despite intact motor/sensory function) is important particularly after:","options": [{"key": "A","text": "Isolated cerebellar lesion"},{"key": "B","text": "Isolated peripheral nerve injury"},{"key": "C","text": "Isolated muscle disease"},{"key": "D","text": "Stroke, especially involving parietal lobe"}],"correct": "D","explanation": "Apraxia commonly results from cortical (often parietal lobe) damage, frequently assessed in stroke rehabilitation given its impact on functional task performance."},{"id": 5742,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Unilateral spatial neglect (inattention to one side of space) is most commonly associated with lesions of which hemisphere?","options": [{"key": "A","text": "Non-dominant (typically right) parietal lobe"},{"key": "B","text": "Cerebellum exclusively"},{"key": "C","text": "Brainstem exclusively"},{"key": "D","text": "Dominant (typically left) frontal lobe exclusively"}],"correct": "A","explanation": "Unilateral neglect is classically associated with right (non-dominant) parietal lobe lesions, causing inattention to the contralateral (left) side."},{"id": 5743,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing for dysarthria (difficulty with speech articulation) versus aphasia (language impairment) is important because:","options": [{"key": "A","text": "Both terms describe identical conditions requiring identical treatment"},{"key": "B","text": "Neither condition is relevant to physiotherapy assessment"},{"key": "C","text": "Dysarthria reflects motor speech production issues while aphasia reflects language comprehension/formulation deficits, requiring different management approaches"},{"key": "D","text": "Dysarthria always indicates worse prognosis than aphasia"}],"correct": "C","explanation": "Distinguishing motor speech (dysarthria) from language (aphasia) impairment guides appropriate referral and management, important in the broader neurological rehabilitation team context."},{"id": 5744,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Hard","question": "The corneal reflex tests which two cranial nerves (afferent and efferent)?","options": [{"key": "A","text": "CN IX (afferent) and CN X (efferent)"},{"key": "B","text": "CN II (afferent) and CN III (efferent)"},{"key": "C","text": "CN V (afferent) and CN VII (efferent)"},{"key": "D","text": "CN III (afferent) and CN IV (efferent)"}],"correct": "C","explanation": "Corneal reflex involves CN V (sensory, cornea) as afferent and CN VII (motor, orbicularis oculi blink) as efferent limb."},{"id": 5745,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Easy","question": "Testing the biceps reflex assesses which nerve root level?","options": [{"key": "A","text": "S1-S2"},{"key": "B","text": "C5-C6"},{"key": "C","text": "L3-L4"},{"key": "D","text": "C7-C8"}],"correct": "B","explanation": "Biceps deep tendon reflex corresponds to C5-C6 nerve root level."},{"id": 5746,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "Testing the triceps reflex assesses which nerve root level?","options": [{"key": "A","text": "L4-L5"},{"key": "B","text": "C7-C8"},{"key": "C","text": "C5-C6"},{"key": "D","text": "S1"}],"correct": "B","explanation": "Triceps reflex corresponds primarily to C7 (with some C8 contribution) nerve root level."},{"id": 5747,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "Testing the knee jerk (patellar) reflex assesses which nerve root level?","options": [{"key": "A","text": "S2-S4"},{"key": "B","text": "L3-L4"},{"key": "C","text": "L5-S1"},{"key": "D","text": "C5-C6"}],"correct": "B","explanation": "Patellar reflex corresponds to L3-L4 nerve root level."},{"id": 5748,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "Testing the ankle jerk reflex assesses which nerve root level?","options": [{"key": "A","text": "L1-L2"},{"key": "B","text": "C7-C8"},{"key": "C","text": "S1-S2"},{"key": "D","text": "L3-L4"}],"correct": "C","explanation": "Ankle (Achilles) reflex corresponds to S1-S2 nerve root level."},{"id": 5749,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Superficial abdominal reflexes, if absent, may suggest pathology at which level (among other causes)?","options": [{"key": "A","text": "Always a normal finding regardless of clinical context"},{"key": "B","text": "Corticospinal tract lesion above the reflex arc level"},{"key": "C","text": "Only muscular pathology"},{"key": "D","text": "Only peripheral nerve pathology"}],"correct": "B","explanation": "Absent superficial abdominal reflexes can be a subtle sign of pyramidal (corticospinal) tract dysfunction, among other causes including obesity or multiple pregnancies."},{"id": 5750,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Easy","question": "The cremasteric reflex, when tested in males, assesses spinal cord/nerve root level:","options": [{"key": "A","text": "S2-S4"},{"key": "B","text": "L5-S1"},{"key": "C","text": "L1-L2"},{"key": "D","text": "C8-T1"}],"correct": "C","explanation": "Cremasteric reflex corresponds to the L1-L2 spinal segment level."},{"id": 5751,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Assessment of sacral sparing (perianal sensation, voluntary anal contraction) in spinal cord injury is important because it indicates:","options": [{"key": "A","text": "The injury is anatomically/functionally incomplete"},{"key": "B","text": "Only relevant for cervical level injuries"},{"key": "C","text": "Irrelevant finding with no prognostic value"},{"key": "D","text": "Complete injury with no recovery potential"}],"correct": "A","explanation": "Presence of sacral sparing indicates an incomplete spinal cord injury, carrying more favorable prognostic implications than complete injury."},{"id": 5752,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Testing light touch sensation over the C6 dermatome would typically involve testing which area?","options": [{"key": "A","text": "Medial forearm"},{"key": "B","text": "Axilla"},{"key": "C","text": "Thumb"},{"key": "D","text": "Little finger"}],"correct": "C","explanation": "C6 dermatome classically includes the thumb and lateral forearm."},{"id": 5753,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Testing light touch sensation over the C8 dermatome would typically involve testing which area?","options": [{"key": "A","text": "Lateral forearm"},{"key": "B","text": "Thumb"},{"key": "C","text": "Shoulder"},{"key": "D","text": "Little finger"}],"correct": "D","explanation": "C8 dermatome classically corresponds to the little finger and medial hand."},{"id": 5754,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Testing sensation over the L5 dermatome would typically involve testing which area?","options": [{"key": "A","text": "Medial thigh"},{"key": "B","text": "Anterior thigh"},{"key": "C","text": "Lateral foot and little toe"},{"key": "D","text": "Dorsum of foot and big toe"}],"correct": "D","explanation": "L5 dermatome covers the dorsum of the foot and great toe region."},{"id": 5755,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Testing sensation over the S1 dermatome would typically involve testing which area?","options": [{"key": "A","text": "Lateral foot and little toe/heel"},{"key": "B","text": "Dorsum of foot"},{"key": "C","text": "Anterior thigh"},{"key": "D","text": "Medial leg"}],"correct": "A","explanation": "S1 dermatome corresponds to the lateral foot, little toe, and posterior leg/heel region."},{"id": 5756,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "An 'intention tremor' combined with dysmetria and ataxic gait forms a classic clinical triad suggesting pathology in the:","options": [{"key": "A","text": "Neuromuscular junction"},{"key": "B","text": "Peripheral nerves"},{"key": "C","text": "Basal ganglia"},{"key": "D","text": "Cerebellum"}],"correct": "D","explanation": "This classic triad (intention tremor, dysmetria, ataxia) is characteristic of cerebellar dysfunction."},{"id": 5757,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "'Titubation' (rhythmic tremor of the head/trunk) is associated with dysfunction of which structure?","options": [{"key": "A","text": "Peripheral nerve"},{"key": "B","text": "Neuromuscular junction"},{"key": "C","text": "Cerebellum (particularly vermis)"},{"key": "D","text": "Basal ganglia exclusively"}],"correct": "C","explanation": "Titubation, a rhythmic head/trunk tremor, is associated with cerebellar (particularly midline/vermis) dysfunction."},{"id": 5758,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Bradykinesia, a cardinal feature of Parkinson's disease, refers to:","options": [{"key": "A","text": "Increased speed of movement"},{"key": "B","text": "Complete absence of movement"},{"key": "C","text": "Only affects speech, not limb movement"},{"key": "D","text": "Slowness of movement initiation and execution"}],"correct": "D","explanation": "Bradykinesia describes generalized slowness in initiating and performing voluntary movement, a core Parkinsonian feature."},{"id": 5759,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Assessing postural reflexes (e.g., pull test) in Parkinson's disease helps evaluate risk of:","options": [{"key": "A","text": "Cognitive impairment exclusively"},{"key": "B","text": "Peripheral neuropathy"},{"key": "C","text": "Autonomic dysfunction exclusively"},{"key": "D","text": "Falls due to postural instability"}],"correct": "D","explanation": "The pull test assesses postural stability, with impaired righting response indicating increased fall risk in Parkinson's disease."},{"id": 5760,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "The 'pull test' for postural stability in Parkinson's disease involves:","options": [{"key": "A","text": "Pulling the patient's arm forward"},{"key": "B","text": "Testing grip strength"},{"key": "C","text": "A quick backward pull on the shoulders while the examiner is ready to catch the patient, observing recovery steps"},{"key": "D","text": "Testing resistance to passive movement"}],"correct": "C","explanation": "Pull test assesses postural reflexes by observing the number of steps needed to regain balance (or falling) after a brief backward pull."},{"id": 5761,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing for micrographia (progressively smaller handwriting) is a clinical feature associated with:","options": [{"key": "A","text": "Upper motor neuron lesion of the arm"},{"key": "B","text": "Cerebellar ataxia"},{"key": "C","text": "Peripheral neuropathy"},{"key": "D","text": "Parkinson's disease"}],"correct": "D","explanation": "Micrographia, progressively diminishing handwriting size, is a recognized feature of Parkinson's disease bradykinesia."},{"id": 5762,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Assessing chorea (involuntary, irregular, unpredictable movements) is characteristic of which condition?","options": [{"key": "A","text": "Huntington's disease"},{"key": "B","text": "Cerebellar ataxia"},{"key": "C","text": "Peripheral neuropathy"},{"key": "D","text": "Parkinson's disease"}],"correct": "A","explanation": "Chorea, characterized by irregular, dance-like involuntary movements, is a hallmark feature of Huntington's disease."},{"id": 5763,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Dystonia refers to:","options": [{"key": "A","text": "Sustained or repetitive muscle contractions causing twisting movements or abnormal postures"},{"key": "B","text": "Rhythmic tremor only"},{"key": "C","text": "Complete loss of muscle tone"},{"key": "D","text": "Random brief muscle jerks"}],"correct": "A","explanation": "Dystonia describes sustained abnormal muscle contractions producing twisting/repetitive movements or postures."},{"id": 5764,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Myoclonus refers to:","options": [{"key": "A","text": "Rhythmic oscillating tremor"},{"key": "B","text": "Sustained abnormal posturing"},{"key": "C","text": "Sudden, brief, shock-like involuntary muscle jerks"},{"key": "D","text": "Slow writhing movements"}],"correct": "C","explanation": "Myoclonus describes sudden brief muscle jerks, which can be physiological (e.g., hypnic jerks) or pathological."},{"id": 5765,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Stroke is broadly classified into which two main types?","options": [{"key": "A","text": "Only hemorrhagic"},{"key": "B","text": "Only ischemic, hemorrhage is not classified as stroke"},{"key": "C","text": "Cortical and subcortical only"},{"key": "D","text": "Ischemic and hemorrhagic"}],"correct": "D","explanation": "Stroke is classified as ischemic (from vascular occlusion) or hemorrhagic (from vessel rupture/bleeding)."},{"id": 5766,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Ischemic stroke accounts for approximately what percentage of all strokes?","options": [{"key": "A","text": "50%"},{"key": "B","text": "15%"},{"key": "C","text": "100%"},{"key": "D","text": "Approximately 85%"}],"correct": "D","explanation": "Ischemic stroke represents the majority (~85%) of stroke cases, with hemorrhagic stroke accounting for the remainder."},{"id": 5767,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A Transient Ischemic Attack (TIA) is defined as:","options": [{"key": "A","text": "Always associated with permanent infarction on imaging"},{"key": "B","text": "A type of hemorrhagic stroke"},{"key": "C","text": "Permanent neurological deficit"},{"key": "D","text": "Temporary neurological deficit from ischemia, typically resolving within 24 hours without infarction on imaging"}],"correct": "D","explanation": "TIA is a transient episode of neurological dysfunction from focal ischemia without evidence of acute infarction on imaging, historically defined by resolution within 24 hours."},{"id": 5768,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A TIA is clinically significant primarily because it:","options": [{"key": "A","text": "Has no clinical significance"},{"key": "B","text": "Only occurs in young patients"},{"key": "C","text": "Always progresses to permanent stroke immediately"},{"key": "D","text": "Serves as a warning sign for potential future stroke, requiring urgent risk factor assessment"}],"correct": "D","explanation": "TIA significantly increases short-term risk of subsequent stroke, warranting urgent evaluation and secondary prevention measures."},{"id": 5769,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Middle cerebral artery (MCA) stroke commonly presents with which contralateral deficit pattern?","options": [{"key": "A","text": "Face and arm weakness greater than leg weakness (with possible aphasia if dominant hemisphere)"},{"key": "B","text": "Leg weakness greater than face/arm weakness"},{"key": "C","text": "Isolated cerebellar signs"},{"key": "D","text": "Isolated visual field defect only"}],"correct": "A","explanation": "MCA territory covers the lateral cortex representing face/arm predominantly, causing greater face/arm than leg weakness, with aphasia if the dominant hemisphere is involved."},{"id": 5770,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Anterior cerebral artery (ACA) stroke commonly presents with which contralateral deficit pattern?","options": [{"key": "A","text": "Leg weakness greater than face/arm weakness"},{"key": "B","text": "Isolated homonymous hemianopia"},{"key": "C","text": "Isolated dysarthria"},{"key": "D","text": "Face/arm weakness greater than leg weakness"}],"correct": "A","explanation": "ACA territory covers the medial cortex representing the lower limb, causing greater leg than face/arm weakness."},{"id": 5771,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Posterior cerebral artery (PCA) stroke commonly presents with:","options": [{"key": "A","text": "Contralateral homonymous hemianopia (visual field defect)"},{"key": "B","text": "Isolated aphasia without visual symptoms"},{"key": "C","text": "Contralateral leg weakness predominantly"},{"key": "D","text": "Contralateral face/arm weakness predominantly"}],"correct": "A","explanation": "PCA supplies the occipital lobe (visual cortex), so PCA stroke classically causes contralateral homonymous hemianopia, often with macular sparing."},{"id": 5772,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Lacunar strokes typically result from occlusion of which type of vessels?","options": [{"key": "A","text": "Extracranial carotid arteries only"},{"key": "B","text": "Small penetrating arteries (deep perforators)"},{"key": "C","text": "Large cerebral arteries"},{"key": "D","text": "Venous sinuses"}],"correct": "B","explanation": "Lacunar strokes result from occlusion of small deep penetrating arteries, often related to chronic hypertension/small vessel disease."},{"id": 5773,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "'Pure motor' lacunar stroke syndrome typically involves infarction in which location?","options": [{"key": "A","text": "Occipital lobe exclusively"},{"key": "B","text": "Cerebellum exclusively"},{"key": "C","text": "Posterior limb of internal capsule or pons"},{"key": "D","text": "Cerebral cortex"}],"correct": "C","explanation": "Pure motor hemiparesis, a classic lacunar syndrome, commonly results from small infarcts in the posterior limb of the internal capsule or basis pontis."},{"id": 5774,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Wallenberg syndrome (lateral medullary syndrome) results from occlusion of which artery?","options": [{"key": "A","text": "Anterior cerebral artery"},{"key": "B","text": "Anterior spinal artery"},{"key": "C","text": "Posterior inferior cerebellar artery (PICA)"},{"key": "D","text": "Middle cerebral artery"}],"correct": "C","explanation": "Wallenberg syndrome classically results from PICA (or vertebral artery) occlusion, causing lateral medullary infarction with characteristic crossed sensory deficits and other brainstem signs."},{"id": 5775,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Locked-in syndrome typically results from a lesion at which level?","options": [{"key": "A","text": "Ventral pons (basilar artery occlusion)"},{"key": "B","text": "Spinal cord"},{"key": "C","text": "Cerebellum exclusively"},{"key": "D","text": "Cerebral cortex diffusely"}],"correct": "A","explanation": "Locked-in syndrome results from ventral pontine infarction (often basilar artery occlusion), preserving consciousness and vertical eye movement/blinking but causing quadriplegia and anarthria."},{"id": 5776,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which stroke risk factor is considered most significant and modifiable?","options": [{"key": "A","text": "Hypertension"},{"key": "B","text": "Age (non-modifiable)"},{"key": "C","text": "Family history (non-modifiable)"},{"key": "D","text": "Gender"}],"correct": "A","explanation": "Hypertension is the single most important modifiable risk factor for both ischemic and hemorrhagic stroke."},{"id": 5777,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Atrial fibrillation increases stroke risk primarily through which mechanism?","options": [{"key": "A","text": "Cardioembolic phenomenon from stasis-related clot formation in the left atrium"},{"key": "B","text": "No established mechanism"},{"key": "C","text": "Direct vessel wall damage"},{"key": "D","text": "Only through hemorrhagic mechanism"}],"correct": "A","explanation": "AF causes blood stasis in the left atrium/appendage, predisposing to thrombus formation that can embolize to cerebral vessels."},{"id": 5778,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The FAST (Face, Arm, Speech, Time) mnemonic is used for:","options": [{"key": "A","text": "Detailed neurological examination"},{"key": "B","text": "Cognitive assessment"},{"key": "C","text": "Public/rapid recognition of stroke symptoms to prompt urgent action"},{"key": "D","text": "Rehabilitation outcome measurement"}],"correct": "C","explanation": "FAST is a widely used public education tool for rapid stroke symptom recognition, emphasizing urgency of seeking care."},{"id": 5779,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Thrombolysis (tPA) for acute ischemic stroke is generally most effective when administered within which time window from symptom onset?","options": [{"key": "A","text": "1 week"},{"key": "B","text": "24 hours for all patients"},{"key": "C","text": "4.5 hours (with some extended window criteria in select cases)"},{"key": "D","text": "No time restriction applies"}],"correct": "C","explanation": "Standard tPA administration window is within 4.5 hours of symptom onset, though extended windows may apply with specific imaging criteria in select cases."},{"id": 5780,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Mechanical thrombectomy for large vessel occlusion stroke can be considered up to what extended time window in select patients (with appropriate imaging)?","options": [{"key": "A","text": "Only within 1 hour"},{"key": "B","text": "No thrombectomy option exists regardless of timing"},{"key": "C","text": "Up to 24 hours in carefully selected patients"},{"key": "D","text": "Only within 3 hours"}],"correct": "C","explanation": "With advanced imaging selection criteria, mechanical thrombectomy can be considered up to 24 hours post-onset in appropriately selected large vessel occlusion patients."},{"id": 5781,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Early mobilization after stroke (within 24 hours) is generally recommended, though very early aggressive mobilization protocols have shown:","options": [{"key": "A","text": "Complete contraindication at any time post-stroke"},{"key": "B","text": "No relevance to stroke recovery"},{"key": "C","text": "Universal benefit at all doses/timing"},{"key": "D","text": "Mixed evidence, with some very early high-dose mobilization potentially associated with worse outcomes in specific trials (e.g., AVERT)"}],"correct": "D","explanation": "While early mobilization is generally beneficial, trials like AVERT have shown that very early, high-frequency, high-dose mobilization may not always be superior and requires individualized clinical judgment."},{"id": 5782,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Constraint-Induced Movement Therapy (CIMT) for post-stroke upper limb rehabilitation involves:","options": [{"key": "A","text": "Restraining the affected limb to protect it from use"},{"key": "B","text": "Only passive range of motion exercises"},{"key": "C","text": "Restraining the less-affected limb to encourage intensive use of the more-affected limb"},{"key": "D","text": "Only strengthening the unaffected limb"}],"correct": "C","explanation": "CIMT restrains the less-affected limb, forcing intensive, repetitive use of the affected limb to promote motor recovery and reduce learned non-use."},{"id": 5783,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "'Learned non-use' phenomenon after stroke refers to:","options": [{"key": "A","text": "Physical inability to move the limb due to complete paralysis only"},{"key": "B","text": "Progressive avoidance of using the affected limb due to early unsuccessful attempts, becoming a learned behavioral pattern"},{"key": "C","text": "A normal expected recovery pattern requiring no intervention"},{"key": "D","text": "Improved function of the affected limb over time without intervention"}],"correct": "B","explanation": "Learned non-use describes a behavioral suppression of affected limb use following initial unsuccessful movement attempts, which CIMT specifically aims to counteract."},{"id": 5784,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "The Bobath (Neurodevelopmental Treatment) approach to stroke rehabilitation emphasizes:","options": [{"key": "A","text": "Exclusively passive range of motion"},{"key": "B","text": "Complete restriction of all movement"},{"key": "C","text": "Only strength training regardless of movement quality"},{"key": "D","text": "Normalizing tone and facilitating normal movement patterns through handling techniques"}],"correct": "D","explanation": "Bobath approach traditionally emphasizes tone normalization and facilitation of more normal movement patterns, though the approach has evolved considerably with updated evidence-based practice."},{"id": 5785,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Motor Relearning Programme (MRP) approach to stroke rehabilitation emphasizes:","options": [{"key": "A","text": "Task-specific practice with active problem-solving and motor learning principles"},{"key": "B","text": "Avoidance of functional tasks entirely"},{"key": "C","text": "Only isolated muscle strengthening without functional context"},{"key": "D","text": "Passive handling techniques exclusively"}],"correct": "A","explanation": "MRP emphasizes active, task-specific practice grounded in motor learning theory, encouraging patient active participation and problem-solving."},{"id": 5786,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Task-oriented training approaches in stroke rehabilitation are supported by evidence to promote recovery primarily through:","options": [{"key": "A","text": "Passive modalities alone"},{"key": "B","text": "Complete rest and immobilization"},{"key": "C","text": "Avoidance of any repetitive practice"},{"key": "D","text": "Practice of meaningful, functional tasks that promote neuroplastic adaptation"}],"correct": "D","explanation": "Task-oriented training leverages principles of neuroplasticity and motor learning through meaningful, repetitive functional task practice."},{"id": 5787,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Mirror therapy in stroke rehabilitation is used to:","options": [{"key": "A","text": "Replace all other rehabilitation approaches"},{"key": "B","text": "Only manage phantom limb pain, not applicable post-stroke"},{"key": "C","text": "Only used for lower limb rehabilitation, not upper limb"},{"key": "D","text": "Provide visual feedback that may facilitate motor recovery of the affected limb through cortical reorganization mechanisms"}],"correct": "D","explanation": "Mirror therapy uses visual illusion of normal movement in the affected limb to potentially facilitate motor recovery via cortical/neuroplastic mechanisms."},{"id": 5788,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which upper limb pattern is classically seen in post-stroke spastic hemiplegia?","options": [{"key": "A","text": "Shoulder adduction/internal rotation, elbow flexion, wrist/finger flexion (flexor synergy predominance)"},{"key": "B","text": "Full normal movement pattern preserved"},{"key": "C","text": "Shoulder abduction with elbow extension predominance"},{"key": "D","text": "Isolated finger extension weakness only"}],"correct": "A","explanation": "The classic post-stroke upper limb spastic pattern shows flexor synergy dominance: shoulder adduction/IR, elbow flexion, forearm pronation, wrist/finger flexion."},{"id": 5789,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which lower limb pattern is classically seen in post-stroke spastic hemiplegia during gait?","options": [{"key": "A","text": "Hip flexion with knee flexion dominance throughout stance"},{"key": "B","text": "Normal reciprocal gait pattern preserved"},{"key": "C","text": "Hip extension/adduction, knee extension, ankle plantarflexion/inversion (extensor synergy dominance)"},{"key": "D","text": "Isolated toe flexion weakness only"}],"correct": "C","explanation": "Lower limb extensor synergy dominance (hip extension/adduction, knee extension, ankle plantarflexion-inversion/equinovarus) is classically seen, contributing to circumduction gait pattern."},{"id": 5790,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Brunnstrom's stages of motor recovery after stroke describe progression through how many stages?","options": [{"key": "A","text": "Ten stages"},{"key": "B","text": "Three stages"},{"key": "C","text": "Two stages"},{"key": "D","text": "Six stages"}],"correct": "D","explanation": "Brunnstrom described six stages of motor recovery post-stroke, from flaccidity (stage 1) to normal isolated movement (stage 6)."},{"id": 5791,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "Brunnstrom Stage 1 is characterized by:","options": [{"key": "A","text": "Normal isolated joint movement"},{"key": "B","text": "Emergence of spasticity with synergy patterns"},{"key": "C","text": "Voluntary movement outside of synergy patterns"},{"key": "D","text": "Flaccidity, no voluntary movement"}],"correct": "D","explanation": "Stage 1 represents the initial flaccid phase immediately following stroke, with absence of voluntary movement."},{"id": 5792,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "Brunnstrom Stage 3 is characterized by:","options": [{"key": "A","text": "Isolated joint movements with minimal synergy influence"},{"key": "B","text": "Complete absence of movement"},{"key": "C","text": "Marked spasticity with synergy patterns performed voluntarily"},{"key": "D","text": "Normal coordinated movement"}],"correct": "C","explanation": "Stage 3 shows peak spasticity with voluntary movement occurring only within stereotyped synergy patterns."},{"id": 5793,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Homonymous hemianopia following stroke refers to:","options": [{"key": "A","text": "No visual field loss, only diplopia"},{"key": "B","text": "Loss of the entire visual field in one eye only"},{"key": "C","text": "Loss of the same half of the visual field in both eyes"},{"key": "D","text": "Loss of central vision only"}],"correct": "C","explanation": "Homonymous hemianopia involves loss of the corresponding half (same side) of the visual field in both eyes, resulting from post-chiasmal visual pathway lesions."},{"id": 5794,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Pusher syndrome (contraversive pushing) after stroke is characterized by:","options": [{"key": "A","text": "Only affecting upper limb positioning, not trunk/posture"},{"key": "B","text": "Active pushing toward the hemiparetic side with resistance to correction toward midline/unaffected side"},{"key": "C","text": "Normal postural alignment with no pushing behavior"},{"key": "D","text": "Pushing away from the hemiparetic side"}],"correct": "B","explanation": "Pusher syndrome involves patients actively pushing toward their affected side and resisting passive correction, often associated with parietal/thalamic lesions and impaired perception of vertical."},{"id": 5795,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Pusher syndrome is most commonly associated with lesions in which hemisphere?","options": [{"key": "A","text": "Only the cerebellum"},{"key": "B","text": "Either hemisphere, though often associated with right hemisphere/posterior thalamic lesions"},{"key": "C","text": "Only the dominant (left) hemisphere"},{"key": "D","text": "Only the brainstem"}],"correct": "B","explanation": "While it can occur with either hemisphere lesion, pusher syndrome has notable association with right hemisphere and posterior thalamic damage."},{"id": 5796,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Shoulder subluxation following stroke commonly results from:","options": [{"key": "A","text": "Excessive muscle tone/spasticity around the shoulder"},{"key": "B","text": "Normal muscle activity with no structural change"},{"key": "C","text": "Bony fracture of the humeral head"},{"key": "D","text": "Flaccid paralysis of shoulder girdle muscles with loss of normal joint support"}],"correct": "D","explanation": "Flaccid weakness of shoulder support muscles (particularly supraspinatus, deltoid) in the early post-stroke phase predisposes to inferior glenohumeral subluxation."},{"id": 5797,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Management strategies for post-stroke shoulder subluxation include:","options": [{"key": "A","text": "Aggressive overhead pulley exercises regardless of pain"},{"key": "B","text": "Complete immobilization in a sling permanently"},{"key": "C","text": "Proper positioning/support, functional electrical stimulation, and gradual muscle re-education"},{"key": "D","text": "Ignoring the subluxation as it resolves without intervention"}],"correct": "C","explanation": "Management combines careful positioning/support, appropriate stimulation techniques, and progressive muscle re-education, avoiding techniques that risk further joint trauma."},{"id": 5798,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Shoulder-hand syndrome (a form of complex regional pain syndrome) following stroke presents with:","options": [{"key": "A","text": "Isolated shoulder pain without hand involvement"},{"key": "B","text": "Only affects the unaffected limb"},{"key": "C","text": "Isolated hand swelling without any pain"},{"key": "D","text": "Pain, swelling, and trophic changes in the shoulder and hand of the affected side"}],"correct": "D","explanation": "Shoulder-hand syndrome presents with the classic CRPS triad of pain, swelling, and trophic/autonomic changes affecting both shoulder and hand regions."},{"id": 5799,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which factor is considered important in preventing shoulder-hand syndrome after stroke?","options": [{"key": "A","text": "Complete immobilization of the entire arm"},{"key": "B","text": "Aggressive passive stretching regardless of pain response"},{"key": "C","text": "No preventive measures exist"},{"key": "D","text": "Careful handling avoiding excessive traction/trauma to the flaccid shoulder, along with early appropriate positioning"}],"correct": "D","explanation": "Gentle, careful handling of the vulnerable flaccid shoulder along with proper positioning helps reduce risk of developing shoulder-hand syndrome."},{"id": 5800,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Dysphagia screening after stroke is critical primarily to prevent:","options": [{"key": "A","text": "Aspiration pneumonia"},{"key": "B","text": "Urinary tract infection"},{"key": "C","text": "Constipation"},{"key": "D","text": "Pressure ulcers directly"}],"correct": "A","explanation": "Undetected dysphagia significantly increases aspiration risk, a leading cause of post-stroke pneumonia and associated morbidity/mortality."},{"id": 5801,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Broca's (expressive) aphasia is characterized by:","options": [{"key": "A","text": "Normal fluent speech and comprehension"},{"key": "B","text": "Complete absence of any language function"},{"key": "C","text": "Non-fluent speech with relatively preserved comprehension"},{"key": "D","text": "Fluent but meaningless speech with poor comprehension"}],"correct": "C","explanation": "Broca's aphasia presents with effortful, non-fluent speech production while comprehension remains relatively preserved."},{"id": 5802,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Wernicke's (receptive) aphasia is characterized by:","options": [{"key": "A","text": "Non-fluent, effortful speech with good comprehension"},{"key": "B","text": "Complete mutism"},{"key": "C","text": "Fluent speech that is often meaningless/paraphasic, with impaired comprehension"},{"key": "D","text": "Normal comprehension and speech production"}],"correct": "C","explanation": "Wernicke's aphasia shows fluent but often nonsensical/paraphasic speech, with significantly impaired auditory comprehension."},{"id": 5803,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Global aphasia refers to:","options": [{"key": "A","text": "Severe impairment of both language production and comprehension"},{"key": "B","text": "Only receptive language impairment"},{"key": "C","text": "Only expressive language impairment"},{"key": "D","text": "Mild language impairment affecting only writing"}],"correct": "A","explanation": "Global aphasia represents the most severe form, with significant impairment across both expressive and receptive language domains."},{"id": 5804,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Dysarthria following stroke refers to:","options": [{"key": "A","text": "Language comprehension impairment"},{"key": "B","text": "Complete loss of voice production capacity always"},{"key": "C","text": "Motor speech impairment affecting articulation due to muscle weakness/incoordination"},{"key": "D","text": "Language formulation impairment"}],"correct": "C","explanation": "Dysarthria is a motor speech disorder from weakness/incoordination of speech musculature, distinct from the language-based impairments of aphasia."},{"id": 5805,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which stroke rehabilitation outcome measure specifically assesses upper limb motor function?","options": [{"key": "A","text": "Fugl-Meyer Assessment (upper extremity subscale)"},{"key": "B","text": "Berg Balance Scale"},{"key": "C","text": "MMSE"},{"key": "D","text": "Modified Rankin Scale exclusively"}],"correct": "A","explanation": "Fugl-Meyer Assessment is a widely used, validated tool specifically quantifying motor impairment/recovery, including a dedicated upper extremity subscale."},{"id": 5806,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "The Modified Rankin Scale (mRS) is used to assess:","options": [{"key": "A","text": "Sensory function specifically"},{"key": "B","text": "Cognitive function specifically"},{"key": "C","text": "Overall global disability/functional outcome following stroke"},{"key": "D","text": "Specific muscle strength grading"}],"correct": "C","explanation": "mRS is a widely used global disability scale (0-6) assessing overall functional outcome post-stroke."},{"id": 5807,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "The NIH Stroke Scale (NIHSS) is primarily used to:","options": [{"key": "A","text": "Assess muscle tone exclusively"},{"key": "B","text": "Quantify stroke severity in the acute setting"},{"key": "C","text": "Assess long-term functional independence"},{"key": "D","text": "Measure cognitive function exclusively"}],"correct": "B","explanation": "NIHSS is a standardized tool quantifying neurological deficit severity in acute stroke, guiding treatment decisions and prognostication."},{"id": 5808,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Post-stroke depression is a common complication that should be:","options": [{"key": "A","text": "Assumed to resolve without any intervention needed"},{"key": "B","text": "Only relevant in severe stroke cases"},{"key": "C","text": "Ignored as it has no impact on rehabilitation outcomes"},{"key": "D","text": "Actively screened for and addressed as part of comprehensive rehabilitation"}],"correct": "D","explanation": "Post-stroke depression is common and can significantly impact rehabilitation engagement/outcomes, warranting active screening and appropriate management."},{"id": 5809,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following best describes the concept of 'neuroplasticity-driven' rehabilitation approaches after stroke?","options": [{"key": "A","text": "Complete rest to allow spontaneous recovery without any intervention"},{"key": "B","text": "Utilizing intensive, repetitive, task-specific practice to promote cortical reorganization and functional recovery"},{"key": "C","text": "Passive modalities exclusively without active participation"},{"key": "D","text": "Avoiding any repetitive practice to prevent overuse"}],"correct": "B","explanation": "Modern stroke rehabilitation is grounded in neuroplasticity principles, emphasizing intensive, repetitive, meaningful task practice to drive beneficial cortical reorganization."},{"id": 5810,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Functional Electrical Stimulation (FES) is used in stroke rehabilitation primarily to:","options": [{"key": "A","text": "Cause permanent nerve damage intentionally"},{"key": "B","text": "Only provide pain relief with no motor benefit"},{"key": "C","text": "Assist muscle activation (e.g., for foot drop or shoulder subluxation) and potentially facilitate motor recovery"},{"key": "D","text": "Replace the need for any active exercise"}],"correct": "C","explanation": "FES can assist functional movement (e.g., dorsiflexion during gait) and may contribute to motor recovery through repeated activation and sensory feedback."},{"id": 5811,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Robotic-assisted therapy for post-stroke upper limb rehabilitation aims to:","options": [{"key": "A","text": "Replace all human therapist involvement entirely in every case"},{"key": "B","text": "Provide high-intensity, repetitive, task-specific practice with consistent movement assistance/resistance"},{"key": "C","text": "Cause increased spasticity intentionally"},{"key": "D","text": "Only be used for lower limb rehabilitation"}],"correct": "B","explanation": "Robotic devices facilitate intensive, consistent, repetitive practice, complementing conventional therapy approaches for motor recovery."},{"id": 5812,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which secondary prevention strategy is important for reducing recurrent stroke risk in ischemic stroke patients with atrial fibrillation?","options": [{"key": "A","text": "Anticoagulation therapy"},{"key": "B","text": "No specific secondary prevention needed"},{"key": "C","text": "Surgery is always required"},{"key": "D","text": "Antiplatelet therapy alone is always preferred over anticoagulation"}],"correct": "A","explanation": "Anticoagulation (rather than antiplatelet therapy alone) is generally the preferred secondary stroke prevention strategy for AF-related ischemic stroke, per current guidelines."},{"id": 5813,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Blood pressure management in the acute phase of ischemic stroke (before/without thrombolysis) generally follows which principle?","options": [{"key": "A","text": "Immediate hypotensive therapy is always mandated"},{"key": "B","text": "Permissive hypertension is often allowed initially to maintain cerebral perfusion, unless levels are extremely high"},{"key": "C","text": "No blood pressure monitoring is needed"},{"key": "D","text": "Aggressive immediate normalization to standard target ranges regardless of stroke type"}],"correct": "B","explanation": "Acute ischemic stroke management often allows permissive hypertension (within limits) to maintain penumbral perfusion, differing from more aggressive BP control needed with thrombolysis or hemorrhagic stroke."},{"id": 5814,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Hemorrhagic stroke management differs from ischemic stroke in that blood pressure control is generally:","options": [{"key": "A","text": "Identical in approach to ischemic stroke management"},{"key": "B","text": "Allowed to remain permissively high without intervention"},{"key": "C","text": "Irrelevant to hemorrhagic stroke management"},{"key": "D","text": "More aggressively targeted to lower levels to reduce ongoing bleeding risk"}],"correct": "D","explanation": "Hemorrhagic stroke management typically involves more aggressive blood pressure lowering to reduce hematoma expansion risk, contrasting with the more permissive approach sometimes used in ischemic stroke."},{"id": 5815,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Dysphagia management in acute stroke may include which compensatory strategy?","options": [{"key": "A","text": "Ignoring swallow assessment findings"},{"key": "B","text": "Complete removal of all oral intake permanently without reassessment"},{"key": "C","text": "Encouraging normal diet regardless of swallow assessment findings"},{"key": "D","text": "Chin-tuck positioning during swallowing and modified food/liquid consistency"}],"correct": "D","explanation": "Compensatory strategies (positioning, modified consistency) are commonly used based on swallow assessment findings to reduce aspiration risk while maintaining nutrition."},{"id": 5816,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best represents an appropriate early physiotherapy goal in the acute phase following ischemic stroke (once medically stable)?","options": [{"key": "A","text": "Complete bed rest for the first month"},{"key": "B","text": "Immediate high-intensity strength training regardless of medical stability"},{"key": "C","text": "Positioning to prevent complications, early safe mobilization, and initiating appropriate assessment"},{"key": "D","text": "Avoiding any physiotherapy involvement until full recovery has occurred"}],"correct": "C","explanation": "Early physiotherapy focuses on appropriate positioning, assessment, and progressive safe mobilization once the patient is medically stable, balancing activity with appropriate precautions."},{"id": 5817,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Ipsilateral limb ataxia combined with contralateral loss of pain/temperature sensation on the trunk/limbs and other brainstem signs is characteristic of which stroke syndrome?","options": [{"key": "A","text": "Pure motor lacunar syndrome"},{"key": "B","text": "Locked-in syndrome"},{"key": "C","text": "Anterior cerebral artery syndrome"},{"key": "D","text": "Lateral medullary (Wallenberg) syndrome"}],"correct": "D","explanation": "Wallenberg syndrome characteristically presents with ipsilateral cerebellar signs (ataxia) and ipsilateral facial sensory loss, combined with contralateral body sensory loss (crossed pattern), among other brainstem findings."},{"id": 5818,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes a key difference in prognosis between complete and partial spinal cord versus the general concept of ischemic penumbra in stroke?","options": [{"key": "A","text": "No such concept of salvageable tissue exists in stroke"},{"key": "B","text": "The penumbra always progresses to complete recovery without any intervention needed"},{"key": "C","text": "The penumbra represents potentially salvageable tissue if perfusion is restored promptly, unlike the irreversibly infarcted core"},{"key": "D","text": "The penumbra is identical to the infarct core with no difference in tissue viability"}],"correct": "C","explanation": "The ischemic penumbra represents tissue at risk but still potentially salvageable with timely reperfusion, distinct from the already infarcted, non-viable core, forming the rationale for acute reperfusion therapies."},{"id": 5819,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which upper limb positioning strategy is commonly recommended to help prevent shoulder problems in the flaccid stage post-stroke?","options": [{"key": "A","text": "Supporting the arm with pillows/armrests to maintain proper alignment and avoid unsupported dangling"},{"key": "B","text": "Allowing the arm to hang unsupported for extended periods"},{"key": "C","text": "Aggressively pulling on the arm during transfers"},{"key": "D","text": "Complete immobilization in extreme internal rotation"}],"correct": "A","explanation": "Proper support (pillows, armrests, appropriate sling use during mobilization) helps prevent shoulder subluxation and associated complications during the vulnerable flaccid phase."},{"id": 5820,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Balance training in stroke rehabilitation typically progresses from:","options": [{"key": "A","text": "Complete avoidance of any balance challenge throughout rehabilitation"},{"key": "B","text": "Random unstructured activities without progression"},{"key": "C","text": "Only dynamic tasks from the very beginning regardless of stability"},{"key": "D","text": "Static, supported positions to dynamic, less-supported/more challenging tasks"}],"correct": "D","explanation": "Balance rehabilitation follows a graded progression from stable/supported positions toward increasingly dynamic and challenging tasks as the patient's control improves."},{"id": 5821,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes the general recovery trajectory typically seen after stroke?","options": [{"key": "A","text": "Most significant spontaneous recovery occurs within the first 3-6 months, though continued improvement can occur beyond this with rehabilitation"},{"key": "B","text": "Full recovery is guaranteed for all patients within 1 week"},{"key": "C","text": "No recovery occurs after the acute phase"},{"key": "D","text": "Recovery only occurs after 2 years post-stroke, never before"}],"correct": "A","explanation": "While individual trajectories vary considerably, the most substantial spontaneous neurological recovery typically occurs within the first 3-6 months, though functional gains can continue with ongoing rehabilitation beyond this period."},{"id": 5822,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following is an important consideration when selecting appropriate outcome measures for stroke rehabilitation?","options": [{"key": "A","text": "Selecting valid, reliable, and responsive measures appropriate to the specific domain (impairment, activity, participation) being assessed"},{"key": "B","text": "Avoiding standardized measures in favor of purely subjective impression"},{"key": "C","text": "Using outcome measures only at the end of rehabilitation, never at baseline"},{"key": "D","text": "Using only one generic measure regardless of the specific rehabilitation goal"}],"correct": "A","explanation": "Appropriate outcome measurement requires selecting valid, reliable tools matched to the specific domain of interest (e.g., impairment-level Fugl-Meyer vs. participation-level measures), assessed at baseline and throughout to track progress."},{"id": 5823,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "The Oxford (Bamford) classification system categorizes ischemic stroke into which four clinical subtypes?","options": [{"key": "A","text": "TACI, PACI, LACI, POCI"},{"key": "B","text": "Only anterior and posterior circulation types"},{"key": "C","text": "Only cortical and subcortical types"},{"key": "D","text": "Type A, B, C, D based on severity only"}],"correct": "A","explanation": "Bamford classification includes Total Anterior Circulation Infarct (TACI), Partial Anterior Circulation Infarct (PACI), Lacunar Infarct (LACI), and Posterior Circulation Infarct (POCI)."},{"id": 5824,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "TOAST classification of ischemic stroke categorizes based on:","options": [{"key": "A","text": "Only anatomical location"},{"key": "B","text": "Only severity of neurological deficit"},{"key": "C","text": "Time since symptom onset only"},{"key": "D","text": "Etiology/underlying cause of stroke (e.g., large artery atherosclerosis, cardioembolism, small vessel disease)"}],"correct": "D","explanation": "TOAST classification categorizes ischemic stroke by presumed etiological mechanism, guiding secondary prevention strategy."},{"id": 5825,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Hemorrhagic transformation of an ischemic infarct refers to:","options": [{"key": "A","text": "A separate unrelated hemorrhagic stroke event"},{"key": "B","text": "Complete resolution of the infarct"},{"key": "C","text": "Normal expected healing without any bleeding component"},{"key": "D","text": "Bleeding occurring within previously infarcted ischemic brain tissue"}],"correct": "D","explanation": "Hemorrhagic transformation describes secondary bleeding into an area of ischemic infarction, a recognized complication particularly with larger infarcts or post-thrombolysis."},{"id": 5826,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following is an absolute contraindication to intravenous thrombolysis in acute ischemic stroke?","options": [{"key": "A","text": "Mild neurological deficit alone"},{"key": "B","text": "Hypertension within normal treatable range"},{"key": "C","text": "Active internal bleeding or recent significant hemorrhage"},{"key": "D","text": "Age over 18 years"}],"correct": "C","explanation": "Active bleeding or significant recent hemorrhage represents an absolute contraindication to thrombolytic therapy due to bleeding risk."},{"id": 5827,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Deep vein thrombosis (DVT) prophylaxis is an important consideration in stroke patients primarily due to:","options": [{"key": "A","text": "Only relevant if the patient is ambulatory"},{"key": "B","text": "No increased risk compared to general population"},{"key": "C","text": "Only relevant for hemorrhagic stroke patients"},{"key": "D","text": "Increased risk from immobility and paretic limb"}],"correct": "D","explanation": "Stroke-related immobility and limb paresis significantly increase DVT risk, necessitating appropriate prophylactic measures."},{"id": 5828,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes the role of a multidisciplinary stroke unit compared to general ward care?","options": [{"key": "A","text": "Associated with improved outcomes including reduced mortality and disability through coordinated specialized care"},{"key": "B","text": "Only beneficial for hemorrhagic stroke patients"},{"key": "C","text": "Increases cost without any outcome benefit"},{"key": "D","text": "No difference in outcomes compared to general ward care"}],"correct": "A","explanation": "Strong evidence supports organized stroke unit care (coordinated multidisciplinary team) as improving mortality and functional outcomes compared to general ward management."},{"id": 5829,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Central post-stroke pain syndrome (thalamic pain syndrome) is characterized by:","options": [{"key": "A","text": "Only nociceptive musculoskeletal pain"},{"key": "B","text": "Chronic neuropathic pain on the affected side, often following thalamic lesions"},{"key": "C","text": "Pain exclusively in the unaffected limb"},{"key": "D","text": "Pain that always resolves within days without intervention"}],"correct": "B","explanation": "Central post-stroke pain is a neuropathic pain syndrome, classically (though not exclusively) associated with thalamic lesions, presenting with often severe, difficult-to-treat pain on the affected side."},{"id": 5830,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which of the following gait deviations is commonly seen in a patient with post-stroke hemiplegia during the swing phase due to extensor synergy and inadequate foot clearance?","options": [{"key": "A","text": "Normal reciprocal swing pattern"},{"key": "B","text": "Circumduction of the affected lower limb"},{"key": "C","text": "Isolated hip flexor weakness without compensatory pattern"},{"key": "D","text": "Excessive knee flexion during swing without compensation"}],"correct": "B","explanation": "Circumduction (swinging the leg outward in an arc) is a common compensatory strategy for inadequate hip/knee flexion and foot clearance in spastic hemiplegic gait."},{"id": 5831,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Ankle-foot orthosis (AFO) prescription in post-stroke gait rehabilitation is commonly used to address:","options": [{"key": "A","text": "Cognitive impairment"},{"key": "B","text": "Only knee hyperextension without any ankle involvement"},{"key": "C","text": "Only hip weakness"},{"key": "D","text": "Foot drop and provide mediolateral ankle stability during stance and swing"}],"correct": "D","explanation": "AFOs commonly address foot drop (dorsiflexor weakness) and provide ankle stability, improving foot clearance during swing and stability during stance."},{"id": 5832,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes 'trunk control' importance in post-stroke rehabilitation?","options": [{"key": "A","text": "Trunk control is irrelevant to overall functional recovery"},{"key": "B","text": "Trunk control is foundational for proximal stability supporting limb function and predicts functional recovery/balance outcomes"},{"key": "C","text": "Only relevant for lower limb function, not upper limb"},{"key": "D","text": "Trunk control cannot be improved with rehabilitation"}],"correct": "B","explanation": "Trunk control provides the proximal stability base necessary for effective limb movement and is a recognized predictor of functional balance and mobility outcomes post-stroke."},{"id": 5833,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes the role of family/caregiver education in stroke rehabilitation?","options": [{"key": "A","text": "Essential component supporting safe transitions, home exercise carryover, and long-term management"},{"key": "B","text": "Should be avoided to prevent caregiver burden"},{"key": "C","text": "Only relevant for severe stroke cases"},{"key": "D","text": "Irrelevant to rehabilitation outcomes"}],"correct": "A","explanation": "Family/caregiver education is a critical component of comprehensive stroke rehabilitation, supporting safe home transition, exercise carryover, and understanding of the condition."},{"id": 5834,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following is a recognized risk factor specifically for hemorrhagic stroke?","options": [{"key": "A","text": "Anticoagulant medication use and uncontrolled hypertension"},{"key": "B","text": "Diabetes mellitus exclusively"},{"key": "C","text": "Carotid artery stenosis exclusively"},{"key": "D","text": "Atrial fibrillation exclusively"}],"correct": "A","explanation": "Anticoagulant use and poorly controlled hypertension are particularly significant risk factors for hemorrhagic stroke, distinct from the more ischemic-specific risk factors like AF/carotid stenosis."},{"id": 5835,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Cerebral amyloid angiopathy is a recognized cause of which type of stroke, particularly in elderly patients?","options": [{"key": "A","text": "TIA exclusively"},{"key": "B","text": "Lobar intracerebral hemorrhage"},{"key": "C","text": "Subarachnoid hemorrhage exclusively"},{"key": "D","text": "Ischemic stroke exclusively"}],"correct": "B","explanation": "Cerebral amyloid angiopathy is associated with recurrent lobar hemorrhages in elderly patients, distinct from typical hypertensive deep hemorrhage locations."},{"id": 5836,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Subarachnoid hemorrhage most commonly results from rupture of:","options": [{"key": "A","text": "Cardiac embolic source"},{"key": "B","text": "Small penetrating arteries (lacunar mechanism)"},{"key": "C","text": "Carotid artery atherosclerotic plaque"},{"key": "D","text": "A cerebral (berry) aneurysm"}],"correct": "D","explanation": "Ruptured cerebral (saccular/berry) aneurysm is the most common cause of spontaneous subarachnoid hemorrhage."},{"id": 5837,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Thunderclap headache' (sudden severe headache reaching maximal intensity rapidly) is a classic presenting symptom of:","options": [{"key": "A","text": "TIA typically"},{"key": "B","text": "Subarachnoid hemorrhage"},{"key": "C","text": "Lacunar stroke typically"},{"key": "D","text": "Ischemic stroke typically"}],"correct": "B","explanation": "Sudden, severe 'worst headache of life' onset is the classic presenting symptom prompting urgent investigation for subarachnoid hemorrhage."},{"id": 5838,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Vasospasm following subarachnoid hemorrhage is a significant concern typically occurring within which timeframe?","options": [{"key": "A","text": "Days 4-14 post-hemorrhage"},{"key": "B","text": "Immediately within the first hour only"},{"key": "C","text": "Never a concern following SAH"},{"key": "D","text": "After 3 months"}],"correct": "A","explanation": "Cerebral vasospasm typically peaks around days 4-14 post-SAH, risking secondary ischemic injury, requiring close monitoring during this period."},{"id": 5839,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following best describes the general principle behind graded task practice in stroke motor rehabilitation?","options": [{"key": "A","text": "Avoiding any progression to prevent frustration"},{"key": "B","text": "Providing the same difficulty level throughout the entire rehabilitation course"},{"key": "C","text": "Progressively increasing task complexity/demand as the patient's ability improves, following motor learning principles"},{"key": "D","text": "Skipping directly to the most complex tasks regardless of baseline ability"}],"correct": "C","explanation": "Graded task practice systematically progresses difficulty/complexity in line with the patient's improving capability, consistent with motor learning and neuroplasticity principles."},{"id": 5840,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which of the following statements about spasticity management in post-stroke rehabilitation is accurate?","options": [{"key": "A","text": "Spasticity never provides any functional benefit and should always be eliminated completely"},{"key": "B","text": "Management is individualized and may include stretching, positioning, splinting, and pharmacological options like botulinum toxin, depending on functional impact"},{"key": "C","text": "No management approaches exist for post-stroke spasticity"},{"key": "D","text": "Spasticity should always be maximally reduced regardless of any functional benefit it may provide"}],"correct": "B","explanation": "Spasticity management is individualized; sometimes mild spasticity can provide functional support (e.g., standing), so management targets problematic spasticity impacting function/care, using varied combined approaches."},{"id": 5841,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following is an example of a compensatory (rather than restorative) approach in stroke upper limb rehabilitation?","options": [{"key": "A","text": "Constraint-induced movement therapy aiming to restore affected limb function"},{"key": "B","text": "Robotic-assisted repetitive practice of the affected limb"},{"key": "C","text": "Task-specific practice targeting the affected limb's motor recovery"},{"key": "D","text": "Teaching one-handed techniques for dressing when significant arm impairment persists"}],"correct": "D","explanation": "Compensatory approaches (e.g., one-handed techniques) adapt the task to accommodate persistent impairment, contrasting with restorative approaches aiming to recover affected limb function."},{"id": 5842,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes an appropriate approach for addressing unilateral neglect in stroke rehabilitation?","options": [{"key": "A","text": "Always approaching the patient exclusively from the neglected side without any adaptation"},{"key": "B","text": "Ignoring the neglected side entirely during all therapy sessions"},{"key": "C","text": "Assuming neglect will resolve without any intervention needed"},{"key": "D","text": "Cueing strategies, environmental modification, and specific training to increase attention toward the neglected side"}],"correct": "D","explanation": "Management strategies for unilateral neglect include cueing, environmental setup, and specific training techniques (e.g., visual scanning training) to improve attention toward the neglected side."},{"id": 5843,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following statements about cognitive impairment following stroke is accurate?","options": [{"key": "A","text": "Cognitive impairment never occurs following stroke, only motor deficits are relevant"},{"key": "B","text": "Cognitive assessment is not relevant to physiotherapy practice"},{"key": "C","text": "Cognitive impairment (e.g., attention, memory) is common and can significantly affect rehabilitation participation and outcomes"},{"key": "D","text": "Cognitive impairment always resolves completely within one week"}],"correct": "C","explanation": "Cognitive impairments are common post-stroke and can significantly influence rehabilitation engagement, learning, and safety, making cognitive screening relevant across the rehabilitation team including physiotherapy."},{"id": 5844,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following is an important safety consideration when mobilizing a patient with significant hemianopia following stroke?","options": [{"key": "A","text": "No special precautions are needed for visual field deficits"},{"key": "B","text": "Complete avoidance of any mobilization until the deficit resolves"},{"key": "C","text": "Only relevant for wheelchair users, not ambulatory patients"},{"key": "D","text": "Awareness of the visual field deficit to prevent collisions/falls, with appropriate environmental setup and compensatory strategies"}],"correct": "D","explanation": "Awareness and compensation for visual field deficits (e.g., approaching from the seeing side, environmental setup) are important safety considerations during mobilization and functional training."},{"id": 5845,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which of the following best describes the concept of 'use-dependent plasticity' relevant to stroke motor recovery?","options": [{"key": "A","text": "Only relevant in the pediatric population, not adult stroke recovery"},{"key": "B","text": "Neural circuits are fixed and unaffected by patterns of limb use"},{"key": "C","text": "Neural circuits are shaped by the pattern and amount of limb use, underpinning both recovery potential and risk of maladaptive patterns with disuse"},{"key": "D","text": "Only applies to sensory pathways, not motor pathways"}],"correct": "C","explanation": "Use-dependent plasticity describes how neural reorganization is shaped by patterns of activity/use, forming the rationale for intensive practice approaches while also explaining risks like learned non-use."},{"id": 5846,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following statements about post-stroke fatigue is accurate?","options": [{"key": "A","text": "Fatigue only occurs in the first 24 hours post-stroke"},{"key": "B","text": "Post-stroke fatigue is rare and clinically insignificant"},{"key": "C","text": "Fatigue has no relationship to rehabilitation engagement"},{"key": "D","text": "Post-stroke fatigue is common, can persist for months to years, and may significantly impact rehabilitation participation"}],"correct": "D","explanation": "Post-stroke fatigue is a common, often under-recognized symptom that can persist long-term and significantly affect participation in rehabilitation and daily activities."},{"id": 5847,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes appropriate exercise intensity considerations for cardiovascular conditioning in stroke rehabilitation?","options": [{"key": "A","text": "Individualized prescription considering cardiovascular status, medications, and stroke-specific impairments, following general exercise prescription principles adapted to the individual"},{"key": "B","text": "Avoidance of any cardiovascular exercise in all stroke patients"},{"key": "C","text": "Maximum intensity exercise from the first rehabilitation session regardless of medical clearance"},{"key": "D","text": "A single fixed intensity applied uniformly to all stroke patients regardless of status"}],"correct": "A","explanation": "Cardiovascular exercise prescription for stroke survivors should be individualized based on medical status, cardiovascular risk factors, and functional capacity, following established exercise prescription guidelines adapted to stroke-specific considerations."},{"id": 5848,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an appropriate approach when a patient exhibits signs of pusher syndrome during rehabilitation?","options": [{"key": "A","text": "Assuming pusher syndrome cannot be improved with any rehabilitation approach"},{"key": "B","text": "Ignoring the pushing behavior entirely without any specific intervention"},{"key": "C","text": "Restraining the patient completely to prevent any pushing movement"},{"key": "D","text": "Providing visual feedback and specific retraining strategies to address the altered perception of vertical, avoiding simply pushing the patient back to midline forcefully"}],"correct": "D","explanation": "Specific therapeutic approaches addressing the underlying perceptual distortion (e.g., visual feedback, specific retraining protocols) are more effective than simply forcing correction, which patients will resist."},{"id": 5849,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following is a recognized long-term complication risk in stroke survivors with persistent significant hemiplegia if joint positioning/ROM maintenance is neglected?","options": [{"key": "A","text": "Improved joint mobility without any intervention needed"},{"key": "B","text": "Joint contractures"},{"key": "C","text": "Complete spontaneous resolution of any positioning issues"},{"key": "D","text": "No risk of any musculoskeletal complications"}],"correct": "B","explanation": "Without appropriate positioning and ROM maintenance, prolonged abnormal tone/immobility can lead to joint contractures, a preventable complication requiring proactive management."},{"id": 5850,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which of the following best describes the general principle guiding gait rehabilitation intensity/dosage in evidence-based stroke practice?","options": [{"key": "A","text": "Lower intensity is always superior regardless of patient tolerance"},{"key": "B","text": "Higher intensity and repetition of task-specific gait practice is generally associated with better mobility outcomes, within safe tolerable limits"},{"key": "C","text": "Only a single gait training session is needed for full recovery"},{"key": "D","text": "Gait practice intensity has no relationship to outcomes"}],"correct": "B","explanation": "Evidence generally supports higher intensity/repetition of task-specific gait practice for improved mobility outcomes, though individualized based on patient tolerance and safety."},{"id": 5851,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes an appropriate consideration when working with a stroke patient who has significant aphasia during physiotherapy sessions?","options": [{"key": "A","text": "Using simplified language, visual demonstration, and allowing adequate response time to support communication and participation"},{"key": "B","text": "Avoiding any communication attempts and relying solely on physical guidance"},{"key": "C","text": "Assuming the patient cannot participate meaningfully in therapy decisions"},{"key": "D","text": "Speaking loudly and quickly to compensate for the aphasia"}],"correct": "A","explanation": "Adapting communication approaches (simplified language, demonstration, patience) supports meaningful engagement and safety for patients with aphasia during rehabilitation."},{"id": 5852,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best summarizes current evidence-based practice regarding the timing and intensity balance in post-stroke rehabilitation?","options": [{"key": "A","text": "Early, appropriately dosed mobilization and rehabilitation is generally beneficial, though extremely early very-high-dose protocols require careful individualized consideration based on emerging trial evidence"},{"key": "B","text": "Maximum intensity from day one is always safe and beneficial for every patient regardless of medical status"},{"key": "C","text": "Rehabilitation timing and intensity have no bearing on functional outcomes"},{"key": "D","text": "Rehabilitation should always be delayed until at least 6 months post-stroke"}],"correct": "A","explanation": "Current evidence supports timely, appropriately individualized rehabilitation, balancing the benefits of early mobilization/task practice against emerging evidence suggesting caution with very early excessive intensity in some contexts."},{"id": 5853,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Traumatic brain injury severity is commonly classified based on which initial assessment tool?","options": [{"key": "A","text": "Glasgow Coma Scale score"},{"key": "B","text": "MRC scale"},{"key": "C","text": "Modified Ashworth Scale"},{"key": "D","text": "Berg Balance Scale"}],"correct": "A","explanation": "GCS score at presentation is the standard tool for initial TBI severity classification (mild, moderate, severe)."},{"id": 5854,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "A GCS score of 13-15 is generally classified as which severity of TBI?","options": [{"key": "A","text": "Moderate"},{"key": "B","text": "Not classifiable using GCS"},{"key": "C","text": "Mild"},{"key": "D","text": "Severe"}],"correct": "C","explanation": "GCS 13-15 is generally classified as mild TBI, though clinical correlation and imaging findings are also considered."},{"id": 5855,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "A GCS score of 9-12 is generally classified as which severity of TBI?","options": [{"key": "A","text": "Moderate"},{"key": "B","text": "Severe"},{"key": "C","text": "Not classifiable using GCS"},{"key": "D","text": "Mild"}],"correct": "A","explanation": "GCS 9-12 represents moderate TBI classification."},{"id": 5856,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A GCS score of 3-8 is generally classified as which severity of TBI?","options": [{"key": "A","text": "Severe"},{"key": "B","text": "Normal, no injury present"},{"key": "C","text": "Moderate"},{"key": "D","text": "Mild"}],"correct": "A","explanation": "GCS 3-8 represents severe TBI, often associated with coma."},{"id": 5857,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Diffuse axonal injury (DAI) results from which mechanism?","options": [{"key": "A","text": "Focal direct impact only"},{"key": "B","text": "Only penetrating injury"},{"key": "C","text": "Rotational/shear forces causing widespread axonal stretching and damage"},{"key": "D","text": "Only vascular occlusion"}],"correct": "C","explanation": "DAI results from rotational acceleration-deceleration forces causing widespread shearing injury to axons, common in high-velocity trauma."},{"id": 5858,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A coup-contrecoup injury pattern refers to:","options": [{"key": "A","text": "A specific type of skull fracture only"},{"key": "B","text": "Injury occurring only in the brainstem"},{"key": "C","text": "Brain injury occurring both at the site of impact and the opposite side due to brain movement within the skull"},{"key": "D","text": "Injury occurring only at the impact site"}],"correct": "C","explanation": "Coup-contrecoup injuries occur from brain impacting the skull at the point of contact and then rebounding to impact the opposite side."},{"id": 5859,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Post-traumatic amnesia (PTA) duration is used as a measure of:","options": [{"key": "A","text": "Only relevant for penetrating injuries"},{"key": "B","text": "TBI severity and prognostic indicator for recovery"},{"key": "C","text": "Cognitive function unrelated to injury severity"},{"key": "D","text": "Motor recovery specifically"}],"correct": "B","explanation": "PTA duration correlates with injury severity and is a useful prognostic indicator, with longer PTA generally associated with worse outcomes."},{"id": 5860,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Easy","question": "The Rancho Los Amigos Scale is used to assess:","options": [{"key": "A","text": "Cognitive and behavioral recovery levels following TBI"},{"key": "B","text": "Motor strength grading"},{"key": "C","text": "Balance ability"},{"key": "D","text": "Sensory function"}],"correct": "A","explanation": "Rancho Los Amigos Levels of Cognitive Functioning Scale (I-VIII/X) describes stages of cognitive-behavioral recovery post-TBI, guiding rehabilitation approach."},{"id": 5861,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Rancho Los Amigos Level I is characterized by:","options": [{"key": "A","text": "No response to stimuli"},{"key": "B","text": "Purposeful, appropriate response"},{"key": "C","text": "Confused, agitated response"},{"key": "D","text": "Automatic, appropriate response"}],"correct": "A","explanation": "Level I represents no observable response to any stimulation, the most severe/earliest level of the scale."},{"id": 5862,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Rancho Los Amigos Level IV is characterized by:","options": [{"key": "A","text": "Purposeful, appropriate response with full orientation"},{"key": "B","text": "No response at all"},{"key": "C","text": "Automatic, appropriate response with carryover for new learning"},{"key": "D","text": "Confused, agitated behavior with heightened, often non-purposeful activity"}],"correct": "D","explanation": "Level IV represents a confused, agitated state with heightened activity, often requiring careful environmental management to reduce overstimulation."},{"id": 5863,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Physiotherapy management during Rancho Los Amigos Level IV (confused-agitated) typically emphasizes:","options": [{"key": "A","text": "Providing a calm, structured, low-stimulation environment while maintaining safety and basic mobility"},{"key": "B","text": "Full participation in group therapy sessions"},{"key": "C","text": "High-intensity cognitive-motor dual tasking"},{"key": "D","text": "Complex multi-step functional training"}],"correct": "A","explanation": "Managing agitation with a calm, structured, low-stimulus approach while maintaining safety is prioritized at this cognitively vulnerable stage."},{"id": 5864,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Decorticate posturing (flexion of upper limbs, extension of lower limbs) suggests lesion at which level?","options": [{"key": "A","text": "Above the level of the red nucleus (cerebral hemispheres/diencephalon)"},{"key": "B","text": "Below the level of the red nucleus (brainstem, midbrain-pons)"},{"key": "C","text": "Peripheral nerve level"},{"key": "D","text": "Muscle level exclusively"}],"correct": "A","explanation": "Decorticate posturing suggests a lesion above the red nucleus, typically cerebral hemisphere or diencephalic damage."},{"id": 5865,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Decerebrate posturing (extension of both upper and lower limbs) suggests lesion at which level, generally indicating worse prognosis than decorticate posturing?","options": [{"key": "A","text": "Peripheral nerve level"},{"key": "B","text": "Spinal cord level exclusively"},{"key": "C","text": "Above the level of the red nucleus (cerebral cortex)"},{"key": "D","text": "Below the level of the red nucleus (midbrain-pons)"}],"correct": "D","explanation": "Decerebrate posturing indicates a more caudal brainstem lesion (below red nucleus), generally associated with worse prognosis than decorticate posturing."},{"id": 5866,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Increased intracranial pressure (ICP) following severe TBI is a critical concern primarily because it can lead to:","options": [{"key": "A","text": "Reduced cerebral perfusion pressure and risk of brain herniation"},{"key": "B","text": "Only affects peripheral nerve function"},{"key": "C","text": "Improved cerebral blood flow"},{"key": "D","text": "No clinically significant consequences"}],"correct": "A","explanation": "Elevated ICP compromises cerebral perfusion pressure (CPP = MAP - ICP) and risks life-threatening brain herniation if uncontrolled."},{"id": 5867,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Cerebral perfusion pressure (CPP) is calculated as:","options": [{"key": "A","text": "Systolic blood pressure minus diastolic blood pressure"},{"key": "B","text": "Heart rate multiplied by stroke volume"},{"key": "C","text": "Mean arterial pressure minus intracranial pressure (MAP - ICP)"},{"key": "D","text": "ICP multiplied by 2"}],"correct": "C","explanation": "CPP = MAP - ICP, representing the pressure gradient driving cerebral blood flow; maintaining adequate CPP is critical in severe TBI management."},{"id": 5868,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Decompressive craniectomy may be performed in severe TBI management primarily to:","options": [{"key": "A","text": "Improve cognitive function directly"},{"key": "B","text": "Treat peripheral nerve injury"},{"key": "C","text": "Relieve elevated intracranial pressure refractory to medical management"},{"key": "D","text": "Repair skull fracture cosmetically only"}],"correct": "C","explanation": "Decompressive craniectomy removes a portion of the skull to allow brain swelling room, reducing otherwise refractory elevated ICP."},{"id": 5869,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Post-traumatic hydrocephalus following TBI results from:","options": [{"key": "A","text": "Disrupted CSF absorption/circulation, often related to subarachnoid hemorrhage or intraventricular blood"},{"key": "B","text": "Muscle atrophy"},{"key": "C","text": "Direct penetrating skull injury exclusively"},{"key": "D","text": "Peripheral nerve damage"}],"correct": "A","explanation": "Post-traumatic hydrocephalus can develop from impaired CSF dynamics, often related to blood products interfering with CSF absorption pathways."},{"id": 5870,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Heterotopic ossification, a recognized complication following severe TBI, refers to:","options": [{"key": "A","text": "Joint dislocation"},{"key": "B","text": "Abnormal bone formation in soft tissue, commonly around joints"},{"key": "C","text": "Bone density loss"},{"key": "D","text": "Muscle contracture without any bony change"}],"correct": "B","explanation": "Heterotopic ossification involves abnormal ectopic bone formation in periarticular soft tissues, a recognized complication of severe TBI and SCI."},{"id": 5871,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which joints are most commonly affected by heterotopic ossification following severe brain injury?","options": [{"key": "A","text": "Only the temporomandibular joint"},{"key": "B","text": "Only the spine"},{"key": "C","text": "Only small joints of the hand"},{"key": "D","text": "Hip, elbow, shoulder, and knee"}],"correct": "D","explanation": "HO classically affects large joints including hip, elbow, shoulder, and knee, often in the context of spasticity and immobility."},{"id": 5872,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Post-traumatic seizures following TBI are classified as 'early' if they occur within:","options": [{"key": "A","text": "Never classified by timing"},{"key": "B","text": "The first year post-injury"},{"key": "C","text": "Only within the first hour"},{"key": "D","text": "The first 7 days post-injury"}],"correct": "D","explanation": "Early post-traumatic seizures occur within 7 days of injury, distinguished from late seizures (>7 days), which carry different implications for long-term epilepsy risk."},{"id": 5873,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Cognitive rehabilitation following TBI commonly addresses which domains?","options": [{"key": "A","text": "Attention, memory, executive function, and problem-solving"},{"key": "B","text": "Only muscle strength"},{"key": "C","text": "Only vestibular function"},{"key": "D","text": "Only speech articulation"}],"correct": "A","explanation": "Cognitive rehabilitation targets domains commonly affected by TBI including attention, memory, and executive functions critical for daily function."},{"id": 5874,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Executive dysfunction following TBI, particularly with frontal lobe involvement, commonly presents with:","options": [{"key": "A","text": "Only visual field defects"},{"key": "B","text": "Only motor weakness"},{"key": "C","text": "Only sensory loss"},{"key": "D","text": "Impaired planning, judgment, impulse control, and problem-solving"}],"correct": "D","explanation": "Frontal lobe damage commonly impairs executive functions including planning, judgment, self-regulation, and problem-solving abilities."},{"id": 5875,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Agitation management following TBI in the acute recovery phase typically emphasizes:","options": [{"key": "A","text": "Environmental modification, structured routine, and minimizing overstimulation before considering pharmacological intervention"},{"key": "B","text": "Immediate physical restraint as first-line management"},{"key": "C","text": "Ignoring agitated behavior entirely"},{"key": "D","text": "Maximizing environmental stimulation to promote arousal"}],"correct": "A","explanation": "Non-pharmacological strategies (environmental modification, structure, reduced stimulation) are generally prioritized initially in managing post-TBI agitation."},{"id": 5876,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Post-concussion syndrome refers to:","options": [{"key": "A","text": "A syndrome unrelated to head injury"},{"key": "B","text": "Persistent symptoms (headache, dizziness, cognitive difficulty) following mild TBI beyond the expected recovery period"},{"key": "C","text": "Symptoms only present in the first 24 hours"},{"key": "D","text": "A syndrome exclusive to severe TBI"}],"correct": "B","explanation": "Post-concussion syndrome describes persistent symptoms following mild TBI/concussion that extend beyond typical recovery timeframes."},{"id": 5877,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Vestibular dysfunction following TBI/concussion commonly presents with:","options": [{"key": "A","text": "Only speech impairment"},{"key": "B","text": "Dizziness, imbalance, and visual disturbance with head movement"},{"key": "C","text": "Only motor weakness"},{"key": "D","text": "Only cognitive impairment without any physical symptoms"}],"correct": "B","explanation": "Vestibular symptoms (dizziness, imbalance, oculomotor dysfunction) are common following TBI/concussion, often warranting specific vestibular rehabilitation."},{"id": 5878,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Return-to-activity/sport protocols following concussion emphasize:","options": [{"key": "A","text": "Immediate return once headache resolves for a few hours"},{"key": "B","text": "No specific protocol is needed, return whenever desired"},{"key": "C","text": "Complete avoidance of any physical activity indefinitely"},{"key": "D","text": "Gradual, symptom-limited stepwise progression before full unrestricted return"}],"correct": "D","explanation": "Structured graduated return protocols with symptom monitoring at each stage are recommended before full unrestricted return to activity/sport following concussion."},{"id": 5879,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which factor is important in TBI rehabilitation planning regarding family/caregiver involvement?","options": [{"key": "A","text": "Family involvement should be minimized to avoid interference"},{"key": "B","text": "Family involvement is irrelevant to rehabilitation outcomes"},{"key": "C","text": "Only relevant for pediatric TBI, not adult cases"},{"key": "D","text": "Family education and involvement are important for carryover, safety, and long-term support planning"}],"correct": "D","explanation": "Family/caregiver education and involvement are important components of comprehensive TBI rehabilitation given the often significant long-term care and support needs."},{"id": 5880,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Dysautonomia (paroxysmal sympathetic hyperactivity) following severe TBI presents with:","options": [{"key": "A","text": "Episodes of increased heart rate, blood pressure, temperature, sweating, and posturing"},{"key": "B","text": "Only isolated bradycardia without other symptoms"},{"key": "C","text": "Only cognitive symptoms without autonomic changes"},{"key": "D","text": "A condition unrelated to TBI severity"}],"correct": "A","explanation": "Paroxysmal sympathetic hyperactivity (dysautonomia) presents with episodic autonomic storms (tachycardia, hypertension, hyperthermia, diaphoresis, posturing), seen particularly in severe/diffuse TBI."},{"id": 5881,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes appropriate physiotherapy considerations for a TBI patient with associated dysautonomia episodes during treatment sessions?","options": [{"key": "A","text": "Assuming dysautonomia has no relevance to physiotherapy sessions"},{"key": "B","text": "Continuing therapy at full intensity regardless of autonomic symptoms"},{"key": "C","text": "Monitoring vital signs, recognizing triggers, and modifying/pausing treatment during autonomic storm episodes"},{"key": "D","text": "Ignoring vital sign changes during treatment sessions"}],"correct": "C","explanation": "Awareness of dysautonomia and appropriate monitoring/modification of treatment during episodes is important for patient safety during TBI rehabilitation."},{"id": 5882,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following is a recognized long-term outcome consideration following moderate-severe TBI?","options": [{"key": "A","text": "Complete resolution of all deficits within one month in all cases"},{"key": "B","text": "No long-term impact on any patient regardless of severity"},{"key": "C","text": "Persistent cognitive, physical, and behavioral changes affecting long-term function and community reintegration"},{"key": "D","text": "Only physical deficits occur, no cognitive/behavioral impact"}],"correct": "C","explanation": "Moderate-severe TBI can result in persistent multidomain (cognitive, physical, behavioral) impairments significantly impacting long-term function and community reintegration, necessitating comprehensive ongoing rehabilitation planning."},{"id": 5883,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding return-to-work/school planning after TBI?","options": [{"key": "A","text": "Immediate full return with no modifications regardless of residual impairment"},{"key": "B","text": "Permanent restriction from any work/school activity in all cases"},{"key": "C","text": "Gradual, individualized return with appropriate accommodations based on residual cognitive/physical impairments"},{"key": "D","text": "Return timing is irrelevant to functional outcome"}],"correct": "C","explanation": "Individualized, often graduated return-to-work/school planning with appropriate accommodations supports successful reintegration considering residual impairments."},{"id": 5884,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Sensory overload/overstimulation is a particular concern in early TBI rehabilitation because it can:","options": [{"key": "A","text": "Only affect patients with mild TBI"},{"key": "B","text": "Have no impact on patient presentation"},{"key": "C","text": "Exacerbate agitation and confusion, hindering recovery progress"},{"key": "D","text": "Always improve cognitive recovery regardless of amount"}],"correct": "C","explanation": "Excessive environmental stimulation can worsen agitation/confusion in vulnerable early recovery stages, necessitating careful environmental management."},{"id": 5885,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Balance and vestibular rehabilitation following TBI-related dizziness typically includes:","options": [{"key": "A","text": "Only cognitive exercises, no physical component"},{"key": "B","text": "Habituation exercises, gaze stabilization, and balance training tailored to specific vestibular deficits"},{"key": "C","text": "Only medication management without any exercise component"},{"key": "D","text": "Complete avoidance of any head movement exercises indefinitely"}],"correct": "B","explanation": "Vestibular rehabilitation uses targeted exercises (habituation, gaze stabilization, balance training) addressing the specific vestibular impairment identified on assessment."},{"id": 5886,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following is an example of a compensatory cognitive strategy commonly taught in TBI rehabilitation for memory impairment?","options": [{"key": "A","text": "Using external memory aids such as notebooks, phone reminders, or structured routines"},{"key": "B","text": "Avoiding any strategy and hoping for spontaneous full recovery"},{"key": "C","text": "Restricting all daily activities requiring memory"},{"key": "D","text": "Relying solely on internal memory retraining without any external aids"}],"correct": "A","explanation": "External compensatory strategies (memory aids, structured routines) are commonly employed to support functional memory performance in TBI rehabilitation."},{"id": 5887,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to exercise/physical activity prescription in a patient recovering from moderate-severe TBI with associated motor impairment?","options": [{"key": "A","text": "Maximum intensity exercise regardless of medical stability or cognitive status"},{"key": "B","text": "A single standardized exercise program applied uniformly regardless of specific impairments"},{"key": "C","text": "Individualized progressive program addressing specific motor/cognitive impairments, considering safety and any medical precautions"},{"key": "D","text": "Complete avoidance of any physical activity throughout recovery"}],"correct": "C","explanation": "TBI rehabilitation requires individualized programming addressing the specific pattern of motor/cognitive impairment while considering safety and medical status."},{"id": 5888,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following is a recognized risk factor increasing the likelihood of chronic traumatic encephalopathy (CTE), associated with repetitive head trauma?","options": [{"key": "A","text": "Isolated spinal cord injury"},{"key": "B","text": "Peripheral nerve injury unrelated to head trauma"},{"key": "C","text": "A single mild concussion without any repeat injury"},{"key": "D","text": "Repeated concussive/subconcussive head impacts, often in contact sports"}],"correct": "D","explanation": "CTE is associated with repetitive head trauma exposure, often seen in contact sport athletes with multiple concussive/subconcussive impacts over time."},{"id": 5889,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes the relevance of pupillary examination findings in acute severe TBI assessment?","options": [{"key": "A","text": "Asymmetric or non-reactive pupils can indicate raised intracranial pressure or herniation, requiring urgent medical attention"},{"key": "B","text": "Pupillary examination is only relevant for ophthalmology referral, not acute management"},{"key": "C","text": "Pupillary changes only occur with peripheral nerve injury"},{"key": "D","text": "Pupillary findings are irrelevant to TBI severity assessment"}],"correct": "A","explanation": "Pupillary asymmetry/non-reactivity is a critical clinical sign potentially indicating raised ICP or herniation, requiring urgent medical/surgical evaluation."},{"id": 5890,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following is a recognized consideration regarding sleep disturbance following TBI?","options": [{"key": "A","text": "Sleep issues have no relevance to rehabilitation outcomes"},{"key": "B","text": "Sleep disturbances are common post-TBI and can negatively impact cognitive recovery and rehabilitation participation"},{"key": "C","text": "Sleep disturbance only affects patients with mild TBI, never moderate-severe"},{"key": "D","text": "Sleep disturbance never occurs following TBI"}],"correct": "B","explanation": "Sleep disturbances are commonly reported following TBI across severity levels and can negatively affect cognitive function and overall rehabilitation engagement, warranting attention in comprehensive management."},{"id": 5891,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an important consideration when assessing readiness for higher-level mobility/balance tasks in TBI rehabilitation?","options": [{"key": "A","text": "Considering both physical capacity and cognitive/behavioral factors (e.g., impulsivity, safety awareness) that may affect safe task performance"},{"key": "B","text": "Readiness assessment is unnecessary; all patients should attempt maximum difficulty tasks immediately"},{"key": "C","text": "Only physical strength needs to be considered, cognitive factors are irrelevant"},{"key": "D","text": "Cognitive factors alone determine readiness, physical capacity is irrelevant"}],"correct": "A","explanation": "TBI rehabilitation requires considering both physical and cognitive/behavioral factors (e.g., impulsivity, insight, safety awareness) that can significantly impact safe performance of mobility tasks."},{"id": 5892,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the general prognosis relationship between initial GCS score and long-term functional outcome following TBI?","options": [{"key": "A","text": "Lower initial GCS scores are generally associated with worse long-term functional prognosis, though individual variation and other factors also play a significant role"},{"key": "B","text": "GCS score has no relationship to long-term outcome"},{"key": "C","text": "Higher initial GCS always guarantees complete recovery with no possibility of long-term impairment"},{"key": "D","text": "Only imaging findings determine prognosis, GCS is irrelevant"}],"correct": "A","explanation": "While individual outcomes vary considerably and depend on multiple factors, lower initial GCS scores are generally associated with worse long-term functional prognosis on a population level."},{"id": 5893,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "An epidural hematoma classically presents clinically with which pattern?","options": [{"key": "A","text": "Immediate permanent coma without any recovery period"},{"key": "B","text": "Gradual onset over weeks without any lucid interval"},{"key": "C","text": "No loss of consciousness at any point"},{"key": "D","text": "Initial loss of consciousness, a 'lucid interval', followed by rapid neurological deterioration"}],"correct": "D","explanation": "The classic epidural hematoma presentation includes initial LOC, a lucid interval as the hematoma slowly expands, then rapid deterioration as ICP rises critically."},{"id": 5894,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following is an important physiotherapy consideration for a TBI patient with a ventriculoperitoneal (VP) shunt in place?","options": [{"key": "A","text": "Shunts always contraindicate any physiotherapy involvement"},{"key": "B","text": "Awareness of shunt precautions and monitoring for signs of shunt malfunction (e.g., headache, altered consciousness) during rehabilitation"},{"key": "C","text": "Shunt malfunction cannot be assessed by physiotherapy staff observation"},{"key": "D","text": "No special considerations are needed regarding the shunt"}],"correct": "B","explanation": "Physiotherapists should be aware of shunt-related precautions and vigilant for signs suggestive of shunt malfunction, which requires urgent medical attention."},{"id": 5895,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Tetraplegia (quadriplegia) refers to impairment resulting from injury at which spinal level?","options": [{"key": "A","text": "Thoracic or lumbar segments, affecting only lower limbs"},{"key": "B","text": "Only affecting bowel/bladder function"},{"key": "C","text": "Cervical spinal cord segments, affecting all four limbs"},{"key": "D","text": "Only affecting one upper limb"}],"correct": "C","explanation": "Tetraplegia results from cervical spinal cord injury, affecting motor/sensory function in all four limbs and trunk."},{"id": 5896,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Paraplegia refers to impairment resulting from injury at which spinal level?","options": [{"key": "A","text": "Brainstem level"},{"key": "B","text": "Cervical segments, affecting all four limbs"},{"key": "C","text": "Thoracic, lumbar, or sacral segments, sparing upper limb function"},{"key": "D","text": "Cerebral cortex level"}],"correct": "C","explanation": "Paraplegia results from spinal cord injury at thoracic, lumbar, or sacral levels, with upper limb function typically preserved."},{"id": 5897,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A C4 complete tetraplegic patient's functional respiratory status is a major concern because:","options": [{"key": "A","text": "Only upper limb function is affected, breathing is unaffected"},{"key": "B","text": "Respiratory function is never affected at this level"},{"key": "C","text": "The diaphragm (C3-C5) may be significantly compromised, risking respiratory insufficiency"},{"key": "D","text": "C4 level injuries do not affect any vital function"}],"correct": "C","explanation": "Since the phrenic nerve (innervating the diaphragm) arises from C3-C5, injuries at or above C4 significantly risk respiratory compromise requiring close monitoring/possible ventilatory support."},{"id": 5898,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "A patient with a C6 complete spinal cord injury would be expected to have functional use of which muscle group, enabling tenodesis grip?","options": [{"key": "A","text": "Full trunk control"},{"key": "B","text": "Finger flexors with full intrinsic hand function"},{"key": "C","text": "Wrist extensors (allowing passive tenodesis grasp)"},{"key": "D","text": "Triceps with full elbow extension strength"}],"correct": "C","explanation": "C6 level typically preserves wrist extensor function, enabling a passive tenodesis grasp mechanism (wrist extension causing passive finger flexion) despite absent finger flexor/intrinsic function."},{"id": 5899,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "A patient with C7 complete tetraplegia would typically have functional triceps, enabling:","options": [{"key": "A","text": "Independent transfers and wheelchair propulsion with active elbow extension"},{"key": "B","text": "No functional improvement over C6 level"},{"key": "C","text": "Complete lower limb function"},{"key": "D","text": "Full hand intrinsic muscle function"}],"correct": "A","explanation": "C7 level preservation of triceps (elbow extension) significantly improves independence in transfers and wheelchair mobility compared to more proximal levels."},{"id": 5900,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "A patient with T1 complete paraplegia would be expected to have:","options": [{"key": "A","text": "Full upper limb function including intrinsic hand muscles, with paraplegia affecting trunk/lower limbs"},{"key": "B","text": "Complete independence in ambulation without any assistive device"},{"key": "C","text": "No upper limb function at all"},{"key": "D","text": "Only shoulder function preserved"}],"correct": "A","explanation": "T1 level preserves full upper limb function (including hand intrinsics), with the injury affecting trunk stability and lower limb function."},{"id": 5901,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Central cord syndrome classically presents with:","options": [{"key": "A","text": "Motor weakness disproportionately greater in the upper limbs compared to lower limbs"},{"key": "B","text": "Motor weakness disproportionately greater in lower limbs"},{"key": "C","text": "Complete symmetric paralysis of all four limbs equally"},{"key": "D","text": "Isolated sensory loss without any motor involvement"}],"correct": "A","explanation": "Central cord syndrome, often from hyperextension injury in a stenotic canal, characteristically shows greater upper limb than lower limb weakness due to the somatotopic organization of the corticospinal tract."},{"id": 5902,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Anterior cord syndrome presents with:","options": [{"key": "A","text": "Complete preservation of all function"},{"key": "B","text": "Loss of proprioception only"},{"key": "C","text": "Loss of motor function and pain/temperature sensation below the lesion, with relative preservation of proprioception/vibration"},{"key": "D","text": "Only affecting one side of the body"}],"correct": "C","explanation": "Anterior cord syndrome (affecting the anterior 2/3 of the cord, typically from anterior spinal artery compromise) spares the posteriorly-located dorsal columns, preserving proprioception/vibration while causing motor and pain/temperature loss."},{"id": 5903,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Posterior cord syndrome presents primarily with:","options": [{"key": "A","text": "Loss of proprioception and vibration sense, with relative preservation of motor function and pain/temperature sensation"},{"key": "B","text": "Bilateral upper limb weakness only"},{"key": "C","text": "Complete motor paralysis with intact sensation"},{"key": "D","text": "Loss of pain/temperature only"}],"correct": "A","explanation": "Posterior cord syndrome (rare) affects the dorsal columns, causing proprioceptive/vibratory loss while relatively sparing motor function and pain/temperature sensation."},{"id": 5904,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Brown-Sequard syndrome (spinal cord hemisection) presents with:","options": [{"key": "A","text": "Only motor loss, no sensory involvement"},{"key": "B","text": "Ipsilateral motor and proprioceptive loss with contralateral pain/temperature loss below the lesion"},{"key": "C","text": "Bilateral symmetric loss of all modalities"},{"key": "D","text": "Only sensory loss, no motor involvement"}],"correct": "B","explanation": "Hemisection affects ipsilateral corticospinal (motor) and dorsal column (proprioception) pathways, while the already-crossed spinothalamic tract causes contralateral pain/temperature loss."},{"id": 5905,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Cauda equina syndrome, resulting from injury below the conus medullaris, is characterized by:","options": [{"key": "A","text": "Only affecting upper limb function"},{"key": "B","text": "Lower motor neuron pattern deficits (flaccid, areflexic) with possible saddle anesthesia and bowel/bladder dysfunction"},{"key": "C","text": "Complete preservation of bowel/bladder function always"},{"key": "D","text": "Upper motor neuron pattern deficits with spasticity and hyperreflexia"}],"correct": "B","explanation": "Cauda equina involves peripheral nerve roots, producing LMN-type deficits (flaccidity, areflexia) rather than the UMN pattern seen with true spinal cord (above conus) injury."},{"id": 5906,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Spinal shock following acute spinal cord injury is characterized by:","options": [{"key": "A","text": "Permanent unchanging neurological status"},{"key": "B","text": "Temporary areflexia and flaccidity below the injury level"},{"key": "C","text": "Complete preservation of all reflexes"},{"key": "D","text": "Immediate hyperreflexia and spasticity from the moment of injury"}],"correct": "B","explanation": "Spinal shock represents a temporary physiological state of reduced/absent reflex activity below the injury, typically resolving over days to weeks."},{"id": 5907,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Autonomic dysreflexia is a potentially life-threatening complication typically occurring in SCI at or above which level?","options": [{"key": "A","text": "T6"},{"key": "B","text": "S2"},{"key": "C","text": "C1 exclusively, never below"},{"key": "D","text": "L1"}],"correct": "A","explanation": "Autonomic dysreflexia typically occurs in injuries at or above T6, due to unopposed sympathetic outflow below the injury level in response to noxious stimuli."},{"id": 5908,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Autonomic dysreflexia is characterized by which combination of signs/symptoms?","options": [{"key": "A","text": "Only localized limb symptoms without any systemic signs"},{"key": "B","text": "Sudden severe hypertension, bradycardia, pounding headache, and sweating/flushing above the injury level"},{"key": "C","text": "Hypotension and tachycardia only"},{"key": "D","text": "No changes in blood pressure or heart rate"}],"correct": "B","explanation": "AD classically presents with severe hypertension, reflex bradycardia, severe headache, and sweating/flushing above the lesion level, triggered by noxious stimuli below the injury (e.g., bladder distension)."},{"id": 5909,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The most common triggering cause of autonomic dysreflexia is:","options": [{"key": "A","text": "Emotional stress alone"},{"key": "B","text": "Room temperature changes"},{"key": "C","text": "Mild skin pressure"},{"key": "D","text": "Bladder distension (e.g., blocked catheter, overfull bladder)"}],"correct": "D","explanation": "Bladder distension is the most frequent trigger for autonomic dysreflexia, making prompt catheter/bladder assessment a priority in acute AD management."},{"id": 5910,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Immediate management of an autonomic dysreflexia episode includes:","options": [{"key": "A","text": "Sitting the patient upright, loosening restrictive clothing, and identifying/removing the noxious stimulus"},{"key": "B","text": "Ignoring the episode as it will resolve spontaneously"},{"key": "C","text": "Administering only pain medication without addressing the trigger"},{"key": "D","text": "Laying the patient flat immediately"}],"correct": "A","explanation": "Sitting the patient upright (to reduce BP via orthostatic effect) while identifying and removing the triggering noxious stimulus is essential immediate management."},{"id": 5911,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Neurogenic bladder in SCI above the sacral micturition center typically results in which pattern?","options": [{"key": "A","text": "No effect on bladder function regardless of level"},{"key": "B","text": "Reflexive (spastic/UMN) bladder with detrusor hyperreflexia"},{"key": "C","text": "Normal bladder function preserved"},{"key": "D","text": "Flaccid (LMN) areflexic bladder always"}],"correct": "B","explanation": "Injuries above the sacral cord (S2-S4) typically produce a reflexive/spastic bladder pattern with detrusor hyperreflexia due to loss of higher inhibitory control."},{"id": 5912,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Neurogenic bladder resulting from injury directly affecting the sacral micturition center (conus/cauda equina) typically produces:","options": [{"key": "A","text": "Reflexive (spastic) bladder pattern"},{"key": "B","text": "No bladder dysfunction"},{"key": "C","text": "Complete normal voiding function"},{"key": "D","text": "Flaccid (areflexic/LMN) bladder pattern"}],"correct": "D","explanation": "Injury directly at the sacral segments (conus medullaris) or cauda equina produces a flaccid, areflexic bladder pattern due to LMN damage."},{"id": 5913,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Intermittent catheterization is commonly used in SCI bladder management primarily to:","options": [{"key": "A","text": "Only used for bowel management, not bladder"},{"key": "B","text": "Regularly empty the bladder, reducing risk of overdistension and urinary tract infection"},{"key": "C","text": "Replace the need for any bladder training"},{"key": "D","text": "Permanently prevent any bladder function recovery"}],"correct": "B","explanation": "Regular intermittent catheterization helps maintain safe bladder volumes, reducing UTI risk and supporting long-term renal/bladder health."},{"id": 5914,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "Pressure injury (pressure ulcer) prevention is a critical component of SCI management primarily due to:","options": [{"key": "A","text": "Only relevant for patients with normal sensation"},{"key": "B","text": "Loss of protective sensation and inability to independently reposition, increasing pressure injury risk"},{"key": "C","text": "Only relevant during the acute hospital phase, not long-term"},{"key": "D","text": "No increased risk compared to general population"}],"correct": "B","explanation": "Impaired sensation and mobility significantly elevate pressure injury risk in SCI, necessitating lifelong vigilant skin care and regular repositioning."},{"id": 5915,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Regular pressure relief (weight shifts) for wheelchair users with SCI is generally recommended at what approximate frequency?","options": [{"key": "A","text": "Only when discomfort is felt, which may not occur due to sensory loss"},{"key": "B","text": "Once daily"},{"key": "C","text": "Once every 4 hours"},{"key": "D","text": "Every 15-30 minutes"}],"correct": "D","explanation": "Regular pressure relief maneuvers approximately every 15-30 minutes are commonly recommended to prevent tissue ischemia and pressure injury development."},{"id": 5916,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Deep vein thrombosis prophylaxis is particularly important in acute SCI due to:","options": [{"key": "A","text": "Only relevant if the patient has additional lower limb fractures"},{"key": "B","text": "No increased risk compared to general population"},{"key": "C","text": "Only relevant for injuries below L2"},{"key": "D","text": "Immobility and altered venous return increasing DVT risk"}],"correct": "D","explanation": "SCI-related immobility and altered autonomic/venous function significantly increase DVT risk, particularly in the acute phase, warranting appropriate prophylaxis."},{"id": 5917,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Respiratory management is particularly critical in high cervical SCI (C1-C4) due to:","options": [{"key": "A","text": "No respiratory implications at this level"},{"key": "B","text": "Potential compromise of diaphragmatic function requiring ventilatory support"},{"key": "C","text": "Only relevant for injuries below T6"},{"key": "D","text": "Only affecting speech, not breathing"}],"correct": "B","explanation": "High cervical injuries (especially C1-C3) can completely abolish diaphragmatic function (phrenic nerve C3-C5), often necessitating permanent or long-term ventilatory support."},{"id": 5918,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Assisted coughing techniques are important in SCI rehabilitation, particularly for injuries affecting which muscle groups?","options": [{"key": "A","text": "Only relevant for lumbar level injuries"},{"key": "B","text": "Only affecting upper limb muscles"},{"key": "C","text": "Abdominal and intercostal muscles needed for effective forceful expiration"},{"key": "D","text": "Not relevant to any SCI level"}],"correct": "C","explanation": "Loss of abdominal/intercostal muscle function (common in tetraplegia and high paraplegia) impairs effective cough, necessitating assisted cough techniques to clear secretions."},{"id": 5919,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "Spasticity management in SCI may include which combination of approaches?","options": [{"key": "A","text": "Ignoring spasticity entirely regardless of functional impact"},{"key": "B","text": "Complete avoidance of any management since spasticity always provides benefit"},{"key": "C","text": "Only surgical intervention in all cases"},{"key": "D","text": "Stretching/positioning, physical modalities, oral medications, and in some cases botulinum toxin or intrathecal baclofen"}],"correct": "D","explanation": "Spasticity management is individualized and multimodal, balancing potential functional benefits of mild spasticity against problematic spasticity affecting function/care."},{"id": 5920,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Functional Electrical Stimulation (FES) cycling is used in SCI rehabilitation primarily to:","options": [{"key": "A","text": "Replace the need for any wheelchair mobility training"},{"key": "B","text": "Provide cardiovascular conditioning and maintain muscle mass/bone density in paralyzed lower limbs"},{"key": "C","text": "Only relevant for upper limb paralysis"},{"key": "D","text": "Cure the spinal cord injury completely"}],"correct": "B","explanation": "FES cycling activates paralyzed lower limb muscles via electrical stimulation, providing cardiovascular benefit and helping maintain muscle/bone health."},{"id": 5921,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which level of complete SCI would generally be expected to allow independent wheelchair propulsion on level surfaces, given adequate upper limb strength?","options": [{"key": "A","text": "No level of tetraplegia allows any wheelchair independence"},{"key": "B","text": "C7 or below (with C6 also often achieving functional independence with adaptations)"},{"key": "C","text": "Only C1-C3 level injuries"},{"key": "D","text": "Only T10 and below exclusively, never higher"}],"correct": "B","explanation": "C7 level (with functional triceps) typically allows good independent wheelchair propulsion capability, with C6 also often achieving reasonable function using tenodesis and adapted techniques."},{"id": 5922,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Standing frames or tilt tables are used in SCI rehabilitation primarily for benefits including:","options": [{"key": "A","text": "No proven benefit exists"},{"key": "B","text": "Bone loading, spasticity management, bowel/bladder function, and psychological benefit"},{"key": "C","text": "Only for cosmetic purposes"},{"key": "D","text": "Complete restoration of ambulation ability"}],"correct": "B","explanation": "Standing programs offer multiple physiological benefits (bone loading, spasticity reduction, improved GI/GU function) and psychological benefits, even without functional ambulation goals."},{"id": 5923,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following is an important consideration in prescribing a wheelchair for a person with SCI?","options": [{"key": "A","text": "Cosmetic appearance being the primary consideration"},{"key": "B","text": "Individual factors including injury level, body size, functional goals, and environment"},{"key": "C","text": "A single standard wheelchair model suitable for all SCI levels"},{"key": "D","text": "Cost being the only relevant factor regardless of function"}],"correct": "B","explanation": "Wheelchair prescription requires careful individualized assessment considering injury level/function, body dimensions, lifestyle goals, and environmental factors."},{"id": 5924,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes the ASIA sensory examination key sensory points assessment?","options": [{"key": "A","text": "Only testing motor function, no sensory component"},{"key": "B","text": "Testing only vibration sense"},{"key": "C","text": "Testing light touch and pinprick sensation at specific dermatomal key points from C2 to S4-S5"},{"key": "D","text": "Testing only proprioception at random points"}],"correct": "C","explanation": "ASIA sensory exam uses standardized key sensory points across dermatomes (C2-S4/5), testing both light touch and pinprick, each graded 0-2."},{"id": 5925,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "The zone of partial preservation (ZPP) in SCI classification refers to:","options": [{"key": "A","text": "A term used only for cervical injuries"},{"key": "B","text": "The entire area of preserved function in an incomplete injury"},{"key": "C","text": "Dermatomes/myotomes caudal to the neurological level that remain partially innervated in a complete injury"},{"key": "D","text": "An area with completely normal function"}],"correct": "C","explanation": "ZPP describes the extent of partially preserved sensory/motor segments caudal to the neurological level in complete (ASIA A) injuries."},{"id": 5926,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Bowel management programs in SCI rehabilitation typically aim to establish:","options": [{"key": "A","text": "Reliance solely on medication without any behavioral/mechanical strategies"},{"key": "B","text": "Immediate surgical colostomy for all patients"},{"key": "C","text": "Complete avoidance of any bowel management program"},{"key": "D","text": "A regular, predictable, and efficient bowel routine to prevent complications like impaction and incontinence"}],"correct": "D","explanation": "Structured bowel programs (timing, diet, mechanical/pharmacological strategies) aim to establish predictable, effective evacuation, preventing complications and supporting community participation."},{"id": 5927,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following best describes appropriate transfer training progression for a person with new SCI?","options": [{"key": "A","text": "Progressing from assisted/supported transfers toward independent transfers as strength and skill develop, appropriate to injury level"},{"key": "B","text": "Using only mechanical lifts regardless of the patient's potential for independence"},{"key": "C","text": "Immediate independent transfer training regardless of strength/stability"},{"key": "D","text": "Complete avoidance of transfer training until full strength returns"}],"correct": "A","explanation": "Transfer training is progressively graded based on the patient's developing strength, trunk control, and skill, tailored to their specific injury level and potential."},{"id": 5928,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following statements about incomplete SCI recovery potential is most accurate?","options": [{"key": "A","text": "Complete and incomplete injuries have identical recovery potential"},{"key": "B","text": "Incomplete injuries never show any further recovery after initial presentation"},{"key": "C","text": "Incomplete injuries generally have better recovery potential than complete injuries, though individual outcomes vary considerably"},{"key": "D","text": "Recovery potential is unrelated to injury completeness"}],"correct": "C","explanation": "Incomplete SCI (ASIA B-D) generally carries better prognosis for further neurological/functional recovery compared to complete (ASIA A) injury, though individual variability remains significant."},{"id": 5929,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "Which of the following describes an important skin care education point for SCI patients regarding sensory loss?","options": [{"key": "A","text": "Relying on the patient to feel pain if a pressure injury develops"},{"key": "B","text": "Skin inspection is unnecessary if the patient reports feeling comfortable"},{"key": "C","text": "Regular skin inspection (including using a mirror for areas that cannot be directly seen) since pain/pressure sensation may be absent"},{"key": "D","text": "Only inspecting skin once a week is sufficient"}],"correct": "C","explanation": "Given loss of protective sensation, regular thorough skin inspection (including using mirrors for hard-to-see areas) is essential since patients cannot rely on pain sensation to detect developing pressure injuries."},{"id": 5930,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Which of the following best describes an appropriate goal for respiratory physiotherapy in a patient with high paraplegia/tetraplegia affecting expiratory muscle function?","options": [{"key": "A","text": "Complete avoidance of any respiratory intervention since it is not relevant to SCI"},{"key": "B","text": "Only relevant in the acute phase, with no ongoing need thereafter"},{"key": "C","text": "Optimizing secretion clearance and respiratory function through techniques like assisted coughing and breathing exercises"},{"key": "D","text": "Relying solely on medication without any physical intervention"}],"correct": "C","explanation": "Ongoing respiratory physiotherapy (secretion clearance techniques, breathing exercises) remains important throughout SCI rehabilitation given persistent respiratory muscle impairment risk, particularly with higher-level injuries."},{"id": 5931,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following best describes psychological adjustment considerations following SCI?","options": [{"key": "A","text": "Adjustment is a significant, ongoing process that benefits from psychological support integrated within comprehensive rehabilitation"},{"key": "B","text": "All patients adjust identically without any need for individualized support"},{"key": "C","text": "Psychological factors are irrelevant to physical rehabilitation outcomes"},{"key": "D","text": "Psychological adjustment is complete immediately after the acute injury phase"}],"correct": "A","explanation": "Psychological adjustment to SCI is a significant, individualized, ongoing process, and comprehensive rehabilitation benefits from integrated psychological support alongside physical rehabilitation."},{"id": 5932,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "The most common cause of traumatic spinal cord injury worldwide is:","options": [{"key": "A","text": "Falls exclusively"},{"key": "B","text": "Sports injuries exclusively"},{"key": "C","text": "Violence exclusively"},{"key": "D","text": "Road traffic accidents"}],"correct": "D","explanation": "Road traffic accidents remain the leading cause of traumatic SCI globally, though falls are increasingly significant particularly in elderly populations."},{"id": 5933,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Falls are an increasingly significant cause of SCI particularly in which population?","options": [{"key": "A","text": "Young athletes exclusively"},{"key": "B","text": "Infants exclusively"},{"key": "C","text": "Elderly individuals"},{"key": "D","text": "Middle-aged manual laborers exclusively"}],"correct": "C","explanation": "Fall-related SCI incidence has been rising, particularly affecting the elderly population, often resulting in incomplete injury patterns like central cord syndrome."},{"id": 5934,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "The most common level of traumatic cervical spinal cord injury is:","options": [{"key": "A","text": "C5"},{"key": "B","text": "T1"},{"key": "C","text": "C2"},{"key": "D","text": "C1"}],"correct": "A","explanation": "C5 level is among the most commonly injured cervical levels in traumatic SCI, related to biomechanical vulnerability of the lower cervical spine."},{"id": 5935,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following is a component of the ASIA motor examination, testing key muscles from C5 to S1?","options": [{"key": "A","text": "Testing specific key muscle groups bilaterally, graded 0-5 using MRC scale"},{"key": "B","text": "Only testing lower limb muscles"},{"key": "C","text": "Only testing grip strength"},{"key": "D","text": "Testing only reflexes, not voluntary strength"}],"correct": "A","explanation": "ASIA motor exam tests specific key muscles at each level (e.g., C5-elbow flexors, L3-knee extensors) bilaterally using the standard 0-5 MRC grading."},{"id": 5936,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which key muscle is tested for the C5 myotome in ASIA motor examination?","options": [{"key": "A","text": "Wrist extensors"},{"key": "B","text": "Finger flexors"},{"key": "C","text": "Elbow extensors"},{"key": "D","text": "Elbow flexors"}],"correct": "D","explanation": "C5 key muscle for ASIA testing is elbow flexors (biceps/brachialis)."},{"id": 5937,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which key muscle is tested for the C6 myotome in ASIA motor examination?","options": [{"key": "A","text": "Finger flexors"},{"key": "B","text": "Wrist extensors"},{"key": "C","text": "Elbow flexors"},{"key": "D","text": "Small finger abductors"}],"correct": "B","explanation": "C6 key muscle for ASIA testing is wrist extensors."},{"id": 5938,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which key muscle is tested for the L3 myotome in ASIA motor examination?","options": [{"key": "A","text": "Great toe extensors"},{"key": "B","text": "Knee extensors"},{"key": "C","text": "Ankle dorsiflexors"},{"key": "D","text": "Hip flexors"}],"correct": "B","explanation": "L3 key muscle for ASIA testing is knee extensors (quadriceps)."},{"id": 5939,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which key muscle is tested for the L4 myotome in ASIA motor examination?","options": [{"key": "A","text": "Ankle dorsiflexors"},{"key": "B","text": "Ankle plantarflexors"},{"key": "C","text": "Great toe extensors"},{"key": "D","text": "Knee extensors"}],"correct": "A","explanation": "L4 key muscle for ASIA testing is ankle dorsiflexors (tibialis anterior)."},{"id": 5940,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which key muscle is tested for the S1 myotome in ASIA motor examination?","options": [{"key": "A","text": "Ankle dorsiflexors"},{"key": "B","text": "Ankle plantarflexors"},{"key": "C","text": "Knee flexors"},{"key": "D","text": "Great toe extensors"}],"correct": "B","explanation": "S1 key muscle for ASIA testing is ankle plantarflexors (gastrocnemius/soleus)."},{"id": 5941,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Orthostatic hypotension is a common concern particularly in the acute/early rehabilitation phase for which SCI population?","options": [{"key": "A","text": "Higher level injuries (tetraplegia and high paraplegia) due to impaired sympathetic vasomotor control"},{"key": "B","text": "Not a concern in any SCI level"},{"key": "C","text": "Only affects lower lumbar level injuries"},{"key": "D","text": "Only relevant during the chronic phase, never acutely"}],"correct": "A","explanation": "Higher-level SCI significantly impairs sympathetic vasomotor control, predisposing to orthostatic hypotension particularly during early mobilization/upright positioning."},{"id": 5942,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Management strategies for orthostatic hypotension in SCI include:","options": [{"key": "A","text": "No management strategies exist"},{"key": "B","text": "Avoiding all upright positioning permanently"},{"key": "C","text": "Immediate rapid return to full upright position regardless of symptoms"},{"key": "D","text": "Gradual postural changes, compression garments/abdominal binders, and adequate hydration"}],"correct": "D","explanation": "Gradual position changes, external compression (garments, abdominal binder), and hydration help manage orthostatic hypotension during SCI rehabilitation."},{"id": 5943,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Thermoregulation impairment (poikilothermia) can occur in SCI, particularly with higher-level injuries, due to:","options": [{"key": "A","text": "Only affecting injuries below L3"},{"key": "B","text": "No relationship to injury level"},{"key": "C","text": "Disrupted autonomic control of vasomotor and sweating responses below the injury level"},{"key": "D","text": "Always resolving completely within 24 hours regardless of level"}],"correct": "C","explanation": "Higher-level SCI disrupts autonomic thermoregulatory control (vasomotor tone, sweating) below the lesion, impairing the body's ability to regulate temperature effectively."},{"id": 5944,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "Sexual dysfunction is a common concern following SCI; management/counseling should be:","options": [{"key": "A","text": "Avoided entirely as an inappropriate topic for rehabilitation discussion"},{"key": "B","text": "Only relevant for male patients, not female patients"},{"key": "C","text": "Addressed as an important component of comprehensive rehabilitation, considering individual injury level and goals"},{"key": "D","text": "Assumed to be irrelevant to quality of life"}],"correct": "C","explanation": "Sexual health is an important quality-of-life domain warranting appropriate, sensitive discussion and support as part of comprehensive SCI rehabilitation for all patients."},{"id": 5945,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following is an important consideration in wheelchair seating/positioning for pressure injury prevention?","options": [{"key": "A","text": "Using any available chair without specific consideration for pressure distribution"},{"key": "B","text": "Assuming all patients need identical seating solutions regardless of individual risk factors"},{"key": "C","text": "Ignoring seating considerations if the patient reports no discomfort"},{"key": "D","text": "Appropriate cushion selection and regular pressure mapping/assessment as needed"}],"correct": "D","explanation": "Individualized cushion selection and pressure assessment help optimize pressure distribution, a key pressure injury prevention strategy for wheelchair users with impaired sensation."},{"id": 5946,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following describes an important goal of upper limb rehabilitation in tetraplegia, given the significant functional impact of hand function?","options": [{"key": "A","text": "Maximizing available hand/arm function including tenodesis grasp training where applicable, to support independence in daily activities"},{"key": "B","text": "Assuming no functional improvement is possible in tetraplegia"},{"key": "C","text": "Ignoring upper limb rehabilitation since lower limb function is the only priority"},{"key": "D","text": "Focusing exclusively on passive range of motion without any functional training"}],"correct": "A","explanation": "Given the critical importance of hand function for independence, upper limb rehabilitation (including tenodesis training where relevant) is a major focus in tetraplegia rehabilitation."},{"id": 5947,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the role of splinting in tetraplegic hand management?","options": [{"key": "A","text": "Maintaining functional hand position (e.g., preserving tenodesis potential) and preventing contracture"},{"key": "B","text": "Only for cosmetic purposes"},{"key": "C","text": "Should never be used in SCI management"},{"key": "D","text": "Only relevant for paraplegic patients, not tetraplegic"}],"correct": "A","explanation": "Splinting helps maintain a functional hand position (preserving the natural finger flexion contracture useful for tenodesis grip) while preventing problematic contractures."},{"id": 5948,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following is an important physiotherapy consideration for range of motion maintenance in a person with complete SCI and paralyzed limbs?","options": [{"key": "A","text": "Regular passive range of motion exercises to prevent joint contracture given the lack of active movement"},{"key": "B","text": "Passive ROM is unnecessary since paralysis prevents any joint stiffness from developing"},{"key": "C","text": "Only active-assisted range of motion should ever be used"},{"key": "D","text": "Range of motion maintenance is only relevant for the upper limbs"}],"correct": "A","explanation": "Regular passive ROM exercises are essential to prevent joint contractures in paralyzed limbs lacking active movement, which would otherwise stiffen without intervention."},{"id": 5949,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "Which of the following describes the general goal of respiratory muscle training in tetraplegia?","options": [{"key": "A","text": "Respiratory training has no evidence base in SCI rehabilitation"},{"key": "B","text": "Should be avoided due to risk of fatigue"},{"key": "C","text": "Improving inspiratory/expiratory muscle strength and endurance to support respiratory function and secretion clearance"},{"key": "D","text": "Only relevant for ventilator-dependent patients"}],"correct": "C","explanation": "Respiratory muscle training aims to optimize available respiratory muscle function, supporting ventilation and effective secretion clearance in tetraplegic individuals."},{"id": 5950,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Which of the following best describes an appropriate approach to gait training in a person with incomplete SCI showing some voluntary lower limb movement?","options": [{"key": "A","text": "Assuming ambulation is never possible with any incomplete injury"},{"key": "B","text": "Complete avoidance of any gait training regardless of injury completeness"},{"key": "C","text": "Task-specific, progressive gait training potentially including body-weight-supported treadmill training or robotic-assisted devices, based on individual capacity"},{"key": "D","text": "Immediate unsupported independent walking without any progressive training"}],"correct": "C","explanation": "Incomplete SCI with residual motor function may benefit from progressive, task-specific gait training approaches (including technology-assisted options), individualized to the person's specific capacity and goals."},{"id": 5951,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following describes an important long-term health consideration for individuals living with chronic SCI?","options": [{"key": "A","text": "Complete return to pre-injury health risk profile once rehabilitation is completed"},{"key": "B","text": "No long-term health considerations beyond the initial injury and rehabilitation period"},{"key": "C","text": "Increased risk of secondary conditions including cardiovascular disease, metabolic syndrome, and pressure injuries requiring ongoing monitoring"},{"key": "D","text": "Only respiratory complications are relevant long-term, no other systems affected"}],"correct": "C","explanation": "Chronic SCI is associated with increased long-term risk of several secondary health conditions (cardiovascular, metabolic, skin, urinary), necessitating ongoing comprehensive health monitoring and management."},{"id": 5952,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following best describes the concept of 'discomplete' spinal cord injury increasingly recognized in research?","options": [{"key": "A","text": "A term with no clinical or research relevance"},{"key": "B","text": "Clinically classified as complete (ASIA A) but showing evidence of some retained neural connectivity on specialized testing"},{"key": "C","text": "Only relevant to cervical level injuries"},{"key": "D","text": "Synonymous with ASIA B classification"}],"correct": "B","explanation": "'Discomplete' injury describes cases clinically classified as complete but demonstrating some evidence of residual trans-lesional neural connectivity (e.g., on EMG or other specialized testing), an evolving area of SCI research with implications for future therapeutic approaches."},{"id": 5953,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following best describes an important consideration in caregiver training for families of individuals with significant SCI-related care needs?","options": [{"key": "A","text": "Comprehensive training covering transfers, skin care, bowel/bladder management, and recognizing complications like autonomic dysreflexia"},{"key": "B","text": "Caregiver training is unnecessary if professional care will always be available"},{"key": "C","text": "Only physical transfer training is relevant, other care aspects are not needed"},{"key": "D","text": "Caregivers should be excluded from all training to avoid overwhelming them"}],"correct": "A","explanation": "Comprehensive caregiver training across multiple domains (transfers, skin/bowel/bladder care, complication recognition) is important for supporting safe, effective long-term care."},{"id": 5954,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Hard","question": "Which of the following best describes an important psychosocial consideration during the acute SCI rehabilitation phase?","options": [{"key": "A","text": "Providing only physical rehabilitation without any attention to psychosocial factors"},{"key": "B","text": "Avoiding any discussion of prognosis or emotional concerns during the acute phase"},{"key": "C","text": "Assuming all patients will have identical emotional responses requiring the same standardized approach"},{"key": "D","text": "Addressing the significant emotional adjustment process while providing realistic, hope-focused information and support"}],"correct": "D","explanation": "Acute SCI rehabilitation should thoughtfully address the significant psychosocial adjustment process alongside physical rehabilitation, providing appropriately balanced, realistic support."},{"id": 5955,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Which of the following describes an important exercise prescription consideration for cardiovascular fitness training in individuals with SCI, particularly higher-level injuries?","options": [{"key": "A","text": "Considering altered autonomic cardiovascular responses and potentially reduced active muscle mass available for exercise, adapting prescription accordingly"},{"key": "B","text": "Assuming cardiovascular exercise is never appropriate or beneficial for individuals with SCI"},{"key": "C","text": "Only upper body exercise is ever relevant regardless of injury level"},{"key": "D","text": "Using identical exercise prescription approaches as for the general non-disabled population without any modification"}],"correct": "A","explanation": "SCI-specific factors (altered autonomic response, reduced active muscle mass, particularly with higher level injuries) require adapted exercise prescription approaches (e.g., arm ergometry, FES-assisted exercise) tailored to the individual's specific presentation."},{"id": 5956,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following best summarizes overall physiotherapy goals across the continuum of SCI rehabilitation, from acute to long-term community phases?","options": [{"key": "A","text": "Goals are irrelevant since SCI rehabilitation outcomes are predetermined by injury level alone"},{"key": "B","text": "A single fixed set of goals applied uniformly regardless of rehabilitation phase"},{"key": "C","text": "Progressing from acute complication prevention and impairment management toward maximizing functional independence, community participation, and long-term health/wellbeing"},{"key": "D","text": "Physiotherapy has no role beyond the acute hospital phase"}],"correct": "C","explanation": "SCI rehabilitation goals evolve across the continuum of care, from acute complication prevention through to maximizing long-term functional independence, community participation, and overall health/wellbeing."},{"id": 5957,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Medium","question": "Guillain-Barre Syndrome (GBS) is best characterized as:","options": [{"key": "A","text": "A demyelinating disease of the central nervous system only"},{"key": "B","text": "An acute autoimmune polyneuropathy causing progressive ascending weakness"},{"key": "C","text": "A chronic degenerative motor neuron disease"},{"key": "D","text": "A hereditary peripheral neuropathy"}],"correct": "B","explanation": "GBS is an acute, immune-mediated polyneuropathy, classically presenting with rapidly progressive ascending weakness."},{"id": 5958,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "GBS classically presents with weakness following which pattern?","options": [{"key": "A","text": "Asymmetric focal weakness in a single limb"},{"key": "B","text": "Only affecting the upper limbs"},{"key": "C","text": "Descending from face to legs"},{"key": "D","text": "Ascending, typically starting in the lower limbs and progressing upward"}],"correct": "D","explanation": "Classic GBS presents with symmetric ascending weakness, often beginning distally in the legs and progressing proximally/upward."},{"id": 5959,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "GBS often follows which type of preceding event?","options": [{"key": "A","text": "Malignancy diagnosis"},{"key": "B","text": "Head trauma"},{"key": "C","text": "Vascular event"},{"key": "D","text": "Infection (e.g., Campylobacter jejuni gastroenteritis, respiratory infection)"}],"correct": "D","explanation": "GBS frequently follows an antecedent infection (commonly Campylobacter jejuni, also respiratory viruses), triggering an autoimmune response affecting peripheral nerves."},{"id": 5960,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The most severe potential complication of GBS requiring close monitoring is:","options": [{"key": "A","text": "Cognitive impairment"},{"key": "B","text": "Isolated sensory loss without any motor involvement"},{"key": "C","text": "Skin breakdown as the primary concern"},{"key": "D","text": "Respiratory failure from respiratory muscle weakness"}],"correct": "D","explanation": "Progressive weakness in GBS can involve respiratory muscles, risking respiratory failure requiring close monitoring and potential ventilatory support."},{"id": 5961,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Autonomic dysfunction in GBS can present with:","options": [{"key": "A","text": "No autonomic involvement ever occurs in GBS"},{"key": "B","text": "Only sensory symptoms without any autonomic involvement"},{"key": "C","text": "Only affecting bowel/bladder function, no cardiovascular involvement"},{"key": "D","text": "Blood pressure lability, cardiac arrhythmias, and other autonomic instability"}],"correct": "D","explanation": "GBS can significantly affect autonomic function, causing blood pressure instability, arrhythmias, and other autonomic complications requiring careful monitoring."},{"id": 5962,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Miller Fisher variant of GBS classically presents with which triad?","options": [{"key": "A","text": "Isolated bulbar weakness only"},{"key": "B","text": "Ascending limb weakness with normal cranial nerve function"},{"key": "C","text": "Ophthalmoplegia, ataxia, and areflexia"},{"key": "D","text": "Isolated facial weakness only"}],"correct": "C","explanation": "Miller Fisher syndrome, a GBS variant, presents with the classic triad of ophthalmoplegia, ataxia, and areflexia, often with relatively preserved limb strength."},{"id": 5963,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "GBS diagnosis is typically supported by CSF analysis showing:","options": [{"key": "A","text": "Elevated red blood cell count"},{"key": "B","text": "Normal CSF findings always"},{"key": "C","text": "Albuminocytologic dissociation (elevated protein with normal cell count)"},{"key": "D","text": "Elevated white cell count with normal protein"}],"correct": "C","explanation": "Classic GBS CSF finding is albuminocytologic dissociation - elevated protein without a corresponding significant increase in cell count."},{"id": 5964,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "GBS treatment options include:","options": [{"key": "A","text": "Intravenous immunoglobulin (IVIg) or plasma exchange (plasmapheresis)"},{"key": "B","text": "No specific treatment is available or beneficial"},{"key": "C","text": "Antibiotics as the primary treatment for all cases"},{"key": "D","text": "Corticosteroids as the primary first-line and most effective treatment"}],"correct": "A","explanation": "IVIg and plasma exchange are the primary evidence-based treatments for GBS, with corticosteroids generally not showing benefit as monotherapy in typical GBS."},{"id": 5965,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Physiotherapy management during the acute progressive phase of GBS primarily focuses on:","options": [{"key": "A","text": "Full weight-bearing gait training immediately"},{"key": "B","text": "Aggressive strengthening exercises regardless of disease phase"},{"key": "C","text": "High-intensity resistance training from the outset"},{"key": "D","text": "Respiratory monitoring/support, positioning, gentle passive ROM, and preventing complications of immobility"}],"correct": "D","explanation": "Acute phase management prioritizes monitoring, positioning, gentle ROM, and complication prevention (contractures, pressure injury, DVT), with active strengthening introduced cautiously as recovery progresses."},{"id": 5966,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "A key principle in GBS rehabilitation regarding exercise intensity, particularly in earlier recovery stages, is to:","options": [{"key": "A","text": "Avoid overwork/fatigue which may be counterproductive to nerve recovery, progressing exercise gradually"},{"key": "B","text": "Exercise intensity has no relevance to GBS recovery"},{"key": "C","text": "Complete avoidance of all exercise throughout the entire recovery process"},{"key": "D","text": "Push maximal exercise intensity from the earliest recovery stage regardless of fatigue"}],"correct": "A","explanation": "Similar to some other neuromuscular conditions, avoiding overwork/excessive fatigue is considered important in GBS rehabilitation, with gradual progressive exercise introduction as recovery allows."},{"id": 5967,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Bell's palsy refers to:","options": [{"key": "A","text": "A peripheral nerve disorder affecting only the lower limb"},{"key": "B","text": "Idiopathic acute unilateral facial nerve (CN VII) palsy"},{"key": "C","text": "A central (upper motor neuron) facial weakness pattern"},{"key": "D","text": "Bilateral facial weakness always"}],"correct": "B","explanation": "Bell's palsy is an idiopathic, acute, typically unilateral lower motor neuron facial nerve palsy."},{"id": 5968,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Bell's palsy characteristically affects which part of the face, distinguishing it from central (UMN) facial palsy?","options": [{"key": "A","text": "Both upper and lower face on the affected side (forehead involvement present)"},{"key": "B","text": "Neither upper nor lower face is affected"},{"key": "C","text": "Only the lower face, sparing the forehead"},{"key": "D","text": "Only the upper face, sparing the mouth"}],"correct": "A","explanation": "Bell's palsy (LMN lesion) affects the entire ipsilateral face including the forehead, unlike central (UMN) facial palsy which typically spares forehead movement due to bilateral cortical innervation of the upper face."},{"id": 5969,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Central (UMN) facial palsy, in contrast to Bell's palsy, typically:","options": [{"key": "A","text": "Always presents bilaterally"},{"key": "B","text": "Spares the forehead/upper face due to bilateral cortical innervation of upper facial muscles"},{"key": "C","text": "Affects the forehead equally to the lower face"},{"key": "D","text": "Never occurs following stroke"}],"correct": "B","explanation": "Because the forehead/upper facial muscles receive bilateral cortical (UMN) innervation, a unilateral UMN lesion (e.g., stroke) typically spares forehead movement, unlike LMN facial palsy (Bell's palsy) which affects the entire face."},{"id": 5970,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Physiotherapy management for Bell's palsy commonly includes:","options": [{"key": "A","text": "Immobilization of the entire face in a splint"},{"key": "B","text": "Complete avoidance of any facial exercise"},{"key": "C","text": "Only surgical intervention as first-line management"},{"key": "D","text": "Facial muscle exercises, soft tissue techniques, and patient education on eye protection"}],"correct": "D","explanation": "Facial rehabilitation exercises, soft tissue mobilization, and eye protection education (given risk of corneal exposure from incomplete eye closure) are common physiotherapy components for Bell's palsy."},{"id": 5971,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Eye protection is an important consideration in Bell's palsy management primarily due to:","options": [{"key": "A","text": "No risk to the eye exists in Bell's palsy"},{"key": "B","text": "Only relevant in bilateral cases"},{"key": "C","text": "Incomplete eyelid closure risking corneal exposure/drying and injury"},{"key": "D","text": "Only relevant if the patient reports eye pain"}],"correct": "C","explanation": "Weakness of orbicularis oculi impairs complete eyelid closure, risking corneal drying/exposure keratopathy, making protective measures (lubricant drops, taping at night) important."},{"id": 5972,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Medium","question": "Peripheral neuropathy commonly associated with diabetes mellitus typically presents with which pattern?","options": [{"key": "A","text": "Only affecting cranial nerves"},{"key": "B","text": "Symmetric, distal, length-dependent sensory-predominant neuropathy (stocking-glove pattern)"},{"key": "C","text": "Asymmetric proximal weakness pattern exclusively"},{"key": "D","text": "Only affecting motor function, no sensory involvement"}],"correct": "B","explanation": "Diabetic peripheral neuropathy classically presents as a symmetric, distal, sensory-predominant polyneuropathy affecting the longest nerves first (stocking-glove pattern)."},{"id": 5973,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Charcot-Marie-Tooth disease is best classified as:","options": [{"key": "A","text": "An acquired autoimmune neuropathy"},{"key": "B","text": "A neuromuscular junction disorder"},{"key": "C","text": "A hereditary motor and sensory neuropathy"},{"key": "D","text": "A central nervous system demyelinating disease"}],"correct": "C","explanation": "CMT disease is the most common hereditary peripheral neuropathy, affecting both motor and sensory nerve function."},{"id": 5974,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Charcot-Marie-Tooth disease commonly presents with which foot deformity due to distal muscle weakness/imbalance?","options": [{"key": "A","text": "Hallux valgus exclusively"},{"key": "B","text": "No characteristic foot deformity"},{"key": "C","text": "Pes planus exclusively"},{"key": "D","text": "Pes cavus with hammer toes"}],"correct": "D","explanation": "CMT classically causes pes cavus (high arch) with hammer toe deformities due to distal muscle weakness and imbalance, particularly intrinsic foot muscle involvement."},{"id": 5975,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Common peroneal nerve injury/compression, often occurring at the fibular neck, classically presents with:","options": [{"key": "A","text": "Complete lower limb paralysis"},{"key": "B","text": "Foot drop with weakness of dorsiflexion and eversion"},{"key": "C","text": "Weakness of hip flexion"},{"key": "D","text": "Weakness of plantarflexion primarily"}],"correct": "B","explanation": "Common peroneal nerve palsy (vulnerable at the fibular neck from compression) classically causes foot drop due to loss of dorsiflexor/evertor function."},{"id": 5976,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Carpal tunnel syndrome results from compression of the median nerve, typically presenting with:","options": [{"key": "A","text": "Nocturnal hand paresthesia/pain in thumb, index, and middle finger distribution"},{"key": "B","text": "Bilateral lower limb weakness"},{"key": "C","text": "Weakness of wrist extension as the primary presenting symptom"},{"key": "D","text": "Pain localized only to the little finger"}],"correct": "A","explanation": "CTS classically presents with median nerve distribution paresthesia/pain (thumb, index, middle finger), often worse at night."},{"id": 5977,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Medium","question": "Ulnar neuropathy at the elbow (cubital tunnel syndrome) classically presents with sensory symptoms in which distribution?","options": [{"key": "A","text": "Thumb, index, and middle finger"},{"key": "B","text": "Entire hand equally"},{"key": "C","text": "Only the dorsum of the hand"},{"key": "D","text": "Ring and little finger"}],"correct": "D","explanation": "Ulnar nerve territory includes the ring and little finger; cubital tunnel syndrome causes symptoms in this distribution."},{"id": 5978,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Radial nerve palsy, classically from 'Saturday night palsy' (compression during sleep), presents with:","options": [{"key": "A","text": "Ape hand deformity"},{"key": "B","text": "Wrist drop and finger drop"},{"key": "C","text": "Foot drop"},{"key": "D","text": "Claw hand deformity"}],"correct": "B","explanation": "Radial nerve palsy causes characteristic wrist and finger drop from loss of extensor function."},{"id": 5979,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Meralgia paresthetica results from entrapment of which nerve?","options": [{"key": "A","text": "Lateral femoral cutaneous nerve"},{"key": "B","text": "Femoral nerve"},{"key": "C","text": "Sciatic nerve"},{"key": "D","text": "Obturator nerve"}],"correct": "A","explanation": "Entrapment of the lateral femoral cutaneous nerve (often near the inguinal ligament) causes anterolateral thigh burning/paresthesia."},{"id": 5980,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Brachial plexopathy can result from various causes including trauma, radiation, or compression; symptoms typically depend on:","options": [{"key": "A","text": "Which specific trunks/cords/branches of the plexus are affected"},{"key": "B","text": "Are always identical regardless of the specific lesion location"},{"key": "C","text": "Only occur in pediatric populations"},{"key": "D","text": "Only affect sensory function, never motor"}],"correct": "A","explanation": "Brachial plexus injury presentation varies significantly based on the specific level/branches involved (upper trunk, lower trunk, cords, etc.), producing distinct patterns like Erb's or Klumpke's palsy."},{"id": 5981,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Erb's palsy (upper brachial plexus injury, C5-C6) classically presents with which posture?","options": [{"key": "A","text": "Claw hand deformity"},{"key": "B","text": "'Waiter's tip' posture - arm adducted, internally rotated, elbow extended, forearm pronated"},{"key": "C","text": "Complete flaccid paralysis of the entire arm"},{"key": "D","text": "Isolated hand intrinsic muscle weakness"}],"correct": "B","explanation": "Erb's palsy causes loss of shoulder abduction/external rotation and elbow flexion, producing the classic waiter's tip posture."},{"id": 5982,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Klumpke's palsy (lower brachial plexus injury, C8-T1) classically presents with:","options": [{"key": "A","text": "Waiter's tip posture"},{"key": "B","text": "Claw hand deformity from intrinsic hand muscle weakness"},{"key": "C","text": "Isolated shoulder weakness only"},{"key": "D","text": "Complete absence of any hand function abnormality"}],"correct": "B","explanation": "Klumpke's palsy affects the intrinsic hand muscles (ulnar/median innervated), producing claw hand deformity."},{"id": 5983,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Nerve conduction studies in demyelinating neuropathies (like typical GBS) typically show:","options": [{"key": "A","text": "Reduced conduction velocity with relatively preserved amplitude"},{"key": "B","text": "No abnormality detected"},{"key": "C","text": "Normal conduction velocity with severely reduced amplitude"},{"key": "D","text": "Completely absent responses in all cases"}],"correct": "A","explanation": "Demyelinating neuropathies primarily slow conduction velocity (impaired myelin function), contrasting with axonal neuropathies which primarily reduce amplitude."},{"id": 5984,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Axonal neuropathies, in contrast to demyelinating neuropathies, typically show which pattern on nerve conduction studies?","options": [{"key": "A","text": "Reduced conduction velocity with preserved amplitude"},{"key": "B","text": "Reduced amplitude with relatively preserved conduction velocity"},{"key": "C","text": "No detectable change in any parameter"},{"key": "D","text": "Identical findings to demyelinating neuropathies"}],"correct": "B","explanation": "Axonal neuropathies primarily reduce the amplitude of the compound action potential (loss of functioning axons), with conduction velocity relatively preserved (in surviving axons)."},{"id": 5985,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following is a common cause of acquired peripheral polyneuropathy in addition to diabetes?","options": [{"key": "A","text": "Peripheral neuropathy has no acquired causes"},{"key": "B","text": "Chronic alcohol use, vitamin B12 deficiency, and certain chemotherapy agents"},{"key": "C","text": "Only genetic causes exist for peripheral neuropathy"},{"key": "D","text": "Only autoimmune causes are possible"}],"correct": "B","explanation": "Multiple acquired causes contribute to peripheral neuropathy including toxic (alcohol, chemotherapy), metabolic (diabetes), and nutritional (B12 deficiency) etiologies."},{"id": 5986,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Chronic Inflammatory Demyelinating Polyneuropathy (CIDP) differs from GBS primarily in that it:","options": [{"key": "A","text": "Follows a chronic, relapsing, or progressive course rather than the typically monophasic acute course of GBS"},{"key": "B","text": "Only affects sensory nerves, never motor"},{"key": "C","text": "Never responds to immunomodulatory treatment"},{"key": "D","text": "Is always acute and self-limiting like GBS"}],"correct": "A","explanation": "CIDP is essentially considered the chronic counterpart of GBS, with a protracted (>8 weeks), often relapsing or progressive course requiring longer-term management."},{"id": 5987,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Medium","question": "Sensory ataxia, resulting from peripheral neuropathy affecting proprioceptive fibers, is characterized by:","options": [{"key": "A","text": "Ataxia unaffected by visual input"},{"key": "B","text": "Complete absence of any gait abnormality"},{"key": "C","text": "Only affecting upper limb coordination"},{"key": "D","text": "Unsteady gait that worsens significantly with eyes closed or in the dark (positive Romberg's sign)"}],"correct": "D","explanation": "Sensory ataxia relies heavily on visual compensation for lost proprioceptive input, hence significant worsening with eyes closed (positive Romberg's) or in low-light conditions."},{"id": 5988,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Physiotherapy management for peripheral polyneuropathy commonly includes:","options": [{"key": "A","text": "Only pharmacological management, no role for physiotherapy"},{"key": "B","text": "Balance/proprioceptive training, appropriate strengthening, and gait aids/orthoses as needed"},{"key": "C","text": "Only passive modalities with no active exercise component"},{"key": "D","text": "Complete avoidance of any exercise due to nerve damage"}],"correct": "B","explanation": "Physiotherapy addresses functional deficits from peripheral neuropathy through balance training, appropriate strengthening, and compensatory strategies/devices as needed."},{"id": 5989,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Hard","question": "Footwear/foot care education is particularly important in diabetic peripheral neuropathy management primarily to:","options": [{"key": "A","text": "Improve cosmetic foot appearance only"},{"key": "B","text": "Address only pain symptoms, not injury prevention"},{"key": "C","text": "Prevent unnoticed injury/ulceration due to impaired protective sensation"},{"key": "D","text": "Cure the underlying neuropathy"}],"correct": "C","explanation": "Loss of protective sensation in diabetic neuropathy significantly increases risk of unnoticed injury/ulceration, making footwear/foot care education a critical preventive measure."},{"id": 5990,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Easy","question": "Which of the following describes an important safety consideration during gait training for a patient with significant peripheral sensory neuropathy affecting the feet?","options": [{"key": "A","text": "Only relevant for patients with additional motor weakness"},{"key": "B","text": "Increased fall risk due to impaired proprioceptive/sensory feedback, requiring appropriate balance training and environmental awareness"},{"key": "C","text": "No increased fall risk exists with peripheral sensory neuropathy"},{"key": "D","text": "Sensory neuropathy has no bearing on gait training considerations"}],"correct": "B","explanation": "Impaired sensory feedback from the feet significantly increases fall risk during gait, necessitating appropriate balance training, visual compensation strategies, and environmental safety awareness."},{"id": 5991,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Medium","question": "Which of the following statements about recovery potential in peripheral nerve injury/neuropathy is generally accurate?","options": [{"key": "A","text": "All peripheral neuropathies have identical, universally excellent recovery potential"},{"key": "B","text": "Recovery potential depends on the underlying cause, severity, and whether the pathology is primarily demyelinating (better prognosis) or axonal (potentially slower/more limited recovery)"},{"key": "C","text": "No peripheral neuropathy ever shows any recovery"},{"key": "D","text": "Recovery is entirely unrelated to the underlying pathological mechanism"}],"correct": "B","explanation": "Recovery potential varies considerably based on the underlying pathology, with primarily demyelinating processes (where the axon remains intact) generally having better/faster recovery potential than significant axonal loss, which requires slower nerve regeneration."},{"id": 5992,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Fatigue management is an important consideration in physiotherapy for patients recovering from GBS because:","options": [{"key": "A","text": "Fatigue never persists beyond the acute illness phase"},{"key": "B","text": "Persistent fatigue is a common residual symptom even after motor recovery, requiring appropriate pacing strategies"},{"key": "C","text": "Only relevant for patients who required mechanical ventilation"},{"key": "D","text": "Fatigue is irrelevant to functional rehabilitation planning"}],"correct": "B","explanation": "Persistent fatigue is a commonly reported long-term symptom following GBS, even after substantial motor recovery, warranting attention to appropriate activity pacing in rehabilitation planning."},{"id": 5993,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to strength training progression during GBS recovery, considering the risk of overwork weakness?","options": [{"key": "A","text": "Complete avoidance of any strengthening throughout the recovery process"},{"key": "B","text": "Using identical protocols regardless of the individual's recovery stage or response"},{"key": "C","text": "Gradual, monitored progression avoiding excessive fatigue, with close attention to the patient's response"},{"key": "D","text": "Immediate maximal resistance training regardless of fatigue signs"}],"correct": "C","explanation": "Given historical concern (extrapolated from other neuromuscular conditions) about overwork weakness, GBS strength training should progress gradually with careful monitoring of fatigue/response, avoiding excessive early loading."},{"id": 5994,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes a key consideration in patient/family education regarding the expected recovery trajectory of typical GBS?","options": [{"key": "A","text": "No recovery is expected in typical GBS, it is a permanently progressive condition"},{"key": "B","text": "Recovery always occurs within one week for all patients"},{"key": "C","text": "Recovery trajectory is completely unpredictable with no general pattern"},{"key": "D","text": "Recovery often occurs over months, with the majority showing significant improvement, though timeline and extent vary individually"}],"correct": "D","explanation": "While individual variation exists, typical GBS recovery generally follows a pattern of plateau followed by gradual improvement over weeks to months, important information for patient/family education and goal-setting."},{"id": 5995,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Tarsal tunnel syndrome results from compression of which nerve, causing plantar foot symptoms?","options": [{"key": "A","text": "Saphenous nerve"},{"key": "B","text": "Posterior tibial nerve"},{"key": "C","text": "Common peroneal nerve"},{"key": "D","text": "Sural nerve"}],"correct": "B","explanation": "Posterior tibial nerve compression within the tarsal tunnel (behind the medial malleolus) causes plantar foot pain/paresthesia."},{"id": 5996,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following is a recognized cause of mononeuritis multiplex (multiple individual peripheral nerves affected asymmetrically)?","options": [{"key": "A","text": "Vasculitis (e.g., polyarteritis nodosa)"},{"key": "B","text": "Charcot-Marie-Tooth disease"},{"key": "C","text": "GBS in its classic presentation"},{"key": "D","text": "Typical length-dependent diabetic polyneuropathy"}],"correct": "A","explanation": "Mononeuritis multiplex, with asymmetric involvement of multiple distinct individual nerves, is classically associated with vasculitic processes affecting the vasa nervorum."},{"id": 5997,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following nerve conduction study finding pattern is most consistent with typical (demyelinating) GBS (AIDP subtype)?","options": [{"key": "A","text": "Purely reduced amplitude with normal conduction velocity"},{"key": "B","text": "Conduction block and slowing, with relatively preserved amplitude initially"},{"key": "C","text": "Only sensory nerve abnormality with normal motor studies"},{"key": "D","text": "No abnormality on any nerve conduction parameter"}],"correct": "B","explanation": "AIDP (the classic demyelinating GBS subtype) shows conduction slowing/block on nerve conduction studies, reflecting the underlying demyelinating pathology."},{"id": 5998,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Medium","question": "Which of the following describes the Acute Motor Axonal Neuropathy (AMAN) variant of GBS?","options": [{"key": "A","text": "Only affects sensory function, never motor"},{"key": "B","text": "Identical pathophysiology to classic demyelinating GBS"},{"key": "C","text": "A primarily axonal (rather than demyelinating) variant, often associated with anti-ganglioside antibodies"},{"key": "D","text": "A variant that never causes any significant weakness"}],"correct": "C","explanation": "AMAN is an axonal GBS variant, often associated with preceding Campylobacter jejuni infection and anti-GM1 ganglioside antibodies, generally carrying a somewhat different recovery pattern than typical demyelinating AIDP."},{"id": 5999,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes appropriate splinting considerations for a patient with radial nerve palsy causing wrist drop?","options": [{"key": "A","text": "Splinting the wrist in full flexion"},{"key": "B","text": "A cock-up wrist splint to maintain functional wrist position and prevent overstretching of paralyzed extensors"},{"key": "C","text": "No splinting is ever indicated for radial nerve palsy"},{"key": "D","text": "Only splinting the fingers, never the wrist"}],"correct": "B","explanation": "A cock-up splint maintains functional wrist extension, preventing overstretch of paralyzed wrist extensors and supporting functional hand use during recovery."},{"id": 6000,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes appropriate positioning/splinting for common peroneal nerve palsy with foot drop, to prevent contracture?","options": [{"key": "A","text": "Positioning the ankle in maximal plantarflexion"},{"key": "B","text": "Only providing splinting during active physiotherapy sessions"},{"key": "C","text": "An ankle-foot orthosis or resting splint maintaining the ankle in neutral/dorsiflexed position"},{"key": "D","text": "No splinting is indicated regardless of the duration of palsy"}],"correct": "C","explanation": "Maintaining the ankle in a neutral position via splinting/AFO helps prevent Achilles tendon shortening/plantarflexion contracture during the recovery period from peroneal nerve palsy."},{"id": 6001,"subject": "Neurology","topic": "Peripheral Neuropathies","difficulty": "Medium","question": "Which of the following best describes nerve gliding/mobilization exercise rationale in peripheral nerve entrapment rehabilitation?","options": [{"key": "A","text": "Nerve gliding exercises have no theoretical or practical rationale"},{"key": "B","text": "Nerve gliding is only relevant for central nervous system conditions"},{"key": "C","text": "Promoting normal nerve excursion/mobility relative to surrounding tissue, potentially reducing adhesions and improving symptoms"},{"key": "D","text": "Nerve gliding exercises are contraindicated in all peripheral nerve conditions"}],"correct": "C","explanation": "Nerve gliding techniques aim to restore normal relative movement of the nerve within its surrounding tissue bed, potentially reducing adhesion-related symptoms in entrapment neuropathies."},{"id": 6002,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Parkinson's disease results from progressive degeneration of dopaminergic neurons primarily in which structure?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Thalamus"},{"key": "C","text": "Substantia nigra pars compacta"},{"key": "D","text": "Caudate nucleus"}],"correct": "C","explanation": "PD is characterized by progressive loss of dopaminergic neurons in the substantia nigra pars compacta, disrupting the nigrostriatal pathway."},{"id": 6003,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "The four cardinal motor features of Parkinson's disease are:","options": [{"key": "A","text": "Ataxia, dysmetria, tremor, and nystagmus"},{"key": "B","text": "Flaccidity, areflexia, fasciculations, and atrophy"},{"key": "C","text": "Resting tremor, rigidity, bradykinesia, and postural instability"},{"key": "D","text": "Spasticity, hyperreflexia, clonus, and Babinski sign"}],"correct": "C","explanation": "Classic PD cardinal features (TRAP mnemonic) include Tremor, Rigidity, Akinesia/bradykinesia, and Postural instability."},{"id": 6004,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Parkinsonian tremor classically occurs:","options": [{"key": "A","text": "Only during voluntary movement, never at rest"},{"key": "B","text": "Only when maintaining a sustained posture"},{"key": "C","text": "Only during sleep"},{"key": "D","text": "At rest, often described as 'pill-rolling'"}],"correct": "D","explanation": "Classic Parkinsonian tremor is a resting tremor, often with a characteristic 'pill-rolling' quality of the thumb and fingers."},{"id": 6005,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "Bradykinesia in Parkinson's disease refers to:","options": [{"key": "A","text": "Slowness in initiation and execution of voluntary movement"},{"key": "B","text": "Complete absence of any movement"},{"key": "C","text": "Only affecting speech, not limb movement"},{"key": "D","text": "Increased speed of movement"}],"correct": "A","explanation": "Bradykinesia describes generalized slowness in movement initiation/execution, a core diagnostic feature of PD."},{"id": 6006,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Postural instability in Parkinson's disease typically becomes clinically apparent in which disease stage?","options": [{"key": "A","text": "Not a recognized feature of PD"},{"key": "B","text": "Later stages of disease progression"},{"key": "C","text": "Only in atypical Parkinsonism, never idiopathic PD"},{"key": "D","text": "The very earliest presenting symptom in most patients"}],"correct": "B","explanation": "Postural instability typically emerges in later disease stages, and its early/prominent presence may suggest an atypical Parkinsonian syndrome rather than idiopathic PD."},{"id": 6007,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "The Hoehn and Yahr scale is used clinically to:","options": [{"key": "A","text": "Measure medication dosage requirements directly"},{"key": "B","text": "Stage the overall severity/progression of Parkinson's disease"},{"key": "C","text": "Assess sensory function"},{"key": "D","text": "Assess cognitive function specifically"}],"correct": "B","explanation": "Hoehn and Yahr scale (stages 1-5) is a widely used clinical staging system reflecting overall PD severity/progression, based on symptom distribution and postural stability."},{"id": 6008,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Hoehn and Yahr Stage 1 is characterized by:","options": [{"key": "A","text": "Wheelchair-bound or bedridden"},{"key": "B","text": "Unilateral symptoms only, minimal or no functional impairment"},{"key": "C","text": "Bilateral symptoms without postural instability"},{"key": "D","text": "Bilateral symptoms with postural instability"}],"correct": "B","explanation": "Stage 1 represents the earliest disease stage with unilateral involvement and minimal functional impact."},{"id": 6009,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Levodopa remains the most effective pharmacological treatment for Parkinson's disease motor symptoms by:","options": [{"key": "A","text": "Being converted to dopamine in the brain, replenishing the depleted neurotransmitter"},{"key": "B","text": "Having no effect on dopaminergic pathways"},{"key": "C","text": "Increasing acetylcholine levels"},{"key": "D","text": "Directly blocking dopamine receptors"}],"correct": "A","explanation": "Levodopa crosses the blood-brain barrier and is converted to dopamine, directly addressing the underlying dopamine deficiency in PD."},{"id": 6010,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "'Wearing-off' phenomenon in long-term levodopa therapy refers to:","options": [{"key": "A","text": "An immediate adverse reaction to the first dose"},{"key": "B","text": "Return of Parkinsonian symptoms before the next scheduled medication dose"},{"key": "C","text": "Complete resolution of all symptoms without further medication need"},{"key": "D","text": "Permanent loss of any medication benefit"}],"correct": "B","explanation": "Wearing-off describes the re-emergence of symptoms as medication effect diminishes before the next dose, common with long-term levodopa use."},{"id": 6011,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Levodopa-induced dyskinesias refer to:","options": [{"key": "A","text": "The primary symptoms of untreated Parkinson's disease"},{"key": "B","text": "Symptoms that only occur before any levodopa treatment is started"},{"key": "C","text": "Involuntary, often choreiform movements occurring as a complication of long-term levodopa therapy"},{"key": "D","text": "A separate unrelated movement disorder"}],"correct": "C","explanation": "Dyskinesias are involuntary movements that develop as a treatment complication with long-term levodopa use, often related to fluctuating dopamine levels."},{"id": 6012,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "'Freezing of gait' in Parkinson's disease refers to:","options": [{"key": "A","text": "Complete permanent inability to walk"},{"key": "B","text": "Slow but continuous walking without any interruption"},{"key": "C","text": "Only occurring during sleep"},{"key": "D","text": "Sudden, brief inability to initiate or continue walking, often triggered by turning, doorways, or dual-tasking"}],"correct": "D","explanation": "Freezing of gait describes episodic, brief motor blocks during walking, often triggered by specific situational factors like turning or narrow spaces."},{"id": 6013,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Cueing strategies (visual, auditory, or cognitive) are commonly used in Parkinson's disease physiotherapy to help address:","options": [{"key": "A","text": "Cognitive impairment exclusively"},{"key": "B","text": "Freezing of gait and bradykinesia by providing external triggers for movement initiation"},{"key": "C","text": "Tremor exclusively"},{"key": "D","text": "Autonomic dysfunction exclusively"}],"correct": "B","explanation": "External cues (e.g., visual lines on floor, rhythmic auditory cues) can help bypass impaired internal movement generation, improving gait initiation and reducing freezing episodes."},{"id": 6014,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Which of the following exercise approaches has strong evidence support for improving mobility/balance in Parkinson's disease?","options": [{"key": "A","text": "Isolated single-joint exercises only"},{"key": "B","text": "Only passive range of motion without active participation"},{"key": "C","text": "Complete rest and avoidance of exercise"},{"key": "D","text": "Big movement/amplitude-based training (e.g., LSVT BIG) and multimodal exercise programs"}],"correct": "D","explanation": "Amplitude-focused training approaches (like LSVT BIG) along with comprehensive exercise programs addressing strength, balance, and gait have good evidence support in PD management."},{"id": 6015,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "LSVT BIG therapy for Parkinson's disease specifically emphasizes:","options": [{"key": "A","text": "Passive stretching exclusively"},{"key": "B","text": "High-amplitude movement training to counteract bradykinesia/hypokinesia"},{"key": "C","text": "Small, precise fine motor movements only"},{"key": "D","text": "Cognitive training exclusively"}],"correct": "B","explanation": "LSVT BIG uses high-amplitude, high-effort movement training to address the characteristic movement amplitude reduction (hypokinesia) in PD."},{"id": 6016,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Postural changes commonly seen in Parkinson's disease include:","options": [{"key": "A","text": "Scoliotic posture as the primary characteristic finding"},{"key": "B","text": "Excessive lordotic posture with hyperextended joints"},{"key": "C","text": "Normal upright posture maintained throughout disease course"},{"key": "D","text": "Stooped/flexed posture with forward head, kyphosis, and flexed hips/knees"}],"correct": "D","explanation": "Classic Parkinsonian posture shows flexed, stooped alignment (forward head, kyphosis, flexed hips/knees), related to rigidity and postural control impairment."},{"id": 6017,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following best describes appropriate balance training considerations for individuals with Parkinson's disease?","options": [{"key": "A","text": "Balance training should be avoided due to fall risk"},{"key": "B","text": "Balance is not typically affected in Parkinson's disease"},{"key": "C","text": "Addressing reactive and anticipatory postural control, considering the increased fall risk associated with the condition"},{"key": "D","text": "Balance training has no evidence base in PD management"}],"correct": "C","explanation": "Balance training addressing both reactive and anticipatory postural control components is an important, evidence-supported component of PD rehabilitation given significantly increased fall risk."},{"id": 6018,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Deep Brain Stimulation (DBS) for Parkinson's disease commonly targets which structure?","options": [{"key": "A","text": "Hippocampus"},{"key": "B","text": "Primary motor cortex"},{"key": "C","text": "Subthalamic nucleus (or globus pallidus internus)"},{"key": "D","text": "Cerebellum"}],"correct": "C","explanation": "DBS for PD commonly targets the subthalamic nucleus or globus pallidus internus, modulating basal ganglia circuit activity to improve motor symptoms."},{"id": 6019,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Non-motor symptoms of Parkinson's disease include which of the following?","options": [{"key": "A","text": "Only affects vision, no other non-motor symptoms occur"},{"key": "B","text": "Depression, sleep disturbance, autonomic dysfunction, and cognitive changes"},{"key": "C","text": "Only motor symptoms occur in PD, no non-motor features exist"},{"key": "D","text": "Non-motor symptoms only occur in the terminal disease stage"}],"correct": "B","explanation": "PD is increasingly recognized as involving significant non-motor features (mood, sleep, autonomic, cognitive) alongside the classic motor symptoms, often significantly impacting quality of life."},{"id": 6020,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "Orthostatic hypotension, a recognized autonomic non-motor feature of Parkinson's disease, is important to consider because it can:","options": [{"key": "A","text": "Never occur in Parkinson's disease"},{"key": "B","text": "Only affect medication timing decisions, not physical safety"},{"key": "C","text": "Increase fall risk, particularly with position changes"},{"key": "D","text": "Have no relevance to functional mobility"}],"correct": "C","explanation": "Orthostatic hypotension (from autonomic dysfunction, sometimes exacerbated by medication) increases fall risk with position changes, an important safety consideration in PD rehabilitation."},{"id": 6021,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Hypomimia (reduced facial expression) in Parkinson's disease results from:","options": [{"key": "A","text": "Facial nerve palsy"},{"key": "B","text": "Complete facial muscle paralysis"},{"key": "C","text": "Bradykinesia affecting facial musculature"},{"key": "D","text": "Cognitive impairment exclusively, unrelated to motor function"}],"correct": "C","explanation": "Hypomimia reflects generalized bradykinesia affecting facial muscles, producing the characteristic reduced, mask-like facial expression in PD, distinct from facial nerve palsy."},{"id": 6022,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Micrographia (progressively smaller handwriting) in Parkinson's disease is attributed to:","options": [{"key": "A","text": "Bradykinesia affecting fine motor control"},{"key": "B","text": "Tremor exclusively"},{"key": "C","text": "Visual impairment"},{"key": "D","text": "Cognitive decline exclusively"}],"correct": "A","explanation": "Micrographia reflects the bradykinesia component of PD affecting fine motor control during sustained repetitive tasks like handwriting."},{"id": 6023,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Hypophonia (soft, quiet speech) in Parkinson's disease relates to:","options": [{"key": "A","text": "Only affecting comprehension, not speech production"},{"key": "B","text": "Bradykinesia/rigidity affecting respiratory and laryngeal musculature"},{"key": "C","text": "Hearing loss"},{"key": "D","text": "Complete loss of vocal cord function"}],"correct": "B","explanation": "Hypophonia results from reduced respiratory drive and laryngeal muscle bradykinesia/rigidity, a common speech feature in PD often addressed with speech therapy (e.g., LSVT LOUD)."},{"id": 6024,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "LSVT LOUD is a specific therapy approach for Parkinson's disease targeting:","options": [{"key": "A","text": "Cognitive function"},{"key": "B","text": "Gross motor movement amplitude"},{"key": "C","text": "Balance specifically"},{"key": "D","text": "Voice volume/intensity impairment (hypophonia)"}],"correct": "D","explanation": "LSVT LOUD is a speech therapy protocol specifically addressing PD-related hypophonia, training increased vocal loudness/intensity."},{"id": 6025,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "Assessing 'on-off' fluctuations in Parkinson's disease medication response is important for physiotherapy scheduling because:","options": [{"key": "A","text": "Treatment sessions may be more productive when timed during the 'on' (medication-effective) period"},{"key": "B","text": "On-off fluctuations only affect cognitive function, not motor performance"},{"key": "C","text": "Physiotherapy should only ever occur during 'off' periods"},{"key": "D","text": "Medication timing has no relevance to therapy scheduling"}],"correct": "A","explanation": "Understanding medication cycles helps optimize therapy session timing during the patient's 'on' period when motor function is typically best, maximizing treatment effectiveness."},{"id": 6026,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Dual-task training (combining motor and cognitive tasks) is relevant in Parkinson's disease rehabilitation because:","options": [{"key": "A","text": "PD patients often show particular difficulty with dual-tasking, which can worsen gait/balance and increase fall risk in daily life"},{"key": "B","text": "Dual-tasking is irrelevant to functional daily activities"},{"key": "C","text": "PD patients show no difference in dual-task performance compared to healthy individuals"},{"key": "D","text": "Dual-task training should always be avoided in PD rehabilitation"}],"correct": "A","explanation": "PD-related basal ganglia dysfunction particularly impairs automatic movement control, making dual-tasking (e.g., walking while talking) especially challenging and relevant to address given real-world fall risk implications."},{"id": 6027,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following best describes an appropriate exercise consideration regarding rigidity management in Parkinson's disease physiotherapy?","options": [{"key": "A","text": "Avoiding all stretching or flexibility exercises entirely"},{"key": "B","text": "Only pharmacological management is relevant for rigidity"},{"key": "C","text": "Rigidity cannot be addressed through any physiotherapy intervention"},{"key": "D","text": "Incorporating rotational/flexibility exercises and stretching to help manage rigidity's impact on movement and posture"}],"correct": "D","explanation": "Flexibility and rotational exercises are commonly incorporated into PD physiotherapy programs to help manage the functional impact of rigidity on movement and posture."},{"id": 6028,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following best describes the general disease course of idiopathic Parkinson's disease?","options": [{"key": "A","text": "Symptoms typically improve spontaneously over time without any treatment"},{"key": "B","text": "A static, non-progressive condition once diagnosed"},{"key": "C","text": "Complete resolution of symptoms is expected within months of diagnosis"},{"key": "D","text": "Progressive, though rate of progression varies considerably between individuals, with symptoms typically worsening over years"}],"correct": "D","explanation": "PD is a progressive neurodegenerative condition, though the rate and pattern of progression vary significantly between individuals."},{"id": 6029,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Which of the following describes atypical Parkinsonism/Parkinson-plus syndromes in relation to idiopathic Parkinson's disease?","options": [{"key": "A","text": "Conditions sharing some Parkinsonian features but with additional distinguishing signs and typically poorer response to levodopa/faster progression"},{"key": "B","text": "Conditions that always show better prognosis than idiopathic PD"},{"key": "C","text": "Conditions unrelated to any basal ganglia pathology"},{"key": "D","text": "Identical conditions to idiopathic Parkinson's disease requiring no distinction"}],"correct": "A","explanation": "Atypical Parkinsonism (e.g., Progressive Supranuclear Palsy, Multiple System Atrophy) shares some parkinsonian features but typically shows additional distinguishing signs, generally poorer levodopa response, and often faster progression than idiopathic PD."},{"id": 6030,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Progressive Supranuclear Palsy (PSP), an atypical Parkinsonism, classically presents with which distinguishing feature?","options": [{"key": "A","text": "Normal eye movements throughout the disease course"},{"key": "B","text": "Early prominent asymmetric resting tremor as the dominant feature"},{"key": "C","text": "Excellent, sustained response to levodopa"},{"key": "D","text": "Early, prominent postural instability with falls and vertical gaze palsy"}],"correct": "D","explanation": "PSP classically presents with early postural instability/falls and characteristic vertical (particularly downward) gaze palsy, distinguishing it from idiopathic PD."},{"id": 6031,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Multiple System Atrophy (MSA), another atypical Parkinsonism, is characterized by combination of Parkinsonian features with:","options": [{"key": "A","text": "No additional distinguishing clinical features"},{"key": "B","text": "Excellent sustained levodopa response similar to idiopathic PD"},{"key": "C","text": "Isolated tremor without any other additional features"},{"key": "D","text": "Prominent autonomic dysfunction and/or cerebellar signs"}],"correct": "D","explanation": "MSA combines Parkinsonian features with prominent autonomic dysfunction (MSA-A/Shy-Drager pattern) and/or cerebellar signs (MSA-C), distinguishing it from idiopathic PD."},{"id": 6032,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following best describes an appropriate long-term physiotherapy management approach across the progression of Parkinson's disease?","options": [{"key": "A","text": "Regular reassessment and progressive adaptation of the exercise/rehabilitation program as the disease and functional status evolve"},{"key": "B","text": "A single fixed exercise program applied unchanged throughout the entire disease course"},{"key": "C","text": "Complete discontinuation of physiotherapy once medication is optimized"},{"key": "D","text": "Physiotherapy is only relevant in the earliest disease stage, not later stages"}],"correct": "A","explanation": "Given the progressive nature of PD, ongoing physiotherapy involvement with regular reassessment and program adaptation is important throughout the disease course, addressing evolving needs."},{"id": 6033,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following best describes the rationale for group-based exercise classes (e.g., dance, tai chi, boxing programs) in Parkinson's disease management?","options": [{"key": "A","text": "Combining physical, cognitive, and social engagement benefits while addressing specific PD-related impairments"},{"key": "B","text": "Group exercise classes are only appropriate for early-stage disease"},{"key": "C","text": "Individual therapy is always superior with no role for group-based approaches"},{"key": "D","text": "Group exercise has no evidence base for PD and should be avoided"}],"correct": "A","explanation": "Various group-based exercise modalities (dance, tai chi, boxing-inspired programs) have shown benefit in PD management, combining physical training with cognitive engagement and valuable social support."},{"id": 6034,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Hard","question": "Which of the following describes an important safety consideration when prescribing home exercise programs for individuals with Parkinson's disease and significant balance impairment?","options": [{"key": "A","text": "Assuming all PD patients have identical fall risk regardless of individual assessment findings"},{"key": "B","text": "Home exercise programs are never appropriate for PD patients with any balance impairment"},{"key": "C","text": "Ensuring exercises are appropriately supervised/safe for the home environment, considering fall risk"},{"key": "D","text": "No safety considerations are needed regardless of balance status"}],"correct": "C","explanation": "Individualized assessment of fall risk and appropriate program design/safety considerations (e.g., appropriate supervision, environment) are important when prescribing home exercises for PD patients with balance impairment."},{"id": 6035,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Easy","question": "Which of the following best describes 'akathisia' as it may relate to Parkinson's disease medication management?","options": [{"key": "A","text": "A type of resting tremor"},{"key": "B","text": "A visual disturbance"},{"key": "C","text": "A subjective feeling of inner restlessness with an urge to move, sometimes associated with dopaminergic medication fluctuations"},{"key": "D","text": "A form of memory impairment"}],"correct": "C","explanation": "Akathisia describes an uncomfortable inner restlessness/urge to move, which can occur in the context of PD medication effects, distinct from other PD motor features."},{"id": 6036,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following best describes the general approach to fall prevention education in Parkinson's disease rehabilitation?","options": [{"key": "A","text": "Assuming falls are an unavoidable, unmodifiable consequence of disease progression"},{"key": "B","text": "Only relevant for patients who have already experienced multiple falls"},{"key": "C","text": "Addressing specific PD-related risk factors (freezing, postural instability, orthostatic hypotension) alongside general fall prevention strategies"},{"key": "D","text": "Fall prevention education is not relevant to PD management"}],"correct": "C","explanation": "Proactive fall prevention education addressing PD-specific risk factors (in addition to general strategies) is an important component of comprehensive rehabilitation, ideally implemented before significant fall history develops."},{"id": 6037,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following exercise modalities has evidence supporting benefit for both motor symptoms and potentially disease-modifying effects in Parkinson's disease, based on current research?","options": [{"key": "A","text": "Only passive modalities without any active movement component"},{"key": "B","text": "Complete rest and avoidance of physical exertion"},{"key": "C","text": "Exercise has no evidence-based role in Parkinson's disease management"},{"key": "D","text": "Aerobic exercise (e.g., forced/voluntary cycling) at appropriate intensity"}],"correct": "D","explanation": "Emerging research suggests aerobic exercise may have benefits extending beyond symptomatic management, with some evidence suggesting potential neuroprotective/disease-modifying effects, an active area of ongoing research."},{"id": 6038,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Which of the following best describes appropriate transfer training considerations for individuals with Parkinson's disease experiencing bradykinesia/rigidity affecting bed mobility?","options": [{"key": "A","text": "Complete reliance on caregiver assistance for all transfers regardless of the patient's potential for independence"},{"key": "B","text": "Avoiding any transfer training since bradykinesia cannot be addressed through rehabilitation"},{"key": "C","text": "Assuming no specific strategies are needed beyond general transfer training principles"},{"key": "D","text": "Teaching specific strategies (e.g., using momentum, breaking movement into components, verbal/visual cueing) to compensate for impaired automatic movement"}],"correct": "D","explanation": "PD-specific strategies (movement breakdown, cueing, utilizing momentum) can help compensate for impaired automatic movement control affecting bed mobility and transfers, supporting continued independence where possible."},{"id": 6039,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Multiple sclerosis is best characterized as:","options": [{"key": "A","text": "An autoimmune demyelinating disease of the central nervous system"},{"key": "B","text": "A basal ganglia degenerative disorder"},{"key": "C","text": "A muscular dystrophy variant"},{"key": "D","text": "A peripheral nerve degenerative disease"}],"correct": "A","explanation": "MS is an autoimmune-mediated demyelinating disease affecting the central nervous system (brain, spinal cord, optic nerves)."},{"id": 6040,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The most common clinical course of MS at initial diagnosis is:","options": [{"key": "A","text": "Progressive-relapsing MS exclusively"},{"key": "B","text": "Secondary progressive MS from onset"},{"key": "C","text": "Relapsing-remitting MS (RRMS)"},{"key": "D","text": "Primary progressive MS (PPMS)"}],"correct": "C","explanation": "RRMS, characterized by discrete relapses with periods of remission, is the most common initial disease course, affecting approximately 85% of patients at onset."},{"id": 6041,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Secondary progressive MS (SPMS) refers to:","options": [{"key": "A","text": "A phase of steadily worsening disability following an initial relapsing-remitting course"},{"key": "B","text": "A benign form of MS with no progression"},{"key": "C","text": "The most common initial presentation of MS"},{"key": "D","text": "A course with no relapses ever occurring"}],"correct": "A","explanation": "SPMS describes the transition many RRMS patients experience to a phase of gradual progressive worsening, with or without occasional relapses, typically after several years."},{"id": 6042,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Primary progressive MS (PPMS) is characterized by:","options": [{"key": "A","text": "Steady progression of disability from onset without distinct relapses"},{"key": "B","text": "Multiple discrete relapses with full recovery between episodes"},{"key": "C","text": "Always the mildest form of MS"},{"key": "D","text": "Onset exclusively in childhood"}],"correct": "A","explanation": "PPMS shows gradual, steady worsening from disease onset, without the relapsing-remitting pattern seen in RRMS."},{"id": 6043,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "MS diagnosis is supported by MRI findings showing:","options": [{"key": "A","text": "Multiple demyelinating plaques disseminated in time and space within the CNS"},{"key": "B","text": "A single isolated lesion only"},{"key": "C","text": "Peripheral nerve abnormalities exclusively"},{"key": "D","text": "Normal imaging findings in all confirmed cases"}],"correct": "A","explanation": "MS diagnosis (per McDonald criteria) relies on demonstrating dissemination in time and space of CNS demyelinating lesions on MRI, alongside clinical findings."},{"id": 6044,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Optic neuritis, a common early presenting feature of MS, typically presents with:","options": [{"key": "A","text": "Painful, often unilateral vision loss/blurring"},{"key": "B","text": "Isolated limb weakness without any visual symptoms"},{"key": "C","text": "Bilateral simultaneous hearing loss"},{"key": "D","text": "Isolated bowel/bladder dysfunction"}],"correct": "A","explanation": "Optic neuritis (inflammation of the optic nerve) commonly presents with painful unilateral vision impairment, often an early MS manifestation."},{"id": 6045,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "'Uhthoff's phenomenon' in MS refers to:","options": [{"key": "A","text": "Permanent worsening of symptoms unrelated to temperature"},{"key": "B","text": "A visual phenomenon unrelated to temperature"},{"key": "C","text": "Improvement of symptoms with heat exposure"},{"key": "D","text": "Temporary worsening of neurological symptoms with increased body temperature (e.g., heat, fever, exercise)"}],"correct": "D","explanation": "Uhthoff's phenomenon describes transient symptom worsening with elevated body temperature, related to impaired conduction in demyelinated axons at higher temperatures."},{"id": 6046,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Lhermitte's sign' in MS refers to:","options": [{"key": "A","text": "Pain relief with neck extension"},{"key": "B","text": "Visual disturbance with eye movement"},{"key": "C","text": "Electric shock-like sensation down the spine/limbs with neck flexion"},{"key": "D","text": "A sign exclusively related to peripheral nerve pathology"}],"correct": "C","explanation": "Lhermitte's sign describes an electric shock-like sensation radiating down the spine/limbs upon neck flexion, suggesting cervical cord demyelinating pathology."},{"id": 6047,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Fatigue in MS is best described as:","options": [{"key": "A","text": "A rare symptom with minimal functional impact"},{"key": "B","text": "A common, often debilitating symptom that may be disproportionate to physical activity level and distinct from simple tiredness"},{"key": "C","text": "Always directly correlated with visible physical disability level"},{"key": "D","text": "Only occurring in the most severe/advanced disease stages"}],"correct": "B","explanation": "MS-related fatigue is a common, often significantly disabling symptom that can occur even in patients with minimal visible physical impairment, requiring specific management strategies."},{"id": 6048,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Spasticity in MS commonly affects which limbs, often causing functional mobility challenges?","options": [{"key": "A","text": "Never affects mobility, only fine motor tasks"},{"key": "B","text": "Only affects the upper limbs, never the lower limbs"},{"key": "C","text": "Lower limbs, though upper limbs can also be affected"},{"key": "D","text": "Only occurs in the terminal disease stage"}],"correct": "C","explanation": "Spasticity commonly affects the lower limbs in MS, significantly impacting mobility and gait, though upper limb involvement can also occur."},{"id": 6049,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Cerebellar involvement in MS commonly presents with:","options": [{"key": "A","text": "Ataxia, intention tremor, and dysarthria"},{"key": "B","text": "Isolated cranial nerve palsy without cerebellar signs"},{"key": "C","text": "Only sensory symptoms without any coordination impairment"},{"key": "D","text": "Only affecting bladder function"}],"correct": "A","explanation": "Cerebellar plaques in MS commonly produce classic cerebellar signs including ataxia, intention tremor, and scanning dysarthria."},{"id": 6050,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Cognitive impairment in MS commonly affects which domains?","options": [{"key": "A","text": "Processing speed, memory, and executive function"},{"key": "B","text": "Cognitive function is never affected in MS"},{"key": "C","text": "Only affects patients in the terminal disease stage"},{"key": "D","text": "Only affects language production, never other cognitive domains"}],"correct": "A","explanation": "MS commonly affects information processing speed, memory, and executive function, sometimes occurring even relatively early in the disease course."},{"id": 6051,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Exercise therapy in MS management is generally supported by evidence to:","options": [{"key": "A","text": "Always worsen MS symptoms and should be avoided entirely"},{"key": "B","text": "Have no effect on any MS-related symptoms"},{"key": "C","text": "Improve fatigue, strength, mobility, and quality of life without worsening disease course"},{"key": "D","text": "Only be appropriate in the earliest disease stage"}],"correct": "C","explanation": "Contrary to historical concerns, current evidence supports exercise therapy as beneficial for various MS-related outcomes (fatigue, strength, mobility, quality of life) without evidence of disease worsening."},{"id": 6052,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Heat sensitivity considerations are important in MS exercise prescription because:","options": [{"key": "A","text": "Elevated body temperature can transiently worsen symptoms (Uhthoff's phenomenon), requiring appropriate environmental/cooling strategies"},{"key": "B","text": "Heat has no relevance to MS symptom management"},{"key": "C","text": "Heat sensitivity only affects a small minority of patients and can be universally ignored"},{"key": "D","text": "All MS patients should completely avoid any exercise due to heat sensitivity"}],"correct": "A","explanation": "Given Uhthoff's phenomenon, appropriate environmental temperature control and cooling strategies (e.g., pre-cooling, cooling garments) can help optimize exercise tolerance in heat-sensitive MS patients."},{"id": 6053,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Disease-modifying therapies (DMTs) in MS management aim to:","options": [{"key": "A","text": "Replace the need for any physiotherapy involvement"},{"key": "B","text": "Reduce relapse frequency and slow disease progression"},{"key": "C","text": "Only provide symptomatic relief without affecting underlying disease course"},{"key": "D","text": "Cure MS completely in all patients"}],"correct": "B","explanation": "DMTs target the underlying immune-mediated disease process, aiming to reduce relapse rate and slow progression, distinct from symptomatic management approaches."},{"id": 6054,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes an appropriate approach to fatigue management education in MS rehabilitation?","options": [{"key": "A","text": "Energy conservation strategies, activity pacing, and prioritization techniques"},{"key": "B","text": "Assuming fatigue cannot be addressed through any behavioral strategies"},{"key": "C","text": "Complete avoidance of all activity to prevent fatigue"},{"key": "D","text": "Encouraging maximal activity regardless of fatigue levels"}],"correct": "A","explanation": "Energy conservation, pacing, and activity prioritization strategies are important components of comprehensive fatigue management in MS rehabilitation."},{"id": 6055,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes the relapsing-remitting MS pattern in terms of relapse recovery?","options": [{"key": "A","text": "Relapses always result in complete permanent function loss with no recovery"},{"key": "B","text": "Relapses are typically followed by partial or complete recovery, though residual deficits may accumulate over time"},{"key": "C","text": "Relapses always fully resolve without any residual deficit ever"},{"key": "D","text": "No distinction exists between relapses and baseline function"}],"correct": "B","explanation": "RRMS relapses are typically followed by variable recovery (partial or complete), though incomplete recovery from successive relapses can lead to gradual accumulation of residual disability over time."},{"id": 6056,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an important physiotherapy consideration regarding MS symptom variability?","options": [{"key": "A","text": "MS symptoms remain completely constant and predictable at all times"},{"key": "B","text": "Symptoms can fluctuate significantly day-to-day and even within a day, requiring flexible, adaptive treatment planning"},{"key": "C","text": "Symptom variability has no relevance to treatment planning"},{"key": "D","text": "Only relevant for patients with progressive MS subtypes"}],"correct": "B","explanation": "MS symptoms often show considerable variability, requiring physiotherapists to adopt flexible, responsive treatment approaches accommodating day-to-day fluctuation."},{"id": 6057,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Bladder dysfunction is a common symptom in MS, often related to lesions affecting which pathway?","options": [{"key": "A","text": "Only peripheral nerve pathways, never central pathways"},{"key": "B","text": "Only occurs in the terminal disease stage"},{"key": "C","text": "Spinal cord pathways controlling bladder function"},{"key": "D","text": "Never related to MS pathology"}],"correct": "C","explanation": "MS commonly affects spinal cord pathways controlling bladder function, contributing to various patterns of neurogenic bladder dysfunction."},{"id": 6058,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an appropriate approach for balance training in MS patients with cerebellar-related ataxia?","options": [{"key": "A","text": "Progressive balance challenges incorporating multisensory training, appropriately graded to the individual's ability and safety"},{"key": "B","text": "Balance training has no role in cerebellar ataxia management"},{"key": "C","text": "Complete avoidance of any balance training due to cerebellar involvement"},{"key": "D","text": "Immediate maximal balance challenge regardless of baseline ability"}],"correct": "A","explanation": "Progressive, appropriately graded balance training (incorporating visual, vestibular, and proprioceptive elements) can help optimize function despite underlying cerebellar impairment."},{"id": 6059,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes appropriate gait aid/assistive device consideration in MS rehabilitation?","options": [{"key": "A","text": "Assistive devices should never be recommended in MS management"},{"key": "B","text": "Individualized prescription based on specific mobility impairments and fatigue considerations, potentially changing over the disease course"},{"key": "C","text": "Assuming all MS patients require identical mobility aids regardless of individual presentation"},{"key": "D","text": "A single fixed assistive device prescribed at diagnosis regardless of changing needs"}],"correct": "B","explanation": "Assistive device needs in MS often evolve with the disease course and symptom fluctuation, requiring individualized, periodically reassessed prescription approaches."},{"id": 6060,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes cooling strategies sometimes used to manage heat-related symptom exacerbation in MS?","options": [{"key": "A","text": "Only relevant for patients living in extremely hot climates"},{"key": "B","text": "Pre-cooling vests or environmental temperature control to help maintain exercise tolerance and reduce Uhthoff's phenomenon impact"},{"key": "C","text": "Cooling strategies replace the need for any other symptom management"},{"key": "D","text": "Cooling strategies have no evidence base and should never be used"}],"correct": "B","explanation": "Cooling strategies (garments, environmental control) can help some heat-sensitive MS patients better tolerate exercise/activity by mitigating Uhthoff's phenomenon-related symptom worsening."},{"id": 6061,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an important consideration in exercise prescription intensity for individuals with MS, given the risk of triggering fatigue or heat-related symptom worsening?","options": [{"key": "A","text": "Complete avoidance of any exercise intensity above minimal levels for all patients"},{"key": "B","text": "Individualized, appropriately monitored progression considering fatigue and thermoregulatory factors specific to the person"},{"key": "C","text": "Exercise intensity considerations are irrelevant in MS-specific programming"},{"key": "D","text": "A single standardized high-intensity protocol applied to all MS patients regardless of individual factors"}],"correct": "B","explanation": "MS exercise prescription should be individualized, considering the person's specific fatigue patterns, thermoregulatory sensitivity, and overall functional status to appropriately guide safe, effective progression."},{"id": 6062,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the general relationship between MS relapse and physiotherapy management during an acute relapse?","options": [{"key": "A","text": "Intensive strengthening should always be initiated immediately during an acute relapse regardless of symptom severity"},{"key": "B","text": "Physiotherapy has no role at any point during or after a relapse"},{"key": "C","text": "Complete bed rest for the entire relapse duration is always recommended regardless of severity"},{"key": "D","text": "Management typically focuses on symptom management and functional support during the acute relapse, with more intensive rehabilitation often emphasized during recovery"}],"correct": "D","explanation": "During an acute relapse, physiotherapy typically emphasizes appropriate symptom management and functional support, with more intensive rehabilitative approaches often emphasized as recovery progresses."},{"id": 6063,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the potential impact of MS-related cognitive impairment on physiotherapy treatment planning?","options": [{"key": "A","text": "Cognitive impairment has no relevance to physiotherapy treatment approach"},{"key": "B","text": "Only relevant for patients with the most severe cognitive impairment, mild impairment can be ignored"},{"key": "C","text": "May require treatment approach adaptation (e.g., simplified instructions, written reminders, consistent routine) to support learning and adherence"},{"key": "D","text": "Cognitive impairment always precludes any meaningful physiotherapy participation"}],"correct": "C","explanation": "Even relatively mild cognitive impairment can benefit from thoughtful treatment approach adaptations (simplified communication, consistent structure, written support) to optimize therapy engagement and home program adherence."},{"id": 6064,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important multidisciplinary team consideration in comprehensive MS management?","options": [{"key": "A","text": "Multidisciplinary care has no evidence benefit in MS"},{"key": "B","text": "Physiotherapy alone is sufficient to address all aspects of MS management"},{"key": "C","text": "Collaboration across neurology, physiotherapy, occupational therapy, and other specialists to address the diverse symptom profile"},{"key": "D","text": "Only relevant for patients with the most advanced/severe disease"}],"correct": "C","explanation": "Given the diverse and often multisystem symptom profile of MS, comprehensive multidisciplinary team involvement is important for optimal management across the disease course."},{"id": 6065,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes an appropriate approach when a patient reports increased weakness/symptoms specifically during warm weather or after a hot shower?","options": [{"key": "A","text": "Assuming this represents a true disease relapse requiring the same management as an acute exacerbation"},{"key": "B","text": "Recommending complete avoidance of any warm water exposure permanently"},{"key": "C","text": "Dismissing the symptom report as clinically irrelevant"},{"key": "D","text": "Recognizing this as potentially consistent with Uhthoff's phenomenon and discussing appropriate temperature management strategies"}],"correct": "D","explanation": "Temperature-related transient symptom fluctuation (Uhthoff's phenomenon) should be distinguished from true relapse, with appropriate patient education regarding temperature management strategies."},{"id": 6066,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the typical demographic profile most commonly affected by multiple sclerosis?","options": [{"key": "A","text": "Equal prevalence across all age groups and genders with no demographic pattern"},{"key": "B","text": "Predominantly elderly males over 70 years"},{"key": "C","text": "Young adults (typically 20-40 years), with higher prevalence in females"},{"key": "D","text": "Exclusively pediatric population under 10 years"}],"correct": "C","explanation": "MS typically presents in young adults (peak onset 20-40 years), with a notably higher prevalence in females compared to males."},{"id": 6067,"subject": "Neurology","topic": "Cerebral Palsy","difficulty": "Medium","question": "Cerebral palsy is best defined as:","options": [{"key": "A","text": "A group of permanent, non-progressive disorders of movement/posture development attributed to disturbances in the developing fetal/infant brain"},{"key": "B","text": "A purely genetic muscular disorder"},{"key": "C","text": "An acquired adult-onset condition exclusively"},{"key": "D","text": "A progressive degenerative motor neuron disease"}],"correct": "A","explanation": "CP describes a group of non-progressive motor disorders resulting from disturbances occurring in the developing brain, though secondary musculoskeletal changes can progress over time."},{"id": 6068,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Although the underlying brain lesion in CP is non-progressive, which aspect of the clinical presentation can change/progress over time?","options": [{"key": "A","text": "Musculoskeletal impairments (e.g., contractures, deformities) can progress with growth"},{"key": "B","text": "Nothing about the clinical presentation ever changes"},{"key": "C","text": "The brain lesion itself continues to progressively worsen"},{"key": "D","text": "Cognitive function always progressively deteriorates"}],"correct": "A","explanation": "While the brain lesion is static, secondary musculoskeletal complications (contractures, bony deformities) can develop/progress over time, particularly during growth, requiring ongoing management."},{"id": 6069,"subject": "Neurology","topic": "Cerebral Palsy","difficulty": "Hard","question": "Spastic cerebral palsy, the most common type, is characterized by:","options": [{"key": "A","text": "Reduced tone throughout without any hypertonia"},{"key": "B","text": "Fluctuating tone with involuntary movements"},{"key": "C","text": "Poor coordination and balance as the primary feature"},{"key": "D","text": "Increased muscle tone/hypertonia due to upper motor neuron damage"}],"correct": "D","explanation": "Spastic CP, the most common subtype, results from pyramidal tract damage, causing hypertonia/spasticity."},{"id": 6070,"subject": "Neurology","topic": "Cerebral Palsy","difficulty": "Easy","question": "Dyskinetic cerebral palsy is characterized by:","options": [{"key": "A","text": "Pure ataxia without any tone abnormality"},{"key": "B","text": "Complete absence of any movement"},{"key": "C","text": "Involuntary movements (athetosis, chorea, dystonia) with fluctuating muscle tone"},{"key": "D","text": "Pure hypertonia without any involuntary movement"}],"correct": "C","explanation": "Dyskinetic CP results from basal ganglia/extrapyramidal damage, producing involuntary movements and variable, fluctuating tone."},{"id": 6071,"subject": "Neurology","topic": "Cerebral Palsy","difficulty": "Medium","question": "Ataxic cerebral palsy is characterized by:","options": [{"key": "A","text": "Impaired coordination and balance due to cerebellar involvement"},{"key": "B","text": "Pure spasticity without any coordination deficit"},{"key": "C","text": "Purely involuntary movement without any balance impairment"},{"key": "D","text": "Complete absence of any motor function"}],"correct": "A","explanation": "Ataxic CP results from cerebellar damage, producing characteristic incoordination, poor balance, and often intention tremor."},{"id": 6072,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which topographical classification describes CP affecting all four limbs relatively equally, often with significant involvement?","options": [{"key": "A","text": "Diplegia"},{"key": "B","text": "Quadriplegia (tetraplegia)"},{"key": "C","text": "Hemiplegia"},{"key": "D","text": "Monoplegia"}],"correct": "B","explanation": "Quadriplegic (tetraplegic) CP involves all four limbs, often with significant trunk and bulbar involvement as well."},{"id": 6073,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which topographical classification describes CP predominantly affecting both lower limbs, with lesser upper limb involvement?","options": [{"key": "A","text": "Monoplegia"},{"key": "B","text": "Quadriplegia with equal involvement"},{"key": "C","text": "Hemiplegia"},{"key": "D","text": "Diplegia"}],"correct": "D","explanation": "Diplegic CP predominantly affects the lower limbs, often associated with periventricular leukomalacia in premature infants, with relatively lesser upper limb involvement."},{"id": 6074,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which topographical classification describes CP affecting one side of the body (arm and leg on the same side)?","options": [{"key": "A","text": "Paraplegia"},{"key": "B","text": "Hemiplegia"},{"key": "C","text": "Diplegia"},{"key": "D","text": "Quadriplegia"}],"correct": "B","explanation": "Hemiplegic CP involves unilateral arm and leg involvement on the same side of the body."},{"id": 6075,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The Gross Motor Function Classification System (GMFCS) classifies CP severity into how many levels?","options": [{"key": "A","text": "Five levels (I-V)"},{"key": "B","text": "Ten levels"},{"key": "C","text": "Three levels"},{"key": "D","text": "Two levels only"}],"correct": "A","explanation": "GMFCS classifies gross motor function into five levels (I being most independent, V being most dependent), widely used for CP severity classification and prognostication."},{"id": 6076,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "GMFCS Level I describes children who:","options": [{"key": "A","text": "Walk without limitations"},{"key": "B","text": "Have no functional mobility of any kind"},{"key": "C","text": "Walk only with hand-held mobility devices"},{"key": "D","text": "Require a wheelchair for all mobility"}],"correct": "A","explanation": "GMFCS Level I represents the highest functional level, with children walking without significant limitations, though may have difficulty with more advanced gross motor skills."},{"id": 6077,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "GMFCS Level V describes children who:","options": [{"key": "A","text": "Walk using hand-held mobility devices"},{"key": "B","text": "Have severely limited self-mobility even with assistive technology, requiring manual wheelchair transport"},{"key": "C","text": "Self-propel a manual wheelchair independently in most settings"},{"key": "D","text": "Walk independently without any limitation"}],"correct": "B","explanation": "GMFCS Level V represents the most severe functional limitation, with very limited self-mobility even with assistive technology."},{"id": 6078,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Periventricular leukomalacia, a common finding in preterm infants who develop CP, refers to:","options": [{"key": "A","text": "Damage exclusively to peripheral nerves"},{"key": "B","text": "A condition unrelated to CP development"},{"key": "C","text": "Damage/necrosis to white matter around the lateral ventricles"},{"key": "D","text": "Damage exclusively to the cerebellum"}],"correct": "C","explanation": "PVL involves white matter injury near the lateral ventricles, particularly common in premature infants, strongly associated with subsequent spastic diplegic CP."},{"id": 6079,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Hypoxic-ischemic encephalopathy (HIE) in term infants is a recognized cause of CP, resulting from:","options": [{"key": "A","text": "Perinatal oxygen deprivation/reduced blood flow to the brain"},{"key": "B","text": "Only postnatal infection, never perinatal hypoxia"},{"key": "C","text": "Only genetic factors, unrelated to any perinatal event"},{"key": "D","text": "A condition exclusively affecting premature infants"}],"correct": "A","explanation": "HIE results from perinatal asphyxia/reduced cerebral perfusion in term infants, a recognized significant cause of subsequent CP, often with more diffuse/severe presentation patterns."},{"id": 6080,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Contractures are a common secondary musculoskeletal complication in CP, particularly related to:","options": [{"key": "A","text": "A condition unrelated to underlying tone abnormality"},{"key": "B","text": "Persistent spasticity/muscle imbalance combined with growth, if not adequately managed"},{"key": "C","text": "Only occurring in ataxic CP, never spastic CP"},{"key": "D","text": "Complete absence of any muscle tone abnormality"}],"correct": "B","explanation": "Chronic spasticity and muscle imbalance, combined with skeletal growth, predispose to progressive contracture development if not proactively managed through stretching, positioning, and other interventions."},{"id": 6081,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Hip displacement/subluxation is a significant concern in CP, particularly in which GMFCS levels?","options": [{"key": "A","text": "Equally distributed across all GMFCS levels with no relationship to severity"},{"key": "B","text": "Only in GMFCS Level I"},{"key": "C","text": "Never a concern in cerebral palsy"},{"key": "D","text": "Higher GMFCS levels (more severe motor impairment, e.g., IV-V)"}],"correct": "D","explanation": "Hip displacement risk correlates strongly with GMFCS level, being significantly more common and severe in children with higher levels (more severe motor impairment), warranting regular hip surveillance."},{"id": 6082,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Regular hip surveillance (clinical and radiographic monitoring) is recommended in CP management primarily to:","options": [{"key": "A","text": "Screen for unrelated congenital conditions only"},{"key": "B","text": "Monitor cognitive development"},{"key": "C","text": "Detect early hip displacement, allowing timely intervention before dislocation occurs"},{"key": "D","text": "Assess cardiovascular fitness"}],"correct": "C","explanation": "Proactive hip surveillance protocols aim to identify progressive hip displacement early, enabling timely intervention (e.g., botulinum toxin, surgery) before complete dislocation develops."},{"id": 6083,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Botulinum toxin injections are commonly used in CP management to:","options": [{"key": "A","text": "Only used for cosmetic purposes"},{"key": "B","text": "Permanently cure the underlying spasticity"},{"key": "C","text": "Replace the need for any physiotherapy involvement"},{"key": "D","text": "Temporarily reduce focal spasticity, facilitating functional improvement or preventing contracture progression"}],"correct": "D","explanation": "Botulinum toxin provides temporary (typically 3-6 months) focal spasticity reduction, often used alongside physiotherapy/splinting to optimize functional outcomes or slow contracture progression."},{"id": 6084,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Selective Dorsal Rhizotomy (SDR) is a surgical intervention for CP that aims to:","options": [{"key": "A","text": "Cure the underlying brain lesion"},{"key": "B","text": "Permanently reduce spasticity by selectively cutting overactive sensory nerve rootlets"},{"key": "C","text": "Temporarily reduce spasticity similar to botulinum toxin"},{"key": "D","text": "Address only cognitive symptoms"}],"correct": "B","explanation": "SDR selectively divides hyperactive dorsal (sensory) nerve rootlets contributing to spasticity, providing permanent tone reduction, typically combined with intensive post-surgical rehabilitation."},{"id": 6085,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Intrathecal baclofen therapy for severe CP-related spasticity involves:","options": [{"key": "A","text": "Only used for upper limb spasticity, never lower limb"},{"key": "B","text": "Delivering baclofen directly into the CSF via an implanted pump for targeted spasticity management"},{"key": "C","text": "Oral medication administration only"},{"key": "D","text": "A one-time injection with permanent effect"}],"correct": "B","explanation": "Intrathecal baclofen pumps deliver medication directly to the CSF, providing more targeted, often more effective spasticity management for severe cases with fewer systemic side effects than oral dosing."},{"id": 6086,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Constraint-Induced Movement Therapy (CIMT) has been adapted for use in children with hemiplegic CP primarily to:","options": [{"key": "A","text": "Only address lower limb function"},{"key": "B","text": "Replace the need for any other therapy approach"},{"key": "C","text": "Restrain the more-affected limb to protect it"},{"key": "D","text": "Encourage increased use of the more-affected upper limb by restraining the less-affected limb"}],"correct": "D","explanation": "Pediatric CIMT applies similar principles to adult stroke rehabilitation, restraining the less-affected limb to promote intensive practice and use of the more-affected limb in hemiplegic CP."},{"id": 6087,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Hand-Arm Bimanual Intensive Therapy (HABIT) differs from CIMT in that it emphasizes:","options": [{"key": "A","text": "Only unilateral practice of the more-affected limb"},{"key": "B","text": "Complete restraint of both upper limbs simultaneously"},{"key": "C","text": "Passive range of motion exclusively"},{"key": "D","text": "Intensive bimanual (two-handed) task practice rather than restraint of the less-affected limb"}],"correct": "D","explanation": "HABIT focuses on intensive practice of bimanual coordinated tasks, addressing the functional need for two-handed activities, differing from CIMT's unilateral restraint approach."},{"id": 6088,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Serial casting in CP management is commonly used to address:","options": [{"key": "A","text": "Acute fractures exclusively"},{"key": "B","text": "Joint contractures, particularly ankle equinus, through gradual progressive stretching"},{"key": "C","text": "Cognitive impairment"},{"key": "D","text": "Speech difficulties"}],"correct": "B","explanation": "Serial casting applies progressive gentle stretch through successive cast changes, commonly used to address contractures like ankle equinus in CP."},{"id": 6089,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Ankle-foot orthoses (AFOs) are commonly prescribed in CP management to address:","options": [{"key": "A","text": "Only upper limb function"},{"key": "B","text": "Only speech difficulties"},{"key": "C","text": "Only cognitive impairment"},{"key": "D","text": "Ankle instability/equinus and improve gait mechanics"}],"correct": "D","explanation": "AFOs help manage common CP-related ankle issues (equinus, instability), supporting improved gait mechanics and stability."},{"id": 6090,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Gait analysis (including instrumented/3D gait analysis) is particularly useful in CP management to:","options": [{"key": "A","text": "Replace the need for any clinical examination"},{"key": "B","text": "Only relevant for research purposes with no clinical application"},{"key": "C","text": "Objectively characterize specific gait deviations, informing targeted treatment planning including surgical decision-making"},{"key": "D","text": "Assess only upper limb function"}],"correct": "C","explanation": "Detailed gait analysis provides objective data on specific movement deviations, informing individualized treatment planning, particularly valuable for complex surgical decision-making in CP."},{"id": 6091,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Crouch gait' pattern, commonly seen in spastic diplegic CP, is characterized by:","options": [{"key": "A","text": "Normal knee flexion-extension pattern"},{"key": "B","text": "Excessive knee extension/hyperextension throughout stance"},{"key": "C","text": "Isolated ankle abnormality without any proximal joint involvement"},{"key": "D","text": "Excessive hip and knee flexion throughout stance phase"}],"correct": "D","explanation": "Crouch gait shows excessive flexed posture at hip and knee throughout stance, a common and often problematic pattern in spastic diplegic CP, sometimes related to hamstring tightness/weakness."},{"id": 6092,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to strength training in children with CP, given historical concerns about exacerbating spasticity?","options": [{"key": "A","text": "Strength training should always be avoided in CP due to spasticity concerns"},{"key": "B","text": "Strength training should only ever be performed passively"},{"key": "C","text": "Current evidence supports appropriately dosed strength training as beneficial without worsening spasticity"},{"key": "D","text": "Strength training has no evidence base in CP management"}],"correct": "C","explanation": "Contrary to older concerns, current evidence supports strength training as a beneficial, safe component of CP management, not exacerbating spasticity as was once feared."},{"id": 6093,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an appropriate goal-setting approach in pediatric CP rehabilitation?","options": [{"key": "A","text": "Family-centered, functional goal setting involving the child/family in identifying meaningful priorities"},{"key": "B","text": "Goal setting is not relevant to pediatric rehabilitation planning"},{"key": "C","text": "Generic goals applied uniformly regardless of individual child/family priorities"},{"key": "D","text": "Goals determined exclusively by the therapist without family/child input"}],"correct": "A","explanation": "Family-centered practice, involving the child and family in meaningful, functional goal identification, is considered best practice in pediatric CP rehabilitation."},{"id": 6094,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding transition planning for adolescents/young adults with CP?","options": [{"key": "A","text": "Planning for transition to adult services, addressing evolving needs including musculoskeletal, functional, and psychosocial aspects"},{"key": "B","text": "No transition planning is needed since CP only affects children"},{"key": "C","text": "Transition planning is solely the responsibility of medical specialists, with no physiotherapy involvement"},{"key": "D","text": "Assuming all needs automatically resolve upon reaching adulthood"}],"correct": "A","explanation": "Thoughtful transition planning addressing evolving needs (including ongoing musculoskeletal management, changing functional goals, and psychosocial factors) is important as individuals with CP move into adulthood."},{"id": 6095,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes a common associated impairment that may accompany the motor disorder in CP, beyond the primary movement impairment?","options": [{"key": "A","text": "CP exclusively affects motor function with no other associated impairments ever occurring"},{"key": "B","text": "Cognitive, sensory, communication, and/or seizure disorders can commonly co-occur"},{"key": "C","text": "Only visual impairment can co-occur, no other associated conditions"},{"key": "D","text": "Associated impairments only occur in the mildest CP presentations"}],"correct": "B","explanation": "CP frequently co-occurs with a range of associated impairments (cognitive, sensory, communication, epilepsy) reflecting the often widespread nature of the underlying brain injury, requiring comprehensive multidisciplinary assessment."},{"id": 6096,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the general approach to physiotherapy across the developmental course of a child with CP?","options": [{"key": "A","text": "A single fixed intervention program unchanged from diagnosis through adulthood"},{"key": "B","text": "Intervention focus remaining identical regardless of the child's changing age and needs"},{"key": "C","text": "Physiotherapy involvement ending once the child reaches school age"},{"key": "D","text": "Regularly evolving intervention addressing changing developmental stages, functional goals, and secondary complications as the child grows"}],"correct": "D","explanation": "CP physiotherapy management evolves considerably across childhood/adolescence, addressing changing developmental priorities, functional goals, and emerging secondary musculoskeletal concerns as the child grows."},{"id": 6097,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding equipment/assistive technology provision for children with CP?","options": [{"key": "A","text": "Regular reassessment and appropriate adaptation as the child grows and functional needs change"},{"key": "B","text": "Equipment needs are identical for all children regardless of GMFCS level"},{"key": "C","text": "Equipment provided once at diagnosis should never require any modification or replacement"},{"key": "D","text": "Assistive technology has no role in CP management"}],"correct": "A","explanation": "Equipment/assistive technology needs evolve with growth and changing function, requiring regular reassessment and appropriate modification/replacement throughout childhood."},{"id": 6098,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the concept of 'selective motor control' impairment often seen in spastic CP, relevant to movement quality beyond simple weakness/spasticity?","options": [{"key": "A","text": "A term unrelated to CP motor impairment"},{"key": "B","text": "Reduced ability to isolate movement at a single joint without involuntary movement at other joints"},{"key": "C","text": "Complete absence of any voluntary movement capability"},{"key": "D","text": "Only relevant to upper limb function, never lower limb"}],"correct": "B","explanation": "Impaired selective motor control describes difficulty isolating movement at individual joints (e.g., difficulty flexing the knee without also flexing the hip), an important consideration beyond simple strength/tone assessment in CP."},{"id": 6099,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes the rationale for early intervention services in infants at risk for or diagnosed with CP?","options": [{"key": "A","text": "Capitalizing on early neuroplasticity and addressing developmental needs during critical early developmental windows"},{"key": "B","text": "Early intervention has no evidence base and provides no benefit"},{"key": "C","text": "Intervention should always be delayed until definitive CP diagnosis is confirmed with certainty"},{"key": "D","text": "Early intervention is only relevant for cognitive development, not motor development"}],"correct": "A","explanation": "Early intervention aims to leverage the young brain's heightened neuroplasticity and address developmental needs during critical early windows, though diagnostic certainty may evolve over time."},{"id": 6100,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration regarding orthopedic surgical intervention timing in CP management?","options": [{"key": "A","text": "Careful individualized timing considering growth, gait analysis findings, and functional goals, often coordinated within a multidisciplinary team"},{"key": "B","text": "Surgical intervention is never appropriate in CP management"},{"key": "C","text": "Surgery should always be performed as early as possible regardless of growth considerations"},{"key": "D","text": "Timing considerations are irrelevant since outcomes are identical regardless of surgical timing"}],"correct": "A","explanation": "Orthopedic surgical decision-making in CP requires careful consideration of growth stage, comprehensive gait analysis findings, and functional goals, typically within a coordinated multidisciplinary approach."},{"id": 6101,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the concept of single-event multilevel surgery (SEMLS) in CP orthopedic management?","options": [{"key": "A","text": "Requiring multiple separate surgical episodes for each individual deformity"},{"key": "B","text": "Addressing multiple musculoskeletal deformities in a single surgical episode/anesthetic, followed by coordinated rehabilitation"},{"key": "C","text": "Performing surgery on only one body segment regardless of multiple deformities present"},{"key": "D","text": "A term unrelated to CP surgical management"}],"correct": "B","explanation": "SEMLS addresses multiple concurrent musculoskeletal deformities within a single surgical event, aiming to reduce the cumulative burden of multiple separate procedures/recovery periods, followed by coordinated intensive rehabilitation."},{"id": 6102,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes appropriate consideration regarding communication/participation goals in comprehensive CP management, beyond purely physical/motor goals?","options": [{"key": "A","text": "Addressing communication, social participation, and overall quality of life as important, integrated components of holistic CP management"},{"key": "B","text": "Quality of life considerations are irrelevant to rehabilitation planning"},{"key": "C","text": "Only physical/motor goals are relevant to CP management"},{"key": "D","text": "Communication and participation goals are the sole responsibility of speech-language pathology with no relevance to physiotherapy"}],"correct": "A","explanation": "Holistic CP management recognizes the importance of communication, social participation, and overall quality of life as integrated goals alongside physical/motor rehabilitation, often requiring coordinated multidisciplinary team input."},{"id": 6103,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Athetoid movements, seen in dyskinetic CP, are best described as:","options": [{"key": "A","text": "Sustained fixed postures without any movement"},{"key": "B","text": "Rhythmic oscillating tremor at rest only"},{"key": "C","text": "Slow, writhing, continuous involuntary movements"},{"key": "D","text": "Sudden brief shock-like jerks"}],"correct": "C","explanation": "Athetosis describes slow, writhing, continuous involuntary movements, a characteristic feature of dyskinetic CP."},{"id": 6104,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding classroom/educational positioning equipment for a child with CP at school?","options": [{"key": "A","text": "Educational positioning needs are identical to home positioning needs with no distinction required"},{"key": "B","text": "School-based positioning has no relevance to physiotherapy involvement"},{"key": "C","text": "Positioning equipment is only relevant at home, never in educational settings"},{"key": "D","text": "Appropriate seating/positioning supports participation, posture, and function during educational activities"}],"correct": "D","explanation": "Appropriate classroom positioning/seating supports the child's postural needs and functional participation during school activities, often requiring physiotherapy input alongside educational staff collaboration."},{"id": 6105,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes a recognized benefit of hydrotherapy (aquatic therapy) in pediatric CP rehabilitation?","options": [{"key": "A","text": "Only appropriate for children with the mildest CP presentation"},{"key": "B","text": "Complete replacement of land-based therapy in all cases"},{"key": "C","text": "Hydrotherapy has no evidence-based benefit in CP management"},{"key": "D","text": "Buoyancy-assisted movement allowing exercise with reduced gravitational/joint loading demands, potentially facilitating movement not possible on land"}],"correct": "D","explanation": "Water's buoyancy properties can facilitate movement and exercise participation with reduced loading demands, offering a valuable complementary therapeutic modality in pediatric CP rehabilitation."},{"id": 6106,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Amyotrophic Lateral Sclerosis (ALS) is characterized by progressive degeneration of:","options": [{"key": "A","text": "Only sensory neurons"},{"key": "B","text": "Only autonomic neurons"},{"key": "C","text": "Both upper and lower motor neurons"},{"key": "D","text": "Only cerebellar neurons"}],"correct": "C","explanation": "ALS uniquely involves progressive degeneration of both upper motor neurons (corticospinal) and lower motor neurons (anterior horn cells/brainstem motor nuclei)."},{"id": 6107,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "ALS characteristically presents with a combination of which clinical signs?","options": [{"key": "A","text": "Mixed upper motor neuron (spasticity, hyperreflexia) and lower motor neuron (weakness, atrophy, fasciculations) signs"},{"key": "B","text": "Only lower motor neuron signs exclusively"},{"key": "C","text": "Only upper motor neuron signs exclusively"},{"key": "D","text": "Only sensory symptoms without any motor involvement"}],"correct": "A","explanation": "The combination of UMN and LMN signs is a defining diagnostic feature of ALS, distinguishing it from purely upper or lower motor neuron conditions."},{"id": 6108,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Sensory function in classic ALS is typically:","options": [{"key": "A","text": "Severely impaired from disease onset"},{"key": "B","text": "Completely absent throughout the body"},{"key": "C","text": "Relatively preserved, as ALS primarily affects motor neurons"},{"key": "D","text": "Affected before any motor symptoms develop"}],"correct": "C","explanation": "ALS is primarily a motor neuron disease; sensory pathways are classically relatively spared, distinguishing it from many other neurological conditions."},{"id": 6109,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Bulbar onset ALS presents initially with which symptoms?","options": [{"key": "A","text": "Dysarthria and dysphagia"},{"key": "B","text": "Isolated upper limb weakness only"},{"key": "C","text": "Isolated lower limb weakness"},{"key": "D","text": "Cognitive impairment as the sole initial feature"}],"correct": "A","explanation": "Bulbar onset ALS begins with speech (dysarthria) and swallowing (dysphagia) difficulties, reflecting brainstem motor neuron involvement, and generally carries a different progression pattern than limb-onset disease."},{"id": 6110,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Limb-onset ALS, the more common presentation, typically begins with:","options": [{"key": "A","text": "Bulbar symptoms exclusively"},{"key": "B","text": "Bilateral symmetric weakness from onset always"},{"key": "C","text": "Sensory symptoms preceding any motor involvement"},{"key": "D","text": "Asymmetric limb weakness, often distal"}],"correct": "D","explanation": "Limb-onset ALS (more common than bulbar onset) typically presents with asymmetric, often distal limb weakness that progressively spreads."},{"id": 6111,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Respiratory failure in ALS results from:","options": [{"key": "A","text": "Progressive weakness of respiratory muscles (diaphragm, intercostals)"},{"key": "B","text": "Direct lung parenchymal disease"},{"key": "C","text": "Upper airway obstruction from tumor"},{"key": "D","text": "Cardiac dysfunction exclusively"}],"correct": "A","explanation": "ALS-related respiratory muscle weakness (diaphragm, accessory muscles) is the primary cause of respiratory failure, ultimately the most common cause of death in ALS."},{"id": 6112,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Non-invasive ventilation (NIV) in ALS management is used to:","options": [{"key": "A","text": "Support respiratory function and improve quality of life/survival as respiratory muscles weaken"},{"key": "B","text": "Only used in the earliest disease stage before any symptoms develop"},{"key": "C","text": "Cure the underlying disease process"},{"key": "D","text": "Replace the need for any physiotherapy respiratory management"}],"correct": "A","explanation": "NIV provides ventilatory support as respiratory muscles weaken, shown to improve quality of life and potentially survival in appropriately selected ALS patients."},{"id": 6113,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Riluzole, a pharmacological treatment for ALS, works by:","options": [{"key": "A","text": "Reversing existing motor neuron damage"},{"key": "B","text": "Reducing glutamate excitotoxicity, modestly slowing disease progression"},{"key": "C","text": "Completely curing the underlying disease"},{"key": "D","text": "Only providing symptomatic pain relief"}],"correct": "B","explanation": "Riluzole is thought to reduce glutamate-mediated excitotoxicity, providing modest disease-modifying effect (slowing progression) rather than a cure."},{"id": 6114,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Physiotherapy management in ALS should generally emphasize which approach to exercise, given the progressive nature of the disease and risk of overwork weakness?","options": [{"key": "A","text": "Moderate, non-fatiguing exercise avoiding excessive intensity that could accelerate weakness"},{"key": "B","text": "Maximal intensity strength training regardless of fatigue"},{"key": "C","text": "Identical high-intensity protocols regardless of disease stage"},{"key": "D","text": "Complete avoidance of all physical activity throughout the disease course"}],"correct": "A","explanation": "Given concerns about overwork weakness in denervated/weakened muscle, ALS exercise programs generally favor moderate, carefully monitored, non-fatiguing approaches rather than maximal intensity training."},{"id": 6115,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Assistive devices and adaptive equipment in ALS management are important primarily to:","options": [{"key": "A","text": "Replace the need for any medical management"},{"key": "B","text": "Cure the underlying disease"},{"key": "C","text": "Only relevant in the earliest disease stage"},{"key": "D","text": "Maintain function and independence as progressive weakness develops"}],"correct": "D","explanation": "As ALS causes progressive weakness, timely provision of appropriate assistive devices/equipment helps maintain function, safety, and independence throughout the disease course."},{"id": 6116,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Dysphagia management in ALS, given progressive bulbar weakness, may eventually require consideration of:","options": [{"key": "A","text": "Immediate complete cessation of any oral intake from disease onset"},{"key": "B","text": "Percutaneous endoscopic gastrostomy (PEG) tube feeding to maintain nutrition/hydration safely"},{"key": "C","text": "Surgical intervention to reverse the underlying bulbar weakness"},{"key": "D","text": "No modification to feeding approach is ever needed regardless of swallowing function"}],"correct": "B","explanation": "As bulbar dysfunction progresses and safe oral intake becomes compromised, PEG tube placement is often considered to maintain adequate nutrition/hydration while reducing aspiration risk."},{"id": 6117,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Cognitive/behavioral changes, sometimes overlapping with frontotemporal dementia, can occur in a subset of ALS patients, which is important for:","options": [{"key": "A","text": "Only relevant in bulbar onset ALS, never limb onset"},{"key": "B","text": "Assuming all ALS patients have identical cognitive profiles"},{"key": "C","text": "No relevance to ALS management, as ALS never involves any cognitive change"},{"key": "D","text": "Comprehensive assessment and appropriately tailored communication/care planning approaches"}],"correct": "D","explanation": "A recognized subset of ALS patients develop cognitive/behavioral changes (including ALS-FTD spectrum), important to consider in comprehensive assessment and care planning approaches."},{"id": 6118,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Multidisciplinary team care in ALS management is strongly recommended because:","options": [{"key": "A","text": "ALS management requires no specialized coordinated approach"},{"key": "B","text": "The complex, multisystem progressive nature of the disease benefits from coordinated specialist input across multiple domains"},{"key": "C","text": "Multidisciplinary care has no evidence of benefit in ALS"},{"key": "D","text": "A single specialist can adequately address all aspects of ALS care"}],"correct": "B","explanation": "Given the complex, evolving, multisystem impact of ALS (motor, respiratory, nutritional, communication, psychosocial), coordinated multidisciplinary specialist care is strongly recommended and associated with improved outcomes."},{"id": 6119,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Advance care planning discussions are an important component of comprehensive ALS management primarily because:","options": [{"key": "A","text": "Advance care planning is irrelevant to ALS given its motor-only impact"},{"key": "B","text": "These discussions should always be avoided to prevent patient distress"},{"key": "C","text": "ALS never requires any consideration of end-of-life care planning"},{"key": "D","text": "The progressive, ultimately life-limiting nature of the disease benefits from proactive discussion of goals of care and future decision-making"}],"correct": "D","explanation": "Given the progressive, ultimately life-limiting trajectory of ALS, proactive advance care planning discussions (respecting patient autonomy and preferences) are an important, sensitively-handled component of comprehensive care."},{"id": 6120,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Communication aids/augmentative and alternative communication (AAC) devices become increasingly important in ALS management particularly for patients with:","options": [{"key": "A","text": "Bulbar involvement causing significant dysarthria/anarthria"},{"key": "B","text": "No relevance to ALS management regardless of symptom pattern"},{"key": "C","text": "Only relevant for patients who have never developed any speech difficulty"},{"key": "D","text": "Isolated lower limb weakness without any bulbar involvement"}],"correct": "A","explanation": "As bulbar weakness progressively affects speech (dysarthria progressing potentially to anarthria), AAC devices become increasingly important for maintaining communication ability."},{"id": 6121,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Fatigue management is an important consideration in ALS physiotherapy given:","options": [{"key": "A","text": "Fatigue is irrelevant to functional planning in ALS"},{"key": "B","text": "Only relevant in the very earliest disease stage"},{"key": "C","text": "The progressive weakness and increased effort required for daily activities can contribute to significant fatigue"},{"key": "D","text": "Fatigue never occurs in ALS patients"}],"correct": "C","explanation": "Progressive weakness increases the relative effort required for daily tasks, commonly contributing to significant fatigue that should be considered in activity planning and pacing strategies."},{"id": 6122,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the general prognosis pattern in typical ALS?","options": [{"key": "A","text": "Complete spontaneous recovery is expected in most cases"},{"key": "B","text": "A static, non-progressive condition once diagnosed"},{"key": "C","text": "Symptoms typically resolve completely within 1-2 years without any intervention"},{"key": "D","text": "Progressive, ultimately life-limiting course, though individual progression rate varies considerably"}],"correct": "D","explanation": "ALS follows a progressive, ultimately life-limiting course, though the rate of progression shows considerable individual variability, important for prognostic discussion and care planning."},{"id": 6123,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration regarding positioning/seating for ALS patients with progressive weakness?","options": [{"key": "A","text": "A single fixed seating solution provided at diagnosis requiring no future modification"},{"key": "B","text": "Positioning considerations are irrelevant to ALS management"},{"key": "C","text": "Complete avoidance of any seating/positioning equipment throughout the disease course"},{"key": "D","text": "Regular reassessment and adaptation of seating/positioning as weakness progresses, to maintain comfort, function, and prevent complications"}],"correct": "D","explanation": "Given progressive weakness, regular reassessment and timely adaptation of seating/positioning equipment is important to maintain comfort, function, and prevent secondary complications throughout the disease course."},{"id": 6124,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes appropriate range of motion management considerations in ALS patients with progressive limb weakness?","options": [{"key": "A","text": "Only active range of motion should ever be performed regardless of strength level"},{"key": "B","text": "Range of motion maintenance is only relevant in bulbar-onset ALS"},{"key": "C","text": "Range of motion exercises are unnecessary in ALS management"},{"key": "D","text": "Regular passive/active-assisted range of motion exercises to help prevent contracture as active movement capacity diminishes"}],"correct": "D","explanation": "As active movement capacity diminishes with progressive weakness, regular passive/active-assisted ROM exercises help maintain joint mobility and prevent contracture development."},{"id": 6125,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration when providing patient/family education about ALS disease progression?","options": [{"key": "A","text": "Providing honest, sensitively delivered information while supporting hope and quality of life focus throughout the disease course"},{"key": "B","text": "Providing only worst-case scenario information without any supportive context"},{"key": "C","text": "Assuming no education or discussion is needed since the diagnosis itself is sufficient information"},{"key": "D","text": "Withholding all information about disease progression from patients and families"}],"correct": "A","explanation": "Sensitive, honest communication about disease progression, balanced with support for hope and quality of life focus, is an important component of comprehensive ALS care throughout the disease trajectory."},{"id": 6126,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the role of physiotherapy assessment in monitoring ALS disease progression?","options": [{"key": "A","text": "Only medical/neurological assessment is relevant, physiotherapy assessment provides no useful information"},{"key": "B","text": "Regular functional and respiratory assessment helps track progression and guide timely intervention/equipment adaptation"},{"key": "C","text": "Assessment should only occur once at initial diagnosis with no follow-up monitoring needed"},{"key": "D","text": "Physiotherapy assessment has no role in monitoring ALS progression"}],"correct": "B","explanation": "Regular physiotherapy assessment (functional status, respiratory function, mobility) provides valuable ongoing monitoring information, helping guide timely adaptation of intervention and equipment as the disease progresses."},{"id": 6127,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Progressive Muscular Atrophy (PMA), a variant within the motor neuron disease spectrum, differs from classic ALS in that it involves:","options": [{"key": "A","text": "Predominantly or exclusively lower motor neuron involvement, without significant upper motor neuron signs"},{"key": "B","text": "Predominantly upper motor neuron involvement only"},{"key": "C","text": "Identical presentation to classic ALS with no distinguishing features"},{"key": "D","text": "Only sensory pathway involvement"}],"correct": "A","explanation": "PMA involves predominantly lower motor neuron degeneration without the significant upper motor neuron component seen in classic ALS, representing one variant within the motor neuron disease spectrum."},{"id": 6128,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Myasthenia gravis results from autoimmune antibodies targeting:","options": [{"key": "A","text": "Peripheral sensory nerve fibers"},{"key": "B","text": "Postsynaptic nicotinic acetylcholine receptors at the neuromuscular junction"},{"key": "C","text": "Motor neuron cell bodies"},{"key": "D","text": "Presynaptic calcium channels"}],"correct": "B","explanation": "MG involves autoantibodies against postsynaptic nicotinic acetylcholine receptors, impairing neuromuscular transmission."},{"id": 6129,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The hallmark clinical feature of myasthenia gravis is:","options": [{"key": "A","text": "Weakness that improves with sustained activity"},{"key": "B","text": "Fatigable weakness that worsens with sustained/repetitive activity and improves with rest"},{"key": "C","text": "Purely sensory symptoms without any weakness"},{"key": "D","text": "Weakness that remains constant regardless of activity level"}],"correct": "B","explanation": "Fatigable weakness (worsening with repeated/sustained muscle use, improving with rest) is the defining clinical characteristic of MG."},{"id": 6130,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Ocular symptoms (ptosis, diplopia) are a common initial presentation in myasthenia gravis due to:","options": [{"key": "A","text": "Particular susceptibility of extraocular and eyelid muscles to the underlying pathophysiology"},{"key": "B","text": "Only occurring in the most severe generalized cases"},{"key": "C","text": "A completely unrelated separate condition"},{"key": "D","text": "These muscles being unaffected in MG, symptoms arise elsewhere"}],"correct": "A","explanation": "Extraocular and levator palpebrae muscles show particular vulnerability in MG, commonly causing initial ptosis and diplopia symptoms."},{"id": 6131,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Myasthenic crisis refers to:","options": [{"key": "A","text": "A term unrelated to disease severity"},{"key": "B","text": "Severe exacerbation causing respiratory failure requiring urgent ventilatory support"},{"key": "C","text": "A mild, self-limiting symptom flare"},{"key": "D","text": "Only affecting ocular muscles, never respiratory function"}],"correct": "B","explanation": "Myasthenic crisis describes severe respiratory muscle weakness causing potential respiratory failure, a medical emergency requiring urgent intervention/ventilatory support."},{"id": 6132,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Edrophonium (Tensilon) test, historically used in MG diagnosis, works by:","options": [{"key": "A","text": "Only useful for excluding MG, never confirming it"},{"key": "B","text": "Directly blocking acetylcholine receptors"},{"key": "C","text": "Permanently curing the underlying disease"},{"key": "D","text": "Temporarily inhibiting acetylcholinesterase, transiently improving strength if MG is present"}],"correct": "D","explanation": "Edrophonium temporarily inhibits acetylcholinesterase, increasing available acetylcholine at the NMJ, producing transient strength improvement diagnostic of MG."},{"id": 6133,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Pyridostigmine, a common symptomatic treatment for MG, works by:","options": [{"key": "A","text": "Suppressing the autoimmune antibody production"},{"key": "B","text": "Enhancing calcium channel function presynaptically"},{"key": "C","text": "Inhibiting acetylcholinesterase, increasing acetylcholine availability at the neuromuscular junction"},{"key": "D","text": "Directly replacing the deficient neurotransmitter"}],"correct": "C","explanation": "Pyridostigmine (acetylcholinesterase inhibitor) increases acetylcholine availability at the NMJ, providing symptomatic improvement in MG."},{"id": 6134,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Thymectomy is a recognized treatment approach for myasthenia gravis, particularly relevant given the association with:","options": [{"key": "A","text": "Thymic abnormalities (hyperplasia or thymoma) commonly seen in MG patients"},{"key": "B","text": "Only relevant for patients with purely ocular MG"},{"key": "C","text": "Thymus involvement only in pediatric MG cases"},{"key": "D","text": "No relationship exists between the thymus and MG pathophysiology"}],"correct": "A","explanation": "MG is associated with thymic abnormalities (hyperplasia, or less commonly thymoma), forming the rationale for thymectomy as part of comprehensive management in appropriate patients."},{"id": 6135,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Physiotherapy exercise prescription in myasthenia gravis should consider:","options": [{"key": "A","text": "Maximal intensity exercise regardless of fatigue response"},{"key": "B","text": "Complete avoidance of any exercise due to the underlying condition"},{"key": "C","text": "The fatigable nature of MG weakness, timing exercise appropriately relative to medication dosing and monitoring for fatigue"},{"key": "D","text": "Ignoring fatigue patterns entirely during exercise prescription"}],"correct": "C","explanation": "Given the fatigable weakness pattern in MG, exercise timing relative to medication effect and careful fatigue monitoring are important considerations in physiotherapy management."},{"id": 6136,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Lambert-Eaton Myasthenic Syndrome (LEMS) differs from myasthenia gravis in that weakness characteristically:","options": [{"key": "A","text": "Improves with sustained/repeated muscle activity (rather than worsening as in MG)"},{"key": "B","text": "Never affects proximal muscles"},{"key": "C","text": "Only affects ocular muscles, never generalized weakness"},{"key": "D","text": "Worsens with sustained activity identically to MG"}],"correct": "A","explanation": "LEMS, involving presynaptic calcium channel antibodies, characteristically shows improvement in strength with repeated muscle contraction, contrasting with the fatigable pattern in MG."},{"id": 6137,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "LEMS is frequently associated with which underlying condition, making it a paraneoplastic syndrome in many cases?","options": [{"key": "A","text": "Prostate cancer"},{"key": "B","text": "Small cell lung cancer"},{"key": "C","text": "No malignancy association exists"},{"key": "D","text": "Breast cancer"}],"correct": "B","explanation": "LEMS is frequently paraneoplastic, particularly associated with small cell lung cancer, warranting appropriate malignancy screening upon diagnosis."},{"id": 6138,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Muscular dystrophies are best characterized as:","options": [{"key": "A","text": "Autoimmune conditions affecting the neuromuscular junction"},{"key": "B","text": "Acquired conditions unrelated to genetic factors"},{"key": "C","text": "Conditions primarily affecting peripheral nerves rather than muscle"},{"key": "D","text": "A group of genetic disorders causing progressive muscle degeneration and weakness"}],"correct": "D","explanation": "Muscular dystrophies are genetically determined conditions causing progressive muscle fiber degeneration and weakness, distinct from neuromuscular junction or nerve-based pathology."},{"id": 6139,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Duchenne muscular dystrophy results from mutations affecting which protein?","options": [{"key": "A","text": "Myosin"},{"key": "B","text": "Acetylcholine receptor"},{"key": "C","text": "Actin exclusively"},{"key": "D","text": "Dystrophin"}],"correct": "D","explanation": "DMD results from mutations in the dystrophin gene, causing absent/severely deficient dystrophin protein essential for muscle membrane stability."},{"id": 6140,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Duchenne muscular dystrophy is inherited in which pattern?","options": [{"key": "A","text": "Mitochondrial inheritance"},{"key": "B","text": "Autosomal dominant"},{"key": "C","text": "Autosomal recessive"},{"key": "D","text": "X-linked recessive"}],"correct": "D","explanation": "DMD follows X-linked recessive inheritance, predominantly affecting males, with female carriers occasionally showing mild symptoms."},{"id": 6141,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Becker muscular dystrophy differs from Duchenne muscular dystrophy in that it typically shows:","options": [{"key": "A","text": "A milder phenotype with later onset and slower progression, related to partially functional dystrophin"},{"key": "B","text": "Onset exclusively in adulthood with no childhood presentation"},{"key": "C","text": "Autosomal dominant inheritance pattern"},{"key": "D","text": "An identical severe phenotype to DMD"}],"correct": "A","explanation": "BMD results from mutations allowing some functional (though reduced/abnormal) dystrophin production, generally causing a milder, later-onset, more slowly progressive phenotype than DMD."},{"id": 6142,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Calf pseudohypertrophy, a classic finding in Duchenne muscular dystrophy, results from:","options": [{"key": "A","text": "True muscle hypertrophy from increased use"},{"key": "B","text": "Inflammatory swelling exclusively"},{"key": "C","text": "Fat and fibrous tissue replacement of degenerating muscle fibers"},{"key": "D","text": "Fluid retention unrelated to muscle pathology"}],"correct": "C","explanation": "Pseudohypertrophy reflects fat/fibrous tissue infiltration replacing degenerating muscle fibers, giving an enlarged appearance despite underlying weakness."},{"id": 6143,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Gower's sign in Duchenne muscular dystrophy reflects weakness of which muscle groups?","options": [{"key": "A","text": "Distal hand muscles exclusively"},{"key": "B","text": "Isolated facial muscles"},{"key": "C","text": "Proximal hip and thigh muscles"},{"key": "D","text": "Isolated respiratory muscles only"}],"correct": "C","explanation": "Gower's maneuver (using hands to 'walk up' the legs when rising from floor) compensates for proximal hip/thigh muscle weakness characteristic of DMD."},{"id": 6144,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Cardiac involvement (cardiomyopathy) is a significant concern in Duchenne muscular dystrophy management because:","options": [{"key": "A","text": "Dystrophin deficiency also affects cardiac muscle, contributing to cardiomyopathy and arrhythmia risk"},{"key": "B","text": "Cardiac involvement only occurs in Becker MD, never Duchenne"},{"key": "C","text": "Cardiac monitoring is unnecessary in DMD management"},{"key": "D","text": "Cardiac muscle is never affected in DMD, only skeletal muscle"}],"correct": "A","explanation": "Since dystrophin is also expressed in cardiac muscle, DMD commonly involves cardiomyopathy, necessitating regular cardiac monitoring as part of comprehensive management."},{"id": 6145,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Respiratory decline is an expected part of Duchenne muscular dystrophy progression, related to weakness of:","options": [{"key": "A","text": "Only occurring in the earliest disease stage before any ambulation loss"},{"key": "B","text": "Only affecting cardiac muscle, not respiratory muscles"},{"key": "C","text": "Respiratory muscles including diaphragm and intercostals"},{"key": "D","text": "Never occurring in DMD regardless of disease stage"}],"correct": "C","explanation": "Progressive respiratory muscle weakness is an expected feature of DMD progression, requiring regular respiratory monitoring and eventually ventilatory support consideration."},{"id": 6146,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Physiotherapy management in Duchenne muscular dystrophy typically emphasizes:","options": [{"key": "A","text": "Ignoring contracture prevention since it has no functional relevance"},{"key": "B","text": "Maximal intensity resistance training throughout the disease course"},{"key": "C","text": "Maintaining function, preventing contractures, and appropriate (non-fatiguing) activity, adapting to disease progression"},{"key": "D","text": "Complete immobilization to prevent any muscle damage"}],"correct": "C","explanation": "DMD physiotherapy focuses on maintaining function/mobility as long as possible, preventing/managing contractures, and appropriately dosed activity, adapting the approach as the disease progresses."},{"id": 6147,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Corticosteroid therapy (e.g., prednisone) is used in DMD management primarily to:","options": [{"key": "A","text": "Slow the rate of muscle strength decline and prolong ambulation"},{"key": "B","text": "Cure the underlying genetic condition"},{"key": "C","text": "Address respiratory symptoms exclusively, no effect on muscle strength"},{"key": "D","text": "Only provide pain relief with no effect on disease progression"}],"correct": "A","explanation": "Corticosteroids have demonstrated benefit in slowing DMD progression, prolonging ambulation and delaying complications, despite significant side effect considerations requiring careful management."},{"id": 6148,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Contracture prevention is a major focus of DMD physiotherapy management particularly affecting which joints?","options": [{"key": "A","text": "Ankle (equinus), knee, and hip flexors, along with upper limb joints as disease progresses"},{"key": "B","text": "No joints are particularly predisposed to contracture in DMD"},{"key": "C","text": "Only affecting the temporomandibular joint"},{"key": "D","text": "Only affecting the cervical spine"}],"correct": "A","explanation": "DMD commonly causes contractures at the ankle (equinus), knee, and hip flexors due to muscle imbalance and reduced mobility, with upper limb joints also becoming affected as the disease progresses."},{"id": 6149,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Myotonic dystrophy, another muscular dystrophy type, is characterized by which distinctive additional feature beyond muscle weakness?","options": [{"key": "A","text": "Purely proximal weakness pattern identical to DMD"},{"key": "B","text": "Onset exclusively in the neonatal period"},{"key": "C","text": "Myotonia (delayed muscle relaxation after contraction)"},{"key": "D","text": "Complete absence of any muscle tone abnormality"}],"correct": "C","explanation": "Myotonic dystrophy uniquely features myotonia (delayed relaxation following muscle contraction) alongside progressive weakness, along with multisystem involvement (cardiac, endocrine, cognitive)."},{"id": 6150,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Facioscapulohumeral muscular dystrophy (FSHD) characteristically affects which muscle groups initially?","options": [{"key": "A","text": "Facial, scapular, and upper arm muscles"},{"key": "B","text": "Only distal hand/foot muscles"},{"key": "C","text": "Only respiratory muscles"},{"key": "D","text": "Only cardiac muscle"}],"correct": "A","explanation": "FSHD characteristically begins with facial weakness, scapular winging, and upper arm (particularly biceps/triceps, sparing deltoid initially) weakness, as reflected in its name."},{"id": 6151,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Limb-girdle muscular dystrophy primarily affects which muscle groups?","options": [{"key": "A","text": "Only respiratory muscles exclusively"},{"key": "B","text": "Only distal hand/foot muscles"},{"key": "C","text": "Only facial muscles"},{"key": "D","text": "Proximal shoulder and hip girdle muscles"}],"correct": "D","explanation": "Limb-girdle muscular dystrophies (a heterogeneous group) primarily affect proximal shoulder and pelvic girdle musculature."},{"id": 6152,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration regarding exercise intensity in muscular dystrophy management generally?","options": [{"key": "A","text": "Exercise intensity has no relevance to muscular dystrophy management"},{"key": "B","text": "Maximal eccentric resistance training is always beneficial regardless of dystrophy type"},{"key": "C","text": "Avoiding excessive/high-resistance eccentric exercise which may accelerate muscle damage in dystrophic muscle"},{"key": "D","text": "Complete avoidance of any exercise throughout the disease course"}],"correct": "C","explanation": "Dystrophic muscle may be particularly vulnerable to damage from high-intensity eccentric loading, making moderate, carefully monitored exercise approaches generally preferred over maximal resistance training."},{"id": 6153,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the general approach to wheelchair provision timing in Duchenne muscular dystrophy as ambulation becomes increasingly difficult?","options": [{"key": "A","text": "Wheelchairs are never appropriate in DMD management"},{"key": "B","text": "Timely introduction to support safe mobility and energy conservation as walking becomes progressively more difficult/unsafe"},{"key": "C","text": "Wheelchair provision should always be delayed as long as possible regardless of safety/energy concerns"},{"key": "D","text": "Wheelchair provision timing has no relevance to overall functional outcomes"}],"correct": "B","explanation": "Timely wheelchair introduction (power or manual, as appropriate) supports continued safe mobility and energy conservation as walking becomes increasingly difficult, an important consideration in comprehensive DMD care planning."},{"id": 6154,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes an important multidisciplinary team consideration in Duchenne muscular dystrophy management?","options": [{"key": "A","text": "A single specialist can adequately manage all aspects of DMD care"},{"key": "B","text": "DMD management only requires physiotherapy input, with no other specialty involvement needed"},{"key": "C","text": "Coordinated input addressing the multisystem impact (musculoskeletal, respiratory, cardiac, and psychosocial) of the progressive condition"},{"key": "D","text": "Multidisciplinary team involvement has no evidence base in DMD management"}],"correct": "C","explanation": "Given the multisystem impact of DMD (musculoskeletal, respiratory, cardiac, psychosocial), coordinated multidisciplinary team care is considered best practice, similar to comprehensive ALS management approaches."},{"id": 6155,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Scapular winging observed in facioscapulohumeral muscular dystrophy differs from that seen in isolated long thoracic nerve palsy in that FSHD winging typically results from:","options": [{"key": "A","text": "A condition entirely unrelated to muscle weakness"},{"key": "B","text": "Nerve compression exclusively, identical to isolated nerve palsy presentations"},{"key": "C","text": "Intrinsic weakness of scapular stabilizing muscles themselves (e.g., serratus anterior, trapezius) due to the muscular dystrophy process"},{"key": "D","text": "Only occurring unilaterally, never bilaterally"}],"correct": "C","explanation": "FSHD-related winging results from the muscular dystrophy process itself weakening scapular stabilizers (often bilateral), differing from the nerve-based mechanism of isolated long thoracic nerve palsy, though the resulting clinical winging appearance can look similar."},{"id": 6156,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding genetic counseling in muscular dystrophy management, given the hereditary nature of these conditions?","options": [{"key": "A","text": "Providing family members with information regarding inheritance patterns, carrier testing, and family planning implications"},{"key": "B","text": "Genetic counseling is solely a physiotherapy responsibility with no specialist genetics involvement needed"},{"key": "C","text": "Only the affected individual requires any genetic information, family members should not be informed"},{"key": "D","text": "Genetic counseling has no relevance to muscular dystrophy since these are not hereditary conditions"}],"correct": "A","explanation": "Given the hereditary nature of most muscular dystrophies, genetic counseling addressing inheritance patterns, carrier testing, and family planning is an important component of comprehensive care, typically involving specialist genetics services."},{"id": 6157,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Congenital muscular dystrophies differ from Duchenne muscular dystrophy in that they typically present:","options": [{"key": "A","text": "Only in adulthood after age 40"},{"key": "B","text": "Only in female patients exclusively"},{"key": "C","text": "At birth or in early infancy with hypotonia and weakness"},{"key": "D","text": "Only with isolated facial weakness"}],"correct": "C","explanation": "Congenital muscular dystrophies present from birth/early infancy with hypotonia and weakness, distinguishing their onset timing from the later childhood presentation typical of DMD."},{"id": 6158,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The vestibular system primarily contributes to which functions?","options": [{"key": "A","text": "Only hearing function"},{"key": "B","text": "Only muscle strength"},{"key": "C","text": "Only cognitive function"},{"key": "D","text": "Balance, spatial orientation, and gaze stabilization"}],"correct": "D","explanation": "The vestibular system (semicircular canals, otolith organs) provides critical input for balance, spatial orientation, and reflexive gaze stabilization during head movement."},{"id": 6159,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The semicircular canals of the inner ear primarily detect:","options": [{"key": "A","text": "Angular (rotational) head acceleration"},{"key": "B","text": "Sound frequency"},{"key": "C","text": "Linear acceleration and head tilt relative to gravity"},{"key": "D","text": "Visual motion"}],"correct": "A","explanation": "The three semicircular canals detect angular/rotational head movements in three planes."},{"id": 6160,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The otolith organs (utricle and saccule) primarily detect:","options": [{"key": "A","text": "Linear acceleration and head position relative to gravity"},{"key": "B","text": "Sound intensity"},{"key": "C","text": "Visual acuity"},{"key": "D","text": "Angular/rotational head movement"}],"correct": "A","explanation": "Utricle and saccule detect linear acceleration and static head tilt/position relative to gravity."},{"id": 6161,"subject": "Neurology","topic": "Neuroanatomy & Physiology Basics","difficulty": "Medium","question": "The Vestibulo-Ocular Reflex (VOR) functions to:","options": [{"key": "A","text": "Control hearing sensitivity"},{"key": "B","text": "Regulate blood pressure"},{"key": "C","text": "Stabilize gaze/vision during head movement by producing compensatory eye movements"},{"key": "D","text": "Stabilize posture during standing"}],"correct": "C","explanation": "VOR produces eye movements opposite to head movement direction, maintaining stable visual fixation during head motion."},{"id": 6162,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Benign Paroxysmal Positional Vertigo (BPPV) results from:","options": [{"key": "A","text": "Vestibular nerve inflammation"},{"key": "B","text": "Cochlear damage exclusively"},{"key": "C","text": "Central brainstem lesion"},{"key": "D","text": "Displaced otoconia (canaliths) within the semicircular canals"}],"correct": "D","explanation": "BPPV results from otoconia (calcium carbonate crystals) becoming dislodged from the utricle and migrating into a semicircular canal, causing abnormal fluid movement/vertigo with position changes."},{"id": 6163,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The posterior semicircular canal is the most commonly affected canal in BPPV, accounting for approximately what percentage of cases?","options": [{"key": "A","text": "50%"},{"key": "B","text": "Approximately 80-90%"},{"key": "C","text": "100% of all cases exclusively"},{"key": "D","text": "Less than 5%"}],"correct": "B","explanation": "Posterior canal BPPV is by far the most common variant, accounting for the vast majority of cases."},{"id": 6164,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The Dix-Hallpike test is used to diagnose which condition?","options": [{"key": "A","text": "Vestibular neuritis exclusively"},{"key": "B","text": "Central vestibular disorders exclusively"},{"key": "C","text": "Meniere's disease exclusively"},{"key": "D","text": "Posterior (or anterior) canal BPPV"}],"correct": "D","explanation": "Dix-Hallpike positioning maneuver provokes characteristic nystagmus/vertigo diagnostic of posterior (or anterior) canal BPPV."},{"id": 6165,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The Epley maneuver is a treatment technique used for:","options": [{"key": "A","text": "Strengthening vestibular function generally"},{"key": "B","text": "Managing Meniere's disease exclusively"},{"key": "C","text": "Repositioning displaced otoconia in posterior canal BPPV"},{"key": "D","text": "Treating central vestibular disorders"}],"correct": "C","explanation": "Epley (canalith repositioning) maneuver sequentially moves the head to guide displaced otoconia out of the semicircular canal back into the utricle, effectively treating posterior canal BPPV."},{"id": 6166,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The Roll test (Pagnini-McClure maneuver) is used to assess for BPPV affecting which canal?","options": [{"key": "A","text": "No specific canal association"},{"key": "B","text": "Horizontal (lateral) semicircular canal"},{"key": "C","text": "Posterior canal exclusively"},{"key": "D","text": "Anterior canal exclusively"}],"correct": "B","explanation": "The supine roll test specifically assesses for horizontal canal BPPV, producing characteristic horizontal nystagmus."},{"id": 6167,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Vestibular neuritis typically presents with:","options": [{"key": "A","text": "Chronic intermittent vertigo over years without any acute episode"},{"key": "B","text": "Acute, severe, continuous vertigo lasting days, without hearing loss"},{"key": "C","text": "Brief positional vertigo episodes lasting seconds"},{"key": "D","text": "Hearing loss as the predominant symptom without any vertigo"}],"correct": "B","explanation": "Vestibular neuritis (presumed viral inflammation of the vestibular nerve) causes acute, severe, continuous vertigo lasting days, typically without associated hearing changes."},{"id": 6168,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Labyrinthitis differs from vestibular neuritis in that it additionally involves:","options": [{"key": "A","text": "Only affecting balance, never any auditory symptoms"},{"key": "B","text": "No vertigo whatsoever"},{"key": "C","text": "Hearing loss/tinnitus, due to concurrent cochlear involvement"},{"key": "D","text": "Chronic recurrent episodes rather than a single acute event"}],"correct": "C","explanation": "Labyrinthitis involves both vestibular and cochlear structures, causing vertigo plus hearing loss/tinnitus, unlike vestibular neuritis which spares hearing."},{"id": 6169,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Meniere's disease is classically characterized by which symptom triad?","options": [{"key": "A","text": "Isolated positional vertigo without any other symptoms"},{"key": "B","text": "Chronic imbalance without any acute episodic component"},{"key": "C","text": "Episodic vertigo, fluctuating hearing loss, and tinnitus (often with aural fullness)"},{"key": "D","text": "Progressive hearing loss without any vertigo"}],"correct": "C","explanation": "Meniere's disease classically presents with the triad of episodic vertigo, fluctuating sensorineural hearing loss, and tinnitus, often with a sensation of aural fullness."},{"id": 6170,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Meniere's disease is thought to result from:","options": [{"key": "A","text": "Otoconia displacement into the semicircular canals"},{"key": "B","text": "Vestibular nerve tumor"},{"key": "C","text": "Central brainstem lesion"},{"key": "D","text": "Endolymphatic hydrops (excess endolymph fluid pressure within the inner ear)"}],"correct": "D","explanation": "Endolymphatic hydrops (abnormal fluid accumulation within the membranous labyrinth) is the presumed underlying pathophysiology of Meniere's disease."},{"id": 6171,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Vestibular rehabilitation therapy (VRT) for peripheral vestibular hypofunction primarily works through which mechanism?","options": [{"key": "A","text": "Promoting central vestibular compensation through habituation, adaptation, and substitution exercises"},{"key": "B","text": "Directly regenerating damaged vestibular hair cells"},{"key": "C","text": "Complete avoidance of any head movement to prevent symptom provocation"},{"key": "D","text": "Only through medication, with no exercise-based component"}],"correct": "A","explanation": "VRT leverages central nervous system plasticity to promote compensation for peripheral vestibular deficits through targeted habituation, adaptation (gaze stabilization), and substitution exercises."},{"id": 6172,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Gaze stabilization exercises (e.g., VOR x1 training) in vestibular rehabilitation aim to:","options": [{"key": "A","text": "Address only balance without any visual component"},{"key": "B","text": "Improve VOR function/gain to maintain stable vision during head movement"},{"key": "C","text": "Reduce blood pressure"},{"key": "D","text": "Improve hearing function"}],"correct": "B","explanation": "Gaze stabilization exercises specifically train the VOR to promote adaptation and improve visual stability during head movement, addressing a common complaint (blurred vision with head motion) in vestibular hypofunction."},{"id": 6173,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Habituation exercises in vestibular rehabilitation are particularly useful for patients experiencing:","options": [{"key": "A","text": "Symptoms provoked by specific repeated movements/positions, using controlled repeated exposure to promote symptom reduction"},{"key": "B","text": "Only relevant for patients with normal vestibular function"},{"key": "C","text": "Complete avoidance of any provoking movement as the primary strategy"},{"key": "D","text": "Only useful for central vestibular disorders, never peripheral"}],"correct": "A","explanation": "Habituation exercises involve controlled repeated exposure to specific symptom-provoking movements/positions, promoting gradual reduction in symptom intensity through central adaptation."},{"id": 6174,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Substitution exercises in vestibular rehabilitation aim to:","options": [{"key": "A","text": "Promote use of alternative sensory strategies (visual, somatosensory) to compensate for permanent vestibular loss"},{"key": "B","text": "Restore complete normal vestibular function in all cases"},{"key": "C","text": "Replace the need for any other vestibular rehabilitation technique"},{"key": "D","text": "Only be used for BPPV management"}],"correct": "A","explanation": "Substitution strategies help patients with significant/permanent vestibular loss develop compensatory reliance on visual and somatosensory input for balance control."},{"id": 6175,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes central vestibular disorders compared to peripheral vestibular disorders?","options": [{"key": "A","text": "Central disorders arise from brainstem/cerebellar pathology, often with additional neurological signs beyond isolated vestibular symptoms"},{"key": "B","text": "Central disorders are always milder than peripheral disorders"},{"key": "C","text": "Central vestibular disorders never cause any vertigo symptoms"},{"key": "D","text": "Central and peripheral vestibular disorders present identically with no distinguishing features"}],"correct": "A","explanation": "Central vestibular disorders (from brainstem/cerebellar pathology) often present with additional neurological signs (e.g., other cranial nerve findings, ataxia) beyond isolated vestibular symptoms, an important differentiating consideration."},{"id": 6176,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following nystagmus characteristics would be more suggestive of a central rather than peripheral vestibular cause?","options": [{"key": "A","text": "Nystagmus consistently in one direction with a clear latency period"},{"key": "B","text": "Nystagmus that fatigues/habituates with repeated testing and is suppressed by fixation"},{"key": "C","text": "Purely vertical or direction-changing nystagmus not suppressed by visual fixation"},{"key": "D","text": "Nystagmus limited to horizontal-torsional pattern"}],"correct": "C","explanation": "Central vestibular nystagmus often shows features like pure vertical direction, direction-changing pattern, or lack of visual fixation suppression, differing from typical peripheral BPPV nystagmus characteristics."},{"id": 6177,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following is an important 'red flag' consideration when assessing a patient presenting with acute vertigo?","options": [{"key": "A","text": "Red flag screening is unnecessary in vestibular assessment"},{"key": "B","text": "Additional neurological symptoms/signs suggesting possible central (e.g., stroke) rather than purely peripheral cause"},{"key": "C","text": "All vertigo presentations can be safely assumed to be peripheral in origin"},{"key": "D","text": "Vertigo is never associated with any serious underlying pathology"}],"correct": "B","explanation": "Careful screening for additional neurological signs/symptoms is important to identify potential central causes (e.g., posterior circulation stroke) requiring urgent medical referral, distinguishing from benign peripheral vestibular causes."},{"id": 6178,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The HINTS examination (Head Impulse, Nystagmus, Test of Skew) is used clinically to help differentiate:","options": [{"key": "A","text": "BPPV canal variants from each other"},{"key": "B","text": "Vestibular disorders from purely orthopedic balance impairments"},{"key": "C","text": "Meniere's disease from labyrinthitis"},{"key": "D","text": "Peripheral vestibular neuritis from central (stroke) causes of acute vestibular syndrome"}],"correct": "D","explanation": "HINTS examination, when properly applied in acute vestibular syndrome, can help identify findings more suggestive of central (stroke) versus peripheral (vestibular neuritis) etiology."},{"id": 6179,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important balance assessment consideration incorporating the concept of sensory conflict/reweighting?","options": [{"key": "A","text": "Only vestibular function needs assessment, ignoring visual/somatosensory contributions"},{"key": "B","text": "Sensory conditions have no relevance to balance assessment"},{"key": "C","text": "Assessing balance performance under varying sensory conditions (e.g., altered vision, surface) to understand sensory system contributions/reliance"},{"key": "D","text": "Balance assessment only requires testing on a stable, well-lit surface"}],"correct": "C","explanation": "Assessing balance performance across varying sensory conditions helps identify specific sensory system deficits/over-reliance patterns, informing targeted balance rehabilitation approaches."},{"id": 6180,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The Clinical Test of Sensory Interaction on Balance (CTSIB) assesses balance under which varying conditions?","options": [{"key": "A","text": "Combinations of eyes open/closed and stable/unstable support surface"},{"key": "B","text": "Only different walking speeds"},{"key": "C","text": "Only different room temperatures"},{"key": "D","text": "Only different times of day"}],"correct": "A","explanation": "CTSIB systematically varies visual input (eyes open/closed, sometimes with visual conflict dome) and surface stability to assess sensory system contributions to balance."},{"id": 6181,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding fall risk assessment in patients with vestibular disorders?","options": [{"key": "A","text": "Vestibular disorders have no relationship to fall risk"},{"key": "B","text": "Fall risk assessment is irrelevant to vestibular rehabilitation planning"},{"key": "C","text": "Vestibular dysfunction significantly increases fall risk, warranting comprehensive balance/fall risk assessment as part of vestibular rehabilitation"},{"key": "D","text": "Only relevant for elderly patients with vestibular disorders, not younger patients"}],"correct": "C","explanation": "Vestibular dysfunction is a recognized significant contributor to fall risk across age groups, making comprehensive fall risk assessment an important component of vestibular rehabilitation."},{"id": 6182,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Cervicogenic dizziness, related to altered cervical proprioceptive input, should be considered in differential diagnosis particularly when dizziness is associated with:","options": [{"key": "A","text": "Only occurring with eyes closed, never with eyes open"},{"key": "B","text": "Only affecting hearing, never balance"},{"key": "C","text": "Complete absence of any neck-related symptoms"},{"key": "D","text": "Neck pain/stiffness and provoked by neck movement rather than purely head movement in space"}],"correct": "D","explanation": "Cervicogenic dizziness is considered when dizziness correlates with neck pain/movement patterns, requiring careful differentiation from primary vestibular causes."},{"id": 6183,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the general prognosis for BPPV following appropriate canalith repositioning treatment?","options": [{"key": "A","text": "Treatment success rates are equally poor regardless of technique used"},{"key": "B","text": "Poor prognosis with treatment rarely providing any benefit"},{"key": "C","text": "BPPV always resolves spontaneously without any need for treatment"},{"key": "D","text": "Generally good, with high success rates in resolving symptoms, though recurrence can occur"}],"correct": "D","explanation": "Canalith repositioning maneuvers (e.g., Epley) generally show high success rates for BPPV symptom resolution, though recurrence is possible, sometimes requiring repeat treatment."},{"id": 6184,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important safety consideration during vestibular rehabilitation exercise progression?","options": [{"key": "A","text": "Maximum difficulty exercises should always be prescribed regardless of symptom response"},{"key": "B","text": "Careful monitoring for symptom provocation and fall risk, progressing exercise difficulty appropriately based on individual tolerance and safety"},{"key": "C","text": "Complete avoidance of any exercise that provokes symptoms, even mild manageable symptoms"},{"key": "D","text": "Vestibular exercises carry no safety considerations requiring monitoring"}],"correct": "B","explanation": "Vestibular rehabilitation requires careful monitoring of symptom response and fall risk, with appropriately graded exercise progression balancing therapeutic benefit (some symptom provocation is often necessary for habituation) against safety."},{"id": 6185,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes bilateral vestibular hypofunction/loss in terms of rehabilitation approach compared to unilateral loss?","options": [{"key": "A","text": "Bilateral loss always shows better recovery than unilateral loss"},{"key": "B","text": "Identical rehabilitation approach to unilateral loss with no distinction needed"},{"key": "C","text": "Bilateral vestibular loss cannot be addressed through any rehabilitation approach"},{"key": "D","text": "Often relies more heavily on substitution strategies (visual/somatosensory) given reduced potential for typical central compensation mechanisms"}],"correct": "D","explanation": "Bilateral vestibular loss, lacking a relatively intact side to help drive typical compensation mechanisms, often requires greater emphasis on substitution strategies (enhanced visual/somatosensory reliance) in rehabilitation."},{"id": 6186,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding vision and vestibular rehabilitation for patients with additional visual impairment?","options": [{"key": "A","text": "Assuming identical rehabilitation approach regardless of visual status"},{"key": "B","text": "Visual impairment has no relevance to vestibular rehabilitation planning"},{"key": "C","text": "Visual impairment may limit the effectiveness of substitution strategies relying on vision, requiring adapted approaches emphasizing other available sensory systems"},{"key": "D","text": "Vestibular rehabilitation is contraindicated in patients with any visual impairment"}],"correct": "C","explanation": "Co-existing visual impairment can limit the effectiveness of visually-based substitution strategies, requiring thoughtful adaptation of the vestibular rehabilitation approach to emphasize other available compensatory systems."},{"id": 6187,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the general approach to progressing balance training difficulty in vestibular/balance rehabilitation programs?","options": [{"key": "A","text": "Using a single fixed difficulty level throughout the entire rehabilitation program"},{"key": "B","text": "Avoiding any progression to prevent overwhelming the patient"},{"key": "C","text": "Systematically increasing challenge (e.g., reducing base of support, altering surface, adding dual-task demands) as the patient's ability improves"},{"key": "D","text": "Random unstructured progression without any systematic approach"}],"correct": "C","explanation": "Balance/vestibular rehabilitation typically follows a systematic progression model, gradually increasing task complexity/challenge as the patient's tolerance and ability improve."},{"id": 6188,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes the potential impact of anxiety/psychological factors in patients with chronic dizziness/vestibular symptoms?","options": [{"key": "A","text": "Vestibular rehabilitation should never address any psychological aspect of the presentation"},{"key": "B","text": "Anxiety and vestibular symptoms can interact bidirectionally, sometimes requiring integrated management addressing both physical and psychological components"},{"key": "C","text": "Anxiety always resolves completely once vestibular function is restored, requiring no separate consideration"},{"key": "D","text": "Psychological factors have no relevance to vestibular symptom presentation or management"}],"correct": "B","explanation": "Chronic dizziness and anxiety can interact bidirectionally (persistent postural-perceptual dizziness being a recognized example), sometimes warranting integrated management approaches addressing both physical and psychological contributing factors."},{"id": 6189,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes Persistent Postural-Perceptual Dizziness (PPPD) as a recognized clinical entity?","options": [{"key": "A","text": "An acute peripheral vestibular condition identical to vestibular neuritis"},{"key": "B","text": "A chronic functional vestibular disorder characterized by persistent dizziness/unsteadiness, often triggered/exacerbated by an initial vestibular event but perpetuated by additional factors"},{"key": "C","text": "A condition exclusively caused by inner ear structural damage with no functional component"},{"key": "D","text": "A term with no clinical validity or recognition"}],"correct": "B","explanation": "PPPD is an increasingly recognized chronic functional vestibular disorder, often triggered by an initial vestibular event but perpetuated by maladaptive postural strategies and psychological factors, requiring a somewhat different management approach than acute peripheral vestibular conditions."},{"id": 6190,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an appropriate approach for a patient with suspected BPPV who also reports significant neck pain/limited cervical rotation, potentially complicating standard positional testing?","options": [{"key": "A","text": "Considering modified testing positions or alternative approaches while being mindful of cervical precautions"},{"key": "B","text": "Assuming BPPV cannot be assessed at all if any neck limitation is present"},{"key": "C","text": "Ignoring the cervical spine consideration entirely during vestibular assessment"},{"key": "D","text": "Forcing standard Dix-Hallpike positioning regardless of neck limitations or pain"}],"correct": "A","explanation": "Cervical spine limitations/precautions may require modified testing approaches for BPPV assessment, balancing diagnostic needs with patient safety/comfort regarding neck positioning."},{"id": 6191,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the Semont maneuver as a treatment option for posterior canal BPPV?","options": [{"key": "A","text": "Identical technique to the Epley maneuver with no distinguishing features"},{"key": "B","text": "A technique only used for horizontal canal BPPV"},{"key": "C","text": "A purely diagnostic test with no therapeutic application"},{"key": "D","text": "A liberatory maneuver using rapid positional changes to dislodge otoconia from the canal"}],"correct": "D","explanation": "The Semont maneuver is an alternative canalith repositioning technique using rapid sequential positioning changes, effective for posterior canal BPPV treatment."},{"id": 6192,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding post-treatment instructions following a canalith repositioning maneuver for BPPV?","options": [{"key": "A","text": "No follow-up or reassessment is ever needed after treatment"},{"key": "B","text": "Strict 24-48 hour upright positioning is universally required and evidence-strongly supports this in all cases"},{"key": "C","text": "Patients should immediately resume all activities including high-risk activities without any caution"},{"key": "D","text": "Historical post-maneuver positional restrictions are now considered largely unnecessary based on current evidence, though patient-specific guidance may still be given"}],"correct": "D","explanation": "Current evidence suggests that strict post-treatment positional restrictions (once commonly recommended) provide limited additional benefit over the repositioning maneuver alone, though individualized guidance and follow-up remain appropriate."},{"id": 6193,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The cerebellum is primarily responsible for:","options": [{"key": "A","text": "Initiating voluntary movement"},{"key": "B","text": "Language production"},{"key": "C","text": "Primary sensory processing"},{"key": "D","text": "Coordinating movement timing, accuracy, and balance"}],"correct": "D","explanation": "The cerebellum coordinates the timing and accuracy of movement and contributes significantly to balance, without directly initiating voluntary movement."},{"id": 6194,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Cerebellar lesions typically produce signs on which side of the body?","options": [{"key": "A","text": "Bilateral regardless of lesion side"},{"key": "B","text": "Contralateral to the lesion"},{"key": "C","text": "No consistent lateralization"},{"key": "D","text": "Ipsilateral to the lesion"}],"correct": "D","explanation": "Due to double decussation of cerebellar pathways, cerebellar lesions characteristically produce ipsilateral signs, unlike cerebral hemisphere lesions."},{"id": 6195,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Dysmetria, a cardinal cerebellar sign, refers to:","options": [{"key": "A","text": "Sensory loss"},{"key": "B","text": "Impaired ability to judge distance/range during movement, causing overshoot or undershoot"},{"key": "C","text": "Complete absence of any movement"},{"key": "D","text": "Increased muscle tone"}],"correct": "B","explanation": "Dysmetria describes difficulty accurately judging the distance/range needed for a movement, resulting in overshoot (hypermetria) or undershoot (hypometria)."},{"id": 6196,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Dysdiadochokinesia refers to:","options": [{"key": "A","text": "Loss of sensation"},{"key": "B","text": "Abnormal gait pattern exclusively"},{"key": "C","text": "Impaired ability to perform rapid alternating movements"},{"key": "D","text": "Increased deep tendon reflexes"}],"correct": "C","explanation": "Dysdiadochokinesia describes difficulty with rapid alternating movements (e.g., hand pronation-supination), a classic cerebellar sign."},{"id": 6197,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Intention tremor, a cerebellar sign, is characterized by:","options": [{"key": "A","text": "Tremor that worsens as the limb approaches its target during goal-directed movement"},{"key": "B","text": "Tremor that improves as the target is approached"},{"key": "C","text": "Tremor unrelated to any movement or posture"},{"key": "D","text": "Tremor present only at rest, diminishing with movement"}],"correct": "A","explanation": "Intention tremor increases in amplitude as a movement approaches its target, distinguishing it from Parkinsonian resting tremor."},{"id": 6198,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Cerebellar (ataxic) gait is characterized by:","options": [{"key": "A","text": "Wide-based, unsteady gait, often with irregular step length/timing"},{"key": "B","text": "Normal gait pattern with no observable abnormality"},{"key": "C","text": "Narrow-based gait with small shuffling steps"},{"key": "D","text": "Scissoring gait pattern"}],"correct": "A","explanation": "Cerebellar ataxic gait shows a characteristic wide base of support with irregular, unsteady stepping pattern."},{"id": 6199,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Scanning dysarthria, a cerebellar speech pattern, is characterized by:","options": [{"key": "A","text": "Rapid, pressured speech"},{"key": "B","text": "Complete loss of speech production ability"},{"key": "C","text": "Slow, deliberate speech with irregular stress/rhythm pattern"},{"key": "D","text": "Whispered, soft speech (hypophonia)"}],"correct": "C","explanation": "Scanning dysarthria describes the characteristic irregular, slow, poorly modulated speech pattern seen with cerebellar dysfunction, sometimes described as 'explosive' or scanning quality."},{"id": 6200,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Nystagmus associated with cerebellar dysfunction typically shows which characteristic?","options": [{"key": "A","text": "Complete absence of any eye movement abnormality"},{"key": "B","text": "Only present with eyes closed, never observable with eyes open"},{"key": "C","text": "Gaze-evoked nystagmus, often worse looking toward the side of the lesion"},{"key": "D","text": "Only occurring with specific head positions, identical to BPPV pattern"}],"correct": "C","explanation": "Cerebellar dysfunction commonly produces gaze-evoked nystagmus, often more pronounced when looking toward the affected side."},{"id": 6201,"subject": "Neurology","topic": "Parkinsonism & Movement Disorders","difficulty": "Medium","question": "Titubation, a rhythmic tremor of the head/trunk, is associated with dysfunction of which cerebellar region particularly?","options": [{"key": "A","text": "Only the flocculonodular lobe"},{"key": "B","text": "Cerebellar hemispheres exclusively, never midline structures"},{"key": "C","text": "A structure unrelated to the cerebellum"},{"key": "D","text": "Cerebellar vermis (midline structures)"}],"correct": "D","explanation": "Titubation is particularly associated with midline (vermis) cerebellar dysfunction, affecting axial/proximal postural control."},{"id": 6202,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Hypotonia is a recognized feature of cerebellar dysfunction, typically presenting as:","options": [{"key": "A","text": "Complete absence of any reflex response"},{"key": "B","text": "Reduced resistance to passive movement with pendular reflexes"},{"key": "C","text": "Rigid resistance throughout range of motion"},{"key": "D","text": "Increased resistance to passive movement"}],"correct": "B","explanation": "Cerebellar hypotonia presents with reduced tone and characteristically pendular (swinging) deep tendon reflexes."},{"id": 6203,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Friedreich's ataxia, a hereditary ataxic condition, is characterized by:","options": [{"key": "A","text": "Onset exclusively after age 60"},{"key": "B","text": "Autosomal dominant inheritance pattern"},{"key": "C","text": "Purely cerebellar signs with no other body system involvement"},{"key": "D","text": "Progressive ataxia with additional features including cardiomyopathy and skeletal deformities (e.g., scoliosis, pes cavus)"}],"correct": "D","explanation": "Friedreich's ataxia (autosomal recessive) combines progressive ataxia with cardiomyopathy, skeletal deformities, and other features, typically presenting in childhood/adolescence."},{"id": 6204,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Spinocerebellar ataxias (SCAs) are a group of conditions characterized by:","options": [{"key": "A","text": "A single uniform clinical presentation across all subtypes"},{"key": "B","text": "Onset exclusively in infancy"},{"key": "C","text": "Exclusively acquired (non-genetic) etiology"},{"key": "D","text": "Hereditary, progressive cerebellar degeneration, often with variable additional neurological features depending on specific subtype"}],"correct": "D","explanation": "SCAs represent a genetically heterogeneous group of hereditary progressive cerebellar ataxias, with numerous subtypes showing variable additional features."},{"id": 6205,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Acute cerebellar ataxia in children is most commonly associated with:","options": [{"key": "A","text": "Never occurring in the pediatric population"},{"key": "B","text": "Always indicating an underlying tumor requiring immediate surgery"},{"key": "C","text": "Post-viral/post-infectious etiology, often self-limiting"},{"key": "D","text": "Hereditary causes exclusively"}],"correct": "C","explanation": "Acute cerebellar ataxia in children is frequently post-infectious/post-viral, generally following a self-limiting course, though other causes should be appropriately excluded."},{"id": 6206,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Physiotherapy management for cerebellar ataxia commonly emphasizes:","options": [{"key": "A","text": "Strengthening exercises exclusively, without any coordination component"},{"key": "B","text": "Balance training, coordination exercises, and strategies to compensate for movement inaccuracy"},{"key": "C","text": "Only passive range of motion exercises"},{"key": "D","text": "Complete avoidance of any balance challenge"}],"correct": "B","explanation": "Ataxia rehabilitation focuses on balance/coordination training and compensatory strategies (e.g., weighted devices, wider base of support) to manage functional impact of movement inaccuracy."},{"id": 6207,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Weighted devices/equipment (e.g., weighted utensils, walking aids) are sometimes used in ataxia management to:","options": [{"key": "A","text": "Provide additional proprioceptive feedback and dampen tremor/inaccuracy, improving functional task performance"},{"key": "B","text": "Only used for cosmetic purposes"},{"key": "C","text": "Strengthen muscles directly through resistance training"},{"key": "D","text": "Cure the underlying cerebellar pathology"}],"correct": "A","explanation": "Added weight can provide additional sensory feedback and mechanically dampen excessive movement amplitude/tremor, sometimes improving functional performance in ataxic patients."},{"id": 6208,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Frenkel's exercises, a classic rehabilitation approach for ataxia, emphasize:","options": [{"key": "A","text": "High-resistance strength training"},{"key": "B","text": "Passive stretching exclusively"},{"key": "C","text": "Complete rest and avoidance of movement practice"},{"key": "D","text": "Repetitive, precise movement practice using visual feedback to improve coordination"}],"correct": "D","explanation": "Frenkel's exercises use structured, repetitive practice of precise movements with visual feedback and concentration, a traditional approach to ataxia rehabilitation."},{"id": 6209,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding gait aid prescription for patients with significant ataxia?","options": [{"key": "A","text": "Selecting devices providing appropriate stability (e.g., wider-based walker) considering the specific balance/coordination deficits present"},{"key": "B","text": "A single cane is always the most appropriate device regardless of ataxia severity"},{"key": "C","text": "Gait aids are never appropriate for ataxic patients"},{"key": "D","text": "Assuming identical device needs regardless of individual presentation"}],"correct": "A","explanation": "Gait aid selection for ataxic patients should consider the specific balance/coordination deficit pattern, often favoring wider-based, more stable devices given the characteristic wide-based unsteady gait pattern."},{"id": 6210,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes the general prognosis consideration for progressive hereditary ataxias (e.g., Friedreich's ataxia, SCAs) compared to some acute/acquired ataxic conditions?","options": [{"key": "A","text": "Progressive hereditary ataxias typically show gradual worsening over time, differing from the potentially more favorable recovery trajectory of some acute/acquired causes"},{"key": "B","text": "Hereditary ataxias always show better prognosis than acquired causes"},{"key": "C","text": "Progressive ataxias always resolve completely within a few years"},{"key": "D","text": "All ataxic conditions show identical progressive, non-recovering courses"}],"correct": "A","explanation": "Progressive hereditary ataxic conditions generally follow a gradually worsening course, contrasting with certain acute/acquired causes (e.g., some post-infectious ataxias) which may show more complete recovery potential."},{"id": 6211,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important safety consideration during functional mobility training for a patient with significant ataxia, given their increased fall risk?","options": [{"key": "A","text": "Close supervision/guarding and appropriate environmental setup, considering the characteristic wide-based unsteady gait and coordination impairment"},{"key": "B","text": "No specific safety considerations are needed beyond standard mobility training approaches"},{"key": "C","text": "Complete avoidance of any mobility training due to safety concerns"},{"key": "D","text": "Assuming ataxic patients have no increased fall risk compared to the general population"}],"correct": "A","explanation": "Given the significantly increased fall risk associated with ataxic gait/coordination impairment, careful supervision and environmental considerations are important safety priorities during functional mobility training."},{"id": 6212,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to exercise dosing/progression in ataxia rehabilitation, considering the potential for fatigue to worsen coordination?","options": [{"key": "A","text": "Ignoring any fatigue-related changes during exercise sessions"},{"key": "B","text": "Monitoring for fatigue-related symptom worsening and appropriately pacing exercise progression accordingly"},{"key": "C","text": "Complete avoidance of any exercise due to fatigue concerns"},{"key": "D","text": "Maximal intensity exercise regardless of fatigue-related coordination changes"}],"correct": "B","explanation": "Since fatigue can worsen coordination/ataxia symptoms, appropriately monitoring for this effect and pacing exercise progression accordingly is an important consideration in ataxia rehabilitation programming."},{"id": 6213,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The Bobath concept (Neurodevelopmental Treatment) was originally developed for management of:","options": [{"key": "A","text": "Muscular dystrophy exclusively"},{"key": "B","text": "Spinal cord injury exclusively"},{"key": "C","text": "Peripheral nerve injuries exclusively"},{"key": "D","text": "Cerebral palsy and adult hemiplegia following stroke"}],"correct": "D","explanation": "The Bobath approach was originally developed by Berta and Karel Bobath for treating cerebral palsy in children and later applied to adult hemiplegia."},{"id": 6214,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The traditional Bobath approach historically emphasized which key concept regarding abnormal muscle tone?","options": [{"key": "A","text": "Inhibiting abnormal tone/reflex patterns and facilitating more normal movement through specific handling techniques"},{"key": "B","text": "Ignoring tone entirely and focusing only on strength training"},{"key": "C","text": "Avoiding any handling or facilitation techniques"},{"key": "D","text": "Maximizing abnormal tone patterns to enhance function"}],"correct": "A","explanation": "Classic Bobath theory emphasized normalizing abnormal tone and facilitating more typical movement patterns through specific therapeutic handling, though the approach has evolved considerably with updated neuroscience understanding."},{"id": 6215,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Contemporary evidence-based practice has led to evolution of the Bobath concept to increasingly incorporate:","options": [{"key": "A","text": "Principles of motor learning, task-specific practice, and active patient participation"},{"key": "B","text": "Rejection of any neuroplasticity-based rationale"},{"key": "C","text": "Complete abandonment of any handling techniques"},{"key": "D","text": "Exclusive focus on passive treatment approaches"}],"correct": "A","explanation": "Modern NDT/Bobath practice has evolved to integrate contemporary motor learning and neuroplasticity principles, emphasizing more active, task-specific patient participation alongside traditional handling skills."},{"id": 6216,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Proprioceptive Neuromuscular Facilitation (PNF) was developed based on the principle of:","options": [{"key": "A","text": "Using diagonal movement patterns and specific facilitation techniques to promote neuromuscular response"},{"key": "B","text": "Complete rest and avoidance of any active movement"},{"key": "C","text": "Only isolated single-joint movement in cardinal planes"},{"key": "D","text": "Purely passive stretching without any active facilitation component"}],"correct": "A","explanation": "PNF, developed by Kabat and colleagues, uses functional diagonal movement patterns combined with specific facilitation techniques (stretch, resistance, verbal cues) to promote neuromuscular response."},{"id": 6217,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The 'contract-relax' PNF technique is primarily used to:","options": [{"key": "A","text": "Increase muscle power explosively"},{"key": "B","text": "Replace all strengthening approaches"},{"key": "C","text": "Improve range of motion through post-isometric relaxation of the target muscle"},{"key": "D","text": "Assess joint stability specifically"}],"correct": "C","explanation": "Contract-relax uses isometric contraction of the tight muscle followed by relaxation to facilitate increased stretch/ROM, based on autogenic inhibition principles."},{"id": 6218,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Rhythmic stabilization' PNF technique primarily aims to:","options": [{"key": "A","text": "Only used for gait training, not stability"},{"key": "B","text": "Increase range of motion through passive stretching"},{"key": "C","text": "Facilitate maximal concentric strength"},{"key": "D","text": "Improve stability through alternating isometric contractions of agonist and antagonist muscles"}],"correct": "D","explanation": "Rhythmic stabilization uses alternating isometric holds against resistance in opposing directions to enhance co-contraction and postural stability."},{"id": 6219,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The Motor Relearning Programme (MRP), developed by Carr and Shepherd, emphasizes:","options": [{"key": "A","text": "Task-specific practice with active problem-solving, based on motor learning and biomechanical principles"},{"key": "B","text": "Avoidance of functional task practice entirely"},{"key": "C","text": "Purely isolated muscle strengthening without functional context"},{"key": "D","text": "Passive handling techniques as the primary intervention approach"}],"correct": "A","explanation": "MRP is grounded in motor learning theory and biomechanics, emphasizing active, task-specific practice with patient problem-solving and minimal unnecessary handling."},{"id": 6220,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Task-oriented training approaches share which common underlying principle?","options": [{"key": "A","text": "Complete avoidance of repetitive practice to prevent overuse"},{"key": "B","text": "Isolated impairment-focused exercise is always superior to functional task practice"},{"key": "C","text": "Practice of meaningful, functional tasks promotes motor learning and neuroplastic adaptation relevant to real-world function"},{"key": "D","text": "Passive modalities are the primary driver of functional recovery"}],"correct": "C","explanation": "Task-oriented approaches share the underlying principle that practicing meaningful, functional tasks (rather than isolated impairment-focused exercises alone) best promotes relevant motor learning and neuroplastic change."},{"id": 6221,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes a key principle of motor learning relevant to neurorehabilitation practice?","options": [{"key": "A","text": "Feedback should always be avoided during motor skill practice"},{"key": "B","text": "Motor learning principles are irrelevant to neurological rehabilitation"},{"key": "C","text": "A single practice session is always sufficient for permanent skill acquisition"},{"key": "D","text": "Practice specificity, appropriate feedback, and sufficient repetition/intensity are important for skill acquisition and retention"}],"correct": "D","explanation": "Motor learning principles (specificity, feedback timing/type, repetition, practice variability) inform evidence-based neurorehabilitation practice design."},{"id": 6222,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Knowledge of results' feedback in motor learning refers to:","options": [{"key": "A","text": "Information about the movement pattern/quality itself"},{"key": "B","text": "Information about the outcome/success of a movement (e.g., whether a target was reached)"},{"key": "C","text": "A term unrelated to motor learning"},{"key": "D","text": "Only relevant for cognitive rehabilitation, not motor rehabilitation"}],"correct": "B","explanation": "Knowledge of results (KR) refers to outcome-based feedback (task success/failure), distinct from knowledge of performance (movement quality feedback)."},{"id": 6223,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Knowledge of performance' feedback in motor learning refers to:","options": [{"key": "A","text": "Feedback that should never be provided during rehabilitation"},{"key": "B","text": "Information about the movement pattern/quality used to achieve the outcome"},{"key": "C","text": "A term unrelated to motor rehabilitation"},{"key": "D","text": "Information exclusively about task outcome success/failure"}],"correct": "B","explanation": "Knowledge of performance (KP) provides information about the quality/characteristics of the movement itself, complementing outcome-focused knowledge of results feedback."},{"id": 6224,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Constraint-Induced Movement Therapy (CIMT) is grounded in the concept of addressing:","options": [{"key": "A","text": "Complete avoidance of any limb use to promote recovery"},{"key": "B","text": "Only central nervous system lesion location, without any behavioral component"},{"key": "C","text": "Learned non-use of the affected limb through forced, intensive practice"},{"key": "D","text": "Purely passive range of motion limitations"}],"correct": "C","explanation": "CIMT specifically targets the behavioral phenomenon of learned non-use, using constraint of the less-affected limb to force intensive practice of the more-affected limb."},{"id": 6225,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes the general principle behind mental practice/motor imagery as an adjunct rehabilitation technique?","options": [{"key": "A","text": "Mental practice should always replace physical practice entirely"},{"key": "B","text": "Motor imagery is only relevant for cognitive rehabilitation, unrelated to motor recovery"},{"key": "C","text": "Mentally rehearsing a movement can activate similar neural networks to physical practice, potentially supporting motor learning/recovery"},{"key": "D","text": "Motor imagery has no neurological basis or evidence of benefit"}],"correct": "C","explanation": "Motor imagery/mental practice is thought to activate overlapping neural networks with actual movement execution, supporting its use as a complementary technique in motor rehabilitation."},{"id": 6226,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Mirror therapy, used in various neurorehabilitation contexts, works through which proposed mechanism?","options": [{"key": "A","text": "Visual feedback creating an illusion of normal movement, potentially facilitating cortical reorganization/motor recovery"},{"key": "B","text": "Direct electrical stimulation of the affected limb"},{"key": "C","text": "Physical manipulation of the affected limb by the therapist"},{"key": "D","text": "A technique with no proposed neurological mechanism"}],"correct": "A","explanation": "Mirror therapy uses visual illusion (reflecting the unaffected limb's movement) to potentially influence cortical processing and support motor recovery in the affected limb."},{"id": 6227,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the principle of 'massed' versus 'distributed' practice in motor learning?","options": [{"key": "A","text": "Massed practice involves less rest between practice trials/sessions compared to distributed practice with more rest intervals"},{"key": "B","text": "Distributed practice refers to practicing only a single task repeatedly without variation"},{"key": "C","text": "These terms are synonymous with no distinction"},{"key": "D","text": "Massed practice always produces superior long-term retention compared to distributed practice"}],"correct": "A","explanation": "Massed practice involves minimal rest between trials/sessions, while distributed practice incorporates more rest; the relative effectiveness for learning/retention can vary depending on task and population factors."},{"id": 6228,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Random' versus 'blocked' practice schedules in motor learning refer to:","options": [{"key": "A","text": "Blocked practice always produces superior outcomes for all populations and tasks"},{"key": "B","text": "These terms describe identical practice structures"},{"key": "C","text": "Random practice varies task order unpredictably while blocked practice repeats the same task consecutively before switching"},{"key": "D","text": "Random practice always refers to practicing without any therapist supervision"}],"correct": "C","explanation": "Random practice interleaves different tasks unpredictably, while blocked practice involves repeated practice of one task before moving to the next; research suggests random practice, despite feeling harder, often promotes better retention/transfer in appropriate populations."},{"id": 6229,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding practice variability in motor rehabilitation programming?","options": [{"key": "A","text": "Practice should always be completely identical/unvarying to maximize learning"},{"key": "B","text": "Variability in practice always impairs motor learning with no potential benefit"},{"key": "C","text": "Variability considerations are irrelevant to neurorehabilitation program design"},{"key": "D","text": "Incorporating some variability in practice conditions can enhance adaptability and transfer of learned skills to real-world contexts"}],"correct": "D","explanation": "Appropriately incorporating variability in practice conditions (within a patient's capability) can enhance the flexibility and real-world transferability of learned motor skills."},{"id": 6230,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes the general evidence-based consensus regarding comparison between different major neurorehabilitation approaches (e.g., Bobath vs. motor relearning-based approaches)?","options": [{"key": "A","text": "One specific named approach has been definitively proven superior to all others in all contexts"},{"key": "B","text": "All approaches are entirely ineffective and lack any evidence support"},{"key": "C","text": "No single approach has been shown definitively superior overall; evidence increasingly emphasizes shared active, task-specific, and intensity principles across approaches"},{"key": "D","text": "Comparison research has never been conducted between rehabilitation approaches"}],"correct": "C","explanation": "Contemporary evidence suggests that shared underlying principles (active engagement, task-specificity, appropriate intensity/repetition) across various named approaches may be more important than approach-specific branding, without clear definitive superiority of one named approach over others."},{"id": 6231,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the concept of 'externally-paced' versus 'self-paced' task practice relevant to neurorehabilitation?","options": [{"key": "A","text": "Self-paced tasks always require more advanced equipment than externally-paced tasks"},{"key": "B","text": "Externally-paced tasks are controlled by an outside timing cue (e.g., treadmill speed) while self-paced tasks allow the patient to control timing/speed"},{"key": "C","text": "These terms describe identical practice conditions"},{"key": "D","text": "External pacing is always contraindicated in neurorehabilitation"}],"correct": "B","explanation": "This distinction (e.g., treadmill walking as externally-paced versus overground walking as more self-paced) is relevant to task practice selection and progression in gait rehabilitation."},{"id": 6232,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes the rationale for incorporating dual-task training in neurorehabilitation programs for conditions like stroke or Parkinson's disease?","options": [{"key": "A","text": "Dual-task training should always be avoided due to safety concerns regardless of individual capacity"},{"key": "B","text": "Many real-world functional activities require simultaneous cognitive-motor performance, and specific deficits in dual-tasking are common in these populations"},{"key": "C","text": "Single-task training alone is always sufficient to address all functional mobility needs"},{"key": "D","text": "Dual-task training has no relevance to real-world functional performance"}],"correct": "B","explanation": "Given the real-world relevance of simultaneous cognitive-motor task performance and documented dual-task deficits in various neurological populations, appropriately graded dual-task training is often incorporated into comprehensive rehabilitation."},{"id": 6233,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes an important principle underlying high-intensity, high-repetition practice approaches increasingly emphasized in neurorehabilitation (e.g., for gait training post-stroke)?","options": [{"key": "A","text": "Practice intensity/repetition has no relationship to rehabilitation outcomes"},{"key": "B","text": "Minimal practice repetition is always equally effective as high-repetition practice"},{"key": "C","text": "Sufficient practice dose/intensity is considered important for driving meaningful neuroplastic change and functional improvement"},{"key": "D","text": "High-intensity practice should never be attempted regardless of patient tolerance"}],"correct": "C","explanation": "Growing evidence supports the importance of adequate practice dose (intensity, repetition) in driving beneficial neuroplastic adaptation, informing the emphasis on high-repetition task practice in contemporary rehabilitation approaches."},{"id": 6234,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best describes an appropriate integration of different rehabilitation techniques/approaches in contemporary clinical practice?","options": [{"key": "A","text": "Flexible, evidence-informed selection and combination of techniques based on individual patient presentation and goals, rather than rigid adherence to a single named approach"},{"key": "B","text": "Strict, exclusive adherence to only one named historical approach regardless of patient-specific factors"},{"key": "C","text": "Assuming all patients require an identical fixed treatment protocol regardless of individual assessment findings"},{"key": "D","text": "Complete rejection of all traditionally-named approaches in favor of an entirely novel untested method"}],"correct": "A","explanation": "Contemporary evidence-based neurorehabilitation practice typically involves flexible, individualized selection and integration of various techniques/principles based on patient-specific assessment findings and goals, rather than rigid adherence to any single historical approach."},{"id": 6235,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "The systems theory of motor control proposes that movement emerges from the dynamic interaction of:","options": [{"key": "A","text": "Multiple systems including the individual, task, and environment"},{"key": "B","text": "Only cognitive factors"},{"key": "C","text": "Only peripheral muscle properties"},{"key": "D","text": "Only the central nervous system in isolation"}],"correct": "A","explanation": "Systems theory (dynamical systems approach) views movement as emerging from complex interaction between the individual's systems, the task demands, and environmental context, rather than solely top-down neural control."},{"id": 6236,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The hierarchical theory of motor control, an older model, proposed that movement is primarily controlled by:","options": [{"key": "A","text": "Only spinal cord circuits without cortical involvement"},{"key": "B","text": "Purely peripheral reflex arcs without any central involvement"},{"key": "C","text": "Equal, non-hierarchical interaction of all levels"},{"key": "D","text": "Higher cortical centers in a top-down manner over lower reflex centers"}],"correct": "D","explanation": "The traditional hierarchical model emphasized top-down cortical control over lower (brainstem, spinal) reflex centers, though contemporary systems models incorporate more complex, non-linear interactions."},{"id": 6237,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Virtual reality (VR) based rehabilitation is increasingly used in neurorehabilitation primarily to:","options": [{"key": "A","text": "Provide engaging, potentially motivating task-specific practice with performance feedback in a controlled environment"},{"key": "B","text": "Only be used for cognitive rehabilitation, never motor rehabilitation"},{"key": "C","text": "Provide a technique with no evidence of any benefit"},{"key": "D","text": "Replace all conventional therapy approaches entirely in every case"}],"correct": "A","explanation": "VR-based approaches can provide engaging, motivating, task-specific practice opportunities with real-time feedback, complementing conventional therapy approaches across various neurological populations."},{"id": 6238,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Robotic-assisted gait training devices are used in neurorehabilitation to:","options": [{"key": "A","text": "Provide a technique with no evidence of any clinical benefit"},{"key": "B","text": "Only be appropriate for patients with mild impairment requiring minimal assistance"},{"key": "C","text": "Replace the need for any human therapist involvement entirely"},{"key": "D","text": "Provide consistent, repetitive, task-specific gait practice, particularly useful for patients requiring significant assistance"}],"correct": "D","explanation": "Robotic gait training devices can provide consistent, high-repetition, task-specific practice, particularly valuable for patients with more significant impairment requiring substantial assistance for overground practice."},{"id": 6239,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Body-weight-supported treadmill training (BWSTT) allows practice of gait-related movement patterns by:","options": [{"key": "A","text": "Replacing the need for any progression toward overground walking"},{"key": "B","text": "Partially unweighting the patient via a harness system while walking on a treadmill"},{"key": "C","text": "Complete elimination of any weight-bearing through the lower limbs"},{"key": "D","text": "Only being appropriate for patients able to walk independently overground already"}],"correct": "B","explanation": "BWSTT uses a harness system to partially offload body weight, enabling earlier, more repetitive practice of gait patterns in patients who could not yet manage full overground walking independently."},{"id": 6240,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes the concept of 'forced use' as related to but distinct from constraint-induced movement therapy?","options": [{"key": "A","text": "Forced use refers to restraining the affected limb rather than the unaffected limb"},{"key": "B","text": "These terms are entirely synonymous with no distinction"},{"key": "C","text": "Forced use describes simply constraining the unaffected limb, while CIMT combines constraint with structured intensive practice of the affected limb"},{"key": "D","text": "Neither term has any relevance to neurorehabilitation practice"}],"correct": "C","explanation": "While related, 'forced use' (simple constraint) is considered a component of the more comprehensive CIMT protocol, which additionally incorporates structured, intensive, shaped practice of the affected limb."},{"id": 6241,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "'Shaping' as a specific behavioral technique used within CIMT protocols refers to:","options": [{"key": "A","text": "A technique unrelated to motor rehabilitation"},{"key": "B","text": "Physically molding the patient's limb into a desired position"},{"key": "C","text": "Complete avoidance of any feedback during practice"},{"key": "D","text": "Progressively increasing task difficulty in small increments with positive feedback, building toward a functional goal"}],"correct": "D","explanation": "Shaping involves systematically increasing task demands in small, achievable increments with performance feedback, a specific behavioral training technique incorporated within CIMT protocols."},{"id": 6242,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding environmental enrichment principles as they may apply to neurorehabilitation settings?","options": [{"key": "A","text": "A stark, minimally stimulating environment is always preferable for optimal recovery"},{"key": "B","text": "Providing varied, engaging, and stimulating environments/activities may support neuroplasticity and motor learning, based partly on animal model research"},{"key": "C","text": "Environmental enrichment concepts apply only to animal research with no translational relevance to human rehabilitation"},{"key": "D","text": "Environmental factors have no relevance to neuroplasticity or rehabilitation outcomes"}],"correct": "B","explanation": "Research (including foundational animal studies) suggests that enriched, engaging environments may support neuroplasticity, informing efforts to create stimulating, motivating rehabilitation environments for patients."},{"id": 6243,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an important consideration regarding transfer of learning/generalization in neurorehabilitation practice design?","options": [{"key": "A","text": "Practicing tasks in varied, contextually relevant conditions can help promote transfer of learned skills to real-world function beyond the specific training context"},{"key": "B","text": "Practicing only in a single, highly controlled context always maximizes real-world functional transfer"},{"key": "C","text": "Transfer of learning is not a relevant consideration in rehabilitation program design"},{"key": "D","text": "Skills learned in a clinical setting always automatically transfer perfectly to all real-world contexts without any specific consideration needed"}],"correct": "A","explanation": "Thoughtful consideration of practice context variability and relevance to real-world demands supports better transfer/generalization of learned motor skills beyond the specific clinical training environment."},{"id": 6244,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes the concept of 'guided discovery' or problem-solving approaches within contemporary motor relearning-based rehabilitation?","options": [{"key": "A","text": "Encouraging the patient to actively problem-solve and discover effective movement strategies, with therapist guidance rather than purely passive instruction"},{"key": "B","text": "Complete avoidance of any therapist guidance, leaving the patient entirely without direction"},{"key": "C","text": "A technique only relevant for cognitive rehabilitation, unrelated to motor learning"},{"key": "D","text": "The therapist physically performing the movement for the patient without any patient active involvement"}],"correct": "A","explanation": "Guided discovery/problem-solving approaches (consistent with motor relearning program principles) encourage active patient engagement in finding effective movement solutions, with appropriate therapist guidance rather than purely passive correction."},{"id": 6245,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the concept of 'compensation' versus 'restitution' as differing rehabilitation goals/strategies?","options": [{"key": "A","text": "Restitution aims to restore the original movement pattern/function while compensation involves using alternative strategies to achieve a functional goal"},{"key": "B","text": "Restitution approaches are always preferred over compensation regardless of individual prognosis/context"},{"key": "C","text": "Compensation strategies should never be used under any circumstances in neurorehabilitation"},{"key": "D","text": "These terms are synonymous with no meaningful distinction"}],"correct": "A","explanation": "Understanding the distinction between restitution (restoring original function) and compensation (alternative strategies) approaches, and appropriately balancing both based on individual prognosis/goals, is an important consideration in rehabilitation planning."},{"id": 6246,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an appropriate consideration regarding when compensatory strategies might be more heavily emphasized over restitution-focused approaches in rehabilitation planning?","options": [{"key": "A","text": "Restitution approaches should always be pursued exclusively regardless of chronicity or severity"},{"key": "B","text": "When the potential for further restitution-based recovery appears limited (e.g., chronic phase, severe impairment) and functional independence is a priority"},{"key": "C","text": "This distinction has no relevance to clinical decision-making in rehabilitation"},{"key": "D","text": "Compensatory strategies should always be emphasized from the very first rehabilitation session regardless of prognosis"}],"correct": "B","explanation": "Clinical judgment regarding an individual's likely restitution potential (considering factors like chronicity, severity, and specific impairment pattern) helps inform the relative emphasis on compensatory versus restitution-focused strategies at different points in rehabilitation."},{"id": 6247,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the role of goal-setting (e.g., SMART goals) within a motor relearning/task-oriented rehabilitation framework?","options": [{"key": "A","text": "Generic, non-specific goals are equally effective as SMART goals for guiding rehabilitation"},{"key": "B","text": "Goals should always be set exclusively by the therapist without any patient input"},{"key": "C","text": "Goal-setting is irrelevant to rehabilitation program design and evaluation"},{"key": "D","text": "Establishing specific, measurable, achievable, relevant, and time-bound goals helps guide and evaluate meaningful, functionally-relevant intervention"}],"correct": "D","explanation": "SMART goal-setting frameworks help ensure rehabilitation intervention is appropriately targeted, measurable, and meaningful to the individual patient, supporting effective task-oriented practice planning."},{"id": 6248,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the timing/scheduling of feedback (e.g., immediate versus delayed) in motor skill practice?","options": [{"key": "A","text": "Some research suggests that reduced feedback frequency or delayed feedback may promote better long-term retention compared to continuous immediate feedback, despite potentially slower initial acquisition"},{"key": "B","text": "Feedback should never be provided at any point during motor skill practice"},{"key": "C","text": "Immediate, continuous feedback for every single practice trial always produces superior long-term retention with no exceptions"},{"key": "D","text": "Feedback timing has no relevance to motor learning outcomes"}],"correct": "A","explanation": "Motor learning research suggests that feedback scheduling can influence the balance between performance during acquisition versus long-term retention, with some evidence favoring reduced/summary feedback for better retention despite feeling less immediately helpful."},{"id": 6249,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes the concept of 'implicit' versus 'explicit' motor learning relevant to neurorehabilitation, particularly in populations with cognitive impairment?","options": [{"key": "A","text": "Explicit learning is always superior regardless of the patient's cognitive status"},{"key": "B","text": "Implicit learning occurs without conscious awareness of the learning process, potentially offering advantages for patients with limited explicit/declarative memory capacity"},{"key": "C","text": "These terms are synonymous with no meaningful distinction"},{"key": "D","text": "Implicit learning is irrelevant to neurorehabilitation practice"}],"correct": "B","explanation": "Understanding implicit (procedural, less consciously mediated) versus explicit (consciously mediated, instruction-based) learning processes can inform rehabilitation approach selection, particularly relevant for patients with cognitive impairment limiting explicit learning capacity."},{"id": 6250,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration regarding group-based versus individual therapy sessions in neurorehabilitation program design?","options": [{"key": "A","text": "Group therapy has no potential benefit and should never be used in neurorehabilitation"},{"key": "B","text": "Group sessions can offer social support, peer motivation, and efficient resource use, complementing individualized therapy addressing specific patient needs"},{"key": "C","text": "Individual therapy is always completely unnecessary if group sessions are available"},{"key": "D","text": "These approaches are mutually exclusive and can never be appropriately combined"}],"correct": "B","explanation": "Thoughtfully combining group-based sessions (offering social/motivational benefits and efficient resource use) with individualized therapy addressing specific needs can provide a comprehensive, well-rounded rehabilitation program."},{"id": 6251,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding technology-assisted home exercise programs (e.g., mobile apps, wearable sensors) in extending rehabilitation beyond clinical sessions?","options": [{"key": "A","text": "Technology-assisted approaches have no potential role in extending rehabilitation practice"},{"key": "B","text": "Such technologies may support increased practice frequency/monitoring and patient engagement between formal therapy sessions"},{"key": "C","text": "Home-based technology should always completely replace in-person clinical therapy sessions"},{"key": "D","text": "These technologies are only relevant for research purposes with no practical clinical application"}],"correct": "B","explanation": "Appropriately selected technology-assisted approaches can help extend practice opportunities and engagement between formal clinical sessions, potentially supporting overall practice dose and outcomes when thoughtfully integrated into comprehensive care."},{"id": 6252,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important principle underlying the concept of 'use-dependent' cortical reorganization relevant to neurorehabilitation practice?","options": [{"key": "A","text": "This concept only applies to research in non-human animal models with no human relevance"},{"key": "B","text": "Use-dependent plasticity concepts are irrelevant to rehabilitation program design"},{"key": "C","text": "Cortical representation/organization can be shaped by patterns of use, supporting rationale for intensive, repetitive, meaningful practice approaches"},{"key": "D","text": "Cortical organization is entirely fixed and unaffected by any pattern of limb use or practice"}],"correct": "C","explanation": "Use-dependent plasticity, demonstrating that cortical organization can be shaped by patterns of activity/use, provides important theoretical support for intensive, repetitive, meaningful practice-based rehabilitation approaches."},{"id": 6253,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to selecting rehabilitation techniques for a patient with significant cognitive impairment limiting their ability to engage in complex problem-solving-based approaches?","options": [{"key": "A","text": "Complete avoidance of any structured practice approach for cognitively impaired patients"},{"key": "B","text": "Adapting the approach to emphasize simpler, more structured, potentially more implicit/procedural learning strategies suited to the individual's cognitive capacity"},{"key": "C","text": "Using identical complex problem-solving approaches regardless of the patient's cognitive capacity"},{"key": "D","text": "Assuming rehabilitation is not possible or worthwhile for any patient with cognitive impairment"}],"correct": "B","explanation": "Thoughtful adaptation of rehabilitation approach (favoring simpler, structured, more procedural/implicit learning strategies where appropriate) helps optimize engagement and outcomes for patients with cognitive impairment limiting capacity for complex explicit problem-solving approaches."},{"id": 6254,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following best summarizes the overarching theme across contemporary evidence-based neurorehabilitation approaches, regardless of specific named technique?","options": [{"key": "A","text": "Passive treatment approaches without active patient participation are considered equally effective as active approaches"},{"key": "B","text": "Active patient engagement in meaningful, sufficiently intensive, task-specific practice, individualized to patient goals and capacity, tends to be emphasized across effective approaches"},{"key": "C","text": "A single universally superior named technique has been definitively established for all patients and conditions"},{"key": "D","text": "Rehabilitation approach selection has no meaningful impact on patient outcomes"}],"correct": "B","explanation": "Across the evolution of various named approaches, contemporary evidence increasingly emphasizes shared core principles—active engagement, task-specificity, and sufficient practice intensity/dose, individualized to the patient—as key drivers of effective neurorehabilitation, more so than allegiance to any single named historical approach."},{"id": 6255,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Spina bifida occulta refers to:","options": [{"key": "A","text": "Always causing severe paralysis"},{"key": "B","text": "A mild form with incomplete vertebral arch closure without externally visible neural tissue herniation"},{"key": "C","text": "Herniation of meninges and neural tissue through a visible defect"},{"key": "D","text": "Complete absence of spinal cord development"}],"correct": "B","explanation": "Spina bifida occulta is the mildest form, often asymptomatic, with incomplete vertebral fusion but no externally visible neural tissue protrusion."},{"id": 6256,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Myelomeningocele, the most severe form of spina bifida, is characterized by:","options": [{"key": "A","text": "Herniation of both meninges and neural tissue through the vertebral defect"},{"key": "B","text": "Only bony vertebral defect without neural involvement"},{"key": "C","text": "Isolated skin abnormality without any spinal involvement"},{"key": "D","text": "A condition that never causes any functional impairment"}],"correct": "A","explanation": "Myelomeningocele involves protrusion of neural tissue and meninges through an open vertebral defect, typically causing significant neurological deficit below the lesion level."},{"id": 6257,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Hydrocephalus is commonly associated with myelomeningocele due to:","options": [{"key": "A","text": "Only occurring in isolated cases unrelated to the spinal defect"},{"key": "B","text": "Always resolving spontaneously without any intervention"},{"key": "C","text": "No relationship exists between these conditions"},{"key": "D","text": "Associated Chiari II malformation affecting CSF flow dynamics"}],"correct": "D","explanation": "Chiari II malformation (commonly associated with myelomeningocele) affects normal CSF circulation, contributing to hydrocephalus development requiring monitoring/shunt management in many cases."},{"id": 6258,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Duchenne muscular dystrophy, though primarily a muscle disorder, is relevant to pediatric neurology given its:","options": [{"key": "A","text": "Complete absence of any relevance to pediatric rehabilitation"},{"key": "B","text": "Onset exclusively in adulthood"},{"key": "C","text": "X-linked inheritance and progressive weakness pattern requiring similar rehabilitation principles to other pediatric neuromuscular conditions"},{"key": "D","text": "Classification as a pure central nervous system disorder"}],"correct": "C","explanation": "While primarily a muscle disorder, DMD's pediatric onset and progressive nature place it within the broader scope of pediatric neuromuscular rehabilitation consideration."},{"id": 6259,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Spinal Muscular Atrophy (SMA) results from degeneration of:","options": [{"key": "A","text": "Cerebellar Purkinje cells exclusively"},{"key": "B","text": "Peripheral sensory nerves exclusively"},{"key": "C","text": "Upper motor neurons exclusively"},{"key": "D","text": "Anterior horn cells (lower motor neurons) in the spinal cord"}],"correct": "D","explanation": "SMA is a genetic condition causing progressive degeneration of anterior horn cells, producing lower motor neuron pattern weakness."},{"id": 6260,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "SMA Type 1 (Werdnig-Hoffmann disease), the most severe form, typically presents with onset:","options": [{"key": "A","text": "Before 6 months of age with severe, rapidly progressive weakness"},{"key": "B","text": "After age 10 with mild symptoms"},{"key": "C","text": "Only in adulthood"},{"key": "D","text": "Exclusively affecting upper limb function"}],"correct": "A","explanation": "SMA Type 1 presents in early infancy (before 6 months) with severe hypotonia and weakness, historically associated with poor prognosis without treatment, though newer therapies have changed outcomes."},{"id": 6261,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Newer disease-modifying therapies for SMA (e.g., nusinersen, gene therapy) work by:","options": [{"key": "A","text": "Addressing the underlying genetic/molecular deficiency to increase functional SMN protein levels"},{"key": "B","text": "Having no effect on the underlying disease process"},{"key": "C","text": "Curing the condition through surgical intervention exclusively"},{"key": "D","text": "Only providing symptomatic pain relief"}],"correct": "A","explanation": "Modern SMA therapies target the underlying molecular deficiency (increasing SMN protein), representing significant advancement changing disease trajectory and prognosis for many patients."},{"id": 6262,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Erb's palsy (upper brachial plexus birth injury) typically results from which mechanism during delivery?","options": [{"key": "A","text": "Prenatal viral infection"},{"key": "B","text": "Post-natal accidental injury unrelated to birth process"},{"key": "C","text": "Direct genetic mutation unrelated to birth trauma"},{"key": "D","text": "Excessive lateral traction on the neck/shoulder during difficult delivery (e.g., shoulder dystocia)"}],"correct": "D","explanation": "Erb's palsy classically results from traction injury to the upper brachial plexus (C5-C6) during difficult delivery, often associated with shoulder dystocia."},{"id": 6263,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Congenital torticollis (sternocleidomastoid fibrosis) in infants is typically managed initially with:","options": [{"key": "A","text": "Observation without any intervention in all cases"},{"key": "B","text": "Immediate surgical intervention as first-line treatment"},{"key": "C","text": "Complete immobilization of the neck"},{"key": "D","text": "Stretching exercises and positioning techniques"}],"correct": "D","explanation": "Conservative management with stretching and repositioning is generally first-line for congenital muscular torticollis, with surgery reserved for resistant cases."},{"id": 6264,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Pediatric epilepsy syndromes such as childhood absence epilepsy typically present with:","options": [{"key": "A","text": "Brief lapses in awareness without dramatic motor convulsion"},{"key": "B","text": "Isolated motor weakness without any seizure activity"},{"key": "C","text": "Onset exclusively in adolescence"},{"key": "D","text": "Only prolonged tonic-clonic seizures"}],"correct": "A","explanation": "Childhood absence epilepsy presents with brief, frequent staring/lapses in awareness, distinct from more dramatic tonic-clonic seizure presentations."},{"id": 6265,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "West syndrome (infantile spasms) is characterized by which triad?","options": [{"key": "A","text": "Normal EEG with isolated motor delay"},{"key": "B","text": "Onset exclusively in adolescence"},{"key": "C","text": "Absence of any developmental concern"},{"key": "D","text": "Infantile spasms, hypsarrhythmia on EEG, and developmental regression/impairment"}],"correct": "D","explanation": "West syndrome presents with the classic triad of infantile spasms, characteristic hypsarrhythmic EEG pattern, and developmental regression, requiring prompt recognition and treatment."},{"id": 6266,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration for infants/children with epilepsy engaging in physical activity/rehabilitation?","options": [{"key": "A","text": "No special considerations are needed regarding epilepsy during physiotherapy sessions"},{"key": "B","text": "Assuming all epilepsy diagnoses require identical activity restrictions"},{"key": "C","text": "Complete exclusion from all physical activity regardless of seizure control status"},{"key": "D","text": "Awareness of seizure triggers/precautions and appropriate safety planning during physical activity, without unnecessarily restricting participation"}],"correct": "D","explanation": "Individualized safety planning (considering seizure control status, specific triggers if known) allows appropriate physical activity participation while maintaining necessary precautions, avoiding unnecessary activity restriction."},{"id": 6267,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Global developmental delay in a young child refers to:","options": [{"key": "A","text": "Significant delay across multiple developmental domains (motor, cognitive, language, social)"},{"key": "B","text": "A condition that always indicates cerebral palsy specifically"},{"key": "C","text": "Delay isolated to a single developmental domain only"},{"key": "D","text": "A term used exclusively for motor delay"}],"correct": "A","explanation": "Global developmental delay describes significant delay across multiple domains, distinguishing it from isolated delays in a single area, and warranting comprehensive multidisciplinary assessment to identify underlying etiology where possible."},{"id": 6268,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Autism Spectrum Disorder, while primarily a neurodevelopmental/behavioral condition, is relevant to physiotherapy practice due to:","options": [{"key": "A","text": "Common co-occurring motor coordination difficulties and the need for adapted communication/sensory approaches during intervention"},{"key": "B","text": "Exclusively affecting cognitive function with no relevance to physical therapy"},{"key": "C","text": "Complete irrelevance to any physical/motor intervention needs"},{"key": "D","text": "Always requiring identical intervention approaches to typically developing children"}],"correct": "A","explanation": "Many children with ASD show co-occurring motor coordination difficulties, and effective physiotherapy engagement often requires thoughtfully adapted communication and sensory-considerate approaches."},{"id": 6269,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Developmental Coordination Disorder (DCD) is characterized by:","options": [{"key": "A","text": "A condition always associated with significant cognitive impairment"},{"key": "B","text": "Motor coordination difficulty significantly below expected level for age, impacting daily function, without another explanatory neurological condition"},{"key": "C","text": "Diagnostic criteria identical to cerebral palsy"},{"key": "D","text": "Onset exclusively in adulthood"}],"correct": "B","explanation": "DCD describes significant motor coordination impairment affecting functional performance, occurring in the absence of another diagnosed neurological condition (like CP) that would otherwise explain the motor difficulty."},{"id": 6270,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration in physiotherapy assessment/intervention for children with Developmental Coordination Disorder?","options": [{"key": "A","text": "Complete avoidance of any motor skill practice for children with DCD"},{"key": "B","text": "DCD requires no specific physiotherapy intervention since it always resolves spontaneously"},{"key": "C","text": "Assuming identical intervention needs to children with cerebral palsy"},{"key": "D","text": "Addressing specific functional motor skill deficits impacting daily activities/participation (e.g., handwriting, sports participation, self-care tasks)"}],"correct": "D","explanation": "DCD intervention typically focuses on addressing specific functional motor skill difficulties impacting the child's participation in meaningful daily activities, often using task-specific practice approaches."},{"id": 6271,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Traumatic brain injury in the pediatric population differs from adult TBI in several respects, including:","options": [{"key": "A","text": "The developing brain's unique vulnerability and potential for different long-term developmental impact patterns"},{"key": "B","text": "Complete absence of any long-term impact given greater 'plasticity' assumption in children"},{"key": "C","text": "Identical presentation and management considerations as adult TBI with no distinguishing features"},{"key": "D","text": "Never requiring any specialized pediatric-specific rehabilitation approach"}],"correct": "A","explanation": "Pediatric TBI involves unique considerations related to the developing brain's vulnerability and the potential for injury to affect ongoing developmental trajectories differently than in the mature adult brain, requiring specialized pediatric rehabilitation approaches."},{"id": 6272,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding family-centered care principles in pediatric neurological rehabilitation?","options": [{"key": "A","text": "Excluding family involvement to maintain purely clinical objectivity"},{"key": "B","text": "Assuming family involvement has no relevance to pediatric rehabilitation outcomes"},{"key": "C","text": "Actively involving family members in goal-setting, intervention planning, and understanding the condition, recognizing their central role in the child's ongoing care and development"},{"key": "D","text": "Family-centered care principles only apply to adult rehabilitation, not pediatric practice"}],"correct": "C","explanation": "Family-centered care, recognizing the family's central and ongoing role in the child's life and development, is a foundational principle in effective pediatric neurological rehabilitation practice."},{"id": 6273,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding play-based intervention approaches commonly used in pediatric neurological physiotherapy?","options": [{"key": "A","text": "Play should never be incorporated into any goal-directed therapeutic activity"},{"key": "B","text": "Play-based intervention is only appropriate for the very youngest infants, never older children"},{"key": "C","text": "Incorporating meaningful, enjoyable play activities can enhance engagement and motivation while addressing therapeutic goals appropriate to the child's developmental level"},{"key": "D","text": "Play-based approaches have no therapeutic value and should be avoided in favor of purely structured exercise"}],"correct": "C","explanation": "Play-based intervention approaches leverage children's natural engagement with play to enhance motivation and participation while working toward specific therapeutic/developmental goals in a developmentally appropriate manner."},{"id": 6274,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding transition planning for children with chronic neurological conditions as they approach adolescence/young adulthood?","options": [{"key": "A","text": "Transition planning is solely the responsibility of medical specialists with no physiotherapy involvement"},{"key": "B","text": "Proactive planning addressing evolving medical, functional, educational, and psychosocial needs as the young person transitions toward adult services/independence"},{"key": "C","text": "Assuming identical needs and services remain appropriate throughout the lifespan without any need for transition consideration"},{"key": "D","text": "No transition planning is necessary since pediatric conditions always resolve by adulthood"}],"correct": "B","explanation": "Thoughtful transition planning, addressing the evolving needs of young people with chronic pediatric neurological conditions as they move toward adulthood, is an important component of comprehensive long-term care planning."},{"id": 6275,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Epilepsy is best defined as:","options": [{"key": "A","text": "A condition always associated with structural brain damage"},{"key": "B","text": "A purely psychological condition without any neurological basis"},{"key": "C","text": "A single isolated seizure event only"},{"key": "D","text": "A tendency toward recurrent, unprovoked seizures resulting from abnormal excessive neuronal activity"}],"correct": "D","explanation": "Epilepsy describes a condition characterized by an enduring predisposition to recurrent, unprovoked seizures, resulting from abnormal, excessive/synchronous neuronal electrical activity."},{"id": 6276,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Generalized tonic-clonic seizures classically involve which sequence of events?","options": [{"key": "A","text": "Progressive weakness without any abnormal movement"},{"key": "B","text": "Isolated brief staring without any motor component"},{"key": "C","text": "Only jerking movements without any stiffening phase"},{"key": "D","text": "Initial tonic (stiffening) phase followed by clonic (rhythmic jerking) phase, often with loss of consciousness"}],"correct": "D","explanation": "Generalized tonic-clonic seizures classically show an initial tonic stiffening phase followed by rhythmic clonic jerking, with associated loss of consciousness."},{"id": 6277,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Focal (partial) seizures originate from:","options": [{"key": "A","text": "The spinal cord exclusively"},{"key": "B","text": "The peripheral nervous system exclusively"},{"key": "C","text": "A localized region of one cerebral hemisphere"},{"key": "D","text": "Simultaneous onset across both hemispheres always"}],"correct": "C","explanation": "Focal seizures arise from a localized cortical region, potentially remaining focal or secondarily generalizing to involve both hemispheres."},{"id": 6278,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Absence seizures (petit mal) typically present with:","options": [{"key": "A","text": "Brief lapses in awareness/staring episodes without dramatic motor convulsion"},{"key": "B","text": "Prolonged tonic-clonic convulsion"},{"key": "C","text": "Progressive limb weakness"},{"key": "D","text": "Only occurring during sleep"}],"correct": "A","explanation": "Absence seizures present with brief (typically seconds), abrupt lapses in awareness/staring, often with rapid full recovery, classically associated with a characteristic 3Hz spike-wave EEG pattern."},{"id": 6279,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Status epilepticus refers to:","options": [{"key": "A","text": "A prolonged seizure or repeated seizures without full recovery between episodes, considered a medical emergency"},{"key": "B","text": "A term used only for absence seizures"},{"key": "C","text": "A single brief seizure lasting less than 30 seconds"},{"key": "D","text": "A condition unrelated to seizure duration"}],"correct": "A","explanation": "Status epilepticus (prolonged/repeated seizure activity without recovery) is a neurological emergency requiring urgent medical management given significant morbidity/mortality risk."},{"id": 6280,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following is an important physiotherapy safety consideration for a patient with a known seizure disorder undergoing physical rehabilitation?","options": [{"key": "A","text": "Assuming identical seizure risk/precautions for all patients regardless of individual history"},{"key": "B","text": "No specific precautions are needed regardless of seizure history"},{"key": "C","text": "Awareness of seizure history/triggers and appropriate environmental safety planning during treatment sessions"},{"key": "D","text": "Complete exclusion from all physiotherapy participation regardless of seizure control"}],"correct": "C","explanation": "Individualized awareness of seizure history, known triggers, and appropriate environmental/safety planning allows safe physiotherapy participation for patients with epilepsy."},{"id": 6281,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "If a patient experiences a generalized tonic-clonic seizure during a physiotherapy session, an appropriate immediate response includes:","options": [{"key": "A","text": "Leaving the patient unattended during the seizure"},{"key": "B","text": "Protecting the patient from injury (clearing the area, cushioning the head), timing the seizure, and not restraining movements"},{"key": "C","text": "Forcefully restraining all limb movement"},{"key": "D","text": "Immediately placing an object in the patient's mouth"}],"correct": "B","explanation": "Appropriate seizure first aid involves protecting from injury without restraint, timing the event, and positioning safely (e.g., recovery position after convulsive movement ends), while never placing objects in the mouth."},{"id": 6282,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Post-ictal state following a seizure is characterized by:","options": [{"key": "A","text": "Immediate return to completely normal alertness"},{"key": "B","text": "A state that always lasts several days"},{"key": "C","text": "Only relevant for absence seizures, never tonic-clonic seizures"},{"key": "D","text": "A period of confusion, drowsiness, or altered consciousness following the seizure's motor activity resolution"}],"correct": "D","explanation": "The post-ictal period involves variable confusion/drowsiness following seizure resolution, requiring appropriate monitoring and reorientation support."},{"id": 6283,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Anti-epileptic medications work through various mechanisms primarily aimed at:","options": [{"key": "A","text": "Curing the underlying structural brain abnormality directly"},{"key": "B","text": "Reducing abnormal neuronal excitability/synchronization to prevent seizure occurrence"},{"key": "C","text": "Only providing symptomatic relief during an active seizure"},{"key": "D","text": "Having no effect on neuronal excitability"}],"correct": "B","explanation": "Anti-epileptic drugs work through various mechanisms (e.g., sodium channel blockade, GABA enhancement) to reduce abnormal neuronal excitability and prevent seizure occurrence."},{"id": 6284,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding exercise participation for individuals with well-controlled epilepsy?","options": [{"key": "A","text": "Complete avoidance of all exercise is universally recommended regardless of seizure control"},{"key": "B","text": "Exercise always significantly increases seizure frequency in all patients"},{"key": "C","text": "Regular exercise is generally encouraged and safe, with individualized consideration of any specific activity-related risks/precautions"},{"key": "D","text": "No consideration of seizure history is ever needed when prescribing exercise"}],"correct": "C","explanation": "For individuals with well-controlled epilepsy, regular exercise participation is generally encouraged as part of a healthy lifestyle, with individualized safety planning for specific higher-risk activities as needed."},{"id": 6285,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following is an important consideration regarding sleep deprivation and epilepsy management, relevant to rehabilitation scheduling?","options": [{"key": "A","text": "Sleep deprivation is a recognized seizure trigger for many individuals, making adequate rest an important consideration in overall care planning"},{"key": "B","text": "Sleep deprivation always prevents any seizure occurrence"},{"key": "C","text": "This consideration is irrelevant to rehabilitation practice"},{"key": "D","text": "Sleep has no relationship to seizure threshold or frequency"}],"correct": "A","explanation": "Sleep deprivation is a well-recognized seizure trigger for many individuals with epilepsy, relevant to overall lifestyle/care planning considerations including appropriate rehabilitation scheduling."},{"id": 6286,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding photosensitive epilepsy relevant to certain rehabilitation technologies (e.g., some virtual reality or flashing light-based interventions)?","options": [{"key": "A","text": "Photosensitivity has no relevance to any rehabilitation technology selection"},{"key": "B","text": "All patients with epilepsy have photosensitive triggers requiring universal avoidance of all visual technology"},{"key": "C","text": "Screening for photosensitivity history is important before using interventions involving flashing/flickering visual stimuli"},{"key": "D","text": "Photosensitive epilepsy only affects seizure presentation, never triggering actual seizure occurrence"}],"correct": "C","explanation": "For the subset of patients with photosensitive epilepsy, appropriate screening and caution regarding flashing/flickering visual stimuli (potentially present in some technology-based interventions) is an important safety consideration."},{"id": 6287,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important psychosocial consideration in comprehensive epilepsy management relevant to rehabilitation practice?","options": [{"key": "A","text": "Rehabilitation providers should avoid any discussion of psychosocial epilepsy-related concerns"},{"key": "B","text": "Addressing potential stigma, anxiety, and quality of life impact alongside seizure management, recognizing the broader psychosocial burden of the condition"},{"key": "C","text": "Psychosocial factors are irrelevant to epilepsy management, only seizure control matters"},{"key": "D","text": "Epilepsy has no associated psychosocial impact for most patients"}],"correct": "B","explanation": "Comprehensive epilepsy care recognizes the significant psychosocial burden (stigma, anxiety, quality of life impact) that can accompany the condition, relevant to holistic rehabilitation practice alongside physical/seizure-focused management."},{"id": 6288,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The autonomic nervous system is divided into which two main divisions with generally antagonistic effects?","options": [{"key": "A","text": "Somatic and central"},{"key": "B","text": "Cranial and spinal only"},{"key": "C","text": "Afferent and efferent only"},{"key": "D","text": "Sympathetic and parasympathetic"}],"correct": "D","explanation": "The ANS comprises sympathetic (fight-or-flight) and parasympathetic (rest-and-digest) divisions, generally producing antagonistic physiological effects on target organs."},{"id": 6289,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Orthostatic hypotension, a common autonomic dysfunction, is defined by a significant drop in blood pressure upon:","options": [{"key": "A","text": "Sleep onset"},{"key": "B","text": "Remaining seated without any position change"},{"key": "C","text": "Standing/postural change from lying or sitting to upright position"},{"key": "D","text": "Lying down from standing"}],"correct": "C","explanation": "Orthostatic hypotension is defined by a significant BP drop (typically systolic ≥20mmHg or diastolic ≥10mmHg) within a few minutes of standing/upright postural change."},{"id": 6290,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Autonomic dysreflexia, occurring in spinal cord injury at or above T6, results from:","options": [{"key": "A","text": "Complete absence of any autonomic response below the injury"},{"key": "B","text": "Unopposed sympathetic response below the injury level to a noxious stimulus, without normal descending inhibitory control"},{"key": "C","text": "Only affecting parasympathetic function"},{"key": "D","text": "A condition unrelated to spinal cord injury level"}],"correct": "B","explanation": "Loss of descending inhibitory control from higher centers (due to the SCI level) allows an exaggerated, unopposed sympathetic response below the lesion in reaction to noxious stimuli."},{"id": 6291,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following conditions can cause autonomic dysfunction as part of its clinical presentation?","options": [{"key": "A","text": "Guillain-Barre Syndrome, Parkinson's disease, and Multiple System Atrophy"},{"key": "B","text": "Only conditions affecting children, never adults"},{"key": "C","text": "Conditions affecting only the somatic nervous system with no autonomic involvement"},{"key": "D","text": "Only isolated peripheral musculoskeletal injuries"}],"correct": "A","explanation": "Multiple neurological conditions (GBS, PD, MSA, and others) can involve significant autonomic dysfunction as part of their broader clinical presentation, relevant to comprehensive rehabilitation assessment."},{"id": 6292,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration when mobilizing a patient with significant autonomic dysfunction causing orthostatic hypotension?","options": [{"key": "A","text": "No monitoring of vital signs is needed during mobilization"},{"key": "B","text": "Immediate full upright mobilization regardless of blood pressure response"},{"key": "C","text": "Gradual postural changes, monitoring vital signs, and appropriate compensatory strategies (e.g., compression garments) during mobilization"},{"key": "D","text": "Assuming orthostatic hypotension resolves without any specific management strategy"}],"correct": "C","explanation": "Careful, gradual postural progression with vital sign monitoring and appropriate compensatory strategies helps safely manage orthostatic hypotension during rehabilitation mobilization."},{"id": 6293,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Thermoregulatory dysfunction (impaired ability to regulate body temperature) can occur with significant autonomic nervous system involvement, particularly relevant in:","options": [{"key": "A","text": "Higher-level spinal cord injuries affecting sympathetic vasomotor/sweating control below the lesion"},{"key": "B","text": "A condition that never has any relevance to rehabilitation practice"},{"key": "C","text": "Only affecting patients with peripheral nerve injuries, never central conditions"},{"key": "D","text": "Only relevant during the acute hospital phase, never long-term management"}],"correct": "A","explanation": "Higher-level SCI significantly disrupts autonomic thermoregulatory control below the lesion, an important long-term consideration in comprehensive rehabilitation and lifestyle management."},{"id": 6294,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Bladder and bowel dysfunction, commonly seen in various neurological conditions, often reflects disruption of:","options": [{"key": "A","text": "Only affecting patients with primary urological/gastrointestinal disease, unrelated to neurological conditions"},{"key": "B","text": "Purely musculoskeletal factors unrelated to any neural control"},{"key": "C","text": "A condition never related to underlying neurological pathology"},{"key": "D","text": "Autonomic (and sometimes somatic) neural control pathways governing these functions"}],"correct": "D","explanation": "Bladder/bowel dysfunction in neurological populations frequently reflects underlying disruption of the complex autonomic (and somatic) neural control mechanisms governing these functions, relevant across multiple conditions (SCI, MS, PD, and others)."},{"id": 6295,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Easy","question": "Which of the following describes an important consideration regarding cardiovascular autonomic monitoring during exercise/rehabilitation for patients with significant autonomic dysfunction (e.g., high-level SCI)?","options": [{"key": "A","text": "Exercise is always completely contraindicated for any patient with autonomic dysfunction"},{"key": "B","text": "Assuming normal cardiovascular response patterns identical to individuals without autonomic dysfunction"},{"key": "C","text": "Close monitoring of heart rate/blood pressure response given potentially altered/unpredictable autonomic cardiovascular regulation during activity"},{"key": "D","text": "No monitoring is required regardless of the severity of autonomic impairment"}],"correct": "C","explanation": "Given potentially altered/unpredictable cardiovascular autonomic responses (e.g., blunted heart rate response, risk of autonomic dysreflexia) in conditions like high-level SCI, careful monitoring during exercise/rehabilitation activity is an important safety consideration."},{"id": 6296,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Gliomas, the most common primary malignant brain tumors, arise from:","options": [{"key": "A","text": "Meningeal tissue exclusively"},{"key": "B","text": "Peripheral nerve cells exclusively"},{"key": "C","text": "Neurons directly"},{"key": "D","text": "Glial (supportive) cells of the central nervous system"}],"correct": "D","explanation": "Gliomas arise from glial cells (astrocytes, oligodendrocytes), representing the most common primary malignant brain tumor category, including glioblastoma as the most aggressive subtype."},{"id": 6297,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Meningiomas, typically benign brain tumors, arise from:","options": [{"key": "A","text": "Peripheral nerve tissue"},{"key": "B","text": "The meninges (membranes covering the brain and spinal cord)"},{"key": "C","text": "Neurons directly"},{"key": "D","text": "Glial cells"}],"correct": "B","explanation": "Meningiomas arise from meningeal tissue, are typically benign/slow-growing, though can cause significant symptoms through mass effect depending on location/size."},{"id": 6298,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Brain tumor-related neurological deficits typically depend primarily on:","options": [{"key": "A","text": "Tumor size alone, regardless of location"},{"key": "B","text": "Only the histological tumor type, regardless of location"},{"key": "C","text": "The specific location of the tumor and structures affected/compressed"},{"key": "D","text": "Patient age exclusively"}],"correct": "C","explanation": "The specific neurological deficit pattern from a brain tumor primarily reflects the affected anatomical location and structures involved/compressed, alongside tumor type/size considerations."},{"id": 6299,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Physiotherapy rehabilitation for patients with brain tumors shares similarities with stroke rehabilitation in that both may address:","options": [{"key": "A","text": "Rehabilitation approaches entirely unrelated between these conditions"},{"key": "B","text": "Only cognitive impairment, never motor impairment"},{"key": "C","text": "Completely different rehabilitation principles with no overlap whatsoever"},{"key": "D","text": "Similar patterns of motor, sensory, and functional impairment depending on lesion location"}],"correct": "D","explanation": "Given potentially similar patterns of focal neurological impairment (depending on lesion location), brain tumor rehabilitation often shares overlapping principles with stroke rehabilitation approaches, adapted to the tumor-specific context (e.g., prognosis, treatment effects)."},{"id": 6300,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which of the following describes an important consideration distinguishing brain tumor rehabilitation from typical stroke rehabilitation planning?","options": [{"key": "A","text": "No distinguishing considerations exist between these two rehabilitation contexts"},{"key": "B","text": "Brain tumor patients never require any rehabilitation input"},{"key": "C","text": "Stroke rehabilitation principles are entirely inapplicable to brain tumor rehabilitation"},{"key": "D","text": "Consideration of tumor prognosis, ongoing oncological treatment effects (e.g., radiation, chemotherapy), and potential for disease progression"}],"correct": "D","explanation": "Brain tumor rehabilitation must additionally consider prognosis, treatment-related effects (fatigue from radiation/chemotherapy), and potential for disease progression, informing a somewhat different overall approach compared to the generally more stable post-stroke recovery trajectory."},{"id": 6301,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Radiation therapy for brain tumors can contribute to which relevant rehabilitation consideration?","options": [{"key": "A","text": "Treatment-related fatigue and potential cognitive effects impacting rehabilitation participation"},{"key": "B","text": "Only affects the tumor itself with no impact on surrounding brain tissue or patient function"},{"key": "C","text": "Complete restoration of normal function immediately following treatment completion"},{"key": "D","text": "No relevant impact on rehabilitation planning"}],"correct": "A","explanation": "Radiation therapy can contribute to fatigue and potential cognitive effects, relevant considerations for pacing and adapting rehabilitation approaches during and after treatment."},{"id": 6302,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Spinal cord tumors (intramedullary or extramedullary) can produce neurological deficits reflecting:","options": [{"key": "A","text": "No relationship between tumor location and resulting clinical presentation"},{"key": "B","text": "Only sensory symptoms, never motor involvement"},{"key": "C","text": "Identical presentation regardless of spinal level involved"},{"key": "D","text": "The specific spinal level and structures affected, similar in principle to traumatic spinal cord injury presentations"}],"correct": "D","explanation": "Similar to traumatic SCI, spinal cord tumors produce deficits reflecting the specific level and structures affected, informing a comparable rehabilitation approach adapted to the oncological context."},{"id": 6303,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important palliative care consideration relevant to rehabilitation for patients with progressive, incurable brain/spinal tumors?","options": [{"key": "A","text": "Focus shifting toward comfort, quality of life, and functional support appropriate to the person's changing status and goals as the disease progresses"},{"key": "B","text": "Palliative considerations are entirely separate from rehabilitation practice with no overlap"},{"key": "C","text": "Rehabilitation has no role whatsoever in palliative/end-of-life care contexts"},{"key": "D","text": "Maximal restorative rehabilitation intensity should always be maintained regardless of disease progression or patient wishes"}],"correct": "A","explanation": "Palliative rehabilitation approaches appropriately shift focus toward comfort, quality of life, and functional support tailored to the individual's changing status and goals as a progressive, incurable condition advances."},{"id": 6304,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding fatigue management for patients undergoing chemotherapy as part of neuro-oncological treatment?","options": [{"key": "A","text": "Fatigue never occurs during chemotherapy treatment"},{"key": "B","text": "Maximal intensity exercise should always be prescribed regardless of treatment-related fatigue"},{"key": "C","text": "Cancer-related fatigue is common and multifactorial, requiring appropriately paced, individualized activity/exercise approaches"},{"key": "D","text": "Complete avoidance of all physical activity during any cancer treatment is universally recommended"}],"correct": "C","explanation": "Cancer-related fatigue is a common, multifactorial symptom during oncological treatment, requiring individualized, appropriately paced activity/exercise approaches (rather than either overexertion or complete inactivity) as part of comprehensive supportive care."},{"id": 6305,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes an appropriate multidisciplinary approach to neuro-oncology rehabilitation?","options": [{"key": "A","text": "A single discipline can independently manage all aspects of neuro-oncology care without any need for coordination"},{"key": "B","text": "Rehabilitation professionals should have no involvement in the care of neuro-oncology patients"},{"key": "C","text": "Multidisciplinary care has no relevance or evidence base in neuro-oncology management"},{"key": "D","text": "Coordination between oncology, neurology, rehabilitation specialists, and other relevant team members to address the complex, evolving needs across the disease trajectory"}],"correct": "D","explanation": "Given the complex, evolving needs across the neuro-oncology disease trajectory (diagnosis, treatment, survivorship, or progression), coordinated multidisciplinary team involvement is important for comprehensive, appropriately adapted care."},{"id": 6306,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Migraine headache is classically characterized by:","options": [{"key": "A","text": "Sudden onset 'thunderclap' severe headache always"},{"key": "B","text": "Often unilateral, throbbing/pulsatile pain, frequently associated with nausea, photophobia, and phonophobia"},{"key": "C","text": "Bilateral, band-like pressure without any associated symptoms"},{"key": "D","text": "Pain exclusively triggered by neck movement"}],"correct": "B","explanation": "Migraine classically presents with unilateral, throbbing pain often accompanied by nausea, photophobia, and phonophobia, sometimes preceded by an aura."},{"id": 6307,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Migraine with aura refers to:","options": [{"key": "A","text": "A term unrelated to any neurological symptom pattern"},{"key": "B","text": "A migraine subtype that never involves any headache pain"},{"key": "C","text": "Migraine preceded by transient neurological symptoms (e.g., visual disturbance) before headache onset"},{"key": "D","text": "Migraine occurring exclusively at night"}],"correct": "C","explanation": "Migraine with aura involves transient neurological symptoms (commonly visual, sometimes sensory or speech-related) preceding or accompanying the headache phase."},{"id": 6308,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Tension-type headache, the most common primary headache type, is typically characterized by:","options": [{"key": "A","text": "Bilateral, band-like pressure or tightness sensation, generally without significant nausea or photophobia"},{"key": "B","text": "Pain exclusively associated with visual aura"},{"key": "C","text": "Unilateral throbbing pain with prominent nausea"},{"key": "D","text": "Sudden severe onset requiring emergency evaluation always"}],"correct": "A","explanation": "Tension-type headache typically presents with bilateral, pressing/tightening (non-pulsatile) pain, generally milder and without the prominent associated features seen in migraine."},{"id": 6309,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Cluster headache is characterized by:","options": [{"key": "A","text": "Severe, unilateral periorbital pain occurring in clusters, often with ipsilateral autonomic features (e.g., tearing, nasal congestion)"},{"key": "B","text": "Bilateral mild pressure sensation without any autonomic features"},{"key": "C","text": "Pain that is never severe in intensity"},{"key": "D","text": "A headache type exclusively affecting women"}],"correct": "A","explanation": "Cluster headache presents with severe unilateral periorbital/temporal pain, often with ipsilateral autonomic signs (lacrimation, rhinorrhea, ptosis), occurring in characteristic clusters."},{"id": 6310,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Cervicogenic headache is thought to originate from:","options": [{"key": "A","text": "Primary intracranial vascular pathology exclusively"},{"key": "B","text": "A condition entirely unrelated to any musculoskeletal structure"},{"key": "C","text": "Exclusively psychological factors"},{"key": "D","text": "Referred pain from upper cervical spine structures (joints, muscles)"}],"correct": "D","explanation": "Cervicogenic headache is attributed to referred pain from upper cervical spine structures, relevant to physiotherapy assessment and management given its musculoskeletal origin."},{"id": 6311,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which 'red flag' features in headache presentation would warrant urgent medical evaluation to exclude serious underlying pathology?","options": [{"key": "A","text": "Headache occurring only with specific known triggers like stress"},{"key": "B","text": "Mild headache relieved by simple analgesics"},{"key": "C","text": "Sudden severe 'thunderclap' onset, headache with fever/neck stiffness, or new headache with neurological deficit"},{"key": "D","text": "Headache that has occurred in a similar pattern for many years without change"}],"correct": "C","explanation": "Red flag features (thunderclap onset, meningeal signs, new neurological deficit, and others) suggest possible serious underlying pathology (e.g., subarachnoid hemorrhage, meningitis, mass lesion) requiring urgent medical evaluation, distinct from typical primary headache presentations."},{"id": 6312,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Trigeminal neuralgia is characterized by:","options": [{"key": "A","text": "Pain exclusively affecting the lower limb"},{"key": "B","text": "Constant, dull facial ache without any triggering factor"},{"key": "C","text": "Severe, brief, electric shock-like facial pain in the trigeminal nerve distribution, often triggered by light touch"},{"key": "D","text": "Bilateral symmetric facial pain always"}],"correct": "C","explanation": "Trigeminal neuralgia presents with severe, brief, lancinating facial pain in the CN V distribution, classically triggered by light touch/stimulation of specific facial trigger zones."},{"id": 6313,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration for patients with cervicogenic headache?","options": [{"key": "A","text": "Assuming all headaches are cervicogenic in origin, requiring identical management regardless of type"},{"key": "B","text": "Physiotherapy has no relevant role in headache management of any type"},{"key": "C","text": "Complete avoidance of any cervical spine assessment in headache presentations"},{"key": "D","text": "Assessment and treatment of upper cervical spine mobility/muscle function as a potential contributing/treatable factor"}],"correct": "D","explanation": "Given the musculoskeletal origin proposed for cervicogenic headache, physiotherapy assessment/treatment of upper cervical spine function represents a relevant, evidence-informed management approach for this specific headache type."},{"id": 6314,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Medication overuse headache refers to:","options": [{"key": "A","text": "Headache resulting from excessive use of acute headache/pain medications, paradoxically perpetuating chronic headache"},{"key": "B","text": "A headache type completely unrelated to medication use"},{"key": "C","text": "A condition that always requires increasing medication dose for management"},{"key": "D","text": "A term with no clinical relevance"}],"correct": "A","explanation": "Medication overuse headache describes a paradoxical chronic headache pattern resulting from excessive use of acute symptomatic headache medications, an important consideration in chronic headache management requiring appropriate medication review."},{"id": 6315,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration regarding exercise as a potential migraine trigger versus management strategy?","options": [{"key": "A","text": "Maximal high-intensity exercise is always recommended for all migraine patients regardless of individual trigger patterns"},{"key": "B","text": "Exercise should always be completely avoided by all migraine patients"},{"key": "C","text": "Exercise has no relationship whatsoever to migraine in any patient"},{"key": "D","text": "While intense exercise can trigger migraine in some individuals, regular moderate exercise may help reduce migraine frequency in others, requiring individualized approach"}],"correct": "D","explanation": "The relationship between exercise and migraine is individualized—while it can be a trigger for some, regular moderate exercise is associated with reduced migraine frequency for others, requiring a personalized approach to exercise prescription in migraine management."},{"id": 6316,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following brainstem syndromes results from occlusion of the anterior inferior cerebellar artery (AICA)?","options": [{"key": "A","text": "Lateral pontine syndrome"},{"key": "B","text": "Lateral medullary (Wallenberg) syndrome"},{"key": "C","text": "Medial medullary syndrome"},{"key": "D","text": "Weber syndrome"}],"correct": "A","explanation": "AICA occlusion causes lateral pontine syndrome, presenting with ipsilateral facial paralysis, deafness, and cerebellar signs alongside contralateral pain/temperature loss."},{"id": 6317,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Weber syndrome, a midbrain stroke syndrome, presents with which combination of findings?","options": [{"key": "A","text": "Only cerebellar signs without any cranial nerve involvement"},{"key": "B","text": "Isolated contralateral sensory loss without any motor involvement"},{"key": "C","text": "Ipsilateral CN III palsy with contralateral hemiplegia"},{"key": "D","text": "Bilateral CN III palsy without any limb weakness"}],"correct": "C","explanation": "Weber syndrome results from midbrain infarction affecting the cerebral peduncle and CN III fascicles, causing ipsilateral oculomotor palsy with contralateral hemiplegia."},{"id": 6318,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Medial medullary syndrome classically presents with which combination of findings?","options": [{"key": "A","text": "Bilateral symmetric weakness of all four limbs"},{"key": "B","text": "Isolated cerebellar ataxia without any other findings"},{"key": "C","text": "Contralateral hemiplegia (sparing face), contralateral loss of proprioception, and ipsilateral tongue weakness"},{"key": "D","text": "Ipsilateral hemiplegia with contralateral facial weakness"}],"correct": "C","explanation": "Medial medullary syndrome (anterior spinal artery/vertebral artery territory) affects the pyramid, medial lemniscus, and hypoglossal nerve fascicles, producing this characteristic pattern."},{"id": 6319,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "The 'clasp-knife' phenomenon, seen in spasticity, describes:","options": [{"key": "A","text": "Sudden release of resistance to passive stretch after an initial catch"},{"key": "B","text": "Uniform resistance throughout the entire range of motion"},{"key": "C","text": "A phenomenon exclusive to cerebellar hypotonia"},{"key": "D","text": "Complete absence of any resistance to movement"}],"correct": "A","explanation": "Clasp-knife phenomenon describes the characteristic sudden give/release of resistance during passive stretch of a spastic muscle after an initial catch, related to Golgi tendon organ-mediated inhibition."},{"id": 6320,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Apraxia of speech differs from dysarthria in that it primarily involves:","options": [{"key": "A","text": "Complete absence of any speech production capability"},{"key": "B","text": "Weakness of the speech musculature itself"},{"key": "C","text": "A pure language comprehension deficit"},{"key": "D","text": "Difficulty planning/programming the motor movements for speech, despite intact muscle strength"}],"correct": "D","explanation": "Apraxia of speech reflects a motor planning deficit (difficulty sequencing/programming articulatory movements) rather than the muscle weakness/incoordination seen in dysarthria."},{"id": 6321,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Ideomotor apraxia refers to:","options": [{"key": "A","text": "Difficulty performing learned skilled movements on command despite intact comprehension and motor ability"},{"key": "B","text": "A pure sensory deficit"},{"key": "C","text": "Complete paralysis of the affected limb"},{"key": "D","text": "Only affecting facial movement, never limb movement"}],"correct": "A","explanation": "Ideomotor apraxia describes impaired ability to perform learned motor tasks on command (e.g., 'show me how to wave') despite intact strength, sensation, and comprehension of the task."},{"id": 6322,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Anosognosia, sometimes seen after right hemisphere stroke, refers to:","options": [{"key": "A","text": "Lack of awareness or denial of one's own neurological deficit"},{"key": "B","text": "Excessive awareness/preoccupation with minor symptoms"},{"key": "C","text": "Only relevant to left hemisphere lesions"},{"key": "D","text": "A pure motor deficit without any cognitive component"}],"correct": "A","explanation": "Anosognosia describes a striking unawareness or denial of one's deficit (e.g., denying hemiplegia), more commonly associated with right hemisphere lesions, with important safety implications for rehabilitation."},{"id": 6323,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "The 'mini-mental state examination' typically assesses cognitive domains including:","options": [{"key": "A","text": "Only cranial nerve function"},{"key": "B","text": "Orientation, registration, attention/calculation, recall, and language"},{"key": "C","text": "Only sensory function"},{"key": "D","text": "Only motor strength"}],"correct": "B","explanation": "MMSE covers multiple cognitive domains (orientation, registration, attention/calculation, recall, language, visuospatial), providing a brief overall cognitive screen."},{"id": 6324,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following best describes the concept of 'diaschisis' relevant to stroke recovery?","options": [{"key": "A","text": "Permanent damage to areas distant from the lesion with no recovery potential"},{"key": "B","text": "Only relevant to spinal cord injury, not stroke"},{"key": "C","text": "A term unrelated to stroke pathophysiology"},{"key": "D","text": "Temporary functional depression of areas distant from but connected to the lesion site, which may recover as diaschisis resolves"}],"correct": "D","explanation": "Diaschisis describes temporary functional suppression in brain regions connected to (but distant from) the primary lesion, with potential for its resolution to contribute to early spontaneous recovery."},{"id": 6325,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "The concept of 'penumbra' in acute ischemic stroke refers to:","options": [{"key": "A","text": "Tissue that is functionally impaired but still potentially viable/salvageable if perfusion is restored promptly"},{"key": "B","text": "Healthy tissue completely unaffected by the ischemic event"},{"key": "C","text": "Tissue that is already irreversibly infarcted"},{"key": "D","text": "A term unrelated to blood flow/perfusion"}],"correct": "A","explanation": "The ischemic penumbra represents at-risk but potentially salvageable tissue surrounding the infarct core, the therapeutic target of acute reperfusion strategies."},{"id": 6326,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes the 'time is brain' concept in acute stroke management?","options": [{"key": "A","text": "A concept suggesting that stroke treatment timing has no impact on outcomes"},{"key": "B","text": "A term with no clinical relevance to stroke care"},{"key": "C","text": "Emphasizing that delays in treatment result in progressive, ongoing loss of potentially salvageable brain tissue"},{"key": "D","text": "Only relevant to hemorrhagic stroke, not ischemic stroke"}],"correct": "C","explanation": "'Time is brain' emphasizes the urgency of acute stroke treatment, as ongoing ischemia progressively converts penumbral tissue into irreversible infarct, making rapid intervention critical."},{"id": 6327,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the general concept of 'critical period' relevance to neuroplasticity-based rehabilitation timing?","options": [{"key": "A","text": "No time-related variation in neuroplastic potential exists at any point post-injury"},{"key": "B","text": "Certain time windows post-injury may show heightened neuroplastic potential, informing rationale for early, appropriately dosed rehabilitation"},{"key": "C","text": "Rehabilitation timing has no relationship to neuroplasticity concepts"},{"key": "D","text": "Neuroplasticity only occurs during a fixed 24-hour window post-injury"}],"correct": "B","explanation": "Emerging evidence suggests potential time-sensitive windows of heightened neuroplastic responsiveness post-injury, informing (though still evolving) understanding of optimal rehabilitation timing and intensity."},{"id": 6328,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following best describes 'spasticity' distribution typically seen in the upper limb following stroke, relevant to splinting/positioning decisions?","options": [{"key": "A","text": "No spasticity ever develops in the upper limb after stroke"},{"key": "B","text": "Predominant flexor pattern (shoulder adductors/internal rotators, elbow/wrist/finger flexors)"},{"key": "C","text": "Predominant extensor pattern throughout the entire upper limb"},{"key": "D","text": "Equal distribution between flexors and extensors with no predominant pattern"}],"correct": "B","explanation": "Post-stroke upper limb spasticity typically shows flexor pattern predominance, informing common positioning/splinting strategies aimed at counteracting this pattern."},{"id": 6329,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following describes the general lower limb spasticity distribution pattern following stroke, relevant to gait and orthotic management?","options": [{"key": "A","text": "Predominant extensor pattern (hip extensors/adductors, knee extensors, ankle plantarflexors/invertors)"},{"key": "B","text": "Predominant flexor pattern throughout the entire lower limb"},{"key": "C","text": "Only affects the ankle, never the hip or knee"},{"key": "D","text": "No consistent pattern develops in the lower limb after stroke"}],"correct": "A","explanation": "Lower limb post-stroke spasticity typically shows extensor pattern predominance (contributing to equinovarus foot position), informing common AFO and management strategies."},{"id": 6330,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the use of standardized outcome measures across different neurological rehabilitation settings?","options": [{"key": "A","text": "Only one single outcome measure should ever be used regardless of the specific clinical population or context"},{"key": "B","text": "Outcome measurement is only relevant for research, never for clinical practice"},{"key": "C","text": "Consistent use of validated, standardized measures supports tracking progress, communication between providers, and evidence-based practice"},{"key": "D","text": "Standardized measures have no value and should be replaced entirely with subjective clinical impression"}],"correct": "C","explanation": "Consistent use of appropriately selected, validated standardized outcome measures supports progress tracking, communication, and evidence-based clinical decision-making across neurological rehabilitation settings."},{"id": 6331,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the general concept of 'neurogenic' versus 'myogenic' pattern differentiation on clinical/electrodiagnostic assessment?","options": [{"key": "A","text": "Neurogenic patterns only occur in muscle disease, never nerve disease"},{"key": "B","text": "These terms are synonymous with no meaningful distinction"},{"key": "C","text": "Myogenic patterns always show more severe weakness than neurogenic patterns"},{"key": "D","text": "Neurogenic patterns suggest nerve/motor neuron pathology (e.g., fasciculations, neurogenic EMG pattern) while myogenic patterns suggest primary muscle pathology"}],"correct": "D","explanation": "Differentiating neurogenic (nerve/motor neuron origin, e.g., fasciculations, specific EMG findings) from myogenic (primary muscle disease) patterns is an important diagnostic consideration in evaluating weakness."},{"id": 6332,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes the general relevance of the 'Modified Rankin Scale' in stroke outcome reporting?","options": [{"key": "A","text": "A tool with no relevance to stroke outcome assessment"},{"key": "B","text": "A measure exclusively used for assessing upper limb motor function"},{"key": "C","text": "Only used for pediatric neurological conditions, not adult stroke"},{"key": "D","text": "Widely used global disability outcome measure (0-6) commonly reported in stroke clinical trials and clinical practice"}],"correct": "D","explanation": "mRS is one of the most widely used global disability outcome measures in stroke research and clinical practice, providing a simple overall functional status classification."},{"id": 6333,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the use of the Berg Balance Scale across different neurological populations?","options": [{"key": "A","text": "Has no established validity in any neurological population"},{"key": "B","text": "Validated for use across multiple neurological populations (e.g., stroke, Parkinson's) though ceiling/floor effects may limit sensitivity in certain contexts"},{"key": "C","text": "Only validated and appropriate for stroke populations, never other neurological conditions"},{"key": "D","text": "Cannot be used in any research or clinical context due to lack of standardization"}],"correct": "B","explanation": "BBS has been validated across various neurological populations, though clinicians should be aware of potential ceiling (high-functioning patients) or floor (very impaired patients) effects limiting its sensitivity in certain contexts."},{"id": 6334,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following describes an important consideration regarding fatigue as a symptom across multiple different neurological conditions (e.g., MS, stroke, TBI, GBS, ALS)?","options": [{"key": "A","text": "Fatigue only occurs in Multiple Sclerosis, not in any other neurological condition"},{"key": "B","text": "Fatigue has no relevance to rehabilitation planning in any neurological condition"},{"key": "C","text": "Fatigue always resolves spontaneously without requiring any specific management approach"},{"key": "D","text": "Fatigue is a commonly reported, often significant symptom across many neurological conditions, frequently requiring dedicated assessment and management strategies"}],"correct": "D","explanation": "Fatigue is recognized as a common, often underappreciated symptom across numerous neurological conditions, warranting dedicated assessment and appropriately tailored management strategies as part of comprehensive rehabilitation."},{"id": 6335,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following best describes an important general principle regarding goal-setting across different neurological rehabilitation contexts?","options": [{"key": "A","text": "Goals should always be set without any patient/family input across all neurological conditions"},{"key": "B","text": "A single universal goal-setting template applies identically regardless of the underlying condition or prognosis"},{"key": "C","text": "Goals should be individualized, meaningful to the patient, and appropriately adjusted based on the specific condition's trajectory (recovery-focused versus progressive/degenerative)"},{"key": "D","text": "Goal-setting is irrelevant in progressive/degenerative neurological conditions"}],"correct": "C","explanation": "Effective goal-setting across neurological rehabilitation requires individualization considering the patient's specific condition, prognosis (recovery potential versus progressive decline), and personally meaningful priorities."},{"id": 6336,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding caregiver burden in the context of long-term neurological conditions?","options": [{"key": "A","text": "Caregiver support needs are identical regardless of the specific underlying condition or care demands"},{"key": "B","text": "Only paid professional caregivers experience any burden, family caregivers are unaffected"},{"key": "C","text": "Caregiver burden is not a relevant consideration in neurological rehabilitation practice"},{"key": "D","text": "Caregivers of individuals with significant, long-term neurological disability often experience considerable physical/emotional burden, warranting attention within comprehensive care planning"}],"correct": "D","explanation": "Recognizing and addressing caregiver burden (which varies based on condition, care demands, and available support) is an important, often underemphasized, component of comprehensive long-term neurological care planning."},{"id": 6337,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the interpretation of muscle stretch reflex changes in the context of an evolving acute neurological presentation (e.g., early spinal cord injury)?","options": [{"key": "A","text": "Reflex findings remain completely static and unchanging from the moment of acute injury"},{"key": "B","text": "Hyperreflexia is always present immediately from the moment of any upper motor neuron injury"},{"key": "C","text": "Reflex assessment provides no useful clinical information in acute neurological presentations"},{"key": "D","text": "Initial hyporeflexia/areflexia (spinal shock) may transition to hyperreflexia over time, requiring serial reassessment rather than a single static interpretation"}],"correct": "D","explanation": "Understanding the potential evolution of reflex findings over time (e.g., spinal shock transitioning to hyperreflexia) is important for accurate serial clinical assessment and interpretation in acute neurological injury."},{"id": 6338,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the assessment of pain in patients with significant cognitive or communication impairment following neurological injury?","options": [{"key": "A","text": "Only relying on vital sign changes, ignoring any behavioral indicators of pain"},{"key": "B","text": "Using appropriate observational pain assessment tools/behavioral indicators when self-report is unreliable or unavailable"},{"key": "C","text": "Assuming no pain assessment is possible or necessary if the patient cannot verbally self-report"},{"key": "D","text": "Pain assessment is irrelevant in patients with cognitive/communication impairment"}],"correct": "B","explanation": "For patients unable to reliably self-report pain (due to cognitive/communication impairment), appropriate observational/behavioral pain assessment tools become important for adequate pain recognition and management."},{"id": 6339,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes the general relevance of interdisciplinary team meetings/case conferences in complex neurological rehabilitation settings?","options": [{"key": "A","text": "Only physicians need to be involved in any case discussion, other team members' input is unnecessary"},{"key": "B","text": "Facilitate coordinated goal-setting, information sharing, and consistent approach across team members addressing the patient's multifaceted needs"},{"key": "C","text": "Interdisciplinary meetings have no practical benefit and should be avoided as inefficient use of time"},{"key": "D","text": "A single discipline's assessment is always sufficient without needing any broader team discussion"}],"correct": "B","explanation": "Regular interdisciplinary team communication supports coordinated, consistent, and comprehensive management addressing the multifaceted needs commonly seen in complex neurological rehabilitation cases."},{"id": 6340,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the use of standing frames/tilt tables for patients with severely limited mobility following neurological injury, beyond simply promoting ambulation?","options": [{"key": "A","text": "No physiological benefit exists from standing programs regardless of ambulation potential"},{"key": "B","text": "Standing frames are contraindicated in all patients with severe neurological impairment"},{"key": "C","text": "Multiple physiological benefits including bone loading, spasticity management, cardiovascular conditioning, and psychological benefit, even without ambulation as an immediate goal"},{"key": "D","text": "Standing frames only have value if independent ambulation is an achievable, immediate goal"}],"correct": "C","explanation": "Standing programs offer multiple physiological and psychological benefits independent of ambulation potential, making them valuable even for patients unlikely to achieve independent walking."},{"id": 6341,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the impact of medication side effects (e.g., sedation from certain antiepileptics or spasticity medications) on rehabilitation participation?","options": [{"key": "A","text": "All medications used in neurological conditions have identical side effect profiles with no impact on rehabilitation"},{"key": "B","text": "Physiotherapists should never consider or discuss medication effects with the broader medical team"},{"key": "C","text": "Medication effects are entirely irrelevant to physiotherapy assessment and treatment planning"},{"key": "D","text": "Medication side effects can significantly impact alertness, fatigue, and rehabilitation engagement, warranting awareness and potential coordination with the medical team regarding timing/dosing"}],"correct": "D","explanation": "Awareness of medication side effects (e.g., sedation, fatigue) affecting rehabilitation participation is important, sometimes warranting appropriate coordination/communication with the prescribing medical team regarding timing or dosing considerations."},{"id": 6342,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes an important consideration in comprehensive fall risk assessment across various neurological populations (e.g., stroke, Parkinson's, peripheral neuropathy)?","options": [{"key": "A","text": "A single universal fall risk assessment tool applies identically and adequately across all neurological populations without any need for condition-specific consideration"},{"key": "B","text": "Fall risk factors are identical regardless of the specific underlying neurological condition"},{"key": "C","text": "Fall risk assessment is only relevant for elderly patients, never younger individuals with neurological conditions"},{"key": "D","text": "Multifactorial assessment addressing condition-specific risk factors (e.g., visual field deficits, freezing episodes, sensory loss) alongside general balance/strength factors"}],"correct": "D","explanation": "Comprehensive fall risk assessment should consider both general balance/strength factors and condition-specific risk elements (e.g., visual field deficits in stroke, freezing in PD, sensory loss in neuropathy) for a thorough, individualized evaluation."},{"id": 6343,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes an important consideration regarding return-to-driving assessment following neurological injury/illness (e.g., stroke, seizure, significant motor/cognitive impairment)?","options": [{"key": "A","text": "Driving assessment has no relevance to neurological rehabilitation practice"},{"key": "B","text": "Requires careful, often formal assessment addressing physical, cognitive, and visual factors, alongside relevant legal/regulatory requirements which vary by jurisdiction"},{"key": "C","text": "Legal/regulatory requirements regarding driving are irrelevant to rehabilitation planning"},{"key": "D","text": "Return to driving should always be immediately permitted regardless of any residual impairment"}],"correct": "B","explanation": "Return-to-driving decisions following neurological injury require careful consideration of physical, cognitive, and visual factors, often involving formal assessment and awareness of relevant jurisdiction-specific legal/regulatory requirements."},{"id": 6344,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Hard","question": "Which of the following describes an important consideration regarding sexuality/intimacy discussions as part of comprehensive rehabilitation following significant neurological injury (e.g., SCI, stroke)?","options": [{"key": "A","text": "An important quality-of-life domain warranting sensitive, appropriate discussion and support as part of holistic rehabilitation care"},{"key": "B","text": "Irrelevant to comprehensive rehabilitation planning and outcomes"},{"key": "C","text": "Only relevant for younger patients, never for older individuals with neurological injury"},{"key": "D","text": "A topic that should never be discussed within rehabilitation settings under any circumstances"}],"correct": "A","explanation": "Sexuality and intimacy represent important quality-of-life domains that warrant sensitive, appropriately timed discussion and support as part of comprehensive, holistic rehabilitation following significant neurological injury."},{"id": 6345,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes an important consideration regarding vocational rehabilitation as part of comprehensive care following neurological injury in working-age adults?","options": [{"key": "A","text": "Vocational considerations are irrelevant to rehabilitation practice, only physical recovery matters"},{"key": "B","text": "Vocational rehabilitation is solely the responsibility of employers with no role for the rehabilitation team"},{"key": "C","text": "All patients automatically return to their previous employment without requiring any specific support or planning"},{"key": "D","text": "Addressing return-to-work potential and any necessary workplace accommodations is an important component of comprehensive rehabilitation planning for working-age individuals"}],"correct": "D","explanation": "Vocational rehabilitation, addressing return-to-work potential and necessary accommodations, is an important consideration for comprehensive care planning in working-age adults following neurological injury."},{"id": 6346,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the assessment of visual perceptual deficits (e.g., unilateral neglect, visual field defects) as distinct from primary visual acuity problems following stroke?","options": [{"key": "A","text": "Visual perceptual deficits and visual acuity problems are identical with no need for any distinction"},{"key": "B","text": "Only ophthalmological assessment is relevant, with no role for rehabilitation-specific visual perceptual assessment"},{"key": "C","text": "Specific assessment tools/approaches are needed to differentiate these higher-order visual processing deficits from simple visual acuity impairment, given different management implications"},{"key": "D","text": "Visual perceptual deficits never occur following stroke, only primary visual acuity changes are relevant"}],"correct": "C","explanation": "Distinguishing higher-order visual perceptual deficits (like neglect or field cuts) from primary visual acuity problems requires specific assessment approaches, given their different underlying mechanisms and management implications for rehabilitation."},{"id": 6347,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes the general concept of 'apraxia of gait' sometimes seen in certain neurological conditions (e.g., normal pressure hydrocephalus)?","options": [{"key": "A","text": "Only relevant to peripheral nerve conditions, never central nervous system pathology"},{"key": "B","text": "Difficulty initiating/performing the learned motor pattern of walking despite adequate strength/sensation, distinct from weakness-based gait disturbance"},{"key": "C","text": "A condition that never impacts functional mobility"},{"key": "D","text": "A term identical to simple leg weakness affecting gait"}],"correct": "B","explanation": "Gait apraxia describes a higher-order difficulty in the motor planning/initiation of walking patterns, seen in certain conditions like normal pressure hydrocephalus, distinct from primary weakness-based gait impairment."},{"id": 6348,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Normal Pressure Hydrocephalus (NPH) classically presents with which triad of symptoms?","options": [{"key": "A","text": "Isolated tremor without any gait or cognitive involvement"},{"key": "B","text": "Gait disturbance, urinary incontinence, and cognitive impairment"},{"key": "C","text": "Isolated hearing loss without any other associated features"},{"key": "D","text": "Isolated visual field defect without any other symptoms"}],"correct": "B","explanation": "NPH classically presents with the triad of gait apraxia/disturbance, urinary incontinence, and cognitive impairment (sometimes remembered as 'wet, wacky, and wobbly'), potentially treatable with CSF shunting."},{"id": 6349,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the potential reversibility of NPH-related symptoms with appropriate treatment (CSF shunting)?","options": [{"key": "A","text": "NPH symptoms are always completely irreversible regardless of any treatment"},{"key": "B","text": "Gait disturbance in NPH never responds to any treatment intervention"},{"key": "C","text": "Shunt treatment provides no benefit for any NPH-related symptom"},{"key": "D","text": "Symptoms, particularly gait disturbance, may show significant improvement with timely shunt placement, making accurate diagnosis important"}],"correct": "D","explanation": "Timely diagnosis and appropriate CSF shunting can lead to significant improvement, particularly in gait function, making accurate NPH diagnosis clinically important given this treatment potential."},{"id": 6350,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes the general relevance of assessing 'insight' and 'safety awareness' in patients with significant cognitive impairment following neurological injury, relevant to physiotherapy discharge/home safety planning?","options": [{"key": "A","text": "Physical function alone determines safe discharge planning, with no need to consider cognitive/insight factors"},{"key": "B","text": "Impaired insight/safety awareness can significantly affect a patient's ability to safely manage risks independently, requiring careful consideration in discharge and support planning"},{"key": "C","text": "Assuming all patients have identical insight regardless of their specific cognitive impairment pattern"},{"key": "D","text": "Insight and safety awareness have no relevance to physiotherapy discharge planning"}],"correct": "B","explanation": "Assessing insight and safety awareness is crucial, as impairments in these domains can significantly affect a patient's ability to safely manage risks independently, informing appropriate discharge planning and support recommendations."},{"id": 6351,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'errorless learning' sometimes used in cognitive-motor rehabilitation for patients with significant memory impairment?","options": [{"key": "A","text": "This approach is only relevant for physical motor learning, never for any cognitive rehabilitation context"},{"key": "B","text": "Deliberately maximizing errors during practice is always the most effective approach for all patients regardless of memory status"},{"key": "C","text": "Structuring practice to minimize errors during the learning process, as patients with significant memory impairment may not benefit from and may be disadvantaged by trial-and-error learning with error correction"},{"key": "D","text": "Errorless learning has no evidence base or relevance to neurorehabilitation practice"}],"correct": "C","explanation": "Errorless learning approaches (minimizing mistakes during the learning process) can be particularly beneficial for patients with significant memory impairment who may not effectively learn from or remember error correction in typical trial-and-error learning paradigms."},{"id": 6352,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the use of external memory aids (e.g., calendars, alarms, notebooks) as a compensatory strategy in cognitive rehabilitation?","options": [{"key": "A","text": "Memory aids should never be used as they may worsen the underlying memory impairment"},{"key": "B","text": "External memory aids have no evidence of benefit for any patient with memory impairment"},{"key": "C","text": "Only relevant for patients with completely normal cognitive function, providing no benefit for those with impairment"},{"key": "D","text": "Can effectively support functional independence for patients with memory impairment, particularly when consistently and systematically implemented with appropriate training"}],"correct": "D","explanation": "External memory aids represent an effective compensatory strategy for supporting functional independence in patients with memory impairment, particularly when systematically trained and consistently implemented as part of a structured rehabilitation approach."},{"id": 6353,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration in interpreting standardized cognitive screening tool results (e.g., MMSE, MoCA) within the broader clinical context?","options": [{"key": "A","text": "Cognitive screening tool scores require no clinical interpretation or contextualization whatsoever"},{"key": "B","text": "These tools provide a definitive, complete diagnostic assessment requiring no further clinical judgment or additional testing"},{"key": "C","text": "Scores should be interpreted considering factors like education level, cultural/language background, and the specific clinical context, rather than as an absolute isolated number"},{"key": "D","text": "A single cut-off score applies identically and appropriately to interpret impairment across all patients regardless of any other individual factors"}],"correct": "C","explanation": "Standardized cognitive screening results should be interpreted within the broader clinical context, considering factors such as education, cultural/language background, and other relevant individual factors, rather than relying solely on an isolated cut-off score."},{"id": 6354,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes the general principle underlying 'spaced retrieval' technique sometimes used in memory rehabilitation?","options": [{"key": "A","text": "A technique with no evidence base or theoretical rationale"},{"key": "B","text": "Requiring immediate, continuous repetition without any increasing time intervals between practice attempts"},{"key": "C","text": "Practicing recall of information at gradually increasing time intervals to strengthen memory retention"},{"key": "D","text": "Only relevant for physical motor skill practice, not for memory-specific rehabilitation"}],"correct": "C","explanation": "Spaced retrieval practice involves progressively increasing the time interval between recall attempts, a technique shown to support memory consolidation particularly relevant in cognitive rehabilitation contexts."},{"id": 6355,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which of the following describes an important consideration regarding assessment and management of dysphagia in patients with progressive neurological conditions (e.g., ALS, advanced Parkinson's), compared to typically more stable post-stroke dysphagia?","options": [{"key": "A","text": "Once initial dysphagia management strategies are established, no further reassessment is ever needed regardless of the underlying condition's trajectory"},{"key": "B","text": "May require ongoing reassessment and progressive adaptation of management strategies as swallowing function continues to change over the disease course"},{"key": "C","text": "Dysphagia never occurs in progressive neurological conditions, only following acute events like stroke"},{"key": "D","text": "Assessment and management approaches are identical regardless of whether the underlying condition is progressive or relatively stable"}],"correct": "B","explanation": "Progressive neurological conditions require ongoing dysphagia reassessment and adaptive management as swallowing function continues to evolve, differing from the generally more stable trajectory (following initial recovery) typically seen post-stroke."},{"id": 6356,"subject": "Neurology","topic": "Spinal Cord Injury","difficulty": "Medium","question": "Which of the following describes an important consideration regarding respiratory physiotherapy techniques (e.g., assisted coughing, breathing exercises) across different neurological conditions affecting respiratory muscle function (e.g., high SCI, GBS, ALS, DMD)?","options": [{"key": "A","text": "Respiratory physiotherapy techniques are completely different and non-transferable between these various conditions"},{"key": "B","text": "No respiratory physiotherapy techniques have any evidence base across any of these neurological conditions"},{"key": "C","text": "Similar underlying respiratory muscle weakness principles apply across these conditions, though specific management may need adaptation based on the condition's trajectory (acute/recovering versus chronic/progressive)"},{"key": "D","text": "Respiratory considerations are only relevant for spinal cord injury, not for any other neurological condition"}],"correct": "C","explanation": "While sharing common underlying principles related to respiratory muscle weakness management, specific approaches may require adaptation based on whether the condition follows an acute/recovering trajectory (e.g., GBS, acute SCI) versus a chronic/progressive course (e.g., ALS, advanced DMD)."},{"id": 6357,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'total communication' approaches for patients with severe combined motor and communication impairment (e.g., advanced ALS, locked-in syndrome)?","options": [{"key": "A","text": "Only verbal speech should be pursued as a communication goal, regardless of its feasibility given the physical impairment"},{"key": "B","text": "Utilizing multiple available communication modalities/technologies (e.g., eye-gaze systems, switch access) to maximize communication potential despite severe physical limitation"},{"key": "C","text": "Communication considerations are irrelevant to comprehensive rehabilitation planning for patients with severe motor impairment"},{"key": "D","text": "Assuming no meaningful communication is possible once severe motor impairment develops"}],"correct": "B","explanation": "Total communication approaches, leveraging various available technologies/modalities suited to the individual's specific remaining capabilities, aim to maximize communication potential even in the context of severe combined motor and communication impairment."},{"id": 6358,"subject": "Neurology","topic": "Assessment & Scales","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the interpretation of muscle strength testing (MRC scale) in the context of significant spasticity?","options": [{"key": "A","text": "Spasticity can complicate accurate strength assessment, sometimes requiring careful technique/interpretation to distinguish true voluntary strength from spasticity-related resistance"},{"key": "B","text": "Strength testing should never be attempted in patients with any degree of spasticity"},{"key": "C","text": "MRC grading is impossible to perform in the presence of any spasticity"},{"key": "D","text": "Spasticity has no impact whatsoever on the accuracy or interpretation of standard strength testing"}],"correct": "A","explanation": "The presence of spasticity can complicate straightforward strength assessment, requiring careful clinical technique and interpretation to appropriately distinguish true voluntary muscle strength from spasticity-related resistance/co-contraction effects."},{"id": 6359,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the interpretation of 'active range of motion' assessment findings in a patient with significant weakness combined with joint contracture?","options": [{"key": "A","text": "Active ROM assessment provides no useful information when any contracture is present"},{"key": "B","text": "Weakness and contracture always contribute identically and cannot be meaningfully distinguished during clinical assessment"},{"key": "C","text": "Assuming limited active ROM is always due to contracture alone, never related to underlying weakness"},{"key": "D","text": "Distinguishing the relative contribution of weakness versus contracture to limited active ROM is important for appropriately targeted intervention planning"}],"correct": "D","explanation": "Careful clinical assessment (comparing active versus passive ROM, and considering the overall clinical picture) helps distinguish the relative contribution of weakness versus true joint contracture, informing appropriately targeted intervention (e.g., strengthening versus stretching-focused approaches)."},{"id": 6360,"subject": "Neurology","topic": "Stroke & CVA","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the potential for 'central sensitization' to contribute to persistent pain following neurological injury (e.g., central post-stroke pain, SCI-related neuropathic pain)?","options": [{"key": "A","text": "This concept has no relevance to physiotherapy pain management approaches in neurological populations"},{"key": "B","text": "Pain following neurological injury always directly reflects ongoing peripheral tissue damage with no central contribution"},{"key": "C","text": "Central nervous system changes can amplify/perpetuate pain signaling independent of ongoing peripheral tissue pathology, relevant to understanding and managing chronic neuropathic pain in these populations"},{"key": "D","text": "Central sensitization is a concept exclusively relevant to musculoskeletal pain, with no relevance to neurological injury-related pain"}],"correct": "C","explanation": "Understanding central sensitization mechanisms (amplified/perpetuated central pain processing) is relevant to comprehending and appropriately managing chronic neuropathic pain conditions sometimes seen following neurological injury, such as central post-stroke pain or SCI-related neuropathic pain."},{"id": 6361,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding graded motor imagery approaches sometimes used in managing certain chronic neuropathic pain conditions?","options": [{"key": "A","text": "Only relevant for musculoskeletal pain conditions, never applicable to neurological pain presentations"},{"key": "B","text": "A staged approach (laterality recognition, imagined movements, then mirror therapy) aiming to gradually engage motor-related cortical networks without provoking excessive pain"},{"key": "C","text": "An approach with no theoretical rationale or evidence base"},{"key": "D","text": "A technique requiring immediate full engagement in actual physical movement without any graded/staged approach"}],"correct": "B","explanation": "Graded motor imagery uses a staged approach (starting with laterality judgment tasks, progressing to imagined movement, then mirror therapy) to gradually engage motor-related cortical networks in chronic pain management, including some neurological pain contexts."},{"id": 6362,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the assessment of 'functional' versus 'organic' presentations in neurological rehabilitation (e.g., functional neurological disorder)?","options": [{"key": "A","text": "Requires careful, non-judgmental clinical assessment and often specific positive clinical signs, with appropriately tailored, often multidisciplinary management approaches"},{"key": "B","text": "Organic and functional presentations are always immediately and easily distinguishable requiring no specific assessment approach"},{"key": "C","text": "Functional neurological disorders have no legitimate basis and should not be considered a genuine clinical entity"},{"key": "D","text": "Functional neurological presentations should always be assumed to reflect deliberate symptom fabrication"}],"correct": "A","explanation": "Functional neurological disorder represents a genuine, increasingly recognized clinical entity requiring careful, non-judgmental assessment (including specific positive clinical signs where applicable) and appropriately tailored, often multidisciplinary management approaches, distinct from assumptions of deliberate fabrication."},{"id": 6363,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding effective communication between physiotherapists and other team members when documenting/reporting on complex neurological rehabilitation cases?","options": [{"key": "A","text": "Clear, standardized, objective documentation supports continuity of care, appropriate goal tracking, and effective interdisciplinary communication"},{"key": "B","text": "Documentation has no relevance to effective interdisciplinary care coordination"},{"key": "C","text": "Only verbal communication is relevant, with no value in written documentation for care coordination"},{"key": "D","text": "Highly subjective, non-standardized documentation is equally effective as objective, standardized reporting"}],"correct": "A","explanation": "Clear, objective, appropriately standardized documentation supports continuity of care, accurate progress tracking, and effective communication among the interdisciplinary team managing complex neurological rehabilitation cases."},{"id": 6364,"subject": "Neurology","topic": "General Neurology","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the concept of 'patient-centered' versus 'impairment-focused' outcome goals in comprehensive neurological rehabilitation planning?","options": [{"key": "A","text": "Impairment-level findings are entirely irrelevant to effective rehabilitation planning"},{"key": "B","text": "These two considerations are mutually exclusive and can never be appropriately integrated within a single rehabilitation plan"},{"key": "C","text": "Effective rehabilitation typically integrates both impairment-level findings and patient-centered functional/participation goals, rather than focusing exclusively on one level alone"},{"key": "D","text": "Patient-centered goals should never be considered, with rehabilitation focusing exclusively on impairment-level measures"}],"correct": "C","explanation": "Comprehensive, effective rehabilitation planning typically integrates impairment-level assessment findings with meaningful patient-centered functional and participation goals, recognizing the value of both levels within a holistic approach (consistent with frameworks like the ICF model)."},{"id": 6365,"subject": "Neurology","topic": "General Neurology","difficulty": "Easy","question": "Which of the following describes the general relevance of the International Classification of Functioning, Disability and Health (ICF) framework to neurological rehabilitation practice?","options": [{"key": "A","text": "Focuses exclusively on impairment-level findings, ignoring broader activity/participation considerations"},{"key": "B","text": "Only relevant to research applications, never applied in direct clinical practice"},{"key": "C","text": "A framework with no practical relevance to clinical neurological rehabilitation practice"},{"key": "D","text": "Provides a holistic framework considering body structure/function, activity, participation, and contextual factors, guiding comprehensive assessment and intervention planning"}],"correct": "D","explanation": "The ICF framework provides a widely adopted, holistic model considering body structure/function impairments alongside activity limitations, participation restrictions, and relevant contextual (environmental/personal) factors, informing comprehensive neurological rehabilitation assessment and planning."},{"id": 6366,"subject": "Neurology","topic": "General Neurology","difficulty": "Medium","question": "Which of the following describes an important consideration regarding evidence-based practice application in neurological physiotherapy, integrating research evidence with clinical expertise and patient values?","options": [{"key": "A","text": "Effective evidence-based practice integrates best available research evidence, clinical expertise, and individual patient values/preferences, rather than relying on any single source in isolation"},{"key": "B","text": "Patient values/preferences are irrelevant to evidence-based practice, which should focus exclusively on research evidence"},{"key": "C","text": "Evidence-based practice means rigidly applying research findings regardless of individual patient factors or clinical judgment"},{"key": "D","text": "Clinical expertise alone, without any consideration of research evidence, represents adequate evidence-based practice"}],"correct": "A","explanation": "True evidence-based practice integrates three key components—best available research evidence, clinical expertise, and patient values/preferences—rather than relying exclusively on any single element in isolation, supporting individualized yet evidence-informed care."},{"id": 6367,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "By what age does a typically developing infant achieve good head control in prone/supported sitting?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "1 month"},{"key": "C","text": "3-4 months"},{"key": "D","text": "8 months"}],"correct": "C","explanation": "Head control is typically well established by 3-4 months of age."},{"id": 6368,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "By what age does a typically developing infant achieve independent sitting?","options": [{"key": "A","text": "18 months"},{"key": "B","text": "2-3 months"},{"key": "C","text": "6-8 months"},{"key": "D","text": "12-14 months"}],"correct": "C","explanation": "Independent, stable sitting without support is typically achieved by 6-8 months."},{"id": 6369,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant begin to pull to stand?","options": [{"key": "A","text": "18 months"},{"key": "B","text": "4-5 months"},{"key": "C","text": "8-10 months"},{"key": "D","text": "2-3 months"}],"correct": "C","explanation": "Pulling to stand using furniture support typically emerges around 8-10 months."},{"id": 6370,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child achieve independent walking?","options": [{"key": "A","text": "24 months"},{"key": "B","text": "6 months"},{"key": "C","text": "3 years"},{"key": "D","text": "12-15 months"}],"correct": "D","explanation": "Independent walking is typically achieved between 12-15 months, with a wide normal range."},{"id": 6371,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age can a typically developing child run, though with a stiff, immature pattern?","options": [{"key": "A","text": "6 months"},{"key": "B","text": "5 years"},{"key": "C","text": "18-24 months"},{"key": "D","text": "4 years"}],"correct": "C","explanation": "A rudimentary running pattern typically emerges around 18-24 months."},{"id": 6372,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "By what age does a typically developing child achieve reciprocal stair climbing (alternating feet)?","options": [{"key": "A","text": "18 months"},{"key": "B","text": "12 months"},{"key": "C","text": "3-4 years"},{"key": "D","text": "6 years"}],"correct": "C","explanation": "Reciprocal (alternating foot) stair climbing typically develops around 3-4 years, before which children mark time on each step."},{"id": 6373,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age can a typically developing child hop on one foot?","options": [{"key": "A","text": "2 years"},{"key": "B","text": "4 years"},{"key": "C","text": "6 years"},{"key": "D","text": "12 months"}],"correct": "B","explanation": "Hopping on one foot several times typically emerges around 4 years of age."},{"id": 6374,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "At what age does the palmar grasp reflex typically integrate (disappear)?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "3-6 months"},{"key": "C","text": "2 years"},{"key": "D","text": "Birth"}],"correct": "B","explanation": "The palmar grasp reflex, present at birth, typically integrates by 3-6 months as voluntary grasp develops."},{"id": 6375,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does an infant typically develop a voluntary/mature pincer grasp?","options": [{"key": "A","text": "2 months"},{"key": "B","text": "9-12 months"},{"key": "C","text": "3 years"},{"key": "D","text": "18 months"}],"correct": "B","explanation": "Fine pincer grasp (thumb-index finger tip-to-tip) typically develops by 9-12 months."},{"id": 6376,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age does an infant typically develop a raking grasp for small objects?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "6-8 months"},{"key": "C","text": "1 month"},{"key": "D","text": "2 years"}],"correct": "B","explanation": "The immature raking grasp (using fingers against palm without thumb opposition) typically appears around 6-8 months, preceding the mature pincer grasp."},{"id": 6377,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "By what age does an infant typically reach for objects with a controlled voluntary reach?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "4-5 months"},{"key": "C","text": "1 month"},{"key": "D","text": "9 months"}],"correct": "B","explanation": "Controlled, purposeful voluntary reaching typically develops around 4-5 months."},{"id": 6378,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does an infant typically transfer objects from one hand to another?","options": [{"key": "A","text": "5-6 months"},{"key": "B","text": "9 months"},{"key": "C","text": "12 months"},{"key": "D","text": "1 month"}],"correct": "A","explanation": "Hand-to-hand object transfer typically develops around 5-6 months."},{"id": 6379,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a child typically build a tower of 2 cubes?","options": [{"key": "A","text": "3 years"},{"key": "B","text": "12-15 months"},{"key": "C","text": "2 years"},{"key": "D","text": "6 months"}],"correct": "B","explanation": "Building a 2-cube tower is typically achieved around 12-15 months."},{"id": 6380,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a child typically build a tower of 6-8 cubes?","options": [{"key": "A","text": "6 years"},{"key": "B","text": "12 months"},{"key": "C","text": "4 years"},{"key": "D","text": "2 years"}],"correct": "D","explanation": "Building a tower of 6-8 cubes is typically achieved around 2 years of age."},{"id": 6381,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age does a child typically copy a circle when drawing?","options": [{"key": "A","text": "5 years"},{"key": "B","text": "7 years"},{"key": "C","text": "1 year"},{"key": "D","text": "3 years"}],"correct": "D","explanation": "Copying a circle is a typical fine motor/visual-perceptual milestone achieved around 3 years."},{"id": 6382,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "By what age does a child typically copy a square when drawing?","options": [{"key": "A","text": "1 year"},{"key": "B","text": "4-5 years"},{"key": "C","text": "2 years"},{"key": "D","text": "6 months"}],"correct": "B","explanation": "Copying a square is a more complex visual-motor task typically achieved around 4-5 years."},{"id": 6383,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant produce social smile?","options": [{"key": "A","text": "At birth"},{"key": "B","text": "4 months"},{"key": "C","text": "6 months"},{"key": "D","text": "6-8 weeks"}],"correct": "D","explanation": "Social smiling (in response to social interaction) typically emerges around 6-8 weeks of age."},{"id": 6384,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant begin to babble (repetitive consonant-vowel sounds)?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "2 years"},{"key": "C","text": "1 month"},{"key": "D","text": "6-9 months"}],"correct": "D","explanation": "Babbling with repetitive syllables (e.g., 'ba-ba', 'da-da') typically begins around 6-9 months."},{"id": 6385,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child speak their first meaningful words?","options": [{"key": "A","text": "1 month"},{"key": "B","text": "2 years"},{"key": "C","text": "10-14 months"},{"key": "D","text": "3 years"}],"correct": "C","explanation": "First meaningful words are typically spoken between 10-14 months."},{"id": 6386,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age does a typically developing child combine two words into simple phrases?","options": [{"key": "A","text": "18-24 months"},{"key": "B","text": "3 years"},{"key": "C","text": "6 months"},{"key": "D","text": "4 years"}],"correct": "A","explanation": "Two-word combinations/phrases typically emerge between 18-24 months."},{"id": 6387,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "By what age does a typically developing child use complete, grammatically appropriate sentences?","options": [{"key": "A","text": "8 years"},{"key": "B","text": "3-4 years"},{"key": "C","text": "6 years"},{"key": "D","text": "1 year"}],"correct": "B","explanation": "More complete, grammatically structured sentences typically develop by 3-4 years."},{"id": 6388,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does an infant typically achieve rolling from prone to supine?","options": [{"key": "A","text": "4-5 months"},{"key": "B","text": "8 months"},{"key": "C","text": "1 month"},{"key": "D","text": "12 months"}],"correct": "A","explanation": "Rolling prone to supine typically develops around 4-5 months, often preceding supine to prone rolling."},{"id": 6389,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does an infant typically achieve rolling from supine to prone?","options": [{"key": "A","text": "1 month"},{"key": "B","text": "4 months"},{"key": "C","text": "6 months"},{"key": "D","text": "12 months"}],"correct": "C","explanation": "Rolling supine to prone typically develops slightly later, around 6 months."},{"id": 6390,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does an infant typically begin creeping/crawling on hands and knees?","options": [{"key": "A","text": "8-10 months"},{"key": "B","text": "14 months"},{"key": "C","text": "2 months"},{"key": "D","text": "4 months"}],"correct": "A","explanation": "Reciprocal creeping/crawling on hands and knees typically develops around 8-10 months."},{"id": 6391,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age does an infant typically achieve cruising (walking while holding onto furniture)?","options": [{"key": "A","text": "3 months"},{"key": "B","text": "18 months"},{"key": "C","text": "6 months"},{"key": "D","text": "9-11 months"}],"correct": "D","explanation": "Cruising along furniture typically develops around 9-11 months, preceding independent walking."},{"id": 6392,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "By what age does an infant typically develop the ability to sit independently without hand support for balance?","options": [{"key": "A","text": "4 months"},{"key": "B","text": "12 months"},{"key": "C","text": "7-8 months"},{"key": "D","text": "2 months"}],"correct": "C","explanation": "Fully independent sitting without needing hands for support ('sitting with pivot') typically develops around 7-8 months."},{"id": 6393,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child kick a ball forward?","options": [{"key": "A","text": "6 months"},{"key": "B","text": "18-24 months"},{"key": "C","text": "4 years"},{"key": "D","text": "3 years"}],"correct": "B","explanation": "Kicking a ball forward while standing typically develops around 18-24 months."},{"id": 6394,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child throw a ball overhand with some direction?","options": [{"key": "A","text": "4 years"},{"key": "B","text": "6 years"},{"key": "C","text": "2 years"},{"key": "D","text": "6 months"}],"correct": "C","explanation": "Overhand throwing with some directional control typically emerges around 2 years, with continued refinement through childhood."},{"id": 6395,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child pedal a tricycle?","options": [{"key": "A","text": "7 years"},{"key": "B","text": "5 years"},{"key": "C","text": "18 months"},{"key": "D","text": "3 years"}],"correct": "D","explanation": "Tricycle pedaling typically develops around 3 years of age."},{"id": 6396,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age does a typically developing child ride a bicycle with training wheels removed?","options": [{"key": "A","text": "10 years"},{"key": "B","text": "2 years"},{"key": "C","text": "3 years"},{"key": "D","text": "5-7 years"}],"correct": "D","explanation": "Independent two-wheel bicycle riding typically develops around 5-7 years, varying with practice/exposure."},{"id": 6397,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Moro (startle) reflex is elicited by:","options": [{"key": "A","text": "Placing pressure on the palm"},{"key": "B","text": "Sudden change in head position or loud noise/sudden movement"},{"key": "C","text": "Stroking the sole of the foot"},{"key": "D","text": "Stroking the cheek"}],"correct": "B","explanation": "Moro reflex is elicited by sudden head extension/drop or loud stimulus, producing arm abduction/extension followed by adduction."},{"id": 6398,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Moro reflex typically integrates (disappears) by what age?","options": [{"key": "A","text": "4-6 months"},{"key": "B","text": "Birth"},{"key": "C","text": "2 years"},{"key": "D","text": "12 months"}],"correct": "A","explanation": "The Moro reflex, present at birth, typically integrates by 4-6 months of age."},{"id": 6399,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Asymmetric Tonic Neck Reflex (ATNR) is elicited by:","options": [{"key": "A","text": "Stroking the sole of the foot"},{"key": "B","text": "Placing the infant prone"},{"key": "C","text": "Turning the infant's head to one side, causing ipsilateral limb extension and contralateral limb flexion ('fencer' posture)"},{"key": "D","text": "Sudden loud noise"}],"correct": "C","explanation": "ATNR produces the classic 'fencing' posture with ipsilateral arm/leg extension and contralateral flexion when the head is turned."},{"id": 6400,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Persistence of the ATNR beyond the typical integration age is significant because it can interfere with:","options": [{"key": "A","text": "Having no functional significance"},{"key": "B","text": "Midline hand use, rolling, and symmetric development"},{"key": "C","text": "Only affecting speech development"},{"key": "D","text": "Only affecting lower limb function"}],"correct": "B","explanation": "Persistent ATNR can interfere with important developmental skills requiring midline orientation, symmetric posture, and rolling."},{"id": 6401,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "The ATNR typically integrates by what age?","options": [{"key": "A","text": "4-6 months"},{"key": "B","text": "Birth"},{"key": "C","text": "12 months"},{"key": "D","text": "2 years"}],"correct": "A","explanation": "ATNR typically integrates by 4-6 months as more mature postural control develops."},{"id": 6402,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Symmetric Tonic Neck Reflex (STNR) produces which pattern with neck flexion?","options": [{"key": "A","text": "Arm extension with leg flexion"},{"key": "B","text": "Arm flexion with leg extension"},{"key": "C","text": "Only affects the trunk, not limbs"},{"key": "D","text": "No change in limb position"}],"correct": "B","explanation": "STNR with neck flexion causes arm flexion and leg extension; neck extension causes the opposite (arm extension, leg flexion)."},{"id": 6403,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Persistent STNR can interfere with development of which important motor milestone?","options": [{"key": "A","text": "Sitting balance"},{"key": "B","text": "Creeping/crawling on hands and knees"},{"key": "C","text": "Head control"},{"key": "D","text": "Rolling"}],"correct": "B","explanation": "Persistent STNR particularly interferes with the reciprocal, symmetric coordination needed for effective quadruped creeping."},{"id": 6404,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The rooting reflex is elicited by:","options": [{"key": "A","text": "Sudden loud noise"},{"key": "B","text": "Stroking the corner of the infant's mouth/cheek, causing head turn toward the stimulus"},{"key": "C","text": "Placing the infant prone"},{"key": "D","text": "Stroking the sole of the foot"}],"correct": "B","explanation": "Rooting reflex causes the infant to turn toward and open the mouth in response to perioral/cheek stimulation, supporting feeding."},{"id": 6405,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The rooting reflex typically integrates by what age?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "Birth"},{"key": "C","text": "2 years"},{"key": "D","text": "3-4 months"}],"correct": "D","explanation": "Rooting reflex typically integrates by 3-4 months as voluntary feeding behavior develops."},{"id": 6406,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "The sucking reflex is present from birth and typically integrates (becomes voluntary) by what age?","options": [{"key": "A","text": "2-3 months"},{"key": "B","text": "12 months"},{"key": "C","text": "Birth"},{"key": "D","text": "2 years"}],"correct": "A","explanation": "The reflexive sucking pattern gradually becomes more voluntary/mature by 2-3 months of age."},{"id": 6407,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The palmar grasp reflex is elicited by:","options": [{"key": "A","text": "Sudden loud noise"},{"key": "B","text": "Stroking the sole of the foot"},{"key": "C","text": "Stroking the cheek"},{"key": "D","text": "Placing pressure/stroking the palm, causing finger flexion/grasp"}],"correct": "D","explanation": "Palmar grasp reflex causes reflexive finger flexion/grasping in response to palmar pressure/stroking."},{"id": 6408,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The plantar grasp reflex is elicited by:","options": [{"key": "A","text": "Placing pressure on the heel"},{"key": "B","text": "Stroking the lateral sole from heel to toe"},{"key": "C","text": "Placing pressure on the sole of the foot near the toes, causing toe flexion/curling"},{"key": "D","text": "Sudden loud noise"}],"correct": "C","explanation": "Plantar grasp reflex causes toe flexion/curling in response to pressure applied to the ball of the foot."},{"id": 6409,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The plantar grasp reflex typically integrates by what age?","options": [{"key": "A","text": "Birth"},{"key": "B","text": "2 years"},{"key": "C","text": "9-12 months"},{"key": "D","text": "2 months"}],"correct": "C","explanation": "Plantar grasp reflex typically integrates by 9-12 months, before independent standing/walking."},{"id": 6410,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The positive supporting reaction refers to:","options": [{"key": "A","text": "Reflexive lower limb extension/stiffening when the sole contacts a supporting surface"},{"key": "B","text": "A reflex only present in the upper limb"},{"key": "C","text": "A reflex unrelated to weight bearing"},{"key": "D","text": "Reflexive flexion of the lower limb upon contact with a surface"}],"correct": "A","explanation": "Positive supporting reaction produces reflexive lower limb extension when the foot contacts a surface, contributing to early standing support."},{"id": 6411,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "The Babinski reflex (plantar reflex causing toe extension/fanning) is considered:","options": [{"key": "A","text": "A normal finding in infants, becoming abnormal if persisting beyond approximately 12-24 months"},{"key": "B","text": "Only relevant in adults"},{"key": "C","text": "Never present in infants"},{"key": "D","text": "Always abnormal at any age including infancy"}],"correct": "A","explanation": "An extensor plantar response (Babinski) is a normal finding in infants due to immature corticospinal tract myelination, becoming a pathological sign if it persists well beyond the first one to two years."},{"id": 6412,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Galant reflex (trunk incurvation) is elicited by:","options": [{"key": "A","text": "Sudden loud noise"},{"key": "B","text": "Placing the infant supine"},{"key": "C","text": "Stroking the sole of the foot"},{"key": "D","text": "Stroking one side of the infant's back paravertebrally, causing lateral trunk flexion toward the stimulated side"}],"correct": "D","explanation": "Galant reflex causes the infant to laterally flex the trunk toward the side of paraspinal stroking stimulus."},{"id": 6413,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Galant reflex typically integrates by what age?","options": [{"key": "A","text": "4-6 months"},{"key": "B","text": "2 years"},{"key": "C","text": "Birth"},{"key": "D","text": "12 months"}],"correct": "A","explanation": "The Galant reflex typically integrates by 4-6 months of age."},{"id": 6414,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The parachute reaction (protective extension of arms when tilted forward) typically emerges by what age and persists throughout life?","options": [{"key": "A","text": "Birth"},{"key": "B","text": "5 years"},{"key": "C","text": "2 years"},{"key": "D","text": "6-9 months"}],"correct": "D","explanation": "The forward parachute reaction typically emerges around 6-9 months and, unlike primitive reflexes, persists as a protective reaction throughout life."},{"id": 6415,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Righting reactions, which help maintain normal head/body alignment, typically emerge in which developmental sequence relative to primitive reflexes?","options": [{"key": "A","text": "Are present from birth identically to primitive reflexes"},{"key": "B","text": "Never develop in typically developing infants"},{"key": "C","text": "Emerge as primitive reflexes integrate, supporting more mature postural control"},{"key": "D","text": "Emerge simultaneously with primitive reflexes with no developmental relationship"}],"correct": "C","explanation": "Righting reactions typically emerge as primitive reflexes integrate, representing the maturation toward more voluntary, adaptive postural control mechanisms."},{"id": 6416,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Equilibrium reactions, which help maintain balance during postural challenges, typically continue to develop and refine:","options": [{"key": "A","text": "Only relevant for adult balance, not pediatric development"},{"key": "B","text": "Never develop in any child"},{"key": "C","text": "Only during the first month of life"},{"key": "D","text": "Throughout early childhood and beyond, supporting increasingly complex balance demands"}],"correct": "D","explanation": "Equilibrium reactions continue developing and refining through early childhood, supporting increasingly complex balance control as the child's motor repertoire expands."},{"id": 6417,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The landau reaction/reflex, seen in prone suspension, is characterized by:","options": [{"key": "A","text": "No response in this test position"},{"key": "B","text": "A reflex that persists unchanged throughout life"},{"key": "C","text": "Head and trunk extension with the infant held horizontally prone in the air"},{"key": "D","text": "Head and trunk flexion in this position"}],"correct": "C","explanation": "The Landau reaction shows head/trunk extension when an infant is suspended prone in the air, typically emerging around 3-4 months and integrating by around 2 years."},{"id": 6418,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant achieve good visual tracking/following of an object across midline?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "Birth"},{"key": "C","text": "2-3 months"},{"key": "D","text": "6 months"}],"correct": "C","explanation": "Smooth visual tracking across midline typically develops by 2-3 months."},{"id": 6419,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant recognize and show preference for their primary caregiver's face?","options": [{"key": "A","text": "Birth"},{"key": "B","text": "2-3 months"},{"key": "C","text": "12 months"},{"key": "D","text": "6 months"}],"correct": "B","explanation": "Facial recognition and preference for primary caregivers typically develops by 2-3 months."},{"id": 6420,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child engage in parallel play (playing alongside but not directly interacting with peers)?","options": [{"key": "A","text": "2-3 years"},{"key": "B","text": "5 years"},{"key": "C","text": "6 months"},{"key": "D","text": "12 months"}],"correct": "A","explanation": "Parallel play, where children play near but not directly with each other, typically characterizes the toddler period around 2-3 years."},{"id": 6421,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age does a typically developing child engage in cooperative/interactive play with peers?","options": [{"key": "A","text": "6 years"},{"key": "B","text": "3-4 years"},{"key": "C","text": "1 year"},{"key": "D","text": "2 years"}],"correct": "B","explanation": "More cooperative, interactive play with shared goals typically develops by 3-4 years, building on earlier parallel play."},{"id": 6422,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "By what age does a typically developing child achieve independent feeding with a spoon (with some spilling)?","options": [{"key": "A","text": "2 years"},{"key": "B","text": "3 months"},{"key": "C","text": "12-15 months"},{"key": "D","text": "6 months"}],"correct": "C","explanation": "Self-feeding with a spoon (though with some spilling initially) typically develops around 12-15 months."},{"id": 6423,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child achieve independent dressing (simple garments)?","options": [{"key": "A","text": "1 year"},{"key": "B","text": "6 years"},{"key": "C","text": "2 years"},{"key": "D","text": "3-4 years"}],"correct": "D","explanation": "Independent dressing of simple garments typically develops around 3-4 years, with more complex fastenings developing later."},{"id": 6424,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child achieve daytime bladder control?","options": [{"key": "A","text": "1 year"},{"key": "B","text": "5 years"},{"key": "C","text": "2-3 years"},{"key": "D","text": "6 months"}],"correct": "C","explanation": "Daytime bladder control typically develops around 2-3 years, with nighttime control often achieved somewhat later."},{"id": 6425,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which developmental principle describes the general progression of motor development from head to tail?","options": [{"key": "A","text": "Cephalocaudal development"},{"key": "B","text": "Mass to specific development"},{"key": "C","text": "Proximodistal development"},{"key": "D","text": "Simple to complex development"}],"correct": "A","explanation": "Cephalocaudal principle describes the head-to-tail progression of motor control development (e.g., head control before trunk/leg control)."},{"id": 6426,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "Which developmental principle describes the general progression of motor development from central body parts to peripheral extremities?","options": [{"key": "A","text": "Mass to specific development"},{"key": "B","text": "Cephalocaudal development"},{"key": "C","text": "Proximodistal development"},{"key": "D","text": "None of these principles apply to motor development"}],"correct": "C","explanation": "Proximodistal principle describes development progressing from central/proximal body control (trunk, shoulders) toward more distal control (hands, fingers)."},{"id": 6427,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "Which developmental principle describes progression from generalized, mass movement patterns toward more specific, refined, isolated movements?","options": [{"key": "A","text": "Proximodistal development only"},{"key": "B","text": "A principle unrelated to motor development"},{"key": "C","text": "Mass to specific development"},{"key": "D","text": "Cephalocaudal development only"}],"correct": "C","explanation": "Development progresses from generalized whole-body mass movement responses toward increasingly specific, refined, isolated motor control."},{"id": 6428,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "The Denver Developmental Screening Test (DDST/Denver II) assesses development across which domains?","options": [{"key": "A","text": "Only gross motor development"},{"key": "B","text": "Only language development"},{"key": "C","text": "Only cognitive development"},{"key": "D","text": "Personal-social, fine motor-adaptive, language, and gross motor"}],"correct": "D","explanation": "Denver II is a widely used developmental screening tool assessing four domains: personal-social, fine motor-adaptive, language, and gross motor."},{"id": 6429,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the wide normal range seen in achieving developmental milestones?","options": [{"key": "A","text": "Developmental milestone timing has no normal variation whatsoever"},{"key": "B","text": "Any deviation from the average milestone age indicates a significant pathological condition"},{"key": "C","text": "Normal development shows considerable individual variation, so isolated mild delays should be interpreted within the broader developmental context"},{"key": "D","text": "All children must achieve every milestone at the exact same age or be considered abnormal"}],"correct": "C","explanation": "Developmental milestones show a normal range of variation; isolated mild delays require careful contextual interpretation rather than immediate assumption of pathology."},{"id": 6430,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "'Red flags' warranting further developmental evaluation include which of the following?","options": [{"key": "A","text": "Normal variation in temperament"},{"key": "B","text": "Typical age-appropriate shyness with strangers"},{"key": "C","text": "Loss of previously acquired skills (regression), or significant delay across multiple domains"},{"key": "D","text": "Achieving a milestone slightly later than the average age within the normal range"}],"correct": "C","explanation": "Developmental regression (loss of previously acquired skills) and significant multi-domain delay are important red flags warranting prompt further evaluation."},{"id": 6431,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "By what age does a typically developing infant achieve adequate head control to allow supported sitting without significant head lag?","options": [{"key": "A","text": "4 months"},{"key": "B","text": "8 months"},{"key": "C","text": "1 month"},{"key": "D","text": "12 months"}],"correct": "A","explanation": "By 4 months, head control is typically sufficient to prevent significant head lag when pulled to sit."},{"id": 6432,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "By what age does an infant typically begin to bear weight on their legs when held in standing (bounce/dance reflex-like behavior)?","options": [{"key": "A","text": "Birth"},{"key": "B","text": "3-4 months"},{"key": "C","text": "8 months"},{"key": "D","text": "12 months"}],"correct": "B","explanation": "Infants typically begin to enjoy bearing some weight/bouncing when held supported in standing around 3-4 months."},{"id": 6433,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant achieve protective extension of the arms sideways (lateral propping) when seated?","options": [{"key": "A","text": "10 months"},{"key": "B","text": "2 months"},{"key": "C","text": "14 months"},{"key": "D","text": "6-7 months"}],"correct": "D","explanation": "Lateral protective extension/propping reactions in sitting typically develop around 6-7 months, before posterior protective extension."},{"id": 6434,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant achieve protective extension of the arms backward (posterior propping) when seated?","options": [{"key": "A","text": "14 months"},{"key": "B","text": "2 months"},{"key": "C","text": "6 months"},{"key": "D","text": "9-10 months"}],"correct": "D","explanation": "Posterior protective extension typically develops later than lateral, around 9-10 months, completing the full range of sitting protective reactions."},{"id": 6435,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child typically demonstrate an established hand dominance/preference?","options": [{"key": "A","text": "8 years"},{"key": "B","text": "1 year"},{"key": "C","text": "3-4 years, though some prefer one hand earlier"},{"key": "D","text": "At birth"}],"correct": "C","explanation": "Consistent hand dominance is typically well-established by 3-4 years, though some infants show earlier hand preferences."},{"id": 6436,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "By what age does a typically developing infant demonstrate object permanence (understanding that an object continues to exist even when out of sight)?","options": [{"key": "A","text": "1 month"},{"key": "B","text": "4 months"},{"key": "C","text": "8-9 months"},{"key": "D","text": "18 months"}],"correct": "C","explanation": "Object permanence, a key Piagetian cognitive milestone, typically develops around 8-9 months."},{"id": 6437,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "According to Piaget's theory, the sensorimotor stage of cognitive development occurs during approximately which age range?","options": [{"key": "A","text": "7 to 11 years"},{"key": "B","text": "11 years and older"},{"key": "C","text": "Birth to 2 years"},{"key": "D","text": "2 to 7 years"}],"correct": "C","explanation": "Piaget's sensorimotor stage spans birth to approximately 2 years, characterized by learning through sensory experience and motor actions."},{"id": 6438,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing child achieve independent, safe stair descent (not just ascent)?","options": [{"key": "A","text": "12 months"},{"key": "B","text": "3-4 years, slightly later than ascent typically"},{"key": "C","text": "6 years"},{"key": "D","text": "6 months"}],"correct": "B","explanation": "Safe stair descent typically develops slightly after ascent, with reciprocal descent typically achieved around 3-4 years."},{"id": 6439,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant achieve independent standing without support?","options": [{"key": "A","text": "18 months"},{"key": "B","text": "6 months"},{"key": "C","text": "10-12 months"},{"key": "D","text": "2 months"}],"correct": "C","explanation": "Independent standing without any support typically develops around 10-12 months, shortly before independent walking."},{"id": 6440,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "By what age does a typically developing infant achieve a controlled, purposeful transition from sitting to prone/quadruped position?","options": [{"key": "A","text": "2 months"},{"key": "B","text": "12 months"},{"key": "C","text": "7-8 months"},{"key": "D","text": "4 months"}],"correct": "C","explanation": "Controlled transitional movements between sitting and prone/quadruped typically develop around 7-8 months."},{"id": 6441,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "Which of the following best describes the concept of 'developmental sequence' relevant to pediatric physiotherapy assessment/intervention planning?","options": [{"key": "A","text": "Motor skills typically develop in a predictable, though somewhat individually variable, sequential order building upon previously acquired abilities"},{"key": "B","text": "All children achieve every motor skill in an identical, fixed order with zero variation"},{"key": "C","text": "Developmental sequence has no relevance to pediatric physiotherapy assessment or treatment planning"},{"key": "D","text": "Motor skills develop in a completely random order with no predictable sequence whatsoever"}],"correct": "A","explanation": "Understanding the typical developmental sequence (while allowing for normal individual variation) is fundamental to pediatric physiotherapy assessment and intervention planning."},{"id": 6442,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Primitive reflexes are best understood as:","options": [{"key": "A","text": "Reflexes that persist unchanged throughout the entire lifespan in all individuals"},{"key": "B","text": "Voluntary movements learned through practice"},{"key": "C","text": "Brainstem-mediated, involuntary responses present in infancy that typically integrate as higher cortical control develops"},{"key": "D","text": "Responses exclusively mediated by the cerebral cortex"}],"correct": "C","explanation": "Primitive reflexes are subcortically (brainstem) mediated involuntary responses present from birth, typically integrating as cortical control matures."},{"id": 6443,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Persistence of primitive reflexes beyond their typical integration age is clinically significant because it may indicate:","options": [{"key": "A","text": "Always indicates normal development with no clinical significance"},{"key": "B","text": "Delayed central nervous system maturation or underlying neurological pathology"},{"key": "C","text": "A finding of no relevance to physiotherapy assessment"},{"key": "D","text": "Only relevant to assess muscle strength directly"}],"correct": "B","explanation": "Persistent primitive reflexes beyond expected integration age can suggest delayed CNS maturation or underlying neurological impairment, informing further developmental assessment."},{"id": 6444,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The Moro reflex assessment technique typically involves:","options": [{"key": "A","text": "Stroking the sole of the foot"},{"key": "B","text": "Supporting the infant's head/trunk and then allowing brief controlled head drop, or a sudden loud noise"},{"key": "C","text": "Turning the infant's head to one side"},{"key": "D","text": "Applying pressure to the palm"}],"correct": "B","explanation": "Moro reflex is classically elicited via sudden controlled head drop (with support) or a sudden loud stimulus, producing arm abduction/extension then adduction."},{"id": 6445,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "An asymmetric Moro reflex response (one side showing reduced/absent response) may suggest:","options": [{"key": "A","text": "Possible brachial plexus injury, fracture, or other unilateral pathology on the affected side"},{"key": "B","text": "Always indicating bilateral cerebral palsy"},{"key": "C","text": "A normal finding requiring no further evaluation"},{"key": "D","text": "Only relevant to assess hearing function"}],"correct": "A","explanation": "Asymmetric Moro response should prompt evaluation for possible unilateral pathology such as brachial plexus injury, clavicle fracture, or hemiparesis."},{"id": 6446,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "The rooting reflex, in addition to its role in reflexive orientation for feeding, when persistently strong beyond typical integration age, may be a red flag associated with which broader developmental concern?","options": [{"key": "A","text": "Exclusively related to visual development"},{"key": "B","text": "General oral-motor/feeding developmental delay warranting further assessment"},{"key": "C","text": "No clinical significance regardless of persistence"},{"key": "D","text": "Only relevant to hearing assessment"}],"correct": "B","explanation": "Persistent strong rooting beyond typical integration age can be one indicator prompting broader assessment of oral-motor and general developmental status."},{"id": 6447,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "The ATNR test position involves:","options": [{"key": "A","text": "Infant held in vertical suspension"},{"key": "B","text": "Infant supine, examiner passively turning the head to one side and observing limb response"},{"key": "C","text": "Infant seated with trunk support"},{"key": "D","text": "Infant prone with head lifted"}],"correct": "B","explanation": "ATNR is tested with the infant supine, passively rotating the head to each side and observing the characteristic 'fencing' limb response."},{"id": 6448,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "A 'obligatory' ATNR response (one from which the infant cannot break free/move out of) beyond the typical integration period is considered:","options": [{"key": "A","text": "A normal variant requiring no further assessment"},{"key": "B","text": "Only relevant for assessing hearing"},{"key": "C","text": "A pathological finding suggesting significant neurological impairment"},{"key": "D","text": "A finding exclusively related to visual tracking ability"}],"correct": "C","explanation": "An obligatory (rather than typical transient, non-obligatory) ATNR response persisting is considered a significant pathological finding, often associated with conditions like cerebral palsy."},{"id": 6449,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The STNR test position for assessing the response to neck flexion/extension typically involves:","options": [{"key": "A","text": "Infant seated independently"},{"key": "B","text": "Infant supine with head turned to one side"},{"key": "C","text": "Infant in quadruped/all-fours position, examiner passively flexing/extending the neck and observing limb response"},{"key": "D","text": "Infant held in vertical suspension"}],"correct": "C","explanation": "STNR is typically assessed with the infant in a quadruped position, observing limb responses to passive neck flexion (arms flex, legs extend) and extension (arms extend, legs flex)."},{"id": 6450,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following primitive reflexes, if persistently obligatory, would be expected to particularly interfere with independent sitting balance?","options": [{"key": "A","text": "Sucking reflex"},{"key": "B","text": "Palmar grasp reflex"},{"key": "C","text": "Rooting reflex"},{"key": "D","text": "Symmetric Tonic Labyrinthine Reflex (STLR) affecting tone based on head position in space"}],"correct": "D","explanation": "Persistent STLR (tone changes based on head position relative to gravity, extensor tone increasing in supine and flexor tone in prone) can significantly interfere with sitting balance and postural control."},{"id": 6451,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "The Symmetric Tonic Labyrinthine Reflex (STLR) in supine position typically produces:","options": [{"key": "A","text": "No change in overall body tone"},{"key": "B","text": "Increased extensor tone throughout the body"},{"key": "C","text": "Only affects the upper limbs, never the trunk/lower limbs"},{"key": "D","text": "Increased flexor tone throughout the body"}],"correct": "B","explanation": "STLR in supine position is associated with increased extensor tone throughout the body, based on labyrinthine/vestibular input related to head position."},{"id": 6452,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Symmetric Tonic Labyrinthine Reflex (STLR) in prone position typically produces:","options": [{"key": "A","text": "Only affects the lower limbs, never the upper limbs/trunk"},{"key": "B","text": "Increased flexor tone throughout the body"},{"key": "C","text": "Increased extensor tone throughout the body"},{"key": "D","text": "No change in overall body tone"}],"correct": "B","explanation": "STLR in prone position is associated with increased flexor tone throughout the body, contrasting with the extensor pattern seen in supine."},{"id": 6453,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "The positive supporting reaction, if it persists obligatorily beyond the typical integration period, can interfere with development of:","options": [{"key": "A","text": "Speech and language development specifically"},{"key": "B","text": "Normal reciprocal stepping/walking pattern due to excessive lower limb extensor stiffening"},{"key": "C","text": "Visual tracking ability specifically"},{"key": "D","text": "Upper limb reaching ability specifically"}],"correct": "B","explanation": "Persistent obligatory positive supporting reaction can cause excessive lower limb extensor stiffening, interfering with the normal reciprocal flexion-extension pattern needed for typical walking."},{"id": 6454,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Assessment of primitive reflexes forms part of a comprehensive neurological examination in infants primarily to help:","options": [{"key": "A","text": "Replace the need for any other developmental assessment component"},{"key": "B","text": "Identify potential early indicators of neurological impairment and inform appropriate early intervention referral"},{"key": "C","text": "Only relevant for infants born at term, never for premature infants"},{"key": "D","text": "Only assess visual function"}],"correct": "B","explanation": "Primitive reflex assessment is one component (alongside tone, posture, and milestone assessment) of comprehensive infant neurological examination, helping identify early indicators warranting further monitoring or intervention referral."},{"id": 6455,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration when interpreting primitive reflex findings in premature infants?","options": [{"key": "A","text": "Corrected age adjustment is only relevant for gross motor milestones, never for reflex assessment"},{"key": "B","text": "Premature infants should always be assessed using chronological age with no adjustment"},{"key": "C","text": "Primitive reflexes are irrelevant to assessment of premature infants"},{"key": "D","text": "Reflex maturation should generally be considered relative to corrected (adjusted) age rather than chronological age from birth"}],"correct": "D","explanation": "For premature infants, reflex maturation and developmental expectations should generally be considered relative to corrected (adjusted for prematurity) age rather than chronological age from birth, at least through early childhood."},{"id": 6456,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "The palmomental reflex (contraction of chin muscle upon stroking the palm), while more classically discussed in adult neurology, can be considered alongside other primitive reflexes; in infants, palmar-related reflexes are more relevant primarily as:","options": [{"key": "A","text": "A test exclusively used to assess hearing function"},{"key": "B","text": "The palmar grasp reflex, an important primitive reflex assessed in standard infant neurological examination"},{"key": "C","text": "Only relevant in geriatric neurological assessment"},{"key": "D","text": "A reflex with no relevance to pediatric assessment"}],"correct": "B","explanation": "In pediatric assessment, the palmar grasp reflex (rather than palmomental reflex, more an adult neurological sign) is the standard and clinically relevant primitive reflex assessed."},{"id": 6457,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes the general clinical approach when a persistent or obligatory primitive reflex is identified during pediatric assessment?","options": [{"key": "A","text": "Assuming this single isolated finding definitively diagnoses a specific condition without any further assessment"},{"key": "B","text": "Only relevant if identified before 1 month of age, with no significance if found later"},{"key": "C","text": "Considering it within the broader clinical picture (other developmental findings, tone, milestones) rather than in isolation, and referring for further evaluation as appropriate"},{"key": "D","text": "Ignoring the finding entirely if the infant appears otherwise well"}],"correct": "C","explanation": "Persistent/obligatory primitive reflex findings should be interpreted within the broader clinical context (other developmental/neurological findings) rather than in isolation, guiding appropriate further evaluation/referral."},{"id": 6458,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the general sequence relationship between integration of primitive reflexes and emergence of postural/righting reactions?","options": [{"key": "A","text": "Primitive reflexes always emerge after postural reactions are fully established"},{"key": "B","text": "Postural reactions are present from birth identically to primitive reflexes with no developmental progression"},{"key": "C","text": "These two categories of reflexes/reactions develop with no relationship to each other whatsoever"},{"key": "D","text": "Postural/righting reactions typically emerge and develop as primitive reflexes integrate, reflecting maturing cortical control"}],"correct": "D","explanation": "The typical developmental progression involves postural/righting/equilibrium reactions emerging and maturing as primitive reflexes integrate, reflecting the shift from brainstem-mediated to more cortically-controlled movement."},{"id": 6459,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding standardized primitive reflex assessment as part of a broader pediatric physiotherapy evaluation?","options": [{"key": "A","text": "Only relevant for infants suspected of having cerebral palsy, with no relevance to general developmental screening"},{"key": "B","text": "Should be integrated within a comprehensive assessment including tone, posture, milestone achievement, and functional observation, rather than used as a standalone diagnostic tool"},{"key": "C","text": "Reflex assessment should never be included in pediatric physiotherapy evaluation"},{"key": "D","text": "Primitive reflex testing alone provides a complete, sufficient neurological assessment with no need for any other component"}],"correct": "B","explanation": "Primitive reflex assessment is most valuable as one component integrated within a comprehensive pediatric evaluation, rather than relied upon as an isolated standalone diagnostic tool."},{"id": 6460,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "The 'Galant reflex' is sometimes discussed in relation to popular claims about its impact on later childhood function (e.g., bedwetting, scoliosis); from a clinical evidence perspective, physiotherapists should be aware that:","options": [{"key": "A","text": "While the reflex itself is a legitimate, well-described primitive reflex, some popular claims linking its retention to specific later childhood issues extend beyond current robust scientific evidence"},{"key": "B","text": "The Galant reflex has no legitimate clinical basis whatsoever as a primitive reflex"},{"key": "C","text": "This reflex is only relevant in adult neurological examination, never in pediatric assessment"},{"key": "D","text": "All popular claims about primitive reflex retention and later function are definitively proven by strong scientific evidence"}],"correct": "A","explanation": "While the Galant reflex is a legitimately described primitive reflex, clinicians should apply appropriate critical evaluation regarding some popular, less rigorously evidenced claims about specific causal links to particular later childhood functional issues."},{"id": 6461,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Hard","question": "Which of the following best describes an appropriate approach to explaining primitive reflex assessment findings to parents/caregivers during a pediatric physiotherapy evaluation?","options": [{"key": "A","text": "Avoiding any discussion of reflex assessment as it is considered too technical for parents to understand"},{"key": "B","text": "Providing clear, appropriately contextualized information about what the findings mean within the broader developmental picture, avoiding undue alarm while being honest about any concerns"},{"key": "C","text": "Providing no information whatsoever to parents regardless of findings"},{"key": "D","text": "Presenting isolated reflex findings as definitive proof of a specific severe diagnosis without appropriate context"}],"correct": "B","explanation": "Clear, appropriately contextualized communication with parents about reflex assessment findings—balancing honesty with avoiding undue alarm from isolated findings—is an important component of family-centered pediatric practice."},{"id": 6462,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the use of standardized infant neurological/reflex assessment tools (e.g., Dubowitz, Hammersmith Infant Neurological Examination)?","options": [{"key": "A","text": "Only relevant for research purposes, with no practical clinical utility"},{"key": "B","text": "Standardized tools eliminate any need for clinical judgment or interpretation"},{"key": "C","text": "Provide a structured, standardized approach supporting more consistent and comprehensive assessment of infant neurological status including reflexes, tone, and posture"},{"key": "D","text": "These tools have no evidence base and should never be used clinically"}],"correct": "C","explanation": "Standardized infant neurological assessment tools support consistent, comprehensive evaluation, though appropriate clinical judgment remains important in interpreting findings within the individual infant's broader context."},{"id": 6463,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the relevance of primitive reflex assessment specifically for infants identified as being at high biological/environmental risk (e.g., significant prematurity, perinatal complications)?","options": [{"key": "A","text": "High-risk infants should never undergo any neurological assessment given their fragility"},{"key": "B","text": "Assessment findings in high-risk infants provide no additional useful clinical information compared to typically developing infants"},{"key": "C","text": "Primitive reflex assessment is irrelevant for high-risk infants, only relevant for typically developing infants"},{"key": "D","text": "Particularly important for close, serial monitoring given increased risk of neurodevelopmental impairment in this population"}],"correct": "D","explanation": "Given increased neurodevelopmental risk, careful serial monitoring including primitive reflex assessment is particularly important for infants identified as high-risk (e.g., significant prematurity, perinatal complications), supporting early identification of any emerging concerns."},{"id": 6464,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following best describes the general concept of the 'startle' response pattern seen with the Moro reflex, distinguishing it as a specific reflex pattern rather than simply a general fright response?","options": [{"key": "A","text": "A response that shows significant variability in pattern between different typically developing infants"},{"key": "B","text": "An identical pattern to any general startle response seen at any age with no distinguishing characteristics"},{"key": "C","text": "A response that only involves the lower limbs, never the arms"},{"key": "D","text": "A specific, stereotyped bilateral pattern of arm abduction/extension followed by adduction/flexion, distinct from a general variable startle response"}],"correct": "D","explanation": "The Moro reflex describes a specific, relatively stereotyped bilateral limb response pattern (abduction/extension then adduction/flexion), distinguishing it as a defined primitive reflex rather than simply a generic variable startle reaction."},{"id": 6465,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding cultural/family variations in typical infant handling/positioning practices as relevant context for reflex and developmental assessment?","options": [{"key": "A","text": "Assuming identical developmental expectations regardless of any cultural/environmental context differences"},{"key": "B","text": "Awareness of cultural variations in typical practices (e.g., swaddling, carrying positions) can provide important context for interpreting developmental/reflex assessment findings appropriately"},{"key": "C","text": "Cultural considerations should never be discussed as part of family-centered pediatric practice"},{"key": "D","text": "Cultural practices have no relevance whatsoever to developmental assessment interpretation"}],"correct": "B","explanation": "Awareness of cultural and family variations in typical infant care practices provides important context for appropriately interpreting developmental and reflex assessment findings within family-centered pediatric physiotherapy practice."},{"id": 6466,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best describes the general relevance of reflex integration to the broader concept of 'sensory integration' sometimes referenced in pediatric therapy discussions?","options": [{"key": "A","text": "There is no theoretical relationship proposed between these concepts in any therapeutic framework"},{"key": "B","text": "Reflex integration and sensory integration are entirely identical concepts with no distinction"},{"key": "C","text": "Some therapeutic frameworks propose relationships between primitive reflex integration and broader sensory processing development, an area with varying degrees of supporting evidence depending on the specific claim"},{"key": "D","text": "All claims linking reflex integration to sensory processing are equally and definitively supported by strong scientific evidence"}],"correct": "C","explanation": "While some therapeutic frameworks propose relationships between primitive reflex integration and broader sensory processing/integration concepts, physiotherapists should apply appropriately critical evaluation of the strength of evidence supporting specific claims within this area."},{"id": 6467,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding documentation of primitive reflex assessment findings in pediatric physiotherapy practice?","options": [{"key": "A","text": "Clear, objective documentation of the specific reflex tested, response observed, and clinical interpretation supports appropriate communication and follow-up planning"},{"key": "B","text": "Only vague, non-specific documentation should be used to avoid any liability concerns"},{"key": "C","text": "Documentation of reflex findings is unnecessary and provides no clinical value"},{"key": "D","text": "Reflex findings should never be documented in the clinical record"}],"correct": "A","explanation": "Clear, objective documentation of primitive reflex assessment (specific reflex, observed response, clinical interpretation) supports appropriate communication with the broader care team and informs follow-up/monitoring planning."},{"id": 6468,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following best describes an appropriate integration of primitive reflex assessment findings into overall pediatric physiotherapy treatment planning?","options": [{"key": "A","text": "Reflex findings should be treated as entirely separate from and irrelevant to overall treatment planning"},{"key": "B","text": "Treatment should focus exclusively on directly 'treating' or attempting to forcibly integrate specific reflexes in isolation, without broader developmental consideration"},{"key": "C","text": "Primitive reflex status has no bearing whatsoever on appropriate positioning or handling recommendations"},{"key": "D","text": "Informing understanding of the infant's current neuromotor status and potentially guiding specific handling/positioning or intervention strategies within a broader, holistic treatment approach"}],"correct": "D","explanation": "Primitive reflex assessment findings should inform a holistic understanding of the infant's neuromotor status, appropriately integrated within broader developmentally-focused treatment planning, rather than treated as an isolated target for direct intervention."},{"id": 6469,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the reliability of primitive reflex assessment, given that infant state (e.g., alertness, hunger, fatigue) can influence responses?","options": [{"key": "A","text": "Reflex assessment should always be performed regardless of infant state, with no consideration of potential state-related influence on results"},{"key": "B","text": "Infant behavioral state should be considered and ideally optimized when performing reflex assessment, as it can significantly influence response quality/presence"},{"key": "C","text": "Infant state has no influence whatsoever on reflex assessment findings"},{"key": "D","text": "Only the examiner's technique matters, with infant state being entirely irrelevant to assessment reliability"}],"correct": "B","explanation": "Infant behavioral state (alertness, hunger, fatigue) can significantly influence reflex response quality, making consideration of and ideally optimizing infant state an important factor in obtaining reliable assessment findings."},{"id": 6470,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the general clinical significance of finding a completely absent (rather than simply diminished) primitive reflex response at an age when it would typically still be present?","options": [{"key": "A","text": "Always indicates completely normal development requiring no further consideration"},{"key": "B","text": "May warrant further evaluation for possible underlying neurological or musculoskeletal pathology (e.g., peripheral nerve injury, significant CNS depression)"},{"key": "C","text": "Only relevant if the infant is also failing to gain weight appropriately, with no other clinical relevance"},{"key": "D","text": "Absent reflexes have no clinical significance at any age"}],"correct": "B","explanation": "A completely absent primitive reflex at an age when it would typically be present (rather than the reflex being appropriately integrated at an expected later age) warrants further evaluation for possible underlying pathology."},{"id": 6471,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Hard","question": "Which of the following best summarizes the overall clinical value of primitive reflex assessment within comprehensive pediatric physiotherapy practice?","options": [{"key": "A","text": "Has no clinical value and should be eliminated entirely from pediatric physiotherapy practice"},{"key": "B","text": "Provides complete, standalone diagnostic certainty requiring no other assessment component whatsoever"},{"key": "C","text": "Is only relevant for research purposes with no practical clinical application"},{"key": "D","text": "Serves as one valuable component contributing to a comprehensive neurodevelopmental picture, best interpreted alongside other assessment findings rather than in isolation"}],"correct": "D","explanation": "Primitive reflex assessment contributes valuable information as one component of comprehensive pediatric neurodevelopmental assessment, most meaningfully interpreted in the context of other clinical findings rather than as an isolated, standalone diagnostic measure."},{"id": 6472,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The crossed extensor reflex, elicited by stimulating the sole of one foot while that leg is held extended, produces which response in the opposite leg?","options": [{"key": "A","text": "A response identical to the withdrawal reflex in the same leg only"},{"key": "B","text": "Extension only, with no flexion component"},{"key": "C","text": "Flexion followed by extension of the contralateral leg"},{"key": "D","text": "No response in the contralateral leg"}],"correct": "C","explanation": "The crossed extensor reflex causes the stimulated leg to flex/withdraw while the contralateral leg flexes then extends, a primitive reflex pattern relevant to early reciprocal limb coordination."},{"id": 6473,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The withdrawal reflex (flexor withdrawal) in a neonate, elicited by a noxious stimulus to the sole of the foot, produces:","options": [{"key": "A","text": "A response identical to the plantar grasp reflex"},{"key": "B","text": "No motor response, only a sensory/pain report"},{"key": "C","text": "Extension of the stimulated limb"},{"key": "D","text": "Flexion/withdrawal of the stimulated limb"}],"correct": "D","explanation": "The flexor withdrawal reflex causes reflexive flexion of the stimulated limb away from a noxious stimulus, a protective primitive reflex pattern present in neonates."},{"id": 6474,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration when a primitive reflex, typically integrated by a certain age, is found to be present but notably weak/incomplete rather than clearly obligatory or clearly absent?","options": [{"key": "A","text": "Requires careful clinical correlation with other findings, as an equivocal finding alone may not be definitively diagnostic in either direction"},{"key": "B","text": "Has no clinical relevance and should be disregarded from documentation entirely"},{"key": "C","text": "Should always be interpreted as entirely normal with certainty, requiring no further consideration"},{"key": "D","text": "Automatically confirms a diagnosis of cerebral palsy regardless of any other clinical findings"}],"correct": "A","explanation": "Equivocal or borderline reflex findings require careful correlation with the broader clinical picture (tone, other milestones, history) rather than being interpreted with false certainty in either direction."},{"id": 6475,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding repeat/serial assessment of primitive reflexes over time in an infant with an initially concerning finding?","options": [{"key": "A","text": "Repeat assessment should never be performed once an initial finding has been documented"},{"key": "B","text": "A single assessment at one point in time always provides complete, sufficient information with no need for any follow-up"},{"key": "C","text": "Serial assessment provides no additional useful information beyond a single initial assessment"},{"key": "D","text": "Serial reassessment helps track the trajectory (resolution, persistence, or worsening) of findings, informing ongoing clinical decision-making and referral timing"}],"correct": "D","explanation": "Serial reassessment over time helps track whether an initially concerning reflex finding resolves as expected, persists, or worsens, providing valuable trajectory information to inform ongoing clinical decisions and appropriate referral timing."},{"id": 6476,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the interpretation of an asymmetric primitive reflex finding when the infant also has a known history of birth trauma?","options": [{"key": "A","text": "The asymmetry should be correlated with the birth history, as it may reflect a specific peripheral injury rather than central neurological pathology"},{"key": "B","text": "Asymmetric reflex findings are always interpreted identically regardless of any birth history context"},{"key": "C","text": "Birth history has no relevance to interpreting reflex asymmetry"},{"key": "D","text": "Assuming asymmetric findings always indicate central nervous system pathology regardless of any other clinical context"}],"correct": "A","explanation": "Correlating reflex asymmetry with relevant clinical history (such as birth trauma) supports more accurate interpretation, distinguishing a peripheral cause (e.g., brachial plexus injury) from central neurological pathology."},{"id": 6477,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "A premature infant is defined as one born before which gestational age?","options": [{"key": "A","text": "40 weeks of gestation"},{"key": "B","text": "37 completed weeks of gestation"},{"key": "C","text": "32 weeks of gestation exclusively"},{"key": "D","text": "42 weeks of gestation"}],"correct": "B","explanation": "Prematurity is defined as birth before 37 completed weeks of gestation."},{"id": 6478,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "'Extremely preterm' infants are those born before which gestational age?","options": [{"key": "A","text": "37 weeks"},{"key": "B","text": "28 weeks"},{"key": "C","text": "34 weeks"},{"key": "D","text": "30 weeks exclusively defines this category"}],"correct": "B","explanation": "Extremely preterm classification applies to infants born before 28 weeks gestation, carrying the highest risk profile among preterm categories."},{"id": 6479,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "'Corrected age' (adjusted age) for a premature infant is calculated as:","options": [{"key": "A","text": "Always identical to chronological age with no adjustment"},{"key": "B","text": "Chronological age minus the number of weeks born before full term (40 weeks)"},{"key": "C","text": "Only relevant after the child reaches 2 years of age"},{"key": "D","text": "Chronological age plus additional weeks"}],"correct": "B","explanation": "Corrected age accounts for the degree of prematurity, subtracting the weeks born early from chronological age, important for appropriate developmental expectation setting."},{"id": 6480,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Corrected age is generally considered relevant for developmental assessment/milestone expectations up to approximately what age?","options": [{"key": "A","text": "Throughout the entire lifespan with no upper limit"},{"key": "B","text": "6 months"},{"key": "C","text": "5 years"},{"key": "D","text": "2 years"}],"correct": "D","explanation": "Corrected age adjustment is generally considered most relevant for developmental milestone comparison up to approximately 2 years of age, after which chronological age is typically used."},{"id": 6481,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Respiratory Distress Syndrome (RDS) in premature infants results primarily from:","options": [{"key": "A","text": "Surfactant deficiency causing alveolar collapse"},{"key": "B","text": "Primary cardiac dysfunction"},{"key": "C","text": "Excess surfactant production"},{"key": "D","text": "Congenital airway malformation exclusively"}],"correct": "A","explanation": "RDS results from insufficient surfactant production in premature lungs, causing alveolar collapse and impaired gas exchange."},{"id": 6482,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Antenatal corticosteroid administration to mothers at risk of preterm delivery is used primarily to:","options": [{"key": "A","text": "Accelerate fetal lung maturation and surfactant production, reducing RDS risk"},{"key": "B","text": "Increase fetal birth weight directly"},{"key": "C","text": "Delay labor onset indefinitely"},{"key": "D","text": "Treat maternal infection"}],"correct": "A","explanation": "Antenatal corticosteroids promote fetal lung maturation, significantly reducing RDS incidence/severity in infants born preterm."},{"id": 6483,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "Bronchopulmonary Dysplasia (BPD), a chronic lung disease of prematurity, is associated with which risk factors?","options": [{"key": "A","text": "No relationship to respiratory support/ventilation history"},{"key": "B","text": "Only occurring in full-term infants"},{"key": "C","text": "Maternal diabetes exclusively"},{"key": "D","text": "Prematurity, prolonged mechanical ventilation, and oxygen therapy"}],"correct": "D","explanation": "BPD develops particularly in premature infants requiring prolonged ventilatory/oxygen support, reflecting lung injury during a critical developmental period."},{"id": 6484,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Intraventricular Hemorrhage (IVH) in premature infants results from bleeding into the ventricles, most commonly originating from:","options": [{"key": "A","text": "The spinal cord"},{"key": "B","text": "The fragile germinal matrix, particularly vulnerable in preterm infants"},{"key": "C","text": "The cerebellum exclusively"},{"key": "D","text": "The cerebral cortex directly"}],"correct": "B","explanation": "IVH in preterm infants typically originates from the fragile, highly vascular germinal matrix, which is particularly vulnerable before its involution with advancing gestational age."},{"id": 6485,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "IVH is graded (I-IV) based primarily on:","options": [{"key": "A","text": "Only the infant's birth weight"},{"key": "B","text": "Only the infant's gestational age at diagnosis"},{"key": "C","text": "The specific ventilator settings used"},{"key": "D","text": "The extent of bleeding and presence/absence of ventricular dilation or parenchymal extension"}],"correct": "D","explanation": "IVH grading (I-IV) reflects increasing severity based on hemorrhage extent, ventricular involvement/dilation, and parenchymal extension."},{"id": 6486,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Periventricular Leukomalacia (PVL) refers to:","options": [{"key": "A","text": "Hemorrhage into the ventricles"},{"key": "B","text": "A condition exclusively affecting full-term infants"},{"key": "C","text": "Damage to the cerebellum exclusively"},{"key": "D","text": "Ischemic injury/necrosis to white matter around the lateral ventricles"}],"correct": "D","explanation": "PVL involves white matter injury near the lateral ventricles from ischemia, a significant risk factor for later cerebral palsy, particularly spastic diplegia."},{"id": 6487,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Retinopathy of Prematurity (ROP) is a condition affecting premature infants related to:","options": [{"key": "A","text": "Exclusively caused by genetic factors unrelated to prematurity"},{"key": "B","text": "Abnormal retinal vascular development, associated with prematurity and oxygen therapy exposure"},{"key": "C","text": "Only affects hearing, not vision"},{"key": "D","text": "A condition unrelated to prematurity"}],"correct": "B","explanation": "ROP results from abnormal retinal vessel development in premature infants, with oxygen exposure as a contributing risk factor, requiring appropriate ophthalmological screening/monitoring."},{"id": 6488,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Necrotizing Enterocolitis (NEC) is a serious gastrointestinal condition particularly affecting:","options": [{"key": "A","text": "Full-term infants exclusively"},{"key": "B","text": "Premature infants, involving intestinal tissue necrosis"},{"key": "C","text": "A condition unrelated to prematurity"},{"key": "D","text": "Only affecting the respiratory system"}],"correct": "B","explanation": "NEC is a serious, potentially life-threatening condition involving intestinal necrosis, disproportionately affecting premature infants."},{"id": 6489,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Hypoxic-Ischemic Encephalopathy (HIE) results from:","options": [{"key": "A","text": "Perinatal oxygen deprivation and reduced cerebral blood flow, typically in term or near-term infants"},{"key": "B","text": "Genetic factors unrelated to any perinatal event"},{"key": "C","text": "Postnatal infection exclusively"},{"key": "D","text": "A condition exclusively affecting premature infants"}],"correct": "A","explanation": "HIE results from perinatal asphyxia/reduced cerebral perfusion, typically occurring in term or near-term infants, causing potential significant neurological injury."},{"id": 6490,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "HIE severity is commonly graded using which classification system?","options": [{"key": "A","text": "Sarnat staging (mild, moderate, severe)"},{"key": "B","text": "Only gestational age classification"},{"key": "C","text": "Apgar score exclusively"},{"key": "D","text": "Bayley Scales of Infant Development"}],"correct": "A","explanation": "Sarnat staging classifies HIE severity (Stage I-III) based on clinical neurological findings, informing prognosis and management."},{"id": 6491,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Therapeutic hypothermia (cooling therapy) for HIE management works by:","options": [{"key": "A","text": "Reducing cerebral metabolic demand and secondary injury processes following the initial hypoxic-ischemic insult"},{"key": "B","text": "Increasing cerebral metabolic rate to promote faster recovery"},{"key": "C","text": "Only providing comfort/temperature regulation with no neuroprotective mechanism"},{"key": "D","text": "Directly reversing the initial hypoxic injury completely"}],"correct": "A","explanation": "Therapeutic hypothermia reduces cerebral metabolic demand and mitigates secondary injury cascades (excitotoxicity, inflammation) following the initial hypoxic-ischemic insult, improving outcomes in moderate-severe HIE."},{"id": 6492,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Erb's palsy (upper brachial plexus birth injury, C5-C6) typically results from which delivery-related mechanism?","options": [{"key": "A","text": "Cesarean delivery exclusively, never vaginal delivery"},{"key": "B","text": "Genetic factors unrelated to the delivery process"},{"key": "C","text": "Excessive lateral traction on the neck/shoulder, often associated with shoulder dystocia"},{"key": "D","text": "Prolonged labor without any traction-related mechanism"}],"correct": "C","explanation": "Erb's palsy classically results from traction injury during difficult delivery, particularly associated with shoulder dystocia."},{"id": 6493,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Klumpke's palsy (lower brachial plexus birth injury, C8-T1) is less common than Erb's palsy and may be associated with which additional finding due to nearby sympathetic chain involvement?","options": [{"key": "A","text": "Bilateral leg weakness"},{"key": "B","text": "Isolated facial nerve palsy"},{"key": "C","text": "Complete absence of any additional associated findings"},{"key": "D","text": "Horner's syndrome (ptosis, miosis, anhidrosis)"}],"correct": "D","explanation": "Klumpke's palsy can be associated with Horner's syndrome if the sympathetic chain (near T1) is also affected, an important associated finding to assess for."},{"id": 6494,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Physiotherapy management for neonatal brachial plexus palsy typically includes:","options": [{"key": "A","text": "Complete immobilization of the affected limb"},{"key": "B","text": "Aggressive stretching regardless of pain response"},{"key": "C","text": "Surgical intervention as the universal first-line approach in all cases"},{"key": "D","text": "Gentle passive range of motion exercises and positioning to prevent contracture, alongside monitoring for spontaneous recovery"}],"correct": "D","explanation": "Gentle passive ROM and appropriate positioning help prevent contracture while many cases show spontaneous recovery, with surgical referral considered for cases showing inadequate recovery within expected timeframes."},{"id": 6495,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Clavicle fracture during birth is a relatively common birth injury, typically managed with:","options": [{"key": "A","text": "Immediate surgical fixation as first-line management"},{"key": "B","text": "Prolonged complete immobilization of the entire arm for months"},{"key": "C","text": "No specific management is ever required regardless of symptoms"},{"key": "D","text": "Conservative management (gentle handling, arm support) as clavicle fractures in neonates generally heal well"}],"correct": "D","explanation": "Neonatal clavicle fractures typically heal well with simple conservative management (gentle handling, brief arm support), given the excellent healing potential in this age group."},{"id": 6496,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Caput succedaneum, a common finding on the newborn scalp, refers to:","options": [{"key": "A","text": "A serious intracranial hemorrhage"},{"key": "B","text": "A collection of blood beneath the periosteum, not crossing suture lines"},{"key": "C","text": "Diffuse edematous swelling of the scalp, crossing suture lines, from birth canal pressure"},{"key": "D","text": "A congenital skull deformity"}],"correct": "C","explanation": "Caput succedaneum is benign, diffuse scalp swelling from birth canal pressure, crossing suture lines and typically resolving within days."},{"id": 6497,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Cephalohematoma, another common newborn scalp finding, differs from caput succedaneum in that it:","options": [{"key": "A","text": "Represents a serious emergency requiring immediate surgical intervention"},{"key": "B","text": "Crosses suture lines freely, identical to caput succedaneum"},{"key": "C","text": "Represents a subperiosteal blood collection that does NOT cross suture lines"},{"key": "D","text": "Never resolves without significant long-term intervention"}],"correct": "C","explanation": "Cephalohematoma is a subperiosteal hemorrhage confined by suture lines (unlike caput succedaneum which crosses them), typically resolving over weeks to months."},{"id": 6498,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Apgar scoring, performed at 1 and 5 minutes after birth, assesses which parameters?","options": [{"key": "A","text": "Only birth weight and gestational age"},{"key": "B","text": "Appearance (color), Pulse, Grimace (reflex irritability), Activity (tone), and Respiration"},{"key": "C","text": "Only neurological reflexes"},{"key": "D","text": "Only heart rate and respiratory rate"}],"correct": "B","explanation": "Apgar score (0-10) assesses five parameters (Appearance, Pulse, Grimace, Activity, Respiration) at standardized time points to evaluate immediate newborn transition/status."},{"id": 6499,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Kangaroo care (skin-to-skin contact) in NICU management of premature infants is associated with benefits including:","options": [{"key": "A","text": "Increased risk of infection with no offsetting benefit"},{"key": "B","text": "Improved thermoregulation, physiological stability, and parent-infant bonding"},{"key": "C","text": "Only relevant for full-term infants, never appropriate for premature infants"},{"key": "D","text": "No demonstrated benefit and should be avoided in premature infants"}],"correct": "B","explanation": "Kangaroo care provides multiple evidence-supported benefits for premature infants including thermoregulation, physiological stability, and support for parent-infant bonding."},{"id": 6500,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Positioning support in the NICU (e.g., using nests/boundaries) for premature infants aims to:","options": [{"key": "A","text": "Only relevant for infants requiring mechanical ventilation"},{"key": "B","text": "Have no developmental relevance or benefit"},{"key": "C","text": "Encourage excessive extension posturing"},{"key": "D","text": "Promote flexion, midline orientation, and support neuromusculoskeletal development, mimicking aspects of the intrauterine environment"}],"correct": "D","explanation": "Developmentally supportive positioning (promoting flexion, containment, midline orientation) aims to support appropriate neuromusculoskeletal development in the NICU environment, given the loss of the normally containing intrauterine environment."},{"id": 6501,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important physiotherapy consideration regarding handling of a medically unstable premature infant in the NICU?","options": [{"key": "A","text": "Aggressive handling/stimulation regardless of the infant's physiological stability"},{"key": "B","text": "Assuming identical handling approaches are appropriate regardless of the infant's medical stability"},{"key": "C","text": "Complete avoidance of any physiotherapy involvement for any premature infant in the NICU"},{"key": "D","text": "Minimal, gentle handling with careful monitoring of physiological stability (heart rate, oxygen saturation, behavioral state) during any intervention"}],"correct": "D","explanation": "Gentle, carefully monitored handling respecting the infant's physiological stability and behavioral cues is essential when providing any intervention for medically fragile premature infants in the NICU."},{"id": 6502,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "Which of the following describes the concept of 'developmental care' philosophy in NICU management?","options": [{"key": "A","text": "An approach applicable only after the infant reaches full-term corrected age"},{"key": "B","text": "An approach considering the infant's neurodevelopmental needs alongside medical care, incorporating environmental modification, positioning, and family involvement"},{"key": "C","text": "An approach focusing exclusively on medical/physiological parameters with no consideration of neurodevelopmental factors"},{"key": "D","text": "A philosophy with no evidence base or practical application in NICU settings"}],"correct": "B","explanation": "Developmental care philosophy integrates neurodevelopmental considerations (environment, positioning, family involvement, minimizing stress) alongside medical management in comprehensive NICU care."},{"id": 6503,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding environmental stimulation (light, noise) in NICU developmental care?","options": [{"key": "A","text": "Environmental factors have no relevance to premature infant neurodevelopmental outcomes"},{"key": "B","text": "Maximizing environmental stimulation is always beneficial for premature infant development"},{"key": "C","text": "Minimizing excessive light/noise stimulation is generally recommended to support the fragile premature infant's neurodevelopment and reduce stress"},{"key": "D","text": "Only relevant for infants who have already been diagnosed with a neurological impairment"}],"correct": "C","explanation": "NICU developmental care emphasizes minimizing excessive environmental stimulation (light, noise) to reduce physiological stress and support the fragile premature infant's ongoing neurodevelopment."},{"id": 6504,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding oral feeding readiness assessment in premature infants transitioning from tube feeding?","options": [{"key": "A","text": "Oral feeding readiness has no relevance to NICU care planning"},{"key": "B","text": "Assessing coordination of suck-swallow-breathe pattern and overall physiological stability before/during oral feeding attempts"},{"key": "C","text": "Assuming all premature infants are ready for oral feeding based solely on reaching a specific chronological age"},{"key": "D","text": "Physiotherapy has no role in supporting oral feeding transition in the NICU"}],"correct": "B","explanation": "Careful assessment of suck-swallow-breathe coordination and physiological stability (rather than chronological age alone) guides appropriate, safe transition to oral feeding in premature infants, often involving physiotherapy/occupational therapy input alongside other team members."},{"id": 6505,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important long-term follow-up consideration for infants who experienced significant NICU complications (e.g., severe IVH, HIE, extreme prematurity)?","options": [{"key": "A","text": "Structured developmental follow-up/surveillance is important given increased risk of later neurodevelopmental impairment"},{"key": "B","text": "Long-term follow-up has no evidence of benefit for this population"},{"key": "C","text": "Follow-up is only relevant if the infant shows obvious impairment immediately at NICU discharge"},{"key": "D","text": "No follow-up is needed once the infant is discharged from the NICU medically stable"}],"correct": "A","explanation": "Given increased risk of later neurodevelopmental impairment, structured developmental follow-up/surveillance programs are important for infants who experienced significant NICU complications, supporting early identification and intervention if needed."},{"id": 6506,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding parental involvement/education during NICU physiotherapy intervention?","options": [{"key": "A","text": "Only medical staff should ever interact with or educate parents, excluding physiotherapy involvement"},{"key": "B","text": "Parents should be excluded from all NICU physiotherapy sessions to maintain clinical focus"},{"key": "C","text": "Actively involving and educating parents supports their engagement, understanding, and confidence in caring for their infant, both during and after NICU admission"},{"key": "D","text": "Parental involvement has no relevance to NICU care outcomes"}],"correct": "C","explanation": "Family-centered NICU care actively involves and educates parents, supporting their engagement, confidence, and understanding in caring for their infant both during NICU admission and the transition to home."},{"id": 6507,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding respiratory physiotherapy techniques for infants in the NICU with respiratory complications?","options": [{"key": "A","text": "Respiratory physiotherapy has no role in NICU management"},{"key": "B","text": "Standard adult respiratory physiotherapy techniques should be applied without any modification"},{"key": "C","text": "Careful, gentle techniques appropriately adapted to the infant's specific respiratory condition and physiological stability, given the fragility of this population"},{"key": "D","text": "Aggressive percussion/vibration techniques should always be used regardless of the infant's stability"}],"correct": "C","explanation": "Respiratory physiotherapy techniques for NICU infants require careful adaptation and gentle application appropriate to the infant's specific condition and physiological fragility, differing significantly from adult respiratory physiotherapy approaches."},{"id": 6508,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the general relevance of gestational age at birth to overall neurodevelopmental risk/prognosis?","options": [{"key": "A","text": "Generally, lower gestational age at birth is associated with increased risk of neurodevelopmental complications, though individual outcomes vary considerably"},{"key": "B","text": "All premature infants, regardless of gestational age, show identical risk profiles"},{"key": "C","text": "Gestational age at birth has no relationship whatsoever to neurodevelopmental risk"},{"key": "D","text": "Only birth weight matters for prognosis, with gestational age being entirely irrelevant"}],"correct": "A","explanation": "While individual variation is significant, lower gestational age at birth is generally associated with increased risk of various neurodevelopmental and medical complications, informing risk stratification and follow-up planning."},{"id": 6509,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the assessment of tone in premature infants, given their typically different baseline tone compared to term infants?","options": [{"key": "A","text": "Tone assessment is irrelevant for premature infants"},{"key": "B","text": "Premature infants typically show more hypotonia (particularly in flexor tone) compared to term infants, requiring assessment interpretation appropriate to their corrected age"},{"key": "C","text": "Premature and term infants show identical tone patterns requiring no different interpretation approach"},{"key": "D","text": "Premature infants always show hypertonia rather than hypotonia compared to term infants"}],"correct": "B","explanation": "Premature infants typically demonstrate more hypotonia (especially reduced flexor tone) compared to term infants, an important consideration when interpreting tone assessment findings relative to corrected age expectations."},{"id": 6510,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes the general pattern of flexor tone development observed as premature infants approach term-equivalent age?","options": [{"key": "A","text": "Flexor tone typically develops progressively in a caudocephalic (leg-to-head) direction as the infant approaches term age"},{"key": "B","text": "Flexor tone decreases progressively as infants approach term age"},{"key": "C","text": "Flexor tone development has no relationship to gestational/corrected age"},{"key": "D","text": "Flexor tone develops uniformly and simultaneously throughout the entire body with no directional pattern"}],"correct": "A","explanation": "Flexor tone in developing premature infants typically emerges progressively in a caudocephalic (lower body before upper body) pattern as they approach term-equivalent age, an important consideration in tone assessment interpretation."},{"id": 6511,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Hard","question": "Which of the following describes an important consideration regarding feeding-related physiotherapy/occupational therapy assessment in premature infants with respiratory compromise?","options": [{"key": "A","text": "Feeding assessment should never consider respiratory status"},{"key": "B","text": "Feeding and respiratory function are entirely unrelated with no need for combined assessment consideration"},{"key": "C","text": "All premature infants with any respiratory history should be permanently restricted from oral feeding"},{"key": "D","text": "Careful assessment of the coordination between feeding and respiratory effort is important, as compromised respiratory status can significantly impact safe feeding ability"}],"correct": "D","explanation": "Given the close physiological relationship between feeding and respiratory effort/coordination, careful assessment considering both domains together is important for premature infants with respiratory compromise, informing safe feeding progression."},{"id": 6512,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the use of standardized NICU-specific developmental assessment tools?","options": [{"key": "A","text": "Only medical/physiological monitoring is relevant in the NICU, with no role for standardized developmental assessment"},{"key": "B","text": "Tools specifically validated/normed for the NICU population and premature infants provide more clinically appropriate assessment compared to using tools designed primarily for term infants without adaptation"},{"key": "C","text": "Standardized assessment tools have no relevance to NICU physiotherapy practice"},{"key": "D","text": "Any developmental assessment tool designed for full-term infants can be used identically without any need for NICU-specific consideration or adaptation"}],"correct": "B","explanation": "Using assessment tools specifically validated for the NICU/premature population (rather than simply applying term-infant-normed tools without adaptation) provides more clinically appropriate and meaningful assessment in this specialized setting."},{"id": 6513,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding discharge planning and transition support for families of infants requiring extended NICU admission?","options": [{"key": "A","text": "No specific discharge planning is needed since all families are assumed to be equally prepared for the transition home"},{"key": "B","text": "Discharge planning is solely the responsibility of medical staff with no role for physiotherapy involvement"},{"key": "C","text": "Comprehensive discharge planning addressing ongoing medical/developmental needs, equipment requirements, and family education/support is important given the often complex transition to home care"},{"key": "D","text": "Discharge occurs at a fixed corrected age regardless of the infant's individual medical/developmental status"}],"correct": "C","explanation": "Comprehensive, individualized discharge planning—addressing ongoing needs, necessary equipment, and family education/support—is important given the often complex nature of transitioning infants with extended NICU admission to home care, frequently involving coordinated multidisciplinary input including physiotherapy."},{"id": 6514,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the general concept of 'cue-based' care in the NICU, relevant to physiotherapy intervention timing/approach?","options": [{"key": "A","text": "Ignoring any infant behavioral cues during intervention delivery"},{"key": "B","text": "A concept with no relevance to NICU physiotherapy practice"},{"key": "C","text": "Providing intervention according to a fixed schedule regardless of any infant behavioral or physiological signals"},{"key": "D","text": "Observing and responding to the individual infant's behavioral/physiological cues (stress signs, readiness signals) to guide the timing and nature of intervention"}],"correct": "D","explanation": "Cue-based care involves carefully observing and responding to the individual infant's behavioral and physiological signals to appropriately guide intervention timing and approach, rather than applying a rigid, fixed schedule regardless of the infant's readiness/stability."},{"id": 6515,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding multiple gestation pregnancies (e.g., twins, triplets) in relation to prematurity risk?","options": [{"key": "A","text": "This consideration has no relevance to NICU physiotherapy practice"},{"key": "B","text": "Multiple gestation pregnancies always result in full-term delivery with no increased prematurity risk"},{"key": "C","text": "Multiple gestation pregnancies carry significantly increased risk of preterm delivery compared to singleton pregnancies"},{"key": "D","text": "Multiple gestation pregnancies show identical prematurity risk to singleton pregnancies"}],"correct": "C","explanation": "Multiple gestation pregnancies carry substantially increased risk of preterm delivery compared to singleton pregnancies, relevant context for understanding NICU population risk profiles."},{"id": 6516,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the potential impact of prolonged NICU admission on parent-infant bonding/attachment, relevant to family-centered physiotherapy practice?","options": [{"key": "A","text": "NICU admission has no potential impact on parent-infant bonding processes"},{"key": "B","text": "Bonding concerns are only relevant for the most extremely premature infants, with no relevance for other NICU populations"},{"key": "C","text": "Parent-infant bonding is solely the responsibility of psychology/social work with no relevance to physiotherapy practice"},{"key": "D","text": "Extended separation and the NICU environment can present challenges to typical bonding processes, making deliberate support for parent-infant interaction/bonding an important care consideration"}],"correct": "D","explanation": "Recognizing the potential challenges that extended NICU admission and separation can present to typical parent-infant bonding processes, and actively supporting positive interaction opportunities, is an important consideration within family-centered NICU physiotherapy practice."},{"id": 6517,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding physiotherapy assessment findings interpretation for an infant born at 28 weeks gestation who is now 3 months chronological age?","options": [{"key": "A","text": "Corrected age (approximately newborn/very young corrected age) should guide developmental expectation interpretation, rather than the 3-month chronological age alone"},{"key": "B","text": "Developmental expectations should be identical to a full-term 3-month-old infant with no adjustment whatsoever"},{"key": "C","text": "Corrected age adjustment is irrelevant once the infant reaches 3 months chronological age regardless of the degree of prematurity"},{"key": "D","text": "Chronological age alone (3 months) should be used exclusively with no consideration of the significant prematurity"}],"correct": "A","explanation": "For an infant born at 28 weeks (extremely preterm) now 3 months chronological age, the corrected age would be substantially younger, and this corrected age should appropriately guide developmental expectation interpretation rather than chronological age alone."},{"id": 6518,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding assessment/monitoring of head growth (head circumference) in premature infants, particularly those with history of IVH?","options": [{"key": "A","text": "Head circumference monitoring is only relevant after the infant reaches full-term corrected age"},{"key": "B","text": "Regular head circumference monitoring is important given the risk of post-hemorrhagic hydrocephalus development following significant IVH"},{"key": "C","text": "Only weight and length require monitoring, with head circumference having no clinical relevance"},{"key": "D","text": "Head circumference monitoring is irrelevant for premature infants"}],"correct": "B","explanation": "Regular head circumference monitoring is an important surveillance measure for premature infants, particularly those with IVH history, given the risk of subsequent post-hemorrhagic ventricular dilation/hydrocephalus development."},{"id": 6519,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Meconium Aspiration Syndrome occurs when a term or post-term infant aspirates meconium-stained amniotic fluid, potentially causing:","options": [{"key": "A","text": "Respiratory distress from airway obstruction and chemical pneumonitis"},{"key": "B","text": "No respiratory consequence of any kind"},{"key": "C","text": "A condition exclusively affecting premature infants"},{"key": "D","text": "Only affecting the gastrointestinal system"}],"correct": "A","explanation": "Meconium aspiration can cause significant respiratory distress through mechanical airway obstruction and chemical irritation/inflammation of lung tissue, more common in term/post-term infants."},{"id": 6520,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Persistent Pulmonary Hypertension of the Newborn (PPHN) refers to:","options": [{"key": "A","text": "Normal newborn cardiovascular physiology requiring no intervention"},{"key": "B","text": "A condition unrelated to any respiratory or cardiovascular pathophysiology"},{"key": "C","text": "A condition exclusively affecting premature infants' cardiac structure"},{"key": "D","text": "Failure of the normal transition from fetal to postnatal circulation, with persistently elevated pulmonary vascular resistance"}],"correct": "D","explanation": "PPHN involves failure of normal postnatal pulmonary vascular resistance decrease, causing right-to-left shunting and significant hypoxemia, requiring specialized management."},{"id": 6521,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Extracorporeal Membrane Oxygenation (ECMO) may be used in severe neonatal respiratory/cardiac failure to:","options": [{"key": "A","text": "Only be used for infants over 1 year of age"},{"key": "B","text": "Provide temporary cardiopulmonary support while allowing the underlying condition to resolve/be treated"},{"key": "C","text": "Permanently replace the infant's own cardiopulmonary function indefinitely"},{"key": "D","text": "Treat only musculoskeletal conditions"}],"correct": "B","explanation": "ECMO provides temporary extracorporeal cardiopulmonary support for severe, potentially reversible respiratory/cardiac failure unresponsive to conventional management."},{"id": 6522,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important physiotherapy consideration for an infant recovering from ECMO support?","options": [{"key": "A","text": "Immediate full mobility/therapy intensity regardless of the infant's post-ECMO medical status"},{"key": "B","text": "Assuming identical rehabilitation needs to infants who did not require this level of intensive support"},{"key": "C","text": "Physiotherapy has no role for infants who have required ECMO support"},{"key": "D","text": "Careful, gradual introduction of positioning/mobility considerations once medically stable, given the significant deconditioning and potential complications associated with this intensive support"}],"correct": "D","explanation": "Infants recovering from ECMO support often show significant deconditioning and may have specific complications requiring careful, gradual, individualized physiotherapy approach once medically stabilized."},{"id": 6523,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding neonatal abstinence syndrome (NAS) relevant to physiotherapy/handling approaches in the NICU?","options": [{"key": "A","text": "Physiotherapy involvement is contraindicated for any infant with NAS"},{"key": "B","text": "Infants with NAS may show increased irritability/altered tone and benefit from gentle, calming handling techniques and appropriate environmental modification"},{"key": "C","text": "All infants with NAS require identical, standardized handling regardless of their individual presentation"},{"key": "D","text": "NAS has no relevance to physiotherapy practice or handling considerations"}],"correct": "B","explanation": "Infants with NAS often show increased irritability, altered tone, and sensory sensitivity, benefiting from gentle, calming handling approaches and appropriate environmental/positioning modifications as part of comprehensive supportive care."},{"id": 6524,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding congenital infections (e.g., TORCH infections) and their potential relevance to neonatal neurodevelopmental risk?","options": [{"key": "A","text": "Congenital infections have no relationship to any neurodevelopmental outcome"},{"key": "B","text": "This consideration is entirely irrelevant to physiotherapy practice"},{"key": "C","text": "Certain congenital infections can be associated with significant neurodevelopmental impairment, relevant to comprehensive risk assessment and follow-up planning"},{"key": "D","text": "Only postnatal infections are relevant to neurodevelopmental risk, never congenital infections"}],"correct": "C","explanation": "Certain congenital infections (grouped under the TORCH acronym: Toxoplasmosis, Other, Rubella, Cytomegalovirus, Herpes) can be associated with significant neurodevelopmental impairment, relevant context for comprehensive risk assessment and appropriate developmental follow-up planning."},{"id": 6525,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'late preterm' infants (born between 34-36 weeks gestation) compared to more extremely premature infants?","options": [{"key": "A","text": "Late preterm infants always show higher risk than extremely premature infants"},{"key": "B","text": "This gestational age category has no clinical relevance or distinct consideration compared to other prematurity categories"},{"key": "C","text": "While generally at lower risk than more extremely premature infants, late preterm infants still show increased risk of complications compared to full-term infants, warranting appropriate monitoring"},{"key": "D","text": "Late preterm infants show identical risk profiles to full-term infants with no need for any additional monitoring consideration"}],"correct": "C","explanation": "Late preterm infants, while generally at lower risk than more extremely premature infants, still demonstrate increased risk of various complications compared to full-term infants, warranting appropriate ongoing monitoring rather than being treated as equivalent to full-term infants."},{"id": 6526,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding vitamin K administration shortly after birth, relevant to preventing a rare but serious bleeding disorder in neonates?","options": [{"key": "A","text": "This is only relevant for premature infants, never for full-term infants"},{"key": "B","text": "Vitamin K administration has no relevance to neonatal bleeding risk"},{"key": "C","text": "Vitamin K prophylaxis helps prevent Vitamin K Deficiency Bleeding (previously called hemorrhagic disease of the newborn)"},{"key": "D","text": "Vitamin K prophylaxis is administered exclusively to treat existing intraventricular hemorrhage"}],"correct": "C","explanation": "Routine vitamin K administration shortly after birth is a standard preventive measure against Vitamin K Deficiency Bleeding, a rare but serious neonatal bleeding disorder."},{"id": 6527,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Easy","question": "Cerebral palsy is best defined as a group of disorders affecting:","options": [{"key": "A","text": "Only peripheral nerve function"},{"key": "B","text": "Movement and posture development, attributed to non-progressive disturbances in the developing fetal/infant brain"},{"key": "C","text": "Only cognitive function with no motor component"},{"key": "D","text": "A purely progressive, degenerative condition"}],"correct": "B","explanation": "CP describes non-progressive movement/posture disorders resulting from disturbances occurring in the developing brain, though secondary musculoskeletal changes can evolve over time."},{"id": 6528,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Medium","question": "Spastic cerebral palsy, the most common subtype, results from damage to which pathway?","options": [{"key": "A","text": "Basal ganglia pathway exclusively"},{"key": "B","text": "Corticospinal (pyramidal) pathway"},{"key": "C","text": "Peripheral nerve pathway"},{"key": "D","text": "Cerebellar pathway exclusively"}],"correct": "B","explanation": "Spastic CP results from pyramidal/corticospinal tract damage, producing characteristic hypertonia."},{"id": 6529,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Medium","question": "Dyskinetic cerebral palsy results from damage primarily to which structures?","options": [{"key": "A","text": "Corticospinal tract exclusively"},{"key": "B","text": "Spinal cord exclusively"},{"key": "C","text": "Basal ganglia"},{"key": "D","text": "Peripheral nerves exclusively"}],"correct": "C","explanation": "Dyskinetic CP results from basal ganglia/extrapyramidal damage, producing involuntary movements and variable tone."},{"id": 6530,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Medium","question": "Ataxic cerebral palsy results from damage primarily to which structure?","options": [{"key": "A","text": "Cerebellum"},{"key": "B","text": "Peripheral nerves"},{"key": "C","text": "Basal ganglia exclusively"},{"key": "D","text": "Corticospinal tract exclusively"}],"correct": "A","explanation": "Ataxic CP results from cerebellar damage, producing characteristic incoordination and balance impairment."},{"id": 6531,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Spastic diplegia, commonly associated with prematurity and periventricular leukomalacia, predominantly affects:","options": [{"key": "A","text": "All four limbs equally"},{"key": "B","text": "Only one side of the body (arm and leg)"},{"key": "C","text": "Only the upper limbs"},{"key": "D","text": "Both lower limbs, with lesser upper limb involvement"}],"correct": "D","explanation": "Spastic diplegia predominantly affects the lower limbs, classically associated with PVL in premature infants."},{"id": 6532,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Spastic hemiplegia refers to CP predominantly affecting:","options": [{"key": "A","text": "All four limbs equally"},{"key": "B","text": "Only the trunk musculature"},{"key": "C","text": "One side of the body (arm and leg on the same side)"},{"key": "D","text": "Both lower limbs equally"}],"correct": "C","explanation": "Hemiplegic CP involves unilateral arm and leg involvement on the same body side."},{"id": 6533,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Spastic quadriplegia (tetraplegia) refers to CP affecting:","options": [{"key": "A","text": "Only one side of the body"},{"key": "B","text": "Only the lower limbs"},{"key": "C","text": "Only the upper limbs"},{"key": "D","text": "All four limbs, often with significant trunk and bulbar involvement as well"}],"correct": "D","explanation": "Quadriplegic CP involves all four limbs, often with significant additional trunk/bulbar involvement, generally representing more severe presentation."},{"id": 6534,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Gross Motor Function Classification System (GMFCS) classifies CP into how many severity levels?","options": [{"key": "A","text": "Ten levels"},{"key": "B","text": "Three levels"},{"key": "C","text": "Two levels"},{"key": "D","text": "Five levels (I-V)"}],"correct": "D","explanation": "GMFCS uses five levels (I to V) to classify gross motor function severity, widely used for CP classification and prognostic communication."},{"id": 6535,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "GMFCS Level I describes children who can:","options": [{"key": "A","text": "Only walk using hand-held mobility devices"},{"key": "B","text": "Walk without limitations in most settings"},{"key": "C","text": "Require a wheelchair for all mobility"},{"key": "D","text": "Have no functional mobility whatsoever"}],"correct": "B","explanation": "GMFCS Level I represents the most independent functional level, walking without significant limitation, though may show some difficulty with more advanced motor skills."},{"id": 6536,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "GMFCS Level V describes children who:","options": [{"key": "A","text": "Self-propel a manual wheelchair independently in most environments"},{"key": "B","text": "Have severe limitations in self-mobility even with assistive technology"},{"key": "C","text": "Walk independently without any limitation"},{"key": "D","text": "Walk using hand-held mobility devices in most settings"}],"correct": "B","explanation": "GMFCS Level V represents the most severe functional limitation category, with very limited self-mobility capacity even with assistive technology support."},{"id": 6537,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Manual Ability Classification System (MACS) is used to classify:","options": [{"key": "A","text": "Gross motor function specifically"},{"key": "B","text": "How children with CP use their hands to handle objects in daily activities"},{"key": "C","text": "Cognitive function specifically"},{"key": "D","text": "Communication ability specifically"}],"correct": "B","explanation": "MACS (Levels I-V) specifically classifies bimanual hand function/object handling ability in daily activities for children with CP."},{"id": 6538,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Communication Function Classification System (CFCS) is used to classify:","options": [{"key": "A","text": "A child's overall performance in everyday communication with various communication partners"},{"key": "B","text": "Cognitive function specifically"},{"key": "C","text": "Gross motor function specifically"},{"key": "D","text": "Manual/hand function specifically"}],"correct": "A","explanation": "CFCS classifies the effectiveness of a child's everyday communication performance, complementing GMFCS and MACS in comprehensive CP classification."},{"id": 6539,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Periventricular leukomalacia (PVL), a common finding preceding spastic diplegic CP, particularly affects:","options": [{"key": "A","text": "White matter near the lateral ventricles, particularly vulnerable in preterm infants"},{"key": "B","text": "Only the cerebellum"},{"key": "C","text": "Only the spinal cord"},{"key": "D","text": "Grey matter of the cerebral cortex primarily"}],"correct": "A","explanation": "PVL specifically affects periventricular white matter, an area particularly vulnerable in preterm infants due to vascular supply characteristics during this developmental period."},{"id": 6540,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Hip surveillance programs in CP management are recommended primarily because:","options": [{"key": "A","text": "Hip surveillance is only relevant for GMFCS Level I children"},{"key": "B","text": "All children with CP require identical hip monitoring frequency regardless of GMFCS level"},{"key": "C","text": "Hip problems never occur in children with CP"},{"key": "D","text": "Hip displacement risk correlates with GMFCS level and can progress silently without regular monitoring"}],"correct": "D","explanation": "Regular hip surveillance (clinical and radiographic) allows early detection of progressive hip displacement, particularly important given the correlation between GMFCS level and displacement risk, allowing timely intervention."},{"id": 6541,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Contractures are a common secondary complication in CP, developing due to:","options": [{"key": "A","text": "A condition unrelated to the underlying motor impairment"},{"key": "B","text": "Chronic spasticity/muscle imbalance combined with skeletal growth, if not proactively managed"},{"key": "C","text": "Purely genetic factors unrelated to tone abnormality"},{"key": "D","text": "Only occurring in children who never receive any physiotherapy"}],"correct": "B","explanation": "Persistent spasticity and muscle imbalance, compounded by ongoing skeletal growth, predispose to progressive contracture development without appropriate proactive management (stretching, positioning, splinting, and other interventions)."},{"id": 6542,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Botulinum toxin injections in CP management provide which type of spasticity reduction?","options": [{"key": "A","text": "Permanent, generalized spasticity elimination"},{"key": "B","text": "Temporary, focal spasticity reduction (typically lasting 3-6 months)"},{"key": "C","text": "A cure for the underlying cerebral palsy condition"},{"key": "D","text": "Only affects cognitive symptoms, not motor tone"}],"correct": "B","explanation": "Botulinum toxin provides temporary, focal spasticity reduction at the injected muscle, often used to facilitate functional improvement or reduce contracture progression risk, requiring repeat injection as effects wear off."},{"id": 6543,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Selective Dorsal Rhizotomy (SDR) surgical intervention for CP-related spasticity works by:","options": [{"key": "A","text": "A reversible procedure allowing complete return to prior tone level if desired"},{"key": "B","text": "Only affecting cognitive function with no motor effect"},{"key": "C","text": "Temporarily blocking motor nerve function"},{"key": "D","text": "Selectively dividing overactive sensory (dorsal) nerve rootlets, providing permanent spasticity reduction"}],"correct": "D","explanation": "SDR selectively divides hyperactive dorsal (sensory) rootlets, permanently reducing spasticity, typically followed by intensive post-surgical rehabilitation to maximize functional benefit."},{"id": 6544,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Intrathecal baclofen therapy is generally reserved for which CP population given its more invasive nature?","options": [{"key": "A","text": "Only for children under 1 year of age"},{"key": "B","text": "More severe, generalized spasticity not adequately managed by less invasive approaches"},{"key": "C","text": "Only the mildest spasticity presentations"},{"key": "D","text": "Exclusively for GMFCS Level I children"}],"correct": "B","explanation": "Intrathecal baclofen, involving surgical pump implantation, is generally reserved for more severe generalized spasticity requiring more targeted management than oral medications or botulinum toxin alone can achieve."},{"id": 6545,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Constraint-Induced Movement Therapy (CIMT), adapted for hemiplegic CP, involves:","options": [{"key": "A","text": "Only applicable to lower limb function, not upper limb"},{"key": "B","text": "Restraining the less-affected upper limb to encourage intensive practice/use of the more-affected limb"},{"key": "C","text": "Requiring complete immobilization of both upper limbs simultaneously"},{"key": "D","text": "Restraining the more-affected limb to protect it from overuse"}],"correct": "B","explanation": "Pediatric CIMT restrains the less-affected limb, promoting intensive, structured practice of the more-affected upper limb in hemiplegic CP."},{"id": 6546,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Hand-Arm Bimanual Intensive Therapy (HABIT) differs from CIMT in its emphasis on:","options": [{"key": "A","text": "Intensive practice of bimanual (two-handed) coordinated tasks rather than unilateral restraint-based practice"},{"key": "B","text": "Only lower limb function"},{"key": "C","text": "Passive range of motion exclusively without any active practice component"},{"key": "D","text": "Complete restraint of both upper limbs simultaneously"}],"correct": "A","explanation": "HABIT focuses on intensive bimanual task practice, addressing functional two-handed activity demands, contrasting with CIMT's unilateral restraint-based approach."},{"id": 6547,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Serial casting is commonly used in CP management to address:","options": [{"key": "A","text": "Acute fracture management exclusively"},{"key": "B","text": "Communication difficulties"},{"key": "C","text": "Cognitive impairment"},{"key": "D","text": "Joint contractures (e.g., ankle equinus) through progressive, gradual stretching via successive cast changes"}],"correct": "D","explanation": "Serial casting applies gradual progressive stretch through repeated cast changes, commonly addressing contractures like ankle equinus common in spastic CP."},{"id": 6548,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Ankle-foot orthoses (AFOs) are commonly prescribed for children with CP primarily to:","options": [{"key": "A","text": "Improve ankle stability/alignment and support more efficient gait mechanics"},{"key": "B","text": "Address upper limb function exclusively"},{"key": "C","text": "Replace the need for any physiotherapy intervention"},{"key": "D","text": "Only for cosmetic purposes with no functional benefit"}],"correct": "A","explanation": "AFOs help manage common ankle issues (instability, equinus) in CP, supporting improved gait mechanics and functional mobility."},{"id": 6549,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Selective motor control impairment in spastic CP refers to:","options": [{"key": "A","text": "Complete absence of any voluntary movement capability"},{"key": "B","text": "Reduced ability to isolate movement at a single joint without involuntary movement at adjacent joints"},{"key": "C","text": "Only relevant to upper limb function, never lower limb"},{"key": "D","text": "A concept unrelated to CP motor presentation"}],"correct": "B","explanation": "Impaired selective motor control describes difficulty isolating movement at individual joints, an important consideration in CP motor assessment beyond simple strength/tone measures."},{"id": 6550,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "'Crouch gait,' a common gait pattern in spastic diplegic CP, is characterized by:","options": [{"key": "A","text": "Excessive knee hyperextension throughout stance"},{"key": "B","text": "A completely normal gait pattern with no deviation"},{"key": "C","text": "Isolated ankle abnormality without any proximal joint involvement"},{"key": "D","text": "Excessive hip and knee flexion throughout stance phase"}],"correct": "D","explanation": "Crouch gait shows excessive flexed posture at hip/knee throughout stance, a common problematic pattern in spastic diplegia, sometimes related to hamstring tightness combined with weakness."},{"id": 6551,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Instrumented 3D gait analysis in CP management is particularly valuable for:","options": [{"key": "A","text": "Replacing the need for any clinical examination entirely"},{"key": "B","text": "Assessing only upper limb function"},{"key": "C","text": "Objectively characterizing specific gait deviations, informing targeted treatment planning including surgical decision-making"},{"key": "D","text": "Only research purposes with no clinical application"}],"correct": "C","explanation": "3D gait analysis provides objective, detailed movement data supporting individualized treatment planning, particularly valuable for complex surgical decision-making in CP gait management."},{"id": 6552,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Single-Event Multilevel Surgery (SEMLS) in CP orthopedic management refers to:","options": [{"key": "A","text": "A term unrelated to CP surgical management"},{"key": "B","text": "Addressing multiple musculoskeletal deformities within a single surgical episode/anesthetic event"},{"key": "C","text": "Performing surgery on only one body region regardless of multiple deformities present"},{"key": "D","text": "A procedure requiring separate surgical episodes for each individual deformity"}],"correct": "B","explanation": "SEMLS addresses multiple concurrent deformities in one surgical event, reducing the cumulative burden of multiple separate procedures/recovery periods."},{"id": 6553,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an appropriate approach to strength training in children with CP, addressing historical concerns about worsening spasticity?","options": [{"key": "A","text": "Current evidence supports appropriately dosed strength training as beneficial without exacerbating spasticity"},{"key": "B","text": "Strength training should only ever be performed passively without active patient effort"},{"key": "C","text": "Strength training should always be avoided given spasticity concerns"},{"key": "D","text": "Strength training has no evidence base for CP management"}],"correct": "A","explanation": "Contrary to older concerns, contemporary evidence supports strength training as a safe, beneficial component of CP management without evidence of worsening spasticity."},{"id": 6554,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding equipment/assistive technology provision for children with CP as they grow?","options": [{"key": "A","text": "Regular reassessment and appropriate adaptation/replacement as growth and functional needs evolve over time"},{"key": "B","text": "Equipment provided once should never require any subsequent modification or replacement"},{"key": "C","text": "Assistive technology has no relevant role in CP management"},{"key": "D","text": "Equipment needs are identical for all children with CP regardless of GMFCS level"}],"correct": "A","explanation": "Equipment/assistive technology needs evolve considerably with growth and changing function, requiring regular reassessment and appropriate modification throughout childhood development."},{"id": 6555,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Hydrotherapy (aquatic therapy) in pediatric CP rehabilitation offers which particular benefit?","options": [{"key": "A","text": "Complete replacement of all land-based therapy in every case"},{"key": "B","text": "Buoyancy-assisted movement allowing exercise with reduced gravitational/joint loading demands"},{"key": "C","text": "Only appropriate for the mildest CP presentations, GMFCS Level I only"},{"key": "D","text": "No evidence-based benefit and should be avoided"}],"correct": "B","explanation": "Water's buoyancy properties facilitate movement with reduced loading demands, offering valuable complementary therapeutic benefit in pediatric CP rehabilitation across various severity levels."},{"id": 6556,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding family-centered goal-setting in pediatric CP rehabilitation?","options": [{"key": "A","text": "Goals should be determined exclusively by the therapist without any family/child input"},{"key": "B","text": "Generic standardized goals applied uniformly regardless of individual family priorities are always preferable"},{"key": "C","text": "Actively involving the child/family in identifying meaningful, functional priorities supports engagement and relevant outcome achievement"},{"key": "D","text": "Goal-setting has no relevance to effective pediatric rehabilitation planning"}],"correct": "C","explanation": "Family-centered practice, actively involving children/families in meaningful, functional goal-setting, is considered best practice, supporting engagement and achievement of personally relevant outcomes."},{"id": 6557,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Athetoid movements, characteristic of dyskinetic CP, are best described as:","options": [{"key": "A","text": "Sudden brief shock-like jerks"},{"key": "B","text": "Slow, writhing, continuous involuntary movements"},{"key": "C","text": "Sustained fixed abnormal postures without any movement component"},{"key": "D","text": "Rhythmic tremor present only at rest"}],"correct": "B","explanation": "Athetosis describes slow, writhing, continuous involuntary movement, a characteristic feature distinguishing dyskinetic CP from other subtypes."},{"id": 6558,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding classroom/educational positioning equipment for a child with CP?","options": [{"key": "A","text": "School-based positioning has no relevance to physiotherapy involvement"},{"key": "B","text": "Appropriate seating/positioning supports participation, posture, and function during educational activities, often requiring collaboration with school staff"},{"key": "C","text": "Educational and home positioning needs are always identical with no distinction required"},{"key": "D","text": "Positioning equipment is only relevant at home, never in educational settings"}],"correct": "B","explanation": "Appropriate classroom seating/positioning supports the child's postural needs and functional educational participation, often requiring physiotherapy collaboration with school-based staff."},{"id": 6559,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important transition planning consideration for adolescents with CP approaching adulthood?","options": [{"key": "A","text": "No transition planning is needed since CP-related needs automatically resolve in adulthood"},{"key": "B","text": "Transition planning is solely a medical specialist responsibility with no physiotherapy involvement"},{"key": "C","text": "Assuming needs remain completely static and unchanged throughout the lifespan"},{"key": "D","text": "Planning for transition to adult services, addressing evolving musculoskeletal, functional, and psychosocial needs"}],"correct": "D","explanation": "Thoughtful transition planning, addressing evolving needs as individuals with CP move into adulthood, is an important component of comprehensive lifelong care planning."},{"id": 6560,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes a common associated impairment that may accompany the primary motor disorder in CP?","options": [{"key": "A","text": "Cognitive, sensory, communication, and/or seizure disorders can commonly co-occur"},{"key": "B","text": "CP exclusively affects motor function with no other possible associated impairment"},{"key": "C","text": "Associated impairments occur exclusively in the mildest CP presentations"},{"key": "D","text": "Only visual impairment can ever co-occur alongside CP"}],"correct": "A","explanation": "CP frequently co-occurs with a range of associated impairments reflecting the often widespread nature of the underlying brain injury, requiring comprehensive multidisciplinary assessment beyond the primary motor disorder."},{"id": 6561,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "Which of the following describes the general approach to physiotherapy across a child's developmental course with CP?","options": [{"key": "A","text": "Regularly evolving intervention addressing changing developmental stages, functional goals, and emerging secondary complications"},{"key": "B","text": "Physiotherapy involvement ending once school age is reached"},{"key": "C","text": "A single fixed intervention program unchanged from diagnosis through adulthood"},{"key": "D","text": "Intervention focus remaining identical regardless of the child's changing age/needs"}],"correct": "A","explanation": "CP physiotherapy management evolves considerably across childhood/adolescence, addressing changing developmental priorities and emerging secondary musculoskeletal concerns as the child grows."},{"id": 6562,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following best describes the concept of 'active cycle of breathing techniques' or similar respiratory physiotherapy approaches relevant to some children with CP experiencing respiratory complications?","options": [{"key": "A","text": "Techniques aimed at improving secretion clearance and respiratory function, particularly relevant for children with more significant motor impairment affecting respiratory muscle control/positioning"},{"key": "B","text": "A technique with no relevance to children with CP regardless of respiratory status"},{"key": "C","text": "Respiratory physiotherapy is never indicated for children with cerebral palsy"},{"key": "D","text": "Only relevant for children with CP who also have a separate primary lung disease diagnosis"}],"correct": "A","explanation": "Respiratory physiotherapy techniques can be relevant for children with CP experiencing respiratory complications, particularly those with more significant motor impairment affecting positioning, chest wall mechanics, and secretion clearance ability."},{"id": 6563,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important nutritional consideration for children with CP, particularly those with significant motor/bulbar impairment?","options": [{"key": "A","text": "Nutritional assessment is solely a dietitian responsibility with no relevance to physiotherapy practice"},{"key": "B","text": "Nutrition is never a relevant consideration for children with CP regardless of severity"},{"key": "C","text": "All children with CP have identical nutritional needs and feeding abilities regardless of GMFCS level"},{"key": "D","text": "Risk of feeding difficulties/dysphagia and associated growth/nutritional concerns requiring appropriate assessment and management"}],"correct": "D","explanation": "Children with CP, particularly those with more significant motor/bulbar involvement, are at increased risk of feeding difficulties and associated growth/nutritional concerns, warranting comprehensive multidisciplinary assessment and management."},{"id": 6564,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding sleep positioning equipment (e.g., sleep systems) sometimes used for children with more severe CP?","options": [{"key": "A","text": "Can help support appropriate body alignment during sleep, potentially assisting with comfort, hip positioning, and reducing progressive deformity risk"},{"key": "B","text": "Sleep positioning has no relevance to overall CP management"},{"key": "C","text": "Only relevant for daytime positioning, never for sleep-related considerations"},{"key": "D","text": "All children with CP require identical sleep positioning equipment regardless of individual presentation"}],"correct": "A","explanation": "Sleep positioning systems can support appropriate body alignment overnight, potentially contributing to comfort and management of hip positioning/deformity risk in children with more significant CP-related postural challenges."},{"id": 6565,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding powered mobility (e.g., power wheelchair) provision for young children with severe CP (e.g., GMFCS Level IV-V)?","options": [{"key": "A","text": "Can support independent exploration and participation from a young age, with growing evidence supporting benefits of early powered mobility access"},{"key": "B","text": "Powered mobility provides no developmental or participation benefit for young children"},{"key": "C","text": "Powered mobility should never be considered for children under school age regardless of their motor limitations"},{"key": "D","text": "Manual wheelchair use is always superior to powered mobility regardless of the child's specific capabilities"}],"correct": "A","explanation": "Growing evidence supports the potential developmental and participation benefits of appropriately timed powered mobility provision, even for young children with severe motor limitation who cannot achieve independent mobility through other means."},{"id": 6566,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding standing frame use for children with CP who have limited or no independent standing ability?","options": [{"key": "A","text": "Standing programs are only appropriate for children who will eventually achieve independent ambulation"},{"key": "B","text": "Regular standing program participation may offer benefits including bone loading, hip joint positioning support, and improved bowel/bladder function, alongside psychological benefits"},{"key": "C","text": "Standing frames provide no physiological benefit for children unable to stand independently"},{"key": "D","text": "Standing frame use is contraindicated for any child with significant CP-related impairment"}],"correct": "B","explanation": "Standing programs offer multiple potential physiological benefits (bone loading, hip positioning, GI/GU function) and psychological benefits, valuable even for children unlikely to achieve independent standing/walking."},{"id": 6567,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Easy","question": "Which of the following describes an important consideration regarding scoliosis monitoring in children with more severe CP (e.g., GMFCS Level IV-V)?","options": [{"key": "A","text": "Increased risk of scoliosis development/progression warrants regular monitoring, particularly in this higher-severity population"},{"key": "B","text": "Scoliosis risk is identical across all GMFCS levels with no need for differential monitoring approach"},{"key": "C","text": "Scoliosis never occurs in children with cerebral palsy"},{"key": "D","text": "Scoliosis monitoring is irrelevant to physiotherapy practice in CP management"}],"correct": "A","explanation": "Children with more severe CP (higher GMFCS levels) show increased risk of scoliosis development, warranting regular monitoring as part of comprehensive musculoskeletal surveillance, alongside hip surveillance."},{"id": 6568,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the general approach to selecting appropriate walking aids for children with CP who require some support for ambulation?","options": [{"key": "A","text": "Walking aid needs remain completely static throughout the child's entire developmental course"},{"key": "B","text": "Individualized selection based on the child's specific balance, strength, and stability needs, potentially progressing as skills develop"},{"key": "C","text": "A single standard walking aid type is appropriate for all children with CP regardless of individual presentation"},{"key": "D","text": "Walking aids should never be provided to children, only adults"}],"correct": "B","explanation": "Walking aid selection (e.g., posterior walker, anterior walker, gait trainer) should be individualized based on the child's specific needs, potentially progressing or changing as their skills and stability develop over time."},{"id": 6569,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the timing of orthopedic surgical intervention (e.g., tendon lengthening) in relation to a child's growth in CP management?","options": [{"key": "A","text": "Careful consideration of growth stage is important, as timing relative to growth spurts can affect surgical outcomes and recurrence risk"},{"key": "B","text": "Growth stage has no relevance to surgical timing decisions in CP orthopedic management"},{"key": "C","text": "Timing considerations are irrelevant since surgical outcomes are identical regardless of when performed relative to growth"},{"key": "D","text": "Surgery should always be performed as early as possible in infancy regardless of any growth consideration"}],"correct": "A","explanation": "Growth stage is an important consideration in CP orthopedic surgical timing, as procedures performed too early relative to ongoing growth may show higher recurrence rates, informing careful multidisciplinary surgical planning."},{"id": 6570,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'body-powered' orthopedic deformity in CP versus deformity arising from external forces?","options": [{"key": "A","text": "This distinction has no relevance to understanding CP-related musculoskeletal complications"},{"key": "B","text": "Deformity in CP has no relationship to the underlying muscle tone/imbalance pattern"},{"key": "C","text": "CP-related deformity always results exclusively from external positioning devices or equipment"},{"key": "D","text": "CP-related deformity typically arises from the internal muscle imbalance/spasticity pattern itself acting on growing bone, rather than from external mechanical forces"}],"correct": "D","explanation": "Understanding that CP-related musculoskeletal deformity typically arises from the internal muscle imbalance/spasticity pattern acting on the growing skeleton (rather than primarily from external forces) is important for appropriately targeted management approaches."},{"id": 6571,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the potential benefit of partial body weight-supported treadmill training for some children with CP?","options": [{"key": "A","text": "Only appropriate for children who have already achieved fully independent walking"},{"key": "B","text": "May allow practice of stepping/gait-related patterns with reduced full weight-bearing demand, potentially useful for children with limited independent gait capacity"},{"key": "C","text": "Partial body weight support training is contraindicated for all children with cerebral palsy"},{"key": "D","text": "This approach provides no potential benefit for any child with CP regardless of severity"}],"correct": "B","explanation": "Body weight-supported treadmill training may offer a therapeutic option for practicing gait-related movement patterns with reduced loading demand, potentially relevant for children with limited independent ambulation capacity as part of a broader rehabilitation approach."},{"id": 6572,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the potential role of virtual reality or gaming-based technology in pediatric CP rehabilitation?","options": [{"key": "A","text": "Only appropriate for adolescents with CP, never for younger children"},{"key": "B","text": "Should always completely replace conventional physiotherapy approaches in every case"},{"key": "C","text": "Virtual reality technology has no potential role or evidence base in pediatric CP rehabilitation"},{"key": "D","text": "Can provide engaging, motivating practice opportunities potentially supporting increased repetition/engagement in therapeutic exercise, as a complement to conventional approaches"}],"correct": "D","explanation": "Virtual reality/gaming-based technology can offer engaging, motivating practice opportunities that may support increased therapeutic engagement and repetition, generally used as a complement to (rather than complete replacement for) conventional pediatric physiotherapy approaches."},{"id": 6573,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding orthotic management for upper limb involvement in hemiplegic CP?","options": [{"key": "A","text": "Standardized upper limb splinting protocols are identical for all children regardless of their specific presentation"},{"key": "B","text": "Orthotic devices are only ever used for lower limb management in CP, never upper limb"},{"key": "C","text": "Splinting may be used to help manage contracture risk or support functional hand positioning, individualized to the specific presentation"},{"key": "D","text": "Upper limb orthotic management is never relevant or used in CP care"}],"correct": "C","explanation": "Upper limb splinting/orthotic approaches may be individually considered to help manage contracture risk or support functional positioning in children with hemiplegic CP, tailored to the specific clinical presentation."},{"id": 6574,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'activity-based' therapy approaches sometimes discussed in relation to intensive CP rehabilitation programs?","options": [{"key": "A","text": "Emphasizing high-repetition, task-specific practice of functional activities to promote motor learning and potential neuroplastic adaptation"},{"key": "B","text": "A term identical in meaning to purely passive treatment approaches"},{"key": "C","text": "Only relevant for adult neurological rehabilitation, never applicable to pediatric CP management"},{"key": "D","text": "An approach with no theoretical basis or evidence relevant to CP rehabilitation"}],"correct": "A","explanation": "Activity-based, intensive, task-specific practice approaches (grounded in motor learning and neuroplasticity principles) represent an important and increasingly emphasized component of contemporary evidence-based CP rehabilitation programming."},{"id": 6575,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the assessment of participation (not just impairment/activity level) for children with CP, consistent with the ICF framework?","options": [{"key": "A","text": "Assessment should focus exclusively on gross motor impairment with no consideration of the child's broader life participation"},{"key": "B","text": "Participation-level assessment is irrelevant to pediatric CP rehabilitation, which should focus exclusively on impairment-level findings"},{"key": "C","text": "Only activity-level (functional task) assessment is relevant, with no need to consider broader participation"},{"key": "D","text": "Assessing and addressing meaningful participation in home, school, and community life is an important, holistic component of comprehensive CP rehabilitation planning"}],"correct": "D","explanation": "Consistent with the holistic ICF framework, assessing and addressing meaningful participation in home, school, and community contexts (beyond isolated impairment or activity-level findings) is an important component of comprehensive, person-centered CP rehabilitation."},{"id": 6576,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the timing of initial CP diagnosis, given that early clinical signs may be subtle?","options": [{"key": "A","text": "All children with CP show obvious, unmistakable signs immediately from birth"},{"key": "B","text": "Early detection tools (e.g., General Movements Assessment, Hammersmith Infant Neurological Examination) can support earlier identification, allowing earlier intervention initiation"},{"key": "C","text": "CP can only ever be reliably diagnosed after age 5 years, with no earlier detection possible"},{"key": "D","text": "Early diagnosis has no relevance to intervention timing or outcomes"}],"correct": "B","explanation": "Validated early detection tools support earlier identification of CP risk, increasingly enabling earlier intervention initiation, which is an area of active clinical and research focus given potential benefits of early intervention."},{"id": 6577,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "The General Movements Assessment (GMA), used for early CP risk identification, evaluates:","options": [{"key": "A","text": "Only muscle strength using manual testing"},{"key": "B","text": "Only reflex responses to specific stimuli"},{"key": "C","text": "The quality of spontaneous infant movement patterns, particularly 'fidgety' movements around 3-5 months corrected age"},{"key": "D","text": "Only cognitive function via structured testing"}],"correct": "C","explanation": "GMA is a validated observational tool assessing the quality/complexity of spontaneous infant movements, with absent/abnormal fidgety movements being a strong early predictor of later CP."},{"id": 6578,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding communication approaches for children with CP who have significant speech impairment but relatively preserved cognitive understanding?","options": [{"key": "A","text": "Assuming cognitive impairment automatically accompanies any significant speech impairment in CP"},{"key": "B","text": "Communication support has no relevance to physiotherapy practice or overall rehabilitation planning"},{"key": "C","text": "AAC systems are only appropriate for adults, never for children with CP"},{"key": "D","text": "Augmentative and Alternative Communication (AAC) systems can support meaningful communication and participation despite significant speech production impairment"}],"correct": "D","explanation": "AAC systems can support meaningful communication for children with CP who have significant speech impairment despite relatively preserved cognitive/language comprehension, important for overall participation and often relevant context for physiotherapy interaction."},{"id": 6579,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding drooling/sialorrhea management sometimes relevant in children with CP with significant oral-motor impairment?","options": [{"key": "A","text": "Drooling is never a relevant clinical concern in CP management"},{"key": "B","text": "Only medication is ever used for management, with no role for positioning or therapy-based approaches"},{"key": "C","text": "May require multidisciplinary management approaches (positioning, oral-motor therapy, and sometimes medical/surgical intervention) given potential social and skin-care impact"},{"key": "D","text": "This consideration is entirely unrelated to any physiotherapy involvement in the child's care"}],"correct": "C","explanation": "Sialorrhea management in CP may involve multidisciplinary approaches, with physiotherapy input into positioning/postural control being one relevant component of a broader coordinated management strategy."},{"id": 6580,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding bone health/osteoporosis risk in children with more severe CP (e.g., GMFCS Level IV-V)?","options": [{"key": "A","text": "Bone health considerations are solely a medical/endocrinology responsibility with no relevance to physiotherapy practice"},{"key": "B","text": "Bone health has no relevance to CP management regardless of GMFCS level"},{"key": "C","text": "All children with CP show identical bone health status regardless of their mobility level"},{"key": "D","text": "Increased risk related to reduced weight-bearing activity, warranting consideration of appropriate loading interventions (e.g., standing programs) as part of comprehensive management"}],"correct": "D","explanation": "Reduced weight-bearing activity in more severely affected children increases osteoporosis/fracture risk, making appropriate loading interventions (like standing programs) a relevant physiotherapy consideration within comprehensive bone health management."},{"id": 6581,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Hard","question": "Which of the following describes an important consideration regarding pain assessment in children with CP, particularly those with limited verbal communication ability?","options": [{"key": "A","text": "Pain assessment is irrelevant to comprehensive CP management"},{"key": "B","text": "Only relying on caregiver assumption without any structured assessment approach"},{"key": "C","text": "Assuming children with CP and limited communication cannot experience or need assessment for pain"},{"key": "D","text": "Requires careful use of appropriate observational/behavioral pain assessment tools when self-report is limited or unavailable"}],"correct": "D","explanation": "Given communication limitations in some children with CP, appropriate observational/behavioral pain assessment tools are important for adequate pain recognition, given that pain (from various sources including musculoskeletal issues) can be underrecognized in this population."},{"id": 6582,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the potential relationship between spasticity management and improvement in caregiving ease/burden for children with more significant CP-related impairment?","options": [{"key": "A","text": "Caregiving considerations are entirely irrelevant to spasticity management goal-setting"},{"key": "B","text": "Spasticity management should only ever target the child's own functional goals, never considering caregiving impact"},{"key": "C","text": "Effective spasticity management can sometimes improve ease of caregiving tasks (positioning, hygiene, dressing), an important consideration alongside direct functional goals for the child"},{"key": "D","text": "Caregiving ease has no relationship whatsoever to spasticity intervention outcomes"}],"correct": "C","explanation": "Alongside goals directly targeting the child's own function, spasticity management can also meaningfully improve caregiving ease (positioning, hygiene, transfers), an important, valid consideration particularly relevant for children with more significant impairment requiring greater caregiver assistance."},{"id": 6583,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the potential impact of CP on participation in recreational/sports activities, and the relevance of adapted physical activity approaches?","options": [{"key": "A","text": "Adapted physical activity has no evidence of benefit for children with CP"},{"key": "B","text": "Adapted sports/recreational activity participation can support physical fitness, social engagement, and quality of life, an important consideration within holistic CP management"},{"key": "C","text": "Children with CP should never participate in any sports or recreational physical activity"},{"key": "D","text": "Only children with the mildest CP presentation (GMFCS Level I) can ever participate in any adapted sports activity"}],"correct": "B","explanation": "Supporting participation in appropriately adapted sports/recreational activities offers physical, social, and quality-of-life benefits, representing an important, achievable goal across various severity levels within holistic CP management."},{"id": 6584,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding fatigue as it may relate to children with CP, particularly during physically demanding tasks/therapy sessions?","options": [{"key": "A","text": "Increased energy expenditure often required for movement in CP can contribute to fatigue, relevant to appropriately pacing therapy and daily activity demands"},{"key": "B","text": "Fatigue is never a relevant consideration for children with CP"},{"key": "C","text": "Assuming identical energy expenditure/fatigue patterns to typically developing peers regardless of the CP-related movement pattern"},{"key": "D","text": "Fatigue considerations only apply to adult neurological populations, never to pediatric CP"}],"correct": "A","explanation": "The often higher energy cost of movement in CP (related to altered biomechanics, spasticity, and other factors) can contribute to fatigue, relevant to appropriately pacing therapeutic and daily activity demands."},{"id": 6585,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding co-treatment or coordinated approaches between physiotherapy and occupational therapy for children with CP?","options": [{"key": "A","text": "Only one discipline is ever needed for comprehensive CP management, with no role for the other"},{"key": "B","text": "Coordinated, complementary input addressing overlapping functional goals (e.g., combining gross motor and fine motor/self-care focus) supports comprehensive, efficient rehabilitation"},{"key": "C","text": "Coordinated care approaches have no evidence of additional benefit over isolated, uncoordinated individual discipline management"},{"key": "D","text": "Physiotherapy and occupational therapy should always work in complete isolation with no coordination or communication"}],"correct": "B","explanation": "Coordinated, complementary physiotherapy and occupational therapy input, addressing overlapping functional goals, supports more comprehensive and efficient rehabilitation for children with CP who often have needs spanning both gross and fine motor/self-care domains."},{"id": 6586,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best summarizes the overall contemporary approach to comprehensive CP management across the lifespan?","options": [{"key": "A","text": "A single fixed treatment protocol applied identically and unchanged from initial diagnosis through adulthood"},{"key": "B","text": "Individualized, evidence-informed, family-centered care addressing the evolving physical, functional, and psychosocial needs across the person's developmental trajectory into adulthood"},{"key": "C","text": "Management focus exclusively on early childhood, with no need for any consideration once school age is reached"},{"key": "D","text": "Purely impairment-focused management with no consideration of functional, participation, or psychosocial factors"}],"correct": "B","explanation": "Contemporary CP management emphasizes individualized, evidence-informed, family/person-centered care that evolves appropriately across the lifespan, addressing the full spectrum of physical, functional, and psychosocial needs from early childhood through adulthood."},{"id": 6587,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "Developmental Dysplasia of the Hip (DDH) risk factors include:","options": [{"key": "A","text": "Multiple prior pregnancies protecting against DDH"},{"key": "B","text": "Male gender predominantly"},{"key": "C","text": "No identifiable risk factors exist"},{"key": "D","text": "Breech presentation, female gender, and family history"}],"correct": "D","explanation": "Breech presentation, female sex, and positive family history are well-established DDH risk factors, informing targeted screening approaches."},{"id": 6588,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The Barlow test for DDH screening assesses for:","options": [{"key": "A","text": "Reducing an already dislocated hip"},{"key": "B","text": "Hip instability by attempting to dislocate a potentially dislocatable hip"},{"key": "C","text": "Assessing knee joint stability"},{"key": "D","text": "Assessing ankle range of motion"}],"correct": "B","explanation": "Barlow test applies gentle posterior pressure with adduction to assess if a reduced hip can be dislocated, indicating instability."},{"id": 6589,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The Ortolani test for DDH screening assesses for:","options": [{"key": "A","text": "Testing lower limb reflexes"},{"key": "B","text": "Dislocating a stable hip"},{"key": "C","text": "Assessing shoulder range of motion"},{"key": "D","text": "Reduction of an already dislocated hip back into the acetabulum"}],"correct": "D","explanation": "Ortolani test attempts to reduce a dislocated hip with abduction and gentle lift, producing a palpable 'clunk' if positive."},{"id": 6590,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Pavlik harness, used in DDH management, functions by:","options": [{"key": "A","text": "Maintaining the hip in flexion and abduction, promoting proper acetabular development"},{"key": "B","text": "Only used post-surgically, never as primary conservative treatment"},{"key": "C","text": "Providing rigid immobilization preventing any hip movement"},{"key": "D","text": "Maintaining the hip in extension and adduction"}],"correct": "A","explanation": "Pavlik harness maintains flexion/abduction positioning, promoting concentric reduction and proper acetabular development in infants with DDH."},{"id": 6591,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Untreated DDH can lead to which long-term complication in adulthood?","options": [{"key": "A","text": "Only cosmetic leg length discrepancy with no functional impact"},{"key": "B","text": "Complete spontaneous resolution with no need for any monitoring"},{"key": "C","text": "Early-onset secondary hip osteoarthritis"},{"key": "D","text": "No long-term consequence if the child appears to walk normally"}],"correct": "C","explanation": "Untreated DDH alters hip joint mechanics/coverage, predisposing to premature secondary osteoarthritis in adulthood."},{"id": 6592,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Easy","question": "Congenital Talipes Equinovarus (CTEV/clubfoot) is characterized by which combination of deformities?","options": [{"key": "A","text": "Equinus, varus, adduction, and cavus"},{"key": "B","text": "Only equinus deformity in isolation"},{"key": "C","text": "Valgus and abduction deformity"},{"key": "D","text": "Only cavus deformity in isolation"}],"correct": "A","explanation": "CTEV involves the classic combination of hindfoot equinus and varus, midfoot cavus, and forefoot adduction."},{"id": 6593,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "The Ponseti method for clubfoot treatment primarily involves:","options": [{"key": "A","text": "Only physiotherapy stretching without any casting component"},{"key": "B","text": "Immediate surgical correction as first-line treatment"},{"key": "C","text": "Only bracing without any preceding casting phase"},{"key": "D","text": "Serial gentle manipulation and casting, typically followed by Achilles tenotomy and bracing"}],"correct": "D","explanation": "Ponseti method uses sequential gentle manipulation/casting for correction, commonly followed by percutaneous tenotomy and maintenance bracing (Foot Abduction Brace)."},{"id": 6594,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "Following Ponseti casting correction of clubfoot, the Foot Abduction Brace is typically worn according to which general schedule?","options": [{"key": "A","text": "Only for 1 week total regardless of initial correction status"},{"key": "B","text": "Full-time initially (approximately 23 hours/day) for a period, then part-time (typically nighttime/naps) for several years"},{"key": "C","text": "Only during physiotherapy sessions with no other wear time"},{"key": "D","text": "Never required if casting correction was successful"}],"correct": "B","explanation": "Standard Ponseti bracing protocol involves initial near-full-time wear, transitioning to part-time (naps/nighttime) wear for an extended period (often until around age 4-5), critical for preventing relapse."},{"id": 6595,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Congenital muscular torticollis most commonly results from:","options": [{"key": "A","text": "Genetic chromosomal abnormality exclusively"},{"key": "B","text": "Sternocleidomastoid muscle fibrosis/shortening, often related to intrauterine positioning or birth trauma"},{"key": "C","text": "A central nervous system lesion exclusively"},{"key": "D","text": "Cervical vertebral fusion exclusively"}],"correct": "B","explanation": "Congenital muscular torticollis typically results from unilateral SCM fibrosis/shortening, presenting with characteristic head tilt/rotation posture."},{"id": 6596,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Physiotherapy management for congenital muscular torticollis primarily involves:","options": [{"key": "A","text": "Rigid neck bracing as the primary intervention"},{"key": "B","text": "Complete avoidance of any neck movement/handling"},{"key": "C","text": "Stretching exercises and repositioning techniques"},{"key": "D","text": "Immediate surgical release as first-line treatment in all cases"}],"correct": "C","explanation": "Conservative management with stretching and active repositioning techniques is first-line for congenital muscular torticollis, with surgery reserved for cases resistant to conservative management."},{"id": 6597,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding positional plagiocephaly, sometimes associated with congenital muscular torticollis?","options": [{"key": "A","text": "A condition that never responds to any conservative management approach"},{"key": "B","text": "A condition entirely unrelated to torticollis or positioning"},{"key": "C","text": "Always requiring surgical cranial correction regardless of severity"},{"key": "D","text": "Asymmetric head shape from positional preference, addressed through repositioning strategies alongside torticollis management"}],"correct": "D","explanation": "Plagiocephaly (asymmetric head shape) often co-occurs with torticollis due to positional preference, addressed through combined repositioning strategies alongside torticollis-specific treatment."},{"id": 6598,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "Idiopathic scoliosis in adolescents most commonly affects which population?","options": [{"key": "A","text": "Adolescent females during the pubertal growth spurt"},{"key": "B","text": "Infants exclusively"},{"key": "C","text": "Elderly adults exclusively"},{"key": "D","text": "Adolescent males predominantly"}],"correct": "A","explanation": "Adolescent Idiopathic Scoliosis (AIS) shows a notable female predominance, typically presenting/progressing during the pubertal growth spurt."},{"id": 6599,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Cobb angle is used to quantify:","options": [{"key": "A","text": "Ankle dorsiflexion range"},{"key": "B","text": "The degree of spinal curvature in scoliosis on standing radiographs"},{"key": "C","text": "Shoulder abduction range"},{"key": "D","text": "Hip joint range of motion"}],"correct": "B","explanation": "Cobb angle measurement is the standard radiographic method for quantifying scoliotic curve severity."},{"id": 6600,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "Bracing for adolescent idiopathic scoliosis is generally considered for curves within which approximate Cobb angle range in a skeletally immature patient?","options": [{"key": "A","text": "Less than 10 degrees"},{"key": "B","text": "Greater than 50 degrees, where surgery is instead typically favored"},{"key": "C","text": "No bracing is ever indicated for AIS regardless of curve magnitude"},{"key": "D","text": "Approximately 25-40 degrees"}],"correct": "D","explanation": "Bracing is generally considered for moderate curves (approximately 25-40°) in skeletally immature patients with growth remaining, aiming to prevent progression."},{"id": 6601,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Surgical spinal fusion for AIS is generally considered when the Cobb angle exceeds approximately:","options": [{"key": "A","text": "10 degrees"},{"key": "B","text": "20 degrees in all cases regardless of skeletal maturity"},{"key": "C","text": "45-50 degrees"},{"key": "D","text": "30 degrees regardless of any other clinical consideration"}],"correct": "C","explanation": "Surgical intervention is generally considered for larger curves (approximately 45-50°+), particularly with continued growth potential or significant progression risk."},{"id": 6602,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Legg-Calve-Perthes disease involves which pathological process affecting the hip?","options": [{"key": "A","text": "Traumatic hip fracture"},{"key": "B","text": "Idiopathic avascular necrosis of the proximal femoral epiphysis"},{"key": "C","text": "Bacterial infection of the hip joint"},{"key": "D","text": "Congenital hip dislocation"}],"correct": "B","explanation": "Perthes disease is idiopathic AVN of the femoral head epiphysis in children, undergoing phases of necrosis, fragmentation, and reossification/remodeling."},{"id": 6603,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Legg-Calve-Perthes disease typically presents in which age group and with which gender predominance?","options": [{"key": "A","text": "Girls aged 4-10 years predominantly"},{"key": "B","text": "Boys aged 4-10 years"},{"key": "C","text": "Infants under 1 year"},{"key": "D","text": "Adolescents of both genders equally"}],"correct": "B","explanation": "Perthes disease shows notable male predominance, typically presenting between ages 4-10 years."},{"id": 6604,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Slipped Capital Femoral Epiphysis (SCFE) typically occurs in which population?","options": [{"key": "A","text": "Elderly osteoporotic patients"},{"key": "B","text": "Young adult athletes with no growth plate involvement"},{"key": "C","text": "Obese adolescents during the pubertal growth spurt"},{"key": "D","text": "Neonates"}],"correct": "C","explanation": "SCFE classically occurs in overweight adolescents during rapid growth, with posteroinferior slippage of the femoral epiphysis relative to the metaphysis."},{"id": 6605,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which classic clinical sign is observed in SCFE regarding hip movement during flexion?","options": [{"key": "A","text": "Obligatory internal rotation occurring with hip flexion"},{"key": "B","text": "Obligatory external rotation of the hip occurring with hip flexion"},{"key": "C","text": "Complete absence of any hip flexion movement"},{"key": "D","text": "No movement abnormality whatsoever is present"}],"correct": "B","explanation": "As the hip is passively flexed in SCFE, it obligately externally rotates due to the altered anatomical relationship from the epiphyseal slippage, a classic diagnostic clinical finding."},{"id": 6606,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Blount's disease refers to:","options": [{"key": "A","text": "Pathological bowing of the tibia due to abnormal growth at the medial proximal tibial physis"},{"key": "B","text": "Lateral bowing of the femur exclusively"},{"key": "C","text": "Congenital hip dysplasia"},{"key": "D","text": "A variant term for clubfoot deformity"}],"correct": "A","explanation": "Blount's disease involves abnormal growth suppression at the medial proximal tibial physis, causing progressive pathological genu varum, distinct from physiological bowing."},{"id": 6607,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Physiological genu varum (bow-leg) in toddlers typically:","options": [{"key": "A","text": "Requires immediate surgical correction in all cases"},{"key": "B","text": "Always indicates Blount's disease requiring urgent intervention"},{"key": "C","text": "Persists unchanged throughout life without any resolution"},{"key": "D","text": "Resolves spontaneously by approximately 2-3 years of age as normal development progresses"}],"correct": "D","explanation": "Mild physiological genu varum is a normal developmental variant in toddlers that typically self-corrects by around 2-3 years, distinguishing it from pathological causes like Blount's disease."},{"id": 6608,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Physiological genu valgum (knock-knee) in children typically peaks around which age before resolving toward normal alignment?","options": [{"key": "A","text": "Birth, resolving by 1 year"},{"key": "B","text": "10 years, persisting unchanged into adulthood"},{"key": "C","text": "Adolescence, never resolving spontaneously"},{"key": "D","text": "3-4 years, resolving by approximately 7-8 years"}],"correct": "D","explanation": "Physiological genu valgum typically peaks around 3-4 years and gradually resolves toward more typical alignment by approximately 7-8 years."},{"id": 6609,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Osgood-Schlatter disease is best described as:","options": [{"key": "A","text": "A bacterial infection of the knee joint"},{"key": "B","text": "A congenital knee deformity present from birth"},{"key": "C","text": "A condition exclusively affecting the hip joint"},{"key": "D","text": "A traction apophysitis at the tibial tuberosity from repetitive quadriceps pull, common in active adolescents"}],"correct": "D","explanation": "Osgood-Schlatter disease is an overuse traction injury at the tibial tuberosity apophysis, common in active, growing adolescents, particularly those involved in jumping/running sports."},{"id": 6610,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Sever's disease (calcaneal apophysitis) occurs in which population?","options": [{"key": "A","text": "Adults over 50 years exclusively"},{"key": "B","text": "Infants under 1 year exclusively"},{"key": "C","text": "Active children/adolescents, typically 8-14 years, during growth"},{"key": "D","text": "A condition unrelated to any growth or activity factors"}],"correct": "C","explanation": "Sever's disease is a traction apophysitis at the calcaneal growth plate, common in active growing children/adolescents, particularly with heel-impact activities."},{"id": 6611,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Metatarsus adductus in infants is characterized by:","options": [{"key": "A","text": "Vertical dislocation of the talus"},{"key": "B","text": "Hindfoot valgus deformity as the primary feature"},{"key": "C","text": "Medial deviation of the forefoot relative to the hindfoot, often flexible and resolving spontaneously"},{"key": "D","text": "A rigid equinovarus deformity of the entire foot identical to clubfoot"}],"correct": "C","explanation": "Metatarsus adductus involves isolated forefoot adduction, typically flexible and often resolving without specific treatment, distinct from the more complex clubfoot deformity."},{"id": 6612,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Easy","question": "Congenital vertical talus differs from clubfoot in that it presents as:","options": [{"key": "A","text": "A rigid flatfoot ('rocker-bottom' deformity) from dorsal talar dislocation"},{"key": "B","text": "A condition affecting only ligamentous laxity without any bony abnormality"},{"key": "C","text": "Isolated forefoot adduction without any hindfoot involvement"},{"key": "D","text": "An equinovarus deformity identical in presentation to clubfoot"}],"correct": "A","explanation": "Congenital vertical talus presents as a rigid flatfoot deformity from dorsal navicular dislocation on the talus, requiring different management approach than clubfoot."},{"id": 6613,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Intoeing gait in children can result from different causes depending on age; in infants, the most common cause is typically:","options": [{"key": "A","text": "Femoral anteversion"},{"key": "B","text": "Always indicating an underlying neurological condition"},{"key": "C","text": "Metatarsus adductus"},{"key": "D","text": "Internal tibial torsion primarily"}],"correct": "C","explanation": "In infants, metatarsus adductus is a common contributor to intoeing appearance, while internal tibial torsion (toddlers) and femoral anteversion (older children) become more relevant at later ages."},{"id": 6614,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Internal tibial torsion, a common cause of intoeing in toddlers, typically:","options": [{"key": "A","text": "Resolves spontaneously with growth in the majority of cases without specific intervention"},{"key": "B","text": "Always requires surgical correction regardless of severity"},{"key": "C","text": "Indicates an underlying serious neurological condition in all cases"},{"key": "D","text": "Never improves without bracing intervention"}],"correct": "A","explanation": "Internal tibial torsion in toddlers typically resolves spontaneously with growth in most cases, generally managed with observation rather than active intervention."},{"id": 6615,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Femoral anteversion, a common cause of intoeing in older children, typically presents with which characteristic finding on hip rotation assessment?","options": [{"key": "A","text": "Increased external rotation with decreased internal rotation range"},{"key": "B","text": "Complete absence of any hip rotation capability"},{"key": "C","text": "Increased internal rotation with correspondingly decreased external rotation range"},{"key": "D","text": "No asymmetry in hip rotation range whatsoever"}],"correct": "C","explanation": "Femoral anteversion characteristically shows increased internal hip rotation range with correspondingly reduced external rotation, contributing to the intoeing gait pattern."},{"id": 6616,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Juvenile Idiopathic Arthritis (JIA) diagnostic criteria require arthritis onset before what age and persisting for at least how long?","options": [{"key": "A","text": "Onset only after age 16, with no relevance to younger children"},{"key": "B","text": "Persisting for only 24 hours"},{"key": "C","text": "Onset before age 5 exclusively"},{"key": "D","text": "Onset before age 16, persisting at least 6 weeks"}],"correct": "D","explanation": "JIA diagnostic criteria require arthritis onset before age 16, persisting for at least 6 weeks, with other potential causes appropriately excluded."},{"id": 6617,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Osteogenesis Imperfecta, relevant to pediatric orthopedic assessment given its bone fragility, primarily results from mutations affecting:","options": [{"key": "A","text": "Muscle protein structure exclusively, with no bone-specific involvement"},{"key": "B","text": "Growth hormone production exclusively"},{"key": "C","text": "Type I collagen synthesis"},{"key": "D","text": "Vitamin D metabolism exclusively"}],"correct": "C","explanation": "OI results from mutations affecting type I collagen, causing bone fragility with recurrent low-energy fractures, an important consideration in differential diagnosis of recurrent pediatric fractures."},{"id": 6618,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding differentiating Osteogenesis Imperfecta-related fractures from non-accidental injury (child abuse) in a child presenting with recurrent fractures?","options": [{"key": "A","text": "Assuming all recurrent pediatric fractures always indicate Osteogenesis Imperfecta with no other differential consideration"},{"key": "B","text": "This differentiation has no clinical relevance or importance"},{"key": "C","text": "Assuming all recurrent pediatric fractures always indicate non-accidental injury with no other differential consideration"},{"key": "D","text": "Careful clinical assessment considering fracture pattern, associated features (e.g., blue sclera, family history), and appropriate multidisciplinary evaluation"}],"correct": "D","explanation": "Careful, comprehensive clinical assessment (fracture pattern, associated OI features, family history, and appropriate multidisciplinary evaluation) is important for appropriately differentiating OI from potential non-accidental injury in children presenting with recurrent fractures."},{"id": 6619,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding hip surveillance/monitoring recommendations for children with significant neuromuscular conditions (e.g., severe CP) at risk for hip displacement?","options": [{"key": "A","text": "Regular structured surveillance protocols, often incorporating clinical and radiographic monitoring, support early detection allowing timely intervention"},{"key": "B","text": "Hip displacement risk is identical regardless of the underlying neuromuscular condition severity"},{"key": "C","text": "No monitoring protocols exist for hip displacement risk in neuromuscular conditions"},{"key": "D","text": "Hip surveillance is only relevant for children without any neuromuscular condition"}],"correct": "A","explanation": "Structured hip surveillance protocols (combining clinical and radiographic monitoring at appropriate intervals based on risk level) support early detection of progressive hip displacement, allowing timely intervention before irreversible dislocation in at-risk neuromuscular populations."},{"id": 6620,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding leg length discrepancy assessment/management in growing children?","options": [{"key": "A","text": "Careful assessment distinguishing true versus apparent discrepancy, alongside monitoring for progression given ongoing growth potential, informs appropriate management planning"},{"key": "B","text": "Leg length discrepancy assessment has no relevance to pediatric orthopedic practice"},{"key": "C","text": "Leg length discrepancy always remains completely static throughout the remainder of childhood growth"},{"key": "D","text": "All leg length discrepancies in children require immediate surgical correction regardless of magnitude"}],"correct": "A","explanation": "Given ongoing growth potential in children, careful assessment (distinguishing true from apparent discrepancy) and monitoring for progression informs appropriate management planning, which may range from observation to various orthopedic interventions depending on magnitude and cause."},{"id": 6621,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the general management approach for most cases of physiological (non-pathological) lower limb variations like mild genu varum/valgum or intoeing in young children?","options": [{"key": "A","text": "Reassurance and monitoring, as the majority resolve spontaneously with normal growth without requiring active intervention"},{"key": "B","text": "Surgical correction at the first presentation regardless of the likely physiological, self-resolving nature"},{"key": "C","text": "Casting similar to clubfoot management for all lower limb variations"},{"key": "D","text": "Immediate bracing for all cases regardless of severity or physiological nature"}],"correct": "A","explanation": "Most physiological lower limb variations in young children require only reassurance and monitoring, given their typical spontaneous resolution with growth, reserving more active intervention for atypical/pathological presentations."},{"id": 6622,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important red flag finding that would suggest a pathological rather than physiological cause for lower limb bowing in a child, warranting further investigation?","options": [{"key": "A","text": "Symmetric, mild bowing that resolves by the expected age of 2-3 years"},{"key": "B","text": "Normal growth parameters and developmental milestones"},{"key": "C","text": "Asymmetry between limbs, short stature, or progression/persistence beyond the typically expected resolution age"},{"key": "D","text": "Family history of similar bowing that resolved without any specific intervention"}],"correct": "C","explanation": "Asymmetric involvement, short stature, or persistence/progression beyond the typical physiological resolution timeframe are red flags suggesting a pathological cause (e.g., Blount's disease, rickets) requiring further investigation, distinguishing from benign physiological variation."},{"id": 6623,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy assessment of gait in a child presenting with a limp, given the broad differential diagnosis for pediatric limp?","options": [{"key": "A","text": "Assuming all pediatric limp presentations have an identical, single underlying cause requiring the same management approach"},{"key": "B","text": "Comprehensive assessment considering the child's age, history, and examination findings, given the wide range of potential causes from benign to serious"},{"key": "C","text": "Gait assessment has no relevance to evaluating a child presenting with a limp"},{"key": "D","text": "Physiotherapy assessment should never be involved in evaluating a child with an acute limp presentation"}],"correct": "B","explanation": "Given the broad differential diagnosis for pediatric limp (ranging from benign transient synovitis to more serious conditions like septic arthritis or SCFE), comprehensive assessment considering age-appropriate differential diagnosis is important, often within a broader medical evaluation context."},{"id": 6624,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the general approach to conservative (non-surgical) management trials for many pediatric orthopedic conditions before considering surgical intervention?","options": [{"key": "A","text": "Conservative management is never appropriate for any pediatric orthopedic condition"},{"key": "B","text": "Surgery should always be the first-line approach for any pediatric orthopedic condition regardless of severity"},{"key": "C","text": "Many conditions (e.g., mild scoliosis, physiological variations, many cases of torticollis) are appropriately managed initially with conservative approaches, reserving surgery for specific indications/failure of conservative management"},{"key": "D","text": "All pediatric orthopedic conditions resolve identically regardless of whether conservative or surgical management is pursued"}],"correct": "C","explanation": "For many pediatric orthopedic conditions, appropriately trialed conservative management approaches (physiotherapy, bracing, casting, observation) are often first-line, with surgical intervention reserved for specific indications or failure of adequate conservative management trial."},{"id": 6625,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the recommended infant sleep positioning to reduce SIDS risk, which is also relevant to considering plagiocephaly prevention strategies?","options": [{"key": "A","text": "Side-lying sleeping is the universally recommended position for all infants"},{"key": "B","text": "Prone (stomach) sleeping is recommended for reducing SIDS risk"},{"key": "C","text": "Supine (back) sleeping, with varied positioning during awake, supervised tummy time to reduce plagiocephaly risk"},{"key": "D","text": "No specific sleep positioning recommendations exist for infants"}],"correct": "C","explanation": "Supine sleeping is recommended for SIDS risk reduction, with supervised tummy time during awake periods helping balance this with plagiocephaly prevention and promoting developmental skill practice."},{"id": 6626,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "Which of the following describes 'tummy time' recommendations for infants, relevant to both motor development and plagiocephaly prevention?","options": [{"key": "A","text": "Tummy time should only ever be practiced during sleep, contradicting safe sleep guidelines"},{"key": "B","text": "Complete avoidance of any prone positioning throughout infancy"},{"key": "C","text": "Regular supervised prone positioning during awake periods, gradually increased, supporting upper body strength and head shape variation"},{"key": "D","text": "Only relevant after 6 months of age, never recommended earlier"}],"correct": "C","explanation": "Regular supervised tummy time during awake periods, introduced early and gradually increased, supports upper body/neck strength development while helping vary head positioning to reduce plagiocephaly risk."},{"id": 6627,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding car seat/positioning device use time limits, relevant to infant musculoskeletal and positional health?","options": [{"key": "A","text": "No limits or considerations exist regarding time spent in car seats or similar positioning devices"},{"key": "B","text": "Positioning device use has no relevance to physiotherapy practice or infant development considerations"},{"key": "C","text": "Excessive prolonged time in restrictive positioning devices (car seats, bouncers) outside of travel needs is generally discouraged given potential impact on positional variety and motor development opportunity"},{"key": "D","text": "These devices should always be used for extended periods throughout the day to maximize infant safety"}],"correct": "C","explanation": "Minimizing excessive time in restrictive positioning devices outside of necessary travel supports adequate positional variety and movement opportunity important for typical motor development, a relevant consideration in family education."},{"id": 6628,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes calcaneovalgus foot deformity, a common benign positional foot finding in newborns?","options": [{"key": "A","text": "An identical, rigid deformity to congenital vertical talus requiring surgical correction"},{"key": "B","text": "A deformity always indicating an underlying neurological abnormality"},{"key": "C","text": "A deformity that always requires immediate serial casting identical to clubfoot management"},{"key": "D","text": "A flexible, positional deformity with excessive dorsiflexion/eversion, typically resolving spontaneously without specific treatment"}],"correct": "D","explanation": "Calcaneovalgus foot is a common, flexible, positional newborn foot deformity (from intrauterine positioning) that typically resolves spontaneously, distinct from more significant structural deformities."},{"id": 6629,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration in distinguishing flexible flatfoot (common and often benign in young children) from rigid/pathological flatfoot?","options": [{"key": "A","text": "All pediatric flatfoot presentations are identical and require the same management approach regardless of flexibility"},{"key": "B","text": "Rigid flatfoot is always a normal, benign finding requiring no further evaluation"},{"key": "C","text": "Flexible flatfoot always requires surgical correction in young children"},{"key": "D","text": "Assessing for arch reconstitution on toe-standing or non-weight-bearing (flexible) versus persistent flattening regardless of position (rigid, potentially pathological)"}],"correct": "D","explanation": "Assessing arch reconstitution with toe-standing or non-weight-bearing helps distinguish common, typically benign flexible flatfoot from rigid flatfoot, which may indicate underlying pathology (e.g., tarsal coalition) warranting further evaluation."},{"id": 6630,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the natural history of most cases of flexible pediatric flatfoot?","options": [{"key": "A","text": "Flexible flatfoot is always associated with an underlying serious pathological condition"},{"key": "B","text": "All cases of flexible flatfoot require orthotic intervention regardless of symptoms"},{"key": "C","text": "Most cases are asymptomatic and do not require specific treatment, with arch development continuing through childhood in many children"},{"key": "D","text": "Flexible flatfoot always progresses to significant disability in adulthood without early intervention"}],"correct": "C","explanation": "Most flexible pediatric flatfoot is asymptomatic and does not require specific treatment, as arch development is a normal variable process through childhood, with intervention generally reserved for symptomatic cases."},{"id": 6631,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding shoe recommendations for young children just beginning to walk?","options": [{"key": "A","text": "Shoes have no relevance to foot development considerations in early walkers"},{"key": "B","text": "Complicated, expensive corrective footwear is required for all typically developing early walkers"},{"key": "C","text": "Simple, flexible footwear (or even barefoot in safe environments) is generally recommended over rigid, restrictive shoes to support natural foot development"},{"key": "D","text": "Rigid, highly supportive shoes with significant arch support are always recommended for all beginning walkers"}],"correct": "C","explanation": "Simple, flexible footwear allowing natural foot movement (or safe barefoot opportunities) is generally recommended for early walkers, rather than rigid, overly supportive shoes, supporting natural foot muscle/arch development."},{"id": 6632,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Nursemaid's elbow (radial head subluxation), common in young children, typically results from which mechanism?","options": [{"key": "A","text": "Sudden longitudinal traction on the extended, pronated arm/wrist (e.g., being pulled up by the hand)"},{"key": "B","text": "Chronic repetitive overuse over many months"},{"key": "C","text": "A condition unrelated to any specific traumatic mechanism"},{"key": "D","text": "A high-energy fall from significant height"}],"correct": "A","explanation": "Nursemaid's elbow classically results from sudden longitudinal traction on the extended/pronated forearm, common when a young child is lifted or pulled by the hand/wrist."},{"id": 6633,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the typical management approach for nursemaid's elbow (radial head subluxation)?","options": [{"key": "A","text": "No treatment is available; the condition must resolve entirely on its own without any intervention"},{"key": "B","text": "Immediate surgical intervention is always required"},{"key": "C","text": "Gentle reduction maneuver (supination/flexion technique) typically performed by a trained clinician, often with prompt symptom resolution"},{"key": "D","text": "Prolonged casting for several weeks is the standard management approach"}],"correct": "C","explanation": "Nursemaid's elbow typically responds well to a simple, gentle reduction maneuver (e.g., supination-flexion technique) performed by a trained clinician, often with prompt symptom relief."},{"id": 6634,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy assessment/management following successful reduction of nursemaid's elbow?","options": [{"key": "A","text": "Complete immobilization for several months is required following reduction"},{"key": "B","text": "Generally minimal ongoing intervention is needed following successful reduction, with education regarding avoiding the causative traction mechanism to prevent recurrence"},{"key": "C","text": "The condition always requires surgical intervention despite successful initial reduction"},{"key": "D","text": "Extensive, prolonged physiotherapy rehabilitation is always required following reduction"}],"correct": "B","explanation": "Following successful reduction, minimal ongoing intervention is typically needed, with an emphasis on parent/caregiver education regarding avoiding the specific traction mechanism to prevent recurrence, which is common in young children."},{"id": 6635,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes Panner's disease, a condition sometimes relevant in pediatric elbow presentations?","options": [{"key": "A","text": "A condition identical to Osgood-Schlatter disease but affecting the elbow instead of the knee"},{"key": "B","text": "A condition affecting the hip joint exclusively"},{"key": "C","text": "A term with no relevance to any pediatric orthopedic condition"},{"key": "D","text": "Avascular necrosis of the capitellum (humeral) in children, sometimes related to repetitive throwing/overuse activity"}],"correct": "D","explanation": "Panner's disease involves avascular necrosis of the capitellum, sometimes associated with repetitive elbow loading activities (e.g., throwing sports) in the pediatric population."},{"id": 6636,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Little League elbow, a term describing overuse elbow injury in young throwing athletes, typically involves stress at which anatomical location?","options": [{"key": "A","text": "The shoulder joint exclusively, with no elbow involvement"},{"key": "B","text": "Medial epicondyle apophysis, from repetitive valgus stress during throwing"},{"key": "C","text": "Lateral epicondyle exclusively"},{"key": "D","text": "The wrist joint exclusively, with no elbow involvement"}],"correct": "B","explanation": "Little League elbow describes overuse injury/traction apophysitis at the medial epicondyle from repetitive valgus stress during the throwing motion, common in young pitchers."},{"id": 6637,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding load management/pitch count guidelines relevant to preventing overuse injuries like Little League elbow in young throwing athletes?","options": [{"key": "A","text": "Maximum possible pitching volume should always be encouraged regardless of age or load management guidelines"},{"key": "B","text": "No load management considerations are relevant for young athletes regardless of activity volume"},{"key": "C","text": "Age-appropriate pitch count/load management guidelines help reduce excessive repetitive stress and associated overuse injury risk"},{"key": "D","text": "Pitch count has no relationship to overuse injury risk in young throwing athletes"}],"correct": "C","explanation": "Age-appropriate pitch count and load management guidelines (established by relevant sporting bodies) aim to reduce excessive repetitive throwing stress, helping prevent overuse injuries like Little League elbow in young athletes."},{"id": 6638,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding assessment of a child presenting with an acute, atraumatic limp and fever, given the differential diagnosis including potentially serious conditions?","options": [{"key": "A","text": "This presentation never requires any urgent medical evaluation regardless of clinical findings"},{"key": "B","text": "Assuming all cases of limp with fever in children represent the same benign condition requiring no urgent evaluation"},{"key": "C","text": "Fever is irrelevant to the evaluation and differential diagnosis of pediatric limp"},{"key": "D","text": "Requires prompt, careful evaluation to differentiate between various causes including septic arthritis (a surgical emergency) and more benign conditions like transient synovitis"}],"correct": "D","explanation": "Acute atraumatic limp with fever requires prompt, careful clinical evaluation given the important differential diagnosis including septic arthritis (requiring urgent surgical management) versus more benign causes, informed by clinical prediction tools like Kocher criteria alongside overall clinical judgment."},{"id": 6639,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes Kohler's disease, a condition sometimes relevant in pediatric foot presentations?","options": [{"key": "A","text": "A condition affecting the metatarsal heads exclusively"},{"key": "B","text": "A term identical to Sever's disease affecting a different location"},{"key": "C","text": "Avascular necrosis of the tarsal navicular bone in young children, typically self-limiting"},{"key": "D","text": "A condition with no relevance to pediatric orthopedic practice"}],"correct": "C","explanation": "Kohler's disease is a self-limiting avascular necrosis of the navicular bone occurring in young children, generally managed conservatively given its typically benign, self-resolving course."},{"id": 6640,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes Freiberg's disease, another condition sometimes relevant in pediatric/adolescent foot presentations?","options": [{"key": "A","text": "Avascular necrosis of a metatarsal head (most commonly the second), typically presenting in adolescence"},{"key": "B","text": "A term identical to Kohler's disease affecting the same anatomical structure"},{"key": "C","text": "A condition affecting the hip joint exclusively"},{"key": "D","text": "A condition exclusively affecting adult patients, never adolescents"}],"correct": "A","explanation": "Freiberg's disease involves AVN of a metatarsal head (most commonly second), typically presenting in adolescents, particularly females, sometimes related to repetitive forefoot loading."},{"id": 6641,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding physiotherapy management approach for many self-limiting pediatric apophyseal conditions (e.g., Osgood-Schlatter, Sever's disease)?","options": [{"key": "A","text": "Complete, prolonged cessation of all physical activity is always necessary regardless of symptom severity"},{"key": "B","text": "No management approach exists; these conditions must simply be endured without any intervention"},{"key": "C","text": "Immediate surgical intervention is always required for these conditions"},{"key": "D","text": "Activity modification, appropriate load management, stretching, and education regarding the generally self-limiting nature, while symptoms are present"}],"correct": "D","explanation": "Management of common pediatric apophyseal overuse conditions typically involves activity modification/load management, targeted stretching, and education about the generally self-limiting nature (resolving with growth plate closure), reserving more invasive intervention for atypical/severe cases."},{"id": 6642,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding growth plate (physeal) injuries in children, given their unique vulnerability compared to adult bone injury patterns?","options": [{"key": "A","text": "Growth plate injuries never require any specific classification system or particular management consideration"},{"key": "B","text": "Growth plates have no particular vulnerability or clinical significance different from mature adult bone"},{"key": "C","text": "All growth plate injuries in children are equivalent to simple adult fractures with no distinct considerations"},{"key": "D","text": "Growth plate injuries carry potential risk of growth disturbance, requiring careful classification (e.g., Salter-Harris) and appropriate management/monitoring"}],"correct": "D","explanation": "Growth plate (physeal) injuries carry unique potential for growth disturbance given the vulnerability of this actively growing structure, requiring appropriate classification (e.g., Salter-Harris system) and careful management/monitoring distinct from typical adult fracture considerations."},{"id": 6643,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding pediatric fracture healing potential compared to adult fracture healing?","options": [{"key": "A","text": "Children show identical healing rates and remodeling potential to adults with no distinguishing considerations"},{"key": "B","text": "Remodeling potential has no relevance to pediatric fracture management decision-making"},{"key": "C","text": "Children generally show faster healing and greater remodeling potential compared to adults, influencing management approach differences"},{"key": "D","text": "Children always show slower fracture healing compared to adults"}],"correct": "C","explanation": "Children generally demonstrate faster fracture healing and greater bone remodeling potential compared to adults, an important consideration influencing management approach (e.g., acceptable degree of angulation) differences between pediatric and adult fracture care."},{"id": 6644,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the greenstick fracture pattern, common in pediatric long bone injuries?","options": [{"key": "A","text": "An incomplete fracture pattern where the bone bends and partially breaks, related to the greater flexibility of immature pediatric bone"},{"key": "B","text": "A term unrelated to any pediatric-specific fracture consideration"},{"key": "C","text": "A complete fracture pattern identical to typical adult fracture presentation"},{"key": "D","text": "A fracture pattern exclusively seen in adult bone, never in children"}],"correct": "A","explanation": "Greenstick fractures represent an incomplete fracture pattern characteristic of the more flexible, pliable nature of immature pediatric bone compared to more brittle adult bone."},{"id": 6645,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy involvement following pediatric fracture management, once appropriate healing has occurred?","options": [{"key": "A","text": "Addressing any residual joint stiffness, muscle weakness, or functional limitation, adapted appropriately to the child's age and specific injury"},{"key": "B","text": "Identical rehabilitation protocols to adult fracture rehabilitation should always be applied without any pediatric-specific adaptation"},{"key": "C","text": "Physiotherapy is never relevant following pediatric fracture healing given children's inherently rapid recovery"},{"key": "D","text": "No functional consequences ever occur following pediatric fracture healing, eliminating any need for rehabilitation consideration"}],"correct": "A","explanation": "While children generally show good fracture healing/remodeling potential, physiotherapy may still be relevant for addressing any residual stiffness, weakness, or functional limitation following certain fractures, with approach appropriately adapted to the child's age and specific injury characteristics."},{"id": 6646,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding parent/caregiver education as a component of managing common self-limiting pediatric orthopedic conditions (e.g., physiological bowing, flexible flatfoot, transient toe walking)?","options": [{"key": "A","text": "Parent education has no relevance to managing these common pediatric orthopedic presentations"},{"key": "B","text": "Providing no information or reassurance to concerned parents is the appropriate clinical approach"},{"key": "C","text": "All parents should be told these conditions definitely require surgical intervention regardless of the actual clinical presentation"},{"key": "D","text": "Clear education about the typically benign, self-resolving nature helps address parental concern while supporting appropriate monitoring without unnecessary intervention"}],"correct": "D","explanation": "Clear, appropriate parent/caregiver education about the generally benign, self-limiting nature of many common pediatric orthopedic variations helps address understandable parental concern while supporting appropriate watchful monitoring rather than unnecessary intervention."},{"id": 6647,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Neural tube defects result from:","options": [{"key": "A","text": "A condition unrelated to any developmental process"},{"key": "B","text": "Failure of complete closure of the neural tube during early embryonic development"},{"key": "C","text": "Genetic factors with no relationship to embryonic development timing"},{"key": "D","text": "A condition occurring exclusively in the third trimester of pregnancy"}],"correct": "B","explanation": "Neural tube defects arise from incomplete neural tube closure during early embryonic development (typically within the first month of gestation)."},{"id": 6648,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Folic acid supplementation during pregnancy is recommended primarily to:","options": [{"key": "A","text": "Only relevant in the third trimester of pregnancy"},{"key": "B","text": "Reduce the risk of neural tube defects"},{"key": "C","text": "Have no established relationship to neural tube defect risk"},{"key": "D","text": "Only prevent maternal anemia with no fetal benefit"}],"correct": "B","explanation": "Adequate folic acid intake (particularly periconceptionally) is well-established to reduce neural tube defect risk, informing public health supplementation recommendations."},{"id": 6649,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Spina bifida occulta refers to:","options": [{"key": "A","text": "A form always causing severe paralysis"},{"key": "B","text": "A mild form with incomplete vertebral arch closure without externally visible neural tissue herniation"},{"key": "C","text": "The most severe form with significant neural tissue protrusion"},{"key": "D","text": "A term unrelated to any spinal defect classification"}],"correct": "B","explanation": "Spina bifida occulta is the mildest form, often asymptomatic and incidentally discovered, with incomplete vertebral fusion but no visible neural tissue herniation."},{"id": 6650,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Meningocele refers to:","options": [{"key": "A","text": "Herniation of meninges (without neural tissue) through the vertebral defect"},{"key": "B","text": "Complete absence of any spinal defect"},{"key": "C","text": "A term identical to spina bifida occulta"},{"key": "D","text": "Herniation of both meninges and neural tissue"}],"correct": "A","explanation": "Meningocele involves protrusion of meninges (CSF-filled sac) without neural tissue, generally associated with better prognosis than myelomeningocele."},{"id": 6651,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Hard","question": "Myelomeningocele, the most severe common form of spina bifida, involves:","options": [{"key": "A","text": "Only bony defect without any soft tissue involvement"},{"key": "B","text": "A condition never causing any functional neurological impairment"},{"key": "C","text": "Herniation of both meninges and neural tissue (spinal cord/nerve roots) through the defect"},{"key": "D","text": "Isolated skin abnormality without any deeper structural involvement"}],"correct": "C","explanation": "Myelomeningocele involves protrusion of both meninges and neural tissue, typically causing significant neurological deficit below the lesion level."},{"id": 6652,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The neurological deficit pattern in myelomeningocele primarily depends on:","options": [{"key": "A","text": "Only the infant's birth weight"},{"key": "B","text": "The specific spinal level of the lesion"},{"key": "C","text": "A factor unrelated to the specific lesion characteristics"},{"key": "D","text": "Only the mother's age at delivery"}],"correct": "B","explanation": "Similar to traumatic spinal cord injury, the level of the myelomeningocele lesion largely determines the resulting motor/sensory deficit pattern below that level."},{"id": 6653,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Chiari II malformation, commonly associated with myelomeningocele, involves:","options": [{"key": "A","text": "Downward displacement of cerebellar tissue and brainstem structures into the upper spinal canal"},{"key": "B","text": "A term identical to hydrocephalus with no distinct pathological features"},{"key": "C","text": "A condition entirely unrelated to myelomeningocele"},{"key": "D","text": "A condition affecting only the lumbar spine, unrelated to the brain/brainstem"}],"correct": "A","explanation": "Chiari II malformation involves downward herniation of cerebellar/brainstem tissue through the foramen magnum, commonly associated with myelomeningocele and contributing to hydrocephalus risk."},{"id": 6654,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Hydrocephalus, frequently associated with myelomeningocele, results primarily from:","options": [{"key": "A","text": "Disrupted CSF circulation dynamics, often related to the associated Chiari II malformation"},{"key": "B","text": "A condition entirely unrelated to any CSF flow considerations"},{"key": "C","text": "A condition that always resolves spontaneously without requiring any intervention"},{"key": "D","text": "Only occurring in children without any spinal defect"}],"correct": "A","explanation": "Hydrocephalus in myelomeningocele commonly relates to disrupted CSF flow dynamics associated with the Chiari II malformation, often requiring shunt management."},{"id": 6655,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Ventriculoperitoneal (VP) shunt placement, used to manage hydrocephalus, functions by:","options": [{"key": "A","text": "Only relevant for adult hydrocephalus, never used in pediatric management"},{"key": "B","text": "Diverting excess CSF from the ventricles to the peritoneal cavity for absorption"},{"key": "C","text": "Curing the underlying Chiari malformation completely"},{"key": "D","text": "Directly repairing the underlying neural tube defect"}],"correct": "B","explanation": "VP shunts divert excess CSF from the cerebral ventricles to the peritoneal cavity, managing hydrocephalus by relieving pressure from CSF accumulation."},{"id": 6656,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes important signs of potential shunt malfunction that physiotherapists should be aware of when working with a child with a VP shunt?","options": [{"key": "A","text": "Headache, vomiting, altered consciousness/behavior, or lethargy, requiring urgent medical evaluation"},{"key": "B","text": "Shunt malfunction never occurs once initially placed, requiring no ongoing vigilance"},{"key": "C","text": "No specific signs exist that would indicate shunt malfunction"},{"key": "D","text": "Only fever indicates shunt malfunction, with no other relevant signs"}],"correct": "A","explanation": "Awareness of shunt malfunction signs (headache, vomiting, altered consciousness/behavior changes) is important for physiotherapists working with children with VP shunts, given the urgency of appropriate medical evaluation if malfunction is suspected."},{"id": 6657,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Physiotherapy assessment for a child with myelomeningocele typically includes evaluation of:","options": [{"key": "A","text": "Assessment limited exclusively to upper limb function"},{"key": "B","text": "Motor/sensory level, tone, joint range of motion, and functional mobility, similar in principle to spinal cord injury assessment"},{"key": "C","text": "Only assessment of the shunt itself, with no broader physical evaluation"},{"key": "D","text": "Only cognitive function assessment with no physical component"}],"correct": "B","explanation": "Comprehensive physiotherapy assessment addresses the neurological level of involvement, associated tone/ROM findings, and functional mobility status, sharing conceptual similarities with spinal cord injury assessment approaches."},{"id": 6658,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Bladder/bowel dysfunction, a common feature in myelomeningocele given the associated spinal cord involvement, often requires:","options": [{"key": "A","text": "Multidisciplinary management including intermittent catheterization and bowel management programs"},{"key": "B","text": "No specific management is ever needed regardless of the neurological level involved"},{"key": "C","text": "Complete surgical bladder removal in all cases"},{"key": "D","text": "Only relevant for the most severe, highest-level lesions, never in lower lesions"}],"correct": "A","explanation": "Neurogenic bladder/bowel dysfunction is common in myelomeningocele, typically requiring coordinated multidisciplinary management (often including intermittent catheterization and structured bowel programs)."},{"id": 6659,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Latex allergy is a notably increased risk in individuals with myelomeningocele, thought to relate to:","options": [{"key": "A","text": "Repeated early and ongoing latex exposure from multiple medical procedures/catheterizations"},{"key": "B","text": "Only relevant for adults with myelomeningocele, never children"},{"key": "C","text": "A condition entirely unrelated to their medical history or care needs"},{"key": "D","text": "A risk identical to the general population with no increased susceptibility"}],"correct": "A","explanation": "Individuals with myelomeningocele show notably increased latex allergy risk, likely related to repeated early/ongoing latex exposure from frequent medical procedures, informing important clinical precautions (latex-free equipment/gloves)."},{"id": 6660,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding skin care/pressure injury prevention for children with myelomeningocele, given their sensory impairment below the lesion level?","options": [{"key": "A","text": "Skin care has no relevance to myelomeningocele management"},{"key": "B","text": "Only relevant for children who use wheelchairs, never for ambulatory children with myelomeningocele"},{"key": "C","text": "Pressure injury risk is identical to typically developing children with no additional consideration needed"},{"key": "D","text": "Regular skin inspection and pressure relief strategies are important given impaired sensation increasing pressure injury risk, similar to spinal cord injury considerations"}],"correct": "D","explanation": "Similar to traumatic SCI, impaired sensation below the myelomeningocele lesion level increases pressure injury risk, making regular skin inspection and appropriate pressure relief strategies important throughout life, regardless of ambulation status."},{"id": 6661,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding orthotic/mobility device prescription for children with myelomeningocele?","options": [{"key": "A","text": "A single standard orthotic/mobility solution is appropriate for all children with myelomeningocele regardless of lesion level"},{"key": "B","text": "Individualized based on the specific neurological level and functional capacity, potentially including AFOs, KAFOs, or wheelchair mobility depending on presentation"},{"key": "C","text": "Mobility device needs remain completely static throughout the child's growth and development"},{"key": "D","text": "Orthotic devices are never used in myelomeningocele management"}],"correct": "B","explanation": "Orthotic and mobility device prescription is individualized based on the specific neurological level and functional presentation, ranging from AFOs for lower lumbar/sacral level lesions to more extensive support or wheelchair mobility for higher-level involvement."},{"id": 6662,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding contracture prevention in children with myelomeningocele, given the potential for muscle imbalance below the lesion level?","options": [{"key": "A","text": "Regular positioning, stretching, and monitoring help prevent contractures related to muscle imbalance patterns below the neurological level"},{"key": "B","text": "Contractures never occur in children with myelomeningocele given their sensory impairment"},{"key": "C","text": "No preventive strategies are relevant or effective for this population"},{"key": "D","text": "Contracture prevention is only relevant for the highest-level lesions, never for lower lumbar/sacral involvement"}],"correct": "A","explanation": "Similar to other conditions causing muscle imbalance (e.g., CP, SCI), children with myelomeningocele require attention to contracture prevention through appropriate positioning and stretching strategies addressing their specific pattern of muscle imbalance below the lesion level."},{"id": 6663,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important long-term consideration regarding weight-bearing/bone health for children with myelomeningocele, particularly those with higher-level lesions and limited ambulation?","options": [{"key": "A","text": "All children with myelomeningocele show identical bone health regardless of their functional/ambulation level"},{"key": "B","text": "Fracture risk is lower in this population compared to typically developing children"},{"key": "C","text": "Increased fracture risk related to reduced weight-bearing/bone density, relevant to considering standing programs and other bone health interventions"},{"key": "D","text": "Bone health has no relevance to myelomeningocele management"}],"correct": "C","explanation": "Reduced weight-bearing activity, particularly in higher-level lesions with limited ambulation, increases fracture risk related to lower bone density, making appropriate loading interventions (e.g., standing programs) a relevant consideration."},{"id": 6664,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important educational/functional consideration for children with myelomeningocele as they approach school age, relevant to comprehensive care planning?","options": [{"key": "A","text": "Addressing mobility, self-care independence (including bladder/bowel management), and any associated learning needs to support successful school participation"},{"key": "B","text": "School participation is never a realistic goal for children with myelomeningocele"},{"key": "C","text": "Educational considerations have no relevance to physiotherapy involvement in myelomeningocele care"},{"key": "D","text": "All children with myelomeningocele have identical educational needs regardless of their specific presentation"}],"correct": "A","explanation": "Comprehensive care planning for school-age children with myelomeningocele addresses mobility, self-care independence, and any associated learning needs, supporting successful educational participation, often requiring coordinated multidisciplinary and school-based collaboration."},{"id": 6665,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding tethered cord syndrome, a potential complication sometimes seen in individuals with myelomeningocele over time?","options": [{"key": "A","text": "A benign finding requiring no clinical attention or monitoring"},{"key": "B","text": "A condition that never occurs in individuals with myelomeningocele"},{"key": "C","text": "Can cause progressive neurological deterioration (new/worsening weakness, changing bladder function, or pain) related to abnormal spinal cord tethering, requiring prompt evaluation if suspected"},{"key": "D","text": "A condition unrelated to any spinal cord pathology or neurological function"}],"correct": "C","explanation": "Tethered cord syndrome can develop over time in individuals with myelomeningocele, causing progressive neurological changes (new weakness, altered bladder/bowel function, pain) related to abnormal cord tethering, requiring prompt recognition and evaluation given surgical treatment implications."},{"id": 6666,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "Which of the following describes signs that might suggest tethered cord syndrome development in a child with myelomeningocele, relevant to ongoing physiotherapy monitoring?","options": [{"key": "A","text": "Only relevant if the child reports severe pain, with no other associated clinical signs"},{"key": "B","text": "No specific signs exist that could indicate this condition"},{"key": "C","text": "New or progressively worsening weakness, changes in gait pattern, new-onset scoliosis, or changing bladder/bowel function"},{"key": "D","text": "This condition shows no relationship to any observable clinical changes over time"}],"correct": "C","explanation": "Physiotherapists monitoring children with myelomeningocele over time should be alert to signs potentially suggesting tethered cord (new/progressive weakness, gait changes, new scoliosis, altered bladder/bowel function), prompting appropriate medical referral for further evaluation."},{"id": 6667,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding latex-free precautions during physiotherapy sessions for children with myelomeningocele?","options": [{"key": "A","text": "Latex precautions are irrelevant to physiotherapy practice for this population"},{"key": "B","text": "Only relevant during surgical procedures, never during physiotherapy sessions"},{"key": "C","text": "Latex allergy risk is identical to the general pediatric population, requiring no special precaution"},{"key": "D","text": "Using latex-free equipment/materials given the significantly increased latex allergy risk in this population"}],"correct": "D","explanation": "Given the notably increased latex allergy risk in myelomeningocele, using latex-free equipment/materials during physiotherapy sessions is an important safety precaution."},{"id": 6668,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding cognitive assessment/support for children with myelomeningocele, given the potential association with hydrocephalus and Chiari II malformation?","options": [{"key": "A","text": "All children with myelomeningocele show identical cognitive profiles regardless of their specific associated complications"},{"key": "B","text": "Cognitive function is never affected in myelomeningocele regardless of associated hydrocephalus"},{"key": "C","text": "Some children may show specific cognitive/learning profile considerations related to associated hydrocephalus/Chiari malformation, relevant to comprehensive developmental support planning"},{"key": "D","text": "Cognitive assessment has no relevance to physiotherapy practice or overall care planning"}],"correct": "C","explanation": "Given the association with hydrocephalus and Chiari II malformation, some children with myelomeningocele may show specific cognitive/learning considerations, relevant to comprehensive developmental support and educational planning within the broader care team."},{"id": 6669,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding prenatal (fetal) myelomeningocele repair, an evolving area of management for some cases?","options": [{"key": "A","text": "May be considered in select cases and is associated with certain potential benefits (e.g., reduced hindbrain herniation) though also carrying specific maternal/fetal risks requiring careful counseling"},{"key": "B","text": "This is an outdated approach no longer relevant to current myelomeningocele management"},{"key": "C","text": "Prenatal repair completely eliminates all future neurological impairment in all cases"},{"key": "D","text": "Prenatal repair is never performed or considered for myelomeningocele under any circumstances"}],"correct": "A","explanation": "Prenatal myelomeningocele repair, an evolving management approach, has shown certain benefits (e.g., reduced hindbrain herniation, reduced shunt need in some studies) in appropriately selected cases, while also carrying specific maternal/fetal risks requiring careful multidisciplinary counseling and patient selection."},{"id": 6670,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy goal-setting for a child with a lower lumbar/sacral level myelomeningocele lesion, generally associated with better ambulation potential?","options": [{"key": "A","text": "Ambulation is never a realistic goal for any level of myelomeningocele involvement"},{"key": "B","text": "Often includes goals related to community ambulation with appropriate orthotic support, given the relatively preserved lower limb function at this level"},{"key": "C","text": "Wheelchair mobility is always the only appropriate goal regardless of lesion level"},{"key": "D","text": "Goals should be identical regardless of the specific neurological level of the lesion"}],"correct": "B","explanation": "Lower lumbar/sacral level lesions, given relatively preserved lower limb motor function, often support goals toward community ambulation (potentially with orthotic support), contrasting with higher-level lesions where wheelchair mobility may be a more primary functional goal."},{"id": 6671,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding physiotherapy goal-setting for a child with a higher thoracic/upper lumbar level myelomeningocele lesion?","options": [{"key": "A","text": "Goals should focus exclusively on upper limb function with no consideration of lower limb mobility approaches"},{"key": "B","text": "Often emphasizes wheelchair mobility skills alongside consideration of therapeutic standing/limited ambulation with more extensive orthotic support, depending on individual factors"},{"key": "C","text": "Wheelchair mobility is never considered for any level of myelomeningocele lesion"},{"key": "D","text": "Ambulation goals are always identical regardless of whether the lesion is at a high or low level"}],"correct": "B","explanation": "Higher-level lesions, given more significant lower limb involvement, often emphasize wheelchair mobility skill development, though therapeutic standing or limited ambulation with more extensive orthotic support (e.g., HKAFOs) may still be considered based on individual factors and family/child goals."},{"id": 6672,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding hydrocephalus management in children without associated myelomeningocele (isolated hydrocephalus)?","options": [{"key": "A","text": "Isolated hydrocephalus never requires any medical or surgical management"},{"key": "B","text": "Isolated hydrocephalus always resolves spontaneously without any intervention required"},{"key": "C","text": "Similarly may require shunt placement or other CSF diversion procedures, with associated developmental monitoring needs"},{"key": "D","text": "This condition has no relevance to pediatric physiotherapy practice"}],"correct": "C","explanation": "Hydrocephalus occurring independently of myelomeningocele (from various other causes) similarly may require CSF diversion management (shunt or alternative procedures), with associated developmental monitoring needs relevant to comprehensive pediatric care."},{"id": 6673,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the potential impact of hydrocephalus (with or without associated myelomeningocele) on motor development?","options": [{"key": "A","text": "This consideration has no relevance to physiotherapy assessment or intervention planning"},{"key": "B","text": "Can contribute to motor delay/impairment depending on severity and any associated structural brain changes, relevant to comprehensive developmental assessment"},{"key": "C","text": "Hydrocephalus never has any impact on motor development regardless of severity"},{"key": "D","text": "Motor development is always completely unaffected by hydrocephalus"}],"correct": "B","explanation": "Depending on severity and any associated structural brain involvement, hydrocephalus can contribute to motor delay or impairment, relevant to comprehensive physiotherapy developmental assessment and appropriately individualized intervention planning."},{"id": 6674,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding transition planning for adolescents/young adults with myelomeningocele as they move toward adult healthcare services?","options": [{"key": "A","text": "Assuming needs remain completely identical and unchanged from childhood through adulthood"},{"key": "B","text": "Comprehensive transition planning addressing ongoing medical, mobility, bladder/bowel, and psychosocial needs supports successful movement to adult-focused care"},{"key": "C","text": "Transition planning is solely a medical specialist responsibility with no physiotherapy involvement"},{"key": "D","text": "No transition planning is relevant since myelomeningocele-related needs resolve completely by adulthood"}],"correct": "B","explanation": "Given the lifelong, multisystem nature of myelomeningocele-related needs, comprehensive transition planning addressing evolving medical, mobility, and psychosocial considerations supports successful transition to adult-focused healthcare services."},{"id": 6675,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding family education for caregivers of infants newly diagnosed with myelomeningocele, relevant to early physiotherapy involvement?","options": [{"key": "A","text": "Families should be given no information until the child reaches school age"},{"key": "B","text": "Physiotherapy has no role in early family education following myelomeningocele diagnosis"},{"key": "C","text": "No family education is relevant or beneficial at the time of initial diagnosis"},{"key": "D","text": "Providing clear information about positioning, handling, early developmental support, and the multidisciplinary care approach helps support family understanding and engagement"}],"correct": "D","explanation": "Early family education regarding positioning, handling, developmental support strategies, and the coordinated multidisciplinary care approach supports family understanding, confidence, and engagement from the time of initial diagnosis, an important component of family-centered early physiotherapy involvement."},{"id": 6676,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Encephalocele, another neural tube defect type, refers to:","options": [{"key": "A","text": "A condition with no relationship to neural tube closure defects"},{"key": "B","text": "A defect exclusively affecting the lumbar spine"},{"key": "C","text": "Herniation of brain tissue and meninges through a cranial defect"},{"key": "D","text": "A term identical to myelomeningocele but affecting a different body region with no distinguishing features"}],"correct": "C","explanation": "Encephalocele involves herniation of brain tissue/meninges through a cranial (rather than spinal) defect, another recognized form within the neural tube defect spectrum."},{"id": 6677,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Anencephaly, the most severe neural tube defect, is characterized by:","options": [{"key": "A","text": "A condition identical in severity to spina bifida occulta"},{"key": "B","text": "Absence of a major portion of the brain and skull, generally incompatible with long-term survival"},{"key": "C","text": "A mild, generally asymptomatic condition"},{"key": "D","text": "A condition primarily affecting only lower limb function with normal brain development"}],"correct": "B","explanation": "Anencephaly represents the most severe neural tube defect, involving significant absence of brain and skull development, generally incompatible with long-term survival."},{"id": 6678,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding scoliosis monitoring in children with myelomeningocele, particularly those with higher-level lesions?","options": [{"key": "A","text": "Increased scoliosis risk warrants regular monitoring as part of comprehensive musculoskeletal surveillance"},{"key": "B","text": "Scoliosis never occurs in children with myelomeningocele"},{"key": "C","text": "Scoliosis risk is identical regardless of the neurological lesion level"},{"key": "D","text": "Scoliosis monitoring has no relevance to physiotherapy practice in this population"}],"correct": "A","explanation": "Children with myelomeningocele, particularly those with higher-level lesions, show increased scoliosis risk related to muscle imbalance and other factors, warranting regular monitoring as part of comprehensive care."},{"id": 6679,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding hip surveillance in children with myelomeningocele, given the muscle imbalance pattern below the lesion level?","options": [{"key": "A","text": "Regular hip monitoring is important given increased dislocation/subluxation risk related to the specific pattern of muscle imbalance at their neurological level"},{"key": "B","text": "All children with myelomeningocele show identical hip stability regardless of lesion level"},{"key": "C","text": "Hip monitoring is only relevant for the lowest sacral-level lesions"},{"key": "D","text": "Hip surveillance is irrelevant since myelomeningocele never affects hip joint stability"}],"correct": "A","explanation": "Given the specific patterns of muscle imbalance around the hip that vary by neurological level, regular hip surveillance is an important component of comprehensive musculoskeletal monitoring in myelomeningocele management."},{"id": 6680,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the potential for upper limb involvement in some children with myelomeningocele, despite the primary lesion being spinal?","options": [{"key": "A","text": "Upper limb assessment is never relevant to myelomeningocele physiotherapy evaluation"},{"key": "B","text": "Upper limb function is always completely unaffected in every case of myelomeningocele regardless of associated complications"},{"key": "C","text": "Associated Chiari II malformation or hydrocephalus can sometimes contribute to upper limb coordination/function changes, relevant to comprehensive assessment beyond the primary spinal level findings"},{"key": "D","text": "Only lower limb assessment is ever relevant regardless of any associated brain-related complications"}],"correct": "C","explanation": "Beyond the primary spinal lesion effects, associated complications like Chiari II malformation can sometimes contribute to upper limb coordination or function changes, making comprehensive assessment (not limited solely to the primary spinal level) relevant in some cases."},{"id": 6681,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding bracing (e.g., AFOs) for children with lower lumbar/sacral level myelomeningocele who have some active ankle musculature but with imbalance?","options": [{"key": "A","text": "Assuming no orthotic intervention is ever beneficial for myelomeningocele-related lower limb involvement"},{"key": "B","text": "Orthotic support can help manage muscle imbalance around the ankle/foot, supporting more efficient gait mechanics"},{"key": "C","text": "Orthotic management is identical regardless of the specific pattern of muscle imbalance present"},{"key": "D","text": "Bracing is never relevant for lower lumbar/sacral level lesions given their relatively preserved function"}],"correct": "B","explanation": "Even with relatively preserved lower limb function in lower-level lesions, orthotic support can help manage specific patterns of muscle imbalance around the ankle/foot, supporting more efficient and stable gait mechanics."},{"id": 6682,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Down syndrome results from which chromosomal abnormality?","options": [{"key": "A","text": "A single gene mutation rather than a chromosomal abnormality"},{"key": "B","text": "Trisomy 18"},{"key": "C","text": "Trisomy 21 (extra copy of chromosome 21)"},{"key": "D","text": "Monosomy X"}],"correct": "C","explanation": "Down syndrome results from an extra full or partial copy of chromosome 21, most commonly from non-disjunction during meiosis."},{"id": 6683,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following musculoskeletal features is commonly associated with Down syndrome, relevant to physiotherapy assessment?","options": [{"key": "A","text": "Absence of any characteristic musculoskeletal features"},{"key": "B","text": "Only affecting the upper limbs, never lower limbs or trunk"},{"key": "C","text": "Generalized hypertonia/spasticity"},{"key": "D","text": "Generalized ligamentous laxity/hypotonia"}],"correct": "D","explanation": "Generalized ligamentous laxity and hypotonia are characteristic features in Down syndrome, relevant to physiotherapy assessment and management planning."},{"id": 6684,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Atlantoaxial instability, a recognized concern in a subset of individuals with Down syndrome, relates to:","options": [{"key": "A","text": "A concern only relevant in adulthood, never in childhood"},{"key": "B","text": "Increased laxity of the ligaments supporting the C1-C2 (atlantoaxial) joint, risking potential spinal cord compression"},{"key": "C","text": "A condition unrelated to any ligamentous laxity consideration"},{"key": "D","text": "A condition affecting only the lumbar spine"}],"correct": "B","explanation": "Atlantoaxial instability, related to ligamentous laxity at the C1-C2 level, is a recognized concern in a subset of individuals with Down syndrome, with important implications for activity/positioning precautions."},{"id": 6685,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important precaution consideration regarding atlantoaxial instability risk in some individuals with Down syndrome, relevant to physiotherapy practice?","options": [{"key": "A","text": "All individuals with Down syndrome require complete avoidance of any neck movement whatsoever"},{"key": "B","text": "Caution regarding activities/positions involving significant neck flexion/extension stress (e.g., certain gymnastic activities, some manual therapy techniques) in at-risk individuals"},{"key": "C","text": "No precautions are ever relevant regarding this consideration"},{"key": "D","text": "This consideration is entirely irrelevant to physiotherapy practice"}],"correct": "B","explanation": "Awareness of atlantoaxial instability risk informs appropriate caution regarding certain high-risk neck movement activities in some individuals with Down syndrome, though the specific approach should be individualized based on any relevant screening/clinical findings."},{"id": 6686,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Congenital heart defects are notably more common in individuals with Down syndrome, relevant to which physiotherapy consideration?","options": [{"key": "A","text": "All individuals with Down syndrome have identical cardiac status requiring no individual consideration"},{"key": "B","text": "Cardiac considerations are entirely irrelevant to physiotherapy practice for this population"},{"key": "C","text": "Awareness of potential cardiac status when planning exercise intensity/activity, given the increased prevalence of congenital heart conditions"},{"key": "D","text": "Congenital heart defects never occur in individuals with Down syndrome"}],"correct": "C","explanation": "Given the notably increased prevalence of congenital heart defects in Down syndrome, awareness of an individual's specific cardiac status is relevant when planning exercise/activity intensity within physiotherapy intervention."},{"id": 6687,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "Which of the following describes typical motor development in children with Down syndrome compared to typically developing peers?","options": [{"key": "A","text": "No physiotherapy involvement is ever relevant given assumed normal motor development"},{"key": "B","text": "Motor development always shows acceleration compared to typically developing peers"},{"key": "C","text": "Generally shows delayed motor milestone achievement, though with significant individual variation"},{"key": "D","text": "Motor development is always identical to typically developing peers with no delay"}],"correct": "C","explanation": "Children with Down syndrome generally show delayed motor milestone achievement (related to hypotonia, ligamentous laxity, and other factors), though with considerable individual variation, often benefiting from early physiotherapy involvement."},{"id": 6688,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration regarding gait pattern often observed in children with Down syndrome, related to their characteristic hypotonia/laxity?","options": [{"key": "A","text": "All children with Down syndrome show an identical, single gait pattern with no individual variation"},{"key": "B","text": "Gait assessment is irrelevant to physiotherapy practice for this population"},{"key": "C","text": "Gait pattern is always completely typical/normal in children with Down syndrome"},{"key": "D","text": "Often shows a wide-based gait pattern with characteristic features related to underlying hypotonia and ligamentous laxity"}],"correct": "D","explanation": "Children with Down syndrome often show characteristic gait features (e.g., wide base, altered foot posture) related to their underlying hypotonia and ligamentous laxity, relevant to physiotherapy gait assessment and intervention planning."},{"id": 6689,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding obesity risk in individuals with Down syndrome, relevant to comprehensive physiotherapy/health management?","options": [{"key": "A","text": "Physical activity promotion is never appropriate or beneficial for individuals with Down syndrome"},{"key": "B","text": "Increased obesity risk is recognized, relevant to considering appropriate physical activity promotion as part of comprehensive health management"},{"key": "C","text": "Obesity risk is identical to the general population with no additional consideration needed"},{"key": "D","text": "This consideration has no relevance to physiotherapy practice"}],"correct": "B","explanation": "Given increased obesity risk in this population, promoting appropriate physical activity is a relevant consideration within comprehensive health management, alongside other physiotherapy goals."},{"id": 6690,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Turner syndrome results from which chromosomal abnormality, relevant to understanding associated features?","options": [{"key": "A","text": "A condition affecting only autosomal chromosomes, not sex chromosomes"},{"key": "B","text": "An extra Y chromosome in males"},{"key": "C","text": "An extra copy of chromosome 21"},{"key": "D","text": "Complete or partial absence of one X chromosome in females (45,X or variants)"}],"correct": "D","explanation": "Turner syndrome results from complete or partial monosomy of the X chromosome in females, associated with various physical features including short stature."},{"id": 6691,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Klinefelter syndrome results from which chromosomal abnormality?","options": [{"key": "A","text": "An extra X chromosome in males (47,XXY)"},{"key": "B","text": "A condition affecting only females"},{"key": "C","text": "Monosomy X"},{"key": "D","text": "Trisomy 21"}],"correct": "A","explanation": "Klinefelter syndrome results from an extra X chromosome in males (47,XXY karyotype), associated with various features including relevance to physical development."},{"id": 6692,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Prader-Willi syndrome, a genetic condition sometimes relevant to pediatric physiotherapy practice, is characterized by which combination of features?","options": [{"key": "A","text": "A condition with no relevance to motor development or physiotherapy involvement"},{"key": "B","text": "A condition identical in presentation to Down syndrome with no distinguishing features"},{"key": "C","text": "Neonatal hypotonia, followed by later hyperphagia/obesity risk and characteristic developmental features"},{"key": "D","text": "A condition characterized exclusively by hypertonia from birth with no hypotonic phase"}],"correct": "C","explanation": "Prader-Willi syndrome characteristically presents with significant neonatal hypotonia (relevant to early physiotherapy involvement) followed by later hyperphagia and associated obesity risk, along with other characteristic developmental features."},{"id": 6693,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Fragile X syndrome, the most common inherited cause of intellectual disability, is relevant to physiotherapy practice primarily due to:","options": [{"key": "A","text": "Associated motor coordination difficulties and hypotonia sometimes seen alongside the primary cognitive/behavioral features"},{"key": "B","text": "A condition that always presents identically to cerebral palsy"},{"key": "C","text": "Exclusively affecting cognitive function with no possible motor component"},{"key": "D","text": "No relevance to physiotherapy practice whatsoever"}],"correct": "A","explanation": "Fragile X syndrome can be associated with motor coordination difficulties and hypotonia alongside its primary cognitive/behavioral features, relevant to comprehensive physiotherapy assessment within a multidisciplinary team approach."},{"id": 6694,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding sensory processing differences sometimes seen in various genetic/neurodevelopmental conditions, relevant to physiotherapy intervention approach?","options": [{"key": "A","text": "All individuals with genetic conditions show identical sensory processing patterns requiring no individualized consideration"},{"key": "B","text": "Sensory processing has no relevance to physiotherapy practice for any genetic condition"},{"key": "C","text": "May require thoughtful adaptation of therapeutic approach (environment, handling, activity presentation) to accommodate individual sensory processing patterns"},{"key": "D","text": "Sensory considerations are solely an occupational therapy responsibility with no relevance to physiotherapy"}],"correct": "C","explanation": "Awareness of and thoughtful adaptation to individual sensory processing differences (sometimes associated with various genetic/neurodevelopmental conditions) can support more effective physiotherapy engagement and intervention delivery."},{"id": 6695,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding growth patterns in children with certain genetic syndromes (e.g., Turner syndrome, achondroplasia), relevant to physiotherapy assessment interpretation?","options": [{"key": "A","text": "Growth considerations are solely a medical/endocrinology responsibility with no relevance to physiotherapy practice"},{"key": "B","text": "All children, regardless of any genetic condition, should be assessed using identical standard growth charts with no condition-specific consideration"},{"key": "C","text": "Some genetic conditions are associated with characteristic growth patterns (e.g., short stature) requiring condition-specific growth reference standards for appropriate interpretation"},{"key": "D","text": "Growth pattern has no relevance to physiotherapy assessment for any pediatric population"}],"correct": "C","explanation": "For certain genetic conditions associated with characteristic growth patterns, using condition-specific growth references (where available) supports more appropriate interpretation of growth-related findings within comprehensive assessment."},{"id": 6696,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Achondroplasia, the most common form of disproportionate short stature, results from mutations affecting:","options": [{"key": "A","text": "The X chromosome exclusively"},{"key": "B","text": "FGFR3 gene, affecting cartilage/bone growth"},{"key": "C","text": "A condition unrelated to any specific genetic mutation"},{"key": "D","text": "Chromosome 21 copy number"}],"correct": "B","explanation": "Achondroplasia results from FGFR3 gene mutations affecting endochondral bone growth, causing characteristic disproportionate short stature with rhizomelic limb shortening."},{"id": 6697,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important physiotherapy consideration regarding spinal stenosis risk sometimes associated with achondroplasia?","options": [{"key": "A","text": "This consideration has no relevance to physiotherapy practice for individuals with achondroplasia"},{"key": "B","text": "Increased risk of spinal stenosis, potentially causing neurological symptoms, relevant to monitoring for related signs during physiotherapy involvement"},{"key": "C","text": "Spinal stenosis risk is identical to the general population with no additional consideration needed"},{"key": "D","text": "Spinal stenosis never occurs in achondroplasia regardless of any anatomical considerations"}],"correct": "B","explanation": "Individuals with achondroplasia show increased risk of spinal stenosis (related to their characteristic skeletal anatomy), potentially causing neurological symptoms, relevant to ongoing monitoring within comprehensive care."},{"id": 6698,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding motor development expectations for infants with significant hypotonia related to an underlying genetic condition?","options": [{"key": "A","text": "Assuming identical developmental trajectory to typically developing infants with no condition-specific consideration"},{"key": "B","text": "All hypotonic infants, regardless of underlying genetic diagnosis, require identical intervention approaches"},{"key": "C","text": "Individualized assessment and appropriately adapted developmental expectations/intervention planning, considering the specific condition and presentation"},{"key": "D","text": "Motor development assessment is irrelevant for infants with genetic conditions"}],"correct": "C","explanation": "Individualized assessment and intervention planning, considering the specific underlying genetic condition and the infant's individual presentation, supports appropriately tailored physiotherapy approach rather than a one-size-fits-all model."},{"id": 6699,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding genetic counseling relevance to comprehensive family support for families of children with newly diagnosed genetic conditions?","options": [{"key": "A","text": "Genetic counseling is only relevant before a child's birth, never after diagnosis"},{"key": "B","text": "Genetic counseling has no relevance to comprehensive family-centered care"},{"key": "C","text": "Genetic counseling provides important information regarding inheritance patterns, recurrence risk, and prognosis, complementing the broader multidisciplinary support including physiotherapy"},{"key": "D","text": "Physiotherapists should independently provide detailed genetic counseling without any specialist genetics involvement"}],"correct": "C","explanation": "Genetic counseling (typically provided by specialist genetics services) offers important information supporting family understanding and decision-making, complementing the broader multidisciplinary support team including physiotherapy involvement in the child's ongoing care."},{"id": 6700,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the use of standardized developmental assessment tools for children with specific genetic syndromes that may have unique developmental trajectories?","options": [{"key": "A","text": "Standard population-based developmental tools are always equally appropriate and meaningful for every genetic condition with no need for any specific consideration"},{"key": "B","text": "Condition-specific growth/developmental curves, where available and validated, may provide more clinically meaningful comparison than standard population-based tools alone"},{"key": "C","text": "Developmental assessment is irrelevant for children with identified genetic syndromes"},{"key": "D","text": "Only chronological age matters for developmental assessment interpretation, regardless of any underlying genetic diagnosis"}],"correct": "B","explanation": "For certain genetic syndromes with well-characterized, distinct developmental trajectories, condition-specific assessment references (where validated and available) can provide more clinically meaningful interpretation than relying solely on general population-based standards."},{"id": 6701,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding multidisciplinary team involvement in the comprehensive management of children with complex genetic conditions?","options": [{"key": "A","text": "Multidisciplinary involvement has no evidence of benefit for children with genetic conditions"},{"key": "B","text": "Physiotherapy should always operate in complete isolation from other team members regardless of the condition's complexity"},{"key": "C","text": "A single discipline can independently manage all aspects of care for any genetic condition without need for coordination"},{"key": "D","text": "Given the often multisystem impact of genetic conditions, coordinated multidisciplinary team involvement (medical, therapy, educational, and psychosocial) supports comprehensive care"}],"correct": "D","explanation": "Given the often multisystem impact of genetic conditions on various aspects of a child's development and health, coordinated multidisciplinary team involvement is important for comprehensive, well-integrated care planning and delivery."},{"id": 6702,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the potential for co-occurring cardiac, respiratory, or other organ system involvement in certain genetic syndromes, relevant to physiotherapy exercise/activity planning?","options": [{"key": "A","text": "Cardiac and respiratory considerations are entirely irrelevant to physiotherapy practice for genetic conditions"},{"key": "B","text": "Genetic conditions never involve any organ systems beyond the musculoskeletal/neurological systems"},{"key": "C","text": "All children with genetic conditions can safely participate in identical activity levels with no individual consideration needed"},{"key": "D","text": "Awareness of any relevant co-occurring organ system involvement is important for appropriately individualizing exercise/activity intensity and precautions"}],"correct": "D","explanation": "Many genetic syndromes can involve multiple organ systems beyond the primary musculoskeletal/neurological features, making awareness of any relevant co-occurring involvement (cardiac, respiratory, and others) important for appropriately individualized physiotherapy exercise/activity planning."},{"id": 6703,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding realistic goal-setting and family communication for children with genetic conditions associated with progressive or complex presentations?","options": [{"key": "A","text": "Providing overly optimistic information regardless of the actual clinical presentation and prognosis"},{"key": "B","text": "Withholding all information from families regarding expected developmental trajectory"},{"key": "C","text": "Honest, sensitively delivered communication balancing realistic expectations with supportive, family-centered goal-setting appropriate to the specific condition and individual presentation"},{"key": "D","text": "Using identical, generic goal-setting templates regardless of the specific genetic condition or individual presentation"}],"correct": "C","explanation": "Honest, appropriately sensitive communication that balances realistic expectations with supportive, individualized, family-centered goal-setting is important when working with families of children with genetic conditions, particularly those with more complex or progressive presentations."},{"id": 6704,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding thyroid function screening relevance in children with Down syndrome, indirectly relevant to physiotherapy given potential impact on energy/tone?","options": [{"key": "A","text": "Increased hypothyroidism risk in Down syndrome warrants regular screening, as untreated thyroid dysfunction could affect energy levels/tone relevant to therapy engagement"},{"key": "B","text": "Thyroid screening is solely a medical responsibility with absolutely no indirect relevance to physiotherapy practice"},{"key": "C","text": "All children with Down syndrome have identical thyroid function requiring no monitoring"},{"key": "D","text": "Thyroid function has no relationship to Down syndrome or any relevance to physiotherapy consideration"}],"correct": "A","explanation": "Down syndrome is associated with increased hypothyroidism risk, warranting regular medical screening; awareness of thyroid status is indirectly relevant to physiotherapy given potential impact on energy levels and muscle tone affecting therapy engagement."},{"id": 6705,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes Rett syndrome, a genetic condition primarily affecting females, relevant to pediatric physiotherapy practice?","options": [{"key": "A","text": "A condition with no motor or developmental impact requiring no physiotherapy involvement"},{"key": "B","text": "A condition exclusively affecting males with no relevance to female patients"},{"key": "C","text": "A condition identical to Down syndrome with no distinguishing features"},{"key": "D","text": "A condition causing developmental regression after a period of apparently normal early development, with characteristic hand stereotypies and motor impairment"}],"correct": "D","explanation": "Rett syndrome characteristically shows developmental regression after initially normal early development, with characteristic hand stereotypies and progressive motor impairment, relevant to physiotherapy assessment and ongoing management."},{"id": 6706,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding physiotherapy approach for a child with a genetic condition associated with significant intellectual disability, relevant to therapy engagement strategies?","options": [{"key": "A","text": "Assuming identical communication/instruction approaches are appropriate regardless of the child's cognitive level"},{"key": "B","text": "Physiotherapy should never be attempted for children with significant intellectual disability"},{"key": "C","text": "Adapting communication, instruction complexity, and activity presentation to the child's cognitive level supports more effective therapeutic engagement"},{"key": "D","text": "Cognitive level has no relevance to physiotherapy intervention approach or engagement strategies"}],"correct": "C","explanation": "Thoughtfully adapting communication style, instruction complexity, and activity presentation to the child's individual cognitive level supports more effective therapeutic engagement and outcomes."},{"id": 6707,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding Marfan syndrome, a genetic connective tissue disorder sometimes relevant to physiotherapy practice given its musculoskeletal features?","options": [{"key": "A","text": "Associated with joint hypermobility, tall stature, and potential cardiovascular involvement (aortic root concerns), relevant to considering appropriate activity precautions"},{"key": "B","text": "A condition identical to Down syndrome with no distinguishing features"},{"key": "C","text": "A condition with no musculoskeletal features of any relevance to physiotherapy"},{"key": "D","text": "A condition never requiring any activity-related precaution consideration"}],"correct": "A","explanation": "Marfan syndrome involves connective tissue abnormalities causing joint hypermobility and characteristic tall stature, alongside potential cardiovascular involvement (particularly aortic root dilation) requiring important activity-related precaution consideration in physiotherapy planning."},{"id": 6708,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding Ehlers-Danlos syndrome, another connective tissue disorder relevant to physiotherapy practice given its hypermobility features?","options": [{"key": "A","text": "A condition identical in presentation and management approach to Down syndrome"},{"key": "B","text": "A condition with no relevance to physiotherapy assessment or intervention planning"},{"key": "C","text": "A condition causing only hypertonia with no joint mobility considerations"},{"key": "D","text": "Characterized by joint hypermobility and skin/connective tissue fragility, requiring careful, often modified approach to exercise/manual therapy given increased injury susceptibility"}],"correct": "D","explanation": "Ehlers-Danlos syndrome involves connective tissue fragility and joint hypermobility, requiring thoughtful, often modified physiotherapy approach (careful exercise prescription, cautious manual therapy) given increased susceptibility to joint/soft tissue injury."},{"id": 6709,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding exercise prescription for children with joint hypermobility (whether isolated or associated with a specific syndrome like Ehlers-Danlos)?","options": [{"key": "A","text": "Often emphasizes proprioceptive/stability-focused exercise and appropriate joint protection strategies, rather than exercises that further stress already lax joints"},{"key": "B","text": "Exercise should always be completely avoided for any child with joint hypermobility"},{"key": "C","text": "Identical exercise prescription approaches as for children with normal joint stability, with no modification needed"},{"key": "D","text": "Maximal range-of-motion stretching exercises are always the most appropriate approach for hypermobile joints"}],"correct": "A","explanation": "Exercise prescription for hypermobile joints typically emphasizes proprioceptive training and stability-focused strengthening, alongside appropriate joint protection education, rather than approaches that might further stress already lax joint structures."},{"id": 6710,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding sensory processing and behavioral approaches relevant to physiotherapy practice with children who have autism spectrum disorder alongside a co-occurring genetic syndrome?","options": [{"key": "A","text": "Assuming identical intervention approaches regardless of any co-occurring autism spectrum features"},{"key": "B","text": "Individualized, sensory-aware, and behaviorally-informed approaches support more effective engagement, considering the specific combination of presenting features"},{"key": "C","text": "Autism spectrum considerations are entirely irrelevant when a genetic syndrome diagnosis is also present"},{"key": "D","text": "Physiotherapy should never be attempted for any child with co-occurring autism spectrum disorder"}],"correct": "B","explanation": "For children with co-occurring genetic syndrome and autism spectrum features, individualized approaches considering both sensory processing and behavioral factors support more effective, tailored physiotherapy engagement."},{"id": 6711,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best summarizes the overall approach to physiotherapy practice across the diverse range of pediatric genetic/chromosomal conditions?","options": [{"key": "A","text": "Genetic conditions have no relevance to physiotherapy practice and require no condition-specific knowledge"},{"key": "B","text": "Individualized assessment and intervention planning considering the specific condition's characteristic features, the child's individual presentation, and family-centered goals, rather than a one-size-fits-all approach"},{"key": "C","text": "Assessment and intervention planning should ignore any condition-specific considerations entirely"},{"key": "D","text": "A single standardized treatment protocol should be applied identically regardless of the specific underlying genetic condition"}],"correct": "B","explanation": "Given the diversity of genetic/chromosomal conditions and their varied presentations, individualized, condition-informed, family-centered assessment and intervention planning represents the appropriate overall approach to pediatric physiotherapy practice in this population."},{"id": 6712,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Easy","question": "Duchenne Muscular Dystrophy (DMD) results from mutations affecting which protein?","options": [{"key": "A","text": "Actin exclusively"},{"key": "B","text": "Myosin"},{"key": "C","text": "Dystrophin"},{"key": "D","text": "Acetylcholine receptor"}],"correct": "C","explanation": "DMD results from mutations causing absent/severely deficient dystrophin, a protein essential for muscle membrane stability."},{"id": 6713,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "DMD is inherited in which pattern, explaining its predominant occurrence in males?","options": [{"key": "A","text": "X-linked recessive"},{"key": "B","text": "Mitochondrial inheritance"},{"key": "C","text": "Autosomal recessive"},{"key": "D","text": "Autosomal dominant"}],"correct": "A","explanation": "DMD follows X-linked recessive inheritance, predominantly affecting males, with female carriers occasionally showing mild symptoms."},{"id": 6714,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "DMD typically presents with initial symptom onset around which age?","options": [{"key": "A","text": "At birth"},{"key": "B","text": "Adolescence"},{"key": "C","text": "2-5 years"},{"key": "D","text": "10-12 years"}],"correct": "C","explanation": "DMD symptoms (delayed walking, frequent falls, difficulty rising) typically become apparent around 2-5 years of age."},{"id": 6715,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Gower's sign in DMD reflects weakness of which muscle groups?","options": [{"key": "A","text": "Isolated facial muscles"},{"key": "B","text": "Distal hand muscles exclusively"},{"key": "C","text": "Proximal hip and thigh muscles"},{"key": "D","text": "Isolated respiratory muscles only"}],"correct": "C","explanation": "Gower's maneuver (using hands to 'walk up' the legs when rising from floor) compensates for proximal hip/thigh weakness characteristic of DMD."},{"id": 6716,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Calf pseudohypertrophy, a classic DMD finding, results from:","options": [{"key": "A","text": "Fluid retention unrelated to any muscle pathology"},{"key": "B","text": "True muscle hypertrophy from increased physical activity"},{"key": "C","text": "Inflammatory swelling exclusively"},{"key": "D","text": "Fat and fibrous tissue replacement of degenerating muscle fibers"}],"correct": "D","explanation": "Pseudohypertrophy reflects fat/fibrous tissue infiltration replacing degenerating muscle, giving an enlarged calf appearance despite underlying weakness."},{"id": 6717,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Easy","question": "Becker Muscular Dystrophy differs from DMD in that it typically shows:","options": [{"key": "A","text": "Onset exclusively in adulthood with no childhood presentation possible"},{"key": "B","text": "Autosomal dominant inheritance pattern rather than X-linked"},{"key": "C","text": "A milder phenotype with later onset and slower progression, related to partially functional dystrophin"},{"key": "D","text": "An identical severe phenotype to DMD with no distinguishing features"}],"correct": "C","explanation": "BMD results from mutations allowing some functional (though reduced/abnormal) dystrophin production, generally causing a milder, later-onset, more slowly progressive phenotype than DMD."},{"id": 6718,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Cardiac involvement (cardiomyopathy) is a significant concern in DMD given that:","options": [{"key": "A","text": "Cardiac muscle is never affected in DMD, only skeletal muscle"},{"key": "B","text": "Cardiac monitoring is unnecessary in DMD comprehensive management"},{"key": "C","text": "Cardiac involvement only occurs in Becker MD, never in Duchenne MD"},{"key": "D","text": "Dystrophin deficiency also affects cardiac muscle, necessitating regular cardiac monitoring"}],"correct": "D","explanation": "Since dystrophin is also expressed in cardiac muscle, DMD commonly involves cardiomyopathy, necessitating regular cardiac monitoring as part of comprehensive multidisciplinary management."},{"id": 6719,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the typical progression of ambulation loss in DMD without disease-modifying treatment (e.g., corticosteroids)?","options": [{"key": "A","text": "Ambulation loss occurs only after age 30"},{"key": "B","text": "Progressive weakness typically leads to loss of independent ambulation around 10-13 years of age"},{"key": "C","text": "Ambulation loss occurs immediately in early infancy"},{"key": "D","text": "Ambulation is never lost throughout the entire disease course"}],"correct": "B","explanation": "Without disease-modifying treatment, DMD typically shows progressive weakness leading to loss of independent ambulation around 10-13 years of age, though corticosteroid treatment can meaningfully extend this timeframe."},{"id": 6720,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Corticosteroid therapy (e.g., prednisone, deflazacort) in DMD management is used primarily to:","options": [{"key": "A","text": "Address only cardiac symptoms with no effect on skeletal muscle strength"},{"key": "B","text": "Slow the rate of muscle strength decline and prolong ambulation/function"},{"key": "C","text": "Only address pain symptoms with no effect on disease progression"},{"key": "D","text": "Cure the underlying genetic dystrophin deficiency completely"}],"correct": "B","explanation": "Corticosteroids have demonstrated benefit in slowing DMD progression and prolonging ambulation/function, despite requiring careful management of associated side effects."},{"id": 6721,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Contracture prevention is a major focus of DMD physiotherapy management particularly affecting which joints?","options": [{"key": "A","text": "No joints are particularly predisposed to contracture in DMD"},{"key": "B","text": "Ankle (equinus), knee, and hip flexors, with upper limb joints also becoming affected as the disease progresses"},{"key": "C","text": "Only affecting the cervical spine with no other joint involvement"},{"key": "D","text": "Only affecting the temporomandibular joint"}],"correct": "B","explanation": "DMD commonly causes contractures at the ankle (equinus), knee, and hip flexors due to muscle imbalance and reduced mobility, with upper limb joints becoming increasingly affected as the disease progresses and mobility further declines."},{"id": 6722,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Respiratory decline is an expected part of DMD progression, related to weakness of:","options": [{"key": "A","text": "Never occurring in DMD regardless of disease stage"},{"key": "B","text": "Only occurring in the earliest disease stage before ambulation loss"},{"key": "C","text": "Respiratory muscles including diaphragm and intercostals"},{"key": "D","text": "Only affecting cardiac muscle, not respiratory muscles"}],"correct": "C","explanation": "Progressive respiratory muscle weakness is an expected feature of DMD progression, requiring regular respiratory monitoring and eventually ventilatory support consideration as the disease advances."},{"id": 6723,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration regarding exercise intensity in DMD management, given concerns about eccentric loading in dystrophic muscle?","options": [{"key": "A","text": "Avoiding excessive/high-resistance eccentric exercise which may accelerate muscle damage, favoring moderate, non-fatiguing activity approaches"},{"key": "B","text": "Exercise intensity has no relevance to DMD management planning"},{"key": "C","text": "Complete avoidance of any exercise/activity throughout the entire disease course"},{"key": "D","text": "Maximal eccentric resistance training is always beneficial regardless of the underlying dystrophic process"}],"correct": "A","explanation": "Dystrophic muscle in DMD may be particularly vulnerable to damage from high-intensity eccentric loading, making moderate, carefully monitored exercise approaches generally preferred over maximal resistance training."},{"id": 6724,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the timely introduction consideration for wheelchair provision as DMD-related ambulation becomes increasingly difficult?","options": [{"key": "A","text": "Wheelchair provision should always be delayed as long as possible regardless of safety or energy conservation concerns"},{"key": "B","text": "Wheelchair provision timing has no relevance to overall functional outcomes or quality of life"},{"key": "C","text": "Wheelchairs are never appropriate at any stage of DMD management"},{"key": "D","text": "Timely introduction supports safe mobility and energy conservation as walking becomes progressively more difficult/unsafe"}],"correct": "D","explanation": "Timely wheelchair introduction (power or manual, as appropriate) supports continued safe mobility and energy conservation as walking becomes increasingly difficult, an important comprehensive DMD care planning consideration."},{"id": 6725,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Spinal Muscular Atrophy (SMA) results from degeneration of:","options": [{"key": "A","text": "Peripheral sensory nerves exclusively"},{"key": "B","text": "Anterior horn cells (lower motor neurons) in the spinal cord"},{"key": "C","text": "Cerebellar Purkinje cells exclusively"},{"key": "D","text": "Upper motor neurons exclusively"}],"correct": "B","explanation": "SMA is a genetic condition (related to SMN1 gene) causing progressive anterior horn cell degeneration, producing lower motor neuron pattern weakness."},{"id": 6726,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "SMA Type 1 (Werdnig-Hoffmann disease), the most severe classical form, typically presents with onset:","options": [{"key": "A","text": "Exclusively affecting upper limb function with normal lower limb strength"},{"key": "B","text": "Only in adulthood"},{"key": "C","text": "Before 6 months of age with severe, rapidly progressive weakness"},{"key": "D","text": "After age 10 with mild symptoms"}],"correct": "C","explanation": "SMA Type 1 presents in early infancy (before 6 months) with severe hypotonia/weakness, historically carrying poor prognosis, though newer disease-modifying therapies have substantially changed outcomes for many patients."},{"id": 6727,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "SMA Type 2, an intermediate severity form, typically allows achievement of which motor milestone but not independent ambulation?","options": [{"key": "A","text": "No motor milestone achievement whatsoever"},{"key": "B","text": "Independent sitting"},{"key": "C","text": "Only head control, with no further motor development possible"},{"key": "D","text": "Independent walking"}],"correct": "B","explanation": "SMA Type 2 typically allows children to achieve independent sitting, but not independent ambulation, representing an intermediate severity level between Type 1 and Type 3."},{"id": 6728,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "SMA Type 3 (Kugelberg-Welander disease), the mildest classical childhood-onset form, typically allows:","options": [{"key": "A","text": "Onset exclusively in adulthood, never in childhood"},{"key": "B","text": "Identical severity/prognosis to SMA Type 1"},{"key": "C","text": "Achievement of independent ambulation, though with potential later functional decline"},{"key": "D","text": "Never allows independent sitting or any motor milestone achievement"}],"correct": "C","explanation": "SMA Type 3 typically allows children to achieve independent ambulation, representing the mildest classical childhood-onset SMA form, though some individuals may experience functional decline over time."},{"id": 6729,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Newer disease-modifying therapies for SMA (e.g., nusinersen, onasemnogene abeparvovec gene therapy) work by:","options": [{"key": "A","text": "Curing the condition exclusively through surgical intervention"},{"key": "B","text": "Having no meaningful effect on the underlying disease process or trajectory"},{"key": "C","text": "Addressing the underlying genetic/molecular SMN protein deficiency"},{"key": "D","text": "Only providing symptomatic pain relief with no effect on the underlying disease process"}],"correct": "C","explanation": "Modern SMA therapies target the underlying molecular deficiency (increasing functional SMN protein), representing significant advancement that has substantially changed disease trajectory and prognosis for many patients when appropriately timed."},{"id": 6730,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Congenital myopathies, a group of conditions sometimes relevant to pediatric physiotherapy practice, are characterized by:","options": [{"key": "A","text": "Structural/functional muscle abnormalities typically presenting with hypotonia and weakness from early infancy"},{"key": "B","text": "A condition with no relevance to physiotherapy assessment or management"},{"key": "C","text": "A condition identical to muscular dystrophy with no distinguishing features"},{"key": "D","text": "A condition exclusively affecting adults, never presenting in infancy"}],"correct": "A","explanation": "Congenital myopathies represent a group of genetically heterogeneous conditions causing structural/functional muscle abnormalities, typically presenting with early hypotonia and weakness, relevant to pediatric physiotherapy assessment/management."},{"id": 6731,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Congenital Myasthenic Syndromes differ from acquired (autoimmune) myasthenia gravis in that they result from:","options": [{"key": "A","text": "A condition exclusively affecting adults, never presenting in childhood"},{"key": "B","text": "Genetic defects affecting neuromuscular junction function, rather than an acquired autoimmune process"},{"key": "C","text": "An identical autoimmune mechanism to typical myasthenia gravis"},{"key": "D","text": "A condition unrelated to any neuromuscular junction pathology"}],"correct": "B","explanation": "Congenital myasthenic syndromes result from inherited genetic defects affecting various neuromuscular junction components, distinct from the acquired autoimmune mechanism underlying typical myasthenia gravis."},{"id": 6732,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important physiotherapy assessment consideration for infants presenting with significant hypotonia ('floppy infant'), given the broad differential diagnosis?","options": [{"key": "A","text": "Hypotonia assessment has no relevance to physiotherapy practice"},{"key": "B","text": "Assuming all hypotonic infants have an identical underlying cause requiring the same management approach"},{"key": "C","text": "Requires comprehensive assessment considering the wide range of potential causes (central, peripheral nerve, neuromuscular junction, or primary muscle disease)"},{"key": "D","text": "Hypotonia is always caused by cerebral palsy with no other possible differential diagnosis"}],"correct": "C","explanation": "The 'floppy infant' presentation has a broad differential diagnosis spanning central, peripheral nerve, neuromuscular junction, and primary muscle disease causes, requiring comprehensive assessment (often within a broader medical evaluation) to appropriately identify the underlying etiology."},{"id": 6733,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding scoliosis development in children with neuromuscular conditions (e.g., SMA, DMD) as weakness progresses?","options": [{"key": "A","text": "Increased scoliosis risk related to trunk muscle weakness, warranting regular monitoring as part of comprehensive musculoskeletal surveillance"},{"key": "B","text": "Scoliosis risk is identical to typically developing children with no additional consideration needed"},{"key": "C","text": "Scoliosis never occurs in children with neuromuscular conditions"},{"key": "D","text": "Scoliosis monitoring is irrelevant to physiotherapy practice for this population"}],"correct": "A","explanation": "Progressive trunk muscle weakness in neuromuscular conditions significantly increases scoliosis risk, warranting regular monitoring as an important component of comprehensive musculoskeletal surveillance."},{"id": 6734,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding seating/positioning equipment for children with progressive neuromuscular weakness affecting trunk control?","options": [{"key": "A","text": "Seating considerations have no relevance to neuromuscular condition management"},{"key": "B","text": "Appropriate seating support helps maintain postural alignment, comfort, and function as trunk control weakens with disease progression"},{"key": "C","text": "Seating equipment needs remain completely static throughout the disease course with no need for reassessment"},{"key": "D","text": "All children with neuromuscular conditions require identical seating equipment regardless of their specific weakness pattern"}],"correct": "B","explanation": "As trunk control weakens with neuromuscular disease progression, appropriately individualized seating/positioning equipment supports postural alignment, comfort, and continued functional participation, requiring regular reassessment as needs evolve."},{"id": 6735,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding respiratory physiotherapy involvement for children with progressive neuromuscular conditions affecting respiratory muscle strength?","options": [{"key": "A","text": "Techniques supporting secretion clearance and respiratory function become increasingly important as respiratory muscle weakness progresses"},{"key": "B","text": "Respiratory physiotherapy has no relevance to neuromuscular condition management"},{"key": "C","text": "Respiratory considerations are only relevant once a child requires full-time ventilatory support, never before"},{"key": "D","text": "Respiratory muscle strength is never affected in pediatric neuromuscular conditions"}],"correct": "A","explanation": "As respiratory muscle weakness progresses in many pediatric neuromuscular conditions, respiratory physiotherapy techniques (secretion clearance support, breathing exercises) become an increasingly important component of comprehensive management."},{"id": 6736,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Hard","question": "Which of the following describes an important consideration regarding multidisciplinary team involvement in comprehensive pediatric neuromuscular condition management?","options": [{"key": "A","text": "A single specialist can adequately manage all aspects of pediatric neuromuscular condition care"},{"key": "B","text": "Multidisciplinary team involvement has no evidence base in pediatric neuromuscular condition management"},{"key": "C","text": "Physiotherapy should operate in complete isolation from all other team members regardless of the condition's complexity"},{"key": "D","text": "Given the multisystem impact (musculoskeletal, respiratory, cardiac, nutritional, psychosocial), coordinated multidisciplinary team care is considered best practice"}],"correct": "D","explanation": "Given the often multisystem impact of pediatric neuromuscular conditions, coordinated multidisciplinary team care (medical, therapy, nutritional, psychosocial) is considered best practice for comprehensive management."},{"id": 6737,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Easy","question": "Which of the following describes an important consideration regarding family/caregiver education and support for families of children with progressive neuromuscular conditions?","options": [{"key": "A","text": "Providing honest, sensitively delivered information alongside practical caregiving education and psychosocial support is an important component of comprehensive care"},{"key": "B","text": "Families should be given no information regarding the progressive nature of the condition"},{"key": "C","text": "Assuming identical family support needs regardless of the specific condition or individual family circumstances"},{"key": "D","text": "Physiotherapy has no role in family education for children with neuromuscular conditions"}],"correct": "A","explanation": "Honest, appropriately sensitive communication combined with practical caregiving education and psychosocial support represents an important, ongoing component of comprehensive care for families of children with progressive neuromuscular conditions."},{"id": 6738,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding genetic testing/newborn screening relevance to early identification of conditions like SMA?","options": [{"key": "A","text": "Newborn screening programs increasingly include SMA in some regions, supporting earlier identification and treatment initiation given time-sensitive treatment benefit"},{"key": "B","text": "Newborn screening is universally available and identical across all regions globally with no variation"},{"key": "C","text": "Early identification provides no benefit regarding treatment timing or outcomes"},{"key": "D","text": "Genetic testing/newborn screening has no relevance to SMA identification or management"}],"correct": "A","explanation": "Given the availability of time-sensitive disease-modifying SMA therapies, newborn screening inclusion (increasingly implemented in various regions) supports earlier identification and treatment initiation, with growing evidence suggesting improved outcomes from earlier intervention."},{"id": 6739,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy goal-setting for a child with a progressive neuromuscular condition, differing somewhat from goal-setting in a non-progressive condition like cerebral palsy?","options": [{"key": "A","text": "Goals should remain completely static and unchanged throughout the entire disease course regardless of progression"},{"key": "B","text": "Requires ongoing reassessment and adaptation of goals considering the expected disease trajectory, alongside maintaining focus on current functional priorities and quality of life"},{"key": "C","text": "Progressive conditions require no goal-setting since decline is considered inevitable regardless of intervention"},{"key": "D","text": "Goal-setting principles are identical for progressive and non-progressive pediatric conditions with no need for any distinction"}],"correct": "B","explanation": "Goal-setting for progressive neuromuscular conditions requires ongoing reassessment and thoughtful adaptation considering the expected disease trajectory, while still maintaining meaningful focus on current functional priorities and quality of life, differing from the potentially more stable goal-setting context in non-progressive conditions."},{"id": 6740,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding equipment/technology needs evolution for children with progressive neuromuscular conditions as the disease advances?","options": [{"key": "A","text": "Equipment/technology considerations have no relevance to physiotherapy practice in this population"},{"key": "B","text": "Assuming identical equipment needs for all children regardless of their specific condition or disease stage"},{"key": "C","text": "Equipment needs remain completely static once initially established, requiring no future reassessment"},{"key": "D","text": "Regular reassessment supports timely adaptation/provision of appropriate equipment (mobility, seating, respiratory support) matching the child's evolving needs"}],"correct": "D","explanation": "Given the progressive nature of many pediatric neuromuscular conditions, regular reassessment supporting timely adaptation of equipment (mobility aids, seating, potentially respiratory support) is important for matching provision to the child's evolving functional needs."},{"id": 6741,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Hard","question": "Which of the following describes an important consideration regarding pain assessment in children with neuromuscular conditions, particularly those with more advanced weakness/limited communication ability?","options": [{"key": "A","text": "Pain assessment is irrelevant to comprehensive neuromuscular condition management"},{"key": "B","text": "Requires careful, appropriate assessment approaches (potentially including observational tools) given that pain from various sources (musculoskeletal, positioning-related) can occur but may be under-recognized"},{"key": "C","text": "Only relying on caregiver assumption without any structured assessment approach when self-report is limited"},{"key": "D","text": "Assuming pain never occurs in children with neuromuscular conditions given their muscle weakness"}],"correct": "B","explanation": "Pain (from various sources including musculoskeletal positioning-related factors) can occur in children with neuromuscular conditions and may be under-recognized, particularly in those with limited communication ability, warranting careful, appropriate assessment approaches within comprehensive care."},{"id": 6742,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Congenital myotonic dystrophy, the most severe form of myotonic dystrophy presenting from birth, is characterized by:","options": [{"key": "A","text": "A condition identical to Duchenne muscular dystrophy with no distinguishing features"},{"key": "B","text": "Onset exclusively in adulthood with no possible neonatal presentation"},{"key": "C","text": "Severe hypotonia and weakness present from birth, often with significant respiratory/feeding difficulty"},{"key": "D","text": "A condition with no relevance to pediatric physiotherapy practice"}],"correct": "C","explanation": "Congenital myotonic dystrophy presents with severe neonatal hypotonia/weakness, often with significant associated respiratory and feeding difficulties, representing the most severe end of the myotonic dystrophy spectrum."},{"id": 6743,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'natural history' data for progressive neuromuscular conditions, relevant to counseling families and setting realistic expectations?","options": [{"key": "A","text": "Understanding typical disease trajectory (based on natural history studies) helps inform appropriate counseling and goal-setting, while recognizing individual variation and the impact of emerging treatments"},{"key": "B","text": "All children with a given neuromuscular condition show an identical, completely predictable disease course with no variation"},{"key": "C","text": "Natural history data is only relevant for research purposes with no practical clinical application"},{"key": "D","text": "Natural history data has no relevance to family counseling or goal-setting"}],"correct": "A","explanation": "Natural history data provides valuable context for understanding typical disease trajectories, informing appropriate family counseling and goal-setting, while clinicians should also recognize individual variation and the potential impact of newer disease-modifying treatments on traditionally described natural history patterns."},{"id": 6744,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding upper limb function assessment/intervention in children with DMD, given that upper limb weakness typically progresses after lower limb ambulation loss?","options": [{"key": "A","text": "Upper limb weakness never occurs in DMD, only lower limb involvement is relevant"},{"key": "B","text": "Ongoing assessment and appropriate intervention (including consideration of assistive technology) addressing upper limb function remains important as the disease progresses beyond ambulation loss"},{"key": "C","text": "Upper limb assessment becomes irrelevant once a child loses independent ambulation"},{"key": "D","text": "Physiotherapy involvement ends completely once ambulation is lost regardless of ongoing upper limb needs"}],"correct": "B","explanation": "As DMD progresses beyond ambulation loss, upper limb weakness typically becomes increasingly significant, making ongoing assessment and appropriate intervention (including assistive technology consideration) for upper limb function an important continuing focus of comprehensive care."},{"id": 6745,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'quality of life' focus within comprehensive care planning for children with severe, progressive neuromuscular conditions?","options": [{"key": "A","text": "Quality of life focus should only begin once a child reaches the most advanced disease stage, not earlier in the disease course"},{"key": "B","text": "Quality of life considerations are irrelevant once a condition is classified as progressive/severe"},{"key": "C","text": "Maintaining focus on the child's comfort, meaningful participation, and overall quality of life remains an important goal throughout the disease course, alongside disease-specific management"},{"key": "D","text": "Comprehensive care planning should focus exclusively on disease-modifying treatment with no attention to broader quality of life considerations"}],"correct": "C","explanation": "Maintaining a consistent focus on the child's comfort, meaningful participation, and overall quality of life throughout the disease course (alongside appropriate disease-specific management) is an important, holistic component of comprehensive care for children with severe, progressive neuromuscular conditions."},{"id": 6746,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding creatine kinase (CK) levels, often significantly elevated in conditions like DMD, relevant to understanding disease pathophysiology?","options": [{"key": "A","text": "Elevated CK reflects ongoing muscle fiber membrane damage/leakage, a laboratory marker relevant to diagnosis though not directly used for physiotherapy treatment planning"},{"key": "B","text": "CK levels have no relevance to muscular dystrophy diagnosis or understanding"},{"key": "C","text": "CK is only relevant to cardiac conditions, never to muscle disease"},{"key": "D","text": "Assuming CK levels directly guide physiotherapy exercise dosing decisions with no other consideration needed"}],"correct": "A","explanation": "Significantly elevated CK levels reflect ongoing muscle fiber membrane damage/leakage characteristic of dystrophinopathies like DMD, an important diagnostic laboratory marker, though physiotherapy exercise dosing decisions are guided by broader clinical assessment rather than CK level alone."},{"id": 6747,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "Developmental Coordination Disorder (DCD) is characterized by:","options": [{"key": "A","text": "A condition always associated with significant intellectual disability"},{"key": "B","text": "Diagnostic criteria identical to cerebral palsy"},{"key": "C","text": "Motor coordination difficulty significantly below expected level for age, impacting daily function, without another explanatory neurological condition"},{"key": "D","text": "Onset exclusively in adulthood"}],"correct": "C","explanation": "DCD describes significant motor coordination impairment affecting functional performance, in the absence of another diagnosed neurological condition (like CP) that would otherwise explain the motor difficulty."},{"id": 6748,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following functional areas is commonly affected in children with DCD?","options": [{"key": "A","text": "DCD has no impact on any daily functional activity"},{"key": "B","text": "Only cognitive/academic function with no motor-related impact"},{"key": "C","text": "Only affecting gross motor skills, never fine motor tasks"},{"key": "D","text": "Handwriting, sports participation, and self-care tasks (e.g., dressing, using cutlery)"}],"correct": "D","explanation": "DCD commonly affects a range of functional motor tasks including handwriting, sports/physical activity participation, and self-care skills, significantly impacting daily function."},{"id": 6749,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding DCD diagnosis, given its differentiation from other conditions with motor impairment?","options": [{"key": "A","text": "DCD is diagnosed identically to cerebral palsy with no distinguishing diagnostic process"},{"key": "B","text": "DCD diagnosis requires no differentiation from any other condition"},{"key": "C","text": "DCD only affects children with a known specific genetic cause"},{"key": "D","text": "Requires ruling out other explanatory conditions (e.g., cerebral palsy, muscular dystrophy) as DCD is a diagnosis of exclusion regarding other specific neurological/medical causes"}],"correct": "D","explanation": "DCD diagnosis involves appropriately ruling out other conditions that could explain the motor coordination difficulty (e.g., CP, muscular dystrophy, significant intellectual disability), as DCD specifically describes coordination difficulty not otherwise explained by another diagnosed condition."},{"id": 6750,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important physiotherapy intervention approach commonly used for children with DCD?","options": [{"key": "A","text": "Complete avoidance of any motor skill practice for children with DCD"},{"key": "B","text": "Assuming DCD always resolves spontaneously without requiring any intervention"},{"key": "C","text": "Only passive range of motion exercises with no active skill practice component"},{"key": "D","text": "Task-specific practice addressing functional motor skill deficits impacting daily activities/participation"}],"correct": "D","explanation": "DCD intervention typically focuses on task-specific practice addressing the specific functional motor skills impacting the child's daily activities and participation (e.g., handwriting practice, specific sport skill practice)."},{"id": 6751,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following approaches to DCD intervention emphasizes teaching children specific strategies/steps to accomplish functional motor tasks, rather than addressing presumed underlying deficits directly?","options": [{"key": "A","text": "An approach with no evidence base or theoretical rationale for DCD intervention"},{"key": "B","text": "Cognitive Orientation to daily Occupational Performance (CO-OP) or similar task-specific, problem-solving approaches"},{"key": "C","text": "An approach focusing exclusively on passive stretching with no active problem-solving component"},{"key": "D","text": "An approach identical to constraint-induced movement therapy used in stroke rehabilitation"}],"correct": "B","explanation": "Task-specific, problem-solving approaches (such as CO-OP) teach children specific cognitive strategies to accomplish functional motor tasks, representing an evidence-supported intervention approach for DCD."},{"id": 6752,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes a 'process-oriented' or 'bottom-up' approach to DCD intervention, historically used but with generally weaker evidence support compared to task-specific approaches?","options": [{"key": "A","text": "A term unrelated to any DCD intervention approach"},{"key": "B","text": "Addressing presumed underlying sensory/perceptual-motor deficits, assuming this will generalize to improve broader functional skills"},{"key": "C","text": "An approach identical to task-specific functional skill practice"},{"key": "D","text": "An approach with the strongest current evidence base for DCD intervention"}],"correct": "B","explanation": "Process-oriented/bottom-up approaches target presumed underlying deficits (e.g., sensory processing, balance components) hoping for generalization to functional skills; current evidence generally favors more direct task-specific approaches for DCD intervention."},{"id": 6753,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding co-occurring conditions sometimes seen alongside DCD?","options": [{"key": "A","text": "DCD never co-occurs with any other developmental condition"},{"key": "B","text": "Co-occurring conditions have no relevance to DCD intervention planning"},{"key": "C","text": "All children with DCD have identical co-occurring conditions requiring the same standardized intervention approach"},{"key": "D","text": "DCD frequently co-occurs with conditions such as ADHD, learning disabilities, and autism spectrum features, relevant to comprehensive assessment"}],"correct": "D","explanation": "DCD frequently co-occurs with other conditions (ADHD, learning disabilities, autism spectrum features), relevant to comprehensive assessment and individualized intervention planning considering the child's full presentation."},{"id": 6754,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Autism Spectrum Disorder (ASD) is primarily characterized by which core features?","options": [{"key": "A","text": "A condition identical to Down syndrome with no distinguishing features"},{"key": "B","text": "A condition characterized exclusively by motor impairment with no social/communication features"},{"key": "C","text": "Only affecting cognitive function with no impact on social communication"},{"key": "D","text": "Persistent difficulties in social communication/interaction, alongside restricted/repetitive behaviors or interests"}],"correct": "D","explanation": "ASD core diagnostic features include persistent social communication/interaction difficulties combined with restricted, repetitive patterns of behavior/interests/activities."},{"id": 6755,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the prevalence relationship between ASD and motor coordination difficulties?","options": [{"key": "A","text": "Motor difficulties are the primary/sole diagnostic feature of ASD"},{"key": "B","text": "Motor coordination is never affected in children with ASD"},{"key": "C","text": "Many children with ASD show co-occurring motor coordination difficulties, sometimes meeting criteria for co-occurring DCD"},{"key": "D","text": "This relationship has no relevance to physiotherapy practice"}],"correct": "C","explanation": "A significant proportion of children with ASD show co-occurring motor coordination difficulties, sometimes meeting diagnostic criteria for co-occurring DCD, relevant to comprehensive physiotherapy assessment in this population."},{"id": 6756,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding sensory processing differences commonly seen in children with ASD, relevant to physiotherapy intervention approach?","options": [{"key": "A","text": "May show hyper- or hypo-sensitivity to various sensory input (tactile, auditory, vestibular), requiring thoughtful consideration in therapy environment/activity design"},{"key": "B","text": "All children with ASD show an identical sensory processing pattern requiring no individualized consideration"},{"key": "C","text": "Sensory processing is never affected in any child with ASD"},{"key": "D","text": "Sensory considerations are solely an occupational therapy responsibility with no relevance to physiotherapy"}],"correct": "A","explanation": "Children with ASD frequently show individualized patterns of sensory sensitivity/processing differences, relevant to thoughtfully designing the physiotherapy treatment environment and activity approach for effective engagement."},{"id": 6757,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding communication approach when providing physiotherapy for a child with ASD who has limited verbal communication?","options": [{"key": "A","text": "Assuming verbal instruction alone is always sufficient regardless of the child's communication profile"},{"key": "B","text": "Physiotherapy should never be attempted for children with limited verbal communication"},{"key": "C","text": "Communication approach adaptation has no relevance to physiotherapy practice for this population"},{"key": "D","text": "Using visual supports, clear simple language, and considering alternative/augmentative communication methods where relevant supports effective engagement"}],"correct": "D","explanation": "Adapting communication approach (visual supports, simplified language, considering AAC where relevant) supports more effective physiotherapy engagement for children with ASD who have limited verbal communication ability."},{"id": 6758,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding routine/predictability in therapy session structure for children with ASD?","options": [{"key": "A","text": "Many children with ASD benefit from predictable routine/structure, which can reduce anxiety and support engagement during therapy sessions"},{"key": "B","text": "Maximum unpredictability and constant novelty is always preferred for children with ASD"},{"key": "C","text": "All children with ASD show an identical preference for routine with no individual variation"},{"key": "D","text": "Routine/predictability has no relevance to therapy engagement for children with ASD"}],"correct": "A","explanation": "Many children with ASD benefit from predictable session structure/routine, which can help reduce anxiety and support more effective therapeutic engagement, though individualized preferences should always be considered."},{"id": 6759,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the use of special interests/preferred activities in physiotherapy intervention planning for children with ASD?","options": [{"key": "A","text": "Special interests have no relevance to physiotherapy intervention planning for children with ASD"},{"key": "B","text": "Incorporating the child's special interests/preferred activities into therapeutic tasks can enhance motivation and engagement"},{"key": "C","text": "Special interests should always be avoided during therapy sessions to maintain focus on generic goals"},{"key": "D","text": "Assuming special interests are irrelevant distractions that should never be incorporated into any therapeutic activity"}],"correct": "B","explanation": "Thoughtfully incorporating a child's special interests or preferred activities into therapeutic tasks can enhance motivation and engagement, an effective strategy sometimes used in physiotherapy intervention for children with ASD."},{"id": 6760,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physical activity/exercise participation benefits for children with ASD, beyond addressing specific motor coordination difficulties?","options": [{"key": "A","text": "Children with ASD should never participate in group-based physical activity"},{"key": "B","text": "Physical activity provides no benefit beyond addressing isolated motor coordination difficulties"},{"key": "C","text": "Regular physical activity may offer additional benefits including potential positive impact on behavior, sleep, and overall wellbeing, alongside addressing motor skill development"},{"key": "D","text": "Exercise/physical activity has no relevance to comprehensive ASD management"}],"correct": "C","explanation": "Beyond addressing specific motor coordination needs, regular physical activity participation may offer additional benefits for children with ASD including potential positive impacts on behavior, sleep, and overall wellbeing, supporting its inclusion within comprehensive management."},{"id": 6761,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding transition support (e.g., between activities or environments) for children with ASD during physiotherapy sessions?","options": [{"key": "A","text": "Transitions have no relevance to physiotherapy practice for children with ASD"},{"key": "B","text": "Providing clear warning/preparation for transitions (e.g., visual timers, verbal cues) can help reduce anxiety and support smoother session flow"},{"key": "C","text": "Transition support is solely a special education responsibility with no relevance to physiotherapy sessions"},{"key": "D","text": "Assuming abrupt, unannounced transitions are always well-tolerated regardless of the child's individual presentation"}],"correct": "B","explanation": "Providing clear preparation/warning for transitions between activities (using visual timers, consistent verbal cues, or other individualized strategies) can help reduce anxiety and support smoother engagement during physiotherapy sessions for children with ASD."},{"id": 6762,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding parent/caregiver involvement in physiotherapy intervention for children with ASD?","options": [{"key": "A","text": "Parent involvement has no relevance to physiotherapy outcomes for children with ASD"},{"key": "B","text": "Active parent/caregiver involvement supports carryover of strategies to the home/community environment and consistency of approach"},{"key": "C","text": "Parents should always be excluded from therapy sessions for children with ASD"},{"key": "D","text": "Assuming identical parent involvement needs regardless of the individual family's circumstances or preferences"}],"correct": "B","explanation": "Active parent/caregiver involvement supports important carryover of therapeutic strategies to the home and community environment, along with consistency of approach, an important component of effective intervention for children with ASD."},{"id": 6763,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding group-based physical activity/therapy programs for children with ASD, given the potential social interaction demands?","options": [{"key": "A","text": "Assuming identical group program suitability regardless of the individual child's specific social/sensory profile"},{"key": "B","text": "Group-based programs should never be considered for any child with ASD given social interaction difficulties"},{"key": "C","text": "Group programs provide no potential benefit beyond what individual sessions offer"},{"key": "D","text": "Can offer social skill practice opportunities alongside motor benefits, though requiring thoughtful consideration of group size/structure appropriate to individual needs"}],"correct": "D","explanation": "Appropriately structured group-based physical activity programs can offer valuable social interaction practice alongside motor skill benefits for some children with ASD, though careful individualized consideration of group size, structure, and the specific child's needs is important."},{"id": 6764,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding motor planning (praxis) difficulties sometimes observed in children with ASD?","options": [{"key": "A","text": "Motor planning difficulties are identical to simple muscle weakness with no distinct clinical consideration"},{"key": "B","text": "Difficulty planning and sequencing novel motor tasks can occur, relevant to how new skills are introduced and practiced in therapy"},{"key": "C","text": "This consideration has no relevance to physiotherapy intervention approach for children with ASD"},{"key": "D","text": "Motor planning is never affected in any child with ASD"}],"correct": "B","explanation": "Motor planning (praxis) difficulties, distinct from simple strength/coordination issues, can occur in children with ASD, relevant to how new motor skills are thoughtfully introduced, broken down, and practiced within physiotherapy intervention."},{"id": 6765,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding assessment tool selection for evaluating motor skills in children with ASD, given potential communication/attention differences?","options": [{"key": "A","text": "Standard motor assessment tools always require no adaptation regardless of the child's individual ASD-related presentation"},{"key": "B","text": "Assessment tool selection has no relevance to obtaining accurate results for this population"},{"key": "C","text": "Motor assessment is never appropriate or valid for children with ASD"},{"key": "D","text": "Selecting appropriately validated tools and adapting administration approach (considering communication needs, attention span, sensory preferences) supports more accurate assessment"}],"correct": "D","explanation": "Thoughtful selection of appropriately validated assessment tools, combined with individualized administration adaptation (considering communication, attention, and sensory factors), supports more accurate and meaningful motor assessment for children with ASD."},{"id": 6766,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the potential impact of anxiety on physical activity/therapy participation for some children with ASD?","options": [{"key": "A","text": "Assuming identical anxiety levels and triggers across all children with ASD with no individual variation"},{"key": "B","text": "Anxiety considerations are entirely irrelevant to physiotherapy practice"},{"key": "C","text": "Anxiety (sometimes related to sensory sensitivities, unpredictability, or social demands) can significantly impact participation, relevant to thoughtful session/activity planning"},{"key": "D","text": "Anxiety never affects therapy participation for children with ASD"}],"correct": "C","explanation": "Recognizing that anxiety (often related to sensory sensitivities, unpredictability, or social demands) can significantly impact a child's participation and engagement supports more thoughtful, individualized session and activity planning for children with ASD."},{"id": 6767,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding realistic goal-setting for physiotherapy intervention in children with co-occurring ASD and DCD?","options": [{"key": "A","text": "Individualized goal-setting considering both the specific motor coordination difficulties and relevant ASD-related factors (communication, sensory, behavioral) supports meaningful, achievable intervention planning"},{"key": "B","text": "Assuming co-occurring ASD automatically means no meaningful motor goals can be established"},{"key": "C","text": "Physiotherapy goal-setting has no relevance for children with co-occurring ASD and DCD"},{"key": "D","text": "Goals should be identical to those set for children with DCD alone, with no consideration of co-occurring ASD-related factors"}],"correct": "A","explanation": "Individualized goal-setting that thoughtfully considers both the specific motor coordination difficulties (DCD) and relevant ASD-related factors (communication style, sensory preferences, behavioral considerations) supports more meaningful, achievable, and effectively implemented intervention planning."},{"id": 6768,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the general prognosis/trajectory for motor coordination difficulties in DCD without specific intervention?","options": [{"key": "A","text": "DCD shows no relationship to any long-term functional outcome"},{"key": "B","text": "Assuming identical outcomes for all children with DCD regardless of intervention or lack thereof"},{"key": "C","text": "DCD always resolves spontaneously by early childhood without requiring any intervention"},{"key": "D","text": "DCD-related motor difficulties often persist into adolescence/adulthood without intervention, relevant to supporting appropriate early identification and management"}],"correct": "D","explanation": "Without appropriate intervention, DCD-related motor coordination difficulties often persist into adolescence and adulthood, potentially impacting various life domains, supporting the rationale for appropriate early identification and evidence-based intervention."},{"id": 6769,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding self-esteem/psychosocial impact for children with DCD, relevant to a holistic physiotherapy approach?","options": [{"key": "A","text": "DCD never affects self-esteem or peer relationships regardless of severity"},{"key": "B","text": "Psychosocial impact has no relevance to physiotherapy practice for children with DCD"},{"key": "C","text": "Physiotherapy should focus exclusively on motor skills with no consideration of any psychosocial factors"},{"key": "D","text": "Motor coordination difficulties can significantly impact self-esteem and social participation (e.g., peer relationships, sports involvement), relevant to considering psychosocial factors alongside motor skill intervention"}],"correct": "D","explanation": "Given the potential significant impact of motor coordination difficulties on self-esteem and social participation (peer relationships, sports involvement), considering these psychosocial factors alongside direct motor skill intervention supports a more holistic physiotherapy approach for children with DCD."},{"id": 6770,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding handwriting difficulties commonly seen in children with DCD, relevant to physiotherapy/occupational therapy collaborative involvement?","options": [{"key": "A","text": "Physiotherapy has no potential contribution to addressing handwriting-related difficulties in children with DCD"},{"key": "B","text": "Often relates to underlying fine motor coordination and postural control difficulties, benefiting from coordinated therapy input addressing both proximal stability and distal fine motor skill"},{"key": "C","text": "Handwriting is solely an educational concern with no relevance to therapy involvement"},{"key": "D","text": "Handwriting difficulties are entirely unrelated to any motor coordination consideration"}],"correct": "B","explanation": "Handwriting difficulties in DCD often relate to underlying postural control and fine motor coordination challenges, benefiting from coordinated physiotherapy/occupational therapy input addressing both proximal stability and distal fine motor skill components."},{"id": 6771,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding ball skills (catching, throwing, kicking) difficulties commonly seen in children with DCD, relevant to intervention planning?","options": [{"key": "A","text": "Assuming ball skill difficulties always resolve spontaneously without requiring any specific practice or intervention"},{"key": "B","text": "Often represents a common area of functional difficulty impacting sports/play participation, addressed through graded, task-specific practice"},{"key": "C","text": "Ball skill difficulties have no relevance to physiotherapy intervention planning"},{"key": "D","text": "Ball skills are never affected in children with DCD"}],"correct": "B","explanation": "Ball skills (catching, throwing, kicking) commonly represent an area of functional difficulty for children with DCD, significantly impacting sports and play participation, often addressed through graded, task-specific practice within physiotherapy intervention."},{"id": 6772,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding bilateral coordination (using both sides of the body together) difficulties sometimes seen in children with DCD?","options": [{"key": "A","text": "This consideration has no relevance to physiotherapy assessment or intervention approach"},{"key": "B","text": "Can affect functional tasks requiring coordinated use of both body sides (e.g., riding a bicycle, some dressing tasks), relevant to targeted intervention planning"},{"key": "C","text": "Bilateral coordination is never relevant to DCD-related functional difficulties"},{"key": "D","text": "Bilateral coordination difficulties only affect upper limb tasks, never whole-body activities"}],"correct": "B","explanation": "Bilateral coordination difficulties (using both body sides together effectively) can impact various functional tasks in children with DCD, relevant to comprehensive assessment and targeted intervention addressing this specific coordination component."},{"id": 6773,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'automaticity' of motor skills, relevant to understanding functional impact in DCD?","options": [{"key": "A","text": "Automaticity has no relevance to understanding DCD-related functional difficulties"},{"key": "B","text": "All motor skills are equally automatic for children with DCD as for typically developing peers"},{"key": "C","text": "Children with DCD often require more conscious attention/effort for motor tasks that would typically become automatic with practice, impacting dual-task performance (e.g., walking while carrying an object)"},{"key": "D","text": "This concept is irrelevant to physiotherapy intervention planning for DCD"}],"correct": "C","explanation": "Reduced automaticity of motor skills in DCD (requiring more conscious effort/attention than typical) can impact dual-task performance and overall functional efficiency, relevant to understanding the broader functional impact of the condition beyond isolated skill assessment."},{"id": 6774,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physical education (PE) class participation/modification for children with DCD within the school setting?","options": [{"key": "A","text": "Appropriate modification/support within PE settings can promote continued participation and positive experience, potentially involving collaboration with school staff"},{"key": "B","text": "Children with DCD should always be completely excluded from PE class participation"},{"key": "C","text": "PE-related considerations have no relevance to physiotherapy practice for children with DCD"},{"key": "D","text": "Assuming identical PE participation approaches are appropriate regardless of the individual child's specific difficulties"}],"correct": "A","explanation": "Thoughtful modification and support within PE settings, potentially involving physiotherapy collaboration with school staff, can promote continued positive participation for children with DCD, supporting both physical activity engagement and psychosocial wellbeing."},{"id": 6775,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following best summarizes the overall contemporary evidence-based approach to physiotherapy intervention for DCD?","options": [{"key": "A","text": "Physiotherapy intervention has no evidence base for DCD management"},{"key": "B","text": "Passive treatment approaches without any active skill practice represent the most effective approach for DCD"},{"key": "C","text": "A single fixed protocol applied identically to every child with DCD regardless of their specific functional difficulties or goals"},{"key": "D","text": "Task-specific, individualized intervention addressing functionally relevant motor skills, informed by best available evidence and the child/family's specific goals and context"}],"correct": "D","explanation": "Contemporary evidence-based DCD physiotherapy practice emphasizes task-specific, individualized intervention addressing functionally meaningful motor skills, tailored to each child's specific presentation, goals, and context, rather than a generic, non-specific approach."},{"id": 6776,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the potential value of peer-modeling within group-based motor skill intervention for children with DCD?","options": [{"key": "A","text": "Observing peers successfully performing tasks may provide additional motivation and learning opportunity, alongside direct therapist instruction"},{"key": "B","text": "Peer modeling has no potential value within DCD intervention approaches"},{"key": "C","text": "Group-based intervention should never be considered for children with DCD"},{"key": "D","text": "Assuming peer modeling always negatively impacts a child's motivation or engagement regardless of individual context"}],"correct": "A","explanation": "Within appropriately structured group-based intervention, observing peers successfully performing motor tasks may provide valuable additional motivation and learning opportunity for children with DCD, complementing direct therapist instruction."},{"id": 6777,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Juvenile Idiopathic Arthritis (JIA) diagnostic criteria require arthritis onset before what age, persisting for at least how long?","options": [{"key": "A","text": "Onset only after age 16"},{"key": "B","text": "Onset before age 5 exclusively"},{"key": "C","text": "Onset before age 16, persisting at least 6 weeks"},{"key": "D","text": "Persisting for only 24 hours"}],"correct": "C","explanation": "JIA diagnostic criteria require arthritis onset before age 16, persisting at least 6 weeks, with other potential causes appropriately excluded."},{"id": 6778,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Oligoarticular JIA, the most common subtype, is defined by involvement of how many joints in the first 6 months of disease?","options": [{"key": "A","text": "Five or more joints"},{"key": "B","text": "Four or fewer joints"},{"key": "C","text": "All joints simultaneously"},{"key": "D","text": "Only a single joint, never more"}],"correct": "B","explanation": "Oligoarticular JIA involves four or fewer joints within the first 6 months of disease onset, the most common JIA subtype."},{"id": 6779,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Polyarticular JIA is defined by involvement of how many joints within the first 6 months of disease?","options": [{"key": "A","text": "This subtype is defined by systemic symptoms rather than joint count"},{"key": "B","text": "Five or more joints"},{"key": "C","text": "Four or fewer joints exclusively"},{"key": "D","text": "Only a single joint"}],"correct": "B","explanation": "Polyarticular JIA involves five or more joints within the first 6 months, distinguishing it from the oligoarticular subtype."},{"id": 6780,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Systemic JIA is characterized by which distinguishing features beyond joint involvement?","options": [{"key": "A","text": "Joint involvement exclusively with no systemic features whatsoever"},{"key": "B","text": "Systemic features including fever, rash, and potential internal organ involvement"},{"key": "C","text": "A condition entirely unrelated to any inflammatory process"},{"key": "D","text": "Onset exclusively in adulthood, never in childhood"}],"correct": "B","explanation": "Systemic JIA presents with characteristic systemic features (quotidian fever, evanescent rash, and potential organ involvement) alongside arthritis, distinguishing it from other JIA subtypes."},{"id": 6781,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Morning stiffness is a common symptom in JIA; physiotherapy management addressing this often includes:","options": [{"key": "A","text": "Aggressive stretching immediately upon waking regardless of pain level"},{"key": "B","text": "Complete avoidance of any morning activity or exercise"},{"key": "C","text": "Gentle morning range of motion exercises and warmth application to help ease stiffness"},{"key": "D","text": "Only relevant for adult rheumatoid arthritis, never for JIA"}],"correct": "C","explanation": "Gentle morning exercise and warmth application are common strategies to help manage the characteristic morning stiffness associated with JIA, supporting improved function through the day."},{"id": 6782,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding joint protection principles taught to children with JIA and their families?","options": [{"key": "A","text": "Joint protection principles have no relevance to pediatric rheumatology management"},{"key": "B","text": "Assuming identical joint protection needs regardless of the specific joints affected"},{"key": "C","text": "Techniques to reduce excessive stress on affected joints during daily activities, balanced with maintaining function and activity engagement"},{"key": "D","text": "Complete joint immobilization is always recommended regardless of disease activity"}],"correct": "C","explanation": "Joint protection education helps reduce excessive stress on affected joints during daily activities, while balancing this with maintaining function and healthy activity engagement, individualized to the specific pattern of joint involvement."},{"id": 6783,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration regarding exercise participation for children with JIA during a disease flare versus a quieter disease period?","options": [{"key": "A","text": "Management typically balances appropriate rest of acutely inflamed joints during flares with encouraging maintained activity/exercise during quieter periods"},{"key": "B","text": "Exercise has no relevance to JIA management at any point in the disease course"},{"key": "C","text": "Complete rest is always recommended throughout the entire disease course regardless of flare status"},{"key": "D","text": "Maximal intensity exercise should always be maintained regardless of active joint inflammation"}],"correct": "A","explanation": "JIA physiotherapy management typically involves appropriately balancing rest of acutely inflamed joints during flares with encouraging maintained activity and exercise during quieter disease periods, supporting overall physical function and fitness."},{"id": 6784,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding growth-related complications sometimes seen in JIA, particularly with chronic joint inflammation?","options": [{"key": "A","text": "Chronic inflammation can affect local growth plates, potentially causing limb length discrepancy or localized growth disturbance"},{"key": "B","text": "Growth is never affected by JIA regardless of disease severity or duration"},{"key": "C","text": "This complication only occurs in adult-onset arthritis, never in JIA"},{"key": "D","text": "Growth-related considerations are irrelevant to physiotherapy assessment in JIA"}],"correct": "A","explanation": "Chronic joint inflammation in JIA can affect local growth plates, potentially causing limb length discrepancy or other localized growth disturbances, relevant to comprehensive musculoskeletal monitoring."},{"id": 6785,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Uveitis, an important extra-articular complication sometimes associated with JIA (particularly certain subtypes), refers to:","options": [{"key": "A","text": "A term identical to arthritis with no distinguishing features"},{"key": "B","text": "A complication with no relevance to comprehensive JIA management"},{"key": "C","text": "A condition affecting only the cardiovascular system"},{"key": "D","text": "Inflammation of the eye (uveal tract), requiring regular ophthalmological screening given risk of vision-threatening complications if undetected"}],"correct": "D","explanation": "Uveitis (eye inflammation) is a significant extra-articular JIA complication, particularly associated with certain subtypes (e.g., oligoarticular JIA, especially ANA-positive), requiring regular ophthalmological screening given risk of silent progression to vision-threatening complications."},{"id": 6786,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding hydrotherapy (aquatic therapy) benefits for children with JIA?","options": [{"key": "A","text": "Buoyancy-assisted movement allows exercise with reduced joint loading, potentially beneficial for pain management and maintaining mobility"},{"key": "B","text": "Hydrotherapy has no evidence-based benefit for children with JIA"},{"key": "C","text": "Complete replacement of all land-based therapy is always appropriate for JIA management"},{"key": "D","text": "Hydrotherapy is contraindicated for any child with active joint inflammation"}],"correct": "A","explanation": "Hydrotherapy's buoyancy-assisted movement properties can be particularly beneficial for children with JIA, allowing exercise with reduced joint loading, supporting pain management and continued mobility."},{"id": 6787,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding splinting sometimes used in JIA management?","options": [{"key": "A","text": "Splinting is never used in pediatric rheumatology management"},{"key": "B","text": "Splinting always requires complete, permanent joint immobilization with no functional use allowed"},{"key": "C","text": "All children with JIA require identical splinting regardless of their specific joint involvement pattern"},{"key": "D","text": "May be used to help maintain joint position/alignment, manage pain, or address specific functional needs, individualized to the child's presentation"}],"correct": "D","explanation": "Splinting may be individually considered in JIA management to help address specific concerns (positioning, pain, function), tailored to the child's particular pattern of joint involvement and needs, rather than a uniform approach."},{"id": 6788,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding disease-modifying antirheumatic drugs (DMARDs) and biologic therapies in contemporary JIA management, relevant to overall physiotherapy planning?","options": [{"key": "A","text": "Physiotherapy should be planned in complete isolation from any consideration of the child's medical management"},{"key": "B","text": "Pharmacological management has no relevance to physiotherapy practice or planning"},{"key": "C","text": "Modern pharmacological management has significantly improved disease control for many children, relevant context for physiotherapy goal-setting alongside medical management"},{"key": "D","text": "All children with JIA show identical response to pharmacological treatment regardless of specific medication"}],"correct": "C","explanation": "Understanding that modern DMARD/biologic therapies have significantly improved disease control for many children with JIA provides important context for physiotherapy goal-setting, ideally coordinated within the broader multidisciplinary management approach."},{"id": 6789,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding school participation support for children with JIA experiencing joint pain/stiffness?","options": [{"key": "A","text": "School-related considerations have no relevance to physiotherapy practice"},{"key": "B","text": "School participation is never affected by JIA regardless of disease severity"},{"key": "C","text": "May require accommodations (e.g., modified PE participation, assistance with certain tasks) supported by appropriate communication with school staff"},{"key": "D","text": "Assuming identical school accommodation needs regardless of the individual child's specific joint involvement and functional status"}],"correct": "C","explanation": "Depending on disease severity/joint involvement, some children with JIA may benefit from school accommodations, with physiotherapy potentially contributing to appropriate communication/recommendations supporting successful school participation."},{"id": 6790,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding footwear/orthotic recommendations for children with JIA affecting the lower limb joints?","options": [{"key": "A","text": "Footwear considerations are irrelevant to JIA management"},{"key": "B","text": "All children with JIA require identical footwear regardless of their specific joint involvement pattern"},{"key": "C","text": "Appropriate supportive footwear or orthoses may help manage pain and support function for affected foot/ankle/knee joints"},{"key": "D","text": "Orthotic intervention is never appropriate for children with inflammatory arthritis"}],"correct": "C","explanation": "Appropriately individualized footwear or orthotic recommendations can help manage pain and support function for children with JIA affecting lower limb joints, tailored to the specific pattern and severity of involvement."},{"id": 6791,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding psychosocial support for children with JIA, given the chronic nature of the condition?","options": [{"key": "A","text": "JIA never has any psychosocial impact regardless of disease severity or chronicity"},{"key": "B","text": "Psychosocial factors have no relevance to comprehensive JIA management"},{"key": "C","text": "Psychosocial support is solely a psychology/social work responsibility with no relevance to physiotherapy interaction"},{"key": "D","text": "Chronic illness can significantly impact psychosocial wellbeing, making attention to this domain (alongside physical management) an important component of comprehensive care"}],"correct": "D","explanation": "Given the chronic nature of JIA and its potential impact on activity participation, peer relationships, and self-image, attention to psychosocial wellbeing (alongside physical management) is an important component of holistic, comprehensive care."},{"id": 6792,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding physiotherapy assessment frequency/monitoring for children with JIA, given the condition's often fluctuating course?","options": [{"key": "A","text": "A single initial assessment is always sufficient with no need for any follow-up monitoring"},{"key": "B","text": "Assessment frequency has no relevance to effective JIA physiotherapy management"},{"key": "C","text": "Assuming disease activity and functional status remain completely static throughout the condition's course"},{"key": "D","text": "Regular reassessment supports timely adaptation of intervention as disease activity and functional status change over time"}],"correct": "D","explanation": "Given the often fluctuating nature of JIA disease activity, regular physiotherapy reassessment supports timely adaptation of intervention approach as the child's status changes over time."},{"id": 6793,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physical activity/sports participation recommendations for children with JIA during periods of good disease control?","options": [{"key": "A","text": "Regular physical activity/sports participation is generally encouraged during quieter disease periods, supporting fitness, function, and psychosocial wellbeing, with individualized consideration of any specific joint precautions"},{"key": "B","text": "Complete avoidance of any physical activity/sports is always recommended regardless of disease activity level"},{"key": "C","text": "Assuming identical activity recommendations regardless of the child's specific joint involvement or current disease status"},{"key": "D","text": "Physical activity has no relevance to JIA management during any disease phase"}],"correct": "A","explanation": "During periods of good disease control, regular physical activity/sports participation is generally encouraged, supporting fitness, function, and psychosocial wellbeing, with individualized consideration of any specific precautions related to particular joint involvement."},{"id": 6794,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the general goal of physiotherapy intervention across the various JIA subtypes?","options": [{"key": "A","text": "Physiotherapy intervention should focus exclusively on pain relief with no consideration of function or activity participation"},{"key": "B","text": "A single identical treatment protocol should be applied regardless of the specific JIA subtype or individual presentation"},{"key": "C","text": "Maintaining/optimizing joint function, muscle strength, and overall physical activity participation, individualized to the specific subtype and pattern of involvement"},{"key": "D","text": "Physiotherapy goals are irrelevant given that JIA is managed exclusively through pharmacological treatment"}],"correct": "C","explanation": "While pharmacological management addresses the underlying inflammatory disease process, physiotherapy plays an important complementary role in maintaining/optimizing joint function, strength, and physical activity participation, individualized to each child's specific JIA subtype and presentation."},{"id": 6795,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding temporomandibular joint (TMJ) involvement, which can occur in some children with JIA?","options": [{"key": "A","text": "TMJ involvement is identical in presentation and management to typical limb joint involvement with no distinguishing features"},{"key": "B","text": "TMJ-related considerations have no relevance to comprehensive JIA assessment"},{"key": "C","text": "Can affect jaw function/growth, potentially requiring specific assessment and management approaches beyond typical limb joint considerations"},{"key": "D","text": "TMJ involvement never occurs in JIA regardless of subtype"}],"correct": "C","explanation": "TMJ involvement, which can occur in some children with JIA, may affect jaw function and even facial growth, requiring specific assessment consideration beyond the more commonly emphasized limb joint involvement, often involving coordination with dental/orthodontic specialists."},{"id": 6796,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding multidisciplinary team involvement in comprehensive JIA management?","options": [{"key": "A","text": "Multidisciplinary team involvement has no evidence base or relevance to JIA management"},{"key": "B","text": "Physiotherapy should operate in complete isolation from all other team members regardless of the condition's complexity"},{"key": "C","text": "Coordination between rheumatology, physiotherapy, occupational therapy, and other relevant specialists supports comprehensive addressing of the condition's multisystem potential impact"},{"key": "D","text": "A single discipline can independently manage all aspects of JIA care without any need for coordination"}],"correct": "C","explanation": "Given JIA's potential multisystem impact (joints, eyes, growth, psychosocial wellbeing), coordinated multidisciplinary team management supports comprehensive, well-integrated care addressing the full scope of the condition's potential effects."},{"id": 6797,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Asthma in children is characterized by:","options": [{"key": "A","text": "A condition unrelated to any airway inflammatory process"},{"key": "B","text": "Reversible airway obstruction with airway inflammation and hyperresponsiveness"},{"key": "C","text": "A condition exclusively affecting adults, never children"},{"key": "D","text": "Irreversible, progressive airway destruction"}],"correct": "B","explanation": "Pediatric asthma involves reversible airway obstruction related to underlying airway inflammation and bronchial hyperresponsiveness to various triggers."},{"id": 6798,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Common asthma triggers in children include:","options": [{"key": "A","text": "Only occurring in response to cold weather exposure exclusively"},{"key": "B","text": "Allergens, respiratory infections, exercise, and irritants (e.g., smoke)"},{"key": "C","text": "A condition with no identifiable triggers in any child"},{"key": "D","text": "Only genetic factors with no environmental trigger component"}],"correct": "B","explanation": "Multiple trigger categories (allergens, infections, exercise, irritants) can provoke asthma symptoms/exacerbations in susceptible children."},{"id": 6799,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Exercise-induced bronchoconstriction, relevant to physiotherapy exercise prescription for children with asthma, refers to:","options": [{"key": "A","text": "A condition unrelated to underlying asthma"},{"key": "B","text": "Airway narrowing triggered by physical exertion, typically manageable with appropriate precautions/medication"},{"key": "C","text": "A term identical to general asthma with no distinguishing features"},{"key": "D","text": "A condition indicating exercise should always be completely avoided"}],"correct": "B","explanation": "Exercise-induced bronchoconstriction describes airway narrowing triggered specifically by physical exertion, generally manageable with appropriate pre-exercise medication and activity modification, rather than requiring complete exercise avoidance."},{"id": 6800,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physical activity/exercise recommendations for children with well-controlled asthma?","options": [{"key": "A","text": "Physical activity has no relevance to comprehensive asthma management"},{"key": "B","text": "Exercise always worsens asthma control regardless of management approach"},{"key": "C","text": "Regular physical activity is generally encouraged, with appropriate precautions (e.g., pre-exercise bronchodilator use if indicated) for those with exercise-induced symptoms"},{"key": "D","text": "Complete avoidance of any physical activity is always recommended for children with asthma"}],"correct": "C","explanation": "With appropriate management (including pre-exercise medication where indicated), regular physical activity participation is generally encouraged and beneficial for children with asthma, supporting overall fitness and asthma control."},{"id": 6801,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Cystic Fibrosis (CF) results from mutations affecting which gene/protein?","options": [{"key": "A","text": "SMN1"},{"key": "B","text": "A gene unrelated to any specific protein function"},{"key": "C","text": "CFTR (Cystic Fibrosis Transmembrane conductance Regulator)"},{"key": "D","text": "Dystrophin"}],"correct": "C","explanation": "CF results from CFTR gene mutations, affecting chloride channel function and causing abnormally thick, sticky secretions affecting multiple organ systems, particularly lungs and pancreas."},{"id": 6802,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "CF is inherited in which pattern?","options": [{"key": "A","text": "Autosomal recessive"},{"key": "B","text": "Autosomal dominant"},{"key": "C","text": "X-linked recessive"},{"key": "D","text": "Mitochondrial inheritance"}],"correct": "A","explanation": "CF follows autosomal recessive inheritance, requiring two copies of the mutated CFTR gene (one from each parent) for the condition to manifest."},{"id": 6803,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Airway clearance techniques are a cornerstone of CF respiratory physiotherapy management, aiming to:","options": [{"key": "A","text": "Mobilize and clear thick, tenacious secretions from the airways, reducing infection risk and supporting lung function"},{"key": "B","text": "Only relevant during acute exacerbations, never as ongoing maintenance management"},{"key": "C","text": "Replace the need for any pharmacological CF management"},{"key": "D","text": "Only provide symptomatic comfort with no impact on secretion clearance"}],"correct": "A","explanation": "Airway clearance techniques are fundamental, ongoing CF physiotherapy management, aiming to mobilize and clear the characteristic thick, sticky secretions, reducing infection risk and supporting long-term lung function preservation."},{"id": 6804,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an example of a manual airway clearance technique sometimes used in CF management?","options": [{"key": "A","text": "Complete avoidance of any physical airway clearance approach"},{"key": "B","text": "A technique exclusively used for adult patients, never in pediatric CF management"},{"key": "C","text": "Percussion and postural drainage"},{"key": "D","text": "Only pharmacological mucolytic medication with no physical technique component"}],"correct": "C","explanation": "Percussion and postural drainage represent a traditional manual airway clearance technique, among various approaches (including device-assisted and active cycle breathing techniques) used in CF respiratory management."},{"id": 6805,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Active Cycle of Breathing Technique (ACBT) is an airway clearance approach that combines:","options": [{"key": "A","text": "A technique requiring specialized expensive equipment only, with no self-administered component"},{"key": "B","text": "Only percussion with no active breathing component"},{"key": "C","text": "A technique exclusively relevant to adult respiratory conditions, never used in pediatric practice"},{"key": "D","text": "Breathing control, thoracic expansion exercises, and forced expiration technique (huffing)"}],"correct": "D","explanation": "ACBT combines relaxed breathing control, deep breathing (thoracic expansion) exercises, and huffing (forced expiration technique) in a structured cycle to mobilize and clear secretions."},{"id": 6806,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes a device-assisted airway clearance technique sometimes used in CF management?","options": [{"key": "A","text": "Only manual percussion with no device-based options available"},{"key": "B","text": "Positive Expiratory Pressure (PEP) devices or oscillating PEP devices (e.g., flutter, acapella)"},{"key": "C","text": "Devices are never used in pediatric CF airway clearance management"},{"key": "D","text": "A technique unrelated to any airway clearance goal"}],"correct": "B","explanation": "Various devices (PEP, oscillating PEP) provide alternative or complementary airway clearance approaches, offering options for independent/self-administered technique as children grow older."},{"id": 6807,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding exercise participation for children with CF, beyond its general fitness benefits?","options": [{"key": "A","text": "Exercise has no additional benefit beyond general fitness for children with CF"},{"key": "B","text": "Regular exercise can also contribute to airway clearance and is associated with better long-term lung function outcomes"},{"key": "C","text": "Exercise should always be avoided given the underlying lung disease"},{"key": "D","text": "Exercise participation has no relevance to comprehensive CF management"}],"correct": "B","explanation": "Beyond general fitness benefits, regular exercise in CF can contribute to airway secretion clearance and is associated with better long-term lung function trajectories, making it an important, actively encouraged component of comprehensive CF management."},{"id": 6808,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding CFTR modulator therapies, an evolving area of CF treatment, relevant to overall physiotherapy management context?","options": [{"key": "A","text": "CFTR modulators have no relevance to CF management or physiotherapy planning context"},{"key": "B","text": "Physiotherapy airway clearance is no longer needed for any patient once CFTR modulator therapy is initiated"},{"key": "C","text": "All patients with CF respond identically to CFTR modulator therapy regardless of their specific genetic mutation"},{"key": "D","text": "These therapies target the underlying CFTR protein defect and have significantly improved outcomes for many patients with specific eligible mutations, relevant context for comprehensive care planning"}],"correct": "D","explanation": "CFTR modulator therapies (targeting the underlying protein defect) have significantly improved outcomes for many CF patients with eligible mutations; while transformative, ongoing airway clearance/physiotherapy typically remains an important component of comprehensive care alongside these therapies for most patients."},{"id": 6809,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Bronchiolitis, a common lower respiratory tract infection in infants, is most commonly caused by:","options": [{"key": "A","text": "A condition exclusively affecting children over 5 years of age"},{"key": "B","text": "Respiratory Syncytial Virus (RSV)"},{"key": "C","text": "Bacterial infection exclusively"},{"key": "D","text": "A genetic condition unrelated to any infectious cause"}],"correct": "B","explanation": "RSV is the most common causative organism for bronchiolitis, a viral lower respiratory tract infection particularly affecting infants and young children."},{"id": 6810,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Bronchiolitis typically presents with which combination of symptoms in an infant?","options": [{"key": "A","text": "Only isolated fever with no respiratory symptoms whatsoever"},{"key": "B","text": "Only affecting the gastrointestinal system with no respiratory involvement"},{"key": "C","text": "Wheeze, cough, and respiratory distress, often following initial upper respiratory symptoms"},{"key": "D","text": "A condition with no observable clinical symptoms"}],"correct": "C","explanation": "Bronchiolitis typically presents with wheeze, cough, and varying degrees of respiratory distress, commonly following initial upper respiratory tract symptoms."},{"id": 6811,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes current evidence regarding routine chest physiotherapy for uncomplicated acute bronchiolitis?","options": [{"key": "A","text": "Physiotherapy has no role whatsoever in any aspect of bronchiolitis-related care"},{"key": "B","text": "Chest physiotherapy is the definitive first-line treatment for all cases of bronchiolitis regardless of severity"},{"key": "C","text": "Chest physiotherapy is always definitively beneficial and should be routinely applied for every case of bronchiolitis"},{"key": "D","text": "Current evidence generally does not support routine chest physiotherapy (e.g., percussion/vibration) for typical uncomplicated bronchiolitis"}],"correct": "D","explanation": "Contemporary evidence-based guidelines generally do not support routine conventional chest physiotherapy for typical uncomplicated bronchiolitis, reflecting an important evolution in practice based on accumulated research evidence, though nasal suctioning and supportive care remain relevant."},{"id": 6812,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an appropriate primary management approach for uncomplicated bronchiolitis, given the current evidence base?","options": [{"key": "A","text": "Complete hospitalization is required for every single case regardless of severity"},{"key": "B","text": "Supportive care including adequate hydration, nasal suctioning as needed, and monitoring, as the condition is typically self-limiting"},{"key": "C","text": "Immediate chest physiotherapy intervention for every case"},{"key": "D","text": "Aggressive antibiotic treatment for all cases regardless of the viral etiology"}],"correct": "B","explanation": "Given the typically self-limiting viral nature of uncomplicated bronchiolitis, primary management emphasizes supportive care (hydration, nasal suctioning, monitoring), with hospitalization reserved for more severe presentations requiring closer monitoring/support."},{"id": 6813,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Pneumonia in children can result from various pathogens; physiotherapy involvement, when indicated, typically focuses on:","options": [{"key": "A","text": "Physiotherapy is never relevant to pediatric pneumonia management under any circumstances"},{"key": "B","text": "Supporting secretion clearance and respiratory function in select cases, particularly those with significant secretion retention or underlying comorbidity"},{"key": "C","text": "Physiotherapy replaces the need for any antibiotic treatment in bacterial pneumonia"},{"key": "D","text": "Physiotherapy should be applied identically and routinely to every single case of pediatric pneumonia regardless of clinical presentation"}],"correct": "B","explanation": "Physiotherapy involvement in pediatric pneumonia is typically selective, focusing on cases with significant secretion retention concerns or underlying comorbidities affecting clearance ability, rather than being routinely applied to all cases."},{"id": 6814,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding chest physiotherapy for children with neuromuscular conditions who develop a respiratory infection, given their underlying weakness?","options": [{"key": "A","text": "Assuming identical respiratory management needs regardless of any underlying neuromuscular weakness"},{"key": "B","text": "May be particularly beneficial given compromised cough effectiveness/secretion clearance ability related to their underlying muscle weakness"},{"key": "C","text": "Chest physiotherapy is always contraindicated in the presence of any respiratory infection"},{"key": "D","text": "Physiotherapy has no relevance for children with neuromuscular conditions during respiratory illness"}],"correct": "B","explanation": "Children with underlying neuromuscular weakness affecting cough effectiveness may particularly benefit from physiotherapy-assisted secretion clearance techniques during respiratory illness, given their compromised ability to clear secretions independently."},{"id": 6815,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding assisted cough techniques (e.g., manual assisted cough) sometimes used for children with respiratory muscle weakness?","options": [{"key": "A","text": "This technique has no relevance to airway clearance in any pediatric respiratory condition"},{"key": "B","text": "Assisted cough techniques are never appropriate for use in pediatric patients"},{"key": "C","text": "Can help augment an ineffective cough, supporting secretion clearance in children with conditions causing significant respiratory muscle weakness"},{"key": "D","text": "Assisted cough techniques replace the need for any other respiratory management approach"}],"correct": "C","explanation": "Manual or mechanically assisted cough techniques can help augment inadequate cough effectiveness, supporting secretion clearance particularly relevant for children with conditions causing significant respiratory muscle weakness (e.g., advanced neuromuscular disease)."},{"id": 6816,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding incentive spirometry sometimes used post-operatively or in certain respiratory conditions in children old enough to cooperate?","options": [{"key": "A","text": "Aims to encourage deep breathing/lung expansion, potentially helping prevent atelectasis, requiring adequate child cooperation/understanding for effective use"},{"key": "B","text": "Incentive spirometry always requires no patient cooperation or understanding whatsoever"},{"key": "C","text": "This technique has no physiological rationale or purpose"},{"key": "D","text": "Incentive spirometry is only ever used in adult patients, never appropriate for children"}],"correct": "A","explanation": "Incentive spirometry encourages deep breathing/lung expansion (helping prevent atelectasis in relevant contexts like post-operative care), requiring the child to have sufficient cooperation/understanding to use the device effectively, generally more applicable to older children."},{"id": 6817,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding secretion clearance technique selection for a very young infant compared to an older cooperative child?","options": [{"key": "A","text": "Identical techniques are always appropriate and effective regardless of the child's age or developmental stage"},{"key": "B","text": "Very young infants require more passive/facilitated techniques (e.g., positioning, gentle percussion/vibration by the therapist) given their inability to actively participate in techniques like huffing"},{"key": "C","text": "Secretion clearance techniques are never relevant for infants under any circumstances"},{"key": "D","text": "Only active, self-administered techniques should ever be used regardless of the child's developmental capability"}],"correct": "B","explanation": "Technique selection must be adapted to the child's developmental stage/ability to cooperate, with very young infants requiring more passive/therapist-facilitated approaches compared to older children who can actively participate in techniques like ACBT or device-assisted methods."},{"id": 6818,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding humidification/hydration in supporting secretion clearance for children with respiratory conditions involving thick secretions (e.g., CF)?","options": [{"key": "A","text": "Humidification is never used in pediatric respiratory management"},{"key": "B","text": "Hydration has no relevance to secretion clearance effectiveness"},{"key": "C","text": "Adequate hydration and, in some cases, humidification/nebulized therapies can help optimize secretion viscosity, supporting more effective clearance"},{"key": "D","text": "This consideration is entirely unrelated to any airway clearance technique effectiveness"}],"correct": "C","explanation": "Adequate hydration and appropriate humidification/nebulized therapies (as clinically indicated) can help optimize secretion viscosity, supporting the effectiveness of airway clearance techniques, particularly relevant in conditions like CF with characteristically thick secretions."},{"id": 6819,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding recurrent wheeze in infants/toddlers, given the broad differential diagnosis beyond typical asthma?","options": [{"key": "A","text": "All recurrent wheeze in young children definitively represents asthma with no other possible cause"},{"key": "B","text": "Assuming an identical underlying cause and management approach for all cases of recurrent wheeze regardless of the child's specific presentation"},{"key": "C","text": "Requires careful clinical evaluation as the differential includes various causes (viral-induced wheeze, structural airway abnormalities, and others) beyond typical asthma presentation seen in older children"},{"key": "D","text": "Recurrent wheeze has no relevance to physiotherapy assessment or broader medical evaluation"}],"correct": "C","explanation": "Recurrent wheeze in young children has a broader differential diagnosis than typical asthma seen in older children, requiring careful clinical evaluation to appropriately identify the underlying cause and guide management."},{"id": 6820,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy involvement in supporting children with chronic respiratory conditions to participate in age-appropriate physical activity?","options": [{"key": "A","text": "Children with any chronic respiratory condition should always be completely excluded from physical activity participation"},{"key": "B","text": "Physiotherapy has no role in supporting physical activity participation for children with respiratory conditions"},{"key": "C","text": "Assuming identical physical activity capacity and recommendations regardless of the specific respiratory condition or its severity"},{"key": "D","text": "Individualized exercise prescription/guidance can support safe, beneficial physical activity participation despite the underlying respiratory condition"}],"correct": "D","explanation": "Individualized physiotherapy-guided exercise prescription can support safe, beneficial physical activity participation for children with various chronic respiratory conditions, tailored to their specific condition, severity, and current status."},{"id": 6821,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding multidisciplinary team involvement in comprehensive management of children with complex chronic respiratory conditions like CF?","options": [{"key": "A","text": "A single discipline can independently manage all aspects of CF care without any need for coordination"},{"key": "B","text": "Coordinated input from respiratory medicine, physiotherapy, dietetics, and other relevant specialists supports comprehensive management of this multisystem condition"},{"key": "C","text": "Multidisciplinary team involvement has no evidence base or relevance to CF management"},{"key": "D","text": "Physiotherapy should operate in complete isolation from all other CF team members"}],"correct": "B","explanation": "Given the multisystem impact of conditions like CF (respiratory, nutritional, and other involvement), coordinated multidisciplinary team management is considered standard best practice for comprehensive care."},{"id": 6822,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding family/caregiver training in airway clearance techniques for children with CF who require ongoing home-based management?","options": [{"key": "A","text": "Assuming families require no specific training or support to implement these techniques effectively"},{"key": "B","text": "Comprehensive training supports effective, consistent home-based technique implementation as part of the child's ongoing daily management routine"},{"key": "C","text": "Family training is unnecessary since airway clearance should only ever be performed by healthcare professionals in clinical settings"},{"key": "D","text": "Airway clearance techniques are only ever relevant during hospital admissions, never as part of routine home management"}],"correct": "B","explanation": "Given the need for regular, ongoing airway clearance as part of CF daily management, comprehensive family/caregiver training supports effective, consistent home-based implementation of these important techniques."},{"id": 6823,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding monitoring for signs of respiratory deterioration in children with chronic respiratory conditions, relevant to physiotherapy practice?","options": [{"key": "A","text": "Assuming respiratory status always remains completely stable with no need for any ongoing monitoring"},{"key": "B","text": "Physiotherapists have no role in monitoring for any signs of respiratory deterioration"},{"key": "C","text": "Awareness of signs suggesting worsening respiratory status (increased work of breathing, changes in secretion characteristics, reduced exercise tolerance) supports timely escalation/medical review"},{"key": "D","text": "Only medical staff can ever recognize or respond to signs of respiratory deterioration"}],"correct": "C","explanation": "Physiotherapists working with children with chronic respiratory conditions should maintain awareness of signs suggesting potential deterioration, supporting timely communication/escalation to the medical team as part of comprehensive, safe ongoing management."},{"id": 6824,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Croup (laryngotracheobronchitis), a common pediatric respiratory condition, is characterized by:","options": [{"key": "A","text": "A condition identical to bronchiolitis with no distinguishing clinical features"},{"key": "B","text": "A characteristic barking cough and stridor, typically related to viral upper airway inflammation"},{"key": "C","text": "A condition exclusively affecting the lower respiratory tract with no upper airway involvement"},{"key": "D","text": "A bacterial infection requiring immediate surgical intervention in all cases"}],"correct": "B","explanation": "Croup classically presents with a characteristic barking cough and stridor, typically related to viral-induced upper airway (laryngeal/tracheal) inflammation and narrowing."},{"id": 6825,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding chest physiotherapy relevance for typical uncomplicated croup, similar to the evidence regarding bronchiolitis?","options": [{"key": "A","text": "Chest physiotherapy is generally not indicated for typical uncomplicated croup, which primarily involves upper airway pathology rather than lower airway secretion retention"},{"key": "B","text": "Croup always requires identical management to cystic fibrosis-related respiratory complications"},{"key": "C","text": "Physiotherapy has extensive, well-established evidence supporting routine involvement in uncomplicated croup management"},{"key": "D","text": "Chest physiotherapy is the definitive first-line treatment for all cases of croup regardless of severity"}],"correct": "A","explanation": "Given that croup primarily involves upper airway inflammation/narrowing rather than lower airway secretion retention, chest physiotherapy techniques are generally not indicated for typical uncomplicated presentations, with management instead focusing on other supportive/medical approaches."},{"id": 6826,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding air travel or high-altitude exposure for children with certain chronic respiratory conditions, relevant to comprehensive condition management awareness?","options": [{"key": "A","text": "All children with respiratory conditions are always completely restricted from any air travel"},{"key": "B","text": "Air travel and altitude have no relevance to any pediatric respiratory condition"},{"key": "C","text": "Assuming identical travel-related risk regardless of the specific respiratory condition or its severity"},{"key": "D","text": "May require specific precautions/medical clearance depending on the underlying condition and severity, relevant context for comprehensive family education"}],"correct": "D","explanation": "For children with certain chronic respiratory conditions, air travel or high-altitude exposure may warrant specific precautions or medical clearance depending on the condition and severity, relevant context for comprehensive family education as part of holistic condition management."},{"id": 6827,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Congenital heart defects are broadly classified into which two main categories based on oxygenation status?","options": [{"key": "A","text": "Only acyanotic defects exist in pediatric practice"},{"key": "B","text": "Cyanotic and acyanotic (non-cyanotic) defects"},{"key": "C","text": "Only cyanotic defects exist in pediatric practice"},{"key": "D","text": "Left-sided and right-sided defects exclusively, with no relevance to cyanosis"}],"correct": "B","explanation": "Congenital heart defects are commonly classified as cyanotic (causing decreased blood oxygenation, e.g., Tetralogy of Fallot) or acyanotic (e.g., ventricular septal defect), informing clinical presentation and management approach."},{"id": 6828,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Ventricular Septal Defect (VSD), one of the most common congenital heart defects, involves:","options": [{"key": "A","text": "An abnormal opening between the atria exclusively"},{"key": "B","text": "An abnormal opening between the left and right ventricles"},{"key": "C","text": "A condition affecting only the pulmonary artery"},{"key": "D","text": "Narrowing of the aortic valve exclusively"}],"correct": "B","explanation": "VSD involves an abnormal communication between the ventricles, causing left-to-right shunting in typical presentations, one of the most common congenital heart defects."},{"id": 6829,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Tetralogy of Fallot, a common cyanotic congenital heart defect, comprises which four components?","options": [{"key": "A","text": "Four separate unrelated conditions occurring coincidentally together"},{"key": "B","text": "VSD, pulmonary stenosis, overriding aorta, and right ventricular hypertrophy"},{"key": "C","text": "A condition affecting only the venous system with no arterial involvement"},{"key": "D","text": "Only a single isolated cardiac defect despite the name suggesting otherwise"}],"correct": "B","explanation": "Tetralogy of Fallot comprises the classic combination of VSD, pulmonary stenosis, overriding aorta, and right ventricular hypertrophy, causing characteristic cyanosis."},{"id": 6830,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding exercise/activity recommendations for children with congenital heart disease, relevant to physiotherapy involvement?","options": [{"key": "A","text": "Individualized recommendations based on the specific defect, repair status, and current cardiac function, often guided by cardiology input alongside physiotherapy assessment"},{"key": "B","text": "All children with any congenital heart defect should be completely restricted from any physical activity permanently"},{"key": "C","text": "Exercise recommendations are identical regardless of the specific cardiac defect or repair status"},{"key": "D","text": "Physiotherapy has no role in supporting appropriate activity participation for this population"}],"correct": "A","explanation": "Exercise/activity recommendations for children with congenital heart disease require individualization based on the specific defect, any surgical repair status, and current cardiac function, typically informed by cardiology guidance alongside physiotherapy involvement in supporting appropriate participation."},{"id": 6831,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "Which of the following describes an important consideration regarding developmental delay risk in children with significant congenital heart disease, particularly those requiring complex early surgical intervention?","options": [{"key": "A","text": "Developmental monitoring is irrelevant for children with congenital heart disease regardless of severity"},{"key": "B","text": "All children with congenital heart disease show identical developmental trajectories regardless of defect complexity or treatment course"},{"key": "C","text": "Congenital heart disease never has any impact on neurodevelopmental outcomes"},{"key": "D","text": "Increased risk of developmental delay is recognized in this population, relevant to appropriate developmental monitoring and early intervention consideration"}],"correct": "D","explanation": "Children with significant congenital heart disease, particularly those requiring complex early surgery, show increased risk of developmental delay, relevant to appropriate developmental surveillance and consideration of early intervention services as part of comprehensive care."},{"id": 6832,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding physiotherapy involvement for infants following cardiac surgery, relevant to post-operative recovery?","options": [{"key": "A","text": "Aggressive full-intensity intervention should always be applied immediately regardless of the infant's post-surgical stability"},{"key": "B","text": "Physiotherapy involvement is identical regardless of the specific surgical procedure or the infant's individual recovery status"},{"key": "C","text": "May include appropriate positioning, respiratory support (as indicated), and early mobilization considerations tailored to the infant's post-surgical status"},{"key": "D","text": "Physiotherapy has no role whatsoever in post-cardiac surgery infant care"}],"correct": "C","explanation": "Physiotherapy involvement following pediatric cardiac surgery is individualized to the infant's specific post-surgical status, potentially including appropriate positioning, respiratory support as clinically indicated, and carefully graded early mobilization."},{"id": 6833,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding growth/nutritional status in infants with significant congenital heart disease, indirectly relevant to physiotherapy assessment?","options": [{"key": "A","text": "This consideration is entirely irrelevant to physiotherapy practice"},{"key": "B","text": "All infants with congenital heart disease show identical growth patterns regardless of defect severity"},{"key": "C","text": "Growth and nutrition have no relationship to congenital heart disease"},{"key": "D","text": "Increased energy expenditure related to cardiac workload can contribute to growth/nutritional challenges, relevant context for comprehensive developmental assessment"}],"correct": "D","explanation": "Increased cardiac workload/energy expenditure in significant congenital heart disease can contribute to growth and nutritional challenges, relevant context for comprehensive developmental assessment even though primary nutritional management involves other specialist input."},{"id": 6834,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding cardiac rehabilitation programs, increasingly relevant for some pediatric populations with congenital heart disease or following cardiac intervention?","options": [{"key": "A","text": "Exercise-based cardiac rehabilitation has no evidence of benefit for any pediatric population"},{"key": "B","text": "Cardiac rehabilitation programs should never involve any physiotherapy input"},{"key": "C","text": "Cardiac rehabilitation is exclusively relevant to adult populations, never applicable to pediatric patients"},{"key": "D","text": "Structured, individualized exercise programs can support improved fitness and quality of life in appropriately selected pediatric cardiac patients"}],"correct": "D","explanation": "Structured pediatric cardiac rehabilitation programs, incorporating individualized exercise prescription, are increasingly recognized as beneficial for supporting fitness and quality of life in appropriately selected children/adolescents with congenital heart disease."},{"id": 6835,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding monitoring vital signs (heart rate, oxygen saturation) during physiotherapy sessions for children with significant congenital heart disease?","options": [{"key": "A","text": "Monitoring should only ever be performed by nursing staff, with no role for physiotherapy in this process"},{"key": "B","text": "Appropriate monitoring supports safe exercise/activity progression, helping identify any concerning physiological response requiring session modification"},{"key": "C","text": "Vital sign monitoring is irrelevant during physiotherapy sessions for this population"},{"key": "D","text": "Assuming identical physiological response and safety parameters regardless of the specific cardiac defect or current status"}],"correct": "B","explanation": "Appropriate vital sign monitoring during physiotherapy sessions supports safe activity progression for children with significant congenital heart disease, helping identify any concerning physiological responses requiring session modification."},{"id": 6836,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding multidisciplinary team involvement in comprehensive management of children with complex congenital heart disease?","options": [{"key": "A","text": "A single specialist can independently manage all aspects of complex congenital heart disease care"},{"key": "B","text": "Physiotherapy should operate in complete isolation from the broader cardiac care team"},{"key": "C","text": "Coordination between cardiology, cardiac surgery, physiotherapy, and other relevant specialists supports comprehensive management addressing the condition's multisystem implications"},{"key": "D","text": "Multidisciplinary team involvement has no relevance to congenital heart disease management"}],"correct": "C","explanation": "Given the complex, multisystem implications of significant congenital heart disease, coordinated multidisciplinary team management (cardiology, surgery, physiotherapy, and others) supports comprehensive, well-integrated care."},{"id": 6837,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Kawasaki disease, a condition sometimes relevant to pediatric practice given its potential cardiac complications, is characterized by:","options": [{"key": "A","text": "An acute vasculitis with risk of coronary artery involvement/aneurysm formation if inadequately treated"},{"key": "B","text": "A condition affecting only the respiratory system with no cardiac relevance"},{"key": "C","text": "A condition identical to typical viral bronchiolitis"},{"key": "D","text": "A congenital (present from birth) cardiac defect"}],"correct": "A","explanation": "Kawasaki disease is an acute vasculitis (not congenital) with significant risk of coronary artery complications if not promptly and adequately treated, relevant context for understanding acquired pediatric cardiac risk beyond congenital defects."},{"id": 6838,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physical activity clearance/guidance for a child recovering from Kawasaki disease with documented coronary artery involvement?","options": [{"key": "A","text": "All children recovering from Kawasaki disease can safely return to unrestricted maximal activity immediately regardless of any coronary findings"},{"key": "B","text": "Assuming identical activity recommendations regardless of whether coronary artery involvement was present"},{"key": "C","text": "Activity guidance has no relevance to Kawasaki disease recovery management"},{"key": "D","text": "Requires individualized cardiology guidance regarding safe activity level given the specific coronary involvement, rather than generic recommendations"}],"correct": "D","explanation": "Given the potential for coronary artery involvement in Kawasaki disease, individualized cardiology-guided activity recommendations (rather than generic guidance) are important, considering the specific findings and risk profile for each child."},{"id": 6839,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'single ventricle' congenital heart defects (e.g., hypoplastic left heart syndrome), relevant to understanding the complexity of some cardiac conditions?","options": [{"key": "A","text": "A term describing the mildest, simplest category of congenital heart defect"},{"key": "B","text": "A condition identical in complexity and management to a simple VSD"},{"key": "C","text": "A condition requiring no specific ongoing monitoring or specialized management approach"},{"key": "D","text": "Represents a category of complex defects where only one functional ventricle is present, typically requiring staged surgical palliation and long-term specialized management"}],"correct": "D","explanation": "Single ventricle defects represent some of the most complex congenital heart conditions, typically requiring staged surgical palliation (e.g., Norwood, Glenn, Fontan procedures) and long-term specialized multidisciplinary management, relevant context for understanding the spectrum of congenital heart disease complexity."},{"id": 6840,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy assessment of exercise tolerance in children with congenital heart disease, relevant to appropriately individualized activity guidance?","options": [{"key": "A","text": "Exercise tolerance assessment has no relevance to physiotherapy practice for this population"},{"key": "B","text": "Assessment considering the child's specific cardiac status, any relevant limitations, and functional capacity supports appropriately individualized activity recommendations"},{"key": "C","text": "Assuming all children with congenital heart disease have identical exercise capacity regardless of defect type or repair status"},{"key": "D","text": "A single standardized exercise tolerance expectation applies identically to all children regardless of their specific cardiac condition"}],"correct": "B","explanation": "Individualized assessment of exercise tolerance, considering the child's specific cardiac status and any relevant limitations, supports appropriately tailored activity guidance rather than generic recommendations applied uniformly across this heterogeneous population."},{"id": 6841,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding family education for parents of children with congenital heart disease regarding activity/exercise participation?","options": [{"key": "A","text": "Families should always be told to completely restrict their child from any physical activity regardless of the specific cardiac status"},{"key": "B","text": "Physiotherapy has no role in family education regarding activity participation for this population"},{"key": "C","text": "Clear, appropriately individualized education helps families understand safe activity levels, supporting confident, appropriate participation rather than excessive restriction or risk"},{"key": "D","text": "Family education is unnecessary since all activity decisions should be made exclusively by medical staff without any family understanding required"}],"correct": "C","explanation": "Clear, individualized family education regarding safe activity participation helps support confident, appropriately balanced engagement (avoiding both excessive restriction and inappropriate risk), an important component of comprehensive family-centered care."},{"id": 6842,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding the potential impact of chronic hypoxemia (in cyanotic congenital heart disease) on exercise capacity/tolerance, relevant to physiotherapy assessment interpretation?","options": [{"key": "A","text": "Chronic hypoxemia has no relationship to exercise capacity or tolerance in any child"},{"key": "B","text": "This consideration is entirely irrelevant to physiotherapy assessment or intervention planning"},{"key": "C","text": "Exercise capacity is always identical between children with cyanotic and acyanotic defects"},{"key": "D","text": "Chronic reduced oxygenation can contribute to reduced exercise capacity, relevant context for appropriately interpreting assessment findings and setting realistic activity expectations"}],"correct": "D","explanation": "Chronic hypoxemia associated with some cyanotic congenital heart defects can contribute to reduced exercise capacity, relevant context for physiotherapists in appropriately interpreting assessment findings and setting realistic, individualized activity expectations and goals."},{"id": 6843,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "Which of the following describes an important consideration regarding developmental assessment timing/frequency for infants who have undergone complex early cardiac surgery?","options": [{"key": "A","text": "No developmental assessment is ever needed following successful cardiac surgery regardless of complexity"},{"key": "B","text": "Regular, structured developmental surveillance is often recommended given the increased developmental risk profile in this population"},{"key": "C","text": "Assuming a single assessment at any point provides completely sufficient information with no need for ongoing monitoring"},{"key": "D","text": "Developmental assessment timing has no relevance to this population's care planning"}],"correct": "B","explanation": "Given the increased developmental risk associated with complex early cardiac surgery, regular structured developmental surveillance (rather than a single isolated assessment) is often recommended to support timely identification of any concerns and appropriate early intervention."},{"id": 6844,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the potential relevance of genetic syndromes (e.g., some cases of Down syndrome) to congenital heart disease presentation?","options": [{"key": "A","text": "Genetic syndromes never show any association with congenital heart disease"},{"key": "B","text": "Assuming identical cardiac risk and presentation regardless of any associated genetic syndrome"},{"key": "C","text": "Certain genetic syndromes show increased association with specific congenital heart defects, relevant context for comprehensive assessment when both conditions co-occur"},{"key": "D","text": "This consideration has no relevance to physiotherapy practice"}],"correct": "C","explanation": "Certain genetic syndromes (e.g., Down syndrome, with its notably increased association with specific heart defects like AV septal defects) show recognized relationships with particular congenital heart disease patterns, relevant context when both conditions co-occur in comprehensive assessment planning."},{"id": 6845,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy contribution to respiratory management for infants with congenital heart disease who may have associated pulmonary complications (e.g., related to pulmonary overcirculation in certain defects)?","options": [{"key": "A","text": "Physiotherapy has no potential role in respiratory management for this population regardless of any pulmonary complications"},{"key": "B","text": "May include appropriate respiratory support techniques tailored to the infant's specific cardiopulmonary status, coordinated with the broader medical team"},{"key": "C","text": "Assuming identical respiratory management needs regardless of the specific cardiac defect or associated pulmonary status"},{"key": "D","text": "Respiratory considerations are entirely unrelated to congenital heart disease"}],"correct": "B","explanation": "For infants with congenital heart disease and associated pulmonary complications (e.g., related to certain defects causing pulmonary overcirculation), physiotherapy may contribute appropriate respiratory support techniques, carefully tailored and coordinated within the broader medical management approach."},{"id": 6846,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best summarizes the overall approach to physiotherapy involvement across the spectrum of pediatric congenital heart disease severity and presentation?","options": [{"key": "A","text": "A single standardized protocol should be applied identically regardless of the specific defect or individual presentation"},{"key": "B","text": "Assessment and intervention should ignore any condition-specific or individual patient considerations entirely"},{"key": "C","text": "Physiotherapy has no meaningful role across any presentation of congenital heart disease"},{"key": "D","text": "Individualized assessment and intervention planning considering the specific defect, treatment course, and current status, coordinated within a broader multidisciplinary cardiac care team"}],"correct": "D","explanation": "Given the heterogeneity of congenital heart disease presentations and treatment courses, individualized, condition-informed physiotherapy assessment and intervention planning, coordinated within the broader multidisciplinary cardiac care team, represents the appropriate overall approach."},{"id": 6847,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Gross Motor Function Measure (GMFM) is primarily used to assess:","options": [{"key": "A","text": "Fine motor function exclusively"},{"key": "B","text": "Change in gross motor function over time in children with cerebral palsy and similar conditions"},{"key": "C","text": "Cognitive function exclusively"},{"key": "D","text": "Speech and language development exclusively"}],"correct": "B","explanation": "GMFM (66 or 88 item versions) is a validated, widely used tool specifically designed to measure change in gross motor function over time, particularly in children with cerebral palsy."},{"id": 6848,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The GMFM assesses gross motor function across which dimensions?","options": [{"key": "A","text": "Only cognitive-motor integration"},{"key": "B","text": "Lying/rolling, sitting, crawling/kneeling, standing, and walking/running/jumping"},{"key": "C","text": "Only walking ability with no other movement dimensions assessed"},{"key": "D","text": "Only upper limb function"}],"correct": "B","explanation": "GMFM covers five dimensions spanning the developmental sequence from lying/rolling through to walking/running/jumping, providing a comprehensive gross motor assessment."},{"id": 6849,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The GMFM-66 differs from the GMFM-88 primarily in that it:","options": [{"key": "A","text": "Requires no standardized administration protocol"},{"key": "B","text": "Assesses entirely different developmental domains"},{"key": "C","text": "Is only appropriate for adult populations"},{"key": "D","text": "Uses Rasch analysis-based scoring with a reduced, interval-level item set"}],"correct": "D","explanation": "GMFM-66 uses Rasch analysis methodology with a refined 66-item subset, providing interval-level measurement properties advantageous for tracking change over time."},{"id": 6850,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Pediatric Evaluation of Disability Inventory (PEDI) assesses functional capabilities across which domains?","options": [{"key": "A","text": "Only gross motor function with no other domains"},{"key": "B","text": "Only speech/language function exclusively"},{"key": "C","text": "Self-care, mobility, and social function"},{"key": "D","text": "Only cognitive function exclusively"}],"correct": "C","explanation": "PEDI assesses functional performance across self-care, mobility, and social function domains, capturing both capability and caregiver assistance/modification needs."},{"id": 6851,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "The PEDI is designed for use with children within which general age range?","options": [{"key": "A","text": "Exclusively for adults, not children"},{"key": "B","text": "6 months to 7.5 years (with an extended/computer-adaptive version covering a broader range)"},{"key": "C","text": "Exclusively for adolescents 15-18 years"},{"key": "D","text": "Exclusively for infants under 3 months"}],"correct": "B","explanation": "The original PEDI is designed for children approximately 6 months to 7.5 years, with PEDI-CAT (computer adaptive test) extending applicability to a broader age range."},{"id": 6852,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "The Bayley Scales of Infant and Toddler Development assess which domains?","options": [{"key": "A","text": "Only gross motor function exclusively"},{"key": "B","text": "Cognitive, language, and motor development, along with social-emotional and adaptive behavior in newer editions"},{"key": "C","text": "Only speech articulation exclusively"},{"key": "D","text": "Only cognitive function exclusively with no other domains"}],"correct": "B","explanation": "Bayley Scales provide comprehensive developmental assessment across cognitive, language, and motor domains, with newer editions also including social-emotional and adaptive behavior components."},{"id": 6853,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Bayley Scales are primarily designed for use with which population?","options": [{"key": "A","text": "Exclusively adolescents"},{"key": "B","text": "Infants and young children (typically 1-42 months)"},{"key": "C","text": "Exclusively adults"},{"key": "D","text": "Exclusively school-age children over 10 years"}],"correct": "B","explanation": "Bayley Scales are specifically designed and normed for infants and young children, widely used for early developmental assessment including in NICU follow-up contexts."},{"id": 6854,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "The Denver Developmental Screening Test (Denver II/DDST) is primarily used as:","options": [{"key": "A","text": "A tool exclusively used in research with no clinical application"},{"key": "B","text": "A definitive diagnostic tool providing complete diagnostic certainty"},{"key": "C","text": "A tool exclusively for assessing gross motor function with no other domains"},{"key": "D","text": "A developmental screening tool to identify children who may need further diagnostic evaluation"}],"correct": "D","explanation": "Denver II is a screening tool (not a diagnostic instrument) designed to identify children who may warrant further, more comprehensive developmental evaluation."},{"id": 6855,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Medium","question": "The Denver II assesses development across which domains?","options": [{"key": "A","text": "Personal-social, fine motor-adaptive, language, and gross motor"},{"key": "B","text": "Only gross motor development"},{"key": "C","text": "Only language development exclusively"},{"key": "D","text": "Only cognitive development"}],"correct": "A","explanation": "Denver II screens across four domains: personal-social, fine motor-adaptive, language, and gross motor development."},{"id": 6856,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Hard","question": "The Alberta Infant Motor Scale (AIMS) is used to assess:","options": [{"key": "A","text": "Fine motor skills exclusively"},{"key": "B","text": "Only cognitive development in infants"},{"key": "C","text": "Only used for infants over 2 years of age"},{"key": "D","text": "Gross motor development in infants from birth to independent walking, based on observation of spontaneous movement"}],"correct": "D","explanation": "AIMS assesses spontaneous gross motor development/maturation in infants (birth to independent walking age), observing posture and movement across prone, supine, sitting, and standing positions."},{"id": 6857,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Easy","question": "The Peabody Developmental Motor Scales (PDMS) assess:","options": [{"key": "A","text": "Only social-emotional function exclusively"},{"key": "B","text": "Only cognitive function exclusively"},{"key": "C","text": "Only speech/language function exclusively"},{"key": "D","text": "Both gross and fine motor skills in young children"}],"correct": "D","explanation": "PDMS provides comprehensive assessment of both gross and fine motor skill development in young children, commonly used in pediatric physiotherapy/occupational therapy practice."},{"id": 6858,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The Test of Infant Motor Performance (TIMP) is designed to assess:","options": [{"key": "A","text": "Only speech-related motor function"},{"key": "B","text": "Only used for children over 5 years of age"},{"key": "C","text": "Postural and selective motor control in young infants, including premature infants"},{"key": "D","text": "Only cognitive function in infants"}],"correct": "C","explanation": "TIMP assesses postural control and selective movement in young infants (including premature infants from 34 weeks postmenstrual age), useful for early identification of motor concerns."},{"id": 6859,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The General Movements Assessment (GMA), used for early identification of neurological risk, evaluates:","options": [{"key": "A","text": "Only reflex responses to specific applied stimuli"},{"key": "B","text": "Only muscle strength using manual resistance testing"},{"key": "C","text": "Only cognitive function via structured testing tasks"},{"key": "D","text": "The quality of spontaneous infant movement patterns, particularly 'fidgety' movements around 3-5 months corrected age"}],"correct": "D","explanation": "GMA is a validated observational tool assessing spontaneous movement quality, with absent/abnormal fidgety movements being a strong early predictor of later neuromotor impairment including cerebral palsy."},{"id": 6860,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Manual Ability Classification System (MACS) is used to classify:","options": [{"key": "A","text": "Communication ability specifically"},{"key": "B","text": "Gross motor function specifically"},{"key": "C","text": "Cognitive function specifically"},{"key": "D","text": "How children with cerebral palsy use their hands to handle objects in daily activities"}],"correct": "D","explanation": "MACS (Levels I-V) specifically classifies bimanual hand function/object handling ability in daily activities for children with cerebral palsy."},{"id": 6861,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Hard","question": "The Gross Motor Function Classification System (GMFCS) classifies gross motor function severity in cerebral palsy into how many levels?","options": [{"key": "A","text": "Three levels"},{"key": "B","text": "Five levels (I-V)"},{"key": "C","text": "Two levels only"},{"key": "D","text": "Ten levels"}],"correct": "B","explanation": "GMFCS uses five levels to classify gross motor function severity, providing standardized communication regarding functional status in cerebral palsy."},{"id": 6862,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Communication Function Classification System (CFCS) is used to classify:","options": [{"key": "A","text": "Manual/hand function specifically"},{"key": "B","text": "A child's overall everyday communication performance with various communication partners"},{"key": "C","text": "Cognitive function specifically"},{"key": "D","text": "Gross motor function specifically"}],"correct": "B","explanation": "CFCS classifies the effectiveness of everyday communication performance, complementing GMFCS and MACS in comprehensive cerebral palsy classification."},{"id": 6863,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The Berg Balance Scale, though originally developed for adult populations, can also be relevant in pediatric physiotherapy practice for:","options": [{"key": "A","text": "Assessing functional balance in older children/adolescents capable of completing the required tasks"},{"key": "B","text": "Exclusively infants under 6 months of age"},{"key": "C","text": "No relevance whatsoever to any pediatric population"},{"key": "D","text": "Only used for assessing cognitive function"}],"correct": "A","explanation": "While originally developed for adults, the Berg Balance Scale can be relevant for assessing functional balance in older children/adolescents (particularly those with neurological conditions) capable of understanding and completing the required tasks."},{"id": 6864,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The Pediatric Balance Scale, a modified version specifically adapted for children, is used to assess:","options": [{"key": "A","text": "Only fine motor coordination"},{"key": "B","text": "Only speech/language function"},{"key": "C","text": "Functional balance ability in children, adapted from the adult Berg Balance Scale with pediatric-appropriate modifications"},{"key": "D","text": "Only cognitive function in children"}],"correct": "C","explanation": "Pediatric Balance Scale adapts the Berg Balance Scale framework specifically for children, providing age-appropriate functional balance assessment."},{"id": 6865,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "The Timed Up and Go (TUG) test, adapted for pediatric use, assesses:","options": [{"key": "A","text": "Only cognitive processing speed"},{"key": "B","text": "Only upper limb function"},{"key": "C","text": "Functional mobility, incorporating elements of transfers, walking, and turning"},{"key": "D","text": "Only static balance with no dynamic mobility component"}],"correct": "C","explanation": "Pediatric TUG assesses functional mobility (rising from a chair, walking, turning, returning to sit), similar in concept to the adult version but with pediatric-appropriate norms/considerations."},{"id": 6866,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "The Functional Independence Measure for Children (WeeFIM) assesses:","options": [{"key": "A","text": "Functional independence in self-care, mobility, and cognitive domains for children"},{"key": "B","text": "Only speech articulation exclusively"},{"key": "C","text": "Only used for adults, not children despite its pediatric-focused name"},{"key": "D","text": "Only gross motor function exclusively"}],"correct": "A","explanation": "WeeFIM is a pediatric adaptation of the adult FIM, assessing functional independence across self-care, mobility, and cognitive domains in children."},{"id": 6867,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "The Ages and Stages Questionnaire (ASQ) is primarily used as:","options": [{"key": "A","text": "A parent-completed developmental screening tool across multiple domains"},{"key": "B","text": "A tool exclusively completed by physiotherapists with no parent input"},{"key": "C","text": "A diagnostic tool providing definitive diagnosis rather than screening"},{"key": "D","text": "A tool exclusively for assessing gross motor function"}],"correct": "A","explanation": "ASQ is a widely used, parent-completed developmental screening questionnaire covering multiple domains (communication, gross motor, fine motor, problem-solving, personal-social), supporting accessible, family-involved screening."},{"id": 6868,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding selecting an appropriate outcome measure for a specific pediatric physiotherapy assessment purpose?","options": [{"key": "A","text": "Any available assessment tool can be used interchangeably regardless of its intended purpose or validated population"},{"key": "B","text": "Assessment tool selection has no relevance to obtaining clinically meaningful results"},{"key": "C","text": "Using the same single tool for every possible pediatric assessment purpose regardless of appropriateness"},{"key": "D","text": "Considering the specific purpose (screening vs. diagnostic vs. monitoring change), the child's age/condition, and the tool's established psychometric properties for that population"}],"correct": "D","explanation": "Appropriate outcome measure selection requires considering the specific assessment purpose, the child's age/condition relative to the tool's validated population, and its established psychometric properties (reliability, validity) for that context."},{"id": 6869,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the concept of 'floor effect' relevant to outcome measure selection/interpretation in pediatric physiotherapy?","options": [{"key": "A","text": "Only relevant to measures assessing cognitive function, never motor function"},{"key": "B","text": "Occurs when a measure is insufficiently sensitive to detect meaningful differences among children with more severe impairment, all scoring near the lowest possible score"},{"key": "C","text": "A term unrelated to any outcome measure consideration"},{"key": "D","text": "A term describing when all children achieve the maximum possible score"}],"correct": "B","explanation": "Floor effects occur when a measure cannot adequately differentiate among more severely impaired individuals (who all score near the bottom), limiting its sensitivity to detect meaningful change or difference in that population."},{"id": 6870,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the concept of 'ceiling effect' relevant to outcome measure selection/interpretation in pediatric physiotherapy?","options": [{"key": "A","text": "A term describing when all children score at the lowest possible level"},{"key": "B","text": "Only relevant to measures assessing motor function, never cognitive function"},{"key": "C","text": "Occurs when a measure is insufficiently sensitive to detect meaningful differences among higher-functioning children, many scoring at or near the maximum possible score"},{"key": "D","text": "A term unrelated to any outcome measure consideration"}],"correct": "C","explanation": "Ceiling effects occur when a measure cannot adequately differentiate among higher-functioning individuals (many scoring at/near the maximum), limiting sensitivity to detect further improvement or differences in that population."},{"id": 6871,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes the concept of 'minimal clinically important difference' (MCID) relevant to interpreting outcome measure score changes?","options": [{"key": "A","text": "A fixed universal value identical across all outcome measures and populations"},{"key": "B","text": "A term with no relevance to outcome measure interpretation"},{"key": "C","text": "Identical in meaning to statistical significance with no distinct clinical relevance"},{"key": "D","text": "The smallest change in score considered clinically meaningful to the patient/family, distinct from simple statistical significance"}],"correct": "D","explanation": "MCID represents the smallest score change considered clinically meaningful (rather than simply statistically significant), an important concept for meaningfully interpreting outcome measure changes over time in individual patients."},{"id": 6872,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding standardized versus non-standardized (informal) assessment approaches in pediatric physiotherapy practice?","options": [{"key": "A","text": "Only standardized tools should ever be used, with no role for informal clinical observation"},{"key": "B","text": "Standardized tools offer established reliability/validity and normative comparison, complementing informal clinical observation within comprehensive assessment"},{"key": "C","text": "Standardized and informal assessment approaches provide identical information with no distinguishing value"},{"key": "D","text": "Only informal, non-standardized observation should ever be used in pediatric physiotherapy assessment"}],"correct": "B","explanation": "Standardized assessment tools offer established psychometric properties and normative comparison data, appropriately complementing (rather than replacing) informal clinical observation within comprehensive pediatric physiotherapy assessment."},{"id": 6873,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding cultural/linguistic appropriateness of standardized pediatric assessment tools?","options": [{"key": "A","text": "Cultural/linguistic factors have no relevance to standardized assessment tool selection or interpretation"},{"key": "B","text": "Tools should ideally be validated/appropriate for the specific population being assessed, with awareness of potential limitations when applied outside their validated context"},{"key": "C","text": "Assuming identical norms apply universally regardless of any population-specific validation considerations"},{"key": "D","text": "All standardized tools are equally valid and appropriate regardless of the child's cultural/linguistic background"}],"correct": "B","explanation": "Awareness of cultural/linguistic appropriateness (or limitations) of standardized tools when applied to a specific child's background is important for appropriate assessment interpretation, recognizing that norms may not always generalize perfectly across all populations."},{"id": 6874,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the use of outcome measures for demonstrating physiotherapy intervention effectiveness/progress?","options": [{"key": "A","text": "Only subjective clinical impression should be used, with no role for any standardized measurement"},{"key": "B","text": "Using appropriate, validated measures at baseline and follow-up supports objective demonstration of change, complementing clinical judgment"},{"key": "C","text": "Outcome measures have no relevance to demonstrating intervention effectiveness"},{"key": "D","text": "Assuming a single baseline assessment provides sufficient information with no need for any follow-up measurement"}],"correct": "B","explanation": "Systematic use of appropriate, validated outcome measures at baseline and follow-up time points supports objective demonstration of intervention-related change, complementing clinical judgment within evidence-based practice."},{"id": 6875,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes the Hammersmith Infant Neurological Examination (HINE), relevant to pediatric neurological assessment?","options": [{"key": "A","text": "A standardized neurological examination tool for infants, useful for structured assessment and some predictive value regarding later motor outcome"},{"key": "B","text": "A tool exclusively assessing cognitive function with no neurological examination component"},{"key": "C","text": "A tool with no established reliability or validity"},{"key": "D","text": "A tool only appropriate for children over 5 years of age"}],"correct": "A","explanation": "HINE provides a standardized, structured approach to infant neurological examination, with established utility including some predictive value for later motor outcomes (e.g., cerebral palsy risk) when used in appropriate clinical contexts."},{"id": 6876,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the frequency of reassessment using standardized outcome measures in ongoing pediatric physiotherapy management?","options": [{"key": "A","text": "Appropriately timed reassessment (balancing meaningful interval for change against overburdening the child/family) supports monitoring progress and informing intervention adaptation"},{"key": "B","text": "A single baseline assessment is always sufficient with no need for any subsequent reassessment"},{"key": "C","text": "Reassessment frequency has no relevance to effective outcome measure utilization"},{"key": "D","text": "Reassessment should always occur at an identical fixed interval regardless of the specific condition, goals, or measure used"}],"correct": "A","explanation": "Reassessment timing should be thoughtfully individualized, balancing an appropriate interval for detecting meaningful change against the burden of frequent assessment, supporting effective progress monitoring and informed intervention adaptation."},{"id": 6877,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes the concept of 'responsiveness' as a psychometric property relevant to selecting outcome measures for tracking change over time?","options": [{"key": "A","text": "A term identical to simple test-retest reliability with no distinct meaning"},{"key": "B","text": "A term describing only how quickly a measure can be administered"},{"key": "C","text": "The measure's ability to detect clinically meaningful change when it has genuinely occurred"},{"key": "D","text": "A property irrelevant to selecting measures for tracking change over time"}],"correct": "C","explanation": "Responsiveness describes a measure's capacity to detect genuine, clinically meaningful change over time, a particularly important psychometric property when selecting tools intended to track progress/intervention effectiveness."},{"id": 6878,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding using the GMFM for a child already at GMFCS Level I with high-level gross motor skills?","options": [{"key": "A","text": "Potential ceiling effect limitations may reduce the GMFM's sensitivity to detect further improvement in this higher-functioning population, relevant to appropriate measure selection"},{"key": "B","text": "The GMFM is always equally sensitive and appropriate for children across the full range of GMFCS levels with no ceiling effect consideration"},{"key": "C","text": "GMFCS level has no relevance to GMFM measure selection or interpretation"},{"key": "D","text": "The GMFM should never be used for any child regardless of their GMFCS level"}],"correct": "A","explanation": "For higher-functioning children (e.g., GMFCS Level I) with more advanced gross motor skills, potential ceiling effects may limit the GMFM's sensitivity to detect further meaningful improvement, relevant consideration when selecting the most appropriate outcome measure for a specific child's assessment needs."},{"id": 6879,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding parent/caregiver-reported outcome measures (e.g., some PEDI components) compared to direct clinician observation-based measures?","options": [{"key": "A","text": "Provide valuable information regarding real-world functional performance in natural environments, complementing clinic-based observational assessment"},{"key": "B","text": "Parent-reported measures provide no valid or useful clinical information"},{"key": "C","text": "Only clinician-observed assessment should ever be considered valid, with no role for parent-report measures"},{"key": "D","text": "Parent-reported and clinician-observed measures always provide identical information with no distinguishing value"}],"correct": "A","explanation": "Parent/caregiver-reported outcome measures provide valuable insight into a child's real-world functional performance across natural environments and contexts, appropriately complementing clinic-based observational assessment within comprehensive evaluation."},{"id": 6880,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding administering standardized assessment tools to a child who is unwell, fatigued, or otherwise not in optimal testing condition?","options": [{"key": "A","text": "Assessment results are always equally valid regardless of the child's current physical/behavioral state during testing"},{"key": "B","text": "Assessment should always proceed exactly as scheduled regardless of any consideration of the child's current state"},{"key": "C","text": "Child state has no relevance to assessment validity or reliability"},{"key": "D","text": "Test conditions/child state should be considered and ideally optimized, as suboptimal state can affect assessment validity/reliability of results obtained"}],"correct": "D","explanation": "The child's behavioral/physical state during testing can significantly influence assessment results; considering and, where possible, optimizing testing conditions supports more valid and reliable outcome measure administration."},{"id": 6881,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding interpreting a single outcome measure score in isolation versus considering it within the broader clinical picture?","options": [{"key": "A","text": "A single score should be interpreted alongside other relevant clinical information (history, other assessment findings, functional context) rather than in complete isolation"},{"key": "B","text": "A single outcome measure score always provides complete, sufficient information requiring no further clinical context or correlation"},{"key": "C","text": "Clinical judgment has no role in interpreting standardized outcome measure results"},{"key": "D","text": "Outcome measure scores should never be discussed or interpreted within any broader clinical context"}],"correct": "A","explanation": "Appropriate clinical interpretation involves considering standardized outcome measure scores alongside other relevant clinical information (history, additional assessment findings, functional/environmental context) rather than relying on an isolated score alone."},{"id": 6882,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding training/competency requirements for administering certain standardized pediatric assessment tools (e.g., Bayley Scales)?","options": [{"key": "A","text": "Training requirements have no relevance to obtaining valid, reliable assessment results"},{"key": "B","text": "Some tools require specific training/certification to ensure valid, reliable administration and scoring, an important consideration for appropriate clinical use"},{"key": "C","text": "Any healthcare professional can administer any standardized tool without any specific training regardless of the tool's complexity"},{"key": "D","text": "No training or competency requirements exist for any standardized pediatric assessment tool"}],"correct": "B","explanation": "Certain standardized tools (particularly more complex developmental assessments like the Bayley Scales) require specific training/competency to ensure valid, reliable administration and scoring, an important consideration for clinicians using these instruments."},{"id": 6883,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following best summarizes the overall value of using validated, standardized outcome measures within comprehensive pediatric physiotherapy practice?","options": [{"key": "A","text": "Standardized outcome measures provide no additional value beyond informal clinical observation alone"},{"key": "B","text": "Outcome measures are only relevant for research purposes with no practical clinical application"},{"key": "C","text": "Only standardized measures should ever be used, completely eliminating any role for clinical judgment"},{"key": "D","text": "Support objective assessment, communication, progress tracking, and evidence-based practice, complementing (rather than replacing) clinical judgment and informal observation"}],"correct": "D","explanation": "Validated, standardized outcome measures support objective assessment, clear communication (within the team and with families), progress tracking, and evidence-based practice, functioning as a valuable complement to (rather than replacement for) clinical judgment and informal observation in comprehensive pediatric physiotherapy practice."},{"id": 6884,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The Canadian Occupational Performance Measure (COPM), sometimes used in pediatric rehabilitation goal-setting, is primarily designed to:","options": [{"key": "A","text": "Provide a purely clinician-determined assessment with no client/family input"},{"key": "B","text": "Only assess gross motor function with no client-identified goal component"},{"key": "C","text": "Identify and measure change in client/family-identified functional priorities"},{"key": "D","text": "Only relevant for adult populations with no pediatric application"}],"correct": "C","explanation": "COPM is a client/family-centered measure identifying and tracking change in self-identified functional performance priorities, supporting individualized, meaningful goal-setting in pediatric (and adult) rehabilitation practice."},{"id": 6885,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding using video recording as an adjunct to standardized assessment in pediatric physiotherapy practice?","options": [{"key": "A","text": "Can support detailed movement analysis, family education, and progress documentation, used appropriately with informed consent"},{"key": "B","text": "Video recording has no potential value or application in pediatric physiotherapy assessment"},{"key": "C","text": "Video recording requires no consideration of consent or privacy in pediatric practice"},{"key": "D","text": "Video recording should always replace standardized assessment tools entirely"}],"correct": "A","explanation": "Video recording, used appropriately with informed consent, can support detailed movement analysis, family education, and objective progress documentation, complementing standardized assessment approaches in pediatric physiotherapy practice."},{"id": 6886,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding using goal attainment scaling (GAS) as an individualized outcome measurement approach in pediatric physiotherapy?","options": [{"key": "A","text": "GAS can only be used in adult rehabilitation settings, never in pediatric practice"},{"key": "B","text": "Individualized goal measurement approaches have no relevance to pediatric physiotherapy practice"},{"key": "C","text": "GAS is identical to standardized norm-referenced assessment with no distinguishing features"},{"key": "D","text": "Allows measurement of progress toward individually defined, meaningful goals, complementing standardized norm-referenced outcome measures"}],"correct": "D","explanation": "Goal Attainment Scaling allows measurement of progress toward individually meaningful, specific goals set for each child, providing a valuable complement to standardized, norm-referenced outcome measures within comprehensive pediatric physiotherapy assessment."},{"id": 6887,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Easy","question": "Neurodevelopmental Treatment (NDT), historically developed for cerebral palsy management, traditionally emphasized:","options": [{"key": "A","text": "Complete avoidance of any therapist handling"},{"key": "B","text": "Only passive stretching with no active facilitation component"},{"key": "C","text": "Only isolated muscle strengthening exercises"},{"key": "D","text": "Facilitating more normal movement patterns and inhibiting abnormal tone/reflex patterns through specific handling techniques"}],"correct": "D","explanation": "Classic NDT theory emphasized facilitating normal movement and inhibiting abnormal patterns through specific handling, though the approach has evolved substantially with contemporary motor learning/neuroplasticity understanding."},{"id": 6888,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Contemporary NDT practice has evolved to increasingly incorporate:","options": [{"key": "A","text": "Principles of motor learning, active task-specific practice, and evidence-based intervention alongside traditional handling skills"},{"key": "B","text": "Abandonment of any theoretical framework"},{"key": "C","text": "Complete rejection of any handling techniques"},{"key": "D","text": "Exclusive focus on passive treatment with no active patient participation"}],"correct": "A","explanation": "Modern NDT practice has evolved considerably, integrating contemporary motor learning and neuroplasticity principles alongside traditional therapeutic handling skills."},{"id": 6889,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Sensory Integration (SI) therapy, developed by A. Jean Ayres, is based on the theoretical premise that:","options": [{"key": "A","text": "Only cognitive factors influence motor development with no sensory contribution"},{"key": "B","text": "Sensory processing has no relationship to motor or behavioral function"},{"key": "C","text": "Effective processing and organization of sensory information supports adaptive behavioral and motor responses"},{"key": "D","text": "Sensory integration concepts apply exclusively to adult populations"}],"correct": "C","explanation": "SI theory proposes that effective neural processing/organization of sensory input (tactile, vestibular, proprioceptive, and others) underlies adaptive motor and behavioral responses."},{"id": 6890,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the evidence base for classical clinic-based Sensory Integration therapy protocols?","options": [{"key": "A","text": "All claims associated with classical SI therapy protocols are definitively and uniformly supported by strong scientific evidence"},{"key": "B","text": "Evidence remains mixed/evolving for some specific claims, warranting critical appraisal alongside consideration of more broadly evidence-supported sensory-informed approaches"},{"key": "C","text": "Sensory integration concepts have no theoretical basis whatsoever"},{"key": "D","text": "No research has ever been conducted regarding sensory integration approaches"}],"correct": "B","explanation": "While sensory processing is a legitimate area of study, evidence for some specific classical SI therapy protocol claims remains mixed/evolving, warranting appropriately critical evidence appraisal by clinicians."},{"id": 6891,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Play-based intervention approaches in pediatric physiotherapy leverage which principle to support therapeutic engagement?","options": [{"key": "A","text": "Play has no relevance to achieving therapeutic goals"},{"key": "B","text": "Play-based approaches are only appropriate for the youngest infants, never older children"},{"key": "C","text": "Children's natural motivation and engagement with play to support achievement of therapeutic goals in a developmentally appropriate manner"},{"key": "D","text": "Only formal, structured exercise (never play) can achieve meaningful therapeutic outcomes"}],"correct": "C","explanation": "Play-based approaches leverage children's natural engagement and motivation, embedding therapeutic goals within meaningful, enjoyable play activities appropriate to the child's developmental level."},{"id": 6892,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding selecting play activities for therapeutic purposes in pediatric physiotherapy?","options": [{"key": "A","text": "Assuming identical play preferences and therapeutic value across all children regardless of individual interests"},{"key": "B","text": "Activities should be developmentally appropriate, motivating to the individual child, and structured to elicit the specific therapeutic goals targeted"},{"key": "C","text": "Any play activity is equally therapeutic regardless of the child's specific goals or developmental level"},{"key": "D","text": "Play activities should never be intentionally structured toward any specific therapeutic goal"}],"correct": "B","explanation": "Effective therapeutic play selection considers developmental appropriateness, individual child motivation/interest, and intentional structuring to elicit the specific movement patterns/skills being targeted."},{"id": 6893,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Constraint-Induced Movement Therapy (CIMT), adapted for pediatric hemiplegia, is grounded in which underlying concept?","options": [{"key": "A","text": "A concept unrelated to any behavioral or motor learning theory"},{"key": "B","text": "Complete restraint of both upper limbs simultaneously with no differential approach"},{"key": "C","text": "Addressing 'learned non-use' of the affected limb through structured, intensive practice while restraining the less-affected limb"},{"key": "D","text": "Passive treatment with no active practice requirement"}],"correct": "C","explanation": "CIMT specifically targets learned non-use through intensive, structured practice of the more-affected limb while constraining the less-affected limb, grounded in behavioral/motor learning theory."},{"id": 6894,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Hand-Arm Bimanual Intensive Therapy (HABIT), an alternative to CIMT for hemiplegic CP, emphasizes:","options": [{"key": "A","text": "Restraint-based unilateral practice identical to CIMT"},{"key": "B","text": "Exclusive focus on lower limb function"},{"key": "C","text": "Passive range of motion exclusively with no active practice component"},{"key": "D","text": "Intensive practice of bimanual (two-handed) coordinated functional tasks"}],"correct": "D","explanation": "HABIT focuses on intensive bimanual task practice, addressing the functional demand for coordinated two-handed activities, differing from CIMT's unilateral restraint-based approach."},{"id": 6895,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Task-oriented/task-specific training approaches in pediatric physiotherapy are grounded in the principle that:","options": [{"key": "A","text": "Complete avoidance of repetitive practice prevents any risk of overuse"},{"key": "B","text": "Passive modalities are the primary driver of pediatric motor development"},{"key": "C","text": "Isolated impairment-focused exercise is always superior to functional task practice"},{"key": "D","text": "Practicing meaningful, functional tasks promotes motor learning relevant to real-world function"}],"correct": "D","explanation": "Task-oriented approaches share the underlying principle that practicing meaningful, functional tasks (rather than isolated exercises alone) best promotes relevant motor learning applicable to real-world function."},{"id": 6896,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important principle of motor learning particularly relevant to pediatric physiotherapy intervention design?","options": [{"key": "A","text": "A single practice session is always sufficient for permanent skill acquisition in children"},{"key": "B","text": "Feedback should always be avoided during pediatric motor skill practice"},{"key": "C","text": "Motor learning principles are irrelevant to pediatric physiotherapy practice"},{"key": "D","text": "Sufficient practice repetition/intensity, appropriate feedback, and task specificity support effective skill acquisition"}],"correct": "D","explanation": "Motor learning principles (practice repetition/intensity, appropriate feedback, task specificity) inform evidence-based pediatric physiotherapy intervention design, similar to their relevance in adult neurorehabilitation."},{"id": 6897,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding family-centered practice as a foundational principle in pediatric physiotherapy?","options": [{"key": "A","text": "Family-centered practice is only relevant for infants, never for older children or adolescents"},{"key": "B","text": "Families should be excluded from all aspects of the therapeutic process to maintain clinical objectivity"},{"key": "C","text": "Actively involving families in assessment, goal-setting, and intervention planning, recognizing their central, ongoing role in the child's life and development"},{"key": "D","text": "Family involvement has no relevance to effective pediatric physiotherapy practice"}],"correct": "C","explanation": "Family-centered practice, actively involving families throughout the therapeutic process, is a foundational principle in pediatric physiotherapy, recognizing the family's central and ongoing role in the child's development and care."},{"id": 6898,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding goal-setting collaboratively with children (when developmentally appropriate) and families in pediatric physiotherapy?","options": [{"key": "A","text": "Goals should always be determined exclusively by the therapist without any child or family input"},{"key": "B","text": "Generic, standardized goals applied uniformly are always preferable to individualized goal-setting"},{"key": "C","text": "Child involvement in goal-setting is never developmentally appropriate at any age"},{"key": "D","text": "Involving the child and family in identifying meaningful, functional goals supports engagement and achievement of personally relevant outcomes"}],"correct": "D","explanation": "Collaborative goal-setting involving the child (as developmentally appropriate) and family supports meaningful engagement and achievement of personally relevant, functional outcomes, consistent with family/child-centered practice principles."},{"id": 6899,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes the concept of 'errorless learning' sometimes relevant to pediatric intervention for children with significant cognitive impairment?","options": [{"key": "A","text": "This approach is only relevant for adult neurorehabilitation, never applicable to pediatric intervention"},{"key": "B","text": "Errorless learning has no evidence base or relevance to pediatric practice"},{"key": "C","text": "Deliberately maximizing errors during practice is always the most effective approach for all children regardless of cognitive status"},{"key": "D","text": "Structuring practice to minimize errors during the learning process, as children with significant cognitive impairment may not benefit from typical trial-and-error learning with error correction"}],"correct": "D","explanation": "Errorless learning approaches, minimizing mistakes during the learning process, can be particularly beneficial for children with significant cognitive impairment who may not effectively learn from typical trial-and-error paradigms."},{"id": 6900,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding intervention approach adaptation for a child with significant sensory sensitivities during physiotherapy sessions?","options": [{"key": "A","text": "Assuming identical intervention approach is appropriate regardless of any individual sensory processing differences"},{"key": "B","text": "Thoughtful adaptation of the therapeutic environment, handling approach, and activity presentation supports more effective engagement given the child's individual sensory profile"},{"key": "C","text": "Sensory sensitivities have no relevance to physiotherapy intervention approach or environment"},{"key": "D","text": "Sensory considerations are solely an occupational therapy responsibility with no relevance to physiotherapy practice"}],"correct": "B","explanation": "Thoughtful adaptation of the therapeutic environment and approach, considering a child's individual sensory sensitivities, supports more effective therapeutic engagement across various pediatric conditions."},{"id": 6901,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the use of positive reinforcement/behavioral strategies within pediatric physiotherapy intervention?","options": [{"key": "A","text": "Positive reinforcement has no relevance to pediatric physiotherapy practice"},{"key": "B","text": "Behavioral strategies should never be incorporated into physiotherapy intervention approach"},{"key": "C","text": "Assuming identical reinforcement strategies are effective and appropriate for every child regardless of individual factors"},{"key": "D","text": "Appropriately applied positive reinforcement can support motivation and engagement with therapeutic tasks, particularly relevant for young children or those with additional behavioral considerations"}],"correct": "D","explanation": "Appropriately individualized use of positive reinforcement/behavioral strategies can effectively support motivation and engagement with therapeutic tasks, particularly relevant for young children or those with specific behavioral/motivational considerations."},{"id": 6902,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding intensity/dosage of pediatric physiotherapy intervention, relevant to evidence-based practice?","options": [{"key": "A","text": "Sufficient practice intensity/repetition is increasingly recognized as important for driving meaningful functional change, informing contemporary intervention intensity considerations"},{"key": "B","text": "Minimal practice repetition is always equally effective as higher-intensity practice regardless of the specific goal"},{"key": "C","text": "Intervention intensity considerations are irrelevant to evidence-based pediatric physiotherapy practice"},{"key": "D","text": "Practice intensity/dosage has no relationship to intervention outcomes in pediatric physiotherapy"}],"correct": "A","explanation": "Growing evidence supports the importance of adequate practice intensity/dosage in driving meaningful functional change, informing contemporary considerations regarding appropriate intervention intensity in pediatric physiotherapy planning."},{"id": 6903,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding transitioning intervention approach as a child develops/matures over time within ongoing pediatric physiotherapy management?","options": [{"key": "A","text": "Regular reassessment and appropriate adaptation of intervention approach supports addressing the child's evolving developmental stage, goals, and needs"},{"key": "B","text": "Intervention approach has no need for adaptation regardless of the child's changing age or developmental stage"},{"key": "C","text": "Assuming identical intervention needs and approach regardless of significant developmental changes over time"},{"key": "D","text": "A single fixed intervention approach should remain completely unchanged throughout the child's entire developmental course"}],"correct": "A","explanation": "Given children's ongoing development, regular reassessment and thoughtful adaptation of intervention approach supports appropriately addressing the child's evolving developmental stage, functional goals, and changing needs over time."},{"id": 6904,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding co-treatment or coordinated approaches between physiotherapy and other disciplines (e.g., occupational therapy, speech-language pathology) in comprehensive pediatric intervention?","options": [{"key": "A","text": "Coordinated care approaches have no evidence of additional benefit over isolated, uncoordinated individual discipline management"},{"key": "B","text": "Only one discipline is ever needed for comprehensive pediatric intervention, with no role for others"},{"key": "C","text": "Different disciplines should always work in complete isolation with no coordination or communication"},{"key": "D","text": "Coordinated, complementary input addressing overlapping developmental goals supports comprehensive, efficient intervention for children with complex needs"}],"correct": "D","explanation": "Coordinated, complementary input across relevant disciplines (physiotherapy, occupational therapy, speech-language pathology, and others as needed) supports more comprehensive, efficient intervention for children with complex developmental needs spanning multiple domains."},{"id": 6905,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding evidence-based practice application in pediatric physiotherapy, integrating research evidence with clinical expertise and family values?","options": [{"key": "A","text": "Clinical expertise alone, without any consideration of research evidence, represents adequate evidence-based practice"},{"key": "B","text": "Family/child values and preferences are irrelevant to evidence-based pediatric physiotherapy practice"},{"key": "C","text": "Effective evidence-based practice integrates best available research evidence, clinical expertise, and family/child values and preferences, rather than relying on any single source in isolation"},{"key": "D","text": "Evidence-based practice means rigidly applying research findings regardless of individual child/family factors or clinical judgment"}],"correct": "C","explanation": "True evidence-based pediatric physiotherapy practice integrates research evidence, clinical expertise, and family/child values/preferences, rather than relying exclusively on any single element, supporting individualized yet evidence-informed care."},{"id": 6906,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding technology-assisted intervention approaches (e.g., robotics, virtual reality, wearable sensors) increasingly used in some pediatric physiotherapy contexts?","options": [{"key": "A","text": "Should always completely replace conventional physiotherapy approaches regardless of the specific context or evidence"},{"key": "B","text": "Technology-assisted approaches have no potential role or evidence base in pediatric physiotherapy"},{"key": "C","text": "Can offer engaging, motivating, and consistent practice opportunities, generally complementing rather than replacing conventional therapeutic approaches"},{"key": "D","text": "Only appropriate for adolescents, never for younger children"}],"correct": "C","explanation": "Technology-assisted approaches can offer engaging, motivating practice opportunities and consistent intervention delivery, generally serving as a valuable complement to (rather than complete replacement for) conventional pediatric physiotherapy approaches."},{"id": 6907,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding home exercise program design for pediatric physiotherapy, supporting effective carryover beyond formal therapy sessions?","options": [{"key": "A","text": "Home program design has no relevance to overall intervention effectiveness"},{"key": "B","text": "Complex, extensive programs are always more effective than simple, focused programs regardless of family capacity"},{"key": "C","text": "Clear, achievable, appropriately explained programs (often incorporating play-based elements) support better family adherence and effective carryover"},{"key": "D","text": "Home exercise programs are never relevant or beneficial in pediatric physiotherapy practice"}],"correct": "C","explanation": "Well-designed home exercise programs—clear, achievable, and often incorporating engaging play-based elements—support better family adherence and more effective carryover of therapeutic gains beyond formal clinical sessions."},{"id": 6908,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding cultural sensitivity/awareness in pediatric physiotherapy practice, relevant to family-centered care?","options": [{"key": "A","text": "Cultural sensitivity is solely relevant to social work practice, with no application to physiotherapy"},{"key": "B","text": "Assuming identical approach and expectations are appropriate regardless of any cultural context or family background"},{"key": "C","text": "Awareness of and respect for cultural variations in family beliefs, practices, and expectations supports more effective, respectful, family-centered intervention"},{"key": "D","text": "Cultural considerations have no relevance to pediatric physiotherapy practice"}],"correct": "C","explanation": "Awareness of and appropriate sensitivity to cultural variations in family beliefs, practices, and expectations supports more effective, respectful, and genuinely family-centered pediatric physiotherapy practice."},{"id": 6909,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the concept of 'graded exposure' sometimes relevant to pediatric intervention for children with significant fear-avoidance or anxiety related to movement/activity?","options": [{"key": "A","text": "Gradual, systematically structured exposure to feared movements/activities, paired with appropriate support, can help build confidence and reduce avoidance over time"},{"key": "B","text": "Complete avoidance of any feared activity is always the most appropriate management approach"},{"key": "C","text": "Children should always be immediately exposed to maximally feared activities without any graded approach"},{"key": "D","text": "Graded exposure concepts have no relevance to pediatric physiotherapy practice"}],"correct": "A","explanation": "Graded, systematic exposure to feared movements/activities (rather than complete avoidance or overwhelming immediate exposure) can help build confidence and reduce movement-related fear-avoidance over time, relevant to certain pediatric presentations."},{"id": 6910,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding session length/structure adaptation based on a young child's attention span and fatigue tolerance?","options": [{"key": "A","text": "Assuming identical session structure and length is appropriate regardless of the child's age or individual attention/fatigue characteristics"},{"key": "B","text": "Session structure has no relevance to effective pediatric physiotherapy engagement"},{"key": "C","text": "Longer sessions are always more effective regardless of the child's attention span or fatigue level"},{"key": "D","text": "Adapting session length, activity variety, and pacing to the child's individual attention span and fatigue tolerance supports more effective engagement"}],"correct": "D","explanation": "Thoughtfully adapting session length, activity variety, and pacing to a child's individual attention span and fatigue tolerance (particularly relevant for younger children) supports more effective, sustained therapeutic engagement."},{"id": 6911,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding using siblings or peers within pediatric physiotherapy sessions, where appropriate and feasible?","options": [{"key": "A","text": "This consideration has no relevance to pediatric physiotherapy practice"},{"key": "B","text": "Peer involvement always guarantees improved outcomes regardless of the specific situation"},{"key": "C","text": "Can sometimes enhance motivation and provide modeling opportunities, though requiring thoughtful consideration of the specific therapeutic context and goals"},{"key": "D","text": "Sibling/peer involvement should never be considered in any pediatric physiotherapy context"}],"correct": "C","explanation": "In appropriate contexts, involving siblings or peers can sometimes enhance a child's motivation and provide valuable movement modeling opportunities, though this requires thoughtful consideration of the specific therapeutic goals and individual situation."},{"id": 6912,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding balancing structured, therapist-directed activities with child-led/self-directed exploration within a pediatric physiotherapy session?","options": [{"key": "A","text": "Sessions should always be entirely therapist-directed with absolutely no child-led exploration component"},{"key": "B","text": "Sessions should always be entirely child-led with no structured, therapist-directed component whatsoever"},{"key": "C","text": "Thoughtfully balancing both approaches, informed by the child's individual needs and specific session goals, can support effective engagement and skill development"},{"key": "D","text": "This balance consideration has no relevance to effective pediatric physiotherapy session planning"}],"correct": "C","explanation": "Thoughtfully balancing structured, therapist-directed activities with opportunities for child-led exploration, tailored to the individual child and specific session goals, can support effective engagement while still achieving targeted therapeutic objectives."},{"id": 6913,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following best summarizes the overall contemporary approach to selecting and integrating various pediatric physiotherapy treatment approaches (NDT, sensory-informed strategies, task-oriented training, and others) in clinical practice?","options": [{"key": "A","text": "Flexible, evidence-informed selection and integration of techniques based on the individual child's presentation and goals, rather than rigid adherence to a single named historical approach"},{"key": "B","text": "Strict, exclusive adherence to only one named historical approach regardless of the child's individual presentation or needs"},{"key": "C","text": "Assuming all children require an identical, fixed treatment protocol regardless of individual assessment findings"},{"key": "D","text": "Complete rejection of all traditionally-named approaches in favor of an entirely novel, untested method"}],"correct": "A","explanation": "Contemporary evidence-based pediatric physiotherapy practice typically involves flexible, individualized selection and integration of various techniques/principles based on the child's specific assessment findings and goals, rather than rigid adherence to any single historical named approach."},{"id": 6914,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the use of therapeutic equipment (e.g., therapy balls, swings, wedges) in pediatric physiotherapy sessions?","options": [{"key": "A","text": "Assuming identical equipment is appropriate for every child regardless of their individual presentation or goals"},{"key": "B","text": "Equipment should be selected purposefully to support specific therapeutic goals, appropriately graded to the child's current ability level"},{"key": "C","text": "Any available equipment can be used interchangeably regardless of the specific therapeutic goal"},{"key": "D","text": "Equipment use has no relevance to achieving pediatric physiotherapy goals"}],"correct": "B","explanation": "Purposeful equipment selection, appropriately graded to the child's current ability and aligned with specific therapeutic goals, supports effective, targeted pediatric physiotherapy intervention."},{"id": 6915,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding modeling/demonstration as a teaching strategy in pediatric physiotherapy intervention?","options": [{"key": "A","text": "Demonstrating a movement or task can support the child's understanding and motor learning, particularly useful alongside verbal instruction"},{"key": "B","text": "Verbal instruction alone is always sufficient with no benefit from demonstration"},{"key": "C","text": "Modeling should never be used as it might encourage imitation rather than independent problem-solving"},{"key": "D","text": "Modeling/demonstration has no relevance to pediatric motor learning"}],"correct": "A","explanation": "Demonstrating a target movement or task can effectively support a child's understanding and motor learning, particularly valuable when combined with appropriate verbal instruction and guided practice."},{"id": 6916,"subject": "Pediatrics","topic": "Developmental Milestones","difficulty": "Hard","question": "Which of the following describes an important consideration regarding the concept of 'scaffolding' in pediatric intervention, borrowed from educational/developmental psychology theory?","options": [{"key": "A","text": "A concept with no relevance to pediatric physiotherapy practice"},{"key": "B","text": "Removing all support immediately regardless of the child's current skill level"},{"key": "C","text": "Providing appropriate support/structure that is gradually reduced as the child's independent skill develops"},{"key": "D","text": "Providing maximal support indefinitely with no reduction over time regardless of the child's progress"}],"correct": "C","explanation": "Scaffolding involves providing appropriate initial support that is progressively and thoughtfully reduced as the child's independent skill and confidence develop, a concept relevant to graded pediatric physiotherapy intervention progression."},{"id": 6917,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding therapist positioning/handling technique when facilitating a movement for a young child, relevant to promoting active (rather than purely passive) participation?","options": [{"key": "A","text": "Assuming identical handling approaches are appropriate regardless of the child's active movement potential"},{"key": "B","text": "Handling technique has no relevance to whether a child actively participates in a movement task"},{"key": "C","text": "Always fully passively moving the child through every task regardless of their potential for active participation"},{"key": "D","text": "Using handling that facilitates and guides while still encouraging the child's own active motor effort, rather than fully passively moving the child through the task"}],"correct": "D","explanation": "Skilled therapeutic handling aims to facilitate and guide movement while still encouraging the child's own active motor effort and problem-solving, rather than simply passively moving the child through a task without their active engagement."},{"id": 6918,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding setting appropriately challenging (not too easy, not too difficult) tasks within pediatric physiotherapy sessions, relevant to motor learning and motivation?","options": [{"key": "A","text": "Tasks calibrated to an appropriate challenge level (sometimes described in relation to a 'zone of proximal development' concept) support effective learning and sustained motivation"},{"key": "B","text": "Tasks should always be set at the easiest possible level to avoid any frustration"},{"key": "C","text": "Task difficulty calibration has no relevance to motor learning or motivation in pediatric intervention"},{"key": "D","text": "Tasks should always be set at maximum difficulty regardless of the child's current ability level"}],"correct": "A","explanation": "Appropriately calibrated task difficulty—challenging enough to promote learning but achievable with effort/support—supports both effective motor learning and sustained child motivation, related to concepts like the 'zone of proximal development.'"},{"id": 6919,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding documentation of intervention approach and rationale in pediatric physiotherapy clinical records?","options": [{"key": "A","text": "Documentation of treatment approach/rationale has no relevance to pediatric physiotherapy practice"},{"key": "B","text": "Treatment rationale should never be documented, only the outcome"},{"key": "C","text": "Clear documentation of the chosen approach, rationale, and observed response supports continuity of care, communication, and reflective evidence-based practice"},{"key": "D","text": "Only vague, non-specific documentation should be used regardless of the approach implemented"}],"correct": "C","explanation": "Clear documentation of the chosen intervention approach, clinical rationale, and the child's observed response supports continuity of care, effective team communication, and ongoing reflective, evidence-based practice."},{"id": 6920,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding balancing evidence-based practice with individual child/family preference when multiple intervention approaches have comparable evidence support?","options": [{"key": "A","text": "Incorporating family/child preference alongside available evidence supports person-centered, engaged, and sustainable intervention planning"},{"key": "B","text": "Evidence-based practice means ignoring all individual preference regardless of the strength of available evidence for alternative approaches"},{"key": "C","text": "Assuming identical preferences and priorities across all families regardless of individual circumstances"},{"key": "D","text": "Family/child preference should never be considered when selecting among evidence-supported approaches"}],"correct": "A","explanation": "When multiple approaches have reasonably comparable evidence support, incorporating family/child preference into the shared decision-making process supports more person-centered, engaged, and ultimately sustainable intervention planning."},{"id": 6921,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best describes the overall goal of thoughtfully selecting and combining various pediatric physiotherapy treatment approaches for an individual child?","options": [{"key": "A","text": "Using as many different named approaches as possible simultaneously regardless of any coherent clinical rationale"},{"key": "B","text": "Supporting the child's meaningful functional progress and participation, informed by best available evidence, clinical expertise, and family-centered goals"},{"key": "C","text": "Strictly adhering to a single named approach regardless of the child's actual response or progress"},{"key": "D","text": "Treatment approach selection has no bearing on the child's ultimate functional outcomes"}],"correct": "B","explanation": "The overarching goal of thoughtful, individualized treatment approach selection and integration is to support the child's meaningful functional progress and participation, guided by best available evidence, sound clinical reasoning, and family-centered goal-setting."},{"id": 6922,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Standard pediatric growth charts typically plot which measurements against age?","options": [{"key": "A","text": "Only cognitive test scores"},{"key": "B","text": "Weight, length/height, and head circumference (in younger children)"},{"key": "C","text": "Only weight with no other parameters"},{"key": "D","text": "Only motor milestone achievement"}],"correct": "B","explanation": "Standard growth charts track weight, length/height, and (in infants/young children) head circumference against age, using percentile curves for comparison to reference populations."},{"id": 6923,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Failure to thrive (FTT) in pediatrics generally refers to:","options": [{"key": "A","text": "A condition only relevant in adolescence, never in infancy"},{"key": "B","text": "A term unrelated to any growth parameter"},{"key": "C","text": "Inadequate physical growth compared to expected norms, often reflected in declining growth percentiles"},{"key": "D","text": "A term exclusively describing cognitive delay with no growth component"}],"correct": "C","explanation": "FTT describes inadequate growth (typically weight, sometimes also length/height) compared to expected norms, often identified through declining growth chart percentiles over time."},{"id": 6924,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding indirect relevance of nutritional/growth status to pediatric physiotherapy assessment?","options": [{"key": "A","text": "Poor growth/nutritional status can affect energy levels, muscle mass, and overall capacity for participation in physical activity/therapy"},{"key": "B","text": "Nutritional status has no relevance to physiotherapy assessment or intervention planning"},{"key": "C","text": "Physiotherapists should never consider growth parameters as part of comprehensive assessment"},{"key": "D","text": "Assuming identical physical capacity and therapy tolerance regardless of a child's nutritional/growth status"}],"correct": "A","explanation": "Nutritional and growth status can indirectly affect a child's energy levels, muscle mass, and overall capacity for participation, relevant context for comprehensive physiotherapy assessment even though primary nutritional management involves other specialists."},{"id": 6925,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Medium","question": "Which of the following describes an important consideration regarding growth monitoring for children with significant motor impairment (e.g., severe cerebral palsy) who may have feeding difficulties?","options": [{"key": "A","text": "All children with motor impairment show identical growth patterns regardless of any feeding-related challenges"},{"key": "B","text": "Regular growth monitoring is important given increased risk of nutritional/growth challenges related to feeding difficulties in this population"},{"key": "C","text": "Growth considerations have no relationship to motor impairment severity"},{"key": "D","text": "Growth monitoring is irrelevant for children with motor impairment"}],"correct": "B","explanation": "Children with significant motor impairment affecting feeding ability show increased risk of growth/nutritional challenges, making regular monitoring an important component of comprehensive multidisciplinary care."},{"id": 6926,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding using condition-specific growth charts (where available) for children with certain genetic syndromes affecting typical growth patterns?","options": [{"key": "A","text": "Condition-specific growth charts have no clinical utility or relevance"},{"key": "B","text": "Condition-specific charts provide more clinically meaningful comparison than standard population charts for conditions with characteristically atypical growth patterns"},{"key": "C","text": "Growth chart selection has no bearing on appropriate clinical interpretation"},{"key": "D","text": "Standard population growth charts are always equally appropriate regardless of any underlying genetic condition affecting growth"}],"correct": "B","explanation": "For certain genetic conditions with well-characterized, distinct growth patterns (e.g., Down syndrome, Turner syndrome), condition-specific growth charts provide more clinically meaningful comparison than standard population-based charts alone."},{"id": 6927,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important multidisciplinary consideration when a physiotherapist identifies possible growth/nutritional concerns during a pediatric assessment?","options": [{"key": "A","text": "Physiotherapists should independently manage all nutritional concerns without any referral to other specialists"},{"key": "B","text": "Growth/nutritional concerns identified during physiotherapy assessment should always be ignored"},{"key": "C","text": "Assuming physiotherapy assessment alone provides sufficient information to fully address any nutritional concern"},{"key": "D","text": "Appropriate referral/communication with relevant team members (medical, dietetics) supports comprehensive evaluation and management of the identified concern"}],"correct": "D","explanation": "When growth/nutritional concerns are identified during physiotherapy assessment, appropriate referral/communication with relevant specialists (medical, dietetics) supports comprehensive, coordinated evaluation and management."},{"id": 6928,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Medium","question": "Which of the following describes an important consideration regarding energy expenditure differences in children with certain movement disorders (e.g., dyskinetic cerebral palsy with significant involuntary movement), relevant to growth/nutritional needs?","options": [{"key": "A","text": "Energy expenditure is always identical regardless of the specific movement disorder or pattern present"},{"key": "B","text": "Assuming identical nutritional needs regardless of the child's specific movement pattern or associated energy expenditure"},{"key": "C","text": "Increased energy expenditure related to excessive involuntary movement can contribute to elevated caloric needs, relevant context for comprehensive nutritional planning"},{"key": "D","text": "This consideration has no relevance to physiotherapy practice or broader care planning"}],"correct": "C","explanation": "Some movement disorders (e.g., dyskinetic CP with significant involuntary movement) can be associated with increased energy expenditure, relevant context for comprehensive nutritional planning involving appropriate specialist input."},{"id": 6929,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Medium","question": "Which of the following describes an important consideration regarding oral-motor/feeding skill assessment relevance to overall growth outcomes in young children with neurological conditions?","options": [{"key": "A","text": "Oral-motor function has no relationship to growth outcomes"},{"key": "B","text": "Assuming identical growth outcomes regardless of any oral-motor/feeding skill differences"},{"key": "C","text": "Feeding assessment is solely relevant to speech-language pathology with no broader growth-related implications"},{"key": "D","text": "Oral-motor/feeding difficulties can directly impact adequate nutritional intake and subsequent growth, relevant to comprehensive multidisciplinary assessment"}],"correct": "D","explanation": "Oral-motor/feeding difficulties, common in various pediatric neurological conditions, can directly impact adequate nutritional intake and consequently growth outcomes, highlighting the interconnection between these assessment domains within comprehensive multidisciplinary care."},{"id": 6930,"subject": "Pediatrics","topic": "Cerebral Palsy","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the relevance of adequate nutrition to bone health in children with reduced weight-bearing/mobility (e.g., significant cerebral palsy)?","options": [{"key": "A","text": "Assuming identical bone health regardless of any nutritional or mobility-related factors"},{"key": "B","text": "Only weight-bearing intervention matters for bone health, with nutrition being entirely irrelevant"},{"key": "C","text": "Adequate nutrition (including calcium/vitamin D) alongside appropriate weight-bearing interventions supports bone health in this at-risk population"},{"key": "D","text": "Nutrition has no relevance to bone health regardless of a child's mobility status"}],"correct": "C","explanation": "Adequate nutrition (including calcium/vitamin D) combined with appropriate weight-bearing interventions (e.g., standing programs) supports bone health in children with reduced mobility who are at increased osteoporosis/fracture risk."},{"id": 6931,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding growth monitoring in premature infants, relevant to using corrected age?","options": [{"key": "A","text": "Premature infant growth should always be plotted using chronological age with no correction applied"},{"key": "B","text": "Growth monitoring is irrelevant for premature infants"},{"key": "C","text": "Corrected age adjustment has no relevance to growth chart interpretation"},{"key": "D","text": "Growth parameters for premature infants are typically plotted using corrected age (at least through early childhood) for appropriate interpretation relative to expected norms"}],"correct": "D","explanation": "Similar to developmental milestone assessment, growth parameters for premature infants are typically plotted using corrected age (at least through early childhood) to support appropriate interpretation relative to expected growth trajectories."},{"id": 6932,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding obesity risk monitoring in certain pediatric populations (e.g., some children with Down syndrome, Prader-Willi syndrome, or reduced mobility from various causes)?","options": [{"key": "A","text": "Obesity risk is identical across all pediatric populations regardless of any underlying condition"},{"key": "B","text": "Increased obesity risk in certain populations warrants attention to appropriate physical activity promotion and monitoring as part of comprehensive health management"},{"key": "C","text": "Obesity-related considerations have no relevance to physiotherapy practice"},{"key": "D","text": "Physical activity promotion is never appropriate for children with any underlying health condition"}],"correct": "B","explanation": "Certain pediatric populations (some genetic syndromes, conditions causing reduced mobility) show increased obesity risk, relevant to comprehensive health management including appropriate physiotherapy-supported physical activity promotion."},{"id": 6933,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding hydration status relevance to a child's physical performance/tolerance during physiotherapy sessions, particularly in hot climates or with certain conditions?","options": [{"key": "A","text": "Assuming identical hydration needs and considerations regardless of environmental conditions or individual health factors"},{"key": "B","text": "Physiotherapists should never consider hydration status as part of session planning"},{"key": "C","text": "Hydration status has no relevance to physical performance or exercise tolerance in children"},{"key": "D","text": "Adequate hydration supports physical performance and safety during activity/exercise, relevant consideration particularly in warmer conditions or for children with specific relevant health considerations"}],"correct": "D","explanation": "Adequate hydration supports safe physical performance and exercise tolerance, a relevant consideration particularly in warmer environmental conditions or for children with specific health factors affecting fluid balance/thermoregulation."},{"id": 6934,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the potential impact of chronic illness-related fatigue on a child's engagement with mealtime and adequate nutritional intake, indirectly relevant to comprehensive care?","options": [{"key": "A","text": "Chronic illness-related fatigue can sometimes indirectly affect feeding engagement/intake, relevant context for comprehensive, coordinated multidisciplinary understanding of a child's overall status"},{"key": "B","text": "This consideration is entirely unrelated to comprehensive pediatric care planning"},{"key": "C","text": "Assuming identical feeding engagement and nutritional status regardless of any underlying fatigue-related factors"},{"key": "D","text": "Fatigue has no relationship to feeding engagement or nutritional intake in any child"}],"correct": "A","explanation": "Recognizing that chronic illness-related fatigue can sometimes indirectly affect a child's feeding engagement and nutritional intake supports comprehensive, coordinated multidisciplinary understanding of interconnected factors affecting overall status."},{"id": 6935,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding growth chart interpretation for children with significant scoliosis potentially affecting accurate height/length measurement?","options": [{"key": "A","text": "Assuming identical measurement accuracy regardless of significant musculoskeletal deformity affecting standard measurement techniques"},{"key": "B","text": "Alternative measurement approaches (e.g., arm span, segmental measurements) may be considered when standard height/length measurement is complicated by significant spinal curvature"},{"key": "C","text": "Growth monitoring becomes entirely irrelevant once any scoliosis is present"},{"key": "D","text": "Standard height measurement is always equally accurate regardless of any spinal curvature present"}],"correct": "B","explanation": "For children with significant scoliosis potentially complicating standard height/length measurement accuracy, alternative approaches (arm span, segmental measurements) may be considered to support more meaningful growth monitoring."},{"id": 6936,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best summarizes the overall relevance of growth/nutritional considerations to comprehensive pediatric physiotherapy practice, despite these not being the primary physiotherapy management domain?","options": [{"key": "A","text": "Growth and nutritional considerations have absolutely no relevance to physiotherapy practice under any circumstances"},{"key": "B","text": "Awareness of growth/nutritional status provides important context for overall assessment and supports appropriate multidisciplinary referral/communication when concerns are identified"},{"key": "C","text": "Physiotherapists should independently manage all growth and nutritional concerns without involving other specialists"},{"key": "D","text": "These considerations are only relevant for physiotherapists working in dedicated nutrition-focused clinical settings"}],"correct": "B","explanation": "While not the primary physiotherapy management domain, awareness of growth/nutritional status provides valuable context for comprehensive assessment and supports appropriate identification and communication/referral regarding any concerns within the broader multidisciplinary care team."},{"id": 6937,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Burn severity classification includes superficial, partial-thickness, and full-thickness categories; full-thickness burns are characterized by:","options": [{"key": "A","text": "Damage extending through the entire dermis, often appearing white/leathery and typically insensate"},{"key": "B","text": "Damage limited only to the epidermis with intact sensation"},{"key": "C","text": "The mildest burn category requiring minimal intervention"},{"key": "D","text": "A category identical to superficial burns with no distinguishing features"}],"correct": "A","explanation": "Full-thickness burns extend through the entire dermis, often appearing white or leathery, with characteristic reduced/absent sensation due to nerve ending destruction, generally requiring surgical management (grafting)."},{"id": 6938,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important physiotherapy consideration during the acute phase of significant pediatric burn management?","options": [{"key": "A","text": "Aggressive stretching regardless of pain or wound status is always appropriate during the acute phase"},{"key": "B","text": "Physiotherapy has no role during the acute phase of burn management"},{"key": "C","text": "Positioning to prevent contracture, appropriate range of motion exercises, and edema management, balanced with wound healing considerations"},{"key": "D","text": "Complete immobilization is always the appropriate approach throughout the entire acute burn management phase"}],"correct": "C","explanation": "Acute burn physiotherapy management balances contracture prevention (positioning, appropriate ROM), edema management, and consideration of wound healing status, requiring careful, individualized clinical judgment."},{"id": 6939,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding scar management following significant pediatric burn injury, relevant to ongoing physiotherapy involvement?","options": [{"key": "A","text": "Scar management has no relevance to physiotherapy practice following burn injury"},{"key": "B","text": "Scarring never occurs following pediatric burns requiring no specific management consideration"},{"key": "C","text": "Physiotherapy involvement ends immediately once the wound has achieved initial closure with no ongoing role"},{"key": "D","text": "May include techniques such as pressure garment therapy, scar massage, and stretching to help manage hypertrophic scarring and maintain function"}],"correct": "D","explanation": "Ongoing physiotherapy involvement in scar management (pressure garments, scar massage, stretching) is important for managing hypertrophic scarring risk and maintaining functional range of motion following significant burn injury."},{"id": 6940,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding growth-related complications sometimes seen following significant burns crossing joint areas in growing children?","options": [{"key": "A","text": "Scar tissue can restrict growth and cause progressive contracture/deformity as the child grows, requiring ongoing monitoring"},{"key": "B","text": "Growth is never affected by burn scarring regardless of location or severity"},{"key": "C","text": "Assuming identical outcomes regardless of burn location relative to joints or growth plates"},{"key": "D","text": "This consideration has no relevance to long-term pediatric burn management"}],"correct": "A","explanation": "Non-elastic scar tissue crossing joint areas can restrict normal growth and increasingly cause functional contracture/deformity as the child continues to grow, necessitating long-term monitoring and management."},{"id": 6941,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding psychological support relevance for children who have experienced significant burn injury, alongside physical rehabilitation?","options": [{"key": "A","text": "Physical rehabilitation alone is always sufficient with no need for any psychological consideration"},{"key": "B","text": "Significant burn injury can have substantial psychological impact, making integrated psychological support an important component of comprehensive care"},{"key": "C","text": "Assuming identical psychological impact and needs regardless of burn severity or individual child factors"},{"key": "D","text": "Psychological factors have no relevance to comprehensive pediatric burn management"}],"correct": "B","explanation": "Given the potentially significant psychological impact of burn injury (pain, appearance changes, trauma), integrated psychological support alongside physical rehabilitation is an important component of comprehensive pediatric burn care."},{"id": 6942,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Torticollis in older children (beyond the congenital muscular torticollis typically presenting in infancy) can sometimes result from which acquired cause requiring appropriate differential consideration?","options": [{"key": "A","text": "A condition that never has any acquired presentation beyond infancy"},{"key": "B","text": "A condition entirely unrelated to any cervical spine consideration"},{"key": "C","text": "Acute atlantoaxial rotatory subluxation, sometimes following minor trauma or upper respiratory infection"},{"key": "D","text": "Only congenital causes exist for torticollis at any age"}],"correct": "C","explanation": "Acquired torticollis in older children can result from various causes including atlantoaxial rotatory subluxation, sometimes following minor trauma or infection, requiring appropriate differential diagnosis distinct from congenital muscular torticollis."},{"id": 6943,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding non-accidental injury (child abuse) awareness relevant to pediatric physiotherapy practice, given physiotherapists' regular contact with children?","options": [{"key": "A","text": "Awareness of potential indicators and appropriate safeguarding reporting pathways is an important professional responsibility"},{"key": "B","text": "Non-accidental injury awareness has no relevance to physiotherapy practice"},{"key": "C","text": "Physiotherapists have no professional responsibility regarding child safeguarding concerns"},{"key": "D","text": "Assuming all injuries presented for physiotherapy assessment always have a straightforward accidental explanation with no need for any clinical vigilance"}],"correct": "A","explanation": "Given their regular contact with children, physiotherapists have an important professional responsibility to maintain awareness of potential non-accidental injury indicators and appropriate safeguarding reporting pathways as part of comprehensive, safe pediatric practice."},{"id": 6944,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding pediatric obesity as a broader health concern sometimes relevant to physiotherapy practice, beyond any specific underlying condition?","options": [{"key": "A","text": "Physiotherapy has no potential role in supporting healthy physical activity for children with obesity"},{"key": "B","text": "Increasing prevalence with associated musculoskeletal and broader health implications, relevant to physiotherapy's potential contribution to physical activity promotion"},{"key": "C","text": "Assuming identical musculoskeletal presentation and needs regardless of any weight-related considerations"},{"key": "D","text": "Pediatric obesity has no relevance to physiotherapy practice under any circumstances"}],"correct": "B","explanation": "Pediatric obesity, an increasingly prevalent health concern, carries various musculoskeletal (e.g., increased lower limb loading) and broader health implications, relevant to physiotherapy's potential contribution within comprehensive management including physical activity promotion."},{"id": 6945,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy involvement for children with chronic pain conditions (e.g., some cases of complex regional pain syndrome, chronic musculoskeletal pain) in the pediatric population?","options": [{"key": "A","text": "Assuming identical management approaches to adult chronic pain with no pediatric-specific adaptation needed"},{"key": "B","text": "Chronic pain never occurs in the pediatric population"},{"key": "C","text": "May involve graded activity/exposure approaches and broader biopsychosocial management considerations, similar in principle to adult chronic pain management adapted appropriately"},{"key": "D","text": "Physiotherapy has no role in managing pediatric chronic pain conditions"}],"correct": "C","explanation": "Pediatric chronic pain management, while requiring developmentally appropriate adaptation, often incorporates similar biopsychosocial principles to adult chronic pain approaches, potentially including graded activity/exposure strategies within comprehensive management."},{"id": 6946,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding hypermobility spectrum disorders (beyond specific syndromes like Ehlers-Danlos) sometimes seen in children presenting with joint pain/instability concerns?","options": [{"key": "A","text": "Generalized joint hypermobility, whether syndromic or non-syndromic, can contribute to musculoskeletal symptoms requiring appropriate stability-focused physiotherapy management"},{"key": "B","text": "Assuming identical management approach regardless of whether hypermobility is present"},{"key": "C","text": "Hypermobility-related presentations require no specific physiotherapy consideration or approach adaptation"},{"key": "D","text": "Joint hypermobility never has any clinical relevance or symptom association in children"}],"correct": "A","explanation": "Generalized joint hypermobility (whether part of a specific syndrome or occurring more generally) can contribute to musculoskeletal symptoms in children, often benefiting from stability-focused physiotherapy management approaches."},{"id": 6947,"subject": "Pediatrics","topic": "Assessment Tools","difficulty": "Easy","question": "Which of the following describes an important consideration regarding physiotherapy assessment for a child presenting with unexplained, recurrent limb pain without clear injury history?","options": [{"key": "A","text": "This presentation never requires any careful clinical assessment or consideration of differential diagnosis"},{"key": "B","text": "Assuming identical underlying cause for every child presenting with unexplained recurrent limb pain"},{"key": "C","text": "Automatically assuming all such presentations represent simple 'growing pains' with no further assessment needed"},{"key": "D","text": "Requires careful, comprehensive assessment considering the broad differential diagnosis (including growing pains, but also more serious considerations requiring exclusion) rather than automatic assumption of a single benign cause"}],"correct": "D","explanation": "Unexplained recurrent limb pain in children requires careful, comprehensive assessment considering the appropriately broad differential diagnosis, avoiding automatic assumption of a single benign explanation (like growing pains) without adequate clinical consideration."},{"id": 6948,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "'Growing pains,' a common benign cause of recurrent limb pain in children, are typically characterized by:","options": [{"key": "A","text": "Pain that is constant throughout the day with no positional/timing pattern"},{"key": "B","text": "Bilateral lower limb pain, often occurring in the evening/night, with no associated swelling, redness, or limitation of function between episodes"},{"key": "C","text": "A condition always requiring extensive investigation and specialist referral"},{"key": "D","text": "Unilateral pain with associated joint swelling and warmth"}],"correct": "B","explanation": "Growing pains classically present with bilateral, often evening/nighttime lower limb pain, without associated objective findings (swelling, warmth, limitation) between episodes, representing a benign, self-limiting condition distinct from pathological causes requiring further investigation."},{"id": 6949,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding red flag features that would distinguish concerning limb pain presentations from benign 'growing pains' in children?","options": [{"key": "A","text": "Unilateral pain, associated swelling/warmth, systemic symptoms (fever, weight loss), or functional limitation between episodes warrant further evaluation"},{"key": "B","text": "Red flag consideration has no relevance to pediatric limb pain assessment"},{"key": "C","text": "All limb pain presentations in children should be assumed benign regardless of any associated features"},{"key": "D","text": "No red flag features exist that would distinguish concerning presentations from typical growing pains"}],"correct": "A","explanation": "Features such as unilateral presentation, associated swelling/warmth, systemic symptoms, or persistent functional limitation are red flags distinguishing potentially concerning presentations from typical benign growing pains, warranting further medical evaluation."},{"id": 6950,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding the potential relevance of vitamin D deficiency to pediatric musculoskeletal presentations, relevant to comprehensive differential diagnosis consideration?","options": [{"key": "A","text": "Vitamin D deficiency has no relevance to any pediatric musculoskeletal presentation"},{"key": "B","text": "Assuming identical musculoskeletal presentation regardless of any nutritional/vitamin status considerations"},{"key": "C","text": "Can contribute to conditions like rickets, presenting with bone pain, deformity, or muscle weakness, relevant to appropriate differential diagnosis consideration in relevant presentations"},{"key": "D","text": "This consideration is entirely irrelevant to physiotherapy assessment"}],"correct": "C","explanation": "Vitamin D deficiency can contribute to conditions like rickets (bone deformity, pain) or contribute to muscle weakness, relevant context for comprehensive differential diagnosis consideration in certain pediatric musculoskeletal presentations, particularly with appropriate risk factor history."},{"id": 6951,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best summarizes the overall importance of maintaining broad clinical awareness/vigilance across diverse presentations within comprehensive pediatric physiotherapy practice?","options": [{"key": "A","text": "Supports appropriate assessment, differential diagnosis consideration, and timely referral when needed, given the wide range of conditions that can present within pediatric physiotherapy practice"},{"key": "B","text": "Assuming every pediatric presentation has an identical, predictable underlying cause requiring no differential consideration"},{"key": "C","text": "Broad clinical awareness has no relevance to safe, effective pediatric physiotherapy practice"},{"key": "D","text": "Physiotherapists only need awareness of a single narrow category of pediatric conditions with no broader clinical vigilance required"}],"correct": "A","explanation": "Given the wide diversity of conditions that can present within pediatric physiotherapy practice, maintaining broad clinical awareness and appropriate diagnostic vigilance supports safe, effective assessment, differential diagnosis consideration, and timely referral when clinically indicated."},{"id": 6952,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Spinal Muscular Atrophy (SMA) results from mutations affecting which gene?","options": [{"key": "A","text": "CFTR"},{"key": "B","text": "Dystrophin"},{"key": "C","text": "SMN1 (Survival Motor Neuron 1)"},{"key": "D","text": "FGFR3"}],"correct": "C","explanation": "SMA results from SMN1 gene mutations/deletions, causing insufficient functional SMN protein, leading to progressive anterior horn cell degeneration."},{"id": 6953,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "The SMN2 gene, a near-identical copy of SMN1, is clinically relevant in SMA because:","options": [{"key": "A","text": "It is the primary gene responsible for causing SMA when mutated"},{"key": "B","text": "Its copy number can modify disease severity, with more copies generally associated with milder phenotype"},{"key": "C","text": "It has no relevance whatsoever to SMA disease severity or presentation"},{"key": "D","text": "It only affects cardiac function with no relevance to motor neuron disease"}],"correct": "B","explanation": "SMN2 copy number acts as a disease modifier in SMA; because SMN2 produces some functional SMN protein (though less efficiently than SMN1), more SMN2 copies are generally associated with milder disease phenotype."},{"id": 6954,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "SMA is inherited in which pattern?","options": [{"key": "A","text": "Mitochondrial inheritance"},{"key": "B","text": "Autosomal dominant"},{"key": "C","text": "Autosomal recessive"},{"key": "D","text": "X-linked recessive"}],"correct": "C","explanation": "SMA follows autosomal recessive inheritance, requiring two mutated/deleted SMN1 alleles (one from each parent) for the condition to manifest."},{"id": 6955,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "SMA Type 1 (Werdnig-Hoffmann disease) infants classically present with which combination of findings?","options": [{"key": "A","text": "Severe hypotonia, weakness (particularly proximal), and relatively preserved facial expression/alertness"},{"key": "B","text": "Onset exclusively after age 10 years"},{"key": "C","text": "Normal motor function with isolated cognitive impairment"},{"key": "D","text": "Hypertonia and spasticity throughout all limbs"}],"correct": "A","explanation": "SMA Type 1 classically shows severe generalized hypotonia and proximal-predominant weakness, with a characteristic pattern of relatively preserved facial expressiveness/alertness despite significant limb weakness."},{"id": 6956,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important clinical feature helping distinguish SMA from many other causes of infantile hypotonia?","options": [{"key": "A","text": "SMA characteristically causes significant sensory loss, unlike other hypotonia causes"},{"key": "B","text": "Sensation typically remains intact in SMA, as it is a pure motor neuron disease"},{"key": "C","text": "SMA never presents with any hypotonia, only with hypertonia"},{"key": "D","text": "Cognitive function is always severely impaired in SMA"}],"correct": "B","explanation": "As SMA is a pure motor neuron disease, sensation is characteristically preserved, an important distinguishing clinical feature when considering the differential diagnosis of infantile hypotonia."},{"id": 6957,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Disease-modifying therapies for SMA (e.g., nusinersen - intrathecal antisense oligonucleotide, risdiplam - oral small molecule, onasemnogene abeparvovec - gene therapy) generally work by:","options": [{"key": "A","text": "Only providing symptomatic pain relief with no effect on the underlying disease mechanism"},{"key": "B","text": "Curing the condition exclusively through physical therapy intervention alone"},{"key": "C","text": "Increasing functional SMN protein production through different mechanisms targeting the underlying molecular deficiency"},{"key": "D","text": "Having no meaningful effect on functional motor outcomes"}],"correct": "C","explanation": "These various disease-modifying therapies work through different molecular mechanisms (splicing modulation, gene replacement) to increase functional SMN protein production, representing significant advances that have substantially changed SMA management and prognosis."},{"id": 6958,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding physiotherapy goals for infants with SMA now receiving disease-modifying therapy, compared to the historical pre-treatment era?","options": [{"key": "A","text": "Disease-modifying therapy eliminates any need for physiotherapy involvement"},{"key": "B","text": "Goals may now include supporting achievement of previously atypical motor milestones, requiring updated expectations informed by the changing treatment landscape"},{"key": "C","text": "Physiotherapy goals remain completely identical regardless of whether disease-modifying therapy has been administered"},{"key": "D","text": "Physiotherapy has no meaningful role for infants receiving SMA disease-modifying therapy"}],"correct": "B","explanation": "With disease-modifying therapies substantially changing the SMA disease trajectory for many infants, physiotherapy goals and expectations require updating, potentially supporting achievement of motor milestones that would have been atypical in the historical pre-treatment era."},{"id": 6959,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding respiratory management for infants/children with SMA, given characteristic intercostal muscle weakness with relatively preserved diaphragmatic function in many cases?","options": [{"key": "A","text": "Assuming identical respiratory presentation regardless of SMA type or severity"},{"key": "B","text": "Respiratory considerations have no relevance to SMA management"},{"key": "C","text": "Respiratory muscles are never affected in SMA regardless of type or severity"},{"key": "D","text": "May show a characteristic 'bell-shaped' chest deformity related to intercostal weakness, with respiratory physiotherapy addressing secretion clearance and support as needed"}],"correct": "D","explanation": "SMA often shows a characteristic pattern of intercostal muscle weakness (contributing to a 'bell-shaped' chest appearance) with relatively better-preserved diaphragmatic function, informing targeted respiratory physiotherapy approaches addressing secretion clearance and support."},{"id": 6960,"subject": "Pediatrics","topic": "Pediatric Orthopedic Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding scoliosis risk in children with SMA, particularly those with more significant weakness?","options": [{"key": "A","text": "Scoliosis risk is identical to typically developing children with no additional consideration needed"},{"key": "B","text": "Scoliosis never occurs in children with SMA regardless of severity"},{"key": "C","text": "Scoliosis monitoring is irrelevant to physiotherapy practice for children with SMA"},{"key": "D","text": "Significantly increased scoliosis risk related to trunk muscle weakness, warranting regular monitoring as part of comprehensive musculoskeletal surveillance"}],"correct": "D","explanation": "Given significant trunk muscle weakness (particularly in more severe SMA types), scoliosis risk is markedly increased, warranting regular monitoring as an important component of comprehensive musculoskeletal surveillance."},{"id": 6961,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following describes an important consideration regarding joint contracture prevention in children with SMA-related weakness?","options": [{"key": "A","text": "Contractures never occur in children with SMA given their muscle weakness pattern"},{"key": "B","text": "No preventive strategies are relevant or effective for this population"},{"key": "C","text": "Contracture prevention is only relevant for the mildest SMA types, never for more severe presentations"},{"key": "D","text": "Regular positioning, stretching, and monitoring help prevent contractures related to muscle weakness/imbalance and reduced active movement"}],"correct": "D","explanation": "Similar to other conditions causing significant weakness, children with SMA require attention to contracture prevention through appropriate positioning and stretching strategies, particularly important given reduced active movement capacity."},{"id": 6962,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Easy","question": "Which of the following describes an important consideration regarding equipment/seating provision for children with SMA, given their characteristic pattern of proximal-predominant weakness with relative preservation of some distal/hand function in certain cases?","options": [{"key": "A","text": "Equipment needs remain completely static throughout the disease course with no need for reassessment"},{"key": "B","text": "Individualized equipment (seating, mobility, potentially adapted hand-function-preserving interfaces) supports function and participation, tailored to the specific pattern of preserved/affected function"},{"key": "C","text": "A single standard equipment solution is appropriate for all children with SMA regardless of their specific functional pattern"},{"key": "D","text": "Equipment provision has no relevance to SMA management"}],"correct": "B","explanation": "Given SMA's characteristic pattern of often relatively preserved distal/hand function despite significant proximal weakness, individualized equipment provision (supporting seating, mobility, and potentially hand-function-preserving interfaces) tailored to the specific functional pattern supports optimal participation."},{"id": 6963,"subject": "Pediatrics","topic": "Neuromuscular Pediatric Conditions","difficulty": "Medium","question": "Which of the following describes an important consideration regarding hip surveillance in children with SMA, similar to considerations in other neuromuscular conditions?","options": [{"key": "A","text": "Hip displacement never occurs in SMA regardless of the pattern of muscle weakness"},{"key": "B","text": "Assuming identical hip stability regardless of the child's specific SMA type or severity"},{"key": "C","text": "Increased hip displacement risk related to muscle imbalance warrants regular monitoring as part of comprehensive musculoskeletal surveillance"},{"key": "D","text": "Hip surveillance is irrelevant for children with SMA"}],"correct": "C","explanation": "Similar to other conditions causing significant muscle weakness/imbalance, children with SMA show increased hip displacement risk, warranting regular surveillance as part of comprehensive musculoskeletal monitoring."},{"id": 6964,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding multidisciplinary team involvement in comprehensive SMA management, particularly relevant given the multisystem impact and evolving treatment landscape?","options": [{"key": "A","text": "A single specialist can independently manage all aspects of SMA care"},{"key": "B","text": "Multidisciplinary team involvement has no relevance to SMA management"},{"key": "C","text": "Coordinated input from neurology, physiotherapy, respiratory, orthopedics, and other relevant specialists supports comprehensive management addressing the condition's multisystem implications"},{"key": "D","text": "Physiotherapy should operate in complete isolation from the broader SMA care team"}],"correct": "C","explanation": "Given the multisystem impact of SMA (motor, respiratory, musculoskeletal) and the evolving, complex treatment landscape, coordinated multidisciplinary team management is considered essential for comprehensive, well-integrated care."},{"id": 6965,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Medium","question": "Which of the following describes an important consideration regarding newborn screening for SMA, increasingly implemented in various regions, relevant to early physiotherapy involvement?","options": [{"key": "A","text": "Newborn screening for SMA has no relevance to physiotherapy practice or timing of involvement"},{"key": "B","text": "Newborn screening is universally implemented identically across all regions with no variation in availability"},{"key": "C","text": "Early identification provides no benefit regarding treatment timing or outcomes"},{"key": "D","text": "Enables earlier identification and treatment initiation, supporting the rationale for early physiotherapy assessment/involvement even before significant symptom onset in screened infants"}],"correct": "D","explanation": "Newborn screening for SMA (increasingly implemented given the availability of time-sensitive disease-modifying therapies) enables earlier identification and treatment initiation, supporting the rationale for early physiotherapy involvement even in presymptomatic or minimally symptomatic identified infants."},{"id": 6966,"subject": "Pediatrics","topic": "General Pediatrics","difficulty": "Hard","question": "Which of the following best summarizes the overall evolution of the physiotherapy approach to SMA management in the context of disease-modifying therapies?","options": [{"key": "A","text": "Physiotherapy goals and approach have no relationship to advances in SMA medical treatment"},{"key": "B","text": "Disease-modifying therapies have made physiotherapy involvement entirely unnecessary for all children with SMA"},{"key": "C","text": "Physiotherapy approach remains completely unchanged regardless of any advances in disease-modifying treatment"},{"key": "D","text": "Physiotherapy approach and expectations continue to evolve alongside the changing disease trajectory associated with modern treatments, requiring ongoing updated clinical knowledge and appropriately adapted goal-setting"}],"correct": "D","explanation": "The physiotherapy approach to SMA management continues to evolve alongside the changing disease trajectory associated with modern disease-modifying therapies, requiring clinicians to maintain updated knowledge and appropriately adapt goal-setting and intervention planning to reflect this evolving landscape."},{"id": 6967,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which bone is known as the 'keystone' of the pelvis?","options": [{"key": "A","text": "Sacrum"},{"key": "B","text": "Pubis"},{"key": "C","text": "Ilium"},{"key": "D","text": "Ischium"}],"correct": "A","explanation": "The sacrum wedges between the two ilia and transmits body weight to the pelvic girdle, acting as the pelvis's keystone."},{"id": 6968,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The carrying angle of the elbow is formed due to the obliquity of which structure?","options": [{"key": "A","text": "Trochlea of humerus"},{"key": "B","text": "Coronoid process"},{"key": "C","text": "Olecranon process"},{"key": "D","text": "Capitulum of humerus"}],"correct": "A","explanation": "The trochlea's asymmetric shape tilts the forearm laterally in extension, producing the normal valgus carrying angle."},{"id": 6969,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which carpal bone is most commonly fractured?","options": [{"key": "A","text": "Capitate"},{"key": "B","text": "Triquetrum"},{"key": "C","text": "Lunate"},{"key": "D","text": "Scaphoid"}],"correct": "D","explanation": "The scaphoid is the most frequently fractured carpal bone, typically from a fall on an outstretched hand (FOOSH)."},{"id": 6970,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'anatomical snuffbox' is bordered laterally by the tendons of which muscles?","options": [{"key": "A","text": "Flexor pollicis longus"},{"key": "B","text": "Abductor pollicis longus and extensor pollicis brevis"},{"key": "C","text": "Extensor carpi radialis longus"},{"key": "D","text": "Extensor pollicis longus"}],"correct": "B","explanation": "Abductor pollicis longus and extensor pollicis brevis form the radial (lateral) border of the anatomical snuffbox."},{"id": 6971,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which ligament of the knee is the primary restraint to anterior tibial translation?","options": [{"key": "A","text": "Anterior cruciate ligament"},{"key": "B","text": "Lateral collateral ligament"},{"key": "C","text": "Medial collateral ligament"},{"key": "D","text": "Posterior cruciate ligament"}],"correct": "A","explanation": "The ACL is the main structure preventing excessive anterior translation of the tibia relative to the femur."},{"id": 6972,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The sciatic nerve most commonly passes in relation to piriformis as:","options": [{"key": "A","text": "Through the muscle belly"},{"key": "B","text": "Below the muscle"},{"key": "C","text": "Behind the muscle only"},{"key": "D","text": "Above the muscle"}],"correct": "B","explanation": "In the majority of individuals, the sciatic nerve exits the greater sciatic foramen below piriformis."},{"id": 6973,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle forms the floor of the axilla?","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Serratus anterior"},{"key": "C","text": "Pectoralis major"},{"key": "D","text": "Latissimus dorsi"}],"correct": "D","explanation": "Latissimus dorsi, along with teres major, forms the posterior wall and floor of the axilla."},{"id": 6974,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "The rotator cuff muscle primarily responsible for initiating abduction is:","options": [{"key": "A","text": "Supraspinatus"},{"key": "B","text": "Infraspinatus"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Teres minor"}],"correct": "A","explanation": "Supraspinatus initiates the first 15 degrees of shoulder abduction before deltoid takes over."},{"id": 6975,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which nerve root predominantly supplies the deltoid muscle?","options": [{"key": "A","text": "T1"},{"key": "B","text": "C4"},{"key": "C","text": "C7"},{"key": "D","text": "C5"}],"correct": "D","explanation": "The deltoid is primarily innervated by the axillary nerve, carrying fibers mainly from the C5 nerve root."},{"id": 6976,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Hard","question": "The 'anatomical neck' of the humerus is the site of attachment for:","options": [{"key": "A","text": "Deltoid muscle"},{"key": "B","text": "Joint capsule"},{"key": "C","text": "Biceps tendon"},{"key": "D","text": "Rotator cuff tendons"}],"correct": "B","explanation": "The anatomical neck lies just distal to the head of the humerus and gives attachment to the glenohumeral joint capsule."},{"id": 6977,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which structure passes through the tarsal tunnel?","options": [{"key": "A","text": "Deep peroneal nerve"},{"key": "B","text": "Superficial peroneal nerve"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Tibial nerve"}],"correct": "D","explanation": "The tibial nerve, along with flexor tendons and posterior tibial vessels, passes through the tarsal tunnel behind the medial malleolus."},{"id": 6978,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The primary function of the iliotibial band is to:","options": [{"key": "A","text": "Extend the knee"},{"key": "B","text": "Medially rotate the tibia"},{"key": "C","text": "Flex the hip"},{"key": "D","text": "Provide lateral knee stability during stance"}],"correct": "D","explanation": "The IT band, tensioned by TFL and gluteus maximus, stabilizes the lateral knee especially during single-leg stance."},{"id": 6979,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle is the primary external rotator of the hip along with piriformis?","options": [{"key": "A","text": "Iliopsoas"},{"key": "B","text": "Adductor longus"},{"key": "C","text": "Obturator internus"},{"key": "D","text": "Gluteus medius"}],"correct": "C","explanation": "Obturator internus, along with piriformis and the gemelli, forms the deep external rotator group of the hip."},{"id": 6980,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'pes anserinus' is formed by the tendons of which three muscles?","options": [{"key": "A","text": "Sartorius, gracilis, semitendinosus"},{"key": "B","text": "Semimembranosus, semitendinosus, biceps femoris"},{"key": "C","text": "Sartorius, gracilis, biceps femoris"},{"key": "D","text": "Gracilis, adductor longus, sartorius"}],"correct": "A","explanation": "Pes anserinus is the conjoint insertion of sartorius, gracilis, and semitendinosus on the proximal medial tibia."},{"id": 6981,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which cervical vertebra is known as the 'atlas'?","options": [{"key": "A","text": "C3"},{"key": "B","text": "C7"},{"key": "C","text": "C2"},{"key": "D","text": "C1"}],"correct": "D","explanation": "C1, the atlas, articulates with the occipital condyles and lacks a vertebral body, supporting the skull like the mythological Atlas."},{"id": 6982,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "The dens (odontoid process) is a bony projection of which vertebra?","options": [{"key": "A","text": "C2"},{"key": "B","text": "C3"},{"key": "C","text": "C4"},{"key": "D","text": "C1"}],"correct": "A","explanation": "The dens projects superiorly from the body of C2 (axis) and articulates with the anterior arch of C1."},{"id": 6983,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle is the prime mover for scapular upward rotation along with upper trapezius?","options": [{"key": "A","text": "Rhomboid major"},{"key": "B","text": "Pectoralis minor"},{"key": "C","text": "Levator scapulae"},{"key": "D","text": "Serratus anterior"}],"correct": "D","explanation": "Serratus anterior, together with upper and lower trapezius, forms the force couple for scapular upward rotation."},{"id": 6984,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Hard","question": "The 'quadrangular space' transmits which nerve?","options": [{"key": "A","text": "Axillary nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Suprascapular nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "A","explanation": "The axillary nerve and posterior circumflex humeral vessels pass through the quadrangular space."},{"id": 6985,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which ligament prevents excessive hip extension?","options": [{"key": "A","text": "Iliofemoral ligament"},{"key": "B","text": "Pubofemoral ligament"},{"key": "C","text": "Ligamentum teres"},{"key": "D","text": "Ischiofemoral ligament"}],"correct": "A","explanation": "The iliofemoral (Y) ligament is the strongest hip ligament and checks excessive extension."},{"id": 6986,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Hard","question": "The 'triangle of auscultation' is bounded medially by:","options": [{"key": "A","text": "Latissimus dorsi"},{"key": "B","text": "Scapula"},{"key": "C","text": "Trapezius"},{"key": "D","text": "Rhomboid major"}],"correct": "D","explanation": "The triangle of auscultation is bounded by trapezius (superomedially), latissimus dorsi (inferiorly), and rhomboid major medially/scapula."},{"id": 6987,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle is primarily responsible for scapular downward rotation and depression?","options": [{"key": "A","text": "Lower trapezius"},{"key": "B","text": "Serratus anterior"},{"key": "C","text": "Rhomboids and pectoralis minor"},{"key": "D","text": "Upper trapezius"}],"correct": "C","explanation": "Rhomboids and pectoralis minor act together to downwardly rotate and depress/retract the scapula."},{"id": 6988,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "The plantar fascia originates from which structure?","options": [{"key": "A","text": "Sustentaculum tali"},{"key": "B","text": "Calcaneal tuberosity"},{"key": "C","text": "Base of metatarsals"},{"key": "D","text": "Navicular tuberosity"}],"correct": "B","explanation": "The plantar fascia arises from the medial calcaneal tuberosity and fans out to the proximal phalanges."},{"id": 6989,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which nerve supplies sensation to the first dorsal web space of the foot?","options": [{"key": "A","text": "Superficial peroneal nerve"},{"key": "B","text": "Saphenous nerve"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Deep peroneal nerve"}],"correct": "D","explanation": "The deep peroneal nerve supplies the first dorsal web space, tested clinically in peroneal nerve injury."},{"id": 6990,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'safe zone' for radial nerve during humeral shaft surgery relates to its course in which groove?","options": [{"key": "A","text": "Deltoid tuberosity groove"},{"key": "B","text": "Bicipital groove"},{"key": "C","text": "Radial (spiral) groove"},{"key": "D","text": "Intertubercular groove"}],"correct": "C","explanation": "The radial nerve winds around the humeral shaft in the spiral (radial) groove, making it vulnerable in midshaft fractures."},{"id": 6991,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle is the chief flexor of the distal interphalangeal joints?","options": [{"key": "A","text": "Lumbricals"},{"key": "B","text": "Flexor digitorum superficialis"},{"key": "C","text": "Flexor pollicis longus"},{"key": "D","text": "Flexor digitorum profundus"}],"correct": "D","explanation": "Flexor digitorum profundus is the only muscle that flexes the DIP joints."},{"id": 6992,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'carpal tunnel' transmits how many flexor tendons along with the median nerve?","options": [{"key": "A","text": "9"},{"key": "B","text": "4"},{"key": "C","text": "6"},{"key": "D","text": "12"}],"correct": "A","explanation": "Nine tendons (4 FDS, 4 FDP, 1 FPL) pass through the carpal tunnel along with the median nerve."},{"id": 6993,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which structure is the primary restraint against varus stress at the knee?","options": [{"key": "A","text": "Medial collateral ligament"},{"key": "B","text": "Posterior cruciate ligament"},{"key": "C","text": "Anterior cruciate ligament"},{"key": "D","text": "Lateral collateral ligament"}],"correct": "D","explanation": "The lateral (fibular) collateral ligament resists varus (adduction) stress at the knee."},{"id": 6994,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'unhappy triad' of knee injury classically involves ACL, MCL and:","options": [{"key": "A","text": "LCL"},{"key": "B","text": "PCL"},{"key": "C","text": "Medial meniscus"},{"key": "D","text": "Lateral meniscus"}],"correct": "C","explanation": "O'Donoghue's unhappy triad classically includes ACL, MCL, and medial meniscus injury."},{"id": 6995,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Hard","question": "Which muscle group forms the 'pes anserinus bursa' floor?","options": [{"key": "A","text": "Popliteus tendon"},{"key": "B","text": "Tibial collateral ligament and pes anserinus tendons"},{"key": "C","text": "Quadriceps tendon"},{"key": "D","text": "Patellar tendon"}],"correct": "B","explanation": "The anserine bursa lies between the pes anserinus tendons and the underlying tibial collateral ligament."},{"id": 6996,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "The greater trochanter serves as attachment for which muscle primarily?","options": [{"key": "A","text": "Gluteus maximus"},{"key": "B","text": "Piriformis only"},{"key": "C","text": "Iliopsoas"},{"key": "D","text": "Gluteus medius and minimus"}],"correct": "D","explanation": "Gluteus medius and minimus insert on the greater trochanter, acting as prime hip abductors."},{"id": 6997,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which nerve is at risk during shoulder dislocation due to its course around the surgical neck of humerus?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "B","explanation": "The axillary nerve winds around the surgical neck of the humerus and is commonly injured in anterior shoulder dislocations."},{"id": 6998,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Hard","question": "The 'Hunter's canal (adductor canal)' transmits which nerve?","options": [{"key": "A","text": "Saphenous nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Sciatic nerve"},{"key": "D","text": "Femoral nerve (main trunk)"}],"correct": "A","explanation": "The saphenous nerve, along with the femoral artery and vein, passes through the adductor (Hunter's) canal."},{"id": 6999,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle is primarily responsible for 'locking' the knee into full extension?","options": [{"key": "A","text": "Gracilis"},{"key": "B","text": "Sartorius"},{"key": "C","text": "Popliteus"},{"key": "D","text": "Vastus medialis obliquus"}],"correct": "D","explanation": "Vastus medialis obliquus, through its terminal extension pull, helps achieve the screw-home mechanism/final locking of the knee."},{"id": 7000,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'screw-home mechanism' at the knee involves which rotation of the tibia during terminal extension?","options": [{"key": "A","text": "External rotation"},{"key": "B","text": "Internal rotation"},{"key": "C","text": "No rotation"},{"key": "D","text": "Abduction"}],"correct": "A","explanation": "During terminal knee extension, the tibia externally rotates relative to the femur due to differing condylar shapes — the screw-home mechanism."},{"id": 7001,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which ligament is the primary stabilizer against posterior tibial translation?","options": [{"key": "A","text": "MCL"},{"key": "B","text": "LCL"},{"key": "C","text": "ACL"},{"key": "D","text": "PCL"}],"correct": "D","explanation": "The posterior cruciate ligament is the main restraint to posterior translation of the tibia on the femur."},{"id": 7002,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The suprascapular nerve can be entrapped at which anatomical site?","options": [{"key": "A","text": "Carpal tunnel"},{"key": "B","text": "Suprascapular notch"},{"key": "C","text": "Cubital tunnel"},{"key": "D","text": "Quadrangular space"}],"correct": "B","explanation": "The suprascapular nerve passes under the transverse scapular ligament at the suprascapular notch, a common entrapment site."},{"id": 7003,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which muscle inserts on the lesser tuberosity of the humerus?","options": [{"key": "A","text": "Teres minor"},{"key": "B","text": "Infraspinatus"},{"key": "C","text": "Subscapularis"},{"key": "D","text": "Supraspinatus"}],"correct": "C","explanation": "Subscapularis, the only anterior rotator cuff muscle, inserts on the lesser tuberosity and internally rotates the shoulder."},{"id": 7004,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'Bankart lesion' refers to injury of which structure?","options": [{"key": "A","text": "Rotator interval"},{"key": "B","text": "Posterior labrum"},{"key": "C","text": "Anteroinferior glenoid labrum"},{"key": "D","text": "Superior labrum"}],"correct": "C","explanation": "A Bankart lesion is a tear of the anteroinferior glenoid labrum, commonly seen after anterior shoulder dislocation."},{"id": 7005,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which nerve provides sensation to the lateral aspect of the leg and dorsum of foot except first web space?","options": [{"key": "A","text": "Deep peroneal nerve"},{"key": "B","text": "Saphenous nerve"},{"key": "C","text": "Sural nerve"},{"key": "D","text": "Superficial peroneal nerve"}],"correct": "D","explanation": "The superficial peroneal nerve supplies the dorsum of the foot and lateral leg, sparing the first web space (deep peroneal territory)."},{"id": 7006,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'annular ligament' primarily stabilizes which joint?","options": [{"key": "A","text": "Knee joint"},{"key": "B","text": "Hip joint"},{"key": "C","text": "Glenohumeral joint"},{"key": "D","text": "Proximal radioulnar joint"}],"correct": "D","explanation": "The annular ligament encircles the radial head and maintains its position against the ulna at the proximal radioulnar joint."},{"id": 7007,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which muscle is the strongest hip flexor?","options": [{"key": "A","text": "Rectus femoris"},{"key": "B","text": "Iliopsoas"},{"key": "C","text": "Sartorius"},{"key": "D","text": "Tensor fasciae latae"}],"correct": "B","explanation": "Iliopsoas (iliacus + psoas major) is the primary and most powerful hip flexor."},{"id": 7008,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'Q angle' is measured between the line of pull of quadriceps and:","options": [{"key": "A","text": "Patellar tendon axis"},{"key": "B","text": "Femoral shaft axis"},{"key": "C","text": "Tibial shaft axis"},{"key": "D","text": "Tibial tuberosity to ASIS line"}],"correct": "A","explanation": "The Q angle is formed between a line from ASIS to patella center and a line from patella center to tibial tuberosity (patellar tendon axis)."},{"id": 7009,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which structure is primarily responsible for shock absorption in the foot during heel strike?","options": [{"key": "A","text": "Calcaneal fat pad"},{"key": "B","text": "Plantar fascia"},{"key": "C","text": "Achilles tendon"},{"key": "D","text": "Peroneal tendons"}],"correct": "A","explanation": "The specialized fibro-fatty calcaneal fat pad cushions and absorbs impact forces at heel strike."},{"id": 7010,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "The deltoid ligament of the ankle primarily resists which movement?","options": [{"key": "A","text": "Dorsiflexion"},{"key": "B","text": "Eversion"},{"key": "C","text": "Inversion"},{"key": "D","text": "Plantarflexion"}],"correct": "B","explanation": "The strong medial deltoid ligament resists excessive eversion and is less commonly injured than lateral ligaments."},{"id": 7011,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Easy","question": "Which of the following is NOT part of the lateral ankle ligament complex?","options": [{"key": "A","text": "Calcaneofibular ligament"},{"key": "B","text": "Anterior talofibular ligament"},{"key": "C","text": "Posterior talofibular ligament"},{"key": "D","text": "Deltoid ligament"}],"correct": "D","explanation": "The deltoid ligament is medial; the lateral complex includes ATFL, CFL, and PTFL."},{"id": 7012,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'anatomic snuffbox' floor is formed by which bone?","options": [{"key": "A","text": "Capitate"},{"key": "B","text": "Scaphoid"},{"key": "C","text": "Trapezium"},{"key": "D","text": "Lunate"}],"correct": "B","explanation": "The scaphoid forms the floor of the anatomical snuffbox, making it clinically important to palpate for tenderness after wrist trauma."},{"id": 7013,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle is primarily responsible for wrist ulnar deviation?","options": [{"key": "A","text": "Flexor carpi ulnaris and extensor carpi ulnaris"},{"key": "B","text": "Palmaris longus"},{"key": "C","text": "Flexor carpi radialis"},{"key": "D","text": "Extensor carpi radialis longus"}],"correct": "A","explanation": "Flexor carpi ulnaris and extensor carpi ulnaris act together to produce ulnar deviation of the wrist."},{"id": 7014,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Hard","question": "The transverse acetabular ligament converts the acetabular notch into a foramen for passage of:","options": [{"key": "A","text": "Sciatic nerve"},{"key": "B","text": "Nutrient vessels to femoral head"},{"key": "C","text": "Femoral artery"},{"key": "D","text": "Obturator nerve"}],"correct": "B","explanation": "The transverse acetabular ligament bridges the acetabular notch, allowing passage of nutrient vessels supplying the femoral head."},{"id": 7015,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle's tendon forms the 'roof' of the carpal tunnel?","options": [{"key": "A","text": "Abductor pollicis brevis"},{"key": "B","text": "None — the flexor retinaculum forms the roof"},{"key": "C","text": "Palmaris longus"},{"key": "D","text": "Flexor carpi radialis"}],"correct": "B","explanation": "The flexor retinaculum (transverse carpal ligament), not a muscle tendon, forms the roof of the carpal tunnel."},{"id": 7016,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "The 'watershed area' of poor vascularity predisposing to tendon rupture is classically described in which tendon?","options": [{"key": "A","text": "Quadriceps tendon"},{"key": "B","text": "Achilles tendon"},{"key": "C","text": "Patellar tendon"},{"key": "D","text": "Biceps tendon"}],"correct": "B","explanation": "The Achilles tendon has a hypovascular watershed zone approximately 2-6 cm above its insertion, prone to degeneration and rupture."},{"id": 7017,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "According to Newton's third law, forces always occur in:","options": [{"key": "A","text": "Equal and opposite pairs"},{"key": "B","text": "Isolated single directions"},{"key": "C","text": "Sequential but unrelated events"},{"key": "D","text": "Random unpredictable patterns"}],"correct": "A","explanation": "Newton's third law states every action has an equal and opposite reaction, forming force pairs."},{"id": 7018,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Hard","question": "The instantaneous axis of rotation of a joint refers to:","options": [{"key": "A","text": "A fixed anatomical point"},{"key": "B","text": "A theoretical construct with no clinical use"},{"key": "C","text": "The center of the joint capsule"},{"key": "D","text": "The momentarily changing axis about which motion occurs"}],"correct": "D","explanation": "The instantaneous axis of rotation shifts continuously through range of motion, unlike a fixed mechanical axis."},{"id": 7019,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Which type of lever is exemplified by the triceps acting at the elbow during extension against resistance?","options": [{"key": "A","text": "First-class lever"},{"key": "B","text": "Third-class lever"},{"key": "C","text": "Second-class lever"},{"key": "D","text": "Fourth-class lever"}],"correct": "A","explanation": "With the elbow (fulcrum) between the triceps insertion (effort) and the hand (resistance), this represents a first-class lever."},{"id": 7020,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "The brachialis muscle acting at the elbow is an example of which class of lever?","options": [{"key": "A","text": "First-class"},{"key": "B","text": "Third-class"},{"key": "C","text": "No lever system involved"},{"key": "D","text": "Second-class"}],"correct": "B","explanation": "In a third-class lever, effort lies between fulcrum and resistance — typical of most limb muscles including brachialis at the elbow."},{"id": 7021,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Which lever system provides a mechanical advantage greater than 1?","options": [{"key": "A","text": "First-class only"},{"key": "B","text": "Second-class"},{"key": "C","text": "None of these always do"},{"key": "D","text": "Third-class"}],"correct": "B","explanation": "Second-class levers (resistance between fulcrum and effort) always provide mechanical advantage >1, e.g., calf raise."},{"id": 7022,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Torque is the product of force and:","options": [{"key": "A","text": "Velocity"},{"key": "B","text": "Time"},{"key": "C","text": "Mass"},{"key": "D","text": "Moment arm (perpendicular distance)"}],"correct": "D","explanation": "Torque = Force x moment arm, where the moment arm is the perpendicular distance from the axis of rotation to the line of force."},{"id": 7023,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Center of gravity of the human body in standing is located approximately at which vertebral level?","options": [{"key": "A","text": "S2"},{"key": "B","text": "L5"},{"key": "C","text": "T12"},{"key": "D","text": "C7"}],"correct": "A","explanation": "The center of gravity in an average standing adult lies anterior to the S2 vertebra."},{"id": 7024,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "A wider base of support generally results in:","options": [{"key": "A","text": "Increased center of gravity height"},{"key": "B","text": "Decreased stability"},{"key": "C","text": "No change in stability"},{"key": "D","text": "Increased stability"}],"correct": "D","explanation": "A wider base of support increases stability by expanding the limits within which the center of gravity can shift without falling."},{"id": 7025,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Which term describes the resistance of an object to a change in its state of motion?","options": [{"key": "A","text": "Momentum"},{"key": "B","text": "Inertia"},{"key": "C","text": "Velocity"},{"key": "D","text": "Torque"}],"correct": "B","explanation": "Inertia, per Newton's first law, is the tendency of an object to resist changes in its state of motion."},{"id": 7026,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "The concept of 'closed kinetic chain' exercise refers to:","options": [{"key": "A","text": "No joint movement occurs"},{"key": "B","text": "Distal segment free to move"},{"key": "C","text": "Only isometric contractions"},{"key": "D","text": "Distal segment fixed, proximal segment moves"}],"correct": "D","explanation": "In closed kinetic chain exercises, the distal segment is fixed against a surface while proximal segments move, e.g., squats."},{"id": 7027,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Which of the following is an example of an open kinetic chain exercise?","options": [{"key": "A","text": "Seated knee extension"},{"key": "B","text": "Squat"},{"key": "C","text": "Leg press"},{"key": "D","text": "Push-up"}],"correct": "A","explanation": "Seated knee extension has the distal segment (foot) free to move in space, characteristic of open kinetic chain exercise."},{"id": 7028,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "The 'force-velocity relationship' of muscle states that as velocity of shortening increases, force generation:","options": [{"key": "A","text": "Becomes infinite"},{"key": "B","text": "Decreases"},{"key": "C","text": "Remains constant"},{"key": "D","text": "Increases proportionally"}],"correct": "B","explanation": "Per the Hill force-velocity curve, muscle force capacity decreases as the velocity of concentric shortening increases."},{"id": 7029,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Which type of muscle contraction generates the greatest force for a given muscle?","options": [{"key": "A","text": "Isometric"},{"key": "B","text": "Concentric"},{"key": "C","text": "Isokinetic at high speed"},{"key": "D","text": "Eccentric"}],"correct": "D","explanation": "Eccentric contractions typically generate the highest force output compared to concentric or isometric contractions."},{"id": 7030,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "The length-tension relationship of skeletal muscle indicates maximum active tension occurs at:","options": [{"key": "A","text": "Optimal resting length with maximal cross-bridge overlap"},{"key": "B","text": "Any length equally"},{"key": "C","text": "Very short muscle lengths"},{"key": "D","text": "Maximal muscle stretch"}],"correct": "A","explanation": "Maximum active tension is generated at the muscle's optimal resting length, allowing maximal actin-myosin cross-bridge formation."},{"id": 7031,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Which plane of motion does flexion and extension of the knee occur in?","options": [{"key": "A","text": "Sagittal plane"},{"key": "B","text": "Transverse plane"},{"key": "C","text": "Oblique plane"},{"key": "D","text": "Frontal plane"}],"correct": "A","explanation": "Flexion and extension are sagittal plane movements occurring around a coronal (frontal) axis."},{"id": 7032,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Abduction and adduction of the hip occur primarily in which plane?","options": [{"key": "A","text": "Horizontal plane at the hip only"},{"key": "B","text": "Sagittal plane"},{"key": "C","text": "Frontal plane"},{"key": "D","text": "Transverse plane"}],"correct": "C","explanation": "Abduction/adduction occurs in the frontal plane around a sagittal axis."},{"id": 7033,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Internal and external rotation of the shoulder occur in which plane?","options": [{"key": "A","text": "Transverse plane"},{"key": "B","text": "Frontal plane"},{"key": "C","text": "Sagittal plane"},{"key": "D","text": "None of the cardinal planes"}],"correct": "A","explanation": "Rotational movements occur in the transverse plane around a vertical (longitudinal) axis."},{"id": 7034,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Which term describes a muscle's ability to generate tension while shortening?","options": [{"key": "A","text": "Isometric contraction"},{"key": "B","text": "Concentric contraction"},{"key": "C","text": "Passive tension"},{"key": "D","text": "Eccentric contraction"}],"correct": "B","explanation": "Concentric contraction occurs when a muscle shortens while generating tension to overcome resistance."},{"id": 7035,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "During eccentric contraction, the muscle:","options": [{"key": "A","text": "Lengthens while generating tension"},{"key": "B","text": "Shortens while generating tension"},{"key": "C","text": "Maintains constant length"},{"key": "D","text": "Generates no tension"}],"correct": "A","explanation": "Eccentric contraction involves the muscle lengthening under tension, often used to decelerate movement."},{"id": 7036,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "The 'stretch-shortening cycle' utilizes which property of muscle-tendon units?","options": [{"key": "A","text": "Passive stiffness only"},{"key": "B","text": "Isometric holding capacity"},{"key": "C","text": "Concentric force alone"},{"key": "D","text": "Elastic energy storage from eccentric pre-stretch"}],"correct": "D","explanation": "The stretch-shortening cycle stores elastic energy during a rapid eccentric phase, which is then released during the subsequent concentric phase, enhancing performance."},{"id": 7037,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Which factor primarily determines the moment arm of a muscle at a joint?","options": [{"key": "A","text": "Muscle color"},{"key": "B","text": "Perpendicular distance from muscle line of pull to joint axis"},{"key": "C","text": "Muscle fiber type"},{"key": "D","text": "Blood supply to the muscle"}],"correct": "B","explanation": "The moment arm is defined by the perpendicular distance between the muscle's line of pull and the joint's axis of rotation."},{"id": 7038,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "A muscle with a large physiological cross-sectional area (PCSA) primarily has greater:","options": [{"key": "A","text": "Endurance only"},{"key": "B","text": "Speed of contraction"},{"key": "C","text": "Range of motion"},{"key": "D","text": "Force-generating capacity"}],"correct": "D","explanation": "PCSA is directly proportional to the maximum force a muscle can generate."},{"id": 7039,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Pennate muscle architecture (compared to fusiform) generally provides:","options": [{"key": "A","text": "Equal force and excursion"},{"key": "B","text": "Neither force nor excursion advantage"},{"key": "C","text": "Greater force, less excursion"},{"key": "D","text": "Greater excursion, less force"}],"correct": "C","explanation": "Pennate muscles pack more fibers per unit area (higher PCSA), producing greater force but with reduced excursion/velocity compared to fusiform muscles."},{"id": 7040,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Which of Newton's laws explains why a person continues moving forward when a moving vehicle suddenly stops?","options": [{"key": "A","text": "First law (inertia)"},{"key": "B","text": "None of these"},{"key": "C","text": "Second law (F=ma)"},{"key": "D","text": "Third law (action-reaction)"}],"correct": "A","explanation": "Newton's first law of inertia explains that a body in motion tends to remain in motion unless acted upon by an external force."},{"id": 7041,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Hard","question": "Ground reaction force during normal walking gait shows a characteristic pattern with how many peaks (M-shape)?","options": [{"key": "A","text": "Three peaks"},{"key": "B","text": "No consistent pattern"},{"key": "C","text": "Two peaks"},{"key": "D","text": "One peak"}],"correct": "C","explanation": "Normal vertical ground reaction force during stance shows a double-hump (M-shaped) pattern with two peaks corresponding to loading and push-off."},{"id": 7042,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Hard","question": "The 'line of gravity' in ideal standing posture passes through which of the following, among others?","options": [{"key": "A","text": "Through the sternum only"},{"key": "B","text": "Anterior to hip joint, posterior to knee axis"},{"key": "C","text": "Behind the spine only"},{"key": "D","text": "Posterior to hip joint, anterior to knee axis"}],"correct": "B","explanation": "In ideal alignment, the line of gravity passes posterior to hip axis... actually it passes slightly anterior to S2, posterior to hip joint and anterior to knee and ankle axes for energy-efficient standing."},{"id": 7043,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Which of the following best defines 'stability' in biomechanical terms?","options": [{"key": "A","text": "The height of the center of gravity"},{"key": "B","text": "Resistance to disturbance of equilibrium"},{"key": "C","text": "Muscle strength alone"},{"key": "D","text": "The ability to move quickly"}],"correct": "B","explanation": "Stability refers to the resistance of a body to having its equilibrium disturbed, influenced by base of support and center of gravity height."},{"id": 7044,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "A lower center of gravity relative to the base of support results in:","options": [{"key": "A","text": "Increased risk of falling"},{"key": "B","text": "No effect on stability"},{"key": "C","text": "Increased stability"},{"key": "D","text": "Decreased stability"}],"correct": "C","explanation": "Lowering the center of gravity relative to the base of support enhances postural stability."},{"id": 7045,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Which joint motion combination describes 'circumduction'?","options": [{"key": "A","text": "Sequential flexion, abduction, extension, adduction"},{"key": "B","text": "Pure rotation only"},{"key": "C","text": "Pure flexion only"},{"key": "D","text": "Simultaneous flexion and extension"}],"correct": "A","explanation": "Circumduction is a conical movement combining flexion, abduction, extension, and adduction in sequence."},{"id": 7046,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "The term 'kinematics' refers to the study of:","options": [{"key": "A","text": "Joint pathology"},{"key": "B","text": "Muscle physiology only"},{"key": "C","text": "Forces causing motion"},{"key": "D","text": "Motion without regard to forces causing it"}],"correct": "D","explanation": "Kinematics describes motion (displacement, velocity, acceleration) without considering the forces that produce it, unlike kinetics."},{"id": 7047,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "'Kinetics' in biomechanics refers to the study of:","options": [{"key": "A","text": "Motion patterns only"},{"key": "B","text": "Joint range of motion only"},{"key": "C","text": "Muscle color and fiber type"},{"key": "D","text": "Forces that cause or result from motion"}],"correct": "D","explanation": "Kinetics is the branch of mechanics dealing with forces that cause or result from motion."},{"id": 7048,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Which statement about 'friction' is correct in a biomechanical context?","options": [{"key": "A","text": "Friction has no relevance to gait"},{"key": "B","text": "Friction always aids stability regardless of direction"},{"key": "C","text": "Friction opposes relative motion between two contacting surfaces"},{"key": "D","text": "Friction is always harmful to joint motion"}],"correct": "C","explanation": "Friction is a resistive force opposing relative motion between two surfaces in contact, relevant to foot-ground interaction during gait."},{"id": 7049,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Angular velocity is defined as the rate of change of:","options": [{"key": "A","text": "Mass"},{"key": "B","text": "Linear displacement"},{"key": "C","text": "Angular displacement"},{"key": "D","text": "Force"}],"correct": "C","explanation": "Angular velocity measures how quickly angular displacement (rotation) changes over time."},{"id": 7050,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "Which factor does NOT affect the magnitude of torque produced by a muscle?","options": [{"key": "A","text": "Muscle color"},{"key": "B","text": "Angle of muscle pull relative to bone"},{"key": "C","text": "Force of muscle contraction"},{"key": "D","text": "Moment arm length"}],"correct": "A","explanation": "Muscle color (red vs white fibers, related to fiber type) does not directly determine torque; torque depends on force, moment arm, and angle of pull."},{"id": 7051,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Hard","question": "The 'active insufficiency' of a two-joint muscle occurs when the muscle is:","options": [{"key": "A","text": "Maximally stretched over both joints"},{"key": "B","text": "Passively stretched only"},{"key": "C","text": "At resting length"},{"key": "D","text": "Shortened over both joints simultaneously, limiting further shortening"}],"correct": "D","explanation": "Active insufficiency occurs when a two-joint muscle is shortened over both joints simultaneously and can no longer generate effective tension."},{"id": 7052,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Hard","question": "'Passive insufficiency' occurs when a two-joint muscle is:","options": [{"key": "A","text": "Stretched over both joints simultaneously, limiting further range"},{"key": "B","text": "Contracting isometrically"},{"key": "C","text": "Shortened maximally"},{"key": "D","text": "Not involved in the movement"}],"correct": "A","explanation": "Passive insufficiency occurs when a two-joint muscle is lengthened over both joints simultaneously, restricting the range achievable at both joints together."},{"id": 7053,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Hard","question": "Which of the following best exemplifies passive insufficiency?","options": [{"key": "A","text": "Inability to abduct the shoulder"},{"key": "B","text": "Inability to make a full fist with wrist flexed (finger flexors)"},{"key": "C","text": "Inability to fully extend the elbow"},{"key": "D","text": "Inability to plantarflex the ankle"}],"correct": "B","explanation": "Attempting to make a full fist with the wrist flexed demonstrates passive insufficiency of the finger extensors limiting simultaneous full wrist and finger flexion... clinically the classic example is finger flexors becoming passively insufficient limiting grip strength when wrist is flexed."},{"id": 7054,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Medium","question": "The coefficient of friction between two surfaces depends primarily on:","options": [{"key": "A","text": "The temperature of the room only"},{"key": "B","text": "The nature/texture of the two surfaces in contact"},{"key": "C","text": "The color of the surfaces"},{"key": "D","text": "The speed of movement alone"}],"correct": "B","explanation": "The coefficient of friction is primarily determined by the material properties and texture of the two contacting surfaces."},{"id": 7055,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Which of the following is a vector quantity?","options": [{"key": "A","text": "Mass"},{"key": "B","text": "Speed"},{"key": "C","text": "Distance"},{"key": "D","text": "Force"}],"correct": "D","explanation": "Force is a vector quantity possessing both magnitude and direction, unlike scalar quantities such as speed, distance, or mass."},{"id": 7056,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Easy","question": "Mechanical work is calculated as the product of force and:","options": [{"key": "A","text": "Time"},{"key": "B","text": "Displacement in the direction of force"},{"key": "C","text": "Velocity"},{"key": "D","text": "Mass"}],"correct": "B","explanation": "Work = Force x displacement in the direction the force is applied."},{"id": 7057,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "In manual muscle testing (MMT), a grade of 3/5 (Fair) indicates the patient can:","options": [{"key": "A","text": "Move through full ROM against gravity with moderate resistance"},{"key": "B","text": "Show only a trace of contraction"},{"key": "C","text": "Move through full ROM against gravity with no resistance"},{"key": "D","text": "Move only with gravity eliminated"}],"correct": "C","explanation": "Grade 3 (Fair) means the patient completes full ROM against gravity but cannot tolerate any added manual resistance."},{"id": 7058,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "A muscle grade of 2/5 in MMT (Poor) corresponds to:","options": [{"key": "A","text": "No palpable contraction"},{"key": "B","text": "Full ROM with gravity eliminated"},{"key": "C","text": "Trace contraction, no joint movement"},{"key": "D","text": "Full ROM against gravity"}],"correct": "B","explanation": "Grade 2 (Poor) indicates the patient can move the part through full range only when gravity is eliminated (e.g., on a horizontal surface)."},{"id": 7059,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "MMT grade 0 signifies:","options": [{"key": "A","text": "Weak but visible movement"},{"key": "B","text": "Trace contraction palpable"},{"key": "C","text": "No contraction detected on palpation or observation"},{"key": "D","text": "Full range against gravity"}],"correct": "C","explanation": "Grade 0 (Zero) means no muscle contraction is palpable or visible on attempted movement."},{"id": 7060,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which posture is characterized by increased thoracic kyphosis, forward head, and rounded shoulders?","options": [{"key": "A","text": "Military posture"},{"key": "B","text": "Swayback posture"},{"key": "C","text": "Flat back posture"},{"key": "D","text": "Kyphotic-lordotic posture"}],"correct": "D","explanation": "Kyphotic-lordotic posture shows increased thoracic kyphosis along with forward head, protracted scapulae, and often increased lumbar lordosis."},{"id": 7061,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "In 'swayback' posture, the pelvis characteristically shows:","options": [{"key": "A","text": "No tilt, neutral position"},{"key": "B","text": "Posterior pelvic tilt with forward-shifted pelvis"},{"key": "C","text": "Lateral pelvic tilt"},{"key": "D","text": "Anterior pelvic tilt"}],"correct": "B","explanation": "Swayback posture involves posterior pelvic tilt with the pelvis translated anteriorly relative to the thorax, and increased thoracic kyphosis."},{"id": 7062,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Normal active range of motion for shoulder flexion is approximately:","options": [{"key": "A","text": "220 degrees"},{"key": "B","text": "120 degrees"},{"key": "C","text": "180 degrees"},{"key": "D","text": "90 degrees"}],"correct": "C","explanation": "Normal shoulder flexion range is approximately 0-180 degrees."},{"id": 7063,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Normal active range of motion for knee flexion is approximately:","options": [{"key": "A","text": "90 degrees"},{"key": "B","text": "60 degrees"},{"key": "C","text": "135 degrees"},{"key": "D","text": "180 degrees"}],"correct": "C","explanation": "Normal knee flexion range is approximately 0-135 to 140 degrees."},{"id": 7064,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "The goniometer's stationary arm during hip flexion measurement is typically aligned with:","options": [{"key": "A","text": "The tibia"},{"key": "B","text": "The midaxillary line of trunk"},{"key": "C","text": "The fibula"},{"key": "D","text": "The femur"}],"correct": "B","explanation": "For hip flexion, the stationary arm is aligned parallel to the trunk (midaxillary line) while the moving arm follows the femur."},{"id": 7065,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which phase of gait represents the period when both feet are in contact with the ground?","options": [{"key": "A","text": "Double support phase"},{"key": "B","text": "Swing phase"},{"key": "C","text": "Single limb stance"},{"key": "D","text": "Terminal swing"}],"correct": "A","explanation": "Double support (double stance) occurs twice per gait cycle when both feet simultaneously contact the ground."},{"id": 7066,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "The normal gait cycle stance phase constitutes approximately what percentage of the cycle?","options": [{"key": "A","text": "40%"},{"key": "B","text": "80%"},{"key": "C","text": "20%"},{"key": "D","text": "60%"}],"correct": "D","explanation": "Stance phase constitutes approximately 60% of the normal gait cycle, with swing phase making up the remaining 40%."},{"id": 7067,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "'Heel strike' is now more commonly termed as which phase in Rancho Los Amigos gait terminology?","options": [{"key": "A","text": "Pre-swing"},{"key": "B","text": "Initial contact"},{"key": "C","text": "Mid stance"},{"key": "D","text": "Loading response"}],"correct": "B","explanation": "In Rancho Los Amigos terminology, 'heel strike' is termed 'initial contact', the instant the foot touches the ground."},{"id": 7068,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "An antalgic gait pattern is characterized by:","options": [{"key": "A","text": "No change in gait timing"},{"key": "B","text": "Shortened swing phase on painful limb"},{"key": "C","text": "Shortened stance phase on the painful limb"},{"key": "D","text": "Prolonged stance on painful limb"}],"correct": "C","explanation": "Antalgic gait involves a shortened stance phase on the affected/painful limb to minimize weight-bearing time and pain."},{"id": 7069,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Trendelenburg gait results from weakness of which muscle?","options": [{"key": "A","text": "Iliopsoas"},{"key": "B","text": "Quadriceps"},{"key": "C","text": "Gluteus maximus"},{"key": "D","text": "Gluteus medius"}],"correct": "D","explanation": "Weak gluteus medius fails to stabilize the pelvis during single-limb stance, causing the contralateral pelvis to drop (Trendelenburg sign)."},{"id": 7070,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "A 'steppage gait' is most commonly associated with weakness of which muscle group?","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Ankle dorsiflexors"},{"key": "C","text": "Hip abductors"},{"key": "D","text": "Knee extensors"}],"correct": "B","explanation": "Steppage gait, with exaggerated hip and knee flexion to clear the foot, results from ankle dorsiflexor weakness (foot drop)."},{"id": 7071,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which observation tool is used to standardize gait phase terminology developed by a rehabilitation center in California?","options": [{"key": "A","text": "Rancho Los Amigos system"},{"key": "B","text": "Vicon system"},{"key": "C","text": "Berg scale"},{"key": "D","text": "Oxford scale"}],"correct": "A","explanation": "The Rancho Los Amigos National Rehabilitation Center developed the widely used standardized gait terminology."},{"id": 7072,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Normal cadence (steps per minute) in adult walking is approximately:","options": [{"key": "A","text": "40-60"},{"key": "B","text": "70-90"},{"key": "C","text": "150-180"},{"key": "D","text": "100-130"}],"correct": "D","explanation": "Normal adult cadence during comfortable walking is approximately 100-130 steps per minute (walking speed dependent)."},{"id": 7073,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "During gait analysis, 'step length' refers to:","options": [{"key": "A","text": "Distance between heel strike of one foot and heel strike of the opposite foot"},{"key": "B","text": "Distance between successive heel strikes of same foot"},{"key": "C","text": "Total distance walked"},{"key": "D","text": "Width between the two feet"}],"correct": "A","explanation": "Step length is measured from the heel strike of one foot to the heel strike of the contralateral foot."},{"id": 7074,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "'Stride length' in gait analysis refers to:","options": [{"key": "A","text": "Half of step length"},{"key": "B","text": "Time taken for one step"},{"key": "C","text": "Distance between two feet"},{"key": "D","text": "Distance covered by one full gait cycle of the same limb"}],"correct": "D","explanation": "Stride length is the linear distance between two successive points of contact of the same foot (i.e., one complete gait cycle)."},{"id": 7075,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which sensory examination technique tests protective (superficial) sensation using a fine filament?","options": [{"key": "A","text": "Vibration testing"},{"key": "B","text": "Two-point discrimination"},{"key": "C","text": "Semmes-Weinstein monofilament test"},{"key": "D","text": "Stereognosis testing"}],"correct": "C","explanation": "The Semmes-Weinstein monofilament test assesses light touch/protective sensation threshold, commonly used in diabetic neuropathy screening."},{"id": 7076,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Manual muscle testing grade 4/5 (Good) indicates the patient can move through full ROM against gravity with:","options": [{"key": "A","text": "Maximal resistance"},{"key": "B","text": "No resistance"},{"key": "C","text": "Moderate resistance"},{"key": "D","text": "Only gravity-eliminated positions"}],"correct": "C","explanation": "Grade 4 (Good) means the patient tolerates moderate manual resistance through full range against gravity, less than a normal (5/5) muscle."},{"id": 7077,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which of the following best describes 'end-feel' in joint assessment?","options": [{"key": "A","text": "The speed of joint movement"},{"key": "B","text": "The patient's pain rating at end range"},{"key": "C","text": "The quality of resistance felt by the examiner at the end of passive ROM"},{"key": "D","text": "The final position reached in active ROM"}],"correct": "C","explanation": "End-feel refers to the sensation the examiner perceives at the end of passive range of motion, providing diagnostic information about the limiting structure."},{"id": 7078,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "A 'capsular end-feel' is best described as:","options": [{"key": "A","text": "Hard, bony, abrupt stop"},{"key": "B","text": "Firm with slight give, leathery sensation"},{"key": "C","text": "Springy rebound"},{"key": "D","text": "Soft tissue approximation, mushy"}],"correct": "B","explanation": "Capsular end-feel has a firm, leathery quality with some give, typical of ligamentous/capsular restriction."},{"id": 7079,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "A 'bony' end-feel is typically found in which condition?","options": [{"key": "A","text": "Ligament sprain"},{"key": "B","text": "Muscle spasm"},{"key": "C","text": "Normal elbow extension (physiological)"},{"key": "D","text": "Osteoarthritis with osteophyte formation"}],"correct": "C","explanation": "Normal elbow extension has an abrupt, hard bony end-feel due to olecranon contacting the olecranon fossa; pathological bony end-feel occurs with osteophytes as in OA."},{"id": 7080,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "An 'empty end-feel' occurs when:","options": [{"key": "A","text": "There is normal joint resistance with no pain"},{"key": "B","text": "Pain prevents the examiner from reaching the actual tissue limit"},{"key": "C","text": "The examiner cannot feel any resistance sensation but movement is normal"},{"key": "D","text": "The joint moves freely with a soft stop"}],"correct": "B","explanation": "Empty end-feel occurs when the patient stops the examiner due to severe pain before any mechanical resistance is felt, often indicating acute inflammation or serious pathology."},{"id": 7081,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Which posture assessment finding is termed 'genu varum'?","options": [{"key": "A","text": "Bow legs"},{"key": "B","text": "Knock knees"},{"key": "C","text": "Hyperextended knees"},{"key": "D","text": "Flexed knees"}],"correct": "A","explanation": "Genu varum refers to a bow-legged deformity where the knees are positioned laterally relative to the midline (increased intercondylar distance)."},{"id": 7082,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "'Genu valgum' describes which lower limb alignment?","options": [{"key": "A","text": "Internally rotated tibia"},{"key": "B","text": "Hyperextended knees"},{"key": "C","text": "Knock knees"},{"key": "D","text": "Bow legs"}],"correct": "C","explanation": "Genu valgum, or 'knock knees', is characterized by the knees angling inward and touching while the ankles remain apart."},{"id": 7083,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "'Genu recurvatum' refers to:","options": [{"key": "A","text": "Rotational knee deformity"},{"key": "B","text": "Flexion contracture of the knee"},{"key": "C","text": "Lateral knee deviation"},{"key": "D","text": "Hyperextension deformity of the knee"}],"correct": "D","explanation": "Genu recurvatum is a hyperextension deformity where the knee bows backward beyond normal extension range."},{"id": 7084,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Which observation describes 'pes cavus'?","options": [{"key": "A","text": "Foot turned inward"},{"key": "B","text": "High-arched foot"},{"key": "C","text": "Foot turned outward"},{"key": "D","text": "Flat foot with low medial arch"}],"correct": "B","explanation": "Pes cavus refers to an abnormally high medial longitudinal arch of the foot."},{"id": 7085,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "'Pes planus' refers to:","options": [{"key": "A","text": "High arched foot"},{"key": "B","text": "Hammer toe deformity"},{"key": "C","text": "Clubfoot deformity"},{"key": "D","text": "Flat foot (collapsed medial arch)"}],"correct": "D","explanation": "Pes planus describes a flattened or collapsed medial longitudinal arch of the foot."},{"id": 7086,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "During gait assessment, 'foot slap' immediately after initial contact suggests weakness of:","options": [{"key": "A","text": "Gastrocnemius"},{"key": "B","text": "Gluteus maximus"},{"key": "C","text": "Quadriceps"},{"key": "D","text": "Tibialis anterior (eccentric control)"}],"correct": "D","explanation": "Foot slap occurs when weak dorsiflexors (tibialis anterior) fail to eccentrically control the foot after initial contact, allowing it to slap down."},{"id": 7087,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "A goniometer's fulcrum is placed at the:","options": [{"key": "A","text": "Origin of the muscle being tested"},{"key": "B","text": "Distal end of the stationary segment"},{"key": "C","text": "Midpoint of the moving segment"},{"key": "D","text": "Axis of joint motion"}],"correct": "D","explanation": "The goniometer's fulcrum (axis) is aligned with the estimated axis of motion of the joint being measured."},{"id": 7088,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Normal shoulder external rotation range (with arm at side) is approximately:","options": [{"key": "A","text": "120 degrees"},{"key": "B","text": "90 degrees"},{"key": "C","text": "60 degrees"},{"key": "D","text": "30 degrees"}],"correct": "C","explanation": "Normal shoulder external rotation with the arm at the side is approximately 60-90 degrees, commonly cited as 60 degrees in neutral."},{"id": 7089,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Normal ankle dorsiflexion range of motion is approximately:","options": [{"key": "A","text": "0-20 degrees"},{"key": "B","text": "0-10 degrees"},{"key": "C","text": "0-60 degrees"},{"key": "D","text": "0-45 degrees"}],"correct": "A","explanation": "Normal ankle dorsiflexion range is approximately 0-20 degrees."},{"id": 7090,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Normal ankle plantarflexion range of motion is approximately:","options": [{"key": "A","text": "30 degrees"},{"key": "B","text": "20 degrees"},{"key": "C","text": "50 degrees"},{"key": "D","text": "70 degrees"}],"correct": "C","explanation": "Normal ankle plantarflexion range is approximately 0-50 degrees."},{"id": 7091,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which examination is used to assess for leg length discrepancy?","options": [{"key": "A","text": "Ober's test"},{"key": "B","text": "Trendelenburg test"},{"key": "C","text": "Tape measure method (ASIS to medial malleolus)"},{"key": "D","text": "Thomas test"}],"correct": "C","explanation": "True leg length is measured using a tape from the ASIS to the medial malleolus on each side and comparing."},{"id": 7092,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "'Apparent' leg length discrepancy is measured from which landmark?","options": [{"key": "A","text": "Greater trochanter to lateral malleolus"},{"key": "B","text": "ASIS to medial malleolus"},{"key": "C","text": "Umbilicus to medial malleolus"},{"key": "D","text": "Xiphisternum to ASIS"}],"correct": "C","explanation": "Apparent leg length is measured from a fixed midline point (umbilicus) to the medial malleolus, reflecting functional/postural asymmetry rather than true bony length."},{"id": 7093,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Which grading scale is commonly used to assess spasticity in clinical practice?","options": [{"key": "A","text": "Nine-Hole Peg Test"},{"key": "B","text": "Berg Balance Scale"},{"key": "C","text": "Modified Ashworth Scale"},{"key": "D","text": "Oxford scale"}],"correct": "C","explanation": "The Modified Ashworth Scale is the standard clinical tool for grading resistance to passive stretch (spasticity)."},{"id": 7094,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "On the Modified Ashworth Scale, a grade of '1+' indicates:","options": [{"key": "A","text": "Rigid in flexion or extension"},{"key": "B","text": "No increase in muscle tone"},{"key": "C","text": "Considerable increase in tone throughout ROM"},{"key": "D","text": "Slight increase in tone with catch followed by minimal resistance through remaining ROM"}],"correct": "D","explanation": "Grade 1+ describes a slight increase in muscle tone manifested by a catch followed by minimal resistance through the rest of the range."},{"id": 7095,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which functional balance assessment tool uses 14 items scored 0-4 to assess fall risk in elderly patients?","options": [{"key": "A","text": "Berg Balance Scale"},{"key": "B","text": "Functional Reach Test"},{"key": "C","text": "Tinetti scale"},{"key": "D","text": "Timed Up and Go test"}],"correct": "A","explanation": "The Berg Balance Scale comprises 14 functional tasks, each scored 0-4, widely used to assess balance and fall risk."},{"id": 7096,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "The 'Timed Up and Go' (TUG) test primarily assesses:","options": [{"key": "A","text": "Functional mobility and fall risk"},{"key": "B","text": "Upper limb coordination"},{"key": "C","text": "Cognitive function only"},{"key": "D","text": "Cardiovascular endurance"}],"correct": "A","explanation": "TUG measures the time taken to rise from a chair, walk 3 meters, turn, return, and sit down — a functional mobility and fall risk indicator."},{"id": 7097,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "A TUG test time greater than how many seconds is generally considered indicative of increased fall risk?","options": [{"key": "A","text": "12-14 seconds"},{"key": "B","text": "5 seconds"},{"key": "C","text": "30 seconds"},{"key": "D","text": "8 seconds"}],"correct": "A","explanation": "A TUG time of 12-14 seconds or more is generally associated with increased fall risk in older adults."},{"id": 7098,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which posture type is characterized by decreased normal spinal curves (flattened lumbar and thoracic curves)?","options": [{"key": "A","text": "Swayback posture"},{"key": "B","text": "Flat back posture"},{"key": "C","text": "Military posture"},{"key": "D","text": "Kyphotic-lordotic posture"}],"correct": "B","explanation": "Flat back posture shows a posterior pelvic tilt with reduced/flattened lumbar lordosis and often reduced thoracic kyphosis."},{"id": 7099,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Palpation of muscle tone at rest helps assess for which condition?","options": [{"key": "A","text": "Bone density"},{"key": "B","text": "Joint alignment only"},{"key": "C","text": "Ligament integrity"},{"key": "D","text": "Hypertonia or hypotonia"}],"correct": "D","explanation": "Resting muscle palpation helps identify abnormal tone states such as hypertonia (spasticity/rigidity) or hypotonia (flaccidity)."},{"id": 7100,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "During gait, 'circumduction' of the lower limb during swing phase is a compensatory strategy commonly seen with:","options": [{"key": "A","text": "Excessive knee flexion during swing"},{"key": "B","text": "Strong ankle dorsiflexors"},{"key": "C","text": "Normal walking pattern"},{"key": "D","text": "Weak hip flexors or inadequate knee flexion (e.g., stiff knee gait)"}],"correct": "D","explanation": "Circumduction compensates for inadequate toe clearance, often from weak hip flexors, stiff knee gait, or foot drop, by swinging the limb outward."},{"id": 7101,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "'Vaulting' gait pattern is a compensation strategy typically used to accommodate:","options": [{"key": "A","text": "Hip flexor tightness only"},{"key": "B","text": "Weak quadriceps only"},{"key": "C","text": "A functionally longer contralateral limb during swing"},{"key": "D","text": "Normal limb length"}],"correct": "C","explanation": "Vaulting involves rising on the toes of the stance limb to allow the contralateral (often functionally longer) limb to clear the ground during swing."},{"id": 7102,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which cranial-to-caudal postural landmark alignment is expected in ideal standing posture (lateral view)?","options": [{"key": "A","text": "Hip anterior to shoulder"},{"key": "B","text": "Ear lobe anterior to shoulder only"},{"key": "C","text": "Ear lobe, shoulder, hip, knee, ankle roughly in one vertical line"},{"key": "D","text": "No consistent alignment expected"}],"correct": "C","explanation": "In ideal lateral standing alignment, the earlobe, shoulder, greater trochanter, slightly anterior to knee axis, and slightly anterior to lateral malleolus should form a roughly vertical line."},{"id": 7103,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "During MMT of the middle trapezius, the test position is typically:","options": [{"key": "A","text": "Sitting, arm overhead"},{"key": "B","text": "Prone, arm abducted to 90 degrees, elbow extended, thumb up"},{"key": "C","text": "Standing, arm behind back"},{"key": "D","text": "Supine, arm at side"}],"correct": "B","explanation": "Middle trapezius is tested prone with the shoulder abducted to 90 degrees and externally rotated (thumb pointing up), resisting horizontal abduction."},{"id": 7104,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which observation during gait assessment suggests quadriceps weakness?","options": [{"key": "A","text": "Vaulting"},{"key": "B","text": "Foot slap at initial contact"},{"key": "C","text": "Excessive knee flexion during stance"},{"key": "D","text": "Knee hyperextension (back-knee) thrust during stance"}],"correct": "D","explanation": "With quadriceps weakness, patients often compensate by locking the knee into hyperextension during stance to maintain stability, termed a 'back-knee' or genu recurvatum thrust."},{"id": 7105,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "A 'lateral trunk lean' (compensated Trendelenburg / Duchenne sign) toward the stance limb during gait suggests weakness of which muscle on the stance side?","options": [{"key": "A","text": "Gluteus medius"},{"key": "B","text": "Tibialis anterior"},{"key": "C","text": "Gluteus maximus"},{"key": "D","text": "Quadriceps"}],"correct": "A","explanation": "Leaning the trunk over the weak stance-side hip shifts the center of gravity to reduce the demand on a weak gluteus medius, called compensated Trendelenburg or Duchenne gait."},{"id": 7106,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which test position is used to assess passive insufficiency of the hamstrings?","options": [{"key": "A","text": "Faber test"},{"key": "B","text": "Straight leg raise with hip flexed and knee extended"},{"key": "C","text": "Ober's test"},{"key": "D","text": "Thomas test"}],"correct": "B","explanation": "Straight leg raise assesses hamstring flexibility/passive insufficiency by combining hip flexion with knee extension, stretching the two-joint hamstring muscle."},{"id": 7107,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Normal cervical spine rotation range (each side) is approximately:","options": [{"key": "A","text": "45 degrees"},{"key": "B","text": "110 degrees"},{"key": "C","text": "80 degrees"},{"key": "D","text": "20 degrees"}],"correct": "C","explanation": "Normal cervical rotation is approximately 80 degrees to each side."},{"id": 7108,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Normal lumbar spine flexion range is approximately:","options": [{"key": "A","text": "20 degrees"},{"key": "B","text": "120 degrees"},{"key": "C","text": "80-90 degrees"},{"key": "D","text": "40-60 degrees"}],"correct": "D","explanation": "Normal lumbar flexion range is approximately 40-60 degrees, though measurement methods vary."},{"id": 7109,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "The 'finger-to-floor' test is a functional assessment of:","options": [{"key": "A","text": "Cervical rotation"},{"key": "B","text": "Combined lumbar and hip flexion flexibility"},{"key": "C","text": "Ankle dorsiflexion"},{"key": "D","text": "Shoulder flexibility"}],"correct": "B","explanation": "The finger-to-floor test provides a gross functional measure combining lumbar spine and hip flexion mobility, though it lacks specificity."},{"id": 7110,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "During passive range of motion assessment, pain occurring before the end of available range most likely indicates:","options": [{"key": "A","text": "Muscle strength deficit"},{"key": "B","text": "Excessive joint mobility"},{"key": "C","text": "An acute or inflammatory condition limiting motion"},{"key": "D","text": "Normal physiological end-feel"}],"correct": "C","explanation": "Pain that limits motion before the normal anatomical end-range typically suggests acute inflammation, injury, or irritability rather than a mechanical/capsular restriction."},{"id": 7111,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Which of the following best defines 'active range of motion' (AROM)?","options": [{"key": "A","text": "Motion produced entirely by an external force"},{"key": "B","text": "Motion produced by the patient's own muscular effort"},{"key": "C","text": "Motion tested using resistance bands only"},{"key": "D","text": "Motion assessed only in supine"}],"correct": "B","explanation": "AROM is the range through which a joint moves using the patient's own voluntary muscle contraction, without external assistance."},{"id": 7112,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "'Passive range of motion' (PROM) is typically greater than AROM due to:","options": [{"key": "A","text": "Increased pain during PROM"},{"key": "B","text": "Decreased joint lubrication"},{"key": "C","text": "Increased muscle activation"},{"key": "D","text": "Additional stretch of periarticular tissues without muscular limitation"}],"correct": "D","explanation": "PROM often slightly exceeds AROM because the examiner can move the joint through the full available tissue extensibility without the limiting factor of active muscle control/strength."},{"id": 7113,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "A goniometric measurement showing greater PROM than AROM at a joint most likely suggests:","options": [{"key": "A","text": "Excessive capsular tightness"},{"key": "B","text": "Joint ankylosis"},{"key": "C","text": "Muscle weakness, pain inhibition, or neurological deficit limiting active motion"},{"key": "D","text": "Full muscle strength"}],"correct": "C","explanation": "A discrepancy where PROM exceeds AROM suggests factors limiting active movement such as muscle weakness, pain inhibition, or neurological involvement, while the joint itself has available passive range."},{"id": 7114,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Observation of scapular winging during a wall push-up test suggests weakness of which muscle?","options": [{"key": "A","text": "Rhomboids"},{"key": "B","text": "Trapezius (lower fibers)"},{"key": "C","text": "Deltoid"},{"key": "D","text": "Serratus anterior"}],"correct": "D","explanation": "Serratus anterior weakness classically causes medial scapular winging, most apparent when pushing against resistance (e.g., wall push-up test)."},{"id": 7115,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which is the correct sequence of the phases of stance in the Rancho Los Amigos gait model?","options": [{"key": "A","text": "Loading response, initial contact, terminal stance, mid stance"},{"key": "B","text": "Mid stance, initial contact, pre-swing, terminal stance"},{"key": "C","text": "Pre-swing, initial contact, loading response, mid stance"},{"key": "D","text": "Initial contact, loading response, mid stance, terminal stance, pre-swing"}],"correct": "D","explanation": "The correct stance phase sequence is initial contact, loading response, mid stance, terminal stance, and pre-swing."},{"id": 7116,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "The swing phase of gait is subdivided into which three parts?","options": [{"key": "A","text": "Initial swing, mid swing, terminal swing"},{"key": "B","text": "Initial contact, mid swing, terminal stance"},{"key": "C","text": "Pre-swing, mid swing, loading response"},{"key": "D","text": "Early swing, loading response, terminal swing"}],"correct": "A","explanation": "Swing phase consists of initial swing, mid swing, and terminal swing."},{"id": 7117,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which observational gait deviation is associated with hip flexor weakness during swing phase?","options": [{"key": "A","text": "Vaulting"},{"key": "B","text": "Foot slap"},{"key": "C","text": "Genu recurvatum"},{"key": "D","text": "Excessive trunk extension to advance the limb (hip hiking or circumduction)"}],"correct": "D","explanation": "Weak hip flexors may cause compensations such as circumduction, hip hiking, or backward trunk lean to help advance the swinging limb."},{"id": 7118,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "The normal walking base of support (distance between the two feet) is approximately:","options": [{"key": "A","text": "0-2 inches (5-10 cm)"},{"key": "B","text": "15 inches"},{"key": "C","text": "10-12 inches"},{"key": "D","text": "6-8 inches"}],"correct": "A","explanation": "Normal walking base width is narrow, approximately 5-10 cm (2-4 inches), commonly cited as 0-2 inches at the heels in some texts."},{"id": 7119,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "During postural assessment from behind, an elevated shoulder on one side may indicate:","options": [{"key": "A","text": "Possible scoliosis, muscle imbalance, or leg length discrepancy"},{"key": "B","text": "Cervical disc herniation exclusively"},{"key": "C","text": "Normal variant only, always insignificant"},{"key": "D","text": "Ankle instability"}],"correct": "A","explanation": "Asymmetric shoulder height can be associated with scoliosis, muscular imbalance (e.g., upper trapezius tightness), or leg length discrepancy, warranting further evaluation."},{"id": 7120,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "A 'positive' finding of increased lumbar lordosis on postural screening is often associated with tightness of which muscle group?","options": [{"key": "A","text": "Hip flexors and lumbar erector spinae"},{"key": "B","text": "Hamstrings and gluteals"},{"key": "C","text": "Hip abductors"},{"key": "D","text": "Abdominals"}],"correct": "A","explanation": "Increased lumbar lordosis is commonly associated with tight hip flexors (iliopsoas) and lumbar erector spinae, along with weak abdominals."},{"id": 7121,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which term describes limited joint motion due to pain, without true mechanical restriction?","options": [{"key": "A","text": "Ankylosis"},{"key": "B","text": "Functional limitation (pain-guarded motion)"},{"key": "C","text": "Contracture"},{"key": "D","text": "Hypermobility"}],"correct": "B","explanation": "Pain-guarded or functionally limited motion occurs when the patient restricts movement due to pain despite the joint having potential mechanical range available."},{"id": 7122,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "During assessment of active shoulder abduction, a 'painful arc' between 60-120 degrees is most suggestive of:","options": [{"key": "A","text": "Acromioclavicular joint pathology"},{"key": "B","text": "Glenohumeral instability"},{"key": "C","text": "Subacromial impingement (supraspinatus/rotator cuff)"},{"key": "D","text": "Cervical radiculopathy"}],"correct": "C","explanation": "A painful arc in the mid-range of abduction (60-120°) classically indicates subacromial impingement involving the supraspinatus tendon."},{"id": 7123,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "Pain occurring at the extreme of shoulder abduction (above 170 degrees) is more suggestive of:","options": [{"key": "A","text": "Rotator cuff tear"},{"key": "B","text": "Acromioclavicular joint pathology"},{"key": "C","text": "Bicipital tendinopathy"},{"key": "D","text": "Subacromial impingement"}],"correct": "B","explanation": "Pain specifically at the top of full overhead abduction often points to acromioclavicular joint involvement rather than mid-range impingement."},{"id": 7124,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "MMT grade 5/5 (Normal) is defined as the ability to move through full ROM against gravity with:","options": [{"key": "A","text": "Maximal resistance appropriate for that muscle group"},{"key": "B","text": "Moderate resistance only"},{"key": "C","text": "Only gravity-eliminated positions"},{"key": "D","text": "No resistance tolerated"}],"correct": "A","explanation": "Grade 5 (Normal) indicates the muscle can move through the full available range against gravity and tolerate maximal resistance appropriate to the individual's age and body type."},{"id": 7125,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "In goniometry, the 'moving arm' of the instrument is aligned with:","options": [{"key": "A","text": "The distal, moving body segment"},{"key": "B","text": "The joint axis itself"},{"key": "C","text": "The examiner's forearm"},{"key": "D","text": "The proximal (stationary) body segment"}],"correct": "A","explanation": "The moving arm of a goniometer follows the distal segment that moves during the joint motion being measured."},{"id": 7126,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "Which of the following describes a 'springy block' end-feel and is considered abnormal/pathological?","options": [{"key": "A","text": "Indicates full muscle strength"},{"key": "B","text": "Normal elbow flexion end-feel"},{"key": "C","text": "Normal knee extension end-feel"},{"key": "D","text": "Suggests a loose fragment within the joint (e.g., meniscal tear) blocking full motion"}],"correct": "D","explanation": "A springy block end-feel, with a rebound sensation, suggests an internal derangement such as a loose body or meniscal fragment blocking full range."},{"id": 7127,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Assessing 'accessory motion' (joint play) is important because:","options": [{"key": "A","text": "It has no clinical relevance"},{"key": "B","text": "It reflects involuntary component motions necessary for normal physiological movement"},{"key": "C","text": "It reflects voluntary muscle-produced movement"},{"key": "D","text": "It only applies to the spine"}],"correct": "B","explanation": "Accessory (joint play) motions are small involuntary movements essential for normal physiological joint motion and are assessed to detect capsular or articular restrictions."},{"id": 7128,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "The 'concave-convex rule' in arthrokinematics states that when a concave surface moves on a fixed convex surface, roll and glide occur:","options": [{"key": "A","text": "In the same direction"},{"key": "B","text": "Only rolling occurs, no gliding"},{"key": "C","text": "In opposite directions"},{"key": "D","text": "Only gliding occurs, no rolling"}],"correct": "A","explanation": "When a concave surface moves on a stationary convex surface, roll and glide occur in the same direction (e.g., tibial plateau on femoral condyle during knee flexion in open chain)."},{"id": 7129,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "According to the concave-convex rule, when a convex surface moves on a fixed concave surface, roll and glide occur:","options": [{"key": "A","text": "Simultaneously with no distinction"},{"key": "B","text": "Neither roll nor glide occurs"},{"key": "C","text": "In the same direction"},{"key": "D","text": "In opposite directions"}],"correct": "D","explanation": "When a convex surface moves on a fixed concave surface (e.g., humeral head on glenoid during arm elevation), roll and glide occur in opposite directions."},{"id": 7130,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Observation of an increased thoracic kyphosis with compensatory cervical hyperextension (forward head posture) is commonly termed:","options": [{"key": "A","text": "Lower crossed syndrome"},{"key": "B","text": "Upper crossed syndrome pattern"},{"key": "C","text": "Swayback posture only"},{"key": "D","text": "Flat back posture"}],"correct": "B","explanation": "This pattern of forward head, rounded shoulders, and increased thoracic kyphosis with compensatory cervical extension is described as upper crossed syndrome (Janda)."},{"id": 7131,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "'Lower crossed syndrome' typically involves tightness of which muscle groups?","options": [{"key": "A","text": "Pectorals only"},{"key": "B","text": "Hip flexors and lumbar erector spinae, with weak gluteals and abdominals"},{"key": "C","text": "Upper trapezius and levator scapulae only"},{"key": "D","text": "Hamstrings and gluteals, with weak hip flexors"}],"correct": "B","explanation": "Lower crossed syndrome (Janda) describes tight hip flexors and lumbar extensors combined with weak gluteus maximus and abdominal muscles, producing anterior pelvic tilt."},{"id": 7132,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which observation is characteristic of a 'Trendelenburg sign' during single-leg stance?","options": [{"key": "A","text": "Pelvic elevation on the stance side"},{"key": "B","text": "No change in pelvic position"},{"key": "C","text": "Ipsilateral pelvic drop on the stance side"},{"key": "D","text": "Contralateral pelvic drop (opposite to stance leg)"}],"correct": "D","explanation": "A positive Trendelenburg sign shows the pelvis dropping on the side opposite (contralateral) to the weight-bearing stance limb due to weak ipsilateral hip abductors."},{"id": 7133,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "Which functional outcome measure specifically assesses lower extremity function through timed sit-to-stand repetitions?","options": [{"key": "A","text": "Berg Balance Scale"},{"key": "B","text": "Tinetti Scale"},{"key": "C","text": "30-second Sit-to-Stand Test"},{"key": "D","text": "Functional Reach Test"}],"correct": "C","explanation": "The 30-second Sit-to-Stand test counts repetitions completed in 30 seconds, assessing lower extremity strength and functional power."},{"id": 7134,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "The 'Functional Reach Test' measures:","options": [{"key": "A","text": "Maximum distance a person can reach forward without losing balance/moving feet"},{"key": "B","text": "Range of shoulder motion"},{"key": "C","text": "Grip strength"},{"key": "D","text": "Gait speed"}],"correct": "A","explanation": "Functional Reach measures the maximal distance one can reach forward beyond arm's length while maintaining a fixed base of support, assessing dynamic balance."},{"id": 7135,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Medium","question": "A patient unable to actively extend the wrist but with full passive extension available most likely has weakness of:","options": [{"key": "A","text": "Wrist flexors"},{"key": "B","text": "Wrist extensors (e.g., radial nerve involvement)"},{"key": "C","text": "Finger flexors"},{"key": "D","text": "Thumb opposition muscles"}],"correct": "B","explanation": "Active-passive ROM discrepancy pointing to wrist extension suggests wrist extensor weakness, often seen in radial nerve palsy (wrist drop)."},{"id": 7136,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Easy","question": "Palpation for muscle guarding/spasm is best performed with the patient in a position that:","options": [{"key": "A","text": "Actively contracts the muscle"},{"key": "B","text": "Maximally stretches the muscle"},{"key": "C","text": "Allows relaxation of the muscle being palpated"},{"key": "D","text": "Is always standing"}],"correct": "C","explanation": "Muscle palpation for guarding or spasm is best done with the area relaxed and appropriately supported to avoid confounding voluntary contraction."},{"id": 7137,"subject": "Clinical Skills","topic": "Clinical Examination","difficulty": "Hard","question": "During observation of gait from behind, excessive pronation of the foot during stance may contribute to:","options": [{"key": "A","text": "Decreased stress on medial structures"},{"key": "B","text": "Improved shock absorption only, with no downside"},{"key": "C","text": "No effect on proximal joints"},{"key": "D","text": "Increased medial knee stress and dynamic valgus"}],"correct": "D","explanation": "Excessive foot pronation can create a kinetic chain effect, increasing internal tibial rotation and contributing to dynamic knee valgus and medial stress."},{"id": 7138,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The Neer's impingement test is performed by:","options": [{"key": "A","text": "Resisted external rotation at 0 degrees abduction"},{"key": "B","text": "Active abduction against resistance at 90 degrees"},{"key": "C","text": "Passive extension of the shoulder"},{"key": "D","text": "Passive full flexion/elevation of the shoulder with internal rotation while stabilizing the scapula"}],"correct": "D","explanation": "Neer's test involves passive forward elevation of the internally rotated arm, compressing the greater tuberosity against the acromion, reproducing impingement pain."},{"id": 7139,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The Hawkins-Kennedy test is performed with the shoulder and elbow flexed to 90 degrees, followed by:","options": [{"key": "A","text": "Passive external rotation"},{"key": "B","text": "Passive horizontal abduction"},{"key": "C","text": "Passive internal rotation of the shoulder"},{"key": "D","text": "Resisted abduction"}],"correct": "C","explanation": "Hawkins-Kennedy test involves passive internal rotation of the forward-flexed shoulder, compressing the supraspinatus tendon under the coracoacromial arch."},{"id": 7140,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The 'empty can' (Jobe's) test primarily assesses which muscle?","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Infraspinatus"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "The empty can test, with the arm abducted, forward flexed 30 degrees, and internally rotated (thumb down), isolates and tests supraspinatus strength/integrity."},{"id": 7141,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'lift-off test' (Gerber's test) primarily assesses integrity of which rotator cuff muscle?","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Infraspinatus"},{"key": "C","text": "Supraspinatus"},{"key": "D","text": "Teres minor"}],"correct": "A","explanation": "The lift-off test, where the patient lifts the hand off the lower back, assesses subscapularis function/integrity."},{"id": 7142,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'belly press test' is an alternative to which test when the lift-off test cannot be performed?","options": [{"key": "A","text": "Speed's test"},{"key": "B","text": "Sulcus sign"},{"key": "C","text": "Lift-off test (subscapularis assessment)"},{"key": "D","text": "Apprehension test"}],"correct": "C","explanation": "The belly press test is used as an alternative to assess subscapularis when patients cannot achieve the internal rotation position required for the lift-off test."},{"id": 7143,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The 'drop arm test' is used to assess for:","options": [{"key": "A","text": "Shoulder instability"},{"key": "B","text": "Large rotator cuff tear (especially supraspinatus)"},{"key": "C","text": "Biceps tendon rupture"},{"key": "D","text": "AC joint pathology"}],"correct": "B","explanation": "The drop arm test detects significant rotator cuff tear; the patient is unable to slowly lower the arm from abduction, and it drops suddenly."},{"id": 7144,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Speed's test primarily assesses pathology of which structure?","options": [{"key": "A","text": "Supraspinatus tendon"},{"key": "B","text": "Glenoid labrum posteriorly"},{"key": "C","text": "Long head of biceps tendon"},{"key": "D","text": "AC joint"}],"correct": "C","explanation": "Speed's test involves resisted shoulder flexion with the elbow extended and forearm supinated, provoking pain in bicipital tendinopathy."},{"id": 7145,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Yergason's test is used to assess for:","options": [{"key": "A","text": "SLAP lesion primarily"},{"key": "B","text": "Rotator cuff tear"},{"key": "C","text": "Bicipital tendinopathy/instability"},{"key": "D","text": "AC joint separation"}],"correct": "C","explanation": "Yergason's test involves resisted forearm supination with the elbow flexed to 90 degrees, testing for biceps tendon pathology/instability in the bicipital groove."},{"id": 7146,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'sulcus sign' is used to assess for:","options": [{"key": "A","text": "Posterior labral tear"},{"key": "B","text": "Inferior glenohumeral instability"},{"key": "C","text": "Anterior shoulder instability"},{"key": "D","text": "AC joint arthritis"}],"correct": "B","explanation": "A positive sulcus sign, seen as a gap below the acromion with inferior traction on the arm, indicates inferior glenohumeral laxity/instability."},{"id": 7147,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The apprehension test for the shoulder assesses for:","options": [{"key": "A","text": "Rotator cuff tear"},{"key": "B","text": "Superior labral tear"},{"key": "C","text": "Anterior instability"},{"key": "D","text": "Posterior instability"}],"correct": "C","explanation": "The apprehension test, performed with the shoulder abducted and externally rotated, provokes a feeling of impending dislocation in anterior instability."},{"id": 7148,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "A positive relocation test (following a positive apprehension test) confirms:","options": [{"key": "A","text": "Frozen shoulder"},{"key": "B","text": "AC joint arthritis"},{"key": "C","text": "Rotator cuff pathology"},{"key": "D","text": "Anterior glenohumeral instability"}],"correct": "D","explanation": "Relief of apprehension with a posteriorly directed force (relocation test) confirms anterior instability as the cause of symptoms."},{"id": 7149,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The O'Brien's (active compression) test is primarily used to detect:","options": [{"key": "A","text": "SLAP lesion (superior labral tear)"},{"key": "B","text": "Rotator cuff tear"},{"key": "C","text": "Bicipital tendon rupture"},{"key": "D","text": "AC joint separation only"}],"correct": "A","explanation": "O'Brien's test helps identify SLAP lesions and can also indicate AC joint pathology depending on pain location."},{"id": 7150,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The cross-body (horizontal) adduction test primarily assesses:","options": [{"key": "A","text": "Long head of biceps"},{"key": "B","text": "Rotator cuff strength"},{"key": "C","text": "AC joint pathology"},{"key": "D","text": "Glenohumeral instability"}],"correct": "C","explanation": "The cross-body adduction test compresses the AC joint, reproducing localized pain in AC joint pathology."},{"id": 7151,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Cozen's test is used to diagnose:","options": [{"key": "A","text": "Medial epicondylitis (golfer's elbow)"},{"key": "B","text": "Cubital tunnel syndrome"},{"key": "C","text": "Lateral epicondylitis (tennis elbow)"},{"key": "D","text": "Radial tunnel syndrome"}],"correct": "C","explanation": "Cozen's test involves resisted wrist extension with the elbow extended, reproducing pain at the lateral epicondyle in lateral epicondylitis."},{"id": 7152,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'golfer's elbow test' (resisted wrist flexion with elbow extended) assesses for:","options": [{"key": "A","text": "Medial epicondylitis"},{"key": "B","text": "Lateral epicondylitis"},{"key": "C","text": "Cubital tunnel syndrome"},{"key": "D","text": "Ulnar collateral ligament tear"}],"correct": "A","explanation": "Resisted wrist flexion/pronation with the elbow extended provokes pain at the medial epicondyle in medial epicondylitis (golfer's elbow)."},{"id": 7153,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "Tinel's sign at the elbow (percussion over the cubital tunnel) tests for irritability of which nerve?","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "B","explanation": "Tapping over the cubital tunnel at the medial elbow reproduces tingling in ulnar nerve distribution when the nerve is irritated/compressed."},{"id": 7154,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The 'moving valgus stress test' at the elbow assesses integrity of which structure?","options": [{"key": "A","text": "Lateral collateral ligament"},{"key": "B","text": "Interosseous membrane"},{"key": "C","text": "Ulnar (medial) collateral ligament"},{"key": "D","text": "Annular ligament"}],"correct": "C","explanation": "This dynamic test assesses ulnar collateral ligament integrity, commonly used in throwing athletes with medial elbow instability."},{"id": 7155,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "Phalen's test is used to assess for:","options": [{"key": "A","text": "Cubital tunnel syndrome"},{"key": "B","text": "De Quervain's tenosynovitis"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "Guyon's canal syndrome"}],"correct": "C","explanation": "Phalen's test involves sustained wrist flexion for 60 seconds, reproducing median nerve symptoms (numbness/tingling) in carpal tunnel syndrome."},{"id": 7156,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "Tinel's sign at the wrist tests for irritability of which nerve in suspected carpal tunnel syndrome?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Posterior interosseous nerve"}],"correct": "C","explanation": "Percussion over the carpal tunnel reproducing tingling in the median nerve distribution supports a diagnosis of carpal tunnel syndrome."},{"id": 7157,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "Finkelstein's test is used to diagnose:","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "Trigger finger"},{"key": "C","text": "Dupuytren's contracture"},{"key": "D","text": "De Quervain's tenosynovitis"}],"correct": "D","explanation": "Finkelstein's test involves ulnar deviation of the wrist with the thumb tucked into a fist, provoking pain over the first dorsal compartment in De Quervain's tenosynovitis."},{"id": 7158,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The 'Watson (scaphoid shift) test' assesses for instability of which joint?","options": [{"key": "A","text": "Distal radioulnar joint"},{"key": "B","text": "Scapholunate joint"},{"key": "C","text": "Radiocarpal joint"},{"key": "D","text": "Triquetrolunate joint"}],"correct": "B","explanation": "The Watson test detects scapholunate instability by applying dorsal pressure on the scaphoid tubercle during radial-to-ulnar wrist deviation, feeling for a clunk."},{"id": 7159,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Which test is used to assess the integrity of the ulnar collateral ligament of the thumb MCP joint (gamekeeper's/skier's thumb)?","options": [{"key": "A","text": "Valgus stress test at thumb MCP joint"},{"key": "B","text": "Bunnel-Littler test"},{"key": "C","text": "Phalen's test"},{"key": "D","text": "Finkelstein's test"}],"correct": "A","explanation": "Applying a valgus (radial) stress to the thumb MCP joint tests the ulnar collateral ligament, commonly injured in skier's/gamekeeper's thumb."},{"id": 7160,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The Thomas test is used to assess for tightness of which muscle?","options": [{"key": "A","text": "Piriformis"},{"key": "B","text": "Hamstrings"},{"key": "C","text": "Gluteus medius"},{"key": "D","text": "Hip flexors (iliopsoas, rectus femoris)"}],"correct": "D","explanation": "The Thomas test detects hip flexor tightness by observing compensatory hip flexion of the tested leg when the contralateral hip is maximally flexed to flatten the lumbar spine."},{"id": 7161,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "Ober's test is used to assess tightness of which structure?","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Adductors"},{"key": "C","text": "Iliotibial band/tensor fasciae latae"},{"key": "D","text": "Hamstrings"}],"correct": "C","explanation": "Ober's test assesses IT band and TFL tightness by observing whether the abducted leg can adduct past neutral (positive test = leg remains abducted)."},{"id": 7162,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The FABER (Patrick's) test stands for:","options": [{"key": "A","text": "Flexion, Abduction, External Rotation"},{"key": "B","text": "Flexion, Adduction, External Rotation"},{"key": "C","text": "Flexion, Abduction, Extension, Rotation"},{"key": "D","text": "Full Abduction, External Rotation"}],"correct": "A","explanation": "FABER stands for Flexion, ABduction, External Rotation, used to screen for hip, sacroiliac, or lumbar pathology."},{"id": 7163,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "A positive FABER test with pain localized to the SI joint suggests:","options": [{"key": "A","text": "Lumbar disc herniation"},{"key": "B","text": "Sacroiliac joint dysfunction"},{"key": "C","text": "Femoral nerve irritation"},{"key": "D","text": "Hip joint pathology"}],"correct": "B","explanation": "Pain specifically at the SI joint during the FABER test suggests sacroiliac joint dysfunction, while groin pain suggests hip pathology."},{"id": 7164,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The Trendelenburg test assesses the function of which muscle?","options": [{"key": "A","text": "Gluteus medius"},{"key": "B","text": "Piriformis"},{"key": "C","text": "Iliopsoas"},{"key": "D","text": "Gluteus maximus"}],"correct": "A","explanation": "The Trendelenburg test evaluates gluteus medius strength/function by observing pelvic control during single-leg stance."},{"id": 7165,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The scour (quadrant) test of the hip is used to detect:","options": [{"key": "A","text": "SI joint dysfunction"},{"key": "B","text": "Femoral nerve entrapment"},{"key": "C","text": "Piriformis syndrome"},{"key": "D","text": "Hip labral or chondral pathology"}],"correct": "D","explanation": "The hip scour test, combining compression with circular hip motion in flexion, helps identify intra-articular pathology such as labral tears or chondral lesions."},{"id": 7166,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The Lachman test primarily assesses integrity of which knee ligament?","options": [{"key": "A","text": "LCL"},{"key": "B","text": "PCL"},{"key": "C","text": "ACL"},{"key": "D","text": "MCL"}],"correct": "C","explanation": "The Lachman test, performed with the knee at 20-30 degrees flexion, is the most sensitive clinical test for ACL integrity."},{"id": 7167,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The anterior drawer test of the knee assesses for laxity of which structure?","options": [{"key": "A","text": "Meniscus"},{"key": "B","text": "MCL"},{"key": "C","text": "PCL"},{"key": "D","text": "ACL"}],"correct": "D","explanation": "The anterior drawer test, with the knee flexed to 90 degrees, assesses anterior tibial translation indicating ACL insufficiency."},{"id": 7168,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The posterior drawer test of the knee primarily assesses for laxity of:","options": [{"key": "A","text": "LCL"},{"key": "B","text": "MCL"},{"key": "C","text": "ACL"},{"key": "D","text": "PCL"}],"correct": "D","explanation": "The posterior drawer test detects posterior tibial translation indicating PCL insufficiency."},{"id": 7169,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "A 'posterior sag sign' at the knee is indicative of:","options": [{"key": "A","text": "Meniscal tear"},{"key": "B","text": "ACL deficiency"},{"key": "C","text": "PCL deficiency"},{"key": "D","text": "MCL sprain"}],"correct": "C","explanation": "With the hip and knee flexed, gravity causes the tibia to sag posteriorly relative to the femur when the PCL is deficient — the posterior sag sign."},{"id": 7170,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The McMurray test is primarily used to detect:","options": [{"key": "A","text": "Meniscal tears"},{"key": "B","text": "Collateral ligament sprain"},{"key": "C","text": "Patellar instability"},{"key": "D","text": "ACL tears"}],"correct": "A","explanation": "McMurray's test combines knee flexion with tibial rotation and varus/valgus stress, eliciting a palpable/audible click or pain with meniscal tears."},{"id": 7171,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The Apley compression test assesses for pathology of which structure, differentiated from the Apley distraction test which assesses ligaments?","options": [{"key": "A","text": "ACL only"},{"key": "B","text": "Meniscus (compression) vs ligaments (distraction)"},{"key": "C","text": "PCL only"},{"key": "D","text": "Patellar tendon"}],"correct": "B","explanation": "Apley's compression test loads the meniscus (compression + rotation reproduces meniscal pain), while distraction unloads the meniscus and stresses the ligaments instead."},{"id": 7172,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The valgus stress test of the knee (performed at 0 and 30 degrees flexion) primarily assesses:","options": [{"key": "A","text": "ACL"},{"key": "B","text": "MCL"},{"key": "C","text": "LCL"},{"key": "D","text": "PCL"}],"correct": "B","explanation": "Valgus stress testing assesses medial collateral ligament integrity; laxity at 30 degrees suggests isolated MCL injury, while laxity at 0 degrees suggests combined ligament/capsular injury."},{"id": 7173,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The varus stress test of the knee primarily assesses integrity of:","options": [{"key": "A","text": "PCL"},{"key": "B","text": "ACL"},{"key": "C","text": "LCL"},{"key": "D","text": "MCL"}],"correct": "C","explanation": "Varus stress testing assesses the lateral collateral ligament for laxity."},{"id": 7174,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The patellar apprehension test is used to assess for:","options": [{"key": "A","text": "Meniscal tear"},{"key": "B","text": "ACL laxity"},{"key": "C","text": "Patellofemoral instability/subluxation risk"},{"key": "D","text": "Quadriceps tendon rupture"}],"correct": "C","explanation": "This test involves laterally displacing the patella; apprehension or guarding suggests a history/risk of patellar instability or subluxation."},{"id": 7175,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Clarke's sign (patellar grind test) is used to assess for:","options": [{"key": "A","text": "Patellofemoral pain/chondromalacia patellae"},{"key": "B","text": "Popliteal cyst"},{"key": "C","text": "Meniscal tear"},{"key": "D","text": "ACL tear"}],"correct": "A","explanation": "Clarke's sign involves compressing the patella against the femoral trochlea during quadriceps contraction, reproducing anterior knee pain in patellofemoral dysfunction."},{"id": 7176,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The 'dial test' of the knee, performed at 30 and 90 degrees flexion, primarily assesses for:","options": [{"key": "A","text": "Isolated ACL injury"},{"key": "B","text": "Isolated MCL injury"},{"key": "C","text": "Patellar maltracking"},{"key": "D","text": "Posterolateral corner injury/rotational instability"}],"correct": "D","explanation": "Excessive external rotation of the tibia relative to the femur (dial test) at 30 degrees suggests posterolateral corner injury; involvement at both 30 and 90 degrees suggests combined PCL/PLC injury."},{"id": 7177,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The anterior drawer test of the ankle primarily assesses integrity of which ligament?","options": [{"key": "A","text": "Anterior talofibular ligament"},{"key": "B","text": "Deltoid ligament"},{"key": "C","text": "Calcaneofibular ligament"},{"key": "D","text": "Posterior talofibular ligament"}],"correct": "A","explanation": "The ankle anterior drawer test assesses anterior talofibular ligament laxity, most commonly injured in inversion ankle sprains."},{"id": 7178,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The talar tilt test primarily assesses integrity of which ankle ligament?","options": [{"key": "A","text": "Deltoid ligament"},{"key": "B","text": "Calcaneofibular ligament"},{"key": "C","text": "Anterior talofibular ligament"},{"key": "D","text": "Posterior tibiofibular ligament"}],"correct": "B","explanation": "The talar tilt (inversion stress) test primarily assesses calcaneofibular ligament integrity."},{"id": 7179,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The Thompson test (squeeze test) is used to assess for rupture of which structure?","options": [{"key": "A","text": "Posterior tibial tendon"},{"key": "B","text": "Peroneal tendons"},{"key": "C","text": "Achilles tendon"},{"key": "D","text": "Plantar fascia"}],"correct": "C","explanation": "Squeezing the calf while prone with the foot hanging free; absence of plantarflexion indicates a positive test for Achilles tendon rupture."},{"id": 7180,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'squeeze test' at the ankle/leg (compressing tibia and fibula together at mid-calf) is used to assess for:","options": [{"key": "A","text": "Lateral ankle sprain"},{"key": "B","text": "Stress fracture of calcaneus"},{"key": "C","text": "Achilles tendon rupture"},{"key": "D","text": "High ankle sprain (syndesmotic injury)"}],"correct": "D","explanation": "The squeeze test compresses the tibia and fibula, and pain at the syndesmosis (distal tibiofibular joint) indicates a high ankle sprain."},{"id": 7181,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Which test involves external rotation of the foot with the knee flexed to assess syndesmotic ankle injury?","options": [{"key": "A","text": "Thompson test"},{"key": "B","text": "Anterior drawer test"},{"key": "C","text": "Kleiger's (external rotation) test"},{"key": "D","text": "Talar tilt test"}],"correct": "C","explanation": "Kleiger's test applies external rotation to the foot/ankle to stress the syndesmosis and deltoid ligament, reproducing pain in syndesmotic injuries."},{"id": 7182,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The Tinel's sign at the ankle, tested over the tarsal tunnel, assesses irritability of which nerve?","options": [{"key": "A","text": "Posterior tibial nerve"},{"key": "B","text": "Superficial peroneal nerve"},{"key": "C","text": "Deep peroneal nerve"},{"key": "D","text": "Sural nerve"}],"correct": "A","explanation": "Percussion over the tarsal tunnel behind the medial malleolus reproduces symptoms along the posterior tibial nerve distribution in tarsal tunnel syndrome."},{"id": 7183,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The Straight Leg Raise (SLR) test is primarily used to screen for:","options": [{"key": "A","text": "SI joint dysfunction only"},{"key": "B","text": "Hip joint pathology"},{"key": "C","text": "Lumbar disc herniation/nerve root tension (sciatica)"},{"key": "D","text": "Knee ligament laxity"}],"correct": "C","explanation": "SLR reproduces radicular leg pain by placing tension on the sciatic nerve roots, commonly used to screen for lumbar disc herniation."},{"id": 7184,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "A positive SLR test typically reproduces symptoms between which range of hip flexion?","options": [{"key": "A","text": "90-120 degrees"},{"key": "B","text": "0-30 degrees"},{"key": "C","text": "30-70 degrees"},{"key": "D","text": "120-150 degrees"}],"correct": "C","explanation": "Nerve root tension signs during SLR are most specific when symptoms are reproduced between approximately 30-70 degrees of hip flexion."},{"id": 7185,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The crossed straight leg raise test is considered positive when raising the unaffected leg reproduces symptoms in the affected leg, and is highly specific for:","options": [{"key": "A","text": "Hamstring tightness"},{"key": "B","text": "Large central disc herniation"},{"key": "C","text": "Piriformis syndrome"},{"key": "D","text": "SI joint dysfunction"}],"correct": "B","explanation": "A positive crossed SLR (reproducing contralateral leg symptoms) is highly specific, though less sensitive, for lumbar disc herniation, often a large central protrusion."},{"id": 7186,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The slump test is a neurodynamic test primarily used to assess tension on:","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Sciatic nerve and neuromeningeal structures"},{"key": "D","text": "Femoral nerve"}],"correct": "C","explanation": "The slump test combines cervical flexion, thoracolumbar flexion, knee extension, and ankle dorsiflexion to place tension along the neuromeningeal tract and sciatic nerve."},{"id": 7187,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The femoral nerve stretch test (prone knee bend) is primarily used to assess for pathology at which lumbar level?","options": [{"key": "A","text": "No specific level correlation"},{"key": "B","text": "L2-L4 nerve roots"},{"key": "C","text": "L4-S1 nerve roots"},{"key": "D","text": "S1-S2 nerve roots"}],"correct": "B","explanation": "The femoral nerve stretch test, performed prone with hip extension and knee flexion, stresses the upper lumbar nerve roots (L2-L4), relevant to femoral nerve/upper lumbar disc pathology."},{"id": 7188,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "Spurling's test is used to assess for:","options": [{"key": "A","text": "Thoracic outlet syndrome"},{"key": "B","text": "Cervical radiculopathy"},{"key": "C","text": "Lumbar radiculopathy"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "B","explanation": "Spurling's test combines cervical extension, lateral flexion, and axial compression toward the symptomatic side to reproduce cervical nerve root compression symptoms."},{"id": 7189,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The distraction test of the cervical spine, which relieves symptoms when positive, is used to assess for:","options": [{"key": "A","text": "Thoracic outlet syndrome"},{"key": "B","text": "Vertebral artery insufficiency"},{"key": "C","text": "Torticollis"},{"key": "D","text": "Cervical radiculopathy relief with traction"}],"correct": "D","explanation": "Cervical distraction, applying gentle traction, relieves radicular symptoms when nerve root compression is the source, supporting a diagnosis of cervical radiculopathy."},{"id": 7190,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The vertebral artery test of the cervical spine is performed to screen for:","options": [{"key": "A","text": "Disc herniation"},{"key": "B","text": "Vertebrobasilar insufficiency prior to manipulation"},{"key": "C","text": "Rotator cuff pathology"},{"key": "D","text": "Nerve root compression"}],"correct": "B","explanation": "This test sustains cervical rotation and extension to provoke symptoms of vertebrobasilar insufficiency before performing cervical manipulation techniques, as a safety screen."},{"id": 7191,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Adson's test is used in the assessment of:","options": [{"key": "A","text": "Cubital tunnel syndrome"},{"key": "B","text": "Thoracic outlet syndrome"},{"key": "C","text": "Cervical radiculopathy"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "B","explanation": "Adson's test involves neck extension/rotation with deep inspiration while palpating the radial pulse, assessing for compression at the scalene triangle in thoracic outlet syndrome."},{"id": 7192,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Roos test (EAST - Elevated Arm Stress Test) is used to assess for:","options": [{"key": "A","text": "Thoracic outlet syndrome"},{"key": "B","text": "Cervical myelopathy"},{"key": "C","text": "Rotator cuff tear"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "A","explanation": "The Roos/EAST test involves sustained shoulder abduction and external rotation with repetitive hand opening/closing for 3 minutes, provoking symptoms in thoracic outlet syndrome."},{"id": 7193,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "Wright's test (hyperabduction test) assesses thoracic outlet syndrome by:","options": [{"key": "A","text": "Assessing ulnar nerve mobility"},{"key": "B","text": "Testing radial nerve entrapment at the elbow"},{"key": "C","text": "Compressing the neurovascular bundle beneath pectoralis minor with shoulder hyperabduction"},{"key": "D","text": "Compressing the carpal tunnel"}],"correct": "C","explanation": "Wright's test hyperabducts the shoulder, compressing the neurovascular bundle under pectoralis minor, provoking symptoms in thoracic outlet syndrome."},{"id": 7194,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "The 'Faber test' is also known as which eponym?","options": [{"key": "A","text": "Craig's test"},{"key": "B","text": "Patrick's test"},{"key": "C","text": "Ober's test"},{"key": "D","text": "Thomas test"}],"correct": "B","explanation": "The FABER test is also called Patrick's test, named after the physician who described it."},{"id": 7195,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'piriformis test (FAIR test)' places the hip in which position to stress the piriformis?","options": [{"key": "A","text": "Extension, Adduction, External Rotation"},{"key": "B","text": "Flexion, Adduction, Internal Rotation"},{"key": "C","text": "Flexion, Abduction, External Rotation"},{"key": "D","text": "Extension, Abduction, Internal Rotation"}],"correct": "B","explanation": "FAIR stands for Flexion, ADduction, Internal Rotation of the hip, a position that stretches and compresses the piriformis, reproducing sciatic-like symptoms in piriformis syndrome."},{"id": 7196,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Ely's test is used to assess tightness of which muscle?","options": [{"key": "A","text": "Gluteus maximus"},{"key": "B","text": "Rectus femoris"},{"key": "C","text": "Hamstrings"},{"key": "D","text": "Adductors"}],"correct": "B","explanation": "Ely's test, performed prone with passive knee flexion, is positive (hip rises off the table) when the rectus femoris is tight."},{"id": 7197,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 90-90 straight leg raise test (passive knee extension test) is used to assess flexibility of which muscle group?","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Hamstrings"},{"key": "C","text": "Quadriceps"},{"key": "D","text": "Adductors"}],"correct": "B","explanation": "With the hip flexed to 90 degrees, passive knee extension assesses hamstring flexibility (popliteal angle measurement)."},{"id": 7198,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The Craig's test is used to measure:","options": [{"key": "A","text": "Leg length discrepancy"},{"key": "B","text": "Tibial torsion"},{"key": "C","text": "Femoral anteversion"},{"key": "D","text": "Q angle"}],"correct": "C","explanation": "Craig's test estimates the degree of femoral anteversion by palpating the greater trochanter's most prominent position during hip internal/external rotation, prone with knee flexed."},{"id": 7199,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The pivot shift test is a dynamic test used to assess for:","options": [{"key": "A","text": "Rotational instability associated with ACL deficiency"},{"key": "B","text": "Patellar instability"},{"key": "C","text": "Isolated MCL laxity"},{"key": "D","text": "Meniscal tear only"}],"correct": "A","explanation": "The pivot shift test reproduces a subluxation-relocation event of the lateral tibial plateau, highly specific for functional ACL insufficiency."},{"id": 7200,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The 'noble compression test' is used to assess for:","options": [{"key": "A","text": "Meniscal tear"},{"key": "B","text": "Patellofemoral pain syndrome"},{"key": "C","text": "Popliteus tendinopathy"},{"key": "D","text": "Iliotibial band friction syndrome"}],"correct": "D","explanation": "Noble's compression test applies pressure over the lateral femoral epicondyle while flexing/extending the knee, reproducing pain at approximately 30 degrees in ITB friction syndrome."},{"id": 7201,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'bounce home test' of the knee assesses for:","options": [{"key": "A","text": "Meniscal tear/mechanical block to extension"},{"key": "B","text": "Patellar tracking"},{"key": "C","text": "PCL laxity"},{"key": "D","text": "ACL laxity"}],"correct": "A","explanation": "In this test, passive knee extension from flexion that stops with a rubbery/springy block suggests a meniscal tear blocking full extension."},{"id": 7202,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Which special test is used to assess for a SLAP lesion by combining shoulder abduction, forward flexion, and internal rotation with downward resistance?","options": [{"key": "A","text": "Neer's test"},{"key": "B","text": "Speed's test"},{"key": "C","text": "O'Brien's active compression test"},{"key": "D","text": "Hawkins-Kennedy test"}],"correct": "C","explanation": "O'Brien's test is specifically designed to provoke pain from a superior labral (SLAP) tear, differentiating it from AC joint pain by comparing pronated vs supinated forearm positions."},{"id": 7203,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'Allen test' is used to assess the patency of which vascular structures?","options": [{"key": "A","text": "Vertebral arteries"},{"key": "B","text": "Carotid arteries"},{"key": "C","text": "Femoral and popliteal arteries"},{"key": "D","text": "Radial and ulnar arteries of the hand"}],"correct": "D","explanation": "Allen's test evaluates collateral circulation and patency of the radial and ulnar arteries supplying the hand."},{"id": 7204,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'Hoffmann's sign' is a neurological test used to screen for:","options": [{"key": "A","text": "Upper motor neuron lesion/cervical myelopathy"},{"key": "B","text": "Lumbar radiculopathy"},{"key": "C","text": "Peripheral nerve entrapment"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "A","explanation": "A positive Hoffmann's sign (flicking the middle finger nail causing thumb/index finger flexion) suggests an upper motor neuron lesion, such as cervical spinal cord compression."},{"id": 7205,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'Babinski sign' (positive when great toe extends with fanning of other toes upon plantar stimulation) indicates:","options": [{"key": "A","text": "Lower motor neuron lesion"},{"key": "B","text": "Peripheral nerve entrapment"},{"key": "C","text": "Upper motor neuron lesion"},{"key": "D","text": "Normal reflex in adults"}],"correct": "C","explanation": "A positive Babinski sign in adults is a classic indicator of an upper motor neuron lesion affecting the corticospinal tract."},{"id": 7206,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'Romberg test' primarily assesses:","options": [{"key": "A","text": "Muscle strength"},{"key": "B","text": "Proprioceptive contribution to balance (with eyes closed)"},{"key": "C","text": "Cerebellar coordination only"},{"key": "D","text": "Cardiovascular fitness"}],"correct": "B","explanation": "The Romberg test assesses postural sway/balance with eyes closed to remove visual input, isolating proprioceptive and vestibular contributions."},{"id": 7207,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The 'Sharp-Purser test' is used to assess for instability at which joint?","options": [{"key": "A","text": "Occipitoatlantal joint"},{"key": "B","text": "Lumbosacral joint"},{"key": "C","text": "Sacroiliac joint"},{"key": "D","text": "Atlantoaxial (C1-C2) instability"}],"correct": "D","explanation": "This test screens for excessive anterior translation of the atlas on the axis (atlantoaxial instability), often related to rheumatoid arthritis or trauma."},{"id": 7208,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Which special test assesses SI joint pathology by applying a posterior-to-anterior compressive force with the patient side-lying?","options": [{"key": "A","text": "Sacral thrust test"},{"key": "B","text": "Gaenslen's test"},{"key": "C","text": "Compression (approximation) test"},{"key": "D","text": "FABER test"}],"correct": "C","explanation": "The compression (approximation) test applies medially directed force through the iliac crests in side-lying, stressing the SI joints posteriorly."},{"id": 7209,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "Gaenslen's test for SI joint dysfunction is performed by:","options": [{"key": "A","text": "Hyperextending one hip while flexing the opposite hip toward the chest"},{"key": "B","text": "Passive straight leg raise"},{"key": "C","text": "Applying axial compression through the femur"},{"key": "D","text": "Compressing both iliac crests simultaneously"}],"correct": "A","explanation": "Gaenslen's test stresses the SI joint by extending one hip off the table edge while flexing the contralateral hip, creating opposing torsional forces across the joint."},{"id": 7210,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'stork test' (Gillet test) assesses mobility of which joint?","options": [{"key": "A","text": "Ankle joint"},{"key": "B","text": "Sacroiliac joint"},{"key": "C","text": "Hip joint"},{"key": "D","text": "Knee joint"}],"correct": "B","explanation": "The stork/Gillet test observes relative movement of the PSIS during single-leg hip flexion, assessing SI joint mobility."},{"id": 7211,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The Ludington's test is used to assess pathology of which structure?","options": [{"key": "A","text": "Long head of biceps tendon rupture"},{"key": "B","text": "Rotator cuff tear"},{"key": "C","text": "AC joint"},{"key": "D","text": "Glenoid labrum"}],"correct": "A","explanation": "Ludington's test has the patient clasp hands behind the head and contract the biceps, used to help identify a ruptured long head of biceps tendon (Popeye deformity assessment)."},{"id": 7212,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Easy","question": "A positive Tinel's sign is generally considered indicative of:","options": [{"key": "A","text": "Normal nerve function"},{"key": "B","text": "Complete nerve transection only"},{"key": "C","text": "Muscle strain"},{"key": "D","text": "Regenerating or irritated peripheral nerve fibers"}],"correct": "D","explanation": "A positive Tinel's sign (tingling with percussion) suggests an irritable or regenerating nerve at that location."},{"id": 7213,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The 'Milgram's test' is used to help differentiate intraspinal from extraspinal causes of leg pain by:","options": [{"key": "A","text": "Applying cervical compression"},{"key": "B","text": "Having the patient hold both legs raised 2 inches off the table for 30 seconds"},{"key": "C","text": "Testing shoulder abduction strength"},{"key": "D","text": "Passive hip flexion with knee extended"}],"correct": "B","explanation": "Milgram's test increases intrathecal pressure; reproduction of symptoms suggests an intraspinal source such as disc herniation."},{"id": 7214,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Kemp's test (quadrant test) of the lumbar spine combines which movements to stress the facet joints and neural foramina?","options": [{"key": "A","text": "Pure lateral flexion"},{"key": "B","text": "Extension, lateral flexion, and rotation toward the symptomatic side"},{"key": "C","text": "Pure flexion"},{"key": "D","text": "Flexion and rotation only"}],"correct": "B","explanation": "Kemp's test combines lumbar extension with ipsilateral rotation and lateral flexion, narrowing the neural foramen and stressing facet joints to reproduce symptoms."},{"id": 7215,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Hard","question": "The 'PACVP' (Posteroanterior Central Vertebral Pressure) test is primarily used in manual therapy to assess:","options": [{"key": "A","text": "Ligamentous laxity of extremities"},{"key": "B","text": "Peripheral nerve conduction"},{"key": "C","text": "Muscle strength grading"},{"key": "D","text": "Segmental spinal mobility and provoke pain response"}],"correct": "D","explanation": "PACVP involves applying graded posterior-to-anterior pressure over spinous processes to assess segmental mobility and reproduce localized pain, guiding manual therapy treatment."},{"id": 7216,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Which test assesses hamstring flexibility by measuring the popliteal angle with the hip stabilized at 90 degrees flexion?","options": [{"key": "A","text": "Ely's test"},{"key": "B","text": "90-90 hamstring test"},{"key": "C","text": "Ober's test"},{"key": "D","text": "Thomas test"}],"correct": "B","explanation": "The 90-90 hamstring test measures the angle of knee extension limitation with the hip held at 90 degrees flexion, quantifying hamstring tightness."},{"id": 7217,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "The 'windlass test' of the foot is used to assess for:","options": [{"key": "A","text": "Plantar fasciitis"},{"key": "B","text": "Achilles tendinopathy"},{"key": "C","text": "Tarsal tunnel syndrome"},{"key": "D","text": "Morton's neuroma"}],"correct": "A","explanation": "Passive dorsiflexion of the great toe with weight-bearing tightens the plantar fascia via the windlass mechanism, reproducing pain in plantar fasciitis when positive."},{"id": 7218,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Mulder's sign (click test) is used to help diagnose:","options": [{"key": "A","text": "Tarsal tunnel syndrome"},{"key": "B","text": "Hallux rigidus"},{"key": "C","text": "Morton's neuroma"},{"key": "D","text": "Plantar fasciitis"}],"correct": "C","explanation": "Compressing the metatarsal heads together while palpating the interspace elicits a palpable/audible click and pain in the presence of Morton's neuroma."},{"id": 7219,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "The first stage of fracture healing is called:","options": [{"key": "A","text": "Callus formation stage"},{"key": "B","text": "Consolidation stage"},{"key": "C","text": "Hematoma formation stage"},{"key": "D","text": "Remodeling stage"}],"correct": "C","explanation": "Fracture healing begins with hematoma formation at the fracture site within hours of injury, initiating the inflammatory response."},{"id": 7220,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Which stage of fracture healing involves the conversion of soft callus to hard (bony) callus?","options": [{"key": "A","text": "Remodeling stage"},{"key": "B","text": "Hematoma stage"},{"key": "C","text": "Reparative/callus stage"},{"key": "D","text": "Inflammatory stage"}],"correct": "C","explanation": "During the reparative stage, soft cartilaginous callus is gradually converted to hard bony callus via endochondral ossification."},{"id": 7221,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "The final stage of fracture healing, which can take months to years, is:","options": [{"key": "A","text": "Soft callus stage"},{"key": "B","text": "Remodeling stage"},{"key": "C","text": "Hematoma organization"},{"key": "D","text": "Inflammatory stage"}],"correct": "B","explanation": "Remodeling is the final, longest stage where woven bone is reorganized into lamellar bone along lines of stress (Wolff's law)."},{"id": 7222,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Hard","question": "Which type of bone healing occurs with rigid internal fixation (compression plating) without callus formation?","options": [{"key": "A","text": "Primary/direct bone healing"},{"key": "B","text": "Endochondral healing"},{"key": "C","text": "Secondary/indirect bone healing"},{"key": "D","text": "Delayed union"}],"correct": "A","explanation": "Primary bone healing occurs via direct osteonal remodeling across a fracture gap under rigid, stable fixation, bypassing visible callus formation."},{"id": 7223,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "'Delayed union' is defined as:","options": [{"key": "A","text": "Immediate healing within 2 weeks"},{"key": "B","text": "Healing with excessive callus only"},{"key": "C","text": "Fracture healing progressing slower than expected for that bone/site"},{"key": "D","text": "Complete failure of healing"}],"correct": "C","explanation": "Delayed union refers to fracture healing that takes longer than the expected/average time for the specific fracture, but healing is still progressing."},{"id": 7224,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "'Nonunion' is defined as:","options": [{"key": "A","text": "Healing with mild angulation"},{"key": "B","text": "Slower than normal but progressing healing"},{"key": "C","text": "Failure of fracture healing, typically after 6-9 months with no radiographic progression"},{"key": "D","text": "Union within expected time"}],"correct": "C","explanation": "Nonunion is the permanent failure of a fracture to heal, generally confirmed when no progressive healing is seen on serial radiographs over an extended period (commonly cited as 6-9 months)."},{"id": 7225,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "'Malunion' refers to a fracture that has healed:","options": [{"key": "A","text": "Too rapidly"},{"key": "B","text": "In correct anatomical alignment"},{"key": "C","text": "Without any callus"},{"key": "D","text": "In unacceptable position (angulation, rotation, or shortening)"}],"correct": "D","explanation": "Malunion describes fracture union occurring in a faulty position with angulation, rotation, or shortening beyond acceptable limits."},{"id": 7226,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "Which factor is known to negatively affect fracture healing?","options": [{"key": "A","text": "Adequate blood supply"},{"key": "B","text": "Young age"},{"key": "C","text": "Smoking"},{"key": "D","text": "Proper immobilization"}],"correct": "C","explanation": "Smoking impairs fracture healing due to nicotine's vasoconstrictive effects reducing blood supply to the healing bone."},{"id": 7227,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Which of the following is a classic sign of compartment syndrome?","options": [{"key": "A","text": "Absence of any symptoms"},{"key": "B","text": "The 5 P's including pain out of proportion and paresthesia"},{"key": "C","text": "Fever alone"},{"key": "D","text": "Localized redness without pain"}],"correct": "B","explanation": "Compartment syndrome presents classically with the 5 P's: Pain (disproportionate), Paresthesia, Pallor, Pulselessness (late), and Paralysis (late)."},{"id": 7228,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "The earliest and most reliable clinical sign of acute compartment syndrome is:","options": [{"key": "A","text": "Pulselessness"},{"key": "B","text": "Pain out of proportion to injury and pain with passive stretch"},{"key": "C","text": "Pallor"},{"key": "D","text": "Paralysis"}],"correct": "B","explanation": "Pain disproportionate to the injury, especially aggravated by passive muscle stretch, is the earliest and most sensitive clinical indicator of compartment syndrome."},{"id": 7229,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Volkmann's ischemic contracture most commonly results as a complication following which fracture?","options": [{"key": "A","text": "Distal radius fracture"},{"key": "B","text": "Supracondylar fracture of humerus"},{"key": "C","text": "Tibial plateau fracture"},{"key": "D","text": "Femoral shaft fracture"}],"correct": "B","explanation": "Volkmann's ischemic contracture classically results from compartment syndrome following supracondylar humerus fractures in children, due to brachial artery compromise."},{"id": 7230,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Which type of fracture is described by the Salter-Harris classification system?","options": [{"key": "A","text": "Pathological fractures only"},{"key": "B","text": "Stress fractures"},{"key": "C","text": "Pediatric growth plate (physeal) fractures"},{"key": "D","text": "Adult long bone fractures"}],"correct": "C","explanation": "The Salter-Harris classification specifically categorizes fractures involving the pediatric growth plate (physis)."},{"id": 7231,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Hard","question": "In the Salter-Harris classification, a Type II fracture involves:","options": [{"key": "A","text": "Physis only"},{"key": "B","text": "Physis, metaphysis, and epiphysis (crush injury)"},{"key": "C","text": "Physis and epiphysis"},{"key": "D","text": "Physis and metaphysis"}],"correct": "D","explanation": "Salter-Harris Type II, the most common type, involves a fracture line through the physis extending into the metaphysis."},{"id": 7232,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "A 'greenstick fracture' is characteristic of which population due to bone flexibility?","options": [{"key": "A","text": "Adult athletes"},{"key": "B","text": "Elderly patients"},{"key": "C","text": "Postmenopausal women"},{"key": "D","text": "Children"}],"correct": "D","explanation": "Greenstick fractures, an incomplete fracture with bending on one side and cortical break on the other, are typical in children due to their more pliable, less mineralized bone."},{"id": 7233,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "A 'comminuted fracture' is defined as:","options": [{"key": "A","text": "A fracture along the growth plate"},{"key": "B","text": "An incomplete fracture line"},{"key": "C","text": "A single clean fracture line"},{"key": "D","text": "A fracture with more than two bone fragments"}],"correct": "D","explanation": "Comminuted fractures involve fragmentation of bone into three or more pieces at the fracture site."},{"id": 7234,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "A 'pathological fracture' occurs due to:","options": [{"key": "A","text": "Normal stress on healthy bone"},{"key": "B","text": "High-energy trauma only"},{"key": "C","text": "Repetitive microtrauma in healthy bone"},{"key": "D","text": "Minimal trauma to bone already weakened by disease (e.g., tumor, osteoporosis)"}],"correct": "D","explanation": "Pathological fractures occur through bone that has been weakened by an underlying condition such as tumor, infection, or metabolic bone disease, often from minimal trauma."},{"id": 7235,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "A 'stress fracture' typically results from:","options": [{"key": "A","text": "Pathological bone weakness"},{"key": "B","text": "Direct blunt trauma"},{"key": "C","text": "Repetitive submaximal loading/microtrauma over time"},{"key": "D","text": "Single high-energy trauma"}],"correct": "C","explanation": "Stress fractures develop from cumulative repetitive loading exceeding the bone's capacity to remodel, common in athletes and military recruits."},{"id": 7236,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "Which of the following best describes a 'transverse' fracture pattern?","options": [{"key": "A","text": "Fracture line perpendicular to the long axis of bone"},{"key": "B","text": "Fracture line at an oblique angle"},{"key": "C","text": "Fracture line spiraling around the bone"},{"key": "D","text": "Multiple bone fragments"}],"correct": "A","explanation": "A transverse fracture has a fracture line running perpendicular (horizontal) to the long axis of the bone, usually from a direct bending force."},{"id": 7237,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "A 'spiral fracture' pattern typically results from which mechanism of injury?","options": [{"key": "A","text": "Direct blow"},{"key": "B","text": "Torsional (twisting) force"},{"key": "C","text": "Traction force"},{"key": "D","text": "Compression force"}],"correct": "B","explanation": "Spiral fractures result from a rotational/torsional force applied to the bone, common in twisting injuries."},{"id": 7238,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "Which term describes a fracture where the bone is broken but the overlying skin remains intact?","options": [{"key": "A","text": "Segmental fracture"},{"key": "B","text": "Open (compound) fracture"},{"key": "C","text": "Comminuted fracture"},{"key": "D","text": "Closed (simple) fracture"}],"correct": "D","explanation": "A closed fracture has intact overlying skin, distinguishing it from an open fracture where bone communicates with the external environment."},{"id": 7239,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "Which fracture classification carries the highest risk of infection due to communication with the external environment?","options": [{"key": "A","text": "Greenstick fracture"},{"key": "B","text": "Closed fracture"},{"key": "C","text": "Stress fracture"},{"key": "D","text": "Open (compound) fracture"}],"correct": "D","explanation": "Open fractures, with a break in the skin exposing the fracture site, carry significantly higher infection risk than closed fractures."},{"id": 7240,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "The Gustilo-Anderson classification is used to grade the severity of:","options": [{"key": "A","text": "Open fractures"},{"key": "B","text": "Closed fractures"},{"key": "C","text": "Pathological fractures"},{"key": "D","text": "Stress fractures"}],"correct": "A","explanation": "The Gustilo-Anderson classification system grades open fracture severity based on wound size, contamination, and soft tissue/vascular injury."},{"id": 7241,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Fat embolism syndrome is a serious complication most commonly associated with fractures of which bones?","options": [{"key": "A","text": "Long bones (especially femur) and pelvis"},{"key": "B","text": "Metacarpals"},{"key": "C","text": "Radius and ulna"},{"key": "D","text": "Vertebrae"}],"correct": "A","explanation": "Fat embolism syndrome classically occurs after fractures of long bones (particularly femur) and the pelvis, where marrow fat enters the circulation."},{"id": 7242,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Hard","question": "Which of the following is a classic triad of symptoms in fat embolism syndrome?","options": [{"key": "A","text": "Fever, hypotension, bradycardia"},{"key": "B","text": "Joint pain, swelling, redness"},{"key": "C","text": "Numbness, tingling, weakness only"},{"key": "D","text": "Respiratory distress, neurological symptoms, petechial rash"}],"correct": "D","explanation": "Fat embolism syndrome classically presents with the triad of respiratory insufficiency, neurological abnormalities, and petechial rash."},{"id": 7243,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Deep vein thrombosis (DVT) is a significant risk following fractures, particularly of which region?","options": [{"key": "A","text": "Upper limb fractures"},{"key": "B","text": "Lower limb and pelvic fractures"},{"key": "C","text": "Rib fractures"},{"key": "D","text": "Facial fractures"}],"correct": "B","explanation": "Lower limb and pelvic fractures, especially with prolonged immobilization, carry significant DVT risk due to venous stasis and vessel injury."},{"id": 7244,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Physiotherapy management immediately after fracture immobilization typically begins with:","options": [{"key": "A","text": "Passive stretching of the fracture site"},{"key": "B","text": "Active exercises of unaffected joints and isometric exercises within the cast"},{"key": "C","text": "Weight-bearing on the fractured limb immediately"},{"key": "D","text": "Aggressive strengthening of the immobilized limb"}],"correct": "B","explanation": "Early physiotherapy focuses on maintaining mobility of unaffected joints and gentle isometric exercises within the immobilized segment to minimize atrophy and stiffness."},{"id": 7245,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Which factor is essential to consider before initiating weight-bearing exercises after a lower limb fracture?","options": [{"key": "A","text": "Radiographic and clinical evidence of adequate healing/callus formation as advised by the surgeon"},{"key": "B","text": "Time since injury alone, regardless of healing"},{"key": "C","text": "Patient's pain tolerance only"},{"key": "D","text": "Patient's preference only"}],"correct": "A","explanation": "Weight-bearing progression should be guided by radiographic/clinical evidence of fracture healing and surgeon clearance, not solely by time elapsed."},{"id": 7246,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "'Wolff's law' relates to which principle of bone physiology?","options": [{"key": "A","text": "Bone healing always takes exactly 6 weeks"},{"key": "B","text": "Bone density is unaffected by loading"},{"key": "C","text": "Bone healing requires immobilization only"},{"key": "D","text": "Bone remodels in response to the mechanical stresses placed upon it"}],"correct": "D","explanation": "Wolff's law states that bone adapts and remodels its internal architecture in response to the mechanical demands (stress/loading) placed upon it."},{"id": 7247,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Easy","question": "Which of the following factors generally favors faster fracture healing?","options": [{"key": "A","text": "Increasing patient age"},{"key": "B","text": "Adequate blood supply and stable fixation"},{"key": "C","text": "Presence of infection"},{"key": "D","text": "Smoking"}],"correct": "B","explanation": "Good vascular supply and mechanical stability at the fracture site are key factors that favor efficient fracture healing."},{"id": 7248,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Refracture (re-fracture) risk after fracture healing is increased by:","options": [{"key": "A","text": "Premature return to high-impact activity before adequate bone strength is restored"},{"key": "B","text": "Complete callus remodeling"},{"key": "C","text": "Adequate rehabilitation"},{"key": "D","text": "Gradual progressive loading"}],"correct": "A","explanation": "Returning to high-impact or high-load activities before the bone has regained adequate strength significantly increases refracture risk."},{"id": 7249,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Complex Regional Pain Syndrome (CRPS) following fracture is characterized by:","options": [{"key": "A","text": "Localized infection only"},{"key": "B","text": "Simple delayed union"},{"key": "C","text": "Normal recovery pattern"},{"key": "D","text": "Disproportionate pain, swelling, and autonomic changes in the affected limb"}],"correct": "D","explanation": "CRPS presents with disproportionate pain, swelling, temperature/color changes, and autonomic dysfunction, often following fracture or minor trauma."},{"id": 7250,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Which of the following best describes 'avascular necrosis' as a fracture complication?","options": [{"key": "A","text": "Overgrowth of bone"},{"key": "B","text": "Death of bone tissue due to compromised blood supply"},{"key": "C","text": "Infection at the fracture site"},{"key": "D","text": "Excessive callus formation"}],"correct": "B","explanation": "Avascular necrosis occurs when the blood supply to a bone segment is disrupted (commonly at the femoral head, scaphoid, talus), leading to bone tissue death."},{"id": 7251,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Hard","question": "Which of the following bones is particularly susceptible to avascular necrosis after fracture due to its precarious retrograde blood supply?","options": [{"key": "A","text": "Clavicle"},{"key": "B","text": "Radius shaft"},{"key": "C","text": "Scaphoid (proximal pole)"},{"key": "D","text": "Fibula shaft"}],"correct": "C","explanation": "The scaphoid's blood supply enters distally and flows retrograde, making proximal pole fractures particularly prone to avascular necrosis."},{"id": 7252,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Myositis ossificans, a complication seen especially after elbow trauma, refers to:","options": [{"key": "A","text": "Nerve entrapment in muscle"},{"key": "B","text": "Abnormal heterotopic bone formation within muscle/soft tissue"},{"key": "C","text": "Muscle tear without healing"},{"key": "D","text": "Infection of muscle tissue"}],"correct": "B","explanation": "Myositis ossificans involves the abnormal formation of bone within muscle or soft tissue, often following trauma, and is a concern especially with aggressive elbow mobilization."},{"id": 7253,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Hard","question": "Which precaution is important during physiotherapy of a patient with suspected myositis ossificans at the elbow?","options": [{"key": "A","text": "Heat application before any assessment"},{"key": "B","text": "Aggressive passive stretching to break down the tissue"},{"key": "C","text": "Avoiding aggressive/forceful passive stretching, favoring gentle active exercises"},{"key": "D","text": "Complete immobilization indefinitely"}],"correct": "C","explanation": "Aggressive passive stretching can exacerbate heterotopic bone formation in myositis ossificans; gentle active, pain-free movement is preferred."},{"id": 7254,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Easy","question": "A Colles' fracture involves a fracture of the distal radius with which characteristic displacement?","options": [{"key": "A","text": "Lateral displacement only"},{"key": "B","text": "Dorsal displacement with radial shortening ('dinner fork' deformity)"},{"key": "C","text": "Volar (palmar) displacement"},{"key": "D","text": "No displacement"}],"correct": "B","explanation": "Colles' fracture shows dorsal angulation/displacement of the distal fragment, producing the classic 'dinner fork' deformity."},{"id": 7255,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A Smith's fracture is essentially the reverse of a Colles' fracture, with which displacement direction?","options": [{"key": "A","text": "Dorsal displacement"},{"key": "B","text": "No displacement"},{"key": "C","text": "Lateral displacement"},{"key": "D","text": "Volar (palmar) displacement"}],"correct": "D","explanation": "Smith's fracture involves volar displacement of the distal radius fragment, opposite to the dorsal displacement seen in Colles' fracture."},{"id": 7256,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Easy","question": "A supracondylar fracture of the humerus most commonly occurs in which population?","options": [{"key": "A","text": "Children (typically 5-10 years)"},{"key": "B","text": "Neonates"},{"key": "C","text": "Young male athletes"},{"key": "D","text": "Elderly women"}],"correct": "A","explanation": "Supracondylar humerus fractures are most common in children, typically from a fall on an outstretched hand."},{"id": 7257,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Hard","question": "Which nerve is most commonly injured in a supracondylar fracture of the humerus?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Anterior interosseous branch of median nerve"},{"key": "C","text": "Radial nerve only"},{"key": "D","text": "Axillary nerve"}],"correct": "B","explanation": "The anterior interosseous nerve (branch of median nerve) is the most commonly injured nerve in supracondylar fractures, though radial and ulnar nerves can also be affected depending on displacement direction."},{"id": 7258,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A Monteggia fracture-dislocation involves fracture of which bone with dislocation of which joint?","options": [{"key": "A","text": "Ulna fracture with radial head dislocation"},{"key": "B","text": "Both bone fracture without dislocation"},{"key": "C","text": "Radius fracture with distal radioulnar joint dislocation"},{"key": "D","text": "Humeral fracture with elbow dislocation"}],"correct": "A","explanation": "Monteggia fracture-dislocation involves a proximal ulna fracture combined with dislocation of the radial head."},{"id": 7259,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A Galeazzi fracture-dislocation involves fracture of which bone with dislocation of which joint?","options": [{"key": "A","text": "Ulna fracture with elbow dislocation"},{"key": "B","text": "Radius fracture with distal radioulnar joint (DRUJ) dislocation"},{"key": "C","text": "Both bones fractured without dislocation"},{"key": "D","text": "Humerus fracture with shoulder dislocation"}],"correct": "B","explanation": "Galeazzi fracture-dislocation involves a distal radial shaft fracture with associated disruption of the distal radioulnar joint."},{"id": 7260,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A helpful mnemonic to remember Monteggia vs Galeazzi fracture patterns is:","options": [{"key": "A","text": "Both involve identical bones"},{"key": "B","text": "No mnemonic exists"},{"key": "C","text": "MUGR - Monteggia=Radius, Galeazzi=Ulna"},{"key": "D","text": "MUGR - Monteggia=Ulna, Galeazzi=Radius"}],"correct": "D","explanation": "'MUGR': Monteggia = Ulna fracture (proximal) with radial head dislocation; Galeazzi = Radius fracture (distal) with DRUJ disruption."},{"id": 7261,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Easy","question": "Clavicle fractures most commonly occur at which part of the bone?","options": [{"key": "A","text": "Medial third"},{"key": "B","text": "Sternal end"},{"key": "C","text": "Lateral third"},{"key": "D","text": "Middle third"}],"correct": "D","explanation": "The middle third of the clavicle is the most common fracture site due to its structurally weaker cross-sectional profile."},{"id": 7262,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "Most clavicle fractures are managed with which primary approach?","options": [{"key": "A","text": "Immediate surgical fixation always"},{"key": "B","text": "Amputation"},{"key": "C","text": "Complete immobilization for 6 months"},{"key": "D","text": "Conservative management with sling/figure-of-eight bandage"}],"correct": "D","explanation": "The majority of clavicle fractures, especially middle-third, heal well with conservative sling immobilization; surgery is reserved for specific indications."},{"id": 7263,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Easy","question": "A proximal humerus fracture is most common in which patient population?","options": [{"key": "A","text": "Middle-aged manual laborers only"},{"key": "B","text": "Neonates"},{"key": "C","text": "Elderly patients with osteoporosis, often from a fall"},{"key": "D","text": "Young athletes"}],"correct": "C","explanation": "Proximal humerus fractures are common in elderly osteoporotic patients, typically resulting from a low-energy fall onto an outstretched arm."},{"id": 7264,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "Which nerve is at risk of injury in proximal humerus (surgical neck) fractures?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Musculocutaneous nerve"},{"key": "C","text": "Axillary nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "C","explanation": "The axillary nerve, coursing close to the surgical neck of the humerus, is particularly vulnerable in fractures/dislocations at this level."},{"id": 7265,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A humeral shaft fracture carries risk of injury to which nerve as it courses in the spiral groove?","options": [{"key": "A","text": "Axillary nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Median nerve"}],"correct": "C","explanation": "The radial nerve winds around the humeral shaft in the spiral groove, making it susceptible to injury (wrist drop) in midshaft humeral fractures."},{"id": 7266,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Easy","question": "A boxer's fracture typically involves the neck of which metacarpal?","options": [{"key": "A","text": "Second metacarpal"},{"key": "B","text": "Third metacarpal"},{"key": "C","text": "Fifth metacarpal"},{"key": "D","text": "Fourth metacarpal"}],"correct": "C","explanation": "A boxer's fracture classically involves the neck of the fifth metacarpal, typically from punching with a closed fist."},{"id": 7267,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A Bennett's fracture involves an intra-articular fracture at the base of which bone?","options": [{"key": "A","text": "Fifth metacarpal"},{"key": "B","text": "Scaphoid"},{"key": "C","text": "Distal radius"},{"key": "D","text": "First metacarpal"}],"correct": "D","explanation": "Bennett's fracture is an intra-articular fracture-dislocation at the base of the first metacarpal, involving the carpometacarpal joint."},{"id": 7268,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A radial head fracture is commonly caused by which mechanism?","options": [{"key": "A","text": "Twisting injury of the wrist"},{"key": "B","text": "Direct blow to the posterior elbow"},{"key": "C","text": "Fall on an outstretched hand with axial loading through the forearm"},{"key": "D","text": "Hyperflexion of the elbow"}],"correct": "C","explanation": "Radial head fractures typically result from a fall onto an outstretched hand, transmitting axial force through the radius to the elbow."},{"id": 7269,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "An olecranon fracture most commonly results from which mechanism?","options": [{"key": "A","text": "Fall on outstretched hand only"},{"key": "B","text": "Direct fall onto the point of the flexed elbow or forceful triceps contraction"},{"key": "C","text": "Twisting of the forearm"},{"key": "D","text": "Repetitive overuse only"}],"correct": "B","explanation": "Olecranon fractures typically occur from a direct blow/fall onto the flexed elbow or a sudden forceful triceps contraction (avulsion mechanism)."},{"id": 7270,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "Scaphoid fractures are notoriously prone to which complication due to retrograde blood supply?","options": [{"key": "A","text": "Rapid uneventful healing"},{"key": "B","text": "Immediate infection"},{"key": "C","text": "Excessive callus formation only"},{"key": "D","text": "Nonunion and avascular necrosis, especially of the proximal pole"}],"correct": "D","explanation": "The scaphoid's retrograde blood flow (entering distally) predisposes proximal pole fractures to nonunion and avascular necrosis."},{"id": 7271,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Easy","question": "Which clinical sign classically raises suspicion for a scaphoid fracture after a FOOSH injury?","options": [{"key": "A","text": "Tenderness over the ulnar styloid"},{"key": "B","text": "Pain with shoulder movement"},{"key": "C","text": "Swelling of the fifth finger"},{"key": "D","text": "Tenderness in the anatomical snuffbox"}],"correct": "D","explanation": "Tenderness in the anatomical snuffbox is the classic clinical finding suggestive of scaphoid fracture after a fall on an outstretched hand."},{"id": 7272,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Hard","question": "A distal radius fracture with dorsal comminution and intra-articular extension is best classified using which system?","options": [{"key": "A","text": "Salter-Harris classification only"},{"key": "B","text": "Gustilo-Anderson classification"},{"key": "C","text": "AO/OTA classification or Frykman classification"},{"key": "D","text": "Neer classification"}],"correct": "C","explanation": "The AO/OTA and Frykman classification systems are commonly used to describe distal radius fracture patterns and guide management."},{"id": 7273,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "Physiotherapy after a Colles' fracture cast removal typically begins with:","options": [{"key": "A","text": "Aggressive resisted wrist exercises immediately"},{"key": "B","text": "Weight-bearing through the hand immediately"},{"key": "C","text": "Complete rest for another 6 weeks"},{"key": "D","text": "Gentle active ROM of wrist and hand, and shoulder/elbow mobility exercises during immobilization"}],"correct": "D","explanation": "Post-cast rehabilitation begins with gentle active wrist/hand ROM, progressing gradually, while shoulder and elbow mobility should have been maintained throughout immobilization."},{"id": 7274,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "Which complication is particularly associated with distal radius fractures, presenting with pain, stiffness, and autonomic changes?","options": [{"key": "A","text": "Malunion only"},{"key": "B","text": "Complex Regional Pain Syndrome (CRPS)"},{"key": "C","text": "Avascular necrosis of radius"},{"key": "D","text": "Compartment syndrome only"}],"correct": "B","explanation": "CRPS is a recognized complication following distal radius fractures, presenting with disproportionate pain, swelling, and autonomic/trophic changes."},{"id": 7275,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "A clavicle fracture with significant displacement/shortening in an active young adult may be treated with:","options": [{"key": "A","text": "Conservative sling only regardless of displacement"},{"key": "B","text": "Surgical fixation (ORIF) considered for significant displacement/shortening"},{"key": "C","text": "Amputation"},{"key": "D","text": "No treatment required"}],"correct": "B","explanation": "While most clavicle fractures are managed conservatively, significantly displaced or shortened fractures, especially in active individuals, may warrant surgical fixation."},{"id": 7276,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Hard","question": "Which structure is at risk of injury with a first rib fracture, given its proximity?","options": [{"key": "A","text": "Phrenic nerve only"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Subclavian vessels and brachial plexus"},{"key": "D","text": "Radial nerve"}],"correct": "C","explanation": "First rib fractures are associated with potential injury to the subclavian vessels and brachial plexus due to their close anatomical relationship."},{"id": 7277,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "Elbow fractures in children (e.g., supracondylar) require careful vascular assessment primarily to detect compromise of which artery?","options": [{"key": "A","text": "Axillary artery"},{"key": "B","text": "Radial artery"},{"key": "C","text": "Brachial artery"},{"key": "D","text": "Ulnar artery"}],"correct": "C","explanation": "The brachial artery is at risk of compression or injury in displaced pediatric supracondylar fractures, requiring careful neurovascular monitoring."},{"id": 7278,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Hard","question": "Malunion of a distal radius fracture with dorsal angulation can lead to functional limitation primarily in which movement?","options": [{"key": "A","text": "Wrist extension and grip strength"},{"key": "B","text": "Elbow flexion"},{"key": "C","text": "Finger abduction"},{"key": "D","text": "Shoulder abduction"}],"correct": "A","explanation": "Dorsal malunion of the distal radius alters the joint mechanics, commonly limiting wrist extension and reducing grip strength."},{"id": 7279,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Easy","question": "Femoral neck fractures are most common in which population?","options": [{"key": "A","text": "Elderly patients with osteoporosis"},{"key": "B","text": "Young athletes"},{"key": "C","text": "Children"},{"key": "D","text": "Middle-aged manual laborers"}],"correct": "A","explanation": "Femoral neck fractures predominantly occur in elderly osteoporotic individuals, often from low-energy falls."},{"id": 7280,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Garden classification is used to grade the severity of which fracture?","options": [{"key": "A","text": "Ankle fracture"},{"key": "B","text": "Tibial plateau fracture"},{"key": "C","text": "Femoral neck fracture"},{"key": "D","text": "Femoral shaft fracture"}],"correct": "C","explanation": "The Garden classification system grades femoral neck fractures based on the degree of displacement, guiding treatment decisions."},{"id": 7281,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Displaced femoral neck fractures carry significant risk of which complication due to precarious blood supply?","options": [{"key": "A","text": "Immediate infection only"},{"key": "B","text": "Excessive callus formation"},{"key": "C","text": "Avascular necrosis of femoral head"},{"key": "D","text": "Nonunion of femoral shaft"}],"correct": "C","explanation": "Displaced femoral neck fractures disrupt the retinacular blood supply to the femoral head, risking avascular necrosis."},{"id": 7282,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Intertrochanteric fractures of the femur, compared to femoral neck fractures, have:","options": [{"key": "A","text": "Higher risk of avascular necrosis"},{"key": "B","text": "Always require amputation"},{"key": "C","text": "No difference in vascular risk"},{"key": "D","text": "Lower risk of avascular necrosis due to good extracapsular blood supply"}],"correct": "D","explanation": "Intertrochanteric fractures occur in a well-vascularized extracapsular region, carrying much lower avascular necrosis risk than intracapsular femoral neck fractures."},{"id": 7283,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Post-operative physiotherapy after hip fracture fixation typically emphasizes early:","options": [{"key": "A","text": "Mobilization and weight-bearing as tolerated/advised, to reduce complications"},{"key": "B","text": "Avoidance of all movement"},{"key": "C","text": "Complete bed rest for 6 weeks"},{"key": "D","text": "Immediate return to sport"}],"correct": "A","explanation": "Early mobilization after hip fracture surgery is emphasized to reduce risks of DVT, pressure sores, pneumonia, and to restore function faster."},{"id": 7284,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Easy","question": "A femoral shaft fracture in a young adult typically results from which mechanism?","options": [{"key": "A","text": "Minor fall"},{"key": "B","text": "Pathological weakening"},{"key": "C","text": "High-energy trauma (e.g., road traffic accident)"},{"key": "D","text": "Repetitive stress"}],"correct": "C","explanation": "Femoral shaft fractures in younger, healthy bone usually require significant high-energy trauma, such as motor vehicle accidents."},{"id": 7285,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Significant blood loss (up to 1-1.5 liters) can occur internally with which lower limb fracture?","options": [{"key": "A","text": "Closed femoral shaft fracture"},{"key": "B","text": "Patellar fracture"},{"key": "C","text": "Ankle fracture"},{"key": "D","text": "Metatarsal fracture"}],"correct": "A","explanation": "Closed femoral shaft fractures can cause substantial internal hemorrhage into the thigh, up to 1-1.5 liters, due to rich vascularity of the region."},{"id": 7286,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Tibial plateau fractures commonly result from which mechanism?","options": [{"key": "A","text": "Axial loading combined with valgus or varus force (e.g., fall from height, MVA)"},{"key": "B","text": "Repetitive low-impact activity"},{"key": "C","text": "Simple twisting injury"},{"key": "D","text": "Direct blow to the shin only"}],"correct": "A","explanation": "Tibial plateau fractures typically result from axial compressive loading combined with a varus or valgus force, common in falls from height or vehicle accidents."},{"id": 7287,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Which associated soft tissue injury should be suspected with tibial plateau fractures?","options": [{"key": "A","text": "Meniscal and/or ligamentous knee injury"},{"key": "B","text": "Rotator cuff tear"},{"key": "C","text": "Achilles tendon rupture"},{"key": "D","text": "Plantar fascia rupture"}],"correct": "A","explanation": "Given the mechanism and location, tibial plateau fractures frequently have concomitant meniscal tears and/or collateral or cruciate ligament injuries."},{"id": 7288,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Tibial shaft fractures carry a notably higher risk of which complication compared to other long bones, due to limited soft tissue coverage?","options": [{"key": "A","text": "Open fracture and compartment syndrome"},{"key": "B","text": "Pathological refracture only"},{"key": "C","text": "Malignant transformation"},{"key": "D","text": "Avascular necrosis"}],"correct": "A","explanation": "The tibia's subcutaneous anteromedial surface with limited soft tissue coverage predisposes it to open fractures and compartment syndrome."},{"id": 7289,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "A 'bimalleolar' ankle fracture involves fracture of which two structures?","options": [{"key": "A","text": "Medial and lateral malleoli"},{"key": "B","text": "Lateral malleolus and calcaneus"},{"key": "C","text": "Distal tibia and fibula shaft"},{"key": "D","text": "Medial malleolus and talus"}],"correct": "A","explanation": "A bimalleolar fracture involves both the medial malleolus (tibia) and lateral malleolus (fibula)."},{"id": 7290,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "A 'trimalleolar' ankle fracture adds fracture of which additional structure to the bimalleolar pattern?","options": [{"key": "A","text": "Posterior malleolus (posterior tibia)"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Navicular"},{"key": "D","text": "Talus"}],"correct": "A","explanation": "Trimalleolar fracture includes the medial malleolus, lateral malleolus, and the posterior malleolus (posterior tibial articular margin)."},{"id": 7291,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Hard","question": "The Weber classification of ankle fractures is based on the level of fibular fracture relative to:","options": [{"key": "A","text": "The syndesmosis"},{"key": "B","text": "The tibial plateau"},{"key": "C","text": "The medial malleolus"},{"key": "D","text": "The talus"}],"correct": "A","explanation": "Weber classification (A, B, C) categorizes fibular fracture location relative to the level of the tibiofibular syndesmosis, correlating with syndesmotic stability."},{"id": 7292,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "A calcaneal fracture most commonly results from which mechanism?","options": [{"key": "A","text": "Repetitive overuse"},{"key": "B","text": "Twisting injury"},{"key": "C","text": "Axial loading from a fall from height landing on the heel"},{"key": "D","text": "Direct lateral blow"}],"correct": "C","explanation": "Calcaneal fractures classically occur from axial compressive loading during a fall from height with the person landing on their heels."},{"id": 7293,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Hard","question": "Calcaneal fractures are often associated with concomitant injury to which region due to the shared injury mechanism (axial loading)?","options": [{"key": "A","text": "Cervical spine"},{"key": "B","text": "Wrist"},{"key": "C","text": "Thoracolumbar spine"},{"key": "D","text": "Shoulder girdle"}],"correct": "C","explanation": "The axial loading mechanism causing calcaneal fractures (fall from height) commonly also causes thoracolumbar spine compression fractures; screening is essential."},{"id": 7294,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "A Jones fracture involves the fracture of which bone at a region prone to poor healing?","options": [{"key": "A","text": "Body of the calcaneus"},{"key": "B","text": "Base of the first metatarsal"},{"key": "C","text": "Base of the fifth metatarsal (metaphyseal-diaphyseal junction)"},{"key": "D","text": "Neck of the talus"}],"correct": "C","explanation": "The Jones fracture occurs at the metaphyseal-diaphyseal junction of the fifth metatarsal, an area with relatively poor blood supply predisposing to delayed union/nonunion."},{"id": 7295,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Hard","question": "A talar neck fracture carries significant risk of which complication due to its precarious retrograde blood supply?","options": [{"key": "A","text": "Immediate deformity only"},{"key": "B","text": "No significant complications"},{"key": "C","text": "Avascular necrosis of the talar body"},{"key": "D","text": "Excessive callus formation"}],"correct": "C","explanation": "Similar to the scaphoid, the talus has a retrograde blood supply, and talar neck fractures risk avascular necrosis of the talar body."},{"id": 7296,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Toddler's fracture refers to a nondisplaced spiral fracture typically of which bone in young children?","options": [{"key": "A","text": "Femur"},{"key": "B","text": "Tibia"},{"key": "C","text": "Humerus"},{"key": "D","text": "Fibula"}],"correct": "B","explanation": "Toddler's fracture is a subtle, often nondisplaced spiral fracture of the tibia seen in young ambulating children, often from a minor twisting fall."},{"id": 7297,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "A 'March fracture' (stress fracture) is classically described in which bone, historically named after military recruits?","options": [{"key": "A","text": "Tibial plateau"},{"key": "B","text": "Second or third metatarsal"},{"key": "C","text": "Femur"},{"key": "D","text": "Calcaneus"}],"correct": "B","explanation": "March fracture refers to a stress fracture of the metatarsals (classically second or third), historically described in military recruits after long marches."},{"id": 7298,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Post-fixation physiotherapy for tibial shaft fracture typically progresses weight-bearing status based on:","options": [{"key": "A","text": "Patient's own decision without guidance"},{"key": "B","text": "Pain level only, regardless of imaging"},{"key": "C","text": "Radiographic evidence of healing, fixation stability, and surgeon's protocol"},{"key": "D","text": "Time alone"}],"correct": "C","explanation": "Weight-bearing progression after tibial fracture fixation should follow the surgeon's protocol, informed by radiographic healing and construct stability."},{"id": 7299,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Which condition should be closely monitored for in the initial 24-72 hours following a high-energy tibial fracture due to swelling within fascial compartments?","options": [{"key": "A","text": "Avascular necrosis"},{"key": "B","text": "Malunion"},{"key": "C","text": "Delayed union"},{"key": "D","text": "Acute compartment syndrome"}],"correct": "D","explanation": "The early post-injury period is critical for monitoring compartment syndrome, as swelling within closed fascial compartments can compromise perfusion."},{"id": 7300,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "A patella fracture is most commonly caused by which mechanism?","options": [{"key": "A","text": "Axial loading through the tibia"},{"key": "B","text": "Direct blow to the anterior knee or forceful quadriceps contraction"},{"key": "C","text": "Twisting injury of the knee"},{"key": "D","text": "Repetitive low-grade stress only"}],"correct": "B","explanation": "Patella fractures typically result from a direct blow (e.g., dashboard injury) or a sudden forceful quadriceps contraction against a flexed knee."},{"id": 7301,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Following patella fracture fixation, early physiotherapy typically emphasizes:","options": [{"key": "A","text": "Immediate full weight-bearing and running"},{"key": "B","text": "No exercise until 6 months post-op"},{"key": "C","text": "Complete immobilization for 3 months"},{"key": "D","text": "Protected ROM progression and quadriceps activation per surgical protocol"}],"correct": "D","explanation": "Rehabilitation after patella fracture fixation generally involves protected, progressive ROM along with early quadriceps activation to prevent extensor lag, following surgeon-specific protocols."},{"id": 7302,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Hip fracture fixation choice (e.g., hemiarthroplasty vs internal fixation) is largely influenced by which factor?","options": [{"key": "A","text": "Fracture displacement, location (intra- vs extracapsular), and patient's age/activity level"},{"key": "B","text": "Time of day of injury"},{"key": "C","text": "Patient's favorite color"},{"key": "D","text": "Weather conditions"}],"correct": "A","explanation": "Surgical decision-making for hip fractures depends on fracture pattern/location, displacement, patient age, bone quality, and functional demands."},{"id": 7303,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "Which of the following best describes the primary goal of early physiotherapy after any lower limb fracture fixation?","options": [{"key": "A","text": "Immediate return to competitive sport"},{"key": "B","text": "Avoiding all movement until complete bony union"},{"key": "C","text": "Restoring functional mobility, preventing complications, and progressive strengthening within safe limits"},{"key": "D","text": "Ignoring pain during rehabilitation"}],"correct": "C","explanation": "Early rehabilitation aims to safely restore function, prevent complications like stiffness/DVT/muscle atrophy, and progressively strengthen within limits set by fixation stability and healing stage."},{"id": 7304,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "A compression (wedge) fracture of the vertebral body most commonly results from which mechanism?","options": [{"key": "A","text": "Direct posterior blow"},{"key": "B","text": "Axial loading with flexion, common in osteoporotic bone"},{"key": "C","text": "Hyperextension injury"},{"key": "D","text": "Rotational injury"}],"correct": "B","explanation": "Vertebral compression fractures typically occur from axial loading combined with flexion, frequently in osteoporotic patients from minor trauma or even routine activity."},{"id": 7305,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Hard","question": "A burst fracture of the vertebra differs from a simple compression fracture by involving:","options": [{"key": "A","text": "Both anterior and posterior vertebral body walls, with potential retropulsion into the canal"},{"key": "B","text": "Only the anterior column"},{"key": "C","text": "Only the posterior elements"},{"key": "D","text": "No bony involvement, only ligamentous injury"}],"correct": "A","explanation": "Burst fractures involve failure of both anterior and posterior vertebral body walls, with risk of bone fragment retropulsion into the spinal canal, unlike simple wedge compression fractures."},{"id": 7306,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Hard","question": "A Chance fracture (seatbelt fracture) typically results from which mechanism?","options": [{"key": "A","text": "Flexion-distraction injury, classically from lap seatbelt restraint in vehicle accidents"},{"key": "B","text": "Direct lateral blow"},{"key": "C","text": "Axial compression alone"},{"key": "D","text": "Hyperextension"}],"correct": "A","explanation": "The Chance fracture is a flexion-distraction injury through the vertebral body and posterior elements, classically associated with lap-belt-only restraints in motor vehicle accidents."},{"id": 7307,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Hard","question": "Which spinal fracture classification system is commonly used to describe thoracolumbar fracture patterns and guide treatment (e.g., stable vs unstable)?","options": [{"key": "A","text": "Gustilo-Anderson classification"},{"key": "B","text": "Weber classification"},{"key": "C","text": "AO Spine (Magerl) classification"},{"key": "D","text": "Salter-Harris classification"}],"correct": "C","explanation": "The AO Spine (Magerl) classification categorizes thoracolumbar fractures into compression, distraction, and rotational injury types, informing stability assessment and management."},{"id": 7308,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Hard","question": "Pelvic ring fractures are classified using which commonly referenced system based on mechanism and stability?","options": [{"key": "A","text": "Neer classification"},{"key": "B","text": "Young-Burgess classification"},{"key": "C","text": "Frykman classification"},{"key": "D","text": "Salter-Harris classification"}],"correct": "B","explanation": "The Young-Burgess classification categorizes pelvic fractures based on injury mechanism (lateral compression, anteroposterior compression, vertical shear) and associated instability."},{"id": 7309,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "Pelvic fractures carry significant risk of which life-threatening complication due to the rich vascular network in the region?","options": [{"key": "A","text": "Massive hemorrhage/hemodynamic instability"},{"key": "B","text": "Nerve entrapment only"},{"key": "C","text": "Delayed wound healing only"},{"key": "D","text": "Avascular necrosis of femoral head only"}],"correct": "A","explanation": "Pelvic fractures, particularly unstable patterns, can cause massive retroperitoneal hemorrhage due to disruption of the extensive pelvic venous plexus and arteries."},{"id": 7310,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "Which structure is at risk of injury with pelvic fractures, potentially causing bladder or urethral trauma?","options": [{"key": "A","text": "Brachial plexus"},{"key": "B","text": "Genitourinary structures (bladder, urethra)"},{"key": "C","text": "Phrenic nerve"},{"key": "D","text": "Sciatic nerve"}],"correct": "B","explanation": "Given the close anatomical relationship, pelvic fractures can be associated with genitourinary injuries including bladder rupture or urethral disruption."},{"id": 7311,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "A stable, isolated osteoporotic vertebral compression fracture without neurological deficit is typically managed initially with:","options": [{"key": "A","text": "Immediate spinal fusion"},{"key": "B","text": "Complete bed rest for 6 months"},{"key": "C","text": "Conservative management including pain control, bracing, and gradual mobilization"},{"key": "D","text": "Emergency surgical fixation always"}],"correct": "C","explanation": "Uncomplicated osteoporotic compression fractures without neurological compromise are usually managed conservatively with analgesia, bracing as needed, and early gradual mobilization."},{"id": 7312,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "Which clinical sign warrants urgent evaluation for spinal cord/cauda equina involvement in a patient with a suspected spinal fracture?","options": [{"key": "A","text": "Mild localized tenderness only"},{"key": "B","text": "New bowel/bladder dysfunction, saddle anesthesia, or progressive neurological deficit"},{"key": "C","text": "Normal reflexes"},{"key": "D","text": "Absence of pain"}],"correct": "B","explanation": "Bowel/bladder dysfunction, saddle anesthesia, or progressive neurological deficits are red flags suggesting cauda equina syndrome or spinal cord compromise, requiring urgent evaluation."},{"id": 7313,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "Physiotherapy precautions after an unstable pelvic fracture typically include:","options": [{"key": "A","text": "Immediate full weight-bearing on both limbs"},{"key": "B","text": "No physiotherapy involvement at all"},{"key": "C","text": "Aggressive early running programs"},{"key": "D","text": "Protected/restricted weight-bearing per surgeon's guidance until adequate healing/fixation stability"}],"correct": "D","explanation": "Weight-bearing status after pelvic fracture fixation is carefully guided by fracture stability and fixation, often requiring protected/partial weight-bearing initially."},{"id": 7314,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Hard","question": "A sacral fracture may present with which neurological finding due to proximity to sacral nerve roots?","options": [{"key": "A","text": "Facial numbness"},{"key": "B","text": "Cranial nerve palsy"},{"key": "C","text": "Upper limb weakness"},{"key": "D","text": "Saddle anesthesia and/or bowel/bladder dysfunction"}],"correct": "D","explanation": "Sacral fractures can injure sacral nerve roots, potentially causing saddle anesthesia and bowel/bladder dysfunction."},{"id": 7315,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "Log-rolling technique is used in early management of suspected spinal fracture patients primarily to:","options": [{"key": "A","text": "Maintain spinal alignment while turning/repositioning the patient"},{"key": "B","text": "Test for sensation loss"},{"key": "C","text": "Assess muscle strength"},{"key": "D","text": "Reduce pelvic fracture displacement"}],"correct": "A","explanation": "Log-rolling maintains neutral spinal alignment during patient repositioning, minimizing further injury risk to a potentially unstable spine."},{"id": 7316,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "Thoracolumbar orthoses (braces) prescribed after vertebral compression fractures primarily aim to:","options": [{"key": "A","text": "Replace the need for any physiotherapy"},{"key": "B","text": "Limit flexion and provide external support during the healing phase"},{"key": "C","text": "Increase spinal flexibility"},{"key": "D","text": "Completely eliminate all spinal movement permanently"}],"correct": "B","explanation": "TLSO braces aim to restrict excessive flexion and provide external support to protect the healing vertebra during the initial recovery phase."},{"id": 7317,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Easy","question": "Which population is at particular risk for low-energy vertebral compression fractures?","options": [{"key": "A","text": "Young athletes with strong bone density"},{"key": "B","text": "Middle-aged manual laborers with normal bone density"},{"key": "C","text": "Children"},{"key": "D","text": "Postmenopausal women with osteoporosis"}],"correct": "D","explanation": "Postmenopausal women with reduced bone mineral density (osteoporosis) are at significantly increased risk of vertebral compression fractures even with minor trauma."},{"id": 7318,"subject": "Orthopedics","topic": "Fractures - Spine & Pelvis","difficulty": "Medium","question": "Progressive resistance and weight-bearing exercise prescribed for osteoporotic patients after compression fracture healing primarily aims to:","options": [{"key": "A","text": "Avoid all physical activity permanently"},{"key": "B","text": "Immediately return to pre-injury sport"},{"key": "C","text": "Improve bone density, posture, and reduce future fracture risk"},{"key": "D","text": "Increase fracture risk further"}],"correct": "C","explanation": "Appropriately dosed weight-bearing and resistance exercise helps stimulate bone remodeling, improve posture and balance, and reduce future fracture risk in osteoporotic patients."},{"id": 7319,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Easy","question": "The shoulder joint is the most commonly dislocated major joint in the body primarily due to:","options": [{"key": "A","text": "Strong ligamentous support"},{"key": "B","text": "Its large range of motion with relatively shallow glenoid socket"},{"key": "C","text": "Its bony congruency"},{"key": "D","text": "Small range of motion"}],"correct": "B","explanation": "The glenohumeral joint's inherent mobility, achieved partly through a shallow glenoid fossa relative to the humeral head, predisposes it to dislocation."},{"id": 7320,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Easy","question": "The most common direction of shoulder dislocation is:","options": [{"key": "A","text": "Anterior"},{"key": "B","text": "Posterior"},{"key": "C","text": "Superior"},{"key": "D","text": "Inferior (luxatio erecta)"}],"correct": "A","explanation": "Anterior dislocation accounts for the vast majority (approximately 95%) of shoulder dislocations."},{"id": 7321,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "A Hill-Sachs lesion, commonly associated with anterior shoulder dislocation, refers to:","options": [{"key": "A","text": "A compression fracture of the posterolateral humeral head"},{"key": "B","text": "A tear of the anterior labrum only"},{"key": "C","text": "An avulsion of the coracoid process"},{"key": "D","text": "A rotator cuff tear"}],"correct": "A","explanation": "A Hill-Sachs lesion is a compression (impaction) fracture of the posterolateral humeral head caused by impact against the anterior glenoid rim during anterior dislocation."},{"id": 7322,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "A Bankart lesion, frequently associated with recurrent anterior shoulder instability, involves injury to:","options": [{"key": "A","text": "The supraspinatus tendon"},{"key": "B","text": "The posterior labrum"},{"key": "C","text": "The AC joint"},{"key": "D","text": "The anteroinferior glenoid labrum"}],"correct": "D","explanation": "Bankart lesions involve detachment of the anteroinferior glenoid labrum, a common finding after anterior shoulder dislocation contributing to recurrent instability."},{"id": 7323,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Posterior shoulder dislocation, though rare, is classically associated with which event?","options": [{"key": "A","text": "Fall on outstretched hand"},{"key": "B","text": "Seizures or electric shock"},{"key": "C","text": "Direct anterior blow"},{"key": "D","text": "Repetitive overhead activity"}],"correct": "B","explanation": "Posterior shoulder dislocations are classically associated with seizures or electrical shock, due to the powerful internal rotators overpowering external rotators."},{"id": 7324,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Elbow dislocations most commonly occur in which direction?","options": [{"key": "A","text": "Medial"},{"key": "B","text": "Anterior"},{"key": "C","text": "Lateral"},{"key": "D","text": "Posterior"}],"correct": "D","explanation": "Posterior elbow dislocation is the most common pattern, typically resulting from a fall on an outstretched hand with the elbow extended."},{"id": 7325,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Which nerve is at particular risk of injury during elbow dislocation?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve (and occasionally brachial artery)"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Axillary nerve"}],"correct": "B","explanation": "Elbow dislocation can injure the median nerve and, in severe cases, compromise the brachial artery, requiring careful neurovascular assessment."},{"id": 7326,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Patellar dislocation most commonly occurs in which direction?","options": [{"key": "A","text": "Medial"},{"key": "B","text": "Superior"},{"key": "C","text": "Lateral"},{"key": "D","text": "Inferior"}],"correct": "C","explanation": "Lateral patellar dislocation is by far the most common pattern, often related to anatomical risk factors like a shallow trochlear groove or increased Q angle."},{"id": 7327,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Which structure is commonly injured/torn with a first-time lateral patellar dislocation?","options": [{"key": "A","text": "Meniscus only"},{"key": "B","text": "ACL"},{"key": "C","text": "Lateral collateral ligament"},{"key": "D","text": "Medial patellofemoral ligament (MPFL)"}],"correct": "D","explanation": "The medial patellofemoral ligament (MPFL), the primary soft tissue restraint to lateral patellar translation, is commonly torn during lateral patellar dislocation."},{"id": 7328,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Hip dislocations most commonly occur in which direction, especially following high-energy trauma such as a dashboard injury?","options": [{"key": "A","text": "Superior"},{"key": "B","text": "Posterior"},{"key": "C","text": "Anterior"},{"key": "D","text": "Central"}],"correct": "B","explanation": "Posterior hip dislocation is the most common pattern, classically from a dashboard-type injury with the hip flexed and adducted at time of impact."},{"id": 7329,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Which nerve is at significant risk of injury with posterior hip dislocation?","options": [{"key": "A","text": "Obturator nerve"},{"key": "B","text": "Pudendal nerve"},{"key": "C","text": "Sciatic nerve"},{"key": "D","text": "Femoral nerve"}],"correct": "C","explanation": "The sciatic nerve, coursing posterior to the hip joint, is at significant risk of stretch or compression injury during posterior hip dislocation."},{"id": 7330,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Hip dislocation is considered an orthopedic emergency primarily due to risk of:","options": [{"key": "A","text": "Permanent skin damage"},{"key": "B","text": "Immediate fatal hemorrhage"},{"key": "C","text": "Avascular necrosis of the femoral head if reduction is delayed"},{"key": "D","text": "No significant urgency involved"}],"correct": "C","explanation": "Timely reduction of a dislocated hip is critical to minimize the risk of avascular necrosis, as prolonged displacement compromises femoral head blood supply."},{"id": 7331,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Developmental Dysplasia of the Hip (DDH) refers to:","options": [{"key": "A","text": "A spectrum of abnormal hip development in infants/children leading to instability or dislocation"},{"key": "B","text": "Acute traumatic hip dislocation in adults"},{"key": "C","text": "An inflammatory hip condition"},{"key": "D","text": "A degenerative hip condition in the elderly"}],"correct": "A","explanation": "DDH encompasses a spectrum of hip joint developmental abnormalities in infants, ranging from mild instability to frank dislocation."},{"id": 7332,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Acromioclavicular (AC) joint injuries are graded using which commonly used classification?","options": [{"key": "A","text": "Weber classification"},{"key": "B","text": "Rockwood classification"},{"key": "C","text": "Garden classification"},{"key": "D","text": "Salter-Harris classification"}],"correct": "B","explanation": "The Rockwood classification grades AC joint injuries from Type I (sprain) to Type VI, based on the degree of ligamentous disruption and displacement."},{"id": 7333,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Hard","question": "A Rockwood Type III AC joint injury involves complete disruption of which ligaments?","options": [{"key": "A","text": "Acromioclavicular and coracoclavicular ligaments"},{"key": "B","text": "Only acromioclavicular ligament, minimal displacement"},{"key": "C","text": "No ligamentous disruption"},{"key": "D","text": "Coracoclavicular ligaments only"}],"correct": "A","explanation": "Type III AC injuries involve complete tearing of both the acromioclavicular and coracoclavicular ligaments, with visible clavicular elevation."},{"id": 7334,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Hard","question": "Sternoclavicular joint dislocation, though rare, is potentially most dangerous when displaced in which direction due to proximity to mediastinal structures?","options": [{"key": "A","text": "Anterior"},{"key": "B","text": "Posterior"},{"key": "C","text": "Inferior"},{"key": "D","text": "Superior"}],"correct": "B","explanation": "Posterior sternoclavicular dislocation is potentially life-threatening due to risk of compression of mediastinal vessels, trachea, or esophagus."},{"id": 7335,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Easy","question": "Which of the following best describes a 'subluxation' as opposed to a complete dislocation?","options": [{"key": "A","text": "Complete loss of joint congruity"},{"key": "B","text": "Only ligamentous laxity with no positional change"},{"key": "C","text": "No change in joint position at all"},{"key": "D","text": "Partial loss of joint congruity, with some articular contact maintained"}],"correct": "D","explanation": "Subluxation refers to a partial dislocation where some articular surface contact is maintained, unlike a complete dislocation with total loss of congruity."},{"id": 7336,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Radial head subluxation ('nursemaid's elbow') is common in young children and typically results from:","options": [{"key": "A","text": "Twisting injury of the wrist"},{"key": "B","text": "Fall onto the shoulder"},{"key": "C","text": "Direct blow to the elbow"},{"key": "D","text": "Sudden longitudinal traction/pulling on the pronated extended arm"}],"correct": "D","explanation": "Nursemaid's elbow occurs when sudden traction is applied to a young child's extended, pronated arm (e.g., being pulled up by the hand), subluxating the radial head."},{"id": 7337,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Following closed reduction of a first-time anterior shoulder dislocation in a young active patient, recurrence risk is:","options": [{"key": "A","text": "Very low regardless of age"},{"key": "B","text": "Relatively high, particularly in younger patients"},{"key": "C","text": "Zero after successful reduction"},{"key": "D","text": "Higher in older patients than younger"}],"correct": "B","explanation": "Recurrence rates after a first anterior shoulder dislocation are notably higher in younger, more active patients compared to older individuals."},{"id": 7338,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Post-reduction physiotherapy management for a first-time traumatic anterior shoulder dislocation typically includes:","options": [{"key": "A","text": "Immediate aggressive overhead strengthening"},{"key": "B","text": "Permanent avoidance of all shoulder movement"},{"key": "C","text": "A period of relative immobilization followed by graded strengthening avoiding provocative positions initially"},{"key": "D","text": "No restrictions at all"}],"correct": "C","explanation": "Management generally involves brief immobilization/protection followed by a graded rehabilitation program, initially avoiding the apprehension position (abduction-external rotation) before progressive strengthening."},{"id": 7339,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Hard","question": "Multidirectional shoulder instability differs from traumatic unidirectional instability primarily by involving:","options": [{"key": "A","text": "Instability in a single direction only, from significant trauma"},{"key": "B","text": "Exclusively bony pathology"},{"key": "C","text": "Instability in multiple directions, often with underlying capsular laxity and minimal trauma"},{"key": "D","text": "Only posterior instability"}],"correct": "C","explanation": "Multidirectional instability involves symptomatic laxity in more than one direction, often related to generalized capsular/ligamentous laxity rather than a single traumatic event."},{"id": 7340,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Hard","question": "Which term describes recurrent shoulder dislocation with minimal or no trauma due to underlying structural/capsular laxity?","options": [{"key": "A","text": "Impingement syndrome"},{"key": "B","text": "Atraumatic multidirectional bilateral instability (AMBRI)"},{"key": "C","text": "Traumatic unidirectional instability with Bankart lesion (TUBS)"},{"key": "D","text": "Simple sprain"}],"correct": "B","explanation": "AMBRI describes atraumatic, multidirectional, often bilateral instability, typically managed with rehabilitation (Rehabilitation) rather than surgery initially, contrasting with TUBS which often needs surgical Bankart repair."},{"id": 7341,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Hard","question": "Knee dislocation (tibiofemoral) is a rare but severe injury requiring urgent assessment of which structure due to high risk of injury?","options": [{"key": "A","text": "Sural nerve only"},{"key": "B","text": "Femoral nerve"},{"key": "C","text": "Popliteal artery"},{"key": "D","text": "Saphenous vein only"}],"correct": "C","explanation": "Knee dislocation carries a high risk of popliteal artery injury, requiring urgent vascular assessment to prevent limb-threatening ischemia."},{"id": 7342,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "Following reduction of a traumatic elbow dislocation, early physiotherapy typically emphasizes:","options": [{"key": "A","text": "No follow-up needed after reduction"},{"key": "B","text": "Early protected active/active-assisted ROM to prevent stiffness, guided by stability assessment"},{"key": "C","text": "Complete immobilization for 8 weeks minimum"},{"key": "D","text": "Aggressive passive stretching from day one"}],"correct": "B","explanation": "Early protected mobilization after elbow dislocation is generally emphasized to reduce the significant risk of post-traumatic stiffness, balanced against joint stability."},{"id": 7343,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Hard","question": "Recurrent patellar dislocation is more likely in patients with which anatomical predisposing factor?","options": [{"key": "A","text": "Strong VMO development"},{"key": "B","text": "Genu varum"},{"key": "C","text": "Trochlear dysplasia (shallow groove) and increased Q angle"},{"key": "D","text": "Deep trochlear groove"}],"correct": "C","explanation": "Anatomical risk factors such as trochlear dysplasia, patella alta, and increased Q angle predispose to recurrent lateral patellar instability."},{"id": 7344,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "A 'sprain' refers to injury of which type of tissue?","options": [{"key": "A","text": "Muscle-tendon unit"},{"key": "B","text": "Nerve"},{"key": "C","text": "Bone"},{"key": "D","text": "Ligament"}],"correct": "D","explanation": "A sprain specifically refers to a stretch or tear injury of a ligament, connecting bone to bone."},{"id": 7345,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "A 'strain' refers to injury of which type of tissue?","options": [{"key": "A","text": "Ligament"},{"key": "B","text": "Bone"},{"key": "C","text": "Cartilage"},{"key": "D","text": "Muscle or musculotendinous unit"}],"correct": "D","explanation": "A strain refers to injury of the muscle or musculotendinous unit, often from excessive stretch or overload."},{"id": 7346,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "A Grade I ligament sprain is characterized by:","options": [{"key": "A","text": "Mild stretching with microscopic tearing, minimal instability"},{"key": "B","text": "Avulsion fracture"},{"key": "C","text": "Complete tear with gross instability"},{"key": "D","text": "Complete rupture requiring surgery"}],"correct": "A","explanation": "Grade I sprains involve mild stretching with microtearing of ligament fibers, with minimal to no joint instability."},{"id": 7347,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "A Grade III ligament sprain is characterized by:","options": [{"key": "A","text": "Mild stretching only"},{"key": "B","text": "Complete rupture of the ligament with gross instability"},{"key": "C","text": "No structural damage"},{"key": "D","text": "Partial tear with mild laxity"}],"correct": "B","explanation": "Grade III sprains represent complete ligament rupture, resulting in significant joint instability."},{"id": 7348,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "A Grade II muscle strain typically presents with:","options": [{"key": "A","text": "Partial tear with moderate pain, swelling, and some loss of strength"},{"key": "B","text": "Complete rupture with palpable defect"},{"key": "C","text": "No pain at all"},{"key": "D","text": "No loss of strength or function"}],"correct": "A","explanation": "Grade II strains involve partial muscle fiber tearing with moderate pain, swelling, and some functional/strength deficit, without a palpable complete defect."},{"id": 7349,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "A Grade III muscle strain is characterized by:","options": [{"key": "A","text": "Minimal swelling and pain"},{"key": "B","text": "Complete muscle/tendon rupture, often with a palpable defect and significant functional loss"},{"key": "C","text": "No need for rehabilitation"},{"key": "D","text": "Mild overstretching only"}],"correct": "B","explanation": "Grade III strains represent complete rupture of the muscle or musculotendinous unit, often producing a palpable gap and significant loss of function."},{"id": 7350,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "The acronym PRICE (Protection, Rest, Ice, Compression, Elevation) is traditionally used in the management of which phase of soft tissue injury?","options": [{"key": "A","text": "Acute inflammatory phase"},{"key": "B","text": "Late functional phase only"},{"key": "C","text": "Chronic/remodeling phase"},{"key": "D","text": "Surgical phase"}],"correct": "A","explanation": "PRICE principles are applied in the acute inflammatory phase of soft tissue injury to control swelling, pain, and further tissue damage."},{"id": 7351,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "More recent evidence-based guidelines have modified PRICE to which updated acronym emphasizing early controlled loading?","options": [{"key": "A","text": "PEACE and LOVE only, replacing all prior protocols universally without any Loading component"},{"key": "B","text": "RICE only"},{"key": "C","text": "POLICE (Protection, Optimal Loading, Ice, Compression, Elevation)"},{"key": "D","text": "No modification exists"}],"correct": "C","explanation": "POLICE introduces 'Optimal Loading' in place of strict rest, recognizing that controlled early loading benefits tissue healing more than complete immobilization."},{"id": 7352,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Tendinopathy is now understood to primarily involve which pathological process, rather than pure inflammation?","options": [{"key": "A","text": "Bone erosion"},{"key": "B","text": "Bacterial infection"},{"key": "C","text": "Acute inflammatory infiltrate only"},{"key": "D","text": "Collagen degeneration and disorganization (tendinosis) with failed healing response"}],"correct": "D","explanation": "Chronic tendinopathy is now understood as primarily a degenerative process (tendinosis) with collagen disorganization and neovascularization, rather than a classic inflammatory process."},{"id": 7353,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Which of the following best differentiates 'tendinitis' from 'tendinosis'?","options": [{"key": "A","text": "Tendinitis only occurs in the lower limb"},{"key": "B","text": "Tendinitis implies acute inflammation, while tendinosis implies chronic degeneration without significant inflammatory cells"},{"key": "C","text": "They are identical conditions with different names"},{"key": "D","text": "Tendinosis is always more acute than tendinitis"}],"correct": "B","explanation": "Tendinitis traditionally denotes acute inflammatory tendon pathology, while tendinosis reflects chronic degenerative changes with minimal inflammatory cell presence."},{"id": 7354,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Eccentric exercise protocols (e.g., Alfredson protocol) have strong evidence for the management of which condition?","options": [{"key": "A","text": "Acute muscle strain"},{"key": "B","text": "Bone fracture"},{"key": "C","text": "Acute ligament sprain"},{"key": "D","text": "Chronic tendinopathy (e.g., Achilles, patellar)"}],"correct": "D","explanation": "Eccentric loading protocols have substantial evidence supporting their use in managing chronic tendinopathies such as Achilles and patellar tendinopathy."},{"id": 7355,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Lateral epicondylalgia ('tennis elbow') primarily involves pathology of which tendon?","options": [{"key": "A","text": "Flexor carpi radialis"},{"key": "B","text": "Extensor carpi radialis brevis (and common extensor origin)"},{"key": "C","text": "Triceps tendon"},{"key": "D","text": "Biceps tendon"}],"correct": "B","explanation": "Lateral epicondylalgia most commonly involves tendinosis of the extensor carpi radialis brevis at its origin on the lateral epicondyle."},{"id": 7356,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Medial epicondylalgia ('golfer's elbow') primarily involves pathology of which tendon group?","options": [{"key": "A","text": "Common extensor origin"},{"key": "B","text": "Biceps insertion"},{"key": "C","text": "Common flexor-pronator origin"},{"key": "D","text": "Triceps insertion"}],"correct": "C","explanation": "Medial epicondylalgia involves degenerative changes at the common flexor-pronator tendon origin on the medial epicondyle."},{"id": 7357,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Rotator cuff tendinopathy is commonly associated with which mechanical factor?","options": [{"key": "A","text": "Excessive glenohumeral stability"},{"key": "B","text": "Increased rotator cuff strength"},{"key": "C","text": "Subacromial impingement/reduced subacromial space"},{"key": "D","text": "Adequate scapular kinematics only"}],"correct": "C","explanation": "Rotator cuff tendinopathy is often related to mechanical impingement within a reduced subacromial space, along with intrinsic tendon degeneration factors."},{"id": 7358,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Achilles tendinopathy is classified based on location as either insertional or:","options": [{"key": "A","text": "Proximal"},{"key": "B","text": "Distal only"},{"key": "C","text": "Bilateral only"},{"key": "D","text": "Mid-portion (non-insertional)"}],"correct": "D","explanation": "Achilles tendinopathy is classified as insertional (at the calcaneal insertion) or mid-portion/non-insertional (typically 2-6 cm proximal to insertion)."},{"id": 7359,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Patellar tendinopathy ('jumper's knee') most commonly affects which portion of the tendon?","options": [{"key": "A","text": "Quadriceps tendon insertion"},{"key": "B","text": "Distal insertion at tibial tuberosity"},{"key": "C","text": "Proximal portion at the inferior pole of patella"},{"key": "D","text": "Mid-substance uniformly"}],"correct": "C","explanation": "Patellar tendinopathy most commonly involves the proximal tendon near its origin at the inferior pole of the patella."},{"id": 7360,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "A hamstring strain most commonly occurs at which location?","options": [{"key": "A","text": "Muscle belly mid-substance"},{"key": "B","text": "Musculotendinous junction, often the biceps femoris"},{"key": "C","text": "Bony insertion only"},{"key": "D","text": "Tendon mid-substance away from muscle"}],"correct": "B","explanation": "Hamstring strains most frequently occur at the musculotendinous junction, with the biceps femoris long head being the most commonly injured component."},{"id": 7361,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Hard","question": "A high-grade hamstring strain near the ischial tuberosity with significant retraction may require which management approach?","options": [{"key": "A","text": "Amputation"},{"key": "B","text": "Conservative management always regardless of severity"},{"key": "C","text": "No treatment necessary"},{"key": "D","text": "Surgical repair may be considered for complete proximal avulsions with significant retraction"}],"correct": "D","explanation": "Complete proximal hamstring avulsions with significant tendon retraction are often considered for surgical repair, particularly in active individuals."},{"id": 7362,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "A gastrocnemius strain (often called 'tennis leg') classically occurs at which location?","options": [{"key": "A","text": "Soleus muscle belly only"},{"key": "B","text": "Peroneal tendons"},{"key": "C","text": "Achilles tendon insertion"},{"key": "D","text": "Musculotendinous junction of the medial gastrocnemius head"}],"correct": "D","explanation": "'Tennis leg' classically refers to a strain at the musculotendinous junction of the medial head of gastrocnemius, often during forceful push-off with knee extended and ankle dorsiflexed."},{"id": 7363,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Groin strains commonly involve which muscle group?","options": [{"key": "A","text": "Gluteals"},{"key": "B","text": "Hip adductors (particularly adductor longus)"},{"key": "C","text": "Quadriceps"},{"key": "D","text": "Hip abductors"}],"correct": "B","explanation": "Groin strains most frequently involve the hip adductor group, especially adductor longus, common in sports involving cutting and kicking."},{"id": 7364,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Which factor is considered a risk factor for recurrent muscle strain injury?","options": [{"key": "A","text": "Gradual progressive loading"},{"key": "B","text": "Complete rehabilitation before return to sport"},{"key": "C","text": "Adequate flexibility training"},{"key": "D","text": "Inadequate rehabilitation and premature return to activity"}],"correct": "D","explanation": "Returning to sport/activity before adequate strength, flexibility, and functional capacity are restored significantly increases the risk of re-injury."},{"id": 7365,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "De Quervain's tenosynovitis involves inflammation of which tendons?","options": [{"key": "A","text": "Abductor pollicis longus and extensor pollicis brevis (first dorsal compartment)"},{"key": "B","text": "Flexor digitorum superficialis"},{"key": "C","text": "Flexor carpi radialis and ulnaris"},{"key": "D","text": "Extensor digitorum communis"}],"correct": "A","explanation": "De Quervain's tenosynovitis affects the tendons of abductor pollicis longus and extensor pollicis brevis within the first dorsal wrist compartment."},{"id": 7366,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Trigger finger (stenosing tenosynovitis) results from a mismatch between the flexor tendon and which structure?","options": [{"key": "A","text": "Annular pulley (commonly A1 pulley)"},{"key": "B","text": "Collateral ligaments"},{"key": "C","text": "Carpal bones"},{"key": "D","text": "Extensor retinaculum"}],"correct": "A","explanation": "Trigger finger occurs due to a size mismatch/nodule formation causing the flexor tendon to catch as it passes through the A1 pulley."},{"id": 7367,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "Plantar fasciitis most commonly presents with pain localized to which area?","options": [{"key": "A","text": "Lateral heel"},{"key": "B","text": "Achilles insertion"},{"key": "C","text": "Dorsum of the foot"},{"key": "D","text": "Medial calcaneal tubercle/plantar heel, worse with first steps in the morning"}],"correct": "D","explanation": "Plantar fasciitis classically causes pain at the medial calcaneal tubercle, characteristically worse with the first steps after rest (post-static dyskinesia)."},{"id": 7368,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Iliotibial band syndrome typically presents with lateral knee pain aggravated by which activity?","options": [{"key": "A","text": "Upper body exercise"},{"key": "B","text": "Static standing only"},{"key": "C","text": "Running, especially downhill or with increased mileage"},{"key": "D","text": "Swimming"}],"correct": "C","explanation": "ITB syndrome commonly presents with lateral knee pain during repetitive activities like running, often worsened by downhill running or sudden mileage increases."},{"id": 7369,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "Bursitis refers to inflammation of which structure?","options": [{"key": "A","text": "Bone periosteum"},{"key": "B","text": "Fluid-filled sac that reduces friction between tissues (bursa)"},{"key": "C","text": "Ligament"},{"key": "D","text": "Tendon sheath"}],"correct": "B","explanation": "Bursitis is inflammation of a bursa, the fluid-filled sac that reduces friction between adjacent moving structures such as tendon and bone."},{"id": 7370,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Trochanteric bursitis (now often termed greater trochanteric pain syndrome) typically presents with pain over which area?","options": [{"key": "A","text": "Lateral hip over the greater trochanter"},{"key": "B","text": "Posterior buttock"},{"key": "C","text": "Medial thigh"},{"key": "D","text": "Anterior groin"}],"correct": "A","explanation": "Greater trochanteric pain syndrome classically presents with lateral hip pain localized over the greater trochanter, often worse with side-lying or stair climbing."},{"id": 7371,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Subacromial bursitis commonly coexists with which other shoulder condition due to their close anatomical relationship?","options": [{"key": "A","text": "Rotator cuff tendinopathy/impingement"},{"key": "B","text": "Wrist tenosynovitis"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "Elbow tendinopathy"}],"correct": "A","explanation": "Subacromial bursitis frequently coexists with rotator cuff tendinopathy and subacromial impingement due to their shared anatomical space."},{"id": 7372,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "Prepatellar bursitis ('housemaid's knee') is commonly caused by:","options": [{"key": "A","text": "Twisting injury of the knee"},{"key": "B","text": "Overhead activity"},{"key": "C","text": "Direct trauma to the lateral knee only"},{"key": "D","text": "Repetitive/prolonged kneeling"}],"correct": "D","explanation": "Prepatellar bursitis classically results from repetitive or prolonged kneeling, causing friction/pressure over the anterior knee bursa."},{"id": 7373,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Hard","question": "Which structure is primarily responsible for shock absorption and load distribution within the meniscus?","options": [{"key": "A","text": "Cartilage thickness alone"},{"key": "B","text": "Collagen fiber arrangement (circumferential hoop fibers)"},{"key": "C","text": "Synovial fluid volume only"},{"key": "D","text": "Bone mineral density"}],"correct": "B","explanation": "The meniscus's circumferentially arranged collagen fibers convert axial compressive loads into hoop (tensile) stresses, effectively distributing load and absorbing shock."},{"id": 7374,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Meniscal tears are classified by tear pattern, which of the following is a recognized type?","options": [{"key": "A","text": "Bucket-handle tear"},{"key": "B","text": "Spiral tear of bone"},{"key": "C","text": "Transverse fracture pattern"},{"key": "D","text": "Comminuted pattern"}],"correct": "A","explanation": "Bucket-handle tears represent a longitudinal meniscal tear pattern where the inner fragment displaces centrally, resembling a bucket handle."},{"id": 7375,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Hard","question": "Meniscal tears in the peripheral 'red-red' zone have better healing potential than tears in the central 'white-white' zone primarily due to:","options": [{"key": "A","text": "Greater collagen density centrally"},{"key": "B","text": "No difference in healing potential exists"},{"key": "C","text": "Better vascular supply in the peripheral zone"},{"key": "D","text": "Greater cartilage thickness centrally"}],"correct": "C","explanation": "The peripheral (red-red) zone of the meniscus has better blood supply, giving it superior healing potential compared to the avascular central (white-white) zone."},{"id": 7376,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Labral tears of the shoulder (e.g., SLAP lesions) often result from which combination of forces?","options": [{"key": "A","text": "Pure axial compression only"},{"key": "B","text": "Pure rotational forces of the wrist"},{"key": "C","text": "Static postural loading only"},{"key": "D","text": "Traction and/or repetitive overhead throwing motions with shear forces"}],"correct": "D","explanation": "SLAP and other labral tears often result from repetitive overhead throwing mechanics, traction injuries, or falls onto an outstretched arm creating shear at the labrum."},{"id": 7377,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Whiplash-associated disorder typically results from which mechanism?","options": [{"key": "A","text": "Repetitive overhead activity"},{"key": "B","text": "Direct blow to the head"},{"key": "C","text": "Chronic postural strain only"},{"key": "D","text": "Rapid acceleration-deceleration force to the neck (e.g., rear-end collision)"}],"correct": "D","explanation": "Whiplash injury classically results from sudden acceleration-deceleration forces to the cervical spine, commonly from rear-end motor vehicle collisions."},{"id": 7378,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Which soft tissue structures are commonly implicated in whiplash-associated disorder?","options": [{"key": "A","text": "Cervical musculature, ligaments, facet joint capsules, and potentially discs"},{"key": "B","text": "Only the cervical discs"},{"key": "C","text": "Only the vertebral bodies"},{"key": "D","text": "Only the brachial plexus"}],"correct": "A","explanation": "Whiplash can involve strain/sprain of cervical muscles, ligaments, facet joint capsules, and occasionally discogenic structures."},{"id": 7379,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Adhesive capsulitis (frozen shoulder) primarily involves pathological changes in which structure?","options": [{"key": "A","text": "Bony structures of the glenoid"},{"key": "B","text": "The glenohumeral joint capsule, becoming thickened and contracted"},{"key": "C","text": "Rotator cuff tendons only"},{"key": "D","text": "Only the AC joint"}],"correct": "B","explanation": "Frozen shoulder involves progressive thickening, fibrosis, and contracture of the glenohumeral joint capsule, restricting both active and passive motion."},{"id": 7380,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Which patient population has an increased predisposition to developing adhesive capsulitis?","options": [{"key": "A","text": "Young athletic males"},{"key": "B","text": "Children"},{"key": "C","text": "Patients with hypermobility syndromes"},{"key": "D","text": "Diabetic patients and those aged 40-60, particularly women"}],"correct": "D","explanation": "Diabetes mellitus and middle age (40-60 years), with a higher prevalence in women, are recognized risk factors for adhesive capsulitis."},{"id": 7381,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "The 'freezing' phase of adhesive capsulitis is characterized by:","options": [{"key": "A","text": "Progressively worsening pain with gradual loss of motion"},{"key": "B","text": "Progressive stiffness with minimal pain"},{"key": "C","text": "Complete resolution of symptoms"},{"key": "D","text": "Sudden onset of instability"}],"correct": "A","explanation": "The freezing phase involves increasing pain and progressive loss of shoulder motion over weeks to months."},{"id": 7382,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "The 'thawing' phase of adhesive capsulitis is characterized by:","options": [{"key": "A","text": "Gradual improvement in range of motion with resolving pain"},{"key": "B","text": "Worsening stiffness and pain"},{"key": "C","text": "Sudden onset of new symptoms"},{"key": "D","text": "No change in symptoms"}],"correct": "A","explanation": "The thawing (resolution) phase involves gradual, often slow, improvement in range of motion and reduction in pain over months."},{"id": 7383,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Hard","question": "Ligament healing, unlike tendon, is often complicated by which structural difference?","options": [{"key": "A","text": "Ligaments have superior blood supply compared to tendons"},{"key": "B","text": "Ligaments always heal faster than tendons"},{"key": "C","text": "Ligaments generally have relatively poorer vascularity, especially certain ligaments like the ACL"},{"key": "D","text": "No differences exist in healing capacity"}],"correct": "C","explanation": "Certain ligaments, notably the ACL, have relatively poor intrinsic vascularity, contributing to limited spontaneous healing capacity compared to some tendons."},{"id": 7384,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Cross-friction (transverse friction) massage is a manual therapy technique commonly used in chronic tendinopathy to:","options": [{"key": "A","text": "Weaken the tendon further"},{"key": "B","text": "Promote fibril realignment/mobility and reduce adhesions at the lesion site"},{"key": "C","text": "Replace the need for exercise entirely"},{"key": "D","text": "Increase local swelling"}],"correct": "B","explanation": "Transverse friction massage aims to mobilize the tendon/soft tissue, potentially improving fibril alignment and reducing localized adhesions as part of a broader treatment approach."},{"id": 7385,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Easy","question": "Which imaging modality is most useful for detailed soft tissue assessment of ligaments, tendons, and menisci?","options": [{"key": "A","text": "Magnetic Resonance Imaging (MRI)"},{"key": "B","text": "Plain radiograph (X-ray)"},{"key": "C","text": "CT scan primarily"},{"key": "D","text": "Bone scan"}],"correct": "A","explanation": "MRI provides superior soft tissue contrast resolution, making it the imaging modality of choice for detailed assessment of ligaments, tendons, cartilage, and menisci."},{"id": 7386,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Hard","question": "The 'load-deformation curve' of ligament tissue shows an initial 'toe region' representing:","options": [{"key": "A","text": "Straightening of the crimped collagen fiber pattern under low load"},{"key": "B","text": "Plastic deformation only"},{"key": "C","text": "Maximum tensile strength"},{"key": "D","text": "Immediate ligament failure"}],"correct": "A","explanation": "The toe region of the load-deformation curve represents the initial straightening of the naturally crimped/wavy collagen fibers under low load, before linear stiffness increases."},{"id": 7387,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Immobilization following soft tissue injury, if prolonged excessively, can lead to which negative effect on healing tissue?","options": [{"key": "A","text": "No negative effects at all"},{"key": "B","text": "Disorganized collagen deposition, adhesion formation, and reduced tensile strength"},{"key": "C","text": "Enhanced strength beyond normal"},{"key": "D","text": "Improved collagen organization"}],"correct": "B","explanation": "Excessive prolonged immobilization can result in poorly organized collagen, increased adhesion formation, and reduced tissue tensile strength, supporting the trend toward early controlled mobilization."},{"id": 7388,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Which of the following is a recognized benefit of early controlled mobilization (within tolerable limits) after soft tissue injury?","options": [{"key": "A","text": "Guaranteed reinjury"},{"key": "B","text": "Delayed healing in all cases"},{"key": "C","text": "Improved collagen fiber alignment along lines of stress and reduced adhesion formation"},{"key": "D","text": "Increased scar tissue disorganization"}],"correct": "C","explanation": "Controlled early mobilization promotes collagen fiber alignment along functional lines of stress and helps minimize excessive adhesion formation, supporting better quality healing."},{"id": 7389,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "Achilles tendon rupture most commonly occurs in which demographic?","options": [{"key": "A","text": "Elite marathon runners exclusively"},{"key": "B","text": "Middle-aged 'weekend warrior' athletes engaging in sudden intense activity"},{"key": "C","text": "Children"},{"key": "D","text": "Young sedentary individuals"}],"correct": "B","explanation": "Achilles rupture classically occurs in middle-aged recreational athletes who engage in sudden bursts of intense activity without adequate conditioning."},{"id": 7390,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Medium","question": "A high ankle sprain involves injury to which ligamentous structure, distinct from typical lateral ankle sprains?","options": [{"key": "A","text": "Anterior talofibular ligament"},{"key": "B","text": "Calcaneofibular ligament"},{"key": "C","text": "Deltoid ligament only"},{"key": "D","text": "Distal tibiofibular syndesmosis"}],"correct": "D","explanation": "High ankle sprains involve injury to the tibiofibular syndesmosis, typically from external rotation/dorsiflexion mechanisms, and generally require longer recovery than typical lateral sprains."},{"id": 7391,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Subacromial impingement syndrome is classified by Neer into how many stages?","options": [{"key": "A","text": "Four stages"},{"key": "B","text": "Two stages"},{"key": "C","text": "Three stages"},{"key": "D","text": "Five stages"}],"correct": "C","explanation": "Neer classified subacromial impingement into three progressive stages: Stage I (edema/hemorrhage), Stage II (fibrosis/tendinitis), and Stage III (tears/bony changes)."},{"id": 7392,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Neer Stage I impingement is characterized by:","options": [{"key": "A","text": "Complete tendon rupture requiring surgery"},{"key": "B","text": "Full-thickness rotator cuff tear"},{"key": "C","text": "Reversible edema and hemorrhage of the rotator cuff, typically in young patients"},{"key": "D","text": "Bony spur formation with irreversible cuff tearing"}],"correct": "C","explanation": "Stage I involves reversible inflammatory changes (edema/hemorrhage), commonly seen in younger patients following overuse, and responds well to conservative management."},{"id": 7393,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Neer Stage III impingement typically involves which finding?","options": [{"key": "A","text": "No pathology at all"},{"key": "B","text": "Fibrosis and tendinitis without tearing"},{"key": "C","text": "Partial or full-thickness rotator cuff tears with associated bony changes"},{"key": "D","text": "Reversible inflammation only"}],"correct": "C","explanation": "Stage III represents advanced disease with partial or complete rotator cuff tears, often accompanied by bony changes such as osteophyte formation, typically in older patients."},{"id": 7394,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which structural factor can contribute to 'outlet' subacromial impingement?","options": [{"key": "A","text": "Increased subacromial space"},{"key": "B","text": "A curved or hooked acromion (Type II/III)"},{"key": "C","text": "Weak deltoid muscle"},{"key": "D","text": "A flat acromion type"}],"correct": "B","explanation": "Curved (Type II) or hooked (Type III) acromion morphology reduces the subacromial space, predisposing to mechanical (outlet) impingement."},{"id": 7395,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "'Internal impingement' of the shoulder, seen commonly in overhead throwing athletes, involves contact between which structures?","options": [{"key": "A","text": "Undersurface of the rotator cuff and posterosuperior glenoid labrum"},{"key": "B","text": "Subacromial bursa and acromion"},{"key": "C","text": "Biceps tendon and coracoid process only"},{"key": "D","text": "AC joint structures only"}],"correct": "A","explanation": "Internal impingement occurs when the articular surface of the rotator cuff contacts the posterosuperior glenoid labrum during the late cocking phase of throwing."},{"id": 7396,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "A full-thickness rotator cuff tear is best confirmed with which imaging modality?","options": [{"key": "A","text": "CT scan alone"},{"key": "B","text": "MRI or ultrasound"},{"key": "C","text": "Plain X-ray alone"},{"key": "D","text": "Bone scan"}],"correct": "B","explanation": "MRI and diagnostic ultrasound are the primary imaging modalities for confirming and characterizing rotator cuff tears, offering good soft tissue visualization."},{"id": 7397,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Conservative management of a small, chronic, degenerative rotator cuff tear in an older, lower-demand patient typically includes:","options": [{"key": "A","text": "Immediate surgical repair regardless of symptoms"},{"key": "B","text": "Complete shoulder immobilization"},{"key": "C","text": "No treatment recommended"},{"key": "D","text": "Physiotherapy focusing on strengthening the remaining cuff and periscapular muscles, activity modification"}],"correct": "D","explanation": "Many chronic degenerative tears, especially in lower-demand older patients, are managed conservatively with a structured strengthening and activity modification program."},{"id": 7398,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Calcific tendinitis of the shoulder most commonly affects which tendon?","options": [{"key": "A","text": "Supraspinatus"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Teres minor"},{"key": "D","text": "Infraspinatus"}],"correct": "A","explanation": "Calcific tendinitis, involving calcium hydroxyapatite deposition, most frequently occurs within the supraspinatus tendon."},{"id": 7399,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "The acute 'resorptive' phase of calcific tendinitis is characterized by:","options": [{"key": "A","text": "Chronic, mild, well-tolerated pain"},{"key": "B","text": "Severe, often intense acute pain as the body resorbs the calcium deposit"},{"key": "C","text": "Gradual onset over years"},{"key": "D","text": "Complete absence of symptoms"}],"correct": "B","explanation": "The resorptive phase, when the body actively breaks down the calcium deposit, is often associated with severe acute pain, sometimes mimicking a more serious pathology."},{"id": 7400,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Adhesive capsulitis (frozen shoulder) characteristically shows restriction in which pattern of motion?","options": [{"key": "A","text": "No restriction pattern, purely random"},{"key": "B","text": "Isolated loss of flexion only"},{"key": "C","text": "Capsular pattern with external rotation most limited, followed by abduction and internal rotation"},{"key": "D","text": "Isolated loss of internal rotation only"}],"correct": "C","explanation": "Frozen shoulder classically demonstrates a capsular pattern of restriction with external rotation most limited, followed by abduction, then internal rotation."},{"id": 7401,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which condition is a recognized risk factor for developing secondary adhesive capsulitis?","options": [{"key": "A","text": "Prolonged immobilization after shoulder injury/surgery, or diabetes"},{"key": "B","text": "Excellent glycemic control"},{"key": "C","text": "Regular shoulder exercise"},{"key": "D","text": "High shoulder mobility baseline"}],"correct": "A","explanation": "Prolonged immobilization and diabetes mellitus are well-recognized risk factors predisposing individuals to adhesive capsulitis."},{"id": 7402,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Physiotherapy management during the 'freezing' (painful) phase of adhesive capsulitis typically emphasizes:","options": [{"key": "A","text": "Pain management and gentle mobility within tolerable limits, avoiding aggressive stretching"},{"key": "B","text": "High-intensity strengthening"},{"key": "C","text": "Aggressive stretching to end range"},{"key": "D","text": "Complete immobilization"}],"correct": "A","explanation": "During the painful freezing phase, gentle, pain-guided mobility and pain management strategies are favored over aggressive stretching, which may exacerbate irritability."},{"id": 7403,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Physiotherapy management during the 'thawing' phase of adhesive capsulitis can more appropriately include:","options": [{"key": "A","text": "No treatment necessary"},{"key": "B","text": "Progressive stretching and mobilization techniques to restore range of motion"},{"key": "C","text": "Surgical referral in all cases"},{"key": "D","text": "Only rest and immobilization"}],"correct": "B","explanation": "As irritability decreases in the thawing phase, more assertive stretching and joint mobilization techniques can be progressively introduced to restore motion."},{"id": 7404,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Scapular dyskinesis refers to:","options": [{"key": "A","text": "Normal, symmetric scapular movement"},{"key": "B","text": "A specific fracture of the scapula"},{"key": "C","text": "A type of rotator cuff tear"},{"key": "D","text": "Altered/abnormal scapular position or motion pattern during arm movement"}],"correct": "D","explanation": "Scapular dyskinesis describes observable alterations in scapular position or movement patterns, which may contribute to or result from shoulder dysfunction."},{"id": 7405,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which muscle weakness/imbalance is commonly implicated in scapular dyskinesis with excessive scapular winging?","options": [{"key": "A","text": "Weak pectoralis minor only"},{"key": "B","text": "Overactive lower trapezius"},{"key": "C","text": "Overactive serratus anterior"},{"key": "D","text": "Weak or inhibited serratus anterior and/or lower trapezius"}],"correct": "D","explanation": "Weakness or inhibition of serratus anterior and/or lower trapezius commonly contributes to scapular dyskinesis and winging patterns."},{"id": 7406,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Glenohumeral internal rotation deficit (GIRD), commonly seen in overhead athletes, refers to:","options": [{"key": "A","text": "Normal symmetric rotation range"},{"key": "B","text": "Loss of external rotation only"},{"key": "C","text": "Excessive internal rotation range compared to external rotation"},{"key": "D","text": "A significant loss of internal rotation range of motion compared to the contralateral shoulder"}],"correct": "D","explanation": "GIRD describes a clinically significant loss of glenohumeral internal rotation range, often from posterior capsule tightness, common in throwing athletes."},{"id": 7407,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Long head of biceps tendinopathy classically presents with pain localized to which region?","options": [{"key": "A","text": "Posterior shoulder"},{"key": "B","text": "Anterior shoulder over the bicipital groove"},{"key": "C","text": "Lateral elbow"},{"key": "D","text": "Medial scapular border"}],"correct": "B","explanation": "Biceps tendinopathy typically causes anterior shoulder pain localized over the bicipital (intertubercular) groove."},{"id": 7408,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "A SLAP (Superior Labrum Anterior to Posterior) lesion involves injury to which structure?","options": [{"key": "A","text": "Rotator cuff tendons"},{"key": "B","text": "Acromioclavicular ligament"},{"key": "C","text": "Superior glenoid labrum, including the biceps anchor"},{"key": "D","text": "Coracoacromial ligament"}],"correct": "C","explanation": "SLAP lesions involve tearing of the superior labrum extending from anterior to posterior, often involving the biceps tendon anchor."},{"id": 7409,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Acromioclavicular (AC) joint osteoarthritis commonly presents with pain aggravated by which movement/position?","options": [{"key": "A","text": "Wrist extension"},{"key": "B","text": "Cross-body (horizontal) adduction and end-range overhead elevation"},{"key": "C","text": "Elbow flexion"},{"key": "D","text": "Shoulder abduction below 60 degrees"}],"correct": "B","explanation": "AC joint osteoarthritis typically causes localized pain aggravated by movements that compress or stress the joint, such as cross-body adduction and full overhead reaching."},{"id": 7410,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Suprascapular nerve entrapment at the spinoglenoid notch primarily affects which muscle?","options": [{"key": "A","text": "Infraspinatus (isolated, if entrapment is distal to supraspinatus branch)"},{"key": "B","text": "Deltoid"},{"key": "C","text": "Supraspinatus"},{"key": "D","text": "Subscapularis"}],"correct": "A","explanation": "Entrapment specifically at the spinoglenoid notch (distal to the suprascapular notch) selectively affects infraspinatus, sparing supraspinatus."},{"id": 7411,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which condition presents with painless, progressive winging of the scapula due to long thoracic nerve palsy affecting serratus anterior?","options": [{"key": "A","text": "Serratus anterior palsy (long thoracic nerve injury)"},{"key": "B","text": "AC joint separation"},{"key": "C","text": "Rotator cuff tear"},{"key": "D","text": "Adhesive capsulitis"}],"correct": "A","explanation": "Long thoracic nerve injury causes serratus anterior weakness/paralysis, resulting in characteristic medial scapular winging, often without significant pain."},{"id": 7412,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Thoracic outlet syndrome can present with which category of symptoms depending on the structure compressed?","options": [{"key": "A","text": "Only cardiac symptoms"},{"key": "B","text": "Only visual disturbances"},{"key": "C","text": "Neurogenic, vascular (arterial/venous), or combined symptoms"},{"key": "D","text": "Only motor symptoms"}],"correct": "C","explanation": "TOS symptoms vary based on whether the brachial plexus (neurogenic), subclavian artery, or subclavian vein is compressed, producing correspondingly different symptom patterns."},{"id": 7413,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Pectoralis minor tightness is often implicated as a contributing factor in which shoulder condition?","options": [{"key": "A","text": "Thoracic outlet syndrome and altered scapular position/impingement"},{"key": "B","text": "Bicipital tendon rupture"},{"key": "C","text": "AC joint arthritis"},{"key": "D","text": "Sternoclavicular dislocation"}],"correct": "A","explanation": "Tight pectoralis minor can contribute to altered scapular resting position and has been implicated in some presentations of thoracic outlet syndrome and secondary impingement."},{"id": 7414,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Massive irreparable rotator cuff tears in select patients may be managed surgically with which procedure?","options": [{"key": "A","text": "Simple arthroscopic debridement in all cases"},{"key": "B","text": "No surgical options exist"},{"key": "C","text": "Reverse total shoulder arthroplasty"},{"key": "D","text": "Total shoulder arthroplasty only"}],"correct": "C","explanation": "Reverse total shoulder arthroplasty is specifically designed for patients with massive irreparable cuff tears and cuff tear arthropathy, utilizing deltoid function to power elevation."},{"id": 7415,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which special consideration is important when prescribing exercises for a patient with a rotator cuff tendinopathy in the early irritable stage?","options": [{"key": "A","text": "Complete avoidance of all shoulder movement"},{"key": "B","text": "High-velocity plyometric exercises immediately"},{"key": "C","text": "Avoiding painful arcs of motion and progressing load gradually within tolerable limits"},{"key": "D","text": "Immediate heavy overhead resistance training"}],"correct": "C","explanation": "In the early, more irritable stage, exercise prescription should avoid provocative painful ranges while gradually progressing load as tolerated, following a graded exposure approach."},{"id": 7416,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Post-operative rehabilitation after arthroscopic rotator cuff repair typically follows which general principle in the initial weeks?","options": [{"key": "A","text": "Immediate return to overhead sports"},{"key": "B","text": "Immediate full active range of motion and resistance training"},{"key": "C","text": "No restrictions at all from day one"},{"key": "D","text": "Protected passive/active-assisted ROM within surgeon-defined limits to protect the repair"}],"correct": "D","explanation": "Early post-operative phases typically emphasize protected passive or active-assisted motion to protect the healing repair, with active strengthening introduced later per protocol."},{"id": 7417,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "The 'critical zone' of relative hypovascularity in the supraspinatus tendon, predisposing it to degeneration, is located:","options": [{"key": "A","text": "Approximately 1-2 cm proximal to its insertion on the greater tuberosity"},{"key": "B","text": "At the muscle origin on the scapula"},{"key": "C","text": "Throughout the entire tendon uniformly"},{"key": "D","text": "At the muscle belly"}],"correct": "A","explanation": "The supraspinatus critical zone, an area of relative hypovascularity near its insertion, is particularly susceptible to degenerative changes and tearing."},{"id": 7418,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Scapulohumeral rhythm describes the coordinated ratio of movement between:","options": [{"key": "A","text": "Glenohumeral and scapulothoracic motion during arm elevation"},{"key": "B","text": "Hip and knee during gait"},{"key": "C","text": "Cervical and thoracic spine motion"},{"key": "D","text": "Elbow and wrist during forearm rotation"}],"correct": "A","explanation": "Scapulohumeral rhythm describes the coordinated relationship (commonly cited as approximately 2:1) between glenohumeral and scapulothoracic movement during arm elevation."},{"id": 7419,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which muscle's overactivity is commonly associated with impaired scapulohumeral rhythm and elevated/hiked scapular position?","options": [{"key": "A","text": "Rhomboid minor"},{"key": "B","text": "Serratus anterior"},{"key": "C","text": "Lower trapezius"},{"key": "D","text": "Upper trapezius (relative to lower trapezius/serratus anterior)"}],"correct": "D","explanation": "Overactivity/dominance of upper trapezius relative to lower trapezius and serratus anterior is commonly implicated in altered scapular kinematics and elevated resting scapular position."},{"id": 7420,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which clinical test combination is often used together to increase diagnostic accuracy for rotator cuff tears?","options": [{"key": "A","text": "A cluster of tests (e.g., painful arc, external rotation weakness, infraspinatus test) improves diagnostic accuracy"},{"key": "B","text": "A single isolated test alone is always sufficient"},{"key": "C","text": "No tests have any diagnostic value"},{"key": "D","text": "Only imaging is used, clinical tests are never combined"}],"correct": "A","explanation": "Combining multiple clinical tests into a cluster generally improves diagnostic accuracy for rotator cuff pathology compared to relying on a single test in isolation."},{"id": 7421,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Post-traumatic shoulder stiffness following prolonged immobilization (e.g., after fracture) primarily requires which physiotherapy approach initially?","options": [{"key": "A","text": "No intervention, will resolve spontaneously"},{"key": "B","text": "Immediate aggressive manipulation under anesthesia in all cases"},{"key": "C","text": "Gradual, progressive mobility exercises and manual therapy within tissue tolerance"},{"key": "D","text": "Surgical release as first-line management always"}],"correct": "C","explanation": "Post-immobilization stiffness is generally managed with progressive, graded mobility exercises and manual therapy, reserving more aggressive interventions for refractory cases."},{"id": 7422,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Os acromiale, a failure of fusion of an acromial ossification center, can predispose to which condition?","options": [{"key": "A","text": "AC joint dislocation"},{"key": "B","text": "Adhesive capsulitis"},{"key": "C","text": "Biceps tendon rupture"},{"key": "D","text": "Subacromial impingement due to instability of the unfused fragment"}],"correct": "D","explanation": "An unfused os acromiale can create instability of the acromial fragment, contributing to subacromial impingement symptoms."},{"id": 7423,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which shoulder condition is characterized by a positive 'sulcus sign' with inferior traction on an adducted arm?","options": [{"key": "A","text": "Rotator cuff tear"},{"key": "B","text": "AC joint separation"},{"key": "C","text": "Multidirectional/inferior glenohumeral instability"},{"key": "D","text": "Adhesive capsulitis"}],"correct": "C","explanation": "A positive sulcus sign, showing a visible gap below the acromion with inferior traction, indicates inferior glenohumeral laxity/instability."},{"id": 7424,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Overhead throwing athletes with internal impingement often show adaptive changes in which structure?","options": [{"key": "A","text": "Symmetric rotation range bilaterally"},{"key": "B","text": "No adaptive changes occur"},{"key": "C","text": "Reduced external rotation only"},{"key": "D","text": "Increased external rotation with GIRD (reduced internal rotation)"}],"correct": "D","explanation": "Throwing athletes commonly develop increased external rotation range with a corresponding glenohumeral internal rotation deficit (GIRD) on the dominant throwing shoulder."},{"id": 7425,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which of the following best describes 'proprioceptive' rehabilitation exercises for shoulder instability?","options": [{"key": "A","text": "High-resistance isolated strengthening only"},{"key": "B","text": "Static stretching alone"},{"key": "C","text": "Exercises challenging joint position sense and neuromuscular control (e.g., rhythmic stabilization, closed-chain perturbation)"},{"key": "D","text": "Purely passive stretching exercises"}],"correct": "C","explanation": "Proprioceptive/neuromuscular training uses techniques like rhythmic stabilization and perturbation exercises to enhance joint position sense and dynamic stability, particularly important in instability rehabilitation."},{"id": 7426,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "A positive 'painful arc' test during shoulder abduction is most typically found between which range?","options": [{"key": "A","text": "0-30 degrees"},{"key": "B","text": "60-120 degrees"},{"key": "C","text": "No specific range is typical"},{"key": "D","text": "150-180 degrees"}],"correct": "B","explanation": "A painful arc between approximately 60-120 degrees of abduction is characteristic of subacromial impingement/rotator cuff pathology."},{"id": 7427,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Cuff tear arthropathy refers to:","options": [{"key": "A","text": "Acute traumatic dislocation"},{"key": "B","text": "Degenerative glenohumeral joint changes secondary to chronic massive rotator cuff deficiency"},{"key": "C","text": "Simple bicipital tendinopathy"},{"key": "D","text": "Isolated AC joint arthritis"}],"correct": "B","explanation": "Cuff tear arthropathy describes the pattern of glenohumeral joint degeneration that develops secondary to long-standing, massive rotator cuff tears with loss of humeral head centering."},{"id": 7428,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Which exercise principle is emphasized in the rehabilitation of scapular dyskinesis?","options": [{"key": "A","text": "Restoring balanced activation of scapular stabilizers, especially serratus anterior and lower trapezius"},{"key": "B","text": "Complete avoidance of scapular exercises"},{"key": "C","text": "Isolated strengthening of upper trapezius only"},{"key": "D","text": "Static bracing alone without exercise"}],"correct": "A","explanation": "Rehabilitation of scapular dyskinesis focuses on restoring appropriate coordinated activation among scapular stabilizing muscles, particularly targeting serratus anterior and lower trapezius."},{"id": 7429,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Medium","question": "Post-arthroscopic Bankart repair for anterior instability typically requires protection from which movement combination in the early rehabilitation phase?","options": [{"key": "A","text": "Extension and internal rotation"},{"key": "B","text": "Combined abduction and external rotation (apprehension position)"},{"key": "C","text": "Internal rotation and adduction"},{"key": "D","text": "Flexion and internal rotation"}],"correct": "B","explanation": "Early post-Bankart repair rehabilitation avoids the combined abduction-external rotation position to protect the healing anterior labral repair."},{"id": 7430,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Which clinical presentation suggests a 'reverse Bankart' lesion associated with posterior instability?","options": [{"key": "A","text": "Superior labral tear only"},{"key": "B","text": "No labral involvement"},{"key": "C","text": "Anterior labral tear only"},{"key": "D","text": "Posterior labral tear associated with posterior shoulder instability"}],"correct": "D","explanation": "A reverse Bankart lesion refers to a posterior labral tear, analogous to the classic anterior Bankart lesion but associated with posterior instability."},{"id": 7431,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "The 'critical shoulder angle' is a radiographic measurement associated with increased risk of which two conditions at opposite ends of its spectrum?","options": [{"key": "A","text": "Only fractures"},{"key": "B","text": "Rotator cuff tears (larger angle) and osteoarthritis (smaller angle)"},{"key": "C","text": "Only AC joint separation"},{"key": "D","text": "No clinical correlation exists"}],"correct": "B","explanation": "A larger critical shoulder angle is associated with increased risk of rotator cuff tear, while a smaller angle correlates with increased osteoarthritis risk, reflecting altered glenoid-acromial biomechanics."},{"id": 7432,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Which condition classically presents with shoulder pain and weakness following a viral illness, with acute severe pain followed by patchy motor weakness (often affecting serratus anterior or supraspinatus)?","options": [{"key": "A","text": "Adhesive capsulitis"},{"key": "B","text": "Parsonage-Turner syndrome (neuralgic amyotrophy)"},{"key": "C","text": "AC joint arthritis"},{"key": "D","text": "Rotator cuff tendinopathy"}],"correct": "B","explanation": "Parsonage-Turner syndrome presents with acute severe shoulder/arm pain, often following a viral illness or stressor, followed by patchy motor weakness from brachial plexus inflammation."},{"id": 7433,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Postoperative rehabilitation following reverse total shoulder arthroplasty places particular emphasis on protecting which structure/function?","options": [{"key": "A","text": "Deltoid muscle integrity and avoiding excessive early stress on the prosthesis/deltoid"},{"key": "B","text": "AC joint stability only"},{"key": "C","text": "Rotator cuff repair integrity (as cuff is typically deficient)"},{"key": "D","text": "Biceps tendon repair"}],"correct": "A","explanation": "Since reverse arthroplasty relies on deltoid function (given cuff deficiency), rehabilitation protocols emphasize protecting deltoid integrity and appropriate progressive loading of the reconstructed joint."},{"id": 7434,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "Lateral epicondylalgia (tennis elbow) is typically aggravated by which activity?","options": [{"key": "A","text": "Passive wrist flexion only"},{"key": "B","text": "Resisted wrist flexion"},{"key": "C","text": "Resisted elbow flexion"},{"key": "D","text": "Resisted wrist extension and gripping activities"}],"correct": "D","explanation": "Lateral epicondylalgia symptoms are classically provoked by resisted wrist extension and gripping tasks, which load the extensor carpi radialis brevis."},{"id": 7435,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Which exercise approach has strong evidence for management of chronic lateral epicondylalgia?","options": [{"key": "A","text": "Immediate surgical intervention as first-line"},{"key": "B","text": "Complete rest with no exercise"},{"key": "C","text": "Progressive eccentric and/or isotonic loading exercises"},{"key": "D","text": "Aggressive passive stretching only, without loading"}],"correct": "C","explanation": "Progressive loading programs, including eccentric exercise, have good evidence supporting improved outcomes in chronic lateral epicondylalgia."},{"id": 7436,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "Cubital tunnel syndrome results from compression of which nerve at the elbow?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Median nerve"}],"correct": "A","explanation": "Cubital tunnel syndrome is the second most common upper limb nerve entrapment, involving ulnar nerve compression posterior to the medial epicondyle."},{"id": 7437,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Symptoms of cubital tunnel syndrome typically involve sensory changes in which fingers?","options": [{"key": "A","text": "Ring and little fingers (ulnar 1.5 digits)"},{"key": "B","text": "Thumb, index, and middle fingers"},{"key": "C","text": "Thumb only"},{"key": "D","text": "All five fingers equally"}],"correct": "A","explanation": "Ulnar nerve compression classically causes sensory symptoms in the ring and little fingers, corresponding to the ulnar nerve's cutaneous distribution."},{"id": 7438,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "Radial tunnel syndrome, involving compression of the posterior interosseous nerve, can mimic which more common condition, complicating diagnosis?","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "Cubital tunnel syndrome"},{"key": "C","text": "De Quervain's tenosynovitis"},{"key": "D","text": "Lateral epicondylalgia"}],"correct": "D","explanation": "Radial tunnel syndrome often presents with lateral forearm pain similar to lateral epicondylalgia, making differential diagnosis challenging."},{"id": 7439,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Distal biceps tendon rupture typically presents with which clinical sign?","options": [{"key": "A","text": "Wrist drop"},{"key": "B","text": "Increased elbow flexion strength"},{"key": "C","text": "A 'Popeye' deformity with proximal muscle belly retraction and loss of supination strength"},{"key": "D","text": "No visible deformity ever"}],"correct": "C","explanation": "Distal biceps rupture causes proximal retraction of the biceps muscle belly (reverse Popeye sign at the elbow) along with significant loss of supination strength."},{"id": 7440,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Olecranon bursitis commonly presents with which clinical finding?","options": [{"key": "A","text": "Superficial, often fluctuant swelling over the posterior elbow with relatively preserved range of motion"},{"key": "B","text": "Deep joint line tenderness with restricted ROM"},{"key": "C","text": "Numbness in the ulnar nerve distribution"},{"key": "D","text": "Complete loss of elbow flexion"}],"correct": "A","explanation": "Olecranon bursitis typically presents as a superficial, often visible swelling over the olecranon, with joint range of motion frequently preserved unless severely inflamed."},{"id": 7441,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Which condition should be considered if olecranon bursitis presents with significant warmth, erythema, and systemic symptoms (fever)?","options": [{"key": "A","text": "Septic bursitis requiring further medical evaluation"},{"key": "B","text": "Referred cervical pain"},{"key": "C","text": "Simple mechanical bursitis"},{"key": "D","text": "Chronic degenerative bursitis"}],"correct": "A","explanation": "Warmth, erythema, and systemic symptoms raise suspicion for septic bursitis, which requires prompt medical evaluation and possible aspiration/antibiotics, distinct from simple mechanical bursitis."},{"id": 7442,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Ulnar collateral ligament injury of the elbow is a common overuse injury in which population?","options": [{"key": "A","text": "Recreational swimmers"},{"key": "B","text": "Overhead throwing athletes (e.g., baseball pitchers)"},{"key": "C","text": "Cyclists"},{"key": "D","text": "Weightlifters performing squats"}],"correct": "B","explanation": "UCL injuries are classically associated with the repetitive valgus stress of overhead throwing, particularly in baseball pitchers."},{"id": 7443,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "Carpal tunnel syndrome results from compression of the median nerve, producing sensory symptoms typically in which fingers?","options": [{"key": "A","text": "Ring and little fingers"},{"key": "B","text": "Little finger only"},{"key": "C","text": "Thumb, index, middle, and radial half of ring finger"},{"key": "D","text": "All fingers equally including little finger"}],"correct": "C","explanation": "Median nerve compression in carpal tunnel syndrome classically affects sensation in the thumb, index, middle, and radial half of the ring finger."},{"id": 7444,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Which factor is a recognized risk factor for developing carpal tunnel syndrome?","options": [{"key": "A","text": "Younger age exclusively"},{"key": "B","text": "Regular wrist stretching exercises"},{"key": "C","text": "Pregnancy, diabetes, repetitive wrist activities, and hypothyroidism"},{"key": "D","text": "Male gender predominantly"}],"correct": "C","explanation": "Pregnancy, diabetes, hypothyroidism, and repetitive/forceful wrist activities are all recognized risk factors for carpal tunnel syndrome; it is also more common in women."},{"id": 7445,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Initial conservative management of mild-to-moderate carpal tunnel syndrome commonly includes:","options": [{"key": "A","text": "Night-time wrist splinting in neutral position and activity modification"},{"key": "B","text": "Complete wrist immobilization for months"},{"key": "C","text": "Immediate surgical release in all cases"},{"key": "D","text": "Aggressive wrist strengthening only"}],"correct": "A","explanation": "Conservative management typically begins with night splinting in a neutral wrist position and activity/ergonomic modification, reserving surgery for refractory or severe cases."},{"id": 7446,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Guyon's canal syndrome involves compression of which nerve at the wrist?","options": [{"key": "A","text": "Anterior interosseous nerve"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Guyon's canal syndrome results from ulnar nerve compression as it passes through Guyon's canal at the wrist, near the pisiform and hook of hamate."},{"id": 7447,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "De Quervain's tenosynovitis is often associated with which repetitive activity, sometimes termed 'mommy thumb'?","options": [{"key": "A","text": "Repetitive lifting of a child with thumb abduction/extension (e.g., new parents)"},{"key": "B","text": "Running"},{"key": "C","text": "Overhead throwing"},{"key": "D","text": "Prolonged sitting"}],"correct": "A","explanation": "De Quervain's tenosynovitis is commonly associated with repetitive thumb and wrist movements, classically seen in new parents lifting infants, hence the informal name 'mommy thumb'."},{"id": 7448,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Dupuytren's contracture primarily affects which structure in the hand?","options": [{"key": "A","text": "Palmar fascia, causing progressive flexion contracture typically of the ring/little fingers"},{"key": "B","text": "Median nerve"},{"key": "C","text": "Extensor tendons"},{"key": "D","text": "Flexor tendon sheaths"}],"correct": "A","explanation": "Dupuytren's contracture involves progressive thickening and contracture of the palmar fascia, most commonly affecting the ring and little fingers."},{"id": 7449,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Mallet finger deformity results from injury to which structure?","options": [{"key": "A","text": "Flexor digitorum profundus at the DIP joint"},{"key": "B","text": "Terminal extensor tendon at its insertion on the distal phalanx"},{"key": "C","text": "Volar plate of the PIP joint"},{"key": "D","text": "Central slip of extensor tendon"}],"correct": "B","explanation": "Mallet finger results from disruption of the terminal extensor tendon (or associated bony avulsion) at the DIP joint, causing an inability to actively extend the distal phalanx."},{"id": 7450,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "Boutonniere deformity results from injury to which structure?","options": [{"key": "A","text": "Terminal extensor tendon"},{"key": "B","text": "Central slip of the extensor tendon at the PIP joint"},{"key": "C","text": "Ulnar collateral ligament of MCP"},{"key": "D","text": "Flexor digitorum superficialis"}],"correct": "B","explanation": "Boutonniere deformity results from central slip disruption at the PIP joint, causing the PIP joint to flex while the DIP joint hyperextends."},{"id": 7451,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "Swan-neck deformity of the finger is characterized by which joint position pattern?","options": [{"key": "A","text": "MCP hyperextension only"},{"key": "B","text": "PIP hyperextension with DIP flexion"},{"key": "C","text": "No characteristic pattern"},{"key": "D","text": "PIP flexion with DIP extension"}],"correct": "B","explanation": "Swan-neck deformity presents with PIP joint hyperextension combined with DIP joint flexion, often related to intrinsic muscle tightness or volar plate laxity."},{"id": 7452,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Skier's/gamekeeper's thumb involves injury to which ligament?","options": [{"key": "A","text": "Volar plate of the thumb IP joint"},{"key": "B","text": "Radial collateral ligament of the thumb MCP"},{"key": "C","text": "Ulnar collateral ligament of the thumb MCP joint"},{"key": "D","text": "Scapholunate ligament"}],"correct": "C","explanation": "This injury involves the ulnar collateral ligament of the thumb metacarpophalangeal joint, classically from a forceful radial/valgus stress (e.g., ski pole fall)."},{"id": 7453,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "A Stener lesion, complicating thumb UCL injury, refers to:","options": [{"key": "A","text": "A fracture of the thumb metacarpal"},{"key": "B","text": "A tendon rupture of flexor pollicis longus"},{"key": "C","text": "Interposition of the adductor pollicis aponeurosis preventing ligament healing, often requiring surgery"},{"key": "D","text": "A simple partial ligament tear"}],"correct": "C","explanation": "A Stener lesion occurs when the torn UCL becomes displaced superficial to the adductor aponeurosis, physically preventing normal apposition and healing, usually necessitating surgical repair."},{"id": 7454,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "Kienbock's disease refers to avascular necrosis of which carpal bone?","options": [{"key": "A","text": "Lunate"},{"key": "B","text": "Scaphoid"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Capitate"}],"correct": "A","explanation": "Kienbock's disease is avascular necrosis of the lunate, thought to relate to its vascular supply and repetitive loading, particularly in patients with negative ulnar variance."},{"id": 7455,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "Trigger finger commonly presents with which clinical symptom?","options": [{"key": "A","text": "Catching or locking of the finger in flexion, often with a painful click on extension"},{"key": "B","text": "Numbness in the fingertip"},{"key": "C","text": "Painless clicking with no functional limitation"},{"key": "D","text": "Complete inability to flex the finger"}],"correct": "A","explanation": "Trigger finger characteristically presents with catching/locking during finger flexion-extension, often with a palpable/audible snap as the nodule passes through the A1 pulley."},{"id": 7456,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Initial conservative management of trigger finger may include:","options": [{"key": "A","text": "Complete finger amputation"},{"key": "B","text": "Immediate surgical release in all cases"},{"key": "C","text": "Aggressive stretching alone without other measures"},{"key": "D","text": "Splinting the MCP joint, activity modification, and corticosteroid injection"}],"correct": "D","explanation": "Conservative management options for trigger finger include splinting, activity modification, and corticosteroid injection, with surgical release reserved for refractory cases."},{"id": 7457,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "Which nerve injury classically causes 'wrist drop' due to loss of wrist and finger extension?","options": [{"key": "A","text": "Radial nerve palsy"},{"key": "B","text": "Ulnar nerve palsy"},{"key": "C","text": "Median nerve palsy"},{"key": "D","text": "Musculocutaneous nerve palsy"}],"correct": "A","explanation": "Radial nerve palsy results in wrist drop due to paralysis of the wrist and finger extensor muscles."},{"id": 7458,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "A high ulnar nerve lesion (at or above the elbow) classically produces which deformity, sometimes paradoxically less severe than a low lesion?","options": [{"key": "A","text": "Complete hand paralysis"},{"key": "B","text": "Wrist drop"},{"key": "C","text": "Ulnar claw hand, sometimes less pronounced than a distal lesion due to concurrent FDP paralysis ('ulnar paradox')"},{"key": "D","text": "Ape hand deformity"}],"correct": "C","explanation": "In a high ulnar lesion, concurrent paralysis of the ulnar half of flexor digitorum profundus reduces the clawing effect on the ring/little fingers compared to a distal (wrist-level) lesion — the 'ulnar paradox'."},{"id": 7459,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "'Ape hand' deformity, with the thumb lying flat in the plane of the palm, is classically associated with which nerve injury?","options": [{"key": "A","text": "Radial nerve palsy"},{"key": "B","text": "Axillary nerve palsy"},{"key": "C","text": "Ulnar nerve palsy"},{"key": "D","text": "Median nerve palsy (particularly affecting thenar muscles)"}],"correct": "D","explanation": "Median nerve palsy, particularly with thenar muscle paralysis (loss of opposition/abduction), can result in an 'ape hand' deformity due to unopposed extensor/adductor action on the thumb."},{"id": 7460,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "A scapholunate ligament injury can lead to which pattern of carpal instability if untreated?","options": [{"key": "A","text": "Volar intercalated segment instability (VISI)"},{"key": "B","text": "Kienbock's disease"},{"key": "C","text": "Dorsal intercalated segment instability (DISI)"},{"key": "D","text": "No long-term consequences"}],"correct": "C","explanation": "Scapholunate ligament disruption commonly leads to dorsal intercalated segment instability (DISI), characterized by abnormal lunate extension on imaging."},{"id": 7461,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Post-fracture wrist stiffness (e.g., after distal radius fracture) rehabilitation typically progresses from:","options": [{"key": "A","text": "Immediate resisted strengthening only"},{"key": "B","text": "Complete avoidance of movement indefinitely"},{"key": "C","text": "Gentle active/active-assisted ROM progressing to strengthening and functional activities as healing allows"},{"key": "D","text": "Passive stretching alone throughout the entire program"}],"correct": "C","explanation": "Rehabilitation typically progresses in a graded fashion from gentle mobility work toward strengthening and functional retraining as tissue healing and tolerance permit."},{"id": 7462,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Which functional grip pattern is most compromised by significant carpal tunnel syndrome affecting thenar muscle strength?","options": [{"key": "A","text": "Pincer/precision grip involving thumb opposition"},{"key": "B","text": "Power grip using the ulnar fingers"},{"key": "C","text": "Hook grip"},{"key": "D","text": "Cylindrical grasp using little finger primarily"}],"correct": "A","explanation": "Thenar weakness from median nerve compromise particularly affects fine precision/pincer grip requiring thumb opposition and abduction."},{"id": 7463,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Elbow flexion contracture is a common long-term complication following which type of injury if not adequately rehabilitated?","options": [{"key": "A","text": "Shoulder impingement"},{"key": "B","text": "Wrist sprain"},{"key": "C","text": "Elbow trauma/dislocation with prolonged immobilization"},{"key": "D","text": "Ankle sprain"}],"correct": "C","explanation": "The elbow joint is particularly prone to stiffness and flexion contracture after trauma or prolonged immobilization, making early appropriate mobilization important."},{"id": 7464,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Which manual technique is commonly used to address joint stiffness/restricted accessory motion in the wrist following immobilization?","options": [{"key": "A","text": "Passive physiological stretching alone"},{"key": "B","text": "Strengthening exercises exclusively, without any mobility work"},{"key": "C","text": "Joint mobilization techniques targeting specific accessory (glide) motions"},{"key": "D","text": "Ultrasound therapy alone"}],"correct": "C","explanation": "Joint mobilization techniques, addressing specific accessory glides, are commonly used alongside other interventions to restore restricted wrist joint mobility."},{"id": 7465,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "A common compensatory pattern seen with weak grip strength following nerve injury or immobilization involves overuse of which structures?","options": [{"key": "A","text": "Only the affected muscles, with no compensation"},{"key": "B","text": "Only contralateral limb muscles"},{"key": "C","text": "No compensatory patterns occur"},{"key": "D","text": "Proximal muscles (wrist/forearm) attempting to substitute for weak intrinsic hand muscles"}],"correct": "D","explanation": "Patients with weak intrinsic hand muscles often compensate by overusing proximal wrist/forearm musculature, which should be addressed in a comprehensive rehabilitation program."},{"id": 7466,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Which condition, presenting with numbness/tingling in the hand at night, may sometimes be confused with cervical radiculopathy, requiring careful differential diagnosis?","options": [{"key": "A","text": "Rotator cuff tear"},{"key": "B","text": "Ankle sprain"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "Achilles tendinopathy"}],"correct": "C","explanation": "Nocturnal hand numbness/tingling from carpal tunnel syndrome can sometimes overlap symptomatically with cervical radiculopathy, requiring careful clinical differentiation."},{"id": 7467,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "Which special test combination is often used in the clinical diagnosis of carpal tunnel syndrome?","options": [{"key": "A","text": "Finkelstein's test and Watson's test"},{"key": "B","text": "Cozen's test and Mill's test"},{"key": "C","text": "Phalen's test and Tinel's sign at the wrist"},{"key": "D","text": "Spurling's test and distraction test"}],"correct": "C","explanation": "Phalen's test and Tinel's sign at the wrist are the two most commonly used provocative tests to support a clinical diagnosis of carpal tunnel syndrome."},{"id": 7468,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Nerve gliding (neurodynamic) exercises are sometimes incorporated into carpal tunnel syndrome management with the aim of:","options": [{"key": "A","text": "Increasing local inflammation"},{"key": "B","text": "Compressing the nerve further"},{"key": "C","text": "Promoting mobility of the median nerve relative to surrounding structures within its tolerance"},{"key": "D","text": "Replacing the need for splinting entirely"}],"correct": "C","explanation": "Nerve gliding exercises aim to promote relative mobility of the nerve within its surrounding tissues, used cautiously as part of a broader conservative management approach."},{"id": 7469,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Medium","question": "Post-operative management following carpal tunnel release surgery typically emphasizes early:","options": [{"key": "A","text": "No follow-up rehabilitation required"},{"key": "B","text": "Complete hand immobilization for 6 weeks"},{"key": "C","text": "Early active finger/wrist motion within surgical guidelines to prevent stiffness and promote nerve gliding"},{"key": "D","text": "Aggressive strengthening on day one"}],"correct": "C","explanation": "Early active motion within the surgeon's guidelines is generally emphasized post-carpal tunnel release to prevent stiffness/adhesions and support nerve recovery."},{"id": 7470,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "Which grip strength assessment tool is commonly used to objectively quantify hand grip strength in clinical practice?","options": [{"key": "A","text": "Goniometer"},{"key": "B","text": "Inclinometer"},{"key": "C","text": "Dynamometer (e.g., Jamar hand dynamometer)"},{"key": "D","text": "Pedometer"}],"correct": "C","explanation": "The Jamar hand dynamometer is a widely used, standardized tool for objectively measuring grip strength in clinical practice."},{"id": 7471,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Hard","question": "Intersection syndrome of the wrist/forearm involves inflammation at the crossing point of which two muscle groups' tendons?","options": [{"key": "A","text": "Extensor pollicis longus and extensor carpi radialis"},{"key": "B","text": "Flexor digitorum superficialis and profundus"},{"key": "C","text": "Flexor carpi radialis and palmaris longus"},{"key": "D","text": "First dorsal compartment (APL/EPB) crossing over the second dorsal compartment (ECRL/ECRB)"}],"correct": "D","explanation": "Intersection syndrome occurs at the point where the first dorsal compartment tendons cross over the second dorsal compartment tendons, causing localized dorsal forearm pain and crepitus."},{"id": 7472,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Easy","question": "Osteoarthritis of the hip typically presents with pain localized to which region initially?","options": [{"key": "A","text": "Lateral hip only"},{"key": "B","text": "Groin, with possible referral to anterior thigh or knee"},{"key": "C","text": "Posterior buttock exclusively"},{"key": "D","text": "Lower back only"}],"correct": "B","explanation": "Hip OA classically presents with groin pain, which may radiate to the anterior thigh or, notably, refer to the knee."},{"id": 7473,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Which capsular pattern is classically associated with hip osteoarthritis?","options": [{"key": "A","text": "Extension most limited, followed by adduction"},{"key": "B","text": "Flexion most limited, followed by abduction and external rotation"},{"key": "C","text": "Internal rotation most limited, followed by flexion and abduction"},{"key": "D","text": "No consistent capsular pattern exists for the hip"}],"correct": "C","explanation": "The hip capsular pattern classically shows internal rotation as most limited, followed by flexion and abduction, with relative preservation of extension and external rotation."},{"id": 7474,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Femoroacetabular impingement (FAI) is classified into which two main morphological types?","options": [{"key": "A","text": "Cam and pincer type"},{"key": "B","text": "Anterior and posterior type only"},{"key": "C","text": "Varus and valgus type"},{"key": "D","text": "Superior and inferior type"}],"correct": "A","explanation": "FAI is classified as cam-type (abnormal femoral head-neck junction), pincer-type (excessive acetabular coverage), or a mixed/combined type."},{"id": 7475,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Cam-type femoroacetabular impingement involves an abnormality of which structure?","options": [{"key": "A","text": "Labral hypertrophy only"},{"key": "B","text": "Acetabular rim overcoverage"},{"key": "C","text": "Femoral head-neck junction (aspherical/bump)"},{"key": "D","text": "Ligamentum teres"}],"correct": "C","explanation": "Cam-type FAI involves an aspherical femoral head or bony prominence at the head-neck junction, causing abnormal contact with the acetabulum during hip flexion/internal rotation."},{"id": 7476,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Pincer-type femoroacetabular impingement involves an abnormality of which structure?","options": [{"key": "A","text": "Ligamentum teres"},{"key": "B","text": "Acetabulum (excessive coverage/overcoverage of the femoral head)"},{"key": "C","text": "Iliopsoas tendon only"},{"key": "D","text": "Femoral head-neck offset"}],"correct": "B","explanation": "Pincer-type FAI results from excessive acetabular coverage of the femoral head (e.g., acetabular retroversion or global overcoverage), causing abnormal rim contact."},{"id": 7477,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Which special test is commonly positive in patients with femoroacetabular impingement or labral pathology?","options": [{"key": "A","text": "Trendelenburg test"},{"key": "B","text": "Thomas test"},{"key": "C","text": "FADIR test (Flexion, Adduction, Internal Rotation)"},{"key": "D","text": "Ober's test"}],"correct": "C","explanation": "The FADIR test (hip flexion, adduction, internal rotation) is commonly used to provoke anterior hip/groin pain in FAI or labral pathology."},{"id": 7478,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Greater trochanteric pain syndrome (GTPS) most commonly involves pathology of which structure(s)?","options": [{"key": "A","text": "Gluteus medius/minimus tendinopathy and/or trochanteric bursitis"},{"key": "B","text": "Iliopsoas tendon"},{"key": "C","text": "Rectus femoris"},{"key": "D","text": "Adductor longus"}],"correct": "A","explanation": "GTPS is now understood to primarily involve gluteus medius/minimus tendinopathy, often with associated trochanteric bursitis, rather than isolated bursitis alone."},{"id": 7479,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Easy","question": "Which activity classically aggravates greater trochanteric pain syndrome?","options": [{"key": "A","text": "Swimming with a kickboard"},{"key": "B","text": "Side-lying on the affected hip, stair climbing, and prolonged standing on one leg"},{"key": "C","text": "Standing on both feet symmetrically"},{"key": "D","text": "Seated activities only"}],"correct": "B","explanation": "GTPS symptoms are typically aggravated by direct compression (side-lying) and activities loading the hip abductors, such as stair climbing or single-leg standing."},{"id": 7480,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Iliopsoas tendinopathy/bursitis commonly presents with pain localized to which region, aggravated by resisted hip flexion?","options": [{"key": "A","text": "Lateral knee"},{"key": "B","text": "Posterior buttock"},{"key": "C","text": "Anterior groin/hip"},{"key": "D","text": "Lateral hip"}],"correct": "C","explanation": "Iliopsoas pathology typically causes anterior groin pain, aggravated by resisted hip flexion or passive hip extension stretch."},{"id": 7481,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Snapping hip syndrome (coxa saltans) can result from which structure snapping over the greater trochanter (external type)?","options": [{"key": "A","text": "Rectus femoris tendon"},{"key": "B","text": "Iliopsoas tendon over the iliopectineal eminence"},{"key": "C","text": "Sartorius muscle"},{"key": "D","text": "Iliotibial band/tensor fasciae latae"}],"correct": "D","explanation": "External snapping hip syndrome most commonly results from the iliotibial band or tensor fasciae latae snapping over the greater trochanter."},{"id": 7482,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Internal snapping hip syndrome typically results from which structure?","options": [{"key": "A","text": "Iliotibial band over the greater trochanter"},{"key": "B","text": "Iliopsoas tendon snapping over the iliopectineal eminence or femoral head"},{"key": "C","text": "Gluteus maximus tendon"},{"key": "D","text": "Piriformis tendon"}],"correct": "B","explanation": "Internal snapping hip is caused by the iliopsoas tendon snapping over a bony prominence (iliopectineal eminence or femoral head) during hip movement."},{"id": 7483,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Piriformis syndrome presents with symptoms mimicking which more common condition, requiring careful differential diagnosis?","options": [{"key": "A","text": "Sciatica/lumbar radiculopathy"},{"key": "B","text": "Adhesive capsulitis"},{"key": "C","text": "Rotator cuff tendinopathy"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "A","explanation": "Piriformis syndrome can mimic lumbar radiculopathy/sciatica due to sciatic nerve irritation from the piriformis muscle, requiring careful clinical differentiation."},{"id": 7484,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Which examination finding may help differentiate piriformis syndrome from true lumbar radiculopathy?","options": [{"key": "A","text": "Positive Tinel's sign at the wrist"},{"key": "B","text": "Identical presentation with no distinguishing features"},{"key": "C","text": "Positive straight leg raise in both conditions equally"},{"key": "D","text": "Absence of true lumbar spine signs (e.g., normal reflexes) with positive piriformis-specific provocation tests (e.g., FAIR test)"}],"correct": "D","explanation": "Piriformis syndrome typically lacks true lumbar spine neurological signs and shows positive provocation with piriformis-specific tests, unlike lumbar radiculopathy which often shows dermatomal/myotomal deficits."},{"id": 7485,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Legg-Calve-Perthes disease refers to:","options": [{"key": "A","text": "Idiopathic avascular necrosis of the femoral head in children"},{"key": "B","text": "A traumatic hip dislocation in adults"},{"key": "C","text": "Congenital hip dysplasia"},{"key": "D","text": "Adult-onset osteoarthritis"}],"correct": "A","explanation": "Legg-Calve-Perthes disease is idiopathic avascular necrosis of the proximal femoral epiphysis occurring in children, typically aged 4-10 years."},{"id": 7486,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Slipped Capital Femoral Epiphysis (SCFE) typically occurs in which age group?","options": [{"key": "A","text": "Infants"},{"key": "B","text": "Adolescents, particularly during growth spurts (often obese males)"},{"key": "C","text": "Neonates"},{"key": "D","text": "Elderly patients"}],"correct": "B","explanation": "SCFE classically occurs in adolescents during rapid growth, with increased incidence in overweight/obese individuals, more commonly males."},{"id": 7487,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Total hip arthroplasty (THA) posterior surgical approach requires which specific movement precautions in early rehabilitation to protect against dislocation?","options": [{"key": "A","text": "Avoiding knee flexion only"},{"key": "B","text": "No specific precautions needed"},{"key": "C","text": "Avoiding hip flexion beyond 90 degrees, adduction past midline, and internal rotation"},{"key": "D","text": "Avoiding hip extension and external rotation only"}],"correct": "C","explanation": "Posterior approach THA precautions typically include avoiding combined hip flexion beyond 90 degrees, adduction, and internal rotation, as these positions risk posterior dislocation."},{"id": 7488,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Anterior approach total hip arthroplasty typically requires precautions against which movement combination, differing from posterior approach precautions?","options": [{"key": "A","text": "Excessive hip extension and external rotation"},{"key": "B","text": "Avoiding all weight-bearing"},{"key": "C","text": "No precautions ever required"},{"key": "D","text": "Excessive hip flexion only"}],"correct": "A","explanation": "Anterior approach THA generally requires precautions against combined hip extension and external rotation, which risks anterior dislocation, contrasting with posterior approach precautions."},{"id": 7489,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Post-THA rehabilitation typically progresses weight-bearing status based on:","options": [{"key": "A","text": "Surgeon's protocol, fixation type (cemented vs uncemented), and bone quality"},{"key": "B","text": "Time since surgery only, ignoring other factors"},{"key": "C","text": "Patient preference alone regardless of surgical factors"},{"key": "D","text": "No weight-bearing restriction ever applies"}],"correct": "A","explanation": "Weight-bearing progression after THA depends on surgeon-specific protocols, which factor in fixation method, bone quality, and surgical approach."},{"id": 7490,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Which of the following is a recognized long-term complication following total hip arthroplasty?","options": [{"key": "A","text": "Immediate full recovery with no risks"},{"key": "B","text": "Prosthetic loosening, dislocation, or periprosthetic fracture"},{"key": "C","text": "Complete elimination of all future hip issues"},{"key": "D","text": "Guaranteed improvement in unrelated joint conditions"}],"correct": "B","explanation": "Potential long-term complications of THA include component loosening, dislocation, infection, and periprosthetic fracture, among others."},{"id": 7491,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Hip labral tears commonly present with which symptom in addition to pain?","options": [{"key": "A","text": "Numbness in the entire lower limb"},{"key": "B","text": "Complete loss of hip motion"},{"key": "C","text": "Mechanical symptoms such as clicking, catching, or locking"},{"key": "D","text": "No functional limitation at all"}],"correct": "C","explanation": "Hip labral tears often produce mechanical symptoms including clicking, catching, or a sensation of locking, in addition to pain."},{"id": 7492,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Which imaging modality with intra-articular contrast is often used to improve diagnostic accuracy for hip labral tears?","options": [{"key": "A","text": "MR arthrography"},{"key": "B","text": "Bone scan"},{"key": "C","text": "Ultrasound alone"},{"key": "D","text": "Plain X-ray alone"}],"correct": "A","explanation": "MR arthrography, using intra-articular contrast, improves sensitivity for detecting labral tears compared to standard MRI alone."},{"id": 7493,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Adductor-related groin pain (adductor tendinopathy/strain) is commonly aggravated by which movement/test?","options": [{"key": "A","text": "Resisted knee extension"},{"key": "B","text": "Resisted hip adduction (e.g., squeeze test)"},{"key": "C","text": "Resisted hip abduction"},{"key": "D","text": "Passive ankle dorsiflexion"}],"correct": "B","explanation": "Adductor pathology is typically provoked by resisted hip adduction, often assessed clinically using an adductor squeeze test."},{"id": 7494,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Athletic pubalgia ('sports hernia') presents with chronic groin pain often related to imbalance between which muscle groups?","options": [{"key": "A","text": "Hip flexors and hip extensors only"},{"key": "B","text": "Abdominal muscles and hip adductors"},{"key": "C","text": "Quadriceps and hamstrings"},{"key": "D","text": "Gluteals and quadriceps"}],"correct": "B","explanation": "Athletic pubalgia is thought to relate to a biomechanical imbalance/instability at the pubic symphysis region between the abdominal muscles and hip adductors."},{"id": 7495,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Which condition presents with hip/groin pain and is associated with stress reaction/fracture of the femoral neck, requiring careful screening in runners with insidious groin pain?","options": [{"key": "A","text": "Adductor strain only"},{"key": "B","text": "Trochanteric bursitis only"},{"key": "C","text": "Femoral neck stress fracture"},{"key": "D","text": "Simple muscle strain"}],"correct": "C","explanation": "Femoral neck stress fractures should be considered in runners/athletes with insidious groin pain, as missed diagnosis risks progression to a displaced fracture."},{"id": 7496,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Which stress fracture location at the femoral neck carries higher risk of complication and is considered more urgent (compression vs tension side)?","options": [{"key": "A","text": "Only the shaft location matters"},{"key": "B","text": "Inferior/compression side (lower risk)"},{"key": "C","text": "No difference in risk by location"},{"key": "D","text": "Superior/tension side (higher risk of displacement)"}],"correct": "D","explanation": "Tension-side (superior) femoral neck stress fractures carry a higher risk of progression to complete/displaced fracture and generally require more urgent management than compression-side fractures."},{"id": 7497,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Hip osteoarthritis management with a strong evidence base includes which conservative approach as first-line?","options": [{"key": "A","text": "Exercise therapy (strengthening, aerobic) and education/self-management"},{"key": "B","text": "Complete rest and immobilization"},{"key": "C","text": "Long-term opioid use as first-line"},{"key": "D","text": "Immediate joint replacement in all cases"}],"correct": "A","explanation": "Exercise therapy combined with patient education is recommended as first-line conservative management for hip osteoarthritis before considering surgical intervention."},{"id": 7498,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Which muscle group weakness is commonly targeted in rehabilitation for hip osteoarthritis and related gait deviations?","options": [{"key": "A","text": "Only the hip flexors"},{"key": "B","text": "Only the ankle plantarflexors"},{"key": "C","text": "Hip abductors (gluteus medius) and extensors (gluteus maximus)"},{"key": "D","text": "Only the wrist extensors"}],"correct": "C","explanation": "Strengthening hip abductors and extensors is a key focus in hip OA rehabilitation, as weakness in these groups contributes to pain and gait abnormalities like Trendelenburg pattern."},{"id": 7499,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Avascular necrosis of the femoral head in adults is associated with which risk factor?","options": [{"key": "A","text": "Adequate hydration"},{"key": "B","text": "Regular exercise"},{"key": "C","text": "Low-impact activity only"},{"key": "D","text": "Corticosteroid use and excessive alcohol consumption"}],"correct": "D","explanation": "Corticosteroid use and excessive alcohol intake are well-recognized risk factors for adult avascular necrosis of the femoral head, along with trauma and other conditions."},{"id": 7500,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Transient osteoporosis of the hip, presenting with acute hip pain without trauma, is more commonly seen in which population?","options": [{"key": "A","text": "Children"},{"key": "B","text": "Middle-aged men and pregnant women (third trimester)"},{"key": "C","text": "Infants"},{"key": "D","text": "Elderly women with chronic OA"}],"correct": "B","explanation": "Transient osteoporosis of the hip is a self-limiting condition seen more often in middle-aged men and women in late pregnancy, presenting with acute onset hip pain."},{"id": 7501,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Ischiofemoral impingement involves abnormal contact/narrowing between which two structures?","options": [{"key": "A","text": "Greater trochanter and iliac crest"},{"key": "B","text": "Femoral head and acetabular rim"},{"key": "C","text": "Lesser trochanter/quadratus femoris region and the ischium"},{"key": "D","text": "Pubic symphysis structures only"}],"correct": "C","explanation": "Ischiofemoral impingement involves narrowing of the space between the lesser trochanter and ischium, potentially compressing the quadratus femoris muscle."},{"id": 7502,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Hip flexor tightness (e.g., iliopsoas) is commonly associated with which postural change?","options": [{"key": "A","text": "No effect on pelvic position"},{"key": "B","text": "Lateral pelvic tilt exclusively"},{"key": "C","text": "Anterior pelvic tilt and increased lumbar lordosis"},{"key": "D","text": "Posterior pelvic tilt and decreased lumbar lordosis"}],"correct": "C","explanation": "Tight hip flexors tend to pull the pelvis into anterior tilt, contributing to increased lumbar lordosis."},{"id": 7503,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Gluteus medius weakness contributes to which observed gait/functional deficit?","options": [{"key": "A","text": "No functional consequences"},{"key": "B","text": "Improved single-leg balance"},{"key": "C","text": "Excessive hip extension during swing"},{"key": "D","text": "Trendelenburg gait pattern and dynamic knee valgus during single-leg tasks"}],"correct": "D","explanation": "Weak gluteus medius commonly manifests as Trendelenburg gait and contributes to dynamic valgus collapse at the knee during single-leg loading activities."},{"id": 7504,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Hip osteoarthritis pain referred to the knee is explained by which anatomical/neurological principle?","options": [{"key": "A","text": "Always indicates concurrent knee pathology"},{"key": "B","text": "Shared innervation (obturator and femoral nerve branches supplying both hip and knee)"},{"key": "C","text": "Direct mechanical connection between the joints"},{"key": "D","text": "Coincidental unrelated pain"}],"correct": "B","explanation": "Referred knee pain in hip OA is explained by shared segmental innervation via branches of the obturator and femoral nerves supplying both joints."},{"id": 7505,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Which post-operative precaution is generally important regardless of THA surgical approach in the initial recovery period?","options": [{"key": "A","text": "No precautions of any kind are necessary"},{"key": "B","text": "Complete bed rest for 3 months"},{"key": "C","text": "Immediate return to high-impact sport"},{"key": "D","text": "Avoiding excessive combined extreme range of motion that stresses the new joint"}],"correct": "D","explanation": "Regardless of specific approach-based precautions, avoiding extreme combined ranges of motion that stress the reconstructed joint is a general principle in early THA recovery."},{"id": 7506,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Hip resurfacing arthroplasty differs from traditional total hip arthroplasty primarily by:","options": [{"key": "A","text": "Preserving more of the femoral head/neck with a cap-like prosthesis over the reshaped femoral head"},{"key": "B","text": "Not requiring any post-op rehabilitation"},{"key": "C","text": "Removing the entire pelvis"},{"key": "D","text": "Complete removal of the femoral head and neck"}],"correct": "A","explanation": "Hip resurfacing preserves more native femoral bone by capping the reshaped femoral head rather than removing it entirely, differing from conventional THA stem-based reconstruction."},{"id": 7507,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Hard","question": "Osteitis pubis, presenting with pain over the pubic symphysis, is commonly associated with which activity/population?","options": [{"key": "A","text": "Only manual laborers lifting heavy weights overhead"},{"key": "B","text": "Sedentary elderly patients"},{"key": "C","text": "Athletes involved in repetitive kicking, cutting, or running (e.g., soccer players)"},{"key": "D","text": "Only pregnant women"}],"correct": "C","explanation": "Osteitis pubis is commonly seen in athletes performing repetitive kicking, twisting, or high-load running activities, particularly in sports like soccer."},{"id": 7508,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Which clinical finding would raise 'red flag' concern in a patient presenting with hip pain, warranting further urgent medical investigation?","options": [{"key": "A","text": "Pain that improves with appropriate exercise"},{"key": "B","text": "Unexplained weight loss, night pain, or fever accompanying hip pain"},{"key": "C","text": "Pain relieved with rest"},{"key": "D","text": "Gradual onset pain with mechanical aggravating factors"}],"correct": "B","explanation": "Systemic symptoms such as unexplained weight loss, significant night pain, or fever alongside hip pain are red flags warranting investigation for serious pathology (e.g., malignancy, infection)."},{"id": 7509,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Functional outcome measures commonly used to assess hip osteoarthritis/hip pathology status include which of the following?","options": [{"key": "A","text": "Berg Balance Scale exclusively"},{"key": "B","text": "DASH score"},{"key": "C","text": "Hip disability and Osteoarthritis Outcome Score (HOOS) or Harris Hip Score"},{"key": "D","text": "Oswestry Disability Index only"}],"correct": "C","explanation": "The HOOS and Harris Hip Score are validated, commonly used patient-reported/clinician outcome measures specific to hip joint conditions."},{"id": 7510,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Easy","question": "Knee osteoarthritis most commonly affects which compartment of the knee?","options": [{"key": "A","text": "Patellofemoral compartment exclusively"},{"key": "B","text": "Lateral compartment predominantly"},{"key": "C","text": "Medial compartment predominantly"},{"key": "D","text": "All compartments equally in all patients"}],"correct": "C","explanation": "Medial compartment involvement is the most common pattern in knee OA, often associated with varus (bow-leg) malalignment."},{"id": 7511,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which postural/alignment change is commonly associated with medial compartment knee osteoarthritis?","options": [{"key": "A","text": "Genu valgum"},{"key": "B","text": "Genu recurvatum"},{"key": "C","text": "Genu varum"},{"key": "D","text": "No consistent alignment association"}],"correct": "C","explanation": "Genu varum (bow-legged alignment) increases medial compartment loading, both contributing to and resulting from medial knee OA progression."},{"id": 7512,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Easy","question": "First-line conservative management for knee osteoarthritis, strongly supported by evidence, includes:","options": [{"key": "A","text": "Exercise therapy (strengthening and aerobic) and weight management"},{"key": "B","text": "Long-term opioid analgesics as first choice"},{"key": "C","text": "Immediate arthroscopic debridement"},{"key": "D","text": "Complete joint immobilization"}],"correct": "A","explanation": "Exercise therapy and weight management are recommended as first-line, evidence-based conservative interventions for knee osteoarthritis."},{"id": 7513,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Total knee arthroplasty is generally considered for knee osteoarthritis when:","options": [{"key": "A","text": "Mild symptoms are present with good conservative response"},{"key": "B","text": "Patient is under 30 years old with mild OA"},{"key": "C","text": "Symptoms are present only in cold weather"},{"key": "D","text": "Significant pain and functional limitation persist despite adequate conservative management"}],"correct": "D","explanation": "TKA is typically reserved for patients with significant persistent pain and disability that has not adequately responded to conservative management options."},{"id": 7514,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "ACL injuries commonly occur via which mechanism in sports?","options": [{"key": "A","text": "Non-contact mechanism involving deceleration, pivoting, or landing with valgus/rotational stress"},{"key": "B","text": "Only through high-speed collision"},{"key": "C","text": "Chronic repetitive low-load activity"},{"key": "D","text": "Direct contact blow to the lateral knee only"}],"correct": "A","explanation": "The majority of ACL injuries occur via non-contact mechanisms during sudden deceleration, cutting, pivoting, or landing with knee valgus and rotational loading."},{"id": 7515,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which population shows a notably higher incidence of non-contact ACL injury, attributed partly to biomechanical and neuromuscular factors?","options": [{"key": "A","text": "Male athletes compared to female athletes"},{"key": "B","text": "No gender difference exists"},{"key": "C","text": "Female athletes compared to male athletes in similar sports"},{"key": "D","text": "Only older athletes above 50 years"}],"correct": "C","explanation": "Female athletes demonstrate a significantly higher incidence of non-contact ACL injury compared to males in comparable sports, attributed to anatomical, hormonal, and neuromuscular factors."},{"id": 7516,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Following ACL rupture, which structure often shows a characteristic bone bruise pattern on MRI, supporting the injury mechanism diagnosis?","options": [{"key": "A","text": "Patella only"},{"key": "B","text": "Lateral femoral condyle and posterolateral tibial plateau"},{"key": "C","text": "Fibular head only"},{"key": "D","text": "Medial femoral condyle and medial tibial plateau"}],"correct": "B","explanation": "A characteristic bone bruise pattern involving the lateral femoral condyle and posterolateral tibial plateau is commonly seen on MRI following ACL injury, reflecting the pivot-shift mechanism."},{"id": 7517,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "ACL reconstruction graft choices commonly include which of the following autograft options?","options": [{"key": "A","text": "Only synthetic grafts, autografts are never used"},{"key": "B","text": "Quadriceps muscle belly tissue only"},{"key": "C","text": "Bone-patellar tendon-bone (BPTB) and hamstring tendon (semitendinosus/gracilis) grafts"},{"key": "D","text": "Achilles tendon and plantaris only"}],"correct": "C","explanation": "Common autograft choices for ACL reconstruction include bone-patellar tendon-bone and hamstring tendon grafts, each with distinct advantages/disadvantages."},{"id": 7518,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Post-ACL reconstruction rehabilitation criteria for return to sport typically include which of the following?","options": [{"key": "A","text": "No criteria needed, return based on surgeon's calendar date only"},{"key": "B","text": "Time since surgery alone, regardless of functional testing"},{"key": "C","text": "Achieving specific strength symmetry, functional hop test performance, and psychological readiness"},{"key": "D","text": "Complete avoidance of all future sport participation"}],"correct": "C","explanation": "Modern return-to-sport criteria after ACL reconstruction incorporate objective strength and functional testing (e.g., hop tests, limb symmetry index) alongside psychological readiness, not just elapsed time."},{"id": 7519,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "A limb symmetry index (LSI) of what percentage or greater is commonly used as a benchmark for strength/functional testing prior to return to sport after ACL reconstruction?","options": [{"key": "A","text": "90%"},{"key": "B","text": "70%"},{"key": "C","text": "100% required, no exceptions"},{"key": "D","text": "50%"}],"correct": "A","explanation": "An LSI of approximately 90% or greater on strength and hop testing is commonly used as a benchmark, though this should be considered alongside other criteria."},{"id": 7520,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "PCL injuries commonly result from which mechanism?","options": [{"key": "A","text": "Valgus stress alone"},{"key": "B","text": "Direct anterior blow to the proximal tibia with knee flexed (e.g., dashboard injury) or hyperflexion with plantarflexed foot"},{"key": "C","text": "Non-contact pivoting"},{"key": "D","text": "Repetitive low-impact loading"}],"correct": "B","explanation": "PCL injuries classically result from a direct blow to the anterior tibia (dashboard injury) or forced hyperflexion, often with the foot plantarflexed."},{"id": 7521,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Compared to ACL injuries, isolated PCL injuries are generally managed:","options": [{"key": "A","text": "Always surgically, regardless of severity"},{"key": "B","text": "Never treated at all"},{"key": "C","text": "Only with immediate amputation"},{"key": "D","text": "Often conservatively for isolated, low-grade injuries, with surgery reserved for combined injuries or high-grade instability"}],"correct": "D","explanation": "Isolated, lower-grade PCL injuries are frequently managed conservatively with focused quadriceps strengthening, while surgery is more often reserved for combined ligamentous injuries or significant instability."},{"id": 7522,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Meniscal tears are classified by tear pattern; a 'radial' tear pattern is oriented:","options": [{"key": "A","text": "Perpendicular to the meniscal circumference, extending from inner edge toward the periphery"},{"key": "B","text": "Only in the posterior horn"},{"key": "C","text": "Parallel to the meniscal circumference"},{"key": "D","text": "Only in the anterior horn"}],"correct": "A","explanation": "Radial tears run perpendicular to the circumferential fibers, potentially disrupting the meniscus's hoop stress function significantly depending on tear extent."},{"id": 7523,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Meniscal repair (rather than meniscectomy) is more likely to be considered for tears located in which vascular zone?","options": [{"key": "A","text": "Central avascular (white-white) zone"},{"key": "B","text": "Only tears in the posterior horn regardless of zone"},{"key": "C","text": "Location has no bearing on repair decision"},{"key": "D","text": "Peripheral vascular (red-red) zone or red-white zone"}],"correct": "D","explanation": "Tears in the peripheral, better-vascularized zones have greater healing potential, making repair a more viable option compared to tears in the avascular central zone."},{"id": 7524,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Following partial meniscectomy, rehabilitation and return to activity is generally:","options": [{"key": "A","text": "Faster than after meniscal repair, due to no need to protect a healing repair"},{"key": "B","text": "Not applicable, as no rehabilitation is needed"},{"key": "C","text": "Slower than after meniscal repair"},{"key": "D","text": "Identical in timeline to ACL reconstruction"}],"correct": "A","explanation": "Meniscectomy generally allows faster progression of weight-bearing and rehabilitation compared to meniscal repair, which requires protection to allow the repair to heal."},{"id": 7525,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Easy","question": "Patellofemoral pain syndrome commonly presents with pain aggravated by which activities?","options": [{"key": "A","text": "Stair climbing/descending, squatting, and prolonged sitting ('theater sign')"},{"key": "B","text": "Upper body resistance training only"},{"key": "C","text": "Swimming only"},{"key": "D","text": "Walking on flat ground only"}],"correct": "A","explanation": "Patellofemoral pain is classically aggravated by activities loading the patellofemoral joint in flexion, such as stairs, squatting, and prolonged sitting with knees bent."},{"id": 7526,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which factor is commonly implicated as a contributing biomechanical factor in patellofemoral pain syndrome?","options": [{"key": "A","text": "Excessive ankle dorsiflexion range"},{"key": "B","text": "Hip abductor/external rotator weakness contributing to dynamic knee valgus"},{"key": "C","text": "Strong core stability"},{"key": "D","text": "Excessive quadriceps strength relative to hip muscles"}],"correct": "B","explanation": "Proximal hip muscle weakness (abductors/external rotators) is commonly implicated in patellofemoral pain, contributing to dynamic valgus and altered patellar tracking."},{"id": 7527,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Chondromalacia patellae refers specifically to:","options": [{"key": "A","text": "Ligament laxity of the knee"},{"key": "B","text": "A meniscal tear pattern"},{"key": "C","text": "Softening and degeneration of the articular cartilage on the undersurface of the patella"},{"key": "D","text": "A fracture of the patella"}],"correct": "C","explanation": "Chondromalacia patellae describes pathological softening/fibrillation of the patellar articular cartilage, a specific structural finding sometimes associated with patellofemoral pain."},{"id": 7528,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Osgood-Schlatter disease involves traction apophysitis at which anatomical site?","options": [{"key": "A","text": "Tibial tuberosity"},{"key": "B","text": "Femoral condyle"},{"key": "C","text": "Inferior pole of the patella"},{"key": "D","text": "Fibular head"}],"correct": "A","explanation": "Osgood-Schlatter disease is a traction apophysitis at the tibial tuberosity, common in adolescents during growth spurts, related to repetitive quadriceps pull via the patellar tendon."},{"id": 7529,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Sinding-Larsen-Johansson syndrome involves traction apophysitis at which site, sometimes considered analogous to Osgood-Schlatter but at a different location?","options": [{"key": "A","text": "Superior pole of the patella"},{"key": "B","text": "Inferior pole of the patella"},{"key": "C","text": "Tibial tuberosity"},{"key": "D","text": "Femoral condyle"}],"correct": "B","explanation": "Sinding-Larsen-Johansson syndrome affects the inferior pole of the patella, representing a similar traction apophysitis process to Osgood-Schlatter but at the patellar attachment of the patellar tendon."},{"id": 7530,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Osteochondritis dissecans of the knee most commonly affects which location?","options": [{"key": "A","text": "Fibular head"},{"key": "B","text": "Tibial plateau exclusively"},{"key": "C","text": "Patellar articular surface exclusively"},{"key": "D","text": "Lateral aspect of the medial femoral condyle"}],"correct": "D","explanation": "Osteochondritis dissecans classically affects the lateral aspect of the medial femoral condyle, involving separation of a segment of subchondral bone and overlying cartilage."},{"id": 7531,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "A popliteal (Baker's) cyst commonly develops secondary to which underlying knee pathology?","options": [{"key": "A","text": "Patellar fracture"},{"key": "B","text": "Isolated healthy knee with no pathology"},{"key": "C","text": "Intra-articular pathology such as meniscal tear or osteoarthritis causing excess synovial fluid production"},{"key": "D","text": "ACL reconstruction always"}],"correct": "C","explanation": "Baker's cysts typically develop secondary to increased intra-articular fluid/pressure from underlying pathology like meniscal tears or osteoarthritis, with fluid extending into the popliteal bursa."},{"id": 7532,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which grading system is commonly used to classify the severity of knee osteoarthritis on radiographs?","options": [{"key": "A","text": "Weber classification"},{"key": "B","text": "Garden classification"},{"key": "C","text": "Rockwood classification"},{"key": "D","text": "Kellgren-Lawrence classification"}],"correct": "D","explanation": "The Kellgren-Lawrence classification grades knee osteoarthritis severity (0-4) based on radiographic features such as osteophytes and joint space narrowing."},{"id": 7533,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Multiligamentous knee injury (e.g., knee dislocation) requires urgent assessment of which structure due to high injury risk?","options": [{"key": "A","text": "Sural nerve only, with no other concerns"},{"key": "B","text": "Popliteal artery and peroneal nerve"},{"key": "C","text": "Saphenous vein only"},{"key": "D","text": "Femoral nerve"}],"correct": "B","explanation": "Multiligamentous knee injuries carry significant risk of popliteal artery and peroneal nerve injury, necessitating urgent vascular and neurological assessment."},{"id": 7534,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Quadriceps tendon rupture, compared to patellar tendon rupture, is more common in which age group?","options": [{"key": "A","text": "Equally common across all age groups with no distinction"},{"key": "B","text": "Older individuals, often with pre-existing tendon degeneration"},{"key": "C","text": "Neonates"},{"key": "D","text": "Younger athletes under 30"}],"correct": "B","explanation": "Quadriceps tendon rupture is more common in older individuals, often associated with pre-existing degenerative tendon changes, while patellar tendon rupture tends to occur in younger, more athletic individuals."},{"id": 7535,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Following total knee arthroplasty, early post-operative rehabilitation typically emphasizes:","options": [{"key": "A","text": "Early mobilization, progressive ROM, and quadriceps activation to restore function and prevent stiffness"},{"key": "B","text": "Aggressive high-impact activity immediately"},{"key": "C","text": "No physiotherapy involvement"},{"key": "D","text": "Complete immobilization for 6 weeks"}],"correct": "A","explanation": "Early post-TKA rehabilitation emphasizes progressive mobilization, ROM restoration, and quadriceps strengthening to optimize functional recovery and minimize stiffness."},{"id": 7536,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Arthrofibrosis, a complication following knee surgery (e.g., ACL reconstruction, TKA), refers to:","options": [{"key": "A","text": "Excessive joint laxity"},{"key": "B","text": "Infection of the joint"},{"key": "C","text": "Excessive scar tissue formation leading to restricted range of motion"},{"key": "D","text": "Immediate post-operative swelling only, resolving quickly"}],"correct": "C","explanation": "Arthrofibrosis involves pathological excessive scar tissue formation within the joint, leading to significant, sometimes debilitating, loss of motion."},{"id": 7537,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Which early post-operative sign after knee surgery should raise concern for possible arthrofibrosis risk, prompting closer monitoring/intervention?","options": [{"key": "A","text": "Normal surgical scar healing"},{"key": "B","text": "Significant, disproportionate loss of ROM (especially extension) not improving with standard rehabilitation"},{"key": "C","text": "Mild bruising around the incision"},{"key": "D","text": "Normal expected swelling that resolves with elevation"}],"correct": "B","explanation": "A notable, persistent loss of range of motion (particularly extension) that fails to respond to standard post-operative rehabilitation should raise concern for developing arthrofibrosis."},{"id": 7538,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which quadriceps exercise is often emphasized early after knee injury/surgery due to its relatively low joint compressive/shear stress?","options": [{"key": "A","text": "Plyometric jump training"},{"key": "B","text": "Open-chain resisted knee extension at 0-30 degrees exclusively"},{"key": "C","text": "Deep squatting immediately"},{"key": "D","text": "Quadriceps setting/isometric exercises"}],"correct": "D","explanation": "Quadriceps setting (isometric) exercises are commonly emphasized in early rehabilitation due to their relatively low stress on healing structures while still activating the quadriceps."},{"id": 7539,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Closed kinetic chain exercises are often preferred over open kinetic chain exercises in early ACL reconstruction rehabilitation, particularly avoiding open-chain quadriceps exercise in which range?","options": [{"key": "A","text": "No specific range restriction applies"},{"key": "B","text": "0-30 degrees of knee flexion range, due to increased anterior tibial shear stress on the graft"},{"key": "C","text": "90-120 degrees of knee flexion"},{"key": "D","text": "Full extension in weight-bearing only"}],"correct": "B","explanation": "Open-chain quadriceps extension exercises in the 0-30 degree range are generally avoided/limited early after ACL reconstruction due to increased anterior tibial translation stress on the healing graft."},{"id": 7540,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Hamstring strengthening is emphasized early in ACL rehabilitation partly because the hamstrings act as:","options": [{"key": "A","text": "Muscles that should be avoided entirely during rehabilitation"},{"key": "B","text": "Muscles with no relevance to ACL function"},{"key": "C","text": "Antagonists that increase anterior tibial translation"},{"key": "D","text": "Dynamic stabilizers that help resist anterior tibial translation, supporting the ACL graft"}],"correct": "D","explanation": "The hamstrings act as dynamic agonists to the ACL, helping resist anterior tibial translation, making their strengthening beneficial in supporting knee stability during ACL rehabilitation."},{"id": 7541,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Patellar tendon-femoral condyle friction/impingement (patellar tendinopathy risk factor) can be associated with which patellar height abnormality?","options": [{"key": "A","text": "Patella baja (low-riding patella)"},{"key": "B","text": "Patella alta (high-riding patella)"},{"key": "C","text": "Normal patellar height"},{"key": "D","text": "Bipartite patella only"}],"correct": "B","explanation": "Patella alta has been associated with increased strain on the proximal patellar tendon, potentially contributing to patellar tendinopathy risk."},{"id": 7542,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "The 'terrible triad' of the knee, a severe multiligamentous injury pattern, classically involves the ACL, and which two additional structures?","options": [{"key": "A","text": "PCL and LCL"},{"key": "B","text": "MCL and medial meniscus (originally described by O'Donoghue)"},{"key": "C","text": "MCL and lateral meniscus"},{"key": "D","text": "Patellar tendon and quadriceps tendon"}],"correct": "B","explanation": "The classic 'unhappy/terrible triad' (O'Donoghue's triad) involves combined ACL, MCL, and medial meniscus injury."},{"id": 7543,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Discoid meniscus, a congenital variant, most commonly affects which meniscus?","options": [{"key": "A","text": "Lateral meniscus"},{"key": "B","text": "Neither meniscus, it affects the patella"},{"key": "C","text": "Both equally in most cases"},{"key": "D","text": "Medial meniscus"}],"correct": "A","explanation": "Discoid meniscus, an abnormal thickened disc-shaped congenital variant, most commonly affects the lateral meniscus and can predispose to tears and mechanical symptoms."},{"id": 7544,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Post-meniscal repair rehabilitation typically involves which weight-bearing/ROM restriction to protect the repair, compared to meniscectomy?","options": [{"key": "A","text": "Immediate unrestricted return to sport"},{"key": "B","text": "Complete non-weight-bearing for 6 months"},{"key": "C","text": "No restrictions at all, identical to meniscectomy"},{"key": "D","text": "Restricted weight-bearing and/or limited deep flexion range in the initial weeks per protocol"}],"correct": "D","explanation": "Meniscal repair protocols typically involve temporary restrictions on weight-bearing and/or deep knee flexion to protect the healing repair, differing from the faster progression allowed after meniscectomy."},{"id": 7545,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which knee ligament injury is most commonly managed conservatively (non-surgically) even when complete, due to good intrinsic healing potential?","options": [{"key": "A","text": "PCL combined with other structures"},{"key": "B","text": "MCL (isolated, most grades)"},{"key": "C","text": "ACL"},{"key": "D","text": "Multiligamentous injury"}],"correct": "B","explanation": "Isolated MCL injuries, even complete (Grade III) tears, are frequently managed conservatively due to the ligament's relatively good vascular supply and healing capacity, unlike the ACL."},{"id": 7546,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "A positive pivot shift test is considered one of the most specific clinical findings for which condition?","options": [{"key": "A","text": "Meniscal tear"},{"key": "B","text": "Functional ACL insufficiency with rotational instability"},{"key": "C","text": "Isolated MCL sprain"},{"key": "D","text": "Patellofemoral pain syndrome"}],"correct": "B","explanation": "The pivot shift test, when positive, is highly specific for functional ACL insufficiency, reproducing the rotational subluxation-relocation event characteristic of ACL-deficient knees."},{"id": 7547,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which outcome measure is commonly used to assess patient-reported knee function, particularly in ACL/ligamentous injury research and clinical practice?","options": [{"key": "A","text": "International Knee Documentation Committee (IKDC) score"},{"key": "B","text": "Oswestry Disability Index"},{"key": "C","text": "DASH score"},{"key": "D","text": "Berg Balance Scale"}],"correct": "A","explanation": "The IKDC subjective knee form is a widely used, validated patient-reported outcome measure specifically designed for knee ligamentous/joint conditions."},{"id": 7548,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Which of the following best describes 'quadriceps avoidance gait' sometimes seen in ACL-deficient patients?","options": [{"key": "A","text": "Excessive hip flexion with normal knee mechanics"},{"key": "B","text": "Excessive knee flexion throughout stance to reduce quadriceps demand"},{"key": "C","text": "Normal unaltered gait pattern"},{"key": "D","text": "Reduced knee flexion and minimized quadriceps activation during stance to avoid anterior tibial translation"}],"correct": "D","explanation": "Quadriceps avoidance gait describes a compensatory pattern where patients minimize knee flexion and quadriceps activation during stance to reduce the anterior tibial shear force that would otherwise stress the ACL-deficient knee."},{"id": 7549,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "High tibial osteotomy is a surgical procedure sometimes considered for younger, active patients with which knee condition?","options": [{"key": "A","text": "Isolated patellar tendinopathy"},{"key": "B","text": "Acute meniscal tear only"},{"key": "C","text": "Complete ACL rupture with no OA"},{"key": "D","text": "Unicompartmental (typically medial) knee osteoarthritis with varus malalignment"}],"correct": "D","explanation": "High tibial osteotomy realigns the knee to unload a degenerated compartment (commonly medial), offering a joint-preserving option for younger active patients with unicompartmental OA and malalignment."},{"id": 7550,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Unicompartmental (partial) knee arthroplasty is generally considered appropriate for patients with:","options": [{"key": "A","text": "Active infection of the joint"},{"key": "B","text": "Diffuse tricompartmental osteoarthritis"},{"key": "C","text": "Osteoarthritis limited to a single compartment with intact ligaments"},{"key": "D","text": "Complete ACL and PCL deficiency"}],"correct": "C","explanation": "Unicompartmental knee arthroplasty is indicated for isolated single-compartment osteoarthritis in patients with otherwise intact ligamentous structures and good alignment potential."},{"id": 7551,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which factor is important to assess before progressing a patient to plyometric/jump training in later-stage ACL rehabilitation?","options": [{"key": "A","text": "No assessment needed, all patients progress identically"},{"key": "B","text": "Patient's enthusiasm alone, regardless of physical readiness"},{"key": "C","text": "Adequate strength, neuromuscular control, and landing mechanics to minimize reinjury risk"},{"key": "D","text": "Time since surgery alone"}],"correct": "C","explanation": "Progression to plyometric training should be based on demonstrated adequate strength, movement quality, and neuromuscular control rather than time alone, to minimize reinjury risk."},{"id": 7552,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Excessive dynamic knee valgus during landing tasks is considered a risk factor for which injury, and is a common target of injury prevention programs?","options": [{"key": "A","text": "Ankle sprain only"},{"key": "B","text": "Achilles tendon rupture"},{"key": "C","text": "Rotator cuff tear"},{"key": "D","text": "ACL injury"}],"correct": "D","explanation": "Dynamic knee valgus during landing/cutting is a recognized biomechanical risk factor for ACL injury, and its correction is a key focus of many ACL injury prevention programs."},{"id": 7553,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Neuromuscular training programs (e.g., FIFA 11+) designed for ACL injury prevention typically emphasize which components?","options": [{"key": "A","text": "Only upper body strengthening"},{"key": "B","text": "Only aerobic conditioning"},{"key": "C","text": "Strength, balance/proprioception, plyometrics, and movement technique/landing mechanics"},{"key": "D","text": "Only static stretching"}],"correct": "C","explanation": "Effective ACL injury prevention programs are multi-component, incorporating strength, balance, plyometric, and technique/landing mechanics training."},{"id": 7554,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Blood flow restriction (BFR) training has emerging evidence for use in early post-operative knee rehabilitation primarily to:","options": [{"key": "A","text": "Increase joint swelling intentionally"},{"key": "B","text": "Replace the need for any strength training entirely"},{"key": "C","text": "Eliminate the need for post-operative precautions"},{"key": "D","text": "Allow strength/hypertrophy gains using low mechanical loads, useful when heavy loading is contraindicated"}],"correct": "D","explanation": "BFR training allows for muscular strength and hypertrophy adaptations using lower external loads, which can be valuable in early post-operative phases when heavier loading is restricted."},{"id": 7555,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Easy","question": "Which sign, an audible/palpable 'pop' at the time of injury, is commonly reported by patients at the moment of ACL rupture?","options": [{"key": "A","text": "Never reported in ACL injuries"},{"key": "B","text": "Only occurs with patellar dislocation"},{"key": "C","text": "Only occurs with meniscal tears"},{"key": "D","text": "Frequently reported and often associated with immediate swelling (hemarthrosis)"}],"correct": "D","explanation": "A palpable/audible pop at the time of injury, often followed by rapid swelling (hemarthrosis), is a commonly reported feature of acute ACL rupture."},{"id": 7556,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Rapid-onset knee effusion (within 1-2 hours) following acute injury is more suggestive of which type of injury compared to slower-onset swelling?","options": [{"key": "A","text": "Ligamentous injury with hemarthrosis (e.g., ACL tear), typically rapid onset"},{"key": "B","text": "No correlation between swelling onset and injury type"},{"key": "C","text": "Only indicates infection"},{"key": "D","text": "Meniscal tear (typically slower onset)"}],"correct": "A","explanation": "Rapid effusion onset (hemarthrosis) within a few hours is more characteristic of significant ligamentous injury like ACL rupture, while meniscal tears often show more delayed, gradual swelling."},{"id": 7557,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Genu recurvatum (knee hyperextension) can be a compensatory strategy in patients with which underlying weakness?","options": [{"key": "A","text": "Hip flexor weakness only"},{"key": "B","text": "Normal quadriceps strength with no compensation needed"},{"key": "C","text": "Quadriceps weakness, using passive structures to lock the knee for stability"},{"key": "D","text": "Ankle plantarflexor weakness only"}],"correct": "C","explanation": "Patients with quadriceps weakness may adopt a genu recurvatum thrust strategy during stance, using ligamentous/capsular structures to passively stabilize the knee in the absence of adequate active control."},{"id": 7558,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which of the following describes the primary biomechanical function of the ACL?","options": [{"key": "A","text": "Providing lateral knee stability only"},{"key": "B","text": "Providing shock absorption for axial loads"},{"key": "C","text": "Primary restraint to anterior tibial translation and a secondary restraint to rotational and varus/valgus loads"},{"key": "D","text": "Resisting posterior tibial translation only"}],"correct": "C","explanation": "The ACL's primary role is resisting anterior tibial translation, with additional secondary roles in controlling rotational and varus/valgus stability of the knee."},{"id": 7559,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Knee joint effusion can be clinically assessed using which test to detect the presence of fluid?","options": [{"key": "A","text": "Sweep test (bulge sign) or patellar tap test"},{"key": "B","text": "McMurray test"},{"key": "C","text": "Lachman test"},{"key": "D","text": "Thomas test"}],"correct": "A","explanation": "The sweep/bulge test and patellar tap test are clinical techniques used to detect the presence and approximate volume of knee joint effusion."},{"id": 7560,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which of the following best describes the role of proprioceptive/balance training following knee ligament injury?","options": [{"key": "A","text": "It should be avoided entirely after ligament injury"},{"key": "B","text": "It helps restore neuromuscular control and joint position sense, important for functional stability and injury prevention"},{"key": "C","text": "It has no evidence-based benefit"},{"key": "D","text": "It only benefits upper limb function"}],"correct": "B","explanation": "Proprioceptive and balance training is a well-supported component of knee ligament rehabilitation, helping restore neuromuscular control important for dynamic joint stability and reducing reinjury risk."},{"id": 7561,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Hard","question": "Which patellofemoral taping/bracing technique aims to alter patellar position/tracking, though evidence for long-term structural change is limited?","options": [{"key": "A","text": "Ankle taping"},{"key": "B","text": "Kinesio taping applied to the lumbar spine"},{"key": "C","text": "McConnell taping technique"},{"key": "D","text": "Wrist strapping"}],"correct": "C","explanation": "McConnell taping is a technique aimed at correcting patellar position/tracking to reduce patellofemoral pain, though its primary benefit may relate more to pain modulation than lasting structural correction."},{"id": 7562,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "A 'locked knee' with inability to fully extend, following a twisting injury, most strongly suggests which pathology?","options": [{"key": "A","text": "Simple ligament sprain"},{"key": "B","text": "Displaced meniscal tear (e.g., bucket-handle) mechanically blocking extension"},{"key": "C","text": "Quadriceps strain"},{"key": "D","text": "Patellar dislocation only"}],"correct": "B","explanation": "A true mechanical locked knee, with inability to achieve full passive extension after a twisting injury, is classically caused by a displaced meniscal fragment (such as a bucket-handle tear) blocking the joint."},{"id": 7563,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which of the following best describes appropriate early management goals following acute, uncomplicated knee ligament sprain (e.g., Grade I MCL)?","options": [{"key": "A","text": "Surgical repair required for all grades"},{"key": "B","text": "Immediate return to full sport without restriction"},{"key": "C","text": "Complete immobilization for 6 weeks regardless of severity"},{"key": "D","text": "Pain/swelling management, protection as needed, and early controlled motion/loading within tolerance"}],"correct": "D","explanation": "Management of milder knee ligament sprains typically follows a graded approach with initial protection/symptom management progressing to early controlled motion and loading as tolerated."},{"id": 7564,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Easy","question": "Lateral ankle sprains most commonly involve injury to which ligament first, due to its relative weakness?","options": [{"key": "A","text": "Deltoid ligament"},{"key": "B","text": "Anterior talofibular ligament (ATFL)"},{"key": "C","text": "Posterior talofibular ligament"},{"key": "D","text": "Calcaneofibular ligament"}],"correct": "B","explanation": "The ATFL is the weakest of the lateral ankle ligaments and is most commonly injured first during an inversion ankle sprain."},{"id": 7565,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Easy","question": "Which mechanism of injury typically causes a lateral ankle sprain?","options": [{"key": "A","text": "Eversion and dorsiflexion"},{"key": "B","text": "Inversion and plantarflexion"},{"key": "C","text": "Pure dorsiflexion"},{"key": "D","text": "Pure eversion"}],"correct": "B","explanation": "Lateral ankle sprains classically result from a combined inversion and plantarflexion mechanism, such as landing awkwardly on an inverted foot."},{"id": 7566,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Grade II lateral ankle sprain involves which degree of injury?","options": [{"key": "A","text": "Mild stretching with no instability"},{"key": "B","text": "Complete rupture with gross instability"},{"key": "C","text": "Partial ligament tear with mild-moderate instability"},{"key": "D","text": "No structural damage at all"}],"correct": "C","explanation": "A Grade II sprain represents partial ligament tearing with associated mild-to-moderate joint laxity/instability, more severe than Grade I but less than complete Grade III rupture."},{"id": 7567,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "The Ottawa Ankle Rules are used clinically to determine the need for:","options": [{"key": "A","text": "Physiotherapy referral only"},{"key": "B","text": "Radiographs (X-ray) to rule out fracture"},{"key": "C","text": "MRI in all ankle injuries"},{"key": "D","text": "Immediate surgical referral"}],"correct": "B","explanation": "The Ottawa Ankle Rules are a validated clinical decision tool used to determine whether radiographic imaging is indicated following acute ankle injury, helping reduce unnecessary X-rays."},{"id": 7568,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Chronic ankle instability following recurrent lateral ankle sprains is often attributed to which combination of deficits?","options": [{"key": "A","text": "Complete absence of any deficits"},{"key": "B","text": "Mechanical instability (ligamentous laxity) and functional instability (proprioceptive/neuromuscular deficits)"},{"key": "C","text": "Only mechanical laxity, with no functional component"},{"key": "D","text": "Only muscle weakness, unrelated to ligament status"}],"correct": "B","explanation": "Chronic ankle instability involves both mechanical factors (residual ligamentous laxity) and functional factors (impaired proprioception, neuromuscular control, and postural stability)."},{"id": 7569,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Balance/proprioceptive training (e.g., wobble board exercises) following ankle sprain aims primarily to address which deficit?","options": [{"key": "A","text": "Cardiovascular fitness"},{"key": "B","text": "Bone density loss"},{"key": "C","text": "Functional instability related to impaired neuromuscular control and proprioception"},{"key": "D","text": "Ligament laxity directly, correcting mechanical instability"}],"correct": "C","explanation": "Balance and proprioceptive training specifically targets the functional/neuromuscular component of ankle instability, improving postural control and reducing reinjury risk."},{"id": 7570,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Achilles tendinopathy is commonly associated with which biomechanical risk factor?","options": [{"key": "A","text": "Excessive hip mobility"},{"key": "B","text": "Excessive ankle dorsiflexion mobility"},{"key": "C","text": "Reduced ankle dorsiflexion range/calf flexibility and sudden increases in training load"},{"key": "D","text": "Strong, flexible gastrocnemius-soleus complex"}],"correct": "C","explanation": "Reduced ankle dorsiflexion mobility and sudden spikes in training load/intensity are recognized contributing factors to Achilles tendinopathy development."},{"id": 7571,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Insertional Achilles tendinopathy differs from mid-portion tendinopathy partly in management, as which exercise modification is often recommended?","options": [{"key": "A","text": "Full range eccentric loading through deep dorsiflexion, identical to mid-portion protocols"},{"key": "B","text": "Identical treatment with no modifications needed"},{"key": "C","text": "Avoiding excessive dorsiflexion during loading exercises to reduce compressive stress at the insertion"},{"key": "D","text": "Complete avoidance of any loading exercise"}],"correct": "C","explanation": "Insertional Achilles tendinopathy management typically modifies loading exercises to avoid excessive ankle dorsiflexion, which would increase compressive stress at the tendon-bone insertion, unlike mid-portion protocols that use full range."},{"id": 7572,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Plantar fasciitis is thought to be more accurately termed 'plantar fasciopathy' by some sources, reflecting which underlying pathology understanding, similar to tendinopathy?","options": [{"key": "A","text": "Only present in athletes"},{"key": "B","text": "Primarily an acute inflammatory process only"},{"key": "C","text": "A degenerative process with collagen disorganization, similar to tendinosis, rather than purely inflammatory"},{"key": "D","text": "No pathological changes present"}],"correct": "C","explanation": "Similar to the tendinopathy model, plantar fascia pathology is increasingly understood to involve degenerative changes rather than being purely inflammatory in nature, supporting the term 'fasciopathy'."},{"id": 7573,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Which stretching technique is commonly recommended in plantar fasciitis management, targeting both the fascia and calf complex?","options": [{"key": "A","text": "Only cervical spine stretches"},{"key": "B","text": "Only upper limb stretches"},{"key": "C","text": "Plantar fascia-specific stretching (e.g., toe extension stretch) and calf/Achilles stretching"},{"key": "D","text": "Avoiding all stretching entirely"}],"correct": "C","explanation": "Combined stretching of the plantar fascia (e.g., dorsiflexing the toes) and calf/Achilles complex is commonly incorporated into plantar fasciitis management programs."},{"id": 7574,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Morton's neuroma involves pathological thickening of tissue around which structure?","options": [{"key": "A","text": "The plantar fascia"},{"key": "B","text": "An interdigital (common digital) nerve, most commonly the third web space"},{"key": "C","text": "The Achilles tendon"},{"key": "D","text": "A metatarsal bone"}],"correct": "B","explanation": "Morton's neuroma involves perineural fibrosis around an interdigital nerve, most commonly affecting the third (and sometimes second) web space."},{"id": 7575,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Which footwear modification is commonly recommended as part of conservative management for Morton's neuroma?","options": [{"key": "A","text": "Wide toe box footwear with a metatarsal pad to offload the affected area"},{"key": "B","text": "No footwear modification has any relevance"},{"key": "C","text": "Barefoot walking exclusively"},{"key": "D","text": "Narrow, tight-fitting shoes with high heels"}],"correct": "A","explanation": "Wide toe-box shoes and metatarsal pads/offloading strategies help reduce compressive/tensile stress on the affected interdigital nerve in Morton's neuroma management."},{"id": 7576,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Tarsal tunnel syndrome involves compression of which nerve as it passes behind the medial malleolus?","options": [{"key": "A","text": "Posterior tibial nerve"},{"key": "B","text": "Deep peroneal nerve"},{"key": "C","text": "Superficial peroneal nerve"},{"key": "D","text": "Sural nerve"}],"correct": "A","explanation": "Tarsal tunnel syndrome results from compression of the posterior tibial nerve (or its branches) within the tarsal tunnel behind the medial malleolus."},{"id": 7577,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Posterior tibial tendon dysfunction (PTTD) is a leading cause of which acquired foot deformity in adults?","options": [{"key": "A","text": "Acquired adult flatfoot (pes planovalgus)"},{"key": "B","text": "Pes cavus"},{"key": "C","text": "Claw toe deformity"},{"key": "D","text": "Hallux valgus"}],"correct": "A","explanation": "Progressive posterior tibial tendon dysfunction is the most common cause of acquired flatfoot deformity in adults, as the tendon fails to adequately support the medial longitudinal arch."},{"id": 7578,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "The 'too many toes' sign, observed from behind a standing patient, is a clinical finding associated with which condition?","options": [{"key": "A","text": "Achilles tendinopathy"},{"key": "B","text": "Hallux rigidus"},{"key": "C","text": "Posterior tibial tendon dysfunction with forefoot abduction"},{"key": "D","text": "Plantar fasciitis"}],"correct": "C","explanation": "The 'too many toes' sign, where more lateral toes are visible from behind due to forefoot abduction, is a classic finding in posterior tibial tendon dysfunction/acquired flatfoot."},{"id": 7579,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Easy","question": "Hallux valgus (bunion) deformity involves lateral deviation of which joint?","options": [{"key": "A","text": "Ankle joint"},{"key": "B","text": "First metatarsophalangeal joint (great toe deviates laterally, first metatarsal deviates medially)"},{"key": "C","text": "Second MTP joint"},{"key": "D","text": "Interphalangeal joint of the great toe"}],"correct": "B","explanation": "Hallux valgus involves lateral deviation of the great toe at the first MTP joint, often with medial deviation of the first metatarsal, creating the characteristic bunion deformity."},{"id": 7580,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Hallux rigidus refers to:","options": [{"key": "A","text": "Degenerative arthritis and progressive stiffness of the first MTP joint"},{"key": "B","text": "A ligament sprain of the great toe"},{"key": "C","text": "A specific type of stress fracture"},{"key": "D","text": "Excessive mobility of the first MTP joint"}],"correct": "A","explanation": "Hallux rigidus describes osteoarthritic changes causing progressive stiffness and pain at the first metatarsophalangeal joint, limiting great toe extension."},{"id": 7581,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Which gait modification is often adopted by patients with hallux rigidus to compensate for limited first MTP extension during push-off?","options": [{"key": "A","text": "No compensation is typically observed"},{"key": "B","text": "Increased hip extension only"},{"key": "C","text": "Increased first MTP joint loading"},{"key": "D","text": "Lateral weight transfer/rolling off the lateral forefoot to avoid painful first MTP dorsiflexion"}],"correct": "D","explanation": "Patients with hallux rigidus often shift weight-bearing laterally during push-off to avoid painful dorsiflexion of the restricted first MTP joint."},{"id": 7582,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Sever's disease (calcaneal apophysitis) is a common cause of heel pain in which population?","options": [{"key": "A","text": "Active children and adolescents during growth spurts"},{"key": "B","text": "Postmenopausal women exclusively"},{"key": "C","text": "Infants"},{"key": "D","text": "Adults over 50"}],"correct": "A","explanation": "Sever's disease is a traction apophysitis at the calcaneal growth plate, common in physically active children and adolescents, particularly during growth spurts."},{"id": 7583,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Metatarsal stress fractures commonly present with which pattern of symptom onset?","options": [{"key": "A","text": "No pain at all until complete fracture"},{"key": "B","text": "Gradual, insidious onset of forefoot pain that worsens with activity"},{"key": "C","text": "Only present with numbness, no pain"},{"key": "D","text": "Sudden acute onset from a single traumatic event"}],"correct": "B","explanation": "Metatarsal stress fractures typically develop with a gradual, insidious onset of activity-related forefoot pain, reflecting the cumulative repetitive loading mechanism."},{"id": 7584,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Which of the following is a recognized risk factor for lower extremity stress fractures in athletes?","options": [{"key": "A","text": "Adequate footwear and surface variation"},{"key": "B","text": "Adequate caloric intake and normal menstrual function"},{"key": "C","text": "Gradual, well-periodized training progression"},{"key": "D","text": "Relative energy deficiency (e.g., low energy availability, menstrual dysfunction) as part of Female/Male Athlete Triad concerns"}],"correct": "D","explanation": "Relative energy deficiency in sport (RED-S), including low energy availability and associated menstrual dysfunction, is a recognized risk factor for stress fractures, particularly relevant in the Female Athlete Triad."},{"id": 7585,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Peroneal tendon subluxation/dislocation results from injury/laxity of which structure?","options": [{"key": "A","text": "Inferior extensor retinaculum"},{"key": "B","text": "Deltoid ligament"},{"key": "C","text": "Superior peroneal retinaculum"},{"key": "D","text": "Flexor retinaculum"}],"correct": "C","explanation": "Peroneal tendon instability results from disruption or laxity of the superior peroneal retinaculum, which normally holds the peroneal tendons in the retromalleolar groove."},{"id": 7586,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Charcot foot (neuropathic arthropathy) is a serious complication most commonly associated with which underlying condition?","options": [{"key": "A","text": "Gout"},{"key": "B","text": "Diabetes mellitus with peripheral neuropathy"},{"key": "C","text": "Osteoporosis alone"},{"key": "D","text": "Rheumatoid arthritis"}],"correct": "B","explanation": "Charcot neuroarthropathy is most commonly associated with diabetic peripheral neuropathy, where impaired sensation allows progressive, often unrecognized joint destruction."},{"id": 7587,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Which clinical presentation should raise concern for acute Charcot foot in a diabetic patient, sometimes mimicking infection?","options": [{"key": "A","text": "Warm, red, swollen foot, often with minimal pain despite significant changes due to neuropathy"},{"key": "B","text": "No visible changes at all"},{"key": "C","text": "Only presents with severe pain and no swelling"},{"key": "D","text": "Cold, pale foot with reduced pulses"}],"correct": "A","explanation": "Acute Charcot foot classically presents with a warm, erythematous, swollen foot, often with disproportionately minimal pain due to underlying neuropathy, which can be mistaken for cellulitis/infection."},{"id": 7588,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Turf toe injury involves a sprain of which structure at the first MTP joint?","options": [{"key": "A","text": "Dorsal capsule"},{"key": "B","text": "Achilles tendon"},{"key": "C","text": "Plantar plate/capsuloligamentous complex"},{"key": "D","text": "Lateral collateral ligament of the ankle"}],"correct": "C","explanation": "Turf toe involves injury to the plantar capsuloligamentous complex (plantar plate) of the first MTP joint, typically from forced hyperextension."},{"id": 7589,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Anterior ankle impingement syndrome (footballer's ankle) is characterized by pain with which movement, related to bony/soft tissue changes at the anterior joint line?","options": [{"key": "A","text": "Plantarflexion"},{"key": "B","text": "Inversion only"},{"key": "C","text": "Eversion only"},{"key": "D","text": "Dorsiflexion"}],"correct": "D","explanation": "Anterior ankle impingement typically causes pain with forced dorsiflexion, related to anterior osteophyte formation or soft tissue impingement at the tibiotalar joint."},{"id": 7590,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Posterior ankle impingement syndrome is characterized by pain with which movement, sometimes related to an os trigonum?","options": [{"key": "A","text": "Eversion"},{"key": "B","text": "Forced plantarflexion"},{"key": "C","text": "Dorsiflexion"},{"key": "D","text": "Inversion"}],"correct": "B","explanation": "Posterior ankle impingement, sometimes related to an accessory os trigonum bone, typically presents with pain during forced plantarflexion (e.g., in dancers performing en pointe)."},{"id": 7591,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Which foot type (pes cavus vs pes planus) is generally associated with reduced shock absorption and increased risk of lateral ankle instability/stress injuries?","options": [{"key": "A","text": "Neither type shows any association"},{"key": "B","text": "Pes planus (flat foot)"},{"key": "C","text": "Only affects the upper limb"},{"key": "D","text": "Pes cavus (high-arched foot)"}],"correct": "D","explanation": "Pes cavus feet are typically more rigid with reduced shock absorption capacity, associated with increased risk of lateral ankle instability and certain overuse injuries."},{"id": 7592,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Excessive foot pronation (pes planus) has been associated with increased risk of which overuse condition, due to altered lower limb kinetic chain mechanics?","options": [{"key": "A","text": "Lateral ankle sprain primarily"},{"key": "B","text": "Posterior impingement syndrome only"},{"key": "C","text": "Hallux rigidus exclusively"},{"key": "D","text": "Medial tibial stress syndrome ('shin splints') and patellofemoral pain"}],"correct": "D","explanation": "Excessive pronation can alter the kinetic chain, contributing to conditions like medial tibial stress syndrome and patellofemoral pain through increased internal tibial rotation stress."},{"id": 7593,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Medial tibial stress syndrome ('shin splints') presents with pain typically located along which region?","options": [{"key": "A","text": "Diffuse pain along the posteromedial tibial border"},{"key": "B","text": "Lateral malleolus"},{"key": "C","text": "Achilles tendon insertion"},{"key": "D","text": "Anterior compartment only, with sharp focal pain"}],"correct": "A","explanation": "Medial tibial stress syndrome classically presents with diffuse aching pain along the posteromedial border of the tibia, related to repetitive traction/overload at the periosteum."},{"id": 7594,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Which condition must be carefully differentiated from medial tibial stress syndrome due to overlapping presentation but requiring different management, given progression risk?","options": [{"key": "A","text": "Tibial stress fracture"},{"key": "B","text": "Simple muscle strain"},{"key": "C","text": "Ankle sprain"},{"key": "D","text": "Plantar fasciitis"}],"correct": "A","explanation": "Tibial stress fracture can present similarly to medial tibial stress syndrome but represents a more advanced/different stage on the bone stress injury continuum, requiring more restricted loading and careful management."},{"id": 7595,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "Chronic exertional compartment syndrome of the lower leg presents with symptoms that are:","options": [{"key": "A","text": "Only present during sleep"},{"key": "B","text": "Present at rest and unrelated to activity"},{"key": "C","text": "Reproducibly triggered by exercise and relieved with rest"},{"key": "D","text": "Constant and unchanging regardless of activity level"}],"correct": "C","explanation": "Chronic exertional compartment syndrome characteristically produces exercise-induced pain/tightness that predictably resolves with rest, distinguishing it from acute compartment syndrome."},{"id": 7596,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Ankle syndesmotic ('high ankle') sprains generally require a longer recovery period compared to typical lateral ankle sprains primarily due to:","options": [{"key": "A","text": "Lower functional demand on the syndesmosis"},{"key": "B","text": "Being less common and therefore under-researched"},{"key": "C","text": "Identical healing time in all cases"},{"key": "D","text": "The syndesmosis's critical role in maintaining ankle mortise stability during weight-bearing and its more limited healing capacity under ongoing stress"}],"correct": "D","explanation": "The syndesmosis experiences significant ongoing stress during weight-bearing activities, and its disruption affects fundamental ankle mortise stability, generally necessitating a longer, more cautious recovery timeline than typical lateral ligament sprains."},{"id": 7597,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Functional rehabilitation approach (early mobilization with protective bracing) versus prolonged immobilization for acute ankle sprains is generally supported by evidence to result in:","options": [{"key": "A","text": "Worse outcomes with functional approach"},{"key": "B","text": "Similar or better outcomes with functional rehabilitation, including faster return to activity"},{"key": "C","text": "Prolonged immobilization is always superior"},{"key": "D","text": "No difference exists between approaches, both are equally poor"}],"correct": "B","explanation": "Evidence generally supports functional rehabilitation (early controlled mobilization/protection) over prolonged immobilization for most acute ankle sprains, associated with faster recovery without compromising outcomes."},{"id": 7598,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Which muscle group weakness has been implicated as a contributing factor to recurrent ankle sprains, targeted in rehabilitation programs?","options": [{"key": "A","text": "Only hip flexor weakness"},{"key": "B","text": "Peroneal muscle weakness/delayed reaction time"},{"key": "C","text": "Quadriceps weakness exclusively"},{"key": "D","text": "Neck muscle weakness"}],"correct": "B","explanation": "Peroneal muscle weakness and delayed neuromuscular reaction time have been implicated in recurrent lateral ankle instability, making peroneal strengthening a rehabilitation focus."},{"id": 7599,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Hard","question": "A calcaneal stress fracture often presents with pain aggravated by which activity, sometimes assessed with a specific squeeze test?","options": [{"key": "A","text": "Only present at rest"},{"key": "B","text": "Toe walking only, with no other findings"},{"key": "C","text": "Weight-bearing/running activities, with pain reproduced by medial-lateral calcaneal compression (squeeze test)"},{"key": "D","text": "Upper limb activity"}],"correct": "C","explanation": "Calcaneal stress fractures typically present with activity-related heel pain, and a positive calcaneal squeeze test (medial-lateral compression reproducing pain) supports the clinical diagnosis."},{"id": 7600,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Return-to-running progression following a lower limb bone stress injury typically follows which general principle?","options": [{"key": "A","text": "Complete avoidance of running permanently"},{"key": "B","text": "No specific progression needed, return whenever pain-free for one day"},{"key": "C","text": "Immediate return to pre-injury mileage"},{"key": "D","text": "Gradual, individualized progressive loading program guided by symptom response and healing timeline"}],"correct": "D","explanation": "Return to running after bone stress injury follows a carefully graded, individualized progression, monitoring symptom response and respecting biological healing timelines to minimize recurrence risk."},{"id": 7601,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Which orthotic intervention is commonly used to help offload/support the medial longitudinal arch in conditions like plantar fasciitis or PTTD?","options": [{"key": "A","text": "Rigid cervical collar"},{"key": "B","text": "Ankle-foot orthosis for wrist support"},{"key": "C","text": "Elbow splint"},{"key": "D","text": "Custom or prefabricated foot orthoses with arch support"}],"correct": "D","explanation": "Foot orthoses providing medial arch support are commonly used as part of conservative management for conditions like plantar fasciitis and posterior tibial tendon dysfunction, aiming to redistribute load and support alignment."},{"id": 7602,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Easy","question": "Cervical spondylosis refers to:","options": [{"key": "A","text": "An acute traumatic cervical fracture"},{"key": "B","text": "An autoimmune inflammatory condition exclusively"},{"key": "C","text": "Age-related degenerative changes of the cervical spine, including disc and facet joint degeneration"},{"key": "D","text": "A congenital cervical anomaly"}],"correct": "C","explanation": "Cervical spondylosis describes the chronic degenerative changes affecting cervical discs, facet joints, and associated structures that occur with aging."},{"id": 7603,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical radiculopathy typically presents with symptoms following which pattern?","options": [{"key": "A","text": "Random, non-specific distribution"},{"key": "B","text": "Bilateral symmetric symptoms only"},{"key": "C","text": "Dermatomal/myotomal pattern corresponding to the affected nerve root, often unilateral"},{"key": "D","text": "Symptoms limited strictly to the neck with no arm involvement"}],"correct": "C","explanation": "Cervical radiculopathy classically presents with pain, numbness, and/or weakness in a pattern corresponding to the specific affected nerve root's dermatome/myotome, typically unilateral."},{"id": 7604,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Which nerve root is most commonly affected in cervical radiculopathy?","options": [{"key": "A","text": "C6-C7"},{"key": "B","text": "C5"},{"key": "C","text": "C4"},{"key": "D","text": "T1"}],"correct": "A","explanation": "C6 and C7 nerve roots are the most commonly affected levels in cervical radiculopathy, often related to degenerative changes at C5-C6 and C6-C7 levels."},{"id": 7605,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "C6 nerve root radiculopathy typically causes sensory symptoms in which distribution?","options": [{"key": "A","text": "Little finger"},{"key": "B","text": "Medial forearm"},{"key": "C","text": "Middle finger only"},{"key": "D","text": "Thumb and index finger"}],"correct": "D","explanation": "C6 dermatome sensory changes classically involve the thumb and index finger, along with potential weakness in wrist extensors and biceps."},{"id": 7606,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "C7 nerve root radiculopathy is classically associated with weakness of which muscle/reflex?","options": [{"key": "A","text": "Triceps weakness/reflex"},{"key": "B","text": "No reflex association"},{"key": "C","text": "Deltoid weakness only"},{"key": "D","text": "Biceps weakness/reflex"}],"correct": "A","explanation": "C7 radiculopathy classically presents with triceps weakness and diminished triceps reflex, along with sensory changes typically in the middle finger."},{"id": 7607,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "C5 nerve root radiculopathy is classically associated with weakness of which muscle?","options": [{"key": "A","text": "Finger flexors"},{"key": "B","text": "Deltoid and biceps"},{"key": "C","text": "Wrist extensors primarily"},{"key": "D","text": "Triceps"}],"correct": "B","explanation": "C5 radiculopathy typically presents with deltoid and biceps weakness, along with sensory changes over the lateral shoulder/upper arm region."},{"id": 7608,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical myelopathy, resulting from spinal cord compression, presents with which characteristic pattern of symptoms distinct from radiculopathy?","options": [{"key": "A","text": "Only autonomic symptoms"},{"key": "B","text": "Upper motor neuron signs, gait disturbance, and possible bilateral/diffuse limb involvement"},{"key": "C","text": "Purely unilateral arm symptoms only"},{"key": "D","text": "Symptoms limited exclusively to the neck"}],"correct": "B","explanation": "Cervical myelopathy involves spinal cord compression producing upper motor neuron signs (hyperreflexia, spasticity), gait disturbance, and often more diffuse or bilateral limb involvement, unlike the typically unilateral radicular pattern."},{"id": 7609,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Which clinical sign, involving thumb/index finger flexion upon flicking the middle finger nail, supports a diagnosis of cervical myelopathy?","options": [{"key": "A","text": "Phalen's sign"},{"key": "B","text": "Tinel's sign"},{"key": "C","text": "Spurling's sign"},{"key": "D","text": "Hoffmann's sign"}],"correct": "D","explanation": "A positive Hoffmann's sign is a useful clinical indicator supporting upper motor neuron involvement, relevant to cervical myelopathy assessment."},{"id": 7610,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Which gait characteristic may be observed in patients with cervical myelopathy?","options": [{"key": "A","text": "Antalgic gait due to hip pain"},{"key": "B","text": "Normal, unaffected gait"},{"key": "C","text": "Broad-based, unsteady, spastic gait pattern"},{"key": "D","text": "Steppage gait from isolated peripheral nerve injury"}],"correct": "C","explanation": "Patients with cervical myelopathy often exhibit a broad-based, spastic, unsteady gait due to upper motor neuron/corticospinal tract involvement."},{"id": 7611,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Whiplash-associated disorder (WAD) is graded using which commonly referenced classification system?","options": [{"key": "A","text": "Salter-Harris classification"},{"key": "B","text": "Quebec Task Force classification"},{"key": "C","text": "Garden classification"},{"key": "D","text": "Rockwood classification"}],"correct": "B","explanation": "The Quebec Task Force classification grades whiplash-associated disorders from Grade 0 (no symptoms) to Grade IV (fracture/dislocation), guiding clinical management."},{"id": 7612,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervicogenic headache is characterized by headache originating from which source?","options": [{"key": "A","text": "Sinus infection only"},{"key": "B","text": "Musculoskeletal dysfunction in the cervical spine, often upper cervical segments"},{"key": "C","text": "Primary intracranial pathology"},{"key": "D","text": "Vascular migraine mechanisms exclusively"}],"correct": "B","explanation": "Cervicogenic headache arises from musculoskeletal dysfunction within the cervical spine, commonly involving the upper cervical segments (C1-C3), producing referred head pain."},{"id": 7613,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Hard","question": "Which examination finding, involving restricted upper cervical rotation, is often assessed in suspected cervicogenic headache using a specific flexion-rotation test?","options": [{"key": "A","text": "No specific test exists for this condition"},{"key": "B","text": "Only lower cervical restriction is relevant"},{"key": "C","text": "Reduced rotation range specifically at the C1-C2 segment when the neck is placed in full flexion"},{"key": "D","text": "Full, symmetric cervical rotation"}],"correct": "C","explanation": "The flexion-rotation test isolates upper cervical (C1-C2) rotation by first fully flexing the neck, and reduced rotation range in this position supports a cervicogenic headache diagnosis related to upper cervical dysfunction."},{"id": 7614,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical facet joint dysfunction commonly presents with which pattern of pain?","options": [{"key": "A","text": "Only bilateral symmetric leg pain"},{"key": "B","text": "Localized neck pain with possible referred pain patterns to the shoulder/upper back, without true dermatomal distribution"},{"key": "C","text": "Only headache with no neck involvement"},{"key": "D","text": "Purely central neck pain with radicular arm symptoms in a strict dermatomal pattern"}],"correct": "B","explanation": "Cervical facet joint pain typically produces localized neck pain with characteristic but non-dermatomal referred pain patterns to areas like the shoulder or upper back/scapular region."},{"id": 7615,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical disc herniation most commonly occurs at which spinal levels?","options": [{"key": "A","text": "C1-C2"},{"key": "B","text": "C5-C6 and C6-C7"},{"key": "C","text": "C7-T1 exclusively"},{"key": "D","text": "Upper thoracic levels"}],"correct": "B","explanation": "C5-C6 and C6-C7 are the most common levels for cervical disc herniation, correlating with the commonly affected C6 and C7 nerve roots."},{"id": 7616,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Torticollis (wry neck) is characterized by:","options": [{"key": "A","text": "Isolated arm weakness with normal neck posture"},{"key": "B","text": "Complete inability to move the neck in any direction"},{"key": "C","text": "Bilateral symmetric neck stiffness"},{"key": "D","text": "Asymmetric cervical positioning, often with lateral flexion to one side and rotation to the opposite side"}],"correct": "D","explanation": "Torticollis presents with characteristic asymmetric neck positioning, classically lateral flexion toward one side combined with rotation toward the opposite side, often due to muscle spasm (e.g., sternocleidomastoid)."},{"id": 7617,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Congenital muscular torticollis in infants is most commonly related to which structural finding?","options": [{"key": "A","text": "Cervical vertebral fracture"},{"key": "B","text": "Normal developmental variant with no pathology"},{"key": "C","text": "Fibrosis/shortening of the sternocleidomastoid muscle, sometimes with a palpable mass"},{"key": "D","text": "Brachial plexus injury exclusively"}],"correct": "C","explanation": "Congenital muscular torticollis is typically related to fibrotic shortening of the sternocleidomastoid muscle, sometimes presenting with a palpable fibrous mass (pseudotumor) within the muscle in infancy."},{"id": 7618,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical spinal stenosis refers to:","options": [{"key": "A","text": "A specific ligament injury"},{"key": "B","text": "Widening of the spinal canal"},{"key": "C","text": "An acute inflammatory condition only"},{"key": "D","text": "Narrowing of the spinal canal, potentially compressing the spinal cord and/or nerve roots"}],"correct": "D","explanation": "Cervical spinal stenosis describes narrowing of the spinal canal diameter, which can lead to compression of neural structures, potentially causing radiculopathy or myelopathy."},{"id": 7619,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Which precaution is important when considering cervical spine manipulation techniques, related to screening for vertebrobasilar insufficiency risk?","options": [{"key": "A","text": "Manipulation should always be performed regardless of findings"},{"key": "B","text": "Performing appropriate pre-manipulative screening tests and assessing for contraindications/red flags"},{"key": "C","text": "No screening is necessary before manipulation"},{"key": "D","text": "Screening is only relevant for lumbar manipulation"}],"correct": "B","explanation": "Careful pre-manipulative screening, including assessment for vertebrobasilar insufficiency risk factors and other red flags, is an important safety consideration before performing cervical spine manipulation."},{"id": 7620,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Deep neck flexor muscle dysfunction (e.g., reduced endurance/activation) has been associated with which common cervical condition?","options": [{"key": "A","text": "Cervical fracture healing complications"},{"key": "B","text": "Non-specific neck pain and forward head posture patterns"},{"key": "C","text": "Vertebral artery dissection"},{"key": "D","text": "Cervical myelopathy exclusively"}],"correct": "B","explanation": "Impaired deep neck flexor (e.g., longus colli/capitis) activation and endurance has been associated with non-specific neck pain and is commonly targeted in rehabilitation programs."},{"id": 7621,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "The craniocervical flexion test is a clinical/rehabilitation tool used to assess and train which specific muscle group?","options": [{"key": "A","text": "Superficial neck flexors (sternocleidomastoid) in isolation"},{"key": "B","text": "Upper trapezius exclusively"},{"key": "C","text": "Deep cervical flexor muscles (longus colli, longus capitis)"},{"key": "D","text": "Cervical extensor muscles only"}],"correct": "C","explanation": "The craniocervical flexion test specifically assesses and trains the deep cervical flexor muscles, aiming to improve their activation capacity relative to superficial neck flexors."},{"id": 7622,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical radiculopathy is generally managed initially with which approach in the absence of significant/progressive neurological deficit?","options": [{"key": "A","text": "Conservative management including physiotherapy, activity modification, and possibly medication"},{"key": "B","text": "No treatment recommended, allow spontaneous resolution without guidance"},{"key": "C","text": "Immediate surgical decompression in all cases"},{"key": "D","text": "Complete cervical immobilization indefinitely"}],"correct": "A","explanation": "Most cases of cervical radiculopathy without significant progressive neurological deficit are managed conservatively initially, with surgery reserved for refractory cases or significant/progressive deficits."},{"id": 7623,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Which red flag finding in a patient with neck pain would warrant urgent further investigation, potentially indicating cervical myelopathy or serious pathology?","options": [{"key": "A","text": "Progressive weakness, bowel/bladder changes, or significant gait disturbance"},{"key": "B","text": "Mild stiffness in the morning only"},{"key": "C","text": "Mechanical pain that varies with movement/position"},{"key": "D","text": "Pain that improves with rest"}],"correct": "A","explanation": "Progressive neurological deficits, bowel/bladder dysfunction, or significant gait disturbance in the context of neck symptoms are red flags requiring urgent further medical evaluation."},{"id": 7624,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Hard","question": "Cervical extension-compression injuries (e.g., in American football) can contribute to which acute neurological presentation involving transient bilateral limb symptoms?","options": [{"key": "A","text": "Cervical cord neurapraxia ('stinger'/burner or transient quadriparesis)"},{"key": "B","text": "Isolated peripheral nerve injury with no spinal involvement"},{"key": "C","text": "Permanent complete spinal cord injury in all cases"},{"key": "D","text": "Simple muscle strain only"}],"correct": "A","explanation": "Cervical cord neurapraxia, sometimes causing transient bilateral limb symptoms (numbness, weakness), can occur following extension-compression type injuries, particularly in contact sports, requiring careful evaluation before return to play."},{"id": 7625,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "'Burner' or 'stinger' syndrome, common in contact sports, typically presents with which symptom pattern?","options": [{"key": "A","text": "Unilateral arm burning/tingling pain and transient weakness following a traction or compression injury to the brachial plexus/cervical nerve roots"},{"key": "B","text": "No sensory changes, only motor findings"},{"key": "C","text": "Bilateral lower limb symptoms only"},{"key": "D","text": "Symptoms lasting permanently with no recovery"}],"correct": "A","explanation": "Burner/stinger syndrome classically presents with unilateral arm burning, tingling, and transient weakness following a traction or compressive injury mechanism affecting the brachial plexus or cervical nerve roots, usually with rapid recovery."},{"id": 7626,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical spine precautions in trauma settings (e.g., c-spine immobilization) are guided by clinical decision rules such as:","options": [{"key": "A","text": "Canadian C-Spine Rule or NEXUS criteria"},{"key": "B","text": "Berg Balance Scale"},{"key": "C","text": "Ottawa Ankle Rules"},{"key": "D","text": "Modified Ashworth Scale"}],"correct": "A","explanation": "The Canadian C-Spine Rule and NEXUS criteria are validated clinical decision tools used to help determine the need for cervical spine imaging following trauma."},{"id": 7627,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Forward head posture has been associated with increased mechanical load/stress on which cervical structures?","options": [{"key": "A","text": "Only affects lumbar spine loading"},{"key": "B","text": "Increased load on posterior cervical extensor muscles and lower cervical/upper thoracic structures"},{"key": "C","text": "Reduced load on posterior cervical muscles and structures"},{"key": "D","text": "No mechanical consequence at all"}],"correct": "B","explanation": "Forward head posture increases the moment arm of the head's weight relative to the cervical spine, increasing mechanical demand on posterior cervical extensor muscles and structures."},{"id": 7628,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical spine rehabilitation for chronic non-specific neck pain typically incorporates which evidence-supported approach?","options": [{"key": "A","text": "Complete rest and avoidance of all neck movement"},{"key": "B","text": "Only passive modalities with no active exercise component"},{"key": "C","text": "A combination of therapeutic exercise (strengthening/endurance), manual therapy, and education"},{"key": "D","text": "Surgical referral as first-line for all chronic neck pain"}],"correct": "C","explanation": "Evidence supports a multimodal approach combining active exercise (strengthening and endurance training), manual therapy techniques, and patient education for managing chronic non-specific neck pain."},{"id": 7629,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Hard","question": "Which structure's degeneration is a common contributing factor to the development of cervical spondylotic myelopathy over time?","options": [{"key": "A","text": "Combined disc degeneration, osteophyte formation, and ligamentum flavum hypertrophy narrowing the spinal canal"},{"key": "B","text": "Only muscular weakness, unrelated to structural changes"},{"key": "C","text": "Acute traumatic fracture exclusively"},{"key": "D","text": "Isolated ligament laxity only, with no disc/bone involvement"}],"correct": "A","explanation": "Cervical spondylotic myelopathy develops from a combination of chronic degenerative changes including disc degeneration, osteophyte formation, and ligamentum flavum hypertrophy, collectively narrowing the spinal canal over time."},{"id": 7630,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Cervical spine traction, sometimes used in radiculopathy management, is theorized to help by which mechanism?","options": [{"key": "A","text": "Weakening the cervical musculature intentionally"},{"key": "B","text": "Increasing nerve root compression"},{"key": "C","text": "Potentially increasing intervertebral foraminal space and reducing mechanical nerve root compression"},{"key": "D","text": "Having no plausible mechanism of benefit"}],"correct": "C","explanation": "Cervical traction is theorized to work partly by increasing intervertebral disc height/foraminal space, potentially reducing mechanical pressure on an affected nerve root, though evidence for its overall efficacy is mixed."},{"id": 7631,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Which patient-reported outcome measure is commonly used to assess disability related to neck pain?","options": [{"key": "A","text": "Berg Balance Scale"},{"key": "B","text": "Oswestry Disability Index"},{"key": "C","text": "Harris Hip Score"},{"key": "D","text": "Neck Disability Index (NDI)"}],"correct": "D","explanation": "The Neck Disability Index is a widely used, validated patient-reported outcome measure specifically designed to assess disability related to neck pain conditions."},{"id": 7632,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Hard","question": "Klippel-Feil syndrome is a congenital condition characterized by:","options": [{"key": "A","text": "Excessive cervical mobility at all segments"},{"key": "B","text": "Congenital fusion of two or more cervical vertebrae"},{"key": "C","text": "A traumatic dislocation pattern"},{"key": "D","text": "An acquired degenerative condition in the elderly"}],"correct": "B","explanation": "Klippel-Feil syndrome involves congenital fusion of cervical vertebrae, potentially associated with reduced neck mobility and other associated anomalies."},{"id": 7633,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Hard","question": "Atlantoaxial instability is a particular concern in which patient population, requiring careful screening before certain activities/procedures?","options": [{"key": "A","text": "Patients with Down syndrome or rheumatoid arthritis"},{"key": "B","text": "Elderly patients with isolated lumbar OA"},{"key": "C","text": "Patients with isolated ankle sprains"},{"key": "D","text": "Healthy young athletes with no comorbidities"}],"correct": "A","explanation": "Patients with Down syndrome or rheumatoid arthritis have increased risk of atlantoaxial instability, requiring careful screening particularly before activities involving significant cervical stress or certain medical procedures."},{"id": 7634,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "Which of the following describes an appropriate physiotherapy approach for a patient presenting with acute, uncomplicated mechanical neck pain without red flags?","options": [{"key": "A","text": "Reassurance, education, and progressive active exercise/movement-based approach"},{"key": "B","text": "Referral for surgical consultation immediately"},{"key": "C","text": "Immediate imaging for all patients regardless of presentation"},{"key": "D","text": "Prolonged cervical collar immobilization as first-line"}],"correct": "A","explanation": "For uncomplicated acute mechanical neck pain without red flags, a reassuring, education-focused approach combined with progressive active movement/exercise is generally recommended over prolonged immobilization or unnecessary imaging."},{"id": 7635,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Low back pain is classified as 'non-specific' when:","options": [{"key": "A","text": "A definitive pathoanatomical source of pain cannot be reliably identified"},{"key": "B","text": "It is always caused by a fracture"},{"key": "C","text": "An MRI always shows a clear disc herniation"},{"key": "D","text": "It only occurs in athletes"}],"correct": "A","explanation": "The majority of low back pain cases are classified as non-specific, meaning no single definitive structural cause can be reliably identified despite the pain being real and often significantly disabling."},{"id": 7636,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Lumbar disc herniation most commonly occurs at which levels?","options": [{"key": "A","text": "L2-L3"},{"key": "B","text": "T12-L1"},{"key": "C","text": "L1-L2"},{"key": "D","text": "L4-L5 and L5-S1"}],"correct": "D","explanation": "The L4-L5 and L5-S1 levels are the most common sites for lumbar disc herniation, correlating with the high mechanical stress at the lumbosacral junction."},{"id": 7637,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "A herniated disc at L5-S1 most commonly affects which nerve root?","options": [{"key": "A","text": "L5"},{"key": "B","text": "L4"},{"key": "C","text": "S1"},{"key": "D","text": "S2"}],"correct": "C","explanation": "An L5-S1 disc herniation typically compresses the S1 nerve root (traversing nerve root at that level), though L5 can also be affected depending on herniation pattern."},{"id": 7638,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "S1 nerve root involvement classically presents with weakness of which movement and diminished which reflex?","options": [{"key": "A","text": "Ankle plantarflexion weakness, Achilles reflex diminished"},{"key": "B","text": "Ankle dorsiflexion weakness, patellar reflex diminished"},{"key": "C","text": "Hip flexion weakness, no reflex change"},{"key": "D","text": "Knee extension weakness, patellar reflex diminished"}],"correct": "A","explanation": "S1 radiculopathy classically presents with plantarflexion weakness and a diminished or absent Achilles (ankle jerk) reflex."},{"id": 7639,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "L5 nerve root involvement is classically associated with weakness of which movement?","options": [{"key": "A","text": "Great toe extension (EHL) and ankle dorsiflexion"},{"key": "B","text": "Ankle plantarflexion"},{"key": "C","text": "Knee flexion"},{"key": "D","text": "Hip adduction"}],"correct": "A","explanation": "L5 radiculopathy classically presents with weakness of great toe extension (extensor hallucis longus) and ankle dorsiflexion."},{"id": 7640,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "L4 nerve root involvement is classically associated with diminished which reflex?","options": [{"key": "A","text": "Biceps reflex"},{"key": "B","text": "Triceps reflex"},{"key": "C","text": "Patellar (knee jerk) reflex"},{"key": "D","text": "Achilles reflex"}],"correct": "C","explanation": "L4 radiculopathy is classically associated with a diminished patellar (knee jerk) reflex, along with possible quadriceps weakness and anteromedial leg sensory changes."},{"id": 7641,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Cauda equina syndrome is a surgical emergency presenting with which classic combination of symptoms?","options": [{"key": "A","text": "Isolated unilateral leg pain only"},{"key": "B","text": "Isolated ankle weakness with no other findings"},{"key": "C","text": "Mild low back stiffness only"},{"key": "D","text": "Saddle anesthesia, bilateral leg symptoms, and bowel/bladder dysfunction"}],"correct": "D","explanation": "Cauda equina syndrome classically presents with saddle anesthesia, bilateral leg symptoms/weakness, and bowel/bladder dysfunction, representing a surgical emergency requiring urgent decompression."},{"id": 7642,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which finding is a critical 'red flag' requiring urgent referral when assessing a patient with low back pain?","options": [{"key": "A","text": "Mild stiffness in the morning that improves with movement"},{"key": "B","text": "Pain localized to one side of the low back"},{"key": "C","text": "Pain that worsens with prolonged sitting"},{"key": "D","text": "New saddle anesthesia or bladder/bowel dysfunction"}],"correct": "D","explanation": "New-onset saddle anesthesia or bladder/bowel dysfunction are critical red flags suggesting possible cauda equina syndrome, requiring immediate medical referral."},{"id": 7643,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Spondylolysis refers to:","options": [{"key": "A","text": "A stress fracture of the pars interarticularis"},{"key": "B","text": "Ligamentous laxity of the facet joints"},{"key": "C","text": "Disc herniation only"},{"key": "D","text": "Complete vertebral dislocation"}],"correct": "A","explanation": "Spondylolysis is a defect/stress fracture of the pars interarticularis, commonly seen in adolescent athletes involved in repetitive hyperextension activities (e.g., gymnastics, fast bowling in cricket)."},{"id": 7644,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Spondylolisthesis refers to:","options": [{"key": "A","text": "Anterior (or posterior) displacement/slippage of one vertebra relative to the adjacent vertebra, often following bilateral spondylolysis"},{"key": "B","text": "A stress fracture with no vertebral displacement"},{"key": "C","text": "A congenital fusion of vertebrae"},{"key": "D","text": "An inflammatory joint condition"}],"correct": "A","explanation": "Spondylolisthesis describes the forward (or occasionally backward) slippage of one vertebral body relative to the one below, often resulting from bilateral pars defects (spondylolysis)."},{"id": 7645,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Spondylolisthesis is commonly graded using which classification system based on percentage of vertebral slippage?","options": [{"key": "A","text": "Garden classification"},{"key": "B","text": "Weber classification"},{"key": "C","text": "Kellgren-Lawrence classification"},{"key": "D","text": "Meyerding classification"}],"correct": "D","explanation": "The Meyerding classification grades spondylolisthesis severity (Grade I-V) based on the percentage of anterior slippage of the vertebral body relative to the one below."},{"id": 7646,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which activity is classically associated with increased risk of spondylolysis in adolescent athletes due to repetitive hyperextension/rotation?","options": [{"key": "A","text": "Long-distance running on flat terrain"},{"key": "B","text": "Gymnastics, fast bowling in cricket, and American football linemen"},{"key": "C","text": "Cycling"},{"key": "D","text": "Swimming freestyle"}],"correct": "B","explanation": "Sports involving repetitive lumbar hyperextension and rotation, such as gymnastics, cricket fast bowling, and certain football positions, are associated with increased spondylolysis risk in young athletes."},{"id": 7647,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Lumbar spinal stenosis classically presents with which symptom pattern, termed 'neurogenic claudication'?","options": [{"key": "A","text": "Leg pain/heaviness that worsens with walking/standing (extension) and improves with sitting/flexion (e.g., leaning on a shopping cart)"},{"key": "B","text": "Pain isolated strictly to the lower back with no leg involvement"},{"key": "C","text": "Symptoms that worsen with sitting/lumbar flexion and improve with standing/extension"},{"key": "D","text": "Symptoms present only at rest with no activity relationship"}],"correct": "A","explanation": "Neurogenic claudication from lumbar spinal stenosis classically worsens with walking/standing (lumbar extension narrows the canal further) and improves with sitting or forward flexion, which increases canal diameter."},{"id": 7648,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Neurogenic claudication (spinal stenosis) must be differentiated from vascular claudication; which feature favors a neurogenic cause?","options": [{"key": "A","text": "Symptoms unrelated to posture entirely"},{"key": "B","text": "Symptoms relieved by standing still without changing position"},{"key": "C","text": "Symptoms relieved specifically by lumbar flexion (e.g., sitting or leaning forward), not just stopping activity"},{"key": "D","text": "Presence of diminished peripheral pulses"}],"correct": "C","explanation": "Neurogenic claudication is characteristically relieved by lumbar flexion specifically (not just stopping walking), while vascular claudication typically resolves simply by stopping activity regardless of position, and may show diminished pulses."},{"id": 7649,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "The McKenzie method (Mechanical Diagnosis and Therapy) classifies low back pain presentations into which primary syndromes?","options": [{"key": "A","text": "Only inflammatory syndrome"},{"key": "B","text": "Only structural syndrome"},{"key": "C","text": "Only postural syndrome"},{"key": "D","text": "Postural, dysfunction, and derangement syndromes"}],"correct": "D","explanation": "McKenzie's classification system identifies postural, dysfunction, and derangement syndromes as primary mechanical pain patterns, guiding specific exercise-based management strategies."},{"id": 7650,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "'Centralization' of symptoms, a favorable prognostic sign in McKenzie assessment, refers to:","options": [{"key": "A","text": "Symptoms spreading further into the leg with repeated movements"},{"key": "B","text": "No change in symptom location with any movement"},{"key": "C","text": "Symptoms worsening in intensity without location change"},{"key": "D","text": "Peripheral (leg) symptoms retreating toward the midline of the spine with repeated specific movements"}],"correct": "D","explanation": "Centralization describes the phenomenon where distal/peripheral symptoms progressively move toward the spinal midline with repeated directional movements, generally considered a favorable prognostic indicator."},{"id": 7651,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "'Peripheralization' of symptoms during assessment is generally considered:","options": [{"key": "A","text": "An unfavorable sign, suggesting the movement/direction should be avoided"},{"key": "B","text": "Irrelevant to clinical decision-making"},{"key": "C","text": "Always indicative of a need for immediate surgery"},{"key": "D","text": "A favorable prognostic sign"}],"correct": "A","explanation": "Peripheralization, where symptoms spread further from the spine toward the periphery, is generally an unfavorable sign suggesting that particular movement direction should be avoided in initial management."},{"id": 7652,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Which classification system for low back pain emphasizes categorizing patients based on likely response to specific treatment approaches (e.g., manipulation, stabilization, specific exercise)?","options": [{"key": "A","text": "Garden classification"},{"key": "B","text": "Rockwood classification"},{"key": "C","text": "Treatment-Based Classification (TBC) system"},{"key": "D","text": "Kellgren-Lawrence system"}],"correct": "C","explanation": "The Treatment-Based Classification system aims to match patients with low back pain to specific treatment approaches (e.g., manipulation, directional exercise, stabilization) based on clinical examination findings, potentially improving outcomes over generic approaches."},{"id": 7653,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Lumbar segmental instability is often characterized clinically by which finding during active movement assessment?","options": [{"key": "A","text": "Smooth, controlled movement throughout range"},{"key": "B","text": "Complete absence of any pain"},{"key": "C","text": "Symmetric bilateral movement with no deviations"},{"key": "D","text": "A visible/palpable 'catch' or aberrant movement pattern (e.g., painful arc, instability catch) during active range of motion"}],"correct": "D","explanation": "Clinical signs suggestive of lumbar segmental instability can include aberrant movement patterns such as a painful arc, instability catch, or reversal of lumbopelvic rhythm during active movement testing."},{"id": 7654,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Core stabilization exercise programs targeting the lumbar spine commonly emphasize activation of which deep muscle in particular?","options": [{"key": "A","text": "Transversus abdominis and multifidus"},{"key": "B","text": "Erector spinae exclusively, avoiding abdominal muscles"},{"key": "C","text": "External oblique only"},{"key": "D","text": "Rectus abdominis exclusively"}],"correct": "A","explanation": "Core stability programs often specifically target activation of the deep stabilizing muscles, transversus abdominis and multifidus, which show altered activation patterns in some low back pain populations."},{"id": 7655,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which factor is considered important in the biopsychosocial model of chronic low back pain management, beyond purely biomechanical factors?","options": [{"key": "A","text": "Age alone as the only relevant factor"},{"key": "B","text": "Genetics exclusively, with no other contributing factors"},{"key": "C","text": "Only structural/anatomical findings on imaging"},{"key": "D","text": "Psychological factors (e.g., fear-avoidance beliefs) and social factors influencing pain experience and disability"}],"correct": "D","explanation": "The biopsychosocial model recognizes that psychological factors (like fear-avoidance and catastrophizing) and social factors significantly influence the pain experience and disability in chronic low back pain, beyond purely structural considerations."},{"id": 7656,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "'Fear-avoidance' behavior in chronic low back pain patients refers to:","options": [{"key": "A","text": "Increased confidence in movement leading to better outcomes"},{"key": "B","text": "A specific structural spinal pathology"},{"key": "C","text": "Avoidance of activity/movement due to fear of pain or reinjury, potentially perpetuating disability"},{"key": "D","text": "A physical examination test"}],"correct": "C","explanation": "Fear-avoidance describes a behavioral pattern where patients avoid activities due to fear of causing pain or further injury, which can paradoxically contribute to increased disability and chronicity."},{"id": 7657,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Graded exposure/graded activity approaches in chronic low back pain rehabilitation aim to address which psychological factor?","options": [{"key": "A","text": "Fear-avoidance beliefs, by systematically and progressively reintroducing feared movements/activities"},{"key": "B","text": "Encouraging complete rest indefinitely"},{"key": "C","text": "Ignoring psychological factors entirely"},{"key": "D","text": "Increasing pain intensity intentionally"}],"correct": "A","explanation": "Graded exposure and graded activity approaches specifically target fear-avoidance beliefs by systematically reintroducing previously avoided movements/activities in a structured, progressive manner."},{"id": 7658,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Ankylosing spondylitis characteristically presents with which pattern of back pain, distinguishing it from typical mechanical low back pain?","options": [{"key": "A","text": "Pain limited strictly to one specific movement direction"},{"key": "B","text": "Pain that is purely activity-related with no morning stiffness"},{"key": "C","text": "Pain that improves with rest and worsens with activity"},{"key": "D","text": "Inflammatory back pain pattern: insidious onset, morning stiffness lasting >30-60 minutes, improvement with exercise, and often nocturnal pain"}],"correct": "D","explanation": "Inflammatory back pain, as seen in ankylosing spondylitis, classically presents with insidious onset in young adults, prolonged morning stiffness that improves with activity, and often disturbs sleep, contrasting with typical mechanical patterns."},{"id": 7659,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Modic changes, seen on MRI adjacent to the vertebral endplates, are associated with which condition?","options": [{"key": "A","text": "Purely congenital anomalies"},{"key": "B","text": "Only acute traumatic fractures"},{"key": "C","text": "Normal aging with no clinical significance in any case"},{"key": "D","text": "Degenerative disc disease, and in some cases correlated with chronic low back pain"}],"correct": "D","explanation": "Modic changes represent vertebral endplate/bone marrow signal changes on MRI associated with degenerative disc disease, and certain types have been correlated with chronic low back pain in research, though the relationship remains an area of ongoing study."},{"id": 7660,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which imaging finding is important to recognize as potentially present in asymptomatic individuals, cautioning against over-interpretation of MRI findings alone in low back pain?","options": [{"key": "A","text": "No imaging findings are ever present without symptoms"},{"key": "B","text": "Complete absence of any disc changes in all healthy adults"},{"key": "C","text": "Disc bulges/degeneration are commonly found on MRI even in asymptomatic individuals, increasing with age"},{"key": "D","text": "MRI findings always perfectly correlate with symptom severity"}],"correct": "C","explanation": "Research has demonstrated that disc bulges and degenerative changes are commonly found on MRI in asymptomatic individuals, with prevalence increasing with age, underscoring the importance of correlating imaging with clinical presentation rather than relying on imaging alone."},{"id": 7661,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Thoracic spine hypomobility is sometimes implicated as a contributing factor to which commonly co-occurring conditions in the kinetic chain?","options": [{"key": "A","text": "Only affects thoracic breathing mechanics with no musculoskeletal relevance"},{"key": "B","text": "No relationship to other body regions exists"},{"key": "C","text": "Shoulder impingement and cervical/lumbar compensatory dysfunction"},{"key": "D","text": "Isolated ankle sprains only, unrelated to spine mobility"}],"correct": "C","explanation": "Reduced thoracic spine mobility can contribute to compensatory movement patterns and increased stress at adjacent regions, being implicated in conditions like shoulder impingement and cervical or lumbar dysfunction."},{"id": 7662,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Costovertebral joint dysfunction can present with pain that may be mistaken for which other condition due to its location and referral pattern?","options": [{"key": "A","text": "Hip pathology exclusively"},{"key": "B","text": "Wrist pathology"},{"key": "C","text": "Ankle pathology"},{"key": "D","text": "Cardiac or pulmonary conditions, due to chest wall pain presentation"}],"correct": "D","explanation": "Costovertebral joint dysfunction can produce chest wall pain that sometimes mimics cardiac or pulmonary symptoms, requiring careful clinical differentiation and appropriate medical screening when indicated."},{"id": 7663,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Scheuermann's disease (juvenile kyphosis) is characterized by:","options": [{"key": "A","text": "Structural thoracic kyphosis with vertebral wedging, typically presenting in adolescence"},{"key": "B","text": "A traumatic fracture in adults"},{"key": "C","text": "Excessive lumbar lordosis only"},{"key": "D","text": "An acute inflammatory condition"}],"correct": "A","explanation": "Scheuermann's disease involves structural thoracic hyperkyphosis with characteristic vertebral body wedging, typically identified during adolescent growth."},{"id": 7664,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Which diagnostic criterion is often used to help identify Scheuermann's disease on radiographs, involving vertebral wedging?","options": [{"key": "A","text": "Anterior wedging of 5 degrees or more in at least three consecutive vertebrae"},{"key": "B","text": "Complete vertebral collapse"},{"key": "C","text": "Only posterior element fractures"},{"key": "D","text": "Any degree of wedging in a single vertebra"}],"correct": "A","explanation": "A commonly cited radiographic criterion for Scheuermann's disease involves anterior wedging of at least 5 degrees in three or more consecutive vertebrae."},{"id": 7665,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Scoliosis is defined radiographically using the Cobb angle; a curve is generally considered clinically significant (warranting closer monitoring/treatment) above which approximate threshold?","options": [{"key": "A","text": "Only curves exceeding 90 degrees are considered relevant"},{"key": "B","text": "No threshold exists, all curves are treated identically"},{"key": "C","text": "Approximately 10 degrees for diagnosis, with treatment thresholds typically higher (e.g., bracing often considered around 25-40 degrees depending on factors)"},{"key": "D","text": "Any curve greater than 0 degrees"}],"correct": "C","explanation": "A Cobb angle of 10 degrees or more is generally used as the diagnostic threshold for scoliosis, while treatment decisions (e.g., bracing, surgery) depend on additional factors including curve magnitude, growth potential, and progression risk."},{"id": 7666,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Adolescent idiopathic scoliosis is more commonly seen in which population?","options": [{"key": "A","text": "Equal incidence with no gender predominance"},{"key": "B","text": "Males more than females, with mild curves predominating"},{"key": "C","text": "Females more than males, particularly with curve progression"},{"key": "D","text": "Only in adults over 60"}],"correct": "C","explanation": "Adolescent idiopathic scoliosis shows a female predominance, particularly regarding curve progression requiring treatment."},{"id": 7667,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Physiotherapy scoliosis-specific exercise approaches (e.g., Schroth method) aim to address scoliosis through which mechanism?","options": [{"key": "A","text": "Three-dimensional postural correction, breathing techniques, and neuromuscular re-education to influence curve progression and function"},{"key": "B","text": "Complete curve reversal guaranteed in all patients"},{"key": "C","text": "No evidence-based rationale exists for any exercise approach"},{"key": "D","text": "Surgical correction replacement in all cases regardless of severity"}],"correct": "A","explanation": "Scoliosis-specific exercise approaches like Schroth aim to address the three-dimensional nature of the deformity through targeted postural correction, specific breathing patterns, and neuromuscular retraining, used as an adjunct within a comprehensive management approach."},{"id": 7668,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Piriformis syndrome-related sciatica differs from true lumbar disc-related sciatica primarily in which aspect of clinical presentation?","options": [{"key": "A","text": "Absence of true lumbar spine signs (e.g., normal neurological exam of lumbar myotomes/reflexes) with positive hip/buttock provocation tests"},{"key": "B","text": "Identical presentation in every respect with no distinguishing features"},{"key": "C","text": "Only occurs in elderly patients"},{"key": "D","text": "Always presents bilaterally, unlike disc-related sciatica"}],"correct": "A","explanation": "Piriformis-related sciatic symptoms typically lack the objective lumbar spine neurological findings (reflex/myotomal changes) seen in true disc-related radiculopathy, while showing positive provocation with hip-specific tests."},{"id": 7669,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which factor is associated with increased risk of chronicity/poor prognosis in acute low back pain (a 'yellow flag')?","options": [{"key": "A","text": "Positive expectations for recovery"},{"key": "B","text": "High levels of pain catastrophizing and fear-avoidance beliefs"},{"key": "C","text": "Early return to normal activity"},{"key": "D","text": "Strong social support"}],"correct": "B","explanation": "Yellow flags such as pain catastrophizing and strong fear-avoidance beliefs are psychosocial risk factors associated with increased likelihood of developing chronic, disabling low back pain."},{"id": 7670,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Manual therapy techniques (e.g., spinal mobilization/manipulation) for low back pain are generally considered most appropriate as part of:","options": [{"key": "A","text": "Only appropriate for chronic pain, never acute pain"},{"key": "B","text": "A treatment to be used indefinitely without any exercise component"},{"key": "C","text": "A multimodal approach combined with active exercise and education, rather than as an isolated passive treatment"},{"key": "D","text": "A standalone treatment with no need for exercise"}],"correct": "C","explanation": "Current evidence-based guidelines generally support manual therapy as part of a multimodal approach combined with active exercise and patient education, rather than as a standalone or exclusively passive treatment strategy."},{"id": 7671,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which exercise approach, focused on motor control and directional preference, has shown effectiveness for certain subgroups of low back pain patients?","options": [{"key": "A","text": "Motor control exercise targeting specific movement/muscle activation patterns, tailored to patient presentation"},{"key": "B","text": "Only passive modalities without any active component"},{"key": "C","text": "Random, non-specific general exercise with no clinical reasoning"},{"key": "D","text": "Complete bed rest"}],"correct": "A","explanation": "Motor control exercise approaches, which target specific movement patterns and muscle activation deficits tailored to the individual patient's presentation, have demonstrated effectiveness for certain low back pain subgroups."},{"id": 7672,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Facet joint (zygapophyseal) pain in the lumbar spine is often aggravated by which movement combination?","options": [{"key": "A","text": "Extension and rotation toward the symptomatic side"},{"key": "B","text": "No specific movement pattern is typical"},{"key": "C","text": "Flexion only"},{"key": "D","text": "Pure lateral flexion away from the symptomatic side only"}],"correct": "A","explanation": "Lumbar facet joint pain is classically aggravated by extension combined with ipsilateral rotation, which compresses/loads the facet joints on that side."},{"id": 7673,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Discogenic low back pain is often aggravated by which position/activity due to increased intradiscal pressure?","options": [{"key": "A","text": "Lying supine with knees bent"},{"key": "B","text": "Walking on a treadmill"},{"key": "C","text": "Prolonged sitting and forward flexion"},{"key": "D","text": "Standing"}],"correct": "C","explanation": "Discogenic pain is often aggravated by activities and positions that increase intradiscal pressure, such as prolonged sitting and forward flexion."},{"id": 7674,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which of the following is a recognized indication for surgical intervention in lumbar disc herniation, beyond failed conservative management?","options": [{"key": "A","text": "Absence of any neurological findings"},{"key": "B","text": "Mild, intermittent leg pain that responds well to physiotherapy"},{"key": "C","text": "Improvement in symptoms with conservative care"},{"key": "D","text": "Progressive neurological deficit or cauda equina syndrome"}],"correct": "D","explanation": "Progressive neurological deficit or cauda equina syndrome are recognized indications for more urgent surgical consideration in lumbar disc herniation, beyond the typical trial of conservative management for uncomplicated cases."},{"id": 7675,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which of the following describes the general natural history of most acute lumbar disc herniations managed conservatively?","options": [{"key": "A","text": "No improvement is ever seen without surgery"},{"key": "B","text": "Symptoms always worsen progressively without intervention"},{"key": "C","text": "Many cases show significant improvement over weeks to months, with the herniated fragment sometimes decreasing in size (resorption) over time"},{"key": "D","text": "Universal progression to surgery required"}],"correct": "C","explanation": "The natural history of many acute lumbar disc herniations, particularly without significant/progressive neurological deficit, shows substantial improvement with conservative management over time, with some herniated fragments demonstrating spontaneous resorption on follow-up imaging."},{"id": 7676,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Sacroiliac joint dysfunction is often assessed using a cluster of provocation tests because:","options": [{"key": "A","text": "No single test has adequate sensitivity/specificity alone, but a cluster of positive tests improves diagnostic confidence"},{"key": "B","text": "SI joint dysfunction cannot be assessed clinically at all"},{"key": "C","text": "Only imaging can diagnose SI joint dysfunction"},{"key": "D","text": "A single test alone provides perfect diagnostic accuracy"}],"correct": "A","explanation": "Given the limitations of individual SI joint provocation tests in isolation, using a cluster of tests (e.g., three or more positive) improves diagnostic confidence for SI joint-related pain."},{"id": 7677,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Coccydynia (tailbone pain) is commonly associated with which precipitating factor?","options": [{"key": "A","text": "Regular aerobic exercise"},{"key": "B","text": "Upper limb overuse"},{"key": "C","text": "Direct trauma (e.g., fall onto the tailbone) or prolonged sitting on hard surfaces"},{"key": "D","text": "No identifiable precipitating factors ever exist"}],"correct": "C","explanation": "Coccydynia is commonly associated with direct trauma such as a fall onto the tailbone, or repetitive/prolonged pressure from sitting on hard surfaces."},{"id": 7678,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which cushion modification is commonly recommended as a conservative management strategy for coccydynia?","options": [{"key": "A","text": "No cushion modification has any benefit"},{"key": "B","text": "Standing at all times with no sitting allowed"},{"key": "C","text": "A firm, flat cushion with no modification"},{"key": "D","text": "A wedge or donut-shaped cushion that offloads direct pressure from the coccyx"}],"correct": "D","explanation": "Specialized cushions (e.g., wedge or donut-shaped) that reduce direct pressure on the coccyx during sitting are commonly recommended as part of conservative coccydynia management."},{"id": 7679,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Thoracic outlet syndrome symptoms can sometimes be provoked or worsened by postural factors affecting which region, relevant to physiotherapy assessment?","options": [{"key": "A","text": "Hip position only"},{"key": "B","text": "Ankle position exclusively"},{"key": "C","text": "Lumbar lordosis exclusively, with no upper quarter relevance"},{"key": "D","text": "Cervical and shoulder girdle posture (e.g., forward head, elevated first rib, tight scalenes/pec minor)"}],"correct": "D","explanation": "Postural factors affecting the cervical spine and shoulder girdle, such as forward head posture and tightness of scalene or pectoralis minor muscles, can contribute to or exacerbate thoracic outlet syndrome symptoms."},{"id": 7680,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Lumbar extension-based exercise approaches (e.g., McKenzie extension protocol) are generally most appropriate for patients whose symptoms demonstrate which pattern?","options": [{"key": "A","text": "Only appropriate for patients with confirmed spinal stenosis"},{"key": "B","text": "Symptoms unaffected by any spinal movement direction"},{"key": "C","text": "Peripheralization of symptoms with any extension movement"},{"key": "D","text": "Centralization and reduction of leg symptoms with extension movements/repeated extension testing"}],"correct": "D","explanation": "Extension-based approaches are typically indicated for patients whose directional preference assessment shows centralization/improvement of symptoms with repeated extension movements, reflecting a derangement pattern that responds favorably to extension."},{"id": 7681,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Flexion-based exercise approaches (e.g., Williams flexion exercises) have traditionally been used for conditions such as which of the following, though evidence and specific application require clinical reasoning?","options": [{"key": "A","text": "Only appropriate immediately after spinal fracture"},{"key": "B","text": "All low back pain presentations universally, with no need for individualized assessment"},{"key": "C","text": "Acute disc herniation with extension preference"},{"key": "D","text": "Lumbar spinal stenosis, where flexion often provides symptomatic relief"}],"correct": "D","explanation": "Flexion-based approaches have traditionally been considered for conditions like spinal stenosis, where flexion tends to relieve neurogenic claudication symptoms by increasing canal dimensions, though individualized assessment remains essential."},{"id": 7682,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which of the following describes an appropriate physiotherapy approach when a patient with acute low back pain presents with signs concerning for a specific serious pathology (red flags)?","options": [{"key": "A","text": "Appropriately refer for further medical evaluation/investigation before proceeding with routine musculoskeletal management"},{"key": "B","text": "Ignore the findings and continue with symptomatic treatment only"},{"key": "C","text": "Proceed with standard exercise-based treatment regardless of findings"},{"key": "D","text": "Immediately discharge the patient with no further action"}],"correct": "A","explanation": "When red flags suggesting potential serious underlying pathology are identified, appropriate referral for further medical evaluation is essential before proceeding with routine musculoskeletal management."},{"id": 7683,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Baastrup's disease ('kissing spines') refers to:","options": [{"key": "A","text": "Abnormal contact and degenerative changes between adjacent spinous processes, often in the lumbar spine with hyperlordosis"},{"key": "B","text": "A congenital vertebral fusion"},{"key": "C","text": "A disc herniation pattern"},{"key": "D","text": "A ligamentous injury of the SI joint"}],"correct": "A","explanation": "Baastrup's disease describes degenerative changes from abnormal approximation/contact of adjacent spinous processes, often associated with increased lumbar lordosis, causing localized midline back pain typically relieved by flexion."},{"id": 7684,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Hard","question": "Degenerative spondylolisthesis, unlike isthmic (pars defect) spondylolisthesis, typically occurs due to which underlying process?","options": [{"key": "A","text": "Acute traumatic fracture in young athletes"},{"key": "B","text": "Degenerative changes of the facet joints and disc allowing gradual vertebral slippage, typically in older adults"},{"key": "C","text": "Infectious destruction of the vertebral body"},{"key": "D","text": "Congenital pars defect present from birth"}],"correct": "B","explanation": "Degenerative spondylolisthesis results from age-related degenerative changes in the facet joints and intervertebral disc, allowing gradual anterior vertebral slippage, typically affecting older adults, most commonly at L4-L5."},{"id": 7685,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which of the following best describes the role of patient education regarding imaging findings in managing non-specific low back pain?","options": [{"key": "A","text": "Emphasizing that all findings on imaging directly cause the pain and require aggressive intervention"},{"key": "B","text": "Providing reassurance and appropriate context, explaining that many imaging findings are common even in pain-free individuals, to reduce unnecessary fear/catastrophizing"},{"key": "C","text": "Avoiding any discussion of imaging findings entirely"},{"key": "D","text": "Recommending immediate surgery based solely on any abnormal imaging finding"}],"correct": "B","explanation": "Appropriate patient education about the limited correlation between certain imaging findings and pain, along with reassurance about the common prevalence of such findings in asymptomatic individuals, can help reduce unnecessary fear and support a more active management approach."},{"id": 7686,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which factor should be considered when determining an appropriate exercise dosage/progression for a patient with chronic low back pain and significant fear-avoidance beliefs?","options": [{"key": "A","text": "A graded, progressive approach considering both physical capacity and psychological readiness, potentially starting below the patient's perceived pain threshold and gradually progressing"},{"key": "B","text": "Avoiding exercise entirely until fear is completely resolved through other means"},{"key": "C","text": "Providing no structure or individualization to the exercise program"},{"key": "D","text": "Immediately prescribing maximal intensity exercise regardless of readiness"}],"correct": "A","explanation": "For patients with significant fear-avoidance, a carefully graded and progressive exercise approach, considering both physical and psychological factors, is generally recommended to build confidence and capacity systematically."},{"id": 7687,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Easy","question": "Osteoarthritis is best characterized as which type of joint disease?","options": [{"key": "A","text": "A purely genetic condition with no environmental contribution"},{"key": "B","text": "An infectious joint condition"},{"key": "C","text": "Primarily an autoimmune inflammatory condition"},{"key": "D","text": "A degenerative joint disease involving progressive cartilage breakdown and secondary bony changes"}],"correct": "D","explanation": "Osteoarthritis is fundamentally a degenerative process involving progressive articular cartilage breakdown, along with secondary changes including osteophyte formation and subchondral bone remodeling."},{"id": 7688,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which joint pattern is classically affected in osteoarthritis, typically involving weight-bearing and frequently used joints?","options": [{"key": "A","text": "Only the cervical spine"},{"key": "B","text": "Exclusively the shoulder joint"},{"key": "C","text": "Weight-bearing joints (hip, knee) and commonly used hand joints (DIP, first CMC), often asymmetric"},{"key": "D","text": "Small joints of hands/feet symmetrically, as the primary pattern"}],"correct": "C","explanation": "OA classically affects weight-bearing joints like the hip and knee, along with commonly used hand joints such as the distal interphalangeal (DIP) joints and first carpometacarpal joint, often in an asymmetric pattern."},{"id": 7689,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Easy","question": "Rheumatoid arthritis is classified as which type of disease process?","options": [{"key": "A","text": "A crystal-induced arthropathy"},{"key": "B","text": "A purely degenerative joint condition"},{"key": "C","text": "An infectious arthritis"},{"key": "D","text": "A systemic autoimmune inflammatory disease primarily affecting synovial joints"}],"correct": "D","explanation": "Rheumatoid arthritis is a systemic autoimmune disease characterized by chronic inflammation primarily targeting the synovium of joints, though it can have systemic manifestations beyond the joints."},{"id": 7690,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Rheumatoid arthritis classically presents with which joint involvement pattern, differing from osteoarthritis?","options": [{"key": "A","text": "Exclusively affects the spine"},{"key": "B","text": "Isolated single-joint involvement in all cases"},{"key": "C","text": "Asymmetric involvement of weight-bearing joints only"},{"key": "D","text": "Symmetric polyarticular involvement, often affecting MCP and PIP joints of the hands"}],"correct": "D","explanation": "RA classically presents with symmetric polyarticular involvement, with characteristic early involvement of the metacarpophalangeal (MCP) and proximal interphalangeal (PIP) joints, contrasting with the often asymmetric pattern and DIP joint involvement seen in OA."},{"id": 7691,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Morning stiffness lasting longer than which duration is more suggestive of an inflammatory arthritis (like RA) rather than osteoarthritis?","options": [{"key": "A","text": "Duration of morning stiffness has no diagnostic relevance"},{"key": "B","text": "Greater than 30-60 minutes"},{"key": "C","text": "Only relevant if lasting less than 5 minutes"},{"key": "D","text": "5 minutes"}],"correct": "B","explanation": "Inflammatory arthritides like RA classically present with prolonged morning stiffness, typically lasting more than 30-60 minutes, compared to the shorter, more transient stiffness typically seen in osteoarthritis."},{"id": 7692,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which laboratory marker, though not entirely specific, is commonly associated with rheumatoid arthritis diagnosis?","options": [{"key": "A","text": "Only ESR, with no other markers relevant"},{"key": "B","text": "HLA-B27 exclusively"},{"key": "C","text": "Uric acid level"},{"key": "D","text": "Rheumatoid factor (RF) and anti-citrullinated protein antibodies (anti-CCP)"}],"correct": "D","explanation": "Rheumatoid factor and anti-CCP antibodies are commonly used laboratory markers supporting an RA diagnosis, with anti-CCP generally showing higher specificity."},{"id": 7693,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Ulnar deviation of the fingers at the MCP joints, along with swan-neck and boutonniere deformities, are classic hand deformities associated with which condition in advanced stages?","options": [{"key": "A","text": "Rheumatoid arthritis"},{"key": "B","text": "Ankylosing spondylitis"},{"key": "C","text": "Gout"},{"key": "D","text": "Osteoarthritis"}],"correct": "A","explanation": "Advanced, poorly controlled rheumatoid arthritis classically produces characteristic hand deformities including MCP ulnar deviation, swan-neck, and boutonniere deformities due to chronic synovitis and ligamentous damage."},{"id": 7694,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Physiotherapy management during an acute rheumatoid arthritis flare typically emphasizes:","options": [{"key": "A","text": "Complete avoidance of all movement indefinitely, even after the flare resolves"},{"key": "B","text": "Joint protection principles, gentle range of motion, and rest of acutely inflamed joints, avoiding excessive stress"},{"key": "C","text": "High-impact activity to prevent stiffness"},{"key": "D","text": "Aggressive strengthening exercises regardless of joint inflammation status"}],"correct": "B","explanation": "During acute flares, management emphasizes joint protection, gentle ROM to prevent stiffness, and appropriate rest of significantly inflamed joints, avoiding excessive stress that could exacerbate inflammation."},{"id": 7695,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which exercise approach is generally recommended for rheumatoid arthritis patients during periods of disease remission/low activity?","options": [{"key": "A","text": "Only passive range of motion exercises, avoiding any active strengthening"},{"key": "B","text": "High-impact contact sports without restriction"},{"key": "C","text": "Complete avoidance of all exercise permanently"},{"key": "D","text": "Regular graded aerobic and resistance exercise to maintain function, bone health, and cardiovascular fitness"}],"correct": "D","explanation": "During periods of lower disease activity/remission, regular graded exercise including both aerobic and resistance training is generally recommended to maintain function, joint health, and overall fitness in RA patients."},{"id": 7696,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Ankylosing spondylitis is strongly associated with which genetic marker?","options": [{"key": "A","text": "HLA-B27"},{"key": "B","text": "HLA-DR4 exclusively"},{"key": "C","text": "Anti-dsDNA antibodies"},{"key": "D","text": "Rheumatoid factor positivity"}],"correct": "A","explanation": "Ankylosing spondylitis shows a strong association with the HLA-B27 genetic marker, though its presence alone is not diagnostic and many HLA-B27 positive individuals never develop the condition."},{"id": 7697,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Ankylosing spondylitis primarily and characteristically affects which anatomical structures first?","options": [{"key": "A","text": "Knee joints exclusively"},{"key": "B","text": "Sacroiliac joints and axial spine"},{"key": "C","text": "Peripheral small joints of the hands"},{"key": "D","text": "Temporomandibular joint exclusively"}],"correct": "B","explanation": "AS characteristically begins with inflammation of the sacroiliac joints (sacroiliitis) and progressively involves the axial spine, potentially leading to spinal fusion in advanced disease."},{"id": 7698,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Advanced, untreated ankylosing spondylitis can result in which characteristic spinal deformity/finding on imaging?","options": [{"key": "A","text": "Increased lumbar lordosis with preserved flexibility"},{"key": "B","text": "Progressive spinal fusion with a 'bamboo spine' appearance and loss of normal spinal curves/mobility"},{"key": "C","text": "No structural change occurs even in severe cases"},{"key": "D","text": "Isolated cervical hypermobility"}],"correct": "B","explanation": "Advanced AS can lead to progressive ossification and fusion of spinal segments, producing the characteristic 'bamboo spine' radiographic appearance and significant loss of spinal mobility."},{"id": 7699,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which postural deformity is a common concern in advanced ankylosing spondylitis if not appropriately managed?","options": [{"key": "A","text": "Progressive thoracic kyphosis and forward head posture, sometimes termed the 'question mark posture'"},{"key": "B","text": "No postural changes occur regardless of disease progression"},{"key": "C","text": "Scoliosis exclusively, with no sagittal plane changes"},{"key": "D","text": "Excessive lumbar lordosis with normal thoracic curve"}],"correct": "A","explanation": "Progressive kyphotic postural changes, sometimes described as a 'question mark' posture, can develop in advanced, poorly managed AS, making early postural and mobility-focused physiotherapy management important."},{"id": 7700,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Physiotherapy management for ankylosing spondylitis places strong emphasis on which type of exercise, given the disease's tendency toward stiffness/fusion?","options": [{"key": "A","text": "Avoiding all exercise due to fusion risk"},{"key": "B","text": "Regular extension-based mobility and postural exercises to counteract stiffness and maintain spinal extension/mobility"},{"key": "C","text": "Complete rest and avoidance of spinal movement"},{"key": "D","text": "Only isolated peripheral joint exercises with no spinal focus"}],"correct": "B","explanation": "Given the tendency toward progressive spinal stiffness and kyphotic deformity, physiotherapy for AS strongly emphasizes regular mobility exercises, particularly extension-based movements, to maintain spinal mobility and prevent/minimize deformity progression."},{"id": 7701,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Gout is characterized by which underlying pathological process?","options": [{"key": "A","text": "Progressive cartilage degeneration without crystal involvement"},{"key": "B","text": "Bacterial joint infection"},{"key": "C","text": "Deposition of monosodium urate crystals within joints, causing acute inflammatory arthritis"},{"key": "D","text": "Autoimmune synovial inflammation"}],"correct": "C","explanation": "Gout results from the deposition of monosodium urate crystals within joints (related to hyperuricemia), triggering acute, intensely painful inflammatory arthritis episodes."},{"id": 7702,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Gout classically affects which joint first in the majority of initial presentations?","options": [{"key": "A","text": "First metatarsophalangeal joint (podagra)"},{"key": "B","text": "Wrist joint"},{"key": "C","text": "Shoulder joint"},{"key": "D","text": "Knee joint"}],"correct": "A","explanation": "The first metatarsophalangeal joint is the classic initial site of gouty arthritis, a presentation termed 'podagra', though other joints can be affected especially with disease progression."},{"id": 7703,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "An acute gout attack typically presents with which characteristic onset and symptom pattern?","options": [{"key": "A","text": "Gradual onset over months with mild symptoms"},{"key": "B","text": "Rapid onset (often overnight) of severe pain, redness, swelling, and warmth in the affected joint"},{"key": "C","text": "Symmetric bilateral joint involvement from the outset"},{"key": "D","text": "No visible inflammatory signs at all"}],"correct": "B","explanation": "Acute gout classically presents with rapid, often overnight onset of severe joint pain accompanied by prominent inflammatory signs including redness, swelling, and warmth."},{"id": 7704,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Physiotherapy involvement during an acute gout flare is generally limited to which approach, given the acute inflammatory nature?","options": [{"key": "A","text": "Aggressive joint mobilization during the acute attack"},{"key": "B","text": "Immediate high-intensity strengthening"},{"key": "C","text": "Ignoring the condition entirely, physiotherapy has no role at any stage"},{"key": "D","text": "Rest, protection of the joint, and gentle range of motion as tolerated once acute inflammation begins to subside, with medical management addressing the acute crystal-induced inflammation"}],"correct": "D","explanation": "During the acute phase, physiotherapy input is typically limited, focusing on protection and gentle movement as tolerated once acute inflammation subsides, with medical management (e.g., anti-inflammatory medication) addressing the acute crystal-induced process."},{"id": 7705,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Pseudogout differs from true gout in that it involves deposition of which crystal type?","options": [{"key": "A","text": "No crystal deposition occurs in pseudogout"},{"key": "B","text": "Calcium pyrophosphate dihydrate (CPPD) crystals"},{"key": "C","text": "Calcium oxalate crystals"},{"key": "D","text": "Monosodium urate crystals"}],"correct": "B","explanation": "Pseudogout involves deposition of calcium pyrophosphate dihydrate crystals, distinguishing it from true gout's monosodium urate crystal deposition, though clinical presentation can be similar."},{"id": 7706,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Systemic Lupus Erythematosus (SLE) is characterized by which type of pathological process?","options": [{"key": "A","text": "A purely localized joint infection"},{"key": "B","text": "A crystal-induced arthropathy"},{"key": "C","text": "A systemic autoimmune condition that can affect multiple organ systems including joints, skin, kidneys, and other structures"},{"key": "D","text": "Isolated joint degeneration only"}],"correct": "C","explanation": "SLE is a systemic autoimmune disease with the potential to affect numerous organ systems beyond joints, including skin, kidneys, cardiovascular, and neurological systems, in addition to causing arthralgia/arthritis."},{"id": 7707,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Joint involvement in SLE, when present, is typically characterized by which pattern, often less destructive than RA?","options": [{"key": "A","text": "No joint involvement ever occurs in SLE"},{"key": "B","text": "Often non-erosive, though can still cause significant pain and, in some cases, deformity (Jaccoud's arthropathy) without typical radiographic erosions"},{"key": "C","text": "Severe erosive joint destruction identical to RA in all cases"},{"key": "D","text": "Only affects the spine, never peripheral joints"}],"correct": "B","explanation": "SLE arthritis is often non-erosive (unlike typical RA), though a subset of patients can develop a reducible deformity pattern (Jaccoud's arthropathy) related to ligamentous laxity rather than true bony erosion."},{"id": 7708,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which characteristic skin finding is classically associated with SLE, though not present in all patients?","options": [{"key": "A","text": "Nodular skin lesions over extensor surfaces exclusively"},{"key": "B","text": "Psoriatic plaques"},{"key": "C","text": "Erythema migrans"},{"key": "D","text": "Malar ('butterfly') rash across the cheeks and nose bridge"}],"correct": "D","explanation": "The classic malar or 'butterfly' rash across the cheeks and nasal bridge is a well-recognized, though not universal, cutaneous finding associated with SLE."},{"id": 7709,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Physiotherapy considerations for patients with SLE should include awareness of which factor that can significantly influence exercise tolerance and program design?","options": [{"key": "A","text": "Fatigue is a common and significant symptom in SLE, requiring careful exercise pacing and monitoring"},{"key": "B","text": "SLE has no impact on exercise capacity or fatigue"},{"key": "C","text": "Exercise is always contraindicated in SLE patients"},{"key": "D","text": "Only joint symptoms are relevant, with no other systemic considerations"}],"correct": "A","explanation": "Fatigue is a prominent and often debilitating symptom in SLE, requiring careful consideration in exercise prescription, including appropriate pacing and monitoring of the patient's response."},{"id": 7710,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Psoriatic arthritis is associated with which skin condition, and can present with a distinctive joint involvement pattern?","options": [{"key": "A","text": "Identical presentation to gout in all cases"},{"key": "B","text": "No associated skin condition exists"},{"key": "C","text": "Psoriasis, with joint patterns that can include DIP joint involvement and 'dactylitis' (sausage digit)"},{"key": "D","text": "Only affects internal organs with no skin or joint involvement"}],"correct": "C","explanation": "Psoriatic arthritis is associated with psoriasis and can present with distinctive patterns including DIP joint involvement and dactylitis (diffuse swelling of an entire digit, the 'sausage digit' appearance)."},{"id": 7711,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Reactive arthritis (formerly Reiter's syndrome) is classically triggered by which type of preceding event?","options": [{"key": "A","text": "Cold weather exposure exclusively"},{"key": "B","text": "A preceding infection, typically genitourinary or gastrointestinal"},{"key": "C","text": "Direct joint trauma only"},{"key": "D","text": "Chronic overuse without any infectious trigger"}],"correct": "B","explanation": "Reactive arthritis develops following a preceding infection, classically genitourinary (e.g., Chlamydia) or gastrointestinal, triggering an inflammatory arthritis response."},{"id": 7712,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Which of the seronegative spondyloarthropathies group includes ankylosing spondylitis, psoriatic arthritis, reactive arthritis, and enteropathic arthritis, sharing certain common clinical and genetic features?","options": [{"key": "A","text": "Osteoarthritis subtype classification"},{"key": "B","text": "Crystal arthropathy classification"},{"key": "C","text": "Rheumatoid arthritis subtype classification"},{"key": "D","text": "Seronegative spondyloarthropathies"}],"correct": "D","explanation": "Ankylosing spondylitis, psoriatic arthritis, reactive arthritis, and enteropathic arthritis (associated with inflammatory bowel disease) are grouped together as seronegative spondyloarthropathies, sharing features like HLA-B27 association and axial/enthesis involvement."},{"id": 7713,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Enthesitis, commonly seen in the seronegative spondyloarthropathies, refers to inflammation at which anatomical site?","options": [{"key": "A","text": "The site where tendons/ligaments attach to bone"},{"key": "B","text": "The joint capsule exclusively"},{"key": "C","text": "Muscle belly mid-substance"},{"key": "D","text": "Synovial membrane exclusively"}],"correct": "A","explanation": "Enthesitis specifically describes inflammation at entheses, the sites where tendons and ligaments attach to bone, a characteristic feature distinguishing spondyloarthropathies from rheumatoid arthritis."},{"id": 7714,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Total knee/hip arthroplasty is generally considered for patients with severe osteoarthritis when:","options": [{"key": "A","text": "Any radiographic evidence of OA regardless of symptoms"},{"key": "B","text": "Patient age is the sole determining factor"},{"key": "C","text": "Significant, persistent pain and functional limitation despite adequate conservative management trial"},{"key": "D","text": "Mild symptoms with good response to conservative management"}],"correct": "C","explanation": "Joint arthroplasty is generally reserved for patients with significant, persistent symptoms and functional limitation that have not adequately responded to a reasonable trial of conservative management."},{"id": 7715,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which exercise modality has strong evidence supporting benefit for knee osteoarthritis, focusing on both strength and function?","options": [{"key": "A","text": "High-impact plyometric training exclusively"},{"key": "B","text": "Complete avoidance of any lower limb exercise"},{"key": "C","text": "Land-based and/or aquatic therapeutic exercise programs including strengthening and functional training"},{"key": "D","text": "Only passive modalities with no active component"}],"correct": "C","explanation": "Both land-based and aquatic therapeutic exercise programs incorporating strengthening and functional training have strong evidence supporting improved pain and function in knee osteoarthritis."},{"id": 7716,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Aquatic therapy is often particularly beneficial for patients with significant arthritis-related joint pain due to which property of water?","options": [{"key": "A","text": "Water always worsens joint symptoms"},{"key": "B","text": "No specific benefit over land-based exercise"},{"key": "C","text": "Buoyancy reducing joint loading while providing resistance for strengthening"},{"key": "D","text": "Increased gravitational loading compared to land"}],"correct": "C","explanation": "Water's buoyancy property reduces effective joint loading during exercise while still providing resistance, making aquatic therapy particularly suitable for patients with significant joint pain who may struggle with land-based loading."},{"id": 7717,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Joint protection principles taught to patients with inflammatory arthritis (e.g., RA) typically include which strategy?","options": [{"key": "A","text": "Avoiding all activity permanently"},{"key": "B","text": "Distributing load across larger/stronger joints and using assistive devices/adapted techniques to reduce stress on vulnerable joints"},{"key": "C","text": "Ignoring joint positioning during daily tasks"},{"key": "D","text": "Using the smallest, weakest joints for demanding tasks whenever possible"}],"correct": "B","explanation": "Joint protection education emphasizes distributing load to larger, stronger joints, using proper body mechanics, and utilizing assistive devices/adapted techniques to minimize stress on vulnerable, potentially inflamed joints."},{"id": 7718,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which of the following describes an appropriate physiotherapy approach for a patient with rheumatoid arthritis regarding exercise intensity during periods of active, significant joint inflammation?","options": [{"key": "A","text": "No modification needed regardless of disease activity level"},{"key": "B","text": "Push through pain for maximal strengthening gains regardless of inflammation"},{"key": "C","text": "Complete cessation of all activity indefinitely, even after inflammation resolves"},{"key": "D","text": "Modify exercise intensity/type appropriately, favoring gentler ROM and avoiding high-load stress on acutely inflamed joints, while still encouraging appropriate activity"}],"correct": "D","explanation": "During periods of active significant inflammation, exercise intensity and type should be appropriately modified, favoring gentler approaches for affected joints while still encouraging safe activity, rather than either pushing through pain or stopping entirely."},{"id": 7719,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Easy","question": "Osteoarthritis pain is often described using which typical pattern in relation to activity?","options": [{"key": "A","text": "Constant unchanging pain regardless of any factor"},{"key": "B","text": "Pain unrelated to any mechanical factors"},{"key": "C","text": "Pain that typically worsens with activity/loading and improves with rest, at least in earlier stages"},{"key": "D","text": "Pain present only at rest, with no activity relationship"}],"correct": "C","explanation": "Osteoarthritis pain classically follows a mechanical pattern, worsening with activity/joint loading and improving with rest, at least in the earlier stages of the condition before potentially becoming more constant in advanced disease."},{"id": 7720,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Crepitus, a palpable/audible grinding sensation during joint movement, is a common clinical finding associated with which condition?","options": [{"key": "A","text": "Exclusively seen in gout"},{"key": "B","text": "Never a relevant clinical finding"},{"key": "C","text": "Osteoarthritis, related to irregular cartilage surfaces"},{"key": "D","text": "Only acute traumatic fracture"}],"correct": "C","explanation": "Crepitus is a commonly observed clinical finding in osteoarthritis, related to the irregular, roughened articular cartilage surfaces characteristic of the degenerative process."},{"id": 7721,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Heberden's nodes, bony enlargements at which finger joints, are a classic clinical finding in hand osteoarthritis?","options": [{"key": "A","text": "MCP joints"},{"key": "B","text": "PIP joints"},{"key": "C","text": "DIP joints"},{"key": "D","text": "Wrist joints"}],"correct": "C","explanation": "Heberden's nodes are characteristic bony enlargements occurring at the distal interphalangeal (DIP) joints, a classic finding in hand osteoarthritis."},{"id": 7722,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Bouchard's nodes, similar bony enlargements but occurring at a different finger joint compared to Heberden's nodes, are found at which location?","options": [{"key": "A","text": "DIP joints"},{"key": "B","text": "PIP joints"},{"key": "C","text": "MCP joints only"},{"key": "D","text": "Thumb CMC joint exclusively"}],"correct": "B","explanation": "Bouchard's nodes are the analogous bony enlargements occurring at the proximal interphalangeal (PIP) joints in hand osteoarthritis, distinguishing their location from the DIP-located Heberden's nodes."},{"id": 7723,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Which of the following medications, commonly used in RA management, requires physiotherapists to be aware of potential effects on wound healing and infection risk, particularly relevant post-surgically?","options": [{"key": "A","text": "Simple analgesics like paracetamol"},{"key": "B","text": "Disease-modifying antirheumatic drugs (DMARDs) and biologic agents"},{"key": "C","text": "Vitamin supplements exclusively"},{"key": "D","text": "Only topical creams with no systemic effect"}],"correct": "B","explanation": "DMARDs and biologic agents used in RA management can affect immune function and wound healing, which is clinically relevant information for physiotherapists, particularly in post-surgical rehabilitation contexts."},{"id": 7724,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which functional outcome measure is commonly used across various arthritis conditions to assess patient-reported physical function and disability?","options": [{"key": "A","text": "DASH score exclusively, regardless of joint involved"},{"key": "B","text": "Health Assessment Questionnaire (HAQ) or similar disease-specific/general function questionnaires"},{"key": "C","text": "Only radiographic grading, with no patient-reported measures used"},{"key": "D","text": "Berg Balance Scale exclusively"}],"correct": "B","explanation": "The Health Assessment Questionnaire and similar patient-reported outcome measures are commonly used across various arthritis conditions to assess functional status and disability from the patient's perspective."},{"id": 7725,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Septic arthritis is a medical emergency requiring urgent recognition; which clinical presentation should raise immediate suspicion?","options": [{"key": "A","text": "Acute, severe joint pain with significant swelling, warmth, and often fever/systemic illness"},{"key": "B","text": "Bilateral symmetric joint stiffness lasting exactly 30 minutes each morning"},{"key": "C","text": "Gradual onset mild joint stiffness over months"},{"key": "D","text": "Chronic, well-tolerated joint pain with no inflammatory signs"}],"correct": "A","explanation": "Septic arthritis presents with acute, severe joint symptoms including significant pain, swelling, warmth, and often systemic signs like fever, requiring urgent medical evaluation and treatment given the risk of rapid joint destruction and systemic sepsis."},{"id": 7726,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which of the following is an appropriate action if a physiotherapist suspects septic arthritis in a patient presenting for musculoskeletal assessment?","options": [{"key": "A","text": "Apply heat and encourage vigorous movement of the joint"},{"key": "B","text": "Urgently refer for medical evaluation given the emergency nature of the condition"},{"key": "C","text": "Wait several weeks to see if symptoms resolve spontaneously before taking any action"},{"key": "D","text": "Proceed with standard exercise-based treatment as usual"}],"correct": "B","explanation": "Given the emergency nature and risk of rapid joint destruction/systemic complications with septic arthritis, urgent medical referral is required rather than proceeding with routine physiotherapy management."},{"id": 7727,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Fibromyalgia is characterized by which core clinical feature, distinguishing it from classic inflammatory or degenerative arthritis?","options": [{"key": "A","text": "Objective joint swelling and erosive changes on imaging"},{"key": "B","text": "Elevated inflammatory markers in all cases"},{"key": "C","text": "Isolated single-joint involvement with clear structural pathology"},{"key": "D","text": "Widespread chronic pain with tenderness at multiple points, without the objective joint damage/inflammation seen in conditions like RA or OA"}],"correct": "D","explanation": "Fibromyalgia is characterized by widespread chronic musculoskeletal pain and tenderness, notably without the objective structural joint damage or significant inflammatory markers typically seen in conditions like RA or OA."},{"id": 7728,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which exercise approach is generally recommended for fibromyalgia management, supported by evidence?","options": [{"key": "A","text": "No exercise recommendations exist for this condition"},{"key": "B","text": "Complete avoidance of exercise due to pain sensitivity"},{"key": "C","text": "Only high-intensity interval training regardless of patient tolerance"},{"key": "D","text": "Graded aerobic exercise, often starting at low intensity and progressing gradually, alongside other multimodal management strategies"}],"correct": "D","explanation": "Graded, low-to-moderate intensity aerobic exercise, progressed gradually according to patient tolerance, has good evidence supporting benefit in fibromyalgia management as part of a broader multimodal approach."},{"id": 7729,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which of the following describes 'pacing' as a self-management strategy often taught to patients with chronic inflammatory or widespread pain conditions?","options": [{"key": "A","text": "Balancing activity and rest strategically to avoid symptom flare-ups from overexertion, rather than a boom-bust cycle"},{"key": "B","text": "Avoiding all activity permanently"},{"key": "C","text": "Ignoring symptoms entirely and pushing through regardless of consequences"},{"key": "D","text": "Working at maximal intensity until symptoms force a complete stop"}],"correct": "A","explanation": "Pacing involves strategically balancing activity levels with adequate rest to avoid the common 'boom-bust' cycle of overexertion followed by significant symptom flare, helping patients maintain more consistent function over time."},{"id": 7730,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Polymyalgia rheumatica typically presents in which age group with which characteristic symptom pattern?","options": [{"key": "A","text": "Older adults (typically over 50) with proximal muscle pain/stiffness, particularly shoulder and hip girdle regions"},{"key": "B","text": "Young adults with isolated joint pain"},{"key": "C","text": "Neonates with congenital deformity"},{"key": "D","text": "Children with peripheral joint swelling"}],"correct": "A","explanation": "Polymyalgia rheumatica classically affects older adults, presenting with proximal muscle pain and stiffness particularly involving the shoulder and hip girdle regions, often with significant morning stiffness."},{"id": 7731,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Polymyalgia rheumatica has an important clinical association requiring screening for which serious condition due to shared pathophysiology/co-occurrence?","options": [{"key": "A","text": "Reactive arthritis"},{"key": "B","text": "Giant cell (temporal) arteritis"},{"key": "C","text": "Gout"},{"key": "D","text": "Osteoarthritis"}],"correct": "B","explanation": "Polymyalgia rheumatica has a notable clinical association with giant cell arteritis, and patients should be screened for symptoms of this condition (e.g., headache, visual disturbance, jaw claudication) given the risk of serious complications like vision loss if untreated."},{"id": 7732,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Juvenile idiopathic arthritis (JIA) refers to:","options": [{"key": "A","text": "Osteoarthritis occurring in children"},{"key": "B","text": "A group of chronic arthritis conditions with onset before age 16, of unknown/idiopathic origin"},{"key": "C","text": "A purely traumatic condition"},{"key": "D","text": "An adult-onset condition misdiagnosed in children"}],"correct": "B","explanation": "Juvenile idiopathic arthritis encompasses a heterogeneous group of chronic arthritis conditions with onset in childhood (before age 16), of idiopathic (unknown) origin, distinct from adult-onset arthritis conditions."},{"id": 7733,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Physiotherapy management for JIA should consider which important factor specific to the pediatric population, beyond typical adult arthritis considerations?","options": [{"key": "A","text": "Growth and development considerations, including potential impact of chronic inflammation on growth plates and the importance of maintaining function for normal developmental activities"},{"key": "B","text": "Only cosmetic considerations, with no functional relevance"},{"key": "C","text": "No special considerations are needed, treat identically to adult arthritis"},{"key": "D","text": "JIA never requires any physiotherapy involvement"}],"correct": "A","explanation": "Physiotherapy for JIA must consider the unique pediatric context, including potential effects of chronic inflammation on growth and the critical importance of maintaining function to support normal developmental and participation needs."},{"id": 7734,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which type of exercise is generally contraindicated or requires significant caution during an acutely inflamed/swollen joint in an inflammatory arthritis flare?","options": [{"key": "A","text": "High-load resistance exercise directly stressing the acutely inflamed joint"},{"key": "B","text": "Appropriate rest positioning"},{"key": "C","text": "Gentle pain-free active range of motion"},{"key": "D","text": "Ice application for symptom management"}],"correct": "A","explanation": "High-load resistance exercise directly stressing an acutely inflamed joint is generally avoided or requires significant caution during active inflammatory flares, in favor of gentler approaches until inflammation subsides."},{"id": 7735,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which of the following best describes the concept of 'disease-modifying' treatment in inflammatory arthritis (e.g., DMARDs in RA), distinguishing it from purely symptomatic treatment?","options": [{"key": "A","text": "Aims to alter the underlying disease process and slow/prevent structural joint damage, beyond just symptom control"},{"key": "B","text": "Only provides temporary symptom relief with no effect on disease progression"},{"key": "C","text": "Is identical in mechanism and goal to simple analgesic medication"},{"key": "D","text": "Has no relevance to long-term joint outcomes"}],"correct": "A","explanation": "Disease-modifying treatments aim to address the underlying inflammatory disease process itself, slowing or preventing structural joint damage over time, distinguishing them from treatments that only provide symptomatic relief without altering disease progression."},{"id": 7736,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Hard","question": "Post-total joint arthroplasty rehabilitation for a patient with underlying inflammatory arthritis (e.g., RA) may require additional consideration of which factor compared to a patient with isolated osteoarthritis?","options": [{"key": "A","text": "Potential involvement of multiple joints, systemic disease activity, and medication effects on healing/rehabilitation progression"},{"key": "B","text": "No additional considerations are needed in any case"},{"key": "C","text": "Only cosmetic outcome differences"},{"key": "D","text": "Complete avoidance of any rehabilitation"}],"correct": "A","explanation": "Patients with underlying systemic inflammatory arthritis undergoing joint arthroplasty may require additional consideration of multi-joint involvement, overall systemic disease activity, and potential medication effects on healing, which can influence rehabilitation planning compared to isolated OA cases."},{"id": 7737,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which of the following statements accurately reflects current understanding regarding exercise and osteoarthritis progression?","options": [{"key": "A","text": "Appropriate exercise worsens joint degeneration in all cases and should be avoided"},{"key": "B","text": "Appropriately dosed exercise is generally safe and beneficial, without evidence of accelerating structural OA progression in most circumstances"},{"key": "C","text": "Exercise has no relevance to OA management at all"},{"key": "D","text": "Only complete joint immobilization prevents OA progression"}],"correct": "B","explanation": "Current evidence generally supports that appropriately dosed exercise is safe for patients with osteoarthritis and does not appear to accelerate structural disease progression in most circumstances, while providing symptomatic and functional benefits."},{"id": 7738,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Easy","question": "Osteoporosis is characterized by which primary pathological change in bone?","options": [{"key": "A","text": "Infection-related bone destruction"},{"key": "B","text": "Excessive bone formation without resorption"},{"key": "C","text": "Reduced bone mass and micro-architectural deterioration, increasing fracture risk"},{"key": "D","text": "Increased bone mineral density with normal architecture"}],"correct": "C","explanation": "Osteoporosis involves reduced bone mineral density and deterioration of bone micro-architecture, resulting in increased bone fragility and fracture risk."},{"id": 7739,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Osteoporosis diagnosis is typically confirmed using which measurement, expressed as a T-score?","options": [{"key": "A","text": "MRI signal intensity"},{"key": "B","text": "Dual-energy X-ray absorptiometry (DEXA) scan bone mineral density measurement"},{"key": "C","text": "CT Hounsfield units exclusively"},{"key": "D","text": "Plain X-ray density estimation alone"}],"correct": "B","explanation": "DEXA scanning is the gold standard for measuring bone mineral density, with results expressed as a T-score used to diagnose osteoporosis and osteopenia."},{"id": 7740,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "A T-score of -2.5 or lower on DEXA scan is diagnostic of which condition?","options": [{"key": "A","text": "Osteopenia"},{"key": "B","text": "Osteomalacia"},{"key": "C","text": "Osteoporosis"},{"key": "D","text": "Normal bone density"}],"correct": "C","explanation": "A T-score of -2.5 or below meets the WHO diagnostic criteria for osteoporosis, while a T-score between -1.0 and -2.5 indicates osteopenia."},{"id": 7741,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Which type of exercise is particularly recommended for stimulating bone mineral density improvement in osteoporosis management?","options": [{"key": "A","text": "Complete rest and avoidance of physical activity"},{"key": "B","text": "Purely non-weight-bearing swimming only"},{"key": "C","text": "Only passive stretching exercises"},{"key": "D","text": "Weight-bearing and resistance exercise, providing appropriate mechanical loading stimulus to bone"}],"correct": "D","explanation": "Weight-bearing and resistance exercise provide the mechanical loading stimulus needed to promote bone remodeling and help maintain or improve bone mineral density in osteoporosis management."},{"id": 7742,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Which exercise/movement should generally be avoided or approached with caution in patients with significant osteoporosis, particularly with vertebral involvement, due to increased fracture risk?","options": [{"key": "A","text": "Balance training"},{"key": "B","text": "High-impact activities and excessive spinal flexion movements (e.g., toe-touches with rounded spine)"},{"key": "C","text": "Gentle weight-bearing walking"},{"key": "D","text": "Appropriate resistance training within guidelines"}],"correct": "B","explanation": "High-impact activities and excessive spinal flexion (particularly combined with loading) are generally approached cautiously or avoided in significant osteoporosis due to increased risk of vertebral compression fracture."},{"id": 7743,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Osteomalacia refers to:","options": [{"key": "A","text": "A purely genetic bone disorder with no nutritional component"},{"key": "B","text": "A crystal-induced arthropathy"},{"key": "C","text": "Excessive bone mineralization"},{"key": "D","text": "Defective mineralization of newly formed bone matrix (osteoid) in adults, often related to vitamin D deficiency"}],"correct": "D","explanation": "Osteomalacia describes defective mineralization of bone osteoid in adults, commonly related to vitamin D deficiency or metabolism disorders, resulting in soft, weakened bone."},{"id": 7744,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Rickets refers to the pediatric equivalent of which adult metabolic bone condition, occurring before growth plate closure?","options": [{"key": "A","text": "Osteoporosis"},{"key": "B","text": "Paget's disease"},{"key": "C","text": "Osteomalacia"},{"key": "D","text": "Osteopetrosis"}],"correct": "C","explanation": "Rickets is the pediatric counterpart of osteomalacia, involving defective mineralization affecting the growing skeleton, classically related to vitamin D deficiency, before growth plate closure."},{"id": 7745,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Which classic skeletal deformity is associated with rickets in children due to weight-bearing on softened bone?","options": [{"key": "A","text": "Bowing of the long bones (e.g., genu varum) and widened growth plates"},{"key": "B","text": "Kyphoscoliosis exclusively"},{"key": "C","text": "Complete absence of any deformity"},{"key": "D","text": "Isolated skull deformity only"}],"correct": "A","explanation": "Rickets classically produces bowing deformities of weight-bearing long bones (such as genu varum) along with widened, irregular growth plates, related to inadequate mineralization of the growing skeleton."},{"id": 7746,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Paget's disease of bone is characterized by which abnormal process?","options": [{"key": "A","text": "Complete cessation of bone remodeling"},{"key": "B","text": "Pure bone resorption without any new bone formation"},{"key": "C","text": "Excessive, disorganized bone remodeling with abnormally increased osteoclastic and osteoblastic activity, producing structurally weaker bone"},{"key": "D","text": "A purely inflammatory joint condition with no bone involvement"}],"correct": "C","explanation": "Paget's disease involves excessive and disorganized bone remodeling, with abnormally increased turnover producing enlarged but structurally weaker, more fracture-prone bone."},{"id": 7747,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Hard","question": "Which bones are most commonly affected by Paget's disease?","options": [{"key": "A","text": "Pelvis, spine, skull, and long bones (particularly femur and tibia)"},{"key": "B","text": "Only the small bones of the hands/feet"},{"key": "C","text": "Exclusively the ribs"},{"key": "D","text": "Only the cervical spine"}],"correct": "A","explanation": "Paget's disease commonly affects the pelvis, spine, skull, and long bones such as the femur and tibia, though any bone can potentially be involved."},{"id": 7748,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Hard","question": "Which laboratory marker is characteristically elevated in Paget's disease, reflecting increased bone turnover?","options": [{"key": "A","text": "Serum calcium exclusively"},{"key": "B","text": "Uric acid"},{"key": "C","text": "Serum alkaline phosphatase"},{"key": "D","text": "Rheumatoid factor"}],"correct": "C","explanation": "Elevated serum alkaline phosphatase, reflecting increased osteoblastic activity, is a characteristic laboratory finding in Paget's disease of bone."},{"id": 7749,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Hard","question": "Which complication is a recognized risk in long-standing Paget's disease, requiring vigilance?","options": [{"key": "A","text": "Complete resolution without any complications"},{"key": "B","text": "No increased fracture risk compared to normal bone"},{"key": "C","text": "Only cosmetic concerns with no functional impact"},{"key": "D","text": "Pathological fracture, bone deformity, and rarely malignant transformation (osteosarcoma)"}],"correct": "D","explanation": "Long-standing Paget's disease carries risk of pathological fracture through weakened, disorganized bone, progressive deformity, and rarely malignant transformation to osteosarcoma."},{"id": 7750,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Easy","question": "Which population group is at particularly increased risk of developing osteoporosis due to hormonal changes?","options": [{"key": "A","text": "Prepubescent children"},{"key": "B","text": "Postmenopausal women, due to declining estrogen levels"},{"key": "C","text": "Middle-aged men with normal testosterone levels"},{"key": "D","text": "Young athletic males"}],"correct": "B","explanation": "Postmenopausal women are at significantly increased osteoporosis risk due to declining estrogen levels, which normally help maintain bone density by regulating bone remodeling."},{"id": 7751,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Secondary osteoporosis can result from which of the following contributing factors, distinct from primary age/hormone-related osteoporosis?","options": [{"key": "A","text": "Regular weight-bearing exercise"},{"key": "B","text": "Normal physical activity levels"},{"key": "C","text": "Prolonged corticosteroid use, certain endocrine disorders, or prolonged immobilization"},{"key": "D","text": "Adequate calcium and vitamin D intake"}],"correct": "C","explanation": "Secondary osteoporosis can result from various contributing factors including prolonged corticosteroid therapy, endocrine disorders (e.g., hyperthyroidism), and prolonged immobilization, distinct from primary age-related bone loss."},{"id": 7752,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Fall prevention strategies are a critical component of osteoporosis management primarily to reduce risk of which outcome?","options": [{"key": "A","text": "Muscle hypertrophy"},{"key": "B","text": "Cardiovascular disease"},{"key": "C","text": "Improved bone density directly"},{"key": "D","text": "Fragility fractures resulting from falls in individuals with reduced bone strength"}],"correct": "D","explanation": "Given the increased fracture risk associated with reduced bone density, fall prevention strategies are a critical component of comprehensive osteoporosis management to reduce fragility fracture incidence."},{"id": 7753,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Which balance/functional exercise component is often incorporated into osteoporosis management programs specifically to address fall risk?","options": [{"key": "A","text": "Only isolated strength training with no balance component"},{"key": "B","text": "Complete avoidance of any dynamic movement"},{"key": "C","text": "Only static stretching exercises"},{"key": "D","text": "Balance and functional mobility training alongside strengthening and weight-bearing exercise"}],"correct": "D","explanation": "Comprehensive osteoporosis exercise programs typically incorporate balance and functional mobility training alongside strengthening and weight-bearing components, specifically targeting fall risk reduction."},{"id": 7754,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Vitamin D plays which key role relevant to bone health and metabolic bone disease prevention?","options": [{"key": "A","text": "No relevant role in bone metabolism"},{"key": "B","text": "Only relevant to skin health, not bone"},{"key": "C","text": "Facilitating intestinal calcium absorption, essential for adequate bone mineralization"},{"key": "D","text": "Directly causing bone resorption"}],"correct": "C","explanation": "Vitamin D plays a crucial role in facilitating intestinal calcium absorption, essential for adequate bone mineralization; deficiency contributes to conditions like osteomalacia and rickets."},{"id": 7755,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Hard","question": "Osteopetrosis, in contrast to osteoporosis, is characterized by which abnormal process?","options": [{"key": "A","text": "Defective osteoclast function leading to abnormally increased bone density, though the bone is often more brittle"},{"key": "B","text": "Complete absence of bone mineralization"},{"key": "C","text": "Excessive bone resorption"},{"key": "D","text": "Identical pathology to osteoporosis with different terminology only"}],"correct": "A","explanation": "Osteopetrosis involves defective osteoclast function, resulting in abnormally increased bone density; however, despite the increased density, the bone is often structurally abnormal and more prone to fracture."},{"id": 7756,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Medium","question": "Which patient education point is important when counseling on fracture risk reduction in significant osteoporosis, related to functional activities?","options": [{"key": "A","text": "No modification of daily activities is ever necessary"},{"key": "B","text": "Educating on safe movement patterns (e.g., proper lifting technique, avoiding excessive spinal flexion under load) to reduce vertebral fracture risk"},{"key": "C","text": "Encouraging aggressive spinal flexion exercises for core strengthening"},{"key": "D","text": "Complete avoidance of all functional activity"}],"correct": "B","explanation": "Patient education regarding safe movement patterns, particularly avoiding excessive spinal flexion under load during daily activities, is an important component of reducing vertebral fracture risk in significant osteoporosis."},{"id": 7757,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Hard","question": "Renal osteodystrophy refers to bone changes that develop secondary to which underlying condition?","options": [{"key": "A","text": "Chronic kidney disease, affecting calcium/phosphate/vitamin D metabolism"},{"key": "B","text": "Acute traumatic injury"},{"key": "C","text": "Primary bone malignancy"},{"key": "D","text": "Isolated dietary calcium deficiency alone"}],"correct": "A","explanation": "Renal osteodystrophy describes the complex bone changes that develop secondary to chronic kidney disease, related to disturbances in calcium, phosphate, vitamin D, and parathyroid hormone regulation."},{"id": 7758,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Osteosarcoma, the most common primary malignant bone tumor, most typically occurs in which age group and location?","options": [{"key": "A","text": "Infants, in the skull"},{"key": "B","text": "Elderly patients, in the spine"},{"key": "C","text": "Adolescents/young adults, most commonly around the knee (distal femur/proximal tibia)"},{"key": "D","text": "Middle-aged adults, in the ribs exclusively"}],"correct": "C","explanation": "Osteosarcoma classically affects adolescents and young adults, with the most common location being the metaphyseal region around the knee (distal femur or proximal tibia), correlating with areas of rapid bone growth."},{"id": 7759,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Hard","question": "Which radiographic finding is classically associated with osteosarcoma, reflecting periosteal reaction?","options": [{"key": "A","text": "Complete absence of any bony change"},{"key": "B","text": "Smooth, well-circumscribed lesion with no periosteal reaction"},{"key": "C","text": "Punched-out lytic lesions without any periosteal involvement"},{"key": "D","text": "Sunburst pattern or Codman's triangle, reflecting aggressive periosteal reaction"}],"correct": "D","explanation": "The classic 'sunburst' appearance and Codman's triangle (elevated periosteum) are characteristic aggressive radiographic findings associated with osteosarcoma."},{"id": 7760,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Hard","question": "Ewing sarcoma, another malignant pediatric bone tumor, classically presents with which radiographic periosteal reaction pattern?","options": [{"key": "A","text": "Sunburst pattern exclusively"},{"key": "B","text": "'Onion-skin' layered periosteal reaction"},{"key": "C","text": "Complete cortical destruction with no reactive changes"},{"key": "D","text": "No periosteal reaction ever occurs"}],"correct": "B","explanation": "Ewing sarcoma classically demonstrates a multi-layered 'onion-skin' periosteal reaction pattern on radiographs, distinct from but sometimes overlapping with other aggressive lesion appearances."},{"id": 7761,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Which benign bone tumor commonly presents in adolescents/young adults with characteristic nighttime pain that is classically relieved by NSAIDs?","options": [{"key": "A","text": "Ewing sarcoma"},{"key": "B","text": "Osteosarcoma"},{"key": "C","text": "Chondrosarcoma"},{"key": "D","text": "Osteoid osteoma"}],"correct": "D","explanation": "Osteoid osteoma classically presents with characteristic nocturnal pain that is often dramatically relieved by NSAIDs, a helpful clinical clue in diagnosis."},{"id": 7762,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Multiple myeloma, a malignant plasma cell neoplasm affecting bone, typically presents in which age group?","options": [{"key": "A","text": "Neonates"},{"key": "B","text": "Adolescents exclusively"},{"key": "C","text": "Older adults, typically over 60"},{"key": "D","text": "Children"}],"correct": "C","explanation": "Multiple myeloma is a disease of older adults, typically presenting in patients over 60 years, and is a common cause of pathological fracture and bone pain in this population."},{"id": 7763,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Metastatic bone disease, the most common cause of malignant bone lesions overall, most commonly originates from which primary cancers?","options": [{"key": "A","text": "No common primary sites exist"},{"key": "B","text": "Only skin cancer"},{"key": "C","text": "Only pediatric cancers"},{"key": "D","text": "Breast, prostate, lung, kidney, and thyroid cancers"}],"correct": "D","explanation": "The most common primary cancers that metastasize to bone include breast, prostate, lung, kidney, and thyroid cancers, making metastatic disease the most common overall cause of malignant bone lesions, particularly in older adults."},{"id": 7764,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Which clinical presentation should raise suspicion for a pathological fracture secondary to underlying bone tumor/metastasis, rather than a simple traumatic fracture?","options": [{"key": "A","text": "No distinguishing features exist between pathological and traumatic fractures"},{"key": "B","text": "Fracture occurring with minimal or no trauma, especially in a patient with known malignancy history or unexplained bone pain preceding the fracture"},{"key": "C","text": "Fracture in a well-conditioned athlete after significant impact"},{"key": "D","text": "Fracture following high-energy trauma in a young healthy individual"}],"correct": "B","explanation": "A fracture occurring with minimal or no trauma, particularly with a history of known malignancy or preceding unexplained bone pain, should raise suspicion for an underlying pathological process rather than simple trauma."},{"id": 7765,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Which physiotherapy consideration is critical when managing a patient with known or suspected bone metastasis, particularly regarding exercise prescription?","options": [{"key": "A","text": "Encourage maximal high-impact loading regardless of lesion status"},{"key": "B","text": "No special precautions are needed, treat identically to non-oncology patients"},{"key": "C","text": "Careful consideration of fracture risk at affected sites, potentially requiring modified/protected loading and close communication with the medical team"},{"key": "D","text": "Complete avoidance of any physiotherapy involvement in all oncology patients"}],"correct": "C","explanation": "Physiotherapy management for patients with known or suspected bone metastases requires careful consideration of pathological fracture risk at affected sites, often necessitating modified exercise prescription and close interprofessional communication."},{"id": 7766,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Easy","question": "Osteomyelitis refers to:","options": [{"key": "A","text": "Infection of the bone, which can be acute or chronic"},{"key": "B","text": "A metabolic bone disorder unrelated to infection"},{"key": "C","text": "A degenerative joint condition"},{"key": "D","text": "A benign bone tumor"}],"correct": "A","explanation": "Osteomyelitis is an infection involving bone tissue, which can present acutely or develop into a chronic condition if inadequately treated."},{"id": 7767,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Hard","question": "Acute hematogenous osteomyelitis in children most commonly affects which anatomical region of long bones, related to vascular anatomy?","options": [{"key": "A","text": "Articular cartilage only"},{"key": "B","text": "Epiphysis exclusively"},{"key": "C","text": "Diaphysis exclusively"},{"key": "D","text": "Metaphysis, due to the relatively sluggish blood flow in this region favoring bacterial seeding"}],"correct": "D","explanation": "The metaphyseal region of long bones, with its relatively sluggish vascular flow pattern in growing children, is the classic site for hematogenous seeding of bacteria in acute osteomyelitis."},{"id": 7768,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Which organism is the most common causative pathogen in acute osteomyelitis across most age groups?","options": [{"key": "A","text": "Streptococcus pneumoniae exclusively"},{"key": "B","text": "Mycobacterium tuberculosis"},{"key": "C","text": "Staphylococcus aureus"},{"key": "D","text": "Escherichia coli"}],"correct": "C","explanation": "Staphylococcus aureus is the most common causative organism responsible for acute osteomyelitis across most patient populations and age groups."},{"id": 7769,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Hard","question": "Chronic osteomyelitis can be characterized by which pathological finding, representing dead, infected bone that has separated from healthy bone?","options": [{"key": "A","text": "Complete resolution with no residual pathology"},{"key": "B","text": "Excessive new bone formation with no infection markers"},{"key": "C","text": "Isolated soft tissue involvement only"},{"key": "D","text": "Sequestrum formation"}],"correct": "D","explanation": "Sequestrum, representing necrotic, infected bone fragments that have separated from viable surrounding bone, is a characteristic finding in chronic osteomyelitis."},{"id": 7770,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Hard","question": "Which clinical presentation is characteristic of TB (tuberculous) spondylitis (Pott's disease), often distinguishing it from acute pyogenic spinal infection?","options": [{"key": "A","text": "Rapid onset with high fever and acute severe pain, resolving quickly with antibiotics"},{"key": "B","text": "Insidious, chronic onset with back pain, low-grade constitutional symptoms, and potential progressive deformity/neurological compromise if untreated"},{"key": "C","text": "No back pain ever occurs"},{"key": "D","text": "Only affects peripheral joints, never the spine"}],"correct": "B","explanation": "TB spondylitis (Pott's disease) classically presents with an insidious, chronic course involving back pain and constitutional symptoms (low-grade fever, weight loss), with risk of progressive vertebral destruction, deformity (gibbus), and potential neurological compromise if untreated."},{"id": 7771,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Hard","question": "Pott's disease characteristically affects which region of the vertebral body initially, related to the pattern of spread?","options": [{"key": "A","text": "Posterior elements primarily"},{"key": "B","text": "Exclusively the facet joints"},{"key": "C","text": "Only the spinous processes"},{"key": "D","text": "Anterior vertebral body, often affecting adjacent vertebrae with disc space involvement"}],"correct": "D","explanation": "Tuberculous spondylitis typically begins in the anterior vertebral body (often near the endplate), with a tendency to spread to adjacent vertebrae, characteristically involving the intervertebral disc space."},{"id": 7772,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Hard","question": "'Gibbus deformity', a sharp angular kyphosis, is a recognized complication of untreated or advanced which spinal condition?","options": [{"key": "A","text": "Tuberculous spondylitis (Pott's disease) with vertebral collapse"},{"key": "B","text": "Isolated disc herniation without bone involvement"},{"key": "C","text": "Ankylosing spondylitis exclusively"},{"key": "D","text": "Simple mechanical low back pain"}],"correct": "A","explanation": "Progressive vertebral body destruction and collapse in untreated Pott's disease can result in a sharp, angular kyphotic deformity known as gibbus deformity."},{"id": 7773,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Septic arthritis, involving infection within a joint, is considered an orthopedic emergency primarily due to risk of which rapid complication?","options": [{"key": "A","text": "Guaranteed complete recovery regardless of treatment timing"},{"key": "B","text": "Rapid articular cartilage destruction if not promptly treated"},{"key": "C","text": "No significant complications if left untreated"},{"key": "D","text": "Slow, gradual joint stiffness over years with no urgency"}],"correct": "B","explanation": "Septic arthritis requires urgent recognition and treatment due to the risk of rapid, potentially irreversible articular cartilage destruction if appropriate treatment (often including joint drainage/washout and antibiotics) is delayed."},{"id": 7774,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Which physiotherapy role is appropriate once a patient with osteomyelitis or septic arthritis has received appropriate medical/surgical treatment and is medically stable for rehabilitation?","options": [{"key": "A","text": "Progressive rehabilitation addressing range of motion, strength, and functional recovery, guided by ongoing communication with the medical team regarding infection status/precautions"},{"key": "B","text": "No role exists for physiotherapy at any stage"},{"key": "C","text": "Immediate aggressive high-impact activity regardless of infection status"},{"key": "D","text": "Complete avoidance of any movement indefinitely even after medical clearance"}],"correct": "A","explanation": "Once medically stable and cleared by the treating medical team, physiotherapy plays an important role in progressive rehabilitation addressing range of motion, strength, and functional recovery following bone/joint infection, with appropriate ongoing communication regarding any precautions."},{"id": 7775,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Which of the following 'red flag' presentations in a patient presenting for musculoskeletal assessment should prompt consideration of possible underlying malignancy, warranting further medical investigation?","options": [{"key": "A","text": "Unexplained weight loss, progressive unremitting pain (including significant night pain unrelated to position), and pain not responding to typical conservative measures"},{"key": "B","text": "Mechanical pain that clearly varies with specific movements/positions and responds to conservative treatment"},{"key": "C","text": "Age under 30 with clear traumatic onset and typical mechanical presentation"},{"key": "D","text": "Pain that improves with appropriate exercise and rest"}],"correct": "A","explanation": "Red flags such as unexplained weight loss, progressive unremitting pain including significant night pain, and lack of response to appropriate conservative measures should prompt consideration of serious underlying pathology including possible malignancy, warranting further medical investigation."},{"id": 7776,"subject": "Orthopedics","topic": "Bone Tumors & Infections","difficulty": "Medium","question": "Benign bone lesions such as simple bone cysts are often identified incidentally or present with which complication in children/adolescents?","options": [{"key": "A","text": "Immediate malignant transformation in all cases"},{"key": "B","text": "Pathological fracture through the weakened area of bone"},{"key": "C","text": "Rapid metastatic spread"},{"key": "D","text": "No clinical relevance at any point"}],"correct": "B","explanation": "Simple bone cysts, though benign, weaken the local bone structure and are often identified incidentally or present clinically following a pathological fracture through the cystic lesion."},{"id": 7777,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Congenital talipes equinovarus (CTEV), commonly known as clubfoot, is characterized by which combination of foot deformities?","options": [{"key": "A","text": "Only excessive dorsiflexion"},{"key": "B","text": "Isolated flatfoot deformity"},{"key": "C","text": "Hindfoot equinus and varus, midfoot cavus, and forefoot adduction"},{"key": "D","text": "Only forefoot abduction"}],"correct": "C","explanation": "CTEV (clubfoot) is characterized by a combination of hindfoot equinus (plantarflexion) and varus, midfoot cavus, and forefoot adduction, often remembered by the mnemonic CAVE."},{"id": 7778,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which conservative treatment method is considered the gold-standard first-line approach for congenital clubfoot management?","options": [{"key": "A","text": "Ponseti method, involving serial casting followed by bracing"},{"key": "B","text": "Complete observation with no treatment until adulthood"},{"key": "C","text": "Only physiotherapy with no casting or bracing"},{"key": "D","text": "Immediate extensive surgical correction in all cases"}],"correct": "A","explanation": "The Ponseti method, involving sequential gentle manipulation and casting followed by a bracing maintenance phase, is the internationally recognized gold-standard first-line treatment for clubfoot."},{"id": 7779,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "In the Ponseti method for clubfoot, which structure/tendon often requires a minor surgical release (tenotomy) to fully correct the equinus component?","options": [{"key": "A","text": "Peroneal tendons"},{"key": "B","text": "Achilles tendon (percutaneous tenotomy)"},{"key": "C","text": "Flexor hallucis longus tendon"},{"key": "D","text": "Tibialis anterior tendon"}],"correct": "B","explanation": "A percutaneous Achilles tenotomy is commonly required as part of the Ponseti protocol to adequately correct the equinus (plantarflexion) component of the clubfoot deformity, typically performed after the serial casting phase."},{"id": 7780,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Following Ponseti casting correction, maintenance of clubfoot correction typically requires which ongoing intervention to prevent relapse?","options": [{"key": "A","text": "No further intervention needed once casting is complete"},{"key": "B","text": "Immediate return to unrestricted normal footwear"},{"key": "C","text": "A foot abduction bracing (orthosis) protocol, worn according to a structured weaning schedule"},{"key": "D","text": "Permanent, uninterrupted rigid casting for years"}],"correct": "C","explanation": "Following successful casting correction, a structured foot abduction bracing protocol is essential to maintain correction and minimize relapse risk, with wearing time gradually reduced over time per protocol."},{"id": 7781,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Developmental Dysplasia of the Hip (DDH) encompasses a spectrum of abnormalities ranging from which mild to severe presentation?","options": [{"key": "A","text": "Only affects the knee joint, not the hip"},{"key": "B","text": "Only complete dislocation, with no milder forms recognized"},{"key": "C","text": "Exclusively a congenital fusion, unrelated to instability"},{"key": "D","text": "Mild acetabular dysplasia/instability through to frank dislocation of the hip"}],"correct": "D","explanation": "DDH represents a spectrum of hip joint developmental abnormalities, ranging from mild acetabular dysplasia and instability to complete dislocation of the femoral head from the acetabulum."},{"id": 7782,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which clinical screening tests are classically used to assess for hip instability in newborns/infants suspected of DDH?","options": [{"key": "A","text": "Spurling's test and distraction test"},{"key": "B","text": "McMurray test and Lachman test"},{"key": "C","text": "Ober's test and Thomas test"},{"key": "D","text": "Barlow test and Ortolani test"}],"correct": "D","explanation": "The Barlow test (attempting to dislocate an unstable hip) and Ortolani test (attempting to relocate a dislocated hip) are the classic clinical screening maneuvers used to assess for hip instability in infants."},{"id": 7783,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "A positive Ortolani test in a newborn hip examination is characterized by:","options": [{"key": "A","text": "Pain with any hip movement, with no palpable sensation"},{"key": "B","text": "A palpable 'clunk' as a dislocated femoral head reduces back into the acetabulum during hip abduction"},{"key": "C","text": "No palpable finding at all"},{"key": "D","text": "Complete absence of hip movement"}],"correct": "B","explanation": "A positive Ortolani test demonstrates a palpable/audible 'clunk' as gentle abduction and anterior pressure reduce a previously dislocated femoral head back into the acetabulum."},{"id": 7784,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which risk factor is associated with increased likelihood of DDH in newborns?","options": [{"key": "A","text": "Prematurity alone with no other associated factors"},{"key": "B","text": "Twin pregnancy protects against DDH risk"},{"key": "C","text": "Male gender, cephalic presentation, and no family history"},{"key": "D","text": "Female gender, breech presentation, and positive family history"}],"correct": "D","explanation": "Female gender, breech presentation, and a positive family history of DDH are well-recognized risk factors associated with increased likelihood of developmental dysplasia of the hip."},{"id": 7785,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which orthotic device is commonly used as first-line conservative treatment for DDH diagnosed in early infancy?","options": [{"key": "A","text": "Ankle-foot orthosis"},{"key": "B","text": "No treatment is used, observation only regardless of severity"},{"key": "C","text": "Pavlik harness, maintaining the hip in a flexed, abducted position to promote stable reduction/development"},{"key": "D","text": "Rigid hip spica cast immediately in all cases"}],"correct": "C","explanation": "The Pavlik harness, which maintains the hip in a flexed and abducted position, is the standard first-line conservative treatment for DDH diagnosed in early infancy, promoting stable joint development."},{"id": 7786,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Legg-Calve-Perthes disease, involving idiopathic avascular necrosis of the femoral head, most commonly presents in which age group?","options": [{"key": "A","text": "Adolescents over 15 years"},{"key": "B","text": "Adults over 40 years"},{"key": "C","text": "Children typically aged 4-10 years, with peak incidence around 5-7 years"},{"key": "D","text": "Infants under 1 year"}],"correct": "C","explanation": "Legg-Calve-Perthes disease classically presents in children aged approximately 4-10 years, with peak incidence around 5-7 years, and shows a male predominance."},{"id": 7787,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Perthes disease classically presents with which clinical symptom pattern?","options": [{"key": "A","text": "Acute severe hip pain with obvious trauma history"},{"key": "B","text": "Sudden onset of bilateral knee swelling with no hip involvement"},{"key": "C","text": "No functional limitation, purely an incidental imaging finding"},{"key": "D","text": "Insidious onset of limp and hip/groin/knee pain, often with limited hip internal rotation and abduction on examination"}],"correct": "D","explanation": "Perthes disease typically presents with an insidious onset of limp and hip, groin, or referred knee pain, with clinical examination often revealing limited hip internal rotation and abduction."},{"id": 7788,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Management goals for Perthes disease generally focus on which principle, particularly regarding the femoral head shape during the healing process?","options": [{"key": "A","text": "'Containment' of the femoral head within the acetabulum during the reparative phase to promote a more spherical healed shape and reduce long-term deformity"},{"key": "B","text": "Immediate hip replacement in all pediatric cases"},{"key": "C","text": "No treatment is ever indicated, the condition always resolves without intervention or management consideration"},{"key": "D","text": "Complete immobilization with no weight-bearing for years regardless of severity"}],"correct": "A","explanation": "A key management principle in Perthes disease is 'containment' of the femoral head within the acetabulum during the vulnerable reparative phase, aiming to promote a more spherical healed femoral head shape and reduce long-term degenerative risk."},{"id": 7789,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Slipped Capital Femoral Epiphysis (SCFE) involves displacement of which structure relative to the femoral neck?","options": [{"key": "A","text": "The greater trochanter"},{"key": "B","text": "The acetabulum itself"},{"key": "C","text": "The femoral head (capital epiphysis) slipping posteriorly and inferiorly relative to the femoral neck through the growth plate"},{"key": "D","text": "The lesser trochanter"}],"correct": "C","explanation": "SCFE involves posterior and inferior displacement (slippage) of the capital femoral epiphysis relative to the femoral neck, occurring through the vulnerable growth plate (physis)."},{"id": 7790,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which population is at increased risk for SCFE, given its association with body habitus and growth patterns?","options": [{"key": "A","text": "Obese adolescents, particularly during the pubertal growth spurt, more commonly males"},{"key": "B","text": "Exclusively affects elite young athletes with low body fat"},{"key": "C","text": "Underweight adolescent females"},{"key": "D","text": "Only affects children under age 5"}],"correct": "A","explanation": "SCFE shows increased incidence in obese adolescents during the pubertal growth spurt, with a higher prevalence in males, related to increased mechanical shear stress across the vulnerable growth plate."},{"id": 7791,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "SCFE typically presents with which clinical symptom pattern, sometimes with a notable characteristic regarding referred pain?","options": [{"key": "A","text": "Often insidious onset of hip, groin, thigh, or referred knee pain with an antalgic/limping gait; occasionally acute-on-chronic presentation following minor trauma"},{"key": "B","text": "No pain ever present, purely an incidental radiographic finding"},{"key": "C","text": "Acute severe trauma-related pain only, with no chronic component"},{"key": "D","text": "Isolated ankle pain with no proximal symptoms"}],"correct": "A","explanation": "SCFE often presents with an insidious onset of symptoms including hip, groin, thigh, or referred knee pain and a limp, though some cases present acutely (sometimes as an acute slip on a chronic pre-existing slip) following minor trauma."},{"id": 7792,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Why is referred knee pain clinically important to recognize in the context of SCFE assessment?","options": [{"key": "A","text": "Referred pain patterns are never clinically relevant in pediatric orthopedics"},{"key": "B","text": "A patient presenting with knee pain but with an underlying hip problem (like SCFE) may be misdiagnosed/delayed if the hip is not also examined"},{"key": "C","text": "Knee pain always indicates primary knee pathology with no relevance to the hip"},{"key": "D","text": "SCFE never causes any referred symptoms"}],"correct": "B","explanation": "Recognizing that hip pathology like SCFE can present with referred knee pain is clinically important, as failing to examine the hip in a child presenting with knee pain risks missed or delayed diagnosis of the underlying hip condition."},{"id": 7793,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Management of SCFE, once diagnosed, generally requires which approach to prevent further slippage?","options": [{"key": "A","text": "Surgical stabilization (typically pin fixation) to prevent further epiphyseal displacement"},{"key": "B","text": "No treatment is required, spontaneous resolution is expected in all cases"},{"key": "C","text": "Only physiotherapy exercises, without any surgical consideration"},{"key": "D","text": "Conservative management with rest alone, avoiding any surgical intervention"}],"correct": "A","explanation": "SCFE generally requires surgical stabilization, typically with pin fixation across the growth plate, to prevent further slippage and its associated complications once diagnosed."},{"id": 7794,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Which serious complication is a recognized risk following SCFE, particularly with unstable/severe slips, similar to concerns seen with femoral neck fractures?","options": [{"key": "A","text": "Guaranteed normal hip function regardless of slip severity"},{"key": "B","text": "Immediate complete resolution with no risk of any sequelae"},{"key": "C","text": "Avascular necrosis of the femoral head"},{"key": "D","text": "No complications are ever associated with SCFE"}],"correct": "C","explanation": "Avascular necrosis of the femoral head is a recognized and serious potential complication of SCFE, particularly associated with unstable or severe slips, related to disruption of the femoral head's vascular supply."},{"id": 7795,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Blount's disease refers to:","options": [{"key": "A","text": "A shoulder condition in infants"},{"key": "B","text": "A growth disorder of the proximal medial tibial physis causing progressive genu varum (bowing)"},{"key": "C","text": "An ankle deformity exclusively"},{"key": "D","text": "A hip dysplasia condition"}],"correct": "B","explanation": "Blount's disease involves abnormal growth at the proximal medial tibial physis, resulting in progressive pathological genu varum (bow-leg) deformity, distinct from normal physiological bowing seen in early childhood."},{"id": 7796,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Physiological genu varum (bow-leggedness) in toddlers typically follows which natural developmental course, important to distinguish from pathological conditions like Blount's disease?","options": [{"key": "A","text": "Immediate correction within the first month of life"},{"key": "B","text": "Permanent unchanging deformity throughout life without any treatment"},{"key": "C","text": "Progressive worsening throughout childhood with no spontaneous correction"},{"key": "D","text": "Gradual spontaneous improvement/correction with growth, typically resolving by around age 2-3 years"}],"correct": "D","explanation": "Physiological genu varum in toddlers typically shows gradual spontaneous correction with growth, usually resolving by approximately age 2-3 years, in contrast to pathological conditions like Blount's disease which tend to progress without intervention."},{"id": 7797,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Idiopathic toe walking in young children, when other neurological/developmental causes have been ruled out, is generally managed initially with which approach for milder cases?","options": [{"key": "A","text": "No management is ever appropriate, the pattern always requires surgical intervention"},{"key": "B","text": "Immediate surgical Achilles tendon lengthening in all cases regardless of severity"},{"key": "C","text": "Observation, stretching, and monitoring, as many cases improve with growth and conservative management"},{"key": "D","text": "Permanent rigid leg casting from birth"}],"correct": "C","explanation": "For idiopathic toe walking without underlying neurological cause, initial management typically involves observation, stretching exercises, and monitoring, as many milder cases show improvement with conservative approaches and growth."},{"id": 7798,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which underlying conditions must be considered and ruled out when evaluating a child presenting with toe walking, given the differential diagnosis?","options": [{"key": "A","text": "Only cardiac conditions need to be considered"},{"key": "B","text": "Toe walking has only one possible cause and requires no differential consideration"},{"key": "C","text": "Toe walking is always purely a behavioral choice with no medical relevance"},{"key": "D","text": "Neurological conditions (e.g., cerebral palsy), muscular conditions, and other developmental factors, in addition to idiopathic toe walking"}],"correct": "D","explanation": "Evaluation of a child with toe walking requires consideration of a differential diagnosis including neurological conditions like cerebral palsy, muscular conditions, and other developmental factors, in addition to the diagnosis of idiopathic toe walking by exclusion."},{"id": 7799,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Adolescent idiopathic scoliosis screening in schools/clinical practice commonly uses which simple clinical test to detect potential curves?","options": [{"key": "A","text": "Ober's test"},{"key": "B","text": "Thomas test"},{"key": "C","text": "Adam's forward bend test, assessing for rib hump/asymmetry"},{"key": "D","text": "Straight leg raise test"}],"correct": "C","explanation": "Adam's forward bend test, observing for rib hump or trunk asymmetry as the child bends forward, is a simple, commonly used clinical screening test for scoliosis."},{"id": 7800,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Bracing for adolescent idiopathic scoliosis is generally considered for curves within which approximate range, in a skeletally immature patient, to attempt to prevent progression?","options": [{"key": "A","text": "Curves less than 10 degrees"},{"key": "B","text": "Moderate curves, often in the approximate range of 25-40 degrees, in a growing/skeletally immature patient"},{"key": "C","text": "Only curves exceeding 90 degrees"},{"key": "D","text": "Bracing is never used regardless of curve magnitude or growth status"}],"correct": "B","explanation": "Bracing is generally considered for moderate curves (often cited approximately in the 25-40 degree range) in skeletally immature, growing patients, aiming to prevent further curve progression during the remaining growth period."},{"id": 7801,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Congenital muscular torticollis, related to sternocleidomastoid tightness/fibrosis, is typically managed in infancy with which first-line conservative approach?","options": [{"key": "A","text": "Rigid neck bracing for years"},{"key": "B","text": "No treatment is ever indicated"},{"key": "C","text": "Immediate surgical release regardless of severity or age"},{"key": "D","text": "Stretching exercises and positioning strategies, often successful if initiated early"}],"correct": "D","explanation": "First-line management of congenital muscular torticollis typically involves stretching exercises and positioning strategies, which are often successful when initiated early in infancy, with surgery reserved for cases not responding to conservative management."},{"id": 7802,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Which associated condition should be screened for in infants diagnosed with congenital muscular torticollis, given a recognized clinical association?","options": [{"key": "A","text": "Isolated ankle deformity, with no other associations"},{"key": "B","text": "Cardiac malformations exclusively"},{"key": "C","text": "No associated conditions require screening"},{"key": "D","text": "Developmental dysplasia of the hip (DDH), given a recognized association between the two conditions"}],"correct": "D","explanation": "Given a recognized clinical association, infants diagnosed with congenital muscular torticollis should also be screened for developmental dysplasia of the hip."},{"id": 7803,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Osgood-Schlatter disease, a traction apophysitis at the tibial tuberosity, is particularly common in which population during a specific developmental period?","options": [{"key": "A","text": "Infants under 1 year"},{"key": "B","text": "Adults over 50"},{"key": "C","text": "Exclusively in sedentary individuals with no relationship to activity level"},{"key": "D","text": "Active adolescents during growth spurts, particularly those involved in running/jumping sports"}],"correct": "D","explanation": "Osgood-Schlatter disease is particularly common in active adolescents during growth spurts, especially those participating in running and jumping sports that create repetitive traction stress at the tibial tuberosity via the patellar tendon."},{"id": 7804,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Management of Osgood-Schlatter disease typically involves which general approach, given its usually self-limiting nature?","options": [{"key": "A","text": "Activity modification/relative rest during symptomatic periods, along with quadriceps/hamstring flexibility and appropriate strengthening, as the condition is generally self-limiting with growth plate closure"},{"key": "B","text": "No conservative management options exist"},{"key": "C","text": "Immediate surgical intervention in all cases regardless of severity"},{"key": "D","text": "Complete cessation of all physical activity permanently, even after symptom resolution"}],"correct": "A","explanation": "Osgood-Schlatter disease is typically managed conservatively with activity modification during symptomatic periods and appropriate flexibility/strengthening work, as the condition is generally self-limiting, resolving with skeletal maturity and growth plate closure."},{"id": 7805,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which of the following describes 'growing pains' in children, a common benign condition requiring differentiation from more serious pathology?","options": [{"key": "A","text": "Typically benign, often bilateral lower limb pain occurring in the evening/night, with normal physical examination and no functional limitation during the day"},{"key": "B","text": "Always indicates serious underlying pathology requiring urgent investigation"},{"key": "C","text": "Always associated with fever and systemic illness"},{"key": "D","text": "Exclusively occurs in adults, never in children"}],"correct": "A","explanation": "Growing pains typically present as benign, often bilateral lower limb pain occurring in the evening or night, with an otherwise normal physical examination and no daytime functional limitation, requiring differentiation from more serious causes of limb pain in children."},{"id": 7806,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which red flag features in a child presenting with limb pain would warrant further investigation to rule out serious pathology (e.g., malignancy, infection), distinguishing from benign growing pains?","options": [{"key": "A","text": "Pain only occurring after vigorous physical activity during the day"},{"key": "B","text": "Bilateral symmetric pain occurring only at night with normal examination and normal activity levels during the day"},{"key": "C","text": "Pain that resolves completely by morning with no residual symptoms"},{"key": "D","text": "Unilateral persistent pain, systemic symptoms (fever, weight loss), night pain that wakes the child with associated swelling/limp, or abnormal physical examination findings"}],"correct": "D","explanation": "Red flags such as unilateral persistent pain, systemic symptoms, pain with associated swelling or limp, or abnormal examination findings should prompt further investigation to rule out more serious underlying pathology in a child presenting with limb pain."},{"id": 7807,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which gait pattern might be observed in a child with underlying hip pathology (e.g., Perthes disease, SCFE), reflecting pain avoidance and/or weakness?","options": [{"key": "A","text": "An antalgic and/or Trendelenburg-type gait pattern, reflecting pain avoidance and/or hip abductor dysfunction"},{"key": "B","text": "A perfectly normal, unaltered gait pattern in all cases"},{"key": "C","text": "Exclusively a toe-walking pattern with no other gait deviations possible"},{"key": "D","text": "Only affects upper limb movement patterns during gait"}],"correct": "A","explanation": "Children with underlying hip pathology such as Perthes disease or SCFE often demonstrate an antalgic gait and/or Trendelenburg-type pattern, reflecting pain avoidance behavior and/or hip abductor dysfunction secondary to the underlying condition."},{"id": 7808,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Physiotherapy management following surgical intervention for a pediatric orthopedic condition (e.g., post-operative Perthes or SCFE management) should consider which important developmental factor, distinct from adult rehabilitation?","options": [{"key": "A","text": "No developmental considerations are relevant, treat identically to adult post-operative protocols"},{"key": "B","text": "Only cosmetic outcomes matter, with no functional rehabilitation considerations"},{"key": "C","text": "Complete avoidance of any post-operative rehabilitation in pediatric patients"},{"key": "D","text": "The child's ongoing growth, developmental stage, and need for age-appropriate engagement strategies in the rehabilitation process"}],"correct": "D","explanation": "Pediatric rehabilitation must consider the child's ongoing growth and developmental stage, along with using age-appropriate engagement strategies to optimize participation and outcomes, distinguishing it from adult-focused rehabilitation approaches."},{"id": 7809,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Metatarsus adductus, a common congenital foot positional deformity, is characterized by which finding?","options": [{"key": "A","text": "Only affects the ankle joint, not the foot itself"},{"key": "B","text": "Medial deviation (adduction) of the forefoot relative to the hindfoot, with a normal hindfoot position"},{"key": "C","text": "Hindfoot equinus with forefoot abduction"},{"key": "D","text": "Complete rigid deformity unresponsive to any passive correction in all cases"}],"correct": "B","explanation": "Metatarsus adductus involves medial deviation of the forefoot relative to a normally positioned hindfoot, distinguishing it from the more complex multi-planar deformity seen in true clubfoot (CTEV)."},{"id": 7810,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Flexible flatfoot in children, a very common finding, is generally distinguished from a potentially pathological rigid flatfoot by which key examination finding?","options": [{"key": "A","text": "Both types always require identical, aggressive surgical management"},{"key": "B","text": "Presence of an arch on non-weight-bearing/tip-toe standing (flexible) versus absence of arch formation even non-weight-bearing (suggesting rigid, potentially pathological)"},{"key": "C","text": "Flexible flatfoot is always more concerning than rigid flatfoot"},{"key": "D","text": "No distinguishing features exist between flexible and rigid flatfoot"}],"correct": "B","explanation": "Flexible flatfoot typically shows arch reformation with non-weight-bearing or tip-toe standing, distinguishing it from a rigid flatfoot (where the arch fails to reform), which requires further investigation as it may indicate underlying pathology such as tarsal coalition."},{"id": 7811,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Tarsal coalition, an abnormal connection between two or more tarsal bones, is a recognized cause of which clinical presentation in adolescents?","options": [{"key": "A","text": "Purely a cosmetic finding with no functional relevance"},{"key": "B","text": "Rigid, painful flatfoot, often with peroneal muscle spasm, typically becoming symptomatic in later childhood/adolescence as the coalition ossifies"},{"key": "C","text": "Isolated finger deformity"},{"key": "D","text": "Complete absence of any symptoms in all affected individuals"}],"correct": "B","explanation": "Tarsal coalition can present with a rigid, painful flatfoot, often accompanied by peroneal muscle spasm, typically becoming symptomatic during later childhood or adolescence as the coalition progressively ossifies and restricts normal subtalar motion."},{"id": 7812,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Which of the following is an important physiotherapy consideration when working with a child who has Perthes disease during the active disease phase, particularly regarding activity modification?","options": [{"key": "A","text": "Complete bed rest and total immobilization is the only appropriate approach in all phases and severities"},{"key": "B","text": "Encourage unrestricted high-impact activity throughout the entire disease course"},{"key": "C","text": "No physiotherapy involvement is ever indicated in Perthes disease management"},{"key": "D","text": "Activity modification to reduce high-impact loading on the vulnerable femoral head during the active/fragmentation phase, per orthopedic guidance, while maintaining appropriate mobility and strength within recommended limits"}],"correct": "D","explanation": "During the active phase of Perthes disease, activity modification to reduce high-impact loading on the vulnerable femoral head is typically recommended per orthopedic guidance, while physiotherapy still plays a role in maintaining appropriate mobility and strength within advised limits."},{"id": 7813,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Hard","question": "Sprengel deformity refers to a congenital condition involving which structure?","options": [{"key": "A","text": "A specific spinal deformity unrelated to the shoulder"},{"key": "B","text": "Congenital elevation/malposition of the scapula, often with limited shoulder motion"},{"key": "C","text": "Congenital hip dislocation exclusively"},{"key": "D","text": "Congenital clubfoot"}],"correct": "B","explanation": "Sprengel deformity is a congenital condition involving failure of normal scapular descent during development, resulting in an elevated, malpositioned scapula with associated limitation of shoulder motion."},{"id": 7814,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "Which of the following statements accurately reflects general management principles for many common pediatric positional foot/limb variations (e.g., mild metatarsus adductus, physiological bowing) that are flexible and non-progressive?","options": [{"key": "A","text": "No pediatric positional variations ever resolve without surgical intervention"},{"key": "B","text": "Physiotherapy has no role in monitoring or supporting families through the natural resolution process"},{"key": "C","text": "Many flexible, non-progressive positional variations resolve spontaneously with growth and may only require observation/monitoring rather than aggressive intervention"},{"key": "D","text": "All such variations require immediate aggressive surgical correction regardless of flexibility or progression"}],"correct": "C","explanation": "Many common pediatric positional variations that are flexible and show no progression tend to resolve spontaneously with normal growth and development, often requiring only appropriate observation and monitoring rather than aggressive intervention, with physiotherapy potentially supporting monitoring and parent education."},{"id": 7815,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Seddon's classification of peripheral nerve injury describes three categories in order of increasing severity as:","options": [{"key": "A","text": "Neurapraxia, Axonotmesis, Neurotmesis"},{"key": "B","text": "Neurotmesis, Neurapraxia, Axonotmesis"},{"key": "C","text": "Axonotmesis, Neurapraxia, Neurotmesis"},{"key": "D","text": "No classification system exists for nerve injury severity"}],"correct": "A","explanation": "Seddon's classification orders nerve injury severity as neurapraxia (mildest, conduction block), axonotmesis (axonal disruption with intact connective tissue), and neurotmesis (complete nerve disruption, most severe)."},{"id": 7816,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Neurapraxia is characterized by which underlying pathology and prognosis?","options": [{"key": "A","text": "A temporary conduction block without structural axonal disruption, typically with good, often rapid spontaneous recovery"},{"key": "B","text": "Complete Wallerian degeneration throughout the nerve"},{"key": "C","text": "Complete nerve transection with poor spontaneous recovery"},{"key": "D","text": "Permanent nerve damage requiring surgical repair in all cases"}],"correct": "A","explanation": "Neurapraxia involves a temporary physiological conduction block without significant structural axonal damage, generally associated with good and often relatively rapid spontaneous recovery."},{"id": 7817,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Hard","question": "Axonotmesis involves disruption of which structure while preserving which supportive framework?","options": [{"key": "A","text": "Disruption of the axon with preservation of the surrounding connective tissue (endoneurium), allowing potential for regeneration along the intact pathway"},{"key": "B","text": "No axonal disruption occurs, only myelin sheath damage"},{"key": "C","text": "Disruption only of the connective tissue with intact axons"},{"key": "D","text": "Complete disruption of both axon and all connective tissue layers"}],"correct": "A","explanation": "Axonotmesis involves disruption of the axon itself, but the surrounding connective tissue framework (endoneurial tubes) remains intact, providing a pathway to guide axonal regeneration, generally with reasonable prognosis though slower than neurapraxia."},{"id": 7818,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Neurotmesis represents the most severe nerve injury classification, involving:","options": [{"key": "A","text": "No structural damage at all"},{"key": "B","text": "Only temporary conduction block"},{"key": "C","text": "Spontaneous excellent recovery without any intervention"},{"key": "D","text": "Complete disruption of the axon and all supporting connective tissue structures, generally requiring surgical repair for meaningful recovery"}],"correct": "D","explanation": "Neurotmesis involves complete structural disruption of the nerve including axon and connective tissue layers, generally requiring surgical intervention (repair or grafting) for any meaningful functional recovery."},{"id": 7819,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Erb's palsy (upper brachial plexus injury) classically involves injury to which nerve roots?","options": [{"key": "A","text": "C8-T1"},{"key": "B","text": "C7 only"},{"key": "C","text": "C5-C6"},{"key": "D","text": "T1 exclusively"}],"correct": "C","explanation": "Erb's palsy results from injury to the upper brachial plexus roots, classically C5-C6, often from traction injury during difficult childbirth or trauma."},{"id": 7820,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Erb's palsy classically presents with which characteristic arm posture, sometimes described as the 'waiter's tip' position?","options": [{"key": "A","text": "Wrist flexed, forearm supinated, shoulder flexed"},{"key": "B","text": "Shoulder adducted and internally rotated, elbow extended, forearm pronated, wrist flexed"},{"key": "C","text": "Complete flaccid paralysis of the entire limb with no characteristic posture"},{"key": "D","text": "Isolated finger flexion deformity only"}],"correct": "B","explanation": "Erb's palsy classically presents with the characteristic 'waiter's tip' posture: shoulder adducted/internally rotated, elbow extended, forearm pronated, and wrist flexed, reflecting the pattern of muscle weakness from C5-C6 involvement."},{"id": 7821,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Klumpke's palsy (lower brachial plexus injury) classically involves injury to which nerve roots?","options": [{"key": "A","text": "Only the axillary nerve"},{"key": "B","text": "C5-C6"},{"key": "C","text": "C6-C7 only"},{"key": "D","text": "C8-T1"}],"correct": "D","explanation": "Klumpke's palsy results from injury to the lower brachial plexus roots, classically C8-T1, often associated with excessive arm abduction/traction during birth trauma or similar mechanisms."},{"id": 7822,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Hard","question": "Klumpke's palsy classically presents with which distinctive clinical finding, distinguishing it from Erb's palsy?","options": [{"key": "A","text": "Complete shoulder paralysis with normal hand function"},{"key": "B","text": "Isolated deltoid weakness with normal hand function"},{"key": "C","text": "No sensory changes of any kind"},{"key": "D","text": "Weakness/paralysis of intrinsic hand muscles, sometimes with an associated Horner's syndrome (due to sympathetic chain involvement)"}],"correct": "D","explanation": "Klumpke's palsy characteristically involves weakness of the intrinsic hand muscles due to C8-T1 involvement, and can be associated with Horner's syndrome (ptosis, miosis, anhidrosis) if the sympathetic chain is also affected."},{"id": 7823,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Easy","question": "Radial nerve palsy classically results in which functional deficit?","options": [{"key": "A","text": "Wrist drop due to loss of wrist and finger extension"},{"key": "B","text": "Complete loss of forearm pronation"},{"key": "C","text": "Loss of thumb opposition only"},{"key": "D","text": "Claw hand deformity"}],"correct": "A","explanation": "Radial nerve palsy causes wrist drop, resulting from paralysis of the wrist and finger extensor muscles innervated by this nerve."},{"id": 7824,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Which common site of injury is classically associated with radial nerve palsy, related to its anatomical course?","options": [{"key": "A","text": "Spiral (radial) groove of the humerus, e.g., with midshaft humeral fractures or prolonged compression ('Saturday night palsy')"},{"key": "B","text": "Tarsal tunnel"},{"key": "C","text": "Cubital tunnel"},{"key": "D","text": "Carpal tunnel"}],"correct": "A","explanation": "The radial nerve's course through the spiral groove of the humerus makes it particularly vulnerable to injury from midshaft humeral fractures or prolonged external compression, as classically seen in 'Saturday night palsy'."},{"id": 7825,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Median nerve palsy at the wrist (e.g., severe carpal tunnel syndrome) classically results in weakness of which muscle group, contributing to 'ape hand' deformity?","options": [{"key": "A","text": "Hypothenar muscles exclusively"},{"key": "B","text": "Wrist extensors"},{"key": "C","text": "Thenar muscles (particularly abductor pollicis brevis, opponens pollicis)"},{"key": "D","text": "Finger extensors"}],"correct": "C","explanation": "Median nerve palsy at the wrist classically weakens the thenar muscles, particularly affecting thumb abduction and opposition, contributing to the characteristic 'ape hand' appearance in severe/chronic cases."},{"id": 7826,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Ulnar nerve palsy classically results in 'claw hand' deformity, primarily due to weakness/paralysis of which muscle groups?","options": [{"key": "A","text": "Forearm pronators"},{"key": "B","text": "Intrinsic hand muscles (interossei and medial two lumbricals), leading to unopposed extensor/flexor action on the ring and little fingers"},{"key": "C","text": "Wrist flexors only"},{"key": "D","text": "Thenar muscles exclusively"}],"correct": "B","explanation": "Ulnar nerve palsy classically causes claw hand deformity due to paralysis of the intrinsic hand muscles (interossei and medial lumbricals), resulting in unopposed extensor action at the MCP joints and flexor action at the IP joints of the ring and little fingers."},{"id": 7827,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Easy","question": "Common peroneal nerve palsy classically results in which functional deficit?","options": [{"key": "A","text": "Loss of hip flexion"},{"key": "B","text": "Complete loss of knee extension"},{"key": "C","text": "Foot drop, due to loss of ankle dorsiflexion and eversion"},{"key": "D","text": "Wrist drop"}],"correct": "C","explanation": "Common peroneal nerve palsy causes foot drop due to paralysis of the ankle dorsiflexors (tibialis anterior) and evertors (peroneal muscles), commonly resulting in a steppage gait pattern."},{"id": 7828,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Which anatomical site is a common location for compression/injury of the common peroneal nerve, given its superficial course?","options": [{"key": "A","text": "Around the fibular neck, where the nerve is superficial and vulnerable to compression (e.g., prolonged leg crossing, tight casts)"},{"key": "B","text": "At the hip joint capsule"},{"key": "C","text": "Within the tarsal tunnel"},{"key": "D","text": "Deep within the gluteal muscles"}],"correct": "A","explanation": "The common peroneal nerve's superficial course around the fibular neck makes it particularly vulnerable to compression injury from external sources such as prolonged leg crossing, tight casts, or direct trauma at this site."},{"id": 7829,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Sciatic nerve injury, given its large contribution to lower limb innervation, can result in combined dysfunction of which nerve distributions distally?","options": [{"key": "A","text": "Only femoral nerve territory"},{"key": "B","text": "No functional deficit occurs with sciatic nerve injury"},{"key": "C","text": "Only obturator nerve territory"},{"key": "D","text": "Both tibial and common peroneal nerve territories, as the sciatic nerve gives rise to both distally"}],"correct": "D","explanation": "Since the sciatic nerve divides into the tibial and common peroneal nerves, injury proximal to this division can result in combined dysfunction affecting both nerve territories in the leg and foot."},{"id": 7830,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Femoral nerve palsy classically results in weakness of which key movement, given its innervation of the quadriceps?","options": [{"key": "A","text": "Toe flexion"},{"key": "B","text": "Ankle plantarflexion"},{"key": "C","text": "Knee extension, along with variable hip flexion weakness"},{"key": "D","text": "Hip abduction"}],"correct": "C","explanation": "Femoral nerve palsy classically causes significant knee extension weakness due to quadriceps paralysis, along with variable hip flexion weakness given its partial innervation of iliopsoas."},{"id": 7831,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Nerve conduction studies (NCS) and electromyography (EMG) are diagnostic tools used to assess peripheral nerve injuries by evaluating:","options": [{"key": "A","text": "Only bone density"},{"key": "B","text": "Electrical conduction properties of nerves and the electrical activity of muscles, helping localize and characterize nerve injury severity"},{"key": "C","text": "Cardiovascular function exclusively"},{"key": "D","text": "Only soft tissue swelling"}],"correct": "B","explanation": "NCS and EMG are electrodiagnostic tools that assess nerve conduction properties and muscle electrical activity respectively, valuable for localizing nerve lesions and characterizing injury severity/prognosis."},{"id": 7832,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Which physiotherapy intervention is important during the recovery phase following peripheral nerve injury to prevent joint contracture while awaiting nerve regeneration/reinnervation?","options": [{"key": "A","text": "Passive range of motion exercises and appropriate splinting to maintain joint mobility and prevent soft tissue shortening"},{"key": "B","text": "Complete immobilization of the affected limb indefinitely"},{"key": "C","text": "Aggressive resisted strengthening of paralyzed muscles immediately"},{"key": "D","text": "No intervention is needed until reinnervation is complete"}],"correct": "A","explanation": "Maintaining passive range of motion and using appropriate splinting is important during peripheral nerve injury recovery to prevent joint contracture and soft tissue shortening while awaiting potential nerve regeneration and muscle reinnervation."},{"id": 7833,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Hard","question": "Electrical stimulation is sometimes used in the management of denervated muscle following peripheral nerve injury with which theoretical aim, though evidence remains an area of ongoing discussion?","options": [{"key": "A","text": "To accelerate nerve regeneration directly"},{"key": "B","text": "To replace the need for any other rehabilitation intervention"},{"key": "C","text": "To help maintain muscle mass/reduce atrophy while awaiting reinnervation, though its specific role and evidence base continue to be studied"},{"key": "D","text": "To immediately restore full function without any nerve regeneration"}],"correct": "C","explanation": "Electrical stimulation of denervated muscle has been used with the aim of helping maintain muscle bulk and potentially supporting the muscle bed for eventual reinnervation, though its precise role and supporting evidence remain areas of ongoing clinical discussion and research."},{"id": 7834,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Sensory re-education techniques following peripheral nerve injury/repair aim to help patients:","options": [{"key": "A","text": "Increase pain sensitivity in the affected area intentionally"},{"key": "B","text": "Replace the need for any motor rehabilitation"},{"key": "C","text": "Relearn to interpret and adapt to altered sensory input as nerve regeneration progresses, improving functional sensory discrimination"},{"key": "D","text": "Avoid using the affected limb permanently"}],"correct": "C","explanation": "Sensory re-education programs help patients relearn to interpret and functionally utilize sensory information as it returns following nerve regeneration, which can be qualitatively altered from normal, aiming to improve functional sensory discrimination and use."},{"id": 7835,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Tinel's sign, when progressively advancing along the course of a recovering nerve over serial assessments, generally suggests:","options": [{"key": "A","text": "Worsening of the underlying nerve injury"},{"key": "B","text": "No nerve regeneration is occurring"},{"key": "C","text": "Complete failure of nerve recovery"},{"key": "D","text": "Progressive axonal regeneration advancing along the nerve, a generally favorable sign"}],"correct": "D","explanation": "A Tinel's sign that progressively advances distally along the nerve's course over sequential assessments generally indicates ongoing axonal regeneration, considered a favorable prognostic sign."},{"id": 7836,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Which factor generally influences the prognosis for functional recovery following peripheral nerve repair (e.g., after neurotmesis requiring surgical repair)?","options": [{"key": "A","text": "Multiple factors including injury severity/level, patient age, timing of repair, and distance to target muscles, among others"},{"key": "B","text": "Only the surgeon's preference, with no other relevant factors"},{"key": "C","text": "Time since injury has no bearing on outcome"},{"key": "D","text": "Complete recovery is guaranteed in all surgically repaired nerve injuries"}],"correct": "A","explanation": "Prognosis following nerve repair is influenced by multiple factors, including the severity and level of injury, patient age, timing of surgical repair, and the distance the regenerating axons must travel to reach target muscles, among other variables."},{"id": 7837,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Which functional splint is commonly used to support wrist/finger function and prevent contracture in a patient with radial nerve palsy (wrist drop)?","options": [{"key": "A","text": "Cervical collar"},{"key": "B","text": "Elbow extension splint"},{"key": "C","text": "Cock-up wrist splint, maintaining the wrist in an extended, functional position"},{"key": "D","text": "Ankle-foot orthosis"}],"correct": "C","explanation": "A cock-up wrist splint is commonly used in radial nerve palsy to support the wrist in a functional extended position, compensating for the loss of active wrist extension and helping prevent secondary joint/soft tissue contracture."},{"id": 7838,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Meralgia paresthetica involves entrapment of which sensory nerve, presenting with anterolateral thigh numbness/tingling?","options": [{"key": "A","text": "Lateral femoral cutaneous nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Femoral nerve"},{"key": "D","text": "Saphenous nerve"}],"correct": "A","explanation": "Meralgia paresthetica results from entrapment of the lateral femoral cutaneous nerve, typically near the inguinal ligament, presenting with characteristic anterolateral thigh sensory symptoms without motor involvement."},{"id": 7839,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Hard","question": "Which factor is a recognized contributing/risk factor for meralgia paresthetica?","options": [{"key": "A","text": "Only occurs following direct surgical nerve transection"},{"key": "B","text": "Regular stretching of the hip flexors"},{"key": "C","text": "Complete absence of any identifiable risk factors"},{"key": "D","text": "Tight clothing/belts, obesity, or pregnancy increasing pressure near the inguinal ligament"}],"correct": "D","explanation": "Factors that increase pressure or tension near the inguinal ligament, such as tight clothing/belts, obesity, and pregnancy, are recognized contributing factors to lateral femoral cutaneous nerve entrapment (meralgia paresthetica)."},{"id": 7840,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Which level of lower limb amputation is generally preferred when feasible, given its relative functional and energy expenditure advantages compared to a more proximal level?","options": [{"key": "A","text": "Hip disarticulation is always preferred regardless of other factors"},{"key": "B","text": "No difference in outcome exists between levels"},{"key": "C","text": "Transtibial (below-knee) amputation preserved over transfemoral (above-knee) when clinically feasible, due to better functional outcomes and lower energy expenditure"},{"key": "D","text": "Transfemoral over transtibial whenever possible"}],"correct": "C","explanation": "Preserving a more distal amputation level, such as transtibial rather than transfemoral, when clinically appropriate generally offers better functional outcomes and lower ambulation energy expenditure due to preserved knee joint function."},{"id": 7841,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Phantom limb sensation refers to:","options": [{"key": "A","text": "A psychological disorder unrelated to the amputation"},{"key": "B","text": "Actual physical pain originating from the residual limb tissue"},{"key": "C","text": "The perception that the amputated limb is still present, which can include sensory awareness without necessarily being painful"},{"key": "D","text": "Complete absence of any sensation in the residual limb"}],"correct": "C","explanation": "Phantom limb sensation describes the perception that the amputated body part is still present, which is a common experience following amputation and can occur with or without associated pain."},{"id": 7842,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Phantom limb pain differs from phantom limb sensation in that it specifically involves:","options": [{"key": "A","text": "Pain located only in the intact contralateral limb"},{"key": "B","text": "A condition that never occurs following amputation"},{"key": "C","text": "Painful sensations perceived as originating from the amputated limb"},{"key": "D","text": "No perception of the missing limb at all"}],"correct": "C","explanation": "Phantom limb pain specifically refers to painful sensations perceived as arising from the amputated limb, distinguishing it from the broader, not necessarily painful, phenomenon of phantom limb sensation."},{"id": 7843,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Which management approach has emerging evidence for phantom limb pain, using visual feedback to help 'trick' the brain regarding limb representation?","options": [{"key": "A","text": "Complete limb immobilization"},{"key": "B","text": "Avoiding any visual engagement with the residual limb"},{"key": "C","text": "Mirror therapy, using a mirror to create a visual illusion of the intact limb in place of the amputated limb"},{"key": "D","text": "Only pharmacological management, with no role for physical/visual therapies"}],"correct": "C","explanation": "Mirror therapy uses a mirror positioned to reflect the intact limb, creating a visual illusion that can help address phantom limb pain, thought to work through mechanisms related to cortical reorganization and visual-motor feedback."},{"id": 7844,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Residual limb shaping/shrinking following amputation is commonly achieved using which technique to prepare for optimal prosthetic fitting?","options": [{"key": "A","text": "No specific technique is needed, natural healing alone achieves adequate shaping"},{"key": "B","text": "Complete immobilization without any compression"},{"key": "C","text": "Compression bandaging or shrinker socks to control edema and shape the residual limb appropriately"},{"key": "D","text": "Only ice application with no compression component"}],"correct": "C","explanation": "Compression techniques, such as bandaging or shrinker socks, are commonly used following amputation to control post-surgical edema and appropriately shape the residual limb in preparation for optimal prosthetic socket fitting."},{"id": 7845,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Hard","question": "Which figure-of-eight bandaging technique consideration is important for a transfemoral (above-knee) amputation to help prevent a specific joint contracture?","options": [{"key": "A","text": "Only preventing knee flexion contracture, as there is no knee joint remaining at the transfemoral level"},{"key": "B","text": "Only relevant for upper limb amputations"},{"key": "C","text": "Preventing hip flexion and abduction contracture, given the tendency for these positions following surgery"},{"key": "D","text": "No specific joint contracture risk exists at this level"}],"correct": "C","explanation": "For transfemoral amputations, bandaging and positioning techniques aim to help prevent hip flexion and abduction contracture, which can develop from surgical positioning tendencies and muscle imbalances following surgery."},{"id": 7846,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Early post-amputation physiotherapy typically emphasizes which key components?","options": [{"key": "A","text": "Residual limb care/desensitization, contracture prevention, strengthening, and early mobility training"},{"key": "B","text": "Complete avoidance of any residual limb handling or desensitization"},{"key": "C","text": "Only passive rest with no active intervention"},{"key": "D","text": "Immediate return to unrestricted high-impact activity"}],"correct": "A","explanation": "Early post-amputation rehabilitation focuses on residual limb care and desensitization, preventing joint contractures, appropriate strengthening, and progressive mobility training in preparation for prosthetic fitting and use."},{"id": 7847,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Desensitization techniques for the residual limb following amputation aim to:","options": [{"key": "A","text": "Cause additional tissue damage intentionally"},{"key": "B","text": "Replace the need for any prosthetic fitting"},{"key": "C","text": "Gradually reduce hypersensitivity and improve tolerance to touch/pressure, important for comfortable prosthetic socket wear"},{"key": "D","text": "Increase hypersensitivity and pain"}],"correct": "C","explanation": "Desensitization techniques gradually expose the residual limb to various tactile stimuli, aiming to reduce hypersensitivity and improve tolerance, which is important for comfortable and functional prosthetic socket wear."},{"id": 7848,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "A prosthetic 'socket' refers to which component of a lower limb prosthesis?","options": [{"key": "A","text": "The custom-molded interface that connects the residual limb to the rest of the prosthesis"},{"key": "B","text": "The knee joint mechanism exclusively"},{"key": "C","text": "The foot component"},{"key": "D","text": "An external support cane"}],"correct": "A","explanation": "The socket is the custom-molded component that interfaces directly with the residual limb, forming the critical connection point between the patient and the rest of the prosthetic components."},{"id": 7849,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Hard","question": "Which type of prosthetic knee joint mechanism uses fluid resistance to help control swing phase, offering more adaptive gait characteristics compared to simpler mechanical designs?","options": [{"key": "A","text": "Single-axis mechanical knee only"},{"key": "B","text": "Only used in upper limb prosthetics"},{"key": "C","text": "Hydraulic or pneumatic knee units, providing variable resistance/damping through the gait cycle"},{"key": "D","text": "No knee mechanism ever varies resistance"}],"correct": "C","explanation": "Hydraulic or pneumatic knee units use fluid-based resistance mechanisms to provide variable damping through the gait cycle, generally offering more adaptive and natural gait characteristics compared to simpler mechanical single-axis designs."},{"id": 7850,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Hard","question": "Microprocessor-controlled prosthetic knees represent an advancement by using which technology to adjust resistance in real-time based on gait phase/conditions?","options": [{"key": "A","text": "Sensors and computerized control systems that continuously adjust knee resistance/damping based on real-time gait analysis"},{"key": "B","text": "No technological advancement over basic mechanical knees"},{"key": "C","text": "Manual adjustment required by the patient for every step"},{"key": "D","text": "Only available for upper limb prosthetics"}],"correct": "A","explanation": "Microprocessor-controlled knees incorporate sensors and computerized control systems that continuously analyze gait parameters and adjust resistance/damping characteristics in real-time, offering enhanced stability and adaptability compared to non-microprocessor designs."},{"id": 7851,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Energy-storing prosthetic feet (e.g., dynamic response/carbon fiber feet) are designed to:","options": [{"key": "A","text": "Increase energy expenditure during walking"},{"key": "B","text": "Store and return energy during the gait cycle, potentially improving efficiency and function, particularly for more active users"},{"key": "C","text": "Only be used for cosmetic purposes with no functional role"},{"key": "D","text": "Provide no functional benefit over simple SACH (solid ankle cushion heel) feet"}],"correct": "B","explanation": "Energy-storing/dynamic response prosthetic feet are designed with materials (often carbon fiber) that store energy during loading and release it during push-off, potentially improving gait efficiency and function, particularly benefiting more active prosthesis users."},{"id": 7852,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Gait training following lower limb amputation typically progresses through which general sequence?","options": [{"key": "A","text": "No specific progression, patients are expected to walk normally immediately upon prosthetic fitting"},{"key": "B","text": "Only wheelchair mobility training with no gait training component"},{"key": "C","text": "Parallel bars/assistive device use, progressing to less restrictive assistive devices as balance/confidence improve, working toward independent ambulation"},{"key": "D","text": "Immediate unsupervised community ambulation without any preliminary training"}],"correct": "C","explanation": "Gait training typically progresses from more supported environments (e.g., parallel bars) with appropriate assistive devices, gradually advancing to less restrictive devices as balance, confidence, and prosthetic control improve, working toward the most independent ambulation level appropriate for the individual."},{"id": 7853,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Hard","question": "Which specific gait deviation might be observed in a transtibial amputee if the prosthetic socket fit or alignment is suboptimal, related to excessive/inadequate socket flexion?","options": [{"key": "A","text": "Only affects upper limb swing, never lower limb gait pattern"},{"key": "B","text": "No gait deviations are ever related to socket fit or alignment"},{"key": "C","text": "Excessive knee flexion or hyperextension during stance, potentially related to socket alignment issues"},{"key": "D","text": "Complete inability to bear any weight regardless of alignment"}],"correct": "C","explanation": "Suboptimal prosthetic socket fit or alignment in transtibial amputees can contribute to gait deviations such as excessive knee flexion or hyperextension during stance phase, highlighting the importance of proper prosthetic alignment and fit assessment."},{"id": 7854,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Upper limb amputation prosthetic options generally include which broad categories?","options": [{"key": "A","text": "Body-powered, myoelectric, and cosmetic/passive prostheses, each with different functional and control characteristics"},{"key": "B","text": "Only cosmetic prostheses with no functional options available"},{"key": "C","text": "No prosthetic options exist for upper limb amputation"},{"key": "D","text": "Only myoelectric options exist for upper limb prosthetics"}],"correct": "A","explanation": "Upper limb prosthetic options broadly include body-powered (using cables/harness controlled by body movement), myoelectric (using electrical signals from residual muscles), and cosmetic/passive designs, each offering different functional capabilities and control mechanisms."},{"id": 7855,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Myoelectric prostheses function by which control mechanism?","options": [{"key": "A","text": "Purely passive, non-functional design"},{"key": "B","text": "Voice-activated control exclusively"},{"key": "C","text": "Detecting electrical signals (EMG) from residual limb muscles to control prosthetic movement"},{"key": "D","text": "Direct mechanical cable control from body movement"}],"correct": "C","explanation": "Myoelectric prostheses use surface electrodes to detect electromyographic (EMG) signals from residual limb muscles, using these signals to control prosthetic hand/arm movement."},{"id": 7856,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Which factor is important to consider in prosthetic prescription decision-making for an amputee, beyond simply the amputation level?","options": [{"key": "A","text": "Only the amputation level matters, with no other relevant patient factors"},{"key": "B","text": "Age is an absolute contraindication to any prosthetic fitting regardless of other factors"},{"key": "C","text": "Patient's functional goals, activity level, cognitive status, and overall health/comorbidities, in addition to amputation level"},{"key": "D","text": "Cosmetic appearance is the only relevant consideration"}],"correct": "C","explanation": "Prosthetic prescription should consider multiple patient factors beyond amputation level alone, including functional goals, activity level, cognitive status, and overall health, to select an appropriately matched prosthetic solution."},{"id": 7857,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Skin/residual limb complications that physiotherapists should monitor for in prosthesis users include which of the following?","options": [{"key": "A","text": "Only concerns related to the intact limb, never the residual limb"},{"key": "B","text": "Pressure areas, skin breakdown, and signs of poor prosthetic fit requiring adjustment"},{"key": "C","text": "Complications are exclusively addressed by prosthetists with no physiotherapy role"},{"key": "D","text": "No skin complications are ever relevant to monitor"}],"correct": "B","explanation": "Physiotherapists play an important role in monitoring for residual limb skin complications such as pressure areas or breakdown, which can indicate suboptimal prosthetic fit requiring adjustment by the prosthetist."},{"id": 7858,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Contralateral (intact) limb care is an important consideration in unilateral lower limb amputee rehabilitation primarily due to:","options": [{"key": "A","text": "Complete restriction of any activity on the intact limb"},{"key": "B","text": "No relevance, only the amputated side requires any attention"},{"key": "C","text": "The intact limb requires no different consideration compared to the general population"},{"key": "D","text": "Increased loading/stress on the intact limb during ambulation, potentially increasing risk of overuse injury or secondary complications over time"}],"correct": "D","explanation": "The intact contralateral limb bears increased loading and stress during ambulation in unilateral amputees, making its ongoing care and monitoring for overuse injury or other complications an important long-term rehabilitation consideration."},{"id": 7859,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Amputee energy expenditure during ambulation is generally increased compared to able-bodied walking, with which level of amputation typically associated with the greatest relative increase?","options": [{"key": "A","text": "Energy expenditure is identical regardless of amputation level"},{"key": "B","text": "Amputation never affects walking energy expenditure"},{"key": "C","text": "Transtibial amputation shows the greatest increase"},{"key": "D","text": "More proximal levels (e.g., transfemoral, hip disarticulation) are generally associated with progressively greater energy expenditure increases compared to more distal levels"}],"correct": "D","explanation": "Generally, more proximal amputation levels are associated with progressively greater increases in ambulation energy expenditure compared to able-bodied walking, reflecting the loss of more anatomical joints/structures contributing to normal gait efficiency."},{"id": 7860,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Which psychological consideration is important to address as part of comprehensive amputee rehabilitation, given the significant life adjustment involved?","options": [{"key": "A","text": "Only physical rehabilitation matters, with no psychosocial component to address"},{"key": "B","text": "Psychological factors are irrelevant to physical rehabilitation outcomes"},{"key": "C","text": "Amputation never has any psychological impact on patients"},{"key": "D","text": "Adjustment to body image changes, potential grief response, and overall psychosocial adaptation to living with limb loss"}],"correct": "D","explanation": "Comprehensive amputee rehabilitation should address important psychosocial factors including body image adjustment, potential grief responses related to limb loss, and overall psychological adaptation, recognizing the significant life impact of amputation beyond purely physical considerations."},{"id": 7861,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Vascular disease (e.g., peripheral arterial disease, diabetes-related complications) is a common indication for lower limb amputation in which patient population?","options": [{"key": "A","text": "Exclusively young trauma patients"},{"key": "B","text": "Older adults, often with significant comorbidities including diabetes and peripheral vascular disease"},{"key": "C","text": "Only pediatric patients with congenital limb differences"},{"key": "D","text": "Amputation is never related to vascular disease"}],"correct": "B","explanation": "Vascular disease, often in the context of diabetes and peripheral arterial disease, is a leading cause of lower limb amputation particularly in older adult populations with significant related comorbidities."},{"id": 7862,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Which rehabilitation consideration is particularly important for dysvascular amputees (amputation due to vascular disease), given their often more complex comorbidity profile compared to traumatic amputees?","options": [{"key": "A","text": "Identical, standardized rehabilitation protocol regardless of underlying cause or comorbidities"},{"key": "B","text": "Complete avoidance of any prosthetic fitting in dysvascular patients"},{"key": "C","text": "Careful monitoring of cardiovascular status, wound healing capacity, and often more conservative/graded functional progression given comorbidities"},{"key": "D","text": "No special considerations are needed compared to traumatic amputation rehabilitation"}],"correct": "C","explanation": "Dysvascular amputees often require careful consideration of cardiovascular status, wound healing capacity (given underlying vascular compromise), and typically a more conservative, individualized functional progression given their often more complex comorbidity profile compared to traumatic amputees."},{"id": 7863,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Hard","question": "Osseointegration, an alternative to traditional socket-based prosthetic attachment, involves:","options": [{"key": "A","text": "A type of prosthetic knee mechanism"},{"key": "B","text": "A specific type of residual limb bandaging technique"},{"key": "C","text": "Direct skeletal attachment of the prosthesis via a surgically implanted metal fixture integrated with bone"},{"key": "D","text": "A phantom limb pain treatment technique"}],"correct": "C","explanation": "Osseointegration is an alternative prosthetic attachment method involving direct skeletal fixation via a surgically implanted metal fixture that osseointegrates with bone, allowing direct prosthetic attachment without a traditional socket interface."},{"id": 7864,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Easy","question": "An ankle-foot orthosis (AFO) is commonly prescribed to manage which functional deficit?","options": [{"key": "A","text": "Isolated hip weakness with no ankle involvement"},{"key": "B","text": "Shoulder subluxation"},{"key": "C","text": "Wrist drop"},{"key": "D","text": "Foot drop and/or instability, providing support during the gait cycle"}],"correct": "D","explanation": "AFOs are commonly used to manage foot drop and ankle instability, providing support to control foot position during swing and/or stance phases of gait."},{"id": 7865,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "A solid (rigid) AFO design, compared to a hinged/articulated AFO, provides which functional characteristic?","options": [{"key": "A","text": "Fixed ankle position with no sagittal plane motion, providing maximal stability but less natural gait mechanics"},{"key": "B","text": "Free ankle motion in all planes"},{"key": "C","text": "Identical function to a hinged AFO in all respects"},{"key": "D","text": "Only used for upper limb conditions"}],"correct": "A","explanation": "A solid AFO fixes the ankle in a set position, providing maximal mediolateral and anteroposterior stability, though this comes at the cost of more natural sagittal plane ankle motion during gait compared to a hinged design."},{"id": 7866,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "A knee-ankle-foot orthosis (KAFO) is typically indicated when there is significant weakness/instability affecting which additional joint compared to an AFO alone?","options": [{"key": "A","text": "Exclusively for upper limb conditions"},{"key": "B","text": "Only the hip joint"},{"key": "C","text": "Only the shoulder joint"},{"key": "D","text": "The knee joint, requiring additional stability beyond what an AFO alone can provide"}],"correct": "D","explanation": "A KAFO extends orthotic control proximally to include the knee joint, indicated when significant knee instability or weakness exists in addition to any ankle/foot involvement, requiring more extensive support than an AFO alone provides."},{"id": 7867,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "A cock-up wrist splint is commonly used to manage which condition, maintaining the wrist in a functional extended position?","options": [{"key": "A","text": "Ankle instability"},{"key": "B","text": "Cervical spine instability"},{"key": "C","text": "Radial nerve palsy (wrist drop) or other conditions causing wrist extensor weakness"},{"key": "D","text": "Hip flexor tightness"}],"correct": "C","explanation": "A cock-up wrist splint supports the wrist in a functional extended position, commonly used in conditions like radial nerve palsy where wrist extensor weakness would otherwise result in a non-functional flexed wrist posture."},{"id": 7868,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "A four-point cane provides which advantage over a standard single-point cane, particularly relevant for patients with significant balance deficits?","options": [{"key": "A","text": "Identical stability to a single-point cane in all situations"},{"key": "B","text": "Only used for upper limb rehabilitation, unrelated to gait"},{"key": "C","text": "A wider base of support, offering increased stability, though often at the cost of being bulkier and slower to advance"},{"key": "D","text": "Reduced base of support compared to a single-point cane"}],"correct": "C","explanation": "A four-point (quad) cane provides a wider base of support compared to a standard single-point cane, offering increased stability for patients with more significant balance deficits, though it can be bulkier and slightly slower to maneuver during gait."},{"id": 7869,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "Which assistive device generally provides the greatest degree of stability/support for a patient with significant lower limb weakness or bilateral involvement, compared to canes or single crutches?","options": [{"key": "A","text": "Forearm crutches always provide more stability than a walker"},{"key": "B","text": "No assistive device provides more stability than a cane"},{"key": "C","text": "Single-point cane"},{"key": "D","text": "Standard (pick-up) walker or wheeled walker, offering a wide base of support and bilateral upper limb weight-bearing capability"}],"correct": "D","explanation": "A standard walker (pick-up or wheeled) generally offers the greatest stability among common assistive devices, providing a wide base of support and allowing bilateral upper limb weight-bearing, appropriate for patients with more significant balance or bilateral lower limb involvement."},{"id": 7870,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "When fitting a standard cane for a patient, the handle height is typically adjusted to align with which anatomical landmark, with the elbow in slight flexion?","options": [{"key": "A","text": "Knee joint level"},{"key": "B","text": "Shoulder level"},{"key": "C","text": "Ankle level"},{"key": "D","text": "Greater trochanter/wrist crease level, with approximately 15-30 degrees of elbow flexion"}],"correct": "D","explanation": "Standard cane height is typically fitted so the handle aligns approximately with the greater trochanter or wrist crease when standing, allowing approximately 15-30 degrees of elbow flexion for optimal function and stability."},{"id": 7871,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "A cane is generally held in which hand relative to the affected/weaker lower limb to optimize gait mechanics and reduce joint loading?","options": [{"key": "A","text": "In the hand opposite (contralateral) to the affected/weaker limb, mimicking normal reciprocal arm-leg gait pattern and reducing joint loading on the affected side"},{"key": "B","text": "It makes no difference which hand is used"},{"key": "C","text": "Always in the dominant hand regardless of which limb is affected"},{"key": "D","text": "In the same hand as the affected/weaker limb"}],"correct": "A","explanation": "A cane is typically held in the hand contralateral to the affected/weaker limb, which mimics the normal reciprocal gait pattern and has been shown to help reduce joint loading forces on the affected side during stance."},{"id": 7872,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "A lumbosacral orthosis (LSO) is commonly used following which type of injury/condition to provide external spinal support?","options": [{"key": "A","text": "Isolated ankle sprain"},{"key": "B","text": "Lumbar spine fracture (e.g., stable compression fracture) or post-surgical spinal stabilization needs, as prescribed"},{"key": "C","text": "Shoulder dislocation"},{"key": "D","text": "Wrist fracture exclusively"}],"correct": "B","explanation": "Lumbosacral orthoses are commonly used to provide external support and limit motion following conditions such as stable lumbar compression fractures or as part of post-surgical spinal stabilization protocols, as appropriately prescribed."},{"id": 7873,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "Which functional benefit is generally provided by a properly fitted knee brace (e.g., functional ACL brace) for a patient with ligamentous knee instability?","options": [{"key": "A","text": "No functional benefit whatsoever in any clinical scenario"},{"key": "B","text": "Additional mechanical support/proprioceptive feedback that may help reduce excessive joint translation and provide functional confidence, used as an adjunct rather than a replacement for comprehensive rehabilitation"},{"key": "C","text": "Complete elimination of any need for muscular strengthening or rehabilitation"},{"key": "D","text": "Guaranteed prevention of all future injury regardless of other rehabilitation factors"}],"correct": "B","explanation": "Functional knee braces may provide additional mechanical support and proprioceptive feedback that can help reduce excessive joint translation and support functional confidence, generally used as an adjunct to, rather than a replacement for, comprehensive strength and neuromuscular rehabilitation."},{"id": 7874,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "Crutch fitting for axillary crutches typically ensures which gap distance between the top of the crutch and the axilla to avoid nerve compression?","options": [{"key": "A","text": "A gap of at least 12 inches"},{"key": "B","text": "Crutches should never contact the axilla region under any fitting, making this measurement irrelevant"},{"key": "C","text": "Approximately 2-3 finger widths (or 2 inches/5cm) gap, to avoid pressure on the axillary/radial nerve region"},{"key": "D","text": "No gap at all, direct contact is recommended"}],"correct": "C","explanation": "Proper axillary crutch fitting maintains a gap of approximately 2-3 finger widths (or about 2 inches) between the top of the crutch and the axilla, helping avoid excessive pressure on neurovascular structures in this region during use."},{"id": 7875,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Hard","question": "Improper axillary crutch use/fitting, with excessive pressure in the axilla, can potentially cause injury to which nerve, resulting in a recognizable clinical presentation sometimes called 'crutch palsy'?","options": [{"key": "A","text": "Sciatic nerve"},{"key": "B","text": "Common peroneal nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Radial nerve (compression against the humerus in the axillary region)"}],"correct": "D","explanation": "Excessive or prolonged pressure in the axilla from improperly fitted/used axillary crutches can compress the radial nerve against the humerus, potentially resulting in a compressive neuropathy sometimes termed 'crutch palsy'."},{"id": 7876,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "Forearm (Lofstrand) crutches, compared to axillary crutches, offer which functional advantage for appropriate patients with adequate upper limb strength/balance?","options": [{"key": "A","text": "Reduced bulk and often preferred for longer-term or more independent ambulatory users with adequate trunk/upper limb control, without axillary pressure concerns"},{"key": "B","text": "Identical function and fitting considerations as axillary crutches in every respect"},{"key": "C","text": "Greater overall stability for patients with severe balance deficits"},{"key": "D","text": "Only appropriate for upper limb injuries, never for lower limb conditions"}],"correct": "A","explanation": "Forearm crutches are generally less bulky and often preferred for patients with adequate upper limb strength and trunk control for longer-term or more independent ambulation, without the axillary pressure concerns associated with axillary crutch use."},{"id": 7877,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Hard","question": "A functional/dynamic wrist-hand orthosis for a patient with median nerve palsy might be designed to substitute for which lost function?","options": [{"key": "A","text": "Elbow flexion"},{"key": "B","text": "Thumb opposition/abduction function, compensating for thenar muscle weakness"},{"key": "C","text": "Wrist extension only, with no thumb component needed"},{"key": "D","text": "Ankle dorsiflexion"}],"correct": "B","explanation": "A functional orthosis for median nerve palsy may be designed to help substitute for lost thenar muscle function, particularly supporting thumb opposition/abduction to maintain functional grasp/pinch capability."},{"id": 7878,"subject": "Musculoskeletal Physiotherapy","topic": "Orthotics & Assistive Devices","difficulty": "Medium","question": "When progressing a patient from a walker to a cane, which functional/clinical criteria should generally guide this progression decision?","options": [{"key": "A","text": "Patient preference alone, without any clinical assessment of readiness"},{"key": "B","text": "No specific criteria are needed, progression should occur automatically after a fixed time period"},{"key": "C","text": "Time since injury alone, regardless of demonstrated functional capacity"},{"key": "D","text": "Demonstrated adequate strength, balance, and safety with the less supportive device during supervised assessment/practice"}],"correct": "D","explanation": "Progression to a less supportive assistive device should be guided by demonstrated adequate strength, balance, and safety during supervised practice, rather than based solely on time elapsed or patient preference without clinical assessment."},{"id": 7879,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "The general phases of sports injury rehabilitation typically progress through which sequence?","options": [{"key": "A","text": "Only acute management with no further structured progression"},{"key": "B","text": "Acute management, restoration of motion/strength, sport-specific training, and graded return to sport"},{"key": "C","text": "Return to sport, then acute management, then strengthening"},{"key": "D","text": "Immediate full-intensity training regardless of injury phase"}],"correct": "B","explanation": "Sports injury rehabilitation typically follows a structured progression from acute injury management through restoration of motion and strength, sport-specific functional training, and finally a graded return to sport."},{"id": 7880,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Which principle describes the gradual, progressive increase in training load to allow tissue adaptation while minimizing injury risk?","options": [{"key": "A","text": "Complete avoidance of any loading until full pain resolution"},{"key": "B","text": "Random, non-systematic loading with no progression logic"},{"key": "C","text": "The principle of progressive overload/graded exposure, respecting tissue healing timelines and individual response"},{"key": "D","text": "Immediate maximal loading regardless of tissue tolerance"}],"correct": "C","explanation": "Progressive overload, applying gradually increasing loads that respect tissue healing timelines and individual response, is a fundamental principle in safely progressing sports rehabilitation."},{"id": 7881,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Hard","question": "The acute:chronic workload ratio is a concept used in sports injury prevention to help monitor:","options": [{"key": "A","text": "Only total training volume with no time-based comparison"},{"key": "B","text": "The relationship between recent (acute) training load and longer-term (chronic) training load, with rapid spikes associated with increased injury risk"},{"key": "C","text": "Cardiovascular fitness exclusively, unrelated to injury risk"},{"key": "D","text": "Only relevant to upper limb sports"}],"correct": "B","explanation": "The acute:chronic workload ratio compares recent training load to a longer-term rolling average, with research suggesting that rapid spikes in acute load relative to chronic load are associated with increased injury risk."},{"id": 7882,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Return-to-sport decision-making following significant injury (e.g., ACL reconstruction) increasingly incorporates which multi-factorial approach, beyond simple time-based criteria?","options": [{"key": "A","text": "Return to sport decisions should never involve any physiotherapy input"},{"key": "B","text": "Patient's own subjective feeling alone, without any objective assessment"},{"key": "C","text": "A combination of objective functional/strength testing, psychological readiness assessment, and clinical judgment"},{"key": "D","text": "Time since surgery alone as the sole criterion"}],"correct": "C","explanation": "Contemporary return-to-sport decision-making incorporates a multi-factorial approach including objective functional and strength testing, psychological readiness (e.g., using validated questionnaires), and overall clinical judgment, moving beyond simple time-based criteria alone."},{"id": 7883,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Which psychological factor has been identified as important in successful return to sport following significant injury, sometimes assessed using tools like the ACL-RSI scale?","options": [{"key": "A","text": "Only physical readiness matters, with no psychological component relevant"},{"key": "B","text": "Psychological readiness/confidence, including addressing fear of reinjury, which can significantly influence successful return to sport outcomes"},{"key": "C","text": "Psychological factors are only relevant for elite athletes, not recreational participants"},{"key": "D","text": "Complete absence of any psychological consideration is appropriate"}],"correct": "B","explanation": "Psychological readiness, including confidence and addressing fear of reinjury, has been identified as an important factor influencing successful return to sport, with tools like the ACL Return to Sport after Injury (ACL-RSI) scale used to help assess this readiness."},{"id": 7884,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Sport-specific functional testing (e.g., hop tests, agility drills) in later-stage rehabilitation aims to:","options": [{"key": "A","text": "Assess functional capacity and movement quality under conditions that more closely simulate actual sport demands, informing return-to-sport readiness"},{"key": "B","text": "Have no relevance to return-to-sport decision-making"},{"key": "C","text": "Only assess isolated joint range of motion"},{"key": "D","text": "Replace the need for any strength assessment"}],"correct": "A","explanation": "Sport-specific functional testing assesses functional capacity and movement quality under conditions simulating actual sport demands, providing valuable information to inform return-to-sport readiness decisions beyond basic strength or ROM measures alone."},{"id": 7885,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Which of the following describes an appropriate approach to injury prevention programming for team sports, incorporating evidence-based multi-component elements?","options": [{"key": "A","text": "Multi-component programs incorporating strength, balance/proprioception, plyometrics, and movement technique training, implemented consistently as part of regular training"},{"key": "B","text": "Only static stretching before competition, with no other components"},{"key": "C","text": "Injury prevention programs have no evidence supporting their use, so should be omitted"},{"key": "D","text": "Only relevant for elite/professional athletes, with no application to recreational sport"}],"correct": "A","explanation": "Effective injury prevention programs for team sports incorporate multiple evidence-based components including strength, balance, plyometric, and movement technique training, implemented consistently as part of regular training routine rather than as an occasional or isolated intervention."},{"id": 7886,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Concussion in sport is defined as:","options": [{"key": "A","text": "A condition that only affects contact sport athletes"},{"key": "B","text": "A functional disturbance of brain function following biomechanical trauma, typically without structural abnormality on standard neuroimaging"},{"key": "C","text": "Always associated with loss of consciousness"},{"key": "D","text": "A structural brain injury visible on standard CT/MRI imaging in all cases"}],"correct": "B","explanation": "Sport-related concussion is generally defined as a functional disturbance of brain function resulting from biomechanical forces, typically without structural abnormality visible on standard neuroimaging, and does not require loss of consciousness for diagnosis."},{"id": 7887,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Current concussion management guidelines generally emphasize which initial approach following diagnosis?","options": [{"key": "A","text": "Immediate return to full sport participation without restriction"},{"key": "B","text": "Complete indefinite avoidance of any physical or cognitive activity"},{"key": "C","text": "No specific management approach is recommended, management is purely individualized with no general guidelines"},{"key": "D","text": "A brief period of relative rest followed by a gradual, symptom-guided return to activity protocol"}],"correct": "D","explanation": "Current concussion management guidelines generally recommend a brief initial period of relative rest, followed by a gradual, symptom-guided stepwise return to both cognitive and physical activity, rather than prolonged strict rest or immediate full return."},{"id": 7888,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "The graduated return-to-sport protocol following concussion typically progresses through stages beginning with light aerobic activity, and requires which condition to progress between stages?","options": [{"key": "A","text": "Progression occurs automatically after a fixed 24-hour period regardless of symptoms"},{"key": "B","text": "The athlete should be asymptomatic (or at their symptom baseline) at the current stage before progressing to the next, more demanding stage"},{"key": "C","text": "Athletes should push through worsening symptoms to progress faster"},{"key": "D","text": "No symptom monitoring is required during return-to-sport progression"}],"correct": "B","explanation": "Graduated return-to-sport protocols following concussion typically require the athlete to remain asymptomatic (or at baseline) at each stage for a period before progressing to the next, more demanding stage, with any symptom recurrence prompting a return to the previous tolerated stage."},{"id": 7889,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Overtraining syndrome in athletes is characterized by which general presentation, resulting from an imbalance between training load and recovery?","options": [{"key": "A","text": "Persistent fatigue, declining performance, and other symptoms (mood changes, sleep disturbance) despite continued or increased training, reflecting inadequate recovery relative to training stress"},{"key": "B","text": "Only affects untrained/sedentary individuals"},{"key": "C","text": "No identifiable symptoms, purely a theoretical concept with no clinical relevance"},{"key": "D","text": "Improved performance with increased training load in all cases"}],"correct": "A","explanation": "Overtraining syndrome results from a chronic imbalance between training stress and recovery, presenting with persistent fatigue, declining performance despite continued/increased training effort, and often associated symptoms such as mood disturbance and sleep problems."},{"id": 7890,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Which factor is important in periodization of athletic training programs, aiming to systematically vary training variables over time?","options": [{"key": "A","text": "Maintaining identical, unvarying training load throughout an entire season"},{"key": "B","text": "Systematically varying training volume, intensity, and focus across different training phases to optimize performance while managing fatigue/injury risk"},{"key": "C","text": "Only applies to strength training, with no relevance to other training modalities"},{"key": "D","text": "Periodization has no relevance to injury prevention or performance"}],"correct": "B","explanation": "Periodization involves the systematic variation of training variables (volume, intensity, focus) across different phases of a training cycle, aiming to optimize performance development while appropriately managing fatigue accumulation and injury risk."},{"id": 7891,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Hard","question": "Sudden cardiac events in young athletes, though rare, are an important consideration in sports medicine; which screening approach is commonly recommended to help identify at-risk individuals?","options": [{"key": "A","text": "Only screening for musculoskeletal injuries is relevant, with no cardiovascular consideration needed"},{"key": "B","text": "No screening is ever recommended for young athletes"},{"key": "C","text": "Screening is only relevant for athletes over age 50"},{"key": "D","text": "Pre-participation cardiovascular screening, including history and physical examination, with additional testing (e.g., ECG) considered in some settings/populations"}],"correct": "D","explanation": "Pre-participation cardiovascular screening, including a thorough history and physical examination (with additional testing like ECG considered in certain settings or higher-risk populations), is recommended to help identify young athletes at risk for rare but serious cardiac events."},{"id": 7892,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Hard","question": "Exercise-associated muscle cramps in athletes have traditionally been attributed to dehydration/electrolyte imbalance, though current understanding also recognizes which additional contributing mechanism?","options": [{"key": "A","text": "Only relates to ambient temperature, with no other contributing factors"},{"key": "B","text": "Altered neuromuscular control, potentially related to fatigue affecting the balance between excitatory and inhibitory neural input to muscle"},{"key": "C","text": "No alternative mechanisms are recognized, dehydration is the only accepted cause"},{"key": "D","text": "Muscle cramps have no relationship to exercise or fatigue whatsoever"}],"correct": "B","explanation": "While dehydration/electrolyte factors have traditionally been implicated, current understanding also recognizes a neuromuscular fatigue-related mechanism, involving altered balance between excitatory and inhibitory neural control of muscle, as a contributing factor to exercise-associated muscle cramping."},{"id": 7893,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Hard","question": "Female athletes are at increased risk for a condition sometimes referred to as the 'Female Athlete Triad' or more broadly RED-S (Relative Energy Deficiency in Sport), which involves the interrelationship between which factors?","options": [{"key": "A","text": "Low energy availability, menstrual dysfunction, and impaired bone health, which can interrelate and negatively impact both health and performance"},{"key": "B","text": "This condition exclusively affects male athletes"},{"key": "C","text": "Cardiovascular fitness exclusively"},{"key": "D","text": "Only muscle strength and flexibility, unrelated to nutrition or menstrual function"}],"correct": "A","explanation": "The Female Athlete Triad (or the broader RED-S concept) describes the interrelationship between low energy availability, menstrual dysfunction, and impaired bone health, which can negatively impact both long-term health and athletic performance if not appropriately identified and managed."},{"id": 7894,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Which of the following best describes appropriate physiotherapy screening/education regarding RED-S/Female Athlete Triad in at-risk athlete populations?","options": [{"key": "A","text": "Ignoring any signs or symptoms suggestive of this condition"},{"key": "B","text": "This topic has no relevance to physiotherapy practice"},{"key": "C","text": "Being aware of risk factors and warning signs, and appropriately referring for further multidisciplinary evaluation/management when concerns are identified"},{"key": "D","text": "Providing specific dietary prescriptions independently without referral to appropriate nutrition/medical specialists"}],"correct": "C","explanation": "Physiotherapists should maintain awareness of risk factors and warning signs for RED-S/Female Athlete Triad and appropriately refer for further multidisciplinary evaluation and management (e.g., sports medicine physician, dietitian) when concerns are identified, recognizing the limits of their scope in managing the nutritional/medical aspects independently."},{"id": 7895,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Heat-related illness in athletes exists on a spectrum; which condition represents the most severe, life-threatening presentation requiring immediate emergency management?","options": [{"key": "A","text": "Heat cramps"},{"key": "B","text": "Heat exhaustion"},{"key": "C","text": "Mild dehydration with no other symptoms"},{"key": "D","text": "Exertional heat stroke, characterized by significantly elevated core body temperature and central nervous system dysfunction"}],"correct": "D","explanation": "Exertional heat stroke represents the most severe end of the heat illness spectrum, characterized by significantly elevated core body temperature along with central nervous system dysfunction, requiring immediate aggressive cooling and emergency medical management."},{"id": 7896,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Hard","question": "Which immediate management step is considered critical in suspected exertional heat stroke, given the strong correlation between cooling speed and outcome?","options": [{"key": "A","text": "Providing only oral fluids with no other intervention"},{"key": "B","text": "Delaying cooling until arrival at a hospital setting"},{"key": "C","text": "Avoiding any cooling measures until core temperature is formally confirmed with specialized equipment"},{"key": "D","text": "Rapid, aggressive cooling (e.g., cold water immersion) initiated as quickly as possible on-site"}],"correct": "D","explanation": "Rapid, aggressive cooling, ideally through methods like cold water immersion, initiated as quickly as possible at the site of collapse, is considered critical in exertional heat stroke management given the strong correlation between time to effective cooling and patient outcomes."},{"id": 7897,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "Which principle underlies the use of a structured warm-up protocol prior to sports participation, beyond simply increasing muscle temperature?","options": [{"key": "A","text": "Warm-ups should always be passive, involving no active movement"},{"key": "B","text": "Only relevant for endurance sports, with no application to team/field sports"},{"key": "C","text": "Preparing the neuromuscular system, potentially improving movement patterns/activation, alongside physiological benefits like increased tissue temperature and blood flow"},{"key": "D","text": "Warm-ups have no evidence-based benefit and should be omitted to save training time"}],"correct": "C","explanation": "Structured warm-up protocols aim not only to increase tissue temperature and blood flow but also to prepare the neuromuscular system, potentially improving movement patterns and muscle activation in preparation for sport-specific demands, contributing to both performance and injury risk reduction goals."},{"id": 7898,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Hard","question": "Which of the following best reflects current understanding regarding the relationship between static stretching immediately before explosive/power-based athletic activity and performance?","options": [{"key": "A","text": "Static stretching should never be included in any athlete's training program at any time"},{"key": "B","text": "Some evidence suggests that prolonged static stretching immediately prior to power/explosive activity may have a transient negative effect on subsequent performance, leading many programs to favor dynamic warm-up approaches in this context"},{"key": "C","text": "Static stretching immediately before power-based activity consistently and significantly improves performance with no downside"},{"key": "D","text": "Static stretching has no relevance to any pre-competition warm-up considerations"}],"correct": "B","explanation": "Evidence suggests that prolonged static stretching performed immediately before power/explosive activities may have a transient negative effect on subsequent performance, contributing to the common practice of favoring dynamic warm-up approaches immediately pre-competition, while static stretching may still have value at other points in a training program."},{"id": 7899,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Postural kyphosis, as opposed to structural kyphosis (e.g., Scheuermann's disease), is generally characterized by which distinguishing feature?","options": [{"key": "A","text": "Identical presentation and prognosis to structural kyphosis in all respects"},{"key": "B","text": "Always associated with vertebral wedging on imaging"},{"key": "C","text": "A flexible curve that can be actively or passively corrected, without fixed structural vertebral changes"},{"key": "D","text": "Fixed, non-correctable curve regardless of position change"}],"correct": "C","explanation": "Postural kyphosis is characterized by a flexible curve that can be actively or passively corrected (e.g., with active extension or lying supine), distinguishing it from structural kyphosis which involves fixed vertebral changes that don't fully correct."},{"id": 7900,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Management of postural (non-structural) kyphosis typically emphasizes which approach, given its flexible nature?","options": [{"key": "A","text": "No intervention is ever appropriate or beneficial"},{"key": "B","text": "Postural awareness training, strengthening of postural extensor muscles, and flexibility work addressing contributing muscle imbalances"},{"key": "C","text": "Rigid bracing as the primary and only intervention"},{"key": "D","text": "Surgical correction as first-line management"}],"correct": "B","explanation": "Postural kyphosis management typically emphasizes an active exercise-based approach including postural awareness training, strengthening of relevant postural muscles, and addressing flexibility imbalances that may contribute to the postural pattern."},{"id": 7901,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Excessive lumbar lordosis (hyperlordosis) is commonly associated with which combination of muscle imbalances?","options": [{"key": "A","text": "Weak hip flexors and strong abdominals"},{"key": "B","text": "No consistent muscle imbalance pattern is associated with this postural presentation"},{"key": "C","text": "Only related to leg length discrepancy, with no muscular component"},{"key": "D","text": "Tight hip flexors and lumbar erector spinae, combined with weak abdominal and gluteal muscles"}],"correct": "D","explanation": "Hyperlordotic posture is commonly associated with a pattern of tight hip flexors and lumbar erector spinae combined with relative weakness of the abdominal and gluteal muscles, contributing to anterior pelvic tilt and increased lumbar curve."},{"id": 7902,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Which exercise approach is commonly incorporated when addressing postural hyperlordosis related to the muscle imbalance pattern described?","options": [{"key": "A","text": "Exclusively passive modalities with no active exercise component"},{"key": "B","text": "A combination of stretching tight hip flexors/lumbar extensors and strengthening weak abdominal/gluteal muscles"},{"key": "C","text": "Only strengthening the hip flexors and lumbar extensors further"},{"key": "D","text": "Complete avoidance of any exercise intervention"}],"correct": "B","explanation": "Addressing postural hyperlordosis typically involves a combined approach of stretching the tight hip flexor/lumbar extensor muscles while strengthening the relatively weak abdominal and gluteal muscle groups, aiming to help correct the underlying imbalance pattern."},{"id": 7903,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Functional (non-structural) scoliosis, as distinguished from structural scoliosis, is generally characterized by which feature?","options": [{"key": "A","text": "A curve that resolves or significantly improves with a change in position (e.g., forward bending, addressing an underlying cause like leg length discrepancy), without fixed vertebral rotation"},{"key": "B","text": "Always requires surgical intervention regardless of severity"},{"key": "C","text": "A fixed vertebral rotation that persists in all positions"},{"key": "D","text": "Identical prognosis and management to structural (e.g., idiopathic) scoliosis"}],"correct": "A","explanation": "Functional scoliosis is characterized by a curve that resolves or significantly improves with position changes (such as forward bending) or by addressing an underlying contributing cause (e.g., correcting a leg length discrepancy), without the fixed vertebral rotation seen in structural scoliosis."},{"id": 7904,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Which of the following can be a contributing cause of functional (non-structural) scoliosis?","options": [{"key": "A","text": "Leg length discrepancy or muscle spasm/pain-related postural adaptation"},{"key": "B","text": "Structural vertebral anomalies present since birth"},{"key": "C","text": "Functional scoliosis has no recognized contributing causes"},{"key": "D","text": "Only idiopathic factors with no identifiable cause"}],"correct": "A","explanation": "Leg length discrepancy and muscle spasm or pain-related postural adaptations are recognized potential contributing causes of functional (non-structural) scoliosis, distinct from the different pathophysiology underlying structural scoliosis."},{"id": 7905,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Pes planus (flatfoot) as a postural finding may contribute to altered lower limb kinetic chain mechanics, potentially influencing more proximal structures through which mechanism?","options": [{"key": "A","text": "Exclusively affects upper limb function"},{"key": "B","text": "Excessive foot pronation potentially contributing to increased internal tibial and femoral rotation, influencing knee and hip mechanics up the kinetic chain"},{"key": "C","text": "Only affects local foot structures, with no proximal kinetic chain influence"},{"key": "D","text": "No relationship exists between foot posture and proximal joint mechanics"}],"correct": "B","explanation": "Excessive foot pronation associated with pes planus can contribute to increased internal rotation forces transmitted up the kinetic chain, potentially influencing knee and hip mechanics, illustrating the interconnected nature of postural and biomechanical factors across the lower limb."},{"id": 7906,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Forward head posture is commonly associated with which pattern of muscle imbalance in the cervical/upper thoracic region?","options": [{"key": "A","text": "Only affects lumbar spine muscles, with no cervical involvement"},{"key": "B","text": "Weak upper trapezius and levator scapulae with strong deep neck flexors"},{"key": "C","text": "Tight/overactive upper trapezius, levator scapulae, and suboccipital muscles, combined with weak/lengthened deep neck flexors"},{"key": "D","text": "No muscle imbalance is associated with this postural pattern"}],"correct": "C","explanation": "Forward head posture is commonly associated with tightness/overactivity of muscles like upper trapezius, levator scapulae, and suboccipitals, combined with weakness of the deep cervical flexor muscles, contributing to the characteristic postural pattern."},{"id": 7907,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Which postural assessment tool/method is commonly used to objectively document and monitor postural alignment over time in clinical practice?","options": [{"key": "A","text": "Only radiographic imaging can assess posture, with no clinical assessment methods available"},{"key": "B","text": "Plumb line assessment, postural grids, or photographic documentation with standardized landmarks"},{"key": "C","text": "Postural assessment cannot be objectively documented in any way"},{"key": "D","text": "Only subjective visual assessment with no documentation method available"}],"correct": "B","explanation": "Various methods including plumb line assessment, postural grids, and standardized photographic documentation are commonly used in clinical practice to objectively assess and monitor postural alignment over time."},{"id": 7908,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Genu recurvatum (knee hyperextension) as a postural finding may be associated with which underlying factor in some individuals?","options": [{"key": "A","text": "Genu recurvatum has no recognized association with any postural or biomechanical factors"},{"key": "B","text": "Exclusively related to footwear choice, with no other contributing factors"},{"key": "C","text": "Only occurs in the context of acute traumatic injury, never as a postural pattern"},{"key": "D","text": "General ligamentous laxity or compensatory patterns related to proximal or distal muscle weakness"}],"correct": "D","explanation": "Genu recurvatum can be associated with general ligamentous laxity in some individuals, or may develop as a compensatory postural pattern related to proximal (e.g., quadriceps) or distal muscle weakness, among other potential contributing factors."},{"id": 7909,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Hard","question": "Upper crossed syndrome, a postural pattern described by Janda, involves a 'crossing' pattern of tightness and weakness across which regions?","options": [{"key": "A","text": "No specific muscle pattern is implied by this terminology"},{"key": "B","text": "Only affects the lower limb, unrelated to upper body posture"},{"key": "C","text": "Identical muscle pattern to lower crossed syndrome, just located in a different body region with no distinct pattern"},{"key": "D","text": "Tight upper trapezius/levator scapulae crossing with tight pectoralis muscles, combined with weak deep neck flexors crossing with weak lower trapezius/serratus anterior"}],"correct": "D","explanation": "Upper crossed syndrome describes a characteristic crossing pattern involving tight upper trapezius/levator scapulae and tight pectoral muscles, combined with weak deep neck flexors and weak lower trapezius/serratus anterior, contributing to the associated forward head, rounded shoulder postural presentation."},{"id": 7910,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Postural correction exercise programs generally show most benefit when combined with which additional educational component for sustained change?","options": [{"key": "A","text": "No additional component is needed, exercise alone is always sufficient for lasting postural change"},{"key": "B","text": "Postural correction exercises have no evidence of benefit under any circumstances"},{"key": "C","text": "Ergonomic/behavioral education addressing sustained postures during daily activities (e.g., workstation setup, movement habits), supporting carryover beyond the exercise session itself"},{"key": "D","text": "Complete avoidance of any daily activity modification, relying exclusively on exercise"}],"correct": "C","explanation": "Postural correction exercise programs generally show greater and more sustained benefit when combined with ergonomic and behavioral education addressing sustained postures during daily activities, supporting better carryover of postural improvements beyond the specific exercise session itself."},{"id": 7911,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Which factor should be considered when addressing postural deviations in a growing adolescent, distinct from considerations in a skeletally mature adult?","options": [{"key": "A","text": "Only cosmetic concerns are relevant in this population, with no functional considerations"},{"key": "B","text": "Adolescents never develop any postural deviations requiring clinical attention"},{"key": "C","text": "No distinct considerations exist, management is identical regardless of skeletal maturity"},{"key": "D","text": "The potential for structural changes to progress or be influenced during the remaining growth period, making monitoring and appropriately timed intervention particularly relevant"}],"correct": "D","explanation": "In growing adolescents, the potential for structural postural changes (e.g., scoliosis, kyphosis) to progress during the remaining growth period is an important consideration, making appropriately timed monitoring and intervention particularly relevant compared to a skeletally mature adult population."},{"id": 7912,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Lateral pelvic tilt, often related to leg length discrepancy or hip abductor imbalance, can contribute to compensatory changes in which adjacent spinal region?","options": [{"key": "A","text": "Compensatory functional scoliosis or altered lumbar spine alignment as the spine adapts to the pelvic asymmetry"},{"key": "B","text": "No compensatory changes occur in any adjacent region"},{"key": "C","text": "Exclusively affects upper limb posture"},{"key": "D","text": "Only affects the cervical spine, with no lumbar involvement"}],"correct": "A","explanation": "Lateral pelvic tilt can contribute to compensatory functional scoliosis or altered lumbar spine alignment as the spine adapts to the underlying pelvic asymmetry, illustrating the interconnected relationship between pelvic and spinal postural alignment."},{"id": 7913,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Which general principle guides the physiotherapy approach to addressing postural deviations, recognizing that posture is influenced by multiple interacting factors?","options": [{"key": "A","text": "Addressing only the most visually obvious deviation in isolation, without considering broader contributing factors"},{"key": "B","text": "No systematic approach is relevant to postural assessment and management"},{"key": "C","text": "A comprehensive assessment approach considering the interrelated influence of muscle imbalances, joint mobility, habitual movement patterns, and relevant lifestyle/ergonomic factors across the kinetic chain"},{"key": "D","text": "Postural assessment and intervention should focus exclusively on a single isolated body region with no consideration of broader kinetic chain relationships"}],"correct": "C","explanation": "Given the interconnected nature of postural alignment across the kinetic chain, a comprehensive physiotherapy assessment approach considers the interrelated influence of muscle imbalances, joint mobility, movement patterns, and relevant lifestyle factors, rather than focusing narrowly on an isolated body region."},{"id": 7914,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "The Maitland concept of manual therapy is characterized by which distinctive approach to grading passive joint mobilization?","options": [{"key": "A","text": "Exclusively high-velocity thrust manipulation techniques, with no oscillatory component"},{"key": "B","text": "No systematic grading system is used in this approach"},{"key": "C","text": "A fixed, single-intensity technique applied identically to all patients regardless of presentation"},{"key": "D","text": "A graded oscillatory mobilization system (Grades I-IV), with grade selection guided primarily by patient response (pain and resistance) during treatment"}],"correct": "D","explanation": "The Maitland concept uses a graded oscillatory mobilization system (Grades I-IV, sometimes extended to V for manipulation), with the specific grade selected and continuously adjusted based on the patient's ongoing pain and resistance response during treatment, emphasizing a responsive, patient-guided approach."},{"id": 7915,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "In the Maitland grading system, Grade IV mobilization is characterized by:","options": [{"key": "A","text": "Grade IV does not exist in the Maitland grading system"},{"key": "B","text": "A small-amplitude oscillation performed at the end of available range, into tissue resistance"},{"key": "C","text": "A small-amplitude oscillation performed at the very beginning of available range"},{"key": "D","text": "A large-amplitude oscillation through the mid-range only, avoiding end range"}],"correct": "B","explanation": "Grade IV mobilizations involve small-amplitude oscillations performed at the end of the available range, moving into tissue resistance, typically used to address stiffness-dominant presentations."},{"id": 7916,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "The Mulligan concept of manual therapy is distinctively characterized by which combination of technique elements?","options": [{"key": "A","text": "Combining a sustained accessory glide applied by the therapist with an active movement or function performed by the patient (Mobilization with Movement, MWM)"},{"key": "B","text": "Purely passive mobilization with no active patient participation required"},{"key": "C","text": "Exclusively high-velocity thrust techniques with no sustained component"},{"key": "D","text": "Only involves soft tissue massage techniques, with no joint mobilization component"}],"correct": "A","explanation": "The Mulligan concept is distinctively characterized by Mobilization with Movement (MWM) techniques, which combine a sustained accessory glide applied by the therapist with an active movement or functional task performed simultaneously by the patient."},{"id": 7917,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "A key clinical indicator guiding appropriate technique selection/application within the Mulligan concept is:","options": [{"key": "A","text": "The technique should always be painful during application to be considered effective"},{"key": "B","text": "Patient age determines technique choice with no other clinical reasoning involved"},{"key": "C","text": "The technique should be immediately pain-free during application; if pain is provoked, the technique parameters (e.g., glide direction/grade) should be adjusted or the approach reconsidered"},{"key": "D","text": "Time since injury is the only relevant consideration for technique selection"}],"correct": "C","explanation": "A defining principle of the Mulligan concept is that the applied technique should be pain-free during performance; if pain is provoked, this indicates the need to adjust technique parameters or reconsider the approach, as pain-free execution is considered an important indicator of appropriate technique application."},{"id": 7918,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "The Kaltenborn concept of manual therapy places particular emphasis on which biomechanical principle guiding joint mobilization direction, related to joint surface convexity/concavity?","options": [{"key": "A","text": "Ignoring joint surface shape entirely when determining mobilization direction"},{"key": "B","text": "Only using distraction techniques, regardless of specific joint anatomy"},{"key": "C","text": "Joint surface shape has no relevance to this manual therapy approach"},{"key": "D","text": "The concave-convex rule, using joint surface shape (concave or convex) to determine the appropriate direction of accessory glide mobilization relative to physiological movement"}],"correct": "D","explanation": "The Kaltenborn approach places strong emphasis on the concave-convex rule, using the specific joint surface shape (whether the moving segment is concave or convex relative to its partner) to guide the appropriate direction of accessory glide mobilization relative to the physiological movement being addressed."},{"id": 7919,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Within manual therapy approaches generally, 'traction/distraction' techniques applied to a joint aim primarily to:","options": [{"key": "A","text": "Separate the joint surfaces, potentially reducing compressive load and/or addressing capsular restriction depending on grade/purpose"},{"key": "B","text": "Compress the joint surfaces together more forcefully"},{"key": "C","text": "Have no distinct mechanical effect compared to glide techniques"},{"key": "D","text": "Only be used for spinal joints, never peripheral joints"}],"correct": "A","explanation": "Traction/distraction techniques aim to separate joint surfaces, which can serve various purposes depending on the grade applied, including pain modulation (lighter grades) or addressing capsular restriction (stronger, sustained grades)."},{"id": 7920,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "High-velocity, low-amplitude (HVLA) thrust manipulation techniques are characterized by which distinguishing feature compared to oscillatory mobilization?","options": [{"key": "A","text": "A rapid, small-amplitude thrust applied at the end of available range, often producing an audible 'pop' or 'crack' (cavitation)"},{"key": "B","text": "Slow, rhythmic, repeated small-amplitude movements"},{"key": "C","text": "No distinguishing features exist compared to standard oscillatory mobilization"},{"key": "D","text": "Techniques that are always sustained for several minutes without any thrust component"}],"correct": "A","explanation": "HVLA manipulation techniques involve a rapid, small-amplitude thrust delivered at the end of available joint range, often associated with an audible cavitation ('pop'), distinguishing them from the slower, rhythmic oscillatory mobilization techniques."},{"id": 7921,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Which safety consideration is particularly emphasized before performing cervical spine manipulation, given the region's specific vascular anatomy considerations?","options": [{"key": "A","text": "Manipulation should always be performed regardless of any screening findings"},{"key": "B","text": "This safety consideration is only relevant to lumbar spine techniques"},{"key": "C","text": "Appropriate screening for vertebrobasilar insufficiency risk factors and other contraindications, given the vascular structures in proximity to the cervical spine"},{"key": "D","text": "No specific pre-manipulative screening is required for the cervical spine, unlike other spinal regions"}],"correct": "C","explanation": "Given the vascular structures in close proximity to the cervical spine, appropriate pre-manipulative screening for vertebrobasilar insufficiency risk factors and other contraindications is particularly emphasized before considering cervical manipulation techniques."},{"id": 7922,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Soft tissue mobilization techniques (e.g., myofascial release, cross-friction massage) are generally used within a comprehensive treatment approach to address which type of tissue restriction/dysfunction?","options": [{"key": "A","text": "Exclusively cardiovascular conditioning, unrelated to any tissue restriction"},{"key": "B","text": "Only bony joint restrictions, with no application to soft tissue structures"},{"key": "C","text": "Only used as a standalone treatment approach, never combined with other interventions"},{"key": "D","text": "Muscle, fascial, or tendon-related restrictions/dysfunction, often used alongside joint-focused techniques and active exercise"}],"correct": "D","explanation": "Soft tissue mobilization techniques address muscle, fascial, or tendon-related restrictions and dysfunction, generally used as part of a comprehensive treatment approach alongside joint-focused manual therapy techniques and active exercise interventions."},{"id": 7923,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Which clinical reasoning principle is emphasized across most contemporary manual therapy approaches regarding technique selection and progression?","options": [{"key": "A","text": "Manual therapy techniques should never be adjusted once initially selected, regardless of patient response"},{"key": "B","text": "An individualized approach guided by ongoing patient assessment and response to treatment, adjusting technique selection and parameters accordingly rather than following a rigid, one-size-fits-all protocol"},{"key": "C","text": "Applying a fixed, predetermined technique sequence to all patients regardless of individual presentation or response"},{"key": "D","text": "Clinical reasoning has no role in manual therapy, as it is purely a mechanical intervention"}],"correct": "B","explanation": "Contemporary manual therapy approaches generally emphasize individualized clinical reasoning, with technique selection and progression guided by ongoing assessment of patient response, rather than rigid application of a predetermined, one-size-fits-all protocol."},{"id": 7924,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Hard","question": "The proposed mechanism of pain relief following manual therapy intervention is understood to potentially involve which combination of factors, beyond purely mechanical/structural explanations?","options": [{"key": "A","text": "A combination of neurophysiological effects (e.g., pain modulation via various neural pathways), along with potential mechanical and psychosocial contributing factors"},{"key": "B","text": "Manual therapy mechanisms are completely understood with no ongoing scientific discussion"},{"key": "C","text": "Only direct mechanical correction of a 'misaligned' joint, with no other contributing mechanisms"},{"key": "D","text": "Manual therapy has no plausible mechanism and works only through placebo effect with certainty"}],"correct": "A","explanation": "Contemporary understanding of manual therapy's therapeutic effects recognizes a likely combination of neurophysiological pain modulation mechanisms, along with potential mechanical and psychosocial contributing factors, moving beyond simplistic purely structural/mechanical explanations of a 'misaligned' joint being directly corrected."},{"id": 7925,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Contraindications to manual therapy techniques generally include which category of conditions, requiring careful screening before treatment application?","options": [{"key": "A","text": "Only relevant for spinal techniques, with no contraindications applicable to peripheral joint techniques"},{"key": "B","text": "Manual therapy is always safe regardless of any underlying patient condition"},{"key": "C","text": "Conditions such as active malignancy at the treatment site, acute fracture, significant instability, or active infection, among others depending on specific technique and region"},{"key": "D","text": "No contraindications exist for any manual therapy technique"}],"correct": "C","explanation": "Manual therapy techniques carry contraindications that require careful screening, including conditions such as active malignancy at the treatment site, acute fracture, significant joint instability, or active infection, among other considerations depending on the specific technique and body region involved."},{"id": 7926,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Hard","question": "Sustained natural apophyseal glides (SNAGs), a specific technique category within the Mulligan concept, are commonly applied to which region, combining sustained glide with active movement?","options": [{"key": "A","text": "SNAGs have no specific defining characteristics distinguishing them from other Mulligan techniques"},{"key": "B","text": "Exclusively used for soft tissue conditions, with no application to joint-related presentations"},{"key": "C","text": "Commonly applied to the spine, combining a sustained accessory glide to a vertebral segment with an active physiological movement performed by the patient"},{"key": "D","text": "Only applied to peripheral joints, never the spine"}],"correct": "C","explanation": "SNAGs (Sustained Natural Apophyseal Glides) are a specific Mulligan concept technique category commonly applied to spinal segments, combining a sustained accessory glide with an active physiological movement performed by the patient, following the core pain-free principle of the Mulligan approach."},{"id": 7927,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Which factor should guide the clinician's decision regarding appropriate manual therapy grade/intensity for a patient presenting with a highly irritable, acutely painful condition?","options": [{"key": "A","text": "Always beginning with the most aggressive, high-grade technique available regardless of irritability"},{"key": "B","text": "Generally favoring gentler techniques (e.g., lower Maitland grades focused on pain modulation) initially, progressing as irritability decreases and tolerance improves"},{"key": "C","text": "Irritability level has no bearing on appropriate technique grade selection"},{"key": "D","text": "Only high-velocity manipulation techniques are appropriate regardless of presentation"}],"correct": "B","explanation": "For highly irritable, acutely painful presentations, clinical reasoning generally favors initially selecting gentler techniques (such as lower-grade oscillatory mobilizations focused on pain modulation) before progressing to more vigorous techniques as irritability decreases and tissue tolerance improves."},{"id": 7928,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Combining manual therapy techniques with active exercise interventions, rather than using manual therapy as an isolated passive treatment, is generally supported because:","options": [{"key": "A","text": "There is no evidence supporting the combination of these treatment approaches"},{"key": "B","text": "Manual therapy alone, without any active component, has been shown to provide superior and more sustained outcomes in all conditions"},{"key": "C","text": "Active exercise has no role in musculoskeletal rehabilitation, manual therapy alone is sufficient"},{"key": "D","text": "A combined approach is generally associated with better outcomes for many musculoskeletal conditions compared to passive treatment alone, supporting active patient engagement in the recovery process"}],"correct": "D","explanation": "Evidence generally supports that combining manual therapy with active exercise interventions is associated with better outcomes for many musculoskeletal conditions compared to relying on passive manual therapy treatment in isolation, supporting the importance of active patient engagement in the rehabilitation process."},{"id": 7929,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "The principle of 'specificity' in exercise therapy refers to:","options": [{"key": "A","text": "Exercise specificity has no relevance to rehabilitation program design"},{"key": "B","text": "Only relevant to strength training, with no application to other exercise modalities"},{"key": "C","text": "Training adaptations being specific to the type of exercise, movement pattern, and demands placed on the body, meaning rehabilitation exercises should closely relate to the functional goals being targeted"},{"key": "D","text": "Training adaptations occurring generally across all movement patterns regardless of the specific exercise performed"}],"correct": "C","explanation": "The principle of specificity states that training adaptations are specific to the particular type of exercise and demands imposed, meaning rehabilitation exercise selection should closely relate to and progress toward the specific functional movement patterns/goals being targeted for the individual patient."},{"id": 7930,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Easy","question": "Progressive overload, a fundamental exercise therapy principle, refers to:","options": [{"key": "A","text": "Systematically and gradually increasing the demand placed on the body (e.g., through load, repetitions, or complexity) over time to continue promoting adaptation"},{"key": "B","text": "Maintaining an identical, unchanging exercise stimulus indefinitely throughout a rehabilitation program"},{"key": "C","text": "Progressive overload is only relevant to elite athletes, not general rehabilitation patients"},{"key": "D","text": "Immediately applying maximal load regardless of the patient's current capacity"}],"correct": "A","explanation": "Progressive overload involves systematically and gradually increasing the exercise demand (through variables such as load, volume, or complexity) over time, which is necessary to continue promoting physiological adaptation and functional improvement throughout a rehabilitation program."},{"id": 7931,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Which exercise dosage parameter is generally manipulated to primarily target muscular endurance adaptations, as opposed to maximal strength gains?","options": [{"key": "A","text": "Lower to moderate load with higher repetitions (e.g., 15-25+ reps) and/or extended time under tension"},{"key": "B","text": "Only exercise frequency matters, with no relevance of load/repetition parameters"},{"key": "C","text": "Exercise dosage has no influence on the type of adaptation achieved"},{"key": "D","text": "Very heavy load with low repetitions (e.g., 1-5 reps)"}],"correct": "A","explanation": "Muscular endurance adaptations are generally targeted using lower to moderate loads combined with higher repetition ranges (or extended time under tension), contrasting with the heavier loads and lower repetition ranges typically used to more specifically target maximal strength gains."},{"id": 7932,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Isometric exercise, involving muscle contraction without joint movement, is often particularly useful in early-stage rehabilitation for which reason?","options": [{"key": "A","text": "Allowing muscle activation/strengthening with minimal joint movement stress, useful when joint motion needs to be limited (e.g., acute injury, post-surgical protocols) while still promoting some muscular loading"},{"key": "B","text": "Isometric exercise is identical in effect to eccentric exercise with no distinguishing characteristics"},{"key": "C","text": "Isometric exercise should only ever be used in the final stage of rehabilitation, never early stages"},{"key": "D","text": "Isometric exercise provides no benefit at any stage of rehabilitation"}],"correct": "A","explanation": "Isometric exercise allows for muscle activation and strengthening stimulus while minimizing joint movement, making it particularly useful in early rehabilitation stages when joint motion may need to be limited (e.g., following acute injury or within certain post-surgical protocols) while still providing some beneficial muscular loading."},{"id": 7933,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Eccentric exercise, involving muscle lengthening under tension, has particularly strong evidence supporting its use in the management of which type of condition?","options": [{"key": "A","text": "Chronic tendinopathy (e.g., Achilles, patellar tendinopathy)"},{"key": "B","text": "Acute ligament sprains exclusively"},{"key": "C","text": "Acute fracture healing"},{"key": "D","text": "Acute compartment syndrome"}],"correct": "A","explanation": "Eccentric exercise protocols have particularly strong evidence supporting their use in the management of chronic tendinopathy conditions, such as Achilles and patellar tendinopathy, as part of a progressive loading approach."},{"id": 7934,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Which type of exercise is generally characterized by a fixed, external constraint on the distal segment, with the proximal segments moving relative to it (e.g., squats, push-ups)?","options": [{"key": "A","text": "Open kinetic chain exercise"},{"key": "B","text": "Isolated single-joint exercise exclusively"},{"key": "C","text": "Closed kinetic chain exercise"},{"key": "D","text": "Passive range of motion exercise"}],"correct": "C","explanation": "Closed kinetic chain exercises involve a fixed distal segment (in contact with a supporting surface) with proximal body segments moving relative to this fixed point, as seen in exercises like squats or push-ups."},{"id": 7935,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Hard","question": "Closed kinetic chain exercises are often favored in certain phases of lower limb rehabilitation (e.g., early ACL rehabilitation) partly due to which biomechanical characteristic compared to some open chain exercises?","options": [{"key": "A","text": "Closed kinetic chain exercises always produce identical joint forces to open kinetic chain exercises"},{"key": "B","text": "Generally producing greater joint shear forces compared to equivalent open chain exercises"},{"key": "C","text": "Often producing relatively greater joint compressive forces with potentially reduced shear forces at certain joint angles compared to some open chain movements, which can be advantageous for protecting healing ligamentous structures"},{"key": "D","text": "Closed kinetic chain exercises are never appropriate in any phase of ligament rehabilitation"}],"correct": "C","explanation": "Closed kinetic chain exercises often produce relatively greater joint compressive forces with potentially more favorable (reduced) shear force profiles at certain joint angles compared to some open kinetic chain movements, which can be advantageous when aiming to protect healing ligamentous structures during specific rehabilitation phases."},{"id": 7936,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Plyometric exercise, involving rapid eccentric-to-concentric muscle action (stretch-shortening cycle), is generally introduced at which stage of a comprehensive rehabilitation progression?","options": [{"key": "A","text": "Plyometric exercise has no role in musculoskeletal rehabilitation at any stage"},{"key": "B","text": "Only appropriate for upper limb rehabilitation, never lower limb"},{"key": "C","text": "As the very first exercise type introduced immediately following acute injury"},{"key": "D","text": "Later in the rehabilitation progression, once adequate foundational strength, joint stability, and movement control have been established"}],"correct": "D","explanation": "Given the high demands plyometric exercise places on the neuromuscular system and joint structures, it is generally introduced later in a rehabilitation progression, once adequate foundational strength, joint stability, and movement control have been established through earlier program phases."},{"id": 7937,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Hard","question": "Proprioceptive neuromuscular facilitation (PNF) stretching techniques (e.g., contract-relax) are thought to improve flexibility partly through which physiological mechanism?","options": [{"key": "A","text": "Only effective for upper limb muscle groups, with no application to lower limb flexibility"},{"key": "B","text": "Neurophysiological mechanisms potentially including autogenic inhibition (via Golgi tendon organ activation) and/or reciprocal inhibition, alongside mechanical tissue effects"},{"key": "C","text": "PNF techniques have no proposed mechanism and show no evidence of effectiveness"},{"key": "D","text": "Purely mechanical tissue lengthening with no neurophysiological component involved"}],"correct": "B","explanation": "PNF stretching techniques are thought to improve flexibility through a combination of proposed neurophysiological mechanisms, including autogenic inhibition (via Golgi tendon organ activation following contraction) and/or reciprocal inhibition, alongside direct mechanical tissue effects."},{"id": 7938,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Hard","question": "Which exercise prescription consideration is important when working with a patient who has significant pain sensitization/chronic pain presentation, potentially requiring modification from a purely tissue-healing-focused loading approach?","options": [{"key": "A","text": "Exercise should always be avoided entirely in any patient with chronic pain"},{"key": "B","text": "Immediately applying maximal exercise intensity to 'push through' any pain sensitization"},{"key": "C","text": "Chronic pain presentations require an identical exercise approach to acute, uncomplicated tissue injury with no modification needed"},{"key": "D","text": "Considering pain neuroscience education alongside graded exercise exposure, potentially starting at lower thresholds and progressing more gradually while addressing associated psychosocial factors"}],"correct": "D","explanation": "For patients with significant pain sensitization or chronic pain presentations, exercise prescription often benefits from incorporating pain neuroscience education alongside a carefully graded exercise exposure approach, potentially starting at lower thresholds and progressing more gradually while also addressing relevant psychosocial contributing factors."},{"id": 7939,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Which principle describes the loss of training adaptations that occurs when a structured exercise stimulus is discontinued or significantly reduced?","options": [{"key": "A","text": "Reversibility (detraining)"},{"key": "B","text": "Progressive overload"},{"key": "C","text": "Periodization"},{"key": "D","text": "Specificity"}],"correct": "A","explanation": "The principle of reversibility (detraining) describes the phenomenon whereby training-induced adaptations (e.g., strength, endurance gains) are gradually lost when the structured exercise stimulus is discontinued or significantly reduced, underscoring the importance of maintenance programming."},{"id": 7940,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "A structured home exercise program (HEP) is an important component of comprehensive rehabilitation primarily because:","options": [{"key": "A","text": "It extends therapeutic exercise dosage beyond supervised clinical sessions, supporting more consistent progress and patient self-management, given the limited frequency of typical clinic visits"},{"key": "B","text": "Home exercise programs should always be identical in content to supervised clinic sessions with no individualization"},{"key": "C","text": "Supervised clinical sessions alone are always sufficient without any need for home-based practice"},{"key": "D","text": "Home exercise programs have no evidence of benefit and should be avoided"}],"correct": "A","explanation": "A well-designed home exercise program extends the effective therapeutic exercise dosage beyond the relatively limited frequency of supervised clinical sessions, supporting more consistent progress and fostering patient self-management skills as an important component of comprehensive rehabilitation."},{"id": 7941,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Exercise adherence in rehabilitation programs can be influenced by which of the following factors, important for clinicians to consider in program design?","options": [{"key": "A","text": "Exercise adherence has no relationship to rehabilitation outcomes"},{"key": "B","text": "Factors such as program complexity, perceived relevance to patient goals, self-efficacy, and appropriate education/communication, among others"},{"key": "C","text": "Adherence is entirely random and cannot be influenced by any programmatic factors"},{"key": "D","text": "Only the specific exercises prescribed matter, with no relevance of communication or education factors"}],"correct": "B","explanation": "Exercise adherence can be influenced by various factors including program complexity, the patient's perceived relevance of exercises to their personal goals, self-efficacy, and the quality of clinician education/communication, all of which are important considerations in comprehensive rehabilitation program design."},{"id": 7942,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Medium","question": "Which of the following best describes an appropriate approach to exercise progression criteria within a structured rehabilitation protocol?","options": [{"key": "A","text": "Exercise progression should never occur under any circumstances once an initial program is established"},{"key": "B","text": "Progression criteria should generally be based on the patient demonstrating specific functional/performance benchmarks (e.g., adequate pain-free range, strength thresholds, movement quality) rather than time alone"},{"key": "C","text": "No criteria are needed for exercise progression decisions, progression should be entirely arbitrary"},{"key": "D","text": "Progression should occur automatically based purely on a fixed calendar timeline regardless of the patient's demonstrated readiness"}],"correct": "B","explanation": "Appropriate exercise progression within a rehabilitation protocol is generally guided by the patient demonstrating specific functional or performance-based benchmarks (such as adequate pain-free range of motion, strength thresholds, or movement quality), rather than progressing based on a fixed timeline alone without consideration of individual readiness."},{"id": 7943,"subject": "Exercise Therapy","topic": "Rehabilitation Principles","difficulty": "Hard","question": "Motor learning principles relevant to rehabilitation exercise prescription include which of the following considerations regarding practice structure?","options": [{"key": "A","text": "Practice structure has no relevance to rehabilitation exercise outcomes"},{"key": "B","text": "Considerations such as practice variability, feedback timing/frequency, and appropriate task complexity progression, which can influence motor skill acquisition and retention"},{"key": "C","text": "Only massed (continuous repetitive) practice should ever be used, with no consideration of other practice structures"},{"key": "D","text": "Motor learning principles only apply to neurological rehabilitation, with no relevance to musculoskeletal rehabilitation"}],"correct": "B","explanation": "Motor learning principles relevant to rehabilitation include considerations such as practice variability, the timing and frequency of feedback provided, and appropriate progression of task complexity, all of which can influence motor skill acquisition and longer-term retention, relevant across both neurological and musculoskeletal rehabilitation contexts."},{"id": 7944,"subject": "Anatomy","topic": "Applied Anatomy","difficulty": "Medium","question": "Which muscle is primarily responsible for scapular retraction, working with rhomboids?","options": [{"key": "A","text": "Upper trapezius"},{"key": "B","text": "Middle trapezius"},{"key": "C","text": "Serratus anterior"},{"key": "D","text": "Pectoralis minor"}],"correct": "B","explanation": "Middle trapezius, along with the rhomboids, is a primary scapular retractor, drawing the scapula toward the spine."},{"id": 7945,"subject": "Biomechanics","topic": "Kinesiology","difficulty": "Hard","question": "The 'obligate translation' concept in shoulder biomechanics refers to:","options": [{"key": "A","text": "Normal humeral head translation accompanying active elevation within a healthy joint"},{"key": "B","text": "Translation that occurs exclusively at the AC joint"},{"key": "C","text": "A finding with no clinical relevance"},{"key": "D","text": "Only pathological translation seen in unstable shoulders"}],"correct": "A","explanation": "Obligate translation describes the small, normal humeral head translations that accompany active shoulder elevation as part of healthy joint mechanics, distinct from pathological excessive translation."},{"id": 7946,"subject": "Clinical Skills","topic": "Special Tests","difficulty": "Medium","question": "Which special test differentiates a superior labral (SLAP) tear from AC joint pathology by comparing pronated versus supinated forearm positions during resisted forward flexion?","options": [{"key": "A","text": "Neer's test"},{"key": "B","text": "Speed's test"},{"key": "C","text": "O'Brien's active compression test"},{"key": "D","text": "Hawkins-Kennedy test"}],"correct": "C","explanation": "O'Brien's test compares pain with the forearm pronated versus supinated; pain localized deep in the shoulder with pronation suggests SLAP pathology, while pain at the AC joint suggests AC pathology."},{"id": 7947,"subject": "Orthopedics","topic": "Fractures - General","difficulty": "Medium","question": "Which fracture pattern is most associated with a 'butterfly fragment', a triangular third piece from bending forces?","options": [{"key": "A","text": "Spiral fracture"},{"key": "B","text": "Wedge (bending) fracture with a butterfly fragment"},{"key": "C","text": "Avulsion fracture"},{"key": "D","text": "Simple transverse fracture"}],"correct": "B","explanation": "A bending force can produce a wedge-shaped 'butterfly' fragment on the compression side of the bone, characteristic of a wedge fracture pattern."},{"id": 7948,"subject": "Orthopedics","topic": "Fractures - Upper Limb","difficulty": "Medium","question": "Which upper limb fracture is most associated with radial nerve injury presenting as wrist drop?","options": [{"key": "A","text": "Humeral shaft fracture (midshaft, spiral pattern)"},{"key": "B","text": "Clavicle fracture"},{"key": "C","text": "Distal radius fracture"},{"key": "D","text": "Olecranon fracture"}],"correct": "A","explanation": "Midshaft humeral fractures, particularly spiral patterns, are classically associated with radial nerve injury as the nerve courses in the spiral groove."},{"id": 7949,"subject": "Orthopedics","topic": "Fractures - Lower Limb","difficulty": "Medium","question": "A stress fracture of the femoral shaft in a runner most commonly presents with which symptom pattern?","options": [{"key": "A","text": "Gradual onset of activity-related thigh pain, worsening with continued running"},{"key": "B","text": "No pain, only weakness"},{"key": "C","text": "Sudden acute pain with obvious deformity"},{"key": "D","text": "Painless swelling only"}],"correct": "A","explanation": "Femoral shaft stress fractures in runners typically present with a gradual, activity-related pain pattern that worsens with continued training, similar to other lower limb stress fractures."},{"id": 7950,"subject": "Orthopedics","topic": "Dislocations & Subluxations","difficulty": "Medium","question": "A traumatic anterior shoulder dislocation is most likely to occur with the arm in which position?","options": [{"key": "A","text": "Neutral position at the side"},{"key": "B","text": "Full flexion and pronation"},{"key": "C","text": "Adduction and internal rotation"},{"key": "D","text": "Abduction and external rotation"}],"correct": "D","explanation": "The classic position of vulnerability for anterior shoulder dislocation is abduction combined with external rotation, which stresses the anteroinferior capsuloligamentous structures."},{"id": 7951,"subject": "Orthopedics","topic": "Soft Tissue Injuries","difficulty": "Hard","question": "Chronic ankle sprains that fail to respond to conservative management may show which pathological change on imaging?","options": [{"key": "A","text": "Increased ligament elasticity with no scarring"},{"key": "B","text": "Chronic ligament thickening/scarring or associated osteochondral lesions of the talus"},{"key": "C","text": "Only muscle atrophy with no ligament involvement"},{"key": "D","text": "Complete absence of any structural change"}],"correct": "B","explanation": "Chronic, poorly resolving ankle sprains can show ligament thickening/scarring and are associated with increased risk of osteochondral lesions of the talar dome, which should be considered in refractory cases."},{"id": 7952,"subject": "Orthopedics","topic": "Shoulder Disorders","difficulty": "Hard","question": "Which of the following best describes the 'critical shoulder angle' relevance in preoperative planning for rotator cuff repair?","options": [{"key": "A","text": "It is used exclusively for elbow conditions"},{"key": "B","text": "It only applies to hip surgery planning"},{"key": "C","text": "A larger critical shoulder angle may be associated with higher retear risk, informing surgical decision-making"},{"key": "D","text": "It has no relevance to surgical planning"}],"correct": "C","explanation": "The critical shoulder angle has been studied as a factor associated with rotator cuff tear risk and potentially retear risk after repair, informing some aspects of surgical planning and risk stratification."},{"id": 7953,"subject": "Orthopedics","topic": "Elbow, Wrist & Hand Disorders","difficulty": "Easy","question": "A positive Finkelstein's test combined with pain over the radial styloid strongly suggests which diagnosis?","options": [{"key": "A","text": "De Quervain's tenosynovitis"},{"key": "B","text": "Carpal tunnel syndrome"},{"key": "C","text": "Trigger finger"},{"key": "D","text": "Guyon's canal syndrome"}],"correct": "A","explanation": "The combination of a positive Finkelstein's test and radial styloid pain is classic for De Quervain's tenosynovitis, involving the first dorsal compartment tendons."},{"id": 7954,"subject": "Orthopedics","topic": "Hip Joint Disorders","difficulty": "Medium","question": "Which hip pathology should be considered in a young athlete presenting with anterior groin pain, mechanical symptoms, and a positive FADIR test?","options": [{"key": "A","text": "Isolated trochanteric bursitis"},{"key": "B","text": "Femoroacetabular impingement with possible labral tear"},{"key": "C","text": "Simple adductor strain only"},{"key": "D","text": "Ankylosing spondylitis exclusively"}],"correct": "B","explanation": "Anterior groin pain with mechanical symptoms and a positive FADIR test in a young athlete raises suspicion for femoroacetabular impingement with possible associated labral pathology."},{"id": 7955,"subject": "Orthopedics","topic": "Knee Joint Disorders","difficulty": "Medium","question": "Which structure's injury is most associated with a positive Lachman test combined with a positive pivot shift test?","options": [{"key": "A","text": "Isolated MCL sprain"},{"key": "B","text": "Isolated meniscal tear"},{"key": "C","text": "PCL insufficiency"},{"key": "D","text": "ACL insufficiency with rotational instability"}],"correct": "D","explanation": "Both a positive Lachman and positive pivot shift together strongly support functional ACL insufficiency with associated rotational instability."},{"id": 7956,"subject": "Orthopedics","topic": "Foot & Ankle Disorders","difficulty": "Medium","question": "Which condition should be considered in a runner presenting with gradual-onset lateral knee pain that worsens specifically with downhill running?","options": [{"key": "A","text": "Patellar tendinopathy"},{"key": "B","text": "Pes anserine bursitis"},{"key": "C","text": "Popliteus tendinopathy"},{"key": "D","text": "Iliotibial band syndrome"}],"correct": "D","explanation": "ITB syndrome classically presents with lateral knee pain aggravated by running, particularly downhill running, related to repetitive friction near the lateral femoral epicondyle."},{"id": 7957,"subject": "Orthopedics","topic": "Cervical Spine Disorders","difficulty": "Medium","question": "A positive Spurling's test combined with weakness in C6 myotome distribution supports which diagnosis?","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "Thoracic outlet syndrome"},{"key": "C","text": "Cervical radiculopathy at the C6 level"},{"key": "D","text": "Rotator cuff tear"}],"correct": "C","explanation": "A positive Spurling's test with corresponding C6 myotomal weakness supports a diagnosis of cervical radiculopathy affecting the C6 nerve root."},{"id": 7958,"subject": "Orthopedics","topic": "Lumbar Spine Disorders","difficulty": "Medium","question": "Which clinical finding pattern would be most consistent with lumbar spinal stenosis rather than a disc herniation?","options": [{"key": "A","text": "Symptoms unrelated to any posture"},{"key": "B","text": "Symptoms worse with sitting, better with standing"},{"key": "C","text": "Symptoms worse with standing/walking, better with sitting or forward flexion"},{"key": "D","text": "Symptoms only present at night with no activity relationship"}],"correct": "C","explanation": "Neurogenic claudication from spinal stenosis worsens with standing/walking (extension) and improves with sitting/flexion, the opposite pattern typically seen with many disc herniation presentations that may worsen with flexion/sitting."},{"id": 7959,"subject": "Orthopedics","topic": "Arthritis Disorders","difficulty": "Medium","question": "Which laboratory finding pattern would be most suggestive of rheumatoid arthritis rather than osteoarthritis in a patient with polyarticular hand pain?","options": [{"key": "A","text": "Normal inflammatory markers with positive imaging showing osteophytes"},{"key": "B","text": "Normal all laboratory findings with joint space narrowing only"},{"key": "C","text": "Elevated ESR/CRP with positive rheumatoid factor and anti-CCP antibodies"},{"key": "D","text": "Elevated uric acid level only"}],"correct": "C","explanation": "Elevated inflammatory markers (ESR/CRP) along with positive rheumatoid factor and anti-CCP antibodies support a diagnosis of rheumatoid arthritis over the typically normal inflammatory marker profile seen in osteoarthritis."},{"id": 7960,"subject": "Orthopedics","topic": "Metabolic Bone Diseases","difficulty": "Hard","question": "Which combination of findings would most strongly suggest osteomalacia rather than osteoporosis in an adult patient?","options": [{"key": "A","text": "Low vitamin D, low/normal calcium, elevated alkaline phosphatase, and bone pain in addition to reduced density"},{"key": "B","text": "No laboratory abnormalities in either condition"},{"key": "C","text": "Normal calcium/phosphate with reduced bone density only"},{"key": "D","text": "Elevated calcium with normal vitamin D"}],"correct": "A","explanation": "Osteomalacia typically shows biochemical abnormalities including low vitamin D, low or low-normal calcium, and elevated alkaline phosphatase, along with bone pain, distinguishing it from osteoporosis which typically shows normal biochemistry with isolated reduced bone density."},{"id": 7961,"subject": "Pediatrics","topic": "Orthopedic Conditions","difficulty": "Medium","question": "A child presenting with insidious hip pain, limited internal rotation, and a positive log roll test with irritability should raise suspicion for which condition requiring further workup?","options": [{"key": "A","text": "Normal developmental variant requiring no further evaluation"},{"key": "B","text": "Perthes disease or other significant hip pathology requiring imaging workup"},{"key": "C","text": "Simple growing pains"},{"key": "D","text": "Isolated ankle sprain"}],"correct": "B","explanation": "Insidious hip pain with limited internal rotation and a positive log roll test in a child are concerning findings that should prompt further evaluation for conditions such as Perthes disease, among other significant hip pathologies."},{"id": 7962,"subject": "Neurology","topic": "Peripheral Nerve Injuries","difficulty": "Medium","question": "Which nerve injury classification would be expected to show the best and fastest spontaneous recovery on serial clinical assessment?","options": [{"key": "A","text": "Neurapraxia"},{"key": "B","text": "Axonotmesis"},{"key": "C","text": "All three show identical recovery timelines"},{"key": "D","text": "Neurotmesis"}],"correct": "A","explanation": "Neurapraxia, involving only a temporary conduction block without axonal disruption, generally shows the fastest and most complete spontaneous recovery among the three Seddon classification categories."},{"id": 7963,"subject": "Musculoskeletal Physiotherapy","topic": "Amputation & Prosthetics","difficulty": "Medium","question": "Which residual limb complication would most urgently require adjustment of a prosthetic socket?","options": [{"key": "A","text": "Normal expected limb volume fluctuation early post-amputation"},{"key": "B","text": "Mild residual limb fatigue after a full day of use"},{"key": "C","text": "Persistent skin breakdown or ulceration at a pressure point"},{"key": "D","text": "Mild, transient redness that resolves within minutes of prosthesis removal"}],"correct": "C","explanation": "Persistent skin breakdown or ulceration at a pressure point is a concerning finding requiring urgent prosthetic socket adjustment to prevent further tissue damage and complications."},{"id": 7964,"subject": "Exercise Therapy","topic": "Sports Injuries & Rehab","difficulty": "Medium","question": "An athlete with a suspected concussion who reports worsening headache, repeated vomiting, and increasing confusion should be managed with which priority action?","options": [{"key": "A","text": "Urgent medical/emergency evaluation given possible signs of a more serious intracranial injury"},{"key": "B","text": "No action needed, these are expected concussion symptoms requiring no escalation"},{"key": "C","text": "Reassurance and immediate return to play"},{"key": "D","text": "Continue standard graduated return-to-play protocol without changes"}],"correct": "A","explanation": "Worsening headache, repeated vomiting, and increasing confusion are red flag symptoms that could indicate a more serious intracranial injury requiring urgent emergency medical evaluation, rather than routine concussion protocol management."},{"id": 7965,"subject": "Biomechanics","topic": "Postural Deformities","difficulty": "Medium","question": "Which finding would most support a diagnosis of structural rather than postural/functional scoliosis on clinical examination?","options": [{"key": "A","text": "Curve improves completely with active postural correction"},{"key": "B","text": "Persistent rib hump/vertebral rotation on forward bending (positive Adam's test) that does not correct"},{"key": "C","text": "Curve fully corrects with forward bending"},{"key": "D","text": "Curve only present when standing, absent when supine"}],"correct": "B","explanation": "A persistent rib hump or vertebral rotation on the Adam's forward bend test that does not correct with position change is a key finding supporting structural rather than functional/postural scoliosis."},{"id": 7966,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy Concepts","difficulty": "Medium","question": "Which principle from the Mulligan concept would guide a clinician to discontinue or modify a mobilization-with-movement technique during treatment?","options": [{"key": "A","text": "The technique should continue regardless of any pain elicited"},{"key": "B","text": "Techniques should only be modified based on time elapsed, not patient response"},{"key": "C","text": "Pain during treatment is expected and should be ignored entirely"},{"key": "D","text": "If the technique provokes pain during application, indicating it should be adjusted or reconsidered per the pain-free principle"}],"correct": "D","explanation": "A core Mulligan concept principle is that techniques should be pain-free during application; provocation of pain signals the need to adjust technique parameters (e.g., glide direction, grade) or reconsider the approach."},{"id": 7967,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The greater trochanter of femur gives attachment to all of the following EXCEPT:","options": [{"key": "A","text": "Gluteus minimus"},{"key": "B","text": "Piriformis"},{"key": "C","text": "Gluteus maximus"},{"key": "D","text": "Gluteus medius"}],"correct": "C","explanation": "Gluteus maximus inserts into the iliotibial tract and gluteal tuberosity, not the greater trochanter."},{"id": 7968,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Which muscle forms the 'rotator cuff' but is NOT a medial rotator of the shoulder?","options": [{"key": "A","text": "Infraspinatus"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Supraspinatus"},{"key": "D","text": "Subscapularis"}],"correct": "C","explanation": "Supraspinatus initiates abduction; infraspinatus and teres minor are lateral rotators, subscapularis is a medial rotator."},{"id": 7969,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'anatomical snuff box' is bounded medially by the tendon of:","options": [{"key": "A","text": "Extensor pollicis longus"},{"key": "B","text": "Flexor pollicis longus"},{"key": "C","text": "Abductor pollicis longus"},{"key": "D","text": "Extensor pollicis brevis"}],"correct": "A","explanation": "EPL forms the medial (ulnar) border; APL and EPB form the lateral border."},{"id": 7970,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which carpal bone is most commonly fractured?","options": [{"key": "A","text": "Scaphoid"},{"key": "B","text": "Capitate"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Lunate"}],"correct": "A","explanation": "Scaphoid fracture is the commonest carpal fracture, often from FOOSH injury."},{"id": 7971,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The nerve most likely injured in a mid-shaft humeral fracture is:","options": [{"key": "A","text": "Median nerve"},{"key": "B","text": "Ulnar nerve"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Axillary nerve"}],"correct": "C","explanation": "Radial nerve runs in the spiral (radial) groove of the humeral shaft."},{"id": 7972,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The primary ossification center for a long bone shaft is called the:","options": [{"key": "A","text": "Diaphysis"},{"key": "B","text": "Metaphysis"},{"key": "C","text": "Physis"},{"key": "D","text": "Epiphysis"}],"correct": "A","explanation": "Diaphysis is the primary ossification center; epiphyses are secondary centers."},{"id": 7973,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which ligament is the primary restraint to anterior tibial translation?","options": [{"key": "A","text": "LCL"},{"key": "B","text": "ACL"},{"key": "C","text": "PCL"},{"key": "D","text": "MCL"}],"correct": "B","explanation": "ACL prevents anterior translation of tibia on femur."},{"id": 7974,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'pes anserinus' is formed by tendons of all EXCEPT:","options": [{"key": "A","text": "Semitendinosus"},{"key": "B","text": "Gracilis"},{"key": "C","text": "Sartorius"},{"key": "D","text": "Semimembranosus"}],"correct": "D","explanation": "Pes anserinus = Sartorius + Gracilis + Semitendinosus; semimembranosus inserts separately on tibial condyle."},{"id": 7975,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which classification of joint is the pubic symphysis?","options": [{"key": "A","text": "Syndesmosis"},{"key": "B","text": "Synchondrosis"},{"key": "C","text": "Synovial"},{"key": "D","text": "Symphysis (secondary cartilaginous)"}],"correct": "D","explanation": "Pubic symphysis is a secondary cartilaginous (symphysis) joint with fibrocartilage disc."},{"id": 7976,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "The 'carrying angle' of the elbow is formed due to:","options": [{"key": "A","text": "Radial head shape"},{"key": "B","text": "Olecranon fossa depth"},{"key": "C","text": "Obliquity of trochlear groove"},{"key": "D","text": "Trochlea shape"}],"correct": "C","explanation": "The oblique trochlear groove causes lateral deviation of forearm (valgus) in extension = carrying angle."},{"id": 7977,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Which muscle is the chief flexor of the hip joint?","options": [{"key": "A","text": "Rectus femoris"},{"key": "B","text": "Pectineus"},{"key": "C","text": "Sartorius"},{"key": "D","text": "Iliopsoas"}],"correct": "D","explanation": "Iliopsoas (iliacus + psoas major) is the principal hip flexor."},{"id": 7978,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "The 'Q angle' of the knee is measured between lines joining:","options": [{"key": "A","text": "Iliac crest to patella and patella to malleolus"},{"key": "B","text": "PSIS to patella and patella to tibial tuberosity"},{"key": "C","text": "ASIS to tibial tuberosity and patella center to tibial tuberosity"},{"key": "D","text": "ASIS to patella and patella to ankle"}],"correct": "C","explanation": "Q angle = line from ASIS to patella center, and patella center to tibial tuberosity; normal ~10-15°."},{"id": 7979,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which nerve supplies the quadriceps femoris?","options": [{"key": "A","text": "Sciatic nerve"},{"key": "B","text": "Obturator nerve"},{"key": "C","text": "Femoral nerve"},{"key": "D","text": "Superior gluteal nerve"}],"correct": "C","explanation": "Femoral nerve (L2-L4) innervates quadriceps femoris."},{"id": 7980,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'safe zone' for intramuscular injection in gluteal region is:","options": [{"key": "A","text": "Lower outer quadrant"},{"key": "B","text": "Upper outer quadrant"},{"key": "C","text": "Central quadrant"},{"key": "D","text": "Medial lower quadrant"}],"correct": "B","explanation": "Upper outer quadrant avoids sciatic nerve and superior gluteal vessels."},{"id": 7981,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which of the following is a hinge (ginglymus) joint?","options": [{"key": "A","text": "Shoulder joint"},{"key": "B","text": "Hip joint"},{"key": "C","text": "Knee joint"},{"key": "D","text": "Elbow joint (humero-ulnar)"}],"correct": "D","explanation": "Humero-ulnar joint is a classic uniaxial hinge joint permitting flexion-extension only."},{"id": 7982,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "The deltoid ligament of the ankle prevents excessive:","options": [{"key": "A","text": "Dorsiflexion"},{"key": "B","text": "Eversion"},{"key": "C","text": "Plantarflexion"},{"key": "D","text": "Inversion"}],"correct": "B","explanation": "Deltoid (medial) ligament resists eversion/pronation stress at the ankle."},{"id": 7983,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Which muscle initiates the first 15° of shoulder abduction?","options": [{"key": "A","text": "Deltoid"},{"key": "B","text": "Serratus anterior"},{"key": "C","text": "Trapezius"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Supraspinatus initiates abduction; deltoid continues it beyond 15°."},{"id": 7984,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'scapulohumeral rhythm' ratio during arm abduction (180°) is approximately:","options": [{"key": "A","text": "3:1"},{"key": "B","text": "1:2"},{"key": "C","text": "1:1"},{"key": "D","text": "2:1 (glenohumeral:scapulothoracic)"}],"correct": "D","explanation": "Overall ratio of glenohumeral to scapulothoracic motion is about 2:1."},{"id": 7985,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following muscles is NOT a part of the quadriceps group?","options": [{"key": "A","text": "Vastus lateralis"},{"key": "B","text": "Vastus intermedius"},{"key": "C","text": "Tensor fascia lata"},{"key": "D","text": "Vastus medialis"}],"correct": "C","explanation": "TFL is a hip abductor/flexor, not part of quadriceps."},{"id": 7986,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "The 'anatomical position' of the shoulder in relation to scapular plane abduction is termed:","options": [{"key": "A","text": "Extension"},{"key": "B","text": "Flexion"},{"key": "C","text": "Elevation only"},{"key": "D","text": "Scaption"}],"correct": "D","explanation": "Scaption = elevation in the plane of scapula, 30-45° anterior to coronal plane."},{"id": 7987,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Which structure prevents posterior dislocation of the hip?","options": [{"key": "A","text": "Iliofemoral ligament"},{"key": "B","text": "Ischiofemoral ligament"},{"key": "C","text": "Pubofemoral ligament"},{"key": "D","text": "Ligamentum teres"}],"correct": "B","explanation": "Ischiofemoral ligament reinforces posterior hip capsule, limiting medial rotation/posterior dislocation."},{"id": 7988,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Which muscle is the strongest external rotator of the shoulder?","options": [{"key": "A","text": "Teres minor"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Deltoid (posterior fibers)"},{"key": "D","text": "Infraspinatus"}],"correct": "D","explanation": "Infraspinatus is the primary and strongest external rotator."},{"id": 7989,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'iliotibial band' primarily attaches distally to:","options": [{"key": "A","text": "Gerdy's tubercle of tibia"},{"key": "B","text": "Fibular head"},{"key": "C","text": "Medial tibial condyle"},{"key": "D","text": "Tibial tuberosity"}],"correct": "A","explanation": "ITB inserts on Gerdy's tubercle on the anterolateral tibia."},{"id": 7990,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which of the following is a plane synovial joint?","options": [{"key": "A","text": "Hip joint"},{"key": "B","text": "Knee joint"},{"key": "C","text": "Acromioclavicular joint"},{"key": "D","text": "Ankle joint"}],"correct": "C","explanation": "AC joint is a plane (gliding) synovial joint."},{"id": 7991,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The 'triangular space' in the axilla transmits which artery?","options": [{"key": "A","text": "Subscapular artery"},{"key": "B","text": "Circumflex scapular artery"},{"key": "C","text": "Profunda brachii artery"},{"key": "D","text": "Posterior circumflex humeral artery"}],"correct": "B","explanation": "Triangular space transmits circumflex scapular vessels."},{"id": 7992,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which muscle is primarily responsible for scapular downward rotation?","options": [{"key": "A","text": "Serratus anterior"},{"key": "B","text": "Trapezius (upper)"},{"key": "C","text": "Rhomboids"},{"key": "D","text": "Supraspinatus"}],"correct": "C","explanation": "Rhomboids (with levator scapulae) produce downward rotation and retraction of scapula."},{"id": 7993,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "The medial meniscus of the knee is more prone to injury than lateral because:","options": [{"key": "A","text": "It is more mobile"},{"key": "B","text": "It is smaller"},{"key": "C","text": "It is firmly attached to MCL and less mobile"},{"key": "D","text": "It has better blood supply"}],"correct": "C","explanation": "Medial meniscus is fixed to deep MCL, restricting mobility, predisposing to tear."},{"id": 7994,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'carrying angle' is normally greater in:","options": [{"key": "A","text": "Children only"},{"key": "B","text": "Females"},{"key": "C","text": "Equal in both"},{"key": "D","text": "Males"}],"correct": "B","explanation": "Females typically have a slightly larger carrying angle (~10-15°) than males (~5-10°)."},{"id": 7995,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which nerve, if injured, produces 'winging of scapula'?","options": [{"key": "A","text": "Long thoracic nerve"},{"key": "B","text": "Suprascapular nerve"},{"key": "C","text": "Axillary nerve"},{"key": "D","text": "Dorsal scapular nerve"}],"correct": "A","explanation": "Long thoracic nerve injury paralyzes serratus anterior causing medial winging."},{"id": 7996,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The 'Bankart lesion' involves which structure?","options": [{"key": "A","text": "Rotator cuff tendon"},{"key": "B","text": "Posterior labrum"},{"key": "C","text": "Biceps tendon"},{"key": "D","text": "Anteroinferior glenoid labrum"}],"correct": "D","explanation": "Bankart lesion = detachment of anteroinferior glenoid labrum, seen in anterior shoulder dislocation."},{"id": 7997,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following muscles has dual nerve supply (median and ulnar)?","options": [{"key": "A","text": "Palmaris longus"},{"key": "B","text": "Flexor digitorum superficialis"},{"key": "C","text": "Flexor digitorum profundus"},{"key": "D","text": "Flexor carpi radialis"}],"correct": "C","explanation": "FDP: lateral half by median (AIN), medial half by ulnar nerve."},{"id": 7998,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The primary function of the coracoacromial arch is to:","options": [{"key": "A","text": "Increase glenoid depth"},{"key": "B","text": "Protect the superior aspect of shoulder joint"},{"key": "C","text": "Provide muscle attachment only"},{"key": "D","text": "Stabilize the clavicle"}],"correct": "B","explanation": "Coraco-acromial arch prevents superior displacement of humeral head."},{"id": 7999,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which structure is the 'keystone' of the pelvic arch?","options": [{"key": "A","text": "Sacrum"},{"key": "B","text": "Pubis"},{"key": "C","text": "Ischium"},{"key": "D","text": "Ilium"}],"correct": "A","explanation": "Sacrum acts as keystone transmitting weight from spine to pelvis."},{"id": 8000,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "The 'screw home mechanism' of the knee occurs due to:","options": [{"key": "A","text": "Larger medial femoral condyle causing external tibial rotation in terminal extension"},{"key": "B","text": "Larger lateral femoral condyle"},{"key": "C","text": "Patellar tracking"},{"key": "D","text": "ACL laxity"}],"correct": "A","explanation": "Asymmetry of femoral condyles (medial larger) produces obligatory external rotation of tibia in last 30° extension, 'locking' the knee."},{"id": 8001,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "Which muscle is the prime mover for forearm supination when elbow is extended?","options": [{"key": "A","text": "Pronator teres"},{"key": "B","text": "Brachioradialis"},{"key": "C","text": "Biceps brachii"},{"key": "D","text": "Supinator"}],"correct": "D","explanation": "Supinator is prime mover in extension; biceps assists mainly when elbow flexed."},{"id": 8002,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "The 'four rotator cuff muscles' can be remembered by the acronym:","options": [{"key": "A","text": "STIS"},{"key": "B","text": "SATS"},{"key": "C","text": "TISS"},{"key": "D","text": "SITS (Supraspinatus, Infraspinatus, Teres minor, Subscapularis)"}],"correct": "D","explanation": "SITS mnemonic covers all 4 rotator cuff muscles."},{"id": 8003,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Which ligament of the knee is intra-articular but extra-synovial?","options": [{"key": "A","text": "LCL"},{"key": "B","text": "MCL"},{"key": "C","text": "Patellar ligament"},{"key": "D","text": "Cruciate ligaments"}],"correct": "D","explanation": "Cruciate ligaments lie within the joint capsule but outside the synovial cavity, covered by synovium."},{"id": 8004,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "The 'Trendelenburg sign' tests weakness of:","options": [{"key": "A","text": "Piriformis"},{"key": "B","text": "Gluteus medius and minimus"},{"key": "C","text": "Iliopsoas"},{"key": "D","text": "Gluteus maximus"}],"correct": "B","explanation": "Gluteus medius/minimus weakness causes contralateral pelvic drop during single-leg stance."},{"id": 8005,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Which is the strongest ligament of the hip joint?","options": [{"key": "A","text": "Iliofemoral (Y ligament of Bigelow)"},{"key": "B","text": "Ligamentum teres"},{"key": "C","text": "Ischiofemoral"},{"key": "D","text": "Pubofemoral"}],"correct": "A","explanation": "Iliofemoral ligament is the strongest, limiting hyperextension."},{"id": 8006,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The 'anatomical neck' of humerus is a common site of fracture in:","options": [{"key": "A","text": "Children (epiphyseal)"},{"key": "B","text": "Young adults from trauma"},{"key": "C","text": "Elderly (osteoporotic)"},{"key": "D","text": "Athletes"}],"correct": "C","explanation": "Anatomical neck fractures are rare, mostly elderly osteoporotic bone; surgical neck fracture is more common overall."},{"id": 8007,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Which muscle group forms the 'rotator interval' borders in the shoulder?","options": [{"key": "A","text": "Supraspinatus and subscapularis"},{"key": "B","text": "Subscapularis and teres minor"},{"key": "C","text": "Infraspinatus and teres minor"},{"key": "D","text": "Deltoid and biceps"}],"correct": "A","explanation": "Rotator interval lies between supraspinatus (superior) and subscapularis (inferior) tendons."},{"id": 8008,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The tibial tuberosity ossification center appears and is relevant clinically in which condition?","options": [{"key": "A","text": "Blount's disease"},{"key": "B","text": "Osgood-Schlatter disease"},{"key": "C","text": "Perthes disease"},{"key": "D","text": "Sever's disease"}],"correct": "B","explanation": "Osgood-Schlatter is traction apophysitis at tibial tuberosity in adolescents."},{"id": 8009,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which of the following best describes the hip joint type?","options": [{"key": "A","text": "Saddle (biaxial)"},{"key": "B","text": "Hinge (uniaxial)"},{"key": "C","text": "Pivot (uniaxial)"},{"key": "D","text": "Ball and socket (multiaxial)"}],"correct": "D","explanation": "Hip is a ball-and-socket synovial joint allowing triaxial movement."},{"id": 8010,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The 'carrying' function of forearm bones during pronation-supination occurs mainly at:","options": [{"key": "A","text": "Intercarpal joints"},{"key": "B","text": "Proximal and distal radioulnar joints"},{"key": "C","text": "Wrist joint"},{"key": "D","text": "Elbow joint"}],"correct": "B","explanation": "Pronation/supination occurs at proximal and distal radioulnar joints, radius rotating around ulna."},{"id": 8011,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which muscle is primarily responsible for 'clawing' when paralyzed (ulnar nerve palsy)?","options": [{"key": "A","text": "Both lumbricals and interossei of ring/little finger"},{"key": "B","text": "Flexor digitorum profundus"},{"key": "C","text": "Lumbricals (3rd and 4th)"},{"key": "D","text": "Interossei"}],"correct": "A","explanation": "Ulnar claw hand results from paralysis of medial lumbricals and interossei, leaving unopposed EDC and FDP action on ring/little fingers."},{"id": 8012,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "The 'annular ligament' of the elbow encircles the:","options": [{"key": "A","text": "Capitulum"},{"key": "B","text": "Head of radius"},{"key": "C","text": "Head of ulna"},{"key": "D","text": "Trochlea"}],"correct": "B","explanation": "Annular ligament wraps around and stabilizes the radial head at the proximal radioulnar joint."},{"id": 8013,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following is the primary dynamic stabilizer of the patellofemoral joint?","options": [{"key": "A","text": "Rectus femoris"},{"key": "B","text": "Vastus lateralis"},{"key": "C","text": "Sartorius"},{"key": "D","text": "Vastus medialis obliquus (VMO)"}],"correct": "D","explanation": "VMO counteracts lateral pull, stabilizing patellar tracking."},{"id": 8014,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The nutrient artery of a long bone typically enters through the:","options": [{"key": "A","text": "Epiphysis"},{"key": "B","text": "Metaphysis"},{"key": "C","text": "Articular cartilage"},{"key": "D","text": "Diaphysis obliquely"}],"correct": "D","explanation": "Nutrient artery pierces the shaft (diaphysis) obliquely and supplies the medullary cavity."},{"id": 8015,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which of the following joints permits circumduction but not axial rotation?","options": [{"key": "A","text": "Hip joint"},{"key": "B","text": "Ankle joint"},{"key": "C","text": "Shoulder joint"},{"key": "D","text": "Wrist joint (radiocarpal)"}],"correct": "D","explanation": "Wrist (condyloid/ellipsoid joint) allows flexion, extension, abduction, adduction, circumduction, but not true rotation."},{"id": 8016,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "The primary muscle responsible for terminal extension (last 10-15°) of the knee is:","options": [{"key": "A","text": "Sartorius"},{"key": "B","text": "Vastus lateralis"},{"key": "C","text": "Rectus femoris"},{"key": "D","text": "Vastus medialis obliquus"}],"correct": "D","explanation": "VMO is crucial for completing terminal knee extension and patellar stabilization."},{"id": 8017,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "According to Newton's first law, a body remains in its state of rest or uniform motion unless acted upon by:","options": [{"key": "A","text": "Gravity only"},{"key": "B","text": "An external unbalanced force"},{"key": "C","text": "Internal muscle force only"},{"key": "D","text": "Friction only"}],"correct": "B","explanation": "Law of inertia — external unbalanced force is required to change state of motion."},{"id": 8018,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'instantaneous center of rotation' of a joint refers to:","options": [{"key": "A","text": "Point of maximum torque"},{"key": "B","text": "Fixed axis for entire ROM"},{"key": "C","text": "Point that shifts throughout the arc of motion"},{"key": "D","text": "Center of mass of the bone"}],"correct": "C","explanation": "ICR changes moment to moment as the joint surfaces roll and glide."},{"id": 8019,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Roll, spin, and glide are types of:","options": [{"key": "A","text": "Isokinetic motion"},{"key": "B","text": "Osteokinematic motion"},{"key": "C","text": "Plyometric motion"},{"key": "D","text": "Arthrokinematic motion"}],"correct": "D","explanation": "Arthrokinematics describes motion between joint surfaces (roll, spin, glide, slide)."},{"id": 8020,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "In a convex-on-concave joint surface movement, the glide occurs:","options": [{"key": "A","text": "In the same direction as the bone movement"},{"key": "B","text": "No glide occurs"},{"key": "C","text": "Perpendicular to bone movement"},{"key": "D","text": "Opposite to the direction of bone movement"}],"correct": "D","explanation": "Convex-concave rule: convex moving on concave — roll and glide occur in opposite directions."},{"id": 8021,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "In a concave-on-convex joint surface movement, the glide occurs:","options": [{"key": "A","text": "Same direction as bone movement"},{"key": "B","text": "No relationship"},{"key": "C","text": "Always superior"},{"key": "D","text": "Opposite to bone movement"}],"correct": "A","explanation": "Concave-convex rule: concave moving on fixed convex — roll and glide occur in the same direction."},{"id": 8022,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The term 'kinetic chain' refers to:","options": [{"key": "A","text": "Series of linked joints/segments where movement at one affects others"},{"key": "B","text": "A single joint moving in isolation"},{"key": "C","text": "Muscle strength grading"},{"key": "D","text": "Only lower limb joints"}],"correct": "A","explanation": "Kinetic chain = linked segments; movement/force at one joint influences adjacent segments."},{"id": 8023,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "In a 'closed kinetic chain' exercise, the distal segment is:","options": [{"key": "A","text": "Non-weight bearing"},{"key": "B","text": "Free to move"},{"key": "C","text": "Irrelevant to chain"},{"key": "D","text": "Fixed against resistance/ground"}],"correct": "D","explanation": "CKC = distal segment fixed (e.g., squat), proximal segment moves."},{"id": 8024,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following is an example of an open kinetic chain exercise?","options": [{"key": "A","text": "Leg press"},{"key": "B","text": "Seated knee extension"},{"key": "C","text": "Push-up"},{"key": "D","text": "Squat"}],"correct": "B","explanation": "OKC = distal segment moves freely, e.g., seated knee extension."},{"id": 8025,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The 'moment of force' (torque) is the product of:","options": [{"key": "A","text": "Force and perpendicular distance from axis (lever arm)"},{"key": "B","text": "Mass and acceleration"},{"key": "C","text": "Force and time"},{"key": "D","text": "Force and mass"}],"correct": "A","explanation": "Torque = Force × perpendicular distance (moment arm) from axis of rotation."},{"id": 8026,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "A first-class lever has its fulcrum located:","options": [{"key": "A","text": "At one end, effort in middle"},{"key": "B","text": "At one end, resistance in middle"},{"key": "C","text": "Between effort and resistance"},{"key": "D","text": "Not applicable to human body"}],"correct": "C","explanation": "1st class lever: Fulcrum is between effort and resistance (e.g., atlanto-occipital joint in neck nodding)."},{"id": 8027,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "The human elbow joint (biceps flexing forearm) is an example of which class of lever?","options": [{"key": "A","text": "First class"},{"key": "B","text": "Fourth class"},{"key": "C","text": "Third class"},{"key": "D","text": "Second class"}],"correct": "C","explanation": "Third class lever: effort between fulcrum and resistance, common in limb muscles (mechanical disadvantage but speed advantage)."},{"id": 8028,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Center of gravity' of an average human standing upright is located approximately at:","options": [{"key": "A","text": "L5 vertebra"},{"key": "B","text": "T12 vertebra"},{"key": "C","text": "S2 vertebra (anterior to it)"},{"key": "D","text": "C7 vertebra"}],"correct": "C","explanation": "COG lies roughly anterior to the second sacral vertebra in standing posture."},{"id": 8029,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "A wider base of support generally results in:","options": [{"key": "A","text": "No change in stability"},{"key": "B","text": "Increased center of gravity height"},{"key": "C","text": "Increased stability"},{"key": "D","text": "Decreased stability"}],"correct": "C","explanation": "Wider BOS increases stability by increasing the area within which COG must project."},{"id": 8030,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Stability of a body is inversely proportional to:","options": [{"key": "A","text": "Base of support area"},{"key": "B","text": "Height of center of gravity"},{"key": "C","text": "Body weight"},{"key": "D","text": "Mass"}],"correct": "B","explanation": "Higher COG = lower stability; lower COG = greater stability."},{"id": 8031,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The term 'degrees of freedom' at a joint refers to:","options": [{"key": "A","text": "Number of muscles crossing it"},{"key": "B","text": "Number of independent movements possible (translation/rotation axes)"},{"key": "C","text": "Range of motion in degrees"},{"key": "D","text": "Number of ligaments"}],"correct": "B","explanation": "DOF = independent planes/axes of motion possible at a joint (max 6: 3 rotation + 3 translation)."},{"id": 8032,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which type of muscle contraction generates the greatest force?","options": [{"key": "A","text": "Isometric"},{"key": "B","text": "Isotonic"},{"key": "C","text": "Eccentric"},{"key": "D","text": "Concentric"}],"correct": "C","explanation": "Eccentric contractions produce the highest force output among contraction types."},{"id": 8033,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The length-tension relationship states that maximum active tension is produced when:","options": [{"key": "A","text": "Muscle is passive"},{"key": "B","text": "Sarcomere is maximally shortened"},{"key": "C","text": "Sarcomere is maximally stretched"},{"key": "D","text": "Sarcomere is at optimal resting length with maximum actin-myosin overlap"}],"correct": "D","explanation": "Optimal overlap of actin-myosin filaments at resting length produces peak active tension."},{"id": 8034,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The force-velocity relationship of muscle states that as velocity of shortening increases, force generation:","options": [{"key": "A","text": "Remains constant"},{"key": "B","text": "Becomes zero immediately"},{"key": "C","text": "Decreases"},{"key": "D","text": "Increases"}],"correct": "C","explanation": "Inverse relationship — force decreases as concentric shortening velocity increases."},{"id": 8035,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which of the following best defines 'stress' in biomechanics?","options": [{"key": "A","text": "Energy per unit mass"},{"key": "B","text": "Force per unit area"},{"key": "C","text": "Deformation per unit length"},{"key": "D","text": "Force per unit time"}],"correct": "B","explanation": "Stress = Force/Area."},{"id": 8036,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Strain' in biomechanics is defined as:","options": [{"key": "A","text": "Force per area"},{"key": "B","text": "Force applied"},{"key": "C","text": "Change in length / original length"},{"key": "D","text": "Rate of loading"}],"correct": "C","explanation": "Strain = deformation (ΔL) / original length (L)."},{"id": 8037,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'stress-strain curve' elastic region represents:","options": [{"key": "A","text": "Permanent deformation"},{"key": "B","text": "Reversible deformation (returns to original shape)"},{"key": "C","text": "Plastic deformation"},{"key": "D","text": "Fracture point"}],"correct": "B","explanation": "Elastic region = reversible; beyond yield point, plastic (permanent) deformation occurs."},{"id": 8038,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Creep' in connective tissue refers to:","options": [{"key": "A","text": "Progressive deformation under a constant sustained load over time"},{"key": "B","text": "Sudden failure under load"},{"key": "C","text": "Elastic recoil"},{"key": "D","text": "Immediate recovery"}],"correct": "A","explanation": "Creep = time-dependent deformation under constant load (viscoelastic property)."},{"id": 8039,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Viscoelasticity of connective tissue means the tissue's response depends on:","options": [{"key": "A","text": "Only magnitude of force"},{"key": "B","text": "Both magnitude and rate/time of loading"},{"key": "C","text": "Only muscle activity"},{"key": "D","text": "Only joint angle"}],"correct": "B","explanation": "Viscoelastic materials show time- and rate-dependent mechanical behavior."},{"id": 8040,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Which plane does flexion-extension of the knee occur in?","options": [{"key": "A","text": "Frontal (coronal) plane"},{"key": "B","text": "Oblique plane"},{"key": "C","text": "Sagittal plane"},{"key": "D","text": "Transverse plane"}],"correct": "C","explanation": "Flexion-extension occurs in sagittal plane around a coronal (mediolateral) axis."},{"id": 8041,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Internal-external rotation of the hip occurs in which plane?","options": [{"key": "A","text": "Oblique plane"},{"key": "B","text": "Frontal plane"},{"key": "C","text": "Sagittal plane"},{"key": "D","text": "Transverse (horizontal) plane"}],"correct": "D","explanation": "Rotational movements occur in the transverse plane around a vertical (longitudinal) axis."},{"id": 8042,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Newton's third law' (action-reaction) is best exemplified in gait by:","options": [{"key": "A","text": "Ground reaction force equal and opposite to force exerted by foot on ground"},{"key": "B","text": "Friction force only"},{"key": "C","text": "Momentum conservation"},{"key": "D","text": "Center of mass shift"}],"correct": "A","explanation": "Ground reaction force is equal and opposite to the force the foot applies to ground during stance."},{"id": 8043,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The term 'couple' in biomechanics refers to:","options": [{"key": "A","text": "Force and mass product"},{"key": "B","text": "Two equal, opposite, parallel forces producing pure rotation"},{"key": "C","text": "A single force with moment arm"},{"key": "D","text": "Two forces in the same direction"}],"correct": "B","explanation": "Force couple = two equal/opposite parallel (non-collinear) forces producing rotation without translation."},{"id": 8044,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Mechanical advantage' of a lever system is the ratio of:","options": [{"key": "A","text": "Effort to mass"},{"key": "B","text": "Resistance arm to effort arm"},{"key": "C","text": "Effort arm to resistance arm"},{"key": "D","text": "Resistance to time"}],"correct": "C","explanation": "MA = Effort arm length / Resistance arm length."},{"id": 8045,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which factor primarily determines the moment arm of a muscle at a joint?","options": [{"key": "A","text": "Perpendicular distance from muscle's line of pull to joint axis"},{"key": "B","text": "Muscle length only"},{"key": "C","text": "Muscle mass"},{"key": "D","text": "Muscle fiber type"}],"correct": "A","explanation": "Moment arm = perpendicular distance between muscle's line of action and the joint's axis of rotation."},{"id": 8046,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Ground reaction force' during normal walking typically shows how many peaks in the vertical component?","options": [{"key": "A","text": "Three peaks"},{"key": "B","text": "One peak"},{"key": "C","text": "Two peaks (M-shaped curve)"},{"key": "D","text": "No consistent pattern"}],"correct": "C","explanation": "Vertical GRF curve is classically M-shaped with two peaks (loading response and push-off) and a mid-stance dip."},{"id": 8047,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following describes 'angular velocity'?","options": [{"key": "A","text": "Torque per mass"},{"key": "B","text": "Force per time"},{"key": "C","text": "Rate of change of linear displacement"},{"key": "D","text": "Rate of change of angular displacement"}],"correct": "D","explanation": "Angular velocity = rate of change of angular displacement over time."},{"id": 8048,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "In the sagittal plane, the axis of motion for flexion-extension passes in which direction?","options": [{"key": "A","text": "Vertical (longitudinal)"},{"key": "B","text": "Oblique"},{"key": "C","text": "Anteroposterior"},{"key": "D","text": "Mediolateral"}],"correct": "D","explanation": "Sagittal plane motions rotate about a mediolateral (coronal) axis."},{"id": 8049,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Muscle synergy' refers to:","options": [{"key": "A","text": "A single muscle acting alone"},{"key": "B","text": "Passive muscle stretch"},{"key": "C","text": "Antagonist muscle inhibition only"},{"key": "D","text": "Coordinated action of multiple muscles working together for a movement"}],"correct": "D","explanation": "Synergists work together, sometimes stabilizing to allow prime movers to act efficiently."},{"id": 8050,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "An 'agonist' muscle is best described as:","options": [{"key": "A","text": "Antagonist's helper"},{"key": "B","text": "Prime mover producing the desired movement"},{"key": "C","text": "Stabilizer only"},{"key": "D","text": "Muscle opposing the movement"}],"correct": "B","explanation": "Agonist = prime mover directly responsible for producing a given movement."},{"id": 8051,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Passive insufficiency' of a two-joint muscle occurs when:","options": [{"key": "A","text": "Muscle is fully relaxed only"},{"key": "B","text": "Muscle length is optimal"},{"key": "C","text": "Muscle is actively contracting maximally"},{"key": "D","text": "Muscle is stretched over both joints simultaneously, limiting further stretch/ROM"}],"correct": "D","explanation": "Passive insufficiency: a two-joint muscle cannot stretch enough to allow full ROM at both joints simultaneously (e.g., hamstrings limiting SLR with knee extended and hip flexed)."},{"id": 8052,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Active insufficiency' refers to:","options": [{"key": "A","text": "Joint hypermobility"},{"key": "B","text": "Inability of a shortened two-joint muscle to generate further useful tension"},{"key": "C","text": "Excess muscle stretch"},{"key": "D","text": "Ligament laxity"}],"correct": "B","explanation": "Active insufficiency: muscle shortened over both joints cannot generate additional effective tension (e.g., finger flexors weak when wrist is also flexed)."},{"id": 8053,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which of the following best defines 'work' in biomechanics?","options": [{"key": "A","text": "Mass × acceleration"},{"key": "B","text": "Force × distance moved in direction of force"},{"key": "C","text": "Force/area"},{"key": "D","text": "Force × time"}],"correct": "B","explanation": "Work = Force × displacement (in direction of force applied)."},{"id": 8054,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Power' in biomechanical terms is defined as:","options": [{"key": "A","text": "Force × area"},{"key": "B","text": "Force × distance"},{"key": "C","text": "Mass × velocity"},{"key": "D","text": "Work done per unit time"}],"correct": "D","explanation": "Power = Work/Time, or Force × velocity."},{"id": 8055,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which posture is characterized by increased thoracic kyphosis, forward head, and rounded shoulders?","options": [{"key": "A","text": "Military posture"},{"key": "B","text": "Flat back posture"},{"key": "C","text": "Kyphotic-lordotic posture"},{"key": "D","text": "Sway back posture"}],"correct": "C","explanation": "Kyphotic-lordotic posture: increased thoracic kyphosis with compensatory lumbar lordosis and forward head."},{"id": 8056,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "In 'sway back' posture, the pelvis is:","options": [{"key": "A","text": "Neutral"},{"key": "B","text": "Laterally tilted"},{"key": "C","text": "Posteriorly tilted with hip extended and shifted forward"},{"key": "D","text": "Anteriorly tilted"}],"correct": "C","explanation": "Sway back: posterior pelvic tilt, hip joint shifted anterior to the gravity line, flat lumbar with increased thoracic kyphosis."},{"id": 8057,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Normal value of goniometric measurement for knee flexion is approximately:","options": [{"key": "A","text": "120°"},{"key": "B","text": "135-140°"},{"key": "C","text": "160°"},{"key": "D","text": "90°"}],"correct": "B","explanation": "Normal active knee flexion range is about 135-140°."},{"id": 8058,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The 'universal goniometer' axis is aligned with:","options": [{"key": "A","text": "Bone shaft only"},{"key": "B","text": "Joint's axis of rotation"},{"key": "C","text": "Muscle belly"},{"key": "D","text": "Skin crease always"}],"correct": "B","explanation": "Goniometer fulcrum is placed over the estimated joint axis of rotation."},{"id": 8059,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Grade '3' (Fair) in Manual Muscle Testing (MMT - Oxford scale) indicates:","options": [{"key": "A","text": "Full ROM with gravity eliminated"},{"key": "B","text": "Full ROM against gravity, no resistance"},{"key": "C","text": "No contraction"},{"key": "D","text": "Full ROM against gravity and moderate resistance"}],"correct": "B","explanation": "Grade 3 (Fair) = complete ROM against gravity without added manual resistance."},{"id": 8060,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "MMT Grade 2 (Poor) is tested in which position?","options": [{"key": "A","text": "Against gravity"},{"key": "B","text": "Gravity eliminated (horizontal plane)"},{"key": "C","text": "Cannot be tested"},{"key": "D","text": "Against maximum resistance"}],"correct": "B","explanation": "Grade 2 = full ROM achieved with gravity eliminated."},{"id": 8061,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "MMT Grade 1 (Trace) indicates:","options": [{"key": "A","text": "Full ROM against gravity"},{"key": "B","text": "Palpable/visible contraction, no joint motion"},{"key": "C","text": "No palpable contraction"},{"key": "D","text": "Partial ROM against gravity"}],"correct": "B","explanation": "Grade 1 = flicker or trace of contraction, no visible joint movement."},{"id": 8062,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Antalgic gait' is characterized by:","options": [{"key": "A","text": "Shortened stance phase on painful limb to avoid weight bearing"},{"key": "B","text": "Absent swing phase"},{"key": "C","text": "Circumduction"},{"key": "D","text": "Prolonged stance phase on painful limb"}],"correct": "A","explanation": "Antalgic gait: patient minimizes time on the painful limb, shortening stance phase on that side."},{"id": 8063,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Trendelenburg gait' results from weakness of:","options": [{"key": "A","text": "Gastrocnemius"},{"key": "B","text": "Tibialis anterior"},{"key": "C","text": "Quadriceps"},{"key": "D","text": "Gluteus medius/minimus"}],"correct": "D","explanation": "Weak hip abductors cause pelvic drop on the swing side (contralateral) during stance."},{"id": 8064,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "'Steppage gait' (foot drop gait) results from weakness of:","options": [{"key": "A","text": "Hip flexors"},{"key": "B","text": "Quadriceps"},{"key": "C","text": "Plantarflexors"},{"key": "D","text": "Dorsiflexors (tibialis anterior)"}],"correct": "D","explanation": "Weak dorsiflexors cause foot drop; patient lifts knee higher to clear the foot (steppage)."},{"id": 8065,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Circumduction gait' is commonly compensatory for:","options": [{"key": "A","text": "Weak gluteus maximus only"},{"key": "B","text": "Weak plantarflexors"},{"key": "C","text": "Weak hip flexors or limited knee flexion causing difficulty clearing foot"},{"key": "D","text": "Hyperextended knee"}],"correct": "C","explanation": "Patient swings the leg outward in a circular arc to clear the foot when hip flexion/knee flexion is limited."},{"id": 8066,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Normal cadence in adults during walking is approximately:","options": [{"key": "A","text": "200 steps/min"},{"key": "B","text": "150-160 steps/min"},{"key": "C","text": "90-120 steps/min"},{"key": "D","text": "50-60 steps/min"}],"correct": "C","explanation": "Average adult cadence is about 90-120 steps per minute (~110-120 typical)."},{"id": 8067,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'stance phase' constitutes approximately what percentage of the gait cycle?","options": [{"key": "A","text": "50%"},{"key": "B","text": "70%"},{"key": "C","text": "40%"},{"key": "D","text": "60%"}],"correct": "D","explanation": "Stance phase = ~60% of gait cycle; swing phase = ~40%."},{"id": 8068,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Double support' phase occurs:","options": [{"key": "A","text": "Only during running"},{"key": "B","text": "Never in normal walking"},{"key": "C","text": "Only once per gait cycle"},{"key": "D","text": "Twice per gait cycle, both feet on ground"}],"correct": "D","explanation": "Double support occurs twice per cycle when both feet contact ground simultaneously (absent in running)."},{"id": 8069,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Which muscle is primarily active (eccentrically) during the loading response of gait to control knee flexion?","options": [{"key": "A","text": "Tibialis posterior"},{"key": "B","text": "Quadriceps"},{"key": "C","text": "Hamstrings"},{"key": "D","text": "Gastrocnemius"}],"correct": "B","explanation": "Quadriceps contracts eccentrically at loading response to control the small knee flexion wave."},{"id": 8070,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The Modified Ashworth Scale is used to assess:","options": [{"key": "A","text": "Muscle strength"},{"key": "B","text": "Balance"},{"key": "C","text": "Joint ROM"},{"key": "D","text": "Spasticity/tone"}],"correct": "D","explanation": "MAS grades resistance to passive stretch, i.e., spasticity."},{"id": 8071,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which test is used to assess balance and fall risk in elderly?","options": [{"key": "A","text": "MMT"},{"key": "B","text": "Berg Balance Scale"},{"key": "C","text": "Ashworth scale"},{"key": "D","text": "Ober's test"}],"correct": "B","explanation": "Berg Balance Scale is a validated tool assessing functional balance and fall risk."},{"id": 8072,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Timed Up and Go' (TUG) test primarily assesses:","options": [{"key": "A","text": "Functional mobility and fall risk"},{"key": "B","text": "Upper limb coordination"},{"key": "C","text": "Muscle power only"},{"key": "D","text": "Pain intensity"}],"correct": "A","explanation": "TUG measures time to rise from chair, walk 3m, turn, return, and sit — a mobility/fall-risk screen."},{"id": 8073,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Normal shoulder flexion range (goniometric) is approximately:","options": [{"key": "A","text": "90°"},{"key": "B","text": "120°"},{"key": "C","text": "160-180°"},{"key": "D","text": "200°"}],"correct": "C","explanation": "Normal shoulder flexion ROM is about 160-180°."},{"id": 8074,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Normal range for hip flexion (with knee flexed) is approximately:","options": [{"key": "A","text": "120-125°"},{"key": "B","text": "180°"},{"key": "C","text": "90°"},{"key": "D","text": "150°"}],"correct": "A","explanation": "Normal hip flexion with knee bent is about 120-125°."},{"id": 8075,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Leg length discrepancy' is best measured using which two landmarks (true LLD)?","options": [{"key": "A","text": "Iliac crest to knee joint line"},{"key": "B","text": "ASIS to lateral malleolus"},{"key": "C","text": "Xiphisternum to ASIS"},{"key": "D","text": "Umbilicus to medial malleolus"}],"correct": "B","explanation": "True (real) leg length: ASIS to ipsilateral medial malleolus (some texts use lateral malleolus)."},{"id": 8076,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Apparent leg length' is measured from:","options": [{"key": "A","text": "Greater trochanter to lateral malleolus"},{"key": "B","text": "Iliac crest to lateral malleolus"},{"key": "C","text": "Umbilicus (or xiphisternum) to medial malleolus"},{"key": "D","text": "ASIS to medial malleolus"}],"correct": "C","explanation": "Apparent LLD is measured from a fixed midline point (umbilicus/xiphisternum) to malleolus, affected by pelvic obliquity."},{"id": 8077,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "MMT grade 4 (Good) is defined as:","options": [{"key": "A","text": "Gravity eliminated full ROM"},{"key": "B","text": "Full ROM against gravity, no resistance"},{"key": "C","text": "Trace contraction only"},{"key": "D","text": "Full ROM against gravity with moderate resistance"}],"correct": "D","explanation": "Grade 4 = complete ROM against gravity and moderate manual resistance."},{"id": 8078,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which observation method is used to assess scoliosis clinically?","options": [{"key": "A","text": "Thomas test"},{"key": "B","text": "Adam's forward bend test"},{"key": "C","text": "Trendelenburg test"},{"key": "D","text": "Ober's test"}],"correct": "B","explanation": "Adam's forward bend test reveals rib hump/paraspinal asymmetry suggestive of scoliosis."},{"id": 8079,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Genu valgum' refers to:","options": [{"key": "A","text": "Flexed knee deformity"},{"key": "B","text": "Knock knees"},{"key": "C","text": "Bow legs"},{"key": "D","text": "Hyperextended knee"}],"correct": "B","explanation": "Genu valgum = knock-knee deformity, tibia angled laterally relative to femur."},{"id": 8080,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Genu varum' refers to:","options": [{"key": "A","text": "High arched feet"},{"key": "B","text": "Flat feet"},{"key": "C","text": "Knock knees"},{"key": "D","text": "Bow legs"}],"correct": "D","explanation": "Genu varum = bow-leg deformity."},{"id": 8081,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which test assesses tightness of the iliotibial band?","options": [{"key": "A","text": "Thomas test"},{"key": "B","text": "FABER test"},{"key": "C","text": "Ober's test"},{"key": "D","text": "Ely's test"}],"correct": "C","explanation": "Ober's test specifically assesses ITB tightness."},{"id": 8082,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Thomas test is primarily used to assess:","options": [{"key": "A","text": "Quadriceps strength"},{"key": "B","text": "Hamstring tightness"},{"key": "C","text": "Hip flexor tightness"},{"key": "D","text": "ITB tightness"}],"correct": "C","explanation": "Thomas test detects hip flexor (iliopsoas/rectus femoris) contracture."},{"id": 8083,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "Ely's test assesses tightness of which muscle?","options": [{"key": "A","text": "Hamstrings"},{"key": "B","text": "Rectus femoris"},{"key": "C","text": "Piriformis"},{"key": "D","text": "Gluteus maximus"}],"correct": "B","explanation": "Ely's test (prone knee flexion causing hip to lift) indicates rectus femoris tightness."},{"id": 8084,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Normal ankle dorsiflexion ROM (with knee extended) is approximately:","options": [{"key": "A","text": "0-10°"},{"key": "B","text": "50°"},{"key": "C","text": "40-45°"},{"key": "D","text": "20-30°"}],"correct": "A","explanation": "Normal ankle dorsiflexion is approximately 0-10° (up to 20° with knee flexed)."},{"id": 8085,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which grade of MMT corresponds to '0' on the standard scale?","options": [{"key": "A","text": "Fair against gravity"},{"key": "B","text": "Trace contraction"},{"key": "C","text": "Poor with gravity eliminated"},{"key": "D","text": "No contraction visible/palpable"}],"correct": "D","explanation": "Grade 0 = no palpable or visible muscle contraction."},{"id": 8086,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Functional Reach Test' primarily measures:","options": [{"key": "A","text": "Dynamic balance (forward reach limits)"},{"key": "B","text": "Muscle strength"},{"key": "C","text": "Joint ROM"},{"key": "D","text": "Pain threshold"}],"correct": "A","explanation": "FRT measures the maximum distance one can reach forward beyond arm's length while maintaining a fixed base of support — a balance measure."},{"id": 8087,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Which posture shows flattening of both thoracic kyphosis and lumbar lordosis?","options": [{"key": "A","text": "Military posture"},{"key": "B","text": "Kyphotic-lordotic posture"},{"key": "C","text": "Sway back posture"},{"key": "D","text": "Flat back posture"}],"correct": "D","explanation": "Flat back posture: reduced lumbar lordosis and often reduced thoracic kyphosis, posterior pelvic tilt."},{"id": 8088,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Normal shoulder abduction ROM is approximately:","options": [{"key": "A","text": "120°"},{"key": "B","text": "200°"},{"key": "C","text": "180°"},{"key": "D","text": "90°"}],"correct": "C","explanation": "Full shoulder abduction is approximately 180°."},{"id": 8089,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Pronator drift test' is used to assess:","options": [{"key": "A","text": "Cerebellar function"},{"key": "B","text": "Upper motor neuron weakness"},{"key": "C","text": "Joint stability"},{"key": "D","text": "Peripheral nerve sensation"}],"correct": "B","explanation": "Pronator drift indicates subtle upper motor neuron (pyramidal) weakness."},{"id": 8090,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Manual muscle testing position for gluteus maximus is typically:","options": [{"key": "A","text": "Side-lying"},{"key": "B","text": "Standing"},{"key": "C","text": "Prone with knee flexed to 90°, hip extension tested"},{"key": "D","text": "Supine"}],"correct": "C","explanation": "Gluteus maximus MMT: prone, knee flexed to relax hamstring assistance, resist hip extension."},{"id": 8091,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which test evaluates hamstring flexibility functionally?","options": [{"key": "A","text": "Ober's test"},{"key": "B","text": "FABER test"},{"key": "C","text": "Thomas test"},{"key": "D","text": "Straight Leg Raise (SLR) test / Popliteal angle test"}],"correct": "D","explanation": "SLR / 90-90 popliteal angle test assesses hamstring length/flexibility."},{"id": 8092,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Functional gait assessment' items typically include walking with:","options": [{"key": "A","text": "Eyes closed and head turns"},{"key": "B","text": "Only forward walking"},{"key": "C","text": "Static standing"},{"key": "D","text": "Sitting balance only"}],"correct": "A","explanation": "FGA includes tasks like walking with eyes closed, head turns, over obstacles etc., testing dynamic balance during gait."},{"id": 8093,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "During normal gait, the 'toe-off' event occurs at the end of:","options": [{"key": "A","text": "Loading response"},{"key": "B","text": "Terminal stance"},{"key": "C","text": "Mid-swing"},{"key": "D","text": "Initial contact"}],"correct": "B","explanation": "Toe-off marks the end of terminal stance / start of pre-swing."},{"id": 8094,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "Which structure's contracture leads to a positive Thomas test result?","options": [{"key": "A","text": "Iliopsoas and/or rectus femoris"},{"key": "B","text": "Gastrocnemius"},{"key": "C","text": "Hamstrings"},{"key": "D","text": "Piriformis only"}],"correct": "A","explanation": "Inability to keep the opposite leg flat (hip flexes off table) indicates hip flexor tightness."},{"id": 8095,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Normal elbow flexion ROM is approximately:","options": [{"key": "A","text": "90°"},{"key": "B","text": "180°"},{"key": "C","text": "145-150°"},{"key": "D","text": "110°"}],"correct": "C","explanation": "Normal active elbow flexion is about 145-150°."},{"id": 8096,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'FABER test' (Patrick's test) is used to screen for pathology of:","options": [{"key": "A","text": "Shoulder"},{"key": "B","text": "Hip and sacroiliac joint"},{"key": "C","text": "Knee only"},{"key": "D","text": "Ankle"}],"correct": "B","explanation": "FABER (Flexion-ABduction-External Rotation) screens hip and SIJ pathology."},{"id": 8097,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "During assessment of posture from lateral view, the plumb line normally passes through all EXCEPT:","options": [{"key": "A","text": "Anterior to shoulder joint"},{"key": "B","text": "Slightly anterior to lateral malleolus"},{"key": "C","text": "Lobule of ear"},{"key": "D","text": "Bodies of most cervical/lumbar vertebrae"}],"correct": "A","explanation": "Plumb line normally passes slightly posterior/through the shoulder joint, not distinctly anterior to it."},{"id": 8098,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Ober's test' is performed in which patient position?","options": [{"key": "A","text": "Supine"},{"key": "B","text": "Side-lying with hip abducted then lowered"},{"key": "C","text": "Prone"},{"key": "D","text": "Standing"}],"correct": "B","explanation": "Ober's test: side-lying, hip abducted and extended, then allowed to adduct — limited adduction suggests ITB tightness."},{"id": 8099,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Grading of Manual Muscle Testing was originally developed and popularized by:","options": [{"key": "A","text": "Maitland"},{"key": "B","text": "Kaltenborn"},{"key": "C","text": "Cyriax"},{"key": "D","text": "Kendall and Kendall / Lovett scale origin"}],"correct": "D","explanation": "MMT grading (0-5 scale) traces to the Lovett scale, further developed by Kendall and Kendall among others."},{"id": 8100,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following gait deviations is seen with weak quadriceps?","options": [{"key": "A","text": "Excessive knee flexion in stance"},{"key": "B","text": "Genu recurvatum / back-knee thrust during stance"},{"key": "C","text": "Foot slap"},{"key": "D","text": "Vaulting"}],"correct": "B","explanation": "Weak quadriceps often leads to compensatory hyperextension (back-knee) thrust to stabilize the knee during stance."},{"id": 8101,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "'Foot slap' during loading response is due to weakness of:","options": [{"key": "A","text": "Hip extensors"},{"key": "B","text": "Quadriceps"},{"key": "C","text": "Plantarflexors"},{"key": "D","text": "Dorsiflexors (eccentric control)"}],"correct": "D","explanation": "Weak dorsiflexors fail to control the foot eccentrically after heel strike, causing audible foot slap."},{"id": 8102,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Vaulting gait' is a compensation typically for:","options": [{"key": "A","text": "Weak hip abductors"},{"key": "B","text": "Leg length discrepancy (longer limb) or stiff prosthesis/limb"},{"key": "C","text": "Weak quadriceps"},{"key": "D","text": "Weak dorsiflexors"}],"correct": "B","explanation": "Patient rises on the toes of the stance limb to allow clearance of a functionally longer contralateral limb during swing."},{"id": 8103,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "'Goniometry' end-feel for normal elbow extension is:","options": [{"key": "A","text": "Hard/bony (olecranon in fossa)"},{"key": "B","text": "Soft"},{"key": "C","text": "Empty"},{"key": "D","text": "Firm (capsular)"}],"correct": "A","explanation": "Normal elbow extension end-feel is bony/hard due to olecranon process engaging the olecranon fossa."},{"id": 8104,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Empty end-feel' during passive ROM assessment usually indicates:","options": [{"key": "A","text": "Normal joint"},{"key": "B","text": "Muscle spasm only"},{"key": "C","text": "Pain limiting movement before tissue resistance is felt (e.g., acute bursitis, fracture)"},{"key": "D","text": "Capsular tightness"}],"correct": "C","explanation": "Empty end-feel = movement stopped by pain before any true mechanical resistance, often pathological (bursitis, abscess, fracture, tumor)."},{"id": 8105,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following is considered an abnormal (pathological) end-feel?","options": [{"key": "A","text": "Bony (elbow extension)"},{"key": "B","text": "Springy block (meniscus tear blocking extension)"},{"key": "C","text": "Capsular (hip rotation)"},{"key": "D","text": "Soft tissue approximation (knee flexion)"}],"correct": "B","explanation": "Springy block end-feel (rebound) is pathological, e.g., due to a loose body or torn meniscus blocking full extension."},{"id": 8106,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "'Capsular pattern' of the hip joint (limitation order) is classically:","options": [{"key": "A","text": "Extension most limited"},{"key": "B","text": "Flexion, abduction, medial rotation limited most; extension least"},{"key": "C","text": "Lateral rotation most limited"},{"key": "D","text": "Flexion > abduction > medial rotation"}],"correct": "B","explanation": "Cyriax capsular pattern of hip: gross limitation of flexion, abduction, and medial rotation, with little/no limitation of extension and lateral rotation."},{"id": 8107,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Capsular pattern of the shoulder (glenohumeral) joint is:","options": [{"key": "A","text": "Equal limitation in all directions"},{"key": "B","text": "Flexion most limited"},{"key": "C","text": "Lateral rotation most limited, then abduction, then medial rotation"},{"key": "D","text": "Extension most limited"}],"correct": "C","explanation": "Shoulder capsular pattern: external (lateral) rotation most limited > abduction > internal (medial) rotation."},{"id": 8108,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Capsular pattern of the knee joint is:","options": [{"key": "A","text": "No consistent pattern"},{"key": "B","text": "Flexion more limited than extension"},{"key": "C","text": "Equal limitation of flexion and extension"},{"key": "D","text": "Extension more limited than flexion, with limited flexion too"}],"correct": "D","explanation": "Knee capsular pattern: flexion is grossly limited, extension slightly limited."},{"id": 8109,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Non-capsular pattern' of restriction suggests:","options": [{"key": "A","text": "Always muscular tightness"},{"key": "B","text": "Normal joint"},{"key": "C","text": "Arthritis/capsulitis"},{"key": "D","text": "Internal derangement e.g. ligament/meniscus lesion, loose body"}],"correct": "D","explanation": "Non-capsular pattern (not following typical proportion) suggests internal derangement rather than generalized capsulitis/arthritis."},{"id": 8110,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Selective Tissue Tension' testing (Cyriax approach) differentiates contractile vs inert tissue lesion mainly by:","options": [{"key": "A","text": "Combination of active, passive, and resisted movements"},{"key": "B","text": "Passive movement only"},{"key": "C","text": "X-ray findings"},{"key": "D","text": "Active movement only"}],"correct": "A","explanation": "Cyriax's approach uses active (willingness+ROM), passive (inert tissue+ROM/end feel), and resisted tests (contractile tissue) to localize the lesion."},{"id": 8111,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pain on resisted movement with full painless passive and active ROM suggests lesion in:","options": [{"key": "A","text": "Ligament"},{"key": "B","text": "Joint capsule"},{"key": "C","text": "Bone"},{"key": "D","text": "Contractile tissue (muscle/tendon)"}],"correct": "D","explanation": "Resisted (isometric) test isolates contractile tissue — pain here with normal passive ROM suggests muscle/tendon lesion."},{"id": 8112,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pain and limitation on both active AND passive movement in the same direction suggests lesion in:","options": [{"key": "A","text": "Skin"},{"key": "B","text": "Nerve root only"},{"key": "C","text": "Inert tissue (capsule/ligament)"},{"key": "D","text": "Contractile tissue only"}],"correct": "C","explanation": "Concordant limitation on both active and passive movement (non-contractile) points to inert (capsulo-ligamentous) tissue."},{"id": 8113,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Hard","question": "During gait analysis, 'initial contact' typically occurs with which part of the foot in normal gait?","options": [{"key": "A","text": "Heel"},{"key": "B","text": "Forefoot"},{"key": "C","text": "Lateral border only"},{"key": "D","text": "Midfoot flat"}],"correct": "A","explanation": "Normal gait initial contact is via the heel (heel strike)."},{"id": 8114,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Base of support' during normal walking is approximately:","options": [{"key": "A","text": "0 cm (feet cross midline)"},{"key": "B","text": "15-20 cm"},{"key": "C","text": "25-30 cm"},{"key": "D","text": "5-10 cm"}],"correct": "D","explanation": "Normal step width (base of support) during gait is about 5-10 cm."},{"id": 8115,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Normal cervical spine rotation ROM (each side) is approximately:","options": [{"key": "A","text": "45°"},{"key": "B","text": "60-80°"},{"key": "C","text": "30°"},{"key": "D","text": "90°"}],"correct": "B","explanation": "Normal active cervical rotation is roughly 60-80° each side."},{"id": 8116,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Which special test position is used for assessing lumbar spine flexion using a modified Schober's technique?","options": [{"key": "A","text": "Mark 10cm above and 5cm below the lumbosacral junction, measure increase on flexion"},{"key": "B","text": "Measure finger to floor only"},{"key": "C","text": "Mark only at L1"},{"key": "D","text": "Mark at iliac crest only"}],"correct": "A","explanation": "Modified Schober's test marks 10 cm above and 5 cm below the lumbosacral junction (PSIS level); increase >5cm on flexion is considered normal mobility."},{"id": 8117,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'Finger to floor test' primarily measures:","options": [{"key": "A","text": "Only hamstring length"},{"key": "B","text": "Only hip flexor length"},{"key": "C","text": "Isolated lumbar flexion"},{"key": "D","text": "Combined hip and lumbar spine flexion (functional)"}],"correct": "D","explanation": "Finger-floor distance reflects combined lumbar and hip flexion, not isolated spinal movement."},{"id": 8118,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "MMT testing of the middle trapezius is performed in which position?","options": [{"key": "A","text": "Standing, arms overhead"},{"key": "B","text": "Sitting"},{"key": "C","text": "Supine"},{"key": "D","text": "Prone, arm abducted to 90° with external rotation (thumb up), scapular retraction resisted"}],"correct": "D","explanation": "Middle trapezius MMT: prone, shoulder abducted 90°, externally rotated, resist horizontal scapular retraction."},{"id": 8119,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Serratus anterior' MMT is best tested through resisted:","options": [{"key": "A","text": "Push-up plus / protraction with arm forward flexed"},{"key": "B","text": "Scapular downward rotation"},{"key": "C","text": "Scapular retraction"},{"key": "D","text": "Scapular elevation"}],"correct": "A","explanation": "Serratus anterior MMT: resisted forward punch/protraction (wall push-up plus) tests its strength; weakness causes winging."},{"id": 8120,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Which nerve root is primarily tested by resisted shoulder abduction (deltoid) during a quick myotome screen?","options": [{"key": "A","text": "C5"},{"key": "B","text": "C7"},{"key": "C","text": "C4"},{"key": "D","text": "T1"}],"correct": "A","explanation": "C5 myotome corresponds largely to shoulder abduction (deltoid)."},{"id": 8121,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Resisted elbow flexion is used to screen which cervical myotome?","options": [{"key": "A","text": "T1"},{"key": "B","text": "C5-C6"},{"key": "C","text": "C8"},{"key": "D","text": "C7"}],"correct": "B","explanation": "Elbow flexors (biceps) reflect C5-C6 myotome."},{"id": 8122,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Resisted wrist extension tests which nerve root myotome?","options": [{"key": "A","text": "C8"},{"key": "B","text": "C5"},{"key": "C","text": "C6"},{"key": "D","text": "C7"}],"correct": "C","explanation": "Wrist extension corresponds to C6 myotome (radial nerve)."},{"id": 8123,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "Resisted elbow extension (triceps) primarily tests which myotome?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C6"},{"key": "C","text": "T1"},{"key": "D","text": "C8"}],"correct": "A","explanation": "Elbow extension/triceps corresponds to C7 myotome."},{"id": 8124,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "Resisted finger abduction (small hand muscles) tests which myotome?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C8"},{"key": "C","text": "T1"},{"key": "D","text": "T2"}],"correct": "C","explanation": "Finger abduction/adduction (intrinsics) corresponds to T1 myotome."},{"id": 8125,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Resisted great toe extension (EHL) tests which lumbar myotome?","options": [{"key": "A","text": "L4"},{"key": "B","text": "L5"},{"key": "C","text": "L3"},{"key": "D","text": "S1"}],"correct": "B","explanation": "Great toe extension corresponds to L5 myotome."},{"id": 8126,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Resisted ankle plantarflexion / heel walking difficulty suggests which nerve root involvement?","options": [{"key": "A","text": "S1"},{"key": "B","text": "S2"},{"key": "C","text": "L4"},{"key": "D","text": "L5"}],"correct": "A","explanation": "Plantarflexors (gastrocsoleus) correspond to S1 myotome; heel raise weakness suggests S1 radiculopathy."},{"id": 8127,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Resisted knee extension (quadriceps) primarily tests which myotome?","options": [{"key": "A","text": "L5"},{"key": "B","text": "S1"},{"key": "C","text": "L3-L4"},{"key": "D","text": "L2"}],"correct": "C","explanation": "Knee extension corresponds mainly to L3-L4 myotome."},{"id": 8128,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Resisted hip flexion tests which lumbar myotome primarily?","options": [{"key": "A","text": "L1-L2"},{"key": "B","text": "L4"},{"key": "C","text": "S1"},{"key": "D","text": "L5"}],"correct": "A","explanation": "Hip flexion (iliopsoas) reflects L1-L2 myotomes primarily."},{"id": 8129,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "Resisted ankle dorsiflexion (tibialis anterior) tests which myotome?","options": [{"key": "A","text": "L3"},{"key": "B","text": "S2"},{"key": "C","text": "L5"},{"key": "D","text": "L4"}],"correct": "D","explanation": "Ankle dorsiflexion corresponds primarily to L4 myotome."},{"id": 8130,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "'Dermatome' mapping for the lateral aspect of the leg and dorsum of foot corresponds to which nerve root?","options": [{"key": "A","text": "S2"},{"key": "B","text": "S1"},{"key": "C","text": "L5"},{"key": "D","text": "L4"}],"correct": "C","explanation": "L5 dermatome covers lateral leg and dorsum of foot including big toe."},{"id": 8131,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Deep tendon reflex - biceps reflex assesses which nerve root?","options": [{"key": "A","text": "T1"},{"key": "B","text": "C8"},{"key": "C","text": "C5-C6"},{"key": "D","text": "C7"}],"correct": "C","explanation": "Biceps reflex corresponds to C5-C6 nerve roots."},{"id": 8132,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Triceps deep tendon reflex assesses which nerve root?","options": [{"key": "A","text": "T1"},{"key": "B","text": "C8"},{"key": "C","text": "C6"},{"key": "D","text": "C7"}],"correct": "D","explanation": "Triceps reflex corresponds mainly to C7 nerve root."},{"id": 8133,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Knee jerk (patellar) reflex assesses which nerve root?","options": [{"key": "A","text": "L3-L4"},{"key": "B","text": "L2-L3"},{"key": "C","text": "S1"},{"key": "D","text": "L5"}],"correct": "A","explanation": "Patellar reflex corresponds to L3-L4 nerve roots."},{"id": 8134,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "Ankle jerk reflex assesses which nerve root?","options": [{"key": "A","text": "S1-S2"},{"key": "B","text": "S3"},{"key": "C","text": "L4"},{"key": "D","text": "L5"}],"correct": "A","explanation": "Ankle (Achilles) reflex corresponds to S1-S2 nerve roots."},{"id": 8135,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "'Babinski sign' positive (extensor plantar response) indicates:","options": [{"key": "A","text": "Peripheral nerve injury only"},{"key": "B","text": "Upper motor neuron lesion"},{"key": "C","text": "Lower motor neuron lesion only"},{"key": "D","text": "Normal in adults"}],"correct": "B","explanation": "Positive Babinski (great toe extension, fanning of other toes) indicates upper motor neuron pathology in adults."},{"id": 8136,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which grading scale is commonly used to document deep tendon reflex intensity?","options": [{"key": "A","text": "MMT scale"},{"key": "B","text": "Ashworth scale"},{"key": "C","text": "0 to 4+ scale"},{"key": "D","text": "Borg scale"}],"correct": "C","explanation": "DTRs are typically graded 0 (absent) to 4+ (hyperreflexia with clonus)."},{"id": 8137,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Neer's impingement test' is positive when pain occurs during:","options": [{"key": "A","text": "Passive extension"},{"key": "B","text": "Resisted abduction"},{"key": "C","text": "Resisted internal rotation"},{"key": "D","text": "Passive shoulder flexion with forced internal rotation and scapula stabilized"}],"correct": "D","explanation": "Neer's test: passive forward flexion with internal rotation impinges greater tuberosity against acromion."},{"id": 8138,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Hawkins-Kennedy test' is performed by:","options": [{"key": "A","text": "Empty can position resisted"},{"key": "B","text": "Shoulder flexed to 90°, elbow flexed 90°, then forced internal rotation"},{"key": "C","text": "Arm behind back"},{"key": "D","text": "Shoulder abducted and externally rotated"}],"correct": "B","explanation": "Hawkins-Kennedy: 90° shoulder/elbow flexion with forced internal rotation, provoking subacromial impingement."},{"id": 8139,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Empty can test' (Jobe's test) primarily assesses:","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Supraspinatus"},{"key": "C","text": "Teres minor"},{"key": "D","text": "Infraspinatus"}],"correct": "B","explanation": "Empty can test isolates supraspinatus — resisted abduction in scapular plane with thumbs down (internally rotated)."},{"id": 8140,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Lift-off test' assesses integrity of:","options": [{"key": "A","text": "Teres minor"},{"key": "B","text": "Supraspinatus"},{"key": "C","text": "Infraspinatus"},{"key": "D","text": "Subscapularis"}],"correct": "D","explanation": "Lift-off test (hand off lower back) tests subscapularis function."},{"id": 8141,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Speed's test' is used to assess:","options": [{"key": "A","text": "Biceps tendon pathology (long head)"},{"key": "B","text": "Supraspinatus tear"},{"key": "C","text": "AC joint pathology"},{"key": "D","text": "Rotator interval laxity"}],"correct": "A","explanation": "Speed's test: resisted shoulder flexion with elbow extended and forearm supinated, pain suggests biceps tendinopathy."},{"id": 8142,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Yergason's test' assesses:","options": [{"key": "A","text": "AC joint"},{"key": "B","text": "Rotator cuff strength"},{"key": "C","text": "SLAP lesion primarily"},{"key": "D","text": "Long head of biceps tendon stability/pathology"}],"correct": "D","explanation": "Yergason's test: resisted supination with elbow flexed 90°, pain/snap suggests biceps tendon instability/pathology."},{"id": 8143,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "'Apprehension test' for the shoulder assesses:","options": [{"key": "A","text": "Anterior instability"},{"key": "B","text": "AC joint arthritis"},{"key": "C","text": "Posterior instability"},{"key": "D","text": "Rotator cuff tear"}],"correct": "A","explanation": "Apprehension test: abduction and external rotation reproduces apprehension of anterior shoulder instability."},{"id": 8144,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Relocation test' (Jobe) is positive when:","options": [{"key": "A","text": "Apprehension relieved with posteriorly directed humeral head pressure"},{"key": "B","text": "No change occurs"},{"key": "C","text": "Apprehension increases with posterior pressure"},{"key": "D","text": "Pain increases with anterior pressure"}],"correct": "A","explanation": "Posteriorly directed force relieving apprehension confirms anterior instability (relocation test)."},{"id": 8145,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Sulcus sign' assesses:","options": [{"key": "A","text": "Inferior glenohumeral instability"},{"key": "B","text": "Biceps pathology"},{"key": "C","text": "AC joint separation"},{"key": "D","text": "Superior instability"}],"correct": "A","explanation": "Downward traction on the arm producing a sulcus below acromion indicates inferior instability."},{"id": 8146,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Cross-body adduction test' assesses pathology of:","options": [{"key": "A","text": "Rotator cuff"},{"key": "B","text": "Glenohumeral joint capsule"},{"key": "C","text": "Acromioclavicular joint"},{"key": "D","text": "Biceps tendon"}],"correct": "C","explanation": "Horizontal adduction compresses AC joint, reproducing pain in AC pathology."},{"id": 8147,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'O'Brien's test' (active compression test) is used to detect:","options": [{"key": "A","text": "AC joint separation only"},{"key": "B","text": "SLAP lesion / labral tear"},{"key": "C","text": "Rotator cuff full tear"},{"key": "D","text": "Frozen shoulder"}],"correct": "B","explanation": "O'Brien's test differentiates labral (SLAP) pathology from AC joint pathology based on pain location and change with forearm position."},{"id": 8148,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Drop arm test' is positive in:","options": [{"key": "A","text": "Labral tear only"},{"key": "B","text": "Biceps tendon rupture"},{"key": "C","text": "Massive rotator cuff tear (inability to slowly lower arm from abduction)"},{"key": "D","text": "AC separation"}],"correct": "C","explanation": "Inability to smoothly lower the arm from 90° abduction (it drops) suggests significant rotator cuff tear."},{"id": 8149,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "'Tinel's sign' at the wrist assesses:","options": [{"key": "A","text": "Ulnar nerve at elbow"},{"key": "B","text": "Median nerve compression at carpal tunnel"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Radial nerve"}],"correct": "B","explanation": "Tapping over carpal tunnel reproducing tingling in median distribution supports carpal tunnel syndrome."},{"id": 8150,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Phalen's test' is used for diagnosis of:","options": [{"key": "A","text": "De Quervain's tenosynovitis"},{"key": "B","text": "Cubital tunnel syndrome"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "Guyon's canal syndrome"}],"correct": "C","explanation": "Sustained wrist flexion for 60 seconds reproducing median nerve symptoms supports CTS."},{"id": 8151,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Finkelstein's test' is used to diagnose:","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "Dupuytren's contracture"},{"key": "C","text": "De Quervain's tenosynovitis"},{"key": "D","text": "Trigger finger"}],"correct": "C","explanation": "Ulnar deviation of wrist with thumb tucked in fist reproduces pain over first dorsal compartment (APL/EPB) in De Quervain's."},{"id": 8152,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Froment's sign' tests for weakness of which nerve function?","options": [{"key": "A","text": "Median nerve (thenar)"},{"key": "B","text": "Ulnar nerve (adductor pollicis)"},{"key": "C","text": "Radial nerve"},{"key": "D","text": "Musculocutaneous nerve"}],"correct": "B","explanation": "Froment's sign: substitution by flexor pollicis longus (median) when adductor pollicis (ulnar) is weak, tested via pinch grip with paper."},{"id": 8153,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "'Tinel's sign' at the elbow assesses compression of:","options": [{"key": "A","text": "Axillary nerve"},{"key": "B","text": "Ulnar nerve at cubital tunnel"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Radial nerve"}],"correct": "B","explanation": "Percussion over cubital tunnel reproducing ulnar paraesthesia indicates cubital tunnel syndrome."},{"id": 8154,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Cozen's test' is used to assess:","options": [{"key": "A","text": "Lateral epicondylitis (tennis elbow)"},{"key": "B","text": "Radial tunnel syndrome"},{"key": "C","text": "Medial epicondylitis (golfer's elbow)"},{"key": "D","text": "Cubital tunnel syndrome"}],"correct": "A","explanation": "Resisted wrist extension with elbow extended reproducing lateral elbow pain confirms lateral epicondylitis."},{"id": 8155,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'Golfer's elbow test' (resisted wrist flexion with elbow extended) assesses:","options": [{"key": "A","text": "Cubital tunnel"},{"key": "B","text": "Lateral epicondylitis"},{"key": "C","text": "Radial tunnel syndrome"},{"key": "D","text": "Medial epicondylitis"}],"correct": "D","explanation": "Pain at medial epicondyle with resisted wrist flexion/pronation indicates medial epicondylitis."},{"id": 8156,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Mill's test' is another provocative test for:","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "Lateral epicondylitis"},{"key": "C","text": "Medial epicondylitis"},{"key": "D","text": "De Quervain's"}],"correct": "B","explanation": "Mill's test: passive wrist flexion/pronation with elbow extended reproduces lateral elbow pain in tennis elbow."},{"id": 8157,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'Elbow flexion test' (analogous to Phalen's) is used to diagnose:","options": [{"key": "A","text": "Pronator syndrome"},{"key": "B","text": "Cubital tunnel syndrome (ulnar nerve)"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "Radial tunnel syndrome"}],"correct": "B","explanation": "Sustained elbow flexion compresses ulnar nerve at cubital tunnel, reproducing symptoms."},{"id": 8158,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Thomas test' positive finding indicates tightness of:","options": [{"key": "A","text": "Hamstrings"},{"key": "B","text": "Hip flexors (iliopsoas/rectus femoris)"},{"key": "C","text": "Adductors"},{"key": "D","text": "Gluteus medius"}],"correct": "B","explanation": "Inability of contralateral thigh to remain flat on table indicates hip flexor contracture."},{"id": 8159,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'FABER (Patrick's) test' pain in the groin suggests:","options": [{"key": "A","text": "Lumbar spine only"},{"key": "B","text": "SI joint only"},{"key": "C","text": "Knee pathology"},{"key": "D","text": "Hip joint pathology"}],"correct": "D","explanation": "Groin pain on FABER suggests intra-articular hip pathology; posterior/buttock pain suggests SIJ."},{"id": 8160,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'FADIR test' (Flexion-ADduction-Internal Rotation) is used to screen for:","options": [{"key": "A","text": "Piriformis syndrome only"},{"key": "B","text": "Hip flexor tightness"},{"key": "C","text": "Femoroacetabular impingement / labral tear"},{"key": "D","text": "SI joint dysfunction"}],"correct": "C","explanation": "FADIR provokes anterior hip impingement, suggestive of FAI or labral tear."},{"id": 8161,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Trendelenburg test' assesses:","options": [{"key": "A","text": "Hip flexor strength"},{"key": "B","text": "Quadriceps strength"},{"key": "C","text": "Hamstring flexibility"},{"key": "D","text": "Hip abductor strength (gluteus medius/minimus)"}],"correct": "D","explanation": "Positive test = pelvic drop on the unsupported side during single-leg stance, indicating weak abductors on stance side."},{"id": 8162,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Ober's test' positive finding indicates tightness of:","options": [{"key": "A","text": "Adductors"},{"key": "B","text": "Hamstrings"},{"key": "C","text": "Hip flexors"},{"key": "D","text": "Iliotibial band/TFL"}],"correct": "D","explanation": "Inability of the leg to adduct past neutral in side-lying suggests ITB/TFL tightness."},{"id": 8163,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Piriformis test' (FAIR test) reproduces symptoms of:","options": [{"key": "A","text": "Superior gluteal nerve"},{"key": "B","text": "Obturator nerve entrapment"},{"key": "C","text": "Femoral nerve entrapment"},{"key": "D","text": "Sciatic nerve compression by piriformis"}],"correct": "D","explanation": "Flexion-Adduction-Internal Rotation of hip stretches/compresses piriformis over sciatic nerve, reproducing radiating symptoms."},{"id": 8164,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Craig's test' measures:","options": [{"key": "A","text": "Tibial torsion"},{"key": "B","text": "Femoral anteversion angle"},{"key": "C","text": "Leg length discrepancy"},{"key": "D","text": "Q angle"}],"correct": "B","explanation": "Craig's test estimates femoral neck anteversion by palpating greater trochanter prominence during hip rotation, prone."},{"id": 8165,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "'Log roll test' of the hip primarily assesses:","options": [{"key": "A","text": "SI joint mobility"},{"key": "B","text": "Ligament laxity of knee"},{"key": "C","text": "Muscle strength"},{"key": "D","text": "Intra-articular hip pathology (least provocative, most specific)"}],"correct": "D","explanation": "Passive internal/external rotation of the extended leg (log roll) with pain suggests intra-articular hip pathology."},{"id": 8166,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "'Anterior drawer test' of the knee primarily assesses integrity of:","options": [{"key": "A","text": "PCL"},{"key": "B","text": "ACL"},{"key": "C","text": "MCL"},{"key": "D","text": "LCL"}],"correct": "B","explanation": "Anterior drawer tests ACL by assessing anterior tibial translation on femur."},{"id": 8167,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "'Posterior drawer test' of the knee assesses:","options": [{"key": "A","text": "ACL"},{"key": "B","text": "Meniscus"},{"key": "C","text": "PCL"},{"key": "D","text": "MCL"}],"correct": "C","explanation": "Posterior drawer tests PCL integrity via posterior tibial translation."},{"id": 8168,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Lachman test' is considered more sensitive than anterior drawer for detecting:","options": [{"key": "A","text": "PCL tear"},{"key": "B","text": "MCL tear"},{"key": "C","text": "Meniscal tear"},{"key": "D","text": "ACL tear"}],"correct": "D","explanation": "Lachman's (20-30° knee flexion) is the most sensitive clinical test for ACL integrity."},{"id": 8169,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Pivot shift test' assesses:","options": [{"key": "A","text": "Patellar instability"},{"key": "B","text": "PCL tear"},{"key": "C","text": "Meniscus tear"},{"key": "D","text": "Rotational/anterolateral instability due to ACL deficiency"}],"correct": "D","explanation": "Pivot shift reproduces the sensation of the tibia subluxing/reducing due to ACL insufficiency."},{"id": 8170,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "'Valgus stress test' of the knee (at 30° flexion) assesses:","options": [{"key": "A","text": "ACL"},{"key": "B","text": "MCL"},{"key": "C","text": "PCL"},{"key": "D","text": "LCL"}],"correct": "B","explanation": "Valgus stress opens the medial joint line, testing MCL integrity."},{"id": 8171,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "'Varus stress test' of the knee assesses:","options": [{"key": "A","text": "LCL"},{"key": "B","text": "Meniscus"},{"key": "C","text": "PCL"},{"key": "D","text": "MCL"}],"correct": "A","explanation": "Varus stress opens lateral joint line, testing LCL integrity."},{"id": 8172,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'McMurray's test' is used to assess:","options": [{"key": "A","text": "Patellar tracking"},{"key": "B","text": "Meniscal tear"},{"key": "C","text": "Quadriceps strength"},{"key": "D","text": "Ligament laxity"}],"correct": "B","explanation": "Combined rotation and flexion-extension of the knee producing a click/pain suggests meniscal tear."},{"id": 8173,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Apley's compression/distraction test' differentiates:","options": [{"key": "A","text": "Ligamentous injury (distraction) from meniscal injury (compression)"},{"key": "B","text": "Patellar tendon injury"},{"key": "C","text": "ACL from PCL"},{"key": "D","text": "MCL from LCL"}],"correct": "A","explanation": "Compression with rotation stresses meniscus; distraction stresses ligaments — helps differentiate source of pain."},{"id": 8174,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Patellar apprehension test' assesses:","options": [{"key": "A","text": "Quadriceps tendon rupture"},{"key": "B","text": "Patellofemoral instability (lateral subluxation risk)"},{"key": "C","text": "Meniscus tear"},{"key": "D","text": "ACL tear"}],"correct": "B","explanation": "Lateral glide of patella producing apprehension suggests patellar instability."},{"id": 8175,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Clarke's sign' (patellar grind test) is used to assess:","options": [{"key": "A","text": "Patellofemoral pain syndrome / chondromalacia patellae"},{"key": "B","text": "MCL sprain"},{"key": "C","text": "ACL injury"},{"key": "D","text": "Meniscal tear"}],"correct": "A","explanation": "Pain with quadriceps contraction against downward patellar pressure suggests patellofemoral joint pathology."},{"id": 8176,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Noble compression test' is used to diagnose:","options": [{"key": "A","text": "Patellar tendinopathy"},{"key": "B","text": "Pes anserine bursitis"},{"key": "C","text": "Meniscal injury"},{"key": "D","text": "Iliotibial band friction syndrome"}],"correct": "D","explanation": "Pressure over lateral femoral epicondyle during knee flexion-extension reproducing pain suggests ITB friction syndrome."},{"id": 8177,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Talar tilt test' assesses integrity of:","options": [{"key": "A","text": "Calcaneofibular ligament"},{"key": "B","text": "Anterior talofibular ligament"},{"key": "C","text": "Both CFL and ATFL depending on direction"},{"key": "D","text": "Deltoid ligament"}],"correct": "C","explanation": "Talar tilt (inversion) stresses CFL primarily and ATFL secondarily; test direction dependent."},{"id": 8178,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Hard","question": "'Anterior drawer test of the ankle' primarily assesses:","options": [{"key": "A","text": "Posterior talofibular ligament"},{"key": "B","text": "Calcaneofibular ligament only"},{"key": "C","text": "Anterior talofibular ligament (ATFL)"},{"key": "D","text": "Deltoid ligament"}],"correct": "C","explanation": "Anterior drawer at ankle mainly tests ATFL, the most commonly injured lateral ankle ligament."},{"id": 8179,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Thompson's test' is used to assess integrity of:","options": [{"key": "A","text": "Plantar fascia"},{"key": "B","text": "Achilles tendon"},{"key": "C","text": "Anterior tibial tendon"},{"key": "D","text": "Peroneal tendons"}],"correct": "B","explanation": "Calf squeeze test — absence of plantarflexion suggests Achilles tendon rupture."},{"id": 8180,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Windlass test' is used to diagnose:","options": [{"key": "A","text": "Tarsal tunnel syndrome"},{"key": "B","text": "Morton's neuroma"},{"key": "C","text": "Achilles tendinopathy"},{"key": "D","text": "Plantar fasciitis"}],"correct": "D","explanation": "Passive great toe extension reproducing plantar heel pain supports plantar fasciitis diagnosis."},{"id": 8181,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "'Tinel's sign' at the ankle assesses:","options": [{"key": "A","text": "Peroneal nerve entrapment at fibular head"},{"key": "B","text": "Saphenous nerve"},{"key": "C","text": "Tarsal tunnel syndrome (posterior tibial nerve)"},{"key": "D","text": "Sural nerve"}],"correct": "C","explanation": "Percussion behind medial malleolus reproducing plantar tingling suggests tarsal tunnel syndrome."},{"id": 8182,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Mulder's click test' is used to diagnose:","options": [{"key": "A","text": "Plantar fasciitis"},{"key": "B","text": "Morton's neuroma"},{"key": "C","text": "Achilles tendinopathy"},{"key": "D","text": "Tarsal coalition"}],"correct": "B","explanation": "Squeezing metatarsal heads together producing a palpable/audible click and pain suggests interdigital (Morton's) neuroma."},{"id": 8183,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Straight Leg Raise (SLR) test' is primarily used to detect:","options": [{"key": "A","text": "Hamstring strain only"},{"key": "B","text": "Lumbar disc herniation / sciatic nerve root tension"},{"key": "C","text": "Hip joint OA"},{"key": "D","text": "SI joint dysfunction"}],"correct": "B","explanation": "SLR reproducing radicular leg pain below 70° suggests nerve root tension, commonly from disc herniation (L4-S1)."},{"id": 8184,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Crossed SLR test' being positive (pain in symptomatic leg when raising asymptomatic leg) indicates:","options": [{"key": "A","text": "Muscular strain"},{"key": "B","text": "Non-specific finding"},{"key": "C","text": "High specificity for disc herniation"},{"key": "D","text": "Hip pathology"}],"correct": "C","explanation": "Crossed SLR is less sensitive but highly specific for lumbar disc herniation."},{"id": 8185,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Slump test' is a neural tension test primarily assessing:","options": [{"key": "A","text": "Hamstring flexibility only"},{"key": "B","text": "Dural/neural mobility of lumbar and sciatic nerve tissue"},{"key": "C","text": "Hip joint mobility"},{"key": "D","text": "SI joint mobility"}],"correct": "B","explanation": "Slump test combines spinal flexion, neck flexion, knee extension, and ankle dorsiflexion to tension the neuraxis and sciatic nerve."},{"id": 8186,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "'Femoral nerve stretch test' (prone knee bend) is used to assess:","options": [{"key": "A","text": "Hip flexor tightness only"},{"key": "B","text": "Upper lumbar nerve root tension (L2-L4)"},{"key": "C","text": "SI joint pathology"},{"key": "D","text": "Lower lumbar/sciatic nerve tension"}],"correct": "B","explanation": "Prone hip extension with knee flexion tensions femoral nerve, useful for suspected L2-L4 radiculopathy."},{"id": 8187,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Spurling's test' is used to assess:","options": [{"key": "A","text": "Rotator cuff pathology"},{"key": "B","text": "Carpal tunnel syndrome"},{"key": "C","text": "Thoracic outlet syndrome"},{"key": "D","text": "Cervical nerve root compression/foraminal encroachment"}],"correct": "D","explanation": "Cervical extension, lateral flexion, and axial compression toward the symptomatic side reproduces radicular arm symptoms if nerve root compressed."},{"id": 8188,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Hard","question": "'Distraction test' of the cervical spine relieving symptoms suggests:","options": [{"key": "A","text": "Ligament laxity"},{"key": "B","text": "Vertebral artery insufficiency"},{"key": "C","text": "Muscle spasm only"},{"key": "D","text": "Nerve root compression relieved by traction"}],"correct": "D","explanation": "Symptom relief with cervical distraction supports nerve root compression as the pain source."},{"id": 8189,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Vertebral artery test' assesses risk of:","options": [{"key": "A","text": "Vertebrobasilar insufficiency before cervical manipulation"},{"key": "B","text": "Cervical disc herniation"},{"key": "C","text": "Carpal tunnel"},{"key": "D","text": "Thoracic outlet syndrome"}],"correct": "A","explanation": "Sustained cervical extension and rotation assesses for vertebrobasilar insufficiency symptoms (dizziness, nystagmus) prior to manipulation."},{"id": 8190,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Adson's test' is used to screen for:","options": [{"key": "A","text": "Rotator cuff impingement"},{"key": "B","text": "Cervical radiculopathy"},{"key": "C","text": "Thoracic outlet syndrome (subclavian artery compression)"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "C","explanation": "Adson's test: head rotated/extended toward affected side with deep inspiration, radial pulse diminishes if TOS present."},{"id": 8191,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Roos test' (EAST - Elevated Arm Stress Test) is used for:","options": [{"key": "A","text": "Rotator cuff tear"},{"key": "B","text": "Thoracic outlet syndrome"},{"key": "C","text": "Cubital tunnel syndrome"},{"key": "D","text": "Carpal tunnel syndrome"}],"correct": "B","explanation": "Sustained overhead arm position with hand opening/closing reproducing TOS symptoms/fatigue supports diagnosis."},{"id": 8192,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Sacroiliac (SI) joint compression test' is performed with patient in which position?","options": [{"key": "A","text": "Side-lying, distract iliac crests"},{"key": "B","text": "Standing"},{"key": "C","text": "Supine, compress iliac crests medially"},{"key": "D","text": "Prone, compress sacrum posteriorly"}],"correct": "C","explanation": "Compression test: patient supine, examiner applies medially directed pressure over both iliac crests."},{"id": 8193,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Gaenslen's test' is used to assess:","options": [{"key": "A","text": "Piriformis syndrome"},{"key": "B","text": "Hip joint pathology"},{"key": "C","text": "SI joint pathology"},{"key": "D","text": "Lumbar disc herniation"}],"correct": "C","explanation": "Gaenslen's test stresses the SI joint by hyperextending one hip while flexing the other, patient near edge of table."},{"id": 8194,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "'Thigh thrust test' (posterior shear test) assesses:","options": [{"key": "A","text": "Piriformis syndrome"},{"key": "B","text": "Femoral nerve tension"},{"key": "C","text": "SI joint pathology"},{"key": "D","text": "Hip OA"}],"correct": "C","explanation": "Posteriorly directed force through flexed hip/femur stresses SI joint, reproducing pain if SIJ dysfunction present."},{"id": 8195,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "'Kemp's test' (quadrant test) for the lumbar spine assesses:","options": [{"key": "A","text": "SI joint pathology only"},{"key": "B","text": "Hamstring tightness"},{"key": "C","text": "Disc herniation only"},{"key": "D","text": "Facet joint pathology / nerve root compression via extension-rotation-lateral flexion"}],"correct": "D","explanation": "Combined extension, rotation, and lateral flexion narrows the foramen/facet, reproducing pain from facet or nerve root pathology."},{"id": 8196,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Milgram's test' assesses:","options": [{"key": "A","text": "Intrathecal pressure changes (disc pathology)"},{"key": "B","text": "Hip joint pathology"},{"key": "C","text": "SI joint pathology"},{"key": "D","text": "Facet joint pathology"}],"correct": "A","explanation": "Bilateral active straight leg raise held for 30 sec, pain suggests increased intrathecal pressure from disc pathology."},{"id": 8197,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Valsalva maneuver' in spinal assessment increases:","options": [{"key": "A","text": "Joint mobility"},{"key": "B","text": "Muscle tone only"},{"key": "C","text": "Blood pressure only, no diagnostic value"},{"key": "D","text": "Intrathecal pressure, provoking symptoms from space-occupying lesion"}],"correct": "D","explanation": "Valsalva raises intrathecal pressure; reproduction of radicular symptoms suggests disc herniation or space-occupying lesion."},{"id": 8198,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Hard","question": "'Prone instability test' for the lumbar spine helps identify:","options": [{"key": "A","text": "SI joint dysfunction"},{"key": "B","text": "Facet arthropathy only"},{"key": "C","text": "Disc herniation"},{"key": "D","text": "Segmental instability responding to stabilization exercises"}],"correct": "D","explanation": "Pain present with trunk unsupported (prone, feet off floor) but reduced when trunk stabilized (feet on floor) suggests clinical lumbar instability."},{"id": 8199,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Hoover test' is used to detect:","options": [{"key": "A","text": "Facet syndrome"},{"key": "B","text": "Malingering / non-organic leg weakness"},{"key": "C","text": "Disc herniation"},{"key": "D","text": "True paraplegia"}],"correct": "B","explanation": "Absence of expected contralateral heel pressure during 'weak' leg raise suggests non-organic or feigned weakness."},{"id": 8200,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Waddell's signs' are used to assess:","options": [{"key": "A","text": "True nerve root compression"},{"key": "B","text": "Muscle imbalance only"},{"key": "C","text": "Disc herniation severity"},{"key": "D","text": "Non-organic/psychosocial components of low back pain"}],"correct": "D","explanation": "Waddell's signs (tenderness, simulation, distraction, regional, overreaction) screen for non-organic contribution to LBP presentation."},{"id": 8201,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "'Bounce home test' of the knee assesses:","options": [{"key": "A","text": "Patellar tracking"},{"key": "B","text": "Quadriceps strength"},{"key": "C","text": "Ligament laxity"},{"key": "D","text": "Presence of a mechanical block (loose body/meniscal tear) preventing full extension"}],"correct": "D","explanation": "Passive knee extension that doesn't reach full/normal end feel suggests intra-articular block, e.g., torn meniscus fragment."},{"id": 8202,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Hughston's plica test' assesses:","options": [{"key": "A","text": "Patellar tendon rupture"},{"key": "B","text": "Meniscal tear"},{"key": "C","text": "ACL laxity"},{"key": "D","text": "Medial patellar plica syndrome"}],"correct": "D","explanation": "Palpable snap/pop with knee flexion-extension while pressing patella medially suggests symptomatic plica."},{"id": 8203,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "'Dial test' of the knee (tibial external rotation test) assesses:","options": [{"key": "A","text": "Patellar instability"},{"key": "B","text": "Posterolateral corner injury"},{"key": "C","text": "MCL injury"},{"key": "D","text": "ACL injury only"}],"correct": "B","explanation": "Excessive external tibial rotation at 30° (more than 90°) suggests posterolateral corner injury; if present at both 30° and 90°, suggests combined PCL/PLC injury."},{"id": 8204,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Reverse Lachman/Godfrey test' assesses:","options": [{"key": "A","text": "Meniscus"},{"key": "B","text": "ACL integrity"},{"key": "C","text": "MCL integrity"},{"key": "D","text": "PCL integrity (posterior tibial sag)"}],"correct": "D","explanation": "Godfrey's test observes posterior sag of tibia with hips/knees flexed 90°, supported — indicates PCL deficiency."},{"id": 8205,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'External rotation recurvatum test' assesses combined injury of:","options": [{"key": "A","text": "LCL and patellar tendon"},{"key": "B","text": "ACL and posterolateral structures"},{"key": "C","text": "PCL and MCL"},{"key": "D","text": "MCL and meniscus"}],"correct": "B","explanation": "Excessive hyperextension and external rotation of tibia with leg lifted by great toes suggests combined ACL/posterolateral laxity."},{"id": 8206,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "'Coleman block test' is used to assess flexibility of which foot deformity component?","options": [{"key": "A","text": "Flexible vs rigid subtalar varus in cavovarus foot"},{"key": "B","text": "Achilles tightness"},{"key": "C","text": "Hallux valgus"},{"key": "D","text": "Plantar fasciitis"}],"correct": "A","explanation": "Standing on a block under the lateral foot (first ray off block) determines if hindfoot varus is flexible/correctable, guiding surgical planning."},{"id": 8207,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "'Squeeze test' at the ankle/leg assesses:","options": [{"key": "A","text": "Peroneal tendon subluxation"},{"key": "B","text": "Lateral ankle ligament sprain"},{"key": "C","text": "Achilles rupture"},{"key": "D","text": "Syndesmotic (high ankle) sprain"}],"correct": "D","explanation": "Squeezing tibia and fibula together at mid-calf producing distal ankle pain suggests syndesmotic injury."},{"id": 8208,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Hard","question": "'External rotation stress test' of the ankle is used to assess:","options": [{"key": "A","text": "Syndesmotic injury"},{"key": "B","text": "Plantar fascia"},{"key": "C","text": "Lateral ligament complex"},{"key": "D","text": "Achilles tendon"}],"correct": "A","explanation": "Passive external rotation of the foot with leg stabilized reproducing anterior ankle pain suggests syndesmotic (high ankle) sprain."},{"id": 8209,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Homan's sign' historically used to screen for:","options": [{"key": "A","text": "Deep vein thrombosis (calf pain on ankle dorsiflexion)"},{"key": "B","text": "Compartment syndrome"},{"key": "C","text": "Gastrocnemius strain"},{"key": "D","text": "Achilles tendinopathy"}],"correct": "A","explanation": "Calf pain with passive ankle dorsiflexion was historically used to screen for DVT, though now considered unreliable/non-specific."},{"id": 8210,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Compression test for compartment syndrome' relies primarily on:","options": [{"key": "A","text": "X-ray findings"},{"key": "B","text": "Intracompartmental pressure measurement and clinical 5 P's (pain, pallor, pulselessness, paresthesia, paralysis)"},{"key": "C","text": "Simple palpation alone"},{"key": "D","text": "MRI only"}],"correct": "B","explanation": "Compartment syndrome diagnosis combines clinical signs (disproportionate pain, pain on passive stretch) with pressure measurement when needed."},{"id": 8211,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Allen's test' is used clinically to assess:","options": [{"key": "A","text": "Carpal tunnel"},{"key": "B","text": "Brachial plexus"},{"key": "C","text": "Median nerve function"},{"key": "D","text": "Patency of radial and ulnar arteries to the hand"}],"correct": "D","explanation": "Allen's test evaluates collateral circulation via ulnar and radial arteries before procedures like arterial line placement."},{"id": 8212,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Watson's test' (scaphoid shift test) assesses:","options": [{"key": "A","text": "Lunotriquetral instability"},{"key": "B","text": "Carpal tunnel syndrome"},{"key": "C","text": "TFCC tear"},{"key": "D","text": "Scapholunate ligament instability"}],"correct": "D","explanation": "Watson's test detects scapholunate instability by palpating scaphoid tuberosity during radial-ulnar wrist deviation."},{"id": 8213,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "'Piano key sign' at the wrist suggests instability/injury of the:","options": [{"key": "A","text": "Triangular fibrocartilage complex"},{"key": "B","text": "Carpal tunnel"},{"key": "C","text": "Scapholunate joint"},{"key": "D","text": "Distal radioulnar joint (DRUJ)"}],"correct": "D","explanation": "Excessive dorsal-volar mobility of the ulnar head ('piano key') suggests DRUJ instability."},{"id": 8214,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "'Grind test' of the thumb CMC joint is used to detect:","options": [{"key": "A","text": "Thumb CMC osteoarthritis"},{"key": "B","text": "De Quervain's tenosynovitis"},{"key": "C","text": "Ulnar collateral ligament injury"},{"key": "D","text": "Trigger thumb"}],"correct": "A","explanation": "Axial compression and rotation of the thumb metacarpal on trapezium reproduces pain/crepitus in CMC OA."},{"id": 8215,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Valgus stress test of the thumb MCP' (skier's thumb test) assesses:","options": [{"key": "A","text": "Scapholunate ligament"},{"key": "B","text": "Radial collateral ligament"},{"key": "C","text": "Extensor pollicis tendon"},{"key": "D","text": "Ulnar collateral ligament of thumb MCP"}],"correct": "D","explanation": "Valgus stress at thumb MCP tests UCL integrity, torn in 'skier's/gamekeeper's thumb'."},{"id": 8216,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The first stage of fracture healing is:","options": [{"key": "A","text": "Remodeling"},{"key": "B","text": "Consolidation"},{"key": "C","text": "Callus formation"},{"key": "D","text": "Hematoma formation"}],"correct": "D","explanation": "Fracture healing begins with hematoma formation at the fracture site within hours."},{"id": 8217,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Soft callus' formation typically occurs by which week post-fracture?","options": [{"key": "A","text": "12 weeks"},{"key": "B","text": "6 weeks"},{"key": "C","text": "1 week"},{"key": "D","text": "2-3 weeks"}],"correct": "D","explanation": "Soft (fibrocartilaginous) callus forms around 2-3 weeks, providing early stability."},{"id": 8218,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Hard callus' (bony callus) formation, via endochondral ossification, is typically complete by:","options": [{"key": "A","text": "1 week"},{"key": "B","text": "6-12 weeks"},{"key": "C","text": "6 months only"},{"key": "D","text": "3 weeks"}],"correct": "B","explanation": "Hard callus formation and clinical union typically occur by 6-12 weeks depending on bone and age."},{"id": 8219,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The final stage of fracture healing, restoring bone to near-original shape, is called:","options": [{"key": "A","text": "Soft callus"},{"key": "B","text": "Hematoma organization"},{"key": "C","text": "Remodeling"},{"key": "D","text": "Inflammation"}],"correct": "C","explanation": "Remodeling (following Wolff's law) is the final, longest phase, reshaping bone over months to years."},{"id": 8220,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Delayed union' is defined as fracture failing to unite within:","options": [{"key": "A","text": "1 week"},{"key": "B","text": "2 weeks"},{"key": "C","text": "Expected time for that bone but still showing potential to heal"},{"key": "D","text": "Never"}],"correct": "C","explanation": "Delayed union = union not achieved in expected time frame but healing process still ongoing/possible."},{"id": 8221,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Non-union' is characterized by:","options": [{"key": "A","text": "Complete healing"},{"key": "B","text": "Normal healing progressing slowly"},{"key": "C","text": "Malunion only"},{"key": "D","text": "Cessation of healing process with no bridging callus, often with sclerotic bone ends"}],"correct": "D","explanation": "Non-union = healing process has stopped; fibrous tissue or pseudarthrosis forms instead of bone bridging."},{"id": 8222,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Malunion' refers to:","options": [{"key": "A","text": "Fracture healed in unacceptable position/alignment"},{"key": "B","text": "Fracture failed to heal"},{"key": "C","text": "Delayed healing"},{"key": "D","text": "Avascular necrosis"}],"correct": "A","explanation": "Malunion = union occurred but with deformity/unacceptable alignment (angulation, rotation, shortening)."},{"id": 8223,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Fat embolism syndrome' most commonly occurs after fracture of:","options": [{"key": "A","text": "Radius"},{"key": "B","text": "Ribs"},{"key": "C","text": "Metacarpals"},{"key": "D","text": "Long bones (especially femur) and pelvis"}],"correct": "D","explanation": "Fat embolism is classically associated with long bone (femoral shaft) and pelvic fractures."},{"id": 8224,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Volkmann's ischemic contracture' is a complication most associated with fracture around:","options": [{"key": "A","text": "Femoral shaft fracture"},{"key": "B","text": "Ankle fracture"},{"key": "C","text": "Supracondylar fracture of humerus in children"},{"key": "D","text": "Colles' fracture"}],"correct": "C","explanation": "Supracondylar humeral fractures can compromise brachial artery, leading to compartment syndrome and Volkmann's contracture."},{"id": 8225,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Compartment syndrome' is characterized clinically by pain that is:","options": [{"key": "A","text": "Relieved by rest"},{"key": "B","text": "Absent"},{"key": "C","text": "Disproportionate to injury and increased by passive stretch"},{"key": "D","text": "Only present at night"}],"correct": "C","explanation": "Classic early sign is pain out of proportion, worsened by passive stretch of muscles in the compartment."},{"id": 8226,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Avascular necrosis' is a well-known complication of fracture of the:","options": [{"key": "A","text": "Radius shaft"},{"key": "B","text": "Scaphoid, femoral neck, talus"},{"key": "C","text": "Metatarsal"},{"key": "D","text": "Clavicle"}],"correct": "B","explanation": "These bones have precarious retrograde blood supply, predisposing to AVN after fracture."},{"id": 8227,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which type of fracture is described as bone broken into more than two fragments?","options": [{"key": "A","text": "Comminuted fracture"},{"key": "B","text": "Greenstick fracture"},{"key": "C","text": "Simple fracture"},{"key": "D","text": "Transverse fracture"}],"correct": "A","explanation": "Comminuted fracture = more than two bone fragments at the fracture site."},{"id": 8228,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Greenstick fracture' is typically seen in:","options": [{"key": "A","text": "Post-menopausal women"},{"key": "B","text": "Athletes"},{"key": "C","text": "Elderly osteoporotic bone"},{"key": "D","text": "Children (incomplete fracture, bone bends and cracks)"}],"correct": "D","explanation": "Greenstick fracture is common in children due to more pliable, less brittle bone."},{"id": 8229,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "A fracture where the bone is crushed/compressed is termed:","options": [{"key": "A","text": "Spiral fracture"},{"key": "B","text": "Compression fracture"},{"key": "C","text": "Avulsion fracture"},{"key": "D","text": "Comminuted fracture"}],"correct": "B","explanation": "Compression fractures occur commonly in vertebral bodies under axial loading."},{"id": 8230,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "An 'avulsion fracture' occurs due to:","options": [{"key": "A","text": "Axial compression"},{"key": "B","text": "Sudden forceful muscle/tendon pull tearing off a bone fragment"},{"key": "C","text": "Direct blow"},{"key": "D","text": "Rotational torque"}],"correct": "B","explanation": "Avulsion fractures occur when tendon/ligament pulls off a bony fragment at its attachment."},{"id": 8231,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Salter-Harris classification' is used for fractures involving:","options": [{"key": "A","text": "Spinal fractures"},{"key": "B","text": "Growth plate (epiphyseal) injuries in children"},{"key": "C","text": "Adult long bone shaft fractures"},{"key": "D","text": "Pelvic fractures"}],"correct": "B","explanation": "Salter-Harris types I-V classify pediatric physeal (growth plate) fracture patterns."},{"id": 8232,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Salter-Harris Type II' fracture involves:","options": [{"key": "A","text": "Physis and epiphysis"},{"key": "B","text": "Physis and metaphysis"},{"key": "C","text": "Physis, metaphysis, and epiphysis (crush)"},{"key": "D","text": "Physis only"}],"correct": "B","explanation": "Type II (most common) involves the physis and a metaphyseal fragment."},{"id": 8233,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which Salter-Harris type has the worst prognosis for growth disturbance?","options": [{"key": "A","text": "Type V (crush injury)"},{"key": "B","text": "Type III"},{"key": "C","text": "Type I"},{"key": "D","text": "Type II"}],"correct": "A","explanation": "Type V (crush injury to physis) carries the highest risk of growth arrest, though rare and often diagnosed retrospectively."},{"id": 8234,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Colles' fracture' involves fracture of the distal radius with:","options": [{"key": "A","text": "Radial shaft only"},{"key": "B","text": "Volar (palmar) displacement"},{"key": "C","text": "No displacement"},{"key": "D","text": "Dorsal displacement of distal fragment"}],"correct": "D","explanation": "Colles' fracture = distal radius fracture with dorsal angulation/displacement, classic 'dinner fork' deformity."},{"id": 8235,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Smith's fracture' involves distal radius fracture with:","options": [{"key": "A","text": "Dorsal displacement"},{"key": "B","text": "Volar (palmar) displacement of distal fragment"},{"key": "C","text": "No displacement"},{"key": "D","text": "Radial styloid only"}],"correct": "B","explanation": "Smith's fracture (reverse Colles') has volar displacement of the distal fragment."},{"id": 8236,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Monteggia fracture-dislocation' involves:","options": [{"key": "A","text": "Fracture of radius shaft with distal radioulnar joint dislocation"},{"key": "B","text": "Fracture of proximal ulna with radial head dislocation"},{"key": "C","text": "Fracture of both bones of forearm"},{"key": "D","text": "Fracture of distal radius with ulnar styloid fracture"}],"correct": "B","explanation": "Monteggia = proximal 1/3 ulna fracture + radial head dislocation."},{"id": 8237,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Galeazzi fracture-dislocation' involves:","options": [{"key": "A","text": "Proximal ulna fracture with radial head dislocation"},{"key": "B","text": "Distal radius fracture with distal radioulnar joint (DRUJ) disruption"},{"key": "C","text": "Colles fracture variant"},{"key": "D","text": "Both bone forearm fracture"}],"correct": "B","explanation": "Galeazzi = distal 1/3 radius shaft fracture with DRUJ dislocation."},{"id": 8238,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Pott's fracture' classically refers to fracture around:","options": [{"key": "A","text": "Ankle joint (bimalleolar)"},{"key": "B","text": "Wrist"},{"key": "C","text": "Hip"},{"key": "D","text": "Elbow"}],"correct": "A","explanation": "Pott's fracture describes bimalleolar/trimalleolar ankle fracture-dislocation."},{"id": 8239,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Bennett's fracture' involves the base of which bone?","options": [{"key": "A","text": "Fifth metacarpal"},{"key": "B","text": "Scaphoid"},{"key": "C","text": "Radius"},{"key": "D","text": "First metacarpal (intra-articular)"}],"correct": "D","explanation": "Bennett's fracture is an intra-articular fracture-dislocation at the base of the thumb (1st) metacarpal."},{"id": 8240,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Boxer's fracture' most commonly involves the neck of which metacarpal?","options": [{"key": "A","text": "Third metacarpal"},{"key": "B","text": "Second metacarpal"},{"key": "C","text": "Fifth metacarpal"},{"key": "D","text": "First metacarpal"}],"correct": "C","explanation": "Boxer's fracture classically involves the neck of the 5th metacarpal from punching injury."},{"id": 8241,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Jones fracture' occurs at which location?","options": [{"key": "A","text": "Navicular"},{"key": "B","text": "Calcaneus"},{"key": "C","text": "Base of 5th metatarsal (metaphyseal-diaphyseal junction)"},{"key": "D","text": "Base of 1st metatarsal"}],"correct": "C","explanation": "Jones fracture occurs at the metaphyseal-diaphyseal junction of the 5th metatarsal, prone to non-union due to watershed blood supply."},{"id": 8242,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following is a stress (fatigue) fracture commonly seen in athletes/military recruits?","options": [{"key": "A","text": "Comminuted fracture"},{"key": "B","text": "Tibial/metatarsal stress fracture from repetitive loading"},{"key": "C","text": "Femoral neck fracture from single trauma"},{"key": "D","text": "Colles fracture"}],"correct": "B","explanation": "Stress fractures occur from repetitive submaximal loading exceeding bone's remodeling capacity, common in tibia/metatarsals."},{"id": 8243,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Pathological fracture' occurs due to:","options": [{"key": "A","text": "Weakened bone (tumor, osteoporosis, infection) under normal/minimal force"},{"key": "B","text": "Normal bone under excessive force"},{"key": "C","text": "Direct high energy trauma always"},{"key": "D","text": "Fatigue loading only"}],"correct": "A","explanation": "Pathological fractures occur through diseased/weakened bone under forces that wouldn't fracture normal bone."},{"id": 8244,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "During fracture management, RICE protocol stands for:","options": [{"key": "A","text": "Reduce, Immobilize, Cast, Evaluate"},{"key": "B","text": "Reduce, Ice, Cast, Exercise"},{"key": "C","text": "Rest, Ice, Compression, Elevation"},{"key": "D","text": "Rest, Immobilize, Compress, Elevate"}],"correct": "C","explanation": "RICE = Rest, Ice, Compression, Elevation — standard acute soft tissue/fracture adjunct management."},{"id": 8245,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which of the following is a sign of infected non-union rather than aseptic non-union?","options": [{"key": "A","text": "Painless mobility only"},{"key": "B","text": "Hypertrophic callus without pain"},{"key": "C","text": "Sclerotic bone ends without inflammation"},{"key": "D","text": "Discharge, warmth, elevated inflammatory markers"}],"correct": "D","explanation": "Infected non-union presents with signs of infection (discharge, warmth, raised CRP/ESR) in addition to failure to heal."},{"id": 8246,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "'Hypertrophic non-union' (elephant foot type) typically results from inadequate:","options": [{"key": "A","text": "Bone contact only"},{"key": "B","text": "Blood supply"},{"key": "C","text": "Nutrition"},{"key": "D","text": "Mechanical stability (excessive movement) despite good blood supply"}],"correct": "D","explanation": "Hypertrophic non-union occurs due to instability with abundant but ineffective callus, blood supply usually adequate."},{"id": 8247,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Atrophic non-union' occurs primarily due to:","options": [{"key": "A","text": "Excessive mechanical motion only"},{"key": "B","text": "Infection always"},{"key": "C","text": "Poor blood supply / biological factors"},{"key": "D","text": "Overloading"}],"correct": "C","explanation": "Atrophic non-union results from inadequate biology (poor vascularity) with minimal callus formation."},{"id": 8248,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Factors that impair fracture healing include all EXCEPT:","options": [{"key": "A","text": "Adequate blood supply"},{"key": "B","text": "Poor nutrition"},{"key": "C","text": "Smoking"},{"key": "D","text": "Infection"}],"correct": "A","explanation": "Adequate blood supply promotes healing; the others impair it."},{"id": 8249,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Physiotherapy in the immobilization phase of fracture management primarily focuses on:","options": [{"key": "A","text": "Aggressive stretching of fracture site"},{"key": "B","text": "Maintaining ROM/strength of adjacent joints, preventing stiffness and muscle atrophy"},{"key": "C","text": "Manipulation of the fracture site"},{"key": "D","text": "Weight-bearing exercises regardless of healing stage"}],"correct": "B","explanation": "Focus during immobilization: maintain mobility/strength of unaffected adjacent joints and isometric exercises for immobilized limb as tolerated."},{"id": 8250,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Sudeck's atrophy' (Complex Regional Pain Syndrome) following fracture is characterized by:","options": [{"key": "A","text": "Pain, swelling, stiffness, and trophic skin/bone changes disproportionate to injury"},{"key": "B","text": "Simple muscle wasting only"},{"key": "C","text": "Isolated joint stiffness without pain"},{"key": "D","text": "Normal recovery pattern"}],"correct": "A","explanation": "CRPS/Sudeck's atrophy presents with disproportionate pain, autonomic and trophic changes following fracture/trauma."},{"id": 8251,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Most common site of clavicle fracture is:","options": [{"key": "A","text": "Lateral third"},{"key": "B","text": "Middle third"},{"key": "C","text": "Sternal end"},{"key": "D","text": "Medial third"}],"correct": "B","explanation": "Middle third of clavicle is the most common site due to anatomical transition and lack of muscular/ligamentous support."},{"id": 8252,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "In clavicle fracture, the medial fragment is typically displaced:","options": [{"key": "A","text": "Backward"},{"key": "B","text": "Upward by sternocleidomastoid pull"},{"key": "C","text": "No displacement"},{"key": "D","text": "Downward and forward by weight of arm"}],"correct": "B","explanation": "SCM pulls the medial fragment upward, while the lateral fragment drops due to arm weight and trapezius weakness."},{"id": 8253,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Most common fracture of the proximal humerus occurs at the:","options": [{"key": "A","text": "Greater tuberosity only"},{"key": "B","text": "Surgical neck"},{"key": "C","text": "Anatomical neck"},{"key": "D","text": "Head only"}],"correct": "B","explanation": "Surgical neck fracture is the most common proximal humeral fracture, especially in elderly osteoporotic bone."},{"id": 8254,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Radial nerve injury is a well-known complication of fracture of the:","options": [{"key": "A","text": "Humeral shaft (mid-shaft, spiral groove)"},{"key": "B","text": "Distal radius"},{"key": "C","text": "Proximal humerus"},{"key": "D","text": "Olecranon"}],"correct": "A","explanation": "Radial nerve runs in the spiral groove of humeral shaft, vulnerable in mid-shaft fractures."},{"id": 8255,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Supracondylar fracture of humerus is most common in which age group?","options": [{"key": "A","text": "Adults (30-40 years)"},{"key": "B","text": "Children (5-10 years)"},{"key": "C","text": "Infants (0-1 year)"},{"key": "D","text": "Elderly (>65 years)"}],"correct": "B","explanation": "Supracondylar fractures are most common in children aged 5-10 years, typically from FOOSH."},{"id": 8256,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Gartland classification is used to grade the severity of:","options": [{"key": "A","text": "Clavicle fractures"},{"key": "B","text": "Supracondylar humerus fractures"},{"key": "C","text": "Radial head fractures"},{"key": "D","text": "Colles fractures"}],"correct": "B","explanation": "Gartland classification (I-III) grades displacement severity of pediatric supracondylar humeral fractures."},{"id": 8257,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Gun stock deformity' (cubitus varus) is a late complication of:","options": [{"key": "A","text": "Radial head fracture"},{"key": "B","text": "Supracondylar fracture of humerus"},{"key": "C","text": "Monteggia fracture"},{"key": "D","text": "Colles fracture"}],"correct": "B","explanation": "Malunion of supracondylar fracture can lead to cubitus varus, termed gun stock deformity."},{"id": 8258,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Radial head fractures are most commonly caused by:","options": [{"key": "A","text": "Fall on outstretched hand (FOOSH) with elbow extended"},{"key": "B","text": "Repetitive strain"},{"key": "C","text": "Direct blow to elbow"},{"key": "D","text": "Twisting injury"}],"correct": "A","explanation": "Axial loading through FOOSH transmits force to radial head against capitulum, causing fracture."},{"id": 8259,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Dinner fork deformity' is classically associated with which fracture?","options": [{"key": "A","text": "Colles' fracture"},{"key": "B","text": "Bennett's fracture"},{"key": "C","text": "Smith's fracture"},{"key": "D","text": "Scaphoid fracture"}],"correct": "A","explanation": "Dorsal displacement in Colles' fracture creates the characteristic 'dinner fork' silhouette on lateral view."},{"id": 8260,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which nerve is at risk of injury in a scaphoid fracture's associated blood supply disruption issue, but more importantly, delayed diagnosis of scaphoid fracture risks:","options": [{"key": "A","text": "Median nerve palsy"},{"key": "B","text": "Radial nerve palsy"},{"key": "C","text": "Avascular necrosis of proximal pole"},{"key": "D","text": "Ulnar nerve palsy"}],"correct": "C","explanation": "Scaphoid's retrograde blood supply predisposes the proximal pole to AVN, especially if fracture missed/delayed treatment."},{"id": 8261,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'Snuffbox tenderness' after a fall on outstretched hand is highly suggestive of:","options": [{"key": "A","text": "Lunate dislocation"},{"key": "B","text": "Colles fracture"},{"key": "C","text": "Triquetral fracture"},{"key": "D","text": "Scaphoid fracture"}],"correct": "D","explanation": "Anatomical snuffbox tenderness is a classic clinical sign of scaphoid fracture, even with normal initial X-ray."},{"id": 8262,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Median nerve compression can occur acutely following which carpal injury?","options": [{"key": "A","text": "Trapezium fracture"},{"key": "B","text": "Hamate fracture"},{"key": "C","text": "Lunate dislocation"},{"key": "D","text": "Pisiform fracture"}],"correct": "C","explanation": "Lunate dislocation can push into the carpal tunnel, compressing the median nerve acutely."},{"id": 8263,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Olecranon fractures are typically caused by:","options": [{"key": "A","text": "Twisting injury"},{"key": "B","text": "Repetitive overuse only"},{"key": "C","text": "FOOSH with elbow extended"},{"key": "D","text": "Direct fall onto point of elbow or forceful triceps contraction"}],"correct": "D","explanation": "Olecranon fractures result from direct trauma to elbow tip or sudden forceful triceps pull (avulsion mechanism)."},{"id": 8264,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which upper limb fracture is associated with 'waiter's tip' deformity if brachial plexus is also injured?","options": [{"key": "A","text": "Scaphoid fracture"},{"key": "B","text": "Distal radius fracture"},{"key": "C","text": "Clavicle fracture alone"},{"key": "D","text": "Proximal humerus fracture with Erb's palsy"}],"correct": "D","explanation": "Severe proximal humeral/shoulder trauma may associate with upper brachial plexus (Erb's) injury producing waiter's tip posture."},{"id": 8265,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "In children, a fracture of the clavicle is usually managed by:","options": [{"key": "A","text": "Immediate surgery"},{"key": "B","text": "Traction for 6 weeks"},{"key": "C","text": "Open reduction internal fixation always"},{"key": "D","text": "Figure-of-8 bandage/sling, conservative management"}],"correct": "D","explanation": "Most pediatric clavicle fractures heal well conservatively with sling/figure-of-8 immobilization."},{"id": 8266,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which is the most common complication after a distal radius (Colles') fracture affecting function?","options": [{"key": "A","text": "Non-union (rare in this bone)"},{"key": "B","text": "Wrist stiffness and grip weakness"},{"key": "C","text": "Avascular necrosis"},{"key": "D","text": "Compartment syndrome always"}],"correct": "B","explanation": "Wrist/finger stiffness and reduced grip strength are common after immobilization for Colles' fracture, addressed with physiotherapy."},{"id": 8267,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'Median nerve' injury is a recognized complication of which elbow fracture in children?","options": [{"key": "A","text": "Olecranon fracture"},{"key": "B","text": "Radial head fracture"},{"key": "C","text": "Lateral condyle fracture"},{"key": "D","text": "Supracondylar fracture (anterior interosseous branch particularly)"}],"correct": "D","explanation": "Supracondylar humeral fractures can injure median nerve (including AIN), along with radial and ulnar nerves depending on displacement direction."},{"id": 8268,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "Which upper limb fracture is classically associated with a 'Terrible triad' injury pattern of the elbow?","options": [{"key": "A","text": "Radial head fracture + coronoid process fracture + elbow dislocation"},{"key": "B","text": "Clavicle + scapula fracture"},{"key": "C","text": "Olecranon fracture + Monteggia"},{"key": "D","text": "Colles + Smith fracture"}],"correct": "A","explanation": "Terrible triad = elbow dislocation with radial head and coronoid process fractures, causing significant instability."},{"id": 8269,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "A fracture of the humeral shaft with wrist drop suggests injury to which nerve?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Median nerve"}],"correct": "B","explanation": "Radial nerve palsy from humeral shaft fracture classically causes wrist drop (loss of wrist/finger extension)."},{"id": 8270,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following best describes management priority for an open fracture?","options": [{"key": "A","text": "Immediate wound debridement, antibiotics, and fracture stabilization"},{"key": "B","text": "Delayed treatment after 48 hours"},{"key": "C","text": "Observation only"},{"key": "D","text": "Cast immobilization alone without surgery"}],"correct": "A","explanation": "Open fractures require urgent debridement, antibiotic prophylaxis, and stabilization to reduce infection risk."},{"id": 8271,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Buckle (torus) fracture' of the distal radius is typically seen in:","options": [{"key": "A","text": "Adults with pathological bone"},{"key": "B","text": "Elderly osteoporotic patients"},{"key": "C","text": "Athletes with high energy trauma"},{"key": "D","text": "Children (incomplete cortical buckling)"}],"correct": "D","explanation": "Torus fractures occur in children due to compression of the pliable metaphyseal cortex without a complete break."},{"id": 8272,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which fracture pattern of the proximal humerus is classified using the Neer classification?","options": [{"key": "A","text": "AO classification only"},{"key": "B","text": "Number of displaced parts (2, 3, or 4-part fractures)"},{"key": "C","text": "Gartland type"},{"key": "D","text": "Salter-Harris type"}],"correct": "B","explanation": "Neer classification categorizes proximal humeral fractures based on displaced segments (head, shaft, greater/lesser tuberosity)."},{"id": 8273,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Which structure is most at risk of injury with an anterior shoulder (glenohumeral) dislocation associated fracture (Hill-Sachs lesion) located on:","options": [{"key": "A","text": "Glenoid rim anteriorly (Bankart)"},{"key": "B","text": "Posterolateral humeral head"},{"key": "C","text": "Acromion"},{"key": "D","text": "Anteromedial humeral head"}],"correct": "B","explanation": "Hill-Sachs lesion is a compression fracture on the posterolateral humeral head from impaction against the anterior glenoid rim."},{"id": 8274,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Easy","question": "'Reverse Hill-Sachs lesion' occurs with which type of shoulder dislocation?","options": [{"key": "A","text": "Posterior dislocation"},{"key": "B","text": "Superior dislocation"},{"key": "C","text": "Anterior dislocation"},{"key": "D","text": "Inferior dislocation (luxatio erecta)"}],"correct": "A","explanation": "Reverse Hill-Sachs = anteromedial humeral head defect from posterior dislocation impaction."},{"id": 8275,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Weight-bearing precautions after upper limb fracture fixation typically depend on:","options": [{"key": "A","text": "Fracture stability, fixation type, and surgeon's protocol"},{"key": "B","text": "Never allowed to bear weight through upper limb"},{"key": "C","text": "Always immediate full weight bearing"},{"key": "D","text": "Patient's age only"}],"correct": "A","explanation": "Progression of loading/weight-bearing through the limb (e.g., using it for support) is guided by fixation stability and surgeon protocol."},{"id": 8276,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Femoral neck fractures are most common in which population?","options": [{"key": "A","text": "Young athletes"},{"key": "B","text": "Children"},{"key": "C","text": "Middle-aged men only"},{"key": "D","text": "Elderly osteoporotic individuals (especially women)"}],"correct": "D","explanation": "Femoral neck fractures classically occur in elderly osteoporotic patients, often from low-energy falls."},{"id": 8277,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Garden classification is used to grade:","options": [{"key": "A","text": "Tibial plateau fractures"},{"key": "B","text": "Femoral shaft fractures"},{"key": "C","text": "Femoral neck fractures"},{"key": "D","text": "Ankle fractures"}],"correct": "C","explanation": "Garden classification (I-IV) grades displacement of femoral neck fractures, guiding treatment (fixation vs arthroplasty)."},{"id": 8278,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Avascular necrosis risk is highest with which femoral neck fracture classification?","options": [{"key": "A","text": "Garden III and IV (displaced)"},{"key": "B","text": "Garden II"},{"key": "C","text": "Garden I"},{"key": "D","text": "Not related to Garden classification"}],"correct": "A","explanation": "Displaced fractures (Garden III/IV) carry higher risk of disrupting retinacular blood supply, leading to AVN."},{"id": 8279,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Intertrochanteric fractures typically have better healing potential than femoral neck fractures because:","options": [{"key": "A","text": "They occur outside the joint capsule with good blood supply from surrounding muscle"},{"key": "B","text": "They occur only in young patients"},{"key": "C","text": "They have poor blood supply"},{"key": "D","text": "They are always non-displaced"}],"correct": "A","explanation": "Extracapsular location with rich muscular blood supply favors healing compared to intracapsular femoral neck fractures."},{"id": 8280,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Most common mechanism of femoral shaft fracture in young adults is:","options": [{"key": "A","text": "Pathological process"},{"key": "B","text": "Repetitive stress"},{"key": "C","text": "Low-energy fall"},{"key": "D","text": "High-energy trauma (RTA, fall from height)"}],"correct": "D","explanation": "Femoral shaft fractures in young healthy bone usually require significant force, e.g., road traffic accidents."},{"id": 8281,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Popliteal artery injury is a significant risk in which knee-region fracture/dislocation?","options": [{"key": "A","text": "Fibular head fracture"},{"key": "B","text": "Knee dislocation (tibiofemoral)"},{"key": "C","text": "Tibial tuberosity avulsion"},{"key": "D","text": "Patellar fracture"}],"correct": "B","explanation": "Knee dislocation carries high risk of popliteal artery injury due to its fixed position posteriorly, requiring vascular assessment."},{"id": 8282,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Tibial plateau fractures most commonly involve which condyle?","options": [{"key": "A","text": "Lateral condyle"},{"key": "B","text": "Neither, only tibial shaft"},{"key": "C","text": "Both equally always"},{"key": "D","text": "Medial condyle"}],"correct": "A","explanation": "Lateral tibial plateau fractures are more common due to valgus loading mechanism and relative weakness of lateral plateau."},{"id": 8283,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Compartment syndrome is most frequently associated with fracture of the:","options": [{"key": "A","text": "Clavicle"},{"key": "B","text": "Tibial shaft"},{"key": "C","text": "Patella"},{"key": "D","text": "Femoral neck"}],"correct": "B","explanation": "Tibial shaft fractures are the most common cause of acute compartment syndrome due to tight fascial compartments."},{"id": 8284,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "Ankle fractures are classified using which commonly used system based on mechanism/fibular fracture level?","options": [{"key": "A","text": "Neer classification"},{"key": "B","text": "Garden classification"},{"key": "C","text": "Weber classification"},{"key": "D","text": "Salter-Harris classification (in adults)"}],"correct": "C","explanation": "Weber classification (A, B, C) categorizes ankle fractures based on the level of fibular fracture relative to syndesmosis."},{"id": 8285,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Pilon fracture' refers to fracture of the:","options": [{"key": "A","text": "Calcaneus"},{"key": "B","text": "Proximal tibia"},{"key": "C","text": "Talus"},{"key": "D","text": "Distal tibial articular surface (axial loading injury)"}],"correct": "D","explanation": "Pilon fractures result from high-energy axial loading, causing comminuted distal tibial plafond fracture."},{"id": 8286,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Calcaneal fractures most commonly result from:","options": [{"key": "A","text": "Direct blow to lateral foot"},{"key": "B","text": "Repetitive stress"},{"key": "C","text": "Twisting injury"},{"key": "D","text": "Fall from height (axial loading through heel)"}],"correct": "D","explanation": "Calcaneal fractures classically occur from axial loading during falls from height, landing on the heel."},{"id": 8287,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Calcaneal fractures are frequently associated with which concurrent injury due to shared mechanism?","options": [{"key": "A","text": "Cervical spine fracture"},{"key": "B","text": "Wrist fracture"},{"key": "C","text": "Shoulder dislocation"},{"key": "D","text": "Lumbar spine (vertebral) compression fracture"}],"correct": "D","explanation": "Axial loading mechanism causing calcaneal fracture also predisposes to concurrent lumbar spine compression fractures."},{"id": 8288,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Böhler's angle' is used radiographically to assess:","options": [{"key": "A","text": "Ankle mortise congruity"},{"key": "B","text": "Talar neck fracture"},{"key": "C","text": "Calcaneal fracture severity"},{"key": "D","text": "Tibial plateau fracture"}],"correct": "C","explanation": "Böhler's angle (normal 20-40°) is reduced in calcaneal fractures, indicating loss of height/collapse."},{"id": 8289,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Talar neck fractures carry significant risk of:","options": [{"key": "A","text": "Avascular necrosis of talar body"},{"key": "B","text": "Peroneal tendon rupture"},{"key": "C","text": "Compartment syndrome primarily"},{"key": "D","text": "Achilles tendon rupture"}],"correct": "A","explanation": "Retrograde blood supply to talar body makes it vulnerable to AVN after neck fracture, especially displaced (Hawkins classification)."},{"id": 8290,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Hawkins sign' on X-ray (subchondral lucency) following talar fracture indicates:","options": [{"key": "A","text": "Adequate blood supply/lower AVN risk"},{"key": "B","text": "Definite AVN"},{"key": "C","text": "Infection"},{"key": "D","text": "Non-union"}],"correct": "A","explanation": "Presence of Hawkins sign (subchondral radiolucency at 6-8 weeks) suggests preserved vascularity, favorable prognosis."},{"id": 8291,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Patellar fractures most commonly occur due to:","options": [{"key": "A","text": "Twisting injury"},{"key": "B","text": "Repetitive overuse"},{"key": "C","text": "Low energy fall on outstretched hand"},{"key": "D","text": "Direct blow or forceful quadriceps contraction against a flexed knee"}],"correct": "D","explanation": "Direct trauma (fall on knee) or sudden eccentric quadriceps contraction can fracture the patella."},{"id": 8292,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "A fracture with inability to perform straight leg raise and palpable gap suggests which patellar fracture pattern?","options": [{"key": "A","text": "Stress fracture"},{"key": "B","text": "Non-displaced hairline fracture"},{"key": "C","text": "Vertical fracture, minimally displaced"},{"key": "D","text": "Displaced transverse fracture with extensor mechanism disruption"}],"correct": "D","explanation": "Displaced fracture disrupting the extensor mechanism prevents active knee extension/SLR."},{"id": 8293,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Tibial stress fractures are common in which population?","options": [{"key": "A","text": "Infants"},{"key": "B","text": "Post-surgical patients only"},{"key": "C","text": "Runners and military recruits"},{"key": "D","text": "Elderly sedentary population"}],"correct": "C","explanation": "Repetitive loading in runners/recruits predisposes to tibial stress fractures."},{"id": 8294,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Fibular fractures near the neck can risk injury to which nerve?","options": [{"key": "A","text": "Common peroneal nerve"},{"key": "B","text": "Sural nerve"},{"key": "C","text": "Saphenous nerve"},{"key": "D","text": "Tibial nerve"}],"correct": "A","explanation": "Common peroneal nerve winds around the fibular neck, vulnerable to injury with fractures in that region."},{"id": 8295,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'March fracture' commonly refers to stress fracture of the:","options": [{"key": "A","text": "Metatarsals (especially 2nd/3rd)"},{"key": "B","text": "Femur"},{"key": "C","text": "Fibula"},{"key": "D","text": "Tibia"}],"correct": "A","explanation": "March fracture is a classic term for metatarsal stress fracture, historically seen in soldiers marching long distances."},{"id": 8296,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which lower limb fracture in children commonly involves the distal femoral or proximal tibial physis with growth disturbance risk?","options": [{"key": "A","text": "Metatarsal fractures"},{"key": "B","text": "Patellar fractures"},{"key": "C","text": "Salter-Harris fractures around knee physes"},{"key": "D","text": "Diaphyseal fractures only"}],"correct": "C","explanation": "Physeal injuries around the knee (fast-growing physes) carry significant growth disturbance risk if not properly managed."},{"id": 8297,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Weight-bearing status after femoral neck fracture fixation is typically determined by:","options": [{"key": "A","text": "Fracture stability and fixation method chosen by surgeon"},{"key": "B","text": "Patient's preference alone"},{"key": "C","text": "Never allowed to bear weight"},{"key": "D","text": "Always full weight bearing immediately"}],"correct": "A","explanation": "Surgeon's assessment of construct stability and fracture pattern guides weight-bearing progression (touch-down, partial, or full)."},{"id": 8298,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which classification system is commonly used for open fractures based on wound size/contamination/soft tissue injury?","options": [{"key": "A","text": "Gustilo-Anderson classification"},{"key": "B","text": "Garden classification"},{"key": "C","text": "Salter-Harris classification"},{"key": "D","text": "Weber classification"}],"correct": "A","explanation": "Gustilo-Anderson (Type I, II, IIIA/B/C) classifies open fractures based on wound characteristics and contamination."},{"id": 8299,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Deep vein thrombosis (DVT) risk is notably elevated after which lower limb fracture requiring prolonged immobilization?","options": [{"key": "A","text": "Clavicle fracture"},{"key": "B","text": "Toe fracture"},{"key": "C","text": "Femoral neck/hip fracture"},{"key": "D","text": "Isolated finger fracture"}],"correct": "C","explanation": "Hip fractures with prolonged immobilization significantly raise DVT/PE risk, necessitating prophylaxis."},{"id": 8300,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Medium","question": "Early mobilization after lower limb fracture fixation primarily aims to prevent:","options": [{"key": "A","text": "Infection directly"},{"key": "B","text": "DVT, muscle atrophy, joint stiffness, and pressure sores"},{"key": "C","text": "Avascular necrosis directly"},{"key": "D","text": "Malunion only"}],"correct": "B","explanation": "Early safe mobilization reduces complications of prolonged bed rest (DVT, deconditioning, stiffness, skin breakdown)."},{"id": 8301,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The most common type of vertebral fracture in osteoporotic patients is:","options": [{"key": "A","text": "Fracture-dislocation"},{"key": "B","text": "Burst fracture"},{"key": "C","text": "Compression (wedge) fracture"},{"key": "D","text": "Chance fracture"}],"correct": "C","explanation": "Osteoporotic vertebral fractures are typically anterior wedge compression fractures from minimal trauma."},{"id": 8302,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "'Burst fracture' of the vertebra involves:","options": [{"key": "A","text": "Only anterior column compression"},{"key": "B","text": "Both anterior and middle column failure with retropulsion of fragments into canal"},{"key": "C","text": "Posterior column only"},{"key": "D","text": "Ligamentous injury only"}],"correct": "B","explanation": "Burst fracture involves failure of anterior and middle columns, risking canal compromise from retropulsed fragments."},{"id": 8303,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Chance fracture' (seatbelt fracture) involves failure of:","options": [{"key": "A","text": "Posterior column only"},{"key": "B","text": "Anterior column only"},{"key": "C","text": "All three columns (flexion-distraction injury)"},{"key": "D","text": "Odontoid process"}],"correct": "C","explanation": "Chance fracture is a flexion-distraction injury through all three spinal columns, classically from lap-belt trauma."},{"id": 8304,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which spinal fracture classification system uses the concept of three columns (anterior, middle, posterior)?","options": [{"key": "A","text": "ASIA classification"},{"key": "B","text": "Denis classification"},{"key": "C","text": "Frankel classification"},{"key": "D","text": "Gustilo classification"}],"correct": "B","explanation": "Denis three-column theory helps assess spinal fracture stability."},{"id": 8305,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Instability of a vertebral fracture is most concerning when it involves:","options": [{"key": "A","text": "Middle column (posterior wall of vertebral body)"},{"key": "B","text": "Only the anterior column"},{"key": "C","text": "Transverse process only"},{"key": "D","text": "Spinous process only"}],"correct": "A","explanation": "Middle column failure (posterior body wall) is critical for canal compromise/instability assessment."},{"id": 8306,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "'Jefferson fracture' involves which vertebra?","options": [{"key": "A","text": "C7"},{"key": "B","text": "C2 (axis)"},{"key": "C","text": "C1 (atlas) - burst fracture"},{"key": "D","text": "T1"}],"correct": "C","explanation": "Jefferson fracture is a burst fracture of the atlas (C1) ring, usually from axial loading."},{"id": 8307,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Hangman's fracture' involves fracture of:","options": [{"key": "A","text": "C1 ring"},{"key": "B","text": "Odontoid process of C2"},{"key": "C","text": "Pars interarticularis of C2 (axis)"},{"key": "D","text": "C6-C7 facet joints"}],"correct": "C","explanation": "Hangman's fracture = bilateral pars interarticularis fracture of C2, classically from hyperextension-distraction."},{"id": 8308,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Odontoid (dens) fractures are classified using which system?","options": [{"key": "A","text": "Weber classification"},{"key": "B","text": "Frankel classification"},{"key": "C","text": "Denis classification"},{"key": "D","text": "Anderson-D'Alonzo classification"}],"correct": "D","explanation": "Anderson-D'Alonzo classifies odontoid fractures into Type I, II, III based on fracture location."},{"id": 8309,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which type of odontoid fracture has the highest non-union rate?","options": [{"key": "A","text": "All equal risk"},{"key": "B","text": "Type II (base of dens)"},{"key": "C","text": "Type I (tip)"},{"key": "D","text": "Type III (extends into body)"}],"correct": "B","explanation": "Type II odontoid fractures have highest non-union risk due to relatively poor blood supply at that level."},{"id": 8310,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pelvic fractures with significant hemorrhage risk are most concerning when they involve:","options": [{"key": "A","text": "Iliac crest avulsion"},{"key": "B","text": "Disruption of the posterior pelvic ring (SI joint/sacrum)"},{"key": "C","text": "Isolated pubic rami fracture"},{"key": "D","text": "Coccyx fracture"}],"correct": "B","explanation": "Posterior ring disruption is associated with major vessel injury and life-threatening hemorrhage."},{"id": 8311,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Open book' pelvic fracture pattern results from which mechanism?","options": [{"key": "A","text": "Combined mechanism only"},{"key": "B","text": "Anteroposterior compression"},{"key": "C","text": "Vertical shear"},{"key": "D","text": "Lateral compression"}],"correct": "B","explanation": "AP compression causes symphyseal diastasis and posterior ring opening — 'open book' pattern."},{"id": 8312,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Young-Burgess classification of pelvic fractures is based on:","options": [{"key": "A","text": "Mechanism of injury (AP compression, lateral compression, vertical shear)"},{"key": "B","text": "Neurological deficit"},{"key": "C","text": "Bone density"},{"key": "D","text": "Age of patient"}],"correct": "A","explanation": "Young-Burgess system classifies pelvic ring injuries by injury mechanism/force vector."},{"id": 8313,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "Sacral fractures can be associated with injury to which structures, requiring neurological assessment?","options": [{"key": "A","text": "Brachial plexus"},{"key": "B","text": "Cervical spinal cord"},{"key": "C","text": "Cauda equina / sacral nerve roots (bowel/bladder function)"},{"key": "D","text": "Phrenic nerve"}],"correct": "C","explanation": "Sacral fractures risk cauda equina/sacral nerve root injury, affecting bowel, bladder, and sexual function."},{"id": 8314,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which spinal region fracture carries the highest risk of complete spinal cord injury due to narrow canal-to-cord ratio?","options": [{"key": "A","text": "Cervical spine (C3-C4) only"},{"key": "B","text": "Thoracic spine (T4-T9, watershed vascular zone)"},{"key": "C","text": "Sacral spine"},{"key": "D","text": "Lumbar spine"}],"correct": "B","explanation": "Mid-thoracic spine has a relatively narrow canal and watershed blood supply, making complete cord injury more likely with fracture-dislocation there."},{"id": 8315,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Physiotherapy management priorities immediately after stable vertebral compression fracture typically include:","options": [{"key": "A","text": "Pain management, postural education, avoiding flexion-based exercises initially, gradual mobilization"},{"key": "B","text": "Aggressive spinal flexion exercises"},{"key": "C","text": "Complete bed rest indefinitely"},{"key": "D","text": "Immediate high-impact activity"}],"correct": "A","explanation": "Early management focuses on pain control, extension-biased postural correction, avoiding excessive flexion loading, and gradual safe mobilization."},{"id": 8316,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "The most common direction of shoulder (glenohumeral) dislocation is:","options": [{"key": "A","text": "Superior"},{"key": "B","text": "Anterior"},{"key": "C","text": "Posterior"},{"key": "D","text": "Inferior"}],"correct": "B","explanation": "Anterior dislocation accounts for approximately 95% of shoulder dislocations."},{"id": 8317,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Posterior shoulder dislocation is classically associated with:","options": [{"key": "A","text": "FOOSH injury"},{"key": "B","text": "Seizures or electric shock"},{"key": "C","text": "Direct anterior blow"},{"key": "D","text": "Overhead throwing"}],"correct": "B","explanation": "Posterior dislocations are classically linked with seizures, electrocution, due to strong internal rotator contraction."},{"id": 8318,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Axillary nerve injury is a well-recognized complication of which shoulder injury?","options": [{"key": "A","text": "AC joint sprain"},{"key": "B","text": "Biceps tendinopathy"},{"key": "C","text": "Anterior shoulder dislocation"},{"key": "D","text": "Rotator cuff tendinopathy"}],"correct": "C","explanation": "Axillary nerve, closely related to the inferior glenohumeral joint capsule, is at risk during anterior dislocation."},{"id": 8319,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Easy","question": "'Luxatio erecta' refers to which type of shoulder dislocation?","options": [{"key": "A","text": "Posterior dislocation"},{"key": "B","text": "Inferior dislocation with arm fixed overhead"},{"key": "C","text": "Superior dislocation"},{"key": "D","text": "Anterior dislocation"}],"correct": "B","explanation": "Luxatio erecta is inferior glenohumeral dislocation, rare, arm held overhead."},{"id": 8320,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Elbow dislocations most commonly occur in which direction?","options": [{"key": "A","text": "Medial"},{"key": "B","text": "Anterior"},{"key": "C","text": "Lateral only"},{"key": "D","text": "Posterior (posterolateral)"}],"correct": "D","explanation": "Posterior/posterolateral elbow dislocation is the most common pattern, usually from FOOSH."},{"id": 8321,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which nerve is most at risk of injury during elbow dislocation?","options": [{"key": "A","text": "Ulnar nerve"},{"key": "B","text": "Median nerve (less commonly)"},{"key": "C","text": "Both ulnar and median can be affected, ulnar more common"},{"key": "D","text": "Radial nerve"}],"correct": "C","explanation": "Both nerves can be stretched/injured, though ulnar nerve involvement is relatively more frequently reported."},{"id": 8322,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'Nursemaid's elbow' refers to:","options": [{"key": "A","text": "Olecranon fracture"},{"key": "B","text": "Elbow dislocation in adults"},{"key": "C","text": "Radial head subluxation in young children"},{"key": "D","text": "Ulnar nerve entrapment"}],"correct": "C","explanation": "Nursemaid's elbow is a common radial head subluxation in toddlers from sudden longitudinal traction on the arm."},{"id": 8323,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Hip dislocations are most commonly which type?","options": [{"key": "A","text": "Central (protrusio)"},{"key": "B","text": "Inferior"},{"key": "C","text": "Anterior"},{"key": "D","text": "Posterior"}],"correct": "D","explanation": "Posterior hip dislocation accounts for approximately 90% of traumatic hip dislocations, typically from dashboard injury."},{"id": 8324,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Sciatic nerve injury is a recognized complication of which hip injury?","options": [{"key": "A","text": "Hip flexor strain"},{"key": "B","text": "Piriformis syndrome only"},{"key": "C","text": "Posterior hip dislocation"},{"key": "D","text": "Anterior hip dislocation"}],"correct": "C","explanation": "Sciatic nerve, running posterior to the hip joint, is at risk during posterior dislocation."},{"id": 8325,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Avascular necrosis of femoral head is a significant long-term risk following:","options": [{"key": "A","text": "Ankle sprain"},{"key": "B","text": "Knee dislocation"},{"key": "C","text": "Shoulder dislocation"},{"key": "D","text": "Hip dislocation, especially if reduction delayed"}],"correct": "D","explanation": "Disruption of the retinacular blood supply during hip dislocation predisposes to femoral head AVN, worsened by delayed reduction."},{"id": 8326,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Knee dislocations (tibiofemoral) are considered orthopedic emergencies primarily due to risk of:","options": [{"key": "A","text": "Osteoarthritis"},{"key": "B","text": "Patellar fracture"},{"key": "C","text": "Popliteal artery injury"},{"key": "D","text": "Meniscal tear only"}],"correct": "C","explanation": "High risk of popliteal artery injury demands urgent vascular assessment after knee dislocation."},{"id": 8327,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Patellar dislocation most commonly occurs in which direction?","options": [{"key": "A","text": "Inferior"},{"key": "B","text": "Medial"},{"key": "C","text": "Lateral"},{"key": "D","text": "Superior"}],"correct": "C","explanation": "Patella most commonly dislocates laterally, often related to VMO weakness, ligamentous laxity, or trochlear dysplasia."},{"id": 8328,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Hard","question": "Ankle dislocations are usually associated with:","options": [{"key": "A","text": "No bony injury typically"},{"key": "B","text": "Concurrent malleolar fracture (fracture-dislocation)"},{"key": "C","text": "Always without ligament injury"},{"key": "D","text": "Isolated soft tissue injury only"}],"correct": "B","explanation": "Ankle dislocations frequently occur alongside malleolar fractures due to high force required to dislocate this stable joint."},{"id": 8329,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Acromioclavicular (AC) joint injuries are graded using which classification?","options": [{"key": "A","text": "Garden classification"},{"key": "B","text": "Neer classification"},{"key": "C","text": "Rockwood classification"},{"key": "D","text": "Weber classification"}],"correct": "C","explanation": "Rockwood classification (Type I-VI) grades AC joint injury severity based on ligamentous disruption and displacement."},{"id": 8330,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "In Rockwood Type III AC joint injury, both the AC and coracoclavicular ligaments are:","options": [{"key": "A","text": "Only CC ligament torn"},{"key": "B","text": "Completely disrupted"},{"key": "C","text": "Only AC ligament torn"},{"key": "D","text": "Intact"}],"correct": "B","explanation": "Type III involves complete disruption of both AC and coracoclavicular ligaments with clavicle displaced 25-100%."},{"id": 8331,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sternoclavicular joint dislocation, though rare, is most concerning when it occurs in which direction due to mediastinal structure risk?","options": [{"key": "A","text": "Superior"},{"key": "B","text": "Anterior"},{"key": "C","text": "Posterior"},{"key": "D","text": "Inferior"}],"correct": "C","explanation": "Posterior SC dislocation risks compression of great vessels, trachea, esophagus in the mediastinum — a surgical emergency."},{"id": 8332,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Temporomandibular joint (TMJ) dislocation most commonly occurs in which direction?","options": [{"key": "A","text": "Anterior"},{"key": "B","text": "Posterior"},{"key": "C","text": "Superior"},{"key": "D","text": "Lateral"}],"correct": "A","explanation": "Anterior TMJ dislocation is most common, often from wide yawning or trauma, condyle displaced anterior to articular eminence."},{"id": 8333,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "First-time (primary) traumatic anterior shoulder dislocation in young athletic patients carries a high risk of:","options": [{"key": "A","text": "Recurrent instability"},{"key": "B","text": "Rotator cuff tear predominantly (elderly pattern)"},{"key": "C","text": "No further risk"},{"key": "D","text": "Frozen shoulder only"}],"correct": "A","explanation": "Young patients have significantly higher recurrence rates of instability after first dislocation compared to older patients."},{"id": 8334,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Reduction of an acute joint dislocation should ideally be performed:","options": [{"key": "A","text": "Never before imaging in any case"},{"key": "B","text": "Only in operating theatre always"},{"key": "C","text": "After 24 hours delay routinely"},{"key": "D","text": "As soon as possible after neurovascular assessment, to reduce complications"}],"correct": "D","explanation": "Prompt reduction (after appropriate assessment/analgesia) reduces risk of neurovascular compromise and cartilage damage."},{"id": 8335,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Post-reduction management of a first-time anterior shoulder dislocation typically includes:","options": [{"key": "A","text": "No immobilization needed"},{"key": "B","text": "Permanent restriction from overhead activity"},{"key": "C","text": "Immediate full-contact sport"},{"key": "D","text": "Period of immobilization followed by progressive rehabilitation of rotator cuff and scapular stabilizers"}],"correct": "D","explanation": "Brief immobilization followed by structured rehab focusing on dynamic stabilizers helps reduce recurrence risk and restore function."},{"id": 8336,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Voluntary/habitual dislocation' of a joint, typically seen in hypermobile individuals, is best managed primarily with:","options": [{"key": "A","text": "Immediate immobilization only"},{"key": "B","text": "Injection therapy as first line"},{"key": "C","text": "Surgery as first line"},{"key": "D","text": "Muscle strengthening/motor control rehabilitation programs"}],"correct": "D","explanation": "Rehabilitation focusing on dynamic muscular stability is the first-line approach in atraumatic/voluntary instability."},{"id": 8337,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Congenital hip dislocation is more accurately termed:","options": [{"key": "A","text": "Coxa vara"},{"key": "B","text": "Developmental dysplasia of the hip (DDH)"},{"key": "C","text": "Perthes disease"},{"key": "D","text": "Slipped capital femoral epiphysis"}],"correct": "B","explanation": "The modern preferred term is Developmental Dysplasia of the Hip (DDH), reflecting the spectrum of abnormal development."},{"id": 8338,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Recurrent patellar dislocation is most associated with which anatomical predisposing factor?","options": [{"key": "A","text": "Tight hamstrings only"},{"key": "B","text": "Genu varum only"},{"key": "C","text": "Pes planus only"},{"key": "D","text": "Trochlear dysplasia and patella alta"}],"correct": "D","explanation": "Trochlear dysplasia (shallow groove) and patella alta are key anatomical risk factors for recurrent lateral patellar instability."},{"id": 8339,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Immediate management of a suspected dislocated joint in the field/pre-hospital setting should focus on:","options": [{"key": "A","text": "Forceful reduction attempts by untrained personnel"},{"key": "B","text": "Ignoring until hospital imaging"},{"key": "C","text": "Aggressive ROM exercises"},{"key": "D","text": "Immobilization in position found, neurovascular check, and urgent transfer"}],"correct": "D","explanation": "Field management prioritizes splinting/immobilizing, checking distal neurovascular status, and prompt transport for definitive care."},{"id": 8340,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following joints is inherently most stable and least commonly dislocated due to bony congruency?","options": [{"key": "A","text": "Shoulder joint"},{"key": "B","text": "Hip joint"},{"key": "C","text": "Acromioclavicular joint"},{"key": "D","text": "Patellofemoral joint"}],"correct": "B","explanation": "The hip's deep, congruent ball-and-socket architecture makes it inherently more stable than the shallow glenohumeral joint, requiring high-energy trauma to dislocate."},{"id": 8341,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "A Grade I ligament sprain is characterized by:","options": [{"key": "A","text": "Mild stretching with microscopic tearing, minimal instability"},{"key": "B","text": "Partial tear with some laxity"},{"key": "C","text": "Complete tear with instability"},{"key": "D","text": "Avulsion fracture"}],"correct": "A","explanation": "Grade I = mild sprain, stretching/microtearing without significant joint instability."},{"id": 8342,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "A Grade III ligament sprain involves:","options": [{"key": "A","text": "Mild stretching only"},{"key": "B","text": "Complete rupture with joint instability"},{"key": "C","text": "No structural damage"},{"key": "D","text": "Partial tear, some laxity, firm end feel"}],"correct": "B","explanation": "Grade III = complete ligament tear, significant instability, often with an empty end feel."},{"id": 8343,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Muscle strain grading uses a similar 3-grade system; Grade II muscle strain indicates:","options": [{"key": "A","text": "Partial tearing of muscle fibers with some loss of strength/function"},{"key": "B","text": "Complete rupture"},{"key": "C","text": "No fiber disruption"},{"key": "D","text": "Only tendon involvement"}],"correct": "A","explanation": "Grade II strain = partial tear, moderate pain and functional loss, palpable defect may be absent."},{"id": 8344,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which phase of soft tissue healing is characterized by fibroblast proliferation and collagen synthesis, typically days 3 to 21?","options": [{"key": "A","text": "Inflammatory phase"},{"key": "B","text": "Hemostasis phase"},{"key": "C","text": "Proliferative (repair) phase"},{"key": "D","text": "Remodeling phase"}],"correct": "C","explanation": "Proliferative phase involves fibroblast activity, granulation tissue, and collagen deposition."},{"id": 8345,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The remodeling phase of soft tissue healing can continue for how long after injury?","options": [{"key": "A","text": "2-3 weeks"},{"key": "B","text": "Only 3 days"},{"key": "C","text": "Up to 1-2 years"},{"key": "D","text": "1 week"}],"correct": "C","explanation": "Remodeling/maturation phase, involving collagen realignment along stress lines, can continue for months to over a year."},{"id": 8346,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "During the inflammatory phase of healing, physiotherapy management should primarily focus on:","options": [{"key": "A","text": "Maximal strengthening"},{"key": "B","text": "Return to sport"},{"key": "C","text": "Protection, relative rest, and controlling inflammation (PRICE/POLICE)"},{"key": "D","text": "Aggressive stretching"}],"correct": "C","explanation": "Early phase management protects healing tissue while controlling swelling/pain (Protection, Optimal Loading, Ice, Compression, Elevation)."},{"id": 8347,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'POLICE' principle (updated from RICE) emphasizes:","options": [{"key": "A","text": "Complete rest throughout recovery"},{"key": "B","text": "Protection and Optimal Loading instead of complete rest"},{"key": "C","text": "Ice and elevation only"},{"key": "D","text": "Compression alone"}],"correct": "B","explanation": "POLICE = Protection, Optimal Loading, Ice, Compression, Elevation — emphasizing early controlled loading over strict rest."},{"id": 8348,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Tendinopathy is now understood pathologically to primarily involve:","options": [{"key": "A","text": "Acute inflammation (tendinitis) in all cases"},{"key": "B","text": "Bacterial infection"},{"key": "C","text": "Degenerative changes with collagen disorganization (tendinosis), often without significant inflammation"},{"key": "D","text": "Complete rupture always"}],"correct": "C","explanation": "Chronic tendinopathy shows degenerative, non-inflammatory changes (tendinosis) rather than classic inflammation."},{"id": 8349,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Achilles tendinopathy commonly affects which zone of the tendon?","options": [{"key": "A","text": "Musculotendinous junction only"},{"key": "B","text": "Mid-portion (2-6cm proximal to insertion) - watershed zone"},{"key": "C","text": "Insertion at calcaneus only"},{"key": "D","text": "Proximal muscle belly"}],"correct": "B","explanation": "Mid-portion Achilles tendinopathy occurs in a relatively hypovascular watershed zone, most commonly affected."},{"id": 8350,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which is the most common site for a hamstring muscle strain?","options": [{"key": "A","text": "Bony insertion only"},{"key": "B","text": "Muscle belly mid-substance always"},{"key": "C","text": "Distal tendon only"},{"key": "D","text": "Musculotendinous junction, especially biceps femoris"}],"correct": "D","explanation": "Hamstring strains most commonly occur at the proximal musculotendinous junction, biceps femoris long head most affected."},{"id": 8351,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Rotator cuff tendinopathy is commonly associated with which mechanism?","options": [{"key": "A","text": "Genetic factors alone"},{"key": "B","text": "Subacromial impingement and repetitive overhead activity"},{"key": "C","text": "Direct trauma only"},{"key": "D","text": "Cold exposure"}],"correct": "B","explanation": "Repetitive mechanical impingement under the coracoacromial arch contributes significantly to rotator cuff tendinopathy."},{"id": 8352,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Lateral epicondylitis (tennis elbow) primarily involves degeneration of which tendon origin?","options": [{"key": "A","text": "Flexor carpi radialis"},{"key": "B","text": "Flexor digitorum superficialis"},{"key": "C","text": "Extensor carpi radialis brevis (ECRB)"},{"key": "D","text": "Pronator teres"}],"correct": "C","explanation": "ECRB origin at the lateral epicondyle is the classic site of degenerative changes in lateral epicondylitis."},{"id": 8353,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "Medial epicondylitis (golfer's elbow) primarily involves the common flexor-pronator origin, especially:","options": [{"key": "A","text": "Biceps tendon"},{"key": "B","text": "Extensor carpi radialis brevis"},{"key": "C","text": "Triceps tendon"},{"key": "D","text": "Flexor carpi radialis and pronator teres"}],"correct": "D","explanation": "Flexor carpi radialis and pronator teres origins at the medial epicondyle are commonly involved."},{"id": 8354,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Patellar tendinopathy ('jumper's knee') most commonly affects which part of the tendon?","options": [{"key": "A","text": "Proximal (inferior pole of patella)"},{"key": "B","text": "Distal insertion at tibial tuberosity"},{"key": "C","text": "Quadriceps tendon"},{"key": "D","text": "Mid-substance only"}],"correct": "A","explanation": "Jumper's knee classically affects the proximal patellar tendon at its origin from the inferior pole of the patella."},{"id": 8355,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "De Quervain's tenosynovitis involves which tendons?","options": [{"key": "A","text": "Flexor pollicis longus"},{"key": "B","text": "Extensor carpi ulnaris"},{"key": "C","text": "Abductor pollicis longus and extensor pollicis brevis"},{"key": "D","text": "Flexor digitorum profundus"}],"correct": "C","explanation": "De Quervain's affects APL and EPB tendons within the first dorsal compartment of the wrist."},{"id": 8356,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Trigger finger is caused by:","options": [{"key": "A","text": "Nerve compression only"},{"key": "B","text": "Extensor tendon rupture"},{"key": "C","text": "Ligament laxity"},{"key": "D","text": "Nodular thickening of flexor tendon causing catching at A1 pulley"}],"correct": "D","explanation": "Thickening/nodule on flexor tendon catches at the A1 pulley, causing locking/triggering."},{"id": 8357,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Rotator cuff full-thickness tears most commonly involve which tendon?","options": [{"key": "A","text": "Subscapularis"},{"key": "B","text": "Teres minor"},{"key": "C","text": "Infraspinatus"},{"key": "D","text": "Supraspinatus"}],"correct": "D","explanation": "Supraspinatus tendon, subject to greatest mechanical stress and relative avascularity, is most commonly torn."},{"id": 8358,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "An ACL tear commonly occurs via which mechanism?","options": [{"key": "A","text": "Axial loading in full extension only"},{"key": "B","text": "Non-contact deceleration/pivoting with valgus and rotation stress"},{"key": "C","text": "Hyperflexion without rotation"},{"key": "D","text": "Direct blow to anterior tibia only"}],"correct": "B","explanation": "Non-contact mechanisms involving deceleration, cutting, pivoting with knee valgus/rotation are classic ACL injury mechanisms."},{"id": 8359,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "MCL injuries of the knee commonly result from:","options": [{"key": "A","text": "Direct blow to medial knee"},{"key": "B","text": "Varus stress"},{"key": "C","text": "Hyperextension only"},{"key": "D","text": "Valgus stress with the foot planted"}],"correct": "D","explanation": "Valgus force applied to a planted, slightly flexed knee is the classic MCL injury mechanism."},{"id": 8360,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Meniscal tears frequently occur in combination with which ligament injury (unhappy triad)?","options": [{"key": "A","text": "MCL and LCL"},{"key": "B","text": "PCL and LCL"},{"key": "C","text": "ACL and MCL"},{"key": "D","text": "ACL and PCL"}],"correct": "C","explanation": "O'Donoghue's unhappy triad classically includes ACL, MCL, and medial meniscus injury."},{"id": 8361,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Ankle inversion sprains most commonly injure which ligament first?","options": [{"key": "A","text": "Anterior talofibular ligament (ATFL)"},{"key": "B","text": "Posterior talofibular ligament"},{"key": "C","text": "Deltoid ligament"},{"key": "D","text": "Calcaneofibular ligament (CFL)"}],"correct": "A","explanation": "ATFL is the weakest and most frequently injured ligament in inversion ankle sprains."},{"id": 8362,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "High ankle (syndesmotic) sprains involve injury to:","options": [{"key": "A","text": "Lateral collateral ligament complex only"},{"key": "B","text": "Distal tibiofibular ligaments (AITFL, PITFL, interosseous ligament)"},{"key": "C","text": "Plantar fascia"},{"key": "D","text": "Deltoid ligament only"}],"correct": "B","explanation": "Syndesmotic sprains involve the ligaments connecting distal tibia and fibula, often from external rotation/dorsiflexion mechanism."},{"id": 8363,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Rotator cuff tendinopathy staging by Neer includes which stages?","options": [{"key": "A","text": "Only acute and chronic"},{"key": "B","text": "Not staged, only graded by MRI"},{"key": "C","text": "Edema/hemorrhage, fibrosis/tendinitis, tears/bony changes"},{"key": "D","text": "4 stages based on ROM"}],"correct": "C","explanation": "Neer's 3-stage classification progresses from reversible edema to fibrosis to partial/complete tears with bone changes."},{"id": 8364,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Whiplash-associated disorder typically results from which mechanism?","options": [{"key": "A","text": "Prolonged static posture only"},{"key": "B","text": "Sudden acceleration-deceleration of cervical spine (e.g., rear-end collision)"},{"key": "C","text": "Repetitive overuse"},{"key": "D","text": "Direct blow to head"}],"correct": "B","explanation": "Whiplash results from rapid hyperextension-hyperflexion of the neck typically in vehicle collisions."},{"id": 8365,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Muscle contusion severity is often graded based on:","options": [{"key": "A","text": "Presence of fracture always"},{"key": "B","text": "Tendon involvement only"},{"key": "C","text": "Skin color change alone"},{"key": "D","text": "Amount of hemorrhage/hematoma and resultant ROM loss"}],"correct": "D","explanation": "Contusion severity correlates with degree of intramuscular hemorrhage and functional (ROM) loss."},{"id": 8366,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Myositis ossificans' is a potential complication of:","options": [{"key": "A","text": "Tendon overuse only"},{"key": "B","text": "Ligament sprain"},{"key": "C","text": "Nerve injury"},{"key": "D","text": "Repeated/severe muscle contusion with aggressive early mobilization"}],"correct": "D","explanation": "Ectopic bone formation within muscle can occur after significant contusion, exacerbated by premature aggressive stretching/massage."},{"id": 8367,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Eccentric exercise programs (e.g., Alfredson protocol) are a well-supported treatment for:","options": [{"key": "A","text": "Fresh muscle tear (grade III)"},{"key": "B","text": "Acute ligament sprain"},{"key": "C","text": "Fracture"},{"key": "D","text": "Achilles tendinopathy"}],"correct": "D","explanation": "Heavy slow resistance/eccentric loading protocols (like Alfredson) are evidence-based for chronic Achilles tendinopathy."},{"id": 8368,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which imaging modality is generally best for evaluating soft tissue injuries such as ligament and muscle tears?","options": [{"key": "A","text": "Plain X-ray"},{"key": "B","text": "MRI"},{"key": "C","text": "Bone scan"},{"key": "D","text": "CT scan"}],"correct": "B","explanation": "MRI provides superior soft tissue contrast, ideal for evaluating ligaments, tendons, and muscles."},{"id": 8369,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "Diagnostic ultrasound is particularly useful in soft tissue assessment for:","options": [{"key": "A","text": "Bone density measurement"},{"key": "B","text": "Dynamic, real-time assessment of tendons and muscles including tears"},{"key": "C","text": "Spinal cord imaging"},{"key": "D","text": "Deep bone marrow evaluation"}],"correct": "B","explanation": "Ultrasound allows dynamic real-time evaluation of superficial soft tissue structures like tendons and muscles."},{"id": 8370,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following best describes 'tendinosis' pathologically?","options": [{"key": "A","text": "Calcific deposits only"},{"key": "B","text": "Complete tendon rupture"},{"key": "C","text": "Acute inflammatory cell infiltration"},{"key": "D","text": "Chronic degeneration with disorganized collagen and neovascularization, minimal inflammation"}],"correct": "D","explanation": "Tendinosis is characterized by collagen disorganization, increased ground substance, and neovascularization without significant inflammatory cells."},{"id": 8371,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Groin strain (adductor strain) most commonly involves which muscle?","options": [{"key": "A","text": "Pectineus"},{"key": "B","text": "Adductor longus"},{"key": "C","text": "Adductor magnus"},{"key": "D","text": "Gracilis"}],"correct": "B","explanation": "Adductor longus is the most commonly strained groin muscle, especially in kicking/cutting sports."},{"id": 8372,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Calf muscle strain ('tennis leg') classically involves which muscle?","options": [{"key": "A","text": "Soleus"},{"key": "B","text": "Tibialis posterior"},{"key": "C","text": "Plantaris only"},{"key": "D","text": "Medial head of gastrocnemius"}],"correct": "D","explanation": "Tennis leg classically involves a strain/partial tear of the medial gastrocnemius head, often at the musculotendinous junction."},{"id": 8373,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "Which structure is commonly injured in a 'jersey finger' injury?","options": [{"key": "A","text": "Extensor tendon central slip"},{"key": "B","text": "Volar plate"},{"key": "C","text": "Flexor digitorum profundus tendon avulsion"},{"key": "D","text": "Collateral ligament of PIP"}],"correct": "C","explanation": "Jersey finger is an avulsion of the FDP tendon insertion, typically from forced extension during active flexion (e.g., grabbing a jersey)."},{"id": 8374,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "'Mallet finger' results from injury to the:","options": [{"key": "A","text": "Central slip at PIP"},{"key": "B","text": "Collateral ligament"},{"key": "C","text": "FDP tendon"},{"key": "D","text": "Terminal extensor tendon at DIP joint"}],"correct": "D","explanation": "Mallet finger is due to disruption of the terminal extensor tendon insertion at the distal phalanx, causing DIP droop."},{"id": 8375,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Boutonniere deformity' results from injury to which structure?","options": [{"key": "A","text": "Central slip of extensor tendon at PIP joint"},{"key": "B","text": "Terminal extensor tendon at DIP"},{"key": "C","text": "Volar plate"},{"key": "D","text": "FDP tendon"}],"correct": "A","explanation": "Central slip rupture allows PIP flexion with compensatory DIP hyperextension, producing boutonniere deformity."},{"id": 8376,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Swan neck deformity' involves:","options": [{"key": "A","text": "No joint involvement"},{"key": "B","text": "MCP flexion with PIP flexion"},{"key": "C","text": "PIP flexion with DIP hyperextension"},{"key": "D","text": "PIP hyperextension with DIP flexion"}],"correct": "D","explanation": "Swan neck: PIP hyperextension and DIP flexion, often from volar plate laxity or FDS dysfunction."},{"id": 8377,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Skier's thumb (gamekeeper's thumb) involves injury to which structure?","options": [{"key": "A","text": "Radial collateral ligament of thumb"},{"key": "B","text": "Flexor pollicis longus"},{"key": "C","text": "Extensor pollicis brevis"},{"key": "D","text": "Ulnar collateral ligament of thumb MCP joint"}],"correct": "D","explanation": "UCL of the thumb MCP joint is injured classically from forced radial/valgus deviation, e.g., ski pole fall."},{"id": 8378,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Rotator cuff tear management in elderly, low-demand patients with degenerative tears is often:","options": [{"key": "A","text": "Conservative physiotherapy management first-line"},{"key": "B","text": "Only pain medication with no rehab"},{"key": "C","text": "No treatment at all"},{"key": "D","text": "Immediate surgery always"}],"correct": "A","explanation": "Conservative management (exercise-based rehabilitation) is often first-line for degenerative cuff tears, especially in lower-demand elderly patients."},{"id": 8379,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which factor is most predictive of poor healing potential in a meniscal tear?","options": [{"key": "A","text": "Peripheral tear location"},{"key": "B","text": "Young patient age"},{"key": "C","text": "Location in the avascular (white-white) zone"},{"key": "D","text": "Location in the vascular (red-red) zone"}],"correct": "C","explanation": "Tears in the avascular inner zone have poor healing potential due to lack of blood supply, unlike peripheral red-red zone tears."},{"id": 8380,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Plantar fasciitis is best described pathologically as primarily:","options": [{"key": "A","text": "Infectious process"},{"key": "B","text": "Autoimmune condition"},{"key": "C","text": "Acute inflammatory condition always"},{"key": "D","text": "Chronic degenerative process (fasciosis) similar to tendinopathy"}],"correct": "D","explanation": "Chronic plantar fasciitis shows degenerative collagen changes similar to tendinosis rather than pure inflammation."},{"id": 8381,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which structure is most commonly implicated in 'shin splints' (medial tibial stress syndrome)?","options": [{"key": "A","text": "Periosteum and surrounding soft tissue at posteromedial tibial border"},{"key": "B","text": "Fibula"},{"key": "C","text": "Anterior compartment muscles only"},{"key": "D","text": "Achilles tendon"}],"correct": "A","explanation": "MTSS involves periostitis/traction stress at the posteromedial tibial border from repetitive loading."},{"id": 8382,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Return-to-sport criteria after significant ligament/muscle injury should be based primarily on:","options": [{"key": "A","text": "X-ray findings alone"},{"key": "B","text": "Patient's request only"},{"key": "C","text": "Functional testing, strength symmetry, and psychological readiness combined with time"},{"key": "D","text": "Time since injury alone"}],"correct": "C","explanation": "Modern return-to-sport decisions integrate objective functional/strength testing and psychological readiness, not just elapsed time."},{"id": 8383,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which of the following best differentiates a Grade II from Grade III ligament sprain clinically?","options": [{"key": "A","text": "No difference clinically"},{"key": "B","text": "Grade III has less pain than Grade II"},{"key": "C","text": "Grade II always requires surgery"},{"key": "D","text": "Presence of joint laxity with firm end feel (II) vs gross instability with empty end feel (III)"}],"correct": "D","explanation": "Grade II shows partial tearing with some laxity but a firm end point; Grade III shows complete tear with gross instability and often no firm end feel."},{"id": 8384,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Corticosteroid injections in tendinopathy management are generally associated with:","options": [{"key": "A","text": "Always curative"},{"key": "B","text": "No effect whatsoever"},{"key": "C","text": "Short-term pain relief but possible risk to tendon integrity with repeated use"},{"key": "D","text": "Long-term structural improvement of tendon"}],"correct": "C","explanation": "While providing short-term symptomatic relief, repeated corticosteroid injections may weaken tendon structure and increase rupture risk."},{"id": 8385,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following exercise types has the strongest evidence base for chronic tendinopathy rehabilitation?","options": [{"key": "A","text": "Progressive loading programs including isometric, eccentric, and heavy slow resistance training"},{"key": "B","text": "Aggressive stretching only"},{"key": "C","text": "Complete rest until pain-free"},{"key": "D","text": "Passive modalities alone (ultrasound only)"}],"correct": "A","explanation": "Progressive tendon loading protocols (isometric to isotonic/eccentric to energy-storage exercises) form the evidence-based cornerstone of tendinopathy rehab."},{"id": 8386,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Adhesive capsulitis (frozen shoulder) is characterized by which classic capsular pattern?","options": [{"key": "A","text": "External rotation most limited, then abduction, then internal rotation"},{"key": "B","text": "Internal rotation most limited"},{"key": "C","text": "Flexion most limited"},{"key": "D","text": "Extension most limited"}],"correct": "A","explanation": "Frozen shoulder follows the classic capsular pattern with external rotation most restricted."},{"id": 8387,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Adhesive capsulitis is more commonly seen in which population?","options": [{"key": "A","text": "Elderly males only"},{"key": "B","text": "Children"},{"key": "C","text": "Diabetics and individuals aged 40-60 years"},{"key": "D","text": "Young athletes"}],"correct": "C","explanation": "Frozen shoulder has a strong association with diabetes mellitus and typically affects the 40-60 age group, more common in women."},{"id": 8388,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The 'freezing' stage of adhesive capsulitis is characterized by:","options": [{"key": "A","text": "Progressive pain with increasing stiffness"},{"key": "B","text": "Gradual return of ROM"},{"key": "C","text": "No symptoms"},{"key": "D","text": "Pain resolving with stiffness remaining"}],"correct": "A","explanation": "Freezing stage: progressive pain and gradually worsening restriction of motion, lasting weeks to months."},{"id": 8389,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The 'frozen' (adhesive) stage of adhesive capsulitis is characterized by:","options": [{"key": "A","text": "Full ROM with pain"},{"key": "B","text": "Predominant stiffness with reduced pain"},{"key": "C","text": "Complete resolution"},{"key": "D","text": "Predominant pain with minimal stiffness"}],"correct": "B","explanation": "Frozen stage: pain often decreases while significant stiffness/restriction persists, lasting months."},{"id": 8390,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'thawing' stage of adhesive capsulitis is marked by:","options": [{"key": "A","text": "Gradual improvement in ROM over months"},{"key": "B","text": "Persistent severe pain"},{"key": "C","text": "No functional recovery"},{"key": "D","text": "Sudden worsening of symptoms"}],"correct": "A","explanation": "Thawing stage: gradual spontaneous improvement in range of motion over months to years."},{"id": 8391,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Subacromial impingement syndrome primarily involves compression of structures between:","options": [{"key": "A","text": "Clavicle and first rib"},{"key": "B","text": "Humeral head and acromion/coracoacromial arch"},{"key": "C","text": "Glenoid and labrum"},{"key": "D","text": "Scapula and rib cage"}],"correct": "B","explanation": "Impingement occurs when subacromial structures (cuff tendons, bursa) are compressed against the coracoacromial arch."},{"id": 8392,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which classification describes the three stages of subacromial impingement (Neer)?","options": [{"key": "A","text": "Mild, moderate, severe based only on age"},{"key": "B","text": "Type I, II, III based on ROM"},{"key": "C","text": "Edema/hemorrhage, fibrosis/tendinitis, tears with bony changes"},{"key": "D","text": "Grade A, B, C based on pain"}],"correct": "C","explanation": "Neer's classification: Stage I (edema/hemorrhage, reversible), Stage II (fibrosis/tendinitis), Stage III (tears, bony changes)."},{"id": 8393,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which acromion morphology (Bigliani classification) is most associated with impingement/cuff tears?","options": [{"key": "A","text": "Type II (curved)"},{"key": "B","text": "Type I (flat)"},{"key": "C","text": "Type III (hooked)"},{"key": "D","text": "Type IV (convex)"}],"correct": "C","explanation": "Type III hooked acromion is most strongly associated with subacromial impingement and rotator cuff pathology."},{"id": 8394,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Easy","question": "Calcific tendinitis of the shoulder most commonly affects which tendon?","options": [{"key": "A","text": "Long head of biceps"},{"key": "B","text": "Subscapularis"},{"key": "C","text": "Supraspinatus"},{"key": "D","text": "Infraspinatus"}],"correct": "C","explanation": "Calcific deposits most commonly occur in the supraspinatus tendon, in its critical zone near insertion."},{"id": 8395,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Rotator cuff arthropathy refers to:","options": [{"key": "A","text": "Glenohumeral arthritis secondary to chronic massive rotator cuff tear"},{"key": "B","text": "Acute tendinitis"},{"key": "C","text": "Simple AC joint arthritis"},{"key": "D","text": "Isolated labral tear"}],"correct": "A","explanation": "Long-standing massive cuff tears lead to superior humeral head migration and secondary glenohumeral joint degeneration."},{"id": 8396,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "SLAP lesion refers to tearing of the:","options": [{"key": "A","text": "Inferior labrum"},{"key": "B","text": "Rotator cuff insertion"},{"key": "C","text": "AC joint capsule"},{"key": "D","text": "Superior labrum from anterior to posterior"}],"correct": "D","explanation": "SLAP = Superior Labrum Anterior to Posterior tear, often involving the biceps anchor."},{"id": 8397,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Multidirectional instability (MDI) of the shoulder is best managed initially with:","options": [{"key": "A","text": "Immediate immobilization only"},{"key": "B","text": "Injection therapy first-line"},{"key": "C","text": "Physiotherapy focusing on dynamic stabilizer strengthening"},{"key": "D","text": "Surgery as first-line"}],"correct": "C","explanation": "MDI, often related to capsular laxity, typically responds well to rotator cuff/scapular stabilizer strengthening before considering surgery."},{"id": 8398,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Scapular dyskinesis refers to:","options": [{"key": "A","text": "Fracture of scapula"},{"key": "B","text": "Abnormal scapular positioning/motion pattern during arm movement"},{"key": "C","text": "Normal scapular rhythm"},{"key": "D","text": "AC joint dislocation"}],"correct": "B","explanation": "Scapular dyskinesis describes altered scapular position or motion, often contributing to shoulder dysfunction/impingement."},{"id": 8399,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Winging of the scapula' due to serratus anterior weakness is best tested by:","options": [{"key": "A","text": "Apprehension test"},{"key": "B","text": "Speed's test"},{"key": "C","text": "Empty can test"},{"key": "D","text": "Wall push-up test"}],"correct": "D","explanation": "Wall push-up (or resisted forward punch) accentuates medial scapular winging in serratus anterior weakness."},{"id": 8400,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'SICK scapula syndrome' stands for:","options": [{"key": "A","text": "None of the above"},{"key": "B","text": "Scapular malposition, Inferior medial border prominence, Coracoid pain, dysKinesis"},{"key": "C","text": "Superior Impingement Chronic Kinetic"},{"key": "D","text": "Scapular Instability, Cuff, Kyphosis"}],"correct": "B","explanation": "SICK scapula = Scapular malposition, Inferior medial border prominence, Coracoid pain and malposition, dysKinesis of scapular movement."},{"id": 8401,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Glenohumeral osteoarthritis typically presents with limitation predominantly in:","options": [{"key": "A","text": "Only internal rotation"},{"key": "B","text": "Only flexion"},{"key": "C","text": "External rotation and abduction"},{"key": "D","text": "No specific pattern"}],"correct": "C","explanation": "Similar to capsular pattern, GH OA often shows greatest restriction in external rotation and abduction."},{"id": 8402,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Thoracic outlet syndrome most commonly involves compression of neurovascular structures at which site(s)?","options": [{"key": "A","text": "Suprascapular notch only"},{"key": "B","text": "Interscalene triangle, costoclavicular space, or subpectoral space"},{"key": "C","text": "Carpal tunnel"},{"key": "D","text": "Cubital tunnel"}],"correct": "B","explanation": "TOS can occur at the interscalene triangle, costoclavicular space, or beneath pectoralis minor (subcoracoid space)."},{"id": 8403,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Suprascapular nerve entrapment commonly occurs at which anatomical site?","options": [{"key": "A","text": "Cubital tunnel"},{"key": "B","text": "Quadrilateral space"},{"key": "C","text": "Carpal tunnel"},{"key": "D","text": "Suprascapular notch or spinoglenoid notch"}],"correct": "D","explanation": "Suprascapular nerve is vulnerable at the suprascapular notch (affecting supra- and infraspinatus) or spinoglenoid notch (infraspinatus only)."},{"id": 8404,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Quadrilateral space syndrome involves compression of which nerve?","options": [{"key": "A","text": "Suprascapular nerve"},{"key": "B","text": "Axillary nerve"},{"key": "C","text": "Musculocutaneous nerve"},{"key": "D","text": "Radial nerve"}],"correct": "B","explanation": "Axillary nerve and posterior circumflex humeral artery pass through the quadrilateral space, vulnerable to compression there."},{"id": 8405,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Biceps tendon instability/subluxation is most closely associated with pathology of the:","options": [{"key": "A","text": "Transverse humeral ligament and subscapularis"},{"key": "B","text": "AC joint"},{"key": "C","text": "Rotator interval only"},{"key": "D","text": "Coracoacromial ligament"}],"correct": "A","explanation": "The transverse humeral ligament and subscapularis tendon stabilize the biceps tendon in the bicipital groove; their compromise causes instability."},{"id": 8406,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Os acromiale (unfused acromial ossification center) can predispose to:","options": [{"key": "A","text": "AC joint dislocation only"},{"key": "B","text": "Labral tear specifically"},{"key": "C","text": "Frozen shoulder specifically"},{"key": "D","text": "Subacromial impingement"}],"correct": "D","explanation": "An unfused acromial fragment can be unstable and contribute to impingement symptoms."},{"id": 8407,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which physiotherapy modality/technique is commonly used in the 'freezing' stage of adhesive capsulitis to manage pain?","options": [{"key": "A","text": "Gentle pain-free ROM, modalities for pain relief, avoiding aggressive stretching"},{"key": "B","text": "High-intensity strengthening"},{"key": "C","text": "Aggressive manual stretching into pain"},{"key": "D","text": "Immediate manipulation under anesthesia"}],"correct": "A","explanation": "In the acute/freezing stage, gentle pain management approaches are favored over aggressive stretching which may exacerbate inflammation."},{"id": 8408,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "In the 'frozen' stage of adhesive capsulitis, physiotherapy emphasis typically shifts to:","options": [{"key": "A","text": "Only pain modalities"},{"key": "B","text": "More vigorous mobilization and stretching to restore ROM"},{"key": "C","text": "Avoiding all movement"},{"key": "D","text": "Complete rest"}],"correct": "B","explanation": "As pain subsides in the frozen stage, more assertive mobilization/stretching techniques can be introduced to address stiffness."},{"id": 8409,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Easy","question": "Which grade of mobilization (Maitland) is typically preferred for pain-dominant shoulder conditions?","options": [{"key": "A","text": "Grade V (manipulation)"},{"key": "B","text": "Grade I-II (small amplitude, within available range)"},{"key": "C","text": "Grade III-IV (large amplitude, into resistance)"},{"key": "D","text": "No mobilization indicated"}],"correct": "B","explanation": "Grade I-II oscillations are generally used for pain modulation in acute/painful presentations."},{"id": 8410,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Medium","question": "Which grade of mobilization is typically used to address stiffness/restricted ROM once pain has settled?","options": [{"key": "A","text": "Grade III-IV (larger amplitude into resistance)"},{"key": "B","text": "Grade V exclusively for all cases"},{"key": "C","text": "No mobilization needed"},{"key": "D","text": "Grade I only"}],"correct": "A","explanation": "Grade III-IV mobilizations, performed into tissue resistance, are used to address stiffness once acute pain has reduced."},{"id": 8411,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Post-rotator cuff repair rehabilitation typically begins with which phase?","options": [{"key": "A","text": "Immediate return to overhead sport"},{"key": "B","text": "Protective phase with passive/assisted ROM only, protecting the repair"},{"key": "C","text": "No restriction on movement"},{"key": "D","text": "Immediate aggressive strengthening"}],"correct": "B","explanation": "Early post-op phase protects the repair with passive/assisted motion, avoiding active contraction of repaired tendon per surgeon protocol."},{"id": 8412,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Scapular stabilization exercises are particularly important in rehabilitation of:","options": [{"key": "A","text": "Ankle sprains"},{"key": "B","text": "Subacromial impingement and scapular dyskinesis"},{"key": "C","text": "Hip OA"},{"key": "D","text": "Isolated wrist fractures"}],"correct": "B","explanation": "Improving scapular control/positioning reduces abnormal subacromial mechanics contributing to impingement."},{"id": 8413,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Pectoralis minor tightness can contribute to which shoulder dysfunction?","options": [{"key": "A","text": "Anterior tilt and internal rotation of scapula, contributing to impingement"},{"key": "B","text": "Improved scapular upward rotation"},{"key": "C","text": "Posterior tilt of scapula"},{"key": "D","text": "No functional effect"}],"correct": "A","explanation": "Tight pectoralis minor pulls the scapula into anterior tilt/internal rotation/protraction, altering normal scapulohumeral mechanics."},{"id": 8414,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "Which special test differentiates internal (subacromial) impingement from AC joint pathology by comparing pain location?","options": [{"key": "A","text": "O'Brien's active compression test"},{"key": "B","text": "Apprehension test"},{"key": "C","text": "Sulcus sign"},{"key": "D","text": "Empty can test alone"}],"correct": "A","explanation": "O'Brien's test uses arm position (pronated vs supinated) and pain location (top of shoulder for AC vs inside for labral) to differentiate pathology."},{"id": 8415,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Internal impingement of the shoulder (posterosuperior glenoid impingement) is typically seen in:","options": [{"key": "A","text": "Overhead throwing athletes"},{"key": "B","text": "Post-fracture patients only"},{"key": "C","text": "Sedentary elderly patients"},{"key": "D","text": "Non-athletic population primarily"}],"correct": "A","explanation": "Internal impingement occurs from repetitive abduction-external rotation loading in throwing athletes, causing undersurface cuff/labral contact."},{"id": 8416,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "GIRD (Glenohumeral Internal Rotation Deficit) is commonly seen in which population and is associated with:","options": [{"key": "A","text": "Not clinically relevant"},{"key": "B","text": "Overhead athletes; posterior capsule tightness"},{"key": "C","text": "General population equally; anterior instability"},{"key": "D","text": "Elderly with OA only; anterior tightness"}],"correct": "B","explanation": "GIRD, common in throwers, is associated with posterior capsular/muscular tightness altering the humeral rotation arc."},{"id": 8417,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'sleeper stretch' is commonly prescribed to address:","options": [{"key": "A","text": "AC joint stiffness"},{"key": "B","text": "Anterior capsule laxity"},{"key": "C","text": "Posterior capsule/GIRD tightness"},{"key": "D","text": "Biceps tendinopathy"}],"correct": "C","explanation": "Sleeper stretch (side-lying, internal rotation stretch) targets posterior shoulder tightness contributing to GIRD."},{"id": 8418,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which nerve injury classically presents as 'winged scapula' with medial border prominence?","options": [{"key": "A","text": "Long thoracic nerve injury (serratus anterior)"},{"key": "B","text": "Axillary nerve injury"},{"key": "C","text": "Spinal accessory nerve injury (trapezius)"},{"key": "D","text": "Suprascapular nerve injury"}],"correct": "A","explanation": "Long thoracic nerve palsy causes serratus anterior weakness, resulting in medial winging most apparent with wall push."},{"id": 8419,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Spinal accessory nerve injury (affecting trapezius) causes which type of scapular winging?","options": [{"key": "A","text": "Lateral winging with depressed/laterally rotated scapula"},{"key": "B","text": "No winging occurs"},{"key": "C","text": "Medial winging identical to serratus anterior palsy"},{"key": "D","text": "Only affects rhomboids"}],"correct": "A","explanation": "Trapezius weakness from spinal accessory nerve injury causes lateral winging with a drooped shoulder appearance."},{"id": 8420,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Chronic subacromial bursitis is often a result of:","options": [{"key": "A","text": "Bacterial infection in most cases"},{"key": "B","text": "Genetic predisposition primarily"},{"key": "C","text": "Direct trauma only"},{"key": "D","text": "Repetitive mechanical friction/impingement"}],"correct": "D","explanation": "Chronic bursitis frequently develops secondary to repetitive impingement mechanics rather than infection."},{"id": 8421,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sternoclavicular joint osteoarthritis commonly presents with pain aggravated by:","options": [{"key": "A","text": "Cross-body/horizontal adduction and shoulder shrugging"},{"key": "B","text": "Wrist extension"},{"key": "C","text": "Elbow flexion only"},{"key": "D","text": "Hip flexion"}],"correct": "A","explanation": "Movements loading the SC joint (shrugging, protraction, cross-body movements) typically aggravate SC joint OA pain."},{"id": 8422,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Rotator cuff related shoulder pain (RCRSP) is the currently preferred umbrella term encompassing:","options": [{"key": "A","text": "Only complete cuff tears"},{"key": "B","text": "Impingement, tendinopathy, partial tears, and bursitis without clear structural correlation to symptoms"},{"key": "C","text": "Only AC joint pathology"},{"key": "D","text": "Only calcific tendinitis"}],"correct": "B","explanation": "RCRSP is used as many patients show similar structural pathology (impingement, tendinopathy) without perfect correlation to symptom severity, reflecting current best evidence."},{"id": 8423,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Hard","question": "Which of the following best supports use of exercise therapy over surgery for many rotator cuff related shoulder pain presentations?","options": [{"key": "A","text": "Surgery always superior"},{"key": "B","text": "No evidence exists comparing the two"},{"key": "C","text": "Exercise therapy is never appropriate"},{"key": "D","text": "Evidence shows comparable outcomes for structured exercise vs surgery in many non-traumatic cases"}],"correct": "D","explanation": "Multiple RCTs support structured exercise-based rehabilitation as comparable to surgery for many non-traumatic rotator cuff related shoulder pain cases."},{"id": 8424,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Easy","question": "Proprioceptive and neuromuscular control training is emphasized in shoulder instability rehab because:","options": [{"key": "A","text": "It is only relevant post-surgery"},{"key": "B","text": "It replaces the need for strength training entirely"},{"key": "C","text": "It improves dynamic stabilization, compensating for static/capsular deficits"},{"key": "D","text": "It has no evidence base"}],"correct": "C","explanation": "Enhancing proprioception and neuromuscular control helps dynamically stabilize a joint with underlying capsuloligamentous laxity."},{"id": 8425,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Closed kinetic chain exercises (e.g., wall push-up plus) are often introduced early in shoulder rehab because they:","options": [{"key": "A","text": "Only strengthen the deltoid"},{"key": "B","text": "Should never be used post-surgery"},{"key": "C","text": "Are more stressful to healing tissue than open chain"},{"key": "D","text": "Promote co-contraction and joint compression, enhancing dynamic stability with lower shear forces"}],"correct": "D","explanation": "CKC exercises promote joint compression/co-contraction with relatively lower shear stress, useful in early-stage shoulder rehab."},{"id": 8426,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Isometric exercises in early rotator cuff rehabilitation are useful primarily to:","options": [{"key": "A","text": "Cause muscle hypertrophy rapidly"},{"key": "B","text": "Build maximal strength immediately"},{"key": "C","text": "Maintain some muscle activation and reduce pain via pain gating, without excessive joint stress"},{"key": "D","text": "Replace all other exercise forms permanently"}],"correct": "C","explanation": "Early isometric loading helps maintain muscle activity and modulate pain, serving as a bridge to more dynamic loading."},{"id": 8427,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Medium","question": "Which imaging is typically the gold standard for diagnosing full-thickness rotator cuff tears?","options": [{"key": "A","text": "Plain X-ray"},{"key": "B","text": "CT scan without contrast"},{"key": "C","text": "MRI (or MR arthrogram)"},{"key": "D","text": "Bone scan"}],"correct": "C","explanation": "MRI provides detailed soft tissue visualization, considered the gold standard imaging for cuff tear diagnosis."},{"id": 8428,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "A positive 'painful arc' (60-120° of abduction) is most suggestive of:","options": [{"key": "A","text": "Biceps tendon rupture"},{"key": "B","text": "Full ROM without pathology"},{"key": "C","text": "AC joint pathology (typically painful at end range 170-180°)"},{"key": "D","text": "Subacromial impingement (supraspinatus/subacromial bursa involvement)"}],"correct": "D","explanation": "Pain in the mid-range of abduction (60-120°) classically indicates subacromial structures being compressed — painful arc sign."},{"id": 8429,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Corticosteroid injection into the subacromial space is generally used for:","options": [{"key": "A","text": "First-line treatment before any conservative management"},{"key": "B","text": "Short-term pain relief in impingement/bursitis as an adjunct to rehabilitation"},{"key": "C","text": "Contraindicated in all shoulder conditions"},{"key": "D","text": "Definitive cure without need for rehab"}],"correct": "B","explanation": "Subacromial corticosteroid injection can provide short-term symptomatic relief, ideally combined with an exercise-based rehabilitation program."},{"id": 8430,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Codman's pendulum exercises' are primarily used to:","options": [{"key": "A","text": "Build maximal shoulder strength"},{"key": "B","text": "Assess rotator cuff tear"},{"key": "C","text": "Promote gentle passive/active-assisted shoulder movement using gravity, reducing pain and stiffness"},{"key": "D","text": "Diagnose labral pathology"}],"correct": "C","explanation": "Codman's pendulum exercises use gravity-assisted momentum for gentle, low-load shoulder mobility, often used early in rehab."},{"id": 8431,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Cubital tunnel syndrome results from compression of which nerve at the elbow?","options": [{"key": "A","text": "Musculocutaneous nerve"},{"key": "B","text": "Radial nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Ulnar nerve is compressed at the cubital tunnel (behind medial epicondyle), causing cubital tunnel syndrome."},{"id": 8432,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Cubital tunnel syndrome classically presents with sensory changes in which digits?","options": [{"key": "A","text": "All fingers equally"},{"key": "B","text": "Ring and little finger"},{"key": "C","text": "Only thumb"},{"key": "D","text": "Thumb, index, middle finger"}],"correct": "B","explanation": "Ulnar nerve supplies sensation to the ring (medial half) and little finger."},{"id": 8433,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Radial tunnel syndrome involves compression of the radial nerve (posterior interosseous branch) and presents primarily with:","options": [{"key": "A","text": "Pain without significant motor weakness, mimicking lateral epicondylitis"},{"key": "B","text": "Complete wrist drop"},{"key": "C","text": "Numbness in little finger"},{"key": "D","text": "Sensory loss over thumb web space primarily"}],"correct": "A","explanation": "Radial tunnel syndrome often presents as deep forearm pain, frequently confused with resistant lateral epicondylitis, usually without significant weakness."},{"id": 8434,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Posterior interosseous nerve syndrome (a motor branch of radial nerve) primarily causes:","options": [{"key": "A","text": "Weakness of intrinsic hand muscles"},{"key": "B","text": "Weakness of finger/thumb extensors without sensory loss"},{"key": "C","text": "Wrist flexor weakness"},{"key": "D","text": "Complete sensory loss over dorsum of hand"}],"correct": "B","explanation": "PIN is purely motor; compression causes finger/thumb extensor weakness without sensory deficit (radial sensory branch spared)."},{"id": 8435,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Carpal tunnel syndrome results from compression of the median nerve, causing sensory symptoms in:","options": [{"key": "A","text": "Dorsum of hand"},{"key": "B","text": "All fingers"},{"key": "C","text": "Only little finger"},{"key": "D","text": "Thumb, index, middle, and half of ring finger"}],"correct": "D","explanation": "Median nerve territory in the hand includes thumb, index, middle, and radial half of ring finger."},{"id": 8436,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which structure forms the roof of the carpal tunnel?","options": [{"key": "A","text": "Flexor retinaculum (transverse carpal ligament)"},{"key": "B","text": "Palmar aponeurosis alone"},{"key": "C","text": "Pisiform bone"},{"key": "D","text": "Extensor retinaculum"}],"correct": "A","explanation": "Flexor retinaculum forms the roof, carpal bones form the floor of the carpal tunnel."},{"id": 8437,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Guyon's canal syndrome involves compression of which nerve at the wrist?","options": [{"key": "A","text": "Radial nerve"},{"key": "B","text": "Anterior interosseous nerve"},{"key": "C","text": "Median nerve"},{"key": "D","text": "Ulnar nerve"}],"correct": "D","explanation": "Guyon's canal (between pisiform and hook of hamate) transmits the ulnar nerve and artery."},{"id": 8438,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Anterior interosseous nerve syndrome (a branch of median nerve) presents with weakness of:","options": [{"key": "A","text": "Flexor pollicis longus and flexor digitorum profundus (index/middle), causing inability to make 'OK sign'"},{"key": "B","text": "Intrinsic hand muscles"},{"key": "C","text": "Thenar muscles causing thumb opposition loss"},{"key": "D","text": "Wrist extensors"}],"correct": "A","explanation": "AIN syndrome classically causes weakness of FPL and FDP (index/middle), producing inability to form a proper 'OK' pinch."},{"id": 8439,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Dupuytren's contracture primarily affects which structure?","options": [{"key": "A","text": "Palmar fascia (progressive thickening/contracture)"},{"key": "B","text": "Joint capsule"},{"key": "C","text": "Extensor tendon"},{"key": "D","text": "Flexor tendon sheath"}],"correct": "A","explanation": "Dupuytren's is a progressive fibromatosis of the palmar fascia, commonly causing flexion contracture of ring/little fingers."},{"id": 8440,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which finger is most commonly affected by Dupuytren's contracture?","options": [{"key": "A","text": "Middle finger"},{"key": "B","text": "Thumb"},{"key": "C","text": "Ring finger"},{"key": "D","text": "Index finger"}],"correct": "C","explanation": "Ring finger (followed by little finger) is most commonly affected in Dupuytren's contracture."},{"id": 8441,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Trigger finger most commonly affects which digit?","options": [{"key": "A","text": "Thumb and ring finger most commonly"},{"key": "B","text": "Index finger only"},{"key": "C","text": "Never affects thumb"},{"key": "D","text": "Little finger only"}],"correct": "A","explanation": "Thumb (trigger thumb) and ring finger are among the most commonly affected digits."},{"id": 8442,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ganglion cysts most commonly arise from which location?","options": [{"key": "A","text": "Dorsal wrist (over scapholunate joint)"},{"key": "B","text": "Fingertip only"},{"key": "C","text": "Elbow joint"},{"key": "D","text": "Palm centrally always"}],"correct": "A","explanation": "Dorsal wrist ganglion, arising from the scapholunate joint capsule, is the most common location."},{"id": 8443,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "'Kienbock's disease' refers to avascular necrosis of which carpal bone?","options": [{"key": "A","text": "Capitate"},{"key": "B","text": "Scaphoid"},{"key": "C","text": "Triquetrum"},{"key": "D","text": "Lunate"}],"correct": "D","explanation": "Kienbock's disease is avascular necrosis of the lunate bone, often related to negative ulnar variance."},{"id": 8444,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "Wrist OA secondary to untreated scaphoid non-union progressing to a specific arthritic pattern is termed:","options": [{"key": "A","text": "SLAC wrist"},{"key": "B","text": "SNAC wrist (Scaphoid Non-union Advanced Collapse)"},{"key": "C","text": "Rheumatoid wrist"},{"key": "D","text": "Kienbock's disease"}],"correct": "B","explanation": "SNAC wrist describes the predictable pattern of degenerative changes following untreated scaphoid non-union."},{"id": 8445,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'SLAC wrist' (Scapholunate Advanced Collapse) most commonly results from:","options": [{"key": "A","text": "Distal radius fracture malunion only"},{"key": "B","text": "Trigger finger"},{"key": "C","text": "Chronic scapholunate ligament injury/instability"},{"key": "D","text": "Rheumatoid arthritis exclusively"}],"correct": "C","explanation": "SLAC wrist is the most common pattern of wrist arthritis, resulting from chronic scapholunate ligament disruption."},{"id": 8446,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Thumb carpometacarpal (CMC) joint osteoarthritis most commonly presents in which population?","options": [{"key": "A","text": "Children"},{"key": "B","text": "Post-traumatic young adults only"},{"key": "C","text": "Postmenopausal women, middle-aged to elderly"},{"key": "D","text": "Young athletic males"}],"correct": "C","explanation": "Thumb base OA (CMC joint) is particularly common in postmenopausal women."},{"id": 8447,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which deformity of the thumb is classically seen with advanced CMC joint OA?","options": [{"key": "A","text": "Swan neck deformity"},{"key": "B","text": "Boutonniere deformity"},{"key": "C","text": "Zigzag/adduction deformity with MCP hyperextension"},{"key": "D","text": "Mallet thumb"}],"correct": "C","explanation": "Advanced thumb CMC OA leads to metacarpal adduction with compensatory MCP hyperextension, a zigzag deformity."},{"id": 8448,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "Rheumatoid arthritis of the hand classically causes which deviation at the MCP joints?","options": [{"key": "A","text": "Ulnar deviation"},{"key": "B","text": "Radial deviation"},{"key": "C","text": "Only flexion deformity"},{"key": "D","text": "No deviation typically"}],"correct": "A","explanation": "Chronic RA classically produces ulnar deviation at the MCP joints due to soft tissue changes and joint destruction."},{"id": 8449,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Boutonniere deformity' and 'swan neck deformity' are both classically associated with which condition?","options": [{"key": "A","text": "Osteoarthritis primarily"},{"key": "B","text": "Gout primarily"},{"key": "C","text": "De Quervain's tenosynovitis"},{"key": "D","text": "Rheumatoid arthritis"}],"correct": "D","explanation": "Both deformities are hallmark finger deformities seen in chronic rheumatoid arthritis affecting the hand."},{"id": 8450,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Osteoarthritis of the hand classically affects which joints, producing Heberden's nodes?","options": [{"key": "A","text": "Metacarpophalangeal joints predominantly"},{"key": "B","text": "Wrist joint predominantly"},{"key": "C","text": "Elbow joint"},{"key": "D","text": "Distal interphalangeal (DIP) joints"}],"correct": "D","explanation": "Heberden's nodes (DIP joint osteophytes) are classic findings in hand OA."},{"id": 8451,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "'Bouchard's nodes' in hand osteoarthritis occur at which joint?","options": [{"key": "A","text": "DIP joints"},{"key": "B","text": "Proximal interphalangeal (PIP) joints"},{"key": "C","text": "Wrist"},{"key": "D","text": "MCP joints"}],"correct": "B","explanation": "Bouchard's nodes are bony enlargements at the PIP joints, seen in hand OA."},{"id": 8452,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which structure is primarily affected in 'tennis elbow' (lateral epicondylitis)?","options": [{"key": "A","text": "Radial head cartilage"},{"key": "B","text": "Extensor carpi radialis brevis tendon origin"},{"key": "C","text": "Ulnar collateral ligament"},{"key": "D","text": "Common flexor tendon origin"}],"correct": "B","explanation": "ECRB tendinopathy at its origin from the lateral epicondyle is the primary pathology in tennis elbow."},{"id": 8453,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "Elbow osteoarthritis most commonly results secondary to:","options": [{"key": "A","text": "Rheumatoid arthritis primarily"},{"key": "B","text": "Primary idiopathic cause predominantly, as with hip/knee"},{"key": "C","text": "Gout primarily"},{"key": "D","text": "Previous trauma/fracture (post-traumatic OA)"}],"correct": "D","explanation": "Elbow OA is often post-traumatic, secondary to prior fracture or repetitive occupational/sports loading, unlike primary hip/knee OA."},{"id": 8454,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Olecranon bursitis' is commonly caused by:","options": [{"key": "A","text": "Nerve compression"},{"key": "B","text": "Repetitive friction/pressure or direct trauma to the posterior elbow"},{"key": "C","text": "Muscle strain"},{"key": "D","text": "Ligament rupture"}],"correct": "B","explanation": "Olecranon bursitis often results from repetitive leaning on elbows or direct trauma causing bursal irritation/effusion."},{"id": 8455,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Wrist extensor tendinopathy (lateral epicondylitis) rehabilitation typically emphasizes:","options": [{"key": "A","text": "Only corticosteroid injections without exercise"},{"key": "B","text": "Avoidance of any grip activity permanently"},{"key": "C","text": "Complete immobilization for months"},{"key": "D","text": "Progressive eccentric loading of wrist extensors"}],"correct": "D","explanation": "Eccentric strengthening of the wrist extensors is a well-supported rehabilitation approach for lateral epicondylitis."},{"id": 8456,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Nerve gliding exercises in carpal tunnel syndrome management aim to:","options": [{"key": "A","text": "Increase inflammation deliberately"},{"key": "B","text": "Weaken thenar muscles"},{"key": "C","text": "Improve median nerve mobility within the carpal tunnel, reducing adhesions/symptoms"},{"key": "D","text": "Replace surgical decompression always"}],"correct": "C","explanation": "Nerve gliding/tendon gliding exercises aim to promote median nerve mobility and reduce tension/adhesions within the tunnel."},{"id": 8457,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "A wrist cock-up splint is commonly used in management of:","options": [{"key": "A","text": "Boutonniere deformity"},{"key": "B","text": "Dupuytren's contracture"},{"key": "C","text": "Carpal tunnel syndrome (maintaining neutral wrist position, especially at night)"},{"key": "D","text": "Trigger finger"}],"correct": "C","explanation": "Neutral wrist splinting reduces carpal tunnel pressure, commonly used especially for night-time symptom relief in CTS."},{"id": 8458,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Post-flexor tendon repair rehabilitation protocols (e.g., Kleinert or Duran protocols) primarily emphasize:","options": [{"key": "A","text": "Immediate aggressive active motion"},{"key": "B","text": "No splinting required"},{"key": "C","text": "Early controlled passive/protected motion to prevent adhesions while protecting the repair"},{"key": "D","text": "Complete immobilization for 12 weeks"}],"correct": "C","explanation": "Early protected motion protocols balance tendon gliding (preventing adhesions) against risk of repair rupture."},{"id": 8459,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Buddy taping' is a common conservative management technique for:","options": [{"key": "A","text": "Finger sprains/minor collateral ligament injuries"},{"key": "B","text": "Trigger finger"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "Wrist fractures"}],"correct": "A","explanation": "Buddy taping (taping injured finger to adjacent finger) provides support while allowing protected motion for minor finger sprains."},{"id": 8460,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which condition presents with a positive Finkelstein's test and pain over the radial wrist with thumb/wrist movement?","options": [{"key": "A","text": "Trigger finger"},{"key": "B","text": "Guyon's canal syndrome"},{"key": "C","text": "Carpal tunnel syndrome"},{"key": "D","text": "De Quervain's tenosynovitis"}],"correct": "D","explanation": "Finkelstein's test specifically provokes pain in De Quervain's tenosynovitis affecting APL/EPB tendons."},{"id": 8461,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which is a common cause of ulnar-sided wrist pain related to the fibrocartilage disc between ulna and carpus?","options": [{"key": "A","text": "Carpal tunnel syndrome"},{"key": "B","text": "Scaphoid fracture"},{"key": "C","text": "Triangular fibrocartilage complex (TFCC) injury"},{"key": "D","text": "De Quervain's tenosynovitis"}],"correct": "C","explanation": "TFCC injury is a common source of ulnar wrist pain, often from axial loading with rotation."},{"id": 8462,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Splinting position for a mallet finger injury is typically:","options": [{"key": "A","text": "DIP joint in extension (slight hyperextension), PIP free"},{"key": "B","text": "PIP joint extension only"},{"key": "C","text": "Full hand immobilization including wrist"},{"key": "D","text": "DIP joint in flexion"}],"correct": "A","explanation": "Mallet finger splinting maintains DIP extension to allow terminal extensor tendon healing, leaving PIP mobile."},{"id": 8463,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Boutonniere deformity splinting typically positions the PIP joint in:","options": [{"key": "A","text": "No splinting required"},{"key": "B","text": "Flexion"},{"key": "C","text": "Extension, allowing DIP motion"},{"key": "D","text": "Full hand immobilization"}],"correct": "C","explanation": "PIP extension splinting protects the healing central slip while allowing DIP mobility in boutonniere management."},{"id": 8464,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "Which grip strength assessment tool is commonly used in hand therapy?","options": [{"key": "A","text": "Ashworth scale"},{"key": "B","text": "Berg Balance Scale"},{"key": "C","text": "Goniometer"},{"key": "D","text": "Jamar dynamometer"}],"correct": "D","explanation": "Jamar dynamometer is the standard clinical tool for quantifying grip strength."},{"id": 8465,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Pinch strength (tip, key, palmar pinch) assessment is important in evaluating function of which nerves collectively?","options": [{"key": "A","text": "Axillary nerve"},{"key": "B","text": "Median and ulnar nerve-innervated intrinsic and extrinsic hand muscles"},{"key": "C","text": "Radial nerve only"},{"key": "D","text": "Musculocutaneous nerve only"}],"correct": "B","explanation": "Pinch strength relies on coordinated median (thenar, FPL) and ulnar (adductor pollicis, first dorsal interosseous) innervated muscles."},{"id": 8466,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Which is a classic sign of complete median nerve injury at the wrist regarding thumb function?","options": [{"key": "A","text": "Loss of thumb opposition (thenar wasting, 'ape hand' deformity in severe cases)"},{"key": "B","text": "Loss of thumb adduction only"},{"key": "C","text": "Wrist drop"},{"key": "D","text": "Claw hand deformity primarily"}],"correct": "A","explanation": "Median nerve injury causes thenar muscle wasting and loss of opposition, producing the classic 'ape hand' in severe/chronic cases."},{"id": 8467,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Complete ulnar nerve injury at the wrist classically produces:","options": [{"key": "A","text": "Ape hand deformity"},{"key": "B","text": "Loss of thumb opposition primarily"},{"key": "C","text": "Wrist drop"},{"key": "D","text": "Claw hand deformity (hyperextended MCP, flexed IP joints of ring/little finger)"}],"correct": "D","explanation": "Ulnar claw hand results from unopposed extensor action on ring/little fingers due to lumbrical/interossei paralysis."},{"id": 8468,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Radial nerve injury at the level of the humeral shaft classically produces:","options": [{"key": "A","text": "Loss of sensation in little finger only"},{"key": "B","text": "Ape hand"},{"key": "C","text": "Claw hand"},{"key": "D","text": "Wrist drop and finger drop (loss of wrist/finger extension)"}],"correct": "D","explanation": "Radial nerve palsy causes loss of wrist and finger extensor function, producing characteristic wrist drop."},{"id": 8469,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Intersection syndrome' at the forearm involves friction/inflammation where which tendon groups cross?","options": [{"key": "A","text": "Median and ulnar nerve crossing"},{"key": "B","text": "No specific tendon crossing involved"},{"key": "C","text": "First and second dorsal extensor compartments (APL/EPB crossing ECRL/ECRB)"},{"key": "D","text": "Flexor and extensor compartments generally"}],"correct": "C","explanation": "Intersection syndrome occurs at the crossing point of the first (APL/EPB) and second (ECRL/ECRB) dorsal extensor compartments, about 4-6cm proximal to the wrist."},{"id": 8470,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Occupational/ergonomic modification is a key component of management for which of the following conditions?","options": [{"key": "A","text": "Acute fracture only"},{"key": "B","text": "Not relevant to upper limb rehabilitation"},{"key": "C","text": "Repetitive strain conditions like lateral epicondylitis and carpal tunnel syndrome"},{"key": "D","text": "Congenital hand deformities only"}],"correct": "C","explanation": "Addressing repetitive/ergonomic contributing factors is essential in managing and preventing recurrence of overuse conditions like tennis elbow and CTS."},{"id": 8471,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Hip osteoarthritis classically presents with pain located in:","options": [{"key": "A","text": "Buttock only always"},{"key": "B","text": "Lower back exclusively"},{"key": "C","text": "Lateral hip only"},{"key": "D","text": "Groin, with possible referral to anterior thigh/knee"}],"correct": "D","explanation": "Hip OA classically presents with groin pain, sometimes referring down the anterior thigh to the knee."},{"id": 8472,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Capsular pattern in hip OA typically shows greatest restriction in:","options": [{"key": "A","text": "Internal rotation, flexion, and abduction"},{"key": "B","text": "Adduction primarily"},{"key": "C","text": "Extension primarily"},{"key": "D","text": "External rotation only"}],"correct": "A","explanation": "Hip OA capsular pattern: internal rotation most limited, followed by flexion and abduction; extension/external rotation relatively spared."},{"id": 8473,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Greater trochanteric pain syndrome (GTPS) is primarily related to pathology of:","options": [{"key": "A","text": "Iliopsoas tendon only"},{"key": "B","text": "Gluteus medius/minimus tendinopathy and trochanteric bursa"},{"key": "C","text": "Hip joint cartilage primarily"},{"key": "D","text": "Sciatic nerve"}],"correct": "B","explanation": "GTPS encompasses gluteal tendinopathy and trochanteric bursitis as the primary sources of lateral hip pain."},{"id": 8474,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Femoroacetabular impingement (FAI) is classified into which two main morphological types?","options": [{"key": "A","text": "Primary and secondary type"},{"key": "B","text": "Cam and Pincer type"},{"key": "C","text": "Anterior and posterior type"},{"key": "D","text": "Type A and Type B"}],"correct": "B","explanation": "Cam (femoral head-neck abnormality) and Pincer (acetabular over-coverage) are the two main FAI morphology types, often coexisting (mixed type)."},{"id": 8475,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Cam-type femoroacetabular impingement involves:","options": [{"key": "A","text": "Normal femoral anatomy"},{"key": "B","text": "Labral hypertrophy only"},{"key": "C","text": "Abnormal femoral head-neck junction morphology (aspherical head)"},{"key": "D","text": "Excessive acetabular coverage"}],"correct": "C","explanation": "Cam morphology describes an aspherical femoral head/reduced head-neck offset causing abnormal contact during hip flexion/internal rotation."},{"id": 8476,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pincer-type femoroacetabular impingement involves:","options": [{"key": "A","text": "Femoral head-neck deformity only"},{"key": "B","text": "Excessive acetabular over-coverage of the femoral head"},{"key": "C","text": "Reduced acetabular coverage"},{"key": "D","text": "Labral absence"}],"correct": "B","explanation": "Pincer morphology describes excessive acetabular rim coverage causing abutment against the femoral neck."},{"id": 8477,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Hip labral tears are commonly associated with which underlying pathology?","options": [{"key": "A","text": "Lumbar disc herniation primarily"},{"key": "B","text": "Femoroacetabular impingement or hip dysplasia"},{"key": "C","text": "Ankle sprain"},{"key": "D","text": "Plantar fasciitis"}],"correct": "B","explanation": "FAI and dysplasia are common structural contributors to labral tears via altered joint mechanics."},{"id": 8478,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Iliopsoas tendinopathy/bursitis commonly presents with pain in which location, aggravated by which movement?","options": [{"key": "A","text": "Medial thigh pain, aggravated by adduction"},{"key": "B","text": "Anterior groin pain, aggravated by resisted hip flexion"},{"key": "C","text": "Lateral hip pain, aggravated by side-lying"},{"key": "D","text": "Posterior buttock pain, aggravated by sitting"}],"correct": "B","explanation": "Iliopsoas pathology presents with anterior groin pain, worsened by resisted hip flexion or passive stretch into extension."},{"id": 8479,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "'Snapping hip syndrome' (coxa saltans) external type is caused by:","options": [{"key": "A","text": "Iliotibial band/tensor fascia lata snapping over greater trochanter"},{"key": "B","text": "Loose body in joint"},{"key": "C","text": "Iliopsoas tendon snapping over iliopectineal eminence"},{"key": "D","text": "Labral tear"}],"correct": "A","explanation": "External snapping hip results from the ITB/TFL snapping over the greater trochanter during hip flexion-extension."},{"id": 8480,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Internal snapping hip syndrome is caused by:","options": [{"key": "A","text": "ITB snapping over trochanter"},{"key": "B","text": "Labral tear alone"},{"key": "C","text": "Iliopsoas tendon snapping over the iliopectineal eminence or femoral head"},{"key": "D","text": "Ligamentum teres tear"}],"correct": "C","explanation": "Internal snapping hip results from the iliopsoas tendon catching on the iliopectineal eminence or femoral head during hip movement."},{"id": 8481,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Piriformis syndrome presents with symptoms that mimic:","options": [{"key": "A","text": "Meralgia paresthetica"},{"key": "B","text": "Carpal tunnel syndrome"},{"key": "C","text": "Sciatica (due to sciatic nerve irritation by piriformis muscle)"},{"key": "D","text": "Femoral nerve entrapment"}],"correct": "C","explanation": "Piriformis syndrome causes buttock pain with possible radiation down the leg, mimicking lumbar radiculopathy due to sciatic nerve involvement."},{"id": 8482,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Meralgia paresthetica results from entrapment of which nerve?","options": [{"key": "A","text": "Femoral nerve"},{"key": "B","text": "Lateral femoral cutaneous nerve"},{"key": "C","text": "Obturator nerve"},{"key": "D","text": "Sciatic nerve"}],"correct": "B","explanation": "Lateral femoral cutaneous nerve entrapment (often near the inguinal ligament) causes anterolateral thigh paresthesia/burning."},{"id": 8483,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Avascular necrosis of the femoral head is associated with which risk factor among the following?","options": [{"key": "A","text": "Regular moderate exercise"},{"key": "B","text": "Long-term corticosteroid use"},{"key": "C","text": "Vitamin D sufficiency"},{"key": "D","text": "Young healthy adults without risk factors"}],"correct": "B","explanation": "Corticosteroid use, alcohol abuse, and trauma are well-known risk factors for femoral head AVN."},{"id": 8484,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Which imaging is most sensitive for early detection of avascular necrosis of the hip, before X-ray changes appear?","options": [{"key": "A","text": "Ultrasound"},{"key": "B","text": "CT scan"},{"key": "C","text": "MRI"},{"key": "D","text": "Plain X-ray"}],"correct": "C","explanation": "MRI detects early marrow edema/AVN changes before plain radiographs show abnormality."},{"id": 8485,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Transient osteoporosis of the hip typically presents in which population?","options": [{"key": "A","text": "Middle-aged men and pregnant women (third trimester)"},{"key": "B","text": "Athletes with stress fractures only"},{"key": "C","text": "Elderly with chronic OA only"},{"key": "D","text": "Children exclusively"}],"correct": "A","explanation": "Transient osteoporosis of hip classically presents in middle-aged men and pregnant women, self-limiting condition with marrow edema."},{"id": 8486,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Hip bursitis commonly involves which two bursae?","options": [{"key": "A","text": "Olecranon bursa only"},{"key": "B","text": "Subacromial and subdeltoid bursae"},{"key": "C","text": "Prepatellar and infrapatellar bursae"},{"key": "D","text": "Trochanteric and iliopsoas bursae"}],"correct": "D","explanation": "Trochanteric bursa (lateral hip) and iliopsoas bursa (anterior hip) are the two commonly implicated bursae around the hip."},{"id": 8487,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Adductor-related groin pain (athletic pubalgia component) is often associated with:","options": [{"key": "A","text": "Purely intra-articular hip pathology"},{"key": "B","text": "Sciatic nerve entrapment"},{"key": "C","text": "Adductor longus tendinopathy from repetitive kicking/cutting sports"},{"key": "D","text": "Iliotibial band syndrome"}],"correct": "C","explanation": "Repetitive adduction/kicking loads predispose to adductor longus tendinopathy, a common cause of groin pain in athletes."},{"id": 8488,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Sports hernia (athletic pubalgia) typically presents with pain aggravated by:","options": [{"key": "A","text": "Rest only"},{"key": "B","text": "Sudden movements, sit-ups, coughing, and sporting activity"},{"key": "C","text": "Sleep"},{"key": "D","text": "Sitting only"}],"correct": "B","explanation": "Athletic pubalgia/sports hernia pain worsens with activities increasing intra-abdominal pressure or explosive movement."},{"id": 8489,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Hip osteoarthritis conservative management typically includes all EXCEPT:","options": [{"key": "A","text": "Weight management education"},{"key": "B","text": "Activity modification and pain education"},{"key": "C","text": "Exercise therapy for strength and ROM"},{"key": "D","text": "Immediate hip replacement in all mild cases"}],"correct": "D","explanation": "Immediate surgery is not first-line for mild OA; conservative management (exercise, weight, education) is prioritized initially."},{"id": 8490,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Total hip arthroplasty (THA) posterior approach precautions typically include avoiding:","options": [{"key": "A","text": "Hip extension and external rotation"},{"key": "B","text": "Standing upright"},{"key": "C","text": "Hip flexion beyond 90°, adduction past midline, and internal rotation"},{"key": "D","text": "Any weight bearing"}],"correct": "C","explanation": "Posterior approach THA precautions classically avoid combined flexion, adduction, and internal rotation to prevent dislocation."},{"id": 8491,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Total hip arthroplasty anterior approach precautions typically emphasize avoiding:","options": [{"key": "A","text": "No specific precautions needed"},{"key": "B","text": "Extension, external rotation, and adduction"},{"key": "C","text": "Internal rotation only"},{"key": "D","text": "Flexion beyond 90° primarily"}],"correct": "B","explanation": "Anterior approach THA precautions typically avoid combined extension, external rotation, and adduction (opposite pattern to posterior approach)."},{"id": 8492,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which of the following is a common early post-operative goal after total hip replacement?","options": [{"key": "A","text": "Immediate return to high-impact sport"},{"key": "B","text": "Early mobilization, gait training with assistive device, and pain management"},{"key": "C","text": "Complete bed rest for 6 weeks"},{"key": "D","text": "Avoidance of any weight bearing indefinitely"}],"correct": "B","explanation": "Modern THA rehabilitation emphasizes early safe mobilization and progressive gait training."},{"id": 8493,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Hip flexor contracture is commonly assessed using which special test?","options": [{"key": "A","text": "FABER test"},{"key": "B","text": "Trendelenburg test"},{"key": "C","text": "Ober's test"},{"key": "D","text": "Thomas test"}],"correct": "D","explanation": "Thomas test specifically detects hip flexor (iliopsoas/rectus femoris) tightness/contracture."},{"id": 8494,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Developmental dysplasia of the hip (DDH), if untreated, commonly leads to which adult condition?","options": [{"key": "A","text": "Trochanteric bursitis only"},{"key": "B","text": "Piriformis syndrome"},{"key": "C","text": "Meralgia paresthetica"},{"key": "D","text": "Early-onset secondary hip osteoarthritis"}],"correct": "D","explanation": "Uncorrected DDH alters joint mechanics/coverage, predisposing to premature secondary hip OA in adulthood."},{"id": 8495,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Legg-Calve-Perthes disease involves avascular necrosis of the femoral head in which age group?","options": [{"key": "A","text": "Adults (30-40 years)"},{"key": "B","text": "Children (typically 4-10 years)"},{"key": "C","text": "Infants (<1 year)"},{"key": "D","text": "Elderly (>65 years)"}],"correct": "B","explanation": "Perthes disease is idiopathic AVN of the proximal femoral epiphysis in children, typically 4-10 years old."},{"id": 8496,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Slipped Capital Femoral Epiphysis (SCFE) typically occurs in which population?","options": [{"key": "A","text": "Young adult athletes"},{"key": "B","text": "Neonates"},{"key": "C","text": "Elderly osteoporotic patients"},{"key": "D","text": "Obese adolescents during growth spurt"}],"correct": "D","explanation": "SCFE classically occurs in overweight adolescents during rapid growth, with posteroinferior slippage of the femoral epiphysis."},{"id": 8497,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ischiofemoral impingement syndrome involves narrowing of the space between:","options": [{"key": "A","text": "Greater trochanter and iliac crest"},{"key": "B","text": "Pubic symphysis and femoral neck"},{"key": "C","text": "Femoral head and acetabular rim"},{"key": "D","text": "Ischial tuberosity and lesser trochanter"}],"correct": "D","explanation": "Ischiofemoral impingement occurs when the space between ischial tuberosity and lesser trochanter narrows, compressing quadratus femoris."},{"id": 8498,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which muscle is primarily implicated in ischiofemoral impingement syndrome symptoms?","options": [{"key": "A","text": "Gluteus maximus"},{"key": "B","text": "Piriformis"},{"key": "C","text": "Iliopsoas"},{"key": "D","text": "Quadratus femoris"}],"correct": "D","explanation": "Quadratus femoris becomes compressed/irritated within the narrowed ischiofemoral space in this impingement syndrome."},{"id": 8499,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Hip osteoarthritis exercise programs commonly emphasize strengthening of which muscle group to reduce joint loading?","options": [{"key": "A","text": "Neck flexors"},{"key": "B","text": "Hip adductors only"},{"key": "C","text": "Ankle plantarflexors only"},{"key": "D","text": "Hip abductors (gluteus medius/minimus)"}],"correct": "D","explanation": "Strengthening hip abductors helps improve pelvic stability and reduce joint reaction forces during single-leg stance activities like gait."},{"id": 8500,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which of the following best describes 'hip pointer' injury?","options": [{"key": "A","text": "Fracture of the femoral neck"},{"key": "B","text": "Avulsion of hamstring origin"},{"key": "C","text": "Contusion of the iliac crest with attached musculature"},{"key": "D","text": "Labral tear"}],"correct": "C","explanation": "Hip pointer is a contusion injury to the iliac crest and surrounding musculature, common in contact sports."},{"id": 8501,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteitis pubis presents with pain located at the:","options": [{"key": "A","text": "Sacroiliac joint"},{"key": "B","text": "Greater trochanter"},{"key": "C","text": "Ischial tuberosity"},{"key": "D","text": "Pubic symphysis, aggravated by activities like kicking or sudden direction change"}],"correct": "D","explanation": "Osteitis pubis is an overuse/inflammatory condition of the pubic symphysis, common in athletes with repetitive kicking/cutting."},{"id": 8502,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ischial tuberosity apophysitis/avulsion is commonly seen in adolescent athletes due to traction from which muscle group?","options": [{"key": "A","text": "Hamstring origin"},{"key": "B","text": "Gluteus maximus insertion"},{"key": "C","text": "Quadriceps origin"},{"key": "D","text": "Adductor origin"}],"correct": "A","explanation": "Hamstring origin at the ischial tuberosity is a common site of traction apophysitis/avulsion in growing adolescent athletes."},{"id": 8503,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Coxa vara refers to:","options": [{"key": "A","text": "Increased femoral neck-shaft angle (>135°)"},{"key": "B","text": "Excessive femoral anteversion"},{"key": "C","text": "Normal femoral neck-shaft angle"},{"key": "D","text": "Decreased femoral neck-shaft angle (<120°)"}],"correct": "D","explanation": "Coxa vara = reduced neck-shaft angle, altering hip biomechanics and abductor lever arm."},{"id": 8504,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Coxa valga refers to:","options": [{"key": "A","text": "Increased femoral neck-shaft angle (>135°)"},{"key": "B","text": "Normal femoral anatomy"},{"key": "C","text": "Retroversion of femoral neck"},{"key": "D","text": "Decreased femoral neck-shaft angle"}],"correct": "A","explanation": "Coxa valga = increased neck-shaft angle, associated with conditions like cerebral palsy and can predispose to hip instability."},{"id": 8505,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which functional test is commonly used to assess hip abductor strength/endurance clinically?","options": [{"key": "A","text": "Thomas test"},{"key": "B","text": "Single-leg stance / Trendelenburg test"},{"key": "C","text": "Ober's test"},{"key": "D","text": "FADIR test"}],"correct": "B","explanation": "Single-leg stance/Trendelenburg testing assesses hip abductor strength via pelvic control during unilateral weight bearing."},{"id": 8506,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Hip osteoarthritis functional limitation is commonly assessed using which patient-reported outcome measure?","options": [{"key": "A","text": "Harris Hip Score / HOOS (Hip disability and Osteoarthritis Outcome Score)"},{"key": "B","text": "DASH score"},{"key": "C","text": "Berg Balance Scale"},{"key": "D","text": "Oswestry Disability Index"}],"correct": "A","explanation": "Harris Hip Score and HOOS are validated hip-specific outcome measures assessing pain and function."},{"id": 8507,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which of the following is a common precaution after hip resurfacing/arthroplasty regarding activity in the first few weeks?","options": [{"key": "A","text": "No precautions are ever needed"},{"key": "B","text": "Complete immobilization in bed"},{"key": "C","text": "Immediate high-impact running allowed"},{"key": "D","text": "Avoiding excessive combined movements that stress the joint per surgical approach precautions"}],"correct": "D","explanation": "Approach-specific movement precautions (flexion/rotation combinations) are typically maintained for the initial healing period post-arthroplasty."},{"id": 8508,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Ligamentum teres injury of the hip is increasingly recognized as a cause of:","options": [{"key": "A","text": "Ankle instability"},{"key": "B","text": "Sciatic neuropathy"},{"key": "C","text": "Femoral shaft fracture"},{"key": "D","text": "Hip instability and mechanical symptoms, especially in athletes/dancers"}],"correct": "D","explanation": "Ligamentum teres tears can contribute to hip instability and mechanical symptoms (clicking, giving way), particularly in flexible athletes/dancers."},{"id": 8509,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Gluteal tendinopathy is now recognized to be a more common cause of lateral hip pain than which previously over-diagnosed condition?","options": [{"key": "A","text": "Piriformis syndrome"},{"key": "B","text": "Isolated trochanteric bursitis"},{"key": "C","text": "Femoral neck fracture"},{"key": "D","text": "Hip osteoarthritis"}],"correct": "B","explanation": "Current evidence suggests gluteal tendinopathy is the primary pathology in most 'trochanteric bursitis' presentations (GTPS)."},{"id": 8510,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which exercise position is typically avoided initially in gluteal tendinopathy rehabilitation due to compressive loading?","options": [{"key": "A","text": "Prone lying"},{"key": "B","text": "Deep hip adduction positions like crossing legs or hanging hip in stance"},{"key": "C","text": "Hip extension exercises"},{"key": "D","text": "Supine bridging with feet close together"}],"correct": "B","explanation": "Positions creating compression of the gluteal tendons against the greater trochanter (e.g., adducted/crossed leg postures) are minimized early in GTPS rehab."},{"id": 8511,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Knee osteoarthritis most commonly affects which compartment first?","options": [{"key": "A","text": "Lateral compartment"},{"key": "B","text": "All compartments equally always"},{"key": "C","text": "Patellofemoral compartment only"},{"key": "D","text": "Medial compartment"}],"correct": "D","explanation": "Medial compartment OA is most common, related to typical varus alignment and higher medial joint loading."},{"id": 8512,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Kellgren-Lawrence classification is used to grade severity of:","options": [{"key": "A","text": "Knee osteoarthritis on radiographs"},{"key": "B","text": "Meniscal tear severity"},{"key": "C","text": "ACL tear on MRI"},{"key": "D","text": "Cartilage defect depth"}],"correct": "A","explanation": "Kellgren-Lawrence (Grade 0-IV) is the standard radiographic OA severity classification."},{"id": 8513,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Patellofemoral pain syndrome (PFPS) is commonly associated with which biomechanical factor?","options": [{"key": "A","text": "VMO weakness/delayed activation relative to VL"},{"key": "B","text": "Excessive quadriceps strength"},{"key": "C","text": "Weak hamstrings only"},{"key": "D","text": "Tight gastrocnemius primarily"}],"correct": "A","explanation": "Relative VMO weakness/timing delay compared to vastus lateralis is commonly implicated in PFPS, altering patellar tracking."},{"id": 8514,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Chondromalacia patellae refers to:","options": [{"key": "A","text": "Patellar fracture"},{"key": "B","text": "Softening/degeneration of patellar articular cartilage"},{"key": "C","text": "Patellar tendon rupture"},{"key": "D","text": "Bursitis around patella"}],"correct": "B","explanation": "Chondromalacia patellae describes cartilage softening/fibrillation on the undersurface of the patella."},{"id": 8515,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osgood-Schlatter disease involves traction apophysitis at the:","options": [{"key": "A","text": "Femoral condyle"},{"key": "B","text": "Tibial tuberosity"},{"key": "C","text": "Fibular head"},{"key": "D","text": "Inferior pole of patella"}],"correct": "B","explanation": "Osgood-Schlatter disease is traction apophysitis at the tibial tuberosity in growing adolescents, related to quadriceps pull."},{"id": 8516,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sinding-Larsen-Johansson syndrome involves traction apophysitis/pathology at the:","options": [{"key": "A","text": "Tibial tuberosity"},{"key": "B","text": "Popliteal fossa"},{"key": "C","text": "Inferior pole of the patella"},{"key": "D","text": "Femoral condyle"}],"correct": "C","explanation": "Sinding-Larsen-Johansson affects the inferior patellar pole (proximal patellar tendon attachment), analogous to Osgood-Schlatter."},{"id": 8517,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Osteochondritis dissecans of the knee most commonly affects which location?","options": [{"key": "A","text": "Tibial plateau exclusively"},{"key": "B","text": "Patella exclusively"},{"key": "C","text": "Fibular head"},{"key": "D","text": "Lateral aspect of medial femoral condyle"}],"correct": "D","explanation": "OCD classically affects the lateral aspect of the medial femoral condyle, involving separation of subchondral bone/cartilage."},{"id": 8518,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Iliotibial band friction syndrome commonly presents with pain at:","options": [{"key": "A","text": "Popliteal fossa"},{"key": "B","text": "Medial joint line"},{"key": "C","text": "Lateral femoral epicondyle, aggravated by repetitive knee flexion-extension (e.g., running)"},{"key": "D","text": "Patellar tendon"}],"correct": "C","explanation": "ITB friction syndrome causes lateral knee pain from repetitive band friction over the lateral femoral epicondyle, common in runners/cyclists."},{"id": 8519,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Pes anserine bursitis presents with pain and tenderness at:","options": [{"key": "A","text": "Anterior patella"},{"key": "B","text": "Proximal medial tibia, below the joint line"},{"key": "C","text": "Popliteal fossa"},{"key": "D","text": "Lateral joint line"}],"correct": "B","explanation": "Pes anserine bursa lies beneath the conjoined sartorius, gracilis, and semitendinosus tendon insertion on proximal medial tibia."},{"id": 8520,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Baker's cyst (popliteal cyst) commonly arises secondary to which underlying condition in adults?","options": [{"key": "A","text": "Patellar dislocation exclusively"},{"key": "B","text": "Isolated primary condition unrelated to knee pathology"},{"key": "C","text": "ACL rupture exclusively"},{"key": "D","text": "Intra-articular knee pathology (OA, meniscal tear) causing effusion"}],"correct": "D","explanation": "Adult Baker's cysts usually result from increased intra-articular pressure/effusion secondary to conditions like OA or meniscal tears, communicating with the joint."},{"id": 8521,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Meniscal tears are classified by pattern; a 'bucket handle tear' refers to:","options": [{"key": "A","text": "Horizontal cleavage tear"},{"key": "B","text": "Radial tear"},{"key": "C","text": "Degenerative complex tear"},{"key": "D","text": "Longitudinal tear with displaced fragment causing mechanical locking"}],"correct": "D","explanation": "Bucket handle tears are longitudinal tears where the inner fragment displaces centrally, often causing true mechanical locking."},{"id": 8522,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "True mechanical locking of the knee (inability to fully extend) most commonly suggests:","options": [{"key": "A","text": "Displaced meniscal tear or loose body blocking extension"},{"key": "B","text": "Simple effusion"},{"key": "C","text": "Ligament sprain without mechanical block"},{"key": "D","text": "Patellar tendinopathy"}],"correct": "A","explanation": "True locking indicates a physical block to full extension, classically from a displaced meniscal fragment or loose body."},{"id": 8523,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Which meniscus is more frequently torn, and why?","options": [{"key": "A","text": "Neither is commonly torn"},{"key": "B","text": "Both equally, no anatomical predisposition"},{"key": "C","text": "Lateral meniscus - due to increased mobility"},{"key": "D","text": "Medial meniscus - due to firmer attachment to MCL/joint capsule limiting mobility"}],"correct": "D","explanation": "Medial meniscus is less mobile due to firm capsular/MCL attachment, predisposing it to greater shear stress and tearing."},{"id": 8524,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "ACL reconstruction rehabilitation typically progresses through phases; the initial phase primarily focuses on:","options": [{"key": "A","text": "Aggressive resisted knee flexion immediately"},{"key": "B","text": "Reducing swelling, restoring full extension, and quadriceps activation"},{"key": "C","text": "Plyometric training"},{"key": "D","text": "Return to sport testing"}],"correct": "B","explanation": "Early ACL reconstruction rehab prioritizes controlling effusion, achieving full knee extension, and restoring quadriceps activation (avoiding arthrogenic muscle inhibition)."},{"id": 8525,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Loss of full knee extension after ACL reconstruction most significantly predisposes to:","options": [{"key": "A","text": "Anterior knee pain and altered gait mechanics (quadriceps-avoidance-like patterns)"},{"key": "B","text": "Improved function"},{"key": "C","text": "Only cosmetic issue"},{"key": "D","text": "No functional consequence"}],"correct": "A","explanation": "Extension deficits after ACL reconstruction can cause anterior knee pain, quadriceps weakness, and abnormal gait patterns; early priority to restore full extension."},{"id": 8526,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Open kinetic chain quadriceps exercises (e.g., seated knee extension) after ACL reconstruction are typically:","options": [{"key": "A","text": "Delayed/restricted in early phases due to increased anterior tibial shear stress near full extension"},{"key": "B","text": "Preferred over closed chain from day one"},{"key": "C","text": "Contraindicated permanently"},{"key": "D","text": "Started immediately post-op without restriction"}],"correct": "A","explanation": "OKC extension exercises, particularly in terminal extension range, can increase strain on the ACL graft and are often introduced cautiously/later in rehab."},{"id": 8527,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Closed kinetic chain exercises are generally preferred early in ACL rehabilitation because they:","options": [{"key": "A","text": "Increase anterior shear force significantly"},{"key": "B","text": "Produce co-contraction of hamstrings and quadriceps, reducing anterior tibial translation stress"},{"key": "C","text": "Are contraindicated after ACL surgery"},{"key": "D","text": "Isolate quadriceps only"}],"correct": "B","explanation": "CKC exercises promote hamstring co-contraction, which helps protect the ACL graft by reducing anterior tibial translation."},{"id": 8528,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "PCL injuries commonly result from which mechanism?","options": [{"key": "A","text": "Non-contact pivoting"},{"key": "B","text": "Direct blow to anterior tibia with knee flexed (dashboard injury) or hyperflexion"},{"key": "C","text": "Valgus stress with foot planted"},{"key": "D","text": "Varus stress"}],"correct": "B","explanation": "PCL injuries classically result from a posteriorly directed force on the proximal tibia, e.g., dashboard injury in flexed knee."},{"id": 8529,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Which knee ligament injury is generally managed more conservatively (non-operatively) when isolated, compared to ACL?","options": [{"key": "A","text": "ACL complete tear in young active patients"},{"key": "B","text": "Isolated PCL injury (often managed conservatively depending on grade)"},{"key": "C","text": "LCL grade III always"},{"key": "D","text": "Combined multi-ligament injury"}],"correct": "B","explanation": "Isolated PCL injuries, especially lower grade, are often managed conservatively with quadriceps-focused rehabilitation, unlike ACL in active populations."},{"id": 8530,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Posterolateral corner (PLC) injuries of the knee often occur in combination with:","options": [{"key": "A","text": "Patellar dislocation alone"},{"key": "B","text": "Isolated MCL injury"},{"key": "C","text": "PCL and/or ACL injuries"},{"key": "D","text": "Meniscal tear alone"}],"correct": "C","explanation": "PLC injuries frequently accompany cruciate ligament injuries, particularly PCL, given shared injury mechanisms."},{"id": 8531,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "MCL injuries are typically managed with which approach for isolated Grade I-II injuries?","options": [{"key": "A","text": "Complete immobilization for 3 months"},{"key": "B","text": "Conservative management with bracing and progressive rehabilitation"},{"key": "C","text": "No treatment needed"},{"key": "D","text": "Immediate surgical reconstruction always"}],"correct": "B","explanation": "Isolated MCL injuries (Grade I-II) generally heal well conservatively given good intrinsic healing capacity and blood supply."},{"id": 8532,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Total knee arthroplasty (TKA) early post-operative physiotherapy focuses on:","options": [{"key": "A","text": "Pain/swelling control, achieving full extension, quadriceps activation, and progressive ROM/gait training"},{"key": "B","text": "Immediate high-impact activity"},{"key": "C","text": "Avoiding all knee flexion"},{"key": "D","text": "Prolonged bed rest"}],"correct": "A","explanation": "Early TKA rehab prioritizes controlling swelling, restoring extension, activating quadriceps, and safe progressive mobilization."},{"id": 8533,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "A common goal for knee flexion ROM by discharge after TKA is approximately:","options": [{"key": "A","text": "Only 45°"},{"key": "B","text": "Full 135° immediately"},{"key": "C","text": "90° or more"},{"key": "D","text": "No specific ROM goal needed"}],"correct": "C","explanation": "Achieving at least ~90° flexion (with continued progress) is a commonly cited functional milestone post-TKA, though targets vary."},{"id": 8534,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Genu recurvatum (knee hyperextension) can result from weakness of which muscle group, leading to compensatory locking?","options": [{"key": "A","text": "Gastrocnemius weakness only"},{"key": "B","text": "Hamstring weakness only"},{"key": "C","text": "Gluteus medius weakness"},{"key": "D","text": "Quadriceps weakness causing compensatory hyperextension for stability"}],"correct": "D","explanation": "Weak quadriceps can lead patients to compensate by locking the knee into hyperextension for passive stability during stance."},{"id": 8535,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Runner's knee is a lay term most often referring to:","options": [{"key": "A","text": "MCL sprain"},{"key": "B","text": "ACL injury"},{"key": "C","text": "Patellofemoral pain syndrome"},{"key": "D","text": "Meniscal tear"}],"correct": "C","explanation": "'Runner's knee' commonly refers to patellofemoral pain syndrome, common in repetitive loading activities like running."},{"id": 8536,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Patellar tendinopathy ('jumper's knee') is most commonly seen in athletes involved in:","options": [{"key": "A","text": "Jumping sports (volleyball, basketball)"},{"key": "B","text": "Archery"},{"key": "C","text": "Swimming"},{"key": "D","text": "Golf"}],"correct": "A","explanation": "Repetitive jumping/landing loads predispose to patellar tendinopathy, hence the name 'jumper's knee'."},{"id": 8537,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Quadriceps tendon rupture is more common in which population compared to patellar tendon rupture?","options": [{"key": "A","text": "Children exclusively"},{"key": "B","text": "Older patients (>40 years), often with predisposing systemic conditions"},{"key": "C","text": "Young athletes exclusively"},{"key": "D","text": "No age predisposition"}],"correct": "B","explanation": "Quadriceps tendon rupture is more common in older individuals, often with underlying tendon degeneration or systemic disease (e.g., diabetes, chronic steroid use)."},{"id": 8538,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Patellar tendon rupture is more common in which population?","options": [{"key": "A","text": "Infants"},{"key": "B","text": "Post-menopausal women exclusively"},{"key": "C","text": "Older sedentary population primarily"},{"key": "D","text": "Younger, athletic individuals"}],"correct": "D","explanation": "Patellar tendon rupture more typically occurs in younger athletic individuals with higher activity-related tendon loading."},{"id": 8539,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Easy","question": "Which clinical sign helps differentiate quadriceps tendon rupture from patellar tendon rupture regarding patella position?","options": [{"key": "A","text": "No difference in patellar position"},{"key": "B","text": "Patella dislocates laterally in both"},{"key": "C","text": "Patella always central in both"},{"key": "D","text": "Patella baja (low-riding) in patellar tendon rupture; patella alta (high-riding) in quadriceps tendon rupture"}],"correct": "D","explanation": "Quadriceps rupture causes patella alta (unopposed patellar tendon pulls patella down less, appears high); patellar tendon rupture causes patella baja."},{"id": 8540,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Discoid meniscus is a congenital variant most commonly affecting which meniscus?","options": [{"key": "A","text": "Medial meniscus"},{"key": "B","text": "Lateral meniscus"},{"key": "C","text": "Neither, it's an acquired condition"},{"key": "D","text": "Both equally"}],"correct": "B","explanation": "Discoid meniscus, an abnormal disc-shaped congenital variant, most commonly affects the lateral meniscus."},{"id": 8541,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Which knee condition is characterized by a snapping/popping sensation and is common in children with discoid lateral meniscus?","options": [{"key": "A","text": "Osgood-Schlatter disease"},{"key": "B","text": "Patellar dislocation"},{"key": "C","text": "ACL laxity"},{"key": "D","text": "Snapping knee syndrome from discoid meniscus"}],"correct": "D","explanation": "Discoid lateral meniscus commonly presents with snapping and clicking during knee movement in children."},{"id": 8542,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Post-meniscectomy (partial) rehabilitation generally allows faster progression compared to meniscal repair because:","options": [{"key": "A","text": "Meniscectomy causes more pain requiring slower rehab"},{"key": "B","text": "Meniscectomy patients cannot bear weight for weeks"},{"key": "C","text": "No difference in rehabilitation timelines"},{"key": "D","text": "No tissue healing constraints from repair sutures limiting early loading"}],"correct": "D","explanation": "Without repair sutures to protect, meniscectomy rehab can progress faster than meniscal repair, which requires protecting the healing repair site."},{"id": 8543,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Meniscal repair rehabilitation protocols typically restrict which movement/position early to protect the repair?","options": [{"key": "A","text": "All flexion regardless of degree"},{"key": "B","text": "All extension movements"},{"key": "C","text": "No restrictions are typically applied"},{"key": "D","text": "Deep flexion combined with weight bearing/rotation depending on tear location"}],"correct": "D","explanation": "Depending on tear location/repair type, deep flexion under load or with rotation is often restricted initially to protect the repaired meniscus."},{"id": 8544,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Unicompartmental (partial) knee arthroplasty is generally indicated for:","options": [{"key": "A","text": "ACL deficiency without OA"},{"key": "B","text": "Multi-compartment severe OA"},{"key": "C","text": "Isolated single-compartment osteoarthritis with intact ligaments"},{"key": "D","text": "Rheumatoid arthritis with pan-compartmental disease"}],"correct": "C","explanation": "UKA is suitable for isolated single-compartment (usually medial) OA with preserved ligamentous stability."},{"id": 8545,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "High tibial osteotomy is a surgical option primarily indicated for:","options": [{"key": "A","text": "Elderly patients with tricompartmental OA"},{"key": "B","text": "Acute ACL tear"},{"key": "C","text": "Meniscal tear without OA"},{"key": "D","text": "Younger, active patients with unicompartmental OA and malalignment (e.g., varus)"}],"correct": "D","explanation": "HTO redistributes load away from the affected compartment by correcting malalignment, suited to younger active patients wanting to delay arthroplasty."},{"id": 8546,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Patellar taping (McConnell technique) aims to:","options": [{"key": "A","text": "Replace the need for exercise therapy"},{"key": "B","text": "Improve patellar alignment/tracking and reduce pain during activity"},{"key": "C","text": "Increase quadriceps bulk"},{"key": "D","text": "Immobilize the knee completely"}],"correct": "B","explanation": "McConnell taping aims to correct patellar position/tracking, providing symptomatic relief to allow more effective exercise participation."},{"id": 8547,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Hoffa's syndrome (fat pad impingement) involves irritation of which structure?","options": [{"key": "A","text": "Suprapatellar bursa"},{"key": "B","text": "Popliteus tendon"},{"key": "C","text": "Infrapatellar fat pad"},{"key": "D","text": "Pes anserine bursa"}],"correct": "C","explanation": "Hoffa's syndrome involves impingement/inflammation of the infrapatellar (Hoffa's) fat pad, often aggravated by hyperextension."},{"id": 8548,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Popliteus tendinopathy typically presents with pain located:","options": [{"key": "A","text": "Popliteal fossa centrally, unrelated to activity"},{"key": "B","text": "Medial joint line"},{"key": "C","text": "Posterolateral knee, aggravated by downhill walking/running"},{"key": "D","text": "Anterior knee"}],"correct": "C","explanation": "Popliteus, which controls tibial rotation and resists anterior translation, can become symptomatic with posterolateral knee pain, notably with downhill activity."},{"id": 8549,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Knee effusion assessment using the 'sweep test' (bulge sign) is most sensitive for detecting:","options": [{"key": "A","text": "Small to moderate joint effusions"},{"key": "B","text": "Meniscal tears directly"},{"key": "C","text": "Ligament laxity"},{"key": "D","text": "Large tense effusions only"}],"correct": "A","explanation": "The sweep/bulge test is useful clinically for detecting smaller effusions by observing fluid wave movement."},{"id": 8550,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "'Patellar tap test' (ballottement) is used to assess:","options": [{"key": "A","text": "Meniscal integrity"},{"key": "B","text": "Ligament stability"},{"key": "C","text": "Presence of moderate to large knee effusion"},{"key": "D","text": "Quadriceps strength"}],"correct": "C","explanation": "Patellar tap/ballottement test detects moderate-large effusions by feeling the patella 'float' and tap against the femur."},{"id": 8551,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which exercise is generally emphasized early after patellar dislocation to improve dynamic patellar stability?","options": [{"key": "A","text": "Passive lateral patellar glide stretching"},{"key": "B","text": "Immediate return to jumping sports"},{"key": "C","text": "VMO/quadriceps strengthening with attention to hip strengthening (proximal control)"},{"key": "D","text": "Complete immobilization for months without exercise"}],"correct": "C","explanation": "Strengthening VMO and proximal hip musculature (particularly external rotators/abductors) helps improve dynamic patellar tracking/stability post-dislocation."},{"id": 8552,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which factor is a recognized risk for recurrent patellar dislocation?","options": [{"key": "A","text": "Older age"},{"key": "B","text": "Trochlear dysplasia, patella alta, and generalized ligamentous laxity"},{"key": "C","text": "Strong quadriceps only"},{"key": "D","text": "Male gender predominantly"}],"correct": "B","explanation": "Structural risk factors (trochlear dysplasia, patella alta, laxity) significantly increase recurrence risk of patellar dislocation."},{"id": 8553,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Anterior knee pain in adolescents without significant structural pathology is commonly attributed to:","options": [{"key": "A","text": "Always meniscal tear"},{"key": "B","text": "Always ACL injury"},{"key": "C","text": "Patellofemoral pain syndrome related to growth, biomechanics, and muscle imbalance"},{"key": "D","text": "Osteoarthritis"}],"correct": "C","explanation": "PFPS is a common, largely biomechanical/overuse cause of anterior knee pain in the adolescent/young adult population."},{"id": 8554,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Knee valgus collapse during landing tasks (observed clinically, e.g., drop jump test) is considered a risk factor for:","options": [{"key": "A","text": "Meniscal tear only"},{"key": "B","text": "Patellar tendon rupture only"},{"key": "C","text": "Ankle sprain exclusively"},{"key": "D","text": "ACL injury, particularly in female athletes"}],"correct": "D","explanation": "Dynamic knee valgus during landing/cutting is a well-documented biomechanical risk factor for non-contact ACL injury."},{"id": 8555,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "ACL injury prevention programs commonly include which type of training?","options": [{"key": "A","text": "Isolated quadriceps strengthening only"},{"key": "B","text": "Neuromuscular training including plyometrics, strength, and landing mechanics"},{"key": "C","text": "Passive modalities only"},{"key": "D","text": "Static stretching alone"}],"correct": "B","explanation": "Comprehensive neuromuscular training programs (e.g., FIFA 11+) combining strength, plyometrics, and balance reduce ACL injury risk."},{"id": 8556,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Which term describes excessive/abnormal internal rotation and valgus movement of the knee often assessed in the single-leg squat test?","options": [{"key": "A","text": "Dynamic knee valgus"},{"key": "B","text": "Q angle deviation only"},{"key": "C","text": "Genu recurvatum"},{"key": "D","text": "Screw home mechanism dysfunction"}],"correct": "A","explanation": "Dynamic knee valgus, observed during functional movement screens, reflects poor neuromuscular control and injury risk."},{"id": 8557,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Blood Flow Restriction (BFR) training is increasingly used post-knee surgery to:","options": [{"key": "A","text": "Only be used pre-operatively"},{"key": "B","text": "Increase risk of complications with no benefit"},{"key": "C","text": "Allow strength gains using low loads by restricting venous blood flow, reducing joint stress"},{"key": "D","text": "Replace all resistance training entirely"}],"correct": "C","explanation": "BFR training enables muscle strength/hypertrophy gains with lower mechanical loads, useful when heavy loading is contraindicated post-surgery."},{"id": 8558,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "'Terrible triad' injury of the knee (O'Donoghue's triad) classically includes ACL tear, MCL tear, and:","options": [{"key": "A","text": "Lateral meniscus tear"},{"key": "B","text": "LCL tear"},{"key": "C","text": "Medial meniscus tear"},{"key": "D","text": "PCL tear"}],"correct": "C","explanation": "O'Donoghue's unhappy/terrible triad = ACL + MCL + medial meniscus injury, from valgus rotational stress."},{"id": 8559,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Knee joint proprioception is often impaired following ACL injury; rehabilitation addresses this primarily through:","options": [{"key": "A","text": "Complete rest"},{"key": "B","text": "Passive modalities exclusively"},{"key": "C","text": "Balance and neuromuscular training exercises"},{"key": "D","text": "Only strength training"}],"correct": "C","explanation": "Balance/proprioceptive training is a critical rehab component addressing mechanoreceptor deficits from ACL injury."},{"id": 8560,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Patellofemoral joint reaction forces are generally greatest during which activity?","options": [{"key": "A","text": "Standing still"},{"key": "B","text": "Walking on flat ground"},{"key": "C","text": "Deep squatting/stair descent"},{"key": "D","text": "Straight leg raise"}],"correct": "C","explanation": "Increased knee flexion angles during activities like deep squats or stair descent significantly raise patellofemoral joint compressive forces."},{"id": 8561,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Hamstring-to-quadriceps strength ratio is commonly assessed clinically because significant imbalance may increase risk of:","options": [{"key": "A","text": "Ankle sprain"},{"key": "B","text": "Only patellar tendinopathy"},{"key": "C","text": "ACL injury and hamstring strain"},{"key": "D","text": "Hip OA"}],"correct": "C","explanation": "H:Q ratio imbalance is associated with altered knee joint control and increased injury risk, particularly ACL and hamstring strains."},{"id": 8562,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Which of the following knee conditions in children/adolescents is self-limiting and typically resolves with growth cessation?","options": [{"key": "A","text": "Osteoarthritis"},{"key": "B","text": "ACL tear"},{"key": "C","text": "Meniscal tear"},{"key": "D","text": "Osgood-Schlatter disease"}],"correct": "D","explanation": "Osgood-Schlatter disease typically resolves once tibial tuberosity ossification is complete, though it may leave a residual bony prominence."},{"id": 8563,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Genu valgum (knock knee) alters knee joint loading by increasing stress on which compartment?","options": [{"key": "A","text": "Medial compartment"},{"key": "B","text": "No effect on compartment loading"},{"key": "C","text": "Lateral compartment"},{"key": "D","text": "Patellofemoral joint only"}],"correct": "C","explanation": "Valgus alignment shifts load laterally, increasing stress on the lateral tibiofemoral compartment."},{"id": 8564,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Genu varum (bow leg) alignment increases loading stress on which knee compartment, predisposing to OA there?","options": [{"key": "A","text": "Medial compartment"},{"key": "B","text": "Patellofemoral joint exclusively"},{"key": "C","text": "Equal loading on both"},{"key": "D","text": "Lateral compartment"}],"correct": "A","explanation": "Varus alignment shifts load medially, a key contributor to medial compartment OA progression."},{"id": 8565,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which exercise modification is often recommended for patellofemoral pain during squatting to reduce patellofemoral joint stress?","options": [{"key": "A","text": "Adding maximum external load immediately"},{"key": "B","text": "Always performing full deep squats"},{"key": "C","text": "Limiting depth of knee flexion and avoiding excessive forward knee travel over toes"},{"key": "D","text": "Avoiding squats permanently"}],"correct": "C","explanation": "Limiting knee flexion depth and controlling knee position can reduce patellofemoral compressive forces during squatting exercises."},{"id": 8566,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Multi-ligament knee injury (knee dislocation) requires urgent assessment of which structure due to high injury risk?","options": [{"key": "A","text": "Hip joint"},{"key": "B","text": "Lumbar spine only"},{"key": "C","text": "Popliteal artery and peroneal nerve"},{"key": "D","text": "Ankle ligaments only"}],"correct": "C","explanation": "Knee dislocation carries significant risk to the popliteal artery and common peroneal nerve, requiring urgent vascular/neurological assessment."},{"id": 8567,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Post-operative cryotherapy (ice/cold compression) after knee surgery is primarily used to:","options": [{"key": "A","text": "Reduce pain and swelling in the early post-operative period"},{"key": "B","text": "Increase ROM directly"},{"key": "C","text": "Replace the need for exercise"},{"key": "D","text": "Promote tissue healing directly"}],"correct": "A","explanation": "Cryotherapy is an adjunct for pain and edema management, not a primary driver of tissue healing or ROM restoration."},{"id": 8568,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Continuous Passive Motion (CPM) machines after TKA are used primarily to:","options": [{"key": "A","text": "Strengthen quadriceps"},{"key": "B","text": "Bear weight through the limb"},{"key": "C","text": "Replace active exercise entirely"},{"key": "D","text": "Assist early passive ROM and potentially reduce stiffness, though evidence for long-term benefit is mixed"}],"correct": "D","explanation": "CPM provides passive motion assistance post-TKA; evidence on added long-term benefit over standard physiotherapy alone is mixed/limited."},{"id": 8569,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Easy","question": "Return to running after ACL reconstruction is typically considered once the patient demonstrates:","options": [{"key": "A","text": "No criteria are used, time-based only"},{"key": "B","text": "Simply reaching 3 months post-surgery regardless of strength"},{"key": "C","text": "Adequate quadriceps strength symmetry, full ROM, and controlled single-leg functional tasks"},{"key": "D","text": "Any pain-free walking"}],"correct": "C","explanation": "Criteria-based progression (strength symmetry, functional testing) rather than time alone is recommended for safe return to running/sport after ACL reconstruction."},{"id": 8570,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which term describes gradual thinning and softening of patellar articular cartilage often preceding patellofemoral OA?","options": [{"key": "A","text": "Plica syndrome"},{"key": "B","text": "Chondromalacia patellae"},{"key": "C","text": "Osteochondritis dissecans"},{"key": "D","text": "Bipartite patella"}],"correct": "B","explanation": "Chondromalacia patellae represents early cartilage softening/fibrillation, which can progress toward patellofemoral OA if unaddressed."},{"id": 8571,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Plantar fasciitis classically presents with pain located at:","options": [{"key": "A","text": "Achilles insertion"},{"key": "B","text": "Lateral midfoot"},{"key": "C","text": "Metatarsal heads"},{"key": "D","text": "Medial calcaneal tubercle, worst with first steps in the morning"}],"correct": "D","explanation": "Plantar fasciitis presents with classic post-static dyskinesia (worst on first steps) and tenderness at the medial calcaneal tubercle."},{"id": 8572,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Plantar fasciitis is associated with which of the following risk factors?","options": [{"key": "A","text": "Obesity, prolonged standing, pes planus/cavus, tight gastrocnemius"},{"key": "B","text": "Low BMI"},{"key": "C","text": "Regular stretching only"},{"key": "D","text": "Flexible flat feet without other factors"}],"correct": "A","explanation": "Obesity, occupational standing, abnormal foot arch, and calf tightness are recognized risk factors for plantar fasciitis."},{"id": 8573,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "Achilles tendon rupture classically presents with which finding on Thompson's test?","options": [{"key": "A","text": "No change in ankle position"},{"key": "B","text": "Normal plantarflexion with calf squeeze"},{"key": "C","text": "Excessive dorsiflexion"},{"key": "D","text": "Absent plantarflexion with calf squeeze"}],"correct": "D","explanation": "Absence of passive plantarflexion when calf is squeezed (positive Thompson's test) indicates Achilles tendon rupture."},{"id": 8574,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Achilles tendinopathy insertional type differs from mid-portion type primarily in:","options": [{"key": "A","text": "Location of pathology (at the calcaneal insertion vs 2-6cm proximal)"},{"key": "B","text": "Occurring only in athletes"},{"key": "C","text": "Being always surgical"},{"key": "D","text": "Response to eccentric loading being identical in both"}],"correct": "A","explanation": "Insertional Achilles tendinopathy occurs at the calcaneal attachment, often with different loading strategy considerations than mid-portion tendinopathy."},{"id": 8575,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Retrocalcaneal bursitis is often associated with which condition due to shared anatomical location?","options": [{"key": "A","text": "Plantar fasciitis exclusively"},{"key": "B","text": "Insertional Achilles tendinopathy and Haglund's deformity"},{"key": "C","text": "Tarsal tunnel syndrome"},{"key": "D","text": "Morton's neuroma"}],"correct": "B","explanation": "Retrocalcaneal bursa lies anterior to the Achilles insertion, commonly implicated alongside insertional tendinopathy and Haglund's deformity (bony prominence)."},{"id": 8576,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Tarsal tunnel syndrome results from compression of which nerve?","options": [{"key": "A","text": "Sural nerve"},{"key": "B","text": "Posterior tibial nerve"},{"key": "C","text": "Deep peroneal nerve"},{"key": "D","text": "Superficial peroneal nerve"}],"correct": "B","explanation": "Posterior tibial nerve is compressed within the tarsal tunnel (behind medial malleolus), causing plantar foot symptoms."},{"id": 8577,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Morton's neuroma most commonly occurs between which metatarsal heads?","options": [{"key": "A","text": "Fourth and fifth"},{"key": "B","text": "First and second"},{"key": "C","text": "Third and fourth"},{"key": "D","text": "Second and third"}],"correct": "C","explanation": "Morton's (interdigital) neuroma most commonly affects the third web space, between third and fourth metatarsal heads."},{"id": 8578,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Hallux valgus (bunion) deformity involves lateral deviation of the:","options": [{"key": "A","text": "Great toe at the first MTP joint, with medial deviation of first metatarsal"},{"key": "B","text": "Second toe primarily"},{"key": "C","text": "Great toe medially"},{"key": "D","text": "Fifth toe primarily"}],"correct": "A","explanation": "Hallux valgus involves lateral deviation of the great toe with medial deviation of the first metatarsal, creating the classic bunion prominence."},{"id": 8579,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Hallux rigidus refers to:","options": [{"key": "A","text": "Bunion deformity"},{"key": "B","text": "Claw toe deformity"},{"key": "C","text": "Plantar plate rupture"},{"key": "D","text": "Osteoarthritis of the first MTP joint with restricted dorsiflexion"}],"correct": "D","explanation": "Hallux rigidus is degenerative arthritis of the first MTP joint, causing painful restriction of great toe dorsiflexion."},{"id": 8580,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Pes planus (flat foot) is characterized by:","options": [{"key": "A","text": "Increased arch height"},{"key": "B","text": "Fixed forefoot varus only"},{"key": "C","text": "Normal arch with lateral deviation"},{"key": "D","text": "Reduced/absent medial longitudinal arch height"}],"correct": "D","explanation": "Pes planus refers to a collapsed or reduced medial longitudinal arch, which may be flexible or rigid."},{"id": 8581,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Pes cavus (high-arched foot) is often associated with which underlying condition when severe/progressive?","options": [{"key": "A","text": "Ligamentous laxity syndromes primarily"},{"key": "B","text": "Flat feet in childhood"},{"key": "C","text": "Neurological conditions (e.g., Charcot-Marie-Tooth disease)"},{"key": "D","text": "Obesity primarily"}],"correct": "C","explanation": "Progressive or severe pes cavus warrants investigation for underlying neuromuscular conditions like Charcot-Marie-Tooth disease."},{"id": 8582,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Posterior tibial tendon dysfunction (PTTD) is a leading cause of which acquired foot deformity in adults?","options": [{"key": "A","text": "Hallux valgus"},{"key": "B","text": "Claw toe"},{"key": "C","text": "Adult-acquired flatfoot deformity"},{"key": "D","text": "Pes cavus"}],"correct": "C","explanation": "PTTD progressively leads to collapse of the medial longitudinal arch, causing adult-acquired flatfoot deformity."},{"id": 8583,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Too many toes sign' observed from behind a standing patient is associated with:","options": [{"key": "A","text": "Plantar fasciitis"},{"key": "B","text": "Achilles tendinopathy"},{"key": "C","text": "Normal foot posture"},{"key": "D","text": "Posterior tibial tendon dysfunction with forefoot abduction"}],"correct": "D","explanation": "Excessive forefoot abduction from hindfoot valgus in PTTD causes more toes to be visible laterally when viewed from behind — 'too many toes sign'."},{"id": 8584,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "Lateral ankle sprains most commonly result from which mechanism?","options": [{"key": "A","text": "Inversion with plantarflexion"},{"key": "B","text": "Pure dorsiflexion"},{"key": "C","text": "Axial loading"},{"key": "D","text": "Eversion with dorsiflexion"}],"correct": "A","explanation": "Combined inversion and plantarflexion is the classic mechanism for lateral ankle ligament sprain (ATFL most affected)."},{"id": 8585,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Chronic ankle instability following repeated sprains is often related to:","options": [{"key": "A","text": "Mechanical laxity and/or impaired proprioception/neuromuscular control"},{"key": "B","text": "Complete absence of ligaments"},{"key": "C","text": "Age-related change only"},{"key": "D","text": "Only bony abnormality"}],"correct": "A","explanation": "Chronic ankle instability results from both mechanical (ligamentous laxity) and functional (proprioceptive/neuromuscular) deficits."},{"id": 8586,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Balance/proprioceptive training (e.g., wobble board) is a key component of ankle sprain rehabilitation to address:","options": [{"key": "A","text": "Only pain relief"},{"key": "B","text": "Impaired proprioception and reduce recurrence risk"},{"key": "C","text": "Bone density"},{"key": "D","text": "Ligament strength directly"}],"correct": "B","explanation": "Proprioceptive training addresses neuromuscular deficits post-sprain, reducing risk of re-injury/chronic instability."},{"id": 8587,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Achilles tendon rupture rehabilitation (functional/accelerated protocols) increasingly favors:","options": [{"key": "A","text": "Immediate unrestricted activity"},{"key": "B","text": "Early controlled weight-bearing and motion in a protective boot rather than prolonged immobilization"},{"key": "C","text": "Prolonged non-weight bearing casting for 12 weeks always"},{"key": "D","text": "No rehabilitation required post-surgery"}],"correct": "B","explanation": "Modern evidence supports early functional rehabilitation with controlled loading, improving outcomes compared to prolonged strict immobilization."},{"id": 8588,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Sever's disease (calcaneal apophysitis) occurs in which population?","options": [{"key": "A","text": "Post-menopausal women"},{"key": "B","text": "Active children/adolescents (typically 8-14 years) during growth"},{"key": "C","text": "Infants"},{"key": "D","text": "Adults over 50"}],"correct": "B","explanation": "Sever's disease is a traction apophysitis at the calcaneal growth plate, common in active growing children."},{"id": 8589,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Freiberg's disease (avascular necrosis) typically affects which bone?","options": [{"key": "A","text": "Second metatarsal head"},{"key": "B","text": "Navicular"},{"key": "C","text": "Calcaneus"},{"key": "D","text": "Talus"}],"correct": "A","explanation": "Freiberg's disease is AVN of a metatarsal head, most commonly the second."},{"id": 8590,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Kohler's disease refers to avascular necrosis of the:","options": [{"key": "A","text": "Navicular bone (in children)"},{"key": "B","text": "Cuboid"},{"key": "C","text": "Talus"},{"key": "D","text": "Calcaneus"}],"correct": "A","explanation": "Kohler's disease is a self-limiting AVN of the tarsal navicular in young children."},{"id": 8591,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Turf toe injury involves sprain of which structure?","options": [{"key": "A","text": "Plantar fascia"},{"key": "B","text": "Achilles tendon"},{"key": "C","text": "Plantar plate/capsuloligamentous complex of the first MTP joint"},{"key": "D","text": "Lateral ankle ligaments"}],"correct": "C","explanation": "Turf toe is a hyperextension injury to the plantar plate/capsular structures of the first MTP joint, common on hard playing surfaces."},{"id": 8592,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Claw toe deformity is characterized by:","options": [{"key": "A","text": "Only MTP flexion"},{"key": "B","text": "Only DIP flexion"},{"key": "C","text": "MTP hyperextension with PIP and DIP flexion"},{"key": "D","text": "MTP flexion with PIP/DIP extension"}],"correct": "C","explanation": "Claw toe: MTP joint hyperextension combined with flexion at PIP and DIP joints."},{"id": 8593,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Hammer toe deformity is characterized by:","options": [{"key": "A","text": "MTP flexion primarily"},{"key": "B","text": "DIP flexion only"},{"key": "C","text": "PIP hyperextension"},{"key": "D","text": "PIP joint flexion with MTP and DIP relatively neutral/extended"}],"correct": "D","explanation": "Hammer toe: flexion deformity primarily at the PIP joint, MTP and DIP relatively normal or slightly extended."},{"id": 8594,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Mallet toe deformity is characterized by:","options": [{"key": "A","text": "MTP hyperextension primarily"},{"key": "B","text": "No joint deformity"},{"key": "C","text": "DIP joint flexion deformity"},{"key": "D","text": "PIP flexion primarily"}],"correct": "C","explanation": "Mallet toe involves flexion deformity isolated to the DIP joint."},{"id": 8595,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Peroneal tendon subluxation/dislocation occurs due to injury of which structure?","options": [{"key": "A","text": "Deltoid ligament"},{"key": "B","text": "ATFL"},{"key": "C","text": "Superior peroneal retinaculum"},{"key": "D","text": "Plantar fascia"}],"correct": "C","explanation": "Disruption of the superior peroneal retinaculum allows the peroneal tendons to subluxate/dislocate from the fibular groove."},{"id": 8596,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Metatarsalgia refers to:","options": [{"key": "A","text": "Generalized pain under the metatarsal heads"},{"key": "B","text": "Fracture of metatarsal shaft"},{"key": "C","text": "Specific nerve entrapment only"},{"key": "D","text": "Bunion deformity"}],"correct": "A","explanation": "Metatarsalgia is a general term for pain/inflammation in the forefoot under the metatarsal heads, from various causes including overload."},{"id": 8597,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Charcot foot (neuropathic arthropathy) is most commonly associated with which underlying condition?","options": [{"key": "A","text": "Osteoporosis alone"},{"key": "B","text": "Rheumatoid arthritis primarily"},{"key": "C","text": "Diabetes mellitus with peripheral neuropathy"},{"key": "D","text": "Gout primarily"}],"correct": "C","explanation": "Diabetic peripheral neuropathy predisposes to repetitive unrecognized trauma, leading to progressive joint destruction (Charcot foot)."},{"id": 8598,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Hard","question": "Ankle equinus (limited dorsiflexion) is a recognized risk factor for which foot condition?","options": [{"key": "A","text": "Ankle eversion sprain"},{"key": "B","text": "Peroneal tendon rupture"},{"key": "C","text": "Plantar fasciitis and forefoot overload conditions"},{"key": "D","text": "Tarsal tunnel syndrome exclusively"}],"correct": "C","explanation": "Restricted ankle dorsiflexion (equinus) increases compensatory forefoot/midfoot stress, contributing to plantar fasciitis and metatarsalgia."},{"id": 8599,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which orthotic intervention is commonly recommended for symptomatic pes planus with PTTD?","options": [{"key": "A","text": "No orthotic intervention indicated"},{"key": "B","text": "Lateral wedge only"},{"key": "C","text": "Medial longitudinal arch support/custom orthosis"},{"key": "D","text": "Rigid cavus-specific orthosis"}],"correct": "C","explanation": "Arch-supporting orthoses help offload the posterior tibial tendon and support the medial longitudinal arch in PTTD management."},{"id": 8600,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Gait analysis in a patient with foot drop typically shows compensatory:","options": [{"key": "A","text": "Excessive plantarflexion during swing"},{"key": "B","text": "Steppage gait with excessive hip/knee flexion during swing"},{"key": "C","text": "Normal swing phase pattern"},{"key": "D","text": "Reduced hip flexion during swing"}],"correct": "B","explanation": "Steppage gait compensates for inadequate ankle dorsiflexion during swing by increasing hip/knee flexion to clear the foot."},{"id": 8601,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Windlass mechanism of the plantar fascia is activated by:","options": [{"key": "A","text": "Great toe dorsiflexion during push-off, tightening the plantar fascia and raising the arch"},{"key": "B","text": "Heel strike"},{"key": "C","text": "Ankle plantarflexion only"},{"key": "D","text": "Toe flexion"}],"correct": "A","explanation": "Dorsiflexion of the great toe during gait tightens the plantar fascia via the windlass mechanism, raising the medial arch for efficient push-off."},{"id": 8602,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Which classification system grades ankle sprain severity based on ligament damage?","options": [{"key": "A","text": "Gustilo classification"},{"key": "B","text": "Grade I-III system (similar to general ligament sprain grading)"},{"key": "C","text": "Weber classification"},{"key": "D","text": "Salter-Harris classification"}],"correct": "B","explanation": "Ankle sprains are commonly graded I-III based on degree of ligament tearing and functional instability, similar to general ligament injury grading."},{"id": 8603,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Hard","question": "Which test assesses syndesmotic ankle injury by external rotation of the foot with the leg stabilized?","options": [{"key": "A","text": "Talar tilt test"},{"key": "B","text": "Kleiger's test (external rotation stress test)"},{"key": "C","text": "Thompson's test"},{"key": "D","text": "Anterior drawer test"}],"correct": "B","explanation": "Kleiger's test specifically stresses the syndesmosis via external rotation, useful in diagnosing high ankle sprains."},{"id": 8604,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "Sesamoiditis of the foot involves inflammation of the sesamoid bones located beneath which joint?","options": [{"key": "A","text": "Ankle joint"},{"key": "B","text": "Fifth metatarsophalangeal joint"},{"key": "C","text": "First metatarsophalangeal joint"},{"key": "D","text": "Subtalar joint"}],"correct": "C","explanation": "Sesamoid bones lie beneath the first MTP joint within the flexor hallucis brevis tendon, prone to overload/sesamoiditis."},{"id": 8605,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which type of orthotic modification is typically used to offload symptomatic sesamoiditis?","options": [{"key": "A","text": "Heel raise only"},{"key": "B","text": "Lateral wedge"},{"key": "C","text": "Metatarsal pad/cut-out to offload the first metatarsal head"},{"key": "D","text": "Rigid arch support only"}],"correct": "C","explanation": "A dancer's pad or metatarsal cut-out offloading pressure from the sesamoids is a common conservative management strategy."},{"id": 8606,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Subtalar joint motion primarily contributes to which foot movements?","options": [{"key": "A","text": "Dorsiflexion and plantarflexion"},{"key": "B","text": "Toe flexion/extension"},{"key": "C","text": "Forefoot abduction only"},{"key": "D","text": "Inversion and eversion (pronation/supination component)"}],"correct": "D","explanation": "Subtalar joint motion is the primary contributor to hindfoot inversion/eversion, key to pronation-supination mechanics."},{"id": 8607,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Midtarsal joint (Chopart's joint) primarily contributes to which foot function?","options": [{"key": "A","text": "Toe extension"},{"key": "B","text": "Forefoot flexibility and shock absorption, working with subtalar motion"},{"key": "C","text": "Ankle dorsiflexion primarily"},{"key": "D","text": "No functional role in gait"}],"correct": "B","explanation": "Midtarsal joint motion complements subtalar motion in adapting the foot to terrain and absorbing shock during gait."},{"id": 8608,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Overpronation during gait can contribute to which lower limb overuse conditions?","options": [{"key": "A","text": "ACL injury directly"},{"key": "B","text": "Medial tibial stress syndrome, PTTD, and plantar fasciitis"},{"key": "C","text": "Lateral ankle sprain primarily"},{"key": "D","text": "Hip labral tear directly"}],"correct": "B","explanation": "Excessive/prolonged pronation alters lower limb kinetic chain loading, contributing to conditions like MTSS and PTTD."},{"id": 8609,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "Foot orthoses are commonly prescribed to address which biomechanical issue contributing to overuse injuries?","options": [{"key": "A","text": "Muscle hypertrophy"},{"key": "B","text": "Only cosmetic concerns"},{"key": "C","text": "Bone density issues"},{"key": "D","text": "Excessive or prolonged pronation/supination patterns"}],"correct": "D","explanation": "Orthoses aim to modify abnormal foot mechanics (excessive pronation/supination) contributing to overuse injury patterns."},{"id": 8610,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "Which of the following best describes the primary role of the plantar fascia during weight-bearing gait?","options": [{"key": "A","text": "Providing dynamic support to the medial longitudinal arch via the windlass mechanism"},{"key": "B","text": "Preventing ankle inversion"},{"key": "C","text": "Acting as the primary shock absorber alone"},{"key": "D","text": "Providing sensory feedback only"}],"correct": "A","explanation": "The plantar fascia's windlass mechanism dynamically supports the arch and aids efficient propulsion during gait."},{"id": 8611,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Achilles tendon loading progression (isometric to isotonic to plyometric) in rehabilitation follows principles primarily aimed at:","options": [{"key": "A","text": "Immediate return to full sprinting"},{"key": "B","text": "Complete avoidance of loading until fully healed"},{"key": "C","text": "Gradual, progressive tendon loading to restore tolerance to functional/sporting demands"},{"key": "D","text": "Passive stretching only, no loading"}],"correct": "C","explanation": "Progressive loading protocols gradually build tendon capacity, mirroring the demands of eventual return to activity/sport."},{"id": 8612,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical spondylosis refers to:","options": [{"key": "A","text": "Degenerative changes of cervical intervertebral discs and facet joints"},{"key": "B","text": "Congenital vertebral fusion"},{"key": "C","text": "Acute disc herniation only"},{"key": "D","text": "Inflammatory arthritis of cervical spine"}],"correct": "A","explanation": "Cervical spondylosis is age-related degeneration affecting discs, facet joints, and associated structures."},{"id": 8613,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Hard","question": "Cervical radiculopathy most commonly results from:","options": [{"key": "A","text": "Ligamentous laxity"},{"key": "B","text": "Nerve root compression due to disc herniation or foraminal stenosis"},{"key": "C","text": "Muscle strain only"},{"key": "D","text": "Vascular insufficiency"}],"correct": "B","explanation": "Cervical radiculopathy typically results from mechanical compression/irritation of a nerve root, commonly from disc herniation or degenerative foraminal narrowing."},{"id": 8614,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Easy","question": "Which cervical nerve root is most commonly affected in cervical radiculopathy?","options": [{"key": "A","text": "T1"},{"key": "B","text": "C4"},{"key": "C","text": "C2"},{"key": "D","text": "C6"}],"correct": "D","explanation": "C6 and C7 nerve roots are most commonly affected in cervical radiculopathy, related to disc levels C5-C6 and C6-C7."},{"id": 8615,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical myelopathy results from compression of:","options": [{"key": "A","text": "Peripheral nerves"},{"key": "B","text": "The spinal cord itself within the cervical canal"},{"key": "C","text": "Vertebral artery only"},{"key": "D","text": "Only nerve roots exiting the foramen"}],"correct": "B","explanation": "Cervical myelopathy involves spinal cord compression, presenting with upper motor neuron signs, distinct from radiculopathy (nerve root)."},{"id": 8616,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Which clinical sign supports a diagnosis of cervical myelopathy rather than isolated radiculopathy?","options": [{"key": "A","text": "Normal reflexes with focal weakness only"},{"key": "B","text": "Absence of any neurological findings"},{"key": "C","text": "Isolated dermatomal sensory loss only"},{"key": "D","text": "Hoffman's sign, hyperreflexia, and gait disturbance"}],"correct": "D","explanation": "Upper motor neuron signs (hyperreflexia, Hoffman's sign, clonus, gait disturbance) distinguish myelopathy from simple radiculopathy."},{"id": 8617,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervicogenic headache typically originates from dysfunction of which upper cervical structures?","options": [{"key": "A","text": "Temporomandibular joint exclusively"},{"key": "B","text": "Lower cervical spine (C6-C7) exclusively"},{"key": "C","text": "Upper cervical joints (C1-C3) and associated musculature"},{"key": "D","text": "Thoracic spine only"}],"correct": "C","explanation": "Cervicogenic headache is attributed to referred pain from upper cervical spine (particularly C1-C3) structures."},{"id": 8618,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Whiplash-associated disorder (WAD) is graded using which classification system?","options": [{"key": "A","text": "Frankel classification"},{"key": "B","text": "Quebec Task Force classification (WAD I-IV)"},{"key": "C","text": "Neer classification"},{"key": "D","text": "ASIA classification"}],"correct": "B","explanation": "Quebec Task Force WAD grading (0-IV) classifies severity based on symptoms and objective findings."},{"id": 8619,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "WAD Grade II is characterized by:","options": [{"key": "A","text": "Neck complaints plus musculoskeletal signs (reduced ROM, point tenderness)"},{"key": "B","text": "No physical signs, symptoms only"},{"key": "C","text": "Neurological deficit with fracture"},{"key": "D","text": "Fracture or dislocation"}],"correct": "A","explanation": "WAD II includes musculoskeletal signs (reduced ROM, tenderness) in addition to neck complaints, without neurological signs."},{"id": 8620,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Torticollis (wry neck) is characterized by:","options": [{"key": "A","text": "Painless neck stiffness"},{"key": "B","text": "Complete neck immobility in all planes"},{"key": "C","text": "Bilateral neck flexion limitation only"},{"key": "D","text": "Involuntary lateral flexion with rotation of the neck, often with muscle spasm"}],"correct": "D","explanation": "Torticollis presents with asymmetric neck posture (lateral flexion + rotation), commonly involving sternocleidomastoid spasm."},{"id": 8621,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Congenital muscular torticollis in infants is most commonly related to:","options": [{"key": "A","text": "Atlantoaxial instability"},{"key": "B","text": "Sternocleidomastoid muscle fibrosis/contracture"},{"key": "C","text": "Brachial plexus injury"},{"key": "D","text": "Cervical vertebral fusion (Klippel-Feil)"}],"correct": "B","explanation": "Congenital muscular torticollis typically results from unilateral SCM fibrosis/shortening, often related to intrauterine positioning or birth trauma."},{"id": 8622,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Klippel-Feil syndrome is characterized by:","options": [{"key": "A","text": "Acute cervical fracture"},{"key": "B","text": "Congenital fusion of two or more cervical vertebrae"},{"key": "C","text": "Cervical rib anomaly only"},{"key": "D","text": "Acquired cervical disc degeneration"}],"correct": "B","explanation": "Klippel-Feil syndrome involves congenital fusion of cervical vertebrae, classically presenting with short neck, low hairline, and limited neck motion."},{"id": 8623,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Hard","question": "Vertebral artery insufficiency should be screened for before performing which type of cervical spine intervention?","options": [{"key": "A","text": "Postural correction advice"},{"key": "B","text": "High-velocity manipulation techniques"},{"key": "C","text": "Isometric neck exercises"},{"key": "D","text": "Superficial heat application"}],"correct": "B","explanation": "Given the risk of vertebrobasilar compromise, pre-manipulative screening (vertebral artery test, red flag screening) is essential before high-velocity thrust techniques."},{"id": 8624,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Easy","question": "Which of the following is considered a 'red flag' requiring urgent referral in cervical spine assessment?","options": [{"key": "A","text": "Localized muscle tenderness only"},{"key": "B","text": "Progressive neurological deficit or signs of cervical myelopathy"},{"key": "C","text": "Mild mechanical neck pain aggravated by movement"},{"key": "D","text": "Improvement with rest"}],"correct": "B","explanation": "Progressive neurological deficits, myelopathic signs, or signs of serious pathology (infection, tumor, fracture) are red flags requiring urgent medical referral."},{"id": 8625,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical facet joint pain (facet syndrome) typically presents with pain aggravated by:","options": [{"key": "A","text": "Only at rest"},{"key": "B","text": "Flexion only"},{"key": "C","text": "No positional relationship"},{"key": "D","text": "Extension and ipsilateral rotation/lateral flexion"}],"correct": "D","explanation": "Facet joint loading increases with extension combined with rotation/lateral flexion toward the affected side, reproducing facet-mediated pain."},{"id": 8626,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical disc herniation most commonly occurs at which levels?","options": [{"key": "A","text": "C7-T1 exclusively"},{"key": "B","text": "C1-C2 and C2-C3"},{"key": "C","text": "C5-C6 and C6-C7"},{"key": "D","text": "Uniformly across all levels"}],"correct": "C","explanation": "C5-C6 and C6-C7 are the most common levels for cervical disc herniation due to increased mobility/mechanical stress at these segments."},{"id": 8627,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Thoracic outlet syndrome symptoms overlapping with cervical spine conditions require differentiation primarily via:","options": [{"key": "A","text": "Careful clinical examination including provocative tests (Adson's, Roos) and neurological assessment"},{"key": "B","text": "Only patient's subjective description"},{"key": "C","text": "X-ray alone"},{"key": "D","text": "No differentiation is needed clinically"}],"correct": "A","explanation": "Clinical differentiation relies on combining history, provocative testing, and neurological examination to localize the source of symptoms."},{"id": 8628,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Postural (mechanical) neck pain related to prolonged forward head posture is commonly associated with which muscle imbalance?","options": [{"key": "A","text": "Tight deep cervical flexors"},{"key": "B","text": "Weak deep cervical flexors and tight upper trapezius/suboccipitals"},{"key": "C","text": "Weak upper trapezius only"},{"key": "D","text": "No consistent muscular pattern"}],"correct": "B","explanation": "Forward head posture is commonly linked with deep cervical flexor weakness alongside tightness of upper trapezius, levator scapulae, and suboccipital muscles."},{"id": 8629,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Easy","question": "Deep cervical flexor training (craniocervical flexion exercise) is a well-supported intervention for:","options": [{"key": "A","text": "Acute cervical fracture management"},{"key": "B","text": "Chronic mechanical neck pain and cervicogenic headache"},{"key": "C","text": "Vertebral artery insufficiency treatment"},{"key": "D","text": "Cervical myelopathy surgical alternative"}],"correct": "B","explanation": "Craniocervical flexion exercises target deep cervical flexor endurance/strength, evidence-supported for chronic neck pain and headache management."},{"id": 8630,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical spine capsular pattern shows greatest restriction typically in:","options": [{"key": "A","text": "Flexion only"},{"key": "B","text": "No consistent capsular pattern exists for cervical spine"},{"key": "C","text": "Lateral flexion and rotation equally limited, with some extension limitation"},{"key": "D","text": "Extension only significantly limited"}],"correct": "C","explanation": "Cervical spine capsular pattern (per Cyriax) shows fairly equal limitation of rotation and lateral flexion with some extension restriction."},{"id": 8631,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical spine traction is sometimes used therapeutically primarily to:","options": [{"key": "A","text": "Reduce nerve root compression symptoms via decreasing intradiscal pressure/increasing foraminal space"},{"key": "B","text": "Worsen radicular symptoms intentionally"},{"key": "C","text": "Replace exercise therapy entirely"},{"key": "D","text": "Increase intradiscal pressure"}],"correct": "A","explanation": "Cervical traction aims to reduce compressive forces on nerve roots by increasing intervertebral foraminal space and reducing disc pressure."},{"id": 8632,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical spine instability (e.g., in rheumatoid arthritis affecting C1-C2) poses significant risk of:","options": [{"key": "A","text": "Only cosmetic deformity"},{"key": "B","text": "Peripheral joint pain only"},{"key": "C","text": "Spinal cord compression/injury from atlantoaxial subluxation"},{"key": "D","text": "No serious risk if asymptomatic"}],"correct": "C","explanation": "Atlantoaxial instability, common in longstanding RA, carries risk of spinal cord compression, requiring careful screening before manual techniques."},{"id": 8633,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Hard","question": "Which special test is used to specifically screen for upper cervical (craniovertebral) ligamentous instability?","options": [{"key": "A","text": "Spurling's test"},{"key": "B","text": "Distraction test"},{"key": "C","text": "Sharp-Purser test / alar ligament stress test"},{"key": "D","text": "Vertebral artery test"}],"correct": "C","explanation": "Sharp-Purser test and alar ligament stress tests specifically assess craniovertebral ligamentous (transverse/alar ligament) integrity."},{"id": 8634,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Cervicogenic dizziness is thought to arise from disturbed input from which structures?","options": [{"key": "A","text": "Cervical proprioceptors (upper cervical spine mechanoreceptors)"},{"key": "B","text": "Visual system primarily"},{"key": "C","text": "Vestibular apparatus primarily"},{"key": "D","text": "Cardiovascular system"}],"correct": "A","explanation": "Cervicogenic dizziness is attributed to altered proprioceptive input from upper cervical joint/muscle mechanoreceptors."},{"id": 8635,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Manual therapy combined with exercise is generally supported by evidence for management of:","options": [{"key": "A","text": "Mechanical neck pain (non-specific)"},{"key": "B","text": "Only post-surgical cervical fusion cases"},{"key": "C","text": "Acute cervical fracture"},{"key": "D","text": "Cervical myelopathy as sole treatment"}],"correct": "A","explanation": "Combined manual therapy and exercise approaches have good evidence support for mechanical/non-specific neck pain management."},{"id": 8636,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which condition presents with neck pain, arm pain following a dermatomal pattern, and a positive Spurling's test?","options": [{"key": "A","text": "Cervical myelopathy"},{"key": "B","text": "Thoracic outlet syndrome primarily"},{"key": "C","text": "Fibromyalgia"},{"key": "D","text": "Cervical radiculopathy"}],"correct": "D","explanation": "Dermatomal arm pain with positive foraminal compression testing (Spurling's) is characteristic of cervical radiculopathy."},{"id": 8637,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical extension-compression injuries (e.g., diving into shallow water) are particularly concerning due to risk of:","options": [{"key": "A","text": "Simple muscle strain only"},{"key": "B","text": "Central cord syndrome"},{"key": "C","text": "No significant risk"},{"key": "D","text": "Isolated peripheral nerve injury only"}],"correct": "B","explanation": "Hyperextension injuries in a stenotic cervical canal are classically associated with central cord syndrome."},{"id": 8638,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Central cord syndrome classically presents with:","options": [{"key": "A","text": "Isolated sensory loss without motor involvement"},{"key": "B","text": "Motor weakness greater in lower limbs than upper limbs"},{"key": "C","text": "Motor weakness greater in upper limbs than lower limbs"},{"key": "D","text": "Complete symmetric paralysis"}],"correct": "C","explanation": "Central cord syndrome, often from hyperextension injury, classically causes disproportionately greater upper limb weakness due to central cord fiber organization."},{"id": 8639,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Easy","question": "Cervical spine range of motion assessment for rotation is often performed with which additional consideration?","options": [{"key": "A","text": "Stabilizing/differentiating upper cervical vs lower cervical contribution"},{"key": "B","text": "Testing only with cervical flexion combined"},{"key": "C","text": "Only measuring total ROM without segmental consideration"},{"key": "D","text": "Never clinically relevant"}],"correct": "A","explanation": "Understanding relative contribution of upper (C1-C2, ~50% of rotation) vs lower cervical segments aids in localizing dysfunction."},{"id": 8640,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical dystonia (spasmodic torticollis) in adults is classified as which type of movement disorder?","options": [{"key": "A","text": "Peripheral neuropathy"},{"key": "B","text": "Focal dystonia"},{"key": "C","text": "Myopathy"},{"key": "D","text": "Radiculopathy"}],"correct": "B","explanation": "Cervical dystonia is a focal movement disorder causing involuntary, sustained neck muscle contractions."},{"id": 8641,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Neck disability index (NDI) is used clinically to assess:","options": [{"key": "A","text": "Self-reported functional limitation due to neck pain"},{"key": "B","text": "Muscle strength directly"},{"key": "C","text": "Radiological severity"},{"key": "D","text": "Cervical ROM objectively"}],"correct": "A","explanation": "NDI is a validated patient-reported outcome measure assessing functional disability related to neck pain."},{"id": 8642,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Cervicogenic headache is typically differentiated from migraine by which key feature?","options": [{"key": "A","text": "Bilateral throbbing headache with photophobia primarily"},{"key": "B","text": "Nausea and vomiting as primary features"},{"key": "C","text": "Aura preceding headache"},{"key": "D","text": "Unilateral headache associated with neck movement/posture and reproducible with manual cervical provocation"}],"correct": "D","explanation": "Cervicogenic headache classically shows a relationship to neck movement/position and reproducibility with cervical spine provocation testing, unlike migraine's vascular/neurological features."},{"id": 8643,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Hard","question": "Thoracic spine mobility deficits can contribute to cervical spine dysfunction due to:","options": [{"key": "A","text": "Compensatory increased stress/motion demand on the cervical spine"},{"key": "B","text": "Direct effect on peripheral nerves only"},{"key": "C","text": "No biomechanical relationship exists"},{"key": "D","text": "Only affecting lumbar spine"}],"correct": "A","explanation": "Reduced thoracic mobility can lead to compensatory overuse/stress at the cervical spine, a rationale for including thoracic assessment/treatment in neck pain management."},{"id": 8644,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Easy","question": "Which muscle group is commonly targeted for stretching in patients with upper crossed syndrome affecting the cervical region?","options": [{"key": "A","text": "Lower trapezius"},{"key": "B","text": "Serratus anterior"},{"key": "C","text": "Deep cervical flexors"},{"key": "D","text": "Upper trapezius, levator scapulae, and suboccipitals"}],"correct": "D","explanation": "Upper crossed syndrome involves tightness of upper trapezius, levator scapulae, and suboccipital muscles, typically targeted for stretching alongside deep flexor strengthening."},{"id": 8645,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Cervical spine assessment in patients with a history of trauma should always first rule out:","options": [{"key": "A","text": "Postural dysfunction"},{"key": "B","text": "Muscle strain only"},{"key": "C","text": "Chronic degenerative changes"},{"key": "D","text": "Fracture/instability (using appropriate clinical decision rules like Canadian C-spine rule)"}],"correct": "D","explanation": "Serious pathology (fracture, instability) must be ruled out first in trauma cases, guided by validated clinical decision rules before proceeding with further assessment/treatment."},{"id": 8646,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Nerve root tension tests for the upper limb (e.g., Upper Limb Neurodynamic Test - ULNT) are used to assess:","options": [{"key": "A","text": "Vascular supply"},{"key": "B","text": "Mechanosensitivity of cervical nerve roots and peripheral nerve pathways"},{"key": "C","text": "Joint ROM only"},{"key": "D","text": "Muscle strength only"}],"correct": "B","explanation": "ULNTs assess neural mechanosensitivity along the nerve pathway from cervical spine to hand, useful in differentiating neural involvement in arm symptoms."},{"id": 8647,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Lumbar disc herniation most commonly occurs at which levels?","options": [{"key": "A","text": "T12-L1 exclusively"},{"key": "B","text": "L4-L5 and L5-S1"},{"key": "C","text": "L1-L2 and L2-L3"},{"key": "D","text": "Equally at all lumbar levels"}],"correct": "B","explanation": "L4-L5 and L5-S1 are the most common levels for lumbar disc herniation due to greatest mechanical stress at the lumbosacral junction."},{"id": 8648,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "A posterolateral disc herniation at L4-L5 most commonly compresses which nerve root?","options": [{"key": "A","text": "L5 nerve root"},{"key": "B","text": "L3 nerve root"},{"key": "C","text": "L4 nerve root"},{"key": "D","text": "S1 nerve root exclusively"}],"correct": "A","explanation": "Posterolateral herniation at L4-L5 typically affects the traversing L5 nerve root (exiting at the level below)."},{"id": 8649,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "A far lateral (foraminal) disc herniation at L4-L5 would most likely affect which nerve root?","options": [{"key": "A","text": "S1 nerve root"},{"key": "B","text": "L5 nerve root"},{"key": "C","text": "L4 nerve root (exiting nerve root at that level)"},{"key": "D","text": "No nerve root affected"}],"correct": "C","explanation": "Far lateral/foraminal herniations affect the exiting nerve root at that same level (L4 at the L4-L5 foramen), unlike posterolateral herniations affecting the traversing root."},{"id": 8650,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Cauda equina syndrome is a surgical emergency characterized by:","options": [{"key": "A","text": "Saddle anesthesia, bowel/bladder dysfunction, and bilateral leg symptoms"},{"key": "B","text": "Isolated foot drop"},{"key": "C","text": "Unilateral leg pain only"},{"key": "D","text": "Mild low back pain without neurological signs"}],"correct": "A","explanation": "Cauda equina syndrome presents with red flag features including saddle anesthesia and bladder/bowel dysfunction, requiring urgent surgical referral."},{"id": 8651,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Spondylolysis refers to:","options": [{"key": "A","text": "A defect/fracture of the pars interarticularis"},{"key": "B","text": "Vertebral body compression fracture"},{"key": "C","text": "Disc herniation"},{"key": "D","text": "Facet joint dislocation"}],"correct": "A","explanation": "Spondylolysis is a stress fracture/defect of the pars interarticularis, commonly at L5."},{"id": 8652,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Spondylolisthesis refers to:","options": [{"key": "A","text": "Vertebral fusion"},{"key": "B","text": "Ligamentous calcification"},{"key": "C","text": "Anterior (or posterior) slippage of one vertebra relative to the adjacent vertebra"},{"key": "D","text": "Disc desiccation"}],"correct": "C","explanation": "Spondylolisthesis involves forward (or less commonly backward/retrolisthesis) slippage of a vertebral body relative to the one below."},{"id": 8653,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Isthmic spondylolisthesis is most commonly caused by:","options": [{"key": "A","text": "Congenital vertebral anomaly exclusively"},{"key": "B","text": "Traumatic fracture-dislocation"},{"key": "C","text": "Degenerative facet joint changes"},{"key": "D","text": "Bilateral pars interarticularis defect (spondylolysis)"}],"correct": "D","explanation": "Isthmic spondylolisthesis results from bilateral pars defects (spondylolysis), commonly seen in adolescent athletes (e.g., gymnasts, fast bowlers)."},{"id": 8654,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Degenerative spondylolisthesis most commonly occurs at which level and population?","options": [{"key": "A","text": "L4-L5, in older adults due to facet joint degeneration"},{"key": "B","text": "L5-S1, in adolescents"},{"key": "C","text": "T12-L1, in young athletes"},{"key": "D","text": "Cervical spine, in infants"}],"correct": "A","explanation": "Degenerative spondylolisthesis typically occurs at L4-L5 in older adults, related to facet joint arthropathy and disc degeneration."},{"id": 8655,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Spondylolisthesis is graded using the Meyerding classification based on:","options": [{"key": "A","text": "Percentage of vertebral slip relative to the vertebra below"},{"key": "B","text": "Nerve root compression severity"},{"key": "C","text": "Degree of disc herniation"},{"key": "D","text": "Facet joint angle"}],"correct": "A","explanation": "Meyerding classification grades I-V based on percentage of anterior slippage of the vertebral body."},{"id": 8656,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Lumbar spinal stenosis classically presents with symptoms relieved by which position/activity?","options": [{"key": "A","text": "Extension"},{"key": "B","text": "Flexion (e.g., leaning forward, sitting) - neurogenic claudication pattern"},{"key": "C","text": "Standing upright without flexion"},{"key": "D","text": "Lying supine with legs extended"}],"correct": "B","explanation": "Neurogenic claudication from lumbar stenosis typically improves with flexion (increasing canal space) and worsens with extension/standing."},{"id": 8657,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Neurogenic claudication (from spinal stenosis) is differentiated from vascular claudication primarily by:","options": [{"key": "A","text": "Relief only with rest regardless of position"},{"key": "B","text": "No positional relationship to symptoms"},{"key": "C","text": "Absent peripheral pulses always"},{"key": "D","text": "Relief with flexion/sitting rather than simply stopping walking; pulses typically normal"}],"correct": "D","explanation": "Neurogenic claudication improves specifically with spinal flexion (not just rest), and peripheral pulses remain normal, unlike vascular claudication."},{"id": 8658,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Degenerative disc disease is characterized radiographically by which finding?","options": [{"key": "A","text": "Normal disc height with facet fusion"},{"key": "B","text": "Vertebral body fracture"},{"key": "C","text": "Widened disc space"},{"key": "D","text": "Disc space narrowing with osteophyte formation"}],"correct": "D","explanation": "DDD shows disc height loss, endplate sclerosis, and osteophyte formation on imaging, reflecting degenerative changes."},{"id": 8659,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Easy","question": "Facet joint syndrome of the lumbar spine typically presents with pain aggravated by:","options": [{"key": "A","text": "No positional relationship"},{"key": "B","text": "Extension and rotation"},{"key": "C","text": "Only with coughing"},{"key": "D","text": "Flexion primarily"}],"correct": "B","explanation": "Lumbar facet-mediated pain classically worsens with extension and rotation, which load the posterior elements."},{"id": 8660,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sacroiliac joint dysfunction commonly presents with pain located:","options": [{"key": "A","text": "Central low back pain with bilateral leg symptoms always"},{"key": "B","text": "Below L5, over the posterior superior iliac spine, often unilateral"},{"key": "C","text": "Above L1 exclusively"},{"key": "D","text": "Only in the anterior abdomen"}],"correct": "B","explanation": "SIJ pain typically localizes below L5 near the PSIS, often unilateral, sometimes referring into the buttock/posterior thigh."},{"id": 8661,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ankylosing spondylitis classically presents with which pattern of back pain?","options": [{"key": "A","text": "Sudden onset following trauma only"},{"key": "B","text": "Mechanical pain worse with activity, better with rest"},{"key": "C","text": "Inflammatory back pain: insidious onset, morning stiffness >30 min, improves with activity"},{"key": "D","text": "Pain only with sitting"}],"correct": "C","explanation": "Inflammatory back pain pattern (insidious onset in young adults, prolonged morning stiffness, improvement with exercise) is characteristic of AS."},{"id": 8662,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Scheuermann's disease (juvenile kyphosis) is characterized by:","options": [{"key": "A","text": "Isolated disc herniation"},{"key": "B","text": "Anterior vertebral body wedging (>5°) at three or more consecutive levels causing structural kyphosis"},{"key": "C","text": "Lateral vertebral curvature"},{"key": "D","text": "Spondylolisthesis"}],"correct": "B","explanation": "Scheuermann's disease involves structural thoracic kyphosis from anterior wedging of multiple consecutive vertebrae during growth."},{"id": 8663,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Idiopathic scoliosis most commonly affects which population?","options": [{"key": "A","text": "Elderly males"},{"key": "B","text": "Infants exclusively"},{"key": "C","text": "Adolescent females during growth spurt (Adolescent Idiopathic Scoliosis)"},{"key": "D","text": "Adult males primarily"}],"correct": "C","explanation": "AIS is the most common type, predominantly affecting adolescent females during the pubertal growth spurt."},{"id": 8664,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Cobb angle is used to quantify severity of:","options": [{"key": "A","text": "Spondylolisthesis grade"},{"key": "B","text": "Scoliosis curvature on radiographs"},{"key": "C","text": "Lordosis only"},{"key": "D","text": "Kyphosis only"}],"correct": "B","explanation": "Cobb angle measures the degree of lateral spinal curvature on standing radiographs, standard for scoliosis assessment."},{"id": 8665,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Bracing for adolescent idiopathic scoliosis is generally considered for curves in which Cobb angle range (with growth remaining)?","options": [{"key": "A","text": "Greater than 50° always braced instead of surgery"},{"key": "B","text": "Approximately 25-40°"},{"key": "C","text": "Less than 10°"},{"key": "D","text": "No bracing is ever used"}],"correct": "B","explanation": "Bracing is generally considered for moderate curves (~25-40°) in skeletally immature patients to prevent progression."},{"id": 8666,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Surgical intervention (spinal fusion) for scoliosis is generally considered when Cobb angle exceeds approximately:","options": [{"key": "A","text": "45-50°"},{"key": "B","text": "20°"},{"key": "C","text": "10°"},{"key": "D","text": "30° in all cases regardless of growth"}],"correct": "A","explanation": "Surgical fusion is generally considered for curves exceeding approximately 45-50°, especially with continued growth or risk of progression."},{"id": 8667,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "McKenzie method (Mechanical Diagnosis and Therapy) classifies spinal disorders primarily based on:","options": [{"key": "A","text": "Directional preference and centralization/peripheralization of symptoms with repeated movements"},{"key": "B","text": "Age of patient"},{"key": "C","text": "Duration of symptoms only"},{"key": "D","text": "Imaging findings alone"}],"correct": "A","explanation": "MDT classification relies on patient's symptomatic response (centralization/peripheralization) to repeated end-range movements."},{"id": 8668,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "'Centralization' phenomenon in McKenzie assessment refers to:","options": [{"key": "A","text": "Symptoms spreading further into the limb"},{"key": "B","text": "Complete resolution of all pain immediately"},{"key": "C","text": "No change in symptom location"},{"key": "D","text": "Progressive movement of peripheral/radiating symptoms toward the spine's midline with repeated movement testing"}],"correct": "D","explanation": "Centralization describes symptoms retreating from distal to more proximal/central location, a favorable prognostic sign."},{"id": 8669,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Directional preference in low back pain most commonly favors which movement for posterior disc-related presentations?","options": [{"key": "A","text": "Extension"},{"key": "B","text": "Lateral flexion only"},{"key": "C","text": "Rotation only"},{"key": "D","text": "Flexion"}],"correct": "A","explanation": "Many posterior disc bulge presentations show a directional preference for extension, which can centralize symptoms."},{"id": 8670,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Flexion-biased exercises are generally more appropriate for which lumbar spine condition?","options": [{"key": "A","text": "Lumbar spinal stenosis with neurogenic claudication"},{"key": "B","text": "Spondylolisthesis with instability"},{"key": "C","text": "Facet joint syndrome"},{"key": "D","text": "Posterior disc herniation with extension preference"}],"correct": "A","explanation": "Flexion increases canal diameter, providing symptomatic relief in stenosis, making flexion-biased exercises/postures beneficial."},{"id": 8671,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Extension-biased exercises are generally contraindicated or used cautiously in which condition?","options": [{"key": "A","text": "Posterior disc bulge with extension preference"},{"key": "B","text": "Postural low back pain"},{"key": "C","text": "Spondylolisthesis with instability and lumbar spinal stenosis"},{"key": "D","text": "Facet joint hypomobility"}],"correct": "C","explanation": "Extension can increase symptoms in stenosis (narrows canal) and may exacerbate instability in spondylolisthesis, requiring cautious/modified approach."},{"id": 8672,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Core stability/motor control training for low back pain primarily targets which muscles?","options": [{"key": "A","text": "Transversus abdominis, multifidus, and other deep spinal stabilizers"},{"key": "B","text": "Latissimus dorsi primarily"},{"key": "C","text": "Only rectus abdominis"},{"key": "D","text": "Only erector spinae superficial fibers"}],"correct": "A","explanation": "Motor control approaches focus on deep stabilizing muscles (TrA, multifidus) that provide segmental spinal stability."},{"id": 8673,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which classification system for low back pain categorizes patients based on treatment-based subgroups (e.g., manipulation, stabilization, specific exercise)?","options": [{"key": "A","text": "Waddell's signs classification"},{"key": "B","text": "Quebec Task Force classification for LBP disability only"},{"key": "C","text": "Only imaging-based classification"},{"key": "D","text": "Treatment-Based Classification (TBC) system"}],"correct": "D","explanation": "Treatment-based classification categorizes LBP patients into subgroups predicted to respond to specific interventions (manipulation, stabilization, directional exercise, traction)."},{"id": 8674,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Non-specific low back pain accounts for approximately what percentage of LBP presentations in primary care?","options": [{"key": "A","text": "10%"},{"key": "B","text": "50%"},{"key": "C","text": "Approximately 85-90%"},{"key": "D","text": "Nearly 0%"}],"correct": "C","explanation": "The majority of LBP presentations (~85-90%) are classified as non-specific, without a definitive identifiable pathoanatomical source."},{"id": 8675,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which is considered a psychosocial 'yellow flag' in low back pain assessment?","options": [{"key": "A","text": "Radiating leg pain"},{"key": "B","text": "Reduced ankle reflex"},{"key": "C","text": "Positive SLR test"},{"key": "D","text": "Fear-avoidance beliefs and catastrophizing about pain"}],"correct": "D","explanation": "Yellow flags refer to psychosocial risk factors (fear-avoidance, catastrophizing, low mood) predicting poor LBP outcomes/chronicity."},{"id": 8676,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which of the following is considered a 'red flag' in acute low back pain assessment?","options": [{"key": "A","text": "Age between 20-40 years"},{"key": "B","text": "Unexplained weight loss, history of cancer, or progressive neurological deficit"},{"key": "C","text": "Mechanical pain pattern worse with movement"},{"key": "D","text": "Improvement with rest"}],"correct": "B","explanation": "Red flags suggest possible serious underlying pathology (malignancy, infection, fracture, cauda equina), warranting further investigation."},{"id": 8677,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Modic changes on lumbar MRI refer to:","options": [{"key": "A","text": "Disc herniation type"},{"key": "B","text": "Ligamentous ossification"},{"key": "C","text": "Vertebral endplate and bone marrow signal changes associated with degenerative disc disease"},{"key": "D","text": "Facet joint arthropathy grade"}],"correct": "C","explanation": "Modic changes (Type I-III) describe vertebral endplate/marrow signal alterations seen with disc degeneration, associated with pain in some patients."},{"id": 8678,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Hard","question": "Thoracic spine hypomobility can contribute to which compensatory dysfunction pattern?","options": [{"key": "A","text": "Reduced motion at all adjacent segments"},{"key": "B","text": "Only local thoracic pain, no distal effects"},{"key": "C","text": "Increased compensatory mobility demand at cervical and lumbar spine"},{"key": "D","text": "No effect on adjacent regions"}],"correct": "C","explanation": "Reduced thoracic mobility often results in compensatory increased stress/motion at the more mobile cervical and lumbar regions."},{"id": 8679,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Costovertebral joint dysfunction can present clinically with pain mimicking:","options": [{"key": "A","text": "Wrist pain"},{"key": "B","text": "Rib pain or referred pain patterns that can mimic cardiac/visceral pain"},{"key": "C","text": "Ankle pain"},{"key": "D","text": "Only isolated cervical pain"}],"correct": "B","explanation": "Costovertebral joint dysfunction can cause localized rib pain and referred patterns sometimes concerning for cardiac or visceral origin, requiring careful differential diagnosis."},{"id": 8680,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which condition is characterized by calcification/ossification of spinal ligaments, particularly affecting the elderly, causing stiffness without significant inflammatory markers?","options": [{"key": "A","text": "Diffuse Idiopathic Skeletal Hyperostosis (DISH)"},{"key": "B","text": "Osteoporosis"},{"key": "C","text": "Ankylosing spondylitis"},{"key": "D","text": "Rheumatoid arthritis"}],"correct": "A","explanation": "DISH involves flowing ossification of spinal ligaments (especially ALL), typically in older patients, without the inflammatory markers seen in AS."},{"id": 8681,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Thoracic kyphosis increases progressively with age most commonly due to:","options": [{"key": "A","text": "Muscle hypertrophy"},{"key": "B","text": "Ligament laxity alone"},{"key": "C","text": "Vertebral compression fractures and disc degeneration (often osteoporosis-related)"},{"key": "D","text": "Genetic factors exclusively"}],"correct": "C","explanation": "Age-related increased kyphosis is often linked to osteoporotic vertebral compression fractures and disc height loss."},{"id": 8682,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which special test assesses sacroiliac joint provocation by applying posterior-to-anterior shear force through a flexed hip/knee?","options": [{"key": "A","text": "Thigh thrust (posterior shear) test"},{"key": "B","text": "Compression test only"},{"key": "C","text": "FABER test only"},{"key": "D","text": "Gaenslen's test only"}],"correct": "A","explanation": "Thigh thrust test applies direct shear force through the femur to stress the SI joint, part of a cluster of SIJ provocation tests."},{"id": 8683,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "A cluster of positive SI joint provocation tests (e.g., 3 or more of distraction, compression, thigh thrust, Gaenslen's, sacral thrust) increases diagnostic confidence for:","options": [{"key": "A","text": "Lumbar disc herniation"},{"key": "B","text": "Hip osteoarthritis"},{"key": "C","text": "Facet joint syndrome"},{"key": "D","text": "Sacroiliac joint pain as the pain generator"}],"correct": "D","explanation": "Using a cluster of SIJ provocation tests improves diagnostic accuracy for SIJ-related pain compared to any single test alone."},{"id": 8684,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which exercise approach has strong evidence support as first-line management for chronic non-specific low back pain?","options": [{"key": "A","text": "Bed rest for extended periods"},{"key": "B","text": "Surgery as first-line"},{"key": "C","text": "Passive modalities alone without exercise"},{"key": "D","text": "General exercise therapy (regardless of specific type) combined with education"}],"correct": "D","explanation": "Current guidelines strongly support active exercise therapy and education as first-line management for chronic non-specific LBP over passive/surgical approaches."},{"id": 8685,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Prolonged bed rest for acute low back pain is now considered:","options": [{"key": "A","text": "Required for at least 2 weeks"},{"key": "B","text": "Generally not recommended; early activity/mobilization is preferred"},{"key": "C","text": "The gold standard treatment"},{"key": "D","text": "Only appropriate for cauda equina syndrome patients"}],"correct": "B","explanation": "Evidence supports early mobilization and staying active over prolonged bed rest, which is associated with worse outcomes for most LBP presentations."},{"id": 8686,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Manipulation of the lumbar spine is generally supported by evidence for:","options": [{"key": "A","text": "Acute non-specific low back pain, particularly as part of a multimodal approach"},{"key": "B","text": "Severe osteoporosis with compression fracture"},{"key": "C","text": "Confirmed spinal fracture"},{"key": "D","text": "Cauda equina syndrome"}],"correct": "A","explanation": "Spinal manipulation has evidence support for acute non-specific LBP as part of a comprehensive management approach, contraindicated in fracture/serious pathology."},{"id": 8687,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Spinal stenosis surgical decompression is generally considered when:","options": [{"key": "A","text": "Significant functional limitation persists despite adequate conservative management"},{"key": "B","text": "Immediately upon diagnosis regardless of symptoms"},{"key": "C","text": "Only in young patients"},{"key": "D","text": "Never indicated regardless of severity"}],"correct": "A","explanation": "Surgery is typically reserved for patients with significant ongoing functional limitation after failed conservative management trial."},{"id": 8688,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which factor differentiates mechanical low back pain from inflammatory back pain in history taking?","options": [{"key": "A","text": "Inflammatory pain is always acute onset following trauma"},{"key": "B","text": "Both present identically"},{"key": "C","text": "Mechanical pain always has morning stiffness over 1 hour"},{"key": "D","text": "Mechanical pain worsens with activity and improves with rest; inflammatory pain improves with activity"}],"correct": "D","explanation": "Mechanical LBP typically worsens with activity/improves with rest, whereas inflammatory back pain characteristically improves with movement and worsens with rest/morning stiffness."},{"id": 8689,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Easy","question": "Straight leg raise test sensitivity for lumbar disc herniation with nerve root involvement is generally considered:","options": [{"key": "A","text": "High sensitivity but lower specificity"},{"key": "B","text": "100% accurate diagnostic test"},{"key": "C","text": "Neither sensitive nor specific"},{"key": "D","text": "Low sensitivity, high specificity"}],"correct": "A","explanation": "SLR is a sensitive test for nerve root tension from disc herniation but has relatively lower specificity, meaning false positives can occur."},{"id": 8690,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Crossed SLR test has which characteristic compared to standard SLR?","options": [{"key": "A","text": "Lower sensitivity but higher specificity for disc herniation"},{"key": "B","text": "Higher sensitivity, lower specificity"},{"key": "C","text": "Equal sensitivity and specificity"},{"key": "D","text": "No diagnostic value"}],"correct": "A","explanation": "Crossed SLR (pain in affected leg when raising the unaffected leg) is less commonly positive but more specific for disc herniation when present."},{"id": 8691,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Segmental instability of the lumbar spine is best assessed clinically using a combination of:","options": [{"key": "A","text": "Only patient-reported pain scores"},{"key": "B","text": "X-ray alone"},{"key": "C","text": "Prone instability test, aberrant movement patterns, and patient history of 'catching/giving way'"},{"key": "D","text": "MRI alone without clinical correlation"}],"correct": "C","explanation": "Clinical instability assessment combines specific tests (prone instability test), observed aberrant movement patterns, and history features suggestive of instability."},{"id": 8692,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Aberrant movement patterns (e.g., painful arc of motion, reversal of lumbopelvic rhythm) observed during lumbar flexion-extension testing suggest:","options": [{"key": "A","text": "Normal spinal function"},{"key": "B","text": "Disc herniation exclusively"},{"key": "C","text": "Facet joint ankylosis"},{"key": "D","text": "Possible clinical lumbar instability"}],"correct": "D","explanation": "Aberrant movements during active spinal testing are considered clinical indicators potentially associated with segmental instability."},{"id": 8693,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which patient-reported outcome measure is commonly used to assess disability related to low back pain?","options": [{"key": "A","text": "DASH score"},{"key": "B","text": "Neck Disability Index"},{"key": "C","text": "Oswestry Disability Index (ODI)"},{"key": "D","text": "Harris Hip Score"}],"correct": "C","explanation": "Oswestry Disability Index is a widely used, validated tool for assessing functional disability related to low back pain."},{"id": 8694,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Roland-Morris Disability Questionnaire is another validated tool used to assess:","options": [{"key": "A","text": "Low back pain related disability"},{"key": "B","text": "Knee function"},{"key": "C","text": "Neck pain disability"},{"key": "D","text": "Shoulder function"}],"correct": "A","explanation": "Roland-Morris Disability Questionnaire is a commonly used patient-reported outcome measure for low back pain functional disability."},{"id": 8695,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Which of the following describes 'lumbar instability' from a clinical biomechanical perspective (Panjabi's model)?","options": [{"key": "A","text": "Complete absence of spinal motion"},{"key": "B","text": "Normal spinal function with increased strength"},{"key": "C","text": "Loss of the spine's ability to maintain its pattern of displacement under physiological loads, causing symptoms"},{"key": "D","text": "Excessive spinal stiffness"}],"correct": "C","explanation": "Panjabi's model describes clinical instability as reduced capacity of the spinal stabilizing system to maintain intervertebral neutral zones within physiological limits."},{"id": 8696,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Which of the following muscles is a key target in lumbar segmental stabilization exercise programs due to its deep stabilizing role?","options": [{"key": "A","text": "Quadratus lumborum exclusively"},{"key": "B","text": "Multifidus"},{"key": "C","text": "Rectus abdominis (superficial)"},{"key": "D","text": "Latissimus dorsi"}],"correct": "B","explanation": "Multifidus provides crucial segmental spinal stability and is commonly atrophied/inhibited in chronic LBP, targeted in stabilization programs."},{"id": 8697,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pregnancy-related pelvic girdle pain most commonly involves which joint(s)?","options": [{"key": "A","text": "Lumbar facet joints exclusively"},{"key": "B","text": "Sacroiliac joints and/or pubic symphysis"},{"key": "C","text": "Knee joints"},{"key": "D","text": "Hip joints exclusively"}],"correct": "B","explanation": "Hormonal changes (relaxin) and biomechanical load increase during pregnancy commonly affect SI joints and pubic symphysis, causing pelvic girdle pain."},{"id": 8698,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Coccydynia (tailbone pain) is commonly aggravated by:","options": [{"key": "A","text": "Standing only"},{"key": "B","text": "Lying prone"},{"key": "C","text": "Prolonged sitting, especially on hard surfaces"},{"key": "D","text": "Walking only"}],"correct": "C","explanation": "Coccydynia typically worsens with sitting, particularly prolonged sitting or on hard surfaces, due to direct pressure on the coccyx."},{"id": 8699,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which biomechanical factor is most associated with increased risk of low back pain in occupational settings?","options": [{"key": "A","text": "Regular moderate exercise"},{"key": "B","text": "Repetitive heavy lifting with poor technique and prolonged awkward postures"},{"key": "C","text": "Ergonomically optimized workstations"},{"key": "D","text": "Adequate rest breaks"}],"correct": "B","explanation": "Occupational risk factors for LBP include repetitive/heavy manual handling, awkward sustained postures, and vibration exposure."},{"id": 8700,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Graded activity/graded exposure approaches in chronic low back pain rehabilitation primarily aim to address:","options": [{"key": "A","text": "Surgical candidacy"},{"key": "B","text": "Fear-avoidance behavior and gradually restore functional capacity"},{"key": "C","text": "Only physical deconditioning without addressing psychological factors"},{"key": "D","text": "Acute tissue healing exclusively"}],"correct": "B","explanation": "Graded activity/exposure programs specifically target fear-avoidance beliefs, gradually reintroducing feared movements/activities to restore function."},{"id": 8701,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Biopsychosocial model application in chronic low back pain management emphasizes addressing:","options": [{"key": "A","text": "Only social factors, ignoring physical impairments"},{"key": "B","text": "Only psychological factors"},{"key": "C","text": "Biological, psychological, and social factors contributing to pain and disability"},{"key": "D","text": "Only the biological/tissue pathology component"}],"correct": "C","explanation": "The biopsychosocial model recognizes that chronic pain and disability result from interacting biological, psychological, and social factors, guiding comprehensive management."},{"id": 8702,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Rheumatoid arthritis is classified as which type of disease process?","options": [{"key": "A","text": "Degenerative joint disease"},{"key": "B","text": "Crystal-induced arthropathy"},{"key": "C","text": "Infectious arthritis"},{"key": "D","text": "Autoimmune inflammatory polyarthritis"}],"correct": "D","explanation": "RA is a systemic autoimmune disease causing chronic symmetric inflammatory polyarthritis."},{"id": 8703,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Rheumatoid arthritis classically affects joints in which pattern?","options": [{"key": "A","text": "Asymmetric, large joints only"},{"key": "B","text": "DIP joints predominantly"},{"key": "C","text": "Only axial spine joints"},{"key": "D","text": "Symmetric, small joints of hands and feet first (MCP, PIP, MTP)"}],"correct": "D","explanation": "RA typically presents with symmetric polyarthritis affecting small joints (MCP, PIP, MTP), sparing DIP joints (unlike OA)."},{"id": 8704,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Morning stiffness in rheumatoid arthritis typically lasts:","options": [{"key": "A","text": "More than 30-60 minutes"},{"key": "B","text": "Only a few seconds"},{"key": "C","text": "Less than 15 minutes"},{"key": "D","text": "Absent entirely"}],"correct": "A","explanation": "Prolonged morning stiffness (>30-60 min) is characteristic of inflammatory arthritis like RA, distinguishing it from OA's brief stiffness."},{"id": 8705,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which laboratory marker, along with rheumatoid factor, is more specific for rheumatoid arthritis diagnosis?","options": [{"key": "A","text": "Anti-CCP (anti-cyclic citrullinated peptide) antibody"},{"key": "B","text": "CRP alone"},{"key": "C","text": "Uric acid level"},{"key": "D","text": "ESR alone"}],"correct": "A","explanation": "Anti-CCP antibodies have higher specificity for RA diagnosis compared to rheumatoid factor alone."},{"id": 8706,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteoarthritis is best characterized as:","options": [{"key": "A","text": "An infectious process"},{"key": "B","text": "A degenerative joint disease involving progressive cartilage loss and bony remodeling"},{"key": "C","text": "An autoimmune inflammatory condition primarily"},{"key": "D","text": "A crystal deposition disease"}],"correct": "B","explanation": "OA is primarily a degenerative process with cartilage breakdown, subchondral bone changes, and osteophyte formation."},{"id": 8707,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteoarthritis morning stiffness typically lasts:","options": [{"key": "A","text": "Less than 30 minutes"},{"key": "B","text": "More than 1 hour"},{"key": "C","text": "All day"},{"key": "D","text": "Several days"}],"correct": "A","explanation": "OA-related stiffness is typically brief (<30 min), unlike the prolonged stiffness of inflammatory arthritis."},{"id": 8708,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which joints are classically spared in rheumatoid arthritis but commonly affected in osteoarthritis?","options": [{"key": "A","text": "Wrist joints"},{"key": "B","text": "PIP joints (though can be involved in OA too)"},{"key": "C","text": "DIP joints"},{"key": "D","text": "MCP joints"}],"correct": "C","explanation": "DIP joints (Heberden's nodes) are classically affected in OA but typically spared in RA."},{"id": 8709,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Gout is caused by deposition of which crystal type in joints?","options": [{"key": "A","text": "Hydroxyapatite crystals"},{"key": "B","text": "Monosodium urate crystals"},{"key": "C","text": "Calcium pyrophosphate crystals"},{"key": "D","text": "Calcium oxalate crystals"}],"correct": "B","explanation": "Gout results from monosodium urate crystal deposition due to hyperuricemia."},{"id": 8710,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pseudogout is caused by deposition of which crystal type?","options": [{"key": "A","text": "Calcium pyrophosphate dihydrate (CPPD) crystals"},{"key": "B","text": "Cholesterol crystals"},{"key": "C","text": "Calcium oxalate crystals"},{"key": "D","text": "Monosodium urate crystals"}],"correct": "A","explanation": "Pseudogout (CPPD disease) results from calcium pyrophosphate dihydrate crystal deposition, often affecting the knee."},{"id": 8711,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Acute gout most classically affects which joint first?","options": [{"key": "A","text": "First metatarsophalangeal joint (podagra)"},{"key": "B","text": "Knee joint"},{"key": "C","text": "Shoulder joint"},{"key": "D","text": "Wrist joint"}],"correct": "A","explanation": "Podagra (acute gouty arthritis of the first MTP joint) is the classic initial presentation of gout."},{"id": 8712,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ankylosing spondylitis is strongly associated with which genetic marker?","options": [{"key": "A","text": "HLA-DQ2"},{"key": "B","text": "HLA-B27"},{"key": "C","text": "HLA-B7"},{"key": "D","text": "HLA-DR4"}],"correct": "B","explanation": "HLA-B27 shows strong association with ankylosing spondylitis and other spondyloarthropathies."},{"id": 8713,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Ankylosing spondylitis classically causes which spinal deformity in advanced disease?","options": [{"key": "A","text": "Progressive kyphosis with 'bamboo spine' fusion"},{"key": "B","text": "Scoliosis primarily"},{"key": "C","text": "Spondylolisthesis"},{"key": "D","text": "Isolated lumbar lordosis increase"}],"correct": "A","explanation": "Advanced AS leads to syndesmophyte formation and vertebral fusion, producing the characteristic 'bamboo spine' appearance with kyphotic posture."},{"id": 8714,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "Psoriatic arthritis characteristically causes which finger deformity due to combined DIP and other joint involvement?","options": [{"key": "A","text": "Swan neck deformity primarily"},{"key": "B","text": "Mallet finger"},{"key": "C","text": "Boutonniere deformity primarily"},{"key": "D","text": "Dactylitis ('sausage digit')"}],"correct": "D","explanation": "Dactylitis (diffuse digit swelling from combined joint and tendon sheath inflammation) is characteristic of psoriatic arthritis."},{"id": 8715,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Reactive arthritis (formerly Reiter's syndrome) classically presents with the triad of:","options": [{"key": "A","text": "Arthritis, conjunctivitis, and urethritis"},{"key": "B","text": "Arthritis, rash, and fever only"},{"key": "C","text": "Back pain, joint swelling, and hearing loss"},{"key": "D","text": "Joint pain, weight loss, and fatigue"}],"correct": "A","explanation": "Classic triad: arthritis, conjunctivitis, and urethritis, typically following a GI or GU infection."},{"id": 8716,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Juvenile idiopathic arthritis (JIA) is diagnosed based on arthritis persisting for at least how long, with onset before what age?","options": [{"key": "A","text": "6 months, before age 18"},{"key": "B","text": "6 weeks, before age 16"},{"key": "C","text": "1 week, before age 10"},{"key": "D","text": "No time criteria needed"}],"correct": "B","explanation": "JIA diagnostic criteria require arthritis onset before age 16, persisting at least 6 weeks, with other causes excluded."},{"id": 8717,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Systemic lupus erythematosus (SLE) commonly causes arthritis with which characteristic feature distinguishing it from RA?","options": [{"key": "A","text": "Only affects large joints"},{"key": "B","text": "Severe erosive joint destruction identical to RA"},{"key": "C","text": "Never affects small joints"},{"key": "D","text": "Typically non-erosive, non-deforming arthritis (Jaccoud's arthropathy in some cases)"}],"correct": "D","explanation": "SLE arthritis is typically non-erosive, though a subset can develop reversible deformities (Jaccoud's arthropathy) without true erosion."},{"id": 8718,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which condition is characterized by widespread musculoskeletal pain, fatigue, and specific tender points, without inflammatory markers?","options": [{"key": "A","text": "Ankylosing spondylitis"},{"key": "B","text": "Polymyalgia rheumatica"},{"key": "C","text": "Rheumatoid arthritis"},{"key": "D","text": "Fibromyalgia"}],"correct": "D","explanation": "Fibromyalgia presents with chronic widespread pain and tenderness without elevated inflammatory markers, distinguishing it from inflammatory arthropathies."},{"id": 8719,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Polymyalgia rheumatica classically presents in which population with which symptom pattern?","options": [{"key": "A","text": "Young adults with peripheral joint pain"},{"key": "B","text": "Children with fever and rash"},{"key": "C","text": "Middle-aged men with isolated knee pain"},{"key": "D","text": "Elderly patients with bilateral shoulder and hip girdle pain/stiffness"}],"correct": "D","explanation": "PMR typically affects patients over 50 with proximal (shoulder/hip girdle) pain and stiffness, often with elevated ESR/CRP."},{"id": 8720,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Polymyalgia rheumatica is closely associated with which vasculitic condition requiring screening?","options": [{"key": "A","text": "Giant cell (temporal) arteritis"},{"key": "B","text": "Kawasaki disease"},{"key": "C","text": "Wegener's granulomatosis"},{"key": "D","text": "Polyarteritis nodosa"}],"correct": "A","explanation": "PMR and giant cell arteritis frequently co-exist; screening for GCA symptoms (headache, visual disturbance, jaw claudication) is essential due to risk of vision loss."},{"id": 8721,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Septic arthritis is a medical emergency most commonly caused by which organism in adults?","options": [{"key": "A","text": "Staphylococcus aureus"},{"key": "B","text": "Neisseria gonorrhoeae exclusively"},{"key": "C","text": "Mycobacterium tuberculosis"},{"key": "D","text": "Streptococcus pneumoniae exclusively"}],"correct": "A","explanation": "Staphylococcus aureus is the most common causative organism in septic arthritis among adults generally."},{"id": 8722,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Septic arthritis typically requires urgent management including:","options": [{"key": "A","text": "Observation without intervention"},{"key": "B","text": "Physiotherapy exercise as first-line treatment"},{"key": "C","text": "Joint aspiration/drainage and antibiotic therapy"},{"key": "D","text": "NSAIDs alone without antibiotics"}],"correct": "C","explanation": "Septic arthritis requires urgent joint drainage/aspiration and appropriate antibiotic therapy to prevent joint destruction."},{"id": 8723,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Physiotherapy in acute septic arthritis (before infection control) should primarily focus on:","options": [{"key": "A","text": "Positioning to prevent deformity/contracture, deferring aggressive mobilization until infection controlled"},{"key": "B","text": "Aggressive joint mobilization immediately"},{"key": "C","text": "Full weight-bearing regardless of infection status"},{"key": "D","text": "High-intensity strengthening"}],"correct": "A","explanation": "Early physiotherapy focuses on positioning/preventing complications, with active rehabilitation progressing once acute infection is controlled."},{"id": 8724,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Rheumatoid arthritis physiotherapy management during an acute flare typically emphasizes:","options": [{"key": "A","text": "Rest of inflamed joints with gentle ROM, avoiding aggressive strengthening"},{"key": "B","text": "High-impact exercise during flare"},{"key": "C","text": "Ignoring joint protection principles"},{"key": "D","text": "Aggressive strengthening during flare"}],"correct": "A","explanation": "During acute flares, gentle ROM and joint protection are prioritized over aggressive strengthening, which resumes once inflammation settles."},{"id": 8725,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Joint protection principles taught to RA patients include:","options": [{"key": "A","text": "Avoiding all activity permanently"},{"key": "B","text": "Using larger joints/stronger muscles for tasks, avoiding sustained grips, and using assistive devices"},{"key": "C","text": "Ignoring biomechanics during ADLs"},{"key": "D","text": "Maximizing repetitive small joint loading"}],"correct": "B","explanation": "Joint protection education teaches techniques to reduce stress on vulnerable joints during daily activities."},{"id": 8726,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which exercise type is generally well-supported for both RA and OA management once acute inflammation is controlled?","options": [{"key": "A","text": "High-impact plyometric training exclusively"},{"key": "B","text": "Complete rest indefinitely"},{"key": "C","text": "Aerobic and resistance exercise combined with ROM exercises"},{"key": "D","text": "Only passive modalities"}],"correct": "C","explanation": "Combined aerobic, resistance, and flexibility exercise programs are evidence-based for both RA and OA management, improving function and reducing pain."},{"id": 8727,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Hydrotherapy (aquatic therapy) is particularly beneficial for arthritis patients because:","options": [{"key": "A","text": "It is contraindicated in all arthritis types"},{"key": "B","text": "Buoyancy reduces joint loading while allowing exercise and improving ROM"},{"key": "C","text": "It has no therapeutic benefit"},{"key": "D","text": "It replaces the need for any land-based exercise"}],"correct": "B","explanation": "Water buoyancy reduces joint compressive forces, allowing arthritic patients to exercise with less pain while improving strength/ROM."},{"id": 8728,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "Which deformity is classically associated with rheumatoid arthritis affecting the wrist and hand?","options": [{"key": "A","text": "Isolated DIP joint deformity"},{"key": "B","text": "Ulnar deviation at MCP joints with radial deviation of the wrist"},{"key": "C","text": "Radial deviation at MCP joints"},{"key": "D","text": "No characteristic deformity pattern exists"}],"correct": "B","explanation": "RA classically causes MCP ulnar deviation combined with radial deviation of the wrist, a characteristic deformity pattern."},{"id": 8729,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Rheumatoid nodules typically occur at which common location?","options": [{"key": "A","text": "Facial skin exclusively"},{"key": "B","text": "Only on soles of feet"},{"key": "C","text": "Only on palms"},{"key": "D","text": "Extensor surfaces such as the olecranon/forearm"}],"correct": "D","explanation": "Rheumatoid nodules classically develop over extensor surfaces subject to pressure, such as the elbow (olecranon area)."},{"id": 8730,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Systemic sclerosis (scleroderma) primarily affects which tissue, with musculoskeletal implications including joint contractures?","options": [{"key": "A","text": "Only cartilage"},{"key": "B","text": "Only bone"},{"key": "C","text": "Only synovial tissue"},{"key": "D","text": "Skin and connective tissue with progressive fibrosis"}],"correct": "D","explanation": "Systemic sclerosis causes progressive skin/connective tissue fibrosis, which can lead to joint contractures and reduced hand function."},{"id": 8731,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Enteropathic arthritis is associated with which underlying condition?","options": [{"key": "A","text": "Chronic kidney disease"},{"key": "B","text": "Diabetes mellitus"},{"key": "C","text": "Inflammatory bowel disease (Crohn's disease, ulcerative colitis)"},{"key": "D","text": "Thyroid disease"}],"correct": "C","explanation": "Enteropathic arthritis occurs in association with inflammatory bowel disease, part of the spondyloarthropathy spectrum."},{"id": 8732,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following best describes 'boutonniere deformity' pathophysiology in RA?","options": [{"key": "A","text": "Volar plate rupture at MCP"},{"key": "B","text": "Radial collateral ligament rupture"},{"key": "C","text": "Terminal extensor tendon rupture at DIP"},{"key": "D","text": "Central slip attenuation/rupture allowing lateral band displacement volarly"}],"correct": "D","explanation": "Chronic synovitis weakens the central slip, allowing lateral bands to slip volarly, producing PIP flexion with DIP hyperextension."},{"id": 8733,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Total joint replacement (e.g., hip, knee) is considered in advanced arthritis primarily when:","options": [{"key": "A","text": "Never appropriate for inflammatory arthritis"},{"key": "B","text": "Significant pain and functional limitation persist despite optimal conservative management"},{"key": "C","text": "Immediately at diagnosis regardless of symptom severity"},{"key": "D","text": "Only in RA, never in OA"}],"correct": "B","explanation": "Joint replacement is generally reserved for advanced disease with significant impact on pain/function despite conservative management trial."},{"id": 8734,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Disease-modifying antirheumatic drugs (DMARDs) in RA management aim to:","options": [{"key": "A","text": "Cure RA completely in all patients"},{"key": "B","text": "Replace the need for any physiotherapy"},{"key": "C","text": "Slow disease progression and prevent joint damage, not just symptomatic relief"},{"key": "D","text": "Only provide symptomatic pain relief like NSAIDs"}],"correct": "C","explanation": "DMARDs (e.g., methotrexate) target the underlying disease process to slow progression and prevent structural joint damage, distinct from symptomatic NSAIDs."},{"id": 8735,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Biologic agents used in RA treatment often target which inflammatory mediator?","options": [{"key": "A","text": "Tumor necrosis factor (TNF-alpha)"},{"key": "B","text": "Collagen synthesis directly"},{"key": "C","text": "Calcium pyrophosphate directly"},{"key": "D","text": "Uric acid directly"}],"correct": "A","explanation": "Many biologic DMARDs target TNF-alpha or other inflammatory cytokines/pathways involved in RA pathogenesis."},{"id": 8736,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Erosive changes on X-ray are a hallmark finding in which type of arthritis rather than osteoarthritis?","options": [{"key": "A","text": "Mechanical low back pain"},{"key": "B","text": "Osteoarthritis primarily"},{"key": "C","text": "Rheumatoid arthritis (inflammatory erosive arthropathy)"},{"key": "D","text": "Fibromyalgia"}],"correct": "C","explanation": "Marginal bony erosions are characteristic radiographic findings in RA, reflecting synovial inflammation-mediated bone destruction, distinct from OA's osteophyte/joint space narrowing pattern."},{"id": 8737,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteophyte formation is a characteristic radiographic feature of:","options": [{"key": "A","text": "Rheumatoid arthritis primarily"},{"key": "B","text": "Osteoarthritis"},{"key": "C","text": "Septic arthritis"},{"key": "D","text": "Gout exclusively"}],"correct": "B","explanation": "Osteophytes (bony spurs) form as part of the degenerative/reparative process in OA, distinguishing it radiographically from inflammatory arthropathies."},{"id": 8738,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Tophi (subcutaneous urate deposits) are characteristic findings in advanced/chronic:","options": [{"key": "A","text": "Gout"},{"key": "B","text": "Psoriatic arthritis exclusively"},{"key": "C","text": "Rheumatoid arthritis"},{"key": "D","text": "Osteoarthritis"}],"correct": "A","explanation": "Tophi represent chronic urate crystal deposition in soft tissue, a hallmark of long-standing untreated gout."},{"id": 8739,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which dietary/lifestyle factor is commonly associated with increased risk of gout flares?","options": [{"key": "A","text": "Regular moderate exercise"},{"key": "B","text": "High fiber diet"},{"key": "C","text": "High purine intake (red meat, alcohol, seafood) and obesity"},{"key": "D","text": "Adequate hydration"}],"correct": "C","explanation": "High purine foods, alcohol (especially beer), and obesity increase uric acid production/reduce excretion, precipitating gout flares."},{"id": 8740,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Acute gout attack management typically includes:","options": [{"key": "A","text": "Surgery as first-line treatment"},{"key": "B","text": "NSAIDs, colchicine, or corticosteroids for acute inflammation control"},{"key": "C","text": "Immediate uric acid-lowering therapy initiation during the acute attack"},{"key": "D","text": "Joint immobilization for months"}],"correct": "B","explanation": "Acute gout flares are managed with anti-inflammatory medications; urate-lowering therapy is typically started/adjusted once the acute attack has resolved."},{"id": 8741,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following joint patterns is classically seen in psoriatic arthritis, distinguishing it from RA?","options": [{"key": "A","text": "Only axial spine involvement"},{"key": "B","text": "Only large joint involvement"},{"key": "C","text": "Symmetric small joint involvement sparing DIP joints only"},{"key": "D","text": "DIP joint involvement along with asymmetric oligoarthritis pattern"}],"correct": "D","explanation": "Psoriatic arthritis characteristically involves DIP joints (unlike RA) and can present with asymmetric oligoarticular patterns, along with dactylitis and nail changes."},{"id": 8742,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Enthesitis (inflammation at tendon/ligament bone insertion sites) is a hallmark feature of which group of arthropathies?","options": [{"key": "A","text": "Rheumatoid arthritis primarily"},{"key": "B","text": "Osteoarthritis"},{"key": "C","text": "Fibromyalgia"},{"key": "D","text": "Spondyloarthropathies (AS, psoriatic arthritis, reactive arthritis)"}],"correct": "D","explanation": "Enthesitis is a characteristic feature distinguishing spondyloarthropathies from RA, commonly at sites like the Achilles insertion and plantar fascia."},{"id": 8743,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which imaging modality is particularly useful for detecting early sacroiliitis in suspected ankylosing spondylitis, before changes appear on plain X-ray?","options": [{"key": "A","text": "Bone scan alone"},{"key": "B","text": "Ultrasound"},{"key": "C","text": "MRI"},{"key": "D","text": "Plain X-ray alone"}],"correct": "C","explanation": "MRI can detect early inflammatory sacroiliitis (bone marrow edema) before structural changes are visible on conventional radiographs."},{"id": 8744,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Exercise therapy for ankylosing spondylitis particularly emphasizes:","options": [{"key": "A","text": "Avoiding all physical activity"},{"key": "B","text": "Spinal extension exercises, deep breathing, and postural maintenance to counter kyphotic progression"},{"key": "C","text": "Isolated peripheral joint strengthening only"},{"key": "D","text": "Only flexion-based exercises"}],"correct": "B","explanation": "AS management emphasizes maintaining spinal extension/posture and chest expansion to counteract the tendency toward kyphotic deformity and reduced chest mobility."},{"id": 8745,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following best describes 'flare management' education for inflammatory arthritis patients?","options": [{"key": "A","text": "Avoiding all medical follow-up"},{"key": "B","text": "Recognizing early flare signs, appropriate rest/activity modification, and timely medical consultation"},{"key": "C","text": "Continuing maximal exercise intensity regardless of flare"},{"key": "D","text": "Ignoring symptoms until severe"}],"correct": "B","explanation": "Flare management education helps patients recognize and appropriately respond to disease flares, balancing rest and activity while seeking timely medical input."},{"id": 8746,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Rheumatoid arthritis extra-articular manifestations can include which of the following?","options": [{"key": "A","text": "Rheumatoid nodules, interstitial lung disease, and vasculitis"},{"key": "B","text": "Only ocular symptoms"},{"key": "C","text": "Only joint symptoms, no systemic involvement"},{"key": "D","text": "Isolated skin rash without organ involvement"}],"correct": "A","explanation": "RA is a systemic disease with potential extra-articular manifestations affecting lungs, skin, blood vessels, and other organ systems."},{"id": 8747,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Felty's syndrome is a rare complication of which condition, characterized by the triad of arthritis, splenomegaly, and neutropenia?","options": [{"key": "A","text": "Rheumatoid arthritis"},{"key": "B","text": "Osteoarthritis"},{"key": "C","text": "Gout"},{"key": "D","text": "Ankylosing spondylitis"}],"correct": "A","explanation": "Felty's syndrome is a rare complication of longstanding seropositive RA, presenting with splenomegaly and neutropenia alongside arthritis."},{"id": 8748,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which physical examination finding helps distinguish inflammatory synovitis from simple bony osteoarthritic joint enlargement?","options": [{"key": "A","text": "Soft, boggy swelling with warmth (synovitis) vs hard, bony enlargement (OA)"},{"key": "B","text": "Only X-ray can differentiate, never clinical exam"},{"key": "C","text": "No palpable difference exists"},{"key": "D","text": "Both present identically on palpation"}],"correct": "A","explanation": "Inflammatory synovitis typically presents with soft, warm, boggy swelling, while OA shows firm, bony joint enlargement (osteophytes)."},{"id": 8749,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which of the following best supports the use of a multidisciplinary team approach in managing inflammatory arthritis?","options": [{"key": "A","text": "Combines rheumatologist, physiotherapist, occupational therapist, and other specialists to address disease and functional/psychosocial impact"},{"key": "B","text": "Physiotherapy alone is sufficient for all cases"},{"key": "C","text": "Only medication management is required"},{"key": "D","text": "Multidisciplinary care has no evidence benefit"}],"correct": "A","explanation": "Comprehensive inflammatory arthritis management benefits from a multidisciplinary approach addressing medical, physical, occupational, and psychosocial aspects of the disease."},{"id": 8750,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Medium","question": "Splinting in RA hand management is used to:","options": [{"key": "A","text": "Permanently immobilize joints to prevent any movement"},{"key": "B","text": "Replace exercise therapy entirely"},{"key": "C","text": "Only for cosmetic purposes"},{"key": "D","text": "Support joints, reduce pain/inflammation, and prevent/correct deformity progression"}],"correct": "D","explanation": "Resting or functional splints in RA aim to reduce joint stress/pain and help manage or prevent progression of deformity, used alongside (not instead of) exercise therapy."},{"id": 8751,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which of the following exercise precautions is important in ankylosing spondylitis with significant spinal fusion?","options": [{"key": "A","text": "Avoiding high-risk activities/manipulation due to increased fracture risk from a rigid, brittle fused spine"},{"key": "B","text": "No precautions are necessary regardless of fusion extent"},{"key": "C","text": "Avoiding all exercise entirely"},{"key": "D","text": "Only avoiding upper limb exercise"}],"correct": "A","explanation": "A fused, osteoporotic AS spine has increased fracture risk even from relatively minor trauma; high-risk manipulative techniques and certain activities require caution."},{"id": 8752,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteoarthritis risk factors include which of the following?","options": [{"key": "A","text": "Absence of any joint loading history"},{"key": "B","text": "Obesity, prior joint injury, and advancing age"},{"key": "C","text": "Young age exclusively"},{"key": "D","text": "Regular low-impact exercise"}],"correct": "B","explanation": "Obesity, previous joint trauma, and increasing age are well-established risk factors for OA development."},{"id": 8753,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Weight loss in overweight/obese patients with knee osteoarthritis is associated with:","options": [{"key": "A","text": "Worsening of joint symptoms"},{"key": "B","text": "No effect on knee OA symptoms"},{"key": "C","text": "Only benefits cardiovascular health, no joint benefit"},{"key": "D","text": "Significant reduction in joint loading and improved symptoms"}],"correct": "D","explanation": "Weight loss substantially reduces knee joint loading forces and is associated with meaningful symptomatic improvement in knee OA."},{"id": 8754,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Reactive arthritis is typically triggered by infection with which type of organisms?","options": [{"key": "A","text": "Parasitic infections exclusively"},{"key": "B","text": "Respiratory viruses exclusively"},{"key": "C","text": "Genitourinary (e.g., Chlamydia) or gastrointestinal (e.g., Salmonella, Shigella) pathogens"},{"key": "D","text": "Fungal skin infections"}],"correct": "C","explanation": "Reactive arthritis classically follows GU (Chlamydia) or GI (Salmonella, Shigella, Campylobacter) infections, presenting weeks after the triggering infection."},{"id": 8755,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which is a key differentiating clinical feature between inflammatory and mechanical joint pain regarding activity response?","options": [{"key": "A","text": "No relationship between pain type and activity response exists"},{"key": "B","text": "Inflammatory pain improves with activity/movement; mechanical pain worsens with activity"},{"key": "C","text": "Both worsen equally with activity"},{"key": "D","text": "Inflammatory pain always worsens with activity"}],"correct": "B","explanation": "Inflammatory conditions typically show improvement with movement/activity (and worse with rest), the opposite pattern to typical mechanical/degenerative joint pain."},{"id": 8756,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteoporosis is defined as a condition characterized by:","options": [{"key": "A","text": "Excessive bone formation"},{"key": "B","text": "Increased bone density"},{"key": "C","text": "Defective mineralization of normal bone matrix"},{"key": "D","text": "Reduced bone mass with preserved mineral-to-matrix ratio, increasing fracture risk"}],"correct": "D","explanation": "Osteoporosis involves quantitative bone loss (reduced mass/density) with normal mineralization, unlike osteomalacia's mineralization defect."},{"id": 8757,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteoporosis is diagnosed based on which T-score threshold on DEXA scan?","options": [{"key": "A","text": "T-score above +1.0"},{"key": "B","text": "T-score of -2.5 or below"},{"key": "C","text": "T-score of 0 or below"},{"key": "D","text": "T-score of -1.0 or below"}],"correct": "B","explanation": "WHO criteria define osteoporosis as a T-score of -2.5 SD or below at the hip or spine."},{"id": 8758,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Osteopenia is defined by which T-score range?","options": [{"key": "A","text": "Above 0"},{"key": "B","text": "Between +1.0 and +2.5"},{"key": "C","text": "Below -2.5"},{"key": "D","text": "Between -1.0 and -2.5"}],"correct": "D","explanation": "Osteopenia represents low bone mass with T-score between -1.0 and -2.5, a precursor stage to osteoporosis."},{"id": 8759,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which type of osteoporosis is most associated with postmenopausal estrogen deficiency?","options": [{"key": "A","text": "Type II (senile) osteoporosis"},{"key": "B","text": "Type I (postmenopausal) osteoporosis"},{"key": "C","text": "Secondary osteoporosis from steroid use"},{"key": "D","text": "Osteomalacia"}],"correct": "B","explanation": "Type I postmenopausal osteoporosis results from estrogen deficiency, predominantly affecting trabecular bone (vertebrae, distal radius)."},{"id": 8760,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteomalacia results primarily from:","options": [{"key": "A","text": "Excessive calcium intake"},{"key": "B","text": "Vitamin D deficiency causing defective bone mineralization"},{"key": "C","text": "Estrogen deficiency"},{"key": "D","text": "Primary hyperparathyroidism only"}],"correct": "B","explanation": "Osteomalacia results from inadequate mineralization of osteoid, most commonly due to vitamin D deficiency."},{"id": 8761,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Rickets is the pediatric equivalent of which adult metabolic bone disease?","options": [{"key": "A","text": "Paget's disease"},{"key": "B","text": "Osteomalacia"},{"key": "C","text": "Osteoporosis"},{"key": "D","text": "Osteopetrosis"}],"correct": "B","explanation": "Rickets represents impaired mineralization of growing bone/growth plates in children, analogous to osteomalacia in adults."},{"id": 8762,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Classic skeletal deformities seen in rickets include:","options": [{"key": "A","text": "Bowing of long bones (genu varum) and widened growth plates"},{"key": "B","text": "Vertebral compression fractures primarily"},{"key": "C","text": "Bamboo spine"},{"key": "D","text": "Bone density increase"}],"correct": "A","explanation": "Rickets classically causes bowleg deformity and rachitic rosary (costochondral widening) due to defective growth plate mineralization."},{"id": 8763,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Paget's disease of bone is characterized by:","options": [{"key": "A","text": "Simple reduction in bone density"},{"key": "B","text": "Complete mineralization defect only"},{"key": "C","text": "Abnormal, disorganized bone remodeling with excessive osteoclastic and osteoblastic activity"},{"key": "D","text": "Autoimmune joint destruction"}],"correct": "C","explanation": "Paget's disease shows chaotic bone turnover with initial excessive resorption followed by disorganized new bone formation, resulting in enlarged, weakened bone."},{"id": 8764,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Paget's disease most commonly affects which bones?","options": [{"key": "A","text": "Only ribs"},{"key": "B","text": "Only vertebrae"},{"key": "C","text": "Pelvis, spine, skull, and long bones (femur, tibia)"},{"key": "D","text": "Only small hand bones"}],"correct": "C","explanation": "Paget's disease has predilection for pelvis, spine, skull, and femur/tibia, though can affect any bone."},{"id": 8765,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which biochemical marker is characteristically elevated in Paget's disease reflecting increased bone turnover?","options": [{"key": "A","text": "Alkaline phosphatase"},{"key": "B","text": "Serum calcium (usually normal in uncomplicated Paget's)"},{"key": "C","text": "Uric acid"},{"key": "D","text": "Rheumatoid factor"}],"correct": "A","explanation": "Elevated serum alkaline phosphatase reflects the markedly increased bone turnover characteristic of Paget's disease."},{"id": 8766,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Hyperparathyroidism can lead to which bone-related pathology due to excessive PTH-mediated bone resorption?","options": [{"key": "A","text": "Osteitis fibrosa cystica"},{"key": "B","text": "Osteogenesis imperfecta"},{"key": "C","text": "Osteopetrosis"},{"key": "D","text": "Achondroplasia"}],"correct": "A","explanation": "Chronic excess PTH causes osteitis fibrosa cystica, characterized by subperiosteal bone resorption and cystic changes."},{"id": 8767,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteogenesis imperfecta is a genetic disorder primarily affecting:","options": [{"key": "A","text": "Type I collagen synthesis, causing bone fragility"},{"key": "B","text": "Calcium absorption"},{"key": "C","text": "Parathyroid hormone production"},{"key": "D","text": "Vitamin D metabolism"}],"correct": "A","explanation": "OI results from mutations affecting type I collagen, leading to fragile bones prone to fracture, along with other connective tissue manifestations."},{"id": 8768,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which fracture pattern is highly suggestive of osteogenesis imperfecta in a child, requiring careful differentiation from non-accidental injury?","options": [{"key": "A","text": "Single traumatic fracture only"},{"key": "B","text": "Only affects adults"},{"key": "C","text": "No distinguishing features exist"},{"key": "D","text": "Multiple fractures with minimal trauma, blue sclera, and family history"}],"correct": "D","explanation": "Recurrent low-energy fractures with associated features (blue sclera, family history, dentinogenesis imperfecta) suggest OI, though must be differentiated from abuse."},{"id": 8769,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Osteopetrosis is characterized by:","options": [{"key": "A","text": "Mineralization defect only"},{"key": "B","text": "Excessive bone resorption"},{"key": "C","text": "Decreased bone density"},{"key": "D","text": "Increased, abnormally dense but brittle bone due to defective osteoclast function"}],"correct": "D","explanation": "Osteopetrosis results from defective osteoclastic bone resorption, causing abnormally dense but structurally weak/brittle bone."},{"id": 8770,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Renal osteodystrophy refers to bone changes secondary to:","options": [{"key": "A","text": "Primary bone tumor"},{"key": "B","text": "Direct trauma"},{"key": "C","text": "Autoimmune arthritis"},{"key": "D","text": "Chronic kidney disease affecting calcium/phosphate/vitamin D metabolism"}],"correct": "D","explanation": "Renal osteodystrophy encompasses the spectrum of bone disease resulting from CKD-related mineral and PTH metabolism disturbances."},{"id": 8771,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Weight-bearing exercise is recommended in osteoporosis management primarily to:","options": [{"key": "A","text": "Only improve cardiovascular fitness, not bone health"},{"key": "B","text": "Reduce bone density intentionally"},{"key": "C","text": "Stimulate bone formation and help maintain/improve bone mineral density"},{"key": "D","text": "Have no effect on bone health"}],"correct": "C","explanation": "Weight-bearing and resistance exercise provide mechanical loading stimulus that helps maintain or improve bone density per Wolff's law."},{"id": 8772,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Fall prevention strategies are a critical component of osteoporosis management primarily to reduce risk of:","options": [{"key": "A","text": "Improving bone density directly"},{"key": "B","text": "Reducing muscle mass"},{"key": "C","text": "Increasing joint mobility only"},{"key": "D","text": "Fragility fractures, especially hip and vertebral fractures"}],"correct": "D","explanation": "Given fragile bone in osteoporosis, preventing falls directly reduces the risk of serious fragility fractures."},{"id": 8773,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which exercise type should generally be approached cautiously or modified in patients with significant osteoporosis due to fracture risk?","options": [{"key": "A","text": "High-impact activities and excessive spinal flexion with loading"},{"key": "B","text": "Balance training"},{"key": "C","text": "Weight-bearing walking"},{"key": "D","text": "Resistance training with appropriate progression"}],"correct": "A","explanation": "High-impact loading and excessive spinal flexion (especially with added load) increase vertebral fracture risk in osteoporotic patients and are typically modified/avoided."},{"id": 8774,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Vitamin D and calcium supplementation in osteoporosis management serves to:","options": [{"key": "A","text": "Support bone mineralization and reduce fracture risk as an adjunct to other therapies"},{"key": "B","text": "Have no role in bone health management"},{"key": "C","text": "Replace the need for exercise entirely"},{"key": "D","text": "Cure osteoporosis independently without other interventions"}],"correct": "A","explanation": "Adequate calcium/vitamin D supports bone mineralization and is a foundational adjunct alongside exercise and pharmacological therapy in osteoporosis management."},{"id": 8775,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "FRAX tool is used clinically to:","options": [{"key": "A","text": "Diagnose osteomalacia specifically"},{"key": "B","text": "Estimate 10-year fracture risk based on clinical risk factors and bone density"},{"key": "C","text": "Measure muscle strength"},{"key": "D","text": "Assess joint inflammation"}],"correct": "B","explanation": "FRAX (Fracture Risk Assessment Tool) estimates individual 10-year probability of major osteoporotic fracture using clinical risk factors with or without BMD."},{"id": 8776,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteosarcoma most commonly affects which age group and location?","options": [{"key": "A","text": "Middle-aged adults, in the pelvis exclusively"},{"key": "B","text": "Infants, in the skull"},{"key": "C","text": "Adolescents, around the knee (distal femur/proximal tibia)"},{"key": "D","text": "Elderly, in the spine"}],"correct": "C","explanation": "Osteosarcoma classically affects adolescents/young adults, with a predilection for the metaphyseal region around the knee."},{"id": 8777,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteosarcoma classically shows which radiographic pattern?","options": [{"key": "A","text": "Ground-glass appearance"},{"key": "B","text": "Punched-out lytic lesions only"},{"key": "C","text": "Onion-skin periosteal reaction"},{"key": "D","text": "'Sunburst' periosteal reaction with Codman's triangle"}],"correct": "D","explanation": "Sunburst appearance and Codman's triangle (periosteal elevation) are classic radiographic features of osteosarcoma."},{"id": 8778,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Ewing's sarcoma classically presents with which periosteal reaction pattern on X-ray?","options": [{"key": "A","text": "Sunburst pattern"},{"key": "B","text": "'Onion-skin' layered periosteal reaction"},{"key": "C","text": "Ground-glass appearance"},{"key": "D","text": "No periosteal reaction"}],"correct": "B","explanation": "Ewing's sarcoma classically shows onion-skin (laminated) periosteal reaction, though this can overlap with other lesions."},{"id": 8779,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Ewing's sarcoma most commonly affects which age group?","options": [{"key": "A","text": "Infants under 1 year"},{"key": "B","text": "Middle-aged adults primarily"},{"key": "C","text": "Elderly patients"},{"key": "D","text": "Children and adolescents"}],"correct": "D","explanation": "Ewing's sarcoma is predominantly a pediatric/adolescent malignant bone tumor."},{"id": 8780,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Chondrosarcoma most commonly affects which age group compared to osteosarcoma?","options": [{"key": "A","text": "Older adults (40-60 years)"},{"key": "B","text": "Adolescents exclusively, same as osteosarcoma"},{"key": "C","text": "Children exclusively"},{"key": "D","text": "Infants"}],"correct": "A","explanation": "Chondrosarcoma typically presents in an older age group than osteosarcoma, often arising from cartilage-forming tissue."},{"id": 8781,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which is the most common site for skeletal metastasis in adults?","options": [{"key": "A","text": "Skull exclusively"},{"key": "B","text": "Axial skeleton (spine, pelvis, ribs) and proximal long bones"},{"key": "C","text": "Distal phalanges exclusively"},{"key": "D","text": "Hands and feet"}],"correct": "B","explanation": "Metastatic bone disease most commonly involves the axial skeleton and proximal long bones, reflecting red marrow distribution."},{"id": 8782,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which primary cancers most commonly metastasize to bone?","options": [{"key": "A","text": "Skin cancer exclusively"},{"key": "B","text": "Testicular cancer exclusively"},{"key": "C","text": "Brain tumors exclusively"},{"key": "D","text": "Breast, prostate, lung, kidney, and thyroid"}],"correct": "D","explanation": "Breast, prostate, lung, kidney, and thyroid cancers account for the majority of bone metastases (commonly remembered mnemonics include these primaries)."},{"id": 8783,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Osteoid osteoma classically presents with which characteristic symptom pattern?","options": [{"key": "A","text": "Pain only with weight bearing"},{"key": "B","text": "Pain worse with rest, unrelieved by any medication"},{"key": "C","text": "Night pain relieved dramatically by NSAIDs"},{"key": "D","text": "No pain, incidental finding only"}],"correct": "C","explanation": "Osteoid osteoma classically causes night pain that is characteristically relieved by NSAIDs (due to prostaglandin-mediated pain mechanism)."},{"id": 8784,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Giant cell tumor of bone typically occurs in which location and age group?","options": [{"key": "A","text": "Skull in infants"},{"key": "B","text": "Epiphyseal region of long bones in skeletally mature young adults (20-40 years)"},{"key": "C","text": "Vertebral body in elderly exclusively"},{"key": "D","text": "Diaphysis in children"}],"correct": "B","explanation": "Giant cell tumor characteristically occurs in the epiphyseal-metaphyseal region of long bones in skeletally mature young adults."},{"id": 8785,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Multiple myeloma classically presents with which radiographic finding?","options": [{"key": "A","text": "Sunburst periosteal reaction"},{"key": "B","text": "Increased bone density throughout"},{"key": "C","text": "Onion-skin periosteal reaction"},{"key": "D","text": "Multiple 'punched-out' lytic lesions, especially in skull and axial skeleton"}],"correct": "D","explanation": "Multiple myeloma classically shows multiple well-defined punched-out lytic lesions, particularly affecting the skull and axial skeleton."},{"id": 8786,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osteomyelitis in children most commonly affects which region of long bones due to vascular anatomy?","options": [{"key": "A","text": "Metaphysis (rich vascular supply with sluggish blood flow)"},{"key": "B","text": "Articular cartilage exclusively"},{"key": "C","text": "Epiphysis exclusively"},{"key": "D","text": "Diaphysis exclusively"}],"correct": "A","explanation": "The metaphyseal region's vascular anatomy (sluggish flow in looping vessels) predisposes to bacterial seeding and osteomyelitis in children."},{"id": 8787,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Acute hematogenous osteomyelitis is most commonly caused by which organism?","options": [{"key": "A","text": "Salmonella species exclusively"},{"key": "B","text": "Mycobacterium tuberculosis"},{"key": "C","text": "Staphylococcus aureus"},{"key": "D","text": "Streptococcus pyogenes exclusively"}],"correct": "C","explanation": "Staphylococcus aureus is the most common causative organism in acute osteomyelitis across most populations."},{"id": 8788,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Chronic osteomyelitis is characterized radiographically by the presence of a 'sequestrum,' which refers to:","options": [{"key": "A","text": "A segment of dead, necrotic bone separated from living bone"},{"key": "B","text": "Periosteal elevation only"},{"key": "C","text": "Soft tissue abscess only"},{"key": "D","text": "New reactive bone formation surrounding infection"}],"correct": "A","explanation": "Sequestrum is necrotic bone that has separated from viable bone, a hallmark feature of chronic osteomyelitis."},{"id": 8789,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "An 'involucrum' in chronic osteomyelitis refers to:","options": [{"key": "A","text": "New bone formation surrounding a sequestrum, from elevated periosteum"},{"key": "B","text": "Sinus tract formation"},{"key": "C","text": "Necrotic bone fragment"},{"key": "D","text": "Soft tissue swelling only"}],"correct": "A","explanation": "Involucrum is the sheath of new bone that forms around the necrotic sequestrum as the periosteum reacts to infection."},{"id": 8790,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Tuberculous (Pott's) spine disease classically affects which spinal structures first?","options": [{"key": "A","text": "Only the facet joints"},{"key": "B","text": "Anterior vertebral body, often with disc space involvement and adjacent vertebral collapse"},{"key": "C","text": "Only the spinous processes"},{"key": "D","text": "Posterior elements exclusively"}],"correct": "B","explanation": "Spinal TB (Pott's disease) typically begins in the anterior vertebral body, often spreading to the adjacent disc and causing vertebral collapse/kyphotic deformity (gibbus)."},{"id": 8791,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Gibbus deformity' is a classic complication seen in advanced:","options": [{"key": "A","text": "Tuberculous spondylitis (Pott's disease)"},{"key": "B","text": "Osteoporotic compression fracture only"},{"key": "C","text": "Rheumatoid arthritis"},{"key": "D","text": "Ankylosing spondylitis exclusively"}],"correct": "A","explanation": "Gibbus (sharp angular kyphotic deformity) classically results from vertebral body destruction and collapse in spinal tuberculosis."},{"id": 8792,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Septic arthritis in a native joint requires urgent management primarily to prevent:","options": [{"key": "A","text": "Rapid cartilage destruction and joint damage from bacterial enzymes/inflammatory response"},{"key": "B","text": "Muscle weakness only"},{"key": "C","text": "Ligament laxity"},{"key": "D","text": "Osteoporosis"}],"correct": "A","explanation": "Bacterial and inflammatory enzymes rapidly degrade articular cartilage, making urgent drainage and antibiotic treatment essential to preserve joint function."},{"id": 8793,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Physiotherapy management following resolution of acute osteomyelitis/septic arthritis infection typically focuses on:","options": [{"key": "A","text": "Restoring ROM, strength, and function progressively once infection is controlled"},{"key": "B","text": "Immediate aggressive loading during active infection"},{"key": "C","text": "Permanent immobilization"},{"key": "D","text": "No role for physiotherapy in this condition"}],"correct": "A","explanation": "Once infection is medically controlled, physiotherapy plays a key role in restoring joint ROM, strength, and functional capacity."},{"id": 8794,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Benign bone tumors are generally differentiated from malignant tumors radiographically by which feature?","options": [{"key": "A","text": "Only biopsy can ever differentiate, imaging is irrelevant"},{"key": "B","text": "Well-defined margins with a narrow zone of transition, versus ill-defined margins with wide transition zone in malignant lesions"},{"key": "C","text": "Both always have identical margins"},{"key": "D","text": "Malignant tumors always show sclerotic well-defined borders"}],"correct": "B","explanation": "Benign lesions typically show sharp, well-defined margins (narrow transition zone); malignant lesions often show ill-defined, permeative margins (wide transition zone), aiding radiographic differentiation."},{"id": 8795,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which red flag combination in a patient with bone pain should prompt urgent investigation for possible malignancy?","options": [{"key": "A","text": "Pain only with specific movements, resolving with physiotherapy"},{"key": "B","text": "Unremitting night pain, unexplained weight loss, and progressive swelling"},{"key": "C","text": "Pain that improves with rest and NSAIDs"},{"key": "D","text": "Mild intermittent pain without other symptoms"}],"correct": "B","explanation": "Constant/night pain unrelieved by rest, systemic symptoms (weight loss), and progressive local swelling are red flags warranting urgent oncological investigation."},{"id": 8796,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Congenital Talipes Equinovarus (CTEV/clubfoot) is characterized by which combination of deformities?","options": [{"key": "A","text": "Equinus, varus, adduction, and cavus"},{"key": "B","text": "Only equinus"},{"key": "C","text": "Only varus"},{"key": "D","text": "Valgus and abduction"}],"correct": "A","explanation": "CTEV involves a combination of hindfoot equinus and varus, forefoot adduction, and midfoot cavus."},{"id": 8797,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ponseti method for clubfoot treatment primarily involves:","options": [{"key": "A","text": "Only bracing without casting"},{"key": "B","text": "Only physiotherapy stretching without casting"},{"key": "C","text": "Serial gentle manipulation and casting followed by bracing"},{"key": "D","text": "Immediate surgical correction always"}],"correct": "C","explanation": "Ponseti method uses sequential gentle manipulation/casting to correct deformity, typically followed by tenotomy if needed and maintenance bracing."},{"id": 8798,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Developmental Dysplasia of the Hip (DDH) risk factors include:","options": [{"key": "A","text": "Breech presentation, female gender, and firstborn status"},{"key": "B","text": "No known risk factors identified"},{"key": "C","text": "Male gender predominantly"},{"key": "D","text": "Multiple prior pregnancies protecting against DDH"}],"correct": "A","explanation": "Breech presentation, female sex, family history, and firstborn status are recognized DDH risk factors."},{"id": 8799,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Which clinical test is used to screen for hip instability in a newborn (DDH screening)?","options": [{"key": "A","text": "FABER test"},{"key": "B","text": "Barlow and Ortolani tests"},{"key": "C","text": "Trendelenburg test"},{"key": "D","text": "Thomas test"}],"correct": "B","explanation": "Barlow (provocative, dislocating a reducible hip) and Ortolani (reducing a dislocated hip) tests are standard newborn DDH screening maneuvers."},{"id": 8800,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Ortolani test is positive when:","options": [{"key": "A","text": "Hip abducts fully without any sensation"},{"key": "B","text": "A palpable 'clunk' is felt as a dislocated hip reduces into the acetabulum with abduction"},{"key": "C","text": "No movement is detected"},{"key": "D","text": "Only pain is elicited without movement"}],"correct": "B","explanation": "Ortolani test reduces a dislocated hip back into the socket, producing a palpable clunk, indicating positive DDH finding."},{"id": 8801,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pavlik harness is commonly used in management of:","options": [{"key": "A","text": "Developmental Dysplasia of the Hip in infants"},{"key": "B","text": "Clubfoot"},{"key": "C","text": "Genu valgum"},{"key": "D","text": "Scoliosis"}],"correct": "A","explanation": "Pavlik harness maintains hip flexion and abduction, promoting proper acetabular development in infants with DDH."},{"id": 8802,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Legg-Calve-Perthes disease involves which pathological process?","options": [{"key": "A","text": "Bacterial infection of the hip joint"},{"key": "B","text": "Congenital hip dislocation"},{"key": "C","text": "Traumatic hip fracture"},{"key": "D","text": "Idiopathic avascular necrosis of the femoral head epiphysis"}],"correct": "D","explanation": "Perthes disease is idiopathic AVN of the proximal femoral epiphysis in children, with subsequent revascularization and remodeling phases."},{"id": 8803,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Perthes disease most commonly presents in which age group and gender?","options": [{"key": "A","text": "Infants under 1 year"},{"key": "B","text": "Girls aged 4-10 years"},{"key": "C","text": "Adolescents of both genders equally"},{"key": "D","text": "Boys aged 4-10 years"}],"correct": "D","explanation": "Perthes disease shows male predominance, typically presenting between ages 4-10 years."},{"id": 8804,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Easy","question": "Slipped Capital Femoral Epiphysis (SCFE) involves displacement of the femoral epiphysis in which direction relative to the femoral neck?","options": [{"key": "A","text": "Anterosuperior displacement"},{"key": "B","text": "No displacement, only widening of physis"},{"key": "C","text": "Lateral displacement"},{"key": "D","text": "Posteroinferior displacement"}],"correct": "D","explanation": "SCFE classically involves posteroinferior slippage of the capital femoral epiphysis relative to the femoral neck/metaphysis."},{"id": 8805,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which classic clinical sign is seen in SCFE regarding hip movement?","options": [{"key": "A","text": "No movement abnormality present"},{"key": "B","text": "Obligatory internal rotation with flexion"},{"key": "C","text": "Obligatory external rotation of the hip with flexion"},{"key": "D","text": "Full internal rotation preserved"}],"correct": "C","explanation": "As the hip is flexed in SCFE, it obligately externally rotates due to the altered epiphyseal position, a classic clinical finding."},{"id": 8806,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Blount's disease refers to:","options": [{"key": "A","text": "Lateral bowing of the femur"},{"key": "B","text": "Clubfoot variant"},{"key": "C","text": "Pathological bowing of the tibia due to abnormal medial proximal tibial growth plate"},{"key": "D","text": "Congenital hip dysplasia"}],"correct": "C","explanation": "Blount's disease involves abnormal growth at the medial proximal tibial physis, causing progressive genu varum (bowing)."},{"id": 8807,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Physiological bow-leg (genu varum) in toddlers typically:","options": [{"key": "A","text": "Persists lifelong without treatment"},{"key": "B","text": "Indicates Blount's disease in all cases"},{"key": "C","text": "Resolves spontaneously by around 2-3 years of age as normal development progresses"},{"key": "D","text": "Requires immediate surgical correction"}],"correct": "C","explanation": "Mild physiological genu varum in toddlers is a normal developmental variant that typically self-corrects by 2-3 years."},{"id": 8808,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Physiological knock-knee (genu valgum) in children typically peaks around which age before resolving?","options": [{"key": "A","text": "10 years, persisting into adulthood"},{"key": "B","text": "3-4 years, resolving by around 7-8 years"},{"key": "C","text": "Birth, resolving by 1 year"},{"key": "D","text": "Adolescence, never resolving"}],"correct": "B","explanation": "Physiological genu valgum typically peaks around 3-4 years and gradually resolves toward normal alignment by around 7-8 years."},{"id": 8809,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Intoeing gait in children is most commonly caused by which of the following (age-dependent)?","options": [{"key": "A","text": "Only cerebral palsy"},{"key": "B","text": "Metatarsus adductus (infant), tibial torsion (toddler), or femoral anteversion (older child)"},{"key": "C","text": "Only clubfoot"},{"key": "D","text": "Only hip dysplasia"}],"correct": "B","explanation": "Different causes of intoeing predominate at different ages: metatarsus adductus in infants, internal tibial torsion in toddlers, and femoral anteversion in older children."},{"id": 8810,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Most cases of pediatric intoeing/torsional deformities are managed with:","options": [{"key": "A","text": "Immediate surgical correction"},{"key": "B","text": "Casting similar to clubfoot management"},{"key": "C","text": "Rigid bracing for all cases"},{"key": "D","text": "Observation, as most resolve spontaneously with growth"}],"correct": "D","explanation": "The majority of pediatric torsional variations are physiological and resolve without intervention as the child grows."},{"id": 8811,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Osgood-Schlatter disease is best classified as:","options": [{"key": "A","text": "A congenital deformity"},{"key": "B","text": "An autoimmune condition"},{"key": "C","text": "An infectious process"},{"key": "D","text": "A traction apophysitis of the tibial tuberosity from repetitive quadriceps pull"}],"correct": "D","explanation": "Osgood-Schlatter is an overuse traction injury at the tibial tuberosity apophysis, common in active adolescents."},{"id": 8812,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Scoliosis screening in schools typically uses which clinical test?","options": [{"key": "A","text": "FABER test"},{"key": "B","text": "Adam's forward bend test"},{"key": "C","text": "Thomas test"},{"key": "D","text": "Ober's test"}],"correct": "B","explanation": "Adam's forward bend test is the standard screening test for detecting spinal asymmetry/rib hump suggestive of scoliosis."},{"id": 8813,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Congenital scoliosis results from:","options": [{"key": "A","text": "Postural habits in adolescence"},{"key": "B","text": "Vertebral malformation during embryonic development (e.g., hemivertebra)"},{"key": "C","text": "Neuromuscular disease exclusively"},{"key": "D","text": "Idiopathic causes"}],"correct": "B","explanation": "Congenital scoliosis arises from structural vertebral anomalies (failure of formation/segmentation) present from birth."},{"id": 8814,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Neuromuscular scoliosis is commonly associated with which underlying conditions?","options": [{"key": "A","text": "Ankylosing spondylitis"},{"key": "B","text": "Only congenital vertebral anomalies"},{"key": "C","text": "Only idiopathic causes"},{"key": "D","text": "Cerebral palsy, muscular dystrophy, and spina bifida"}],"correct": "D","explanation": "Neuromuscular scoliosis develops secondary to underlying neurological or muscular conditions affecting spinal muscle control/balance."},{"id": 8815,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Cerebral palsy is classified based on movement disorder type; 'spastic' CP is characterized by:","options": [{"key": "A","text": "Increased muscle tone/hypertonia due to upper motor neuron damage"},{"key": "B","text": "Poor coordination/balance primarily"},{"key": "C","text": "Fluctuating tone with involuntary movements"},{"key": "D","text": "Reduced tone throughout"}],"correct": "A","explanation": "Spastic CP, the most common type, involves hypertonia/spasticity from upper motor neuron (pyramidal tract) damage."},{"id": 8816,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Gross Motor Function Classification System (GMFCS) is used to classify functional severity in:","options": [{"key": "A","text": "Cerebral palsy"},{"key": "B","text": "Spina bifida exclusively"},{"key": "C","text": "Muscular dystrophy exclusively"},{"key": "D","text": "Scoliosis"}],"correct": "A","explanation": "GMFCS (Levels I-V) classifies functional gross motor abilities in children with cerebral palsy."},{"id": 8817,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Duchenne muscular dystrophy is characterized by:","options": [{"key": "A","text": "Autosomal dominant inheritance with distal weakness"},{"key": "B","text": "Female predominance"},{"key": "C","text": "Onset only in adulthood"},{"key": "D","text": "X-linked recessive inheritance causing progressive proximal muscle weakness"}],"correct": "D","explanation": "DMD is an X-linked recessive dystrophinopathy, predominantly affecting boys, with progressive proximal muscle weakness from early childhood."},{"id": 8818,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Hard","question": "Gower's sign, seen in Duchenne muscular dystrophy, refers to:","options": [{"key": "A","text": "Using hands to 'walk up' the thighs to rise from floor due to proximal muscle weakness"},{"key": "B","text": "Trendelenburg gait only"},{"key": "C","text": "Toe walking only"},{"key": "D","text": "Winging of scapula only"}],"correct": "A","explanation": "Gower's sign describes the characteristic maneuver of using hands on legs to compensate for proximal (hip/thigh) muscle weakness when rising from the floor."},{"id": 8819,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Pseudohypertrophy of the calf muscles is a classic finding in which condition?","options": [{"key": "A","text": "Cerebral palsy"},{"key": "B","text": "Perthes disease"},{"key": "C","text": "Spina bifida"},{"key": "D","text": "Duchenne muscular dystrophy"}],"correct": "D","explanation": "Calf pseudohypertrophy (fat/fibrous tissue replacing muscle) is a classic early finding in DMD."},{"id": 8820,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Spina bifida occulta refers to:","options": [{"key": "A","text": "A mild form with incomplete vertebral arch closure without neural tissue herniation"},{"key": "B","text": "Always causing severe paralysis"},{"key": "C","text": "Herniation of meninges and neural tissue through a defect"},{"key": "D","text": "Complete absence of neural tube formation"}],"correct": "A","explanation": "Spina bifida occulta is the mildest form, involving incomplete vertebral fusion without externally visible neural tissue involvement, often asymptomatic."},{"id": 8821,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Myelomeningocele, the most severe form of spina bifida, involves:","options": [{"key": "A","text": "Herniation of meninges and spinal cord/nerve tissue through the vertebral defect"},{"key": "B","text": "Isolated skin dimple"},{"key": "C","text": "Muscle weakness without any spinal defect"},{"key": "D","text": "Only bony defect without neural involvement"}],"correct": "A","explanation": "Myelomeningocele is the most severe spina bifida form, with neural tissue and meninges protruding through the open defect, typically causing significant neurological deficit."},{"id": 8822,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Torticollis in infants due to sternocleidomastoid fibrosis is typically managed initially with:","options": [{"key": "A","text": "Immediate surgical release"},{"key": "B","text": "Stretching exercises and positioning techniques"},{"key": "C","text": "Rigid neck bracing"},{"key": "D","text": "Observation without any intervention"}],"correct": "B","explanation": "Conservative management with stretching and repositioning is first-line for congenital muscular torticollis, with surgery reserved for resistant cases."},{"id": 8823,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Brachial plexus birth palsy (Erb's palsy) typically results from injury to which nerve roots?","options": [{"key": "A","text": "C5-C6"},{"key": "B","text": "C7 exclusively"},{"key": "C","text": "C8-T1"},{"key": "D","text": "T1-T2"}],"correct": "A","explanation": "Erb's palsy (upper brachial plexus injury) involves C5-C6 roots, producing the classic 'waiter's tip' posture."},{"id": 8824,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Klumpke's palsy involves injury to which brachial plexus roots, causing which characteristic deformity?","options": [{"key": "A","text": "C5-C6, causing waiter's tip posture"},{"key": "B","text": "C8-T1, causing claw hand deformity"},{"key": "C","text": "Isolated radial nerve palsy"},{"key": "D","text": "Only C7"}],"correct": "B","explanation": "Klumpke's palsy affects lower brachial plexus roots (C8-T1), causing intrinsic hand muscle weakness and claw hand deformity."},{"id": 8825,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Congenital vertical talus differs from clubfoot in that it involves:","options": [{"key": "A","text": "Isolated forefoot adduction"},{"key": "B","text": "Equinovarus deformity identical to clubfoot"},{"key": "C","text": "Rigid flatfoot with rocker-bottom deformity from talar dislocation"},{"key": "D","text": "Only ligamentous laxity without bony abnormality"}],"correct": "C","explanation": "Congenital vertical talus presents as a rigid flatfoot deformity ('rocker-bottom foot') due to dorsal dislocation of the navicular on the talus, distinct from clubfoot."},{"id": 8826,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Juvenile idiopathic arthritis physiotherapy management primarily focuses on:","options": [{"key": "A","text": "Aggressive strengthening during active flares"},{"key": "B","text": "Only rest during all phases"},{"key": "C","text": "Maintaining joint ROM, preventing contracture, and appropriate strengthening between flares"},{"key": "D","text": "Avoiding all exercise permanently"}],"correct": "C","explanation": "JIA management balances rest during flares with maintaining ROM/strength and function during quieter disease periods to prevent long-term joint contracture/deformity."},{"id": 8827,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Which condition presents with hip pain and limp in a child following a viral illness, being a diagnosis of exclusion?","options": [{"key": "A","text": "Transient synovitis of the hip"},{"key": "B","text": "Septic arthritis definitively"},{"key": "C","text": "SCFE definitively"},{"key": "D","text": "Perthes disease definitively"}],"correct": "A","explanation": "Transient synovitis is a common, self-limiting cause of childhood hip pain/limp, often post-viral, but must be differentiated from more serious causes like septic arthritis."},{"id": 8828,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Kocher criteria are used clinically to help differentiate:","options": [{"key": "A","text": "Septic arthritis from transient synovitis of the hip in children"},{"key": "B","text": "Perthes disease from SCFE"},{"key": "C","text": "Clubfoot classification"},{"key": "D","text": "Scoliosis severity"}],"correct": "A","explanation": "Kocher criteria (fever, non-weight bearing, elevated ESR/CRP, elevated WBC) help stratify probability of septic arthritis versus transient synovitis."},{"id": 8829,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Metatarsus adductus in infants is characterized by:","options": [{"key": "A","text": "Rigid equinovarus deformity of the whole foot"},{"key": "B","text": "Hindfoot valgus deformity"},{"key": "C","text": "Vertical talus dislocation"},{"key": "D","text": "Medial deviation of the forefoot relative to the hindfoot, often flexible and resolving spontaneously"}],"correct": "D","explanation": "Metatarsus adductus involves isolated forefoot adduction, typically flexible and often resolving without treatment in infants."},{"id": 8830,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Cerebral palsy management commonly includes which physiotherapy approach to improve gross motor function?","options": [{"key": "A","text": "Passive range of motion exercises only"},{"key": "B","text": "Complete immobilization"},{"key": "C","text": "Task-specific functional training and goal-directed therapy"},{"key": "D","text": "Avoidance of all weight-bearing activity"}],"correct": "C","explanation": "Modern CP management emphasizes active, task-specific, functional goal-directed therapy approaches over purely passive interventions."},{"id": 8831,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Serial casting is a common conservative intervention used in pediatric orthopedics for which purpose?","options": [{"key": "A","text": "Gradually correcting joint contractures/deformities (e.g., clubfoot, equinus contracture)"},{"key": "B","text": "Only for scoliosis management"},{"key": "C","text": "Diagnostic purposes only"},{"key": "D","text": "Only for fracture immobilization"}],"correct": "A","explanation": "Serial casting applies progressive gentle correction over successive cast changes to gradually correct contractures or deformities."},{"id": 8832,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Medium","question": "Hip spica cast is commonly used in management of which condition/injury in young children?","options": [{"key": "A","text": "Torticollis"},{"key": "B","text": "Clubfoot"},{"key": "C","text": "Scoliosis"},{"key": "D","text": "Femoral shaft fractures and post-surgical DDH management"}],"correct": "D","explanation": "Hip spica casting immobilizes the hip and lower limb, commonly used for pediatric femoral fractures or after DDH surgical correction."},{"id": 8833,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which of the following best describes the general management approach for physiological genu varum/valgum in toddlers?","options": [{"key": "A","text": "Immediate bracing for all cases"},{"key": "B","text": "Reassurance and monitoring, as most resolve with normal growth"},{"key": "C","text": "Surgical correction at first presentation"},{"key": "D","text": "Casting similar to clubfoot"}],"correct": "B","explanation": "Physiological variations typically require only observation/reassurance as they resolve naturally with growth, unless red flags suggest pathological cause."},{"id": 8834,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which red flag finding in a child with lower limb bowing would suggest a pathological rather than physiological cause?","options": [{"key": "A","text": "Family history of similar resolved bowing"},{"key": "B","text": "Symmetric mild bowing resolving by age 2-3"},{"key": "C","text": "Asymmetry, short stature, or progression beyond expected age"},{"key": "D","text": "Normal growth parameters"}],"correct": "C","explanation": "Asymmetric deformity, short stature, or persistence/worsening beyond typical resolution age suggests pathological causes (e.g., Blount's disease, rickets) requiring further investigation."},{"id": 8835,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Physiotherapy assessment of gait in children with cerebral palsy commonly uses which observational classification for lower limb patterns?","options": [{"key": "A","text": "Gustilo classification"},{"key": "B","text": "Neer classification"},{"key": "C","text": "Meyerding classification"},{"key": "D","text": "Rancho Los Amigos / Winters classification of CP gait patterns"}],"correct": "D","explanation": "Specific gait classification systems (e.g., Winters classification for hemiplegic gait) help characterize and guide management of CP-related gait patterns."},{"id": 8836,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Seddon's classification of nerve injury includes which three categories?","options": [{"key": "A","text": "Mild, moderate, severe"},{"key": "B","text": "Neurapraxia, Axonotmesis, Neurotmesis"},{"key": "C","text": "Type A, B, C"},{"key": "D","text": "Grade I, II, III only"}],"correct": "B","explanation": "Seddon's classification categorizes nerve injury severity into neurapraxia (mildest), axonotmesis, and neurotmesis (most severe)."},{"id": 8837,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Neurapraxia is characterized by:","options": [{"key": "A","text": "Permanent nerve damage without recovery potential"},{"key": "B","text": "Axonal disruption with intact connective tissue"},{"key": "C","text": "Complete nerve transection"},{"key": "D","text": "Temporary conduction block without axonal disruption, full recovery expected"}],"correct": "D","explanation": "Neurapraxia involves local conduction block (often from compression) without structural axonal damage, typically resolving completely within weeks."},{"id": 8838,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Axonotmesis involves:","options": [{"key": "A","text": "Only myelin sheath damage without axonal involvement"},{"key": "B","text": "No structural damage at all"},{"key": "C","text": "Disruption of the axon with preservation of the surrounding connective tissue (endoneurium)"},{"key": "D","text": "Complete nerve transection including all connective tissue"}],"correct": "C","explanation": "Axonotmesis involves axonal disruption with intact supporting connective tissue framework, allowing potential regeneration along the preserved pathway."},{"id": 8839,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Neurotmesis represents:","options": [{"key": "A","text": "Complete disruption of the nerve including axon and all connective tissue layers"},{"key": "B","text": "Axonal injury with intact epineurium only"},{"key": "C","text": "Temporary conduction block only"},{"key": "D","text": "Mildest form of nerve injury"}],"correct": "A","explanation": "Neurotmesis is the most severe injury, with complete structural disruption typically requiring surgical repair for any chance of recovery."},{"id": 8840,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sunderland's classification expands nerve injury into how many degrees?","options": [{"key": "A","text": "Two degrees"},{"key": "B","text": "Seven degrees"},{"key": "C","text": "Three degrees only"},{"key": "D","text": "Five degrees"}],"correct": "D","explanation": "Sunderland's classification provides more detailed grading (1st through 5th degree) based on specific connective tissue layers involved."},{"id": 8841,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Wallerian degeneration refers to:","options": [{"key": "A","text": "Immediate regeneration without degeneration"},{"key": "B","text": "Degeneration of the axon distal to the site of injury"},{"key": "C","text": "Degeneration proximal to the injury site only"},{"key": "D","text": "Only myelin changes without axonal involvement"}],"correct": "B","explanation": "Wallerian degeneration describes the breakdown of the axon and myelin distal to an injury site, a necessary precursor to regeneration."},{"id": 8842,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Peripheral nerve regeneration after axonotmesis typically occurs at approximately what rate?","options": [{"key": "A","text": "10cm per day"},{"key": "B","text": "No regeneration is possible"},{"key": "C","text": "1cm per day"},{"key": "D","text": "1mm per day (approximately 1 inch per month)"}],"correct": "D","explanation": "Peripheral nerve axons typically regenerate at approximately 1mm/day, informing expected recovery timelines."},{"id": 8843,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Radial nerve palsy classically presents with:","options": [{"key": "A","text": "Ape hand deformity"},{"key": "B","text": "Wrist drop and finger drop with sensory loss over the dorsal first web space"},{"key": "C","text": "Claw hand deformity"},{"key": "D","text": "Foot drop"}],"correct": "B","explanation": "Radial nerve palsy causes loss of wrist/finger extension (wrist drop) with characteristic sensory loss over the dorsal thumb-index web space."},{"id": 8844,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "Median nerve palsy at the wrist (complete) causes weakness of which key function?","options": [{"key": "A","text": "Thumb opposition (thenar muscles)"},{"key": "B","text": "Finger abduction"},{"key": "C","text": "Wrist extension"},{"key": "D","text": "Elbow flexion"}],"correct": "A","explanation": "Median nerve innervates thenar muscles (via recurrent branch); wrist-level injury classically impairs thumb opposition."},{"id": 8845,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ulnar nerve palsy classically causes which deformity due to unopposed extensor action?","options": [{"key": "A","text": "Wrist drop"},{"key": "B","text": "Ape hand"},{"key": "C","text": "Mallet finger"},{"key": "D","text": "Claw hand (ring and little finger)"}],"correct": "D","explanation": "Ulnar nerve palsy paralyzes medial lumbricals/interossei, causing claw deformity of ring and little fingers from unopposed EDC/FDP action."},{"id": 8846,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Common peroneal nerve injury classically results in:","options": [{"key": "A","text": "Complete loss of all ankle movement"},{"key": "B","text": "Foot drop with loss of dorsiflexion and eversion"},{"key": "C","text": "Loss of plantarflexion only"},{"key": "D","text": "Loss of inversion only"}],"correct": "B","explanation": "Common peroneal nerve palsy (often at fibular neck) causes foot drop due to loss of dorsiflexor and evertor function."},{"id": 8847,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sciatic nerve injury affects which combined muscle groups?","options": [{"key": "A","text": "Only hip flexors"},{"key": "B","text": "Only quadriceps"},{"key": "C","text": "Only gluteal muscles"},{"key": "D","text": "Hamstrings and all muscles below the knee (both peroneal and tibial nerve distribution)"}],"correct": "D","explanation": "Complete sciatic nerve injury affects hamstring function and all muscles supplied by its peroneal and tibial divisions below the knee."},{"id": 8848,"subject": "Musculoskeletal Physiotherapy","topic": "Hip & Thigh","difficulty": "Hard","question": "Femoral nerve injury classically presents with weakness of:","options": [{"key": "A","text": "Hip abduction"},{"key": "B","text": "Ankle plantarflexion"},{"key": "C","text": "Knee extension (quadriceps) and sensory loss over anterior/medial thigh"},{"key": "D","text": "Hip extension primarily"}],"correct": "C","explanation": "Femoral nerve supplies the quadriceps (knee extension) and iliopsoas (hip flexion), with sensory distribution over anterior thigh and medial leg (saphenous)."},{"id": 8849,"subject": "Musculoskeletal Physiotherapy","topic": "Shoulder Complex","difficulty": "Easy","question": "Axillary nerve injury (e.g., after shoulder dislocation) classically causes weakness of:","options": [{"key": "A","text": "Deltoid (shoulder abduction) with sensory loss over 'regimental badge' area"},{"key": "B","text": "Rotator cuff external rotators only"},{"key": "C","text": "Biceps only"},{"key": "D","text": "Wrist extensors"}],"correct": "A","explanation": "Axillary nerve palsy weakens deltoid (and teres minor), with sensory deficit over the lateral shoulder ('regimental badge' area)."},{"id": 8850,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Long thoracic nerve injury causes weakness of which muscle, leading to winged scapula?","options": [{"key": "A","text": "Trapezius"},{"key": "B","text": "Rhomboids"},{"key": "C","text": "Serratus anterior"},{"key": "D","text": "Levator scapulae"}],"correct": "C","explanation": "Long thoracic nerve palsy weakens serratus anterior, producing classic medial winging of the scapula."},{"id": 8851,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Nerve conduction studies (NCS) and electromyography (EMG) are used clinically to:","options": [{"key": "A","text": "Replace clinical examination entirely"},{"key": "B","text": "Localize and characterize the severity/type of nerve injury"},{"key": "C","text": "Only assess muscle strength subjectively"},{"key": "D","text": "Diagnose bone fractures"}],"correct": "B","explanation": "NCS/EMG provide objective electrophysiological data to help localize nerve lesions and assess severity/prognosis."},{"id": 8852,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Which sign indicates advancing nerve regeneration along a peripheral nerve's course?","options": [{"key": "A","text": "Static Tinel's sign with no change"},{"key": "B","text": "Absence of any sensation permanently"},{"key": "C","text": "Increasing motor weakness over time"},{"key": "D","text": "Advancing Tinel's sign (tingling with percussion moving distally over time)"}],"correct": "D","explanation": "A distally advancing Tinel's sign over serial examinations suggests progressing axonal regeneration along the nerve."},{"id": 8853,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Physiotherapy management for peripheral nerve injury during the denervation period typically includes:","options": [{"key": "A","text": "Splinting to prevent overstretching of denervated muscles, passive ROM, and electrical stimulation (where indicated)"},{"key": "B","text": "Complete immobilization of the entire limb"},{"key": "C","text": "Aggressive resistance training of denervated muscles"},{"key": "D","text": "No intervention until spontaneous full recovery"}],"correct": "A","explanation": "Protecting denervated muscles from overstretch, maintaining joint ROM, and appropriate stimulation are key components during nerve recovery."},{"id": 8854,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "A 'foot drop splint' (ankle-foot orthosis) is commonly prescribed for which nerve injury?","options": [{"key": "A","text": "Common peroneal nerve palsy"},{"key": "B","text": "Obturator nerve palsy"},{"key": "C","text": "Femoral nerve palsy"},{"key": "D","text": "Tibial nerve palsy"}],"correct": "A","explanation": "AFO supports the foot in a neutral/dorsiflexed position, compensating for dorsiflexor weakness from peroneal nerve injury."},{"id": 8855,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Brachial plexus injuries are classified anatomically based on location relative to which structure?","options": [{"key": "A","text": "Skin dermatome pattern only"},{"key": "B","text": "Dorsal root ganglion (pre-ganglionic vs post-ganglionic)"},{"key": "C","text": "Vertebral level only"},{"key": "D","text": "Muscle involvement only"}],"correct": "B","explanation": "Pre-ganglionic (root avulsion, worse prognosis, no surgical repair of root itself possible) versus post-ganglionic injury classification is critical for brachial plexus injury management/prognosis."},{"id": 8856,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pre-ganglionic (nerve root avulsion) brachial plexus injuries have which characteristic finding, aiding diagnosis?","options": [{"key": "A","text": "Negative Horner's syndrome always"},{"key": "B","text": "Absent sensory nerve action potentials always with clinical anesthesia"},{"key": "C","text": "No distinguishing features from post-ganglionic injury"},{"key": "D","text": "Positive Horner's syndrome (if lower roots involved) and preserved sensory nerve action potentials despite clinical anesthesia"}],"correct": "D","explanation": "Pre-ganglionic injuries can show a 'dissociation' - clinically absent sensation but preserved SNAPs (since the dorsal root ganglion cell body remains intact), aiding localization; Horner's syndrome suggests T1 root avulsion."},{"id": 8857,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Medium","question": "Nerve gliding/mobilization exercises are used in rehabilitation of entrapment neuropathies to:","options": [{"key": "A","text": "Cause further nerve damage intentionally"},{"key": "B","text": "Replace the need for addressing the underlying compressive cause"},{"key": "C","text": "Increase compression on the nerve deliberately"},{"key": "D","text": "Improve nerve mobility and reduce adhesions along its anatomical course"}],"correct": "D","explanation": "Nerve gliding techniques aim to restore normal nerve mobility/excursion, reducing symptoms related to entrapment/adhesions."},{"id": 8858,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which factor most significantly influences the prognosis for recovery following peripheral nerve injury?","options": [{"key": "A","text": "Patient's age only, unrelated to injury type"},{"key": "B","text": "Nothing influences prognosis, all injuries are identical"},{"key": "C","text": "Type/severity of injury (per Seddon/Sunderland classification) and time to treatment"},{"key": "D","text": "Only the specific nerve involved, regardless of injury severity"}],"correct": "C","explanation": "Injury severity (neurapraxia vs neurotmesis) and timely appropriate management are key prognostic factors for nerve injury recovery."},{"id": 8859,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Electrical stimulation of denervated muscle is sometimes used clinically primarily to:","options": [{"key": "A","text": "Replace the need for any surgical nerve repair"},{"key": "B","text": "Directly speed up axonal regeneration rate"},{"key": "C","text": "Help maintain muscle bulk/delay atrophy while awaiting reinnervation"},{"key": "D","text": "Cure the nerve injury completely"}],"correct": "C","explanation": "Electrical stimulation of denervated muscle aims to slow disuse atrophy during the reinnervation waiting period, though evidence and protocols vary."},{"id": 8860,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Compression neuropathy (entrapment) differs from traumatic nerve transection primarily in:","options": [{"key": "A","text": "Mechanism (chronic compression vs acute disruption) and generally better prognosis with decompression"},{"key": "B","text": "Entrapment always being worse prognostically"},{"key": "C","text": "Transection always resolving spontaneously without treatment"},{"key": "D","text": "Both having identical mechanisms and prognosis"}],"correct": "A","explanation": "Entrapment neuropathies result from chronic compression and generally have good prognosis with timely decompression, differing from acute traumatic transection requiring surgical repair."},{"id": 8861,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The most common cause of lower limb amputation worldwide is:","options": [{"key": "A","text": "Trauma"},{"key": "B","text": "Malignancy"},{"key": "C","text": "Congenital limb deficiency"},{"key": "D","text": "Peripheral vascular disease/diabetes-related complications"}],"correct": "D","explanation": "Vascular disease and diabetic complications account for the majority of lower limb amputations, particularly in older populations."},{"id": 8862,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Transtibial amputation refers to amputation at which level?","options": [{"key": "A","text": "Through the ankle"},{"key": "B","text": "Below knee"},{"key": "C","text": "Through the hip"},{"key": "D","text": "Above knee"}],"correct": "B","explanation": "Transtibial (below-knee) amputation is performed through the tibia/fibula, preserving the knee joint."},{"id": 8863,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Transfemoral amputation refers to amputation at which level?","options": [{"key": "A","text": "Through the ankle (Syme's)"},{"key": "B","text": "Above knee"},{"key": "C","text": "Through the hip"},{"key": "D","text": "Below knee"}],"correct": "B","explanation": "Transfemoral (above-knee) amputation is performed through the femur."},{"id": 8864,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Syme's amputation is performed at which level?","options": [{"key": "A","text": "Through the ankle joint, preserving the heel pad"},{"key": "B","text": "Below the knee"},{"key": "C","text": "Above the knee"},{"key": "D","text": "Through the midfoot"}],"correct": "A","explanation": "Syme's amputation is an ankle disarticulation preserving the heel pad for end-bearing capability."},{"id": 8865,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Preserving knee joint function in a transtibial amputation is advantageous primarily because it:","options": [{"key": "A","text": "Reduces energy expenditure during ambulation compared to transfemoral level"},{"key": "B","text": "Increases energy expenditure"},{"key": "C","text": "Only benefits cosmetic appearance"},{"key": "D","text": "Has no effect on functional outcome"}],"correct": "A","explanation": "Preserving the knee joint significantly reduces the energy cost of walking compared to more proximal (transfemoral) amputation levels."},{"id": 8866,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Phantom limb sensation refers to:","options": [{"key": "A","text": "The perception that the amputated limb is still present"},{"key": "B","text": "Loss of all sensation in residual limb"},{"key": "C","text": "A surgical complication requiring reamputation"},{"key": "D","text": "Only pain in the residual limb"}],"correct": "A","explanation": "Phantom limb sensation is a common perceptual phenomenon where patients feel the presence of the amputated part, distinct from phantom limb pain."},{"id": 8867,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Phantom limb pain differs from phantom limb sensation in that it involves:","options": [{"key": "A","text": "Simple awareness of limb presence without pain"},{"key": "B","text": "Complete absence of any limb perception"},{"key": "C","text": "Only residual limb tenderness"},{"key": "D","text": "Painful sensations perceived in the missing limb"}],"correct": "D","explanation": "Phantom limb pain specifically refers to painful (rather than just perceptual) sensations attributed to the amputated limb."},{"id": 8868,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Mirror therapy is a recognized intervention used to help manage:","options": [{"key": "A","text": "Contracture prevention exclusively"},{"key": "B","text": "Prosthetic fitting issues only"},{"key": "C","text": "Residual limb wound infection"},{"key": "D","text": "Phantom limb pain"}],"correct": "D","explanation": "Mirror therapy uses visual feedback (reflecting the intact limb) to help modulate phantom limb pain via cortical reorganization mechanisms."},{"id": 8869,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Residual limb shaping/shrinking after amputation is commonly achieved using:","options": [{"key": "A","text": "Only elevation without compression"},{"key": "B","text": "Compression bandaging or shrinker socks"},{"key": "C","text": "Massage alone without compression"},{"key": "D","text": "Only ice application"}],"correct": "B","explanation": "Compression techniques (bandaging, shrinker socks) help reduce edema and shape the residual limb in preparation for prosthetic fitting."},{"id": 8870,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Desensitization techniques for the residual limb after amputation aim to:","options": [{"key": "A","text": "Replace the need for wound care"},{"key": "B","text": "Reduce hypersensitivity and improve tolerance to touch/pressure for prosthetic wear"},{"key": "C","text": "Prevent phantom limb sensation entirely"},{"key": "D","text": "Increase pain sensitivity intentionally"}],"correct": "B","explanation": "Desensitization (tapping, varied textures) helps the residual limb tolerate contact/pressure needed for comfortable prosthetic use."},{"id": 8871,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which contracture is a common risk following transfemoral amputation if not properly managed with positioning?","options": [{"key": "A","text": "Knee flexion contracture primarily"},{"key": "B","text": "Hip extension contracture"},{"key": "C","text": "Hip flexion and abduction contracture"},{"key": "D","text": "Ankle plantarflexion contracture"}],"correct": "C","explanation": "Unopposed hip flexors/abductors (with loss of distal muscle attachments) predispose to hip flexion-abduction contracture after transfemoral amputation if prone positioning/prevention isn't emphasized."},{"id": 8872,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which contracture is a common risk following transtibial amputation?","options": [{"key": "A","text": "Knee extension contracture"},{"key": "B","text": "Hip abduction contracture primarily"},{"key": "C","text": "Knee flexion contracture"},{"key": "D","text": "Ankle dorsiflexion contracture"}],"correct": "C","explanation": "Prolonged sitting/knee flexion positioning post-transtibial amputation risks knee flexion contracture without proper prevention (extension positioning, prone lying)."},{"id": 8873,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Pre-prosthetic training typically includes all of the following EXCEPT:","options": [{"key": "A","text": "Strengthening of residual and intact limb muscles"},{"key": "B","text": "Balance and mobility training with assistive devices"},{"key": "C","text": "Residual limb shaping and desensitization"},{"key": "D","text": "Advanced prosthetic gait training with the definitive prosthesis"}],"correct": "D","explanation": "Advanced prosthetic gait training occurs after prosthetic fitting; pre-prosthetic phase focuses on preparing the limb and patient for eventual prosthetic use."},{"id": 8874,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Energy expenditure during ambulation is generally highest with which level of lower limb amputation?","options": [{"key": "A","text": "Syme's amputation"},{"key": "B","text": "Bilateral transfemoral amputation"},{"key": "C","text": "Partial foot amputation"},{"key": "D","text": "Unilateral transtibial amputation"}],"correct": "B","explanation": "Higher (more proximal) and bilateral amputation levels significantly increase the metabolic/energy cost of walking compared to distal, unilateral levels."},{"id": 8875,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Prosthetic socket fit assessment is critical because poor fit can lead to:","options": [{"key": "A","text": "No functional consequence if ignored"},{"key": "B","text": "Improved proprioception automatically"},{"key": "C","text": "Only cosmetic concerns"},{"key": "D","text": "Skin breakdown, pain, and gait deviations"}],"correct": "D","explanation": "A poorly fitting socket can cause pressure areas, pain, and compensatory gait abnormalities, making proper fit assessment essential."},{"id": 8876,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which gait deviation is commonly seen with a prosthesis that is too long?","options": [{"key": "A","text": "Excessive knee flexion during stance"},{"key": "B","text": "Vaulting or circumduction on the prosthetic side"},{"key": "C","text": "Foot slap"},{"key": "D","text": "Lateral trunk bending toward prosthesis"}],"correct": "B","explanation": "An excessively long prosthesis requires compensatory strategies (vaulting, circumduction) to achieve ground clearance during swing."},{"id": 8877,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Lateral trunk bending (lurching) toward the prosthetic side during stance may indicate:","options": [{"key": "A","text": "Prosthesis too short"},{"key": "B","text": "Inadequate socket fit, weak hip abductors, or a socket that is too narrow medio-laterally"},{"key": "C","text": "Normal gait pattern requiring no correction"},{"key": "D","text": "Prosthesis too long"}],"correct": "B","explanation": "Lateral trunk lean during prosthetic stance often relates to socket fit issues or hip abductor weakness/discomfort, similar to a Trendelenburg-type compensation."},{"id": 8878,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Hard","question": "Which prosthetic knee component type provides greater stability but less natural swing-phase knee flexion, often used for less active/elderly transfemoral amputees?","options": [{"key": "A","text": "Microprocessor-controlled knee"},{"key": "B","text": "Locked/manual locking knee or single-axis constant friction knee"},{"key": "C","text": "Energy-storing dynamic response foot"},{"key": "D","text": "Polycentric knee with advanced hydraulics"}],"correct": "B","explanation": "Simpler, more stable knee mechanisms (e.g., locked knee) prioritize safety over natural gait dynamics, often suited to lower-demand users."},{"id": 8879,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Microprocessor-controlled prosthetic knees offer which advantage over conventional mechanical knees?","options": [{"key": "A","text": "Lower cost compared to mechanical knees"},{"key": "B","text": "Real-time adjustment of resistance based on gait phase, improving stability and natural movement"},{"key": "C","text": "No maintenance required ever"},{"key": "D","text": "Elimination of the need for physiotherapy gait training"}],"correct": "B","explanation": "Microprocessor knees continuously adjust to walking speed/terrain, offering improved stability and more natural gait patterns compared to fixed mechanical knees."},{"id": 8880,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Energy-storing prosthetic feet (e.g., dynamic response feet) are particularly beneficial for:","options": [{"key": "A","text": "Patients requiring maximum stability with no dynamic function"},{"key": "B","text": "Only sedentary, low-demand elderly patients"},{"key": "C","text": "Patients with significant cognitive impairment only"},{"key": "D","text": "More active amputees engaging in varied activities including running/sports"}],"correct": "D","explanation": "Energy-storing feet return stored energy during push-off, benefiting more active users with higher functional demands."},{"id": 8881,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Upper limb amputation prosthetic options include body-powered and myoelectric prostheses; myoelectric prostheses function by:","options": [{"key": "A","text": "Only being used for cosmetic purposes without function"},{"key": "B","text": "Using cables and body movement to control the device"},{"key": "C","text": "Detecting electrical signals from residual limb muscles to control prosthetic movement"},{"key": "D","text": "Requiring no residual muscle function at all"}],"correct": "C","explanation": "Myoelectric prostheses use surface EMG signals from residual muscles to control motorized prosthetic components."},{"id": 8882,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Body-powered upper limb prostheses are controlled by:","options": [{"key": "A","text": "Voice commands"},{"key": "B","text": "Electrical muscle signals exclusively"},{"key": "C","text": "External remote control"},{"key": "D","text": "Cables connected to a harness, activated by body/shoulder movement"}],"correct": "D","explanation": "Body-powered prostheses use a harness-cable system where residual body movement (e.g., shoulder shrug/flexion) operates the terminal device."},{"id": 8883,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which factor is important in successful psychological adjustment following limb amputation?","options": [{"key": "A","text": "Avoiding any discussion of the limb loss"},{"key": "B","text": "Early involvement of multidisciplinary support including psychological counseling alongside physical rehabilitation"},{"key": "C","text": "Focusing exclusively on physical rehabilitation without psychosocial support"},{"key": "D","text": "Isolation from support networks"}],"correct": "B","explanation": "Comprehensive amputation rehabilitation addresses psychological adjustment alongside physical recovery, recognizing the significant emotional impact of limb loss."},{"id": 8884,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which of the following is an important consideration in prescribing a prosthesis for a dysvascular (e.g., diabetic) amputee?","options": [{"key": "A","text": "Avoiding all mobility training"},{"key": "B","text": "Always prescribing the most advanced/heaviest componentry"},{"key": "C","text": "Careful skin/vascular monitoring given increased risk of skin breakdown and slower healing"},{"key": "D","text": "No special considerations needed compared to traumatic amputees"}],"correct": "C","explanation": "Dysvascular amputees require careful attention to skin integrity and vascular status given their compromised healing capacity and comorbidities."},{"id": 8885,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Rehabilitation goals following amputation should be primarily guided by:","options": [{"key": "A","text": "Insurance coverage exclusively, disregarding functional needs"},{"key": "B","text": "Individual patient factors including functional goals, comorbidities, and level of amputation"},{"key": "C","text": "A single standardized protocol applied to all patients uniformly"},{"key": "D","text": "Amputation level alone regardless of patient factors"}],"correct": "B","explanation": "Person-centered rehabilitation considers the individual's functional goals, health status, and amputation characteristics to guide realistic, appropriate rehabilitation planning."},{"id": 8886,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Medium","question": "An Ankle-Foot Orthosis (AFO) is commonly prescribed for which condition?","options": [{"key": "A","text": "Foot drop (dorsiflexor weakness)"},{"key": "B","text": "Shoulder instability"},{"key": "C","text": "Knee extensor weakness primarily"},{"key": "D","text": "Hip abductor weakness"}],"correct": "A","explanation": "AFO supports the ankle in neutral/dorsiflexed position, compensating for dorsiflexor weakness (e.g., peroneal nerve palsy, stroke)."},{"id": 8887,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "A Knee-Ankle-Foot Orthosis (KAFO) is typically indicated for:","options": [{"key": "A","text": "Hip flexor weakness only"},{"key": "B","text": "Significant quadriceps weakness requiring knee stability during stance"},{"key": "C","text": "Shoulder subluxation"},{"key": "D","text": "Isolated foot drop only"}],"correct": "B","explanation": "KAFO provides knee stability (often locked in extension) in addition to ankle control, used when quadriceps cannot adequately stabilize the knee."},{"id": 8888,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "A resting hand splint in rheumatoid arthritis is primarily used to:","options": [{"key": "A","text": "Increase joint mobility beyond normal range"},{"key": "B","text": "Force maximal ROM constantly"},{"key": "C","text": "Support joints in a functional position, reduce pain, and help prevent deformity"},{"key": "D","text": "Replace the need for any exercise"}],"correct": "C","explanation": "Resting splints position the hand to reduce stress and support joints, typically worn during rest periods (e.g., night) rather than during activity."},{"id": 8889,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Easy","question": "A cock-up wrist splint is commonly prescribed for:","options": [{"key": "A","text": "Ankle instability"},{"key": "B","text": "Knee OA"},{"key": "C","text": "Carpal tunnel syndrome or wrist extensor weakness (e.g., radial nerve palsy)"},{"key": "D","text": "Hip dysplasia"}],"correct": "C","explanation": "Wrist cock-up splints maintain neutral/extended wrist position, useful in CTS management or compensating for wrist extensor weakness."},{"id": 8890,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "A cervical collar (soft or rigid) is used primarily to:","options": [{"key": "A","text": "Provide support and limit motion of the cervical spine following injury/surgery"},{"key": "B","text": "Strengthen neck muscles"},{"key": "C","text": "Increase cervical ROM"},{"key": "D","text": "Replace physiotherapy exercises long-term"}],"correct": "A","explanation": "Cervical collars provide temporary support/immobilization, typically used short-term post-injury, with prolonged use discouraged due to muscle deconditioning risk."},{"id": 8891,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "A lumbosacral corset/brace may be used post-operatively or in acute low back pain primarily to:","options": [{"key": "A","text": "Permanently replace core muscle function"},{"key": "B","text": "Provide temporary external support and proprioceptive feedback"},{"key": "C","text": "Increase spinal mobility"},{"key": "D","text": "Cure the underlying spinal pathology"}],"correct": "B","explanation": "Lumbar braces offer short-term support and proprioceptive cues, generally used as an adjunct rather than a long-term solution to avoid muscle deconditioning."},{"id": 8892,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "A hinged knee brace is commonly used following which type of injury to allow controlled protected motion?","options": [{"key": "A","text": "Ligament injury/reconstruction (e.g., ACL, MCL)"},{"key": "B","text": "Simple ankle sprain"},{"key": "C","text": "Wrist fracture"},{"key": "D","text": "Shoulder dislocation"}],"correct": "A","explanation": "Hinged knee braces allow controlled ROM while providing protection/support following ligamentous knee injury or surgery."},{"id": 8893,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "A thumb spica splint is commonly used for management of:","options": [{"key": "A","text": "Trigger finger"},{"key": "B","text": "Boutonniere deformity"},{"key": "C","text": "De Quervain's tenosynovitis or scaphoid fracture"},{"key": "D","text": "Mallet finger"}],"correct": "C","explanation": "Thumb spica immobilizes the thumb and wrist, appropriate for conditions involving the thumb's radial structures like De Quervain's or suspected scaphoid injury."},{"id": 8894,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Crutches (axillary or forearm) are prescribed to:","options": [{"key": "A","text": "Increase weight bearing through an injured limb"},{"key": "B","text": "Reduce weight-bearing load and assist with balance/mobility"},{"key": "C","text": "Only for cosmetic support"},{"key": "D","text": "Replace the need for any gait training"}],"correct": "B","explanation": "Crutches assist ambulation by redistributing load away from an injured/weak limb while providing balance support."},{"id": 8895,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Proper axillary crutch fitting should ensure a gap of approximately how much between the axilla and the crutch top?","options": [{"key": "A","text": "10cm gap minimum"},{"key": "B","text": "2-3 finger widths (approximately 2 inches/5cm)"},{"key": "C","text": "No gap, crutch should press into axilla"},{"key": "D","text": "Direct contact with axilla is required"}],"correct": "B","explanation": "A small gap (about 2-3 finger widths) between axilla and crutch top prevents pressure on the brachial plexus/axillary structures."},{"id": 8896,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "A four-point gait pattern with a walking aid is generally used for patients requiring:","options": [{"key": "A","text": "Only unilateral limb involvement"},{"key": "B","text": "Minimal support with good balance"},{"key": "C","text": "Maximum stability, e.g., significant balance impairment with ability to bear weight on both limbs"},{"key": "D","text": "No weight-bearing on either limb"}],"correct": "C","explanation": "Four-point gait pattern (moving one device/limb at a time) provides maximum stability, suited for patients needing significant support with adequate bilateral weight-bearing ability."},{"id": 8897,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "A walking frame/walker is generally recommended over a single cane when:","options": [{"key": "A","text": "The patient requires a device for cosmetic reasons only"},{"key": "B","text": "Only mild balance impairment exists"},{"key": "C","text": "No weight-bearing restriction exists and balance is excellent"},{"key": "D","text": "Greater stability and support is required due to significant balance or strength deficits"}],"correct": "D","explanation": "Walking frames provide a wider base of support, appropriate for patients with more significant balance/strength limitations than a single point cane can address."},{"id": 8898,"subject": "Musculoskeletal Physiotherapy","topic": "Elbow, Wrist & Hand","difficulty": "Hard","question": "A cane should typically be used in which hand relative to the affected/weaker lower limb?","options": [{"key": "A","text": "Cannot be used with any lower limb condition"},{"key": "B","text": "Opposite (contralateral) hand to the affected limb"},{"key": "C","text": "Either hand, no difference in biomechanics"},{"key": "D","text": "Same side as the affected limb"}],"correct": "B","explanation": "Using a cane in the hand contralateral to the affected limb creates a more normal reciprocal gait pattern and effectively reduces joint loading on the affected side."},{"id": 8899,"subject": "Musculoskeletal Physiotherapy","topic": "Foot & Ankle","difficulty": "Easy","question": "Custom foot orthoses are commonly prescribed to address which biomechanical issue?","options": [{"key": "A","text": "Fixing structural bone deformities permanently without other intervention"},{"key": "B","text": "Abnormal foot pronation/supination patterns contributing to pain or overuse injury"},{"key": "C","text": "Complete replacement of muscle strengthening needs"},{"key": "D","text": "Only cosmetic foot appearance"}],"correct": "B","explanation": "Foot orthoses aim to modify abnormal foot mechanics that may contribute to pain conditions like plantar fasciitis or PTTD, as an adjunct to other management."},{"id": 8900,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Serial static splinting differs from dynamic splinting in that it:","options": [{"key": "A","text": "Is used exclusively for acute fractures"},{"key": "B","text": "Never allows any joint movement in either type"},{"key": "C","text": "Both provide identical continuous tension with movement"},{"key": "D","text": "Applies a fixed, sustained stretch that is periodically adjusted, versus dynamic splints providing continuous gentle tension with joint movement allowed"}],"correct": "D","explanation": "Static progressive/serial splints are remolded/adjusted periodically to gradually increase stretch, while dynamic splints use elastic/spring components allowing controlled active movement against gentle resistance."},{"id": 8901,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sports injuries are broadly classified into which two main categories based on onset?","options": [{"key": "A","text": "Only traumatic injuries exist in sport"},{"key": "B","text": "Acute (traumatic) and chronic (overuse) injuries"},{"key": "C","text": "Only overuse injuries occur in sport"},{"key": "D","text": "Congenital and acquired injuries"}],"correct": "B","explanation": "Sports injuries are commonly categorized as acute (sudden onset trauma) or chronic/overuse (repetitive microtrauma) injuries."},{"id": 8902,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Overuse injuries in sport typically result from:","options": [{"key": "A","text": "Repetitive submaximal loading exceeding tissue's adaptive capacity"},{"key": "B","text": "Only poor nutrition"},{"key": "C","text": "A single traumatic event"},{"key": "D","text": "Genetic factors exclusively"}],"correct": "A","explanation": "Overuse injuries develop when cumulative repetitive stress exceeds the tissue's ability to repair/adapt, common in endurance and repetitive-motion sports."},{"id": 8903,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which principle describes the balance between training load and recovery to prevent overuse injury?","options": [{"key": "A","text": "Specificity principle only"},{"key": "B","text": "Load management / training load monitoring principle"},{"key": "C","text": "Reversibility principle only"},{"key": "D","text": "Overload principle in isolation without recovery consideration"}],"correct": "B","explanation": "Appropriate load management, balancing progressive overload with adequate recovery, is key to injury prevention in sports training."},{"id": 8904,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "The 'acute:chronic workload ratio' concept is used in sports science to:","options": [{"key": "A","text": "Measure muscle strength directly"},{"key": "B","text": "Assess injury risk based on recent training load relative to longer-term average load"},{"key": "C","text": "Replace clinical assessment entirely"},{"key": "D","text": "Diagnose specific injuries"}],"correct": "B","explanation": "ACWR compares short-term (acute) training load to longer-term (chronic) load, with spikes in this ratio associated with increased injury risk."},{"id": 8905,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Functional Movement Screen (FMS) is used in sports settings to:","options": [{"key": "A","text": "Diagnose specific ligament tears"},{"key": "B","text": "Replace the need for any clinical examination"},{"key": "C","text": "Identify movement pattern limitations/asymmetries that may predispose to injury"},{"key": "D","text": "Measure cardiovascular fitness"}],"correct": "C","explanation": "FMS assesses fundamental movement patterns to identify potential dysfunction/asymmetry that could contribute to injury risk."},{"id": 8906,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Return-to-play decision making after sports injury should be based on:","options": [{"key": "A","text": "Patient's desire to return without any assessment"},{"key": "B","text": "Coach's preference exclusively regardless of clinical status"},{"key": "C","text": "Criteria-based progression including functional testing, not just time since injury"},{"key": "D","text": "Time elapsed since injury alone"}],"correct": "C","explanation": "Modern return-to-play protocols emphasize objective criteria (strength, function, psychological readiness) over arbitrary time-based decisions alone."},{"id": 8907,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The 'H:Q ratio' (hamstring to quadriceps strength ratio) is particularly relevant in prevention of which injury?","options": [{"key": "A","text": "Rotator cuff tear"},{"key": "B","text": "Hamstring strain and ACL injury"},{"key": "C","text": "Wrist fracture"},{"key": "D","text": "Ankle sprain"}],"correct": "B","explanation": "An imbalanced H:Q ratio has been associated with increased risk of hamstring strains and ACL injuries, particularly in explosive/cutting sports."},{"id": 8908,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Plyometric training is used in sports rehabilitation primarily to improve:","options": [{"key": "A","text": "Only flexibility"},{"key": "B","text": "Passive joint ROM"},{"key": "C","text": "Explosive power and the stretch-shortening cycle utilization"},{"key": "D","text": "Only cardiovascular endurance"}],"correct": "C","explanation": "Plyometrics train the neuromuscular system to efficiently utilize the stretch-shortening cycle for explosive power development."},{"id": 8909,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Concussion in sport is best described as:","options": [{"key": "A","text": "A structural brain injury visible on standard CT/MRI"},{"key": "B","text": "Only relevant if loss of consciousness occurs"},{"key": "C","text": "Always requiring surgical intervention"},{"key": "D","text": "A traumatic brain injury induced by biomechanical forces, causing temporary neurological dysfunction"}],"correct": "D","explanation": "Concussion is a functional rather than structural brain injury, typically not showing abnormality on standard imaging, caused by biomechanical forces (direct or transmitted)."},{"id": 8910,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Graduated Return to Sport (GRTS) protocol following concussion typically involves:","options": [{"key": "A","text": "No specific protocol needed, return whenever athlete feels ready"},{"key": "B","text": "Return to play on the same day regardless of symptoms"},{"key": "C","text": "Stepwise progression through symptom-limited activity stages before full contact return"},{"key": "D","text": "Immediate return once symptom-free for a few hours"}],"correct": "C","explanation": "Structured graduated return protocols progress through stages (rest, light aerobic, sport-specific, non-contact training, full contact) with symptom monitoring at each step."},{"id": 8911,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Second Impact Syndrome refers to:","options": [{"key": "A","text": "A type of chronic overuse injury"},{"key": "B","text": "Delayed onset muscle soreness after repeated training"},{"key": "C","text": "A rare but catastrophic brain swelling event if a second concussion occurs before the first has resolved"},{"key": "D","text": "A minor re-injury with no significant risk"}],"correct": "C","explanation": "Second impact syndrome is a rare, potentially fatal condition where a second head injury before full recovery from a first concussion causes severe brain swelling."},{"id": 8912,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Delayed Onset Muscle Soreness (DOMS) typically peaks at approximately:","options": [{"key": "A","text": "24-72 hours after unaccustomed/eccentric exercise"},{"key": "B","text": "1 month after exercise"},{"key": "C","text": "1 week after exercise"},{"key": "D","text": "Immediately after exercise"}],"correct": "A","explanation": "DOMS classically peaks 24-72 hours post-exercise, particularly following unaccustomed or eccentric-heavy activity."},{"id": 8913,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Female athlete triad refers to the interrelated conditions of:","options": [{"key": "A","text": "Only stress fractures"},{"key": "B","text": "Low energy availability, menstrual dysfunction, and low bone mineral density"},{"key": "C","text": "Only amenorrhea without other components"},{"key": "D","text": "Only eating disorders in isolation"}],"correct": "B","explanation": "The female athlete triad describes the interrelationship between energy availability, menstrual function, and bone health in female athletes."},{"id": 8914,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Relative Energy Deficiency in Sport (RED-S) is a broader concept than the female athlete triad because it:","options": [{"key": "A","text": "Recognizes impact on multiple body systems and applies to both male and female athletes"},{"key": "B","text": "Only applies to elite female athletes"},{"key": "C","text": "Only concerns bone health, ignoring other systems"},{"key": "D","text": "Is identical in scope to the female athlete triad"}],"correct": "A","explanation": "RED-S expands on the triad concept, recognizing low energy availability's impact on multiple physiological systems in athletes of any gender."},{"id": 8915,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Sports-specific rehabilitation progression typically follows which general sequence?","options": [{"key": "A","text": "Immediate full competitive return without progression"},{"key": "B","text": "Only passive treatment throughout rehabilitation"},{"key": "C","text": "Basic strength/ROM restoration, progressing to sport-specific movement patterns, then full competitive return"},{"key": "D","text": "Random exercise selection without structured progression"}],"correct": "C","explanation": "Structured rehabilitation progresses from foundational impairment-based work toward increasingly sport-specific and complex functional demands before full return."},{"id": 8916,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which type of taping technique is commonly used to provide dynamic support while allowing functional movement in sports injury management?","options": [{"key": "A","text": "Complete casting"},{"key": "B","text": "Kinesiology taping"},{"key": "C","text": "No taping techniques are used in sports"},{"key": "D","text": "Only rigid strapping in all cases"}],"correct": "B","explanation": "Kinesiology taping is used to provide proprioceptive feedback and dynamic support while permitting continued functional movement, though evidence for mechanism is debated."},{"id": 8917,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pre-participation screening in athletes primarily aims to:","options": [{"key": "A","text": "Identify risk factors for injury or serious medical conditions before sports participation"},{"key": "B","text": "Guarantee complete injury prevention"},{"key": "C","text": "Only assess cardiovascular fitness"},{"key": "D","text": "Replace the need for team physicians"}],"correct": "A","explanation": "Pre-participation screening helps identify modifiable risk factors and underlying conditions (musculoskeletal or medical) that could affect safe sports participation."},{"id": 8918,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Cross-training is often incorporated into sports rehabilitation to:","options": [{"key": "A","text": "Maintain cardiovascular fitness while reducing load on the injured structure"},{"key": "B","text": "Only for elite athletes, not applicable to recreational athletes"},{"key": "C","text": "Increase risk of re-injury intentionally"},{"key": "D","text": "Replace sport-specific training entirely at all stages"}],"correct": "A","explanation": "Cross-training (e.g., swimming, cycling) allows maintenance of fitness during recovery while minimizing stress on the healing injured tissue."},{"id": 8919,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Sports hernia (athletic pubalgia) rehabilitation typically emphasizes:","options": [{"key": "A","text": "Immediate surgery in all cases regardless of severity"},{"key": "B","text": "Core and hip strengthening addressing the abdominal-adductor balance"},{"key": "C","text": "Isolated adductor stretching only, no strengthening"},{"key": "D","text": "Complete rest without any exercise intervention"}],"correct": "B","explanation": "Rehabilitation addresses the interrelated core/hip musculature balance implicated in athletic pubalgia, often successfully managing milder presentations conservatively."},{"id": 8920,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which principle underlies the use of progressive functional testing (e.g., hop tests) before return to sport after lower limb injury?","options": [{"key": "A","text": "Replacing strength testing entirely"},{"key": "B","text": "Only relevant for upper limb injuries"},{"key": "C","text": "Assessing functional symmetry and readiness to tolerate sport-specific loading demands"},{"key": "D","text": "Testing is purely for research purposes with no clinical application"}],"correct": "C","explanation": "Functional hop/agility tests assess whether the injured limb can tolerate the dynamic loading demands of sport, informing safe return-to-play decisions alongside strength testing."},{"id": 8921,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Ideal postural alignment, viewed laterally, has the plumb line passing through all EXCEPT:","options": [{"key": "A","text": "External auditory meatus"},{"key": "B","text": "Slightly anterior to lateral malleolus"},{"key": "C","text": "Anterior to the shoulder joint (should pass through/near it)"},{"key": "D","text": "Greater trochanter"}],"correct": "C","explanation": "The plumb line should pass through or very near the shoulder joint, not distinctly anterior to it, in ideal alignment."},{"id": 8922,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Kyphotic-lordotic' posture is characterized by:","options": [{"key": "A","text": "Increased thoracic kyphosis, increased lumbar lordosis, forward head, and protracted scapulae"},{"key": "B","text": "Lateral spinal asymmetry"},{"key": "C","text": "Normal spinal curves with posterior pelvic tilt"},{"key": "D","text": "Decreased thoracic kyphosis with flat lumbar spine"}],"correct": "A","explanation": "This common postural pattern combines increased thoracic kyphosis with compensatory increased lumbar lordosis, forward head, and rounded/protracted shoulders."},{"id": 8923,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Flat back' posture is characterized by:","options": [{"key": "A","text": "Increased thoracic kyphosis only"},{"key": "B","text": "Lateral curvature of the spine"},{"key": "C","text": "Decreased lumbar lordosis with posterior pelvic tilt and often reduced thoracic kyphosis"},{"key": "D","text": "Increased lumbar lordosis with anterior pelvic tilt"}],"correct": "C","explanation": "Flat back posture shows reduced lumbar curve with posterior pelvic tilt, sometimes accompanied by reduced thoracic kyphosis."},{"id": 8924,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'Sway back' posture is characterized by:","options": [{"key": "A","text": "Posterior pelvic tilt with hip joint shifted anterior to the gravity line and increased thoracic kyphosis"},{"key": "B","text": "Symmetric normal alignment"},{"key": "C","text": "Lateral trunk shift only"},{"key": "D","text": "Anterior pelvic tilt with increased lumbar lordosis"}],"correct": "A","explanation": "Sway back involves posterior pelvic tilt, hip extended and shifted forward relative to the line of gravity, with a relatively flat lumbar spine but increased upper thoracic kyphosis."},{"id": 8925,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Forward head posture is commonly associated with which muscle imbalance pattern (upper crossed syndrome)?","options": [{"key": "A","text": "No specific muscle imbalance pattern"},{"key": "B","text": "Tight deep cervical flexors with weak upper trapezius"},{"key": "C","text": "Tight hip flexors with weak abdominals only"},{"key": "D","text": "Tight upper trapezius/suboccipitals/pectorals with weak deep cervical flexors/lower trapezius"}],"correct": "D","explanation": "Upper crossed syndrome describes the characteristic tightness of upper trapezius, levator scapulae, suboccipitals, and pectorals, paired with weakness of deep cervical flexors and scapular retractors/lower trapezius."},{"id": 8926,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "'Lower crossed syndrome' describes a postural imbalance pattern involving:","options": [{"key": "A","text": "Tight abdominals with weak hip flexors"},{"key": "B","text": "Tight hamstrings with weak quadriceps only"},{"key": "C","text": "No relationship between muscle groups"},{"key": "D","text": "Tight hip flexors/erector spinae with weak abdominals/gluteals"}],"correct": "D","explanation": "Lower crossed syndrome involves tight hip flexors and lumbar erector spinae combined with weak abdominal and gluteal muscles, often producing increased anterior pelvic tilt/lordosis."},{"id": 8927,"subject": "Musculoskeletal Physiotherapy","topic": "Spine (Cervical/Thoracic/Lumbar)","difficulty": "Medium","question": "Increased anterior pelvic tilt is commonly associated with which postural change in the lumbar spine?","options": [{"key": "A","text": "Increased lumbar lordosis"},{"key": "B","text": "Lateral spinal curvature"},{"key": "C","text": "Decreased lumbar lordosis"},{"key": "D","text": "No effect on lumbar curve"}],"correct": "A","explanation": "Anterior pelvic tilt is biomechanically linked to increased lumbar lordosis due to the sacral base angle change."},{"id": 8928,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Scoliosis is defined as a Cobb angle greater than:","options": [{"key": "A","text": "30 degrees minimum for any diagnosis"},{"key": "B","text": "10 degrees"},{"key": "C","text": "1 degree"},{"key": "D","text": "50 degrees minimum for diagnosis"}],"correct": "B","explanation": "A Cobb angle greater than 10° on standing radiograph is the standard threshold for scoliosis diagnosis, along with rotational component."},{"id": 8929,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Postural (functional) scoliosis differs from structural scoliosis in that it:","options": [{"key": "A","text": "Always requires surgical correction"},{"key": "B","text": "Shows identical rigid vertebral rotation as structural scoliosis"},{"key": "C","text": "Corrects with forward bending/positional changes and lacks fixed vertebral rotation"},{"key": "D","text": "Never corrects with any positional change"}],"correct": "C","explanation": "Functional/postural scoliosis is flexible and resolves with correction of the underlying cause (e.g., leg length discrepancy), unlike structural scoliosis with fixed vertebral rotation."},{"id": 8930,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Genu recurvatum (knee hyperextension) as a postural finding is often associated with:","options": [{"key": "A","text": "Normal knee alignment variant with no clinical relevance"},{"key": "B","text": "Excessive hamstring tightness only"},{"key": "C","text": "Weak quadriceps/posterior capsule laxity leading to compensatory locking"},{"key": "D","text": "Ankle equinus contracture exclusively"}],"correct": "C","explanation": "Genu recurvatum often develops as compensatory hyperextension where posterior structures are lax and/or quadriceps are weak, common in certain neurological conditions."},{"id": 8931,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Pes planus (flat feet) can contribute to postural changes proximally, including:","options": [{"key": "A","text": "Increased tibial internal rotation and potential knee valgus stress"},{"key": "B","text": "Isolated forefoot changes with no kinetic chain effect"},{"key": "C","text": "Decreased tibial rotation with no proximal effect"},{"key": "D","text": "Improved shock absorption with no negative consequence"}],"correct": "A","explanation": "Excessive pronation (flat feet) can transmit altered rotational forces up the kinetic chain, potentially contributing to knee valgus stress and related issues."},{"id": 8932,"subject": "Musculoskeletal Physiotherapy","topic": "Assessment & Special Tests","difficulty": "Medium","question": "Postural assessment should ideally be conducted:","options": [{"key": "A","text": "With the patient fully clothed in loose garments"},{"key": "B","text": "Only in a seated position"},{"key": "C","text": "From multiple views (anterior, posterior, lateral) with the patient in minimal, form-fitting clothing"},{"key": "D","text": "From only one view for efficiency"}],"correct": "C","explanation": "Comprehensive postural assessment requires visualization from multiple planes, necessitating appropriate clothing to observe bony landmarks and alignment accurately."},{"id": 8933,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Which intervention approach is generally most effective for correcting postural dysfunction related to muscle imbalance?","options": [{"key": "A","text": "Combination of stretching tight muscles and strengthening weak/lengthened muscles, along with postural education"},{"key": "B","text": "Only strengthening without addressing flexibility"},{"key": "C","text": "Only stretching without strengthening"},{"key": "D","text": "Passive bracing alone without active exercise"}],"correct": "A","explanation": "Addressing both sides of the muscle imbalance (lengthening tight structures, strengthening weak ones) combined with postural awareness training is the evidence-based approach."},{"id": 8934,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Prolonged sitting with poor ergonomic support is commonly associated with development of:","options": [{"key": "A","text": "Increased thoracic kyphosis, forward head posture, and posterior pelvic tilt"},{"key": "B","text": "Increased lumbar lordosis exclusively with no thoracic change"},{"key": "C","text": "Improved postural alignment over time"},{"key": "D","text": "No musculoskeletal consequences"}],"correct": "A","explanation": "Prolonged poor sitting posture contributes to sustained flexed/rounded postures, forward head positioning, and altered pelvic alignment over time."},{"id": 8935,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Leg length discrepancy can contribute to compensatory postural changes including:","options": [{"key": "A","text": "Always causing permanent structural scoliosis"},{"key": "B","text": "Only local ankle changes"},{"key": "C","text": "Functional scoliosis and pelvic obliquity"},{"key": "D","text": "No effect on spinal alignment"}],"correct": "C","explanation": "Significant leg length discrepancy can cause pelvic obliquity and secondary functional (compensatory) spinal curvature, which is typically reversible if the discrepancy is corrected."},{"id": 8936,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Medium","question": "Maitland's mobilization grading system uses how many grades (I-IV) based on amplitude and range?","options": [{"key": "A","text": "Ten grades"},{"key": "B","text": "Four grades (I-IV), plus Grade V for manipulation in some descriptions"},{"key": "C","text": "Grades are not standardized in Maitland's approach"},{"key": "D","text": "Two grades only"}],"correct": "B","explanation": "Maitland's system uses Grades I-IV based on amplitude of oscillation relative to available range, with manipulation sometimes described as Grade V."},{"id": 8937,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Medium","question": "Maitland Grade I mobilization is characterized by:","options": [{"key": "A","text": "Large amplitude movement into resistance"},{"key": "B","text": "Small amplitude movement at the beginning of available range"},{"key": "C","text": "Small amplitude movement at end of range"},{"key": "D","text": "Large amplitude movement throughout full range"}],"correct": "B","explanation": "Grade I: small amplitude oscillation performed at the very beginning of the range, typically used for pain management."},{"id": 8938,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Hard","question": "Maitland Grade IV mobilization is characterized by:","options": [{"key": "A","text": "Large amplitude movement avoiding any resistance"},{"key": "B","text": "Large amplitude movement at beginning of range"},{"key": "C","text": "Small amplitude movement performed at the very end of available range, into resistance"},{"key": "D","text": "Small amplitude movement at beginning of range"}],"correct": "C","explanation": "Grade IV: small amplitude oscillation at the end of range, into tissue resistance, typically used to address stiffness."},{"id": 8939,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Easy","question": "Kaltenborn's concept of joint mobilization emphasizes which key principle regarding treatment plane and direction of glide?","options": [{"key": "A","text": "Movement always parallel to the long bone axis regardless of joint surface"},{"key": "B","text": "Only oscillatory movements regardless of joint shape"},{"key": "C","text": "Convex-concave rule guiding the direction of glide mobilization relative to joint surface shape"},{"key": "D","text": "No consideration of joint surface shape is needed"}],"correct": "C","explanation": "Kaltenborn's approach applies the convex-concave rule to determine appropriate glide direction for mobilization based on joint surface congruency."},{"id": 8940,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Medium","question": "Kaltenborn's grading system for mobilization includes which distinct categories?","options": [{"key": "A","text": "Only two grades"},{"key": "B","text": "No grading system is used in Kaltenborn's approach"},{"key": "C","text": "Five distinct grades similar to Maitland"},{"key": "D","text": "Grade I (loosen), Grade II (tighten/take up slack), Grade III (stretch)"}],"correct": "D","explanation": "Kaltenborn describes three grades: I (traction to reduce compressive forces without separating joint surfaces), II (taking up slack), and III (stretching the capsule/ligaments)."},{"id": 8941,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Medium","question": "Mulligan's concept of Mobilization With Movement (MWM) is characterized by:","options": [{"key": "A","text": "Passive mobilization performed with the patient completely relaxed and no active movement"},{"key": "B","text": "Combining a sustained accessory glide with an active movement, performed pain-free"},{"key": "C","text": "Only manipulation techniques with high velocity thrust"},{"key": "D","text": "Static stretching without any joint mobilization component"}],"correct": "B","explanation": "MWM combines a therapist-applied sustained glide with patient-performed active movement, with the fundamental rule being that the technique should be pain-free."},{"id": 8942,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "A key principle of Mulligan's MWM technique is that the intervention should be:","options": [{"key": "A","text": "Immediately pain-free during application, with no latent pain response"},{"key": "B","text": "Painful during application to be effective"},{"key": "C","text": "Only used in acute injury phases"},{"key": "D","text": "Applied regardless of symptom response"}],"correct": "A","explanation": "The 'no pain' principle is fundamental to Mulligan's approach; if pain occurs during MWM application, the technique is modified or abandoned."},{"id": 8943,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'SNAGs' (Sustained Natural Apophyseal Glides) are a Mulligan technique typically applied to which region?","options": [{"key": "A","text": "Only the wrist"},{"key": "B","text": "Only the ankle"},{"key": "C","text": "Spine (cervical, thoracic, lumbar)"},{"key": "D","text": "Only peripheral joints"}],"correct": "C","explanation": "SNAGs are spinal mobilization-with-movement techniques applying a sustained glide to a spinal segment during active patient movement."},{"id": 8944,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "'NAGs' (Natural Apophyseal Glides) in Mulligan's approach differ from SNAGs in that they are:","options": [{"key": "A","text": "Only used on peripheral joints"},{"key": "B","text": "Always combined with resisted active movement"},{"key": "C","text": "Identical to SNAGs in application"},{"key": "D","text": "Passive oscillatory glides applied without a sustained hold or combined active movement requirement in the same way"}],"correct": "D","explanation": "NAGs are gentle oscillatory passive accessory glides applied to spinal facet joints, distinct from the sustained/active-movement combination in SNAGs."},{"id": 8945,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "McKenzie's Mechanical Diagnosis and Therapy (MDT) approach classifies spinal syndromes into which main categories?","options": [{"key": "A","text": "Structural and non-structural categories only"},{"key": "B","text": "Postural, dysfunction, and derangement syndromes"},{"key": "C","text": "Only inflammatory and degenerative categories"},{"key": "D","text": "Acute and chronic categories only"}],"correct": "B","explanation": "McKenzie's classification system identifies postural syndrome, dysfunction syndrome, and derangement syndrome as primary mechanical categories guiding treatment approach."},{"id": 8946,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "In McKenzie's derangement syndrome, treatment direction is primarily guided by:","options": [{"key": "A","text": "Random selection of exercise direction"},{"key": "B","text": "Imaging findings alone"},{"key": "C","text": "A fixed protocol regardless of patient response"},{"key": "D","text": "The patient's directional preference determined through repeated movement testing (centralization response)"}],"correct": "D","explanation": "Treatment direction in derangement syndrome is individualized based on which repeated movement direction produces centralization of symptoms."},{"id": 8947,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "High-velocity, low-amplitude (HVLA) thrust manipulation techniques are characterized by:","options": [{"key": "A","text": "Gentle oscillations well within available range"},{"key": "B","text": "Patient-performed active movement without therapist force"},{"key": "C","text": "Slow, large-amplitude sustained stretching"},{"key": "D","text": "A quick, small-amplitude thrust performed at the end of available joint range"}],"correct": "D","explanation": "HVLA manipulation involves a rapid, small-amplitude thrust at end-range, distinct from the oscillatory mobilization techniques of Maitland or the sustained approach of Kaltenborn's stretch grade."},{"id": 8948,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Contraindications to spinal manipulation/high-velocity techniques include which of the following?","options": [{"key": "A","text": "Simple mechanical joint stiffness"},{"key": "B","text": "Suspected fracture, spinal cord compression, or vertebrobasilar insufficiency"},{"key": "C","text": "Chronic postural dysfunction without red flags"},{"key": "D","text": "Mild muscle tightness"}],"correct": "B","explanation": "Serious pathology (fracture, cord compression, vascular compromise) represents absolute/relative contraindications to high-velocity manipulation techniques, requiring careful screening."},{"id": 8949,"subject": "Musculoskeletal Physiotherapy","topic": "Manual Therapy & Mobilization","difficulty": "Easy","question": "Soft tissue mobilization techniques (e.g., myofascial release, deep transverse friction massage) are generally used to address:","options": [{"key": "A","text": "Muscle/fascial tightness, adhesions, and scar tissue mobility"},{"key": "B","text": "Only bone density issues"},{"key": "C","text": "Ligament tensile strength directly"},{"key": "D","text": "Nerve conduction velocity directly"}],"correct": "A","explanation": "Soft tissue techniques target muscular/fascial restrictions and adhesions, complementing joint-focused manual therapy approaches."},{"id": 8950,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Deep transverse friction massage (Cyriax technique) is specifically applied to:","options": [{"key": "A","text": "Bone directly"},{"key": "B","text": "Nerve tissue exclusively"},{"key": "C","text": "Only skin surface without deeper tissue engagement"},{"key": "D","text": "Tendons and ligaments, applied transverse to fiber direction to promote mobility and reduce adhesion"}],"correct": "D","explanation": "Cyriax's deep transverse friction technique is applied specifically across the fiber direction of tendons/ligaments to mobilize the tissue and address adhesions/promote healing response."},{"id": 8951,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The overload principle in exercise therapy states that:","options": [{"key": "A","text": "Exercise intensity should never increase over time"},{"key": "B","text": "A tissue/system must be stressed beyond its accustomed level to produce adaptation"},{"key": "C","text": "Only maximal loads produce any training effect"},{"key": "D","text": "Rest alone produces strength gains"}],"correct": "B","explanation": "Overload principle: progressive stress beyond current capacity is necessary to stimulate physiological adaptation (strength, endurance, etc.)."},{"id": 8952,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "The specificity principle (SAID principle - Specific Adaptation to Imposed Demand) states that:","options": [{"key": "A","text": "Only aerobic exercise follows this principle"},{"key": "B","text": "Training adaptations are specific to the type of stress/demand imposed"},{"key": "C","text": "All exercise types produce identical training effects"},{"key": "D","text": "Specificity is irrelevant to rehabilitation programming"}],"correct": "B","explanation": "SAID principle: the body adapts specifically to the particular demands placed on it, guiding functional/sport-specific exercise prescription."},{"id": 8953,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "The principle of reversibility in exercise therapy refers to:","options": [{"key": "A","text": "Loss of training adaptations/gains when training stimulus is reduced or stopped"},{"key": "B","text": "Irrelevance of detraining in rehabilitation"},{"key": "C","text": "Exercise effects being immediately reversible within minutes"},{"key": "D","text": "Permanent retention of all strength gains regardless of continued training"}],"correct": "A","explanation": "Reversibility (detraining) describes the loss of physiological adaptations when training stimulus decreases or ceases, relevant to maintaining rehabilitation gains."},{"id": 8954,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Isometric exercise involves:","options": [{"key": "A","text": "Muscle contraction without a change in muscle length or joint movement"},{"key": "B","text": "Muscle contraction with shortening and joint movement"},{"key": "C","text": "Passive movement without muscle contraction"},{"key": "D","text": "Muscle contraction with lengthening under load"}],"correct": "A","explanation": "Isometric contraction generates tension without observable change in muscle length or joint angle."},{"id": 8955,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Isotonic (dynamic) exercise involves muscle contraction with:","options": [{"key": "A","text": "Constant external load through a range of joint movement (concentric/eccentric)"},{"key": "B","text": "No joint movement"},{"key": "C","text": "Variable resistance matched to strength curve throughout range"},{"key": "D","text": "Only eccentric contraction exclusively"}],"correct": "A","explanation": "Isotonic exercise involves movement through a range against a relatively constant external load, encompassing both concentric and eccentric phases."},{"id": 8956,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Isokinetic exercise is characterized by:","options": [{"key": "A","text": "Variable, uncontrolled speed of movement"},{"key": "B","text": "Constant external load regardless of speed"},{"key": "C","text": "No movement at all"},{"key": "D","text": "Constant angular velocity with accommodating resistance throughout the range of motion"}],"correct": "D","explanation": "Isokinetic exercise (typically using specialized dynamometers) maintains constant velocity while resistance accommodates to the force applied throughout ROM."},{"id": 8957,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Proprioceptive Neuromuscular Facilitation (PNF) techniques primarily utilize which movement pattern characteristic?","options": [{"key": "A","text": "Diagonal, spiral movement patterns combined with specific facilitation techniques"},{"key": "B","text": "Only isometric holds without any movement"},{"key": "C","text": "Only single-plane movements"},{"key": "D","text": "Random unstructured movement patterns"}],"correct": "A","explanation": "PNF uses diagonal/spiral patterns that closely mimic functional movement, combined with techniques like contract-relax and rhythmic stabilization to facilitate neuromuscular response."},{"id": 8958,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "'Contract-relax' PNF technique is primarily used to:","options": [{"key": "A","text": "Assess joint stability only"},{"key": "B","text": "Replace strength training entirely"},{"key": "C","text": "Increase muscle power explosively"},{"key": "D","text": "Improve flexibility/ROM by utilizing post-isometric relaxation"}],"correct": "D","explanation": "Contract-relax technique uses an isometric contraction of the target muscle followed by relaxation to facilitate increased stretch/ROM."},{"id": 8959,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Progressive Resistance Exercise (PRE) programs typically manipulate which variables to progress training?","options": [{"key": "A","text": "Load (resistance), volume (sets/reps), and frequency"},{"key": "B","text": "Only the type of equipment used"},{"key": "C","text": "Only exercise duration, never load"},{"key": "D","text": "Random variation without systematic progression"}],"correct": "A","explanation": "PRE programs systematically progress by adjusting resistance, volume, and/or frequency based on the patient's adaptation and rehabilitation phase."},{"id": 8960,"subject": "Musculoskeletal Physiotherapy","topic": "Knee","difficulty": "Medium","question": "Closed Kinetic Chain (CKC) exercises are generally preferred in early ligament rehabilitation (e.g., post-ACL) because they:","options": [{"key": "A","text": "Increase shear force on the joint significantly"},{"key": "B","text": "Promote joint compression and co-contraction, reducing shear forces on healing structures"},{"key": "C","text": "Are contraindicated in all early rehabilitation phases"},{"key": "D","text": "Isolate single muscle groups only"}],"correct": "B","explanation": "CKC exercises' compressive, co-contraction nature is generally protective for healing ligamentous structures compared to some OKC exercises."},{"id": 8961,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Aerobic conditioning is an important component of comprehensive MSK rehabilitation programs primarily to:","options": [{"key": "A","text": "Replace strength training entirely"},{"key": "B","text": "Maintain cardiovascular fitness and support overall recovery/function during musculoskeletal rehabilitation"},{"key": "C","text": "Have no role in orthopedic rehabilitation"},{"key": "D","text": "Only benefit weight management, unrelated to MSK recovery"}],"correct": "B","explanation": "Maintaining aerobic fitness supports overall functional recovery and general health during the rehabilitation process, complementing strength/ROM work."},{"id": 8962,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Which exercise progression principle suggests moving from simple to complex, and stable to unstable surfaces, in functional rehabilitation?","options": [{"key": "A","text": "Specificity principle in isolation"},{"key": "B","text": "Progressive functional/neuromuscular re-education principle"},{"key": "C","text": "Reversibility principle"},{"key": "D","text": "Overload principle applied only to resistance training"}],"correct": "B","explanation": "Functional rehabilitation progresses systematically from basic stable-surface exercises to more complex, dynamic, and unstable-surface challenges as the patient improves."},{"id": 8963,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Hard","question": "Pain-contingent exercise progression (only progressing when pain-free) differs from time-contingent progression in that the latter:","options": [{"key": "A","text": "Never considers any timeline for progression"},{"key": "B","text": "Only applies to chronic pain conditions, never acute injuries"},{"key": "C","text": "Progresses exercise based on a predetermined schedule regardless of current pain level (within safe limits)"},{"key": "D","text": "Is identical in approach to pain-contingent progression"}],"correct": "C","explanation": "Time-contingent progression follows a set schedule for advancing exercise difficulty, useful in some chronic pain rehabilitation approaches to avoid pain-avoidance reinforcement, contrasted with strictly symptom-guided progression."},{"id": 8964,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Easy","question": "Which of the following best describes the role of patient education within exercise therapy programs for musculoskeletal conditions?","options": [{"key": "A","text": "Enhances self-management, adherence, and understanding of the condition, supporting better outcomes"},{"key": "B","text": "Has no measurable impact on treatment outcomes"},{"key": "C","text": "Only relevant for post-surgical patients"},{"key": "D","text": "Should be avoided to prevent patient anxiety"}],"correct": "A","explanation": "Patient education regarding their condition and exercise rationale improves engagement, adherence, and overall rehabilitation outcomes across MSK conditions."},{"id": 8965,"subject": "Musculoskeletal Physiotherapy","topic": "General Musculoskeletal","difficulty": "Medium","question": "Home exercise program (HEP) compliance is generally improved by which strategy?","options": [{"key": "A","text": "Simplifying the program, providing clear instructions, and regular follow-up/monitoring"},{"key": "B","text": "Providing no follow-up after initial prescription"},{"key": "C","text": "Prescribing the maximum number of exercises possible regardless of complexity"},{"key": "D","text": "Avoiding any explanation of exercise purpose"}],"correct": "A","explanation": "Simple, clearly explained programs with appropriate follow-up support better patient adherence to home exercise prescriptions."}];
